window.QURAN={"bismillah":"بِسْمِ [h:1[ٱ]للَّهِ [h:2[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ [h:3[ٱ][l[ل]رَّح[p[ِي]مِ","surahs":[{"n":1,"ar":"ٱلْفَاتِحَةِ","en":"Al-Faatiha","uz":"Фотиҳа","type":"Макка","ayahs":[["بِسْمِ [h:1[ٱ]للَّهِ [h:2[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ [h:3[ٱ][l[ل]رَّح[p[ِي]مِ","Меҳрибон ва раҳмли Аллоҳнинг номи билан бошлайман.",1,1],["ٱلْحَمْدُ لِلَّهِ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Барча мақтов, шукрлар оламларнинг тарбиячиси Аллоҳга бўлсин.",1,1],["ٱ[l[ل]رَّحْمَ[n[ـٰ]نِ [h:3[ٱ][l[ل]رَّح[p[ِي]مِ","У Роҳман ва Раҳийм...",1,1],["مَ[n[ـٰ]لِكِ يَوْمِ [h:5[ٱ][l[ل]دّ[p[ِي]نِ","У қиёмат кунининг подшоҳи, эгаси.",1,1],["إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَع[p[ِي]نُ","Фақат сенгагина ибодат қиламиз ва фақат сендангина ёрдам сўраймиз.",1,1],["ٱهْدِنَا [h:6[ٱ][l[ل]صِّر[n[َٲ]طَ [h:7[ٱ]لْمُسْتَق[p[ِي]مَ","Бизни тўғри йўлга бошлагин.",1,1],["صِر[n[َٲ]طَ [h:8[ٱ]لَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ [h:9[ٱ]لْمَغْضُوبِ عَلَيْهِمْ وَلَا [h:10[ٱ][l[ل]ضّ[m[َا]ٓلّ[p[ِي]نَ","Ўзинг неъмат берганларнинг йўлига, ғазабга дучор бўлганларнинг йўлига эмас, адашганларникига ҳам эмас.",1,1]]},{"n":2,"ar":"البَقَرَةِ","en":"Al-Baqara","uz":"Бақара","type":"Мадина","ayahs":[["ا[m[لٓ][m[مٓ]","Алиф Лом Мим.",2,1],["ذ[n[َٲ]لِكَ [h:11[ٱ]لْكِتَ[n[ـٰ]بُ لَا رَيْبَ‌ۛ فِيهِ‌ۛ هُ[u:12[دًى ل]ِّلْمُتَّق[p[ِي]نَ","Бу китобда шак-шубҳа йўқ, у тақводорларга ҳидоятдир.",2,1],["ٱلَّذِينَ يُؤْمِنُونَ بِ[h:13[ٱ]لْغَيْبِ وَيُقِيمُونَ [h:14[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَمِ[g[مّ]َا رَزَ[q:15[قْ]نَ[n[ـٰ]هُمْ يُ[f:16[نف]ِق[p[ُو]نَ","Улар Ғайбга иймон келтирурлар, намоз ўқирлар ва Биз уларга берган ризқдан нафақа қилурлар.;",2,1],["وَ[h:9999[ٱ]لَّذِينَ يُؤْمِنُونَ بِم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْكَ وَم[o[َآ] أُ[f:17[نز]ِلَ مِ[f:18[ن ق]َ[q:19[بْ]لِكَ وَبِ[h:20[ٱ]لْأَخِرَةِ هُمْ يُوقِن[p[ُو]نَ","Ва улар сенга ва сендан олдин нозил қилинган нарсага иймон келтирурлар ва охиратга аниқ ишонурлар.",2,1],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ عَلَىٰ هُ[a:21[دًى م]ّ[u:22[ِن ر]َّبِّهِمْ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Ана ўшалар Роббиларидан бўлган ҳидоятидадирлар ва ана ўшалар, ўшаларгина нажот топгувчилардир.",2,1],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] سَو[o[َا]ٓءٌ عَلَيْهِمْ ءَأَ[f:25[نذ]َرْتَهُمْ أَمْ لَمْ تُ[f:26[نذ]ِرْهُمْ لَا يُؤْمِن[p[ُو]نَ","Албатта, куфр келтирганларга қўрқитасанми-қўрқитмайсанми-барибир, иймон келтирмайдилар.",3,1],["خَتَمَ [h:27[ٱ]للَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ‌ۖ وَعَلَ[o[ىٰٓ] أَ[q:28[بْ]صَ[n[ـٰ]رِهِمْ غِشَ[n[ـٰ]وَ[a:29[ةٌ‌ۖ و]َلَهُمْ عَذَابٌ عَظ[p[ِي]مٌ","Аллоҳ уларнинг қалблари ва қулоқларини муҳрлаб қўйган ва кўзларида парда бор. Ва уларга улкан азоб бордир.",3,1],["وَمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ م[a:31[َن ي]َقُولُ ءَامَ[g[نّ]َا بِ[h:32[ٱ]للَّهِ وَبِ[h:33[ٱ]لْيَوْمِ [h:34[ٱ]لْأَخِرِ وَمَا ه[c:35[ُم ب]ِمُؤْمِن[p[ِي]نَ","Ва Одамлардан, Аллоҳга ва охират кунига иймон келтирдик, дейдиганлари бор. Ҳолбуки, улар мўмин эмаслар.",3,1],["يُخَ[n[ـٰ]دِعُونَ [h:36[ٱ]للَّهَ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَمَا يَخْدَعُونَ إِلّ[o[َآ] أَ[f:38[نف]ُسَهُمْ وَمَا يَشْعُر[p[ُو]نَ","Улар Аллоҳни ва иймон келтирганларни алдамоқчи бўладилар. Ва ҳолбуки, сезмасдан ўзларини алдайдилар.",3,1],["فِى قُلُوبِه[w:39[ِم م]َّرَ[f:40[ضٌ ف]َزَادَهُمُ [h:41[ٱ]للَّهُ مَرَ[a:42[ضًا‌ۖ و]َلَهُمْ عَذَابٌ أَلِي[i:43[مُۢ ب]ِمَا كَانُو[s[اْ] يَكْذِب[p[ُو]نَ","Уларнинг қалбларида касал бор. Аллоҳ касалларини зиёда қилди. Ва уларга ёлғон гапирганлари учун аламли азоб бор.",3,1],["وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َمَا نَحْنُ مُصْلِح[p[ُو]نَ","Ва агар уларга, ер юзида фасод қилманг, дейилса, биз фақат ислоҳ қилувчилармиз, дейдилар.",3,1],["أَل[o[َآ] إِ[g[نّ]َهُمْ هُمُ [h:45[ٱ]لْمُفْسِدُونَ وَلَ[n[ـٰ]ك[u:46[ِن ل]َّا يَشْعُر[p[ُو]نَ","Огоҳ бўлинг, улар, фақат улар фасодчилардир, лекин сезмайдилар.",3,1],["وَإِذَا قِيلَ لَهُمْ ءَامِنُو[s[اْ] كَم[o[َآ] ءَامَنَ [h:47[ٱ][l[ل][g[نّ]َاسُ قَال[o[ُوٓ][s[اْ] أَنُؤْمِنُ كَم[o[َآ] ءَامَنَ [h:48[ٱ][l[ل]سُّفَه[o[َا]ٓءُ‌ۗ أَل[o[َآ] إِ[g[نّ]َهُمْ هُمُ [h:49[ٱ][l[ل]سُّفَه[o[َا]ٓءُ وَلَ[n[ـٰ]ك[u:46[ِن ل]َّا يَعْلَم[p[ُو]نَ","Ва агар уларга, одамлар иймон келтирганидек, иймон келтиринглар, дейилса, \"Эсипастлар иймон келтирганидек иймон келтирамизми?\" дейишади. Огоҳ бўлинг, улар, фақат улар эсипастлардир ва лекин ўзлари билмайдилар.",3,1],["وَإِذَا لَقُو[s[اْ] [h:50[ٱ]لَّذِينَ ءَامَنُو[s[اْ] قَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا وَإِذَا خَلَوْ[s[اْ] إِلَىٰ شَيَ[n[ـٰ]طِينِهِمْ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا مَعَكُمْ إِ[g[نّ]َمَا نَحْنُ مُسْتَهْزِء[p[ُو]نَ","Улар иймон келтирганларни учратсалар, иймон келтирдик, дейдилар, шайтонлари билан ҳоли қолганда эса, биз сизлар биланмиз, фақат истеҳзо қиляпмиз холос, дейдилар.",3,1],["ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَ[n[ـٰ]نِهِمْ يَعْمَه[p[ُو]نَ","Аллоҳ уларни истеҳзо қилади ва туғёнларида довдирашларига қўйиб беради.",3,1],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ [h:52[ٱ]شْتَرَوُ[s[اْ] [h:53[ٱ][l[ل]ضَّلَ[n[ـٰ]لَةَ بِ[h:54[ٱ]لْهُدَىٰ فَمَا رَبِحَت تِّجَ[n[ـٰ]رَتُهُمْ وَمَا كَانُو[s[اْ] مُهْتَد[p[ِي]نَ","Ана ўшалар, ҳидоятга залолатни сотиб олганлардир. Ва тижоратлари фойда келтирмади ҳамда ҳидоят топганлардан бўлмадилар.",3,1],["مَثَلُهُمْ كَمَثَلِ [h:55[ٱ]لَّذِى [h:56[ٱ]سْتَوْقَدَ نَا[f:57[رًا ف]َلَ[g[مّ][o[َآ] أَض[o[َا]ٓءَتْ مَا حَوْلَهُ[n[ۥ] ذَهَبَ [h:58[ٱ]للَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَ[n[ـٰ][u:59[تٍ ل]َّا يُ[q:60[بْ]صِر[p[ُو]نَ","Улар мисоли ёққан ўти энди атрофини ёритганида Аллоҳ нурларини кетказиб, қоронғу зулматларда қолдирган кишиларга ўхшайдилар. Улар кўрмайдилар.",4,1],["صُم[i:61[ُّۢ ب]ُكْمٌ عُمْ[f:62[ىٌ ف]َهُمْ لَا يَرْجِع[p[ُو]نَ","Улар кар, соқов, кўрдирлар. Бас, улар қайтмаслар.",4,1],["أَوْ كَصَيِّ[a:63[بٍ م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ فِيهِ ظُلُمَ[n[ـٰ][a:65[تٌ و]َرَعْ[a:66[دٌ و]َبَرْ[a:67[قٌ ي]َ[q:68[جْ]عَلُونَ أَصَ[n[ـٰ]بِعَهُمْ ف[o[ِىٓ] ءَاذَانِه[w:69[ِم م]ِّنَ [h:70[ٱ][l[ل]صَّو[n[َٲ]عِقِ حَذَرَ [h:71[ٱ]لْمَوْتِ‌ۚ وَ[h:72[ٱ]للَّهُ مُحِي[i:73[طُۢ ب]ِ[h:74[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Ёки худди осмондан ёмғир ёғиб, қоронғу босиб, момақалдироқ ва чақмоқ чаққанда, яшиндан қочиб, панжаларини қулоқларига тиқиб, ўлимдан эҳтиёт бўлаётган одамга ўхшарлар. Ва Аллоҳ кофирларни ўраб олувчидир.",4,1],["يَكَادُ [h:75[ٱ]لْبَرْقُ يَخْطَفُ أَ[q:76[بْ]صَ[n[ـٰ]رَهُمْ‌ۖ كُلَّم[o[َآ] أَض[o[َا]ٓءَ لَه[w:77[ُم م]َّشَوْ[s[اْ] فِيهِ وَإِذ[o[َآ] أَظْلَمَ عَلَيْهِمْ قَامُو[s[اْ‌ۚ] وَلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَ[q:79[بْ]صَ[n[ـٰ]رِهِمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Чақмоқ уларнинг кўзини олиб қўяй дейди. Ёриган пайтда юришади, қоронғи бўлса, тўхташади. Агар Аллоҳ хоҳласа, уларнинг кўзу қулоқларини кеткизади. Албатта, Аллоҳ ҳар бир нарсага қодирдир.",4,1],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ [h:83[ٱ]عْبُدُو[s[اْ] رَبَّكُمُ [h:84[ٱ]لَّذِى خَلَقَكُمْ وَ[h:37[ٱ]لَّذِينَ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ لَعَلَّكُمْ تَتَّق[p[ُو]نَ","Эй одамлар, сизларни ва сиздан олдингиларни яратган Роббингизга ибодат қилинг. Шоядки тақводор бўлсангиз.",4,1],["ٱلَّذِى جَعَلَ لَكُمُ [h:87[ٱ]لْأَرْضَ فِر[n[َٲ][a:88[شًا و]َ[h:89[ٱ][l[ل]سَّم[o[َا]ٓءَ بِن[o[َا]ٓ[a:90[ءً و]َأَ[f:91[نز]َلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:92[ءً ف]َأَخْرَجَ بِه[n[ِۦ] مِنَ [h:93[ٱ][l[ل]ثَّمَر[n[َٲ]تِ رِزْ[u:94[قًا ل]َّكُمْ‌ۖ فَلَا تَ[q:95[جْ]عَلُو[s[اْ] لِلَّهِ أَ[f:96[ند]َا[a:97[دًا و]َأَ[f:98[نت]ُمْ تَعْلَم[p[ُو]نَ","У сизларга ерни тўшаб, осмонни бино қилган ва осмондан сув тушириб, у билан сизларга меваларни ризқ қилиб чиқарган зотдир. Билиб туриб Аллоҳга бошқаларни тенглаштирманг.",4,1],["وَإِ[f:99[ن ك]ُ[f:100[نت]ُمْ فِى رَيْ[a:101[بٍ م]ِّ[g[مّ]َا نَزَّلْنَا عَلَىٰ عَ[q:102[بْ]دِنَا فَأْتُو[s[اْ] بِسُورَ[a:103[ةٍ م]ّ[a:104[ِن م]ِّثْلِه[n[ِۦ] وَ[h:105[ٱ][q:105[دْ]عُو[s[اْ] شُهَد[o[َا]ٓءَك[w:106[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Ва агар бандамизга туширилган нарсамизга шакингиз бўлса, унга ўхшаш бир сура келтиринг ва рост сўзловчилардан бўлсангиз, Аллоҳдан ўзга гувоҳларингизни чақиринг.",4,1],["فَإ[u:110[ِن ل]َّمْ تَفْعَلُو[s[اْ] وَلَ[f:111[ن ت]َفْعَلُو[s[اْ] فَ[h:112[ٱ]تَّقُو[s[اْ] [h:113[ٱ][l[ل][g[نّ]َارَ [h:114[ٱ]لَّتِى وَقُودُهَا [h:115[ٱ][l[ل][g[نّ]َاسُ وَ[h:116[ٱ]لْحِجَارَةُ‌ۖ أُعِدَّتْ لِلْكَ[n[ـٰ]فِر[p[ِي]نَ","Бас, агар қила олмасанглар, ҳеч қачон қила олмайсизлар ҳам, ёқилғиси одамлар ва тош бўлган, кофирлар учун тайёрланган ўтдан қўрқинглар.",4,1],["وَبَشِّرِ [h:117[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ أَ[g[نّ]َ لَهُمْ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۖ كُلَّمَا رُزِقُو[s[اْ] مِنْهَا مِ[f:123[ن ث]َمَرَ[u:124[ةٍ ر]ِّزْ[f:125[قًا‌ۙ ق]َالُو[s[اْ] هَ[n[ـٰ]ذَا [h:126[ٱ]لَّذِى رُزِ[q:127[قْ]نَا مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ وَأُتُو[s[اْ] بِه[n[ِۦ] مُتَشَ[n[ـٰ]بِ[a:130[هًا‌ۖ و]َلَهُمْ فِيه[o[َآ] أَزْو[n[َٲ][a:131[جٌ م]ُّطَهَّرَ[a:132[ةٌ‌ۖ و]َهُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Иймон келтирган ва солиҳ амаллар қилганларга, улар учун остидан анҳорлар оқиб турган жаннатлар борлигининг башоратини бер. Қачонки уларнинг мевасидан баҳраманд бўлсалар, бундан аввал ҳам ризқланган эдик, дейишади. Уларга ўхшаш нарсалар берилгандир. Уларга бу ерда покиза жуфтлар бор ва улар у ерда абадий қолурлар.",5,1],["۞ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَسْتَحْى[o[ِۦٓ] أ[a:133[َن ي]َضْرِبَ مَثَل[a:134[اً م]َّا بَعُوضَ[f:135[ةً ف]َمَا فَوْقَهَا‌ۚ فَأَ[g[مّ]َا [h:136[ٱ]لَّذِينَ ءَامَنُو[s[اْ] فَيَعْلَمُونَ أَ[g[نّ]َهُ [h:137[ٱ]لْحَقُّ م[u:22[ِن ر]َّبِّهِمْ‌ۖ وَأَ[g[مّ]َا [h:138[ٱ]لَّذِينَ كَفَرُو[s[اْ] فَيَقُولُونَ مَاذ[o[َآ] أَرَادَ [h:139[ٱ]للَّهُ بِهَ[n[ـٰ]ذَا مَثَل[a:140[اً‌ۘ ي]ُضِلُّ بِه[n[ِۦ] كَثِي[a:141[رًا و]َيَهْدِى بِه[n[ِۦ] كَثِي[a:142[رًا‌ۚ و]َمَا يُضِلُّ بِه[o[ِۦٓ] إِلَّا [h:143[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","Албатта, Аллоҳ чивин ёки ундан устунроқ нарсани мисол келтиришдан уялмас. Иймон келтирганлар, албатта, у Роббиларидан келган ҳақлигини биладилар. Аммо куфр келтирганлар. Аллоҳ бу мисолдан нимани ирода қилади, дейишади. У билан кўпчиликни залолатга кеткизади ва кўпчиликни ҳидоятга солади. У билан фақат фосиқларнигина залолатга кеткизади.",5,1],["ٱلَّذِينَ يَ[f:144[نق]ُضُونَ عَهْدَ [h:145[ٱ]للَّهِ م[i:146[ِنۢ ب]َعْدِ مِيثَ[n[ـٰ]قِه[n[ِۦ] وَيَ[q:147[قْ]طَعُونَ م[o[َآ] أَمَرَ [h:148[ٱ]للَّهُ بِه[o[ِۦٓ] أ[a:149[َن ي]ُوصَلَ وَيُفْسِدُونَ فِى [h:44[ٱ]لْأَرْضِ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:150[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","Улар Аллоҳнинг аҳдини боғлангандан сўнг бузадиган, Аллоҳ боғланишига буюрган нарсаларни кесадиган, ер юзида фасод қиладиган зотлардир. Ана ўшалар ютқазувчилардир.",5,1],["كَيْفَ تَكْفُرُونَ بِ[h:32[ٱ]للَّهِ وَكُ[f:151[نت]ُمْ أَمْو[n[َٲ][f:152[تًا ف]َأَحْيَ[n[ـٰ]كُمْ‌ۖ ثُ[g[مّ]َ يُمِيتُكُمْ ثُ[g[مّ]َ يُحْيِيكُمْ ثُ[g[مّ]َ إِلَيْهِ تُرْجَع[p[ُو]نَ","Аллоҳга қандай куфр келтирасизлар? Ва ҳолбуки жонсиз эдингиз У сизга жон берди, сўнгра жонингизни олади ва яна тирилтиради ва сизлар Унга қайтажаксизлар.",5,1],["هُوَ [h:153[ٱ]لَّذِى خَلَقَ لَك[w:154[ُم م]َّا فِى [h:44[ٱ]لْأَرْضِ جَمِي[f:155[عًا ث]ُ[g[مّ]َ [h:156[ٱ]سْتَوَ[o[ىٰٓ] إِلَى [h:157[ٱ][l[ل]سَّم[o[َا]ٓءِ فَسَوَّ[n[ٮٰ]هُ[g[نّ]َ سَ[q:158[بْ]عَ سَمَ[n[ـٰ]و[n[َٲ][a:159[تٍ‌ۚ و]َهُوَ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","У сизлар учун ер юзидаги барча нарсани яратган зот. Сўнгра осмонга юзланди ва уларни еттита қилиб тўғрилади. Ва У ҳар бир нарсани билувчи зотдир.",5,1],["وَإِذْ قَالَ رَبُّكَ لِلْمَلَ[o[ـٰٓ]ئِكَةِ إِ[g[نّ]ِى جَاعِ[f:160[لٌ ف]ِى [h:44[ٱ]لْأَرْضِ خَلِيفَ[f:161[ةً‌ۖ ق]َال[o[ُوٓ][s[اْ] أَتَ[q:162[جْ]عَلُ فِيهَا م[a:163[َن ي]ُفْسِدُ فِيهَا وَيَسْفِكُ [h:164[ٱ][l[ل]دِّم[o[َا]ٓءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ‌ۖ قَالَ إِ[g[نّ][o[ِىٓ] أَعْلَمُ مَا لَا تَعْلَم[p[ُو]نَ","Эсла, вақтики Роббинг фаришталарга: \"Мен ер юзида халифа қилмоқчиман\", деди. Улар: \"Унда фасод қиладиган, қон тўкадиган кимсани қилмоқчимисан? Ва ҳолбуки, биз Сенга тасбиҳ, ҳамд айтиб ва Сени улуғлаб турибмиз\", дедилар. У: \"Мен сиз билмаганни биламан\", деди.",6,1],["وَعَلَّمَ ءَادَمَ [h:165[ٱ]لْأَسْم[o[َا]ٓءَ كُلَّهَا ثُ[g[مّ]َ عَرَضَهُمْ عَلَى [h:166[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ فَقَالَ أَ[i:167[نۢب]ِــُٔونِى بِأَسْم[o[َا]ٓءِ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Ва У зот одамга исмларнинг барчасини ўргатди, сўнгра уларни фаришталарга рўбарў қилди. Кейин: \"Агар ростгўйлардан бўлсангиз, анавиларнинг исмларини Менга айтиб беринг\", деди.",6,1],["قَالُو[s[اْ] سُ[q:168[بْ]حَ[n[ـٰ]نَكَ لَا عِلْمَ لَن[o[َآ] إِلَّا مَا عَلَّمْتَن[o[َآ‌ۖ] إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:170[ٱ]لْعَلِيمُ [h:171[ٱ]لْحَك[p[ِي]مُ","Улар:\"Эй пок Парвардигор! Бизда Сен билдиргандан бошқа илм йўқ. Албатта, Сенинг Ўзинг билувчисан ва ҳикматли зотсан\", дедилар.",6,1],["قَالَ يَ[o[ـٰٓـ]ــَٔادَمُ أَ[i:172[نۢب]ِئْه[c:173[ُم ب]ِأَسْم[o[َا]ٓئِهِمْ‌ۖ فَلَ[g[مّ][o[َآ] أَ[i:174[نۢب]َأَه[c:175[ُم ب]ِأَسْم[o[َا]ٓئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِ[g[نّ][o[ِىٓ] أَعْلَمُ غَيْبَ [h:176[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَأَعْلَمُ مَا تُ[q:178[بْ]دُونَ وَمَا كُ[f:100[نت]ُمْ تَكْتُم[p[ُو]نَ","У зот:\"Эй Одам, буларга у нарсаларнинг исмларини айтиб бер\", деди. Уларга ўша нарсаларнинг исмларини айтиб берган чоғида, \"Мен сизларга осмонлару ернинг ғайбини биламан ва сизлар беркитмагану беркитган нарсаларни ҳам биламан демабмидим\", деди.",6,1],["وَإِذْ قُلْنَا لِلْمَلَ[o[ـٰٓ]ئِكَةِ [h:179[ٱ]سْجُدُو[s[اْ] لِأَدَمَ فَسَجَد[o[ُوٓ][s[اْ] إِلّ[o[َآ] إِ[q:180[بْ]لِيسَ أَبَىٰ وَ[h:181[ٱ]سْتَكْبَرَ وَكَانَ مِنَ [h:182[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Эсла, фаришталарга: \"Одамга сажда қилинглар!\" деганимизни. Бас, сажда қилдилар, магар Иблис бош тортди, мутакаббирлик қилди ва кофирлардан бўлди.",6,1],["وَقُلْنَا يَ[o[ـٰٓـ]ــَٔادَمُ [h:183[ٱ]سْكُنْ أَ[f:169[نت]َ وَزَوْجُكَ [h:184[ٱ]لْجَ[g[نّ]َةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَ[q:185[قْ]رَبَا هَ[n[ـٰ]ذِهِ [h:186[ٱ][l[ل]شَّجَرَةَ فَتَكُونَا مِنَ [h:187[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Ва: \"Эй Одам, сен ўз жуфтинг ила жаннатда маскан топ. Унда нимани хоҳласаларингиз, енглар, ош бўлсин ва мана бу дарахтга яқин келманглар, бас, у ҳолда золимлардан бўласизлар\", дедик.",6,1],["فَأَزَلَّهُمَا [h:188[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ عَنْهَا فَأَخْرَجَهُمَا مِ[g[مّ]َا كَانَا فِيهِ‌ۖ وَقُلْنَا [h:189[ٱ]هْبِطُو[s[اْ] بَعْضُكُمْ لِبَعْضٍ عَدُ[a:190[وٌّ‌ۖ و]َلَكُمْ فِى [h:44[ٱ]لْأَرْضِ مُسْتَقَ[a:191[رٌّ و]َمَتَ[n[ـٰ]عٌ إِلَىٰ ح[p[ِي]نٍ","Шайтон уларни ундан оздирди ва бўлган нарсаларидан чиқарди. Ва Биз: \"Баъзингиз баъзингизга душман бўлиб тушинглар, сизларга ер юзида қароргоҳ ва бир муддат ҳузур қилиш бордир\", дедик.",6,1],["فَتَلَقَّ[o[ىٰٓ] ءَادَمُ م[u:192[ِن ر]َّبِّه[n[ِۦ] كَلِمَ[n[ـٰ][f:193[تٍ ف]َتَابَ عَلَيْهِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:194[ٱ][l[ل]تَّوَّابُ [h:195[ٱ][l[ل]رَّح[p[ِي]مُ","Бас, Одам ўз Роббисидан сўзларни қабул қилиб олди, кейин У зот унинг тавбасини қабул қилди. Албатта, У тавбани қабул қилувчи ва раҳмли зотдир.",6,1],["قُلْنَا [h:196[ٱ]هْبِطُو[s[اْ] مِنْهَا جَمِي[f:197[عًا‌ۖ ف]َإِ[g[مّ]َا يَأْتِيَ[g[نّ]َك[w:198[ُم م]ِّ[g[نّ]ِى هُ[f:199[دًى ف]َمَ[f:200[ن ت]َبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Биз: \"Ундан ҳаммангиз тушинг, бас, Мендан сизга ҳидоят келажак. Ким Менинг ҳидоятимга эргашса, уларга хавф йўқ ва улар хафа ҳам бўлмаслар\", дедик.",7,1],["وَ[h:9999[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَكَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِن[o[َآ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Ва куфр келтирган ҳамда оятларимизни ёлғонга чиқарганлар эса, улар дўзах эгаларидир, улар унда абадий қолурлар.",7,1],["يَ[n[ـٰ]بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ [h:202[ٱ]ذْكُرُو[s[اْ] نِعْمَتِىَ [h:203[ٱ]لَّت[o[ِىٓ] أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُو[s[اْ] بِعَهْد[o[ِىٓ] أُوفِ بِعَهْدِكُمْ وَإِيَّ[n[ـٰ]ىَ فَ[h:204[ٱ]رْهَب[p[ُو]نِ","Эй Бани Исроил, сизга берган неъматларимни эсланг ва Менга берган аҳдингизга вафо қилинг. Мен ҳам сизга берган аҳдимга вафо қиламан. Ва Мендангина қўрқинг.",7,1],["وَءَامِنُو[s[اْ] بِم[o[َآ] أَ[f:205[نز]َلْتُ مُصَدِّ[u:206[قًا ل]ِّمَا مَعَكُمْ وَلَا تَكُون[o[ُوٓ][s[اْ] أَوَّلَ كَافِ[i:207[رِۭ ب]ِه[n[ِۦ]‌ۖ وَلَا تَشْتَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِى ثَمَ[f:208[نًا ق]َلِيل[a:209[اً و]َإِيَّ[n[ـٰ]ىَ فَ[h:210[ٱ]تَّق[p[ُو]نِ","Ва сиздаги нарсани тасдиқловчи қилиб туширган нарсамга иймон келтиринг. Унга биринчи куфр келтирувчи бўлманг. Менинг оятларимни оз баҳога сотманг ва Менгагина тақво қилинг.",7,1],["وَلَا تَلْبِسُو[s[اْ] [h:211[ٱ]لْحَقَّ بِ[h:212[ٱ]لْبَ[n[ـٰ]طِلِ وَتَكْتُمُو[s[اْ] [h:213[ٱ]لْحَقَّ وَأَ[f:98[نت]ُمْ تَعْلَم[p[ُو]نَ","Ҳақни ботилга аралаштирманг ва ўзингиз билиб туриб ҳақни беркитманг.",7,1],["وَأَقِيمُو[s[اْ] [h:214[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتُو[s[اْ] [h:215[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَ[h:216[ٱ]رْكَعُو[s[اْ] مَعَ [h:217[ٱ][l[ل]رّ[n[َٲ]كِع[p[ِي]نَ","Намозни тўкис адо қилинг, закот беринг ва рукуъ қилувчилар билан рукуъ қилинг.",7,1],["۞ أَتَأْمُرُونَ [h:218[ٱ][l[ل][g[نّ]َاسَ بِ[h:219[ٱ]لْبِرِّ وَتَ[f:220[نس]َوْنَ أَ[f:221[نف]ُسَكُمْ وَأَ[f:98[نت]ُمْ تَتْلُونَ [h:222[ٱ]لْكِتَ[n[ـٰ]بَ‌ۚ أَفَلَا تَعْقِل[p[ُو]نَ","Одамларни яхшиликка чорлаб туриб, ўзингизни унутасизми? Ҳолбуки, китобни тиловат қиляпсиз-ку. Ақлни ишлатмайсизми?!",7,1],["وَ[h:9999[ٱ]سْتَعِينُو[s[اْ] بِ[h:223[ٱ][l[ل]صَّ[q:223[بْ]رِ وَ[h:224[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ‌ۚ وَإِ[g[نّ]َهَا لَكَبِيرَةٌ إِلَّا عَلَى [h:225[ٱ]لْخَ[n[ـٰ]شِع[p[ِي]نَ","Сабр ва намоз ила ёрдам сўранг. Ва, албатта, у нафси синиқлардан бошқаларга жуда катта ишдир.",7,1],["ٱلَّذِينَ يَظُ[g[نّ]ُونَ أَ[g[نّ]َه[w:226[ُم م]ُّلَ[n[ـٰ]قُو[s[اْ] رَبِّهِمْ وَأَ[g[نّ]َهُمْ إِلَيْهِ ر[n[َٲ]جِع[p[ُو]نَ","Улар, албатта, Роббиларига рўбарў бўлишлари ва, албатта, Унга қайтиб боришларига ишонган зотлардир.",7,1],["يَ[n[ـٰ]بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ [h:202[ٱ]ذْكُرُو[s[اْ] نِعْمَتِىَ [h:203[ٱ]لَّت[o[ِىٓ] أَنْعَمْتُ عَلَيْكُمْ وَأَ[g[نّ]ِى فَضَّلْتُكُمْ عَلَى [h:227[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Эй Бани Исроил, сизга берган неъматларимни ва Мен сизларни оламлардан афзал қилиб қўйганимни эсланг!",7,1],["وَ[h:9999[ٱ]تَّقُو[s[اْ] يَوْ[u:228[مًا ل]َّا تَ[q:229[جْ]زِى نَفْسٌ ع[a:230[َن ن]َّفْ[f:231[سٍ ش]َيْـ[a:232[ـًٔا و]َلَا يُ[q:233[قْ]بَلُ مِنْهَا شَفَ[n[ـٰ]عَ[a:234[ةٌ و]َلَا يُؤْخَذُ مِنْهَا عَ[q:235[دْ][a:236[لٌ و]َلَا هُمْ يُ[f:237[نص]َر[p[ُو]نَ","Бир жон бошқасидан ҳеч нарсани адо қила олмайдиган, ундан шафоат қабул қилинмайдиган, ундан тўлов олинмайдиган ва уларга ёрдам берилмайдиган кундан қўрқинг.",7,1],["وَإِذْ نَجَّيْنَ[n[ـٰ]ك[w:238[ُم م]ِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ س[o[ُو]ٓءَ [h:239[ٱ]لْعَذَابِ يُذَبِّحُونَ أَ[q:240[بْ]ن[o[َا]ٓءَكُمْ وَيَسْتَحْيُونَ نِس[o[َا]ٓءَكُمْ‌ۚ وَفِى ذ[n[َٲ]لِك[c:241[ُم ب]َل[o[َا]ٓ[a:242[ءٌ م]ّ[u:243[ِن ر]َّبِّكُمْ عَظ[p[ِي]مٌ","Сизни ёмон азобларга солиб, ўғилларингизни сўйиб, қизларингизни тирик қолдираётган Фиръавн аҳлидан қутқарганимизни эсланг. Ана ўшанда Роббингиздан улуғ синов бордир.",8,1],["وَإِذْ فَرَ[q:244[قْ]نَا بِكُمُ [h:245[ٱ]لْبَحْرَ فَأَ[f:246[نج]َيْنَ[n[ـٰ]كُمْ وَأَغْرَ[q:247[قْ]ن[o[َآ] ءَالَ فِرْعَوْنَ وَأَ[f:98[نت]ُمْ تَ[f:248[نظ]ُر[p[ُو]نَ","Ва денгизни ёриб, сизни қутқариб, сизнинг кўз олдингизда Фиръавн аҳлини ғарқ қилганимизни эсланг.",8,1],["وَإِذْ و[n[َٲ]عَ[q:249[دْ]نَا مُوسَ[o[ىٰٓ] أَرْبَعِينَ لَيْلَ[f:250[ةً ث]ُ[g[مّ]َ [h:251[ٱ]تَّخَذْتُمُ [h:252[ٱ]لْعِ[q:253[جْ]لَ م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] وَأَ[f:98[نت]ُمْ ظَ[n[ـٰ]لِم[p[ُو]نَ","Ва Мусо билан қирқ кечага ваъдалашганимизни, у дан сўнг золим бўлган ҳолингизда бузоқни тутганингизни эсланг!",8,1],["ثُ[g[مّ]َ عَفَوْنَا عَ[f:255[نك][w:256[ُم م]ّ[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ لَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Ўшандан кейин сизни афв этдик. Шоядки шукр қилсангиз.",8,1],["وَإِذْ ءَاتَيْنَا مُوسَى [h:257[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:258[ٱ]لْفُرْقَانَ لَعَلَّكُمْ تَهْتَد[p[ُو]نَ","Шоядки ҳидоят топсангиз, деб Мусога китобни ва фурқонни берганимизни эсланг.",8,1],["وَإِذْ قَالَ مُوسَىٰ لِقَوْمِه[n[ِۦ] يَ[n[ـٰ]قَوْمِ إِ[g[نّ]َكُمْ ظَلَمْتُمْ أَ[f:221[نف]ُسَك[c:259[ُم ب]ِ[h:260[ٱ]تِّخَاذِكُمُ [h:261[ٱ]لْعِ[q:253[جْ]لَ فَتُوب[o[ُوٓ][s[اْ] إِلَىٰ بَارِئِكُمْ فَ[h:262[ٱ][q:262[قْ]تُل[o[ُوٓ][s[اْ] أَ[f:221[نف]ُسَكُمْ ذ[n[َٲ]لِكُمْ خَيْ[u:263[رٌ ل]َّكُمْ عِ[f:264[ند]َ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ‌ۚ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:194[ٱ][l[ل]تَّوَّابُ [h:195[ٱ][l[ل]رَّح[p[ِي]مُ","Мусонинг ўз қавмига: «Эй қавмим, албатта, сиз бузоқни тутишингиз ила ўзингизга ўзингиз зулм қилдингиз. Энди сизни йўқдан бор қилувчи зотга тавба қилинг, ўзингизни ўзингиз ўлдиринг, шундоқ қилмоғингиз йўқданбор қилувчи зот ҳузурида сиз учун яхшидир. Бас, тавбангизни қабул қилди. Чунки У тавбани кўплаб қабул қилувчи ва раҳмли зотдир», деганини эсланг.",8,1],["وَإِذْ قُلْتُمْ يَ[n[ـٰ]مُوسَىٰ ل[a:265[َن ن]ُّؤْمِنَ لَكَ حَتَّىٰ نَرَى [h:266[ٱ]للَّهَ جَهْرَ[f:267[ةً ف]َأَخَذَتْكُمُ [h:268[ٱ][l[ل]صَّ[n[ـٰ]عِقَةُ وَأَ[f:98[نت]ُمْ تَ[f:248[نظ]ُر[p[ُو]نَ","«Эй Мусо, Аллоҳни очиқ-равшан кўрмагунимизча сенга ишонмаймиз», деганингизни, шунда сизни ўзингиз назар солиб турганингизда яшин урганини эсланг.",8,1],["ثُ[g[مّ]َ بَعَثْنَ[n[ـٰ]ك[w:269[ُم م]ّ[i:146[ِنۢ ب]َعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Сўнгра ўлимингиздан кейин қайта тирилтирдик, шоядки шукр қилсангиз.",8,1],["وَظَلَّلْنَا عَلَيْكُمُ [h:270[ٱ]لْغَمَامَ وَأَ[f:271[نز]َلْنَا عَلَيْكُمُ [h:272[ٱ]لْمَ[g[نّ]َ وَ[h:273[ٱ][l[ل]سَّلْوَىٰ‌ۖ كُلُو[s[اْ] مِ[f:274[ن ط]َيِّبَ[n[ـٰ]تِ مَا رَزَ[q:275[قْ]نَ[n[ـٰ]كُمْ‌ۖ وَمَا ظَلَمُونَا وَلَ[n[ـٰ]كِ[f:276[ن ك]َان[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ يَظْلِم[p[ُو]نَ","Ва булутни устингиздан соя солдириб қўйдик, сизга манн ва беданани туширдик. Ризқ қилиб берган нарсаларимизнинг покларини енглар. Бизга зулм қилмадилар. Лекин ўзларига зулм қилар эдилар.",8,1],["وَإِذْ قُلْنَا [h:277[ٱ][q:278[دْ]خُلُو[s[اْ] هَ[n[ـٰ]ذِهِ [h:279[ٱ]لْقَرْيَةَ فَكُلُو[s[اْ] مِنْهَا حَيْثُ شِئْتُمْ رَغَ[a:280[دًا و]َ[h:281[ٱ][q:281[دْ]خُلُو[s[اْ] [h:282[ٱ]لْبَابَ سُجَّ[a:283[دًا و]َقُولُو[s[اْ] حِطَّ[a:284[ةٌ ن]َّغْفِرْ لَكُمْ خَطَ[n[ـٰ]يَ[n[ـٰ]كُمْ‌ۚ وَسَنَزِيدُ [h:285[ٱ]لْمُحْسِن[p[ِي]نَ","«Ушбу қишлоққа кирингиз ва унинг хоҳлаган жойида енглар, еганингиз ош бўлсин ва эшикдан таъзим билан, ҳиттатун, деб киринг, сизнинг хатоларингизни мағфират қиламиз ва яхшиларга зиёда қиламиз», деганимизни эсланг.",9,1],["فَبَدَّلَ [h:286[ٱ]لَّذِينَ ظَلَمُو[s[اْ] قَوْلاً غَيْرَ [h:287[ٱ]لَّذِى قِيلَ لَهُمْ فَأَ[f:288[نز]َلْنَا عَلَى [h:289[ٱ]لَّذِينَ ظَلَمُو[s[اْ] رِ[q:290[جْ][a:291[زًا م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ بِمَا كَانُو[s[اْ] يَفْسُق[p[ُو]نَ","Бас, зулм қилганлар уларга айтилган сўзни бошқасига алмаштирдилар. Биз зулм қилганларга фисқ қилаётганлари учун осмондан азоб туширдик.",9,1],["۞ وَإِذِ [h:292[ٱ]سْتَسْقَىٰ مُوسَىٰ لِقَوْمِه[n[ِۦ] فَقُلْنَا [h:293[ٱ]ضْرِب بِّعَصَاكَ [h:294[ٱ]لْحَجَرَ‌ۖ فَ[h:295[ٱ][f:295[نف]َجَرَتْ مِنْهُ [h:296[ٱ]ثْنَتَا عَشْرَةَ عَيْ[f:297[نًا‌ۖ ق]َ[q:298[دْ] عَلِمَ كُلُّ أُنَا[a:299[سٍ م]َّشْرَبَهُمْ‌ۖ كُلُو[s[اْ] وَ[h:300[ٱ]شْرَبُو[s[اْ] م[u:301[ِن ر]ِّزْقِ [h:302[ٱ]للَّهِ وَلَا تَعْثَوْ[s[اْ] فِى [h:44[ٱ]لْأَرْضِ مُفْسِد[p[ِي]نَ","Мусо ўз қавмини сероб қилишни сўраганида, «Ҳассанг билан тошни ур!» деганимизни эсланг. Бас, ундан ўн икки булоқ отилиб чиқди. Ҳар қабила ўз сувини билди. Аллоҳ берган ризқдан еб-ичинглар. Ер юзида бузғунчилик устига бузғунчилик қилманглар.",9,1],["وَإِذْ قُلْتُمْ يَ[n[ـٰ]مُوسَىٰ ل[a:303[َن ن]َّصْبِرَ عَلَىٰ طَعَا[a:304[مٍ و][n[َٲ]حِ[f:305[دٍ ف]َ[h:306[ٱ][q:306[دْ]عُ لَنَا رَبَّكَ يُخْرِ[q:307[جْ] لَنَا مِ[g[مّ]َا تُ[i:308[نۢب]ِتُ [h:309[ٱ]لْأَرْضُ م[i:310[ِنۢ ب]َ[q:311[قْ]لِهَا وَقِثّ[o[َا]ٓئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا‌ۖ قَالَ أَتَسْتَ[q:312[بْ]دِلُونَ [h:313[ٱ]لَّذِى هُوَ أَ[q:314[دْ]نَىٰ بِ[h:315[ٱ]لَّذِى هُوَ خَيْرٌ‌ۚ [h:316[ٱ]هْبِطُو[s[اْ] مِصْ[f:317[رًا ف]َإِ[g[نّ]َ لَك[w:154[ُم م]َّا سَأَلْتُمْ‌ۗ وَضُرِبَتْ عَلَيْهِمُ [h:318[ٱ][l[ل]ذِّلَّةُ وَ[h:319[ٱ]لْمَسْكَنَةُ وَب[o[َا]ٓءُو بِغَضَ[a:320[بٍ م]ِّنَ [h:321[ٱ]للَّهِ‌ۗ ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ كَانُو[s[اْ] يَكْفُرُونَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ وَيَ[q:323[قْ]تُلُونَ [h:324[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ بِغَيْرِ [h:325[ٱ]لْحَقِّ‌ۗ ذ[n[َٲ]لِكَ بِمَا عَصَو[s[اْ] وَّكَانُو[s[اْ] يَعْتَد[p[ُو]نَ","«Эй Мусо, бир хил таомга ҳеч чидай олмаймиз, Роббингга дуо қил, бизга ерда ўсадиган нарсалардан–сабзавот, бодринг, саримсоқ, мош, пиёз чиқариб берсин», деганингизни эсланг. У: «Яхши нарсани паст нарсага алмаштиришни сўрайсизларми? Бирорта шаҳарга тушинг, сўраганингизни албатта, топасиз», деди. Уларга хорлик ва мискинлик ёзилди ва Аллоҳнинг ғазабига лойиқ бўлдилар. Бу Аллоҳнинг оятларига куфр келтирганлари, Пайғамбарларни ноҳақ қатл этганлари учундир. Бу исёнга кетганлари ва ҳаддан ошганлари учундир.",9,1],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَ[h:37[ٱ]لَّذِينَ هَادُو[s[اْ] وَ[h:326[ٱ][l[ل][g[نّ]َصَ[n[ـٰ]رَىٰ وَ[h:327[ٱ][l[ل]صَّ[n[ـٰ]بِــِٔينَ مَنْ ءَامَنَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ وَعَمِلَ صَ[n[ـٰ]لِ[f:330[حًا ف]َلَهُمْ أَ[q:331[جْ]رُهُمْ عِ[f:264[ند]َ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Албатта, иймон келтирганлар, яҳудий бўлганлар, насоролар ва собиийлардан, қайсилари Аллоҳга ва қиёмат кунига иймон келтирса ва яхши амалларни қилса, ўшаларга Роббилари ҳузурида ажрлар бордир. Уларга хавф йўқ ва улар хафа ҳам бўлмаслар.",10,1],["وَإِذْ أَخَذْنَا مِيثَ[n[ـٰ]قَكُمْ وَرَفَعْنَا فَوْقَكُمُ [h:332[ٱ][l[ل]طُّورَ خُذُو[s[اْ] م[o[َآ] ءَاتَيْنَ[n[ـٰ]ك[c:333[ُم ب]ِقُوَّ[a:334[ةٍ و]َ[h:335[ٱ]ذْكُرُو[s[اْ] مَا فِيهِ لَعَلَّكُمْ تَتَّق[p[ُو]نَ","Аҳду паймонларингизни олганимизни ва устингизга Турни кўтарганимизни, «Биз сизга берган нарсани қувват билан олинг ва ундаги нарсани эсланг, шоядки тақводор бўлсангиз», деганимизни эсланг.",10,1],["ثُ[g[مّ]َ تَوَلَّيْت[w:336[ُم م]ّ[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ‌ۖ فَلَوْلَا فَضْلُ [h:337[ٱ]للَّهِ عَلَيْكُمْ وَرَحْمَتُهُ[n[ۥ] لَكُ[f:338[نت][w:339[ُم م]ِّنَ [h:340[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","Сўнгра ўшандан кейин юз ўгирдингиз. Сизга Аллоҳнинг фазли бўлмаганида, албатта ютқазганлардан бўлардингиз.",10,1],["وَلَقَ[q:341[دْ] عَلِمْتُمُ [h:342[ٱ]لَّذِينَ [h:343[ٱ]عْتَدَوْ[s[اْ] مِ[f:344[نك]ُمْ فِى [h:345[ٱ][l[ل]سَّ[q:346[بْ]تِ فَقُلْنَا لَهُمْ كُونُو[s[اْ] قِرَدَةً خَ[n[ـٰ]سِــٔ[p[ِي]نَ","Батаҳқиқ, сизлардан шанба куни тажовузкорлик қилганларни билдингиз. Биз уларга: «Қувилган, хор-зор маймунга айланинг», дедик.",10,1],["فَجَعَلْنَ[n[ـٰ]هَا نَكَ[n[ـٰ]ل[u:347[اً ل]ِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَ[u:348[ةً ل]ِّلْمُتَّق[p[ِي]نَ","Биз бу ни унинг олдидагиларга ва кейинидагиларга ва тақводорларга мавъиза қилдик.",10,1],["وَإِذْ قَالَ مُوسَىٰ لِقَوْمِه[o[ِۦٓ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَأْمُرُكُمْ أَ[f:349[ن ت]َذْبَحُو[s[اْ] بَقَرَ[f:350[ةً‌ۖ ق]َال[o[ُوٓ][s[اْ] أَتَتَّخِذُنَا هُزُ[f:351[وًا‌ۖ ق]َالَ أَعُوذُ بِ[h:32[ٱ]للَّهِ أَنْ أَكُونَ مِنَ [h:352[ٱ]لْجَ[n[ـٰ]هِل[p[ِي]نَ","Мусо ўз қавмига: «Аллоҳ сизга сигир сўймоқни буюрмоқда», деганини эсланг. Улар: «Бизни масхара қиляпсанми?» дедилар. У: «Жоҳиллардан бўлишимдан Аллоҳдан паноҳ сўрайман», деди.",10,1],["قَالُو[s[اْ] [h:353[ٱ][q:354[دْ]عُ لَنَا رَبَّكَ يُبَيّ[u:355[ِن ل]َّنَا مَا هِىَ‌ۚ قَالَ إِ[g[نّ]َهُ[n[ۥ] يَقُولُ إِ[g[نّ]َهَا بَقَرَ[u:356[ةٌ ل]َّا فَارِ[a:357[ضٌ و]َلَا بِكْرٌ عَوَا[i:358[نُۢ ب]َيْنَ ذ[n[َٲ]لِكَ‌ۖ فَ[h:359[ٱ]فْعَلُو[s[اْ] مَا تُؤْمَر[p[ُو]نَ","Улар: «Роббингга дуо қил, унинг қандай эканини баён қилиб берсин», дедилар. У: «У қари ҳам, ёш ҳам бўлмаган, икковининг ўртасидаги сигир, деяпти. Бас, буюрилган нарсани бажаринг», деди.",10,1],["قَالُو[s[اْ] [h:353[ٱ][q:354[دْ]عُ لَنَا رَبَّكَ يُبَيّ[u:355[ِن ل]َّنَا مَا لَوْنُهَا‌ۚ قَالَ إِ[g[نّ]َهُ[n[ۥ] يَقُولُ إِ[g[نّ]َهَا بَقَرَ[f:360[ةٌ ص]َفْر[o[َا]ٓءُ فَاقِ[u:361[عٌ ل]َّوْنُهَا تَسُرُّ [h:362[ٱ][l[ل][g[نّ]َ[n[ـٰ]ظِر[p[ِي]نَ","Улар: «Роббингга дуо қил, унинг рангини баён қилиб берсин», дедилар. У: «У, ранги сап-сариқ, қараганларни хурсанд қиладиган сигир, деяпти», деди.",10,1],["قَالُو[s[اْ] [h:353[ٱ][q:354[دْ]عُ لَنَا رَبَّكَ يُبَيّ[u:355[ِن ل]َّنَا مَا هِىَ إِ[g[نّ]َ [h:363[ٱ]لْبَقَرَ تَشَ[n[ـٰ]بَهَ عَلَيْنَا وَإِ[g[نّ][o[َآ] إِ[f:364[ن ش][o[َا]ٓءَ [h:78[ٱ]للَّهُ لَمُهْتَد[p[ُو]نَ","Улар: «Роббингга дуо қил, унинг қандай эканини бизга баён қилиб берсин, сигир бизга ноаниқ бўлиб қолди, биз, иншааллоҳ, албатта ҳидоят топувчимиз», дедилар.",11,1],["قَالَ إِ[g[نّ]َهُ[n[ۥ] يَقُولُ إِ[g[نّ]َهَا بَقَرَ[u:356[ةٌ ل]َّا ذَلُو[f:365[لٌ ت]ُثِيرُ [h:366[ٱ]لْأَرْضَ وَلَا تَسْقِى [h:367[ٱ]لْحَرْثَ مُسَلَّمَ[u:368[ةٌ ل]َّا شِيَةَ فِيهَا‌ۚ قَالُو[s[اْ] [h:369[ٱ]لْـَٔ[n[ـٰ]نَ جِئْتَ بِ[h:370[ٱ]لْحَقِّ‌ۚ فَذَبَحُوهَا وَمَا كَادُو[s[اْ] يَفْعَل[p[ُو]نَ","У: «У, ўша сигир минилмаган, ер ҳайдаш, экин суғоришда ишлатилмаган, айблардан саломат, аралашган ранги йўқ, деяпти», деди. Улар: «Ана энди ҳақни келтирдинг», дедилар. Бас, уни сўйдилар. Сал бўлмаса, қилмасдилар.",11,1],["وَإِذْ قَتَلْتُمْ نَفْ[f:371[سًا ف]َ[h:372[ٱ]دّ[n[َٲ]رَٲْٔتُمْ فِيهَا‌ۖ وَ[h:72[ٱ]للَّهُ مُخْرِ[a:373[جٌ م]َّا كُ[f:100[نت]ُمْ تَكْتُم[p[ُو]نَ","Бир жонни ўлдириб қўйиб, у ҳақида ихтилофга тушганингизни эсланг. Аллоҳ сиз беркитган нарсани чиқаргувчидир.",11,1],["فَقُلْنَا [h:374[ٱ]ضْرِبُوهُ بِبَعْضِهَا‌ۚ كَذ[n[َٲ]لِكَ يُحْىِ [h:375[ٱ]للَّهُ [h:376[ٱ]لْمَوْتَىٰ وَيُرِيكُمْ ءَايَ[n[ـٰ]تِه[n[ِۦ] لَعَلَّكُمْ تَعْقِل[p[ُو]نَ","«Бас, уни унинг баъзи жойи билан уринг», дедик. Аллоҳ худди шундай қилиб ўликларни тирилтиради ва оят-аломатларини сизга кўрсатади. Шоядки ақл ишлатсангиз.",11,1],["ثُ[g[مّ]َ قَسَتْ قُلُوبُك[w:377[ُم م]ّ[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ فَهِىَ كَ[h:378[ٱ]لْحِجَارَةِ أَوْ أَشَدُّ قَسْوَ[a:379[ةً‌ۚ و]َإِ[g[نّ]َ مِنَ [h:380[ٱ]لْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ [h:381[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۚ وَإِ[g[نّ]َ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ [h:382[ٱ]لْم[o[َا]ٓءُ‌ۚ وَإِ[g[نّ]َ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ [h:383[ٱ]للَّهِ‌ۗ وَمَا [h:384[ٱ]للَّهُ بِغَ[n[ـٰ]فِلٍ عَ[g[مّ]َا تَعْمَل[p[ُو]نَ","Сўнгра, шундан кейин қалбларингиз қаттиқ бўлди, улар тошдек ёки тошдан ҳам қаттиқ. Ва ҳолбуки, тошларнинг баъзиларидан анҳорлар отилиб чиқади, баъзилари ёрилиб ундан сув чиқади ва баъзилари Аллоҳдан қўрққанидан қулаб тушади. Ва Аллоҳ қилаётган ишларингиздан ғофил эмас.",11,1],["۞ أَفَتَ[q:385[طْ]مَعُونَ أ[a:386[َن ي]ُؤْمِنُو[s[اْ] لَكُمْ وَقَ[q:387[دْ] كَانَ فَرِي[a:388[قٌ م]ِّنْهُمْ يَسْمَعُونَ كَلَ[n[ـٰ]مَ [h:389[ٱ]للَّهِ ثُ[g[مّ]َ يُحَرِّفُونَهُ[n[ۥ] م[i:146[ِنۢ ب]َعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَم[p[ُو]نَ","Уларнинг иймон келтиришларини тамаъ қиласизларми? Ва ҳолбуки, улардан бир гуруҳлари Аллоҳнинг каломини эшитар эдилар ва сўнгра уни тушунганларидан кейин билиб туриб бузар эдилар.",11,1],["وَإِذَا لَقُو[s[اْ] [h:50[ٱ]لَّذِينَ ءَامَنُو[s[اْ] قَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْ[f:390[ضٍ ق]َال[o[ُوٓ][s[اْ] أَتُحَدِّثُونَه[c:391[ُم ب]ِمَا فَتَحَ [h:392[ٱ]للَّهُ عَلَيْكُمْ لِيُح[m[َا]ٓجُّوك[c:393[ُم ب]ِه[n[ِۦ] عِ[f:264[ند]َ رَبِّكُمْ‌ۚ أَفَلَا تَعْقِل[p[ُو]نَ","Улар иймон келтирганларни учратсалар, иймон келтирдик, дейдилар. Баъзилари баъзилари билан холи қолсалар: «Уларга Аллоҳ сизга очган нарса ҳақида Роббингиз ҳузурида ҳужжат талашишлари учун гапиряпсизми? Ақлни ишлатмайсизми?» дейдилар.",11,1],["أَوَلَا يَعْلَمُونَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِن[p[ُو]نَ","Аллоҳ уларнинг сир тутгану ва ошкор қилган нарсаларини, албатта, билишини англамайдиларми?",12,1],["وَمِنْهُمْ أُ[g[مّ]ِيُّونَ لَا يَعْلَمُونَ [h:395[ٱ]لْكِتَ[n[ـٰ]بَ إِلّ[o[َآ] أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُ[g[نّ][p[ُو]نَ","Уларнинг ичида китобдан бехабар, хомхаёлдан бошқани билмайдиган омийлар бор. Улар фақат гумон қиладилар халос.",12,1],["فَوَيْ[u:396[لٌ ل]ِّلَّذِينَ يَكْتُبُونَ [h:397[ٱ]لْكِتَ[n[ـٰ]بَ بِأَيْدِيهِمْ ثُ[g[مّ]َ يَقُولُونَ هَ[n[ـٰ]ذَا مِنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ لِيَشْتَرُو[s[اْ] بِه[n[ِۦ] ثَمَ[f:208[نًا ق]َلِيل[f:400[اً‌ۖ ف]َوَيْ[u:401[لٌ ل]َّه[w:402[ُم م]ِّ[g[مّ]َا كَتَبَتْ أَيْدِيهِمْ وَوَيْ[u:403[لٌ ل]َّه[w:402[ُم م]ِّ[g[مّ]َا يَكْسِب[p[ُو]نَ","Китобни ўз қўли билан ёзиб, сўнгра уни арзон баҳога сотиш учун: «Бу Аллоҳнинг ҳузуридан», дейдиганларга ҳалокат бўлсин! Уларга қўллари билан ёзган нарсаларидан ҳалокат бўлсин! Уларга топган фойдаларидан ҳалокат бўлсин!",12,1],["وَقَالُو[s[اْ] لَ[f:404[ن ت]َمَسَّنَا [h:405[ٱ][l[ل][g[نّ]َارُ إِلّ[o[َآ] أَيَّا[a:406[مًا م]َّعْدُودَ[f:407[ةً‌ۚ ق]ُلْ أَتَّخَذْتُمْ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ عَهْ[f:409[دًا ف]َل[a:410[َن ي]ُخْلِفَ [h:411[ٱ]للَّهُ عَهْدَهُ[o[ۥٓ‌ۖ] أَمْ تَقُولُونَ عَلَى [h:412[ٱ]للَّهِ مَا لَا تَعْلَم[p[ُو]نَ","Ва улар: «Бизга ўти ҳеч тегмайди, тегса ҳам саноқли кунларгина тегади», дедилар. Сен: «Аллоҳдан аҳд олдингизми? Зотан, Аллоҳ аҳдига ҳеч хилоф қилмайди. Ёки Аллоҳнинг номидан билмаган нарсангизни гапиряпсизми?» деб айт.",12,1],["بَلَىٰ مَ[f:413[ن ك]َسَبَ سَيِّئَ[a:414[ةً و]َأَحَ[n[ـٰ]طَتْ بِه[n[ِۦ] خَطِ[o[يٓ]ــَٔتُهُ[n[ۥ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Йўқ! Ким гуноҳ қилса ва уни хатолари ўраб олган бўлса, ана ўшалар дўзах эгаларидир. Улар унда абадий қолурлар.",12,1],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:415[ٱ]لْجَ[g[نّ]َةِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Ва иймон келтириб, яхши амалларни қилганлар, ана ўшалар жаннат эгаларидир. Улар унда абадий қолурлар.",12,1],["وَإِذْ أَخَذْنَا مِيثَ[n[ـٰ]قَ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ لَا تَعْبُدُونَ إِلَّا [h:416[ٱ]للَّهَ وَبِ[h:417[ٱ]لْو[n[َٲ]لِدَيْنِ إِحْسَا[a:418[نًا و]َذِى [h:419[ٱ]لْقُرْبَىٰ وَ[h:420[ٱ]لْيَتَ[n[ـٰ]مَىٰ وَ[h:421[ٱ]لْمَسَ[n[ـٰ]كِينِ وَقُولُو[s[اْ] لِل[g[نّ]َاسِ حُسْ[a:422[نًا و]َأَقِيمُو[s[اْ] [h:214[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتُو[s[اْ] [h:215[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ ثُ[g[مّ]َ تَوَلَّيْتُمْ إِلَّا قَلِيل[a:423[اً م]ِّ[f:344[نك]ُمْ وَأَ[f:98[نت][w:424[ُم م]ُّعْرِض[p[ُو]نَ","Бани Исорилдан Аллоҳдан бошқага ибодат этмайсиз, ота-онага, қариндошларга, етимларга, мискинларга яхшилик қиласиз, одамларга яхши гаплар айтинг, намозни қоим қилинг, закот беринг, деб аҳду паймон олганимизни эсланг. Сўнгра озгинангиздан бошқангиз юз ўгириб, ортга қараб кетдингиз.",12,1],["وَإِذْ أَخَذْنَا مِيثَ[n[ـٰ]قَكُمْ لَا تَسْفِكُونَ دِم[o[َا]ٓءَكُمْ وَلَا تُخْرِجُونَ أَ[f:221[نف]ُسَك[w:425[ُم م]ِّ[f:426[ن د]ِيَ[n[ـٰ]رِكُمْ ثُ[g[مّ]َ أَ[q:427[قْ]رَرْتُمْ وَأَ[f:98[نت]ُمْ تَشْهَد[p[ُو]نَ","Сизлардан бир-бирингизнинг қонларингизни тўкмайсиз ва диёрингиздан чиқармайсиз, деб аҳду паймонингизни олганимизни эсланг. Сўнгра гувоҳлик бериб туриб иқрор бўлдингиз.",13,1],["ثُ[g[مّ]َ أَ[f:428[نت]ُمْ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ تَ[q:429[قْ]تُلُونَ أَ[f:221[نف]ُسَكُمْ وَتُخْرِجُونَ فَرِي[a:430[قًا م]ِّ[f:344[نك][w:431[ُم م]ِّ[f:432[ن د]ِيَ[n[ـٰ]رِهِمْ تَظَ[n[ـٰ]هَرُونَ عَلَيْه[c:433[ِم ب]ِ[h:434[ٱ]لْإِثْمِ وَ[h:435[ٱ]لْعُ[q:435[دْ]و[n[َٲ]نِ وَإ[a:436[ِن ي]َأْتُوكُمْ أُسَ[n[ـٰ]رَىٰ تُفَ[n[ـٰ]دُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ‌ۚ أَفَتُؤْمِنُونَ بِبَعْضِ [h:437[ٱ]لْكِتَ[n[ـٰ]بِ وَتَكْفُرُونَ بِبَعْ[f:438[ضٍ‌ۚ ف]َمَا جَز[o[َا]ٓءُ م[a:439[َن ي]َفْعَلُ ذ[n[َٲ]لِكَ مِ[f:344[نك]ُمْ إِلَّا خِزْ[f:440[ىٌ ف]ِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۖ وَيَوْمَ [h:443[ٱ]لْقِيَ[n[ـٰ]مَةِ يُرَدُّونَ إِلَ[o[ىٰٓ] أَشَدِّ [h:444[ٱ]لْعَذَابِ‌ۗ وَمَا [h:384[ٱ]للَّهُ بِغَ[n[ـٰ]فِلٍ عَ[g[مّ]َا تَعْمَل[p[ُو]نَ","Сўнгра сиз ўзингизни ўзингиз ўлдирасиз ва бир гуруҳингизни диёридан чиқарасиз ҳамда уларга қарши гуноҳ ва душманлик йўлида ёрдам берасиз. Агар улар асир бўлсалар, қутқариб оласиз. Ва ҳолбуки, уларни чиқариш ҳаром эди. Ёки китобнинг баъзисига иймон келтириб, баъзисига куфр келтирасизми?! Сизлардан ўшани қилганларнинг жазоси бу дунёда фақат расво бўлишликдир, қиёмат кунида эса, энг шиддатли азобга қайтарилурлар. Аллоҳ қилаётганингиздан ғофил эмас.",13,1],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ [h:52[ٱ]شْتَرَوُ[s[اْ] [h:445[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَا بِ[h:447[ٱ]لْأَخِرَةِ‌ۖ فَلَا يُخَفَّفُ عَنْهُمُ [h:448[ٱ]لْعَذَابُ وَلَا هُمْ يُ[f:237[نص]َر[p[ُو]نَ","Ана ўшалар дунё ҳаётини охиратга сотиб олганлардир. Улардан азоб енгиллатилмас ва уларга ёрдам ҳам берилмас.",13,1],["وَلَقَ[q:341[دْ] ءَاتَيْنَا مُوسَى [h:257[ٱ]لْكِتَ[n[ـٰ]بَ وَقَفَّيْنَا م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] بِ[h:449[ٱ][l[ل]رُّسُلِ‌ۖ وَءَاتَيْنَا عِيسَى [h:450[ٱ][q:451[بْ]نَ مَرْيَمَ [h:452[ٱ]لْبَيِّنَ[n[ـٰ]تِ وَأَيَّ[q:453[دْ]نَ[n[ـٰ]هُ بِرُوحِ [h:454[ٱ]لْقُدُسِ‌ۗ أَفَكُلَّمَا ج[o[َا]ٓءَكُمْ رَسُو[i:455[لُۢ ب]ِمَا لَا تَهْوَ[o[ىٰٓ] أَ[f:456[نف]ُسُكُمُ [h:457[ٱ]سْتَكْبَرْتُمْ فَفَرِي[f:458[قًا ك]َذَّ[q:459[بْ]تُمْ وَفَرِي[f:460[قًا ت]َ[q:429[قْ]تُل[p[ُو]نَ","Ва батаҳқиқ, Мусога китобни бердик ва унинг ортидан Пайғамбарларни кетма-кет юбордик. Ва Ийсо ибн Марямга равшан ни бердик ва уни руҳул қудс билан қўлладик. Ҳар қачон Пайғамбар сизнинг ҳавою нафсингизга ёқмайдиган нарса келтирса, мутакаббирлик қилиб, баъзиларини ёлғончига чиқариб, баъзиларини ўлдираверасизми?!",13,1],["وَقَالُو[s[اْ] قُلُوبُنَا غُلْ[i:461[فُۢ‌ۚ ب]َل لَّعَنَهُمُ [h:462[ٱ]للَّهُ بِكُفْرِهِمْ فَقَلِيل[a:463[اً م]َّا يُؤْمِن[p[ُو]نَ","Ва улар: «Қалбимиз ғилофланган», дейишади. Йўқ, ундай эмас, куфрлари сабабли Аллоҳ уларни лаънатлаган. Бас, озгинагина иймон келтирадилар.",13,1],["وَلَ[g[مّ]َا ج[o[َا]ٓءَهُمْ كِتَ[n[ـٰ][a:464[بٌ م]ِّنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ مُصَدِّ[u:465[قٌ ل]ِّمَا مَعَهُمْ وَكَانُو[s[اْ] مِ[f:128[ن ق]َ[q:129[بْ]لُ يَسْتَفْتِحُونَ عَلَى [h:289[ٱ]لَّذِينَ كَفَرُو[s[اْ] فَلَ[g[مّ]َا ج[o[َا]ٓءَه[w:466[ُم م]َّا عَرَفُو[s[اْ] كَفَرُو[s[اْ] بِه[n[ِۦ]‌ۚ فَلَعْنَةُ [h:467[ٱ]للَّهِ عَلَى [h:468[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Уларга Аллоҳнинг ҳузуридан ўзларидаги нарсани тасдиқловчи китоб келганда, ва ҳолбуки, кофирларга қарши ёрдам кутардилар, ўзлари билган нарса келганда, унга куфр келтирдилар. Кофирларга Аллоҳнинг лаънати бўлсин.",14,1],["بِئْسَمَا [h:469[ٱ]شْتَرَوْ[s[اْ] بِه[o[ِۦٓ] أَ[f:38[نف]ُسَهُمْ أ[a:470[َن ي]َكْفُرُو[s[اْ] بِم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ بَغْيًا أ[a:473[َن ي]ُنَزِّلَ [h:474[ٱ]للَّهُ مِ[f:475[ن ف]َضْلِه[n[ِۦ] عَلَىٰ م[a:476[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[n[ِۦ]‌ۖ فَب[o[َا]ٓءُو بِغَضَبٍ عَلَىٰ غَضَ[a:477[بٍ‌ۚ و]َلِلْكَ[n[ـٰ]فِرِينَ عَذَا[a:478[بٌ م]ُّه[p[ِي]نٌ","Улар ўзларини сотган нарса, Аллоҳ бандаларидан хоҳлаганига Ўз фазлидан туширганига ҳасад қилиб, Аллоҳ туширган нарсага куфр келтирмоқлик, қандоқ ҳам ёмон. Улар ғазабнинг устига ғазабни лозим тутдилар. Кофирларга хор қилувчи азоб бордир.",14,1],["وَإِذَا قِيلَ لَهُمْ ءَامِنُو[s[اْ] بِم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ قَالُو[s[اْ] نُؤْمِنُ بِم[o[َآ] أُ[f:17[نز]ِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَر[o[َا]ٓءَهُ[n[ۥ] وَهُوَ [h:479[ٱ]لْحَقُّ مُصَدِّ[u:206[قًا ل]ِّمَا مَعَهُمْ‌ۗ قُلْ فَلِمَ تَ[q:429[قْ]تُلُونَ أَ[i:480[نۢب]ِي[o[َا]ٓءَ [h:481[ٱ]للَّهِ مِ[f:128[ن ق]َ[q:129[بْ]لُ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Агар уларга: «Аллоҳ туширган нарсага иймон келтиринг», дейилса, «Бизга туширилган нарсага иймон келтирамиз», дейишади. Ва ундан кейинги нарсага куфр келтиришади. Ҳолбуки, у улардаги нарсани тасдиқловчи ҳақдир. Айт: «Агар мўмин бўлсангиз, нимага илгари Аллоҳнинг Пайғамбарларини ўлдирдингиз?!»",14,1],["۞ وَلَقَ[q:341[دْ] ج[o[َا]ٓءَك[w:483[ُم م]ُّوسَىٰ بِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ ثُ[g[مّ]َ [h:251[ٱ]تَّخَذْتُمُ [h:252[ٱ]لْعِ[q:253[جْ]لَ م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] وَأَ[f:98[نت]ُمْ ظَ[n[ـٰ]لِم[p[ُو]نَ","Ва батаҳқиқ, Мусо сизларга равшан лар ила келди. Сўнгра сиз ундан кейин золим бўлган ҳолингизда бузоқни тутдингиз.",14,1],["وَإِذْ أَخَذْنَا مِيثَ[n[ـٰ]قَكُمْ وَرَفَعْنَا فَوْقَكُمُ [h:332[ٱ][l[ل]طُّورَ خُذُو[s[اْ] م[o[َآ] ءَاتَيْنَ[n[ـٰ]ك[c:333[ُم ب]ِقُوَّ[a:485[ةٍ و]َ[h:486[ٱ]سْمَعُو[s[اْ‌ۖ] قَالُو[s[اْ] سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُو[s[اْ] فِى قُلُوبِهِمُ [h:487[ٱ]لْعِ[q:253[جْ]لَ بِكُفْرِهِمْ‌ۚ قُلْ بِئْسَمَا يَأْمُرُك[c:488[ُم ب]ِه[o[ِۦٓ] إِيمَ[n[ـٰ]نُكُمْ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Сиздан аҳду паймонингизни олиб, устингизга Турни кўтариб: «Сизга Биз берган нарсани қувват билан тутинг ва тингланг», деганимизни эсланг. Улар: «Тингладик ва исён қилдик», дедилар. Куфрлари сабабли қалбларига бузоқ ўрнаштирилди. Айт: «Агар мўмин бўлсангиз сизнинг иймонингиз қандай ҳам ёмон нарсага буюради!»",14,1],["قُلْ إِ[f:489[ن ك]َانَتْ لَكُمُ [h:490[ٱ][l[ل]دَّارُ [h:491[ٱ]لْأَخِرَةُ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ خَالِصَ[a:492[ةً م]ِّ[f:107[ن د]ُونِ [h:493[ٱ][l[ل][g[نّ]َاسِ فَتَمَ[g[نّ]َوُ[s[اْ] [h:494[ٱ]لْمَوْتَ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Айт: «Агар Аллоҳнинг ҳузуридаги охират ҳовлиси бошқа одамларсиз холис сизга бўладиган бўлса, гапингизда ростгўй бўлсангиз, ўлимни орзу қилинг».",15,1],["وَل[a:495[َن ي]َتَمَ[g[نّ]َوْهُ أَبَد[i:496[َۢا ب]ِمَا قَدَّمَتْ أَيْدِيهِمْ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِي[i:497[مُۢ ب]ِ[h:498[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Улар қўллари тақдим қилган нарсалар сабабидан, уни абадий, ҳеч-ҳеч орзу қилмаслар ва Аллоҳ зулм қилувчиларни билувчи зотдир.",15,1],["وَلَتَجِدَ[g[نّ]َهُمْ أَحْرَصَ [h:499[ٱ][l[ل][g[نّ]َاسِ عَلَىٰ حَيَ[s[و][n[ٲ][a:500[ةٍ و]َمِنَ [h:501[ٱ]لَّذِينَ أَشْرَكُو[s[اْ‌ۚ] يَوَدُّ أَحَدُهُمْ لَوْ يُعَ[g[مّ]َرُ أَلْفَ سَنَ[a:502[ةٍ و]َمَا هُوَ بِمُزَحْزِحِه[n[ِۦ] مِنَ [h:503[ٱ]لْعَذَابِ أ[a:504[َن ي]ُعَ[g[مّ]َرَ‌ۗ وَ[h:72[ٱ]للَّهُ بَصِي[i:505[رُۢ ب]ِمَا يَعْمَل[p[ُو]نَ","Уларнинг ҳаётга энг ҳирс қўйган одамлар эканлигини биласан. Мушриклардан бирлари минг йил умр кўришни суяди. Аммо узоқ умр кўриши уни азобдан қутқармайди. Ва Аллоҳ уларнинг қилаётганларини кўрувчидир.",15,1],["قُلْ مَ[f:506[ن ك]َانَ عَدُو[u:507[ًّا ل]ِّجِ[q:508[بْ]رِيلَ فَإِ[g[نّ]َهُ[n[ۥ] نَزَّلَهُ[n[ۥ] عَلَىٰ قَلْبِكَ بِإِذْنِ [h:509[ٱ]للَّهِ مُصَدِّ[u:206[قًا ل]ِّمَا بَيْنَ يَدَيْهِ وَهُ[a:510[دًى و]َبُشْرَىٰ لِلْمُؤْمِن[p[ِي]نَ","Жиброилга душман бўлганларга айт, албатта уни сенинг қалбингга Аллоҳнинг изни билан, ўзидан олдингини тасдиқловчи ва мўминлар учун ҳидоят ва башорат қилиб туширди.",15,1],["مَ[f:506[ن ك]َانَ عَدُو[u:511[ًّا ل]ِّلَّهِ وَمَلَ[o[ـٰٓ]ئِكَتِه[n[ِۦ] وَرُسُلِه[n[ِۦ] وَجِ[q:512[بْ]رِيلَ وَمِيكَ[n[ـٰ]لَ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ عَدُ[u:514[وٌّ ل]ِّلْكَ[n[ـٰ]فِر[p[ِي]نَ","Ким Аллоҳга, унинг фаришталарига, Пайғамбарларига, Жиброилга ва Микоилга душман бўлса, албатта, Аллоҳ кофирларнинг душманидир.",15,1],["وَلَقَ[q:341[دْ] أَ[f:515[نز]َلْن[o[َآ] إِلَيْكَ ءَايَ[n[ـٰ][i:516[تِۭ ب]َيِّنَ[n[ـٰ][a:517[تٍ‌ۖ و]َمَا يَكْفُرُ بِه[o[َآ] إِلَّا [h:518[ٱ]لْفَ[n[ـٰ]سِق[p[ُو]نَ","Батаҳқиқ, сенга равшан оятларни туширдик, уларга фақат фосиқларгина куфр келтирадир.",15,1],["أَوَكُلَّمَا عَ[n[ـٰ]هَدُو[s[اْ] عَهْ[a:519[دًا ن]َّبَذَهُ[n[ۥ] فَرِي[a:388[قٌ م]ِّنْه[c:520[ُم‌ۚ ب]َلْ أَكْثَرُهُمْ لَا يُؤْمِن[p[ُو]نَ","Ҳар қачон аҳд қилишсалар, улардан бир гуруҳи уни бузаверадими?! Йўқ! Уларнинг кўплари иймон келтирмаслар.",15,1],["وَلَ[g[مّ]َا ج[o[َا]ٓءَهُمْ رَسُو[a:521[لٌ م]ِّنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ مُصَدِّ[u:465[قٌ ل]ِّمَا مَعَهُمْ نَبَذَ فَرِي[a:522[قٌ م]ِّنَ [h:523[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ كِتَ[n[ـٰ]بَ [h:525[ٱ]للَّهِ وَر[o[َا]ٓءَ ظُهُورِهِمْ كَأَ[g[نّ]َهُمْ لَا يَعْلَم[p[ُو]نَ","Улардаги нарсани тасдиқлаб, Аллоҳнинг ҳузуридан уларга Пайғамбар келса, китоб берилганлардан бир гуруҳи, худди билмагандек, Аллоҳнинг китобини ортларига қараб отдилар.",15,1],["وَ[h:9999[ٱ]تَّبَعُو[s[اْ] مَا تَتْلُو[s[اْ] [h:526[ٱ][l[ل]شَّيَ[n[ـٰ]طِينُ عَلَىٰ مُلْكِ سُلَيْمَ[n[ـٰ]نَ‌ۖ وَمَا كَفَرَ سُلَيْمَ[n[ـٰ]نُ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:527[ٱ][l[ل]شَّيَ[n[ـٰ]طِينَ كَفَرُو[s[اْ] يُعَلِّمُونَ [h:528[ٱ][l[ل][g[نّ]َاسَ [h:529[ٱ][l[ل]سِّحْرَ وَم[o[َآ] أُ[f:17[نز]ِلَ عَلَى [h:530[ٱ]لْمَلَكَيْنِ بِبَابِلَ هَ[n[ـٰ]رُوتَ وَمَ[n[ـٰ]رُوتَ‌ۚ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُول[o[َآ] إِ[g[نّ]َمَا نَحْنُ فِتْنَ[f:531[ةٌ ف]َلَا تَكْفُرْ‌ۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِه[n[ِۦ] بَيْنَ [h:532[ٱ]لْمَرْءِ وَزَوْجِه[n[ِۦ]‌ۚ وَمَا ه[c:533[ُم ب]ِض[m[َا]ٓرِّينَ بِه[n[ِۦ] مِنْ أَحَدٍ إِلَّا بِإِذْنِ [h:509[ٱ]للَّهِ‌ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَ[f:534[نف]َعُهُمْ‌ۚ وَلَقَ[q:341[دْ] عَلِمُو[s[اْ] لَمَنِ [h:535[ٱ]شْتَرَ[n[ٮٰ]هُ مَا لَهُ[n[ۥ] فِى [h:536[ٱ]لْأَخِرَةِ مِنْ خَلَ[n[ـٰ][a:537[قٍ‌ۚ و]َلَبِئْسَ مَا شَرَوْ[s[اْ] بِه[o[ِۦٓ] أَ[f:38[نف]ُسَهُمْ‌ۚ لَوْ كَانُو[s[اْ] يَعْلَم[p[ُو]نَ","Ва Сулаймон подшолигида шайтонлар тиловат қилган нарсага эргашдилар. Сулаймон куфр келтиргани йўқ. Лекин шайтонлар одамларга сеҳрни ўргатиб, кофир бўлдилар. Ва Бобилда Ҳорут ва Морут номли икки фариштага тушган нарсага эргашдилар. Икковлари ҳатто: «Биз фитна-синов учунмиз, кофир бўлмагин», демасдан олдин ҳеч кимга ўргатмасдилар. Бас, икковларидан эр-хотиннинг ўртасини бузадиган нарсани ўрганишар эди. Ва улар Аллоҳнинг изнисиз бирор кишига зарар етказувчи эмасдилар. Ва икковларидан зарар келтирадиган, фойда келтирмайдиган нарсани ўрганадилар. Ва, батаҳқиқ, биладиларки, уни сотиб олган кишига охиратда насиба йўқ. Агар билсалар, ўзларини сотган нарса қандоқ ҳам ёмон!",16,1],["وَلَوْ أَ[g[نّ]َهُمْ ءَامَنُو[s[اْ] وَ[h:538[ٱ]تَّقَوْ[s[اْ] لَمَثُوبَ[a:539[ةٌ م]ِّنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ خَيْ[u:540[رٌ‌ۖ ل]َّوْ كَانُو[s[اْ] يَعْلَم[p[ُو]نَ","Агар улар иймон келтириб, тақво қилганларида, гар билсалар, Аллоҳнинг ҳузуридаги савоб яхши эди.",16,1],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَقُولُو[s[اْ] ر[n[َٲ]عِنَا وَقُولُو[s[اْ] [h:542[ٱ][f:543[نظ]ُرْنَا وَ[h:486[ٱ]سْمَعُو[s[اْ‌ۗ] وَلِلْكَ[n[ـٰ]فِرِينَ عَذَابٌ أَل[p[ِي]مٌ","Эй иймон келтирганлар! «Роъина» деманглар, «унзурна» денглар ва тингланглар. Ва кофирларга аламли азоб бўлур.",16,1],["مَّا يَوَدُّ [h:544[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ وَلَا [h:546[ٱ]لْمُشْرِكِينَ أ[a:547[َن ي]ُنَزَّلَ عَلَيْك[w:548[ُم م]ِّنْ خَيْ[a:549[رٍ م]ّ[u:243[ِن ر]َّبِّكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ يَخْتَصُّ بِرَحْمَتِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَ[h:72[ٱ]للَّهُ ذُو [h:550[ٱ]لْفَضْلِ [h:551[ٱ]لْعَظ[p[ِي]مِ","Аҳли китоб ва мушриклардан бўлган кофирлар сизларга Роббингиздан яхшилик туширилишини ёқтирмайдилар. Ва ҳолбуки, Аллоҳ Ўз раҳматини кимга хоҳласа, ўшанга хос қилади. Аллоҳ улуғ фазл эгасидир.",16,1],["۞ مَا نَ[f:552[نس]َخْ مِنْ ءَايَةٍ أَوْ نُ[f:553[نس]ِهَا نَأْتِ بِخَيْ[a:554[رٍ م]ِّنْه[o[َآ] أَوْ مِثْلِه[o[َآ‌ۗ] أَلَمْ تَعْلَمْ أَ[g[نّ]َ [h:394[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Оятлардан биронтасини насх қилсак ёки унутдирсак, ундан яхшисини ёки унга ўхшашини келтирамиз. Аллоҳ ҳар нарсага қодир эканини билмадингми?",17,1],["أَلَمْ تَعْلَمْ أَ[g[نّ]َ [h:394[ٱ]للَّهَ لَهُ[n[ۥ] مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۗ وَمَا لَك[w:556[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ م[a:557[ِن و]َلِ[a:558[ىٍّ و]َلَا نَص[p[ِي]رٍ","Албатта, осмонлару ернинг мулки Аллоҳники эканини ва сизларга Аллоҳдан ўзга дўст йўқ, ёрдамчи ҳам йўқлигини билмадингми?",17,1],["أَمْ تُرِيدُونَ أَ[f:559[ن ت]َسْــَٔلُو[s[اْ] رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۗ وَم[a:560[َن ي]َتَبَدَّلِ [h:561[ٱ]لْكُفْرَ بِ[h:562[ٱ]لْإِيمَ[n[ـٰ]نِ فَقَ[q:563[دْ] ضَلَّ سَو[o[َا]ٓءَ [h:564[ٱ][l[ل]سَّب[p[ِي]لِ","Ёки Пайғамбарингиздан, бундан аввал Мусодан сўралганидек, савол сўрашни хоҳлайсизми?! Ким иймонни куфрга алмаштирса, батаҳқиқ, тўғри йўлдан адашган бўлади.",17,1],["وَدَّ كَثِي[a:565[رٌ م]ِّنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ لَوْ يَرُدُّونَك[w:566[ُم م]ّ[i:146[ِنۢ ب]َعْدِ إِيمَ[n[ـٰ]نِكُمْ كُفَّارًا حَسَ[a:567[دًا م]ِّنْ عِ[f:398[ند]ِ أَ[f:568[نف]ُسِه[w:569[ِم م]ّ[i:146[ِنۢ ب]َعْدِ مَا تَبَيَّنَ لَهُمُ [h:570[ٱ]لْحَقُّ‌ۖ فَ[h:571[ٱ]عْفُو[s[اْ] وَ[h:572[ٱ]صْفَحُو[s[اْ] حَتَّىٰ يَأْتِىَ [h:573[ٱ]للَّهُ بِأَمْرِه[o[ِۦٓ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Аҳли китоблардан кўплари уларга ҳақ равшан бўлганидан кейин, ўзларича ҳасад қилиб, сизларни иймонли бўлганингиздан кейин кофирликка қайтармоқчи бўладилар. Аллоҳнинг амри келгунча афв этинг, кечиримли бўлинг. Албатта, Аллоҳ ҳар бир нарсага қодирдир.",17,1],["وَأَقِيمُو[s[اْ] [h:214[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتُو[s[اْ] [h:215[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ‌ۚ وَمَا تُقَدِّمُو[s[اْ] لِأَ[f:574[نف]ُسِك[w:575[ُم م]ِّنْ خَيْ[f:576[رٍ ت]َجِدُوهُ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","Намозни қоим қилинг, закот беринг, ўзингиз учун қилган яхшиликларни Аллоҳнинг ҳузурида топасиз. Албатта, Аллоҳ қилаётганингизни кўрувчидир.",17,1],["وَقَالُو[s[اْ] ل[a:577[َن ي]َ[q:578[دْ]خُلَ [h:579[ٱ]لْجَ[g[نّ]َةَ إِلَّا مَ[f:506[ن ك]َانَ هُودًا أَوْ نَصَ[n[ـٰ]رَىٰ‌ۗ تِلْكَ أَمَانِيُّهُمْ‌ۗ قُلْ هَاتُو[s[اْ] بُرْهَ[n[ـٰ]نَكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Ва улар: «Жаннатга яҳудий ва насронийлардан бошқа ҳеч ким кирмайди», дедилар. Бу уларнинг хом хаёлларидир. «Агар ростгўй бўлсангиз, ҳужжатингизни келтиринг», деб айт.",17,1],["بَلَىٰ مَنْ أَسْلَمَ وَ[q:580[جْ]هَهُ[n[ۥ] لِلَّهِ وَهُوَ مُحْسِ[f:581[نٌ ف]َلَهُ[o[ۥٓ] أَ[q:582[جْ]رُهُ[n[ۥ] عِ[f:264[ند]َ رَبِّه[n[ِۦ] وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Йўқ! Кимки яхшилик қилган ҳолида юзини Аллоҳга топширса, унга Робби ҳузурида ажр бордир. Уларга хавф йўқ ва улар хафа ҳам бўлмаслар.",17,1],["وَقَالَتِ [h:583[ٱ]لْيَهُودُ لَيْسَتِ [h:584[ٱ][l[ل][g[نّ]َصَ[n[ـٰ]رَىٰ عَلَىٰ ش[a:585[َىْءٍ و]َقَالَتِ [h:586[ٱ][l[ل][g[نّ]َصَ[n[ـٰ]رَىٰ لَيْسَتِ [h:587[ٱ]لْيَهُودُ عَلَىٰ ش[a:588[َىْءٍ و]َهُمْ يَتْلُونَ [h:589[ٱ]لْكِتَ[n[ـٰ]بَ‌ۗ كَذ[n[َٲ]لِكَ قَالَ [h:590[ٱ]لَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ‌ۚ فَ[h:591[ٱ]للَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ فِيمَا كَانُو[s[اْ] فِيهِ يَخْتَلِف[p[ُو]نَ","Яҳудийлар: «Насронийлар арзимас нарсададирлар», дедилар. Насронийлар: «Яҳудийлар арзимас нарсададирлар», дедилар. Ва ҳолбуки, улар китоб тиловат қиладилар. Шунингдек, билмайдиган кимсалар ҳам уларнинг гапига ўхшаш гап айтдилар. Бас, қиёмат куни ораларида Аллоҳ улар ихтилоф қилган нарса ҳақида ҳакамлик қилади.",18,1],["وَمَنْ أَظْلَمُ مِ[g[مّ][a:593[َن م]َّنَعَ مَسَ[n[ـٰ]جِدَ [h:594[ٱ]للَّهِ أ[a:595[َن ي]ُذْكَرَ فِيهَا [h:596[ٱ]سْمُهُ[n[ۥ] وَسَعَىٰ فِى خَرَابِه[o[َآ‌ۚ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مَا كَانَ لَهُمْ أ[a:597[َن ي]َ[q:598[دْ]خُلُوه[o[َآ] إِلَّا خ[o[َا]ٓئِفِينَ‌ۚ لَهُمْ فِى [h:599[ٱ][l[ل]دُّنْيَا خِزْ[a:600[ىٌ و]َلَهُمْ فِى [h:536[ٱ]لْأَخِرَةِ عَذَابٌ عَظ[p[ِي]مٌ","Аллоҳнинг масжидларида Унинг исми зикр қилинишини ман этган ва уларни бузишга ҳаракат қилгандан ҳам золимроқ одам борми? Ана ўшалар у жойларга фақат қўрққан ҳолларидагина киришлари керак эди-ку! Уларга бу дунёда хорлик бордир ва уларга охиратда улуғ азоб бордир.",18,1],["وَلِلَّهِ [h:601[ٱ]لْمَشْرِقُ وَ[h:602[ٱ]لْمَغْرِبُ‌ۚ فَأَيْنَمَا تُوَلُّو[s[اْ] فَثَ[g[مّ]َ وَ[q:603[جْ]هُ [h:604[ٱ]للَّهِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ و[n[َٲ]سِعٌ عَل[p[ِي]مٌ","Машриқу мағриб Аллоҳникидир, қаёққа қарасангиз, Аллоҳнинг юзи бор. Албатта, Аллоҳ кенг қамровли, билувчи зотдир.",18,1],["وَقَالُو[s[اْ] [h:605[ٱ]تَّخَذَ [h:606[ٱ]للَّهُ وَلَ[f:607[دًا‌ۗ س]ُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ]‌ۖ بَل لَّهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ كُ[u:610[لٌّ ل]َّهُ[n[ۥ] قَ[n[ـٰ]نِت[p[ُو]نَ","Улар: «Аллоҳ ўзига фарзанд тутди», дейдилар. У покдир. Балки осмонлару ердаги барча нарсалар Уникидир. Ҳамма Унга бўйсунувчидир.",18,1],["بَدِيعُ [h:611[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ وَإِذَا قَضَ[o[ىٰٓ] أَمْ[f:612[رًا ف]َإِ[g[نّ]َمَا يَقُولُ لَهُ[n[ۥ] كُ[f:613[ن ف]َيَك[p[ُو]نُ","У осмонлару ерни пайдо қилувчидир. Бирор ишни қилмоқчи бўлганида, унга: «Бўл!» деса, бўлаверадир.",18,1],["وَقَالَ [h:614[ٱ]لَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا [h:615[ٱ]للَّهُ أَوْ تَأْتِين[o[َآ] ءَايَ[f:616[ةٌ‌ۗ ك]َذ[n[َٲ]لِكَ قَالَ [h:590[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِه[w:619[ِم م]ِّثْلَ قَوْلِهِمْ‌ۘ تَشَ[n[ـٰ]بَهَتْ قُلُوبُهُمْ‌ۗ قَ[q:298[دْ] بَيَّ[g[نّ]َا [h:620[ٱ]لْأَيَ[n[ـٰ]تِ لِقَوْ[a:621[مٍ ي]ُوقِن[p[ُو]نَ","Билмайдиган кимсалар: «Аллоҳ биз билан гаплашса эди ёки мўъжиза келса эди», дейишди. Улардан олдингилар ҳам уларнинг сўзига ўхшаш гапирган эдилар. Қалблари ўхшаш бўлди. Батаҳқиқ, Биз яхши билувчи қавмларга мўъжизаларни баён қилганмиз.",18,1],["إِ[g[نّ][o[َآ] أَرْسَلْنَ[n[ـٰ]كَ بِ[h:370[ٱ]لْحَقِّ بَشِي[a:622[رًا و]َنَذِي[a:623[رًا‌ۖ و]َلَا تُسْــَٔلُ عَنْ أَصْحَ[n[ـٰ]بِ [h:624[ٱ]لْجَح[p[ِي]مِ","Албатта, Биз сени ҳақ билан суюнчли хабар берувчи ва огоҳлантирувчи қилиб юбордик. Ва дўзахилар ҳақида сўралмайсан.",18,1],["وَلَ[f:625[ن ت]َرْضَىٰ عَ[f:626[نك]َ [h:627[ٱ]لْيَهُودُ وَلَا [h:628[ٱ][l[ل][g[نّ]َصَ[n[ـٰ]رَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ‌ۗ قُلْ إِ[g[نّ]َ هُدَى [h:629[ٱ]للَّهِ هُوَ [h:630[ٱ]لْهُدَىٰ‌ۗ وَلَئِنِ [h:631[ٱ]تَّبَعْتَ أَهْو[o[َا]ٓءَه[c:632[ُم ب]َعْدَ [h:633[ٱ]لَّذِى ج[o[َا]ٓءَكَ مِنَ [h:634[ٱ]لْعِلْمِ‌ۙ مَا لَكَ مِنَ [h:321[ٱ]للَّهِ م[a:557[ِن و]َلِ[a:558[ىٍّ و]َلَا نَص[p[ِي]رٍ","Сендан яҳудийлар ҳам, насронийлар ҳам уларнинг миллатига эргашмагунингча ҳеч-ҳеч рози бўлмаслар. «Албатта, Аллоҳнинг ҳидояти ҳақиқий ҳидоятдир», деб айт. Агар сенга келган илмдан кейин ҳам уларнинг ҳавои нафсларига эргашсанг, сени Аллоҳдан дўст ҳам, ёрдамчи ҳам йўқдир.",19,1],["ٱلَّذِينَ ءَاتَيْنَ[n[ـٰ]هُمُ [h:635[ٱ]لْكِتَ[n[ـٰ]بَ يَتْلُونَهُ[n[ۥ] حَقَّ تِلَاوَتِه[o[ِۦٓ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يُؤْمِنُونَ بِه[n[ِۦ]‌ۗ وَم[a:636[َن ي]َكْفُرْ بِه[n[ِۦ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:150[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","Биз китоб берганлардан уни ўрнига қўйиб тиловат қиладиганлари, ана ўшалари унга иймон келтиради. Ким унга куфр келтирса, ана ўшалар, ўзларигина ютқазганлардир.",19,1],["يَ[n[ـٰ]بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ [h:202[ٱ]ذْكُرُو[s[اْ] نِعْمَتِىَ [h:203[ٱ]لَّت[o[ِىٓ] أَنْعَمْتُ عَلَيْكُمْ وَأَ[g[نّ]ِى فَضَّلْتُكُمْ عَلَى [h:227[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Эй Бани Исроил, сизга берган неъматларимни ва Мен сизларни оламлардан афзал қилиб қўйганимни эсланг!",19,1],["وَ[h:9999[ٱ]تَّقُو[s[اْ] يَوْ[u:228[مًا ل]َّا تَ[q:229[جْ]زِى نَفْسٌ ع[a:230[َن ن]َّفْ[f:231[سٍ ش]َيْـ[a:232[ـًٔا و]َلَا يُ[q:233[قْ]بَلُ مِنْهَا عَ[q:235[دْ][a:236[لٌ و]َلَا تَ[f:637[نف]َعُهَا شَفَ[n[ـٰ]عَ[a:234[ةٌ و]َلَا هُمْ يُ[f:237[نص]َر[p[ُو]نَ","Бир жон бошқа жондан ҳеч нарсани адо қила олмайдиган, ундан шафоат қабул қилинмайдиган, ундан тўлов олинмайдиган ва уларга ёрдам берилмайдиган Кундан қўрқинг!",19,1],["۞ وَإِذِ [h:638[ٱ][q:639[بْ]تَلَ[o[ىٰٓ] إِ[q:640[بْ]ر[n[َٲ]هِـ[n[ـۧ]مَ رَبُّهُ[n[ۥ] بِكَلِمَ[n[ـٰ][f:641[تٍ ف]َأَتَ[g[مّ]َهُ[g[نّ]َ‌ۖ قَالَ إِ[g[نّ]ِى جَاعِلُكَ لِل[g[نّ]َاسِ إِمَا[f:642[مًا‌ۖ ق]َالَ وَمِ[f:643[ن ذ]ُرِّيَّتِى‌ۖ قَالَ لَا يَنَالُ عَهْدِى [h:644[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Иброҳимни Роббиси калималар ила синаб кўрганда, у уларни батамом адо этганини эсла! У зот: «Мен, албатта, сени одамларга имом қилмоқчиман» деди. У: «Зурриётимдан ҳамми?» деди. У зот: «Золимлар аҳдимга ҳеч қачон эриша олмайдилар», деди.",19,1],["وَإِذْ جَعَلْنَا [h:645[ٱ]لْبَيْتَ مَثَابَ[u:646[ةً ل]ِّل[g[نّ]َاسِ وَأَمْ[a:647[نًا و]َ[h:648[ٱ]تَّخِذُو[s[اْ] م[a:649[ِن م]َّقَامِ إِ[q:640[بْ]ر[n[َٲ]هِـ[n[ـۧ]مَ مُصَل[a:650[ًّى‌ۖ و]َعَهِ[q:651[دْ]ن[o[َآ] إِلَ[o[ىٰٓ] إِ[q:640[بْ]ر[n[َٲ]هِـ[n[ـۧ]مَ وَإِسْمَ[n[ـٰ]عِيلَ أَ[f:652[ن ط]َهِّرَا بَيْتِىَ لِلطّ[o[َا]ٓئِفِينَ وَ[h:653[ٱ]لْعَ[n[ـٰ]كِفِينَ وَ[h:654[ٱ][l[ل]رُّكَّعِ [h:655[ٱ][l[ل]سُّج[p[ُو][q[د]ِ","«Уй»ни одамлар учун масаба ва омонлик жойи қилганимизни эсланг. Ва Иброҳимнинг мақомини намозгоҳ тутинг. Ва Иброҳим ва Исмоилга: «Уйимни тавоф қилувчилар, муқим турувчилар, рукуъ ва сажда қилувчилар учун поклаб қўйинглар», деб амр қилдик.",19,1],["وَإِذْ قَالَ إِ[q:656[بْ]ر[n[َٲ]هِـ[n[ـۧ]مُ رَبِّ [h:657[ٱ][q:658[جْ]عَلْ هَ[n[ـٰ]ذَا بَلَدًا ءَامِ[a:659[نًا و]َ[h:660[ٱ]رْزُ[q:660[قْ] أَهْلَهُ[n[ۥ] مِنَ [h:93[ٱ][l[ل]ثَّمَر[n[َٲ]تِ مَنْ ءَامَنَ مِنْه[c:661[ُم ب]ِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ‌ۖ قَالَ وَمَ[f:662[ن ك]َفَرَ فَأُمَتِّعُهُ[n[ۥ] قَلِيل[f:663[اً ث]ُ[g[مّ]َ أَضْطَرُّهُ[o[ۥٓ] إِلَىٰ عَذَابِ [h:664[ٱ][l[ل][g[نّ]َارِ‌ۖ وَبِئْسَ [h:665[ٱ]لْمَص[p[ِي]رُ","Иброҳимнинг: «Роббим, буни омонлик юрти қилгин ва аҳлидан Аллоҳга ва қиёмат кунига иймон келтирганларини мевалар ила ризқлантиргин», деганини эсла. У зот: «Ким куфр келтирса, озгина ҳузур бахш этаман, сўнгра дўзах азобига мажбур қиламан ва у қандай ҳам ёмон жой!» деди.",19,1],["وَإِذْ يَرْفَعُ إِ[q:656[بْ]ر[n[َٲ]هِـ[n[ـۧ]مُ [h:666[ٱ]لْقَوَاعِدَ مِنَ [h:667[ٱ]لْبَيْتِ وَإِسْمَ[n[ـٰ]عِيلُ رَبَّنَا تَقَبَّلْ مِ[g[نّ][o[َآ‌ۖ] إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:668[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Иброҳим билан Исмоил: «Эй Роббимиз, биздан қабул эт, албатта, Сенинг Ўзинг эшитувчи, билувчи зотсан», деб, байтнинг пойдеворларини кўтараётганини эсла.",20,1],["رَبَّنَا وَ[h:670[ٱ][q:670[جْ]عَلْنَا مُسْلِمَيْنِ لَكَ وَمِ[f:671[ن ذ]ُرِّيَّتِن[o[َآ] أُ[g[مّ]َ[a:672[ةً م]ُّسْلِمَ[u:673[ةً ل]َّكَ وَأَرِنَا مَنَاسِكَنَا وَتُ[q:674[بْ] عَلَيْن[o[َآ‌ۖ] إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:675[ٱ][l[ل]تَّوَّابُ [h:195[ٱ][l[ل]رَّح[p[ِي]مُ","«Роббимиз, икковимизни Ўзингга мусулмон бўлганлардан қил ва зурриётимиздан ҳам Ўзингга мусулмон уммат қил, бизга ибодатларимизни кўрсат, тавбамизни қабул эт. Албатта, Сенинг Ўзинг тавбаларни кўплаб қабул этувчи, раҳмли зотсан».",20,1],["رَبَّنَا وَ[h:676[ٱ][q:676[بْ]عَثْ فِيهِمْ رَسُول[a:677[اً م]ِّنْهُمْ يَتْلُو[s[اْ] عَلَيْهِمْ ءَايَ[n[ـٰ]تِكَ وَيُعَلِّمُهُمُ [h:678[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:679[ٱ]لْحِكْمَةَ وَيُزَكِّيهِمْ‌ۚ إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:680[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","«Роббимиз, ўзларининг ичидан уларга оятларингни тиловат қилиб берадиган, китобни ва ҳикматни ўргатадиган, уларни поклайдиган Пайғамбар юбор. Албатта, Сенинг Ўзинг азиз ва ҳикматли зотсан».",20,1],["وَم[a:682[َن ي]َرْغَبُ ع[a:683[َن م]ِّلَّةِ إِ[q:640[بْ]ر[n[َٲ]هِـ[n[ـۧ]مَ إِلَّا مَ[f:684[ن س]َفِهَ نَفْسَهُ[n[ۥ]‌ۚ وَلَقَدِ [h:685[ٱ]صْطَفَيْنَ[n[ـٰ]هُ فِى [h:599[ٱ][l[ل]دُّنْيَا‌ۖ وَإِ[g[نّ]َهُ[n[ۥ] فِى [h:536[ٱ]لْأَخِرَةِ لَمِنَ [h:686[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Ўзини эси паст санаганларгина Иброҳимнинг миллатидан юз ўгиради. Албатта, Биз уни бу дунёда танлаб олдик ва, албатта, у охиратда солиҳлардан бўлгай.",20,1],["إِذْ قَالَ لَهُ[n[ۥ] رَبُّهُ[o[ۥٓ] أَسْلِمْ‌ۖ قَالَ أَسْلَمْتُ لِرَبِّ [h:687[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Чунки Робби унга: «Мусулмон бўл!» деганида, у: «Оламларнинг Роббига мусулмон бўлдим», деди.",20,1],["وَوَصَّىٰ بِه[o[َآ] إِ[q:656[بْ]ر[n[َٲ]هِـ[n[ـۧ]مُ بَنِيهِ وَيَعْقُوبُ يَ[n[ـٰ]بَنِىَّ إِ[g[نّ]َ [h:80[ٱ]للَّهَ [h:688[ٱ]صْطَفَىٰ لَكُمُ [h:689[ٱ][l[ل]دِّينَ فَلَا تَمُوتُ[g[نّ]َ إِلَّا وَأَ[f:98[نت][w:690[ُم م]ُّسْلِم[p[ُو]نَ","Иброҳим ўша ни болаларига васият қилди. Яъқуб ҳам: «Эй болаларим, албатта, Аллоҳ сизларга динни танлади, сизлар мусулмон бўлмасдан туриб ўлмайсиз» деди.",20,1],["أَمْ كُ[f:100[نت]ُمْ شُهَد[o[َا]ٓءَ إِذْ حَضَرَ يَعْقُوبَ [h:691[ٱ]لْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ م[i:692[ِنۢ ب]َعْدِى قَالُو[s[اْ] نَعْبُدُ إِلَ[n[ـٰ]هَكَ وَإِلَ[n[ـٰ]هَ ءَاب[o[َا]ٓئِكَ إِ[q:640[بْ]ر[n[َٲ]هِـ[n[ـۧ]مَ وَإِسْمَ[n[ـٰ]عِيلَ وَإِسْحَ[n[ـٰ]قَ إِلَ[n[ـٰ][a:693[هًا و][n[َٲ]حِ[a:694[دًا و]َنَحْنُ لَهُ[n[ۥ] مُسْلِم[p[ُو]نَ","Ёки Яъқубга ўлим ҳозир бўлиб, у ўз болаларига: «Мендан кейин нимага ибодат қиласизлар?» деганида, улар: «Сенинг илоҳингга ва оталаринг Иброҳим, Исмоил ва Исҳоқларнинг илоҳига, ёлғиз илоҳга ибодат қиламиз ҳамда биз Унга мусулмон бўлувчимиз», деганларида гувоҳ бўлганмисиз?!",20,1],["تِلْكَ أُ[g[مّ]َ[f:695[ةٌ ق]َ[q:298[دْ] خَلَتْ‌ۖ لَهَا مَا كَسَبَتْ وَلَك[w:696[ُم م]َّا كَسَ[q:697[بْ]تُمْ‌ۖ وَلَا تُسْــَٔلُونَ عَ[g[مّ]َا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Улар бир уммат эди, ўтиб кетдилар. Уларга ўзлари касб қилганлари бўлади. Сизларга ўзингиз касб қилганингиз бўлади. Уларнинг қилган амалларидан сиз сўралмайсиз.",20,1],["وَقَالُو[s[اْ] كُونُو[s[اْ] هُودًا أَوْ نَصَ[n[ـٰ]رَىٰ تَهْتَدُو[s[اْ‌ۗ] قُلْ بَلْ مِلَّةَ إِ[q:640[بْ]ر[n[َٲ]هِـ[n[ـۧ]مَ حَنِي[a:698[فًا‌ۖ و]َمَا كَانَ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Улар: «Яҳудий ёки насроний бўлинг, ҳидоят топасиз», дейдилар. Балки: «Иброҳимнинг ҳаниф миллатига эргашамиз ва у мушриклардан бўлмаган», деб айт.",21,1],["قُول[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا بِ[h:32[ٱ]للَّهِ وَم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْنَا وَم[o[َآ] أُ[f:17[نز]ِلَ إِلَ[o[ىٰٓ] إِ[q:640[بْ]ر[n[َٲ]هِـ[n[ـۧ]مَ وَإِسْمَ[n[ـٰ]عِيلَ وَإِسْحَ[n[ـٰ]قَ وَيَعْقُوبَ وَ[h:700[ٱ]لْأَسْبَاطِ وَم[o[َآ] أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَم[o[َآ] أُوتِىَ [h:701[ٱ][l[ل][g[نّ]َبِيُّونَ م[u:22[ِن ر]َّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَ[a:702[دٍ م]ِّنْهُمْ وَنَحْنُ لَهُ[n[ۥ] مُسْلِم[p[ُو]نَ","Айтинглар: «Аллоҳга ва бизга туширилган нарсага, Иброҳим, Исмоил, Исҳоқ, Яъқуб, асботларга туширилган нарсага, Мусо ва Ийсога берилган нарсага ва Пайғамбарларга Роббиларидан берилган нарсага иймон келтирдик. Уларнинг орасидан бирортасини фарқламаймиз ва биз Унга мусулмонлармиз».",21,1],["فَإِنْ ءَامَنُو[s[اْ] بِمِثْلِ م[o[َآ] ءَامَ[f:703[نت][c:704[ُم ب]ِه[n[ِۦ] فَقَدِ [h:705[ٱ]هْتَدَو[s[اْ‌ۖ] وَّإِ[f:706[ن ت]َوَلَّوْ[s[اْ] فَإِ[g[نّ]َمَا هُمْ فِى شِقَا[f:707[قٍ‌ۖ ف]َسَيَكْفِيكَهُمُ [h:708[ٱ]للَّهُ‌ۚ وَهُوَ [h:709[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Агар сиз иймон келтирганга ўхшаш иймон келтирсалар, батаҳқиқ, ҳидоят топадилар. Ва агар юз ўгирсалар, бас, албатта, улар хилофдан бошқа нарсада бўлмайдилар. Аллоҳ сенга улар дан кифоя қилади. Ва У эшитувчи, билувчи зотдир.",21,1],["صِ[q:710[بْ]غَةَ [h:711[ٱ]للَّهِ‌ۖ وَمَنْ أَحْسَنُ مِنَ [h:321[ٱ]للَّهِ صِ[q:712[بْ]غَ[a:713[ةً‌ۖ و]َنَحْنُ لَهُ[n[ۥ] عَ[n[ـٰ]بِد[p[ُو]نَ","Аллоҳнинг бўёғини. Аллоҳнинг бўёғидан чиройлироқ бўёқ бергувчи ким бор?! Ва биз Унга ибодат қилувчилармиз.",21,1],["قُلْ أَتُح[m[َا]ٓجُّونَنَا فِى [h:714[ٱ]للَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَن[o[َآ] أَعْمَ[n[ـٰ]لُنَا وَلَكُمْ أَعْمَ[n[ـٰ]لُكُمْ وَنَحْنُ لَهُ[n[ۥ] مُخْلِص[p[ُو]نَ","Айт: «Биз билан Аллоҳ ҳақида тортишасизми?! Ва ҳолбуки, У бизнинг Роббимиз ва сизнинг Роббингиз, бизнинг ўз амалларимиз бор, сизнинг ўз амалларингиз бор. Ва биз Унга мухлисмиз».",21,1],["أَمْ تَقُولُونَ إِ[g[نّ]َ إِ[q:640[بْ]ر[n[َٲ]هِـ[n[ـۧ]مَ وَإِسْمَ[n[ـٰ]عِيلَ وَإِسْحَ[n[ـٰ]قَ وَيَعْقُوبَ وَ[h:715[ٱ]لْأَسْبَاطَ كَانُو[s[اْ] هُودًا أَوْ نَصَ[n[ـٰ]رَىٰ‌ۗ قُلْ ءَأَ[f:716[نت]ُمْ أَعْلَمُ أَمِ [h:717[ٱ]للَّهُ‌ۗ وَمَنْ أَظْلَمُ مِ[g[مّ]َ[f:718[ن ك]َتَمَ شَهَ[n[ـٰ]دَةً عِ[f:719[ند]َهُ[n[ۥ] مِنَ [h:321[ٱ]للَّهِ‌ۗ وَمَا [h:384[ٱ]للَّهُ بِغَ[n[ـٰ]فِلٍ عَ[g[مّ]َا تَعْمَل[p[ُو]نَ","Ёки: «Албатта, Иброҳим, Исмоил, Исҳоқ, Яъқуб ва асботлар яҳудий ва насроний бўлган», дейсизларми?! «Сизлар билимдонроқми ёки Аллоҳми?» дегин. Ҳузуридаги Аллоҳдан бўлган гувоҳликни беркитган кимсадан ҳам золимроқ одам борми?! Ва Аллоҳ қилаётган ишларингиздан ғофил эмасдир.",21,1],["تِلْكَ أُ[g[مّ]َ[f:695[ةٌ ق]َ[q:298[دْ] خَلَتْ‌ۖ لَهَا مَا كَسَبَتْ وَلَك[w:696[ُم م]َّا كَسَ[q:697[بْ]تُمْ‌ۖ وَلَا تُسْــَٔلُونَ عَ[g[مّ]َا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Улар бир уммат эдилар, ўтиб кетдилар. Уларга ўзлари касб қилганлари бўлади. Сизларга ўзингиз касб қилганингиз бўлади. Уларнинг қилган амалларидан сизлар сўралмайсизлар.",21,1],["۞ سَيَقُولُ [h:720[ٱ][l[ل]سُّفَه[o[َا]ٓءُ مِنَ [h:721[ٱ][l[ل][g[نّ]َاسِ مَا وَلَّ[n[ـٰ]هُمْ عَ[f:722[ن ق]ِ[q:723[بْ]لَتِهِمُ [h:724[ٱ]لَّتِى كَانُو[s[اْ] عَلَيْهَا‌ۚ قُل لِّلَّهِ [h:725[ٱ]لْمَشْرِقُ وَ[h:602[ٱ]لْمَغْرِبُ‌ۚ يَهْدِى م[a:476[َن ي]َش[o[َا]ٓءُ إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Одамлардан эси пастлари: «Буларни қиблаларидан нима юз ўгиртирди экан?» дейдилар. «Машриқу мағриб Аллоҳники, кимни хоҳласа, ўшани тўғри йўлга бошлайди», деб айт.",22,2],["وَكَذ[n[َٲ]لِكَ جَعَلْنَ[n[ـٰ]كُمْ أُ[g[مّ]َ[a:727[ةً و]َسَ[u:728[طًا ل]ِّتَكُونُو[s[اْ] شُهَد[o[َا]ٓءَ عَلَى [h:729[ٱ][l[ل][g[نّ]َاسِ وَيَكُونَ [h:730[ٱ][l[ل]رَّسُولُ عَلَيْكُمْ شَهِي[a:731[دًا‌ۗ و]َمَا جَعَلْنَا [h:732[ٱ]لْقِ[q:733[بْ]لَةَ [h:734[ٱ]لَّتِى كُ[f:735[نت]َ عَلَيْه[o[َآ] إِلَّا لِنَعْلَمَ م[a:736[َن ي]َتَّبِعُ [h:737[ٱ][l[ل]رَّسُولَ مِ[g[مّ][a:738[َن ي]َ[f:739[نق]َلِبُ عَلَىٰ عَقِبَيْهِ‌ۚ وَإِ[f:740[ن ك]َانَتْ لَكَبِيرَةً إِلَّا عَلَى [h:289[ٱ]لَّذِينَ هَدَى [h:741[ٱ]للَّهُ‌ۗ وَمَا كَانَ [h:742[ٱ]للَّهُ لِيُضِيعَ إِيمَ[n[ـٰ]نَكُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ بِ[h:743[ٱ][l[ل][g[نّ]َاسِ لَرَءُو[u:744[فٌ ر]َّح[p[ِي]مٌ","Шунингдек, сизларни одамлар устидан гувоҳ бўлишингиз ва Пайғамбар сизларнинг устингиздан гувоҳ бўлиши учун ўрта миллат қилдик. Сен аввал юзланган қиблани ортга бурилиб кетадиганлар ким-у Пайғамбарга эргашувчилар ким эканини билиш учунгина қилганмиз. Гарчи бу иш Аллоҳ ҳидоятга солганлардан бошқаларга оғир бўлса ҳам. Аллоҳ иймонингизни зое қилмайди. Албатта, Аллоҳ одамларга меҳрибон ва раҳмлидир.",22,2],["قَ[q:298[دْ] نَرَىٰ تَقَلُّبَ وَ[q:745[جْ]هِكَ فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ‌ۖ فَلَنُوَلِّيَ[g[نّ]َكَ قِ[q:747[بْ]لَ[f:748[ةً ت]َرْضَ[n[ـٰ]هَا‌ۚ فَوَلِّ وَ[q:749[جْ]هَكَ شَ[q:750[طْ]رَ [h:751[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ‌ۚ وَحَيْثُ مَا كُ[f:100[نت]ُمْ فَوَلُّو[s[اْ] وُجُوهَكُمْ شَ[q:753[طْ]رَهُ[n[ۥ]‌ۗ وَإِ[g[نّ]َ [h:754[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ لَيَعْلَمُونَ أَ[g[نّ]َهُ [h:137[ٱ]لْحَقُّ م[u:22[ِن ر]َّبِّهِمْ‌ۗ وَمَا [h:384[ٱ]للَّهُ بِغَ[n[ـٰ]فِلٍ عَ[g[مّ]َا يَعْمَل[p[ُو]نَ","Гоҳо юзингни осмонга тез-тез бурилганини кўрамиз. Бас, албатта, сени ўзинг рози бўлган қиблага қаратамиз. Юзингни Масжидул Ҳаром томон бур. Қаерда бўлсангиз ҳам, юзингизни у томон бурингиз. Албатта, китоб берилганлар уни Роббиларидан бўлган ҳақ эканини биладилар. Ва Аллоҳ уларнинг қилаётган амалларидан ғофил эмасдир.",22,2],["وَلَئِنْ أَتَيْتَ [h:755[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ بِكُلِّ ءَايَ[a:756[ةٍ م]َّا تَبِعُو[s[اْ] قِ[q:757[بْ]لَتَكَ‌ۚ وَم[o[َآ] أَ[f:169[نت]َ بِتَابِ[f:758[عٍ ق]ِ[q:759[بْ]لَتَهُمْ‌ۚ وَمَا بَعْضُه[c:760[ُم ب]ِتَابِ[f:761[عٍ ق]ِ[q:762[بْ]لَةَ بَعْ[a:763[ضٍ‌ۚ و]َلَئِنِ [h:631[ٱ]تَّبَعْتَ أَهْو[o[َا]ٓءَه[w:764[ُم م]ّ[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَكَ مِنَ [h:634[ٱ]لْعِلْمِ‌ۙ إِ[g[نّ]َكَ إِ[u:765[ذًا ل]َّمِنَ [h:766[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Агар китоб берилганларга барча ҳужжатларни келтирсанг ҳам, сенинг қиблангга эргашмаслар. Сен ҳам уларнинг қибласига эргашувчи эмассан. Ва улар бир-бирларининг қибласига эргашувчи эмаслар. Агар сенга келган илмдан кейин ҳам уларнинг ҳавою нафсларига эргашсанг, унда, албатта, золимлардан бўлурсан.",22,2],["ٱلَّذِينَ ءَاتَيْنَ[n[ـٰ]هُمُ [h:635[ٱ]لْكِتَ[n[ـٰ]بَ يَعْرِفُونَهُ[n[ۥ] كَمَا يَعْرِفُونَ أَ[q:767[بْ]ن[o[َا]ٓءَهُمْ‌ۖ وَإِ[g[نّ]َ فَرِي[a:768[قًا م]ِّنْهُمْ لَيَكْتُمُونَ [h:769[ٱ]لْحَقَّ وَهُمْ يَعْلَم[p[ُو]نَ","Китоб берилганлар уни худди болаларини танигандек танийдилар. Ва, албатта, улардан бир гуруҳлари билиб туриб ҳақни беркитадилар.",23,2],["ٱلْحَقُّ م[u:770[ِن ر]َّبِّكَ‌ۖ فَلَا تَكُونَ[g[نّ]َ مِنَ [h:771[ٱ]لْمُمْتَر[p[ِي]نَ","Бу ҳақ Роббингдандир, ҳеч-ҳеч шак қилувчилардан бўлма.",23,2],["وَلِكُ[a:772[لٍّ و]ِ[q:773[جْ]هَةٌ هُوَ مُوَلِّيهَا‌ۖ فَ[h:774[ٱ]سْتَبِقُو[s[اْ] [h:775[ٱ]لْخَيْر[n[َٲ]تِ‌ۚ أَيْنَ مَا تَكُونُو[s[اْ] يَأْتِ بِكُمُ [h:776[ٱ]للَّهُ جَمِيعًا‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Ҳар кимнинг юзланадиган тарафи бор. У ўшанга боқади. Яхшиликларга шошилинг. Қаерда бўлсангиз ҳам, Аллоҳ сизларни жамлайди. Албатта, Аллоҳ ҳар бир нарсага қодирдир.",23,2],["وَمِنْ حَيْثُ خَرَ[q:777[جْ]تَ فَوَلِّ وَ[q:749[جْ]هَكَ شَ[q:750[طْ]رَ [h:751[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ‌ۖ وَإِ[g[نّ]َهُ[n[ۥ] لَلْحَقُّ م[u:770[ِن ر]َّبِّكَ‌ۗ وَمَا [h:384[ٱ]للَّهُ بِغَ[n[ـٰ]فِلٍ عَ[g[مّ]َا تَعْمَل[p[ُو]نَ","Қаердан чиқсанг ҳам, юзингни Масжидул Ҳаром томон бур. Ва, албатта, бу Роббингдан бўлган ҳақдир.",23,2],["وَمِنْ حَيْثُ خَرَ[q:777[جْ]تَ فَوَلِّ وَ[q:749[جْ]هَكَ شَ[q:750[طْ]رَ [h:751[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ‌ۚ وَحَيْثُ مَا كُ[f:100[نت]ُمْ فَوَلُّو[s[اْ] وُجُوهَكُمْ شَ[q:753[طْ]رَهُ[n[ۥ] لِئَلَّا يَكُونَ لِل[g[نّ]َاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا [h:778[ٱ]لَّذِينَ ظَلَمُو[s[اْ] مِنْهُمْ فَلَا تَخْشَوْهُمْ وَ[h:779[ٱ]خْشَوْنِى وَلِأُتِ[g[مّ]َ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَد[p[ُو]نَ","Ва қаердан чиқсан ҳам, юзингни Масжидул Ҳаром томон бур. Қаерда бўлсангиз ҳам, юзингизни у томонга буринг. Одамларда сизга қарши ҳужжат бўлмаслиги учун. Улардан зулм қилганларидан қўрқманглар, Мендан қўрқинглар. Ва сизга неъматимни батамом этиш учун, шоядки ҳидоят топсангиз.",23,2],["كَم[o[َآ] أَرْسَلْنَا فِيكُمْ رَسُول[a:780[اً م]ِّ[f:344[نك]ُمْ يَتْلُو[s[اْ] عَلَيْكُمْ ءَايَ[n[ـٰ]تِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ [h:781[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:679[ٱ]لْحِكْمَةَ وَيُعَلِّمُك[w:782[ُم م]َّا لَمْ تَكُونُو[s[اْ] تَعْلَم[p[ُو]نَ","Шунингдек, ичингизга ўзингиздан, сизларга оятларимизни тиловат қиладиган, сизларни поклайдиган, сизларга китобни, ҳикматни ва билмайдиган нарсаларингизни ўргатадиган Пайғамбар юбордик.'",23,2],["فَ[h:9999[ٱ]ذْكُرُون[o[ِىٓ] أَذْكُرْكُمْ وَ[h:783[ٱ]شْكُرُو[s[اْ] لِى وَلَا تَكْفُر[p[ُو]نِ","Бас, Мени эслангиз, сизни эслайман. Ва Менга шукр қилингиз, куфр қилмангиз.",23,2],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:784[ٱ]سْتَعِينُو[s[اْ] بِ[h:223[ٱ][l[ل]صَّ[q:223[بْ]رِ وَ[h:224[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ مَعَ [h:785[ٱ][l[ل]صَّ[n[ـٰ]بِر[p[ِي]نَ","Эй иймон келтирганлар! Сабр ва намоз ила мадад сўранглар. Албатта, Аллоҳ сабрлилар биландир.",23,2],["وَلَا تَقُولُو[s[اْ] لِم[a:786[َن ي]ُ[q:787[قْ]تَلُ فِى سَبِيلِ [h:788[ٱ]للَّهِ أَمْو[n[َٲ][i:789[تُۢ‌ۚ ب]َلْ أَحْي[o[َا]ٓ[a:790[ءٌ و]َلَ[n[ـٰ]ك[u:46[ِن ل]َّا تَشْعُر[p[ُو]نَ","Аллоҳнинг йўлида қатл бўлганларни ўликлар деманг. Балки улар тирикдирлар, лекин сиз сезмайсиз.",24,2],["وَلَنَ[q:791[بْ]لُوَ[g[نّ]َك[c:792[ُم ب]ِش[a:793[َىْءٍ م]ِّنَ [h:794[ٱ]لْخَوْفِ وَ[h:795[ٱ]لْجُوعِ وَنَ[q:796[قْ][a:797[صٍ م]ِّنَ [h:798[ٱ]لْأَمْو[n[َٲ]لِ وَ[h:799[ٱ]لْأَ[f:799[نف]ُسِ وَ[h:800[ٱ][l[ل]ثَّمَر[n[َٲ]تِ‌ۗ وَبَشِّرِ [h:801[ٱ][l[ل]صَّ[n[ـٰ]بِر[p[ِي]نَ","Албата, Биз сизларни бир оз қўрқинч ва очлик билан, мол-мулкга, жонга меваларга нуқсон етказиш билан синаймиз. Ва сабрлиларга башорат бер.",24,2],["ٱلَّذِينَ إِذ[o[َآ] أَصَ[n[ـٰ]بَتْه[w:802[ُم م]ُّصِيبَ[f:803[ةٌ ق]َال[o[ُوٓ][s[اْ] إِ[g[نّ]َا لِلَّهِ وَإِ[g[نّ][o[َآ] إِلَيْهِ ر[n[َٲ]جِع[p[ُو]نَ","Улар мусибат етганда: «Албатта, биз Аллоҳникимиз ва, албатта, биз Унга қайтувчимиз», дерлар.",24,2],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ عَلَيْهِمْ صَلَو[n[َٲ][a:804[تٌ م]ّ[u:22[ِن ر]َّبِّهِمْ وَرَحْمَ[a:805[ةٌ‌ۖ و]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:806[ٱ]لْمُهْتَد[p[ُو]نَ","Ана ўшаларга Роббиларидан саловатлар ва раҳмат бор. Ана ўшалар ҳидоят топганлардир.",24,2],["۞ إِ[g[نّ]َ [h:807[ٱ][l[ل]صَّفَا وَ[h:808[ٱ]لْمَرْوَةَ مِ[f:809[ن ش]َع[o[َا]ٓئِرِ [h:810[ٱ]للَّهِ‌ۖ فَمَنْ حَجَّ [h:811[ٱ]لْبَيْتَ أَوِ [h:812[ٱ]عْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أ[a:813[َن ي]َطَّوَّفَ بِهِمَا‌ۚ وَمَ[f:814[ن ت]َطَوَّعَ خَيْ[f:815[رًا ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ شَاكِرٌ عَل[p[ِي]مٌ","Албатта, Сафо ва Марва Аллоҳнинг белгиларидандир. Ким Байтуллоҳни ҳаж ёки умра қилса, икковлари ўртасида саъйи қилиш гуноҳ эмас. Ким яхшиликни холисона қилса, бас, албатта, Аллоҳ шукр қилувчи ва билувчидир.",24,2],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَكْتُمُونَ م[o[َآ] أَ[f:515[نز]َلْنَا مِنَ [h:816[ٱ]لْبَيِّنَ[n[ـٰ]تِ وَ[h:817[ٱ]لْهُدَىٰ م[i:146[ِنۢ ب]َعْدِ مَا بَيَّ[g[نّ]َ[n[ـٰ]هُ لِل[g[نّ]َاسِ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ‌ۙ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يَلْعَنُهُمُ [h:819[ٱ]للَّهُ وَيَلْعَنُهُمُ [h:820[ٱ][l[ل]لَّ[n[ـٰ]عِن[p[ُو]نَ","Албатта, Биз нозил қилган равшан оятларни ва ҳидоятни одамларга китобда баён қилиб берганимиздан кейин беркитганларни–ўшаларни Аллоҳ лаънатлайди. Ва лаънатловчилар лаънатлайди.",24,2],["إِلَّا [h:778[ٱ]لَّذِينَ تَابُو[s[اْ] وَأَصْلَحُو[s[اْ] وَبَيَّنُو[s[اْ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَتُوبُ عَلَيْهِمْ‌ۚ وَأَنَا [h:821[ٱ][l[ل]تَّوَّابُ [h:195[ٱ][l[ل]رَّح[p[ِي]مُ","Магар тавба қилиб, аҳли солиҳ бўлиб, баён қилганларнинг, ана ўшаларнинг тавбасини қабул қиламан. Ва Мен тавбаларни кўплаб қабул қилувчи ва раҳмлидирман.",24,2],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَمَاتُو[s[اْ] وَهُمْ كُفَّارٌ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ عَلَيْهِمْ لَعْنَةُ [h:822[ٱ]للَّهِ وَ[h:823[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ وَ[h:824[ٱ][l[ل][g[نّ]َاسِ أَ[q:825[جْ]مَع[p[ِي]نَ","Албатта, куфр келтирган ва кофирлик ҳолида ўлганларга–ана ўшаларга Аллоҳнинг, фаришталарнинг ва одамларнинг–барчанинг лаънати бўлгай.",24,2],["خَ[n[ـٰ]لِدِينَ فِيهَا‌ۖ لَا يُخَفَّفُ عَنْهُمُ [h:448[ٱ]لْعَذَابُ وَلَا هُمْ يُ[f:826[نظ]َر[p[ُو]نَ","Унда абадий бўлурлар. Улардан азоб енгиллатилмас. Ва уларга назар ҳам солинмас.",24,2],["وَإِلَ[n[ـٰ]هُكُمْ إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[u:828[دٌ‌ۖ ل]ّ[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ [h:829[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ [h:830[ٱ][l[ل]رَّح[p[ِي]مُ","Ва илоҳингиз бир илоҳдир. Роҳман ва Раҳийм бўлмиш Ундан ўзга ибодатга сазовор зот йўқдир.",24,2],["إِ[g[نّ]َ فِى خَلْقِ [h:831[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَ[h:832[ٱ]خْتِلَ[n[ـٰ]فِ [h:833[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ وَ[h:835[ٱ]لْفُلْكِ [h:836[ٱ]لَّتِى تَ[q:120[جْ]رِى فِى [h:837[ٱ]لْبَحْرِ بِمَا يَ[f:838[نف]َعُ [h:839[ٱ][l[ل][g[نّ]َاسَ وَم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[a:840[ِن م]ّ[o[َا]ٓ[f:841[ءٍ ف]َأَحْيَا بِهِ [h:842[ٱ]لْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِ[f:843[ن ك]ُلِّ د[m[َا]ٓبَّ[a:844[ةٍ و]َتَصْرِيفِ [h:845[ٱ][l[ل]رِّيَ[n[ـٰ]حِ وَ[h:846[ٱ][l[ل]سَّحَابِ [h:847[ٱ]لْمُسَخَّرِ بَيْنَ [h:848[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:850[مٍ ي]َعْقِل[p[ُو]نَ","Албатта, осмонлару ернинг яратилишида, кечаю кундузнинг алмашиб туришида, одамларга манфаатли нарсалари ила денгизда юриб турган кемада, Аллоҳнинг осмондан сув тушириб, у билан ўлган ерни тирилтириши ва унда турли жондорларни таратишида, шамолларни йўналтиришида, осмону ер орасидаги итоатгўй булутда ақл юритувчи қавмлар учун белгилар бор.",25,2],["وَمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ م[a:851[َن ي]َتَّخِذُ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ أَ[f:96[ند]َا[a:852[دًا ي]ُحِبُّونَهُمْ كَحُبِّ [h:853[ٱ]للَّهِ‌ۖ وَ[h:37[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَشَدُّ حُب[u:854[ًّا ل]ِّلَّهِ‌ۗ وَلَوْ يَرَى [h:855[ٱ]لَّذِينَ ظَلَم[o[ُوٓ][s[اْ] إِذْ يَرَوْنَ [h:856[ٱ]لْعَذَابَ أَ[g[نّ]َ [h:857[ٱ]لْقُوَّةَ لِلَّهِ جَمِي[a:858[عًا و]َأَ[g[نّ]َ [h:859[ٱ]للَّهَ شَدِيدُ [h:860[ٱ]لْعَذ[p[َا][q[ب]ِ","Одамлар ичида Аллоҳдан ўзга тенгдошларни тутадиганлар ва уларни Аллоҳни севгандек севадиганлар бор. Иймон келтирганларнинг Аллоҳга муҳаббатлари қаттиқдир. Зулм қилганлар азобни кўрган чоғларида, албатта, барча қувват Аллоҳга хослигини ва, албатта, Аллоҳнинг азоби шиддатли эканини билсалар эди!",25,2],["إِذْ تَبَرَّأَ [h:861[ٱ]لَّذِينَ [h:862[ٱ]تُّبِعُو[s[اْ] مِنَ [h:523[ٱ]لَّذِينَ [h:863[ٱ]تَّبَعُو[s[اْ] وَرَأَوُ[s[اْ] [h:864[ٱ]لْعَذَابَ وَتَقَطَّعَتْ بِهِمُ [h:865[ٱ]لْأَسْب[p[َا][q[ب]ُ","У пайтда пешволар эргашганлардан тонурлар ва азобни кўрурлар, уларнинг боғланишлари кесилур.",25,2],["وَقَالَ [h:614[ٱ]لَّذِينَ [h:863[ٱ]تَّبَعُو[s[اْ] لَوْ أَ[g[نّ]َ لَنَا كَرَّ[f:866[ةً ف]َنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُو[s[اْ] مِ[g[نّ]َا‌ۗ كَذ[n[َٲ]لِكَ يُرِيهِمُ [h:867[ٱ]للَّهُ أَعْمَ[n[ـٰ]لَهُمْ حَسَر[n[َٲ]تٍ عَلَيْهِمْ‌ۖ وَمَا ه[c:868[ُم ب]ِخَ[n[ـٰ]رِجِينَ مِنَ [h:869[ٱ][l[ل][g[نّ][p[َا]رِ","Ва эргашганлар: «Қани энди бизга бир ортга қайтиш бўлса эди, биздан тонганларидек, биз ҳам улардан тонар эдик», дерлар. Шундай қилиб, Аллоҳ уларга амалларининг ўзларига ҳасрат бўлганини кўрсатур. Ва улар дўзахдан чиқувчи эмаслар.",25,2],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ كُلُو[s[اْ] مِ[g[مّ]َا فِى [h:44[ٱ]لْأَرْضِ حَلَ[n[ـٰ]ل[f:870[اً ط]َيِّ[a:871[بًا و]َلَا تَتَّبِعُو[s[اْ] خُطُو[n[َٲ]تِ [h:872[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] لَكُمْ عَدُ[a:873[وٌّ م]ُّب[p[ِي]نٌ","Эй одамлар! Ер юзидаги нарсалардан ҳалол-покларини енглар. Ва шайтон изидан эргашманглар, чунки у сизларга очиқ душмандир.",25,2],["إِ[g[نّ]َمَا يَأْمُرُك[c:874[ُم ب]ِ[h:875[ٱ][l[ل]سّ[o[ُو]ٓءِ وَ[h:876[ٱ]لْفَحْش[o[َا]ٓءِ وَأَ[f:877[ن ت]َقُولُو[s[اْ] عَلَى [h:412[ٱ]للَّهِ مَا لَا تَعْلَم[p[ُو]نَ","Албатта, у сизларни ёмон ва фаҳш ишларга ҳамда Аллоҳга қарши билмаган нарсангизни гапиришингизга буюради.",25,2],["وَإِذَا قِيلَ لَهُمُ [h:878[ٱ]تَّبِعُو[s[اْ] م[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ قَالُو[s[اْ] بَلْ نَتَّبِعُ م[o[َآ] أَلْفَيْنَا عَلَيْهِ ءَاب[o[َا]ٓءَن[o[َآ‌ۗ] أَوَلَوْ كَانَ ءَاب[o[َا]ٓؤُهُمْ لَا يَعْقِلُونَ شَيْـ[a:232[ـًٔا و]َلَا يَهْتَد[p[ُو]نَ","Уларга: «Аллоҳ нозил қилган нарсага эргашингиз», дейилса, улар: «Йўк, биз оталаримизни нимада топсак, шунга эргашамиз», дейдилар. Оталари ҳеч нарсага ақли етмаган ва ҳидоят топмаган бўлсалар ҳам-а?!",26,2],["وَمَثَلُ [h:879[ٱ]لَّذِينَ كَفَرُو[s[اْ] كَمَثَلِ [h:55[ٱ]لَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُع[o[َا]ٓ[a:880[ءً و]َنِد[o[َا]ٓ[f:881[ءً‌ۚ ص]ُم[i:61[ُّۢ ب]ُكْمٌ عُمْ[f:62[ىٌ ف]َهُمْ لَا يَعْقِل[p[ُو]نَ","Куфр келтирганлар мисоли худди қичқириқ ва сасдан бошқа нарсани эшитмайдиганларга бақираётганга ўхшайди. Улар кар, соқов ва кўрдирлар. Улар ақл ишлатмаслар.",26,2],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] كُلُو[s[اْ] مِ[f:274[ن ط]َيِّبَ[n[ـٰ]تِ مَا رَزَ[q:275[قْ]نَ[n[ـٰ]كُمْ وَ[h:783[ٱ]شْكُرُو[s[اْ] لِلَّهِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ إِيَّاهُ تَعْبُد[p[ُو]نَ","Эй иймон келтирганлар! Сизларга ризқ қилиб берганимиз пок нарсалардан енглар ва Аллоҳга шукр қилинглар, агар Унга ибодат қиладиган бўлсаларингиз.",26,2],["إِ[g[نّ]َمَا حَرَّمَ عَلَيْكُمُ [h:882[ٱ]لْمَيْتَةَ وَ[h:883[ٱ][l[ل]دَّمَ وَلَحْمَ [h:884[ٱ]لْخِ[f:885[نز]ِيرِ وَم[o[َآ] أُهِلَّ بِه[n[ِۦ] لِغَيْرِ [h:886[ٱ]للَّهِ‌ۖ فَمَنِ [h:887[ٱ]ضْطُرَّ غَيْرَ بَا[a:888[غٍ و]َلَا عَا[f:889[دٍ ف]َل[o[َآ] إِثْمَ عَلَيْهِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Албатта, У зот сизларга фақат ўлимтикни, қонни, чўчқанинг гўштини ва Аллоҳдан бошқага сўйилганни ҳаром қилди. Кимки мажбур бўлса-ю, зулм қилмай, ҳаддан ошмай, унга гуноҳ бўлмайди. Албатта, Аллоҳ мағфиратли ва раҳмлидир.",26,2],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَكْتُمُونَ م[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ مِنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ وَيَشْتَرُونَ بِه[n[ِۦ] ثَمَ[f:208[نًا ق]َلِيلاً‌ۙ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا [h:892[ٱ][l[ل][g[نّ]َارَ وَلَا يُكَلِّمُهُمُ [h:893[ٱ]للَّهُ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Албатта, Аллоҳ китобда туширган нарсани беркитганлар ва уни озгина баҳога сотганлар, ана ўшалар қоринларига оловдан бошқа нарсани емаслар, уларга Аллоҳ қиёмат куни гапирмас ва уларни покламас. Уларга аламли азоблар бор.",26,2],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ [h:52[ٱ]شْتَرَوُ[s[اْ] [h:53[ٱ][l[ل]ضَّلَ[n[ـٰ]لَةَ بِ[h:54[ٱ]لْهُدَىٰ وَ[h:894[ٱ]لْعَذَابَ بِ[h:895[ٱ]لْمَغْفِرَةِ‌ۚ فَم[o[َآ] أَصْبَرَهُمْ عَلَى [h:896[ٱ][l[ل][g[نّ][p[َا]رِ","Ана ўшалар адашувни ҳидоятга, азобни мағфиратга сотиб олганлардир. Дўзах ўтига қандоқ чидайдилар-а?!",26,2],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َ [h:897[ٱ]للَّهَ نَزَّلَ [h:898[ٱ]لْكِتَ[n[ـٰ]بَ بِ[h:370[ٱ]لْحَقِّ‌ۗ وَإِ[g[نّ]َ [h:754[ٱ]لَّذِينَ [h:899[ٱ]خْتَلَفُو[s[اْ] فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ لَفِى شِقَا[i:900[قِۭ ب]َع[p[ِي][q[د]ٍ","Бунинг сабаби, албатта, Аллоҳ китобни ҳақ билан нозил қилган эди. Китоб хусусида ихтилоф қилганлар эса, тубсиз тортишувдадирлар.",26,2],["۞ لَّيْسَ [h:901[ٱ]لْبِرَّ أَ[f:902[ن ت]ُوَلُّو[s[اْ] وُجُوهَكُمْ قِبَلَ [h:903[ٱ]لْمَشْرِقِ وَ[h:904[ٱ]لْمَغْرِبِ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:905[ٱ]لْبِرَّ مَنْ ءَامَنَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ وَ[h:823[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ وَ[h:906[ٱ]لْكِتَ[n[ـٰ]بِ وَ[h:907[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ وَءَاتَى [h:908[ٱ]لْمَالَ عَلَىٰ حُبِّه[n[ِۦ] ذَوِى [h:909[ٱ]لْقُرْبَىٰ وَ[h:420[ٱ]لْيَتَ[n[ـٰ]مَىٰ وَ[h:910[ٱ]لْمَسَ[n[ـٰ]كِينَ وَ[h:911[ٱ][q:911[بْ]نَ [h:912[ٱ][l[ل]سَّبِيلِ وَ[h:913[ٱ][l[ل]سّ[o[َا]ٓئِلِينَ وَفِى [h:914[ٱ][l[ل]رِّقَابِ وَأَقَامَ [h:915[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتَى [h:916[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَ[h:917[ٱ]لْمُوفُونَ بِعَهْدِهِمْ إِذَا عَ[n[ـٰ]هَدُو[s[اْ‌ۖ] وَ[h:918[ٱ][l[ل]صَّ[n[ـٰ]بِرِينَ فِى [h:919[ٱ]لْبَأْس[o[َا]ٓءِ وَ[h:920[ٱ][l[ل]ضَّرّ[o[َا]ٓءِ وَحِينَ [h:921[ٱ]لْبَأْسِ‌ۗ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ صَدَقُو[s[اْ‌ۖ] وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:922[ٱ]لْمُتَّق[p[ُو]نَ","Яхшилик юзингизни машриқ ёки мағриб томонга буришингизда эмас. Лекин яхшилик ким Аллоҳга, охират кунига, фаришталарга, китобга, Пайғамбарларга иймон келтирса ва яхши кўрган молини қариндошларга, етимларга, мискинларга, ватангадоларга, тиланчиларга, қул озод қилишга берса, намозни қоим қилса, закот берса. Аҳд қилганда аҳдига вафо қилувчилар, камбағаллик, қийинчилик пайтида ва шиддат вақтида ҳам сабр қилувчиларга, ана ўшалар содиқ бўлганлардир. Ана ўшалар тақводорлардир.",27,2],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] كُتِبَ عَلَيْكُمُ [h:923[ٱ]لْقِصَاصُ فِى [h:924[ٱ]لْقَتْلَى‌ۖ [h:925[ٱ]لْحُرُّ بِ[h:926[ٱ]لْحُرِّ وَ[h:927[ٱ]لْعَ[q:927[بْ]دُ بِ[h:928[ٱ]لْعَ[q:928[بْ]دِ وَ[h:929[ٱ]لْأُ[f:929[نث]َىٰ بِ[h:930[ٱ]لْأُ[f:930[نث]َىٰ‌ۚ فَمَنْ عُفِىَ لَهُ[n[ۥ] مِنْ أَخِيهِ ش[f:931[َىْءٌ ف]َ[h:932[ٱ]تِّبَا[i:933[عُۢ ب]ِ[h:934[ٱ]لْمَعْرُوفِ وَأَد[o[َا]ٓءٌ إِلَيْهِ بِإِحْسَ[n[ـٰ][f:935[نٍ‌ۗ ذ][n[َٲ]لِكَ تَخْفِي[a:936[فٌ م]ّ[u:243[ِن ر]َّبِّكُمْ وَرَحْمَ[f:937[ةٌ‌ۗ ف]َمَنِ [h:938[ٱ]عْتَدَىٰ بَعْدَ ذ[n[َٲ]لِكَ فَلَهُ[n[ۥ] عَذَابٌ أَل[p[ِي]مٌ","Эй иймон келтирганлар! Сизга ўлдирилганлар учун қасос фарз қилинди: ҳурга ҳур, қулга қул, аёлга аёл. Кимга ўз биродаридан бир нарса афв қилинса, бас, яхшилик ила сўралсин ва адо этиш ҳам яхшиликча бўлсин. Бу Роббиларингиздан енгиллик ва раҳматдир. Ундан кейин ким душманлик қилса, унга аламли азоб бор.",27,2],["وَلَكُمْ فِى [h:939[ٱ]لْقِصَاصِ حَيَ[s[و][n[ٲ][a:940[ةٌ ي]َ[o[ـٰٓ]أُ[s[وْ]لِى [h:941[ٱ]لْأَلْبَ[n[ـٰ]بِ لَعَلَّكُمْ تَتَّق[p[ُو]نَ","Сизларга қасос олишда ҳаёт бор. Эй ақл эгалари! Шоядки тақводор бўлсангиз.",27,2],["كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ [h:942[ٱ]لْمَوْتُ إِ[f:943[ن ت]َرَكَ خَيْرًا [h:944[ٱ]لْوَصِيَّةُ لِلْو[n[َٲ]لِدَيْنِ وَ[h:945[ٱ]لْأَ[q:945[قْ]رَبِينَ بِ[h:934[ٱ]لْمَعْرُوفِ‌ۖ حَقًّا عَلَى [h:946[ٱ]لْمُتَّق[p[ِي]نَ","Сизлардан бирортангизга ўлим келганда, агар у бойлик қолдираётган бўлса, ота-онаси ва яқинларига тўғрилик билан васият қилиш тақводорларнинг бурчи сифатида фарз қилинди.",27,2],["فَم[i:947[َنۢ ب]َدَّلَهُ[n[ۥ] بَعْدَمَا سَمِعَهُ[n[ۥ] فَإِ[g[نّ]َم[o[َآ] إِثْمُهُ[n[ۥ] عَلَى [h:289[ٱ]لَّذِينَ يُبَدِّلُونَهُ[o[ۥٓ‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَمِيعٌ عَل[p[ِي]مٌ","Ким уни эшитгандан сўнг ўзгартирса, бас, гуноҳи фақат ўзгартирганларнинг ўзига бўлади. Албатта, Аллоҳ эшитувчи ва билувчидир.",27,2],["فَمَنْ خَافَ م[a:948[ِن م]ُّو[f:949[صٍ ج]َنَفًا أَوْ إِثْ[f:950[مًا ف]َأَصْلَحَ بَيْنَهُمْ فَل[o[َآ] إِثْمَ عَلَيْهِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Кимки васият қилувчидан тойилиш ёки гуноҳ содир бўлишидан қўрқса, бас, уларнинг орасини ислоҳ қилса, унга гуноҳ бўлмайди. Албатта, Аллоҳ мағфиратли ва раҳмли зотдир.",28,2],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] كُتِبَ عَلَيْكُمُ [h:951[ٱ][l[ل]صِّيَامُ كَمَا كُتِبَ عَلَى [h:289[ٱ]لَّذِينَ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ لَعَلَّكُمْ تَتَّق[p[ُو]نَ","Эй иймон келтирганлар! Сизлардан аввалгиларга фарз қилганидек, сизларга ҳам рўза фарз қилинди. Шоядки тақводор бўлсангиз.",28,2],["أَيَّا[a:952[مًا م]َّعْدُود[n[َٲ][f:953[تٍ‌ۚ ف]َمَ[f:954[ن ك]َانَ مِ[f:344[نك][w:955[ُم م]َّرِيضًا أَوْ عَلَىٰ سَفَ[f:956[رٍ ف]َعِدَّ[a:957[ةٌ م]ِّنْ أَيَّامٍ أُخَرَ‌ۚ وَعَلَى [h:958[ٱ]لَّذِينَ يُطِيقُونَهُ[n[ۥ] فِ[q:959[دْ]يَ[f:960[ةٌ ط]َعَامُ مِسْكِي[f:961[نٍ‌ۖ ف]َمَ[f:962[ن ت]َطَوَّعَ خَيْ[f:963[رًا ف]َهُوَ خَيْ[u:964[رٌ ل]َّهُ[n[ۥ]‌ۚ وَأَ[f:965[ن ت]َصُومُو[s[اْ] خَيْ[u:263[رٌ ل]َّكُمْ‌ۖ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","Саноқли кунлар. Сизлардан ким бемор ёки мусофир бўлса, бас, саноғини бошқа кунларда тутади. Уни қийналиб тутадиганлар зиммасида бир мискин таоми фидя лозимдир. Ким яхшиликни ўз ихтиёри ила қилса, ўзи учун яхшидир. Агар билсангиз, рўза тутмоғингиз сиз учун яхшидир.",28,2],["شَهْرُ رَمَضَانَ [h:966[ٱ]لَّذ[o[ِىٓ] أُ[f:17[نز]ِلَ فِيهِ [h:967[ٱ]لْقُرْءَانُ هُ[u:968[دًى ل]ِّل[g[نّ]َاسِ وَبَيِّنَ[n[ـٰ][a:969[تٍ م]ِّنَ [h:970[ٱ]لْهُدَىٰ وَ[h:971[ٱ]لْفُرْقَانِ‌ۚ فَمَ[f:972[ن ش]َهِدَ مِ[f:973[نك]ُمُ [h:974[ٱ][l[ل]شَّهْرَ فَلْيَصُمْهُ‌ۖ وَمَ[f:975[ن ك]َانَ مَرِيضًا أَوْ عَلَىٰ سَفَ[f:956[رٍ ف]َعِدَّ[a:957[ةٌ م]ِّنْ أَيَّامٍ أُخَرَ‌ۗ يُرِيدُ [h:976[ٱ]للَّهُ بِكُمُ [h:977[ٱ]لْيُسْرَ وَلَا يُرِيدُ بِكُمُ [h:978[ٱ]لْعُسْرَ وَلِتُكْمِلُو[s[اْ] [h:979[ٱ]لْعِدَّةَ وَلِتُكَبِّرُو[s[اْ] [h:980[ٱ]للَّهَ عَلَىٰ مَا هَدَ[n[ٮٰ]كُمْ وَلَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Рамазон ойики, унда одамларга ҳидоят ҳамда ҳидояту фурқондан иборат очиқ баёнотлар бўлиб, Қуръон туширилгандир. Сиздан ким у ойда ҳозир бўлса, рўзасини тутсин. Ким бемор ёки сафарда бўлса, бас, саноғини бошқа кунлардан тутади. Аллоҳ сизларга енгилликни хоҳлайди ва сизларга қийинчиликни хоҳламайди. Саноғини мукаммал қилишингиз ва сизни ҳидоятга бошлаган Аллоҳни улуғлашингиз учун. Шоядки шукр қилсаларингиз.",28,2],["وَإِذَا سَأَلَكَ عِبَادِى عَ[g[نّ]ِى فَإِ[g[نّ]ِى قَرِيبٌ‌ۖ أُجِيبُ دَعْوَةَ [h:981[ٱ][l[ل]دَّاعِ إِذَا دَعَانِ‌ۖ فَلْيَسْتَجِيبُو[s[اْ] لِى وَلْيُؤْمِنُو[s[اْ] بِى لَعَلَّهُمْ يَرْشُد[p[ُو]نَ","Агар бандаларим сендан Мени сўрасалар, Мен, албатта, яқинман. Дуо қилгувчи дуо қилганда ижобат қиламан. Бас, Менга ҳам ижобат қилсинлар ва иймон келтирсинлар. Шоядки тўғри йўлни топсалар.",28,2],["أُحِلَّ لَكُمْ لَيْلَةَ [h:982[ٱ][l[ل]صِّيَامِ [h:983[ٱ][l[ل]رَّفَثُ إِلَىٰ نِس[o[َا]ٓئِكُمْ‌ۚ هُ[g[نّ]َ لِبَا[u:984[سٌ ل]َّكُمْ وَأَ[f:98[نت]ُمْ لِبَا[u:985[سٌ ل]َّهُ[g[نّ]َ‌ۗ عَلِمَ [h:986[ٱ]للَّهُ أَ[g[نّ]َكُمْ كُ[f:100[نت]ُمْ تَخْتَانُونَ أَ[f:221[نف]ُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَ[f:255[نك]ُمْ‌ۖ فَ[h:987[ٱ]لْـَٔ[n[ـٰ]نَ بَ[n[ـٰ]شِرُوهُ[g[نّ]َ وَ[h:988[ٱ][q:988[بْ]تَغُو[s[اْ] مَا كَتَبَ [h:989[ٱ]للَّهُ لَكُمْ‌ۚ وَكُلُو[s[اْ] وَ[h:300[ٱ]شْرَبُو[s[اْ] حَتَّىٰ يَتَبَيَّنَ لَكُمُ [h:990[ٱ]لْخَيْطُ [h:991[ٱ]لْأَ[q:992[بْ]يَضُ مِنَ [h:993[ٱ]لْخَيْطِ [h:994[ٱ]لْأَسْوَدِ مِنَ [h:995[ٱ]لْفَ[q:996[جْ]رِ‌ۖ ثُ[g[مّ]َ أَتِ[g[مّ]ُو[s[اْ] [h:997[ٱ][l[ل]صِّيَامَ إِلَى [h:998[ٱ]لَّيْلِ‌ۚ وَلَا تُبَ[n[ـٰ]شِرُوهُ[g[نّ]َ وَأَ[f:98[نت]ُمْ عَ[n[ـٰ]كِفُونَ فِى [h:999[ٱ]لْمَسَ[n[ـٰ]جِدِ‌ۗ تِلْكَ حُدُودُ [h:1000[ٱ]للَّهِ فَلَا تَ[q:1001[قْ]رَبُوهَا‌ۗ كَذ[n[َٲ]لِكَ يُبَيِّنُ [h:1002[ٱ]للَّهُ ءَايَ[n[ـٰ]تِه[n[ِۦ] لِل[g[نّ]َاسِ لَعَلَّهُمْ يَتَّق[p[ُو]نَ","Сизларга рўза кечасида хотинларингизга яқинлик қилиш ҳалол қилинди. Улар сизга либосдир, сиз уларга либосдирсиз. Аллоҳ сизнинг ўзингизга ҳиёнат қилаётганингизни билди, тавбангизни қабул этди ва сизларни афв этди. Энди уларга яқинлашаверинг ва Аллоҳ сизга ёзган нарсани талаб қилинг. Тонг пайтида оқ ип қора ипдан ажрагунча еб-ичаверинг. Сўнгра рўзани кечасигача батамом қилинг. Масжидларда, эътикофдалигингизда уларга яқинлик қилманг. Булар Аллоҳнинг чегараларидир, унга яқинлашманг. Аллоҳ одамларга Ўз оятларини шундоқ баён этади. Шоядки тақво қилсалар.",29,2],["وَلَا تَأْكُل[o[ُوٓ][s[اْ] أَمْو[n[َٲ]لَك[c:1003[ُم ب]َيْنَك[c:1004[ُم ب]ِ[h:212[ٱ]لْبَ[n[ـٰ]طِلِ وَتُ[q:1005[دْ]لُو[s[اْ] بِه[o[َآ] إِلَى [h:1006[ٱ]لْحُكَّامِ لِتَأْكُلُو[s[اْ] فَرِي[a:1007[قًا م]ِّنْ أَمْو[n[َٲ]لِ [h:1008[ٱ][l[ل][g[نّ]َاسِ بِ[h:434[ٱ]لْإِثْمِ وَأَ[f:98[نت]ُمْ تَعْلَم[p[ُو]نَ","Бир-бирларингизнинг молларингизни ботил йўл билан еманг. Билиб туриб одамларнинг молларидан бир қисмини ейишингиз учун уни ҳокимларга гуноҳкорона ташламанг.",29,2],["۞ يَسْــَٔلُونَكَ عَنِ [h:1009[ٱ]لْأَهِلَّةِ‌ۖ قُلْ هِىَ مَو[n[َٲ]قِيتُ لِل[g[نّ]َاسِ وَ[h:1010[ٱ]لْحَجِّ‌ۗ وَلَيْسَ [h:1011[ٱ]لْبِرُّ بِأَ[f:1012[ن ت]َأْتُو[s[اْ] [h:1013[ٱ]لْبُيُوتَ مِ[f:1014[ن ظ]ُهُورِهَا وَلَ[n[ـٰ]كِ[g[نّ]َ [h:905[ٱ]لْبِرَّ مَنِ [h:1015[ٱ]تَّقَىٰ‌ۗ وَأْتُو[s[اْ] [h:1016[ٱ]لْبُيُوتَ مِنْ أَ[q:1017[بْ]و[n[َٲ]بِهَا‌ۚ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ لَعَلَّكُمْ تُفْلِح[p[ُو]نَ","Сендан ҳилоллар ҳақида сўрарлар. «Улар одамлар ва ҳаж учун вақт ўлчовидир», деб айт. Яхшилик уйларнинг орқасидан киришингизда эмас, лекин яхшилик, ким тақводорлик қилса, шундадир. Ва уйларга эшикларидан киринг. Аллоҳга тақво қилинг. Шоядки нажот топсангиз.",29,2],["وَقَ[n[ـٰ]تِلُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ [h:1020[ٱ]لَّذِينَ يُقَ[n[ـٰ]تِلُونَكُمْ وَلَا تَعْتَد[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُحِبُّ [h:1021[ٱ]لْمُعْتَد[p[ِي]نَ","Сизга уруш қилаётганларга қарши Аллоҳнинг йўлида уруш қилинг. Ва тажовузкор бўлманг. Албатта, Аллоҳ тажовузкор бўлганларни хуш кўрмас.",29,2],["وَ[h:9999[ٱ][q:1022[قْ]تُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوه[w:1023[ُم م]ِّنْ حَيْثُ أَخْرَجُوكُمْ‌ۚ وَ[h:1024[ٱ]لْفِتْنَةُ أَشَدُّ مِنَ [h:1025[ٱ]لْقَتْلِ‌ۚ وَلَا تُقَ[n[ـٰ]تِلُوهُمْ عِ[f:264[ند]َ [h:1026[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ حَتَّىٰ يُقَ[n[ـٰ]تِلُوكُمْ فِيهِ‌ۖ فَإِ[f:1027[ن ق]َ[n[ـٰ]تَلُوكُمْ فَ[h:1028[ٱ][q:1028[قْ]تُلُوهُمْ‌ۗ كَذ[n[َٲ]لِكَ جَز[o[َا]ٓءُ [h:1029[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Уларни топган ерингизда қатл қилинг. Ва сизларни чиқарган жойдан уларни ҳам чиқаринг. Фитна қатл этишдан ёмонроқдир. Масжидул Ҳаром олдида сизга қарши урушмагунларича, сиз урушманг. Агар урушсалар, бас, сиз ҳам урушинг. Кофирларнинг жазоси шундай.",30,2],["فَإِنِ [h:1030[ٱ][f:1031[نت]َهَوْ[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Агар тўхтасалар, албатта, Аллоҳ мағфиратли ва раҳмлидир.",30,2],["وَقَ[n[ـٰ]تِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَ[a:1032[ةٌ و]َيَكُونَ [h:1033[ٱ][l[ل]دِّينُ لِلَّهِ‌ۖ فَإِنِ [h:1030[ٱ][f:1031[نت]َهَوْ[s[اْ] فَلَا عُ[q:1034[دْ]و[n[َٲ]نَ إِلَّا عَلَى [h:1035[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Фитна бўлмаслиги ва дин Аллоҳга бўлиши учун улар билан жанг қилинг. Агар тўхтасалар, золимлардан бошқаларга душманлик йўқ.",30,2],["ٱ[l[ل]شَّهْرُ [h:1036[ٱ]لْحَرَامُ بِ[h:1037[ٱ][l[ل]شَّهْرِ [h:1038[ٱ]لْحَرَامِ وَ[h:1039[ٱ]لْحُرُمَ[n[ـٰ]تُ قِصَا[f:1040[صٌ‌ۚ ف]َمَنِ [h:938[ٱ]عْتَدَىٰ عَلَيْكُمْ فَ[h:1041[ٱ]عْتَدُو[s[اْ] عَلَيْهِ بِمِثْلِ مَا [h:1042[ٱ]عْتَدَىٰ عَلَيْكُمْ‌ۚ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ مَعَ [h:1044[ٱ]لْمُتَّق[p[ِي]نَ","Ҳаром ойга ҳаром ой. Ҳаром қилинган нарсаларда қасос бор. Ким сизга душманлик қилса, сиз ҳам унга шунга ўхшаш душманлик қилинг. Ва Аллоҳга тақво қилинг ҳамда, билингки, албатта, Аллоҳ тақводорлар биландир.",30,2],["وَأَ[f:1045[نف]ِقُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ وَلَا تُلْقُو[s[اْ] بِأَيْدِيكُمْ إِلَى [h:1046[ٱ][l[ل]تَّهْلُكَةِ‌ۛ وَأَحْسِن[o[ُوٓ[s[اْ]‌ۛ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُحِبُّ [h:1047[ٱ]لْمُحْسِن[p[ِي]نَ","Ва Аллоҳнинг йўлида нафақа қилинг. Ўзингизни ҳалокатга дучор қилманг. Эҳсон қилинг, албатта. Аллоҳ эҳсон қилувчиларни хуш кўради.",30,2],["وَأَتِ[g[مّ]ُو[s[اْ] [h:1048[ٱ]لْحَجَّ وَ[h:1049[ٱ]لْعُمْرَةَ لِلَّهِ‌ۚ فَإِنْ أُحْصِرْتُمْ فَمَا [h:1050[ٱ]سْتَيْسَرَ مِنَ [h:1051[ٱ]لْهَ[q:1052[دْ]ىِ‌ۖ وَلَا تَحْلِقُو[s[اْ] رُءُوسَكُمْ حَتَّىٰ يَ[q:1053[بْ]لُغَ [h:1054[ٱ]لْهَ[q:1055[دْ]ىُ مَحِلَّهُ[n[ۥ]‌ۚ فَمَ[f:954[ن ك]َانَ مِ[f:344[نك][w:955[ُم م]َّرِيضًا أَوْ بِه[o[ِۦٓ] أَ[a:1056[ذًى م]ّ[u:1057[ِن ر]َّأْسِه[n[ِۦ] فَفِ[q:1058[دْ]يَ[a:1059[ةٌ م]ِّ[f:1060[ن ص]ِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُ[f:1061[كٍ‌ۚ ف]َإِذ[o[َآ] أَمِ[f:1062[نت]ُمْ فَمَ[f:1063[ن ت]َمَتَّعَ بِ[h:1064[ٱ]لْعُمْرَةِ إِلَى [h:1065[ٱ]لْحَجِّ فَمَا [h:1050[ٱ]سْتَيْسَرَ مِنَ [h:1051[ٱ]لْهَ[q:1052[دْ]ىِ‌ۚ فَم[u:1066[َن ل]َّمْ يَجِ[q:1067[دْ] فَصِيَامُ ثَلَ[n[ـٰ]ثَةِ أَيَّا[f:1068[مٍ ف]ِى [h:1069[ٱ]لْحَجِّ وَسَ[q:1070[بْ]عَةٍ إِذَا رَجَعْتُمْ‌ۗ تِلْكَ عَشَرَ[f:1071[ةٌ ك]َامِلَ[f:1072[ةٌ‌ۗ ذ][n[َٲ]لِكَ لِم[u:1073[َن ل]َّمْ يَكُنْ أَهْلُهُ[n[ۥ] حَاضِرِى [h:1074[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ‌ۚ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ شَدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Аллоҳ учун ҳаж ва умрани тугал адо этинг. Агар ушланиб қолсангиз, муяссар бўлганича қурбонлик қилинг. Қурбонлик ўз жойига емагунча, сочингизни олдирманг. Сиздан ким бемор бўлса ёки бошида озор берувчи нарса бўлса, рўза тутиш ёки садақа бериш ёхуд қурбонлик сўйиш ила тўлов тўласин. Агар тинч бўлсангиз, ким умрадан ҳажгача ҳузур қилган бўлса, муяссар бўлган қурбонликни қилсин. Ким топмаса, уч кун ҳажда, етти кун қайтганингизда–ҳаммаси ўн кун тўлиқ рўза тутсин. Бу аҳли Масжидул Ҳаромда яшамайдиганлар учун. Ва Аллоҳга тақво қилинг ҳамда, билингки, албатта, Аллоҳ иқоби шиддатли зотдир.",30,2],["ٱلْحَجُّ أَشْهُ[a:1076[رٌ م]َّعْلُومَ[n[ـٰ][f:1077[تٌ‌ۚ ف]َمَ[f:1078[ن ف]َرَضَ فِيهِ[g[نّ]َ [h:1079[ٱ]لْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى [h:1069[ٱ]لْحَجِّ‌ۗ وَمَا تَفْعَلُو[s[اْ] مِنْ خَيْ[a:1080[رٍ ي]َعْلَمْهُ [h:1081[ٱ]للَّهُ‌ۗ وَتَزَوَّدُو[s[اْ] فَإِ[g[نّ]َ خَيْرَ [h:1082[ٱ][l[ل]زَّادِ [h:1083[ٱ][l[ل]تَّ[q:1084[قْ]وَىٰ‌ۚ وَ[h:1085[ٱ]تَّقُونِ يَ[o[ـٰٓ]أُ[s[وْ]لِى [h:941[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","Ҳаж маълум ойлардир. Кимки уларда ўзига ҳажни фарз қилса, ҳажда шаҳвоний нарсалар, фисқ ва жанжал йўқдир. Нима яхшилик қилсангиз, Аллоҳ уни билади. Озуқа олинг, энг яхши озуқа тақводир. Менга тақво қилинг, эй ақл эгалари!",31,2],["لَيْسَ عَلَيْكُمْ جُنَاحٌ أَ[f:1086[ن ت]َ[q:1087[بْ]تَغُو[s[اْ] فَضْل[a:1088[اً م]ّ[u:243[ِن ر]َّبِّكُمْ‌ۚ فَإِذ[o[َآ] أَفَضْت[w:1089[ُم م]ِّنْ عَرَفَ[n[ـٰ][f:1090[تٍ ف]َ[h:1091[ٱ]ذْكُرُو[s[اْ] [h:1092[ٱ]للَّهَ عِ[f:264[ند]َ [h:1093[ٱ]لْمَشْعَرِ [h:1094[ٱ]لْحَرَامِ‌ۖ وَ[h:1095[ٱ]ذْكُرُوهُ كَمَا هَدَ[n[ٮٰ]كُمْ وَإِ[f:99[ن ك]ُ[f:100[نت][w:1096[ُم م]ِّ[f:1097[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] لَمِنَ [h:1099[ٱ][l[ل]ضّ[m[َا]ٓلّ[p[ِي]نَ","Сизга ўз Роббингиздан фазл исташингизда гуноҳ йўқдир. Арофатдан қайтиб тушганингизда, Аллоҳни машъарул ҳаромда зикр қилинг. Илгари адашганлардан бўлсангиз ҳам, сизни ҳидоятга бошлагани учун Уни зикр қилинг.",31,2],["ثُ[g[مّ]َ أَفِيضُو[s[اْ] مِنْ حَيْثُ أَفَاضَ [h:1100[ٱ][l[ل][g[نّ]َاسُ وَ[h:1101[ٱ]سْتَغْفِرُو[s[اْ] [h:1102[ٱ]للَّهَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Сўнгра одамлар қайтиб тушган жойдан тушинглар. Ва Аллоҳга истиғфор айтинглар. Албатта, Аллоҳ мағфиратли, раҳмли зотдир.",31,2],["فَإِذَا قَضَيْت[w:1103[ُم م]َّنَ[n[ـٰ]سِكَكُمْ فَ[h:1091[ٱ]ذْكُرُو[s[اْ] [h:1092[ٱ]للَّهَ كَذِكْرِكُمْ ءَاب[o[َا]ٓءَكُمْ أَوْ أَشَدَّ ذِكْ[f:1104[رًا‌ۗ ف]َمِنَ [h:1105[ٱ][l[ل][g[نّ]َاسِ م[a:31[َن ي]َقُولُ رَبَّن[o[َآ] ءَاتِنَا فِى [h:599[ٱ][l[ل]دُّنْيَا وَمَا لَهُ[n[ۥ] فِى [h:536[ٱ]لْأَخِرَةِ مِنْ خَلَ[p[ـٰ][q[ق]ٍ","Ибодатларингизни тугатганигизда, Аллоҳни оталарингизни эслагандек, балки ундан ҳам кучлироқ эсланг. Одамлардан баъзилари: «Роббимиз бизга бу дунёда бергин», дейди ва унга охиратда насиба йўқдир.",31,2],["وَمِنْه[w:1106[ُم م]ّ[a:31[َن ي]َقُولُ رَبَّن[o[َآ] ءَاتِنَا فِى [h:599[ٱ][l[ل]دُّنْيَا حَسَنَ[a:1107[ةً و]َفِى [h:1108[ٱ]لْأَخِرَةِ حَسَنَ[a:1109[ةً و]َقِنَا عَذَابَ [h:1110[ٱ][l[ل][g[نّ][p[َا]رِ","Ва улардан баъзилари: «Роббимиз, бизга бу дунёда ҳам яхшиликни, охиратда ҳам яхшиликни бергин ва бизни дўзах олови азобидан сақлагин», дейди.\"",31,2],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ نَصِي[a:1111[بٌ م]ِّ[g[مّ]َا كَسَبُو[s[اْ‌ۚ] وَ[h:72[ٱ]للَّهُ سَرِيعُ [h:1112[ٱ]لْحِس[p[َا][q[ب]ِ","Ана ўшаларга қилган касбларидан насиба бор. Ва Аллоҳ тез ҳисоб қилувчидир.",31,2],["۞ وَ[h:9999[ٱ]ذْكُرُو[s[اْ] [h:1113[ٱ]للَّهَ ف[o[ِىٓ] أَيَّا[a:1114[مٍ م]َّعْدُود[n[َٲ][f:953[تٍ‌ۚ ف]َمَ[f:1115[ن ت]َعَجَّلَ فِى يَوْمَيْنِ فَل[o[َآ] إِثْمَ عَلَيْهِ وَمَ[f:1116[ن ت]َأَخَّرَ فَل[o[َآ] إِثْمَ عَلَيْهِ‌ۚ لِمَنِ [h:1117[ٱ]تَّقَىٰ‌ۗ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َكُمْ إِلَيْهِ تُحْشَر[p[ُو]نَ","Аллоҳни саноқли кунларда эсланг. Бас, ким икки кундан кейин шошилиб, кетса, унга гуноҳ йўқ. Ким кечикиб қолса, унга гуноҳ йўқ. Тақво қилувчилар учун. Аллоҳга тақво қилинглар ва, билингларки, албатта сиз Унга тўпланурсиз.",32,2],["وَمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ م[a:1118[َن ي]ُعْجِبُكَ قَوْلُهُ[n[ۥ] فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا وَيُشْهِدُ [h:1119[ٱ]للَّهَ عَلَىٰ مَا فِى قَلْبِه[n[ِۦ] وَهُوَ أَلَدُّ [h:1120[ٱ]لْخِص[p[َا]مِ","Одамлар ичида дунё ҳаётидаги гапи сени ажаблантирадиганлари бор. У қалбидаги нарсага Аллоҳни гувоҳ ҳам қилади. Ҳолбуки, у ашаддий хусуматчидир.",32,2],["وَإِذَا تَوَلَّىٰ سَعَىٰ فِى [h:44[ٱ]لْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ [h:1121[ٱ]لْحَرْثَ وَ[h:1122[ٱ][l[ل][g[نّ]َسْلَ‌ۗ وَ[h:72[ٱ]للَّهُ لَا يُحِبُّ [h:1123[ٱ]لْفَس[p[َا][q[د]َ","Ва бурилиб кетганда, ер юзида фасод учун ҳамда экин ва насилни ҳалок қилиш учун ҳаракат этади. Ва ҳолбуки, Аллоҳ фасодни хуш кўрмас.",32,2],["وَإِذَا قِيلَ لَهُ [h:1124[ٱ]تَّقِ [h:1125[ٱ]للَّهَ أَخَذَتْهُ [h:1126[ٱ]لْعِزَّةُ بِ[h:434[ٱ]لْإِثْمِ‌ۚ فَحَسْبُهُ[n[ۥ] جَهَ[g[نّ]َمُ‌ۚ وَلَبِئْسَ [h:1127[ٱ]لْمِه[p[َا][q[د]ُ","Агар унга, Аллоҳдан қўрқгин, дейилса, уни кибру ҳавоси гуноҳга етаклайди. Жаҳаннам унга етарлидир. У қандай ҳам ёмон ўрин-а?",32,2],["وَمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ م[a:1128[َن ي]َشْرِى نَفْسَهُ [h:1129[ٱ][q:1130[بْ]تِغ[o[َا]ٓءَ مَرْضَاتِ [h:1131[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ رَءُو[i:1132[فُۢ ب]ِ[h:1133[ٱ]لْعِب[p[َا][q[د]ِ","Ва одамлардан Аллоҳнинг розилигини тилаб жонини сотадиганлар бор. Ва Аллоҳ бандаларга меҳрибондир.",32,2],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:1134[ٱ][q:278[دْ]خُلُو[s[اْ] فِى [h:1135[ٱ][l[ل]سِّلْمِ ك[m[َا]ٓفَّ[a:1136[ةً و]َلَا تَتَّبِعُو[s[اْ] خُطُو[n[َٲ]تِ [h:872[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] لَكُمْ عَدُ[a:873[وٌّ م]ُّب[p[ِي]نٌ","Эй иймон келтирганлар! Исломга тўлиғича киринг. Ва шайтоннинг изидан эргашманг. Албатта, у сизга очиқ душмандир.",32,2],["فَإِ[f:1137[ن ز]َلَلْت[w:1138[ُم م]ّ[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَتْكُمُ [h:1139[ٱ]لْبَيِّنَ[n[ـٰ]تُ فَ[h:1140[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ عَزِيزٌ حَك[p[ِي]مٌ","Агар очиқ баёнотлар келгандан кейин ҳам тойилсангиз, билингки, албатта, Аллоҳ азиз ва ҳикматлидир.",32,2],["هَلْ يَ[f:1141[نظ]ُرُونَ إِلّ[o[َآ] أ[a:1142[َن ي]َأْتِيَهُمُ [h:1143[ٱ]للَّهُ فِى ظُلَ[a:1144[لٍ م]ِّنَ [h:1145[ٱ]لْغَمَامِ وَ[h:1146[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ وَقُضِىَ [h:1147[ٱ]لْأَمْرُ‌ۚ وَإِلَى [h:1148[ٱ]للَّهِ تُرْجَعُ [h:1149[ٱ]لْأُم[p[ُو]رُ","Улар Аллоҳ ва фаришталар сояли булутларда келиши ҳамда ишнинг тугашидан бошқага интизор бўлмаяптилар шекилли?! Ва барча ишлар Аллоҳга қайтажак.",32,2],["سَلْ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ كَمْ ءَاتَيْنَ[n[ـٰ]ه[w:1150[ُم م]ِّنْ ءَايَ[i:1151[ةِۭ ب]َيِّنَ[a:1152[ةٍ‌ۗ و]َم[a:1153[َن ي]ُبَدِّلْ نِعْمَةَ [h:1154[ٱ]للَّهِ م[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَتْهُ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ شَدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Бани Исроилдан уларга қанча оятларни берганимизни сўра. Кимки ўзига келган Аллоҳнинг неъматини ўзгартирса, бас, албатта, Аллоҳ иқоби қаттиқ зотдир.",33,2],["زُيِّنَ لِلَّذِينَ كَفَرُو[s[اْ] [h:1155[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَا وَيَسْخَرُونَ مِنَ [h:523[ٱ]لَّذِينَ ءَامَنُو[s[اْ‌ۘ] وَ[h:37[ٱ]لَّذِينَ [h:1157[ٱ]تَّقَوْ[s[اْ] فَوْقَهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۗ وَ[h:72[ٱ]للَّهُ يَرْزُقُ م[a:476[َن ي]َش[o[َا]ٓءُ بِغَيْرِ حِس[p[َا][q[ب]ٍ","Куфр келтирганларга бу дунё ҳаёти зийнатланди ва улар иймон келтирганларни масхара қиладилар. Ва ҳолбуки, қиёмат куни тақво қилганлар улардан устундир. Аллоҳ кимни хоҳласа, беҳисоб ризқ беради.",33,2],["كَانَ [h:1158[ٱ][l[ل][g[نّ]َاسُ أُ[g[مّ]َ[a:1159[ةً و][n[َٲ]حِدَ[f:1160[ةً ف]َبَعَثَ [h:1161[ٱ]للَّهُ [h:1162[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ مُبَشِّرِينَ وَمُ[f:1163[نذ]ِرِينَ وَأَ[f:91[نز]َلَ مَعَهُمُ [h:1164[ٱ]لْكِتَ[n[ـٰ]بَ بِ[h:370[ٱ]لْحَقِّ لِيَحْكُمَ بَيْنَ [h:1165[ٱ][l[ل][g[نّ]َاسِ فِيمَا [h:1166[ٱ]خْتَلَفُو[s[اْ] فِيهِ‌ۚ وَمَا [h:1167[ٱ]خْتَلَفَ فِيهِ إِلَّا [h:778[ٱ]لَّذِينَ أُوتُوهُ م[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَتْهُمُ [h:1168[ٱ]لْبَيِّنَ[n[ـٰ]تُ بَغْي[i:1169[َۢا ب]َيْنَهُمْ‌ۖ فَهَدَى [h:1170[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لِمَا [h:1172[ٱ]خْتَلَفُو[s[اْ] فِيهِ مِنَ [h:1173[ٱ]لْحَقِّ بِإِذْنِه[n[ِۦ]‌ۗ وَ[h:72[ٱ]للَّهُ يَهْدِى م[a:476[َن ي]َش[o[َا]ٓءُ إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Одамлар бир миллат эдилар. Бас, Аллоҳ хушхабар ва огоҳлантириш берувчи Набийларни юборди ва уларга одамлар ўртасида, улар ихтилоф қилган нарсаларда ҳукм қилиш учун ҳақ китоб туширди. У тўғрисида ихтилофни очиқ ҳужжатлар келгандан сўнг, кимга берилган бўлса, ўшаларгина ҳаддан ошиб қилдилар. Иймон келтирганларни ҳақ тўғрисида ихтилоф қилган нарсаларида Аллоҳ Ўз изни ила ҳидоятга солади. Аллоҳ кимни хоҳласа, тўғри йўлга бошлайди.",33,2],["أَمْ حَسِ[q:1174[بْ]تُمْ أَ[f:1175[ن ت]َ[q:1176[دْ]خُلُو[s[اْ] [h:1177[ٱ]لْجَ[g[نّ]َةَ وَلَ[g[مّ]َا يَأْتِك[w:1178[ُم م]َّثَلُ [h:1179[ٱ]لَّذِينَ خَلَوْ[s[اْ] مِ[f:85[ن ق]َ[q:86[بْ]لِك[w:1180[ُم‌ۖ م]َّسَّتْهُمُ [h:1181[ٱ]لْبَأْس[o[َا]ٓءُ وَ[h:1182[ٱ][l[ل]ضَّرّ[o[َا]ٓءُ وَزُلْزِلُو[s[اْ] حَتَّىٰ يَقُولَ [h:1183[ٱ][l[ل]رَّسُولُ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مَعَهُ[n[ۥ] مَتَىٰ نَصْرُ [h:1184[ٱ]للَّهِ‌ۗ أَل[o[َآ] إِ[g[نّ]َ نَصْرَ [h:1185[ٱ]للَّهِ قَر[p[ِي][q[ب]ٌ","Сиздан аввал ўтганларга келганга ўхшаш нарса сизларга келмасдан туриб, жаннатга кирамиз, деб ўйладингизми? Уларни бало ва мусибатлар тутган ва ларзага туширилганлар. Ҳаттоки, Пайғамбар ва у билан иймон келтирганлар: «Аллоҳнинг нусрати қачон бўлади?» деганлар. Огоҳ бўлинглар, албатта, Аллоҳнинг нусрати яқиндир.",33,2],["يَسْــَٔلُونَكَ مَاذَا يُ[f:16[نف]ِقُونَ‌ۖ قُلْ م[o[َآ] أَ[f:1186[نف]َ[q:1186[قْ]ت[w:1187[ُم م]ِّنْ خَيْ[f:1188[رٍ ف]َلِلْو[n[َٲ]لِدَيْنِ وَ[h:945[ٱ]لْأَ[q:945[قْ]رَبِينَ وَ[h:420[ٱ]لْيَتَ[n[ـٰ]مَىٰ وَ[h:421[ٱ]لْمَسَ[n[ـٰ]كِينِ وَ[h:1189[ٱ][q:1189[بْ]نِ [h:1190[ٱ][l[ل]سَّبِيلِ‌ۗ وَمَا تَفْعَلُو[s[اْ] مِنْ خَيْ[f:1191[رٍ ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ بِه[n[ِۦ] عَل[p[ِي]مٌ","Сендан нимани нафақа қилишни сўрарлар. Сен: «Нафақа қилган яхшилигингиздан ота-оналарга, яқин кишиларга, етимларга, мискинларга ва ватангадоларга бўлсин. Қандай яхшилик қилган бўлсангиз, албатта, Аллоҳ уни билувчидир», деб айт.",33,2],["كُتِبَ عَلَيْكُمُ [h:1192[ٱ]لْقِتَالُ وَهُوَ كُرْ[u:1193[هٌ ل]َّكُمْ‌ۖ وَعَسَ[o[ىٰٓ] أَ[f:1194[ن ت]َكْرَهُو[s[اْ] شَيْـ[a:1195[ـًٔا و]َهُوَ خَيْ[u:263[رٌ ل]َّكُمْ‌ۖ وَعَسَ[o[ىٰٓ] أَ[f:1196[ن ت]ُحِبُّو[s[اْ] شَيْـ[a:1195[ـًٔا و]َهُوَ شَ[u:1197[رٌّ ل]َّكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ يَعْلَمُ وَأَ[f:98[نت]ُمْ لَا تَعْلَم[p[ُو]نَ","Сизга ёқмаса ҳам, жанг қилишингиз фарз қилинди. Шоядки ёқтирмаган нарсангиз сиз учун яхши бўлса. Ва шоядки ёқтирган нарсангиз сиз учун ёмон бўлса. Аллоҳ билади, сиз билмайсиз.",34,2],["يَسْــَٔلُونَكَ عَنِ [h:1198[ٱ][l[ل]شَّهْرِ [h:1199[ٱ]لْحَرَامِ قِتَا[f:1200[لٍ ف]ِيهِ‌ۖ قُلْ قِتَا[f:1201[لٌ ف]ِيهِ كَبِي[a:1202[رٌ‌ۖ و]َصَدٌّ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ وَكُفْ[i:1204[رُۢ ب]ِه[n[ِۦ] وَ[h:1205[ٱ]لْمَسْجِدِ [h:1206[ٱ]لْحَرَامِ وَإِخْرَاجُ أَهْلِه[n[ِۦ] مِنْهُ أَكْبَرُ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۚ وَ[h:1024[ٱ]لْفِتْنَةُ أَكْبَرُ مِنَ [h:1025[ٱ]لْقَتْلِ‌ۗ وَلَا يَزَالُونَ يُقَ[n[ـٰ]تِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَ[f:1207[ن د]ِينِكُمْ إِنِ [h:1208[ٱ]سْتَطَ[n[ـٰ]عُو[s[اْ‌ۚ] وَم[a:1209[َن ي]َرْتَدِ[q:1210[دْ] مِ[f:344[نك]ُمْ عَ[f:1211[ن د]ِينِه[n[ِۦ] فَيَمُتْ وَهُوَ كَافِ[f:1212[رٌ ف]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ حَبِطَتْ أَعْمَ[n[ـٰ]لُهُمْ فِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Сендан ҳаром ойда уруш қилиш ҳақида сўрайдилар. Сен: «Унда уруш қилиш катта гуноҳ. Аллоҳнинг йўлидан тўсиш, унга куфр келтириш, Масжидул Ҳаромдан тўсиш, унинг аҳлини ундан чиқариш Аллоҳнинг ҳузурида энг катта гуноҳдир. Фитна ўлдиришдан каттароқдир», деб айт. Улар агар қодир бўлсалар, сизларни динингиздан қайтаргунларича сизга қарши уруш қилаверадилар. Сиздан кимки диндан қайтиб, кофир ҳолида ўлиб кетса, ана ўшалар бу дунёю охиратда амали ҳабата бўлганлардир. Ана ўшалар дўзах эгаларидир. Улар унда абадий қолгувчилардир.",34,2],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَ[h:37[ٱ]لَّذِينَ هَاجَرُو[s[اْ] وَجَ[n[ـٰ]هَدُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يَرْجُونَ رَحْمَتَ [h:1214[ٱ]للَّهِ‌ۚ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Албатта, иймон келтирганлар, ҳижрат қилганлар ва Аллоҳнинг йўлида жиҳод қилганлар–ана ўшалар Аллоҳнинг раҳматини умид қиладилар. Аллоҳ мағфиратли ва раҳмли зотдир.",34,2],["۞ يَسْــَٔلُونَكَ عَنِ [h:1215[ٱ]لْخَمْرِ وَ[h:1216[ٱ]لْمَيْسِرِ‌ۖ قُلْ فِيهِم[o[َآ] إِثْ[f:1217[مٌ ك]َبِي[a:1218[رٌ و]َمَنَ[n[ـٰ]فِعُ لِل[g[نّ]َاسِ وَإِثْمُهُم[o[َآ] أَكْبَرُ م[a:1219[ِن ن]َّفْعِهِمَا‌ۗ وَيَسْــَٔلُونَكَ مَاذَا يُ[f:16[نف]ِقُونَ قُلِ [h:1220[ٱ]لْعَفْوَ‌ۗ كَذ[n[َٲ]لِكَ يُبَيِّنُ [h:1002[ٱ]للَّهُ لَكُمُ [h:1221[ٱ]لْأَيَ[n[ـٰ]تِ لَعَلَّكُمْ تَتَفَكَّر[p[ُو]نَ","Сендан хамр ва қимор ҳақида сўрарлар. Сен: «Иккисида катта гуноҳ ва кишилар учун манфаат бор ва гуноҳлари нафларидан каттадир», деб айт. Ва сендан нимани нафақа қилишни сўрарлар. Сен: «Ортиқчасини», деб айт. Аллоҳ шундоқ қилиб сизга Ўз оятларини баён қилади. Шоядки тафаккур қилсангиз.",34,2],["فِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ‌ۗ وَيَسْــَٔلُونَكَ عَنِ [h:1222[ٱ]لْيَتَ[n[ـٰ]مَىٰ‌ۖ قُلْ إِصْلَا[u:1223[حٌ ل]َّهُمْ خَيْ[a:1224[رٌ‌ۖ و]َإِ[f:1225[ن ت]ُخَالِطُوهُمْ فَإِخْو[n[َٲ]نُكُمْ‌ۚ وَ[h:72[ٱ]للَّهُ يَعْلَمُ [h:1226[ٱ]لْمُفْسِدَ مِنَ [h:1227[ٱ]لْمُصْلِحِ‌ۚ وَلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ لَأَعْنَتَكُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَزِيزٌ حَك[p[ِي]مٌ","Бу дунё ва охират ҳақида. Сендан етимлар ҳақида сўрарлар. Сен: «Уларга ислоҳ қилиш яхшидир», деб айт. Агар уларнинг аралаштириб юборсангиз, бас, биродарларингиз. Аллоҳ бузғунчини ҳам, ислоҳчини ҳам билади. Агар хоҳласа, Аллоҳ сизларни қийинчиликка соларди. Албатта, Аллоҳ азиз ва ҳикматли зотдир.",35,2],["وَلَا تَ[f:1228[نك]ِحُو[s[اْ] [h:1229[ٱ]لْمُشْرِكَ[n[ـٰ]تِ حَتَّىٰ يُؤْمِ[g[نّ]َ‌ۚ وَلَأَمَ[a:1230[ةٌ م]ُّؤْمِنَةٌ خَيْ[a:1231[رٌ م]ّ[a:1232[ِن م]ُّشْرِكَ[a:1233[ةٍ و]َلَوْ أَعْجَبَتْكُمْ‌ۗ وَلَا تُ[f:1234[نك]ِحُو[s[اْ] [h:1235[ٱ]لْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُو[s[اْ‌ۚ] وَلَعَ[q:1236[بْ][a:1237[دٌ م]ُّؤْمِنٌ خَيْ[a:1231[رٌ م]ّ[a:1238[ِن م]ُّشْرِ[a:1239[كٍ و]َلَوْ أَعْجَبَكُمْ‌ۗ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يَ[q:1240[دْ]عُونَ إِلَى [h:1241[ٱ][l[ل][g[نّ]َارِ‌ۖ وَ[h:72[ٱ]للَّهُ يَ[q:1242[دْ]ع[o[ُوٓ][s[اْ] إِلَى [h:1243[ٱ]لْجَ[g[نّ]َةِ وَ[h:1244[ٱ]لْمَغْفِرَةِ بِإِذْنِه[n[ِۦ]‌ۖ وَيُبَيِّنُ ءَايَ[n[ـٰ]تِه[n[ِۦ] لِل[g[نّ]َاسِ لَعَلَّهُمْ يَتَذَكَّر[p[ُو]نَ","Мушрика аёлларни иймон келтирмагунларича никоҳингизга олманг. Шубҳасиз, мўмина чўри мушрикадан, гар у сизни ажаблантирса ҳам, яхшидир. Ва мушриклар иймонга келмагунларича уларга никоҳлаб берманг. Шубҳасиз, мўмин қул мушрикдан, гар сизни ажаблантирса ҳам, яхшидир. Анавилар дўзах ўтига чақирадилар. Аллоҳ эса, Ўз изни ила жаннатга ва мағфиратга чақиради ҳамда одамларга Ўз оятларини баён қилади. Шоядки эсга олсалар.",35,2],["وَيَسْــَٔلُونَكَ عَنِ [h:1245[ٱ]لْمَحِيضِ‌ۖ قُلْ هُوَ أَ[f:1246[ذًى ف]َ[h:1247[ٱ]عْتَزِلُو[s[اْ] [h:1248[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءَ فِى [h:1249[ٱ]لْمَحِيضِ‌ۖ وَلَا تَ[q:1250[قْ]رَبُوهُ[g[نّ]َ حَتَّىٰ يَ[q:1251[طْ]هُرْنَ‌ۖ فَإِذَا تَطَهَّرْنَ فَأْتُوهُ[g[نّ]َ مِنْ حَيْثُ أَمَرَكُمُ [h:1252[ٱ]للَّهُ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُحِبُّ [h:1253[ٱ][l[ل]تَّوّ[n[َٲ]بِينَ وَيُحِبُّ [h:1254[ٱ]لْمُتَطَهِّر[p[ِي]نَ","Сендан ҳайз ҳақида сўрарлар. Сен: «У кўнгилсиз нарсадир. Ҳайз чоғида аёллардан четда бўлинг. Уларга пок бўлмагунларича яқинлашманглар. Агар пок бўлсалар, уларга Аллоҳ амр қилган жойдан келинг. Албатта, Аллоҳ тавба қилувчиларни севади ва покланувчиларни севади», деб айт.",35,2],["نِس[o[َا]ٓؤُكُمْ حَرْ[u:1255[ثٌ ل]َّكُمْ فَأْتُو[s[اْ] حَرْثَكُمْ أَ[g[نّ]َىٰ شِئْتُمْ‌ۖ وَقَدِّمُو[s[اْ] لِأَ[f:574[نف]ُسِكُمْ‌ۚ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َك[w:1256[ُم م]ُّلَ[n[ـٰ]قُوهُ‌ۗ وَبَشِّرِ [h:1257[ٱ]لْمُؤْمِن[p[ِي]نَ","Аёлларингиз экинзорларингиздир. Бас, экинзорингизга хоҳлаганингизча келинг. Ўзингиз учун тақдим қилинг. Ва Аллоҳга тақво қилинг ҳамда, билингки, албатта, Унга рўбарў келувчисиз. Мўминларга башорат бер.",35,2],["وَلَا تَ[q:95[جْ]عَلُو[s[اْ] [h:1258[ٱ]للَّهَ عُرْضَ[u:1259[ةً ل]ِّأَيْمَ[n[ـٰ]نِكُمْ أَ[f:1260[ن ت]َبَرُّو[s[اْ] وَتَتَّقُو[s[اْ] وَتُصْلِحُو[s[اْ] بَيْنَ [h:1165[ٱ][l[ل][g[نّ]َاسِ‌ۗ وَ[h:72[ٱ]للَّهُ سَمِيعٌ عَل[p[ِي]مٌ","Аллоҳга ичган қасамларингизни яхшилик қилиш, тақво қилиш ва одамлар орасини ислоҳ этишингизга тўсиқ қилманг. Аллоҳ эшитувчи, билувчи зотдир.",35,2],["لَّا يُؤَاخِذُكُمُ [h:1261[ٱ]للَّهُ بِ[h:1262[ٱ][l[ل]لَّغْوِ ف[o[ِىٓ] أَيْمَ[n[ـٰ]نِكُمْ وَلَ[n[ـٰ]ك[a:1263[ِن ي]ُؤَاخِذُك[c:1264[ُم ب]ِمَا كَسَبَتْ قُلُوبُكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ غَفُورٌ حَل[p[ِي]مٌ","Аллоҳ сизларнинг бехуда қасамларингиз учун тутмайди. Лекин қалбдан касб қилганингиз учун тутади. Ва Аллоҳ мағфиратли, раҳмли зотдир.",36,2],["لِّلَّذِينَ يُؤْلُونَ م[a:1265[ِن ن]ِّس[o[َا]ٓئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُ[f:1266[رٍ‌ۖ ف]َإِ[f:1267[ن ف][o[َا]ٓءُو فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Хотинларидан ийлаа қилганлар учун кутиш тўрт ойдир. Агар қайтсалар, бас, албатта, Аллоҳ мағфиратли, раҳмли зотдир.",36,2],["وَإِنْ عَزَمُو[s[اْ] [h:1268[ٱ][l[ل]طَّلَ[n[ـٰ]قَ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ سَمِيعٌ عَل[p[ِي]مٌ","Ва агар талоқни қасд қилсалар, бас, албатта, Аллоҳ эшитувчи, билувчи зотдир.",36,2],["وَ[h:9999[ٱ]لْمُطَلَّقَ[n[ـٰ]تُ يَتَرَبَّصْنَ بِأَ[f:1269[نف]ُسِهِ[g[نّ]َ ثَلَ[n[ـٰ]ثَةَ قُر[o[ُو]ٓ[a:1270[ءٍ‌ۚ و]َلَا يَحِلُّ لَهُ[g[نّ]َ أ[a:1271[َن ي]َكْتُمْنَ مَا خَلَقَ [h:1272[ٱ]للَّهُ ف[o[ِىٓ] أَرْحَامِهِ[g[نّ]َ إِ[f:1273[ن ك]ُ[g[نّ]َ يُؤْمِ[g[نّ]َ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ‌ۚ وَبُعُولَتُهُ[g[نّ]َ أَحَقُّ بِرَدِّهِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ إِنْ أَرَاد[o[ُوٓ][s[اْ] إِصْلَ[n[ـٰ][a:1274[حًا‌ۚ و]َلَهُ[g[نّ]َ مِثْلُ [h:1275[ٱ]لَّذِى عَلَيْهِ[g[نّ]َ بِ[h:934[ٱ]لْمَعْرُوفِ‌ۚ وَلِلرِّجَالِ عَلَيْهِ[g[نّ]َ دَرَجَ[a:1276[ةٌ‌ۗ و]َ[h:72[ٱ]للَّهُ عَزِيزٌ حَك[p[ِي]مٌ","Талоқ қилинган аёллар уч қуръу кутадилар. Агар Аллоҳга ва қиёмат кунига иймон келтирган бўлсалар, Аллоҳ раҳмларида ҳалқ қилинган нарсани беркитишлари ҳалол бўлмайди. Ўшанда эрлари уларни, агар ислоҳни ирода қилсалар, ўзларига қайтариб олишга ҳақлироқдирлар. Ва яхшилик ила уларнинг бурчлари муқобилида ҳақлари ҳам бордир. Ва эркакларга улардан устун даража бордир. Аллоҳ азиз ва ҳакимдир.",36,2],["ٱ[l[ل]طَّلَ[n[ـٰ]قُ مَرَّتَانِ‌ۖ فَإِمْسَا[i:1277[كُۢ ب]ِمَعْرُوفٍ أَوْ تَسْرِي[i:1278[حُۢ ب]ِإِحْسَ[n[ـٰ][a:1279[نٍ‌ۗ و]َلَا يَحِلُّ لَكُمْ أَ[f:1280[ن ت]َأْخُذُو[s[اْ] مِ[g[مّ][o[َآ] ءَاتَيْتُمُوهُ[g[نّ]َ شَيْــًٔا إِلّ[o[َآ] أ[a:1281[َن ي]َخَاف[o[َآ] أَلَّا يُقِيمَا حُدُودَ [h:1282[ٱ]للَّهِ‌ۖ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ [h:1282[ٱ]للَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا [h:1283[ٱ]فْتَدَتْ بِه[n[ِۦ]‌ۗ تِلْكَ حُدُودُ [h:1000[ٱ]للَّهِ فَلَا تَعْتَدُوهَا‌ۚ وَم[a:1284[َن ي]َتَعَدَّ حُدُودَ [h:1282[ٱ]للَّهِ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:1285[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Талоқ икки мартадир. Сўнгра яхшиликча ушлаб қолиш ёки яхшиликча қўйиб юбориш. Сизга уларга берган нарсангиздан бирор нарсани олиш ҳалол бўлмайди, магар икковлари Аллоҳнинг чегараларида тура олмасликдан қўрқсалар. Бас, агар икковларининг Аллоҳнинг чегараларида тура олмаслигидан қўрқсангиз, хотин берган эвазда икковларига гуноҳ йўқдир. Ушбулар Аллоҳнинг чегараларидир. Бас, улардан тажовуз қилманг. Ва ким Аллоҳнинг чегараларида тажовуз қилса, бас, ўшалар, ана ўшалар, золимлардир.",36,2],["فَإِ[f:1286[ن ط]َلَّقَهَا فَلَا تَحِلُّ لَهُ[n[ۥ] م[i:1287[ِنۢ ب]َعْدُ حَتَّىٰ تَ[f:1288[نك]ِحَ زَوْجًا غَيْرَهُ[n[ۥ]‌ۗ فَإِ[f:1286[ن ط]َلَّقَهَا فَلَا جُنَاحَ عَلَيْهِم[o[َآ] أ[a:1289[َن ي]َتَرَاجَع[o[َآ] إِ[f:1290[ن ظ]َ[g[نّ][o[َآ] أ[a:1291[َن ي]ُقِيمَا حُدُودَ [h:1282[ٱ]للَّهِ‌ۗ وَتِلْكَ حُدُودُ [h:1000[ٱ]للَّهِ يُبَيِّنُهَا لِقَوْ[a:1292[مٍ ي]َعْلَم[p[ُو]نَ","Бас, агар яна талоқ қилса, бундан кейин у аёл токи бошқа эрга тегиб чиқмагунча унга ҳалол бўлмайди. Агар у ҳам талоқ қилса, гар Аллоҳнинг чегараларида туришга ишонсалар, бир-бирларига қайтсалар, гуноҳ бўлмайди. Ушбулар Аллоҳнинг билган қавмларга баён қилаётган чегараларидир.",36,2],["وَإِذَا طَلَّ[q:1293[قْ]تُمُ [h:1294[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءَ فَبَلَغْنَ أَجَلَهُ[g[نّ]َ فَأَمْسِكُوهُ[g[نّ]َ بِمَعْرُوفٍ أَوْ سَرِّحُوهُ[g[نّ]َ بِمَعْرُو[a:1295[فٍ‌ۚ و]َلَا تُمْسِكُوهُ[g[نّ]َ ضِرَا[u:1296[رًا ل]ِّتَعْتَدُو[s[اْ‌ۚ] وَم[a:1297[َن ي]َفْعَلْ ذ[n[َٲ]لِكَ فَقَ[q:563[دْ] ظَلَمَ نَفْسَهُ[n[ۥ]‌ۚ وَلَا تَتَّخِذ[o[ُوٓ][s[اْ] ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ هُزُ[a:1299[وًا‌ۚ و]َ[h:335[ٱ]ذْكُرُو[s[اْ] نِعْمَتَ [h:1300[ٱ]للَّهِ عَلَيْكُمْ وَم[o[َآ] أَ[f:471[نز]َلَ عَلَيْك[w:1301[ُم م]ِّنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ وَ[h:1302[ٱ]لْحِكْمَةِ يَعِظُك[c:1303[ُم ب]ِه[n[ِۦ]‌ۚ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","Хотинларни талоқ қилишингизда, муддатлари охирига етганда, уларни яхшилик билан ушлаб қолинг ёки яхшилик билан қўйворинг. Уларни тажовуз учун, зарар етказиш юзасидан ушлаб турманг. Ким ўшандоқ қилса, шубҳасиз, ўзига зулм қилади. Аллоҳнинг оятларини ҳазил билманг. Аллоҳнинг сизга берган неъматини ва ваъз этиб туширган китоби ва ҳикматини эсда тутинг. Аллоҳга тақво қилинг ва, билингки, албатта, Аллоҳ ҳар бир нарсани билувчидир.",37,2],["وَإِذَا طَلَّ[q:1293[قْ]تُمُ [h:1294[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءَ فَبَلَغْنَ أَجَلَهُ[g[نّ]َ فَلَا تَعْضُلُوهُ[g[نّ]َ أ[a:1304[َن ي]َ[f:1305[نك]ِحْنَ أَزْو[n[َٲ]جَهُ[g[نّ]َ إِذَا تَر[n[َٲ]ضَوْ[s[اْ] بَيْنَه[c:1306[ُم ب]ِ[h:934[ٱ]لْمَعْرُوفِ‌ۗ ذ[n[َٲ]لِكَ يُوعَظُ بِه[n[ِۦ] مَ[f:506[ن ك]َانَ مِ[f:344[نك]ُمْ يُؤْمِنُ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ‌ۗ ذ[n[َٲ]لِكُمْ أَزْكَىٰ لَكُمْ وَأَ[q:1307[طْ]هَرُ‌ۗ وَ[h:72[ٱ]للَّهُ يَعْلَمُ وَأَ[f:98[نت]ُمْ لَا تَعْلَم[p[ُو]نَ","Хотинларни талоқ қилганингизда, муддатлари охирига етганда, яхшилик билан ўзаро рози бўлишиб, эрларига қайта никоҳланишларини ман қилиб, қийинлаштирманг. Ушбу ила сизлардан Аллоҳга ва охират кунига иймон келтирганлар ваъзланади. Шундоқ қилишингиз сиз учун тозароқ ва покроқдир. Ва Аллоҳ билади, сиз эса билмайсиз.",37,2],["۞ وَ[h:9999[ٱ]لْو[n[َٲ]لِد[n[َٲ]تُ يُرْضِعْنَ أَوْلَ[n[ـٰ]دَهُ[g[نّ]َ حَوْلَيْنِ كَامِلَيْنِ‌ۖ لِمَنْ أَرَادَ أ[a:1308[َن ي]ُتِ[g[مّ]َ [h:1309[ٱ][l[ل]رَّضَاعَةَ‌ۚ وَعَلَى [h:1310[ٱ]لْمَوْلُودِ لَهُ[n[ۥ] رِزْقُهُ[g[نّ]َ وَكِسْوَتُهُ[g[نّ]َ بِ[h:934[ٱ]لْمَعْرُوفِ‌ۚ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا‌ۚ لَا تُض[m[َا]ٓرَّ و[n[َٲ]لِدَ[i:1311[ةُۢ ب]ِوَلَدِهَا وَلَا مَوْلُو[u:1312[دٌ ل]َّهُ[n[ۥ] بِوَلَدِه[n[ِۦ]‌ۚ وَعَلَى [h:1313[ٱ]لْوَارِثِ مِثْلُ ذ[n[َٲ]لِكَ‌ۗ فَإِنْ أَرَادَا فِصَالاً عَ[f:1314[ن ت]َرَا[a:1315[ضٍ م]ِّنْهُمَا وَتَشَاوُ[f:1316[رٍ ف]َلَا جُنَاحَ عَلَيْهِمَا‌ۗ وَإِنْ أَرَ[d:1317[د]تُّمْ أَ[f:1318[ن ت]َسْتَرْضِع[o[ُوٓ][s[اْ] أَوْلَ[n[ـٰ]دَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْت[w:1319[ُم م]ّ[o[َآ] ءَاتَيْت[c:1320[ُم ب]ِ[h:934[ٱ]لْمَعْرُوفِ‌ۗ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","Ким эмизишни батамом қилишни ирода қилса, оналар фарзандларни тўлиқ икки йил эмизадилар. Уларни яхшилаб едириб, кийинтириш отанинг зиммасидадир. Ҳеч бир жонга имкондан ташқари таклиф бўлмайди. Она ҳам, ота ҳам боласи сабабидан зарар тортмасин. Меросхўрга ҳам худди шундоқ. Агар ўзаро рози бўлиб, сутдан ажратишни ирода қилсалар, икковларига гуноҳ бўлмайди. Агар фарзандларингизга эмизувчи талаб қилишни ирода қилсангиз, берадиганингизни яхшилик билан аввалдан топширсангиз, гуноҳ бўлмайди. Ва Аллоҳга тақво қилинг ҳамда, билингки, албатта, Аллоҳ қилаётганингизни кўриб турувчидир.",37,2],["وَ[h:9999[ٱ]لَّذِينَ يُتَوَفَّوْنَ مِ[f:344[نك]ُمْ وَيَذَرُونَ أَزْو[n[َٲ][a:1321[جًا ي]َتَرَبَّصْنَ بِأَ[f:1269[نف]ُسِهِ[g[نّ]َ أَرْبَعَةَ أَشْهُ[a:1322[رٍ و]َعَشْ[f:1323[رًا‌ۖ ف]َإِذَا بَلَغْنَ أَجَلَهُ[g[نّ]َ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ ف[o[ِىٓ] أَ[f:1324[نف]ُسِهِ[g[نّ]َ بِ[h:934[ٱ]لْمَعْرُوفِ‌ۗ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ خَب[p[ِي]رٌ","Сизлардан вафот этиб жуфтларини қолдирганларнинг аёллари ўзларича тўрт ой-у ўн кун кутадилар. Муддатлари етганда ўзлари ҳақида яхшилик билан қилган ишларида сизга гуноҳ йўқ. Аллоҳ қилаётган амалингиздан хабардордир.",38,2],["وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْت[c:1325[ُم ب]ِه[n[ِۦ] مِنْ خِ[q:1326[طْ]بَةِ [h:1327[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ أَوْ أَكْنَ[f:1328[نت]ُمْ ف[o[ِىٓ] أَ[f:1329[نف]ُسِكُمْ‌ۚ عَلِمَ [h:986[ٱ]للَّهُ أَ[g[نّ]َكُمْ سَتَذْكُرُونَهُ[g[نّ]َ وَلَ[n[ـٰ]ك[u:46[ِن ل]َّا تُوَاعِدُوهُ[g[نّ]َ سِرًّا إِلّ[o[َآ] أَ[f:1330[ن ت]َقُولُو[s[اْ] قَوْل[a:1331[اً م]َّعْرُو[a:1332[فًا‌ۚ و]َلَا تَعْزِمُو[s[اْ] عُ[q:1333[قْ]دَةَ [h:1334[ٱ][l[ل][g[نّ]ِكَاحِ حَتَّىٰ يَ[q:1053[بْ]لُغَ [h:1335[ٱ]لْكِتَ[n[ـٰ]بُ أَجَلَهُ[n[ۥ]‌ۚ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَعْلَمُ مَا ف[o[ِىٓ] أَ[f:1329[نف]ُسِكُمْ فَ[h:1336[ٱ]حْذَرُوهُ‌ۚ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ غَفُورٌ حَل[p[ِي]مٌ","У аёлларга ишора ила совчилик қилишингиз ёки уни ўз ичингизда тутишингизда гуноҳ йўқ. Аллоҳ сиз уларни, албатта, эслашингизни билади. Лекин улар билан хуфёна ваъдалашманг. Магар яхши гап гапирсангиз, майли. Идда ўз муддатига етмагунча, никоҳ боғлашни қасд қилманг. Ва билингки, албатта, Аллоҳ ичингиздагини билади. Бас, Ундан огоҳ бўлинг. Ва билингки, албатта, Аллоҳ мағфиратли ва ҳалимдир.",38,2],["لَّا جُنَاحَ عَلَيْكُمْ إِ[f:1337[ن ط]َلَّ[q:1293[قْ]تُمُ [h:1294[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءَ مَا لَمْ تَمَسُّوهُ[g[نّ]َ أَوْ تَفْرِضُو[s[اْ] لَهُ[g[نّ]َ فَرِيضَ[a:1338[ةً‌ۚ و]َمَتِّعُوهُ[g[نّ]َ عَلَى [h:1339[ٱ]لْمُوسِعِ قَدَرُهُ[n[ۥ] وَعَلَى [h:1340[ٱ]لْمُ[q:1341[قْ]تِرِ قَدَرُهُ[n[ۥ] مَتَ[n[ـٰ]ع[i:1342[َۢا ب]ِ[h:934[ٱ]لْمَعْرُوفِ‌ۖ حَقًّا عَلَى [h:1343[ٱ]لْمُحْسِن[p[ِي]نَ","Агар хотинларга қўл теккизмай туриб ёки уларнинг маҳрни аниқламай туриб талоқ қилсангиз, сизга гуноҳ бўлмайди. Уларни бой борича, йўқ ҳолича яхшилик ила фойда билан фойдалантиринг. Бу яхшилик қилувчилар бурчидир.",38,2],["وَإِ[f:1344[ن ط]َلَّ[q:1345[قْ]تُمُوهُ[g[نّ]َ مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أَ[f:1348[ن ت]َمَسُّوهُ[g[نّ]َ وَقَ[q:387[دْ] فَرَضْتُمْ لَهُ[g[نّ]َ فَرِيضَ[f:1349[ةً ف]َنِصْفُ مَا فَرَضْتُمْ إِلّ[o[َآ] أ[a:1350[َن ي]َعْفُونَ أَوْ يَعْفُوَ[s[اْ] [h:1351[ٱ]لَّذِى بِيَدِه[n[ِۦ] عُ[q:1352[قْ]دَةُ [h:1353[ٱ][l[ل][g[نّ]ِكَاحِ‌ۚ وَأَ[f:1354[ن ت]َعْف[o[ُوٓ][s[اْ] أَ[q:1355[قْ]رَبُ لِلتَّ[q:1356[قْ]وَىٰ‌ۚ وَلَا تَ[f:1357[نس]َوُ[s[اْ] [h:1358[ٱ]لْفَضْلَ بَيْنَكُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","Агар уларга қўл тегизмай талоқ қилсангиз ва маҳрни аниқлаб қўйган бўлсангиз, аниқланганнинг ярмини берасиз, магар аёл ёки никоҳ тугуни қўлида бўлган киши афв қилса, бермайсиз. Ва афв қилишингиз тақвога яқиндир. Орангиздаги фазилатни унутманг. Албатта, Аллоҳ қилаётган амалларингизни кўриб турувчи зотдир.",38,2],["حَ[n[ـٰ]فِظُو[s[اْ] عَلَى [h:1359[ٱ][l[ل]صَّلَو[n[َٲ]تِ وَ[h:224[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ [h:1360[ٱ]لْوُسْطَىٰ وَقُومُو[s[اْ] لِلَّهِ قَ[n[ـٰ]نِت[p[ِي]نَ","Намозларни ва ўрта намозни муҳофаза этинг. Ва Аллоҳ учун хушуъ ила қоим бўлинг.",39,2],["فَإِنْ خِفْتُمْ فَرِجَالاً أَوْ رُكْبَا[f:1361[نًا‌ۖ ف]َإِذ[o[َآ] أَمِ[f:1062[نت]ُمْ فَ[h:1091[ٱ]ذْكُرُو[s[اْ] [h:1092[ٱ]للَّهَ كَمَا عَلَّمَك[w:1362[ُم م]َّا لَمْ تَكُونُو[s[اْ] تَعْلَم[p[ُو]نَ","Агар хавфда қолсангиз, юрган ва минган ҳолингизда, хотиржам бўлганингизда, билмаган нарсангизни қандоқ ўргатган бўлса, Аллоҳни шундоқ зикр қилинг.",39,2],["وَ[h:9999[ٱ]لَّذِينَ يُتَوَفَّوْنَ مِ[f:344[نك]ُمْ وَيَذَرُونَ أَزْو[n[َٲ][a:1363[جًا و]َصِيَّ[u:1364[ةً ل]ِّأَزْو[n[َٲ]جِه[w:1365[ِم م]َّتَ[n[ـٰ]عًا إِلَى [h:1366[ٱ]لْحَوْلِ غَيْرَ إِخْرَا[f:1367[جٍ‌ۚ ف]َإِنْ خَرَ[q:1368[جْ]نَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ ف[o[ِىٓ] أَ[f:1324[نف]ُسِهِ[g[نّ]َ م[a:1369[ِن م]َّعْرُو[a:1370[فٍ‌ۗ و]َ[h:72[ٱ]للَّهُ عَزِيزٌ حَك[p[ِي]مٌ","Сизлардан вафот этганда жуфтларини қолдираётганлар, хотинлари чиқмасдан бир йилгача фойдаланишини васият қилсинлар. Агар улар чиқсалар, ўз хусусларида яхшилик билан қилган ишларида сизга гуноҳ йўқ. Аллоҳ азиз ва ҳаким зотдир.",39,2],["وَلِلْمُطَلَّقَ[n[ـٰ]تِ مَتَ[n[ـٰ][i:1371[عُۢ ب]ِ[h:934[ٱ]لْمَعْرُوفِ‌ۖ حَقًّا عَلَى [h:946[ٱ]لْمُتَّق[p[ِي]نَ","Талоқ қилинган аёлларга мақбул тарзда фойда бериш тақводорлар бурчидир.",39,2],["كَذ[n[َٲ]لِكَ يُبَيِّنُ [h:1002[ٱ]للَّهُ لَكُمْ ءَايَ[n[ـٰ]تِه[n[ِۦ] لَعَلَّكُمْ تَعْقِل[p[ُو]نَ","Аллоҳ шундай қилиб сизларга Ўз оятларини баён этади. Шоядки ақл ишлатсангиз.",39,2],["۞ أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ خَرَجُو[s[اْ] مِ[f:432[ن د]ِيَ[n[ـٰ]رِهِمْ وَهُمْ أُلُوفٌ حَذَرَ [h:71[ٱ]لْمَوْتِ فَقَالَ لَهُمُ [h:1373[ٱ]للَّهُ مُوتُو[s[اْ] ثُ[g[مّ]َ أَحْيَ[n[ـٰ]هُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَذُو فَضْلٍ عَلَى [h:729[ٱ][l[ل][g[نّ]َاسِ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَشْكُر[p[ُو]نَ","Диёрларидан ўлимдан қочиб чиққан мингларча кишиларнинг билмадингми?! Бас, Аллоҳ уларга, ўлинг, деди. Сўнгра уларни тирилтирди. Албатта, Аллоҳ одамларга фазл қилувчидир. Лекин кўп одамлар шукр қилмаслар.",39,2],["وَقَ[n[ـٰ]تِلُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ سَمِيعٌ عَل[p[ِي]مٌ","Аллоҳнинг йўлида жанг қилинг. Ва билингки, албатта, Аллоҳ эшитувчи ва билувчи зотдир.",39,2],["مَّ[f:1375[ن ذ]َا [h:1376[ٱ]لَّذِى يُ[q:1377[قْ]رِضُ [h:1378[ٱ]للَّهَ قَرْضًا حَسَ[f:1379[نًا ف]َيُضَ[n[ـٰ]عِفَهُ[n[ۥ] لَهُ[o[ۥٓ] أَضْعَا[f:1380[فًا ك]َثِيرَ[a:1381[ةً‌ۚ و]َ[h:72[ٱ]للَّهُ يَ[q:1382[قْ]بِضُ وَيَ[q:1383[بْ]صُۜطُ وَإِلَيْهِ تُرْجَع[p[ُو]نَ","Аллоҳга яхши қарз берадиган ким бор?! Бас, токи У зот унга берганини кўп марта кўпайтириб берса. Ва ҳолбуки, Аллоҳ тор қилур ва кенг қилур. Ва Унгагина қайтарилурсиз.",39,2],["أَلَمْ تَرَ إِلَى [h:1384[ٱ]لْمَلَإِ م[i:1385[ِنۢ ب]َن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ م[i:146[ِنۢ ب]َعْدِ مُوسَ[o[ىٰٓ] إِذْ قَالُو[s[اْ] لِنَبِ[u:1386[ىٍّ ل]َّهُمُ [h:1387[ٱ][q:1388[بْ]عَثْ لَنَا مَلِ[a:1389[كًا ن]ُّقَ[n[ـٰ]تِلْ فِى سَبِيلِ [h:788[ٱ]للَّهِ‌ۖ قَالَ هَلْ عَسَيْتُمْ إِ[f:1390[ن ك]ُتِبَ عَلَيْكُمُ [h:1192[ٱ]لْقِتَالُ أَلَّا تُقَ[n[ـٰ]تِلُو[s[اْ‌ۖ] قَالُو[s[اْ] وَمَا لَن[o[َآ] أَلَّا نُقَ[n[ـٰ]تِلَ فِى سَبِيلِ [h:788[ٱ]للَّهِ وَقَ[q:387[دْ] أُخْرِ[q:1391[جْ]نَا مِ[f:1392[ن د]ِيَ[n[ـٰ]رِنَا وَأَ[q:1393[بْ]ن[o[َا]ٓئِنَا‌ۖ فَلَ[g[مّ]َا كُتِبَ عَلَيْهِمُ [h:1394[ٱ]لْقِتَالُ تَوَلَّوْ[s[اْ] إِلَّا قَلِيل[a:1395[اً م]ِّنْهُمْ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِي[i:497[مُۢ ب]ِ[h:498[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Мусодан кейинги Бани Исроилдан бўлган аъёнларни билмадингми?! Вақтики ўз Набийларига: «Бизга бир подшоҳ тайин қилгин, Аллоҳнинг йўлида уруш қилайлик», дедилар. У: «Агар сизларга уруш фарз қилинса, урушмасаларингиз-чи?!» деди. Улар: «Бизга нима бўлибдики, диёримиздан ва фарзандларимиздан жудо қилинсак ҳам, Аллоҳнинг йўлида урушмасак», дедилар. Уруш фарз қилинганда эса, озгиналаридан бошқалари юз ўгириб кетдилар. Ва Аллоҳ зулм қилувчиларни билувчидир.",40,2],["وَقَالَ لَهُمْ نَبِيُّهُمْ إِ[g[نّ]َ [h:80[ٱ]للَّهَ قَ[q:298[دْ] بَعَثَ لَكُمْ طَالُوتَ مَلِ[f:1396[كًا‌ۚ ق]َال[o[ُوٓ][s[اْ] أَ[g[نّ]َىٰ يَكُونُ لَهُ [h:1397[ٱ]لْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِ[h:1398[ٱ]لْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَ[a:1399[ةً م]ِّنَ [h:1400[ٱ]لْمَالِ‌ۚ قَالَ إِ[g[نّ]َ [h:80[ٱ]للَّهَ [h:1401[ٱ]صْطَفَ[n[ـٰ]هُ عَلَيْكُمْ وَزَادَهُ[n[ۥ] بَسْطَ[f:1402[ةً ف]ِى [h:1403[ٱ]لْعِلْمِ وَ[h:1404[ٱ]لْجِسْمِ‌ۖ وَ[h:72[ٱ]للَّهُ يُؤْتِى مُلْكَهُ[n[ۥ] م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَ[h:72[ٱ]للَّهُ و[n[َٲ]سِعٌ عَل[p[ِي]مٌ","Набийлари уларга: «Албатта, Аллоҳ Толутни сизга подшоҳ қилиб тайинлади», деди. Улар: «У бизга қаёқдан подшоҳ бўлсин. Ундан кўра подшоҳликка биз ҳақлироқмиз. Қолаверса, унга кўпроқ мол ҳам берилмаган» дедилар. У: «Албатта, уни Аллоҳнинг Ўзи сизларга танлади ва илмда, жисмда кенглигини зиёда қилди. Аллоҳ подшоҳлигини кимга хоҳласа, ўшанга беради. Ва Аллоҳ кенг қамровли ва билувчидир», деди.",40,2],["وَقَالَ لَهُمْ نَبِيُّهُمْ إِ[g[نّ]َ ءَايَةَ مُلْكِه[o[ِۦٓ] أ[a:1405[َن ي]َأْتِيَكُمُ [h:1406[ٱ][l[ل]تَّابُوتُ فِيهِ سَكِينَ[a:1407[ةٌ م]ّ[u:243[ِن ر]َّبِّكُمْ وَبَقِيَّ[a:1408[ةٌ م]ِّ[g[مّ]َا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَ[n[ـٰ]رُونَ تَحْمِلُهُ [h:1409[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:1410[ةً ل]َّكُمْ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Набийлари уларга: «Албатта, унинг подшоҳлигининг белгиси, сизларга Роббингиздан тобут келмоғидир, унда хотиржамлик ва Мусо ҳамда Ҳорун аҳлидан қолган қолдиқ бўлиб, фаришталар кўтариб келур. Агар мўмин бўлсаларингиз, албатта бу нарсада сизларга белги бор», деди.",40,2],["فَلَ[g[مّ]َا فَصَلَ طَالُوتُ بِ[h:1411[ٱ]لْجُنُودِ قَالَ إِ[g[نّ]َ [h:80[ٱ]للَّهَ مُ[q:1412[بْ]تَلِيك[c:1413[ُم ب]ِنَهَ[f:1414[رٍ ف]َمَ[f:1415[ن ش]َرِبَ مِنْهُ فَلَيْسَ مِ[g[نّ]ِى وَم[u:1416[َن ل]َّمْ يَ[q:1417[طْ]عَمْهُ فَإِ[g[نّ]َهُ[n[ۥ] مِ[g[نّ][o[ِىٓ] إِلَّا مَنِ [h:1418[ٱ]غْتَرَفَ غُرْفَ[i:1419[ةَۢ ب]ِيَدِه[n[ِۦ]‌ۚ فَشَرِبُو[s[اْ] مِنْهُ إِلَّا قَلِيل[a:1395[اً م]ِّنْهُمْ‌ۚ فَلَ[g[مّ]َا جَاوَزَهُ[n[ۥ] هُوَ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مَعَهُ[n[ۥ] قَالُو[s[اْ] لَا طَاقَةَ لَنَا [h:1420[ٱ]لْيَوْمَ بِجَالُوتَ وَجُنُودِه[n[ِۦ]‌ۚ قَالَ [h:590[ٱ]لَّذِينَ يَظُ[g[نّ]ُونَ أَ[g[نّ]َه[w:226[ُم م]ُّلَ[n[ـٰ]قُو[s[اْ] [h:1421[ٱ]للَّهِ ك[w:1422[َم م]ِّ[f:1423[ن ف]ِئَ[f:1424[ةٍ ق]َلِيلَةٍ غَلَبَتْ فِئَ[f:1425[ةً ك]َثِيرَ[i:1426[ةَۢ ب]ِإِذْنِ [h:509[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ مَعَ [h:785[ٱ][l[ل]صَّ[n[ـٰ]بِر[p[ِي]نَ","Толут аскар билан чиққанда: «Албатта, Аллоҳ сизни дарё билан синовчидир, ким ундан ичса, у мендан эмас. Ва ким уни тановвул қилмаса, у, албатта, мендандир. Магар биров қўли билан бир ҳўплам ҳўпласа, майли», деди. Озгиналаридан бошқалари ундан ичдилар. У ва у билан бирга иймон келтирганлар дарёдан ўтганларида улар: «Бугун бизда Жолут ва унинг аскари билан жанг қилишга тоқат йўқ», дедилар. Аллоҳга рўбарў бўлишга ишонганлар: «Қанчадан-қанча оз сонли гуруҳлар Аллоҳнинг изни билан кўп сонли гуруҳларга ғолиб келган. Аллоҳ сабрлилар биландир», дедилар.",41,2],["وَلَ[g[مّ]َا بَرَزُو[s[اْ] لِجَالُوتَ وَجُنُودِه[n[ِۦ] قَالُو[s[اْ] رَبَّن[o[َآ] أَفْرِغْ عَلَيْنَا صَ[q:1427[بْ][a:1428[رًا و]َثَبِّتْ أَ[q:1429[قْ]دَامَنَا وَ[h:1430[ٱ][f:1430[نص]ُرْنَا عَلَى [h:1431[ٱ]لْقَوْمِ [h:1432[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Жолут ва унинг аскарларига рўбарў келганларида: «Роббимиз, бизга сабр тўккин, бизни собитқадам қилгин ва кофир қавмларга қарши нусрат бергин», дедилар.",41,2],["فَهَزَمُوه[c:1433[ُم ب]ِإِذْنِ [h:509[ٱ]للَّهِ وَقَتَلَ دَاوُ[n[ۥ]دُ جَالُوتَ وَءَاتَ[n[ـٰ]هُ [h:1434[ٱ]للَّهُ [h:1435[ٱ]لْمُلْكَ وَ[h:679[ٱ]لْحِكْمَةَ وَعَلَّمَهُ[n[ۥ] مِ[g[مّ]َا يَش[o[َا]ٓءُ‌ۗ وَلَوْلَا دَفْعُ [h:1436[ٱ]للَّهِ [h:1437[ٱ][l[ل][g[نّ]َاسَ بَعْضَه[c:1438[ُم ب]ِبَعْ[u:1439[ضٍ ل]َّفَسَدَتِ [h:1440[ٱ]لْأَرْضُ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ ذُو فَضْلٍ عَلَى [h:227[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Бас, Аллоҳнинг изни билан урушда енгдилар ва Довуд Жолутни қатл этди. Сўнгра Аллоҳ унга подшоҳлик ва ҳикматни берди ва хоҳлаган нарсасини ўргатди. Агар Аллоҳнинг баъзи ларни баъзиларига дафъ қилиш бўлмаса эди, ер юзи бузиларди. Лекин Аллоҳ оламлар устидан фазл эгасидир.",41,2],["تِلْكَ ءَايَ[n[ـٰ]تُ [h:1442[ٱ]للَّهِ نَتْلُوهَا عَلَيْكَ بِ[h:370[ٱ]لْحَقِّ‌ۚ وَإِ[g[نّ]َكَ لَمِنَ [h:1443[ٱ]لْمُرْسَل[p[ِي]نَ","Булар Аллоҳнинг оятларидир. Уларни сенга ҳақ ила тиловат қилурмиз. Ва, албатта, сен Пайғамбарлардандирсан.",41,2],["۞ تِلْكَ [h:1444[ٱ][l[ل]رُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْ[a:1445[ضٍ‌ۘ م]ِّنْه[w:1446[ُم م]َّ[f:1447[ن ك]َلَّمَ [h:1448[ٱ]للَّهُ‌ۖ وَرَفَعَ بَعْضَهُمْ دَرَجَ[n[ـٰ][a:1449[تٍ‌ۚ و]َءَاتَيْنَا عِيسَى [h:450[ٱ][q:451[بْ]نَ مَرْيَمَ [h:452[ٱ]لْبَيِّنَ[n[ـٰ]تِ وَأَيَّ[q:453[دْ]نَ[n[ـٰ]هُ بِرُوحِ [h:454[ٱ]لْقُدُسِ‌ۗ وَلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ مَا [h:1450[ٱ][q:1451[قْ]تَتَلَ [h:1452[ٱ]لَّذِينَ م[i:1453[ِنۢ ب]َعْدِه[w:1454[ِم م]ّ[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَتْهُمُ [h:1168[ٱ]لْبَيِّنَ[n[ـٰ]تُ وَلَ[n[ـٰ]كِنِ [h:1455[ٱ]خْتَلَفُو[s[اْ] فَمِنْه[w:1456[ُم م]َّنْ ءَامَنَ وَمِنْه[w:1106[ُم م]َّ[f:1457[ن ك]َفَرَ‌ۚ وَلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ مَا [h:1458[ٱ][q:1459[قْ]تَتَلُو[s[اْ] وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ يَفْعَلُ مَا يُر[p[ِي][q[د]ُ","Ўшалар Пайғамбарлар. Уларнинг баъзиларини баъзиларидан фазллик қилдик. Улардан Аллоҳ гаплашгани бор ва баъзиларининг даражасини кўтарган. Ва Ийсо ибн Марямга ойдин ларни бердик ва уни муқаддас руҳ билан қўлладик. Агар Аллоҳ хоҳлаганида, улардан кейин қолганлар ўзларига очиқ-ойдин баёнотлар келганидан сўнг урушмас эдилар. Лекин ихтилоф қилдилар. Улардан кимдир иймон келтирди, кимдир куфр келтирди. Агар Аллоҳ хоҳлаганида, урушмас эдилар. Лекин Аллоҳ нимани ирода қилса, шуни қилади.",42,3],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَ[f:1460[نف]ِقُو[s[اْ] مِ[g[مّ]َا رَزَ[q:275[قْ]نَ[n[ـٰ]ك[w:1461[ُم م]ِّ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:1462[َن ي]َأْتِىَ يَوْ[u:1463[مٌ ل]َّا بَيْ[f:1464[عٌ ف]ِيهِ وَلَا خُلَّ[a:1465[ةٌ و]َلَا شَفَ[n[ـٰ]عَ[a:1466[ةٌ‌ۗ و]َ[h:1467[ٱ]لْكَ[n[ـٰ]فِرُونَ هُمُ [h:1285[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Эй иймон келтирганлар! Сизга ризқ қилиб берган нарсаларимиздан, на олди-сотди, на ошна-оғайничилик ва на шафоатчилик йўқ кун келмасдан олдин нафақа қилинг. Ва кофирлар–ўшалар, золимлардир.",42,3],["ٱللَّهُ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ [h:1468[ٱ]لْحَىُّ [h:1469[ٱ]لْقَيُّومُ‌ۚ لَا تَأْخُذُهُ[n[ۥ] سِنَ[a:1470[ةٌ و]َلَا نَوْ[u:1471[مٌ‌ۚ ل]َّهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۗ مَ[f:1375[ن ذ]َا [h:1376[ٱ]لَّذِى يَشْفَعُ عِ[f:719[ند]َهُ[o[ۥٓ] إِلَّا بِإِذْنِه[n[ِۦ]‌ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ‌ۖ وَلَا يُحِيطُونَ بِش[a:1472[َىْءٍ م]ِّنْ عِلْمِه[o[ِۦٓ] إِلَّا بِمَا ش[o[َا]ٓءَ‌ۚ وَسِعَ كُرْسِيُّهُ [h:1473[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ‌ۖ وَلَا يَــُٔودُهُ[n[ۥ] حِفْظُهُمَا‌ۚ وَهُوَ [h:1475[ٱ]لْعَلِىُّ [h:1476[ٱ]لْعَظ[p[ِي]مُ","Аллоҳ Ундан ўзга илоҳ йўқ зотдир. У тирик ва қаййумдир. Уни мудроқ ҳам, уйқу ҳам олмас. Осмонлару ердаги нарсалар Уникидир. Унинг ҳузурида Ўзининг изнисиз ҳеч ким шафоат қила олмас. У уларнинг олдиларидаги нарсани ҳам, ортларидаги нарсани ҳам билур. Унинг илмидан ҳеч нарсани иҳота қила олмаслар, магар Ўзи хоҳлаганини, халос. Унинг курсиси осмонлару ерни қамраган. Уларни муҳофаза қилиш Уни чарчатмас. Ва У Олий ва Азим зотдир.",42,3],["ل[o[َآ] إِكْرَاهَ فِى [h:1477[ٱ][l[ل]دِّينِ‌ۖ قَ[d:1478[د] تَّبَيَّنَ [h:1479[ٱ][l[ل]رُّشْدُ مِنَ [h:1480[ٱ]لْغَىِّ‌ۚ فَم[a:1481[َن ي]َكْفُرْ بِ[h:1482[ٱ][l[ل]طَّ[n[ـٰ]غُوتِ وَيُؤْم[i:1483[ِنۢ ب]ِ[h:32[ٱ]للَّهِ فَقَدِ [h:1484[ٱ]سْتَمْسَكَ بِ[h:1485[ٱ]لْعُرْوَةِ [h:1486[ٱ]لْوُثْقَىٰ لَا [h:1487[ٱ][f:1488[نف]ِصَامَ لَهَا‌ۗ وَ[h:72[ٱ]للَّهُ سَمِيعٌ عَل[p[ِي]مٌ","Динга мажбур қилиш йўқ. Батаҳқиқ, ҳақ ботилдан ажради. Ким тоғутга куфр келтириб, Аллоҳга иймон келтирса, батаҳқиқ, узилмайдиган мустаҳкам тутқични ушлаган бўлур. Ва Аллоҳ эшитувчи, билувчи зотдир.",42,3],["ٱللَّهُ وَلِىُّ [h:1489[ٱ]لَّذِينَ ءَامَنُو[s[اْ] يُخْرِجُه[w:1490[ُم م]ِّنَ [h:1491[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ إِلَى [h:1492[ٱ][l[ل][g[نّ]ُورِ‌ۖ وَ[h:37[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أَوْلِي[o[َا]ٓؤُهُمُ [h:1493[ٱ][l[ل]طَّ[n[ـٰ]غُوتُ يُخْرِجُونَه[w:1494[ُم م]ِّنَ [h:1495[ٱ][l[ل][g[نّ]ُورِ إِلَى [h:1496[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ‌ۗ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Аллоҳ иймон келтирганларнинг дўстидир. Уларни зулматлардан нурга чиқарур. Куфр келтирганларнинг дўстлари тоғутдир. Уларни нурдан зулматларга чиқарурлар. Ана ўшалар дўзах эгаларидир. Улар унда абадийдирлар. «Тоғут»-Аллоҳдан бошқа ибодат қилинадиган нарсалар.",43,3],["أَلَمْ تَرَ إِلَى [h:1497[ٱ]لَّذِى ح[m[َا]ٓجَّ إِ[q:640[بْ]ر[n[َٲ]هِـ[n[ـۧ]مَ فِى رَبِّه[o[ِۦٓ] أَنْ ءَاتَ[n[ـٰ]هُ [h:1498[ٱ]للَّهُ [h:1435[ٱ]لْمُلْكَ إِذْ قَالَ إِ[q:656[بْ]ر[n[َٲ]هِـ[n[ـۧ]مُ رَبِّىَ [h:1499[ٱ]لَّذِى يُحْى[n[ِۦ] وَيُمِيتُ قَالَ أَنَا۟ أُحْى[n[ِۦ] وَأُمِيتُ‌ۖ قَالَ إِ[q:656[بْ]ر[n[َٲ]هِـ[n[ـۧ]مُ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ يَأْتِى بِ[h:1500[ٱ][l[ل]شَّمْسِ مِنَ [h:1501[ٱ]لْمَشْرِقِ فَأْتِ بِهَا مِنَ [h:1502[ٱ]لْمَغْرِبِ فَبُهِتَ [h:1503[ٱ]لَّذِى كَفَرَ‌ۗ وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Аллоҳ подшоҳлик бериб қўйгани сабабидан Иброҳим билан Роббиси ҳақида ҳужжат талашганни билмадингми? Иброҳим: «Менинг Роббиим тирилтиради ва ўлдиради», деганда, у: «Мен тирилтираман ва ўлдираман», деди. Иброҳим: «Албатта, Аллоҳ қуёшни Машриқдан чиқаради, бас, сен уни Мағрибдан чиқаргин-чи», деди. Бас, куфр келтирган лол қолди. Ва Аллоҳ золим қавмларни ҳидоятга солмас.",43,3],["أَوْ كَ[h:1506[ٱ]لَّذِى مَرَّ عَلَىٰ قَرْيَ[a:1507[ةٍ و]َهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَ[g[نّ]َىٰ يُحْى[n[ِۦ] هَ[n[ـٰ]ذِهِ [h:1508[ٱ]للَّهُ بَعْدَ مَوْتِهَا‌ۖ فَأَمَاتَهُ [h:1509[ٱ]للَّهُ مِ[s[اْ]ئَةَ عَا[f:1510[مٍ ث]ُ[g[مّ]َ بَعَثَهُ[n[ۥ]‌ۖ قَالَ كَمْ لَبِثْتَ‌ۖ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْ[f:1511[مٍ‌ۖ ق]َالَ بَل لَّبِثْتَ مِ[s[اْ]ئَةَ عَا[f:1512[مٍ ف]َ[h:1513[ٱ][f:1513[نظ]ُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَ[g[نّ]َهْ‌ۖ وَ[h:1514[ٱ][f:1514[نظ]ُرْ إِلَىٰ حِمَارِكَ وَلِنَ[q:1515[جْ]عَلَكَ ءَايَ[u:1516[ةً ل]ِّل[g[نّ]َاسِ‌ۖ وَ[h:1514[ٱ][f:1514[نظ]ُرْ إِلَى [h:1517[ٱ]لْعِظَامِ كَيْفَ نُ[f:1518[نش]ِزُهَا ثُ[g[مّ]َ نَكْسُوهَا لَحْ[f:1519[مًا‌ۚ ف]َلَ[g[مّ]َا تَبَيَّنَ لَهُ[n[ۥ] قَالَ أَعْلَمُ أَ[g[نّ]َ [h:394[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Ёки шифтлари устига қулаган қишлоқдан ўтган кишига ўхшашни кўрмадингми? У: «Аллоҳ буни ўлимидан кейин қандай тирилтиради?» деди. Бас, Аллоҳ уни юз йил ўлдирди, сўнгра қайта тирилтирди. У зот: «Қанча ётднг?», деди. У: «Бир кун ёки бир куннинг баъзисича ётдим», деди. У зот: «Балки юз йил ётдинг, таомингга ва шаробингга назар сол, ўзгаргани йўқ ва эшагингга ҳам қара. Сени одамларга ибрат қилиш учун шундай қилдик. Ва суякларга назар сол, уларни қандоқ ҳаракатга соламиз ва уларга қандоқ гўшт кийгизамиз», деди. Унга равшан бўлганда: «Албатта, Аллоҳ ҳар бир нарсага қодирлигини билдим», деди.",43,3],["وَإِذْ قَالَ إِ[q:656[بْ]ر[n[َٲ]هِـ[n[ـۧ]مُ رَبِّ أَرِنِى كَيْفَ تُحْىِ [h:1520[ٱ]لْمَوْتَىٰ‌ۖ قَالَ أَوَلَمْ تُؤْمِ[f:1521[ن‌ۖ ق]َالَ بَلَىٰ وَلَ[n[ـٰ]ك[u:1522[ِن ل]ِّيَ[q:1523[طْ]مَئِ[g[نّ]َ قَلْبِى‌ۖ قَالَ فَخُذْ أَرْبَعَ[a:1524[ةً م]ِّنَ [h:1525[ٱ][l[ل]طَّيْرِ فَصُرْهُ[g[نّ]َ إِلَيْكَ ثُ[g[مّ]َ [h:1526[ٱ][q:658[جْ]عَلْ عَلَىٰ كُلِّ جَبَ[a:1527[لٍ م]ِّنْهُ[g[نّ]َ جُزْ[f:1528[ءًا ث]ُ[g[مّ]َ [h:1529[ٱ][q:1530[دْ]عُهُ[g[نّ]َ يَأْتِينَكَ سَعْ[a:1531[يًا‌ۚ و]َ[h:1532[ٱ]عْلَمْ أَ[g[نّ]َ [h:394[ٱ]للَّهَ عَزِيزٌ حَك[p[ِي]مٌ","Эсла, Иброҳим: «Эй Роббим, менга ўликларни қандай тирилтиришингни кўрсат», деганда, У зот: «Ишонмадингми?» деди. У: Оре, лекин қалбим хотиржам бўлиши учун», деди. У зот: «Қушдан тўртта олгин-да, ўзингга тортиб, кесиб майдала, сўнгра улардан ҳар бир тоққа бўлакларини қўйгин, кейин уларни ўзингга чақир, ҳузурингга тезлаб келурлар ва билгинки, албатта, Аллоҳ азиз ва ҳаким зотдир», деди.",44,3],["مَّثَلُ [h:1179[ٱ]لَّذِينَ يُ[f:16[نف]ِقُونَ أَمْو[n[َٲ]لَهُمْ فِى سَبِيلِ [h:788[ٱ]للَّهِ كَمَثَلِ حَبَّةٍ أَ[i:1533[نۢب]َتَتْ سَ[q:158[بْ]عَ سَنَابِلَ فِى كُلِّ سُ[i:1534[نۢب]ُلَ[a:1535[ةٍ م]ِّ[s[اْ]ئَةُ حَبَّ[a:1536[ةٍ‌ۗ و]َ[h:72[ٱ]للَّهُ يُضَ[n[ـٰ]عِفُ لِم[a:1537[َن ي]َش[o[َا]ٓءُ‌ۗ وَ[h:72[ٱ]للَّهُ و[n[َٲ]سِعٌ عَل[p[ِي]مٌ","Молларини Аллоҳнинг йўлида сарфлайдиганларнинг мисоли, худди бир дона донга ўхшайди. Ундан етти бошоқ ўсиб чиқади, ҳар бошоқда юзтадан дон бор. Ва Аллоҳ кимга хоҳласа, яна кўпайтириб берадир. Ва Аллоҳ қамраб олувчи ва билувчи зотдир.",44,3],["ٱلَّذِينَ يُ[f:16[نف]ِقُونَ أَمْو[n[َٲ]لَهُمْ فِى سَبِيلِ [h:788[ٱ]للَّهِ ثُ[g[مّ]َ لَا يُتْبِعُونَ م[o[َآ] أَ[f:1538[نف]َقُو[s[اْ] مَن[a:1539[ًّا و]َل[o[َآ] أَ[u:1540[ذًى‌ۙ ل]َّهُمْ أَ[q:331[جْ]رُهُمْ عِ[f:264[ند]َ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Аллоҳнинг йўлида молларини сарфлаб, сўнгра сарфлари кетидан миннат қилмай ва озор бермайдиганларнинг ажрлари Роббилари ҳузуридадир. Уларга хавф йўқ ва улар хафа ҳам бўлмаслар.",44,3],["۞ قَوْ[a:1541[لٌ م]َّعْرُو[a:1542[فٌ و]َمَغْفِرَةٌ خَيْ[a:1231[رٌ م]ِّ[f:1543[ن ص]َدَقَ[a:1544[ةٍ ي]َتْبَعُه[o[َآ] أَ[a:1545[ذًى‌ۗ و]َ[h:72[ٱ]للَّهُ غَنِىٌّ حَل[p[ِي]مٌ","Яхши сўз ва кечириш, ортидан озор келадиган садақадан кўра яхшироқдир. Ва Аллоҳ ғаний ва ҳалим зотдир.",44,3],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تُ[q:1546[بْ]طِلُو[s[اْ] صَدَقَ[n[ـٰ]تِك[c:1547[ُم ب]ِ[h:1548[ٱ]لْمَ[g[نّ]ِ وَ[h:1549[ٱ]لْأَذَىٰ كَ[h:1506[ٱ]لَّذِى يُ[f:1550[نف]ِقُ مَالَهُ[n[ۥ] رِئ[o[َا]ٓءَ [h:1551[ٱ][l[ل][g[نّ]َاسِ وَلَا يُؤْمِنُ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ‌ۖ فَمَثَلُهُ[n[ۥ] كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَا[f:1552[بٌ ف]َأَصَابَهُ[n[ۥ] وَابِ[f:1553[لٌ ف]َتَرَكَهُ[n[ۥ] صَلْ[u:1554[دًا‌ۖ ل]َّا يَ[q:1555[قْ]دِرُونَ عَلَىٰ ش[a:1556[َىْءٍ م]ِّ[g[مّ]َا كَسَبُو[s[اْ‌ۗ] وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1557[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Эй иймон келтирганлар! Садақаларингизни миннат ва озор бериш билан, молини Аллоҳга ва охират кунига иймон келтирмаса ҳам кишиларга риё учун нафақа қилганга ўхшаб бекорга кетгазманг. У мисоли бир устини тупроқ босган силлиқ тошга ўхшайди. Бас, кучли ёмғир ёғса, силлиқ бўлиб қоладир. Касб қилганларидан ҳеч нарсага қодир бўлмаслар. Ва Аллоҳ кофир қавмларни ҳидоятга бошламас.",44,3],["وَمَثَلُ [h:879[ٱ]لَّذِينَ يُ[f:16[نف]ِقُونَ أَمْو[n[َٲ]لَهُمُ [h:1558[ٱ][q:1130[بْ]تِغ[o[َا]ٓءَ مَرْضَاتِ [h:1131[ٱ]للَّهِ وَتَثْبِي[a:1559[تًا م]ِّنْ أَ[f:568[نف]ُسِهِمْ كَمَثَلِ جَ[g[نّ]َ[i:1560[ةِۭ ب]ِرَ[q:1561[بْ]وَةٍ أَصَابَهَا وَابِ[f:1562[لٌ ف]َـَٔـاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإ[u:110[ِن ل]َّمْ يُصِ[q:1563[بْ]هَا وَابِ[f:1564[لٌ ف]َطَ[a:1565[لٌّ‌ۗ و]َ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","Молларини Аллоҳнинг розилигини истаб, ўзларидаги ишонч билан сарфлайдиганлар худди тепаликдаги боққа ўхшарлар. Унга қаттиқ ёмғир ёғса, мевасини икки баробар беради. Агар қаттиқ ёмғир ёғмаса, майдалаб ёққани ҳам бўлаверади. Ва Аллоҳ қилаётганларингизни кўриб турувчи зотдир.",45,3],["أَيَوَدُّ أَحَدُكُمْ أَ[f:1566[ن ت]َكُونَ لَهُ[n[ۥ] جَ[g[نّ]َ[a:1567[ةٌ م]ّ[a:1568[ِن ن]َّخِي[a:1569[لٍ و]َأَعْنَا[f:1570[بٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ لَهُ[n[ۥ] فِيهَا مِ[f:843[ن ك]ُلِّ [h:1571[ٱ][l[ل]ثَّمَر[n[َٲ]تِ وَأَصَابَهُ [h:1572[ٱ]لْكِبَرُ وَلَهُ[n[ۥ] ذُرِّيَّ[f:1573[ةٌ ض]ُعَف[o[َا]ٓءُ فَأَصَابَه[o[َآ] إِعْصَا[f:1574[رٌ ف]ِيهِ نَا[f:1575[رٌ ف]َ[h:1576[ٱ]حْتَرَقَتْ‌ۗ كَذ[n[َٲ]لِكَ يُبَيِّنُ [h:1002[ٱ]للَّهُ لَكُمُ [h:1221[ٱ]لْأَيَ[n[ـٰ]تِ لَعَلَّكُمْ تَتَفَكَّر[p[ُو]نَ","Сизлардан бирортангиз остидан анҳорлар оқиб турган хурмозор ва узумзор, турли мевали боғи бўлатуриб, ёши бир жойга етганда, заифҳол зурриёти бор пайтда унга ўтли бўрон келиб ёниб битишини хоҳлайдими?! Аллоҳ сизларга шу тариқа Ўз оятларини баён қиладир, шоядки фикр юритсангиз.",45,3],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَ[f:1460[نف]ِقُو[s[اْ] مِ[f:274[ن ط]َيِّبَ[n[ـٰ]تِ مَا كَسَ[q:697[بْ]تُمْ وَمِ[g[مّ][o[َآ] أَخْرَ[q:1577[جْ]نَا لَك[w:1578[ُم م]ِّنَ [h:1579[ٱ]لْأَرْضِ‌ۖ وَلَا تَيَ[g[مّ]َمُو[s[اْ] [h:1580[ٱ]لْخَبِيثَ مِنْهُ تُ[f:1581[نف]ِقُونَ وَلَسْت[c:1582[ُم ب]ِـَٔـاخِذِيهِ إِلّ[o[َآ] أَ[f:1583[ن ت]ُغْمِضُو[s[اْ] فِيهِ‌ۚ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ غَنِىٌّ حَم[p[ِي][q[د]ٌ","Эй иймон келтирганлар! Касб қилган пок нарсаларингиздан ва Биз сизларга ердан чиқариб берган нарсаларимиздан садақа қилинглар. Нопокни қасд этиб садақа қилманг. Ҳолбуки, уни ўзингиз ҳам олувчимассиз, магар кўз юмсангизгина оласиз. Ва билингки, албатта, Аллоҳ бой ва мақталган зотдир.",45,3],["ٱ[l[ل]شَّيْطَ[n[ـٰ]نُ يَعِدُكُمُ [h:1584[ٱ]لْفَ[q:1585[قْ]رَ وَيَأْمُرُك[c:1586[ُم ب]ِ[h:1587[ٱ]لْفَحْش[o[َا]ٓءِ‌ۖ وَ[h:72[ٱ]للَّهُ يَعِدُك[w:1588[ُم م]َّغْفِرَ[a:1589[ةً م]ِّنْهُ وَفَضْل[a:1590[اً‌ۗ و]َ[h:72[ٱ]للَّهُ و[n[َٲ]سِعٌ عَل[p[ِي]مٌ","Шайтон сизга фақирликни ваъда қилади ва фаҳш ишларга буюради. Аллоҳ сизга ўзидан мағфират ва фазлни ваъда қилади. Ва Аллоҳ кенг қамровли, билувчи зотдир.",45,3],["يُؤْتِى [h:1591[ٱ]لْحِكْمَةَ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَم[a:1592[َن ي]ُؤْتَ [h:1593[ٱ]لْحِكْمَةَ فَقَ[q:563[دْ] أُوتِىَ خَيْ[f:1594[رًا ك]َثِي[a:142[رًا‌ۗ و]َمَا يَذَّكَّرُ إِلّ[o[َآ] أُ[s[وْ]لُو[s[اْ] [h:1595[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","У зот кимни хоҳласа, ўшанга ҳикматни беради. Кимга ҳикмат берилса, унга кўп яхшилик берилган бўлади. Фақат ақл эгаларигина эсларлар.",45,3],["وَم[o[َآ] أَ[f:1186[نف]َ[q:1186[قْ]ت[w:1187[ُم م]ّ[a:1596[ِن ن]َّفَقَةٍ أَوْ نَذَرْت[w:1597[ُم م]ّ[a:1598[ِن ن]َّذْ[f:1599[رٍ ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ يَعْلَمُهُ[n[ۥ]‌ۗ وَمَا لِلظَّ[n[ـٰ]لِمِينَ مِنْ أَ[f:1600[نص][p[َا]رٍ","Қилган нафақангизни ёки назрингизни Аллоҳ, албатта, билади. Золимларга ёрдамчилар йўқдир.",46,3],["إِ[f:1601[ن ت]ُ[q:1602[بْ]دُو[s[اْ] [h:1603[ٱ][l[ل]صَّدَقَ[n[ـٰ]تِ فَنِعِ[g[مّ]َا هِىَ‌ۖ وَإِ[f:1604[ن ت]ُخْفُوهَا وَتُؤْتُوهَا [h:1605[ٱ]لْفُقَر[o[َا]ٓءَ فَهُوَ خَيْ[u:263[رٌ ل]َّكُمْ‌ۚ وَيُكَفِّرُ عَ[f:255[نك][w:256[ُم م]ِّ[f:1606[ن س]َيِّـَٔـاتِكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ خَب[p[ِي]رٌ","Садақани ошкора қилсангиз қандоқ ҳам яхши. Агар махфий қилсангиз ва фақирларга берсангиз, бу сиз учун яхшидир. Сиздан гуноҳларингизни ювади. Ва Аллоҳ қилаётган амалларингиздан хабардордир.",46,3],["۞ لَّيْسَ عَلَيْكَ هُدَ[n[ٮٰ]هُمْ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ يَهْدِى م[a:476[َن ي]َش[o[َا]ٓءُ‌ۗ وَمَا تُ[f:1607[نف]ِقُو[s[اْ] مِنْ خَيْ[f:1608[رٍ ف]َلِأَ[f:1609[نف]ُسِكُمْ‌ۚ وَمَا تُ[f:1581[نف]ِقُونَ إِلَّا [h:1610[ٱ][q:1130[بْ]تِغ[o[َا]ٓءَ وَ[q:1611[جْ]هِ [h:1612[ٱ]للَّهِ‌ۚ وَمَا تُ[f:1607[نف]ِقُو[s[اْ] مِنْ خَيْ[a:1613[رٍ ي]ُوَفَّ إِلَيْكُمْ وَأَ[f:98[نت]ُمْ لَا تُظْلَم[p[ُو]نَ","Уларни ҳидоятга солиш сенинг зиммангда эмас. Лекин Аллоҳ кимни хоҳласа, ҳидоятга бошлар. Нафақа қилган яхшиликларингиз ўз фойдангизга. Қилган нафақангиз, фақат Аллоҳнинг юзини исташ учундир. Нафақа қилган яхшиликларингиз ўзингизга тўлалигича қайтарилур. Сизларга зулм қилинмас.",46,3],["لِلْفُقَر[o[َا]ٓءِ [h:1614[ٱ]لَّذِينَ أُحْصِرُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ لَا يَسْتَطِيعُونَ ضَرْ[f:1615[بًا ف]ِى [h:44[ٱ]لْأَرْضِ يَحْسَبُهُمُ [h:1616[ٱ]لْجَاهِلُ أَغْنِي[o[َا]ٓءَ مِنَ [h:1617[ٱ][l[ل]تَّعَفُّفِ تَعْرِفُه[c:1618[ُم ب]ِسِيمَ[n[ـٰ]هُمْ لَا يَسْــَٔلُونَ [h:1619[ٱ][l[ل][g[نّ]َاسَ إِلْحَا[a:1620[فًا‌ۗ و]َمَا تُ[f:1607[نف]ِقُو[s[اْ] مِنْ خَيْ[f:1191[رٍ ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ بِه[n[ِۦ] عَل[p[ِي]مٌ","Аллоҳнинг йўлида тутилган, ер юзида касб қилишга қодир бўлмаган, иффатлари туфайли билмаган киши уларни бой деб ўйлайдиган фақирларгадир. Уларни сиймоларидан танийсан, одамлардан хиралик қилиб сўрамаслар. Нафақа қилган яхшиликларингизни, албатта, Аллоҳ билгувчидир.",46,3],["ٱلَّذِينَ يُ[f:16[نف]ِقُونَ أَمْو[n[َٲ]لَه[c:1621[ُم ب]ِ[h:1622[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ سِر[a:1623[ًّا و]َعَلَانِيَ[f:1624[ةً ف]َلَهُمْ أَ[q:331[جْ]رُهُمْ عِ[f:264[ند]َ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Кечасию кундузи молларини нафақа қиладиганларнинг ажрлари Роббилари ҳузуридадир. Уларга хавф йўқ ва улар хафа ҳам бўлмаслар.",46,3],["ٱلَّذِينَ يَأْكُلُونَ [h:1625[ٱ][l[ل]رِّبَ[s[و][n[ٲ]اْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ [h:1626[ٱ]لَّذِى يَتَخَبَّطُهُ [h:1627[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ مِنَ [h:1628[ٱ]لْمَسِّ‌ۚ ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َمَا [h:1629[ٱ]لْبَيْعُ مِثْلُ [h:1630[ٱ][l[ل]رِّبَ[s[و][n[ٲ]اْ‌ۗ وَأَحَلَّ [h:1631[ٱ]للَّهُ [h:1632[ٱ]لْبَيْعَ وَحَرَّمَ [h:1633[ٱ][l[ل]رِّبَ[s[و][n[ٲ]اْ‌ۚ فَمَ[f:1634[ن ج][o[َا]ٓءَهُ[n[ۥ] مَوْعِظَ[a:1635[ةٌ م]ّ[u:192[ِن ر]َّبِّه[n[ِۦ] فَ[h:1636[ٱ][f:1636[نت]َهَىٰ فَلَهُ[n[ۥ] مَا سَلَفَ وَأَمْرُهُ[o[ۥٓ] إِلَى [h:1637[ٱ]للَّهِ‌ۖ وَمَنْ عَادَ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Рибони ейдиганлар фақат шайтон уриб жинни бўлган кишидек довдираб турарлар. Бундай бўлиши уларнинг, тижорат ҳам рибога ўхшаш-да, деганлари учундир. Ва ҳолбуки, Аллоҳ тижоратни ҳалол, рибони ҳаром қилган. Кимки Роббидан мавъиза келганда тўхтаса, аввал ўтгани ўзига ва унинг иши Аллоҳнинг Ўзига ҳавола. Кимки яна қайтса, ана ўшалар дўзах эгаларидир. Улар унда абадий қолурлар.",47,3],["يَمْحَقُ [h:1638[ٱ]للَّهُ [h:1639[ٱ][l[ل]رِّبَ[s[و][n[ٲ]اْ وَيُرْبِى [h:1640[ٱ][l[ل]صَّدَقَ[n[ـٰ]تِ‌ۗ وَ[h:72[ٱ]للَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَث[p[ِي]مٍ","Аллоҳ рибони доимо нуқсонга учратади ва садақаларни зиёда қилади. Ва Аллоҳ ҳар бир кофир, гуноҳкорни хуш кўрмас.",47,3],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ وَأَقَامُو[s[اْ] [h:1641[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتَوُ[s[اْ] [h:1642[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ لَهُمْ أَ[q:331[جْ]رُهُمْ عِ[f:264[ند]َ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Албатта, иймон келтирган, яхши амалларни қилган, намозни қоим қилиб, закот берганларнинг ажрлари Роббилари ҳузуридадир. Уларга хавф йўқ ва улар хафа ҳам бўлмаслар.",47,3],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:1643[ٱ]تَّقُو[s[اْ] [h:1644[ٱ]للَّهَ وَذَرُو[s[اْ] مَا بَقِىَ مِنَ [h:1645[ٱ][l[ل]رِّبَ[o[[s[و]ٲٓاْ] إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Эй иймон келтирганлар! Агар мўмин бўлсангиз, Аллоҳга тақво қилинг ва рибонинг сарқитини ҳам тарк қилинг.",47,3],["فَإ[u:110[ِن ل]َّمْ تَفْعَلُو[s[اْ] فَأْذَنُو[s[اْ] بِحَرْ[a:1646[بٍ م]ِّنَ [h:321[ٱ]للَّهِ وَرَسُولِه[n[ِۦ]‌ۖ وَإِ[f:1647[ن ت]ُ[q:1648[بْ]تُمْ فَلَكُمْ رُءُوسُ أَمْو[n[َٲ]لِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَم[p[ُو]نَ","Агар ундоқ қилмасангиз, Аллоҳ ва Унинг Расули томонидан бўладиган урушга ишонаверинг. Агар тавба қилсангиз, сармоянгиз ўзингизга, зулм қилмассиз ва сизга ҳам зулм қилинмас.",47,3],["وَإِ[f:1649[ن ك]َانَ ذُو عُسْرَ[f:1650[ةٍ ف]َنَظِرَةٌ إِلَىٰ مَيْسَرَ[a:1651[ةٍ‌ۚ و]َأَ[f:1652[ن ت]َصَدَّقُو[s[اْ] خَيْ[u:263[رٌ ل]َّكُمْ‌ۖ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","Агар ночор бўлса, бойигунча интизор бўлинг. Садақа қилмоғингиз, гар билсангиз, ўзингиз учун яхшидир.",47,3],["وَ[h:9999[ٱ]تَّقُو[s[اْ] يَوْ[f:1653[مًا ت]ُرْجَعُونَ فِيهِ إِلَى [h:1637[ٱ]للَّهِ‌ۖ ثُ[g[مّ]َ تُوَفَّىٰ كُلُّ نَفْ[a:1654[سٍ م]َّا كَسَبَتْ وَهُمْ لَا يُظْلَم[p[ُو]نَ","Аллоҳга қайтариладиган кунингиздан қўрқинг. Сўнгра ҳар бир жон қилганига яраша тўлиқ оладир. Уларга зулм қилинмас.",47,3],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا تَدَايَ[f:1655[نت][c:1656[ُم ب]ِدَيْنٍ إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَم[f:1658[ًّى ف]َ[h:1659[ٱ]كْتُبُوهُ‌ۚ وَلْيَكْتُب بَّيْنَكُمْ كَاتِ[i:1660[بُۢ ب]ِ[h:1661[ٱ]لْعَ[q:1661[دْ]لِ‌ۚ وَلَا يَأْبَ كَاتِبٌ أ[a:1662[َن ي]َكْتُبَ كَمَا عَلَّمَهُ [h:1663[ٱ]للَّهُ‌ۚ فَلْيَكْتُ[q:1664[بْ] وَلْيُمْلِلِ [h:1665[ٱ]لَّذِى عَلَيْهِ [h:1666[ٱ]لْحَقُّ وَلْيَتَّقِ [h:1667[ٱ]للَّهَ رَبَّهُ[n[ۥ] وَلَا يَ[q:1668[بْ]خَسْ مِنْهُ شَيْـ[f:1669[ـًٔا‌ۚ ف]َإِ[f:1670[ن ك]َانَ [h:1671[ٱ]لَّذِى عَلَيْهِ [h:1666[ٱ]لْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أ[a:1672[َن ي]ُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُ[n[ۥ] بِ[h:1661[ٱ]لْعَ[q:1661[دْ]لِ‌ۚ وَ[h:1673[ٱ]سْتَشْهِدُو[s[اْ] شَهِيدَيْنِ م[u:1674[ِن ر]ِّجَالِكُمْ‌ۖ فَإ[u:110[ِن ل]َّمْ يَكُونَا رَجُلَيْنِ فَرَجُ[a:1675[لٌ و]َ[h:1676[ٱ]مْرَأَتَانِ مِ[g[مّ]َ[f:1677[ن ت]َرْضَوْنَ مِنَ [h:1678[ٱ][l[ل]شُّهَد[o[َا]ٓءِ أَ[f:1679[ن ت]َضِلَّ إِحْدَ[n[ٮٰ]هُمَا فَتُذَكِّرَ إِحْدَ[n[ٮٰ]هُمَا [h:1680[ٱ]لْأُخْرَىٰ‌ۚ وَلَا يَأْبَ [h:1681[ٱ][l[ل]شُّهَد[o[َا]ٓءُ إِذَا مَا دُعُو[s[اْ‌ۚ] وَلَا تَسْــَٔم[o[ُوٓ][s[اْ] أَ[f:1682[ن ت]َكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَ[o[ىٰٓ] أَجَلِه[n[ِۦ]‌ۚ ذ[n[َٲ]لِكُمْ أَ[q:1683[قْ]سَطُ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَأَ[q:1684[قْ]وَمُ لِلشَّهَ[n[ـٰ]دَةِ وَأَ[q:1685[دْ]نَ[o[ىٰٓ] أَلَّا تَرْتَاب[o[ُوٓ[s[اْ]‌ۖ] إِلّ[o[َآ] أَ[f:1566[ن ت]َكُونَ تِجَ[n[ـٰ]رَةً حَاضِرَ[f:1686[ةً ت]ُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا‌ۗ وَأَشْهِد[o[ُوٓ][s[اْ] إِذَا تَبَايَعْتُمْ‌ۚ وَلَا يُض[m[َا]ٓرَّ كَاتِ[a:1687[بٌ و]َلَا شَهِي[a:1688[دٌ‌ۚ و]َإِ[f:1689[ن ت]َفْعَلُو[s[اْ] فَإِ[g[نّ]َهُ[n[ۥ] فُسُو[i:1690[قُۢ ب]ِكُمْ‌ۗ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۖ وَيُعَلِّمُكُمُ [h:1691[ٱ]للَّهُ‌ۗ وَ[h:72[ٱ]للَّهُ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","Эй иймон келтирганлар! Маълум муддатга қарз олди-берди қилган вақтингизда, уни ёзиб қўйинг. Орангизда бир ёзувчи адолат билан ёзсин. Ҳеч бир ёзувчи Аллоҳ билдирганидек қилиб ёзишдан бош тортмасин. Бас, ёзсин ва ҳақ зиммасига тушган киши айтиб турсин, Роббига тақво қилсин ва ундан ҳеч нарсани камайтирмасин. Агар ҳақ зиммасига тушган киши эси паст, заиф ёки айтиб тура олмайдиган бўлса, унинг валийси адолат билан айтиб турсин. Эркакларингиздан икки кишини гувоҳ қилинг. Агар икки эр киши бўлмаса, ўзингиз рози бўладиган гувоҳлардан бир эр киши ва икки аёл киши бўлсин. Икковидан бирорталари адашса, бирлари бошқасининг эсига солади. Ва чақирилган вақтда гувоҳлар бош тортмасинлар. Кичик бўлса ҳам, катта бўлса ҳам, муддатигача ёзишингизни малол олманг. Шундоқ қилмоғингиз Аллоҳнинг ҳузурида адолатлироқ, гувоҳликка кучлироқ ва шубҳаланмаслигингиз учун яқинроқдир. Магар ораларингизда юриб турган нақд савдо бўлса, ёзмасангиз ҳам, сизга гуноҳ бўлмас. Олди-сотди қилганингизда, гувоҳ келтиринг ва ёзувчи ҳам, гувоҳ ҳам зарар тортмасин. Агар қилсангиз, албатта, бу фосиқлигингиздир. Аллоҳга тақво қилинг. Ва Аллоҳ сизга илм беради. Аллоҳ ҳар бир нарсани билувчи зотдир.",48,3],["۞ وَإِ[f:99[ن ك]ُ[f:100[نت]ُمْ عَلَىٰ سَفَ[a:1692[رٍ و]َلَمْ تَجِدُو[s[اْ] كَاتِ[f:1693[بًا ف]َرِهَ[n[ـٰ][a:1694[نٌ م]َّ[q:1695[قْ]بُوضَ[f:1696[ةٌ‌ۖ ف]َإِنْ أَمِنَ بَعْضُك[c:1697[ُم ب]َعْ[f:1698[ضًا ف]َلْيُؤَدِّ [h:1699[ٱ]لَّذِى [h:1700[ٱ]ؤْتُمِنَ أَمَ[n[ـٰ]نَتَهُ[n[ۥ] وَلْيَتَّقِ [h:1667[ٱ]للَّهَ رَبَّهُ[n[ۥ]‌ۗ وَلَا تَكْتُمُو[s[اْ] [h:1701[ٱ][l[ل]شَّهَ[n[ـٰ]دَةَ‌ۚ وَم[a:1702[َن ي]َكْتُمْهَا فَإِ[g[نّ]َهُ[o[ۥٓ] ءَاثِ[f:1703[مٌ ق]َلْبُهُ[n[ۥ]‌ۗ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ عَل[p[ِي]مٌ","Агар сафарда бўлсангиз ва ёзувчи топа олмасангиз, бас, қўлга олинадиган гаров бўлсин. Агар баъзингиз баъзингизга ишонсангиз, бас, ишонилган омонатни адо қилсин, Аллоҳга, Роббисига тақво қилсин. Гувоҳликни беркитманг! Ким уни беркитса, унинг қалби гуноҳкордир. Ва Аллоҳ қилаётган амалларингизни билувчи зотдир.",49,3],["لِّلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۗ وَإِ[f:1704[ن ت]ُ[q:1602[بْ]دُو[s[اْ] مَا ف[o[ِىٓ] أَ[f:1329[نف]ُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِ[q:1705[بْ]ك[c:1706[ُم ب]ِهِ [h:1707[ٱ]للَّهُ‌ۖ فَيَغْفِرُ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيُعَذِّبُ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۗ وَ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Осмонлару ердаги нарсалар Аллоҳникидир. Агар ичингиздаги нарсаларни ошкор қилсангиз ҳам, махфий қилсангиз ҳам, сизларни Аллоҳ ҳисоб-китоб қилади. Ва кимни хоҳласа, мағфират қилар, кимни хоҳласа, азоблар. Ва У ҳар бир нарсага қодирдир.",49,3],["ءَامَنَ [h:1708[ٱ][l[ل]رَّسُولُ بِم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْهِ م[u:192[ِن ر]َّبِّه[n[ِۦ] وَ[h:1709[ٱ]لْمُؤْمِنُونَ‌ۚ كُلٌّ ءَامَنَ بِ[h:32[ٱ]للَّهِ وَمَلَ[o[ـٰٓ]ئِكَتِه[n[ِۦ] وَكُتُبِه[n[ِۦ] وَرُسُلِه[n[ِۦ] لَا نُفَرِّقُ بَيْنَ أَحَ[a:1710[دٍ م]ّ[u:1711[ِن ر]ُّسُلِه[n[ِۦ]‌ۚ وَقَالُو[s[اْ] سَمِعْنَا وَأَطَعْنَا‌ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ [h:1712[ٱ]لْمَص[p[ِي]رُ","Пайғамбар унга ўз Роббидан туширилган нарсага иймон келтирди ва мўминлар ҳам. Барча Аллоҳга, Унинг фаришталарига, китобларига, Пайғамбарларига иймон келтирди. Унинг Пайғамбарларининг бирорталарини ажратмаймиз. Ва эшитдик ва итоат қилдик, эй Роббимиз мағфаратингни сўраймиз ва қайтиб бориш Сенгадир, дедилар.",49,3],["لَا يُكَلِّفُ [h:1713[ٱ]للَّهُ نَفْسًا إِلَّا وُسْعَهَا‌ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا [h:1714[ٱ]كْتَسَبَتْ‌ۗ رَبَّنَا لَا تُؤَاخِذْن[o[َآ] إ[a:1715[ِن ن]َّسِين[o[َآ] أَوْ أَخْطَأْنَا‌ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْن[o[َآ] إِصْ[f:1716[رًا ك]َمَا حَمَلْتَهُ[n[ۥ] عَلَى [h:289[ٱ]لَّذِينَ مِ[f:1717[ن ق]َ[q:1718[بْ]لِنَا‌ۚ رَبَّنَا وَلَا تُحَ[g[مّ]ِلْنَا مَا لَا طَاقَةَ لَنَا بِه[n[ِۦ]‌ۖ وَ[h:1719[ٱ]عْفُ عَ[g[نّ]َا وَ[h:1720[ٱ]غْفِرْ لَنَا وَ[h:1721[ٱ]رْحَمْن[o[َآ‌ۚ] أَ[f:169[نت]َ مَوْلَ[n[ـٰ]نَا فَ[h:1722[ٱ][f:1722[نص]ُرْنَا عَلَى [h:1431[ٱ]لْقَوْمِ [h:1432[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Аллоҳ ҳеч бир жонни тоқатидан ташқари нарсага таклиф қилмас. Фойдаси ҳам касбидан, зарари ҳам касбидан. Эй Роббимиз, агар унутсак ёки хато қилсак, тутмагин. Эй Роббимиз, биздан олдингиларга юклаганга ўхшаш оғирликни бизга юкламагин. Эй Роббимиз, бизга тоқатимз етмайдиган нарсани юкламагин. Бизни афв эт, мағфират қил ва раҳм эт. Сен ҳожамизсан. Бас, кофир қавмларга бизни ғолиб қил.",49,3]]},{"n":3,"ar":"آلِ عِمۡرَانَ","en":"Aal-i-Imraan","uz":"Оли Имрон","type":"Мадина","ayahs":[["ا[m[لٓ][m[مٓ]","Алиф Лом Мим.",50,3],["ٱللَّهُ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ [h:1468[ٱ]لْحَىُّ [h:1469[ٱ]لْقَيّ[p[ُو]مُ","Аллоҳ–Ундан ўзга ибодатга лойиқ илоҳ йўқ, тирик ва қаййум зотдир.",50,3],["نَزَّلَ عَلَيْكَ [h:1723[ٱ]لْكِتَ[n[ـٰ]بَ بِ[h:370[ٱ]لْحَقِّ مُصَدِّ[u:206[قًا ل]ِّمَا بَيْنَ يَدَيْهِ وَأَ[f:91[نز]َلَ [h:1724[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةَ وَ[h:1725[ٱ]لْإِ[f:1725[نج][p[ِي]لَ","У сенга китобни ҳақ ила ўзидан аввалги нарсани тасдиқловчи қилиб туширди ҳамда Таврот ва Инжилни туширди.",50,3],["مِ[f:128[ن ق]َ[q:129[بْ]لُ هُ[u:968[دًى ل]ِّل[g[نّ]َاسِ وَأَ[f:91[نز]َلَ [h:1726[ٱ]لْفُرْقَانَ‌ۗ إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ لَهُمْ عَذَا[f:1727[بٌ ش]َدِي[a:1728[دٌ‌ۗ و]َ[h:72[ٱ]للَّهُ عَزِي[f:1729[زٌ ذ]ُو [h:1730[ٱ][f:1731[نت]ِق[p[َا]مٍ","Ундан олдин одамларга ҳидоят қилиб. Ва Фурқонни ҳам туширди. Аллоҳнинг оятларига куфр келтирганларга шиддатли азоб бор. Аллоҳ азиз ва интиқом олувчи зотдир.",50,3],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَخْفَىٰ عَلَيْهِ ش[f:1732[َىْءٌ ف]ِى [h:44[ٱ]لْأَرْضِ وَلَا فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ","Албатта, Аллоҳ Унга ерда ҳам, осмонда ҳам ҳеч нарса махфий қолмайдиган зотдир.",50,3],["هُوَ [h:153[ٱ]لَّذِى يُصَوِّرُكُمْ فِى [h:1733[ٱ]لْأَرْحَامِ كَيْفَ يَش[o[َا]ٓءُ‌ۚ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ [h:1734[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","У сизларни бачадонларда хоҳлаган сувратга соладиган зотдир. Ундан ўзга ибодатга сазовор илоҳ йўқ. У азиз ва ҳаким зотдир.",50,3],["هُوَ [h:153[ٱ]لَّذ[o[ِىٓ] أَ[f:471[نز]َلَ عَلَيْكَ [h:1723[ٱ]لْكِتَ[n[ـٰ]بَ مِنْهُ ءَايَ[n[ـٰ][a:1735[تٌ م]ُّحْكَمَ[n[ـٰ]تٌ هُ[g[نّ]َ أُ[g[مّ]ُ [h:1736[ٱ]لْكِتَ[n[ـٰ]بِ وَأُخَرُ مُتَشَ[n[ـٰ]بِهَ[n[ـٰ][f:1737[تٌ‌ۖ ف]َأَ[g[مّ]َا [h:136[ٱ]لَّذِينَ فِى قُلُوبِهِمْ زَيْ[f:1738[غٌ ف]َيَتَّبِعُونَ مَا تَشَ[n[ـٰ]بَهَ مِنْهُ [h:1739[ٱ][q:1130[بْ]تِغ[o[َا]ٓءَ [h:1740[ٱ]لْفِتْنَةِ وَ[h:1741[ٱ][q:1741[بْ]تِغ[o[َا]ٓءَ تَأْوِيلِه[n[ِۦ]‌ۗ وَمَا يَعْلَمُ تَأْوِيلَهُ[o[ۥٓ] إِلَّا [h:1742[ٱ]للَّهُ‌ۗ وَ[h:1743[ٱ][l[ل]رّ[n[َٲ]سِخُونَ فِى [h:1403[ٱ]لْعِلْمِ يَقُولُونَ ءَامَ[g[نّ]َا بِه[n[ِۦ] كُ[a:1744[لٌّ م]ِّنْ عِ[f:398[ند]ِ رَبِّنَا‌ۗ وَمَا يَذَّكَّرُ إِلّ[o[َآ] أُ[s[وْ]لُو[s[اْ] [h:1595[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","У сенга китобни туширган зотдир. Унда муҳкам оятлар ҳам бор ва улар китобнинг аслидир ва муташобиҳ лар ҳам бор. Қалбларида ҳидоятдан оғиш борлар фитна мақсадида ва уни таъвил қилиш мақсадида ундан муташобиҳ бўлганига эргашади. Унинг таъвилини Аллоҳдан бошқа ҳеч ким билмас. Илмда собит бўлганлар эса, унга иймон келтирдик, барчаси Раббимиз ҳузуридандир, дерлар. Ва фақат ақл эгаларигина эслайдилар.",50,3],["رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَ[q:1745[بْ] لَنَا م[u:1746[ِن ل]َّدُ[f:1747[نك]َ رَحْمَةً‌ۚ إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:1748[ٱ]لْوَهّ[p[َا][q[ب]ُ","Эй Роббимиз, бизни ҳидоят қилганингдан сўнг қалбларимизни оғдирмагин ва бизга Ўз ҳузурингдан раҳмат ато қилгин. Албатта Сенинг Ўзинг кўплаб ато қилувчисан.",50,3],["رَبَّن[o[َآ] إِ[g[نّ]َكَ جَامِعُ [h:1749[ٱ][l[ل][g[نّ]َاسِ لِيَوْ[u:1750[مٍ ل]َّا رَيْبَ فِيهِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُخْلِفُ [h:1751[ٱ]لْمِيع[p[َا][q[د]َ","Эй Роббимиз, албатта, сен одамларни келишига шубҳа йўқ кунда йиғувчисан. Албатта, Аллоҳ ваъдага хилоф қилмас.",50,3],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَ[f:1752[ن ت]ُغْنِىَ عَنْهُمْ أَمْو[n[َٲ]لُهُمْ وَل[o[َآ] أَوْلَ[n[ـٰ]دُه[w:1753[ُم م]ِّنَ [h:321[ٱ]للَّهِ شَيْـ[a:1754[ـًٔا‌ۖ و]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمْ وَقُودُ [h:1755[ٱ][l[ل][g[نّ][p[َا]رِ","Албатта, куфр келтирганларнинг моллари ҳам, болалари ҳам улардан Аллоҳдан бирор нарса қайтара олмас. Ана ўшалар, ўзлари дўзахнинг ёқилғисидирлар.",51,3],["كَدَأْبِ ءَالِ فِرْعَوْنَ وَ[h:37[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا فَأَخَذَهُمُ [h:1756[ٱ]للَّهُ بِذُنُوبِهِمْ‌ۗ وَ[h:72[ٱ]للَّهُ شَدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Фиръавн аҳлининг ва улардан олдингиларнинг ҳолига ўхшаб оятларимизни ёлғонга чиқардилар. Бас, гуноҳлари туфайли Аллоҳ уларни тутди. Ва Аллоҳ иқоби шиддатли зотдир.",51,3],["قُل لِّلَّذِينَ كَفَرُو[s[اْ] سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَ[g[نّ]َمَ‌ۚ وَبِئْسَ [h:1757[ٱ]لْمِه[p[َا][q[د]ُ","Куфр келтирганларга: «Тезда мағлуб бўлурсизлар ва жаҳаннамга йиғилурсизлар, у қандоқ ҳам ёмон жой», деб айт.",51,3],["قَ[q:298[دْ] كَانَ لَكُمْ ءَايَ[f:1758[ةٌ ف]ِى فِئَتَيْنِ [h:1759[ٱ][l[ل]ْتَقَتَا‌ۖ فِئَ[f:1760[ةٌ ت]ُقَ[n[ـٰ]تِلُ فِى سَبِيلِ [h:788[ٱ]للَّهِ وَأُخْرَىٰ كَافِرَ[a:1761[ةٌ ي]َرَوْنَه[w:1762[ُم م]ِّثْلَيْهِمْ رَأْىَ [h:1763[ٱ]لْعَيْنِ‌ۚ وَ[h:72[ٱ]للَّهُ يُؤَيِّدُ بِنَصْرِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ‌ۗ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَعِ[q:1764[بْ]رَ[u:1765[ةً ل]ِّأُ[s[وْ]لِى [h:1766[ٱ]لْأَ[q:1767[بْ]صَ[p[ـٰ]رِ","«Сизга тўқнашган икки фирқада ибрат бор эди. Бир фирқа Аллоҳнинг йўлида уришади. Бошқаси кофирдир. Улар ўз кўзлари билан ўзларига икки баробарлигини кўриб турардилар. Ва Аллоҳ кимни хоҳласа, ўшани Ўз нусрати ила қўллар. Албатта, бунда ақл эгалари учун ибрат бордир», деб айт.",51,3],["زُيِّنَ لِل[g[نّ]َاسِ حُبُّ [h:1768[ٱ][l[ل]شَّهَو[n[َٲ]تِ مِنَ [h:1769[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ وَ[h:1770[ٱ]لْبَنِينَ وَ[h:1771[ٱ]لْقَنَ[n[ـٰ]طِيرِ [h:1772[ٱ]لْمُقَ[f:1773[نط]َرَةِ مِنَ [h:1774[ٱ][l[ل]ذَّهَبِ وَ[h:1775[ٱ]لْفِضَّةِ وَ[h:1776[ٱ]لْخَيْلِ [h:1777[ٱ]لْمُسَوَّمَةِ وَ[h:1778[ٱ]لْأَنْعَ[n[ـٰ]مِ وَ[h:1779[ٱ]لْحَرْثِ‌ۗ ذ[n[َٲ]لِكَ مَتَ[n[ـٰ]عُ [h:1780[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۖ وَ[h:72[ٱ]للَّهُ عِ[f:719[ند]َهُ[n[ۥ] حُسْنُ [h:1781[ٱ]لْمَـَٔـ[p[ا][q[ب]ِ","Одамларга аёллардан, болалардан, тўп-тўп тилло ва кумушдан, гўзал отлардан, чорвадан, экин-текиндан иборат шаҳватларнинг муҳаббати зийнатланди. Улар дунё ҳаётининг матоҳидир. Аллоҳнинг ҳузурида эса, ҳуснли қайтар жой бор.",51,3],["۞ قُلْ أَؤُنَبِّئُك[c:1782[ُم ب]ِخَيْ[a:1783[رٍ م]ِّ[f:1784[ن ذ][n[َٲ]لِكُمْ‌ۚ لِلَّذِينَ [h:1785[ٱ]تَّقَوْ[s[اْ] عِ[f:264[ند]َ رَبِّهِمْ جَ[g[نّ]َ[n[ـٰ][f:1786[تٌ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا وَأَزْو[n[َٲ][a:1787[جٌ م]ُّطَهَّرَ[a:1788[ةٌ و]َرِضْو[n[َٲ][a:1789[نٌ م]ِّنَ [h:321[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ بَصِي[i:1790[رُۢ ب]ِ[h:1133[ٱ]لْعِب[p[َا][q[د]ِ","«Ўша нарсаларингиздан яхшироғининг хабарини берайми?! –деб айт. Тақво қилганларга Роббилари ҳузурида остидан анҳорлар оқиб турган жаннатлар бор. Унда абадий қолурлар. Покиза жуфтлар ва Аллоҳ томонидан розилик бор. Ва Аллоҳ бандаларни кўриб турувчидир».",51,3],["ٱلَّذِينَ يَقُولُونَ رَبَّن[o[َآ] إِ[g[نّ]َن[o[َآ] ءَامَ[g[نّ]َا فَ[h:1791[ٱ]غْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ [h:1110[ٱ][l[ل][g[نّ][p[َا]رِ","Улар: «Роббимиз, албатта, биз иймон келтирдик, бизнинг гуноҳларимизни мағфират қилгин ва дўзах азобидан сақлагин», дейдиганлардир.",52,3],["ٱ[l[ل]صَّ[n[ـٰ]بِرِينَ وَ[h:1792[ٱ][l[ل]صَّ[n[ـٰ]دِقِينَ وَ[h:1793[ٱ]لْقَ[n[ـٰ]نِتِينَ وَ[h:1794[ٱ]لْمُ[f:1794[نف]ِقِينَ وَ[h:1795[ٱ]لْمُسْتَغْفِرِينَ بِ[h:1796[ٱ]لْأَسْح[p[َا]رِ","Сабр қилувчилар, содиқлар, доимий тоат қилувчилар, нафақа қилувчилар ва саҳарда истиғфор айтувчилардир.",52,3],["شَهِدَ [h:1797[ٱ]للَّهُ أَ[g[نّ]َهُ[n[ۥ] ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ وَ[h:1146[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ وَأُ[s[وْ]لُو[s[اْ] [h:1798[ٱ]لْعِلْمِ ق[o[َا]ٓئِم[i:1799[َۢا ب]ِ[h:1800[ٱ]لْقِسْطِ‌ۚ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ [h:1734[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Аллоҳ адолат ила туриб, албатта, Ундан ўзга илоҳ йўқлигига шоҳидлик берди. Фаришталар ва илм эгалари ҳам. Ундан ўзга илоҳ йўқ. У азиз ва ҳаким зотдир.",52,3],["إِ[g[نّ]َ [h:1801[ٱ][l[ل]دِّينَ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ [h:1802[ٱ]لْإِسْلَ[n[ـٰ]مُ‌ۗ وَمَا [h:1167[ٱ]خْتَلَفَ [h:1803[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ إِلَّا م[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَهُمُ [h:1804[ٱ]لْعِلْمُ بَغْي[i:1169[َۢا ب]َيْنَهُمْ‌ۗ وَم[a:636[َن ي]َكْفُرْ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ سَرِيعُ [h:1112[ٱ]لْحِس[p[َا][q[ب]ِ","Албатта, Аллоҳнинг ҳузуридаги дин Исломдир. Китоб берилганлар фақат уларга илм келгандан сўнг ўзаро ҳасад қилишибгина ихтилоф қилдилар. Ким Аллоҳнинг оятларига куфр келтирса, бас, албатта, Аллоҳ ҳисобни тезда қилувчидир.",52,3],["فَإِنْ ح[m[َا]ٓجُّوكَ فَقُلْ أَسْلَمْتُ وَ[q:1805[جْ]هِىَ لِلَّهِ وَمَنِ [h:1806[ٱ]تَّبَعَنِ‌ۗ وَقُل لِّلَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:1807[ٱ]لْأُ[g[مّ]ِيِّـ[n[ـۧ]نَ ءَأَسْلَمْتُمْ‌ۚ فَإِنْ أَسْلَمُو[s[اْ] فَقَدِ [h:705[ٱ]هْتَدَو[s[اْ‌ۖ] وَّإِ[f:706[ن ت]َوَلَّوْ[s[اْ] فَإِ[g[نّ]َمَا عَلَيْكَ [h:1808[ٱ]لْبَلَ[n[ـٰ]غُ‌ۗ وَ[h:72[ٱ]للَّهُ بَصِي[i:1790[رُۢ ب]ِ[h:1133[ٱ]لْعِب[p[َا][q[د]ِ","Агар сен билан тортишсалар, сен: «Мен юзимни Аллоҳга таслим этдим ва менга эргашганлар ҳам!» деб айт. Ва китоб берилганларга ва саводсизларга: «Исломга кирдингизми?» деб айт. Агар Исломга кирсалар, бас, батаҳқиқ, ҳидоят топдилар. Агар юз ўгирсалар, сенинг зиммангда етказиш, холос. Аллоҳ бандаларни кўриб турувчидир.",52,3],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَكْفُرُونَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ وَيَ[q:323[قْ]تُلُونَ [h:324[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ بِغَيْرِ حَ[a:1809[قٍّ و]َيَ[q:323[قْ]تُلُونَ [h:1810[ٱ]لَّذِينَ يَأْمُرُونَ بِ[h:1800[ٱ]لْقِسْطِ مِنَ [h:721[ٱ][l[ل][g[نّ]َاسِ فَبَشِّرْه[c:1811[ُم ب]ِعَذَابٍ أَل[p[ِي]مٍ","Албатта, Аллоҳнинг оятларига куфр келтирадиганлар, Пайғамбарларни ноҳақдан ўлдирадиганлар ва одамлардан адолатга буюрадиганларни ўлдирадиганларга аламли азобнинг башоратини бер.",52,3],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ حَبِطَتْ أَعْمَ[n[ـٰ]لُهُمْ فِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ وَمَا لَه[w:1812[ُم م]ّ[a:1813[ِن ن]َّ[n[ـٰ]صِر[p[ِي]نَ","Ана ўшалар амаллари бу дунёю охиратда ҳабата бўлганлардир ва уларга ёрдам берувчилар йўқдир.",52,3],["أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ أُوتُو[s[اْ] نَصِي[a:1814[بًا م]ِّنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ يُ[q:1815[دْ]عَوْنَ إِلَىٰ كِتَ[n[ـٰ]بِ [h:1816[ٱ]للَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُ[g[مّ]َ يَتَوَلَّىٰ فَرِي[a:388[قٌ م]ِّنْهُمْ وَه[w:1817[ُم م]ُّعْرِض[p[ُو]نَ","Китобдан насиба берилганларга қарамайсанми?! Ораларида ҳукм юритиш учун Аллоҳнинг китобига чақирилганларида улардан бир гуруҳлари юз ўгириб ортга қайтадилар.",53,3],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ قَالُو[s[اْ] لَ[f:404[ن ت]َمَسَّنَا [h:405[ٱ][l[ل][g[نّ]َارُ إِلّ[o[َآ] أَيَّا[a:952[مًا م]َّعْدُود[n[َٲ][a:1818[تٍ‌ۖ و]َغَرَّهُمْ فِى دِينِه[w:1819[ِم م]َّا كَانُو[s[اْ] يَفْتَر[p[ُو]نَ","Бунинг сабаби–уларнинг: «Бизга саноқли кунлардан бошқа ҳеч ўт тегмайди», деганларидадир. Тўқиган нарсалари уларни динларида адаштирди.",53,3],["فَكَيْفَ إِذَا جَمَعْنَ[n[ـٰ]هُمْ لِيَوْ[u:1750[مٍ ل]َّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْ[a:1654[سٍ م]َّا كَسَبَتْ وَهُمْ لَا يُظْلَم[p[ُو]نَ","Унда, бўлишида шубҳа йўқ кунда уларни жамлаганимизда ва ҳар бир жон зулм қилинмасдан, қилганига яраша жазосини олганда, ҳоллари қандай бўлади?",53,3],["قُلِ [h:1820[ٱ][l[ل]لَّهُ[g[مّ]َ مَ[n[ـٰ]لِكَ [h:1821[ٱ]لْمُلْكِ تُؤْتِى [h:1822[ٱ]لْمُلْكَ مَ[f:1823[ن ت]َش[o[َا]ٓءُ وَتَ[f:1824[نز]ِعُ [h:1825[ٱ]لْمُلْكَ مِ[g[مّ]َ[f:1826[ن ت]َش[o[َا]ٓءُ وَتُعِزُّ مَ[f:1823[ن ت]َش[o[َا]ٓءُ وَتُذِلُّ مَ[f:1823[ن ت]َش[o[َا]ٓءُ‌ۖ بِيَدِكَ [h:1827[ٱ]لْخَيْرُ‌ۖ إِ[g[نّ]َكَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Сен: «Эй барча мулкнинг эгаси Роббим! Хоҳлаган кишингга мулк берурсан ва хоҳлаган кишингдан мулкни тортиб олурсан, хоҳлаган кишингни азиз қилурсан, хоҳлаган кишингни хор қилурсан. Барча яхшилик Сенинг қўлингда. Албатта, Сен ҳар бир нарсага қодирсан.",53,3],["تُولِجُ [h:1828[ٱ]لَّيْلَ فِى [h:1829[ٱ][l[ل][g[نّ]َهَارِ وَتُولِجُ [h:1830[ٱ][l[ل][g[نّ]َهَارَ فِى [h:1831[ٱ]لَّيْلِ‌ۖ وَتُخْرِجُ [h:1832[ٱ]لْحَىَّ مِنَ [h:1833[ٱ]لْمَيِّتِ وَتُخْرِجُ [h:1834[ٱ]لْمَيِّتَ مِنَ [h:1835[ٱ]لْحَىِّ‌ۖ وَتَرْزُقُ مَ[f:1823[ن ت]َش[o[َا]ٓءُ بِغَيْرِ حِس[p[َا][q[ب]ٍ","Кечани кундузга киритурсан ва кундузни кечага киритурсан, ўликдан тирикни чиқарурсан ва тирикдан ўликни чиқарурсан ҳамда хоҳлаган кишингга беҳисоб ризқ берурсан», деб айт.",53,3],["لَّا يَتَّخِذِ [h:1836[ٱ]لْمُؤْمِنُونَ [h:1837[ٱ]لْكَ[n[ـٰ]فِرِينَ أَوْلِي[o[َا]ٓءَ مِ[f:107[ن د]ُونِ [h:1838[ٱ]لْمُؤْمِنِينَ‌ۖ وَم[a:1297[َن ي]َفْعَلْ ذ[n[َٲ]لِكَ فَلَيْسَ مِنَ [h:321[ٱ]للَّهِ فِى شَىْءٍ إِلّ[o[َآ] أَ[f:1839[ن ت]َتَّقُو[s[اْ] مِنْهُمْ تُقَ[n[ـٰ][a:1840[ةً‌ۗ و]َيُحَذِّرُكُمُ [h:1841[ٱ]للَّهُ نَفْسَهُ[n[ۥ]‌ۗ وَإِلَى [h:1148[ٱ]للَّهِ [h:1842[ٱ]لْمَص[p[ِي]رُ","Мўминлар мўминларни қўйиб, кофирларни дўст тутмасинлар. Ким буни қилса, бас, унга Аллоҳдан ҳеч нарса йўқ. Магар улардан сақлансангиз, Аллоҳ сизларни ўзидан огоҳ қиладир. Ва қайтиб бориш Аллоҳнинг Ўзигадир.",53,3],["قُلْ إِ[f:1843[ن ت]ُخْفُو[s[اْ] مَا فِى صُدُورِكُمْ أَوْ تُ[q:1844[بْ]دُوهُ يَعْلَمْهُ [h:1081[ٱ]للَّهُ‌ۗ وَيَعْلَمُ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۗ وَ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Сен: «Агар қалбингиздаги нарсани махфий тутсангиз ҳам, ошкор қилсангиз ҳам, Аллоҳ биладир. Ва осмонлардагию ердаги нарсаларни ҳам биладир. Аллоҳ ҳар бир нарсага қодирдир», деб айт.",53,3],["يَوْمَ تَجِدُ كُلُّ نَفْ[a:1654[سٍ م]َّا عَمِلَتْ مِنْ خَيْ[a:1845[رٍ م]ُّحْضَ[a:1846[رًا و]َمَا عَمِلَتْ مِ[f:1847[ن س][o[ُو]ٓ[f:1848[ءٍ ت]َوَدُّ لَوْ أَ[g[نّ]َ بَيْنَهَا وَبَيْنَهُ[o[ۥٓ] أَمَد[i:1849[َۢا ب]َعِي[a:1850[دًا‌ۗ و]َيُحَذِّرُكُمُ [h:1841[ٱ]للَّهُ نَفْسَهُ[n[ۥ]‌ۗ وَ[h:72[ٱ]للَّهُ رَءُو[i:1132[فُۢ ب]ِ[h:1133[ٱ]لْعِب[p[َا][q[د]ِ","Ҳар бир жон қилган яхши амалини ҳозир топадиган ва ёмон амалини эса, у билан ўзи орасида узоқ масофа бўлишини истайдиган кунда. Аллоҳ сизларни Ўзидан огоҳ қиладир. Аллоҳ бандаларига меҳрибон зотдир.",54,3],["قُلْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تُحِبُّونَ [h:1851[ٱ]للَّهَ فَ[h:1852[ٱ]تَّبِعُونِى يُحْبِ[q:1853[بْ]كُمُ [h:1854[ٱ]للَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Сен: «Агар Аллоҳга муҳаббат қилсангиз, бас, менга эргашинг. Аллоҳ сизга муҳаббат қилади ва сизларни гуноҳларингизни мағфират қилади», деб айт.",54,3],["قُلْ أَطِيعُو[s[اْ] [h:1855[ٱ]للَّهَ وَ[h:1856[ٱ][l[ل]رَّسُولَ‌ۖ فَإِ[f:1857[ن ت]َوَلَّوْ[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ لَا يُحِبُّ [h:1858[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Аллоҳга ва Расулга итоат қилинг. Бас, агар ортга қайтсангиз, Аллоҳ, албатта, кофирларга муҳаббат қилмас.",54,3],["۞ إِ[g[نّ]َ [h:80[ٱ]للَّهَ [h:688[ٱ]صْطَفَ[o[ىٰٓ] ءَادَمَ وَنُو[a:1859[حًا و]َءَالَ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَءَالَ عِمْر[n[َٲ]نَ عَلَى [h:227[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Албатта, Аллоҳ Одамни, Нуҳни, Оли Иброҳимни, Оли Имронни оламлар устидан танлаб олди.",54,3],["ذُرِّيَّ[i:1861[ةَۢ ب]َعْضُهَا م[i:1862[ِنۢ ب]َعْ[a:1863[ضٍ‌ۗ و]َ[h:72[ٱ]للَّهُ سَمِيعٌ عَل[p[ِي]مٌ","Баъзилари баъзиларига зурриётдир. Аллоҳ эшитувчи, билувчи зотдир.",54,3],["إِذْ قَالَتِ [h:1864[ٱ]مْرَأَتُ عِمْر[n[َٲ]نَ رَبِّ إِ[g[نّ]ِى نَذَرْتُ لَكَ مَا فِى بَ[q:1865[طْ]نِى مُحَرَّ[f:1866[رًا ف]َتَقَبَّلْ مِ[g[نّ][o[ِىٓ‌ۖ] إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:668[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Имроннинг хотини: «Эй Роббим! Албатта, мен қорнимдагини холис Ўзингга назр қилдим. Бас, мендан қабул эт. Албатта, Сенинг Ўзинг эшитувчи, билувчи зотсан», деганини эсла!",54,3],["فَلَ[g[مّ]َا وَضَعَتْهَا قَالَتْ رَبِّ إِ[g[نّ]ِى وَضَعْتُه[o[َآ] أُ[f:1867[نث]َىٰ وَ[h:72[ٱ]للَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ [h:1868[ٱ][l[ل]ذَّكَرُ كَ[h:1869[ٱ]لْأُ[f:1869[نث]َىٰ‌ۖ وَإِ[g[نّ]ِى سَ[g[مّ]َيْتُهَا مَرْيَمَ وَإِ[g[نّ][o[ِىٓ] أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ [h:1870[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ [h:1871[ٱ][l[ل]رَّج[p[ِي]مِ","Уни туққан чоқда: «Эй Роббим, мен буни қиз туғдим-ку!!» деди. Ҳолбуки, Аллоҳ нима туққанини яхши билади. «Ва ўғил қиздек эмас. Ва мен унга «Марям» деб ном қўйдим ва, албатта, мен сСндан унга ва унинг зурриётига шайтонир рожим шарридан паноҳ тилайман».",54,3],["فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَ[a:1872[نٍ و]َأَ[i:1873[نۢب]َتَهَا نَبَاتًا حَسَ[a:1874[نًا و]َكَفَّلَهَا زَكَرِيَّا‌ۖ كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا [h:1875[ٱ]لْمِحْرَابَ وَجَدَ عِ[f:1876[ند]َهَا رِزْ[f:1877[قًا‌ۖ ق]َالَ يَ[n[ـٰ]مَرْيَمُ أَ[g[نّ]َىٰ لَكِ هَ[n[ـٰ]ذَا‌ۖ قَالَتْ هُوَ مِنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَرْزُقُ م[a:476[َن ي]َش[o[َا]ٓءُ بِغَيْرِ حِس[p[َا][q[ب]ٍ","Бас, уни Робби жуда яхши қабул қилиб, ниҳоятда гўзал ўстирди ва Закариёни унга кафил қилди. Закариё ҳар қачон унинг олдига, меҳробга кирганида, унинг ҳузурида ризқ кўрди. У: «Эй Марям, сенга бу қаердан?» деди. Ул: «Бу Аллоҳнинг ҳузуридан. Албатта, Аллоҳ хоҳлаган кишисига беҳисоб ризқ беради», деди.",54,3],["هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُ[n[ۥ]‌ۖ قَالَ رَبِّ هَ[q:1878[بْ] لِى م[u:1746[ِن ل]َّدُ[f:1747[نك]َ ذُرِّيَّ[f:1879[ةً ط]َيِّبَةً‌ۖ إِ[g[نّ]َكَ سَمِيعُ [h:1880[ٱ][l[ل]دُّع[o[َا]ٓءِ","Шу чоқда Закариё Роббига дуо қилиб: «Эй Роббим, менга Ўз ҳузурингдан яхши зурриёт бергин. Албатта, сен дуони эшитувчисан», деди.",55,3],["فَنَادَتْهُ [h:1881[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ وَهُوَ ق[o[َا]ٓئِ[a:1882[مٌ ي]ُصَلِّى فِى [h:1883[ٱ]لْمِحْرَابِ أَ[g[نّ]َ [h:394[ٱ]للَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّق[i:1884[َۢا ب]ِكَلِمَ[a:1885[ةٍ م]ِّنَ [h:321[ٱ]للَّهِ وَسَيِّ[a:1886[دًا و]َحَصُو[a:1887[رًا و]َنَبِي[a:1888[ًّا م]ِّنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Меҳробда намоз ўқиб турганида, фаришталар унга: «Албатта, Аллоҳ сенга Аллоҳдан бўлган калимани тасдиқловчи, бошлиқ, шаҳвати тийилган, солиҳлардан бўлган Набий, Яҳъёнинг башоратини бермоқда», дедилар.",55,3],["قَالَ رَبِّ أَ[g[نّ]َىٰ يَكُونُ لِى غُلَ[n[ـٰ][a:1890[مٌ و]َقَ[q:387[دْ] بَلَغَنِىَ [h:1891[ٱ]لْكِبَرُ وَ[h:1892[ٱ]مْرَأَتِى عَاقِ[f:1893[رٌ‌ۖ ق]َالَ كَذ[n[َٲ]لِكَ [h:1894[ٱ]للَّهُ يَفْعَلُ مَا يَش[o[َا]ٓءُ","У: «Эй Роббим, менга қандоқ ўғил бўлсин?! Ўзим улуғ ёшга кирган бўлсам, хотиним туғмас бўлса?!» деди. У зот: «Шундоқ, Аллоҳ хоҳлаганини қилади», деди.",55,3],["قَالَ رَبِّ [h:657[ٱ][q:658[جْ]عَل لّ[o[ِىٓ] ءَايَ[f:1895[ةً‌ۖ ق]َالَ ءَايَتُكَ أَلَّا تُكَلِّمَ [h:1896[ٱ][l[ل][g[نّ]َاسَ ثَلَ[n[ـٰ]ثَةَ أَيَّامٍ إِلَّا رَمْ[a:1897[زًا‌ۗ و]َ[h:1898[ٱ]ذْكُر رَّبَّكَ كَثِي[a:1899[رًا و]َسَبِّحْ بِ[h:1900[ٱ]لْعَشِىِّ وَ[h:1901[ٱ]لْإِ[q:1901[بْ]كَ[p[ـٰ]رِ","У: «Эй Роббим, менга бир белги тайинла», деди. У зот: «Сенинг белгинг, уч кун одамларга фақат ишора билан гапиришингдир. Роббингни кўп эсла ва эртаю кеч тасбиҳ айт!» деди.",55,3],["وَإِذْ قَالَتِ [h:1902[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ يَ[n[ـٰ]مَرْيَمُ إِ[g[نّ]َ [h:80[ٱ]للَّهَ [h:1903[ٱ]صْطَفَ[n[ـٰ]كِ وَطَهَّرَكِ وَ[h:1904[ٱ]صْطَفَ[n[ـٰ]كِ عَلَىٰ نِس[o[َا]ٓءِ [h:1905[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Фаришталарнинг: «Эй Марям, албатта, Аллоҳ сени танлаб олди, поклади ва оламдаги аёллардан устунлигингни ихтиёр қилди.",55,3],["يَ[n[ـٰ]مَرْيَمُ [h:1906[ٱ][q:1907[قْ]نُتِى لِرَبِّكِ وَ[h:1908[ٱ]سْجُدِى وَ[h:1909[ٱ]رْكَعِى مَعَ [h:217[ٱ][l[ل]رّ[n[َٲ]كِع[p[ِي]نَ","Эй Марям, Роббингнинг ибодатида бардавом бўл, Унга сажда қил ва рукуъ қилувчилар билан рукуъ қил», деганларини эсла.",55,3],["ذ[n[َٲ]لِكَ مِنْ أَ[i:1910[نۢب][o[َا]ٓءِ [h:1911[ٱ]لْغَيْبِ نُوحِيهِ إِلَيْكَ‌ۚ وَمَا كُ[f:735[نت]َ لَدَيْهِمْ إِذْ يُلْقُونَ أَ[q:1912[قْ]لَ[n[ـٰ]مَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُ[f:735[نت]َ لَدَيْهِمْ إِذْ يَخْتَصِم[p[ُو]نَ","Бу ғайб хабарлардан бўлиб, сенга ваҳий қилмоқдамиз. Улар қайсилари Марямнинг кафили бўлишига қаламларини ташлашаётганларида, олдиларида эмасдинг ва тортишаётганларида ҳам олдиларида эмасдинг.",55,3],["إِذْ قَالَتِ [h:1902[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ يَ[n[ـٰ]مَرْيَمُ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُبَشِّرُكِ بِكَلِمَ[a:1913[ةٍ م]ِّنْهُ [h:1914[ٱ]سْمُهُ [h:1915[ٱ]لْمَسِيحُ عِيسَى [h:1916[ٱ][q:1917[بْ]نُ مَرْيَمَ وَجِي[f:1918[هًا ف]ِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ وَمِنَ [h:1919[ٱ]لْمُقَرَّب[p[ِي]نَ","Фаришталар: «Эй Марям, албатта, Аллоҳ сенга Ўзидан бўлган сўзнинг башоратини бермоқда, унинг исми Масиҳ, Ийсо ибн Марям бу дунёю охиратда обрўли ва яқин бандалардандир.",55,3],["وَيُكَلِّمُ [h:1920[ٱ][l[ل][g[نّ]َاسَ فِى [h:1921[ٱ]لْمَهْدِ وَكَهْل[a:1922[اً و]َمِنَ [h:1923[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","У одамларга бешикда ҳам, қариган чоғида ҳам гапиради ва солиҳлардандир», деганларини эсла.",56,3],["قَالَتْ رَبِّ أَ[g[نّ]َىٰ يَكُونُ لِى وَلَ[a:1924[دٌ و]َلَمْ يَمْسَسْنِى بَشَ[f:1925[رٌ‌ۖ ق]َالَ كَذ[n[َٲ]لِكِ [h:1926[ٱ]للَّهُ يَخْلُقُ مَا يَش[o[َا]ٓءُ‌ۚ إِذَا قَضَ[o[ىٰٓ] أَمْ[f:612[رًا ف]َإِ[g[نّ]َمَا يَقُولُ لَهُ[n[ۥ] كُ[f:613[ن ف]َيَك[p[ُو]نُ","У: «Эй Роббим, менга башар қўл теккизмаган бўлса, қандай қилиб болам бўлади?!» деди. У зот: «Шундай, Аллоҳ хоҳлаганини қиладир. Бир ишни ирода қилса, «Бўл!» дейиши кифоя, бўлаверадир», деди.",56,3],["وَيُعَلِّمُهُ [h:1927[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:679[ٱ]لْحِكْمَةَ وَ[h:1928[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةَ وَ[h:1725[ٱ]لْإِ[f:1725[نج][p[ِي]لَ","Ва унга китобни, ҳикматни, Таврот ва Инжилни ўргатадир.",56,3],["وَرَسُولاً إِلَىٰ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ أَ[g[نّ]ِى قَ[q:298[دْ] جِئْتُك[c:1929[ُم ب]ِـَٔـايَ[a:1930[ةٍ م]ّ[u:243[ِن ر]َّبِّكُمْ‌ۖ أَ[g[نّ][o[ِىٓ] أَخْلُقُ لَك[w:1578[ُم م]ِّنَ [h:1931[ٱ][l[ل]طِّينِ كَهَيْــَٔةِ [h:1932[ٱ][l[ل]طَّيْرِ فَأَ[f:1933[نف]ُخُ فِيهِ فَيَكُونُ طَيْر[i:1934[َۢا ب]ِإِذْنِ [h:509[ٱ]للَّهِ‌ۖ وَأُ[q:1935[بْ]رِئُ [h:1936[ٱ]لْأَكْمَهَ وَ[h:1937[ٱ]لْأَ[q:1937[بْ]رَصَ وَأُحْىِ [h:1938[ٱ]لْمَوْتَىٰ بِإِذْنِ [h:509[ٱ]للَّهِ‌ۖ وَأُنَبِّئُك[c:1939[ُم ب]ِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:1410[ةً ل]َّكُمْ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Бани Исроилга Пайғамбар қиладир. У: «Албатта, мен сизга Роббингиздан оят-мўжиза келтирдим, мен сизларга лойдан қушга ўхшаш суврат ясайман, унга пуфласам, Аллоҳнинг изни билан қуш бўлади. Аллоҳ изни билан туғма кўр ва песларни тузатаман ва ўликни тирилтираман. Сизларга нимани емоқдасизу, нимани уйингизда сақлаяпсиз–хабарини бераман. Агар мўмин бўлсангиз, албатта, бунда сизга оят-белги бордир.",56,3],["وَمُصَدِّ[u:1940[قًا ل]ِّمَا بَيْنَ يَدَىَّ مِنَ [h:1941[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةِ وَلِأُحِلَّ لَك[c:1942[ُم ب]َعْضَ [h:1943[ٱ]لَّذِى حُرِّمَ عَلَيْكُمْ‌ۚ وَجِئْتُك[c:1944[ُم ب]ِـَٔـايَ[a:1930[ةٍ م]ّ[u:243[ِن ر]َّبِّكُمْ فَ[h:112[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَطِيع[p[ُو]نِ","Ва ўзимдан аввалги Тавротни тасдиқловчи бўлиб, сизга ҳаром қилинганнинг баъзисини ҳалол қилиш учун келдим. Сизга Роббингиздан оят-мўъжиза билан келдим. Аллоҳга тақво қилинг ва менга итоат этинг.",56,3],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ رَبِّى وَرَبُّكُمْ فَ[h:1946[ٱ]عْبُدُوهُ‌ۗ هَ[n[ـٰ]ذَا صِر[n[َٲ][a:1947[طٌ م]ُّسْتَق[p[ِي]مٌ","Албатта, Аллоҳ менинг Роббим ва сизнинг Роббингиздир. Бас, Унга ибодат қилинг. Бу–сироти мустақимдир», дейдир.",56,3],["۞ فَلَ[g[مّ][o[َآ] أَحَسَّ عِيسَىٰ مِنْهُمُ [h:1948[ٱ]لْكُفْرَ قَالَ مَنْ أَ[f:1949[نص]َار[o[ِىٓ] إِلَى [h:1637[ٱ]للَّهِ‌ۖ قَالَ [h:1950[ٱ]لْحَوَارِيُّونَ نَحْنُ أَ[f:1951[نص]َارُ [h:1952[ٱ]للَّهِ ءَامَ[g[نّ]َا بِ[h:32[ٱ]للَّهِ وَ[h:1953[ٱ]شْهَ[q:1953[دْ] بِأَ[g[نّ]َا مُسْلِم[p[ُو]نَ","Ийсо улардан кофирликни сезиб қолганда: «Кимлар Аллоҳ йўлида менга ёрдамчи бўлади?!» деди. Ҳаворийлар: «Биз Аллоҳнинг ёрдамчиларимиз, Аллоҳга иймон келтирдик ва бизнинг мусулмонлигимизга гувоҳ бўл.",56,3],["رَبَّن[o[َآ] ءَامَ[g[نّ]َا بِم[o[َآ] أَ[f:1954[نز]َلْتَ وَ[h:1955[ٱ]تَّبَعْنَا [h:1956[ٱ][l[ل]رَّسُولَ فَ[h:1957[ٱ]كْتُ[q:1957[بْ]نَا مَعَ [h:1958[ٱ][l[ل]شَّ[n[ـٰ]هِد[p[ِي]نَ","Эй Роббимиз! Сен туширган нарсага иймон келтирдик ва Пайғамбарга эргашдик. Бас, бизни гувоҳлик берувчилар қаторига ёзгин», дедилар",57,3],["وَمَكَرُو[s[اْ] وَمَكَرَ [h:1959[ٱ]للَّهُ‌ۖ وَ[h:72[ٱ]للَّهُ خَيْرُ [h:1960[ٱ]لْمَ[n[ـٰ]كِر[p[ِي]نَ","Макр қилдилар. Аллоҳ ҳам макр қилди. Аллоҳ макр қилувчиларнинг «зўри»дир.",57,3],["إِذْ قَالَ [h:1961[ٱ]للَّهُ يَ[n[ـٰ]عِيسَ[o[ىٰٓ] إِ[g[نّ]ِى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ [h:523[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَجَاعِلُ [h:1962[ٱ]لَّذِينَ [h:1963[ٱ]تَّبَعُوكَ فَوْقَ [h:1964[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۖ ثُ[g[مّ]َ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُ[f:100[نت]ُمْ فِيهِ تَخْتَلِف[p[ُو]نَ","Аллоҳ: «Эй Ийсо, Мен сени вафот қилдирувчи ва Ўзимга кўтарувчиман ҳамда куфр келтирганлардан сени покловчиман ва қиёмат кунигача сенга эргашганларни куфр келтирганлардан устун қўювчиман. Сўнгра қайтиш жойингиз Ўзимга, бас, ихтилоф қилган нарсаларингиз бўйича орангизда Ўзим ҳукм чиқараман», деганини эсла!",57,3],["فَأَ[g[مّ]َا [h:136[ٱ]لَّذِينَ كَفَرُو[s[اْ] فَأُعَذِّبُهُمْ عَذَا[f:1966[بًا ش]َدِي[f:1967[دًا ف]ِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ وَمَا لَه[w:1812[ُم م]ّ[a:1813[ِن ن]َّ[n[ـٰ]صِر[p[ِي]نَ","Бас, куфр келтирганларни бу дунёю у дунёда шиддатли азоб ила азоблайман. Уларга ёрдам берувчилар йўқдир.",57,3],["وَأَ[g[مّ]َا [h:138[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ فَيُوَفِّيهِمْ أُجُورَهُمْ‌ۗ وَ[h:72[ٱ]للَّهُ لَا يُحِبُّ [h:1968[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Иймон келтирган ва яхши амаллар қилганларнинг ажрини тўлиқ беради. Ва Аллоҳ золимларни хуш кўрмас.",57,3],["ذ[n[َٲ]لِكَ نَتْلُوهُ عَلَيْكَ مِنَ [h:1969[ٱ]لْأَيَ[n[ـٰ]تِ وَ[h:1970[ٱ][l[ل]ذِّكْرِ [h:1971[ٱ]لْحَك[p[ِي]مِ","Бу сенга тиловат қилиб бераётганимиз оятлар ва ҳаким эслатмадандир.",57,3],["إِ[g[نّ]َ مَثَلَ عِيسَىٰ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ كَمَثَلِ ءَادَمَ‌ۖ خَلَقَهُ[n[ۥ] مِ[f:1972[ن ت]ُرَا[f:1973[بٍ ث]ُ[g[مّ]َ قَالَ لَهُ[n[ۥ] كُ[f:613[ن ف]َيَك[p[ُو]نُ","Албатта, Аллоҳнинг ҳузурида Ийсонинг мисоли худди Одамнинг мисолига ўхшайди. Уни тупроқдан яратиб, сўнгра унга «Бўл!» деди, бас, бўлди.",57,3],["ٱلْحَقُّ م[u:770[ِن ر]َّبِّكَ فَلَا تَك[a:1974[ُن م]ِّنَ [h:771[ٱ]لْمُمْتَر[p[ِي]نَ","Бу ҳақиқат Роббингдандир, бас, шак келтирувчилардан бўлма.",57,3],["فَمَنْ ح[m[َا]ٓجَّكَ فِيهِ م[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَكَ مِنَ [h:634[ٱ]لْعِلْمِ فَقُلْ تَعَالَوْ[s[اْ] نَ[q:1975[دْ]عُ أَ[q:1976[بْ]ن[o[َا]ٓءَنَا وَأَ[q:1977[بْ]ن[o[َا]ٓءَكُمْ وَنِس[o[َا]ٓءَنَا وَنِس[o[َا]ٓءَكُمْ وَأَ[f:1978[نف]ُسَنَا وَأَ[f:1979[نف]ُسَكُمْ ثُ[g[مّ]َ نَ[q:1980[بْ]تَهِلْ فَنَ[q:1981[جْ]عَل لَّعْنَتَ [h:1982[ٱ]للَّهِ عَلَى [h:1983[ٱ]لْكَ[n[ـٰ]ذِب[p[ِي]نَ","Сенга келган илмдан кейин, ким сен билан у ҳақида тортишса: «Келинглар, бизнинг болаларимизни ва сизнинг болаларингизни, бизнинг аёлларимизни ва сизнинг аёлларингизни, биз ўзимизни, сиз ўзингизни чақирамиз-да, сўнгра ёлбориб, ёлғончиларга Аллоҳнинг лаънати бўлишини сўраймиз», деб айтгин.",57,3],["إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَهُوَ [h:1984[ٱ]لْقَصَصُ [h:1985[ٱ]لْحَقُّ‌ۚ وَمَا مِنْ إِلَ[n[ـٰ]هٍ إِلَّا [h:1742[ٱ]للَّهُ‌ۚ وَإِ[g[نّ]َ [h:1986[ٱ]للَّهَ لَهُوَ [h:1987[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Албатта, бу ўзи ҳақ қиссадир. Аллоҳдан ўзга ҳеч бир илоҳ йўқ. Албатта, Аллоҳ, Унинг Ўзи азиз ва ҳаким зотдир.",58,3],["فَإِ[f:1857[ن ت]َوَلَّوْ[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ عَلِي[i:1988[مُۢ ب]ِ[h:1989[ٱ]لْمُفْسِد[p[ِي]نَ","Агар юз ўгириб кетсалар, бас, албатта, Аллоҳ фасод қилувчиларни билувчидир.",58,3],["قُلْ يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ تَعَالَوْ[s[اْ] إِلَىٰ كَلِمَ[f:1991[ةٍ س]َو[o[َا]ٓ[i:1992[ءِۭ ب]َيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا [h:416[ٱ]للَّهَ وَلَا نُشْرِكَ بِه[n[ِۦ] شَيْـ[a:232[ـًٔا و]َلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَا[a:1993[بًا م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ‌ۚ فَإِ[f:1857[ن ت]َوَلَّوْ[s[اْ] فَقُولُو[s[اْ] [h:1994[ٱ]شْهَدُو[s[اْ] بِأَ[g[نّ]َا مُسْلِم[p[ُو]نَ","Сен: «Эй аҳли китоблар! Бизга ҳам, сизга ҳам баробар сўзга келинг: Аллоҳдан ўзгага ибодат қилмайлик, Унга ҳеч нарсани шерик қилмайлик ва Аллоҳни қўйиб, баъзимиз баъзимизни Робб қилиб олмайлик», дегин. Бас, агар юз ўгирсалар: «Гувоҳ бўлинглар, биз, албатта, мусулмонлармиз», деб айтинглар.",58,3],["يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ لِمَ تُح[m[َا]ٓجُّونَ ف[o[ِىٓ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَم[o[َآ] أُ[f:1995[نز]ِلَتِ [h:1996[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةُ وَ[h:1997[ٱ]لْإِ[f:1997[نج]ِيلُ إِلَّا م[i:254[ِنۢ ب]َعْدِه[o[ِۦٓ‌ۚ] أَفَلَا تَعْقِل[p[ُو]نَ","Эй аҳли китоблар, нимага Иброҳим ҳақида талашасизлар. Ҳолбуки, Таврот ҳам, Инжил ҳам ундан кейин тушган-ку! Ақл юритмайсизларми?!",58,3],["هَ[o[ـٰٓ]أَ[f:1998[نت]ُمْ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ حَ[n[ـٰ]جَ[q:1999[جْ]تُمْ فِيمَا لَك[c:2000[ُم ب]ِه[n[ِۦ] عِلْ[f:2001[مٌ ف]َلِمَ تُح[m[َا]ٓجُّونَ فِيمَا لَيْسَ لَك[c:2000[ُم ب]ِه[n[ِۦ] عِلْ[a:2002[مٌ‌ۚ و]َ[h:72[ٱ]للَّهُ يَعْلَمُ وَأَ[f:98[نت]ُمْ لَا تَعْلَم[p[ُو]نَ","Ҳой сизлар, ҳалигилар! Ўзингиз билган нарсада-ку талашдингиз, энди нимага ўзингиз билмаган нарсада талашмоқдасиз?! Аллоҳ билади, сиз эса билмайсиз.",58,3],["مَا كَانَ إِ[q:2003[بْ]ر[n[َٲ]هِيمُ يَهُودِي[a:2004[ًّا و]َلَا نَصْرَانِي[a:2005[ًّا و]َلَ[n[ـٰ]كِ[f:2006[ن ك]َانَ حَنِي[a:2007[فًا م]ُّسْلِ[a:2008[مًا و]َمَا كَانَ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Иброҳим яҳудий ҳам, насроний ҳам бўлмаган эди. Лекин у ҳақ йўлдан тоймаган мусулмон эди. Ва мушриклардан ҳам бўлмаган.",58,3],["إِ[g[نّ]َ أَوْلَى [h:2009[ٱ][l[ل][g[نّ]َاسِ بِإِ[q:2010[بْ]ر[n[َٲ]هِيمَ لَلَّذِينَ [h:2011[ٱ]تَّبَعُوهُ وَهَ[n[ـٰ]ذَا [h:2012[ٱ][l[ل][g[نّ]َبِىُّ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ‌ۗ] وَ[h:72[ٱ]للَّهُ وَلِىُّ [h:2013[ٱ]لْمُؤْمِن[p[ِي]نَ","Албатта, одамларнинг Иброҳимга ҳақлироғи унга эргашганлар, мана бу Набий ва иймон келтирганлардир. Аллоҳ мўминларнинг валийсидир.",58,3],["وَدَّ[d:2014[ت] طّ[o[َا]ٓئِفَ[a:2015[ةٌ م]ِّنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلّ[o[َآ] أَ[f:38[نف]ُسَهُمْ وَمَا يَشْعُر[p[ُو]نَ","Аҳли китоблардан бир тоифалари сизни адаштиришни хоҳлайдилар. Ўзларидан бошқани адаштирмайдилар ва лекин сезмаслар.",58,3],["يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ لِمَ تَكْفُرُونَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ وَأَ[f:98[نت]ُمْ تَشْهَد[p[ُو]نَ","Эй аҳли китоблар, нимага ўзингиз гувоҳ бўлиб туриб, Аллоҳнинг оятларига куфр келтирасиз?!",58,3],["يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ لِمَ تَلْبِسُونَ [h:2016[ٱ]لْحَقَّ بِ[h:212[ٱ]لْبَ[n[ـٰ]طِلِ وَتَكْتُمُونَ [h:2017[ٱ]لْحَقَّ وَأَ[f:98[نت]ُمْ تَعْلَم[p[ُو]نَ","Эй аҳли китоблар, нимага ҳақни ботилга аралаштирасизлар ва билиб туриб ҳақни яширасизлар?!",59,3],["وَقَالَ[d:2018[ت] طّ[o[َا]ٓئِفَ[a:2015[ةٌ م]ِّنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ ءَامِنُو[s[اْ] بِ[h:315[ٱ]لَّذ[o[ِىٓ] أُ[f:17[نز]ِلَ عَلَى [h:289[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَ[q:2019[جْ]هَ [h:2020[ٱ][l[ل][g[نّ]َهَارِ وَ[h:2021[ٱ]كْفُر[o[ُوٓ][s[اْ] ءَاخِرَهُ[n[ۥ] لَعَلَّهُمْ يَرْجِع[p[ُو]نَ","Аҳли китоблардан бир тоифалари: «Иймон келтирганларга тушган нарсага куннинг аввалида иймон келтиринглар ва куннинг охирида куфр келтиринглар, шоядки қайтсалар.",59,3],["وَلَا تُؤْمِن[o[ُوٓ][s[اْ] إِلَّا لِمَ[f:2022[ن ت]َبِعَ دِينَكُمْ قُلْ إِ[g[نّ]َ [h:2023[ٱ]لْهُدَىٰ هُدَى [h:629[ٱ]للَّهِ أ[a:2024[َن ي]ُؤْتَ[o[ىٰٓ] أَحَ[a:2025[دٌ م]ِّثْلَ م[o[َآ] أُوتِيتُمْ أَوْ يُح[m[َا]ٓجُّوكُمْ عِ[f:264[ند]َ رَبِّكُمْ‌ۗ قُلْ إِ[g[نّ]َ [h:2026[ٱ]لْفَضْلَ بِيَدِ [h:2027[ٱ]للَّهِ يُؤْتِيهِ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۗ وَ[h:72[ٱ]للَّهُ و[n[َٲ]سِعٌ عَل[p[ِي]مٌ","Ва динингизга эргашганлардан бошқаларга ишонманглар, токи бирортага сизга берилганга ўхшаш нарса берилмасин ёки Роббингиз ҳузурида сиз билан ҳужжат талашмасин», дейдилар. Сен: «Албатта, ҳақиқий ҳидоят Аллоҳнинг ҳидоятидир», деб айт. Сен: «Албатта фазл Аллоҳнинг қўлида–хоҳлаган кишисига беради. Аллоҳ кенг қамровли, билувчи зотдир.",59,3],["يَخْتَصُّ بِرَحْمَتِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ‌ۗ وَ[h:72[ٱ]للَّهُ ذُو [h:550[ٱ]لْفَضْلِ [h:551[ٱ]لْعَظ[p[ِي]مِ","Ўз раҳматини хоҳлаган кишисигахос қилади ва Аллоҳ улуғ фазл эгасидир», деб айт.",59,3],["۞ وَمِنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ مَنْ إِ[f:2028[ن ت]َأْمَنْهُ بِقِ[f:2029[نط]َا[a:2030[رٍ ي]ُؤَدِّه[o[ِۦٓ] إِلَيْكَ وَمِنْه[w:1106[ُم م]َّنْ إِ[f:2028[ن ت]َأْمَنْهُ بِدِينَا[u:2031[رٍ ل]َّا يُؤَدِّه[o[ِۦٓ] إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ ق[o[َا]ٓئِ[f:2032[مًا‌ۗ ذ][n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ قَالُو[s[اْ] لَيْسَ عَلَيْنَا فِى [h:2033[ٱ]لْأُ[g[مّ]ِيِّـ[n[ـۧ]نَ سَبِي[a:2034[لٌ و]َيَقُولُونَ عَلَى [h:412[ٱ]للَّهِ [h:2035[ٱ]لْكَذِبَ وَهُمْ يَعْلَم[p[ُو]نَ","Аҳли китоблардан, агар ҳисобсиз молни омонат қўйсангиз, уни сенга адо қиладиганлари бор ва бир динорни омонат қўйсанг, устида туриб олмагунингча, сенга адо қилмайдиганлари ҳам бор. Бу уларнинг, омийлар учун бизнинг устимизга йўл йўқ, дейишларидандир. Улар билиб туриб Аллоҳ ҳақида ёлғон сўзлайдилар.",59,3],["بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِه[n[ِۦ] وَ[h:2036[ٱ]تَّقَىٰ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ يُحِبُّ [h:2037[ٱ]لْمُتَّق[p[ِي]نَ","Йўқ! Балки ким аҳдига вафо қилса ва тақводор бўлса. Бас, Аллоҳ тақводорларни хуш кўради.",59,3],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَشْتَرُونَ بِعَهْدِ [h:2038[ٱ]للَّهِ وَأَيْمَ[n[ـٰ]نِهِمْ ثَمَ[f:208[نًا ق]َلِيلاً أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَا خَلَ[n[ـٰ]قَ لَهُمْ فِى [h:536[ٱ]لْأَخِرَةِ وَلَا يُكَلِّمُهُمُ [h:893[ٱ]للَّهُ وَلَا يَ[f:2039[نظ]ُرُ إِلَيْهِمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Аллоҳнинг аҳдини ва ўз қасамларини арзон баҳога сотадиганлар, албатта, ана ўшаларга охиратда насиба йўқдир, қиёмат куни Аллоҳ уларга гапирмас, назар солмас ва покламас. Уларга аламли азоблар бор.",59,3],["وَإِ[g[نّ]َ مِنْهُمْ لَفَرِي[a:2040[قًا ي]َلْوُ[n[ۥ]نَ أَلْسِنَتَه[c:2041[ُم ب]ِ[h:2042[ٱ]لْكِتَ[n[ـٰ]بِ لِتَحْسَبُوهُ مِنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ وَمَا هُوَ مِنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ وَيَقُولُونَ هُوَ مِنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ وَمَا هُوَ مِنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ وَيَقُولُونَ عَلَى [h:412[ٱ]للَّهِ [h:2035[ٱ]لْكَذِبَ وَهُمْ يَعْلَم[p[ُو]نَ","Улардан бир гуруҳлари борки, сизлар китобдан бўлмаган нарсани китобдан деб ўйлашингиз учун, китобни тилларини буриб ўқирлар. Ва: «У Аллоҳнинг ҳузуридандир», дерлар. Ҳолбуки, у Аллоҳнинг ҳузуридан эмас. Улар билиб туриб Аллоҳ ҳақида ёлғон сўзларлар.",60,3],["مَا كَانَ لِبَشَرٍ أ[a:2043[َن ي]ُؤْتِيَهُ [h:2044[ٱ]للَّهُ [h:2045[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:2046[ٱ]لْحُكْمَ وَ[h:2047[ٱ][l[ل][g[نّ]ُبُوَّةَ ثُ[g[مّ]َ يَقُولَ لِل[g[نّ]َاسِ كُونُو[s[اْ] عِبَا[u:2048[دًا ل]ِّى مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَلَ[n[ـٰ]كِ[f:2049[ن ك]ُونُو[s[اْ] رَبَّ[n[ـٰ]نِيِّـ[n[ـۧ]نَ بِمَا كُ[f:100[نت]ُمْ تُعَلِّمُونَ [h:2050[ٱ]لْكِتَ[n[ـٰ]بَ وَبِمَا كُ[f:100[نت]ُمْ تَ[q:2051[دْ]رُس[p[ُو]نَ","Бир кишига Аллоҳ китобни, ҳукмни ва Пайғамбарликни берганидан сўнг, у одамларга: «Аллоҳни қўйиб менга банда бўлинглар», дейиши асло мумкин эмас. Лекин одамларга: «Китобни ўргатганингиз ва ўзингиз ўрганганингиз асосида Роббонийлар бўлинг», дейдир.",60,3],["وَلَا يَأْمُرَكُمْ أَ[f:2052[ن ت]َتَّخِذُو[s[اْ] [h:2053[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةَ وَ[h:907[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ أَرْبَابًا‌ۗ أَيَأْمُرُك[c:2054[ُم ب]ِ[h:2055[ٱ]لْكُفْرِ بَعْدَ إِذْ أَ[f:428[نت][w:2056[ُم م]ُّسْلِم[p[ُو]نَ","У сизларни фаришталар ва Пайғамбарларни Робб қилиб олишингизга буюрмайди. У сизни мусулмон бўлганингиздан кейин куфрга буюрармиди?!",60,3],["وَإِذْ أَخَذَ [h:2057[ٱ]للَّهُ مِيثَ[n[ـٰ]قَ [h:2058[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ لَم[o[َآ] ءَاتَيْتُك[w:2059[ُم م]ِّ[f:2060[ن ك]ِتَ[n[ـٰ][a:2061[بٍ و]َحِكْمَ[f:2062[ةٍ ث]ُ[g[مّ]َ ج[o[َا]ٓءَكُمْ رَسُو[a:2063[لٌ م]ُّصَدِّ[u:465[قٌ ل]ِّمَا مَعَكُمْ لَتُؤْمِنُ[g[نّ]َ بِه[n[ِۦ] وَلَتَ[f:2064[نص]ُرُ[g[نّ]َهُ[n[ۥ]‌ۚ قَالَ ءَأَ[q:2065[قْ]رَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذ[n[َٲ]لِكُمْ إِصْرِى‌ۖ قَال[o[ُوٓ][s[اْ] أَ[q:2066[قْ]رَرْنَا‌ۚ قَالَ فَ[h:2067[ٱ]شْهَدُو[s[اْ] وَأَنَا۟ مَعَك[w:2068[ُم م]ِّنَ [h:2069[ٱ][l[ل]شَّ[n[ـٰ]هِد[p[ِي]نَ","Аллоҳ Набийлардан: «Сизларга китоб ва ҳикмат берганим учун, кетингиздан сизлардаги нарсани тасдиқловчи Пайғамбар келганда, албатта унга иймон келтирасиз ва ёрдам берасиз, –деб аҳду паймонларини олиб туриб: –Иқрор бўлдингизми? Бу ҳақда ишончли аҳду паймонимни қабул қилдингизми?» деганини эсла. Улар: «Иқрор бўлдик», дейишди. У: «Бас, гувоҳ бўлинглар, мен ҳам гувоҳ бўлувчиларданман», деди.",60,3],["فَمَ[f:2070[ن ت]َوَلَّىٰ بَعْدَ ذ[n[َٲ]لِكَ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:2071[ٱ]لْفَ[n[ـٰ]سِق[p[ُو]نَ","Ким бундан кейин юз ўгириб кетса, бас, ана ўшалар, фосиқлардир.",60,3],["أَفَغَيْرَ دِينِ [h:2072[ٱ]للَّهِ يَ[q:2073[بْ]غُونَ وَلَهُ[o[ۥٓ] أَسْلَمَ مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ طَوْ[a:2075[عًا و]َكَرْ[a:2076[هًا و]َإِلَيْهِ يُرْجَع[p[ُو]نَ","Аллоҳнинг динидан бошқани хоҳлайдиларми?! Ахир хоҳласаю хоҳламаса, осмонлару ердаги барча жонзотлар Аллоҳга бўйсуниб турибди-ку?! Ҳамда Унга қайтариладилар-ку?!!",60,3],["قُلْ ءَامَ[g[نّ]َا بِ[h:32[ٱ]للَّهِ وَم[o[َآ] أُ[f:17[نز]ِلَ عَلَيْنَا وَم[o[َآ] أُ[f:17[نز]ِلَ عَلَ[o[ىٰٓ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَإِسْمَ[n[ـٰ]عِيلَ وَإِسْحَ[n[ـٰ]قَ وَيَعْقُوبَ وَ[h:700[ٱ]لْأَسْبَاطِ وَم[o[َآ] أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَ[h:2077[ٱ][l[ل][g[نّ]َبِيُّونَ م[u:22[ِن ر]َّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَ[a:702[دٍ م]ِّنْهُمْ وَنَحْنُ لَهُ[n[ۥ] مُسْلِم[p[ُو]نَ","Сен: «Аллоҳга ва бизга туширилган нарсага, Иброҳим, Исмоил, Исҳоқ, Яъқуб ва асботларга туширилган нарсага, Мусо, Ийсо ва Набийларга Роббиларидан берилган нарсага иймон келтирдик, улардан бирортасини ажратмаймиз ва биз Унгагина мусулмонмиз!» деб айт!",61,3],["وَم[a:2078[َن ي]َ[q:2079[بْ]تَغِ غَيْرَ [h:2080[ٱ]لْإِسْلَ[n[ـٰ]مِ دِي[f:2081[نًا ف]َل[a:2082[َن ي]ُ[q:2083[قْ]بَلَ مِنْهُ وَهُوَ فِى [h:536[ٱ]لْأَخِرَةِ مِنَ [h:340[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","Ким Исломдан бошқа динни хоҳласа, бас, ундан бу ҳаргиз қабул қилинмас ва у охиратда зиён кўргувчилардан бўладир.",61,3],["كَيْفَ يَهْدِى [h:2084[ٱ]للَّهُ قَوْ[f:2085[مًا ك]َفَرُو[s[اْ] بَعْدَ إِيمَ[n[ـٰ]نِهِمْ وَشَهِد[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:2086[ٱ][l[ل]رَّسُولَ حَ[a:2087[قٌّ و]َج[o[َا]ٓءَهُمُ [h:2088[ٱ]لْبَيِّنَ[n[ـٰ]تُ‌ۚ وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Аллоҳ иймонидан, Пайғамбарнинг ҳақлигига гувоҳлик берганидан ва уларга очиқ баёнотлар келганидан кейин куфр кетган қавмни қандай қилиб ҳидоятга солади. Аллоҳ золим қавмларни ҳидоятга солмас.",61,3],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ جَز[o[َا]ٓؤُهُمْ أَ[g[نّ]َ عَلَيْهِمْ لَعْنَةَ [h:2089[ٱ]للَّهِ وَ[h:823[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ وَ[h:824[ٱ][l[ل][g[نّ]َاسِ أَ[q:825[جْ]مَع[p[ِي]نَ","Ана ўшаларнинг жазоси, уларга Аллоҳнинг, фаришталарнинг ва барча одамларнинг лаънати бўлишидир.",61,3],["خَ[n[ـٰ]لِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ [h:448[ٱ]لْعَذَابُ وَلَا هُمْ يُ[f:826[نظ]َر[p[ُو]نَ","Унда абадий қолурлар. Улардан азоб енгиллатилмас ва уларга назар ҳам солинмас.",61,3],["إِلَّا [h:778[ٱ]لَّذِينَ تَابُو[s[اْ] م[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ وَأَصْلَحُو[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Магар шундоқ бўлгандан кейин тавба қилиб, яхши амалларни қилганлар бўлса, бас, Аллоҳ мағфират қилувчи ва раҳмлидир.",61,3],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] بَعْدَ إِيمَ[n[ـٰ]نِهِمْ ثُ[g[مّ]َ [h:2090[ٱ]زْدَادُو[s[اْ] كُفْ[u:2091[رًا ل]َّ[f:2092[ن ت]ُ[q:2093[قْ]بَلَ تَوْبَتُهُمْ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:2094[ٱ][l[ل]ضّ[m[َا]ٓلّ[p[ُو]نَ","Албатта, иймонларидан кейин куфр келтириб, сўнгра куфри зиёда бўлганларнинг тавбаси ҳеч-ҳеч қабул қилинмас. Ана ўшалар адашганлардир.",61,3],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَمَاتُو[s[اْ] وَهُمْ كُفَّا[f:2095[رٌ ف]َل[a:2082[َن ي]ُ[q:2083[قْ]بَلَ مِنْ أَحَدِه[w:2096[ِم م]ِّلْءُ [h:2097[ٱ]لْأَرْضِ ذَهَ[a:2098[بًا و]َلَوِ [h:2099[ٱ]فْتَدَىٰ بِه[o[ِۦٓ‌ۗ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ عَذَابٌ أَلِي[a:2100[مٌ و]َمَا لَه[w:1812[ُم م]ّ[a:1813[ِن ن]َّ[n[ـٰ]صِر[p[ِي]نَ","Албатта, куфр келтириб, кофир ҳолида ўлганларнинг бирортасидан, агар ер юзи тўла олтин фидо қилса ҳам, асло қабул қилинмас. Ана ўшаларга аламли азоб бор. Ва уларга ёрдамчилар йўқ.",61,3],["لَ[f:2101[ن ت]َنَالُو[s[اْ] [h:2102[ٱ]لْبِرَّ حَتَّىٰ تُ[f:1607[نف]ِقُو[s[اْ] مِ[g[مّ]َا تُحِبُّونَ‌ۚ وَمَا تُ[f:1607[نف]ِقُو[s[اْ] مِ[f:2103[ن ش][f:2104[َىْءٍ ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ بِه[n[ِۦ] عَل[p[ِي]مٌ","Ўзингиз суйган нарсадан нафақа қилмагунингизча, ҳаргиз яхшиликка эриша олмассиз. Нимани нафақа қилганингизни Аллоҳ билувчидир.",62,3],["۞ كُلُّ [h:2105[ٱ][l[ل]طَّعَامِ كَانَ حِل[u:2106[اًّ ل]ِّبَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ إِلَّا مَا حَرَّمَ إِسْر[o[َٲ]ٓءِيلُ عَلَىٰ نَفْسِه[n[ِۦ] مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أَ[f:2107[ن ت]ُنَزَّلَ [h:2108[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةُ‌ۗ قُلْ فَأْتُو[s[اْ] بِ[h:2109[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةِ فَ[h:2110[ٱ]تْلُوه[o[َآ] إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Таврот тушишидан олдин Исроил ўзига ҳаром қилгандан бошқа ҳамма таом Бани Исроилга ҳалол эди. Сен: «Агар ростгўйлардан бўлсангиз, Тавротни келтириб ўқинглар», деб айт!",62,4],["فَمَنِ [h:2111[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ [h:2035[ٱ]لْكَذِبَ م[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:1285[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Шундан кейин ҳам, кимки Аллоҳ ҳақида ёлғон тўқиса, бас, ана ўшалар золимлардир.",62,4],["قُلْ صَدَقَ [h:2112[ٱ]للَّهُ‌ۗ فَ[h:2113[ٱ]تَّبِعُو[s[اْ] مِلَّةَ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ حَنِي[a:698[فًا و]َمَا كَانَ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Аллоҳ рост айтди. Иброҳимнинг йўлдан тоймаган миллатига эргашинг. У мушриклардан бўлмаган эди.",62,4],["إِ[g[نّ]َ أَوَّلَ بَيْ[a:2114[تٍ و]ُضِعَ لِل[g[نّ]َاسِ لَلَّذِى بِبَكَّةَ مُبَارَ[a:2115[كًا و]َهُ[u:2116[دًى ل]ِّلْعَ[n[ـٰ]لَم[p[ِي]نَ","Одамларга муборак, оламларга ҳидоят қилиб қўйилган биринчи уй Баккадаги уйдир.",62,4],["فِيهِ ءَايَ[n[ـٰ][i:2117[تُۢ ب]َيِّنَ[n[ـٰ][a:2118[تٌ م]َّقَامُ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ‌ۖ وَمَ[f:2119[ن د]َخَلَهُ[n[ۥ] كَانَ ءَامِ[a:2120[نًا‌ۗ و]َلِلَّهِ عَلَى [h:729[ٱ][l[ل][g[نّ]َاسِ حِجُّ [h:2121[ٱ]لْبَيْتِ مَنِ [h:2122[ٱ]سْتَطَاعَ إِلَيْهِ سَبِيل[a:2123[اً‌ۚ و]َمَ[f:662[ن ك]َفَرَ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَنِىٌّ عَنِ [h:2124[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Унда очиқ аломатлар ва мақоми Иброҳим бор. Ким унга кирса, тинч бўладир. Одамлардан йўлини топганларига Аллоҳ учун байтни ҳаж қилмоқ бурчдир. Кимки куфр келтирса, Аллоҳ одамлардан беҳожатдир.",62,4],["قُلْ يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ لِمَ تَكْفُرُونَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ وَ[h:72[ٱ]للَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَل[p[ُو]نَ","Эй аҳли китоблар, нега Аллоҳнинг оятларига куфр келтирасизлар?! Ҳолбуки, Аллоҳ қилаётганларингизга гувоҳ-ку.",62,4],["قُلْ يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ لِمَ تَصُدُّونَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ مَنْ ءَامَنَ تَ[q:2125[بْ]غُونَهَا عِوَ[a:2126[جًا و]َأَ[f:98[نت]ُمْ شُهَد[o[َا]ٓءُ‌ۗ وَمَا [h:384[ٱ]للَّهُ بِغَ[n[ـٰ]فِلٍ عَ[g[مّ]َا تَعْمَل[p[ُو]نَ","Эй аҳли китоблар! Нега иймон келтирганларни Аллоҳнинг йўлидан тўсиб, қайтарасиз?! Ўзингиз шоҳид бўлиб туриб, унинг қинғир бўлишини хоҳлайсиз?! Аллоҳ қилаётган ишларингиздан ғофил эмасдир.",62,4],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[f:2127[ن ت]ُطِيعُو[s[اْ] فَرِي[a:2128[قًا م]ِّنَ [h:523[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ يَرُدُّوك[c:2129[ُم ب]َعْدَ إِيمَ[n[ـٰ]نِكُمْ كَ[n[ـٰ]فِر[p[ِي]نَ","Эй иймон келтирганлар! Агар китоб берилганлар тоифасига итоат қилсангиз, иймонингиздан кейин сизни кофирликка қайтаради.",62,4],["وَكَيْفَ تَكْفُرُونَ وَأَ[f:98[نت]ُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَ[n[ـٰ]تُ [h:1442[ٱ]للَّهِ وَفِيكُمْ رَسُولُهُ[n[ۥ]‌ۗ وَم[a:2130[َن ي]َعْتَص[c:2131[ِم ب]ِ[h:32[ٱ]للَّهِ فَقَ[q:563[دْ] هُدِىَ إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Аллоҳнинг оятлари сизга тиловат қилиниб турган бўлса-ю, Унинг Расули ичингизда бўлса-ю, қандай қилиб куфр келтирасиз?! Ким Аллоҳни маҳкам тутса, шубҳасиз, тўғри йўлга ҳидоят топган бўлади.",63,4],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:1643[ٱ]تَّقُو[s[اْ] [h:1644[ٱ]للَّهَ حَقَّ تُقَاتِه[n[ِۦ] وَلَا تَمُوتُ[g[نّ]َ إِلَّا وَأَ[f:98[نت][w:690[ُم م]ُّسْلِم[p[ُو]نَ","Эй иймон келтирганлар! Аллоҳга ҳақиқий тақво ила тақво қилинг. Ва фақат мусулмон ҳолингиздагина бу дунёдан ўтинг.",63,4],["وَ[h:9999[ٱ]عْتَصِمُو[s[اْ] بِحَ[q:2132[بْ]لِ [h:2133[ٱ]للَّهِ جَمِي[a:2134[عًا و]َلَا تَفَرَّقُو[s[اْ‌ۚ] وَ[h:335[ٱ]ذْكُرُو[s[اْ] نِعْمَتَ [h:1300[ٱ]للَّهِ عَلَيْكُمْ إِذْ كُ[f:100[نت]ُمْ أَعْد[o[َا]ٓ[f:2135[ءً ف]َأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْت[c:2136[ُم ب]ِنِعْمَتِه[o[ِۦٓ] إِخْو[n[َٲ][a:2137[نًا و]َكُ[f:151[نت]ُمْ عَلَىٰ شَفَا حُفْرَ[a:2138[ةٍ م]ِّنَ [h:869[ٱ][l[ل][g[نّ]َارِ فَأَ[f:2139[نق]َذَك[w:2140[ُم م]ِّنْهَا‌ۗ كَذ[n[َٲ]لِكَ يُبَيِّنُ [h:1002[ٱ]للَّهُ لَكُمْ ءَايَ[n[ـٰ]تِه[n[ِۦ] لَعَلَّكُمْ تَهْتَد[p[ُو]نَ","Барчангиз Аллоҳнинг ипини маҳкам тутинг ва бўлиниб кетманг. Ва Аллоҳнинг сизга берган неъматини эсланг: бир вақтлар душман эдингиз, бас, қалбларингизни улфат қилди. Унинг неъмати ила биродар бўлдингиз. Оловли жар ёқасида эдингиз, ундан сизни қутқарди. Шундай қилиб, Аллоҳ сизга Ўз оятларини баён қилади. Шоядки ҳидоят топсангиз.",63,4],["وَلْتَك[a:2141[ُن م]ِّ[f:344[نك]ُمْ أُ[g[مّ]َ[a:2142[ةٌ ي]َ[q:1240[دْ]عُونَ إِلَى [h:2143[ٱ]لْخَيْرِ وَيَأْمُرُونَ بِ[h:934[ٱ]لْمَعْرُوفِ وَيَنْهَوْنَ عَنِ [h:2144[ٱ]لْمُ[f:2145[نك]َرِ‌ۚ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Сизлардан яхшиликка чақирадиган, амри маъруф–наҳйи мункар қиладиган бир уммат бўлсин. Ана ўшалар, ўзлари нажот топгувчилардир.",63,4],["وَلَا تَكُونُو[s[اْ] كَ[h:2146[ٱ]لَّذِينَ تَفَرَّقُو[s[اْ] وَ[h:2147[ٱ]خْتَلَفُو[s[اْ] م[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَهُمُ [h:2148[ٱ]لْبَيِّنَ[n[ـٰ]تُ‌ۚ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ عَذَابٌ عَظ[p[ِي]مٌ","Ўзларига очиқ баёнотлар келганидан кейин бўлиниб ихтилофга тушганларга ўхшаш бўлмаганлар, ана ўшаларга улуғ азоб бордир.",63,4],["يَوْمَ تَ[q:2149[بْ]يَضُّ وُجُو[a:2150[هٌ و]َتَسْوَدُّ وُجُو[f:2151[هٌ‌ۚ ف]َأَ[g[مّ]َا [h:136[ٱ]لَّذِينَ [h:2152[ٱ]سْوَدَّتْ وُجُوهُهُمْ أَكَفَرْت[c:2153[ُم ب]َعْدَ إِيمَ[n[ـٰ]نِكُمْ فَذُوقُو[s[اْ] [h:2154[ٱ]لْعَذَابَ بِمَا كُ[f:100[نت]ُمْ تَكْفُر[p[ُو]نَ","Юзлар оқ ва юзлар қора бўладиган кунда юзлари қора бўлганларга: «Иймонингиздан кейин кофир бўлдингизми?! Куфр келтирган бўлганингиз учун азобни татиб кўринг», дейилур.",63,4],["وَأَ[g[مّ]َا [h:138[ٱ]لَّذِينَ [h:2155[ٱ][q:2156[بْ]يَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ [h:2157[ٱ]للَّهِ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Юзлари оқ бўлганлар эса, бас, Аллоҳнинг раҳматидадирлар. Улар унда абадий қолурлар.",63,4],["تِلْكَ ءَايَ[n[ـٰ]تُ [h:1442[ٱ]للَّهِ نَتْلُوهَا عَلَيْكَ بِ[h:370[ٱ]لْحَقِّ‌ۗ وَمَا [h:384[ٱ]للَّهُ يُرِيدُ ظُلْ[u:2158[مًا ل]ِّلْعَ[n[ـٰ]لَم[p[ِي]نَ","Булар Аллоҳнинг оятларидир. Уларни сенга ҳақ ила тиловат қилмоқдамиз. Аллоҳ одамларга зулмни хоҳламас.",63,4],["وَلِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۚ وَإِلَى [h:1148[ٱ]للَّهِ تُرْجَعُ [h:1149[ٱ]لْأُم[p[ُو]رُ","Осмонлару ердаги нарсалар Аллоҳникидир. Ишлар Аллоҳга қайтарилажак.",64,4],["كُ[f:100[نت]ُمْ خَيْرَ أُ[g[مّ]َةٍ أُخْرِجَتْ لِل[g[نّ]َاسِ تَأْمُرُونَ بِ[h:934[ٱ]لْمَعْرُوفِ وَتَنْهَوْنَ عَنِ [h:2144[ٱ]لْمُ[f:2145[نك]َرِ وَتُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ‌ۗ وَلَوْ ءَامَنَ أَهْلُ [h:2159[ٱ]لْكِتَ[n[ـٰ]بِ لَكَانَ خَيْ[u:2160[رًا ل]َّه[w:2161[ُم‌ۚ م]ِّنْهُمُ [h:2162[ٱ]لْمُؤْمِنُونَ وَأَكْثَرُهُمُ [h:2163[ٱ]لْفَ[n[ـٰ]سِق[p[ُو]نَ","Сиз одамлар учун чиқарилган энг яхши уммат бўлдингиз. Амри маъруф қиласиз, наҳйи мункар қиласиз ва Аллоҳга иймон келтирасиз. Агар аҳли китоблар иймон келтирганларида, ўзларига яхши бўлар эди. Улардан мўминлари бор. Кўплари фосиқдирлар.",64,4],["ل[a:2164[َن ي]َضُرُّوكُمْ إِلّ[o[َآ] أَ[a:2165[ذًى‌ۖ و]َإ[a:2166[ِن ي]ُقَ[n[ـٰ]تِلُوكُمْ يُوَلُّوكُمُ [h:2167[ٱ]لْأَ[q:2168[دْ]بَارَ ثُ[g[مّ]َ لَا يُ[f:237[نص]َر[p[ُو]نَ","Улар сизларга озор беришдан ўзга ҳеч қандай зарар етказа олмаслар. Агар сизларга қарши уруш қилсалар, ортга қараб қочарлар. Сўнгра уларга ёрдам берилмас.",64,4],["ضُرِبَتْ عَلَيْهِمُ [h:318[ٱ][l[ل]ذِّلَّةُ أَيْنَ مَا ثُقِف[o[ُوٓ][s[اْ] إِلَّا بِحَ[q:2169[بْ][a:2170[لٍ م]ِّنَ [h:321[ٱ]للَّهِ وَحَ[q:2171[بْ][a:2172[لٍ م]ِّنَ [h:721[ٱ][l[ل][g[نّ]َاسِ وَب[o[َا]ٓءُو بِغَضَ[a:320[بٍ م]ِّنَ [h:321[ٱ]للَّهِ وَضُرِبَتْ عَلَيْهِمُ [h:2173[ٱ]لْمَسْكَنَةُ‌ۚ ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ كَانُو[s[اْ] يَكْفُرُونَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ وَيَ[q:323[قْ]تُلُونَ [h:2174[ٱ]لْأَ[i:2175[نۢب]ِي[o[َا]ٓءَ بِغَيْرِ حَ[f:2176[قٍّ‌ۚ ذ][n[َٲ]لِكَ بِمَا عَصَو[s[اْ] وَّكَانُو[s[اْ] يَعْتَد[p[ُو]نَ","Аллоҳ ипи бўлмаса ёки одамлар ипи бўлмаса, уларга қаерда бўлсалар ҳам, хорлик битилди. Уларга Аллоҳнинг ғазаби лозим бўлди ва мискинлик битилди. Бундай бўлишлиги уларнинг Аллоҳнинг оятларига куфр келтиришлари ва Набийларни ноҳақдан ўлдиришлари сабабидандир. Бундай бўлишлиги осий бўлганлари ва ҳаддан ошганлари сабабидандир.",64,4],["۞ لَيْسُو[s[اْ] سَو[o[َا]ٓ[a:2177[ءً‌ۗ م]ِّنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ أُ[g[مّ]َ[f:2178[ةٌ ق][o[َا]ٓئِمَ[a:2179[ةٌ ي]َتْلُونَ ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ ءَان[o[َا]ٓءَ [h:2180[ٱ]لَّيْلِ وَهُمْ يَسْجُد[p[ُو]نَ","Улар баробар эмаслар. Аҳли китоблардан Аллоҳнинг оятларини сажда қилган ҳолларида кечасида тиловат қиладиган яхши тоифалари ҳам бор.",64,4],["يُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ وَيَأْمُرُونَ بِ[h:934[ٱ]لْمَعْرُوفِ وَيَنْهَوْنَ عَنِ [h:2144[ٱ]لْمُ[f:2145[نك]َرِ وَيُسَ[n[ـٰ]رِعُونَ فِى [h:2181[ٱ]لْخَيْر[n[َٲ]تِ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مِنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Улар Аллоҳга, охират кунига иймон келтирарлар, амри маъруф ва наҳйи мункар қиларлар ва яхшиликларга шошиларлар. Ана ўшалар аҳли солиҳлардандир.",64,4],["وَمَا يَفْعَلُو[s[اْ] مِنْ خَيْ[f:2182[رٍ ف]َل[a:2183[َن ي]ُكْفَرُوهُ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِي[i:2184[مُۢ ب]ِ[h:2185[ٱ]لْمُتَّق[p[ِي]نَ","Яхшилик қилсалар, ҳаргиз инкор этилмаслар. Аллоҳ тақводорларни яхши билувчи зотдир.",64,4],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَ[f:1752[ن ت]ُغْنِىَ عَنْهُمْ أَمْو[n[َٲ]لُهُمْ وَل[o[َآ] أَوْلَ[n[ـٰ]دُه[w:1753[ُم م]ِّنَ [h:321[ٱ]للَّهِ شَيْـ[a:1754[ـًٔا‌ۖ و]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ‌ۚ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Албатта, куфр келтирганлардан моллари ҳам, болалари ҳам ҳаргиз Аллоҳ азобидан ҳеч нарсани қайтара олмас. Ана ўшалар дўзах эгаларидир. Улар унда абадийдирлар.",65,4],["مَثَلُ مَا يُ[f:16[نف]ِقُونَ فِى هَ[n[ـٰ]ذِهِ [h:2186[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا كَمَثَلِ رِي[f:2187[حٍ ف]ِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْ[f:2188[مٍ ظ]َلَم[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ فَأَهْلَكَتْهُ‌ۚ وَمَا ظَلَمَهُمُ [h:2189[ٱ]للَّهُ وَلَ[n[ـٰ]كِنْ أَ[f:38[نف]ُسَهُمْ يَظْلِم[p[ُو]نَ","Уларнинг бу дунё ҳаётида қиладиган нафақалари мисоли ўзига зулм қилган бир қавмнинг экинини уриб ҳалок қилган совуқ шамолга ўхшайди. Аллоҳ уларга зулм қилмади. Лекин улар ўзларига зулм қилдилар.",65,4],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَتَّخِذُو[s[اْ] بِطَانَ[a:2190[ةً م]ِّ[f:2191[ن د]ُونِكُمْ لَا يَأْلُونَكُمْ خَبَال[a:2192[اً و]َدُّو[s[اْ] مَا عَنِتُّمْ قَ[q:298[دْ] بَدَتِ [h:2193[ٱ]لْبَغْض[o[َا]ٓءُ مِنْ أَفْو[n[َٲ]هِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ‌ۚ قَ[q:298[دْ] بَيَّ[g[نّ]َا لَكُمُ [h:1221[ٱ]لْأَيَ[n[ـٰ]تِ‌ۖ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْقِل[p[ُو]نَ","Эй иймон келтирганлар, ўзингиздан бошқадан сирдош тутманг. Улар сизга ёмонлик қилишини қўймаслар. Машаққатда қолишингизни хоҳларлар. Душманликлари оғизларидаги дан билиниб турибди. Дилларида махфий тургани яна ҳам каттароқ. Агар ақл юритадиган бўлсангиз, биз сизларга оят-белгиларни баён қилиб бўлдик.",65,4],["هَ[o[ـٰٓ]أَ[f:1998[نت]ُمْ أُ[s[وْ]ل[o[َا]ٓءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِ[h:2042[ٱ]لْكِتَ[n[ـٰ]بِ كُلِّه[n[ِۦ] وَإِذَا لَقُوكُمْ قَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا وَإِذَا خَلَوْ[s[اْ] عَضُّو[s[اْ] عَلَيْكُمُ [h:2194[ٱ]لْأَنَامِلَ مِنَ [h:2195[ٱ]لْغَيْظِ‌ۚ قُلْ مُوتُو[s[اْ] بِغَيْظِكُمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","Ҳой сизлар! Уларни яхши кўрасизлар-у, улар сизни яхши кўрмайдилар. Сизлар китобнинг ҳаммасига иймон келтирасизлар-у, улар сизларни кўрганда, иймон келтирдик, дерлар, аммо ҳоли қолганларида, сизларга бўлган қаттиқ аччиқларидан бармоқ тишларлар. Сен: «Аччиқларинг билан ўлиб кетинглар», деб айт. Албатта, Аллоҳ дилларни эгаллаган нарсаларни билувчидир».",65,4],["إِ[f:2198[ن ت]َمْسَسْكُمْ حَسَنَ[f:2199[ةٌ ت]َسُؤْهُمْ وَإِ[f:2200[ن ت]ُصِ[q:2201[بْ]كُمْ سَيِّئَ[a:2202[ةٌ ي]َفْرَحُو[s[اْ] بِهَا‌ۖ وَإِ[f:2203[ن ت]َصْبِرُو[s[اْ] وَتَتَّقُو[s[اْ] لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْــًٔا‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ بِمَا يَعْمَلُونَ مُح[p[ِي][q[ط]ٌ","Сизга яхшилик етса, уларга ёмон бўлар. Сизларга мусибат етса, улар хурсанд бўларлар. Агар сабр ва тақво қилсангиз, уларнинг макри сизга ҳеч зарар қилмас. Албатта, Аллоҳ қилаётган ишларини иҳота қилгувчидир.",65,4],["وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ [h:2204[ٱ]لْمُؤْمِنِينَ مَقَ[n[ـٰ]عِدَ لِلْقِتَالِ‌ۗ وَ[h:72[ٱ]للَّهُ سَمِيعٌ عَل[p[ِي]مٌ","Аҳлингдан эрталаб чиқиб, мўминларни уруш жойларига турғизганингни эсла! Аллоҳ эшитувчи ва билувчи зотдир.",65,4],["إِذْ هَ[g[مّ]َ[d:2205[ت] طّ[o[َا]ٓئِفَتَانِ مِ[f:344[نك]ُمْ أَ[f:2206[ن ت]َفْشَلَا وَ[h:72[ٱ]للَّهُ وَلِيُّهُمَا‌ۗ وَعَلَى [h:2207[ٱ]للَّهِ فَلْيَتَوَكَّلِ [h:2208[ٱ]لْمُؤْمِن[p[ُو]نَ","Сизлардан икки тоифа қўрқиб заифлашмоқчи бўлганини эсла! Аллоҳ уларнинг валийсидир. Мўминлар фақат Аллоҳнинг Ўзига таваккал қилсинлар.",66,4],["وَلَقَ[q:341[دْ] نَصَرَكُمُ [h:2209[ٱ]للَّهُ بِبَ[q:2210[دْ][a:2211[رٍ و]َأَ[f:98[نت]ُمْ أَذِلَّ[f:2212[ةٌ‌ۖ ف]َ[h:112[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ لَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Батаҳқиқ, Бадрда оз бўлсаларингизлар ҳам, Аллоҳ сизларга нусрат берди. Бас, Аллоҳга тақво қилинг, шоядки шукр қилсангиз.",66,4],["إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَل[a:2213[َن ي]َكْفِيَكُمْ أ[a:2214[َن ي]ُمِدَّكُمْ رَبُّك[c:2215[ُم ب]ِثَلَ[n[ـٰ]ثَةِ ءَالَ[n[ـٰ][a:2216[فٍ م]ِّنَ [h:2217[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ مُ[f:2218[نز]َل[p[ِي]نَ","Мўминларга: «Сизга Роббингиз туширилган уч минг фаришталар ила мадад бермоғи кифоя қилмайдими?!» деганингни эсла!",66,4],["بَلَ[o[ىٰٓ‌ۚ] إِ[f:2219[ن ت]َصْبِرُو[s[اْ] وَتَتَّقُو[s[اْ] وَيَأْتُوك[w:2220[ُم م]ِّ[f:2221[ن ف]َوْرِهِمْ هَ[n[ـٰ]ذَا يُمْدِ[q:2222[دْ]كُمْ رَبُّك[c:2223[ُم ب]ِخَمْسَةِ ءَالَ[n[ـٰ][a:2216[فٍ م]ِّنَ [h:2217[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ مُسَوِّم[p[ِي]نَ","«Ҳа! Агар сабр ва тақво қилсангиз, улар шу пайт келиб қолсалар ҳам, Роббингиз сизга белгили беш минг фаришта ила мадад беради».",66,4],["وَمَا جَعَلَهُ [h:2224[ٱ]للَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَ[q:2225[طْ]مَئِ[g[نّ]َ قُلُوبُك[c:2226[ُم ب]ِه[n[ِۦ]‌ۗ وَمَا [h:2227[ٱ][l[ل][g[نّ]َصْرُ إِلَّا مِنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ [h:2228[ٱ]لْعَزِيزِ [h:2229[ٱ]لْحَك[p[ِي]مِ","Аллоҳ буни фақат сизга суюнчилик ва қалбингиз таскин топиши учунгина қилди. Аслида, нусрат азиз ва ҳаким Аллоҳнинг ҳузуридандир.",66,4],["لِيَ[q:2230[قْ]طَعَ طَرَ[a:2231[فًا م]ِّنَ [h:523[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أَوْ يَكْبِتَهُمْ فَيَ[f:2232[نق]َلِبُو[s[اْ] خ[o[َا]ٓئِب[p[ِي]نَ","Куфр келтирганларнинг бир тарафини кесиш учун ёки хорлаш учун, токи ноумид бўлиб қайтсинлар.",66,4],["لَيْسَ لَكَ مِنَ [h:2233[ٱ]لْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِ[g[نّ]َهُمْ ظَ[n[ـٰ]لِم[p[ُو]نَ","Бу сенинг ишинг эмас! Ёки уларнинг тавбасини қабул қилади, ёки азоблайди. Бас, улар золимлардир.",66,4],["وَلِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۚ يَغْفِرُ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيُعَذِّبُ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Осмонлару ердаги нарсалар Аллоҳникидир. Хоҳлаган кишини мағфират қилади ва хоҳлаган кишини азоблайди. Аллоҳ гуноҳни мағфират қилувчи ва раҳмли зотдир.",66,4],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَأْكُلُو[s[اْ] [h:2234[ٱ][l[ل]رِّبَ[o[[s[و]ٲٓاْ] أَضْعَ[n[ـٰ][a:2235[فًا م]ُّضَ[n[ـٰ]عَفَ[a:2236[ةً‌ۖ و]َ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ لَعَلَّكُمْ تُفْلِح[p[ُو]نَ","Эй иймон келтирганлар! Рибони бир неча баробар қилиб еманг. Аллоҳга тақво қилинг, шоядки нажот топсангиз.",66,4],["وَ[h:9999[ٱ]تَّقُو[s[اْ] [h:2237[ٱ][l[ل][g[نّ]َارَ [h:114[ٱ]لَّت[o[ِىٓ] أُعِدَّتْ لِلْكَ[n[ـٰ]فِر[p[ِي]نَ","Ва кофирлар учун тайёрлаб қўйилган оловдан қўрқинг.",66,4],["وَأَطِيعُو[s[اْ] [h:2238[ٱ]للَّهَ وَ[h:1856[ٱ][l[ل]رَّسُولَ لَعَلَّكُمْ تُرْحَم[p[ُو]نَ","Аллоҳга ва Расулига итоат этинг. Шоядки раҳм қилинсангиз.",66,4],["۞ وَسَارِع[o[ُوٓ][s[اْ] إِلَىٰ مَغْفِرَ[a:2239[ةٍ م]ّ[u:243[ِن ر]َّبِّكُمْ وَجَ[g[نّ]َةٍ عَرْضُهَا [h:2240[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تُ وَ[h:2241[ٱ]لْأَرْضُ أُعِدَّتْ لِلْمُتَّق[p[ِي]نَ","Роббингиздан бўлган мағфиратга ва кенглиги осмонлару ерча бўлган, тақводорлар учун тайёрлаб қўйилган жаннатга шошилинг.",67,4],["ٱلَّذِينَ يُ[f:16[نف]ِقُونَ فِى [h:2242[ٱ][l[ل]سَّرّ[o[َا]ٓءِ وَ[h:920[ٱ][l[ل]ضَّرّ[o[َا]ٓءِ وَ[h:2243[ٱ]لْكَ[n[ـٰ]ظِمِينَ [h:2244[ٱ]لْغَيْظَ وَ[h:2245[ٱ]لْعَافِينَ عَنِ [h:2246[ٱ][l[ل][g[نّ]َاسِ‌ۗ وَ[h:72[ٱ]للَّهُ يُحِبُّ [h:1047[ٱ]لْمُحْسِن[p[ِي]نَ","Улар енгилликда ҳам, оғирликда ҳам нафақа қиладиганлар, ғазабини ютадиганлар ва одамларни авф қиладиганлардир. Аллоҳ яхшилик қилувчиларни ёқтиради.",67,4],["وَ[h:9999[ٱ]لَّذِينَ إِذَا فَعَلُو[s[اْ] فَ[n[ـٰ]حِشَةً أَوْ ظَلَم[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ ذَكَرُو[s[اْ] [h:2247[ٱ]للَّهَ فَ[h:2248[ٱ]سْتَغْفَرُو[s[اْ] لِذُنُوبِهِمْ وَم[a:2249[َن ي]َغْفِرُ [h:2250[ٱ][l[ل]ذُّنُوبَ إِلَّا [h:1742[ٱ]للَّهُ وَلَمْ يُصِرُّو[s[اْ] عَلَىٰ مَا فَعَلُو[s[اْ] وَهُمْ يَعْلَم[p[ُو]نَ","Ва улар фоҳиша иш ёки ўзларига зулм қилган чоғларида Аллоҳни эслаб, гуноҳларини мағфират қилишни сўрайдилар, гуноҳларини Аллоҳдан ўзга ким ҳам мағфират қиларди? Ва улар, билиб туриб, қилган гуноҳларида бардавом бўлмаслар.",67,4],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ جَز[o[َا]ٓؤُه[w:2251[ُم م]َّغْفِرَ[a:2252[ةٌ م]ّ[u:22[ِن ر]َّبِّهِمْ وَجَ[g[نّ]َ[n[ـٰ][f:2253[تٌ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۚ وَنِعْمَ أَ[q:2254[جْ]رُ [h:2255[ٱ]لْعَ[n[ـٰ]مِل[p[ِي]نَ","Ана ўшаларнинг мукофотлари Роббиларидан бўлган мағфират ва остидан анҳорлар оқиб турган жаннатлар бўлиб, улар унда абадий қолурлар. Амал қилувчиларнинг ажри қандай ҳам яхши!",67,4],["قَ[q:298[دْ] خَلَتْ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ سُنَ[f:2256[نٌ ف]َسِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَ[h:2257[ٱ][f:2257[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:2258[ٱ]لْمُكَذِّب[p[ِي]نَ","Сиздан олдин суннатлар қолган. Бас, ер юзида юриб ёлғонга чиқарувчиларнинг оқибати қандай бўлганига назар солинглар.",67,4],["هَ[n[ـٰ]ذَا بَيَا[u:2259[نٌ ل]ِّل[g[نّ]َاسِ وَهُ[a:2260[دًى و]َمَوْعِظَ[u:2261[ةٌ ل]ِّلْمُتَّق[p[ِي]نَ","Бу одамлар учун баён ва тақводорлар учун ҳидоят ва мавъизадир.",67,4],["وَلَا تَهِنُو[s[اْ] وَلَا تَحْزَنُو[s[اْ] وَأَ[f:2262[نت]ُمُ [h:2263[ٱ]لْأَعْلَوْنَ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Бўшашманглар! Хафа бўлманглар! Сизлар, агар мўмин бўлсаларингиз, устунсизлар.",67,4],["إ[a:2264[ِن ي]َمْسَسْكُمْ قَرْ[f:2265[حٌ ف]َقَ[q:563[دْ] مَسَّ [h:2266[ٱ]لْقَوْمَ قَرْ[a:2267[حٌ م]ِّثْلُهُ[n[ۥ]‌ۚ وَتِلْكَ [h:2268[ٱ]لْأَيَّامُ نُدَاوِلُهَا بَيْنَ [h:1165[ٱ][l[ل][g[نّ]َاسِ وَلِيَعْلَمَ [h:2269[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَيَتَّخِذَ مِ[f:344[نك]ُمْ شُهَد[o[َا]ٓءَ‌ۗ وَ[h:72[ٱ]للَّهُ لَا يُحِبُّ [h:1968[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Агар сизга жароҳат етган бўлса, у қавмга ҳам шунга ўхшаш жароҳат етган. Бундай кунларни одамлар орасида айлантириб турамиз. Токи Аллоҳ иймон келтирганларни билиши учун ва улардан шаҳидларни чиқариб олиши учун. Ва Аллоҳ золимларни севмайди.",67,4],["وَلِيُمَحِّصَ [h:2270[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَيَمْحَقَ [h:2271[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Токи Аллоҳ мўминларни поклаши ва кофирларни ҳалок қилиши учун.",68,4],["أَمْ حَسِ[q:1174[بْ]تُمْ أَ[f:1175[ن ت]َ[q:1176[دْ]خُلُو[s[اْ] [h:1177[ٱ]لْجَ[g[نّ]َةَ وَلَ[g[مّ]َا يَعْلَمِ [h:2272[ٱ]للَّهُ [h:2273[ٱ]لَّذِينَ جَ[n[ـٰ]هَدُو[s[اْ] مِ[f:344[نك]ُمْ وَيَعْلَمَ [h:2274[ٱ][l[ل]صَّ[n[ـٰ]بِر[p[ِي]نَ","Ёки Аллоҳ сизлардан жиҳод қилганларни билмасдан ва сабрлиларни билмасдан туриб, жаннатга кираверамиз, деб ҳисоблайсизми?!",68,4],["وَلَقَ[q:341[دْ] كُ[f:100[نت]ُمْ تَمَ[g[نّ]َوْنَ [h:2275[ٱ]لْمَوْتَ مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أَ[f:2276[ن ت]َلْقَوْهُ فَقَ[q:563[دْ] رَأَيْتُمُوهُ وَأَ[f:98[نت]ُمْ تَ[f:248[نظ]ُر[p[ُو]نَ","Дучор бўлмасингиздан олдин ўлимни орзу қилган эдингиз. Энди уни кўриб, назар солиб турибсиз.",68,4],["وَمَا مُحَ[g[مّ]َدٌ إِلَّا رَسُو[f:2277[لٌ ق]َ[q:298[دْ] خَلَتْ مِ[f:1097[ن ق]َ[q:1098[بْ]لِهِ [h:2278[ٱ][l[ل]رُّسُلُ‌ۚ أَفَإِ[s[يْ][a[ن م]َّاتَ أَوْ قُتِلَ [h:2279[ٱ][f:2280[نق]َلَ[q:2280[بْ]تُمْ عَلَ[o[ىٰٓ] أَعْقَ[n[ـٰ]بِكُمْ‌ۚ وَم[a:2281[َن ي]َ[f:2282[نق]َلِ[q:2282[بْ] عَلَىٰ عَقِبَيْهِ فَل[a:2283[َن ي]َضُرَّ [h:2284[ٱ]للَّهَ شَيْـ[a:2285[ـًٔا‌ۗ و]َسَيَ[q:2286[جْ]زِى [h:2287[ٱ]للَّهُ [h:2288[ٱ][l[ل]شَّ[n[ـٰ]كِر[p[ِي]نَ","Муҳаммад ҳам бир Пайғамбар, холос. Ундан аввал ҳам Пайғамбарлар ўтган. Агар у ўлса ёки қатл қилинса, орқангизга қайтасизми?! Кимки орқасига қайтса, Аллоҳга ҳеч зарар келтира олмас. Ва Аллоҳ шукр қилувчиларни мукофотлар.",68,4],["وَمَا كَانَ لِنَفْسٍ أَ[f:2289[ن ت]َمُوتَ إِلَّا بِإِذْنِ [h:509[ٱ]للَّهِ كِتَ[n[ـٰ][a:2290[بًا م]ُّؤَجَّل[a:2291[اً‌ۗ و]َم[a:2292[َن ي]ُرِ[q:2293[دْ] ثَوَابَ [h:2294[ٱ][l[ل]دُّنْيَا نُؤْتِه[n[ِۦ] مِنْهَا وَم[a:2292[َن ي]ُرِ[q:2293[دْ] ثَوَابَ [h:2295[ٱ]لْأَخِرَةِ نُؤْتِه[n[ِۦ] مِنْهَا‌ۚ وَسَنَ[q:2296[جْ]زِى [h:2297[ٱ][l[ل]شَّ[n[ـٰ]كِر[p[ِي]نَ","Ҳеч бир жон Аллоҳнинг изнисиз ўлмас. Бу ёзилган ажалдир. Ким бу дунёнинг савобини хоҳласа, унга ўшандан берамиз. Ким охиратнинг савобини хоҳласа, унга ўшандан берамиз. Ва шукр қилувчиларни мукофотлаймиз.",68,4],["وَكَأَيّ[a:2298[ِن م]ّ[a:2299[ِن ن]َّبِ[f:2300[ىٍّ ق]َ[n[ـٰ]تَلَ مَعَهُ[n[ۥ] رِبِّيُّونَ كَثِي[f:2301[رٌ ف]َمَا وَهَنُو[s[اْ] لِم[o[َآ] أَصَابَهُمْ فِى سَبِيلِ [h:788[ٱ]للَّهِ وَمَا ضَعُفُو[s[اْ] وَمَا [h:2302[ٱ]سْتَكَانُو[s[اْ‌ۗ] وَ[h:72[ٱ]للَّهُ يُحِبُّ [h:2303[ٱ][l[ل]صَّ[n[ـٰ]بِر[p[ِي]نَ","Қанчадан қанча Пайғамбарлар билан бирга кўплаб роббонийлар жанг қилганлар. Улар Аллоҳ йўлида етган мусибатдан бўшашмаганлар, заифлашмаганлар ва бўйсунмаганлар. Аллоҳ сабрлиларни севади.",68,4],["وَمَا كَانَ قَوْلَهُمْ إِلّ[o[َآ] أَ[f:2304[ن ق]َالُو[s[اْ] رَبَّنَا [h:2305[ٱ]غْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا ف[o[ِىٓ] أَمْرِنَا وَثَبِّتْ أَ[q:1429[قْ]دَامَنَا وَ[h:1430[ٱ][f:1430[نص]ُرْنَا عَلَى [h:1431[ٱ]لْقَوْمِ [h:1432[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Улар: «Эй Роббимиз! Бизнинг гуноҳларимиз ва ишимиздаги исрофимизни Ўзинг кечиргин, собитқадам қилгин ва кофир қавмлар устидан бизга нусрат бергин», деган гапдан ўзга гапни айтмаганлар.",68,4],["فَـَٔـاتَ[n[ـٰ]هُمُ [h:2306[ٱ]للَّهُ ثَوَابَ [h:2294[ٱ][l[ل]دُّنْيَا وَحُسْنَ ثَوَابِ [h:2307[ٱ]لْأَخِرَةِ‌ۗ وَ[h:72[ٱ]للَّهُ يُحِبُّ [h:1047[ٱ]لْمُحْسِن[p[ِي]نَ","Бас, Аллоҳ уларга бу дунё савобини ва охиратнинг гўзал савобини берди. Аллоҳ гўзал амал қилувчиларни севади.",68,4],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[f:2127[ن ت]ُطِيعُو[s[اْ] [h:2308[ٱ]لَّذِينَ كَفَرُو[s[اْ] يَرُدُّوكُمْ عَلَ[o[ىٰٓ] أَعْقَ[n[ـٰ]بِكُمْ فَتَ[f:2309[نق]َلِبُو[s[اْ] خَ[n[ـٰ]سِر[p[ِي]نَ","Эй иймон келтирганлар! Агар куфр келтирганларга итоат қилсангиз, орқангизга қайтарурлар. Бас, зиён кўргувчиларга айланиб қоласиз.",69,4],["بَلِ [h:2310[ٱ]للَّهُ مَوْلَ[n[ـٰ]كُمْ‌ۖ وَهُوَ خَيْرُ [h:2311[ٱ][l[ل][g[نّ]َ[n[ـٰ]صِر[p[ِي]نَ","Йўқ! Аллоҳ хўжангиздир. Ва У ёрдам берувчиларнинг яхшисидир!",69,4],["سَنُلْقِى فِى قُلُوبِ [h:2312[ٱ]لَّذِينَ كَفَرُو[s[اْ] [h:2313[ٱ][l[ل]رُّعْبَ بِم[o[َآ] أَشْرَكُو[s[اْ] بِ[h:32[ٱ]للَّهِ مَا لَمْ يُنَزِّلْ بِه[n[ِۦ] سُلْطَ[n[ـٰ][a:2314[نًا‌ۖ و]َمَأْوَ[n[ٮٰ]هُمُ [h:2315[ٱ][l[ل][g[نّ]َارُ‌ۚ وَبِئْسَ مَثْوَى [h:2316[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Тезда куфр келтирганларнинг қалбига, Аллоҳга ҳужжатсиз нарсани ширк келтирганлари учун, қўрқувни соламиз. Уларнинг қароргоҳи дўзахдир. Золимларнинг жойи қандай ҳам ёмон!",69,4],["وَلَقَ[q:341[دْ] صَدَقَكُمُ [h:2317[ٱ]للَّهُ وَعْدَهُ[o[ۥٓ] إِذْ تَحُسُّونَه[c:2318[ُم ب]ِإِذْنِه[n[ِۦ]‌ۖ حَتَّ[o[ىٰٓ] إِذَا فَشِلْتُمْ وَتَنَ[n[ـٰ]زَعْتُمْ فِى [h:2319[ٱ]لْأَمْرِ وَعَصَيْت[w:2320[ُم م]ّ[i:146[ِنۢ ب]َعْدِ م[o[َآ] أَرَ[n[ٮٰ]ك[w:2321[ُم م]َّا تُحِبُّونَ‌ۚ مِ[f:344[نك][w:2322[ُم م]ّ[a:2323[َن ي]ُرِيدُ [h:2324[ٱ][l[ل]دُّنْيَا وَمِ[f:2325[نك][w:2326[ُم م]ّ[a:2323[َن ي]ُرِيدُ [h:2327[ٱ]لْأَخِرَةَ‌ۚ ثُ[g[مّ]َ صَرَفَكُمْ عَنْهُمْ لِيَ[q:2328[بْ]تَلِيَكُمْ‌ۖ وَلَقَ[q:341[دْ] عَفَا عَ[f:255[نك]ُمْ‌ۗ وَ[h:72[ٱ]للَّهُ ذُو فَضْلٍ عَلَى [h:2329[ٱ]لْمُؤْمِن[p[ِي]نَ","Батаҳқиқ, Аллоҳ ваъдаси устидан чиқди. Сиз Унинг изни билан уларни қира бошладингиз. Токи заифлашиб, амр ҳақида ихтилоф қилиб ва сиз суйган нарсани кўрсатганидан сўнг исён қилгунингизча. Орангизда дунёни хоҳлайдиган кимсалар бор ва орангизда охиратни хоҳлайдиган кимсалар бор. Сўнгра сизларни имтиҳон қилиш учун улардан бурди. Батаҳқиқ, сизни афв этди. Аллоҳ мўминларга фазл эгаси бўлган зотдир.",69,4],["۞ إِذْ تُصْعِدُونَ وَلَا تَلْوُ[n[ۥ]نَ عَلَ[o[ىٰٓ] أَحَ[a:2330[دٍ و]َ[h:2331[ٱ][l[ل]رَّسُولُ يَ[q:2332[دْ]عُوكُمْ ف[o[ِىٓ] أُخْرَ[n[ٮٰ]كُمْ فَأَثَ[n[ـٰ]بَكُمْ غَ[g[مّ][i:2333[َۢا ب]ِغَ[u:2334[[g[مّ]ٍ ل]ِّكَيْلَا تَحْزَنُو[s[اْ] عَلَىٰ مَا فَاتَكُمْ وَلَا م[o[َآ] أَصَ[n[ـٰ]بَكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ خَبِي[i:2335[رُۢ ب]ِمَا تَعْمَل[p[ُو]نَ","Пайғамбар ортингиздан чақириб турса ҳам, ҳеч кимга қарамай тирқираб қочганингизни эсланг. Ўтган нарсага ва етган мусибатга хафа бўлмаслигингиз учун сизга ғам устига ғам берди. Аллоҳ қилаётган амалларингиздан хабардор зотдир.",69,4],["ثُ[g[مّ]َ أَ[f:471[نز]َلَ عَلَيْك[w:548[ُم م]ّ[i:146[ِنۢ ب]َعْدِ [h:2336[ٱ]لْغَ[g[مّ]ِ أَمَنَ[a:2337[ةً ن]ُّعَا[a:2338[سًا ي]َغْشَىٰ ط[o[َا]ٓئِفَ[a:2339[ةً م]ِّ[f:344[نك]ُمْ‌ۖ وَط[o[َا]ٓئِفَ[f:2340[ةٌ ق]َ[q:298[دْ] أَهَ[g[مّ]َتْهُمْ أَ[f:2341[نف]ُسُهُمْ يَظُ[g[نّ]ُونَ بِ[h:32[ٱ]للَّهِ غَيْرَ [h:2342[ٱ]لْحَقِّ ظَ[g[نّ]َ [h:2343[ٱ]لْجَ[n[ـٰ]هِلِيَّةِ‌ۖ يَقُولُونَ هَل لَّنَا مِنَ [h:2233[ٱ]لْأَمْرِ مِ[f:2103[ن ش][f:2344[َىْءٍ‌ۗ ق]ُلْ إِ[g[نّ]َ [h:2345[ٱ]لْأَمْرَ كُلَّهُ[n[ۥ] لِلَّهِ‌ۗ يُخْفُونَ ف[o[ِىٓ] أَ[f:568[نف]ُسِه[w:2346[ِم م]َّا لَا يُ[q:2347[بْ]دُونَ لَكَ‌ۖ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ [h:2233[ٱ]لْأَمْرِ ش[a:2348[َىْءٌ م]َّا قُتِلْنَا هَ[n[ـٰ]هُنَا‌ۗ قُل لَّوْ كُ[f:100[نت]ُمْ فِى بُيُوتِكُمْ لَبَرَزَ [h:2349[ٱ]لَّذِينَ كُتِبَ عَلَيْهِمُ [h:2350[ٱ]لْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ‌ۖ وَلِيَ[q:2351[بْ]تَلِىَ [h:2352[ٱ]للَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","Сўнгра, ғамдан кейин, сиздан бир тоифангизни қамраб олган мудроқни омонлик қилиб туширди. Бошқа тоифа эса, ўзи билан овора бўлиб, Аллоҳ ҳақида ноҳақ, жоҳилият гумонини қилиб: «Бизнинг қўлимизда нима иш бор эди», дейишди. Сен: «Ишнинг барчаси Аллоҳдандир», деб айт! Сенга ошкор қилмаган нарсаларини ичларида махфий тутарлар. Улар: «Агар қўлимизда бир иш бўлганида, бу ерда қатл қилинмас эдик, дерлар. Сен: «Агар уйларингизда бўлсангиз ҳам, қатл бўлиш тақдирида ёзилганлар ўз ўлим жойларига чиқар эдилар. Бу, Аллоҳ кўксингиздаги нарсани синаши ва қалбингиздагини яхшилаб поклаши учундир. Аллоҳ кўкракдаги нарсани ҳам билувчи зотдир», деб айт.",70,4],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ تَوَلَّوْ[s[اْ] مِ[f:344[نك]ُمْ يَوْمَ [h:2353[ٱ][l[ل]ْتَقَى [h:2354[ٱ]لْجَمْعَانِ إِ[g[نّ]َمَا [h:2355[ٱ]سْتَزَلَّهُمُ [h:2356[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ بِبَعْضِ مَا كَسَبُو[s[اْ‌ۖ] وَلَقَ[q:341[دْ] عَفَا [h:2357[ٱ]للَّهُ عَنْهُمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُورٌ حَل[p[ِي]مٌ","Икки тўп тўқнашган куни сизлардан юз ўгириб қочганларни баъзи қилган ишлари туфайли шайтон йўлдан урди, холос. Батаҳқиқ, Аллоҳ уларни афв қилди. Албатта, Аллоҳ мағфиратли ва раҳмли зотдир.",70,4],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَكُونُو[s[اْ] كَ[h:2146[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَقَالُو[s[اْ] لِإِخْو[n[َٲ]نِهِمْ إِذَا ضَرَبُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ أَوْ كَانُو[s[اْ] غُز[u:2358[ًّى ل]َّوْ كَانُو[s[اْ] عِ[f:2359[ند]َنَا مَا مَاتُو[s[اْ] وَمَا قُتِلُو[s[اْ] لِيَ[q:2360[جْ]عَلَ [h:2361[ٱ]للَّهُ ذ[n[َٲ]لِكَ حَسْرَ[f:2362[ةً ف]ِى قُلُوبِهِمْ‌ۗ وَ[h:72[ٱ]للَّهُ يُحْى[n[ِۦ] وَيُمِيتُ‌ۗ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","Эй иймон келтирганлар! Куфр келтирганларга ва ер юзида юрган ва ғозий бўлган биродарлари ҳақида, агар бизнинг ҳузуримизда бўлганларида ўлмас эдилар ва қатл қилинмас эдилар, дейдиганларга ўхшаманг. Буни Аллоҳ қалбларида ҳасрат қилиши учун айтадилар. Аллоҳ тирилтиради ва ўлдиради, Аллоҳ қилган амалларингизни кўрувчи зотдир.",70,4],["وَلَئِ[f:2363[ن ق]ُتِلْتُمْ فِى سَبِيلِ [h:788[ٱ]للَّهِ أَوْ مُتُّمْ لَمَغْفِرَ[a:2364[ةٌ م]ِّنَ [h:321[ٱ]للَّهِ وَرَحْمَةٌ خَيْ[a:2365[رٌ م]ِّ[g[مّ]َا يَ[q:2366[جْ]مَع[p[ُو]نَ","Гарчи Аллоҳ йўлида қатл қилинсангиз ҳам ёки ўлсангиз ҳам, Аллоҳдан бўладиган мағфират ва раҳмат улар жамлайдиган нарсадан яхшидир.",70,4],["وَلَئ[a:2367[ِن م]ُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى [h:2368[ٱ]للَّهِ تُحْشَر[p[ُو]نَ","Гарчи ўлсангиз ҳам ёки қатл қилинсангиз ҳам, албатта, Аллоҳ ҳузурида йиғилурсиз.",71,4],["فَبِمَا رَحْمَ[a:2369[ةٍ م]ِّنَ [h:321[ٱ]للَّهِ لِ[f:2370[نت]َ لَهُمْ‌ۖ وَلَوْ كُ[f:735[نت]َ فَظًّا غَلِيظَ [h:2371[ٱ]لْقَلْبِ لَ[h:2372[ٱ][f:2372[نف]َضُّو[s[اْ] مِنْ حَوْلِكَ‌ۖ فَ[h:2373[ٱ]عْفُ عَنْهُمْ وَ[h:2374[ٱ]سْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى [h:2319[ٱ]لْأَمْرِ‌ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى [h:412[ٱ]للَّهِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُحِبُّ [h:2375[ٱ]لْمُتَوَكِّل[p[ِي]نَ","Аллоҳнинг раҳмати ила уларга мулойим бўлдинг. Агар қўпол, қалби қаттиқ бўлганингда, атрофингдан тарқаб кетар эдилар. Бас, уларни афв эт. Уларга истиғфор айт ва улар билан ишларда машварат қил. Азму қарор қилганингдан сўнг Аллоҳга таваккал қил. Албатта, Аллоҳ таваккал қилувчиларни севадир.",71,4],["إ[a:2376[ِن ي]َ[f:2377[نص]ُرْكُمُ [h:2378[ٱ]للَّهُ فَلَا غَالِبَ لَكُمْ‌ۖ وَإ[a:2379[ِن ي]َخْذُلْكُمْ فَمَ[f:2380[ن ذ]َا [h:1376[ٱ]لَّذِى يَ[f:2381[نص]ُرُك[w:2382[ُم م]ّ[i:254[ِنۢ ب]َعْدِه[n[ِۦ]‌ۗ وَعَلَى [h:2207[ٱ]للَّهِ فَلْيَتَوَكَّلِ [h:2208[ٱ]لْمُؤْمِن[p[ُو]نَ","Агар сизга Аллоҳ нусрат берса, сиздан ғолиб келувчи йўқ. Агар сизни ташлаб қўйса, Ундан ўзга ким ҳам ёрдам берар эди. Мўминлар фақат Аллоҳгагина таваккал қилсинлар.",71,4],["وَمَا كَانَ لِنَبِىٍّ أ[a:2383[َن ي]َغُلَّ‌ۚ وَم[a:2384[َن ي]َغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۚ ثُ[g[مّ]َ تُوَفَّىٰ كُلُّ نَفْ[a:1654[سٍ م]َّا كَسَبَتْ وَهُمْ لَا يُظْلَم[p[ُو]نَ","Пайғамбарга хиёнат ҳеч тўғри келмас. Кимки хиёнат қилса, қиёмат куни хиёнат қилиб олган нарсаси билан келади. Сўнгра ҳар бир жон касбига яраша тўлиқ олади. Уларга зулм қилинмас.",71,4],["أَفَمَنِ [h:2385[ٱ]تَّبَعَ رِضْو[n[َٲ]نَ [h:2386[ٱ]للَّهِ كَم[i:2387[َنۢ ب][o[َا]ٓءَ بِسَخَ[a:2388[طٍ م]ِّنَ [h:321[ٱ]للَّهِ وَمَأْوَ[n[ٮٰ]هُ جَهَ[g[نّ]َمُ‌ۚ وَبِئْسَ [h:665[ٱ]لْمَص[p[ِي]رُ","Аллоҳнинг розилигини излаган одам, Аллоҳнинг ғазабига дучор бўлган ва борар жойи жаҳаннам бўлган одамга ўхшармиди?! Ва у қандай ҳам ёмон жой.",71,4],["هُمْ دَرَجَ[n[ـٰ]تٌ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ بَصِي[i:505[رُۢ ب]ِمَا يَعْمَل[p[ُو]نَ","Уларнинг Аллоҳнинг ҳузуридаги даражалари турлича. Аллоҳ қилаётган амалларини кўриб турувчи зотдир.",71,4],["لَقَ[q:2389[دْ] مَ[g[نّ]َ [h:2390[ٱ]للَّهُ عَلَى [h:2329[ٱ]لْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُول[a:2391[اً م]ِّنْ أَ[f:568[نف]ُسِهِمْ يَتْلُو[s[اْ] عَلَيْهِمْ ءَايَ[n[ـٰ]تِه[n[ِۦ] وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ [h:678[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:679[ٱ]لْحِكْمَةَ وَإِ[f:2392[ن ك]َانُو[s[اْ] مِ[f:128[ن ق]َ[q:129[بْ]لُ لَفِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Батаҳқиқ, Аллоҳ мўминларга ўзларидан Пайғамбар юбориб, неъмат берди. У аларга Аллоҳнинг оятларини тиловат қилиб берадир, уларни поклайдир, китоб ва ҳикматни ўргатадир. Гарчи олдин очиқ-ойдин адашувда бўлсалар ҳам.",71,4],["أَوَلَ[g[مّ][o[َآ] أَصَ[n[ـٰ]بَتْك[w:2394[ُم م]ُّصِيبَ[f:2395[ةٌ ق]َ[q:298[دْ] أَصَ[q:2396[بْ]ت[w:2397[ُم م]ِّثْلَيْهَا قُلْتُمْ أَ[g[نّ]َىٰ هَ[n[ـٰ]ذَا‌ۖ قُلْ هُوَ مِنْ عِ[f:398[ند]ِ أَ[f:1329[نف]ُسِكُمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Сен: «Сизга мусибат етган пайтда, ҳолбуки ўзингиз ҳамикки бараварини етказган эдингиз, бу қаердан, дейсизми?! Бу ўзингизнинг ҳузурингиздан!» деб айт. Албатта, Аллоҳ ҳамма нарсага қодирдир.",71,4],["وَم[o[َآ] أَصَ[n[ـٰ]بَكُمْ يَوْمَ [h:2353[ٱ][l[ل]ْتَقَى [h:2354[ٱ]لْجَمْعَانِ فَبِإِذْنِ [h:2398[ٱ]للَّهِ وَلِيَعْلَمَ [h:2399[ٱ]لْمُؤْمِن[p[ِي]نَ","Икки жамоа тўқнашган куни сизга мусибат Аллоҳнинг изни билан ва мўминларни билиш учун.",72,4],["وَلِيَعْلَمَ [h:2400[ٱ]لَّذِينَ نَافَقُو[s[اْ‌ۚ] وَقِيلَ لَهُمْ تَعَالَوْ[s[اْ] قَ[n[ـٰ]تِلُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ أَوِ [h:2401[ٱ][q:2402[دْ]فَعُو[s[اْ‌ۖ] قَالُو[s[اْ] لَوْ نَعْلَمُ قِتَال[u:2403[اً ل]َّ[h:2404[ٱ]تَّبَعْنَ[n[ـٰ]كُمْ‌ۗ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَ[q:1355[قْ]رَبُ مِنْهُمْ لِلْإِيمَ[n[ـٰ]نِ‌ۚ يَقُولُونَ بِأَفْو[n[َٲ]هِه[w:2405[ِم م]َّا لَيْسَ فِى قُلُوبِهِمْ‌ۗ وَ[h:72[ٱ]للَّهُ أَعْلَمُ بِمَا يَكْتُم[p[ُو]نَ","Ва мунофиқлик қилаётганларни билиш учун етди. Ва уларга: «Келинглар, Аллоҳнинг йўлида уруш қилинглар ёки мудофаа қилинглар», дейилди. Улар «Агар жанг бўлишини аниқ билсак, сизга эргашардик», дедилар. Улар ўша кунда иймондан кўра куфрга яқинроқ эдилар. Тиллари билан дилларида йўқ нарсани айтадилар. Аллоҳ беркитаётган нарсаларини яхши билувчи зотдир.",72,4],["ٱلَّذِينَ قَالُو[s[اْ] لِإِخْو[n[َٲ]نِهِمْ وَقَعَدُو[s[اْ] لَوْ أَطَاعُونَا مَا قُتِلُو[s[اْ‌ۗ] قُلْ فَ[h:2406[ٱ][q:2406[دْ]رَءُو[s[اْ] عَنْ أَ[f:2407[نف]ُسِكُمُ [h:2408[ٱ]لْمَوْتَ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Улар ўз биродарларига ва ўтирганларга: «Агар бизга итоат қилганларида қатл қилинмас эдилар», дейишди. Сен: «Агар гапингиз рост бўлса, ўзингиздан ўлимни қайтариб кўринг-чи», деб айт.",72,4],["وَلَا تَحْسَبَ[g[نّ]َ [h:2409[ٱ]لَّذِينَ قُتِلُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ أَمْو[n[َٲ]ت[i:2410[َۢا‌ۚ ب]َلْ أَحْي[o[َا]ٓءٌ عِ[f:264[ند]َ رَبِّهِمْ يُرْزَق[p[ُو]نَ","Аллоҳнинг йўлида қатл бўлганларни ўликлар деб ҳисобламанглар. Балки улар тирик, Роббилари ҳузурида ризқланмоқдалар.",72,4],["فَرِحِينَ بِم[o[َآ] ءَاتَ[n[ـٰ]هُمُ [h:2411[ٱ]للَّهُ مِ[f:475[ن ف]َضْلِه[n[ِۦ] وَيَسْتَ[q:2412[بْ]شِرُونَ بِ[h:2413[ٱ]لَّذِينَ لَمْ يَلْحَقُو[s[اْ] بِه[w:2414[ِم م]ِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Улар Аллоҳ Ўз фазлидан берган нарсалардан хурсандлар ва ҳали ортларидан ўзларига қўшилмаган биродарларига, уларга хавф йўқлигини ҳамда хафа ҳам бўлмасликларининг хушхабарини бермоқдалар.",72,4],["۞ يَسْتَ[q:2415[بْ]شِرُونَ بِنِعْمَ[a:2416[ةٍ م]ِّنَ [h:321[ٱ]للَّهِ وَفَضْ[a:2417[لٍ و]َأَ[g[نّ]َ [h:859[ٱ]للَّهَ لَا يُضِيعُ أَ[q:2418[جْ]رَ [h:2419[ٱ]لْمُؤْمِن[p[ِي]نَ","Улар Аллоҳдан бўлган неъмат ва фазлнинг ҳамда, албатта, Аллоҳ мўминларнинг ажрини зое қилмаслигининг хушхабарини бермоқдалар.",72,4],["ٱلَّذِينَ [h:2420[ٱ]سْتَجَابُو[s[اْ] لِلَّهِ وَ[h:2421[ٱ][l[ل]رَّسُولِ م[i:146[ِنۢ ب]َعْدِ م[o[َآ] أَصَابَهُمُ [h:2422[ٱ]لْقَرْحُ‌ۚ لِلَّذِينَ أَحْسَنُو[s[اْ] مِنْهُمْ وَ[h:538[ٱ]تَّقَوْ[s[اْ] أَ[q:2423[جْ]رٌ عَظ[p[ِي]مٌ","Улар жароҳат етгандан кейин ҳам Аллоҳ ва Пайғамбар чақириғига жавоб берадиганлардир. Улардан яхшилик ва тақво қилганларига улуғ ажрлар бордир.",72,4],["ٱلَّذِينَ قَالَ لَهُمُ [h:2424[ٱ][l[ل][g[نّ]َاسُ إِ[g[نّ]َ [h:2425[ٱ][l[ل][g[نّ]َاسَ قَ[q:298[دْ] جَمَعُو[s[اْ] لَكُمْ فَ[h:2426[ٱ]خْشَوْهُمْ فَزَادَهُمْ إِيمَ[n[ـٰ][a:2427[نًا و]َقَالُو[s[اْ] حَسْبُنَا [h:2428[ٱ]للَّهُ وَنِعْمَ [h:2429[ٱ]لْوَك[p[ِي]لُ","Уларга кишилар: «Албатта, одамлар сизга қарши куч тўпладилар, улардан қўрқинглар», деганда, иймонлари зиёда бўлди ва: «Бизга Аллоҳнинг Ўзи етарли ва У қандай ҳам яхши вакил», дедилар.",72,4],["فَ[h:9999[ٱ][f:2430[نق]َلَبُو[s[اْ] بِنِعْمَ[a:2416[ةٍ م]ِّنَ [h:321[ٱ]للَّهِ وَفَضْ[u:2431[لٍ ل]َّمْ يَمْسَسْهُمْ س[o[ُو]ٓ[a:2432[ءٌ و]َ[h:2433[ٱ]تَّبَعُو[s[اْ] رِضْو[n[َٲ]نَ [h:2386[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ ذُو فَضْلٍ عَظ[p[ِي]مٍ","Бас, Аллоҳнинг неъмати ва фазли ила, уларга ёмонлик етмасдан қайтдилар ва Аллоҳнинг розилигига эришдилар. Аллоҳ улуғ фазл эгасидир.",73,4],["إِ[g[نّ]َمَا ذ[n[َٲ]لِكُمُ [h:2434[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ يُخَوِّفُ أَوْلِي[o[َا]ٓءَهُ[n[ۥ] فَلَا تَخَافُوهُمْ وَخَافُونِ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Албатта, бундай бўлишингиз шайтондандир, у ўз яқинларидан қўрқитади. Бас, агар мўмин бўлсангиз, улардан қўрқманглар, мендан қўрқинглар.",73,4],["وَلَا يَحْزُ[f:2435[نك]َ [h:2436[ٱ]لَّذِينَ يُسَ[n[ـٰ]رِعُونَ فِى [h:2437[ٱ]لْكُفْرِ‌ۚ إِ[g[نّ]َهُمْ ل[a:2438[َن ي]َضُرُّو[s[اْ] [h:2439[ٱ]للَّهَ شَيْـ[a:2440[ـًٔا‌ۗ ي]ُرِيدُ [h:976[ٱ]للَّهُ أَلَّا يَ[q:2441[جْ]عَلَ لَهُمْ حَظ[f:2442[ًّا ف]ِى [h:536[ٱ]لْأَخِرَةِ‌ۖ وَلَهُمْ عَذَابٌ عَظ[p[ِي]مٌ","Куфрга ошиқаётганлар сени хафа қилмасин. Албатта, улар ҳаргиз Аллоҳга бирор зарар етказа олмаслар. Аллоҳ уларга охиратда насиба қилмасликни хоҳлайдир. Уларга улкан азоб бордир.",73,4],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ [h:52[ٱ]شْتَرَوُ[s[اْ] [h:2443[ٱ]لْكُفْرَ بِ[h:562[ٱ]لْإِيمَ[n[ـٰ]نِ ل[a:2438[َن ي]َضُرُّو[s[اْ] [h:2439[ٱ]للَّهَ شَيْـ[a:2444[ـًٔا و]َلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Албатта, куфрни иймонга сотиб олганлар Аллоҳга ҳаргиз бирор зарар етказа олмаслар. Уларга аламли азоб бордир.",73,4],["وَلَا يَحْسَبَ[g[نّ]َ [h:2445[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أَ[g[نّ]َمَا نُمْلِى لَهُمْ خَيْ[u:2446[رٌ ل]ِّأَ[f:2447[نف]ُسِهِمْ‌ۚ إِ[g[نّ]َمَا نُمْلِى لَهُمْ لِيَزْدَاد[o[ُوٓ][s[اْ] إِثْ[a:2448[مًا‌ۚ و]َلَهُمْ عَذَا[a:478[بٌ م]ُّه[p[ِي]نٌ","Куфр келтирганлар уларни тек қўйганимизни ўзлари учун яхши деб ҳисобламасинлар. Биз уларни фақат гуноҳлари кўпайиши учунгина тек қўямиз. Уларга хорловчи азоб бордир.",73,4],["مَّا كَانَ [h:742[ٱ]للَّهُ لِيَذَرَ [h:2449[ٱ]لْمُؤْمِنِينَ عَلَىٰ م[o[َآ] أَ[f:428[نت]ُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ [h:2450[ٱ]لْخَبِيثَ مِنَ [h:2451[ٱ][l[ل]طَّيِّبِ‌ۗ وَمَا كَانَ [h:742[ٱ]للَّهُ لِيُ[q:2452[طْ]لِعَكُمْ عَلَى [h:2453[ٱ]لْغَيْبِ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ يَ[q:2454[جْ]تَبِى م[u:1711[ِن ر]ُّسُلِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ‌ۖ فَـَٔـامِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرُسُلِه[n[ِۦ]‌ۚ وَإِ[f:2455[ن ت]ُؤْمِنُو[s[اْ] وَتَتَّقُو[s[اْ] فَلَكُمْ أَ[q:2423[جْ]رٌ عَظ[p[ِي]مٌ","Аллоҳ мўминларни сиз турган ҳолда, покидан нопокини ажратмасдан қўйиб қўймас. Аллоҳ сизларни ғайбдан хабардор қилиб қўймас. Лекин Аллоҳ Ўз Пайғамбарларидан кимни хоҳласа, танлаб олади. Бас, Аллоҳга ва Унинг Пайғамбарларига иймон келтиринглар. Агар иймон келтирсангиз ва тақво қилсангиз, сизларга улуғ ажр бордир.",73,4],["وَلَا يَحْسَبَ[g[نّ]َ [h:2445[ٱ]لَّذِينَ يَ[q:2456[بْ]خَلُونَ بِم[o[َآ] ءَاتَ[n[ـٰ]هُمُ [h:2411[ٱ]للَّهُ مِ[f:475[ن ف]َضْلِه[n[ِۦ] هُوَ خَيْ[u:2160[رًا ل]َّه[c:2457[ُم‌ۖ ب]َلْ هُوَ شَ[u:2458[رٌّ ل]َّهُمْ‌ۖ سَيُطَوَّقُونَ مَا بَخِلُو[s[اْ] بِه[n[ِۦ] يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۗ وَلِلَّهِ مِير[n[َٲ]ثُ [h:2459[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۗ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ خَب[p[ِي]رٌ","Аллоҳ Ўз фазлидан берган нарсага бахиллик қилганлар буни ўзларига яхшилик деб ҳисобламасинлар. Аксинча, бу уларга ёмонликдир. Қиёмат куни бахиллик қилган нарсалари ила бўйинлари ўралур. Осмонлару ернинг мероси Аллоҳгадир. Ва Аллоҳ қилаётган амалларингиздан хабардордир.",73,4],["لَّقَ[q:2389[دْ] سَمِعَ [h:2460[ٱ]للَّهُ قَوْلَ [h:2461[ٱ]لَّذِينَ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ فَقِي[a:2462[رٌ و]َنَحْنُ أَغْنِي[o[َا]ٓءُ‌ۘ سَنَكْتُبُ مَا قَالُو[s[اْ] وَقَتْلَهُمُ [h:2463[ٱ]لْأَ[i:2175[نۢب]ِي[o[َا]ٓءَ بِغَيْرِ حَ[a:2464[قٍّ و]َنَقُولُ ذُوقُو[s[اْ] عَذَابَ [h:2465[ٱ]لْحَر[p[ِي][q[ق]ِ","Батаҳқиқ, Аллоҳ: «Албатта, Аллоҳ камбағал ва биз боймиз», деганларнинг гапини эшитди. Айтганларини ва Набийларни ноҳақ ўлдирганларни ёзиб қўямиз ва: «Куйдирувчи азобни татиб кўринг!» деймиз.",74,4],["ذ[n[َٲ]لِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ لَيْسَ بِظَلَّا[u:2466[مٍ ل]ِّلْعَب[p[ِي][q[د]ِ","Бундоқ бўлишлиги, сизнинг ўз қўлингиз ила қилганингиз туфайлидир. Албатта, Аллоҳ бандаларига зулм қилувчи эмас.",74,4],["ٱلَّذِينَ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَهِدَ إِلَيْن[o[َآ] أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَا[f:2467[نٍ ت]َأْكُلُهُ [h:2468[ٱ][l[ل][g[نّ]َارُ‌ۗ قُلْ قَ[q:298[دْ] ج[o[َا]ٓءَكُمْ رُسُ[a:2469[لٌ م]ِّ[f:2470[ن ق]َ[q:2471[بْ]لِى بِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ وَبِ[h:2472[ٱ]لَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","«Албатта, Аллоҳ биздан ўтда куядиган қурбонлик келтирмаган Пайғамбарга ишонмаслигимизга аҳд олган», дейдиганларга, сен: «Мендан олдин ҳам сизларга Пайғамбарлар очиқ-ойдин баёнотлар ва сиз айтган нарса билан келганлар. Агар ростгўй бўлсаларингиз, нимага уларни ўлдирдингиз?» деб айт.",74,4],["فَإِ[f:2473[ن ك]َذَّبُوكَ فَقَ[q:563[دْ] كُذِّبَ رُسُ[a:2469[لٌ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ ج[o[َا]ٓءُو بِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ وَ[h:2474[ٱ][l[ل]زُّبُرِ وَ[h:906[ٱ]لْكِتَ[n[ـٰ]بِ [h:2475[ٱ]لْمُن[p[ِي]رِ","Агар сени ёлғончи қилсалар, сендан олдин очиқ-ойдин баёнотлар, ҳикматли китоблар ва нурли китоблар билан келган Пайғамбарларни ҳам ёлғончи қилганлар.",74,4],["كُلُّ نَفْ[f:2476[سٍ ذ][o[َا]ٓئِقَةُ [h:2477[ٱ]لْمَوْتِ‌ۗ وَإِ[g[نّ]َمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۖ فَمَ[f:2478[ن ز]ُحْزِحَ عَنِ [h:2479[ٱ][l[ل][g[نّ]َارِ وَأُ[q:2480[دْ]خِلَ [h:2481[ٱ]لْجَ[g[نّ]َةَ فَقَ[q:563[دْ] فَازَ‌ۗ وَمَا [h:2482[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْي[o[َآ] إِلَّا مَتَ[n[ـٰ]عُ [h:2483[ٱ]لْغُر[p[ُو]رِ","Ҳар бир жон ўлимни тотгувчидир. Қиёмат куни ажрларингизни тўлиғича олурсиз. Ким дўзахдан узоқлаштирилса ва жаннатга киритилса, шубҳасиз, ютибди. Бу дунё ҳаёти ғурур матоҳидан ўзга нарса эмас.",74,4],["۞ لَتُ[q:2484[بْ]لَوُ[g[نّ]َ ف[o[ِىٓ] أَمْو[n[َٲ]لِكُمْ وَأَ[f:2485[نف]ُسِكُمْ وَلَتَسْمَعُ[g[نّ]َ مِنَ [h:523[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ وَمِنَ [h:501[ٱ]لَّذِينَ أَشْرَك[o[ُوٓ][s[اْ] أَ[f:2486[ذًى ك]َثِي[a:2487[رًا‌ۚ و]َإِ[f:2203[ن ت]َصْبِرُو[s[اْ] وَتَتَّقُو[s[اْ] فَإِ[g[نّ]َ ذ[n[َٲ]لِكَ مِنْ عَزْمِ [h:2488[ٱ]لْأُم[p[ُو]رِ","Албатта, молу жонда синовга учрайсиз. Албатта, сиздан олдин китоб берилганлардан ва ширк келтирганлардан кўплаб озор эшитасиз. Агар сабр қилсангиз ва тақво қилсангиз, албатта, бу салмоқли ишлардандир.",74,4],["وَإِذْ أَخَذَ [h:2057[ٱ]للَّهُ مِيثَ[n[ـٰ]قَ [h:2489[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ لَتُبَيِّنُ[g[نّ]َهُ[n[ۥ] لِل[g[نّ]َاسِ وَلَا تَكْتُمُونَهُ[n[ۥ] فَنَبَذُوهُ وَر[o[َا]ٓءَ ظُهُورِهِمْ وَ[h:2490[ٱ]شْتَرَوْ[s[اْ] بِه[n[ِۦ] ثَمَ[f:208[نًا ق]َلِيل[f:2491[اً‌ۖ ف]َبِئْسَ مَا يَشْتَر[p[ُو]نَ","Аллоҳ китоб берилганлардан, албатта, уни одамларга баён қиласиз ва беркитмайсиз, деб аҳд олганини эсла. Бас, уни ортларига қаратиб отдилар ва арзон нархга сотдилар. Сотиб олган нарсалари қандай ҳам ёмон!",75,4],["لَا تَحْسَبَ[g[نّ]َ [h:2409[ٱ]لَّذِينَ يَفْرَحُونَ بِم[o[َآ] أَتَو[s[اْ] وَّيُحِبُّونَ أ[a:2492[َن ي]ُحْمَدُو[s[اْ] بِمَا لَمْ يَفْعَلُو[s[اْ] فَلَا تَحْسَبَ[g[نّ]َه[c:2493[ُم ب]ِمَفَازَ[a:2494[ةٍ م]ِّنَ [h:503[ٱ]لْعَذَابِ‌ۖ وَلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Қилганларига хурсанд бўлиб, қилмаганларига мақталишни суядиганларни азобдан нажотда деб ҳисоблама. Уларга аламли азоб бор!",75,4],["وَلِلَّهِ مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۗ وَ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Осмонлару ернинг мулки Аллоҳникидир. Ва Аллоҳ ҳар бир нарсага қодирдир.",75,4],["إِ[g[نّ]َ فِى خَلْقِ [h:831[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَ[h:832[ٱ]خْتِلَ[n[ـٰ]فِ [h:833[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ لَأَيَ[n[ـٰ][u:2495[تٍ ل]ِّأُ[s[وْ]لِى [h:2496[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","Албатта, осмонлару ернинг яратилишида ва кеча-кундузнинг алмашинишида ақл эгалари учун белгилар бор.",75,4],["ٱلَّذِينَ يَذْكُرُونَ [h:2497[ٱ]للَّهَ قِيَ[n[ـٰ][a:2498[مًا و]َقُعُو[a:2499[دًا و]َعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ [h:831[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ رَبَّنَا مَا خَلَ[q:2500[قْ]تَ هَ[n[ـٰ]ذَا بَ[n[ـٰ]طِل[f:2501[اً س]ُ[q:168[بْ]حَ[n[ـٰ]نَكَ فَقِنَا عَذَابَ [h:1110[ٱ][l[ل][g[نّ][p[َا]رِ","Аллоҳни тик турган, ўтирган ва ёнбошлаган ҳолларида эслайдиган, осмонлару ернинг яратилишини тафаккур қиладиганлар: «Роббимиз, буни бекорга яратганинг йўқ, Ўзинг поксан, бизни ўт азобидан сақлагин.",75,4],["رَبَّن[o[َآ] إِ[g[نّ]َكَ مَ[f:2502[ن ت]ُ[q:2503[دْ]خِلِ [h:2504[ٱ][l[ل][g[نّ]َارَ فَقَ[q:563[دْ] أَخْزَيْتَهُ[n[ۥ]‌ۖ وَمَا لِلظَّ[n[ـٰ]لِمِينَ مِنْ أَ[f:1600[نص][p[َا]رٍ","Роббимиз, албатта, сен кимни дўзахга киритсанг, батаҳқиқ, уни шарманда қилибсан. Ва золимларга ёрдам берувчилар йўқ.",75,4],["رَّبَّن[o[َآ] إِ[g[نّ]َنَا سَمِعْنَا مُنَادِ[a:2505[يًا ي]ُنَادِى لِلْإِيمَ[n[ـٰ]نِ أَنْ ءَامِنُو[s[اْ] بِرَبِّكُمْ فَـَٔـامَ[g[نّ]َا‌ۚ رَبَّنَا فَ[h:1791[ٱ]غْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَ[g[نّ]َا سَيِّـَٔـاتِنَا وَتَوَفَّنَا مَعَ [h:2506[ٱ]لْأَ[q:2507[بْ]ر[p[َا]رِ","Роббимиз биз нидо қилувчининг, Роббингизга иймон келтиринг, деб нидо қилаётганини эшитдик ва иймон келтирдик. Роббимиз, бизнинг гуноҳларимизни кечиргин ва ёмонликларимизни ўчиргин ҳамда яхшилар билан бирга ўлдиргин.",75,4],["رَبَّنَا وَءَاتِنَا مَا وَعَ[d:2508[د]تَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۗ إِ[g[نّ]َكَ لَا تُخْلِفُ [h:2509[ٱ]لْمِيع[p[َا][q[د]َ","Роббимиз, бизга Пайғамбарларингга ваъда қилган нарсаларингни бергин ва бизни қиёмат куни шарманда қилмагин. Албатта, Сен ваъдага хилоф қилмайсан», дерлар.",75,4],["فَ[h:9999[ٱ]سْتَجَابَ لَهُمْ رَبُّهُمْ أَ[g[نّ]ِى ل[o[َآ] أُضِيعُ عَمَلَ عَ[n[ـٰ]مِ[a:2510[لٍ م]ِّ[f:344[نك][w:431[ُم م]ِّ[f:2511[ن ذ]َكَرٍ أَوْ أُ[f:1867[نث]َىٰ‌ۖ بَعْضُك[w:2512[ُم م]ّ[i:1862[ِنۢ ب]َعْ[f:2513[ضٍ‌ۖ ف]َ[h:2514[ٱ]لَّذِينَ هَاجَرُو[s[اْ] وَأُخْرِجُو[s[اْ] مِ[f:432[ن د]ِيَ[n[ـٰ]رِهِمْ وَأُوذُو[s[اْ] فِى سَبِيلِى وَقَ[n[ـٰ]تَلُو[s[اْ] وَقُتِلُو[s[اْ] لَأُكَفِّرَ[g[نّ]َ عَنْهُمْ سَيِّـَٔـاتِهِمْ وَلَأُ[q:2515[دْ]خِلَ[g[نّ]َهُمْ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ ثَوَا[a:2516[بًا م]ِّنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ عِ[f:719[ند]َهُ[n[ۥ] حُسْنُ [h:2517[ٱ][l[ل]ثَّو[p[َا][q[ب]ِ","Роббилари уларнинг истижобат қилиб: «Мен сизлардан эркагу аёл амал қилувчининг амалини зое қилмайман. Баъзингиз баъзингиздансиз. Ҳижрат қилганлар, диёрларидан чиқарилганлар, Менинг йўлимда азият чекканлар, жанг қилганлар ва қатл бўлганларнинг ёмонликларини ўчираман ҳамда уларни, албатта, остидан анҳорлар оқиб турган жаннатларга киритаман, бу Аллоҳнинг ҳузуридан савобдир. Ва Аллоҳ–ҳузурида гўзал савоб бор зотдир», деди.",76,4],["لَا يَغُرَّ[g[نّ]َكَ تَقَلُّبُ [h:2518[ٱ]لَّذِينَ كَفَرُو[s[اْ] فِى [h:2519[ٱ]لْبِلَ[p[ـٰ][q[د]ِ","Куфр келтирганларнинг юрт кезишлари сени алдаб қўймасин.",76,4],["مَتَ[n[ـٰ][f:2520[عٌ ق]َلِي[f:2521[لٌ ث]ُ[g[مّ]َ مَأْوَ[n[ٮٰ]هُمْ جَهَ[g[نّ]َمُ‌ۚ وَبِئْسَ [h:1757[ٱ]لْمِه[p[َا][q[د]ُ","Бу озгина матоҳдир. Сўнгра ўринлари жаҳаннамдир. У қандай ҳам ёмон ётоқ!",76,4],["لَ[n[ـٰ]كِنِ [h:2522[ٱ]لَّذِينَ [h:2523[ٱ]تَّقَوْ[s[اْ] رَبَّهُمْ لَهُمْ جَ[g[نّ]َ[n[ـٰ][f:1786[تٌ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا نُزُل[a:2524[اً م]ِّنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ‌ۗ وَمَا عِ[f:264[ند]َ [h:408[ٱ]للَّهِ خَيْ[u:2525[رٌ ل]ِّلْأَ[q:2526[بْ]ر[p[َا]رِ","Лекин Роббиларига тақво қилганлар учун остидан анҳорлар оқиб турган жаннатлар бўлиб, унда абадий қолурлар. Бу Аллоҳдан зиёфатдир. Аллоҳ ҳузуридаги нарса аброрлар учун яхшидир.",76,4],["وَإِ[g[نّ]َ مِنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ لَم[a:2527[َن ي]ُؤْمِنُ بِ[h:32[ٱ]للَّهِ وَم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْكُمْ وَم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْهِمْ خَ[n[ـٰ]شِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ ثَمَ[f:208[نًا ق]َلِيلاً‌ۗ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ أَ[q:331[جْ]رُهُمْ عِ[f:264[ند]َ رَبِّهِمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَرِيعُ [h:1112[ٱ]لْحِس[p[َا][q[ب]ِ","Албатта, аҳли китоблардан Аллоҳга, сизларга туширилган нарсага, уларга туширилган нарсага иймон келтирадиганлари, Аллоҳга ўзини хор тутиб бўйин эгадиганлари, Аллоҳнинг оятларини арзон баҳога сотмайдиганлари бордир. Ана ўшаларга Роббилари ҳузурида ажр бордир. Албатта, Аллоҳ тезҳисоб зотдир.",76,4],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:2528[ٱ]صْبِرُو[s[اْ] وَصَابِرُو[s[اْ] وَرَابِطُو[s[اْ] وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ لَعَلَّكُمْ تُفْلِح[p[ُو]نَ","Эй иймон келтирганлар! Сабр қилинг. Сабр ила ғолиб келинг. Курашга бел боғлаб туринг. Аллоҳга тақво қилинг. Шоядки ютуққа эришсангиз.",76,4]]},{"n":4,"ar":"النِّسَاءِ","en":"An-Nisaa","uz":"Нисо","type":"Мадина","ayahs":[["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ [h:2529[ٱ]تَّقُو[s[اْ] رَبَّكُمُ [h:84[ٱ]لَّذِى خَلَقَك[w:2530[ُم م]ّ[a:2531[ِن ن]َّفْ[a:2532[سٍ و][n[َٲ]حِدَ[a:2533[ةٍ و]َخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَال[f:2534[اً ك]َثِي[a:2535[رًا و]َنِس[o[َا]ٓ[a:2536[ءً‌ۚ و]َ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ [h:2537[ٱ]لَّذِى تَس[o[َا]ٓءَلُونَ بِه[n[ِۦ] وَ[h:2538[ٱ]لْأَرْحَامَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَلَيْكُمْ رَقِيبًا","Эй одамлар! Сизларни бир жондан яратган ва ундан унинг жуфтини яратиб, икковларидан кўплаб эркагу аёллар таратган Роббингиздан қўрқинглар! Номини ишлатиб бир-бирингиздан сўровда бўладиганингиз Аллоҳдан ва қариндошлик дан қўрқинг. Албатта, Аллоҳ устингиздан рақобат этувчи зотдир.",77,4],["وَءَاتُو[s[اْ] [h:2539[ٱ]لْيَتَ[n[ـٰ]مَ[o[ىٰٓ] أَمْو[n[َٲ]لَهُمْ‌ۖ وَلَا تَتَبَدَّلُو[s[اْ] [h:2540[ٱ]لْخَبِيثَ بِ[h:2541[ٱ][l[ل]طَّيِّبِ‌ۖ وَلَا تَأْكُل[o[ُوٓ][s[اْ] أَمْو[n[َٲ]لَهُمْ إِلَ[o[ىٰٓ] أَمْو[n[َٲ]لِكُمْ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ حُو[f:2542[بًا ك]َبِيرًا","Ва етимларга ўз молларини беринг. Нопокни покка алмаштирманг. Уларнинг молларини ўзингизнинг молларингизга қўшиб еманг. Зеро, бу катта гуноҳ бўлади.",77,4],["وَإِنْ خِفْتُمْ أَلَّا تُ[q:2543[قْ]سِطُو[s[اْ] فِى [h:2544[ٱ]لْيَتَ[n[ـٰ]مَىٰ فَ[h:2545[ٱ][f:2545[نك]ِحُو[s[اْ] مَا طَابَ لَك[w:1578[ُم م]ِّنَ [h:1769[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ مَثْنَىٰ وَثُلَ[n[ـٰ]ثَ وَرُبَ[n[ـٰ]عَ‌ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُو[s[اْ] فَو[n[َٲ]حِدَةً أَوْ مَا مَلَكَتْ أَيْمَ[n[ـٰ]نُكُمْ‌ۚ ذ[n[َٲ]لِكَ أَ[q:314[دْ]نَ[o[ىٰٓ] أَلَّا تَعُولُو[s[اْ]","Агар етимларга адолат қила олмасликдан қўрқсангиз, ўзингизга ёққан аёллардан иккитами, учтами, тўрттами никоҳлаб олинг. Агар адолат қила олмасликдан қўрқсангиз, биттани ёки қўлингизда мулк бўлганлар билан. Мана шу жабр қилмаслигингизга яқинроқдир.",77,4],["وَءَاتُو[s[اْ] [h:2546[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءَ صَدُقَ[n[ـٰ]تِهِ[g[نّ]َ نِحْلَ[f:2547[ةً‌ۚ ف]َإِ[f:2548[ن ط]ِ[q:2549[بْ]نَ لَكُمْ عَ[f:2550[ن ش][a:2551[َىْءٍ م]ِّنْهُ نَفْ[f:2552[سًا ف]َكُلُوهُ هَنِ[o[يٓ]ـ[a:2553[ـًٔا م]َّرِ[o[يٓ]ــًٔا","Аёлларга маҳрларини кўнгилдан чиқариб беринг. Агар улар ундан бирор нарсани чин кўнгилдан тутсалар, бас, уни енглар. Ош бўлсин, офият бўлсин.",77,4],["وَلَا تُؤْتُو[s[اْ] [h:2554[ٱ][l[ل]سُّفَه[o[َا]ٓءَ أَمْو[n[َٲ]لَكُمُ [h:2555[ٱ]لَّتِى جَعَلَ [h:2556[ٱ]للَّهُ لَكُمْ قِيَ[n[ـٰ][a:2557[مًا و]َ[h:2558[ٱ]رْزُقُوهُمْ فِيهَا وَ[h:2559[ٱ]كْسُوهُمْ وَقُولُو[s[اْ] لَهُمْ قَوْل[a:1331[اً م]َّعْرُوفًا","Аллоҳ тургизиш қилган молларингизни эси пастларга берманг. Уларни ўша моллардан ризқлантиринг, кийинтиринг ва уларга яхши сўзлар айтинг.",77,4],["وَ[h:9999[ٱ][q:2560[بْ]تَلُو[s[اْ] [h:2561[ٱ]لْيَتَ[n[ـٰ]مَىٰ حَتَّ[o[ىٰٓ] إِذَا بَلَغُو[s[اْ] [h:2562[ٱ][l[ل][g[نّ]ِكَاحَ فَإِنْ ءَانَسْت[w:2563[ُم م]ِّنْهُمْ رُشْ[f:2564[دًا ف]َ[h:2565[ٱ][q:2565[دْ]فَع[o[ُوٓ][s[اْ] إِلَيْهِمْ أَمْو[n[َٲ]لَهُمْ‌ۖ وَلَا تَأْكُلُوه[o[َآ] إِسْرَا[a:2566[فًا و]َبِدَارًا أ[a:2567[َن ي]َكْبَرُو[s[اْ‌ۚ] وَمَ[f:975[ن ك]َانَ غَنِي[f:2568[ًّا ف]َلْيَسْتَعْفِفْ‌ۖ وَمَ[f:975[ن ك]َانَ فَقِي[f:2569[رًا ف]َلْيَأْكُلْ بِ[h:934[ٱ]لْمَعْرُوفِ‌ۚ فَإِذَا دَفَعْتُمْ إِلَيْهِمْ أَمْو[n[َٲ]لَهُمْ فَأَشْهِدُو[s[اْ] عَلَيْهِمْ‌ۚ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ حَسِيبًا","Етимларни то никоҳ етгунларича синаб туринглар. Агар уларнинг эси-ҳуши жойида эканини билсангиз, уларга ўз молларини топширинг. У молларни исроф ила ва эгаларининг катта бўлиб қолишидан қўрқиб шошилиб еманг. Бой бўлганлар иффатли бўлсинлар. Ким камбағал бўлса, тўғрилик билан есин. Уларга ўз молларини топшираётганингизда гувоҳлар келтиринг. Ҳисобчиликка Аллоҳнинг ўзи кифоя қилур.",77,4],["لِّلرِّجَالِ نَصِي[a:1111[بٌ م]ِّ[g[مّ]َا تَرَكَ [h:2570[ٱ]لْو[n[َٲ]لِدَانِ وَ[h:2571[ٱ]لْأَ[q:2571[قْ]رَبُونَ وَلِل[g[نّ]ِس[o[َا]ٓءِ نَصِي[a:1111[بٌ م]ِّ[g[مّ]َا تَرَكَ [h:2570[ٱ]لْو[n[َٲ]لِدَانِ وَ[h:2571[ٱ]لْأَ[q:2571[قْ]رَبُونَ مِ[g[مّ]َا قَلَّ مِنْهُ أَوْ كَثُرَ‌ۚ نَصِي[a:2572[بًا م]َّفْرُوضًا","Ота-оналар ва қариндошлар қолдирган нарсада эркакларнинг насибаси бор. Ота-оналар ва қариндошлар қолдирган нарсада аёлларнинг насибаси бор. У оз бўлсин, кўп бўлсин–фарз қилинган насибадир.",78,4],["وَإِذَا حَضَرَ [h:2573[ٱ]لْقِسْمَةَ أُ[s[وْ]لُو[s[اْ] [h:2574[ٱ]لْقُرْبَىٰ وَ[h:420[ٱ]لْيَتَ[n[ـٰ]مَىٰ وَ[h:2575[ٱ]لْمَسَ[n[ـٰ]كِينُ فَ[h:2576[ٱ]رْزُقُوه[w:2577[ُم م]ِّنْهُ وَقُولُو[s[اْ] لَهُمْ قَوْل[a:1331[اً م]َّعْرُوفًا","Агар тақсимлашга қариндошлар, етимлар ва мискинлар ҳозир бўлсалар, уларни удан ризқлантиринглар ҳамда уларга яхши гаплар айтинглар.",78,4],["وَلْيَخْشَ [h:2578[ٱ]لَّذِينَ لَوْ تَرَكُو[s[اْ] مِنْ خَلْفِهِمْ ذُرِّيَّ[f:2579[ةً ض]ِعَ[n[ـٰ]فًا خَافُو[s[اْ] عَلَيْهِمْ فَلْيَتَّقُو[s[اْ] [h:2580[ٱ]للَّهَ وَلْيَقُولُو[s[اْ] قَوْل[f:2581[اً س]َدِيدًا","Ўзлари заифҳол зурриётларини ортдан қолдиришдан қандай қўрқсалар, шундай қўрқсинлар. Бас, Аллоҳдан қўрқсинлар ва тўғри сўз айтсинлар.",78,4],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَأْكُلُونَ أَمْو[n[َٲ]لَ [h:2582[ٱ]لْيَتَ[n[ـٰ]مَىٰ ظُلْمًا إِ[g[نّ]َمَا يَأْكُلُونَ فِى بُطُونِهِمْ نَا[a:2583[رًا‌ۖ و]َسَيَصْلَوْنَ سَعِيرًا","Албатта, етимларнинг молини зулм ила еганлар, қоринларида оловни еган бўладилар. Ва, шубҳасиз, дўзахга кирадилар.",78,4],["يُوصِيكُمُ [h:2584[ٱ]للَّهُ ف[o[ِىٓ] أَوْلَ[n[ـٰ]دِكُمْ‌ۖ لِلذَّكَرِ مِثْلُ حَظِّ [h:2585[ٱ]لْأُ[f:2586[نث]َيَيْنِ‌ۚ فَإِ[f:2587[ن ك]ُ[g[نّ]َ نِس[o[َا]ٓ[f:2588[ءً ف]َوْقَ [h:2589[ٱ]ثْنَتَيْنِ فَلَهُ[g[نّ]َ ثُلُثَا مَا تَرَكَ‌ۖ وَإِ[f:740[ن ك]َانَتْ و[n[َٲ]حِدَ[f:2590[ةً ف]َلَهَا [h:2591[ٱ][l[ل][g[نّ]ِصْفُ‌ۚ وَلِأَبَوَيْهِ لِكُلِّ و[n[َٲ]حِ[a:2592[دٍ م]ِّنْهُمَا [h:2593[ٱ][l[ل]سُّدُسُ مِ[g[مّ]َا تَرَكَ إِ[f:2594[ن ك]َانَ لَهُ[n[ۥ] وَلَ[f:2595[دٌ‌ۚ ف]َإ[u:110[ِن ل]َّمْ يَك[u:2596[ُن ل]َّهُ[n[ۥ] وَلَ[a:2597[دٌ و]َوَرِثَهُ[o[ۥٓ] أَبَوَاهُ فَلِأُ[g[مّ]ِهِ [h:2598[ٱ][l[ل]ثُّلُثُ‌ۚ فَإِ[f:1670[ن ك]َانَ لَهُ[o[ۥٓ] إِخْوَ[f:2599[ةٌ ف]َلِأُ[g[مّ]ِهِ [h:2600[ٱ][l[ل]سُّدُسُ‌ۚ م[i:146[ِنۢ ب]َعْدِ وَصِيَّ[a:2601[ةٍ ي]ُوصِى بِه[o[َآ] أَوْ دَيْنٍ‌ۗ ءَاب[o[َا]ٓؤُكُمْ وَأَ[q:2602[بْ]ن[o[َا]ٓؤُكُمْ لَا تَ[q:2603[دْ]رُونَ أَيُّهُمْ أَ[q:1355[قْ]رَبُ لَكُمْ نَفْ[f:2604[عًا‌ۚ ف]َرِيضَ[a:2605[ةً م]ِّنَ [h:321[ٱ]للَّهِ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَلِيمًا حَكِيمًا","Аллоҳ сизга фарзандларингиз ҳақида васият этиб, бир ўғилга икки қиз насибасича беришни амр этади. Агар улар иккитадан кўп бўлсалар, уларга у қолдирганнинг учдан иккиси. Агар қиз битта бўлса, унга ярми. Агар унинг боласи бўлса, у тарк қилган нарсадан ота-онасининг ҳар бирига олтидан бир. Агар унинг боласи бўлмаса ва ота-онаси меросхўр бўлса, онасига учдан бир. Агар унинг ака-укалари бўлса, онасига олтидан бир. У қилган васият ёки қарзини адо этгандан сўнг, оталарингиз ва болаларингиздан қайси бирлари сизга манфаатлироқ эканини билмассизлар. Бу Аллоҳ жорий қилган фарздир. Албатта, Аллоҳ билувчи ва ҳикматли зотдир.",78,4],["۞ وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْو[n[َٲ]جُكُمْ إ[u:2606[ِن ل]َّمْ يَك[u:2607[ُن ل]َّهُ[g[نّ]َ وَلَ[f:2595[دٌ‌ۚ ف]َإِ[f:1670[ن ك]َانَ لَهُ[g[نّ]َ وَلَ[f:2608[دٌ ف]َلَكُمُ [h:2609[ٱ][l[ل]رُّبُعُ مِ[g[مّ]َا تَرَكْنَ‌ۚ م[i:146[ِنۢ ب]َعْدِ وَصِيَّ[a:2610[ةٍ ي]ُوصِينَ بِه[o[َآ] أَوْ دَيْ[a:2611[نٍ‌ۚ و]َلَهُ[g[نّ]َ [h:2612[ٱ][l[ل]رُّبُعُ مِ[g[مّ]َا تَرَكْتُمْ إ[u:2606[ِن ل]َّمْ يَك[u:2613[ُن ل]َّكُمْ وَلَ[f:2595[دٌ‌ۚ ف]َإِ[f:1670[ن ك]َانَ لَكُمْ وَلَ[f:2614[دٌ ف]َلَهُ[g[نّ]َ [h:2615[ٱ][l[ل]ثُّمُنُ مِ[g[مّ]َا تَرَكْت[w:2616[ُم‌ۚ م]ّ[i:146[ِنۢ ب]َعْدِ وَصِيَّ[f:2617[ةٍ ت]ُوصُونَ بِه[o[َآ] أَوْ دَيْ[a:2618[نٍ‌ۗ و]َإِ[f:1649[ن ك]َانَ رَجُ[a:2619[لٌ ي]ُورَثُ كَلَ[n[ـٰ]لَةً أَوِ [h:2620[ٱ]مْرَأَ[a:2621[ةٌ و]َلَهُ[o[ۥٓ] أَخٌ أَوْ أُخْ[f:2622[تٌ ف]َلِكُلِّ و[n[َٲ]حِ[a:2592[دٍ م]ِّنْهُمَا [h:2593[ٱ][l[ل]سُّدُسُ‌ۚ فَإِ[f:2623[ن ك]َان[o[ُوٓ][s[اْ] أَكْثَرَ مِ[f:2624[ن ذ][n[َٲ]لِكَ فَهُمْ شُرَك[o[َا]ٓءُ فِى [h:2625[ٱ][l[ل]ثُّلُثِ‌ۚ م[i:146[ِنۢ ب]َعْدِ وَصِيَّ[a:2626[ةٍ ي]ُوصَىٰ بِه[o[َآ] أَوْ دَيْنٍ غَيْرَ مُض[m[َا]ٓ[a:2627[رٍّ‌ۚ و]َصِيَّ[a:2628[ةً م]ِّنَ [h:321[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَل[p[ِي]مٌ","Сизларга хотинларингиз қолдирган нарсанинг–агар уларнинг боласи бўлмаса–ярми тегади. Агар уларнинг боласи бўлса, сизга улар қолдирган нарсанинг чораги тегади. Улар қилган васиятни ёки қарзларини адо этгандан сўнг. Уларга сиз қолдирган нарсанинг–агар болангиз бўлмаса–чораги тегади. Агар болангиз бўлса, уларга сиз қолдирган нарсанинг саккиздан бири тегади. Сиз қилган васиятни ёки қарзингизни адо этгандан сўнг. Агар бир эркак ёки аёл калола ҳолида мерос қолдирса, унинг биродари ёки синглиси бўлса, улардан ҳар бирига олтидан бир тегур. Агар улар бундан кўп бўлсалар, учдан бирига шерикдирлар. Зарар қилмайдиган васиятни ёки қарзни адо этгандан сўнг. Булар Аллоҳнинг васиятидир. Ва Аллоҳ билувчи ҳамда ҳалийм зотдир.",79,4],["تِلْكَ حُدُودُ [h:1000[ٱ]للَّهِ‌ۚ وَم[a:2629[َن ي]ُطِعِ [h:2630[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] يُ[q:2631[دْ]خِلْهُ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۚ وَذ[n[َٲ]لِكَ [h:2632[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Ана ўшалар, Аллоҳнинг чегараларидир. Ким Аллоҳга ва Унинг Расулига итоат этса, уни остидан анҳорлар оқиб турган жаннатга абадий қолиш учун киритадир. Бу эса, улкан ютуқдир.",79,4],["وَم[a:2634[َن ي]َعْصِ [h:2635[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] وَيَتَعَدَّ حُدُودَهُ[n[ۥ] يُ[q:2631[دْ]خِلْهُ نَارًا خَ[n[ـٰ]لِ[f:2636[دًا ف]ِيهَا وَلَهُ[n[ۥ] عَذَا[a:478[بٌ م]ُّه[p[ِي]نٌ","Ким Аллоҳга ва Унинг Расулига исён қилса ва Унинг чегарасидан тажовуз қилса, уни абадий қолиш учун дўзахга киритадир. Ва унга хорловчи азоб бордир.",79,4],["وَ[h:9999[ٱ]لَّ[n[ـٰ]تِى يَأْتِينَ [h:2637[ٱ]لْفَ[n[ـٰ]حِشَةَ م[a:2638[ِن ن]ِّس[o[َا]ٓئِكُمْ فَ[h:2639[ٱ]سْتَشْهِدُو[s[اْ] عَلَيْهِ[g[نّ]َ أَرْبَعَ[a:2640[ةً م]ِّ[f:344[نك]ُمْ‌ۖ فَإِ[f:2641[ن ش]َهِدُو[s[اْ] فَأَمْسِكُوهُ[g[نّ]َ فِى [h:2642[ٱ]لْبُيُوتِ حَتَّىٰ يَتَوَفَّ[n[ـٰ]هُ[g[نّ]َ [h:2643[ٱ]لْمَوْتُ أَوْ يَ[q:2441[جْ]عَلَ [h:2644[ٱ]للَّهُ لَهُ[g[نّ]َ سَبِيلاً","Аёлларингиздан фоҳиша қилганларига ўзларингиздан тўртта гувоҳ келтиринг. Агар гувоҳлик берсалар, уларни то ўлим етгунча ёки Аллоҳ бир йўл кўрсатгунча уйларида тутиб туринг.",80,4],["وَ[h:9999[ٱ]لَّذَانِ يَأْتِيَ[n[ـٰ]نِهَا مِ[f:344[نك]ُمْ فَـَٔـاذُوهُمَا‌ۖ فَإِ[f:2645[ن ت]َابَا وَأَصْلَحَا فَأَعْرِضُو[s[اْ] عَنْهُم[o[َآ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ تَوَّا[u:2646[بًا ر]َّحِيمًا","Сизлардан ўша ишни қилган икки эркакка озор беринглар. Агар икковлари тавба қилсалар ва тузалсалар, уларни тек қўйинг. Албатта, Аллоҳ тавбаларни қабул қилувчи ва раҳмли зотдир.",80,4],["إِ[g[نّ]َمَا [h:2647[ٱ][l[ل]تَّوْبَةُ عَلَى [h:412[ٱ]للَّهِ لِلَّذِينَ يَعْمَلُونَ [h:2648[ٱ][l[ل]سّ[o[ُو]ٓءَ بِجَهَ[n[ـٰ]لَ[f:2649[ةٍ ث]ُ[g[مّ]َ يَتُوبُونَ مِ[f:2650[ن ق]َرِي[f:2651[بٍ ف]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يَتُوبُ [h:2652[ٱ]للَّهُ عَلَيْهِمْ‌ۗ وَكَانَ [h:2653[ٱ]للَّهُ عَلِيمًا حَكِيمًا","Жаҳолат-ла ёмонлик қилиб қўйиб, сўнгра тезда тавба қиладиганларнинг тавбаси Аллоҳнинг зиммасидадир. Аллоҳ ана ўшаларнинг тавбасини қабул қилади. Ва Аллоҳ билувчи ва ҳикматли зотдир.",80,4],["وَلَيْسَتِ [h:2654[ٱ][l[ل]تَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ [h:2655[ٱ][l[ل]سَّيِّـَٔـاتِ حَتَّ[o[ىٰٓ] إِذَا حَضَرَ أَحَدَهُمُ [h:2656[ٱ]لْمَوْتُ قَالَ إِ[g[نّ]ِى تُ[q:2657[بْ]تُ [h:2658[ٱ]لْـَٔ[n[ـٰ]نَ وَلَا [h:2659[ٱ]لَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَعْتَ[q:2660[دْ]نَا لَهُمْ عَذَابًا أَلِيمًا","Ёмонликларни қилиб юриб, бирларига ўлим етганда, энди тавба қилдим, деганларга ва кофир ҳолларида ўлганларга тавба йўқ. Ана ўшаларга аламли азобларни тайёрлаб қўйганмиз.",80,4],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا يَحِلُّ لَكُمْ أَ[f:2661[ن ت]َرِثُو[s[اْ] [h:2662[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءَ كَرْ[a:2663[هًا‌ۖ و]َلَا تَعْضُلُوهُ[g[نّ]َ لِتَذْهَبُو[s[اْ] بِبَعْضِ م[o[َآ] ءَاتَيْتُمُوهُ[g[نّ]َ إِلّ[o[َآ] أ[a:2664[َن ي]َأْتِينَ بِفَ[n[ـٰ]حِشَ[a:2665[ةٍ م]ُّبَيِّنَ[a:2666[ةٍ‌ۚ و]َعَاشِرُوهُ[g[نّ]َ بِ[h:934[ٱ]لْمَعْرُوفِ‌ۚ فَإِ[f:2667[ن ك]َرِهْتُمُوهُ[g[نّ]َ فَعَسَ[o[ىٰٓ] أَ[f:1194[ن ت]َكْرَهُو[s[اْ] شَيْـ[a:2668[ـًٔا و]َيَ[q:2669[جْ]عَلَ [h:2670[ٱ]للَّهُ فِيهِ خَيْ[f:1594[رًا ك]َثِيرًا","Эй иймон келтирганлар! Сизларга аёлларни зулм-ла меросга олиш ҳалол эмас. Очиқ фоҳиша иш қилмасалар, берган нарсаларнингизнинг баъзисини олиш учун уларни зўрлик-ла ушлаб турманг ва улар илаяхшиликда яшанг. Агар уларни ёқтирмасангиз, шоядки, Аллоҳ сиз ёқтирмаган нарсада кўпгина яхшиликларни қилса.",80,4],["وَإِنْ أَرَ[d:2671[د]تُّمُ [h:2672[ٱ]سْتِ[q:2673[بْ]دَالَ زَوْ[a:2674[جٍ م]َّكَانَ زَوْ[a:2675[جٍ و]َءَاتَيْتُمْ إِحْدَ[n[ٮٰ]هُ[g[نّ]َ قِ[f:2676[نط]َا[f:2677[رًا ف]َلَا تَأْخُذُو[s[اْ] مِنْهُ شَيْــًٔا‌ۚ أَتَأْخُذُونَهُ[n[ۥ] بُهْتَ[n[ـٰ][a:2678[نًا و]َإِثْ[a:2679[مًا م]ُّبِينًا","Ва агар хотин ўрнига бошқа хотин олмоқчи бўлсангиз ва уларнинг бирига ҳаддан зиёд меҳр берган бўлсангиз ҳам, ундан ҳеч нарсани қайтариб олманг. Уни бўҳтон ва катта гуноҳ ҳолида оласизми?",81,4],["وَكَيْفَ تَأْخُذُونَهُ[n[ۥ] وَقَ[q:387[دْ] أَفْضَىٰ بَعْضُكُمْ إِلَىٰ بَعْ[a:2680[ضٍ و]َأَخَذْنَ مِ[f:344[نك][w:2681[ُم م]ِّيثَ[n[ـٰ]قًا غَلِيظًا","Ва қандай ҳам олурсиз?! Ахир, бир-бирингизга қовишдингиз ва улар сиздан мустаҳкам аҳду паймон олганлар-ку?!",81,4],["وَلَا تَ[f:1228[نك]ِحُو[s[اْ] مَا نَكَحَ ءَاب[o[َا]ٓؤُك[w:2682[ُم م]ِّنَ [h:1769[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ إِلَّا مَا قَ[q:298[دْ] سَلَفَ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ فَ[n[ـٰ]حِشَ[a:2683[ةً و]َمَ[q:2684[قْ][a:2685[تًا و]َس[o[َا]ٓءَ سَبِيلاً","Оталарингиз ўз никоҳларига олган аёлларни сиз ўз никоҳингизга олманг! Аввал ўтган бўлса, майли. Бу иш, албатта, фоҳиша, ғазабнок иш ва қандай ҳам ёмон йўлдир!",81,4],["حُرِّمَتْ عَلَيْكُمْ أُ[g[مّ]َهَ[n[ـٰ]تُكُمْ وَبَنَاتُكُمْ وَأَخَو[n[َٲ]تُكُمْ وَعَ[g[مّ]َ[n[ـٰ]تُكُمْ وَخَ[n[ـٰ]لَ[n[ـٰ]تُكُمْ وَبَنَاتُ [h:2686[ٱ]لْأَخِ وَبَنَاتُ [h:2687[ٱ]لْأُخْتِ وَأُ[g[مّ]َهَ[n[ـٰ]تُكُمُ [h:2688[ٱ]لَّ[n[ـٰ]ت[o[ِىٓ] أَرْضَعْنَكُمْ وَأَخَو[n[َٲ]تُك[w:2689[ُم م]ِّنَ [h:2690[ٱ][l[ل]رَّضَ[n[ـٰ]عَةِ وَأُ[g[مّ]َهَ[n[ـٰ]تُ نِس[o[َا]ٓئِكُمْ وَرَبَ[o[ـٰٓ]ئِبُكُمُ [h:2691[ٱ]لَّ[n[ـٰ]تِى فِى حُجُورِك[w:2692[ُم م]ّ[a:2693[ِن ن]ِّس[o[َا]ٓئِكُمُ [h:2694[ٱ]لَّ[n[ـٰ]تِى دَخَلْت[c:2695[ُم ب]ِهِ[g[نّ]َ فَإ[u:110[ِن ل]َّمْ تَكُونُو[s[اْ] دَخَلْت[c:2695[ُم ب]ِهِ[g[نّ]َ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَ[o[ـٰٓ]ئِلُ أَ[q:2696[بْ]ن[o[َا]ٓئِكُمُ [h:2697[ٱ]لَّذِينَ مِنْ أَصْلَ[n[ـٰ]بِكُمْ وَأَ[f:2698[ن ت]َ[q:2699[جْ]مَعُو[s[اْ] بَيْنَ [h:2700[ٱ]لْأُخْتَيْنِ إِلَّا مَا قَ[q:298[دْ] سَلَفَ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ غَفُو[u:2701[رًا ر]َّحِيمًا","Сизларга оналарингиз, қизларингиз, опа-сингилларингиз, аммаларингиз, холаларингиз, ака-укаларингизнинг қизлари, опа-сингилларингизнинг қизлари, эмизган оналарингиз, эмикдош опа-сингилларингиз, хотинларингизнинг оналари, ўзингиз қовушган хотинларингизнинг қарамоғингиздаги қизлари ҳаром қилинди. Агар улар билан қовушмаган бўлсангиз, гуноҳ йўқ. Ва пуштингиздан бўлган ўғилларингизнинг хотинлари, опа-сингилни қўшиб олмоғингиз ҳаром қилинди. Магар аввал ўтган бўлса, майли. Албатта, Аллоҳ маҳфират қилувчи ва раҳмли зотдир.",81,4],["۞ وَ[h:9999[ٱ]لْمُحْصَنَ[n[ـٰ]تُ مِنَ [h:1769[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ إِلَّا مَا مَلَكَتْ أَيْمَ[n[ـٰ]نُكُمْ‌ۖ كِتَ[n[ـٰ]بَ [h:525[ٱ]للَّهِ عَلَيْكُمْ‌ۚ وَأُحِلَّ لَك[w:154[ُم م]َّا وَر[o[َا]ٓءَ ذ[n[َٲ]لِكُمْ أَ[f:1086[ن ت]َ[q:1087[بْ]تَغُو[s[اْ] بِأَمْو[n[َٲ]لِك[w:2702[ُم م]ُّحْصِنِينَ غَيْرَ مُسَ[n[ـٰ]فِحِينَ‌ۚ فَمَا [h:2703[ٱ]سْتَمْتَعْت[c:2704[ُم ب]ِه[n[ِۦ] مِنْهُ[g[نّ]َ فَـَٔـاتُوهُ[g[نّ]َ أُجُورَهُ[g[نّ]َ فَرِيضَ[a:2705[ةً‌ۚ و]َلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَر[n[َٲ]ضَيْت[c:2706[ُم ب]ِه[n[ِۦ] م[i:146[ِنۢ ب]َعْدِ [h:2707[ٱ]لْفَرِيضَةِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَلِيمًا حَكِيمًا","Қўлингизга мулк бўлиб тушганлардан бошқа эрли аёллар ҳам. Бу сизларга Аллоҳнинг ёзганидир. Ана ўшалардан бошқаларни поклик ва зино аралаштирмаган ҳолда молларингиз ила талаб қилмоғингиз ҳалол қилинди. Улардан ҳузурланишингиз сабабидан маҳрларини беринг. Бу фарздир. Фарз маҳрдан кейин ўзаро розилик ила келишганингиз гуноҳ эмас. Албатта, Аллоҳ билувчи ва ҳикматли зотдир.",82,5],["وَم[u:1416[َن ل]َّمْ يَسْتَطِعْ مِ[f:344[نك]ُمْ طَوْلاً أ[a:2708[َن ي]َ[f:2709[نك]ِحَ [h:2710[ٱ]لْمُحْصَنَ[n[ـٰ]تِ [h:2711[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ فَم[a:2712[ِن م]َّا مَلَكَتْ أَيْمَ[n[ـٰ]نُك[w:2713[ُم م]ِّ[f:2714[ن ف]َتَيَ[n[ـٰ]تِكُمُ [h:2715[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ‌ۚ وَ[h:72[ٱ]للَّهُ أَعْلَمُ بِإِيمَ[n[ـٰ]نِك[c:2716[ُم‌ۚ ب]َعْضُك[w:2512[ُم م]ّ[i:1862[ِنۢ ب]َعْ[f:2717[ضٍ‌ۚ ف]َ[h:2718[ٱ][f:2718[نك]ِحُوهُ[g[نّ]َ بِإِذْنِ أَهْلِهِ[g[نّ]َ وَءَاتُوهُ[g[نّ]َ أُجُورَهُ[g[نّ]َ بِ[h:934[ٱ]لْمَعْرُوفِ مُحْصَنَ[n[ـٰ]تٍ غَيْرَ مُسَ[n[ـٰ]فِحَ[n[ـٰ][a:2719[تٍ و]َلَا مُتَّخِذ[n[َٲ]تِ أَخْدَا[f:2720[نٍ‌ۚ ف]َإِذ[o[َآ] أُحْصِ[g[نّ]َ فَإِنْ أَتَيْنَ بِفَ[n[ـٰ]حِشَ[f:2721[ةٍ ف]َعَلَيْهِ[g[نّ]َ نِصْفُ مَا عَلَى [h:2722[ٱ]لْمُحْصَنَ[n[ـٰ]تِ مِنَ [h:503[ٱ]لْعَذَابِ‌ۚ ذ[n[َٲ]لِكَ لِمَنْ خَشِىَ [h:2723[ٱ]لْعَنَتَ مِ[f:344[نك]ُمْ‌ۚ وَأَ[f:2724[ن ت]َصْبِرُو[s[اْ] خَيْ[u:263[رٌ ل]َّكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Сизлардан ким ҳур мўминаларни никоҳига олишга имкон топмаса, қўлингизда мулк бўлган мўмина канизаклардан. Аллоҳ иймонингизни билувчи зотдир. Ҳаммаларингиз бирсиз. Уларни никоҳингизга аҳлларининг изни ила олинг. Ва яхшилик билан маҳрларини беринг. Улар покиза, зинокор эмас ва ўйнаш тутмаган бўлсинлар. Эрга текканларидан сўнг фоҳиша иш қилсалар, уларга ҳур аёлларга бериладиган азобнинг ярми бериладир. Бу бузилишдан қўрққанлар учундир. Сабр қилмоғингиз сиз учун яхшидир. Аллоҳ мағфиратли ва раҳмлидир.",82,5],["يُرِيدُ [h:976[ٱ]للَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ [h:2725[ٱ]لَّذِينَ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ وَيَتُوبَ عَلَيْكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Аллоҳ сизларга баён қилиб беришни, сизни олдингиларнинг йўлига ҳидоят қилишни ва тавбаларингизни қабул этишни хоҳлайди. Аллоҳ билувчи ва ҳикматли зотдир.",82,5],["وَ[h:9999[ٱ]للَّهُ يُرِيدُ أ[a:2726[َن ي]َتُوبَ عَلَيْكُمْ وَيُرِيدُ [h:2727[ٱ]لَّذِينَ يَتَّبِعُونَ [h:2728[ٱ][l[ل]شَّهَو[n[َٲ]تِ أَ[f:2729[ن ت]َمِيلُو[s[اْ] مَيْلاً عَظِيمًا","Аллоҳ сизнинг тавбангизни қабул қилишни хоҳлайдир. Шаҳватларга эргашадиганлар эса, улкан оғишга мойил бўлишингизни хоҳларлар.",83,5],["يُرِيدُ [h:976[ٱ]للَّهُ أ[a:2730[َن ي]ُخَفِّفَ عَ[f:255[نك]ُمْ‌ۚ وَخُلِقَ [h:2731[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ ضَعِيفًا","Аллоҳ сиздан енгиллатмоқни хоҳлайдир. Ва инсон заиф яратилгандир.",83,5],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَأْكُل[o[ُوٓ][s[اْ] أَمْو[n[َٲ]لَك[c:1003[ُم ب]َيْنَك[c:1004[ُم ب]ِ[h:212[ٱ]لْبَ[n[ـٰ]طِلِ إِلّ[o[َآ] أَ[f:1566[ن ت]َكُونَ تِجَ[n[ـٰ]رَةً عَ[f:1314[ن ت]َرَا[a:2733[ضٍ م]ِّ[f:344[نك]ُمْ‌ۚ وَلَا تَ[q:2734[قْ]تُل[o[ُوٓ][s[اْ] أَ[f:221[نف]ُسَكُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ بِكُمْ رَحِيمًا","Эй иймон келтирганлар! Бир-бирларингизнинг молларингизни ботил йўл билан еманглар. Магар ўзаро розилик ила тижорат бўлса, майли. Ўзингизни ўзингиз ўлдирманг. Албатта, Аллоҳ сизларга раҳмлидир.",83,5],["وَم[a:1297[َن ي]َفْعَلْ ذ[n[َٲ]لِكَ عُ[q:2735[دْ]و[n[َٲ][a:2736[نًا و]َظُلْ[f:2737[مًا ف]َسَوْفَ نُصْلِيهِ نَا[a:2738[رًا‌ۚ و]َكَانَ ذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ يَسِيرًا","Ким ўшани тажовузкорлик ва зулм ила қилса, албатта, уни дўзахга киритамиз. Бу эса, Аллоҳга осондир.",83,5],["إِ[f:2739[ن ت]َ[q:2740[جْ]تَنِبُو[s[اْ] كَب[o[َا]ٓئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَ[f:255[نك]ُمْ سَيِّـَٔـاتِكُمْ وَنُ[q:2741[دْ]خِلْك[w:2742[ُم م]ُّ[q:2743[دْ]خَل[f:2744[اً ك]َرِيمًا","Агар қайтарилган нарсаларнинг катталаридан четда бўлсангиз, гуноҳларингизни кечирамиз ва сизни яхши жойга киритамиз.",83,5],["وَلَا تَتَمَ[g[نّ]َوْ[s[اْ] مَا فَضَّلَ [h:2745[ٱ]للَّهُ بِه[n[ِۦ] بَعْضَكُمْ عَلَىٰ بَعْ[u:2746[ضٍ‌ۚ ل]ِّلرِّجَالِ نَصِي[a:1111[بٌ م]ِّ[g[مّ]َا [h:2747[ٱ]كْتَسَبُو[s[اْ‌ۖ] وَلِل[g[نّ]ِس[o[َا]ٓءِ نَصِي[a:1111[بٌ م]ِّ[g[مّ]َا [h:2748[ٱ]كْتَسَ[q:2749[بْ]نَ‌ۚ وَسْــَٔلُو[s[اْ] [h:2750[ٱ]للَّهَ مِ[f:475[ن ف]َضْلِه[o[ِۦٓ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا","Аллоҳ баъзингизни баъзингиздан афзал этган нарсаларни орзу этманг. Эркакларга ўз касбидан насиба бор. Аёлларга ўз касбидан насиба бор. Аллоҳдан фазлини сўранг. Албатта, Аллоҳ ҳар бир нарсани билувчи зотдир.",83,5],["وَلِكُ[f:2751[لٍّ ج]َعَلْنَا مَو[n[َٲ]لِىَ مِ[g[مّ]َا تَرَكَ [h:2570[ٱ]لْو[n[َٲ]لِدَانِ وَ[h:2571[ٱ]لْأَ[q:2571[قْ]رَبُونَ‌ۚ وَ[h:37[ٱ]لَّذِينَ عَقَدَتْ أَيْمَ[n[ـٰ]نُكُمْ فَـَٔـاتُوهُمْ نَصِيبَهُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَلَىٰ كُلِّ ش[f:2752[َىْءٍ ش]َهِيدًا","Ота-она ва қариндошлар қолдирган нарсага ҳар бир киши учун меросхўрлар қилдик. Қасамингиз ила боғланганларга насибасини беринг. Албатта, Аллоҳ ҳар бир нарсага шоҳиддир.",83,5],["ٱ[l[ل]رِّجَالُ قَوّ[n[َٲ]مُونَ عَلَى [h:2753[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ بِمَا فَضَّلَ [h:2745[ٱ]للَّهُ بَعْضَهُمْ عَلَىٰ بَعْ[a:2754[ضٍ و]َبِم[o[َآ] أَ[f:1538[نف]َقُو[s[اْ] مِنْ أَمْو[n[َٲ]لِهِمْ‌ۚ فَ[h:2755[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تُ قَ[n[ـٰ]نِتَ[n[ـٰ]تٌ حَ[n[ـٰ]فِظَ[n[ـٰ][u:2756[تٌ ل]ِّلْغَيْبِ بِمَا حَفِظَ [h:2757[ٱ]للَّهُ‌ۚ وَ[h:2758[ٱ]لَّ[n[ـٰ]تِى تَخَافُونَ نُشُوزَهُ[g[نّ]َ فَعِظُوهُ[g[نّ]َ وَ[h:2759[ٱ]هْجُرُوهُ[g[نّ]َ فِى [h:2760[ٱ]لْمَضَاجِعِ وَ[h:2761[ٱ]ضْرِبُوهُ[g[نّ]َ‌ۖ فَإِنْ أَطَعْنَكُمْ فَلَا تَ[q:2762[بْ]غُو[s[اْ] عَلَيْهِ[g[نّ]َ سَبِيلاً‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَلِي[f:2763[ًّا ك]َبِيرًا","Аллоҳ баъзиларини баъзиларидан устун қилгани ва молларидан сарфлаганлари учун эркаклар аёлларга раҳбардирлар. Солиҳа аёллар–итоаткор ва Аллоҳнинг ҳифзи-ҳимояси бўйича ғойибларининг муҳофазасини қилувчилардир. Бош кўтаришларидан хавф қилинган аёлларга ваъз-насиҳат қилинг, ётоқларида ҳижрон қилинг ва уринг. Агар итоат қилсалар, уларга қарши бошқа йўл ахтарманг. Албатта, Аллоҳ юксак мақомли буюк зотдир.",84,5],["وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَ[h:2764[ٱ][q:2764[بْ]عَثُو[s[اْ] حَكَ[a:2765[مًا م]ِّنْ أَهْلِه[n[ِۦ] وَحَكَ[a:2766[مًا م]ِّنْ أَهْلِه[o[َآ] إ[a:2767[ِن ي]ُرِيد[o[َآ] إِصْلَ[n[ـٰ][a:2768[حًا ي]ُوَفِّقِ [h:2769[ٱ]للَّهُ بَيْنَهُم[o[َآ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَلِيمًا خَبِيرًا","Агар икковларининг оралари бузилишидан қўрқсангиз, эрнинг аҳлидан бир ҳакам ва хотиннинг аҳлидан бир ҳакам ажратинг. Агар улар ислоҳни ирода қилсалар, Аллоҳ эр-хотиннинг орасини мувофиқлаштиради. Албатта, Аллоҳ билувчи ва хабардор зотдир.",84,5],["۞ وَ[h:9999[ٱ]عْبُدُو[s[اْ] [h:2770[ٱ]للَّهَ وَلَا تُشْرِكُو[s[اْ] بِه[n[ِۦ] شَيْـ[a:2771[ـًٔا‌ۖ و]َبِ[h:417[ٱ]لْو[n[َٲ]لِدَيْنِ إِحْسَ[n[ـٰ][a:2772[نًا و]َبِذِى [h:2773[ٱ]لْقُرْبَىٰ وَ[h:420[ٱ]لْيَتَ[n[ـٰ]مَىٰ وَ[h:421[ٱ]لْمَسَ[n[ـٰ]كِينِ وَ[h:2774[ٱ]لْجَارِ ذِى [h:2775[ٱ]لْقُرْبَىٰ وَ[h:2774[ٱ]لْجَارِ [h:2776[ٱ]لْجُنُبِ وَ[h:2777[ٱ][l[ل]صَّاحِبِ بِ[h:2778[ٱ]لْجَ[i:2778[نۢب]ِ وَ[h:1189[ٱ][q:1189[بْ]نِ [h:1190[ٱ][l[ل]سَّبِيلِ وَمَا مَلَكَتْ أَيْمَ[n[ـٰ]نُكُمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُحِبُّ مَ[f:506[ن ك]َانَ مُخْتَال[f:2779[اً ف]َخُورًا","Ва Аллоҳга ибодат қилинглар ва Унга ҳеч нарсани ширк келтирманглар. Ота-онага, қариндошларга, етимларга, мискинларга, яқин қўшниларга, ён қўшниларга, ёнбошдаги соҳибларга, кўчада қолганларга ва қўлингизда мулк бўлганларга яхшилик қилинглар. Албатта, Аллоҳ ўзини юқори тутувчи ва одамлар устидан фахр қилувчиларни хуш кўрмас.",84,5],["ٱلَّذِينَ يَ[q:2456[بْ]خَلُونَ وَيَأْمُرُونَ [h:2780[ٱ][l[ل][g[نّ]َاسَ بِ[h:2781[ٱ]لْبُخْلِ وَيَكْتُمُونَ م[o[َآ] ءَاتَ[n[ـٰ]هُمُ [h:2411[ٱ]للَّهُ مِ[f:475[ن ف]َضْلِه[n[ِۦ]‌ۗ وَأَعْتَ[q:2782[دْ]نَا لِلْكَ[n[ـٰ]فِرِينَ عَذَا[a:2783[بًا م]ُّهِينًا","Улар бахиллик қиладиган, одамларни бахилликка буюрадиган ва Аллоҳ уларга Ўз фазлидан берган нарсаларни беркитадиганлардир. Ва кофирларга хорловчи азобни тайёрлаганмиз.",84,5],["وَ[h:9999[ٱ]لَّذِينَ يُ[f:16[نف]ِقُونَ أَمْو[n[َٲ]لَهُمْ رِئ[o[َا]ٓءَ [h:1551[ٱ][l[ل][g[نّ]َاسِ وَلَا يُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَلَا بِ[h:2784[ٱ]لْيَوْمِ [h:2785[ٱ]لْأَخِرِ‌ۗ وَم[a:2786[َن ي]َكُنِ [h:2787[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ لَهُ[n[ۥ] قَرِي[f:2788[نًا ف]َس[o[َا]ٓءَ قَرِينًا","Улар молларини кишилар кўриши учун сарфлайдилар. Ҳамда Аллоҳга ва қиёмат кунига иймон келтирмайдилар. Кимнинг яқини шайтон бўлса, у қандай ҳам ёмон яқин!",85,5],["وَمَاذَا عَلَيْهِمْ لَوْ ءَامَنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ وَأَ[f:2789[نف]َقُو[s[اْ] مِ[g[مّ]َا رَزَقَهُمُ [h:2790[ٱ]للَّهُ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ بِهِمْ عَلِيمًا","Агар Аллоҳга ва қиёмат кунига иймон келтирсалар, Аллоҳ уларга ризқ қилиб берган нарсадан нафақа қилсалар, уларга нима зарар бўлади? Аллоҳ уларни яхши билувчи зотдир!",85,5],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّ[a:2791[ةٍ‌ۖ و]َإِ[f:2792[ن ت]َكُ حَسَنَ[a:2793[ةً ي]ُضَ[n[ـٰ]عِفْهَا وَيُؤْتِ م[u:2794[ِن ل]َّدُنْهُ أَ[q:2795[جْ]رًا عَظِيمًا","Албатта, Аллоҳ заррача ҳам зулм қилмас. Агар яхшилик бўлса, бир неча бор кўпайтирур ва Ўз ҳузуридан улуғ ажр берур.",85,5],["فَكَيْفَ إِذَا جِئْنَا مِ[f:843[ن ك]ُلِّ أُ[g[مّ]َ[i:2796[ةِۭ ب]ِشَهِي[a:2797[دٍ و]َجِئْنَا بِكَ عَلَىٰ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ شَهِيدًا","Ҳар бир умматдан бир гувоҳ келтириб, сени уларнинг ҳаммасига гувоҳ этиб келтирган чоғимизда ҳол қандоқ бўлур?!",85,5],["يَوْمَئِ[a:2798[ذٍ ي]َوَدُّ [h:544[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَعَصَوُ[s[اْ] [h:2799[ٱ][l[ل]رَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ [h:2800[ٱ]لْأَرْضُ وَلَا يَكْتُمُونَ [h:2801[ٱ]للَّهَ حَدِيثًا","Ўша кунда куфр келтирганлар ва Расулга исён қилганлар ерга қоришиб кетишни истарлар ва Аллоҳдан ҳеч гапни яшира олмаслар.",85,5],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَ[q:2802[قْ]رَبُو[s[اْ] [h:2803[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَأَ[f:98[نت]ُمْ سُكَ[n[ـٰ]رَىٰ حَتَّىٰ تَعْلَمُو[s[اْ] مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغْتَسِلُو[s[اْ‌ۚ] وَإِ[f:99[ن ك]ُ[f:100[نت][w:2804[ُم م]َّرْضَ[o[ىٰٓ] أَوْ عَلَىٰ سَفَرٍ أَوْ ج[o[َا]ٓءَ أَحَ[a:2805[دٌ م]ِّ[f:344[نك][w:2806[ُم م]ِّنَ [h:2807[ٱ]لْغ[o[َا]ٓئِطِ أَوْ لَ[n[ـٰ]مَسْتُمُ [h:2808[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءَ فَلَمْ تَجِدُو[s[اْ] م[o[َا]ٓ[f:2809[ءً ف]َتَيَ[g[مّ]َمُو[s[اْ] صَعِي[f:2810[دًا ط]َيِّ[f:2811[بًا ف]َ[h:2812[ٱ]مْسَحُو[s[اْ] بِوُجُوهِكُمْ وَأَيْدِيكُمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَفُوًّا غَفُورًا","Эй иймон келтирганлар! Маст ҳолингизда–то айтаётган гапингизни биладиган бўлмагунингизча, намозга яқинлашманг ва жунуб ҳолингизда ҳам то ғусл қилмагунингизча. Магар йўлдан ўтувчи бўлса, майли. Агар бемор ёки сафарда бўлсангиз ёки сиздан бирингиз таҳоратхонадан келса ёхуд аёлларга яқинлашган бўлсангиз-у, сув топа олмасангиз, покиза тупроқ-ла таяммум қилинг. Бас, юзингизга ва қўлларингизга масҳ тортинг. Албатта, Аллоҳ афв ва мағфират қилувчи зотдир.",85,5],["أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ أُوتُو[s[اْ] نَصِي[a:1814[بًا م]ِّنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ يَشْتَرُونَ [h:2813[ٱ][l[ل]ضَّلَ[n[ـٰ]لَةَ وَيُرِيدُونَ أَ[f:2814[ن ت]َضِلُّو[s[اْ] [h:2815[ٱ][l[ل]سَّب[p[ِي]لَ","Китобдан насиба берилганларнинг залолатни сотиб олишларини ва сиз йўлдан адашишингизни исташларини кўрмайсизми?",85,5],["وَ[h:9999[ٱ]للَّهُ أَعْلَمُ بِأَعْد[o[َا]ٓئِكُمْ‌ۚ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ وَلِي[a:2816[ًّا و]َكَفَىٰ بِ[h:32[ٱ]للَّهِ نَصِيرًا","Аллоҳ сизнинг душманларингизни билувчи зотдир. Валийликка Аллоҳнинг Ўзи кифоя қилур. Нусрат берувчиликка Аллоҳнинг Ўзи кифоя қилур.",86,5],["مِّنَ [h:523[ٱ]لَّذِينَ هَادُو[s[اْ] يُحَرِّفُونَ [h:2817[ٱ]لْكَلِمَ ع[a:2818[َن م]َّوَاضِعِه[n[ِۦ] وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَ[h:2819[ٱ]سْمَعْ غَيْرَ مُسْمَ[a:2820[عٍ و]َر[n[َٲ]عِنَا لَيّ[i:2821[َۢا ب]ِأَلْسِنَتِهِمْ وَطَعْ[f:2822[نًا ف]ِى [h:1477[ٱ][l[ل]دِّينِ‌ۚ وَلَوْ أَ[g[نّ]َهُمْ قَالُو[s[اْ] سَمِعْنَا وَأَطَعْنَا وَ[h:2819[ٱ]سْمَعْ وَ[h:2823[ٱ][f:2823[نظ]ُرْنَا لَكَانَ خَيْ[u:2160[رًا ل]َّهُمْ وَأَ[q:2824[قْ]وَمَ وَلَ[n[ـٰ]ك[u:2825[ِن ل]َّعَنَهُمُ [h:462[ٱ]للَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلاً","Яҳудий бўлганлардан калималарни ўз жойидан бузиб-ўзгартирувчилар бор. Улар тилларини бураб ва динга таъна етказиб: «Эшитдик ва исён қилдик, эшит, эшитмай қолгур ва «Роина» дерлар. Агар улар, эшитдик, ва итоат қилдик, эшит ва бизга назар сол, деганларида, албатта, ўзларига яхши ва тўғри бўлар эди. Лекин Аллоҳ уларни куфрлари сабабли лаънатлади. Бас, озгиналаридан бошқалари иймон келтирмаслар.",86,5],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ ءَامِنُو[s[اْ] بِمَا نَزَّلْنَا مُصَدِّ[u:206[قًا ل]ِّمَا مَعَك[w:2826[ُم م]ِّ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:2827[َن ن]َّ[q:2828[طْ]مِسَ وُجُو[f:2829[هًا ف]َنَرُدَّهَا عَلَ[o[ىٰٓ] أَ[q:2830[دْ]بَارِه[o[َآ] أَوْ نَلْعَنَهُمْ كَمَا لَعَ[g[نّ][o[َآ] أَصْحَ[n[ـٰ]بَ [h:2831[ٱ][l[ل]سَّ[q:346[بْ]تِ‌ۚ وَكَانَ أَمْرُ [h:2832[ٱ]للَّهِ مَفْعُولاً","Эй китоб берилганлар! Юзларни бузиб, орқаларига бурмасимиздан ёхуд уларни шанба одамларини лаънатлаганимиздек лаънатламасимиздан олдин сизлардаги нарсани тасдиқловчи бўлиб келган нарсага иймон келтиринг. Аллоҳнинг иши амалга ошгусидир.",86,5],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَغْفِرُ أ[a:2833[َن ي]ُشْرَكَ بِه[n[ِۦ] وَيَغْفِرُ مَا دُونَ ذ[n[َٲ]لِكَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ‌ۚ وَم[a:2834[َن ي]ُشْرِكْ بِ[h:32[ٱ]للَّهِ فَقَدِ [h:2835[ٱ]فْتَرَ[o[ىٰٓ] إِثْمًا عَظِيمًا","Албатта, Аллоҳ Ўзига ширк келтирилишини кечирмас. Ундан бошқа гуноҳни, кимни хоҳласа, кечирур. Ким Аллоҳга ширк келтирса, шубҳасиз, катта гуноҳни тўқибдир.",86,5],["أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ يُزَكُّونَ أَ[f:38[نف]ُسَه[c:2836[ُم‌ۚ ب]َلِ [h:2310[ٱ]للَّهُ يُزَكِّى م[a:476[َن ي]َش[o[َا]ٓءُ وَلَا يُظْلَمُونَ فَتِيلاً","Ўзларини пок қилиб кўрсатаётганларни кўрмайсанми?! Йўқ! Аллоҳ кимни хоҳласа, шуни поклайди. Ва қилча зулм қилинмаслар.",86,5],["ٱ[f:2837[نظ]ُرْ كَيْفَ يَفْتَرُونَ عَلَى [h:412[ٱ]للَّهِ [h:2035[ٱ]لْكَذِبَ‌ۖ وَكَفَىٰ بِه[o[ِۦٓ] إِثْ[a:2838[مًا م]ُّبِينًا","Уларнинг Аллоҳга ёлғон тўқишини кўрмайсанми?! Шунинг ўзи ҳам очиқ-ойдин гуноҳликка етарли.",86,5],["أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ أُوتُو[s[اْ] نَصِي[a:1814[بًا م]ِّنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ يُؤْمِنُونَ بِ[h:2839[ٱ]لْجِ[q:2839[بْ]تِ وَ[h:2840[ٱ][l[ل]طَّ[n[ـٰ]غُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُو[s[اْ] هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ أَهْدَىٰ مِنَ [h:523[ٱ]لَّذِينَ ءَامَنُو[s[اْ] سَبِيلاً","Китобдан насибадор бўлганларнинг ботилга ва тоғутга иймон келтиришларини ва куфр келтирганларни кўрсатиб: «Анавилар иймон келтирганлардан кўра ҳидоятлироқ йўлдалар», дейишларини кўрмайсанми?!",86,5],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ لَعَنَهُمُ [h:462[ٱ]للَّهُ‌ۖ وَم[a:2841[َن ي]َلْعَنِ [h:2842[ٱ]للَّهُ فَلَ[f:2843[ن ت]َجِدَ لَهُ[n[ۥ] نَصِيرًا","Ана ўшаларни Аллоҳ лаънатлагандир. Кимни Аллоҳ лаънатласа, унга ҳеч нусратчи тополмассан.",87,5],["أَمْ لَهُمْ نَصِي[a:2844[بٌ م]ِّنَ [h:2845[ٱ]لْمُلْكِ فَإِ[u:2846[ذًا ل]َّا يُؤْتُونَ [h:2847[ٱ][l[ل][g[نّ]َاسَ نَقِيرًا","Ёки улар мулкдан насибадорлар-у, шундай тақдирда ундан одамларга зиғирча ҳам бермайдиларми?!",87,5],["أَمْ يَحْسُدُونَ [h:2848[ٱ][l[ل][g[نّ]َاسَ عَلَىٰ م[o[َآ] ءَاتَ[n[ـٰ]هُمُ [h:2411[ٱ]للَّهُ مِ[f:475[ن ف]َضْلِه[n[ِۦ]‌ۖ فَقَ[q:563[دْ] ءَاتَيْن[o[َآ] ءَالَ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ [h:2849[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:679[ٱ]لْحِكْمَةَ وَءَاتَيْنَ[n[ـٰ]ه[w:2850[ُم م]ُّلْكًا عَظِيمًا","Ёки Аллоҳ одамларга Ўз фазлидан берган нарсаларга ҳасад қилмоқдаларми? Батаҳқиқ, Иброҳим оиласига китобни, ҳикматни ва улуғ мулкни берганмиз-ку?!",87,5],["فَمِنْه[w:1456[ُم م]َّنْ ءَامَنَ بِه[n[ِۦ] وَمِنْه[w:1106[ُم م]َّ[f:2851[ن ص]َدَّ عَنْهُ‌ۚ وَكَفَىٰ بِجَهَ[g[نّ]َمَ سَعِيرًا","Бас, уларнинг ичида унга иймон келтирганлар ҳам бор, ундан юз ўгириб куфр келтирганлар ҳам бор. Жаҳаннам куйдириш азобига кифоя қилур.",87,5],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا سَوْفَ نُصْلِيهِمْ نَا[f:2852[رًا ك]ُلَّمَا نَضِجَتْ جُلُودُه[c:2853[ُم ب]َدَّلْنَ[n[ـٰ]هُمْ جُلُودًا غَيْرَهَا لِيَذُوقُو[s[اْ] [h:2854[ٱ]لْعَذَابَ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَزِيزًا حَكِيمًا","Оятларимизга куфр келтирганларни, албатта, дўзахга киритамиз. Қачонки, терилари етиб пишганда, азобни тортишлари учун бошқа тери алмаштирамиз. Албатта, Аллоҳ азиз ва ҳаким зотдир.",87,5],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ سَنُ[q:2855[دْ]خِلُهُمْ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَ[u:2856[دًا‌ۖ ل]َّهُمْ فِيه[o[َآ] أَزْو[n[َٲ][a:131[جٌ م]ُّطَهَّرَ[a:2857[ةٌ‌ۖ و]َنُ[q:2858[دْ]خِلُهُمْ ظِل[f:2859[اًّ ظ]َلِيلاً","Иймон келтирган ва солиҳ амалларни қилганларни, албатта, остидан анҳорлар оқиб турган жаннатларга киритамиз. Унда абадий боқий қолурлар. Унда уларга покиза жуфтлар бор. Ва уларни қуюқ сояларга киритамиз.",87,5],["۞ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَأْمُرُكُمْ أَ[f:2860[ن ت]ُؤَدُّو[s[اْ] [h:2861[ٱ]لْأَمَ[n[ـٰ]نَ[n[ـٰ]تِ إِلَ[o[ىٰٓ] أَهْلِهَا وَإِذَا حَكَمْت[c:2862[ُم ب]َيْنَ [h:1165[ٱ][l[ل][g[نّ]َاسِ أَ[f:2863[ن ت]َحْكُمُو[s[اْ] بِ[h:1661[ٱ]لْعَ[q:1661[دْ]لِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ نِعِ[g[مّ]َا يَعِظُك[c:1303[ُم ب]ِه[o[ِۦٓ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ سَمِيع[i:2864[َۢا ب]َصِيرًا","Албатта, Аллоҳ сизларга омонатларни ўз аҳлига эриштиришни ва агар одамлар орасида ҳукм қилсангиз, адолат ила ҳукм қилишни амр қиладир. Аллоҳ сизларга қандай ҳам яхши ваъз қилур! Албатта, Аллоҳ эшитувчи ва кўрувчи зотдир.",87,5],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَطِيعُو[s[اْ] [h:1855[ٱ]للَّهَ وَأَطِيعُو[s[اْ] [h:2865[ٱ][l[ل]رَّسُولَ وَأُ[s[وْ]لِى [h:2866[ٱ]لْأَمْرِ مِ[f:344[نك]ُمْ‌ۖ فَإِ[f:2867[ن ت]َنَ[n[ـٰ]زَعْتُمْ فِى ش[f:2868[َىْءٍ ف]َرُدُّوهُ إِلَى [h:1637[ٱ]للَّهِ وَ[h:2421[ٱ][l[ل]رَّسُولِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ‌ۚ ذ[n[َٲ]لِكَ خَيْ[a:2869[رٌ و]َأَحْسَنُ تَأْوِيلاً","Эй иймон келтирганлар! Аллоҳга итоат қилинг, Пайғамбарга ва ўзингиздан бўлган ишбошиларга итоат қилинг. Бирор нарса ҳақида тортишиб қолсангиз, агар Аллоҳ ва охират кунига иймон келтирган бўлсангиз, уни Аллоҳга ва Пайғамбарга қайтаринг. Ана шундай қилиш хайрли ва оқибати яхшидир.",87,5],["أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ يَزْعُمُونَ أَ[g[نّ]َهُمْ ءَامَنُو[s[اْ] بِم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْكَ وَم[o[َآ] أُ[f:17[نز]ِلَ مِ[f:18[ن ق]َ[q:19[بْ]لِكَ يُرِيدُونَ أ[a:2870[َن ي]َتَحَاكَم[o[ُوٓ][s[اْ] إِلَى [h:2871[ٱ][l[ل]طَّ[n[ـٰ]غُوتِ وَقَ[q:387[دْ] أُمِر[o[ُوٓ][s[اْ] أ[a:470[َن ي]َكْفُرُو[s[اْ] بِه[n[ِۦ] وَيُرِيدُ [h:2872[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ أ[a:2873[َن ي]ُضِلَّهُمْ ضَلَ[n[ـٰ]ل[i:2874[اَۢ ب]َعِيدًا","Сенга нозил бўлган нарсага ва сендан олдин нозил бўлган нарсага иймон келтирганларини даъво қилаётганларни кўрмайсанми?! Тоғутдан ҳукм сўраб беришни истайдилар. Ҳолбуки, унга куфр келтиришга буюрилгандир. Шайтон эса, уларни йўлдан бутунлай адаштиришни истайди.",88,5],["وَإِذَا قِيلَ لَهُمْ تَعَالَوْ[s[اْ] إِلَىٰ م[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ وَإِلَى [h:2875[ٱ][l[ل]رَّسُولِ رَأَيْتَ [h:2876[ٱ]لْمُنَ[n[ـٰ]فِقِينَ يَصُدُّونَ عَ[f:626[نك]َ صُدُودًا","Агар уларга: «Аллоҳ нозил қилган нарсага ва Пайғамбар ҳузурига келинглар», дейилса, мунофиқлар сендан тамоман юз ўгирганларини кўрасан.",88,5],["فَكَيْفَ إِذ[o[َآ] أَصَ[n[ـٰ]بَتْه[w:802[ُم م]ُّصِيبَ[i:2877[ةُۢ ب]ِمَا قَدَّمَتْ أَيْدِيهِمْ ثُ[g[مّ]َ ج[o[َا]ٓءُوكَ يَحْلِفُونَ بِ[h:32[ٱ]للَّهِ إِنْ أَرَ[q:2878[دْ]ن[o[َآ] إِلّ[o[َآ] إِحْسَ[n[ـٰ][a:2879[نًا و]َتَوْفِيقًا","Энди қилган нарсалари туфайли уларга мусибат етгандан сўнг сенга келиб, Аллоҳ ила қасам ичиб: «Биз фақат яхшилик ва тавфиқни хоҳлаган эдик», дейишлари қандай бўлди?",88,5],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ يَعْلَمُ [h:2880[ٱ]للَّهُ مَا فِى قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ ف[o[ِىٓ] أَ[f:568[نف]ُسِهِمْ قَوْل[i:2881[اَۢ ب]َلِيغًا","Ана ўшаларнинг қалбларидагини Аллоҳ билади. Бас, уларнинг қилганидан юз ўгир! Уларга ваъз қил! Ёлғиз ўзларига етказиб сўзла!",88,5],["وَم[o[َآ] أَرْسَلْنَا م[u:2882[ِن ر]َّسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ [h:509[ٱ]للَّهِ‌ۚ وَلَوْ أَ[g[نّ]َهُمْ إِ[d:2883[ذ] ظَّلَم[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ ج[o[َا]ٓءُوكَ فَ[h:2248[ٱ]سْتَغْفَرُو[s[اْ] [h:2884[ٱ]للَّهَ وَ[h:2885[ٱ]سْتَغْفَرَ لَهُمُ [h:2886[ٱ][l[ل]رَّسُولُ لَوَجَدُو[s[اْ] [h:2887[ٱ]للَّهَ تَوَّا[u:2646[بًا ر]َّحِيمًا","Қайси бир Пайғамбарни юборган бўлсак, Аллоҳнинг изни ила фақат итоат қилиниши учун юборганмиз. Агар улар ўзларига ўзлари зулм қилган чоғларида ҳузурингга келиб, Аллоҳга истиғфор айтганларида ва Пайғамбар ҳам улар учун истиғфор айтганида эди, албатта, Аллоҳ тавбаларни қабул этувчи ва раҳмли зот эканини топган бўлур эдилар.",88,5],["فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُ[g[مّ]َ لَا يَجِدُو[s[اْ] ف[o[ِىٓ] أَ[f:568[نف]ُسِهِمْ حَرَ[a:2888[جًا م]ِّ[g[مّ]َا قَضَيْتَ وَيُسَلِّمُو[s[اْ] تَسْلِيمًا","Йўқ, Роббингга қасамки, сени ўз ораларида чиққан келишмовчиликларга ҳакам қилмагунларича, кейин, чиқарган ҳукмингга дилларида танглик топмасдан, бутунлай таслим бўлмагунларича, зинҳор мўмин бўла олмаслар!",88,5],["وَلَوْ أَ[g[نّ]َا كَتَ[q:2889[بْ]نَا عَلَيْهِمْ أَنِ [h:2890[ٱ][q:2891[قْ]تُل[o[ُوٓ][s[اْ] أَ[f:221[نف]ُسَكُمْ أَوِ [h:2892[ٱ]خْرُجُو[s[اْ] مِ[f:426[ن د]ِيَ[n[ـٰ]رِك[w:2893[ُم م]َّا فَعَلُوهُ إِلَّا قَلِي[a:2894[لٌ م]ِّنْهُمْ‌ۖ وَلَوْ أَ[g[نّ]َهُمْ فَعَلُو[s[اْ] مَا يُوعَظُونَ بِه[n[ِۦ] لَكَانَ خَيْ[u:2160[رًا ل]َّهُمْ وَأَشَدَّ تَثْبِيتًا","Агар Биз уларга, ўзларингизни ўлдирнг ёки ўзингизни диёрларингиздан чиқаринг, деб фарз қилганимизда, озгиналаридан бошқаси буни қилмас эдилар. Улар ўзларига ваъз қилинган нарсаларни қилганларида эди, ўзларига яхши ва саботлари мустаҳкам бўлар эди.",89,5],["وَإِ[u:2895[ذًا ل]َّأَتَيْنَ[n[ـٰ]ه[w:2896[ُم م]ّ[u:2897[ِن ل]َّدُ[g[نّ][o[َآ] أَ[q:2795[جْ]رًا عَظِيمًا","У ҳолда, Биз ҳам уларга Ўз ҳузуримиздан улуғ ажр берган бўлур эдик.",89,5],["وَلَهَدَيْنَ[n[ـٰ]هُمْ صِر[n[َٲ][a:2898[طًا م]ُّسْتَقِيمًا","Ва уларни тўғри йўлга ҳидоят қилур эдик.",89,5],["وَم[a:2629[َن ي]ُطِعِ [h:2630[ٱ]للَّهَ وَ[h:1856[ٱ][l[ل]رَّسُولَ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مَعَ [h:2899[ٱ]لَّذِينَ أَنْعَمَ [h:2900[ٱ]للَّهُ عَلَيْه[w:2901[ِم م]ِّنَ [h:2902[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ وَ[h:2903[ٱ][l[ل]صِّدِّيقِينَ وَ[h:2904[ٱ][l[ل]شُّهَد[o[َا]ٓءِ وَ[h:2905[ٱ][l[ل]صَّ[n[ـٰ]لِحِينَ‌ۚ وَحَسُنَ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ رَفِيقًا","Ким Аллоҳга ва Расулга итоат қилса, бас, ана ўшалар Аллоҳ неъмат берган набийлар, сиддиқлар, шаҳидлар ва солиҳлар билан биргадирлар. Ва уларнинг рафиқлари қандай ҳам яхши!",89,5],["ذ[n[َٲ]لِكَ [h:2906[ٱ]لْفَضْلُ مِنَ [h:321[ٱ]للَّهِ‌ۚ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ عَلِيمًا","Бу–Аллоҳдан бўлган фазлдир ва билгувчиликда Аллоҳнинг Ўзи кифоя қилур.",89,5],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] خُذُو[s[اْ] حِذْرَكُمْ فَ[h:2907[ٱ][f:2907[نف]ِرُو[s[اْ] ثُبَاتٍ أَوِ [h:2908[ٱ][f:2909[نف]ِرُو[s[اْ] جَمِيعًا","Эй иймон келтирганлар! Ўзингизни ҳушёр тутинг ва гуруҳ-гуруҳ бўлиб қўзғалинг ёки тўп ҳолингизда қўзғалинг!",89,5],["وَإِ[g[نّ]َ مِ[f:344[نك]ُمْ لَم[u:2910[َن ل]َّيُبَطِّئَ[g[نّ]َ فَإِنْ أَصَ[n[ـٰ]بَتْك[w:2394[ُم م]ُّصِيبَ[f:2911[ةٌ ق]َالَ قَ[q:298[دْ] أَنْعَمَ [h:2900[ٱ]للَّهُ عَلَىَّ إِذْ لَمْ أَك[a:2912[ُن م]َّعَهُمْ شَهِيدًا","Албатта, ичингизда ортда қоладиганлар ҳам бор. Агар сизга мусибат етса, у: «Аллоҳ, Ўзи менга неъмат берди, яхшиямки улар билан бирга ҳозир бўлмаганим», дейди.",89,5],["وَلَئِنْ أَصَ[n[ـٰ]بَكُمْ فَضْ[a:2913[لٌ م]ِّنَ [h:321[ٱ]للَّهِ لَيَقُولَ[g[نّ]َ كَأ[u:2914[َن ل]َّمْ تَك[i:2915[ُنۢ ب]َيْنَكُمْ وَبَيْنَهُ[n[ۥ] مَوَدَّ[a:2916[ةٌ ي]َ[n[ـٰ]لَيْتَنِى كُ[f:2917[نت]ُ مَعَهُمْ فَأَفُوزَ فَوْزًا عَظِيمًا","Агар сизга Аллоҳдан фазл етса, худди сиз билан унинг орасида дўстлик бўлмагандек, «Қани эди мен ҳам улар билан бўлганимда, улуғ зафар қозонар эдим», дейди.",89,5],["۞ فَلْيُقَ[n[ـٰ]تِلْ فِى سَبِيلِ [h:788[ٱ]للَّهِ [h:1020[ٱ]لَّذِينَ يَشْرُونَ [h:2918[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَا بِ[h:447[ٱ]لْأَخِرَةِ‌ۚ وَم[a:2919[َن ي]ُقَ[n[ـٰ]تِلْ فِى سَبِيلِ [h:788[ٱ]للَّهِ فَيُ[q:2920[قْ]تَلْ أَوْ يَغْلِ[q:2921[بْ] فَسَوْفَ نُؤْتِيهِ أَ[q:2795[جْ]رًا عَظِيمًا","Охират учун бу дунё ҳаётини сотадиганлар Аллоҳнинг йўлида жанг қилсинлар. Ким Аллоҳнинг йўлида жанг қилиб ўлдирилса ёки ғолиб келса, биз унга, албатта, улуғ ажрни берурмиз.",89,5],["وَمَا لَكُمْ لَا تُقَ[n[ـٰ]تِلُونَ فِى سَبِيلِ [h:788[ٱ]للَّهِ وَ[h:2922[ٱ]لْمُسْتَضْعَفِينَ مِنَ [h:2923[ٱ][l[ل]رِّجَالِ وَ[h:2924[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ وَ[h:2925[ٱ]لْوِلْد[n[َٲ]نِ [h:2926[ٱ]لَّذِينَ يَقُولُونَ رَبَّن[o[َآ] أَخْرِ[q:2927[جْ]نَا مِنْ هَ[n[ـٰ]ذِهِ [h:2928[ٱ]لْقَرْيَةِ [h:2929[ٱ][l[ل]ظَّالِمِ أَهْلُهَا وَ[h:2930[ٱ][q:2930[جْ]عَل لَّنَا م[u:1746[ِن ل]َّدُ[f:1747[نك]َ وَلِي[a:2931[ًّا و]َ[h:2930[ٱ][q:2930[جْ]عَل لَّنَا م[u:1746[ِن ل]َّدُ[f:1747[نك]َ نَصِيرًا","Нима учун Аллоҳнинг йўлида ва: «Эй Роббимиз, бизни аҳли золим шаҳардан чиқаргин, бизга Ўз томонингдан дўст ато қилгин ва Ўз томонингдан нусратчи ато қилгин», деяётган заифҳол эркагу аёл ва болалар йўлида жанг қилмайсизлар?!",90,5],["ٱلَّذِينَ ءَامَنُو[s[اْ] يُقَ[n[ـٰ]تِلُونَ فِى سَبِيلِ [h:788[ٱ]للَّهِ‌ۖ وَ[h:37[ٱ]لَّذِينَ كَفَرُو[s[اْ] يُقَ[n[ـٰ]تِلُونَ فِى سَبِيلِ [h:2932[ٱ][l[ل]طَّ[n[ـٰ]غُوتِ فَقَ[n[ـٰ]تِل[o[ُوٓ][s[اْ] أَوْلِي[o[َا]ٓءَ [h:2933[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ‌ۖ إِ[g[نّ]َ كَيْدَ [h:2934[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ كَانَ ضَعِيفًا","Иймон келтирганлар Аллоҳнинг йўлида жанг қилурлар. Куфр келтирганлар тоғутнинг йўлида жанг қилурлар. Бас, шайтоннинг дўстларига қарши жанг қилинг. Албатта, шайтоннинг ҳийласи заифдир.",90,5],["أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ قِيلَ لَهُمْ كُفّ[o[ُوٓ][s[اْ] أَيْدِيَكُمْ وَأَقِيمُو[s[اْ] [h:214[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتُو[s[اْ] [h:215[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ فَلَ[g[مّ]َا كُتِبَ عَلَيْهِمُ [h:1394[ٱ]لْقِتَالُ إِذَا فَرِي[a:388[قٌ م]ِّنْهُمْ يَخْشَوْنَ [h:2935[ٱ][l[ل][g[نّ]َاسَ كَخَشْيَةِ [h:2936[ٱ]للَّهِ أَوْ أَشَدَّ خَشْيَ[a:2937[ةً‌ۚ و]َقَالُو[s[اْ] رَبَّنَا لِمَ كَتَ[q:2938[بْ]تَ عَلَيْنَا [h:2939[ٱ]لْقِتَالَ لَوْل[o[َآ] أَخَّرْتَن[o[َآ] إِلَ[o[ىٰٓ] أَجَ[f:2940[لٍ ق]َرِي[f:2941[بٍ‌ۗ ق]ُلْ مَتَ[n[ـٰ]عُ [h:2942[ٱ][l[ل]دُّنْيَا قَلِي[a:2943[لٌ و]َ[h:2944[ٱ]لْأَخِرَةُ خَيْ[u:2945[رٌ ل]ِّمَنِ [h:1117[ٱ]تَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلاً","Қўлингизни тийинг, намоз ўқиб, закот беринг, деб айтилган кимсаларни кўрмайсанми?! Уларга уруш фарз қилинганда, бирдан, бир гуруҳлари одамлардан худди Аллоҳдан қўрққандек ёки ундан ҳам қаттиқроқ қўрқишмоқда. Ва: «Эй Роббимиз, бизга урушни нега фарз қилдинг, бир оз ортга суриб турсанг бўлмасмиди?!» демоқдалар. Дунёнинг матоҳи оз, охират эса, тақво қилганларга яхшидир. Ва қилчалик зулм қилинмассизлар», деб айт.",90,5],["أَيْنَمَا تَكُونُو[s[اْ] يُ[q:2946[دْ]رِككُّمُ [h:2947[ٱ]لْمَوْتُ وَلَوْ كُ[f:100[نت]ُمْ فِى بُرُو[a:2948[جٍ م]ُّشَيَّدَ[a:2949[ةٍ‌ۗ و]َإِ[f:2950[ن ت]ُصِ[q:2951[بْ]هُمْ حَسَنَ[a:2952[ةٌ ي]َقُولُو[s[اْ] هَ[n[ـٰ]ذِه[n[ِۦ] مِنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ‌ۖ وَإِ[f:2950[ن ت]ُصِ[q:2951[بْ]هُمْ سَيِّئَ[a:2953[ةٌ ي]َقُولُو[s[اْ] هَ[n[ـٰ]ذِه[n[ِۦ] مِنْ عِ[f:2954[ند]ِكَ‌ۚ قُلْ كُ[a:1744[لٌّ م]ِّنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ‌ۖ فَمَالِ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ [h:2955[ٱ]لْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًا","Қаерда бўлсангиз ҳам, ҳаттоки мустаҳкам қалъаларда бўлсангиз ҳам, ўлим сизни топадир. Агар уларга яхшилик етса, бу Аллоҳдан, дерлар. Ёмонлик етганда эса, бу сендан дерлар. «Ҳаммаси Аллоҳдан», деб айт! Анави қавмларга нима бўлдики, гапни тушунай демайдилар?!",90,5],["مّ[o[َآ] أَصَابَكَ مِنْ حَسَنَ[f:2956[ةٍ ف]َمِنَ [h:2957[ٱ]للَّهِ‌ۖ وَم[o[َآ] أَصَابَكَ مِ[f:2958[ن س]َيِّئَ[f:2959[ةٍ ف]َم[a:2960[ِن ن]َّفْسِكَ‌ۚ وَأَرْسَلْنَ[n[ـٰ]كَ لِل[g[نّ]َاسِ رَسُول[a:2961[اً‌ۚ و]َكَفَىٰ بِ[h:32[ٱ]للَّهِ شَهِيدًا","Сенга етган яхшилик Аллоҳдандир. Ва сенга етган ёмонлик ўзингдандир. Биз сени одамларга Пайғамбар қилиб юбордик. Шоҳидликка Аллоҳнинг Ўзи кифоя қилур.",90,5],["مّ[a:2962[َن ي]ُطِعِ [h:2963[ٱ][l[ل]رَّسُولَ فَقَ[q:563[دْ] أَطَاعَ [h:2964[ٱ]للَّهَ‌ۖ وَمَ[f:2965[ن ت]َوَلَّىٰ فَم[o[َآ] أَرْسَلْنَ[n[ـٰ]كَ عَلَيْهِمْ حَفِيظًا","Ким Пайғамбарга итоат қилса, Аллоҳга итоат қилган бўлади. Ким юз ўгирса, Биз сени уларга қўриқчи қилиб юборганимиз йўқ.",91,5],["وَيَقُولُونَ طَاعَ[f:2966[ةٌ ف]َإِذَا بَرَزُو[s[اْ] مِنْ عِ[f:2954[ند]ِكَ بَيَّتَ ط[o[َا]ٓئِفَ[a:2967[ةٌ م]ِّنْهُمْ غَيْرَ [h:287[ٱ]لَّذِى تَقُولُ‌ۖ وَ[h:72[ٱ]للَّهُ يَكْتُبُ مَا يُبَيِّتُونَ‌ۖ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى [h:412[ٱ]للَّهِ‌ۚ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ وَكِيلاً","Улар, итоат, дерлар. Ҳузурингдан чиққач эса, бир тоифалари айтганингдан бошқага хуфёна тил бириктирадилар. Аллоҳ хуфёна тил бириктирган нарсаларини ёзиб қўяди. Бас, улардан юз ўгир ва Аллоҳга таваккал қил. Вакилликка Аллоҳнинг Ўзи кифоя қилур.",91,5],["أَفَلَا يَتَدَبَّرُونَ [h:2968[ٱ]لْقُرْءَانَ‌ۚ وَلَوْ كَانَ مِنْ عِ[f:398[ند]ِ غَيْرِ [h:2969[ٱ]للَّهِ لَوَجَدُو[s[اْ] فِيهِ [h:2970[ٱ]خْتِلَ[n[ـٰ][f:2971[فًا ك]َثِيرًا","Қуръонни тадаббур этиб кўрмайдиларми?! Агар у Аллоҳдан бошқанинг ҳузуридан бўлганда, ундан кўп ихтилофлар топар эдилар.",91,5],["وَإِذَا ج[o[َا]ٓءَهُمْ أَمْ[a:2972[رٌ م]ِّنَ [h:2973[ٱ]لْأَمْنِ أَوِ [h:2974[ٱ]لْخَوْفِ أَذَاعُو[s[اْ] بِه[n[ِۦ]‌ۖ وَلَوْ رَدُّوهُ إِلَى [h:2975[ٱ][l[ل]رَّسُولِ وَإِلَ[o[ىٰٓ] أُ[s[وْ]لِى [h:2976[ٱ]لْأَمْرِ مِنْهُمْ لَعَلِمَهُ [h:2977[ٱ]لَّذِينَ يَسْتَ[i:2978[نۢب]ِطُونَهُ[n[ۥ] مِنْهُمْ‌ۗ وَلَوْلَا فَضْلُ [h:337[ٱ]للَّهِ عَلَيْكُمْ وَرَحْمَتُهُ[n[ۥ] لَ[h:2979[ٱ]تَّبَعْتُمُ [h:2980[ٱ][l[ل]شَّيْطَ[n[ـٰ]نَ إِلَّا قَلِيلاً","Қачонки уларга эминлик ёки ҳақ тўғрисида бир иш–хабар етса, уни таратадилар. Агар уни Пайғамбарга ва ўзларидан бўлган ишбошиларга ҳавола қилганларида эди, улардан иш негизини биладиганлари уни англаб етар эдилар. Аллоҳнинг фазли ва марҳамати бўлмаганда, озгинангиздан бошқангиз шайтонга эргашиб кетар эдингиз.",91,5],["فَقَ[n[ـٰ]تِلْ فِى سَبِيلِ [h:788[ٱ]للَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ‌ۚ وَحَرِّضِ [h:2981[ٱ]لْمُؤْمِنِينَ‌ۖ عَسَى [h:2982[ٱ]للَّهُ أ[a:2983[َن ي]َكُفَّ بَأْسَ [h:2984[ٱ]لَّذِينَ كَفَرُو[s[اْ‌ۚ] وَ[h:72[ٱ]للَّهُ أَشَدُّ بَأْ[a:2985[سًا و]َأَشَدُّ تَ[f:2986[نك]ِيلاً","Аллоҳнинг йўлида жанг қил! Ўзингдан бошқадан масъул қилинмайсан. Мўминларни қизиқтир. Шоядки Аллоҳ куфр келтирганларнинг шиддатини даф қилса. Аллоҳ шиддати қаттиқ ва азоби ортиқ зотдир.",91,5],["مّ[a:2987[َن ي]َشْفَعْ شَفَ[n[ـٰ]عَةً حَسَنَ[a:2988[ةً ي]َك[u:2596[ُن ل]َّهُ[n[ۥ] نَصِي[a:2989[بٌ م]ِّنْهَا‌ۖ وَم[a:2990[َن ي]َشْفَعْ شَفَ[n[ـٰ]عَ[f:2991[ةً س]َيِّئَ[a:2992[ةً ي]َك[u:2596[ُن ل]َّهُ[n[ۥ] كِفْ[a:2993[لٌ م]ِّنْهَا‌ۗ وَكَانَ [h:2653[ٱ]للَّهُ عَلَىٰ كُلِّ ش[a:2994[َىْءٍ م]ُّقِيتًا","Ким яхши шафоат қилса, ундан ўз насибаси бўлур. Ким ёмон шафоат қилса, ундан ўз наибаси бўлур. Аллоҳ ҳар бир нарсанинг баҳосини берувчи зотдир.",91,5],["وَإِذَا حُيِّيت[c:2995[ُم ب]ِتَحِيَّ[f:2996[ةٍ ف]َحَيُّو[s[اْ] بِأَحْسَنَ مِنْه[o[َآ] أَوْ رُدُّوه[o[َآ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا","Қачонки сизга бир саломлашиш ила салом берилса, сиз ундан кўра яхшироқ алик олинг ёки худди ўзидек жавоб беринг. Албатта, Аллоҳ ҳар бир нарсанинг ҳисобини олувчи зотдир.",91,5],["ٱللَّهُ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۚ لَيَ[q:2997[جْ]مَعَ[g[نّ]َكُمْ إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ لَا رَيْبَ فِيهِ‌ۗ وَمَنْ أَصْدَقُ مِنَ [h:321[ٱ]للَّهِ حَدِيثًا","Аллоҳдан ўзга ибодатга сазовор зот йўқ. У сизларни қоим бўлишида ҳеч шубҳа йўқ қиёмат куни, албатта, жамлар. Ким Аллоҳдан кўра ростгўйроқ?!.",92,5],["۞ فَمَا لَكُمْ فِى [h:2998[ٱ]لْمُنَ[n[ـٰ]فِقِينَ فِئَتَيْنِ وَ[h:72[ٱ]للَّهُ أَرْكَسَه[c:2999[ُم ب]ِمَا كَسَب[o[ُوٓ[s[اْ]‌ۚ] أَتُرِيدُونَ أَ[f:3000[ن ت]َهْدُو[s[اْ] مَنْ أَضَلَّ [h:3001[ٱ]للَّهُ‌ۖ وَم[a:3002[َن ي]ُضْلِلِ [h:3003[ٱ]للَّهُ فَلَ[f:2843[ن ت]َجِدَ لَهُ[n[ۥ] سَبِيلاً","Сизга нима бўлдики, мунофиқлар ҳақида иккига бўлинасизлар, ҳолбуки, Аллоҳ уларни расво қилиб қўйди-ку? Аллоҳ адаштирган кимсаларни ҳидоят қилмоқчи бўласизларми? Аллоҳ кимни адаштирган бўлса, унга йўл топа олмассан.",92,5],["وَدُّو[s[اْ] لَوْ تَكْفُرُونَ كَمَا كَفَرُو[s[اْ] فَتَكُونُونَ سَو[o[َا]ٓ[f:3004[ءً‌ۖ ف]َلَا تَتَّخِذُو[s[اْ] مِنْهُمْ أَوْلِي[o[َا]ٓءَ حَتَّىٰ يُهَاجِرُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ‌ۚ فَإِ[f:1857[ن ت]َوَلَّوْ[s[اْ] فَخُذُوهُمْ وَ[h:1022[ٱ][q:1022[قْ]تُلُوهُمْ حَيْثُ وَجَ[d:3005[د]تُّمُوهُمْ‌ۖ وَلَا تَتَّخِذُو[s[اْ] مِنْهُمْ وَلِي[a:3006[ًّا و]َلَا نَصِيرًا","Улар сиз ҳам худди ўзларидек кофир бўлиб, уларга тенглашишингизни хоҳларлар. Токи Аллоҳ йўлида ҳижрат қилмагунларича, улардан дўст тутманг. Агар юз ўгириб кетсалар, бас, уларни тутинглар ва қаерда топсангиз, ўлдиринглар. Улардан дўст ҳам, ёрдамчи ҳам тутманг.",92,5],["إِلَّا [h:778[ٱ]لَّذِينَ يَصِلُونَ إِلَىٰ قَوْ[i:3007[مِۭ ب]َيْنَكُمْ وَبَيْنَه[w:3008[ُم م]ِّيثَ[n[ـٰ]قٌ أَوْ ج[o[َا]ٓءُوكُمْ حَصِرَتْ صُدُورُهُمْ أ[a:3009[َن ي]ُقَ[n[ـٰ]تِلُوكُمْ أَوْ يُقَ[n[ـٰ]تِلُو[s[اْ] قَوْمَهُمْ‌ۚ وَلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَ[n[ـٰ]تَلُوكُمْ‌ۚ فَإِنِ [h:3010[ٱ]عْتَزَلُوكُمْ فَلَمْ يُقَ[n[ـٰ]تِلُوكُمْ وَأَلْقَوْ[s[اْ] إِلَيْكُمُ [h:3011[ٱ][l[ل]سَّلَمَ فَمَا جَعَلَ [h:2556[ٱ]للَّهُ لَكُمْ عَلَيْهِمْ سَبِيلاً","Магар, сиз билан орасида аҳднома бор қавмга етиб борсалар ёки сизлар билан ҳам, ўз қавмлари билан ҳам урушиш кўнгилларига сиғмасдан ҳузурингизга келсалар майли. Аллоҳ хоҳлаганида, уларни сиздан устун қилиб қўярди ва улар сизларга қарши уруш қилардилар. Агар сиздан четлансалар ва сиз билан урушмасдан тинчликни таклиф қилсалар, Аллоҳ сизларга уларнинг зиддига йўл бермас.",92,5],["سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أ[a:3012[َن ي]َأْمَنُوكُمْ وَيَأْمَنُو[s[اْ] قَوْمَهُمْ كُلَّ مَا رُدّ[o[ُوٓ][s[اْ] إِلَى [h:3013[ٱ]لْفِتْنَةِ أُرْكِسُو[s[اْ] فِيهَا‌ۚ فَإ[u:110[ِن ل]َّمْ يَعْتَزِلُوكُمْ وَيُلْق[o[ُوٓ][s[اْ] إِلَيْكُمُ [h:3011[ٱ][l[ل]سَّلَمَ وَيَكُفّ[o[ُوٓ][s[اْ] أَيْدِيَهُمْ فَخُذُوهُمْ وَ[h:1022[ٱ][q:1022[قْ]تُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ‌ۚ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَ[n[ـٰ][a:3014[نًا م]ُّبِينًا","Сиздан ҳам, ўз қавмларидан ҳам омонда бўлишни хоҳлайдиган, фитнага қайтарилган чоғларида унга шўнғийдиган бошқа бирларни ҳам кўрасизлар. Агар сиздан четланмасалар, сизга тинчликни таклиф қилмасалар ва қўлларини тиймасалар, бас, уларни тутинг ва қаерда топсангиз, ўлдиринг. Ана ўшандайлар устидан сизга очиқ ҳақ бердик.",92,5],["وَمَا كَانَ لِمُؤْمِنٍ أ[a:3015[َن ي]َ[q:3016[قْ]تُلَ مُؤْمِنًا إِلَّا خَطَـ[a:3017[ـًٔا‌ۚ و]َمَ[f:3018[ن ق]َتَلَ مُؤْمِنًا خَطَـ[f:3019[ـًٔا ف]َتَحْرِيرُ رَقَبَ[a:3020[ةٍ م]ُّؤْمِنَ[a:3021[ةٍ و]َدِيَ[a:3022[ةٌ م]ُّسَلَّمَةٌ إِلَ[o[ىٰٓ] أَهْلِه[o[ِۦٓ] إِلّ[o[َآ] أ[a:3023[َن ي]َصَّدَّقُو[s[اْ‌ۚ] فَإِ[f:1670[ن ك]َانَ مِ[f:3024[ن ق]َوْمٍ عَدُ[u:3025[وٍّ ل]َّكُمْ وَهُوَ مُؤْمِ[f:3026[نٌ ف]َتَحْرِيرُ رَقَبَ[a:3020[ةٍ م]ُّؤْمِنَ[a:3027[ةٍ‌ۖ و]َإِ[f:1649[ن ك]َانَ مِ[f:3024[ن ق]َوْ[i:3007[مِۭ ب]َيْنَكُمْ وَبَيْنَه[w:3008[ُم م]ِّيثَ[n[ـٰ][f:3028[قٌ ف]َدِيَ[a:3029[ةٌ م]ُّسَلَّمَةٌ إِلَ[o[ىٰٓ] أَهْلِه[n[ِۦ] وَتَحْرِيرُ رَقَبَ[a:3020[ةٍ م]ُّؤْمِنَ[f:3030[ةٍ‌ۖ ف]َم[u:1066[َن ل]َّمْ يَجِ[q:1067[دْ] فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَ[a:3031[ةً م]ِّنَ [h:321[ٱ]للَّهِ‌ۗ وَكَانَ [h:2653[ٱ]للَّهُ عَلِيمًا حَكِيمًا","Мўмин мўминни ўлдирмас. Магар билмасдан қилиши мумкин. Кимки мўминни билмасдан ўлдириб қўйса, бас, унга мўмин қулни озод қилиш ва аҳли кечирмасалар, хун бериш вожиб бўлур. Агар у сизга душман қавмдан бўлиб, ўзи мўмин бўлса, мўмин қулни озод қилиш вожиб бўлур. Агар у сиз билан орасида аҳдномаси бор қавмдан бўлса, аҳлига бериладиган хун ва мўмин қулни озод қилиш вожиб бўлур. Ким топмаса, Аллоҳга тавба учун кетма-кет икки ой рўза тутиш вожиб бўлур. Аллоҳ билувчи ва ҳикматли зотдир.",93,5],["وَم[a:3032[َن ي]َ[q:3033[قْ]تُلْ مُؤْمِ[a:3034[نًا م]ُّتَعَ[g[مّ]ِ[f:3035[دًا ف]َجَز[o[َا]ٓؤُهُ[n[ۥ] جَهَ[g[نّ]َمُ خَ[n[ـٰ]لِ[f:2636[دًا ف]ِيهَا وَغَضِبَ [h:3036[ٱ]للَّهُ عَلَيْهِ وَلَعَنَهُ[n[ۥ] وَأَعَدَّ لَهُ[n[ۥ] عَذَابًا عَظِيمًا","Ким бир мўминни қасддан ўлдирса, унинг жазоси жаҳаннамдир. Унда абадий қолур. Унга Аллоҳнинг ғазаби ва лаънати ёғилур. Ва Аллоҳ унга улкан азобни тайёрлагандир.",93,5],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا ضَرَ[q:3037[بْ]تُمْ فِى سَبِيلِ [h:788[ٱ]للَّهِ فَتَبَيَّنُو[s[اْ] وَلَا تَقُولُو[s[اْ] لِمَنْ أَلْقَ[o[ىٰٓ] إِلَيْكُمُ [h:3038[ٱ][l[ل]سَّلَ[n[ـٰ]مَ لَسْتَ مُؤْمِ[f:3039[نًا ت]َ[q:3040[بْ]تَغُونَ عَرَضَ [h:3041[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا فَعِ[f:3042[ند]َ [h:3043[ٱ]للَّهِ مَغَانِمُ كَثِيرَ[f:3044[ةٌ‌ۚ ك]َذ[n[َٲ]لِكَ كُ[f:100[نت][w:1096[ُم م]ِّ[f:128[ن ق]َ[q:129[بْ]لُ فَمَ[g[نّ]َ [h:3045[ٱ]للَّهُ عَلَيْكُمْ فَتَبَيَّن[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا","Эй иймон келтирганлар! Аллоҳнинг йўлида жиҳодга чиқсангиз, аниқлаб олинглар ва сизга салом берган кимсага, мўмин эмассан, деманглар. Бу дунё ҳаётининг ўткинчи ўлжасини истайсизлар, Аллоҳнинг ҳузурида эса кўплаб ўлжалар бор. Авваллари сиз ҳам шундай эдингиз, Аллоҳ сизга неъмат берди. Бас, аниқлаб олинг. Албатта, Аллоҳ нима қилаётганингиздан хабардордир.",93,5],["لَّا يَسْتَوِى [h:3046[ٱ]لْقَ[n[ـٰ]عِدُونَ مِنَ [h:3047[ٱ]لْمُؤْمِنِينَ غَيْرُ أُ[s[وْ]لِى [h:3048[ٱ][l[ل]ضَّرَرِ وَ[h:3049[ٱ]لْمُجَ[n[ـٰ]هِدُونَ فِى سَبِيلِ [h:788[ٱ]للَّهِ بِأَمْو[n[َٲ]لِهِمْ وَأَ[f:3050[نف]ُسِهِمْ‌ۚ فَضَّلَ [h:2745[ٱ]للَّهُ [h:3051[ٱ]لْمُجَ[n[ـٰ]هِدِينَ بِأَمْو[n[َٲ]لِهِمْ وَأَ[f:3050[نف]ُسِهِمْ عَلَى [h:3052[ٱ]لْقَ[n[ـٰ]عِدِينَ دَرَجَ[a:3053[ةً‌ۚ و]َكُل[a:3054[اًّ و]َعَدَ [h:3055[ٱ]للَّهُ [h:3056[ٱ]لْحُسْنَىٰ‌ۚ وَفَضَّلَ [h:3057[ٱ]للَّهُ [h:3051[ٱ]لْمُجَ[n[ـٰ]هِدِينَ عَلَى [h:3052[ٱ]لْقَ[n[ـٰ]عِدِينَ أَ[q:2795[جْ]رًا عَظِيمًا","Мўминлардан бешикаст бўла туриб ўтириб қолганлари билан Аллоҳнинг йўлида моллари ва жонлари ила жиҳод қилувчилари баробар бўлмаслар. Аллоҳ моллари ва жонлари билан жиҳод қилувчиларнинг даражасини ўтириб қолувчилардан афзал қилди. Аллоҳ ҳаммага яхшиликни ваъда қилган. Аллоҳ мужоҳидларни ўтириб қолувчилардан улуғ ажр ила, афзал қилган.",94,5],["دَرَجَ[n[ـٰ][a:3058[تٍ م]ِّنْهُ وَمَغْفِرَ[a:3059[ةً و]َرَحْمَ[a:3060[ةً‌ۚ و]َكَانَ [h:2653[ٱ]للَّهُ غَفُو[u:2701[رًا ر]َّحِيمًا","Ўзидан бўлган даражалар ила, мағфират ва раҳмат ила. Ва Аллоҳ мағфират қилувчи ва раҳмли зотдир.",94,5],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ تَوَفَّ[n[ـٰ]هُمُ [h:3061[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ ظَالِم[o[ِىٓ] أَ[f:568[نف]ُسِهِمْ قَالُو[s[اْ] فِيمَ كُ[f:100[نت]ُمْ‌ۖ قَالُو[s[اْ] كُ[g[نّ]َا مُسْتَضْعَفِينَ فِى [h:44[ٱ]لْأَرْضِ‌ۚ قَال[o[ُوٓ][s[اْ] أَلَمْ تَكُنْ أَرْضُ [h:3062[ٱ]للَّهِ و[n[َٲ]سِعَ[f:3063[ةً ف]َتُهَاجِرُو[s[اْ] فِيهَا‌ۚ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مَأْوَ[n[ٮٰ]هُمْ جَهَ[g[نّ]َمُ‌ۖ وَس[o[َا]ٓءَتْ مَصِيرًا","Ўзига зулм қилувчи ҳолида жони олинаётганларга фаришталар: «Нима қилаётган эдинглар?» дерлар. Улар: «Ер юзида бечора эдик», дерлар. Алар: «Аллоҳнинг ери кенг эди-ку, ҳижрат қилсангиз бўлмасмиди?!» дерлар. Ана ўшаларнинг жойи жаҳаннамдир. У қандай ҳам ёмон жой!",94,5],["إِلَّا [h:3064[ٱ]لْمُسْتَضْعَفِينَ مِنَ [h:2923[ٱ][l[ل]رِّجَالِ وَ[h:2924[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ وَ[h:2925[ٱ]لْوِلْد[n[َٲ]نِ لَا يَسْتَطِيعُونَ حِيلَ[a:3065[ةً و]َلَا يَهْتَدُونَ سَبِيلاً","Фақат эркаклар, аёллар ва болалардан иборат, ҳийлага қодир бўлмаган, йўлни топа олмаган бечораларгина бундан мустасно.",94,5],["فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ عَسَى [h:2982[ٱ]للَّهُ أ[a:3066[َن ي]َعْفُوَ عَنْهُمْ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ عَفُوًّا غَفُورًا","Ана ўшалар, шоядки, Аллоҳ уларни афв этса. Зотан, Аллоҳ афв этувчи ва мағфират қилувчи зотдир.",94,5],["۞ وَم[a:3067[َن ي]ُهَاجِرْ فِى سَبِيلِ [h:788[ٱ]للَّهِ يَجِ[q:1067[دْ] فِى [h:44[ٱ]لْأَرْضِ مُر[n[َٲ]غَ[f:3068[مًا ك]َثِي[a:3069[رًا و]َسَعَ[a:3070[ةً‌ۚ و]َم[a:3071[َن ي]َخْرُ[q:3072[جْ] م[i:3073[ِنۢ ب]َيْتِه[n[ِۦ] مُهَاجِرًا إِلَى [h:1637[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] ثُ[g[مّ]َ يُ[q:3074[دْ]رِكْهُ [h:3075[ٱ]لْمَوْتُ فَقَ[q:563[دْ] وَقَعَ أَ[q:582[جْ]رُهُ[n[ۥ] عَلَى [h:412[ٱ]للَّهِ‌ۗ وَكَانَ [h:2653[ٱ]للَّهُ غَفُو[u:2701[رًا ر]َّحِيمًا","Ким Аллоҳнинг йўлида ҳижрат қилса, ер юзида кўпгина паноҳгоҳлар ва кенгчилик топади. Ким уйидан Аллоҳ ва Расулга ҳижрат қилиб чиқса-ю, сўнгра унга ўлим етса, албатта, унинг ажри Аллоҳ зиммасига тушади. Ва Аллоҳ мағфират қилувчи ва раҳмли зотдир.",94,5],["وَإِذَا ضَرَ[q:3037[بْ]تُمْ فِى [h:44[ٱ]لْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَ[f:3076[ن ت]َ[q:3077[قْ]صُرُو[s[اْ] مِنَ [h:3078[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ إِنْ خِفْتُمْ أ[a:3079[َن ي]َفْتِنَكُمُ [h:3080[ٱ]لَّذِينَ كَفَر[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َ [h:3081[ٱ]لْكَ[n[ـٰ]فِرِينَ كَانُو[s[اْ] لَكُمْ عَدُو[a:3082[ًّا م]ُّبِينًا","Ер юзида жавлон урганингизда, куфр келтирганлар сизга фитна қилишидан хавф қилсангиз, намозни қаср қилиб адо этмоғингизда гуноҳ йўқдир. Албатта, кофирлар сизга очиқ душмандирлар.",94,5],["وَإِذَا كُ[f:735[نت]َ فِيهِمْ فَأَقَمْتَ لَهُمُ [h:3083[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ فَلْتَقُمْ ط[o[َا]ٓئِفَ[a:2967[ةٌ م]ِّنْه[w:3084[ُم م]َّعَكَ وَلْيَأْخُذ[o[ُوٓ][s[اْ] أَسْلِحَتَهُمْ فَإِذَا سَجَدُو[s[اْ] فَلْيَكُونُو[s[اْ] م[a:3085[ِن و]َر[o[َا]ٓئِكُمْ وَلْتَأْتِ ط[o[َا]ٓئِفَةٌ أُخْرَىٰ لَمْ يُصَلُّو[s[اْ] فَلْيُصَلُّو[s[اْ] مَعَكَ وَلْيَأْخُذُو[s[اْ] حِذْرَهُمْ وَأَسْلِحَتَهُمْ‌ۗ وَدَّ [h:3086[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْك[w:3087[ُم م]َّيْلَ[a:3088[ةً و][n[َٲ]حِدَ[a:3089[ةً‌ۚ و]َلَا جُنَاحَ عَلَيْكُمْ إِ[f:2594[ن ك]َانَ بِكُمْ أَ[a:1056[ذًى م]ّ[a:3090[ِن م]َّطَرٍ أَوْ كُ[f:100[نت][w:2804[ُم م]َّرْضَ[o[ىٰٓ] أَ[f:3091[ن ت]َضَع[o[ُوٓ][s[اْ] أَسْلِحَتَكُمْ‌ۖ وَخُذُو[s[اْ] حِذْرَكُمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ أَعَدَّ لِلْكَ[n[ـٰ]فِرِينَ عَذَا[a:2783[بًا م]ُّهِينًا","Улар ичида бўлсанг-у, намоз адо қилмоқчи бўлсанг, улардан бир тоифаси сен билан турсин ва силоҳларини ўзлари билан олсинлар. Сажда қилганларидан кейин орқангизга ўтсинлар. Намоз ўқимаган бошқа тоифа келиб сен билан намоз ўқисин. Эҳтиёт бўлиб, силоҳларини ўзлари билан олсинлар. Куфр келтирганлар силоҳларингиз ва матоҳларингиздан ғофил бўлсангиз, устингиздан бирдан ҳамла қилишни истарлар. Ёмғирдан озор етса ёки бемор бўлсангиз, силоҳларингизни қўймоғингизда гуноҳ йўқдир. Xушёр бўлинглар! Албатта, Аллоҳ кофирларга хорловчи азоб тайёрлагандир.",95,5],["فَإِذَا قَضَيْتُمُ [h:3092[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ فَ[h:1091[ٱ]ذْكُرُو[s[اْ] [h:1092[ٱ]للَّهَ قِيَ[n[ـٰ][a:2498[مًا و]َقُعُو[a:2499[دًا و]َعَلَىٰ جُنُوبِكُمْ‌ۚ فَإِذَا [h:3093[ٱ][q:3094[طْ]مَأْنَ[f:3094[نت]ُمْ فَأَقِيمُو[s[اْ] [h:3095[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ‌ۚ إِ[g[نّ]َ [h:3096[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ كَانَتْ عَلَى [h:2329[ٱ]لْمُؤْمِنِينَ كِتَ[n[ـٰ][a:3097[بًا م]َّوْقُوتًا","Намозни адо этганингиздан сўнг Аллоҳни турган, ўтирган ва ёнбошлаган ҳолингизда эсланг. Хотиржам бўлганингизда намозни тўлиқ адо этинг. Албатта, намоз мўминларга вақтида фарз қилингандир.",95,5],["وَلَا تَهِنُو[s[اْ] فِى [h:3098[ٱ][q:3099[بْ]تِغ[o[َا]ٓءِ [h:3100[ٱ]لْقَوْمِ‌ۖ إِ[f:3101[ن ت]َكُونُو[s[اْ] تَأْلَمُونَ فَإِ[g[نّ]َهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ‌ۖ وَتَرْجُونَ مِنَ [h:321[ٱ]للَّهِ مَا لَا يَرْجُونَ‌ۗ وَكَانَ [h:2653[ٱ]للَّهُ عَلِيمًا حَكِيمًا","У қавмни қувишда бўш келманг. Агар алам чекаётган бўлсангиз, улар ҳам сиз алам чекаётганингиздек алам чекмоқдалар. Сиз эса, Аллоҳдан улар умид қилмаган нарсани умид қилмоқдасиз. Аллоҳ билувчи ва ҳикматли зотдир.",95,5],["إِ[g[نّ][o[َآ] أَ[f:515[نز]َلْن[o[َآ] إِلَيْكَ [h:3102[ٱ]لْكِتَ[n[ـٰ]بَ بِ[h:370[ٱ]لْحَقِّ لِتَحْكُمَ بَيْنَ [h:1165[ٱ][l[ل][g[نّ]َاسِ بِم[o[َآ] أَرَ[n[ٮٰ]كَ [h:3103[ٱ]للَّهُ‌ۚ وَلَا تَك[u:3104[ُن ل]ِّلْخ[o[َا]ٓئِنِينَ خَصِيمًا","Албатта, Биз сенга китобни ҳақ ила одамлар орасида сенга Аллоҳ кўрсатганига ҳукм қилишинг учун туширдик. Сен хоинларнинг ёнини олувчи бўлма!",95,5],["وَ[h:9999[ٱ]سْتَغْفِرِ [h:3105[ٱ]للَّهَ‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ غَفُو[u:2701[رًا ر]َّحِيمًا","Аллоҳга истиғфор айт! Албатта, Аллоҳ мағфиратли ва раҳмли зотдир.",96,5],["وَلَا تُجَ[n[ـٰ]دِلْ عَنِ [h:3106[ٱ]لَّذِينَ يَخْتَانُونَ أَ[f:38[نف]ُسَهُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُحِبُّ مَ[f:506[ن ك]َانَ خَوَّانًا أَثِيمًا","Ўз жонларига хиёнат қиладиганларни мудофаа қилма. Албатта, Аллоҳ хиёнатчи ва гуноҳкор бўлган кимсани хуш кўрмас.",96,5],["يَسْتَخْفُونَ مِنَ [h:721[ٱ][l[ل][g[نّ]َاسِ وَلَا يَسْتَخْفُونَ مِنَ [h:321[ٱ]للَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ [h:3107[ٱ]لْقَوْلِ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ بِمَا يَعْمَلُونَ مُحِيطًا","Одамлардан яширадилар ва Аллоҳдан яшира олмаслар. Xолбуки, У Ўзи рози бўлмайдиган гапни хуфёна келишаётганларида ҳам улар ила биргадир. Ва Аллоҳ улар қилаётган амалларни ихота қилувчи зотдир.",96,5],["هَ[o[ـٰٓ]أَ[f:1998[نت]ُمْ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ جَ[n[ـٰ]دَلْتُمْ عَنْهُمْ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا فَم[a:3108[َن ي]ُجَ[n[ـٰ]دِلُ [h:3109[ٱ]للَّهَ عَنْهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ أ[w:3110[َم م]ّ[a:3111[َن ي]َكُونُ عَلَيْهِمْ وَكِيلاً","Ҳой, сизлар! Бу ҳаёти дунёда уларнинг ёнини олдингиз. Қиёмат кунида Аллоҳ олдида уларнинг ёнини ким олади ёки ким уларга вакил бўлади?!.",96,5],["وَم[a:3112[َن ي]َعْمَلْ س[o[ُو]ٓءًا أَوْ يَظْلِمْ نَفْسَهُ[n[ۥ] ثُ[g[مّ]َ يَسْتَغْفِرِ [h:3113[ٱ]للَّهَ يَجِدِ [h:3114[ٱ]للَّهَ غَفُو[u:2701[رًا ر]َّحِيمًا","Ким ёмонлик қилса ёки ўзига зулм этса, сўнгра Аллоҳга истиғфор айтса, Аллоҳни мағфиратли ва раҳмли зот топади.",96,5],["وَم[a:3115[َن ي]َكْسِ[q:3116[بْ] إِثْ[f:3117[مًا ف]َإِ[g[نّ]َمَا يَكْسِبُهُ[n[ۥ] عَلَىٰ نَفْسِه[n[ِۦ]‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ عَلِيمًا حَكِيمًا","Ким гуноҳ қилса, фақатгина ўз зарарига қилади. Ва Аллоҳ билувчи ва ҳикматли зотдир.",96,5],["وَم[a:3115[َن ي]َكْسِ[q:3116[بْ] خَطِ[o[يٓ]ــَٔةً أَوْ إِثْ[f:3118[مًا ث]ُ[g[مّ]َ يَرْمِ بِه[n[ِۦ] بَرِ[o[يٓ]ـ[f:3119[ـًٔا ف]َقَدِ [h:3120[ٱ]حْتَمَلَ بُهْتَ[n[ـٰ][a:2678[نًا و]َإِثْ[a:2679[مًا م]ُّبِينًا","Ким хато ёки гуноҳ қилса-ю, сўнгра уни беайбга ағдарса, шубҳасиз, бўҳтон ва очиқ гуноҳни ўз бўйнига олибди.",96,5],["وَلَوْلَا فَضْلُ [h:337[ٱ]للَّهِ عَلَيْكَ وَرَحْمَتُهُ[n[ۥ] لَهَ[g[مّ]َ[d:3121[ت] طّ[o[َا]ٓئِفَ[a:2967[ةٌ م]ِّنْهُمْ أ[a:3122[َن ي]ُضِلُّوكَ وَمَا يُضِلُّونَ إِلّ[o[َآ] أَ[f:38[نف]ُسَهُمْ‌ۖ وَمَا يَضُرُّونَكَ مِ[f:2103[ن ش][a:3123[َىْءٍ‌ۚ و]َأَ[f:91[نز]َلَ [h:3124[ٱ]للَّهُ عَلَيْكَ [h:1723[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:679[ٱ]لْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُ[f:3125[ن ت]َعْلَمُ‌ۚ وَكَانَ فَضْلُ [h:337[ٱ]للَّهِ عَلَيْكَ عَظِيمًا","Агар сенга Аллоҳнинг фазли ва раҳмати бўлмаганида, улардан бир тоифаси сени адаштиришга уринган эдилар. Улар фақат ўзларини адаштирадилар, холос. Сенга ҳеч зарар етказа олмайдилар. Аллоҳ сенга китобни ва ҳикматни туширди ҳамда билмаган нарсангни билдирди. Ва сенга Аллоҳнинг фазли улуғ бўлди.",96,5],["۞ لَّا خَيْرَ فِى كَثِي[a:3126[رٍ م]ّ[a:3127[ِن ن]َّ[q:3128[جْ]وَ[n[ٮٰ]هُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَ[n[ـٰ][i:3129[حِۭ ب]َيْنَ [h:1165[ٱ][l[ل][g[نّ]َاسِ‌ۚ وَم[a:1297[َن ي]َفْعَلْ ذ[n[َٲ]لِكَ [h:3130[ٱ][q:1130[بْ]تِغ[o[َا]ٓءَ مَرْضَاتِ [h:1131[ٱ]للَّهِ فَسَوْفَ نُؤْتِيهِ أَ[q:2795[جْ]رًا عَظِيمًا","Уларнинг кўпгина махфий суҳбатларида яхшилик йўқ, магар ким садақага, яхшиликка ва одамлар орасида ислоҳга амр қилсагина, яхшилик бор. Ким ўша ишни Аллоҳнинг розилиги учун қилса, албатта, унга улуғ ажр берамиз.",97,5],["وَم[a:3131[َن ي]ُشَاقِقِ [h:3132[ٱ][l[ل]رَّسُولَ م[i:146[ِنۢ ب]َعْدِ مَا تَبَيَّنَ لَهُ [h:3133[ٱ]لْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ [h:3134[ٱ]لْمُؤْمِنِينَ نُوَلِّه[n[ِۦ] مَا تَوَلَّىٰ وَنُصْلِه[n[ِۦ] جَهَ[g[نّ]َمَ‌ۖ وَس[o[َا]ٓءَتْ مَصِيرًا","Ким ўзига ҳидоят равшан бўлгандан кейин Пайғамбарга хилоф қилса ва мўминларнинг йўлидан бошқа йўлга юрса, кетган томонга қўйиб қўямиз ва жаҳаннамга киритамиз. У қандоқ ҳам ёмон жой!",97,5],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَغْفِرُ أ[a:2833[َن ي]ُشْرَكَ بِه[n[ِۦ] وَيَغْفِرُ مَا دُونَ ذ[n[َٲ]لِكَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ‌ۚ وَم[a:2834[َن ي]ُشْرِكْ بِ[h:32[ٱ]للَّهِ فَقَ[q:563[دْ] ضَلَّ ضَلَ[n[ـٰ]ل[i:2874[اَۢ ب]َعِيدًا","Албатта, Аллоҳ Ўзига ширк келтирилишини кечирмас. Ундан бошқани, кимни хоҳласа, кечиради. Ким Аллоҳга ширк келтирса, шубҳасиз, қаттиқ адашган бўлади.",97,5],["إ[a:3135[ِن ي]َ[q:1240[دْ]عُونَ مِ[f:3136[ن د]ُونِه[o[ِۦٓ] إِلّ[o[َآ] إِنَ[n[ـٰ][a:3137[ثًا و]َإ[a:3138[ِن ي]َ[q:1240[دْ]عُونَ إِلَّا شَيْطَ[n[ـٰ][a:3139[نًا م]َّرِيدًا","Улар ундан бошқа фақат аёл-санамларга ибодат қиладилар ва фақат бебош шайтонга ибодат қиладилар.",97,5],["لَّعَنَهُ [h:3140[ٱ]للَّهُ‌ۘ وَقَالَ لَأَتَّخِذَ[g[نّ]َ مِنْ عِبَادِكَ نَصِي[a:2572[بًا م]َّفْرُوضًا","Аллоҳ уни лаънатлади. У эса: «Қасамки, бандаларингдан маълум насибани оламан.",97,5],["وَلَأُضِلَّ[g[نّ]َهُمْ وَلَأُمَ[g[نّ]ِيَ[g[نّ]َهُمْ وَلَأَمُرَ[g[نّ]َهُمْ فَلَيُبَتِّكُ[g[نّ]َ ءَاذَانَ [h:3141[ٱ]لْأَنْعَ[n[ـٰ]مِ وَلَأَمُرَ[g[نّ]َهُمْ فَلَيُغَيِّرُ[g[نّ]َ خَلْقَ [h:3142[ٱ]للَّهِ‌ۚ وَم[a:3143[َن ي]َتَّخِذِ [h:3144[ٱ][l[ل]شَّيْطَ[n[ـٰ]نَ وَلِي[a:3145[ًّا م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ فَقَ[q:563[دْ] خَسِرَ خُسْرَا[a:3146[نًا م]ُّبِينًا","Уларни адаштираман, хом хаёлларига соламан, уларга амр қилсам, чорваларнинг қулоқларини кесарлар ва уларга амр қилсам, Аллоҳнинг яратганини ўзгартирарлар», деди. Кимки Аллоҳни қўйиб шайтонни дўст тутса, батаҳқиқ, очиқ-ойдин зиёнга учрайдир.",97,5],["يَعِدُهُمْ وَيُمَ[g[نّ]ِيهِمْ‌ۖ وَمَا يَعِدُهُمُ [h:3147[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ إِلَّا غُرُورًا","У уларга ваъда берадир ва хом хаёлларга соладир. Шайтон уларга ғурурдан бошқа нарсани ваъда қилмайдир.",97,5],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مَأْوَ[n[ٮٰ]هُمْ جَهَ[g[نّ]َمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًا","Ана ўшаларнинг жойлари жаҳаннамдир. Ва ундан қутулиш йўлини топа олмаслар.",97,5],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ سَنُ[q:2855[دْ]خِلُهُمْ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَ[a:3148[دًا‌ۖ و]َعْدَ [h:3149[ٱ]للَّهِ حَق[a:3150[ًّا‌ۚ و]َمَنْ أَصْدَقُ مِنَ [h:321[ٱ]للَّهِ قِيلاً","Иймон келтириб, яхши амалларни қилганларни остидан анҳорлар оқиб турган жаннатларга киритамиз. Унда абадий–бардавом қолурлар. Аллоҳнинг ваъдаси ҳақдир. Аллоҳдан ростгўйроқ зот борми?",98,5],["لَّيْسَ بِأَمَانِيِّكُمْ وَل[o[َآ] أَمَانِىِّ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ‌ۗ م[a:3151[َن ي]َعْمَلْ س[o[ُو]ٓ[a:3152[ءًا ي]ُ[q:3153[جْ]زَ بِه[n[ِۦ] وَلَا يَجِ[q:1067[دْ] لَهُ[n[ۥ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَلِي[a:3006[ًّا و]َلَا نَصِيرًا","Сизларнинг хом хаёлингизчга ҳам эмас, аҳли китобларнинг хом хаёличга ҳам эмас. Ким ёмонлик қилса, унинг жазосини тортадир. Ва ўзига Аллоҳдан ўзга дўст ҳам, ёрдамчи ҳам топа олмас.",98,5],["وَم[a:3112[َن ي]َعْمَلْ مِنَ [h:3154[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ مِ[f:2511[ن ذ]َكَرٍ أَوْ أُ[f:1867[نث]َىٰ وَهُوَ مُؤْمِ[f:3155[نٌ ف]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يَ[q:3156[دْ]خُلُونَ [h:3157[ٱ]لْجَ[g[نّ]َةَ وَلَا يُظْلَمُونَ نَقِيرًا","Эркакми, аёлми–ким мўмин бўлган ҳолда яхшиликлар қилса, ана ўшалар жаннатга кирарлар ва уларга қилча ҳам зулм қилинмас.",98,5],["وَمَنْ أَحْسَنُ دِي[a:3158[نًا م]ِّ[g[مّ]َنْ أَسْلَمَ وَ[q:580[جْ]هَهُ[n[ۥ] لِلَّهِ وَهُوَ مُحْسِ[a:3159[نٌ و]َ[h:3160[ٱ]تَّبَعَ مِلَّةَ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ حَنِي[a:3161[فًا‌ۗ و]َ[h:3162[ٱ]تَّخَذَ [h:3163[ٱ]للَّهُ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ خَلِيلاً","Яхшилик қилувчи бўлган ҳолида юзини Аллоҳга таслим қилган ва Иброҳимнинг тўғри динига эргашган кимсанинг динидан ҳам яхшироқ дин борми? Ва Аллоҳ Иброҳимни дўст тутган эди.",98,5],["وَلِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ بِكُلِّ ش[a:3164[َىْءٍ م]ُّحِيطًا","Осмонлару ердаги нарсалар Аллоҳга хосдир ва Аллоҳ ҳар бир нарсани ихота қилган зотдир.",98,5],["وَيَسْتَفْتُونَكَ فِى [h:3165[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ‌ۖ قُلِ [h:3166[ٱ]للَّهُ يُفْتِيكُمْ فِيهِ[g[نّ]َ وَمَا يُتْلَىٰ عَلَيْكُمْ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ فِى يَتَ[n[ـٰ]مَى [h:3167[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ [h:3168[ٱ]لَّ[n[ـٰ]تِى لَا تُؤْتُونَهُ[g[نّ]َ مَا كُتِبَ لَهُ[g[نّ]َ وَتَرْغَبُونَ أَ[f:3169[ن ت]َ[f:3170[نك]ِحُوهُ[g[نّ]َ وَ[h:2922[ٱ]لْمُسْتَضْعَفِينَ مِنَ [h:3171[ٱ]لْوِلْد[n[َٲ]نِ وَأَ[f:3172[ن ت]َقُومُو[s[اْ] لِلْيَتَ[n[ـٰ]مَىٰ بِ[h:1800[ٱ]لْقِسْطِ‌ۚ وَمَا تَفْعَلُو[s[اْ] مِنْ خَيْ[f:1191[رٍ ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ كَانَ بِه[n[ِۦ] عَلِيمًا","Сендан аёллар ҳақида фатво сўрарлар. Сен: «Аллоҳ сизга улар ҳақида ва китобда тиловат қилинадиган, сиз уларга тайин қилинган нарсани бермай никоҳига рағбат қилганингиз аёллар ҳақида, заифҳол болалар ҳақида ва етимларга адолат қилмоғингиз ҳақида фатво беради», деб айт. Аллоҳ қилган ҳар бир яхшилигингизни билувчи зотдир.",98,5],["وَإِنِ [h:3173[ٱ]مْرَأَةٌ خَافَتْ م[i:3174[ِنۢ ب]َعْلِهَا نُشُوزًا أَوْ إِعْرَا[f:3175[ضًا ف]َلَا جُنَاحَ عَلَيْهِم[o[َآ] أ[a:3176[َن ي]ُصْلِحَا بَيْنَهُمَا صُلْ[a:3177[حًا‌ۚ و]َ[h:3178[ٱ][l[ل]صُّلْحُ خَيْ[a:3179[رٌ‌ۗ و]َأُحْضِرَتِ [h:3180[ٱ]لْأَ[f:3181[نف]ُسُ [h:3182[ٱ][l[ل]شُّحَّ‌ۚ وَإِ[f:3183[ن ت]ُحْسِنُو[s[اْ] وَتَتَّقُو[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا","Агар аёл киши ўз эридан нафрат ва юз ўгириш содир бўлишидан қўрқса, икковлари ўзаро сулҳга келишишларида гуноҳ йўқ. Сулҳ яхшидир. Нафслар қизғанишга ҳозирдир. Агар яхшилик ва тақво қилсангиз, албатта, Аллоҳ нима қилаётганингиздан хабардор зотдир.",99,5],["وَلَ[f:3184[ن ت]َسْتَطِيع[o[ُوٓ][s[اْ] أَ[f:3185[ن ت]َعْدِلُو[s[اْ] بَيْنَ [h:3186[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ وَلَوْ حَرَصْتُمْ‌ۖ فَلَا تَمِيلُو[s[اْ] كُلَّ [h:3187[ٱ]لْمَيْلِ فَتَذَرُوهَا كَ[h:3188[ٱ]لْمُعَلَّقَةِ‌ۚ وَإِ[f:3189[ن ت]ُصْلِحُو[s[اْ] وَتَتَّقُو[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ كَانَ غَفُو[u:2701[رًا ر]َّحِيمًا","Агар роса ҳаракат қилсангиз ҳам, хотинлар ўртасида адолатли бўла олмайсизлар. Бир йўла мойил бўлиб кетиб, муаллақга ўхшатиб қўйманг. Агар ислоҳ ва тақво қилсангиз, албатта. Аллоҳ мағфиратли ва раҳмли зотдир.",99,5],["وَإ[a:3190[ِن ي]َتَفَرَّقَا يُغْنِ [h:3191[ٱ]للَّهُ كُل[a:3192[اًّ م]ِّ[f:3193[ن س]َعَتِه[n[ِۦ]‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ و[n[َٲ]سِعًا حَكِيمًا","Агар ажрашсалар, Аллоҳ Ўз фазлидан ҳар бирини беҳожат қилур. Аллоҳ фазли кенг ва ҳикматли зотдир.",99,5],["وَلِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۗ وَلَقَ[q:341[دْ] وَصَّيْنَا [h:3194[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ وَإِيَّاكُمْ أَنِ [h:3195[ٱ]تَّقُو[s[اْ] [h:1644[ٱ]للَّهَ‌ۚ وَإِ[f:3196[ن ت]َكْفُرُو[s[اْ] فَإِ[g[نّ]َ لِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ غَنِيًّا حَمِيدًا","Осмонлару ердаги нарсалар Аллоҳникидир. Батаҳқиқ, Биз сиздан олдин китоб берилганларга ҳам, сизга ҳам: «Аллоҳга тақво қилинглар», деб тавсия қилдик. Агар куфр келтирсангиз, албатта, осмонлару ердаги нарсалар Аллоҳникидир. Ва Аллоҳ беҳожат ва мақталган зотдир.",99,5],["وَلِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۚ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ وَكِيلاً","Осмонлару ердаги нарсалар Аллоҳникидир. Вакил бўлишга Аллоҳ кифоядир.",99,5],["إ[a:3197[ِن ي]َشَأْ يُذْهِ[q:3198[بْ]كُمْ أَيُّهَا [h:3199[ٱ][l[ل][g[نّ]َاسُ وَيَأْتِ بِـَٔـاخَرِينَ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ عَلَىٰ ذ[n[َٲ]لِكَ قَدِيرًا","Агар у зот хоҳласа, эй одамлар, сизларни кетказиб, бошқаларни келтирур. Ва Аллоҳ бунга қодир бўлган зотдир.",99,5],["مَّ[f:506[ن ك]َانَ يُرِيدُ ثَوَابَ [h:2294[ٱ][l[ل]دُّنْيَا فَعِ[f:3042[ند]َ [h:3043[ٱ]للَّهِ ثَوَابُ [h:3200[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ سَمِيع[i:2864[َۢا ب]َصِيرًا","Ким бу дунё савобини истаса, билсинки, Аллоҳнинг ҳузурида ҳам бу дунёнинг, ҳам у дунёнинг савоби бордир. Ва Аллоҳ эшитувчи ва кўрувчи зотдир.",99,5],["۞ يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] كُونُو[s[اْ] قَوّ[n[َٲ]مِينَ بِ[h:1800[ٱ]لْقِسْطِ شُهَد[o[َا]ٓءَ لِلَّهِ وَلَوْ عَلَ[o[ىٰٓ] أَ[f:1329[نف]ُسِكُمْ أَوِ [h:3201[ٱ]لْو[n[َٲ]لِدَيْنِ وَ[h:945[ٱ]لْأَ[q:945[قْ]رَبِينَ‌ۚ إ[a:3202[ِن ي]َكُنْ غَنِيًّا أَوْ فَقِي[f:3203[رًا ف]َ[h:591[ٱ]للَّهُ أَوْلَىٰ بِهِمَا‌ۖ فَلَا تَتَّبِعُو[s[اْ] [h:3204[ٱ]لْهَوَ[o[ىٰٓ] أَ[f:3185[ن ت]َعْدِلُو[s[اْ‌ۚ] وَإِ[f:3205[ن ت]َلْوُ[o[ۥٓاْ] أَوْ تُعْرِضُو[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا","Эй иймон келтирганлар! Адолат ила туринг ҳамда агар ўзингиз, ота-онангиз ва қариндошларингиз зиддига бўлса ҳам, Аллоҳ учун тўғри гувоҳлик берувчи бўлинг. Агар у бой бўлса ҳам, камбағал бўлса ҳам, Аллоҳ унга яқинроқдир. Ҳавои нафсга эргашиб, адолатсизлик қилманг. Агар тилингизни бурсангиз ёки юз ўгириб кетсангиз, албатта, Аллоҳ нима қилаётганингиздан хабардордир.",100,5],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] ءَامِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] وَ[h:906[ٱ]لْكِتَ[n[ـٰ]بِ [h:3206[ٱ]لَّذِى نَزَّلَ عَلَىٰ رَسُولِه[n[ِۦ] وَ[h:906[ٱ]لْكِتَ[n[ـٰ]بِ [h:3206[ٱ]لَّذ[o[ِىٓ] أَ[f:471[نز]َلَ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۚ وَم[a:636[َن ي]َكْفُرْ بِ[h:32[ٱ]للَّهِ وَمَلَ[o[ـٰٓ]ئِكَتِه[n[ِۦ] وَكُتُبِه[n[ِۦ] وَرُسُلِه[n[ِۦ] وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ فَقَ[q:563[دْ] ضَلَّ ضَلَ[n[ـٰ]ل[i:2874[اَۢ ب]َعِيدًا","Эй иймон келтирганлар! Аллоҳга, Унинг Расулига, У Ўз Расулига туширган китобга ва бундан олдин туширган китобга иймон келтиринг. Ким Аллоҳга, Унинг фаришталарига, китобларига, Пайғамбарларига ва охират кунига куфр келтирса, батаҳқиқ, қаттиқ адашган бўладир.",100,5],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] ثُ[g[مّ]َ كَفَرُو[s[اْ] ثُ[g[مّ]َ ءَامَنُو[s[اْ] ثُ[g[مّ]َ كَفَرُو[s[اْ] ثُ[g[مّ]َ [h:2090[ٱ]زْدَادُو[s[اْ] كُفْ[u:3207[رًا ل]َّمْ يَكُنِ [h:3208[ٱ]للَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلاَۢ","Албатта, иймон келтирганларидан кейин куфр келтирганлар, сўнгра иймон келтириб яна куфрга кетган ва куфрида зиёда бўлганларни Аллоҳ мағфират қилмас ва тўғри йўлга ҳидоят этмас.",100,5],["بَشِّرِ [h:3209[ٱ]لْمُنَ[n[ـٰ]فِقِينَ بِأَ[g[نّ]َ لَهُمْ عَذَابًا أَلِيمًا","Мунофиқларга, албатта, уларга аламли азоб бўлишининг башоратини бер.",100,5],["ٱلَّذِينَ يَتَّخِذُونَ [h:3210[ٱ]لْكَ[n[ـٰ]فِرِينَ أَوْلِي[o[َا]ٓءَ مِ[f:107[ن د]ُونِ [h:1838[ٱ]لْمُؤْمِنِينَ‌ۚ أَيَ[q:3211[بْ]تَغُونَ عِ[f:3212[ند]َهُمُ [h:3213[ٱ]لْعِزَّةَ فَإِ[g[نّ]َ [h:3214[ٱ]لْعِزَّةَ لِلَّهِ جَمِيعًا","Улар мўминларни қўйиб, кофирлрни дўст тутадиганлардир. Уларнинг олдида иззат–куч-қудрат излайдиларми? Албатта, иззат–куч-қудратнинг барчаси Аллоҳнинг ҳузуридадир.",100,5],["وَقَ[q:387[دْ] نَزَّلَ عَلَيْكُمْ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ أَنْ إِذَا سَمِعْتُمْ ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَ[q:3215[قْ]عُدُو[s[اْ] مَعَهُمْ حَتَّىٰ يَخُوضُو[s[اْ] فِى حَدِيثٍ غَيْرِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َكُمْ إِ[a:3216[ذًا م]ِّثْلُهُمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ جَامِعُ [h:3217[ٱ]لْمُنَ[n[ـٰ]فِقِينَ وَ[h:3218[ٱ]لْكَ[n[ـٰ]فِرِينَ فِى جَهَ[g[نّ]َمَ جَمِيعًا","Батаҳқиқ, сизларга китобда: «Аллоҳнинг оятларига куфр келтирилган ва уларни истеҳзо қилинган чоғда, бошқа гапга ўтмагунларича улар билан ўтирманглар», деб туширди. Агар ўтирсангиз, сиз ҳам уларга ўхшашсиз. Албатта, Аллоҳ мунофиқ ва кофирларнинг барчасини жаҳаннамда жамловчидир.",100,5],["ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِ[f:1670[ن ك]َانَ لَكُمْ فَتْ[a:3219[حٌ م]ِّنَ [h:321[ٱ]للَّهِ قَال[o[ُوٓ][s[اْ] أَلَمْ نَك[a:3220[ُن م]َّعَكُمْ وَإِ[f:1649[ن ك]َانَ لِلْكَ[n[ـٰ]فِرِينَ نَصِي[f:3221[بٌ ق]َال[o[ُوٓ][s[اْ] أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْك[w:3222[ُم م]ِّنَ [h:3047[ٱ]لْمُؤْمِنِينَ‌ۚ فَ[h:591[ٱ]للَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۗ وَل[a:3223[َن ي]َ[q:2441[جْ]عَلَ [h:2644[ٱ]للَّهُ لِلْكَ[n[ـٰ]فِرِينَ عَلَى [h:2329[ٱ]لْمُؤْمِنِينَ سَبِيلاً","Улар сизларни кузатиб турарлар. Сизларга Аллоҳ томонидан фатҳ бўлса: «Сизлар билан бирга эмасмидик?!» дерлар. Агар кофирларга насиба бўлса: «Сизларга устун келиб, мўминлардан ҳимоя қилмадикми?» дерлар. Аллоҳ қиёмат куни улар орасида ҳукм қилур. Аллоҳ ҳаргиз кофирларга мўминлар устидан йўл бермас.",101,5],["إِ[g[نّ]َ [h:3224[ٱ]لْمُنَ[n[ـٰ]فِقِينَ يُخَ[n[ـٰ]دِعُونَ [h:36[ٱ]للَّهَ وَهُوَ خَ[n[ـٰ]دِعُهُمْ وَإِذَا قَام[o[ُوٓ][s[اْ] إِلَى [h:3225[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ قَامُو[s[اْ] كُسَالَىٰ يُر[o[َا]ٓءُونَ [h:3226[ٱ][l[ل][g[نّ]َاسَ وَلَا يَذْكُرُونَ [h:2497[ٱ]للَّهَ إِلَّا قَلِيلاً","Албатта, мунофиқлар Аллоҳни алдамоқчи бўларлар. Ҳолбуки, Аллоҳ уларни «алдовчи»дир. Агар намозга турсалар, дангасалик билан, хўжакўрсинга турарлар ва Аллоҳни камдан кам зикр қиларлар.",101,5],["مُّذَ[q:3227[بْ]ذَبِينَ بَيْنَ ذ[n[َٲ]لِكَ ل[o[َآ] إِلَىٰ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ وَل[o[َآ] إِلَىٰ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ‌ۚ وَم[a:3002[َن ي]ُضْلِلِ [h:3003[ٱ]للَّهُ فَلَ[f:2843[ن ت]َجِدَ لَهُ[n[ۥ] سَبِيلاً","Улар орада сарсондирлар. На анавиларга қўшила оларлар ва на манавиларга қўшила оларлар. Аллоҳ кимни йўлдан адаштирса, ҳаргиз унга йўл топа олмассан.",101,5],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَتَّخِذُو[s[اْ] [h:3228[ٱ]لْكَ[n[ـٰ]فِرِينَ أَوْلِي[o[َا]ٓءَ مِ[f:107[ن د]ُونِ [h:1838[ٱ]لْمُؤْمِنِينَ‌ۚ أَتُرِيدُونَ أَ[f:3229[ن ت]َ[q:95[جْ]عَلُو[s[اْ] لِلَّهِ عَلَيْكُمْ سُلْطَ[n[ـٰ][a:3014[نًا م]ُّبِينًا","Эй иймон келтирганлар! Мўминларни қўйиб, кофирларни дўст тутманг. Аллоҳнинг ҳузурида ўз зиддингизга очиқ ҳужжат қилишни хоҳлайсизми?!",101,5],["إِ[g[نّ]َ [h:3224[ٱ]لْمُنَ[n[ـٰ]فِقِينَ فِى [h:3230[ٱ][l[ل]دَّرْكِ [h:3231[ٱ]لْأَسْفَلِ مِنَ [h:869[ٱ][l[ل][g[نّ]َارِ وَلَ[f:3232[ن ت]َجِدَ لَهُمْ نَصِيرًا","Албатта, мунофиқлар дўзахнинг энг остки қаватидадирлар ва ҳаргиз уларга бир ёрдамчини топа олмассан.",101,5],["إِلَّا [h:778[ٱ]لَّذِينَ تَابُو[s[اْ] وَأَصْلَحُو[s[اْ] وَ[h:3233[ٱ]عْتَصَمُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَأَخْلَصُو[s[اْ] دِينَهُمْ لِلَّهِ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مَعَ [h:3234[ٱ]لْمُؤْمِنِينَ‌ۖ وَسَوْفَ يُؤْتِ [h:3235[ٱ]للَّهُ [h:3236[ٱ]لْمُؤْمِنِينَ أَ[q:2795[جْ]رًا عَظِيمًا","Магар тавба қилиб, солиҳ амаллар қилган, Аллоҳни маҳкам ушлаган ва Аллоҳ учун динга ихлос қўйганлар–ана ўшалар мўминлар ила биргадирлар. Аллоҳ, албатта, мўминларга улуғ ажр берур.",101,5],["مَّا يَفْعَلُ [h:3237[ٱ]للَّهُ بِعَذَابِكُمْ إِ[f:3238[ن ش]َكَرْتُمْ وَءَامَ[f:3239[نت]ُمْ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ شَاكِرًا عَلِيمًا","Агар шукр қилсангиз ва иймон келтирсангиз, Аллоҳ сизни азоблаб нима қилади? Аллоҳ шукр қилувчи ва билувчи зотдир.",101,5],["۞ لَّا يُحِبُّ [h:3240[ٱ]للَّهُ [h:3241[ٱ]لْجَهْرَ بِ[h:875[ٱ][l[ل]سّ[o[ُو]ٓءِ مِنَ [h:3107[ٱ]لْقَوْلِ إِلَّا مَ[f:3242[ن ظ]ُلِمَ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ سَمِيعًا عَلِيمًا","Аллоҳ ёмон гапни ошкор қилишни хуш кўрмайди. Магар мазлумдан бўлса, майли. Аллоҳ эшитувчи ва билувчи зотдир.",102,6],["إِ[f:1601[ن ت]ُ[q:1602[بْ]دُو[s[اْ] خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُو[s[اْ] عَ[f:3243[ن س][o[ُو]ٓ[f:3244[ءٍ ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ كَانَ عَفُو[f:3245[ًّا ق]َدِيرًا","Агар яхшиликни ошкора ёки махфий қилсангиз ёки ёмонликни афв этсангиз, албатта, Аллоҳ афвли ва қодир зотдир.",102,6],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَكْفُرُونَ بِ[h:32[ٱ]للَّهِ وَرُسُلِه[n[ِۦ] وَيُرِيدُونَ أ[a:3246[َن ي]ُفَرِّقُو[s[اْ] بَيْنَ [h:3247[ٱ]للَّهِ وَرُسُلِه[n[ِۦ] وَيَقُولُونَ نُؤْمِنُ بِبَعْ[a:3248[ضٍ و]َنَكْفُرُ بِبَعْ[a:3249[ضٍ و]َيُرِيدُونَ أ[a:3250[َن ي]َتَّخِذُو[s[اْ] بَيْنَ ذ[n[َٲ]لِكَ سَبِيلاً","Албатта, Аллоҳга ва Унинг Пайғамбарларига куфр келтирадиганлар ва Аллоҳ ила Пайғамбарлари орасида айримчиликни ирода қиладиганлар ҳамда баъзиларига иймон ва баъзиларига куфр келтирамиз, деб ана ўшандай ора йўлни тутишни хоҳлайдиганлар.",102,6],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:3251[ٱ]لْكَ[n[ـٰ]فِرُونَ حَق[a:3252[ًّا‌ۚ و]َأَعْتَ[q:2782[دْ]نَا لِلْكَ[n[ـٰ]فِرِينَ عَذَا[a:2783[بًا م]ُّهِينًا","Ана ўшалар ҳақиқий кофирлардир. Ва кофирларга хорловчи азобни тайёрлаб қўйганмиз.",102,6],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرُسُلِه[n[ِۦ] وَلَمْ يُفَرِّقُو[s[اْ] بَيْنَ أَحَ[a:702[دٍ م]ِّنْهُمْ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ‌ۗ وَكَانَ [h:2653[ٱ]للَّهُ غَفُو[u:2701[رًا ر]َّحِيمًا","Аллоҳга ва Унинг Пайғамбарларига иймон келтирганларга ва уларнинг бирортасини ҳам айирмаганларга–ана ўшаларга ажрларини албатта берурмиз. Ва Аллоҳ мағфиратли ва раҳмли зотдир.",102,6],["يَسْــَٔلُكَ أَهْلُ [h:2159[ٱ]لْكِتَ[n[ـٰ]بِ أَ[f:3253[ن ت]ُنَزِّلَ عَلَيْهِمْ كِتَ[n[ـٰ][a:3254[بًا م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ‌ۚ فَقَ[q:563[دْ] سَأَلُو[s[اْ] مُوسَ[o[ىٰٓ] أَكْبَرَ مِ[f:2624[ن ذ][n[َٲ]لِكَ فَقَال[o[ُوٓ][s[اْ] أَرِنَا [h:3255[ٱ]للَّهَ جَهْرَ[f:3256[ةً ف]َأَخَذَتْهُمُ [h:3257[ٱ][l[ل]صَّ[n[ـٰ]عِقَةُ بِظُلْمِهِمْ‌ۚ ثُ[g[مّ]َ [h:3258[ٱ]تَّخَذُو[s[اْ] [h:3259[ٱ]لْعِ[q:253[جْ]لَ م[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَتْهُمُ [h:1168[ٱ]لْبَيِّنَ[n[ـٰ]تُ فَعَفَوْنَا عَ[f:3260[ن ذ][n[َٲ]لِكَ‌ۚ وَءَاتَيْنَا مُوسَىٰ سُلْطَ[n[ـٰ][a:3014[نًا م]ُّبِينًا","Аҳли китоблар сендан уларга осмондан китоб тушириб беришингни сўрарлар. Мусодан бундан ҳам катта нарсани сўраганлар–«Бизга Аллоҳни ошкора кўрсат», деганлар. Бас, зулмлари туфайли уларни чақмоқ урди. Сўнгра, уларга очиқ-ойдин баёнотлар келганидан кейин бузоқни худо қилиб олдилар. Бас, биз буни ҳам афв қилдик ва Мусога очиқ-ойдин султон бердик.",102,6],["وَرَفَعْنَا فَوْقَهُمُ [h:3261[ٱ][l[ل]طُّورَ بِمِيثَ[n[ـٰ]قِهِمْ وَقُلْنَا لَهُمُ [h:3262[ٱ][q:278[دْ]خُلُو[s[اْ] [h:3263[ٱ]لْبَابَ سُجَّ[a:3264[دًا و]َقُلْنَا لَهُمْ لَا تَعْدُو[s[اْ] فِى [h:345[ٱ][l[ل]سَّ[q:346[بْ]تِ وَأَخَذْنَا مِنْه[w:3265[ُم م]ِّيثَ[n[ـٰ]قًا غَلِيظًا","Ва аҳдномаларигаувофиқ устиларига Турни кўтардик ва уларга: «Эшикдан эгилиб кирингларанба ни ҳаддингиздан ошманг», дедик. Ва улардан мустаҳкам аҳднома олдик.",102,6],["فَبِمَا نَ[q:3266[قْ]ضِه[w:3267[ِم م]ِّيثَ[n[ـٰ]قَهُمْ وَكُفْرِه[c:3268[ِم ب]ِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ وَقَتْلِهِمُ [h:3269[ٱ]لْأَ[i:2175[نۢب]ِي[o[َا]ٓءَ بِغَيْرِ حَ[a:3270[قٍّ و]َقَوْلِهِمْ قُلُوبُنَا غُلْ[i:461[فُۢ‌ۚ ب]َلْ طَبَعَ [h:3271[ٱ]للَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلاً","Аҳдномаларини бузганлари, Аллоҳнинг оятларига куфр келтирганлари, Пайғамбарларни ноҳақдан ўлдирганлари, «қалбларимиз берк» деганлари учун. Йўқ! Балки куфрлари сабабли Аллоҳ қалбларига муҳр босган, озгиналаридан бошқаси иймон келтирмаслар.",103,6],["وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَ[n[ـٰ]نًا عَظِيمًا","Ва куфрлари, Марямга қарши улкан бўҳтон айтганлари учун",103,6],["وَقَوْلِهِمْ إِ[g[نّ]َا قَتَلْنَا [h:3272[ٱ]لْمَسِيحَ عِيسَى [h:450[ٱ][q:451[بْ]نَ مَرْيَمَ رَسُولَ [h:3273[ٱ]للَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَ[n[ـٰ]كِ[f:3274[ن ش]ُبِّهَ لَهُمْ‌ۚ وَإِ[g[نّ]َ [h:754[ٱ]لَّذِينَ [h:899[ٱ]خْتَلَفُو[s[اْ] فِيهِ لَفِى شَ[a:3275[كٍّ م]ِّنْهُ‌ۚ مَا لَه[c:3276[ُم ب]ِه[n[ِۦ] مِنْ عِلْمٍ إِلَّا [h:3277[ٱ]تِّبَاعَ [h:3278[ٱ][l[ل]ظَّ[g[نّ]ِ‌ۚ وَمَا قَتَلُوهُ يَقِينَۢا","«Биз Аллоҳнинг Расули Масиҳ Ийсо ибн Марямни ўлдирдик», деганлари учун. Ҳолбуки уни ўлдирмадилар ҳам, осмадилар ҳам, лекин уларга шундай туюлди. У ҳақида ихтилофга тушганлар унинг ўлимидан шак-шубҳададирлар. У тўғрисида уларнинг билимлари йўқ, магар гумонга эргашарлар. Уни ўлдирмаганлари аниқдир.",103,6],["بَ[b:3279[ل] رَّفَعَهُ [h:3280[ٱ]للَّهُ إِلَيْهِ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ عَزِيزًا حَكِيمًا","Балки уни Аллоҳ Ўзига кўтарди. Аллоҳ азиз ва ҳаким бўлган зотдир.",103,6],["وَإ[a:3281[ِن م]ِّنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ إِلَّا لَيُؤْمِنَ[g[نّ]َ بِه[n[ِۦ] قَ[q:3282[بْ]لَ مَوْتِه[n[ِۦ]‌ۖ وَيَوْمَ [h:443[ٱ]لْقِيَ[n[ـٰ]مَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا","Xеч бир аҳли китоб йўқки, унга ўлимидан олдин иймон келтирмаса. Қиёмат куни эса у уларнинг зиддига гувоҳ бўлур.",103,6],["فَبِظُلْ[a:3283[مٍ م]ِّنَ [h:523[ٱ]لَّذِينَ هَادُو[s[اْ] حَرَّمْنَا عَلَيْهِمْ طَيِّبَ[n[ـٰ]تٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ كَثِيرًا","Яҳудий бўлганларга уларнинг зулми, Аллоҳнинг йўлидан кўп тўсганлари учун ўзларига ҳалол қилинган нарсани ҳаром қилдик.",103,6],["وَأَخْذِهِمُ [h:3284[ٱ][l[ل]رِّبَ[s[و][n[ٲ]اْ وَقَ[q:387[دْ] نُهُو[s[اْ] عَنْهُ وَأَكْلِهِمْ أَمْو[n[َٲ]لَ [h:3285[ٱ][l[ل][g[نّ]َاسِ بِ[h:212[ٱ]لْبَ[n[ـٰ]طِلِ‌ۚ وَأَعْتَ[q:2782[دْ]نَا لِلْكَ[n[ـٰ]فِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا","Ва қайтарилган бўлсалар ҳам, рибо олганликлари ва одамларнинг молларини ботил йўл билан еганлари учун. Ва уларнинг кофирлари учун аламли азобни таёрлаб қўйдик.",103,6],["لَّ[n[ـٰ]كِنِ [h:3286[ٱ][l[ل]رّ[n[َٲ]سِخُونَ فِى [h:1403[ٱ]لْعِلْمِ مِنْهُمْ وَ[h:1709[ٱ]لْمُؤْمِنُونَ يُؤْمِنُونَ بِم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْكَ وَم[o[َآ] أُ[f:17[نز]ِلَ مِ[f:18[ن ق]َ[q:19[بْ]لِكَ‌ۚ وَ[h:3287[ٱ]لْمُقِيمِينَ [h:3288[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ‌ۚ وَ[h:3289[ٱ]لْمُؤْتُونَ [h:3290[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَ[h:1709[ٱ]لْمُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ سَنُؤْتِيهِمْ أَ[q:2795[جْ]رًا عَظِيمًا","Лекин улардан илмда мустаҳкам бўлганлари ва мўминлари сенга нозил бўлган нарсага ва сендан олдин нозил бўлган нарсага иймон келтирарлар. Хусусан, намозни қоим қилувчилар, закот берувчилар, Аллоҳга ва охират кунига иймон келтирувчилар ҳам. Ана ўшаларга, албатта, улуғ ажр берамиз.",103,6],["۞ إِ[g[نّ][o[َآ] أَوْحَيْن[o[َآ] إِلَيْكَ كَم[o[َآ] أَوْحَيْن[o[َآ] إِلَىٰ نُو[a:3291[حٍ و]َ[h:907[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ م[i:254[ِنۢ ب]َعْدِه[n[ِۦ]‌ۚ وَأَوْحَيْن[o[َآ] إِلَ[o[ىٰٓ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَإِسْمَ[n[ـٰ]عِيلَ وَإِسْحَ[n[ـٰ]قَ وَيَعْقُوبَ وَ[h:700[ٱ]لْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَ[n[ـٰ]رُونَ وَسُلَيْمَ[n[ـٰ]نَ‌ۚ وَءَاتَيْنَا دَاوُ[n[ۥ]دَ زَبُورًا","Биз сенга худди Нуҳ ва ундан кейинги Набийларга ваҳий юборганимиздек ваҳий юбордик. Биз Иброҳим, Исмоил, Исҳоқ, Яъқуб, Асбот, Ийсо, Айюб, Юнус, Ҳорун ва Сулаймонларга ваҳий юбордик. Довудга эса Забурни бердик.",104,6],["وَرُسُل[f:3292[اً ق]َ[q:298[دْ] قَصَصْنَ[n[ـٰ]هُمْ عَلَيْكَ مِ[f:128[ن ق]َ[q:129[بْ]لُ وَرُسُل[u:3293[اً ل]َّمْ نَ[q:3294[قْ]صُصْهُمْ عَلَيْكَ‌ۚ وَكَلَّمَ [h:3295[ٱ]للَّهُ مُوسَىٰ تَكْلِيمًا","Ва Биз сенга бундан олдин қиссаларини айтиб берган ва қиссаларини айтиб бермаган Пайғамбарларни юбордик. Ва Аллоҳ Мусо ила ўзига хос гаплашди.",104,6],["رُّسُل[a:3296[اً م]ُّبَشِّرِينَ وَمُ[f:1163[نذ]ِرِينَ لِئَلَّا يَكُونَ لِل[g[نّ]َاسِ عَلَى [h:412[ٱ]للَّهِ حُجَّ[i:3297[ةُۢ ب]َعْدَ [h:3298[ٱ][l[ل]رُّسُلِ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ عَزِيزًا حَكِيمًا","Башорат берувчи ва огоҳлантирувчи Пайғамбарларни Аллоҳ ҳузурида одамларга Пайғамбарлардан сўнг ҳужжат бўлмаслиги учун юбордик. Ва Аллоҳ азиз ва ҳаким бўлган зотдир.",104,6],["لَّ[n[ـٰ]كِنِ [h:3299[ٱ]للَّهُ يَشْهَدُ بِم[o[َآ] أَ[f:471[نز]َلَ إِلَيْكَ‌ۖ أَ[f:3300[نز]َلَهُ[n[ۥ] بِعِلْمِه[n[ِۦ]‌ۖ وَ[h:1146[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ يَشْهَدُونَ‌ۚ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ شَهِيدًا","Лекин Аллоҳ сенга нозил қилган нарсаси ила гувоҳлик беради. Уни Ўз илми ила нозил қилди. Фаришталар ҳам гувоҳлик берурлар. Гувоҳликка Аллоҳнинг Ўзи кифоя қилур.",104,6],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَصَدُّو[s[اْ] عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ قَ[q:298[دْ] ضَلُّو[s[اْ] ضَلَ[n[ـٰ]ل[i:2874[اَۢ ب]َعِيدًا","Куфр келтирган ва Аллоҳнинг йўлидан тўсганлар, батаҳқиқ, қаттиқ адашгандирлар.",104,6],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَظَلَمُو[s[اْ] لَمْ يَكُنِ [h:3208[ٱ]للَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا","Албатта, куфр келтирганлар ва зулум қилганларни Аллоҳ зинҳор мағфират қилмас ва йўлга ҳидоят ҳам қилмас.",104,6],["إِلَّا طَرِيقَ جَهَ[g[نّ]َمَ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَ[a:3301[دًا‌ۚ و]َكَانَ ذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ يَسِيرًا","Магар жаҳаннам йўлига ва унда абадий қолурлар. Бу Аллоҳ учун осондир.",104,6],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ قَ[q:298[دْ] ج[o[َا]ٓءَكُمُ [h:3302[ٱ][l[ل]رَّسُولُ بِ[h:370[ٱ]لْحَقِّ م[u:243[ِن ر]َّبِّكُمْ فَـَٔـامِنُو[s[اْ] خَيْ[u:3303[رًا ل]َّكُمْ‌ۚ وَإِ[f:3196[ن ت]َكْفُرُو[s[اْ] فَإِ[g[نّ]َ لِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ عَلِيمًا حَكِيمًا","Эй одамлар! Батаҳқиқ, сизларга Роббингиздан ҳақ ила Пайғамбар келди. Бас, иймон келтиринг, ўзингизга яхши бўладир. Агар куфр келтирсангиз, зотан осмонлару ердаги нарсалар Аллоҳникидир. Ва Аллоҳ билувчи ва ҳикматли зотдир.",104,6],["يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ لَا تَغْلُو[s[اْ] فِى دِينِكُمْ وَلَا تَقُولُو[s[اْ] عَلَى [h:412[ٱ]للَّهِ إِلَّا [h:3304[ٱ]لْحَقَّ‌ۚ إِ[g[نّ]َمَا [h:3305[ٱ]لْمَسِيحُ عِيسَى [h:1916[ٱ][q:1917[بْ]نُ مَرْيَمَ رَسُولُ [h:3306[ٱ]للَّهِ وَكَلِمَتُهُ[o[ۥٓ] أَلْقَ[n[ـٰ]ه[o[َآ] إِلَىٰ مَرْيَمَ وَرُو[a:3307[حٌ م]ِّنْهُ‌ۖ فَـَٔـامِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرُسُلِه[n[ِۦ]‌ۖ وَلَا تَقُولُو[s[اْ] ثَلَ[n[ـٰ]ثَةٌ‌ۚ [h:3308[ٱ][f:3309[نت]َهُو[s[اْ] خَيْ[u:3303[رًا ل]َّكُمْ‌ۚ إِ[g[نّ]َمَا [h:3310[ٱ]للَّهُ إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[f:3311[دٌ‌ۖ س]ُ[q:608[بْ]حَ[n[ـٰ]نَهُ[o[ۥٓ] أ[a:3312[َن ي]َكُونَ لَهُ[n[ۥ] وَلَ[u:3313[دٌ‌ۘ ل]َّهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۗ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ وَكِيلاً","Эй аҳли китоблар! Динингизда ҳаддан ошманг ва Аллоҳ ҳақида ҳақдан бошқани айтманг. Албатта, Масиҳ Ийсо ибн Марям Аллоҳнинг Пайғамбари, Марямга илқо қилган калимаси ва Ундан бўлган руҳдир. Бас, Аллоҳга ва Унинг Пайғамбарларига иймон келтиринг. Уни учта деманг. Тўхтанг, ўзингизга яхши бўлади. Албатта, Аллоҳ ягона илоҳдир, ўзга эмас У Ўзининг боласи бўлишидан пок бўлди. Осмонлардаги нарсалар Уникидир, ердаги нарсалар Уникидир. Вакилликка Аллоҳнинг Ўзи кифоя қилур.",105,6],["لّ[a:3314[َن ي]َسْتَ[f:3315[نك]ِفَ [h:3316[ٱ]لْمَسِيحُ أ[a:3312[َن ي]َكُونَ عَ[q:3317[بْ][u:3318[دًا ل]ِّلَّهِ وَلَا [h:3319[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ [h:3320[ٱ]لْمُقَرَّبُونَ‌ۚ وَم[a:3321[َن ي]َسْتَ[f:3322[نك]ِفْ عَنْ عِبَادَتِه[n[ِۦ] وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا","Масиҳ ҳам, муқарраб фаришталар ҳам Аллоҳга банда бўлишдан зинҳор бош тортмаслар. Ким унинг ибодатидан бош тортса ва мутакаббирлик қилса, уларнинг ҳаммасини Ўзига тўплайди.",105,6],["فَأَ[g[مّ]َا [h:136[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُه[w:3323[ُم م]ِّ[f:475[ن ف]َضْلِه[n[ِۦ]‌ۖ وَأَ[g[مّ]َا [h:138[ٱ]لَّذِينَ [h:3324[ٱ]سْتَ[f:3325[نك]َفُو[s[اْ] وَ[h:3326[ٱ]سْتَكْبَرُو[s[اْ] فَيُعَذِّبُهُمْ عَذَابًا أَلِي[a:3327[مًا و]َلَا يَجِدُونَ لَه[w:1812[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَلِي[a:3006[ًّا و]َلَا نَصِيرًا","Иймон келтириб яхши амалларни қилганларни эса, ажрларини тўлиқ қилиб берур ва Ўз фазлидан ҳам зиёда қилур. Аммо ор қилиб кибрга кетганларни аламли азоб билан азоблар ва улар ўзлари учун Аллоҳдан ўзга дўст ҳам, ёрдамчи ҳам топмаслар.",105,6],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ قَ[q:298[دْ] ج[o[َا]ٓءَك[c:3328[ُم ب]ُرْهَ[n[ـٰ][a:3329[نٌ م]ّ[u:243[ِن ر]َّبِّكُمْ وَأَ[f:271[نز]َلْن[o[َآ] إِلَيْكُمْ نُو[a:3330[رًا م]ُّبِينًا","Эй одамлар! Сизга Роббингиздан бурҳон келди ва сизга аниқ нурни нозил қилдик.",105,6],["فَأَ[g[مّ]َا [h:136[ٱ]لَّذِينَ ءَامَنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَ[h:3233[ٱ]عْتَصَمُو[s[اْ] بِه[n[ِۦ] فَسَيُ[q:3331[دْ]خِلُهُمْ فِى رَحْمَ[a:3332[ةٍ م]ِّنْهُ وَفَضْ[a:3333[لٍ و]َيَهْدِيهِمْ إِلَيْهِ صِر[n[َٲ][a:2898[طًا م]ُّسْتَقِيمًا","Аллоҳга иймон келтирган ва Уни маҳкам тутганларни, шубҳасиз, уларни ўзидан бўлган раҳматга ва фазлга киритади ва уларни Унга–тўғри йўлга ҳидоят қиладир.",105,6],["يَسْتَفْتُونَكَ قُلِ [h:3166[ٱ]للَّهُ يُفْتِيكُمْ فِى [h:3334[ٱ]لْكَلَ[n[ـٰ]لَةِ‌ۚ إِنِ [h:3335[ٱ]مْرُؤٌاْ هَلَكَ لَيْسَ لَهُ[n[ۥ] وَلَ[a:3336[دٌ و]َلَهُ[o[ۥٓ] أُخْ[f:3337[تٌ ف]َلَهَا نِصْفُ مَا تَرَكَ‌ۚ وَهُوَ يَرِثُه[o[َآ] إ[u:2606[ِن ل]َّمْ يَك[u:3338[ُن ل]َّهَا وَلَ[f:2595[دٌ‌ۚ ف]َإِ[f:3339[ن ك]َانَتَا [h:3340[ٱ]ثْنَتَيْنِ فَلَهُمَا [h:3341[ٱ][l[ل]ثُّلُثَانِ مِ[g[مّ]َا تَرَكَ‌ۚ وَإِ[f:2392[ن ك]َان[o[ُوٓ][s[اْ] إِخْوَ[u:3342[ةً ر]ِّجَال[a:3343[اً و]َنِس[o[َا]ٓ[f:3344[ءً ف]َلِلذَّكَرِ مِثْلُ حَظِّ [h:2585[ٱ]لْأُ[f:2586[نث]َيَيْنِ‌ۗ يُبَيِّنُ [h:1002[ٱ]للَّهُ لَكُمْ أَ[f:2814[ن ت]َضِلُّو[s[اْ‌ۗ] وَ[h:72[ٱ]للَّهُ بِكُلِّ شَىْءٍ عَل[p[ِي]مُۢ","Сендан фатво сўрарлар. Сен: «Аллоҳ сизга калола ҳақида фатво берадир», деб айт. Агар бир одам ўлса-ю, унинг боласи бўлмаса, синглиси бўлса, унга марҳумдан қолганнинг ярми берилади. Агар сингилнинг боласи бўлмаса, у ҳамма меросни олади. Агар сингил иккита бўлса, улар марҳумдан қолганнинг учдан иккисини оларлар. Агар эркак-аёл биродарлар бўлсалар, бир эркак икки аёл ҳиссаси асосида оладилар. Адашмаслигингиз учун Аллоҳ баён қилмоқда. Аллоҳ ҳар бир нарсани билувчи зотдир.",106,6]]},{"n":5,"ar":"المَائـِدَةِ","en":"Al-Maaida","uz":"Моида","type":"Мадина","ayahs":[["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَوْفُو[s[اْ] بِ[h:3345[ٱ]لْعُقُودِ‌ۚ أُحِلَّتْ لَك[c:3346[ُم ب]َهِيمَةُ [h:3347[ٱ]لْأَنْعَ[n[ـٰ]مِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّى [h:3348[ٱ][l[ل]صَّيْدِ وَأَ[f:98[نت]ُمْ حُرُمٌ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَحْكُمُ مَا يُر[p[ِي][q[د]ُ","Эй иймон келтирганлар! Аҳдномаларга вафо қилинг! Сизга, кейин тиловат қилинадиганларидан бошқа, чорва ҳайвонлари ҳалол қилинди, эҳромдалик вақтингизда овни ҳалол санамаган ҳолингизда. Албатта, Аллоҳ нимани ирода этса, шуни ҳукм қиладир.",106,6],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تُحِلُّو[s[اْ] شَعَ[o[ـٰٓ]ئِرَ [h:3349[ٱ]للَّهِ وَلَا [h:3350[ٱ][l[ل]شَّهْرَ [h:3351[ٱ]لْحَرَامَ وَلَا [h:3352[ٱ]لْهَ[q:3353[دْ]ىَ وَلَا [h:3354[ٱ]لْقَلَ[o[ـٰٓ]ئِدَ وَل[o[َآ] ء[m[َا]ٓ[g[مّ]ِينَ [h:3355[ٱ]لْبَيْتَ [h:3356[ٱ]لْحَرَامَ يَ[q:3357[بْ]تَغُونَ فَضْل[a:1088[اً م]ّ[u:22[ِن ر]َّبِّهِمْ وَرِضْو[n[َٲ][a:3358[نًا‌ۚ و]َإِذَا حَلَلْتُمْ فَ[h:3359[ٱ]صْطَادُو[s[اْ‌ۚ] وَلَا يَ[q:3360[جْ]رِمَ[g[نّ]َكُمْ شَنَـَٔـانُ قَوْمٍ أَ[f:3361[ن ص]َدُّوكُمْ عَنِ [h:3362[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ أَ[f:3363[ن ت]َعْتَدُو[s[اْ‌ۘ] وَتَعَاوَنُو[s[اْ] عَلَى [h:3364[ٱ]لْبِرِّ وَ[h:3365[ٱ][l[ل]تَّ[q:3365[قْ]وَىٰ‌ۖ وَلَا تَعَاوَنُو[s[اْ] عَلَى [h:3366[ٱ]لْإِثْمِ وَ[h:435[ٱ]لْعُ[q:435[دْ]و[n[َٲ]نِ‌ۚ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ شَدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Эй иймон келтирганлар! Аллоҳнинг дини аломатларини, ҳаром ойни, аталган қурбонликни, осилган белгиларни ва Роббиларидан фазл ва розилик тилаб Байтул Ҳаромни қасд қилиб чиққанларни ўзингизга ҳалол ҳисобламанг. Эҳромдан чиқиб ҳалол бўлсангиз, ов қилсангиз, майли. Масжидул Ҳаромдан тўсгани учун бир қавмни ёмон кўришингиз уларга тажовузкор бўлишингизга олиб бормасин. Яхшилик ва тақво йўлида ҳамкорлик қилинг. Гуноҳ ва душманлик йўлида ҳамкорлик қилманг. Аллоҳга тақво қилинг. Албатта, Аллоҳ иқоби шиддатли зотдир.",106,6],["حُرِّمَتْ عَلَيْكُمُ [h:3367[ٱ]لْمَيْتَةُ وَ[h:3368[ٱ][l[ل]دَّمُ وَلَحْمُ [h:3369[ٱ]لْخِ[f:885[نز]ِيرِ وَم[o[َآ] أُهِلَّ لِغَيْرِ [h:886[ٱ]للَّهِ بِه[n[ِۦ] وَ[h:3370[ٱ]لْمُنْخَنِقَةُ وَ[h:3371[ٱ]لْمَوْقُوذَةُ وَ[h:3372[ٱ]لْمُتَرَدِّيَةُ وَ[h:3373[ٱ][l[ل][g[نّ]َطِيحَةُ وَم[o[َآ] أَكَلَ [h:3374[ٱ][l[ل]سَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى [h:3375[ٱ][l[ل][g[نّ]ُصُبِ وَأَ[f:3376[ن ت]َسْتَ[q:3377[قْ]سِمُو[s[اْ] بِ[h:3378[ٱ]لْأَزْلَ[n[ـٰ]مِ‌ۚ ذ[n[َٲ]لِكُمْ فِسْقٌ‌ۗ [h:3379[ٱ]لْيَوْمَ يَئِسَ [h:3380[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِ[f:3381[ن د]ِينِكُمْ فَلَا تَخْشَوْهُمْ وَ[h:3382[ٱ]خْشَوْنِ‌ۚ [h:3383[ٱ]لْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ [h:3384[ٱ]لْإِسْلَ[n[ـٰ]مَ دِي[f:3385[نًا‌ۚ ف]َمَنِ [h:887[ٱ]ضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِ[u:3386[فٍ ل]ِّإٍِثْ[f:3387[مٍ‌ۙ ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Сизларга ўлимтик, қон, чўчқа гўшти, Аллоҳдан бошқанинг номи ила сўйилган, бўғилиб ўлган, уриб ўлдирилган, йиқилиб ўлган, сузиб ўлдирилган, йиртқич еган ҳайвонлар ҳаром қилинди. Магар, сўйиб олсангиз, ҳалол. Ва бутларга сўйилган ҳайвонлар ҳам, чўплар ила фол очишингиз ҳам ҳаром қилинди. Бундай қилмоғингиз фосиқликдир. Бугунги кунда куфр келтирганлар динингизга зарар етказишдан умид уздилар. Улардан қўрқманглар, Мендан қўрқинглар. Бугунги кунда Мен сизнинг динингизни мукаммал қилиб бердим. Сизга неъматимни батамом қилдим. Ва сизга Исломни дин деб рози бўлдим. Кимки гуноҳга моил бўлмаган ҳолида очликдан музтар бўлса, албатта, Аллоҳ мағфиратли ва раҳмли зотдир.",107,6],["يَسْــَٔلُونَكَ مَاذ[o[َآ] أُحِلَّ لَهُمْ‌ۖ قُلْ أُحِلَّ لَكُمُ [h:3388[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تُ‌ۙ وَمَا عَلَّمْت[w:3389[ُم م]ِّنَ [h:3390[ٱ]لْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُ[g[نّ]َ مِ[g[مّ]َا عَلَّمَكُمُ [h:3391[ٱ]للَّهُ‌ۖ فَكُلُو[s[اْ] مِ[g[مّ][o[َآ] أَمْسَكْنَ عَلَيْكُمْ وَ[h:335[ٱ]ذْكُرُو[s[اْ] [h:3392[ٱ]سْمَ [h:3393[ٱ]للَّهِ عَلَيْهِ‌ۖ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَرِيعُ [h:1112[ٱ]لْحِس[p[َا][q[ب]ِ","Сендан уларга нима ҳалол қилинганини сўрарлар. Сен: «Сизларга пок нарсалар ҳалол қилинди. Овчи итларга ўхшатиб, Аллоҳ сизга ўргатган нарсалардан уларга ҳам ўргатган овчи ҳайвонларингиз сизга тутиб берган нарсадан енглар. Уларга Аллоҳнинг исмини зикр қилинглар. Аллоҳга тақво қилинглар. Албатта, Аллоҳ ҳисоби тезкор зотдир», деб айт!",107,6],["ٱلْيَوْمَ أُحِلَّ لَكُمُ [h:3388[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تُ‌ۖ وَطَعَامُ [h:3394[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ حِ[u:3395[لٌّ ل]َّكُمْ وَطَعَامُكُمْ حِ[u:3396[لٌّ ل]َّهُمْ‌ۖ وَ[h:3397[ٱ]لْمُحْصَنَ[n[ـٰ]تُ مِنَ [h:3398[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ وَ[h:3397[ٱ]لْمُحْصَنَ[n[ـٰ]تُ مِنَ [h:523[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ إِذ[o[َآ] ءَاتَيْتُمُوهُ[g[نّ]َ أُجُورَهُ[g[نّ]َ مُحْصِنِينَ غَيْرَ مُسَ[n[ـٰ]فِحِينَ وَلَا مُتَّخِذ[o[ِىٓ] أَخْدَا[a:3399[نٍ‌ۗ و]َم[a:636[َن ي]َكْفُرْ بِ[h:562[ٱ]لْإِيمَ[n[ـٰ]نِ فَقَ[q:563[دْ] حَبِطَ عَمَلُهُ[n[ۥ] وَهُوَ فِى [h:536[ٱ]لْأَخِرَةِ مِنَ [h:340[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","Бугунги кунда сизларга пок нарсалар ҳалол қилинди. Китоб берилганларнинг таоми сиз учун ҳалолдир. Сизнинг таомингиз улар учун ҳалолдир. Афийфа мўминалар ва сиздан олдин китоб берилганлардан бўлган афийфалар ҳам, агар иффатли бўлган ҳолингизда, зинокор бўлмай ва ўйнаш тутмай маҳрларини берсангиз, сизга ҳалолдир. Ким иймонни инкор қилса, унинг амали бехуда кетадир ва охиратда у зиён кўрувчилардан бўладир.",107,6],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا قُمْتُمْ إِلَى [h:3225[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ فَ[h:3400[ٱ]غْسِلُو[s[اْ] وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى [h:3401[ٱ]لْمَرَافِقِ وَ[h:3402[ٱ]مْسَحُو[s[اْ] بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى [h:3403[ٱ]لْكَعْبَيْنِ‌ۚ وَإِ[f:99[ن ك]ُ[f:100[نت]ُمْ جُنُ[f:3404[بًا ف]َ[h:3405[ٱ]طَّهَّرُو[s[اْ‌ۚ] وَإِ[f:99[ن ك]ُ[f:100[نت][w:2804[ُم م]َّرْضَ[o[ىٰٓ] أَوْ عَلَىٰ سَفَرٍ أَوْ ج[o[َا]ٓءَ أَحَ[a:2805[دٌ م]ِّ[f:344[نك][w:2806[ُم م]ِّنَ [h:2807[ٱ]لْغ[o[َا]ٓئِطِ أَوْ لَ[n[ـٰ]مَسْتُمُ [h:2808[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءَ فَلَمْ تَجِدُو[s[اْ] م[o[َا]ٓ[f:2809[ءً ف]َتَيَ[g[مّ]َمُو[s[اْ] صَعِي[f:2810[دًا ط]َيِّ[f:2811[بًا ف]َ[h:2812[ٱ]مْسَحُو[s[اْ] بِوُجُوهِكُمْ وَأَيْدِيك[w:3406[ُم م]ِّنْهُ‌ۚ مَا يُرِيدُ [h:976[ٱ]للَّهُ لِيَ[q:2360[جْ]عَلَ عَلَيْك[w:548[ُم م]ِّنْ حَرَ[a:3407[جٍ و]َلَ[n[ـٰ]ك[a:3408[ِن ي]ُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِ[g[مّ]َ نِعْمَتَهُ[n[ۥ] عَلَيْكُمْ لَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Эй иймон келтирганлар! Намозга турмоқчи бўлсаларингиз, юзларингизни ва қўлларингизни чиғаноқлари ила ювинглар. Бошларингизга масҳ тортинглар. Ва оёқларингизни тўпиқлари ила ювинглар. Агар жунуб бўлсаларингиз, покланинглар. Агар бемор ёки сафарда бўлсаларингиз ёхуд бирорталарингиз таҳоратхонадан келса ёки аёлларга яқинлик қилса-ю, сув топа олмасаларингиз, бас, покиза тупроқ ила таяммум қилинглар. Ундан юзингизга ва қўлларингизга масҳ тортинглар. Аллоҳ сизларга қийинчилик туғдиришни истамас Аммо сизларни поклашни ва сизларга ўз неъматини батамом қилиб беришни истайдир. Шоядки шукр қилсангизлар.",108,6],["وَ[h:9999[ٱ]ذْكُرُو[s[اْ] نِعْمَةَ [h:1154[ٱ]للَّهِ عَلَيْكُمْ وَمِيثَ[n[ـٰ]قَهُ [h:3409[ٱ]لَّذِى وَاثَقَك[c:3410[ُم ب]ِه[o[ِۦٓ] إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا‌ۖ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","Аллоҳнинг сизга берган неъматини ва сиздан олган аҳдини эсланг. Ўзингиз: «Эшитдик ва итоат қилдик», дегансиз-а?! Ва Аллоҳга тақво қилинг. Албатта, Аллоҳ кўкраклардаги нарсани ҳам билгувчи зотдир.",108,6],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] كُونُو[s[اْ] قَوّ[n[َٲ]مِينَ لِلَّهِ شُهَد[o[َا]ٓءَ بِ[h:1800[ٱ]لْقِسْطِ‌ۖ وَلَا يَ[q:3360[جْ]رِمَ[g[نّ]َكُمْ شَنَـَٔـانُ قَوْمٍ عَلَ[o[ىٰٓ] أَلَّا تَعْدِلُو[s[اْ‌ۚ] [h:9999[ٱ]عْدِلُو[s[اْ] هُوَ أَ[q:1355[قْ]رَبُ لِلتَّ[q:1356[قْ]وَىٰ‌ۖ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ خَبِي[i:2335[رُۢ ب]ِمَا تَعْمَل[p[ُو]نَ","Эй иймон келтирганлар! Аллоҳ учун ҳақда туринг, адолатли гувоҳ бўлинг. Бир қавмни ёмон кўришингиз сизни уларга нисбатан адолат қилмасликка олиб бормасин. Адолат қилинг. Бу тақвога оид ишдир. Аллоҳга тақво қилинг. Албатта, Аллоҳ қилаётган амалингиздан харабдор зотдир.",108,6],["وَعَدَ [h:3055[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ‌ۙ لَه[w:3412[ُم م]َّغْفِرَ[a:3413[ةٌ و]َأَ[q:3414[جْ]رٌ عَظ[p[ِي]مٌ","Аллоҳ иймон келтириб яхши амалларни қилганларга ваъда қилди: Уларга мағфират ва улкан ажр бўлур.",108,6],["وَ[h:9999[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَكَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِن[o[َآ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:3415[ٱ]لْجَح[p[ِي]مِ","Куфр келтирганлар ва оятларимизни ёлғонга чиқарганлар–ана ўшалар дўзах эгаларидир!",109,6],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:3416[ٱ]ذْكُرُو[s[اْ] نِعْمَتَ [h:1300[ٱ]للَّهِ عَلَيْكُمْ إِذْ هَ[g[مّ]َ قَوْمٌ أ[a:3417[َن ي]َ[q:3418[بْ]سُط[o[ُوٓ][s[اْ] إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَ[f:255[نك]ُمْ‌ۖ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۚ وَعَلَى [h:2207[ٱ]للَّهِ فَلْيَتَوَكَّلِ [h:2208[ٱ]لْمُؤْمِن[p[ُو]نَ","Эй иймон келтирганлар! Аллоҳнинг сизга берган неъматини эсланг. Бир қавм сизга қўл узатмоқчи бўлганида, У уларнинг қўлларини сиздан қайтарган эди. Ва Аллоҳга тақво қилинг. Мўминлар Аллоҳга таваккал қилсинлар.",109,6],["۞ وَلَقَ[q:341[دْ] أَخَذَ [h:2057[ٱ]للَّهُ مِيثَ[n[ـٰ]قَ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ وَبَعَثْنَا مِنْهُمُ [h:3419[ٱ]ثْنَىْ عَشَرَ نَقِي[a:3420[بًا‌ۖ و]َقَالَ [h:3421[ٱ]للَّهُ إِ[g[نّ]ِى مَعَكُمْ‌ۖ لَئِنْ أَقَمْتُمُ [h:3422[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتَيْتُمُ [h:3423[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَءَامَ[f:3239[نت][c:3424[ُم ب]ِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَ[q:3425[قْ]رَضْتُمُ [h:3426[ٱ]للَّهَ قَرْضًا حَسَ[u:3427[نًا ل]َّأُكَفِّرَ[g[نّ]َ عَ[f:255[نك]ُمْ سَيِّـَٔـاتِكُمْ وَلَأُ[q:3428[دْ]خِلَ[g[نّ]َكُمْ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۚ فَمَ[f:3429[ن ك]َفَرَ بَعْدَ ذ[n[َٲ]لِكَ مِ[f:344[نك]ُمْ فَقَ[q:563[دْ] ضَلَّ سَو[o[َا]ٓءَ [h:564[ٱ][l[ل]سَّب[p[ِي]لِ","Батаҳқиқ, Аллоҳ Бани Исроилдан аҳднома олди. Улардан ўн иккитасини нақиб қилиб юбордик. Ва Аллоҳ: «Албатта, Мен сизлар биланман. Агар намозни қоим қилсангиз, закотни берсангиз, Пайғамбарларимга иймон келтирсангиз, уларни қўлласангиз ва Аллоҳга яхши қарз берсангиз, албатта, сизнинг хатоларингизни кечираман ҳамда сизни остидан анҳорлар оқиб турадиган жаннатларга киритаман. Бас, бундан кейин ҳам сиздан ким куфр келтирса, батаҳқиқ, тўғри йўлдан адашган бўлади», деди.",109,6],["فَبِمَا نَ[q:3266[قْ]ضِه[w:3267[ِم م]ِّيثَ[n[ـٰ]قَهُمْ لَعَ[g[نّ]َ[n[ـٰ]هُمْ وَجَعَلْنَا قُلُوبَهُمْ قَ[n[ـٰ]سِيَ[a:3430[ةً‌ۖ ي]ُحَرِّفُونَ [h:2817[ٱ]لْكَلِمَ ع[a:2818[َن م]َّوَاضِعِه[n[ِۦ]‌ۙ وَنَسُو[s[اْ] حَظ[a:3431[ًّا م]ِّ[g[مّ]َا ذُكِّرُو[s[اْ] بِه[n[ِۦ]‌ۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خ[o[َا]ٓئِنَ[a:3432[ةٍ م]ِّنْهُمْ إِلَّا قَلِيل[a:1395[اً م]ِّنْهُمْ‌ۖ فَ[h:2373[ٱ]عْفُ عَنْهُمْ وَ[h:3433[ٱ]صْفَحْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُحِبُّ [h:1047[ٱ]لْمُحْسِن[p[ِي]نَ","Аҳдларини бузганлари учун уларни лаънатладик ва қалбларини қаттиқ қилдик. Улар калималарни ўз ўрнидан ўзгартирдилар. Ўзларига эслатма бўлган нарсадан кўп насибани унутдилар. Уларнинг озгиналаридан бошқаларидан мудом хиёнат кўрасан. Бас, уларни авф эт ва айбларини ўтиб юбор. Албатта, Аллоҳ яхшилик қилувчиларни севади.",109,6],["وَمِنَ [h:501[ٱ]لَّذِينَ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا نَصَ[n[ـٰ]رَ[o[ىٰٓ] أَخَذْنَا مِيثَ[n[ـٰ]قَهُمْ فَنَسُو[s[اْ] حَظ[a:3431[ًّا م]ِّ[g[مّ]َا ذُكِّرُو[s[اْ] بِه[n[ِۦ] فَأَغْرَيْنَا بَيْنَهُمُ [h:3434[ٱ]لْعَدَاوَةَ وَ[h:3435[ٱ]لْبَغْض[o[َا]ٓءَ إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۚ وَسَوْفَ يُنَبِّئُهُمُ [h:3436[ٱ]للَّهُ بِمَا كَانُو[s[اْ] يَصْنَع[p[ُو]نَ","Ва «Биз насоролармиз» деганларнинг ҳам аҳдномасини олдик. Бас, улар ўзларига эслатма бўлган нарсадан кўп насибани унутдилар. Биз улар орасида адоват ва ёмон кўришни қиёмат кунигача қўзғатдик. Аллоҳ, албатта, уларга қилмишлари ҳақида хабар беради.",110,6],["يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ قَ[q:298[دْ] ج[o[َا]ٓءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِي[a:3437[رًا م]ِّ[g[مّ]َا كُ[f:100[نت]ُمْ تُخْفُونَ مِنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ وَيَعْفُو[s[اْ] عَ[f:3438[ن ك]َثِي[f:3439[رٍ‌ۚ ق]َ[q:298[دْ] ج[o[َا]ٓءَك[w:3440[ُم م]ِّنَ [h:321[ٱ]للَّهِ نُو[a:3441[رٌ و]َكِتَ[n[ـٰ][a:3442[بٌ م]ُّب[p[ِي]نٌ","Эй аҳли китоблар! Батаҳқиқ, сизларга Пайғамбаримиз келди. У сизга китобдан беркитиб юрган кўпгина нарсаларингизни баён қилиб беради. Кўпгинасини эса авф қилади. Батаҳқиқ, сизларга Аллоҳдан нур ва ойдин Китоб келди.",110,6],["يَهْدِى بِهِ [h:1707[ٱ]للَّهُ مَنِ [h:3443[ٱ]تَّبَعَ رِضْو[n[َٲ]نَهُ[n[ۥ] سُبُلَ [h:3444[ٱ][l[ل]سَّلَ[n[ـٰ]مِ وَيُخْرِجُه[w:3445[ُم م]ِّنَ [h:1491[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ إِلَى [h:1492[ٱ][l[ل][g[نّ]ُورِ بِإِذْنِه[n[ِۦ] وَيَهْدِيهِمْ إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","У билан Аллоҳ Ўз розилигини истаганларни салом йўлларига бошлайди ва уларни Ўз изни ила зулматлардан нурга чиқаради. Ҳамда сироти мустақимга ҳидоят қилади.",110,6],["لَّقَ[q:2389[دْ] كَفَرَ [h:3446[ٱ]لَّذِينَ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ هُوَ [h:3447[ٱ]لْمَسِيحُ [h:3448[ٱ][q:1917[بْ]نُ مَرْيَمَ‌ۚ قُلْ فَم[a:3449[َن ي]َمْلِكُ مِنَ [h:321[ٱ]للَّهِ شَيْــًٔا إِنْ أَرَادَ أ[a:3450[َن ي]ُهْلِكَ [h:3451[ٱ]لْمَسِيحَ [h:3452[ٱ][q:451[بْ]نَ مَرْيَمَ وَأُ[g[مّ]َهُ[n[ۥ] وَمَ[f:3453[ن ف]ِى [h:44[ٱ]لْأَرْضِ جَمِي[a:3454[عًا‌ۗ و]َلِلَّهِ مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَيْنَهُمَا‌ۚ يَخْلُقُ مَا يَش[o[َا]ٓءُ‌ۚ وَ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Батаҳқиқ Масиҳ ибн Марям Аллоҳдир, деганлар ҳам кофир бўлдилар. Уларга: «Агар Аллоҳ Масиҳ ибн Марямни, унинг онасини ва ер юзидаги барча кимсаларни ҳалок этишни ирода қилса, ким уни бирон нарсадан манъ қила олади? Ҳолбуки, осмонлару ер ва уларнинг орасидаги нарсалар Аллоҳникидир. У нимани хоҳласа, халқ қилади. Ва Аллоҳ ҳар бир нарсага қодирдир», деб айт!",110,6],["وَقَالَتِ [h:583[ٱ]لْيَهُودُ وَ[h:326[ٱ][l[ل][g[نّ]َصَ[n[ـٰ]رَىٰ نَحْنُ أَ[q:3455[بْ]نَ[o[ـٰٓ]ؤُ[s[اْ] [h:3456[ٱ]للَّهِ وَأَحِبَّ[o[ـٰٓ]ؤُهُ[n[ۥ]‌ۚ قُلْ فَلِمَ يُعَذِّبُك[c:3457[ُم ب]ِذُنُوبِك[c:3458[ُم‌ۖ ب]َلْ أَ[f:428[نت][c:3459[ُم ب]َشَ[a:3460[رٌ م]ِّ[g[مّ]َنْ خَلَقَ‌ۚ يَغْفِرُ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيُعَذِّبُ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَلِلَّهِ مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَيْنَهُمَا‌ۖ وَإِلَيْهِ [h:3461[ٱ]لْمَص[p[ِي]رُ","Яҳудий ва насоролар: «Биз Аллоҳнинг ўғилларимиз ва Унинг маҳбубларимиз», дедилар. Уларга: «Ундай бўлса, нимага У сизларни гуноҳларингиз туфайли азоблайдир? Балки сизлар У яратган башардирсизлар. У кимни хоҳласа, мағфират қиладир. Кимни хоҳласа, азоблайдир. Осмонлару ер ва уларнинг орасидаги нарсалар Аллоҳникидир. Қайтиб бориш фақат Унинг Ўзигадир», деб айт.",111,6],["يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ قَ[q:298[دْ] ج[o[َا]ٓءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَ[a:3462[ةٍ م]ِّنَ [h:3463[ٱ][l[ل]رُّسُلِ أَ[f:1330[ن ت]َقُولُو[s[اْ] مَا ج[o[َا]ٓءَنَا م[i:3464[ِنۢ ب]َشِي[a:3465[رٍ و]َلَا نَذِي[f:3466[رٍ‌ۖ ف]َقَ[q:563[دْ] ج[o[َا]ٓءَك[c:3467[ُم ب]َشِي[a:3468[رٌ و]َنَذِي[a:3469[رٌ‌ۗ و]َ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Эй аҳли китоблар! Батаҳқиқ, сизларга Пайғамбаримиз келди. У сизларга Пайғамбарлардан бўш даврда баён қилади. Бизга башорат бергувчи ҳам, огоҳлантиргувчи ҳам келмаган, демаслигингиз учун. Бас, батаҳқиқ, сизларга башорат бергувчи ҳам, огоҳлантиргувчи ҳам келди. Ва Аллоҳ ҳар бир нарсага қодирдир.",111,6],["وَإِذْ قَالَ مُوسَىٰ لِقَوْمِه[n[ِۦ] يَ[n[ـٰ]قَوْمِ [h:3470[ٱ]ذْكُرُو[s[اْ] نِعْمَةَ [h:1154[ٱ]للَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَ[i:480[نۢب]ِي[o[َا]ٓءَ وَجَعَلَك[w:3471[ُم م]ُّلُو[a:3472[كًا و]َءَاتَ[n[ـٰ]ك[w:3473[ُم م]َّا لَمْ يُؤْتِ أَحَ[a:3474[دًا م]ِّنَ [h:3475[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Мусо ўз қавмига: «Эй қавмим, Аллоҳнинг сизга берган неъматларини эсланг. Ахир, У сиздан Пайғамбарлар юборди, подшоҳлар чиқарди ва оламларда бирортага бермаган нарсаларни берди-ку.",111,6],["يَ[n[ـٰ]قَوْمِ [h:3476[ٱ][q:278[دْ]خُلُو[s[اْ] [h:3477[ٱ]لْأَرْضَ [h:3478[ٱ]لْمُقَدَّسَةَ [h:3479[ٱ]لَّتِى كَتَبَ [h:989[ٱ]للَّهُ لَكُمْ وَلَا تَرْتَدُّو[s[اْ] عَلَ[o[ىٰٓ] أَ[q:3480[دْ]بَارِكُمْ فَتَ[f:2309[نق]َلِبُو[s[اْ] خَ[n[ـٰ]سِر[p[ِي]نَ","Эй қавмим, Аллоҳ сизга ёзиб қўйган муқаддас ерга киринг. Ортингизга қайтманг, бас, зиён кўргувчига айланасиз», деганини эсла.",111,6],["قَالُو[s[اْ] يَ[n[ـٰ]مُوسَ[o[ىٰٓ] إِ[g[نّ]َ فِيهَا قَوْ[f:3481[مًا ج]َبَّارِينَ وَإِ[g[نّ]َا ل[a:3482[َن ن]َّ[q:3483[دْ]خُلَهَا حَتَّىٰ يَخْرُجُو[s[اْ] مِنْهَا فَإ[a:3484[ِن ي]َخْرُجُو[s[اْ] مِنْهَا فَإِ[g[نّ]َا د[n[َٲ]خِل[p[ُو]نَ","Улар: «Эй Мусо, унда зўравон қавм бор. Улар ундан чиқмагунларича биз ҳеч қачон кирмаймиз. Агар улар чиқсалар, биз кирувчидирмиз», дедилар.",111,6],["قَالَ رَجُلَانِ مِنَ [h:523[ٱ]لَّذِينَ يَخَافُونَ أَنْعَمَ [h:2900[ٱ]للَّهُ عَلَيْهِمَا [h:3485[ٱ][q:278[دْ]خُلُو[s[اْ] عَلَيْهِمُ [h:3486[ٱ]لْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِ[g[نّ]َكُمْ غَ[n[ـٰ]لِبُونَ‌ۚ وَعَلَى [h:2207[ٱ]للَّهِ فَتَوَكَّل[o[ُوٓ][s[اْ] إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Улардан қўрқадиганлардан бўлган ва Аллоҳ уларга неъмат ато этган икки киши: «Уларнинг устига эшикдан кириб боринглар. Агар унга кирсангиз, албатта, ғолиб бўласизлар. Агар мўмин бўлсангиз, Аллоҳга таваккал қилингиз», дедилар.",111,6],["قَالُو[s[اْ] يَ[n[ـٰ]مُوسَ[o[ىٰٓ] إِ[g[نّ]َا ل[a:3482[َن ن]َّ[q:3483[دْ]خُلَه[o[َآ] أَبَ[a:3487[دًا م]َّا دَامُو[s[اْ] فِيهَا‌ۖ فَ[h:3488[ٱ]ذْهَ[q:3488[بْ] أَ[f:169[نت]َ وَرَبُّكَ فَقَ[n[ـٰ]تِل[o[َآ] إِ[g[نّ]َا هَ[n[ـٰ]هُنَا قَ[n[ـٰ]عِد[p[ُو]نَ","Улар: «Эй Мусо, модомики улар бор экан, биз зинҳор ва зинҳор у ерга кирмаймиз. Сен ўзинг Роббинг ила бориб икковлон уларга қарши уруш қилаверинглар. Биз бу ерда ўтириб турувчимиз», дедилар.",112,6],["قَالَ رَبِّ إِ[g[نّ]ِى ل[o[َآ] أَمْلِكُ إِلَّا نَفْسِى وَأَخِى‌ۖ فَ[h:3489[ٱ]فْرُ[q:3489[قْ] بَيْنَنَا وَبَيْنَ [h:3490[ٱ]لْقَوْمِ [h:3491[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","У: «Эй Роббим, албатта, мен ўзим ва биродаримдан бошқага эга эмасман. Ўзинг биз билан фосиқ қавмнинг орасини ажратгин», деди.",112,6],["قَالَ فَإِ[g[نّ]َهَا مُحَرَّمَةٌ عَلَيْهِمْ‌ۛ أَرْبَعِينَ سَنَ[a:3492[ةً‌ۛ ي]َتِيهُونَ فِى [h:44[ٱ]لْأَرْضِ‌ۚ فَلَا تَأْسَ عَلَى [h:1431[ٱ]لْقَوْمِ [h:3491[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","У зот: «Албатта, бу ер уларга қирқ йилгача ҳаромдир. Улар ер юзида ҳайрон бўлиб юрарлар. Фосиқ қавмлар учун хафа бўлма», деди.",112,6],["۞ وَ[h:9999[ٱ]تْلُ عَلَيْهِمْ نَبَأَ [h:3493[ٱ][q:3494[بْ]ن[o[َىْ] ءَادَمَ بِ[h:370[ٱ]لْحَقِّ إِذْ قَرَّبَا قُرْبَا[f:3495[نًا ف]َتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ [h:3496[ٱ]لْأَخَرِ قَالَ لَأَ[q:3497[قْ]تُلَ[g[نّ]َكَ‌ۖ قَالَ إِ[g[نّ]َمَا يَتَقَبَّلُ [h:3498[ٱ]للَّهُ مِنَ [h:3499[ٱ]لْمُتَّق[p[ِي]نَ","Уларга Одамнинг икки ўғли хабарини ҳақ ила тиловат қилиб бер. Икковлари қурбонлик қилганларида, бирларидан қабул қилинди, бошқасидан қабул қилинмади. У: «Албатта, мен сени ўлдиражакман», деди. Бириси: «Албатта, Аллоҳ тақводорлардангина қабул қиладир.",112,6],["لَئ[i:3500[ِنۢ ب]َسَطتَ إِلَىَّ يَدَكَ لِتَ[q:3501[قْ]تُلَنِى م[o[َآ] أَنَا۟ بِبَاسِ[a:3502[طٍ ي]َدِىَ إِلَيْكَ لِأَ[q:3503[قْ]تُلَكَ‌ۖ إِ[g[نّ][o[ِىٓ] أَخَافُ [h:3504[ٱ]للَّهَ رَبَّ [h:3505[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Агар сен мени ўлдириш учун қўл кўтарсанг, мен сени ўлдириш учун қўл кўтармасман. Мен, албатта, оламларнинг Робби Аллоҳдан қўрқаман.",112,6],["إِ[g[نّ][o[ِىٓ] أُرِيدُ أَ[f:3506[ن ت]َب[o[ُو]ٓأَ بِإِثْمِى وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَ[n[ـٰ]بِ [h:3507[ٱ][l[ل][g[نّ]َارِ‌ۚ وَذ[n[َٲ]لِكَ جَز[o[َٲ]ٓؤُ[s[اْ] [h:3508[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Мен, албатта, менинг ҳам гуноҳимни, ўзингнинг ҳам гуноҳингни олиб кетишингни, шу сабабдан дўзах аҳлидан бўлишингни хоҳлайман. Ана ўша золимларнинг жазосидир», деди.",112,6],["فَطَوَّعَتْ لَهُ[n[ۥ] نَفْسُهُ[n[ۥ] قَتْلَ أَخِيهِ فَقَتَلَهُ[n[ۥ] فَأَصْبَحَ مِنَ [h:340[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","Нафси унга биродарини ўлдиришни яхши кўрсатди. Бас, уни ўлдирди. Шу сабабдан зиёнкорлардан бўлди.",112,6],["فَبَعَثَ [h:1161[ٱ]للَّهُ غُرَا[a:3509[بًا ي]َ[q:3510[بْ]حَثُ فِى [h:44[ٱ]لْأَرْضِ لِيُرِيَهُ[n[ۥ] كَيْفَ يُو[n[َٲ]رِى سَوْءَةَ أَخِيهِ‌ۚ قَالَ يَ[n[ـٰ]وَيْلَتَ[o[ىٰٓ] أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَ[n[ـٰ]ذَا [h:3511[ٱ]لْغُرَابِ فَأُو[n[َٲ]رِىَ سَوْءَةَ أَخِى‌ۖ فَأَصْبَحَ مِنَ [h:3512[ٱ][l[ل][g[نّ]َ[n[ـٰ]دِم[p[ِي]نَ","Аллоҳ ер юзида кезиб юрган қарғани унга биродарининг ўлигини қандай кўмишини кўрсатиш учун юборди. У: «Шўрим қурсин! Мана шу қарғачалик бўлиб, биродарим ўлигини кўма олмадим-а?!» деди. Бас, у надомат қилувчилардан бўлди.",112,6],["مِنْ أَ[q:3513[جْ]لِ ذ[n[َٲ]لِكَ كَتَ[q:2889[بْ]نَا عَلَىٰ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ أَ[g[نّ]َهُ[n[ۥ] مَ[f:3514[ن ق]َتَلَ نَفْس[i:3515[َۢا ب]ِغَيْرِ نَفْسٍ أَوْ فَسَا[f:3516[دٍ ف]ِى [h:44[ٱ]لْأَرْضِ فَكَأَ[g[نّ]َمَا قَتَلَ [h:3517[ٱ][l[ل][g[نّ]َاسَ جَمِي[a:3518[عًا و]َمَنْ أَحْيَاهَا فَكَأَ[g[نّ]َم[o[َآ] أَحْيَا [h:3519[ٱ][l[ل][g[نّ]َاسَ جَمِي[a:3520[عًا‌ۚ و]َلَقَ[q:341[دْ] ج[o[َا]ٓءَتْهُمْ رُسُلُنَا بِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ ثُ[g[مّ]َ إِ[g[نّ]َ كَثِي[a:3521[رًا م]ِّنْه[c:3522[ُم ب]َعْدَ ذ[n[َٲ]لِكَ فِى [h:44[ٱ]لْأَرْضِ لَمُسْرِف[p[ُو]نَ","Шунинг учун ҳам Бани Исроилга: «Ким бир жонни ноҳақдан ёки ер юзида фасод қилмаса ҳам ўлдирса, худди ҳамма одамларни ўлдирган бўлади. Ким уни тирилтирса, худди ҳамма одамларни тирилтиргандек бўлади», деб ёздик. Батаҳқиқ, уларга Пайғамбарларимиз баёнотлар олиб келдилар. Сўнгра, бундан кейин ҳам, улардан кўплари ер юзида исроф қилгувчилардан бўлдилар.",113,6],["إِ[g[نّ]َمَا جَز[o[َٲ]ٓؤُ[s[اْ] [h:3523[ٱ]لَّذِينَ يُحَارِبُونَ [h:3524[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] وَيَسْعَوْنَ فِى [h:44[ٱ]لْأَرْضِ فَسَادًا أ[a:3525[َن ي]ُقَتَّل[o[ُوٓ][s[اْ] أَوْ يُصَلَّب[o[ُوٓ][s[اْ] أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُه[w:3526[ُم م]ِّنْ خِلَ[n[ـٰ]فٍ أَوْ يُ[f:3527[نف]َوْ[s[اْ] مِنَ [h:1579[ٱ]لْأَرْضِ‌ۚ ذ[n[َٲ]لِكَ لَهُمْ خِزْ[f:440[ىٌ ف]ِى [h:599[ٱ][l[ل]دُّنْيَا‌ۖ وَلَهُمْ فِى [h:536[ٱ]لْأَخِرَةِ عَذَابٌ عَظ[p[ِي]مٌ","Аллоҳга ва Унинг Пайғамбарига қарши уруш қилувчилар, ер юзида фасод қилувчиларнинг жазоси, албатта, ўлдирилмоқлари ёки осилмоқлари ёхуд қўл-оёқлари қарама-қарши томондан кесилмоғи ёки ер юзида сургун қилинмоқларидир. Бу уларга бу дунёда ор бўлур. Охиратда эса, уларга улкан азоб бор.",113,6],["إِلَّا [h:778[ٱ]لَّذِينَ تَابُو[s[اْ] مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أَ[f:3528[ن ت]َ[q:3529[قْ]دِرُو[s[اْ] عَلَيْهِمْ‌ۖ فَ[h:1140[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Магар, уларга қодир бўлишингиздан олдин тавба қилсалар, билингки, албатта, Аллоҳ мағфиратли ва раҳмли зотдир.",113,6],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:1643[ٱ]تَّقُو[s[اْ] [h:1644[ٱ]للَّهَ وَ[h:988[ٱ][q:988[بْ]تَغ[o[ُوٓ][s[اْ] إِلَيْهِ [h:3530[ٱ]لْوَسِيلَةَ وَجَ[n[ـٰ]هِدُو[s[اْ] فِى سَبِيلِه[n[ِۦ] لَعَلَّكُمْ تُفْلِح[p[ُو]نَ","Эй иймон келтирганлар! Аллоҳга тақво қилинглар ва Унга васийла ахтарингиз ҳамда Унинг йўлида жиҳод қилингиз. Шоядки, ютуққа эришсангиз.",113,6],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَوْ أَ[g[نّ]َ لَه[w:3531[ُم م]َّا فِى [h:44[ٱ]لْأَرْضِ جَمِي[a:3532[عًا و]َمِثْلَهُ[n[ۥ] مَعَهُ[n[ۥ] لِيَفْتَدُو[s[اْ] بِه[n[ِۦ] مِنْ عَذَابِ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ مَا تُقُبِّلَ مِنْهُمْ‌ۖ وَلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Агар куфр келтирганлар қўлида ер юзидаги ҳамма нарса ва яна шунча нарса бўлсаю уни қиёмат кунининг азобидан қутулишга тўлов қилиб берсалар ҳам, улардан қабул қилинмас. Уларга аламли азоб бор.",113,6],["يُرِيدُونَ أ[a:3533[َن ي]َخْرُجُو[s[اْ] مِنَ [h:869[ٱ][l[ل][g[نّ]َارِ وَمَا ه[c:868[ُم ب]ِخَ[n[ـٰ]رِجِينَ مِنْهَا‌ۖ وَلَهُمْ عَذَا[a:3534[بٌ م]ُّق[p[ِي]مٌ","Улар дўзахдан чиқмоқчи бўлурлар. Аммо ундан чиқа олмаслар. Уларга муқим азоб бор.",114,6],["وَ[h:9999[ٱ][l[ل]سَّارِقُ وَ[h:3535[ٱ][l[ل]سَّارِقَةُ فَ[h:3536[ٱ][q:3536[قْ]طَع[o[ُوٓ][s[اْ] أَيْدِيَهُمَا جَز[o[َا]ٓ[i:3537[ءَۢ ب]ِمَا كَسَبَا نَكَ[n[ـٰ]ل[a:3538[اً م]ِّنَ [h:321[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ عَزِيزٌ حَك[p[ِي]مٌ","Ўғри эркак ва ўғри аёлнинг қўлларини кесинглар. Бу уларнинг қилмишига жазо ва Аллоҳдан ъиқобдир. Аллоҳ азиз ва ҳакимдир.",114,6],["فَمَ[f:3539[ن ت]َابَ م[i:146[ِنۢ ب]َعْدِ ظُلْمِه[n[ِۦ] وَأَصْلَحَ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ يَتُوبُ عَلَيْهِ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Ким зулмидан кейин тавба этса ва амали солиҳ қилса, Аллоҳ албатта тавбасини қабул қилади. Шубҳасиз, Аллоҳ мағфиратли ва раҳмли зотдир.",114,6],["أَلَمْ تَعْلَمْ أَ[g[نّ]َ [h:394[ٱ]للَّهَ لَهُ[n[ۥ] مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ يُعَذِّبُ م[a:476[َن ي]َش[o[َا]ٓءُ وَيَغْفِرُ لِم[a:1537[َن ي]َش[o[َا]ٓءُ‌ۗ وَ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Осмонлару ернинг мулки Аллоҳнинг эканлигини, кимни хоҳласа, азоблашини, кимни хоҳласа, мағфират қилишини ва Аллоҳ ҳар бир нарсага қодир эканини билмасмидинг?!",114,6],["۞ يَ[o[ـٰٓ]أَيُّهَا [h:3540[ٱ][l[ل]رَّسُولُ لَا يَحْزُ[f:2435[نك]َ [h:2436[ٱ]لَّذِينَ يُسَ[n[ـٰ]رِعُونَ فِى [h:2437[ٱ]لْكُفْرِ مِنَ [h:523[ٱ]لَّذِينَ قَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا بِأَفْو[n[َٲ]هِهِمْ وَلَمْ تُؤْمِ[f:3541[ن ق]ُلُوبُهُمْ‌ۛ وَمِنَ [h:501[ٱ]لَّذِينَ هَادُو[s[اْ‌ۛ] سَ[g[مّ]َ[n[ـٰ]عُونَ لِلْكَذِبِ سَ[g[مّ]َ[n[ـٰ]عُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ‌ۖ يُحَرِّفُونَ [h:2817[ٱ]لْكَلِمَ م[i:146[ِنۢ ب]َعْدِ مَوَاضِعِه[n[ِۦ]‌ۖ يَقُولُونَ إِنْ أُوتِيتُمْ هَ[n[ـٰ]ذَا فَخُذُوهُ وَإ[u:3542[ِن ل]َّمْ تُؤْتَوْهُ فَ[h:3543[ٱ]حْذَرُو[s[اْ‌ۚ] وَم[a:3544[َن ي]ُرِدِ [h:3545[ٱ]للَّهُ فِتْنَتَهُ[n[ۥ] فَلَ[f:3546[ن ت]َمْلِكَ لَهُ[n[ۥ] مِنَ [h:321[ٱ]للَّهِ شَيْــًٔا‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ لَمْ يُرِدِ [h:3545[ٱ]للَّهُ أ[a:3547[َن ي]ُطَهِّرَ قُلُوبَهُمْ‌ۚ لَهُمْ فِى [h:599[ٱ][l[ل]دُّنْيَا خِزْ[a:600[ىٌ‌ۖ و]َلَهُمْ فِى [h:536[ٱ]لْأَخِرَةِ عَذَابٌ عَظ[p[ِي]مٌ","Эй Пайғамбар! Оғизлари ила, иймон келтирдик, деб қалблари иймон келтирмаганлар ва яҳудий бўлганларнинг куфрга ошиқадиганларидан хафа бўлма. Улар ёлғонни кўп эшитадилар, сенга келмаган қавмлардан ҳам эшитадилар. Сўзларни жойларидан ўзгартирадилар. Улар: «Агар сизга бу берилса, олинглар, агар бу берилмаса, ҳазир бўлинглар», дерлар. Аллоҳ кимни фитнага солишни ирода қилса, унга Аллоҳ томонидан бўладиган бирон нарсани тўса олмассан. Аллоҳ ана ўшаларнинг қалбларини поклашни ирода қилмади. Уларга бу дунёда шармандалик бор. Уларга охиратда улкан азоб бор.",114,6],["سَ[g[مّ]َ[n[ـٰ]عُونَ لِلْكَذِبِ أَكَّ[n[ـٰ]لُونَ لِلسُّحْتِ‌ۚ فَإِ[f:3548[ن ج][o[َا]ٓءُوكَ فَ[h:3549[ٱ]حْك[c:3550[ُم ب]َيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ‌ۖ وَإِ[f:3551[ن ت]ُعْرِضْ عَنْهُمْ فَل[a:3552[َن ي]َضُرُّوكَ شَيْـ[a:3553[ـًٔا‌ۖ و]َإِنْ حَكَمْتَ فَ[h:3549[ٱ]حْك[c:3550[ُم ب]َيْنَه[c:3554[ُم ب]ِ[h:1800[ٱ]لْقِسْطِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُحِبُّ [h:3555[ٱ]لْمُ[q:3556[قْ]سِط[p[ِي]نَ","Улар ёлғонни кўп эшитувчилар, ҳаромни кўп еювчилардир. Агар сенга келсалар, ораларида ҳукм чиқар ёки улардан юз ўгир. Агар улардан юз ўгирсанг, сенга ҳеч зарар келтира олмаслар. Агар ҳукм қилсанг, ораларида адолат ила ҳукм қил. Албатта, Аллоҳ адолат қилувчиларни севади.",115,6],["وَكَيْفَ يُحَكِّمُونَكَ وَعِ[f:3557[ند]َهُمُ [h:3558[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةُ فِيهَا حُكْمُ [h:3559[ٱ]للَّهِ ثُ[g[مّ]َ يَتَوَلَّوْنَ م[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ‌ۚ وَم[o[َآ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ بِ[h:3560[ٱ]لْمُؤْمِن[p[ِي]نَ","Ўзларида Таврот бўла туриб, унда Аллоҳнинг ҳукми бўла туриб, қандай қилиб сени ҳакам қиладилару сўнгра яна юз ўгириб кетарлар? Улар мўмин эмаслар.",115,6],["إِ[g[نّ][o[َآ] أَ[f:515[نز]َلْنَا [h:3561[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةَ فِيهَا هُ[a:3562[دًى و]َنُو[a:3563[رٌ‌ۚ ي]َحْكُمُ بِهَا [h:3564[ٱ][l[ل][g[نّ]َبِيُّونَ [h:3565[ٱ]لَّذِينَ أَسْلَمُو[s[اْ] لِلَّذِينَ هَادُو[s[اْ] وَ[h:3566[ٱ][l[ل]رَّبَّ[n[ـٰ]نِيُّونَ وَ[h:3567[ٱ]لْأَحْبَارُ بِمَا [h:3568[ٱ]سْتُحْفِظُو[s[اْ] مِ[f:3569[ن ك]ِتَ[n[ـٰ]بِ [h:1816[ٱ]للَّهِ وَكَانُو[s[اْ] عَلَيْهِ شُهَد[o[َا]ٓءَ‌ۚ فَلَا تَخْشَوُ[s[اْ] [h:3570[ٱ][l[ل][g[نّ]َاسَ وَ[h:3382[ٱ]خْشَوْنِ وَلَا تَشْتَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِى ثَمَ[f:208[نًا ق]َلِيل[a:3571[اً‌ۚ و]َم[u:1416[َن ل]َّمْ يَحْك[c:3572[ُم ب]ِم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:3251[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Биз Тавротни нозил қилдик. Унда ҳидоят ва нур бор. У билан У зотга таслим бўлган Пайғамбарлар, Аллоҳнинг китобини муҳофаза қилишга мукаллаф бўлган роббонийлар ва аҳборлар яҳудий бўлганларга ҳукм юритарлар. Улар бу китобга гувоҳ қилинганлар. Одамлардан қўрқманглар, Мендан қўрқинглар. Менинг оятларимни арзон баҳога сотманглар. Ким Аллоҳ нозил қилган нарса ила ҳукм юритмаса, ўшалар кофирлардир.",115,6],["وَكَتَ[q:3573[بْ]نَا عَلَيْهِمْ فِيه[o[َآ] أَ[g[نّ]َ [h:3574[ٱ][l[ل][g[نّ]َفْسَ بِ[h:3575[ٱ][l[ل][g[نّ]َفْسِ وَ[h:3576[ٱ]لْعَيْنَ بِ[h:3577[ٱ]لْعَيْنِ وَ[h:3578[ٱ]لْأَ[f:3578[نف]َ بِ[h:3579[ٱ]لْأَ[f:3579[نف]ِ وَ[h:3580[ٱ]لْأُذُنَ بِ[h:3581[ٱ]لْأُذُنِ وَ[h:3582[ٱ][l[ل]سِّ[g[نّ]َ بِ[h:3583[ٱ][l[ل]سِّ[g[نّ]ِ وَ[h:3584[ٱ]لْجُرُوحَ قِصَا[f:3585[صٌ‌ۚ ف]َمَ[f:3586[ن ت]َصَدَّقَ بِه[n[ِۦ] فَهُوَ كَفَّارَ[u:3587[ةٌ ل]َّهُ[n[ۥ]‌ۚ وَم[u:1416[َن ل]َّمْ يَحْك[c:3572[ُم ب]ِم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:1285[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Биз унда уларга жонга–жон, кўзга–кўз, бурунга–бурун, қулоққа–қулоқ, тишга–тиш ва жароҳатларда қасос вожиб, деб ёздик. Ким уни кечиб юборса, бу унга каффоротдир. Ким Аллоҳ нозил қилган нарса ила ҳукм юритмаса, ўшалар золимлардир.",115,6],["وَقَفَّيْنَا عَلَ[o[ىٰٓ] ءَاثَ[n[ـٰ]رِه[c:3588[ِم ب]ِعِيسَى [h:3589[ٱ][q:3590[بْ]نِ مَرْيَمَ مُصَدِّ[u:206[قًا ل]ِّمَا بَيْنَ يَدَيْهِ مِنَ [h:1941[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةِ‌ۖ وَءَاتَيْنَ[n[ـٰ]هُ [h:3591[ٱ]لْإِ[f:3592[نج]ِيلَ فِيهِ هُ[a:3562[دًى و]َنُو[a:3593[رٌ و]َمُصَدِّ[u:1940[قًا ل]ِّمَا بَيْنَ يَدَيْهِ مِنَ [h:1941[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةِ وَهُ[a:3594[دًى و]َمَوْعِظَ[u:348[ةً ل]ِّلْمُتَّق[p[ِي]نَ","Уларнинг изларидан Ийсо ибн Марямни ўзидан олдинги Тавротни тасдиқловчи қилиб юбордик. Унга Инжилни бердик. Унда ҳидоят ва нур бор. У ўзидан олдинги Тавротни тасдиқлагувчидир. У тақводорлар учун ҳидоят ва мавъизадир.",116,6],["وَلْيَحْكُمْ أَهْلُ [h:3595[ٱ]لْإِ[f:3596[نج]ِيلِ بِم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ فِيهِ‌ۚ وَم[u:1416[َن ل]َّمْ يَحْك[c:3572[ُم ب]ِم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:2071[ٱ]لْفَ[n[ـٰ]سِق[p[ُو]نَ","Инжил аҳли унда Аллоҳ нозил қилган нарса ила ҳукм юритсинлар. Ким Аллоҳ нозил қилган нарса ила ҳукм юритмаса, ана ўшалар фосиқлардир.",116,6],["وَأَ[f:271[نز]َلْن[o[َآ] إِلَيْكَ [h:3102[ٱ]لْكِتَ[n[ـٰ]بَ بِ[h:370[ٱ]لْحَقِّ مُصَدِّ[u:206[قًا ل]ِّمَا بَيْنَ يَدَيْهِ مِنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ وَمُهَيْمِنًا عَلَيْهِ‌ۖ فَ[h:3549[ٱ]حْك[c:3550[ُم ب]َيْنَه[c:3597[ُم ب]ِم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ‌ۖ وَلَا تَتَّبِعْ أَهْو[o[َا]ٓءَهُمْ عَ[g[مّ]َا ج[o[َا]ٓءَكَ مِنَ [h:1173[ٱ]لْحَقِّ‌ۚ لِكُ[f:3598[لٍّ ج]َعَلْنَا مِ[f:344[نك]ُمْ شِرْعَ[a:3599[ةً و]َمِنْهَا[a:3600[جًا‌ۚ و]َلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ لَجَعَلَكُمْ أُ[g[مّ]َ[a:1159[ةً و][n[َٲ]حِدَ[a:3601[ةً و]َلَ[n[ـٰ]ك[u:3602[ِن ل]ِّيَ[q:3603[بْ]لُوَكُمْ فِى م[o[َآ] ءَاتَ[n[ـٰ]كُمْ‌ۖ فَ[h:774[ٱ]سْتَبِقُو[s[اْ] [h:775[ٱ]لْخَيْر[n[َٲ]تِ‌ۚ إِلَى [h:1637[ٱ]للَّهِ مَرْجِعُكُمْ جَمِي[f:3604[عًا ف]َيُنَبِّئُك[c:3605[ُم ب]ِمَا كُ[f:100[نت]ُمْ فِيهِ تَخْتَلِف[p[ُو]نَ","Ва Биз сенга китобни ҳақ ила, ўзидан олдинги китобни тасдиқловчи ва унинг устидан назорат этгувчи қилиб нозил қилдик. Бас, улар орасида Аллоҳ нозил этган нарса ила ҳукм юрит. Ўзингга келган ҳақни қўйиб, уларнинг хоҳишларига эргашма. Сизлардан ҳар бирингизга алоҳида шариат ва йўл қилиб қўйдик. Агар Аллоҳ хоҳласа, ҳаммангизни бир уммат қилиб қўяр эди. Аммо У сизларни Ўзи ато этган нарсада синамоқ истайдир. Яхшиликка шошилингиз. Ҳаммангизнинг қайтар жойингиз Аллоҳ ҳузурида. Бас, ўшанда ихтилоф қилган нарсаларингиз ҳақида хабар берадир.",116,6],["وَأَنِ [h:3606[ٱ]حْك[c:3607[ُم ب]َيْنَه[c:3597[ُم ب]ِم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ وَلَا تَتَّبِعْ أَهْو[o[َا]ٓءَهُمْ وَ[h:3608[ٱ]حْذَرْهُمْ أ[a:3609[َن ي]َفْتِنُوكَ ع[i:3610[َنۢ ب]َعْضِ م[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ إِلَيْكَ‌ۖ فَإِ[f:1857[ن ت]َوَلَّوْ[s[اْ] فَ[h:3611[ٱ]عْلَمْ أَ[g[نّ]َمَا يُرِيدُ [h:976[ٱ]للَّهُ أ[a:3612[َن ي]ُصِيبَه[c:3613[ُم ب]ِبَعْضِ ذُنُوبِهِمْ‌ۗ وَإِ[g[نّ]َ كَثِي[a:3614[رًا م]ِّنَ [h:721[ٱ][l[ل][g[نّ]َاسِ لَفَ[n[ـٰ]سِق[p[ُو]نَ","Улар орасида Аллоҳ нозил этган нарса ила ҳукм юрит. Уларнинг хоҳишларига эргашма ва улар сени Аллоҳ сенга нозил қилган нарсада фитнага солишларидан ҳазир бўл. Агар юз ўгирсалар, билки, Аллоҳ уларни баъзи гуноҳлари туфайли мусибатга солишни ирода қилибди. Албатта, одамлардан кўплари фосиқлардир.",116,6],["أَفَحُكْمَ [h:3615[ٱ]لْجَ[n[ـٰ]هِلِيَّةِ يَ[q:2073[بْ]غُونَ‌ۚ وَمَنْ أَحْسَنُ مِنَ [h:321[ٱ]للَّهِ حُكْ[u:3616[مًا ل]ِّقَوْ[a:621[مٍ ي]ُوقِن[p[ُو]نَ","Жоҳилият ҳукмини истайдиларми?! Ишончи комил қавмлар учун Аллоҳдан ҳукми яхшироқ ким бор?!",116,6],["۞ يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَتَّخِذُو[s[اْ] [h:3617[ٱ]لْيَهُودَ وَ[h:326[ٱ][l[ل][g[نّ]َصَ[n[ـٰ]رَ[o[ىٰٓ] أَوْلِي[o[َا]ٓءَ‌ۘ بَعْضُهُمْ أَوْلِي[o[َا]ٓءُ بَعْ[a:3618[ضٍ‌ۚ و]َم[a:3619[َن ي]َتَوَلَّه[w:3620[ُم م]ِّ[f:344[نك]ُمْ فَإِ[g[نّ]َهُ[n[ۥ] مِنْهُمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Эй иймон келтирганлар! Яҳудий ва насороларни ўзингизга дўст тутманг. Улар бир-бирлари билан дўстдирлар. Сиздан ким уларни дўст тутса, алббатта, у улардандир. Албатта, Аллоҳ золим қавмларни ҳидоят этмас.",117,6],["فَتَرَى [h:3621[ٱ]لَّذِينَ فِى قُلُوبِه[w:39[ِم م]َّرَ[a:3622[ضٌ ي]ُسَ[n[ـٰ]رِعُونَ فِيهِمْ يَقُولُونَ نَخْشَ[o[ىٰٓ] أَ[f:3623[ن ت]ُصِيبَنَا د[o[َا]ٓئِرَ[f:3624[ةٌ‌ۚ ف]َعَسَى [h:3625[ٱ]للَّهُ أ[a:1462[َن ي]َأْتِىَ بِ[h:3626[ٱ]لْفَتْحِ أَوْ أَمْ[a:3627[رٍ م]ِّنْ عِ[f:3628[ند]ِه[n[ِۦ] فَيُصْبِحُو[s[اْ] عَلَىٰ م[o[َآ] أَسَرُّو[s[اْ] ف[o[ِىٓ] أَ[f:568[نف]ُسِهِمْ نَ[n[ـٰ]دِم[p[ِي]نَ","Қалбларида касаллик борларнинг, замон айланиб бизга мусибат етишидан қўрқамиз, деб улар томон шошилганини кўрасан. Шоядки, Аллоҳ фатҳу нусрат берса ёки Ўз томонидан бирон иш ато қилсаю ўзларича сирлашган нарсаларига надомат қилсалар.",117,6],["وَيَقُولُ [h:3629[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَهَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ [h:3630[ٱ]لَّذِينَ أَ[q:3631[قْ]سَمُو[s[اْ] بِ[h:32[ٱ]للَّهِ جَهْدَ أَيْمَ[n[ـٰ]نِهِمْ‌ۙ إِ[g[نّ]َهُمْ لَمَعَكُمْ‌ۚ حَبِطَتْ أَعْمَ[n[ـٰ]لُهُمْ فَأَصْبَحُو[s[اْ] خَ[n[ـٰ]سِر[p[ِي]نَ","Иймон келтирганлар: «Ўзларини сизлар билан деб Аллоҳнинг номи ила жон-жаҳдлари ила қасам ичганлар анавиларми?» дейишади. Амаллари бехуда кетди. Бас, зиён кўргувчилардан бўлдилар.",117,6],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] م[a:3632[َن ي]َرْتَدَّ مِ[f:344[نك]ُمْ عَ[f:1211[ن د]ِينِه[n[ِۦ] فَسَوْفَ يَأْتِى [h:3633[ٱ]للَّهُ بِقَوْ[a:3634[مٍ ي]ُحِبُّهُمْ وَيُحِبُّونَهُ[o[ۥٓ] أَذِلَّةٍ عَلَى [h:2329[ٱ]لْمُؤْمِنِينَ أَعِزَّةٍ عَلَى [h:468[ٱ]لْكَ[n[ـٰ]فِرِينَ يُجَ[n[ـٰ]هِدُونَ فِى سَبِيلِ [h:788[ٱ]للَّهِ وَلَا يَخَافُونَ لَوْمَةَ ل[o[َا]ٓئِ[f:3635[مٍ‌ۚ ذ][n[َٲ]لِكَ فَضْلُ [h:337[ٱ]للَّهِ يُؤْتِيهِ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَ[h:72[ٱ]للَّهُ و[n[َٲ]سِعٌ عَل[p[ِي]مٌ","Эй иймон келтирганлар! Сизлардан ким динидан қайтса, Аллоҳ албатта Ўзи севадиган ва улар ҳам Аллоҳни севадиган қавмни келтиради. Улар мўминларга хокисор, кофирларга қаттиққўл, Аллоҳнинг йўлида жиҳод қиларлар ва маломатчининг маломатидан қўрқмаслар. Бу Аллоҳнинг фазли бўлиб, хоҳлаган одамига беради. Аллоҳ фазли-карами кенг ва билувчи зотдир.",117,6],["إِ[g[نّ]َمَا وَلِيُّكُمُ [h:3636[ٱ]للَّهُ وَرَسُولُهُ[n[ۥ] وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:3637[ٱ]لَّذِينَ يُقِيمُونَ [h:3638[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَيُؤْتُونَ [h:3639[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَهُمْ ر[n[َٲ]كِع[p[ُو]نَ","Албатта, сизнинг валийларингиз Аллоҳ, Унинг Пайғамбари ва бўйинсунган ҳолларида намозни қоим қилиб, закотни ато этадиган иймон келтирганлардир.",117,6],["وَم[a:3640[َن ي]َتَوَلَّ [h:3641[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] فَإِ[g[نّ]َ حِزْبَ [h:3642[ٱ]للَّهِ هُمُ [h:3643[ٱ]لْغَ[n[ـٰ]لِب[p[ُو]نَ","Ким Аллоҳни, Унинг Пайғамбарини ва иймон келтирганларни валий қилиб олса, бас, албатта, Аллоҳнинг ҳизби–ана ўшалар ғолиблардир.",117,6],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَتَّخِذُو[s[اْ] [h:3644[ٱ]لَّذِينَ [h:3645[ٱ]تَّخَذُو[s[اْ] دِينَكُمْ هُزُ[a:3646[وًا و]َلَعِ[a:3647[بًا م]ِّنَ [h:523[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ وَ[h:3648[ٱ]لْكُفَّارَ أَوْلِي[o[َا]ٓءَ‌ۚ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Эй иймон келтирганлар! Динингизни масхара ва ўйин қилиб олган сиздан олдин китоб берилганлар ва куфр келтирганларни валий-дўст тутманг. Агар мўмин бўлсангиз, Аллоҳга тақво қилинг.",117,6],["وَإِذَا نَادَيْتُمْ إِلَى [h:3225[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ [h:3649[ٱ]تَّخَذُوهَا هُزُ[a:3646[وًا و]َلَعِ[f:3650[بًا‌ۚ ذ][n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ قَوْ[u:3651[مٌ ل]َّا يَعْقِل[p[ُو]نَ","Агар намозга нидо қилсангиз, улар уни масхара ва ўйин қилишади. Бу уларнинг ақл қилмайдиган қавмлигидандир.",118,6],["قُلْ يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ هَلْ تَ[f:3652[نق]ِمُونَ مِ[g[نّ][o[َآ] إِلّ[o[َآ] أَنْ ءَامَ[g[نّ]َا بِ[h:32[ٱ]للَّهِ وَم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْنَا وَم[o[َآ] أُ[f:17[نز]ِلَ مِ[f:128[ن ق]َ[q:129[بْ]لُ وَأَ[g[نّ]َ أَكْثَرَكُمْ فَ[n[ـٰ]سِق[p[ُو]نَ","Сен: «Эй аҳли китоблар! Бизни фақат Аллоҳга ҳамда ўзимизга нозил қилинган ва авваллари нозил қилинган нарсаларга иймон келтирганимиз учун ва сизларнинг кўпчилигингиз фосиқ бўлганингиз учун айблайсизларми?!» деб айт.",118,6],["قُلْ هَلْ أُنَبِّئُك[c:3653[ُم ب]ِشَ[a:3654[رٍّ م]ِّ[f:2624[ن ذ][n[َٲ]لِكَ مَثُوبَةً عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۚ م[u:3655[َن ل]َّعَنَهُ [h:3140[ٱ]للَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ [h:3656[ٱ]لْقِرَدَةَ وَ[h:3657[ٱ]لْخَنَازِيرَ وَعَبَدَ [h:3658[ٱ][l[ل]طَّ[n[ـٰ]غُوتَ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ شَ[a:3659[رٌّ م]َّكَا[a:3660[نًا و]َأَضَلُّ عَ[f:3661[ن س]َو[o[َا]ٓءِ [h:3662[ٱ][l[ل]سَّب[p[ِي]لِ","Сен: «Сизларга Аллоҳнинг ҳузуридаги бундан ҳам кўра ёмонроқ «савоб»нинг хабарини берайми? Ким Аллоҳнинг лаънатига учраган, ғазабига дучор бўлган, маймун ва чўчқага айлантирилган ва тоғутга ибодат қилган бўлса, ана ўшалар ёмон мартабадаги ва тўғри йўлдан бутунлай адашган кимсалардир», деб айт!",118,6],["وَإِذَا ج[o[َا]ٓءُوكُمْ قَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا وَقَد دَّخَلُو[s[اْ] بِ[h:2055[ٱ]لْكُفْرِ وَهُمْ قَ[q:298[دْ] خَرَجُو[s[اْ] بِه[n[ِۦ]‌ۚ وَ[h:72[ٱ]للَّهُ أَعْلَمُ بِمَا كَانُو[s[اْ] يَكْتُم[p[ُو]نَ","Улар ҳузурингизга келсалар, иймон келтирдик, дерлар. Ҳолбуки, уларнинг куфр ила кириб, куфр ила чиқишлари шубҳасиз. Аллоҳ улар беркитган нарсани яхши биладир.",118,6],["وَتَرَىٰ كَثِي[a:3521[رًا م]ِّنْهُمْ يُسَ[n[ـٰ]رِعُونَ فِى [h:3663[ٱ]لْإِثْمِ وَ[h:435[ٱ]لْعُ[q:435[دْ]و[n[َٲ]نِ وَأَكْلِهِمُ [h:3664[ٱ][l[ل]سُّحْتَ‌ۚ لَبِئْسَ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Ва улардан кўпларининг гуноҳга, душманликка ва ҳаром емоққа ошиқаётганини кўрасан. Қилаётган ишлари қандай ҳам ёмон!",118,6],["لَوْلَا يَنْهَ[n[ـٰ]هُمُ [h:3665[ٱ][l[ل]رَّبَّ[n[ـٰ]نِيُّونَ وَ[h:3567[ٱ]لْأَحْبَارُ عَ[f:3666[ن ق]َوْلِهِمُ [h:3667[ٱ]لْإِثْمَ وَأَكْلِهِمُ [h:3664[ٱ][l[ل]سُّحْتَ‌ۚ لَبِئْسَ مَا كَانُو[s[اْ] يَصْنَع[p[ُو]نَ","Роббонийлари ва аҳборлари уларни гуноҳ айтиш ва ҳаромни ейишдан қайтарсалар бўлмасми?! Қилаётган ҳунарлари қандай ҳам ёмон-а!",118,6],["وَقَالَتِ [h:583[ٱ]لْيَهُودُ يَدُ [h:3668[ٱ]للَّهِ مَغْلُولَةٌ‌ۚ غُلَّتْ أَيْدِيهِمْ وَلُعِنُو[s[اْ] بِمَا قَالُو[s[اْ‌ۘ] بَلْ يَدَاهُ مَ[q:3669[بْ]سُوطَتَانِ يُ[f:1550[نف]ِقُ كَيْفَ يَش[o[َا]ٓءُ‌ۚ وَلَيَزِيدَ[g[نّ]َ كَثِي[a:3521[رًا م]ِّنْه[w:3670[ُم م]ّ[o[َآ] أُ[f:17[نز]ِلَ إِلَيْكَ م[u:770[ِن ر]َّبِّكَ طُغْيَ[n[ـٰ][a:3671[نًا و]َكُفْ[a:3672[رًا‌ۚ و]َأَلْقَيْنَا بَيْنَهُمُ [h:3434[ٱ]لْعَد[n[َٲ]وَةَ وَ[h:3435[ٱ]لْبَغْض[o[َا]ٓءَ إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۚ كُلَّم[o[َآ] أَوْقَدُو[s[اْ] نَا[u:3673[رًا ل]ِّلْحَرْبِ أَ[q:3674[طْ]فَأَهَا [h:3675[ٱ]للَّهُ‌ۚ وَيَسْعَوْنَ فِى [h:44[ٱ]لْأَرْضِ فَسَا[a:3676[دًا‌ۚ و]َ[h:72[ٱ]للَّهُ لَا يُحِبُّ [h:3677[ٱ]لْمُفْسِد[p[ِي]نَ","Яҳудийлар: «Аллоҳнинг қўли боғлиқдир», дедилар. Қўллари боғлсин уларнинг. Айтганлари учун лаънатга учрасинлар. Балки Аллоҳнинг икки қўли очиқ, хоҳлаганича нафақа қилар. Сенга Роббингдан нозил қилинган нарса улардан кўпларининг туғён ва куфрини зиёда қилар. Уларнинг орасига қиёмат кунигача душманлик ва ёмон кўришни солдик. Улар қачон уруш оловини ёқсалар, Аллоҳ ўчирар. Улар ер юзида фасод қилиб юрарлар. Аллоҳ фасод қилгувчиларни севмас.",118,6],["وَلَوْ أَ[g[نّ]َ أَهْلَ [h:3678[ٱ]لْكِتَ[n[ـٰ]بِ ءَامَنُو[s[اْ] وَ[h:538[ٱ]تَّقَوْ[s[اْ] لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔـاتِهِمْ وَلَأَ[q:3679[دْ]خَلْنَ[n[ـٰ]هُمْ جَ[g[نّ]َ[n[ـٰ]تِ [h:3680[ٱ][l[ل][g[نّ]َع[p[ِي]مِ","Агар аҳли китоблар иймон келтириб, тақво қилганларида эди, уларнинг гуноҳларини ювган ва жаннати наъимга киритган бўлардик.",119,6],["وَلَوْ أَ[g[نّ]َهُمْ أَقَامُو[s[اْ] [h:3681[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةَ وَ[h:1725[ٱ]لْإِ[f:1725[نج]ِيلَ وَم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْه[w:3682[ِم م]ّ[u:22[ِن ر]َّبِّهِمْ لَأَكَلُو[s[اْ] مِ[f:3683[ن ف]َوْقِهِمْ وَمِ[f:3684[ن ت]َحْتِ أَرْجُلِه[w:3685[ِم‌ۚ م]ِّنْهُمْ أُ[g[مّ]َ[a:3686[ةٌ م]ُّ[q:3687[قْ]تَصِدَ[a:3688[ةٌ‌ۖ و]َكَثِي[a:3689[رٌ م]ِّنْهُمْ س[o[َا]ٓءَ مَا يَعْمَل[p[ُو]نَ","Агар улар Тавротга, Инжилга ва уларга Роббиларидан нозил бўлган нарсага амал қилганларида эди, албатта, тепаларидан ҳам, оёқлари остидан ҳам еган бўлардилар. Улардан мўътадил тоифалар ҳам бор. Уларнинг кўпларининг қилган нарсалари жуда ҳам ёмон.",119,6],["۞ يَ[o[ـٰٓ]أَيُّهَا [h:3540[ٱ][l[ل]رَّسُولُ بَلِّغْ م[o[َآ] أُ[f:17[نز]ِلَ إِلَيْكَ م[u:770[ِن ر]َّبِّكَ‌ۖ وَإ[u:3542[ِن ل]َّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ[n[ۥ]‌ۚ وَ[h:72[ٱ]للَّهُ يَعْصِمُكَ مِنَ [h:721[ٱ][l[ل][g[نّ]َاسِ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1557[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Эй Пайғамбар! Сенга Роббингдан нозил қилинган нарсани етказ. Агар шундай қилмасанг, Унинг элчилигини етказмаган бўласан. Аллоҳ сени одамлардан сақлайдир. Албатта, Аллоҳ кофир қавмларни ҳидоят қилмас.",119,6],["قُلْ يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ لَسْتُمْ عَلَىٰ شَىْءٍ حَتَّىٰ تُقِيمُو[s[اْ] [h:3690[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةَ وَ[h:1725[ٱ]لْإِ[f:1725[نج]ِيلَ وَم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْك[w:3691[ُم م]ّ[u:243[ِن ر]َّبِّكُمْ‌ۗ وَلَيَزِيدَ[g[نّ]َ كَثِي[a:3521[رًا م]ِّنْه[w:3670[ُم م]ّ[o[َآ] أُ[f:17[نز]ِلَ إِلَيْكَ م[u:770[ِن ر]َّبِّكَ طُغْيَ[n[ـٰ][a:3671[نًا و]َكُفْ[f:3692[رًا‌ۖ ف]َلَا تَأْسَ عَلَى [h:1431[ٱ]لْقَوْمِ [h:1432[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Сен: «Эй аҳли китоблар! Таврот, Инжил ва сизга Роббингиздан нозил қилинган нарсага амал қилмагунларингизгача ҳеч нарсага арзимайсизлар», деб айт. Сенга Роббингдан нозил қилинган нарса улардан кўпларининг туғён ва куфрларини зиёда қилади. Кофир қавмлар учун ачинма.",119,6],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَ[h:37[ٱ]لَّذِينَ هَادُو[s[اْ] وَ[h:3693[ٱ][l[ل]صَّ[n[ـٰ]بِــُٔونَ وَ[h:326[ٱ][l[ل][g[نّ]َصَ[n[ـٰ]رَىٰ مَنْ ءَامَنَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ وَعَمِلَ صَ[n[ـٰ]لِ[f:3694[حًا ف]َلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Албатта, иймон келтирганлар, яҳудий бўлганлар, собиъунлар ва насоролардан ким Аллоҳга ва қиёмат кунига иймон келтирса ва яхши амал қилса, уларга хавф йўқ ва улар хафа ҳам бўлмаслар.",119,6],["لَقَ[q:2389[دْ] أَخَذْنَا مِيثَ[n[ـٰ]قَ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ وَأَرْسَلْن[o[َآ] إِلَيْهِمْ رُسُل[f:3695[اً‌ۖ ك]ُلَّمَا ج[o[َا]ٓءَهُمْ رَسُو[i:455[لُۢ ب]ِمَا لَا تَهْوَ[o[ىٰٓ] أَ[f:2341[نف]ُسُهُمْ فَرِي[f:3696[قًا ك]َذَّبُو[s[اْ] وَفَرِي[a:3697[قًا ي]َ[q:3698[قْ]تُل[p[ُو]نَ","Батаҳқиқ, Биз Бани Исроилдан мийсоқ–аҳднома олдик ва уларга Пайғамбарлар юбордик. Ҳар қачон уларнинг ҳавои нафсларига тўғри келмайдиган нарса келтирган Пайғамбарни: бир гуруҳларини ёлғончи дедилар, бир гуруҳларини ўлдирдилар.",119,6],["وَحَسِب[o[ُوٓ][s[اْ] أَلَّا تَكُونَ فِتْنَ[f:3699[ةٌ ف]َعَمُو[s[اْ] وَصَ[g[مّ]ُو[s[اْ] ثُ[g[مّ]َ تَابَ [h:3700[ٱ]للَّهُ عَلَيْهِمْ ثُ[g[مّ]َ عَمُو[s[اْ] وَصَ[g[مّ]ُو[s[اْ] كَثِي[a:3701[رٌ م]ِّنْهُمْ‌ۚ وَ[h:72[ٱ]للَّهُ بَصِي[i:505[رُۢ ب]ِمَا يَعْمَل[p[ُو]نَ","Улар, ҳеч қандай синов бўлмайди, деб кўру кар бўлиб олдилар. Сўнгра Аллоҳ уларни кечирди. Кейин улардан кўплари яна кўру кар бўлиб олдилар. Аллоҳ уларнинг қилаётганини кўрувчи зотдир.",120,6],["لَقَ[q:2389[دْ] كَفَرَ [h:3446[ٱ]لَّذِينَ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ هُوَ [h:3447[ٱ]لْمَسِيحُ [h:3448[ٱ][q:1917[بْ]نُ مَرْيَمَ‌ۖ وَقَالَ [h:3702[ٱ]لْمَسِيحُ يَ[n[ـٰ]بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ [h:3703[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ رَبِّى وَرَبَّكُمْ‌ۖ إِ[g[نّ]َهُ[n[ۥ] م[a:3705[َن ي]ُشْرِكْ بِ[h:32[ٱ]للَّهِ فَقَ[q:563[دْ] حَرَّمَ [h:3706[ٱ]للَّهُ عَلَيْهِ [h:3707[ٱ]لْجَ[g[نّ]َةَ وَمَأْوَ[n[ٮٰ]هُ [h:3708[ٱ][l[ل][g[نّ]َارُ‌ۖ وَمَا لِلظَّ[n[ـٰ]لِمِينَ مِنْ أَ[f:1600[نص][p[َا]رٍ","Аллоҳ, албатта, Масиҳ ибн Марямдир, деганлар кофир бўлдилар. Масиҳ ибн Марям эса: «Менинг Роббим ва сизнинг Роббингиз Аллоҳга ибодат қилинг. Ким Аллоҳга ширк келтирса, албатта, Аллоҳ унга жаннатни ҳаром қиладир ва унинг турар жойи дўзах бўладир. Ва золимларга нусрат берувчилар йўқдир», деди.",120,6],["لَّقَ[q:2389[دْ] كَفَرَ [h:3446[ٱ]لَّذِينَ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ ثَالِثُ ثَلَ[n[ـٰ]ثَ[a:3709[ةٍ‌ۘ و]َمَا مِنْ إِلَ[n[ـٰ]هٍ إِلّ[o[َآ] إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[a:3710[دٌ‌ۚ و]َإ[u:3542[ِن ل]َّمْ يَ[f:3711[نت]َهُو[s[اْ] عَ[g[مّ]َا يَقُولُونَ لَيَمَسَّ[g[نّ]َ [h:3712[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِنْهُمْ عَذَابٌ أَل[p[ِي]مٌ","Аллоҳ, учтанинг учинчисидир, деганлар, батаҳқиқ, кофир бўлдилар. Ягона илоҳдан ўзга ҳеч қандай илоҳ йўқ! Агар айтаётганларидан қайтмасалар, улардан куфр келтирганларини аламли азоб тутадир.",120,6],["أَفَلَا يَتُوبُونَ إِلَى [h:1637[ٱ]للَّهِ وَيَسْتَغْفِرُونَهُ[n[ۥ]‌ۚ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Аллоҳга тавба қилиб, Унга истиғфор айтмайдиларми?! Зотан, Аллоҳ мағфиратли ва раҳмли зотдир.",120,6],["مَّا [h:3713[ٱ]لْمَسِيحُ [h:3448[ٱ][q:1917[بْ]نُ مَرْيَمَ إِلَّا رَسُو[f:2277[لٌ ق]َ[q:298[دْ] خَلَتْ مِ[f:1097[ن ق]َ[q:1098[بْ]لِهِ [h:2278[ٱ][l[ل]رُّسُلُ وَأُ[g[مّ]ُهُ[n[ۥ] صِدِّيقَ[f:3714[ةٌ‌ۖ ك]َانَا يَأْكُلَانِ [h:3715[ٱ][l[ل]طَّعَامَ‌ۗ [h:3716[ٱ][f:2837[نظ]ُرْ كَيْفَ نُبَيِّنُ لَهُمُ [h:3717[ٱ]لْأَيَ[n[ـٰ]تِ ثُ[g[مّ]َ [h:3718[ٱ][f:2837[نظ]ُرْ أَ[g[نّ]َىٰ يُؤْفَك[p[ُو]نَ","Масиҳ ибн Марям бир Пайғамбар, холос. Ундан олдин ҳам Пайғамбарлар ўтган. Унинг онаси эса, сиддиқадир. Икковлари ҳам таом ер эдилар. Биз уларга оятларни қандай баён қилаётганимизга назар сол-у, кейин уларнинг қандай бурилиб кетаётганларига назар сол.",120,6],["قُلْ أَتَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَر[a:3719[ًّا و]َلَا نَفْ[a:3720[عًا‌ۚ و]َ[h:72[ٱ]للَّهُ هُوَ [h:3721[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Сен: «Аллоҳни қўйиб, сизга зарар ҳам, фойда ҳам бера олмайдиган нарсага ибодат қиласизларми?! Аллоҳ эшитувчи ва билувчи зотдир», деб айт.",120,6],["قُلْ يَ[o[ـٰٓ]أَهْلَ [h:1990[ٱ]لْكِتَ[n[ـٰ]بِ لَا تَغْلُو[s[اْ] فِى دِينِكُمْ غَيْرَ [h:2342[ٱ]لْحَقِّ وَلَا تَتَّبِع[o[ُوٓ][s[اْ] أَهْو[o[َا]ٓءَ قَوْ[f:3722[مٍ ق]َ[q:298[دْ] ضَلُّو[s[اْ] مِ[f:128[ن ق]َ[q:129[بْ]لُ وَأَضَلُّو[s[اْ] كَثِي[a:3723[رًا و]َضَلُّو[s[اْ] عَ[f:3661[ن س]َو[o[َا]ٓءِ [h:3662[ٱ][l[ل]سَّب[p[ِي]لِ","Сен: «Эй аҳли китоблар! Динингизда ҳаддан ошиб, ноҳақлик қилманг. Ва олдин ўзлари адашиб ва кўпчиликни адаштириб, тўғри йўлдан умуман чиққанларнинг ҳавои нафсларига эргашманг», деб айт.",121,6],["لُعِنَ [h:3724[ٱ]لَّذِينَ كَفَرُو[s[اْ] م[i:1385[ِنۢ ب]َن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ عَلَىٰ لِسَانِ دَاوُ[n[ۥ]دَ وَعِيسَى [h:3725[ٱ][q:3590[بْ]نِ مَرْيَمَ‌ۚ ذ[n[َٲ]لِكَ بِمَا عَصَو[s[اْ] وَّكَانُو[s[اْ] يَعْتَد[p[ُو]نَ","Бани Исроилдан куфр келтирганлари Довуд ва Ийсо ибн Марям тилида лаънатландилар. Бу эса, исён қилганлари ва тажовузкор бўлганлари учун бўлди.",121,6],["كَانُو[s[اْ] لَا يَتَنَاهَوْنَ ع[a:3726[َن م]ُّ[f:3727[نك]َ[f:3728[رٍ ف]َعَلُوهُ‌ۚ لَبِئْسَ مَا كَانُو[s[اْ] يَفْعَل[p[ُو]نَ","Улар қилинган ёмон ишдан бир-бирларини қайтармас эдилар. Бу қилмишлари қандай ҳам ёмон бўлди!",121,6],["تَرَىٰ كَثِي[a:3521[رًا م]ِّنْهُمْ يَتَوَلَّوْنَ [h:3729[ٱ]لَّذِينَ كَفَرُو[s[اْ‌ۚ] لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَ[f:2341[نف]ُسُهُمْ أَ[f:3730[ن س]َخِطَ [h:3731[ٱ]للَّهُ عَلَيْهِمْ وَفِى [h:3732[ٱ]لْعَذَابِ هُمْ خَ[n[ـٰ]لِد[p[ُو]نَ","Улардан кўпларининг куфр келтирганларни валий-дўст тутганини кўрасан. Уларга нафслари тақдим қилган нарса қандай ҳам ёмон бўлди. Аллоҳ уларга ғазаб қилди. Ва улар азобда боқий қолувчилардир.",121,6],["وَلَوْ كَانُو[s[اْ] يُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَ[h:3733[ٱ][l[ل][g[نّ]َبِىِّ وَم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْهِ مَا [h:3734[ٱ]تَّخَذُوهُمْ أَوْلِي[o[َا]ٓءَ وَلَ[n[ـٰ]كِ[g[نّ]َ كَثِي[a:3521[رًا م]ِّنْهُمْ فَ[n[ـٰ]سِق[p[ُو]نَ","Агар Аллоҳга, Пайғамбарга ва унга нозил қилинган нарсага иймон келтирганларида эди, уларни валий-дўст тутмас эдилар. Лекин улардан кўплари фосиқлардир.",121,6],["۞ لَتَجِدَ[g[نّ]َ أَشَدَّ [h:3735[ٱ][l[ل][g[نّ]َاسِ عَد[n[َٲ]وَ[u:3736[ةً ل]ِّلَّذِينَ ءَامَنُو[s[اْ] [h:3737[ٱ]لْيَهُودَ وَ[h:37[ٱ]لَّذِينَ أَشْرَكُو[s[اْ‌ۖ] وَلَتَجِدَ[g[نّ]َ أَ[q:3738[قْ]رَبَه[w:3739[ُم م]َّوَدَّ[u:3740[ةً ل]ِّلَّذِينَ ءَامَنُو[s[اْ] [h:3637[ٱ]لَّذِينَ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا نَصَ[n[ـٰ]رَىٰ‌ۚ ذ[n[َٲ]لِكَ بِأَ[g[نّ]َ مِنْهُمْ قِسِّيسِينَ وَرُهْبَا[a:3741[نًا و]َأَ[g[نّ]َهُمْ لَا يَسْتَكْبِر[p[ُو]نَ","Яҳудий ва ширк келтирганларни иймон келтирганларга нисбатан одамларнинг ашаддий адоватлиси эканини топасан. Улардан иймон келтирганларга дўстликка яқинроғи, биз насоролармиз, деганлар эканини топасан. Бу уларнинг ичида диний олимлар ва роҳиблар бўлганидан ва уларнинг такаббурлик қилмасликларидандир.",121,7],["وَإِذَا سَمِعُو[s[اْ] م[o[َآ] أُ[f:17[نز]ِلَ إِلَى [h:2975[ٱ][l[ل]رَّسُولِ تَرَ[o[ىٰٓ] أَعْيُنَهُمْ تَفِيضُ مِنَ [h:3742[ٱ][l[ل]دَّمْعِ مِ[g[مّ]َا عَرَفُو[s[اْ] مِنَ [h:1173[ٱ]لْحَقِّ‌ۖ يَقُولُونَ رَبَّن[o[َآ] ءَامَ[g[نّ]َا فَ[h:1957[ٱ]كْتُ[q:1957[بْ]نَا مَعَ [h:1958[ٱ][l[ل]شَّ[n[ـٰ]هِد[p[ِي]نَ","Уларни Пайғамбарга нозил қилинган нарсани тинглаганларида, ҳақни билганликларидан, кўзлари ёш тўкканини кўрасан. Улар: «Эй Роббимиз, биз иймон келтирдик, бас, бизни шоҳидлар қаторига ёзгин.",122,7],["وَمَا لَنَا لَا نُؤْمِنُ بِ[h:32[ٱ]للَّهِ وَمَا ج[o[َا]ٓءَنَا مِنَ [h:1173[ٱ]لْحَقِّ وَنَ[q:3743[طْ]مَعُ أ[a:3744[َن ي]ُ[q:3745[دْ]خِلَنَا رَبُّنَا مَعَ [h:3746[ٱ]لْقَوْمِ [h:3747[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Нима учун Аллоҳга ва бизга келган ҳаққа иймон келтирмас эканмиз ва Роббимиз бизни ҳам солиҳ қавмлар қаторига киритишини тамаъ қилмас эканмиз?!» дерлар.",122,7],["فَأَثَ[n[ـٰ]بَهُمُ [h:3748[ٱ]للَّهُ بِمَا قَالُو[s[اْ] جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۚ وَذ[n[َٲ]لِكَ جَز[o[َا]ٓءُ [h:3749[ٱ]لْمُحْسِن[p[ِي]نَ","Айтганларига яраша Аллоҳ уларга остидан анҳорлар оқиб турган жаннатларда боқий қолишни мукофот қилиб берди. Яхшилик қилувчиларнинг мукофоти шулдир.",122,7],["وَ[h:9999[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَكَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِن[o[َآ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:3415[ٱ]لْجَح[p[ِي]مِ","Куфр келтирганлар ва оятларимизни ёлғонга чиқарганлар–ана ўшалар жаҳаннам эгаларидир.",122,7],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تُحَرِّمُو[s[اْ] طَيِّبَ[n[ـٰ]تِ م[o[َآ] أَحَلَّ [h:3750[ٱ]للَّهُ لَكُمْ وَلَا تَعْتَد[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُحِبُّ [h:1021[ٱ]لْمُعْتَد[p[ِي]نَ","Эй иймон келтирганлар! Аллоҳ сизга ҳалол қилган пок нарсаларни ҳаром қилмангиз. Ҳаддингиздан ошманг. Албатта, Аллоҳ ҳаддидан ошувчиларни севмас.",122,7],["وَكُلُو[s[اْ] مِ[g[مّ]َا رَزَقَكُمُ [h:3751[ٱ]للَّهُ حَلَ[n[ـٰ]ل[f:870[اً ط]َيِّ[a:3752[بًا‌ۚ و]َ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ [h:2537[ٱ]لَّذ[o[ِىٓ] أَ[f:428[نت][c:3753[ُم ب]ِه[n[ِۦ] مُؤْمِن[p[ُو]نَ","Ва Аллоҳ сизгаризқ қилиб берган ҳалол-пок нарсалардан енглар. Ўзингиз ишонган Аллоҳга тақво қилинг.",122,7],["لَا يُؤَاخِذُكُمُ [h:1261[ٱ]للَّهُ بِ[h:1262[ٱ][l[ل]لَّغْوِ ف[o[ِىٓ] أَيْمَ[n[ـٰ]نِكُمْ وَلَ[n[ـٰ]ك[a:1263[ِن ي]ُؤَاخِذُك[c:1264[ُم ب]ِمَا عَقَّ[d:3754[د]تُّمُ [h:3755[ٱ]لْأَيْمَ[n[ـٰ]نَ‌ۖ فَكَفَّ[n[ـٰ]رَتُهُ[o[ۥٓ] إِ[q:3756[طْ]عَامُ عَشَرَةِ مَسَ[n[ـٰ]كِينَ مِنْ أَوْسَطِ مَا تُ[q:3757[طْ]عِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَ[f:3758[ةٍ‌ۖ ف]َم[u:1066[َن ل]َّمْ يَجِ[q:1067[دْ] فَصِيَامُ ثَلَ[n[ـٰ]ثَةِ أَيَّا[f:3759[مٍ‌ۚ ذ][n[َٲ]لِكَ كَفَّ[n[ـٰ]رَةُ أَيْمَ[n[ـٰ]نِكُمْ إِذَا حَلَفْتُمْ‌ۚ وَ[h:3760[ٱ]حْفَظ[o[ُوٓ][s[اْ] أَيْمَ[n[ـٰ]نَكُمْ‌ۚ كَذ[n[َٲ]لِكَ يُبَيِّنُ [h:1002[ٱ]للَّهُ لَكُمْ ءَايَ[n[ـٰ]تِه[n[ِۦ] لَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Аллоҳ сизларни бехуда қасамларингиз учун тутмас. Лекин қасд ила туккан қасамларингиз учун тутар. Бас, унинг каффорати ўз аҳлингизни ўртача таомлантириш миқдорида ўнта мискинга таом ёки кийим бериш ёхуд бир қул озод қилишдир. Ким топа олмаса, бас, уч кун рўза тутсин. Ана ўша, агар қасам ичган бўлсангиз, қасамингизнинг каффоратидир. Қасамларингизни муҳофаза қилинг. Аллоҳ сизга шундай қилиб Ўз оятларини баён этади. Шоядки шукр қилсангиз.",122,7],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[g[نّ]َمَا [h:3761[ٱ]لْخَمْرُ وَ[h:3762[ٱ]لْمَيْسِرُ وَ[h:3763[ٱ]لْأَ[f:3763[نص]َابُ وَ[h:3764[ٱ]لْأَزْلَ[n[ـٰ]مُ رِ[q:3765[جْ][a:3766[سٌ م]ِّنْ عَمَلِ [h:3767[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ فَ[h:3768[ٱ][q:3768[جْ]تَنِبُوهُ لَعَلَّكُمْ تُفْلِح[p[ُو]نَ","Эй иймон келтирганлар! Албатта, хамр, қимор, бутлар ва чўплар ифлосдир. Шайтоннинг ишидир. Бас, ундан четда бўлинг. Шоядки, нажот топсангиз.",123,7],["إِ[g[نّ]َمَا يُرِيدُ [h:3769[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ أ[a:3770[َن ي]ُوقِعَ بَيْنَكُمُ [h:3771[ٱ]لْعَد[n[َٲ]وَةَ وَ[h:3435[ٱ]لْبَغْض[o[َا]ٓءَ فِى [h:3772[ٱ]لْخَمْرِ وَ[h:1216[ٱ]لْمَيْسِرِ وَيَصُدَّكُمْ عَ[f:3773[ن ذ]ِكْرِ [h:3774[ٱ]للَّهِ وَعَنِ [h:3775[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ‌ۖ فَهَلْ أَ[f:428[نت][w:3776[ُم م]ُّ[f:3777[نت]َه[p[ُو]نَ","Албатта, шайтон хамр ва қимор туфайли ораларингизга адоват ва ёмон кўришликни солишни ҳамда сизларни Аллоҳнинг зикридан ва намоздан тўсишни хоҳлайди. Энди тўхтарсизлар?!",123,7],["وَأَطِيعُو[s[اْ] [h:2238[ٱ]للَّهَ وَأَطِيعُو[s[اْ] [h:2865[ٱ][l[ل]رَّسُولَ وَ[h:3778[ٱ]حْذَرُو[s[اْ‌ۚ] فَإِ[f:3779[ن ت]َوَلَّيْتُمْ فَ[h:1140[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َمَا عَلَىٰ رَسُولِنَا [h:3780[ٱ]لْبَلَ[n[ـٰ]غُ [h:3781[ٱ]لْمُب[p[ِي]نُ","Аллоҳга ва Унинг Пайғамбарига итоат қилинг ва ҳазир бўлинг! Агар юз ўгирадиган бўлсангиз, билингки, Пайғамбаримиз вазифаси аниқ етказиш, холос.",123,7],["لَيْسَ عَلَى [h:289[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ جُنَا[f:3782[حٌ ف]ِيمَا طَعِم[o[ُوٓ][s[اْ] إِذَا مَا [h:3783[ٱ]تَّقَو[s[اْ] وَّءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ ثُ[g[مّ]َ [h:3784[ٱ]تَّقَو[s[اْ] وَّءَامَنُو[s[اْ] ثُ[g[مّ]َ [h:3784[ٱ]تَّقَو[s[اْ] وَّأَحْسَنُو[s[اْ‌ۗ] وَ[h:72[ٱ]للَّهُ يُحِبُّ [h:1047[ٱ]لْمُحْسِن[p[ِي]نَ","Иймон келтирганлар учун, агар тақво қилиб, иймон келтириб, яхши амалларни қилган бўлсалар, сўнгра тақво қилиб, иймон келтирсалар, кейин тақво қилиб эҳсон қилсалар, еб-ичганларида гуноҳ йўқдир. Зотан, Аллоҳ эҳсон қилувчиларни севадир.",123,7],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَيَ[q:3785[بْ]لُوَ[g[نّ]َكُمُ [h:3786[ٱ]للَّهُ بِش[a:793[َىْءٍ م]ِّنَ [h:3787[ٱ][l[ل]صَّيْدِ تَنَالُهُ[o[ۥٓ] أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ [h:3788[ٱ]للَّهُ م[a:3789[َن ي]َخَافُهُ[n[ۥ] بِ[h:13[ٱ]لْغَيْبِ‌ۚ فَمَنِ [h:938[ٱ]عْتَدَىٰ بَعْدَ ذ[n[َٲ]لِكَ فَلَهُ[n[ۥ] عَذَابٌ أَل[p[ِي]مٌ","Эй иймон келтирганлар! Аллоҳ ундан ким ғойибона қўрқишини билиш учун сизларни қўлларингиз ва найзаларингиз етадиган овларда бир оз синаб кўради. Бундан кейин ким тажовуз қилса, унга аламли азоб бор.",123,7],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَ[q:2734[قْ]تُلُو[s[اْ] [h:3790[ٱ][l[ل]صَّيْدَ وَأَ[f:98[نت]ُمْ حُرُ[a:3791[مٌ‌ۚ و]َمَ[f:3792[ن ق]َتَلَهُ[n[ۥ] مِ[f:344[نك][w:3793[ُم م]ُّتَعَ[g[مّ]ِ[f:3794[دًا ف]َجَز[o[َا]ٓ[a:3795[ءٌ م]ِّثْلُ مَا قَتَلَ مِنَ [h:3796[ٱ][l[ل][g[نّ]َعَمِ يَحْكُمُ بِه[n[ِۦ] ذَوَا عَ[q:3797[دْ][a:3798[لٍ م]ِّ[f:344[نك]ُمْ هَ[q:3799[دْ]ي[i:3800[َۢا ب]َ[n[ـٰ]لِغَ [h:3801[ٱ]لْكَعْبَةِ أَوْ كَفَّ[n[ـٰ]رَ[f:3802[ةٌ ط]َعَامُ مَسَ[n[ـٰ]كِينَ أَوْ عَ[q:3803[دْ]لُ ذ[n[َٲ]لِكَ صِيَا[u:3804[مًا ل]ِّيَذُوقَ وَبَالَ أَمْرِه[n[ِۦ]‌ۗ عَفَا [h:2357[ٱ]للَّهُ عَ[g[مّ]َا سَلَفَ‌ۚ وَمَنْ عَادَ فَيَ[f:3805[نت]َقِمُ [h:3806[ٱ]للَّهُ مِنْهُ‌ۗ وَ[h:72[ٱ]للَّهُ عَزِي[f:1729[زٌ ذ]ُو [h:1730[ٱ][f:1731[نت]ِق[p[َا]مٍ","Эй иймон келтирганлар! Эҳромдалик ҳолингизда овни ўлдирманг. Сиздан ким уни қасддан ўлдирса, жазоси сиздан икки одил киши ҳукмига мувофиқ чорва ҳайвонларидан уга тенг келадиганини ҳадий қилиб Каъбага етказишдир. Ёхуд унинг каффорати мискинларга таом бериш ёки шу баробарида, ўз қилмишининг ёмон оқибатини татиб кўрсин учун, рўза тутишдир. Ўтганларини Аллоҳ авф қилди. Ким қайтарса, Аллоҳ ундан интиқом оладир. Зотан, Аллоҳ азиз, интиқом эгасидир.",123,7],["أُحِلَّ لَكُمْ صَيْدُ [h:3807[ٱ]لْبَحْرِ وَطَعَامُهُ[n[ۥ] مَتَ[n[ـٰ][u:3808[عًا ل]َّكُمْ وَلِلسَّيَّارَةِ‌ۖ وَحُرِّمَ عَلَيْكُمْ صَيْدُ [h:3809[ٱ]لْبَرِّ مَا دُمْتُمْ حُرُ[a:3810[مًا‌ۗ و]َ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ [h:2537[ٱ]لَّذ[o[ِىٓ] إِلَيْهِ تُحْشَر[p[ُو]نَ","Денгиз ови ва унинг таоми сизга ва сайр қилувчиларга ҳалол қилинди. Модомики эҳромда экансиз, сизга қуруқлик ови ҳаром қилинди. Ҳузурида тўпланадиганингиз Аллоҳга тақво қилинг.",124,7],["۞ جَعَلَ [h:2556[ٱ]للَّهُ [h:3811[ٱ]لْكَعْبَةَ [h:3812[ٱ]لْبَيْتَ [h:3356[ٱ]لْحَرَامَ قِيَ[n[ـٰ][u:3813[مًا ل]ِّل[g[نّ]َاسِ وَ[h:3814[ٱ][l[ل]شَّهْرَ [h:3815[ٱ]لْحَرَامَ وَ[h:3816[ٱ]لْهَ[q:3816[دْ]ىَ وَ[h:3817[ٱ]لْقَلَ[o[ـٰٓ]ئِدَ‌ۚ ذ[n[َٲ]لِكَ لِتَعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَعْلَمُ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","Аллоҳ Каъбани–Байтул Ҳаромни, ҳаром ойни, ҳадийни ва осиладиган белгиларни одамлар учун асос қилиб қўйди. Бу эса, Аллоҳ албатта осмонлару ердаги нарсаларни билишини ва албатта Аллоҳ ҳар бир нарсани билувчи зот эканини билишингиз учундир.",124,7],["ٱعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ شَدِيدُ [h:1075[ٱ]لْعِقَابِ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Билингки, албатта, Аллоҳнинг иқоби шиддатлидир ва, албатта, Аллоҳ мағфиратли ва раҳмли зотдир.",124,7],["مَّا عَلَى [h:3818[ٱ][l[ل]رَّسُولِ إِلَّا [h:3819[ٱ]لْبَلَ[n[ـٰ]غُ‌ۗ وَ[h:72[ٱ]للَّهُ يَعْلَمُ مَا تُ[q:178[بْ]دُونَ وَمَا تَكْتُم[p[ُو]نَ","Пайғамбар зиммасида фақат етказиш бор, холос. Аллоҳ ошкор қилганингизни ҳам, яширганингизни ҳам биладир.",124,7],["قُل لَّا يَسْتَوِى [h:3820[ٱ]لْخَبِيثُ وَ[h:3821[ٱ][l[ل]طَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ [h:3822[ٱ]لْخَبِيثِ‌ۚ فَ[h:112[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ يَ[o[ـٰٓ]أُ[s[وْ]لِى [h:941[ٱ]لْأَلْبَ[n[ـٰ]بِ لَعَلَّكُمْ تُفْلِح[p[ُو]نَ","Сен: «Агар нопокнинг кўплиги сени ажаблантирса ҳам, пок билан нопок тенг бўла олмас, эй ақл эгалари, Аллоҳга тақво қилинг, шоядки нажот топсангиз», деб айт.",124,7],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَسْــَٔلُو[s[اْ] عَنْ أَشْي[o[َا]ٓءَ إِ[f:3823[ن ت]ُ[q:3824[بْ]دَ لَكُمْ تَسُؤْكُمْ وَإِ[f:3825[ن ت]َسْــَٔلُو[s[اْ] عَنْهَا حِينَ يُنَزَّلُ [h:3826[ٱ]لْقُرْءَانُ تُ[q:3824[بْ]دَ لَكُمْ عَفَا [h:2357[ٱ]للَّهُ عَنْهَا‌ۗ وَ[h:72[ٱ]للَّهُ غَفُورٌ حَل[p[ِي]مٌ","Эй иймон келтирганлар! Ҳар хил нарсаларни сўрайверманглар. Агар зоҳир бўлса, сизга ёмон бўлади. Агар Қуръон нозил қилиниб турган чоғда сўрасангиз, сизга зоҳир бўлади. Ҳолбуки, Аллоҳ уларни авф қилган эди. Аллоҳ мағфиратли ва ҳалим зотдир.",124,7],["قَ[q:298[دْ] سَأَلَهَا قَوْ[a:3827[مٌ م]ِّ[f:85[ن ق]َ[q:86[بْ]لِكُمْ ثُ[g[مّ]َ أَصْبَحُو[s[اْ] بِهَا كَ[n[ـٰ]فِر[p[ِي]نَ","Сиздан олдин ҳар бир қавм уларни сўраган, сўнгра эса, уларга кофир бўлган эди.",124,7],["مَا جَعَلَ [h:2556[ٱ]للَّهُ م[i:3828[ِنۢ ب]َحِيرَ[a:3829[ةٍ و]َلَا س[o[َا]ٓئِبَ[a:3830[ةٍ و]َلَا وَصِيلَ[a:3831[ةٍ و]َلَا حَا[a:3832[مٍ‌ۙ و]َلَ[n[ـٰ]كِ[g[نّ]َ [h:3833[ٱ]لَّذِينَ كَفَرُو[s[اْ] يَفْتَرُونَ عَلَى [h:412[ٱ]للَّهِ [h:2035[ٱ]لْكَذِبَ‌ۖ وَأَكْثَرُهُمْ لَا يَعْقِل[p[ُو]نَ","Аллоҳ баҳийра, соиба, васийла ва ҳоммларни қилгани йўқ. Лекин куфр келтирганлар Аллоҳга нисбатан ёлғон тўқирлар. Уларнинг кўплари ақлсиздирлар.",124,7],["وَإِذَا قِيلَ لَهُمْ تَعَالَوْ[s[اْ] إِلَىٰ م[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ وَإِلَى [h:2875[ٱ][l[ل]رَّسُولِ قَالُو[s[اْ] حَسْبُنَا مَا وَجَ[q:3834[دْ]نَا عَلَيْهِ ءَاب[o[َا]ٓءَن[o[َآ‌ۚ] أَوَلَوْ كَانَ ءَاب[o[َا]ٓؤُهُمْ لَا يَعْلَمُونَ شَيْـ[a:232[ـًٔا و]َلَا يَهْتَد[p[ُو]نَ","Уларга: «Аллоҳ нозил қилган нарсага, Пайғамбарга келинглар», дейилса, «Бизга ота-боболаримизни нимани устида топган бўлсак, ўша етарли», дерлар. Агар ота-боболари ҳеч нарсага ақли етмайдиган ва ҳидоятга эришмаган бўлсалар ҳам-а?!",125,7],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] عَلَيْكُمْ أَ[f:221[نف]ُسَكُمْ‌ۖ لَا يَضُرُّك[w:3835[ُم م]َّ[f:3836[ن ض]َلَّ إِذَا [h:3837[ٱ]هْتَدَيْتُمْ‌ۚ إِلَى [h:1637[ٱ]للَّهِ مَرْجِعُكُمْ جَمِي[f:3604[عًا ف]َيُنَبِّئُك[c:3605[ُم ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Эй иймон келтирганлар! Ўзингизни билинг. Агар ҳидоятда бўлсангиз, уларнинг адашганлари сизга зарар қилмас. Ҳаммангизнинг қайтиб борадиган жойингиз Аллоҳнинг ҳузурида. Ўшанда сизга қилиб юрган ишларингизнинг хабарини берадир.",125,7],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] شَهَ[n[ـٰ]دَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ [h:942[ٱ]لْمَوْتُ حِينَ [h:3838[ٱ]لْوَصِيَّةِ [h:3839[ٱ]ثْنَانِ ذَوَا عَ[q:3797[دْ][a:3798[لٍ م]ِّ[f:344[نك]ُمْ أَوْ ءَاخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَ[f:428[نت]ُمْ ضَرَ[q:3037[بْ]تُمْ فِى [h:44[ٱ]لْأَرْضِ فَأَصَ[n[ـٰ]بَتْك[w:3840[ُم م]ُّصِيبَةُ [h:3841[ٱ]لْمَوْتِ‌ۚ تَحْبِسُونَهُمَا م[i:146[ِنۢ ب]َعْدِ [h:3842[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ فَيُ[q:3843[قْ]سِمَانِ بِ[h:32[ٱ]للَّهِ إِنِ [h:3844[ٱ]رْتَ[q:3845[بْ]تُمْ لَا نَشْتَرِى بِه[n[ِۦ] ثَمَ[a:3846[نًا و]َلَوْ كَانَ ذَا قُرْبَىٰ‌ۙ وَلَا نَكْتُمُ شَهَ[n[ـٰ]دَةَ [h:3847[ٱ]للَّهِ إِ[g[نّ][o[َآ] إِ[u:765[ذًا ل]َّمِنَ [h:3848[ٱ]لْأَثِم[p[ِي]نَ","Эй иймон келтирганлар! Бирортангизга ўлим келганда–васият қилар чоғида ўзингиздан бўлган икки адолатли киши, агар ер юзида сафардалик чоғингизда ўлим мусибати етса, ўзгалардан икки киши ўртангизда гувоҳ бўлсин. Агар шубҳа қилсангиз, гувоҳларни намоздан кейин тутасиз ва улар: «Гарчи қариндошимиз учун бўлса ҳам, қасамни озгина қийматга сотмаймиз ва Аллоҳ учун гувоҳлигимизни яширмаймиз. Зотан, у ҳолда, албатта, гуноҳкорлардан бўлиб қоламиз», деб Аллоҳ номи ила қасам ичадилар.",125,7],["فَإِنْ عُثِرَ عَلَ[o[ىٰٓ] أَ[g[نّ]َهُمَا [h:3849[ٱ]سْتَحَقّ[o[َآ] إِثْ[f:3850[مًا ف]َـَٔـاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ [h:523[ٱ]لَّذِينَ [h:3851[ٱ]سْتَحَقَّ عَلَيْهِمُ [h:3852[ٱ]لْأَوْلَيَ[n[ـٰ]نِ فَيُ[q:3843[قْ]سِمَانِ بِ[h:32[ٱ]للَّهِ لَشَهَ[n[ـٰ]دَتُن[o[َآ] أَحَقُّ مِ[f:3853[ن ش]َهَ[n[ـٰ]دَتِهِمَا وَمَا [h:3854[ٱ]عْتَدَيْن[o[َآ] إِ[g[نّ][o[َآ] إِ[u:765[ذًا ل]َّمِنَ [h:766[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Агар икковларининг гуноҳлари билиниб қолса, ўринларига устиларига ноҳақлик тушган яқинлардан иккиталари ўтадилар ва Аллоҳ ила қасам ичиб: «Бизнинг гувоҳлигимиз уларнинг гувоҳликларидан тўғрироқ ва биз тажовуз қилмадик. Агар қилган бўлсак, албатта, золимлардан бўламиз», дерлар.",125,7],["ذ[n[َٲ]لِكَ أَ[q:314[دْ]نَ[o[ىٰٓ] أ[a:3855[َن ي]َأْتُو[s[اْ] بِ[h:3856[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ عَلَىٰ وَ[q:3857[جْ]هِه[o[َآ] أَوْ يَخَاف[o[ُوٓ][s[اْ] أَ[f:3858[ن ت]ُرَدَّ أَيْمَ[n[ـٰ][i:3859[نُۢ ب]َعْدَ أَيْمَ[n[ـٰ]نِهِمْ‌ۗ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ وَ[h:486[ٱ]سْمَعُو[s[اْ‌ۗ] وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:3860[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","Ана шундай қилмоқлик, гувоҳликни ҳаққоний адо этишларига ёки қасамларидан сўнг раддия қасам бўлишидан қўрқишларига яқинроқдир. Аллоҳга тақво қилинглар ва қулоқ осинглар. Аллоҳ фосиқ қавмларни ҳидоят қилмас.",125,7],["۞ يَوْمَ يَ[q:3861[جْ]مَعُ [h:3862[ٱ]للَّهُ [h:3863[ٱ][l[ل]رُّسُلَ فَيَقُولُ مَاذ[o[َآ] أُجِ[q:3864[بْ]تُمْ‌ۖ قَالُو[s[اْ] لَا عِلْمَ لَن[o[َآ‌ۖ] إِ[g[نّ]َكَ أَ[f:169[نت]َ عَلَّ[n[ـٰ]مُ [h:3865[ٱ]لْغُي[p[ُو][q[ب]ِ","Аллоҳ Пайғамбарларни жамлаган кунда: «Сизга қандай жавоб қилинди?» деб сўрайдир. Улар: «Биз билмайсмиз, албатта, Сенинг Ўзинггина ғайбларни яхши билгувчисан», дерлар.",126,7],["إِذْ قَالَ [h:1961[ٱ]للَّهُ يَ[n[ـٰ]عِيسَى [h:3866[ٱ][q:451[بْ]نَ مَرْيَمَ [h:3867[ٱ]ذْكُرْ نِعْمَتِى عَلَيْكَ وَعَلَىٰ و[n[َٲ]لِدَتِكَ إِذْ أَيَّ[d:3868[د]تُّكَ بِرُوحِ [h:454[ٱ]لْقُدُسِ تُكَلِّمُ [h:3869[ٱ][l[ل][g[نّ]َاسَ فِى [h:1921[ٱ]لْمَهْدِ وَكَهْل[a:3870[اً‌ۖ و]َإِذْ عَلَّمْتُكَ [h:3871[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:679[ٱ]لْحِكْمَةَ وَ[h:1928[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةَ وَ[h:1725[ٱ]لْإِ[f:1725[نج]ِيلَ‌ۖ وَإِذْ تَخْلُقُ مِنَ [h:1931[ٱ][l[ل]طِّينِ كَهَيْــَٔةِ [h:1932[ٱ][l[ل]طَّيْرِ بِإِذْنِى فَتَ[f:3872[نف]ُخُ فِيهَا فَتَكُونُ طَيْر[i:3873[َۢا ب]ِإِذْنِى‌ۖ وَتُ[q:3874[بْ]رِئُ [h:3875[ٱ]لْأَكْمَهَ وَ[h:1937[ٱ]لْأَ[q:1937[بْ]رَصَ بِإِذْنِى‌ۖ وَإِذْ تُخْرِجُ [h:3876[ٱ]لْمَوْتَىٰ بِإِذْنِى‌ۖ وَإِذْ كَفَفْتُ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ عَ[f:626[نك]َ إِذْ جِئْتَه[c:3877[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ فَقَالَ [h:3878[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِنْهُمْ إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا سِحْ[a:3879[رٌ م]ُّب[p[ِي]نٌ","Аллоҳ: «Эй Ийсо ибн Марям, сенга ва волидангга берган неъматимни эсла. Сени муқаддас руҳ билан қўллаганимни, одамларга бешикда ҳам, катталигингда ҳам гапирганингни эсла. Сенга китобни, ҳикматни, Тавротни ва Инжилни ўргатганимни эсла. Менинг изним ила лойдан қуш шаклини ясаганингда ва унга пуфлаганингда, Менинг изним ила қуш бўлганини, Менинг изним ила туғма кўрни ва песни тузатганингни эсла. Менинг изним ила ўликларни чиқарганингни эсла. Бани Исроилга аниқ мўъжизалар келтирганингда, улардан куфр келтирганлари: «Бу очиқ сеҳрдан ўзга ҳеч нарса эмас», деганида, сени улардан қутқарганимини эсла», деганини ёд эт!",126,7],["وَإِذْ أَوْحَيْتُ إِلَى [h:3880[ٱ]لْحَوَارِيِّـ[n[ـۧ]نَ أَنْ ءَامِنُو[s[اْ] بِى وَبِرَسُولِى قَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا وَ[h:1953[ٱ]شْهَ[q:1953[دْ] بِأَ[g[نّ]َنَا مُسْلِم[p[ُو]نَ","Ҳаворийларга: «Менга ва Менинг Пайғамбаримга иймон келтиринг», деб ваҳий юборганимда, улар: «Иймон келтирдик ва шоҳид бўл, биз албатта, мусулмонлармиз» деганини эсла!",126,7],["إِذْ قَالَ [h:1950[ٱ]لْحَوَارِيُّونَ يَ[n[ـٰ]عِيسَى [h:3866[ٱ][q:451[بْ]نَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أ[a:473[َن ي]ُنَزِّلَ عَلَيْنَا م[o[َا]ٓئِدَ[a:3881[ةً م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ‌ۖ قَالَ [h:3882[ٱ]تَّقُو[s[اْ] [h:1644[ٱ]للَّهَ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Ҳаворийлар: «Эй Ийсо ибн Марям, сенинг Роббинг бизга осмондан тузатилган дастурхон тушира оладими?» деганларида, у: «Агар мўмин бўлсаларингиз, Аллоҳга тақво қилинглар», деганини эсла.",126,7],["قَالُو[s[اْ] نُرِيدُ أ[a:3883[َن ن]َّأْكُلَ مِنْهَا وَتَ[q:3884[طْ]مَئِ[g[نّ]َ قُلُوبُنَا وَنَعْلَمَ أَ[f:3885[ن ق]َ[q:298[دْ] صَدَ[q:3886[قْ]تَنَا وَنَكُونَ عَلَيْهَا مِنَ [h:2069[ٱ][l[ل]شَّ[n[ـٰ]هِد[p[ِي]نَ","Улар: «Ундан емоқни, қалбларимиз таскин топмоғини, бизга рост гапирганингни билмоқни ва бунга гувоҳ бўлмоқни истаймиз», дедилар.",126,7],["قَالَ عِيسَى [h:1916[ٱ][q:1917[بْ]نُ مَرْيَمَ [h:3887[ٱ][l[ل]لَّهُ[g[مّ]َ رَبَّن[o[َآ] أَ[f:3888[نز]ِلْ عَلَيْنَا م[o[َا]ٓئِدَ[a:3881[ةً م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ تَكُونُ لَنَا عِي[u:3889[دًا ل]ِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَ[a:3890[ةً م]ِّ[f:3891[نك]َ‌ۖ وَ[h:3892[ٱ]رْزُ[q:3892[قْ]نَا وَأَ[f:3893[نت]َ خَيْرُ [h:3894[ٱ][l[ل]رّ[n[َٲ]زِق[p[ِي]نَ","Ийсо ибн Марям: «Эй бор Худоё! Роббимиз! Бизга осмондан ясатилган дастурхон туширгин, у аввалимизгаю охиримизга байрам бўлиб қолсин. Сендан мўъжиза бўлиб қолсин. Ва бизга ризқ бергин, зотан Ўзинг энг яхши ризқ бергувчисан», деди.",127,7],["قَالَ [h:1961[ٱ]للَّهُ إِ[g[نّ]ِى مُنَزِّلُهَا عَلَيْكُمْ‌ۖ فَم[a:1481[َن ي]َكْفُرْ بَعْدُ مِ[f:344[نك]ُمْ فَإِ[g[نّ][o[ِىٓ] أُعَذِّبُهُ[n[ۥ] عَذَا[u:3895[بًا ل]ّ[o[َآ] أُعَذِّبُهُ[o[ۥٓ] أَحَ[a:3474[دًا م]ِّنَ [h:3475[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Аллоҳ: «Мен, албатта, уни сизларга туширгувчиман. Бас, бундан кейин сизлардан ким куфр келтирса, уни оламларда ҳеч кимни азобламаган азоб ила азоблагайман», деди.",127,7],["وَإِذْ قَالَ [h:1961[ٱ]للَّهُ يَ[n[ـٰ]عِيسَى [h:3866[ٱ][q:451[بْ]نَ مَرْيَمَ ءَأَ[f:3896[نت]َ قُلْتَ لِل[g[نّ]َاسِ [h:3897[ٱ]تَّخِذُونِى وَأُ[g[مّ]ِىَ إِلَ[n[ـٰ]هَيْنِ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ‌ۖ قَالَ سُ[q:168[بْ]حَ[n[ـٰ]نَكَ مَا يَكُونُ ل[o[ِىٓ] أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ‌ۚ إِ[f:3898[ن ك]ُ[f:2917[نت]ُ قُلْتُهُ[n[ۥ] فَقَ[q:563[دْ] عَلِمْتَهُ[n[ۥ]‌ۚ تَعْلَمُ مَا فِى نَفْسِى وَل[o[َآ] أَعْلَمُ مَا فِى نَفْسِكَ‌ۚ إِ[g[نّ]َكَ أَ[f:169[نت]َ عَلَّ[n[ـٰ]مُ [h:3865[ٱ]لْغُي[p[ُو][q[ب]ِ","Аллоҳ: «Эй Ийсо ибн Марям, сен одамларга, Аллоҳни қўйиб, мени ва онамни илоҳ қилиб олинглар, дедингми?» деганини, у эса: «Эй пок Зот, ҳаққим йўқ нарсани мен айта олмайман-ку. Агар айтган бўлганимда, батаҳқиқ, Сен уни билар эдинг. Сен менинг дилимдагини биласан, мен Сендаги ҳеч нарсани билмайман. Албатта, Сен Ўзинг ғайбларни энг яхши билгувчи зотсан.",127,7],["مَا قُلْتُ لَهُمْ إِلَّا م[o[َآ] أَمَرْتَنِى بِه[o[ِۦٓ] أَنِ [h:3899[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ رَبِّى وَرَبَّكُمْ‌ۚ وَكُ[f:3900[نت]ُ عَلَيْهِمْ شَهِي[a:3901[دًا م]َّا دُمْتُ فِيهِمْ‌ۖ فَلَ[g[مّ]َا تَوَفَّيْتَنِى كُ[f:735[نت]َ أَ[f:169[نت]َ [h:3902[ٱ][l[ل]رَّقِيبَ عَلَيْهِمْ‌ۚ وَأَ[f:3893[نت]َ عَلَىٰ كُلِّ ش[f:3903[َىْءٍ ش]َه[p[ِي][q[د]ٌ","Мен уларга Ўзинг менга амр қилган нарса; Аллоҳга менинг Роббим ва сизнинг Роббингизга ибодат қилингдан, бошқани айтганим йўқ. Ва модомики ораларида эканман, уларга гувоҳ бўлдим. Мени Ўзингга олганингдан сўнг, Сенинг Ўзинг уларга кузатувчи бўлдинг. Зотан, сен ҳар бир нарсага гувоҳсан.",127,7],["إِ[f:3904[ن ت]ُعَذِّ[q:3905[بْ]هُمْ فَإِ[g[نّ]َهُمْ عِبَادُكَ‌ۖ وَإِ[f:3906[ن ت]َغْفِرْ لَهُمْ فَإِ[g[نّ]َكَ أَ[f:169[نت]َ [h:680[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Агар уларни азоблайдиган бўлсанг, бас, албатта, улар Сенинг бандаларинг. Агар уларни мағфират қиладиган бўлсанг, бас, албатта, Сенинг Ўзинг азиз-ғолиб ва ҳикматли зотсан», деганини эсла.",127,7],["قَالَ [h:1961[ٱ]للَّهُ هَ[n[ـٰ]ذَا يَوْمُ يَ[f:838[نف]َعُ [h:3907[ٱ][l[ل]صَّ[n[ـٰ]دِقِينَ صِ[q:3908[دْ]قُهُمْ‌ۚ لَهُمْ جَ[g[نّ]َ[n[ـٰ][f:1786[تٌ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَ[u:3909[دًا‌ۚ ر]َّضِىَ [h:3910[ٱ]للَّهُ عَنْهُمْ وَرَضُو[s[اْ] عَنْهُ‌ۚ ذ[n[َٲ]لِكَ [h:3911[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Аллоҳ: «Бу кун ростгўйларга ростгўйликлари манфаат берадиган кун. Уларга остидан сувлар оқиб турган жаннатлар бор, унда абадий-боқий бўлурлар. Аллоҳ улардан рози бўлди. Улар Аллоҳдан рози бўлди. Бу эса улуғ ютуқдир» деди.",127,7],["لِلَّهِ مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا فِيهِ[g[نّ]َ‌ۚ وَهُوَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رُۢ","Осмонлару ер ва улардаги нарсалар Аллоҳнинг мулкидир. Ва У зот ҳар бир нарсага қодирдир.",127,7]]},{"n":6,"ar":"الأَنۡعَامِ","en":"Al-An'aam","uz":"Анъом","type":"Макка","ayahs":[["ٱلْحَمْدُ لِلَّهِ [h:3912[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَجَعَلَ [h:3914[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ وَ[h:3915[ٱ][l[ل][g[نّ]ُورَ‌ۖ ثُ[g[مّ]َ [h:3916[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِرَبِّهِمْ يَعْدِل[p[ُو]نَ","Осмонлару ерни яратган, зулматлару нурни таратган Аллоҳга ҳамд бўлсин. Сўнгра куфр келтирганлар ўз Роббиларига тенглаштирадилар.",128,7],["هُوَ [h:153[ٱ]لَّذِى خَلَقَك[w:2530[ُم م]ِّ[f:3917[ن ط]ِي[f:3918[نٍ ث]ُ[g[مّ]َ قَضَ[o[ىٰٓ] أَجَل[a:3919[اً‌ۖ و]َأَجَ[a:3920[لٌ م]ُّسَ[g[مّ]ًى عِ[f:719[ند]َهُ[n[ۥ]‌ۖ ثُ[g[مّ]َ أَ[f:428[نت]ُمْ تَمْتَر[p[ُو]نَ","У сизларни лойдан яратган, сўнгра ажални белгилаб қўйган зотдир. Белгиланган ажал эса Унинг ҳузуридадир. Шундан кейин ҳам сиз шак келтирасиз.",128,7],["وَهُوَ [h:3921[ٱ]للَّهُ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَفِى [h:3922[ٱ]لْأَرْضِ‌ۖ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِب[p[ُو]نَ","У осмонларда ҳам, ерда ҳам Аллоҳдир. Сирингизни ҳам, ошкорингизни ҳам биладир. Қилган касбу корингизни ҳам биладир.",128,7],["وَمَا تَأْتِيه[w:3923[ِم م]ِّنْ ءَايَ[a:3924[ةٍ م]ِّنْ ءَايَ[n[ـٰ]تِ رَبِّهِمْ إِلَّا كَانُو[s[اْ] عَنْهَا مُعْرِض[p[ِي]نَ","Мудом уларга ўз Роббилари оятларидан бир оят келса, ундан юз ўгирувчи бўлдилар.",128,7],["فَقَ[q:563[دْ] كَذَّبُو[s[اْ] بِ[h:370[ٱ]لْحَقِّ لَ[g[مّ]َا ج[o[َا]ٓءَهُمْ‌ۖ فَسَوْفَ يَأْتِيهِمْ أَ[i:3925[نۢب]َ[o[ـٰٓ]ؤُ[s[اْ] مَا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Уларга ҳақ келганда уни ҳам ёлғонга чиқардилар. Тезда уларга ўзлари истеҳзо қилган нарсанинг хабари келадир.",128,7],["أَلَمْ يَرَوْ[s[اْ] كَمْ أَهْلَكْنَا مِ[f:617[ن ق]َ[q:618[بْ]لِه[w:3926[ِم م]ِّ[f:3927[ن ق]َرْ[a:3928[نٍ م]َّكَّ[g[نّ]َ[n[ـٰ]هُمْ فِى [h:44[ٱ]لْأَرْضِ مَا لَمْ نُمَكّ[u:3929[ِن ل]َّكُمْ وَأَرْسَلْنَا [h:3930[ٱ][l[ل]سَّم[o[َا]ٓءَ عَلَيْه[w:3931[ِم م]ِّ[q:3932[دْ]رَا[a:3933[رًا و]َجَعَلْنَا [h:3934[ٱ]لْأَنْهَ[n[ـٰ]رَ تَ[q:120[جْ]رِى مِ[f:3935[ن ت]َحْتِهِمْ فَأَهْلَكْنَ[n[ـٰ]ه[c:3936[ُم ب]ِذُنُوبِهِمْ وَأَ[f:3937[نش]َأْنَا م[i:1453[ِنۢ ب]َعْدِهِمْ قَرْنًا ءَاخَر[p[ِي]نَ","Улардан олдин қанча асрларни ҳалок қилганимизни билмасларми? Ўшаларга ер юзида сизларга бермаган имконларни берган эдик. Осмондан устларига барака ёмғири юборган ва остларидан анҳорлар оқиб турадиган қилиб қўйган эдик. Бас, гуноҳлари туфайли уларни ҳалок қилдик ва ўринларига бошқа асрларни пайдо қилдик.",128,7],["وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَ[n[ـٰ][f:3938[بًا ف]ِى قِرْطَا[f:3939[سٍ ف]َلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ [h:3940[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا سِحْ[a:3879[رٌ م]ُّب[p[ِي]نٌ","Агар сенга қоғоз-китоб туширсак, уни қўллари билан ушлаб кўришса ҳам, куфр келтирганлар: «Бу аниқ сеҳрдан ўзга ҳеч нарса эмас», дерлар.",128,7],["وَقَالُو[s[اْ] لَوْل[o[َآ] أُ[f:17[نز]ِلَ عَلَيْهِ مَلَ[a:3941[كٌ‌ۖ و]َلَوْ أَ[f:515[نز]َلْنَا مَلَ[u:3942[كًا ل]َّقُضِىَ [h:3943[ٱ]لْأَمْرُ ثُ[g[مّ]َ لَا يُ[f:826[نظ]َر[p[ُو]نَ","Улар: «Агар унга фаришта туширилса эди», дедилар. Агар фаришта туширсак, иш битди ҳисоб. Сўнгра уларга қараб турилмас.",128,7],["وَلَوْ جَعَلْنَ[n[ـٰ]هُ مَلَ[u:3944[كًا ل]َّجَعَلْنَ[n[ـٰ]هُ رَجُل[a:3945[اً و]َلَلَبَسْنَا عَلَيْه[w:3946[ِم م]َّا يَلْبِس[p[ُو]نَ","Агар уни фаришта қилсак ҳам, эркак қилган бўлар эдик ва ўзлари мушкуллаштирган нарсани уларга яна ҳам мушкуллаштирар эдик.",129,7],["وَلَقَدِ [h:3947[ٱ]سْتُهْزِئَ بِرُسُ[a:3948[لٍ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ فَحَاقَ بِ[h:2413[ٱ]لَّذِينَ سَخِرُو[s[اْ] مِنْه[w:3670[ُم م]َّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Сендан олдинги Пайғамбарлар ҳам истеҳзо қилинганлар. Уларни масхара қилганларни қилган истеҳзолари ўз домига тортган.",129,7],["قُلْ سِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ ثُ[g[مّ]َ [h:3949[ٱ][f:3950[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:2258[ٱ]لْمُكَذِّب[p[ِي]نَ","Сен: «Ер юзида сайр қилингиз, сўнгра ёлғончи қилувчиларнинг оқибати қандай бўлганига назар солингиз», деб айт.",129,7],["قُل لِّم[a:3951[َن م]َّا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ قُل لِّلَّهِ‌ۚ كَتَبَ عَلَىٰ نَفْسِهِ [h:3952[ٱ][l[ل]رَّحْمَةَ‌ۚ لَيَ[q:2997[جْ]مَعَ[g[نّ]َكُمْ إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ لَا رَيْبَ فِيهِ‌ۚ [h:3953[ٱ]لَّذِينَ خَسِر[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ فَهُمْ لَا يُؤْمِن[p[ُو]نَ","Сен: «Осмонлар ва ердаги нарсалар кимники?» деб айт! «Аллоҳники», деб айт! У Ўзига Ўзи раҳматни ёзиб қўйган. Сизларни бўлишида шубҳа йўқ қиёмат куни албатта жамлайдир. Ўзига ўзи зиён келтирувчиларгина, ўшаларгина иймон келтирмаслар.",129,7],["۞ وَلَهُ[n[ۥ] مَا سَكَنَ فِى [h:1831[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ‌ۚ وَهُوَ [h:709[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Кечада ва кундузда сокин бўлганлар Уникидир. У эшитгувчи ва билгувчи зотдир.",129,7],["قُلْ أَغَيْرَ [h:3954[ٱ]للَّهِ أَتَّخِذُ وَلِي[f:3955[ًّا ف]َاطِرِ [h:3956[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَهُوَ يُ[q:3957[طْ]عِمُ وَلَا يُ[q:3958[طْ]عَمُ‌ۗ قُلْ إِ[g[نّ][o[ِىٓ] أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ‌ۖ وَلَا تَكُونَ[g[نّ]َ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Сен: «Аллоҳдан ўзгани валий-дўст қилиб оламанми? У осмонлару ерни яратгувчидир. У таом беради ва таомланмайди», деб айт. Сен: «Мен аввалги таслим бўлувчи бўлмоққа амр қилиндим ва менга ҳеч мушриклардан бўлмагин, деб айтилди», деб айт.",129,7],["قُلْ إِ[g[نّ][o[ِىٓ] أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظ[p[ِي]مٍ","Сен: «Албатта, мен агар Роббимга осий бўлсам, улуғ кун азобидан қўрқаман», деб айт.",129,7],["مّ[a:3959[َن ي]ُصْرَفْ عَنْهُ يَوْمَئِ[f:3960[ذٍ ف]َقَ[q:563[دْ] رَحِمَهُ[n[ۥ]‌ۚ وَذ[n[َٲ]لِكَ [h:2632[ٱ]لْفَوْزُ [h:3961[ٱ]لْمُب[p[ِي]نُ","Ким ўша куни ундан четланса, бас, батаҳқиқ, Аллоҳ унга раҳм қилибди. Ана ўша аниқ ютуқдир.",129,7],["وَإ[a:3962[ِن ي]َمْسَسْكَ [h:3963[ٱ]للَّهُ بِضُ[f:3964[رٍّ ف]َلَا كَاشِفَ لَهُ[o[ۥٓ] إِلَّا هُوَ‌ۖ وَإ[a:3962[ِن ي]َمْسَسْكَ بِخَيْ[f:3965[رٍ ف]َهُوَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Агар Аллоҳ сени зарарига оладиган бўлса, унинг ўзидан бошқа кушойиш берадиган йўқ. Агар у сени яхшиликка оладиган бўлса, бас, у ҳар бир нарсага қодирдир.",129,7],["وَهُوَ [h:3966[ٱ]لْقَاهِرُ فَوْقَ عِبَادِه[n[ِۦ]‌ۚ وَهُوَ [h:3967[ٱ]لْحَكِيمُ [h:3968[ٱ]لْخَب[p[ِي]رُ","У бандалари устидан ғолибдур. У ҳикмат эгаси ва ҳар бир нарсадан хабардордир.",129,7],["قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَ[n[ـٰ]دَ[f:3969[ةً‌ۖ ق]ُلِ [h:3166[ٱ]للَّهُ‌ۖ شَهِي[i:3970[دُۢ ب]َيْنِى وَبَيْنَكُمْ‌ۚ وَأُوحِىَ إِلَىَّ هَ[n[ـٰ]ذَا [h:3971[ٱ]لْقُرْءَانُ لِأُ[f:3972[نذ]ِرَك[c:3973[ُم ب]ِه[n[ِۦ] وَم[i:3974[َنۢ ب]َلَغَ‌ۚ أَئِ[g[نّ]َكُمْ لَتَشْهَدُونَ أَ[g[نّ]َ مَعَ [h:3975[ٱ]للَّهِ ءَالِهَةً أُخْرَىٰ‌ۚ قُل لّ[o[َآ] أَشْهَدُ‌ۚ قُلْ إِ[g[نّ]َمَا هُوَ إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[a:3976[دٌ و]َإِ[g[نّ]َنِى بَر[o[ِى]ٓ[a:3977[ءٌ م]ِّ[g[مّ]َا تُشْرِك[p[ُو]نَ","Сен: «Қайси нарса энг катта гувоҳликдир», деб айт. «Аллоҳ», деб айт. У мен билан сизларнинг ўртангизда гувоҳдир. Менга ушбу Қуръонни, унинг ила сизларни ва у етиб борганларни огоҳлантиришим учун ваҳий қилинди. Сизлар «Аллоҳ билан бирга, албатта, бошқа худолар бор», деб гувоҳлик берасизларми? «Мен гувоҳлик бермайман», деб айт. «Албатта, У битта илоҳдир ва мен сиз келтираётган ширкдан покдирман», деб айт.",130,7],["ٱلَّذِينَ ءَاتَيْنَ[n[ـٰ]هُمُ [h:635[ٱ]لْكِتَ[n[ـٰ]بَ يَعْرِفُونَهُ[n[ۥ] كَمَا يَعْرِفُونَ أَ[q:3978[بْ]ن[o[َا]ٓءَهُمُ‌ۘ [h:3979[ٱ]لَّذِينَ خَسِر[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ فَهُمْ لَا يُؤْمِن[p[ُو]نَ","Биз китоб берганлар уни ўз фарзандларини танигандек танирлар. Улар ўзларига зиён қилганлардир, ана ўшалар иймон келтирмаслар.",130,7],["وَمَنْ أَظْلَمُ مِ[g[مّ]َنِ [h:3980[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔـايَ[n[ـٰ]تِه[o[ِۦٓ‌ۗ] إِ[g[نّ]َهُ[n[ۥ] لَا يُفْلِحُ [h:3981[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Аллоҳга нисбатан ёлғон тўқиган ёки Унинг оятларини ёлғонга чиқарганлардан ҳам кўра золимроқ кимса борми? Албатта, золимлар нажот топмаслар.",130,7],["وَيَوْمَ نَحْشُرُهُمْ جَمِي[f:155[عًا ث]ُ[g[مّ]َ نَقُولُ لِلَّذِينَ أَشْرَك[o[ُوٓ][s[اْ] أَيْنَ شُرَك[o[َا]ٓؤُكُمُ [h:3982[ٱ]لَّذِينَ كُ[f:100[نت]ُمْ تَزْعُم[p[ُو]نَ","Ҳаммаларини жамлайдиган, сўнгра ширк келтирганларга: «Сиз худо деб гумон қилган шерикларингиз қани?» деб айтадиганимиз кунни эсла.",130,7],["ثُ[g[مّ]َ لَمْ تَكُ[f:3983[ن ف]ِتْنَتُهُمْ إِلّ[o[َآ] أَ[f:2304[ن ق]َالُو[s[اْ] وَ[h:3984[ٱ]للَّهِ رَبِّنَا مَا كُ[g[نّ]َا مُشْرِك[p[ِي]نَ","Сўнгра, Роббимиз Аллоҳга қасамки, мушрик бўлмаган эдик, дейишдан бошқа фитналари бўлмас.",130,7],["ٱ[f:2837[نظ]ُرْ كَيْفَ كَذَبُو[s[اْ] عَلَ[o[ىٰٓ] أَ[f:568[نف]ُسِهِمْ‌ۚ وَضَلَّ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَفْتَر[p[ُو]نَ","Назар сол! Улар ўзларини қандай алдарлар ва тўқиб юрган нарсалари улардан қандай йўқолди.",130,7],["وَمِنْه[w:1106[ُم م]ّ[a:3986[َن ي]َسْتَمِعُ إِلَيْكَ‌ۖ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِ[g[نّ]َةً أ[a:3987[َن ي]َفْقَهُوهُ وَف[o[ِىٓ] ءَاذَانِهِمْ وَ[q:3988[قْ][a:3989[رًا‌ۚ و]َإ[a:3990[ِن ي]َرَوْ[s[اْ] كُلَّ ءَايَ[u:3991[ةٍ ل]َّا يُؤْمِنُو[s[اْ] بِهَا‌ۚ حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءُوكَ يُجَ[n[ـٰ]دِلُونَكَ يَقُولُ [h:3992[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلّ[o[َآ] أَسَ[n[ـٰ]طِيرُ [h:3993[ٱ]لْأَوَّل[p[ِي]نَ","Улардан сенга қулоқ тутадиганлари ҳам бор. Биз уни фаҳмламасликлари учун қалбларига парда ва қулоқларига тўсиқ қилиб қўйдик. Барча оятларни кўрсалар ҳам, улар иймон келтирмаслар. Ҳатто олдингга сен билан тортишувга келганларида куфр келтирганлар: «Бу ўтганларнинг афсоналаридан бошқа нарса эмас», дерлар.",130,7],["وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْــَٔوْنَ عَنْهُ‌ۖ وَإ[a:3994[ِن ي]ُهْلِكُونَ إِلّ[o[َآ] أَ[f:38[نف]ُسَهُمْ وَمَا يَشْعُر[p[ُو]نَ","Ва улар ундан қайтарадилар ва ундан узоқлашадилар. Улар сезмаган ҳолларида ўзларини ҳалок қиладилар, холос.",130,7],["وَلَوْ تَرَ[o[ىٰٓ] إِذْ وُقِفُو[s[اْ] عَلَى [h:896[ٱ][l[ل][g[نّ]َارِ فَقَالُو[s[اْ] يَ[n[ـٰ]لَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔـايَ[n[ـٰ]تِ رَبِّنَا وَنَكُونَ مِنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Дўзах устида тўхтатилганларида: «Қани энди қайтарилсак эди, Роббимизнинг оятларини ёлғонга чиқармас эдик ва мўминлардан бўлар эдик», дейишларини кўрсанг эди.",130,7],["بَلْ بَدَا لَه[w:3531[ُم م]َّا كَانُو[s[اْ] يُخْفُونَ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ وَلَوْ رُدُّو[s[اْ] لَعَادُو[s[اْ] لِمَا نُهُو[s[اْ] عَنْهُ وَإِ[g[نّ]َهُمْ لَكَ[n[ـٰ]ذِب[p[ُو]نَ","Йўқ! Ундай эмас. Улар олдин махфий тутган нарса ўзларига ошкор бўлди, холос. Агар улар қайтарилсалар ҳам, ўзлари ман қилинган нарсага қайтарлар ва, албатта, улар ёлғончилардир.",131,7],["وَقَال[o[ُوٓ][s[اْ] إِنْ هِىَ إِلَّا حَيَاتُنَا [h:3995[ٱ][l[ل]دُّنْيَا وَمَا نَحْنُ بِمَ[q:3996[بْ]عُوث[p[ِي]نَ","Улар: «Ҳаёт–бу дунё ҳаёти, холос, биз қайта тирилтилмасмиз», дедилар.",131,7],["وَلَوْ تَرَ[o[ىٰٓ] إِذْ وُقِفُو[s[اْ] عَلَىٰ رَبِّهِمْ‌ۚ قَالَ أَلَيْسَ هَ[n[ـٰ]ذَا بِ[h:370[ٱ]لْحَقِّ‌ۚ قَالُو[s[اْ] بَلَىٰ وَرَبِّنَا‌ۚ قَالَ فَذُوقُو[s[اْ] [h:2154[ٱ]لْعَذَابَ بِمَا كُ[f:100[نت]ُمْ تَكْفُر[p[ُو]نَ","Аллоҳнинг ҳузурида тўхтатилганларида, У: «Мана шу ҳақ эмасми?!» деганида, «Роббимизга қасамки ҳақдир», деганларини, У: «Бас, куфр келтирганингиз учун азобини чекинг», дейишини кўрсанг эди.",131,7],["قَ[q:298[دْ] خَسِرَ [h:3997[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِلِق[o[َا]ٓءِ [h:3998[ٱ]للَّهِ‌ۖ حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءَتْهُمُ [h:3999[ٱ][l[ل]سَّاعَةُ بَغْتَ[f:4000[ةً ق]َالُو[s[اْ] يَ[n[ـٰ]حَسْرَتَنَا عَلَىٰ مَا فَرَّ[q:4001[طْ]نَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ‌ۚ أَلَا س[o[َا]ٓءَ مَا يَزِر[p[ُو]نَ","Аллоҳга рўбарў бўлишни ёлғон деганлар, шубҳасиз, зиёнга учрадилар. То тўсатдан қиёмат келиб қолганда, устларига гуноҳларини орқалаб олган ҳолларида: «У да қилган камчиликларимизга ҳасрат-надоматлар бўлсин», дейдилар. Улар орқалаган нарса қандай ёмон-а!",131,7],["وَمَا [h:2482[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْي[o[َآ] إِلَّا لَعِ[a:4002[بٌ و]َلَهْ[a:4003[وٌ‌ۖ و]َلَلدَّارُ [h:4004[ٱ]لْأَخِرَةُ خَيْ[u:4005[رٌ ل]ِّلَّذِينَ يَتَّقُونَ‌ۗ أَفَلَا تَعْقِل[p[ُو]نَ","Бу дунё ҳаёти ўйин-кулгудан ўзга ҳеч нарса эмас. Тақво қилувчилар учун охират ҳовлиси яхшироқдир. Ақл юритмайсизларми?",131,7],["قَ[q:298[دْ] نَعْلَمُ إِ[g[نّ]َهُ[n[ۥ] لَيَحْزُنُكَ [h:4006[ٱ]لَّذِى يَقُولُونَ‌ۖ فَإِ[g[نّ]َهُمْ لَا يُكَذِّبُونَكَ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:4007[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ يَ[q:4008[جْ]حَد[p[ُو]نَ","Сени, албатта, уларнинг айтаётганлари хафа қилишини яхши биламиз. Улар сени ёлғончига чиқараётганлари йўқ, балки золимлар Аллоҳнинг оятларини инкор қилмоқдалар.",131,7],["وَلَقَ[q:341[دْ] كُذِّبَتْ رُسُ[a:2469[لٌ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ فَصَبَرُو[s[اْ] عَلَىٰ مَا كُذِّبُو[s[اْ] وَأُوذُو[s[اْ] حَتَّ[o[ىٰٓ] أَتَ[n[ـٰ]هُمْ نَصْرُنَا‌ۚ وَلَا مُبَدِّلَ لِكَلِمَ[n[ـٰ]تِ [h:4009[ٱ]للَّهِ‌ۚ وَلَقَ[q:341[دْ] ج[o[َا]ٓءَكَ م[a:4010[ِن ن]َّبَإِ[s[ىْ] [h:4011[ٱ]لْمُرْسَل[p[ِي]نَ","Сендан олдин ҳам Пайғамбарлар ёлғончига чиқарилганлар. Бас, улар то нусрат келгунча ёлғончига чиқарилганларига ва берилган озорларга сабр қилганлар. Аллоҳнинг сўзларини ўзгартирувчи йўқ. Батаҳқиқ, сенга Пайғамбарларнинг хабари келган.",131,7],["وَإِ[f:1649[ن ك]َانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ [h:4012[ٱ]سْتَطَعْتَ أَ[f:4013[ن ت]َ[q:4014[بْ]تَغِىَ نَفَ[f:4015[قًا ف]ِى [h:44[ٱ]لْأَرْضِ أَوْ سُلَّ[f:4016[مًا ف]ِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ فَتَأْتِيَه[c:4017[ُم ب]ِـَٔـايَ[a:4018[ةٍ‌ۚ و]َلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ لَجَمَعَهُمْ عَلَى [h:4019[ٱ]لْهُدَىٰ‌ۚ فَلَا تَكُونَ[g[نّ]َ مِنَ [h:352[ٱ]لْجَ[n[ـٰ]هِل[p[ِي]نَ","Агар сенга уларнинг юз ўгиришлари оғир ботаётган бўлса, қодир бўлсанг, ер остидан йўл қилиб ёки осмонга нарвон қўйиб, уларга оят-мўъжиза келтир. Аллоҳ хоҳлаганида, уларни ҳидоятга жамларди. Ҳаргиз жоҳиллардан бўлма.",131,7],["۞ إِ[g[نّ]َمَا يَسْتَجِيبُ [h:4020[ٱ]لَّذِينَ يَسْمَعُونَ‌ۘ وَ[h:4021[ٱ]لْمَوْتَىٰ يَ[q:4022[بْ]عَثُهُمُ [h:4023[ٱ]للَّهُ ثُ[g[مّ]َ إِلَيْهِ يُرْجَع[p[ُو]نَ","Албатта, тинглай оладиганларгина қабул қилурлар. Ўликларни эса Аллоҳ тирилтирур ва сўнгра Унинг Ўзига қайтарилурлар.",132,7],["وَقَالُو[s[اْ] لَوْلَا نُزِّلَ عَلَيْهِ ءَايَ[a:4024[ةٌ م]ّ[u:192[ِن ر]َّبِّه[n[ِۦ]‌ۚ قُلْ إِ[g[نّ]َ [h:80[ٱ]للَّهَ قَادِرٌ عَلَ[o[ىٰٓ] أ[a:473[َن ي]ُنَزِّلَ ءَايَ[a:4025[ةً و]َلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَعْلَم[p[ُو]نَ","Улар: «Унга Роббидан бир оят-мўъжиза тушса эди?» дерлар. Сен: «Албатта, Аллоҳ оят-мўъжиза туширишга қодирдир», деб айт. Лекин кўплари билмаслар.",132,7],["وَمَا مِ[f:4026[ن د][m[َا]ٓبَّ[f:4027[ةٍ ف]ِى [h:44[ٱ]لْأَرْضِ وَلَا طَ[o[ـٰٓ]ئِ[a:4028[رٍ ي]َطِيرُ بِجَنَاحَيْهِ إِلّ[o[َآ] أُمَمٌ أَمْثَالُك[w:4029[ُم‌ۚ م]َّا فَرَّ[q:4001[طْ]نَا فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ مِ[f:2103[ن ش][f:4030[َىْءٍ‌ۚ ث]ُ[g[مّ]َ إِلَىٰ رَبِّهِمْ يُحْشَر[p[ُو]نَ","Ер юзидаги юрувчи ҳар бир жонзот ва икки қаноти ила учувчи қуш борки, ҳаммаси сиз каби умматлардир. Китобга ҳеч нарсани қўймай ёзганмиз. Сўнгра Роббиларига жамланурлар.",132,7],["وَ[h:9999[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا صُ[a:4031[[g[مّ]ٌ و]َبُكْ[f:4032[مٌ ف]ِى [h:4033[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ‌ۗ م[a:4034[َن ي]َشَإِ [h:4035[ٱ]للَّهُ يُضْلِلْهُ وَم[a:4036[َن ي]َشَأْ يَ[q:4037[جْ]عَلْهُ عَلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Оятларимизни ёлғонга чиқарганлар кар ва соқовлардир. Аллоҳ кимни хоҳласа, адаштирар ва кимни хоҳласа, тўғри йўлда барқарор қилиб қўядир.",132,7],["قُلْ أَرَءَيْتَكُمْ إِنْ أَتَ[n[ـٰ]كُمْ عَذَابُ [h:4038[ٱ]للَّهِ أَوْ أَتَتْكُمُ [h:4039[ٱ][l[ل]سَّاعَةُ أَغَيْرَ [h:3954[ٱ]للَّهِ تَ[q:4040[دْ]عُونَ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Сен: «Агар ростгўй бўлсаларингиз, айтинг-чи, сизга Аллоҳнинг азоби ёки қиёмат соати келганда Аллоҳдан бошқага дуо қиласизларми?",132,7],["بَلْ إِيَّاهُ تَ[q:4040[دْ]عُونَ فَيَكْشِفُ مَا تَ[q:4040[دْ]عُونَ إِلَيْهِ إِ[f:364[ن ش][o[َا]ٓءَ وَتَ[f:220[نس]َوْنَ مَا تُشْرِك[p[ُو]نَ","Йўқ! Фақат Унгагина дуо қиласиз. У эса, хоҳласа, сиз дуо қилган нарсага кушойиш берадир. Сиз эса ширк келтираётган нарсангизни унутарсиз», деб айт.",132,7],["وَلَقَ[q:341[دْ] أَرْسَلْن[o[َآ] إِلَ[o[ىٰٓ] أُمَ[a:4041[مٍ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ فَأَخَذْنَ[n[ـٰ]ه[c:4042[ُم ب]ِ[h:4043[ٱ]لْبَأْس[o[َا]ٓءِ وَ[h:920[ٱ][l[ل]ضَّرّ[o[َا]ٓءِ لَعَلَّهُمْ يَتَضَرَّع[p[ُو]نَ","Батаҳқиқ, Биз сендан олдинги умматларга ҳам Пайғамбарлар юборганмиз. Сўнгра, шояд тазарруъ қилсалар, деб уларни бало ва зиёнларга тутганмиз.",132,7],["فَلَوْل[o[َآ] إِذْ ج[o[َا]ٓءَه[c:4044[ُم ب]َأْسُنَا تَضَرَّعُو[s[اْ] وَلَ[n[ـٰ]كِ[f:4045[ن ق]َسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ [h:4046[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Бизнинг баломиз уларга етганда, тазарруъ қилсалар эди! Лекин қалблари қаттиқ бўлди ва шайтон уларга қилаётган ишларини зийнатлаб кўрсатди.",132,7],["فَلَ[g[مّ]َا نَسُو[s[اْ] مَا ذُكِّرُو[s[اْ] بِه[n[ِۦ] فَتَحْنَا عَلَيْهِمْ أَ[q:4047[بْ]و[n[َٲ]بَ كُلِّ شَىْءٍ حَتَّ[o[ىٰٓ] إِذَا فَرِحُو[s[اْ] بِم[o[َآ] أُوت[o[ُوٓ][s[اْ] أَخَذْنَ[n[ـٰ]ه[c:4048[ُم ب]َغْتَ[f:4049[ةً ف]َإِذَا ه[w:4050[ُم م]ُّ[q:4051[بْ]لِس[p[ُو]نَ","Эслатилган нарсаларни унутган чоғларида, уларга ҳамма нарсанинг эшикларини очиб қўйдик. Ўзларига берилган нарсалардан хурсанд бўлиб турганларида, уларни бирданига тутдик. Бас, қарабсизки, бутунлай ноумид бўлдилар.",132,7],["فَقُطِعَ دَابِرُ [h:4052[ٱ]لْقَوْمِ [h:4053[ٱ]لَّذِينَ ظَلَمُو[s[اْ‌ۚ] وَ[h:4054[ٱ]لْحَمْدُ لِلَّهِ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Бас, зулм қилган қавмларнинг кети кесилди. Оламларнинг Робби Аллоҳга ҳамдлар бўлсин.",133,7],["قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ [h:2057[ٱ]للَّهُ سَمْعَكُمْ وَأَ[q:4055[بْ]صَ[n[ـٰ]رَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِك[w:4056[ُم م]َّنْ إِلَ[n[ـٰ]هٌ غَيْرُ [h:4057[ٱ]للَّهِ يَأْتِيك[c:4058[ُم ب]ِهِ‌ۗ [h:4059[ٱ][f:2837[نظ]ُرْ كَيْفَ نُصَرِّفُ [h:4060[ٱ]لْأَيَ[n[ـٰ]تِ ثُ[g[مّ]َ هُمْ يَصْدِف[p[ُو]نَ","Уларга: «Айтинг-чи, агар Аллоҳ қулоқ ва кўзларингизни олиб қўйса, қалбларингизга муҳр босса, Аллоҳдан ўзга қайси илоҳ уни сизга беради», дегин. Биз оятларни қандай келтиришимизга, сўнгра уларнинг қандай юз ўгириб кетишига назар сол.",133,7],["قُلْ أَرَءَيْتَكُمْ إِنْ أَتَ[n[ـٰ]كُمْ عَذَابُ [h:4038[ٱ]للَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا [h:4061[ٱ]لْقَوْمُ [h:4062[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Уларга: «Аайтинг-чи, агар сизга Аллоҳнинг азоби бирданига ёки очиқчасига келса, золим қавмларгина ҳалок қилинадилар-ку!» деб айт.",133,7],["وَمَا نُرْسِلُ [h:4063[ٱ]لْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُ[f:1163[نذ]ِرِينَ‌ۖ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Биз Пайғамбарларни фақат башорат берувчи ва огоҳлантирувчи қилиб юборамиз. Ким иймон келтириб, амали солиҳ қилса, уларга хавфу хатар йўқ ва улар ранжимаслар.",133,7],["وَ[h:9999[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا يَمَسُّهُمُ [h:4064[ٱ]لْعَذَابُ بِمَا كَانُو[s[اْ] يَفْسُق[p[ُو]نَ","Оятларимизни ёлғонга чиқарганларни фосиқлик қилганлари учун азоб тутадир.",133,7],["قُل لّ[o[َآ] أَقُولُ لَكُمْ عِ[f:4065[ند]ِى خَز[o[َا]ٓئِنُ [h:4066[ٱ]للَّهِ وَل[o[َآ] أَعْلَمُ [h:4067[ٱ]لْغَيْبَ وَل[o[َآ] أَقُولُ لَكُمْ إِ[g[نّ]ِى مَلَكٌ‌ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَ[o[ىٰٓ] إِلَىَّ‌ۚ قُلْ هَلْ يَسْتَوِى [h:4068[ٱ]لْأَعْمَىٰ وَ[h:4069[ٱ]لْبَصِيرُ‌ۚ أَفَلَا تَتَفَكَّر[p[ُو]نَ","Сен: «Сизларга, ҳузуримда Аллоҳнинг хазиналари бор, демайман. Ғайбни биламан ҳам, демайман. Ва яна сизларга, мен фариштаман, ҳам демайман. Мен фақат ўзимга ваҳий қилинган нарсага эргашаман, холос», деб айт. Сен: «Кўр билан кўзи ўткир тенг бўла оладими? Ўйлаб кўрмайсизларми?» деб айт.",133,7],["وَأَ[f:4070[نذ]ِرْ بِهِ [h:4071[ٱ]لَّذِينَ يَخَافُونَ أ[a:4072[َن ي]ُحْشَر[o[ُوٓ][s[اْ] إِلَىٰ رَبِّهِمْ‌ۙ لَيْسَ لَه[w:1812[ُم م]ِّ[f:3136[ن د]ُونِه[n[ِۦ] وَلِ[a:4073[ىٌّ و]َلَا شَفِي[u:4074[عٌ ل]َّعَلَّهُمْ يَتَّق[p[ُو]نَ","У билан Роббиларига тўпланишдан қўрқадиганларни огоҳлантир. Уларга Ундан ўзга валий ҳам, шафоатчи ҳам йўқ. Шоядки тақводор бўлсалар.",133,7],["وَلَا تَ[q:4075[طْ]رُدِ [h:4076[ٱ]لَّذِينَ يَ[q:1240[دْ]عُونَ رَبَّه[c:4077[ُم ب]ِ[h:4078[ٱ]لْغَدَ[s[و][n[ٲ]ةِ وَ[h:4079[ٱ]لْعَشِىِّ يُرِيدُونَ وَ[q:580[جْ]هَهُ[n[ۥ]‌ۖ مَا عَلَيْكَ مِنْ حِسَابِه[w:4080[ِم م]ِّ[f:2103[ن ش][a:4081[َىْءٍ و]َمَا مِنْ حِسَابِكَ عَلَيْه[w:4082[ِم م]ِّ[f:2103[ن ش][f:4083[َىْءٍ ف]َتَ[q:4084[طْ]رُدَهُمْ فَتَكُونَ مِنَ [h:187[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Эртаю кеч Роббиларига Унинг юзини ирода қилиб дуо этаётганларни ҳайдама! Уларнинг ҳисобидан сенинг зиммангда ҳеч нарса йўқ. Сенинг ҳисобингдан уларнинг зиммасида ҳеч нарса йўқ. Уларни ҳайдаб, золимлардан бўлиб қолма.",133,7],["وَكَذ[n[َٲ]لِكَ فَتَ[g[نّ]َا بَعْضَه[c:1438[ُم ب]ِبَعْ[u:4085[ضٍ ل]ِّيَقُول[o[ُوٓ][s[اْ] أَهَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ مَ[g[نّ]َ [h:2390[ٱ]للَّهُ عَلَيْه[w:4082[ِم م]ّ[i:4086[ِنۢ ب]َيْنِن[o[َآ‌ۗ] أَلَيْسَ [h:4087[ٱ]للَّهُ بِأَعْلَمَ بِ[h:4088[ٱ][l[ل]شَّ[n[ـٰ]كِر[p[ِي]نَ","«Орамиздан Аллоҳ неъмат берганлар шуларми?» дейишлари учун шундай қилиб, баъзиларини баъзилари ила синадик. Аллоҳнинг Ўзи шукр қилувчиларни яхши билгувчи эмасми?",134,7],["وَإِذَا ج[o[َا]ٓءَكَ [h:4089[ٱ]لَّذِينَ يُؤْمِنُونَ بِـَٔـايَ[n[ـٰ]تِنَا فَقُلْ سَلَ[n[ـٰ]مٌ عَلَيْكُمْ‌ۖ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ [h:3952[ٱ][l[ل]رَّحْمَةَ‌ۖ أَ[g[نّ]َهُ[n[ۥ] مَنْ عَمِلَ مِ[f:344[نك]ُمْ س[o[ُو]ٓء[i:4090[َۢا ب]ِجَهَ[n[ـٰ]لَ[f:2649[ةٍ ث]ُ[g[مّ]َ تَابَ م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] وَأَصْلَحَ فَأَ[g[نّ]َهُ[n[ۥ] غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Агар ҳузурингга оятларимизга иймон келтирганлар келсалар: «Сизларга салом бўлсин, Роббингиз Ўз зиммасига раҳматни ёзди. Сиздан ким билмасдан ёмонлик қилса, сўнгра ундан кейин тавба қилиб, амали солиҳ қилса, бас, албатта, У зот мағфиратли ва раҳмли зотдир», деб айт.",134,7],["وَكَذ[n[َٲ]لِكَ نُفَصِّلُ [h:4091[ٱ]لْأَيَ[n[ـٰ]تِ وَلِتَسْتَبِينَ سَبِيلُ [h:4092[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","Шундай қилиб, жиноятчиларнинг йўли ошкор бўлиши учун оятларни муфассал баён қиламиз.",134,7],["قُلْ إِ[g[نّ]ِى نُهِيتُ أَنْ أَعْبُدَ [h:4094[ٱ]لَّذِينَ تَ[q:4040[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ‌ۚ قُل لّ[o[َآ] أَتَّبِعُ أَهْو[o[َا]ٓءَكُمْ‌ۙ قَ[q:298[دْ] ضَلَلْتُ إِ[a:4095[ذًا و]َم[o[َآ] أَنَا۟ مِنَ [h:4096[ٱ]لْمُهْتَد[p[ِي]نَ","Сен: «Мен Аллоҳни қўйиб, сиз ибодат қилаётганларга ибодат қилишдан қайтарилганман», деб айт. Сен: «Мен сизнинг ҳавойи нафсларингизга эргашмайман. Зеро, адашган бўламан ва ҳидоят топганлардан бўлмай қоламан», деб айт.",134,7],["قُلْ إِ[g[نّ]ِى عَلَىٰ بَيِّنَ[a:4097[ةٍ م]ّ[u:4098[ِن ر]َّبِّى وَكَذَّ[q:4099[بْ]ت[c:4100[ُم ب]ِه[n[ِۦ]‌ۚ مَا عِ[f:4065[ند]ِى مَا تَسْتَعْجِلُونَ بِه[o[ِۦٓ‌ۚ] إِنِ [h:4101[ٱ]لْحُكْمُ إِلَّا لِلَّهِ‌ۖ يَقُصُّ [h:4102[ٱ]لْحَقَّ‌ۖ وَهُوَ خَيْرُ [h:4103[ٱ]لْفَ[n[ـٰ]صِل[p[ِي]نَ","«Албатта, мен Роббимдан берилган аниқ ҳужжатга эгаман. Сизлар уни ёлғонга чиқардингиз. Сиз шошилтираётган нарса менда йўқ. Ҳукм фақат Аллоҳнинг ўзига хосдир. У ҳақни аниқлайди. У ажрим қилувчиларнинг энг яхшиси», деб айт.",134,7],["قُل لَّوْ أَ[g[نّ]َ عِ[f:4065[ند]ِى مَا تَسْتَعْجِلُونَ بِه[n[ِۦ] لَقُضِىَ [h:3943[ٱ]لْأَمْرُ بَيْنِى وَبَيْنَكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ أَعْلَمُ بِ[h:498[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Сен: «Агар сиз шошилтираётган нарса менинг ҳузуримда бўлса эди, мен билан сизнинг орангизда иш аллақачон битган бўлар эди. Аллоҳ золимларни яхши билгувчидир», деб айт.",134,7],["۞ وَعِ[f:4104[ند]َهُ[n[ۥ] مَفَاتِحُ [h:4105[ٱ]لْغَيْبِ لَا يَعْلَمُه[o[َآ] إِلَّا هُوَ‌ۚ وَيَعْلَمُ مَا فِى [h:4106[ٱ]لْبَرِّ وَ[h:4107[ٱ]لْبَحْرِ‌ۚ وَمَا تَسْقُطُ م[a:4108[ِن و]َرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّ[f:4109[ةٍ ف]ِى ظُلُمَ[n[ـٰ]تِ [h:4110[ٱ]لْأَرْضِ وَلَا رَ[q:4111[طْ][a:4112[بٍ و]َلَا يَابِسٍ إِلَّا فِى كِتَ[n[ـٰ][a:4113[بٍ م]ُّب[p[ِي]نٍ","Ғайбнинг калитлари Унинг ҳузурида бўлиб, Уларни унинг Ўзидан бошқа ҳеч ким билмас. У ердаги, қуруқлик ва денгиздаги нарсаларни биладир. Битта япроқ узилиб тушмайдики, магар уни ҳам биладир. Ер тубидаги бир дона дон борми, ҳўлу қуруқ борми, барчаси очиқ китобда бордир.",134,7],["وَهُوَ [h:4114[ٱ]لَّذِى يَتَوَفَّ[n[ـٰ]ك[c:4115[ُم ب]ِ[h:1622[ٱ]لَّيْلِ وَيَعْلَمُ مَا جَرَحْت[c:4116[ُم ب]ِ[h:4117[ٱ][l[ل][g[نّ]َهَارِ ثُ[g[مّ]َ يَ[q:4118[بْ]عَثُكُمْ فِيهِ لِيُ[q:4119[قْ]ضَ[o[ىٰٓ] أَجَ[a:4120[لٌ م]ُّسَم[f:4121[ًّى‌ۖ ث]ُ[g[مّ]َ إِلَيْهِ مَرْجِعُكُمْ ثُ[g[مّ]َ يُنَبِّئُك[c:4122[ُم ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","У кечаси сизни вафот этдирар. У кундузи қилган касбингизни билар. Сўнгра белгилаган ажал тугал бўлиши учун У да сизни қайта тирилтирар. Сўнгра қайтиб боришингиз Унинг Ўзигадир. Сўнгра нима қилиб юрганингизнинг хабарини берар.",135,7],["وَهُوَ [h:3966[ٱ]لْقَاهِرُ فَوْقَ عِبَادِه[n[ِۦ]‌ۖ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءَ أَحَدَكُمُ [h:942[ٱ]لْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّط[p[ُو]نَ","У бандалари устидан ғолибдир. У устингизга ҳафазаларини юборур. Қачонки бирортангизга ўлим келса, элчиларимиз камчиликка йўл қўймаган ҳолда уни вафот эттирарлар.",135,7],["ثُ[g[مّ]َ رُدّ[o[ُوٓ][s[اْ] إِلَى [h:1637[ٱ]للَّهِ مَوْلَ[n[ـٰ]هُمُ [h:4123[ٱ]لْحَقِّ‌ۚ أَلَا لَهُ [h:4124[ٱ]لْحُكْمُ وَهُوَ أَسْرَعُ [h:4125[ٱ]لْحَ[n[ـٰ]سِب[p[ِي]نَ","Сўнгра ҳақиқий хўжалари–Аллоҳга қайтарилурлар. Огоҳ бўлингизким, ҳукм қилиш Унинг Ўзигагина хосдир. Ва У энг тезкор ҳисоб-китоб қилгувчидир.",135,7],["قُلْ م[a:4126[َن ي]ُنَجِّيك[w:4127[ُم م]ِّ[f:4128[ن ظ]ُلُمَ[n[ـٰ]تِ [h:4129[ٱ]لْبَرِّ وَ[h:4107[ٱ]لْبَحْرِ تَ[q:4130[دْ]عُونَهُ[n[ۥ] تَضَرُّ[a:4131[عًا و]َخُفْيَ[u:4132[ةً ل]َّئِنْ أَ[f:4133[نج]َ[n[ـٰ]نَا مِنْ هَ[n[ـٰ]ذِه[n[ِۦ] لَنَكُونَ[g[نّ]َ مِنَ [h:4134[ٱ][l[ل]شَّ[n[ـٰ]كِر[p[ِي]نَ","Сен: «Сизни қуруқлигу денгизнинг зулматларидан қутқарадиган ким? Унга тазарруъ қилган ҳолда ва махфий ҳолда, агар мана шундан бизни қутқарса, албатта, шукр қилувчилардан бўлар эдик, дейдиганингиз ким?» деб айт.",135,7],["قُلِ [h:3166[ٱ]للَّهُ يُنَجِّيك[w:4135[ُم م]ِّنْهَا وَمِ[f:4136[ن ك]ُلِّ كَرْ[f:4137[بٍ ث]ُ[g[مّ]َ أَ[f:428[نت]ُمْ تُشْرِك[p[ُو]نَ","Сен: «Сизни улардан ва барча ғамлардан Аллоҳ қутқарар. Сўнгра эса, сиз ширк келтирасиз», деб айт.",135,7],["قُلْ هُوَ [h:4138[ٱ]لْقَادِرُ عَلَ[o[ىٰٓ] أ[a:4139[َن ي]َ[q:4140[بْ]عَثَ عَلَيْكُمْ عَذَا[a:4141[بًا م]ِّ[f:4142[ن ف]َوْقِكُمْ أَوْ مِ[f:4143[ن ت]َحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَ[a:4144[عًا و]َيُذِيقَ بَعْضَك[c:4145[ُم ب]َأْسَ بَعْضٍ‌ۗ [h:4146[ٱ][f:2837[نظ]ُرْ كَيْفَ نُصَرِّفُ [h:4060[ٱ]لْأَيَ[n[ـٰ]تِ لَعَلَّهُمْ يَفْقَه[p[ُو]نَ","Сен: «У сизга устингиздан ёки оёғингиз остидан азоб юборишга, турли фирқаларга аралаштириб юборишга, баъзиларингизга баъзиларингизнинг азобини тотдиришга қодирдир», деб айт. Оятларимизни қандай тасарруф қилишимизга назар сол. Шоядки англаб етсалар.",135,7],["وَكَذَّبَ بِه[n[ِۦ] قَوْمُكَ وَهُوَ [h:479[ٱ]لْحَقُّ‌ۚ قُل لَّسْتُ عَلَيْك[c:4147[ُم ب]ِوَك[p[ِي]لٍ","Қавминг уни ёлғонга чиқарди. Ҳолбуки у ҳақдир. Сен: «Мен сизларга вакил эмасман.",135,7],["لِّكُلِّ نَبَ[a:4148[إٍ م]ُّسْتَقَ[a:4149[رٌّ‌ۚ و]َسَوْفَ تَعْلَم[p[ُو]نَ","Ҳар бир хабарнинг ўз вақти бор. Тезда буни биласизлар», деб айт.",135,7],["وَإِذَا رَأَيْتَ [h:4150[ٱ]لَّذِينَ يَخُوضُونَ ف[o[ِىٓ] ءَايَ[n[ـٰ]تِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُو[s[اْ] فِى حَدِيثٍ غَيْرِه[n[ِۦ]‌ۚ وَإِ[g[مّ]َا يُ[f:4151[نس]ِيَ[g[نّ]َكَ [h:4152[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ فَلَا تَ[q:4153[قْ]عُ[q:4153[دْ] بَعْدَ [h:4154[ٱ][l[ل]ذِّكْرَىٰ مَعَ [h:3746[ٱ]لْقَوْمِ [h:4155[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Оятлармизни шунғиётганларни кўрган чоғингда, то ундан бошқа гапга шунғигунларича улардан юз ўгир. Агар шайтон эсингдан чиқарган бўлса, эслаганингдан сўнг, золим қавмлар билан ўтирма!",135,7],["وَمَا عَلَى [h:289[ٱ]لَّذِينَ يَتَّقُونَ مِنْ حِسَابِه[w:4080[ِم م]ِّ[f:2103[ن ش][a:4156[َىْءٍ و]َلَ[n[ـٰ]كِ[f:4157[ن ذ]ِكْرَىٰ لَعَلَّهُمْ يَتَّق[p[ُو]نَ","Тақво қиладиганлар зиммасида у «мушрик»ларнинг ҳисобидан ҳеч нарса йўқ. Лекин эслатма бор. Шоядки тақво қилсалар.",136,7],["وَذَرِ [h:4158[ٱ]لَّذِينَ [h:3645[ٱ]تَّخَذُو[s[اْ] دِينَهُمْ لَعِ[a:4159[بًا و]َلَهْ[a:4160[وًا و]َغَرَّتْهُمُ [h:4161[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَا‌ۚ وَذَكِّرْ بِه[o[ِۦٓ] أَ[f:4162[ن ت]ُ[q:4163[بْ]سَلَ نَفْ[i:4164[سُۢ ب]ِمَا كَسَبَتْ لَيْسَ لَهَا مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَلِ[a:4073[ىٌّ و]َلَا شَفِي[a:4165[عٌ و]َإِ[f:4166[ن ت]َعْدِلْ كُلَّ عَ[q:3797[دْ][u:4167[لٍ ل]َّا يُؤْخَذْ مِنْه[o[َآ‌ۗ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ أُ[q:4168[بْ]سِلُو[s[اْ] بِمَا كَسَبُو[s[اْ‌ۖ] لَهُمْ شَرَا[a:4169[بٌ م]ِّنْ حَمِي[a:4170[مٍ و]َعَذَابٌ أَلِي[i:43[مُۢ ب]ِمَا كَانُو[s[اْ] يَكْفُر[p[ُو]نَ","Ўз динларини ўйин-кулгу қилиб олган ва ҳаёти дунёга алданиб кетганларни тарк эт. У ила эслатгин, ҳеч бир жон қилган касби туфайли ҳалокатга дучор бўлиб, Аллоҳдан ўзга бирор дўст ва шафоатчисиз ҳолга ва барча фидо қиладиган нарсани фидо қилса ҳам, ундан қабул қилинмайдиган ҳолга тушиб қолмасин. Ана ўшалар қилган касблари туфайли ҳалокатга дучор бўлганлардир. Куфр келтирганлари учун уларга қайноқ сувдан шароб ва аламли азоб бордир.",136,7],["قُلْ أَنَ[q:4171[دْ]عُو[s[اْ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مَا لَا يَ[f:4172[نف]َعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَ[o[ىٰٓ] أَعْقَابِنَا بَعْدَ إِذْ هَدَ[n[ٮٰ]نَا [h:4173[ٱ]للَّهُ كَ[h:1506[ٱ]لَّذِى [h:4174[ٱ]سْتَهْوَتْهُ [h:4175[ٱ][l[ل]شَّيَ[n[ـٰ]طِينُ فِى [h:44[ٱ]لْأَرْضِ حَيْرَانَ لَهُ[o[ۥٓ] أَصْحَ[n[ـٰ][a:4176[بٌ ي]َ[q:4177[دْ]عُونَهُ[o[ۥٓ] إِلَى [h:4178[ٱ]لْهُدَى [h:4179[ٱ]ئْتِنَا‌ۗ قُلْ إِ[g[نّ]َ هُدَى [h:629[ٱ]للَّهِ هُوَ [h:630[ٱ]لْهُدَىٰ‌ۖ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ [h:687[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Сен: «Аллоҳни қўйиб на фойда, на зарар бера олмайдиган нарсаларга ибодат қиламизми? Худди оғайнилари, бу ёққа кел, деб ҳидоятга чақириб турган бўлса ҳам, шайтон адаштириб, ер юзида ҳайрон бўлиб қолганга ўхшаб, Аллоҳ бизни ҳидоятга солгандан кейин орқамизга қайтамизми?» деб айт. Сен: «Албатта, Аллоҳнинг ҳидояти ҳақиқий ҳидоятдир. Оламларнинг Роббига таслим бўлишга амр қилинганмиз», деб айт.",136,7],["وَأَنْ أَقِيمُو[s[اْ] [h:4180[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَ[h:4181[ٱ]تَّقُوهُ‌ۚ وَهُوَ [h:4114[ٱ]لَّذ[o[ِىٓ] إِلَيْهِ تُحْشَر[p[ُو]نَ","Намозни қоим қилинг ва Аллоҳга тақво қилинг! У сизлар ҳузурига тўпланадиган зотдир.",136,7],["وَهُوَ [h:4114[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ بِ[h:370[ٱ]لْحَقِّ‌ۖ وَيَوْمَ يَقُولُ كُ[f:613[ن ف]َيَكُونُ‌ۚ قَوْلُهُ [h:4182[ٱ]لْحَقُّ‌ۚ وَلَهُ [h:4183[ٱ]لْمُلْكُ يَوْمَ يُ[f:4184[نف]َخُ فِى [h:4185[ٱ][l[ل]صُّورِ‌ۚ عَ[n[ـٰ]لِمُ [h:4186[ٱ]لْغَيْبِ وَ[h:4187[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ‌ۚ وَهُوَ [h:3967[ٱ]لْحَكِيمُ [h:3968[ٱ]لْخَب[p[ِي]رُ","У осмонлару ерни ҳақ ила яратган зотдир. «Бўл», деган куни бўладир. Унинг гапи ҳақдир. Дуд чалинадиган куни мулк Уникидир. У ғайбни ҳам, шоҳидни ҳам билувчи зотдир. Ва У ҳакийм ва хабардор Зотдир.",136,7],["۞ وَإِذْ قَالَ إِ[q:2003[بْ]ر[n[َٲ]هِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً‌ۖ إِ[g[نّ][o[ِىٓ] أَرَ[n[ٮٰ]كَ وَقَوْمَكَ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Иброҳимнинг отаси Озарга: «Санамларни худолар қилиб оласанми? Мен сени ва сенинг қавмингни, албатта, очиқ-ойдин адашувда кўрмоқдаман», деганини эсла.",137,7],["وَكَذ[n[َٲ]لِكَ نُر[o[ِىٓ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ مَلَكُوتَ [h:4188[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَلِيَكُونَ مِنَ [h:4189[ٱ]لْمُوقِن[p[ِي]نَ","Худди шундай қилиб, Иброҳимга аниқ ишонувчилардан бўлиши учун осмонлару ернинг мулкларини кўрсатамиз.",137,7],["فَلَ[g[مّ]َا جَ[g[نّ]َ عَلَيْهِ [h:4190[ٱ]لَّيْلُ رَءَا كَوْكَ[f:4191[بًا‌ۖ ق]َالَ هَ[n[ـٰ]ذَا رَبِّى‌ۖ فَلَ[g[مّ][o[َآ] أَفَلَ قَالَ ل[o[َآ] أُحِبُّ [h:4192[ٱ]لْأَفِل[p[ِي]نَ","Уни тун ўраб олганида юлдузни кўриб: «Мана шу Роббимдир», деди. У ботиб кетганида эса: «Ботувчиларни ёқтирмасман», деди.",137,7],["فَلَ[g[مّ]َا رَءَا [h:4193[ٱ]لْقَمَرَ بَازِ[f:4194[غًا ق]َالَ هَ[n[ـٰ]ذَا رَبِّى‌ۖ فَلَ[g[مّ][o[َآ] أَفَلَ قَالَ لَئ[u:4195[ِن ل]َّمْ يَهْدِنِى رَبِّى لَأَكُونَ[g[نّ]َ مِنَ [h:4196[ٱ]لْقَوْمِ [h:4197[ٱ][l[ل]ضّ[m[َا]ٓلّ[p[ِي]نَ","Чиқаётган ойни кўрганда: «Мана шу Роббимдир», деди. У ҳам ботганида: «Агар Роббим мени тўғри йўлга бошламаса, албатта, адашувчилардан бўламан», деди.",137,7],["فَلَ[g[مّ]َا رَءَا [h:4198[ٱ][l[ل]شَّمْسَ بَازِغَ[f:4199[ةً ق]َالَ هَ[n[ـٰ]ذَا رَبِّى هَ[n[ـٰ]ذ[o[َآ] أَكْبَرُ‌ۖ فَلَ[g[مّ][o[َآ] أَفَلَتْ قَالَ يَ[n[ـٰ]قَوْمِ إِ[g[نّ]ِى بَر[o[ِى]ٓ[a:3977[ءٌ م]ِّ[g[مّ]َا تُشْرِك[p[ُو]نَ","Чиқаётган қуёшни кўрганда: «Мана шу Роббим. Бу каттароқ», деди. У ҳам ботиб кетганида: «Эй қавмим, мен сиз ширк келтираётган нарсадан воз кечдим», деди.",137,7],["إِ[g[نّ]ِى وَجَّهْتُ وَ[q:1805[جْ]هِىَ لِلَّذِى فَطَرَ [h:4200[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ حَنِي[a:698[فًا‌ۖ و]َم[o[َآ] أَنَا۟ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Албатта, мен юзимни осмонлару ерни яратган Зотга, тўғри йўлга мойил бўлган ҳолимда юзлантирдим ва мен мушриклардан эмасман.",137,7],["وَح[m[َا]ٓجَّهُ[n[ۥ] قَوْمُهُ[n[ۥ]‌ۚ قَالَ أَتُحَ[m[ـٰٓ]جّ[m[ُو]ٓ[g[نّ]ِى فِى [h:714[ٱ]للَّهِ وَقَ[q:387[دْ] هَدَ[n[ٮٰ]نِ‌ۚ وَل[o[َآ] أَخَافُ مَا تُشْرِكُونَ بِه[o[ِۦٓ] إِلّ[o[َآ] أ[a:4201[َن ي]َش[o[َا]ٓءَ رَبِّى شَيْـ[a:4202[ـًٔا‌ۗ و]َسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا‌ۗ أَفَلَا تَتَذَكَّر[p[ُو]نَ","Ва қавми у ила тортишди. У: «Мен билан Аллоҳ ҳақида тортишасизларми, ҳолбуки, У мени ҳидоят этди. Мен Унга ширк келтираётган нарсангиздан қўрқмасман. Магар Роббим бирор нарсани ирода этса, бўлиши мумкин. Роббим барча нарсани ўз илми ила қамраб олган. Эсласангиз бўлмасми?",137,7],["وَكَيْفَ أَخَافُ م[o[َآ] أَشْرَكْتُمْ وَلَا تَخَافُونَ أَ[g[نّ]َكُمْ أَشْرَكْت[c:4203[ُم ب]ِ[h:32[ٱ]للَّهِ مَا لَمْ يُنَزِّلْ بِه[n[ِۦ] عَلَيْكُمْ سُلْطَ[n[ـٰ][f:4204[نًا‌ۚ ف]َأَىُّ [h:4205[ٱ]لْفَرِيقَيْنِ أَحَقُّ بِ[h:4206[ٱ]لْأَمْنِ‌ۖ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","Қандай қилиб мен сиз ширк келтирган нарсадан қўрқай. Ҳолбуки, сиз ўзингизга ҳеч ҳужжат туширмаган нарсани Аллоҳга ширк келтириб туриб қўрқмайсиз-у? Агар билсангиз, айтинг-чи, қайси гуруҳ хотиржам бўлишга ҳақлироқ?!» деди.",137,7],["ٱلَّذِينَ ءَامَنُو[s[اْ] وَلَمْ يَلْبِس[o[ُوٓ][s[اْ] إِيمَ[n[ـٰ]نَه[c:4207[ُم ب]ِظُلْمٍ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمُ [h:4208[ٱ]لْأَمْنُ وَه[w:4209[ُم م]ُّهْتَد[p[ُو]نَ","Иймон келтирганлар ва иймонларига зулмни аралаштирмаганлар. Ана ўшаларга хотиржамлик, омонлик бор. Улар ҳидоят топганлардир.",138,7],["وَتِلْكَ حُجَّتُن[o[َآ] ءَاتَيْنَ[n[ـٰ]ه[o[َآ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ عَلَىٰ قَوْمِه[n[ِۦ]‌ۚ نَرْفَعُ دَرَجَ[n[ـٰ][a:4210[تٍ م]ّ[a:4211[َن ن]َّش[o[َا]ٓءُ‌ۗ إِ[g[نّ]َ رَبَّكَ حَكِيمٌ عَل[p[ِي]مٌ","Ана ўшалар Иброҳимга қавмига қарши берган ҳужжатларимиздир. Кимни хоҳласак, даражасини кўтарамиз. Албатта, Роббинг ҳикматли ва яхши билувчи зотдир.",138,7],["وَوَهَ[q:4212[بْ]نَا لَهُ[o[ۥٓ] إِسْحَ[n[ـٰ]قَ وَيَعْقُوبَ‌ۚ كُلاًّ هَدَيْنَا‌ۚ وَنُوحًا هَدَيْنَا مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ وَمِ[f:4213[ن ذ]ُرِّيَّتِه[n[ِۦ] دَاوُ[n[ۥ]دَ وَسُلَيْمَ[n[ـٰ]نَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَ[n[ـٰ]رُونَ‌ۚ وَكَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4215[ٱ]لْمُحْسِن[p[ِي]نَ","Ва Биз унга Исҳоқни ва Яъқубни бердик. Барчаларини ҳидоят қилдик. Бундан олдин Нуҳни ҳам ҳидоят қилган эдик. Ва унинг зурриётидан Довуд, Сулаймон, Айюб, Юсуф, Мусо, Ҳорунни. Чиройли амал қилувчиларни ана шундай мукофотлаймиз.",138,7],["وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ‌ۖ كُ[a:4216[لٌّ م]ِّنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Ва Закариё, Яҳё, Ийсо ва Илёсни ҳам. Ҳаммалари аҳли солиҳлардир.",138,7],["وَإِسْمَ[n[ـٰ]عِيلَ وَ[h:4217[ٱ]لْيَسَعَ وَيُونُسَ وَلُو[a:4218[طًا‌ۚ و]َكُل[f:4219[اًّ ف]َضَّلْنَا عَلَى [h:227[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Ва Исмоил, ал-Ясаъ, Юнус ва Лутни ҳам. Барчаларини бутун оламлардан афзал қилдик.",138,7],["وَمِنْ ءَاب[o[َا]ٓئِهِمْ وَذُرِّيَّ[n[ـٰ]تِهِمْ وَإِخْو[n[َٲ]نِهِمْ‌ۖ وَ[h:4220[ٱ][q:4220[جْ]تَبَيْنَ[n[ـٰ]هُمْ وَهَدَيْنَ[n[ـٰ]هُمْ إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Ва уларнинг оталаридан, зурриётларидан ва биродарларидан ҳам ҳидоят қилдик. Уларни танлаб олдик ва сиротул мустақиймга ҳидоят қилдик.",138,7],["ذ[n[َٲ]لِكَ هُدَى [h:629[ٱ]للَّهِ يَهْدِى بِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[n[ِۦ]‌ۚ وَلَوْ أَشْرَكُو[s[اْ] لَحَبِطَ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Ана ўша Аллоҳнинг ҳидояти бўлиб, Ўз бандаларидан кимни хоҳласа, ўшани унга йўллайдир. Агар улар ширк келтирсалар, қилган ишлари, албатта, бехуда кетадир.",138,7],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ ءَاتَيْنَ[n[ـٰ]هُمُ [h:635[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:2046[ٱ]لْحُكْمَ وَ[h:2047[ٱ][l[ل][g[نّ]ُبُوَّةَ‌ۚ فَإ[a:4221[ِن ي]َكْفُرْ بِهَا هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ فَقَ[q:563[دْ] وَكَّلْنَا بِهَا قَوْ[u:4222[مًا ل]َّيْسُو[s[اْ] بِهَا بِكَ[n[ـٰ]فِر[p[ِي]نَ","Ана ўшалар биз уларга китобни, ҳукмни ва Пайғамбарликни берган зотлардир. Агар анавилар буларга куфр келтирсалар, батаҳқиқки, Биз уларга куфр келтирмайдиган қавмни вакил қилиб қўйганмиз.",138,7],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ هَدَى [h:741[ٱ]للَّهُ‌ۖ فَبِهُدَ[n[ٮٰ]هُمُ [h:4223[ٱ][q:4224[قْ]تَدِهْ‌ۗ قُل لّ[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ أَ[q:2795[جْ]رًا‌ۖ إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَ[n[ـٰ]لَم[p[ِي]نَ","Ана ўшалар Аллоҳ ҳидоят қилган зотлардир. Бас, уларнинг ҳидоятига эргаш. «Мен сизлардан бунинг учун ҳақ сўрамайман. У оламлар учун эслатмадан иборат, холос», деб айт.",138,7],["وَمَا قَدَرُو[s[اْ] [h:4225[ٱ]للَّهَ حَقَّ قَ[q:4226[دْ]رِه[o[ِۦٓ] إِذْ قَالُو[s[اْ] م[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ عَلَىٰ بَشَ[a:4227[رٍ م]ِّ[f:2103[ن ش][f:2344[َىْءٍ‌ۗ ق]ُلْ مَنْ أَ[f:471[نز]َلَ [h:4228[ٱ]لْكِتَ[n[ـٰ]بَ [h:4229[ٱ]لَّذِى ج[o[َا]ٓءَ بِه[n[ِۦ] مُوسَىٰ نُو[a:4230[رًا و]َهُ[u:4231[دًى ل]ِّل[g[نّ]َاسِ‌ۖ تَ[q:4232[جْ]عَلُونَهُ[n[ۥ] قَرَاطِيسَ تُ[q:4233[بْ]دُونَهَا وَتُخْفُونَ كَثِي[a:4234[رًا‌ۖ و]َعُلِّمْت[w:4235[ُم م]َّا لَمْ تَعْلَم[o[ُوٓ][s[اْ] أَ[f:428[نت]ُمْ وَل[o[َآ] ءَاب[o[َا]ٓؤُكُمْ‌ۖ قُلِ [h:3166[ٱ]للَّهُ‌ۖ ثُ[g[مّ]َ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَب[p[ُو]نَ","Улар, Аллоҳ башарга ҳеч нарса туширгани йўқ, деганларида, Аллоҳни тўғри тақдирламадилар. Сен: «Мусо кишиларга ҳидоят ва нур этиб олиб келган, уни сиз қоғозга тушириб олиб, баъзисини зоҳир, кўпини махфий қилган; ва сиз ҳам, ота-боболарингиз ҳам билмаган нарсаларни сизга ўргатган китобни ким туширди?!» деб айт. «Аллоҳ» деб айт. Сўнгра уларни тек қўй, шунғиган нарсаларида ўйнайверсинлар.",139,7],["وَهَ[n[ـٰ]ذَا كِتَ[n[ـٰ]بٌ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ مُبَارَ[a:4237[كٌ م]ُّصَدِّقُ [h:4238[ٱ]لَّذِى بَيْنَ يَدَيْهِ وَلِتُ[f:4239[نذ]ِرَ أُ[g[مّ]َ [h:4240[ٱ]لْقُرَىٰ وَمَنْ حَوْلَهَا‌ۚ وَ[h:37[ٱ]لَّذِينَ يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ يُؤْمِنُونَ بِه[n[ِۦ]‌ۖ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظ[p[ُو]نَ","Бу, Биз туширган китоб муборакдир, ўзидан олдингини тасдиқловчидир. Уммул Қуро ва унинг атрофини огоҳлантиришинг учундир. Охиратга иймон келтирганлар унга иймон келтирарлар. Ва улар намозларини муҳофаза қиларлар.",139,7],["وَمَنْ أَظْلَمُ مِ[g[مّ]َنِ [h:3980[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ ش[a:4241[َىْءٌ و]َمَ[f:4242[ن ق]َالَ سَأُ[f:4243[نز]ِلُ مِثْلَ م[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ‌ۗ وَلَوْ تَرَ[o[ىٰٓ] إِذِ [h:4244[ٱ][l[ل]ظَّ[n[ـٰ]لِمُونَ فِى غَمَر[n[َٲ]تِ [h:4245[ٱ]لْمَوْتِ وَ[h:1146[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ بَاسِط[o[ُوٓ][s[اْ] أَيْدِيهِمْ أَخْرِج[o[ُوٓ][s[اْ] أَ[f:4246[نف]ُسَكُمُ‌ۖ [h:4247[ٱ]لْيَوْمَ تُ[q:4248[جْ]زَوْنَ عَذَابَ [h:4249[ٱ]لْهُونِ بِمَا كُ[f:100[نت]ُمْ تَقُولُونَ عَلَى [h:412[ٱ]للَّهِ غَيْرَ [h:2342[ٱ]لْحَقِّ وَكُ[f:151[نت]ُمْ عَنْ ءَايَ[n[ـٰ]تِه[n[ِۦ] تَسْتَكْبِر[p[ُو]نَ","Аллоҳга нисбатан ёлғон тўқиган ёки унга ҳеч нарса ваҳий қилинмаса ҳам, менга ваҳий келди, деган ёхуд, Аллоҳ нозил қилган нарсага ўхшаш нарсани мен ҳам нозил қиламан, деган кимсадан ҳам золимроқ кимса борми? Золимларнинг ўлим талвасаси пайтларини, фаришталарнинг уларга қўл чўзиб: «Жонингизни чиқаринг! Бугунги кунда Аллоҳга нисбатан ноҳақ гап айтганларингиз учун ва Унинг оятларидан мутакаббирлик қилиб юрганингиз учун хорлик азоби ила жазоланурсиз», дегандаги ҳолларини кўрсанг эди.",139,7],["وَلَقَ[q:341[دْ] جِئْتُمُونَا فُر[n[َٲ]دَىٰ كَمَا خَلَ[q:4250[قْ]نَ[n[ـٰ]كُمْ أَوَّلَ مَرَّ[a:4251[ةٍ و]َتَرَكْت[w:4252[ُم م]َّا خَوَّلْنَ[n[ـٰ]كُمْ وَر[o[َا]ٓءَ ظُهُورِكُمْ‌ۖ وَمَا نَرَىٰ مَعَكُمْ شُفَع[o[َا]ٓءَكُمُ [h:4253[ٱ]لَّذِينَ زَعَمْتُمْ أَ[g[نّ]َهُمْ فِيكُمْ شُرَكَ[o[ـٰٓ]ؤُ[s[اْ]‌ۚ لَقَ[d:4254[د] تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَ[f:255[نك][w:4255[ُم م]َّا كُ[f:100[نت]ُمْ تَزْعُم[p[ُو]نَ","Худди сизларни дастлаб халқ қилганимиздек, ҳузуримизга якка-якка келдингиз. Сизларга берган нарсаларимизни ортингизда қолдирдингиз. Сизлар ўзингизча шерик деб ўйлаган шафоатчиларингизни кўрмаяпмиз?! Батаҳқиқ, ораларингиз узилди. Сиз даъво қилган нарса ғойиб бўлди.",139,7],["۞ إِ[g[نّ]َ [h:80[ٱ]للَّهَ فَالِقُ [h:4256[ٱ]لْحَبِّ وَ[h:4257[ٱ][l[ل][g[نّ]َوَىٰ‌ۖ يُخْرِجُ [h:4258[ٱ]لْحَىَّ مِنَ [h:1833[ٱ]لْمَيِّتِ وَمُخْرِجُ [h:4259[ٱ]لْمَيِّتِ مِنَ [h:1835[ٱ]لْحَىِّ‌ۚ ذ[n[َٲ]لِكُمُ [h:4260[ٱ]للَّهُ‌ۖ فَأَ[g[نّ]َىٰ تُؤْفَك[p[ُو]نَ","Албатта, Аллоҳ донни ҳам, данакни ҳам ёрувчи зотдир. У ўликдан тирикни чиқарадир ва тирикдан ўликни чиқаргувчидир. Ана шундай Аллоҳдир. Сиз қаёққа бурилиб кетяпсиз?!",140,7],["فَالِقُ [h:4261[ٱ]لْإِصْبَاحِ وَجَعَلَ [h:4262[ٱ]لَّيْلَ سَكَ[a:4263[نًا و]َ[h:4264[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ حُسْبَا[f:4266[نًا‌ۚ ذ][n[َٲ]لِكَ تَ[q:4267[قْ]دِيرُ [h:4268[ٱ]لْعَزِيزِ [h:4269[ٱ]لْعَل[p[ِي]مِ","У субҳни ёритгувчи зотдир. У тунни сукунат, қуёш ва ойни ҳисоб қилиб қўйди. Бу эса, ғолиб ва яхши билгувчи зотнинг ўлчовидир.",140,7],["وَهُوَ [h:4114[ٱ]لَّذِى جَعَلَ لَكُمُ [h:4270[ٱ][l[ل][g[نّ]ُجُومَ لِتَهْتَدُو[s[اْ] بِهَا فِى ظُلُمَ[n[ـٰ]تِ [h:4129[ٱ]لْبَرِّ وَ[h:4107[ٱ]لْبَحْرِ‌ۗ قَ[q:298[دْ] فَصَّلْنَا [h:4271[ٱ]لْأَيَ[n[ـٰ]تِ لِقَوْ[a:1292[مٍ ي]َعْلَم[p[ُو]نَ","У сизларга қуруқлик ва денгиз зулматларида йўл топишингиз учун юлдузларни қилиб қўйган зотдир. Биладиган қавмлар учун оят-белгиларни батафсил қилиб қўйганмиз.",140,7],["وَهُوَ [h:4114[ٱ]لَّذ[o[ِىٓ] أَ[f:4272[نش]َأَك[w:4273[ُم م]ّ[a:2531[ِن ن]َّفْ[a:2532[سٍ و][n[َٲ]حِدَ[f:4274[ةٍ ف]َمُسْتَقَ[a:4275[رٌّ و]َمُسْتَوْدَ[f:4276[عٌ‌ۗ ق]َ[q:298[دْ] فَصَّلْنَا [h:4271[ٱ]لْأَيَ[n[ـٰ]تِ لِقَوْ[a:4277[مٍ ي]َفْقَه[p[ُو]نَ","У сизларни бир жондан яратган Зотдир. Бас, қарор топадиган жойда ёки сақлаб қўйиладиган жой дадир. Яхши англайдиганлар учун оят-белгиларни батафсил қилиб қўйганмиз.",140,7],["وَهُوَ [h:4114[ٱ]لَّذ[o[ِىٓ] أَ[f:471[نز]َلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:4278[ءً ف]َأَخْرَ[q:4279[جْ]نَا بِه[n[ِۦ] نَبَاتَ كُلِّ ش[f:4280[َىْءٍ ف]َأَخْرَ[q:4279[جْ]نَا مِنْهُ خَضِ[a:4281[رًا ن]ُّخْرِجُ مِنْهُ حَب[a:4282[ًّا م]ُّتَرَاكِ[a:4283[بًا و]َمِنَ [h:4284[ٱ][l[ل][g[نّ]َخْلِ مِ[f:4285[ن ط]َلْعِهَا قِنْوَا[f:4286[نٌ د]َانِيَ[a:4287[ةٌ و]َجَ[g[نّ]َ[n[ـٰ][a:4288[تٍ م]ِّنْ أَعْنَا[a:4289[بٍ و]َ[h:4290[ٱ][l[ل]زَّيْتُونَ وَ[h:4291[ٱ][l[ل]رُّ[g[مّ]َانَ مُشْتَبِ[a:4292[هًا و]َغَيْرَ مُتَشَ[n[ـٰ]بِهٍ‌ۗ [h:4293[ٱ][f:3950[نظ]ُر[o[ُوٓ][s[اْ] إِلَىٰ ثَمَرِه[o[ِۦٓ] إِذ[o[َآ] أَثْمَرَ وَيَنْعِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َ فِى ذ[n[َٲ]لِكُمْ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","У осмондан сув нозил қилган Зотдир. Бас, у ила турли набототлар чиқардик: Ундан яшил гиёҳларни чиқардик. Ундан ғужум-ғужум бошоқлар чиқарамиз. Ва хурмодан, унинг новдаларидан яқин шингиллар чиқарамиз ва узум боғлари чиқарамиз. Бир-бирига ўхшаган ва ўхшамаган зайтун ва анорларни чиқарамиз. Унинг мева қилиш пайтидаги мевасига ва пишишига назар солинг. Албатта, бундай нарсаларда иймон келтирадиган қавм учун оят-белгилар бордир.",140,7],["وَجَعَلُو[s[اْ] لِلَّهِ شُرَك[o[َا]ٓءَ [h:4295[ٱ]لْجِ[g[نّ]َ وَخَلَقَهُمْ‌ۖ وَخَرَقُو[s[اْ] لَهُ[n[ۥ] بَنِينَ وَبَنَ[n[ـٰ][i:4296[تِۭ ب]ِغَيْرِ عِلْ[f:4297[مٍ‌ۚ س]ُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ] وَتَعَ[n[ـٰ]لَىٰ عَ[g[مّ]َا يَصِف[p[ُو]نَ","Улар жинларни Аллоҳга шерик қилдилар. Ҳолбуки, у ҳаммаларини яратган зотдир. Илмсиз ҳолда унга ўғиллар ва қизлар ясадилар. У улар васф қилган нарсалардан пок ва олий бўлди.",140,7],["بَدِيعُ [h:611[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ أَ[g[نّ]َىٰ يَكُونُ لَهُ[n[ۥ] وَلَ[a:1924[دٌ و]َلَمْ تَك[u:4298[ُن ل]َّهُ[n[ۥ] صَ[n[ـٰ]حِبَ[a:4299[ةٌ‌ۖ و]َخَلَقَ كُلَّ ش[a:4300[َىْءٍ‌ۖ و]َهُوَ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","У осмонлару ерни йўқдан бор қилгувчи Зотдир. Унинг хотини бўлмай туриб, боласи қандай бўлсин?! У ҳамма нарсани Ўзи яратди ва У ҳамма нарсани яхши билгувчидир.",140,7],["ذ[n[َٲ]لِكُمُ [h:4260[ٱ]للَّهُ رَبُّكُمْ‌ۖ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۖ خَ[n[ـٰ]لِقُ كُلِّ ش[f:4301[َىْءٍ ف]َ[h:1946[ٱ]عْبُدُوهُ‌ۚ وَهُوَ عَلَىٰ كُلِّ ش[a:4302[َىْءٍ و]َك[p[ِي]لٌ","Ана ўша Аллоҳ сизнинг Роббингиздир. Ундан бошқа ибодатга сазовор зот йўқ. У ҳар бир нарсанинг Яратгувчисидир. Бас, Унга ибодат қилинг. У ҳар бир нарсага вакилдир!",141,7],["لَّا تُ[q:4303[دْ]رِكُهُ [h:4304[ٱ]لْأَ[q:4305[بْ]صَ[n[ـٰ]رُ وَهُوَ يُ[q:4306[دْ]رِكُ [h:4307[ٱ]لْأَ[q:4308[بْ]صَ[n[ـٰ]رَ‌ۖ وَهُوَ [h:4309[ٱ][l[ل]لَّطِيفُ [h:4310[ٱ]لْخَب[p[ِي]رُ","Кўзлар Уни идрок эта олмас, У кўзларни идрок этар. У латиф ва хабардор зотдир.",141,7],["قَ[q:298[دْ] ج[o[َا]ٓءَك[c:4311[ُم ب]َص[o[َا]ٓئِرُ م[u:243[ِن ر]َّبِّكُمْ‌ۖ فَمَنْ أَ[q:4312[بْ]صَرَ فَلِنَفْسِه[n[ِۦ]‌ۖ وَمَنْ عَمِىَ فَعَلَيْهَا‌ۚ وَم[o[َآ] أَنَا۟ عَلَيْك[c:4313[ُم ب]ِحَف[p[ِي]ظٍ","Сизга Роббингиздан «кўз очувчи»лар келди. Кимки кўрса, ўзига яхши. Ким кўр бўлиб олса, ўзига зарар. Мен сизларга қўриқчи эмасман.",141,7],["وَكَذ[n[َٲ]لِكَ نُصَرِّفُ [h:4060[ٱ]لْأَيَ[n[ـٰ]تِ وَلِيَقُولُو[s[اْ] دَرَسْتَ وَلِنُبَيِّنَهُ[n[ۥ] لِقَوْ[a:1292[مٍ ي]َعْلَم[p[ُو]نَ","Шундай қилиб, дарс олгансан, дейишлари учун ва билган қавмларга баён қилишинг учун оятларни тасарруф қилурмиз.",141,7],["ٱتَّبِعْ م[o[َآ] أُوحِىَ إِلَيْكَ م[u:770[ِن ر]َّبِّكَ‌ۖ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۖ وَأَعْرِضْ عَنِ [h:4314[ٱ]لْمُشْرِك[p[ِي]نَ","Сенга Роббингдан ваҳий қилинган нарсага эргаш. Ундан бошқа ибодатга сазовор зот йўқ. Мушриклардан юз ўгир.",141,7],["وَلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ م[o[َآ] أَشْرَكُو[s[اْ‌ۗ] وَمَا جَعَلْنَ[n[ـٰ]كَ عَلَيْهِمْ حَفِي[a:4315[ظًا‌ۖ و]َم[o[َآ] أَ[f:169[نت]َ عَلَيْه[c:4316[ِم ب]ِوَك[p[ِي]لٍ","Агар Аллоҳ хоҳласа, ширк келтирмас эдилар. Биз сени уларга қўриқчи қилганимиз йўқ. Ва сен уларга вакил ҳам эмассан.",141,7],["وَلَا تَسُبُّو[s[اْ] [h:4317[ٱ]لَّذِينَ يَ[q:1240[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ فَيَسُبُّو[s[اْ] [h:4318[ٱ]للَّهَ عَ[q:4319[دْ]و[i:4320[َۢا ب]ِغَيْرِ عِلْ[f:4321[مٍ‌ۗ ك]َذ[n[َٲ]لِكَ زَيَّ[g[نّ]َا لِكُلِّ أُ[g[مّ]َةٍ عَمَلَهُمْ ثُ[g[مّ]َ إِلَىٰ رَبِّه[w:4322[ِم م]َّرْجِعُهُمْ فَيُنَبِّئُه[c:4323[ُم ب]ِمَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Уларнинг Аллоҳдан ўзга ибодат қиладиганларини сўкмангиз. Бас, билмасдан, зулм ила Аллоҳни сўкиб юрмасинлар. Шундай қилиб, ҳар бир умматга амалини зийнатлаб қўйдик. Сўнгра эса, қайтиб борадиган жойлари Роббиларигадир. Бас, у қилиб юрган ишларининг хабарини берур.",141,7],["وَأَ[q:4324[قْ]سَمُو[s[اْ] بِ[h:32[ٱ]للَّهِ جَهْدَ أَيْمَ[n[ـٰ]نِهِمْ لَئِ[f:4325[ن ج][o[َا]ٓءَتْهُمْ ءَايَ[u:4326[ةٌ ل]َّيُؤْمِنُ[g[نّ]َ بِهَا‌ۚ قُلْ إِ[g[نّ]َمَا [h:4327[ٱ]لْأَيَ[n[ـٰ]تُ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۖ وَمَا يُشْعِرُكُمْ أَ[g[نّ]َه[o[َآ] إِذَا ج[o[َا]ٓءَتْ لَا يُؤْمِن[p[ُو]نَ","Улар агар бирон оят-мўъжиза келса, албатта иймон келтиришлари ҳақида Аллоҳнинг номи билан жон-жаҳдлари ила қасам ичадилар. Сен: «Албатта, оятлар фақат Аллоҳнинг ҳузурида», деб айт. Сизга нима билдирди? Эҳтимол оят келса ҳам, улар иймон келтирмаслар.",141,7],["وَنُقَلِّبُ أَفْــِٔدَتَهُمْ وَأَ[q:4328[بْ]صَ[n[ـٰ]رَهُمْ كَمَا لَمْ يُؤْمِنُو[s[اْ] بِه[o[ِۦٓ] أَوَّلَ مَرَّ[a:4329[ةٍ و]َنَذَرُهُمْ فِى طُغْيَ[n[ـٰ]نِهِمْ يَعْمَه[p[ُو]نَ","Худди аввал иймон келтирмаганларидек, қалблари ва кўзларини буриб қўярмиз ва туғёнларида довдираган ҳолларида тек қўярмиз.",141,7],["۞ وَلَوْ أَ[g[نّ]َنَا نَزَّلْن[o[َآ] إِلَيْهِمُ [h:4330[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةَ وَكَلَّمَهُمُ [h:4331[ٱ]لْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ ش[f:4332[َىْءٍ ق]ُبُل[a:4333[اً م]َّا كَانُو[s[اْ] لِيُؤْمِن[o[ُوٓ][s[اْ] إِلّ[o[َآ] أ[a:4201[َن ي]َش[o[َا]ٓءَ [h:4334[ٱ]للَّهُ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ يَ[q:4335[جْ]هَل[p[ُو]نَ","Агар Биз уларга фаришталарни туширсак ҳам, уларга ўликлар гапирса ҳам ва уларнинг олдига ҳамма нарсани очиқ-ойдин тўпласак ҳам, Аллоҳ хоҳламаса, иймон келтирмаслар. Лекин кўплари жоҳилдирлар.",142,8],["وَكَذ[n[َٲ]لِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُو[f:4336[ًّا ش]َيَ[n[ـٰ]طِينَ [h:4337[ٱ]لْإِ[f:4338[نس]ِ وَ[h:4339[ٱ]لْجِ[g[نّ]ِ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْ[f:4340[ضٍ ز]ُخْرُفَ [h:4341[ٱ]لْقَوْلِ غُرُو[a:4342[رًا‌ۚ و]َلَوْ ش[o[َا]ٓءَ رَبُّكَ مَا فَعَلُوهُ‌ۖ فَذَرْهُمْ وَمَا يَفْتَر[p[ُو]نَ","Шунингдек, ҳар бир Пайғамбарга инсу жин шайтонларини душман қилиб қўйдик. Уларнинг баъзилари баъзиларини ғурурга кетказишлари учун латиф каломларни танларлар. Агар Роббинг хоҳласа, бундай қилмас эдилар. Бас, уларни ўзлари тўқиган нарсалари ила ёлғиз қўй!",142,8],["وَلِتَصْغَ[o[ىٰٓ] إِلَيْهِ أَفْــِٔدَةُ [h:4343[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ وَلِيَرْضَوْهُ وَلِيَ[q:4344[قْ]تَرِفُو[s[اْ] مَا ه[w:4345[ُم م]ُّ[q:4346[قْ]تَرِف[p[ُو]نَ","Унга охиратга иймон келтирмайдиганларнинг қалби мойил бўлиши, ундан рози бўлиб, қиладиган гуноҳларини бажаришлари учундир.",142,8],["أَفَغَيْرَ [h:4347[ٱ]للَّهِ أَ[q:4348[بْ]تَغِى حَكَ[a:4349[مًا و]َهُوَ [h:4114[ٱ]لَّذ[o[ِىٓ] أَ[f:471[نز]َلَ إِلَيْكُمُ [h:4350[ٱ]لْكِتَ[n[ـٰ]بَ مُفَصَّل[a:4351[اً‌ۚ و]َ[h:37[ٱ]لَّذِينَ ءَاتَيْنَ[n[ـٰ]هُمُ [h:635[ٱ]لْكِتَ[n[ـٰ]بَ يَعْلَمُونَ أَ[g[نّ]َهُ[n[ۥ] مُنَزَّ[a:4352[لٌ م]ّ[u:770[ِن ر]َّبِّكَ بِ[h:370[ٱ]لْحَقِّ‌ۖ فَلَا تَكُونَ[g[نّ]َ مِنَ [h:771[ٱ]لْمُمْتَر[p[ِي]نَ","Аллоҳдан ўзгани ҳакам қилиб олайми? Ҳолбуки, У сизга китобни батафсил этиб нозил қилди. Биз уларга китоб берганлар уни Роббингдан ҳақ ила нозил қилинганини биладилар. Бас шак келтирувчилардан бўлма.",142,8],["وَتَ[g[مّ]َتْ كَلِمَتُ رَبِّكَ صِ[q:4353[دْ][a:4354[قًا و]َعَ[q:4355[دْ]ل[u:4356[اً‌ۚ ل]َّا مُبَدِّلَ لِكَلِمَ[n[ـٰ]تِه[n[ِۦ]‌ۚ وَهُوَ [h:709[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Роббингнинг сўзлари содиқлик ва адолат ила батамом бўлди. Унинг сўзларини ўзгартувчи йўқ. Ва У яхши эшитгувчи ва яхши билгувчи зотдир.",142,8],["وَإِ[f:4357[ن ت]ُطِعْ أَكْثَرَ مَ[f:2074[ن ف]ِى [h:44[ٱ]لْأَرْضِ يُضِلُّوكَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ‌ۚ إ[a:4358[ِن ي]َتَّبِعُونَ إِلَّا [h:4359[ٱ][l[ل]ظَّ[g[نّ]َ وَإِنْ هُمْ إِلَّا يَخْرُص[p[ُو]نَ","Ва агар ер юзидагиларнинг кўпларига итоат қилсанг, сени Аллоҳнинг йўлидан адаштирадилар. Улар гумондан бошқага эргашмаслар. Улар тахмин қиларлар, холос.",142,8],["إِ[g[نّ]َ رَبَّكَ هُوَ أَعْلَمُ م[a:4360[َن ي]َضِلُّ عَ[f:4361[ن س]َبِيلِه[n[ِۦ]‌ۖ وَهُوَ أَعْلَمُ بِ[h:4362[ٱ]لْمُهْتَد[p[ِي]نَ","Албатта, Роббинг ким Унинг йўлидан адашишини яхши билгувчидир. Ва У ҳидоят топувчиларни ҳам яхши билгувчидир.",142,8],["فَكُلُو[s[اْ] مِ[g[مّ]َا ذُكِرَ [h:4363[ٱ]سْمُ [h:4364[ٱ]للَّهِ عَلَيْهِ إِ[f:109[ن ك]ُ[f:100[نت][c:4365[ُم ب]ِـَٔـايَ[n[ـٰ]تِه[n[ِۦ] مُؤْمِن[p[ِي]نَ","Агар Унинг оятларига иймон келтиргувчилардан бўлсангиз, Аллоҳнинг исми зикр қилинган нарсадан енг!",142,8],["وَمَا لَكُمْ أَلَّا تَأْكُلُو[s[اْ] مِ[g[مّ]َا ذُكِرَ [h:4363[ٱ]سْمُ [h:4364[ٱ]للَّهِ عَلَيْهِ وَقَ[q:387[دْ] فَصَّلَ لَك[w:154[ُم م]َّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا [h:4366[ٱ]ضْطُرِرْتُمْ إِلَيْهِ‌ۗ وَإِ[g[نّ]َ كَثِي[u:4367[رًا ل]َّيُضِلُّونَ بِأَهْو[o[َا]ٓئِه[c:4368[ِم ب]ِغَيْرِ عِلْمٍ‌ۗ إِ[g[نّ]َ رَبَّكَ هُوَ أَعْلَمُ بِ[h:4369[ٱ]لْمُعْتَد[p[ِي]نَ","Сизга нима бўлдики, Аллоҳнинг номи айтиб сўйилган нарсани емас экансизлар?! У сизларга ҳаром қилган нарсаларини батафсил баён қилиб берган-ку?! Магар музтар бўлганингизда, майли. Албатта, кўпчилик билмасдан, ҳойу ҳаваслари ила адаштирадилар. Албатта, Роббинг тажовузкорларни яхши билгувчидир.",143,8],["وَذَرُو[s[اْ] ظَ[n[ـٰ]هِرَ [h:4370[ٱ]لْإِثْمِ وَبَاطِنَهُ[o[ۥٓ‌ۚ] إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَكْسِبُونَ [h:4371[ٱ]لْإِثْمَ سَيُ[q:4372[جْ]زَوْنَ بِمَا كَانُو[s[اْ] يَ[q:4373[قْ]تَرِف[p[ُو]نَ","Ва ошкора ҳамда махфий гуноҳларни тарк қилинглар! Гуноҳ қилувчилар, албатта, қилган гуноҳларининг жазосини олурлар.",143,8],["وَلَا تَأْكُلُو[s[اْ] مِ[g[مّ]َا لَمْ يُذْكَرِ [h:4374[ٱ]سْمُ [h:4364[ٱ]للَّهِ عَلَيْهِ وَإِ[g[نّ]َهُ[n[ۥ] لَفِسْ[a:4375[قٌ‌ۗ و]َإِ[g[نّ]َ [h:4376[ٱ][l[ل]شَّيَ[n[ـٰ]طِينَ لَيُوحُونَ إِلَ[o[ىٰٓ] أَوْلِي[o[َا]ٓئِهِمْ لِيُجَ[n[ـٰ]دِلُوكُمْ‌ۖ وَإِنْ أَطَعْتُمُوهُمْ إِ[g[نّ]َكُمْ لَمُشْرِك[p[ُو]نَ","Аллоҳнинг исми зикр қилинмаган нарсаларни еманглар. Албатта, бу иш фисқдир. Албатта, шайтонлар ўз дўстларига сизлар билан тортишишни васваса қиларлар. Агар уларга итоат қилсангизлар, сизлар ҳам мушриклардан бўласизлар.",143,8],["أَوَمَ[f:4377[ن ك]َانَ مَيْ[f:4378[تًا ف]َأَحْيَيْنَ[n[ـٰ]هُ وَجَعَلْنَا لَهُ[n[ۥ] نُو[a:4379[رًا ي]َمْشِى بِه[n[ِۦ] فِى [h:4380[ٱ][l[ل][g[نّ]َاسِ كَم[a:4381[َن م]َّثَلُهُ[n[ۥ] فِى [h:4033[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ لَيْسَ بِخَارِ[a:4382[جٍ م]ِّنْهَا‌ۚ كَذ[n[َٲ]لِكَ زُيِّنَ لِلْكَ[n[ـٰ]فِرِينَ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Аввал ўлик бўлган одамни тирилтириб, унга одамлар орасида юрадиган нурни бериб қўйган бўлсак, у билан зулматлар ичида ундан чиқа олмай юрувчи одам ўхшаш бўладими? Шундай қилиб, кофирларга қилаётган амаллари зийнатлаб кўрсатилди.",143,8],["وَكَذ[n[َٲ]لِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَ[n[ـٰ]بِرَ مُ[q:4383[جْ]رِمِيهَا لِيَمْكُرُو[s[اْ] فِيهَا‌ۖ وَمَا يَمْكُرُونَ إِلَّا بِأَ[f:4384[نف]ُسِهِمْ وَمَا يَشْعُر[p[ُو]نَ","Худди шунга ўхшаш ҳар бир шаҳарда катта жиноятчиларни унда макр қилиш учун қўйиб юбордик. Улар сезмаган ҳолда фақат ўзларига ўзлари макр қиладилар, холос.",143,8],["وَإِذَا ج[o[َا]ٓءَتْهُمْ ءَايَ[f:4385[ةٌ ق]َالُو[s[اْ] ل[a:265[َن ن]ُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ م[o[َآ] أُوتِىَ رُسُلُ [h:4386[ٱ]للَّهِ‌ۘ [h:4387[ٱ]للَّهُ أَعْلَمُ حَيْثُ يَ[q:4388[جْ]عَلُ رِسَالَتَهُ[n[ۥ]‌ۗ سَيُصِيبُ [h:4389[ٱ]لَّذِينَ أَ[q:4390[جْ]رَمُو[s[اْ] صَغَارٌ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَعَذَا[f:4391[بٌ ش]َدِي[i:4392[دُۢ ب]ِمَا كَانُو[s[اْ] يَمْكُر[p[ُو]نَ","Агар уларга оят келса, Аллоҳнинг Пайғамбарларига берилган нарсага ўхшаш нарса бизга ҳам берилмагунча зинҳор иймон келтирмасмиз, дерлар. Ўз Пайғамбарлигини қаерга қўйишни Аллоҳнинг Ўзи яхши биладир. Жиноят қилганларга қилган макрлари учун Аллоҳнинг ҳузурида, албатта, хорлик ва шиддатли азоб бордир.",143,8],["فَم[a:4393[َن ي]ُرِدِ [h:3545[ٱ]للَّهُ أ[a:4394[َن ي]َهْدِيَهُ[n[ۥ] يَشْرَحْ صَ[q:4395[دْ]رَهُ[n[ۥ] لِلْإِسْلَ[n[ـٰ]مِ‌ۖ وَم[a:2292[َن ي]ُرِ[q:2293[دْ] أ[a:4396[َن ي]ُضِلَّهُ[n[ۥ] يَ[q:4397[جْ]عَلْ صَ[q:4395[دْ]رَهُ[n[ۥ] ضَيِّقًا حَرَ[f:4398[جًا ك]َأَ[g[نّ]َمَا يَصَّعَّدُ فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ‌ۚ كَذ[n[َٲ]لِكَ يَ[q:4388[جْ]عَلُ [h:4399[ٱ]للَّهُ [h:4400[ٱ][l[ل]رِّ[q:4401[جْ]سَ عَلَى [h:289[ٱ]لَّذِينَ لَا يُؤْمِن[p[ُو]نَ","Кимни Аллоҳ ҳидоят қилмоқчи бўлса, унинг кўксини Исломга очиб қўядир. Кимни залолатга кетказишни ирода қилса, унинг кўксини худди осмонга кўтарилаётгандек, тор ва танг қилиб қўядир. Шундай қилиб, Аллоҳ иймон келтирмайдиганларга азобни дучор қилур.",144,8],["وَهَ[n[ـٰ]ذَا صِر[n[َٲ]طُ رَبِّكَ مُسْتَقِي[f:4402[مًا‌ۗ ق]َ[q:298[دْ] فَصَّلْنَا [h:4271[ٱ]لْأَيَ[n[ـٰ]تِ لِقَوْ[a:4403[مٍ ي]َذَّكَّر[p[ُو]نَ","Мана шу Роббингнинг тўғри йўлидир. Ибрат олувчи қавм учун оятларни батафсил баён қилдик.",144,8],["۞ لَهُمْ دَارُ [h:4404[ٱ][l[ل]سَّلَ[n[ـٰ]مِ عِ[f:264[ند]َ رَبِّهِمْ‌ۖ وَهُوَ وَلِيُّه[c:4405[ُم ب]ِمَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Уларга Роббилари ҳузурида дорус-Салом бордир. У зот қилган ишлари учун уларнинг дўстидир.",144,8],["وَيَوْمَ يَحْشُرُهُمْ جَمِي[a:4406[عًا ي]َ[n[ـٰ]مَعْشَرَ [h:4407[ٱ]لْجِ[g[نّ]ِ قَدِ [h:4408[ٱ]سْتَكْثَرْت[w:4409[ُم م]ِّنَ [h:4410[ٱ]لْإِ[f:4338[نس]ِ‌ۖ وَقَالَ أَوْلِي[o[َا]ٓؤُه[w:4411[ُم م]ِّنَ [h:4410[ٱ]لْإِ[f:4338[نس]ِ رَبَّنَا [h:4412[ٱ]سْتَمْتَعَ بَعْضُنَا بِبَعْ[a:4413[ضٍ و]َبَلَغْن[o[َآ] أَجَلَنَا [h:4414[ٱ]لَّذ[o[ِىٓ] أَجَّلْتَ لَنَا‌ۚ قَالَ [h:4415[ٱ][l[ل][g[نّ]َارُ مَثْوَ[n[ٮٰ]كُمْ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] إِلَّا مَا ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ‌ۗ إِ[g[نّ]َ رَبَّكَ حَكِيمٌ عَل[p[ِي]مٌ","Уларнинг ҳаммасини тўплайдиган кунда: «Эй жинлар жамоаси, инсдан кўпайтирвордингиз?!» дейди. Уларнинг инсдан бўлган дўстлари: «Эй Роббимиз, биз бир-биримиздан ҳузур топдик ва бизга белгилаган ажалингга етиб келдик», дейдилар. У зот: «Қайтар жойингиз дўзахдир. Магар Аллоҳ хоҳласа. Албатта, Роббинг ҳикматли ва билимли зотдир.",144,8],["وَكَذ[n[َٲ]لِكَ نُوَلِّى بَعْضَ [h:4416[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ بَعْض[i:4417[َۢا ب]ِمَا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Шундай қилиб, қилган касбларига биноан золимларни бир-бирларига дўст қилурмиз.",144,8],["يَ[n[ـٰ]مَعْشَرَ [h:4407[ٱ]لْجِ[g[نّ]ِ وَ[h:4418[ٱ]لْإِ[f:4418[نس]ِ أَلَمْ يَأْتِكُمْ رُسُ[a:4419[لٌ م]ِّ[f:344[نك]ُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَ[n[ـٰ]تِى وَيُ[f:4420[نذ]ِرُونَكُمْ لِق[o[َا]ٓءَ يَوْمِكُمْ هَ[n[ـٰ]ذَا‌ۚ قَالُو[s[اْ] شَهِ[q:4421[دْ]نَا عَلَ[o[ىٰٓ] أَ[f:4422[نف]ُسِنَا‌ۖ وَغَرَّتْهُمُ [h:4161[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَا وَشَهِدُو[s[اْ] عَلَ[o[ىٰٓ] أَ[f:568[نف]ُسِهِمْ أَ[g[نّ]َهُمْ كَانُو[s[اْ] كَ[n[ـٰ]فِر[p[ِي]نَ","Эй жин ва инс жамоалари, сизларга ўзингиздан бўлган Пайғамбарлар келиб, оятларимни сизга айтиб бермадиларми, сизларни ушбу кунингизга дучор бўлишингиз ҳақида огоҳлантирмадиларми?» дер. Улар: «Ўзимизга қарши гувоҳлик бердик», дерлар. Уларни ҳаёти дунё ғурурга кетказди ва ўзларига қарши кофир бўлганларини айтиб, гувоҳлик бердилар.",144,8],["ذ[n[َٲ]لِكَ أ[u:4423[َن ل]َّمْ يَك[u:4424[ُن ر]َّبُّكَ مُهْلِكَ [h:4425[ٱ]لْقُرَىٰ بِظُلْ[a:4426[مٍ و]َأَهْلُهَا غَ[n[ـٰ]فِل[p[ُو]نَ","Бундай қилишнинг боиси, Роббинг ғофил турган шаҳар-қишлоқ аҳолисини ҳалок қилмаслигидандир.",144,8],["وَلِكُ[f:4427[لٍّ د]َرَجَ[n[ـٰ][a:4428[تٌ م]ِّ[g[مّ]َا عَمِلُو[s[اْ‌ۚ] وَمَا رَبُّكَ بِغَ[n[ـٰ]فِلٍ عَ[g[مّ]َا يَعْمَل[p[ُو]نَ","Ҳар кимга қилганларига яраша даража бордир. Ва Роббинг уларнинг қилаётган амалларидан ғофил эмасдир.",145,8],["وَرَبُّكَ [h:4429[ٱ]لْغَنِىُّ ذُو [h:4430[ٱ][l[ل]رَّحْمَةِ‌ۚ إ[a:3197[ِن ي]َشَأْ يُذْهِ[q:3198[بْ]كُمْ وَيَسْتَخْلِفْ م[i:4431[ِنۢ ب]َعْدِك[w:4432[ُم م]َّا يَش[o[َا]ٓءُ كَم[o[َآ] أَ[f:4272[نش]َأَك[w:4273[ُم م]ِّ[f:4433[ن ذ]ُرِّيَّةِ قَوْمٍ ءَاخَر[p[ِي]نَ","Ва Роббинг беҳожат ва раҳмат соҳиби бўлган зотдир. Агар хоҳласа, худди сизларни бошқа қавмлар зурриётидан пайдо қилганидек, сизларни кетказиб, ортингиздан нимани хоҳласа, ўринбосар қилиб келтирадир.",145,8],["إِ[g[نّ]َ مَا تُوعَدُونَ لَأَ[a:4434[تٍ‌ۖ و]َم[o[َآ] أَ[f:428[نت][c:4435[ُم ب]ِمُعْجِز[p[ِي]نَ","Албатта, сизга ваъда қилинган нарса келувчидир. Сизлар эса У зотни ожиз қолдирувчи эмассиз.",145,8],["قُلْ يَ[n[ـٰ]قَوْمِ [h:4436[ٱ]عْمَلُو[s[اْ] عَلَىٰ مَكَانَتِكُمْ إِ[g[نّ]ِى عَامِ[f:4437[لٌ‌ۖ ف]َسَوْفَ تَعْلَمُونَ مَ[f:4438[ن ت]َكُونُ لَهُ[n[ۥ] عَ[n[ـٰ]قِبَةُ [h:4439[ٱ][l[ل]دَّارِ‌ۗ إِ[g[نّ]َهُ[n[ۥ] لَا يُفْلِحُ [h:3981[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Сен: «Эй қавмим, ўрнингизда амалингизни қилаверинг. Мен ҳам амал қилувчиман. Тезда охират ҳовлиси оқибати кимнинг фойдасига бўлишини биласиз. Албатта, золимлар нажот топмаслар», деб айт.",145,8],["وَجَعَلُو[s[اْ] لِلَّهِ مِ[g[مّ]َا ذَرَأَ مِنَ [h:4440[ٱ]لْحَرْثِ وَ[h:1778[ٱ]لْأَنْعَ[n[ـٰ]مِ نَصِي[f:4441[بًا ف]َقَالُو[s[اْ] هَ[n[ـٰ]ذَا لِلَّهِ بِزَعْمِهِمْ وَهَ[n[ـٰ]ذَا لِشُرَك[o[َا]ٓئِنَا‌ۖ فَمَا كَانَ لِشُرَك[o[َا]ٓئِهِمْ فَلَا يَصِلُ إِلَى [h:1637[ٱ]للَّهِ‌ۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَك[o[َا]ٓئِهِمْ‌ۗ س[o[َا]ٓءَ مَا يَحْكُم[p[ُو]نَ","Улар Аллоҳга Унинг Ўзи яратган экинлар ва чорвалардан насиба ажратдилар ва ўзларича: «Бу Аллоҳга, бу эса бутларимизга», дедилар. Бас, бутларига бўлган нарса Аллоҳга етмас. Аллоҳга бўлган нарса эса, бутларига етадир. Чиқарган ҳукмлари қандай ҳам ёмон-а?!",145,8],["وَكَذ[n[َٲ]لِكَ زَيَّنَ لِكَثِي[a:4442[رٍ م]ِّنَ [h:699[ٱ]لْمُشْرِكِينَ قَتْلَ أَوْلَ[n[ـٰ]دِهِمْ شُرَك[o[َا]ٓؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُو[s[اْ] عَلَيْهِمْ دِينَهُمْ‌ۖ وَلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ مَا فَعَلُوهُ‌ۖ فَذَرْهُمْ وَمَا يَفْتَر[p[ُو]نَ","Шунингдек, мушриклардан кўпларига шериклари уларни ҳалок этиш ва динларини чалкаштириш учун болаларини ўлдиришни зийнатлаб кўрсатди. Агар Аллоҳ хоҳласа, бундай қилмасдилар. Уларни ва тўқиётган нарсаларини қўйиб қўй.",145,8],["وَقَالُو[s[اْ] هَ[n[ـٰ]ذِه[o[ِۦٓ] أَنْعَ[n[ـٰ][a:4443[مٌ و]َحَرْثٌ حِ[q:4444[جْ][u:4445[رٌ ل]َّا يَ[q:4446[طْ]عَمُه[o[َآ] إِلَّا م[a:4211[َن ن]َّش[o[َا]ٓءُ بِزَعْمِهِمْ وَأَنْعَ[n[ـٰ]مٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَ[n[ـٰ][u:4447[مٌ ل]َّا يَذْكُرُونَ [h:4448[ٱ]سْمَ [h:3393[ٱ]للَّهِ عَلَيْهَا [h:4449[ٱ]فْتِر[o[َا]ٓءً عَلَيْهِ‌ۚ سَيَ[q:4450[جْ]زِيه[c:4451[ِم ب]ِمَا كَانُو[s[اْ] يَفْتَر[p[ُو]نَ","Улар ўзларича: «Мана бу чорва ва экинлар ҳаром, уларни фақат биз хоҳлаган кишиларгина ейрлар ва мана бу миниши ҳаром қилинган чорвалар», дедилар. Улар маълум чорваларга Аллоҳнинг номини зикр қилмаслар. Бу эса, у зотга туҳматдир. У тезда қилган туҳматлари туфайли уларга жазо беражак.",146,8],["وَقَالُو[s[اْ] مَا فِى بُطُونِ هَ[n[ـٰ]ذِهِ [h:4452[ٱ]لْأَنْعَ[n[ـٰ]مِ خَالِصَ[u:4453[ةٌ ل]ِّذُكُورِنَا وَمُحَرَّمٌ عَلَ[o[ىٰٓ] أَزْو[n[َٲ]جِنَا‌ۖ وَإ[a:4454[ِن ي]َك[a:4455[ُن م]َّيْتَ[f:4456[ةً ف]َهُمْ فِيهِ شُرَك[o[َا]ٓءُ‌ۚ سَيَ[q:4450[جْ]زِيهِمْ وَصْفَهُمْ‌ۚ إِ[g[نّ]َهُ[n[ۥ] حَكِيمٌ عَل[p[ِي]مٌ","Улар, мана шу чорваларнинг қорнидаги нарсалар эркакларимизга ҳалол, аёлларимизга ҳаром, дерлар. Агар у ўлик бўлса, улар унга шериклардир. Тезда уларга васфлари учун Ўзи жазо беражак. Албатта, У ҳикматли ва яхши билувчи зотдир.",146,8],["قَ[q:298[دْ] خَسِرَ [h:3997[ٱ]لَّذِينَ قَتَل[o[ُوٓ][s[اْ] أَوْلَ[n[ـٰ]دَهُمْ سَفَه[i:4457[َۢا ب]ِغَيْرِ عِلْ[a:4458[مٍ و]َحَرَّمُو[s[اْ] مَا رَزَقَهُمُ [h:2790[ٱ]للَّهُ [h:4459[ٱ]فْتِر[o[َا]ٓءً عَلَى [h:412[ٱ]للَّهِ‌ۚ قَ[q:298[دْ] ضَلُّو[s[اْ] وَمَا كَانُو[s[اْ] مُهْتَد[p[ِي]نَ","Ақли пастлик қилиб, жоҳиллик ила фарзандларини ўлдирганлар ва Аллоҳ уларга ризқ қилиб берган нарсаларни ҳаром қилганлар зиёнкор бўлдилар. Батаҳқиқ, улар адашдилар ва ҳидоятга юрувчилардан бўлмадилар.",146,8],["۞ وَهُوَ [h:4114[ٱ]لَّذ[o[ِىٓ] أَ[f:4460[نش]َأَ جَ[g[نّ]َ[n[ـٰ][a:4461[تٍ م]َّعْرُوشَ[n[ـٰ][a:4462[تٍ و]َغَيْرَ مَعْرُوشَ[n[ـٰ][a:4463[تٍ و]َ[h:4464[ٱ][l[ل][g[نّ]َخْلَ وَ[h:4465[ٱ][l[ل]زَّرْعَ مُخْتَلِفًا أُكُلُهُ[n[ۥ] وَ[h:4290[ٱ][l[ل]زَّيْتُونَ وَ[h:4291[ٱ][l[ل]رُّ[g[مّ]َانَ مُتَشَ[n[ـٰ]بِ[a:4466[هًا و]َغَيْرَ مُتَشَ[n[ـٰ]بِ[f:4467[هٍ‌ۚ ك]ُلُو[s[اْ] مِ[f:4468[ن ث]َمَرِه[o[ِۦٓ] إِذ[o[َآ] أَثْمَرَ وَءَاتُو[s[اْ] حَقَّهُ[n[ۥ] يَوْمَ حَصَادِه[n[ِۦ]‌ۖ وَلَا تُسْرِف[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َهُ[n[ۥ] لَا يُحِبُّ [h:4469[ٱ]لْمُسْرِف[p[ِي]نَ","У кўтариладиган ва кўтарилмайдиган боғларни, хурмо ва экинларни емагини хилма-хил қилиб, зайтун ва анорларни бир-бирига ўхшатиб ва ўхшатмай пайдо қилган зотдир. Мевалаган пайтида унинг мевасидан енглар ва йиғим-терим кунида ҳаққини беринглар. Ва исроф қилманглар. Албатта, У исроф қилгувчиларни севмас.",146,8],["وَمِنَ [h:4470[ٱ]لْأَنْعَ[n[ـٰ]مِ حَمُولَ[a:4471[ةً و]َفَرْ[f:4472[شًا‌ۚ ك]ُلُو[s[اْ] مِ[g[مّ]َا رَزَقَكُمُ [h:3751[ٱ]للَّهُ وَلَا تَتَّبِعُو[s[اْ] خُطُو[n[َٲ]تِ [h:872[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] لَكُمْ عَدُ[a:873[وٌّ م]ُّب[p[ِي]نٌ","Ва чорвалардан ҳаммолларини ва ерга ётқазиладиганларни пайдо қилди. Аллоҳ сизга ризқ қилиб берган нарсалардан енглар ва шайтоннинг изидан эргашманглар. Албатта, у сизларга очиқ-ойдин душмандир.",146,8],["ثَمَ[n[ـٰ]نِيَةَ أَزْو[n[َٲ][a:4473[جٍ‌ۖ م]ِّنَ [h:4474[ٱ][l[ل]ضَّأْنِ [h:4475[ٱ]ثْنَيْنِ وَمِنَ [h:4476[ٱ]لْمَعْزِ [h:4477[ٱ]ثْنَيْنِ‌ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ [h:4478[ٱ]لْأُ[f:2586[نث]َيَيْنِ أَ[g[مّ]َا [h:4479[ٱ]شْتَمَلَتْ عَلَيْهِ أَرْحَامُ [h:4480[ٱ]لْأُ[f:2586[نث]َيَيْنِ‌ۖ نَبِّــُٔونِى بِعِلْمٍ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Саккиз жуфт: қўйдан иккини ва эчкидан иккини. Сен: «Иккала эркагини ҳаром қилдими ёки иккала урғочисиними ёхуд иккала урғочининг бачадонларида шомил бўлган нарсаними?! Агар ростгўй бўлсангизлар, илмий қилиб хабарини беринглар-чи?» деб айт.",147,8],["وَمِنَ [h:4481[ٱ]لْإِبِلِ [h:4482[ٱ]ثْنَيْنِ وَمِنَ [h:4483[ٱ]لْبَقَرِ [h:4484[ٱ]ثْنَيْنِ‌ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ [h:4478[ٱ]لْأُ[f:2586[نث]َيَيْنِ أَ[g[مّ]َا [h:4479[ٱ]شْتَمَلَتْ عَلَيْهِ أَرْحَامُ [h:4480[ٱ]لْأُ[f:2586[نث]َيَيْنِ‌ۖ أَمْ كُ[f:100[نت]ُمْ شُهَد[o[َا]ٓءَ إِذْ وَصَّ[n[ـٰ]كُمُ [h:4485[ٱ]للَّهُ بِهَ[n[ـٰ]ذَا‌ۚ فَمَنْ أَظْلَمُ مِ[g[مّ]َنِ [h:3980[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِ[u:4486[بًا ل]ِّيُضِلَّ [h:4487[ٱ][l[ل][g[نّ]َاسَ بِغَيْرِ عِلْمٍ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Туядан иккитани, қорамолдан иккини. ен«Иккала эркагини ҳаром қилдими ёки иккала урғочисиними ёхуд иккала урғочининг бачадонларида шомил бўлган нарсаними?! Ёки Аллоҳ сизларга буни амр қилганда шоҳид бўлиб турганмидингиз? Илмсиз ҳолда одамларни адаштириш учун Аллоҳга нисбатан ёлғон тўқигандан ҳам золимроқ одам борми?! Албатта, Аллоҳ золим қавмларни ҳидоят қилмас».",147,8],["قُل لّ[o[َآ] أَجِدُ فِى م[o[َآ] أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِ[a:4488[مٍ ي]َ[q:4489[طْ]عَمُهُ[o[ۥٓ] إِلّ[o[َآ] أ[a:3312[َن ي]َكُونَ مَيْتَةً أَوْ دَ[a:4490[مًا م]َّسْفُوحًا أَوْ لَحْمَ خِ[f:4491[نز]ِي[f:4492[رٍ ف]َإِ[g[نّ]َهُ[n[ۥ] رِ[q:3765[جْ]سٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ [h:886[ٱ]للَّهِ بِه[n[ِۦ]‌ۚ فَمَنِ [h:887[ٱ]ضْطُرَّ غَيْرَ بَا[a:888[غٍ و]َلَا عَا[f:4493[دٍ ف]َإِ[g[نّ]َ رَبَّكَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Менга ваҳий қилинган нарсада таомланувчи учун ҳаром қилинган нарсани топмаяпман. Магар ўлимтик ёки оқизилган қон ёки тўнғиз гўшти бўлса, албатта, у ифлос, ҳаромдир. Ёҳуд фосиқлик ила Аллоҳдан ўзганинг номига сўйилган бўлса. Бас, киши музтар бўлиб, маза талаб қилувчи ва тажовузкор бўлмаган ҳолида. Албатта, Роббинг мағфират қилгувчи ва раҳмли зотдир», деб айт.",147,8],["وَعَلَى [h:958[ٱ]لَّذِينَ هَادُو[s[اْ] حَرَّمْنَا كُلَّ ذِى ظُفُ[a:4494[رٍ‌ۖ و]َمِنَ [h:4483[ٱ]لْبَقَرِ وَ[h:4495[ٱ]لْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُم[o[َآ] إِلَّا مَا حَمَلَتْ ظُهُورُهُم[o[َآ] أَوِ [h:4496[ٱ]لْحَوَاي[o[َآ] أَوْ مَا [h:4497[ٱ]خْتَلَطَ بِعَظْ[f:4498[مٍ‌ۚ ذ][n[َٲ]لِكَ جَزَيْنَ[n[ـٰ]ه[c:4499[ُم ب]ِبَغْيِهِمْ‌ۖ وَإِ[g[نّ]َا لَصَ[n[ـٰ]دِق[p[ُو]نَ","Ва яҳудий бўлганларга барча туёқлиларни ҳаром қилдик. Мол ва қўйдан эса, уларга ёғларини ҳаром қилдик. Магар орқа ва ичакларидаги ёки суякка аралашган ёғлари. Бу зулмлари учун уларга берган жазоимиздир. Албатта, Биз ростгўймиз.",147,8],["فَإِ[f:2473[ن ك]َذَّبُوكَ فَقُ[b:4500[ل] رَّبُّكُمْ ذُو رَحْمَ[a:4501[ةٍ و][n[َٲ]سِعَ[a:4502[ةٍ و]َلَا يُرَدُّ بَأْسُهُ[n[ۥ] عَنِ [h:4503[ٱ]لْقَوْمِ [h:4504[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","Агар сени ёлғончига чиқарсалар: «Роббингиз кенг раҳмат соҳибидир, аммо Унинг азоби жиноятчи қавмлардан қайтарилмас», деб айт.",148,8],["سَيَقُولُ [h:4505[ٱ]لَّذِينَ أَشْرَكُو[s[اْ] لَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ م[o[َآ] أَشْرَكْنَا وَل[o[َآ] ءَاب[o[َا]ٓؤُنَا وَلَا حَرَّمْنَا مِ[f:2103[ن ش][f:4506[َىْءٍ‌ۚ ك]َذ[n[َٲ]لِكَ كَذَّبَ [h:4507[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ حَتَّىٰ ذَاقُو[s[اْ] بَأْسَنَا‌ۗ قُلْ هَلْ عِ[f:4508[ند]َك[w:4509[ُم م]ِّنْ عِلْ[f:4510[مٍ ف]َتُخْرِجُوهُ لَن[o[َآ‌ۖ] إِ[f:4511[ن ت]َتَّبِعُونَ إِلَّا [h:4359[ٱ][l[ل]ظَّ[g[نّ]َ وَإِنْ أَ[f:428[نت]ُمْ إِلَّا تَخْرُص[p[ُو]نَ","Ҳали ширк келтирганлар: «Агар Аллоҳ хоҳлаганда биз ҳам, ота-боболаримиз ҳам ширк келтирмас эдик ва бирор нарсани ҳаром қилмас эдик», дерлар. Улардан олдингилари ҳам азобимизни татигунларига қадар шунга ўхшаш ёлғонга чиқариб турганлар. Сен: «Сизнинг ҳузурингизда бизга чиқариб кўрсатадиган бирон илм–ҳужжат борми? Сизлар фақат гумонга эргашмоқдасиз ва сизлар фақат ёлғон гапирмоқдасиз» - деб айт.",148,8],["قُلْ فَلِلَّهِ [h:4512[ٱ]لْحُجَّةُ [h:4513[ٱ]لْبَ[n[ـٰ]لِغَةُ‌ۖ فَلَوْ ش[o[َا]ٓءَ لَهَدَ[n[ٮٰ]كُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Сен: «Етук ҳужжат Аллоҳнинг Ўзидадир. Агар хоҳласа, ҳаммангизни ҳидоятга солар эди», деб айт.",148,8],["قُلْ هَلُ[g[مّ]َ شُهَد[o[َا]ٓءَكُمُ [h:4514[ٱ]لَّذِينَ يَشْهَدُونَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ حَرَّمَ هَ[n[ـٰ]ذَا‌ۖ فَإِ[f:2641[ن ش]َهِدُو[s[اْ] فَلَا تَشْهَ[q:4515[دْ] مَعَهُمْ‌ۚ وَلَا تَتَّبِعْ أَهْو[o[َا]ٓءَ [h:4516[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا وَ[h:37[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ وَه[c:4517[ُم ب]ِرَبِّهِمْ يَعْدِل[p[ُو]نَ","Сен: «Аллоҳ мана шуни ҳаром қилганига гувоҳлик берадиган гувоҳларингизни келтиринг», деб айт. Бас, агар гувоҳлик берсалар, сен улар ила гувоҳлик берма. Бизнинг оятларимизни ёлғонга чиқарувчиларнинг ва охиратга иймон келтирмайдиганларнинг ҳавои нафсларига эргашма. Улар Роббиларига ширк келтирурлар.",148,8],["۞ قُلْ تَعَالَوْ[s[اْ] أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ‌ۖ أَلَّا تُشْرِكُو[s[اْ] بِه[n[ِۦ] شَيْـ[a:2771[ـًٔا‌ۖ و]َبِ[h:417[ٱ]لْو[n[َٲ]لِدَيْنِ إِحْسَ[n[ـٰ][a:4518[نًا‌ۖ و]َلَا تَ[q:2734[قْ]تُل[o[ُوٓ][s[اْ] أَوْلَ[n[ـٰ]دَك[w:4519[ُم م]ِّنْ إِمْلَ[n[ـٰ][a:4520[قٍ‌ۖ ن]َّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ‌ۖ وَلَا تَ[q:2802[قْ]رَبُو[s[اْ] [h:4521[ٱ]لْفَو[n[َٲ]حِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ‌ۖ وَلَا تَ[q:2734[قْ]تُلُو[s[اْ] [h:4522[ٱ][l[ل][g[نّ]َفْسَ [h:4523[ٱ]لَّتِى حَرَّمَ [h:3706[ٱ]للَّهُ إِلَّا بِ[h:370[ٱ]لْحَقِّ‌ۚ ذ[n[َٲ]لِكُمْ وَصَّ[n[ـٰ]ك[c:4524[ُم ب]ِه[n[ِۦ] لَعَلَّكُمْ تَعْقِل[p[ُو]نَ","Келинг, Роббингиз сизларга ҳаром қилган нарсаларни тиловат қилиб бераман: «Унга ҳеч нарсани ширк келтирманг! Ота-онангизга яхшилик қилинг! Очликдан қўрқиб, болаларингизни ўлдирманг. Биз сизларни ҳам, уларни ҳам ризқлантирурмиз. Фаҳш–бузуқ ишларнинг ошкорасига ҳам, махфийсига ҳам яқинлашманг. Аллоҳ ҳаром қилган жонни ўлдирманг. Магар ҳақ ила бўлса, майли. Ушбуларни сизга амр қилдикки, шояд ақл юритсангиз.»- деб айт.",148,8],["وَلَا تَ[q:2802[قْ]رَبُو[s[اْ] مَالَ [h:4525[ٱ]لْيَتِيمِ إِلَّا بِ[h:4526[ٱ]لَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَ[q:1053[بْ]لُغَ أَشُدَّهُ[n[ۥ]‌ۖ وَأَوْفُو[s[اْ] [h:4527[ٱ]لْكَيْلَ وَ[h:4528[ٱ]لْمِيزَانَ بِ[h:1800[ٱ]لْقِسْطِ‌ۖ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا‌ۖ وَإِذَا قُلْتُمْ فَ[h:4529[ٱ]عْدِلُو[s[اْ] وَلَوْ كَانَ ذَا قُرْبَىٰ‌ۖ وَبِعَهْدِ [h:4530[ٱ]للَّهِ أَوْفُو[s[اْ‌ۚ] ذ[n[َٲ]لِكُمْ وَصَّ[n[ـٰ]ك[c:4524[ُم ب]ِه[n[ِۦ] لَعَلَّكُمْ تَذَكَّر[p[ُو]نَ","Етимнинг молига то вояга етгунча яқинлашманг. Магар яхши йўл билан бўлса, майли. Ўлчов ва тарозини адолат ила тўлиқ адо этинг. Биз ҳеч бир жонни тоқатидан ташқари нарсага таклиф этмасмиз. Агар гапирсангиз, қариндошингиз бўлса ҳам, адолат қилинг. Аллоҳга берган аҳдингизга вафо қилинг. Буларни сизга амр қилдики, шояд эсласангиз.",149,8],["وَأَ[g[نّ]َ هَ[n[ـٰ]ذَا صِر[n[َٲ]طِى مُسْتَقِي[f:4531[مًا ف]َ[h:4532[ٱ]تَّبِعُوهُ‌ۖ وَلَا تَتَّبِعُو[s[اْ] [h:4533[ٱ][l[ل]سُّبُلَ فَتَفَرَّقَ بِكُمْ عَ[f:4361[ن س]َبِيلِه[n[ِۦ]‌ۚ ذ[n[َٲ]لِكُمْ وَصَّ[n[ـٰ]ك[c:4524[ُم ب]ِه[n[ِۦ] لَعَلَّكُمْ تَتَّق[p[ُو]نَ","Албатта, бу Менинг тўғри йўлимдир. Бас, унга эргашинг. Ва бошқа йўлларга эргашманг. Бас, сизни унинг йўлидан адаштирмасинлар. Мана шу сизга қилган амрки, шояд тақво қилсангиз.",149,8],["ثُ[g[مّ]َ ءَاتَيْنَا مُوسَى [h:257[ٱ]لْكِتَ[n[ـٰ]بَ تَمَامًا عَلَى [h:4534[ٱ]لَّذ[o[ِىٓ] أَحْسَنَ وَتَفْصِيل[u:4535[اً ل]ِّكُلِّ ش[a:4536[َىْءٍ و]َهُ[a:4537[دًى و]َرَحْمَ[u:4538[ةً ل]َّعَلَّه[c:4539[ُم ب]ِلِق[o[َا]ٓءِ رَبِّهِمْ يُؤْمِن[p[ُو]نَ","Яна Мусога ҳам китобни, яхшилик қилганга батамом бўлиш учун, ҳар бир нарса батафсил бўлиши учун, ҳидоят ва раҳмат бўлиши учун бердик. Шоядки, улар Роббиларига дучор бўлишларига иймон келтирсалар.",149,8],["وَهَ[n[ـٰ]ذَا كِتَ[n[ـٰ]بٌ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ مُبَارَ[f:4540[كٌ ف]َ[h:4532[ٱ]تَّبِعُوهُ وَ[h:1018[ٱ]تَّقُو[s[اْ] لَعَلَّكُمْ تُرْحَم[p[ُو]نَ","Биз туширган бу китоб, муборакдир. Бас, унга эргашинглар. Ва тақво қилинглар. Шоядки, раҳм қилинсангизлар.",149,8],["أَ[f:1330[ن ت]َقُول[o[ُوٓ][s[اْ] إِ[g[نّ]َم[o[َآ] أُ[f:17[نز]ِلَ [h:4541[ٱ]لْكِتَ[n[ـٰ]بُ عَلَىٰ ط[o[َا]ٓئِفَتَيْنِ مِ[f:1717[ن ق]َ[q:1718[بْ]لِنَا وَإِ[f:4542[ن ك]ُ[g[نّ]َا عَ[f:4543[ن د]ِرَاسَتِهِمْ لَغَ[n[ـٰ]فِل[p[ِي]نَ","«Биздан аввалги икки тоифага китоб туширилган, уларнинг дарсларидан ғофилмиз», демасликларингиз учун.",149,8],["أَوْ تَقُولُو[s[اْ] لَوْ أَ[g[نّ][o[َآ] أُ[f:17[نز]ِلَ عَلَيْنَا [h:4544[ٱ]لْكِتَ[n[ـٰ]بُ لَكُ[g[نّ][o[َآ] أَهْدَىٰ مِنْهُمْ‌ۚ فَقَ[q:563[دْ] ج[o[َا]ٓءَك[c:4545[ُم ب]َيِّنَ[a:4546[ةٌ م]ّ[u:243[ِن ر]َّبِّكُمْ وَهُ[a:4547[دًى و]َرَحْمَ[f:4548[ةٌ‌ۚ ف]َمَنْ أَظْلَمُ مِ[g[مّ]َ[f:4549[ن ك]َذَّبَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ وَصَدَفَ عَنْهَا‌ۗ سَنَ[q:4550[جْ]زِى [h:4551[ٱ]لَّذِينَ يَصْدِفُونَ عَنْ ءَايَ[n[ـٰ]تِنَا س[o[ُو]ٓءَ [h:239[ٱ]لْعَذَابِ بِمَا كَانُو[s[اْ] يَصْدِف[p[ُو]نَ","Ёки «Агар бизга китоб туширилганда, улардан кўра ҳидоятлироқ бўлар эдик», демасликларингиз учун, батаҳқиқки, сизга Роббингиздан очиқ ҳужжат, ҳидоят ва раҳмат келди. Аллоҳнинг оятларини ёлғонга чиқарган ва улардан юз ўгирган кимсадан ҳам золимроқ шахс борми? Тезда оятларимиздан юз ўгирганларни юз ўгирганлари туфайли ёмон азоб ила жазолармиз.",149,8],["هَلْ يَ[f:1141[نظ]ُرُونَ إِلّ[o[َآ] أَ[f:4552[ن ت]َأْتِيَهُمُ [h:4553[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَ[n[ـٰ]تِ رَبِّكَ‌ۗ يَوْمَ يَأْتِى بَعْضُ ءَايَ[n[ـٰ]تِ رَبِّكَ لَا يَ[f:838[نف]َعُ نَفْسًا إِيمَ[n[ـٰ]نُهَا لَمْ تَكُنْ ءَامَنَتْ مِ[f:128[ن ق]َ[q:129[بْ]لُ أَوْ كَسَبَتْ ف[o[ِىٓ] إِيمَ[n[ـٰ]نِهَا خَيْ[f:4554[رًا‌ۗ ق]ُلِ [h:4555[ٱ][f:4556[نت]َظِر[o[ُوٓ][s[اْ] إِ[g[نّ]َا مُ[f:4557[نت]َظِر[p[ُو]نَ","Улар фаришталар келишини, ё Роббингнинг келишини ёки Роббингнинг баъзи оятлари келишини кутмоқдалар, холос. Роббингнинг баъзи оятлари келган кунида ҳеч бир жонга, олдин иймон келтирмаган ёки иймонида яхшилик касб қилмаган бўлса, иймони наф бермас. Сен: «Кутаверинглар, биз ҳам кутгувчилармиз», деб айт.",150,8],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ فَرَّقُو[s[اْ] دِينَهُمْ وَكَانُو[s[اْ] شِيَ[u:4558[عًا ل]َّسْتَ مِنْهُمْ فِى شَىْءٍ‌ۚ إِ[g[نّ]َم[o[َآ] أَمْرُهُمْ إِلَى [h:1637[ٱ]للَّهِ ثُ[g[مّ]َ يُنَبِّئُه[c:4559[ُم ب]ِمَا كَانُو[s[اْ] يَفْعَل[p[ُو]نَ","Динларини тафриқа қилиб, ўзлари гуруҳбозлик қилганлар билан ҳеч бир алоқанг йўқ. Албатта, уларнинг иши Аллоҳнинг Ўзига ҳавола. Сўнгра қилган ишларининг хабарини берур.",150,8],["مَ[f:4560[ن ج][o[َا]ٓءَ بِ[h:4561[ٱ]لْحَسَنَةِ فَلَهُ[n[ۥ] عَشْرُ أَمْثَالِهَا‌ۖ وَمَ[f:4562[ن ج][o[َا]ٓءَ بِ[h:4563[ٱ][l[ل]سَّيِّئَةِ فَلَا يُ[q:4564[جْ]زَ[o[ىٰٓ] إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَم[p[ُو]نَ","Ким бир яхшилик қилса, унга ўн баробар қайтарилур. Ким бир ёмонлик қилса, унга фақат қилганига яраша жазо бўладур. Ва уларга зулм қилинмас.",150,8],["قُلْ إِ[g[نّ]َنِى هَدَ[n[ٮٰ]نِى رَبّ[o[ِىٓ] إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَقِي[f:4565[مٍ د]ِي[f:4566[نًا ق]ِيَ[a:4567[مًا م]ِّلَّةَ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ حَنِي[a:698[فًا‌ۚ و]َمَا كَانَ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Сен: «Албатта, мени Роббим тўғри йўлга–рост динга–тўғриликка мойил Иброҳим миллатига ҳидоят қилди. У мушриклардан бўлмаган эди», деб айт!",150,8],["قُلْ إِ[g[نّ]َ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Сен: «Албатта, менинг намозим, ибодатларим, ҳаёт ва мамотим оламларнинг Робби Аллоҳ учундир.",150,8],["لَا شَرِيكَ لَهُ[n[ۥ]‌ۖ وَبِذ[n[َٲ]لِكَ أُمِرْتُ وَأَنَا۟ أَوَّلُ [h:4568[ٱ]لْمُسْلِم[p[ِي]نَ","Унинг шериги йўқ. Ана шунга буюрилганман. Ва мен энг аввалги мусулмонман.",150,8],["قُلْ أَغَيْرَ [h:3954[ٱ]للَّهِ أَ[q:4569[بْ]غِى رَب[a:4570[ًّا و]َهُوَ رَبُّ كُلِّ ش[a:4571[َىْءٍ‌ۚ و]َلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا‌ۚ وَلَا تَزِرُ وَازِرَ[a:4572[ةٌ و]ِزْرَ أُخْرَىٰ‌ۚ ثُ[g[مّ]َ إِلَىٰ رَبِّك[w:4573[ُم م]َّرْجِعُكُمْ فَيُنَبِّئُك[c:3605[ُم ب]ِمَا كُ[f:100[نت]ُمْ فِيهِ تَخْتَلِف[p[ُو]نَ","Аллоҳдан ўзгани Роббим дейми? Ҳолбуки У ҳамма нарсанинг Роббидир. Ҳар бир жон ёмон касб қилса, фақат ўзига зиён қиладир. Ҳеч бир жон бошқанинг оғирлигини кўтармас. Сўнгра Роббиларингизга қайтишингиз бор. Бас, У сизларга ихтилоф қилган нарсаларингиз хабарини берур.",150,8],["وَهُوَ [h:4114[ٱ]لَّذِى جَعَلَكُمْ خَلَ[o[ـٰٓ]ئِفَ [h:4574[ٱ]لْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْ[f:4575[ضٍ د]َرَجَ[n[ـٰ][u:4576[تٍ ل]ِّيَ[q:3603[بْ]لُوَكُمْ فِى م[o[َآ] ءَاتَ[n[ـٰ]كُمْ‌ۗ إِ[g[نّ]َ رَبَّكَ سَرِيعُ [h:4577[ٱ]لْعِقَابِ وَإِ[g[نّ]َهُ[n[ۥ] لَغَفُو[u:4578[رٌ ر]َّح[p[ِي]مُۢ","У сизларни ер юзида халифалар қилган ва Ўзи берган нарсаларда сизни синаш учун баъзингизнинг даражасини баъзингиздан устун қилган зотдир. Албатта, Роббинг иқоби тез зотдир. Ва, албатта, у мағфират қилувчи ва раҳмлидир», деб айт.",150,8]]},{"n":7,"ar":"الأَعۡرَافِ","en":"Al-A'raaf","uz":"Аъроф","type":"Макка","ayahs":[["ا[m[لٓ][m[مٓ][m[صٓ]","Алиф. Лаам. Миим. Соод.",151,8],["كِتَ[n[ـٰ]بٌ أُ[f:17[نز]ِلَ إِلَيْكَ فَلَا يَكُ[f:4579[ن ف]ِى صَ[q:4580[دْ]رِكَ حَرَ[a:4581[جٌ م]ِّنْهُ لِتُ[f:4582[نذ]ِرَ بِه[n[ِۦ] وَذِكْرَىٰ لِلْمُؤْمِن[p[ِي]نَ","Бу сенга у ила огоҳлантиришинг учун ва мўминларга эслатма этиб нозил қилинган китобдир. Кўнглингда ундан танглик бўлмасин.",151,8],["ٱتَّبِعُو[s[اْ] م[o[َآ] أُ[f:17[نز]ِلَ إِلَيْك[w:3691[ُم م]ّ[u:243[ِن ر]َّبِّكُمْ وَلَا تَتَّبِعُو[s[اْ] مِ[f:3136[ن د]ُونِه[o[ِۦٓ] أَوْلِي[o[َا]ٓءَ‌ۗ قَلِيل[a:4583[اً م]َّا تَذَكَّر[p[ُو]نَ","Сизларга Роббингиздан нозил қилинган нарсага эргашинглар! Ундан бошқа валий-дўстларга эргашманглар. Жуда оз эслайсизлар.",151,8],["وَك[w:4584[َم م]ِّ[f:4585[ن ق]َرْيَةٍ أَهْلَكْنَ[n[ـٰ]هَا فَج[o[َا]ٓءَهَا بَأْسُنَا بَيَ[n[ـٰ]تًا أَوْ هُمْ ق[o[َا]ٓئِل[p[ُو]نَ","Қанчадан-қанча шаҳар-қишлоқларни ҳалок қилдик. Бас, азобимиз уларга тун уйқусида ёки кун уйқусида келди.",151,8],["فَمَا كَانَ دَعْوَ[n[ٮٰ]هُمْ إِذْ ج[o[َا]ٓءَه[c:4044[ُم ب]َأْسُن[o[َآ] إِلّ[o[َآ] أَ[f:2304[ن ق]َال[o[ُوٓ][s[اْ] إِ[g[نّ]َا كُ[g[نّ]َا ظَ[n[ـٰ]لِم[p[ِي]نَ","Бас, Бизнинг азобимиз келган чоғида уларнинг даъволари: «Албатта, биз золимлардан бўлган эдик», дейишларидан бошқа нарса бўлмади.",151,8],["فَلَنَسْــَٔلَ[g[نّ]َ [h:4586[ٱ]لَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْــَٔلَ[g[نّ]َ [h:4587[ٱ]لْمُرْسَل[p[ِي]نَ","Бас, Биз, албатта, Пайғамбар юборилганлардан ҳам ва, албатта, Пайғамбарлардан ҳам сўрармиз.",151,8],["فَلَنَقُصَّ[g[نّ]َ عَلَيْه[c:4588[ِم ب]ِعِلْ[a:4589[مٍ‌ۖ و]َمَا كُ[g[نّ]َا غ[o[َا]ٓئِب[p[ِي]نَ","Бас, уларга илмий равишда қисса қилиб берурмиз. Ҳолбуки, Биз ғойиб бўлмаган эдик.",151,8],["وَ[h:9999[ٱ]لْوَزْنُ يَوْمَئِذٍ [h:4590[ٱ]لْحَقُّ‌ۚ فَمَ[f:4591[ن ث]َقُلَتْ مَو[n[َٲ]زِينُهُ[n[ۥ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Ўша куни тортиш ҳақдир. Бас, кимнинг тортилган оғир келса, ана ўшалар нажот топгувчилардир.",151,8],["وَمَنْ خَفَّتْ مَو[n[َٲ]زِينُهُ[n[ۥ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:4592[ٱ]لَّذِينَ خَسِر[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَه[c:4593[ُم ب]ِمَا كَانُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا يَظْلِم[p[ُو]نَ","Ва кимнинг тортилган енгил келса, бас, ана ўшалар Бизнинг оятларимизга зулм қилиб, ўзларига зиён этганлардир.",151,8],["وَلَقَ[q:341[دْ] مَكَّ[g[نّ]َ[n[ـٰ]كُمْ فِى [h:44[ٱ]لْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَ[n[ـٰ]يِشَ‌ۗ قَلِيل[a:4583[اً م]َّا تَشْكُر[p[ُو]نَ","Батаҳқиқ, Биз сизларга ер юзида имкон бердик ва унда маишат қилдик. Жуда оз шукр этарсизлар.",151,8],["وَلَقَ[q:341[دْ] خَلَ[q:4250[قْ]نَ[n[ـٰ]كُمْ ثُ[g[مّ]َ صَوَّرْنَ[n[ـٰ]كُمْ ثُ[g[مّ]َ قُلْنَا لِلْمَلَ[o[ـٰٓ]ئِكَةِ [h:179[ٱ]سْجُدُو[s[اْ] لِأَدَمَ فَسَجَد[o[ُوٓ][s[اْ] إِلّ[o[َآ] إِ[q:180[بْ]لِيسَ لَمْ يَك[a:4594[ُن م]ِّنَ [h:4595[ٱ][l[ل]سَّ[n[ـٰ]جِد[p[ِي]نَ","Ва батаҳқиқ, Биз сизларни яратдик, кейин сизларга суврат бердик. Сўнгра эса, фаришталарга: «Одамга сажда қилинг», дедик. Бас, улар сажда қилдилар. Магар Иблис сажда қилувчилардан бўлмади.",151,8],["قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ‌ۖ قَالَ أَنَا۟ خَيْ[a:4596[رٌ م]ِّنْهُ خَلَ[q:4597[قْ]تَنِى م[a:4598[ِن ن]َّا[a:4599[رٍ و]َخَلَ[q:4600[قْ]تَهُ[n[ۥ] مِ[f:3917[ن ط][p[ِي]نٍ","У зот: «Сенга амр этганимда сажда қилишингдан нима тўсди?» деди. У: «Мен ундан яхшиман, мени ўтдан яратдинг ва уни лойдан яратдинг», деди.",152,8],["قَالَ فَ[h:4601[ٱ]هْبِ[q:4601[طْ] مِنْهَا فَمَا يَكُونُ لَكَ أَ[f:4602[ن ت]َتَكَبَّرَ فِيهَا فَ[h:4603[ٱ]خْرُ[q:4603[جْ] إِ[g[نّ]َكَ مِنَ [h:4604[ٱ][l[ل]صَّ[n[ـٰ]غِر[p[ِي]نَ","У зот: «Бас, ундан туш! Сен учун унда мутакаббирлик қилиб юриш йўқ. Бас, чиқ! Албатта, сен хору зор бўлгувчилардансан», деди.",152,8],["قَالَ أَ[f:4605[نظ]ِرْن[o[ِىٓ] إِلَىٰ يَوْمِ يُ[q:4606[بْ]عَث[p[ُو]نَ","У: «Менга улар қайта тирилтириладиган кунгача муҳлат бер», деди.",152,8],["قَالَ إِ[g[نّ]َكَ مِنَ [h:4607[ٱ]لْمُ[f:4608[نظ]َر[p[ِي]نَ","У зот: «Албатта, сен муҳлат берилганлардансан», деди.",152,8],["قَالَ فَبِم[o[َآ] أَغْوَيْتَنِى لَأَ[q:4609[قْ]عُدَ[g[نّ]َ لَهُمْ صِر[n[َٲ]طَكَ [h:4610[ٱ]لْمُسْتَق[p[ِي]مَ","У: «Мени иғвога учирганинг сабабли, албатта, мен уларни Тўғри йўлингда тўсиб ўтираман».",152,8],["ثُ[g[مّ]َ لَأَتِيَ[g[نّ]َه[w:4611[ُم م]ّ[i:4612[ِنۢ ب]َيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَ[n[ـٰ]نِهِمْ وَعَ[f:4613[ن ش]َم[o[َا]ٓئِلِهِمْ‌ۖ وَلَا تَجِدُ أَكْثَرَهُمْ شَ[n[ـٰ]كِر[p[ِي]نَ","Сўнгра уларнинг олдиларидан, орқаларидан, ўнг томонларидан ва чап томонларидан келаман. Ва уларнинг кўпларини шукр қилувчи ҳолда топмссан», деди.",152,8],["قَالَ [h:4614[ٱ]خْرُ[q:4615[جْ] مِنْهَا مَذْءُو[a:4616[مًا م]َّ[q:4617[دْ]حُو[u:4618[رًا‌ۖ ل]َّمَ[f:4619[ن ت]َبِعَكَ مِنْهُمْ لَأَمْلَأَ[g[نّ]َ جَهَ[g[نّ]َمَ مِ[f:344[نك]ُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","У зот: «Ундан мазамматга учраган ва қувилган ҳолингда чиқ!!! Улардан ким сенга эргашса, албатта, жаҳаннамни сизларнинг ҳаммангиз билан тўлдираман», деди.",152,8],["وَيَ[o[ـٰٓـ]ـَٔـادَمُ [h:4620[ٱ]سْكُنْ أَ[f:169[نت]َ وَزَوْجُكَ [h:184[ٱ]لْجَ[g[نّ]َةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَ[q:185[قْ]رَبَا هَ[n[ـٰ]ذِهِ [h:186[ٱ][l[ل]شَّجَرَةَ فَتَكُونَا مِنَ [h:187[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Эй Одам, сен жуфтинг билан жаннатни маскан тут. Икковингиз хоҳлаган жойингиздан енг. Аммо мана бу дарахтга яқинлашманглар. Унинг сабабидан золимлардан бўлиб қолманглар.",152,8],["فَوَسْوَسَ لَهُمَا [h:4621[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ لِيُ[q:4622[بْ]دِىَ لَهُمَا مَا وُ[n[ۥ]رِىَ عَنْهُمَا مِ[f:4623[ن س]َوْء[n[َٲ]تِهِمَا وَقَالَ مَا نَهَ[n[ـٰ]كُمَا رَبُّكُمَا عَنْ هَ[n[ـٰ]ذِهِ [h:4624[ٱ][l[ل]شَّجَرَةِ إِلّ[o[َآ] أَ[f:4625[ن ت]َكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ [h:4626[ٱ]لْخَ[n[ـٰ]لِد[p[ِي]نَ","Бас, шайтон икковларининг беркитилган авратларини очиш учун уларни васваса қилди ва: «Роббингиз сизни ушбу дарахтдан фақат икковингиз фаришта бўлмаслигингиз ёки абадий қолмаслигингиз учунгина ман қилди», деди.",152,8],["وَقَاسَمَهُم[o[َآ] إِ[g[نّ]ِى لَكُمَا لَمِنَ [h:4627[ٱ][l[ل][g[نّ]َ[n[ـٰ]صِح[p[ِي]نَ","Уларга: «Албатта, мен сизларга насиҳат қилувчиларданман», деб қасам ичди.",152,8],["فَدَلَّ[n[ـٰ]هُمَا بِغُرُو[f:4628[رٍ‌ۚ ف]َلَ[g[مّ]َا ذَاقَا [h:4629[ٱ][l[ل]شَّجَرَةَ بَدَتْ لَهُمَا سَوْء[n[َٲ]تُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا م[a:4630[ِن و]َرَقِ [h:4631[ٱ]لْجَ[g[نّ]َةِ‌ۖ وَنَادَ[n[ٮٰ]هُمَا رَبُّهُم[o[َآ] أَلَمْ أَنْهَكُمَا عَ[f:4632[ن ت]ِلْكُمَا [h:4633[ٱ][l[ل]شَّجَرَةِ وَأَقُل لَّكُم[o[َآ] إِ[g[نّ]َ [h:4634[ٱ][l[ل]شَّيْطَ[n[ـٰ]نَ لَكُمَا عَدُ[a:873[وٌّ م]ُّب[p[ِي]نٌ","Бас, уларни алдов ила пастга туширди. Икковлари дарахтдан татиб кўришганда, авратлари ўзларига кўриниб қолди ва ўзларига жаннат баргларидан тўсиқ тўқий бошладилар. Шунда Роббилари уларга нидо қилиб: «Сизларни ана ўша дарахтдан қайтарган эмасмидим ва, албатта, шайтон икковингизга очиқ-ойдин душмандир, демаганмидим?!» деди.",152,8],["قَالَا رَبَّنَا ظَلَمْن[o[َآ] أَ[f:4635[نف]ُسَنَا وَإ[u:3542[ِن ل]َّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَ[g[نّ]َ مِنَ [h:340[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","Икковлари: «Эй Роббимиз, биз ўзимизга зулм қилдик. Агар Сен бизни мағфират қилмасанг ва бизга раҳм қилмасанг, албатта, зиён кўрганлардан бўламиз», дедилар.",153,8],["قَالَ [h:4636[ٱ]هْبِطُو[s[اْ] بَعْضُكُمْ لِبَعْضٍ عَدُ[a:190[وٌّ‌ۖ و]َلَكُمْ فِى [h:44[ٱ]لْأَرْضِ مُسْتَقَ[a:191[رٌّ و]َمَتَ[n[ـٰ]عٌ إِلَىٰ ح[p[ِي]نٍ","У зот: «Бир-бирингизга душман бўлган ҳолингизда тушинглар. Сизларга ер юзида қароргоҳ бор ва маълум вақтгача фойдаланиш бор», деди.",153,8],["قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَج[p[ُو]نَ","У зот: «Унда ҳаёт кечирасизлар, унда ўласизлар ва ундан қайта чиқариласизлар», деди.",153,8],["يَ[n[ـٰ]بَن[o[ِىٓ] ءَادَمَ قَ[q:298[دْ] أَ[f:515[نز]َلْنَا عَلَيْكُمْ لِبَا[a:4637[سًا ي]ُو[n[َٲ]رِى سَوْء[n[َٲ]تِكُمْ وَرِي[a:4638[شًا‌ۖ و]َلِبَاسُ [h:4639[ٱ][l[ل]تَّ[q:1084[قْ]وَىٰ ذ[n[َٲ]لِكَ خَيْ[f:4640[رٌ‌ۚ ذ][n[َٲ]لِكَ مِنْ ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ لَعَلَّهُمْ يَذَّكَّر[p[ُو]نَ","Эй Одам болалари, батаҳқиқ, сизларга авратингизни тўсадиган либос ва зийнат либосини нозил қилдик. Тақво либоси, ана ўша яхшидир. Ана ўшалар Аллоҳнинг оят-белгиларидандир. Шоядки эсласалар.",153,8],["يَ[n[ـٰ]بَن[o[ِىٓ] ءَادَمَ لَا يَفْتِنَ[g[نّ]َكُمُ [h:4641[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ كَم[o[َآ] أَخْرَجَ أَبَوَيْك[w:4642[ُم م]ِّنَ [h:4643[ٱ]لْجَ[g[نّ]َةِ يَ[f:4644[نز]ِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْء[n[َٲ]تِهِم[o[َآ‌ۗ] إِ[g[نّ]َهُ[n[ۥ] يَرَ[n[ٮٰ]كُمْ هُوَ وَقَبِيلُهُ[n[ۥ] مِنْ حَيْثُ لَا تَرَوْنَهُمْ‌ۗ إِ[g[نّ]َا جَعَلْنَا [h:4645[ٱ][l[ل]شَّيَ[n[ـٰ]طِينَ أَوْلِي[o[َا]ٓءَ لِلَّذِينَ لَا يُؤْمِن[p[ُو]نَ","Эй Одам болалари, шайтон ота-онангизни ўзларига авратларини кўрсатиш учун устларидан либосларини ечиб, жаннатдан чиқарганидек, сизни ҳам фитнага солмасин. Албатта, у ва унинг ёрдамчилари сизни сиз кўрмайдиган томондан кўради. Биз, албатта, шайтонларни иймон келтирмайдиганларга дўст қилганмиз.",153,8],["وَإِذَا فَعَلُو[s[اْ] فَ[n[ـٰ]حِشَ[f:4646[ةً ق]َالُو[s[اْ] وَجَ[q:3834[دْ]نَا عَلَيْه[o[َآ] ءَاب[o[َا]ٓءَنَا وَ[h:72[ٱ]للَّهُ أَمَرَنَا بِهَا‌ۗ قُلْ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَأْمُرُ بِ[h:1587[ٱ]لْفَحْش[o[َا]ٓءِ‌ۖ أَتَقُولُونَ عَلَى [h:412[ٱ]للَّهِ مَا لَا تَعْلَم[p[ُو]نَ","Улар қачон фоҳиша иш қилсалар: «Ота-боболаримиз ушбуни қилаётганини кўрдик. Буни бизга Аллоҳ буюрган», дерлар. сен: «Аллоҳ, албатта, фаҳш ишларга буюрмас. Аллоҳ шаънига билмайдиган нарсангизни айтасизми?!» дегин.",153,8],["قُلْ أَمَرَ رَبِّى بِ[h:1800[ٱ]لْقِسْطِ‌ۖ وَأَقِيمُو[s[اْ] وُجُوهَكُمْ عِ[f:264[ند]َ كُلِّ مَسْجِ[a:4647[دٍ و]َ[h:4648[ٱ][q:4648[دْ]عُوهُ مُخْلِصِينَ لَهُ [h:4649[ٱ][l[ل]دِّينَ‌ۚ كَمَا بَدَأَكُمْ تَعُود[p[ُو]نَ","Сен: «Роббим адолатга амр қилди. Ҳар бир ибодатда юзингизни тўғри тутинг. Унинг динига ихлос этган ҳолда дуо қилинг. Сизларни аввалда қандай яратган бўлса, ўша ҳолда қайтарсизлар», деб айт.",153,8],["فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ [h:4650[ٱ][l[ل]ضَّلَ[n[ـٰ]لَةُ‌ۗ إِ[g[نّ]َهُمُ [h:4651[ٱ]تَّخَذُو[s[اْ] [h:4652[ٱ][l[ل]شَّيَ[n[ـٰ]طِينَ أَوْلِي[o[َا]ٓءَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَيَحْسَبُونَ أَ[g[نّ]َه[w:4653[ُم م]ُّهْتَد[p[ُو]نَ","Бир гуруҳни ҳидоят қилди. Бошқа гуруҳга йўлдан озиш ҳақ бўлди. Чунки улар Аллоҳни қўйиб шайтонларни ўзларига дўст тутдилар. Ҳамда ўзларини, албатта, ҳидоят топганлар, деб ҳисоблайдилар.",153,8],["۞ يَ[n[ـٰ]بَن[o[ِىٓ] ءَادَمَ خُذُو[s[اْ] زِينَتَكُمْ عِ[f:264[ند]َ كُلِّ مَسْجِ[a:4654[دٍ و]َكُلُو[s[اْ] وَ[h:300[ٱ]شْرَبُو[s[اْ] وَلَا تُسْرِف[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َهُ[n[ۥ] لَا يُحِبُّ [h:4469[ٱ]لْمُسْرِف[p[ِي]نَ","Эй Одам болалари, ҳар бир ибодат чоғида ўз зийнатингизни олинг. Еб-ичинг ва исроф қилманг. Чунки У зот исроф қилувчиларни севмас.",154,8],["قُلْ مَنْ حَرَّمَ زِينَةَ [h:4655[ٱ]للَّهِ [h:4656[ٱ]لَّت[o[ِىٓ] أَخْرَجَ لِعِبَادِه[n[ِۦ] وَ[h:4657[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تِ مِنَ [h:4658[ٱ][l[ل]رِّزْقِ‌ۚ قُلْ هِىَ لِلَّذِينَ ءَامَنُو[s[اْ] فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا خَالِصَ[a:4659[ةً ي]َوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۗ كَذ[n[َٲ]لِكَ نُفَصِّلُ [h:4091[ٱ]لْأَيَ[n[ـٰ]تِ لِقَوْ[a:1292[مٍ ي]َعْلَم[p[ُو]نَ","Сен: «Аллоҳ Ўз бандаларига чиқарган зийнатларни ва покиза ризқларни ким ҳаром қилди?!» деб айт. «Улар ҳаёти дунёда иймон келтирганларга, қиёмат кунида эса фақат ўзларига хосдир», деб айт. Биладиган қавмлар учун оятларни мана шундай муфассал баён қиламиз.",154,8],["قُلْ إِ[g[نّ]َمَا حَرَّمَ رَبِّىَ [h:4660[ٱ]لْفَو[n[َٲ]حِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَ[h:4661[ٱ]لْإِثْمَ وَ[h:4662[ٱ]لْبَغْىَ بِغَيْرِ [h:325[ٱ]لْحَقِّ وَأَ[f:4663[ن ت]ُشْرِكُو[s[اْ] بِ[h:32[ٱ]للَّهِ مَا لَمْ يُنَزِّلْ بِه[n[ِۦ] سُلْطَ[n[ـٰ][a:4664[نًا و]َأَ[f:877[ن ت]َقُولُو[s[اْ] عَلَى [h:412[ٱ]للَّهِ مَا لَا تَعْلَم[p[ُو]نَ","«Роббим фақатгина ошкора ва яширин фаҳш ишларни, гуноҳларни, ноҳақ тажовузкорликни ва Аллоҳга ҳеч қандай ҳужжат туширмаган нарсаларни шерик қилиб олишингизни ҳамда Аллоҳга нисбатан билмаган нарсани айтишни ҳаром қилган, холос», деб айт.",154,8],["وَلِكُلِّ أُ[g[مّ]َةٍ أَجَ[f:4665[لٌ‌ۖ ف]َإِذَا ج[o[َا]ٓءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَ[a:4666[ةً‌ۖ و]َلَا يَسْتَ[q:4667[قْ]دِم[p[ُو]نَ","Ҳар бир умматнинг ажали бор. Ажаллари келган вақтида бирор соатга кетга ҳам, олдинга ҳам сура олмаслар.",154,8],["يَ[n[ـٰ]بَن[o[ِىٓ] ءَادَمَ إِ[g[مّ]َا يَأْتِيَ[g[نّ]َكُمْ رُسُ[a:4419[لٌ م]ِّ[f:344[نك]ُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَ[n[ـٰ]تِى‌ۙ فَمَنِ [h:4668[ٱ]تَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Эй Одам болалари, агар сизларга ўзингиздан бўлган Пайғамбарлар келиб, оятларимни сўзлаганда, бас, ким тақво қилса ва яхши амал қилса, уларга хавф йўқдир ва улар хафа ҳам бўлмаслар.",154,8],["وَ[h:9999[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا وَ[h:3326[ٱ]سْتَكْبَرُو[s[اْ] عَنْه[o[َآ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Оятларимизни ёлғонга чиқарганлар ва улардан кибр қилганлар, ана ўшалар дўзах эгаларидир. Улар унда абадий қолурлар.",154,8],["فَمَنْ أَظْلَمُ مِ[g[مّ]َنِ [h:3980[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔـايَ[n[ـٰ]تِه[o[ِۦٓ‌ۚ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يَنَالُهُمْ نَصِيبُه[w:4669[ُم م]ِّنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ‌ۖ حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَال[o[ُوٓ][s[اْ] أَيْنَ مَا كُ[f:100[نت]ُمْ تَ[q:4040[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ‌ۖ قَالُو[s[اْ] ضَلُّو[s[اْ] عَ[g[نّ]َا وَشَهِدُو[s[اْ] عَلَ[o[ىٰٓ] أَ[f:568[نف]ُسِهِمْ أَ[g[نّ]َهُمْ كَانُو[s[اْ] كَ[n[ـٰ]فِر[p[ِي]نَ","Аллоҳга нисбатан ёлғон тўқиган ёки Унинг оятларини ёлғонга чиқарган кимсадан ҳам золимроқ одам борми?! Ана ўшаларга китобдан насибалари етадир. Бизнинг элчиларимиз келиб уларнинг жонларини олаётиб: «Аллоҳдан ўзга ибодат қилаётган нарсаларингиз қани?» дерлар. Улар: «Биздан ғоиб бўлишди», дерлар ва ўз зиёнларига, кофир бўлганларини айтиб, гувоҳлик берарлар.",154,8],["قَالَ [h:4670[ٱ][q:278[دْ]خُلُو[s[اْ] ف[o[ِىٓ] أُمَ[f:4671[مٍ ق]َ[q:298[دْ] خَلَتْ مِ[f:85[ن ق]َ[q:86[بْ]لِك[w:4672[ُم م]ِّنَ [h:4673[ٱ]لْجِ[g[نّ]ِ وَ[h:4418[ٱ]لْإِ[f:4418[نس]ِ فِى [h:4674[ٱ][l[ل][g[نّ]َارِ‌ۖ كُلَّمَا دَخَلَتْ أُ[g[مّ]َ[u:4675[ةٌ ل]َّعَنَتْ أُخْتَهَا‌ۖ حَتَّ[o[ىٰٓ] إِذَا [h:4676[ٱ]دَّارَكُو[s[اْ] فِيهَا جَمِي[f:4677[عًا ق]َالَتْ أُخْرَ[n[ٮٰ]هُمْ لِأُولَ[n[ـٰ]هُمْ رَبَّنَا هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ أَضَلُّونَا فَـَٔـاتِهِمْ عَذَا[f:4678[بًا ض]ِعْ[a:4679[فًا م]ِّنَ [h:869[ٱ][l[ل][g[نّ]َارِ‌ۖ قَالَ لِكُ[f:4680[لٍّ ض]ِعْ[a:4681[فٌ و]َلَ[n[ـٰ]ك[u:46[ِن ل]َّا تَعْلَم[p[ُو]نَ","У зот: «Сиздан олдин ўтган, жин ва инсдан бўлган умматлар билан дўзахга киринг», дер. Қачонки қайси бир уммат кирса, шеригини лаънатлар. Бироқ у ерда ҳаммалари топишганларида, кейингилари аввалгиларини: «Эй Роббимиз, бизни анавилар адаштирган эдилар. Уларга дўзах азобини икки баробар қилиб бер», дерлар. У зот: «Ҳаммага ҳам икки баробар, лекин билмассизлар», дер.",155,8],["وَقَالَتْ أُولَ[n[ـٰ]هُمْ لِأُخْرَ[n[ٮٰ]هُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِ[f:4682[ن ف]َضْ[f:4683[لٍ ف]َذُوقُو[s[اْ] [h:2154[ٱ]لْعَذَابَ بِمَا كُ[f:100[نت]ُمْ تَكْسِب[p[ُو]نَ","Аввалгилар кейингиларга: «Сизларни биздан афзаллик томонингиз йўқ. Қилган касбингизга яраша азобни тортаверинглар», дерлар.",155,8],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا وَ[h:3326[ٱ]سْتَكْبَرُو[s[اْ] عَنْهَا لَا تُفَتَّحُ لَهُمْ أَ[q:4684[بْ]و[n[َٲ]بُ [h:4685[ٱ][l[ل]سَّم[o[َا]ٓءِ وَلَا يَ[q:3156[دْ]خُلُونَ [h:3157[ٱ]لْجَ[g[نّ]َةَ حَتَّىٰ يَلِجَ [h:4686[ٱ]لْجَمَلُ فِى سَ[g[مّ]ِ [h:4687[ٱ]لْخِيَاطِ‌ۚ وَكَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4688[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","Албатта, оятларимизни ёлғонга чиқарганлар ва улардан кибр қилганларга осмон эшиклари очилмас ва улар туя игна тешигидан ўтмагунча жаннатга кирмаслар. Жиноятчиларни мана шундай жазолаймиз.",155,8],["لَه[w:1812[ُم م]ِّ[f:4689[ن ج]َهَ[g[نّ]َمَ مِهَا[a:4690[دٌ و]َمِ[f:4691[ن ف]َوْقِهِمْ غَوَا[a:4692[شٍ‌ۚ و]َكَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4693[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Уларга жаҳаннамдан тўшак ва устларига чойшаб бор. Золимларни мана шундай жазолаймиз.",155,8],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَه[o[َآ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:415[ٱ]لْجَ[g[نّ]َةِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Иймон келтириб, яхши амалларни қилганлар–Биз ҳеч бир жонни тоқатидан ташқари нарсага таклиф қилмаймиз–ана ўшалар жаннат эгаларидир. Улар унда абадий қолурлар.",155,8],["وَنَزَعْنَا مَا فِى صُدُورِه[w:4694[ِم م]ِّنْ غِ[f:4695[لٍّ ت]َ[q:120[جْ]رِى مِ[f:4696[ن ت]َحْتِهِمُ [h:4697[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۖ وَقَالُو[s[اْ] [h:4698[ٱ]لْحَمْدُ لِلَّهِ [h:3912[ٱ]لَّذِى هَدَ[n[ٮٰ]نَا لِهَ[n[ـٰ]ذَا وَمَا كُ[g[نّ]َا لِنَهْتَدِىَ لَوْل[o[َآ] أَنْ هَدَ[n[ٮٰ]نَا [h:4173[ٱ]للَّهُ‌ۖ لَقَ[q:2389[دْ] ج[o[َا]ٓءَتْ رُسُلُ رَبِّنَا بِ[h:370[ٱ]لْحَقِّ‌ۖ وَنُود[o[ُوٓ][s[اْ] أَ[f:4699[ن ت]ِلْكُمُ [h:4700[ٱ]لْجَ[g[نّ]َةُ أُورِثْتُمُوهَا بِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Ва кўксиларидаги ғиллу ғашларни чиқариб олдик, остиларидан анҳорлар оқиб турибди. Улар: «Бизни шунга ҳидоят қилган Аллоҳга ҳамдлар бўлсин, агар Аллоҳ бизни ҳидоят қилмаганда, ўзимиз йўл топа олмас эдик. Роббимизнинг элчилари ҳақни келтирдилар», дедилар. Ва уларга: «Мана шу жаннатингизни қилган амалларингиз туфайли мерос қилиб олдингиз», деб нидо қилинур.",155,8],["وَنَادَ[o[ىٰٓ] أَصْحَ[n[ـٰ]بُ [h:415[ٱ]لْجَ[g[نّ]َةِ أَصْحَ[n[ـٰ]بَ [h:4701[ٱ][l[ل][g[نّ]َارِ أَ[f:3885[ن ق]َ[q:298[دْ] وَجَ[q:3834[دْ]نَا مَا وَعَدَنَا رَبُّنَا حَق[f:4702[ًّا ف]َهَلْ وَجَ[d:4703[د]تّ[w:4704[ُم م]َّا وَعَدَ رَبُّكُمْ حَق[f:4705[ًّا‌ۖ ق]َالُو[s[اْ] نَعَمْ‌ۚ فَأَذَّنَ مُؤَذِّ[i:4706[نُۢ ب]َيْنَهُمْ أ[u:4707[َن ل]َّعْنَةُ [h:822[ٱ]للَّهِ عَلَى [h:1035[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Ва жаннат эгалари дўзах эгаларига: «Биз Роббимиз бизга ваъда қилган нарсанинг ҳақ эканини топдик. Сизлар ҳам Роббингиз ваъда қилган нарсанинг ҳақ эканини топдингизми?!» деб нидо қиладир. Улар: «Ҳа!» дерлар. Бас, улар ўрталарида бир жарчи: «Золимларга Аллоҳнинг лаънати бўлсин!!!",156,8],["ٱلَّذِينَ يَصُدُّونَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ وَيَ[q:4708[بْ]غُونَهَا عِوَ[a:4709[جًا و]َه[c:4710[ُم ب]ِ[h:447[ٱ]لْأَخِرَةِ كَ[n[ـٰ]فِر[p[ُو]نَ","Аллоҳнинг йўлидан тўсадиган, уни бузишни истайдиган ва охиратга кофир бўлувчиларга!!!» деб жар соладир.",156,8],["وَبَيْنَهُمَا حِجَا[a:4711[بٌ‌ۚ و]َعَلَى [h:4712[ٱ]لْأَعْرَافِ رِجَا[a:4713[لٌ ي]َعْرِفُونَ كُلا[i:4714[َّۢ ب]ِسِيمَ[n[ـٰ]هُمْ‌ۚ وَنَادَوْ[s[اْ] أَصْحَ[n[ـٰ]بَ [h:4715[ٱ]لْجَ[g[نّ]َةِ أَ[f:4716[ن س]َلَ[n[ـٰ]مٌ عَلَيْكُمْ‌ۚ لَمْ يَ[q:598[دْ]خُلُوهَا وَهُمْ يَ[q:4717[طْ]مَع[p[ُو]نَ","Ораларида аъроф-тўсиқ бор, у деворлар устидаги кишилар ҳаммаларини сиймоларидан танирлар. Тамаъ қилган ҳолларида кирмай турган жаннат эгаларига: «Сизга салом бўлсин», деб нидо қиларлар.",156,8],["۞ وَإِذَا صُرِفَتْ أَ[q:4718[بْ]صَ[n[ـٰ]رُهُمْ تِلْق[o[َا]ٓءَ أَصْحَ[n[ـٰ]بِ [h:3507[ٱ][l[ل][g[نّ]َارِ قَالُو[s[اْ] رَبَّنَا لَا تَ[q:4719[جْ]عَلْنَا مَعَ [h:3746[ٱ]لْقَوْمِ [h:4155[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Қачонки кўзлари дўзах эгалари томон бурилиб қолса: «Эй Роббимиз, бизни золим қавмлар билан бирга қилмагин», дерлар.",156,8],["وَنَادَ[o[ىٰٓ] أَصْحَ[n[ـٰ]بُ [h:4720[ٱ]لْأَعْرَافِ رِجَال[a:4721[اً ي]َعْرِفُونَه[c:4722[ُم ب]ِسِيمَ[n[ـٰ]هُمْ قَالُو[s[اْ] م[o[َآ] أَغْنَىٰ عَ[f:255[نك]ُمْ جَمْعُكُمْ وَمَا كُ[f:100[نت]ُمْ تَسْتَكْبِر[p[ُو]نَ","Аъроф эгалари сиймоларидан танийдиган кишиларига нидо қилиб: «Тўплаганингиз ва қилган кибру ҳавоингиз сизга асқотмабди-ку!",156,8],["أَهَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ [h:3630[ٱ]لَّذِينَ أَ[q:4723[قْ]سَمْتُمْ لَا يَنَالُهُمُ [h:4724[ٱ]للَّهُ بِرَحْمَةٍ‌ۚ [h:4725[ٱ][q:278[دْ]خُلُو[s[اْ] [h:4726[ٱ]لْجَ[g[نّ]َةَ لَا خَوْفٌ عَلَيْكُمْ وَل[o[َآ] أَ[f:428[نت]ُمْ تَحْزَن[p[ُو]نَ","Сизлар: Аллоҳ уларга раҳмат етказмас, деб қасам ичганингиз ана уларми?!: Жаннатга киринглар! Сизга хавф йўқ ва сиз хафа ҳам бўлмайсиз, дейилди-ку!» дерлар.",156,8],["وَنَادَ[o[ىٰٓ] أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ أَصْحَ[n[ـٰ]بَ [h:4715[ٱ]لْجَ[g[نّ]َةِ أَنْ أَفِيضُو[s[اْ] عَلَيْنَا مِنَ [h:4727[ٱ]لْم[o[َا]ٓءِ أَوْ مِ[g[مّ]َا رَزَقَكُمُ [h:3751[ٱ]للَّهُ‌ۚ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ حَرَّمَهُمَا عَلَى [h:468[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Дўзах эгалари жаннат эгаларига: «Бизга ҳам сувдан ёки Аллоҳ сизга ризқ қилиб берган нарсадан тўкинглар», деб нидо қиларлар. Улар: «Албатта, Аллоҳ буларни кофирларга ҳаром қилган.",156,8],["ٱلَّذِينَ [h:3645[ٱ]تَّخَذُو[s[اْ] دِينَهُمْ لَهْ[a:4728[وًا و]َلَعِ[a:4729[بًا و]َغَرَّتْهُمُ [h:4161[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَا‌ۚ فَ[h:4730[ٱ]لْيَوْمَ نَ[f:4731[نس]َ[n[ـٰ]هُمْ كَمَا نَسُو[s[اْ] لِق[o[َا]ٓءَ يَوْمِهِمْ هَ[n[ـٰ]ذَا وَمَا كَانُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا يَ[q:4008[جْ]حَد[p[ُو]نَ","Динларини ўйин-кулги қилиб олган ва ҳаёти дунё ғурурига кетганларга», дерлар. Бас, бу Кунда улар бугунги ҳолга дучор бўлишларини унутганлари ва оятларимизни инкор қилганларидек, Биз ҳам уларни унутамиз.",156,8],["وَلَقَ[q:341[دْ] جِئْنَ[n[ـٰ]ه[c:4732[ُم ب]ِكِتَ[n[ـٰ][f:4733[بٍ ف]َصَّلْنَ[n[ـٰ]هُ عَلَىٰ عِلْمٍ هُ[a:4734[دًى و]َرَحْمَ[u:4735[ةً ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Батаҳқиқ, Биз уларга илм ила муфассал қилинган, иймон келтирган қавм учун ҳидоят ва раҳмат бўлган китобни келтирдик.",157,8],["هَلْ يَ[f:1141[نظ]ُرُونَ إِلَّا تَأْوِيلَهُ[n[ۥ]‌ۚ يَوْمَ يَأْتِى تَأْوِيلُهُ[n[ۥ] يَقُولُ [h:3992[ٱ]لَّذِينَ نَسُوهُ مِ[f:128[ن ق]َ[q:129[بْ]لُ قَ[q:298[دْ] ج[o[َا]ٓءَتْ رُسُلُ رَبِّنَا بِ[h:370[ٱ]لْحَقِّ فَهَل لَّنَا مِ[f:4736[ن ش]ُفَع[o[َا]ٓءَ فَيَشْفَعُو[s[اْ] لَن[o[َآ] أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ [h:287[ٱ]لَّذِى كُ[g[نّ]َا نَعْمَلُ‌ۚ قَ[q:298[دْ] خَسِر[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ وَضَلَّ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَفْتَر[p[ُو]نَ","Улар унинг таъвилини–оқибатини кутмоқдалар, холос. Унинг таъвили келган кунда илгари уни унутганлар: «Роббимизнинг Пайғамбарлари ҳақ ила келган эканлар. Энди бизга шафоат қилувчилар борми, шафоат қилсалар ёки ортга қайтарилсагу қилган амалларимиздан бошқача амалларни қилсак», дерлар. Батаҳқиқ, улар ўзларига зиён қилдилар ва тўқиб олган нарсалари улардан ғойиб бўлди.",157,8],["إِ[g[نّ]َ رَبَّكُمُ [h:4737[ٱ]للَّهُ [h:4738[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ فِى سِتَّةِ أَيَّا[f:4739[مٍ ث]ُ[g[مّ]َ [h:156[ٱ]سْتَوَىٰ عَلَى [h:4740[ٱ]لْعَرْشِ يُغْشِى [h:4741[ٱ]لَّيْلَ [h:4742[ٱ][l[ل][g[نّ]َهَارَ يَ[q:4743[طْ]لُبُهُ[n[ۥ] حَثِي[a:4744[ثًا و]َ[h:4264[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ وَ[h:4745[ٱ][l[ل][g[نّ]ُجُومَ مُسَخَّر[n[َٲ][i:4746[تِۭ ب]ِأَمْرِه[o[ِۦٓ‌ۗ] أَلَا لَهُ [h:4747[ٱ]لْخَلْقُ وَ[h:4748[ٱ]لْأَمْرُ‌ۗ تَبَارَكَ [h:4749[ٱ]للَّهُ رَبُّ [h:4750[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Албатта осмонлару ерни олти кунда яратган, сўнгра Аршни эгаллаган Роббингиз кеча ила кундузни қоплайдир. Уни шошилиб қувлайдир. Қуёш, ой ва юлдузларни Ўз амрига бўйсундирилган қилиб яратди. Огоҳ бўлинг, яратиш ва амр қилиш унинг Ўзига хосдир. Оламларнинг Робби–Аллоҳ буюкдир.",157,8],["ٱ[q:4751[دْ]عُو[s[اْ] رَبَّكُمْ تَضَرُّ[a:4131[عًا و]َخُفْيَةً‌ۚ إِ[g[نّ]َهُ[n[ۥ] لَا يُحِبُّ [h:1021[ٱ]لْمُعْتَد[p[ِي]نَ","Роббингизга тазарруъ ила ва махфий дуо қилинг. Зотан, У ҳаддан ошувчиларни севмас.",157,8],["وَلَا تُفْسِدُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ بَعْدَ إِصْلَ[n[ـٰ]حِهَا وَ[h:4648[ٱ][q:4648[دْ]عُوهُ خَوْ[a:4752[فًا و]َطَمَعًا‌ۚ إِ[g[نّ]َ رَحْمَتَ [h:1214[ٱ]للَّهِ قَرِي[a:4753[بٌ م]ِّنَ [h:4754[ٱ]لْمُحْسِن[p[ِي]نَ","Ва ислоҳ қилингандан кейин ер юзида фасод қилманг ва Ундан қўрқиб тамаъ ила дуо қилинг. Албатта, Аллоҳнинг раҳмати яхшилик қилувчиларга яқиндир.",157,8],["وَهُوَ [h:4114[ٱ]لَّذِى يُرْسِلُ [h:4755[ٱ][l[ل]رِّيَ[n[ـٰ]حَ بُشْر[i:4756[َۢا ب]َيْنَ يَدَىْ رَحْمَتِه[n[ِۦ]‌ۖ حَتَّ[o[ىٰٓ] إِذ[o[َآ] أَقَلَّتْ سَحَا[f:4757[بًا ث]ِقَال[f:4758[اً س]ُ[q:4759[قْ]نَ[n[ـٰ]هُ لِبَلَ[a:4760[دٍ م]َّيِّ[f:4761[تٍ ف]َأَ[f:288[نز]َلْنَا بِهِ [h:4762[ٱ]لْم[o[َا]ٓءَ فَأَخْرَ[q:4279[جْ]نَا بِه[n[ِۦ] مِ[f:843[ن ك]ُلِّ [h:1571[ٱ][l[ل]ثَّمَر[n[َٲ]تِ‌ۚ كَذ[n[َٲ]لِكَ نُخْرِجُ [h:4763[ٱ]لْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّر[p[ُو]نَ","У Ўз раҳматидан олдин шамолларни хушхабар қилиб юборадиган Зотдир. Қачонки, улар оғир булутларни кўтариб келтиргач, у ила ўлик юртни суғорамиз. Ундан сув тушириб, ўша ила турли мевалар чиқарамиз. Ўликларни ҳам шундай қилиб чиқарамиз. Шоядки эсласангизлар.",157,8],["وَ[h:9999[ٱ]لْبَلَدُ [h:4764[ٱ][l[ل]طَّيِّبُ يَخْرُجُ نَبَاتُهُ[n[ۥ] بِإِذْنِ رَبِّه[n[ِۦ]‌ۖ وَ[h:4765[ٱ]لَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِ[f:4766[دًا‌ۚ ك]َذ[n[َٲ]لِكَ نُصَرِّفُ [h:4060[ٱ]لْأَيَ[n[ـٰ]تِ لِقَوْ[a:4767[مٍ ي]َشْكُر[p[ُو]نَ","Пок юртнинг набототи Роббининг изни ила чиқадир. Нопок бўлгани эса, фақат қийинчилик ила чиқадир. Шукр келтирган қавмлар учун оятларимизни шундай хилма-хил баён қилурмиз.",158,8],["لَقَ[q:2389[دْ] أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِه[n[ِۦ] فَقَالَ يَ[n[ـٰ]قَوْمِ [h:4768[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ مَا لَك[w:556[ُم م]ِّنْ إِلَ[n[ـٰ]هٍ غَيْرُهُ[o[ۥٓ] إِ[g[نّ][o[ِىٓ] أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظ[p[ِي]مٍ","Батаҳқиқ, Биз Нуҳни ўз қавмига юбордик. Бас, у: «Эй қавмим, Аллоҳга ибодат қилинглар. Сизларга Ундан ўзга илоҳ йўқ. Албатта, мен сизларнинг буюк куннинг азобига гирифтор бўлишингиздан қўрқаман», деди.",158,8],["قَالَ [h:4769[ٱ]لْمَلَأُ مِ[f:4770[ن ق]َوْمِه[o[ِۦٓ] إِ[g[نّ]َا لَنَرَ[n[ٮٰ]كَ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Унинг қавмидан бўлган зодагонлар: «Албатта, биз сени очиқ-ойдин залолатда эканингни кўряпмиз», дедилар.",158,8],["قَالَ يَ[n[ـٰ]قَوْمِ لَيْسَ بِى ضَلَ[n[ـٰ]لَ[a:4771[ةٌ و]َلَ[n[ـٰ]كِ[g[نّ]ِى رَسُو[a:521[لٌ م]ّ[u:4772[ِن ر]َّبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","У: «Эй қавмим, менда залолат йўқ. Балки мен оламларнинг Роббидан Пайғамбарман.",158,8],["أُبَلِّغُكُمْ رِسَ[n[ـٰ]لَ[n[ـٰ]تِ رَبِّى وَأَ[f:4773[نص]َحُ لَكُمْ وَأَعْلَمُ مِنَ [h:321[ٱ]للَّهِ مَا لَا تَعْلَم[p[ُو]نَ","Сизларга Роббимнинг юборганларини етказаман, насиҳат қиламан ва Аллоҳ томонидан сиз билмаган нарсани биламан.",158,8],["أَوَعَجِ[q:4774[بْ]تُمْ أَ[f:4775[ن ج][o[َا]ٓءَكُمْ ذِكْ[a:4776[رٌ م]ّ[u:243[ِن ر]َّبِّكُمْ عَلَىٰ رَجُ[a:4777[لٍ م]ِّ[f:344[نك]ُمْ لِيُ[f:4778[نذ]ِرَكُمْ وَلِتَتَّقُو[s[اْ] وَلَعَلَّكُمْ تُرْحَم[p[ُو]نَ","Ўзингиздан бўлган бир кишига, сизларни огоҳлантириш учун ва тақво қилиб, шояд раҳматга эришсангиз деб Роббингиздан эслатма келганидан ажабланасизларми?!» деди.",158,8],["فَكَذَّبُوهُ فَأَ[f:4779[نج]َيْنَ[n[ـٰ]هُ وَ[h:37[ٱ]لَّذِينَ مَعَهُ[n[ۥ] فِى [h:4780[ٱ]لْفُلْكِ وَأَغْرَ[q:247[قْ]نَا [h:4781[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِن[o[َآ‌ۚ] إِ[g[نّ]َهُمْ كَانُو[s[اْ] قَوْمًا عَم[p[ِي]نَ","Бас, уни ёлғончига чиқардилар. Сўнг Биз уни ва у билан бирга бўлганларни кемада қутқардик ва оятларимизни ёлғонга чиқарганларни ғарқ қилдик. Чунки улар кўр қавм эдилар.",158,8],["۞ وَإِلَىٰ عَادٍ أَخَاهُمْ هُو[f:4782[دًا‌ۗ ق]َالَ يَ[n[ـٰ]قَوْمِ [h:4768[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ مَا لَك[w:556[ُم م]ِّنْ إِلَ[n[ـٰ]هٍ غَيْرُهُ[o[ۥٓ‌ۚ] أَفَلَا تَتَّق[p[ُو]نَ","Ва Одга ўз биродари Ҳудни. У: «Эй қавмим, Аллоҳга ибодат қилинглар. Сизларга Ундан ўзга илоҳ йўқ. Тақво қилмайсизларми?!» деди.",158,8],["قَالَ [h:4769[ٱ]لْمَلَأُ [h:4783[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِ[f:4770[ن ق]َوْمِه[o[ِۦٓ] إِ[g[نّ]َا لَنَرَ[n[ٮٰ]كَ فِى سَفَاهَ[a:4784[ةٍ و]َإِ[g[نّ]َا لَنَظُ[g[نّ]ُكَ مِنَ [h:4785[ٱ]لْكَ[n[ـٰ]ذِب[p[ِي]نَ","Унинг қавмидан куфр келтирган зодагонлар: «Албатта, биз сени эси пастликда кўриб турибмиз ва албатта биз сени ёлғончилардан деб биламиз», дедилар.",158,8],["قَالَ يَ[n[ـٰ]قَوْمِ لَيْسَ بِى سَفَاهَ[a:4786[ةٌ و]َلَ[n[ـٰ]كِ[g[نّ]ِى رَسُو[a:521[لٌ م]ّ[u:4772[ِن ر]َّبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","У: «Эй қавмим, менда эси пастлик йўқ. Лекин мен оламларнинг Роббидан Пайғамбарман.",158,8],["أُبَلِّغُكُمْ رِسَ[n[ـٰ]لَ[n[ـٰ]تِ رَبِّى وَأَنَا۟ لَكُمْ نَاصِحٌ أَم[p[ِي]نٌ","Сизларга Роббимнинг юборганларини етказаман ва мен сизларга ишончли насиҳатгўйман.",159,8],["أَوَعَجِ[q:4774[بْ]تُمْ أَ[f:4775[ن ج][o[َا]ٓءَكُمْ ذِكْ[a:4776[رٌ م]ّ[u:243[ِن ر]َّبِّكُمْ عَلَىٰ رَجُ[a:4777[لٍ م]ِّ[f:344[نك]ُمْ لِيُ[f:4778[نذ]ِرَكُمْ‌ۚ وَ[h:335[ٱ]ذْكُر[o[ُوٓ][s[اْ] إِذْ جَعَلَكُمْ خُلَف[o[َا]ٓءَ م[i:146[ِنۢ ب]َعْدِ قَوْمِ نُو[a:4787[حٍ و]َزَادَكُمْ فِى [h:4788[ٱ]لْخَلْقِ بَصْۜطَ[f:4789[ةً‌ۖ ف]َ[h:1091[ٱ]ذْكُر[o[ُوٓ][s[اْ] ءَال[o[َا]ٓءَ [h:4790[ٱ]للَّهِ لَعَلَّكُمْ تُفْلِح[p[ُو]نَ","Ўзингиздан бўлган бир кишига сизларни огоҳлантириш учун Роббингиздан эслатма келганидан ажабландингизми?! Сизларни Нуҳ қавмидан кейин халифа қилганини ва хилқатингизда куч-қувватни зиёда қилганини эсланг. Аллоҳнинг неъматларини эсланг. Шоядки, нажот топсангиз», деди.",159,8],["قَال[o[ُوٓ][s[اْ] أَجِئْتَنَا لِنَعْبُدَ [h:4791[ٱ]للَّهَ وَحْدَهُ[n[ۥ] وَنَذَرَ مَا كَانَ يَعْبُدُ ءَاب[o[َا]ٓؤُنَا‌ۖ فَأْتِنَا بِمَا تَعِدُن[o[َآ] إِ[f:4792[ن ك]ُ[f:735[نت]َ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","Улар: «Сен бизга ёлғиз Аллоҳнинг Ўзига ибодат қилишимиз ва ота-боболаримиз ибодат қилган нарсаларни тарк этишимиз учун келдингми?! Агар ростгўйлардан бўлсанг, бизга ваъда қилаётган нарсангни келтир!» дедилар.",159,8],["قَالَ قَ[q:298[دْ] وَقَعَ عَلَيْك[w:548[ُم م]ّ[u:243[ِن ر]َّبِّكُمْ رِ[q:3765[جْ][a:4794[سٌ و]َغَضَبٌ‌ۖ أَتُجَ[n[ـٰ]دِلُونَنِى ف[o[ِىٓ] أَسْم[o[َا]ٓ[f:4795[ءٍ س]َ[g[مّ]َيْتُمُوه[o[َآ] أَ[f:428[نت]ُمْ وَءَاب[o[َا]ٓؤُك[w:4796[ُم م]َّا نَزَّلَ [h:4797[ٱ]للَّهُ بِهَا مِ[f:4798[ن س]ُلْطَ[n[ـٰ][f:4799[نٍ‌ۚ ف]َ[h:4800[ٱ][f:4800[نت]َظِر[o[ُوٓ][s[اْ] إِ[g[نّ]ِى مَعَك[w:2068[ُم م]ِّنَ [h:4801[ٱ]لْمُ[f:4802[نت]َظِر[p[ِي]نَ","У: «Батаҳқиқ, устингизга Роббингиз томонидан азоб ва ғазаб тушди. Мен билан Аллоҳ ҳеч бир ҳужжат туширмаган, ўзингиз ва ота боболарингиз қўйиб олган номлар ҳақида тортишасизларми?! Бас, интизор бўлиб туринглар! Мен ҳам сизлар билан интизор бўлувчиларданман», деди.",159,8],["فَأَ[f:4779[نج]َيْنَ[n[ـٰ]هُ وَ[h:37[ٱ]لَّذِينَ مَعَهُ[n[ۥ] بِرَحْمَ[a:4803[ةٍ م]ِّ[g[نّ]َا وَقَطَعْنَا دَابِرَ [h:4804[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا‌ۖ وَمَا كَانُو[s[اْ] مُؤْمِن[p[ِي]نَ","Бас, унга ва у билан бирга бўлганларга Ўз раҳматимиз ила нажот бердик ва оятларимизни ёлғонга чиқарганларнинг кетларини уздик. Улар мўмин эмас эдилар.",159,8],["وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَ[n[ـٰ]لِ[f:4805[حًا‌ۗ ق]َالَ يَ[n[ـٰ]قَوْمِ [h:4768[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ مَا لَك[w:556[ُم م]ِّنْ إِلَ[n[ـٰ]هٍ غَيْرُهُ[n[ۥ]‌ۖ قَ[q:298[دْ] ج[o[َا]ٓءَتْك[c:4806[ُم ب]َيِّنَ[a:4546[ةٌ م]ّ[u:243[ِن ر]َّبِّكُمْ‌ۖ هَ[n[ـٰ]ذِه[n[ِۦ] نَاقَةُ [h:4807[ٱ]للَّهِ لَكُمْ ءَايَ[f:4808[ةً‌ۖ ف]َذَرُوهَا تَأْكُلْ ف[o[ِىٓ] أَرْضِ [h:4809[ٱ]للَّهِ‌ۖ وَلَا تَمَسُّوهَا بِس[o[ُو]ٓ[f:4810[ءٍ ف]َيَأْخُذَكُمْ عَذَابٌ أَل[p[ِي]مٌ","Ва Самудга ўз биродари Солиҳни. У: «Эй қавмим, Аллоҳга ибодат қилинглар. Сизларга Ундан ўзга илоҳ йўқ. Сизга Роббингиздан ҳужжат келди. Мана бу Аллоҳнинг туяси сизларга оят-белгидир. Уни Аллоҳнинг ерида тек қўйинглар. Унга ёмонлик етказманглар. Яна сизни аламли азоб тутмасин-а!",159,8],["وَ[h:9999[ٱ]ذْكُر[o[ُوٓ][s[اْ] إِذْ جَعَلَكُمْ خُلَف[o[َا]ٓءَ م[i:146[ِنۢ ب]َعْدِ عَا[a:4811[دٍ و]َبَوَّأَكُمْ فِى [h:44[ٱ]لْأَرْضِ تَتَّخِذُونَ مِ[f:4812[ن س]ُهُولِهَا قُصُو[a:4813[رًا و]َتَنْحِتُونَ [h:4814[ٱ]لْجِبَالَ بُيُو[f:4815[تًا‌ۖ ف]َ[h:1091[ٱ]ذْكُر[o[ُوٓ][s[اْ] ءَال[o[َا]ٓءَ [h:4790[ٱ]للَّهِ وَلَا تَعْثَوْ[s[اْ] فِى [h:44[ٱ]لْأَرْضِ مُفْسِد[p[ِي]نَ","Ва сизларни Оддан кейин халифа қилганини ва сизга ер юзида имкон бериб, текисликларида қасрлар қуриб, тоғлардан уйлар ўйганларингизни эсланг. Аллоҳнинг неъматларини эсланг ва ер юзида фасод-ла бузғунчилик қилманг!» деди.",160,8],["قَالَ [h:4769[ٱ]لْمَلَأُ [h:4783[ٱ]لَّذِينَ [h:4816[ٱ]سْتَكْبَرُو[s[اْ] مِ[f:4770[ن ق]َوْمِه[n[ِۦ] لِلَّذِينَ [h:4817[ٱ]سْتُضْعِفُو[s[اْ] لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَ[g[نّ]َ صَ[n[ـٰ]لِ[a:4818[حًا م]ُّرْسَ[a:4819[لٌ م]ّ[u:192[ِن ر]َّبِّه[n[ِۦ]‌ۚ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا بِم[o[َآ] أُرْسِلَ بِه[n[ِۦ] مُؤْمِن[p[ُو]نَ","Унинг қавмидан мутакаббир бўлган зодагонлар, заифҳол бўлганлардан иймон келтирганларига: «Солиҳни Роббидан Пайғамбар қилиб юборилган, деб билмоқдамисиз?!» дедилар. Улар: «Албатта, биз у ила юборилган нарсага иймон келтирувчилармиз» дедилар.",160,8],["قَالَ [h:590[ٱ]لَّذِينَ [h:4816[ٱ]سْتَكْبَر[o[ُوٓ][s[اْ] إِ[g[نّ]َا بِ[h:315[ٱ]لَّذ[o[ِىٓ] ءَامَ[f:703[نت][c:704[ُم ب]ِه[n[ِۦ] كَ[n[ـٰ]فِر[p[ُو]نَ","Мутакаббир бўлганлар: «Албатта, биз сиз иймон келтирганга кофирмиз», дедилар.",160,8],["فَعَقَرُو[s[اْ] [h:4820[ٱ][l[ل][g[نّ]َاقَةَ وَعَتَوْ[s[اْ] عَنْ أَمْرِ رَبِّهِمْ وَقَالُو[s[اْ] يَ[n[ـٰ]صَ[n[ـٰ]لِحُ [h:4821[ٱ]ئْتِنَا بِمَا تَعِدُن[o[َآ] إِ[f:4792[ن ك]ُ[f:735[نت]َ مِنَ [h:4822[ٱ]لْمُرْسَل[p[ِي]نَ","Бас, туяни сўйдилар, Роббилари амрида тажовузкорлик қилишди ва: «Эй Солиҳ, агар ростгўйлардан бўлсанг, бизга ваъда қилаётган нарсангни келтир!» дедилар.",160,8],["فَأَخَذَتْهُمُ [h:4823[ٱ][l[ل]رَّ[q:4824[جْ]فَةُ فَأَصْبَحُو[s[اْ] فِى دَارِهِمْ جَ[n[ـٰ]ثِم[p[ِي]نَ","Бас, уларни шиддатли зилзила олди ва жойларида ўтириб қолдилар.",160,8],["فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَ[n[ـٰ]قَوْمِ لَقَ[q:2389[دْ] أَ[q:4825[بْ]لَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَ[n[ـٰ]ك[u:46[ِن ل]َّا تُحِبُّونَ [h:4826[ٱ][l[ل][g[نّ]َ[n[ـٰ]صِح[p[ِي]نَ","Кейин, У улардан юз ўгирди ва: «Эй қавмим, батаҳқиқ, мен сизга Роббимнинг юборганини етказдим ва насиҳат қилдим. Лекин сиз насиҳат қилувчиларни севмас экансиз», деди.",160,8],["وَلُوطًا إِذْ قَالَ لِقَوْمِه[o[ِۦٓ] أَتَأْتُونَ [h:4827[ٱ]لْفَ[n[ـٰ]حِشَةَ مَا سَبَقَك[c:4828[ُم ب]ِهَا مِنْ أَحَ[a:4829[دٍ م]ِّنَ [h:3475[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Ва Лутни. Унинг ўз қавмига: «Сиздан олдин оламларда ҳеч ким қилмаган фоҳиша ишни қиласизларми?!",160,8],["إِ[g[نّ]َكُمْ لَتَأْتُونَ [h:4830[ٱ][l[ل]رِّجَالَ شَهْوَ[a:4831[ةً م]ِّ[f:107[ن د]ُونِ [h:4832[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ‌ۚ بَلْ أَ[f:428[نت]ُمْ قَوْ[a:4833[مٌ م]ُّسْرِف[p[ُو]نَ","Албатта, сизлар аёлларни қўйиб, эркакларга шаҳват ила яқинлик қилмоқдасизлар. Йўқ! Сизлар исрофчи қавмсиз!» деганини эсла.",160,8],["وَمَا كَانَ جَوَابَ قَوْمِه[o[ِۦٓ] إِلّ[o[َآ] أَ[f:2304[ن ق]َال[o[ُوٓ][s[اْ] أَخْرِجُوه[w:4834[ُم م]ِّ[f:4835[ن ق]َرْيَتِكُمْ‌ۖ إِ[g[نّ]َهُمْ أُنَا[a:4836[سٌ ي]َتَطَهَّر[p[ُو]نَ","Қавмнинг жавоби: «Уларни қишлоғингиздан чиқариб юборинг, чунки улар жуда ҳам покиза бўлаверадиган одамлар экан», дейишларидан бошқа нарса бўлмади.",161,8],["فَأَ[f:4779[نج]َيْنَ[n[ـٰ]هُ وَأَهْلَهُ[o[ۥٓ] إِلَّا [h:4837[ٱ]مْرَأَتَهُ[n[ۥ] كَانَتْ مِنَ [h:4838[ٱ]لْغَ[n[ـٰ]بِر[p[ِي]نَ","Бас, унга ва аҳлига нажот бердик. Магар хотини ҳалок бўлгувчилардан бўлди.",161,8],["وَأَمْطَرْنَا عَلَيْه[w:4839[ِم م]َّطَ[f:4840[رًا‌ۖ ف]َ[h:1513[ٱ][f:1513[نظ]ُرْ كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:4841[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","Ва Биз уларнинг устидан «ёмғир» ёғдирдик. Жинояткорларнинг оқибати қандай бўлганига назар сол!",161,8],["وَإِلَىٰ مَ[q:4842[دْ]يَنَ أَخَاهُمْ شُعَيْ[f:4843[بًا‌ۗ ق]َالَ يَ[n[ـٰ]قَوْمِ [h:4768[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ مَا لَك[w:556[ُم م]ِّنْ إِلَ[n[ـٰ]هٍ غَيْرُهُ[n[ۥ]‌ۖ قَ[q:298[دْ] ج[o[َا]ٓءَتْك[c:4806[ُم ب]َيِّنَ[a:4546[ةٌ م]ّ[u:243[ِن ر]َّبِّكُمْ‌ۖ فَأَوْفُو[s[اْ] [h:4844[ٱ]لْكَيْلَ وَ[h:4528[ٱ]لْمِيزَانَ وَلَا تَ[q:4845[بْ]خَسُو[s[اْ] [h:4846[ٱ][l[ل][g[نّ]َاسَ أَشْي[o[َا]ٓءَهُمْ وَلَا تُفْسِدُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ بَعْدَ إِصْلَ[n[ـٰ]حِهَا‌ۚ ذ[n[َٲ]لِكُمْ خَيْ[u:263[رٌ ل]َّكُمْ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Ва Мадянга ўз биродарлари Шуайбни. У: «Эй қавмим, Аллоҳга ибодат қилинг. Сизга Ундан ўзга илоҳ йўқ. Батаҳқиқ, сизга Роббингиздан ҳужжат келди. Бас, ўлчов ва тарозуни тўлиқ адо этинг, одамларнинг нарсаларидан камитиб қолманг ва ер юзида унинг ислоҳидан кейин бузғунчилик қилманг. Агар мўмин бўлсангиз, шундай қилмоғингиз ўзингиз учун яхшидир.",161,8],["وَلَا تَ[q:3215[قْ]عُدُو[s[اْ] بِكُلِّ صِر[n[َٲ][f:4847[طٍ ت]ُوعِدُونَ وَتَصُدُّونَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ مَنْ ءَامَنَ بِه[n[ِۦ] وَتَ[q:4848[بْ]غُونَهَا عِوَ[a:4849[جًا‌ۚ و]َ[h:335[ٱ]ذْكُر[o[ُوٓ][s[اْ] إِذْ كُ[f:100[نت]ُمْ قَلِيل[f:4850[اً ف]َكَثَّرَكُمْ‌ۖ وَ[h:4851[ٱ][f:4851[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:4852[ٱ]لْمُفْسِد[p[ِي]نَ","Ҳар кўчада ўтириб олиб қўрқитманг. Аллоҳнинг йўлидан Унга иймон келтирганларни тўсманг ва уни эгри бўлишини истаманг. Оз бўлган чоғингизда сизни кўпайтириб қўйганини эсланг. Бузғунчиларнинг оқибати қандай бўлганига назар солинг.",161,8],["وَإِ[f:1649[ن ك]َانَ ط[o[َا]ٓئِفَ[a:4853[ةٌ م]ِّ[f:344[نك]ُمْ ءَامَنُو[s[اْ] بِ[h:315[ٱ]لَّذ[o[ِىٓ] أُرْسِلْتُ بِه[n[ِۦ] وَط[o[َا]ٓئِفَ[u:4854[ةٌ ل]َّمْ يُؤْمِنُو[s[اْ] فَ[h:4855[ٱ]صْبِرُو[s[اْ] حَتَّىٰ يَحْكُمَ [h:4856[ٱ]للَّهُ بَيْنَنَا‌ۚ وَهُوَ خَيْرُ [h:4857[ٱ]لْحَ[n[ـٰ]كِم[p[ِي]نَ","Агар сиздан бир тоифа мен ила юборилган нарсага иймон келтирган ва бошқа тоифа иймон келтирмаган бўлса, бас, Аллоҳ орамизда ҳукм қилгунча сабр қилинглар. У ҳукм қилувчиларнинг яхшисидир», деди.",161,8],["۞ قَالَ [h:4769[ٱ]لْمَلَأُ [h:4783[ٱ]لَّذِينَ [h:4816[ٱ]سْتَكْبَرُو[s[اْ] مِ[f:4770[ن ق]َوْمِه[n[ِۦ] لَنُخْرِجَ[g[نّ]َكَ يَ[n[ـٰ]شُعَيْبُ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مَعَكَ مِ[f:4858[ن ق]َرْيَتِن[o[َآ] أَوْ لَتَعُودُ[g[نّ]َ فِى مِلَّتِنَا‌ۚ قَالَ أَوَلَوْ كُ[g[نّ]َا كَ[n[ـٰ]رِه[p[ِي]نَ","Унинг қавмидан мутакаббир бўлган зодагонлар: «Эй Шуайб, ёки, албатта, сени ва сен билан бирга иймон келтирганларни ўз қишлоғимиздан чиқарамиз, ёки ўз миллатимизга қайтасизлар», дедилар. У: «Гарчи ёмон кўрувчи бўлсак ҳам-а?!",162,9],["قَدِ [h:4859[ٱ]فْتَرَيْنَا عَلَى [h:412[ٱ]للَّهِ كَذِبًا إِنْ عُ[q:4860[دْ]نَا فِى مِلَّتِك[c:4861[ُم ب]َعْدَ إِذْ نَجَّ[n[ـٰ]نَا [h:4862[ٱ]للَّهُ مِنْهَا‌ۚ وَمَا يَكُونُ لَن[o[َآ] أ[a:4863[َن ن]َّعُودَ فِيه[o[َآ] إِلّ[o[َآ] أ[a:4201[َن ي]َش[o[َا]ٓءَ [h:4334[ٱ]للَّهُ رَبُّنَا‌ۚ وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا‌ۚ عَلَى [h:412[ٱ]للَّهِ تَوَكَّلْنَا‌ۚ رَبَّنَا [h:4864[ٱ]فْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِ[h:370[ٱ]لْحَقِّ وَأَ[f:3893[نت]َ خَيْرُ [h:4865[ٱ]لْفَ[n[ـٰ]تِح[p[ِي]نَ","Агар сизнинг миллатингизга Аллоҳ бизга ундан нажот бергандан сўнг қайтсак, батаҳқиқ, Аллоҳга нисбатан ёлғон тўқиган бўламиз. Биз учун унга қайтиш мутлақо мумкин эмас, магар Роббимиз–Аллоҳ хоҳласагина. Роббимиз ҳамма нарсани ўз илми ила қамраб олгандир. Аллоҳга таваккал қилдик. Эй Роббимиз, биз билан қавмимизнинг орамизни ҳақ ила очгин. Сен очувчиларнинг яхшисидирсан», деди.",162,9],["وَقَالَ [h:4866[ٱ]لْمَلَأُ [h:4783[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِ[f:4770[ن ق]َوْمِه[n[ِۦ] لَئِنِ [h:4867[ٱ]تَّبَعْتُمْ شُعَيْبًا إِ[g[نّ]َكُمْ إِ[u:4868[ذًا ل]َّخَ[n[ـٰ]سِر[p[ُو]نَ","Унинг қавмидан бўлган, куфр келтирган зодагонлар: «Агар Шуайбга эргашсангиз, у ҳолда, албатта, зиён кўрувчидирсиз», дедилар.",162,9],["فَأَخَذَتْهُمُ [h:4823[ٱ][l[ل]رَّ[q:4824[جْ]فَةُ فَأَصْبَحُو[s[اْ] فِى دَارِهِمْ جَ[n[ـٰ]ثِم[p[ِي]نَ","Бас, уларни шиддатли зилзила олди ва жойларида ўтириб қолдилар.",162,9],["ٱلَّذِينَ كَذَّبُو[s[اْ] شُعَيْ[f:4869[بًا ك]َأ[u:2914[َن ل]َّمْ يَغْنَوْ[s[اْ] فِيهَا‌ۚ [h:4870[ٱ]لَّذِينَ كَذَّبُو[s[اْ] شُعَيْ[f:4871[بًا ك]َانُو[s[اْ] هُمُ [h:4872[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","Шуайбни ёлғончига чиқарганлар худди у ерда яшамагандек бўлдилар. Шуайбни ёлғончига чиқарганлар, ўшалар зиён кўрувчилар бўлдилар.",162,9],["فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَ[n[ـٰ]قَوْمِ لَقَ[q:2389[دْ] أَ[q:4825[بْ]لَغْتُكُمْ رِسَ[n[ـٰ]لَ[n[ـٰ]تِ رَبِّى وَنَصَحْتُ لَكُمْ‌ۖ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْ[f:4873[مٍ ك]َ[n[ـٰ]فِر[p[ِي]نَ","Кейин У улардан юз ўгирди ва: «Эй қавмим, батаҳқиқ, сизга Роббимнинг юборганларини етказган эдим ҳамда сизга насиҳат қилган эдим. Қандай қилиб кофир қавмларга қайғурай», деди.",162,9],["وَم[o[َآ] أَرْسَلْنَا فِى قَرْيَ[a:4874[ةٍ م]ّ[a:2299[ِن ن]َّبِىٍّ إِلّ[o[َآ] أَخَذْن[o[َآ] أَهْلَهَا بِ[h:4043[ٱ]لْبَأْس[o[َا]ٓءِ وَ[h:920[ٱ][l[ل]ضَّرّ[o[َا]ٓءِ لَعَلَّهُمْ يَضَّرَّع[p[ُو]نَ","Қайси бир қишлоққа Пайғамбар юборсак, албатта, унинг аҳлини тазарруъ қилишлари учун зарарлар ва мусибатлар ила тутганмиз.",162,9],["ثُ[g[مّ]َ بَدَّلْنَا مَكَانَ [h:4875[ٱ][l[ل]سَّيِّئَةِ [h:4876[ٱ]لْحَسَنَةَ حَتَّىٰ عَفَو[s[اْ] وَّقَالُو[s[اْ] قَ[q:298[دْ] مَسَّ ءَاب[o[َا]ٓءَنَا [h:4877[ٱ][l[ل]ضَّرّ[o[َا]ٓءُ وَ[h:4878[ٱ][l[ل]سَّرّ[o[َا]ٓءُ فَأَخَذْنَ[n[ـٰ]ه[c:4879[ُم ب]َغْتَ[a:4880[ةً و]َهُمْ لَا يَشْعُر[p[ُو]نَ","Сўнгра ёмонликни яхшиликга алмаштирганмиз. Токи кўпайишиб ва «ота-боболаримизга ҳам қийинчилик ва хурсандчилик етган эди», деганларида, уларни ўзларига сездирмай тўсатдан тутганмиз.",162,9],["وَلَوْ أَ[g[نّ]َ أَهْلَ [h:4881[ٱ]لْقُرَ[o[ىٰٓ] ءَامَنُو[s[اْ] وَ[h:538[ٱ]تَّقَوْ[s[اْ] لَفَتَحْنَا عَلَيْه[c:4882[ِم ب]َرَكَ[n[ـٰ][a:4883[تٍ م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِ وَلَ[n[ـٰ]كِ[f:4884[ن ك]َذَّبُو[s[اْ] فَأَخَذْنَ[n[ـٰ]ه[c:4885[ُم ب]ِمَا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Агар қишлоқлар аҳллари иймон келтирганларида ва тақво қилганларида эди, Биз, албатта, уларга осмону ердан баракотларни очиб қўяр эдик. Лекин улар ёлғонга чиқардилар, бас, уларни қилган касблари туфайли тутдик.",163,9],["أَفَأَمِنَ أَهْلُ [h:4886[ٱ]لْقُرَ[o[ىٰٓ] أ[a:4887[َن ي]َأْتِيَه[c:4888[ُم ب]َأْسُنَا بَيَ[n[ـٰ][a:4889[تًا و]َهُمْ ن[o[َا]ٓئِم[p[ُو]نَ","Қишлоқлар аҳли уларга Бизнинг бало-қазойимиз тунда, ухлаётган ҳолларида келишидан хотиржаммилар?!",163,9],["أَوَأَمِنَ أَهْلُ [h:4886[ٱ]لْقُرَ[o[ىٰٓ] أ[a:4887[َن ي]َأْتِيَه[c:4888[ُم ب]َأْسُنَا ضُ[a:4890[حًى و]َهُمْ يَلْعَب[p[ُو]نَ","Қишлоқлар аҳли уларга Бизнинг бало-қазойимиз чошгоҳда, ўйнаётган ҳолларда келишидан хотиржаммилар?!",163,9],["أَفَأَمِنُو[s[اْ] مَكْرَ [h:4891[ٱ]للَّهِ‌ۚ فَلَا يَأْمَنُ مَكْرَ [h:4891[ٱ]للَّهِ إِلَّا [h:4061[ٱ]لْقَوْمُ [h:4892[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","Аллоҳнинг макридан хотиржам бўлдиларми?! Аллоҳнинг макридан фақат зиён кўрувчи қавмларгина хотиржам бўларлар.",163,9],["أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ [h:4893[ٱ]لْأَرْضَ م[i:146[ِنۢ ب]َعْدِ أَهْلِه[o[َآ] أ[u:4894[َن ل]َّوْ نَش[o[َا]ٓءُ أَصَ[q:4895[بْ]نَ[n[ـٰ]ه[c:4896[ُم ب]ِذُنُوبِهِمْ‌ۚ وَنَ[q:4897[طْ]بَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَع[p[ُو]نَ","Ерга унинг аҳлидан кейин меросхўр бўлганларга, агар хоҳласак, гуноҳлари туфайли уларга мусибат етказишимиз ва қалбларига муҳр босиб, эшитмайдиган қилиб қўйишимиз аён бўлмадими?!",163,9],["تِلْكَ [h:4898[ٱ]لْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَ[i:4899[نۢب][o[َا]ٓئِهَا‌ۚ وَلَقَ[q:341[دْ] ج[o[َا]ٓءَتْهُمْ رُسُلُه[c:4900[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ فَمَا كَانُو[s[اْ] لِيُؤْمِنُو[s[اْ] بِمَا كَذَّبُو[s[اْ] مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۚ كَذ[n[َٲ]لِكَ يَ[q:4901[طْ]بَعُ [h:4902[ٱ]للَّهُ عَلَىٰ قُلُوبِ [h:4903[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Биз сенга ана ўша қишлоқларнинг хабарларини қисқа қилиб айтиб бермоқдамиз. Батаҳқиқ, уларга Пайғамбарлари очиқ-ойдин ҳужжатлар билан келдилар. Аммо улар олдин ёлғонга чиқарган нарсаларига иймон келтирмадилар. Аллоҳ шундай қилиб кофирлар қалбига муҳр босди.",163,9],["وَمَا وَجَ[q:3834[دْ]نَا لِأَكْثَرِه[w:4904[ِم م]ِّنْ عَهْ[a:4905[دٍ‌ۖ و]َإ[a:4906[ِن و]َجَ[q:3834[دْ]ن[o[َآ] أَكْثَرَهُمْ لَفَ[n[ـٰ]سِق[p[ِي]نَ","Уларнинг кўпларида аҳдга вафо кўрмадик. Агар уларнинг кўпларини топсак ҳам, фосиқликда топдик.",163,9],["ثُ[g[مّ]َ بَعَثْنَا م[i:1453[ِنۢ ب]َعْدِه[w:4907[ِم م]ُّوسَىٰ بِـَٔـايَ[n[ـٰ]تِن[o[َآ] إِلَىٰ فِرْعَوْنَ وَمَلَإِ[s[يْ]ه[n[ِۦ] فَظَلَمُو[s[اْ] بِهَا‌ۖ فَ[h:1513[ٱ][f:1513[نظ]ُرْ كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:4852[ٱ]لْمُفْسِد[p[ِي]نَ","Сўнгра уларнинг ортидан Мусони Ўз оятларимиз ила Фиръавн ва унинг зодагонларига юбордик. Бас, уларга зулм қилдилар. Бузғунчиларнинг оқибати қандай бўлишига назар сол.",163,9],["وَقَالَ مُوسَىٰ يَ[n[ـٰ]فِرْعَوْنُ إِ[g[نّ]ِى رَسُو[a:521[لٌ م]ّ[u:4772[ِن ر]َّبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Мусо: «Эй Фиръавн, албатта, мен оламларнинг Роббидан Пайғамбарман.",163,9],["حَقِيقٌ عَلَ[o[ىٰٓ] أ[u:4908[َن ل]ّ[o[َآ] أَقُولَ عَلَى [h:412[ٱ]للَّهِ إِلَّا [h:3304[ٱ]لْحَقَّ‌ۚ قَ[q:298[دْ] جِئْتُك[c:4909[ُم ب]ِبَيِّنَ[a:4910[ةٍ م]ّ[u:243[ِن ر]َّبِّكُمْ فَأَرْسِلْ مَعِىَ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓء[p[ِي]لَ","Менга Аллоҳ ҳақида ҳақдан бошқани айтмаслик лозимдир. Батаҳқиқ, мен сизларга Роббингиздан очиқ-ойдин ҳужжат келтирдим. Мен ила Бани Исроилни қўйиб юбор», деди.",164,9],["قَالَ إِ[f:4792[ن ك]ُ[f:735[نت]َ جِئْتَ بِـَٔـايَ[f:4911[ةٍ ف]َأْتِ بِه[o[َآ] إِ[f:4792[ن ك]ُ[f:735[نت]َ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","У: «Агар оят-мўъжиза келтирган бўлсанг, ростгўйлардан бўлсанг, келтир уни», деди.",164,9],["فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَا[a:4912[نٌ م]ُّب[p[ِي]نٌ","Асосини ташлаган эди... баногоҳ у аниқ аждар бўлди.",164,9],["وَنَزَعَ يَدَهُ[n[ۥ] فَإِذَا هِىَ بَيْض[o[َا]ٓءُ لِل[g[نّ]َ[n[ـٰ]ظِر[p[ِي]نَ","Ва қўлини чиқарган эди... баногоҳ у назар солувчиларга оппоқ бўлиб кўринди.",164,9],["قَالَ [h:4769[ٱ]لْمَلَأُ مِ[f:4913[ن ق]َوْمِ فِرْعَوْنَ إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَسَ[n[ـٰ]حِرٌ عَل[p[ِي]مٌ","Фиръавн қавмидан бўлган зодагонлар: «Албатта, бу билимдон сеҳргардир!",164,9],["يُرِيدُ أ[a:4914[َن ي]ُخْرِجَك[w:4915[ُم م]ِّنْ أَرْضِكُمْ‌ۖ فَمَاذَا تَأْمُر[p[ُو]نَ","Сизларни ерингиздан чиқаришни хоҳлайди. Бас, нимага амр қиласизлар?» дедилар.",164,9],["قَال[o[ُوٓ][s[اْ] أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى [h:4916[ٱ]لْمَد[o[َا]ٓئِنِ حَ[n[ـٰ]شِر[p[ِي]نَ","Улар: «Уни ва акасини қўйиб тургин-да, шаҳарларга тўпловчиларни юбор.",164,9],["يَأْتُوكَ بِكُلِّ سَ[n[ـٰ]حِرٍ عَل[p[ِي]مٍ","Ҳамма билимдон сеҳргарларни сенга олиб келсинлар», дедилар.",164,9],["وَج[o[َا]ٓءَ [h:4917[ٱ][l[ل]سَّحَرَةُ فِرْعَوْنَ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َ لَنَا لَأَ[q:4918[جْ]رًا إِ[f:4919[ن ك]ُ[g[نّ]َا نَحْنُ [h:4920[ٱ]لْغَ[n[ـٰ]لِب[p[ِي]نَ","Сеҳргарлар Фиръавнга келиб: «Агар биз ғолиб бўлсак, албатта, мукофот олсак керак?» дедилар.",164,9],["قَالَ نَعَمْ وَإِ[g[نّ]َكُمْ لَمِنَ [h:4921[ٱ]لْمُقَرَّب[p[ِي]نَ","У: «Ҳа. Ва, албатта, менинг яқин кишиларимдан бўлурсизлар», деди.",164,9],["قَالُو[s[اْ] يَ[n[ـٰ]مُوسَ[o[ىٰٓ] إِ[g[مّ][o[َآ] أَ[f:4922[ن ت]ُلْقِىَ وَإِ[g[مّ][o[َآ] أ[a:4923[َن ن]َّكُونَ نَحْنُ [h:4924[ٱ]لْمُلْق[p[ِي]نَ","Улар: «Эй Мусо, ёки сен ташла, ёки биз ташловчи бўлайлик», дедилар.",164,9],["قَالَ أَلْقُو[s[اْ‌ۖ] فَلَ[g[مّ][o[َآ] أَلْقَوْ[s[اْ] سَحَر[o[ُوٓ][s[اْ] أَعْيُنَ [h:4925[ٱ][l[ل][g[نّ]َاسِ وَ[h:4926[ٱ]سْتَرْهَبُوهُمْ وَج[o[َا]ٓءُو بِسِحْرٍ عَظ[p[ِي]مٍ","У: «Сизлар ташланглар», деди. Улар ташлаганларида, одамларнинг кўзини сеҳрладилар, қўрқитдилар ва зўр сеҳр кўрсатдилар.",164,9],["۞ وَأَوْحَيْن[o[َآ] إِلَىٰ مُوسَ[o[ىٰٓ] أَنْ أَلْقِ عَصَاكَ‌ۖ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِك[p[ُو]نَ","Биз Мусога: «Асонгни ташла», деб ваҳий юбордик. Бирдан у улар уйдираётган нарсани юта бошлади.",164,9],["فَوَقَعَ [h:4927[ٱ]لْحَقُّ وَبَطَلَ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Бас, ҳақ қарор топди ва уларнинг қилаётганлари ботил бўлди.",164,9],["فَغُلِبُو[s[اْ] هُنَالِكَ وَ[h:4928[ٱ][f:4928[نق]َلَبُو[s[اْ] صَ[n[ـٰ]غِر[p[ِي]نَ","Ўша ерда енгилдилар ва беобрў бўлдилар.",164,9],["وَأُلْقِىَ [h:4929[ٱ][l[ل]سَّحَرَةُ سَ[n[ـٰ]جِد[p[ِي]نَ","Ва сеҳргарлар саждага ташланиб:",164,9],["قَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا بِرَبِّ [h:4930[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","«Оламларнинг Роббига.",165,9],["رَبِّ مُوسَىٰ وَهَ[n[ـٰ]ر[p[ُو]نَ","Мусо ва Ҳоруннинг Роббига иймон келтирдик», дедилар.",165,9],["قَالَ فِرْعَوْنُ ءَامَ[f:703[نت][c:704[ُم ب]ِه[n[ِۦ] قَ[q:3282[بْ]لَ أَنْ ءَاذَنَ لَكُمْ‌ۖ إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَمَكْ[a:4931[رٌ م]َّكَرْتُمُوهُ فِى [h:4932[ٱ]لْمَدِينَةِ لِتُخْرِجُو[s[اْ] مِنْه[o[َآ] أَهْلَهَا‌ۖ فَسَوْفَ تَعْلَم[p[ُو]نَ","Фиръавн: «Мен сизга изн бермай туриб унга иймон келтирдингизми?! Албатта, бу сизнинг шаҳардан унинг аҳлини чиқариш учун қилган макрингиздир. Ҳали биласиз.",165,9],["لَأُقَطِّعَ[g[نّ]َ أَيْدِيَكُمْ وَأَرْجُلَك[w:4933[ُم م]ِّنْ خِلَ[n[ـٰ][f:4934[فٍ ث]ُ[g[مّ]َ لَأُصَلِّبَ[g[نّ]َكُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Албатта, оёқ-қўлларингизни қарама-қарши томонидан кесаман ва ҳаммангизни осаман», деди.",165,9],["قَال[o[ُوٓ][s[اْ] إِ[g[نّ][o[َآ] إِلَىٰ رَبِّنَا مُ[f:4935[نق]َلِب[p[ُو]نَ","Улар: «Албатта, биз Роббимизга қайтгувчимиз.",165,9],["وَمَا تَ[f:4936[نق]ِمُ مِ[g[نّ][o[َآ] إِلّ[o[َآ] أَنْ ءَامَ[g[نّ]َا بِـَٔـايَ[n[ـٰ]تِ رَبِّنَا لَ[g[مّ]َا ج[o[َا]ٓءَتْنَا‌ۚ رَبَّن[o[َآ] أَفْرِغْ عَلَيْنَا صَ[q:1427[بْ][a:4937[رًا و]َتَوَفَّنَا مُسْلِم[p[ِي]نَ","Сен биздан фақат Роббимизнинг оятлари келганда уларга иймон келтирганимиз учунгина ўч олмоқдасан! Эй Роббимиз, устимиздан сабр тўккин ва мусулмон ҳолимизда вафот эттиргин», дедилар.",165,9],["وَقَالَ [h:4866[ٱ]لْمَلَأُ مِ[f:4913[ن ق]َوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُ[n[ۥ] لِيُفْسِدُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ‌ۚ قَالَ سَنُقَتِّلُ أَ[q:767[بْ]ن[o[َا]ٓءَهُمْ وَنَسْتَحْى[n[ِۦ] نِس[o[َا]ٓءَهُمْ وَإِ[g[نّ]َا فَوْقَهُمْ قَ[n[ـٰ]هِر[p[ُو]نَ","Фиръавн қавмидан бўлган зодагонлар: «Сени ва худоларингни тарк қилса ҳам, Мусо ва унинг қавмини ер юзида бузғунчилик қилишларига йўл қўйиб берасанми?» дедилар. У: «Ўғилларини ўлдирамиз ва аёлларини тирик қолдирамиз ва, албатта, биз улар устидан қаҳр ўтказувчимиз», деди.",165,9],["قَالَ مُوسَىٰ لِقَوْمِهِ [h:4938[ٱ]سْتَعِينُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَ[h:4939[ٱ]صْبِر[o[ُوٓ[s[اْ]‌ۖ] إِ[g[نّ]َ [h:4940[ٱ]لْأَرْضَ لِلَّهِ يُورِثُهَا م[a:476[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[n[ِۦ]‌ۖ وَ[h:4941[ٱ]لْعَ[n[ـٰ]قِبَةُ لِلْمُتَّق[p[ِي]نَ","Мусо ўз қавмига: «Аллоҳдан ёрдам сўранглар ва сабр қилинглар. Ер Аллоҳники, уни бандаларидан кимни хоҳласа, ўшанга мерос қилиб беради. Ва оқибат тақводорларникидир», деди.",165,9],["قَال[o[ُوٓ][s[اْ] أُوذِينَا مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أَ[f:4942[ن ت]َأْتِيَنَا وَم[i:4943[ِنۢ ب]َعْدِ مَا جِئْتَنَا‌ۚ قَالَ عَسَىٰ رَبُّكُمْ أ[a:3450[َن ي]ُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى [h:44[ٱ]لْأَرْضِ فَيَ[f:4944[نظ]ُرَ كَيْفَ تَعْمَل[p[ُو]نَ","Улар: «Сен бизга келмасингдан олдин ҳам, келганингдан кейин ҳам озор тортдик», дедилар. У: «Шоядки Роббингиз душманларингизни ҳалок этиб, сизларни ер юзига халифа қилиб, қандай амал қилишингизга назар солса», деди.",165,9],["وَلَقَ[q:341[دْ] أَخَذْن[o[َآ] ءَالَ فِرْعَوْنَ بِ[h:4945[ٱ][l[ل]سِّنِينَ وَنَ[q:796[قْ][a:797[صٍ م]ِّنَ [h:93[ٱ][l[ل]ثَّمَر[n[َٲ]تِ لَعَلَّهُمْ يَذَّكَّر[p[ُو]نَ","Биз Фиръавн аҳлини, шояд эсласалар, деб йиллар ва мевалар танқислиги ила тутдик.",165,9],["فَإِذَا ج[o[َا]ٓءَتْهُمُ [h:4946[ٱ]لْحَسَنَةُ قَالُو[s[اْ] لَنَا هَ[n[ـٰ]ذِه[n[ِۦ]‌ۖ وَإِ[f:2950[ن ت]ُصِ[q:2951[بْ]هُمْ سَيِّئَ[a:4947[ةٌ ي]َطَّيَّرُو[s[اْ] بِمُوسَىٰ وَم[a:4948[َن م]َّعَهُ[o[ۥٓ‌ۗ] أَل[o[َآ] إِ[g[نّ]َمَا طَ[o[ـٰٓ]ئِرُهُمْ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَعْلَم[p[ُو]نَ","Улар ўзларига яхшилик етганда: «Бунга биз ҳақдормиз», дедилар. Агар уларга ёмонлик етса, Мусо ва у билан бирга бўлганлардан шумландилар. Огоҳ бўлсинларким, уларнинг шумликлари Аллоҳнинг ҳузуридан бошқа жойда эмас. Лекин кўплари билмайдилар.",166,9],["وَقَالُو[s[اْ] مَهْمَا تَأْتِنَا بِه[n[ِۦ] مِنْ ءَايَ[u:4949[ةٍ ل]ِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِن[p[ِي]نَ","Улар: «Ҳар қанча оят келтириб бизни сеҳрламоқчи бўлсанг ҳам, биз сенга иймон келтиргувчи эмасмиз», дедилар.",166,9],["فَأَرْسَلْنَا عَلَيْهِمُ [h:4950[ٱ][l[ل]طُّوفَانَ وَ[h:4951[ٱ]لْجَرَادَ وَ[h:4952[ٱ]لْقُ[g[مّ]َلَ وَ[h:4953[ٱ][l[ل]ضَّفَادِعَ وَ[h:883[ٱ][l[ل]دَّمَ ءَايَ[n[ـٰ][a:4954[تٍ م]ُّفَصَّلَ[n[ـٰ][f:4955[تٍ ف]َ[h:4956[ٱ]سْتَكْبَرُو[s[اْ] وَكَانُو[s[اْ] قَوْ[a:4957[مًا م]ُّ[q:4958[جْ]رِم[p[ِي]نَ","Бас, уларнинг устидан тўфон, чигиртка, мита, бақа ва қонларни очиқ-ойдин ва муфассал белгилар қилиб юбордик. Бас, улар мутакаббирлик қилдилар ва жиноятчи қавм бўлдилар.",166,9],["وَلَ[g[مّ]َا وَقَعَ عَلَيْهِمُ [h:4959[ٱ][l[ل]رِّ[q:4960[جْ]زُ قَالُو[s[اْ] يَ[n[ـٰ]مُوسَى [h:4961[ٱ][q:354[دْ]عُ لَنَا رَبَّكَ بِمَا عَهِدَ عِ[f:4962[ند]َكَ‌ۖ لَئِ[f:4963[ن ك]َشَفْتَ عَ[g[نّ]َا [h:4964[ٱ][l[ل]رِّ[q:4965[جْ]زَ لَنُؤْمِنَ[g[نّ]َ لَكَ وَلَنُرْسِلَ[g[نّ]َ مَعَكَ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓء[p[ِي]لَ","Қачонки устиларига азоб тушса: «Эй Мусо, сенга берган аҳд ҳурмати, Роббингга дуо қил, агар биздан азобни кўтарсанг, албатта, сенга иймон келтирамиз ва Бани Исроилни сен билан қўйиб юборамиз», дер эдилар.",166,9],["فَلَ[g[مّ]َا كَشَفْنَا عَنْهُمُ [h:4966[ٱ][l[ل]رِّ[q:4965[جْ]زَ إِلَ[o[ىٰٓ] أَجَلٍ ه[c:4967[ُم ب]َ[n[ـٰ]لِغُوهُ إِذَا هُمْ يَ[f:4968[نك]ُث[p[ُو]نَ","Қачонки устиларидаги азобни ўзлари етиб борадиган муддатга кўтарсак, қарабсанки, қасамларини бузиб турибдилар.",166,9],["فَ[h:9999[ٱ][f:4969[نت]َقَمْنَا مِنْهُمْ فَأَغْرَ[q:4970[قْ]نَ[n[ـٰ]هُمْ فِى [h:4971[ٱ]لْيَ[g[مّ]ِ بِأَ[g[نّ]َهُمْ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا وَكَانُو[s[اْ] عَنْهَا غَ[n[ـٰ]فِل[p[ِي]نَ","Бас, улардан интиқом олдик. Оятларимизни ёлғонга чиқарганлари ва улардан ғофил бўлганлари учун уларни денгизга ғарқ қилдик.",166,9],["وَأَوْرَثْنَا [h:4972[ٱ]لْقَوْمَ [h:4973[ٱ]لَّذِينَ كَانُو[s[اْ] يُسْتَضْعَفُونَ مَشَ[n[ـٰ]رِقَ [h:4974[ٱ]لْأَرْضِ وَمَغَ[n[ـٰ]رِبَهَا [h:4975[ٱ]لَّتِى بَ[n[ـٰ]رَكْنَا فِيهَا‌ۖ وَتَ[g[مّ]َتْ كَلِمَتُ رَبِّكَ [h:4976[ٱ]لْحُسْنَىٰ عَلَىٰ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ بِمَا صَبَرُو[s[اْ‌ۖ] وَدَ[g[مّ]َرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُ[n[ۥ] وَمَا كَانُو[s[اْ] يَعْرِش[p[ُو]نَ","Ва хўрланиб юрган қавмни эса, Ўзимиз баракали қилган ернинг машриқию мағрибига меросхўр қилдик. Сабр қилганлари учун Роббингнинг гўзал сўзлари Бани Исроилга батамом бўлди. Фиръавн ва унинг қавми қурган нарсаларни ва улар юксалтирган нарсаларни вайрон қилдик.",166,9],["وَجَ[n[ـٰ]وَزْنَا بِبَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ [h:4977[ٱ]لْبَحْرَ فَأَتَوْ[s[اْ] عَلَىٰ قَوْ[a:4978[مٍ ي]َعْكُفُونَ عَلَ[o[ىٰٓ] أَصْنَا[u:4979[مٍ ل]َّهُمْ‌ۚ قَالُو[s[اْ] يَ[n[ـٰ]مُوسَى [h:4980[ٱ][q:658[جْ]عَل لَّن[o[َآ] إِلَ[n[ـٰ][f:4981[هًا ك]َمَا لَهُمْ ءَالِهَ[f:4982[ةٌ‌ۚ ق]َالَ إِ[g[نّ]َكُمْ قَوْ[f:4983[مٌ ت]َ[q:4984[جْ]هَل[p[ُو]نَ","Ва Бани Исроилни денгиздан олиб ўтдик. Бас, улар ўз санамларига берилиб сиғинаётган қавм устига келдилар. Улар: «Эй Мусо, бизга ҳам худди уларнинг худоларига ўхшаш худо қилиб бер», дедилар. У: «Албатта, сиз жоҳил қавм бўлаётибсиз.",167,9],["إِ[g[نّ]َ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ مُتَبَّ[a:4985[رٌ م]َّا هُمْ فِيهِ وَبَ[n[ـٰ]طِ[a:4986[لٌ م]َّا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Ахир, анавилар этиб турган нарса ҳалокатдир ва қилаётган ишлари ботилдир», деди.",167,9],["قَالَ أَغَيْرَ [h:3954[ٱ]للَّهِ أَ[q:4987[بْ]غِيكُمْ إِلَ[n[ـٰ][a:4988[هًا و]َهُوَ فَضَّلَكُمْ عَلَى [h:227[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","У: «Сизларга Аллоҳдан ўзгани худо қилиб берайми?! Ҳолбуки, У сизларни оламлардан афзал қилган зот-ку!» деди.",167,9],["وَإِذْ أَ[f:4989[نج]َيْنَ[n[ـٰ]ك[w:4990[ُم م]ِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ س[o[ُو]ٓءَ [h:239[ٱ]لْعَذَابِ‌ۖ يُقَتِّلُونَ أَ[q:240[بْ]ن[o[َا]ٓءَكُمْ وَيَسْتَحْيُونَ نِس[o[َا]ٓءَكُمْ‌ۚ وَفِى ذ[n[َٲ]لِك[c:241[ُم ب]َل[o[َا]ٓ[a:242[ءٌ م]ّ[u:243[ِن ر]َّبِّكُمْ عَظ[p[ِي]مٌ","Сизларни ёмон азобларга қўяётган, ўғилларингизни ўлдириб, қизларингизни тирик қолдираётган Фиръавн аҳлидан қутқарганимизни эсланг! Ва бу ишда Роббингиздан улуғ синов бордир.",167,9],["۞ وَو[n[َٲ]عَ[q:4991[دْ]نَا مُوسَىٰ ثَلَ[n[ـٰ]ثِينَ لَيْلَ[a:4992[ةً و]َأَتْمَمْنَ[n[ـٰ]هَا بِعَشْ[f:4993[رٍ ف]َتَ[g[مّ]َ مِيقَ[n[ـٰ]تُ رَبِّه[o[ِۦٓ] أَرْبَعِينَ لَيْلَ[a:4994[ةً‌ۚ و]َقَالَ مُوسَىٰ لِأَخِيهِ هَ[n[ـٰ]رُونَ [h:4995[ٱ]خْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ [h:4996[ٱ]لْمُفْسِد[p[ِي]نَ","Ва Мусо билан ўттиз кечага ваъдалашдик. Кейин эса, уни ўн билан тугал қилдик. Бас, Роббининг белгилаган вақти тўлиқ қирқ кеча бўлди. Мусо акаси Ҳорунга: «Қавмимда менинг ўрнимни ол, яхши иш қил, бузғунчиларнинг йўлига эргашма», деди.",167,9],["وَلَ[g[مّ]َا ج[o[َا]ٓءَ مُوسَىٰ لِمِيقَ[n[ـٰ]تِنَا وَكَلَّمَهُ[n[ۥ] رَبُّهُ[n[ۥ] قَالَ رَبِّ أَرِن[o[ِىٓ] أَ[f:4997[نظ]ُرْ إِلَيْكَ‌ۚ قَالَ لَ[f:4998[ن ت]َرَ[n[ٮٰ]نِى وَلَ[n[ـٰ]كِنِ [h:4999[ٱ][f:2837[نظ]ُرْ إِلَى [h:5000[ٱ]لْجَبَلِ فَإِنِ [h:5001[ٱ]سْتَقَرَّ مَكَانَهُ[n[ۥ] فَسَوْفَ تَرَ[n[ٮٰ]نِى‌ۚ فَلَ[g[مّ]َا تَجَلَّىٰ رَبُّهُ[n[ۥ] لِلْجَبَلِ جَعَلَهُ[n[ۥ] دَك[a:5002[ًّا و]َخَرَّ مُوسَىٰ صَعِ[f:5003[قًا‌ۚ ف]َلَ[g[مّ][o[َآ] أَفَاقَ قَالَ سُ[q:168[بْ]حَ[n[ـٰ]نَكَ تُ[q:2657[بْ]تُ إِلَيْكَ وَأَنَا۟ أَوَّلُ [h:5004[ٱ]لْمُؤْمِن[p[ِي]نَ","Мусо мийқотимизга келиб, Робби унга гапирганида, У: «Роббим, менга кўрсатгин, сенга назар солай», деди. У зот: «Мени ҳеч кўра олмассан. Лекин тоққа назар сол, агар у маконида собит тура олса, бас, Мени кўрасан», деди. Робби тоққа тажаллий қилганида, уни титилган ҳолга келтирди ва Мусо ҳушидан кетиб йиқилди. Ҳушига келгач: «Сен поксан, Сенга тавба қилдим. Мен мўминларнинг аввалгисиман», деди.",167,9],["قَالَ يَ[n[ـٰ]مُوسَ[o[ىٰٓ] إِ[g[نّ]ِى [h:5005[ٱ]صْطَفَيْتُكَ عَلَى [h:729[ٱ][l[ل][g[نّ]َاسِ بِرِسَ[n[ـٰ]لَ[n[ـٰ]تِى وَبِكَلَ[n[ـٰ]مِى فَخُذْ م[o[َآ] ءَاتَيْتُكَ وَك[a:5006[ُن م]ِّنَ [h:4134[ٱ][l[ل]شَّ[n[ـٰ]كِر[p[ِي]نَ","У зот: «Эй Мусо, Мен сени одамлар ичидан Пайғамбарлигим ва гаплашишим ила танлаб олдим. Бас, сенга берган нарсамни ол ва шукр қилувчилардан бўл!» деди.",168,9],["وَكَتَ[q:3573[بْ]نَا لَهُ[n[ۥ] فِى [h:5007[ٱ]لْأَلْوَاحِ مِ[f:843[ن ك]ُلِّ ش[a:5008[َىْءٍ م]َّوْعِظَ[a:5009[ةً و]َتَفْصِيل[u:4535[اً ل]ِّكُلِّ ش[f:5010[َىْءٍ ف]َخُذْهَا بِقُوَّ[a:5011[ةٍ و]َأْمُرْ قَوْمَكَ يَأْخُذُو[s[اْ] بِأَحْسَنِهَا‌ۚ سَأُ[s[وْ]رِيكُمْ دَارَ [h:5012[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","Ва унга лавҳларда ҳамма нарсадан мавъиза ва ҳар бир нарсанинг тафсилотини ёзиб бердик. «Бас, уларни қувват ила тут ва аҳлингга буюр, уларнинг энг яхшиларини олсинлар. Энди сизларга фосиқларнинг диёрини кўрсатаман», дедик.",168,9],["سَأَصْرِفُ عَنْ ءَايَ[n[ـٰ]تِىَ [h:5013[ٱ]لَّذِينَ يَتَكَبَّرُونَ فِى [h:44[ٱ]لْأَرْضِ بِغَيْرِ [h:325[ٱ]لْحَقِّ وَإ[a:3990[ِن ي]َرَوْ[s[اْ] كُلَّ ءَايَ[u:3991[ةٍ ل]َّا يُؤْمِنُو[s[اْ] بِهَا وَإ[a:3990[ِن ي]َرَوْ[s[اْ] سَبِيلَ [h:5014[ٱ][l[ل]رُّشْدِ لَا يَتَّخِذُوهُ سَبِيل[a:5015[اً و]َإ[a:3990[ِن ي]َرَوْ[s[اْ] سَبِيلَ [h:5016[ٱ]لْغَىِّ يَتَّخِذُوهُ سَبِيل[f:5017[اً‌ۚ ذ][n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا وَكَانُو[s[اْ] عَنْهَا غَ[n[ـٰ]فِل[p[ِي]نَ","Энди ер юзида ноҳақдан мутакаббирлик қилаётганларни, барча оятларни кўрсалар ҳам, уларга иймон келтирмаётганларни, тўғрилик йўлини кўрсалар ҳам, уни ўзларига йўл тутмаётганларни, агар адашув йўлини кўрсалар, уни ўзларига йўл тутаётганларни Ўз оятларимдан бураман. Бундай бўлиши уларнинг оятларимизни ёлғонга чиқаришлари ва улардан ғофил бўлишлари сабабидандир.",168,9],["وَ[h:9999[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا وَلِق[o[َا]ٓءِ [h:5018[ٱ]لْأَخِرَةِ حَبِطَتْ أَعْمَ[n[ـٰ]لُهُمْ‌ۚ هَلْ يُ[q:5019[جْ]زَوْنَ إِلَّا مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Оятларимизни ва охират мулоқотини ёлғонга чиқарганлар амаллари бехуда кетганлардир. Улар фақат қилиб юрган амалларининг жазосини олурлар.",168,9],["وَ[h:9999[ٱ]تَّخَذَ قَوْمُ مُوسَىٰ م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] مِنْ حُلِيِّهِمْ عِ[q:5020[جْ]ل[f:5021[اً ج]َسَ[u:5022[دًا ل]َّهُ[n[ۥ] خُوَارٌ‌ۚ أَلَمْ يَرَوْ[s[اْ] أَ[g[نّ]َهُ[n[ۥ] لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلاً‌ۘ [h:5023[ٱ]تَّخَذُوهُ وَكَانُو[s[اْ] ظَ[n[ـٰ]لِم[p[ِي]نَ","Мусонинг қавми ундан кейин тақинчоқларидан бўкирадиган бузоқ жасадини тутдилар. Унинг уларга гапирмаслигини ва уларни ҳидоят қилмаслигини билмадиларми?! Уни тутдилар ва зулм қилувчилардан бўлдилар.",168,9],["وَلَ[g[مّ]َا سُقِطَ ف[o[ِىٓ] أَيْدِيهِمْ وَرَأَوْ[s[اْ] أَ[g[نّ]َهُمْ قَ[q:298[دْ] ضَلُّو[s[اْ] قَالُو[s[اْ] لَئ[u:4195[ِن ل]َّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَ[g[نّ]َ مِنَ [h:340[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","Қўллари тушган пайтда ва ўзларининг адашганларини билганларида: «Агар Роббимиз бизга раҳм қилмаса ва мағфират этмаса, албатта, зиёнкорлардан бўламиз», дедилар.",168,9],["وَلَ[g[مّ]َا رَجَعَ مُوسَ[o[ىٰٓ] إِلَىٰ قَوْمِه[n[ِۦ] غَضْبَ[n[ـٰ]نَ أَسِ[f:5024[فًا ق]َالَ بِئْسَمَا خَلَفْتُمُونِى م[i:692[ِنۢ ب]َعْد[o[ِىٓ‌ۖ] أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ‌ۖ وَأَلْقَى [h:5025[ٱ]لْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُ[o[ۥٓ] إِلَيْهِ‌ۚ قَالَ [h:5026[ٱ][q:451[بْ]نَ أُ[g[مّ]َ إِ[g[نّ]َ [h:5027[ٱ]لْقَوْمَ [h:5028[ٱ]سْتَضْعَفُونِى وَكَادُو[s[اْ] يَ[q:5029[قْ]تُلُونَنِى فَلَا تُشْمِتْ بِىَ [h:5030[ٱ]لْأَعْد[o[َا]ٓءَ وَلَا تَ[q:5031[جْ]عَلْنِى مَعَ [h:3746[ٱ]لْقَوْمِ [h:4155[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Қачонки Мусо ўз қавмига ғазабланган ва афсус қилган ҳолида қайтганида: «Менинг кетимдан қандай ҳам ёмон халифа бўлдингиз. Роббингизнинг амридан шошилдингизми?!» деди ва лавҳларни ташлаб, акасининг бошидан тутиб, ўзига торта бошлади. У: «Эй онамнинг боласи, шубҳасиз, бу қавм мени хўрлади ва ўлдириб қўйишларига сал қолди. Энди сен душманларни устимдан кулдирмагин ва мени ҳам золим қавмлардан деб билмагин», деди.",169,9],["قَالَ رَبِّ [h:5032[ٱ]غْفِرْ لِى وَلِأَخِى وَأَ[q:5033[دْ]خِلْنَا فِى رَحْمَتِكَ‌ۖ وَأَ[f:3893[نت]َ أَرْحَمُ [h:5034[ٱ][l[ل]رّ[n[َٲ]حِم[p[ِي]نَ","У: «Мени ва акамни мағфират қилгин ва бизларни Ўз раҳматингга киритгин. Сенинг Ўзинг раҳм қилгувчиларнинг раҳмлироғисан», деди.",169,9],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ [h:3645[ٱ]تَّخَذُو[s[اْ] [h:3259[ٱ]لْعِ[q:253[جْ]لَ سَيَنَالُهُمْ غَضَ[a:5035[بٌ م]ّ[u:22[ِن ر]َّبِّهِمْ وَذِلَّ[f:5036[ةٌ ف]ِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۚ وَكَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:5037[ٱ]لْمُفْتَر[p[ِي]نَ","Албатта, бузоқни тутганларга Роббиларидан ғазаб ва ҳаёти дунёда хорлик етадир. Ёлғон тўқувчиларни мана шундай жазолаймиз.",169,9],["وَ[h:9999[ٱ]لَّذِينَ عَمِلُو[s[اْ] [h:5038[ٱ][l[ل]سَّيِّـَٔـاتِ ثُ[g[مّ]َ تَابُو[s[اْ] م[i:5039[ِنۢ ب]َعْدِهَا وَءَامَن[o[ُوٓ][s[اْ] إِ[g[نّ]َ رَبَّكَ م[i:5039[ِنۢ ب]َعْدِهَا لَغَفُو[u:4578[رٌ ر]َّح[p[ِي]مٌ","Гуноҳ ишларни қилганлар, ундан кейин тавба қилсалар ва иймон келтирсалар, албатта, Роббинг ундан сўнг мағфират қилгувчи ва меҳрибон зотдир.",169,9],["وَلَ[g[مّ]َا سَكَتَ ع[a:5040[َن م]ُّوسَى [h:5041[ٱ]لْغَضَبُ أَخَذَ [h:5042[ٱ]لْأَلْوَاحَ‌ۖ وَفِى نُسْخَتِهَا هُ[a:5043[دًى و]َرَحْمَ[u:5044[ةٌ ل]ِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَب[p[ُو]نَ","Қачонки Мусонинг ғазаби босилгач, лавҳларни олди. Уларнинг нусхасида Роббиларидан ҳақиқатда қўрқадиганлар учун ҳидоят ва раҳмат бор эди.",169,9],["وَ[h:9999[ٱ]خْتَارَ مُوسَىٰ قَوْمَهُ[n[ۥ] سَ[q:5045[بْ]عِينَ رَجُل[u:5046[اً ل]ِّمِيقَ[n[ـٰ]تِنَا‌ۖ فَلَ[g[مّ][o[َآ] أَخَذَتْهُمُ [h:5047[ٱ][l[ل]رَّ[q:4824[جْ]فَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَه[w:5048[ُم م]ِّ[f:128[ن ق]َ[q:129[بْ]لُ وَإِيَّ[n[ـٰ]ىَ‌ۖ أَتُهْلِكُنَا بِمَا فَعَلَ [h:5049[ٱ][l[ل]سُّفَه[o[َا]ٓءُ مِ[g[نّ][o[َآ‌ۖ] إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَ[f:1823[ن ت]َش[o[َا]ٓءُ وَتَهْدِى مَ[f:1823[ن ت]َش[o[َا]ٓءُ‌ۖ أَ[f:169[نت]َ وَلِيُّنَا فَ[h:1791[ٱ]غْفِرْ لَنَا وَ[h:1721[ٱ]رْحَمْنَا‌ۖ وَأَ[f:3893[نت]َ خَيْرُ [h:5050[ٱ]لْغَ[n[ـٰ]فِر[p[ِي]نَ","Ва Мусо мийқотимизга қавмидан етмиш кишини танлаб олди. Уларни даҳшатли зилзила тутган пайтда: «Эй Роббим, агар хоҳласанг, буларни ҳам, мени ҳам бундан олдин ҳалок қилсанг бўларди. Эсипастларимиз қилган иш туфайли бизни ҳалок қиласанми? Бу Сенинг синовингдан бошқа нарса эмас. У ила кимни хоҳласанг, адаштирасан ва кимни хоҳласанг, ҳидоятга соласан. Сен валиймизсан, бас, бизни мағфират қил ва раҳм эт. Сенинг Ўзинг мағфират қилувчиларнинг энг яхшисисан.",169,9],["۞ وَ[h:9999[ٱ]كْتُ[q:5051[بْ] لَنَا فِى هَ[n[ـٰ]ذِهِ [h:5052[ٱ][l[ل]دُّنْيَا حَسَنَ[a:1107[ةً و]َفِى [h:1108[ٱ]لْأَخِرَةِ إِ[g[نّ]َا هُ[q:5053[دْ]ن[o[َآ] إِلَيْكَ‌ۚ قَالَ عَذَاب[o[ِىٓ] أُصِيبُ بِه[n[ِۦ] مَنْ أَش[o[َا]ٓءُ‌ۖ وَرَحْمَتِى وَسِعَتْ كُلَّ ش[f:5054[َىْءٍ‌ۚ ف]َسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ [h:3639[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَ[h:37[ٱ]لَّذِينَ ه[c:5055[ُم ب]ِـَٔـايَ[n[ـٰ]تِنَا يُؤْمِن[p[ُو]نَ","Ва бизга бу дунёда ҳам, охиратда ҳам яхшиликни ёзиб қўй. Биз сенинг Ўзингга тавба қилдик», деди. У зот: «Азобим ила кимни хоҳласам, тутаман. Раҳматим эса, ҳамма нарсадан кенгдир. Уни тақво қилганларга, закот берганларга, оятларимизга иймон келтирганга ёзажакман.",170,9],["ٱلَّذِينَ يَتَّبِعُونَ [h:5056[ٱ][l[ل]رَّسُولَ [h:5057[ٱ][l[ل][g[نّ]َبِىَّ [h:5058[ٱ]لْأُ[g[مّ]ِىَّ [h:5059[ٱ]لَّذِى يَجِدُونَهُ[n[ۥ] مَكْتُوبًا عِ[f:5060[ند]َهُمْ فِى [h:5061[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةِ وَ[h:5062[ٱ]لْإِ[f:5062[نج]ِيلِ يَأْمُرُه[c:5063[ُم ب]ِ[h:934[ٱ]لْمَعْرُوفِ وَيَنْهَ[n[ـٰ]هُمْ عَنِ [h:2144[ٱ]لْمُ[f:2145[نك]َرِ وَيُحِلُّ لَهُمُ [h:5064[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تِ وَيُحَرِّمُ عَلَيْهِمُ [h:5065[ٱ]لْخَبَ[o[ـٰٓ]ئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَ[h:5066[ٱ]لْأَغْلَ[n[ـٰ]لَ [h:5067[ٱ]لَّتِى كَانَتْ عَلَيْهِمْ‌ۚ فَ[h:2514[ٱ]لَّذِينَ ءَامَنُو[s[اْ] بِه[n[ِۦ] وَعَزَّرُوهُ وَنَصَرُوهُ وَ[h:2433[ٱ]تَّبَعُو[s[اْ] [h:5068[ٱ][l[ل][g[نّ]ُورَ [h:5069[ٱ]لَّذ[o[ِىٓ] أُ[f:17[نز]ِلَ مَعَهُ[o[ۥٓ‌ۙ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Улар ўз ҳузурларидаги Таврот ва Инжилда ёзилган ҳолида топиладиган, уларни яхшиликка буюриб, ёмонликдан қайтарадиган, уларга покиза нарсаларни ҳалол қилиб, нопок нарсаларни ҳаром қиладиган, устиларидаги юкни енгиллатиб, кишанларни ечадиган уммий, Набий, Пайғамбарга эргашадилар. Бас, унга иймон келтириб, ёрдам бериб ва уни қўллаб-қувватлаган ҳамда унга нозил бўлган нурга эргашганлар–ана ўшалар нажот топгувчилардир», деди.",170,9],["قُلْ يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ إِ[g[نّ]ِى رَسُولُ [h:3306[ٱ]للَّهِ إِلَيْكُمْ جَمِيعًا [h:5070[ٱ]لَّذِى لَهُ[n[ۥ] مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ يُحْى[n[ِۦ] وَيُمِيتُ‌ۖ فَـَٔـامِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرَسُولِهِ [h:5071[ٱ][l[ل][g[نّ]َبِىِّ [h:5072[ٱ]لْأُ[g[مّ]ِىِّ [h:5073[ٱ]لَّذِى يُؤْمِنُ بِ[h:32[ٱ]للَّهِ وَكَلِمَ[n[ـٰ]تِه[n[ِۦ] وَ[h:5074[ٱ]تَّبِعُوهُ لَعَلَّكُمْ تَهْتَد[p[ُو]نَ","Сен: «Эй одамлар, албатта, мен сизларнинг барчангизга, осмонлару ернинг мулки Уники бўлган, Ундан ўзга илоҳ йўқ бўлган ва тирилтириб ўлдирадиган Аллоҳнинг Пайғамбаридирман. Бас, Аллоҳга ҳамда Унинг Аллоҳ ва Унинг калималарига иймон келтирадиган уммий элчисига–Пайғамбарига иймон келтиринг. Ва унга эргашинг, шоядки ҳидоят топсангиз», деб айт.",170,9],["وَمِ[f:5075[ن ق]َوْمِ مُوسَ[o[ىٰٓ] أُ[g[مّ]َ[a:5076[ةٌ ي]َهْدُونَ بِ[h:370[ٱ]لْحَقِّ وَبِه[n[ِۦ] يَعْدِل[p[ُو]نَ","Ва Мусонинг қавмидан баъзи жамоалар борки, ҳақ ила ҳидоят қилиб, у ила адолат қиларлар.",170,9],["وَقَطَّعْنَ[n[ـٰ]هُمُ [h:5077[ٱ]ثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَ[a:5078[مًا‌ۚ و]َأَوْحَيْن[o[َآ] إِلَىٰ مُوسَ[o[ىٰٓ] إِذِ [h:5079[ٱ]سْتَسْقَ[n[ـٰ]هُ قَوْمُهُ[o[ۥٓ] أَنِ [h:5080[ٱ]ضْرِب بِّعَصَاكَ [h:294[ٱ]لْحَجَرَ‌ۖ فَ[h:5081[ٱ][i:5081[نۢب]َجَسَتْ مِنْهُ [h:296[ٱ]ثْنَتَا عَشْرَةَ عَيْ[f:297[نًا‌ۖ ق]َ[q:298[دْ] عَلِمَ كُلُّ أُنَا[a:299[سٍ م]َّشْرَبَهُمْ‌ۚ وَظَلَّلْنَا عَلَيْهِمُ [h:5082[ٱ]لْغَمَ[n[ـٰ]مَ وَأَ[f:271[نز]َلْنَا عَلَيْهِمُ [h:5083[ٱ]لْمَ[g[نّ]َ وَ[h:273[ٱ][l[ل]سَّلْوَىٰ‌ۖ كُلُو[s[اْ] مِ[f:274[ن ط]َيِّبَ[n[ـٰ]تِ مَا رَزَ[q:275[قْ]نَ[n[ـٰ]كُمْ‌ۚ وَمَا ظَلَمُونَا وَلَ[n[ـٰ]كِ[f:276[ن ك]َان[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ يَظْلِم[p[ُو]نَ","Уларни ўн икки уруғ–жамоага бўлиб юбордик. Ва қавми ундан сув талаб қилган пайтда Мусога: «Асонг ила тошни ур!» деб ваҳий юбордик. Удан ўн иккита булоқ отилиб чиқди. Ҳамма одамлар ўз сувхонасини билди. Ва уларга булутни соябон қилдик, манн ва беданаларни нозил қилдик. «Сизларга ризқ қилиб берган нарсаларимизнинг покларини енглар». Улар бизга зулм қилмадилар. Лекин ўзларига зулм қилар эдилар.",171,9],["وَإِذْ قِيلَ لَهُمُ [h:5084[ٱ]سْكُنُو[s[اْ] هَ[n[ـٰ]ذِهِ [h:279[ٱ]لْقَرْيَةَ وَكُلُو[s[اْ] مِنْهَا حَيْثُ شِئْتُمْ وَقُولُو[s[اْ] حِطَّ[a:5085[ةٌ و]َ[h:281[ٱ][q:281[دْ]خُلُو[s[اْ] [h:282[ٱ]لْبَابَ سُجَّ[a:5086[دًا ن]َّغْفِرْ لَكُمْ خَطِ[o[يٓ]ـَٔ[n[ـٰ]تِكُمْ‌ۚ سَنَزِيدُ [h:5087[ٱ]لْمُحْسِن[p[ِي]نَ","Уларга: «Мана бу шаҳарни маскан тутинглар, унда хоҳлаган жойингизда таом енг ва «Ҳиттатун» деб эшикдан сажда қилган ҳолингизда кирсангиз, сизнинг хатоларингизни мағфират қиламиз, эҳсон қилувчиларга зиёда қиламиз», деганимизни эсла.",171,9],["فَبَدَّلَ [h:286[ٱ]لَّذِينَ ظَلَمُو[s[اْ] مِنْهُمْ قَوْلاً غَيْرَ [h:287[ٱ]لَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِ[q:290[جْ][a:291[زًا م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ بِمَا كَانُو[s[اْ] يَظْلِم[p[ُو]نَ","Бас, улардан зулм қилганлари уларга айтилгандан ўзга гапни алмаштирдилар. Бас, зулм қилганлари туфайли устларига осмондан азоб юбордик.",171,9],["وَسْــَٔلْهُمْ عَنِ [h:5088[ٱ]لْقَرْيَةِ [h:5089[ٱ]لَّتِى كَانَتْ حَاضِرَةَ [h:5090[ٱ]لْبَحْرِ إِذْ يَعْدُونَ فِى [h:345[ٱ][l[ل]سَّ[q:346[بْ]تِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَ[q:5091[بْ]تِهِمْ شُرَّ[a:5092[عًا و]َيَوْمَ لَا يَسْبِتُونَ‌ۙ لَا تَأْتِيهِمْ‌ۚ كَذ[n[َٲ]لِكَ نَ[q:5093[بْ]لُوه[c:5094[ُم ب]ِمَا كَانُو[s[اْ] يَفْسُق[p[ُو]نَ","Улардан денгиз соҳилида бўлган қишлоқ ҳақида, шанба кунида ҳаддан ошганлари, шанбалик кунларида балиқлари очиқ келиб, шанбалик қилмаган кунлари келмагани ҳақида сўра. Қилган фосиқликлари туфайли уларни шундай синаймиз.",171,9],["وَإِذْ قَالَتْ أُ[g[مّ]َ[a:5095[ةٌ م]ِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا‌ۙ [h:5096[ٱ]للَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَا[f:1966[بًا ش]َدِي[f:5097[دًا‌ۖ ق]َالُو[s[اْ] مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّق[p[ُو]نَ","Улардан бир жамоат: «Аллоҳ ҳалок қилувчи ёки шиддатли азоб-ла азобловчи қавмга ваъз қилиб нима қиласиз?!» деганида, улар, Роббингизга узр бўлиши учун ва шоядки тақво қилсалар деб, дедилар.",172,9],["فَلَ[g[مّ]َا نَسُو[s[اْ] مَا ذُكِّرُو[s[اْ] بِه[o[ِۦٓ] أَ[f:5098[نج]َيْنَا [h:5099[ٱ]لَّذِينَ يَنْهَوْنَ عَنِ [h:5100[ٱ][l[ل]سّ[o[ُو]ٓءِ وَأَخَذْنَا [h:5101[ٱ]لَّذِينَ ظَلَمُو[s[اْ] بِعَذَا[i:5102[بِۭ ب]َــِٔي[i:5103[سِۭ ب]ِمَا كَانُو[s[اْ] يَفْسُق[p[ُو]نَ","Бас, улар ўзларига эслатма бўлган нарсани унутганларида, ёмонликдан қайтараётганларга нажот бердик ва зулм қилганларни қилган фосиқликлари туфайли шиддатли азоб ила тутдик.",172,9],["فَلَ[g[مّ]َا عَتَوْ[s[اْ] ع[a:5104[َن م]َّا نُهُو[s[اْ] عَنْهُ قُلْنَا لَهُمْ كُونُو[s[اْ] قِرَدَةً خَ[n[ـٰ]سِــٔ[p[ِي]نَ","Бас, улар ўзлари қайтарилган нарсадан қайтмай, такаббурлик қилганларида, уларга: «Хўрланган маймунларга айланинг!» дедик.",172,9],["وَإِذْ تَأَذَّنَ رَبُّكَ لَيَ[q:5105[بْ]عَثَ[g[نّ]َ عَلَيْهِمْ إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ م[a:5106[َن ي]َسُومُهُمْ س[o[ُو]ٓءَ [h:239[ٱ]لْعَذَابِ‌ۗ إِ[g[نّ]َ رَبَّكَ لَسَرِيعُ [h:5107[ٱ]لْعِقَابِ‌ۖ وَإِ[g[نّ]َهُ[n[ۥ] لَغَفُو[u:4578[رٌ ر]َّح[p[ِي]مٌ","Роббинг, албатта, уларнинг устларига қиёмат кунигача уларга ёмон азобни тоттирадиганларни юборишни эълон қилганини эсла! Албатта, Роббинг иқоби тез зотдир ва, албатта, У мағфиратли ва раҳмли Зотдир.",172,9],["وَقَطَّعْنَ[n[ـٰ]هُمْ فِى [h:44[ٱ]لْأَرْضِ أُمَ[a:5108[مًا‌ۖ م]ِّنْهُمُ [h:5109[ٱ][l[ل]صَّ[n[ـٰ]لِحُونَ وَمِنْهُمْ دُونَ ذ[n[َٲ]لِكَ‌ۖ وَبَلَوْنَ[n[ـٰ]ه[c:5110[ُم ب]ِ[h:5111[ٱ]لْحَسَنَ[n[ـٰ]تِ وَ[h:5112[ٱ][l[ل]سَّيِّـَٔـاتِ لَعَلَّهُمْ يَرْجِع[p[ُو]نَ","Ва уларни ер юзида жамоатларга бўлиб юбордик. Улардан аҳли солиҳлари бор ва улардан ундай эмаслари ҳам бор. Шоядки қайтсалар, деб уларни яхшиликлар ва ёмонликлар ила синадик.",172,9],["فَخَلَفَ م[i:1453[ِنۢ ب]َعْدِهِمْ خَلْ[a:5113[فٌ و]َرِثُو[s[اْ] [h:5114[ٱ]لْكِتَ[n[ـٰ]بَ يَأْخُذُونَ عَرَضَ هَ[n[ـٰ]ذَا [h:5115[ٱ]لْأَ[q:5116[دْ]نَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإ[a:5117[ِن ي]َأْتِهِمْ عَرَ[a:5118[ضٌ م]ِّثْلُهُ[n[ۥ] يَأْخُذُوهُ‌ۚ أَلَمْ يُؤْخَذْ عَلَيْه[w:5119[ِم م]ِّيثَ[n[ـٰ]قُ [h:5120[ٱ]لْكِتَ[n[ـٰ]بِ أ[u:4908[َن ل]َّا يَقُولُو[s[اْ] عَلَى [h:412[ٱ]للَّهِ إِلَّا [h:3304[ٱ]لْحَقَّ وَدَرَسُو[s[اْ] مَا فِيهِ‌ۗ وَ[h:5121[ٱ][l[ل]دَّارُ [h:5122[ٱ]لْأَخِرَةُ خَيْ[u:4005[رٌ ل]ِّلَّذِينَ يَتَّقُونَ‌ۗ أَفَلَا تَعْقِل[p[ُو]نَ","Бас, улардан сўнг, ортларидан китобни меросга олган бир ўринбосарлар келдики, улар мана бу тубаннинг ўткинчи ни оларлар ва «бизни кечирилади», дерлар. Агар ўшанга ўхшаш ўткинчи нарса келса, яна олаверадилар. Улардан Аллоҳга нисбатан фақат ҳақдан бошқа нарса айтмасликка Китобнинг аҳду паймони олинган эмасмиди?! Улар удаги нарсаларни ўрганганлар-ку?! Охират ҳовлиси тақво қилганлар учун яхшидир. Ақл ишлатмайсизларми?!",172,9],["وَ[h:9999[ٱ]لَّذِينَ يُمَسِّكُونَ بِ[h:2042[ٱ]لْكِتَ[n[ـٰ]بِ وَأَقَامُو[s[اْ] [h:1641[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ إِ[g[نّ]َا لَا نُضِيعُ أَ[q:2418[جْ]رَ [h:5123[ٱ]لْمُصْلِح[p[ِي]نَ","Китобни маҳкам тутганлар ва намозни қоим қилганлар бўлса, албатта, Биз аҳли солиҳларнинг ажрларини зое қилмасмиз.",172,9],["۞ وَإِذْ نَتَ[q:5124[قْ]نَا [h:5125[ٱ]لْجَبَلَ فَوْقَهُمْ كَأَ[g[نّ]َهُ[n[ۥ] ظُلَّ[a:5126[ةٌ و]َظَ[g[نّ][o[ُوٓ][s[اْ] أَ[g[نّ]َهُ[n[ۥ] وَاقِ[i:5127[عُۢ ب]ِهِمْ خُذُو[s[اْ] م[o[َآ] ءَاتَيْنَ[n[ـٰ]ك[c:333[ُم ب]ِقُوَّ[a:334[ةٍ و]َ[h:335[ٱ]ذْكُرُو[s[اْ] مَا فِيهِ لَعَلَّكُمْ تَتَّق[p[ُو]نَ","Уларнинг устига тоғни худди соябондек кўтарганимизни, улар уни, устимизга тушиб кетади, деб ўйлаганларида, сизга берган нарсамизни қувват ила олинглар ва ундаги нарсани эсланглар, шоядки тақво қилсангиз, деганимизни эсла.",173,9],["وَإِذْ أَخَذَ رَبُّكَ م[i:1385[ِنۢ ب]َن[o[ِىٓ] ءَادَمَ مِ[f:5128[ن ظ]ُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَ[o[ىٰٓ] أَ[f:568[نف]ُسِهِمْ أَلَسْتُ بِرَبِّكُمْ‌ۖ قَالُو[s[اْ] بَلَىٰ‌ۛ شَهِ[q:4421[دْ]ن[o[َآ‌ۛ] أَ[f:1330[ن ت]َقُولُو[s[اْ] يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ إِ[g[نّ]َا كُ[g[نّ]َا عَنْ هَ[n[ـٰ]ذَا غَ[n[ـٰ]فِل[p[ِي]نَ","Роббинг Бани Одамнинг умуртқа поғанасидан, қиёмат куни, бундан ғофил эдик, демасликларингиз учун, зурриётларини олиб, ўзларига ўзларини гувоҳ қилиб: «Роббингиз эмасманми?» деганида; «Худди шундай! Гувоҳ бўлдик!» деганларини эсла.",173,9],["أَوْ تَقُول[o[ُوٓ][s[اْ] إِ[g[نّ]َم[o[َآ] أَشْرَكَ ءَاب[o[َا]ٓؤُنَا مِ[f:128[ن ق]َ[q:129[بْ]لُ وَكُ[g[نّ]َا ذُرِّيَّ[a:5129[ةً م]ّ[i:1453[ِنۢ ب]َعْدِهِمْ‌ۖ أَفَتُهْلِكُنَا بِمَا فَعَلَ [h:5130[ٱ]لْمُ[q:5131[بْ]طِل[p[ُو]نَ","Ёки: «Ҳақиқатда, ширк келтирганлар олдинги ота-боболаримиз, биз, уларнинг кейинги зурриётимиз. Ботил иш қилувчиларнинг қилмиши туфайли бизларни ҳалок этасанми», демаслигингиз учун.",173,9],["وَكَذ[n[َٲ]لِكَ نُفَصِّلُ [h:4091[ٱ]لْأَيَ[n[ـٰ]تِ وَلَعَلَّهُمْ يَرْجِع[p[ُو]نَ","Шояд қайтсалар, деб оятларни мана шундай батафсил баён қиламиз.",173,9],["وَ[h:9999[ٱ]تْلُ عَلَيْهِمْ نَبَأَ [h:5132[ٱ]لَّذ[o[ِىٓ] ءَاتَيْنَ[n[ـٰ]هُ ءَايَ[n[ـٰ]تِنَا فَ[h:5133[ٱ][f:5133[نس]َلَخَ مِنْهَا فَأَتْبَعَهُ [h:5134[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ فَكَانَ مِنَ [h:5135[ٱ]لْغَاو[p[ِي]نَ","Уларга оятларимизни берганимизда, улардан ўзини олиб қочган ва уни шайтон эргаштириб кетиб, иғвога учганлардан бўлган шахснинг хабарини тиловот қилиб бер!",173,9],["وَلَوْ شِئْنَا لَرَفَعْنَ[n[ـٰ]هُ بِهَا وَلَ[n[ـٰ]كِ[g[نّ]َهُ[o[ۥٓ] أَخْلَدَ إِلَى [h:5136[ٱ]لْأَرْضِ وَ[h:3160[ٱ]تَّبَعَ هَوَ[n[ٮٰ]هُ‌ۚ فَمَثَلُهُ[n[ۥ] كَمَثَلِ [h:5137[ٱ]لْكَلْبِ إِ[f:5138[ن ت]َحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَ[d:5139[ث]‌ۚ ذّ[n[َٲ]لِكَ مَثَلُ [h:5140[ٱ]لْقَوْمِ [h:4053[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا‌ۚ فَ[h:5141[ٱ][q:5141[قْ]صُصِ [h:5142[ٱ]لْقَصَصَ لَعَلَّهُمْ يَتَفَكَّر[p[ُو]نَ","Агар хоҳласак, уни ўша лар билан кўтарар эдик. Лекин унинг ўзи ерга ёпишди ва ҳавои нафсига эргашди. Бас, унинг мисоли худди бир итга ўхшайди, уни ҳайдасанг ҳам, тилини осилтириб тураверади, тек қўйсанг ҳам, тилини осилтириб тураверади. Бу бизнинг оятларимизни ёлғонга чиқарган қавмларнинг мисолидир. Бу қиссани ҳикоя қил, шоядки тафаккур қилсалар.",173,9],["س[o[َا]ٓءَ مَثَلاً [h:5143[ٱ]لْقَوْمُ [h:5144[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا وَأَ[f:5145[نف]ُسَهُمْ كَانُو[s[اْ] يَظْلِم[p[ُو]نَ","Оятларимизни ёлғонга чиқарган қавмларнинг мисоли қандай ҳам ёмон бўлди! Улар ўзларига зулм қиларлар.",173,9],["م[a:5146[َن ي]َهْدِ [h:5147[ٱ]للَّهُ فَهُوَ [h:5148[ٱ]لْمُهْتَدِى‌ۖ وَم[a:5149[َن ي]ُضْلِلْ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:150[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","Аллоҳ кимни ҳидоятга солса, ўша ҳидоят топувчидир. Кимни адаштирса, ўшалар ўзлари зиён кўрувчилардир.",173,9],["وَلَقَ[q:341[دْ] ذَرَأْنَا لِجَهَ[g[نّ]َمَ كَثِي[a:3614[رًا م]ِّنَ [h:4673[ٱ]لْجِ[g[نّ]ِ وَ[h:4418[ٱ]لْإِ[f:4418[نس]ِ‌ۖ لَهُمْ قُلُو[u:5150[بٌ ل]َّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُ[u:5151[نٌ ل]َّا يُ[q:60[بْ]صِرُونَ بِهَا وَلَهُمْ ءَاذَا[u:5152[نٌ ل]َّا يَسْمَعُونَ بِه[o[َآ‌ۚ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ كَ[h:5153[ٱ]لْأَنْعَ[n[ـٰ]مِ بَلْ هُمْ أَضَلُّ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:5154[ٱ]لْغَ[n[ـٰ]فِل[p[ُو]نَ","Батаҳқиқ, жаҳаннам учун кўплаб жин ва инсларни яратдик. Уларнинг диллари бору тушуна олмаслар. Кўзлари бору кўра олмаслар. Қулоқлари бору эшита олмаслар. Ана ўшалар чорва ҳайвонлари кабидирлар. Балки улардан ҳам баттарроқдирлар. Ана ўшалар ғофилдирлар.",174,9],["وَلِلَّهِ [h:5155[ٱ]لْأَسْم[o[َا]ٓءُ [h:5156[ٱ]لْحُسْنَىٰ فَ[h:5157[ٱ][q:5157[دْ]عُوهُ بِهَا‌ۖ وَذَرُو[s[اْ] [h:5158[ٱ]لَّذِينَ يُلْحِدُونَ ف[o[ِىٓ] أَسْمَ[o[ـٰٓ]ئِه[n[ِۦ‌ۚ] سَيُ[q:4372[جْ]زَوْنَ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Аллоҳнинг гўзал исмлари бордир. Бас, Унга ўшалар ила дуо қилинг ва Унинг исмларидан оғадиганларни тек қўйинг. Яқинда қилган амалларига яраша жазоланурлар.",174,9],["وَمِ[g[مّ]َنْ خَلَ[q:5159[قْ]ن[o[َآ] أُ[g[مّ]َ[a:5076[ةٌ ي]َهْدُونَ بِ[h:370[ٱ]لْحَقِّ وَبِه[n[ِۦ] يَعْدِل[p[ُو]نَ","Ва Биз яратган кимсалар ичида ҳақ ила ҳидоят қиладиган ва у ила адолат қиладиган жамоат ҳам бор.",174,9],["وَ[h:9999[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا سَنَسْتَ[q:5160[دْ]رِجُه[w:5161[ُم م]ِّنْ حَيْثُ لَا يَعْلَم[p[ُو]نَ","Оятларимизни ёлғонга чиқарганларни эса, улар билмайдиган томондан аста-секин оламиз.",174,9],["وَأُمْلِى لَهُمْ‌ۚ إِ[g[نّ]َ كَيْدِى مَت[p[ِي]نٌ","Уларга муҳлат бериб қўяман. Албатта, менинг «макрим» метиндир.",174,9],["أَوَلَمْ يَتَفَكَّرُو[s[اْ‌ۗ] مَا بِصَاحِبِه[w:5162[ِم م]ِّ[f:5163[ن ج]ِ[g[نّ]َةٍ‌ۚ إِنْ هُوَ إِلَّا نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","Улар ўз соҳибларида мажнунлик йўқлигини тафаккур қилиб кўрмайдиларми?! У фақат ошкора огоҳлантирувчи, холос.",174,9],["أَوَلَمْ يَ[f:5165[نظ]ُرُو[s[اْ] فِى مَلَكُوتِ [h:5166[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا خَلَقَ [h:1272[ٱ]للَّهُ مِ[f:2103[ن ش][a:5167[َىْءٍ و]َأَنْ عَسَ[o[ىٰٓ] أ[a:3312[َن ي]َكُونَ قَدِ [h:5168[ٱ][q:5169[قْ]تَرَبَ أَجَلُهُمْ‌ۖ فَبِأَىِّ حَدِي[i:5170[ثِۭ ب]َعْدَهُ[n[ۥ] يُؤْمِن[p[ُو]نَ","Осмонлару ернинг мулкларига, Аллоҳ яратган нарсаларга ва, ажаб эмаски, ажаллари яқинлашиб қолган бўлишига назар солмайдиларми? Бундан кейин, яна қайси гапга ишонарлар?!",174,9],["م[a:5171[َن ي]ُضْلِلِ [h:3003[ٱ]للَّهُ فَلَا هَادِىَ لَهُ[n[ۥ]‌ۚ وَيَذَرُهُمْ فِى طُغْيَ[n[ـٰ]نِهِمْ يَعْمَه[p[ُو]نَ","Аллоҳ кимни залолатга кетказса, унга ҳидоят қилувчи йўқдир. Уларни тек қўйиб қўяди, туғёнларида адашиб-улоқиб юраверадилар.",174,9],["يَسْــَٔلُونَكَ عَنِ [h:5172[ٱ][l[ل]سَّاعَةِ أَيَّانَ مُرْسَ[n[ـٰ]هَا‌ۖ قُلْ إِ[g[نّ]َمَا عِلْمُهَا عِ[f:264[ند]َ رَبِّى‌ۖ لَا يُجَلِّيهَا لِوَ[q:5173[قْ]تِه[o[َآ] إِلَّا هُوَ‌ۚ ثَقُلَتْ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ لَا تَأْتِيكُمْ إِلَّا بَغْتَ[a:5174[ةً‌ۗ ي]َسْــَٔلُونَكَ كَأَ[g[نّ]َكَ حَفِىٌّ عَنْهَا‌ۖ قُلْ إِ[g[نّ]َمَا عِلْمُهَا عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Сендан соати қачон собит бўлиши ҳақида сўрарлар. Сен: «Унинг илми фақат Роббим ҳузуридадир. Уни фақат Ўзигина зоҳир қиладир. У осмонлару ерда оғир иш бўладир. Сизларга фақат тўсатдан келадир», деб айт. Худди сен уни билишинг керакдек, сендан сўрарлар. Сен: «Унинг илми фақат Аллоҳнинг ҳузуридадир. Лекин кўп одамлар билмаслар.",174,9],["قُل لّ[o[َآ] أَمْلِكُ لِنَفْسِى نَفْ[a:5175[عًا و]َلَا ضَرًّا إِلَّا مَا ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ‌ۚ وَلَوْ كُ[f:2917[نت]ُ أَعْلَمُ [h:4067[ٱ]لْغَيْبَ لَ[h:5176[ٱ]سْتَكْثَرْتُ مِنَ [h:5177[ٱ]لْخَيْرِ وَمَا مَسَّنِىَ [h:5178[ٱ][l[ل]سّ[o[ُو]ٓءُ‌ۚ إِنْ أَنَا۟ إِلَّا نَذِي[a:5179[رٌ و]َبَشِي[u:5180[رٌ ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Ўзим учун на фойда ва на зарарга молик эмасман. Магар Аллоҳнинг хоҳлагани бўлади. Агар ғайбни билганимда яхшиликни кўпайтириб олган бўлар эдим ва менга ёмонлик етмасди. Мен фақат иймон келтирадиган қавмлар учун огоҳлантирувчи ва башорат берувчиман, холос», деб айт.",175,9],["۞ هُوَ [h:153[ٱ]لَّذِى خَلَقَك[w:2530[ُم م]ّ[a:2531[ِن ن]َّفْ[a:2532[سٍ و][n[َٲ]حِدَ[a:5181[ةٍ و]َجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا‌ۖ فَلَ[g[مّ]َا تَغَشَّ[n[ـٰ]هَا حَمَلَتْ حَمْلاً خَفِي[f:5182[فًا ف]َمَرَّتْ بِه[n[ِۦ]‌ۖ فَلَ[g[مّ][o[َآ] أَثْقَلَ[d:5183[ت] دَّعَوَا [h:5184[ٱ]للَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَ[n[ـٰ]لِ[u:5185[حًا ل]َّنَكُونَ[g[نّ]َ مِنَ [h:4134[ٱ][l[ل]شَّ[n[ـٰ]كِر[p[ِي]نَ","У сизларни бир жондан яратган ва ором олсин учун ундан жуфтини яратган Зотдир. Вақтики у ўраганида енгил ҳомиладор бўлди. Бас, у билан юрди. У оғирлашганда эса, икковлон Роббилари Аллоҳга: «Агар бизга солиҳ берсанг, албатта, шукр келтирувчилардан бўламиз», деб дуо қилдилар.",175,9],["فَلَ[g[مّ][o[َآ] ءَاتَ[n[ـٰ]هُمَا صَ[n[ـٰ]لِ[f:5186[حًا ج]َعَلَا لَهُ[n[ۥ] شُرَك[o[َا]ٓءَ فِيم[o[َآ] ءَاتَ[n[ـٰ]هُمَا‌ۚ فَتَعَ[n[ـٰ]لَى [h:5187[ٱ]للَّهُ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","Уларга солиҳ ни берганида эса, Аллоҳ берган нарсада Унга шериклар қила бошладилар. Аллоҳ улар келтирган ширкдан олийдир.",175,9],["أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـ[a:5188[ـًٔا و]َهُمْ يُخْلَق[p[ُو]نَ","Ҳеч нарсани ярата олмайдиган, ўзлари яратиладиган нарсаларни ширк келтирадиларми?",175,9],["وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْ[a:5189[رًا و]َل[o[َآ] أَ[f:38[نف]ُسَهُمْ يَ[f:5190[نص]ُر[p[ُو]نَ","Ва уларга ёрдам беришга қодир эмаслар ҳамда ўзларига ҳам ёрдам бера олмаслар.",175,9],["وَإِ[f:5191[ن ت]َ[q:5192[دْ]عُوهُمْ إِلَى [h:4178[ٱ]لْهُدَىٰ لَا يَتَّبِعُوكُمْ‌ۚ سَو[o[َا]ٓءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَ[f:428[نت]ُمْ صَ[n[ـٰ]مِت[p[ُو]نَ","Агар уларни ҳидоятга даъват қилсангиз, сизга эргашмаслар. Уларни даъват қиласизми ёки жим турувчи бўласизми, сиз учун барибир.",175,9],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ تَ[q:4040[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ عِبَادٌ أَمْثَالُكُمْ‌ۖ فَ[h:5193[ٱ][q:5193[دْ]عُوهُمْ فَلْيَسْتَجِيبُو[s[اْ] لَكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Албатта, сиз Аллоҳдан ўзга ибодат қилаётганлар ўзингизга ўхшаш бандалардир. Агар ростгўй бўлсангиз, уларни чақириб кўринг, бас, сизга жавоб берсинлар-чи!",175,9],["أَلَهُمْ أَرْجُ[a:5194[لٌ ي]َمْشُونَ بِه[o[َآ‌ۖ] أَمْ لَهُمْ أَيْ[a:5195[دٍ ي]َ[q:5196[بْ]طِشُونَ بِه[o[َآ‌ۖ] أَمْ لَهُمْ أَعْيُ[a:5197[نٌ ي]ُ[q:60[بْ]صِرُونَ بِه[o[َآ‌ۖ] أَمْ لَهُمْ ءَاذَا[a:5198[نٌ ي]َسْمَعُونَ بِهَا‌ۗ قُلِ [h:5199[ٱ][q:4751[دْ]عُو[s[اْ] شُرَك[o[َا]ٓءَكُمْ ثُ[g[مّ]َ كِيدُونِ فَلَا تُ[f:5200[نظ]ِر[p[ُو]نِ","Ёки уларнинг оёқлари бормики, юрсалар; ёки қўллари бормики, ушласалар; ёки кўзлари бормики, кўрсалар; ёки қулоқлари бормики, эшитсалар. Сен: «Шерикларингизни чақиринг-да, менга ҳеч муҳлат бермай, зиддимга ҳийла-найранг қилаверинг!",175,9],["إِ[g[نّ]َ وَلِــِّۧىَ [h:5201[ٱ]للَّهُ [h:4738[ٱ]لَّذِى نَزَّلَ [h:898[ٱ]لْكِتَ[n[ـٰ]بَ‌ۖ وَهُوَ يَتَوَلَّى [h:5202[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Албатта, менинг валий–эгам Китобни нозил қилган Аллоҳдир. У солиҳларни дўст тутадир.",176,9],["وَ[h:9999[ٱ]لَّذِينَ تَ[q:4040[دْ]عُونَ مِ[f:3136[ن د]ُونِه[n[ِۦ] لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَل[o[َآ] أَ[f:38[نف]ُسَهُمْ يَ[f:5190[نص]ُر[p[ُو]نَ","Ундан ўзга сиз ибодат қилаётганлар сизга ёрдам беришга қодир эмаслар ва ўзларига ҳам ёрдам бера олмаслар.",176,9],["وَإِ[f:5191[ن ت]َ[q:5192[دْ]عُوهُمْ إِلَى [h:4178[ٱ]لْهُدَىٰ لَا يَسْمَعُو[s[اْ‌ۖ] وَتَرَ[n[ٮٰ]هُمْ يَ[f:1141[نظ]ُرُونَ إِلَيْكَ وَهُمْ لَا يُ[q:60[بْ]صِر[p[ُو]نَ","Агар уларни ҳидоятга даъват қилсангиз, эшитмаслар. Уларни сенга назар солиб тургандек кўрасан. Ҳолбуки, улар кўрмаслар», деб айт.",176,9],["خُذِ [h:5203[ٱ]لْعَفْوَ وَأْمُرْ بِ[h:5204[ٱ]لْعُرْفِ وَأَعْرِضْ عَنِ [h:5205[ٱ]لْجَ[n[ـٰ]هِل[p[ِي]نَ","Кечиримли бўл, яхшиликка буюр ва жоҳиллардан юз ўгир.",176,9],["وَإِ[g[مّ]َا يَ[f:5206[نز]َغَ[g[نّ]َكَ مِنَ [h:1870[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ نَزْ[f:5207[غٌ ف]َ[h:5208[ٱ]سْتَعِذْ بِ[h:32[ٱ]للَّهِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] سَمِيعٌ عَل[p[ِي]مٌ","Агар сенга шайтон томонидан санчиш санчилса, Аллоҳдан паноҳ сўра. Албатта, У яхши эшитувчи ва яхши кўрувчи Зотдир.",176,9],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ [h:2523[ٱ]تَّقَوْ[s[اْ] إِذَا مَسَّهُمْ طَ[o[ـٰٓ]ئِ[a:5209[فٌ م]ِّنَ [h:1870[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ تَذَكَّرُو[s[اْ] فَإِذَا ه[w:5210[ُم م]ُّ[q:5211[بْ]صِر[p[ُو]نَ","Тақво қилувчилар, агар уларга шайтондан бир шарпа етса, зикр қиларлар, бас, кўрибсанки, улар кўрувчи бўлиб турибдилар.",176,9],["وَإِخْو[n[َٲ]نُهُمْ يَمُدُّونَهُمْ فِى [h:5212[ٱ]لْغَىِّ ثُ[g[مّ]َ لَا يُ[q:5213[قْ]صِر[p[ُو]نَ","Ва уларнинг биродарлари йўлдан оздиришда уларга мадад берадилар, сўнгра бунда тўхтамаслар.",176,9],["وَإِذَا لَمْ تَأْتِه[c:5214[ِم ب]ِـَٔـايَ[f:5215[ةٍ ق]َالُو[s[اْ] لَوْلَا [h:5216[ٱ][q:5217[جْ]تَبَيْتَهَا‌ۚ قُلْ إِ[g[نّ]َم[o[َآ] أَتَّبِعُ مَا يُوحَ[o[ىٰٓ] إِلَىَّ م[u:4098[ِن ر]َّبِّى‌ۚ هَ[n[ـٰ]ذَا بَص[o[َا]ٓئِرُ م[u:243[ِن ر]َّبِّكُمْ وَهُ[a:4547[دًى و]َرَحْمَ[u:5218[ةٌ ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Ва агар уларга мўъжиза келтирмасанг, «Ўзинг тўқиб қўявермайсанми?» дейдилар. Сен: «Мен фақат Роббимдан ваҳий қилинган нарсага эргашаман, холос. Мана бу–иймон келтирувчи қавм учун Роббингиздан кўз очувчи, ҳидоят ва раҳматдир», деб айт.",176,9],["وَإِذَا قُرِئَ [h:5219[ٱ]لْقُرْءَانُ فَ[h:5220[ٱ]سْتَمِعُو[s[اْ] لَهُ[n[ۥ] وَأَ[f:5221[نص]ِتُو[s[اْ] لَعَلَّكُمْ تُرْحَم[p[ُو]نَ","Қуръон тиловат қилганда уни тингланглар ва жим туринглар, шояд раҳматга эришсангиз.",176,9],["وَ[h:9999[ٱ]ذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّ[a:5222[عًا و]َخِيفَ[a:5223[ةً و]َدُونَ [h:5224[ٱ]لْجَهْرِ مِنَ [h:3107[ٱ]لْقَوْلِ بِ[h:5225[ٱ]لْغُدُوِّ وَ[h:5226[ٱ]لْأَصَالِ وَلَا تَك[a:1974[ُن م]ِّنَ [h:5227[ٱ]لْغَ[n[ـٰ]فِل[p[ِي]نَ","Роббингни эртаю кеч ичингда тазарруъла, қўрқиб овоз чиқариб, гапирмай зикр қил ва ғофиллардан бўлма.",176,9],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ عِ[f:264[ند]َ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِه[n[ِۦ] وَيُسَبِّحُونَهُ[n[ۥ] وَلَهُ[n[ۥ] يَسْجُدُ[p[و]نَ ۩","Роббинг ҳузуридагилар, албатта, Унинг ибодатидан мутакаббирлик қилмаслар, Уни поклаб ёд этарлар ва Унга сажда қиларлар.",176,9]]},{"n":8,"ar":"الأَنفَالِ","en":"Al-Anfaal","uz":"Анфол","type":"Мадина","ayahs":[["يَسْــَٔلُونَكَ عَنِ [h:5228[ٱ]لْأَ[f:5229[نف]َالِ‌ۖ قُلِ [h:5230[ٱ]لْأَ[f:5231[نف]َالُ لِلَّهِ وَ[h:2421[ٱ][l[ل]رَّسُولِ‌ۖ فَ[h:112[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَصْلِحُو[s[اْ] ذَاتَ بَيْنِكُمْ‌ۖ وَأَطِيعُو[s[اْ] [h:2238[ٱ]للَّهَ وَرَسُولَهُ[o[ۥٓ] إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Сендан ўлжалар ҳақида сўрарлар. Сен: «Ўлжалар Аллоҳ ва Пайғамбарникидир. Бас, Аллоҳга тақво қилинглар ва ўз ораларингизни ислоҳ этинглар. Агар мўмин бўлсангиз, Аллоҳга ва Унинг Пайғамбарига итоат қилинглар», деб айт.",177,9],["إِ[g[نّ]َمَا [h:5232[ٱ]لْمُؤْمِنُونَ [h:5233[ٱ]لَّذِينَ إِذَا ذُكِرَ [h:5234[ٱ]للَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَ[n[ـٰ]تُهُ[n[ۥ] زَادَتْهُمْ إِيمَ[n[ـٰ][a:5235[نًا و]َعَلَىٰ رَبِّهِمْ يَتَوَكَّل[p[ُو]نَ","Албатта, Аллоҳ зикр қилинса, қалблари титрагувчи, оятлари тиловат этилса, иймонларини зиёда қилгувчи ва Роббиларига таваккул қилгувчиларгина мўминлардир.",177,9],["ٱلَّذِينَ يُقِيمُونَ [h:3638[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَمِ[g[مّ]َا رَزَ[q:15[قْ]نَ[n[ـٰ]هُمْ يُ[f:16[نف]ِق[p[ُو]نَ","Улар намозни тўкис адо этадиганлар ва Биз ризқ қилиб берган нарсалардан инфоқ қиладиганлардир.",177,9],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:5236[ٱ]لْمُؤْمِنُونَ حَق[u:5237[ًّا‌ۚ ل]َّهُمْ دَرَجَ[n[ـٰ]تٌ عِ[f:264[ند]َ رَبِّهِمْ وَمَغْفِرَ[a:5238[ةٌ و]َرِزْ[f:5239[قٌ ك]َر[p[ِي]مٌ","Ана ўшалар ҳақиқий мўминлардир. Уларга Роббилари ҳузурида даражалар, мағфират ва карамли ризқ бор.",177,9],["كَم[o[َآ] أَخْرَجَكَ رَبُّكَ م[i:5240[ِنۢ ب]َيْتِكَ بِ[h:370[ٱ]لْحَقِّ وَإِ[g[نّ]َ فَرِي[a:2128[قًا م]ِّنَ [h:3047[ٱ]لْمُؤْمِنِينَ لَكَ[n[ـٰ]رِه[p[ُو]نَ","Албатта, бу ҳолат, мўминлардан бир гуруҳи ёқтирмаган бўлсалар ҳам, Роббинг сени ҳақ ила уйингдан чиқарганга ўхшайди.",177,9],["يُجَ[n[ـٰ]دِلُونَكَ فِى [h:5241[ٱ]لْحَقِّ بَعْدَ مَا تَبَيَّنَ كَأَ[g[نّ]َمَا يُسَاقُونَ إِلَى [h:5242[ٱ]لْمَوْتِ وَهُمْ يَ[f:1141[نظ]ُر[p[ُو]نَ","Худди ўзлари кўриб турган ҳолларида ўлимга ҳайдалаётгандек, ҳақ аён бўлгандан кейин ҳам сен билан баҳслашарлар.",177,9],["وَإِذْ يَعِدُكُمُ [h:5243[ٱ]للَّهُ إِحْدَى [h:5244[ٱ][l[ل]طّ[o[َا]ٓئِفَتَيْنِ أَ[g[نّ]َهَا لَكُمْ وَتَوَدُّونَ أَ[g[نّ]َ غَيْرَ ذَاتِ [h:5245[ٱ][l[ل]شَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ [h:5246[ٱ]للَّهُ أ[a:5247[َن ي]ُحِقَّ [h:5248[ٱ]لْحَقَّ بِكَلِمَ[n[ـٰ]تِه[n[ِۦ] وَيَ[q:5249[قْ]طَعَ دَابِرَ [h:5250[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Ўшанда Аллоҳ сизга икки тоифадан бири албатта, сизники бўлишини ваъда қилган эди. Сизлар шавкати йўғи сизларники бўлишини суяр эдингиз. Аллоҳ эса, Ўз калималари ила ҳақни ҳақ қилишни ва кофирларнинг думини қирқишни ирода қилган эди.",177,9],["لِيُحِقَّ [h:5251[ٱ]لْحَقَّ وَيُ[q:5252[بْ]طِلَ [h:5253[ٱ]لْبَ[n[ـٰ]طِلَ وَلَوْ كَرِهَ [h:5254[ٱ]لْمُ[q:5255[جْ]رِم[p[ُو]نَ","Жиноятчилар ёқтирмасалар ҳам, ҳақни ҳақ, ботилни ботил қилиш учун шундай бўлишини ирода қилган эди.",177,9],["إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَ[h:5256[ٱ]سْتَجَابَ لَكُمْ أَ[g[نّ]ِى مُمِدُّك[c:5257[ُم ب]ِأَلْ[a:5258[فٍ م]ِّنَ [h:2217[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ مُرْدِف[p[ِي]نَ","Ўшанда Роббингиздан мадад сўраганингизда, сизни ижобат қилиб: «Албатта, мен сизларга кетма-кет келадиган мингта фаришта ила мадад берувчиман», деди.",178,9],["وَمَا جَعَلَهُ [h:2224[ٱ]للَّهُ إِلَّا بُشْرَىٰ وَلِتَ[q:2225[طْ]مَئِ[g[نّ]َ بِه[n[ِۦ] قُلُوبُكُمْ‌ۚ وَمَا [h:2227[ٱ][l[ل][g[نّ]َصْرُ إِلَّا مِنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَزِيزٌ حَك[p[ِي]مٌ","Аллоҳ уни башорат ва қалбларингиз у билан хотиржам бўлиши учунгина қилди. Ғалаба эса, фақат Аллоҳнинг ҳузуридадир. Албатта, Аллоҳ ғолиб ва ҳикматли зотдир.",178,9],["إِذْ يُغَشِّيكُمُ [h:5259[ٱ][l[ل][g[نّ]ُعَاسَ أَمَنَ[a:5260[ةً م]ِّنْهُ وَيُنَزِّلُ عَلَيْك[w:1301[ُم م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[u:5261[ءً ل]ِّيُطَهِّرَك[c:5262[ُم ب]ِه[n[ِۦ] وَيُذْهِبَ عَ[f:255[نك]ُمْ رِ[q:5263[جْ]زَ [h:5264[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ [h:5265[ٱ]لْأَ[q:5266[قْ]د[p[َا]مَ","Ўшанда У сизни Ўзидан омонлик қилиб, мудроқ ила ўраган эди ва сизни поклаш, сиздан шайтоннинг васвасасини кетказиш ҳамда қалбларингизни боғлаш ва қадамларингизни собит қилиш учун устингизга осмондан сув туширган эди.",178,9],["إِذْ يُوحِى رَبُّكَ إِلَى [h:5267[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ أَ[g[نّ]ِى مَعَكُمْ فَثَبِّتُو[s[اْ] [h:5268[ٱ]لَّذِينَ ءَامَنُو[s[اْ‌ۚ] سَأُلْقِى فِى قُلُوبِ [h:2312[ٱ]لَّذِينَ كَفَرُو[s[اْ] [h:2313[ٱ][l[ل]رُّعْبَ فَ[h:5269[ٱ]ضْرِبُو[s[اْ] فَوْقَ [h:5270[ٱ]لْأَعْنَاقِ وَ[h:5271[ٱ]ضْرِبُو[s[اْ] مِنْهُمْ كُلَّ بَن[p[َا]نٍ","Ўшанда Роббингиз фаришталарга: «Мен, албатта, сиз биланман, бас, сиз иймон келтирганларни собит қилинг, тезда куфр келтирганларнинг қалбларига қўрқинч соламан. Бас, бўйинлар устидан зарба беринглар ва ҳамма бармоқларига зарба беринглар», деб ваҳий қилган эди.",178,9],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ ش[m[َا]ٓقُّو[s[اْ] [h:5272[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ]‌ۚ وَم[a:3131[َن ي]ُشَاقِقِ [h:5273[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ شَدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Бу уларнинг Аллоҳга ва Унинг Расулига қарши турганлари учундир. Ким Аллоҳга ва Унинг Расулига қарши турса, бас, албатта, Аллоҳнинг иқоби шиддатлидир.",178,9],["ذ[n[َٲ]لِكُمْ فَذُوقُوهُ وَأَ[g[نّ]َ لِلْكَ[n[ـٰ]فِرِينَ عَذَابَ [h:1110[ٱ][l[ل][g[نّ][p[َا]رِ","Мана шу сизники, тортаверинглар! Албатта, кофирларга дўзах азоби бордир.",178,9],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا لَقِيتُمُ [h:5274[ٱ]لَّذِينَ كَفَرُو[s[اْ] زَحْ[f:5275[فًا ف]َلَا تُوَلُّوهُمُ [h:5276[ٱ]لْأَ[q:2168[دْ]ب[p[َا]رَ","Эй иймон келтирганлар, куфр келтирганларга яқинлашиб, юзма-юз келганингизда уларга орқа ўгирмангиз.",178,9],["وَم[a:5277[َن ي]ُوَلِّهِمْ يَوْمَئِ[f:5278[ذٍ د]ُبُرَهُ[o[ۥٓ] إِلَّا مُتَحَرِّ[u:5279[فًا ل]ِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَ[f:5280[ةٍ ف]َقَ[q:563[دْ] ب[o[َا]ٓءَ بِغَضَ[a:320[بٍ م]ِّنَ [h:321[ٱ]للَّهِ وَمَأْوَ[n[ٮٰ]هُ جَهَ[g[نّ]َمُ‌ۖ وَبِئْسَ [h:665[ٱ]لْمَص[p[ِي]رُ","Кимки ўша кунда жанг ҳунари кўрсатиб ёки бошқа гуруҳга қўшилмоқчи бўлган ҳолатдан ташқари уларга орқа ўгириб қочса, бас, батаҳқиқ, Аллоҳдан бўлган ғазаб ила қайтибди. Унинг жойи жаҳаннамдир. У қандай ҳам ёмон жой.",178,9],["فَلَمْ تَ[q:5281[قْ]تُلُوهُمْ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ قَتَلَهُمْ‌ۚ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ رَمَىٰ‌ۚ وَلِيُ[q:5282[بْ]لِىَ [h:5283[ٱ]لْمُؤْمِنِينَ مِنْهُ بَل[o[َا]ٓءً حَسَنًا‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَمِيعٌ عَل[p[ِي]مٌ","Уларни сиз ўлдирмадингиз, балки Аллоҳ ўлдирди. Отган пайитингда, сен отмадинг, балки Аллоҳ отди. Ва мўминларни гўзал синов ила синаш учун. Албатта, Аллоҳ эшитгувчи ва билгувчи зотдир.",179,9],["ذ[n[َٲ]لِكُمْ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ مُوهِنُ كَيْدِ [h:5284[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Ана ўшалар Аллоҳ, албатта, кофирларнинг ҳийласини заиф қилгувчи бўлганидандир.",179,9],["إِ[f:5285[ن ت]َسْتَفْتِحُو[s[اْ] فَقَ[q:563[دْ] ج[o[َا]ٓءَكُمُ [h:5286[ٱ]لْفَتْحُ‌ۖ وَإِ[f:5287[ن ت]َ[f:5288[نت]َهُو[s[اْ] فَهُوَ خَيْ[u:263[رٌ ل]َّكُمْ‌ۖ وَإِ[f:5289[ن ت]َعُودُو[s[اْ] نَعُ[q:5290[دْ] وَلَ[f:5291[ن ت]ُغْنِىَ عَ[f:255[نك]ُمْ فِئَتُكُمْ شَيْـ[a:5292[ـًٔا و]َلَوْ كَثُرَتْ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ مَعَ [h:3234[ٱ]لْمُؤْمِن[p[ِي]نَ","Агар орани очишни сўраган бўлсангиз, бас, батаҳқиқ сизга орани очиш келди. Агар тўхтасангиз, бу ўзингиз учун яхшидир. Агар сиз қайтсангиз, Биз ҳам қайтамиз. Сизнинг гуруҳингиз қанча кўп бўлса ҳам, сизга ҳеч бир ҳожатингизни чиқара олмас. Албатта, Аллоҳ мўминлар билан биргадир.",179,9],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَطِيعُو[s[اْ] [h:1855[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] وَلَا تَوَلَّوْ[s[اْ] عَنْهُ وَأَ[f:98[نت]ُمْ تَسْمَع[p[ُو]نَ","Эй иймон келтирганлар! Аллоҳга ва Унинг Расулига итоат қилингиз ва эшитиб туриб, ундан юз ўгириб кетмангиз.",179,9],["وَلَا تَكُونُو[s[اْ] كَ[h:2146[ٱ]لَّذِينَ قَالُو[s[اْ] سَمِعْنَا وَهُمْ لَا يَسْمَع[p[ُو]نَ","Ва ўзлари эшитмасалар ҳам, «эшитдик» деганлар каби бўлмангиз.",179,9],["۞ إِ[g[نّ]َ شَرَّ [h:5293[ٱ][l[ل]دَّو[m[َا]ٓبِّ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ [h:5294[ٱ][l[ل]صُّ[g[مّ]ُ [h:5295[ٱ]لْبُكْمُ [h:5296[ٱ]لَّذِينَ لَا يَعْقِل[p[ُو]نَ","Аллоҳнинг ҳузурида ҳайвоннинг энг ёмони, албатта, кару соқов бўлиб, ақл ишлатмайдиганлардир.",179,9],["وَلَوْ عَلِمَ [h:986[ٱ]للَّهُ فِيهِمْ خَيْ[u:5297[رًا ل]َّأَسْمَعَهُمْ‌ۖ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّو[s[اْ] وَّه[w:1817[ُم م]ُّعْرِض[p[ُو]نَ","Агар Аллоҳ уларда бирор яхшиликни билганида, албатта, эшиттирар эди ва агар уларга эшиттирса ҳам, албатта, юз ўгириб, бурилиб кетар эдилар.",179,9],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:5298[ٱ]سْتَجِيبُو[s[اْ] لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ‌ۖ وَ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَحُولُ بَيْنَ [h:532[ٱ]لْمَرْءِ وَقَلْبِه[n[ِۦ] وَأَ[g[نّ]َهُ[o[ۥٓ] إِلَيْهِ تُحْشَر[p[ُو]نَ","Эй иймон келтирганлар! Сизга ҳаёт берадиган нарсага чақирганларида Аллоҳ ва Расулига жавоб беринг ва билинки, албатта, Аллоҳ киши билан унинг қалбини ажратиб қўяди ва, албатта, Унинг ҳузурида тўпланурсиз.",179,9],["وَ[h:9999[ٱ]تَّقُو[s[اْ] فِتْنَ[u:5299[ةً ل]َّا تُصِيبَ[g[نّ]َ [h:5300[ٱ]لَّذِينَ ظَلَمُو[s[اْ] مِ[f:344[نك]ُمْ خ[m[َا]ٓصَّ[a:5301[ةً‌ۖ و]َ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ شَدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Ва сизлардан фақат зулм қилганларнинг ўзигагина етмайдиган фитнадан сақланинг. Ва билинки, албатта, Аллоҳнинг иқоби шиддатлидир.",179,9],["وَ[h:9999[ٱ]ذْكُر[o[ُوٓ][s[اْ] إِذْ أَ[f:428[نت]ُمْ قَلِي[a:5302[لٌ م]ُّسْتَضْعَفُونَ فِى [h:44[ٱ]لْأَرْضِ تَخَافُونَ أ[a:5303[َن ي]َتَخَطَّفَكُمُ [h:5304[ٱ][l[ل][g[نّ]َاسُ فَـَٔـاوَ[n[ٮٰ]كُمْ وَأَيَّدَك[c:5305[ُم ب]ِنَصْرِه[n[ِۦ] وَرَزَقَك[w:5306[ُم م]ِّنَ [h:5307[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تِ لَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Сиз ер юзида оз сонли, заифҳол бўлиб, одамлар сизни тутиб олишидан қўрқиб юрган ҳолингизни эсланг. Бас, У зот сизга жой берди, Ўз нусрати ила қўллади ва сизларга пок нарсаларни ризқ қилиб берди. Шоядки шукр қилсангиз.",180,9],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَخُونُو[s[اْ] [h:5308[ٱ]للَّهَ وَ[h:1856[ٱ][l[ل]رَّسُولَ وَتَخُون[o[ُوٓ][s[اْ] أَمَ[n[ـٰ]نَ[n[ـٰ]تِكُمْ وَأَ[f:98[نت]ُمْ تَعْلَم[p[ُو]نَ","Эй иймон келтирганлар, билиб туриб, Аллоҳга, Пайғамбарга ва омонатларингизга хиёнат қилманг.",180,9],["وَ[h:9999[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َم[o[َآ] أَمْو[n[َٲ]لُكُمْ وَأَوْلَ[n[ـٰ]دُكُمْ فِتْنَ[a:5309[ةٌ و]َأَ[g[نّ]َ [h:859[ٱ]للَّهَ عِ[f:719[ند]َهُ[o[ۥٓ] أَ[q:2423[جْ]رٌ عَظ[p[ِي]مٌ","Ва билингки, молларингиз ва фарзандларингиз фитнадан ўзга нарса эмас ва, албатта, Аллоҳнинг ҳузурида улуғ ажр бордир.",180,9],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[f:5310[ن ت]َتَّقُو[s[اْ] [h:5311[ٱ]للَّهَ يَ[q:4397[جْ]عَل لَّكُمْ فُرْقَا[a:5312[نًا و]َيُكَفِّرْ عَ[f:255[نك]ُمْ سَيِّـَٔـاتِكُمْ وَيَغْفِرْ لَكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ ذُو [h:550[ٱ]لْفَضْلِ [h:551[ٱ]لْعَظ[p[ِي]مِ","Эй иймон келтирганлар! Агар Аллоҳга тақво қилсангиз, сизга фурқон беради, сизнинг гуноҳларингизни ювиб, мағфират қиладир. Аллоҳ улуғ фазл эгасидир.",180,9],["وَإِذْ يَمْكُرُ بِكَ [h:5313[ٱ]لَّذِينَ كَفَرُو[s[اْ] لِيُثْبِتُوكَ أَوْ يَ[q:5314[قْ]تُلُوكَ أَوْ يُخْرِجُوكَ‌ۚ وَيَمْكُرُونَ وَيَمْكُرُ [h:5315[ٱ]للَّهُ‌ۖ وَ[h:72[ٱ]للَّهُ خَيْرُ [h:1960[ٱ]لْمَ[n[ـٰ]كِر[p[ِي]نَ","Куфр келтирганларнинг сени ушлаш, ўлдириш ёки чиқариб юбориш учун макр қилганларини эсла. Улар макр қилдилар ва Аллоҳ ҳам «макр» қилди. Аллоҳ «макр» қилгувчиларнинг устасидир.",180,9],["وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَ[n[ـٰ]تُنَا قَالُو[s[اْ] قَ[q:298[دْ] سَمِعْنَا لَوْ نَش[o[َا]ٓءُ لَقُلْنَا مِثْلَ هَ[n[ـٰ]ذ[o[َآ‌ۙ] إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلّ[o[َآ] أَسَ[n[ـٰ]طِيرُ [h:3993[ٱ]لْأَوَّل[p[ِي]نَ","Уларга оятларимиз тиловат қилинса: «Батаҳқиқ, эшитдик, агар ҳоҳласак, бунга ўхшашни ўзимиз ҳам айтамиз. Бу аввалгиларнинг афсонасидан ўзга нарса эмас», дерлар.",180,9],["وَإِذْ قَالُو[s[اْ] [h:5316[ٱ][l[ل]لَّهُ[g[مّ]َ إِ[f:2594[ن ك]َانَ هَ[n[ـٰ]ذَا هُوَ [h:5317[ٱ]لْحَقَّ مِنْ عِ[f:2954[ند]ِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَ[a:5318[ةً م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ أَوِ [h:5319[ٱ]ئْتِنَا بِعَذَابٍ أَل[p[ِي]مٍ","«Эй бор Худоё, агар мана шу Сенинг ҳузурингдан келган ҳақ бўлса, устимизга осмондан тош ёғдиргин ёки бизга аламли азоб юборгин», деганларини эсла.",180,9],["وَمَا كَانَ [h:742[ٱ]للَّهُ لِيُعَذِّبَهُمْ وَأَ[f:3893[نت]َ فِيهِمْ‌ۚ وَمَا كَانَ [h:742[ٱ]للَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِر[p[ُو]نَ","Модомики сен уларнинг ичида экансан, Аллоҳ уларни азобламас. Модомики улар истиғфор айтар эканлар, Аллоҳ уларни азобламас.",180,9],["وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ [h:5320[ٱ]للَّهُ وَهُمْ يَصُدُّونَ عَنِ [h:3362[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ وَمَا كَان[o[ُوٓ][s[اْ] أَوْلِي[o[َا]ٓءَهُ[o[ۥٓ‌ۚ] إِنْ أَوْلِي[o[َا]ٓؤُهُ[o[ۥٓ] إِلَّا [h:5321[ٱ]لْمُتَّقُونَ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَعْلَم[p[ُو]نَ","Нега энди Аллоҳ уларни азобламас экан. Улар Масжидул Ҳаромдан тўсмоқдалар. Ҳолбуки, унинг валийлари эмаслар. Унинг валийлари тақводорлардан ўзга ҳеч ким эмас. Лекин кўплари билмайдилар.",181,9],["وَمَا كَانَ صَلَاتُهُمْ عِ[f:264[ند]َ [h:5322[ٱ]لْبَيْتِ إِلَّا مُك[o[َا]ٓ[a:5323[ءً و]َتَصْدِيَ[f:5324[ةً‌ۚ ف]َذُوقُو[s[اْ] [h:2154[ٱ]لْعَذَابَ بِمَا كُ[f:100[نت]ُمْ تَكْفُر[p[ُو]نَ","Уларнинг байт олдидаги намозлари ҳуштак ва қарсак чалишдан иборат эди, холос. Бас, куфр келтирганингиз туфайли азобни татиб кўринг.",181,9],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] يُ[f:16[نف]ِقُونَ أَمْو[n[َٲ]لَهُمْ لِيَصُدُّو[s[اْ] عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ‌ۚ فَسَيُ[f:5325[نف]ِقُونَهَا ثُ[g[مّ]َ تَكُونُ عَلَيْهِمْ حَسْرَ[f:5326[ةً ث]ُ[g[مّ]َ يُغْلَبُونَ‌ۗ وَ[h:37[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] إِلَىٰ جَهَ[g[نّ]َمَ يُحْشَر[p[ُو]نَ","Албатта, куфр келтирганлар молларини Аллоҳнинг йўлидан тўсиш учун сарфларлар. Бас, уларни сарфлайдилар-у, сўнгра ўзларига ҳасрат бўладир, кейин маблуғ бўларлар. Куфр келтирганлар жаҳаннамга тўпланурлар.",181,9],["لِيَمِيزَ [h:5327[ٱ]للَّهُ [h:5328[ٱ]لْخَبِيثَ مِنَ [h:2451[ٱ][l[ل]طَّيِّبِ وَيَ[q:2669[جْ]عَلَ [h:5329[ٱ]لْخَبِيثَ بَعْضَهُ[n[ۥ] عَلَىٰ بَعْ[f:5330[ضٍ ف]َيَرْكُمَهُ[n[ۥ] جَمِي[f:5331[عًا ف]َيَ[q:5332[جْ]عَلَهُ[n[ۥ] فِى جَهَ[g[نّ]َمَ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:150[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","Аллоҳ покдан нопокни айириши учун ва нопокнинг баъзиси устига баъзисини тахлаб, ҳаммасини жаҳаннамга ташлаши учун. Ана ўшалар зиён кўргувчилардир.",181,9],["قُل لِّلَّذِينَ كَفَر[o[ُوٓ][s[اْ] إ[a:5333[ِن ي]َ[f:3711[نت]َهُو[s[اْ] يُغْفَرْ لَه[w:3531[ُم م]َّا قَ[q:298[دْ] سَلَفَ وَإ[a:5334[ِن ي]َعُودُو[s[اْ] فَقَ[q:563[دْ] مَضَتْ سُ[g[نّ]َتُ [h:5335[ٱ]لْأَوَّل[p[ِي]نَ","Куфр келтирганларга айт, агар тўхтасалар, ўтган нарсалар мағфират қилинур ва агар қайтадиган бўлсалар, бас, батаҳқиқ, аввалгиларнинг суннати ўтган.",181,9],["وَقَ[n[ـٰ]تِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَ[a:1032[ةٌ و]َيَكُونَ [h:1033[ٱ][l[ل]دِّينُ كُلُّهُ[n[ۥ] لِلَّهِ‌ۚ فَإِنِ [h:1030[ٱ][f:1031[نت]َهَوْ[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ بِمَا يَعْمَلُونَ بَص[p[ِي]رٌ","Ва улар билан то фитна бўлмагунча ва диннинг ҳаммаси Аллоҳга бўлгунча, уруш қилинг. Агар тўхтасалар, бас, Аллоҳ, албатта, нима қилаётганларини кўриб тургувчи зотдир.",181,9],["وَإِ[f:706[ن ت]َوَلَّوْ[s[اْ] فَ[h:1140[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ مَوْلَ[n[ـٰ]كُمْ‌ۚ نِعْمَ [h:5336[ٱ]لْمَوْلَىٰ وَنِعْمَ [h:5337[ٱ][l[ل][g[نّ]َص[p[ِي]رُ","Агар юз ўгирсалар, бас, билгинки, албатта, Аллоҳ хожангиздир. У қандай ҳам яхши хожа ва қандай ҳам яхши нусрат бергувчи!",181,9],["۞ وَ[h:9999[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َمَا غَنِمْت[w:5338[ُم م]ِّ[f:2103[ن ش][f:5339[َىْءٍ ف]َأَ[g[نّ]َ لِلَّهِ خُمُسَهُ[n[ۥ] وَلِلرَّسُولِ وَلِذِى [h:5340[ٱ]لْقُرْبَىٰ وَ[h:420[ٱ]لْيَتَ[n[ـٰ]مَىٰ وَ[h:421[ٱ]لْمَسَ[n[ـٰ]كِينِ وَ[h:1189[ٱ][q:1189[بْ]نِ [h:1190[ٱ][l[ل]سَّبِيلِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ ءَامَ[f:703[نت][c:5341[ُم ب]ِ[h:32[ٱ]للَّهِ وَم[o[َآ] أَ[f:515[نز]َلْنَا عَلَىٰ عَ[q:102[بْ]دِنَا يَوْمَ [h:5342[ٱ]لْفُرْقَانِ يَوْمَ [h:2353[ٱ][l[ل]ْتَقَى [h:2354[ٱ]لْجَمْعَانِ‌ۗ وَ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Ва агар Аллоҳга, фурқон куни-икки жамоат тўқнашган куни бандамизга нозил қилган нарсамизга иймон келтирган бўлсангиз, билингки, ўлжага олган нарсангиздан бешдан бири Аллоҳга, Расулига, яқинларига, етимларга, мискинларга ва мусофирларгадир. Ва Аллоҳ ҳар бир нарсага қодирдир.",182,10],["إِذْ أَ[f:428[نت][c:5343[ُم ب]ِ[h:5344[ٱ]لْعُ[q:5344[دْ]وَةِ [h:5345[ٱ][l[ل]دُّنْيَا وَه[c:5346[ُم ب]ِ[h:5344[ٱ]لْعُ[q:5344[دْ]وَةِ [h:5347[ٱ]لْقُصْوَىٰ وَ[h:5348[ٱ][l[ل]رَّكْبُ أَسْفَلَ مِ[f:344[نك]ُمْ‌ۚ وَلَوْ تَوَاعَ[d:5349[د]تُّمْ لَ[h:5350[ٱ]خْتَلَفْتُمْ فِى [h:5351[ٱ]لْمِيعَ[n[ـٰ]دِ‌ۙ وَلَ[n[ـٰ]ك[u:5352[ِن ل]ِّيَ[q:5353[قْ]ضِىَ [h:5354[ٱ]للَّهُ أَمْ[f:5355[رًا ك]َانَ مَفْعُول[u:5356[اً ل]ِّيَهْلِكَ مَنْ هَلَكَ ع[i:5357[َنۢ ب]َيِّنَ[a:5358[ةٍ و]َيَحْيَىٰ مَنْ حَىَّ ع[i:5357[َنۢ ب]َيِّنَ[a:5359[ةٍ‌ۗ و]َإِ[g[نّ]َ [h:1986[ٱ]للَّهَ لَسَمِيعٌ عَل[p[ِي]مٌ","Ўшанда сизлар яқин тарафида, улар узоқ тарафида, отлиқлар эса, сиздан пастда эди. Агар ваъдалашиб олганингизда ҳам, келишилган жой ва вақтда хилоф қилардингиз. Лекин Аллоҳ қилиниш керак бўлган ишни ҳал этиш учун, ҳалок бўладиган одам очиқ-ойдин ҳужжат билан ҳалок, бўлиши учун, яшаши керак бўлган одам очиқ-ойдин ҳужжат билан яшаши учун. Ва, албатта, Аллоҳ эшитгувчи ва билгувчи зотдир.",182,10],["إِذْ يُرِيكَهُمُ [h:5360[ٱ]للَّهُ فِى مَنَامِكَ قَلِيل[a:5361[اً‌ۖ و]َلَوْ أَرَ[n[ٮٰ]كَهُمْ كَثِي[u:5362[رًا ل]َّفَشِلْتُمْ وَلَتَنَ[n[ـٰ]زَعْتُمْ فِى [h:2319[ٱ]لْأَمْرِ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ سَلَّمَ‌ۗ إِ[g[نّ]َهُ[n[ۥ] عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","Ўшанда Аллоҳ тушингда уларни сенга оз кўрсатди. Агар уларни сенга кўп кўрсатганида, тушкунликка учрар эдингизлар ва бу ишда ораларингизда низо чиқар эди. Лекин Аллоҳ сақлади. Албатта, У дилингиздаги нарсани билгувчи зотдир.",182,10],["وَإِذْ يُرِيكُمُوهُمْ إِذِ [h:5363[ٱ][l[ل]ْتَقَيْتُمْ ف[o[ِىٓ] أَعْيُنِكُمْ قَلِيل[a:5364[اً و]َيُقَلِّلُكُمْ ف[o[ِىٓ] أَعْيُنِهِمْ لِيَ[q:5353[قْ]ضِىَ [h:5354[ٱ]للَّهُ أَمْ[f:5355[رًا ك]َانَ مَفْعُول[a:5365[اً‌ۗ و]َإِلَى [h:1148[ٱ]للَّهِ تُرْجَعُ [h:1149[ٱ]لْأُم[p[ُو]رُ","Ўшанда, тўқнашганингизда уларни сизнинг кўзингизга оз қилиб кўрсатганини, сизни уларнинг кўзига оз қилиб кўрсатганини эсланг. Буни Аллоҳ қилиниши керак бўлган ишни ҳал этиш учун қилди. Ва барча ишлар Аллоҳга қайтарилур.",182,10],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا لَقِيتُمْ فِئَ[f:5366[ةً ف]َ[h:5367[ٱ]ثْبُتُو[s[اْ] وَ[h:335[ٱ]ذْكُرُو[s[اْ] [h:1113[ٱ]للَّهَ كَثِي[u:5368[رًا ل]َّعَلَّكُمْ تُفْلِح[p[ُو]نَ","Эй иймон келтирганлар! жамоатга рўбарў келганингизда, саботли бўлинг ва Аллоҳни кўп зикр қилинг, шоядки нажот топсангиз.",182,10],["وَأَطِيعُو[s[اْ] [h:2238[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] وَلَا تَنَ[n[ـٰ]زَعُو[s[اْ] فَتَفْشَلُو[s[اْ] وَتَذْهَبَ رِيحُكُمْ‌ۖ وَ[h:4939[ٱ]صْبِر[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ مَعَ [h:785[ٱ][l[ل]صَّ[n[ـٰ]بِر[p[ِي]نَ","Аллоҳга ва Унинг Расулига итоат қилинг. Ўзаро низо қилманг, у ҳолда тушкунликка учрайсиз ва куч-қувватингиз кетади. Ва сабр қилинг. Албатта, Аллоҳ сабр қилгувчилар биландир.",183,10],["وَلَا تَكُونُو[s[اْ] كَ[h:2146[ٱ]لَّذِينَ خَرَجُو[s[اْ] مِ[f:432[ن د]ِيَ[n[ـٰ]رِه[c:5369[ِم ب]َطَ[a:5370[رًا و]َرِئ[o[َا]ٓءَ [h:5371[ٱ][l[ل][g[نّ]َاسِ وَيَصُدُّونَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ‌ۚ وَ[h:72[ٱ]للَّهُ بِمَا يَعْمَلُونَ مُح[p[ِي][q[ط]ٌ","Ва диёрларидан кибру ҳаво билан, одамларга риё учун чиқиб, Аллоҳнинг йўлидан тўсадиганларга ўхшаманг. Аллоҳ нима қилаётганларини иҳота қилгувчидир.",183,10],["وَإِذْ زَيَّنَ لَهُمُ [h:4046[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ أَعْمَ[n[ـٰ]لَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ [h:5372[ٱ]لْيَوْمَ مِنَ [h:721[ٱ][l[ل][g[نّ]َاسِ وَإِ[g[نّ]ِى جَا[u:5373[رٌ ل]َّكُمْ‌ۖ فَلَ[g[مّ]َا تَر[o[َا]ٓءَتِ [h:5374[ٱ]لْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِ[g[نّ]ِى بَر[o[ِى]ٓ[a:5375[ءٌ م]ِّ[f:344[نك]ُمْ إِ[g[نّ][o[ِىٓ] أَرَىٰ مَا لَا تَرَوْنَ إِ[g[نّ][o[ِىٓ] أَخَافُ [h:3504[ٱ]للَّهَ‌ۚ وَ[h:72[ٱ]للَّهُ شَدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Ўшанда шайтон уларга амалларини зийнатлаб кўрсатди ва: «Бу кунда одамлардан сизга ғолиб кела оладиган ҳеч ким йўқ. Мен сизнинг ҳомийингизман», деди. Икки жамоа бир-бирини кўрганида эса, орқасига қайтди ва: «Албатта, мен сиз кўрмаётган нарсани кўрмоқдаман. Мен Аллоҳдан қўрқаман. Аллоҳ иқоби шиддатли зотдир», деди.",183,10],["إِذْ يَقُولُ [h:5376[ٱ]لْمُنَ[n[ـٰ]فِقُونَ وَ[h:37[ٱ]لَّذِينَ فِى قُلُوبِه[w:39[ِم م]َّرَضٌ غَرَّ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ دِينُهُمْ‌ۗ وَم[a:5377[َن ي]َتَوَكَّلْ عَلَى [h:412[ٱ]للَّهِ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ عَزِيزٌ حَك[p[ِي]مٌ","Ўшанда мунофиқлар ва дилларида мараз бўлганлар: «Анавиларни дини мағрур қилиб юборди», дедилар. Ким Аллоҳга таваккул қилса, бас, албатта, Аллоҳ ғолиб ва ҳикматли зотдир.",183,10],["وَلَوْ تَرَ[o[ىٰٓ] إِذْ يَتَوَفَّى [h:5378[ٱ]لَّذِينَ كَفَرُو[s[اْ‌ۙ] [h:5379[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَ[q:5380[دْ]بَ[n[ـٰ]رَهُمْ وَذُوقُو[s[اْ] عَذَابَ [h:2465[ٱ]لْحَر[p[ِي][q[ق]ِ","Агар фаришталар куфр келтирганларнинг жонини олатуриб, юзларига ва кетларига уриб: «Ёнғин азобини тотинг!",183,10],["ذ[n[َٲ]لِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ لَيْسَ بِظَلَّ[n[ـٰ][u:2466[مٍ ل]ِّلْعَب[p[ِي][q[د]ِ","Бу қўлингиз тақдим қилган нарса туфайлидир. Албатта, Аллоҳ бандаларига ҳеч зулм қилгувчи эмасдир», дейишларини кўрсанг эди.",183,10],["كَدَأْبِ ءَالِ فِرْعَوْنَ‌ۙ وَ[h:37[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ كَفَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ فَأَخَذَهُمُ [h:1756[ٱ]للَّهُ بِذُنُوبِهِمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ قَوِ[f:5381[ىٌّ ش]َدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Худди Оли Фиръавн ва улардан олдингиларнинг қилмишларига ўхшайдир. Аллоҳнинг оятига куфр келтирдилар. Бас, Аллоҳ уларни гуноҳлари туфайли тутди. Албатта, Аллоҳ кучли ва иқоби шиддатли зотдир.",183,10],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َ [h:897[ٱ]للَّهَ لَمْ يَكُ مُغَيِّ[a:5382[رًا ن]ِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُو[s[اْ] مَا بِأَ[f:4384[نف]ُسِهِمْ‌ۙ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ سَمِيعٌ عَل[p[ِي]مٌ","Бундай бўлиши Аллоҳ бир қавмга берган неъматини токи улар ўзларини ўзгартирмагунларича ўзгартирувчи бўлмаслиги ва Аллоҳ эшитгувчи ва билгувчи зот бўлганидандир.",184,10],["كَدَأْبِ ءَالِ فِرْعَوْنَ‌ۙ وَ[h:37[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ رَبِّهِمْ فَأَهْلَكْنَ[n[ـٰ]ه[c:3936[ُم ب]ِذُنُوبِهِمْ وَأَغْرَ[q:247[قْ]ن[o[َآ] ءَالَ فِرْعَوْنَ‌ۚ وَكُ[f:5383[لٌّ ك]َانُو[s[اْ] ظَ[n[ـٰ]لِم[p[ِي]نَ","Худди Оли Фиръавн ва улардан олдингиларнинг қилмишига ўхшаб, Роббиларининг оятларини ёлғонга чиқардилар. Бас, Биз уларни гуноҳлари туфайли ҳалок қилдик ва Оли Фиръавни ғарқ қилдик. Ҳаммалари золим эдилар.",184,10],["إِ[g[نّ]َ شَرَّ [h:5293[ٱ][l[ل]دَّو[m[َا]ٓبِّ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ [h:5384[ٱ]لَّذِينَ كَفَرُو[s[اْ] فَهُمْ لَا يُؤْمِن[p[ُو]نَ","Албатта, Аллоҳнинг ҳузурида ҳайвоннинг ёмони куфр келтирганларидир. Бас, улар иймон келтирмаслар.",184,10],["ٱلَّذِينَ عَ[n[ـٰ]هَ[d:5385[د]تَّ مِنْهُمْ ثُ[g[مّ]َ يَ[f:144[نق]ُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّ[a:5386[ةٍ و]َهُمْ لَا يَتَّق[p[ُو]نَ","Улардан сен аҳдлашганлар сўнгра ҳар сафар аҳдларини бузарлар ва улар қўрқмаслар.",184,10],["فَإِ[g[مّ]َا تَثْقَفَ[g[نّ]َهُمْ فِى [h:5387[ٱ]لْحَرْبِ فَشَرِّ[q:5388[دْ] بِه[w:5389[ِم م]َّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّر[p[ُو]نَ","Агар урушда улардан зафар қозонсанг, бас, уларни ҳалок қилиш билан ортларидагиларни сарсон қилиб қўй, шоядки эсласалар.",184,10],["وَإِ[g[مّ]َا تَخَافَ[g[نّ]َ مِ[f:3024[ن ق]َوْمٍ خِيَانَ[f:5390[ةً ف]َ[h:5391[ٱ][i:5391[نۢب]ِذْ إِلَيْهِمْ عَلَىٰ سَو[o[َا]ٓءٍ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُحِبُّ [h:5392[ٱ]لْخ[o[َا]ٓئِن[p[ِي]نَ","Агар бир қавмнинг хиёнатидан қўрқадиган бўлсанг, уларга тенгма-тенг ўртага ташла. Албатта, Аллоҳ хоинларни севмас.",184,10],["وَلَا يَحْسَبَ[g[نّ]َ [h:2445[ٱ]لَّذِينَ كَفَرُو[s[اْ] سَبَق[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َهُمْ لَا يُعْجِز[p[ُو]نَ","Куфр келтирганлар ўздик деб ўйламасинлар. Улар ҳеч қочиб қутула олмайдилар.",184,10],["وَأَعِدُّو[s[اْ] لَه[w:3531[ُم م]َّا [h:5393[ٱ]سْتَطَعْت[w:5394[ُم م]ِّ[f:5395[ن ق]ُوَّ[a:5396[ةٍ و]َم[u:5397[ِن ر]ِّبَاطِ [h:5398[ٱ]لْخَيْلِ تُرْهِبُونَ بِه[n[ِۦ] عَدُوَّ [h:5399[ٱ]للَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِ[f:5400[ن د]ُونِهِمْ لَا تَعْلَمُونَهُمُ [h:5401[ٱ]للَّهُ يَعْلَمُهُمْ‌ۚ وَمَا تُ[f:1607[نف]ِقُو[s[اْ] مِ[f:2103[ن ش][f:5402[َىْءٍ ف]ِى سَبِيلِ [h:788[ٱ]للَّهِ يُوَفَّ إِلَيْكُمْ وَأَ[f:98[نت]ُمْ لَا تُظْلَم[p[ُو]نَ","Улар учун қўлингиздан келганича куч-қувват ва эгарланган отларни тайёр қўйингиз, бу билан Аллоҳнинг душманини, ўз душманингизни ва улардан бошқа ўзингиз билмайдиганларни қўрқитасиз. Уларни Аллоҳ биладир. Аллоҳ йўлида нимани сарф қилсангиз, сизга тўлиқ қайтарилур. Сизга зулм қилинмас.",184,10],["۞ وَإِ[f:5403[ن ج]َنَحُو[s[اْ] لِلسَّلْمِ فَ[h:5404[ٱ][q:5404[جْ]نَحْ لَهَا وَتَوَكَّلْ عَلَى [h:412[ٱ]للَّهِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:3721[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Агар улар тинчликка мойил бўлсалар, сен ҳам мойил бўл. Ва Аллоҳга таваккул қил. Албатта, У эшитгувчи ва билгувчи зотдир.",184,10],["وَإ[a:5405[ِن ي]ُرِيد[o[ُوٓ][s[اْ] أ[a:5406[َن ي]َخْدَعُوكَ فَإِ[g[نّ]َ حَسْبَكَ [h:5407[ٱ]للَّهُ‌ۚ هُوَ [h:153[ٱ]لَّذ[o[ِىٓ] أَيَّدَكَ بِنَصْرِه[n[ِۦ] وَبِ[h:5408[ٱ]لْمُؤْمِن[p[ِي]نَ","Агар сени алдашни ирода қилсалар, бас, сенга Аллоҳ кифоя қиладир. У сени Ўз нусрати ва мўминлар билан қўллаган.",185,10],["وَأَلَّفَ بَيْنَ قُلُوبِهِمْ‌ۚ لَوْ أَ[f:5409[نف]َ[q:5409[قْ]تَ مَا فِى [h:44[ٱ]لْأَرْضِ جَمِي[a:5410[عًا م]ّ[o[َآ] أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ أَلَّفَ بَيْنَهُمْ‌ۚ إِ[g[نّ]َهُ[n[ۥ] عَزِيزٌ حَك[p[ِي]مٌ","Ҳамда уларнинг қалбларини бирлаштирган зотдир. Агар ер юзидаги ҳамма нарсани сарф қилсанг ҳам, уларнинг қалбларини бирлаштира олмас эдинг. Лекин Аллоҳ уларни бирлаштирди. Албатта, У ғолиб ва ҳикматли зотдир.",185,10],["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ حَسْبُكَ [h:5412[ٱ]للَّهُ وَمَنِ [h:5413[ٱ]تَّبَعَكَ مِنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Эй Набий, сенга ва сенга эргашганлар мўминларга Аллоҳ кифоядир.",185,10],["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ حَرِّضِ [h:5414[ٱ]لْمُؤْمِنِينَ عَلَى [h:5415[ٱ]لْقِتَالِ‌ۚ إ[a:3202[ِن ي]َك[a:5416[ُن م]ِّ[f:344[نك]ُمْ عِشْرُونَ صَ[n[ـٰ]بِرُونَ يَغْلِبُو[s[اْ] مِ[s[اْ]ئَتَيْنِ‌ۚ وَإ[a:4454[ِن ي]َك[a:5416[ُن م]ِّ[f:344[نك][w:5417[ُم م]ِّ[s[اْ]ئَ[a:5418[ةٌ ي]َغْلِب[o[ُوٓ][s[اْ] أَلْ[a:5419[فًا م]ِّنَ [h:523[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِأَ[g[نّ]َهُمْ قَوْ[u:3651[مٌ ل]َّا يَفْقَه[p[ُو]نَ","Эй Набий, мўминларни жангга чорла! Агар сиздан йигирмата сабрли бўлса, икки юзтани енгадир. Агар сиздан юзта бўлса, куфр келтирганлардан мингтасини енгадир. Бу улар тушунмайдиган қавм бўлганларидандир.",185,10],["ٱلْـَٔ[n[ـٰ]نَ خَفَّفَ [h:5420[ٱ]للَّهُ عَ[f:255[نك]ُمْ وَعَلِمَ أَ[g[نّ]َ فِيكُمْ ضَعْ[f:5421[فًا‌ۚ ف]َإ[a:5422[ِن ي]َك[a:5416[ُن م]ِّ[f:344[نك][w:5417[ُم م]ِّ[s[اْ]ئَ[f:5423[ةٌ ص]َابِرَ[a:5424[ةٌ ي]َغْلِبُو[s[اْ] مِ[s[اْ]ئَتَيْنِ‌ۚ وَإ[a:4454[ِن ي]َك[a:5416[ُن م]ِّ[f:344[نك]ُمْ أَلْ[a:5425[فٌ ي]َغْلِب[o[ُوٓ][s[اْ] أَلْفَيْنِ بِإِذْنِ [h:509[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ مَعَ [h:785[ٱ][l[ل]صَّ[n[ـٰ]بِر[p[ِي]نَ","Энди Аллоҳ сизлардан енгиллаштирди, сизларда ожизлик борлигини билди. Бас, агар сиздан юзта сабрли бўлса, икки юзтани енгадир. Агар сиздан мингта бўлса, Аллоҳнинг изни ила икки мингтани енгадир. Аллоҳ сабрлилар биландир.",185,10],["مَا كَانَ لِنَبِىٍّ أ[a:3312[َن ي]َكُونَ لَهُ[o[ۥٓ] أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى [h:44[ٱ]لْأَرْضِ‌ۚ تُرِيدُونَ عَرَضَ [h:5426[ٱ][l[ل]دُّنْيَا وَ[h:72[ٱ]للَّهُ يُرِيدُ [h:2327[ٱ]لْأَخِرَةَ‌ۗ وَ[h:72[ٱ]للَّهُ عَزِيزٌ حَك[p[ِي]مٌ","Набий учун ер юзида забардаст бўлмагунича асирлари бўлиши яхши эмас эди. Сизлар дунёнинг ўткинчи матоҳини истарсизлар. Аллоҳ эса, охиратни истар. Ва Аллоҳ ғолиб ва ҳикматли зотдир.",185,10],["لَّوْلَا كِتَ[n[ـٰ][a:5427[بٌ م]ِّنَ [h:321[ٱ]للَّهِ سَبَقَ لَمَسَّكُمْ فِيم[o[َآ] أَخَذْتُمْ عَذَابٌ عَظ[p[ِي]مٌ","Агар Аллоҳнинг олдиндан ёзгани бўлмаганида, сизга олган нарсаларингиз туфайли улуғ азоб етар эди.",185,10],["فَكُلُو[s[اْ] مِ[g[مّ]َا غَنِمْتُمْ حَلَ[n[ـٰ]ل[f:870[اً ط]َيِّ[a:3752[بًا‌ۚ و]َ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Бас, ўлжага олган нарсаларингиздан ҳалол-пок ҳолда енглар. Аллоҳга тақво қилинглар. Албатта, Аллоҳ мағфират қилгувчи ва раҳмли зотдир.",185,10],["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ قُل لِّمَ[f:5428[ن ف][o[ِىٓ] أَيْدِيك[w:5429[ُم م]ِّنَ [h:5430[ٱ]لْأَسْرَ[o[ىٰٓ] إ[a:5431[ِن ي]َعْلَمِ [h:2272[ٱ]للَّهُ فِى قُلُوبِكُمْ خَيْ[a:5432[رًا ي]ُؤْتِكُمْ خَيْ[a:5433[رًا م]ِّ[g[مّ][o[َآ] أُخِذَ مِ[f:344[نك]ُمْ وَيَغْفِرْ لَكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Эй Набий, қўлингиздаги асирларга: «Агар Аллоҳ қалбларингизда яхшилик борлигини билса, сизга ўзингиздан олинган нарсадан кўра яхшироқ нарсани берур ва сизни мағфират қилур. Аллоҳ мағфират қилгувчи ва раҳмли зотдир», деб айт!",186,10],["وَإ[a:5405[ِن ي]ُرِيدُو[s[اْ] خِيَانَتَكَ فَقَ[q:563[دْ] خَانُو[s[اْ] [h:5434[ٱ]للَّهَ مِ[f:128[ن ق]َ[q:129[بْ]لُ فَأَمْكَنَ مِنْهُمْ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Агар сенга хиёнат қилишни истасалар, батаҳқиқ, бундан олдин Аллоҳга хиёнат қилган эдилар. Бас У уларга қарши имкон топди. Аллоҳ билгувчи ва ҳикматли зотдир.",186,10],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَهَاجَرُو[s[اْ] وَجَ[n[ـٰ]هَدُو[s[اْ] بِأَمْو[n[َٲ]لِهِمْ وَأَ[f:3050[نف]ُسِهِمْ فِى سَبِيلِ [h:788[ٱ]للَّهِ وَ[h:37[ٱ]لَّذِينَ ءَاوَو[s[اْ] وَّنَصَر[o[ُوٓ][s[اْ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ بَعْضُهُمْ أَوْلِي[o[َا]ٓءُ بَعْ[a:5435[ضٍ‌ۚ و]َ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَلَمْ يُهَاجِرُو[s[اْ] مَا لَك[w:556[ُم م]ّ[a:5436[ِن و]َلَ[n[ـٰ]يَتِه[w:5437[ِم م]ِّ[f:2103[ن ش]َىْءٍ حَتَّىٰ يُهَاجِرُو[s[اْ‌ۚ] وَإِنِ [h:5438[ٱ]سْتَ[f:5439[نص]َرُوكُمْ فِى [h:1477[ٱ][l[ل]دِّينِ فَعَلَيْكُمُ [h:5440[ٱ][l[ل][g[نّ]َصْرُ إِلَّا عَلَىٰ قَوْ[i:3007[مِۭ ب]َيْنَكُمْ وَبَيْنَه[w:3008[ُم م]ِّيثَ[n[ـٰ][a:5441[قٌ‌ۗ و]َ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","Албатта, иймон келтирган, ҳижрат қилган, Аллоҳнинг йўлида молу жонлари билан жиҳод қилганлар ва жой бериб, ёрдам кўрсатганлар, ана ўшалар бир-бирларига валийдирлар. Иймон келтирган, аммо ҳижрат қилмаганларга эса, то ҳижрат қилмагунларича, сиз ҳеч валий бўла олмассиз. Агар улар сиздан динда ёрдам сўрасалар, ёрдам бермоғингиз вожиб. Фақат сиз билан ўрталарида аҳднома бор қавм зиддига эмас. Аллоҳ нима қилаётганингизни кўргувчи зотдир.",186,10],["وَ[h:9999[ٱ]لَّذِينَ كَفَرُو[s[اْ] بَعْضُهُمْ أَوْلِي[o[َا]ٓءُ بَعْضٍ‌ۚ إِلَّا تَفْعَلُوهُ تَكُ[f:5442[ن ف]ِتْنَ[f:5443[ةٌ ف]ِى [h:44[ٱ]لْأَرْضِ وَفَسَا[f:5444[دٌ ك]َب[p[ِي]رٌ","Куфр келтирганлар бир-бирларига валийдирлар. Агар қилмасангиз, ер юзида фитна ва катта фасод бўладир.",186,10],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَهَاجَرُو[s[اْ] وَجَ[n[ـٰ]هَدُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ وَ[h:37[ٱ]لَّذِينَ ءَاوَو[s[اْ] وَّنَصَر[o[ُوٓ][s[اْ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:5236[ٱ]لْمُؤْمِنُونَ حَق[u:5237[ًّا‌ۚ ل]َّه[w:3412[ُم م]َّغْفِرَ[a:5445[ةٌ و]َرِزْ[f:5239[قٌ ك]َر[p[ِي]مٌ","Иймон келтирган, ҳижрат этган, Аллоҳнинг йўлида жиҳод қилганлар ва жой бериб, ёрдам кўрсатганлар, ана ўшалар ҳақ мўминлардир. Улар учун мағфират ва карамли ризқ бордир.",186,10],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] م[i:1287[ِنۢ ب]َعْدُ وَهَاجَرُو[s[اْ] وَجَ[n[ـٰ]هَدُو[s[اْ] مَعَكُمْ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مِ[f:344[نك]ُمْ‌ۚ وَأُ[s[وْ]لُو[s[اْ] [h:5446[ٱ]لْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْ[f:5447[ضٍ ف]ِى كِتَ[n[ـٰ]بِ [h:1816[ٱ]للَّهِ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ بِكُلِّ شَىْءٍ عَل[p[ِي]مُۢ","Кейин иймон келтириб, ҳижрат қилган ва сизлар билан жиҳод қилганлар ҳам сизлардандир. Аллоҳнинг китобида қариндошлар бир-бирларига ҳақлироқдирлар. Албатта, Аллоҳ ҳар бир нарсани билгувчи зотдир.",186,10]]},{"n":9,"ar":"التَّوۡبَةِ","en":"At-Tawba","uz":"Тавба","type":"Мадина","ayahs":[["بَر[o[َا]ٓءَ[a:5448[ةٌ م]ِّنَ [h:321[ٱ]للَّهِ وَرَسُولِه[o[ِۦٓ] إِلَى [h:1372[ٱ]لَّذِينَ عَ[n[ـٰ]هَ[d:5449[د]تّ[w:5450[ُم م]ِّنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Аллоҳдан ва Унинг Расулидан мушрикларнинг сиз аҳдлашганларига «бароат»–ора очиқлик дир.",187,10],["فَسِيحُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ أَرْبَعَةَ أَشْهُ[a:5451[رٍ و]َ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َكُمْ غَيْرُ مُعْجِزِى [h:5452[ٱ]للَّهِ‌ۙ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ مُخْزِى [h:5453[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Бас, ер юзида тўрт ой сайр қилиб юринглар ва билингларки, албатта, сиз Аллоҳни ожиз қолдирувчи эмассиз ва, албатта, Аллоҳ кофирларни хор қилгувчидир.",187,10],["وَأَذ[n[َٲ][a:5454[نٌ م]ِّنَ [h:321[ٱ]للَّهِ وَرَسُولِه[o[ِۦٓ] إِلَى [h:5455[ٱ][l[ل][g[نّ]َاسِ يَوْمَ [h:5456[ٱ]لْحَجِّ [h:5457[ٱ]لْأَكْبَرِ أَ[g[نّ]َ [h:394[ٱ]للَّهَ بَر[o[ِى]ٓ[a:5458[ءٌ م]ِّنَ [h:699[ٱ]لْمُشْرِكِينَ‌ۙ وَرَسُولُهُ[n[ۥ]‌ۚ فَإِ[f:5459[ن ت]ُ[q:1648[بْ]تُمْ فَهُوَ خَيْ[u:263[رٌ ل]َّكُمْ‌ۖ وَإِ[f:5460[ن ت]َوَلَّيْتُمْ فَ[h:1140[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َكُمْ غَيْرُ مُعْجِزِى [h:5452[ٱ]للَّهِ‌ۗ وَبَشِّرِ [h:117[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِعَذَابٍ أَل[p[ِي]مٍ","Аллоҳ ва Унинг Расулидан одамларга «ҳажжул акбар» куниги билдиришдир. Албатта, Аллоҳ ва Унинг Расулининг мушриклар билан оралари очиқдир. Бас, агар тавба қилсангиз, у ўзингиз учун яхшидир. Агар юз ўгириб кетадиган бўлсангиз, билингларки, албатта, сизлар Аллоҳни ожиз қолдирувчи эмассиз. Куфр келтирганларга аламли азобнинг «башоратини» беравер.",187,10],["إِلَّا [h:778[ٱ]لَّذِينَ عَ[n[ـٰ]هَ[d:5449[د]تّ[w:5450[ُم م]ِّنَ [h:699[ٱ]لْمُشْرِكِينَ ثُ[g[مّ]َ لَمْ يَ[f:5461[نق]ُصُوكُمْ شَيْـ[a:5462[ـًٔا و]َلَمْ يُظَ[n[ـٰ]هِرُو[s[اْ] عَلَيْكُمْ أَحَ[f:5463[دًا ف]َأَتِ[g[مّ][o[ُوٓ][s[اْ] إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُحِبُّ [h:2037[ٱ]لْمُتَّق[p[ِي]نَ","Магар мушриклардан сиз аҳдлашганингиздан кейин ҳеч нарсани нуқсон қилмаганлари ва сизга қарши бировга ёрдам бермаганларининг аҳдларини муддатларигача батамом қилинг. Албатта, Аллоҳ тақводорларни севадир.",187,10],["فَإِذَا [h:5464[ٱ][f:5465[نس]َلَخَ [h:5466[ٱ]لْأَشْهُرُ [h:5467[ٱ]لْحُرُمُ فَ[h:262[ٱ][q:262[قْ]تُلُو[s[اْ] [h:5468[ٱ]لْمُشْرِكِينَ حَيْثُ وَجَ[d:3005[د]تُّمُوهُمْ وَخُذُوهُمْ وَ[h:5469[ٱ]حْصُرُوهُمْ وَ[h:5470[ٱ][q:5470[قْ]عُدُو[s[اْ] لَهُمْ كُلَّ مَرْصَ[f:5471[دٍ‌ۚ ف]َإِ[f:5472[ن ت]َابُو[s[اْ] وَأَقَامُو[s[اْ] [h:1641[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتَوُ[s[اْ] [h:1642[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ فَخَلُّو[s[اْ] سَبِيلَهُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Бас, ҳаром ойлар чиққанда, мушрикларни қаерда топсангиз, ўлдиринглар, тутинглар, қамал қилинглар ва уларни ҳар жойда пойланглар. Агар тавба қилсалар, намозни тўкис адо этсалар ва закотни берсалар, йўлларига қўйиб юборинглар. Албатта, Аллоҳ мағфиратли ва раҳмли зотдир.",187,10],["وَإِنْ أَحَ[a:5473[دٌ م]ِّنَ [h:699[ٱ]لْمُشْرِكِينَ [h:5474[ٱ]سْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَ[n[ـٰ]مَ [h:389[ٱ]للَّهِ ثُ[g[مّ]َ أَ[q:5475[بْ]لِغْهُ مَأْمَنَهُ[n[ۥ]‌ۚ ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ قَوْ[u:3651[مٌ ل]َّا يَعْلَم[p[ُو]نَ","Агар мушриклардан биронтаси паноҳ сўраса, унга паноҳ бер, токи у Аллоҳнинг каломини эшитсин. Сўнгра уни омонлик жойига етказиб қўй. Бу уларнинг билмайдиган қавм бўлганлари учундир.",187,10],["كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَعِ[f:5476[ند]َ رَسُولِه[o[ِۦٓ] إِلَّا [h:778[ٱ]لَّذِينَ عَ[n[ـٰ]هَ[d:5449[د]تُّمْ عِ[f:264[ند]َ [h:1026[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ‌ۖ فَمَا [h:5477[ٱ]سْتَقَ[n[ـٰ]مُو[s[اْ] لَكُمْ فَ[h:5478[ٱ]سْتَقِيمُو[s[اْ] لَهُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُحِبُّ [h:2037[ٱ]لْمُتَّق[p[ِي]نَ","Қандай қилиб мушрикларга Аллоҳнинг ҳузурида ва Унинг Расулининг ҳузурида аҳд бўлсин?! Магар сиз билан Масжидул Ҳаром олдида аҳдлашганлар, сизга нисбатан мудом мустақим турсалар, сиз ҳам мустақим туринг. Албатта, Аллоҳ тақводорларни севадир.",188,10],["كَيْفَ وَإ[a:5479[ِن ي]َظْهَرُو[s[اْ] عَلَيْكُمْ لَا يَرْقُبُو[s[اْ] فِيكُمْ إِل[a:5480[اًّ و]َلَا ذِ[g[مّ]َ[a:5481[ةً‌ۚ ي]ُرْضُونَك[c:5482[ُم ب]ِأَفْو[n[َٲ]هِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَ[n[ـٰ]سِق[p[ُو]نَ","Қандай қилиб, улар агар сиздан устун келсалар, на аҳдга ва на бурчга риоя этмаслар. Сизни оғизлари билан рози қиладилар-у, қалблари кўнмайдир. Уларнинг кўплари фосиқлардир.",188,10],["ٱشْتَرَوْ[s[اْ] بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ ثَمَ[f:208[نًا ق]َلِيل[f:5483[اً ف]َصَدُّو[s[اْ] عَ[f:4361[ن س]َبِيلِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َهُمْ س[o[َا]ٓءَ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Улар Аллоҳнинг оятларини озгина баҳога сотиб, Унинг йўлидан тўсдилар. Дарҳақиқат, уларнинг қилганлари қандай ҳам ёмон бўлди?!",188,10],["لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِل[a:5480[اًّ و]َلَا ذِ[g[مّ]َ[a:5484[ةً‌ۚ و]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:5485[ٱ]لْمُعْتَد[p[ُو]نَ","Улар мўмин ҳақида на аҳдга ва на бурчга риоя қилмаслар. Ана ўшалар ўзлари тажовузкорлардир.",188,10],["فَإِ[f:5472[ن ت]َابُو[s[اْ] وَأَقَامُو[s[اْ] [h:1641[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتَوُ[s[اْ] [h:1642[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ فَإِخْو[n[َٲ]نُكُمْ فِى [h:1477[ٱ][l[ل]دِّينِ‌ۗ وَنُفَصِّلُ [h:5486[ٱ]لْأَيَ[n[ـٰ]تِ لِقَوْ[a:1292[مٍ ي]َعْلَم[p[ُو]نَ","Бас, агар тавба қилсалар, намозни тўкис адо этсалар ва закотни берсалар, дин қардошингиздирлар. Биладиган қавм учун оятларимизни батафсил баён қилурмиз.",188,10],["وَإ[a:5487[ِن ن]َّكَث[o[ُوٓ][s[اْ] أَيْمَ[n[ـٰ]نَه[w:5488[ُم م]ّ[i:146[ِنۢ ب]َعْدِ عَهْدِهِمْ وَطَعَنُو[s[اْ] فِى دِينِكُمْ فَقَ[n[ـٰ]تِل[o[ُوٓ][s[اْ] أَئِ[g[مّ]َةَ [h:5489[ٱ]لْكُفْرِ‌ۙ إِ[g[نّ]َهُمْ ل[o[َآ] أَيْمَ[n[ـٰ]نَ لَهُمْ لَعَلَّهُمْ يَ[f:5490[نت]َه[p[ُو]نَ","Агар, аҳд берганларидан кейин аҳдларини бузсалар ва динингизга таъна тошини отсалар, куфрбошиларга қарши жанг қилинг! Зеро, уларнинг аҳдлари йўқдир. Шоядки, тўхтасалар.",188,10],["أَلَا تُقَ[n[ـٰ]تِلُونَ قَوْ[a:5491[مًا ن]َّكَث[o[ُوٓ][s[اْ] أَيْمَ[n[ـٰ]نَهُمْ وَهَ[g[مّ]ُو[s[اْ] بِإِخْرَاجِ [h:5492[ٱ][l[ل]رَّسُولِ وَه[c:5493[ُم ب]َدَءُوكُمْ أَوَّلَ مَرَّةٍ‌ۚ أَتَخْشَوْنَهُمْ‌ۚ فَ[h:591[ٱ]للَّهُ أَحَقُّ أَ[f:5494[ن ت]َخْشَوْهُ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Аҳдларини бузган, Расулни чиқаришга қасд қилган ва сизга биринчи бўлиб бошлаган қавм билан урушмайсизми?! Улардан қўрқасизми?! Агар мўмин бўлсангиз, қўрқишингиз лойиқ зот Аллоҳдир!!!",188,10],["قَ[n[ـٰ]تِلُوهُمْ يُعَذِّ[q:5495[بْ]هُمُ [h:5496[ٱ]للَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَ[f:5497[نص]ُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْ[a:5498[مٍ م]ُّؤْمِن[p[ِي]نَ","Уларга қарши жанг қилинглар! Аллоҳ уларни сизнинг қўлингиз билан азоблайдир, хорлайдир ва уларга қарши сизга ёрдам берадир. Ва мўмин қавмларнинг кўнгилларига шифо берадир.",189,10],["وَيُذْهِ[q:5499[بْ] غَيْظَ قُلُوبِهِمْ‌ۗ وَيَتُوبُ [h:5500[ٱ]للَّهُ عَلَىٰ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Ва қалбларидаги аччиқни кетказадир. Аллоҳ кимни хоҳласа, ўшанинг тавбасини қабул қиладир. Аллоҳ билгувчи ва ҳикматли зотдир.",189,10],["أَمْ حَسِ[q:1174[بْ]تُمْ أَ[f:5501[ن ت]ُتْرَكُو[s[اْ] وَلَ[g[مّ]َا يَعْلَمِ [h:2272[ٱ]للَّهُ [h:2273[ٱ]لَّذِينَ جَ[n[ـٰ]هَدُو[s[اْ] مِ[f:344[نك]ُمْ وَلَمْ يَتَّخِذُو[s[اْ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَلَا رَسُولِه[n[ِۦ] وَلَا [h:5502[ٱ]لْمُؤْمِنِينَ وَلِيجَ[a:5503[ةً‌ۚ و]َ[h:72[ٱ]للَّهُ خَبِي[i:2335[رُۢ ب]ِمَا تَعْمَل[p[ُو]نَ","Сиздан жиҳод қилганларни, Аллоҳдан, Унинг Расулидан ва мўминлардан ўзгани дўст тутмаганларни билмай туриб, Аллоҳ томонидан тарк этиб қўйилмоғингизни ўйладингизми? Аллоҳ нима қилаётганларингиздан хабардор зотдир.",189,10],["مَا كَانَ لِلْمُشْرِكِينَ أ[a:5504[َن ي]َعْمُرُو[s[اْ] مَسَ[n[ـٰ]جِدَ [h:594[ٱ]للَّهِ شَ[n[ـٰ]هِدِينَ عَلَ[o[ىٰٓ] أَ[f:568[نف]ُسِه[c:5505[ِم ب]ِ[h:2055[ٱ]لْكُفْرِ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ حَبِطَتْ أَعْمَ[n[ـٰ]لُهُمْ وَفِى [h:5506[ٱ][l[ل][g[نّ]َارِ هُمْ خَ[n[ـٰ]لِد[p[ُو]نَ","Мушрикларга ўзларининг кофир эканликларига гувоҳ бўлган ҳолларида Аллоҳнинг масжидларини обод қилишлари жоиз эмас. Ана ўшалар амаллари ҳабата бўлганлардир ва улар дўзахда абадий қолувчилардир.",189,10],["إِ[g[نّ]َمَا يَعْمُرُ مَسَ[n[ـٰ]جِدَ [h:594[ٱ]للَّهِ مَنْ ءَامَنَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ وَأَقَامَ [h:915[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتَى [h:916[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَلَمْ يَخْشَ إِلَّا [h:416[ٱ]للَّهَ‌ۖ فَعَسَ[o[ىٰٓ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أ[a:5507[َن ي]َكُونُو[s[اْ] مِنَ [h:4096[ٱ]لْمُهْتَد[p[ِي]نَ","Албатта, Аллоҳнинг масжидларини фақат Аллоҳга ва охират кунига иймон келтирганлар, намозни тўкис адо этганлар, закотни берганлар ва Аллоҳдан бошқадан қўрқмаганларгина обод қиларлар. Ажаб эмаски, ана ўшалар ҳидоят топгувчилардан бўлсалар.",189,10],["۞ أَجَعَلْتُمْ سِقَايَةَ [h:5508[ٱ]لْح[m[َا]ٓجِّ وَعِمَارَةَ [h:5509[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ كَمَنْ ءَامَنَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ وَجَ[n[ـٰ]هَدَ فِى سَبِيلِ [h:788[ٱ]للَّهِ‌ۚ لَا يَسْتَوُ[n[ۥ]نَ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Ҳожиларга сув беришни ва Масжидул Ҳаромни обод қилишни, Аллоҳга, охират кунига иймон келтирган ва Аллоҳнинг йўлида жиҳод қилган каби қилдингизми?! Улар Аллоҳнинг ҳузурида тенг эмаслар. Аллоҳ золим қавмларни ҳидоят қилмас.",189,10],["ٱلَّذِينَ ءَامَنُو[s[اْ] وَهَاجَرُو[s[اْ] وَجَ[n[ـٰ]هَدُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ بِأَمْو[n[َٲ]لِهِمْ وَأَ[f:3050[نف]ُسِهِمْ أَعْظَمُ دَرَجَةً عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۚ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:5510[ٱ]لْف[o[َا]ٓئِز[p[ُو]نَ","Иймон келтириб, ҳижрат қилганлар ва Аллоҳнинг йўлида моллари ва жонлари билан жиҳод қилганларнинг даражалари Аллоҳнинг ҳузурида жуда улуғдир. Ана ўшалар ютуққа эришувчилардир.",189,10],["يُبَشِّرُهُمْ رَبُّه[c:5511[ُم ب]ِرَحْمَ[a:5512[ةٍ م]ِّنْهُ وَرِضْو[n[َٲ][a:5513[نٍ و]َجَ[g[نّ]َ[n[ـٰ][u:5514[تٍ ل]َّهُمْ فِيهَا نَعِي[a:5515[مٌ م]ُّق[p[ِي]مٌ","Роббилари уларга Ўз тарафидан бўлган раҳмат, розилик ва ичида уларга аталган доимий неъматлар бор жаннатларнинг башоратини беради.",190,10],["خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَدًا‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عِ[f:719[ند]َهُ[o[ۥٓ] أَ[q:2423[جْ]رٌ عَظ[p[ِي]مٌ","Улар унда абадий қолувчилардир. Албатта, Аллоҳ, ҳузурида улуғ ажр бор зотдир.",190,10],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَتَّخِذ[o[ُوٓ][s[اْ] ءَاب[o[َا]ٓءَكُمْ وَإِخْو[n[َٲ]نَكُمْ أَوْلِي[o[َا]ٓءَ إِنِ [h:5516[ٱ]سْتَحَبُّو[s[اْ] [h:5517[ٱ]لْكُفْرَ عَلَى [h:5518[ٱ]لْإِيمَ[n[ـٰ]نِ‌ۚ وَم[a:3619[َن ي]َتَوَلَّه[w:3620[ُم م]ِّ[f:344[نك]ُمْ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:1285[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Эй иймон келтирганлар! Агар куфрни иймондан устун кўрсалар, ота-онангиз ва ака-укаларингизни дўст тутманг. Сиздан ким уларни дўст тутса, бас, ана ўшалар, ўзлари золимлардир.",190,10],["قُلْ إِ[f:2594[ن ك]َانَ ءَاب[o[َا]ٓؤُكُمْ وَأَ[q:2602[بْ]ن[o[َا]ٓؤُكُمْ وَإِخْو[n[َٲ]نُكُمْ وَأَزْو[n[َٲ]جُكُمْ وَعَشِيرَتُكُمْ وَأَمْو[n[َٲ]لٌ [h:5519[ٱ][q:5520[قْ]تَرَفْتُمُوهَا وَتِجَ[n[ـٰ]رَ[f:5521[ةٌ ت]َخْشَوْنَ كَسَادَهَا وَمَسَ[n[ـٰ]كِنُ تَرْضَوْنَه[o[َآ] أَحَبَّ إِلَيْك[w:5522[ُم م]ِّنَ [h:321[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] وَجِهَا[f:5523[دٍ ف]ِى سَبِيلِه[n[ِۦ] فَتَرَبَّصُو[s[اْ] حَتَّىٰ يَأْتِىَ [h:573[ٱ]للَّهُ بِأَمْرِه[n[ِۦ]‌ۗ وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:3860[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","Агар ота-оналарингиз, болаларингиз, ака-укаларингиз, жуфтларингиз, қариндош-уруғларингиз, касб қилган молларингиз, касод бўлишдан қўрққан тижоратларингиз ва хуш кўрган масканларингиз сизга Аллоҳдан, Унинг Расули ва Унинг йўлида жиҳод қилишдан маҳбуброқ бўлса, у ҳолда Аллоҳ Ўз амрини келтургунча кутиб туринг. Аллоҳ фосиқ қавмни ҳидоят қилмас.",190,10],["لَقَ[q:2389[دْ] نَصَرَكُمُ [h:2209[ٱ]للَّهُ فِى مَوَاطِنَ كَثِيرَ[a:5524[ةٍ‌ۙ و]َيَوْمَ حُنَيْنٍ‌ۙ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَ[f:255[نك]ُمْ شَيْـ[a:5525[ـًٔا و]َضَاقَتْ عَلَيْكُمُ [h:5526[ٱ]لْأَرْضُ بِمَا رَحُبَتْ ثُ[g[مّ]َ وَلَّيْت[w:5527[ُم م]ُّ[q:5528[دْ]بِر[p[ِي]نَ","Батаҳқиқ, Аллоҳ сизларга кўп жойларда нусрат берди. Ҳунайн кунида ҳам. Ўшанда сизни кўплигингиз мағрур қилган эди. Бас, сизга ҳеч фойда бермади ва кенг ер сизга торлик қилиб қолди. Сўнгра ортга қараб қочдингиз.",190,10],["ثُ[g[مّ]َ أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ سَكِينَتَهُ[n[ۥ] عَلَىٰ رَسُولِه[n[ِۦ] وَعَلَى [h:5529[ٱ]لْمُؤْمِنِينَ وَأَ[f:91[نز]َلَ جُنُو[u:5530[دًا ل]َّمْ تَرَوْهَا وَعَذَّبَ [h:5531[ٱ]لَّذِينَ كَفَرُو[s[اْ‌ۚ] وَذ[n[َٲ]لِكَ جَز[o[َا]ٓءُ [h:1029[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Сўнгра Аллоҳ сокинлигини Пайғамбарига ва мўминларга туширди ҳамда сиз кўрмайдиган лашкарларни туширди ва куфр келтирганларни азоблади. Ана ўша кофирларнинг жазосидир.",190,10],["ثُ[g[مّ]َ يَتُوبُ [h:2652[ٱ]للَّهُ م[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ عَلَىٰ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۗ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Сўнгра ўшандан кейин Аллоҳ Ўзи хоҳлаган кишиларнинг тавбасини қабул қилди. Аллоҳ мағфиратли ва раҳмли зотдир.",191,10],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[g[نّ]َمَا [h:5532[ٱ]لْمُشْرِكُونَ نَجَ[f:5533[سٌ ف]َلَا يَ[q:5534[قْ]رَبُو[s[اْ] [h:5535[ٱ]لْمَسْجِدَ [h:5536[ٱ]لْحَرَامَ بَعْدَ عَامِهِمْ هَ[n[ـٰ]ذَا‌ۚ وَإِنْ خِفْتُمْ عَيْلَ[f:5537[ةً ف]َسَوْفَ يُغْنِيكُمُ [h:5538[ٱ]للَّهُ مِ[f:475[ن ف]َضْلِه[o[ِۦٓ] إِ[f:364[ن ش][o[َا]ٓءَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلِيمٌ حَك[p[ِي]مٌ","Эй иймон келтирганлар! Албатта, мушриклар нажасдирлар, бунга шубҳа йўқ, бу йилларидан кейин Масжидул Ҳаромга яқин келмасинлар. Агар фақирликдан қўрқсангиз, тезда Аллоҳ Ўзи хоҳласа, сизни фазли ила бой қилиб қўядир. Албатта, Аллоҳ билгувчи ва ҳикматли зотдир.",191,10],["قَ[n[ـٰ]تِلُو[s[اْ] [h:5539[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَلَا بِ[h:2784[ٱ]لْيَوْمِ [h:2785[ٱ]لْأَخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ [h:3706[ٱ]للَّهُ وَرَسُولُهُ[n[ۥ] وَلَا يَدِينُونَ دِينَ [h:5540[ٱ]لْحَقِّ مِنَ [h:523[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ حَتَّىٰ يُعْطُو[s[اْ] [h:5541[ٱ]لْجِزْيَةَ ع[a:5542[َن ي]َ[a:5543[دٍ و]َهُمْ صَ[n[ـٰ]غِر[p[ُو]نَ","Аллоҳга ва охират кунига иймон келтирмайдиганларга, Аллоҳ ва Унинг Расули ҳаром қилган нарсаларни ҳаром деб билмайдиган ва ҳақ динга юрмайдиган китоб берилганларга қарши, то улар бўйинсунган ҳолларида ўз қўллари билан «жизя» бермагунича, жанг қилинг.",191,10],["وَقَالَتِ [h:583[ٱ]لْيَهُودُ عُزَيْرٌ [h:5544[ٱ][q:1917[بْ]نُ [h:5545[ٱ]للَّهِ وَقَالَتِ [h:586[ٱ][l[ل][g[نّ]َصَ[n[ـٰ]رَى [h:5546[ٱ]لْمَسِيحُ [h:3448[ٱ][q:1917[بْ]نُ [h:5545[ٱ]للَّهِ‌ۖ ذ[n[َٲ]لِكَ قَوْلُه[c:5547[ُم ب]ِأَفْو[n[َٲ]هِهِمْ‌ۖ يُضَ[n[ـٰ]هِــُٔونَ قَوْلَ [h:2461[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۚ قَ[n[ـٰ]تَلَهُمُ [h:5548[ٱ]للَّهُ‌ۚ أَ[g[نّ]َىٰ يُؤْفَك[p[ُو]نَ","Яҳудийлар: «Узайр Аллоҳнинг ўғлидир», дедилар. Насоролар: «Масиҳ Аллоҳнинг ўғлидир», дедилар. Бу оғизлари билан айтган гапларидир. Аввалги куфр келтирганларнинг гапига ўхшатадилар. Аллоҳ уларни лаънатласин. Қаён бурилмоқдалар?!",191,10],["ٱتَّخَذ[o[ُوٓ][s[اْ] أَحْبَارَهُمْ وَرُهْبَ[n[ـٰ]نَهُمْ أَرْبَا[a:1993[بًا م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَ[h:5549[ٱ]لْمَسِيحَ [h:5550[ٱ][q:451[بْ]نَ مَرْيَمَ وَم[o[َآ] أُمِر[o[ُوٓ][s[اْ] إِلَّا لِيَعْبُد[o[ُوٓ][s[اْ] إِلَ[n[ـٰ][a:693[هًا و][n[َٲ]حِ[u:5551[دًا‌ۖ ل]ّ[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۚ سُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ] عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","Улар Аллоҳни қўйиб ўзларининг ҳибр ва роҳибларини ҳамда Масиҳ ибн Марямни Робб тутдилар. Улар фақат битта илоҳдан бошқага ибодат қилмасликка амр қилинган эдилар. Ундан ўзга ибодатга сазовар зот йўқ. У зот улар ширк келтираётган нарсадан покдир.",191,10],["يُرِيدُونَ أ[a:5552[َن ي]ُ[q:5553[طْ]فِــُٔو[s[اْ] نُورَ [h:5554[ٱ]للَّهِ بِأَفْو[n[َٲ]هِهِمْ وَيَأْبَى [h:5555[ٱ]للَّهُ إِلّ[o[َآ] أ[a:1308[َن ي]ُتِ[g[مّ]َ نُورَهُ[n[ۥ] وَلَوْ كَرِهَ [h:5556[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Улар Аллоҳнинг нурини оғизлари билан ўчирмоқчи бўлурлар. Аллоҳ эса, гарчи кофирлар ёқтирмаса ҳам, ўз нурини батамом қилишдан бошқа ҳар нарсадан бош тортадир.",192,10],["هُوَ [h:153[ٱ]لَّذ[o[ِىٓ] أَرْسَلَ رَسُولَهُ[n[ۥ] بِ[h:54[ٱ]لْهُدَىٰ وَدِينِ [h:5557[ٱ]لْحَقِّ لِيُظْهِرَهُ[n[ۥ] عَلَى [h:5558[ٱ][l[ل]دِّينِ كُلِّه[n[ِۦ] وَلَوْ كَرِهَ [h:5559[ٱ]لْمُشْرِك[p[ُو]نَ","У гарчи мушриклар ёқтимаса ҳам, Ўз Расулини ҳидоят ва ҳақ дин билан ҳамма диндан устун қилиш учун юборган зотдир.",192,10],["۞ يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[g[نّ]َ كَثِي[a:3614[رًا م]ِّنَ [h:5560[ٱ]لْأَحْبَارِ وَ[h:5561[ٱ][l[ل]رُّهْبَانِ لَيَأْكُلُونَ أَمْو[n[َٲ]لَ [h:3285[ٱ][l[ل][g[نّ]َاسِ بِ[h:212[ٱ]لْبَ[n[ـٰ]طِلِ وَيَصُدُّونَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ‌ۗ وَ[h:37[ٱ]لَّذِينَ يَكْنِزُونَ [h:5562[ٱ][l[ل]ذَّهَبَ وَ[h:5563[ٱ]لْفِضَّةَ وَلَا يُ[f:5564[نف]ِقُونَهَا فِى سَبِيلِ [h:788[ٱ]للَّهِ فَبَشِّرْه[c:1811[ُم ب]ِعَذَابٍ أَل[p[ِي]مٍ","Эй иймон келтирганлар! Албатта, ҳибр ва роҳибларнинг кўплари одамларнинг молларини ботил йўл билан ерлар ва Аллоҳнинг йўлидан тўсарлар. Олтин ва кумушни хазинага босадиган, Аллоҳнинг йўлида сарфламайдиганларга аламли азобнинг башоратини беравер.",192,10],["يَوْمَ يُحْمَىٰ عَلَيْهَا فِى نَارِ جَهَ[g[نّ]َمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ‌ۖ هَ[n[ـٰ]ذَا مَا كَنَزْتُمْ لِأَ[f:574[نف]ُسِكُمْ فَذُوقُو[s[اْ] مَا كُ[f:100[نت]ُمْ تَكْنِز[p[ُو]نَ","Бир куни ўшаларни жаҳаннам ўтида қизитилади ва пешоналари, ёнбошлари ҳамда орқаларига босилиб: «Мана бу ўзингиз учун тўплаган нарсангиз, бас, энди тўплаб юрган нарсангизни татиб кўринг!» дейилур.",192,10],["إِ[g[نّ]َ عِدَّةَ [h:5565[ٱ][l[ل]شُّهُورِ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ [h:5566[ٱ]ثْنَا عَشَرَ شَهْ[f:5567[رًا ف]ِى كِتَ[n[ـٰ]بِ [h:1816[ٱ]للَّهِ يَوْمَ خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ مِنْه[o[َآ] أَرْبَعَةٌ حُرُ[f:5568[مٌ‌ۚ ذ][n[َٲ]لِكَ [h:5569[ٱ][l[ل]دِّينُ [h:5570[ٱ]لْقَيِّمُ‌ۚ فَلَا تَظْلِمُو[s[اْ] فِيهِ[g[نّ]َ أَ[f:221[نف]ُسَكُمْ‌ۚ وَقَ[n[ـٰ]تِلُو[s[اْ] [h:5571[ٱ]لْمُشْرِكِينَ ك[m[َا]ٓفَّ[f:5572[ةً ك]َمَا يُقَ[n[ـٰ]تِلُونَكُمْ ك[m[َا]ٓفَّ[a:5573[ةً‌ۚ و]َ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ مَعَ [h:1044[ٱ]لْمُتَّق[p[ِي]نَ","Албатта, Аллоҳнинг ҳузурида ойларнинг сони, Аллоҳнинг ҳузурида осмонлару ерни яратган куни ўн икки ой қилиб белгиланган. Улардан тўрттаси ҳаром дир. Мана шу тўғри диндир. У ларда ўзингизга зулм қилманг. Мушрикларга қарши жам бўлиб, улар сизга қарши жам бўлиб урушаётгандек уруш қилинг. Ва билингки, албатта, Аллоҳ тақводорлар биландир.",192,10],["إِ[g[نّ]َمَا [h:5574[ٱ][l[ل][g[نّ]َس[o[ِى]ٓءُ زِيَادَ[f:5575[ةٌ ف]ِى [h:2437[ٱ]لْكُفْرِ‌ۖ يُضَلُّ بِهِ [h:4071[ٱ]لَّذِينَ كَفَرُو[s[اْ] يُحِلُّونَهُ[n[ۥ] عَا[a:5576[مًا و]َيُحَرِّمُونَهُ[n[ۥ] عَا[u:5577[مًا ل]ِّيُوَاطِــُٔو[s[اْ] عِدَّةَ مَا حَرَّمَ [h:3706[ٱ]للَّهُ فَيُحِلُّو[s[اْ] مَا حَرَّمَ [h:3706[ٱ]للَّهُ‌ۚ زُيِّنَ لَهُمْ س[o[ُو]ٓءُ أَعْمَ[n[ـٰ]لِهِمْ‌ۗ وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1557[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Албатта, «насийу» куфрда зиёда бўлишдан ўзга нарса эмас. Бу билан куфр келтирганлар залолатга кеткизилурлар. Аллоҳ ҳаром қилган нарсанинг ададига мослаш учун уни бир йил ҳалол қиларлар, бир йил ҳаром қиларлар. Бас, бу билан Аллоҳ ҳаром қилган нарсани ҳалол қиларлар. Уларга амалларининг ёмонлиги зийнатланди. Аллоҳ кофир қавмларни ҳидоят қилмас.",193,10],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مَا لَكُمْ إِذَا قِيلَ لَكُمُ [h:5578[ٱ][f:2909[نف]ِرُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ [h:5579[ٱ]ثَّاقَلْتُمْ إِلَى [h:5136[ٱ]لْأَرْضِ‌ۚ أَرَضِيت[c:5580[ُم ب]ِ[h:5581[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:5582[ٱ][l[ل]دُّنْيَا مِنَ [h:5583[ٱ]لْأَخِرَةِ‌ۚ فَمَا مَتَ[n[ـٰ]عُ [h:1780[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا فِى [h:536[ٱ]لْأَخِرَةِ إِلَّا قَل[p[ِي]لٌ","Эй иймон келтирганлар! Сизга нима бўлдики, Аллоҳнинг йўлида қўзғолинг дейилса, ерга ёпишиб олдингиз. Ёки охиратни қўйиб, ҳаёти дунёга рози бўлдингизми? Охират олдида бу ҳаёти дунё жуда оз-ку?!",193,10],["إِلَّا تَ[f:5584[نف]ِرُو[s[اْ] يُعَذِّ[q:5585[بْ]كُمْ عَذَابًا أَلِي[a:5586[مًا و]َيَسْتَ[q:5587[بْ]دِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـ[a:5588[ـًٔا‌ۗ و]َ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Агар қўзғолмасангиз, У зот сизни аламли азоб билан азоблайдир. Ўрнингизга бошқа қавмни келтирадир. Сиз Унга зарар келтира олмассиз. Аллоҳ ҳар бир нарсага қодирдир.",193,10],["إِلَّا تَ[f:5589[نص]ُرُوهُ فَقَ[q:563[دْ] نَصَرَهُ [h:5590[ٱ]للَّهُ إِذْ أَخْرَجَهُ [h:5591[ٱ]لَّذِينَ كَفَرُو[s[اْ] ثَانِىَ [h:5592[ٱ]ثْنَيْنِ إِذْ هُمَا فِى [h:5593[ٱ]لْغَارِ إِذْ يَقُولُ لِصَ[n[ـٰ]حِبِه[n[ِۦ] لَا تَحْزَنْ إِ[g[نّ]َ [h:80[ٱ]للَّهَ مَعَنَا‌ۖ فَأَ[f:5594[نز]َلَ [h:5595[ٱ]للَّهُ سَكِينَتَهُ[n[ۥ] عَلَيْهِ وَأَيَّدَهُ[n[ۥ] بِجُنُو[u:5596[دٍ ل]َّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ [h:5597[ٱ]لَّذِينَ كَفَرُو[s[اْ] [h:5598[ٱ][l[ل]سُّفْلَىٰ‌ۗ وَكَلِمَةُ [h:5599[ٱ]للَّهِ هِىَ [h:5600[ٱ]لْعُلْيَا‌ۗ وَ[h:72[ٱ]للَّهُ عَزِيزٌ حَك[p[ِي]مٌ","Агар сиз унга ёрдам бермасангиз, батаҳқиқ, Аллоҳ унга, куфр келтирганлар уни икки кишининг бири бўлган ҳолида чиқарганларида, нусрат берди. Улар икковлон ғорда турганларида, у шеригига, хафа бўлма, Аллоҳ, албатта, биз билан, деди. Бас, Аллоҳ унинг устидан Ўз сокинлигини нозил қилди ва сиз кўрмаган лашкарлар билан қўллади. Куфр келтирганлар калимасини паст қилди. Аллоҳнинг калимаси эса, ўзи юқори. Аллоҳ ғолиб ва ҳикматли зотдир.",193,10],["ٱ[f:2909[نف]ِرُو[s[اْ] خِفَا[a:5601[فًا و]َثِقَال[a:5602[اً و]َجَ[n[ـٰ]هِدُو[s[اْ] بِأَمْو[n[َٲ]لِكُمْ وَأَ[f:2485[نف]ُسِكُمْ فِى سَبِيلِ [h:788[ٱ]للَّهِ‌ۚ ذ[n[َٲ]لِكُمْ خَيْ[u:263[رٌ ل]َّكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","Енгил бўлса ҳам, оғир бўлса ҳам, қўзғолингиз ва Аллоҳнинг йўлида молларингиз ва жонларингиз ила жиҳод қилингиз. Агар билсангиз, шу ишингиз ўзингиз учун яхшидир.",194,10],["لَوْ كَانَ عَرَ[f:5603[ضًا ق]َرِي[a:5604[بًا و]َسَفَ[f:5605[رًا ق]َاصِ[u:5606[دًا ل]َّ[h:5607[ٱ]تَّبَعُوكَ وَلَ[n[ـٰ]ك[i:5608[ِنۢ ب]َعُدَتْ عَلَيْهِمُ [h:5609[ٱ][l[ل]شُّقَّةُ‌ۚ وَسَيَحْلِفُونَ بِ[h:32[ٱ]للَّهِ لَوِ [h:5610[ٱ]سْتَطَعْنَا لَخَرَ[q:5611[جْ]نَا مَعَكُمْ يُهْلِكُونَ أَ[f:38[نف]ُسَهُمْ وَ[h:72[ٱ]للَّهُ يَعْلَمُ إِ[g[نّ]َهُمْ لَكَ[n[ـٰ]ذِب[p[ُو]نَ","Агар осон манфаат ва яқин сафар бўлганида, албатта, сенга эргашар эдилар. Лекин уларга масофа узоқ кўринди. Улар тезда Аллоҳ номи билан қасам ичиб: «Агар қодир бўлганимизда, албатта, сиз билан чиқар эдик», дерлар. Улар ўзларини ҳалок қиладилар. Ҳолбуки, Аллоҳ улар ёлғончи эканларини, албатта, билади.",194,10],["عَفَا [h:2357[ٱ]للَّهُ عَ[f:626[نك]َ لِمَ أَذِ[f:5612[نت]َ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ [h:5613[ٱ]لَّذِينَ صَدَقُو[s[اْ] وَتَعْلَمَ [h:5614[ٱ]لْكَ[n[ـٰ]ذِب[p[ِي]نَ","Аллоҳ сени авф қилди. Нима учун уларга то сенга ростгўй бўлганлар равшан бўлмай туриб ва ёлғончиларни билмасингдан туриб, изн бердинг?",194,10],["لَا يَسْتَــْٔذِنُكَ [h:5615[ٱ]لَّذِينَ يُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ أ[a:5616[َن ي]ُجَ[n[ـٰ]هِدُو[s[اْ] بِأَمْو[n[َٲ]لِهِمْ وَأَ[f:3050[نف]ُسِهِمْ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِي[i:2184[مُۢ ب]ِ[h:2185[ٱ]لْمُتَّق[p[ِي]نَ","Аллоҳга ва охират кунига иймон келтирганлар сендан моллари ва жонлари билан жиҳод қилишдан қолишга изн сўрамайдилар. Аллоҳ тақводорларни билгувчи зотдир.",194,10],["إِ[g[نّ]َمَا يَسْتَــْٔذِنُكَ [h:5615[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ وَ[h:5617[ٱ]رْتَابَتْ قُلُوبُهُمْ فَهُمْ فِى رَيْبِهِمْ يَتَرَدَّد[p[ُو]نَ","Албатта фақат Аллоҳга ва охират кунига ишонмайдиганлар ва қалблари шубҳага тўлганларгина сендан изн сўрарлар. Бас, улар шубҳаларида иккиланаверадилар.",194,10],["۞ وَلَوْ أَرَادُو[s[اْ] [h:5618[ٱ]لْخُرُوجَ لَأَعَدُّو[s[اْ] لَهُ[n[ۥ] عُدَّ[a:5619[ةً و]َلَ[n[ـٰ]كِ[f:5620[ن ك]َرِهَ [h:5621[ٱ]للَّهُ [h:5622[ٱ][i:5623[نۢب]ِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ [h:5624[ٱ][q:5625[قْ]عُدُو[s[اْ] مَعَ [h:5626[ٱ]لْقَ[n[ـٰ]عِد[p[ِي]نَ","Агар чиқишни хоҳлаганларида, унга тайёргарлик кўрар эдилар. Лекин Аллоҳ уларнинг ҳаракатланишларини ёқтирмай тутиб қолди. Уларга, ўтирувчилар билан ўтиринглар, деди.",194,10],["لَوْ خَرَجُو[s[اْ] فِيك[w:5627[ُم م]َّا زَادُوكُمْ إِلَّا خَبَال[a:5628[اً و]َلَأَوْضَعُو[s[اْ] خِلَ[n[ـٰ]لَكُمْ يَ[q:5629[بْ]غُونَكُمُ [h:5630[ٱ]لْفِتْنَةَ وَفِيكُمْ سَ[g[مّ]َ[n[ـٰ]عُونَ لَهُمْ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِي[i:497[مُۢ ب]ِ[h:498[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Агар улар ичингизда чиққанларида ҳам сизга ёмонликдан бошқа нарсани зиёда қилмасдилар, тезлаб орангизга фитна солишга уринардилар. Ҳолбуки, ичингизда уларга қулоқ солувчилар бор эди. Аллоҳ золимларни билгувчи зотдир.",194,10],["لَقَدِ [h:5631[ٱ][q:5632[بْ]تَغَوُ[s[اْ] [h:5633[ٱ]لْفِتْنَةَ مِ[f:128[ن ق]َ[q:129[بْ]لُ وَقَلَّبُو[s[اْ] لَكَ [h:5634[ٱ]لْأُمُورَ حَتَّىٰ ج[o[َا]ٓءَ [h:5635[ٱ]لْحَقُّ وَظَهَرَ أَمْرُ [h:2832[ٱ]للَّهِ وَهُمْ كَ[n[ـٰ]رِه[p[ُو]نَ","Батаҳқиқ, бундан аввал ҳам, улар ёқтирмасалар-да, ҳақ келиб, Аллоҳнинг иши устун бўлгунича, фитна қўзиб, сенга ишларни ағдар-тўнтар қилишар эди.",195,10],["وَمِنْه[w:1106[ُم م]ّ[a:31[َن ي]َقُولُ [h:5636[ٱ]ئْذ[u:5637[َن ل]ِّى وَلَا تَفْتِ[g[نّ][o[ِىٓ‌ۚ] أَلَا فِى [h:5638[ٱ]لْفِتْنَةِ سَقَطُو[s[اْ‌ۗ] وَإِ[g[نّ]َ جَهَ[g[نّ]َمَ لَمُحِيطَ[i:5639[ةُۢ ب]ِ[h:74[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Улардан: «Менга изн бер, мени фитнага солма», дейдигани ҳам бор. Ажабо, улар фитнага тушмадиларми? Албатта, жаҳаннам кофирларни ўраб олгувчидир.",195,10],["إِ[f:5640[ن ت]ُصِ[q:5641[بْ]كَ حَسَنَ[f:2199[ةٌ ت]َسُؤْهُمْ‌ۖ وَإِ[f:5642[ن ت]ُصِ[q:5641[بْ]كَ مُصِيبَ[a:5643[ةٌ ي]َقُولُو[s[اْ] قَ[q:298[دْ] أَخَذْن[o[َآ] أَمْرَنَا مِ[f:128[ن ق]َ[q:129[بْ]لُ وَيَتَوَلَّو[s[اْ] وَّهُمْ فَرِح[p[ُو]نَ","Агар сенга яхшилик етса, уларни хафа қиладир. Агар сенга мусибат етса: «Олдиндан ишнинг олдини олган эдик», деб хурсанд бўлиб юз ўгириб кетарлар.",195,10],["قُل لّ[a:5644[َن ي]ُصِيبَن[o[َآ] إِلَّا مَا كَتَبَ [h:989[ٱ]للَّهُ لَنَا هُوَ مَوْلَ[n[ـٰ]نَا‌ۚ وَعَلَى [h:2207[ٱ]للَّهِ فَلْيَتَوَكَّلِ [h:2208[ٱ]لْمُؤْمِن[p[ُو]نَ","Сен: «Бизга Аллоҳ ёзиб қўйган нарсадан ўзгаси зинҳор етмайди. У бизнинг хожамиздир. Мўминлар Аллоҳгагина таваккал қилсинлар», деб айт.",195,10],["قُلْ هَلْ تَرَبَّصُونَ بِن[o[َآ] إِلّ[o[َآ] إِحْدَى [h:5645[ٱ]لْحُسْنَيَيْنِ‌ۖ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أ[a:5646[َن ي]ُصِيبَكُمُ [h:5647[ٱ]للَّهُ بِعَذَا[a:5648[بٍ م]ِّنْ عِ[f:3628[ند]ِه[o[ِۦٓ] أَوْ بِأَيْدِينَا‌ۖ فَتَرَبَّص[o[ُوٓ][s[اْ] إِ[g[نّ]َا مَعَك[w:5649[ُم م]ُّتَرَبِّص[p[ُو]نَ","Сен: «Сиз биз учун фақат икки яхшиликдан бирини кутмоқдасиз, холос. Биз эса, Аллоҳ сизни Ўз ҳузурида бўладиган ёки бизнинг қўлимиздан етадиган азобга дучор қилишини кутмоқдамиз. Бас, кутаверинглар, биз ҳам сизлар билан бирга кутувчилармиз», деб айт.",195,10],["قُلْ أَ[f:1460[نف]ِقُو[s[اْ] طَوْعًا أَوْ كَرْ[u:5650[هًا ل]ّ[a:5651[َن ي]ُتَقَبَّلَ مِ[f:344[نك]ُمْ‌ۖ إِ[g[نّ]َكُمْ كُ[f:100[نت]ُمْ قَوْ[f:5652[مًا ف]َ[n[ـٰ]سِق[p[ِي]نَ","Сен: «Хоҳлаб ёки хоҳламай нафақа қилаверинглар. Сиздан зинҳор қабул қилинмайди. Сизлар, шубҳасиз, фосиқ қавм бўлдингиз», деб айт.",195,10],["وَمَا مَنَعَهُمْ أَ[f:5653[ن ت]ُ[q:2093[قْ]بَلَ مِنْهُمْ نَفَقَ[n[ـٰ]تُهُمْ إِلّ[o[َآ] أَ[g[نّ]َهُمْ كَفَرُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَبِرَسُولِه[n[ِۦ] وَلَا يَأْتُونَ [h:5654[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُ[f:16[نف]ِقُونَ إِلَّا وَهُمْ كَ[n[ـٰ]رِه[p[ُو]نَ","Уларнинг нафақаларининг қабул этлишидан ман қилган нарса фақат Аллоҳга ва Унинг Расулига куфр келтирганлари, намозга доимо дангаса ҳолларида келганлари ва доимо ёқтирмай инфоқ қилганларидир.",195,10],["فَلَا تُعْجِ[q:5655[بْ]كَ أَمْو[n[َٲ]لُهُمْ وَل[o[َآ] أَوْلَ[n[ـٰ]دُهُمْ‌ۚ إِ[g[نّ]َمَا يُرِيدُ [h:976[ٱ]للَّهُ لِيُعَذِّبَه[c:5656[ُم ب]ِهَا فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا وَتَزْهَقَ أَ[f:2341[نف]ُسُهُمْ وَهُمْ كَ[n[ـٰ]فِر[p[ُو]نَ","Уларнинг моллари ва болалари сени ажаблантирмасин. Аслида, Аллоҳ ўша нарсалар сабабли уларни ҳаёти дунёда азоблашни ва кофир ҳолларида жонлари чиқишни хоҳлайди, холос.",196,10],["وَيَحْلِفُونَ بِ[h:32[ٱ]للَّهِ إِ[g[نّ]َهُمْ لَمِ[f:5657[نك]ُمْ وَمَا ه[w:5658[ُم م]ِّ[f:344[نك]ُمْ وَلَ[n[ـٰ]كِ[g[نّ]َهُمْ قَوْ[a:5659[مٌ ي]َفْرَق[p[ُو]نَ","Улар ўзлари, албатта, сиздан эканликларига Аллоҳ номи ила қасам ичарлар. Ҳолбуки, улар сиздан эмас. Лекин улар қўрқадиган қавмдирлар.",196,10],["لَوْ يَجِدُونَ مَلْجَــًٔا أَوْ مَغَ[n[ـٰ]ر[n[َٲ]تٍ أَوْ مُدَّخَل[u:5660[اً ل]َّوَلَّوْ[s[اْ] إِلَيْهِ وَهُمْ يَ[q:5661[جْ]مَح[p[ُو]نَ","Агар бирор бошпаноҳми, ғорми ёки кириб оладиган жойми топсалар, шошилиб ўша томонга юзланарлар.",196,10],["وَمِنْه[w:1106[ُم م]ّ[a:5662[َن ي]َلْمِزُكَ فِى [h:5663[ٱ][l[ل]صَّدَقَ[n[ـٰ]تِ فَإِنْ أُعْطُو[s[اْ] مِنْهَا رَضُو[s[اْ] وَإ[u:3542[ِن ل]َّمْ يُعْطَوْ[s[اْ] مِنْه[o[َآ] إِذَا هُمْ يَسْخَط[p[ُو]نَ","Улардан садақалар ишида сенга айб қўядиганлари ҳам бор. Агар ўша садақалардан уларга берилса, улар рози бўладилар. Агар берилмаса, кўрибсанки, ғазабланадилар.",196,10],["وَلَوْ أَ[g[نّ]َهُمْ رَضُو[s[اْ] م[o[َآ] ءَاتَ[n[ـٰ]هُمُ [h:2411[ٱ]للَّهُ وَرَسُولُهُ[n[ۥ] وَقَالُو[s[اْ] حَسْبُنَا [h:2428[ٱ]للَّهُ سَيُؤْتِينَا [h:5664[ٱ]للَّهُ مِ[f:475[ن ف]َضْلِه[n[ِۦ] وَرَسُولُهُ[o[ۥٓ] إِ[g[نّ][o[َآ] إِلَى [h:1637[ٱ]للَّهِ ر[n[َٲ]غِب[p[ُو]نَ","Агар Аллоҳ ва Унинг Расули уларга берган нарсаларидан рози бўлганларида ва Аллоҳ бизга кифоя қилур, бизга тезда Аллоҳ ва Унинг Расули Ўз фазлидан беради, албатта, биз Аллоҳга рағбат қилувчилармиз, деганларида, яхши бўларди.",196,10],["۞ إِ[g[نّ]َمَا [h:5665[ٱ][l[ل]صَّدَقَ[n[ـٰ]تُ لِلْفُقَر[o[َا]ٓءِ وَ[h:421[ٱ]لْمَسَ[n[ـٰ]كِينِ وَ[h:5666[ٱ]لْعَ[n[ـٰ]مِلِينَ عَلَيْهَا وَ[h:5667[ٱ]لْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى [h:914[ٱ][l[ل]رِّقَابِ وَ[h:5668[ٱ]لْغَ[n[ـٰ]رِمِينَ وَفِى سَبِيلِ [h:788[ٱ]للَّهِ وَ[h:1189[ٱ][q:1189[بْ]نِ [h:1190[ٱ][l[ل]سَّبِيلِ‌ۖ فَرِيضَ[a:2605[ةً م]ِّنَ [h:321[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Албатта, садақалар фақирларга, мискинларга, садақа ишида ишловчиларга, кўнгилларини улфат қилинадиганларга, қул озод қилишга, қарздорларга, Аллоҳнинг йўлига ва йўл ўғлиларига берилиши Аллоҳ томонидан фарз қилингандир. Аллоҳ билгувчи ва ҳикматли зотдир.",196,10],["وَمِنْهُمُ [h:5669[ٱ]لَّذِينَ يُؤْذُونَ [h:5670[ٱ][l[ل][g[نّ]َبِىَّ وَيَقُولُونَ هُوَ أُذُ[f:5671[نٌ‌ۚ ق]ُلْ أُذُنُ خَيْ[u:5672[رٍ ل]َّكُمْ يُؤْمِنُ بِ[h:32[ٱ]للَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَ[u:5044[ةٌ ل]ِّلَّذِينَ ءَامَنُو[s[اْ] مِ[f:344[نك]ُمْ‌ۚ وَ[h:37[ٱ]لَّذِينَ يُؤْذُونَ رَسُولَ [h:3273[ٱ]للَّهِ لَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Улардан Пайғамбарга озор берадиган ва: «У қулоқдир» дейдиганлар бор. Сен: «У сизга яхшилик нарсаларга қулоқдир. Аллоҳга иймон келтирадир, мўминларга ишонадир, сизлардан иймон келтирганларга раҳматдир. Аллоҳнинг Расулига озор берадиганларга аламли азоб бордир», деб айт.",196,10],["يَحْلِفُونَ بِ[h:32[ٱ]للَّهِ لَكُمْ لِيُرْضُوكُمْ وَ[h:72[ٱ]للَّهُ وَرَسُولُهُ[o[ۥٓ] أَحَقُّ أ[a:5673[َن ي]ُرْضُوهُ إِ[f:5674[ن ك]َانُو[s[اْ] مُؤْمِن[p[ِي]نَ","Улар сизларни рози қилиш учун Аллоҳнинг номи ила қасам ичарлар. Агар мўмин бўлсалар, Аллоҳни ва Унинг Расулини рози қилмоқлари ҳақли эди.",197,10],["أَلَمْ يَعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َهُ[n[ۥ] م[a:5675[َن ي]ُحَادِدِ [h:5676[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] فَأَ[g[نّ]َ لَهُ[n[ۥ] نَارَ جَهَ[g[نّ]َمَ خَ[n[ـٰ]لِ[f:2636[دًا ف]ِيهَا‌ۚ ذ[n[َٲ]لِكَ [h:5677[ٱ]لْخِزْىُ [h:5678[ٱ]لْعَظ[p[ِي]مُ","Улар кимки Аллоҳга ва Унинг Расулига хилоф қилса, албатта, унга жаҳаннам оташ бўлиб, унда абадий қолишини. Ана шу катта ор эканлигини билмайдиларми?!",197,10],["يَحْذَرُ [h:5679[ٱ]لْمُنَ[n[ـٰ]فِقُونَ أَ[f:2107[ن ت]ُنَزَّلَ عَلَيْهِمْ سُورَ[f:5680[ةٌ ت]ُنَبِّئُه[c:5681[ُم ب]ِمَا فِى قُلُوبِهِمْ‌ۚ قُلِ [h:5682[ٱ]سْتَهْزِء[o[ُوٓ][s[اْ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ مُخْرِ[a:373[جٌ م]َّا تَحْذَر[p[ُو]نَ","Мунофиқлар уларга қалбларидаги нарсанинг хабарини берадиган сура нозил бўлишидан қўрқарлар. Сен: «Истеҳзо қилаверинглар, албатта, Аллоҳ сиз қўрқаётган нарсани чиқаргувчидир», деб айт.",197,10],["وَلَئِ[f:5683[ن س]َأَلْتَهُمْ لَيَقُولُ[g[نّ]َ إِ[g[نّ]َمَا كُ[g[نّ]َا نَخُوضُ وَنَلْعَبُ‌ۚ قُلْ أَبِ[h:5684[ٱ]للَّهِ وَءَايَ[n[ـٰ]تِه[n[ِۦ] وَرَسُولِه[n[ِۦ] كُ[f:100[نت]ُمْ تَسْتَهْزِء[p[ُو]نَ","Агар улардан сўрасанг, албатта: «Биз фақат ўзимизча гап қилиб ўйнаётган эдик, холос», дерлар. Сен: «Аллоҳни, Унинг оятларини ва Расулини истеҳзо қилаётган эдингизми?» деб айт.",197,10],["لَا تَعْتَذِرُو[s[اْ] قَ[q:298[دْ] كَفَرْت[c:5685[ُم ب]َعْدَ إِيمَ[n[ـٰ]نِكُمْ‌ۚ إ[a:5686[ِن ن]َّعْفُ عَ[f:5687[ن ط][o[َا]ٓئِفَ[a:5688[ةٍ م]ِّ[f:344[نك]ُمْ نُعَذِّ[q:5689[بْ] ط[o[َا]ٓئِفَ[i:5690[ةَۢ ب]ِأَ[g[نّ]َهُمْ كَانُو[s[اْ] مُ[q:4958[جْ]رِم[p[ِي]نَ","Узр айтманглар. Батаҳқиқ, иймонингиздан кейин куфр келтирдингиз. Агар сиздан бир тоифани авф этсак, бошқа тоифани жиноятчи бўлганлари учун азоблаймиз.",197,10],["ٱلْمُنَ[n[ـٰ]فِقُونَ وَ[h:5691[ٱ]لْمُنَ[n[ـٰ]فِقَ[n[ـٰ]تُ بَعْضُه[w:5692[ُم م]ّ[i:1862[ِنۢ ب]َعْ[a:5693[ضٍ‌ۚ ي]َأْمُرُونَ بِ[h:5694[ٱ]لْمُ[f:5694[نك]َرِ وَيَنْهَوْنَ عَنِ [h:5695[ٱ]لْمَعْرُوفِ وَيَ[q:5696[قْ]بِضُونَ أَيْدِيَهُمْ‌ۚ نَسُو[s[اْ] [h:5697[ٱ]للَّهَ فَنَسِيَهُمْ‌ۗ إِ[g[نّ]َ [h:3224[ٱ]لْمُنَ[n[ـٰ]فِقِينَ هُمُ [h:2071[ٱ]لْفَ[n[ـٰ]سِق[p[ُو]نَ","Мунофиқ эркаклар ва мунофиқ аёллар ҳаммалари бирдирлар, ёмонликка буюрарлар, яхшиликдан қайтарарлар ва қўлларини маҳкам юмарлар. Аллоҳни унутдилар, бас, У ҳам уларни унутди. Албатта, мунофиқлар–улар фосиқлардир.",197,10],["وَعَدَ [h:3055[ٱ]للَّهُ [h:5698[ٱ]لْمُنَ[n[ـٰ]فِقِينَ وَ[h:5699[ٱ]لْمُنَ[n[ـٰ]فِقَ[n[ـٰ]تِ وَ[h:3648[ٱ]لْكُفَّارَ نَارَ جَهَ[g[نّ]َمَ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۚ هِىَ حَسْبُهُمْ‌ۚ وَلَعَنَهُمُ [h:5700[ٱ]للَّهُ‌ۖ وَلَهُمْ عَذَا[a:3534[بٌ م]ُّق[p[ِي]مٌ","Аллоҳ мунофиқ эркакларга, мунофиқ аёлларга ва кофирларга жаҳаннам оташини ваъда қилди. Унда абадий қолурлар. Ўша улар учун етарлидир. Ҳамда Аллоҳ уларни лаънатлади. Уларга доимий азоб бордир.",197,10],["كَ[h:9999[ٱ]لَّذِينَ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ كَان[o[ُوٓ][s[اْ] أَشَدَّ مِ[f:344[نك]ُمْ قُوَّ[a:5701[ةً و]َأَكْثَرَ أَمْو[n[َٲ]ل[a:5702[اً و]َأَوْلَ[n[ـٰ][f:5703[دًا ف]َ[h:5704[ٱ]سْتَمْتَعُو[s[اْ] بِخَلَ[n[ـٰ]قِهِمْ فَ[h:5705[ٱ]سْتَمْتَعْت[c:5706[ُم ب]ِخَلَ[n[ـٰ]قِكُمْ كَمَا [h:5707[ٱ]سْتَمْتَعَ [h:5708[ٱ]لَّذِينَ مِ[f:85[ن ق]َ[q:86[بْ]لِك[c:5709[ُم ب]ِخَلَ[n[ـٰ]قِهِمْ وَخُضْتُمْ كَ[h:1506[ٱ]لَّذِى خَاض[o[ُوٓ[s[اْ]‌ۚ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ حَبِطَتْ أَعْمَ[n[ـٰ]لُهُمْ فِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:150[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","Ўзингиздан аввалгиларга ўхшайсиз. Улар сизлардан кўра қувватлироқ, молу дунё ва бола-чақалари кўпроқ эдилар. Бас, ўз насибалари ила маза қилдилар, ўзингиздан олдингилар насибалари ила маза қилганларидек, сиз ҳам ўз насибангиз ила маза қилдингиз. Улар шунғигандек, сиз ҳам шунғидингиз. Ана ўшаларнинг амаллари дунёю охиратда ҳабата бўлди. Ана ўшалар, ўзлари зиён кўргувчилардир.",198,10],["أَلَمْ يَأْتِهِمْ نَبَأُ [h:5710[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ قَوْمِ نُو[a:5711[حٍ و]َعَا[a:5712[دٍ و]َثَمُودَ وَقَوْمِ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَأَصْحَ[n[ـٰ]بِ مَ[q:4842[دْ]يَنَ وَ[h:5713[ٱ]لْمُؤْتَفِكَ[n[ـٰ]تِ‌ۚ أَتَتْهُمْ رُسُلُه[c:4900[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ‌ۖ فَمَا كَانَ [h:742[ٱ]للَّهُ لِيَظْلِمَهُمْ وَلَ[n[ـٰ]كِ[f:276[ن ك]َان[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ يَظْلِم[p[ُو]نَ","Уларга ўзларидан олдин ўтганларнинг, Нуҳ, Од, Самуд қавмининг ва Иброҳим қавмининг, Мадян эгаларининг ва тўнтарилганларнинг хабари келмадими? Уларга Пайғамбарлари очиқ-ойдин ҳужжатлар билан келдилар. Бас, Аллоҳ уларга зулм қилмас эди. Лекин улар ўзларига зулм қилар эдилар.",198,10],["وَ[h:9999[ٱ]لْمُؤْمِنُونَ وَ[h:5714[ٱ]لْمُؤْمِنَ[n[ـٰ]تُ بَعْضُهُمْ أَوْلِي[o[َا]ٓءُ بَعْ[a:5693[ضٍ‌ۚ ي]َأْمُرُونَ بِ[h:934[ٱ]لْمَعْرُوفِ وَيَنْهَوْنَ عَنِ [h:2144[ٱ]لْمُ[f:2145[نك]َرِ وَيُقِيمُونَ [h:14[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَيُؤْتُونَ [h:3639[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَيُطِيعُونَ [h:5715[ٱ]للَّهَ وَرَسُولَهُ[o[ۥٓ‌ۚ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ سَيَرْحَمُهُمُ [h:5716[ٱ]للَّهُ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَزِيزٌ حَك[p[ِي]مٌ","Мўмин эркаклар ва мўмина аёллар бир-бирларига дўстдирлар. Улар яхшиликка буюрарлар, ёмонликдан қайтарарлар, намозни тўкис адо этарлар, закотни берарлар ҳамда Аллоҳга ва Унинг Расулига итоат қиларлар. Ана ўшаларга Аллоҳ тезда раҳм қилур. Албатта, Аллоҳ ғолиб ва ҳикматли зотдир.",198,10],["وَعَدَ [h:3055[ٱ]للَّهُ [h:5717[ٱ]لْمُؤْمِنِينَ وَ[h:5718[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا وَمَسَ[n[ـٰ]كِنَ طَيِّبَ[f:5719[ةً ف]ِى جَ[g[نّ]َ[n[ـٰ]تِ عَ[q:5720[دْ][a:5721[نٍ‌ۚ و]َرِضْو[n[َٲ][a:1789[نٌ م]ِّنَ [h:321[ٱ]للَّهِ أَكْبَرُ‌ۚ ذ[n[َٲ]لِكَ هُوَ [h:5722[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Аллоҳ мўмин эр ва мўмина аёлларга остидан анҳорлар оқиб турган жаннатларни, уларда абадий қолишни ва барқарорлик жаннатидан покиза масканларни ваъда қилди. Аллоҳдан бўладиган розилик эса, энг улуғидир. Ана ўша улкан ютуқдир.",198,10],["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ جَ[n[ـٰ]هِدِ [h:5723[ٱ]لْكُفَّارَ وَ[h:5724[ٱ]لْمُنَ[n[ـٰ]فِقِينَ وَ[h:5725[ٱ]غْلُظْ عَلَيْهِمْ‌ۚ وَمَأْوَ[n[ٮٰ]هُمْ جَهَ[g[نّ]َمُ‌ۖ وَبِئْسَ [h:665[ٱ]لْمَص[p[ِي]رُ","Эй Пайғамбар, кофирлар ва мунофиқларга қарши жиҳод қил ва уларга нисбатан қаттиққўл бўл. Уларнинг жойи жаҳаннамдир. У қандай ҳам ёмон қайтадиган жой.",199,10],["يَحْلِفُونَ بِ[h:32[ٱ]للَّهِ مَا قَالُو[s[اْ] وَلَقَ[q:341[دْ] قَالُو[s[اْ] كَلِمَةَ [h:5726[ٱ]لْكُفْرِ وَكَفَرُو[s[اْ] بَعْدَ إِسْلَ[n[ـٰ]مِهِمْ وَهَ[g[مّ]ُو[s[اْ] بِمَا لَمْ يَنَالُو[s[اْ‌ۚ] وَمَا نَقَم[o[ُوٓ][s[اْ] إِلّ[o[َآ] أَنْ أَغْنَ[n[ـٰ]هُمُ [h:5727[ٱ]للَّهُ وَرَسُولُهُ[n[ۥ] مِ[f:475[ن ف]َضْلِه[n[ِۦ]‌ۚ فَإ[a:5728[ِن ي]َتُوبُو[s[اْ] يَكُ خَيْ[u:2160[رًا ل]َّهُمْ‌ۖ وَإ[a:5729[ِن ي]َتَوَلَّوْ[s[اْ] يُعَذِّ[q:5495[بْ]هُمُ [h:5496[ٱ]للَّهُ عَذَابًا أَلِي[f:5730[مًا ف]ِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ‌ۚ وَمَا لَهُمْ فِى [h:44[ٱ]لْأَرْضِ م[a:557[ِن و]َلِ[a:558[ىٍّ و]َلَا نَص[p[ِي]رٍ","Улар гапирмаганлари ҳақида Аллоҳнинг номи ила қасам ичарлар. Батаҳқиқ, куфр калимасини айтдилар ва Исломларидан кейин куфр келтирдилар ҳамда ета олмаган нарсаларга қасд қилдилар. Аллоҳ ва Унинг Расули уларни Ўз фазлидан бой қилиб қўйганларидан бошқа «айб» топа олмадилар. Агар тавба қилсалар, ўзларига яхши бўладир. Гар юз ўгириб кетсалар, Аллоҳ уларни бу дунёю охиратда аламли азоб билан азоблайдир. Ер юзида уларга дўст ҳам, ёрдамчи ҳам йўқ.",199,10],["۞ وَمِنْه[w:1106[ُم م]َّنْ عَ[n[ـٰ]هَدَ [h:5731[ٱ]للَّهَ لَئِنْ ءَاتَ[n[ـٰ]نَا مِ[f:475[ن ف]َضْلِه[n[ِۦ] لَنَصَّدَّقَ[g[نّ]َ وَلَنَكُونَ[g[نّ]َ مِنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Улардан: «Агар У зот Ўз фазлидан берса, албатта, садақа қиламиз ва, албатта, аҳли солиҳлардан бўламиз», деб Аллоҳга аҳд берувчилар бор.",199,10],["فَلَ[g[مّ][o[َآ] ءَاتَ[n[ـٰ]ه[w:5732[ُم م]ِّ[f:475[ن ف]َضْلِه[n[ِۦ] بَخِلُو[s[اْ] بِه[n[ِۦ] وَتَوَلَّو[s[اْ] وَّه[w:1817[ُم م]ُّعْرِض[p[ُو]نَ","У зот Ўз фазлидан берган чоғда эса, бахиллик қилиб, юз ўгириб, орқага қараб кетарлар.",199,10],["فَأَعْقَبَهُمْ نِفَا[f:5733[قًا ف]ِى قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُ[n[ۥ] بِم[o[َآ] أَخْلَفُو[s[اْ] [h:5734[ٱ]للَّهَ مَا وَعَدُوهُ وَبِمَا كَانُو[s[اْ] يَكْذِب[p[ُو]نَ","Бас, Аллоҳга берган ваъдаларига хилоф қилганлари ва ёлғон гапирганлари учун Унга рўбарў бўладиган кунгача қалбларида нифоқни оқибат қилиб қўйди.",199,10],["أَلَمْ يَعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَعْلَمُ سِرَّهُمْ وَنَ[q:5735[جْ]وَ[n[ٮٰ]هُمْ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ عَلَّ[n[ـٰ]مُ [h:3865[ٱ]لْغُي[p[ُو][q[ب]ِ","Улар Аллоҳ уларнинг сирларини ҳам, яширин гапларини ҳам албатта билишини ва Аллоҳ, албатта, ғайбларни билгувчи зот эканини билмасмидилар?",199,10],["ٱلَّذِينَ يَلْمِزُونَ [h:5736[ٱ]لْمُطَّوِّعِينَ مِنَ [h:3047[ٱ]لْمُؤْمِنِينَ فِى [h:5663[ٱ][l[ل]صَّدَقَ[n[ـٰ]تِ وَ[h:37[ٱ]لَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ‌ۙ سَخِرَ [h:5737[ٱ]للَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Мўминлардан кўнгилли бўлиб садақа қилувчиларни ва ўз кучлари етгандан бошқани топа олмайдиганларни айблайдиган ва масхара қиладиганларни Аллоҳ масхара қилади ва уларга аламли азоб бўладир.",199,10],["ٱسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِ[f:5738[ن ت]َسْتَغْفِرْ لَهُمْ سَ[q:5045[بْ]عِينَ مَرَّ[f:5739[ةً ف]َل[a:5740[َن ي]َغْفِرَ [h:5741[ٱ]للَّهُ لَهُمْ‌ۚ ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ كَفَرُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ]‌ۗ وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:3860[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","Улар учун истиғфор айтсанг ҳам ёки истиғфор айтмасанг ҳам. Агар улар учун етмиш марта истиғфор айтсанг ҳам, Аллоҳ уларни зинҳор мағфират қилмас. Бу уларнинг Аллоҳ ва Унинг Расулига куфр келтирганлари учундир. Аллоҳ фосиқ қавмларни ҳидоят қилмас.",200,10],["فَرِحَ [h:5742[ٱ]لْمُخَلَّفُونَ بِمَ[q:5743[قْ]عَدِهِمْ خِلَ[n[ـٰ]فَ رَسُولِ [h:5744[ٱ]للَّهِ وَكَرِه[o[ُوٓ][s[اْ] أ[a:5616[َن ي]ُجَ[n[ـٰ]هِدُو[s[اْ] بِأَمْو[n[َٲ]لِهِمْ وَأَ[f:3050[نف]ُسِهِمْ فِى سَبِيلِ [h:788[ٱ]للَّهِ وَقَالُو[s[اْ] لَا تَ[f:5584[نف]ِرُو[s[اْ] فِى [h:5745[ٱ]لْحَرِّ‌ۗ قُلْ نَارُ جَهَ[g[نّ]َمَ أَشَدُّ حَر[u:5746[ًّا‌ۚ ل]َّوْ كَانُو[s[اْ] يَفْقَه[p[ُو]نَ","Улар Аллоҳнинг Расулига хилоф қилиб ортда қолганлар ўтирган жойларида хурсанд бўлдилар ва Аллоҳнинг йўлида моллари ва жонлари билан жиҳод қилишни ёқтирмадилар ҳамда «Иссиқда қўзғолманглар», дедилар. Сен: «Жаҳаннамнинг оташи иссиқроқ, агар тушунсалар», деб айт.",200,10],["فَلْيَضْحَكُو[s[اْ] قَلِيل[a:5747[اً و]َلْيَ[q:5748[بْ]كُو[s[اْ] كَثِي[f:5749[رًا ج]َز[o[َا]ٓ[i:3537[ءَۢ ب]ِمَا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Бас, қилган касблари туфайли оз кулиб, кўп йиғласинлар.",200,10],["فَإ[u:5750[ِن ر]َّجَعَكَ [h:5751[ٱ]للَّهُ إِلَىٰ ط[o[َا]ٓئِفَ[a:5752[ةٍ م]ِّنْهُمْ فَ[h:5753[ٱ]سْتَــْٔذَنُوكَ لِلْخُرُوجِ فَقُل لَّ[f:5754[ن ت]َخْرُجُو[s[اْ] مَعِىَ أَبَ[a:5755[دًا و]َلَ[f:5756[ن ت]ُقَ[n[ـٰ]تِلُو[s[اْ] مَعِىَ عَدُوًّا‌ۖ إِ[g[نّ]َكُمْ رَضِيت[c:5757[ُم ب]ِ[h:5758[ٱ]لْقُعُودِ أَوَّلَ مَرَّ[f:5759[ةٍ ف]َ[h:5760[ٱ][q:5760[قْ]عُدُو[s[اْ] مَعَ [h:5761[ٱ]لْخَ[n[ـٰ]لِف[p[ِي]نَ","Бас, Аллоҳ сени улардан бир тоифасига қайтарса-ю, улар сендан чиқишга изн сўрасалар: «Мен билан ҳеч қачон чиқмайсизлар ва мен билан бирга ҳеч қачон жанг қилмайсизлар, сизлар биринчи мартада ўтиришга рози бўлдингиз, бас, ортда қолувчилар билан ўтираверинглар», деб айт.",200,10],["وَلَا تُصَلِّ عَلَ[o[ىٰٓ] أَحَ[a:702[دٍ م]ِّنْه[w:5762[ُم م]َّاتَ أَبَ[a:5763[دًا و]َلَا تَقُمْ عَلَىٰ قَ[q:5764[بْ]رِه[o[ِۦٓ‌ۖ] إِ[g[نّ]َهُمْ كَفَرُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] وَمَاتُو[s[اْ] وَهُمْ فَ[n[ـٰ]سِق[p[ُو]نَ","Ва ҳеч қачон улардан ўлган бирортасига ҳам намоз ўқима, қабри устида турма. Чунки улар Аллоҳга ва Унинг Расулига куфр келтирдилар ҳамда фосиқ ҳолларида ўлдилар.",200,10],["وَلَا تُعْجِ[q:5655[بْ]كَ أَمْو[n[َٲ]لُهُمْ وَأَوْلَ[n[ـٰ]دُهُمْ‌ۚ إِ[g[نّ]َمَا يُرِيدُ [h:976[ٱ]للَّهُ أ[a:5765[َن ي]ُعَذِّبَه[c:5766[ُم ب]ِهَا فِى [h:599[ٱ][l[ل]دُّنْيَا وَتَزْهَقَ أَ[f:2341[نف]ُسُهُمْ وَهُمْ كَ[n[ـٰ]فِر[p[ُو]نَ","Уларнинг мол-дунёлари ва бола-чақалари сени ажаблантирмасин. Аслида, Аллоҳ ўша нарсалар сабабли уларни дунёда азоблашни ва кофир ҳолларида жонлари чиқишни хоҳлайди, холос.",200,10],["وَإِذ[o[َآ] أُ[f:5767[نز]ِلَتْ سُورَةٌ أَنْ ءَامِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَجَ[n[ـٰ]هِدُو[s[اْ] مَعَ رَسُولِهِ [h:5768[ٱ]سْتَــْٔذَنَكَ أُ[s[وْ]لُو[s[اْ] [h:5769[ٱ][l[ل]طَّوْلِ مِنْهُمْ وَقَالُو[s[اْ] ذَرْنَا نَك[a:5770[ُن م]َّعَ [h:5626[ٱ]لْقَ[n[ـٰ]عِد[p[ِي]نَ","«Аллоҳга иймон келтиринглар ва Унинг Расули билан жиҳод қилинглар», деб сура нозил қилинган пайтда улардан бой-задагонлари: «Бизни тек қўй, ўтирувчилар билан бирга бўлайлик», деб изн сўрарлар.",200,10],["رَضُو[s[اْ] بِأ[a:5771[َن ي]َكُونُو[s[اْ] مَعَ [h:5772[ٱ]لْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَه[p[ُو]نَ","Улар хотин-халажлар билан бирга бўлишга рози бўлдилар ва қалбларига муҳр босилди. Бас, улар англамаслар.",201,10],["لَ[n[ـٰ]كِنِ [h:5773[ٱ][l[ل]رَّسُولُ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مَعَهُ[n[ۥ] جَ[n[ـٰ]هَدُو[s[اْ] بِأَمْو[n[َٲ]لِهِمْ وَأَ[f:3050[نف]ُسِهِمْ‌ۚ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمُ [h:5774[ٱ]لْخَيْر[n[َٲ]تُ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Лекин Пайғамбар ва у билан бирга иймон келтирганлар моллари ва жонлари билан жиҳод қилдилар. Ана ўшаларга, ўзларига яхшиликлар бўладир. Ана ўшалар, ўзлари нажот топгувчилардир.",201,10],["أَعَدَّ [h:5775[ٱ]للَّهُ لَهُمْ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۚ ذ[n[َٲ]لِكَ [h:3911[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Аллоҳ улар учун остида анҳорлар оқиб турган жаннатларни тайёрлаб қўйди. Унда абадий қолурлар. Ана шу буюк ютуқдир.",201,10],["وَج[o[َا]ٓءَ [h:5776[ٱ]لْمُعَذِّرُونَ مِنَ [h:5777[ٱ]لْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ [h:5778[ٱ]لَّذِينَ كَذَبُو[s[اْ] [h:5779[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ]‌ۚ سَيُصِيبُ [h:4389[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِنْهُمْ عَذَابٌ أَل[p[ِي]مٌ","Аъробийлардан узр айтувчилар уларга изн берилишини сўраб келдилар. Аллоҳга ва Расулига ёлғон гапирганлар эса, ўтириб қолдилар. Улардан кофир бўлганларга аламли азоб етадир.",201,10],["لَّيْسَ عَلَى [h:5780[ٱ][l[ل]ضُّعَف[o[َا]ٓءِ وَلَا عَلَى [h:5781[ٱ]لْمَرْضَىٰ وَلَا عَلَى [h:289[ٱ]لَّذِينَ لَا يَجِدُونَ مَا يُ[f:16[نف]ِقُونَ حَرَجٌ إِذَا نَصَحُو[s[اْ] لِلَّهِ وَرَسُولِه[n[ِۦ]‌ۚ مَا عَلَى [h:1343[ٱ]لْمُحْسِنِينَ مِ[f:5782[ن س]َبِي[a:5783[لٍ‌ۚ و]َ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Заифҳолларга, беморларга ва сарф-харажат қиладиган нарса топа олмаётганларга, Аллоҳга ва Расулига ихлосли бўлсалар, насиҳат қилсалар, гуноҳ йўқ. Чиройли амал қилувчиларни айблашга йўл йўқ. Аллоҳ мағфиратли ва раҳмли зотдир.",201,10],["وَلَا عَلَى [h:289[ٱ]لَّذِينَ إِذَا م[o[َآ] أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ ل[o[َآ] أَجِدُ م[o[َآ] أَحْمِلُكُمْ عَلَيْهِ تَوَلَّو[s[اْ] وَّأَعْيُنُهُمْ تَفِيضُ مِنَ [h:3742[ٱ][l[ل]دَّمْعِ حَزَنًا أَلَّا يَجِدُو[s[اْ] مَا يُ[f:16[نف]ِق[p[ُو]نَ","Яна сенга улов беришинг учун келганларида: «Сизларни миндиргани нарса топа олмаяпман», деганингда ғамгин бўлиб, кўзларидан ёшлари тўкилиб, орқага қайтиб кетганларга ҳам, сарф-харажат қиладиган нарса топа олмаганлари учун гуноҳ йўқ.",201,10],["۞ إِ[g[نّ]َمَا [h:5784[ٱ][l[ل]سَّبِيلُ عَلَى [h:289[ٱ]لَّذِينَ يَسْتَــْٔذِنُونَكَ وَهُمْ أَغْنِي[o[َا]ٓءُ‌ۚ رَضُو[s[اْ] بِأ[a:5771[َن ي]َكُونُو[s[اْ] مَعَ [h:5772[ٱ]لْخَوَالِفِ وَطَبَعَ [h:5785[ٱ]للَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَم[p[ُو]نَ","Бой-бадавлат бўлиб туриб сендан изн сўрайдиганларни айблашга йўл бор. Улар хотин-халажлар билан бирга бўлишга рози бўлдилар. Аллоҳ уларнинг қалбларига муҳр босди. Бас, улар билмаслар.",201,11],["يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ‌ۚ قُل لَّا تَعْتَذِرُو[s[اْ] ل[a:265[َن ن]ُّؤْمِنَ لَكُمْ قَ[q:298[دْ] نَبَّأَنَا [h:5786[ٱ]للَّهُ مِنْ أَخْبَارِكُمْ‌ۚ وَسَيَرَى [h:5787[ٱ]للَّهُ عَمَلَكُمْ وَرَسُولُهُ[n[ۥ] ثُ[g[مّ]َ تُرَدُّونَ إِلَىٰ عَ[n[ـٰ]لِمِ [h:5788[ٱ]لْغَيْبِ وَ[h:4187[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ فَيُنَبِّئُك[c:3605[ُم ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Ҳузурларига қайтиб келганингизда, сизга узр айтадилар. Сен: «Узр айтманглар, биз сизларга ҳеч қачон ишонмаймиз. Батаҳқиқ, Аллоҳ бизга сизларнинг хабарларингизни берди. Албатта, Аллоҳ ва Унинг Расули амалингизни кўрадир, сўнгра ғайбни ва шаҳодатни билгувчи зотга қайтарилурсизлар. Бас, у сизга қилиб юрган амалингизнинг хабарини берадир», деб айт.",202,11],["سَيَحْلِفُونَ بِ[h:32[ٱ]للَّهِ لَكُمْ إِذَا [h:5789[ٱ][f:2280[نق]َلَ[q:2280[بْ]تُمْ إِلَيْهِمْ لِتُعْرِضُو[s[اْ] عَنْهُمْ‌ۖ فَأَعْرِضُو[s[اْ] عَنْهُمْ‌ۖ إِ[g[نّ]َهُمْ رِ[q:3765[جْ][a:5790[سٌ‌ۖ و]َمَأْوَ[n[ٮٰ]هُمْ جَهَ[g[نّ]َمُ جَز[o[َا]ٓ[i:3537[ءَۢ ب]ِمَا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Уларнинг ҳузурларига қайтиб келганингизда уларни айбламаслигингиз учун сизга Аллоҳнинг номи ила қасам ичадилар. Бас, улардан юз ўгиринглар! Албатта, улар нопокдирлар. Қилиб юрган касблари жазосига жойлари жаҳаннамдадир.",202,11],["يَحْلِفُونَ لَكُمْ لِتَرْضَوْ[s[اْ] عَنْهُمْ‌ۖ فَإِ[f:5791[ن ت]َرْضَوْ[s[اْ] عَنْهُمْ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ لَا يَرْضَىٰ عَنِ [h:4503[ٱ]لْقَوْمِ [h:3491[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","Улар сизлар улардан рози бўлишингиз учун сизга қасам ичарлар. Агарчи сиз улардан рози бўлсангиз ҳам, Аллоҳ фосиқ қавмлардан рози бўлмас.",202,11],["ٱلْأَعْرَابُ أَشَدُّ كُفْ[a:5792[رًا و]َنِفَا[a:5793[قًا و]َأَ[q:5794[جْ]دَرُ أَلَّا يَعْلَمُو[s[اْ] حُدُودَ م[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ عَلَىٰ رَسُولِه[n[ِۦ]‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Аъробийлар куфр ва нифоқда ашаддийроқ ва Аллоҳ Ўз Пайғамбарига нозил қилган нарсанинг чегараларини билмасликка лойиқроқдирлар. Аллоҳ билгувчи ва ҳикматли зотдир.",202,11],["وَمِنَ [h:5795[ٱ]لْأَعْرَابِ م[a:851[َن ي]َتَّخِذُ مَا يُ[f:1550[نف]ِقُ مَغْرَ[a:5796[مًا و]َيَتَرَبَّصُ بِكُمُ [h:5797[ٱ][l[ل]دَّو[o[َا]ٓئِرَ‌ۚ عَلَيْهِمْ د[o[َا]ٓئِرَةُ [h:5798[ٱ][l[ل]سَّوْءِ‌ۗ وَ[h:72[ٱ]للَّهُ سَمِيعٌ عَل[p[ِي]مٌ","Аъробийлардан қилган инфоқни зиён деб биладиган ва сизга бало-офат келишини кутиб турадиганлари ҳам бор. Ёмон балолар ўзларига урсин! Аллоҳ эшитгувчи ва билгувчи зотдир.",202,11],["وَمِنَ [h:5795[ٱ]لْأَعْرَابِ م[a:5799[َن ي]ُؤْمِنُ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ وَيَتَّخِذُ مَا يُ[f:1550[نف]ِقُ قُرُبَ[n[ـٰ]تٍ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَصَلَو[n[َٲ]تِ [h:5800[ٱ][l[ل]رَّسُولِ‌ۚ أَل[o[َآ] إِ[g[نّ]َهَا قُرْبَ[u:5801[ةٌ ل]َّهُمْ‌ۚ سَيُ[q:5802[دْ]خِلُهُمُ [h:5803[ٱ]للَّهُ فِى رَحْمَتِه[o[ِۦٓ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Аъробийлардан Аллоҳга ва охират кунига иймон келтирадиган ҳамда инфоқ қиладиган нарсасини Аллоҳга қурбат ҳосил қилиш ва Расулнинг дуосига мушарраф этиш воситаси деб биладиганлари ҳам бор. Билсинларки, албатта, ўша нарсалар улар учун қурбатдир. Албатта, Аллоҳ уларни ўз раҳматига киритади. Албатта, Аллоҳ мағфиратли ва раҳмли зотдир.",202,11],["وَ[h:9999[ٱ][l[ل]سَّ[n[ـٰ]بِقُونَ [h:5804[ٱ]لْأَوَّلُونَ مِنَ [h:5805[ٱ]لْمُهَ[n[ـٰ]جِرِينَ وَ[h:5806[ٱ]لْأَ[f:5806[نص]َارِ وَ[h:37[ٱ]لَّذِينَ [h:5807[ٱ]تَّبَعُوه[c:5808[ُم ب]ِإِحْسَ[n[ـٰ][u:5809[نٍ ر]َّضِىَ [h:3910[ٱ]للَّهُ عَنْهُمْ وَرَضُو[s[اْ] عَنْهُ وَأَعَدَّ لَهُمْ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى تَحْتَهَا [h:5810[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَ[f:5811[دًا‌ۚ ذ][n[َٲ]لِكَ [h:3911[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Биринчи пешқадам муҳожирлар ва ансорийлар ва уларга яхшилик билан эргашганлар. Аллоҳ улардан рози бўлди, улар ҳам Аллоҳдан рози бўлдилар. Уларга остидан анҳорлар оқиб турган жаннатларни тайёрлаб қўйди. Уларда абадий қолурлар. Ана ўша улкан ютуқдир.",203,11],["وَمِ[g[مّ]َنْ حَوْلَك[w:5812[ُم م]ِّنَ [h:5777[ٱ]لْأَعْرَابِ مُنَ[n[ـٰ]فِقُونَ‌ۖ وَمِنْ أَهْلِ [h:5813[ٱ]لْمَدِينَةِ‌ۖ مَرَدُو[s[اْ] عَلَى [h:5814[ٱ][l[ل][g[نّ]ِفَاقِ لَا تَعْلَمُهُمْ‌ۖ نَحْنُ نَعْلَمُهُمْ‌ۚ سَنُعَذِّبُه[w:5815[ُم م]َّرَّتَيْنِ ثُ[g[مّ]َ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظ[p[ِي]مٍ","Атрофингиздаги аъробийлардан мунофиқлар бор. Мадина аҳлидан ҳам. Улар нифоқда сийқаси чиққанлардир. Сен уларни билмассан, уларни Биз биурамиз. Албатта, уларни икки марта азоблаймиз. Сўнгра улкан азобга қайтарилурлар.",203,11],["وَءَاخَرُونَ [h:5816[ٱ]عْتَرَفُو[s[اْ] بِذُنُوبِهِمْ خَلَطُو[s[اْ] عَمَل[f:5817[اً ص]َ[n[ـٰ]لِ[a:5818[حًا و]َءَاخَرَ سَيِّئًا عَسَى [h:2982[ٱ]للَّهُ أ[a:2726[َن ي]َتُوبَ عَلَيْهِمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Бошқалар эса, гуноҳларини эътироф қилдилар; улар яхши ва ёмон амални аралаштириб қилганлардир. Шоядки Аллоҳ уларнинг тавбасини қабул қилса. Албатта, Аллоҳ мағфиратли ва раҳмли зотдир.",203,11],["خُذْ مِنْ أَمْو[n[َٲ]لِهِمْ صَدَقَ[f:5819[ةً ت]ُطَهِّرُهُمْ وَتُزَكِّيه[c:5820[ِم ب]ِهَا وَصَلِّ عَلَيْهِمْ‌ۖ إِ[g[نّ]َ صَلَ[s[و][n[ٲ]تَكَ سَكَ[u:5821[نٌ ل]َّهُمْ‌ۗ وَ[h:72[ٱ]للَّهُ سَمِيعٌ عَل[p[ِي]مٌ","Уларнинг молларидан садақа ол. Бу билан уларни поклайсан, тозалайсан ва уларнинг ҳаққига дуо қил. Албатта, сенинг дуоинг улар учун сокинликдир. Аллоҳ эшитгуви ва билгувчи зотдир.",203,11],["أَلَمْ يَعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ هُوَ يَ[q:5822[قْ]بَلُ [h:5823[ٱ][l[ل]تَّوْبَةَ عَنْ عِبَادِه[n[ِۦ] وَيَأْخُذُ [h:5824[ٱ][l[ل]صَّدَقَ[n[ـٰ]تِ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ هُوَ [h:194[ٱ][l[ل]تَّوَّابُ [h:195[ٱ][l[ل]رَّح[p[ِي]مُ","Улар, албатта, Аллоҳ Ўз бандаларидан тавбани қабул қилишини ва садақаларни олишини ва, албатта, Аллоҳнинг Ўзи тавбаларни кўплаб қабул қилгувчи ва раҳмли зот эканини билмайдиларми?",203,11],["وَقُلِ [h:5825[ٱ]عْمَلُو[s[اْ] فَسَيَرَى [h:5826[ٱ]للَّهُ عَمَلَكُمْ وَرَسُولُهُ[n[ۥ] وَ[h:1709[ٱ]لْمُؤْمِنُونَ‌ۖ وَسَتُرَدُّونَ إِلَىٰ عَ[n[ـٰ]لِمِ [h:5788[ٱ]لْغَيْبِ وَ[h:4187[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ فَيُنَبِّئُك[c:3605[ُم ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Сен: «Амал қилинглар! Бас, албатта, Аллоҳ, Унинг Расули ва мўминлар амалингизни кўрарлар. Ва, албатта, ғайбни ва шаҳодатни билгувчи зотга қайтариласизлар. Бас, У сизларга қилиб юрган амалларингизнинг хабарини берадир»– деб айт.",203,11],["وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ [h:5827[ٱ]للَّهِ إِ[g[مّ]َا يُعَذِّبُهُمْ وَإِ[g[مّ]َا يَتُوبُ عَلَيْهِمْ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Ва Аллоҳнинг амрига ҳавола қилинган бошқалар бор. Уларни ёки азоблайдир ёки тавбаларини қабул қиладир. Аллоҳ билгувчи ва ҳикматли зотдир.",203,11],["وَ[h:9999[ٱ]لَّذِينَ [h:5828[ٱ]تَّخَذُو[s[اْ] مَسْجِ[f:5829[دًا ض]ِرَا[a:5830[رًا و]َكُفْ[a:5831[رًا و]َتَفْرِيق[i:5832[َۢا ب]َيْنَ [h:5833[ٱ]لْمُؤْمِنِينَ وَإِرْصَا[u:5834[دًا ل]ِّمَنْ حَارَبَ [h:5835[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۚ وَلَيَحْلِفُ[g[نّ]َ إِنْ أَرَ[q:2878[دْ]ن[o[َآ] إِلَّا [h:5836[ٱ]لْحُسْنَىٰ‌ۖ وَ[h:72[ٱ]للَّهُ يَشْهَدُ إِ[g[نّ]َهُمْ لَكَ[n[ـٰ]ذِب[p[ُو]نَ","Зиён, куфр, мўминлар орасига тафриқа солиш ва бундан олдин Аллоҳга ва Унинг Расулига уруш очган кимсани кутиш жойи бўлиши учун масжид қурганлар, албатта, биз яхшиликдан бошқа нарсани ирода қилганимиз йўқ, деб қасам ичарлар. Аллоҳ шоҳидлик берадики, улар, албатта, ёлғончилардир.",204,11],["لَا تَقُمْ فِيهِ أَبَ[u:5837[دًا‌ۚ ل]َّمَسْجِدٌ أُسِّسَ عَلَى [h:5838[ٱ][l[ل]تَّ[q:1084[قْ]وَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَ[f:5839[ن ت]َقُومَ فِيهِ‌ۚ فِيهِ رِجَا[a:5840[لٌ ي]ُحِبُّونَ أ[a:5841[َن ي]َتَطَهَّرُو[s[اْ‌ۚ] وَ[h:72[ٱ]للَّهُ يُحِبُّ [h:5842[ٱ]لْمُطَّهِّر[p[ِي]نَ","Сен у да ҳеч қачон турма! Албатта, биринчи кундан тақво асосида қурилган масжидда турмоқлигинг ҳақдир. Унда покланишни севадиган кишилар бор. Аллоҳ эса покланувчиларни севадир.",204,11],["أَفَمَنْ أَسَّسَ بُنْيَ[n[ـٰ]نَهُ[n[ۥ] عَلَىٰ تَ[q:5843[قْ]وَىٰ مِنَ [h:321[ٱ]للَّهِ وَرِضْو[n[َٲ]نٍ خَيْرٌ أ[w:3110[َم م]َّنْ أَسَّسَ بُنْيَ[n[ـٰ]نَهُ[n[ۥ] عَلَىٰ شَفَا جُرُفٍ هَا[f:5844[رٍ ف]َ[h:5845[ٱ]نْهَارَ بِه[n[ِۦ] فِى نَارِ جَهَ[g[نّ]َمَ‌ۗ وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Биносини Аллоҳга бўлган тақво ва Унинг розилиги асосида қурган кимса яхшими ёки биносини емирилаётган жар ёқасини асос қилиб қуриб у билан бирга жаҳаннам ўтига қулаган кимса яхшими? Ва Аллоҳ золим қавмларни ҳидоят қилмас.",204,11],["لَا يَزَالُ بُنْيَ[n[ـٰ]نُهُمُ [h:5846[ٱ]لَّذِى بَنَوْ[s[اْ] رِيبَ[f:5847[ةً ف]ِى قُلُوبِهِمْ إِلّ[o[َآ] أَ[f:5848[ن ت]َقَطَّعَ قُلُوبُهُمْ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Барпо қилган бинолари қалбларида шак-шубҳа ҳолида бардавом қолади. Магар қалблари қиймаланиб кетсагина шак-шубҳа қолмас. Аллоҳ билгувчи ва ҳикматли зотдир.",204,11],["۞ إِ[g[نّ]َ [h:80[ٱ]للَّهَ [h:5849[ٱ]شْتَرَىٰ مِنَ [h:3047[ٱ]لْمُؤْمِنِينَ أَ[f:38[نف]ُسَهُمْ وَأَمْو[n[َٲ]لَه[c:5850[ُم ب]ِأَ[g[نّ]َ لَهُمُ [h:5851[ٱ]لْجَ[g[نّ]َةَ‌ۚ يُقَ[n[ـٰ]تِلُونَ فِى سَبِيلِ [h:788[ٱ]للَّهِ فَيَ[q:5852[قْ]تُلُونَ وَيُ[q:5853[قْ]تَلُونَ‌ۖ وَعْدًا عَلَيْهِ حَق[f:5854[ًّا ف]ِى [h:5061[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةِ وَ[h:5062[ٱ]لْإِ[f:5062[نج]ِيلِ وَ[h:5855[ٱ]لْقُرْءَانِ‌ۚ وَمَنْ أَوْفَىٰ بِعَهْدِه[n[ِۦ] مِنَ [h:321[ٱ]للَّهِ‌ۚ فَ[h:5856[ٱ]سْتَ[q:5856[بْ]شِرُو[s[اْ] بِبَيْعِكُمُ [h:5857[ٱ]لَّذِى بَايَعْت[c:5858[ُم ب]ِه[n[ِۦ]‌ۚ وَذ[n[َٲ]لِكَ هُوَ [h:5722[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Албатта, Аллоҳ мўминлардан уларнинг жонлари ва молларини жаннат эвазига сотиб олди. Улар Аллоҳнинг йўлида жанг қиладилар, ўлдирадилар ва ўлдириладилар. Бу Тавротда, Инжилда ва Қуръонда Унинг зиммасидаги ҳақ ваъдадир. Аллоҳдан ҳам аҳдига вафодорроқ ким бор? Ким Аллоҳга берган аҳдига вафо қилса, бас, қилган савдоларингиздан шод бўлаверинг. Ана шунинг ўзи улкан ютуқдир.",204,11],["ٱ[l[ل]تَّ[o[ـٰٓ]ئِبُونَ [h:5859[ٱ]لْعَ[n[ـٰ]بِدُونَ [h:5860[ٱ]لْحَ[n[ـٰ]مِدُونَ [h:5861[ٱ][l[ل]سَّ[o[ـٰٓ]ئِحُونَ [h:5862[ٱ][l[ل]رّ[n[َٲ]كِعُونَ [h:5863[ٱ][l[ل]سَّ[n[ـٰ]جِدُونَ [h:5864[ٱ]لْأَمِرُونَ بِ[h:934[ٱ]لْمَعْرُوفِ وَ[h:5865[ٱ][l[ل][g[نّ]َاهُونَ عَنِ [h:2144[ٱ]لْمُ[f:2145[نك]َرِ وَ[h:5866[ٱ]لْحَ[n[ـٰ]فِظُونَ لِحُدُودِ [h:5867[ٱ]للَّهِ‌ۗ وَبَشِّرِ [h:1257[ٱ]لْمُؤْمِن[p[ِي]نَ","Улар тавба қилувчилар, ибодат қилувчилар, ҳамд айтувчилар, рўза тутувчилар, рукуъ қилувчилар, сажда қилувчилар, яхшиликка буюриб, ёмонликдан қайтарувчилар, Аллоҳнинг чегарасида турувчилардир. Ва мўминларга хушхабар бер!",205,11],["مَا كَانَ لِل[g[نّ]َبِىِّ وَ[h:37[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أ[a:5868[َن ي]َسْتَغْفِرُو[s[اْ] لِلْمُشْرِكِينَ وَلَوْ كَان[o[ُوٓ][s[اْ] أُ[s[وْ]لِى قُرْبَىٰ م[i:146[ِنۢ ب]َعْدِ مَا تَبَيَّنَ لَهُمْ أَ[g[نّ]َهُمْ أَصْحَ[n[ـٰ]بُ [h:3415[ٱ]لْجَح[p[ِي]مِ","Пайғамбар ва мўминлар учун дўзах эгалари эканлиги аён бўлган мушрикларга, агар яқин қариндошлари бўлса ҳам, истиғфор айтишлари дуруст эмасдир.",205,11],["وَمَا كَانَ [h:5869[ٱ]سْتِغْفَارُ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ لِأَبِيهِ إِلَّا ع[a:5870[َن م]َّوْعِدَ[a:5871[ةٍ و]َعَدَه[o[َآ] إِيَّاهُ فَلَ[g[مّ]َا تَبَيَّنَ لَهُ[o[ۥٓ] أَ[g[نّ]َهُ[n[ۥ] عَدُ[u:5872[وٌّ ل]ِّلَّهِ تَبَرَّأَ مِنْهُ‌ۚ إِ[g[نّ]َ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ لَأَوّ[n[َٲ]هٌ حَل[p[ِي]مٌ","Иброҳимнинг отаси учун айтган истиғфори унга берган ваъдаси устидан эди, холос. Вақтики, унга отасининг Аллоҳга душман эканлиги аён бўлганда ундан воз кечди. Албатта, Иброҳим тазарруъли ва ҳалиймдир.",205,11],["وَمَا كَانَ [h:742[ٱ]للَّهُ لِيُضِلَّ قَوْم[i:5873[َۢا ب]َعْدَ إِذْ هَدَ[n[ٮٰ]هُمْ حَتَّىٰ يُبَيِّنَ لَه[w:3531[ُم م]َّا يَتَّقُونَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","Аллоҳ бир қавмни ҳидоятга бошлаганидан сўнг уларга сақланишлари лозим бўлган нарсани баён қилмасдан туриб залолатга кетказмас. Албатта, Аллоҳ ҳар бир нарсани билгувчи зотдир.",205,11],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَهُ[n[ۥ] مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ يُحْى[n[ِۦ] وَيُمِيتُ‌ۚ وَمَا لَك[w:556[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ م[a:557[ِن و]َلِ[a:558[ىٍّ و]َلَا نَص[p[ِي]رٍ","Албатта, осмонлару ернинг мулки Аллоҳникидир. У тирилтирур ва ўлдирур. Сизларга Аллоҳдан бошқа дўст ҳам йўқ, ёрдамчи ҳам йўқ.",205,11],["لَّقَ[d:5874[د] تَّابَ [h:3700[ٱ]للَّهُ عَلَى [h:5875[ٱ][l[ل][g[نّ]َبِىِّ وَ[h:5876[ٱ]لْمُهَ[n[ـٰ]جِرِينَ وَ[h:5806[ٱ]لْأَ[f:5806[نص]َارِ [h:5877[ٱ]لَّذِينَ [h:5878[ٱ]تَّبَعُوهُ فِى سَاعَةِ [h:5879[ٱ]لْعُسْرَةِ م[i:146[ِنۢ ب]َعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِي[a:5880[قٍ م]ِّنْهُمْ ثُ[g[مّ]َ تَابَ عَلَيْهِمْ‌ۚ إِ[g[نّ]َهُ[n[ۥ] بِهِمْ رَءُو[u:5881[فٌ ر]َّح[p[ِي]مٌ","Батаҳқиқ, Аллоҳ Пайғамбарининг, муҳожир ва ансорларнинг тавбасини қабул қилди. Улардан баъзиларининг қалблари тойиб кетай дегандан сўнг тавбаларини қабул қилди. Албатта, У зот уларга марҳаматли ва меҳрибондир.",205,11],["وَعَلَى [h:5882[ٱ][l[ل]ثَّلَ[n[ـٰ]ثَةِ [h:5883[ٱ]لَّذِينَ خُلِّفُو[s[اْ] حَتَّ[o[ىٰٓ] إِذَا ضَاقَتْ عَلَيْهِمُ [h:5884[ٱ]لْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَ[f:2341[نف]ُسُهُمْ وَظَ[g[نّ][o[ُوٓ][s[اْ] أ[u:4908[َن ل]َّا مَلْجَأَ مِنَ [h:321[ٱ]للَّهِ إِلّ[o[َآ] إِلَيْهِ ثُ[g[مّ]َ تَابَ عَلَيْهِمْ لِيَتُوب[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ هُوَ [h:194[ٱ][l[ل]تَّوَّابُ [h:195[ٱ][l[ل]رَّح[p[ِي]مُ","Ва ортда қолган уч кишига ҳам. Уларга кенг ер тор бўлиб, юраклари сиқилиб, Аллоҳдан қочиб, ўзгага бориб бўлмаслигига ишонганларидан сўнг тавба қилишлари учун тавба эшиги очилди. Албатта, Аллоҳ тавбаларни қабул қилувчи ва раҳмли зотдир.",206,11],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:1643[ٱ]تَّقُو[s[اْ] [h:1644[ٱ]للَّهَ وَكُونُو[s[اْ] مَعَ [h:5885[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","Эй иймон келтирганлар, Аллоҳга тақво қилинглар ва содиқлар ила бирга бўлинглар.",206,11],["مَا كَانَ لِأَهْلِ [h:5886[ٱ]لْمَدِينَةِ وَمَنْ حَوْلَه[w:5887[ُم م]ِّنَ [h:5777[ٱ]لْأَعْرَابِ أ[a:5888[َن ي]َتَخَلَّفُو[s[اْ] ع[u:5889[َن ر]َّسُولِ [h:5744[ٱ]للَّهِ وَلَا يَرْغَبُو[s[اْ] بِأَ[f:4384[نف]ُسِهِمْ ع[a:5890[َن ن]َّفْسِه[n[ِۦ]‌ۚ ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ لَا يُصِيبُهُمْ ظَمَ[a:5891[أٌ و]َلَا نَصَ[a:5892[بٌ و]َلَا مَخْمَصَ[f:5893[ةٌ ف]ِى سَبِيلِ [h:788[ٱ]للَّهِ وَلَا يَطَــُٔونَ مَوْطِ[a:5894[ئًا ي]َغِيظُ [h:5895[ٱ]لْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُ[a:5896[وٍّ ن]َّيْلاً إِلَّا كُتِبَ لَه[c:3276[ُم ب]ِه[n[ِۦ] عَمَ[f:5897[لٌ ص]َ[n[ـٰ]لِحٌ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُضِيعُ أَ[q:2418[جْ]رَ [h:5898[ٱ]لْمُحْسِن[p[ِي]نَ","Мадина аҳлига ва уларнинг атрофидаги аъробийларга Расулуллоҳдан четда қолишлари ва ўз жонларини кўзлаб унинг жонига эътибор қилмасликлари дуруст эмас. Зеро, уларга Аллоҳнинг йўлида ташналик, чарчоқ, очлик етса, кофирларнинг ғазабини чиқарадиган бирон қадам боссалар, душманга бирон зиён етказсалар, албатта, уларга солиҳ амал ёзиладир. Албатта, Аллоҳ яхшилик қилувчиларнинг ажрини зое қилмас.",206,11],["وَلَا يُ[f:16[نف]ِقُونَ نَفَقَ[f:5899[ةً ص]َغِيرَ[a:5900[ةً و]َلَا كَبِيرَ[a:5901[ةً و]َلَا يَ[q:5902[قْ]طَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَ[q:5903[جْ]زِيَهُمُ [h:5904[ٱ]للَّهُ أَحْسَنَ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Кичик ёки катта нафақа қилсалар ҳам, бирон водийни кесиб ўтсалар ҳам, албатта, уларга ёзиладир. Аллоҳ уларга қилган энг гўзал амалларининг мукофотини берадир.",206,11],["۞ وَمَا كَانَ [h:5905[ٱ]لْمُؤْمِنُونَ لِيَ[f:5906[نف]ِرُو[s[اْ] ك[m[َا]ٓفَّ[f:5907[ةً‌ۚ ف]َلَوْلَا نَفَرَ مِ[f:843[ن ك]ُلِّ فِرْقَ[a:5908[ةٍ م]ِّنْهُمْ ط[o[َا]ٓئِفَ[u:5909[ةٌ ل]ِّيَتَفَقَّهُو[s[اْ] فِى [h:1477[ٱ][l[ل]دِّينِ وَلِيُ[f:5910[نذ]ِرُو[s[اْ] قَوْمَهُمْ إِذَا رَجَع[o[ُوٓ][s[اْ] إِلَيْهِمْ لَعَلَّهُمْ يَحْذَر[p[ُو]نَ","Мўминларнинг ҳаммалари қўзғолишлари лозим эмас. Ҳар жамоадан бир нафар тоифа бўлсайди. Улар динни чуқур англаб, қайтиб келган вақтларида қавмларини огоҳлантирардилар. Шоядки, улар ҳазир бўлсалар.",206,11],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] قَ[n[ـٰ]تِلُو[s[اْ] [h:5539[ٱ]لَّذِينَ يَلُونَك[w:5911[ُم م]ِّنَ [h:5912[ٱ]لْكُفَّارِ وَلْيَجِدُو[s[اْ] فِيكُمْ غِلْظَ[a:5913[ةً‌ۚ و]َ[h:1043[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ مَعَ [h:1044[ٱ]لْمُتَّق[p[ِي]نَ","Эй иймон келтирганлар, сизга яқин бўлган кофирларга қарши жанг қилинг. Улар сиздаги шиддатни кўрсинлар. Ва билингки, албатта, Аллоҳ тақводорлар билан биргадир.",207,11],["وَإِذَا م[o[َآ] أُ[f:5767[نز]ِلَتْ سُورَ[f:5914[ةٌ ف]َمِنْه[w:1456[ُم م]ّ[a:31[َن ي]َقُولُ أَيُّكُمْ زَادَتْهُ هَ[n[ـٰ]ذِه[o[ِۦٓ] إِيمَ[n[ـٰ][f:5915[نًا‌ۚ ف]َأَ[g[مّ]َا [h:136[ٱ]لَّذِينَ ءَامَنُو[s[اْ] فَزَادَتْهُمْ إِيمَ[n[ـٰ][a:5916[نًا و]َهُمْ يَسْتَ[q:2415[بْ]شِر[p[ُو]نَ","Бирон сура нозил қилинган вақтда улардан: «Бу сиздан кимнинг иймонини зиёда қилди?» дейдиган кимсалар бор. Бас, иймон келтирганларнинг иймонини зиёда қилди ва улар шоду хуррам бўлдилар.",207,11],["وَأَ[g[مّ]َا [h:138[ٱ]لَّذِينَ فِى قُلُوبِه[w:39[ِم م]َّرَ[f:5917[ضٌ ف]َزَادَتْهُمْ رِ[q:5918[جْ]سًا إِلَىٰ رِ[q:5919[جْ]سِهِمْ وَمَاتُو[s[اْ] وَهُمْ كَ[n[ـٰ]فِر[p[ُو]نَ","Аммо қалбларида касали борларнинг ифлосликлари устига ифлослик зиёда қилди ва улар кофир ҳолларида ўларлар.",207,11],["أَوَلَا يَرَوْنَ أَ[g[نّ]َهُمْ يُفْتَنُونَ فِى كُلِّ عَا[a:5920[مٍ م]َّرَّةً أَوْ مَرَّتَيْنِ ثُ[g[مّ]َ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّر[p[ُو]نَ","Улар ҳар йили бир ёки икки марта фитна қилаётганларига қарамайдиларми? Шунда ҳам на тавба қилмаслар ва на эсламаслар.",207,11],["وَإِذَا م[o[َآ] أُ[f:5767[نز]ِلَتْ سُورَ[a:5921[ةٌ ن]َّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَ[n[ٮٰ]ك[w:5922[ُم م]ِّنْ أَحَ[f:5923[دٍ ث]ُ[g[مّ]َ [h:5924[ٱ][f:5925[نص]َرَفُو[s[اْ‌ۚ] صَرَفَ [h:5926[ٱ]للَّهُ قُلُوبَه[c:5927[ُم ب]ِأَ[g[نّ]َهُمْ قَوْ[u:3651[مٌ ل]َّا يَفْقَه[p[ُو]نَ","Бирон сура нозил бўлган вақтда сизни биров кўрмадими, деб бир-бирларига назар соладилар-да, сўнгра бурилиб кетадилар. Улар фаҳмламайдиган қавм бўлганлари учун Аллоҳ қалбларини буриб қўйди.",207,11],["لَقَ[q:2389[دْ] ج[o[َا]ٓءَكُمْ رَسُو[a:521[لٌ م]ِّنْ أَ[f:1329[نف]ُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْك[c:5928[ُم ب]ِ[h:3560[ٱ]لْمُؤْمِنِينَ رَءُو[u:5881[فٌ ر]َّح[p[ِي]مٌ","Батаҳқиқ, сизларга ўзингиздан бўлган, сизнинг машаққат чекишингиз унинг учун оғир бўлган, сизнинг ташна, мўминларга марҳаматли, меҳрибон бўлган Пайғамбар келди.",207,11],["فَإِ[f:1857[ن ت]َوَلَّوْ[s[اْ] فَقُلْ حَسْبِىَ [h:5929[ٱ]للَّهُ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۖ عَلَيْهِ تَوَكَّلْتُ‌ۖ وَهُوَ رَبُّ [h:5930[ٱ]لْعَرْشِ [h:5931[ٱ]لْعَظ[p[ِي]مِ","Бас, юз ўгириб кетсалар, сен: «Менга Аллоҳнинг Ўзи етарли. Ундан ўзга ибодатга сазовор зот йўқ, Унга таваккал қилдим, У улуғ аршнинг Роббисидир», дегин.",207,11]]},{"n":10,"ar":"يُونُسَ","en":"Yunus","uz":"Юнус","type":"Макка","ayahs":[["ا[m[لٓ]ر‌ۚ تِلْكَ ءَايَ[n[ـٰ]تُ [h:5932[ٱ]لْكِتَ[n[ـٰ]بِ [h:5933[ٱ]لْحَك[p[ِي]مِ","Алиф. Лом. Ро. Булар ҳикматли китобнинг оятларидир.",208,11],["أَكَانَ لِل[g[نّ]َاسِ عَجَبًا أَنْ أَوْحَيْن[o[َآ] إِلَىٰ رَجُ[a:5934[لٍ م]ِّنْهُمْ أَنْ أَ[f:5935[نذ]ِرِ [h:5936[ٱ][l[ل][g[نّ]َاسَ وَبَشِّرِ [h:117[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَ[g[نّ]َ لَهُمْ قَدَمَ صِ[q:5937[دْ]قٍ عِ[f:264[ند]َ رَبِّهِمْ‌ۗ قَالَ [h:5938[ٱ]لْكَ[n[ـٰ]فِرُونَ إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَسَ[n[ـٰ]حِ[a:5939[رٌ م]ُّب[p[ِي]نٌ","Одамларга ўзларидан бўлган бир кишига ваҳий юбориб: «Одамларни огоҳлантир ва иймон келтирганларга Роббилари ҳузурида улар учун собитқадамлик борлигининг башоратини бер», деганимиз ажабланарли бўлдими? Кофирлар: «Албатта, бу очиқ-ойдин сеҳргардир», дедилар.",208,11],["إِ[g[نّ]َ رَبَّكُمُ [h:4737[ٱ]للَّهُ [h:4738[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ فِى سِتَّةِ أَيَّا[f:4739[مٍ ث]ُ[g[مّ]َ [h:156[ٱ]سْتَوَىٰ عَلَى [h:4740[ٱ]لْعَرْشِ‌ۖ يُدَبِّرُ [h:5940[ٱ]لْأَمْرَ‌ۖ مَا مِ[f:5941[ن ش]َفِيعٍ إِلَّا م[i:146[ِنۢ ب]َعْدِ إِذْنِه[n[ِۦ]‌ۚ ذ[n[َٲ]لِكُمُ [h:4260[ٱ]للَّهُ رَبُّكُمْ فَ[h:1946[ٱ]عْبُدُوهُ‌ۚ أَفَلَا تَذَكَّر[p[ُو]نَ","Албатта, Роббингиз осмонлару ерни олти кунда яратган, сўнг аршни эгаллаган Аллоҳдир. У ишнинг тадбирини қиладир. Унинг изнисиз ҳеч бир шафоатчи бўлмас. Ана ўша Аллоҳ Роббингиздир. Бас, Унга ибодат қилинглар. Эсламайсизларми?!",208,11],["إِلَيْهِ مَرْجِعُكُمْ جَمِي[a:5942[عًا‌ۖ و]َعْدَ [h:3149[ٱ]للَّهِ حَقًّا‌ۚ إِ[g[نّ]َهُ[n[ۥ] يَ[q:5943[بْ]دَؤُ[s[اْ] [h:5944[ٱ]لْخَلْقَ ثُ[g[مّ]َ يُعِيدُهُ[n[ۥ] لِيَ[q:5945[جْ]زِىَ [h:5946[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ بِ[h:1800[ٱ]لْقِسْطِ‌ۚ وَ[h:37[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَهُمْ شَرَا[a:4169[بٌ م]ِّنْ حَمِي[a:4170[مٍ و]َعَذَابٌ أَلِي[i:43[مُۢ ب]ِمَا كَانُو[s[اْ] يَكْفُر[p[ُو]نَ","Барчангизнинг қайтишингиз Унгадир. Аллоҳнинг ваъдаси ҳақдир. Албатта, У аввал бошда Ўзи яратади. Сўнгра иймон келтирган ва яхши амал қилганларни адолат-ла мукофотлаш учун уларни қайтарур. Кофир бўлганлар эса, куфр келтирганлари учун уларга қайноқ сувдан шароб ва аламли азоб бордир.",208,11],["هُوَ [h:153[ٱ]لَّذِى جَعَلَ [h:5947[ٱ][l[ل]شَّمْسَ ضِي[o[َا]ٓ[a:5948[ءً و]َ[h:4265[ٱ]لْقَمَرَ نُو[a:5949[رًا و]َقَدَّرَهُ[n[ۥ] مَنَازِلَ لِتَعْلَمُو[s[اْ] عَدَدَ [h:5950[ٱ][l[ل]سِّنِينَ وَ[h:5951[ٱ]لْحِسَابَ‌ۚ مَا خَلَقَ [h:1272[ٱ]للَّهُ ذ[n[َٲ]لِكَ إِلَّا بِ[h:370[ٱ]لْحَقِّ‌ۚ يُفَصِّلُ [h:5952[ٱ]لْأَيَ[n[ـٰ]تِ لِقَوْ[a:1292[مٍ ي]َعْلَم[p[ُو]نَ","У қуёшни зиё ва ойни нур қилган ҳамда сизлар йилларнинг ададини ва ҳисобини билишингиз учун унинг манзилларини ўлчовли қилган зотдир. Аллоҳ ўшани фақат ҳақ ила яратди. У биладиган қавмлар учун оятларини батафсил баён қилади.",208,11],["إِ[g[نّ]َ فِى [h:5953[ٱ]خْتِلَ[n[ـٰ]فِ [h:5954[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ وَمَا خَلَقَ [h:1272[ٱ]للَّهُ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:5955[مٍ ي]َتَّق[p[ُو]نَ","Албатта, кеча ва кундузнинг алмашиб туришида ва Аллоҳ осмонлару ерда яратган нарсаларда тақво қиладиган қавмлар учун оят-белгилар бордир.",208,11],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ لَا يَرْجُونَ لِق[o[َا]ٓءَنَا وَرَضُو[s[اْ] بِ[h:5581[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:5582[ٱ][l[ل]دُّنْيَا وَ[h:5956[ٱ][q:5956[طْ]مَأَ[g[نّ]ُو[s[اْ] بِهَا وَ[h:37[ٱ]لَّذِينَ هُمْ عَنْ ءَايَ[n[ـٰ]تِنَا غَ[n[ـٰ]فِل[p[ُو]نَ","Албатта, Биз ила мулоқот бўлишини умид қилмаганлар ва бу дунё ҳаётидан рози бўлиб, у билан хотиржам қолганлар ҳамда оятларимиздан ғофил бўлганлар.",209,11],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مَأْوَ[n[ٮٰ]هُمُ [h:5957[ٱ][l[ل][g[نّ]َارُ بِمَا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Ана ўшаларнинг жойлари, қилган касблари туфайли, жаҳаннамдир.",209,11],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ يَهْدِيهِمْ رَبُّه[c:5958[ُم ب]ِإِيمَ[n[ـٰ]نِهِمْ‌ۖ تَ[q:120[جْ]رِى مِ[f:4696[ن ت]َحْتِهِمُ [h:4697[ٱ]لْأَنْهَ[n[ـٰ]رُ فِى جَ[g[نّ]َ[n[ـٰ]تِ [h:3680[ٱ][l[ل][g[نّ]َع[p[ِي]مِ","Албатта, иймон келтирганлар ва яхши амаллар қилганларни Роббилари иймонлари сабабли ҳидоятга бошлайдир. Наим жаннатларида остларидан анҳорлар оқиб турадир.",209,11],["دَعْوَ[n[ٮٰ]هُمْ فِيهَا سُ[q:168[بْ]حَ[n[ـٰ]نَكَ [h:5959[ٱ][l[ل]لَّهُ[g[مّ]َ وَتَحِيَّتُهُمْ فِيهَا سَلَ[n[ـٰ][a:5960[مٌ‌ۚ و]َءَاخِرُ دَعْوَ[n[ٮٰ]هُمْ أَنِ [h:5961[ٱ]لْحَمْدُ لِلَّهِ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","У ердаги дуолари: «Эй бор Худоё, сени поклаб ёд этамиз»дир. У ерда саломлашишлари «ас-Салом»дир. Охирги дуолари эса: «Оламларнинг Робби Аллоҳга ҳамд бўлсин»дир.",209,11],["۞ وَلَوْ يُعَجِّلُ [h:5962[ٱ]للَّهُ لِل[g[نّ]َاسِ [h:5963[ٱ][l[ل]شَّرَّ [h:5964[ٱ]سْتِعْجَالَه[c:5965[ُم ب]ِ[h:5966[ٱ]لْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ‌ۖ فَنَذَرُ [h:5967[ٱ]لَّذِينَ لَا يَرْجُونَ لِق[o[َا]ٓءَنَا فِى طُغْيَ[n[ـٰ]نِهِمْ يَعْمَه[p[ُو]نَ","Агар Аллоҳ одамларга яхшиликни тез келтиргани каби ёмонликни ҳам тезлатса эди, ажаллари битган бўлур эди. Бас, Биз ила мулоқотда бўлишдан умиди йўқларни туғёнларида ташлаб қўямиз, адашиб-улоқиб юраверадилар.",209,11],["وَإِذَا مَسَّ [h:5968[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ [h:5970[ٱ][l[ل]ضُّرُّ دَعَانَا لِجَ[i:5971[نۢب]ِه[o[ِۦٓ] أَوْ قَاعِدًا أَوْ ق[o[َا]ٓئِ[f:5972[مًا ف]َلَ[g[مّ]َا كَشَفْنَا عَنْهُ ضُرَّهُ[n[ۥ] مَرَّ كَأ[u:2914[َن ل]َّمْ يَ[q:5973[دْ]عُن[o[َآ] إِلَىٰ ضُ[a:5974[رٍّ م]َّسَّهُ[n[ۥ]‌ۚ كَذ[n[َٲ]لِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Қачонки инсонга зарар етса, Бизга ёнбошлаган, ўтирган ёки турган ҳолида дуо қиладир. Ундан зарарини кетказсак, худди ўзига етган зарар ҳақида Бизга дуо қилмагандек кетаверади. Ана шундай қилиб, исрофчиларга қилаётган амаллари зийнатланиб кўрсатилди.",209,11],["وَلَقَ[q:341[دْ] أَهْلَكْنَا [h:5975[ٱ]لْقُرُونَ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ لَ[g[مّ]َا ظَلَمُو[s[اْ‌ۙ] وَج[o[َا]ٓءَتْهُمْ رُسُلُه[c:4900[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ وَمَا كَانُو[s[اْ] لِيُؤْمِنُو[s[اْ‌ۚ] كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:5976[ٱ]لْقَوْمَ [h:5977[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","Батаҳқиқ, сиздан олдинги асрларни зулм қилган чоғларида ва Пайғамбарлари очиқ-ойдин ҳужжатлар билан келганларида иймон келтирмайдиган бўлганларида ҳалок қилганмиз. Жиноятчи қавмларни ана шундай жазолаймиз.",209,11],["ثُ[g[مّ]َ جَعَلْنَ[n[ـٰ]كُمْ خَلَ[o[ـٰٓ]ئِفَ فِى [h:44[ٱ]لْأَرْضِ م[i:1453[ِنۢ ب]َعْدِهِمْ لِنَ[f:5978[نظ]ُرَ كَيْفَ تَعْمَل[p[ُو]نَ","Сўнгра қандай амал қилишингизга назар солишимиз учун уларнинг ортидан сизларни ер юзида ўринбосарлар қилдик.",209,11],["وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَ[n[ـٰ][f:5979[تٍ‌ۙ ق]َالَ [h:590[ٱ]لَّذِينَ لَا يَرْجُونَ لِق[o[َا]ٓءَنَا [h:5980[ٱ]ئْتِ بِقُرْءَانٍ غَيْرِ هَ[n[ـٰ]ذ[o[َآ] أَوْ بَدِّلْهُ‌ۚ قُلْ مَا يَكُونُ ل[o[ِىٓ] أَنْ أُبَدِّلَهُ[n[ۥ] مِ[f:5981[ن ت]ِلْقَآىِٕ نَفْس[o[ِىٓ‌ۖ] إِنْ أَتَّبِعُ إِلَّا مَا يُوحَ[o[ىٰٓ] إِلَىَّ‌ۖ إِ[g[نّ][o[ِىٓ] أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظ[p[ِي]مٍ","Қачонки, уларга очиқ-ойдин оятларимиз тиловат қилинганида, Бизга мулоқот бўлишдан умиди йўқлар: «Бундан бошқа Қуръон келтир ёки уни алмаштир», дедилар. Сен: «Мен ўзимча уни алмаштира олмайман. Мен фақат ўзимга ваҳий қилинган нарсага эргашаман, холос. Албатта, мен Роббимга осийлик қилсам, улуғ куннинг азобидан қўрқаман», деб айт.",210,11],["قُل لَّوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ مَا تَلَوْتُهُ[n[ۥ] عَلَيْكُمْ وَل[o[َآ] أَ[q:5982[دْ]رَ[n[ٮٰ]ك[c:5983[ُم ب]ِه[n[ِۦ]‌ۖ فَقَ[q:563[دْ] لَبِثْتُ فِيكُمْ عُمُ[a:5984[رًا م]ِّ[f:1097[ن ق]َ[q:1098[بْ]لِه[o[ِۦٓ‌ۚ] أَفَلَا تَعْقِل[p[ُو]نَ","Сен: «Агар Аллоҳ хоҳлаганида, уни сизларга тиловат қилмас эдим ва У зот ҳам уни сизларга ўргатмас эди. Батаҳқиқ, мен орангизда ундан олдин ҳам умр кечирдим. Ақл ишлатиб кўрмайсизларми?» деб айт.",210,11],["فَمَنْ أَظْلَمُ مِ[g[مّ]َنِ [h:3980[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔـايَ[n[ـٰ]تِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] لَا يُفْلِحُ [h:5985[ٱ]لْمُ[q:5255[جْ]رِم[p[ُو]نَ","Аллоҳга ёлғон тўқиган ёки Унинг оятларини ёлғонга чиқарган кимсадан ҳам золимроқ одам борми?! Албатта, жиноятчилар нажот топмаслар.",210,11],["وَيَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَ[f:534[نف]َعُهُمْ وَيَقُولُونَ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ شُفَعَ[o[ـٰٓ]ؤُنَا عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۚ قُلْ أَتُنَبِّــُٔونَ [h:5986[ٱ]للَّهَ بِمَا لَا يَعْلَمُ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَلَا فِى [h:44[ٱ]لْأَرْضِ‌ۚ سُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ] وَتَعَ[n[ـٰ]لَىٰ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","Улар Аллоҳни қўйиб, ўзларига зарар ҳам, манфаат ҳам етказа олмайдиган нарсаларга ибодат қиларлар ва: «Ана ўшалар бизнинг Аллоҳ ҳузуридаги шафоатчиларимиздир!» дерлар. Сен: «Аллоҳга у осмонлару ерда билмайдиган нарсаларнинг хабарини бермоқчимисизлар?!» деб айт. Аллоҳ улар келтираётган ширкдан пок ва юксак зотдир.",210,11],["وَمَا كَانَ [h:1158[ٱ][l[ل][g[نّ]َاسُ إِلّ[o[َآ] أُ[g[مّ]َ[a:1159[ةً و][n[َٲ]حِدَ[f:5987[ةً ف]َ[h:5988[ٱ]خْتَلَفُو[s[اْ‌ۚ] وَلَوْلَا كَلِمَ[f:5989[ةٌ س]َبَقَتْ م[u:770[ِن ر]َّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِف[p[ُو]نَ","Одамлар фақат бир уммат бўлган эдилар. Сўнгра ихтилофга тушдилар. Агар Роббинг томонидан айтилган сўз бўлмаганида, улар ихтилоф қилаётган нарса ҳақида ораларида ҳукм қилинган бўлар эди.",210,11],["وَيَقُولُونَ لَوْل[o[َآ] أُ[f:17[نز]ِلَ عَلَيْهِ ءَايَ[a:4024[ةٌ م]ّ[u:192[ِن ر]َّبِّه[n[ِۦ]‌ۖ فَقُلْ إِ[g[نّ]َمَا [h:5990[ٱ]لْغَيْبُ لِلَّهِ فَ[h:4800[ٱ][f:4800[نت]َظِر[o[ُوٓ][s[اْ] إِ[g[نّ]ِى مَعَك[w:2068[ُم م]ِّنَ [h:4801[ٱ]لْمُ[f:4802[نت]َظِر[p[ِي]نَ","Ва улар: «Унга Роббидан оят-мўъжиза тушса эди», дерлар. Бас, сен: «Ғайб Аллоҳникидир. Интизор бўлиб туринг, мен ҳам сиз ила интизор бўлувчиларданман», деб айт.",210,11],["وَإِذ[o[َآ] أَذَ[q:5991[قْ]نَا [h:5992[ٱ][l[ل][g[نّ]َاسَ رَحْمَ[a:5993[ةً م]ّ[i:146[ِنۢ ب]َعْدِ ضَرّ[o[َا]ٓءَ مَسَّتْهُمْ إِذَا لَه[w:5994[ُم م]َّكْ[f:5995[رٌ ف][o[ِىٓ] ءَايَاتِنَا‌ۚ قُلِ [h:3166[ٱ]للَّهُ أَسْرَعُ مَكْرًا‌ۚ إِ[g[نّ]َ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُر[p[ُو]نَ","Қачонки одамларга уларга етган зарардан сўнг раҳматни тотдирсак, баногоҳ, уларда оятларимиз ҳақида макр бўлур. Сен: «Аллоҳ макрда тезкордир. Албатта, элчиларимиз қилаётган макрларингизни ёзиб борурлар», деб айт.",211,11],["هُوَ [h:153[ٱ]لَّذِى يُسَيِّرُكُمْ فِى [h:4106[ٱ]لْبَرِّ وَ[h:4107[ٱ]لْبَحْرِ‌ۖ حَتَّ[o[ىٰٓ] إِذَا كُ[f:100[نت]ُمْ فِى [h:4780[ٱ]لْفُلْكِ وَجَرَيْنَ بِه[c:5996[ِم ب]ِرِي[f:5997[حٍ ط]َيِّبَ[a:5998[ةٍ و]َفَرِحُو[s[اْ] بِهَا ج[o[َا]ٓءَتْهَا رِيحٌ عَاصِ[a:5999[فٌ و]َج[o[َا]ٓءَهُمُ [h:6000[ٱ]لْمَوْجُ مِ[f:843[ن ك]ُلِّ مَكَا[a:6001[نٍ و]َظَ[g[نّ][o[ُوٓ][s[اْ] أَ[g[نّ]َهُمْ أُحِيطَ بِهِمْ‌ۙ دَعَوُ[s[اْ] [h:6002[ٱ]للَّهَ مُخْلِصِينَ لَهُ [h:4649[ٱ][l[ل]دِّينَ لَئِنْ أَ[f:6003[نج]َيْتَنَا مِنْ هَ[n[ـٰ]ذِه[n[ِۦ] لَنَكُونَ[g[نّ]َ مِنَ [h:4134[ٱ][l[ل]شَّ[n[ـٰ]كِر[p[ِي]نَ","У сизларни қуруқликда ва денгизда юргизадиган зотдир. Токи сизлар кемада бўлганингизда ва у яхши еллар ила уларни олиб кетганида ҳамда улар бундан хурсанд бўлганларида, қаттиқ шамол келур ва уларга ҳар томондан тўлқин келур. Ўзларининг қуршовда қолганларини англаганларида Аллоҳга чин ихлос билан: «Агар бизни мана шундан қутқазсанг, албатта, шукр келтирувчилардан бўламиз», деб дуо қилурлар.",211,11],["فَلَ[g[مّ][o[َآ] أَ[f:6004[نج]َ[n[ـٰ]هُمْ إِذَا هُمْ يَ[q:2073[بْ]غُونَ فِى [h:44[ٱ]لْأَرْضِ بِغَيْرِ [h:325[ٱ]لْحَقِّ‌ۗ يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ إِ[g[نّ]َمَا بَغْيُكُمْ عَلَ[o[ىٰٓ] أَ[f:1329[نف]ُسِك[w:6005[ُم‌ۖ م]َّتَ[n[ـٰ]عَ [h:6006[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۖ ثُ[g[مّ]َ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُك[c:6007[ُم ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Бас, қачонки У зот уларга нажот берса, кўрибсизки, улар ер юзида ноҳақдан зулм қилурлар. Эй одамлар! Бу зулмингиз фақат ўз зиёнингизгадир. Бу ҳаёти дунё матоҳи, холос. Сўнгра Бизга қайтишингиз бор. Бас, Биз нима амал қилганингизнинг хабарини берурмиз.",211,11],["إِ[g[نّ]َمَا مَثَلُ [h:6008[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا كَم[o[َا]ٓءٍ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ فَ[h:6009[ٱ]خْتَلَطَ بِه[n[ِۦ] نَبَاتُ [h:6010[ٱ]لْأَرْضِ مِ[g[مّ]َا يَأْكُلُ [h:6011[ٱ][l[ل][g[نّ]َاسُ وَ[h:6012[ٱ]لْأَنْعَ[n[ـٰ]مُ حَتَّ[o[ىٰٓ] إِذ[o[َآ] أَخَذَتِ [h:6013[ٱ]لْأَرْضُ زُخْرُفَهَا وَ[h:6014[ٱ]زَّيَّنَتْ وَظَ[g[نّ]َ أَهْلُه[o[َآ] أَ[g[نّ]َهُمْ قَ[n[ـٰ]دِرُونَ عَلَيْه[o[َآ] أَتَ[n[ـٰ]ه[o[َآ] أَمْرُنَا لَيْلاً أَوْ نَهَا[f:6015[رًا ف]َجَعَلْنَ[n[ـٰ]هَا حَصِي[f:6016[دًا ك]َأ[u:2914[َن ل]َّمْ تَغْنَ بِ[h:6017[ٱ]لْأَمْسِ‌ۚ كَذ[n[َٲ]لِكَ نُفَصِّلُ [h:4091[ٱ]لْأَيَ[n[ـٰ]تِ لِقَوْ[a:6018[مٍ ي]َتَفَكَّر[p[ُو]نَ","Албатта, дунё ҳаётининг мисоли худди Биз осмондан туширган сувга ўхшайдир. Бас, одамлар ва чорвалар ейдиган ер набототи у билан аралашиб, ер безагини олганда ва зийнатлаганда ҳамда унинг аҳли, энди бунга эришдик, деб ўйлаганда, кечаси ёки кундузи унга Бизнинг амримиз келадир. Биз уни худди куни кеча яшнаб турмагандек қуритиб қўямиз. Тафаккур қиладиган қавмлар учун оятларимизни ана шундай батафсил баён қилурмиз.",211,11],["وَ[h:9999[ٱ]للَّهُ يَ[q:1242[دْ]ع[o[ُوٓ][s[اْ] إِلَىٰ دَارِ [h:6019[ٱ][l[ل]سَّلَ[n[ـٰ]مِ وَيَهْدِى م[a:476[َن ي]َش[o[َا]ٓءُ إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Аллоҳ тинчлик диёрига даъват қиладир ва Ўзи хоҳлаганларни сироти мустақимга ҳидоят қиладир.",211,11],["۞ لِّلَّذِينَ أَحْسَنُو[s[اْ] [h:6020[ٱ]لْحُسْنَىٰ وَزِيَادَ[a:6021[ةٌ‌ۖ و]َلَا يَرْهَقُ وُجُوهَهُمْ قَتَ[a:6022[رٌ و]َلَا ذِلَّةٌ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:415[ٱ]لْجَ[g[نّ]َةِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Гўзал амал қилганлар учун гўзал савоб ва зиёдалик бордир. Уларнинг юзларини қаролик ҳам, хорлик ҳам қопламас. Ана ўшалар жаннат эгаларидир. Улар унда абадий қолурлар.",212,11],["وَ[h:9999[ٱ]لَّذِينَ كَسَبُو[s[اْ] [h:6023[ٱ][l[ل]سَّيِّـَٔـاتِ جَز[o[َا]ٓءُ سَيِّئَ[i:6024[ةِۭ ب]ِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّ[a:6025[ةٌ‌ۖ م]َّا لَه[w:6026[ُم م]ِّنَ [h:321[ٱ]للَّهِ مِنْ عَاصِ[f:6027[مٍ‌ۖ ك]َأَ[g[نّ]َم[o[َآ] أُغْشِيَتْ وُجُوهُهُمْ قِطَ[a:6028[عًا م]ِّنَ [h:6029[ٱ]لَّيْلِ مُظْلِمًا‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Ёмонликларни касб қилганларга эса ёмонликларига яраша ёмон жазо бўлур. Уларни хорлик қоплайдир. Улар учун Аллоҳдан бирор сақловчи ҳам бўлмас. Юзлари худди тун зулматидан бир парча ила қопланган каби бўлур. Ана ўшалар дўзах эгаларидир. Улар унда абадий қолурлар. Олдинги манзаранинг тамоман акси. Оятда бу дунёда гўзал амаллар эмас, ёмон амаллар қилганлар васф қилинаётир. Ёмонликлари туфайли улар бу дунёнинг ўзида ёмон ҳаёт кечирадилар. Охиратда эса, уларга: «»ёмонликларига яраша ёмон жазо бўлур».",212,11],["وَيَوْمَ نَحْشُرُهُمْ جَمِي[f:155[عًا ث]ُ[g[مّ]َ نَقُولُ لِلَّذِينَ أَشْرَكُو[s[اْ] مَكَانَكُمْ أَ[f:428[نت]ُمْ وَشُرَك[o[َا]ٓؤُكُمْ‌ۚ فَزَيَّلْنَا بَيْنَهُمْ‌ۖ وَقَالَ شُرَك[o[َا]ٓؤُه[w:6030[ُم م]َّا كُ[f:100[نت]ُمْ إِيَّانَا تَعْبُد[p[ُو]نَ","У кунда барчаларини тўплаймиз. Сўнгра ширк келтирганларга: «Сизлар ҳам, шерик қилганларингиз ҳам жойингиздан қимирламангиз», деймиз. Бас, ораларини ажратамиз ва шерик қилинмишлар: «Бизга ибодат этмаган эдингиз.",212,11],["فَكَفَىٰ بِ[h:32[ٱ]للَّهِ شَهِيد[i:6031[َۢا ب]َيْنَنَا وَبَيْنَكُمْ إِ[f:4919[ن ك]ُ[g[نّ]َا عَنْ عِبَادَتِكُمْ لَغَ[n[ـٰ]فِل[p[ِي]نَ","Биз билан сизнинг орангизда шоҳидликка Аллоҳ кифоядир. Биз, албатта, сизнинг ибодатингиздан ғофил эдик», дерлар.",212,11],["هُنَالِكَ تَ[q:6032[بْ]لُو[s[اْ] كُلُّ نَفْ[a:1654[سٍ م]ّ[o[َآ] أَسْلَفَتْ‌ۚ وَرُدّ[o[ُوٓ][s[اْ] إِلَى [h:1637[ٱ]للَّهِ مَوْلَ[n[ـٰ]هُمُ [h:4123[ٱ]لْحَقِّ‌ۖ وَضَلَّ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَفْتَر[p[ُو]نَ","Ўша ерда ҳар бир жон ўзи қилиб ўтган ишдан сўралур-хабардор бўлур ва ҳақиқий хожалари Аллоҳга қайтарилурлар. Ҳамда ўзларича тўқиб чиқарган нарсалари улардан ғойиб бўладир.",212,11],["قُلْ م[a:6033[َن ي]َرْزُقُك[w:6034[ُم م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِ أَ[g[مّ][a:6035[َن ي]َمْلِكُ [h:6036[ٱ][l[ل]سَّمْعَ وَ[h:6037[ٱ]لْأَ[q:6037[بْ]صَ[n[ـٰ]رَ وَم[a:6038[َن ي]ُخْرِجُ [h:4258[ٱ]لْحَىَّ مِنَ [h:1833[ٱ]لْمَيِّتِ وَيُخْرِجُ [h:6039[ٱ]لْمَيِّتَ مِنَ [h:1835[ٱ]لْحَىِّ وَم[a:6040[َن ي]ُدَبِّرُ [h:5940[ٱ]لْأَمْرَ‌ۚ فَسَيَقُولُونَ [h:6041[ٱ]للَّهُ‌ۚ فَقُلْ أَفَلَا تَتَّق[p[ُو]نَ","Сен: «Сизларни осмонлару ерда ким ризқлантирур? Ёки қулоқ ва кўзларингизнинг эгаси ким, тирикни ўликдан, ўликни тирикдан ким чиқарур? Ишнинг тадбирини ким қиладир?» деб айт. Улар, албатта: «Аллоҳ», дерлар. Бас, сен: «Тақво қилмайсизларми?» деб айт.",212,11],["فَذ[n[َٲ]لِكُمُ [h:6042[ٱ]للَّهُ رَبُّكُمُ [h:6043[ٱ]لْحَقُّ‌ۖ فَمَاذَا بَعْدَ [h:6044[ٱ]لْحَقِّ إِلَّا [h:6045[ٱ][l[ل]ضَّلَ[n[ـٰ]لُ‌ۖ فَأَ[g[نّ]َىٰ تُصْرَف[p[ُو]نَ","Бас, мана шу Аллоҳ сизнинг ҳақ Роббингиздир. Ҳақдан сўнг нима бўладир? Магар залолат бўладир. Бас, қаёққа бурилиб кетмоқдасиз?",212,11],["كَذ[n[َٲ]لِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى [h:289[ٱ]لَّذِينَ فَسَق[o[ُوٓ][s[اْ] أَ[g[نّ]َهُمْ لَا يُؤْمِن[p[ُو]نَ","Шундай қилиб, фосиқлик қилганларга Роббингнинг сўзи ҳақ бўлди. Улар иймон келтирмаслар.",212,11],["قُلْ هَلْ مِ[f:6046[ن ش]ُرَك[o[َا]ٓئِك[w:6047[ُم م]ّ[a:6048[َن ي]َ[q:5943[بْ]دَؤُ[s[اْ] [h:5944[ٱ]لْخَلْقَ ثُ[g[مّ]َ يُعِيدُهُ[n[ۥ]‌ۚ قُلِ [h:3166[ٱ]للَّهُ يَ[q:5943[بْ]دَؤُ[s[اْ] [h:5944[ٱ]لْخَلْقَ ثُ[g[مّ]َ يُعِيدُهُ[n[ۥ]‌ۖ فَأَ[g[نّ]َىٰ تُؤْفَك[p[ُو]نَ","Сен: «Сизнинг шерик келтираётганларингиз орасида махлуқотни аввал-бошда яратиб, сўнгра уни қайтарадигани борми?» деб айт. Сен: «Аллоҳ махлуқотни аввал-бошда яратиб, сўнгра уни қайтарадир. Бас, қаёққа бурилиб кетмоқдасизлар?» деб айт.",213,11],["قُلْ هَلْ مِ[f:6046[ن ش]ُرَك[o[َا]ٓئِك[w:6047[ُم م]ّ[a:6049[َن ي]َهْد[o[ِىٓ] إِلَى [h:6050[ٱ]لْحَقِّ‌ۚ قُلِ [h:3166[ٱ]للَّهُ يَهْدِى لِلْحَقِّ‌ۗ أَفَم[a:6051[َن ي]َهْد[o[ِىٓ] إِلَى [h:6050[ٱ]لْحَقِّ أَحَقُّ أ[a:6052[َن ي]ُتَّبَعَ أَ[g[مّ][u:6053[َن ل]َّا يَهِدّ[o[ِىٓ] إِلّ[o[َآ] أ[a:6054[َن ي]ُهْدَىٰ‌ۖ فَمَا لَكُمْ كَيْفَ تَحْكُم[p[ُو]نَ","Сен: «Сизнинг шерик келтираётганларингиз орасида ҳаққа ҳидоят қиладигани борми?» деб айт. Сен: «Аллоҳ ҳаққа ҳидоят қилади. Эргашишга ҳаққа ҳидоят қиладиган зот ҳақлироқми ёки ҳидоят қилмайдиган, балки ўзи ҳидоятга муҳтож кимсами? Сизга нима бўлди?! Қандай ҳукм қилмоқдасиз?!» деб айт.",213,11],["وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَ[g[نّ]ًا‌ۚ إِ[g[نّ]َ [h:6055[ٱ][l[ل]ظَّ[g[نّ]َ لَا يُغْنِى مِنَ [h:1173[ٱ]لْحَقِّ شَيْــًٔا‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلِي[i:6056[مُۢ ب]ِمَا يَفْعَل[p[ُو]نَ","Уларнинг кўплари гумонга эргашадилар, холос. Албатта, гумон ҳақ ўрнида ҳеч нарса бўла олмас. Албатта, Аллоҳ нима қилаётганларини билгувчи зотдир.",213,11],["وَمَا كَانَ هَ[n[ـٰ]ذَا [h:3971[ٱ]لْقُرْءَانُ أ[a:6057[َن ي]ُفْتَرَىٰ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَلَ[n[ـٰ]كِ[f:6058[ن ت]َصْدِيقَ [h:6059[ٱ]لَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ [h:6060[ٱ]لْكِتَ[n[ـٰ]بِ لَا رَيْبَ فِيهِ م[u:4772[ِن ر]َّبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Ушбу Қуръон Аллоҳдан бошқа томонидан тўқиб чиқарилган эмас. Балки у ўзидан олдингининг тасдиғи ва китобнинг тафсилотидир. Унда ҳеч шубҳа йўқ. У оламларнинг Роббисидандир.",213,11],["أَمْ يَقُولُونَ [h:6061[ٱ]فْتَرَ[n[ٮٰ]هُ‌ۖ قُلْ فَأْتُو[s[اْ] بِسُورَ[a:6062[ةٍ م]ِّثْلِه[n[ِۦ] وَ[h:105[ٱ][q:105[دْ]عُو[s[اْ] مَنِ [h:6063[ٱ]سْتَطَعْت[w:5394[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Ёки ўзи тўқиб олган дейдиларми? Сен: «Агар ростгўй бўлсангиз, унга ўхшаш бир сура келтиринг ва Аллоҳдан бошқа кучингиз етганича кимни хоҳласангиз, чақиринг», деб айт.",213,11],["بَلْ كَذَّبُو[s[اْ] بِمَا لَمْ يُحِيطُو[s[اْ] بِعِلْمِه[n[ِۦ] وَلَ[g[مّ]َا يَأْتِهِمْ تَأْوِيلُهُ[n[ۥ]‌ۚ كَذ[n[َٲ]لِكَ كَذَّبَ [h:4507[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۖ فَ[h:1513[ٱ][f:1513[نظ]ُرْ كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6064[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Балки улар ўзлари илмини билмаган нарсани уларга унинг таъвили етмай туриб, ёлғонга чиқарурлар. Улардан олдингилар ҳам шундай ёлғонга чиқарган эдилар. Золимларнинг оқибати қандай бўлганига назар сол.",213,11],["وَمِنْه[w:1106[ُم م]ّ[a:5799[َن ي]ُؤْمِنُ بِه[n[ِۦ] وَمِنْه[w:1106[ُم م]ّ[u:6065[َن ل]َّا يُؤْمِنُ بِه[n[ِۦ]‌ۚ وَرَبُّكَ أَعْلَمُ بِ[h:1989[ٱ]لْمُفْسِد[p[ِي]نَ","Улардан унга иймон келтирадиганлар ҳам бор ва улардан унга иймон келтирмайдиганлар ҳам бор. Роббинг эса, бузғунчиларни яхши билгувчи зотдир.",213,11],["وَإِ[f:6066[ن ك]َذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ‌ۖ أَ[f:428[نت][c:6067[ُم ب]َرِ[o[يٓ]ــُٔونَ مِ[g[مّ][o[َآ] أَعْمَلُ وَأَنَا۟ بَر[o[ِى]ٓ[a:3977[ءٌ م]ِّ[g[مّ]َا تَعْمَل[p[ُو]نَ","Агар улар сени ёлғончи қилсалар, сен: «Менга ўз ишим, сизларга ўз ишингиз, сизлар мен қиладиган ишдан поксизлар, мен сизлар қиладиган ишдан покман», деб айт.",213,11],["وَمِنْه[w:1106[ُم م]ّ[a:6068[َن ي]َسْتَمِعُونَ إِلَيْكَ‌ۚ أَفَأَ[f:6069[نت]َ تُسْمِعُ [h:6070[ٱ][l[ل]صُّ[g[مّ]َ وَلَوْ كَانُو[s[اْ] لَا يَعْقِل[p[ُو]نَ","Ва улардан сенга қулоқ тутадиганлари ҳам бор. Агар ақл ишлатмасалар, карқулоқларга сен эшиттира олурмисан?!",213,11],["وَمِنْه[w:1106[ُم م]ّ[a:6071[َن ي]َ[f:2039[نظ]ُرُ إِلَيْكَ‌ۚ أَفَأَ[f:6069[نت]َ تَهْدِى [h:6072[ٱ]لْعُمْىَ وَلَوْ كَانُو[s[اْ] لَا يُ[q:60[بْ]صِر[p[ُو]نَ","Улардан сенга назар соладиганлари ҳам бор. Агар ўзлари кўрмасалар, кўрларни сен ҳидоят қила олурмисан?!",214,11],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَظْلِمُ [h:6073[ٱ][l[ل][g[نّ]َاسَ شَيْـ[a:6074[ـًٔا و]َلَ[n[ـٰ]كِ[g[نّ]َ [h:6075[ٱ][l[ل][g[نّ]َاسَ أَ[f:38[نف]ُسَهُمْ يَظْلِم[p[ُو]نَ","Албатта, Аллоҳ одамларга ҳеч зулм қилмас, лекин одамлар ўзларига зулм қилурлар.",214,11],["وَيَوْمَ يَحْشُرُهُمْ كَأ[u:2914[َن ل]َّمْ يَلْبَث[o[ُوٓ][s[اْ] إِلَّا سَاعَ[a:6076[ةً م]ِّنَ [h:6077[ٱ][l[ل][g[نّ]َهَارِ يَتَعَارَفُونَ بَيْنَهُمْ‌ۚ قَ[q:298[دْ] خَسِرَ [h:3997[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِلِق[o[َا]ٓءِ [h:3998[ٱ]للَّهِ وَمَا كَانُو[s[اْ] مُهْتَد[p[ِي]نَ","Уларни тўплайдиган кунда худди наҳордан бир соатгина турганга ўхшаб бир-бирлари билан танишурлар. Батаҳқиқ, Аллоҳнинг мулоқотини ёлғонга чиқарганлар ва ҳидоят топганлардан бўлмаганлар зиён қилурлар.",214,11],["وَإِ[g[مّ]َا نُرِيَ[g[نّ]َكَ بَعْضَ [h:1943[ٱ]لَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَ[g[نّ]َكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُ[g[مّ]َ [h:6078[ٱ]للَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَل[p[ُو]نَ","Ёки сенга уларга ваъда қилганимизнинг баъзисини кўрсатамиз, ёки сени вафот эттирамиз. Бас, уларнинг қайтишлари Бизгадир. Сўнгра нима қилаётганларига Аллоҳ шоҳиддир.",214,11],["وَلِكُلِّ أُ[g[مّ]َ[u:6079[ةٍ ر]َّسُو[f:6080[لٌ‌ۖ ف]َإِذَا ج[o[َا]ٓءَ رَسُولُهُمْ قُضِىَ بَيْنَه[c:3554[ُم ب]ِ[h:1800[ٱ]لْقِسْطِ وَهُمْ لَا يُظْلَم[p[ُو]نَ","Ҳар умматнинг ўз Пайғамбари бордир. Қачонки уларга Пайғамбарлари келса, ораларида адолат ила ҳукм чиқарилур. Уларга зулм қилинмас.",214,11],["وَيَقُولُونَ مَتَىٰ هَ[n[ـٰ]ذَا [h:6081[ٱ]لْوَعْدُ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Улар: «Агар ростгўйлардан бўлсангиз, бу ваъда қачон бўладир?» дерлар.",214,11],["قُل لّ[o[َآ] أَمْلِكُ لِنَفْسِى ضَر[a:3719[ًّا و]َلَا نَفْعًا إِلَّا مَا ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ‌ۗ لِكُلِّ أُ[g[مّ]َةٍ أَجَلٌ‌ۚ إِذَا ج[o[َا]ٓءَ أَجَلُهُمْ فَلَا يَسْتَــْٔخِرُونَ سَاعَ[a:4666[ةً‌ۖ و]َلَا يَسْتَ[q:4667[قْ]دِم[p[ُو]نَ","Сен: «Мен ўзим ҳам на зарарга ва на фойдага молик эмасман. Магар Аллоҳ нимани хоҳласа. Ҳар умматнинг ўз ажали бор. Ажаллари келган вақтда бир соатга орқага ҳам, олдинга ҳам сура олмаслар», деб айт.",214,11],["قُلْ أَرَءَيْتُمْ إِنْ أَتَ[n[ـٰ]كُمْ عَذَابُهُ[n[ۥ] بَيَ[n[ـٰ]تًا أَوْ نَهَا[a:6082[رًا م]َّاذَا يَسْتَعْجِلُ مِنْهُ [h:6083[ٱ]لْمُ[q:5255[جْ]رِم[p[ُو]نَ","Сен: «Хабар беринг-чи, агар Унинг азоби сизларга кечаси ёки кундузи келса, жиноятчилар унинг нимасига шошилмоқдалар?» деб айт.",214,11],["أَثُ[g[مّ]َ إِذَا مَا وَقَعَ ءَامَ[f:703[نت][c:704[ُم ب]ِه[o[ِۦٓ‌ۚ] ءَ[m[ا]ٓلْـَٔ[n[ـٰ]نَ وَقَ[q:387[دْ] كُ[f:100[نت][c:6084[ُم ب]ِه[n[ِۦ] تَسْتَعْجِل[p[ُو]نَ","У воқеъ бўлганидан сўнг унга ишондингизми? Энди-я?! Уни тезроқ келсин, деб шошилаётган эдингиз-ку?!",214,11],["ثُ[g[مّ]َ قِيلَ لِلَّذِينَ ظَلَمُو[s[اْ] ذُوقُو[s[اْ] عَذَابَ [h:6085[ٱ]لْخُلْدِ هَلْ تُ[q:4248[جْ]زَوْنَ إِلَّا بِمَا كُ[f:100[نت]ُمْ تَكْسِب[p[ُو]نَ","Зулм қилганларга: «Мангу азобни тортинглар. Фақат касб қилганингизга яраша жазо олурсизлар, холос», дейилур.",214,11],["۞ وَيَسْتَ[i:6086[نۢب]ِــُٔونَكَ أَحَقٌّ هُوَ‌ۖ قُلْ إِى وَرَبّ[o[ِىٓ] إِ[g[نّ]َهُ[n[ۥ] لَحَ[a:6087[قٌّ‌ۖ و]َم[o[َآ] أَ[f:428[نت][c:4435[ُم ب]ِمُعْجِز[p[ِي]نَ","Улар сендан: «У ҳақми?» деб сўрарлар. Сен: «Ҳа, Парвардигорим ҳаққи, албатта, у ҳақдир ва сизлар қочиб қутулувчи эмассизлар», деб айт.",214,11],["وَلَوْ أَ[g[نّ]َ لِكُلِّ نَفْ[f:6088[سٍ ظ]َلَمَتْ مَا فِى [h:44[ٱ]لْأَرْضِ لَ[h:6089[ٱ]فْتَدَتْ بِه[n[ِۦ]‌ۗ وَأَسَرُّو[s[اْ] [h:6090[ٱ][l[ل][g[نّ]َدَامَةَ لَ[g[مّ]َا رَأَوُ[s[اْ] [h:6091[ٱ]لْعَذَابَ‌ۖ وَقُضِىَ بَيْنَه[c:3554[ُم ب]ِ[h:1800[ٱ]لْقِسْطِ‌ۚ وَهُمْ لَا يُظْلَم[p[ُو]نَ","Агар ҳар бир зулм қилган жонга ер юзидаги ҳамма нарса берилсаю уни фидо қилса ҳам. Азобни кўрганларида ичларида надомат чексалар ҳам. Улар ўртасида адолат ила ҳукм чиқарилур. Уларга зулм қилинмас.",215,11],["أَل[o[َآ] إِ[g[نّ]َ لِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۗ أَل[o[َآ] إِ[g[نّ]َ وَعْدَ [h:3149[ٱ]للَّهِ حَ[a:6092[قٌّ و]َلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَعْلَم[p[ُو]نَ","Огоҳ бўлинг! Осмонлару ердаги нарсалар, албатта, Аллоҳникидир. Огоҳ бўлинг! Аллоҳнинг ваъдаси, албатта, ҳақдир. Лекин кўплари билмаслар.",215,11],["هُوَ يُحْى[n[ِۦ] وَيُمِيتُ وَإِلَيْهِ تُرْجَع[p[ُو]نَ","У тирилтирадир ва ўлдирадир ва Унгагина қайтарилурсизлар.",215,11],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ قَ[q:298[دْ] ج[o[َا]ٓءَتْك[w:6093[ُم م]َّوْعِظَ[a:1635[ةٌ م]ّ[u:243[ِن ر]َّبِّكُمْ وَشِف[o[َا]ٓ[u:6094[ءٌ ل]ِّمَا فِى [h:6095[ٱ][l[ل]صُّدُورِ وَهُ[a:4547[دًى و]َرَحْمَ[u:6096[ةٌ ل]ِّلْمُؤْمِن[p[ِي]نَ","Эй одамлар! Сизга ўз Роббингиздан мавъиза, кўксингиздаги нарсага шифо, мўминларга ҳидоят ва раҳмат келди.",215,11],["قُلْ بِفَضْلِ [h:6097[ٱ]للَّهِ وَبِرَحْمَتِه[n[ِۦ] فَبِذ[n[َٲ]لِكَ فَلْيَفْرَحُو[s[اْ] هُوَ خَيْ[a:2365[رٌ م]ِّ[g[مّ]َا يَ[q:2366[جْ]مَع[p[ُو]نَ","Сен: «Аллоҳнинг фазли ила ва Унинг раҳмати ила. Бас, ана шу билан хурсанд бўлсинлар. У улар жамлайдиган нарсалардан яхшидир», деб айт.",215,11],["قُلْ أَرَءَيْت[w:6098[ُم م]ّ[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ لَك[w:556[ُم م]ّ[u:6099[ِن ر]ِّزْ[f:6100[قٍ ف]َجَعَلْت[w:6101[ُم م]ِّنْهُ حَرَا[a:6102[مًا و]َحَلَ[n[ـٰ]ل[f:6103[اً ق]ُلْ ءَآللَّهُ أَذِنَ لَكُمْ‌ۖ أَمْ عَلَى [h:412[ٱ]للَّهِ تَفْتَر[p[ُو]نَ","Сен: «Аллоҳ сизга нозил қилган ризқдан хабар беринг-чи! Уни ҳаром ва ҳалол қилиб олдингиз!» деб айт. Сен: «Аллоҳ сизга изн бердими ёки Аллоҳга нисбатан ёлғон тўқияпсизми?» деб айт.",215,11],["وَمَا ظَ[g[نّ]ُ [h:6104[ٱ]لَّذِينَ يَفْتَرُونَ عَلَى [h:412[ٱ]للَّهِ [h:2035[ٱ]لْكَذِبَ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَذُو فَضْلٍ عَلَى [h:729[ٱ][l[ل][g[نّ]َاسِ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَشْكُر[p[ُو]نَ","Аллоҳга нисбатан ёлғон тўқиётганларнинг қиёмат куни ҳақида нима гумонлари бор? Албатта, Аллоҳ одамлар учун фазл эгасидир. Лекин кўплари шукр қилмаслар.",215,11],["وَمَا تَكُونُ فِى شَأْ[a:6105[نٍ و]َمَا تَتْلُو[s[اْ] مِنْهُ مِ[f:6106[ن ق]ُرْءَا[a:6107[نٍ و]َلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُ[g[نّ]َا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ‌ۚ وَمَا يَعْزُبُ ع[u:6108[َن ر]َّبِّكَ م[a:6109[ِن م]ِّثْقَالِ ذَرَّ[f:6110[ةٍ ف]ِى [h:44[ٱ]لْأَرْضِ وَلَا فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ وَل[o[َآ] أَصْغَرَ مِ[f:2624[ن ذ][n[َٲ]لِكَ وَل[o[َآ] أَكْبَرَ إِلَّا فِى كِتَ[n[ـٰ][a:4113[بٍ م]ُّب[p[ِي]نٍ","Қайси ҳолда бўлсанг, Қуръондан нимани тиловат этсанг, ишлардан қай бирини қилсанг, албатта, биз ўшанга киришаётган пайтингларда сизларга гувоҳмиз. На ер юзида ва на осмонларда зарра миқдоридаги, ундан кичикроқ ёки каттароқ нарса Роббингдан махфий бўла олмас, балки очиқ-ойдин китобдадир.",215,11],["أَل[o[َآ] إِ[g[نّ]َ أَوْلِي[o[َا]ٓءَ [h:6111[ٱ]للَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Огоҳ бўлингким, Аллоҳнинг дўстларига хавф йўқдир ва улар хафа ҳам бўлмаслар.",216,11],["ٱلَّذِينَ ءَامَنُو[s[اْ] وَكَانُو[s[اْ] يَتَّق[p[ُو]نَ","Улар иймон келтирганлар ва тақво қилганлардир.",216,11],["لَهُمُ [h:6112[ٱ]لْبُشْرَىٰ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا وَفِى [h:1108[ٱ]لْأَخِرَةِ‌ۚ لَا تَ[q:6113[بْ]دِيلَ لِكَلِمَ[n[ـٰ]تِ [h:4009[ٱ]للَّهِ‌ۚ ذ[n[َٲ]لِكَ هُوَ [h:5722[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Уларга ҳаёти дунёда ҳам, охиратда ҳам хушхабар бор. Аллоҳнинг сўзларини ўзгартириш йўқ. Ана ўша улуғ ютуқдир.",216,11],["وَلَا يَحْزُ[f:2435[نك]َ قَوْلُهُمْ‌ۘ إِ[g[نّ]َ [h:6114[ٱ]لْعِزَّةَ لِلَّهِ جَمِيعًا‌ۚ هُوَ [h:3721[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Уларнинг гапи сени хафа қилмасин. Азизликнинг барчаси Аллоҳникидир. У эшитгувчи ва билгувчи зотдир.",216,11],["أَل[o[َآ] إِ[g[نّ]َ لِلَّهِ مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَ[f:3453[ن ف]ِى [h:44[ٱ]لْأَرْضِ‌ۗ وَمَا يَتَّبِعُ [h:6115[ٱ]لَّذِينَ يَ[q:1240[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ شُرَك[o[َا]ٓءَ‌ۚ إ[a:4358[ِن ي]َتَّبِعُونَ إِلَّا [h:4359[ٱ][l[ل]ظَّ[g[نّ]َ وَإِنْ هُمْ إِلَّا يَخْرُص[p[ُو]نَ","Огоҳ бўлингким, осмонларда ким бўлса ва ер юзида ким бўлса, албатта, Аллоҳникидир. Аллоҳдан ўзга шерикларга илтижо қилаётганлар нимага эргашадилар? Улар фақат гумонга эргашадилар, холос. Улар фақат тахмин қиладилар, холос.",216,11],["هُوَ [h:153[ٱ]لَّذِى جَعَلَ لَكُمُ [h:6116[ٱ]لَّيْلَ لِتَسْكُنُو[s[اْ] فِيهِ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ مُ[q:6118[بْ]صِرًا‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:6119[مٍ ي]َسْمَع[p[ُو]نَ","У сизларга сокинлик топишингиз учун кечани ва кўрсатувчи этиб кундузни қилган зот. Албатта, бунда эшитадиган қавмлар учун оят-аломатлар бордир.",216,11],["قَالُو[s[اْ] [h:6120[ٱ]تَّخَذَ [h:606[ٱ]للَّهُ وَلَ[f:607[دًا‌ۗ س]ُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ]‌ۖ هُوَ [h:6121[ٱ]لْغَنِىُّ‌ۖ لَهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۚ إِنْ عِ[f:4508[ند]َك[w:4509[ُم م]ِّ[f:4798[ن س]ُلْطَ[n[ـٰ][i:6122[نِۭ ب]ِهَ[n[ـٰ]ذ[o[َآ‌ۚ] أَتَقُولُونَ عَلَى [h:412[ٱ]للَّهِ مَا لَا تَعْلَم[p[ُو]نَ","Улар: «Аллоҳ фарзанд тутди», дедилар. У покдир. У беҳожатдир. Осмонлардаги нарсалар ва ердаги нарсалар Уникидир. Бу ҳақда сизнинг ҳеч қандай далилингиз йўқ-ку! Аллоҳга нисбатан билмаган нарсангизни айтаверасизми?",216,11],["قُلْ إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَفْتَرُونَ عَلَى [h:412[ٱ]للَّهِ [h:2035[ٱ]لْكَذِبَ لَا يُفْلِح[p[ُو]نَ","Сен: «Албатта Аллоҳга нисбатан ёлғон тўқиганлар нажот топмаслар», деб айт.",216,11],["مَتَ[n[ـٰ][f:6123[عٌ ف]ِى [h:599[ٱ][l[ل]دُّنْيَا ثُ[g[مّ]َ إِلَيْنَا مَرْجِعُهُمْ ثُ[g[مّ]َ نُذِيقُهُمُ [h:6124[ٱ]لْعَذَابَ [h:6125[ٱ][l[ل]شَّدِيدَ بِمَا كَانُو[s[اْ] يَكْفُر[p[ُو]نَ","Бу дунёда фойдаланиш, кейин Бизга қайтишлари бор. Сўнгра Биз уларга, куфр келтириб ўтганлари учун, шиддатли азобни тоттирамиз.",216,11],["۞ وَ[h:9999[ٱ]تْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِه[n[ِۦ] يَ[n[ـٰ]قَوْمِ إِ[f:2594[ن ك]َانَ كَبُرَ عَلَيْك[w:6126[ُم م]َّقَامِى وَتَذْكِيرِى بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ فَعَلَى [h:6127[ٱ]للَّهِ تَوَكَّلْتُ فَأَ[q:6128[جْ]مِع[o[ُوٓ][s[اْ] أَمْرَكُمْ وَشُرَك[o[َا]ٓءَكُمْ ثُ[g[مّ]َ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُ[g[مّ]َ[f:6129[ةً ث]ُ[g[مّ]َ [h:6130[ٱ][q:6131[قْ]ض[o[ُوٓ][s[اْ] إِلَىَّ وَلَا تُ[f:5200[نظ]ِر[p[ُو]نِ","Уларга Нуҳнинг хабарини тиловат қилиб бер. Вақтики у ўз қавмига: «Эй қавмим, агар сизларга менинг мақомим ва Аллоҳнинг оятлари ила эслатишим оғир келаётган бўлса, бас, мен Аллоҳга таваккал қилдим. Сиз шерик келтирганларингиз билан биргаликда ўз ишингизни билаверинглар. Яна ишларингиз ўзингиз учун ноаниқ бўлиб қолмасин. Сўнгра менга нисбатан ҳукмингизни ижро этаверинглар, менга муҳлат берманглар.",217,11],["فَإِ[f:3779[ن ت]َوَلَّيْتُمْ فَمَا سَأَلْتُك[w:6132[ُم م]ِّنْ أَ[q:6133[جْ]رٍ‌ۖ إِنْ أَ[q:6134[جْ]رِىَ إِلَّا عَلَى [h:412[ٱ]للَّهِ‌ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ [h:6135[ٱ]لْمُسْلِم[p[ِي]نَ","Бас, агар юз ўгирсангиз, мен сизлардан ажр сўраганим йўқ. Менинг ажрим фақатгина Аллоҳдан. Ва мен мусулмонлардан бўлишга амр қилинганман», деди.",217,11],["فَكَذَّبُوهُ فَنَجَّيْنَ[n[ـٰ]هُ وَم[a:4948[َن م]َّعَهُ[n[ۥ] فِى [h:4780[ٱ]لْفُلْكِ وَجَعَلْنَ[n[ـٰ]هُمْ خَلَ[o[ـٰٓ]ئِفَ وَأَغْرَ[q:247[قْ]نَا [h:4781[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا‌ۖ فَ[h:1513[ٱ][f:1513[نظ]ُرْ كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6136[ٱ]لْمُ[f:6137[نذ]َر[p[ِي]نَ","Сўнгра уни ёлғончига чиқаришди. Бас, Биз уни ва у ила бирга бўлганларни кемада қутқардик ва уларни халифалар қилдик. Оятларимизни ёлғонга чиқарганларни ғарқ этдик. Огоҳлантирилганларнинг оқибати қандай бўлганига назар сол.",217,11],["ثُ[g[مّ]َ بَعَثْنَا م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] رُسُلاً إِلَىٰ قَوْمِهِمْ فَج[o[َا]ٓءُوه[c:6138[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ فَمَا كَانُو[s[اْ] لِيُؤْمِنُو[s[اْ] بِمَا كَذَّبُو[s[اْ] بِه[n[ِۦ] مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۚ كَذ[n[َٲ]لِكَ نَ[q:6139[طْ]بَعُ عَلَىٰ قُلُوبِ [h:6140[ٱ]لْمُعْتَد[p[ِي]نَ","Сўнгра ундан кейин Пайғамбарларни қавмларига юбордик. Бас, улар очиқ-ойдин ҳужжатлар ила келдилар. Аммо улар олдин ёлғонга чиқарган нарсаларига иймон келтирувчи бўлмадилар. Тажовузкорларнинг қалбига шундай қилиб муҳр босамиз.",217,11],["ثُ[g[مّ]َ بَعَثْنَا م[i:1453[ِنۢ ب]َعْدِه[w:4907[ِم م]ُّوسَىٰ وَهَ[n[ـٰ]رُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِ[s[يْ]ه[n[ِۦ] بِـَٔـايَ[n[ـٰ]تِنَا فَ[h:4956[ٱ]سْتَكْبَرُو[s[اْ] وَكَانُو[s[اْ] قَوْ[a:4957[مًا م]ُّ[q:4958[جْ]رِم[p[ِي]نَ","Сўнгра улардан кейин Мусо ва Ҳорунни Фиръавн ва унинг қавмига Ўз оят-мўъжизаларимиз ила юбордик. Бас, улар кибру ҳаво қилдилар ва жиноятчи қавм бўлдилар.",217,11],["فَلَ[g[مّ]َا ج[o[َا]ٓءَهُمُ [h:6141[ٱ]لْحَقُّ مِنْ عِ[f:6142[ند]ِنَا قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَسِحْ[a:6143[رٌ م]ُّب[p[ِي]نٌ","Бизнинг ҳузуримиздан уларга ҳақ келган пайтда: «Бу, албатта, очиқ-ойдин сеҳрдир», дедилар.",217,11],["قَالَ مُوسَ[o[ىٰٓ] أَتَقُولُونَ لِلْحَقِّ لَ[g[مّ]َا ج[o[َا]ٓءَكُمْ‌ۖ أَسِحْرٌ هَ[n[ـٰ]ذَا وَلَا يُفْلِحُ [h:6144[ٱ][l[ل]سَّ[n[ـٰ]حِر[p[ُو]نَ","Мусо: «Сизга ҳақ келганда дейсизларми?! Шу сеҳрми?! Сеҳргарлар нажот топмаслар», деди.",217,11],["قَال[o[ُوٓ][s[اْ] أَجِئْتَنَا لِتَلْفِتَنَا عَ[g[مّ]َا وَجَ[q:3834[دْ]نَا عَلَيْهِ ءَاب[o[َا]ٓءَنَا وَتَكُونَ لَكُمَا [h:6145[ٱ]لْكِ[q:6146[بْ]رِي[o[َا]ٓءُ فِى [h:44[ٱ]لْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِن[p[ِي]نَ","Улар: «Сен бизни оталаримиз тутиб келаётганида топган нарсамиздан буриш учун ва икковингизга ер юзида катталик бўлиши учун келдингми? Биз икковингизга иймон келтирувчилардан эмасмиз», дедилар.",217,11],["وَقَالَ فِرْعَوْنُ [h:6147[ٱ]ئْتُونِى بِكُلِّ سَ[n[ـٰ]حِرٍ عَل[p[ِي]مٍ","Фиръавн: «Менга барча билимдон сеҳргарни келтиринглар», деди.",218,11],["فَلَ[g[مّ]َا ج[o[َا]ٓءَ [h:6148[ٱ][l[ل]سَّحَرَةُ قَالَ لَه[w:6149[ُم م]ُّوسَ[o[ىٰٓ] أَلْقُو[s[اْ] م[o[َآ] أَ[f:428[نت][w:6150[ُم م]ُّلْق[p[ُو]نَ","Сеҳргарлар келганида, Мусо уларга: «Сизлар ташламоқчи бўлган нарсангизни ташлангиз», деди.",218,11],["فَلَ[g[مّ][o[َآ] أَلْقَوْ[s[اْ] قَالَ مُوسَىٰ مَا جِئْت[c:6151[ُم ب]ِهِ [h:6152[ٱ][l[ل]سِّحْرُ‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَيُ[q:6153[بْ]طِلُهُ[o[ۥٓ‌ۖ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُصْلِحُ عَمَلَ [h:6154[ٱ]لْمُفْسِد[p[ِي]نَ","Улар ташлаганларида, Мусо: «Сиз келтирган нарса сеҳрдир. Албатта, Аллоҳ уни ботил қилур. Зеро, Аллоҳ бузғунчиларнинг ишини ўнгламас.",218,11],["وَيُحِقُّ [h:6155[ٱ]للَّهُ [h:6156[ٱ]لْحَقَّ بِكَلِمَ[n[ـٰ]تِه[n[ِۦ] وَلَوْ كَرِهَ [h:5254[ٱ]لْمُ[q:5255[جْ]رِم[p[ُو]نَ","Ва Аллоҳ Ўз калимаси ила, гарчи жиноятчилар ёқтирмаса ҳам, ҳақни рўёбга чиқарур», деди.",218,11],["فَم[o[َآ] ءَامَنَ لِمُوسَ[o[ىٰٓ] إِلَّا ذُرِّيَّ[a:6157[ةٌ م]ِّ[f:4770[ن ق]َوْمِه[n[ِۦ] عَلَىٰ خَوْ[a:6158[فٍ م]ِّ[f:6159[ن ف]ِرْعَوْنَ وَمَلَإِ[s[يْ]هِمْ أ[a:6160[َن ي]َفْتِنَهُمْ‌ۚ وَإِ[g[نّ]َ فِرْعَوْنَ لَعَا[f:6161[لٍ ف]ِى [h:44[ٱ]لْأَرْضِ وَإِ[g[نّ]َهُ[n[ۥ] لَمِنَ [h:6162[ٱ]لْمُسْرِف[p[ِي]نَ","Мусога ўз қавмидан баъзи зурриётларгина Фиръавн ва амалдор-зодагонларининг фитна қилмоқларидан қўрққан ҳолларида иймон келтирдилар, холос. Албатта, Фиръавн ер юзида баланд кетган эди. Албатта, у исрофчилардан эди.",218,11],["وَقَالَ مُوسَىٰ يَ[n[ـٰ]قَوْمِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ ءَامَ[f:703[نت][c:5341[ُم ب]ِ[h:32[ٱ]للَّهِ فَعَلَيْهِ تَوَكَّل[o[ُوٓ][s[اْ] إِ[f:109[ن ك]ُ[f:100[نت][w:6163[ُم م]ُّسْلِم[p[ِي]نَ","Мусо: «Эй қавмим, агар Аллоҳга иймон келтирган бўлсангиз, агар мусулмон бўлсангиз, фақат Унгагина таваккал қилинг», деди.",218,11],["فَقَالُو[s[اْ] عَلَى [h:412[ٱ]للَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَ[q:4719[جْ]عَلْنَا فِتْنَ[u:6164[ةً ل]ِّلْقَوْمِ [h:6165[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Улар: «Аллоҳгагина таваккал қилдик. Роббимиз, бизни золим қавмларга фитна қилиб қўйма.",218,11],["وَنَجِّنَا بِرَحْمَتِكَ مِنَ [h:4196[ٱ]لْقَوْمِ [h:1432[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Ва Ўз раҳматинг ила бизга кофир қавмлардан нажот бергин», дедилар.",218,11],["وَأَوْحَيْن[o[َآ] إِلَىٰ مُوسَىٰ وَأَخِيهِ أَ[f:6166[ن ت]َبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُو[a:6167[تًا و]َ[h:6168[ٱ][q:6168[جْ]عَلُو[s[اْ] بُيُوتَكُمْ قِ[q:747[بْ]لَ[a:6169[ةً و]َأَقِيمُو[s[اْ] [h:214[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ‌ۗ وَبَشِّرِ [h:1257[ٱ]لْمُؤْمِن[p[ِي]نَ","Биз Мусога ва унинг биродарига: «Икковингиз қавмингиз учун Мисрда уйлар тайёрланг, уйларингизни қибла қилиб, намозни тўкис адо этинглар ва мўминларга хушхабар бер», деб ваҳий юбордик.",218,11],["وَقَالَ مُوسَىٰ رَبَّن[o[َآ] إِ[g[نّ]َكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُ[n[ۥ] زِينَ[a:6170[ةً و]َأَمْو[n[َٲ]ل[f:6171[اً ف]ِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا رَبَّنَا لِيُضِلُّو[s[اْ] عَ[f:6172[ن س]َبِيلِكَ‌ۖ رَبَّنَا [h:6173[ٱ][q:6174[طْ]مِسْ عَلَ[o[ىٰٓ] أَمْو[n[َٲ]لِهِمْ وَ[h:6175[ٱ]شْدُ[q:6175[دْ] عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُو[s[اْ] حَتَّىٰ يَرَوُ[s[اْ] [h:6176[ٱ]لْعَذَابَ [h:6177[ٱ]لْأَل[p[ِي]مَ","Мусо: «Эй Роббимиз, Сен Фиръавнга ва унинг амалдорларига зебу зийнат ва молу дунё бердинг. Роббимиз, бу Сенинг йўлингдан адаштиришлари учундир. Роббимиз, уларнинг молларини йўқ қилгин ва қалбларини қаттиқ қилгин, то аламли азобни кўрмагунларича иймонга келмасинлар», деди.",218,11],["قَالَ قَ[q:298[دْ] أُجِيبَ[d:6178[ت] دَّعْوَتُكُمَا فَ[h:6179[ٱ]سْتَقِيمَا وَلَا تَتَّبِع[m[َا]ٓ[g[نّ]ِ سَبِيلَ [h:6180[ٱ]لَّذِينَ لَا يَعْلَم[p[ُو]نَ","У: «Батаҳқиқ, икковингизнинг дуоингиз қабул бўлди. Бас, собит туринглар ва билмайдиганларнинг йўлига эргашманглар», деди.",219,11],["۞ وَجَ[n[ـٰ]وَزْنَا بِبَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ [h:4977[ٱ]لْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُ[n[ۥ] بَغْ[a:6181[يًا و]َعَ[q:6182[دْ]وًا‌ۖ حَتَّ[o[ىٰٓ] إِذ[o[َآ] أَ[q:6183[دْ]رَكَهُ [h:6184[ٱ]لْغَرَقُ قَالَ ءَامَ[f:6185[نت]ُ أَ[g[نّ]َهُ[n[ۥ] ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا [h:6186[ٱ]لَّذ[o[ِىٓ] ءَامَنَتْ بِه[n[ِۦ] بَن[o[ُوٓ][s[اْ] إِسْر[o[َٲ]ٓءِيلَ وَأَنَا۟ مِنَ [h:6135[ٱ]لْمُسْلِم[p[ِي]نَ","Ва Бани Исроилни денгиздан ўтказдик. Бас, Фиръавн ва унинг аскарлари ҳаддан ошган ва туғён қилган ҳолда уларни таъқиб этдилар. Токи унга ғарқ бўлиш етганида: «Бани Исроил иймон келтирган зотдан ўзга илоҳ йўқлигига иймон келтирдим ва мен мусулмонларданман», деди.",219,11],["ءَ[m[آ]لْـَٔ[n[ـٰ]نَ وَقَ[q:387[دْ] عَصَيْتَ قَ[q:129[بْ]لُ وَكُ[f:6187[نت]َ مِنَ [h:6188[ٱ]لْمُفْسِد[p[ِي]نَ","Эндими! Олдин исён қилган ва бузғунчилардан бўлган эдинг-ку?!",219,11],["فَ[h:9999[ٱ]لْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَ[a:6189[ةً‌ۚ و]َإِ[g[نّ]َ كَثِي[a:3614[رًا م]ِّنَ [h:721[ٱ][l[ل][g[نّ]َاسِ عَنْ ءَايَ[n[ـٰ]تِنَا لَغَ[n[ـٰ]فِل[p[ُو]نَ","Бугун сенинг баданингни қутқарамиз. Токи ўзингдан кейингиларга ибрат бўлгин. Албатта, кўп одамлар Бизнинг оятларимиздан ғофилдирлар.",219,11],["وَلَقَ[q:341[دْ] بَوَّأْنَا بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ مُبَوَّأَ صِ[q:5937[دْ][a:6190[قٍ و]َرَزَ[q:6191[قْ]نَ[n[ـٰ]ه[w:6192[ُم م]ِّنَ [h:5307[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تِ فَمَا [h:6193[ٱ]خْتَلَفُو[s[اْ] حَتَّىٰ ج[o[َا]ٓءَهُمُ [h:1804[ٱ]لْعِلْمُ‌ۚ إِ[g[نّ]َ رَبَّكَ يَ[q:6194[قْ]ضِى بَيْنَهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ فِيمَا كَانُو[s[اْ] فِيهِ يَخْتَلِف[p[ُو]نَ","Батаҳқиқ, Биз Бани Исроилни ҳақиқий омонлик масканига жойлаштирдик ва уларни пок нарсалар ила ризқлантирдик. Бас, улар то ўзларига илм келмагунча ихтилоф қилмадилар. Албатта, Роббинг қиёмат куни улар орасида ихтилоф қилган нарсалари ҳақида Ўзи ҳукм чиқарадир.",219,11],["فَإِ[f:6195[ن ك]ُ[f:735[نت]َ فِى شَ[a:6196[كٍّ م]ِّ[g[مّ][o[َآ] أَ[f:515[نز]َلْن[o[َآ] إِلَيْكَ فَسْــَٔلِ [h:6197[ٱ]لَّذِينَ يَ[q:6198[قْ]رَءُونَ [h:6199[ٱ]لْكِتَ[n[ـٰ]بَ مِ[f:18[ن ق]َ[q:19[بْ]لِكَ‌ۚ لَقَ[q:2389[دْ] ج[o[َا]ٓءَكَ [h:6200[ٱ]لْحَقُّ م[u:770[ِن ر]َّبِّكَ فَلَا تَكُونَ[g[نّ]َ مِنَ [h:771[ٱ]لْمُمْتَر[p[ِي]نَ","Агар сенга нозил қилган нарсамиздан шакда бўлсанг, сендан олдин китобни ўқиганлардан сўра. Батаҳқиқ, сенга Роббингдан ҳақ келди. Бас, ҳеч шубҳа қилгувчилардан бўлма.",219,11],["وَلَا تَكُونَ[g[نّ]َ مِنَ [h:523[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ فَتَكُونَ مِنَ [h:340[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","Зинҳор Аллоҳнинг оятларини ёлғонга чиқарувчилардан бўлма, у ҳолда зиёнкорлардан бўлиб қоласан.",219,11],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِن[p[ُو]نَ","Албатта, Роббингнинг калималари зиммасига вожиб бўлганлар иймонга келмаслар.",219,11],["وَلَوْ ج[o[َا]ٓءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُ[s[اْ] [h:6176[ٱ]لْعَذَابَ [h:6177[ٱ]لْأَل[p[ِي]مَ","Агар уларга ҳамма оят-мўъжизалар келса ҳам, то аламли азобни кўрмагунларича.",219,11],["فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَه[o[َآ] إِيمَ[n[ـٰ]نُه[o[َآ] إِلَّا قَوْمَ يُونُسَ لَ[g[مّ][o[َآ] ءَامَنُو[s[اْ] كَشَفْنَا عَنْهُمْ عَذَابَ [h:6201[ٱ]لْخِزْىِ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا وَمَتَّعْنَ[n[ـٰ]هُمْ إِلَىٰ ح[p[ِي]نٍ","Қани энди бирон қишлоқ иймон келтирганда унга иймони манфаат берса эди. Фақат Юнус қавми иймон келтирганларида улардан ҳаёти дунёдаги хорлик азобини кушойиш қилдик ва уларни маълум вақтгача фойдалантирдик.",220,11],["وَلَوْ ش[o[َا]ٓءَ رَبُّكَ لَأَمَنَ مَ[f:2074[ن ف]ِى [h:44[ٱ]لْأَرْضِ كُلُّهُمْ جَمِيعًا‌ۚ أَفَأَ[f:6069[نت]َ تُكْرِهُ [h:6202[ٱ][l[ل][g[نّ]َاسَ حَتَّىٰ يَكُونُو[s[اْ] مُؤْمِن[p[ِي]نَ","Агар Роббинг хоҳласа, ер юзидаги кишиларнинг ҳаммаси иймонга келар эдилар. Ёки сен одамларни мўмин бўлишга мажбурлайсанми?",220,11],["وَمَا كَانَ لِنَفْسٍ أَ[f:6203[ن ت]ُؤْمِنَ إِلَّا بِإِذْنِ [h:509[ٱ]للَّهِ‌ۚ وَيَ[q:6204[جْ]عَلُ [h:6205[ٱ][l[ل]رِّ[q:4401[جْ]سَ عَلَى [h:289[ٱ]لَّذِينَ لَا يَعْقِل[p[ُو]نَ","Аллоҳнинг изнисиз ҳеч бир жон мўмин бўла олмас. У ақл юргизмайдиганларга ўта ифлосликни раво кўрур.",220,11],["قُلِ [h:6206[ٱ][f:3950[نظ]ُرُو[s[اْ] مَاذَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَمَا تُغْنِى [h:6207[ٱ]لْأَيَ[n[ـٰ]تُ وَ[h:6208[ٱ][l[ل][g[نّ]ُذُرُ عَ[f:6209[ن ق]َوْ[u:6210[مٍ ل]َّا يُؤْمِن[p[ُو]نَ","Сен: «Осмонлару ердаги нарсаларга назар солинглар. Иймон келтирмайдиган қавмларга оят-мўъжизалар ва қўрқитувлар фойда бермас», деб айт.",220,11],["فَهَلْ يَ[f:6211[نت]َظِرُونَ إِلَّا مِثْلَ أَيَّامِ [h:6212[ٱ]لَّذِينَ خَلَوْ[s[اْ] مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ قُلْ فَ[h:4800[ٱ][f:4800[نت]َظِر[o[ُوٓ][s[اْ] إِ[g[نّ]ِى مَعَك[w:2068[ُم م]ِّنَ [h:4801[ٱ]لْمُ[f:4802[نت]َظِر[p[ِي]نَ","Улар фақат ўзларидан олдин ўтганларнинг кунларига ўхшаш кунларга интизор бўлмоқдаларми? Сен: «Бас, интизор бўлинглар. Албатта, мен ҳам сизлар билан интизор бўлгувчиларданман», деб айт.",220,11],["ثُ[g[مّ]َ نُنَجِّى رُسُلَنَا وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ‌ۚ] كَذ[n[َٲ]لِكَ حَقًّا عَلَيْنَا نُ[f:6213[نج]ِ [h:6214[ٱ]لْمُؤْمِن[p[ِي]نَ","Сўнгра Пайғамбарларимизга ва иймон келтирганларга нажот берамиз. Шундай қилиб, мўминларга нажот бермоғимиз зиммамиздаги бурчдир.",220,11],["قُلْ يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ فِى شَ[a:6215[كٍّ م]ِّ[f:6216[ن د]ِينِى فَل[o[َآ] أَعْبُدُ [h:6217[ٱ]لَّذِينَ تَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَلَ[n[ـٰ]كِنْ أَعْبُدُ [h:6218[ٱ]للَّهَ [h:2537[ٱ]لَّذِى يَتَوَفَّ[n[ـٰ]كُمْ‌ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Сен: «Эй одамлар, агар менинг динимда шак-шубҳангиз бўлса, бас, мен сизлар ибодат қилаётган–Аллоҳдан ўзга нарсаларга ибодат қилмайман. Лекин сизни вафот эттирадиган Аллоҳга ибодат қиламан ва мўминлардан бўлмоғимга амр қилинганман», деб айт.",220,11],["وَأَنْ أَقِمْ وَ[q:749[جْ]هَكَ لِلدِّينِ حَنِي[a:6219[فًا و]َلَا تَكُونَ[g[نّ]َ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Юзингни динга тўғри тут. Мушриклардан бўлма.",220,11],["وَلَا تَ[q:6220[دْ]عُ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مَا لَا يَ[f:6221[نف]َعُكَ وَلَا يَضُرُّكَ‌ۖ فَإِ[f:6222[ن ف]َعَلْتَ فَإِ[g[نّ]َكَ إِ[a:6223[ذًا م]ِّنَ [h:187[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Аллоҳдан ўзга–сенга манфаат ҳам, зарар ҳам бермайдиган–нарсага илтижо қилма. Бас, агар шундай қилсанг, унда сен золимлардан бўласан.",220,11],["وَإ[a:3962[ِن ي]َمْسَسْكَ [h:3963[ٱ]للَّهُ بِضُ[f:3964[رٍّ ف]َلَا كَاشِفَ لَهُ[o[ۥٓ] إِلَّا هُوَ‌ۖ وَإ[a:6224[ِن ي]ُرِ[q:6225[دْ]كَ بِخَيْ[f:6226[رٍ ف]َلَا ر[m[َا]ٓدَّ لِفَضْلِه[n[ِۦ]‌ۚ يُصِيبُ بِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[n[ِۦ]‌ۚ وَهُوَ [h:6227[ٱ]لْغَفُورُ [h:6228[ٱ][l[ل]رَّح[p[ِي]مُ","Агар Аллоҳ сени зарар ила тутса, Ундан ўзга ўшанга кушойиш берувчи йўқдир. Агар У сенга яхшиликни ирода қилса, Унинг фазлини рад қилувчи ҳам йўқдир. Уни бандаларидан хоҳлаганига етказади. У мағфират қилгувчи ва раҳмли зотдир.",221,11],["قُلْ يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ قَ[q:298[دْ] ج[o[َا]ٓءَكُمُ [h:6229[ٱ]لْحَقُّ م[u:243[ِن ر]َّبِّكُمْ‌ۖ فَمَنِ [h:6230[ٱ]هْتَدَىٰ فَإِ[g[نّ]َمَا يَهْتَدِى لِنَفْسِه[n[ِۦ]‌ۖ وَمَ[f:6231[ن ض]َلَّ فَإِ[g[نّ]َمَا يَضِلُّ عَلَيْهَا‌ۖ وَم[o[َآ] أَنَا۟ عَلَيْك[c:4147[ُم ب]ِوَك[p[ِي]لٍ","Сен: «Эй одамлар, сизга Роббингиздан ҳақ келди. Бас, ким ҳидоятга юрса, ўзи учун ҳидоят топади. Ким залолатга кетса, ўз зарарига залолат топади. Мен сизларнинг устингиздан қўриқчи эмасман», деб айт.",221,11],["وَ[h:9999[ٱ]تَّبِعْ مَا يُوحَ[o[ىٰٓ] إِلَيْكَ وَ[h:6232[ٱ]صْبِرْ حَتَّىٰ يَحْكُمَ [h:4856[ٱ]للَّهُ‌ۚ وَهُوَ خَيْرُ [h:4857[ٱ]لْحَ[n[ـٰ]كِم[p[ِي]نَ","Ва сенга ваҳий қилинган нарсага эргаш ва Аллоҳ ҳукм қилгунча сабр қил. У ҳукм қилгувчиларнинг яхшисидир.",221,11]]},{"n":11,"ar":"هُودٍ","en":"Hud","uz":"Ҳуд","type":"Макка","ayahs":[["ا[m[لٓ]ر‌ۚ كِتَ[n[ـٰ]بٌ أُحْكِمَتْ ءَايَ[n[ـٰ]تُهُ[n[ۥ] ثُ[g[مّ]َ فُصِّلَتْ م[u:6233[ِن ل]َّدُنْ حَكِيمٍ خَب[p[ِي]رٍ","Алиф. Лом. Ро. китоб оятлари маҳкам қилинган, сўнгра ҳикматли ва хабардор Зот томонидан муфассал қилингандир.",221,11],["أَلَّا تَعْبُد[o[ُوٓ][s[اْ] إِلَّا [h:416[ٱ]للَّهَ‌ۚ إِ[g[نّ]َنِى لَك[w:6234[ُم م]ِّنْهُ نَذِي[a:5179[رٌ و]َبَش[p[ِي]رٌ","Аллоҳдан ўзгага ибодат қилмаслигингиз учундир. Албатта, мен сизларга Ундан келган огоҳлантирувчи ва хушхабарчиман.",221,11],["وَأَنِ [h:6235[ٱ]سْتَغْفِرُو[s[اْ] رَبَّكُمْ ثُ[g[مّ]َ تُوب[o[ُوٓ][s[اْ] إِلَيْهِ يُمَتِّعْك[w:6236[ُم م]َّتَ[n[ـٰ]عًا حَسَنًا إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَم[a:6237[ًّى و]َيُؤْتِ كُلَّ ذِى فَضْ[f:6238[لٍ ف]َضْلَهُ[n[ۥ]‌ۖ وَإِ[f:706[ن ت]َوَلَّوْ[s[اْ] فَإِ[g[نّ][o[ِىٓ] أَخَافُ عَلَيْكُمْ عَذَابَ يَوْ[f:6239[مٍ ك]َب[p[ِي]رٍ","Роббингизга истиғфор айтинглар, сўнгра Унга тавба қилинглар. У сизларни маълум муддатгача яхши роҳатлар ила баҳраманд қилур ва ҳар бир фазл эгасига фазлини берур. Агар юз ўгириб кетсангиз, бас, албатта, мен сизларга улуғ куннинг азоби бўлишидан қўрқаман.",221,11],["إِلَى [h:1637[ٱ]للَّهِ مَرْجِعُكُمْ‌ۖ وَهُوَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Аллоҳнинг Ўзига қайтишингиз бор. У ҳар бир нарсага қодир зотдир.",221,11],["أَل[o[َآ] إِ[g[نّ]َهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُو[s[اْ] مِنْهُ‌ۚ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ‌ۚ إِ[g[نّ]َهُ[n[ۥ] عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","Огоҳ бўлингким, албатта, улар ундан яшириниш учун кўксиларига эгадилар. Огоҳ бўлингким, кийимларига ўралган чоғларида ҳам, У зот нимани сир тутаётганларинию нимани ошкор қилаётганларини биладир. Албатта, У қалблардаги бор нарсаларни билгувчи зотдир.",221,11],["۞ وَمَا مِ[f:4026[ن د][m[َا]ٓبَّ[f:4027[ةٍ ف]ِى [h:44[ٱ]لْأَرْضِ إِلَّا عَلَى [h:412[ٱ]للَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا‌ۚ كُ[f:6240[لٌّ ف]ِى كِتَ[n[ـٰ][a:4113[بٍ م]ُّب[p[ِي]نٍ","Ер юзида ўрмалаган нарса борки, уларнинг ризқи Аллоҳнинг зиммасидадир. У уларнинг турар жойларини ҳам, борар жойларини ҳам билур. Ҳаммаси очиқ-ойдин китобдадир.",222,12],["وَهُوَ [h:4114[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ فِى سِتَّةِ أَيَّا[a:6241[مٍ و]َكَانَ عَرْشُهُ[n[ۥ] عَلَى [h:6242[ٱ]لْم[o[َا]ٓءِ لِيَ[q:3603[بْ]لُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَل[a:6243[اً‌ۗ و]َلَئِ[f:6244[ن ق]ُلْتَ إِ[g[نّ]َك[w:6245[ُم م]َّ[q:6246[بْ]عُوثُونَ م[i:146[ِنۢ ب]َعْدِ [h:6247[ٱ]لْمَوْتِ لَيَقُولَ[g[نّ]َ [h:6248[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا سِحْ[a:3879[رٌ م]ُّب[p[ِي]نٌ","У сизлардан қайсингизнинг амали яхшироқ эканини синаб кўриш учун олти кунда осмонлару ерни яратди. Ўшанда арши сув устида эди. Агар сен: «Сизлар ўлимдан кейин, албатта, қайта тирилтириласизлар», десанг, куфр келтирганлар, албатта: «Бу очиқ-ойдин сеҳрдан ўзга нарса эмас», дерлар.",222,12],["وَلَئِنْ أَخَّرْنَا عَنْهُمُ [h:6249[ٱ]لْعَذَابَ إِلَ[o[ىٰٓ] أُ[g[مّ]َ[a:6250[ةٍ م]َّعْدُودَ[u:6251[ةٍ ل]َّيَقُولُ[g[نّ]َ مَا يَحْبِسُهُ[o[ۥٓ‌ۗ] أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِه[w:6252[ِم م]َّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Агар Биз улардан маълум муддатгача азобни кечиктирсак, албатта, улар: «Уни нима тўхтатиб турибди?» дерлар. Огоҳ бўлингларким, у келган кунда улардан қайтарилмас ва уларни ўзлари истеҳзо қилиб юрган нарса ўраб олур.",222,12],["وَلَئِنْ أَذَ[q:5991[قْ]نَا [h:6253[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ مِ[g[نّ]َا رَحْمَ[f:6254[ةً ث]ُ[g[مّ]َ نَزَعْنَ[n[ـٰ]هَا مِنْهُ إِ[g[نّ]َهُ[n[ۥ] لَيَــُٔو[f:6255[سٌ ك]َف[p[ُو]رٌ","Агар инсонга Ўз томонимиздан роҳатни тоттириб, сўнгра ундан уни тортиб олсак, албатта, у ноумид ва ношукр бўлур.",222,12],["وَلَئِنْ أَذَ[q:6256[قْ]نَ[n[ـٰ]هُ نَعْم[o[َا]ٓءَ بَعْدَ ضَرّ[o[َا]ٓءَ مَسَّتْهُ لَيَقُولَ[g[نّ]َ ذَهَبَ [h:6257[ٱ][l[ل]سَّيِّـَٔـاتُ عَ[g[نّ][o[ِىٓ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] لَفَرِ[f:6258[حٌ ف]َخ[p[ُو]رٌ","Агар унга етган қийинчиликлардан сўнг неъмат тоттирсак, албатта: «Мендан ёмонликлар кетди», дейдир. Албатта, у хурсанд ва фахрлидир.",222,12],["إِلَّا [h:778[ٱ]لَّذِينَ صَبَرُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَه[w:3412[ُم م]َّغْفِرَ[a:3413[ةٌ و]َأَ[q:3414[جْ][f:6259[رٌ ك]َب[p[ِي]رٌ","Магар сабр қилганлар ва яхши амаллар қилганлар, ана ўшаларга мағфират ва катта ажр бор.",222,12],["فَلَعَلَّكَ تَارِ[i:6260[كُۢ ب]َعْضَ مَا يُوحَ[o[ىٰٓ] إِلَيْكَ وَض[o[َا]ٓئِ[i:6261[قُۢ ب]ِه[n[ِۦ] صَ[q:6262[دْ]رُكَ أ[a:6263[َن ي]َقُولُو[s[اْ] لَوْل[o[َآ] أُ[f:17[نز]ِلَ عَلَيْهِ كَ[f:6264[نز]ٌ أَوْ ج[o[َا]ٓءَ مَعَهُ[n[ۥ] مَلَكٌ‌ۚ إِ[g[نّ]َم[o[َآ] أَ[f:169[نت]َ نَذِي[a:6265[رٌ‌ۚ و]َ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[a:4302[َىْءٍ و]َك[p[ِي]لٌ","Эҳтимол сен уларнинг: «Унга хазина туширилса эди» ёки «У билан бирга фаришта келса эди», деганлари учун ўзингга ваҳий қилинган нарсанинг баъзисини тарк қилмоқчи бўларсан ёки ундан юрагинг сиқилар. Сен огоҳлантирувчисан, холос. Аллоҳнинг Ўзи ҳамма нарсага вакилдир.",222,12],["أَمْ يَقُولُونَ [h:6061[ٱ]فْتَرَ[n[ٮٰ]هُ‌ۖ قُلْ فَأْتُو[s[اْ] بِعَشْرِ سُوَ[a:6266[رٍ م]ِّثْلِه[n[ِۦ] مُفْتَرَيَ[n[ـٰ][a:6267[تٍ و]َ[h:105[ٱ][q:105[دْ]عُو[s[اْ] مَنِ [h:6063[ٱ]سْتَطَعْت[w:5394[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Ёки: «Ўзи тўқиб олди», дерларми? Сен: «Бас, агар ростгўй бўлсаларингиз, Аллоҳдан бошқа кимни чақиришга қодир бўлсангиз, чақириб, бунга ўхшаш ўнта тўқилган сура келтиринг-чи», дегин.",223,12],["فَإِلَّمْ يَسْتَجِيبُو[s[اْ] لَكُمْ فَ[h:1140[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َم[o[َآ] أُ[f:17[نز]ِلَ بِعِلْمِ [h:6268[ٱ]للَّهِ وَأ[u:6269[َن ل]ّ[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۖ فَهَلْ أَ[f:428[نت][w:2056[ُم م]ُّسْلِم[p[ُو]نَ","Агар жавоб бера олмасалар, бас, билингки, у фақатгина Аллоҳнинг илми ила нозил қилингандир. Ундан ўзга бирон илоҳ йўқдир. Энди мусулмон бўларсизлар?!",223,12],["مَ[f:506[ن ك]َانَ يُرِيدُ [h:6270[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَ[n[ـٰ]لَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُ[q:6271[بْ]خَس[p[ُو]نَ","Кимки бу дунё ҳаётини ва унинг зийнатини хоҳласа, бу борадаги амалларининг ни тўлиқ берурмиз. Улар бунда камситилмаслар.",223,12],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ لَيْسَ لَهُمْ فِى [h:536[ٱ]لْأَخِرَةِ إِلَّا [h:6272[ٱ][l[ل][g[نّ]َارُ‌ۖ وَحَبِطَ مَا صَنَعُو[s[اْ] فِيهَا وَبَ[n[ـٰ]طِ[a:4986[لٌ م]َّا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Ана ўшаларга охиратда дўзах оловидан бошқа ҳеч вақо йўқдир. Бу дунёда қилган ишлари ҳабата бўлди ва қилган амаллари ботил бўлди.",223,12],["أَفَمَ[f:6273[ن ك]َانَ عَلَىٰ بَيِّنَ[a:4097[ةٍ م]ّ[u:192[ِن ر]َّبِّه[n[ِۦ] وَيَتْلُوهُ شَاهِ[a:6274[دٌ م]ِّنْهُ وَمِ[f:6275[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] كِتَ[n[ـٰ]بُ مُوسَ[o[ىٰٓ] إِمَا[a:6276[مًا و]َرَحْمَةً‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يُؤْمِنُونَ بِه[n[ِۦ]‌ۚ وَم[a:636[َن ي]َكْفُرْ بِه[n[ِۦ] مِنَ [h:6277[ٱ]لْأَحْزَابِ فَ[h:6278[ٱ][l[ل][g[نّ]َارُ مَوْعِدُهُ[n[ۥ]‌ۚ فَلَا تَكُ فِى مِرْيَ[a:6279[ةٍ م]ِّنْهُ‌ۚ إِ[g[نّ]َهُ [h:6280[ٱ]لْحَقُّ م[u:770[ِن ر]َّبِّكَ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يُؤْمِن[p[ُو]نَ","Ўз Роббидан аниқ ҳужжатга эга бўлган, унга ўша нинг Ўзидан гувоҳ эргашган ва удан олдин Мусонинг китоби имом ва раҳмат ҳолида унга бўлган кишига ми? Ана ўшалар уга иймон келтирарлар. Гуруҳлардан ким унга куфр келтирса, унга ваъда қилинган жой жаҳаннамдир. Сен у ҳақда шак-шубҳада бўлма! Албатта, у Роббингдан келган ҳақдир. Лекин одамларнинг кўплари иймон келтирмаслар.",223,12],["وَمَنْ أَظْلَمُ مِ[g[مّ]َنِ [h:3980[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِبًا‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ [h:6281[ٱ]لْأَشْهَ[n[ـٰ]دُ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ [h:6282[ٱ]لَّذِينَ كَذَبُو[s[اْ] عَلَىٰ رَبِّهِمْ‌ۚ أَلَا لَعْنَةُ [h:822[ٱ]للَّهِ عَلَى [h:1035[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Аллоҳга нисбатан ёлғон тўқиган кимсадан ҳам золимроқ одам борми? Ана ўшалар Роббиларига рўбарў қилинурлар ва гувоҳлар: «Анавилар Роббилари шаънига ёлғон гапирганлардир. Огоҳ бўлингким, Аллоҳнинг лаънати золимларгадир», дерлар.",223,12],["ٱلَّذِينَ يَصُدُّونَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ وَيَ[q:4708[بْ]غُونَهَا عِوَ[a:4709[جًا و]َه[c:4710[ُم ب]ِ[h:447[ٱ]لْأَخِرَةِ هُمْ كَ[n[ـٰ]فِر[p[ُو]نَ","Улар Аллоҳнинг йўлидан тўсарлар ва унинг эгри бўлишини хоҳларлар ҳамда улар охиратга куфр келтирувчи кимсалардир.",223,12],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَمْ يَكُونُو[s[اْ] مُعْجِزِينَ فِى [h:44[ٱ]لْأَرْضِ وَمَا كَانَ لَه[w:1812[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مِنْ أَوْلِي[o[َا]ٓءَ‌ۘ يُضَ[n[ـٰ]عَفُ لَهُمُ [h:6283[ٱ]لْعَذَابُ‌ۚ مَا كَانُو[s[اْ] يَسْتَطِيعُونَ [h:6284[ٱ][l[ل]سَّمْعَ وَمَا كَانُو[s[اْ] يُ[q:60[بْ]صِر[p[ُو]نَ","Ана ўшалар ер юзида қочиб қутилувчи бўла олмадилар, уларга Аллоҳдан ўзга дўст ҳам бўлмади, азоб бир неча баробар қилинур. Улар эшитишга қодир бўла олмадилар ва кўра олмадилар ҳам.",224,12],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ خَسِر[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ وَضَلَّ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَفْتَر[p[ُو]نَ","Ана ўшалар ўзларига зиён қилганлардир ва тўқиган нарсалари улардан ғойиб бўлди.",224,12],["لَا جَرَمَ أَ[g[نّ]َهُمْ فِى [h:536[ٱ]لْأَخِرَةِ هُمُ [h:6285[ٱ]لْأَخْسَر[p[ُو]نَ","Шак-шубҳасиз, албатта, улар охиратда яна ҳам кўпроқ зиён кўргувчилардир.",224,12],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ وَأَخْبَت[o[ُوٓ][s[اْ] إِلَىٰ رَبِّهِمْ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:415[ٱ]لْجَ[g[نّ]َةِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Албатта, иймон келтирганлар, яхши амаллар қилганлар ва Роббиларига ишонч ила бўйинсунганлар, ана ўшалар жаннат эгаларидир. Улар унда абадий қолурлар.",224,12],["۞ مَثَلُ [h:6286[ٱ]لْفَرِيقَيْنِ كَ[h:6287[ٱ]لْأَعْمَىٰ وَ[h:6288[ٱ]لْأَصَ[g[مّ]ِ وَ[h:6289[ٱ]لْبَصِيرِ وَ[h:6290[ٱ][l[ل]سَّمِيعِ‌ۚ هَلْ يَسْتَوِيَانِ مَثَلاً‌ۚ أَفَلَا تَذَكَّر[p[ُو]نَ","Бу икки гуруҳнинг мисоли худди кару кўр ҳамда эшитувчи ва кўрувчига ўхшайдир. Улар бир-бирларига баробар бўла оладиларми? Ибрат олмайсизларми?",224,12],["وَلَقَ[q:341[دْ] أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِه[o[ِۦٓ] إِ[g[نّ]ِى لَكُمْ نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","Албатта, Биз Нуҳни ўз қавмига: «Албатта, мен сизларга очиқ-ойдин огоҳлантирувчиман.",224,12],["أ[u:4908[َن ل]َّا تَعْبُد[o[ُوٓ][s[اْ] إِلَّا [h:416[ٱ]للَّهَ‌ۖ إِ[g[نّ][o[ِىٓ] أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَل[p[ِي]مٍ","Аллоҳдан ўзгага ҳеч ибодат қилманглар, албатта, мен сизларга аламли кун азоби бўлишидан қўрқаман», дедириб юбордик.",224,12],["فَقَالَ [h:6291[ٱ]لْمَلَأُ [h:4783[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِ[f:4770[ن ق]َوْمِه[n[ِۦ] مَا نَرَ[n[ٮٰ]كَ إِلَّا بَشَ[a:6292[رًا م]ِّثْلَنَا وَمَا نَرَ[n[ٮٰ]كَ [h:6293[ٱ]تَّبَعَكَ إِلَّا [h:778[ٱ]لَّذِينَ هُمْ أَرَاذِلُنَا بَادِىَ [h:6294[ٱ][l[ل]رَّأْىِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِ[f:4682[ن ف]َضْ[i:6295[لِۭ ب]َلْ نَظُ[g[نّ]ُكُمْ كَ[n[ـٰ]ذِب[p[ِي]نَ","Унинг қавмидан куфр келтирган зодагонлар: «Биз сени ҳам фақат ўзимизга ўхшаган одам эканингни кўряпмиз, сенга ичимиздан эси паст пасткашларимизгина эргашаётганини кўряпмиз, сизларнинг биздан устун фазлингизни кўрмаяпмиз, балки сизларни ёлғончи деб ўйлаяпмиз», дедилар.",224,12],["قَالَ يَ[n[ـٰ]قَوْمِ أَرَءَيْتُمْ إِ[f:3898[ن ك]ُ[f:2917[نت]ُ عَلَىٰ بَيِّنَ[a:4097[ةٍ م]ّ[u:4098[ِن ر]َّبِّى وَءَاتَ[n[ـٰ]نِى رَحْمَ[a:5993[ةً م]ِّنْ عِ[f:3628[ند]ِه[n[ِۦ] فَعُ[g[مّ]ِيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَ[f:98[نت]ُمْ لَهَا كَ[n[ـٰ]رِه[p[ُو]نَ","У: «Эй қавмим, айтинг-чи, агар мен Роббимдан аниқ ҳужжатга эга бўлган бўлсам ва У менга Ўз ҳузуридан раҳмат берган бўлса-ю, сизга махфий қолган бўлса, уни сизга, агар ёқтирмасангиз ҳам, мажбурлаймизми?!",224,12],["وَيَ[n[ـٰ]قَوْمِ ل[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ مَالاً‌ۖ إِنْ أَ[q:6134[جْ]رِىَ إِلَّا عَلَى [h:412[ٱ]للَّهِ‌ۚ وَم[o[َآ] أَنَا۟ بِطَارِدِ [h:6296[ٱ]لَّذِينَ ءَامَن[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َه[w:6297[ُم م]ُّلَ[n[ـٰ]قُو[s[اْ] رَبِّهِمْ وَلَ[n[ـٰ]كِ[g[نّ][o[ِىٓ] أَرَ[n[ٮٰ]كُمْ قَوْ[f:6298[مًا ت]َ[q:4984[جْ]هَل[p[ُو]نَ","Эй қавмим, бу учун сиздан мол сўрамайман. Менинг ажрим фақат Аллоҳнинг зиммасида. Мен иймон келтирганларни қувловчи эмасман. Албатта, улар Роббиларига рўбарў бўлувчилардир. Аммо мен сизларнинг жоҳил қавм эканингизни кўрмоқдаман».",225,12],["وَيَ[n[ـٰ]قَوْمِ م[a:6299[َن ي]َ[f:6300[نص]ُرُنِى مِنَ [h:321[ٱ]للَّهِ إِ[f:6301[ن ط]َرَ[d:6302[د]تُّهُمْ‌ۚ أَفَلَا تَذَكَّر[p[ُو]نَ","Эй қавмим, агар уларни қувсам, ким менга Аллоҳдан ёрдам беради? Ўйлаб кўрмайсизларми?»",225,12],["وَل[o[َآ] أَقُولُ لَكُمْ عِ[f:4065[ند]ِى خَز[o[َا]ٓئِنُ [h:4066[ٱ]للَّهِ وَل[o[َآ] أَعْلَمُ [h:4067[ٱ]لْغَيْبَ وَل[o[َآ] أَقُولُ إِ[g[نّ]ِى مَلَ[a:6303[كٌ و]َل[o[َآ] أَقُولُ لِلَّذِينَ تَزْدَر[o[ِىٓ] أَعْيُنُكُمْ ل[a:6304[َن ي]ُؤْتِيَهُمُ [h:6305[ٱ]للَّهُ خَيْرًا‌ۖ [h:6306[ٱ]للَّهُ أَعْلَمُ بِمَا ف[o[ِىٓ] أَ[f:568[نف]ُسِهِمْ‌ۖ إِ[g[نّ][o[ِىٓ] إِ[u:765[ذًا ل]َّمِنَ [h:766[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Мен сизларга: «Ҳузуримда Аллоҳнинг хазиналари бор», демайман. Ғайбни ҳам билмайман. «Мен фариштаман», демайман. «Кўзингизга ҳақир кўринаётганларга Аллоҳ ҳаргиз яхшилик бермайди», демайман. Уларнинг дилларида нима борлигини Аллоҳ яхши биладир. Акс ҳолда, мен, албатта, золимлардан бўлиб қоламан», деди.",225,12],["قَالُو[s[اْ] يَ[n[ـٰ]نُوحُ قَ[q:298[دْ] جَ[n[ـٰ]دَلْتَنَا فَأَكْثَرْتَ جِد[n[َٲ]لَنَا فَأْتِنَا بِمَا تَعِدُن[o[َآ] إِ[f:4792[ن ك]ُ[f:735[نت]َ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","Улар: «Эй Нуҳ, батаҳқиқ, сен биз билан тортишдинг, кўп тортишдинг. Энди, агар ростгўйлардан бўлсанг, бизга ваъда қилаётган нарсангни келтир», дедилар.",225,12],["قَالَ إِ[g[نّ]َمَا يَأْتِيك[c:4058[ُم ب]ِهِ [h:1707[ٱ]للَّهُ إِ[f:364[ن ش][o[َا]ٓءَ وَم[o[َآ] أَ[f:428[نت][c:4435[ُم ب]ِمُعْجِز[p[ِي]نَ","У: «Уни сизларга, агар хоҳласа, фақат Аллоҳгина келтирур ва сизлар қочиб қутулувчи эмассиз.",225,12],["وَلَا يَ[f:6307[نف]َعُكُمْ نُصْح[o[ِىٓ] إِنْ أَرَ[d:6308[د]تُّ أَنْ أَ[f:6309[نص]َحَ لَكُمْ إِ[f:2594[ن ك]َانَ [h:742[ٱ]للَّهُ يُرِيدُ أ[a:6310[َن ي]ُغْوِيَكُمْ‌ۚ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَع[p[ُو]نَ","Ва агар Аллоҳ сизларни йўлдан оздиришни истаса, мен насиҳат қилишни хоҳлаганим билан насиҳатим сизларга манфаат бермайди. У сизнинг Роббингиздир ва Унга қайтарилурсиз», деди.",225,12],["أَمْ يَقُولُونَ [h:6061[ٱ]فْتَرَ[n[ٮٰ]هُ‌ۖ قُلْ إِنِ [h:6311[ٱ]فْتَرَيْتُهُ[n[ۥ] فَعَلَىَّ إِ[q:6312[جْ]رَامِى وَأَنَا۟ بَر[o[ِى]ٓ[a:3977[ءٌ م]ِّ[g[مّ]َا تُ[q:6313[جْ]رِم[p[ُو]نَ","Ёки: «Уни тўқиб олди», дейдиларми? Сен: «Агар уни тўқиб олган бўлсам, жиноятим ўз зиммамда ва мен сиз қилаётган жиноятдан холидирман», деб айт.",225,12],["وَأُوحِىَ إِلَىٰ نُوحٍ أَ[g[نّ]َهُ[n[ۥ] ل[a:6314[َن ي]ُؤْمِنَ مِ[f:6315[ن ق]َوْمِكَ إِلَّا مَ[f:6316[ن ق]َ[q:298[دْ] ءَامَنَ فَلَا تَ[q:6317[بْ]تَئِسْ بِمَا كَانُو[s[اْ] يَفْعَل[p[ُو]نَ","Ва Нуҳга: «Қавмингдан аввал иймон келтирганлардан бошқа ҳеч ким иймон келтирмас ва уларнинг қилмишларидан қайғуга тушмагин.",225,12],["وَ[h:9999[ٱ]صْنَعِ [h:6318[ٱ]لْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَ[n[ـٰ]طِ[q:6319[بْ]نِى فِى [h:6320[ٱ]لَّذِينَ ظَلَم[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َه[w:6321[ُم م]ُّغْرَق[p[ُو]نَ","Бизнинг риоятимиз ва ваҳиймиз ила кема ясагин ҳамда зулм қилганлар тўғрисида Менга гап очмагин, албатта, улар ғарқ бўлгувчилардир», деб ваҳий қилинди.",225,12],["وَيَصْنَعُ [h:6322[ٱ]لْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَ[a:6323[أٌ م]ِّ[f:4770[ن ق]َوْمِه[n[ِۦ] سَخِرُو[s[اْ] مِنْهُ‌ۚ قَالَ إِ[f:6324[ن ت]َسْخَرُو[s[اْ] مِ[g[نّ]َا فَإِ[g[نّ]َا نَسْخَرُ مِ[f:344[نك]ُمْ كَمَا تَسْخَر[p[ُو]نَ","У кема ясамоқда. Ўз қавмидан бўлган зодагонлар қачон олдидан ўтсалар, уни масхара қилдилар. У: «Агар бизни масхара қилсангиз, биз ҳам худди сиз бизни масхара қилганингиздек сизларни масхара қиламиз.",226,12],["فَسَوْفَ تَعْلَمُونَ م[a:6325[َن ي]َأْتِيهِ عَذَا[a:6326[بٌ ي]ُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَا[a:3534[بٌ م]ُّق[p[ِي]مٌ","Бас, яқинда кимга шарманда қилувчи азоб келишини ва кимнинг устига муқим азоб тушишини билиб олурсиз», деди.",226,12],["حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءَ أَمْرُنَا وَفَارَ [h:6327[ٱ][l[ل]تَّ[g[نّ]ُورُ قُلْنَا [h:6328[ٱ]حْمِلْ فِيهَا مِ[f:6329[ن ك]ُ[f:6330[لٍّ ز]َوْجَيْنِ [h:6331[ٱ]ثْنَيْنِ وَأَهْلَكَ إِلَّا مَ[f:6332[ن س]َبَقَ عَلَيْهِ [h:6333[ٱ]لْقَوْلُ وَمَنْ ءَامَنَ‌ۚ وَم[o[َآ] ءَامَنَ مَعَهُ[o[ۥٓ] إِلَّا قَل[p[ِي]لٌ","Токи Бизнинг амримиз келиб, таннур фаввора отганда: «Уга ҳар нарсадан бир жуфтдан ва аҳлингдан аввал сўз кетмаганини ва иймон келтирганларни ол», дедик. У билан бирга иймон келтирганлар жуда оз эди.",226,12],["۞ وَقَالَ [h:6334[ٱ]رْكَبُو[s[اْ] فِيهَا بِسْمِ [h:6335[ٱ]للَّهِ مَ[q:6336[جْ]ر۪[n[ٮٰ]هَا وَمُرْسَ[n[ـٰ]ه[o[َآ‌ۚ] إِ[g[نّ]َ رَبِّى لَغَفُو[u:4578[رٌ ر]َّح[p[ِي]مٌ","Ва у: «Кемага мининглар, унинг юриши ҳам, туриши ҳам Аллоҳнинг исми ила бўлур. Албатта, Роббим мағфиратли ва раҳмлидир», деди.",226,12],["وَهِىَ تَ[q:120[جْ]رِى بِهِمْ فِى مَوْ[f:6337[جٍ ك]َ[h:6338[ٱ]لْجِبَالِ وَنَادَىٰ نُوحٌ [h:6339[ٱ][q:6340[بْ]نَهُ[n[ۥ] وَكَانَ فِى مَعْزِ[a:6341[لٍ ي]َ[n[ـٰ]بُنَىَّ [h:6342[ٱ]رْكَ[d:6343[ب] [g[مّ]َعَنَا وَلَا تَك[a:6344[ُن م]َّعَ [h:6345[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Ва у уларни тоғлардек тўлқинда олиб кетаётганида, Нуҳ бир четда турган ўғлига: «Эй ўғлим, биз билан бирга мингин, кофирлар билан бирга бўлмагин», деди.",226,12],["قَالَ سَـَٔـاو[o[ِىٓ] إِلَىٰ جَبَ[a:6346[لٍ ي]َعْصِمُنِى مِنَ [h:4727[ٱ]لْم[o[َا]ٓءِ‌ۚ قَالَ لَا عَاصِمَ [h:6347[ٱ]لْيَوْمَ مِنْ أَمْرِ [h:6348[ٱ]للَّهِ إِلَّا م[u:6349[َن ر]َّحِمَ‌ۚ وَحَالَ بَيْنَهُمَا [h:6350[ٱ]لْمَوْجُ فَكَانَ مِنَ [h:6351[ٱ]لْمُغْرَق[p[ِي]نَ","У: «Тоққа жойлашиб олсам, мени сувдан сақлайдир», деди. У эса: «Бугун Аллоҳнинг амридан сақловчи йўқдир. Магар кимни раҳм қилсагина», деди. Шунда ораларини тўлқин тўсди ва у ғарқ бўлганлардан бўлди.",226,12],["وَقِيلَ يَ[o[ـٰٓ]أَرْضُ [h:6352[ٱ][q:6353[بْ]لَعِى م[o[َا]ٓءَكِ وَيَ[n[ـٰ]سَم[o[َا]ٓءُ أَ[q:6354[قْ]لِعِى وَغِيضَ [h:6355[ٱ]لْم[o[َا]ٓءُ وَقُضِىَ [h:1147[ٱ]لْأَمْرُ وَ[h:6356[ٱ]سْتَوَتْ عَلَى [h:6357[ٱ]لْجُودِىِّ‌ۖ وَقِيلَ بُعْ[u:6358[دًا ل]ِّلْقَوْمِ [h:6165[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","«Эй ер, сувингни ютгин, эй осмон, ўзингни тутгин», дейилди. Сув қуриди. Фармон бажарилди ва Жудий га жойлашди. Ҳамда «Золим қавмлар йўқолсин!» дейилди.",226,12],["وَنَادَىٰ نُو[u:6359[حٌ ر]َّبَّهُ[n[ۥ] فَقَالَ رَبِّ إِ[g[نّ]َ [h:6360[ٱ][q:6361[بْ]نِى مِنْ أَهْلِى وَإِ[g[نّ]َ وَعْدَكَ [h:6362[ٱ]لْحَقُّ وَأَ[f:3893[نت]َ أَحْكَمُ [h:6363[ٱ]لْحَ[n[ـٰ]كِم[p[ِي]نَ","Нуҳ Роббига нидо қилиб: «Роббим, албатта, ўғлим аҳлимдандир, албатта, ваъданг ҳақдир ва Сен ҳукм қилгувчиларнинг энг ҳикматлисисан», деди.",226,12],["قَالَ يَ[n[ـٰ]نُوحُ إِ[g[نّ]َهُ[n[ۥ] لَيْسَ مِنْ أَهْلِكَ‌ۖ إِ[g[نّ]َهُ[n[ۥ] عَمَلٌ غَيْرُ صَ[n[ـٰ]لِ[f:6364[حٍ‌ۖ ف]َلَا تَسْــَٔلْنِ مَا لَيْسَ لَكَ بِه[n[ِۦ] عِلْمٌ‌ۖ إِ[g[نّ][o[ِىٓ] أَعِظُكَ أَ[f:1566[ن ت]َكُونَ مِنَ [h:352[ٱ]لْجَ[n[ـٰ]هِل[p[ِي]نَ","У зот: «Эй Нуҳ, албатта у аҳлингдан эмас. Албатта, у яхши амал эмасдир. Ўзингнинг илминг бўлмаган нарсани зинҳор сўрамагин. Мен сенга жоҳиллардан бўлмаслигингни насиҳат қиламан», деди.",227,12],["قَالَ رَبِّ إِ[g[نّ][o[ِىٓ] أَعُوذُ بِكَ أَنْ أَسْــَٔلَكَ مَا لَيْسَ لِى بِه[n[ِۦ] عِلْ[a:6365[مٌ‌ۖ و]َإِلَّا تَغْفِرْ لِى وَتَرْحَمْن[o[ِىٓ] أَك[a:6366[ُن م]ِّنَ [h:340[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","У: «Роббим, мен ўзимнинг илмим бўлмаган нарсани сендан сўрамоқдан паноҳ тилайман. Агар мени мағфират қилмасанг ва менга раҳм кўрсатмасанг, зиён кўргувчилардан бўламан», деди.",227,12],["قِيلَ يَ[n[ـٰ]نُوحُ [h:6367[ٱ]هْبِ[q:6368[طْ] بِسَلَ[n[ـٰ][a:6369[مٍ م]ِّ[g[نّ]َا وَبَرَكَ[n[ـٰ]تٍ عَلَيْكَ وَعَلَ[o[ىٰٓ] أُمَ[a:6370[مٍ م]ِّ[g[مّ][a:6371[َن م]َّعَكَ‌ۚ وَأُمَ[f:6372[مٌ س]َنُمَتِّعُهُمْ ثُ[g[مّ]َ يَمَسُّه[w:6373[ُم م]ِّ[g[نّ]َا عَذَابٌ أَل[p[ِي]مٌ","«Эй Нуҳ, Биздан сенга ва сен билан бирга бўлган умматларга бўлган тинчлик ва баракотлар ила тушгин. Яна бир умматлар бўлур, уларни бир оз ҳузурлантирурмиз, сўнгра уларни биздан бўлган аламли азоб тутар», дейилди.",227,12],["تِلْكَ مِنْ أَ[i:1910[نۢب][o[َا]ٓءِ [h:1911[ٱ]لْغَيْبِ نُوحِيه[o[َآ] إِلَيْكَ‌ۖ مَا كُ[f:735[نت]َ تَعْلَمُه[o[َآ] أَ[f:169[نت]َ وَلَا قَوْمُكَ مِ[f:1346[ن ق]َ[q:1347[بْ]لِ هَ[n[ـٰ]ذَا‌ۖ فَ[h:6374[ٱ]صْبِرْ‌ۖ إِ[g[نّ]َ [h:6375[ٱ]لْعَ[n[ـٰ]قِبَةَ لِلْمُتَّق[p[ِي]نَ","Ана шу ғайб хабарларини сенга ваҳий қилмоқдамиз. Бундан олдин уларни сен ҳам билмас эдинг ва сенинг қавминг ҳам. Бас, сабр қил, албатта, оқибат тақводорларникидир.",227,12],["وَإِلَىٰ عَادٍ أَخَاهُمْ هُو[f:4782[دًا‌ۚ ق]َالَ يَ[n[ـٰ]قَوْمِ [h:4768[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ مَا لَك[w:556[ُم م]ِّنْ إِلَ[n[ـٰ]هٍ غَيْرُهُ[o[ۥٓ‌ۖ] إِنْ أَ[f:428[نت]ُمْ إِلَّا مُفْتَر[p[ُو]نَ","Ва Одга ўз биродарлари Ҳудни. У: «Эй қавмим, Аллоҳга ибодат қилинг. Сиз учун ундан ўзга илоҳ йўқдир. Сизлар фақат тўқиб олувчиларсиз, холос.",227,12],["يَ[n[ـٰ]قَوْمِ ل[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ أَ[q:2795[جْ]رًا‌ۖ إِنْ أَ[q:6134[جْ]رِىَ إِلَّا عَلَى [h:4534[ٱ]لَّذِى فَطَرَن[o[ِىٓ‌ۚ] أَفَلَا تَعْقِل[p[ُو]نَ","Эй қавмим, мен сизлардан бу учун ажр сўрамайман. Менинг ажрим фақат мени яратган зотнинг зиммасидадир. Ақл юритмайсизларми?",227,12],["وَيَ[n[ـٰ]قَوْمِ [h:6376[ٱ]سْتَغْفِرُو[s[اْ] رَبَّكُمْ ثُ[g[مّ]َ تُوب[o[ُوٓ][s[اْ] إِلَيْهِ يُرْسِلِ [h:6377[ٱ][l[ل]سَّم[o[َا]ٓءَ عَلَيْك[w:6378[ُم م]ِّ[q:3932[دْ]رَا[a:6379[رًا و]َيَزِ[q:6380[دْ]كُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْ[s[اْ] مُ[q:4958[جْ]رِم[p[ِي]نَ","Эй қавмим, Роббингизга истиғфор айтинг, сўнгра Унга тавба қилинг, шунда У устингизга осмондан барака ёмғири юборади ва қувватингизга қувватни зиёда қилади. Жиноятчи бўлган ҳолингизда юз ўгириб кетманг», деди.",227,12],["قَالُو[s[اْ] يَ[n[ـٰ]هُودُ مَا جِئْتَنَا بِبَيِّنَ[a:6381[ةٍ و]َمَا نَحْنُ بِتَارِك[o[ِىٓ] ءَالِهَتِنَا عَ[f:6382[ن ق]َوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِن[p[ِي]نَ","Улар: «Эй Ҳуд, бизга очиқ-ойдин ҳужжат келтирмадинг. Биз сенинг гапинг учун худоларимизни тарк қилувчи эмасмиз ва биз сенга иймон келтирувчи ҳам эмасмиз.",227,12],["إ[a:6383[ِن ن]َّقُولُ إِلَّا [h:6384[ٱ]عْتَرَ[n[ٮٰ]كَ بَعْضُ ءَالِهَتِنَا بِس[o[ُو]ٓ[f:6385[ءٍ‌ۗ ق]َالَ إِ[g[نّ][o[ِىٓ] أُشْهِدُ [h:6386[ٱ]للَّهَ وَ[h:6387[ٱ]شْهَد[o[ُوٓ][s[اْ] أَ[g[نّ]ِى بَر[o[ِى]ٓ[a:3977[ءٌ م]ِّ[g[مّ]َا تُشْرِك[p[ُو]نَ","Биз фақат, сени баъзи худоларимиз ёмонлик ила урибди, деймиз, холос», дедилар. У: «Албатта, мен Аллоҳни гувоҳ қиламан ва сиз ҳам гувоҳ бўлингки, мен шерик келтираётганингиздан покман.",228,12],["مِ[f:3136[ن د]ُونِه[n[ِۦ]‌ۖ فَكِيدُونِى جَمِي[f:155[عًا ث]ُ[g[مّ]َ لَا تُ[f:5200[نظ]ِر[p[ُو]نِ","Ундан ўзгани. Бас, ҳаммангиз менга қарши ҳийла қилаверинглар, менга муҳлат берманглар.",228,12],["إِ[g[نّ]ِى تَوَكَّلْتُ عَلَى [h:412[ٱ]للَّهِ رَبِّى وَرَبِّك[w:6388[ُم‌ۚ م]َّا مِ[f:4026[ن د][m[َا]ٓبَّةٍ إِلَّا هُوَ ءَاخِ[i:6389[ذُۢ ب]ِنَاصِيَتِه[o[َآ‌ۚ] إِ[g[نّ]َ رَبِّى عَلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Албатта, мен Роббим ва Роббингиз бўлмиш Аллоҳга таваккал қилдим. Ҳар бир ўрмалайдиган нарсанинг пешонаси Унинг чангалидадир. Албатта, Роббим тўғри йўлдадир.",228,12],["فَإِ[f:1857[ن ت]َوَلَّوْ[s[اْ] فَقَ[q:563[دْ] أَ[q:4825[بْ]لَغْتُك[w:6390[ُم م]ّ[o[َآ] أُرْسِلْتُ بِه[o[ِۦٓ] إِلَيْكُمْ‌ۚ وَيَسْتَخْلِفُ رَبِّى قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُ[n[ۥ] شَيْــًٔا‌ۚ إِ[g[نّ]َ رَبِّى عَلَىٰ كُلِّ شَىْءٍ حَف[p[ِي]ظٌ","Агар юз ўгириб кетсангиз, батаҳқиқ, мен сизларга нима ила юборилган бўлсам, уни сизларга етказдим. Роббим ўрнингизга сиздан бошқа қавмни келтиради ва сиз Унга ҳеч бир зарар етказа олмассиз. Албатта, Роббим ҳар бир нарсани муҳофаза қилгувчи зотдир», деди.",228,12],["وَلَ[g[مّ]َا ج[o[َا]ٓءَ أَمْرُنَا نَجَّيْنَا هُو[a:6391[دًا و]َ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مَعَهُ[n[ۥ] بِرَحْمَ[a:4803[ةٍ م]ِّ[g[نّ]َا وَنَجَّيْنَ[n[ـٰ]ه[w:6392[ُم م]ِّنْ عَذَابٍ غَل[p[ِي]ظٍ","Амримиз келган пайтда Ҳудга ва у билан бирга иймон келтирганларга раҳматимиз ила нажот бердик ва уларни қаттиқ азобдан қутқардик.",228,12],["وَتِلْكَ عَا[f:6393[دٌ‌ۖ ج]َحَدُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ رَبِّهِمْ وَعَصَوْ[s[اْ] رُسُلَهُ[n[ۥ] وَ[h:2433[ٱ]تَّبَع[o[ُوٓ][s[اْ] أَمْرَ كُلِّ جَبَّارٍ عَن[p[ِي][q[د]ٍ","Анави Оддир. Улар Роббилари оятларини инкор қилдилар. Унинг Пайғамбарларига осий бўлдилар. Ҳар хил жабрчи ва қайсарнинг ишига эргашдилар.",228,12],["وَأُتْبِعُو[s[اْ] فِى هَ[n[ـٰ]ذِهِ [h:5052[ٱ][l[ل]دُّنْيَا لَعْنَ[a:6394[ةً و]َيَوْمَ [h:443[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۗ أَل[o[َآ] إِ[g[نّ]َ عَا[f:6395[دًا ك]َفَرُو[s[اْ] رَبَّهُمْ‌ۗ أَلَا بُعْ[u:6396[دًا ل]ِّعَا[f:6397[دٍ ق]َوْمِ ه[p[ُو][q[د]ٍ","Ва уларга бу дунёда ҳам, қиёмат кунида ҳам лаънат эргашур. Огоҳ бўлингким, албатта, Одликлар Роббиларига куфр келтирган эдилар. Огоҳ бўлингким, Ҳуд қавми Од йўқолсин-е!",228,12],["۞ وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَ[n[ـٰ]لِ[f:4805[حًا‌ۚ ق]َالَ يَ[n[ـٰ]قَوْمِ [h:4768[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ مَا لَك[w:556[ُم م]ِّنْ إِلَ[n[ـٰ]هٍ غَيْرُهُ[n[ۥ]‌ۖ هُوَ أَ[f:4272[نش]َأَك[w:6398[ُم م]ِّنَ [h:1579[ٱ]لْأَرْضِ وَ[h:6399[ٱ]سْتَعْمَرَكُمْ فِيهَا فَ[h:6400[ٱ]سْتَغْفِرُوهُ ثُ[g[مّ]َ تُوب[o[ُوٓ][s[اْ] إِلَيْهِ‌ۚ إِ[g[نّ]َ رَبِّى قَرِي[a:6401[بٌ م]ُّج[p[ِي][q[ب]ٌ","Ва Самудга биродарлари Солиҳни. У: «Эй қавмим, Аллоҳга ибодат қилинг. Сиз учун Ундан ўзга илоҳ йўқ. У сизларни ердан пайдо қилди ва унга сизни ободлиги учун қўйди. Бас, Унга истиғфор айтинг, сўнгра Унга тавба қилинг. Албатта, Роббим яқин ва ижобат қилгувчидир», деди.",228,12],["قَالُو[s[اْ] يَ[n[ـٰ]صَ[n[ـٰ]لِحُ قَ[q:298[دْ] كُ[f:735[نت]َ فِينَا مَرْجُو[f:6402[ًّا ق]َ[q:3282[بْ]لَ هَ[n[ـٰ]ذ[o[َآ‌ۖ] أَتَنْهَ[n[ـٰ]ن[o[َآ] أ[a:6403[َن ن]َّعْبُدَ مَا يَعْبُدُ ءَاب[o[َا]ٓؤُنَا وَإِ[g[نّ]َنَا لَفِى شَ[a:6196[كٍّ م]ِّ[g[مّ]َا تَ[q:6404[دْ]عُون[o[َآ] إِلَيْهِ مُر[p[ِي][q[ب]ٍ","Улар: «Эй Солиҳ, бундан олдин сен ичимизда орзу қилинган эдинг. Энди бизни ота-боболаримиз ибодат қиладиган нарсага ибодат қилмоғимиздан қайтарасанми? Албатта, биз сен даъват қилаётган нарса ҳақида шак-шубҳадамиз», дедилар.",228,12],["قَالَ يَ[n[ـٰ]قَوْمِ أَرَءَيْتُمْ إِ[f:3898[ن ك]ُ[f:2917[نت]ُ عَلَىٰ بَيِّنَ[a:4097[ةٍ م]ّ[u:4098[ِن ر]َّبِّى وَءَاتَ[n[ـٰ]نِى مِنْهُ رَحْمَ[f:6405[ةً ف]َم[a:6406[َن ي]َ[f:6300[نص]ُرُنِى مِنَ [h:321[ٱ]للَّهِ إِنْ عَصَيْتُهُ[n[ۥ]‌ۖ فَمَا تَزِيدُونَنِى غَيْرَ تَخْس[p[ِي]رٍ","У: «Эй қавмим, хабар беринг-чи, агар мен Роббим томонидан очиқ-ойдин ҳужжатга эга бўлсам ва менга У томонидан раҳмат берилган бўлса-ю, мен Унга осий бўлсам, ким менга Аллоҳ дан ёрдам беради?! Бас, сиз менга зиёндан ўзгани зиёда қилмайсизлар.",229,12],["وَيَ[n[ـٰ]قَوْمِ هَ[n[ـٰ]ذِه[n[ِۦ] نَاقَةُ [h:4807[ٱ]للَّهِ لَكُمْ ءَايَ[f:4808[ةً ف]َذَرُوهَا تَأْكُلْ ف[o[ِىٓ] أَرْضِ [h:4809[ٱ]للَّهِ وَلَا تَمَسُّوهَا بِس[o[ُو]ٓ[f:4810[ءٍ ف]َيَأْخُذَكُمْ عَذَا[f:6407[بٌ ق]َر[p[ِي][q[ب]ٌ","Эй қавмим, Аллоҳнинг мана бу туяси сизга оят-мўъжизадир. Бас, уни тек қўйинглар, Аллоҳнинг ерида еб юрсин, унга ёмонлик етказманглар, акс ҳолда, сизни яқин азоб ушлайди», деди.",229,12],["فَعَقَرُوهَا فَقَالَ تَمَتَّعُو[s[اْ] فِى دَارِكُمْ ثَلَ[n[ـٰ]ثَةَ أَيَّا[f:3759[مٍ‌ۖ ذ][n[َٲ]لِكَ وَعْدٌ غَيْرُ مَكْذ[p[ُو][q[ب]ٍ","Бас, уни сўйдилар. Сўнг У: «Диёрингизда уч кун баҳраманд бўлиб туринг. Бу ёлғон бўлмаган ваъдадир», деди.",229,12],["فَلَ[g[مّ]َا ج[o[َا]ٓءَ أَمْرُنَا نَجَّيْنَا صَ[n[ـٰ]لِ[a:6408[حًا و]َ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مَعَهُ[n[ۥ] بِرَحْمَ[a:4803[ةٍ م]ِّ[g[نّ]َا وَمِنْ خِزْىِ يَوْمِئِذٍ‌ۗ إِ[g[نّ]َ رَبَّكَ هُوَ [h:6409[ٱ]لْقَوِىُّ [h:6410[ٱ]لْعَز[p[ِي]زُ","Амримиз келган пайтда раҳматимиз ила Солиҳга ва у билан бирга иймон келтирганларга нажот бердик ва ўша куннинг шармандалигидан қутқардик. Албатта, Роббинг, Унинг Ўзи кучли ва азиздир.",229,12],["وَأَخَذَ [h:6411[ٱ]لَّذِينَ ظَلَمُو[s[اْ] [h:6412[ٱ][l[ل]صَّيْحَةُ فَأَصْبَحُو[s[اْ] فِى دِيَ[n[ـٰ]رِهِمْ جَ[n[ـٰ]ثِم[p[ِي]نَ","Ва зулм қилганларни даҳшатли қичқириқ олди. Бас, диёрларида тўкилдилар.",229,12],["كَأ[u:2914[َن ل]َّمْ يَغْنَوْ[s[اْ] فِيه[o[َآ‌ۗ] أَل[o[َآ] إِ[g[نّ]َ ثَمُودَ[s[اْ] كَفَرُو[s[اْ] رَبَّهُمْ‌ۗ أَلَا بُعْ[u:6413[دًا ل]ِّثَم[p[ُو][q[د]َ","Худди унда турмаганга ўхшаб. Огоҳ бўлингким, албатта, Самуд Роббиларига куфр келтирган эдилар. Огоҳ бўлингким, Самуд йўқолсин-е!",229,12],["وَلَقَ[q:341[دْ] ج[o[َا]ٓءَتْ رُسُلُن[o[َآ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ بِ[h:6414[ٱ]لْبُشْرَىٰ قَالُو[s[اْ] سَلَ[n[ـٰ][f:6415[مًا‌ۖ ق]َالَ سَلَ[n[ـٰ][f:6416[مٌ‌ۖ ف]َمَا لَبِثَ أَ[f:6417[ن ج][o[َا]ٓءَ بِعِ[q:6418[جْ]لٍ حَن[p[ِي]ذٍ","Батаҳқиқ, элчиларимиз Иброҳимга хушхабар келтирдилар. Улар: «Салом», дедилар. У: «Салом», деди. Ва кўп ўтмай қовурилган бузоқ келтирди.",229,12],["فَلَ[g[مّ]َا رَء[o[َآ] أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَ[f:6419[ةً‌ۚ ق]َالُو[s[اْ] لَا تَخَفْ إِ[g[نّ][o[َآ] أُرْسِلْن[o[َآ] إِلَىٰ قَوْمِ ل[p[ُو][q[ط]ٍ","Уларнинг қўллари уга етмаётганини кўриб, улардан ҳайрон бўлди ва ичида хавфсиради. Улар: «Қўрқма, биз Лут қавмига юборилганмиз», дедилар.",229,12],["وَ[h:9999[ٱ]مْرَأَتُهُ[n[ۥ] ق[o[َا]ٓئِمَ[f:6420[ةٌ ف]َضَحِكَتْ فَبَشَّرْنَ[n[ـٰ]هَا بِإِسْحَ[n[ـٰ]قَ وَم[a:6421[ِن و]َر[o[َا]ٓءِ إِسْحَ[n[ـٰ]قَ يَعْق[p[ُو][q[ب]َ","Тик турган хотини кулди. Бас, Биз уга Исҳоқнинг ва Исҳоқдан кейин Яъқубнинг хушхабарини бердик.",229,12],["قَالَتْ يَ[n[ـٰ]وَيْلَتَ[o[ىٰٓ] ءَأَلِدُ وَأَنَا۟ عَجُو[a:6422[زٌ و]َهَ[n[ـٰ]ذَا بَعْلِى شَيْخًا‌ۖ إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَشَىْءٌ عَج[p[ِي][q[ب]ٌ","У: «Вой шўрим, ўзим кампир, манави эрим чол бўлса ҳам, туғаманми?! Бу қизиқ нарса-ку!» деди.",230,12],["قَال[o[ُوٓ][s[اْ] أَتَعْجَبِينَ مِنْ أَمْرِ [h:6348[ٱ]للَّهِ‌ۖ رَحْمَتُ [h:6423[ٱ]للَّهِ وَبَرَكَ[n[ـٰ]تُهُ[n[ۥ] عَلَيْكُمْ أَهْلَ [h:6424[ٱ]لْبَيْتِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] حَمِي[a:6425[دٌ م]َّج[p[ِي][q[د]ٌ","Улар: «Аллоҳнинг амридан ажабланасанми? Эй аҳли байтлар, сизларга Аллоҳнинг раҳмати ва баракотлари бўлгай. Албатта, У мақталган ва буюк зотдир», дедилар.",230,12],["فَلَ[g[مّ]َا ذَهَبَ عَنْ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ [h:6426[ٱ][l[ل]رَّوْعُ وَج[o[َا]ٓءَتْهُ [h:6427[ٱ]لْبُشْرَىٰ يُجَ[n[ـٰ]دِلُنَا فِى قَوْمِ ل[p[ُو][q[ط]ٍ","Иброҳимдан қўрқинч кетиб, хушхабар етгач, Биз билан Лут қавми ҳақида баҳслаша бошлади.",230,12],["إِ[g[نّ]َ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ لَحَلِيمٌ أَوّ[n[َٲ][a:6428[هٌ م]ُّن[p[ِي][q[ب]ٌ","Албатта, Иброҳим ҳалийм, тазарруъли ва тез қайтувчидир.",230,12],["يَ[o[ـٰٓ]إِ[q:6429[بْ]ر[n[َٲ]هِيمُ أَعْرِضْ عَنْ هَ[n[ـٰ]ذ[o[َآ‌ۖ] إِ[g[نّ]َهُ[n[ۥ] قَ[q:298[دْ] ج[o[َا]ٓءَ أَمْرُ رَبِّكَ‌ۖ وَإِ[g[نّ]َهُمْ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْد[p[ُو][q[د]ٍ","«Эй Иброҳим, бундан воз кеч. Чунки Роббингнинг амри келиб бўлган. Албатта, уларга қайтарилмас азоб келгусидир», дейишди.",230,12],["وَلَ[g[مّ]َا ج[o[َا]ٓءَتْ رُسُلُنَا لُو[f:6430[طًا س][o[ِى]ٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْ[a:6431[عًا و]َقَالَ هَ[n[ـٰ]ذَا يَوْمٌ عَص[p[ِي][q[ب]ٌ","Элчиларимиз Лутга келган пайтларида, у уларни ёмон ҳолга тушди ва қўл-оёғи бўшашди ҳамда: «Бу қийин кундир», деди.",230,12],["وَج[o[َا]ٓءَهُ[n[ۥ] قَوْمُهُ[n[ۥ] يُهْرَعُونَ إِلَيْهِ وَمِ[f:6432[ن ق]َ[q:129[بْ]لُ كَانُو[s[اْ] يَعْمَلُونَ [h:2655[ٱ][l[ل]سَّيِّـَٔـاتِ‌ۚ قَالَ يَ[n[ـٰ]قَوْمِ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ بَنَاتِى هُ[g[نّ]َ أَ[q:6433[طْ]هَرُ لَكُمْ‌ۖ فَ[h:112[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَلَا تُخْزُونِ فِى ضَيْف[o[ِىٓ‌ۖ] أَلَيْسَ مِ[f:344[نك]ُمْ رَجُ[u:6434[لٌ ر]َّش[p[ِي][q[د]ٌ","Қавми унга шошилиб, ҳаллослаб етиб келди. Улар бундан олдин гуноҳлар қилар эдилар. У: «Эй қавмим, анаву қизларим сизлар учун покроқ-ку. Бас, Аллоҳдан қўрқинг! Меҳмонларим ҳақида мени шарманда қилманг. Ичингизда бирорта тузукроқ одам йўқми?!» деди.",230,12],["قَالُو[s[اْ] لَقَ[q:2389[دْ] عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَ[a:6435[قٍّ و]َإِ[g[نّ]َكَ لَتَعْلَمُ مَا نُر[p[ِي][q[د]ُ","Улар: «Сенинг қизларингда бизнинг ҳаққимиз йўқлигини билгансан ва биз нимани хоҳлашимизни, албатта, сен биласан», дедилар.",230,12],["قَالَ لَوْ أَ[g[نّ]َ لِى بِكُمْ قُوَّةً أَوْ ءَاو[o[ِىٓ] إِلَىٰ رُكْ[f:6436[نٍ ش]َد[p[ِي][q[د]ٍ","У: «Қани энди сизларга қувватим етса эди ёки мустаҳкам ерга беркинсайдим», деди.",230,12],["قَالُو[s[اْ] يَ[n[ـٰ]لُوطُ إِ[g[نّ]َا رُسُلُ رَبِّكَ ل[a:6437[َن ي]َصِل[o[ُوٓ][s[اْ] إِلَيْكَ‌ۖ فَأَسْرِ بِأَهْلِكَ بِقِ[q:6438[طْ][a:6439[عٍ م]ِّنَ [h:6029[ٱ]لَّيْلِ وَلَا يَلْتَفِتْ مِ[f:344[نك]ُمْ أَحَدٌ إِلَّا [h:6440[ٱ]مْرَأَتَكَ‌ۖ إِ[g[نّ]َهُ[n[ۥ] مُصِيبُهَا م[o[َآ] أَصَابَهُمْ‌ۚ إِ[g[نّ]َ مَوْعِدَهُمُ [h:6441[ٱ][l[ل]صُّ[q:6442[بْ]حُ‌ۚ أَلَيْسَ [h:6443[ٱ][l[ل]صُّ[q:6442[بْ]حُ بِقَر[p[ِي][q[ب]ٍ","Улар: «Эй Лут, биз Роббингнинг элчиларимиз, булар сенга ҳаргиз тега олмаслар. Бас, кечанинг бир бўлагида аҳлинг ила юргин ва сизлардан хотинингдан бошқа ҳеч ким ўгирилмасин. Чунки уларга етадиган мусибат у га-да етгувчидир. Уларга тайин қилинган вақт субҳдир. Субҳ яқин эмасми?!» дедилар.",230,12],["فَلَ[g[مّ]َا ج[o[َا]ٓءَ أَمْرُنَا جَعَلْنَا عَ[n[ـٰ]لِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَ[a:6444[ةً م]ِّ[f:6445[ن س]ِجِّي[a:6446[لٍ م]َّ[f:6447[نض][p[ُو][q[د]ٍ","Амримиз келган пайтда у ўлкани остин-устун қилдик ва устидан кетма-кет сопол тошларни ёғдирдик.",231,12],["مُّسَوَّمَةً عِ[f:264[ند]َ رَبِّكَ‌ۖ وَمَا هِىَ مِنَ [h:187[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ بِبَع[p[ِي][q[د]ٍ","Уларга Роббинг ҳузурида белги қўйилган эди ва улар золимлардан узоқ эмасдир.",231,12],["۞ وَإِلَىٰ مَ[q:4842[دْ]يَنَ أَخَاهُمْ شُعَيْ[f:4843[بًا‌ۚ ق]َالَ يَ[n[ـٰ]قَوْمِ [h:4768[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ مَا لَك[w:556[ُم م]ِّنْ إِلَ[n[ـٰ]هٍ غَيْرُهُ[n[ۥ]‌ۖ وَلَا تَ[f:6448[نق]ُصُو[s[اْ] [h:6449[ٱ]لْمِكْيَالَ وَ[h:4528[ٱ]لْمِيزَانَ‌ۚ إِ[g[نّ][o[ِىٓ] أَرَ[n[ٮٰ]ك[c:6450[ُم ب]ِخَيْ[a:6451[رٍ و]َإِ[g[نّ][o[ِىٓ] أَخَافُ عَلَيْكُمْ عَذَابَ يَوْ[a:6452[مٍ م]ُّح[p[ِي][q[ط]ٍ","Ва Мадянга биродарлари Шуайбни. У: «Эй қавмим, Аллоҳга ибодат қилинг, сиз учун Ундан ўзга илоҳ йўқ. Ўлчовни ва тортишни камайтирманглар. Албатта, мен сизларнинг яхшиликда эканликларингизни кўриб турибман. Албатта, мен сизларга қамровли кун азобидан қўрқмоқдаман.",231,12],["وَيَ[n[ـٰ]قَوْمِ أَوْفُو[s[اْ] [h:6453[ٱ]لْمِكْيَالَ وَ[h:4528[ٱ]لْمِيزَانَ بِ[h:1800[ٱ]لْقِسْطِ‌ۖ وَلَا تَ[q:4845[بْ]خَسُو[s[اْ] [h:4846[ٱ][l[ل][g[نّ]َاسَ أَشْي[o[َا]ٓءَهُمْ وَلَا تَعْثَوْ[s[اْ] فِى [h:44[ٱ]لْأَرْضِ مُفْسِد[p[ِي]نَ","Эй қавмим, ўлчаш ва тортишни адолат ила мукаммал қилинг. Одамларнинг нарсаларини камайтириб қолманг ва ер юзида бузғунчилик қилиб юрманг.",231,12],["بَقِيَّتُ [h:6454[ٱ]للَّهِ خَيْ[u:263[رٌ ل]َّكُمْ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِنِينَ‌ۚ وَم[o[َآ] أَنَا۟ عَلَيْك[c:4313[ُم ب]ِحَف[p[ِي]ظٍ","Агар мўмин бўлсангиз, Аллоҳнинг наздида боқий қолувчи сиз учун яхшироқдир. Мен сизнинг устингизда қўриқчи эмасман», деди.",231,12],["قَالُو[s[اْ] يَ[n[ـٰ]شُعَيْبُ أَصَلَ[s[و][n[ٲ]تُكَ تَأْمُرُكَ أ[a:6455[َن ن]َّتْرُكَ مَا يَعْبُدُ ءَاب[o[َا]ٓؤُن[o[َآ] أَوْ أ[a:6456[َن ن]َّفْعَلَ ف[o[ِىٓ] أَمْو[n[َٲ]لِنَا مَا نَشَ[o[ـٰٓ]ؤُ[s[اْ]‌ۖ إِ[g[نّ]َكَ لَأَ[f:6457[نت]َ [h:6458[ٱ]لْحَلِيمُ [h:6459[ٱ][l[ل]رَّش[p[ِي][q[د]ُ","Улар: «Эй Шуайб, сенга бизнинг оталаримиз ибодат қиладиган нарсани тарк қилмоғимизни ёки молларимизда хоҳлаганимизни қилмаслигимизни намозинг амр қилмоқдами?! Сен жуда ҳалийм ва рашид экансан-да», дедилар.",231,12],["قَالَ يَ[n[ـٰ]قَوْمِ أَرَءَيْتُمْ إِ[f:3898[ن ك]ُ[f:2917[نت]ُ عَلَىٰ بَيِّنَ[a:4097[ةٍ م]ّ[u:4098[ِن ر]َّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَ[a:6460[نًا‌ۚ و]َم[o[َآ] أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ م[o[َآ] أَنْهَ[n[ـٰ]كُمْ عَنْهُ‌ۚ إِنْ أُرِيدُ إِلَّا [h:6461[ٱ]لْإِصْلَ[n[ـٰ]حَ مَا [h:6462[ٱ]سْتَطَعْتُ‌ۚ وَمَا تَوْفِيق[o[ِىٓ] إِلَّا بِ[h:32[ٱ]للَّهِ‌ۚ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُن[p[ِي][q[ب]ُ","У: «Эй қавмим, хабар беринглар-чи, агар мен Роббимдан аниқ ҳужжатга эга бўлсам-чи ва мени Ўзи тарафидан яхши ризқ ила ризқлантирган бўлса-чи?! Мен сизларни ўзим қайтараётган нарсада ўзим хилоф қилмоқчи эмасман. Мен имконим борича ислоҳ қилишдан ўзга ҳеч нарсани хоҳламасман. Менинг муваффақиятим фақат Аллоҳга боғлиқ. Унгагина таваккал қилдим. Унгагина қайтаман.",231,12],["وَيَ[n[ـٰ]قَوْمِ لَا يَ[q:3360[جْ]رِمَ[g[نّ]َكُمْ شِقَاق[o[ِىٓ] أ[a:6463[َن ي]ُصِيبَك[w:6464[ُم م]ِّثْلُ م[o[َآ] أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَ[n[ـٰ]لِ[a:6465[حٍ‌ۚ و]َمَا قَوْمُ لُو[a:6466[طٍ م]ِّ[f:344[نك][c:6467[ُم ب]ِبَع[p[ِي][q[د]ٍ","Эй қавмим, менга хилоф қилишингиз сизларни ё Нуҳ қавмига, ё Ҳуд қавмига, ёки Солиҳ қавмига етган мусибатга ўхшаш мусибат етишига олиб бормасин. Лут қавми сизлардан узоқ эмас.",232,12],["وَ[h:9999[ٱ]سْتَغْفِرُو[s[اْ] رَبَّكُمْ ثُ[g[مّ]َ تُوب[o[ُوٓ][s[اْ] إِلَيْهِ‌ۚ إِ[g[نّ]َ رَبِّى رَحِي[a:6468[مٌ و]َد[p[ُو][q[د]ٌ","Роббингизга истиғфор айтинг, сўнгра Унга тавба қилинг. Албатта, Роббим раҳмли ва шафқатли зотдир», деди.",232,12],["قَالُو[s[اْ] يَ[n[ـٰ]شُعَيْبُ مَا نَفْقَهُ كَثِي[a:3437[رًا م]ِّ[g[مّ]َا تَقُولُ وَإِ[g[نّ]َا لَنَرَ[n[ٮٰ]كَ فِينَا ضَعِي[a:6469[فًا‌ۖ و]َلَوْلَا رَهْطُكَ لَرَجَمْنَ[n[ـٰ]كَ‌ۖ وَم[o[َآ] أَ[f:169[نت]َ عَلَيْنَا بِعَز[p[ِي]زٍ","Улар: «Эй Шуайб, айтганларингнинг кўпини яхши тушунмадик ва биз сени ичимизда заифҳол кўряпмиз, агар одамларинг бўлмаганида, сени тошбўрон қилар эдик. Сенинг ўзинг биз учун қимматли эмассан», дедилар.",232,12],["قَالَ يَ[n[ـٰ]قَوْمِ أَرَهْط[o[ِىٓ] أَعَزُّ عَلَيْك[w:1301[ُم م]ِّنَ [h:321[ٱ]للَّهِ وَ[h:6470[ٱ]تَّخَذْتُمُوهُ وَر[o[َا]ٓءَكُمْ ظِهْرِيًّا‌ۖ إِ[g[نّ]َ رَبِّى بِمَا تَعْمَلُونَ مُح[p[ِي][q[ط]ٌ","У: «Эй қавмим, менинг одамларим сизлар учун Аллоҳдан кўра азизроқми?! Унга орқангизни ўгириб олдингиз. Албатта, Роббим қилаётган амалларингизни иҳота қилувчидир.",232,12],["وَيَ[n[ـٰ]قَوْمِ [h:6471[ٱ]عْمَلُو[s[اْ] عَلَىٰ مَكَانَتِكُمْ إِ[g[نّ]ِى عَ[n[ـٰ]مِ[f:6472[لٌ‌ۖ س]َوْفَ تَعْلَمُونَ م[a:6325[َن ي]َأْتِيهِ عَذَا[a:6326[بٌ ي]ُخْزِيهِ وَمَنْ هُوَ كَ[n[ـٰ]ذِ[a:6473[بٌ‌ۖ و]َ[h:6474[ٱ]رْتَقِب[o[ُوٓ][s[اْ] إِ[g[نّ]ِى مَعَكُمْ رَق[p[ِي][q[ب]ٌ","Эй қавмим, имконингиздаги амални қилаверинг, мен ҳам амал қилувчиман. Тезда кимга шарманда қиладиган азоб келишини ва ким ёлғончи эканини биласизлар. Кутинглар, мен ҳам сизлар ила кутувчиман», деди.",232,12],["وَلَ[g[مّ]َا ج[o[َا]ٓءَ أَمْرُنَا نَجَّيْنَا شُعَيْ[a:6475[بًا و]َ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مَعَهُ[n[ۥ] بِرَحْمَ[a:4803[ةٍ م]ِّ[g[نّ]َا وَأَخَذَتِ [h:6476[ٱ]لَّذِينَ ظَلَمُو[s[اْ] [h:6412[ٱ][l[ل]صَّيْحَةُ فَأَصْبَحُو[s[اْ] فِى دِيَ[n[ـٰ]رِهِمْ جَ[n[ـٰ]ثِم[p[ِي]نَ","Амримиз келган пайтда Шуайбга ва у билан бирга иймонга келганларга раҳматимиз ила нажот бердик. Зулм қилганларни эса, қичқириқ тутди ва диёрларида тўкилдилар.",232,12],["كَأ[u:2914[َن ل]َّمْ يَغْنَوْ[s[اْ] فِيه[o[َآ‌ۗ] أَلَا بُعْ[u:6477[دًا ل]ِّمَ[q:6478[دْ]يَنَ كَمَا بَعِدَتْ ثَم[p[ُو][q[د]ُ","Худди у ерда яшамаганлардек. Огоҳ бўлингким, худди Самуд йўқолгандек, Мадян ҳам йўқолди.",232,12],["وَلَقَ[q:341[دْ] أَرْسَلْنَا مُوسَىٰ بِـَٔـايَ[n[ـٰ]تِنَا وَسُلْطَ[n[ـٰ][a:6479[نٍ م]ُّب[p[ِي]نٍ","Батаҳқиқ, Биз Мусони оятларимиз ва очиқ-ойдин ҳужжатимиз ила юбордик.",232,12],["إِلَىٰ فِرْعَوْنَ وَمَلَإِ[s[يْ]ه[n[ِۦ] فَ[h:6480[ٱ]تَّبَع[o[ُوٓ][s[اْ] أَمْرَ فِرْعَوْنَ‌ۖ وَم[o[َآ] أَمْرُ فِرْعَوْنَ بِرَش[p[ِي][q[د]ٍ","Фиръавнга ва унинг одамларига. Бас, улар Фиръавн ишига эргашдилар. Фиръавннинг иши эса тўғри эмасди!",232,12],["يَ[q:6481[قْ]دُمُ قَوْمَهُ[n[ۥ] يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ فَأَوْرَدَهُمُ [h:6482[ٱ][l[ل][g[نّ]َارَ‌ۖ وَبِئْسَ [h:6483[ٱ]لْوِرْدُ [h:6484[ٱ]لْمَوْر[p[ُو][q[د]ُ","У қиёмат куни қавмининг олдига тушиб, уларни дўзахга бошлаб келтирадир. У жой қандай ҳам ёмон тушиш жойидир.",233,12],["وَأُتْبِعُو[s[اْ] فِى هَ[n[ـٰ]ذِه[n[ِۦ] لَعْنَ[a:6394[ةً و]َيَوْمَ [h:443[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۚ بِئْسَ [h:6485[ٱ][l[ل]رِّفْدُ [h:6486[ٱ]لْمَرْف[p[ُو][q[د]ُ","Бу дунёда ҳам, қиёмат кунида ҳам уларга лаънат эргашадир. Бу қандай ҳам ёмон ёрдамдир!",233,12],["ذ[n[َٲ]لِكَ مِنْ أَ[i:1910[نۢب][o[َا]ٓءِ [h:6487[ٱ]لْقُرَىٰ نَقُصُّهُ[n[ۥ] عَلَيْكَ‌ۖ مِنْهَا ق[o[َا]ٓئِ[a:6488[مٌ و]َحَص[p[ِي][q[د]ٌ","Мана булар–шаҳарларнинг хабарларидан бўлиб, уларни сенга қисса қилаётирмиз. Улардан турганлари ҳам бор, йиқилганлари ҳам бор.",233,12],["وَمَا ظَلَمْنَ[n[ـٰ]هُمْ وَلَ[n[ـٰ]كِ[f:6489[ن ظ]َلَم[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ‌ۖ فَم[o[َآ] أَغْنَتْ عَنْهُمْ ءَالِهَتُهُمُ [h:6490[ٱ]لَّتِى يَ[q:1240[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مِ[f:2103[ن ش][u:6491[َىْءٍ ل]َّ[g[مّ]َا ج[o[َا]ٓءَ أَمْرُ رَبِّكَ‌ۖ وَمَا زَادُوهُمْ غَيْرَ تَتْب[p[ِي][q[ب]ٍ","Биз уларга зулм қилмадик. Лекин ўзларига зулм қилдилар. Роббингнинг амри келган пайтда Аллоҳни қўйиб илтижо қилган «худо»лари ҳеч бир нарсада уларнинг ҳожатларини чиқара олмади. Уларга зиёндан бошқани зиёда қилмадилар.",233,12],["وَكَذ[n[َٲ]لِكَ أَخْذُ رَبِّكَ إِذ[o[َآ] أَخَذَ [h:6492[ٱ]لْقُرَىٰ وَهِىَ ظَ[n[ـٰ]لِمَةٌ‌ۚ إِ[g[نّ]َ أَخْذَهُ[o[ۥٓ] أَلِي[f:6493[مٌ ش]َد[p[ِي][q[د]ٌ","Роббинг золим шаҳарларни ушлаганида, ана шундай ушлайдир. Албатта, Унинг ушлаши аламли ва шиддатлидир.",233,12],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:6494[ةً ل]ِّمَنْ خَافَ عَذَابَ [h:6495[ٱ]لْأَخِرَةِ‌ۚ ذ[n[َٲ]لِكَ يَوْ[a:6496[مٌ م]َّ[q:6497[جْ]مُو[u:6498[عٌ ل]َّهُ [h:6499[ٱ][l[ل][g[نّ]َاسُ وَذ[n[َٲ]لِكَ يَوْ[a:6500[مٌ م]َّشْه[p[ُو][q[د]ٌ","Албатта, бунда охират азобидан қўрққан кимса учун ибрат бордир. Бу кун одамлар жамланадиган бир кундир. Бу кун шоҳид бўлинадиган кундир.",233,12],["وَمَا نُؤَخِّرُهُ[o[ۥٓ] إِلَّا لِأَجَ[a:6501[لٍ م]َّعْد[p[ُو][q[د]ٍ","Уни Биз фақат саноқли муддатга кечиктирамиз.",233,12],["يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِه[n[ِۦ]‌ۚ فَمِنْهُمْ شَقِ[a:6502[ىٌّ و]َسَع[p[ِي][q[د]ٌ","У келган кунда ҳеч бир жон гапира олмас. Магар У зотнинг изни ила. Бас, улардан бадбахтлари ва бахтлилари бордир.",233,12],["فَأَ[g[مّ]َا [h:136[ٱ]لَّذِينَ شَقُو[s[اْ] فَفِى [h:6503[ٱ][l[ل][g[نّ]َارِ لَهُمْ فِيهَا زَفِي[a:6504[رٌ و]َشَه[p[ِي][q[ق]ٌ","Бас, бадбахт бўлганлар дўзахдалар. У ерда улар дод-фарёд қилурлар.",233,12],["خَ[n[ـٰ]لِدِينَ فِيهَا مَا دَامَتِ [h:6505[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تُ وَ[h:2241[ٱ]لْأَرْضُ إِلَّا مَا ش[o[َا]ٓءَ رَبُّكَ‌ۚ إِ[g[نّ]َ رَبَّكَ فَعَّا[u:6506[لٌ ل]ِّمَا يُر[p[ِي][q[د]ُ","Улар, модомики осмонлару ер бор экан, унда абадий қолурлар. Магар Роббинг хоҳласа,. Албатта, Роббинг нимани хоҳласа, қилгувчи зотдир.",233,12],["۞ وَأَ[g[مّ]َا [h:138[ٱ]لَّذِينَ سُعِدُو[s[اْ] فَفِى [h:6507[ٱ]لْجَ[g[نّ]َةِ خَ[n[ـٰ]لِدِينَ فِيهَا مَا دَامَتِ [h:6505[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تُ وَ[h:2241[ٱ]لْأَرْضُ إِلَّا مَا ش[o[َا]ٓءَ رَبُّكَ‌ۖ عَط[o[َا]ٓءً غَيْرَ مَ[q:6508[جْ]ذ[p[ُو]ذٍ","Бахтли бўлганлар жаннатдадирлар. Улар унда, модомики осмонлару ер бор экан, абадийлар. Магар Аллоҳ хоҳласа,. Бу туганмас инъомдир.",233,12],["فَلَا تَكُ فِى مِرْيَ[a:6509[ةٍ م]ِّ[g[مّ]َا يَعْبُدُ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ‌ۚ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَاب[o[َا]ٓؤُه[w:6510[ُم م]ِّ[f:128[ن ق]َ[q:129[بْ]لُ‌ۚ وَإِ[g[نّ]َا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَ[f:6511[نق][p[ُو]صٍ","Сен анавилар ибодат қилаётган нарсада шак-шубҳада бўлма. Улар олдин оталари ибодат қилганга ўхшаш ибодат қилурлар, холос. Ва, албатта, Биз уларга насибаларини камситмай, тўлиқ қилиб берамиз.",234,12],["وَلَقَ[q:341[دْ] ءَاتَيْنَا مُوسَى [h:257[ٱ]لْكِتَ[n[ـٰ]بَ فَ[h:6512[ٱ]خْتُلِفَ فِيهِ‌ۚ وَلَوْلَا كَلِمَ[f:5989[ةٌ س]َبَقَتْ م[u:770[ِن ر]َّبِّكَ لَقُضِىَ بَيْنَهُمْ‌ۚ وَإِ[g[نّ]َهُمْ لَفِى شَ[a:3275[كٍّ م]ِّنْهُ مُر[p[ِي][q[ب]ٍ","Батаҳқиқ, Мусога китобни бердик. Бас, у ҳақида ихтилоф қилинди. Агар Роббингдан ўтган сўз бўлмаганида, ораларида ҳукм чиқарган бўлар эди. Ва, албатта, улар ундан шак-шубҳададирлар.",234,12],["وَإِ[g[نّ]َ كُل[u:6513[اًّ ل]َّ[g[مّ]َا لَيُوَفِّيَ[g[نّ]َهُمْ رَبُّكَ أَعْمَ[n[ـٰ]لَهُمْ‌ۚ إِ[g[نّ]َهُ[n[ۥ] بِمَا يَعْمَلُونَ خَب[p[ِي]رٌ","Албатта, Роббинг ҳаммага амалларига яраша тўлиқ вафо қилур. Чунки У қилаётган нарсаларидан хабардордир.",234,12],["فَ[h:9999[ٱ]سْتَقِمْ كَم[o[َآ] أُمِرْتَ وَمَ[f:6514[ن ت]َابَ مَعَكَ وَلَا تَ[q:6515[طْ]غَوْ[s[اْ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","Бас, сен ва сен билан тавба қилганлар мустақийм туринглар ва туғёнга кетманглар. Чунки У нима қилаётганингизни кўриб тургувчидир.",234,12],["وَلَا تَرْكَن[o[ُوٓ][s[اْ] إِلَى [h:1372[ٱ]لَّذِينَ ظَلَمُو[s[اْ] فَتَمَسَّكُمُ [h:6516[ٱ][l[ل][g[نّ]َارُ وَمَا لَك[w:556[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مِنْ أَوْلِي[o[َا]ٓءَ ثُ[g[مّ]َ لَا تُ[f:6517[نص]َر[p[ُو]نَ","Зулм қилганларга мойил бўлманглар. Яна сизни дўзах олови тутмасин. Сиз учун Аллоҳдан ўзга дўстлар йўқ. Сўнгра ёрдам берилмайсизлар.",234,12],["وَأَقِمِ [h:6518[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ طَرَفَىِ [h:6519[ٱ][l[ل][g[نّ]َهَارِ وَزُلَ[a:6520[فًا م]ِّنَ [h:6029[ٱ]لَّيْلِ‌ۚ إِ[g[نّ]َ [h:6521[ٱ]لْحَسَنَ[n[ـٰ]تِ يُذْهِ[q:6522[بْ]نَ [h:6523[ٱ][l[ل]سَّيِّـَٔـاتِ‌ۚ ذ[n[َٲ]لِكَ ذِكْرَىٰ لِلذّ[n[َٲ]كِر[p[ِي]نَ","Кундузнинг икки тарафида ва кечанинг бир бўлагида намозни тўкис адо қил! Албатта, яхшиликлар ёмонликларни кетказади. Бу эса, эсловчиларга эслатмадир.",234,12],["وَ[h:9999[ٱ]صْبِرْ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ لَا يُضِيعُ أَ[q:2418[جْ]رَ [h:5898[ٱ]لْمُحْسِن[p[ِي]نَ","Ва сабр қил. Бас, албатта, Аллоҳ яхшилик қилувчиларнинг ажрини зое қилмас.",234,12],["فَلَوْلَا كَانَ مِنَ [h:6524[ٱ]لْقُرُونِ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ أُ[s[وْ]لُو[s[اْ] بَقِيَّ[a:6525[ةٍ ي]َنْهَوْنَ عَنِ [h:6526[ٱ]لْفَسَادِ فِى [h:44[ٱ]لْأَرْضِ إِلَّا قَلِيل[a:6527[اً م]ِّ[g[مّ]َنْ أَ[f:5098[نج]َيْنَا مِنْهُمْ‌ۗ وَ[h:3160[ٱ]تَّبَعَ [h:6528[ٱ]لَّذِينَ ظَلَمُو[s[اْ] م[o[َآ] أُتْرِفُو[s[اْ] فِيهِ وَكَانُو[s[اْ] مُ[q:4958[جْ]رِم[p[ِي]نَ","Сиздан олдинги асрларда ер юзида фасоддан қайтарадиган боқийлик эгалари бўлганида эди. Магар Биз нажот берганлар озгина кишилар бўлди, холос. Зулм қилганлар эса, маишат ортидан кетдилар ва жиноятчилардан бўлдилар.",234,12],["وَمَا كَانَ رَبُّكَ لِيُهْلِكَ [h:6529[ٱ]لْقُرَىٰ بِظُلْ[a:4426[مٍ و]َأَهْلُهَا مُصْلِح[p[ُو]نَ","Роббинг аҳли ислоҳчи бўлган шаҳарларни зулм ила ҳалок қилмас эди.",234,12],["وَلَوْ ش[o[َا]ٓءَ رَبُّكَ لَجَعَلَ [h:6530[ٱ][l[ل][g[نّ]َاسَ أُ[g[مّ]َ[a:1159[ةً و][n[َٲ]حِدَ[a:3089[ةً‌ۖ و]َلَا يَزَالُونَ مُخْتَلِف[p[ِي]نَ","Агар Роббинг хоҳласа, одамларни бир уммат қиларди. Улар ихтилоф қилишда бардавом бўлурлар.",235,12],["إِلَّا م[u:6349[َن ر]َّحِمَ رَبُّكَ‌ۚ وَلِذ[n[َٲ]لِكَ خَلَقَهُمْ‌ۗ وَتَ[g[مّ]َتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَ[g[نّ]َ جَهَ[g[نّ]َمَ مِنَ [h:6531[ٱ]لْجِ[g[نّ]َةِ وَ[h:824[ٱ][l[ل][g[نّ]َاسِ أَ[q:825[جْ]مَع[p[ِي]نَ","Роббинг раҳм қилганларидан бошқалари. Уларни шунинг учун яратгандир. Роббингнинг: «Жаҳаннамни, албатта, жинлар ва одамлар билан тамомила тўлдирурман», деган сўзи батамом бўлди.",235,12],["وَكُل[a:6532[اًّ ن]َّقُصُّ عَلَيْكَ مِنْ أَ[i:1910[نۢب][o[َا]ٓءِ [h:6533[ٱ][l[ل]رُّسُلِ مَا نُثَبِّتُ بِه[n[ِۦ] فُؤَادَكَ‌ۚ وَج[o[َا]ٓءَكَ فِى هَ[n[ـٰ]ذِهِ [h:6534[ٱ]لْحَقُّ وَمَوْعِظَ[a:6535[ةٌ و]َذِكْرَىٰ لِلْمُؤْمِن[p[ِي]نَ","Биз қалбингни саботли қилиш учун сенга Пайғамбарлар хабарининг ҳаммасини қисса қилиб айтмоқдамиз. Бу да сенга ҳақ ва мўминларга мавъиза ҳамда эслатма келди.",235,12],["وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ [h:6536[ٱ]عْمَلُو[s[اْ] عَلَىٰ مَكَانَتِكُمْ إِ[g[نّ]َا عَ[n[ـٰ]مِل[p[ُو]نَ","Иймон келтирмайдиганларга: «Имконингиз бор амалларни қилаверинг, биз ҳам амал қилувчилармиз.",235,12],["وَ[h:9999[ٱ][f:6537[نت]َظِر[o[ُوٓ][s[اْ] إِ[g[نّ]َا مُ[f:4557[نت]َظِر[p[ُو]نَ","Ва интизор бўлинглар, биз ҳам мунтазирмиз», деб айт.",235,12],["وَلِلَّهِ غَيْبُ [h:6538[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَإِلَيْهِ يُرْجَعُ [h:6539[ٱ]لْأَمْرُ كُلُّهُ[n[ۥ] فَ[h:6540[ٱ]عْبُ[q:6540[دْ]هُ وَتَوَكَّلْ عَلَيْهِ‌ۚ وَمَا رَبُّكَ بِغَ[n[ـٰ]فِلٍ عَ[g[مّ]َا تَعْمَل[p[ُو]نَ","Осмонлару ернинг ғайби Аллоҳга хосдир. Ишнинг барчаси Унга қайтарилур. Бас, Унга ибодат қил ва Унгагина таваккал қил. Роббинг қилаётганларингиздан ғофил эмасдир.",235,12]]},{"n":12,"ar":"يُوسُفَ","en":"Yusuf","uz":"Юсуф","type":"Макка","ayahs":[["ا[m[لٓ]ر‌ۚ تِلْكَ ءَايَ[n[ـٰ]تُ [h:5932[ٱ]لْكِتَ[n[ـٰ]بِ [h:6541[ٱ]لْمُب[p[ِي]نِ","Алиф. Лом. Ро. Ушбулар очиқ-ойдин китобнинг оятларидир.",235,12],["إِ[g[نّ][o[َآ] أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ قُرْء[n[َٲ]نًا عَرَبِي[u:6542[ًّا ل]َّعَلَّكُمْ تَعْقِل[p[ُو]نَ","Биз уни арабий Қуръон этиб нозил қилдик, шоядки ақл ишлатсангиз.",235,12],["نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ [h:6543[ٱ]لْقَصَصِ بِم[o[َآ] أَوْحَيْن[o[َآ] إِلَيْكَ هَ[n[ـٰ]ذَا [h:6544[ٱ]لْقُرْءَانَ وَإِ[f:6545[ن ك]ُ[f:735[نت]َ مِ[f:1097[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] لَمِنَ [h:6546[ٱ]لْغَ[n[ـٰ]فِل[p[ِي]نَ","Биз сенга ушбу Қуръонда ваҳий қилган нарсамиз ила энг гўзал қиссани ҳикоя қилурмиз. Агарчи ундан олдин сен бундан бехабарлардан бўлсанг ҳам.",235,12],["إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَ[o[ـٰٓ]أَبَتِ إِ[g[نّ]ِى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَ[a:6547[بًا و]َ[h:4264[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ رَأَيْتُهُمْ لِى سَ[n[ـٰ]جِد[p[ِي]نَ","Юсуф отасига: «Эй отажоним, мен ўн битта юлдузни ҳам қуёш ва ойни кўрдим, уларнинг менга сажда қилаётганларини кўрдим», деганини эсла.",235,12],["قَالَ يَ[n[ـٰ]بُنَىَّ لَا تَ[q:6548[قْ]صُصْ رُءْيَاكَ عَلَ[o[ىٰٓ] إِخْوَتِكَ فَيَكِيدُو[s[اْ] لَكَ كَيْدًا‌ۖ إِ[g[نّ]َ [h:4634[ٱ][l[ل]شَّيْطَ[n[ـٰ]نَ لِلْإِ[f:6549[نس]َ[n[ـٰ]نِ عَدُ[a:873[وٌّ م]ُّب[p[ِي]نٌ","У: «Эй ўғилчам, тушингни акаларингга айтмагин. Яна улар сенга бирор ҳийла қилмасинлар. Албатта, шайтон инсонга очиқ-ойдин душмандир», деди.",236,12],["وَكَذ[n[َٲ]لِكَ يَ[q:6550[جْ]تَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِ[f:6551[ن ت]َأْوِيلِ [h:6552[ٱ]لْأَحَادِيثِ وَيُتِ[g[مّ]ُ نِعْمَتَهُ[n[ۥ] عَلَيْكَ وَعَلَ[o[ىٰٓ] ءَالِ يَعْقُوبَ كَم[o[َآ] أَتَ[g[مّ]َهَا عَلَ[o[ىٰٓ] أَبَوَيْكَ مِ[f:128[ن ق]َ[q:129[بْ]لُ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَإِسْحَ[n[ـٰ]قَ‌ۚ إِ[g[نّ]َ رَبَّكَ عَلِيمٌ حَك[p[ِي]مٌ","Шундай қилиб, Роббинг сени танлаб оладир, сенга тушларнинг таъбирини ўргатадир ва сенга ва Яъқуб аҳлига, худди оталаринг Иброҳим ва Исҳоққа батамом қилганидек, ўз неъматини батамом қилиб берадир. Албатта, Роббинг билгувчи ва ҳикматли зотдир».",236,12],["۞ لَّقَ[q:2389[دْ] كَانَ فِى يُوسُفَ وَإِخْوَتِه[o[ِۦٓ] ءَايَ[n[ـٰ][u:6553[تٌ ل]ِّلسّ[o[َا]ٓئِل[p[ِي]نَ","Батаҳқиқ, Юсуф ва унинг оға-иниларида сўровчилар учун оят-ибратлар бор эди.",236,12],["إِذْ قَالُو[s[اْ] لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَ[o[ىٰٓ] أَبِينَا مِ[g[نّ]َا وَنَحْنُ عُصْبَةٌ إِ[g[نّ]َ أَبَانَا لَفِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Ўшанда улар: «Албатта, Юсуф ва унинг укаси отамизга биздан кўра маҳбуброқлар, ҳолбуки, биз кўпчиликмиз. Албатта, отамиз очиқ-ойдин адашувдадир», дедилар.",236,12],["ٱ[q:2891[قْ]تُلُو[s[اْ] يُوسُفَ أَوِ [h:6554[ٱ][q:6555[طْ]رَحُوهُ أَرْ[a:6556[ضًا ي]َخْلُ لَكُمْ وَ[q:603[جْ]هُ أَبِيكُمْ وَتَكُونُو[s[اْ] م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] قَوْ[f:6557[مًا ص]َ[n[ـٰ]لِح[p[ِي]نَ","«Юсуфни ўлдиринглар ёки узоқ ерга олиб бориб ташланглар, шунда отангизнинг юзи сизга холи қолади. Бундан кейин солиҳ қавмдан бўлиб оласизлар», дедилар.",236,12],["قَالَ ق[o[َا]ٓئِ[a:6558[لٌ م]ِّنْهُمْ لَا تَ[q:2734[قْ]تُلُو[s[اْ] يُوسُفَ وَأَلْقُوهُ فِى غَيَ[n[ـٰ]بَتِ [h:6559[ٱ]لْجُبِّ يَلْتَقِ[q:6560[طْ]هُ بَعْضُ [h:6561[ٱ][l[ل]سَّيَّارَةِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ فَ[n[ـٰ]عِل[p[ِي]نَ","Улардан бир сўзловчи: «Юсуфни ўлдирманглар. Агар бирон иш қилмоқчи бўлсангиз, уни қудуқнинг қаърига ташланглар, баъзи йўловчилар олиб кетади», деди.",236,12],["قَالُو[s[اْ] يَ[o[ـٰٓ]أَبَانَا مَا لَكَ لَا تَأْمَ۫[g[نّ]َا عَلَىٰ يُوسُفَ وَإِ[g[نّ]َا لَهُ[n[ۥ] لَنَ[n[ـٰ]صِح[p[ُو]نَ","Улар: «Эй отамиз, сен нега Юсуфни бизга ишонмайсан? Ҳолбуки, биз унга ихлос қилувчилармиз.",236,12],["أَرْسِلْهُ مَعَنَا غَ[a:6562[دًا ي]َرْتَعْ وَيَلْعَ[q:6563[بْ] وَإِ[g[نّ]َا لَهُ[n[ۥ] لَحَ[n[ـٰ]فِظ[p[ُو]نَ","Эртага уни биз билан юбор, еб-ичиб, ўйнаб келадир. Албатта, биз уни муҳофаза қилувчилармиз», дедилар.",236,12],["قَالَ إِ[g[نّ]ِى لَيَحْزُنُن[o[ِىٓ] أَ[f:6564[ن ت]َذْهَبُو[s[اْ] بِه[n[ِۦ] وَأَخَافُ أ[a:6565[َن ي]َأْكُلَهُ [h:6566[ٱ][l[ل]ذِّئْبُ وَأَ[f:98[نت]ُمْ عَنْهُ غَ[n[ـٰ]فِل[p[ُو]نَ","У: «Уни олиб кетишингиз мени хафа қиладир. Сиз ундан ғофил қолсангиз, уни бўри еб кетишидан қўрқаман», деди.",236,12],["قَالُو[s[اْ] لَئِنْ أَكَلَهُ [h:6567[ٱ][l[ل]ذِّئْبُ وَنَحْنُ عُصْبَةٌ إِ[g[نّ][o[َآ] إِ[u:4868[ذًا ل]َّخَ[n[ـٰ]سِر[p[ُو]نَ","Улар: «Агар биз кўпчилик бўлиб туриб, уни бўри еб кетса, унда биз зиёнкорлардан эканмиз-да?!» дедилар.",236,12],["فَلَ[g[مّ]َا ذَهَبُو[s[اْ] بِه[n[ِۦ] وَأَ[q:6568[جْ]مَع[o[ُوٓ][s[اْ] أ[a:6569[َن ي]َ[q:6570[جْ]عَلُوهُ فِى غَيَ[n[ـٰ]بَتِ [h:6559[ٱ]لْجُبِّ‌ۚ وَأَوْحَيْن[o[َآ] إِلَيْهِ لَتُنَبِّئَ[g[نّ]َه[c:6571[ُم ب]ِأَمْرِهِمْ هَ[n[ـٰ]ذَا وَهُمْ لَا يَشْعُر[p[ُو]نَ","Уни олиб кетиб, қудуқ қаърига ташлашга қарор қилганларида, биз унга: «Сен, албатта, уларга бу қилмишларининг хабарини берасан, ўшанда улар сени сезмаслар ҳам», деб ваҳий қилдик.",237,12],["وَج[o[َا]ٓء[o[ُوٓ] أَبَاهُمْ عِش[o[َا]ٓ[a:6572[ءً ي]َ[q:6573[بْ]ك[p[ُو]نَ","Кечқурун йиғлаган ҳолларида оталарига келиб:",237,12],["قَالُو[s[اْ] يَ[o[ـٰٓ]أَبَان[o[َآ] إِ[g[نّ]َا ذَهَ[q:6574[بْ]نَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِ[f:264[ند]َ مَتَ[n[ـٰ]عِنَا فَأَكَلَهُ [h:6575[ٱ][l[ل]ذِّئْبُ‌ۖ وَم[o[َآ] أَ[f:169[نت]َ بِمُؤْمِ[u:6576[نٍ ل]َّنَا وَلَوْ كُ[g[نّ]َا صَ[n[ـٰ]دِق[p[ِي]نَ","«Эй отамиз, биз Юсуфни нарсаларимиз олдига қолдириб, ўзимиз қувлашиб кетсак, уни бўри еб қўйибди. Агар ростгўй бўлсак ҳам, сен бизга ишонмассан», дедилар.",237,12],["وَج[o[َا]ٓءُو عَلَىٰ قَمِيصِه[n[ِۦ] بِدَ[f:6577[مٍ ك]َذِ[f:6578[بٍ‌ۚ ق]َالَ بَلْ سَوَّلَتْ لَكُمْ أَ[f:6579[نف]ُسُكُمْ أَمْ[f:6580[رًا‌ۖ ف]َصَ[q:6581[بْ][f:6582[رٌ ج]َمِي[a:6583[لٌ‌ۖ و]َ[h:72[ٱ]للَّهُ [h:6584[ٱ]لْمُسْتَعَانُ عَلَىٰ مَا تَصِف[p[ُو]نَ","Ва унинг ёлғон қонга бўялган кўйлагини келтирдилар. У: «Йўқ! Сизга ҳавои нафсингиз бирор ишни зийнатлаб кўрсатибди. Энди чиройли сабр. Сиз васф қилаётган нарсада ёрдам сўраладиган зот ёлғиз Аллоҳнинг Ўзи», деди.",237,12],["وَج[o[َا]ٓءَتْ سَيَّارَ[f:6585[ةٌ ف]َأَرْسَلُو[s[اْ] وَارِدَهُمْ فَأَ[q:6586[دْ]لَىٰ دَلْوَهُ[n[ۥ]‌ۖ قَالَ يَ[n[ـٰ]بُشْرَىٰ هَ[n[ـٰ]ذَا غُلَ[n[ـٰ][a:6587[مٌ‌ۚ و]َأَسَرُّوهُ بِضَ[n[ـٰ]عَ[a:6588[ةً‌ۚ و]َ[h:72[ٱ]للَّهُ عَلِي[i:6056[مُۢ ب]ِمَا يَعْمَل[p[ُو]نَ","Ва йўловчилар келиб сувчиларини юбордилар. Бас, у челагини ташлади ва: «Суюнчи беринглар! Бу бола-ку!», деди. Уни тижорат моли сифатида яшириб қўйдилар. Зотан, Аллоҳ уларнинг нима қилаётганларини билгувчи зотдир.",237,12],["وَشَرَوْهُ بِثَمَ[i:6589[نِۭ ب]َخْ[f:6590[سٍ د]َر[n[َٲ]هِمَ مَعْدُودَ[a:6591[ةٍ و]َكَانُو[s[اْ] فِيهِ مِنَ [h:6592[ٱ][l[ل]زّ[n[َٲ]هِد[p[ِي]نَ","Ва уни арзон баҳога, саноқли дирҳамларга сотдилар. Улар унга қизиқмаган эдилар.",237,12],["وَقَالَ [h:6593[ٱ]لَّذِى [h:6594[ٱ]شْتَرَ[n[ٮٰ]هُ م[a:6595[ِن م]ِّصْرَ لِ[h:6596[ٱ]مْرَأَتِه[o[ِۦٓ] أَكْرِمِى مَثْوَ[n[ٮٰ]هُ عَسَ[o[ىٰٓ] أ[a:6597[َن ي]َ[f:6598[نف]َعَن[o[َآ] أَوْ نَتَّخِذَهُ[n[ۥ] وَلَ[a:6599[دًا‌ۚ و]َكَذ[n[َٲ]لِكَ مَكَّ[g[نّ]َا لِيُوسُفَ فِى [h:44[ٱ]لْأَرْضِ وَلِنُعَلِّمَهُ[n[ۥ] مِ[f:6551[ن ت]َأْوِيلِ [h:6552[ٱ]لْأَحَادِيثِ‌ۚ وَ[h:72[ٱ]للَّهُ غَالِبٌ عَلَ[o[ىٰٓ] أَمْرِه[n[ِۦ] وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Ва уни Мисрда сотиб олган ўз хотинига: «Уни яхшилаб жойлаштир, шояд бизга манфаат берса ёки бола қилиб олсак», деди. Мана шундай қилиб, унга тушларнинг таъбирини ўргатишимиз учун Юсуфни жойлаштириб қўйдик. Аллоҳ Ўз ишида ғолибдир. Лекин одамларнинг кўпи билмаслар.",237,12],["وَلَ[g[مّ]َا بَلَغَ أَشُدَّهُ[o[ۥٓ] ءَاتَيْنَ[n[ـٰ]هُ حُكْ[a:6600[مًا و]َعِلْ[a:6601[مًا‌ۚ و]َكَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4215[ٱ]لْمُحْسِن[p[ِي]نَ","Вояга етган вақтида унга ҳукмни ва илмни бердик. Гўзал иш қилгувчиларни шундай мукофотлармиз.",237,12],["وَر[n[َٲ]وَدَتْهُ [h:6602[ٱ]لَّتِى هُوَ فِى بَيْتِهَا ع[a:5890[َن ن]َّفْسِه[n[ِۦ] وَغَلَّقَتِ [h:6603[ٱ]لْأَ[q:6604[بْ]و[n[َٲ]بَ وَقَالَتْ هَيْتَ لَكَ‌ۚ قَالَ مَعَاذَ [h:6605[ٱ]للَّهِ‌ۖ إِ[g[نّ]َهُ[n[ۥ] رَبّ[o[ِىٓ] أَحْسَنَ مَثْوَاىَ‌ۖ إِ[g[نّ]َهُ[n[ۥ] لَا يُفْلِحُ [h:3981[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","У уйида бўлган аёл ундан нафсини хоҳлади. Эшикларни беркитиб: «Бу ёққа кел!» деди. У: «Аллоҳ сақласин! Ахир, у жойимни яхшилаб берган хўжам-ку! Албатта, золимлар нажот топмаслар», деди.",238,12],["وَلَقَ[q:341[دْ] هَ[g[مّ]َتْ بِه[n[ِۦ]‌ۖ وَهَ[g[مّ]َ بِهَا لَوْل[o[َآ] أ[u:6606[َن ر]َّءَا بُرْهَ[n[ـٰ]نَ رَبِّه[n[ِۦ]‌ۚ كَذ[n[َٲ]لِكَ لِنَصْرِفَ عَنْهُ [h:6607[ٱ][l[ل]سّ[o[ُو]ٓءَ وَ[h:6608[ٱ]لْفَحْش[o[َا]ٓءَ‌ۚ إِ[g[نّ]َهُ[n[ۥ] مِنْ عِبَادِنَا [h:6609[ٱ]لْمُخْلَص[p[ِي]نَ","Батаҳқиқ, унга интилди. У ҳам, агар Роббининг бурҳон-ҳужжатини кўрмаганида, интилар эди. Ундан ёмонлик ва фаҳш ишларни узоқлаштириш учун шундай қилдик. Албатта, у Бизнинг мухлис бандаларимиздан.",238,12],["وَ[h:9999[ٱ]سْتَبَقَا [h:6610[ٱ]لْبَابَ وَقَدَّتْ قَمِيصَهُ[n[ۥ] مِ[f:6611[ن د]ُبُ[a:6612[رٍ و]َأَلْفَيَا سَيِّدَهَا لَدَا [h:6613[ٱ]لْبَابِ‌ۚ قَالَتْ مَا جَز[o[َا]ٓءُ مَنْ أَرَادَ بِأَهْلِكَ س[o[ُو]ٓءًا إِلّ[o[َآ] أ[a:6614[َن ي]ُسْجَنَ أَوْ عَذَابٌ أَل[p[ِي]مٌ","Икковлари эшик томон чопишди. Хотин унинг кўйлагини орқасидан юлиб олди. Эшик олдида унинг хўжайинига дуч келишди. У: «Сенинг аҳлингга ёмонлик хоҳлаганнинг жазоси фақатгина қамалмоқ ёки аламли азобдир», деди.",238,12],["قَالَ هِىَ ر[n[َٲ]وَدَتْنِى ع[a:6615[َن ن]َّفْسِى‌ۚ وَشَهِدَ شَاهِ[a:6616[دٌ م]ِّنْ أَهْلِه[o[َآ] إِ[f:2594[ن ك]َانَ قَمِيصُهُ[n[ۥ] قُدَّ مِ[f:6617[ن ق]ُبُ[f:6618[لٍ ف]َصَدَقَتْ وَهُوَ مِنَ [h:4785[ٱ]لْكَ[n[ـٰ]ذِب[p[ِي]نَ","У: «Унинг ўзи менинг нафсимни хоҳлади», деди. Унинг аҳлидан бир гувоҳ гувоҳлик берди ва: «Агар унинг кўйлаги олд томондан йиртилган бўлса, бас, хотин рост айтибдир, у ёлғончилардандир.",238,12],["وَإِ[f:1649[ن ك]َانَ قَمِيصُهُ[n[ۥ] قُدَّ مِ[f:6611[ن د]ُبُ[f:6619[رٍ ف]َكَذَبَتْ وَهُوَ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","Агар унинг кўйлаги орт томондан йиртилган бўлса, бас, хотин ёлғон гапирибдир, у ростгўйлардандир», деди.",238,12],["فَلَ[g[مّ]َا رَءَا قَمِيصَهُ[n[ۥ] قُدَّ مِ[f:6611[ن د]ُبُ[f:6620[رٍ ق]َالَ إِ[g[نّ]َهُ[n[ۥ] مِ[f:6621[ن ك]َيْدِكُ[g[نّ]َ‌ۖ إِ[g[نّ]َ كَيْدَكُ[g[نّ]َ عَظ[p[ِي]مٌ","Эр унинг кўйлагини орт томонидан йиртилганини кўрган пайтда: «Албатта, бу сиз хотинларнинг макрингиздир. Албатта, сиз хотинларнинг макри жуда зўрдир.",238,12],["يُوسُفُ أَعْرِضْ عَنْ هَ[n[ـٰ]ذَا‌ۚ وَ[h:6622[ٱ]سْتَغْفِرِى لِذَ[i:6623[نۢب]ِكِ‌ۖ إِ[g[نّ]َكِ كُ[f:6624[نت]ِ مِنَ [h:6625[ٱ]لْخَاطِــٔ[p[ِي]نَ","Эй Юсуф, сен бу ишни унут. Сен, хотин, гуноҳингга истиғфор айт. Албатта, сен хато қилгувчилардан бўлдинг», деди.",238,12],["۞ وَقَالَ نِسْوَ[f:6626[ةٌ ف]ِى [h:4932[ٱ]لْمَدِينَةِ [h:6627[ٱ]مْرَأَتُ [h:6628[ٱ]لْعَزِيزِ تُر[n[َٲ]وِدُ فَتَ[n[ـٰ]هَا ع[a:5890[َن ن]َّفْسِه[n[ِۦ]‌ۖ قَ[q:298[دْ] شَغَفَهَا حُبًّا‌ۖ إِ[g[نّ]َا لَنَرَ[n[ٮٰ]هَا فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Шаҳардаги аёллар: «Азизнинг хотини хизматкорининг нафсини хоҳлабди. Унга жуда ҳам муҳаббат қўйиб қолган экан-да! Биз у ни, албатта, очиқ-ойдин адашувда деб биламиз», дейишди.",238,12],["فَلَ[g[مّ]َا سَمِعَتْ بِمَكْرِهِ[g[نّ]َ أَرْسَلَتْ إِلَيْهِ[g[نّ]َ وَأَعْتَدَتْ لَهُ[g[نّ]َ مُتَّكَـ[a:6629[ـًٔا و]َءَاتَتْ كُلَّ و[n[َٲ]حِدَ[a:6630[ةٍ م]ِّنْهُ[g[نّ]َ سِكِّي[a:6631[نًا و]َقَالَتِ [h:6632[ٱ]خْرُ[q:4615[جْ] عَلَيْهِ[g[نّ]َ‌ۖ فَلَ[g[مّ]َا رَأَيْنَهُ[o[ۥٓ] أَكْبَرْنَهُ[n[ۥ] وَقَطَّعْنَ أَيْدِيَهُ[g[نّ]َ وَقُلْنَ حَ[n[ـٰ]شَ لِلَّهِ مَا هَ[n[ـٰ]ذَا بَشَرًا إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا مَلَ[f:6633[كٌ ك]َر[p[ِي]مٌ","Уларнинг макри ҳақида эшитган вақтда, уларга одам юбориб чақирди. Уларга суяниб ўтирадиган жой тайёрлади. Ва ҳар бирларига пичоқ берди. Сўнгра: «Уларнинг олдига чиқ!» деди. Уни кўрган чоғларида лол қолдилар, қўлларини кесдилар. Ва: «Ё пок Парвардигоро! Бу башар эмас! Бу карамли фариштанинг ўзи-ку!» дейишди.",239,12],["قَالَتْ فَذ[n[َٲ]لِكُ[g[نّ]َ [h:6634[ٱ]لَّذِى لُمْتُ[g[نّ]َنِى فِيهِ‌ۖ وَلَقَ[q:341[دْ] ر[n[َٲ]وَ[d:6635[د]تُّهُ[n[ۥ] ع[a:5890[َن ن]َّفْسِه[n[ِۦ] فَ[h:6636[ٱ]سْتَعْصَمَ‌ۖ وَلَئ[u:6637[ِن ل]َّمْ يَفْعَلْ م[o[َآ] ءَامُرُهُ[n[ۥ] لَيُسْجَنَ[g[نّ]َ وَلَيَكُو[a:6638[نًا م]ِّنَ [h:4604[ٱ][l[ل]صَّ[n[ـٰ]غِر[p[ِي]نَ","У: «Сиз мени маломат қилган эдингиз. Ҳа, мен ундан нафсини хоҳладим, бироқ у ўзини сақлади. Агар у менинг амримни бажармаса, албатта, қамалур ва хор бўлгувчилардан бўлур», деди.",239,12],["قَالَ رَبِّ [h:6639[ٱ][l[ل]سِّ[q:6640[جْ]نُ أَحَبُّ إِلَىَّ مِ[g[مّ]َا يَ[q:6641[دْ]عُونَن[o[ِىٓ] إِلَيْهِ‌ۖ وَإِلَّا تَصْرِفْ عَ[g[نّ]ِى كَيْدَهُ[g[نّ]َ أَصْبُ إِلَيْهِ[g[نّ]َ وَأَك[a:6642[ُن م]ِّنَ [h:352[ٱ]لْجَ[n[ـٰ]هِل[p[ِي]نَ","«Эй Роббим, улар мени чорлаётган нарсадан кўра мен учун қамоқ маҳбуброқдир, буларнинг макрини мендан Ўзинг нари қилмасанг, уларга мойил бўлиб, жоҳиллардан бўлиб қоламан», деди.",239,12],["فَ[h:9999[ٱ]سْتَجَابَ لَهُ[n[ۥ] رَبُّهُ[n[ۥ] فَصَرَفَ عَنْهُ كَيْدَهُ[g[نّ]َ‌ۚ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:3721[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Бас, Робби унинг ижобат қилиб, уларнинг макрини ундан нари қилди. Албатта, Унинг ўзи эшитгувчи ва билгувчи зотдир.",239,12],["ثُ[g[مّ]َ بَدَا لَه[w:1812[ُم م]ّ[i:146[ِنۢ ب]َعْدِ مَا رَأَوُ[s[اْ] [h:6643[ٱ]لْأَيَ[n[ـٰ]تِ لَيَسْجُنُ[g[نّ]َهُ[n[ۥ] حَتَّىٰ ح[p[ِي]نٍ","Сўнгра оят-аломатларни кўрганларидан кейин уларга уни бир муддат қамашлари аён бўлди.",239,12],["وَدَخَلَ مَعَهُ [h:6644[ٱ][l[ل]سِّ[q:6645[جْ]نَ فَتَيَانِ‌ۖ قَالَ أَحَدُهُم[o[َآ] إِ[g[نّ][o[ِىٓ] أَرَ[n[ٮٰ]ن[o[ِىٓ] أَعْصِرُ خَمْ[a:6646[رًا‌ۖ و]َقَالَ [h:6647[ٱ]لْأَخَرُ إِ[g[نّ][o[ِىٓ] أَرَ[n[ٮٰ]ن[o[ِىٓ] أَحْمِلُ فَوْقَ رَأْسِى خُ[q:6648[بْ][f:6649[زًا ت]َأْكُلُ [h:6650[ٱ][l[ل]طَّيْرُ مِنْهُ‌ۖ نَبِّئْنَا بِتَأْوِيلِه[o[ِۦٓ‌ۖ] إِ[g[نّ]َا نَرَ[n[ٮٰ]كَ مِنَ [h:4754[ٱ]لْمُحْسِن[p[ِي]نَ","У билан қамоққа иккита йигит ҳам кирди. Улардан бири: «Мен тушимда, шароб тайёрлаб юрибман», деди. Бошқаси эса: «Мен бошимда нон кўтариб юрибман, қуш ундан емоқда», деди. «Бизга бунинг таъбирини хабар қил. Биз сени, шубҳасиз, яхши амал қилгувчилардан, деб билмоқдамиз».",239,12],["قَالَ لَا يَأْتِيكُمَا طَعَا[f:6651[مٌ ت]ُرْزَقَانِه[o[ِۦٓ] إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِه[n[ِۦ] قَ[q:3282[بْ]لَ أ[a:6652[َن ي]َأْتِيَكُمَا‌ۚ ذ[n[َٲ]لِكُمَا مِ[g[مّ]َا عَلَّمَنِى رَبّ[o[ِىٓ‌ۚ] إِ[g[نّ]ِى تَرَكْتُ مِلَّةَ قَوْ[u:6210[مٍ ل]َّا يُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَه[c:4710[ُم ب]ِ[h:447[ٱ]لْأَخِرَةِ هُمْ كَ[n[ـٰ]فِر[p[ُو]نَ","У: «Мен сизларга ризқ бўладиган таом келгунига қадар унинг қандай эканининг хабарини бераман. Бу иш менга Роббим таълим берган нарсалардандир. Чунки мен Аллоҳга иймон келтирмайдиган ва охиратга кофир бўлган қавмнинг миллати-динини тарк этган одамман», деди.",239,12],["وَ[h:9999[ٱ]تَّبَعْتُ مِلَّةَ ءَاب[o[َا]ٓء[o[ِىٓ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَإِسْحَ[n[ـٰ]قَ وَيَعْقُوبَ‌ۚ مَا كَانَ لَن[o[َآ] أ[a:6653[َن ن]ُّشْرِكَ بِ[h:32[ٱ]للَّهِ مِ[f:2103[ن ش][f:6654[َىْءٍ‌ۚ ذ][n[َٲ]لِكَ مِ[f:6655[ن ف]َضْلِ [h:6656[ٱ]للَّهِ عَلَيْنَا وَعَلَى [h:6657[ٱ][l[ل][g[نّ]َاسِ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَشْكُر[p[ُو]نَ","Ва оталарим Иброҳим, Исҳоқ ва Яъқубнинг миллати-динига эргашдим. Биз учун Аллоҳга бирор нарсани шерик қилиш мумкин эмас эди. Бу бизга ва одамларга Аллоҳ берган фазл эди. Лекин одамларнинг кўплари шукр қилмаслар.",240,12],["يَ[n[ـٰ]صَ[n[ـٰ]حِبَىِ [h:6658[ٱ][l[ل]سِّ[q:6659[جْ]نِ ءَأَرْبَا[a:6660[بٌ م]ُّتَفَرِّقُونَ خَيْرٌ أَمِ [h:717[ٱ]للَّهُ [h:6661[ٱ]لْو[n[َٲ]حِدُ [h:6662[ٱ]لْقَهّ[p[َا]رُ","Эй ҳамзиндон дўстларим, турли-туман Робблар яхшими ёки ёлғизу Қаҳҳор Аллоҳми?",240,12],["مَا تَعْبُدُونَ مِ[f:3136[ن د]ُونِه[o[ِۦٓ] إِلّ[o[َآ] أَسْم[o[َا]ٓ[f:6663[ءً س]َ[g[مّ]َيْتُمُوه[o[َآ] أَ[f:428[نت]ُمْ وَءَاب[o[َا]ٓؤُك[w:4796[ُم م]ّ[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ بِهَا مِ[f:4798[ن س]ُلْطَ[n[ـٰ]نٍ‌ۚ إِنِ [h:4101[ٱ]لْحُكْمُ إِلَّا لِلَّهِ‌ۚ أَمَرَ أَلَّا تَعْبُد[o[ُوٓ][s[اْ] إِلّ[o[َآ] إِيَّاهُ‌ۚ ذ[n[َٲ]لِكَ [h:5569[ٱ][l[ل]دِّينُ [h:5570[ٱ]لْقَيِّمُ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Сизлар Ундан ўзга, ўзингиз ва ота-боболарингиз номлаб олган исмларга, Аллоҳ уларга бирон ҳужжат нозил қилмаган нарсаларга ибодат қилмоқдасизлар. Ҳукм қилиш фақат Аллоҳнинг Ўзига хосдир, У фақат Ўзигагина ибодат қилишингизни амр этди. Ана ўша тўғри диндир. Лекин одамларнинг кўпи билмаслар.",240,12],["يَ[n[ـٰ]صَ[n[ـٰ]حِبَىِ [h:6658[ٱ][l[ل]سِّ[q:6659[جْ]نِ أَ[g[مّ][o[َآ] أَحَدُكُمَا فَيَسْقِى رَبَّهُ[n[ۥ] خَمْ[a:6664[رًا‌ۖ و]َأَ[g[مّ]َا [h:6665[ٱ]لْأَخَرُ فَيُصْلَبُ فَتَأْكُلُ [h:6666[ٱ][l[ل]طَّيْرُ م[u:1057[ِن ر]َّأْسِه[n[ِۦ]‌ۚ قُضِىَ [h:6667[ٱ]لْأَمْرُ [h:6668[ٱ]لَّذِى فِيهِ تَسْتَفْتِي[p[َا]نِ","Эй ҳамзиндон дўстларим, сизлардан бирингиз хўжасига хамр соқийлиги қилур. Бошқаси бўлса, осилур ва қушлар унинг бошидан ейдир. Сиз билмоқчи бўлган иш битди.",240,12],["وَقَالَ لِلَّذِى ظَ[g[نّ]َ أَ[g[نّ]َهُ[n[ۥ] نَا[a:6669[جٍ م]ِّنْهُمَا [h:6670[ٱ]ذْكُرْنِى عِ[f:264[ند]َ رَبِّكَ فَأَ[f:6671[نس]َ[n[ـٰ]هُ [h:6672[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ ذِكْرَ رَبِّه[n[ِۦ] فَلَبِثَ فِى [h:6673[ٱ][l[ل]سِّ[q:6659[جْ]نِ بِضْعَ سِن[p[ِي]نَ","Ва у ўзи икковларидан нажот топгувчи деб билган шахсга: «Хўжанг ҳузурида мени эсга ол», деди. Шайтон унга хўжасига эслатишни унуттирди. Бас, у қамоқда бир неча йил қолди.",240,12],["وَقَالَ [h:6674[ٱ]لْمَلِكُ إِ[g[نّ][o[ِىٓ] أَرَىٰ سَ[q:158[بْ]عَ بَقَر[n[َٲ][f:6675[تٍ س]ِمَا[a:6676[نٍ ي]َأْكُلُهُ[g[نّ]َ سَ[q:6677[بْ]عٌ عِجَا[a:6678[فٌ و]َسَ[q:6679[بْ]عَ سُ[i:6680[نۢب]ُلَ[n[ـٰ]تٍ خُضْ[a:6681[رٍ و]َأُخَرَ يَابِسَ[n[ـٰ][a:6682[تٍ‌ۖ ي]َ[o[ـٰٓ]أَيُّهَا [h:6683[ٱ]لْمَلَأُ أَفْتُونِى فِى رُءْيَ[n[ـٰ]ىَ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ لِلرُّءْيَا تَعْبُر[p[ُو]نَ","Подшоҳ: «Мен тушимда еттита семиз сигирни еттита ориқ сигир еяётганини ва еттита яшил бошоқни ва шунча қуруғини кўрмоқдаман. Эй аъёнлар, агар туш таъбирини қиладиган бўлсангиз, менга тушимнинг фатвосини беринг», деди.",240,12],["قَال[o[ُوٓ][s[اْ] أَضْغَ[n[ـٰ]ثُ أَحْلَ[n[ـٰ][a:6684[مٍ‌ۖ و]َمَا نَحْنُ بِتَأْوِيلِ [h:6685[ٱ]لْأَحْلَ[n[ـٰ]مِ بِعَ[n[ـٰ]لِم[p[ِي]نَ","Улар: «Бу алғов-далғов тушдир. Биз бундай тушларнинг таъбирини билувчи эмасмиз», дедилар",241,12],["وَقَالَ [h:6593[ٱ]لَّذِى نَجَا مِنْهُمَا وَ[h:6686[ٱ]دَّكَرَ بَعْدَ أُ[g[مّ]َةٍ أَنَا۟ أُنَبِّئُك[c:6687[ُم ب]ِتَأْوِيلِه[n[ِۦ] فَأَرْسِل[p[ُو]نِ","Ва иккисидан нажот топгани анча муддат ўтгандан сўнг хотирлаб: «Бунинг таъбирининг хабарини сизга мен бераман. Мени юборинг», деди.",241,12],["يُوسُفُ أَيُّهَا [h:6688[ٱ][l[ل]صِّدِّيقُ أَفْتِنَا فِى سَ[q:6689[بْ]عِ بَقَر[n[َٲ][f:6675[تٍ س]ِمَا[a:6676[نٍ ي]َأْكُلُهُ[g[نّ]َ سَ[q:6677[بْ]عٌ عِجَا[a:6690[فٌ و]َسَ[q:6691[بْ]عِ سُ[i:6680[نۢب]ُلَ[n[ـٰ]تٍ خُضْ[a:6681[رٍ و]َأُخَرَ يَابِسَ[n[ـٰ][u:6692[تٍ ل]َّعَلّ[o[ِىٓ] أَرْجِعُ إِلَى [h:5455[ٱ][l[ل][g[نّ]َاسِ لَعَلَّهُمْ يَعْلَم[p[ُو]نَ","«Юсуф, эй ростгўй зот, бизга еттита семиз сигирни еттита ориқ сигир еяётганини ва еттита яшил бошоқни ва шунча қуруғининг таъбирини айт. Шоядки одамларга қайтиб борсам, улар ҳам билсалар», деди.",241,12],["قَالَ تَزْرَعُونَ سَ[q:158[بْ]عَ سِنِينَ دَأَ[f:6693[بًا ف]َمَا حَصَ[d:6694[د]تُّمْ فَذَرُوهُ فِى سُ[i:6695[نۢب]ُلِه[o[ِۦٓ] إِلَّا قَلِيل[a:6696[اً م]ِّ[g[مّ]َا تَأْكُل[p[ُو]نَ","У: «Кетма-кет етти йил зироат қиласизлар. Йиғиштириб олган ҳосилингизни бошоғида қолдиринг. Магар озгина ейдиганингизни.",241,12],["ثُ[g[مّ]َ يَأْتِى م[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ سَ[q:6677[بْ][f:6697[عٌ ش]ِدَا[a:6698[دٌ ي]َأْكُلْنَ مَا قَدَّمْتُمْ لَهُ[g[نّ]َ إِلَّا قَلِيل[a:6696[اً م]ِّ[g[مّ]َا تُحْصِن[p[ُو]نَ","Сўнгра, ундан кейин еттита шиддатли келадид, улар олдиндан тайёрлаб қўйганингизни ейдилар. Магар озгина асраб қўйганингизгина қолур.",241,12],["ثُ[g[مّ]َ يَأْتِى م[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ عَا[f:6699[مٌ ف]ِيهِ يُغَاثُ [h:6700[ٱ][l[ل][g[نّ]َاسُ وَفِيهِ يَعْصِر[p[ُو]نَ","Сўнгра ундан кейин бир йил келадики, унда одамлар сероб қилинадилар ва унда сиқадилар.",241,12],["وَقَالَ [h:6674[ٱ]لْمَلِكُ [h:6701[ٱ]ئْتُونِى بِه[n[ِۦ]‌ۖ فَلَ[g[مّ]َا ج[o[َا]ٓءَهُ [h:6702[ٱ][l[ل]رَّسُولُ قَالَ [h:6703[ٱ]رْجِعْ إِلَىٰ رَبِّكَ فَسْــَٔلْهُ مَا بَالُ [h:6704[ٱ][l[ل][g[نّ]ِسْوَةِ [h:6705[ٱ]لَّ[n[ـٰ]تِى قَطَّعْنَ أَيْدِيَهُ[g[نّ]َ‌ۚ إِ[g[نّ]َ رَبِّى بِكَيْدِهِ[g[نّ]َ عَل[p[ِي]مٌ","Подшоҳ: «Уни менга келтиринглар», деди. Унга элчи келган пайтда: «Хўжанг ҳузурига қайтиб бор ва ундан қўлларини кесган хотинларнинг ҳоли нима бўлганини сўра, албатта, Роббим уларнинг макрини билгувчидир», деди.",241,12],["قَالَ مَا خَ[q:6706[طْ]بُكُ[g[نّ]َ إِذْ ر[n[َٲ]وَ[d:6707[د]تُّ[g[نّ]َ يُوسُفَ ع[a:5890[َن ن]َّفْسِه[n[ِۦ]‌ۚ قُلْنَ حَ[n[ـٰ]شَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِ[f:1847[ن س][o[ُو]ٓ[f:6708[ءٍ‌ۚ ق]َالَتِ [h:1864[ٱ]مْرَأَتُ [h:6628[ٱ]لْعَزِيزِ [h:6709[ٱ]لْـَٔ[n[ـٰ]نَ حَصْحَصَ [h:6710[ٱ]لْحَقُّ أَنَا۟ ر[n[َٲ]وَ[d:6635[د]تُّهُ[n[ۥ] ع[a:5890[َن ن]َّفْسِه[n[ِۦ] وَإِ[g[نّ]َهُ[n[ۥ] لَمِنَ [h:6711[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","У: «Юсуфнинг нафсини хоҳлаган вақтингиздаги ишингиз нима эди?» деди. Улар: «Аллоҳ сақласин! Биз унда бирон ёмонлик сезмадик», дедилар. Азизнинг хотини: «Энди ҳақиқат зоҳир бўлди. Мен унинг нафсини хоҳладим. Албатта, у содиқлардандир.",241,12],["ذ[n[َٲ]لِكَ لِيَعْلَمَ أَ[g[نّ]ِى لَمْ أَخُنْهُ بِ[h:13[ٱ]لْغَيْبِ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ لَا يَهْدِى كَيْدَ [h:6712[ٱ]لْخ[o[َا]ٓئِن[p[ِي]نَ","Бу мен унга йўғида орқасидан хиёнат қилмаганимни, албатта, Аллоҳ хоинларнинг макрини тўғриликка йўлламаслигини билиши учундир.",241,12],["۞ وَم[o[َآ] أُبَرِّئُ نَفْس[o[ِىٓ‌ۚ] إِ[g[نّ]َ [h:6713[ٱ][l[ل][g[نّ]َفْسَ لَأَ[g[مّ]َارَ[i:6714[ةُۢ ب]ِ[h:875[ٱ][l[ل]سّ[o[ُو]ٓءِ إِلَّا مَا رَحِمَ رَبّ[o[ِىٓ‌ۚ] إِ[g[نّ]َ رَبِّى غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Ва ўз нафсимни оқламайман. Албатта, нафс, агар Роббим раҳм қилмаса, ёмонликка кўп ундовчидир. Албатта, Роббим мағфиратли ва билгувчидир», деди..",242,13],["وَقَالَ [h:6674[ٱ]لْمَلِكُ [h:6701[ٱ]ئْتُونِى بِه[o[ِۦٓ] أَسْتَخْلِصْهُ لِنَفْسِى‌ۖ فَلَ[g[مّ]َا كَلَّمَهُ[n[ۥ] قَالَ إِ[g[نّ]َكَ [h:6715[ٱ]لْيَوْمَ لَدَيْنَا مَكِينٌ أَم[p[ِي]نٌ","Подшоҳ: «Уни менга келтиринглар, уни ўзимга хос кишилардан қилиб оламан», деди. У билан гаплашганда эса: «Албатта, сен бугунги кунда ҳузуримизда маконатли ва ишончли кишилардансан», деди.",242,13],["قَالَ [h:6716[ٱ][q:6717[جْ]عَلْنِى عَلَىٰ خَز[o[َا]ٓئِنِ [h:6718[ٱ]لْأَرْضِ‌ۖ إِ[g[نّ]ِى حَفِيظٌ عَل[p[ِي]مٌ","У: «Мени ернинг хазиналари устига қўй. Албатта, мен муҳофаза қилувчи ва билувчиман», деди.",242,13],["وَكَذ[n[َٲ]لِكَ مَكَّ[g[نّ]َا لِيُوسُفَ فِى [h:44[ٱ]لْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَش[o[َا]ٓءُ‌ۚ نُصِيبُ بِرَحْمَتِنَا م[a:4211[َن ن]َّش[o[َا]ٓءُ‌ۖ وَلَا نُضِيعُ أَ[q:2418[جْ]رَ [h:5898[ٱ]لْمُحْسِن[p[ِي]نَ","Шундай қилиб, Юсуфга ер юзида маконат бердик, уни ўзи хоҳлаган жойга ерлаша оладиган қилдик. Ўз раҳматимизни, кимни хоҳласак, ўшанга муяссар этурмиз ва гўзал амал қилувчиларнинг ажрини зое қилмасмиз.",242,13],["وَلَأَ[q:6719[جْ]رُ [h:6720[ٱ]لْأَخِرَةِ خَيْ[u:4005[رٌ ل]ِّلَّذِينَ ءَامَنُو[s[اْ] وَكَانُو[s[اْ] يَتَّق[p[ُو]نَ","Иймон келтирган ва тақво қилганлар учун, албатта, охиратдаги ажр яхшироқ бўлур.",242,13],["وَج[o[َا]ٓءَ إِخْوَةُ يُوسُفَ فَدَخَلُو[s[اْ] عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُ[n[ۥ] مُ[f:6721[نك]ِر[p[ُو]نَ","Юсуфнинг оға-инилари келдилар ва унинг ҳузурига кирдилар. Бас, у уларни таниди. Улар эса, уни танимадилар.",242,13],["وَلَ[g[مّ]َا جَهَّزَه[c:6722[ُم ب]ِجَهَازِهِمْ قَالَ [h:6723[ٱ]ئْتُونِى بِأَ[u:6724[خٍ ل]َّك[w:556[ُم م]ِّنْ أَبِيكُمْ‌ۚ أَلَا تَرَوْنَ أَ[g[نّ][o[ِىٓ] أُوفِى [h:6725[ٱ]لْكَيْلَ وَأَنَا۟ خَيْرُ [h:6726[ٱ]لْمُ[f:6727[نز]ِل[p[ِي]نَ","Уларнинг жиҳозларини юклаган вақтда: «Менинг ҳузуримга ота бир инингизни олиб келинг. Кўраяпсизларми? Мен ўлчовни тўла қилмоқдаман ва мен энг яхши мезбонман.",242,13],["فَإ[u:110[ِن ل]َّمْ تَأْتُونِى بِه[n[ِۦ] فَلَا كَيْلَ لَكُمْ عِ[f:4065[ند]ِى وَلَا تَ[q:6728[قْ]رَب[p[ُو]نِ","Агар уни ҳузуримга олиб келмасангиз, унда сизга менинг даргоҳимда ўлчаб бериш йўқ ва менга яқин ҳам келманглар», деди.",242,13],["قَالُو[s[اْ] سَنُر[n[َٲ]وِدُ عَنْهُ أَبَاهُ وَإِ[g[نّ]َا لَفَ[n[ـٰ]عِل[p[ُو]نَ","Улар: «Уни отасидан сўраб олиб келишга уринамиз. Биз бу ишни, албатта, қилурмиз», дедилар.",242,13],["وَقَالَ لِفِتْيَ[n[ـٰ]نِهِ [h:6729[ٱ][q:6730[جْ]عَلُو[s[اْ] بِضَ[n[ـٰ]عَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَه[o[َآ] إِذَا [h:6731[ٱ][f:6732[نق]َلَب[o[ُوٓ][s[اْ] إِلَ[o[ىٰٓ] أَهْلِهِمْ لَعَلَّهُمْ يَرْجِع[p[ُو]نَ","У ўз йигитларига: «Уларнинг сармояларини юклари ичига солиб қўйинглар. Шояд улар аҳлларига борганларида буларни таниб, қайтиб келсалар», деди.",242,13],["فَلَ[g[مّ]َا رَجَع[o[ُوٓ][s[اْ] إِلَ[o[ىٰٓ] أَبِيهِمْ قَالُو[s[اْ] يَ[o[ـٰٓ]أَبَانَا مُنِعَ مِ[g[نّ]َا [h:6733[ٱ]لْكَيْلُ فَأَرْسِلْ مَعَن[o[َآ] أَخَانَا نَكْتَلْ وَإِ[g[نّ]َا لَهُ[n[ۥ] لَحَ[n[ـٰ]فِظ[p[ُو]نَ","Оталари ҳузурига қайтиб борганларида: «Эй отамиз, бизга ўлчаб бериш ман этилди. Биз билан инимизни юбор, ўлчаб оламиз ва, албатта, биз уни муҳофаза қилувчилармиз», дедилар.",242,13],["قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَم[o[َآ] أَمِ[f:6734[نت]ُكُمْ عَلَ[o[ىٰٓ] أَخِيهِ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ فَ[h:591[ٱ]للَّهُ خَيْرٌ حَ[n[ـٰ]فِ[a:6735[ظًا‌ۖ و]َهُوَ أَرْحَمُ [h:5034[ٱ][l[ل]رّ[n[َٲ]حِم[p[ِي]نَ","У: «Уни сизларга худди акасини ишонганимдек ишониб топширайми? Аллоҳнинг Ўзи энг яхши муҳофазачи ва Унинг Ўзи раҳмлиларнинг энг раҳмлигидир», деди.",243,13],["وَلَ[g[مّ]َا فَتَحُو[s[اْ] مَتَ[n[ـٰ]عَهُمْ وَجَدُو[s[اْ] بِضَ[n[ـٰ]عَتَهُمْ رُدَّتْ إِلَيْهِمْ‌ۖ قَالُو[s[اْ] يَ[o[ـٰٓ]أَبَانَا مَا نَ[q:6736[بْ]غِى‌ۖ هَ[n[ـٰ]ذِه[n[ِۦ] بِضَ[n[ـٰ]عَتُنَا رُدَّتْ إِلَيْنَا‌ۖ وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِي[f:6737[رٍ‌ۖ ذ][n[َٲ]لِكَ كَيْ[a:6738[لٌ ي]َس[p[ِي]رٌ","Юкларини очган пайтда, сармояларининг ўзларига қайтарилганини билдилар. «Эй отамиз, яна нима истаймиз? Мана, сармояларимиз ўзимизга қайтарилибди. Яна аҳлимизга зод келтирурмиз, укамизни муҳофаза қилиб, бир туя зиёда ўлчови оламиз. Бу озгина ўлчовдир», дедилар.",243,13],["قَالَ لَنْ أُرْسِلَهُ[n[ۥ] مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِ[a:6739[قًا م]ِّنَ [h:321[ٱ]للَّهِ لَتَأْتُ[g[نّ]َنِى بِه[o[ِۦٓ] إِلّ[o[َآ] أ[a:6740[َن ي]ُحَاطَ بِكُمْ‌ۖ فَلَ[g[مّ][o[َآ] ءَاتَوْهُ مَوْثِقَهُمْ قَالَ [h:1961[ٱ]للَّهُ عَلَىٰ مَا نَقُولُ وَك[p[ِي]لٌ","У: «Токи менга, албатта, ҳузуримга қайта келтиришингиз ҳақида Аллоҳдан васийқа бермагунингизча, уни зинҳор сиз ила юбормасман. Магар ўралиб қолсангиз, бошқа гап», деди. Унга васийқаларини берганларида, у: «Айтган гапларимизга Аллоҳ вакилдир», деди.",243,13],["وَقَالَ يَ[n[ـٰ]بَنِىَّ لَا تَ[q:1176[دْ]خُلُو[s[اْ] م[i:6741[ِنۢ ب]َا[a:6742[بٍ و][n[َٲ]حِ[a:6743[دٍ و]َ[h:281[ٱ][q:281[دْ]خُلُو[s[اْ] مِنْ أَ[q:6744[بْ]و[n[َٲ][a:6745[بٍ م]ُّتَفَرِّقَ[a:6746[ةٍ‌ۖ و]َم[o[َآ] أُغْنِى عَ[f:255[نك][w:6747[ُم م]ِّنَ [h:321[ٱ]للَّهِ مِ[f:2103[ن ش]َىْءٍ‌ۖ إِنِ [h:4101[ٱ]لْحُكْمُ إِلَّا لِلَّهِ‌ۖ عَلَيْهِ تَوَكَّلْتُ‌ۖ وَعَلَيْهِ فَلْيَتَوَكَّلِ [h:6748[ٱ]لْمُتَوَكِّل[p[ُو]نَ","У: «Эй ўғилларим, битта эшикдан кирманглар, турли эшиклардан киринглар. Мен сизлардан Аллоҳнинг ҳеч нарсасини қайтара олмасман. Ҳукм қилиш фақат Аллоҳнинг Ўзига хосдир. Унгагина таваккал қилдим. Таваккал қилгувчилар фақат Унгагина таваккал қилсинлар», деди.",243,13],["وَلَ[g[مّ]َا دَخَلُو[s[اْ] مِنْ حَيْثُ أَمَرَهُمْ أَبُوه[w:6749[ُم م]َّا كَانَ يُغْنِى عَنْه[w:6750[ُم م]ِّنَ [h:321[ٱ]للَّهِ مِ[f:2103[ن ش]َىْءٍ إِلَّا حَاجَ[f:6751[ةً ف]ِى نَفْسِ يَعْقُوبَ قَضَ[n[ـٰ]هَا‌ۚ وَإِ[g[نّ]َهُ[n[ۥ] لَذُو عِلْ[u:6752[مٍ ل]ِّمَا عَلَّمْنَ[n[ـٰ]هُ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Оталари амр этган томондан кирдилар. Зотан, бу улардан Аллоҳнинг ҳеч бир нарсасини қайтара олмас эди. Магар Яъқубнинг кўнглидаги эҳтиёж бўлиб, уни қондирди, холос. Албатта, у Биз таълим берганимиз туфайли билим соҳиби эди. Лекин кўпчилик одамлар билмаслар.",243,13],["وَلَ[g[مّ]َا دَخَلُو[s[اْ] عَلَىٰ يُوسُفَ ءَاوَ[o[ىٰٓ] إِلَيْهِ أَخَاهُ‌ۖ قَالَ إِ[g[نّ][o[ِىٓ] أَنَا۟ أَخُوكَ فَلَا تَ[q:6317[بْ]تَئِسْ بِمَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Юсуфнинг олдига кирганларида, у инисини ўзига яқин жойлаштирди ва: «Мен акангман, улар қилган нарсалардан хафа бўлма», деди.",243,13],["فَلَ[g[مّ]َا جَهَّزَه[c:6722[ُم ب]ِجَهَازِهِمْ جَعَلَ [h:6753[ٱ][l[ل]سِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُ[g[مّ]َ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا [h:6754[ٱ]لْعِيرُ إِ[g[نّ]َكُمْ لَسَ[n[ـٰ]رِق[p[ُو]نَ","Уларнинг жиҳозларини ҳозирлаган пайтда, инисининг юкига бир сув идишни солиб қўйди. Сўнгра жарчи: «Эй карвондагилар, сизлар ўғридирсизлар», деб жар солди.",244,13],["قَالُو[s[اْ] وَأَ[q:6755[قْ]بَلُو[s[اْ] عَلَيْه[w:6756[ِم م]َّاذَا تَفْقِد[p[ُو]نَ","Улар қараб: «Нима йўқотдингиз?» дедилар.",244,13],["قَالُو[s[اْ] نَفْقِدُ صُوَاعَ [h:6757[ٱ]لْمَلِكِ وَلِمَ[f:6758[ن ج][o[َا]ٓءَ بِه[n[ِۦ] حِمْلُ بَعِي[a:6759[رٍ و]َأَنَا۟ بِه[n[ِۦ] زَع[p[ِي]مٌ","Улар: «Подшоҳнинг идишини йўқотдик. Уни келтирган кишига бир туя юк. Мен унга кафилман», деди.",244,13],["قَالُو[s[اْ] تَ[h:6760[ٱ]للَّهِ لَقَ[q:2389[دْ] عَلِمْت[w:6761[ُم م]َّا جِئْنَا لِنُفْسِدَ فِى [h:44[ٱ]لْأَرْضِ وَمَا كُ[g[نّ]َا سَ[n[ـٰ]رِق[p[ِي]نَ","Улар: «Аллоҳга қасамки, ўзингиз биласиз, биз ер юзида фасод учун келган эмасмиз, биз ўғрилар бўлган эмасмиз», дедилар.",244,13],["قَالُو[s[اْ] فَمَا جَز[o[َٲ]ٓؤُهُ[o[ۥٓ] إِ[f:109[ن ك]ُ[f:100[نت]ُمْ كَ[n[ـٰ]ذِب[p[ِي]نَ","Улар: «Агар ёлғончи бўлиб чиқсангиз, жазоси нима?» дедилар.",244,13],["قَالُو[s[اْ] جَز[o[َٲ]ٓؤُهُ[n[ۥ] م[a:6762[َن و]ُجِدَ فِى رَحْلِه[n[ِۦ] فَهُوَ جَز[o[َٲ]ٓؤُهُ[n[ۥ]‌ۚ كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4693[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Улар: «Унинг жазоси, кимнинг юкида топилса, ўшадир. Бас, унинг жазоси ўшадир. Золимни шундай жазолаймиз», дедилар.",244,13],["فَبَدَأَ بِأَوْعِيَتِهِمْ قَ[q:3282[بْ]لَ وِع[o[َا]ٓءِ أَخِيهِ ثُ[g[مّ]َ [h:6763[ٱ]سْتَخْرَجَهَا م[a:6764[ِن و]ِع[o[َا]ٓءِ أَخِيهِ‌ۚ كَذ[n[َٲ]لِكَ كِ[q:6765[دْ]نَا لِيُوسُفَ‌ۖ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ [h:6766[ٱ]لْمَلِكِ إِلّ[o[َآ] أ[a:4201[َن ي]َش[o[َا]ٓءَ [h:4334[ٱ]للَّهُ‌ۚ نَرْفَعُ دَرَجَ[n[ـٰ][a:4210[تٍ م]ّ[a:4211[َن ن]َّش[o[َا]ٓءُ‌ۗ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَل[p[ِي]مٌ","У инисининг юкидан олдин уларнинг юкидан бошлади. Сўнгра уни унинг юкидан чиқариб олди. Шундай қилиб, Юсуф фойдасига ҳийла қилдик. У подшоҳнинг дини бўйича инисини олиб қола олмас эди. Магар Аллоҳ хоҳласагина, бўлиши мумкин эди. Кимни хоҳласак, ўшанинг даражасини кўтарамиз. Ҳар бир илм эгаси устидан билувчи бор.",244,13],["۞ قَال[o[ُوٓ][s[اْ] إ[a:6767[ِن ي]َسْرِ[q:6768[قْ] فَقَ[q:563[دْ] سَرَقَ أَ[u:6769[خٌ ل]َّهُ[n[ۥ] مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۚ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِه[n[ِۦ] وَلَمْ يُ[q:6770[بْ]دِهَا لَهُمْ‌ۚ قَالَ أَ[f:428[نت]ُمْ شَ[a:3659[رٌّ م]َّكَا[a:6771[نًا‌ۖ و]َ[h:72[ٱ]للَّهُ أَعْلَمُ بِمَا تَصِف[p[ُو]نَ","Улар: «Агар бу ўғирлаган бўлса, бундан олдин унинг акаси ҳам ўғирлаган эди», дедилар. Юсуф буни кўнглига тугиб қўйди, уларга ошкор қилмади. «Ўзингиз ёмонроқ турумдасиз. Аллоҳ сиз васф қилаётган нарсани яхши билгувчи зотдир», деди.",244,13],["قَالُو[s[اْ] يَ[o[ـٰٓ]أَيُّهَا [h:6772[ٱ]لْعَزِيزُ إِ[g[نّ]َ لَهُ[o[ۥٓ] أَ[f:6773[بًا ش]َيْ[f:6774[خًا ك]َبِي[f:6775[رًا ف]َخُذْ أَحَدَنَا مَكَانَهُ[o[ۥٓ‌ۖ] إِ[g[نّ]َا نَرَ[n[ٮٰ]كَ مِنَ [h:4754[ٱ]لْمُحْسِن[p[ِي]نَ","Улар: «Эй Азиз, бунинг катта ёшли чол отаси бор. Бас, биримизни унинг ўрнига ол. Биз сени яхшилик қилувчилардан эканлигингни кўрмоқдамиз», дедилар.",244,13],["قَالَ مَعَاذَ [h:6605[ٱ]للَّهِ أ[a:6776[َن ن]َّأْخُذَ إِلَّا م[a:6777[َن و]َجَ[q:3834[دْ]نَا مَتَ[n[ـٰ]عَنَا عِ[f:719[ند]َهُ[o[ۥٓ] إِ[g[نّ][o[َآ] إِ[u:6778[ذًا ل]َّظَ[n[ـٰ]لِم[p[ُو]نَ","У: «Нарсамизни ҳузуридан топган одамдан бошқани олиб қолишимиздан Аллоҳ сақласин. Акс ҳолда, албатта, золимлардан бўлиб қоламиз», деди.",245,13],["فَلَ[g[مّ]َا [h:6779[ٱ]سْتَيْــَٔسُو[s[اْ] مِنْهُ خَلَصُو[s[اْ] نَجِي[f:6780[ًّا‌ۖ ق]َالَ كَبِيرُهُمْ أَلَمْ تَعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ أَبَاكُمْ قَ[q:298[دْ] أَخَذَ عَلَيْك[w:6781[ُم م]َّوْثِ[a:6739[قًا م]ِّنَ [h:321[ٱ]للَّهِ وَمِ[f:6432[ن ق]َ[q:129[بْ]لُ مَا فَرَّطتُمْ فِى يُوسُفَ‌ۖ فَلَنْ أَ[q:6782[بْ]رَحَ [h:6783[ٱ]لْأَرْضَ حَتَّىٰ يَأْذَنَ ل[o[ِىٓ] أَب[o[ِىٓ] أَوْ يَحْكُمَ [h:4856[ٱ]للَّهُ لِى‌ۖ وَهُوَ خَيْرُ [h:4857[ٱ]لْحَ[n[ـٰ]كِم[p[ِي]نَ","Ундан умидни узган чоғларида, четга чиқиб, хуфёна маслаҳат қилдилар. Катталари: «Отангиз сиздан Аллоҳ номи билан васийқа олганини ва бундан олдин Юсуф ҳақида қилган айбингизни билмайсизларми?! Мен токи отам менга изн бермагунча ёки Аллоҳ ҳукм чиқармагунча бу ердан қимирламасман. У ҳукм чиқарувчиларнинг энг яхшисидир.",245,13],["ٱرْجِع[o[ُوٓ][s[اْ] إِلَ[o[ىٰٓ] أَبِيكُمْ فَقُولُو[s[اْ] يَ[o[ـٰٓ]أَبَان[o[َآ] إِ[g[نّ]َ [h:6784[ٱ][q:6785[بْ]نَكَ سَرَقَ وَمَا شَهِ[q:4421[دْ]ن[o[َآ] إِلَّا بِمَا عَلِمْنَا وَمَا كُ[g[نّ]َا لِلْغَيْبِ حَ[n[ـٰ]فِظ[p[ِي]نَ","Отангиз олдига қайтинглар, бас, унга: «Эй отамиз, ҳақиқатда ўғлинг ўғрилик қилди. Биз фақат ўзимиз билган нарсага гувоҳлик бердик, холос. Биз ғайбни билувчи эмас эдик.",245,13],["وَسْــَٔلِ [h:6786[ٱ]لْقَرْيَةَ [h:6787[ٱ]لَّتِى كُ[g[نّ]َا فِيهَا وَ[h:6788[ٱ]لْعِيرَ [h:6789[ٱ]لَّت[o[ِىٓ] أَ[q:6790[قْ]بَلْنَا فِيهَا‌ۖ وَإِ[g[نّ]َا لَصَ[n[ـٰ]دِق[p[ُو]نَ","Биз бўлган шаҳардан сўра ва у ерда биз учраган карвондан сўра, биз, албатта, ростгўйларданмиз, денглар», деди.",245,13],["قَالَ بَلْ سَوَّلَتْ لَكُمْ أَ[f:6579[نف]ُسُكُمْ أَمْ[f:6580[رًا‌ۖ ف]َصَ[q:6581[بْ][f:6582[رٌ ج]َمِيلٌ‌ۖ عَسَى [h:2982[ٱ]للَّهُ أ[a:6791[َن ي]َأْتِيَنِى بِهِمْ جَمِيعًا‌ۚ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:6792[ٱ]لْعَلِيمُ [h:171[ٱ]لْحَك[p[ِي]مُ","У: «Йўқ, сизга ҳавои нафсингиз бир ишни яхши кўрсатмиш. Бас, чиройли сабр. Шоядки Аллоҳ уларнинг ҳаммасини ҳузуримга жамлаб келтирса. Албатта, Унинг Ўзи билгувчи ва ҳикматли зотдир», деди.",245,13],["وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَ[o[ـٰٓ]أَسَفَىٰ عَلَىٰ يُوسُفَ وَ[h:6793[ٱ][q:6793[بْ]يَضَّتْ عَيْنَاهُ مِنَ [h:6794[ٱ]لْحُزْنِ فَهُوَ كَظ[p[ِي]مٌ","Ва улардан юз ўгирди ҳамда: «Оҳ, Юсуф!!!» деб кўзларига оқ тушди. Бас, у дардини ютувчидир.",245,13],["قَالُو[s[اْ] تَ[h:6760[ٱ]للَّهِ تَفْتَؤُ[s[اْ] تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ [h:6795[ٱ]لْهَ[n[ـٰ]لِك[p[ِي]نَ","Улар: «Аллоҳга қасамки, токи мадордан кетгунингча ёки ҳалок бўлувчилардан бўлгунингча, Юсуфни зикр қилаверасан», дедилар.",245,13],["قَالَ إِ[g[نّ]َم[o[َآ] أَشْكُو[s[اْ] بَثِّى وَحُزْن[o[ِىٓ] إِلَى [h:1637[ٱ]للَّهِ وَأَعْلَمُ مِنَ [h:321[ٱ]للَّهِ مَا لَا تَعْلَم[p[ُو]نَ","У: «Албатта, мен дарду ҳасратимдан фақат Аллоҳнинг Ўзига шикоят қилмоқдаман ва Аллоҳдан сиз билмаган нарсани биламан.",245,13],["يَ[n[ـٰ]بَنِىَّ [h:6796[ٱ]ذْهَبُو[s[اْ] فَتَحَسَّسُو[s[اْ] م[a:6797[ِن ي]ُوسُفَ وَأَخِيهِ وَلَا تَ[s[اْ]يْــَٔسُو[s[اْ] م[u:6798[ِن ر]َّوْحِ [h:6799[ٱ]للَّهِ‌ۖ إِ[g[نّ]َهُ[n[ۥ] لَا يَ[s[اْ]يْــَٔسُ م[u:6798[ِن ر]َّوْحِ [h:6799[ٱ]للَّهِ إِلَّا [h:4061[ٱ]لْقَوْمُ [h:6800[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Эй ўғилларим, боринглар, Юсуфни ва унинг укасини яхшилаб изланглар, Аллоҳнинг раҳматидан ноумид бўлманглар. Ҳақиқатда Аллоҳнинг раҳматидан фақат кофир қавмларгина ноумид бўлурлар», деди.",246,13],["فَلَ[g[مّ]َا دَخَلُو[s[اْ] عَلَيْهِ قَالُو[s[اْ] يَ[o[ـٰٓ]أَيُّهَا [h:6772[ٱ]لْعَزِيزُ مَسَّنَا وَأَهْلَنَا [h:6801[ٱ][l[ل]ضُّرُّ وَجِئْنَا بِبِضَ[n[ـٰ]عَ[a:6802[ةٍ م]ُّزْجَ[n[ـٰ][f:6803[ةٍ ف]َأَوْفِ لَنَا [h:6804[ٱ]لْكَيْلَ وَتَصَدَّ[q:6805[قْ] عَلَيْن[o[َآ‌ۖ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَ[q:6806[جْ]زِى [h:6807[ٱ]لْمُتَصَدِّق[p[ِي]نَ","Унинг ҳузурига кирганларида: «Эй Азиз, бизни ва аҳлимизни зарар тутди ва арзимаган сармоя келтирдик. Бас, бизга ўлчовни тўлиқ қилиб бер ва садақа ҳам бер. Аллоҳ, албатта, садақа қилувчиларни мукофотлайдир», дедилар.",246,13],["قَالَ هَلْ عَلِمْت[w:6761[ُم م]َّا فَعَلْت[c:6808[ُم ب]ِيُوسُفَ وَأَخِيهِ إِذْ أَ[f:428[نت]ُمْ جَ[n[ـٰ]هِل[p[ُو]نَ","У: «Жоҳиллик пайтингизда Юсуфга ва унинг инисига нима қилганларингизни биласизларми?» деди.",246,13],["قَال[o[ُوٓ][s[اْ] أَءِ[g[نّ]َكَ لَأَ[f:6457[نت]َ يُوسُفُ‌ۖ قَالَ أَنَا۟ يُوسُفُ وَهَ[n[ـٰ]ذ[o[َآ] أَخِى‌ۖ قَ[q:298[دْ] مَ[g[نّ]َ [h:2390[ٱ]للَّهُ عَلَيْن[o[َآ‌ۖ] إِ[g[نّ]َهُ[n[ۥ] م[a:6809[َن ي]َتَّقِ وَيَصْبِرْ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ لَا يُضِيعُ أَ[q:2418[جْ]رَ [h:5898[ٱ]لْمُحْسِن[p[ِي]نَ","Улар: «Э-э, ҳали сенн сенн Юсуфмисан?!» дедилар. У: «Мен Юсуфман, мана бу иним. Аллоҳ бизга марҳамат кўрсатди. Ҳақиқатда ким тақво ва сабр қилса, Аллоҳ, албатта, гўзал иш қилувчиларнинг ажрини зое қилмагай», деди.",246,13],["قَالُو[s[اْ] تَ[h:6760[ٱ]للَّهِ لَقَ[q:2389[دْ] ءَاثَرَكَ [h:6810[ٱ]للَّهُ عَلَيْنَا وَإِ[f:4542[ن ك]ُ[g[نّ]َا لَخَ[n[ـٰ]طِــٔ[p[ِي]نَ","Улар: «Аллоҳга қасамки, ҳақиқатда Аллоҳ сени биздан устун қилди. Биз эса, хатокорлардан бўлдик», дедилар.",246,13],["قَالَ لَا تَثْرِيبَ عَلَيْكُمُ [h:6811[ٱ]لْيَوْمَ‌ۖ يَغْفِرُ [h:6812[ٱ]للَّهُ لَكُمْ‌ۖ وَهُوَ أَرْحَمُ [h:5034[ٱ][l[ل]رّ[n[َٲ]حِم[p[ِي]نَ","У: «Бугунги кунда сизларни айблаш йўқ. Сизларни Аллоҳ мағфират қилгай. У раҳм қилгувчиларнинг раҳмлироғидир.",246,13],["ٱذْهَبُو[s[اْ] بِقَمِيصِى هَ[n[ـٰ]ذَا فَأَلْقُوهُ عَلَىٰ وَ[q:1611[جْ]هِ أَبِى يَأْتِ بَصِي[a:6813[رًا و]َأْتُونِى بِأَهْلِكُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Менинг мана бу кўйлагимни олиб бориб, отамнинг юзига ташлангиз, кўзи очилур. Сўнгра аҳлингиз ила жам бўлиб ҳузуримга келинглар», деди.",246,13],["وَلَ[g[مّ]َا فَصَلَتِ [h:6814[ٱ]لْعِيرُ قَالَ أَبُوهُمْ إِ[g[نّ]ِى لَأَجِدُ رِيحَ يُوسُفَ‌ۖ لَوْل[o[َآ] أَ[f:6815[ن ت]ُفَ[g[نّ]ِد[p[ُو]نِ","Карвон йўлга чиққан вақтда оталари: «Мени ақлдан озган деманглар-у, албатта, мен Юсуфнинг ҳидини сезмоқдаман», деди.",246,13],["قَالُو[s[اْ] تَ[h:6760[ٱ]للَّهِ إِ[g[نّ]َكَ لَفِى ضَلَ[n[ـٰ]لِكَ [h:6816[ٱ]لْقَد[p[ِي]مِ","Улар: «Аллоҳга қасамки, сен эски адашувингдасан», дедилар.",246,13],["فَلَ[g[مّ][o[َآ] أَ[f:6417[ن ج][o[َا]ٓءَ [h:6817[ٱ]لْبَشِيرُ أَلْقَ[n[ـٰ]هُ عَلَىٰ وَ[q:6818[جْ]هِه[n[ِۦ] فَ[h:6819[ٱ]رْتَدَّ بَصِي[f:6820[رًا‌ۖ ق]َالَ أَلَمْ أَقُل لَّكُمْ إِ[g[نّ][o[ِىٓ] أَعْلَمُ مِنَ [h:321[ٱ]للَّهِ مَا لَا تَعْلَم[p[ُو]نَ","Хушхабарчи келган чоғида у ни унинг юзига ташлаганида, яна кўрадиган бўлди. У: «Сизларга мен, Аллоҳдан сизлар билмайдиган нарсани биламан, демаганмидим?!» деди.",247,13],["قَالُو[s[اْ] يَ[o[ـٰٓ]أَبَانَا [h:6821[ٱ]سْتَغْفِرْ لَنَا ذُنُوبَن[o[َآ] إِ[g[نّ]َا كُ[g[نّ]َا خَ[n[ـٰ]طِــٔ[p[ِي]نَ","Улар: «Эй отамиз, гуноҳларимиз учун истиғфор айт. Албатта, биз хатокорлардан бўлган эканмиз», дедилар.",247,13],["قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبّ[o[ِىٓ‌ۖ] إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:6822[ٱ]لْغَفُورُ [h:6228[ٱ][l[ل]رَّح[p[ِي]مُ","У: «Сизлар учун Роббимга сўнгра истиғфор айтаман. Албатта, Унинг Ўзи мағфират қилгувчи ва раҳмли Зотдир», деди.",247,13],["فَلَ[g[مّ]َا دَخَلُو[s[اْ] عَلَىٰ يُوسُفَ ءَاوَ[o[ىٰٓ] إِلَيْهِ أَبَوَيْهِ وَقَالَ [h:6823[ٱ][q:278[دْ]خُلُو[s[اْ] مِصْرَ إِ[f:364[ن ش][o[َا]ٓءَ [h:78[ٱ]للَّهُ ءَامِن[p[ِي]نَ","Юсуф ҳузурига кирган чоғларида у отаси ва онасини ўзига яқинлаштирди ва: «Аллоҳнинг хоҳиши ила Мисрга омонликда киринглар!» деди.",247,13],["وَرَفَعَ أَبَوَيْهِ عَلَى [h:4740[ٱ]لْعَرْشِ وَخَرُّو[s[اْ] لَهُ[n[ۥ] سُجَّ[a:6824[دًا‌ۖ و]َقَالَ يَ[o[ـٰٓ]أَبَتِ هَ[n[ـٰ]ذَا تَأْوِيلُ رُءْيَ[n[ـٰ]ىَ مِ[f:128[ن ق]َ[q:129[بْ]لُ قَ[q:298[دْ] جَعَلَهَا رَبِّى حَق[a:6825[ًّا‌ۖ و]َقَ[q:387[دْ] أَحْسَنَ ب[o[ِىٓ] إِذْ أَخْرَجَنِى مِنَ [h:6826[ٱ][l[ل]سِّ[q:6659[جْ]نِ وَج[o[َا]ٓءَ بِك[w:6827[ُم م]ِّنَ [h:6828[ٱ]لْبَ[q:6829[دْ]وِ م[i:146[ِنۢ ب]َعْدِ أ[a:6830[َن ن]َّزَغَ [h:6831[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ بَيْنِى وَبَيْنَ إِخْوَت[o[ِىٓ‌ۚ] إِ[g[نّ]َ رَبِّى لَطِي[u:6832[فٌ ل]ِّمَا يَش[o[َا]ٓءُ‌ۚ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:6792[ٱ]لْعَلِيمُ [h:171[ٱ]لْحَك[p[ِي]مُ","Ва ота-онасини тахтга кўтарди. Улар унга сажда қилиб йиқилдилар. У: «Эй отажон, бу аввал кўрган тушимнинг таъбиридир, Роббим уни ҳаққа айлантирди. Дарҳақиқат, У менга яхшилик қилди. Мени қамоқдан чиқарди. Шайтон мен билан акаларимнинг орасини бузгандан сўнг, сизларни биёбондан олиб келди. Албатта, Роббим нимани хоҳласа, ўшанга латифдир. Албатта, Унинг Ўзи билгувчи ва ҳикматли зотдир.",247,13],["۞ رَبِّ قَ[q:298[دْ] ءَاتَيْتَنِى مِنَ [h:2845[ٱ]لْمُلْكِ وَعَلَّمْتَنِى مِ[f:6551[ن ت]َأْوِيلِ [h:6552[ٱ]لْأَحَادِيثِ‌ۚ فَاطِرَ [h:6833[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ أَ[f:169[نت]َ وَلِىّ[n[ِۦ] فِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ‌ۖ تَوَفَّنِى مُسْلِ[a:6834[مًا و]َأَلْحِ[q:6835[قْ]نِى بِ[h:6836[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Эй Роббим, ҳақиқатда менга мулк бердинг ва менга тушларнинг таъбирини ўргатдинг. Эй осмонлару ерни яратган зот! Сен дунёю охиратда менинг валиййимсан. Мени мусулмон ҳолимда вафот этдиргин ва солиҳларга қўшгин», деди.",247,13],["ذ[n[َٲ]لِكَ مِنْ أَ[i:1910[نۢب][o[َا]ٓءِ [h:1911[ٱ]لْغَيْبِ نُوحِيهِ إِلَيْكَ‌ۖ وَمَا كُ[f:735[نت]َ لَدَيْهِمْ إِذْ أَ[q:6837[جْ]مَع[o[ُوٓ][s[اْ] أَمْرَهُمْ وَهُمْ يَمْكُر[p[ُو]نَ","Бу ғайб хабарлардан бўлиб, уни сенга ваҳий қилмоқдамиз. Улар макр қилиб, ишлари ҳақида гап бириктирганларида олдиларида бўлмаган эдинг.",247,13],["وَم[o[َآ] أَكْثَرُ [h:6838[ٱ][l[ل][g[نّ]َاسِ وَلَوْ حَرَصْتَ بِمُؤْمِن[p[ِي]نَ","Одамларнинг кўплари, гарчи сен жуда қизиқсанг ҳам, мўмин эмаслар.",247,13],["وَمَا تَسْــَٔلُهُمْ عَلَيْهِ مِنْ أَ[q:6133[جْ]رٍ‌ۚ إِنْ هُوَ إِلَّا ذِكْ[u:6839[رٌ ل]ِّلْعَ[n[ـٰ]لَم[p[ِي]نَ","Сен улардан бунинг учун ажр ҳам сўрамайсан. У фақат оламлар учун эслатма, холос.",248,13],["وَكَأَيّ[a:2298[ِن م]ِّنْ ءَايَ[f:6840[ةٍ ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِض[p[ُو]نَ","Улар осмонлару ердаги қанчадан-қанча оят-белгилар қаршисидан юз ўгирган ҳолларида ўтарлар.",248,13],["وَمَا يُؤْمِنُ أَكْثَرُه[c:6841[ُم ب]ِ[h:32[ٱ]للَّهِ إِلَّا وَه[w:6842[ُم م]ُّشْرِك[p[ُو]نَ","Кўплари эса, Аллоҳга мушрик бўлган ҳолларидагина иймон келтирадилар, холос.",248,13],["أَفَأَمِن[o[ُوٓ][s[اْ] أَ[f:6843[ن ت]َأْتِيَهُمْ غَ[n[ـٰ]شِيَ[a:6844[ةٌ م]ِّنْ عَذَابِ [h:6845[ٱ]للَّهِ أَوْ تَأْتِيَهُمُ [h:6846[ٱ][l[ل]سَّاعَةُ بَغْتَ[a:4880[ةً و]َهُمْ لَا يَشْعُر[p[ُو]نَ","Улар ўзларига Аллоҳдан қамраб олувчи азоб келишидан ёки сезмай турганларида қиёмат ногаҳон келиб қолишидан омондамилар?!",248,13],["قُلْ هَ[n[ـٰ]ذِه[n[ِۦ] سَبِيل[o[ِىٓ] أَ[q:6847[دْ]ع[o[ُوٓ][s[اْ] إِلَى [h:1637[ٱ]للَّهِ‌ۚ عَلَىٰ بَصِيرَةٍ أَنَا۟ وَمَنِ [h:6848[ٱ]تَّبَعَنِى‌ۖ وَسُ[q:6849[بْ]حَ[n[ـٰ]نَ [h:6850[ٱ]للَّهِ وَم[o[َآ] أَنَا۟ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Сен: «Бу–менинг йўлимдир. Мен Аллоҳга билиб–ишонч ила чақираман ва менга эргашганлар ҳам. Аллоҳ покдир. Ва мен мушриклардан эмасман», деб айт.",248,13],["وَم[o[َآ] أَرْسَلْنَا مِ[f:18[ن ق]َ[q:19[بْ]لِكَ إِلَّا رِجَال[a:6851[اً ن]ُّوح[o[ِىٓ] إِلَيْه[w:3682[ِم م]ِّنْ أَهْلِ [h:6852[ٱ]لْقُرَ[o[ىٰٓ‌ۗ] أَفَلَمْ يَسِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَيَ[f:6853[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6854[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۗ وَلَدَارُ [h:6855[ٱ]لْأَخِرَةِ خَيْ[u:4005[رٌ ل]ِّلَّذِينَ [h:1785[ٱ]تَّقَوْ[s[اْ‌ۗ] أَفَلَا تَعْقِل[p[ُو]نَ","Биз сендан илгари ҳам фақат шаҳар аҳлидан эр кишиларга ваҳий юбориб, Пайғамбар этганмиз. Ер юзида юриб, ўзларидан олдингиларнинг оқибати нима бўлганига назар солмайдиларми? Албатта, охират диёри тақво қиладиганлар учун яхшироқдир. Ақл юритмайдиларми?!",248,13],["حَتَّ[o[ىٰٓ] إِذَا [h:6856[ٱ]سْتَيْــَٔسَ [h:6857[ٱ][l[ل]رُّسُلُ وَظَ[g[نّ][o[ُوٓ][s[اْ] أَ[g[نّ]َهُمْ قَ[q:298[دْ] كُذِبُو[s[اْ] ج[o[َا]ٓءَهُمْ نَصْرُنَا فَنُجِّىَ م[a:4211[َن ن]َّش[o[َا]ٓءُ‌ۖ وَلَا يُرَدُّ بَأْسُنَا عَنِ [h:4503[ٱ]لْقَوْمِ [h:4504[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","Ҳаттоки Пайғамбарлар ноумид бўлиб, ўзларини ёлғончига чиқарилганлар, деб гумон қилиб қолганларида, уларга Бизнинг нусратимиз келадир. Бас, Биз хоҳлаганларга нажот бериладир. Жиноятчи қавмлардан Бизнинг азобимиз қайтарилмас.",248,13],["لَقَ[q:2389[دْ] كَانَ فِى قَصَصِهِمْ عِ[q:6858[بْ]رَ[u:6859[ةٌ ل]ِّأُ[s[وْ]لِى [h:2496[ٱ]لْأَلْبَ[n[ـٰ]بِ‌ۗ مَا كَانَ حَدِي[a:6860[ثًا ي]ُفْتَرَىٰ وَلَ[n[ـٰ]كِ[f:6058[ن ت]َصْدِيقَ [h:6059[ٱ]لَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ ش[a:4536[َىْءٍ و]َهُ[a:4537[دًى و]َرَحْمَ[u:4735[ةً ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Батаҳқиқ, уларнинг қиссаларида ақл эгалари учун ибрат бор эди. Бу тўқима гап эмас, лекин ўзидан олдин келганни тасдиқлаш ва ҳар бир нарсани батафсил қилиш, ҳидоят ҳамда иймон келтирганлар учун раҳматдир.",248,13]]},{"n":13,"ar":"الرَّعۡدِ","en":"Ar-Ra'd","uz":"Раъд","type":"Мадина","ayahs":[["ا[m[لٓ][m[مٓ]ر‌ۚ تِلْكَ ءَايَ[n[ـٰ]تُ [h:5932[ٱ]لْكِتَ[n[ـٰ]بِ‌ۗ وَ[h:4765[ٱ]لَّذ[o[ِىٓ] أُ[f:17[نز]ِلَ إِلَيْكَ م[u:770[ِن ر]َّبِّكَ [h:6861[ٱ]لْحَقُّ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يُؤْمِن[p[ُو]نَ","Алиф. Лом. Мим. Ро. Ушбулар китобнинг оятларидир. Ва сенга Роббингдан нозил қилинган нарса ҳақдир. Лекин одамларнинг кўплари иймон келтирмаслар.",249,13],["ٱللَّهُ [h:4738[ٱ]لَّذِى رَفَعَ [h:6862[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ بِغَيْرِ عَمَ[f:6863[دٍ ت]َرَوْنَهَا‌ۖ ثُ[g[مّ]َ [h:156[ٱ]سْتَوَىٰ عَلَى [h:4740[ٱ]لْعَرْشِ‌ۖ وَسَخَّرَ [h:6864[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ‌ۖ كُ[a:6865[لٌّ ي]َ[q:6866[جْ]رِى لِأَجَ[a:6867[لٍ م]ُّسَم[a:6868[ًّى‌ۚ ي]ُدَبِّرُ [h:5940[ٱ]لْأَمْرَ يُفَصِّلُ [h:5952[ٱ]لْأَيَ[n[ـٰ]تِ لَعَلَّك[c:6869[ُم ب]ِلِق[o[َا]ٓءِ رَبِّكُمْ تُوقِن[p[ُو]نَ","Аллоҳ сиз кўриб турган осмонни устунсиз кўтарган, сўнгра аршга эга бўлган, қуёш ва ойни Ўзига бўйинсундирган зотдир. Ҳар бири номланган ажалгача юрадир. У ишнинг тадбирини қиладир, оятларни муфассал этадир. Шоядки Роббингизга мулоқот бўлишга ишонч ҳосил қилсангиз.",249,13],["وَهُوَ [h:4114[ٱ]لَّذِى مَدَّ [h:6870[ٱ]لْأَرْضَ وَجَعَلَ فِيهَا رَو[n[َٲ]سِىَ وَأَنْهَ[n[ـٰ][a:6871[رًا‌ۖ و]َمِ[f:4136[ن ك]ُلِّ [h:1571[ٱ][l[ل]ثَّمَر[n[َٲ]تِ جَعَلَ فِيهَا زَوْجَيْنِ [h:6331[ٱ]ثْنَيْنِ‌ۖ يُغْشِى [h:4741[ٱ]لَّيْلَ [h:4742[ٱ][l[ل][g[نّ]َهَارَ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:6018[مٍ ي]َتَفَكَّر[p[ُو]نَ","У ерни чўзиб, унда баланд тоғлар ва анҳорлар қилган, ҳар хил мевалардан жуфт-жуфт қилган зотдир. У кечани кундузга ўратур. Бунда, албатта, тафаккур қилувчи қавмлар учун оят-белгилар бордир.",249,13],["وَفِى [h:3922[ٱ]لْأَرْضِ قِطَ[a:6872[عٌ م]ُّتَجَ[n[ـٰ]وِر[n[َٲ][a:6873[تٌ و]َجَ[g[نّ]َ[n[ـٰ][a:6874[تٌ م]ِّنْ أَعْنَ[n[ـٰ][a:6875[بٍ و]َزَرْ[a:6876[عٌ و]َنَخِي[f:6877[لٌ ص]ِنْوَا[a:6878[نٌ و]َغَيْرُ صِنْوَا[a:6879[نٍ ي]ُسْقَىٰ بِم[o[َا]ٓ[a:6880[ءٍ و][n[َٲ]حِ[a:6881[دٍ و]َنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْ[f:6882[ضٍ ف]ِى [h:6883[ٱ]لْأُكُلِ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:850[مٍ ي]َعْقِل[p[ُو]نَ","Ва ер юзида қўшни бўлаклар бор. Шунингдек, узумлар, боғлар, экинзорлар, шохлаган ва шохламаган хурмолар бўлиб, бир хил сув ила суғориларлар ва уларнинг баъзиларининг мевасини баъзилариникидан афзал қиламиз. Бунда, албатта, ақл ишлатувчи қавмлар учун оят-белгилар бордир.",249,13],["۞ وَإِ[f:6884[ن ت]َعْجَ[q:6885[بْ] فَعَجَ[f:6886[بٌ ق]َوْلُهُمْ أَءِذَا كُ[g[نّ]َا تُر[n[َٲ]بًا أَءِ[g[نّ]َا لَفِى خَلْ[f:6887[قٍ ج]َدِيدٍ‌ۗ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِرَبِّهِمْ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:6888[ٱ]لْأَغْلَ[n[ـٰ]لُ ف[o[ِىٓ] أَعْنَاقِهِمْ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Агар ажабланадиган бўлсанг, уларнинг: «Агар биз тупроқ бўлиб кетсак ҳам, янгидан яратиламизми?!» дейишлари яна ҳам ажабланарлидир. Ана ўшалар Роббиларига куфр келтирганлардир. Ана ўшалар бўйинлари кишанларда бўлганлардир. Ана ўшалар дўзах эгаларидир. Улар унда абадий қолурлар.",249,13],["وَيَسْتَعْجِلُونَكَ بِ[h:4563[ٱ][l[ل]سَّيِّئَةِ قَ[q:3282[بْ]لَ [h:6889[ٱ]لْحَسَنَةِ وَقَ[q:387[دْ] خَلَتْ مِ[f:6890[ن ق]َ[q:6891[بْ]لِهِمُ [h:6892[ٱ]لْمَثُلَ[n[ـٰ]تُ‌ۗ وَإِ[g[نّ]َ رَبَّكَ لَذُو مَغْفِرَ[u:6893[ةٍ ل]ِّل[g[نّ]َاسِ عَلَىٰ ظُلْمِهِمْ‌ۖ وَإِ[g[نّ]َ رَبَّكَ لَشَدِيدُ [h:6894[ٱ]لْعِق[p[َا][q[ب]ِ","Улар сендан яхшиликдан аввал ёмонлик келтиришни талаб қилурлар. Ҳолбуки, улардан аввал мисоллар ўтмишдир. Ва, албатта, Роббинг одамларнинг зулмига қарамай, улар учун мағфиратлидир. Ва, албатта, Роббинг иқоби шиддатлидир.",250,13],["وَيَقُولُ [h:3629[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَوْل[o[َآ] أُ[f:17[نز]ِلَ عَلَيْهِ ءَايَ[a:4024[ةٌ م]ّ[u:192[ِن ر]َّبِّه[o[ِۦٓ‌ۗ] إِ[g[نّ]َم[o[َآ] أَ[f:169[نت]َ مُ[f:6895[نذ]ِ[a:6896[رٌ‌ۖ و]َلِكُلِّ قَوْمٍ ه[p[َا][q[د]ٍ","Куфр келтирганлар: «Унга Роббидан бир оят нозил қилинса эди», дерлар. Сен фақат огоҳлантирувчисан, холос. Ва ҳар қавмнинг ҳидоятчиси бордир.",250,13],["ٱللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُ[f:1867[نث]َىٰ وَمَا تَغِيضُ [h:6897[ٱ]لْأَرْحَامُ وَمَا تَزْدَادُ‌ۖ وَكُلُّ شَىْءٍ عِ[f:719[ند]َهُ[n[ۥ] بِمِ[q:6898[قْ]د[p[َا]رٍ","Аллоҳ ҳар бир урғочининг ҳомиласини ҳамда бачадонлар нуқсон ёки зиёда қиладиган нарсаларни биладир. Ҳар бир нарса Унинг ҳузурида ўлчовлидир.",250,13],["عَ[n[ـٰ]لِمُ [h:4186[ٱ]لْغَيْبِ وَ[h:4187[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ [h:6899[ٱ]لْكَبِيرُ [h:6900[ٱ]لْمُتَع[p[َا]لِ","У зот ғойибни ҳам, шоҳидни ҳам билгувчидир. У буюкдир, юксакдир.",250,13],["سَو[o[َا]ٓ[a:6901[ءٌ م]ِّ[f:344[نك][w:2322[ُم م]َّنْ أَسَرَّ [h:6902[ٱ]لْقَوْلَ وَمَ[f:6903[ن ج]َهَرَ بِه[n[ِۦ] وَمَنْ هُوَ مُسْتَخْ[i:6904[فِۭ ب]ِ[h:1622[ٱ]لَّيْلِ وَسَارِ[i:6905[بُۢ ب]ِ[h:4117[ٱ][l[ل][g[نّ]َه[p[َا]رِ","Сиздан ким гапни сир тутса, ким уни ошкор қилса ёки ким кечаси беркинувчи бўлсаю ким кундузи ошкор юрувчи бўлса, барибир.",250,13],["لَهُ[n[ۥ] مُعَقِّبَ[n[ـٰ][a:6906[تٌ م]ّ[i:4612[ِنۢ ب]َيْنِ يَدَيْهِ وَمِنْ خَلْفِه[n[ِۦ] يَحْفَظُونَهُ[n[ۥ] مِنْ أَمْرِ [h:6348[ٱ]للَّهِ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُو[s[اْ] مَا بِأَ[f:4384[نف]ُسِهِمْ‌ۗ وَإِذ[o[َآ] أَرَادَ [h:139[ٱ]للَّهُ بِقَوْ[f:6907[مٍ س][o[ُو]ٓ[f:6908[ءًا ف]َلَا مَرَدَّ لَهُ[n[ۥ]‌ۚ وَمَا لَه[w:1812[ُم م]ِّ[f:3136[ن د]ُونِه[n[ِۦ] م[a:6909[ِن و][p[َا]لٍ","Унинг олдида ҳам, ортида ҳам таъқиб қилгувчилар бор. Улар уни Аллоҳнинг амри ила ҳифз қилиб турурлар. Албатта, то бир қавм ўзларини ўзгартирмагунларича, Аллоҳ уларнинг ҳолини ўзгартирмас. Агар Аллоҳ бирор қавмга ёмонликни ирода қилса, бас, уни қайтариб бўлмас ва улар учун Ундан ўзга валий ҳам йўқ.",250,13],["هُوَ [h:153[ٱ]لَّذِى يُرِيكُمُ [h:6910[ٱ]لْبَرْقَ خَوْ[a:4752[فًا و]َطَمَ[a:6911[عًا و]َيُ[f:6912[نش]ِئُ [h:6913[ٱ][l[ل]سَّحَابَ [h:6914[ٱ][l[ل]ثِّق[p[َا]لَ","У сизларга чақмоқни хавф ва тамаъ қилиб кўрсатади ва оғир булутларни пайдо қилади.",250,13],["وَيُسَبِّحُ [h:6915[ٱ][l[ل]رَّعْدُ بِحَمْدِه[n[ِۦ] وَ[h:1146[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ مِنْ خِيفَتِه[n[ِۦ] وَيُرْسِلُ [h:6916[ٱ][l[ل]صَّو[n[َٲ]عِقَ فَيُصِيبُ بِهَا م[a:476[َن ي]َش[o[َا]ٓءُ وَهُمْ يُجَ[n[ـٰ]دِلُونَ فِى [h:714[ٱ]للَّهِ وَهُوَ شَدِيدُ [h:6917[ٱ]لْمِح[p[َا]لِ","Ва момақалдироқ Унинг ҳамди ила тасбиҳ айтадир ва фаришталар ҳам ундан қўрққанларидан. У чақмоқларни юборадир ва улар ила хоҳлаган одамларини, улар Аллоҳ ҳақида талашиб турганларида, урадир. У қаттиқ ушлайдиган зотдир.",250,13],["لَهُ[n[ۥ] دَعْوَةُ [h:6918[ٱ]لْحَقِّ‌ۖ وَ[h:37[ٱ]لَّذِينَ يَ[q:1240[دْ]عُونَ مِ[f:3136[ن د]ُونِه[n[ِۦ] لَا يَسْتَجِيبُونَ لَه[c:6919[ُم ب]ِشَىْءٍ إِلَّا كَبَ[n[ـٰ]سِطِ كَفَّيْهِ إِلَى [h:6920[ٱ]لْم[o[َا]ٓءِ لِيَ[q:6921[بْ]لُغَ فَاهُ وَمَا هُوَ بِبَ[n[ـٰ]لِغِه[n[ِۦ]‌ۚ وَمَا دُع[o[َا]ٓءُ [h:6922[ٱ]لْكَ[n[ـٰ]فِرِينَ إِلَّا فِى ضَلَ[p[ـٰ]لٍ","Ҳақ даъвати Уникидир. Ундан ўзгага дуо қилаётганларга эса, ҳеч бир нарсада ижобат этмаслар. Магар, икки кафтини сувга узатиб, сув оғзига етишини кутган одамга ўхшарлар. Ҳолбуки, унга етмас. Кофирларнинг дуоси залолатдан ўзга ҳеч нарса эмасдир.",251,13],["وَلِلَّهِ يَسْجُدُ مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ طَوْ[a:2075[عًا و]َكَرْ[a:6923[هًا و]َظِلَ[n[ـٰ]لُه[c:6924[ُم ب]ِ[h:5225[ٱ]لْغُدُوِّ وَ[h:5226[ٱ]لْأَصَ[p[ا]لِ ۩","Аллоҳга осмонлару ерлардаги кимсалар ва уларнинг соялари хоҳ истасинлар, хоҳ истамасинлар, эртаю кеч сажда қилурлар.",251,13],["قُلْ م[u:6925[َن ر]َّبُّ [h:6926[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ قُلِ [h:3166[ٱ]للَّهُ‌ۚ قُلْ أَفَ[h:6927[ٱ]تَّخَذْت[w:6928[ُم م]ِّ[f:3136[ن د]ُونِه[o[ِۦٓ] أَوْلِي[o[َا]ٓءَ لَا يَمْلِكُونَ لِأَ[f:6929[نف]ُسِهِمْ نَفْ[a:5175[عًا و]َلَا ضَر[f:6930[ًّا‌ۚ ق]ُلْ هَلْ يَسْتَوِى [h:4068[ٱ]لْأَعْمَىٰ وَ[h:4069[ٱ]لْبَصِيرُ أَمْ هَلْ تَسْتَوِى [h:6931[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تُ وَ[h:6932[ٱ][l[ل][g[نّ]ُورُ‌ۗ أَمْ جَعَلُو[s[اْ] لِلَّهِ شُرَك[o[َا]ٓءَ خَلَقُو[s[اْ] كَخَلْقِه[n[ِۦ] فَتَشَ[n[ـٰ]بَهَ [h:6933[ٱ]لْخَلْقُ عَلَيْهِمْ‌ۚ قُلِ [h:3166[ٱ]للَّهُ خَ[n[ـٰ]لِقُ كُلِّ ش[a:4300[َىْءٍ و]َهُوَ [h:6934[ٱ]لْو[n[َٲ]حِدُ [h:6662[ٱ]لْقَهَّ[p[ـٰ]رُ","Сен: «Осмонлару ернинг Робби ким?» деб айт. «Аллоҳ», дегин. «Ўзингизга Ундан ўзга, ўзларига фойда ёки зарарга эга бўлмаган валийларни тутдингизми?» дегин. «Кўзи кўр билан кўрувчи баробар бўлурми ёки зулматлар билан нур баробар бўлурми?» дегин. Ёки улар Аллоҳга У яратган махлуқотларга ўхшаш махуқотларни яратганларни шерик қилиб олдилару уларга яратилган махлуқотларга ўхшаш кўринмоқдами? «Барча нарсанинг яратувчиси Аллоҳдир. Ва У бирдир, Қаҳҳордир», дегин.",251,13],["أَ[f:471[نز]َلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:6935[ءً ف]َسَالَتْ أَوْدِيَ[i:6936[ةُۢ ب]ِقَدَرِهَا فَ[h:6937[ٱ]حْتَمَلَ [h:6938[ٱ][l[ل]سَّيْلُ زَبَ[u:6939[دًا ر]َّابِ[a:6940[يًا‌ۚ و]َمِ[g[مّ]َا يُوقِدُونَ عَلَيْهِ فِى [h:4674[ٱ][l[ل][g[نّ]َارِ [h:6941[ٱ][q:1130[بْ]تِغ[o[َا]ٓءَ حِلْيَةٍ أَوْ مَتَ[n[ـٰ][f:6942[عٍ ز]َبَ[a:6943[دٌ م]ِّثْلُهُ[n[ۥ]‌ۚ كَذ[n[َٲ]لِكَ يَضْرِبُ [h:6944[ٱ]للَّهُ [h:6156[ٱ]لْحَقَّ وَ[h:6945[ٱ]لْبَ[n[ـٰ]طِلَ‌ۚ فَأَ[g[مّ]َا [h:6946[ٱ][l[ل]زَّبَدُ فَيَذْهَبُ جُف[o[َا]ٓ[a:6947[ءً‌ۖ و]َأَ[g[مّ]َا مَا يَ[f:838[نف]َعُ [h:839[ٱ][l[ل][g[نّ]َاسَ فَيَمْكُثُ فِى [h:44[ٱ]لْأَرْضِ‌ۚ كَذ[n[َٲ]لِكَ يَضْرِبُ [h:6944[ٱ]للَّهُ [h:6948[ٱ]لْأَمْث[p[َا]لَ","У зот осмондан сув туширди. Сўнгра водийларда ўз миқдорича сел оқди. Бас, сел ўз устига чиққан кўпикни кўтариб келди. Ва зеб-зийнат, асбоб-ускуна ясаш мақсадида ўтда тобланадиган нарсаларда ҳам шунга ўхшаш кўпик бўладир. Аллоҳ ҳақ ва ботилга мана шундай зарбулмасал келтирур. Аммо кўпик ўз-ўзидан йўқ бўлиб кетди. Одамларга манфаат берадиган нарса эса, ер юзида қолди. Аллоҳ мисолларни ана шундай келтирадир.",251,13],["لِلَّذِينَ [h:6949[ٱ]سْتَجَابُو[s[اْ] لِرَبِّهِمُ [h:6950[ٱ]لْحُسْنَىٰ‌ۚ وَ[h:37[ٱ]لَّذِينَ لَمْ يَسْتَجِيبُو[s[اْ] لَهُ[n[ۥ] لَوْ أَ[g[نّ]َ لَه[w:3531[ُم م]َّا فِى [h:44[ٱ]لْأَرْضِ جَمِي[a:3532[عًا و]َمِثْلَهُ[n[ۥ] مَعَهُ[n[ۥ] لَ[h:6951[ٱ]فْتَدَوْ[s[اْ] بِه[o[ِۦٓ‌ۚ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ س[o[ُو]ٓءُ [h:6952[ٱ]لْحِسَابِ وَمَأْوَ[n[ٮٰ]هُمْ جَهَ[g[نّ]َمُ‌ۖ وَبِئْسَ [h:1757[ٱ]لْمِه[p[َا][q[د]ُ","Роббиларига ижобат этганларга гўзаллик бордир. Унга ижобат этмаганларга эса, агар ер юзидаги ҳамма нарсалар ва яна шунчасига эга бўлсалару уни фидо қилсалар ҳам, ана ўшаларга ёмон ҳисоб бўлур ва жойлари жаҳаннамдадир. У қандай ҳам ёмон жойдир.",251,13],["۞ أَفَم[a:6953[َن ي]َعْلَمُ أَ[g[نّ]َم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْكَ م[u:770[ِن ر]َّبِّكَ [h:6861[ٱ]لْحَقُّ كَمَنْ هُوَ أَعْمَ[o[ىٰٓ‌ۚ] إِ[g[نّ]َمَا يَتَذَكَّرُ أُ[s[وْ]لُو[s[اْ] [h:1595[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","Сенга Роббингдан нозил қилинган нарса, албатта, ҳақ эканини биладиган кимса кўр одамга ўхшармиди? Буни, албатта, ақл эгаларигина эслайдилар.",252,13],["ٱلَّذِينَ يُوفُونَ بِعَهْدِ [h:2038[ٱ]للَّهِ وَلَا يَ[f:144[نق]ُضُونَ [h:6954[ٱ]لْمِيثَ[p[ـٰ][q[ق]َ","Улар Аллоҳнинг аҳдига вафо қиладиган ва мийсоқни бузмайдиганлардир.",252,13],["وَ[h:9999[ٱ]لَّذِينَ يَصِلُونَ م[o[َآ] أَمَرَ [h:148[ٱ]للَّهُ بِه[o[ِۦٓ] أ[a:149[َن ي]ُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ س[o[ُو]ٓءَ [h:6955[ٱ]لْحِس[p[َا][q[ب]ِ","Улар Аллоҳ боғланишига амр этган нарсани боғларлар, Роббиларидан чўчирлар ва ёмон ҳисобдан қўрқарлар.",252,13],["وَ[h:9999[ٱ]لَّذِينَ صَبَرُو[s[اْ] [h:6956[ٱ][q:1130[بْ]تِغ[o[َا]ٓءَ وَ[q:1611[جْ]هِ رَبِّهِمْ وَأَقَامُو[s[اْ] [h:1641[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَأَ[f:2789[نف]َقُو[s[اْ] مِ[g[مّ]َا رَزَ[q:15[قْ]نَ[n[ـٰ]هُمْ سِر[a:1623[ًّا و]َعَلَانِيَ[a:6957[ةً و]َيَ[q:6958[دْ]رَءُونَ بِ[h:4561[ٱ]لْحَسَنَةِ [h:6959[ٱ][l[ل]سَّيِّئَةَ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ عُ[q:6960[قْ]بَى [h:6961[ٱ][l[ل]دّ[p[َا]رِ","Улар Роббилари юзини кўзлаб, сабр қиларлар. Намозни тўкис адо этарлар, Биз уларга ризқ қилиб берган нарсадан махфий ва ошкора инфоқ қиларлар ва ёмонликни яхшилик ила қайтарарлар. Ана ўшаларга оқибат диёри бордир.",252,13],["جَ[g[نّ]َ[n[ـٰ]تُ عَ[q:5720[دْ][a:6962[نٍ ي]َ[q:6963[دْ]خُلُونَهَا وَمَ[f:6964[ن ص]َلَحَ مِنْ ءَاب[o[َا]ٓئِهِمْ وَأَزْو[n[َٲ]جِهِمْ وَذُرِّيَّ[n[ـٰ]تِهِمْ‌ۖ وَ[h:1146[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ يَ[q:3156[دْ]خُلُونَ عَلَيْه[w:4082[ِم م]ِّ[f:843[ن ك]ُلِّ ب[p[َا][q[ب]ٍ","Адн жаннатларидир. Унга улар ва уларнинг оталари, жуфти ҳалоллари ва зурриётларидан солиҳ бўлганлари кирарлар. Сўнгра уларнинг ҳузурларига ҳар эшикдан фаришталар кириб:",252,13],["سَلَ[n[ـٰ]مٌ عَلَيْك[c:6965[ُم ب]ِمَا صَبَرْتُمْ‌ۚ فَنِعْمَ عُ[q:6960[قْ]بَى [h:6961[ٱ][l[ل]دّ[p[َا]رِ","«Сабр қилганингиз учун сизларга Салом бўлсин! Бу оқибат диёри қандай ҳам яхши!!!».",252,13],["وَ[h:9999[ٱ]لَّذِينَ يَ[f:144[نق]ُضُونَ عَهْدَ [h:145[ٱ]للَّهِ م[i:146[ِنۢ ب]َعْدِ مِيثَ[n[ـٰ]قِه[n[ِۦ] وَيَ[q:147[قْ]طَعُونَ م[o[َآ] أَمَرَ [h:148[ٱ]للَّهُ بِه[o[ِۦٓ] أ[a:149[َن ي]ُوصَلَ وَيُفْسِدُونَ فِى [h:44[ٱ]لْأَرْضِ‌ۙ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمُ [h:6966[ٱ][l[ل]لَّعْنَةُ وَلَهُمْ س[o[ُو]ٓءُ [h:6967[ٱ][l[ل]دّ[p[َا]رِ","Аллоҳнинг аҳдини мийсоқдан кейин бузадиганлар, Аллоҳ боғланишига амр этган нарсаларни узадиганлар ва ер юзида бузғунчилик қиладиганларга, ана ўшаларга лаънат ва уларга ёмон диёр бор.",252,13],["ٱللَّهُ يَ[q:6968[بْ]سُطُ [h:6969[ٱ][l[ل]رِّزْقَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيَ[q:6970[قْ]دِرُ‌ۚ وَفَرِحُو[s[اْ] بِ[h:5581[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:5582[ٱ][l[ل]دُّنْيَا وَمَا [h:2482[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَا فِى [h:536[ٱ]لْأَخِرَةِ إِلَّا مَتَ[p[ـٰ]عٌ","Аллоҳ хоҳлаган кишисининг ризқини кенг қилур ва тор қилур. Улар бу дунё ҳаёти ила шод бўлдилар. Ҳолбуки, бу дунё ҳаёти охират олдида арзимас матоҳ, холос.",252,13],["وَيَقُولُ [h:3629[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَوْل[o[َآ] أُ[f:17[نز]ِلَ عَلَيْهِ ءَايَ[a:4024[ةٌ م]ّ[u:192[ِن ر]َّبِّه[n[ِۦ]‌ۗ قُلْ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُضِلُّ م[a:476[َن ي]َش[o[َا]ٓءُ وَيَهْد[o[ِىٓ] إِلَيْهِ مَنْ أَن[p[َا][q[ب]َ","Ва куфр келтирганлар: «Унга Роббидан бир оят-мўъжиза тушса эди», дерлар. Сен: «Албатта, Аллоҳ кимни хоҳласа, залолатга кетказадир ва Ўзига йўналганларини ҳидоят қиладир», деб айт.",252,13],["ٱلَّذِينَ ءَامَنُو[s[اْ] وَتَ[q:6971[طْ]مَئِ[g[نّ]ُ قُلُوبُه[c:6972[ُم ب]ِذِكْرِ [h:6973[ٱ]للَّهِ‌ۗ أَلَا بِذِكْرِ [h:6973[ٱ]للَّهِ تَ[q:6974[طْ]مَئِ[g[نّ]ُ [h:6975[ٱ]لْقُل[p[ُو][q[ب]ُ","Иймон келтирганлар ва Аллоҳнинг зикри ила қалблари ором топганлар. Аё, Аллоҳнинг зикри ила қалблар ором топмасми?",252,13],["ٱلَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ طُوبَىٰ لَهُمْ وَحُسْنُ مَــٔ[p[َا][q[ب]ٍ","Иймон келтирганлар ва яхши амалларни қилганларга хушнудлик ва гўзал маскан бор.",253,13],["كَذ[n[َٲ]لِكَ أَرْسَلْنَ[n[ـٰ]كَ ف[o[ِىٓ] أُ[g[مّ]َ[f:6976[ةٍ ق]َ[q:298[دْ] خَلَتْ مِ[f:6977[ن ق]َ[q:6978[بْ]لِه[o[َآ] أُمَ[u:6979[مٌ ل]ِّتَتْلُوَ[s[اْ] عَلَيْهِمُ [h:6980[ٱ]لَّذ[o[ِىٓ] أَوْحَيْن[o[َآ] إِلَيْكَ وَهُمْ يَكْفُرُونَ بِ[h:6981[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ‌ۚ قُلْ هُوَ رَبِّى ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَت[p[َا][q[ب]ِ","Шундай қилиб, сени ўзларидан олдин ҳам умматлар ўтган бир умматга уларга ўзингга ваҳий қилган нарсамизни тиловат қилиб беришинг учун юбордик. Ҳолбуки, улар Роҳманга куфр келтирурлар. Сен: «У менинг Роббимдир, Ундан ўзга ибодатга сазовор зот йўқ. Унинг Ўзигагина таваккал қилдим. Тавбам ҳам Унинг Ўзигадир», деб айт.",253,13],["وَلَوْ أَ[g[نّ]َ قُرْءَا[f:6982[نًا س]ُيِّرَتْ بِهِ [h:6983[ٱ]لْجِبَالُ أَوْ قُطِّعَتْ بِهِ [h:6984[ٱ]لْأَرْضُ أَوْ كُلِّمَ بِهِ [h:6985[ٱ]لْمَوْتَىٰ‌ۗ بَل لِّلَّهِ [h:6986[ٱ]لْأَمْرُ جَمِيعًا‌ۗ أَفَلَمْ يَ[s[اْ]يْــَٔسِ [h:6987[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أ[u:4894[َن ل]َّوْ يَش[o[َا]ٓءُ [h:6988[ٱ]للَّهُ لَهَدَى [h:6989[ٱ][l[ل][g[نّ]َاسَ جَمِي[a:2134[عًا‌ۗ و]َلَا يَزَالُ [h:6990[ٱ]لَّذِينَ كَفَرُو[s[اْ] تُصِيبُه[c:6991[ُم ب]ِمَا صَنَعُو[s[اْ] قَارِعَةٌ أَوْ تَحُلُّ قَرِي[a:6992[بًا م]ِّ[f:6993[ن د]َارِهِمْ حَتَّىٰ يَأْتِىَ وَعْدُ [h:6994[ٱ]للَّهِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُخْلِفُ [h:1751[ٱ]لْمِيع[p[َا][q[د]َ","Агар Қуръон ила тоғлар жилдириладиган, ер парчаланадиган ёки ўликлар тилга киритиладиган бўлганида. Аммо ишнинг барчаси Аллоҳга хосдир. Иймон келтирганлар, агар Аллоҳ хоҳласа, одамларнинг ҳаммасини ҳидоят қила олишини билмадиларми? Куфр келтирганларга то Аллоҳнинг ваъдаси келгунча ўз ишлари сабабли мудом ларзага солувчи мусибатлар етар ёки уларнинг диёрлари яқинига тушиб турар. Албатта, Аллоҳ ваъдага хилоф қилмас.",253,13],["وَلَقَدِ [h:3947[ٱ]سْتُهْزِئَ بِرُسُ[a:3948[لٍ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُو[s[اْ] ثُ[g[مّ]َ أَخَذْتُهُمْ‌ۖ فَكَيْفَ كَانَ عِق[p[َا][q[ب]ِ","Батаҳқиқ, сендан олдин ҳам Пайғамбарлар масхара қилинганлар. Бас, куфр келтирганларга муҳлат бердим. Сўнгра, уларни ушладим. Бас, иқобим қандоқ бўлган эди?!",253,13],["أَفَمَنْ هُوَ ق[o[َا]ٓئِمٌ عَلَىٰ كُلِّ نَفْ[i:6995[سِۭ ب]ِمَا كَسَبَتْ‌ۗ وَجَعَلُو[s[اْ] لِلَّهِ شُرَك[o[َا]ٓءَ قُلْ سَ[g[مّ]ُوهُمْ‌ۚ أَمْ تُنَبِّــُٔونَهُ[n[ۥ] بِمَا لَا يَعْلَمُ فِى [h:44[ٱ]لْأَرْضِ أ[c:6996[َم ب]ِظَ[n[ـٰ]هِ[a:6997[رٍ م]ِّنَ [h:3107[ٱ]لْقَوْلِ‌ۗ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُو[s[اْ] مَكْرُهُمْ وَصُدُّو[s[اْ] عَنِ [h:6998[ٱ][l[ل]سَّبِيلِ‌ۗ وَم[a:3002[َن ي]ُضْلِلِ [h:3003[ٱ]للَّهُ فَمَا لَهُ[n[ۥ] مِنْ ه[p[َا][q[د]ٍ","Ҳар бир жоннинг қилган касби устидан турувчи зот ким? Аллоҳга ширк келтирдилар. Сен: «Уларнинг номларини айтинг. Ёки Унга ер юзида У билмайдиган нарсанинг хабарини берасизларми? Балки, юзаки гапдир», дегин. Йўқ, куфр келтирганларга макрлари зийнатлаб кўрсатилди ва улар йўлдан тўсилдилар. Аллоҳ кимни залолатга кетказса, унга ҳеч бир ҳидоятчи бўлмас.",253,13],["لَّهُمْ عَذَا[f:6999[بٌ ف]ِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۖ وَلَعَذَابُ [h:7000[ٱ]لْأَخِرَةِ أَشَقُّ‌ۖ وَمَا لَه[w:6026[ُم م]ِّنَ [h:321[ٱ]للَّهِ م[a:7001[ِن و][p[َا][q[ق]ٍ","Уларга бу дунё ҳаётида азоб бор. Албатта, охират азоби машаққатлироқ. Улар учун Аллоҳдан сақловчи бўлмас.",253,13],["۞ مَّثَلُ [h:7002[ٱ]لْجَ[g[نّ]َةِ [h:7003[ٱ]لَّتِى وُعِدَ [h:7004[ٱ]لْمُتَّقُونَ‌ۖ تَ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۖ أُكُلُهَا د[o[َا]ٓئِ[a:7005[مٌ و]َظِلُّهَا‌ۚ تِلْكَ عُ[q:6960[قْ]بَى [h:7006[ٱ]لَّذِينَ [h:7007[ٱ]تَّقَو[s[اْ‌ۖ] وَّعُ[q:7008[قْ]بَى [h:7009[ٱ]لْكَ[n[ـٰ]فِرِينَ [h:7010[ٱ][l[ل][g[نّ][p[َا]رُ","Тақводорларга ваъда қилинган жаннатнинг мисоли: остидан анҳорлар оқади, мевалари ва соялари доимийдир. Бу тақво қилганларнинг оқибатидир. Кофирларнинг оқибати эса, дўзахдир.",254,13],["وَ[h:9999[ٱ]لَّذِينَ ءَاتَيْنَ[n[ـٰ]هُمُ [h:635[ٱ]لْكِتَ[n[ـٰ]بَ يَفْرَحُونَ بِم[o[َآ] أُ[f:17[نز]ِلَ إِلَيْكَ‌ۖ وَمِنَ [h:7011[ٱ]لْأَحْزَابِ م[a:7012[َن ي]ُ[f:7013[نك]ِرُ بَعْضَهُ[n[ۥ]‌ۚ قُلْ إِ[g[نّ]َم[o[َآ] أُمِرْتُ أَنْ أَعْبُدَ [h:7014[ٱ]للَّهَ وَل[o[َآ] أُشْرِكَ بِه[o[ِۦٓ‌ۚ] إِلَيْهِ أَ[q:6847[دْ]عُو[s[اْ] وَإِلَيْهِ مَـَٔـ[p[ا][q[ب]ِ","Биз китоб берганлар, сенга нозил қилинган нарсадан хурсанд бўлурлар. Гуруҳлар ичида унинг баъзисини инкор қиладиган кимсалар ҳам бор. Сен: «Албатта, мен Аллоҳга ибодат қилишга, Унга ширк келтирмасликка амр қилиндим. Унгагина даъват қиламан ҳамда қайтишим ҳам Унгадир«, деб айт.",254,13],["وَكَذ[n[َٲ]لِكَ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ حُكْمًا عَرَبِي[a:7015[ًّا‌ۚ و]َلَئِنِ [h:631[ٱ]تَّبَعْتَ أَهْو[o[َا]ٓءَه[c:7016[ُم ب]َعْدَمَا ج[o[َا]ٓءَكَ مِنَ [h:634[ٱ]لْعِلْمِ مَا لَكَ مِنَ [h:321[ٱ]للَّهِ م[a:557[ِن و]َلِ[a:558[ىٍّ و]َلَا و[p[َا][q[ق]ٍ","Шунингдек, Биз уни арабий ҳукм этиб нозил қилдик. Агар сен ўзингга келган илмдан сўнг уларнинг ҳавойи нафсларига эргашсанг, сен учун Аллоҳдан на бир дўст ва на бир сақловчи бўлмас.",254,13],["وَلَقَ[q:341[دْ] أَرْسَلْنَا رُسُل[a:7017[اً م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ وَجَعَلْنَا لَهُمْ أَزْو[n[َٲ][a:7018[جًا و]َذُرِّيَّ[a:7019[ةً‌ۚ و]َمَا كَانَ لِرَسُولٍ أ[a:1462[َن ي]َأْتِىَ بِـَٔـايَةٍ إِلَّا بِإِذْنِ [h:509[ٱ]للَّهِ‌ۗ لِكُلِّ أَجَ[f:7020[لٍ ك]ِت[p[َا][q[ب]ٌ","Батаҳқиқ, Биз сендан олдин ҳам Пайғамбарлар юбордик ва уларга хотинлар ва зурриётлар ато қилганмиз. Ҳеч бир Пайғамбар Аллоҳнинг изнисиз оят-мўъжиза келтирган эмас. Ҳар бир ажалнинг ўз китоби бордир.",254,13],["يَمْحُو[s[اْ] [h:7021[ٱ]للَّهُ مَا يَش[o[َا]ٓءُ وَيُثْبِتُ‌ۖ وَعِ[f:4104[ند]َهُ[o[ۥٓ] أُ[g[مّ]ُ [h:1736[ٱ]لْكِتَ[p[ـٰ][q[ب]ِ","Аллоҳ нимани хоҳласа, маҳв қилур, нимани хоҳласа, собит қилур. Она китоб Унинг даргоҳидадир.",254,13],["وَإ[a:7022[ِن م]َّا نُرِيَ[g[نّ]َكَ بَعْضَ [h:1943[ٱ]لَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَ[g[نّ]َكَ فَإِ[g[نّ]َمَا عَلَيْكَ [h:1808[ٱ]لْبَلَ[n[ـٰ]غُ وَعَلَيْنَا [h:7023[ٱ]لْحِس[p[َا][q[ب]ُ","Уларга ваъда қилганимизнинг баъзисини сенга кўрсатармиз ёки сени вафот этдираримз. Албатта, етказиш сенинг зиммангда, ҳисоб қилиш Бизнинг зиммамиздадир.",254,13],["أَوَلَمْ يَرَوْ[s[اْ] أَ[g[نّ]َا نَأْتِى [h:7024[ٱ]لْأَرْضَ نَ[f:7025[نق]ُصُهَا مِنْ أَ[q:7026[طْ]رَافِهَا‌ۚ وَ[h:72[ٱ]للَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِه[n[ِۦ]‌ۚ وَهُوَ سَرِيعُ [h:1112[ٱ]لْحِس[p[َا][q[ب]ِ","Биз ерга келиб, унинг атрофидан қисқартириб бораётганимизни кўрмайдиларми?! Ҳукмни Аллоҳ қиладир. Унинг ҳукмини таъқиб қилгувчи йўқ. У ҳисоби тез зотдир.",254,13],["وَقَ[q:387[دْ] مَكَرَ [h:7027[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ فَلِلَّهِ [h:7028[ٱ]لْمَكْرُ جَمِي[a:7029[عًا‌ۖ ي]َعْلَمُ مَا تَكْسِبُ كُلُّ نَفْ[a:7030[سٍ‌ۗ و]َسَيَعْلَمُ [h:7031[ٱ]لْكُفَّ[n[ـٰ]رُ لِمَنْ عُ[q:6960[قْ]بَى [h:6961[ٱ][l[ل]دّ[p[َا]رِ","Батаҳқиқ, улардан олдингилар ҳам макр қилдилар. Аммо барча макрлар Аллоҳнинг. У ҳар бир жон нима қилишини биладир. Яқинда кофирлар оқибат диёри кимга бўлишини билажаклар.",254,13],["وَيَقُولُ [h:3629[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَسْتَ مُرْسَل[f:7032[اً‌ۚ ق]ُلْ كَفَىٰ بِ[h:32[ٱ]للَّهِ شَهِيد[i:7033[َۢا ب]َيْنِى وَبَيْنَكُمْ وَمَنْ عِ[f:719[ند]َهُ[n[ۥ] عِلْمُ [h:7034[ٱ]لْكِتَ[p[ـٰ][q[ب]ِ","Куфр келтирганлар: «Пайғамбар эмассан», дерлар. Сен: «Мен билан сизнинг орангизда Аллоҳ ва Китоб илми бор кимсалар етарли гувоҳдир», деб айт.",255,13]]},{"n":14,"ar":"إِبۡرَاهِيمَ","en":"Ibrahim","uz":"Иброҳим","type":"Макка","ayahs":[["ا[m[لٓ]ر‌ۚ كِتَ[n[ـٰ]بٌ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ إِلَيْكَ لِتُخْرِجَ [h:7035[ٱ][l[ل][g[نّ]َاسَ مِنَ [h:1491[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ إِلَى [h:1492[ٱ][l[ل][g[نّ]ُورِ بِإِذْنِ رَبِّهِمْ إِلَىٰ صِر[n[َٲ]طِ [h:7036[ٱ]لْعَزِيزِ [h:7037[ٱ]لْحَم[p[ِي][q[د]ِ","Алиф. Лом. Ро. Бу китобни сенга одамларни Роббиларининг изни ила зулматлардан нурга, азиз ва мақталган зотнинг йўлига чиқаришинг учун нозил қилдик.",255,13],["ٱللَّهِ [h:7038[ٱ]لَّذِى لَهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۗ وَوَيْ[u:7039[لٌ ل]ِّلْكَ[n[ـٰ]فِرِينَ مِنْ عَذَا[f:7040[بٍ ش]َد[p[ِي][q[د]ٍ","Аллоҳ осмонлару ердаги нарсалар Уники бўлган зотдир. Кофирлар ҳолига шиддатли азобдан вой бўлсин.",255,13],["ٱلَّذِينَ يَسْتَحِبُّونَ [h:7041[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَا عَلَى [h:7042[ٱ]لْأَخِرَةِ وَيَصُدُّونَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ وَيَ[q:4708[بْ]غُونَهَا عِوَجًا‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ فِى ضَلَ[n[ـٰ][i:7043[لِۭ ب]َع[p[ِي][q[د]ٍ","Улар бу дунё ҳаётини охиратдан афзал кўрадиганлар, Аллоҳнинг йўлидан тўсадиганлар ва унинг эгри бўлишини хоҳлайдиганлардир. Ана ўшалар йироқ адашувдадирлар.",255,13],["وَم[o[َآ] أَرْسَلْنَا م[u:2882[ِن ر]َّسُولٍ إِلَّا بِلِسَانِ قَوْمِه[n[ِۦ] لِيُبَيِّنَ لَهُمْ‌ۖ فَيُضِلُّ [h:7044[ٱ]للَّهُ م[a:476[َن ي]َش[o[َا]ٓءُ وَيَهْدِى م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Қайсики Пайғамбарни юборган бўлсак, баён қилиб бериши учун ўз қавми тили ила юборганмиз. Бас, Аллоҳ кимни хоҳласа, залолатга кетказадир, кимни хоҳласа, ҳидоятга соладир. У азиз ва ҳикматли зотдир.",255,13],["وَلَقَ[q:341[دْ] أَرْسَلْنَا مُوسَىٰ بِـَٔـايَ[n[ـٰ]تِن[o[َآ] أَنْ أَخْرِ[q:7046[جْ] قَوْمَكَ مِنَ [h:1491[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ إِلَى [h:1492[ٱ][l[ل][g[نّ]ُورِ وَذَكِّرْه[c:7047[ُم ب]ِأَيَّ[n[ـٰ]مِ [h:7048[ٱ]للَّهِ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:7049[تٍ ل]ِّكُلِّ صَبَّا[f:7050[رٍ ش]َك[p[ُو]رٍ","Батаҳқиқ, Биз Мусони оятларимиз ила: «Қавмингни зулматлардан нурга чиқар ва уларга Аллоҳнинг кунларини эслат! Албатта, бунда ҳар бир сабрли ва шукрли учун ибратлар бордир», деб юбордик.",255,13],["وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ [h:7051[ٱ]ذْكُرُو[s[اْ] نِعْمَةَ [h:1154[ٱ]للَّهِ عَلَيْكُمْ إِذْ أَ[f:7052[نج]َ[n[ـٰ]ك[w:7053[ُم م]ِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ س[o[ُو]ٓءَ [h:239[ٱ]لْعَذَابِ وَيُذَبِّحُونَ أَ[q:240[بْ]ن[o[َا]ٓءَكُمْ وَيَسْتَحْيُونَ نِس[o[َا]ٓءَكُمْ‌ۚ وَفِى ذ[n[َٲ]لِك[c:241[ُم ب]َل[o[َا]ٓ[a:242[ءٌ م]ّ[u:243[ِن ر]َّبِّكُمْ عَظ[p[ِي]مٌ","Ўшанда Мусо қавмига: «Аллоҳнинг сизга берган неъматларини эсланг; вақтики, у сизни Оли Фиръавндан қутқарди. Улар сизга бардавом ёмон азоб берардилар. Ўғилларингизни сўйиб, қизларингизни тирик қолдирардилар. Ана ўшанда Роббингиздан буюк синов бордир», деган эди.",256,13],["وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِ[f:7054[ن ش]َكَرْتُمْ لَأَزِيدَ[g[نّ]َكُمْ‌ۖ وَلَئِ[f:7055[ن ك]َفَرْتُمْ إِ[g[نّ]َ عَذَابِى لَشَد[p[ِي][q[د]ٌ","Ва Роббингиз сизга: «Қасамки, агар шукр қилсангиз, албатта, сизга зиёда қилурман. Агар куфр келтирсангиз, албатта, азобим шиддатлидир», деб билдирганини эсланг.",256,13],["وَقَالَ مُوسَ[o[ىٰٓ] إِ[f:7056[ن ت]َكْفُر[o[ُوٓ][s[اْ] أَ[f:428[نت]ُمْ وَمَ[f:3453[ن ف]ِى [h:44[ٱ]لْأَرْضِ جَمِي[f:7057[عًا ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ لَغَنِىٌّ حَم[p[ِي][q[د]ٌ","Мусо: «Агар сиз ва ер юзидаги кимсалар ҳаммангиз куфр келтирсангизлар ҳам, албатта, Аллоҳ беҳожат ва мақталган зотдир», деди. Эй Муҳаммад уммати!",256,13],["أَلَمْ يَأْتِكُمْ نَبَؤُ[s[اْ] [h:7058[ٱ]لَّذِينَ مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ قَوْمِ نُو[a:5711[حٍ و]َعَا[a:5712[دٍ و]َثَمُودَ‌ۛ وَ[h:37[ٱ]لَّذِينَ م[i:1453[ِنۢ ب]َعْدِهِمْ‌ۛ لَا يَعْلَمُهُمْ إِلَّا [h:1742[ٱ]للَّهُ‌ۚ ج[o[َا]ٓءَتْهُمْ رُسُلُه[c:4900[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ فَرَدّ[o[ُوٓ][s[اْ] أَيْدِيَهُمْ ف[o[ِىٓ] أَفْو[n[َٲ]هِهِمْ وَقَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا كَفَرْنَا بِم[o[َآ] أُرْسِلْت[c:7059[ُم ب]ِه[n[ِۦ] وَإِ[g[نّ]َا لَفِى شَ[a:6196[كٍّ م]ِّ[g[مّ]َا تَ[q:7060[دْ]عُونَن[o[َآ] إِلَيْهِ مُر[p[ِي][q[ب]ٍ","Сизга ўзингиздан олдин ўтган Нуҳ, Од, Самуд қавмларининг ва улардан кейингиларнинг, Аллоҳдан ўзга ҳеч ким билмайдиганларнинг, хабари келмадими? Уларга Пайғамбарлари очиқ-ойдин ҳужжатлар билан келдилар. Улар эса, қўлларини оғизларига қўйиб: «Биз сиз бизни чақираётган нарсада шубҳалантирувчи шакдадирмиз!» дедилар.",256,13],["۞ قَالَتْ رُسُلُهُمْ أَفِى [h:7061[ٱ]للَّهِ شَ[f:7062[كٌّ ف]َاطِرِ [h:3956[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ يَ[q:2332[دْ]عُوكُمْ لِيَغْفِرَ لَك[w:556[ُم م]ِّ[f:7063[ن ذ]ُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَم[f:7064[ًّى‌ۚ ق]َال[o[ُوٓ][s[اْ] إِنْ أَ[f:428[نت]ُمْ إِلَّا بَشَ[a:7065[رٌ م]ِّثْلُنَا تُرِيدُونَ أَ[f:7066[ن ت]َصُدُّونَا عَ[g[مّ]َا كَانَ يَعْبُدُ ءَاب[o[َا]ٓؤُنَا فَأْتُونَا بِسُلْطَ[n[ـٰ][a:7067[نٍ م]ُّب[p[ِي]نٍ","Пайғамбарлари уларга: «Осмонлару ернинг яратгувчиси бўлмиш Аллоҳга шак борми? У сизларни гуноҳларингизни мағфират қилишга ва ўзингизни маълум муддатга қолдиришга чақирмоқда-ку! « дедилар. Улар эса: «Сиз бизга ўхшаш башардан ўзга ҳеч нарса эмассиз. Бизни оталаримиз ибодат қилиб юрган нарсадан тўсмоқчисиз. Бас, бизга очиқ-ойдин ҳужжат келтиринг», дедилар.",256,13],["قَالَتْ لَهُمْ رُسُلُهُمْ إ[a:7068[ِن ن]َّحْنُ إِلَّا بَشَ[a:7069[رٌ م]ِّثْلُكُمْ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ يَمُ[g[نّ]ُ عَلَىٰ م[a:476[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[n[ِۦ]‌ۖ وَمَا كَانَ لَن[o[َآ] أ[a:7070[َن ن]َّأْتِيَك[c:7071[ُم ب]ِسُلْطَ[n[ـٰ]نٍ إِلَّا بِإِذْنِ [h:509[ٱ]للَّهِ‌ۚ وَعَلَى [h:2207[ٱ]للَّهِ فَلْيَتَوَكَّلِ [h:2208[ٱ]لْمُؤْمِن[p[ُو]نَ","Пайғамбарлари уларга: «Биз сизга ўхшаш башардан ўзга ҳеч нарса эмасмиз. Лекин Аллоҳ Ўз бандаларидан кимни хоҳласа, ўшанга инъом қилур. Биз ўзимизча сизга бирор ҳужжат келтира олмаймиз, илло Аллоҳнинг изни ила. Мўминлар фақат Аллоҳгагина таваккал қилсинлар.",257,13],["وَمَا لَن[o[َآ] أَلَّا نَتَوَكَّلَ عَلَى [h:412[ٱ]للَّهِ وَقَ[q:387[دْ] هَدَ[n[ٮٰ]نَا سُبُلَنَا‌ۚ وَلَنَصْبِرَ[g[نّ]َ عَلَىٰ م[o[َآ] ءَاذَيْتُمُونَا‌ۚ وَعَلَى [h:2207[ٱ]للَّهِ فَلْيَتَوَكَّلِ [h:6748[ٱ]لْمُتَوَكِّل[p[ُو]نَ","Нима учун биз Аллоҳга таваккал қилмас эканмиз?! Ҳолбуки, У бизни йўлимизга ҳидоят қилди. Бизга берган озорларингизга, албатта, сабр қиламиз. Таваккал қилувчилар фақат Аллоҳгагина таваккал қилсинлар», дедилар.",257,13],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَرُو[s[اْ] لِرُسُلِهِمْ لَنُخْرِجَ[g[نّ]َك[w:7072[ُم م]ِّنْ أَرْضِن[o[َآ] أَوْ لَتَعُودُ[g[نّ]َ فِى مِلَّتِنَا‌ۖ فَأَوْحَ[o[ىٰٓ] إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَ[g[نّ]َ [h:7073[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Куфр келтирганлар ўз Пайғамбарларига: «Албатта, биз сизларни еримиздан чиқариб юборамиз ёки, албатта, миллатимизга қайтасизлар», дедилар. Бас, Роббилари уларга: «Албатта, Биз золимларни ҳалок қилурмиз.",257,13],["وَلَنُسْكِنَ[g[نّ]َكُمُ [h:7074[ٱ]لْأَرْضَ م[i:1453[ِنۢ ب]َعْدِهِمْ‌ۚ ذ[n[َٲ]لِكَ لِمَنْ خَافَ مَقَامِى وَخَافَ وَع[p[ِي][q[د]ِ","Ва улардан сўнг у ерга сизни жойлаштирурмиз. Бу эса, мақомимдан хавф қилганлар ва таҳдидимдан қўрққанлар учундир», деб ваҳий қилди.",257,13],["وَ[h:9999[ٱ]سْتَفْتَحُو[s[اْ] وَخَابَ كُلُّ جَبَّارٍ عَن[p[ِي][q[د]ٍ","Фатҳу нусрат сўрадилар ва ҳар бир жабрчи, саркаш кимса ноумидликка учради.",257,13],["مّ[a:7075[ِن و]َر[o[َا]ٓئِه[n[ِۦ] جَهَ[g[نّ]َمُ وَيُسْقَىٰ م[a:840[ِن م]ّ[o[َا]ٓ[f:7076[ءٍ ص]َد[p[ِي][q[د]ٍ","Унинг ортида жаҳаннам бордир. Йиринг сув ила суғориладир.",257,13],["يَتَجَرَّعُهُ[n[ۥ] وَلَا يَكَادُ يُسِيغُهُ[n[ۥ] وَيَأْتِيهِ [h:7077[ٱ]لْمَوْتُ مِ[f:843[ن ك]ُلِّ مَكَا[a:7078[نٍ و]َمَا هُوَ بِمَيِّ[a:7079[تٍ‌ۖ و]َم[a:7080[ِن و]َر[o[َا]ٓئِه[n[ِۦ] عَذَابٌ غَل[p[ِي]ظٌ","Уни ютишга уринади-ю, юта олмас. Унга ҳар томондан ўлим келади-ю, ўла олмас. Унинг ортидан эса, қаттиқ азоб бор.",257,13],["مَّثَلُ [h:1179[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِرَبِّهِمْ‌ۖ أَعْمَ[n[ـٰ]لُهُمْ كَرَمَادٍ [h:7081[ٱ]شْتَدَّتْ بِهِ [h:7082[ٱ][l[ل]رِّيحُ فِى يَوْمٍ عَاصِ[u:7083[فٍ‌ۖ ل]َّا يَ[q:1555[قْ]دِرُونَ مِ[g[مّ]َا كَسَبُو[s[اْ] عَلَىٰ ش[f:6654[َىْءٍ‌ۚ ذ][n[َٲ]لِكَ هُوَ [h:7084[ٱ][l[ل]ضَّلَ[n[ـٰ]لُ [h:7085[ٱ]لْبَع[p[ِي][q[د]ُ","Роббиларига куфр келтирганларнинг амалларининг мисоли, худди бўронли кунда шамол учириб кетган кулга ўхшайдир. Улар ўз касбларидан бирор нарсага эга бўлмаслар. Ана ўша узоқ адашувнинг ўзидир.",257,13],["أَلَمْ تَرَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ بِ[h:370[ٱ]لْحَقِّ‌ۚ إ[a:3197[ِن ي]َشَأْ يُذْهِ[q:3198[بْ]كُمْ وَيَأْتِ بِخَلْ[f:7086[قٍ ج]َد[p[ِي][q[د]ٍ","Аллоҳ осмонлару ерни ҳақ ила яратиб қўйганини кўрмадингми? Агар истаса, сизларни кетказиб, янги халқ келтиради.",258,13],["وَمَا ذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ بِعَز[p[ِي]زٍ","Бу эса, Аллоҳ учун қийин эмас.",258,13],["وَبَرَزُو[s[اْ] لِلَّهِ جَمِي[f:7087[عًا ف]َقَالَ [h:7088[ٱ][l[ل]ضُّعَفَ[o[ـٰٓ]ؤُ[s[اْ] لِلَّذِينَ [h:7089[ٱ]سْتَكْبَر[o[ُوٓ][s[اْ] إِ[g[نّ]َا كُ[g[نّ]َا لَكُمْ تَبَ[f:7090[عًا ف]َهَلْ أَ[f:428[نت][w:7091[ُم م]ُّغْنُونَ عَ[g[نّ]َا مِنْ عَذَابِ [h:6845[ٱ]للَّهِ مِ[f:2103[ن ش][f:7092[َىْءٍ‌ۚ ق]َالُو[s[اْ] لَوْ هَدَ[n[ٮٰ]نَا [h:4173[ٱ]للَّهُ لَهَدَيْنَ[n[ـٰ]كُمْ‌ۖ سَو[o[َا]ٓءٌ عَلَيْن[o[َآ] أَجَزِعْن[o[َآ] أَمْ صَبَرْنَا مَا لَنَا م[a:7093[ِن م]َّح[p[ِي]صٍ","Уларнинг ҳаммалари Аллоҳ ҳузурида пайдо бўлдилар. Бас, заифлар мутакаббирларга: «Албатта, биз сизларга тобе бўлган эдик. Энди, сизлар устимиздаги Аллоҳнинг азобидан бирор нарсани енгиллата оласизларми?» дедилар. Улар: «Агар Аллоҳ бизни ҳидоят қилганида, биз ҳам сизларни, албатта, ҳидоят қилар эдик. Биз учун энди, дод-вой қиламизми ёки сабр қиламизми, бари бир. Биз учун қочар жой йўқ», дедилар.",258,13],["وَقَالَ [h:7094[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ لَ[g[مّ]َا قُضِىَ [h:6667[ٱ]لْأَمْرُ إِ[g[نّ]َ [h:80[ٱ]للَّهَ وَعَدَكُمْ وَعْدَ [h:7095[ٱ]لْحَقِّ وَوَعَ[d:7096[د]تُّكُمْ فَأَخْلَفْتُكُمْ‌ۖ وَمَا كَانَ لِىَ عَلَيْك[w:548[ُم م]ِّ[f:4798[ن س]ُلْطَ[n[ـٰ]نٍ إِلّ[o[َآ] أَ[f:7097[ن د]َعَوْتُكُمْ فَ[h:7098[ٱ]سْتَجَ[q:7098[بْ]تُمْ لِى‌ۖ فَلَا تَلُومُونِى وَلُوم[o[ُوٓ][s[اْ] أَ[f:221[نف]ُسَك[w:7099[ُم‌ۖ م]ّ[o[َآ] أَنَا۟ بِمُصْرِخِكُمْ وَم[o[َآ] أَ[f:428[نت][c:7100[ُم ب]ِمُصْرِخِىَّ‌ۖ إِ[g[نّ]ِى كَفَرْتُ بِم[o[َآ] أَشْرَكْتُمُونِ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۗ إِ[g[نّ]َ [h:7101[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ لَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Иш битиб бўлганда шайтон: «Албатта, Аллоҳ сизга ҳақ ваъдани қилган эди. Мен эса, сизга ваъда бердим-у, ваъдамга хилоф қилдим. Менинг устингиздан ҳеч қандай ҳукмронлигим йўқ эди. Фақат даъват қилсам, ўзингиз менга ижобат қилдингиз. Бас, мени маломат қилманг, ўзингизни маломат қилинг. Мен сизларни қутқарувчи эмасман, сизлар ҳам мени қутқарувчи эмассизлар. Энди, мен, албатта, илгари мени шерик қилганингизни инкор қиламан. Албатта, золимларга, ҳа, уларга аламли азоб бор», деди.",258,13],["وَأُ[q:2480[دْ]خِلَ [h:7102[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ‌ۖ تَحِيَّتُهُمْ فِيهَا سَلَ[p[ـٰ]مٌ","Ва иймон келтириб, амали солиҳ қилганлар остидан анҳорлар оқиб турган жаннатларга киритилурлар. Унда Роббилари изни ила абадий қолурлар. Уларнинг ундаги сўрашишлари «Салом»дир.",258,13],["أَلَمْ تَرَ كَيْفَ ضَرَبَ [h:7103[ٱ]للَّهُ مَثَل[f:7104[اً ك]َلِمَ[f:7105[ةً ط]َيِّبَ[f:7106[ةً ك]َشَجَرَ[f:7107[ةٍ ط]َيِّبَةٍ أَصْلُهَا ثَابِ[a:7108[تٌ و]َفَرْعُهَا فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ","Аллоҳ яхши сўзга қандай мисол келтирганини кўрмайсанми? У худди бир яхши дарахтга ўхшайдир. Унинг асли собит турадир. Шохлари эса, осмонда.",258,13],["تُؤْت[o[ِىٓ] أُكُلَهَا كُلَّ حِي[i:7109[نِۭ ب]ِإِذْنِ رَبِّهَا‌ۗ وَيَضْرِبُ [h:7110[ٱ]للَّهُ [h:6948[ٱ]لْأَمْثَالَ لِل[g[نّ]َاسِ لَعَلَّهُمْ يَتَذَكَّر[p[ُو]نَ","Робби изни ила ҳар доим меваларини бериб турадир. Аллоҳ, шояд эсласалар, деб одамларга мисоллар келтирадир.",259,13],["وَمَثَلُ كَلِمَةٍ خَبِيثَ[f:7111[ةٍ ك]َشَجَرَةٍ خَبِيثَةٍ [h:7112[ٱ][q:7113[جْ]تُثَّتْ مِ[f:7114[ن ف]َوْقِ [h:7115[ٱ]لْأَرْضِ مَا لَهَا مِ[f:7116[ن ق]َر[p[َا]رٍ","Ёмон сўзнинг мисоли, худди ёмон дарахтга ўхшайдир. У ердан узилиб қолган, унинг қарори йўқдир.",259,13],["يُثَبِّتُ [h:7117[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ ءَامَنُو[s[اْ] بِ[h:7118[ٱ]لْقَوْلِ [h:7119[ٱ][l[ل]ثَّابِتِ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا وَفِى [h:1108[ٱ]لْأَخِرَةِ‌ۖ وَيُضِلُّ [h:7120[ٱ]للَّهُ [h:7121[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ‌ۚ وَيَفْعَلُ [h:7122[ٱ]للَّهُ مَا يَش[o[َا]ٓءُ","Аллоҳ иймон келтирганларни бу дунё ҳаётида ҳам, охиратда ҳам собит сўз ила собитқадам қилур. Аллоҳ золимларни залолатга кетказур. Аллоҳ хоҳлаганини қилур.",259,13],["۞ أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ بَدَّلُو[s[اْ] نِعْمَتَ [h:1300[ٱ]للَّهِ كُفْ[a:7123[رًا و]َأَحَلُّو[s[اْ] قَوْمَهُمْ دَارَ [h:7124[ٱ]لْبَو[p[َا]رِ","Аллоҳнинг неъматини куфрга алмаштирган ва қавмларини ҳалокат диёрига туширганларни кўрмадингми?",259,13],["جَهَ[g[نّ]َمَ يَصْلَوْنَهَا‌ۖ وَبِئْسَ [h:7125[ٱ]لْقَر[p[َا]رُ","Улар жаҳаннамга кирурлар. Бу қандоқ ҳам ёмон қароргоҳ!",259,13],["وَجَعَلُو[s[اْ] لِلَّهِ أَ[f:96[ند]َا[u:7126[دًا ل]ِّيُضِلُّو[s[اْ] عَ[f:4361[ن س]َبِيلِه[n[ِۦ]‌ۗ قُلْ تَمَتَّعُو[s[اْ] فَإِ[g[نّ]َ مَصِيرَكُمْ إِلَى [h:1241[ٱ][l[ل][g[نّ][p[َا]رِ","Улар Аллоҳнинг йўлидан адаштириш учун Унга тенгдошлар қилдилар. Сен уларга: «Ҳузурланиб қолинг! Бас, албатта, борадиган жойингиз дўзахдир», деб айт!",259,13],["قُل لِّعِبَادِىَ [h:7127[ٱ]لَّذِينَ ءَامَنُو[s[اْ] يُقِيمُو[s[اْ] [h:7128[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَيُ[f:7129[نف]ِقُو[s[اْ] مِ[g[مّ]َا رَزَ[q:15[قْ]نَ[n[ـٰ]هُمْ سِر[a:1623[ًّا و]َعَلَانِيَ[a:7130[ةً م]ِّ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:1462[َن ي]َأْتِىَ يَوْ[u:1463[مٌ ل]َّا بَيْ[f:1464[عٌ ف]ِيهِ وَلَا خِلَ[p[ـٰ]لٌ","Сен иймон келтирган бандаларимга айтгин, намозни тўла-тўкис адо этсинлар. Савдо-сотиқ, оғайнигарчилик йўқ бўлган Кун келмасидан олдин уларга ризқ қилиб берган нарсаларимиздан махфий ва ошкор инфоқ қилсинлар.",259,13],["ٱللَّهُ [h:4738[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَأَ[f:91[نز]َلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:92[ءً ف]َأَخْرَجَ بِه[n[ِۦ] مِنَ [h:93[ٱ][l[ل]ثَّمَر[n[َٲ]تِ رِزْ[u:94[قًا ل]َّكُمْ‌ۖ وَسَخَّرَ لَكُمُ [h:7131[ٱ]لْفُلْكَ لِتَ[q:7132[جْ]رِىَ فِى [h:837[ٱ]لْبَحْرِ بِأَمْرِه[n[ِۦ]‌ۖ وَسَخَّرَ لَكُمُ [h:7133[ٱ]لْأَنْهَ[p[ـٰ]رَ","Аллоҳ осмонлару ерни яратган, осмондан сув тушириб, у ила меваларни сизга ризқ қилиб чиқарган, Ўз амри ила денгизда сузмоғи учун кемаларни сизга бўйсундирган ва анҳорларни сизга бўйсундирган зотдир.",259,13],["وَسَخَّرَ لَكُمُ [h:7134[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ د[o[َا]ٓئِبَيْنِ‌ۖ وَسَخَّرَ لَكُمُ [h:6116[ٱ]لَّيْلَ وَ[h:6117[ٱ][l[ل][g[نّ]َه[p[َا]رَ","У сизга доимий ҳаракатдаги қуёш ва ойни ҳам, шунингдек, кеча ила кундузни ҳам хизматчи қилиб қўйди.",259,13],["وَءَاتَ[n[ـٰ]ك[w:7135[ُم م]ِّ[f:843[ن ك]ُلِّ مَا سَأَلْتُمُوهُ‌ۚ وَإِ[f:7136[ن ت]َعُدُّو[s[اْ] نِعْمَتَ [h:1300[ٱ]للَّهِ لَا تُحْصُوه[o[َآ‌ۗ] إِ[g[نّ]َ [h:7137[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ لَظَلُو[f:7138[مٌ ك]َفّ[p[َا]رٌ","Ва У сизга барча сўраган нарсаларингиздан берди. Агар Аллоҳнинг неъматларини санасангиз, саноғига ета олмассизлар. Албатта, инсон ўта золим ва ўта ношукрдир.",260,13],["وَإِذْ قَالَ إِ[q:2003[بْ]ر[n[َٲ]هِيمُ رَبِّ [h:657[ٱ][q:658[جْ]عَلْ هَ[n[ـٰ]ذَا [h:7139[ٱ]لْبَلَدَ ءَامِ[a:7140[نًا و]َ[h:7141[ٱ][q:7141[جْ]نُ[q:7141[بْ]نِى وَبَنِىَّ أ[a:6403[َن ن]َّعْبُدَ [h:7142[ٱ]لْأَصْن[p[َا]مَ","Эсла, Иброҳим демишди: «Эй Роббим, бу юртни омонлик юрти қилгин, мени ва болаларимни санамларга ибодат қилишимиздан четда қилгин.",260,13],["رَبِّ إِ[g[نّ]َهُ[g[نّ]َ أَضْلَلْنَ كَثِي[a:3614[رًا م]ِّنَ [h:721[ٱ][l[ل][g[نّ]َاسِ‌ۖ فَمَ[f:7143[ن ت]َبِعَنِى فَإِ[g[نّ]َهُ[n[ۥ] مِ[g[نّ]ِى‌ۖ وَمَنْ عَصَانِى فَإِ[g[نّ]َكَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Эй Роббим, албатта, улар одамлардан кўпини адаштирдилар. Бас, ким менга эргашса, у мендандир. Ким менга осий бўлса, албатта, Ўзинг мағфират қилгувчи ва раҳмлисан.",260,13],["رَّبَّن[o[َآ] إِ[g[نّ][o[ِىٓ] أَسْكَ[f:7144[نت]ُ مِ[f:7145[ن ذ]ُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِ[f:264[ند]َ بَيْتِكَ [h:7146[ٱ]لْمُحَرَّمِ رَبَّنَا لِيُقِيمُو[s[اْ] [h:7147[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ فَ[h:7148[ٱ][q:7148[جْ]عَلْ أَفْــِٔدَ[a:7149[ةً م]ِّنَ [h:721[ٱ][l[ل][g[نّ]َاسِ تَهْو[o[ِىٓ] إِلَيْهِمْ وَ[h:7150[ٱ]رْزُ[q:7150[قْ]ه[w:7151[ُم م]ِّنَ [h:93[ٱ][l[ل]ثَّمَر[n[َٲ]تِ لَعَلَّهُمْ يَشْكُر[p[ُو]نَ","Эй Роббимиз, ҳақиқатда мен ўз зурриётимдан, сенинг Байтул Ҳароминг ёнига, гиёҳсиз водийга жойлаштирдим. Эй Роббимиз, намозни тўкис адо этишлари учун Бас, Ўзинг одамлардан баъзиларининг қалбларини уларга талпинадиган қилгин ва уларни мевалардан ризқлантиргин. Шояд шукр қилсалар.",260,13],["رَبَّن[o[َآ] إِ[g[نّ]َكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ‌ۗ وَمَا يَخْفَىٰ عَلَى [h:412[ٱ]للَّهِ مِ[f:2103[ن ش][f:5402[َىْءٍ ف]ِى [h:44[ٱ]لْأَرْضِ وَلَا فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ","Эй Роббимиз, албатта, Сенинг Ўзинг махфий тутган нарсамизни ҳам, ошкор қилган нарсамизни ҳам яхши биласан. Аллоҳ учун на ердаю на осмонда бирор нарса махфий қолмас.",260,13],["ٱلْحَمْدُ لِلَّهِ [h:3912[ٱ]لَّذِى وَهَبَ لِى عَلَى [h:7152[ٱ]لْكِبَرِ إِسْمَ[n[ـٰ]عِيلَ وَإِسْحَ[n[ـٰ]قَ‌ۚ إِ[g[نّ]َ رَبِّى لَسَمِيعُ [h:7153[ٱ][l[ل]دُّع[o[َا]ٓءِ","Кексалик пайтимда менга Исмоил ва Исҳоқни ато қилган Аллоҳга ҳамд бўлсин. Албатта, Роббим дуони эшитгувчидир.",260,13],["رَبِّ [h:7154[ٱ][q:6717[جْ]عَلْنِى مُقِيمَ [h:7155[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ وَمِ[f:643[ن ذ]ُرِّيَّتِى‌ۚ رَبَّنَا وَتَقَبَّلْ دُع[o[َا]ٓءِ","Эй Роббим, мени ва зурриётларимни намозни тўкис адо этадиганлардан қилгин. Эй Роббимиз, дуони қабул этгин.",260,13],["رَبَّنَا [h:2305[ٱ]غْفِرْ لِى وَلِو[n[َٲ]لِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ [h:7156[ٱ]لْحِس[p[َا][q[ب]ُ","Эй Роббимиз, мени, ота-онамни ва мўминларни ҳисоб қилинадиган куни мағфират айлагин».",260,13],["وَلَا تَحْسَبَ[g[نّ]َ [h:7157[ٱ]للَّهَ غَ[n[ـٰ]فِلاً عَ[g[مّ]َا يَعْمَلُ [h:7158[ٱ][l[ل]ظَّ[n[ـٰ]لِمُونَ‌ۚ إِ[g[نّ]َمَا يُؤَخِّرُهُمْ لِيَوْ[f:7159[مٍ ت]َشْخَصُ فِيهِ [h:7160[ٱ]لْأَ[q:4305[بْ]صَ[p[ـٰ]رُ","Сен ҳаргиз, Аллоҳ золимлар қилаётган нарсадан ғофил, деб гумон қилма. Фақатгина уларни кўзлар қотиб қоладиган кунгача қўйиб қўяди, холос.",260,13],["مُهْطِعِينَ مُ[q:7161[قْ]نِعِى رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ‌ۖ وَأَفْــِٔدَتُهُمْ هَو[o[َا]ٓءٌ","Улар бошларини кўтарган ҳолда югурурлар. Кўзлари ўзларига қайтмайдир. Кўнгиллари эса, бўм-бўш бўлур.",261,13],["وَأَ[f:7162[نذ]ِرِ [h:7163[ٱ][l[ل][g[نّ]َاسَ يَوْمَ يَأْتِيهِمُ [h:7164[ٱ]لْعَذَابُ فَيَقُولُ [h:7165[ٱ]لَّذِينَ ظَلَمُو[s[اْ] رَبَّن[o[َآ] أَخِّرْن[o[َآ] إِلَ[o[ىٰٓ] أَجَ[f:2940[لٍ ق]َرِي[a:7166[بٍ ن]ُّجِ[q:7167[بْ] دَعْوَتَكَ وَنَتَّبِعِ [h:7168[ٱ][l[ل]رُّسُلَ‌ۗ أَوَلَمْ تَكُون[o[ُوٓ][s[اْ] أَ[q:4723[قْ]سَمْت[w:7169[ُم م]ِّ[f:128[ن ق]َ[q:129[بْ]لُ مَا لَك[w:556[ُم م]ِّ[f:7170[ن ز]َو[p[َا]لٍ","Сен одамларни уларга азоб келадиган Кундан огоҳлантир. Ўшанда зулм қилганлар: «Эй Роббимиз, бизни озгина вақт қўйиб тургин, Сенинг даъватингни қабул қиламиз ва Пайғамбарларга эргашамиз», дерлар. Бундан олдин сизларга завол йўқлигига қасам ичмаган эдингизми?!",261,13],["وَسَكَ[f:7171[نت]ُمْ فِى مَسَ[n[ـٰ]كِنِ [h:7172[ٱ]لَّذِينَ ظَلَم[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَ[q:7173[بْ]نَا لَكُمُ [h:7174[ٱ]لْأَمْث[p[َا]لَ","Ва ўзига зулм қилганларнинг масканларига жойлашмадингизми? Сизга уларни қандай қилганимиз равшан бўлмадими? Сизга мисоллар келтирмадикми?",261,13],["وَقَ[q:387[دْ] مَكَرُو[s[اْ] مَكْرَهُمْ وَعِ[f:5476[ند]َ [h:7175[ٱ]للَّهِ مَكْرُهُمْ وَإِ[f:1649[ن ك]َانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ [h:7176[ٱ]لْجِب[p[َا]لُ","Дарҳақиқат, улар ўз макрларини қилдилар. Ҳолбуки, уларнинг макрлари, гарчи макрларидан тоғлар заволга учрайдиган бўлса ҳам, Аллоҳнинг ҳузуридадир.",261,13],["فَلَا تَحْسَبَ[g[نّ]َ [h:7157[ٱ]للَّهَ مُخْلِفَ وَعْدِه[n[ِۦ] رُسُلَهُ[o[ۥٓ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَزِي[f:1729[زٌ ذ]ُو [h:1730[ٱ][f:1731[نت]ِق[p[َا]مٍ","Сен, Аллоҳ Пайғамбарларига берган ваъдасига хилоф қилувчи, деб гумон қилма. Албатта, Аллоҳ азиз ва интиқом эгасидир.",261,13],["يَوْمَ تُبَدَّلُ [h:7177[ٱ]لْأَرْضُ غَيْرَ [h:7178[ٱ]لْأَرْضِ وَ[h:7179[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تُ‌ۖ وَبَرَزُو[s[اْ] لِلَّهِ [h:7180[ٱ]لْو[n[َٲ]حِدِ [h:7181[ٱ]لْقَهّ[p[َا]رِ","Ер бошқа ерга ва осмонлар ҳам бошқа осмонларга алмаштириладиган, ёлғиз ва қаҳҳор Аллоҳ ҳузурида пайдо бўлишадиган Кунда бўлади.",261,13],["وَتَرَى [h:7182[ٱ]لْمُ[q:4093[جْ]رِمِينَ يَوْمَئِ[a:7183[ذٍ م]ُّقَرَّنِينَ فِى [h:7184[ٱ]لْأَصْف[p[َا][q[د]ِ","Ва у кунда жиноятчиларни кишанлар ила тўпланган ҳолларида кўрасан.",261,13],["سَرَابِيلُه[w:7185[ُم م]ِّ[f:7186[ن ق]َطِرَا[a:7187[نٍ و]َتَغْشَىٰ وُجُوهَهُمُ [h:7188[ٱ][l[ل][g[نّ][p[َا]رُ","Уларнинг кийимлари қора мойдан бўлиб, юзларини олов қоплагандир.",261,13],["لِيَ[q:5945[جْ]زِىَ [h:7189[ٱ]للَّهُ كُلَّ نَفْ[a:1654[سٍ م]َّا كَسَبَتْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَرِيعُ [h:1112[ٱ]لْحِس[p[َا][q[ب]ِ","Аллоҳ ҳар бир жонга қилган касбига яраша жазо бериши учундир. Албатта, Аллоҳ тез ҳисоб қилгувчидир.",261,13],["هَ[n[ـٰ]ذَا بَلَ[n[ـٰ][u:7190[غٌ ل]ِّل[g[نّ]َاسِ وَلِيُ[f:7191[نذ]َرُو[s[اْ] بِه[n[ِۦ] وَلِيَعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َمَا هُوَ إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[a:7192[دٌ و]َلِيَذَّكَّرَ أُ[s[وْ]لُو[s[اْ] [h:1595[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","Бу одамлар учун, уларнинг у ила огоҳлантирилишлари, У ягона илоҳ эканини билишлари ва ақл эгалари эслашлари учун баёнотдир.",261,13]]},{"n":15,"ar":"الحِجۡرِ","en":"Al-Hijr","uz":"Ҳижр","type":"Макка","ayahs":[["ا[m[لٓ]ر‌ۚ تِلْكَ ءَايَ[n[ـٰ]تُ [h:5932[ٱ]لْكِتَ[n[ـٰ]بِ وَقُرْءَا[a:7193[نٍ م]ُّب[p[ِي]نٍ","Алиф. Лоом. Ро. Ушбулар китобнинг ва равшан Қуръоннинг оятларидир.",262,14],["رُّبَمَا يَوَدُّ [h:544[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَوْ كَانُو[s[اْ] مُسْلِم[p[ِي]نَ","Ҳали, куфр келтирганлар мусулмон бўлишни ҳам истаб қолурлар.",262,14],["ذَرْهُمْ يَأْكُلُو[s[اْ] وَيَتَمَتَّعُو[s[اْ] وَيُلْهِهِمُ [h:7194[ٱ]لْأَمَلُ‌ۖ فَسَوْفَ يَعْلَم[p[ُو]نَ","Уларни тек қўй, еб-ичиб, ҳузурланиб, умидлар ила машғул бўлиб юраверсинлар. Бас, тезда билурлар.",262,14],["وَم[o[َآ] أَهْلَكْنَا مِ[f:4585[ن ق]َرْيَةٍ إِلَّا وَلَهَا كِتَا[a:7195[بٌ م]َّعْل[p[ُو]مٌ","Биз маълум битиксиз ҳеч бир шаҳарни ҳалок этганимиз йўқ.",262,14],["مَّا تَسْبِقُ مِنْ أُ[g[مّ]َةٍ أَجَلَهَا وَمَا يَسْتَــْٔخِر[p[ُو]نَ","Ҳеч бир уммат ўз ажалидан ўзиб кета олмас ва ортда ҳам қола олмас.",262,14],["وَقَالُو[s[اْ] يَ[o[ـٰٓ]أَيُّهَا [h:7196[ٱ]لَّذِى نُزِّلَ عَلَيْهِ [h:7197[ٱ][l[ل]ذِّكْرُ إِ[g[نّ]َكَ لَمَ[q:7198[جْ]ن[p[ُو]نٌ","Улар: «Эй зикр нозил қилинган киши, албатта, сен мажнунсан.",262,14],["لَّوْ مَا تَأْتِينَا بِ[h:7199[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ إِ[f:4792[ن ك]ُ[f:735[نت]َ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","«Агар ростгўйлардан бўлсанг, бизга фаришталарни келтирсанг-чи», дерлар.",262,14],["مَا نُنَزِّلُ [h:7200[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةَ إِلَّا بِ[h:370[ٱ]لْحَقِّ وَمَا كَان[o[ُوٓ][s[اْ] إِ[a:7201[ذًا م]ُّ[f:7202[نظ]َر[p[ِي]نَ","Биз фаришталарни фақат ҳақ ила тушурурмиз, холос. У ҳолда уларга қараб турилмас.",262,14],["إِ[g[نّ]َا نَحْنُ نَزَّلْنَا [h:7203[ٱ][l[ل]ذِّكْرَ وَإِ[g[نّ]َا لَهُ[n[ۥ] لَحَ[n[ـٰ]فِظ[p[ُو]نَ","Албатта, зикрни Биз нозил қилдик ва, албатта, уни Биз муҳофаза қилурмиз.",262,14],["وَلَقَ[q:341[دْ] أَرْسَلْنَا مِ[f:18[ن ق]َ[q:19[بْ]لِكَ فِى شِيَعِ [h:7204[ٱ]لْأَوَّل[p[ِي]نَ","Батаҳқиқ, сендан олдин ҳам аввалгилар гуруҳларига юборганмиз.",262,14],["وَمَا يَأْتِيه[w:7205[ِم م]ّ[u:2882[ِن ر]َّسُولٍ إِلَّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Уларга қайси бир Пайғамбар келса, уни масхара қилмасдан қўймас эдилар.",262,14],["كَذ[n[َٲ]لِكَ نَسْلُكُهُ[n[ۥ] فِى قُلُوبِ [h:7206[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","Шунга ўхшаш Биз уни жиноятчилар қалбига солармиз.",262,14],["لَا يُؤْمِنُونَ بِه[n[ِۦ]‌ۖ وَقَ[q:387[دْ] خَلَتْ سُ[g[نّ]َةُ [h:7207[ٱ]لْأَوَّل[p[ِي]نَ","Унга иймон келтирмаслар. Батаҳқиқ, аввалгиларнинг суннати-одати шундоқ ўтгандир.",262,14],["وَلَوْ فَتَحْنَا عَلَيْه[c:7208[ِم ب]َا[a:7209[بًا م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ فَظَلُّو[s[اْ] فِيهِ يَعْرُج[p[ُو]نَ","Агар уларга осмондан бир эшик очсагу ундан чиқиб турсалар ҳам.",262,14],["لَقَال[o[ُوٓ][s[اْ] إِ[g[نّ]َمَا سُكِّرَتْ أَ[q:7210[بْ]صَ[n[ـٰ]رُنَا بَلْ نَحْنُ قَوْ[a:7211[مٌ م]َّسْحُور[p[ُو]نَ","Улар: «Албатта, кўзларимиз боғланди, балки биз сеҳрланган қавмдирмиз», дерлар.",262,14],["وَلَقَ[q:341[دْ] جَعَلْنَا فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ بُرُو[a:7212[جًا و]َزَيَّ[g[نّ]َ[n[ـٰ]هَا لِل[g[نّ]َ[n[ـٰ]ظِر[p[ِي]نَ","Батаҳқиқ, Биз осмонларда буржлар қилиб қўйдик ва уни назар солувчилар учун зийнатлаб қўйдик.",263,14],["وَحَفِظْنَ[n[ـٰ]هَا مِ[f:843[ن ك]ُلِّ شَيْطَ[n[ـٰ][u:7213[نٍ ر]َّج[p[ِي]مٍ","Уни ҳар бир қувилган шайтондан муҳофаза қилдик.",263,14],["إِلَّا مَنِ [h:7214[ٱ]سْتَرَقَ [h:7215[ٱ][l[ل]سَّمْعَ فَأَتْبَعَهُ[n[ۥ] شِهَا[a:7216[بٌ م]ُّب[p[ِي]نٌ","Магар бирортаси ўғриликча қулоқ осса, равшан олов унинг ортидан тушар.",263,14],["وَ[h:9999[ٱ]لْأَرْضَ مَدَ[q:7217[دْ]نَ[n[ـٰ]هَا وَأَلْقَيْنَا فِيهَا رَو[n[َٲ]سِىَ وَأَ[i:7218[نۢب]َتْنَا فِيهَا مِ[f:843[ن ك]ُلِّ ش[a:7219[َىْءٍ م]َّوْز[p[ُو]نٍ","Биз ерни ёйиб, устига баланд тоғларни ташлаб қўйдик ва унда ўлчанган турли нарсаларни ўстириб қўйдик.",263,14],["وَجَعَلْنَا لَكُمْ فِيهَا مَعَ[n[ـٰ]يِشَ وَم[u:7220[َن ل]َّسْتُمْ لَهُ[n[ۥ] بِر[n[َٲ]زِق[p[ِي]نَ","Ва унда сизлар учун маош воситаларини ва сиз ризқини бера олмайдиган кимсаларни қилиб қўйдик.",263,14],["وَإ[a:3281[ِن م]ِّ[f:2103[ن ش]َىْءٍ إِلَّا عِ[f:2359[ند]َنَا خَز[o[َا]ٓئِنُهُ[n[ۥ] وَمَا نُنَزِّلُهُ[o[ۥٓ] إِلَّا بِقَدَ[a:7221[رٍ م]َّعْل[p[ُو]مٍ","Ҳеч бир нарса йўқки, унинг хазиналари Бизнинг ҳузуримизда бўлмаса. Биз уни фақат маълум миқдорла нозил қилурмиз.",263,14],["وَأَرْسَلْنَا [h:7222[ٱ][l[ل]رِّيَ[n[ـٰ]حَ لَو[n[َٲ]قِحَ فَأَ[f:288[نز]َلْنَا مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:7223[ءً ف]َأَسْقَيْنَ[n[ـٰ]كُمُوهُ وَم[o[َآ] أَ[f:428[نت]ُمْ لَهُ[n[ۥ] بِخَ[n[ـٰ]زِن[p[ِي]نَ","Биз шамолларни урчитувчилар этиб юбордик. Бас, осмондан сув тушириб, у ила сизларни сероб қилдик. Сизлар уни тўплаб олувчи эмассиз.",263,14],["وَإِ[g[نّ]َا لَنَحْنُ نُحْى[n[ِۦ] وَنُمِيتُ وَنَحْنُ [h:7224[ٱ]لْو[n[َٲ]رِث[p[ُو]نَ","Албатта, Биз Ўзимиз тирилтирурмиз ва Биз меросхўрлармиз.",263,14],["وَلَقَ[q:341[دْ] عَلِمْنَا [h:7225[ٱ]لْمُسْتَ[q:7226[قْ]دِمِينَ مِ[f:344[نك]ُمْ وَلَقَ[q:341[دْ] عَلِمْنَا [h:7227[ٱ]لْمُسْتَــْٔخِر[p[ِي]نَ","Батаҳқиқ, сиздан олдин келганларни билдик. Батаҳқиқ, кейин келганларни ҳам билдик.",263,14],["وَإِ[g[نّ]َ رَبَّكَ هُوَ يَحْشُرُهُمْ‌ۚ إِ[g[نّ]َهُ[n[ۥ] حَكِيمٌ عَل[p[ِي]مٌ","Албатта, сенинг Роббинг Ўзи уларни маҳшарга жамлар. Албатта, У ҳикматли ва илмли Зотдир.",263,14],["وَلَقَ[q:341[دْ] خَلَ[q:5159[قْ]نَا [h:7228[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ مِ[f:7229[ن ص]َلْصَ[n[ـٰ][a:7230[لٍ م]ِّنْ حَمَ[a:7231[إٍ م]َّسْن[p[ُو]نٍ","Батаҳқиқ, Биз инсонни қуруқ лойдан, ўзгартирилган қора балчиқдан яратдик.",263,14],["وَ[h:9999[ٱ]لْج[m[َا]ٓ[g[نّ]َ خَلَ[q:7232[قْ]نَ[n[ـٰ]هُ مِ[f:128[ن ق]َ[q:129[بْ]لُ م[a:7233[ِن ن]َّارِ [h:7234[ٱ][l[ل]سَّم[p[ُو]مِ","Ва жинларни бундан олдин самум оловидан яратдик.",263,14],["وَإِذْ قَالَ رَبُّكَ لِلْمَلَ[o[ـٰٓ]ئِكَةِ إِ[g[نّ]ِى خَ[n[ـٰ]لِ[i:7235[قُۢ ب]َشَ[a:7236[رًا م]ِّ[f:7229[ن ص]َلْصَ[n[ـٰ][a:7230[لٍ م]ِّنْ حَمَ[a:7231[إٍ م]َّسْن[p[ُو]نٍ","Сен Роббингнинг фаришталарга: «Албатта, мен қуруқ лойдан, ўзгартирилган қора балчиқдан башар яратгувчидирман.",263,14],["فَإِذَا سَوَّيْتُهُ[n[ۥ] وَنَفَخْتُ فِيهِ م[u:7237[ِن ر]ُّوحِى فَقَعُو[s[اْ] لَهُ[n[ۥ] سَ[n[ـٰ]جِد[p[ِي]نَ","Бас, қачонки уни тўғрилаб бўлганимда ва ичига Ўз руҳимдан пуфлаганимда, унга сажда қилган ҳолингизда йиқилинг», деганини эсла.",263,14],["فَسَجَدَ [h:7238[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ كُلُّهُمْ أَ[q:7239[جْ]مَع[p[ُو]نَ","Бас, фаришталар барчалари сажда қилдилар.",263,14],["إِلّ[o[َآ] إِ[q:180[بْ]لِيسَ أَبَ[o[ىٰٓ] أ[a:3312[َن ي]َكُونَ مَعَ [h:7240[ٱ][l[ل]سَّ[n[ـٰ]جِد[p[ِي]نَ","Магар Иблис сажда қилувчилар билан бирга бўлишдан бош тортди.",263,14],["قَالَ يَ[o[ـٰٓ]إِ[q:7241[بْ]لِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ [h:7240[ٱ][l[ل]سَّ[n[ـٰ]جِد[p[ِي]نَ","У зот: «Эй иблис! Сенга не бўлди, сажда қилувчилар билан бирга бўлмаслигингга?» деди.",264,14],["قَالَ لَمْ أَك[u:7242[ُن ل]ِّأَسْجُدَ لِبَشَرٍ خَلَ[q:7243[قْ]تَهُ[n[ۥ] مِ[f:7229[ن ص]َلْصَ[n[ـٰ][a:7230[لٍ م]ِّنْ حَمَ[a:7231[إٍ م]َّسْن[p[ُو]نٍ","У: «Сен қуруқ лойдан, ўзгартирилган қора балчиқдан яратган башарга сажда қила олмасдим», деди.",264,14],["قَالَ فَ[h:4603[ٱ]خْرُ[q:4603[جْ] مِنْهَا فَإِ[g[نّ]َكَ رَج[p[ِي]مٌ","У зот: «Бас, сен ундан чиқ! Албатта, сен қувилгансан!",264,14],["وَإِ[g[نّ]َ عَلَيْكَ [h:7244[ٱ][l[ل]لَّعْنَةَ إِلَىٰ يَوْمِ [h:5[ٱ][l[ل]دّ[p[ِي]نِ","Ва, албатта, сенга то жазо кунигача лаънат бўлур!» деди.",264,14],["قَالَ رَبِّ فَأَ[f:7245[نظ]ِرْن[o[ِىٓ] إِلَىٰ يَوْمِ يُ[q:4606[بْ]عَث[p[ُو]نَ","У: «Эй Роббим, мени улар қайта тириладиган кунгача қўйиб қўйгин», деди.",264,14],["قَالَ فَإِ[g[نّ]َكَ مِنَ [h:4607[ٱ]لْمُ[f:4608[نظ]َر[p[ِي]نَ","У зот: «Албатта, сен қўйиб қўйилганлардансан.",264,14],["إِلَىٰ يَوْمِ [h:7246[ٱ]لْوَ[q:7247[قْ]تِ [h:7248[ٱ]لْمَعْل[p[ُو]مِ","Маълум вақт кунигача», деди.",264,14],["قَالَ رَبِّ بِم[o[َآ] أَغْوَيْتَنِى لَأُزَيِّنَ[g[نّ]َ لَهُمْ فِى [h:44[ٱ]لْأَرْضِ وَلَأُغْوِيَ[g[نّ]َهُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","У: «Эй Роббим, мени залолатга кетказганинг сабабидан, албатта, мен уларга ер юзида зийнатлаб кўрсатаман ва, албатта, уларнинг ҳаммасини иғво қиламан.",264,14],["إِلَّا عِبَادَكَ مِنْهُمُ [h:7249[ٱ]لْمُخْلَص[p[ِي]نَ","Магар, улардан танланган бандаларингни», деди.",264,14],["قَالَ هَ[n[ـٰ]ذَا صِر[n[َٲ]طٌ عَلَىَّ مُسْتَق[p[ِي]مٌ","У зот: «Ушбу зиммамдаги тўғри йўлдир:",264,14],["إِ[g[نّ]َ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَ[n[ـٰ]نٌ إِلَّا مَنِ [h:7250[ٱ]تَّبَعَكَ مِنَ [h:5135[ٱ]لْغَاو[p[ِي]نَ","Албатта, Менинг бандаларим устида сенинг султонинг йўқдир, магар сенга эргашган гумроҳларгагина бордир.",264,14],["وَإِ[g[نّ]َ جَهَ[g[نّ]َمَ لَمَوْعِدُهُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Албатта, жаҳаннам уларнинг барчасининг ваъда қилинган жойидир.",264,14],["لَهَا سَ[q:7251[بْ]عَةُ أَ[q:6744[بْ]و[n[َٲ][u:7252[بٍ ل]ِّكُلِّ بَا[a:7253[بٍ م]ِّنْهُمْ جُزْ[a:7254[ءٌ م]َّ[q:7255[قْ]س[p[ُو]مٌ","Унинг етти эшиги бордир. Ҳар бир эшик учун улардан тақсимланган бўлаги бордир» деди.",264,14],["إِ[g[نّ]َ [h:7256[ٱ]لْمُتَّقِينَ فِى جَ[g[نّ]َ[n[ـٰ][a:7257[تٍ و]َعُي[p[ُو]نٍ","Албатта, тақводорлар жаннатлар ва чашмалардадир.",264,14],["ٱ[q:7258[دْ]خُلُوهَا بِسَلَ[n[ـٰ]مٍ ءَامِن[p[ِي]نَ","«Уга тинчлик, омонлик ила киринглар».",264,14],["وَنَزَعْنَا مَا فِى صُدُورِه[w:4694[ِم م]ِّنْ غِلٍّ إِخْو[n[َٲ]نًا عَلَىٰ سُرُ[a:7259[رٍ م]ُّتَقَ[n[ـٰ]بِل[p[ِي]نَ","Уларнинг дилларидаги ғилли-ғиштларни чиқариб ташладик. Сўриларда бир-бирларига боқиб, дўст бўлган ҳолларида ўлтирурлар.",264,14],["لَا يَمَسُّهُمْ فِيهَا نَصَ[a:7260[بٌ و]َمَا ه[w:7261[ُم م]ِّنْهَا بِمُخْرَج[p[ِي]نَ","Уларни у жойда чарчоқ тутмас ва улар ундан чиқарилувчи ҳам эмаслар.",264,14],["۞ نَبِّئْ عِبَاد[o[ِىٓ] أَ[g[نّ][o[ِىٓ] أَنَا [h:7262[ٱ]لْغَفُورُ [h:6228[ٱ][l[ل]رَّح[p[ِي]مُ","Бандаларимга хабар бергил: «Албатта, Менинг Ўзим ғофуру роҳиймдирман».",264,14],["وَأَ[g[نّ]َ عَذَابِى هُوَ [h:7263[ٱ]لْعَذَابُ [h:7264[ٱ]لْأَل[p[ِي]مُ","Ва, албатта, азобим аламли азобдир.",264,14],["وَنَبِّئْهُمْ عَ[f:7265[ن ض]َيْفِ إِ[q:1860[بْ]ر[n[َٲ]ه[p[ِي]مَ","Уларга Иброҳимнинг меҳмонлари хабарини бер.",264,14],["إِذْ دَخَلُو[s[اْ] عَلَيْهِ فَقَالُو[s[اْ] سَلَ[n[ـٰ][f:6415[مًا ق]َالَ إِ[g[نّ]َا مِ[f:344[نك]ُمْ وَجِل[p[ُو]نَ","Унинг ҳузурига кирганларида: «Салом», дедилар. У: «Албатта, биз сизлардан қўрқмоқдамиз», деди.",265,14],["قَالُو[s[اْ] لَا تَوْجَلْ إِ[g[نّ]َا نُبَشِّرُكَ بِغُلَ[n[ـٰ]مٍ عَل[p[ِي]مٍ","Улар: «Қўрқма, биз сенга ўта билимдон ўғилнинг хушхабарини берурмиз», дедилар.",265,14],["قَالَ أَبَشَّرْتُمُونِى عَلَ[o[ىٰٓ] أ[a:7266[َن م]َّسَّنِىَ [h:7267[ٱ]لْكِبَرُ فَبِمَ تُبَشِّر[p[ُو]نَ","У: «Мени кексалик тутганида, хушхабар берасизларми? Ниманинг хушхабарини беряпсизлар ўзи?» деди.",265,14],["قَالُو[s[اْ] بَشَّرْنَ[n[ـٰ]كَ بِ[h:370[ٱ]لْحَقِّ فَلَا تَك[a:1974[ُن م]ِّنَ [h:7268[ٱ]لْقَ[n[ـٰ]نِط[p[ِي]نَ","Улар: «Биз сенга ҳақ ила башорат бердик. Бас, сен ноумид бўлувчилардан бўлма», дедилар.",265,14],["قَالَ وَم[a:7269[َن ي]َ[q:7270[قْ]نَطُ م[u:7271[ِن ر]َّحْمَةِ رَبِّه[o[ِۦٓ] إِلَّا [h:7272[ٱ][l[ل]ضّ[m[َا]ٓلّ[p[ُو]نَ","У: «Фақат залолатга кетган кишиларгина ўз Роббининг раҳматидан ноумид бўлурлар», деди.",265,14],["قَالَ فَمَا خَ[q:7273[طْ]بُكُمْ أَيُّهَا [h:7274[ٱ]لْمُرْسَل[p[ُو]نَ","У: «Эй элчилар, нима иш ила юборилдингиз?» деди.",265,14],["قَال[o[ُوٓ][s[اْ] إِ[g[نّ][o[َآ] أُرْسِلْن[o[َآ] إِلَىٰ قَوْ[a:7275[مٍ م]ُّ[q:4958[جْ]رِم[p[ِي]نَ","Улар: «Биз жиноятчи қавмларга юборилдик.",265,14],["إِلّ[o[َآ] ءَالَ لُوطٍ إِ[g[نّ]َا لَمُنَجُّوهُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Магар Лут аҳлига эмас. Албатта, Биз уларнинг ҳаммасини қутқаргувчилармиз.",265,14],["إِلَّا [h:4837[ٱ]مْرَأَتَهُ[n[ۥ] قَدَّرْن[o[َآ‌ۙ] إِ[g[نّ]َهَا لَمِنَ [h:7276[ٱ]لْغَ[n[ـٰ]بِر[p[ِي]نَ","Фақат унинг хотинигина истиснодир. Унинг, албатта, қолувчилардан бўлишини тақдир қилдик», дедилар.",265,14],["فَلَ[g[مّ]َا ج[o[َا]ٓءَ ءَالَ لُوطٍ [h:7277[ٱ]لْمُرْسَل[p[ُو]نَ","Элчилар Лут аҳлига келганларида...",265,14],["قَالَ إِ[g[نّ]َكُمْ قَوْ[a:7278[مٌ م]ُّ[f:7279[نك]َر[p[ُو]نَ","У: «Албатта, сиз нотаниш қавмсиз», деди.",265,14],["قَالُو[s[اْ] بَلْ جِئْنَ[n[ـٰ]كَ بِمَا كَانُو[s[اْ] فِيهِ يَمْتَر[p[ُو]نَ","Улар: «Йўқ! Биз сенга улар шак қилаётган нарса ила келдик.",265,14],["وَأَتَيْنَ[n[ـٰ]كَ بِ[h:370[ٱ]لْحَقِّ وَإِ[g[نّ]َا لَصَ[n[ـٰ]دِق[p[ُو]نَ","Сенга ҳақ ила келдик ва албатта, бизлар ростгўйлардурмиз.",265,14],["فَأَسْرِ بِأَهْلِكَ بِقِ[q:6438[طْ][a:6439[عٍ م]ِّنَ [h:6029[ٱ]لَّيْلِ وَ[h:7280[ٱ]تَّبِعْ أَ[q:7281[دْ]بَ[n[ـٰ]رَهُمْ وَلَا يَلْتَفِتْ مِ[f:344[نك]ُمْ أَحَ[a:7282[دٌ و]َ[h:7283[ٱ]مْضُو[s[اْ] حَيْثُ تُؤْمَر[p[ُو]نَ","Аҳлинг ила кечанинг бир бўлагида йўлга чиқ, сен уларнинг ортидан кузатиб бор. Сизлардан ҳеч бирларингиз ортга қарамасин. Амр қилинган томонингизга кетаверинглар», дедилар.",265,14],["وَقَضَيْن[o[َآ] إِلَيْهِ ذ[n[َٲ]لِكَ [h:7284[ٱ]لْأَمْرَ أَ[g[نّ]َ دَابِرَ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ مَ[q:7285[قْ]طُو[a:7286[عٌ م]ُّصْبِح[p[ِي]نَ","Ва унга ушбу амрни ваҳий қилдик: «Албатта, анавиларнинг орқаси субҳ чоғи кесилажакдир».",265,14],["وَج[o[َا]ٓءَ أَهْلُ [h:7287[ٱ]لْمَدِينَةِ يَسْتَ[q:2415[بْ]شِر[p[ُو]نَ","Ва шаҳар аҳли севиниб, етиб келдилар.",265,14],["قَالَ إِ[g[نّ]َ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ ضَيْفِى فَلَا تَفْضَح[p[ُو]نِ","У: «Булар менинг меҳмонларим, ахир. Мени шарманда қилманглар.",265,14],["وَ[h:9999[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ وَلَا تُخْز[p[ُو]نِ","Ва Аллоҳдан қўрқинглар! Мени хор қилманглар», деди.",265,14],["قَال[o[ُوٓ][s[اْ] أَوَلَمْ نَنْهَكَ عَنِ [h:2124[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Улар: «Биз сени оламлардан қайтармаганмидик?!» дедилар.",265,14],["قَالَ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ بَنَات[o[ِىٓ] إِ[f:109[ن ك]ُ[f:100[نت]ُمْ فَ[n[ـٰ]عِل[p[ِي]نَ","У: «Агар қилувчи бўлсангиз, анаву қизларим бор», деди.",266,14],["لَعَمْرُكَ إِ[g[نّ]َهُمْ لَفِى سَكْرَتِهِمْ يَعْمَه[p[ُو]نَ","Сенинг умринг ила қасамки, албатта, улар ўз сархушликларида тентирамоқдалар.",266,14],["فَأَخَذَتْهُمُ [h:7288[ٱ][l[ل]صَّيْحَةُ مُشْرِق[p[ِي]نَ","Бас, уларни қуёш чиқиш пайтида даҳшатли қичқириқ тутди.",266,14],["فَجَعَلْنَا عَ[n[ـٰ]لِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهِمْ حِجَارَ[a:6444[ةً م]ِّ[f:6445[ن س]ِجّ[p[ِي]لٍ","Бас, Биз остини устин қилдик ва улар устига лойи қотган тошлар ёғдирдик.",266,14],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:7289[تٍ ل]ِّلْمُتَوَسِّم[p[ِي]نَ","Албатта, бунда фаросатли кишилар учун оят-белгилар бордир.",266,14],["وَإِ[g[نّ]َهَا لَبِسَبِي[a:7290[لٍ م]ُّق[p[ِي]مٍ","Албатта, у боқий йўл устидадир.",266,14],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:7291[ةً ل]ِّلْمُؤْمِن[p[ِي]نَ","Албатта, бунда мўминлар учун оят-ибрат бордир.",266,14],["وَإِ[f:1649[ن ك]َانَ أَصْحَ[n[ـٰ]بُ [h:7292[ٱ]لْأَيْكَةِ لَظَ[n[ـٰ]لِم[p[ِي]نَ","Албатта, бир-бирига киришиб кетган дарахтзор эгалари золимлардан бўлганлар.",266,14],["فَ[h:9999[ٱ][f:4969[نت]َقَمْنَا مِنْهُمْ وَإِ[g[نّ]َهُمَا لَبِإِمَا[a:7293[مٍ م]ُّب[p[ِي]نٍ","Бас, Биз улардан интиқом олдик. Албатта, уларнинг икковлари ҳам очиқ йўл устидадир.",266,14],["وَلَقَ[q:341[دْ] كَذَّبَ أَصْحَ[n[ـٰ]بُ [h:7294[ٱ]لْحِ[q:7295[جْ]رِ [h:7296[ٱ]لْمُرْسَل[p[ِي]نَ","Батаҳқиқ, Ҳижр эгалари Пайғамбарларни ёлғончига чиқардилар.",266,14],["وَءَاتَيْنَ[n[ـٰ]هُمْ ءَايَ[n[ـٰ]تِنَا فَكَانُو[s[اْ] عَنْهَا مُعْرِض[p[ِي]نَ","Ва уларга оятларимизни бердик. Бас, юз ўгирувчи бўлдилар.",266,14],["وَكَانُو[s[اْ] يَنْحِتُونَ مِنَ [h:7297[ٱ]لْجِبَالِ بُيُوتًا ءَامِن[p[ِي]نَ","Улар тоғдан ўйиб уй ясаб, омонликда юрар эдилар.",266,14],["فَأَخَذَتْهُمُ [h:7288[ٱ][l[ل]صَّيْحَةُ مُصْبِح[p[ِي]نَ","Бас, субҳидам чоғида уларни қаттиқ қичқириқ тутди.",266,14],["فَم[o[َآ] أَغْنَىٰ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Қилган касблари уларга бирон фойда бермади.",266,14],["وَمَا خَلَ[q:5159[قْ]نَا [h:7298[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَمَا بَيْنَهُم[o[َآ] إِلَّا بِ[h:370[ٱ]لْحَقِّ‌ۗ وَإِ[g[نّ]َ [h:7299[ٱ][l[ل]سَّاعَةَ لَأَتِيَ[f:7300[ةٌ‌ۖ ف]َ[h:7301[ٱ]صْفَحِ [h:7302[ٱ][l[ل]صَّفْحَ [h:7303[ٱ]لْجَم[p[ِي]لَ","Биз осмонлару ерни ва улардаги нарсаларни ҳақ ила яратдик. Албатта, қиёмат келгувчидир. Бас, сен гўзал шаклда юз ўгир.",266,14],["إِ[g[نّ]َ رَبَّكَ هُوَ [h:7304[ٱ]لْخَلَّ[n[ـٰ]قُ [h:7305[ٱ]لْعَل[p[ِي]مُ","Албатта, Роббинг яратгувчи ва билгувчи зотдир.",266,14],["وَلَقَ[q:341[دْ] ءَاتَيْنَ[n[ـٰ]كَ سَ[q:7306[بْ][a:7307[عًا م]ِّنَ [h:7308[ٱ]لْمَثَانِى وَ[h:7309[ٱ]لْقُرْءَانَ [h:7310[ٱ]لْعَظ[p[ِي]مَ","Ва, батаҳқиқ, сенга етти такрорланувчини ва Улуғ Қуръонни бердик.",266,14],["لَا تَمُدَّ[g[نّ]َ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِه[o[ِۦٓ] أَزْو[n[َٲ][a:7311[جًا م]ِّنْهُمْ وَلَا تَحْزَنْ عَلَيْهِمْ وَ[h:7312[ٱ]خْفِضْ جَنَاحَكَ لِلْمُؤْمِن[p[ِي]نَ","Биз улардан баъзи гуруҳларни баҳраманд қилган нарсаларга назар солма! Улар учун хафа ҳам бўлма! Мўминларга қанотингни пастлат!",266,14],["وَقُلْ إِ[g[نّ][o[ِىٓ] أَنَا [h:7313[ٱ][l[ل][g[نّ]َذِيرُ [h:7314[ٱ]لْمُب[p[ِي]نُ","Ва: «Албатта, мен очиқ-ойдин огоҳлантиргувчиман», деб айт.",266,14],["كَم[o[َآ] أَ[f:515[نز]َلْنَا عَلَى [h:7315[ٱ]لْمُ[q:7316[قْ]تَسِم[p[ِي]نَ","Худди тақсимловчиларга туширганимизга ўхшаш.",266,14],["ٱلَّذِينَ جَعَلُو[s[اْ] [h:7317[ٱ]لْقُرْءَانَ عِض[p[ِي]نَ","Қуръонни парча-парча қилганларга.",267,14],["فَوَرَبِّكَ لَنَسْــَٔلَ[g[نّ]َهُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Бас, Роббинг ила қасамки, уларнинг ҳаммасидан, албатта, сўрармиз.",267,14],["عَ[g[مّ]َا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Қилиб юрган ишлари ҳақида.",267,14],["فَ[h:9999[ٱ]صْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ [h:4314[ٱ]لْمُشْرِك[p[ِي]نَ","Бас, сенга амр этилган нарсани юзага чиқар ва мушриклардан юз ўгир.",267,14],["إِ[g[نّ]َا كَفَيْنَ[n[ـٰ]كَ [h:7318[ٱ]لْمُسْتَهْزِء[p[ِي]نَ","Албатта, Биз сенга истеҳзо қилувчилардан кифоя қилурмиз.",267,14],["ٱلَّذِينَ يَ[q:68[جْ]عَلُونَ مَعَ [h:3975[ٱ]للَّهِ إِلَ[n[ـٰ]هًا ءَاخَرَ‌ۚ فَسَوْفَ يَعْلَم[p[ُو]نَ","Улар Аллоҳ билан бирга бошқа илоҳ қилурлар. Бас, тезда билурлар.",267,14],["وَلَقَ[q:341[دْ] نَعْلَمُ أَ[g[نّ]َكَ يَضِيقُ صَ[q:6262[دْ]رُكَ بِمَا يَقُول[p[ُو]نَ","Албатта, Биз уларнинг айтаётганларидан сенинг дилинг сиқилишини яхши биламиз.",267,14],["فَسَبِّحْ بِحَمْدِ رَبِّكَ وَك[a:5006[ُن م]ِّنَ [h:4595[ٱ][l[ل]سَّ[n[ـٰ]جِد[p[ِي]نَ","Бас, Роббинг ҳамди ила тасбиҳ айт ва сажда қилгувчилардан бўл.",267,14],["وَ[h:9999[ٱ]عْبُ[q:7319[دْ] رَبَّكَ حَتَّىٰ يَأْتِيَكَ [h:7320[ٱ]لْيَق[p[ِي]نُ","Ва сенга аниқ нарса келгунича Роббингга ибодат қил.",267,14]]},{"n":16,"ar":"النَّحۡلِ","en":"An-Nahl","uz":"Наҳл","type":"Макка","ayahs":[["أَتَ[o[ىٰٓ] أَمْرُ [h:2832[ٱ]للَّهِ فَلَا تَسْتَعْجِلُوهُ‌ۚ سُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ] وَتَعَ[n[ـٰ]لَىٰ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","Аллоҳнинг амри келди. Бас, унинг тезроқ келишини талаб қилмай қўя қолинг. У зот улар келтираётган ширклардан пок ва олий бўлди.",267,14],["يُنَزِّلُ [h:7321[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةَ بِ[h:7322[ٱ][l[ل]رُّوحِ مِنْ أَمْرِه[n[ِۦ] عَلَىٰ م[a:476[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[o[ِۦٓ] أَنْ أَ[f:7323[نذ]ِر[o[ُوٓ][s[اْ] أَ[g[نّ]َهُ[n[ۥ] ل[o[َآ] إِلَ[n[ـٰ]هَ إِلّ[o[َآ] أَنَا۟ فَ[h:210[ٱ]تَّق[p[ُو]نِ","У Ўз амри ила фаришталарни руҳ-ваҳий билан бандаларидан Ўзи хоҳлаганларига: «Огоҳлантиринглар. Албатта, Мендан ўзга илоҳ йўқ. Бас, Менга тақво қилинглар», деб нозил қиладир.",267,14],["خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ بِ[h:370[ٱ]لْحَقِّ‌ۚ تَعَ[n[ـٰ]لَىٰ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","У осмонлару ерни ҳақ ила яратди. У улар ширк келтираётган нарсалардан олий бўлди.",267,14],["خَلَقَ [h:7324[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ م[a:7325[ِن ن]ُّ[q:7326[طْ]فَ[f:7327[ةٍ ف]َإِذَا هُوَ خَصِي[a:7328[مٌ م]ُّب[p[ِي]نٌ","У инсонни нутфадан яратди. Энди эса, у очиқ-ойдин хусуматчи бўлиб турибди.",267,14],["وَ[h:9999[ٱ]لْأَنْعَ[n[ـٰ]مَ خَلَقَهَا‌ۗ لَكُمْ فِيهَا دِفْ[a:7329[ءٌ و]َمَنَ[n[ـٰ]فِعُ وَمِنْهَا تَأْكُل[p[ُو]نَ","У чорва ҳайвонларини ҳам яратди. Уларда сиз учун иссиқлик манфаатлар бор ва улардан ейсизлар ҳам.",267,14],["وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَح[p[ُو]نَ","Ва сиз учун уларда кечки пайт қайтаётганларида ва эрталаб кетаётганида чиройли-жамол бор.",267,14],["وَتَحْمِلُ أَثْقَالَكُمْ إِلَىٰ بَلَ[u:7330[دٍ ل]َّمْ تَكُونُو[s[اْ] بَ[n[ـٰ]لِغِيهِ إِلَّا بِشِقِّ [h:7331[ٱ]لْأَ[f:7332[نف]ُسِ‌ۚ إِ[g[نّ]َ رَبَّكُمْ لَرَءُو[u:744[فٌ ر]َّح[p[ِي]مٌ","Ва улар юкларингизни сиз жон машаққатисиз ета олмайдиган юртларгача кўтариб борадир. Албатта, Роббингиз меҳрибон ва раҳмлидир.",268,14],["وَ[h:9999[ٱ]لْخَيْلَ وَ[h:7333[ٱ]لْبِغَالَ وَ[h:7334[ٱ]لْحَمِيرَ لِتَرْكَبُوهَا وَزِينَ[a:7335[ةً‌ۚ و]َيَخْلُقُ مَا لَا تَعْلَم[p[ُو]نَ","Отлар, хачирлар ва эшакларни минишингиз ва зийнат учун ва сиз билмайдиган нарсаларни яратадир.",268,14],["وَعَلَى [h:2207[ٱ]للَّهِ قَصْدُ [h:7336[ٱ][l[ل]سَّبِيلِ وَمِنْهَا ج[o[َا]ٓئِ[a:7337[رٌ‌ۚ و]َلَوْ ش[o[َا]ٓءَ لَهَدَ[n[ٮٰ]كُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Йўлларнинг мақсаддагиси Аллоҳга оиддир. Улардан эгриси ҳам бордир. Агар хоҳласа, албатта, ҳаммангизни ҳидоят қилган бўларди.",268,14],["هُوَ [h:153[ٱ]لَّذ[o[ِىٓ] أَ[f:471[نز]َلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[u:7338[ءً‌ۖ ل]َّك[w:6234[ُم م]ِّنْهُ شَرَا[a:7339[بٌ و]َمِنْهُ شَجَ[f:7340[رٌ ف]ِيهِ تُسِيم[p[ُو]نَ","У осмондан сувни туширган зотдир. Сизга ундан шароб ва ҳайвон ўтлатадиган дарахт бордир.",268,14],["يُ[i:7341[نۢب]ِتُ لَك[c:2000[ُم ب]ِهِ [h:7342[ٱ][l[ل]زَّرْعَ وَ[h:4290[ٱ][l[ل]زَّيْتُونَ وَ[h:7343[ٱ][l[ل][g[نّ]َخِيلَ وَ[h:7344[ٱ]لْأَعْنَ[n[ـٰ]بَ وَمِ[f:4136[ن ك]ُلِّ [h:1571[ٱ][l[ل]ثَّمَر[n[َٲ]تِ‌ۗ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:7345[ةً ل]ِّقَوْ[a:6018[مٍ ي]َتَفَكَّر[p[ُو]نَ","У ўша ила сизга экинларни, зайтунни, ҳурмоларни, узумларни ва турли меваларни ўстирадир. Албатта, бунда тафаккур қиладиган қавмлар учун оят-белгилар бордир.",268,14],["وَسَخَّرَ لَكُمُ [h:6116[ٱ]لَّيْلَ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ وَ[h:4264[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ‌ۖ وَ[h:7346[ٱ][l[ل][g[نّ]ُجُومُ مُسَخَّر[n[َٲ][i:7347[تُۢ ب]ِأَمْرِه[o[ِۦٓ‌ۗ] إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:850[مٍ ي]َعْقِل[p[ُو]نَ","У сизга кечанию кундузни, қуёшнию ойни хизматкор қилди. Юлдузлар Унинг амри ила хизматкордир. Албатта, бунда ақл юритгувчи қавмлар учун оят-белгилар бордир.",268,14],["وَمَا ذَرَأَ لَكُمْ فِى [h:44[ٱ]لْأَرْضِ مُخْتَلِفًا أَلْو[n[َٲ]نُهُ[o[ۥٓ‌ۗ] إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:7345[ةً ل]ِّقَوْ[a:4403[مٍ ي]َذَّكَّر[p[ُو]نَ","Ва сиз учун ерда турли рангда қилиб яратган нарсаларини ҳам. Албатта, бунда эслайдиган қавмлар учун оят-белги бордир.",268,14],["وَهُوَ [h:4114[ٱ]لَّذِى سَخَّرَ [h:7348[ٱ]لْبَحْرَ لِتَأْكُلُو[s[اْ] مِنْهُ لَحْ[f:7349[مًا ط]َرِي[a:7350[ًّا و]َتَسْتَخْرِجُو[s[اْ] مِنْهُ حِلْيَ[f:7351[ةً ت]َلْبَسُونَهَا وَتَرَى [h:7352[ٱ]لْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَ[q:7353[بْ]تَغُو[s[اْ] مِ[f:475[ن ف]َضْلِه[n[ِۦ] وَلَعَلَّكُمْ تَشْكُر[p[ُو]نَ","У денгизни сиз ундан тоза гўшт ейишингиз, ундан тақадиган тақинчоқлар чиқариб олишингиз учун, унда ёриб кетаётган кемаларни кўрасан, ҳамда унинг фазлини талаб қилишингиз учун хизматкор қилди. Шоядки, шукр келтирсангиз.",268,14],["وَأَلْقَىٰ فِى [h:44[ٱ]لْأَرْضِ رَو[n[َٲ]سِىَ أَ[f:7354[ن ت]َمِيدَ بِكُمْ وَأَنْهَ[n[ـٰ][a:7355[رًا و]َسُبُل[u:7356[اً ل]َّعَلَّكُمْ تَهْتَد[p[ُو]نَ","У зот ер сизларни тебратиб юбормаслиги учун унинг устига баланд тоғларни ташлаб қўйди. Анҳорлару йўлларни ҳам. Шоядки, тўғри йўл топсангиз.",269,14],["وَعَلَ[n[ـٰ]مَ[n[ـٰ][a:7357[تٍ‌ۚ و]َبِ[h:7358[ٱ][l[ل][g[نّ]َ[q:7358[جْ]مِ هُمْ يَهْتَد[p[ُو]نَ","Ва аломатлар ҳамда юлдузлар ила улар йўл топурлар.",269,14],["أَفَم[a:7359[َن ي]َخْلُقُ كَم[u:7360[َن ل]َّا يَخْلُقُ‌ۗ أَفَلَا تَذَكَّر[p[ُو]نَ","Яратадиган зот яратмайдиган зот каби бўлурми? Ўйлаб кўрмайсизларми?",269,14],["وَإِ[f:7136[ن ت]َعُدُّو[s[اْ] نِعْمَةَ [h:1154[ٱ]للَّهِ لَا تُحْصُوه[o[َآ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَغَفُو[u:4578[رٌ ر]َّح[p[ِي]مٌ","Агар Аллоҳнинг неъматларини санасангизлар, саноғига ета олмайсизлар. Албатта, Аллоҳ ўта мағфиратли ва раҳмли зотдир.",269,14],["وَ[h:9999[ٱ]للَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِن[p[ُو]نَ","Аллоҳ нимани сир тутаётганингизни ва нимани ошкор қилаётганингизни биладир.",269,14],["وَ[h:9999[ٱ]لَّذِينَ يَ[q:1240[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ لَا يَخْلُقُونَ شَيْـ[a:5188[ـًٔا و]َهُمْ يُخْلَق[p[ُو]نَ","Уларнинг Аллоҳдан ўзга ибодат қилаётганлари ҳеч нарсани ярата олмаслар. Ҳолбуки, ўзлари яратиладилар.",269,14],["أَمْو[n[َٲ]تٌ غَيْرُ أَحْي[o[َا]ٓ[a:7361[ءٍ‌ۖ و]َمَا يَشْعُرُونَ أَيَّانَ يُ[q:4606[بْ]عَث[p[ُو]نَ","Ўликлардир, тирик эмаслар ва қачон қайта тирилтирилишларини билмаслар.",269,14],["إِلَ[n[ـٰ]هُكُمْ إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[f:7362[دٌ‌ۚ ف]َ[h:2514[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ قُلُوبُه[w:7363[ُم م]ُّ[f:7364[نك]ِرَ[a:7365[ةٌ و]َه[w:7366[ُم م]ُّسْتَكْبِر[p[ُو]نَ","Илоҳингиз ягона илоҳдир. Охиратга иймон келтирмайдиганларнинг қалблари инкор қилувчидир, ўзлари эса мутакаббирдирлар.",269,14],["لَا جَرَمَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ‌ۚ إِ[g[نّ]َهُ[n[ۥ] لَا يُحِبُّ [h:7367[ٱ]لْمُسْتَكْبِر[p[ِي]نَ","Шубҳасизки, Аллоҳ нимани сир тутаётганларини ва нимани ошкор қилаётганларини биладир. Албатта, У мутакаббирларни хуш кўрмас.",269,14],["وَإِذَا قِيلَ لَه[w:7368[ُم م]َّاذ[o[َآ] أَ[f:471[نز]َلَ رَبُّكُمْ‌ۙ قَال[o[ُوٓ][s[اْ] أَسَ[n[ـٰ]طِيرُ [h:3993[ٱ]لْأَوَّل[p[ِي]نَ","Қачонки, уларга: «Роббингиз нимани нозил қилди?» дейилса, улар: «Аввалгиларнинг афсоналарини», дерлар.",269,14],["لِيَحْمِل[o[ُوٓ][s[اْ] أَوْزَارَهُمْ كَامِلَ[a:7369[ةً ي]َوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۙ وَمِنْ أَوْزَارِ [h:7370[ٱ]لَّذِينَ يُضِلُّونَه[c:7371[ُم ب]ِغَيْرِ عِلْمٍ‌ۗ أَلَا س[o[َا]ٓءَ مَا يَزِر[p[ُو]نَ","Қиёмат куни ўз гуноҳларини тўлалигича ва жаҳолат ила йўлдан адаштирган кишиларнинг гуноҳларидан кўтаришлари учундир. Огоҳ бўлинг! Улар кўтарган нарса қандоқ ҳам ёмон!",269,14],["قَ[q:298[دْ] مَكَرَ [h:7027[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ فَأَتَى [h:7372[ٱ]للَّهُ بُنْيَ[n[ـٰ]نَه[w:7373[ُم م]ِّنَ [h:7374[ٱ]لْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ [h:7375[ٱ][l[ل]سَّ[q:7376[قْ]فُ مِ[f:3683[ن ف]َوْقِهِمْ وَأَتَ[n[ـٰ]هُمُ [h:7377[ٱ]لْعَذَابُ مِنْ حَيْثُ لَا يَشْعُر[p[ُو]نَ","Батаҳқиқ, улардан олдингилар ҳам макр қилганлар. Бас, Аллоҳ биноларини пойдеворидан йиқитди. Шифт уларнинг устига қулаб тушди. Ва уларга ўзлари сезмаган томондан азоб келди.",269,14],["ثُ[g[مّ]َ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَك[o[َا]ٓءِىَ [h:7378[ٱ]لَّذِينَ كُ[f:100[نت]ُمْ تُشَ[m[ـٰٓ]قُّونَ فِيهِمْ‌ۚ قَالَ [h:590[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:7379[ٱ]لْعِلْمَ إِ[g[نّ]َ [h:7380[ٱ]لْخِزْىَ [h:7381[ٱ]لْيَوْمَ وَ[h:7382[ٱ][l[ل]سّ[o[ُو]ٓءَ عَلَى [h:468[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Сўнгра қиёмат кунида У зот уларни хор қиладир ва: «Сизлар улар ҳақида тортишиб юрган Менинг «шерикларим» қани?» дер. Илм берилганлар: «Бугунги кунда хорлик ва ёмонлик кофирларгадир», дерлар.",270,14],["ٱلَّذِينَ تَتَوَفَّ[n[ـٰ]هُمُ [h:7383[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ ظَالِم[o[ِىٓ] أَ[f:568[نف]ُسِهِمْ‌ۖ فَأَلْقَوُ[s[اْ] [h:7384[ٱ][l[ل]سَّلَمَ مَا كُ[g[نّ]َا نَعْمَلُ مِ[f:1847[ن س][o[ُو]ٓ[i:7385[ءِۭ‌ۚ ب]َلَ[o[ىٰٓ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلِي[i:6056[مُۢ ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Фаришталар уларнинг жонларини ўзларига зулм қилган ҳолларида олгандир. Улар, ҳеч бир ёмонлик қилмаган эдик, дея таслим бўлурлар. Йўқ! Албатта, Аллоҳ нима амал қилиб юрганингизни билгувчи зотдир.",270,14],["فَ[h:9999[ٱ][q:7386[دْ]خُل[o[ُوٓ][s[اْ] أَ[q:4047[بْ]و[n[َٲ]بَ جَهَ[g[نّ]َمَ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۖ فَلَبِئْسَ مَثْوَى [h:7387[ٱ]لْمُتَكَبِّر[p[ِي]نَ","Бас, жаҳаннам эшикларидан, унда абадий қолгувчи бўлган ҳолингизда киринг! Бас, мутакаббирларнинг қайтар жойи қандоқ ҳам ёмон!",270,14],["۞ وَقِيلَ لِلَّذِينَ [h:1785[ٱ]تَّقَوْ[s[اْ] مَاذ[o[َآ] أَ[f:471[نز]َلَ رَبُّكُمْ‌ۚ قَالُو[s[اْ] خَيْ[u:7388[رًا‌ۗ ل]ِّلَّذِينَ أَحْسَنُو[s[اْ] فِى هَ[n[ـٰ]ذِهِ [h:5052[ٱ][l[ل]دُّنْيَا حَسَنَ[a:7389[ةٌ‌ۚ و]َلَدَارُ [h:6855[ٱ]لْأَخِرَةِ خَيْ[a:7390[رٌ‌ۚ و]َلَنِعْمَ دَارُ [h:7391[ٱ]لْمُتَّق[p[ِي]نَ","Ва тақво қилганларга: «Роббингиз нимани нозил қилди?» дейилди. Улар: «Яхшиликни», дедилар. Чиройли амаллар қилганлар учун бу дунёда чиройли бордир. Албатта, охират диёри яхшироқдир. Роббиларининг диёри нақадар яхшидир.",270,14],["جَ[g[نّ]َ[n[ـٰ]تُ عَ[q:5720[دْ][a:6962[نٍ ي]َ[q:6963[دْ]خُلُونَهَا تَ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۖ لَهُمْ فِيهَا مَا يَش[o[َا]ٓءُونَ‌ۚ كَذ[n[َٲ]لِكَ يَ[q:6806[جْ]زِى [h:7392[ٱ]للَّهُ [h:7393[ٱ]لْمُتَّق[p[ِي]نَ","У адн жаннатидир. Унга кирганларида остидан анҳорлар оқиб турар, улар учун у ерда истаган нарсалари бор. Аллоҳ тақводорларни ана шундай мукофотлар.",270,14],["ٱلَّذِينَ تَتَوَفَّ[n[ـٰ]هُمُ [h:7383[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ طَيِّبِينَ‌ۙ يَقُولُونَ سَلَ[n[ـٰ]مٌ عَلَيْكُمُ [h:7394[ٱ][q:278[دْ]خُلُو[s[اْ] [h:4726[ٱ]لْجَ[g[نّ]َةَ بِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Фаришталар уларнинг жонларини пок ҳолларида ола туриб: «Сизларга салом бўлсин. Қилиб юрган ишларингиз туфайли жаннатга киринг», дерлар.",270,14],["هَلْ يَ[f:1141[نظ]ُرُونَ إِلّ[o[َآ] أَ[f:4552[ن ت]َأْتِيَهُمُ [h:4553[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ أَوْ يَأْتِىَ أَمْرُ رَبِّكَ‌ۚ كَذ[n[َٲ]لِكَ فَعَلَ [h:7395[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ وَمَا ظَلَمَهُمُ [h:2189[ٱ]للَّهُ وَلَ[n[ـٰ]كِ[f:276[ن ك]َان[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ يَظْلِم[p[ُو]نَ","Улар ўзларига фаришталарини ёки Роббингнинг амри келишига интизор бўлиб турибдиларми? Улардан олдингилар ҳам шундай қилган эдилар. Аллоҳ уларга зулм қилмади. Лекин улар ўзларига зулм қилган эдилар.",270,14],["فَأَصَابَهُمْ سَيِّـَٔـاتُ مَا عَمِلُو[s[اْ] وَحَاقَ بِه[w:6252[ِم م]َّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Бас, қилган ёмон амаллари ўзларига етди ва истеҳзо қилган нарсалари ўзларини ўради.",270,14],["وَقَالَ [h:614[ٱ]لَّذِينَ أَشْرَكُو[s[اْ] لَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ مَا عَبَ[q:7396[دْ]نَا مِ[f:3136[ن د]ُونِه[n[ِۦ] مِ[f:2103[ن ش][a:7397[َىْءٍ ن]َّحْنُ وَل[o[َآ] ءَاب[o[َا]ٓؤُنَا وَلَا حَرَّمْنَا مِ[f:3136[ن د]ُونِه[n[ِۦ] مِ[f:2103[ن ش][f:4506[َىْءٍ‌ۚ ك]َذ[n[َٲ]لِكَ فَعَلَ [h:7395[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ فَهَلْ عَلَى [h:7398[ٱ][l[ل]رُّسُلِ إِلَّا [h:3819[ٱ]لْبَلَ[n[ـٰ]غُ [h:3781[ٱ]لْمُب[p[ِي]نُ","Ширк келтирганлар: «Агар Аллоҳ хоҳлаганида, биз ҳам, ота-боболаримиз ҳам Ундан ўзга ҳеч нарсага ибодат қилмас эдик ҳамда Унинг ҳукмисиз бирон нарсани ҳаром қилмаган бўлар эдик», дедилар. Улардан олдингилар ҳам шундай қилганлар. Пайғамбарлар зиммасида фақат очиқ-ойдин етказиш бор, холос.",271,14],["وَلَقَ[q:341[دْ] بَعَثْنَا فِى كُلِّ أُ[g[مّ]َ[u:7399[ةٍ ر]َّسُولاً أَنِ [h:3899[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ وَ[h:7400[ٱ][q:7400[جْ]تَنِبُو[s[اْ] [h:7401[ٱ][l[ل]طَّ[n[ـٰ]غُوتَ‌ۖ فَمِنْه[w:1456[ُم م]َّنْ هَدَى [h:741[ٱ]للَّهُ وَمِنْه[w:1106[ُم م]َّنْ حَقَّتْ عَلَيْهِ [h:7402[ٱ][l[ل]ضَّلَ[n[ـٰ]لَةُ‌ۚ فَسِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَ[h:2257[ٱ][f:2257[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:2258[ٱ]لْمُكَذِّب[p[ِي]نَ","Батаҳқиқ, Биз ҳар бир умматга: «Аллоҳга ибодат қилинг ва тоғутдан четланинг», деб Пайғамбар юборганмиз. Бас, улардан баъзиларини Аллоҳ ҳидоят қилди. Баъзиларига эса, залолат ҳақ бўлди. Бас, ер юзида сайр қилиб юриб ёлғонга чақирувчиларнинг оқибати қандай бўлганига назар солинг.",271,14],["إِ[f:7403[ن ت]َحْرِصْ عَلَىٰ هُدَ[n[ٮٰ]هُمْ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ لَا يَهْدِى م[a:7404[َن ي]ُضِلُّ‌ۖ وَمَا لَه[w:1812[ُم م]ّ[a:1813[ِن ن]َّ[n[ـٰ]صِر[p[ِي]نَ","Агар сен уларнинг ҳидоятига ўта қизиқсанг ҳам, Аллоҳ залолатга кетказган кимсаларни ҳидоят қилмас. Уларга нусрат бергувчилардан бўлмас.",271,14],["وَأَ[q:4324[قْ]سَمُو[s[اْ] بِ[h:32[ٱ]للَّهِ جَهْدَ أَيْمَ[n[ـٰ]نِهِمْ‌ۙ لَا يَ[q:7405[بْ]عَثُ [h:7406[ٱ]للَّهُ م[a:7407[َن ي]َمُوتُ‌ۚ بَلَىٰ وَعْدًا عَلَيْهِ حَق[a:7408[ًّا و]َلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Улар жон-жаҳдлари билан: «Аллоҳ ўлганларни қайта тирилтирмас», деб Аллоҳ номи ила қасам ичдилар. Йўқ! Бу, У зотнинг зиммасидаги ҳақ ваъдадир. Лекин одамларнинг кўплари билмаслар.",271,14],["لِيُبَيِّنَ لَهُمُ [h:7409[ٱ]لَّذِى يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ [h:2400[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أَ[g[نّ]َهُمْ كَانُو[s[اْ] كَ[n[ـٰ]ذِب[p[ِي]نَ","Уларга ихтилоф қилиб юрган нарсаларини баён қилиб бериш учун, куфр келтирганлар ўзларининг шубҳасиз ёлғончи эканларини билишлари учун.",271,14],["إِ[g[نّ]َمَا قَوْلُنَا لِشَىْءٍ إِذ[o[َآ] أَرَ[q:7410[دْ]نَ[n[ـٰ]هُ أ[a:7411[َن ن]َّقُولَ لَهُ[n[ۥ] كُ[f:613[ن ف]َيَك[p[ُو]نُ","Агар Биз бир нарсанинг бўлишини ирода қилсак, унга «бўл» демоғимиз кифоя. Бас, ўша нарса бўладир.",271,14],["وَ[h:9999[ٱ]لَّذِينَ هَاجَرُو[s[اْ] فِى [h:714[ٱ]للَّهِ م[i:146[ِنۢ ب]َعْدِ مَا ظُلِمُو[s[اْ] لَنُبَوِّئَ[g[نّ]َهُمْ فِى [h:599[ٱ][l[ل]دُّنْيَا حَسَنَ[a:7412[ةً‌ۖ و]َلَأَ[q:6719[جْ]رُ [h:6720[ٱ]لْأَخِرَةِ أَكْبَرُ‌ۚ لَوْ كَانُو[s[اْ] يَعْلَم[p[ُو]نَ","Зулмга дучор бўлганларидан сўнг Аллоҳнинг йўлида ҳижрат қилганларни бу дунёда, албатта, гўзал жойлаштирурмиз. Ва охират ажри каттароқдир, агар биладиган бўлсалар.",271,14],["ٱلَّذِينَ صَبَرُو[s[اْ] وَعَلَىٰ رَبِّهِمْ يَتَوَكَّل[p[ُو]نَ","Улар сабр қилган ва Роббиларига таваккал қилганлардир.",271,14],["وَم[o[َآ] أَرْسَلْنَا مِ[f:18[ن ق]َ[q:19[بْ]لِكَ إِلَّا رِجَال[a:6851[اً ن]ُّوح[o[ِىٓ] إِلَيْهِمْ‌ۚ فَسْــَٔل[o[ُوٓ][s[اْ] أَهْلَ [h:7413[ٱ][l[ل]ذِّكْرِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ لَا تَعْلَم[p[ُو]نَ","Биз сендан олдин ҳам фақат эр кишиларни юбориб, уларга ваҳий қилганмиз. Агар билмайдиган бўлсангиз, зикр аҳлларидан сўрангиз.",272,14],["بِ[h:9999[ٱ]لْبَيِّنَ[n[ـٰ]تِ وَ[h:2474[ٱ][l[ل]زُّبُرِ‌ۗ وَأَ[f:271[نز]َلْن[o[َآ] إِلَيْكَ [h:7414[ٱ][l[ل]ذِّكْرَ لِتُبَيِّنَ لِل[g[نّ]َاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّر[p[ُو]نَ","Очиқ-ойдин баёнотлар ва китоблар ила. Ва сенга одамларга нозил қилинган нарсани ўзларига баён қилиб беришинг учун зикрни нозил қилдик. Шоядки, тафаккур қилсалар.",272,14],["أَفَأَمِنَ [h:7415[ٱ]لَّذِينَ مَكَرُو[s[اْ] [h:7416[ٱ][l[ل]سَّيِّـَٔـاتِ أ[a:7417[َن ي]َخْسِفَ [h:7418[ٱ]للَّهُ بِهِمُ [h:7419[ٱ]لْأَرْضَ أَوْ يَأْتِيَهُمُ [h:7420[ٱ]لْعَذَابُ مِنْ حَيْثُ لَا يَشْعُر[p[ُو]نَ","Макр ила ёмонликлар қилганлар, Аллоҳ уларни ерга ютқазиб юборишидан ёки уларга кутмаган томонларидан азоб келиб қолишидан хотиржам бўлдиларми?!",272,14],["أَوْ يَأْخُذَهُمْ فِى تَقَلُّبِهِمْ فَمَا ه[c:7421[ُم ب]ِمُعْجِز[p[ِي]نَ","Ёхуд уларни ҳаракатлари асносида олишидан, улар У зотни ожиз қолдирувчи бўла олмасликларидан хотиржаммилар?!",272,14],["أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّ[f:7422[فٍ ف]َإِ[g[نّ]َ رَبَّكُمْ لَرَءُو[u:744[فٌ ر]َّح[p[ِي]مٌ","Ёки У зот уларни хавфсираб турган ҳолларида ҳам олишидан. Албатта, Роббингиз меҳрибон ва раҳмлидир.",272,14],["أَوَلَمْ يَرَوْ[s[اْ] إِلَىٰ مَا خَلَقَ [h:1272[ٱ]للَّهُ مِ[f:2103[ن ش][a:7423[َىْءٍ ي]َتَفَيَّؤُ[s[اْ] ظِلَ[n[ـٰ]لُهُ[n[ۥ] عَنِ [h:7424[ٱ]لْيَمِينِ وَ[h:7425[ٱ][l[ل]شَّم[o[َا]ٓئِلِ سُجَّ[u:7426[دًا ل]ِّلَّهِ وَهُمْ د[n[َٲ]خِر[p[ُو]نَ","Ахир улар Аллоҳ яратган ҳар бир нарсанинг соялари ўнгга, чапга мойил бўлиб, Аллоҳга сажда қилиб ётганини ва улар бўйсунувчи эканини кўрмайдиларми?!",272,14],["وَلِلَّهِ يَسْجُدُ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ مِ[f:4026[ن د][m[َا]ٓبَّ[a:7427[ةٍ و]َ[h:1146[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ وَهُمْ لَا يَسْتَكْبِر[p[ُو]نَ","Осмонлару ердаги барча жонзотлар ва фаришталар фақат Аллоҳга сажда қилурлар. Улар мутакаббирлик қилмаслар.",272,14],["يَخَافُونَ رَبَّه[w:7428[ُم م]ِّ[f:3683[ن ف]َوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُ[p[و]نَ ۩","Улар устиларидаги Роббиларидан қўрқурлар ва ўзларига амр қилинган нарсаларни қилурлар.",272,14],["۞ وَقَالَ [h:3421[ٱ]للَّهُ لَا تَتَّخِذ[o[ُوٓ][s[اْ] إِلَ[n[ـٰ]هَيْنِ [h:7429[ٱ]ثْنَيْنِ‌ۖ إِ[g[نّ]َمَا هُوَ إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[f:7430[دٌ‌ۖ ف]َإِيَّ[n[ـٰ]ىَ فَ[h:204[ٱ]رْهَب[p[ُو]نِ","Аллоҳ: «Иккита илоҳ тутмангиз. Ҳақиқатда, У ёлғиз илоҳдир. Бас, Мендангина қўрқингиз», деди.",272,14],["وَلَهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَلَهُ [h:7431[ٱ][l[ل]دِّينُ وَاصِبًا‌ۚ أَفَغَيْرَ [h:4347[ٱ]للَّهِ تَتَّق[p[ُو]نَ","Осмонлару ердаги нарсалар Уникидир. Дин ҳам бардавом Уникидир. Аллоҳдан ўзгадан қўрқасизларми?",272,14],["وَمَا بِك[w:7432[ُم م]ّ[a:7433[ِن ن]ِّعْمَ[f:7434[ةٍ ف]َمِنَ [h:2957[ٱ]للَّهِ‌ۖ ثُ[g[مّ]َ إِذَا مَسَّكُمُ [h:7435[ٱ][l[ل]ضُّرُّ فَإِلَيْهِ تَ[q:7436[جْ]ــَٔر[p[ُو]نَ","Сизда қайсики неъмат бўлса, Аллоҳдандир. Сўнгра қачонки сизга ёмонлик етса, Унгагина ёлборурсиз.",272,14],["ثُ[g[مّ]َ إِذَا كَشَفَ [h:7437[ٱ][l[ل]ضُّرَّ عَ[f:255[نك]ُمْ إِذَا فَرِي[a:7438[قٌ م]ِّ[f:344[نك][c:7439[ُم ب]ِرَبِّهِمْ يُشْرِك[p[ُو]نَ","Сўнгра У сиздан ёмонликни кушойиш қилган чоғда, кўрибсизки, сиздан бир гуруҳ ўз Роббларига ширк келтирурлар.",272,14],["لِيَكْفُرُو[s[اْ] بِم[o[َآ] ءَاتَيْنَ[n[ـٰ]هُمْ‌ۚ فَتَمَتَّعُو[s[اْ‌ۖ] فَسَوْفَ تَعْلَم[p[ُو]نَ","Уларга берган нарсаларимизга куфр келтирурлар. Бас, ҳузурланиб туринглар, тезда билурсиз.",273,14],["وَيَ[q:7440[جْ]عَلُونَ لِمَا لَا يَعْلَمُونَ نَصِي[a:7441[بًا م]ِّ[g[مّ]َا رَزَ[q:15[قْ]نَ[n[ـٰ]هُمْ‌ۗ تَ[h:6760[ٱ]للَّهِ لَتُسْــَٔلُ[g[نّ]َ عَ[g[مّ]َا كُ[f:100[نت]ُمْ تَفْتَر[p[ُو]نَ","Ва улар ўзлари билмаган нарсага Биз уларга берган ризқдан насиба ажратурлар. Аллоҳга қасамки, ўзингиз уйдирган ёлғон нарса ҳақида, албатта, сўралурсиз.",273,14],["وَيَ[q:7440[جْ]عَلُونَ لِلَّهِ [h:7442[ٱ]لْبَنَ[n[ـٰ]تِ سُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ]‌ۙ وَلَه[w:7443[ُم م]َّا يَشْتَه[p[ُو]نَ","Улар қизларни Аллоҳники қилишадир. У покдир. Уларга эса, кўнгиллари тусагани.",273,14],["وَإِذَا بُشِّرَ أَحَدُه[c:7444[ُم ب]ِ[h:930[ٱ]لْأُ[f:930[نث]َىٰ ظَلَّ وَ[q:7445[جْ]هُهُ[n[ۥ] مُسْوَد[a:7446[ًّا و]َهُوَ كَظ[p[ِي]مٌ","Қачонки улардан бирига қизнинг хушхабари берилса, ғам-аламга тўлиб, юзи қорайиб кетур.",273,14],["يَتَو[n[َٲ]رَىٰ مِنَ [h:4196[ٱ]لْقَوْمِ مِ[f:7447[ن س][o[ُو]ٓءِ مَا بُشِّرَ بِه[o[ِۦٓ‌ۚ] أَيُمْسِكُهُ[n[ۥ] عَلَىٰ هُونٍ أَمْ يَدُسُّهُ[n[ۥ] فِى [h:7448[ٱ][l[ل]تُّرَابِ‌ۗ أَلَا س[o[َا]ٓءَ مَا يَحْكُم[p[ُو]نَ","Унга берилган хушхабарнинг ёмонлигидан қавмидан беркинадир. Уни хорлик-ла олиб қолсамикин ёки тупроққа кўмсамикин? Огоҳ бўлинг! Улар қилган ҳукм нақадар ёмон.",273,14],["لِلَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ مَثَلُ [h:7449[ٱ][l[ل]سَّوْءِ‌ۖ وَلِلَّهِ [h:7450[ٱ]لْمَثَلُ [h:7451[ٱ]لْأَعْلَىٰ‌ۚ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Охиратга иймон келтирмайдиганларнинг мисоли ёмон мисолдир. Аъло мисол Аллоҳникидир. У азиз ва ҳакимдир.",273,14],["وَلَوْ يُؤَاخِذُ [h:7452[ٱ]للَّهُ [h:7453[ٱ][l[ل][g[نّ]َاسَ بِظُلْمِه[w:7454[ِم م]َّا تَرَكَ عَلَيْهَا مِ[f:4026[ن د][m[َا]ٓبَّ[a:7455[ةٍ و]َلَ[n[ـٰ]ك[a:7456[ِن ي]ُؤَخِّرُهُمْ إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَم[f:7457[ًّى‌ۖ ف]َإِذَا ج[o[َا]ٓءَ أَجَلُهُمْ لَا يَسْتَــْٔخِرُونَ سَاعَ[a:4666[ةً‌ۖ و]َلَا يَسْتَ[q:4667[قْ]دِم[p[ُو]نَ","Агар Аллоҳ одамларни қилган зулмларига биноан тутганида, ер юзида битта ҳам жонзотни қўймас эди. Лекин уларни белгиланган ажалига қўйиб қўюр. Қачонки, ажаллари келса уни бир соат орқага ҳам, олдинга ҳам сура олмаслар.",273,14],["وَيَ[q:7440[جْ]عَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ [h:7458[ٱ]لْكَذِبَ أَ[g[نّ]َ لَهُمُ [h:7459[ٱ]لْحُسْنَىٰ‌ۖ لَا جَرَمَ أَ[g[نّ]َ لَهُمُ [h:7460[ٱ][l[ل][g[نّ]َارَ وَأَ[g[نّ]َه[w:7461[ُم م]ُّفْرَط[p[ُو]نَ","Улар ўзлари ёқтирмаган нарсани Аллоҳники қилурлар. Уларнинг тиллари эса, ёлғондан ўзларига гўзал бўлишини васф қиладир. Ҳеч шубҳа йўқки, уларга, албатта, дўзах бўлур ва, албатта, улар пешқадамларидир.",273,14],["تَ[h:9999[ٱ]للَّهِ لَقَ[q:2389[دْ] أَرْسَلْن[o[َآ] إِلَ[o[ىٰٓ] أُمَ[a:4041[مٍ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ فَزَيَّنَ لَهُمُ [h:4046[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ أَعْمَ[n[ـٰ]لَهُمْ فَهُوَ وَلِيُّهُمُ [h:7462[ٱ]لْيَوْمَ وَلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Аллоҳга қасамки, Биз сендан олдинги умматларга ҳам юборганмиз. Бас, шайтон уларга амалларини зийнатлаб кўрсатди. У бугун уларнинг дўстидир. Уларга аламли азоб бўлур.",273,14],["وَم[o[َآ] أَ[f:515[نز]َلْنَا عَلَيْكَ [h:1723[ٱ]لْكِتَ[n[ـٰ]بَ إِلَّا لِتُبَيِّنَ لَهُمُ [h:7409[ٱ]لَّذِى [h:7463[ٱ]خْتَلَفُو[s[اْ] فِيهِ‌ۙ وَهُ[a:4537[دًى و]َرَحْمَ[u:4735[ةً ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Биз сенга китобни фақат уларга ўзлари ихтилоф қилган нарсаларни баён қилишинг учун, иймон келтирадиган қавмларга ҳидоят ва раҳмат этиб нозил этдик, холос.",273,14],["وَ[h:9999[ٱ]للَّهُ أَ[f:471[نز]َلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:7464[ءً ف]َأَحْيَا بِهِ [h:842[ٱ]لْأَرْضَ بَعْدَ مَوْتِه[o[َآ‌ۚ] إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:7345[ةً ل]ِّقَوْ[a:6119[مٍ ي]َسْمَع[p[ُو]نَ","Аллоҳ осмондан сув тушириб, у ила ерни ўлимидан кейин тирилтирди. Албатта, бунда эшитадиган қавмлар учун оят-белгилар бордир.",274,14],["وَإِ[g[نّ]َ لَكُمْ فِى [h:7465[ٱ]لْأَنْعَ[n[ـٰ]مِ لَعِ[q:1764[بْ]رَ[a:7466[ةً‌ۖ ن]ُّسْقِيك[w:7467[ُم م]ِّ[g[مّ]َا فِى بُطُونِه[n[ِۦ] م[i:4612[ِنۢ ب]َيْنِ فَرْ[a:7468[ثٍ و]َدَ[u:7469[مٍ ل]َّبَنًا خَالِ[f:7470[صًا س][o[َا]ٓئِ[u:7471[غًا ل]ِّلشَّ[n[ـٰ]رِب[p[ِي]نَ","Чорва ҳайвонларида ҳам сиз учун, албатта, ибрат бордир. Биз сизларни уларнинг қорнидан, гўнг ва қон орасидан ичувчилар дан осон ўтувчи соф сут ила суғорамиз.",274,14],["وَمِ[f:7472[ن ث]َمَر[n[َٲ]تِ [h:7473[ٱ][l[ل][g[نّ]َخِيلِ وَ[h:7474[ٱ]لْأَعْنَ[n[ـٰ]بِ تَتَّخِذُونَ مِنْهُ سَكَ[a:7475[رًا و]َرِزْقًا حَسَنًا‌ۗ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:7345[ةً ل]ِّقَوْ[a:850[مٍ ي]َعْقِل[p[ُو]نَ","Ва хурмо ва узумларнинг меваларидан маст қилувчи нарса ва гўзал ризқ олурсиз. Албатта, бунда ақл юритгувчилар учун оят-белги бордир.",274,14],["وَأَوْحَىٰ رَبُّكَ إِلَى [h:7476[ٱ][l[ل][g[نّ]َحْلِ أَنِ [h:7477[ٱ]تَّخِذِى مِنَ [h:7297[ٱ]لْجِبَالِ بُيُو[a:7478[تًا و]َمِنَ [h:7479[ٱ][l[ل]شَّجَرِ وَمِ[g[مّ]َا يَعْرِش[p[ُو]نَ","Роббинг асаларига: «Тоғлардан, дарахтлардан ва кўтарилган сўритоклардан уй тутгин.",274,14],["ثُ[g[مّ]َ كُلِى مِ[f:843[ن ك]ُلِّ [h:1571[ٱ][l[ل]ثَّمَر[n[َٲ]تِ فَ[h:7480[ٱ]سْلُكِى سُبُلَ رَبِّكِ ذُلُل[a:7481[اً‌ۚ ي]َخْرُجُ م[i:7482[ِنۢ ب]ُطُونِهَا شَرَا[a:7483[بٌ م]ُّخْتَلِفٌ أَلْو[n[َٲ]نُهُ[n[ۥ] فِيهِ شِف[o[َا]ٓ[u:7484[ءٌ ل]ِّل[g[نّ]َاسِ‌ۗ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:7345[ةً ل]ِّقَوْ[a:6018[مٍ ي]َتَفَكَّر[p[ُو]نَ","Сўнгра ҳамма мевалардан егин. Бас, Роббинг осон қилиб қўйган йўллардан юргин», деб ваҳий қилди. Уларнинг қоринларидан турли рангдаги шароб чиқар. Унда одамлар учун шифо бордир. Албатта, бунда тафаккур қилувчилар учун оят-белги бордир.",274,14],["وَ[h:9999[ٱ]للَّهُ خَلَقَكُمْ ثُ[g[مّ]َ يَتَوَفَّ[n[ـٰ]كُمْ‌ۚ وَمِ[f:2325[نك][w:2326[ُم م]ّ[a:7485[َن ي]ُرَدُّ إِلَ[o[ىٰٓ] أَرْذَلِ [h:7486[ٱ]لْعُمُرِ لِكَىْ لَا يَعْلَمَ بَعْدَ عِلْ[f:7487[مٍ ش]َيْــًٔا‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلِي[f:7488[مٌ ق]َد[p[ِي]رٌ","Аллоҳ сизларни яратгандир. Сўнгра У сизларни вафот эттирадир. Сизлардан баъзилар билимли бўлгандан сўнг ҳеч нарса билмаслиги учун умрнинг энг заифлигига қайтариладир. Албатта, Аллоҳ билгувчи ва қодирдир.",274,14],["وَ[h:9999[ٱ]للَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْ[f:6882[ضٍ ف]ِى [h:7489[ٱ][l[ل]رِّزْقِ‌ۚ فَمَا [h:7490[ٱ]لَّذِينَ فُضِّلُو[s[اْ] بِر[m[َا]ٓدِّى رِزْقِهِمْ عَلَىٰ مَا مَلَكَتْ أَيْمَ[n[ـٰ]نُهُمْ فَهُمْ فِيهِ سَو[o[َا]ٓءٌ‌ۚ أَفَبِنِعْمَةِ [h:7491[ٱ]للَّهِ يَ[q:4008[جْ]حَد[p[ُو]نَ","Аллоҳ ризқда баъзингизни баъзингиздан афзал қилди. Бас, афзал қилинганлар ўз ризқларини қўлларида мулк бўлганларга, ҳамма тенг бўлсин, деб берувчи эмаслар-ку. Аллоҳнинг неъматини инкор қиладиларми?!",274,14],["وَ[h:9999[ٱ]للَّهُ جَعَلَ لَك[w:556[ُم م]ِّنْ أَ[f:1329[نف]ُسِكُمْ أَزْو[n[َٲ][a:7492[جًا و]َجَعَلَ لَك[w:556[ُم م]ِّنْ أَزْو[n[َٲ]جِك[c:7493[ُم ب]َنِينَ وَحَفَدَ[a:7494[ةً و]َرَزَقَك[w:5306[ُم م]ِّنَ [h:5307[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تِ‌ۚ أَفَبِ[h:7495[ٱ]لْبَ[n[ـٰ]طِلِ يُؤْمِنُونَ وَبِنِعْمَتِ [h:7496[ٱ]للَّهِ هُمْ يَكْفُر[p[ُو]نَ","Аллоҳ сизларга ўзларингиздан жуфлар қилди ва сизларга жуфтларингиздан болалар ва набиралар қилди ҳамда сизларга пок ризқларни берди. Ботилга иймон келтирадилар-у, Аллоҳнинг неъматига куфр келтирадиларми?!",274,14],["وَيَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْ[a:7497[قًا م]ِّنَ [h:7498[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ شَيْـ[a:232[ـًٔا و]َلَا يَسْتَطِيع[p[ُو]نَ","Ва Аллоҳдан ўзга уларга осмонлару ердан ҳеч бир ризққа молик бўла олмайдиган ва ҳеч нарсага қодир бўла олмайдиган нарсаларга ибодат қиладиларми?",275,14],["فَلَا تَضْرِبُو[s[اْ] لِلَّهِ [h:7499[ٱ]لْأَمْثَالَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَعْلَمُ وَأَ[f:98[نت]ُمْ لَا تَعْلَم[p[ُو]نَ","Аллоҳга зарбул масал келтирманглар! Албатта, Аллоҳ биладир. Сизлар эса, билмайсизлар.",275,14],["۞ ضَرَبَ [h:7103[ٱ]للَّهُ مَثَلاً عَ[q:3317[بْ][a:7500[دًا م]َّمْلُو[u:7501[كًا ل]َّا يَ[q:7502[قْ]دِرُ عَلَىٰ ش[a:7503[َىْءٍ و]َم[u:7504[َن ر]َّزَ[q:7505[قْ]نَ[n[ـٰ]هُ مِ[g[نّ]َا رِزْقًا حَسَ[f:7506[نًا ف]َهُوَ يُ[f:1550[نف]ِقُ مِنْهُ سِر[a:7507[ًّا و]َجَهْرًا‌ۖ هَلْ يَسْتَوُ[n[ۥ]نَ‌ۚ [h:7508[ٱ]لْحَمْدُ لِلَّهِ‌ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَم[p[ُو]نَ","Аллоҳ ҳеч нарсага қодир бўлмайдиган мамлук-қул билан Биз уни яхши ризқ ила ризқлантирган ва ўшандан махфий ва ошкоро инфоқ қиладиган кимсани зарбул масал қиладир. Улар тенг бўладиларми? Ҳамду сано Аллоҳгадир. Лекин кўплари билмаслар.",275,14],["وَضَرَبَ [h:7509[ٱ]للَّهُ مَثَل[u:7510[اً ر]َّجُلَيْنِ أَحَدُهُم[o[َآ] أَ[q:7511[بْ]كَمُ لَا يَ[q:7502[قْ]دِرُ عَلَىٰ ش[a:4300[َىْءٍ و]َهُوَ كَلٌّ عَلَىٰ مَوْلَ[n[ـٰ]هُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ‌ۖ هَلْ يَسْتَوِى هُوَ وَم[a:7512[َن ي]َأْمُرُ بِ[h:1661[ٱ]لْعَ[q:1661[دْ]لِ‌ۙ وَهُوَ عَلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Аллоҳ икки кишини зарбул масал келтирди. Бири соқов, ҳеч нарсага қодир бўлмайдир. У ўз хожасига юкдир. Қаерга юборса ҳам, яхшилик келтирмайдир. Ўша одам билан ўзи тўғри йўлда туриб, бошқаларни адолатга амр қиладиган киши баробар бўларми?",275,14],["وَلِلَّهِ غَيْبُ [h:6538[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَم[o[َآ] أَمْرُ [h:7513[ٱ][l[ل]سَّاعَةِ إِلَّا كَلَمْحِ [h:7514[ٱ]لْبَصَرِ أَوْ هُوَ أَ[q:1355[قْ]رَبُ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Осмонлару ернинг ғайби Аллоҳникидир. Соат иши эса, кўз очиб-юмгандек ёки ундан ҳам яқинроқдир. Албатта, Аллоҳ ҳар бир нарсага қодирдир.",275,14],["وَ[h:9999[ٱ]للَّهُ أَخْرَجَك[w:7515[ُم م]ّ[i:7516[ِنۢ ب]ُطُونِ أُ[g[مّ]َهَ[n[ـٰ]تِكُمْ لَا تَعْلَمُونَ شَيْـ[a:7517[ـًٔا و]َجَعَلَ لَكُمُ [h:7518[ٱ][l[ل]سَّمْعَ وَ[h:6037[ٱ]لْأَ[q:6037[بْ]صَ[n[ـٰ]رَ وَ[h:7519[ٱ]لْأَفْــِٔدَةَ‌ۙ لَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Аллоҳ сизни оналарингиз қорнидан ҳеч нарса билмайдиган ҳолингизда чиқарди. У сизга қулоқ, кўзлар ва дилларни берди. Шоядки, шукр қилсангиз.",275,14],["أَلَمْ يَرَوْ[s[اْ] إِلَى [h:7520[ٱ][l[ل]طَّيْرِ مُسَخَّر[n[َٲ][f:7521[تٍ ف]ِى جَوِّ [h:7522[ٱ][l[ل]سَّم[o[َا]ٓءِ مَا يُمْسِكُهُ[g[نّ]َ إِلَّا [h:1742[ٱ]للَّهُ‌ۗ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Осмон бўшлиғидаги беминнат, бўйсундирилган қушларга қарамайдиларми? Уларни фақатгина Аллоҳ ушлаб туради, холос. Албатта, бунда иймон келтирадиган қавмлар учун оят-белгилар бордир.",275,14],["وَ[h:9999[ٱ]للَّهُ جَعَلَ لَك[w:556[ُم م]ّ[i:7523[ِنۢ ب]ُيُوتِكُمْ سَكَ[a:7524[نًا و]َجَعَلَ لَك[w:556[ُم م]ِّ[f:7525[ن ج]ُلُودِ [h:7526[ٱ]لْأَنْعَ[n[ـٰ]مِ بُيُو[f:7527[تًا ت]َسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ‌ۙ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِه[o[َآ] أَثَ[n[ـٰ][a:7528[ثًا و]َمَتَ[n[ـٰ]عًا إِلَىٰ ح[p[ِي]نٍ","Аллоҳ сизга уйларингизни оромгоҳ қилди. У сизга чорва ҳайвонларининг терисидан кўчадиган ва қўнадиган кунингизда енгил кўтариладиган уйлар қилди. Уларнинг жунлари, юнглари ва қилларидан маълум вақтгача фойда ва мато бўладиган қилди.",276,14],["وَ[h:9999[ٱ]للَّهُ جَعَلَ لَك[w:7529[ُم م]ِّ[g[مّ]َا خَلَقَ ظِلَ[n[ـٰ]ل[a:7530[اً و]َجَعَلَ لَك[w:1578[ُم م]ِّنَ [h:7297[ٱ]لْجِبَالِ أَكْنَ[n[ـٰ][a:7531[نًا و]َجَعَلَ لَكُمْ سَر[n[َٲ]بِيلَ تَقِيكُمُ [h:7532[ٱ]لْحَرَّ وَسَر[n[َٲ]بِيلَ تَقِيك[c:7533[ُم ب]َأْسَكُمْ‌ۚ كَذ[n[َٲ]لِكَ يُتِ[g[مّ]ُ نِعْمَتَهُ[n[ۥ] عَلَيْكُمْ لَعَلَّكُمْ تُسْلِم[p[ُو]نَ","Аллоҳ сизга Ўзи яратган нарсалардан соялар қилиб қўйди ва сизга тоғлардан бошпаналар, сизларни иссиқдан сақлайдиган кийимлар ва зарбадан сақлайдиган кийимлар қилиб қўйди. Шундай қилиб, У сизларга Ўз неъматини батамом қилиб берди. Шоядки, мусулмон бўлсангиз.",276,14],["فَإِ[f:1857[ن ت]َوَلَّوْ[s[اْ] فَإِ[g[نّ]َمَا عَلَيْكَ [h:1808[ٱ]لْبَلَ[n[ـٰ]غُ [h:3781[ٱ]لْمُب[p[ِي]نُ","Агар юз ўгириб кетсалар, бас, сенинг зиммангда очиқ-ойдин етказиб қўйиш, холос.",276,14],["يَعْرِفُونَ نِعْمَتَ [h:1300[ٱ]للَّهِ ثُ[g[مّ]َ يُ[f:7534[نك]ِرُونَهَا وَأَكْثَرُهُمُ [h:7535[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Улар Аллоҳнинг неъматини танирлар, кейин эса, инкор қилурлар. Уларнинг кўплари кофирлардир.",276,14],["وَيَوْمَ نَ[q:7536[بْ]عَثُ مِ[f:843[ن ك]ُلِّ أُ[g[مّ]َ[f:7537[ةٍ ش]َهِي[f:7538[دًا ث]ُ[g[مّ]َ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُو[s[اْ] وَلَا هُمْ يُسْتَعْتَب[p[ُو]نَ","Ҳар бир умматдан гувоҳ келтирган кунимизда, сўнгра куфр келтирганларга изн ҳам берилмас ва улар итобга ҳам қайтарилмаслар.",276,14],["وَإِذَا رَءَا [h:7539[ٱ]لَّذِينَ ظَلَمُو[s[اْ] [h:7540[ٱ]لْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُ[f:826[نظ]َر[p[ُو]نَ","Зулм қилганлар азобни кўрган вақтларида, улардан у енгиллатилмас ва уларга муҳлат ҳам берилмас.",276,14],["وَإِذَا رَءَا [h:7539[ٱ]لَّذِينَ أَشْرَكُو[s[اْ] شُرَك[o[َا]ٓءَهُمْ قَالُو[s[اْ] رَبَّنَا هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ شُرَك[o[َا]ٓؤُنَا [h:7541[ٱ]لَّذِينَ كُ[g[نّ]َا نَ[q:7542[دْ]عُو[s[اْ] مِ[f:7543[ن د]ُونِكَ‌ۖ فَأَلْقَوْ[s[اْ] إِلَيْهِمُ [h:7544[ٱ]لْقَوْلَ إِ[g[نّ]َكُمْ لَكَ[n[ـٰ]ذِب[p[ُو]نَ","Ва ширк келтирганлар ўзларининг «шерик»ларини кўрган чоғларида: «Эй Роббимиз, анавилар бизнинг Сендан ўзга ибодат қилган «шерик»ларимиз», дерлар. Бас, улар буларга: «Албатта, сизлар ёлғончидирсизлар», деб сўз ташларлар.",276,14],["وَأَلْقَوْ[s[اْ] إِلَى [h:1637[ٱ]للَّهِ يَوْمَئِذٍ [h:7545[ٱ][l[ل]سَّلَمَ‌ۖ وَضَلَّ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَفْتَر[p[ُو]نَ","Ўшал кунда улар Аллоҳга таслим бўлурлар ва уйдириб юрган нарсалари ботил бўлур.",276,14],["ٱلَّذِينَ كَفَرُو[s[اْ] وَصَدُّو[s[اْ] عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ زِ[q:7546[دْ]نَ[n[ـٰ]هُمْ عَذَا[f:7547[بًا ف]َوْقَ [h:7548[ٱ]لْعَذَابِ بِمَا كَانُو[s[اْ] يُفْسِد[p[ُو]نَ","Куфр келтирган ва Аллоҳнинг йўлидан тўсганларга фасод қилганлари учун азоб устига азоб зиёда қилдик.",277,14],["وَيَوْمَ نَ[q:7536[بْ]عَثُ فِى كُلِّ أُ[g[مّ]َ[f:7537[ةٍ ش]َهِيدًا عَلَيْه[w:4082[ِم م]ِّنْ أَ[f:568[نف]ُسِهِمْ‌ۖ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ‌ۚ وَنَزَّلْنَا عَلَيْكَ [h:1723[ٱ]لْكِتَ[n[ـٰ]بَ تِ[q:7549[بْ]يَ[n[ـٰ][u:7550[نًا ل]ِّكُلِّ ش[a:4536[َىْءٍ و]َهُ[a:4537[دًى و]َرَحْمَ[a:7551[ةً و]َبُشْرَىٰ لِلْمُسْلِم[p[ِي]نَ","Ҳар бир умматга ўзидан гувоҳ олиб келган кунимизда сени анавиларга гувоҳ қилиб келтирамиз. Сенга китобни ҳар бир нарсани баён қилувчи этиб, мусулмонларга ҳидоят, раҳмат ва хушхабар қилиб нозил этдик.",277,14],["۞ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَأْمُرُ بِ[h:1661[ٱ]لْعَ[q:1661[دْ]لِ وَ[h:7552[ٱ]لْإِحْسَ[n[ـٰ]نِ وَإِيتَآىِٕ ذِى [h:2775[ٱ]لْقُرْبَىٰ وَيَنْهَىٰ عَنِ [h:7553[ٱ]لْفَحْش[o[َا]ٓءِ وَ[h:7554[ٱ]لْمُ[f:7554[نك]َرِ وَ[h:7555[ٱ]لْبَغْىِ‌ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّر[p[ُو]نَ","Албатта, Аллоҳ адолатга, эҳсонга, қариндошларга яхшилик қилишга амр этадир ва фаҳшу мункар ҳамда зулмкорликдан қайтарадир. У сизларга ваъз қилур. Шоядки, эсласангиз.",277,14],["وَأَوْفُو[s[اْ] بِعَهْدِ [h:2038[ٱ]للَّهِ إِذَا عَ[n[ـٰ]هَ[d:5449[د]تُّمْ وَلَا تَ[f:7556[نق]ُضُو[s[اْ] [h:7557[ٱ]لْأَيْمَ[n[ـٰ]نَ بَعْدَ تَوْكِيدِهَا وَقَ[q:387[دْ] جَعَلْتُمُ [h:7558[ٱ]للَّهَ عَلَيْكُمْ كَفِيلاً‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَعْلَمُ مَا تَفْعَل[p[ُو]نَ","Агар аҳдлашсангиз Аллоҳнинг аҳдига вафо қилинг. Қасамларни таъкид қилинганидан сўнг бузманг. Батаҳқиқ, Аллоҳни ўзингизга кафил қилгансиз-а! Албатта, Аллоҳ нима қилаётганингизни билур.",277,14],["وَلَا تَكُونُو[s[اْ] كَ[h:7559[ٱ]لَّتِى نَقَضَتْ غَزْلَهَا م[i:146[ِنۢ ب]َعْدِ قُوَّةٍ أَ[f:7560[نك]َ[n[ـٰ][f:7561[ثًا ت]َتَّخِذُونَ أَيْمَ[n[ـٰ]نَكُمْ دَخَل[i:7562[اَۢ ب]َيْنَكُمْ أَ[f:1566[ن ت]َكُونَ أُ[g[مّ]َةٌ هِىَ أَرْبَىٰ مِنْ أُ[g[مّ]َةٍ‌ۚ إِ[g[نّ]َمَا يَ[q:7563[بْ]لُوكُمُ [h:7564[ٱ]للَّهُ بِه[n[ِۦ]‌ۚ وَلَيُبَيِّنَ[g[نّ]َ لَكُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ مَا كُ[f:100[نت]ُمْ فِيهِ تَخْتَلِف[p[ُو]نَ","Тўқигани кучли бўлгандан сўнг уни сўкиб юборган хотинга ўхшаб, бир уммат бошқа умматдан зиёдроқ бўлгани учун қасамларингизни орангизга алдов воситаси қилиб олманг. Албатта, бу билан сизни Аллоҳ синамоқда, холос. Албатта, У қиёмат куни нима ҳақида ихтилоф қилганингизни баён қилиб берадир.",277,14],["وَلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ لَجَعَلَكُمْ أُ[g[مّ]َ[a:1159[ةً و][n[َٲ]حِدَ[a:3601[ةً و]َلَ[n[ـٰ]ك[a:7565[ِن ي]ُضِلُّ م[a:476[َن ي]َش[o[َا]ٓءُ وَيَهْدِى م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَلَتُسْــَٔلُ[g[نّ]َ عَ[g[مّ]َا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Агар Аллоҳ хоҳласа, сизларни бир уммат қилар эди. Лекин хоҳлаган кимсани залолатга кетказади ва хоҳлаган кимсани ҳидоят қилади. Ва, албатта, қилиб юрган амалларингиздан сўралурсизлар.",277,14],["وَلَا تَتَّخِذ[o[ُوٓ][s[اْ] أَيْمَ[n[ـٰ]نَكُمْ دَخَل[i:7562[اَۢ ب]َيْنَكُمْ فَتَزِلَّ قَدَ[i:7566[مُۢ ب]َعْدَ ثُبُوتِهَا وَتَذُوقُو[s[اْ] [h:7567[ٱ][l[ل]سّ[o[ُو]ٓءَ بِمَا صَدَ[d:7568[د]تُّمْ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ‌ۖ وَلَكُمْ عَذَابٌ عَظ[p[ِي]مٌ","Қасамларингизни орангизда алдов воситаси қилиб олманг. Бас, қадам собит бўлганидан сўнг тоймасин ва Аллоҳнинг йўлидан тўсганингиз учун ёмонликни татиб юрманг. Сизга улкан азоб бўлмасин.",278,14],["وَلَا تَشْتَرُو[s[اْ] بِعَهْدِ [h:2038[ٱ]للَّهِ ثَمَ[f:208[نًا ق]َلِيلاً‌ۚ إِ[g[نّ]َمَا عِ[f:264[ند]َ [h:408[ٱ]للَّهِ هُوَ خَيْ[u:263[رٌ ل]َّكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","Аллоҳнинг аҳдини оз баҳога сотиб юборманг. Агар билсангиз, сиз учун, албатта, Аллоҳнинг ҳузуридаги нарса яхшироқдир.",278,14],["مَا عِ[f:4508[ند]َكُمْ يَ[f:7569[نف]َدُ‌ۖ وَمَا عِ[f:264[ند]َ [h:408[ٱ]للَّهِ بَا[a:7570[قٍ‌ۗ و]َلَنَ[q:7571[جْ]زِيَ[g[نّ]َ [h:7572[ٱ]لَّذِينَ صَبَر[o[ُوٓ][s[اْ] أَ[q:7573[جْ]رَه[c:7574[ُم ب]ِأَحْسَنِ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Сизнинг ҳузурингиздаги нарса тугайдир. Аллоҳнинг ҳузуридаги нарса эса, боқийдир. Албатта, Биз сабр этганларни қилиб юрган амалларининг энг гўзалига бериладиган ажр ила мукофотлармиз.",278,14],["مَنْ عَمِلَ صَ[n[ـٰ]لِ[a:7575[حًا م]ِّ[f:2511[ن ذ]َكَرٍ أَوْ أُ[f:1867[نث]َىٰ وَهُوَ مُؤْمِ[f:7576[نٌ ف]َلَنُحْيِيَ[g[نّ]َهُ[n[ۥ] حَيَ[s[و][n[ٲ][f:7577[ةً ط]َيِّبَ[a:7578[ةً‌ۖ و]َلَنَ[q:7579[جْ]زِيَ[g[نّ]َهُمْ أَ[q:7573[جْ]رَه[c:7574[ُم ب]ِأَحْسَنِ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Эркагу аёл, ким мўмин ҳолида яхши амал қилса, Биз унга яхши ҳаёт кечиртирамиз ва, албатта, уларни қилиб юрган амалларининг энг гўзалига бериладиган ажр ила мукофотлармиз.",278,14],["فَإِذَا قَرَأْتَ [h:7580[ٱ]لْقُرْءَانَ فَ[h:5208[ٱ]سْتَعِذْ بِ[h:32[ٱ]للَّهِ مِنَ [h:1870[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ [h:1871[ٱ][l[ل]رَّج[p[ِي]مِ","Қуръон ўқиган чоғингда, Аллоҳдан қувилган шайтондан паноҳ сўрагин.",278,14],["إِ[g[نّ]َهُ[n[ۥ] لَيْسَ لَهُ[n[ۥ] سُلْطَ[n[ـٰ]نٌ عَلَى [h:289[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَلَىٰ رَبِّهِمْ يَتَوَكَّل[p[ُو]نَ","Албатта, иймон келтирганлар ва ўз Роббиларига таваккал қилганларга унинг султони йўқ.",278,14],["إِ[g[نّ]َمَا سُلْطَ[n[ـٰ]نُهُ[n[ۥ] عَلَى [h:289[ٱ]لَّذِينَ يَتَوَلَّوْنَهُ[n[ۥ] وَ[h:37[ٱ]لَّذِينَ ه[c:7581[ُم ب]ِه[n[ِۦ] مُشْرِك[p[ُو]نَ","Унинг султони фақат уни дўст тутадиганларга ва у сабабли мушрик бўлганларга, холос.",278,14],["وَإِذَا بَدَّلْن[o[َآ] ءَايَ[a:7582[ةً م]َّكَانَ ءَايَ[a:7583[ةٍ‌ۙ و]َ[h:72[ٱ]للَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َم[o[َآ] أَ[f:169[نت]َ مُفْتَ[i:7584[رِۭ‌ۚ ب]َلْ أَكْثَرُهُمْ لَا يَعْلَم[p[ُو]نَ","Қачонки, Биз бир оят ўрнини бошқа бир оят ила алмаштирсак, –ҳолбуки, Аллоҳ нимани нозил қилишни ўзи яхши билгувчидир–улар: «Шубҳасиз, сен уйдирмачисан!» дерлар. Йўқ! Уларнинг кўплари билмаслар.",278,14],["قُلْ نَزَّلَهُ[n[ۥ] رُوحُ [h:7585[ٱ]لْقُدُسِ م[u:770[ِن ر]َّبِّكَ بِ[h:370[ٱ]لْحَقِّ لِيُثَبِّتَ [h:7586[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَهُ[a:510[دًى و]َبُشْرَىٰ لِلْمُسْلِم[p[ِي]نَ","Сен уни руҳул қудус Роббингдан иймон келтирганларни собитқадам қилиш учун ва мусулмонларга ҳидоят ва хушхабар этиб ҳақ ила туширганини айт.",278,14],["وَلَقَ[q:341[دْ] نَعْلَمُ أَ[g[نّ]َهُمْ يَقُولُونَ إِ[g[نّ]َمَا يُعَلِّمُهُ[n[ۥ] بَشَ[u:7587[رٌ‌ۗ ل]ِّسَانُ [h:7588[ٱ]لَّذِى يُلْحِدُونَ إِلَيْهِ أَعْجَمِ[a:7589[ىٌّ و]َهَ[n[ـٰ]ذَا لِسَانٌ عَرَبِ[a:7590[ىٌّ م]ُّب[p[ِي]نٌ","Батаҳқиқ, биламизки, албатта, улар: «Унга фақат башар таълим бермоқда, холос», дерлар. Улар гумон қилаётганнинг тили ажамийдир. Бу эса очиқ-ойдин араб тилидадир.",279,14],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ لَا يَهْدِيهِمُ [h:7591[ٱ]للَّهُ وَلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Албатта, Аллоҳнинг оятларига иймон келтирмайдиганларни Аллоҳ ҳидятга солмас ва уларга аламли азоб бордир.",279,14],["إِ[g[نّ]َمَا يَفْتَرِى [h:7592[ٱ]لْكَذِبَ [h:7593[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:7594[ٱ]لْكَ[n[ـٰ]ذِب[p[ُو]نَ","Ёлғонни фақат Аллоҳнинг оятларига иймон келтирмайдиганларгина тўқирлар. Ана ўшалар ўзлари ёлғончилардир.",279,14],["مَ[f:1457[ن ك]َفَرَ بِ[h:32[ٱ]للَّهِ م[i:146[ِنۢ ب]َعْدِ إِيمَ[n[ـٰ]نِه[o[ِۦٓ] إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ[n[ۥ] مُ[q:7595[طْ]مَئِن[i:7596[ُّۢ ب]ِ[h:562[ٱ]لْإِيمَ[n[ـٰ]نِ وَلَ[n[ـٰ]ك[a:7597[ِن م]َّ[f:7598[ن ش]َرَحَ بِ[h:2055[ٱ]لْكُفْرِ صَ[q:7599[دْ][f:7600[رًا ف]َعَلَيْهِمْ غَضَ[a:7601[بٌ م]ِّنَ [h:321[ٱ]للَّهِ وَلَهُمْ عَذَابٌ عَظ[p[ِي]مٌ","Ким иймондан сўнг Аллоҳга куфр келтирса, қалби иймон ила ором топа туриб зўрланганлар бундан мустасно, ким кўксини куфрга очса, бас, уларга Аллоҳдан ғазаб бор. Уларга улкан азоб бор.",279,14],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمُ [h:7602[ٱ]سْتَحَبُّو[s[اْ] [h:7603[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَا عَلَى [h:7042[ٱ]لْأَخِرَةِ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1557[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Бу уларнинг дунё ҳаётини охиратдан устун қўйганлари сабабидандир. Албатта, Аллоҳ кофир қавмларни ҳидоят этмас.",279,14],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ طَبَعَ [h:3271[ٱ]للَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَ[q:79[بْ]صَ[n[ـٰ]رِهِمْ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:5154[ٱ]لْغَ[n[ـٰ]فِل[p[ُو]نَ","Ана ўшаларнинг қалблари, қулоқлари ва кўзларига Аллоҳ муҳр босгандир. Ана ўшалар ғофиллардир.",279,14],["لَا جَرَمَ أَ[g[نّ]َهُمْ فِى [h:536[ٱ]لْأَخِرَةِ هُمُ [h:150[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","Ҳеч шубҳа йўқки, охиратда улар зиён кўргувчилардир.",279,14],["ثُ[g[مّ]َ إِ[g[نّ]َ رَبَّكَ لِلَّذِينَ هَاجَرُو[s[اْ] م[i:146[ِنۢ ب]َعْدِ مَا فُتِنُو[s[اْ] ثُ[g[مّ]َ جَ[n[ـٰ]هَدُو[s[اْ] وَصَبَر[o[ُوٓ][s[اْ] إِ[g[نّ]َ رَبَّكَ م[i:5039[ِنۢ ب]َعْدِهَا لَغَفُو[u:4578[رٌ ر]َّح[p[ِي]مٌ","Сўнгра, албатта, Роббинг фитнага учраганларидан кейин ҳижрат этиб, жиҳод қилган ва сабр этгани учун, албатта, Роббинг шулардан кейин мағфиратли ва раҳмлидир.",279,14],["۞ يَوْمَ تَأْتِى كُلُّ نَفْ[f:7604[سٍ ت]ُجَ[n[ـٰ]دِلُ ع[a:7605[َن ن]َّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْ[a:1654[سٍ م]َّا عَمِلَتْ وَهُمْ لَا يُظْلَم[p[ُو]نَ","У кунда ҳар жон ўзи ҳақида тортишиш учун келур ва ҳар бир жонга амалига яраша вафо қилинур ҳамда уларга зулм этилмас.",280,14],["وَضَرَبَ [h:7509[ٱ]للَّهُ مَثَل[f:7606[اً ق]َرْيَ[f:7607[ةً ك]َانَتْ ءَامِنَ[a:7608[ةً م]ُّ[q:7609[طْ]مَئِ[g[نّ]َ[a:7610[ةً ي]َأْتِيهَا رِزْقُهَا رَغَ[a:7611[دًا م]ِّ[f:843[ن ك]ُلِّ مَكَا[f:7612[نٍ ف]َكَفَرَتْ بِأَنْعُمِ [h:7613[ٱ]للَّهِ فَأَذ[n[َٲ]قَهَا [h:7614[ٱ]للَّهُ لِبَاسَ [h:7615[ٱ]لْجُوعِ وَ[h:7616[ٱ]لْخَوْفِ بِمَا كَانُو[s[اْ] يَصْنَع[p[ُو]نَ","Аллоҳ бир шаҳарни зарбул масал қилади: у омонлик ва хотиржамликда эди. Ризқи ҳар макондан сероб ҳолда келиб турарди. Сўнг у Аллоҳнинг неъматларига куфр келтирди. Бас, Аллоҳ унга қилган ишлари учун очлик ва хавф кийимини тоттирди.",280,14],["وَلَقَ[q:341[دْ] ج[o[َا]ٓءَهُمْ رَسُو[a:7617[لٌ م]ِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ [h:7618[ٱ]لْعَذَابُ وَهُمْ ظَ[n[ـٰ]لِم[p[ُو]نَ","Батаҳқиқ, уларга ўзларидан Пайғамбар келди. Бас, улар уни ёлғончига чиқардилар. Кейин золим бўлганлари учун уларни азоб тутди.",280,14],["فَكُلُو[s[اْ] مِ[g[مّ]َا رَزَقَكُمُ [h:3751[ٱ]للَّهُ حَلَ[n[ـٰ]ل[f:870[اً ط]َيِّ[a:7619[بًا و]َ[h:783[ٱ]شْكُرُو[s[اْ] نِعْمَتَ [h:1300[ٱ]للَّهِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ إِيَّاهُ تَعْبُد[p[ُو]نَ","Бас, Аллоҳ сизга ризқ қилиб берган нарсалардан ҳалол-пок ҳолида енг. Ва агар Унга ибодат қиладиган бўлсангиз, Аллоҳнинг неъматига шукр қилинг.",280,14],["إِ[g[نّ]َمَا حَرَّمَ عَلَيْكُمُ [h:882[ٱ]لْمَيْتَةَ وَ[h:883[ٱ][l[ل]دَّمَ وَلَحْمَ [h:884[ٱ]لْخِ[f:885[نز]ِيرِ وَم[o[َآ] أُهِلَّ لِغَيْرِ [h:886[ٱ]للَّهِ بِه[n[ِۦ]‌ۖ فَمَنِ [h:887[ٱ]ضْطُرَّ غَيْرَ بَا[a:888[غٍ و]َلَا عَا[f:4493[دٍ ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Сизларга фақат ўлимтикни, қонни, чўчқа гўштини ва Аллоҳдан ўзгага атаб сўйилган нарсаларнигина ҳаром қилди. Ким золим ва ҳаддан ошувчи бўлмаган ҳолида мажбур бўлиб қолса, албатта, Аллоҳ мағфиратли ва раҳмлидир.",280,14],["وَلَا تَقُولُو[s[اْ] لِمَا تَصِفُ أَلْسِنَتُكُمُ [h:7620[ٱ]لْكَذِبَ هَ[n[ـٰ]ذَا حَلَ[n[ـٰ][a:7621[لٌ و]َهَ[n[ـٰ]ذَا حَرَا[u:7622[مٌ ل]ِّتَفْتَرُو[s[اْ] عَلَى [h:412[ٱ]للَّهِ [h:2035[ٱ]لْكَذِبَ‌ۚ إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَفْتَرُونَ عَلَى [h:412[ٱ]للَّهِ [h:2035[ٱ]لْكَذِبَ لَا يُفْلِح[p[ُو]نَ","Аллоҳга нисбатан ёлғон тўқиш учун тилларингиз васф қилган ёлғонни гапириб: «Бу ҳалол, бу ҳаром», деяверманглар. Албатта, Аллоҳга нисбатан ёлғон тўқувчилар нажот топмаслар.",280,14],["مَتَ[n[ـٰ][f:2520[عٌ ق]َلِي[a:7623[لٌ و]َلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Озгина матоҳ ва аламли азоб бор.",280,14],["وَعَلَى [h:958[ٱ]لَّذِينَ هَادُو[s[اْ] حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ وَمَا ظَلَمْنَ[n[ـٰ]هُمْ وَلَ[n[ـٰ]كِ[f:276[ن ك]َان[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ يَظْلِم[p[ُو]نَ","Яҳудий бўлганларга эса, сенга бундан олдин айтиб берган нарсаларимизни ҳаром қилдик. Биз уларга зулм қилмадик. Лекин улар ўзларига зулм қилган эдилар.",280,14],["ثُ[g[مّ]َ إِ[g[نّ]َ رَبَّكَ لِلَّذِينَ عَمِلُو[s[اْ] [h:7624[ٱ][l[ل]سّ[o[ُو]ٓءَ بِجَهَ[n[ـٰ]لَ[f:2649[ةٍ ث]ُ[g[مّ]َ تَابُو[s[اْ] م[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ وَأَصْلَح[o[ُوٓ][s[اْ] إِ[g[نّ]َ رَبَّكَ م[i:5039[ِنۢ ب]َعْدِهَا لَغَفُو[u:4578[رٌ ر]َّح[p[ِي]مٌ","Сўнгра, Роббинг билмасдан ёмон амал қилган, ундан кейин эса тавба қилиб яхши амалларни қилганларга, албатта, Роббинг ўшандан сўнг мағфиратли ва раҳмлидир.",281,14],["إِ[g[نّ]َ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ كَانَ أُ[g[مّ]َ[f:7625[ةً ق]َانِ[u:7626[تًا ل]ِّلَّهِ حَنِي[a:7627[فًا و]َلَمْ يَكُ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Албатта, Иброҳим Аллоҳнинг итоат қилгувчи, ҳаққа мойил уммати эди. Мушриклардан бўлган эмас.",281,14],["شَاكِ[u:7628[رًا ل]ِّأَنْعُمِهِ‌ۚ [h:7629[ٱ][q:7630[جْ]تَبَ[n[ـٰ]هُ وَهَدَ[n[ٮٰ]هُ إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Унинг неъматларига шукр қилгувчи эди. У зот уни танлаб олди ва сиротул мустақиймга ҳидоят қилди.",281,14],["وَءَاتَيْنَ[n[ـٰ]هُ فِى [h:599[ٱ][l[ل]دُّنْيَا حَسَنَ[a:7631[ةً‌ۖ و]َإِ[g[نّ]َهُ[n[ۥ] فِى [h:536[ٱ]لْأَخِرَةِ لَمِنَ [h:686[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Унга бу дунёда яхши бердик. Охиратда эса, у, албатта, солиҳлардандир.",281,14],["ثُ[g[مّ]َ أَوْحَيْن[o[َآ] إِلَيْكَ أَنِ [h:7632[ٱ]تَّبِعْ مِلَّةَ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ حَنِي[a:698[فًا‌ۖ و]َمَا كَانَ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Сўнгра сенга: «Иброҳимнинг ҳаққа мойил миллатига эргаш. У мушриклардан бўлмаган эди», деб ваҳий қилдик.",281,14],["إِ[g[نّ]َمَا جُعِلَ [h:7633[ٱ][l[ل]سَّ[q:7634[بْ]تُ عَلَى [h:289[ٱ]لَّذِينَ [h:899[ٱ]خْتَلَفُو[s[اْ] فِيهِ‌ۚ وَإِ[g[نّ]َ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ فِيمَا كَانُو[s[اْ] فِيهِ يَخْتَلِف[p[ُو]نَ","Шанба фақат у тўғрисида ихтилоф қилганлар зиммасига юкланди, холос. Албатта, Роббинг қиёмат кунида улар орасида ихтилоф қилган нарсалари ҳақида ҳукм чиқарур.",281,14],["ٱ[q:354[دْ]عُ إِلَىٰ سَبِيلِ رَبِّكَ بِ[h:7635[ٱ]لْحِكْمَةِ وَ[h:7636[ٱ]لْمَوْعِظَةِ [h:7637[ٱ]لْحَسَنَةِ‌ۖ وَجَ[n[ـٰ]دِلْه[c:7638[ُم ب]ِ[h:4526[ٱ]لَّتِى هِىَ أَحْسَنُ‌ۚ إِ[g[نّ]َ رَبَّكَ هُوَ أَعْلَمُ بِمَ[f:7639[ن ض]َلَّ عَ[f:4361[ن س]َبِيلِه[n[ِۦ]‌ۖ وَهُوَ أَعْلَمُ بِ[h:4362[ٱ]لْمُهْتَد[p[ِي]نَ","Роббингнинг йўлига ҳикмат ва яхши мавъиза ила даъват қил. Ва улар ила гўзал услубда мунозара қил. Албатта, Роббинг Ўз йўлидан адашганларни ўта билгувчи ва ҳидоят топгувчиларни ҳам ўта билгувчидир.",281,14],["وَإِنْ عَاقَ[q:7640[بْ]تُمْ فَعَاقِبُو[s[اْ] بِمِثْلِ مَا عُوقِ[q:7641[بْ]ت[c:7642[ُم ب]ِه[n[ِۦ]‌ۖ وَلَئِ[f:7643[ن ص]َبَرْتُمْ لَهُوَ خَيْ[u:7644[رٌ ل]ِّلصَّ[n[ـٰ]بِر[p[ِي]نَ","Агар иқоб қиладиган бўлсангиз, ўзингизга қилинган иқобга ўхшаш иқоб қилинг. Агар сабр қилсангиз, албатта, у сабр қилгувчилар учун хайрлидир.",281,14],["وَ[h:9999[ٱ]صْبِرْ وَمَا صَ[q:7645[بْ]رُكَ إِلَّا بِ[h:32[ٱ]للَّهِ‌ۚ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِى ضَيْ[a:7646[قٍ م]ِّ[g[مّ]َا يَمْكُر[p[ُو]نَ","Сабр қил, сенинг сабринг фақат Аллоҳ ила бўлур. Уларга хафа бўлма. Улар қилаётган макрдан сиқилма.",281,14],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ مَعَ [h:2899[ٱ]لَّذِينَ [h:7007[ٱ]تَّقَو[s[اْ] وَّ[h:37[ٱ]لَّذِينَ ه[w:7647[ُم م]ُّحْسِن[p[ُو]نَ","Албатта, Аллоҳ тақво қилганлар ва гўзал ишлар қилганлар биландир.",281,14]]},{"n":17,"ar":"الإِسۡرَاءِ","en":"Al-Israa","uz":"Исро","type":"Макка","ayahs":[["سُ[q:7648[بْ]حَ[n[ـٰ]نَ [h:7649[ٱ]لَّذ[o[ِىٓ] أَسْرَىٰ بِعَ[q:7650[بْ]دِه[n[ِۦ] لَيْل[a:7651[اً م]ِّنَ [h:7652[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ إِلَى [h:7653[ٱ]لْمَسْجِدِ [h:7654[ٱ]لْأَ[q:7655[قْ]صَا [h:7656[ٱ]لَّذِى بَ[n[ـٰ]رَكْنَا حَوْلَهُ[n[ۥ] لِنُرِيَهُ[n[ۥ] مِنْ ءَايَ[n[ـٰ]تِن[o[َآ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:3721[ٱ][l[ل]سَّمِيعُ [h:7657[ٱ]لْبَص[p[ِي]رُ","Ўз бандасини кечаси Масжидул Ҳаромдан атрофини баракали қилганимиз Масжидул Ақсога оят-мўъжизаларимизни кўрсатиш учун сайр қилдирган зот пок бўлди. Албатта, У эшитгувчи ва кўргувчи зотдир.",282,15],["وَءَاتَيْنَا مُوسَى [h:257[ٱ]لْكِتَ[n[ـٰ]بَ وَجَعَلْنَ[n[ـٰ]هُ هُ[u:7658[دًى ل]ِّبَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ أَلَّا تَتَّخِذُو[s[اْ] مِ[f:7659[ن د]ُونِى وَكِيلاً","Ва Биз Мусога китобни бердик ва уни Бани Исроилга ҳидоят қилиб: «Мендан ўзгани вакил тутманглар!» дедик.",282,15],["ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ عَ[q:3317[بْ][f:7660[دًا ش]َكُورًا","Нуҳ билан бирга кўтарганларимизнинг зурриётлари! Албатта, у ўта шукрли банда эди.",282,15],["وَقَضَيْن[o[َآ] إِلَىٰ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ لَتُفْسِدُ[g[نّ]َ فِى [h:44[ٱ]لْأَرْضِ مَرَّتَيْنِ وَلَتَعْلُ[g[نّ]َ عُلُو[f:7661[ًّا ك]َبِيرًا","Биз у китобда Бани Исроилга, ер юзида икки марта бузғунчилик қилурсизлар ва катта туғёнга кетурсизлар, деб билдирдик.",282,15],["فَإِذَا ج[o[َا]ٓءَ وَعْدُ أُولَ[n[ـٰ]هُمَا بَعَثْنَا عَلَيْكُمْ عِبَا[u:7662[دًا ل]َّن[o[َآ] أُ[s[وْ]لِى بَأْ[f:7663[سٍ ش]َدِي[f:7664[دٍ ف]َجَاسُو[s[اْ] خِلَ[n[ـٰ]لَ [h:7665[ٱ][l[ل]دِّيَارِ‌ۚ وَكَانَ وَعْ[a:7666[دًا م]َّفْعُولاً","Бас, ўша иккидан биринчисининг ваъда вақти келганда, устингизга шиддатли куч-қудратга эга бандаларимизни юбораурмиз. Бас, улар ҳовли-жойларни оралаб кезарлар. Бу қилиниши лозим ваъда эди.",282,15],["ثُ[g[مّ]َ رَدَ[q:7667[دْ]نَا لَكُمُ [h:7668[ٱ]لْكَرَّةَ عَلَيْهِمْ وَأَمْدَ[q:7669[دْ]نَ[n[ـٰ]ك[c:7670[ُم ب]ِأَمْو[n[َٲ][a:7671[لٍ و]َبَنِينَ وَجَعَلْنَ[n[ـٰ]كُمْ أَكْثَرَ نَفِيرًا","Сўнгра сизга улар устидан ғалабани қайтардик ва сизга молу дунё ва фарзандлар ила мадад бердик. Ва сизларнинг нафарингизни кўп қилиб қўйдик.",282,15],["إِنْ أَحْسَ[f:7672[نت]ُمْ أَحْسَ[f:7672[نت]ُمْ لِأَ[f:574[نف]ُسِكُمْ‌ۖ وَإِنْ أَسَأْتُمْ فَلَهَا‌ۚ فَإِذَا ج[o[َا]ٓءَ وَعْدُ [h:7673[ٱ]لْأَخِرَةِ لِيَسُ[n[ــۥٓ]ــُٔو[s[اْ] وُجُوهَكُمْ وَلِيَ[q:7674[دْ]خُلُو[s[اْ] [h:7675[ٱ]لْمَسْجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّ[a:7676[ةٍ و]َلِيُتَبِّرُو[s[اْ] مَا عَلَوْ[s[اْ] تَتْبِيرًا","Агар яхшилик қилсангиз, ўзингиз учун яхшилик қиласиз. Агар ёмонлик қилсангиз ҳам, ўзингиз учундир. Бас, кейинги ваъда вақти келганда, юзингизни қора қилишлари учун, масжидга аввал кирганларидек киришлари учун ва эгаллаган нарсаларини тамоман парчалашлари учун.",282,15],["عَسَىٰ رَبُّكُمْ أ[a:7677[َن ي]َرْحَمَكُمْ‌ۚ وَإِنْ عُ[d:7678[د]تُّمْ عُ[q:4860[دْ]نَا‌ۘ وَجَعَلْنَا جَهَ[g[نّ]َمَ لِلْكَ[n[ـٰ]فِرِينَ حَصِيرًا","Шояд Роббингиз сизга раҳм қилса. Агар сиз қайтсангиз, Биз ҳам қайтамиз. Ва жаҳаннамни кофирларга зиндон қилганмиз.",283,15],["إِ[g[نّ]َ هَ[n[ـٰ]ذَا [h:6544[ٱ]لْقُرْءَانَ يَهْدِى لِلَّتِى هِىَ أَ[q:7679[قْ]وَمُ وَيُبَشِّرُ [h:7680[ٱ]لْمُؤْمِنِينَ [h:7681[ٱ]لَّذِينَ يَعْمَلُونَ [h:7682[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ أَ[g[نّ]َ لَهُمْ أَ[q:2795[جْ][f:7683[رًا ك]َبِيرًا","Албатта, бу Қуръон энг тўғри йўлга ҳидоят қилур ва яхши амалларни қилувчи мўминларга, албатта, ўшаларга, улуғ ажр борлиги хушхабарини берур.",283,15],["وَأَ[g[نّ]َ [h:7684[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ أَعْتَ[q:2660[دْ]نَا لَهُمْ عَذَابًا أَلِيمًا","Албатта, охиратга иймон келтирмайдиганларга, ўшаларга аламли азобни тайёрлаб қўйдик.",283,15],["وَيَ[q:7685[دْ]عُ [h:7686[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ بِ[h:7687[ٱ][l[ل]شَّرِّ دُع[o[َا]ٓءَهُ[n[ۥ] بِ[h:5966[ٱ]لْخَيْرِ‌ۖ وَكَانَ [h:7688[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ عَجُولاً","Инсон яхшиликка дуо қилганидек, ёмонликка ҳам дуо қилур. Инсон шошқалоқ бўлгандир.",283,15],["وَجَعَلْنَا [h:7689[ٱ]لَّيْلَ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ ءَايَتَيْنِ‌ۖ فَمَحَوْن[o[َآ] ءَايَةَ [h:7690[ٱ]لَّيْلِ وَجَعَلْن[o[َآ] ءَايَةَ [h:7691[ٱ][l[ل][g[نّ]َهَارِ مُ[q:7692[بْ]صِرَ[u:7693[ةً ل]ِّتَ[q:7694[بْ]تَغُو[s[اْ] فَضْل[a:1088[اً م]ّ[u:243[ِن ر]َّبِّكُمْ وَلِتَعْلَمُو[s[اْ] عَدَدَ [h:5950[ٱ][l[ل]سِّنِينَ وَ[h:5951[ٱ]لْحِسَابَ‌ۚ وَكُلَّ ش[f:7695[َىْءٍ ف]َصَّلْنَ[n[ـٰ]هُ تَفْصِيلاً","Кеча ва кундузни икки оят-аломат қилдик. Кеча аломатини маҳв этдик. Кундуз аломатини кўрсатувчи қилдикки, токи Роббингиздан фазл талаб қилсангиз ва йиллар ададини ҳамда ҳисобини билсангиз. Ва ҳар бир нарсани батафсил баён қилганмиз.",283,15],["وَكُلَّ إِ[f:7696[نس]َ[n[ـٰ]نٍ أَلْزَمْنَ[n[ـٰ]هُ طَ[o[ـٰٓ]ئِرَهُ[n[ۥ] فِى عُنُقِه[n[ِۦ]‌ۖ وَنُخْرِجُ لَهُ[n[ۥ] يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ كِتَ[n[ـٰ][a:7697[بًا ي]َلْقَ[n[ـٰ]هُ مَ[f:7698[نش]ُورًا","Биз ҳар бир инсоннинг амалини бўйнига боғлаб қўйганмиз ва қиёмат куни унга китоб чиқарамизки, унга очилган ҳолда рўбарў бўлур.",283,15],["ٱ[q:7699[قْ]رَأْ كِتَ[n[ـٰ]بَكَ كَفَىٰ بِنَفْسِكَ [h:7700[ٱ]لْيَوْمَ عَلَيْكَ حَسِيبًا","Китобингни ўқи, бугунги кунда сен ўзингга ўзинг ҳисобчиликка кифоя қилурсан.",283,15],["مَّنِ [h:7701[ٱ]هْتَدَىٰ فَإِ[g[نّ]َمَا يَهْتَدِى لِنَفْسِه[n[ِۦ]‌ۖ وَمَ[f:6231[ن ض]َلَّ فَإِ[g[نّ]َمَا يَضِلُّ عَلَيْهَا‌ۚ وَلَا تَزِرُ وَازِرَ[a:4572[ةٌ و]ِزْرَ أُخْرَىٰ‌ۗ وَمَا كُ[g[نّ]َا مُعَذِّبِينَ حَتَّىٰ نَ[q:7702[بْ]عَثَ رَسُولاً","Ким ҳидоятга юрса, фақат ўзи учунгина ҳидоят топадир. Ким залолатга кетса, фақат ўзи учунгина залолатга кетадир. Ҳеч бир жон ўзганинг оғирлигини кўтарувчи бўлмас. Токи Пайғамбар юбормагунимизча, азобловчи бўлган эмасмиз.",283,15],["وَإِذ[o[َآ] أَرَ[q:2878[دْ]ن[o[َآ] أ[a:7703[َن ن]ُّهْلِكَ قَرْيَةً أَمَرْنَا مُتْرَفِيهَا فَفَسَقُو[s[اْ] فِيهَا فَحَقَّ عَلَيْهَا [h:7704[ٱ]لْقَوْلُ فَدَ[g[مّ]َرْنَ[n[ـٰ]هَا تَ[q:7705[دْ]مِيرًا","Қачон бир шаҳарни ҳалок этишни истасак, унинг маишатпарастларини амр қилурмиз, бас, улар уда фисқ қилурлар. Шунда унга «сўз» ҳақ бўлур. Бас, Биз уни мутлақо вайрон қилурмиз.",283,15],["وَكَمْ أَهْلَكْنَا مِنَ [h:6524[ٱ]لْقُرُونِ م[i:146[ِنۢ ب]َعْدِ نُو[a:7706[حٍ‌ۗ و]َكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِه[n[ِۦ] خَبِير[i:7707[َۢا ب]َصِيرًا","Нуҳдан сўнг қанчадан-қанча асрларни ҳалок қилдик. Бандаларининг гуноҳларидан хабардор бўлиш ва уларни кўришда Роббинг Ўзи кифоя қилур.",283,15],["مَّ[f:506[ن ك]َانَ يُرِيدُ [h:7708[ٱ]لْعَاجِلَةَ عَجَّلْنَا لَهُ[n[ۥ] فِيهَا مَا نَش[o[َا]ٓءُ لِم[a:7709[َن ن]ُّرِيدُ ثُ[g[مّ]َ جَعَلْنَا لَهُ[n[ۥ] جَهَ[g[نّ]َمَ يَصْلَ[n[ـٰ]هَا مَذْمُو[a:7710[مًا م]َّ[q:4617[دْ]حُورًا","Ким шошганни истаса, унга бу дунёда ирода қилган кишимизга нимани хоҳласак, шошилинч берурмиз. Сўнгра унга жаҳаннамни берурмиз. Унга хор ва қувғинга учраган ҳолда кирур.",284,15],["وَمَنْ أَرَادَ [h:7711[ٱ]لْأَخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِ[f:3155[نٌ ف]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ كَانَ سَعْيُه[w:7712[ُم م]َّشْكُورًا","Ким охиратни истаса ва унга эришиш учун мўмин бўлган ҳолида керакли ҳаракатини қилса, бас, ана ўшаларнинг ҳаракатлари мақбулдир.",284,15],["كُل[a:7713[اًّ ن]ُّمِدُّ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ وَهَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ مِنْ عَط[o[َا]ٓءِ رَبِّكَ‌ۚ وَمَا كَانَ عَط[o[َا]ٓءُ رَبِّكَ مَحْظُورًا","Барчага–манавиларга ҳам, анавиларга ҳам Роббингнинг атою неъматларидан чўзамиз. Роббингнинг атою неъматлари ман бўлган эмас.",284,15],["ٱ[f:2837[نظ]ُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْ[a:7714[ضٍ‌ۚ و]َلَلْأَخِرَةُ أَكْبَرُ دَرَجَ[n[ـٰ][a:7715[تٍ و]َأَكْبَرُ تَفْضِيلاً","Баъзиларини баъзиларидан қандай афзал қилиб қўйганимизга назар сол. Албатта, охират даражаси ва афзаллиги каттароқдир.",284,15],["لَّا تَ[q:7716[جْ]عَلْ مَعَ [h:3975[ٱ]للَّهِ إِلَ[n[ـٰ]هًا ءَاخَرَ فَتَ[q:7717[قْ]عُدَ مَذْمُو[a:7718[مًا م]َّخْذُولاً","Аллоҳ билан бирга ўзга илоҳни қилма! Яна мазамматга учраб, чорасиз ўтириб қолмагин.",284,15],["۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُد[o[ُوٓ][s[اْ] إِلّ[o[َآ] إِيَّاهُ وَبِ[h:417[ٱ]لْو[n[َٲ]لِدَيْنِ إِحْسَ[n[ـٰ]نًا‌ۚ إِ[g[مّ]َا يَ[q:7719[بْ]لُغَ[g[نّ]َ عِ[f:4962[ند]َكَ [h:7720[ٱ]لْكِبَرَ أَحَدُهُم[o[َآ] أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُم[o[َآ] أُ[a:7721[فٍّ و]َلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْل[f:7722[اً ك]َرِيمًا","Роббинг фақат Унинг Ўзигагина ибодат қилишингни ва ота-онага яхшилик қилишнигни амр этди. Агар ҳузурингда уларнинг бирлари ёки икковлари ҳам кексаликка етсалар, бас, уларга «уфф» дема, уларга озор берма ва уларга яхши сўз айт!",284,15],["وَ[h:9999[ٱ]خْفِضْ لَهُمَا جَنَاحَ [h:7723[ٱ][l[ل]ذُّلِّ مِنَ [h:7724[ٱ][l[ل]رَّحْمَةِ وَقُ[b:7725[ل] رَّبِّ [h:7726[ٱ]رْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًا","Икковларига меҳрибонлик ила хокисорлик қанотингни паслат ва «Роббим, алар мени кичикликда тарбия қилганларидек, уларга раҳм қилгин», деб айт.",284,15],["رَّبُّكُمْ أَعْلَمُ بِمَا فِى نُفُوسِكُمْ‌ۚ إِ[f:3101[ن ت]َكُونُو[s[اْ] صَ[n[ـٰ]لِحِينَ فَإِ[g[نّ]َهُ[n[ۥ] كَانَ لِلْأَوّ[n[َٲ]بِينَ غَفُورًا","Роббингиз, сизнинг дилингиздаги нарсани ҳам ўта билгувчидир. Агар аҳли солиҳлардан бўлсангиз, албатта, У сертавбалар учун сермағфиратдир.",284,15],["وَءَاتِ ذَا [h:7727[ٱ]لْقُرْبَىٰ حَقَّهُ[n[ۥ] وَ[h:7728[ٱ]لْمِسْكِينَ وَ[h:911[ٱ][q:911[بْ]نَ [h:912[ٱ][l[ل]سَّبِيلِ وَلَا تُبَذِّرْ تَ[q:7729[بْ]ذِيرًا","Қариндошга ҳаққини бер! Мискинга ва кўчада қолганга ҳам. Исрофгарчиликка мутлақо йўл қўйма.",284,15],["إِ[g[نّ]َ [h:7730[ٱ]لْمُبَذِّرِينَ كَان[o[ُوٓ][s[اْ] إِخْو[n[َٲ]نَ [h:7731[ٱ][l[ل]شَّيَ[n[ـٰ]طِينِ‌ۖ وَكَانَ [h:7732[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ لِرَبِّه[n[ِۦ] كَفُورًا","Албатта, исрофчилар шайтонларнинг биродарлари бўлганлар. Шайтон эса, Роббига ўта ношукр бўлгандир.",284,15],["وَإِ[g[مّ]َا تُعْرِضَ[g[نّ]َ عَنْهُمُ [h:7733[ٱ][q:1130[بْ]تِغ[o[َا]ٓءَ رَحْمَ[a:7734[ةٍ م]ّ[u:770[ِن ر]َّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْل[a:7735[اً م]َّيْسُورًا","Агар улардан Роббингдан раҳмат талаб қилган ҳолда юз ўгирадиган бўлсанг, бас, уларга мулойим сўз айтгин.",285,15],["وَلَا تَ[q:7716[جْ]عَلْ يَدَكَ مَغْلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَ[q:7736[بْ]سُ[q:7736[طْ]هَا كُلَّ [h:7737[ٱ]لْبَسْطِ فَتَ[q:7717[قْ]عُدَ مَلُو[a:7738[مًا م]َّحْسُورًا","Қўлингни бўйнингга боғлаб олма. Уни бир йўла ёзиб ҳам юборма. Яна маломат ва ҳасратда ўтириб қолмагин.",285,15],["إِ[g[نّ]َ رَبَّكَ يَ[q:6968[بْ]سُطُ [h:6969[ٱ][l[ل]رِّزْقَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيَ[q:6970[قْ]دِرُ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ بِعِبَادِه[n[ِۦ] خَبِير[i:7707[َۢا ب]َصِيرًا","Албатта, Роббинг ризқни кимга хоҳласа, кенг қилур ёки тор қилур. Албатта, у бандаларидан хабардор ва кўргувчи зотдир.",285,15],["وَلَا تَ[q:2734[قْ]تُل[o[ُوٓ][s[اْ] أَوْلَ[n[ـٰ]دَكُمْ خَشْيَةَ إِمْلَ[n[ـٰ][a:4520[قٍ‌ۖ ن]َّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ‌ۚ إِ[g[نّ]َ قَتْلَهُمْ كَانَ خِ[q:7739[طْ]ـ[f:7740[ـًٔا ك]َبِيرًا","Болаларингизни фақирликдан қўрқиб ўлдирманг. Биз уларни ҳам, сизларни ҳам ризқлантирамиз. Албатта, уларни ўлдириш катта хатодир.",285,15],["وَلَا تَ[q:2802[قْ]رَبُو[s[اْ] [h:7741[ٱ][l[ل]زِّنَ[o[ىٰٓ‌ۖ] إِ[g[نّ]َهُ[n[ۥ] كَانَ فَ[n[ـٰ]حِشَ[a:7742[ةً و]َس[o[َا]ٓءَ سَبِيلاً","Ва зинога яқинлашманглар. Албатта, у фоҳиша иш ва ёмон йўлдир.",285,15],["وَلَا تَ[q:2734[قْ]تُلُو[s[اْ] [h:4522[ٱ][l[ل][g[نّ]َفْسَ [h:4523[ٱ]لَّتِى حَرَّمَ [h:3706[ٱ]للَّهُ إِلَّا بِ[h:370[ٱ]لْحَقِّ‌ۗ وَمَ[f:7743[ن ق]ُتِلَ مَظْلُو[f:7744[مًا ف]َقَ[q:563[دْ] جَعَلْنَا لِوَلِيِّه[n[ِۦ] سُلْطَ[n[ـٰ][f:7745[نًا ف]َلَا يُسْرِف فِّى [h:7746[ٱ]لْقَتْلِ‌ۖ إِ[g[نّ]َهُ[n[ۥ] كَانَ مَ[f:7747[نص]ُورًا","Аллоҳ ҳаром қилган жонни ўлдирманг. Магар ҳақ ила бўлса, майли. Кимки мазлум ҳолида ўлдирилса, унинг валийсига ҳақ берганмиз. Бас, у ўлдиришда исроф қилмасин. Албатта, у нусрат берилган одамдир.",285,15],["وَلَا تَ[q:2802[قْ]رَبُو[s[اْ] مَالَ [h:4525[ٱ]لْيَتِيمِ إِلَّا بِ[h:4526[ٱ]لَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَ[q:1053[بْ]لُغَ أَشُدَّهُ[n[ۥ]‌ۚ وَأَوْفُو[s[اْ] بِ[h:7748[ٱ]لْعَهْدِ‌ۖ إِ[g[نّ]َ [h:7749[ٱ]لْعَهْدَ كَانَ مَسْــُٔولاً","Етимнинг молига, токи у балоғат ёшига етгунча, яқинлашманглар. Магар яхшилик ила бўлса, майли. Аҳдга вафо қилинглар. Албатта, аҳд масъул бўлган ишдир.",285,15],["وَأَوْفُو[s[اْ] [h:4527[ٱ]لْكَيْلَ إِذَا كِلْتُمْ وَزِنُو[s[اْ] بِ[h:7750[ٱ]لْقِسْطَاسِ [h:7751[ٱ]لْمُسْتَقِيمِ‌ۚ ذ[n[َٲ]لِكَ خَيْ[a:2869[رٌ و]َأَحْسَنُ تَأْوِيلاً","Ўлчаган чоғингизда тўлиқ ўлчанг ва тўғри тарози ила тортинг. Ана ўша яхшидир ва оқибати гўзалдир.",285,15],["وَلَا تَ[q:7752[قْ]فُ مَا لَيْسَ لَكَ بِه[n[ِۦ] عِلْمٌ‌ۚ إِ[g[نّ]َ [h:7753[ٱ][l[ل]سَّمْعَ وَ[h:7754[ٱ]لْبَصَرَ وَ[h:7755[ٱ]لْفُؤَادَ كُلُّ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ كَانَ عَنْهُ مَسْــُٔولاً","Ўзинг билмаган нарсага эргашма! Албатта, қулоқ, кўз ва дил — ана ўшалар, масъулдирлар.",285,15],["وَلَا تَمْشِ فِى [h:44[ٱ]لْأَرْضِ مَرَحًا‌ۖ إِ[g[نّ]َكَ لَ[f:7756[ن ت]َخْرِقَ [h:7757[ٱ]لْأَرْضَ وَلَ[f:7758[ن ت]َ[q:7759[بْ]لُغَ [h:7760[ٱ]لْجِبَالَ طُولاً","Ер юзида кибру ҳаво ила юрма! Албатта, сен зинҳор ерни тешиб юбора олмайсан ва зинҳор бўйда тоғларга ета олмассан!",285,15],["كُلُّ ذ[n[َٲ]لِكَ كَانَ سَيِّئُهُ[n[ۥ] عِ[f:264[ند]َ رَبِّكَ مَكْرُوهًا","Буларнинг барча ёмони Роббининг ҳузурида хуш кўрилмагандир.",285,15],["ذ[n[َٲ]لِكَ مِ[g[مّ][o[َآ] أَوْحَ[o[ىٰٓ] إِلَيْكَ رَبُّكَ مِنَ [h:7761[ٱ]لْحِكْمَةِ‌ۗ وَلَا تَ[q:7716[جْ]عَلْ مَعَ [h:3975[ٱ]للَّهِ إِلَ[n[ـٰ]هًا ءَاخَرَ فَتُلْقَىٰ فِى جَهَ[g[نّ]َمَ مَلُو[a:7762[مًا م]َّ[q:4617[دْ]حُورًا","Ушбулар Роббинг сенга ваҳий қилган баъзи ҳикматлардир. Аллоҳ билан бирга ўзга илоҳ қилма. Яна жаҳаннамга маломат қилинган ва қувилган ҳолингда ташланмагин.",286,15],["أَفَأَصْفَ[n[ـٰ]كُمْ رَبُّك[c:7763[ُم ب]ِ[h:7764[ٱ]لْبَنِينَ وَ[h:3162[ٱ]تَّخَذَ مِنَ [h:2217[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ إِنَ[n[ـٰ]ثًا‌ۚ إِ[g[نّ]َكُمْ لَتَقُولُونَ قَوْلاً عَظِيمًا","Роббингиз сизларга ўғилларни хос қилиб бериб, фаришталарни ўзига қиз қилиб олдими? Албатта, сизлар зўр гапни айтмоқдасизлар.",286,15],["وَلَقَ[q:341[دْ] صَرَّفْنَا فِى هَ[n[ـٰ]ذَا [h:7765[ٱ]لْقُرْءَانِ لِيَذَّكَّرُو[s[اْ] وَمَا يَزِيدُهُمْ إِلَّا نُفُورًا","Батаҳқиқ, Биз бу Қуръонда эслашлари учун баён қилдик. Лекин бу уларга нафратдан ўзгани зиёда қилмас.",286,15],["قُل لَّوْ كَانَ مَعَهُ[o[ۥٓ] ءَالِهَ[f:7766[ةٌ ك]َمَا يَقُولُونَ إِ[u:7767[ذًا ل]َّ[h:7768[ٱ][q:7768[بْ]تَغَوْ[s[اْ] إِلَىٰ ذِى [h:7769[ٱ]لْعَرْشِ سَبِيلاً","Сен: «Агар, улар айтганидек, У билан бирга бошқа илоҳлар бўлганида, улар Арш эгаси томон йўл излардилар», деб айт.",286,15],["سُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ] وَتَعَ[n[ـٰ]لَىٰ عَ[g[مّ]َا يَقُولُونَ عُلُو[f:7661[ًّا ك]َبِيرًا","У зот улар айтаётган нарсадан пок ва ниҳоятда олийдир.",286,15],["تُسَبِّحُ لَهُ [h:7770[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تُ [h:7771[ٱ][l[ل]سَّ[q:7772[بْ]عُ وَ[h:2241[ٱ]لْأَرْضُ وَمَ[f:7773[ن ف]ِيهِ[g[نّ]َ‌ۚ وَإ[a:3281[ِن م]ِّ[f:2103[ن ش]َىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِه[n[ِۦ] وَلَ[n[ـٰ]ك[u:46[ِن ل]َّا تَفْقَهُونَ تَسْبِيحَهُمْ‌ۗ إِ[g[نّ]َهُ[n[ۥ] كَانَ حَلِيمًا غَفُورًا","Унга етти осмону ер ва улардаги кимсалар тасбеҳ айтур. Унинг ҳамди ила тасбеҳ айтмаган ҳеч бир нарса йўқ. Лекин уларнинг тасбеҳини англамассизлар. Албатта, у ҳалийм ва сермағфират зотдир.",286,15],["وَإِذَا قَرَأْتَ [h:7580[ٱ]لْقُرْءَانَ جَعَلْنَا بَيْنَكَ وَبَيْنَ [h:7774[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ حِجَا[a:7775[بًا م]َّسْتُورًا","Қачон Қуръон қироат қилсанг, сен билан охиратга иймон келтирмайдиганлар орасида кўринмас парда қилурмиз.",286,15],["وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِ[g[نّ]َةً أ[a:3987[َن ي]َفْقَهُوهُ وَف[o[ِىٓ] ءَاذَانِهِمْ وَ[q:3988[قْ][a:7776[رًا‌ۚ و]َإِذَا ذَكَرْتَ رَبَّكَ فِى [h:7777[ٱ]لْقُرْءَانِ وَحْدَهُ[n[ۥ] وَلَّوْ[s[اْ] عَلَ[o[ىٰٓ] أَ[q:7778[دْ]بَ[n[ـٰ]رِهِمْ نُفُورًا","Ва қалбларига уни англамасликлари учун ғилоф қилдик ва қулоқларини кар қилдик. Қачон сен Қуръонда Роббингнинг ёлғиз ўзини зикр қилсанг, улар ортларига ўгирилиб қочурлар.",286,15],["نَّحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِه[o[ِۦٓ] إِذْ يَسْتَمِعُونَ إِلَيْكَ وَإِذْ هُمْ نَ[q:7779[جْ]وَ[o[ىٰٓ] إِذْ يَقُولُ [h:7780[ٱ][l[ل]ظَّ[n[ـٰ]لِمُونَ إِ[f:4511[ن ت]َتَّبِعُونَ إِلَّا رَجُل[a:7781[اً م]َّسْحُورًا","Биз улар нима сабабдан тинглаётганларини, улар сени тинглаётганларида ўзаро пичирлашаётганларини, золимларнинг: «Сизлар сеҳрланган кишига эргашяпсиз, холос», деганларини ҳам яхши билурмиз.",286,15],["ٱ[f:2837[نظ]ُرْ كَيْفَ ضَرَبُو[s[اْ] لَكَ [h:7782[ٱ]لْأَمْثَالَ فَضَلُّو[s[اْ] فَلَا يَسْتَطِيعُونَ سَبِيلاً","Улар сенга қандай мисол келтирганларига назар сол! Бас, залолатга кетдилар ва йўлга қодир бўлмаслар.",286,15],["وَقَال[o[ُوٓ][s[اْ] أَءِذَا كُ[g[نّ]َا عِظَ[n[ـٰ][a:7783[مًا و]َرُفَ[n[ـٰ]تًا أَءِ[g[نّ]َا لَمَ[q:7784[بْ]عُوثُونَ خَلْ[f:7785[قًا ج]َدِيدًا","Улар: «Суяк ва титилган тупроқ бўлганимиздан кейин ҳам, яна янгидан яратилиб тирилтириламизми?» дедилар.",286,15],["۞ قُلْ كُونُو[s[اْ] حِجَارَةً أَوْ حَدِيدًا","Сен: «Тош ёки темир бўлиб олинглар.",287,15],["أَوْ خَلْ[a:7786[قًا م]ِّ[g[مّ]َا يَكْبُرُ فِى صُدُورِكُمْ‌ۚ فَسَيَقُولُونَ م[a:7787[َن ي]ُعِيدُنَا‌ۖ قُلِ [h:7788[ٱ]لَّذِى فَطَرَكُمْ أَوَّلَ مَرَّ[f:7789[ةٍ‌ۚ ف]َسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ‌ۖ قُلْ عَسَ[o[ىٰٓ] أ[a:3312[َن ي]َكُونَ قَرِيبًا","Ёки кўнгилларингизда катта кўринган бошқа бирон махлуқ бўлиб олинглар», деб айт. Бас, улар: «Бизни ким қайта тирилтирур», дерлар. Сен: «Сизларни биринчи марта йўқдан бор қилган Зот», дегин. Улар сенга бошларини қимирлатурлар ва: «У қачон бўлур?» дерлар, Сен: «Шояд яқинда бўлса», дегин.",287,15],["يَوْمَ يَ[q:2332[دْ]عُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِه[n[ِۦ] وَتَظُ[g[نّ]ُونَ إ[u:7790[ِن ل]َّبِثْتُمْ إِلَّا قَلِيلاً","У кунда У зот сизни чақирур. Бас, сиз Унга ҳамд ила жавоб берурсиз ва фақат озгина турганлигингизни гумон қилурсиз.",287,15],["وَقُل لِّعِبَادِى يَقُولُو[s[اْ] [h:7791[ٱ]لَّتِى هِىَ أَحْسَنُ‌ۚ إِ[g[نّ]َ [h:4634[ٱ][l[ل]شَّيْطَ[n[ـٰ]نَ يَ[f:7792[نز]َغُ بَيْنَهُمْ‌ۚ إِ[g[نّ]َ [h:4634[ٱ][l[ل]شَّيْطَ[n[ـٰ]نَ كَانَ لِلْإِ[f:6549[نس]َ[n[ـٰ]نِ عَدُو[a:3082[ًّا م]ُّبِينًا","Бандаларимга айтгин, улар энг гўзал бўлган нарсани айтсинлар. Албатта, шайтон ораларини бузиб турадир. Албатта, шайтон инсон учун очиқ-ойдин душмандир.",287,15],["رَّبُّكُمْ أَعْلَمُ بِكُمْ‌ۖ إ[a:3197[ِن ي]َشَأْ يَرْحَمْكُمْ أَوْ إ[a:3197[ِن ي]َشَأْ يُعَذِّ[q:5585[بْ]كُمْ‌ۚ وَم[o[َآ] أَرْسَلْنَ[n[ـٰ]كَ عَلَيْهِمْ وَكِيلاً","Роббингиз сизларни яхши билгувчи зотдир. Хоҳласа, сизга раҳм қилар, хоҳласа сизни азоблар. Ва Биз сени улар устидан қўриқчи қилиб юборганимиз йўқ.",287,15],["وَرَبُّكَ أَعْلَمُ بِمَ[f:7793[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۗ وَلَقَ[q:341[دْ] فَضَّلْنَا بَعْضَ [h:7794[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ عَلَىٰ بَعْ[a:7795[ضٍ‌ۖ و]َءَاتَيْنَا دَاوُ[n[ۥ]دَ زَبُورًا","Роббинг осмонлару ердаги кимсаларни яхши билгувчи зотдир. Батаҳқиқ, Биз баъзи Пайғамбарларни баъзиларидан афзал қилдик. Ва Довудга Забурни бердик.",287,15],["قُلِ [h:5199[ٱ][q:4751[دْ]عُو[s[اْ] [h:7796[ٱ]لَّذِينَ زَعَمْت[w:7797[ُم م]ِّ[f:3136[ن د]ُونِه[n[ِۦ] فَلَا يَمْلِكُونَ كَشْفَ [h:7798[ٱ][l[ل]ضُّرِّ عَ[f:255[نك]ُمْ وَلَا تَحْوِيلاً","Сен: «Ундан ўзга ўзингизча гумон қилганларингизни чақиринг. Бас, улар сиздан зарарни кушойиш қила олишга ёки буриб юборишга молик эмаслар», деб айт.",287,15],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ يَ[q:1240[دْ]عُونَ يَ[q:3357[بْ]تَغُونَ إِلَىٰ رَبِّهِمُ [h:7799[ٱ]لْوَسِيلَةَ أَيُّهُمْ أَ[q:1355[قْ]رَبُ وَيَرْجُونَ رَحْمَتَهُ[n[ۥ] وَيَخَافُونَ عَذَابَهُ[o[ۥٓ‌ۚ] إِ[g[نّ]َ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا","Ана ўша дуо қилаётганлари Роббиларига васила изларлар, қайсилари яқинроқ эканини. Унинг раҳматини орзу қилурлар ва азобидан қўрқурлар. Албатта, Роббингнинг азоби ҳазир бўлишга лойиқдир.",287,15],["وَإ[a:3281[ِن م]ِّ[f:4585[ن ق]َرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَ[q:3282[بْ]لَ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ أَوْ مُعَذِّبُوهَا عَذَا[f:1966[بًا ش]َدِي[f:7800[دًا‌ۚ ك]َانَ ذ[n[َٲ]لِكَ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ مَسْطُورًا","Ҳеч бир шаҳар йўқки, биз уни қиёмат кунидан аввал ҳалок қилгувчи бўлмасак ёки шиддатли азоб-ла азобловчи бўлмасак. Бу китобда битилгандир.",287,15],["وَمَا مَنَعَن[o[َآ] أ[a:7801[َن ن]ُّرْسِلَ بِ[h:7802[ٱ]لْأَيَ[n[ـٰ]تِ إِلّ[o[َآ] أَ[f:7803[ن ك]َذَّبَ بِهَا [h:7804[ٱ]لْأَوَّلُونَ‌ۚ وَءَاتَيْنَا ثَمُودَ [h:7805[ٱ][l[ل][g[نّ]َاقَةَ مُ[q:7692[بْ]صِرَ[f:7806[ةً ف]َظَلَمُو[s[اْ] بِهَا‌ۚ وَمَا نُرْسِلُ بِ[h:7802[ٱ]لْأَيَ[n[ـٰ]تِ إِلَّا تَخْوِيفًا","Бизни оят-мўъжизаларни юборишимиздан фақат аввалгиларнинг уларни ёлғонга чиқарганлари ман қилди. Самудга туяни кўз очувчи қилиб бердик. Бас, унинг сабабидан зулм қилдилар. Биз оят-мўъжизаларни фақат қўрқитиш учунгина юборурмиз.",288,15],["وَإِذْ قُلْنَا لَكَ إِ[g[نّ]َ رَبَّكَ أَحَاطَ بِ[h:743[ٱ][l[ل][g[نّ]َاسِ‌ۚ وَمَا جَعَلْنَا [h:7807[ٱ][l[ل]رُّءْيَا [h:7808[ٱ]لَّت[o[ِىٓ] أَرَيْنَ[n[ـٰ]كَ إِلَّا فِتْنَ[u:7809[ةً ل]ِّل[g[نّ]َاسِ وَ[h:7810[ٱ][l[ل]شَّجَرَةَ [h:7811[ٱ]لْمَلْعُونَةَ فِى [h:7777[ٱ]لْقُرْءَانِ‌ۚ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمْ إِلَّا طُغْيَ[n[ـٰ][f:7812[نًا ك]َبِيرًا","Биз сенга: «Албатта, Роббинг одамларни иҳота қилиб ўраб олгандир», деганимизни эсла. Биз сенга кўрсатган нарсаларни ва Қуръонда лаънатланган дарахтни фақат одамлар учун синов қилдик, холос. Ва уларни қўрқитамиз. Бас, бу улар учун катта туғёндан бошқани зиёда қилмас.",288,15],["وَإِذْ قُلْنَا لِلْمَلَ[o[ـٰٓ]ئِكَةِ [h:179[ٱ]سْجُدُو[s[اْ] لِأَدَمَ فَسَجَد[o[ُوٓ][s[اْ] إِلّ[o[َآ] إِ[q:180[بْ]لِيسَ قَالَ ءَأَسْجُدُ لِمَنْ خَلَ[q:2500[قْ]تَ طِينًا","Фаришталарга: «Одамга сажда қилинглар!» деганимизда сажда қилганларини, магар иблис қилмаганини, «Сен лойдан яратган кимсага сажда қиламанми?» деганини эсла.",288,15],["قَالَ أَرَءَيْتَكَ هَ[n[ـٰ]ذَا [h:126[ٱ]لَّذِى كَرَّمْتَ عَلَىَّ لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ لَأَحْتَنِكَ[g[نّ]َ ذُرِّيَّتَهُ[o[ۥٓ] إِلَّا قَلِيلاً","У: «Менга хабар бер-чи, мендан устун қилганинг шуми? Агар мени қиёмат кунигача қўйиб қўйсанг, унинг зурриётининг озгинасидан бошқасини жиловлаб оламан», деди.",288,15],["قَالَ [h:7813[ٱ]ذْهَ[q:7814[بْ] فَمَ[f:7815[ن ت]َبِعَكَ مِنْهُمْ فَإِ[g[نّ]َ جَهَ[g[نّ]َمَ جَز[o[َا]ٓؤُكُمْ جَز[o[َا]ٓ[a:7816[ءً م]َّوْفُورًا","У зот: «Боравер, улардан ким сенга эргашса, бас, албатта, жаҳаннам тўлиқ жазоингиз бўлур.",288,15],["وَ[h:9999[ٱ]سْتَفْزِزْ مَنِ [h:7817[ٱ]سْتَطَعْتَ مِنْه[c:7818[ُم ب]ِصَوْتِكَ وَأَ[q:7819[جْ]لِ[q:7819[بْ] عَلَيْه[c:7820[ِم ب]ِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِى [h:7821[ٱ]لْأَمْو[n[َٲ]لِ وَ[h:7822[ٱ]لْأَوْلَ[n[ـٰ]دِ وَعِ[q:7823[دْ]هُمْ‌ۚ وَمَا يَعِدُهُمُ [h:3147[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ إِلَّا غُرُورًا","Улардан кимига кучинг етса, овозинг ила қўзғат, уларнинг устига отлиқ ва пиёда аскарингни торт, уларга молларда ва болаларда шерик бўл ва ваъдалар қил. Шайтон уларга ғурурдан бошқани ваъда қилмайдир.",288,15],["إِ[g[نّ]َ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَ[n[ـٰ][a:7824[نٌ‌ۚ و]َكَفَىٰ بِرَبِّكَ وَكِيلاً","Албатта, Менинг бандаларим устидан сенинг султонинг йўқ. Роббингнинг Ўзи вакилликка кифоядир», деди.",288,15],["رَّبُّكُمُ [h:7825[ٱ]لَّذِى يُزْجِى لَكُمُ [h:7131[ٱ]لْفُلْكَ فِى [h:837[ٱ]لْبَحْرِ لِتَ[q:7694[بْ]تَغُو[s[اْ] مِ[f:475[ن ف]َضْلِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] كَانَ بِكُمْ رَحِيمًا","Роббингиз, Унинг фазлидан талаб қилишингиз учун денгизда кемани юргизиб қўйган зотдир. Албатта, У сизга раҳмлидир.",288,15],["وَإِذَا مَسَّكُمُ [h:7435[ٱ][l[ل]ضُّرُّ فِى [h:837[ٱ]لْبَحْرِ ضَلَّ مَ[f:7826[ن ت]َ[q:4040[دْ]عُونَ إِلّ[o[َآ] إِيَّاهُ‌ۖ فَلَ[g[مّ]َا نَجَّ[n[ـٰ]كُمْ إِلَى [h:7827[ٱ]لْبَرِّ أَعْرَضْتُمْ‌ۚ وَكَانَ [h:7688[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ كَفُورًا","Қачон сизни денгизда фалокат тутса, Ундан ўзга илтижо қиладиганларингиз ғойиб бўлур. Қачонки сизга нажот бериб қуруқликка чиқарса, юз ўгирасиз. Инсон ўзи куфрон қилгувчидир.",289,15],["أَفَأَمِ[f:7828[نت]ُمْ أ[a:7417[َن ي]َخْسِفَ بِكُمْ جَانِبَ [h:7829[ٱ]لْبَرِّ أَوْ يُرْسِلَ عَلَيْكُمْ حَاصِ[f:7830[بًا ث]ُ[g[مّ]َ لَا تَجِدُو[s[اْ] لَكُمْ وَكِيلاً","Сизни қуруқликнинг бир томонига ютқазиб юборишидан ёки устингиздан тошли шамол юборишидан, сўнгра ўзингизга қутқарувчи топа олмай қолишингиздан хотиржаммисиз?!",289,15],["أَمْ أَمِ[f:1062[نت]ُمْ أ[a:7831[َن ي]ُعِيدَكُمْ فِيهِ تَارَةً أُخْرَىٰ فَيُرْسِلَ عَلَيْكُمْ قَاصِ[a:7832[فًا م]ِّنَ [h:7833[ٱ][l[ل]رِّيحِ فَيُغْرِقَك[c:7834[ُم ب]ِمَا كَفَرْتُمْ‌ۙ ثُ[g[مّ]َ لَا تَجِدُو[s[اْ] لَكُمْ عَلَيْنَا بِه[n[ِۦ] تَبِيعًا","Ёки сизни уга яна бир марта қайтариб, устингиздан шиддатли шамол юбориб, куфр қилган нарсангиз сабабли ғарқ қилиб юборишидан ва сиз ўзингизга Биздан ўч олувчи топа олмай қолишингиздан хотиржаммисиз?!",289,15],["۞ وَلَقَ[q:341[دْ] كَرَّمْنَا بَن[o[ِىٓ] ءَادَمَ وَحَمَلْنَ[n[ـٰ]هُمْ فِى [h:4106[ٱ]لْبَرِّ وَ[h:4107[ٱ]لْبَحْرِ وَرَزَ[q:6191[قْ]نَ[n[ـٰ]ه[w:6192[ُم م]ِّنَ [h:5307[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تِ وَفَضَّلْنَ[n[ـٰ]هُمْ عَلَىٰ كَثِي[a:7835[رٍ م]ِّ[g[مّ]َنْ خَلَ[q:5159[قْ]نَا تَفْضِيلاً","Батаҳқиқ, Биз Бани Одамни азизу мукаррам қилиб қўйдик ва уларни қуруқлигу денгизда кўтардик ҳамда уларни пок нарсалар ила ризқлантирдик ва уни Ўзимиз яратган кўп нарсалардан мутлақо афзал қилиб қўйдик.",289,15],["يَوْمَ نَ[q:7542[دْ]عُو[s[اْ] كُلَّ أُنَا[i:7836[سِۭ ب]ِإِمَ[n[ـٰ]مِهِمْ‌ۖ فَمَنْ أُوتِىَ كِتَ[n[ـٰ]بَهُ[n[ۥ] بِيَمِينِه[n[ِۦ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يَ[q:6198[قْ]رَءُونَ كِتَ[n[ـٰ]بَهُمْ وَلَا يُظْلَمُونَ فَتِيلاً","Биз барча одамларни ўз имомлари ила чақирадиган кунни. Кимга китоби ўнг томонидан берилса, бас, ана ўшалар китобларини ўқирлар ва уларга қилчалик зулм қилинмас.",289,15],["وَمَ[f:975[ن ك]َانَ فِى هَ[n[ـٰ]ذِه[o[ِۦٓ] أَعْمَىٰ فَهُوَ فِى [h:536[ٱ]لْأَخِرَةِ أَعْمَىٰ وَأَضَلُّ سَبِيلاً","Ким бу дунёда кўр-гумроҳ бўлса, у охиратда янада кўр-гумроҳ ва янада йўлдан адашганроқ бўлади.",289,15],["وَإِ[f:7837[ن ك]َادُو[s[اْ] لَيَفْتِنُونَكَ عَنِ [h:7838[ٱ]لَّذ[o[ِىٓ] أَوْحَيْن[o[َآ] إِلَيْكَ لِتَفْتَرِىَ عَلَيْنَا غَيْرَهُ[n[ۥ]‌ۖ وَإِ[u:7839[ذًا ل]َّ[h:7840[ٱ]تَّخَذُوكَ خَلِيلاً","Сени Биз ваҳий қилган нарсадан фитна орқали буриб, Бизнинг шаънимизга бошқасини уйдиришингга ундашларига оз қолди. Шундай бўлган тақдирда, албатта, сени дўст тутар эдилар.",289,15],["وَلَوْل[o[َآ] أَ[f:7841[ن ث]َبَّتْنَ[n[ـٰ]كَ لَقَ[q:2389[دْ] كِ[d:7842[د]تَّ تَرْكَنُ إِلَيْهِمْ شَيْـ[f:7843[ـًٔا ق]َلِيلاً","Агар Биз сени собит қилмаганимизда, батаҳқиқ, уларга бир оз бўлса-да, мойил бўлишингга оз қолар эди.",289,15],["إِ[u:7844[ذًا ل]َّأَذَ[q:7845[قْ]نَ[n[ـٰ]كَ ضِعْفَ [h:7846[ٱ]لْحَيَ[s[و][n[ٲ]ةِ وَضِعْفَ [h:7847[ٱ]لْمَمَاتِ ثُ[g[مّ]َ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيرًا","Шундай бўлган тақдирда биз сенга ҳаёт ҳам икки ҳисса, мамот ҳам икки ҳисса тоттирган бўлардик. Сўнгра Ўзинг учун бизга қарши ёрдамчи топа олмас эдинг.",289,15],["وَإِ[f:7837[ن ك]َادُو[s[اْ] لَيَسْتَفِزُّونَكَ مِنَ [h:1579[ٱ]لْأَرْضِ لِيُخْرِجُوكَ مِنْهَا‌ۖ وَإِ[u:7848[ذًا ل]َّا يَلْبَثُونَ خِلَ[n[ـٰ]فَكَ إِلَّا قَلِيلاً","Улар сени бу ерда безовта қилиб, ундан сени чиқариб юборишларига оз қолди. Шундай бўлган тақдирда, сендан кейин улар озгина муддатдан бошқа тура олмаслар.",290,15],["سُ[g[نّ]َةَ مَ[f:6316[ن ق]َ[q:298[دْ] أَرْسَلْنَا قَ[q:7849[بْ]لَكَ م[u:7850[ِن ر]ُّسُلِنَا‌ۖ وَلَا تَجِدُ لِسُ[g[نّ]َتِنَا تَحْوِيلاً","Бу сендан олдин юборган Пайғамбарларимизнинг суннатидир. Бизнинг сунннатимизга ўзгартиш топа олмайссан.",290,15],["أَقِمِ [h:7851[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ لِدُلُوكِ [h:7852[ٱ][l[ل]شَّمْسِ إِلَىٰ غَسَقِ [h:7853[ٱ]لَّيْلِ وَقُرْءَانَ [h:7854[ٱ]لْفَ[q:996[جْ]رِ‌ۖ إِ[g[نّ]َ قُرْءَانَ [h:7855[ٱ]لْفَ[q:996[جْ]رِ كَانَ مَشْهُودًا","Қуёш оғишидан то кун қоронғусигача намозни тўкис адо қил. «Фажр Қуръони»ни ҳам. Албатта, «фажр Қуръони» гувоҳлантирилгандир.",290,15],["وَمِنَ [h:7856[ٱ]لَّيْلِ فَتَهَجَّ[q:7857[دْ] بِه[n[ِۦ] نَافِلَ[u:7858[ةً ل]َّكَ عَسَ[o[ىٰٓ] أ[a:7859[َن ي]َ[q:7860[بْ]عَثَكَ رَبُّكَ مَقَا[a:7861[مًا م]َّحْمُودًا","Кечанинг баъзисида у ила бедор бўл. Сенга нофила бўлсин. Шоядки Роббинг сени мақтовли мақомда тирилтирса.",290,15],["وَقُ[b:7725[ل] رَّبِّ أَ[q:7862[دْ]خِلْنِى مُ[q:7863[دْ]خَلَ صِ[q:5937[دْ][a:7864[قٍ و]َأَخْرِ[q:7865[جْ]نِى مُخْرَجَ صِ[q:5937[دْ][a:7866[قٍ و]َ[h:2930[ٱ][q:2930[جْ]عَل لِّى م[u:1746[ِن ل]َّدُ[f:1747[نك]َ سُلْطَ[n[ـٰ][a:7867[نًا ن]َّصِيرًا","Ва сен: «Эй Роббим, мени кирадиган жойимга содиқлик ила киритиб, чиқадиган жойимга содиқлик билан чиқаргин ва менга Ўз ҳузурингдан ёрдам берувчи қувват ато эт», дегин.",290,15],["وَقُلْ ج[o[َا]ٓءَ [h:5635[ٱ]لْحَقُّ وَزَهَقَ [h:7868[ٱ]لْبَ[n[ـٰ]طِلُ‌ۚ إِ[g[نّ]َ [h:7869[ٱ]لْبَ[n[ـٰ]طِلَ كَانَ زَهُوقًا","Ва: «Ҳақ келди, ботил йўқ бўлди. Зотан, ботил доимо йўқ бўлгувчидир», дегин.",290,15],["وَنُنَزِّلُ مِنَ [h:7870[ٱ]لْقُرْءَانِ مَا هُوَ شِف[o[َا]ٓ[a:7871[ءٌ و]َرَحْمَ[u:6096[ةٌ ل]ِّلْمُؤْمِنِينَ‌ۙ وَلَا يَزِيدُ [h:7872[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ إِلَّا خَسَارًا","Биз Қуръонни мўминлар учун шифо ва раҳмат ўлароқ нозил қилурмиз. У золимларга зиёндан бошқани зиёда қилмас.",290,15],["وَإِذ[o[َآ] أَنْعَمْنَا عَلَى [h:7873[ٱ]لْإِ[f:7874[نس]َ[n[ـٰ]نِ أَعْرَضَ وَنَـَٔـا بِجَانِبِه[n[ِۦ]‌ۖ وَإِذَا مَسَّهُ [h:7875[ٱ][l[ل]شَّرُّ كَانَ يَــُٔوسًا","Қачон Биз инсонга неъмат ато этсак, юз ўгирур ва четга бурилиб, узоқлашур. Қачон уни ёмонлик тутса, ноумид бўлур.",290,15],["قُلْ كُ[a:7876[لٌّ ي]َعْمَلُ عَلَىٰ شَاكِلَتِه[n[ِۦ] فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلاً","Сен: «Ҳар ким ўз ҳолича амал қилур. Бас, Роббингиз ким тўғри йўлдалигини яхши билгувчидир», деб айт.",290,15],["وَيَسْــَٔلُونَكَ عَنِ [h:7877[ٱ][l[ل]رُّوحِ‌ۖ قُلِ [h:7878[ٱ][l[ل]رُّوحُ مِنْ أَمْرِ رَبِّى وَم[o[َآ] أُوتِيت[w:7879[ُم م]ِّنَ [h:634[ٱ]لْعِلْمِ إِلَّا قَلِيلاً","Ва сендан руҳ ҳақида сўрарлар. Сен: «Руҳ Роббимнинг ишидир. Сизга жуда оз илм берилгандир», деб айт.",290,15],["وَلَئِ[f:7880[ن ش]ِئْنَا لَنَذْهَبَ[g[نّ]َ بِ[h:315[ٱ]لَّذ[o[ِىٓ] أَوْحَيْن[o[َآ] إِلَيْكَ ثُ[g[مّ]َ لَا تَجِدُ لَكَ بِه[n[ِۦ] عَلَيْنَا وَكِيلاً","Агар хоҳласак, сенга ваҳий қилган нарсаларимизни кетказамиз. Сўнгра бизга қарши ўзингга вакил топа олмассан.",290,15],["إِلَّا رَحْمَ[a:5993[ةً م]ّ[u:770[ِن ر]َّبِّكَ‌ۚ إِ[g[نّ]َ فَضْلَهُ[n[ۥ] كَانَ عَلَيْكَ كَبِيرًا","Магар Аллоҳда марҳамат бўлсагина. Албатта, Унинг фазлу карами сен учун каттадир.",291,15],["قُل لَّئِنِ [h:7881[ٱ][q:7882[جْ]تَمَعَتِ [h:7883[ٱ]لْإِ[f:7884[نس]ُ وَ[h:7885[ٱ]لْجِ[g[نّ]ُ عَلَ[o[ىٰٓ] أ[a:3855[َن ي]َأْتُو[s[اْ] بِمِثْلِ هَ[n[ـٰ]ذَا [h:7765[ٱ]لْقُرْءَانِ لَا يَأْتُونَ بِمِثْلِه[n[ِۦ] وَلَوْ كَانَ بَعْضُهُمْ لِبَعْ[f:7886[ضٍ ظ]َهِيرًا","Агар инсу жинлар тўпланиб, ушбу Қуръонга ўхшаш нарса келтирмоқчи бўлсалар, бунда баъзилари баъзиларга ёрдамчи бўлсалар ҳам, унга ўхшашини келтира олмаслар.",291,15],["وَلَقَ[q:341[دْ] صَرَّفْنَا لِل[g[نّ]َاسِ فِى هَ[n[ـٰ]ذَا [h:7765[ٱ]لْقُرْءَانِ مِ[f:843[ن ك]ُلِّ مَثَ[f:7887[لٍ ف]َأَبَ[o[ىٰٓ] أَكْثَرُ [h:6838[ٱ][l[ل][g[نّ]َاسِ إِلَّا كُفُورًا","Батаҳқиқ, ушбу Қуръонда одамларга турли мисолларни баён қилдик. Бас, одамларнинг кўплари куфрдан бошқа нарсадан бош тортдилар.",291,15],["وَقَالُو[s[اْ] ل[a:265[َن ن]ُّؤْمِنَ لَكَ حَتَّىٰ تَفْجُرَ لَنَا مِنَ [h:1579[ٱ]لْأَرْضِ يَ[i:7888[نۢب]ُوعًا","Улар: «Токи бизга ердан чашма отилтирмагунингча зинҳор сенга иймон келтирмасмиз», дедилар.",291,15],["أَوْ تَكُونَ لَكَ جَ[g[نّ]َ[a:1567[ةٌ م]ّ[a:1568[ِن ن]َّخِي[a:7889[لٍ و]َعِنَ[f:7890[بٍ ف]َتُفَجِّرَ [h:7891[ٱ]لْأَنْهَ[n[ـٰ]رَ خِلَ[n[ـٰ]لَهَا تَفْجِيرًا","Ёки сенинг хурмо ва узум боғинг бўлиб, уларнинг орасидан анҳорларини отилтириб чиқармагунингча.",291,15],["أَوْ تُسْقِطَ [h:7892[ٱ][l[ل]سَّم[o[َا]ٓءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِىَ بِ[h:32[ٱ]للَّهِ وَ[h:823[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ قَبِيلاً","Ёки ўзинг даъво қилганингдек, устимиздан осмонни парча-парча қилиб туширмагунингча ёхуд Аллоҳни ва фаришталарни олдимизга келтирмагунингча.",291,15],["أَوْ يَكُونَ لَكَ بَيْ[a:7893[تٌ م]ِّ[f:7894[ن ز]ُخْرُفٍ أَوْ تَرْقَىٰ فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ وَل[a:7895[َن ن]ُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَ[n[ـٰ][a:7896[بًا ن]َّ[q:7897[قْ]رَؤُهُ[n[ۥ]‌ۗ قُلْ سُ[q:7648[بْ]حَانَ رَبِّى هَلْ كُ[f:2917[نت]ُ إِلَّا بَشَ[u:7898[رًا ر]َّسُولاً","Ёки сенинг олтиндан безалган уйинг бўлмагунича, ёхуд осмонга кўтарилмагунингча, ўша кўтарилишингга ҳам токи биз ўқишимиз учун китоб келтирмагунингча, ишонмаймиз»,. Сен: «Роббим пок бўлди. Мен фақат башар Пайғамбардан бошқа нарса эмасман», дегин.",291,15],["وَمَا مَنَعَ [h:7899[ٱ][l[ل][g[نّ]َاسَ أ[a:386[َن ي]ُؤْمِن[o[ُوٓ][s[اْ] إِذْ ج[o[َا]ٓءَهُمُ [h:7900[ٱ]لْهُدَ[o[ىٰٓ] إِلّ[o[َآ] أَ[f:2304[ن ق]َال[o[ُوٓ][s[اْ] أَبَعَثَ [h:7901[ٱ]للَّهُ بَشَ[u:7898[رًا ر]َّسُولاً","Одамларга ҳидоят келган пайтда иймон келтиришларидан манъ қилган нарса фақат, Аллоҳ башардан Пайғамбар юборадими, дейишлари бўлди.",291,15],["قُل لَّوْ كَانَ فِى [h:44[ٱ]لْأَرْضِ مَلَ[o[ـٰٓ]ئِكَ[a:7902[ةٌ ي]َمْشُونَ مُ[q:7903[طْ]مَئِ[g[نّ]ِينَ لَنَزَّلْنَا عَلَيْه[w:2901[ِم م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ مَلَ[u:7904[كًا ر]َّسُولاً","Сен айт: «Агар ер юзида фаришталар хотиржам юрганларида, уларга осмондан фаришта Пайғамбар туширган бўлар эдик».",291,15],["قُلْ كَفَىٰ بِ[h:32[ٱ]للَّهِ شَهِيد[i:7033[َۢا ب]َيْنِى وَبَيْنَكُمْ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ بِعِبَادِه[n[ِۦ] خَبِير[i:7707[َۢا ب]َصِيرًا","Сен: «Мен билан сизнинг орамизда гувоҳликка Аллоҳнинг Ўзи кифоя қилур. Албатта, У Ўз бандаларидан хабардор ва уларни кўриб тургувчи зотдир», деб айт.",291,15],["وَم[a:7905[َن ي]َهْدِ [h:5147[ٱ]للَّهُ فَهُوَ [h:7906[ٱ]لْمُهْتَدِ‌ۖ وَم[a:5149[َن ي]ُضْلِلْ فَلَ[f:2843[ن ت]َجِدَ لَهُمْ أَوْلِي[o[َا]ٓءَ مِ[f:3136[ن د]ُونِه[n[ِۦ]‌ۖ وَنَحْشُرُهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ عَلَىٰ وُجُوهِهِمْ عُمْ[a:7907[يًا و]َبُكْ[a:7908[مًا و]َصُم[a:7909[ًّا‌ۖ م]َّأْوَ[n[ٮٰ]هُمْ جَهَ[g[نّ]َمُ‌ۖ كُلَّمَا خَبَتْ زِ[q:7546[دْ]نَ[n[ـٰ]هُمْ سَعِيرًا","Аллоҳ кимни ҳидоят қилса, ўша ҳидоят топгувчидир. У кимни адаштирса, уларга Ундан ўзга зинҳор валийлар топа олмассан. Уларни қиёмат куни юзтубан, кўр, кар, соқов ҳолларида тўплармиз. Уларнинг турар жойлари жаҳаннамдир. У қачон сокин бўлса, уларга оловни зиёда қилармиз.",292,15],["ذ[n[َٲ]لِكَ جَز[o[َا]ٓؤُه[c:7910[ُم ب]ِأَ[g[نّ]َهُمْ كَفَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا وَقَال[o[ُوٓ][s[اْ] أَءِذَا كُ[g[نّ]َا عِظَ[n[ـٰ][a:7783[مًا و]َرُفَ[n[ـٰ]تًا أَءِ[g[نّ]َا لَمَ[q:7784[بْ]عُوثُونَ خَلْ[f:7785[قًا ج]َدِيدًا","Ана ўша, Бизнинг оятларимизга куфр келтирганлари ва «Агар суяк ва титилган тупроқ бўлсак ҳам, албатта, янгитдан яратилиб, қайта тирилтирилурмизми?!» деганлари учун жазоларидир.",292,15],["۞ أَوَلَمْ يَرَوْ[s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ [h:2537[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ قَادِرٌ عَلَ[o[ىٰٓ] أ[a:7911[َن ي]َخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ أَجَل[u:7912[اً ل]َّا رَيْبَ فِيهِ فَأَبَى [h:7913[ٱ][l[ل]ظَّ[n[ـٰ]لِمُونَ إِلَّا كُفُورًا","Улар осмонлару ерни яратган Аллоҳ уларга ўхшашини яратишга қодир эканини ва улар учун шак-шубҳасиз ажал белгилаганини билмадиларми?! Бас, золимлар куфрдан бошқа нарсадан бош тортдилар.",292,15],["قُل لَّوْ أَ[f:428[نت]ُمْ تَمْلِكُونَ خَز[o[َا]ٓئِنَ رَحْمَةِ رَبّ[o[ِىٓ] إِ[u:7914[ذًا ل]َّأَمْسَكْتُمْ خَشْيَةَ [h:7915[ٱ]لْإِ[f:7916[نف]َاقِ‌ۚ وَكَانَ [h:7688[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ قَتُورًا","Сен: «Агар сизлар Роббим раҳмати хазиналарига эга бўлсангиз ҳам, уни сарфлашдан қўрқиб, мумсиклик қилган бўлар эдингиз. Инсон зоти ўзи бахил бўлур», деб айт.",292,15],["وَلَقَ[q:341[دْ] ءَاتَيْنَا مُوسَىٰ تِسْعَ ءَايَ[n[ـٰ][i:516[تِۭ ب]َيِّنَ[n[ـٰ][f:7917[تٍ‌ۖ ف]َسْــَٔلْ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ إِذْ ج[o[َا]ٓءَهُمْ فَقَالَ لَهُ[n[ۥ] فِرْعَوْنُ إِ[g[نّ]ِى لَأَظُ[g[نّ]ُكَ يَ[n[ـٰ]مُوسَىٰ مَسْحُورًا","Батаҳқиқ, Биз Мусога тўққизта очиқ-ойдин оят-мўъжиза бердик. Бани Исроилдан уларга у келган пайтини ўрагин. Бас, Фиръавн унга: «Албатта, мен сени, эй Мусо, сеҳрлангансан деб ўйлайман», деди.",292,15],["قَالَ لَقَ[q:2389[دْ] عَلِمْتَ م[o[َآ] أَ[f:471[نز]َلَ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ إِلَّا رَبُّ [h:6926[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ بَص[o[َا]ٓئِرَ وَإِ[g[نّ]ِى لَأَظُ[g[نّ]ُكَ يَ[n[ـٰ]فِرْعَوْنُ مَثْبُورًا","У: «Ановиларни кўзни очгувчи қилиб, осмонлару ернинг Роббидан ўзга ҳеч бир зот туширмаганини яхши биласан. Албатта, мен сени, эй Фиръавн, ҳалок бўлгувчисан деб ўйлайман», деди.",292,15],["فَأَرَادَ أ[a:7918[َن ي]َسْتَفِزَّه[w:7919[ُم م]ِّنَ [h:1579[ٱ]لْأَرْضِ فَأَغْرَ[q:7920[قْ]نَ[n[ـٰ]هُ وَم[a:4948[َن م]َّعَهُ[n[ۥ] جَمِيعًا","Бас, уларни ердан қўзғатиб чиқармоқчи бўлди. Шунда биз уни ва у билан бирга бўлганларни жамлаб ғарқ қилдик.",292,15],["وَقُلْنَا م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] لِبَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ [h:7921[ٱ]سْكُنُو[s[اْ] [h:7922[ٱ]لْأَرْضَ فَإِذَا ج[o[َا]ٓءَ وَعْدُ [h:7673[ٱ]لْأَخِرَةِ جِئْنَا بِكُمْ لَفِيفًا","Удан сўнг Бани Исроилга: «Мана шу ерни маскан тутинглар. Бас, охират ваъдаси келган чоғида ҳаммангизни тўплаб келтирурмиз», дедик.",292,15],["وَبِ[h:9999[ٱ]لْحَقِّ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ وَبِ[h:7923[ٱ]لْحَقِّ نَزَلَ‌ۗ وَم[o[َآ] أَرْسَلْنَ[n[ـٰ]كَ إِلَّا مُبَشِّ[a:7924[رًا و]َنَذِيرًا","Уни ҳақ ила нозил қилдик ва ҳақ ила нозил бўлди. Биз сени фақат хушхабар бергувчи ва огоҳлантиргувчи этиб юбордик, холос.",293,15],["وَقُرْءَا[f:7925[نًا ف]َرَ[q:7926[قْ]نَ[n[ـٰ]هُ لِتَ[q:7927[قْ]رَأَهُ[n[ۥ] عَلَى [h:729[ٱ][l[ل][g[نّ]َاسِ عَلَىٰ مُكْ[a:7928[ثٍ و]َنَزَّلْنَ[n[ـٰ]هُ تَ[f:7929[نز]ِيلاً","Ва Қуръонни одамларга аста-секин ўқиб беришинг учун бўлиб қўйдик ва бўлак-бўлак қилиб туширдик.",293,15],["قُلْ ءَامِنُو[s[اْ] بِه[o[ِۦٓ] أَوْ لَا تُؤْمِن[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:7379[ٱ]لْعِلْمَ مِ[f:1097[ن ق]َ[q:1098[بْ]لِه[o[ِۦٓ] إِذَا يُتْلَىٰ عَلَيْهِمْ يَخِرُّونَ لِلْأَذْقَانِ سُجَّدًا","Сен: «Унга иймон келтиринглар ёки иймон келтирманглар барибир. Албатта, ундан олдин илм берилганлар у уларга тиловат қилинганда юзлари ила саждага йиқилурлар», деб айт.",293,15],["وَيَقُولُونَ سُ[q:7648[بْ]حَ[n[ـٰ]نَ رَبِّن[o[َآ] إِ[f:2594[ن ك]َانَ وَعْدُ رَبِّنَا لَمَفْعُولاً","Ва улар: «Роббимиз мутлақо пок бўлди. Шубҳасиз, Роббимизнинг ваъдаси амалга ошажак», дерлар.",293,15],["وَيَخِرُّونَ لِلْأَذْقَانِ يَ[q:6573[بْ]كُونَ وَيَزِيدُهُمْ خُشُوعًا ۩","Ва юзлари ила йиқилиб йиғларлар ва у хокисорликларни зиёда қилур.",293,15],["قُلِ [h:5199[ٱ][q:4751[دْ]عُو[s[اْ] [h:7930[ٱ]للَّهَ أَوِ [h:7931[ٱ][q:4751[دْ]عُو[s[اْ] [h:7932[ٱ][l[ل]رَّحْمَ[n[ـٰ]نَ‌ۖ أَي[a:7933[ًّا م]َّا تَ[q:7934[دْ]عُو[s[اْ] فَلَهُ [h:7935[ٱ]لْأَسْم[o[َا]ٓءُ [h:5156[ٱ]لْحُسْنَىٰ‌ۚ وَلَا تَ[q:7936[جْ]هَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَ[h:7937[ٱ][q:7937[بْ]تَغِ بَيْنَ ذ[n[َٲ]لِكَ سَبِيلاً","Сен: «Аллоҳга дуо қилинглар, Роҳманга дуо қилинглар, қайсисига дуо қилсангиз ҳам, барибир. Гўзал исмлар Уникидир», деб айт. Намозингни жуда баланд овоз ила ўқима, уни жуда махфий ҳам ўқима, бунинг орасида бир йўл тут.",293,15],["وَقُلِ [h:7938[ٱ]لْحَمْدُ لِلَّهِ [h:3912[ٱ]لَّذِى لَمْ يَتَّخِذْ وَلَ[a:7939[دًا و]َلَمْ يَك[u:2596[ُن ل]َّهُ[n[ۥ] شَرِي[f:7940[كٌ ف]ِى [h:7941[ٱ]لْمُلْكِ وَلَمْ يَك[u:2596[ُن ل]َّهُ[n[ۥ] وَلِ[a:7942[ىٌّ م]ِّنَ [h:7943[ٱ][l[ل]ذُّلِّ‌ۖ وَكَبِّرْهُ تَكْبِيرَۢا","Сен: «Ҳамд бўлсин, фарзанд тутмаган, мулкда шериги бўлмаган ва хорликдан қутқаргувчи дўстга зор бўлмаган Аллоҳга», дегин. Ва Уни мутлақо улуғла!",293,15]]},{"n":18,"ar":"الكَهۡفِ","en":"Al-Kahf","uz":"Каҳф","type":"Макка","ayahs":[["ٱلْحَمْدُ لِلَّهِ [h:3912[ٱ]لَّذ[o[ِىٓ] أَ[f:471[نز]َلَ عَلَىٰ عَ[q:7944[بْ]دِهِ [h:7945[ٱ]لْكِتَ[n[ـٰ]بَ وَلَمْ يَ[q:4397[جْ]عَل لَّهُ[n[ۥ] عِوَجَاۜ","Ўз бандасига китоб нозил этган ва унда ҳеч бир эгрилик қилмаган Аллоҳга ҳамд бўлсин.",293,15],["قَيِّ[u:7946[مًا ل]ِّيُ[f:7947[نذ]ِرَ بَأْ[f:7948[سًا ش]َدِي[a:7949[دًا م]ّ[u:2794[ِن ل]َّدُنْهُ وَيُبَشِّرَ [h:7950[ٱ]لْمُؤْمِنِينَ [h:7681[ٱ]لَّذِينَ يَعْمَلُونَ [h:7682[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ أَ[g[نّ]َ لَهُمْ أَ[q:2795[جْ]رًا حَسَنًا","Уни тўғри қилган; Ўз ҳузуридан бўладиган шиддатли азобдан огоҳлантирадиган; яхши амалларни қиладиган мўминларга, уларга гўзал ажр бўлиши башоратини берадиган қилган Зотга.",293,15],["مَّ[n[ـٰ]كِثِينَ فِيهِ أَبَدًا","уда абадий қолгувчидирлар.",293,15],["وَيُ[f:7951[نذ]ِرَ [h:7952[ٱ]لَّذِينَ قَالُو[s[اْ] [h:6120[ٱ]تَّخَذَ [h:606[ٱ]للَّهُ وَلَدًا","Ва, Аллоҳ Ўзига бола тутди, деганларни огоҳлантириш учун.",293,15],["مَّا لَه[c:3276[ُم ب]ِه[n[ِۦ] مِنْ عِلْ[a:7953[مٍ و]َلَا لِأَب[o[َا]ٓئِهِمْ‌ۚ كَبُرَتْ كَلِمَ[f:7954[ةً ت]َخْرُجُ مِنْ أَفْو[n[َٲ]هِهِمْ‌ۚ إ[a:7955[ِن ي]َقُولُونَ إِلَّا كَذِبًا","На уларнинг ва на ота-боболарининг бу ҳақда илми йўқдир. Оғизларидан чиқадиган сўз қандай ҳам оғир. Улар ёлғондан бошқани айтмаслар.",294,15],["فَلَعَلَّكَ بَ[n[ـٰ]خِ[a:7956[عٌ ن]َّفْسَكَ عَلَ[o[ىٰٓ] ءَاثَ[n[ـٰ]رِهِمْ إ[u:2606[ِن ل]َّمْ يُؤْمِنُو[s[اْ] بِهَ[n[ـٰ]ذَا [h:7957[ٱ]لْحَدِيثِ أَسَفًا","Улар бу сўзга иймон келтирмасалар, эҳтимол уларнинг ортидан таассуф ила ўзингни ҳалок этмоқчи бўларсан?!",294,15],["إِ[g[نّ]َا جَعَلْنَا مَا عَلَى [h:7958[ٱ]لْأَرْضِ زِينَ[u:7959[ةً ل]َّهَا لِنَ[q:7960[بْ]لُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلاً","Биз ер юзидаги нарсаларни, уларнинг қайсилари гўзалроқ амал қилишини синаш учун, зебу зийнат қилиб қўйганмиз.",294,15],["وَإِ[g[نّ]َا لَجَ[n[ـٰ]عِلُونَ مَا عَلَيْهَا صَعِي[f:7961[دًا ج]ُرُزًا","Албатта, Биз унинг юзидаги нарсаларни қуп-қуруқ тупроққа айлантиргувчимиз.",294,15],["أَمْ حَسِ[q:7962[بْ]تَ أَ[g[نّ]َ أَصْحَ[n[ـٰ]بَ [h:7963[ٱ]لْكَهْفِ وَ[h:7964[ٱ][l[ل]رَّقِيمِ كَانُو[s[اْ] مِنْ ءَايَ[n[ـٰ]تِنَا عَجَبًا","Каҳф ва битик эгаларини Бизнинг ажойиб оят-белгиларимиздан деб ўйладингми?!",294,15],["إِذْ أَوَى [h:7965[ٱ]لْفِتْيَةُ إِلَى [h:7966[ٱ]لْكَهْفِ فَقَالُو[s[اْ] رَبَّن[o[َآ] ءَاتِنَا م[u:1746[ِن ل]َّدُ[f:1747[نك]َ رَحْمَ[a:7967[ةً و]َهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا","Қачонки йигитлар каҳфдан жой олганларида: «Эй Роббимиз, бизга Ўз ҳузурингдан раҳмат бергин ва ишимизни ўзинг тўғрилагин», дедилар.",294,15],["فَضَرَ[q:7968[بْ]نَا عَلَ[o[ىٰٓ] ءَاذَانِهِمْ فِى [h:7969[ٱ]لْكَهْفِ سِنِينَ عَدَدًا","Бас, каҳфда уларнинг қулоқларига бир неча йиллар урдик.",294,15],["ثُ[g[مّ]َ بَعَثْنَ[n[ـٰ]هُمْ لِنَعْلَمَ أَىُّ [h:7970[ٱ]لْحِزْبَيْنِ أَحْصَىٰ لِمَا لَبِث[o[ُوٓ][s[اْ] أَمَدًا","Сўнгра икки гуруҳдан қайси бири уларнинг турган муддатини ҳисобловчироқ эканини билиш учун уларни уйғотдик.",294,15],["نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَه[c:7971[ُم ب]ِ[h:370[ٱ]لْحَقِّ‌ۚ إِ[g[نّ]َهُمْ فِتْيَةٌ ءَامَنُو[s[اْ] بِرَبِّهِمْ وَزِ[q:7972[دْ]نَ[n[ـٰ]هُمْ هُدًى","Биз сенга уларнинг хабарларини ҳақ ила қисса этиб берурмиз. Албатта, улар Роббиларига иймон келтирган йигитлардир. Ва Биз уларга янада зиёда ҳидоят бердик.",294,15],["وَرَبَ[q:7973[طْ]نَا عَلَىٰ قُلُوبِهِمْ إِذْ قَامُو[s[اْ] فَقَالُو[s[اْ] رَبُّنَا رَبُّ [h:6926[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ ل[a:7974[َن ن]َّ[q:7975[دْ]عُوَ[s[اْ] مِ[f:3136[ن د]ُونِه[o[ِۦٓ] إِلَ[n[ـٰ][u:7976[هًا‌ۖ ل]َّقَ[q:2389[دْ] قُلْن[o[َآ] إِ[f:7977[ذًا ش]َطَطًا","Уларнинг қалбларини мустаҳкамладик. Қачонки турдилар ва: «Бизнинг Роббимиз осмонлару ернинг Роббидир. Ундан ўзгани ҳаргиз илоҳ дея дуо қилмаймиз. Агар шундай қилсак, ноҳақ сўзни айтган бўлурмиз.",294,15],["هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ قَوْمُنَا [h:7978[ٱ]تَّخَذُو[s[اْ] مِ[f:3136[ن د]ُونِه[o[ِۦٓ] ءَالِهَ[u:7979[ةً‌ۖ ل]َّوْلَا يَأْتُونَ عَلَيْه[c:7980[ِم ب]ِسُلْطَ[n[ـٰ][i:7981[نِۭ ب]َيِّ[f:7982[نٍ‌ۖ ف]َمَنْ أَظْلَمُ مِ[g[مّ]َنِ [h:3980[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِبًا","Ана у қавмимиз Ундан ўзга худолар тутдилар. Уларга равшан ҳужжатлар келтира олармиканлар?! Аллоҳга ёлғон уйдиргандан ҳам золимроқ ким бор.",294,15],["وَإِذِ [h:7983[ٱ]عْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا [h:416[ٱ]للَّهَ فَأْوُ[o[ۥٓاْ] إِلَى [h:7966[ٱ]لْكَهْفِ يَ[f:7984[نش]ُرْ لَكُمْ رَبُّك[w:7985[ُم م]ّ[u:7986[ِن ر]َّحْمَتِه[n[ِۦ] وَيُهَيِّئْ لَك[w:556[ُم م]ِّنْ أَمْرِك[w:7987[ُم م]ِّرْفَقًا","Модомики улардан ва улар Аллоҳдан бошқа ибодат қилаётган нарсадан узоқлашмоқчи бўлсангиз, каҳфдан паноҳ жой олингиз. Роббингиз сизга Ўз раҳматини таратур ва сизга ишингизда осонлик яратур», дедилар.",295,15],["۞ وَتَرَى [h:7988[ٱ][l[ل]شَّمْسَ إِذَا طَلَعَت تَّز[n[َٲ]وَرُ عَ[f:7989[ن ك]َهْفِهِمْ ذَاتَ [h:7990[ٱ]لْيَمِينِ وَإِذَا غَرَبَت تَّ[q:7991[قْ]رِضُهُمْ ذَاتَ [h:7992[ٱ][l[ل]شِّمَالِ وَهُمْ فِى فَ[q:7993[جْ]وَ[a:7994[ةٍ م]ِّنْهُ‌ۚ ذ[n[َٲ]لِكَ مِنْ ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ‌ۗ م[a:5146[َن ي]َهْدِ [h:5147[ٱ]للَّهُ فَهُوَ [h:7906[ٱ]لْمُهْتَدِ‌ۖ وَم[a:5149[َن ي]ُضْلِلْ فَلَ[f:2843[ن ت]َجِدَ لَهُ[n[ۥ] وَلِي[a:7995[ًّا م]ُّرْشِدًا","Қуёш чиққанида уларнинг каҳфининг ўнг томонидан мойил бўлганини, ботганда эса, чап томонидан қийиб ўтганини кўрасан. Улар эса унинг кенг жойидадирлар. Ана шу ҳам Аллоҳнинг оят-мўъжизаларидандир. Кимни Аллоҳ ҳидоятга бошласа, ўша ҳидоят топгувчидир. Кимни адаштирса, бас, ҳаргиз унга иршод қилувчи бирон дўст топа олмассан.",295,15],["وَتَحْسَبُهُمْ أَيْقَا[a:7996[ظًا و]َهُمْ رُقُو[a:7997[دٌ‌ۚ و]َنُقَلِّبُهُمْ ذَاتَ [h:7990[ٱ]لْيَمِينِ وَذَاتَ [h:7998[ٱ][l[ل]شِّمَالِ‌ۖ وَكَلْبُه[c:7999[ُم ب]َ[n[ـٰ]سِ[f:8000[طٌ ذ]ِرَاعَيْهِ بِ[h:8001[ٱ]لْوَصِيدِ‌ۚ لَوِ [h:8002[ٱ]طَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَا[a:8003[رًا و]َلَمُلِئْتَ مِنْهُمْ رُعْبًا","Уларни уйғоқ деб ўйлайсан, ҳолбуки, ухлаб ётурлар. Уларни гоҳ ўнгга, гоҳ чапга ағдариб турурмиз. Итлари эса, остонада олд оёқларини чўзиб ётур. Гар уларни кўрсайдинг, ортга ўгирилиб қочар ва улардан қўрқинчга тўлар эдинг.",295,15],["وَكَذ[n[َٲ]لِكَ بَعَثْنَ[n[ـٰ]هُمْ لِيَتَس[o[َا]ٓءَلُو[s[اْ] بَيْنَهُمْ‌ۚ قَالَ ق[o[َا]ٓئِ[a:6558[لٌ م]ِّنْهُمْ كَمْ لَبِثْتُمْ‌ۖ قَالُو[s[اْ] لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْ[f:8004[مٍ‌ۚ ق]َالُو[s[اْ] رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ فَ[h:2764[ٱ][q:2764[بْ]عَث[o[ُوٓ][s[اْ] أَحَدَك[c:8005[ُم ب]ِوَرِقِكُمْ هَ[n[ـٰ]ذِه[o[ِۦٓ] إِلَى [h:8006[ٱ]لْمَدِينَةِ فَلْيَ[f:8007[نظ]ُرْ أَيُّه[o[َآ] أَزْكَىٰ طَعَا[f:8008[مًا ف]َلْيَأْتِك[c:8009[ُم ب]ِرِزْ[a:8010[قٍ م]ِّنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَ[g[نّ]َ بِكُمْ أَحَدًا","Ва шундай қилиб, уларни ўзаро сўрашлари учун уйғотдик. Улардан бири: «Қанча қолдинглар?» деди. Улар: «Бир кун ёки бир куннинг баъзисича қолдик», дейишди. «Қанча қолганингизни Роббингиз яхши билгувчидир, шаҳарга бирингизни ушбу пулингиз ила юборинг, назар солиб, яхши таомни танлаб, ундан ризқ келтирсин ва диққатли бўлсин, сизни бировга сездириб қўймасин.",295,15],["إِ[g[نّ]َهُمْ إ[a:8011[ِن ي]َظْهَرُو[s[اْ] عَلَيْكُمْ يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِى مِلَّتِهِمْ وَلَ[f:8012[ن ت]ُفْلِح[o[ُوٓ][s[اْ] إِذًا أَبَدًا","Чунки агар улар сизни қўлга олсалар, тошбўрон қиладилар ёки ўз миллатларига қайтарурлар. Ундай бўлса, зинҳор ва абадий нажот топмассиз, дейишди.",295,15],["وَكَذ[n[َٲ]لِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ وَعْدَ [h:3149[ٱ]للَّهِ حَ[a:8013[قٌّ و]َأَ[g[نّ]َ [h:8014[ٱ][l[ل]سَّاعَةَ لَا رَيْبَ فِيه[o[َآ] إِذْ يَتَنَ[n[ـٰ]زَعُونَ بَيْنَهُمْ أَمْرَهُمْ‌ۖ فَقَالُو[s[اْ] [h:8015[ٱ][q:8016[بْ]نُو[s[اْ] عَلَيْه[c:8017[ِم ب]ُنْيَ[n[ـٰ][u:8018[نًا‌ۖ ر]َّبُّهُمْ أَعْلَمُ بِهِمْ‌ۚ قَالَ [h:590[ٱ]لَّذِينَ غَلَبُو[s[اْ] عَلَ[o[ىٰٓ] أَمْرِهِمْ لَنَتَّخِذَ[g[نّ]َ عَلَيْه[w:8019[ِم م]َّسْجِدًا","Шундай қилиб, Аллоҳнинг ваъдаси ҳақ эканини ва қиёмат соатида шубҳа йўқ эканини билишлари учун уларни билдирдик. Энди эса, улар иши ҳақида тортиша бошладилар: «Уларнинг устларига бино барпо қилинглар, Роббилари уларни яхши билгувчидир», дедилар. Ишларига ғолиб келганлар эса: «Уларнинг устларига, албатта, масжид қуриб олурмиз», дедилар.",296,15],["سَيَقُولُونَ ثَلَ[n[ـٰ]ثَ[u:8020[ةٌ ر]َّابِعُهُمْ كَلْبُهُمْ وَيَقُولُونَ خَمْسَ[f:8021[ةٌ س]َادِسُهُمْ كَلْبُهُمْ رَ[q:8022[جْ]م[i:8023[َۢا ب]ِ[h:13[ٱ]لْغَيْبِ‌ۖ وَيَقُولُونَ سَ[q:8024[بْ]عَ[a:8025[ةٌ و]َثَامِنُهُمْ كَلْبُهُمْ‌ۚ قُ[b:8026[ل] رَّبّ[o[ِىٓ] أَعْلَمُ بِعِدَّتِه[w:8027[ِم م]َّا يَعْلَمُهُمْ إِلَّا قَلِي[f:8028[لٌ‌ۗ ف]َلَا تُمَارِ فِيهِمْ إِلَّا مِر[o[َا]ٓ[f:8029[ءً ظ]َ[n[ـٰ]هِ[a:8030[رًا و]َلَا تَسْتَفْتِ فِيه[w:8031[ِم م]ِّنْهُمْ أَحَدًا","Ҳали улар: «Учтадирлар, итлари тўртинчиларидир», дерлар. Ва: «Бештадирлар, итлари олтинчиларидир», деб ғайбга тош отарлар. Ва: «Еттитадирлар, итлари саккизинчиларидир ҳам», дерлар. Сен: «Роббим уларнинг саноғини яхши билгувчидир. Уларни жуда оз киши билур», дегин. Бас, улар ҳақида тортишиб юрма. Тортишсанг ҳам, очиқ тортиш. Улар ҳақида ҳеч кимдан фатво ҳам сўрама.",296,15],["وَلَا تَقُولَ[g[نّ]َ لِشَ[s[اْ]ىْءٍ إِ[g[نّ]ِى فَاعِ[f:8032[لٌ ذ][n[َٲ]لِكَ غَدًا","Зинҳор бир нарсани: «Буни эртага албатта қилгувчиман», дема.",296,15],["إِلّ[o[َآ] أ[a:4201[َن ي]َش[o[َا]ٓءَ [h:4334[ٱ]للَّهُ‌ۚ وَ[h:1898[ٱ]ذْكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلْ عَسَ[o[ىٰٓ] أ[a:8033[َن ي]َهْدِيَنِ رَبِّى لِأَ[q:8034[قْ]رَبَ مِنْ هَ[n[ـٰ]ذَا رَشَدًا","Магар: «Аллоҳ хоҳласа», дегин. Қачонки унутсанг, Роббингни эсла ва: «Шоядки Роббим мени бундан яхшироққа яқин бўлишимга ҳидоят қилса», дегин.",296,15],["وَلَبِثُو[s[اْ] فِى كَهْفِهِمْ ثَلَ[n[ـٰ]ثَ مِ[s[اْ]ئَ[f:8035[ةٍ س]ِنِينَ وَ[h:8036[ٱ]زْدَادُو[s[اْ] تِسْعًا","Ва каҳфларида уч юз йил қолдилар ва тўққиз йил зиёда ҳам қилдилар.",296,15],["قُلِ [h:3166[ٱ]للَّهُ أَعْلَمُ بِمَا لَبِثُو[s[اْ‌ۖ] لَهُ[n[ۥ] غَيْبُ [h:6538[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ أَ[q:8037[بْ]صِرْ بِه[n[ِۦ] وَأَسْمِعْ‌ۚ مَا لَه[w:1812[ُم م]ِّ[f:3136[ن د]ُونِه[n[ِۦ] م[a:557[ِن و]َلِ[a:558[ىٍّ و]َلَا يُشْرِكُ فِى حُكْمِه[o[ِۦٓ] أَحَدًا","Сен: «Уларнинг қанча қолганларини Аллоҳ яхши билгувчидир. Осмонлару ернинг ғайби Унга хосдир. У зот нақадар яхши кўргувчи ва яхши эшитгувчи зотдир. Уларга Ундан ўзга дўст йўқдир. Ва У Ўз ҳукмида ҳеч кимни шерик қилмас», дегин.",296,15],["وَ[h:9999[ٱ]تْلُ م[o[َآ] أُوحِىَ إِلَيْكَ مِ[f:3569[ن ك]ِتَابِ رَبِّكَ‌ۖ لَا مُبَدِّلَ لِكَلِمَ[n[ـٰ]تِه[n[ِۦ] وَلَ[f:3232[ن ت]َجِدَ مِ[f:3136[ن د]ُونِه[n[ِۦ] مُلْتَحَدًا","Сенга Роббинг китобидан ваҳий қилинганини тиловат қил. Унинг калималарини алмаштиргувчи йўқ. Ундан ўзга ҳеч қандай паноҳни топа олмассан.",296,15],["وَ[h:9999[ٱ]صْبِرْ نَفْسَكَ مَعَ [h:2899[ٱ]لَّذِينَ يَ[q:1240[دْ]عُونَ رَبَّه[c:4077[ُم ب]ِ[h:4078[ٱ]لْغَدَ[s[و][n[ٲ]ةِ وَ[h:4079[ٱ]لْعَشِىِّ يُرِيدُونَ وَ[q:580[جْ]هَهُ[n[ۥ]‌ۖ وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ تُرِيدُ زِينَةَ [h:8038[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۖ وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُ[n[ۥ] عَ[f:8039[ن ذ]ِكْرِنَا وَ[h:3160[ٱ]تَّبَعَ هَوَ[n[ٮٰ]هُ وَكَانَ أَمْرُهُ[n[ۥ] فُرُطًا","Ўзингни эртаю кеч Роббиларига дуо қилиб, Унинг юзини ирода қилувчилар ила сабр этиб тут. Ҳаёти дунё зийнатини хоҳлаб, улардан икки кўзингни бурма. Қалбини Ўз зикримиздан ғофил қилиб қўйганларимизга ва ҳавойи нафсига эргашиб иши издан чиққанларга итоат қилма.",297,15],["وَقُلِ [h:8040[ٱ]لْحَقُّ م[u:243[ِن ر]َّبِّكُمْ‌ۖ فَمَ[f:8041[ن ش][o[َا]ٓءَ فَلْيُؤْم[a:8042[ِن و]َمَ[f:8043[ن ش][o[َا]ٓءَ فَلْيَكْفُرْ‌ۚ إِ[g[نّ][o[َآ] أَعْتَ[q:2660[دْ]نَا لِلظَّ[n[ـٰ]لِمِينَ نَارًا أَحَاطَ بِهِمْ سُرَادِقُهَا‌ۚ وَإ[a:8044[ِن ي]َسْتَغِيثُو[s[اْ] يُغَاثُو[s[اْ] بِم[o[َا]ٓ[f:8045[ءٍ ك]َ[h:8046[ٱ]لْمُهْلِ يَشْوِى [h:8047[ٱ]لْوُجُوهَ‌ۚ بِئْسَ [h:8048[ٱ][l[ل]شَّرَابُ وَس[o[َا]ٓءَتْ مُرْتَفَقًا","Сен: «Бу ҳақ Роббингиз томонидандир. Бас, ким хоҳласа, иймон келтирсин, ким хоҳласа, куфр келтирсин», дегин. Албатта, Биз золимларга деворлари уларни ўраб оладиган оловни тайёрлаб қўйганмиз. Агар ёрдам сўрасалар, эритилган маъдан каби юзларни қўғирувчи сув билан «ёрдам» берилур. Нақадар ёмон шароб ва нақадар ёмон жой!",297,15],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ إِ[g[نّ]َا لَا نُضِيعُ أَ[q:2418[جْ]رَ مَنْ أَحْسَنَ عَمَلاً","Албатта, Биз иймон келтирган ва яхши амаллар қилганларнинг, гўзал иш қилганларнинг ажрини зое қилмасмиз.",297,15],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ جَ[g[نّ]َ[n[ـٰ]تُ عَ[q:5720[دْ][f:8049[نٍ ت]َ[q:120[جْ]رِى مِ[f:4696[ن ت]َحْتِهِمُ [h:4697[ٱ]لْأَنْهَ[n[ـٰ]رُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِ[f:8050[ن ذ]َهَ[a:8051[بٍ و]َيَلْبَسُونَ ثِيَابًا خُضْ[a:8052[رًا م]ِّ[f:8053[ن س]ُ[f:8054[ند]ُ[a:8055[سٍ و]َإِسْتَ[q:8056[بْ]رَ[a:8057[قٍ م]ُّتَّكِــِٔينَ فِيهَا عَلَى [h:8058[ٱ]لْأَر[o[َا]ٓئِكِ‌ۚ نِعْمَ [h:8059[ٱ][l[ل]ثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا","Ана ўшаларга адн жаннатлар бордир. Остиларидан анҳорлар оқиб турадир. У ерда олтиндан бўлган билакузуклар ила безанурлар, шойи иплардан яхши либослар киярлар. Улар у ерда сўриларда ёнбошлаган ҳолда бўлурлар. Нақадар яхши савоб ва нақадар яхши жой.",297,15],["۞ وَ[h:9999[ٱ]ضْرِ[q:8060[بْ] لَه[w:8061[ُم م]َّثَل[u:7510[اً ر]َّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَ[g[نّ]َتَيْنِ مِنْ أَعْنَ[n[ـٰ][a:8062[بٍ و]َحَفَفْنَ[n[ـٰ]هُمَا بِنَخْ[a:8063[لٍ و]َجَعَلْنَا بَيْنَهُمَا زَرْعًا","Уларга икки кишини мисол қилиб келтир. Улардан бирига узумлардан икки боғ бердик ва уларни хурмо ила ўрадик ва ораларида экинзор қилдик.",297,15],["كِلْتَا [h:8064[ٱ]لْجَ[g[نّ]َتَيْنِ ءَاتَتْ أُكُلَهَا وَلَمْ تَظْل[w:8065[ِم م]ِّنْهُ شَيْـ[a:8066[ـًٔا‌ۚ و]َفَجَّرْنَا خِلَ[n[ـٰ]لَهُمَا نَهَرًا","Ўша икки боғ ҳосилларини бекаму кўст берар ва ораларидан анҳор оқизиб қўйган эдик.",297,15],["وَكَانَ لَهُ[n[ۥ] ثَمَ[f:8067[رٌ ف]َقَالَ لِصَ[n[ـٰ]حِبِه[n[ِۦ] وَهُوَ يُحَاوِرُهُ[o[ۥٓ] أَنَا۟ أَكْثَرُ مِ[f:3891[نك]َ مَال[a:8068[اً و]َأَعَزُّ نَفَرًا","Унинг меваси бор эди. У ўз шериги ила гаплашар экан: «Менинг сендан молим кўп ва одамларим қувватлироқ», деди.",297,15],["وَدَخَلَ جَ[g[نّ]َتَهُ[n[ۥ] وَهُوَ ظَالِ[u:8069[مٌ ل]ِّنَفْسِه[n[ِۦ] قَالَ م[o[َآ] أَظُ[g[نّ]ُ أَ[f:8070[ن ت]َبِيدَ هَ[n[ـٰ]ذِه[o[ِۦٓ] أَبَدًا","У ўз боғига кирар экан, ўзига зулм қилган ҳолида: «Мен буни ҳеч қачон йўқ бўлмар, деб ўйлайман.",298,15],["وَم[o[َآ] أَظُ[g[نّ]ُ [h:8071[ٱ][l[ل]سَّاعَةَ ق[o[َا]ٓئِمَ[a:8072[ةً و]َلَئ[u:8073[ِن ر]ُّدِ[d:8074[د]تُّ إِلَىٰ رَبِّى لَأَجِدَ[g[نّ]َ خَيْ[a:8075[رًا م]ِّنْهَا مُ[f:8076[نق]َلَبًا","Қиёмат қоим бўлмаса керак, деб ўйлайман. Агар Роббимга қайтарилсам ҳам, албатта, бундан яхши оқибатни топаман», деди.",298,15],["قَالَ لَهُ[n[ۥ] صَاحِبُهُ[n[ۥ] وَهُوَ يُحَاوِرُهُ[o[ۥٓ] أَكَفَرْتَ بِ[h:315[ٱ]لَّذِى خَلَقَكَ مِ[f:1972[ن ت]ُرَا[f:1973[بٍ ث]ُ[g[مّ]َ م[a:7325[ِن ن]ُّ[q:7326[طْ]فَ[f:8077[ةٍ ث]ُ[g[مّ]َ سَوَّ[n[ٮٰ]كَ رَجُلاً","Унга шериги гаплаша туриб: «Сени тупроқдан, сўнгра нутфадан яратган ва инсон этиб ростлаган зотга куфр келтирдингми?!.",298,15],["لَّ[n[ـٰ]كِ[g[نّ]َا۟ هُوَ [h:8078[ٱ]للَّهُ رَبِّى وَل[o[َآ] أُشْرِكُ بِرَبّ[o[ِىٓ] أَحَدًا","Лекин мен: «У Аллоҳ менинг Роббимдир ва Унга ҳеч кимни шерик қилмайман.",298,15],["وَلَوْل[o[َآ] إِذْ دَخَلْتَ جَ[g[نّ]َتَكَ قُلْتَ مَا ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ لَا قُوَّةَ إِلَّا بِ[h:32[ٱ]للَّهِ‌ۚ إِ[f:8079[ن ت]َرَنِ أَنَا۟ أَقَلَّ مِ[f:3891[نك]َ مَال[a:8080[اً و]َوَلَدًا","Боғингга кирганингда: «Аллоҳнинг хоҳлагани, Аллоҳдан бошқада қувват йўқ», десайдинг. Агар мени ўзингдан молу дунё ва бола-чақа жиҳатидан кам деб билсанг.",298,15],["فَعَسَىٰ رَبّ[o[ِىٓ] أ[a:8081[َن ي]ُؤْتِيَنِ خَيْ[a:8082[رًا م]ِّ[f:8083[ن ج]َ[g[نّ]َتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَا[a:8084[نًا م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ فَتُصْبِحَ صَعِي[f:8085[دًا ز]َلَقًا","Шояд Роббим менга сенинг боғингдан яхшироғини берса, сенинг боғингга осмондан офат юбориб, у сип-силлиқ тупроққа айланиб қолса.",298,15],["أَوْ يُصْبِحَ م[o[َا]ٓؤُهَا غَوْ[f:8086[رًا ف]َلَ[f:8087[ن ت]َسْتَطِيعَ لَهُ[n[ۥ] طَلَبًا","Ёки суви ерга сингиб кетиб, сен уни талаб қилишга қодир бўлмай қолсанг», деди.",298,15],["وَأُحِيطَ بِثَمَرِه[n[ِۦ] فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ م[o[َآ] أَ[f:8088[نف]َقَ فِيهَا وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَ[n[ـٰ]لَيْتَنِى لَمْ أُشْرِكْ بِرَبّ[o[ِىٓ] أَحَدًا","Ва унинг меваси ўралди. Ўзи эса, унга сарф қилгани ҳасратидан чапак чалиб, боғида ишкомлар йиқилиб ётганини кўриб: «Қани энди Роббимга ҳеч кимни шерик қилмаганимда», деб қолаверди.",298,15],["وَلَمْ تَك[u:4298[ُن ل]َّهُ[n[ۥ] فِئَ[a:8089[ةٌ ي]َ[f:8090[نص]ُرُونَهُ[n[ۥ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَمَا كَانَ مُ[f:8091[نت]َصِرًا","Унга Аллоҳдан бошқа ёрдам берадиган гуруҳ бўлмади, ўзи ҳам нусрат қозона олмади.",298,15],["هُنَالِكَ [h:8092[ٱ]لْوَلَ[n[ـٰ]يَةُ لِلَّهِ [h:8093[ٱ]لْحَقِّ‌ۚ هُوَ خَيْ[f:8094[رٌ ث]َوَا[a:8095[بًا و]َخَيْرٌ عُ[q:8096[قْ]بًا","Бундай мақомда ҳақ нусрат Аллоҳга хосдир. У яхши савобли ва яхши оқибатли зотдир.",298,15],["وَ[h:9999[ٱ]ضْرِ[q:8060[بْ] لَه[w:8097[ُم م]َّثَلَ [h:8098[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا كَم[o[َا]ٓءٍ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ فَ[h:6009[ٱ]خْتَلَطَ بِه[n[ِۦ] نَبَاتُ [h:6010[ٱ]لْأَرْضِ فَأَصْبَحَ هَشِي[f:8099[مًا ت]َذْرُوهُ [h:8100[ٱ][l[ل]رِّيَ[n[ـٰ]حُ‌ۗ وَكَانَ [h:2653[ٱ]للَّهُ عَلَىٰ كُلِّ ش[a:8101[َىْءٍ م]ُّ[q:8102[قْ]تَدِرًا","Уларга ҳаёти дунёнинг мисолини келтир. У Биз осмондан туширган сувга ўхшайдир. Унинг сабаби ила ер набототлари аралашиб чиқди. Бас, хашакка айланиб, уни шамол учириб кетди. Аллоҳ ҳар бир нарсага қодир бўлган зотдир.",298,15],["ٱلْمَالُ وَ[h:8103[ٱ]لْبَنُونَ زِينَةُ [h:8104[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۖ وَ[h:8105[ٱ]لْبَ[n[ـٰ]قِيَ[n[ـٰ]تُ [h:8106[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تُ خَيْرٌ عِ[f:264[ند]َ رَبِّكَ ثَوَا[a:8095[بًا و]َخَيْرٌ أَمَلاً","Мол-мулк, бола-чақа ҳаёти дунё зийнатидир. Боқий қолгувчи солиҳ амаллар Роббинг ҳузурида савоб ва умид жиҳатидан яхшироқдир.",299,15],["وَيَوْمَ نُسَيِّرُ [h:8107[ٱ]لْجِبَالَ وَتَرَى [h:8108[ٱ]لْأَرْضَ بَارِزَ[a:8109[ةً و]َحَشَرْنَ[n[ـٰ]هُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا","Тоғларни юргизадиган ва ерни яп-яланғоч кўрадиган кунда. Ўшанда уларни жамлаймиз ва бирон кишини қўймаймиз.",299,15],["وَعُرِضُو[s[اْ] عَلَىٰ رَبِّكَ صَف[u:8110[ًّا ل]َّقَ[q:2389[دْ] جِئْتُمُونَا كَمَا خَلَ[q:4250[قْ]نَ[n[ـٰ]كُمْ أَوَّلَ مَرَّ[i:8111[ةِۭ‌ۚ ب]َلْ زَعَمْتُمْ أَلّ[a:8112[َن ن]َّ[q:8113[جْ]عَلَ لَك[w:8114[ُم م]َّوْعِدًا","Ва Роббингга сафга тортилган ҳолларида рўбарў қилиндилар. «Батаҳқиқ, сизларни аввал қандай яратган бўлсак, шундай Бизга келдингиз. Аммо сиз Бизни ҳеч жой ва вақт ваъда қилганимиз йўқ, деб ўйлар эдингиз»,.",299,15],["وَوُضِعَ [h:8115[ٱ]لْكِتَ[n[ـٰ]بُ فَتَرَى [h:8116[ٱ]لْمُ[q:4093[جْ]رِمِينَ مُشْفِقِينَ مِ[g[مّ]َا فِيهِ وَيَقُولُونَ يَ[n[ـٰ]وَيْلَتَنَا مَالِ هَ[n[ـٰ]ذَا [h:8117[ٱ]لْكِتَ[n[ـٰ]بِ لَا يُغَادِرُ صَغِيرَ[a:5900[ةً و]َلَا كَبِيرَةً إِلّ[o[َآ] أَحْصَ[n[ـٰ]هَا‌ۚ وَوَجَدُو[s[اْ] مَا عَمِلُو[s[اْ] حَاضِ[a:8118[رًا‌ۗ و]َلَا يَظْلِمُ رَبُّكَ أَحَدًا","Ва китоб қўйилди. Бас, жиноятчиларни ундаги нарсадан қўрққан ҳолларида кўрасан. Улар: «Вой, шўримиз қурисин. Бу қандай китоб, кичикни ҳам, каттани ҳам ҳеч қўймай ҳисоб қилибди-я», дерлар. Ва қилган амалларини ҳозир ҳолда топдилар. Роббинг ҳеч кимга зулм қилмас.",299,15],["وَإِذْ قُلْنَا لِلْمَلَ[o[ـٰٓ]ئِكَةِ [h:179[ٱ]سْجُدُو[s[اْ] لِأَدَمَ فَسَجَد[o[ُوٓ][s[اْ] إِلّ[o[َآ] إِ[q:180[بْ]لِيسَ كَانَ مِنَ [h:4673[ٱ]لْجِ[g[نّ]ِ فَفَسَقَ عَنْ أَمْرِ رَبِّه[o[ِۦٓ‌ۗ] أَفَتَتَّخِذُونَهُ[n[ۥ] وَذُرِّيَّتَهُ[o[ۥٓ] أَوْلِي[o[َا]ٓءَ مِ[f:7659[ن د]ُونِى وَهُمْ لَكُمْ عَدُو[i:8119[ُّۢ‌ۚ ب]ِئْسَ لِلظَّ[n[ـٰ]لِمِينَ بَدَلاً","Фаришталарга: «Одамга сажда қилинглар», деганимизни эсла. Бас, ўшанда улар сажда қилдилар. Магар Иблис қилмади. У жиндан бўлган эди. У ўз Роббининг амридан чиқди. Энди сизлар Мени қўйиб уни ва унинг зурриётларини дўст қилиб оласизларми?! Ҳолбуки, у сизларга душман-ку! У золимлар учун нақадар ёмон бадалдир.",299,15],["۞ مّ[o[َآ] أَشْهَ[d:8120[د]تُّهُمْ خَلْقَ [h:8121[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَلَا خَلْقَ أَ[f:568[نف]ُسِهِمْ وَمَا كُ[f:2917[نت]ُ مُتَّخِذَ [h:8122[ٱ]لْمُضِلِّينَ عَضُدًا","Мен уларни на осмонлару ерни яратишга ва на ўзларини яратишга гувоҳ қилмаганман ва адаштиргувчиларни ёрдамчи қилиб олган эмасман.",299,15],["وَيَوْمَ يَقُولُ نَادُو[s[اْ] شُرَك[o[َا]ٓءِىَ [h:7378[ٱ]لَّذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُو[s[اْ] لَهُمْ وَجَعَلْنَا بَيْنَه[w:8123[ُم م]َّوْبِقًا","У зот: «Сизлар Менинг шерикларим, деб ўйлаганларингизни чақиринг», деган кунида уларни чақирдилар. Бас, улар жавоб бермадилар ва уларнинг орасига ҳалокатгоҳ қилмишмиз.",299,15],["وَرَءَا [h:8124[ٱ]لْمُ[q:5255[جْ]رِمُونَ [h:8125[ٱ][l[ل][g[نّ]َارَ فَظَ[g[نّ][o[ُوٓ][s[اْ] أَ[g[نّ]َه[w:8126[ُم م]ُّوَاقِعُوهَا وَلَمْ يَجِدُو[s[اْ] عَنْهَا مَصْرِفًا","Жиноятчилар дўзахни кўрурлар ва, албатта, унга тушувчи эканларига ишонарлар ва ундан қочар жой топмаслар.",299,15],["وَلَقَ[q:341[دْ] صَرَّفْنَا فِى هَ[n[ـٰ]ذَا [h:7765[ٱ]لْقُرْءَانِ لِل[g[نّ]َاسِ مِ[f:843[ن ك]ُلِّ مَثَ[a:8127[لٍ‌ۚ و]َكَانَ [h:7688[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ أَكْثَرَ ش[f:8128[َىْءٍ ج]َدَلاً","Батаҳқиқ, бу Қуръонда одамлар учун турли масаллар баён қилдик. Инсон ўзи кўп тортишувчи бўлган эди.",300,15],["وَمَا مَنَعَ [h:7899[ٱ][l[ل][g[نّ]َاسَ أ[a:386[َن ي]ُؤْمِن[o[ُوٓ][s[اْ] إِذْ ج[o[َا]ٓءَهُمُ [h:7900[ٱ]لْهُدَىٰ وَيَسْتَغْفِرُو[s[اْ] رَبَّهُمْ إِلّ[o[َآ] أَ[f:6843[ن ت]َأْتِيَهُمْ سُ[g[نّ]َةُ [h:7207[ٱ]لْأَوَّلِينَ أَوْ يَأْتِيَهُمُ [h:7420[ٱ]لْعَذَابُ قُبُلاً","Одамларни уларга ҳидоят келганида иймон келтиришларидан ва Роббиларига истиғфор айтишларидан фақатгина аввалгиларнинг суннати келишини ёки очиқ азоб келишини кутишлари тўсди, холос.",300,15],["وَمَا نُرْسِلُ [h:4063[ٱ]لْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُ[f:1163[نذ]ِرِينَ‌ۚ وَيُجَ[n[ـٰ]دِلُ [h:8129[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِ[h:212[ٱ]لْبَ[n[ـٰ]طِلِ لِيُ[q:8130[دْ]حِضُو[s[اْ] بِهِ [h:8131[ٱ]لْحَقَّ‌ۖ وَ[h:8132[ٱ]تَّخَذ[o[ُوٓ][s[اْ] ءَايَ[n[ـٰ]تِى وَم[o[َآ] أُ[f:8133[نذ]ِرُو[s[اْ] هُزُوًا","Биз Пайғамбарларни башорат бергувчи ва огоҳлантиргувчи қилиб юборамиз, холос. Куфр келтирганлар эса, ботил ила мунозара қилиб, у билан ҳақни енгмоқчи бўлурлар. Ҳамда Менинг оятларимдан ва ўзлари огоҳлантирилган нарсадан истеҳзо қилурлар.",300,15],["وَمَنْ أَظْلَمُ مِ[g[مّ]َ[f:8134[ن ذ]ُكِّرَ بِـَٔـايَ[n[ـٰ]تِ رَبِّه[n[ِۦ] فَأَعْرَضَ عَنْهَا وَنَسِىَ مَا قَدَّمَتْ يَدَاهُ‌ۚ إِ[g[نّ]َا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِ[g[نّ]َةً أ[a:3987[َن ي]َفْقَهُوهُ وَف[o[ِىٓ] ءَاذَانِهِمْ وَ[q:3988[قْ][a:3989[رًا‌ۖ و]َإِ[f:8135[ن ت]َ[q:8136[دْ]عُهُمْ إِلَى [h:4178[ٱ]لْهُدَىٰ فَل[a:8137[َن ي]َهْتَد[o[ُوٓ][s[اْ] إِذًا أَبَدًا","Роббиси оятлари ила эслатилганда, улардан юз ўгириб, ўзи қилган ларни унутган кимсадан ҳам золимроқ одам борми?! Албатта, Биз у ни англамасликлари учун уларнинг дилларига пардалар ва қулоқларига оғирлик қилиб қўйдик. Агар уларни ҳидоятга чақирсанг ҳам, ҳаргиз ҳидоят топмаслар.",300,15],["وَرَبُّكَ [h:8138[ٱ]لْغَفُورُ ذُو [h:4430[ٱ][l[ل]رَّحْمَةِ‌ۖ لَوْ يُؤَاخِذُه[c:8139[ُم ب]ِمَا كَسَبُو[s[اْ] لَعَجَّلَ لَهُمُ [h:8140[ٱ]لْعَذَابَ‌ۚ بَل لَّه[w:8141[ُم م]َّوْعِ[u:8142[دٌ ل]ّ[a:8143[َن ي]َجِدُو[s[اْ] مِ[f:3136[ن د]ُونِه[n[ِۦ] مَوْئِلاً","Ва Роббинг сермағфират ва раҳм-шафқат соҳиби зотдир. Агар уларни қилган касбларига биноан олганида, азобларини тезлаштирган бўлар эди. Лекин уларга ваъда қилинган вақт бор. У келганда ундан ўзга паноҳгоҳ топмаслар.",300,15],["وَتِلْكَ [h:8144[ٱ]لْقُرَ[o[ىٰٓ] أَهْلَكْنَ[n[ـٰ]هُمْ لَ[g[مّ]َا ظَلَمُو[s[اْ] وَجَعَلْنَا لِمَهْلِكِه[w:8145[ِم م]َّوْعِدًا","Ана у шаҳарларни ҳам зулм қилганларида ҳалок этганмиз ва уларнинг ҳалокатларига вақт белгилаганмиз.",300,15],["وَإِذْ قَالَ مُوسَىٰ لِفَتَ[n[ـٰ]هُ ل[o[َآ] أَ[q:8146[بْ]رَحُ حَتَّ[o[ىٰٓ] أَ[q:8147[بْ]لُغَ مَ[q:8148[جْ]مَعَ [h:8149[ٱ]لْبَحْرَيْنِ أَوْ أَمْضِىَ حُقُبًا","Мусо ўз йигитига: «Икки денгиз жамланган жойга етмагунимча, йилларни ўтказсам ҳам, юравераман», деганини эсла.",300,15],["فَلَ[g[مّ]َا بَلَغَا مَ[q:8148[جْ]مَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَ[h:8150[ٱ]تَّخَذَ سَبِيلَهُ[n[ۥ] فِى [h:837[ٱ]لْبَحْرِ سَرَبًا","Икковлон икки жамланган жойга етганларида, балиқларни унутдилар. Бас, у денгизни тешиб йўл олди.",300,15],["فَلَ[g[مّ]َا جَاوَزَا قَالَ لِفَتَ[n[ـٰ]هُ ءَاتِنَا غَد[o[َا]ٓءَنَا لَقَ[q:2389[دْ] لَقِينَا مِ[f:8151[ن س]َفَرِنَا هَ[n[ـٰ]ذَا نَصَبًا","Удан ўтганлари замон у йигитига: «Тушлигимизни келтир. Бу сафаримизда чарчоққа учрадик», деди.",301,15],["قَالَ أَرَءَيْتَ إِذْ أَوَيْن[o[َآ] إِلَى [h:8152[ٱ][l[ل]صَّخْرَةِ فَإِ[g[نّ]ِى نَسِيتُ [h:8153[ٱ]لْحُوتَ وَم[o[َآ] أَنْسَ[n[ـٰ]نِيهُ إِلَّا [h:8154[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ أَنْ أَذْكُرَهُ[n[ۥ]‌ۚ وَ[h:3162[ٱ]تَّخَذَ سَبِيلَهُ[n[ۥ] فِى [h:837[ٱ]لْبَحْرِ عَجَبًا","У: «Буни қара, харсангга жойлашганимизда, мен балиқни унутибман. Фақат шайтонгина уни эслашимни унутдирибди. Ажабо, у денгизга йўл олибди», деди.",301,15],["قَالَ ذ[n[َٲ]لِكَ مَا كُ[g[نّ]َا نَ[q:8155[بْ]غِ‌ۚ فَ[h:8156[ٱ]رْتَدَّا عَلَ[o[ىٰٓ] ءَاثَارِهِمَا قَصَصًا","У «Ана шу биз истаган нарса», деди. Бас, келган йўлларидан изларига қайтдилар.",301,15],["فَوَجَدَا عَ[q:3317[بْ][a:8157[دًا م]ِّنْ عِبَادِن[o[َآ] ءَاتَيْنَ[n[ـٰ]هُ رَحْمَ[a:5993[ةً م]ِّنْ عِ[f:6142[ند]ِنَا وَعَلَّمْنَ[n[ـٰ]هُ م[u:2897[ِن ل]َّدُ[g[نّ]َا عِلْمًا","Бас, бандаларимиздан бир бандани топдилар. Биз унга Ўз даргоҳимиздан раҳмат ва Ўз тарафимиздан илм ўргатган эдик.",301,15],["قَالَ لَهُ[n[ۥ] مُوسَىٰ هَلْ أَتَّبِعُكَ عَلَ[o[ىٰٓ] أَ[f:8158[ن ت]ُعَلِّمَنِ مِ[g[مّ]َا عُلِّمْتَ رُشْدًا","Мусо унга: «Сенга ўргатилган рушддан менга ҳам ўргатмоғинг учун сенга эргашсам майлими?» деди.",301,15],["قَالَ إِ[g[نّ]َكَ لَ[f:8159[ن ت]َسْتَطِيعَ مَعِىَ صَ[q:1427[بْ]رًا","У: «Сен мен билан бирга бўлишга сабр қила олмассан.",301,15],["وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِ[q:8160[طْ] بِه[n[ِۦ] خُ[q:8161[بْ]رًا","Ўзинг хабарини иҳота қилмаган нарсага қандай сабр қиласан», деди.",301,15],["قَالَ سَتَجِدُن[o[ِىٓ] إِ[f:364[ن ش][o[َا]ٓءَ [h:78[ٱ]للَّهُ صَابِ[a:8162[رًا و]َل[o[َآ] أَعْصِى لَكَ أَمْرًا","У: «Инша Аллоҳ, менинг сабрли эканимни кўрурсан ва сенга ҳеч бир ишда осий бўлмасман», деди.",301,15],["قَالَ فَإِنِ [h:8163[ٱ]تَّبَعْتَنِى فَلَا تَسْــَٔلْنِى عَ[f:2550[ن ش]َىْءٍ حَتَّ[o[ىٰٓ] أُحْدِثَ لَكَ مِنْهُ ذِكْرًا","У: «Агар менга эргашадиган бўлсанг, то ўзим зикр қилиб айтмагунимча бир нарса ҳақида сўрамагин», деди.",301,15],["فَ[h:9999[ٱ][f:8164[نط]َلَقَا حَتَّ[o[ىٰٓ] إِذَا رَكِبَا فِى [h:8165[ٱ][l[ل]سَّفِينَةِ خَرَقَهَا‌ۖ قَالَ أَخَرَ[q:8166[قْ]تَهَا لِتُغْرِقَ أَهْلَهَا لَقَ[q:2389[دْ] جِئْتَ شَيْــًٔا إِمْرًا","Бас, юриб кетдилар. Кемага минганларида, уни тешиб қўйди. У: «Буни унинг аҳлини ғарқ қилиш учун тешдингми?! Жуда ғалати нарса қилдинг-ку», деди.",301,15],["قَالَ أَلَمْ أَقُلْ إِ[g[نّ]َكَ لَ[f:8159[ن ت]َسْتَطِيعَ مَعِىَ صَ[q:1427[بْ]رًا","У: «Сенга, албатта, мен билан бирга бўлишга сабр қила олмайсан демабмидим?!» деди.",301,15],["قَالَ لَا تُؤَاخِذْنِى بِمَا نَسِيتُ وَلَا تُرْهِ[q:8167[قْ]نِى مِنْ أَمْرِى عُسْرًا","У: «Эсимдан чиққан нарса учун мени жазолама, бу ишим учун мени қийнама», деди.",301,15],["فَ[h:9999[ٱ][f:8164[نط]َلَقَا حَتَّ[o[ىٰٓ] إِذَا لَقِيَا غُلَ[n[ـٰ][f:8168[مًا ف]َقَتَلَهُ[n[ۥ] قَالَ أَقَتَلْتَ نَفْ[f:8169[سًا ز]َكِيَّ[i:8170[ةَۢ ب]ِغَيْرِ نَفْ[u:8171[سٍ ل]َّقَ[q:2389[دْ] جِئْتَ شَيْـ[a:8172[ـًٔا ن]ُّكْرًا","Бас, улар юриб кетдилар. То бир болани учратганида, уни ўлдирди. У: «Бировни ўлдирмаган бегуноҳ жонни ўлдирасанми?! Жуда мункар нарса қилдинг-ку?!» деди.",301,15],["۞ قَالَ أَلَمْ أَقُل لَّكَ إِ[g[نّ]َكَ لَ[f:8159[ن ت]َسْتَطِيعَ مَعِىَ صَ[q:1427[بْ]رًا","У: «Сенга, албатта, сен мен билан бирга сабр қила олмайсан демабмидим?!» деди.",302,16],["قَالَ إِ[f:8173[ن س]َأَلْتُكَ عَ[f:2550[ن ش]َىْ[i:8174[ءِۭ ب]َعْدَهَا فَلَا تُصَ[n[ـٰ]حِ[q:8175[بْ]نِى‌ۖ قَ[q:298[دْ] بَلَغْتَ م[u:8176[ِن ل]َّدُ[g[نّ]ِى عُذْرًا","У: «Агар бундан кейин сендан яна бир нарсани сўрасам, мен билан биродарлик қилмай қўявер. Батаҳқиқ, мен тарафимдан узр ни охирига етказдинг», деди.",302,16],["فَ[h:9999[ٱ][f:8164[نط]َلَقَا حَتَّ[o[ىٰٓ] إِذ[o[َآ] أَتَي[o[َآ] أَهْلَ قَرْيَةٍ [h:8177[ٱ]سْتَ[q:8178[طْ]عَم[o[َآ] أَهْلَهَا فَأَبَوْ[s[اْ] أ[a:8179[َن ي]ُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَا[a:8180[رًا ي]ُرِيدُ أ[a:8181[َن ي]َ[f:8182[نق]َضَّ فَأَقَامَهُ[n[ۥ]‌ۖ قَالَ لَوْ شِئْتَ لَتَّخَذْتَ عَلَيْهِ أَ[q:2795[جْ]رًا","Бас, юриб кетдилар. То бир шаҳар аҳолисига келганларида, унинг аҳлидан таом сўрадилар. Улар икковларини зиёфат қилишдан бош тортдилар. Икковлари у ерда йиқилиб кетай деб турган бир деворни кўришди. Бас, уни турғизиб қўйди. У: «Агар хоҳласанг, бунинг учун ҳақ олар эдинг», деди.",302,16],["قَالَ هَ[n[ـٰ]ذَا فِرَاقُ بَيْنِى وَبَيْنِكَ‌ۚ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَ[q:1427[بْ]رًا","У: «Бу, мен билан сенинг орамиздаги ажрашишдир. Энди сенга сабр қила олмаган нарсанинг таъвилини айтиб бераман;",302,16],["أَ[g[مّ]َا [h:8183[ٱ][l[ل]سَّفِينَةُ فَكَانَتْ لِمَسَ[n[ـٰ]كِينَ يَعْمَلُونَ فِى [h:837[ٱ]لْبَحْرِ فَأَرَ[d:8184[د]تُّ أَنْ أَعِيبَهَا وَكَانَ وَر[o[َا]ٓءَه[w:8185[ُم م]َّلِ[a:8186[كٌ ي]َأْخُذُ كُلَّ سَفِينَةٍ غَصْبًا","Кемага келсак, у денгизда ишлайдиган мискинларники эди. Бас, мен уни айбли қилишни ирода қилдим. Чунки ортларида бир подшоҳ бўлиб, барча кемани тортиб олаётган эди.",302,16],["وَأَ[g[مّ]َا [h:8187[ٱ]لْغُلَ[n[ـٰ]مُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِين[o[َآ] أ[a:8188[َن ي]ُرْهِقَهُمَا طُغْيَ[n[ـٰ][a:3671[نًا و]َكُفْرًا","Энди болага келсак, ота-онаси мўмин кишилар эди. Бас, биз унинг икковларини туғён ва куфр ила эзишидан қўрқдик.",302,16],["فَأَرَ[q:8189[دْ]ن[o[َآ] أ[a:8190[َن ي]ُ[q:8191[بْ]دِلَهُمَا رَبُّهُمَا خَيْ[a:8192[رًا م]ِّنْهُ زَكَ[s[و][n[ٲ][a:8193[ةً و]َأَ[q:8194[قْ]رَبَ رُحْمًا","Бас, Роббилари уларга унинг бадалига ундан кўра яхшироғини, аҳли солиҳроқ ва меҳрибонроғини беришни ирода қилди.",302,16],["وَأَ[g[مّ]َا [h:8195[ٱ]لْجِدَارُ فَكَانَ لِغُلَ[n[ـٰ]مَيْنِ يَتِيمَيْنِ فِى [h:4932[ٱ]لْمَدِينَةِ وَكَانَ تَحْتَهُ[n[ۥ] كَن[u:8196[زٌ ل]َّهُمَا وَكَانَ أَبُوهُمَا صَ[n[ـٰ]لِ[f:8197[حًا ف]َأَرَادَ رَبُّكَ أ[a:8198[َن ي]َ[q:8199[بْ]لُغ[o[َآ] أَشُدَّهُمَا وَيَسْتَخْرِجَا كَ[f:8200[نز]َهُمَا رَحْمَ[a:5993[ةً م]ّ[u:770[ِن ر]َّبِّكَ‌ۚ وَمَا فَعَلْتُهُ[n[ۥ] عَنْ أَمْرِى‌ۚ ذ[n[َٲ]لِكَ تَأْوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَ[q:1427[بْ]رًا","Деворга келсак, у шаҳардаги икки етим боланики бўлиб, унинг остида икковларининг хазинаси бор эди. Уларнинг оталари солиҳ одам эди. Бас, Роббинг икковларининг вояга етишини ва хазиналарини чиқариб олишини ирода қилди. Бу Аллоҳнинг раҳмати ила бўлди. Мен ўзимча қилганим йўқ. Мана шу сен сабр қила олмаган нарсанинг таъвилидир», деди.",302,16],["وَيَسْــَٔلُونَكَ عَ[f:8201[ن ذ]ِى [h:8202[ٱ]لْقَرْنَيْنِ‌ۖ قُلْ سَأَتْلُو[s[اْ] عَلَيْك[w:8203[ُم م]ِّنْهُ ذِكْرًا","Сендан Зулқарнайн ҳақида сўрарлар. сен: «Сизга унинг ҳақидаги зикрни тиловат қилурман», дегин.",302,16],["إِ[g[نّ]َا مَكَّ[g[نّ]َا لَهُ[n[ۥ] فِى [h:44[ٱ]لْأَرْضِ وَءَاتَيْنَ[n[ـٰ]هُ مِ[f:843[ن ك]ُلِّ ش[f:8204[َىْءٍ س]َبَبًا","Албатта, Биз унга ер юзида имконият бердик ва ҳар бир нарсага сабабини ато қилдик.",303,16],["فَأَتْبَعَ سَبَبًا","Бас, сабабга эргашди.",303,16],["حَتَّ[o[ىٰٓ] إِذَا بَلَغَ مَغْرِبَ [h:8205[ٱ][l[ل]شَّمْسِ وَجَدَهَا تَغْرُبُ فِى عَيْنٍ حَمِئَ[a:8206[ةٍ و]َوَجَدَ عِ[f:1876[ند]َهَا قَوْ[f:8207[مًا‌ۗ ق]ُلْنَا يَ[n[ـٰ]ذَا [h:8208[ٱ]لْقَرْنَيْنِ إِ[g[مّ][o[َآ] أَ[f:8209[ن ت]ُعَذِّبَ وَإِ[g[مّ][o[َآ] أَ[f:8210[ن ت]َتَّخِذَ فِيهِمْ حُسْنًا","То қуёш ботиш жойига етганида, унинг қора балчиқ булоққа ботаётганини кўрди ва унинг олдида бир қавмни кўрди. Биз: «Эй Зулқарнайн, ё уларни азобларсан, ёки гўзаллик-ла тутарсан», дедик.",303,16],["قَالَ أَ[g[مّ]َا مَ[f:8211[ن ظ]َلَمَ فَسَوْفَ نُعَذِّبُهُ[n[ۥ] ثُ[g[مّ]َ يُرَدُّ إِلَىٰ رَبِّه[n[ِۦ] فَيُعَذِّبُهُ[n[ۥ] عَذَا[a:8212[بًا ن]ُّكْرًا","У: «Ким зулм қилган бўлса, тезда уни азоблаймиз, сўнгра Роббига қайтарилар, бас, У зот ҳам уни мункар азоб ила азоблайдир.",303,16],["وَأَ[g[مّ]َا مَنْ ءَامَنَ وَعَمِلَ صَ[n[ـٰ]لِ[f:8213[حًا ف]َلَهُ[n[ۥ] جَز[o[َا]ٓءً [h:8214[ٱ]لْحُسْنَىٰ‌ۖ وَسَنَقُولُ لَهُ[n[ۥ] مِنْ أَمْرِنَا يُسْرًا","Аммо иймон келтириб яхши амаллар қилганларга эса, уларга гўзал мукофот бордир ва унга ўз ишимиздан осонини айтурмиз», деди.",303,16],["ثُ[g[مّ]َ أَتْبَعَ سَبَبًا","Сўнгра яна сабабга эргашди.",303,16],["حَتَّ[o[ىٰٓ] إِذَا بَلَغَ مَ[q:8215[طْ]لِعَ [h:8216[ٱ][l[ل]شَّمْسِ وَجَدَهَا تَ[q:8217[طْ]لُعُ عَلَىٰ قَوْ[u:8218[مٍ ل]َّمْ نَ[q:8219[جْ]عَل لَّه[w:1812[ُم م]ِّ[f:8220[ن د]ُونِهَا سِتْرًا","То қуёш чиқиш жойига етганида, уни бир қавм устидан чиқаётганини кўрди. Уларга удан тўсиқ бўладиган нарса қилмаган эдик.",303,16],["كَذ[n[َٲ]لِكَ وَقَ[q:387[دْ] أَحَ[q:8221[طْ]نَا بِمَا لَدَيْهِ خُ[q:8161[بْ]رًا","Ана шундай, батаҳқиқ, Биз унинг олдидаги нарсанинг хабарини иҳота қилдик.",303,16],["ثُ[g[مّ]َ أَتْبَعَ سَبَبًا","Сўнгра у яна сабабга эргашди.",303,16],["حَتَّ[o[ىٰٓ] إِذَا بَلَغَ بَيْنَ [h:8222[ٱ][l[ل]سَّدَّيْنِ وَجَدَ مِ[f:8223[ن د]ُونِهِمَا قَوْ[u:8224[مًا ل]َّا يَكَادُونَ يَفْقَهُونَ قَوْلاً","То икки тоғ орасига етганида, уларнинг ортида бирон гапни англамайдиган қавмни кўрди.",303,16],["قَالُو[s[اْ] يَ[n[ـٰ]ذَا [h:8208[ٱ]لْقَرْنَيْنِ إِ[g[نّ]َ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِى [h:44[ٱ]لْأَرْضِ فَهَلْ نَ[q:8225[جْ]عَلُ لَكَ خَرْجًا عَلَ[o[ىٰٓ] أَ[f:8226[ن ت]َ[q:8227[جْ]عَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّا","Улар: «Эй Зулқарнайн, албатта, Яъжуж ва Маъжуж ер юзида бузғунчилик қилгувчилардир. Биз сенга харож берсак, биз билан уларнинг орасида тўсиқ қилиб берурмисан?» дедилар.",303,16],["قَالَ مَا مَكَّ[g[نّ]ِى فِيهِ رَبِّى خَيْ[f:8228[رٌ ف]َأَعِينُونِى بِقُوَّةٍ أَ[q:8229[جْ]عَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَ[q:8230[دْ]مًا","У: «Роббим менга берган имконият яхшидир. Бас, сиз менга куч ила ёрдам беринг. Сиз билан уларнинг орасида бир девор қилажакман.",303,16],["ءَاتُونِى زُبَرَ [h:8231[ٱ]لْحَدِيدِ‌ۖ حَتَّ[o[ىٰٓ] إِذَا سَاوَىٰ بَيْنَ [h:8232[ٱ][l[ل]صَّدَفَيْنِ قَالَ [h:8233[ٱ][f:8234[نف]ُخُو[s[اْ‌ۖ] حَتَّ[o[ىٰٓ] إِذَا جَعَلَهُ[n[ۥ] نَا[f:8235[رًا ق]َالَ ءَاتُون[o[ِىٓ] أُفْرِغْ عَلَيْهِ قِ[q:8236[طْ]رًا","Менга темир парчаларини келтиринг», деди. Ниҳоят, икки тоғ томонлари ила баробарлашганда: «Дам уринглар», деди. Ниҳоят, у ни ўтга айлантиргач: «Олиб келинглар, устидан мис қуяман», деди.",303,16],["فَمَا [h:8237[ٱ]سْطَ[n[ـٰ]ع[o[ُوٓ][s[اْ] أ[a:8238[َن ي]َظْهَرُوهُ وَمَا [h:8239[ٱ]سْتَطَ[n[ـٰ]عُو[s[اْ] لَهُ[n[ۥ] نَ[q:8240[قْ]بًا","Бас, улар унинг устига чиқа олмадилар, уни тешиб ҳам ўта олмадилар.",303,16],["قَالَ هَ[n[ـٰ]ذَا رَحْمَ[a:8241[ةٌ م]ّ[u:4098[ِن ر]َّبِّى‌ۖ فَإِذَا ج[o[َا]ٓءَ وَعْدُ رَبِّى جَعَلَهُ[n[ۥ] دَكّ[o[َا]ٓءَ‌ۖ وَكَانَ وَعْدُ رَبِّى حَقًّا","У: «Бу Роббим раҳматидандир. Агар Роббимнинг ваъдаси келса, буни ер баробар қилур. Роббимнинг ваъдаси ҳақдир», деди.",304,16],["۞ وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِ[a:8242[ذٍ ي]َمُوجُ فِى بَعْ[a:8243[ضٍ‌ۖ و]َنُفِخَ فِى [h:4185[ٱ][l[ل]صُّورِ فَجَمَعْنَ[n[ـٰ]هُمْ جَمْعًا","Ўша куни уларни бир-бирлари ила мавж урган ҳолларида тарк этдик ва сур чалинди. Бас, уларнинг ҳаммаларини жамладик.",304,16],["وَعَرَضْنَا جَهَ[g[نّ]َمَ يَوْمَئِ[u:8244[ذٍ ل]ِّلْكَ[n[ـٰ]فِرِينَ عَرْضًا","Ўша куни кофирларга жаҳаннамни кўндаланг қилиб кўрсатдик.",304,16],["ٱلَّذِينَ كَانَتْ أَعْيُنُهُمْ فِى غِط[o[َا]ٓءٍ عَ[f:8245[ن ذ]ِكْرِى وَكَانُو[s[اْ] لَا يَسْتَطِيعُونَ سَمْعًا","Улар кўзлари Менинг зикримдан пардада бўлган ва эшитишга қодир бўла олмайдиганлар эдилар.",304,16],["أَفَحَسِبَ [h:8246[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أ[a:3250[َن ي]َتَّخِذُو[s[اْ] عِبَادِى مِ[f:7659[ن د]ُون[o[ِىٓ] أَوْلِي[o[َا]ٓءَ‌ۚ إِ[g[نّ][o[َآ] أَعْتَ[q:2660[دْ]نَا جَهَ[g[نّ]َمَ لِلْكَ[n[ـٰ]فِرِينَ نُزُلاً","Ёки куфр келтирганлар Мени қўйиб бандаларимни валий-илоҳ қилиб олишни гумон қилдиларми?! Албатта, Биз жаҳаннамни кофирларга манзил этиб тайёрлаганмиз.",304,16],["قُلْ هَلْ نُنَبِّئُك[c:8247[ُم ب]ِ[h:8248[ٱ]لْأَخْسَرِينَ أَعْمَ[n[ـٰ]لاً","Сен: «Сизга амаллари юзасидан энг зиёнкорларнинг хабарини берайми?",304,16],["ٱلَّذِينَ ضَلَّ سَعْيُهُمْ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا وَهُمْ يَحْسَبُونَ أَ[g[نّ]َهُمْ يُحْسِنُونَ صُنْعًا","Улар бу дунё ҳаётидаёқ сайъи-ҳаракатлари ботил бўлган, ўзлари эса, гўзал иш қиляпман, деб ҳисоблайдиганлардир», дегин.",304,16],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ رَبِّهِمْ وَلِق[o[َا]ٓئِه[n[ِۦ] فَحَبِطَتْ أَعْمَ[n[ـٰ]لُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ وَزْنًا","Ана ўшалар Роббилари оятларига ва унга рўбарў келишга куфр келтирганлардир. Бас, уларнинг амаллари ҳабата бўлди. Қиёмат куни уларга ҳеч қандай вазн бермасмиз.",304,16],["ذ[n[َٲ]لِكَ جَز[o[َا]ٓؤُهُمْ جَهَ[g[نّ]َمُ بِمَا كَفَرُو[s[اْ] وَ[h:8132[ٱ]تَّخَذ[o[ُوٓ][s[اْ] ءَايَ[n[ـٰ]تِى وَرُسُلِى هُزُوًا","Шунингдек, куфр келтирганлари ва Менинг оятларим ва Пайғамбарларимни масхара қилганлари сабабли уларнинг жазоси жаҳаннамдир.",304,16],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ كَانَتْ لَهُمْ جَ[g[نّ]َ[n[ـٰ]تُ [h:8249[ٱ]لْفِرْدَوْسِ نُزُلاً","Албатта, иймон келтирган ва яхши амалларни қилганларга Фирдавс жаннати манзил бўлгандир.",304,16],["خَ[n[ـٰ]لِدِينَ فِيهَا لَا يَ[q:2073[بْ]غُونَ عَنْهَا حِوَلاً","Унда абадий қолурлар ва ундан кўчишни истамаслар.",304,16],["قُل لَّوْ كَانَ [h:8250[ٱ]لْبَحْرُ مِدَا[u:8251[دًا ل]ِّكَلِمَ[n[ـٰ]تِ رَبِّى لَنَفِدَ [h:8252[ٱ]لْبَحْرُ قَ[q:3282[بْ]لَ أَ[f:8253[ن ت]َ[f:8254[نف]َدَ كَلِمَ[n[ـٰ]تُ رَبِّى وَلَوْ جِئْنَا بِمِثْلِه[n[ِۦ] مَدَدًا","Сен: «Агар денгиз Роббим калималарига сиёҳ бўлсаю унга ўз мислича мадад келтирсак ҳам, Роббим калималари тугашидан олдин денгиз тугаб қолур», дегин.",304,16],["قُلْ إِ[g[نّ]َم[o[َآ] أَنَا۟ بَشَ[a:7069[رٌ م]ِّثْلُكُمْ يُوحَ[o[ىٰٓ] إِلَىَّ أَ[g[نّ]َم[o[َآ] إِلَ[n[ـٰ]هُكُمْ إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[f:8255[دٌ‌ۖ ف]َمَ[f:954[ن ك]َانَ يَرْجُو[s[اْ] لِق[o[َا]ٓءَ رَبِّه[n[ِۦ] فَلْيَعْمَلْ عَمَل[f:5817[اً ص]َ[n[ـٰ]لِ[a:8256[حًا و]َلَا يُشْرِكْ بِعِبَادَةِ رَبِّه[o[ِۦٓ] أَحَدَۢا","Сен: «Мен ҳам сизларга ўхшаган башарман. Менга, шубҳасиз, илоҳингиз битта «илоҳ» экани ваҳий қилинди. Бас, ким Роббига рўбарў келишни умид қилса, яхши амал қилсин ва Робби ибодатига биронтани шерик қилмасин», дегин.",304,16]]},{"n":19,"ar":"مَرۡيَمَ","en":"Maryam","uz":"Марям","type":"Макка","ayahs":[["[m[كٓ]هي[m[عٓ][m[صٓ]","Кааф, ҳаа, йаа, айн, сод.",305,16],["ذِكْرُ رَحْمَتِ رَبِّكَ عَ[q:8257[بْ]دَهُ[n[ۥ] زَكَرِيَّآ","Бу, Роббингнинг бандаси Закариёга раҳмати зикридир.",305,16],["إِذْ نَادَىٰ رَبَّهُ[n[ۥ] نِد[o[َا]ٓءً خَفِيًّا","Унинг Роббига махфий нидо қилган чоғини эсла.",305,16],["قَالَ رَبِّ إِ[g[نّ]ِى وَهَنَ [h:8258[ٱ]لْعَظْمُ مِ[g[نّ]ِى وَ[h:8259[ٱ]شْتَعَلَ [h:8260[ٱ][l[ل]رَّأْسُ شَيْ[a:8261[بًا و]َلَمْ أَك[i:8262[ُنۢ ب]ِدُع[o[َا]ٓئِكَ رَبِّ شَقِيًّا","У: «Эй Роббим, менинг суякларим мўртлашди, бошга оқ туташди, эй Роббим, сенга дуо қилиш-ла бадбахт бўлмаганман.",305,16],["وَإِ[g[نّ]ِى خِفْتُ [h:8263[ٱ]لْمَو[n[َٲ]لِىَ م[a:8264[ِن و]َر[o[َا]ٓءِى وَكَانَتِ [h:8265[ٱ]مْرَأَتِى عَاقِ[f:8266[رًا ف]َهَ[q:8267[بْ] لِى م[u:1746[ِن ل]َّدُ[f:1747[نك]َ وَلِيًّا","Ва, албатта, мен ортимдаги қариндошлардан қўрқдим. Аёлим туғмас эди. Бас, менга Ўз даргоҳингдан бир валий–ортдан қолгувчи ато эт.",305,16],["يَرِثُنِى وَيَرِثُ مِنْ ءَالِ يَعْقُوبَ‌ۖ وَ[h:8268[ٱ][q:8268[جْ]عَلْهُ رَبِّ رَضِيًّا","У менга ва Яъқуб оиласига меросхўр бўлсин. Эй Роббим, уни Ўзинг рози бўладиган қил», деди.",305,16],["يَ[n[ـٰ]زَكَرِيّ[o[َآ] إِ[g[نّ]َا نُبَشِّرُكَ بِغُلَ[n[ـٰ]مٍ [h:8269[ٱ]سْمُهُ[n[ۥ] يَحْيَىٰ لَمْ نَ[q:8219[جْ]عَل لَّهُ[n[ۥ] مِ[f:128[ن ق]َ[q:129[بْ]لُ سَمِيًّا","Эй Закариё, Биз сенга исми Яҳё бўлган бир ўғилнинг хушхабарини берамиз. Бундан олдин унга отдош қилган эмасмиз.",305,16],["قَالَ رَبِّ أَ[g[نّ]َىٰ يَكُونُ لِى غُلَ[n[ـٰ][a:8270[مٌ و]َكَانَتِ [h:8265[ٱ]مْرَأَتِى عَاقِ[a:8271[رًا و]َقَ[q:387[دْ] بَلَغْتُ مِنَ [h:8272[ٱ]لْكِبَرِ عِتِيًّا","У: «Эй Роббим, аёлим туғмас бўлса, ўзим қариб-чириб қолган бўлсам, қандай қилиб менинг ўғлим бўлсин?!» деди.",305,16],["قَالَ كَذ[n[َٲ]لِكَ قَالَ رَبُّكَ هُوَ عَلَىَّ هَيِّ[a:8273[نٌ و]َقَ[q:387[دْ] خَلَ[q:8274[قْ]تُكَ مِ[f:128[ن ق]َ[q:129[بْ]لُ وَلَمْ تَكُ شَيْــًٔا","У: «Ана шундай! Роббинг айтдики, бу мен учун осон. Батаҳқиқ, бундан олдин сени яратдим. Ҳолбуки, сен ҳеч нарса эмас эдинг», деди.",305,16],["قَالَ رَبِّ [h:657[ٱ][q:658[جْ]عَل لّ[o[ِىٓ] ءَايَ[f:1895[ةً‌ۚ ق]َالَ ءَايَتُكَ أَلَّا تُكَلِّمَ [h:1896[ٱ][l[ل][g[نّ]َاسَ ثَلَ[n[ـٰ]ثَ لَيَا[f:8275[لٍ س]َوِيًّا","У: «Роббим, менга бир белги ато қил», деди. У зот: «Сенинг белгинг саломат ҳолингда, одамларга уч кеча гапирмаслигингдир», деди.",305,16],["فَخَرَجَ عَلَىٰ قَوْمِه[n[ِۦ] مِنَ [h:8276[ٱ]لْمِحْرَابِ فَأَوْحَ[o[ىٰٓ] إِلَيْهِمْ أَ[f:8277[ن س]َبِّحُو[s[اْ] بُكْرَ[a:8278[ةً و]َعَشِيًّا","Бас, у ўз қавми ҳузурига меҳробдан чиқди ва уларга, эртаю кеч тасбиҳ айтинглар, деб ишора қилди.",305,16],["يَ[n[ـٰ]يَحْيَىٰ خُذِ [h:8279[ٱ]لْكِتَ[n[ـٰ]بَ بِقُوَّ[a:8280[ةٍ‌ۖ و]َءَاتَيْنَ[n[ـٰ]هُ [h:8281[ٱ]لْحُكْمَ صَبِيًّا","«Эй Яҳё, китобни қувват-ла ол!» ва унга гўдаклигидаёқ ҳукмни бердик.",306,16],["وَحَنَا[a:8282[نًا م]ّ[u:2897[ِن ل]َّدُ[g[نّ]َا وَزَكَ[s[و][n[ٲ][a:8283[ةً‌ۖ و]َكَانَ تَقِيًّا","Ва Ўз томонимиздан меҳрибонлик ва поклик. Ҳамда у тақводор эди.",306,16],["وَبَرّ[i:8284[َۢا ب]ِو[n[َٲ]لِدَيْهِ وَلَمْ يَكُ[f:8285[ن ج]َبَّارًا عَصِيًّا","У ота-онасига меҳрибон бўлиб, жабр-ситам қилгувчи ва исёнчи эмасди.",306,16],["وَسَلَ[n[ـٰ]مٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُ[q:8286[بْ]عَثُ حَيًّا","Унга туғилган кунида ҳам, ўладиган кунида ҳам, қайта тириладиган кунида ҳам саломлар бўлсин.",306,16],["وَ[h:9999[ٱ]ذْكُرْ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ مَرْيَمَ إِذِ [h:8287[ٱ][f:8288[نت]َبَذَتْ مِنْ أَهْلِهَا مَكَا[f:8289[نًا ش]َرْقِيًّا","Китобда Марямни эсла. У ўз аҳлидан шарқий маконга ажраб чиққанда.",306,16],["فَ[h:9999[ٱ]تَّخَذَتْ مِ[f:5400[ن د]ُونِهِمْ حِجَا[f:8290[بًا ف]َأَرْسَلْن[o[َآ] إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَ[f:8291[رًا س]َوِيًّا","Ва улар билан ўзи орасида тўсиқ олганда, Биз унга Ўз руҳимизни юбордик. Бас, у унга бус-бутун одам бўлиб кўринди.",306,16],["قَالَتْ إِ[g[نّ][o[ِىٓ] أَعُوذُ بِ[h:6981[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ مِ[f:3891[نك]َ إِ[f:4792[ن ك]ُ[f:735[نت]َ تَقِيًّا","У: «Мен сендан Аллоҳ паноҳ беришини сўрайман. Агар тақводор бўлсанг...» деди.",306,16],["قَالَ إِ[g[نّ]َم[o[َآ] أَنَا۟ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَ[n[ـٰ][f:8292[مًا ز]َكِيًّا","У: «Мен Роббингнинг элчисиман, холос, сенга бир пок ўғилни ҳадя этиш учун келдим», деди.",306,16],["قَالَتْ أَ[g[نّ]َىٰ يَكُونُ لِى غُلَ[n[ـٰ][a:8293[مٌ و]َلَمْ يَمْسَسْنِى بَشَ[a:8294[رٌ و]َلَمْ أَكُ بَغِيًّا","У: « Менда қаёқдан ўғил бўлсин, менга башар тегмаган бўлса, мен бузуқ ҳам бўлмасам?!» деди.",306,16],["قَالَ كَذ[n[َٲ]لِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّ[a:8295[نٌ‌ۖ و]َلِنَ[q:8296[جْ]عَلَهُ[o[ۥٓ] ءَايَ[u:1516[ةً ل]ِّل[g[نّ]َاسِ وَرَحْمَ[a:8297[ةً م]ِّ[g[نّ]َا‌ۚ وَكَانَ أَمْ[a:8298[رًا م]َّ[q:8299[قْ]ضِيًّا","У: «Ана шундай, Роббинг айтдики, бу Мен учун осондир ва уни одамларга белги қилиш учун ҳамда Биздан раҳмат бўлиш учун, бу, ҳукми чиқиб бўлган ишдир», деди.",306,16],["۞ فَحَمَلَتْهُ فَ[h:8300[ٱ][f:8300[نت]َبَذَتْ بِه[n[ِۦ] مَكَا[f:8301[نًا ق]َصِيًّا","Бас, унга ҳомиладор бўлди. Сўнгра у билан узоқ маконга четланди.",306,16],["فَأَج[o[َا]ٓءَهَا [h:8302[ٱ]لْمَخَاضُ إِلَىٰ جِذْعِ [h:8303[ٱ][l[ل][g[نّ]َخْلَةِ قَالَتْ يَ[n[ـٰ]لَيْتَنِى مِتُّ قَ[q:3282[بْ]لَ هَ[n[ـٰ]ذَا وَكُ[f:3900[نت]ُ نَسْ[a:8304[يًا م]َّ[f:8305[نس]ِيًّا","Бас, тўлғоқ уни хурмо танасига олиб борди. У: «Кошки бундан олдин ўлсам эди ва бутунлай унутилиб кетсам эди», деди.",306,16],["فَنَادَ[n[ٮٰ]هَا مِ[f:121[ن ت]َحْتِه[o[َآ] أَلَّا تَحْزَنِى قَ[q:298[دْ] جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا","Унинг остидан: «Маҳзун бўлма, батаҳқиқ, Роббинг остингдан оқар ариқ қилди.",306,16],["وَهُزّ[o[ِىٓ] إِلَيْكِ بِجِذْعِ [h:8306[ٱ][l[ل][g[نّ]َخْلَةِ تُسَ[n[ـٰ]قِ[q:8307[طْ] عَلَيْكِ رُطَ[f:8308[بًا ج]َنِيًّا","Хурмо танасини силкит, сенга янги мева туширади», деб нидо қилди.",306,16],["فَكُلِى وَ[h:8309[ٱ]شْرَبِى وَقَرِّى عَيْ[f:8310[نًا‌ۖ ف]َإِ[g[مّ]َا تَرَيِ[g[نّ]َ مِنَ [h:8311[ٱ]لْبَشَرِ أَحَ[f:8312[دًا ف]َقُول[o[ِىٓ] إِ[g[نّ]ِى نَذَرْتُ لِلرَّحْمَ[n[ـٰ]نِ صَوْ[f:8313[مًا ف]َلَنْ أُكَلِّمَ [h:8314[ٱ]لْيَوْمَ إِ[f:8315[نس]ِيًّا","Е, ич ва кўзинг қувонсин. Бас, бирор одамни кўрар бўлсанг: «Мен Роҳманга рўза назр қилдим. Бугун инсон зотига зинҳор гапирмасман», дегин.",307,16],["فَأَتَتْ بِه[n[ِۦ] قَوْمَهَا تَحْمِلُهُ[n[ۥ]‌ۖ قَالُو[s[اْ] يَ[n[ـٰ]مَرْيَمُ لَقَ[q:2389[دْ] جِئْتِ شَيْـ[f:8316[ـًٔا ف]َرِيًّا","Бас, уни кўтариб қавмига олиб келди. Улар: «Эй Марям, сен ажойиб нарса келтирдинг-ку!",307,16],["يَ[o[ـٰٓ]أُخْتَ هَ[n[ـٰ]رُونَ مَا كَانَ أَبُوكِ [h:8317[ٱ]مْرَأَ سَوْ[a:8318[ءٍ و]َمَا كَانَتْ أُ[g[مّ]ُكِ بَغِيًّا","Эй Ҳорун синглиси, отанг ёмон одаммас ва онанг ҳам бузуқ бўлмаган эди-ку!» дедилар.",307,16],["فَأَشَارَتْ إِلَيْهِ‌ۖ قَالُو[s[اْ] كَيْفَ نُكَلِّمُ مَ[f:506[ن ك]َانَ فِى [h:1921[ٱ]لْمَهْدِ صَبِيًّا","Бас, у унга ишорат қилди. Улар: «Бешикдаги гўдак ила қандай гаплашамиз?!» дедилар.",307,16],["قَالَ إِ[g[نّ]ِى عَ[q:8319[بْ]دُ [h:8320[ٱ]للَّهِ ءَاتَ[n[ـٰ]نِىَ [h:8321[ٱ]لْكِتَ[n[ـٰ]بَ وَجَعَلَنِى نَبِيًّا","У: «Албатта, мен Аллоҳнинг бандасиман. У менга китоб берди ва мени Пайғамбар қилди.",307,16],["وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُ[f:2917[نت]ُ وَأَوْصَ[n[ـٰ]نِى بِ[h:8322[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ وَ[h:8323[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةِ مَا دُمْتُ حَيًّا","Мени қаерда бўлсам ҳам, муборак қилди. Модомики ҳаёт эканман, намоз ва закотни адо этмоқни тавсия қилди.",307,16],["وَبَرّ[i:8324[َۢا ب]ِو[n[َٲ]لِدَتِى وَلَمْ يَ[q:8325[جْ]عَلْنِى جَبَّا[f:8326[رًا ش]َقِيًّا","Мени онамга меҳрибон қилди ва жабр-ситам қилгувчи, бадбахт қилмади.",307,16],["وَ[h:9999[ٱ][l[ل]سَّلَ[n[ـٰ]مُ عَلَىَّ يَوْمَ وُلِ[d:8327[د]تُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُ[q:8328[بْ]عَثُ حَيًّا","Менга туғилган кунимда ҳам, ўладиган кунимда ҳам ва қайта тириладиган кунимда ҳам салом бордир«, деди.",307,16],["ذ[n[َٲ]لِكَ عِيسَى [h:1916[ٱ][q:1917[بْ]نُ مَرْيَمَ‌ۚ قَوْلَ [h:8329[ٱ]لْحَقِّ [h:8330[ٱ]لَّذِى فِيهِ يَمْتَر[p[ُو]نَ","Мана шу шубҳа қилишаётган Ийсо ибн Марям тўғрисидаги ҳақ сўздир.",307,16],["مَا كَانَ لِلَّهِ أ[a:8331[َن ي]َتَّخِذَ م[a:8332[ِن و]َلَ[f:8333[دٍ‌ۖ س]ُ[q:608[بْ]حَ[n[ـٰ]نَهُ[o[ۥٓ‌ۚ] إِذَا قَضَ[o[ىٰٓ] أَمْ[f:612[رًا ف]َإِ[g[نّ]َمَا يَقُولُ لَهُ[n[ۥ] كُ[f:613[ن ف]َيَك[p[ُو]نُ","Бола тутмоқ Аллоҳга ҳеч тўғри келмас. У бундан покдир. У бир ишни истаса, унга «Бўл!» дейдир. Бас, бўладир.",307,16],["وَإِ[g[نّ]َ [h:1986[ٱ]للَّهَ رَبِّى وَرَبُّكُمْ فَ[h:1946[ٱ]عْبُدُوهُ‌ۚ هَ[n[ـٰ]ذَا صِر[n[َٲ][a:1947[طٌ م]ُّسْتَق[p[ِي]مٌ","«Ва, албатта, Аллоҳ менинг Роббимдир ва сизнинг Роббингиздир. Бас, Унга ибодат қилинг. Мана шу тўғри йўлдир».",307,16],["فَ[h:9999[ٱ]خْتَلَفَ [h:8334[ٱ]لْأَحْزَابُ م[i:8335[ِنۢ ب]َيْنِهِمْ‌ۖ فَوَيْ[u:396[لٌ ل]ِّلَّذِينَ كَفَرُو[s[اْ] م[a:8336[ِن م]َّشْهَدِ يَوْمٍ عَظ[p[ِي]مٍ","Сўнгра фирқалар ўзаро ихтилофга тушдилар. Куфр келтирганларга буюк кундаги кўринишдан вой бўлсин.",307,16],["أَسْمِعْ بِهِمْ وَأَ[q:8337[بْ]صِرْ يَوْمَ يَأْتُونَنَا‌ۖ لَ[n[ـٰ]كِنِ [h:8338[ٱ][l[ل]ظَّ[n[ـٰ]لِمُونَ [h:8339[ٱ]لْيَوْمَ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Бизга келадиган куни қандай ҳам яхши эшитадилар, қандай ҳам яхши кўрадилар. Лекин золимлар бугунги кунда очиқ залолатдадирлар.",307,16],["وَأَ[f:8340[نذ]ِرْهُمْ يَوْمَ [h:8341[ٱ]لْحَسْرَةِ إِذْ قُضِىَ [h:6667[ٱ]لْأَمْرُ وَهُمْ فِى غَفْلَ[a:8342[ةٍ و]َهُمْ لَا يُؤْمِن[p[ُو]نَ","Уларни ҳасрат кунидан, иш битмиш пайтидан огоҳ қил. Улар ғафлатдадирлар, улар иймон келтирмаслар.",308,16],["إِ[g[نّ]َا نَحْنُ نَرِثُ [h:8343[ٱ]لْأَرْضَ وَمَنْ عَلَيْهَا وَإِلَيْنَا يُرْجَع[p[ُو]نَ","Албатта, Биз ерга ва унинг устидаги кимсаларга меросхўр бўламиз ва Бизгагина қайтурлар.",308,16],["وَ[h:9999[ٱ]ذْكُرْ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ صِدِّي[a:8344[قًا ن]َّبِيًّا","Китобда Иброҳимни эсла. Албатта, у сиддиқ ва Набий бўлган эди.",308,16],["إِذْ قَالَ لِأَبِيهِ يَ[o[ـٰٓ]أَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُ[q:8345[بْ]صِرُ وَلَا يُغْنِى عَ[f:626[نك]َ شَيْــًٔا","Қачонки у отасига: «Эй отам, нима учун эшитмайдиган, кўрмайдиган ва сенга бирон фойда бера олмайдиган нарсага ибодат қиласан?",308,16],["يَ[o[ـٰٓ]أَبَتِ إِ[g[نّ]ِى قَ[q:298[دْ] ج[o[َا]ٓءَنِى مِنَ [h:634[ٱ]لْعِلْمِ مَا لَمْ يَأْتِكَ فَ[h:8346[ٱ]تَّبِعْن[o[ِىٓ] أَهْدِكَ صِر[n[َٲ][f:8347[طًا س]َوِيًّا","Эй отам, албатта, сенга келмаган илм менга келди. Бас, менга эргаш, сени тўғри йўлга бошлайман.",308,16],["يَ[o[ـٰٓ]أَبَتِ لَا تَعْبُدِ [h:8348[ٱ][l[ل]شَّيْطَ[n[ـٰ]نَ‌ۖ إِ[g[نّ]َ [h:4634[ٱ][l[ل]شَّيْطَ[n[ـٰ]نَ كَانَ لِلرَّحْمَ[n[ـٰ]نِ عَصِيًّا","Эй отам, шайтонга ибодат қилма. Албатта, шайтон Роҳманга осий бўлгандир.",308,16],["يَ[o[ـٰٓ]أَبَتِ إِ[g[نّ][o[ِىٓ] أَخَافُ أ[a:8349[َن ي]َمَسَّكَ عَذَا[a:8350[بٌ م]ِّنَ [h:8351[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ فَتَكُونَ لِلشَّيْطَ[n[ـٰ]نِ وَلِيًّا","Эй отам, албатта, мен сени Роҳман томонидан азоб тутишидан ва шайтонга дўст бўлиб қолишингдан қўрқаман», деган эди.",308,16],["قَالَ أَرَاغِبٌ أَ[f:169[نت]َ عَنْ ءَالِهَتِى يَ[o[ـٰٓ]إِ[q:6429[بْ]ر[n[َٲ]هِيمُ‌ۖ لَئ[u:4195[ِن ل]َّمْ تَ[f:8352[نت]َهِ لَأَرْجُمَ[g[نّ]َكَ‌ۖ وَ[h:8353[ٱ]هْجُرْنِى مَلِيًّا","У: «Эй Иброҳим, сен менинг худоларимдан юз ўгирувчимисан?! Қасамки, агар тўхтамасанг, сени, албатта, тошбўрон қиламан! Мендан узоқ кет!» деди.",308,16],["قَالَ سَلَ[n[ـٰ]مٌ عَلَيْكَ‌ۖ سَأَسْتَغْفِرُ لَكَ رَبّ[o[ِىٓ‌ۖ] إِ[g[نّ]َهُ[n[ۥ] كَانَ بِى حَفِيًّا","У: «Омон бўл. Энди Роббимдан сени мағфират қилишини сўрайман. Албатта, у менга жуда ҳам лутфи марҳаматлидир.",308,16],["وَأَعْتَزِلُكُمْ وَمَا تَ[q:4040[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَأَ[q:8354[دْ]عُو[s[اْ] رَبِّى عَسَ[o[ىٰٓ] أَلّ[o[َآ] أَكُونَ بِدُع[o[َا]ٓءِ رَبِّى شَقِيًّا","Мен сизлардан ҳам, Аллоҳдан ўзга илтижо қилаётган нарсангиздан ҳам четланаман ва Роббимга илтижо қиламан. Шоядки, Роббимга илтижо қилиш ила бадбахт бўлмасам», деди.",308,16],["فَلَ[g[مّ]َا [h:8355[ٱ]عْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَهَ[q:8356[بْ]نَا لَهُ[o[ۥٓ] إِسْحَ[n[ـٰ]قَ وَيَعْقُوبَ‌ۖ وَكُل[f:8357[اًّ ج]َعَلْنَا نَبِيًّا","Бас, улардан ва улар Аллоҳдан ўзга ибодат қилаётган нарсадан четланганида, Биз унга Исҳоқ ва Яъқубни ҳадя этдик ва барчаларини Пайғамбар қилдик.",308,16],["وَوَهَ[q:4212[بْ]نَا لَه[w:1812[ُم م]ّ[u:8358[ِن ر]َّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِ[q:5937[دْ]قٍ عَلِيًّا","Ва уларга Ўз раҳматимиздан ҳадя этдик ҳамда уларга ростгўй ва олий тил бердик.",308,16],["وَ[h:9999[ٱ]ذْكُرْ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ مُوسَ[o[ىٰٓ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] كَانَ مُخْلَ[a:8359[صًا و]َكَانَ رَسُول[a:8360[اً ن]َّبِيًّا","Китобда Мусони эсла. Албатта, у танлаб олинган Набий ва Расул эди.",308,16],["وَنَ[n[ـٰ]دَيْنَ[n[ـٰ]هُ مِ[f:8361[ن ج]َانِبِ [h:8362[ٱ][l[ل]طُّورِ [h:8363[ٱ]لْأَيْمَنِ وَقَرَّ[q:8364[بْ]نَ[n[ـٰ]هُ نَجِيًّا","Биз унга Турнинг ўнг томонидан нидо қилдик ва муножот учун Ўзимизга яқинлаштирдик.",309,16],["وَوَهَ[q:4212[بْ]نَا لَهُ[n[ۥ] م[u:8358[ِن ر]َّحْمَتِن[o[َآ] أَخَاهُ هَ[n[ـٰ]رُونَ نَبِيًّا","Ва унга Ўз раҳматимиздан оғаси Ҳорунни Пайғамбар қилиб ҳадя этдик.",309,16],["وَ[h:9999[ٱ]ذْكُرْ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ إِسْمَ[n[ـٰ]عِيلَ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ صَادِقَ [h:8365[ٱ]لْوَعْدِ وَكَانَ رَسُول[a:8360[اً ن]َّبِيًّا","Ва китобда Исмоилни эсла. Албатта, у ваъдасига содиқ ҳамда Расул ва Набий бўлган эди.",309,16],["وَكَانَ يَأْمُرُ أَهْلَهُ[n[ۥ] بِ[h:8322[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ وَ[h:8323[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةِ وَكَانَ عِ[f:264[ند]َ رَبِّه[n[ِۦ] مَرْضِيًّا","У аҳлини намозга ва закотга буюрар эди ва Робби наздида рози бўлган эди.",309,16],["وَ[h:9999[ٱ]ذْكُرْ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ إِ[q:8366[دْ]رِيسَ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ صِدِّي[a:8344[قًا ن]َّبِيًّا","Ва китобда Идрисни эсла. Албатта, у сиддиқ ва Набий бўлган эди.",309,16],["وَرَفَعْنَ[n[ـٰ]هُ مَكَانًا عَلِيًّا","Ва уни олий мақомга кўтардик.",309,16],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ أَنْعَمَ [h:2900[ٱ]للَّهُ عَلَيْه[w:2901[ِم م]ِّنَ [h:2902[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ مِ[f:4433[ن ذ]ُرِّيَّةِ ءَادَمَ وَمِ[g[مّ]َنْ حَمَلْنَا مَعَ نُو[a:8367[حٍ و]َمِ[f:8368[ن ذ]ُرِّيَّةِ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَإِسْر[o[َٲ]ٓءِيلَ وَمِ[g[مّ]َنْ هَدَيْنَا وَ[h:8369[ٱ][q:8369[جْ]تَبَيْن[o[َآ‌ۚ] إِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَ[n[ـٰ]تُ [h:8370[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ خَرُّو[s[اْ] سُجَّ[a:8371[دًا و]َبُكِيًّا ۩","Ана ўшалар, Аллоҳ неъмат берган зотлар, Пайғамбарлардан, Одам зурриётидан, Нуҳ билан бирга кўтарганларимиздан, Иброҳим ва Исроилнинг зурриётидан, Ўзимиз ҳидоят қилган ва танлаб олганлардан бўлган зотлар, уларга Роҳманнинг ояти тиловат қилинса, йиғлаб саждага йиқилардилар.",309,16],["۞ فَخَلَفَ م[i:1453[ِنۢ ب]َعْدِهِمْ خَلْفٌ أَضَاعُو[s[اْ] [h:8372[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَ[h:2433[ٱ]تَّبَعُو[s[اْ] [h:8373[ٱ][l[ل]شَّهَو[n[َٲ]تِ‌ۖ فَسَوْفَ يَلْقَوْنَ غَيًّا","Бас, уларнинг ортидан бир ўринбосарлар қолдики, улар намозни зое қилиб, шаҳватларга эргашдилар. Бас, тезда улар ёмонликка йўлиқдилар.",309,16],["إِلَّا مَ[f:8374[ن ت]َابَ وَءَامَنَ وَعَمِلَ صَ[n[ـٰ]لِ[f:8375[حًا ف]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يَ[q:3156[دْ]خُلُونَ [h:3157[ٱ]لْجَ[g[نّ]َةَ وَلَا يُظْلَمُونَ شَيْــًٔا","Магар ким тавба қилса ва иймон келтириб, амали солиҳ қилса, бас, ана ўшалар жаннатга кирурлар ва ҳеч зулм қилинмаслар.",309,16],["جَ[g[نّ]َ[n[ـٰ]تِ عَ[q:5720[دْ]نٍ [h:8376[ٱ]لَّتِى وَعَدَ [h:8377[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ عِبَادَهُ[n[ۥ] بِ[h:13[ٱ]لْغَيْبِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ وَعْدُهُ[n[ۥ] مَأْتِيًّا","Роҳман Ўз бандаларига ғайбдан ваъда қилган адн жаннатларидир. Албатта, Унинг ваъдаси келгусидир.",309,16],["لَّا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَ[n[ـٰ][a:8378[مًا‌ۖ و]َلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَ[a:8278[ةً و]َعَشِيًّا","Улар унда беҳуда сўз эшитмаслар, илло, салом эшитурлар. Уларга у ерда эртаю кеч ризқлари келиб турур.",309,16],["تِلْكَ [h:8379[ٱ]لْجَ[g[نّ]َةُ [h:8380[ٱ]لَّتِى نُورِثُ مِنْ عِبَادِنَا مَ[f:506[ن ك]َانَ تَقِيًّا","У жаннат, бандаларимиздан тақводор бўлганларига мерос қилиб берадиган жаннатимиздир.",309,16],["وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ‌ۖ لَهُ[n[ۥ] مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذ[n[َٲ]لِكَ‌ۚ وَمَا كَانَ رَبُّكَ نَسِيًّا","Биз фақат Роббингнинг амри билангина тушамиз. Бизнинг олдимиздаги нарсалар ва ортимиздаги нарсалар ҳамда уларнинг орасидаги нарсалар ҳам Уникидир. Роббинг унутгувчи бўлмаган.",309,16],["رَّبُّ [h:6926[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَيْنَهُمَا فَ[h:6540[ٱ]عْبُ[q:6540[دْ]هُ وَ[h:8381[ٱ]صْطَبِرْ لِعِبَ[n[ـٰ]دَتِه[n[ِۦ]‌ۚ هَلْ تَعْلَمُ لَهُ[n[ۥ] سَمِيًّا","У осмонлару ернинг ва улар орасидаги нарсаларнинг Роббидир. Бас, Унга ибодат қил ва Унинг ибодатида сабрли бўл. Унга тенгдошни билурмисан?",310,16],["وَيَقُولُ [h:8382[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ أَءِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا","Инсон: «Агар ўлсам, яна қайта тирик ҳолда чиқариламанми?!» дейди.",310,16],["أَوَلَا يَذْكُرُ [h:8383[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ أَ[g[نّ]َا خَلَ[q:7232[قْ]نَ[n[ـٰ]هُ مِ[f:128[ن ق]َ[q:129[بْ]لُ وَلَمْ يَكُ شَيْــًٔا","Ўша инсон Биз уни бундан олдин ҳеч нарса бўлмай турганида яратганимизни эсламайдими?!",310,16],["فَوَرَبِّكَ لَنَحْشُرَ[g[نّ]َهُمْ وَ[h:8384[ٱ][l[ل]شَّيَ[n[ـٰ]طِينَ ثُ[g[مّ]َ لَنُحْضِرَ[g[نّ]َهُمْ حَوْلَ جَهَ[g[نّ]َمَ جِثِيًّا","Роббингга қасамки, Биз уларни ва шайтонларни, албатта, маҳшарга тўплаймиз, сўнгра уларни жаҳаннам атрофига тиз чўккан ҳолларида ҳозир қиламиз.",310,16],["ثُ[g[مّ]َ لَنَ[f:8385[نز]ِعَ[g[نّ]َ مِ[f:843[ن ك]ُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى [h:8386[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ عِتِيًّا","Сўнгра ҳар бир гуруҳдан Роҳманга ашаддий осий бўлганини суғуриб оламиз.",310,16],["ثُ[g[مّ]َ لَنَحْنُ أَعْلَمُ بِ[h:2413[ٱ]لَّذِينَ هُمْ أَوْلَىٰ بِهَا صِلِيًّا","Кейин, албатта, Биз уга киришга кимлар лойиқроқ эканини яхши билгувчимиз.",310,16],["وَإ[a:8387[ِن م]ِّ[f:344[نك]ُمْ إِلَّا وَارِدُهَا‌ۚ كَانَ عَلَىٰ رَبِّكَ حَتْ[a:8388[مًا م]َّ[q:8299[قْ]ضِيًّا","Сиздан унга яқинлашувчи бўлмаган ҳеч ким йўқ. Бу Роббинг ҳузуридаги кескин ҳукмдир.",310,16],["ثُ[g[مّ]َ نُنَجِّى [h:8389[ٱ]لَّذِينَ [h:7007[ٱ]تَّقَو[s[اْ] وَّنَذَرُ [h:8390[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ فِيهَا جِثِيًّا","Сўнгра тақво қилганларга нажот берамиз ва золимларни унда тиз чўккан ҳолларида қолдирамиз.",310,16],["وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَ[n[ـٰ]تُنَا بَيِّنَ[n[ـٰ][f:5979[تٍ ق]َالَ [h:590[ٱ]لَّذِينَ كَفَرُو[s[اْ] لِلَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَىُّ [h:8391[ٱ]لْفَرِيقَيْنِ خَيْ[a:8392[رٌ م]َّقَا[a:8393[مًا و]َأَحْسَنُ نَدِيًّا","Қачонки уларга Бизнинг равшан оятларимиз тиловат қилинса, куфр келтирганлар иймон келтирганларга: «Икки гуруҳнинг қайси бири мақом ва мажлис жиҳатидан яхшироқдир?» дерлар.",310,16],["وَكَمْ أَهْلَكْنَا قَ[q:8394[بْ]لَه[w:8395[ُم م]ِّ[f:3927[ن ق]َرْنٍ هُمْ أَحْسَنُ أَثَ[n[ـٰ][a:8396[ثًا و]َرِءْيًا","Ҳолбуки, Биз улардан олдин мол ва кўриниш жиҳатидан яхшироқ бўлган қанчадан-қанча асрларни ҳалок қилганмиз.",310,16],["قُلْ مَ[f:506[ن ك]َانَ فِى [h:8397[ٱ][l[ل]ضَّلَ[n[ـٰ]لَةِ فَلْيَمْدُ[q:8398[دْ] لَهُ [h:8399[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ مَدًّا‌ۚ حَتَّ[o[ىٰٓ] إِذَا رَأَوْ[s[اْ] مَا يُوعَدُونَ إِ[g[مّ]َا [h:8400[ٱ]لْعَذَابَ وَإِ[g[مّ]َا [h:8401[ٱ][l[ل]سَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَ[a:3659[رٌّ م]َّكَا[a:8402[نًا و]َأَضْعَفُ جُ[f:8403[ند]ًا","Сен: «Ким залолатда бўлса, Роҳман унга муҳлат бериб қўйсин. Токи ўзларига ваъда қилинган нарсани — азобни ёки қиёматни кўрганларида, албатта, кимнинг мартабаси ёмонроқ ва аскари кучсизроқ эканини билурлар», дегин.",310,16],["وَيَزِيدُ [h:8404[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ [h:8405[ٱ]هْتَدَوْ[s[اْ] هُ[a:8406[دًى‌ۗ و]َ[h:8105[ٱ]لْبَ[n[ـٰ]قِيَ[n[ـٰ]تُ [h:8106[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تُ خَيْرٌ عِ[f:264[ند]َ رَبِّكَ ثَوَا[a:8095[بًا و]َخَيْ[a:8407[رٌ م]َّرَدًّا","Ва Аллоҳ ҳидоятга юрганларнинг ҳидоятини зиёда қиладир. Боқий қолувчи, солиҳ амаллар, Роббинг наздида, савоб жиҳатидан яхшироқдир ва оқибат жиҳатидан яхшироқдир.",310,16],["أَفَرَءَيْتَ [h:8408[ٱ]لَّذِى كَفَرَ بِـَٔـايَ[n[ـٰ]تِنَا وَقَالَ لَأُوتَيَ[g[نّ]َ مَال[a:8080[اً و]َوَلَدًا","Оятларимизга куфр келтирган ва: «Албатта, менга молу дунё ҳамда бола-чақа берилажак», деганни кўрдингми?!",311,16],["أَطَّلَعَ [h:8409[ٱ]لْغَيْبَ أَمِ [h:8410[ٱ]تَّخَذَ عِ[f:264[ند]َ [h:8411[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ عَهْدًا","У ғойибни билармикан ёки Роҳманнинг ҳузуридан аҳду паймон олдимикан?!",311,16],["كَلَّا‌ۚ سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُ[n[ۥ] مِنَ [h:503[ٱ]لْعَذَابِ مَدًّا","Йўқ! Нима деганини, албатта, ёзиб қўямиз ва унга азобни узундан-узоқ қиламиз.",311,16],["وَنَرِثُهُ[n[ۥ] مَا يَقُولُ وَيَأْتِينَا فَرْدًا","У айтаётган нарсага меросхўр бўлурмиз ва у бизга ёлғиз ҳолида келур.",311,16],["وَ[h:9999[ٱ]تَّخَذُو[s[اْ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ ءَالِهَ[u:8412[ةً ل]ِّيَكُونُو[s[اْ] لَهُمْ عِزًّا","Улар ўзларига куч-қудрат, иззат бўлиши учун Аллоҳдан ўзгаларни худо қилиб оладилар.",311,16],["كَلَّا‌ۚ سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا","Йўқ! улар уларнинг ибодатларини инкор этурлар ва уларга зид бўлурлар.",311,16],["أَلَمْ تَرَ أَ[g[نّ][o[َآ] أَرْسَلْنَا [h:8413[ٱ][l[ل]شَّيَ[n[ـٰ]طِينَ عَلَى [h:468[ٱ]لْكَ[n[ـٰ]فِرِينَ تَؤُزُّهُمْ أَزًّا","Биз шайтонларни кофирларга уларни доимий қўзғаб туришга юборганимизни кўрмадингми?",311,16],["فَلَا تَعْجَلْ عَلَيْهِمْ‌ۖ إِ[g[نّ]َمَا نَعُدُّ لَهُمْ عَدًّا","Уларнинг зиддига шошилма! Биз уларнинг саноғини санамоқдамиз.",311,16],["يَوْمَ نَحْشُرُ [h:8414[ٱ]لْمُتَّقِينَ إِلَى [h:8415[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ وَفْدًا","Тақводорларни Роҳман ҳузурига меҳмон ҳайъати этиб тўплаган кунимизда.",311,16],["وَنَسُوقُ [h:8416[ٱ]لْمُ[q:4093[جْ]رِمِينَ إِلَىٰ جَهَ[g[نّ]َمَ وِرْدًا","Жиноятчиларни жаҳаннамга чанқоқ ҳолларида ҳайдаймиз.",311,16],["لَّا يَمْلِكُونَ [h:8417[ٱ][l[ل]شَّفَ[n[ـٰ]عَةَ إِلَّا مَنِ [h:8418[ٱ]تَّخَذَ عِ[f:264[ند]َ [h:8411[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ عَهْدًا","Улар шафоатга молик бўлмаслар. Магар ким Роҳман ҳузурида аҳду паймон олган бўлса.",311,16],["وَقَالُو[s[اْ] [h:605[ٱ]تَّخَذَ [h:8419[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ وَلَدًا","Улар: «Роҳман бола тутди», дедилар.",311,16],["لَّقَ[q:2389[دْ] جِئْتُمْ شَيْــًٔا إِدًّا","Батаҳқиқ, жуда оғир нарса келтирдингиз.",311,16],["تَكَادُ [h:8420[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تُ يَتَفَطَّرْنَ مِنْهُ وَتَ[f:8421[نش]َقُّ [h:8422[ٱ]لْأَرْضُ وَتَخِرُّ [h:8423[ٱ]لْجِبَالُ هَدًّا","Ундан осмонлар парчаланиб, ер ёрилиб, тоғлар қулаб йиқилай, дейдир.",311,16],["أَ[f:8424[ن د]َعَوْ[s[اْ] لِلرَّحْمَ[n[ـٰ]نِ وَلَدًا","Роҳманнинг боласи бор, деганларига.",311,16],["وَمَا يَ[i:8425[نۢب]َغِى لِلرَّحْمَ[n[ـٰ]نِ أ[a:8331[َن ي]َتَّخِذَ وَلَدًا","Роҳманга бола тутиш лойиқ эмасдир.",311,16],["إِ[f:8426[ن ك]ُلُّ مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ إِلّ[o[َآ] ءَاتِى [h:8427[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ عَ[q:3317[بْ]دًا","Осмонлару ердаги барча кимсалар Роҳманга банда бўлган ҳолларида келурлар.",311,16],["لَّقَ[q:2389[دْ] أَحْصَ[n[ـٰ]هُمْ وَعَدَّهُمْ عَدًّا","Батаҳқиқ, У зот уларни иҳота қилган ва санаб қўйгандир.",311,16],["وَكُلُّهُمْ ءَاتِيهِ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ فَرْدًا","Уларнинг барчалари У зотнинг ҳузурига қиёмат куни ёлғиз ҳолларида келгувчидирлар.",311,16],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ سَيَ[q:8428[جْ]عَلُ لَهُمُ [h:8429[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ وُدًّا","Албатта, иймон келтирган ва яхши амалларни қилганларга Роҳман муҳаббат пайдо қилур.",312,16],["فَإِ[g[نّ]َمَا يَسَّرْنَ[n[ـٰ]هُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ [h:8430[ٱ]لْمُتَّقِينَ وَتُ[f:8431[نذ]ِرَ بِه[n[ِۦ] قَوْ[u:8432[مًا ل]ُّدًّا","Бас, албатта, тақводорларга хушхабар беришинг ва у билан саркаш қавмларни огоҳлантиришинг учун уни тилингга осон қилдик.",312,16],["وَكَمْ أَهْلَكْنَا قَ[q:8394[بْ]لَه[w:8395[ُم م]ِّ[f:3927[ن ق]َرْنٍ هَلْ تُحِسُّ مِنْه[w:8433[ُم م]ِّنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزَۢا","Улардан олдин қанчадан-қанча асрни ҳалок қилдик. Улардан бирортасини ҳис этасанми ёки шарпасини эшитасанми?!",312,16]]},{"n":20,"ar":"طه","en":"Taa-Haa","uz":"Тоҳа","type":"Макка","ayahs":[["طه","Тоҳо.",312,16],["م[o[َآ] أَ[f:515[نز]َلْنَا عَلَيْكَ [h:8434[ٱ]لْقُرْءَانَ لِتَشْقَىٰٓ","Сенга Қуръонни бадбахт бўлишинг учун нозил қилганимиз йўқ.",312,16],["إِلَّا تَذْكِرَ[u:8435[ةً ل]ِّم[a:8436[َن ي]َخْشَىٰ","Магар қўрққан кимсаларга эслатма бўлиши учун.",312,16],["تَ[f:7929[نز]ِيل[a:8437[اً م]ِّ[g[مّ]َنْ خَلَقَ [h:8438[ٱ]لْأَرْضَ وَ[h:8439[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ [h:8440[ٱ]لْعُلَى","У ерни ва юксак осмонларни яратган зотдан нозил бўлгандир.",312,16],["ٱ[l[ل]رَّحْمَ[n[ـٰ]نُ عَلَى [h:4740[ٱ]لْعَرْشِ [h:8441[ٱ]سْتَوَىٰ","У–Роҳман Аршни эгаллади.",312,16],["لَهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ [h:8442[ٱ][l[ل]ثَّرَىٰ","Осмонлардаги нарсалару ердаги нарсалар, уларнинг орасидаги нарсалару ер остидаги нарсалар Уникидир.",312,16],["وَإِ[f:8443[ن ت]َ[q:7936[جْ]هَرْ بِ[h:7118[ٱ]لْقَوْلِ فَإِ[g[نّ]َهُ[n[ۥ] يَعْلَمُ [h:8444[ٱ][l[ل]سِّرَّ وَأَخْفَى","Сен агар сўзда овозингни юксалтирсанг ҳам. Бас, албатта, у сирни ҳам, махфийни ҳам билгувчидир.",312,16],["ٱللَّهُ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۖ لَهُ [h:8445[ٱ]لْأَسْم[o[َا]ٓءُ [h:5156[ٱ]لْحُسْنَىٰ","Аллоҳ–ундан бошқа ибодатга сазовор илоҳ йўқ зотдир. Гўзал исмлар Уникидир.",312,16],["وَهَلْ أَتَ[n[ـٰ]كَ حَدِيثُ مُوسَىٰٓ","Сенга Мусонинг хабари келдими?",312,16],["إِذْ رَءَا نَا[f:8446[رًا ف]َقَالَ لِأَهْلِهِ [h:8447[ٱ]مْكُث[o[ُوٓ][s[اْ] إِ[g[نّ][o[ِىٓ] ءَانَسْتُ نَا[u:8448[رًا ل]َّعَلّ[o[ِىٓ] ءَاتِيك[w:8449[ُم م]ِّنْهَا بِقَبَسٍ أَوْ أَجِدُ عَلَى [h:896[ٱ][l[ل][g[نّ]َارِ هُدًى","У оловни кўрган чоғида ўз аҳлига:»Туриб туринглар, мен оловни кўрдим, шояд сизга ундан чўғ келтирсам ёки олов бошида йўл кўрсатувчини топсам«, деди.",312,16],["فَلَ[g[مّ][o[َآ] أَتَ[n[ـٰ]هَا نُودِىَ يَ[n[ـٰ]مُوسَىٰٓ","Бас, уга келганида, нидо қилинди: «Эй Мусо.",312,16],["إِ[g[نّ][o[ِىٓ] أَنَا۟ رَبُّكَ فَ[h:8450[ٱ]خْلَعْ نَعْلَيْكَ‌ۖ إِ[g[نّ]َكَ بِ[h:8451[ٱ]لْوَادِ [h:8452[ٱ]لْمُقَدَّسِ طُوًى","Албатта, Мен Ўзим сенинг Роббингдирман. Кавушларингни еч. Чунки сен муқаддас Туво водийсидасан».",312,16],["وَأَنَا [h:8453[ٱ]خْتَرْتُكَ فَ[h:8454[ٱ]سْتَمِعْ لِمَا يُوحَىٰٓ","Мен сени ихтиёр қилиб олдим. Ваҳий қилинадиган нарсага қулоқ ос.",313,16],["إِ[g[نّ]َن[o[ِىٓ] أَنَا [h:8455[ٱ]للَّهُ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلّ[o[َآ] أَنَا۟ فَ[h:8456[ٱ]عْبُ[q:8456[دْ]نِى وَأَقِمِ [h:6518[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ لِذِكْرِىٓ","Албатта, Мен, Ўзим, Аллоҳдирман. Мендан ўзга илоҳ йўқ. Бас, Менга ибодат қил ва мени зикр этиш учун намозни тўкис адо эт.",313,16],["إِ[g[نّ]َ [h:8457[ٱ][l[ل]سَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخْفِيهَا لِتُ[q:8458[جْ]زَىٰ كُلُّ نَفْ[i:6995[سِۭ ب]ِمَا تَسْعَىٰ","Албатта, соати келгувчидир. Ҳар бир жон саъйи-ҳаракатига яраша жазо олиши учун уни махфий тутурман.",313,16],["فَلَا يَصُدَّ[g[نّ]َكَ عَنْهَا م[u:6065[َن ل]َّا يُؤْمِنُ بِهَا وَ[h:3160[ٱ]تَّبَعَ هَوَ[n[ٮٰ]هُ فَتَرْدَىٰ","Ҳаргиз сени унга иймон келтирмайдиганлар ва ҳавойи нафсига эргашганлар ундан тўсмасинлар. У ҳолда ҳалок бўласан».",313,16],["وَمَا تِلْكَ بِيَمِينِكَ يَ[n[ـٰ]مُوسَىٰ","«Эй Мусо, қўлингдаги нима?»",313,16],["قَالَ هِىَ عَصَاىَ أَتَوَكَّؤُ[s[اْ] عَلَيْهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِى وَلِىَ فِيهَا مَـَٔـارِبُ أُخْرَىٰ","У: «Бу асоимдир, унга суянаман, у билан қўйларимга қоқиб бераман ва унда менинг бошқа ишларим бор», деди.",313,16],["قَالَ أَلْقِهَا يَ[n[ـٰ]مُوسَىٰ","У зот: «Эй Мусо, уни ташла», деди.",313,16],["فَأَلْقَ[n[ـٰ]هَا فَإِذَا هِىَ حَيَّ[f:8459[ةٌ ت]َسْعَىٰ","Бас, уни ташлади. Бирдан у илон бўлиб юра бошлади.",313,16],["قَالَ خُذْهَا وَلَا تَخَفْ‌ۖ سَنُعِيدُهَا سِيرَتَهَا [h:8460[ٱ]لْأُولَىٰ","У зот: «Уни ол, қўрқма. Биз уни аввалги ҳолига келтирамиз.",313,16],["وَ[h:9999[ٱ]ضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُ[q:8461[جْ] بَيْض[o[َا]ٓءَ مِنْ غَيْرِ س[o[ُو]ٓءٍ ءَايَةً أُخْرَىٰ","Қўлингни қўлтиғингга тиқ, ёмонликсиз оппоқ бўлиб чиқади. Бу бошқа бир мўъжизадир.",313,16],["لِنُرِيَكَ مِنْ ءَايَ[n[ـٰ]تِنَا [h:8462[ٱ]لْكُ[q:8463[بْ]رَى","Биз сенга буюк мўъжизаларимизни кўрсатиш учун.",313,16],["ٱذْهَ[q:7814[بْ] إِلَىٰ فِرْعَوْنَ إِ[g[نّ]َهُ[n[ۥ] طَغَىٰ","Сен Фиръавнга бор, албатта у туғёнга кетди», деди.",313,16],["قَالَ رَبِّ [h:8464[ٱ]شْرَحْ لِى صَ[q:8465[دْ]رِى","У: «Эй Роббим, менинг қалбимни кенг қил.",313,16],["وَيَسِّرْ ل[o[ِىٓ] أَمْرِى","Менинг ишимни осон қил.",313,16],["وَ[h:9999[ٱ]حْلُلْ عُ[q:8466[قْ]دَ[a:8467[ةً م]ّ[u:8468[ِن ل]ِّسَانِى","Тилимдаги тугунни ечгин.",313,16],["يَفْقَهُو[s[اْ] قَوْلِى","Сўзимни англасинлар.",313,16],["وَ[h:9999[ٱ][q:2930[جْ]عَل لِّى وَزِي[a:8469[رًا م]ِّنْ أَهْلِى","Менга ўз аҳлимдан бир вазир қилиб бер.",313,16],["هَ[n[ـٰ]رُونَ أَخِى","Оғам Ҳорунни.",313,16],["ٱشْدُ[q:8470[دْ] بِه[o[ِۦٓ] أَزْرِى","У билан белимни қувватла.",313,16],["وَأَشْرِكْهُ ف[o[ِىٓ] أَمْرِى","Уни ишимга шерик айла.",313,16],["كَىْ نُسَبِّحَكَ كَثِيرًا","Сенга кўп тасбиҳ айтишимиз учун.",313,16],["وَنَذْكُرَكَ كَثِيرًا","Ва Сени кўп зикр қилишимиз учун.",313,16],["إِ[g[نّ]َكَ كُ[f:735[نت]َ بِنَا بَصِيرًا","Албатта, Сен Ўзинг бизни кўриб турувчи эдинг», деди.",313,16],["قَالَ قَ[q:298[دْ] أُوتِيتَ سُؤْلَكَ يَ[n[ـٰ]مُوسَىٰ","У зот: «Эй Мусо, сенга сўраганинг берилди», деди.",313,16],["وَلَقَ[q:341[دْ] مَنَ[g[نّ]َا عَلَيْكَ مَرَّةً أُخْرَىٰٓ","«Батаҳқиқ, Биз сенга бошқа марта ҳам неъмат берган эдик.",313,16],["إِذْ أَوْحَيْن[o[َآ] إِلَ[o[ىٰٓ] أُ[g[مّ]ِكَ مَا يُوحَىٰٓ","Ўшанда онангга илҳом қилинадиган нарсани илҳом қилган эдик.",314,16],["أَنِ [h:8471[ٱ][q:8472[قْ]ذِفِيهِ فِى [h:8473[ٱ][l[ل]تَّابُوتِ فَ[h:8474[ٱ][q:8474[قْ]ذِفِيهِ فِى [h:4971[ٱ]لْيَ[g[مّ]ِ فَلْيُلْقِهِ [h:8475[ٱ]لْيَ[g[مّ]ُ بِ[h:8476[ٱ][l[ل]سَّاحِلِ يَأْخُذْهُ عَدُ[u:8477[وٌّ ل]ِّى وَعَدُ[u:8478[وٌّ ل]َّهُ[n[ۥ]‌ۚ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّ[a:8479[ةً م]ِّ[g[نّ]ِى وَلِتُصْنَعَ عَلَىٰ عَيْنِىٓ","«Уни тобутга сол, уни эса, дарёга ташла. Дарё уни соҳилга отсин. Уни Менинг душманим ва унинг душмани оладир», дедик. Ва сенга Ўзимдан муҳаббат солдим. Буни Менинг кўз олдимда етиштирилишинг учун.",314,16],["إِذْ تَمْش[o[ِىٓ] أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَىٰ م[a:8480[َن ي]َكْفُلُهُ[n[ۥ]‌ۖ فَرَجَعْنَ[n[ـٰ]كَ إِلَ[o[ىٰٓ] أُ[g[مّ]ِكَ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ‌ۚ وَقَتَلْتَ نَفْ[f:8481[سًا ف]َنَجَّيْنَ[n[ـٰ]كَ مِنَ [h:8482[ٱ]لْغَ[g[مّ]ِ وَفَتَ[g[نّ]َ[n[ـٰ]كَ فُتُو[f:8483[نًا‌ۚ ف]َلَبِثْتَ سِنِينَ ف[o[ِىٓ] أَهْلِ مَ[q:4842[دْ]يَنَ ثُ[g[مّ]َ جِئْتَ عَلَىٰ قَدَ[a:8484[رٍ ي]َ[n[ـٰ]مُوسَىٰ","Ўшанда опанг юриб бориб: «У ни кафилликка оладиганларга далолат қилайми? « деган эди. Бас, Биз сени кўзи қувониши ва хафа бўлмаслиги учун онангга қайтардик. Ва бир жонни ўлдирдинг. Бас, Биз сени ғамдан қутқардик ва турли синовлар ила синадик. Сўнгра Мадян аҳли ила йилларга қолдинг ва тақдирга биноан келдинг, эй Мусо!",314,16],["وَ[h:9999[ٱ]صْطَنَعْتُكَ لِنَفْسِى","Мен сени Ўзим учун танладим.",314,16],["ٱذْهَ[q:7814[بْ] أَ[f:169[نت]َ وَأَخُوكَ بِـَٔـايَ[n[ـٰ]تِى وَلَا تَنِيَا فِى ذِكْرِى","Сен ва оғанг мўъжизаларимни олиб боринглар ва Мени зикр этишда сусткашлик қилманглар.",314,16],["ٱذْهَب[o[َآ] إِلَىٰ فِرْعَوْنَ إِ[g[نّ]َهُ[n[ۥ] طَغَىٰ","Фиръавнга боринглар! Чунки, у туғёнга кетди.",314,16],["فَقُولَا لَهُ[n[ۥ] قَوْل[u:8485[اً ل]َّيِّ[u:8486[نًا ل]َّعَلَّهُ[n[ۥ] يَتَذَكَّرُ أَوْ يَخْشَىٰ","Бас, унга юмшоқ сўз айтинглар. Шояд эсласа ёки қўрқса».",314,16],["قَالَا رَبَّن[o[َآ] إِ[g[نّ]َنَا نَخَافُ أ[a:8487[َن ي]َفْرُطَ عَلَيْن[o[َآ] أَوْ أ[a:8488[َن ي]َ[q:8489[طْ]غَىٰ","Икковлари: «Эй Роббимиз, биз унинг тезда бизга ёмонлик қилишидан ёки ҳаддан ошишидан қўрқамиз», дедилар.",314,16],["قَالَ لَا تَخَاف[o[َآ‌ۖ] إِ[g[نّ]َنِى مَعَكُم[o[َآ] أَسْمَعُ وَأَرَىٰ","У зот: «Қўрқманглар! Албатта, Мен сизлар биланман, эшитаман ва кўраман», деди.",314,16],["فَأْتِيَاهُ فَقُول[o[َآ] إِ[g[نّ]َا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ وَلَا تُعَذِّ[q:3905[بْ]هُمْ‌ۖ قَ[q:298[دْ] جِئْنَ[n[ـٰ]كَ بِـَٔـايَ[a:1930[ةٍ م]ّ[u:770[ِن ر]َّبِّكَ‌ۖ وَ[h:8490[ٱ][l[ل]سَّلَ[n[ـٰ]مُ عَلَىٰ مَنِ [h:3443[ٱ]تَّبَعَ [h:8491[ٱ]لْهُدَىٰٓ","Бас, унинг олдига боринглар ва унга: «Албатта, биз Роббингнинг Пайғамбарларимиз, Бани Исроилни биз билан қўйиб юбор. Уларни азоблама. Батаҳқиқ, биз сенга Роббингдан мўъжиза келтирдик. Ҳидоятга эргашган кимсага салом бўлур.",314,16],["إِ[g[نّ]َا قَ[q:298[دْ] أُوحِىَ إِلَيْن[o[َآ] أَ[g[نّ]َ [h:8492[ٱ]لْعَذَابَ عَلَىٰ مَ[f:8493[ن ك]َذَّبَ وَتَوَلَّىٰ","Албатта, бизга ваҳий қилиндики, ёлғонга чиқарганларга ва юз ўгириб кетганларга шубҳасиз азоб бўлур», денглар.",314,16],["قَالَ فَم[u:8494[َن ر]َّبُّكُمَا يَ[n[ـٰ]مُوسَىٰ","У: «Эй Мусо, икковингизнинг Роббингиз ким?» деди.",314,16],["قَالَ رَبُّنَا [h:8495[ٱ]لَّذ[o[ِىٓ] أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُ[n[ۥ] ثُ[g[مّ]َ هَدَىٰ","У: «Бизнинг Роббимиз ҳар нарсага ўз яратилишини берган ҳамда уни ҳидоятга солган зотдир», деди.",314,16],["قَالَ فَمَا بَالُ [h:8496[ٱ]لْقُرُونِ [h:8497[ٱ]لْأُولَىٰ","У: «Ўтган асрларнинг ҳоли недир?» деди.",314,16],["قَالَ عِلْمُهَا عِ[f:264[ند]َ رَبِّى فِى كِتَ[n[ـٰ][u:8498[بٍ‌ۖ ل]َّا يَضِلُّ رَبِّى وَلَا يَ[f:8499[نس]َى","У: «Уларнинг илми Роббим ҳузурида, китобдадир. Роббим адашмас ва унутмас.",315,16],["ٱلَّذِى جَعَلَ لَكُمُ [h:87[ٱ]لْأَرْضَ مَهْ[a:8500[دًا و]َسَلَكَ لَكُمْ فِيهَا سُبُل[a:8501[اً و]َأَ[f:91[نز]َلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:4278[ءً ف]َأَخْرَ[q:4279[جْ]نَا بِه[o[ِۦٓ] أَزْو[n[َٲ][a:8502[جًا م]ّ[a:8503[ِن ن]َّبَا[f:8504[تٍ ش]َتَّىٰ","У сизга ерни бешик қилган, сизга унда йўллар очган ва осмондан сув туширган зотдир», деди. Бас, ўша ила турли набототлар жуфтларини чиқардик.",315,16],["كُلُو[s[اْ] وَ[h:8505[ٱ]رْعَوْ[s[اْ] أَنْعَ[n[ـٰ]مَكُمْ‌ۗ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:2495[تٍ ل]ِّأُ[s[وْ]لِى [h:8506[ٱ][l[ل][g[نّ]ُهَىٰ","Енглар ва чорваларингизни боқинглар. Албатта, бунда ақл эгалари учун ибратлар бордир.",315,16],["۞ مِنْهَا خَلَ[q:4250[قْ]نَ[n[ـٰ]كُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ","Сизларни ундан яратдик, унга қайтарамиз ва яна бир бор ундан чиқариб оламиз.",315,16],["وَلَقَ[q:341[دْ] أَرَيْنَ[n[ـٰ]هُ ءَايَ[n[ـٰ]تِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ","Батаҳқиқ, Биз унга оят-мўъжизаларимизнинг ҳаммасини кўрсатдик. Бас, у ёлғонга чиқарди ва бош тортди.",315,16],["قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنْ أَرْضِنَا بِسِحْرِكَ يَ[n[ـٰ]مُوسَىٰ","У: «Эй Мусо, бизни еримиздан чиқариш учун сеҳринг ила келдингми?!",315,16],["فَلَنَأْتِيَ[g[نّ]َكَ بِسِحْ[a:8507[رٍ م]ِّثْلِه[n[ِۦ] فَ[h:7148[ٱ][q:7148[جْ]عَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِ[u:8508[دًا ل]َّا نُخْلِفُهُ[n[ۥ] نَحْنُ وَل[o[َآ] أَ[f:169[نت]َ مَكَا[f:8509[نًا سُ]وًى","Бас, албатта, биз ҳам унга ўхшаш сеҳр келтирамиз, биз билан ўзинг орангда ваъда вақти тайин қил, унга биз ҳам, сен ҳам хилоф қилмайдиган бўлайлик, ўрта жой бўлсин«, деди.",315,16],["قَالَ مَوْعِدُكُمْ يَوْمُ [h:8510[ٱ][l[ل]زِّينَةِ وَأ[a:8511[َن ي]ُحْشَرَ [h:8512[ٱ][l[ل][g[نّ]َاسُ ضُحًى","У: «Ваъда вақтингиз зийнат куни. Одамларнинг чошгоҳда тўпланиши», деди.",315,16],["فَتَوَلَّىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُ[n[ۥ] ثُ[g[مّ]َ أَتَىٰ","Бас, Фиръавн қайтиб кетди, сўнгра ҳийласини йиғиб келди.",315,16],["قَالَ لَه[w:6149[ُم م]ُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُو[s[اْ] عَلَى [h:412[ٱ]للَّهِ كَذِ[f:8513[بًا ف]َيُسْحِتَك[c:8514[ُم ب]ِعَذَا[a:8515[بٍ‌ۖ و]َقَ[q:387[دْ] خَابَ مَنِ [h:8516[ٱ]فْتَرَىٰ","Уларга Мусо: «Ҳолингизга вой! Аллоҳга нисбатан ёлғон уйдирманг, бас, сизни азоб ила бутунлай ҳалок қилур. Батаҳқиқ, ким ёлғон уйдирса, ноумид бўлур», деди.",315,16],["فَتَنَ[n[ـٰ]زَع[o[ُوٓ][s[اْ] أَمْرَه[c:8517[ُم ب]َيْنَهُمْ وَأَسَرُّو[s[اْ] [h:8518[ٱ][l[ل][g[نّ]َ[q:8519[جْ]وَىٰ","Бас, улар ишлари ҳақида ўзаро аста шивирлашиб, мунозара қила бошладилар.",315,16],["قَال[o[ُوٓ][s[اْ] إِنْ هَ[n[ـٰ]ذ[n[َٲ]نِ لَسَ[n[ـٰ]حِر[n[َٲ]نِ يُرِيدَانِ أ[a:8520[َن ي]ُخْرِجَاك[w:8521[ُم م]ِّنْ أَرْضِك[c:8522[ُم ب]ِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ [h:8523[ٱ]لْمُثْلَىٰ","Улар: «Албатта, бу иккови сеҳргардирлар. Сизни сеҳрлари билан ерларингиздан чиқаришни ва сизнинг афзал йўлингизни йўқотишни хоҳлайдилар.",315,16],["فَأَ[q:6128[جْ]مِعُو[s[اْ] كَيْدَكُمْ ثُ[g[مّ]َ [h:8524[ٱ]ئْتُو[s[اْ] صَف[a:8525[ًّا‌ۚ و]َقَ[q:387[دْ] أَفْلَحَ [h:8526[ٱ]لْيَوْمَ مَنِ [h:8527[ٱ]سْتَعْلَىٰ","Бас, макр-ҳийлангизни жамлаб, бир саф бўлиб келинг. Батаҳқиқ, бугунги кунда ким устун келса, ўша ғолиб бўладир», дедилар.",315,16],["قَالُو[s[اْ] يَ[n[ـٰ]مُوسَ[o[ىٰٓ] إِ[g[مّ][o[َآ] أَ[f:4922[ن ت]ُلْقِىَ وَإِ[g[مّ][o[َآ] أ[a:4923[َن ن]َّكُونَ أَوَّلَ مَنْ أَلْقَىٰ","Улар: «Эй Мусо, сен ташлайсанми ёки биз аввал ташловчи бўлайликми?» дедилар.",316,16],["قَالَ بَلْ أَلْقُو[s[اْ‌ۖ] فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِ[f:8528[ن س]ِحْرِهِمْ أَ[g[نّ]َهَا تَسْعَىٰ","У: «Йўқ. Сизлар ташланг», деди. Бирдан уларнинг арқонлари ва асолари унга сеҳрларидан худди ҳаракатланаётгандек бўлиб кўринди.",316,16],["فَأَوْجَسَ فِى نَفْسِه[n[ِۦ] خِيفَ[a:8529[ةً م]ُّوسَىٰ","Бас, Мусо ичида хавф ҳис этди.",316,16],["قُلْنَا لَا تَخَفْ إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:8530[ٱ]لْأَعْلَىٰ","Биз: «Қўрқма, албатта, сен устунсан.",316,16],["وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَع[o[ُوٓ[s[اْ]‌ۖ] إِ[g[نّ]َمَا صَنَعُو[s[اْ] كَيْدُ سَ[n[ـٰ]حِ[a:8531[رٍ‌ۖ و]َلَا يُفْلِحُ [h:8532[ٱ][l[ل]سَّاحِرُ حَيْثُ أَتَىٰ","Қўлингдаги нарсани ташлагин, уларнинг қилган ҳунарини ютиб юбораур. Уларнинг қилган ҳунари сеҳргарнинг ҳийласи, холос. Сеҳргар қаерда бўлса ҳам, зафар топмас», дедик.",316,16],["فَأُلْقِىَ [h:8533[ٱ][l[ل]سَّحَرَةُ سُجَّ[f:8534[دًا ق]َال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا بِرَبِّ هَ[n[ـٰ]رُونَ وَمُوسَىٰ","Бас, сеҳргарлар: «Ҳорун ва Мусонинг Роббига иймон келтирдик», деб саждага ташландилар.",316,16],["قَالَ ءَامَ[f:703[نت]ُمْ لَهُ[n[ۥ] قَ[q:3282[بْ]لَ أَنْ ءَاذَنَ لَكُمْ‌ۖ إِ[g[نّ]َهُ[n[ۥ] لَكَبِيرُكُمُ [h:8535[ٱ]لَّذِى عَلَّمَكُمُ [h:8536[ٱ][l[ل]سِّحْرَ‌ۖ فَلَأُقَطِّعَ[g[نّ]َ أَيْدِيَكُمْ وَأَرْجُلَك[w:4933[ُم م]ِّنْ خِلَ[n[ـٰ][a:8537[فٍ و]َلَأُصَلِّبَ[g[نّ]َكُمْ فِى جُذُوعِ [h:8538[ٱ][l[ل][g[نّ]َخْلِ وَلَتَعْلَمُ[g[نّ]َ أَيُّن[o[َآ] أَشَدُّ عَذَا[a:8539[بًا و]َأَ[q:8540[بْ]قَىٰ","У: «Сизга изн бермасимдан олдин унга иймон келтирдингизми?! Албатта, у сизга сеҳр ўргатган каттангиздир! Бас, албатта, қўл-оёқларингизни қарама-қаршисидан кесурман ва, албатта, сизларни хурмо танасига осурман, албатта, қайси биримизнинг азобимиз шиддатлироқ ва боқийроқ эканини билурсиз», деди.",316,16],["قَالُو[s[اْ] ل[a:8541[َن ن]ُّؤْثِرَكَ عَلَىٰ مَا ج[o[َا]ٓءَنَا مِنَ [h:816[ٱ]لْبَيِّنَ[n[ـٰ]تِ وَ[h:4765[ٱ]لَّذِى فَطَرَنَا‌ۖ فَ[h:8542[ٱ][q:8542[قْ]ضِ م[o[َآ] أَ[f:169[نت]َ قَاضٍ‌ۖ إِ[g[نّ]َمَا تَ[q:8543[قْ]ضِى هَ[n[ـٰ]ذِهِ [h:8544[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَآ","Улар: «Биз сени зинҳор ўзимизга келган очиқ-ойдин лардан ва бизни яратган зотдан устун қўймаймиз. Бас, нима ҳукм қилсанг, қилавер. Сен фақат ҳаёти дунёда ҳукм чиқарасан, холос.",316,16],["إِ[g[نّ][o[َآ] ءَامَ[g[نّ]َا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَ[n[ـٰ]يَ[n[ـٰ]نَا وَم[o[َآ] أَكْرَهْتَنَا عَلَيْهِ مِنَ [h:8545[ٱ][l[ل]سِّحْرِ‌ۗ وَ[h:72[ٱ]للَّهُ خَيْ[a:8546[رٌ و]َأَ[q:8540[بْ]قَىٰٓ","Албатта, биз Роббимиз хатоларимизни ва сен бизни мажбур қилган сеҳрни мағфират қилиши учун иймон келтирдик. Аллоҳ яхши ва боқийдир», дедилар.",316,16],["إِ[g[نّ]َهُ[n[ۥ] م[a:8547[َن ي]َأْتِ رَبَّهُ[n[ۥ] مُ[q:8548[جْ]رِ[f:8549[مًا ف]َإِ[g[نّ]َ لَهُ[n[ۥ] جَهَ[g[نّ]َمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","Шубҳасиз, ким Роббига жиноятчи бўлган ҳолида келса, албатта, унга жаҳаннам бордир. У ерда у ўлиб ўлмас, яшаб яшамас.",316,16],["وَم[a:8550[َن ي]َأْتِه[n[ِۦ] مُؤْمِ[f:8551[نًا ق]َ[q:298[دْ] عَمِلَ [h:8552[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمُ [h:8553[ٱ][l[ل]دَّرَجَ[n[ـٰ]تُ [h:8554[ٱ]لْعُلَىٰ","Ким Унга мўмин ўлароқ, яхши амаллар қилган ҳолида келса, бас, ана ўшаларга олий даражалар.",316,16],["جَ[g[نّ]َ[n[ـٰ]تُ عَ[q:5720[دْ][f:8049[نٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۚ وَذ[n[َٲ]لِكَ جَز[o[َا]ٓءُ مَ[f:8555[ن ت]َزَكَّىٰ","Остидан анҳорлар оқиб турган адн жаннатлар бордир. Унда абадий қолурлар. Ана шу пок бўлганнинг мукофотидир.",316,16],["وَلَقَ[q:341[دْ] أَوْحَيْن[o[َآ] إِلَىٰ مُوسَ[o[ىٰٓ] أَنْ أَسْرِ بِعِبَادِى فَ[h:8556[ٱ]ضْرِ[q:8556[بْ] لَهُمْ طَرِي[f:8557[قًا ف]ِى [h:837[ٱ]لْبَحْرِ يَبَ[u:8558[سًا ل]َّا تَخَ[n[ـٰ]فُ دَرَ[a:8559[كًا و]َلَا تَخْشَىٰ","Батаҳқиқ, Биз Мусога: «Сен бандаларим ила кечаси йўлга туш, уларга денгиздан қуруқ йўл оч, етиб олишларидан хавф қилма ва қўрқма», деб ваҳий қилдик.",317,16],["فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِه[n[ِۦ] فَغَشِيَه[w:8560[ُم م]ِّنَ [h:8561[ٱ]لْيَ[g[مّ]ِ مَا غَشِيَهُمْ","Бас, Фиръавн аскарлари ила уларнинг ортидан таъқиб этди. Денгиз уларни ўраганича ўраб олди.",317,16],["وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ[n[ۥ] وَمَا هَدَىٰ","Фиръавн ўз қавмини адаштирди, тўғри йўлга бошламади.",317,16],["يَ[n[ـٰ]بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ قَ[q:298[دْ] أَ[f:4989[نج]َيْنَ[n[ـٰ]ك[w:4990[ُم م]ِّنْ عَدُوِّكُمْ وَو[n[َٲ]عَ[q:8562[دْ]نَ[n[ـٰ]كُمْ جَانِبَ [h:8563[ٱ][l[ل]طُّورِ [h:8564[ٱ]لْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ [h:272[ٱ]لْمَ[g[نّ]َ وَ[h:273[ٱ][l[ل]سَّلْوَىٰ","Эй Бани Исроил, батаҳқиқ, Биз сизни душманингиздан қутқардик ва сиз билан Турнинг ўнг томонини ваъдалашдик ҳамда сизларга манн ва бедана туширдик.",317,16],["كُلُو[s[اْ] مِ[f:274[ن ط]َيِّبَ[n[ـٰ]تِ مَا رَزَ[q:275[قْ]نَ[n[ـٰ]كُمْ وَلَا تَ[q:6515[طْ]غَوْ[s[اْ] فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِى‌ۖ وَم[a:8565[َن ي]َحْلِلْ عَلَيْهِ غَضَبِى فَقَ[q:563[دْ] هَوَىٰ","Биз сизга ризқ қилиб берган пок нарсалардан енглар, унда ҳаддингиздан ошманг, яна бошингизга ғазабим тушиб қолмасин. Кимнинг бошига ғазабим тушса, бас, батаҳқиқ, ҳалок бўлибдир.",317,16],["وَإِ[g[نّ]ِى لَغَفَّا[u:8566[رٌ ل]ِّمَ[f:8567[ن ت]َابَ وَءَامَنَ وَعَمِلَ صَ[n[ـٰ]لِ[f:8568[حًا ث]ُ[g[مّ]َ [h:8569[ٱ]هْتَدَىٰ","Албатта, Мен тавба қилган, иймон келтириб, яхши амал қилган, сўнгра тўғри юрганларни кўплаб мағфират қилгувчиман.",317,16],["۞ وَم[o[َآ] أَعْجَلَكَ عَ[f:8570[ن ق]َوْمِكَ يَ[n[ـٰ]مُوسَىٰ","Эй Мусо, сени қавмингдан нима илгарилатди?",317,16],["قَالَ هُمْ أُ[s[وْ]ل[o[َا]ٓءِ عَلَ[o[ىٰٓ] أَثَرِى وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ","У: «Улар, ана, изимдалар. Рози бўлишинг учун Мен сенга шошдим, эй Роббим», деди.",317,16],["قَالَ فَإِ[g[نّ]َا قَ[q:298[دْ] فَتَ[g[نّ]َا قَوْمَكَ م[i:8571[ِنۢ ب]َعْدِكَ وَأَضَلَّهُمُ [h:8572[ٱ][l[ل]سَّامِرِىُّ","У зот: «Батаҳқиқ, Биз қавмингни сендан кейин фитнага дучор қилдик. Сомирий уларни адаштирди», деди.",317,16],["فَرَجَعَ مُوسَ[o[ىٰٓ] إِلَىٰ قَوْمِه[n[ِۦ] غَضْبَ[n[ـٰ]نَ أَسِ[f:5024[فًا‌ۚ ق]َالَ يَ[n[ـٰ]قَوْمِ أَلَمْ يَعِ[q:8573[دْ]كُمْ رَبُّكُمْ وَعْدًا حَسَنًا‌ۚ أَفَطَالَ عَلَيْكُمُ [h:8574[ٱ]لْعَهْدُ أَمْ أَرَ[d:1317[د]تُّمْ أ[a:8575[َن ي]َحِلَّ عَلَيْكُمْ غَضَ[a:5035[بٌ م]ّ[u:243[ِن ر]َّبِّكُمْ فَأَخْلَفْت[w:8576[ُم م]َّوْعِدِى","Бас, Мусо қавмига ғазабланган, афсусланган ҳолда қайтди. У: «Эй қавмим, Роббингиз сизга яхши ваъда қилмаганмиди?! Сизларга замон узоқ кўриндими ёки бошингизга Роббингиздан ғазаб тушишини хоҳладингизми?! Менга берган ваъдага хилоф қилибсиз?!» деди.",317,16],["قَالُو[s[اْ] م[o[َآ] أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَ[n[ـٰ]كِ[g[نّ]َا حُ[g[مّ]ِلْن[o[َآ] أَوْزَا[a:8577[رًا م]ِّ[f:8578[ن ز]ِينَةِ [h:8579[ٱ]لْقَوْمِ فَقَذَفْنَ[n[ـٰ]هَا فَكَذ[n[َٲ]لِكَ أَلْقَى [h:8580[ٱ][l[ل]سَّامِرِىُّ","Улар: «Биз сенга берган ваъдага ўз ихтиёримиз ила хилоф қилмадик. Лекин бизга қавмнинг зийнатидан оғирликлар юкланган эди. Бас, уларни ташладик, Сомирий ана шундай илқо қилди», дедилар.",317,16],["فَأَخْرَجَ لَهُمْ عِ[q:5020[جْ]ل[f:5021[اً ج]َسَ[u:5022[دًا ل]َّهُ[n[ۥ] خُوَا[f:8581[رٌ ف]َقَالُو[s[اْ] هَ[n[ـٰ]ذ[o[َآ] إِلَ[n[ـٰ]هُكُمْ وَإِلَ[n[ـٰ]هُ مُوسَىٰ فَنَسِىَ","Бас, у уларга бўкирадиган бузоқ шаклини чиқариб берди. Улар: «Мана шу сизнинг илоҳингиз ва Мусонинг ҳам илоҳи, фақат у унутди», дедилар.",318,16],["أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْل[a:8582[اً و]َلَا يَمْلِكُ لَهُمْ ضَر[a:3719[ًّا و]َلَا نَفْعًا","Унинг ўзларига бирон сўз қайтара олмаётганини, на зарар ва на фойдага молик бўла олмаётганини кўрмаяптиларми?!",318,16],["وَلَقَ[q:341[دْ] قَالَ لَهُمْ هَ[n[ـٰ]رُونُ مِ[f:128[ن ق]َ[q:129[بْ]لُ يَ[n[ـٰ]قَوْمِ إِ[g[نّ]َمَا فُتِ[f:8583[نت][c:8584[ُم ب]ِه[n[ِۦ]‌ۖ وَإِ[g[نّ]َ رَبَّكُمُ [h:8585[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ فَ[h:1852[ٱ]تَّبِعُونِى وَأَطِيع[o[ُوٓ][s[اْ] أَمْرِى","Батаҳқиқ, илгари Ҳорун уларга: «Эй қавмим, бу билан фитнага дучор қилиндингиз, холос. Шубҳасиз, Роббингиз Роҳмандир. Бас, менга эргашинг. Менинг амримга итоат қилинг», деган эди.",318,16],["قَالُو[s[اْ] ل[a:8586[َن ن]َّ[q:8587[بْ]رَحَ عَلَيْهِ عَ[n[ـٰ]كِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسَىٰ","Улар: «То Мусо бизга қайтгунича, унга ибодат қилишда бардавом бўламиз», дедилар.",318,16],["قَالَ يَ[n[ـٰ]هَ[n[ـٰ]رُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوٓ[s[اْ]","У: «Эй Ҳорун, уларнинг залолатга кетганларини кўрганингда сени нима ман қилди?!",318,16],["أَلَّا تَتَّبِعَنِ‌ۖ أَفَعَصَيْتَ أَمْرِى","Менга эргашишингдан?! Менинг амримга осий бўлдингми?!» деди.",318,16],["قَالَ يَ[q:8588[بْ]نَؤُ[g[مّ]َ لَا تَأْخُذْ بِلِحْيَتِى وَلَا بِرَأْس[o[ِىٓ‌ۖ] إِ[g[نّ]ِى خَشِيتُ أَ[f:8589[ن ت]َقُولَ فَرَّ[q:8590[قْ]تَ بَيْنَ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ وَلَمْ تَرْقُ[q:8591[بْ] قَوْلِى","У: «Эй онамнинг ўғли, соч-соқолимдан тутма. Мен сенинг: «Бани Исроилни тафриқага солибсан, гапимга кирмабсан, дейишингдан қўрқдим», деди.",318,16],["قَالَ فَمَا خَ[q:8592[طْ]بُكَ يَ[n[ـٰ]سَ[n[ـٰ]مِرِىُّ","У: «Бу нима қилганинг, эй Сомирий?!» деди.",318,16],["قَالَ بَصُرْتُ بِمَا لَمْ يَ[q:8593[بْ]صُرُو[s[اْ] بِه[n[ِۦ] فَقَبَضْتُ قَ[q:8594[بْ]ضَ[a:8595[ةً م]ِّنْ أَثَرِ [h:8596[ٱ][l[ل]رَّسُولِ فَنَبَذْتُهَا وَكَذ[n[َٲ]لِكَ سَوَّلَتْ لِى نَفْسِى","У: «Улар кўрмаган нарсани кўрдим. Бас, Расулнинг изидан бир сиқим олдим, сўнгра уни ташладим. Ҳавои нафсим менга шундай қилишни хуш кўрсатди», деди.",318,16],["قَالَ فَ[h:3488[ٱ]ذْهَ[q:3488[بْ] فَإِ[g[نّ]َ لَكَ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ أَ[f:8589[ن ت]َقُولَ لَا مِسَاسَ‌ۖ وَإِ[g[نّ]َ لَكَ مَوْعِ[u:8597[دًا ل]َّ[f:8598[ن ت]ُخْلَفَهُ[n[ۥ]‌ۖ وَ[h:1514[ٱ][f:1514[نظ]ُرْ إِلَ[o[ىٰٓ] إِلَ[n[ـٰ]هِكَ [h:8599[ٱ]لَّذِى ظَلْتَ عَلَيْهِ عَاكِ[u:8600[فًا‌ۖ ل]َّنُحَرِّقَ[g[نّ]َهُ[n[ۥ] ثُ[g[مّ]َ لَنَ[f:8601[نس]ِفَ[g[نّ]َهُ[n[ۥ] فِى [h:4971[ٱ]لْيَ[g[مّ]ِ نَسْفًا","У: «Бас, жўна! Кет! Энди сенга бу ҳаётда «тегиш йўқ» дейишинг бор, холос. Албатта, сенга хилоф қилмайдиган ваъдамиз бор. Ўзинг ибодатида бардавом бўлган илоҳингга назар солиб қўй. Биз уни, албатта, куйдирурмиз, сўнгра денгизга сочиб юборурмиз.",318,16],["إِ[g[نّ]َم[o[َآ] إِلَ[n[ـٰ]هُكُمُ [h:8602[ٱ]للَّهُ [h:4738[ٱ]لَّذِى ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۚ وَسِعَ كُلَّ شَىْءٍ عِلْمًا","Албатта, сизнинг илоҳингиз Аллоҳдир, холос. Ундан ўзга ибодатга сазовор зот йўқдир. У барча нарсани ўз илми билан қамраб олгандир.",318,16],["كَذ[n[َٲ]لِكَ نَقُصُّ عَلَيْكَ مِنْ أَ[i:1910[نۢب][o[َا]ٓءِ مَا قَ[q:298[دْ] سَبَقَ‌ۚ وَقَ[q:387[دْ] ءَاتَيْنَ[n[ـٰ]كَ م[u:2897[ِن ل]َّدُ[g[نّ]َا ذِكْرًا","Шундай қилиб, сенга ўтган нарсалар хабарини қисса қилиб берурмиз. Батаҳқиқ, сенга ўз тарафимиздан зикрни бердик.",319,16],["مَّنْ أَعْرَضَ عَنْهُ فَإِ[g[نّ]َهُ[n[ۥ] يَحْمِلُ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ وِزْرًا","Ким ундан юз ўгирса, албатта, у қиёмат куни юкини кўтарур.",319,16],["خَ[n[ـٰ]لِدِينَ فِيهِ‌ۖ وَس[o[َا]ٓءَ لَهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ حِمْلاً","Унда абадий қолурлар. Қиёмат кунида уларнинг юки қандай ҳам ёмон бўлди.",319,16],["يَوْمَ يُ[f:4184[نف]َخُ فِى [h:4185[ٱ][l[ل]صُّورِ‌ۚ وَنَحْشُرُ [h:8603[ٱ]لْمُ[q:4093[جْ]رِمِينَ يَوْمَئِ[f:8604[ذٍ ز]ُرْقًا","У кун сурга пуфланадиган кундир. Ўша кунда жиноятчиларни кўзлари кўк бўлган ҳолда тўплармиз.",319,16],["يَتَخَ[n[ـٰ]فَتُونَ بَيْنَهُمْ إ[u:7790[ِن ل]َّبِثْتُمْ إِلَّا عَشْرًا","Улар ўзаро: «Ўн кундан ортиқ турганингиз йўқ», дея шивирлашади.",319,16],["نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إ[u:7790[ِن ل]َّبِثْتُمْ إِلَّا يَوْمًا","Биз нима деяётганларини яхши билгувчимиз. Ўшанда уларнинг энг тўғри йўлдагиси: «Бир кундан ортиқ турганимиз йўқ», дейдир.",319,16],["وَيَسْــَٔلُونَكَ عَنِ [h:8605[ٱ]لْجِبَالِ فَقُلْ يَ[f:8606[نس]ِفُهَا رَبِّى نَسْفًا","Сендан тоғлар ҳақида сўрарлар. Бас: «Роббим уларни мутлақо совуриб юборажак.",319,16],["فَيَذَرُهَا قَا[f:8607[عًا ص]َفْصَفًا","Сўнг уларни теп-текис ҳолга келтирур.",319,16],["لَّا تَرَىٰ فِيهَا عِوَ[a:8608[جًا و]َل[o[َآ] أَمْتًا","У ерда чуқур ҳам, дўнг ҳам кўрмассан.",319,16],["يَوْمَئِ[a:8609[ذٍ ي]َتَّبِعُونَ [h:8610[ٱ][l[ل]دَّاعِىَ لَا عِوَجَ لَهُ[n[ۥ]‌ۖ وَخَشَعَتِ [h:8611[ٱ]لْأَصْوَاتُ لِلرَّحْمَ[n[ـٰ]نِ فَلَا تَسْمَعُ إِلَّا هَمْسًا","У кунда чорловчига эргашурлар. Ундан бурилиш йўқ. Овозлар Роҳман дан жим қолмиш. Пичирлашдан бошқа нарса эшитмассан.",319,16],["يَوْمَئِ[u:8612[ذٍ ل]َّا تَ[f:8613[نف]َعُ [h:8614[ٱ][l[ل]شَّفَ[n[ـٰ]عَةُ إِلَّا مَنْ أَذِنَ لَهُ [h:8399[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ وَرَضِىَ لَهُ[n[ۥ] قَوْلاً","У кунда Роҳман унга изн берган ва сўзидан рози бўлганлардан бошқанинг шафоати фойда бермас.",319,16],["يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِه[n[ِۦ] عِلْمًا","У уларни олдиларидаги нарсаларни ҳам, орқаларидаги нарсаларни ҳам билур. Улар эса, уни илм ила иҳота қила олмаслар.",319,16],["۞ وَعَنَتِ [h:8615[ٱ]لْوُجُوهُ لِلْحَىِّ [h:8616[ٱ]لْقَيُّومِ‌ۖ وَقَ[q:387[دْ] خَابَ مَنْ حَمَلَ ظُلْمًا","Бутун юзлар тирик ва доим турувчи зотга бош эгмиш. Батаҳқиқ, ким зулм кўтарган бўлса, ноумид бўлмиш.",319,16],["وَم[a:3112[َن ي]َعْمَلْ مِنَ [h:3154[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ وَهُوَ مُؤْمِ[f:8617[نٌ ف]َلَا يَخَافُ ظُلْ[a:8618[مًا و]َلَا هَضْمًا","Ким мўмин ҳолида яхши амаллардан қилган бўлса, зулмдан ҳам, нуқсондан ҳам қўрқмас», деб айт.",319,16],["وَكَذ[n[َٲ]لِكَ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ قُرْءَانًا عَرَبِي[a:8619[ًّا و]َصَرَّفْنَا فِيهِ مِنَ [h:8620[ٱ]لْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًا","Шундай қилиб, Биз уни арабий Қуръон этиб нозил этдик. Шоядки тақво қилсалар ёки уларда эслаш пайдо қилса, деб унда қўрқинчли ваъдаларни баён қилдик.",319,16],["فَتَعَ[n[ـٰ]لَى [h:5187[ٱ]للَّهُ [h:8621[ٱ]لْمَلِكُ [h:8622[ٱ]لْحَقُّ‌ۗ وَلَا تَعْجَلْ بِ[h:8623[ٱ]لْقُرْءَانِ مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:8624[َن ي]ُ[q:8625[قْ]ضَ[o[ىٰٓ] إِلَيْكَ وَحْيُهُ[n[ۥ]‌ۖ وَقُ[b:7725[ل] رَّبِّ زِ[q:8626[دْ]نِى عِلْمًا","Ҳақ Подшоҳ–Аллоҳ олий бўлди. Сенга ваҳийи битгунча Қуръон га ошиқма ва: «Роббим, илмимни зиёда қилгин», дегин.",320,16],["وَلَقَ[q:341[دْ] عَهِ[q:8627[دْ]ن[o[َآ] إِلَ[o[ىٰٓ] ءَادَمَ مِ[f:128[ن ق]َ[q:129[بْ]لُ فَنَسِىَ وَلَمْ نَجِ[q:8628[دْ] لَهُ[n[ۥ] عَزْمًا","Батаҳқиқ, илгари Биз Одам билан аҳдлашган эдик. Лекин у унутди. Унда азму қарор топмадик.",320,16],["وَإِذْ قُلْنَا لِلْمَلَ[o[ـٰٓ]ئِكَةِ [h:179[ٱ]سْجُدُو[s[اْ] لِأَدَمَ فَسَجَد[o[ُوٓ][s[اْ] إِلّ[o[َآ] إِ[q:180[بْ]لِيسَ أَبَىٰ","Биз фаришталарга: «Одамга сажда қилинг», деганимизда, улар сажда қилдилар. Магар Иблис бош тортди.",320,16],["فَقُلْنَا يَ[o[ـٰٓـ]ـَٔـادَمُ إِ[g[نّ]َ هَ[n[ـٰ]ذَا عَدُ[u:8629[وٌّ ل]َّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَ[g[نّ]َكُمَا مِنَ [h:4643[ٱ]لْجَ[g[نّ]َةِ فَتَشْقَىٰٓ","Бас, Биз: «Эй Одам, албатта, бу сенга ва жуфтингга душмандир. Яна у икковингизни жаннатдан чиқариб, бадбахт бўлиб қолмагин.",320,16],["إِ[g[نّ]َ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ","Албатта, сен у ерда оч-яланғоч қолмассан.",320,16],["وَأَ[g[نّ]َكَ لَا تَظْمَؤُ[s[اْ] فِيهَا وَلَا تَضْحَىٰ","Албатта, сен у ерда ташна ҳам бўлмассан, иссиқда ҳам қолмассан», дедик.",320,16],["فَوَسْوَسَ إِلَيْهِ [h:8630[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ قَالَ يَ[o[ـٰٓـ]ـَٔـادَمُ هَلْ أَدُلُّكَ عَلَىٰ شَجَرَةِ [h:8631[ٱ]لْخُلْدِ وَمُلْ[u:8632[كٍ ل]َّا يَ[q:8633[بْ]لَىٰ","Бас, шайтон уни васваса қилди. У: «Эй Одам, мен сенга абадият дарахтини ва битмас-туганмас мулкни кўрсатайми?» деди.",320,16],["فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْء[n[َٲ]تُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا م[a:4630[ِن و]َرَقِ [h:4631[ٱ]لْجَ[g[نّ]َةِ‌ۚ وَعَصَ[o[ىٰٓ] ءَادَمُ رَبَّهُ[n[ۥ] فَغَوَىٰ","Бас, икковлари ундан едилар. Кейин, авратлари ўзларига очилиб қолиб, ўзларини жаннат барглари билан тўса бошладилар. Одам Роббига осий бўлди ва йўлдан озди.",320,16],["ثُ[g[مّ]َ [h:8634[ٱ][q:8635[جْ]تَبَ[n[ـٰ]هُ رَبُّهُ[n[ۥ] فَتَابَ عَلَيْهِ وَهَدَىٰ","Сўнгра Робби уни танлаб олди, бас, тавбасини қабул қилди ва ҳидоятга бошлади.",320,16],["قَالَ [h:8636[ٱ]هْبِطَا مِنْهَا جَمِيع[i:8637[َۢا‌ۖ ب]َعْضُكُمْ لِبَعْضٍ عَدُ[f:8638[وٌّ‌ۖ ف]َإِ[g[مّ]َا يَأْتِيَ[g[نّ]َك[w:198[ُم م]ِّ[g[نّ]ِى هُ[f:8639[دًى ف]َمَنِ [h:8640[ٱ]تَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ","У зот: «Ҳаммангиз бир-бирингизга душман ҳолда ундан тушинг. Агар Мен томонимдан сизга ҳидоят келганида, ким ҳидоятимга эргашса, адашмас ва бадбахт бўлмас.",320,16],["وَمَنْ أَعْرَضَ عَ[f:8245[ن ذ]ِكْرِى فَإِ[g[نّ]َ لَهُ[n[ۥ] مَعِيشَ[f:8641[ةً ض]َن[a:8642[كًا و]َنَحْشُرُهُ[n[ۥ] يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ أَعْمَىٰ","Ким Менинг зикримдан юз ўгирса, албатта, унга торчилик ҳаёти бўлур ва қиёмат куни уни кўр ҳолида тирилтирурмиз», деди.",320,16],["قَالَ رَبِّ لِمَ حَشَرْتَن[o[ِىٓ] أَعْمَىٰ وَقَ[q:387[دْ] كُ[f:2917[نت]ُ بَصِيرًا","У: «Эй Роббим, нима учун мени кўр ҳолда тирилтирдинг. Ахир, кўрувчи эдим-ку!» деди.",320,16],["قَالَ كَذ[n[َٲ]لِكَ أَتَتْكَ ءَايَ[n[ـٰ]تُنَا فَنَسِيتَهَا‌ۖ وَكَذ[n[َٲ]لِكَ [h:8643[ٱ]لْيَوْمَ تُ[f:8644[نس]َىٰ","У зот: «Шундай. Сенга оятларимиз келди. Сен эса, уларни унутдинг? Шунингдек, сен ҳам бугун унутиурсан», деди.",321,16],["وَكَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى مَنْ أَسْرَفَ وَلَمْ يُؤْم[i:8645[ِنۢ ب]ِـَٔـايَ[n[ـٰ]تِ رَبِّه[n[ِۦ]‌ۚ وَلَعَذَابُ [h:7000[ٱ]لْأَخِرَةِ أَشَدُّ وَأَ[q:8540[بْ]قَىٰٓ","Исроф қилган ва Робби оятларига иймон келтирмаганларни ана шундай жазолайрмиз. Охират азоби, албатта, ашаддийроқ ва боқийроқдир.",321,16],["أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَ[q:8394[بْ]لَه[w:8646[ُم م]ِّنَ [h:6524[ٱ]لْقُرُونِ يَمْشُونَ فِى مَسَ[n[ـٰ]كِنِهِمْ‌ۗ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:2495[تٍ ل]ِّأُ[s[وْ]لِى [h:8506[ٱ][l[ل][g[نّ]ُهَىٰ","Улардан илгари уларнинг масканларида юрган асрлардан қанчадан-қанчасини ҳалок қилганимиз ҳам ҳидоят қилмадими? Албатта, бунда ақл эгалари учун ибратлар бордир.",321,16],["وَلَوْلَا كَلِمَ[f:5989[ةٌ س]َبَقَتْ م[u:770[ِن ر]َّبِّكَ لَكَانَ لِزَا[a:8647[مًا و]َأَجَ[a:3920[لٌ م]ُّسَ[g[مّ]ًى","Агар Роббингдан сўз ўтиб қолмаганида ва номланган ажал бўлмаганида, албатта, лозим бўлар эди.",321,16],["فَ[h:9999[ٱ]صْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَ[q:3282[بْ]لَ طُلُوعِ [h:8648[ٱ][l[ل]شَّمْسِ وَقَ[q:8649[بْ]لَ غُرُوبِهَا‌ۖ وَمِنْ ءَانَآىِٕ [h:8650[ٱ]لَّيْلِ فَسَبِّحْ وَأَ[q:8651[طْ]رَافَ [h:8652[ٱ][l[ل][g[نّ]َهَارِ لَعَلَّكَ تَرْضَىٰ","Бас, улар айтаётган нарсаларга сабр қил. Роббингга қуёш чиқишидан олдин ва ботишидан олдин тасбиҳ ва ҳамд айт. Шунингдек, кечанинг бир қисмида ва кундузнинг атрофида ҳам тасбиҳ айт. Шоядки рози бўлсанг.",321,16],["وَلَا تَمُدَّ[g[نّ]َ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِه[o[ِۦٓ] أَزْو[n[َٲ][a:7311[جًا م]ِّنْهُمْ زَهْرَةَ [h:8653[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا لِنَفْتِنَهُمْ فِيهِ‌ۚ وَرِزْقُ رَبِّكَ خَيْ[a:8546[رٌ و]َأَ[q:8540[بْ]قَىٰ","Кўзларингни уларни синаш учун айримларига баҳраманд қилиб берганимиз ҳаёти дунёнинг турли зийнатларига тикма. Роббингнинг ризқи яхши ва боқийдир.",321,16],["وَأْمُرْ أَهْلَكَ بِ[h:8322[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ وَ[h:8381[ٱ]صْطَبِرْ عَلَيْهَا‌ۖ لَا نَسْــَٔلُكَ رِزْ[a:8654[قًا‌ۖ ن]َّحْنُ نَرْزُقُكَ‌ۗ وَ[h:4941[ٱ]لْعَ[n[ـٰ]قِبَةُ لِلتَّ[q:1356[قْ]وَىٰ","Аҳлингни намозга амр эт ва ўзинг унга сабр қил. Биз сендан ризқ сўрамасмиз. Биз сенга ризқ берурмиз. Оқибат тақвоникидир.",321,16],["وَقَالُو[s[اْ] لَوْلَا يَأْتِينَا بِـَٔـايَ[a:1930[ةٍ م]ّ[u:192[ِن ر]َّبِّه[o[ِۦٓ‌ۚ] أَوَلَمْ تَأْتِه[c:8655[ِم ب]َيِّنَةُ مَا فِى [h:8656[ٱ][l[ل]صُّحُفِ [h:8657[ٱ]لْأُولَىٰ","Улар: «Бизга Роббидан оят-мўъжиза келтирса эди», дейдилар. Ахир, уларга аввалги саҳифалардаги нарсаларнинг баёноти келмадими?",321,16],["وَلَوْ أَ[g[نّ][o[َآ] أَهْلَكْنَ[n[ـٰ]ه[c:8658[ُم ب]ِعَذَا[a:5648[بٍ م]ِّ[f:1097[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] لَقَالُو[s[اْ] رَبَّنَا لَوْل[o[َآ] أَرْسَلْتَ إِلَيْنَا رَسُول[f:8659[اً ف]َنَتَّبِعَ ءَايَ[n[ـٰ]تِكَ مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:8660[َن ن]َّذِلَّ وَنَخْزَىٰ","Агар Биз уларни удан олдин азоб-ла ҳалок қилганимизда эди, албатта: «Эй Роббимиз, бизга Пайғамбар юборганингда эди, хору зор ва шарманда бўлишимиздан олдин оятларингга эргашган бўлар эдик», дердилар.",321,16],["قُلْ كُ[a:8661[لٌّ م]ُّتَرَبِّ[f:8662[صٌ ف]َتَرَبَّصُو[s[اْ‌ۖ] فَسَتَعْلَمُونَ مَنْ أَصْحَ[n[ـٰ]بُ [h:8663[ٱ][l[ل]صِّر[n[َٲ]طِ [h:8664[ٱ][l[ل]سَّوِىِّ وَمَنِ [h:8665[ٱ]هْتَدَىٰ","Сен: «Барча кутгувчидир. Бас, кутинглар. Албатта, кимлар тўғри йўл соҳиблари ва кимлар ҳидоят топганини билурсизлар», деб айт.",321,16]]},{"n":21,"ar":"الأَنبِيَاءِ","en":"Al-Anbiyaa","uz":"Анбиё","type":"Макка","ayahs":[["ٱ[q:5169[قْ]تَرَبَ لِل[g[نّ]َاسِ حِسَابُهُمْ وَهُمْ فِى غَفْلَ[a:8666[ةٍ م]ُّعْرِض[p[ُو]نَ","Одамларга ҳисоблари яқинлашиб қолди. Улар эса, ғафлатда, юз ўгирувчи бўлган ҳолларида.",322,17],["مَا يَأْتِيه[w:7205[ِم م]ِّ[f:8667[ن ذ]ِكْ[a:8668[رٍ م]ّ[u:22[ِن ر]َّبِّه[w:8669[ِم م]ُّحْدَثٍ إِلَّا [h:8670[ٱ]سْتَمَعُوهُ وَهُمْ يَلْعَب[p[ُو]نَ","Қачон Роббиларидан янги эслатма келса, фақат уни ўйнаётган ҳолларида тингларлар.",322,17],["لَاهِيَ[f:8671[ةً ق]ُلُوبُهُمْ‌ۗ وَأَسَرُّو[s[اْ] [h:8518[ٱ][l[ل][g[نّ]َ[q:8519[جْ]وَى [h:8672[ٱ]لَّذِينَ ظَلَمُو[s[اْ] هَلْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا بَشَ[a:7069[رٌ م]ِّثْلُكُمْ‌ۖ أَفَتَأْتُونَ [h:8673[ٱ][l[ل]سِّحْرَ وَأَ[f:98[نت]ُمْ تُ[q:8674[بْ]صِر[p[ُو]نَ","Қалблари ғофил бўлиб. Зулм қилганлар ўзаро: «Бу ўзимизга ўхшаган башардан ўзга эмас-ку. Ўзингиз кўриб туриб сеҳрга келасизми?» деб пичирлашарлар.",322,17],["قَالَ رَبِّى يَعْلَمُ [h:8675[ٱ]لْقَوْلَ فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ وَهُوَ [h:709[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","У: «Роббим осмону ердаги сўзни билур. У эшитгувчи ва билгувчи зотдир», деди.",322,17],["بَلْ قَال[o[ُوٓ][s[اْ] أَضْغَ[n[ـٰ]ثُ أَحْلَ[n[ـٰ][i:8676[مِۭ ب]َلِ [h:8677[ٱ]فْتَرَ[n[ٮٰ]هُ بَلْ هُوَ شَاعِ[f:8678[رٌ ف]َلْيَأْتِنَا بِـَٔـايَ[f:8679[ةٍ ك]َم[o[َآ] أُرْسِلَ [h:8680[ٱ]لْأَوَّل[p[ُو]نَ","Улар: «Балки алғов-далғов тушлардир, балки ўзи уйдириб олгандир, балки у шоирдир. Бас, бизга аввалгилар юборилганидек, мўъжиза келтирсин», дедилар.",322,17],["م[o[َآ] ءَامَنَتْ قَ[q:8394[بْ]لَه[w:8395[ُم م]ِّ[f:4585[ن ق]َرْيَةٍ أَهْلَكْنَ[n[ـٰ]ه[o[َآ‌ۖ] أَفَهُمْ يُؤْمِن[p[ُو]نَ","Улардан олдин бирор шаҳар иймон келтирмади. Биз уларни ҳалок қилдик. Энди улар иймон келтирармидилар?!",322,17],["وَم[o[َآ] أَرْسَلْنَا قَ[q:7849[بْ]لَكَ إِلَّا رِجَال[a:6851[اً ن]ُّوح[o[ِىٓ] إِلَيْهِمْ‌ۖ فَسْــَٔل[o[ُوٓ][s[اْ] أَهْلَ [h:7413[ٱ][l[ل]ذِّكْرِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ لَا تَعْلَم[p[ُو]نَ","Биз сендан илгари ҳам фақат эр кишиларни Пайғамбар қилиб юбориб, уларга ваҳий қилганмиз, холос. Агар билмасангиз зикр аҳлларидан сўранг.",322,17],["وَمَا جَعَلْنَ[n[ـٰ]هُمْ جَسَ[u:8681[دًا ل]َّا يَأْكُلُونَ [h:8682[ٱ][l[ل]طَّعَامَ وَمَا كَانُو[s[اْ] خَ[n[ـٰ]لِد[p[ِي]نَ","Биз уларни таом емайдиган жасад қилганимиз йўқ. Улар абадий қолгувчи ҳам бўлган эмаслар.",322,17],["ثُ[g[مّ]َ صَدَ[q:8683[قْ]نَ[n[ـٰ]هُمُ [h:8684[ٱ]لْوَعْدَ فَأَ[f:8685[نج]َيْنَ[n[ـٰ]هُمْ وَم[a:8686[َن ن]َّش[o[َا]ٓءُ وَأَهْلَكْنَا [h:8687[ٱ]لْمُسْرِف[p[ِي]نَ","Сўнгра уларга ваъдамиз устидан чиқдик. Бас, уларга ҳамда ўзимиз хоҳлаганларга нажот бердик ва исрофчиларни ҳалок қилдик.",322,17],["لَقَ[q:2389[دْ] أَ[f:515[نز]َلْن[o[َآ] إِلَيْكُمْ كِتَ[n[ـٰ][f:8688[بًا ف]ِيهِ ذِكْرُكُمْ‌ۖ أَفَلَا تَعْقِل[p[ُو]نَ","Батаҳқиқ, Биз сизга китоб нозил қилдик. Унда сизнинг зикрингиз бор. Ақл ишлатмайсизларми?!.",322,17],["وَكَمْ قَصَمْنَا مِ[f:4585[ن ق]َرْيَ[f:8689[ةٍ ك]َانَتْ ظَالِمَ[a:8690[ةً و]َأَ[f:3937[نش]َأْنَا بَعْدَهَا قَوْمًا ءَاخَر[p[ِي]نَ","Биз золим бўлган шаҳар-қишлоқлардан қанчасини синдирдик ва улардан кейин бошқа қавмларни пайдо этдик.",323,17],["فَلَ[g[مّ][o[َآ] أَحَسُّو[s[اْ] بَأْسَن[o[َآ] إِذَا ه[w:7261[ُم م]ِّنْهَا يَرْكُض[p[ُو]نَ","Бизнинг азобимизни ҳис қилганларида эса, бирдан у ердан қочишга бошларлар.",323,17],["لَا تَرْكُضُو[s[اْ] وَ[h:8691[ٱ]رْجِع[o[ُوٓ][s[اْ] إِلَىٰ م[o[َآ] أُتْرِفْتُمْ فِيهِ وَمَسَ[n[ـٰ]كِنِكُمْ لَعَلَّكُمْ تُسْــَٔل[p[ُو]نَ","Қочманглар! Маишатпарсатлик қилган нарсаларингизга, масканларингизга қайтинглар. Ҳали эҳтимол сўралурсизлар.",323,17],["قَالُو[s[اْ] يَ[n[ـٰ]وَيْلَن[o[َآ] إِ[g[نّ]َا كُ[g[نّ]َا ظَ[n[ـٰ]لِم[p[ِي]نَ","Улар: «Ҳолимизга вой! Биз, албатта, золим бўлган эканмиз», дедилар.",323,17],["فَمَا زَالَت تِّلْكَ دَعْوَ[n[ٮٰ]هُمْ حَتَّىٰ جَعَلْنَ[n[ـٰ]هُمْ حَصِيدًا خَ[n[ـٰ]مِد[p[ِي]نَ","Уларнинг ўша дод-войлари, Биз уларни ўрилган ўтдай, совуган кулдай қилгунимизча бардавом бўлди.",323,17],["وَمَا خَلَ[q:5159[قْ]نَا [h:8692[ٱ][l[ل]سَّم[o[َا]ٓءَ وَ[h:1474[ٱ]لْأَرْضَ وَمَا بَيْنَهُمَا لَ[n[ـٰ]عِب[p[ِي]نَ","Биз осмонлару ерни ва уларнинг орасидаги нарсаларни ўйин учун яратганимиз йўқ.",323,17],["لَوْ أَرَ[q:2878[دْ]ن[o[َآ] أ[a:8693[َن ن]َّتَّخِذَ لَهْ[u:8694[وًا ل]َّ[h:8695[ٱ]تَّخَذْنَ[n[ـٰ]هُ م[u:2897[ِن ل]َّدُ[g[نّ][o[َآ] إِ[f:4919[ن ك]ُ[g[نّ]َا فَ[n[ـٰ]عِل[p[ِي]نَ","Агар Биз кўнгилхуши тутишни ирода қилсак, уни қилувчи бўлганимизда ҳам, Ўз томонимиздан тутар эдик.",323,17],["بَلْ نَ[q:8696[قْ]ذِفُ بِ[h:370[ٱ]لْحَقِّ عَلَى [h:8697[ٱ]لْبَ[n[ـٰ]طِلِ فَيَ[q:8698[دْ]مَغُهُ[n[ۥ] فَإِذَا هُوَ زَاهِ[a:8699[قٌ‌ۚ و]َلَكُمُ [h:8700[ٱ]لْوَيْلُ مِ[g[مّ]َا تَصِف[p[ُو]نَ","Йўқ, Биз ҳақни ботил устига отурмиз. Бас, уни яксон қилур. Кўрибсанки, у заволга учрабди. Сизларга эса, қилган васфларингиздан ҳалокат келур.",323,17],["وَلَهُ[n[ۥ] مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَمَنْ عِ[f:719[ند]َهُ[n[ۥ] لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِه[n[ِۦ] وَلَا يَسْتَحْسِر[p[ُو]نَ","Осмонлару ердаги барча жонзотлар Уникидир. Унинг ҳузуридагилар ибодатидан такаббурлик қилмаслар ва малол олмаслар.",323,17],["يُسَبِّحُونَ [h:8701[ٱ]لَّيْلَ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ لَا يَفْتُر[p[ُو]نَ","Улар кечаю кундуз тасбиҳ айтарлар. Чарчамаслар.",323,17],["أَمِ [h:8702[ٱ]تَّخَذ[o[ُوٓ][s[اْ] ءَالِهَ[a:8703[ةً م]ِّنَ [h:1579[ٱ]لْأَرْضِ هُمْ يُ[f:8704[نش]ِر[p[ُو]نَ","Ёки улар ердан худолар тутдилару ўшалар тирилтирурларми?",323,17],["لَوْ كَانَ فِيهِم[o[َآ] ءَالِهَةٌ إِلَّا [h:1742[ٱ]للَّهُ لَفَسَدَتَا‌ۚ فَسُ[q:8705[بْ]حَ[n[ـٰ]نَ [h:8706[ٱ]للَّهِ رَبِّ [h:8707[ٱ]لْعَرْشِ عَ[g[مّ]َا يَصِف[p[ُو]نَ","Агар уларда Аллоҳдан ўзга «худо»лар бўлганида, бузулиб кетар эдилар. Аршнинг Робби Аллоҳ улар васф қилган нарсадан покдир.",323,17],["لَا يُسْــَٔلُ عَ[g[مّ]َا يَفْعَلُ وَهُمْ يُسْــَٔل[p[ُو]نَ","У қилган нарсасидан сўралмас. Ҳолбуки, улар сўралурлар.",323,17],["أَمِ [h:8702[ٱ]تَّخَذُو[s[اْ] مِ[f:3136[ن د]ُونِه[o[ِۦٓ] ءَالِهَ[f:8708[ةً‌ۖ ق]ُلْ هَاتُو[s[اْ] بُرْهَ[n[ـٰ]نَكُمْ‌ۖ هَ[n[ـٰ]ذَا ذِكْرُ م[a:8709[َن م]َّعِىَ وَذِكْرُ مَ[f:8710[ن ق]َ[q:2471[بْ]لِى‌ۗ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ [h:8711[ٱ]لْحَقَّ‌ۖ فَه[w:8712[ُم م]ُّعْرِض[p[ُو]نَ","Ёки ундан ўзга «худо»лар тутдиларми? Сен: «Ҳужжатларингизни келтиринг. Мана бу мен билан биргаларнинг зикридир ва мендан олдингиларнинг зикридир», дегин. Йўқ, уларнинг кўплари ҳақни билмаслар. Бас, улар юз ўгиргувчидирлар.",323,17],["وَم[o[َآ] أَرْسَلْنَا مِ[f:18[ن ق]َ[q:19[بْ]لِكَ م[u:2882[ِن ر]َّسُولٍ إِلَّا نُوح[o[ِىٓ] إِلَيْهِ أَ[g[نّ]َهُ[n[ۥ] ل[o[َآ] إِلَ[n[ـٰ]هَ إِلّ[o[َآ] أَنَا۟ فَ[h:8713[ٱ]عْبُد[p[ُو]نِ","Сендан илгари юборган ҳар бир Пайғамбарга: «Албатта, Мендан ўзга ибодатга сазовор илоҳ йўқ. Бас, Менга ибодат қилинг», деб ваҳий қилганмиз.",324,17],["وَقَالُو[s[اْ] [h:605[ٱ]تَّخَذَ [h:8419[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ وَلَ[f:607[دًا‌ۗ س]ُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ]‌ۚ بَلْ عِبَا[a:8714[دٌ م]ُّكْرَم[p[ُو]نَ","Улар: «Роҳман фарзанд тутди», дедилар. У покдир. Йўқ! Икром этилган бандалардирлар.",324,17],["لَا يَسْبِقُونَهُ[n[ۥ] بِ[h:7118[ٱ]لْقَوْلِ وَه[c:8715[ُم ب]ِأَمْرِه[n[ِۦ] يَعْمَل[p[ُو]نَ","Улар ундан олдин сўз айтмаслар. Улар Унинг амри ила амал қилурлар.",324,17],["يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ [h:8716[ٱ]رْتَضَىٰ وَه[w:8717[ُم م]ِّنْ خَشْيَتِه[n[ِۦ] مُشْفِق[p[ُو]نَ","У зот уларнинг олдиларидаги нарсани ҳам, ортларидаги нарсани ҳам биладир. Улар фақат у зот рози бўлган шахсларгагина шафоат қилурлар. Улар у зотнинг қўрқинчидан титраган ҳолда турурлар.",324,17],["۞ وَم[a:8718[َن ي]َقُلْ مِنْهُمْ إِ[g[نّ][o[ِىٓ] إِلَ[n[ـٰ][a:8719[هٌ م]ِّ[f:3136[ن د]ُونِه[n[ِۦ] فَذ[n[َٲ]لِكَ نَ[q:8720[جْ]زِيهِ جَهَ[g[نّ]َمَ‌ۚ كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4693[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Улардан ким: «Мен ундан ўзга илоҳман», деса, бас, ўшани жаҳаннам ила жазолармиз. Золимларни шундай жазолармиз.",324,17],["أَوَلَمْ يَرَ [h:8721[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:8722[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ كَانَتَا رَتْ[f:8723[قًا ف]َفَتَ[q:8724[قْ]نَ[n[ـٰ]هُمَا‌ۖ وَجَعَلْنَا مِنَ [h:4727[ٱ]لْم[o[َا]ٓءِ كُلَّ شَىْءٍ حَىٍّ‌ۖ أَفَلَا يُؤْمِن[p[ُو]نَ","Куфр келтирганлар осмонлару ер битишган бўлган эканини, бас, Биз уларни очганимизни ва сувдан ҳар бир тирик нарсани қилганимизни билмайдиларми? Иймон келтирмайдиларми?",324,17],["وَجَعَلْنَا فِى [h:44[ٱ]لْأَرْضِ رَو[n[َٲ]سِىَ أَ[f:7354[ن ت]َمِيدَ بِهِمْ وَجَعَلْنَا فِيهَا فِجَا[f:8725[جًا س]ُبُل[u:8726[اً ل]َّعَلَّهُمْ يَهْتَد[p[ُو]نَ","Биз ерда уларни тебранмасликлари учун тоғлар қилдик ва шоядки тўғри йўл топсалар, деб унда даралар, йўллар қилдик.",324,17],["وَجَعَلْنَا [h:8727[ٱ][l[ل]سَّم[o[َا]ٓءَ سَ[q:8728[قْ][a:8729[فًا م]َّحْفُو[a:8730[ظًا‌ۖ و]َهُمْ عَنْ ءَايَ[n[ـٰ]تِهَا مُعْرِض[p[ُو]نَ","Ва осмонни сақлаган шифт қилиб қўйдик. Улар эса, Унинг аломатларидан юз ўгиргувчи бўлмоқдалар.",324,17],["وَهُوَ [h:4114[ٱ]لَّذِى خَلَقَ [h:8731[ٱ]لَّيْلَ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ وَ[h:4264[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ‌ۖ كُ[f:6240[لٌّ ف]ِى فَلَ[a:8732[كٍ ي]َسْبَح[p[ُو]نَ","У кечаю кундузни, қуёшу ойни яратган зотдир. Ҳаммаси фалакда сузмоқдалар.",324,17],["وَمَا جَعَلْنَا لِبَشَ[a:8733[رٍ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ [h:8734[ٱ]لْخُلْدَ‌ۖ أَفَإِ[s[يْ][a[ن م]ِّتَّ فَهُمُ [h:8735[ٱ]لْخَ[n[ـٰ]لِد[p[ُو]نَ","Сендан олдин ҳам бирор башарга абадийликни қилганимиз йўқ. Агар сен ўлсанг, улар абадий қолар эканларми?",324,17],["كُلُّ نَفْ[f:2476[سٍ ذ][o[َا]ٓئِقَةُ [h:2477[ٱ]لْمَوْتِ‌ۗ وَنَ[q:8736[بْ]لُوك[c:8737[ُم ب]ِ[h:7687[ٱ][l[ل]شَّرِّ وَ[h:8738[ٱ]لْخَيْرِ فِتْنَ[a:8739[ةً‌ۖ و]َإِلَيْنَا تُرْجَع[p[ُو]نَ","Ҳар бир жон ўлимни татиб кўргувчидир. Биз сизларни ёмонлик ва яхшилик ила имтиҳон учун синаймиз ҳамда бизгагина қайтарилурсиз.",324,17],["وَإِذَا رَءَاكَ [h:8740[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] إ[a:8741[ِن ي]َتَّخِذُونَكَ إِلَّا هُزُوًا أَهَ[n[ـٰ]ذَا [h:8742[ٱ]لَّذِى يَذْكُرُ ءَالِهَتَكُمْ وَه[c:8743[ُم ب]ِذِكْرِ [h:8744[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ هُمْ كَ[n[ـٰ]فِر[p[ُو]نَ","Куфр келтирганлар сени кўрганларида, масхара қилиб: «Худоларингизни зикр қилаётган шуми?!» дейишдан бошқани билмаслар. Ҳолбуки, улар Роҳманнинг зикрига ўзлари кофирдирлар.",325,17],["خُلِقَ [h:8745[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ مِنْ عَجَ[f:8746[لٍ‌ۚ س]َأُ[s[وْ]رِيكُمْ ءَايَ[n[ـٰ]تِى فَلَا تَسْتَعْجِل[p[ُو]نِ","Инсон шошқалоқ ўлароқ яратилгандир. Мен, албатта, сизларга Ўз оят-аломатларимни кўрсатурман. Бас, мени шошилтирманглар.",325,17],["وَيَقُولُونَ مَتَىٰ هَ[n[ـٰ]ذَا [h:6081[ٱ]لْوَعْدُ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Улар: «Агар содиқ бўлсангиз, бу ваъда қачон бўладир», дерлар.",325,17],["لَوْ يَعْلَمُ [h:8747[ٱ]لَّذِينَ كَفَرُو[s[اْ] حِينَ لَا يَكُفُّونَ ع[a:8748[َن و]ُجُوهِهِمُ [h:8749[ٱ][l[ل][g[نّ]َارَ وَلَا عَ[f:8750[ن ظ]ُهُورِهِمْ وَلَا هُمْ يُ[f:237[نص]َر[p[ُو]نَ","Куфр келтирганлар юзларидан ва сиртларидан оловни тўса олмайдиган ва ўзларига ёрдам берилмайдиган вақтни билсалар эди.",325,17],["بَلْ تَأْتِيه[c:8751[ِم ب]َغْتَ[f:8752[ةً ف]َتَ[q:8753[بْ]هَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُ[f:826[نظ]َر[p[ُو]نَ","Йўқ! У уларга тўсатдан келиб, ҳайрату даҳшатга солур. Бас, уни рад қилишга қодир бўлмаслар ва уларга муҳлат ҳам берилмас.",325,17],["وَلَقَدِ [h:3947[ٱ]سْتُهْزِئَ بِرُسُ[a:3948[لٍ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ فَحَاقَ بِ[h:2413[ٱ]لَّذِينَ سَخِرُو[s[اْ] مِنْه[w:3670[ُم م]َّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Батаҳқиқ, сендан олдин ҳам Пайғамбарлар масхара қилинган. Бас, уларни масхара қилганларга ўзлари масхара этиб юрган нарса тушди.",325,17],["قُلْ م[a:8754[َن ي]َكْلَؤُك[c:8755[ُم ب]ِ[h:1622[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ مِنَ [h:8351[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ‌ۗ بَلْ هُمْ عَ[f:3773[ن ذ]ِكْرِ رَبِّه[w:8756[ِم م]ُّعْرِض[p[ُو]نَ","Сен: «Кечаси ва кундузи сизни Роҳмандан ким қўрийди?» дегин. Йўқ! Улар Роббилари зикридан юз ўгиргувчилардир!",325,17],["أَمْ لَهُمْ ءَالِهَ[f:8757[ةٌ ت]َمْنَعُه[w:8758[ُم م]ِّ[f:8759[ن د]ُونِنَا‌ۚ لَا يَسْتَطِيعُونَ نَصْرَ أَ[f:568[نف]ُسِهِمْ وَلَا ه[w:8760[ُم م]ِّ[g[نّ]َا يُصْحَب[p[ُو]نَ","Ёки уларнинг Биздан ўзга ҳимоя қиладиган «худо»лари борми? Улар ўзларига ҳам ёрдам беришга қодир бўла олмаслар ва Биздан дўстлик топмаслар.",325,17],["بَلْ مَتَّعْنَا هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ وَءَاب[o[َا]ٓءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ [h:8761[ٱ]لْعُمُرُ‌ۗ أَفَلَا يَرَوْنَ أَ[g[نّ]َا نَأْتِى [h:7024[ٱ]لْأَرْضَ نَ[f:7025[نق]ُصُهَا مِنْ أَ[q:7026[طْ]رَافِه[o[َآ‌ۚ] أَفَهُمُ [h:8762[ٱ]لْغَ[n[ـٰ]لِب[p[ُو]نَ","Балки Биз уларни ва ота-боболарини баҳраманд қилдик, ҳатто уларга умр узун кўринди. Улар ерга келиб, уни атрофидан қисқартираётганимизни кўрмайдиларми?! Ғолиб келгувчи уларми?",325,17],["قُلْ إِ[g[نّ]َم[o[َآ] أُ[f:8763[نذ]ِرُك[c:8764[ُم ب]ِ[h:8765[ٱ]لْوَحْىِ‌ۚ وَلَا يَسْمَعُ [h:8766[ٱ][l[ل]صُّ[g[مّ]ُ [h:8767[ٱ][l[ل]دُّع[o[َا]ٓءَ إِذَا مَا يُ[f:8768[نذ]َر[p[ُو]نَ","Сен: «Мен сизларни фақат ваҳий орқалигина огоҳлантирурман. Гунглар огоҳлантирилганларида даъватни эшитмаслар», дегин.",326,17],["وَلَئ[a:8769[ِن م]َّسَّتْهُمْ نَفْحَ[a:8770[ةٌ م]ِّنْ عَذَابِ رَبِّكَ لَيَقُولُ[g[نّ]َ يَ[n[ـٰ]وَيْلَن[o[َآ] إِ[g[نّ]َا كُ[g[نّ]َا ظَ[n[ـٰ]لِم[p[ِي]نَ","Қасамки, агар уларга Роббинг азобидан салгина етса, албатта: «Ҳолимизга вой! Ҳақиқатда биз золимлар бўлган эканмиз», дерлар.",326,17],["وَنَضَعُ [h:8771[ٱ]لْمَو[n[َٲ]زِينَ [h:8772[ٱ]لْقِسْطَ لِيَوْمِ [h:8773[ٱ]لْقِيَ[n[ـٰ]مَةِ فَلَا تُظْلَمُ نَفْ[f:8774[سٌ ش]َيْـ[a:3553[ـًٔا‌ۖ و]َإِ[f:1649[ن ك]َانَ مِثْقَالَ حَبَّ[a:8775[ةٍ م]ِّنْ خَرْدَلٍ أَتَيْنَا بِهَا‌ۗ وَكَفَىٰ بِنَا حَ[n[ـٰ]سِب[p[ِي]نَ","Биз қиёмат куни учун адолат тарозуларини қўюрмиз. Бирор жонга ҳеч қандай зулм қилинмас. Агар ачитқи донаси оғирлигича бўлса ҳам, келтирурмиз. Ҳисобчиликда Ўзимиз кифоя қилурмиз.",326,17],["وَلَقَ[q:341[دْ] ءَاتَيْنَا مُوسَىٰ وَهَ[n[ـٰ]رُونَ [h:8776[ٱ]لْفُرْقَانَ وَضِي[o[َا]ٓ[a:8777[ءً و]َذِكْ[u:8778[رًا ل]ِّلْمُتَّق[p[ِي]نَ","Батаҳқиқ, Биз Мусо ва Ҳорунга Фурқонни тақводорлар учун зиё ва эслатма қилиб бердик.",326,17],["ٱلَّذِينَ يَخْشَوْنَ رَبَّه[c:8779[ُم ب]ِ[h:13[ٱ]لْغَيْبِ وَه[w:8780[ُم م]ِّنَ [h:8781[ٱ][l[ل]سَّاعَةِ مُشْفِق[p[ُو]نَ","Улар Роббиларидан ғойибона қўрқурлар ва улар соатидан титрарлар.",326,17],["وَهَ[n[ـٰ]ذَا ذِكْ[a:8782[رٌ م]ُّبَارَكٌ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ‌ۚ أَفَأَ[f:8783[نت]ُمْ لَهُ[n[ۥ] مُ[f:6721[نك]ِر[p[ُو]نَ","Бу, Биз нозил қилган муборак эслатмадир. Сизлар уни инкор қилгувчи бўласизларми?!",326,17],["۞ وَلَقَ[q:341[دْ] ءَاتَيْن[o[َآ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ رُشْدَهُ[n[ۥ] مِ[f:128[ن ق]َ[q:129[بْ]لُ وَكُ[g[نّ]َا بِه[n[ِۦ] عَ[n[ـٰ]لِم[p[ِي]نَ","Батаҳқиқ, илгари Биз Иброҳимга рушди ҳидоятни берган эдик. Биз унинг билгувчи эдик.",326,17],["إِذْ قَالَ لِأَبِيهِ وَقَوْمِه[n[ِۦ] مَا هَ[n[ـٰ]ذِهِ [h:8784[ٱ][l[ل]تَّمَاثِيلُ [h:8785[ٱ]لَّت[o[ِىٓ] أَ[f:428[نت]ُمْ لَهَا عَ[n[ـٰ]كِف[p[ُو]نَ","Ўшанда у отасига ва қавмига: «Манави сиз ибодатига берилаётган ҳайкаллар нима?» деган эди.",326,17],["قَالُو[s[اْ] وَجَ[q:3834[دْ]ن[o[َآ] ءَاب[o[َا]ٓءَنَا لَهَا عَ[n[ـٰ]بِد[p[ِي]نَ","Улар: «Ота-боболаримизни уларга ибодат қилган ҳолларида топганмиз», дедилар.",326,17],["قَالَ لَقَ[q:2389[دْ] كُ[f:100[نت]ُمْ أَ[f:428[نت]ُمْ وَءَاب[o[َا]ٓؤُكُمْ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","У: «Батаҳқиқ, сиз ҳам, ота-боболарингиз ҳам очиқ-ойдин залолатдасизлар», деди.",326,17],["قَال[o[ُوٓ][s[اْ] أَجِئْتَنَا بِ[h:370[ٱ]لْحَقِّ أَمْ أَ[f:169[نت]َ مِنَ [h:8786[ٱ][l[ل]لَّ[n[ـٰ]عِب[p[ِي]نَ","Улар: «Сен бизга ҳақ ила келдингми ёки ўйин қилгувчиларданмисан?» дедилар.",326,17],["قَالَ بَ[b:8787[ل] رَّبُّكُمْ رَبُّ [h:6926[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ [h:8788[ٱ]لَّذِى فَطَرَهُ[g[نّ]َ وَأَنَا۟ عَلَىٰ ذ[n[َٲ]لِك[w:8789[ُم م]ِّنَ [h:2069[ٱ][l[ل]شَّ[n[ـٰ]هِد[p[ِي]نَ","У: «Йўқ! Роббингиз осмонлару ернинг Роббидир. У зот уларни яратгандир. Мен бунга гувоҳлик бергувчиларданман.",326,17],["وَتَ[h:9999[ٱ]للَّهِ لَأَكِيدَ[g[نّ]َ أَصْنَ[n[ـٰ]مَك[c:8790[ُم ب]َعْدَ أَ[f:902[ن ت]ُوَلُّو[s[اْ] مُ[q:5528[دْ]بِر[p[ِي]نَ","Аллоҳга қасамки, сизлар ортга ўгирилиб кетганингиздан кейин санамларингизга бир бало қиламан», деди.",326,17],["فَجَعَلَهُمْ جُذ[n[َٲ]ذًا إِلَّا كَبِي[u:8791[رًا ل]َّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِع[p[ُو]نَ","Бас, уларни парча-парча қилиб ташлади. Магар энг каттасини, шоядки унга қайтсалар, деб қолдирди.",327,17],["قَالُو[s[اْ] مَ[f:8792[ن ف]َعَلَ هَ[n[ـٰ]ذَا بِـَٔـالِهَتِن[o[َآ] إِ[g[نّ]َهُ[n[ۥ] لَمِنَ [h:766[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Улар: «Бизнинг худоларимизга ким бундай қилди?! Албатта, у золимлардандир!» дедилар.",327,17],["قَالُو[s[اْ] سَمِعْنَا فَ[a:8793[تًى ي]َذْكُرُهُمْ يُقَالُ لَهُ[o[ۥٓ] إِ[q:2003[بْ]ر[n[َٲ]ه[p[ِي]مُ","Улар: «Уларни эслаб юрган бир йигитни эшитган эдик, уни Иброҳим, деб айтиларди», дедилар.",327,17],["قَالُو[s[اْ] فَأْتُو[s[اْ] بِه[n[ِۦ] عَلَ[o[ىٰٓ] أَعْيُنِ [h:8794[ٱ][l[ل][g[نّ]َاسِ لَعَلَّهُمْ يَشْهَد[p[ُو]نَ","Улар: «Уни одамлар кўзи олдига олиб келинглар. Шоядки гувоҳ бўлсинлар», дедилар.",327,17],["قَال[o[ُوٓ][s[اْ] ءَأَ[f:3896[نت]َ فَعَلْتَ هَ[n[ـٰ]ذَا بِـَٔـالِهَتِنَا يَ[o[ـٰٓ]إِ[q:6429[بْ]ر[n[َٲ]ه[p[ِي]مُ","Улар: «Худоларимизга буни сен қилдингми, эй Иброҳим?!» дедилар.",327,17],["قَالَ بَلْ فَعَلَهُ[n[ۥ] كَبِيرُهُمْ هَ[n[ـٰ]ذَا فَسْــَٔلُوهُمْ إِ[f:5674[ن ك]َانُو[s[اْ] يَ[f:8795[نط]ِق[p[ُو]نَ","У: «Йўқ, буни манави, уларнинг каттаси қилди. Агар гапирадиган бўлсалар, улардан сўраб кўринглар», деди.",327,17],["فَرَجَع[o[ُوٓ][s[اْ] إِلَ[o[ىٰٓ] أَ[f:568[نف]ُسِهِمْ فَقَال[o[ُوٓ][s[اْ] إِ[g[نّ]َكُمْ أَ[f:8796[نت]ُمُ [h:8797[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Бас, улар ўзларига келдилар ва: «Албатта, сизлар ўзингиз золимдирсиз», дедилар.",327,17],["ثُ[g[مّ]َ نُكِسُو[s[اْ] عَلَىٰ رُءُوسِهِمْ لَقَ[q:2389[دْ] عَلِمْتَ مَا هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ يَ[f:8795[نط]ِق[p[ُو]نَ","Сўнгра яна бошлари айланиб: «Сен, батаҳқиқ, буларнинг гапирмаслигини билар эдинг!» дедилар.",327,17],["قَالَ أَفَتَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مَا لَا يَ[f:6307[نف]َعُكُمْ شَيْـ[a:232[ـًٔا و]َلَا يَضُرُّكُمْ","У: «Аллоҳни қўйиб, сиз ҳеч манфаат ҳам, зарар ҳам бермайдиган нарсага ибодат қиласизми?!",327,17],["أُ[u:8798[فٍّ ل]َّكُمْ وَلِمَا تَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ‌ۖ أَفَلَا تَعْقِل[p[ُو]نَ","Сизга ҳам, Аллоҳни қўйиб, ибодат қилаётган нарсаларингизга ҳам суф-э! Ахир, ақл юритиб кўрмайсизларми?!» деди.",327,17],["قَالُو[s[اْ] حَرِّقُوهُ وَ[h:8799[ٱ][f:8799[نص]ُر[o[ُوٓ][s[اْ] ءَالِهَتَكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ فَ[n[ـٰ]عِل[p[ِي]نَ","Улар: «Уни куйдиринглар! Агар қиладиган бўлсангиз, худоларингизга ёрдам беринг!» дедилар.",327,17],["قُلْنَا يَ[n[ـٰ]نَارُ كُونِى بَرْ[a:8800[دًا و]َسَلَ[n[ـٰ]مًا عَلَ[o[ىٰٓ] إِ[q:1860[بْ]ر[n[َٲ]ه[p[ِي]مَ","Биз: «Эй олов, сен Иброҳимга салқин ва саломатлик бўл!» дедик.",327,17],["وَأَرَادُو[s[اْ] بِه[n[ِۦ] كَيْ[f:8801[دًا ف]َجَعَلْنَ[n[ـٰ]هُمُ [h:8802[ٱ]لْأَخْسَر[p[ِي]نَ","Улар уга ёмонлик ирода қилган эдилар. Биз уларни энг зиёнкорлар қилиб қўйдик.",327,17],["وَنَجَّيْنَ[n[ـٰ]هُ وَلُوطًا إِلَى [h:5136[ٱ]لْأَرْضِ [h:8803[ٱ]لَّتِى بَ[n[ـٰ]رَكْنَا فِيهَا لِلْعَ[n[ـٰ]لَم[p[ِي]نَ","Унга ва Лутга нажот бериб, оламлар учун баракали қилган ерга юбордик.",327,17],["وَوَهَ[q:4212[بْ]نَا لَهُ[o[ۥٓ] إِسْحَ[n[ـٰ]قَ وَيَعْقُوبَ نَافِلَ[a:8804[ةً‌ۖ و]َكُل[f:8357[اًّ ج]َعَلْنَا صَ[n[ـٰ]لِح[p[ِي]نَ","Унга Исҳоқни ҳадя этдик ва Яъқубни зиёда қилиб бердик ва ҳаммаларини аҳли солиҳлар қилдик.",327,17],["وَجَعَلْنَ[n[ـٰ]هُمْ أَئِ[g[مّ]َ[a:8805[ةً ي]َهْدُونَ بِأَمْرِنَا وَأَوْحَيْن[o[َآ] إِلَيْهِمْ فِعْلَ [h:8806[ٱ]لْخَيْر[n[َٲ]تِ وَإِقَامَ [h:8807[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ وَإِيت[o[َا]ٓءَ [h:8808[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةِ‌ۖ وَكَانُو[s[اْ] لَنَا عَ[n[ـٰ]بِد[p[ِي]نَ","Ва уларни Ўз амримиз ила ҳидоятга бошловчилар қилдик. Уларга яхшиликлар қилишни, намозни тугал адо этишни ва закот беришни ваҳий қилдик. Улар Бизга ибодат қилгувчилар бўлдилар.",328,17],["وَلُوطًا ءَاتَيْنَ[n[ـٰ]هُ حُكْ[a:6600[مًا و]َعِلْ[a:8809[مًا و]َنَجَّيْنَ[n[ـٰ]هُ مِنَ [h:8810[ٱ]لْقَرْيَةِ [h:5089[ٱ]لَّتِى كَانَت تَّعْمَلُ [h:8811[ٱ]لْخَبَ[o[ـٰٓ]ئِثَ‌ۗ إِ[g[نّ]َهُمْ كَانُو[s[اْ] قَوْمَ سَوْ[f:8812[ءٍ ف]َ[n[ـٰ]سِق[p[ِي]نَ","Ва Лутга ҳукм ва илм бердик ва унга ифлосликлар қилаётган қишлоқдан нажот бердик. Албатта, улар ёмон, бузғунчи қавм эдилар.",328,17],["وَأَ[q:8813[دْ]خَلْنَ[n[ـٰ]هُ فِى رَحْمَتِن[o[َآ‌ۖ] إِ[g[نّ]َهُ[n[ۥ] مِنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Ва Биз уни Ўз раҳматимизга киритдик. Албатта, у солиҳлардандир.",328,17],["وَنُوحًا إِذْ نَادَىٰ مِ[f:128[ن ق]َ[q:129[بْ]لُ فَ[h:8814[ٱ]سْتَجَ[q:8814[بْ]نَا لَهُ[n[ۥ] فَنَجَّيْنَ[n[ـٰ]هُ وَأَهْلَهُ[n[ۥ] مِنَ [h:8815[ٱ]لْكَرْبِ [h:8816[ٱ]لْعَظ[p[ِي]مِ","Ва Нуҳни. Бундан олдин у нидо этганида, Биз унинг нидосига жавоб қилдик ва унга ҳамда унинг аҳлига улуғ ғамдан нажот бердик.",328,17],["وَنَصَرْنَ[n[ـٰ]هُ مِنَ [h:4196[ٱ]لْقَوْمِ [h:4053[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِن[o[َآ‌ۚ] إِ[g[نّ]َهُمْ كَانُو[s[اْ] قَوْمَ سَوْ[f:8817[ءٍ ف]َأَغْرَ[q:4970[قْ]نَ[n[ـٰ]هُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Унга оятларимизни ёлғонга чиқарган қавмга қарши нусрат бердик. Албатта, улар ёмон қавм эдилар. Бас, Биз уларнинг барчасини ғарқ қилдик.",328,17],["وَدَاوُ[n[ۥ]دَ وَسُلَيْمَ[n[ـٰ]نَ إِذْ يَحْكُمَانِ فِى [h:8818[ٱ]لْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ [h:8819[ٱ]لْقَوْمِ وَكُ[g[نّ]َا لِحُكْمِهِمْ شَ[n[ـٰ]هِد[p[ِي]نَ","Ва Довуд билан Сулаймоннинг экинзор ҳақида ҳукм қилаётганларини. Ўшанда уга қавмнинг қўйи кечаси тарқалиб кетган эди. Биз уларнинг ҳукмига шоҳид бўлган эдик.",328,17],["فَفَهَّمْنَ[n[ـٰ]هَا سُلَيْمَ[n[ـٰ]نَ‌ۚ وَكُلاًّ ءَاتَيْنَا حُكْ[a:6600[مًا و]َعِلْ[a:8820[مًا‌ۚ و]َسَخَّرْنَا مَعَ دَاوُ[n[ۥ]دَ [h:8821[ٱ]لْجِبَالَ يُسَبِّحْنَ وَ[h:8822[ٱ][l[ل]طَّيْرَ‌ۚ وَكُ[g[نّ]َا فَ[n[ـٰ]عِل[p[ِي]نَ","Бас, Биз уни Сулаймонга фаҳмлатдик. Уларнинг ҳар бирига ҳукмни ва илмни берган эдик. Довуд билан бирга тасбиҳ айтсин деб тоғларни ва қушларни бўйинсундириб қўйдик. Шуларни қилгувчи бўлган Бизмиз.",328,17],["وَعَلَّمْنَ[n[ـٰ]هُ صَنْعَةَ لَبُو[u:8823[سٍ ل]َّكُمْ لِتُحْصِنَك[w:8824[ُم م]ّ[i:8825[ِنۢ ب]َأْسِكُمْ‌ۖ فَهَلْ أَ[f:428[نت]ُمْ شَ[n[ـٰ]كِر[p[ُو]نَ","Биз унга сизлар учун сизни ёмонликдан сақлайдиган кийим қилиш санъатини ўргатдик. Энди шукр қиларсизлар?!",328,17],["وَلِسُلَيْمَ[n[ـٰ]نَ [h:8826[ٱ][l[ل]رِّيحَ عَاصِفَ[f:8827[ةً ت]َ[q:120[جْ]رِى بِأَمْرِه[o[ِۦٓ] إِلَى [h:5136[ٱ]لْأَرْضِ [h:8803[ٱ]لَّتِى بَ[n[ـٰ]رَكْنَا فِيهَا‌ۚ وَكُ[g[نّ]َا بِكُلِّ شَىْءٍ عَ[n[ـٰ]لِم[p[ِي]نَ","Сулаймонга шамолни қаттиқ эсувчи қилиб бердик. Уни унинг амри ила, Биз баракали қилган ерга эсадиган қилиб қўйдик. Барча нарсани билгувчи бўлдик.",328,17],["وَمِنَ [h:8828[ٱ][l[ل]شَّيَ[n[ـٰ]طِينِ م[a:8829[َن ي]َغُوصُونَ لَهُ[n[ۥ] وَيَعْمَلُونَ عَمَل[f:8830[اً د]ُونَ ذ[n[َٲ]لِكَ‌ۖ وَكُ[g[نّ]َا لَهُمْ حَ[n[ـٰ]فِظ[p[ِي]نَ","Ва шайтонлардан унга ғаввослик қиладиганларни ва бундан бошқа амалларни қиладиганларни қилдик. Биз уларни муҳофаза қилгувчи бўлдик.",329,17],["۞ وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُ[o[ۥٓ] أَ[g[نّ]ِى مَسَّنِىَ [h:8831[ٱ][l[ل]ضُّرُّ وَأَ[f:3893[نت]َ أَرْحَمُ [h:5034[ٱ][l[ل]رّ[n[َٲ]حِم[p[ِي]نَ","Ва Айюбнинг ўз Роббига нидо қилиб: «Албатта, мени зарар тутди. Сенинг Ўзинг раҳмлиларнинг раҳмлигисан!» деганини эсла.",329,17],["فَ[h:9999[ٱ]سْتَجَ[q:8814[بْ]نَا لَهُ[n[ۥ] فَكَشَفْنَا مَا بِه[n[ِۦ] مِ[f:8832[ن ض]ُ[a:8833[رٍّ‌ۖ و]َءَاتَيْنَ[n[ـٰ]هُ أَهْلَهُ[n[ۥ] وَمِثْلَه[w:8834[ُم م]َّعَهُمْ رَحْمَ[a:5993[ةً م]ِّنْ عِ[f:6142[ند]ِنَا وَذِكْرَىٰ لِلْعَ[n[ـٰ]بِد[p[ِي]نَ","Бас, Биз унинг истижобат қилдик. Унга етган зарарни кетказдик. Унга аҳлини, улар билан бирга яна шунчани ҳам бердик. Буни Ўз раҳматимиз ила ва, обидларга эслатма бўлсин, деб қилдик.",329,17],["وَإِسْمَ[n[ـٰ]عِيلَ وَإِ[q:8835[دْ]رِيسَ وَذَا [h:8836[ٱ]لْكِفْلِ‌ۖ كُ[a:4216[لٌّ م]ِّنَ [h:8837[ٱ][l[ل]صَّ[n[ـٰ]بِر[p[ِي]نَ","Ва Исмоил, Идрис ва Зул-кифлни эсла. Уларнинг ҳар бири сабр қилгувчилардандир.",329,17],["وَأَ[q:8838[دْ]خَلْنَ[n[ـٰ]هُمْ فِى رَحْمَتِن[o[َآ‌ۖ] إِ[g[نّ]َه[w:8839[ُم م]ِّنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Ва уларни Ўз раҳматимизга киритдик. Албатта, улар солиҳлардандир.",329,17],["وَذَا [h:8840[ٱ][l[ل][g[نّ]ُونِ إِذ ذَّهَبَ مُغَ[n[ـٰ]ضِ[f:8841[بًا ف]َظَ[g[نّ]َ أ[u:8842[َن ل]ّ[a:8843[َن ن]َّ[q:8844[قْ]دِرَ عَلَيْهِ فَنَادَىٰ فِى [h:4033[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ أ[u:4908[َن ل]ّ[o[َآ] إِلَ[n[ـٰ]هَ إِلّ[o[َآ] أَ[f:169[نت]َ سُ[q:168[بْ]حَ[n[ـٰ]نَكَ إِ[g[نّ]ِى كُ[f:2917[نت]ُ مِنَ [h:187[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Зуннунни эсла. Ўшанда у ғазабланган ҳолда чиқиб кетган эди. Бас, у Бизни ўзига тор этмайди, деб гумон қилди. Зулматларда туриб, Сендан ўзга Илоҳ йўқ, Сен поксан, албатта, мен золимлардан бўлдим, деб нидо қилди.",329,17],["فَ[h:9999[ٱ]سْتَجَ[q:8814[بْ]نَا لَهُ[n[ۥ] وَنَجَّيْنَ[n[ـٰ]هُ مِنَ [h:8482[ٱ]لْغَ[g[مّ]ِ‌ۚ وَكَذ[n[َٲ]لِكَ نُـۨجِى [h:8845[ٱ]لْمُؤْمِن[p[ِي]نَ","Бас, Биз унинг ижобат қилдик. Унга ғамдан нажот бердик. Мўминларга шундай нажот берурмиз.",329,17],["وَزَكَرِيّ[o[َآ] إِذْ نَادَىٰ رَبَّهُ[n[ۥ] رَبِّ لَا تَذَرْنِى فَرْ[a:8846[دًا و]َأَ[f:3893[نت]َ خَيْرُ [h:8847[ٱ]لْو[n[َٲ]رِث[p[ِي]نَ","Ва Закариёни эсла. Ўшанда у Роббига нидо қилиб: «Эй Роббим, мени ёлғиз ташлаб қўйма, Сен, Ўзинг ворисларнинг энг яхшисисан», деган эди.",329,17],["فَ[h:9999[ٱ]سْتَجَ[q:8814[بْ]نَا لَهُ[n[ۥ] وَوَهَ[q:4212[بْ]نَا لَهُ[n[ۥ] يَحْيَىٰ وَأَصْلَحْنَا لَهُ[n[ۥ] زَوْجَهُ[o[ۥٓ‌ۚ] إِ[g[نّ]َهُمْ كَانُو[s[اْ] يُسَ[n[ـٰ]رِعُونَ فِى [h:2181[ٱ]لْخَيْر[n[َٲ]تِ وَيَ[q:8848[دْ]عُونَنَا رَغَ[a:8849[بًا و]َرَهَ[a:8850[بًا‌ۖ و]َكَانُو[s[اْ] لَنَا خَ[n[ـٰ]شِع[p[ِي]نَ","Бас, Биз унинг ижобат этдик ва унга Яҳъёни ҳадя қилдик ҳамда жуфтини ўнглаб қўйдик. Албатта, улар яхшиликларга шошилишар эди ва Бизга рағбат ила ва қўрқиб дуо қилишар эди. Улар Бизга таъзим ила бўйинсунувчи эдилар.",329,17],["وَ[h:9999[ٱ]لَّت[o[ِىٓ] أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا م[u:8851[ِن ر]ُّوحِنَا وَجَعَلْنَ[n[ـٰ]هَا وَ[h:8852[ٱ][q:8852[بْ]نَه[o[َآ] ءَايَ[u:8853[ةً ل]ِّلْعَ[n[ـٰ]لَم[p[ِي]نَ","Фаржини пок сақлаган аёлни эсла. Биз унга Ўз руҳимиздан пуфладик. Уни ва унинг ўғлини оламларга оят-белги қилдик.",330,17],["إِ[g[نّ]َ هَ[n[ـٰ]ذِه[o[ِۦٓ] أُ[g[مّ]َتُكُمْ أُ[g[مّ]َ[a:1159[ةً و][n[َٲ]حِدَ[a:8854[ةً و]َأَنَا۟ رَبُّكُمْ فَ[h:8713[ٱ]عْبُد[p[ُو]نِ","Албатта, сизнинг ушбу умматингиз бир умматдир ва Мен сизнинг Роббингизман. Бас, Менгагина ибодат қилинг.",330,17],["وَتَقَطَّع[o[ُوٓ][s[اْ] أَمْرَه[c:8517[ُم ب]َيْنَهُمْ‌ۖ كُلٌّ إِلَيْنَا ر[n[َٲ]جِع[p[ُو]نَ","Улар эса ишларини парчаладилар. Барчалари Бизга қайтувчидирлар.",330,17],["فَم[a:8855[َن ي]َعْمَلْ مِنَ [h:3154[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ وَهُوَ مُؤْمِ[f:8617[نٌ ف]َلَا كُفْرَانَ لِسَعْيِه[n[ِۦ] وَإِ[g[نّ]َا لَهُ[n[ۥ] كَ[n[ـٰ]تِب[p[ُو]نَ","Ким мўмин ҳолида солиҳ амаллардан қилса, саъйи-ҳаракати зое кетмас. Албатта, Биз уни ёзиб қўйгувчидирмиз.",330,17],["وَحَر[n[َٲ]مٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَ[n[ـٰ]ه[o[َآ] أَ[g[نّ]َهُمْ لَا يَرْجِع[p[ُو]نَ","Биз ҳалок қилган қишлоқ-шаҳарларнинг қайтмаслиги ҳаромдир.",330,17],["حَتَّ[o[ىٰٓ] إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَه[w:8717[ُم م]ِّ[f:843[ن ك]ُلِّ حَدَ[a:8856[بٍ ي]َ[f:8857[نس]ِل[p[ُو]نَ","Ниҳоят, Яъжуж ва Маъжуж очилиб, улар ҳар бир тепаликлардан оқиб келганларида.",330,17],["وَ[h:9999[ٱ][q:8858[قْ]تَرَبَ [h:8859[ٱ]لْوَعْدُ [h:8860[ٱ]لْحَقُّ فَإِذَا هِىَ شَ[n[ـٰ]خِصَةٌ أَ[q:8861[بْ]صَ[n[ـٰ]رُ [h:8862[ٱ]لَّذِينَ كَفَرُو[s[اْ] يَ[n[ـٰ]وَيْلَنَا قَ[q:298[دْ] كُ[g[نّ]َا فِى غَفْلَ[a:8863[ةٍ م]ِّنْ هَ[n[ـٰ]ذَا بَلْ كُ[g[نّ]َا ظَ[n[ـٰ]لِم[p[ِي]نَ","Ва ҳақ ваъда яқинлашгандаги ҳолни кўрсанг, куфр келтирганларнинг кўзлари чақчайиб: «Ҳолимизга вой! Бизлар бундан ғафлатда эдик. Йўқ! Бизлар зулм қилгувчилар эдик», дерлар.",330,17],["إِ[g[نّ]َكُمْ وَمَا تَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ حَصَبُ جَهَ[g[نّ]َمَ أَ[f:428[نت]ُمْ لَهَا و[n[َٲ]رِد[p[ُو]نَ","Албатта, сизлар ва Аллоҳдан ўзга ибодат қилган нарсаларингиз жаҳаннам ёқилғисидирсиз. Сизлар унга киргувчилардирсиз.",330,17],["لَوْ كَانَ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ ءَالِهَ[a:8864[ةً م]َّا وَرَدُوهَا‌ۖ وَكُ[f:8865[لٌّ ف]ِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Агар анавилар худолар бўлганида унга кирмас эдилар. Ҳаммалари унда абадий қолурлар.",330,17],["لَهُمْ فِيهَا زَفِي[a:8866[رٌ و]َهُمْ فِيهَا لَا يَسْمَع[p[ُو]نَ","У ерда уларга инграш бордир. Улар у ерда эшитмаслар.",330,17],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ سَبَقَتْ لَه[w:8867[ُم م]ِّ[g[نّ]َا [h:8868[ٱ]لْحُسْنَ[o[ىٰٓ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ عَنْهَا مُ[q:8869[بْ]عَد[p[ُو]نَ","Албатта, Биздан уларга яхшилик раво кўрилганлар, ана ўшалар, ундан узоқлаштирилгандирлар.",330,17],["لَا يَسْمَعُونَ حَسِيسَهَا‌ۖ وَهُمْ فِى مَا [h:8870[ٱ]شْتَهَتْ أَ[f:2341[نف]ُسُهُمْ خَ[n[ـٰ]لِد[p[ُو]نَ","Улар унинг чисирлашини эшитмаслар. Улар ўз нафслари иштаҳа қилган нарсалари ичида абадий қолгувчилардир.",331,17],["لَا يَحْزُنُهُمُ [h:8871[ٱ]لْفَزَعُ [h:8872[ٱ]لْأَكْبَرُ وَتَتَلَقَّ[n[ـٰ]هُمُ [h:8873[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ هَ[n[ـٰ]ذَا يَوْمُكُمُ [h:8874[ٱ]لَّذِى كُ[f:100[نت]ُمْ تُوعَد[p[ُو]نَ","Уларни буюк даҳшат ғами босмас. Уларни фаришталар: «Бу сизларга ваъда қилинган кунингиздир», деб кутиб оларлар.",331,17],["يَوْمَ نَ[q:8875[طْ]وِى [h:8876[ٱ][l[ل]سَّم[o[َا]ٓءَ كَطَىِّ [h:8877[ٱ][l[ل]سِّجِلِّ لِلْكُتُبِ‌ۚ كَمَا بَدَأْن[o[َآ] أَوَّلَ خَلْ[a:8878[قٍ ن]ُّعِيدُهُ[n[ۥ]‌ۚ وَعْدًا عَلَيْن[o[َآ‌ۚ] إِ[g[نّ]َا كُ[g[نّ]َا فَ[n[ـٰ]عِل[p[ِي]نَ","Ўша кунда осмонни худди мактуб ёзилган дафтарни ёпгандек ёпамиз. Аввал қандай яратган бўлсак, шундай ҳолга қайтарамиз. Бу зиммамиздаги ваъдадир. Албатта, Биз буни қилгувчимиз.",331,17],["وَلَقَ[q:341[دْ] كَتَ[q:2889[بْ]نَا فِى [h:8879[ٱ][l[ل]زَّبُورِ م[i:146[ِنۢ ب]َعْدِ [h:8880[ٱ][l[ل]ذِّكْرِ أَ[g[نّ]َ [h:8881[ٱ]لْأَرْضَ يَرِثُهَا عِبَادِىَ [h:8882[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ُو]نَ","Батаҳқиқ, Биз зикрдан сўнг Забурда ҳам: «Албатта, ерга солиҳ бандаларим меросхўр бўлурлар», деб ёзган эдик.",331,17],["إِ[g[نّ]َ فِى هَ[n[ـٰ]ذَا لَبَلَ[n[ـٰ][u:8883[غًا ل]ِّقَوْمٍ عَ[n[ـٰ]بِد[p[ِي]نَ","Албатта, буда ибодат қилгувчи қавм учун етарли ўгит бордир.",331,17],["وَم[o[َآ] أَرْسَلْنَ[n[ـٰ]كَ إِلَّا رَحْمَ[u:8884[ةً ل]ِّلْعَ[n[ـٰ]لَم[p[ِي]نَ","Биз сени фақат оламларга раҳмат қилиб юбордик.",331,17],["قُلْ إِ[g[نّ]َمَا يُوحَ[o[ىٰٓ] إِلَىَّ أَ[g[نّ]َم[o[َآ] إِلَ[n[ـٰ]هُكُمْ إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[f:8885[دٌ‌ۖ ف]َهَلْ أَ[f:428[نت][w:2056[ُم م]ُّسْلِم[p[ُو]نَ","Сен: «Менга фақат, албатта, сизнинг илоҳингиз битта илоҳдир, деб ваҳий этилади. Бас, сизлар мусулмон бўласизларми?!» деб айт.",331,17],["فَإِ[f:1857[ن ت]َوَلَّوْ[s[اْ] فَقُلْ ءَاذَ[f:8886[نت]ُكُمْ عَلَىٰ سَو[o[َا]ٓ[a:8887[ءٍ‌ۖ و]َإِنْ أَ[q:8888[دْ]ر[o[ِىٓ] أَقَرِيبٌ أ[c:8889[َم ب]َعِي[a:8890[دٌ م]َّا تُوعَد[p[ُو]نَ","Агар улар юз ўгириб кетсалар: «Мен сизларга баробарлик бўлиши учун эълон қилдим. Сизга ваъда қилинаётган нарса яқинми ёки узоқми билмасман.",331,17],["إِ[g[نّ]َهُ[n[ۥ] يَعْلَمُ [h:8891[ٱ]لْجَهْرَ مِنَ [h:3107[ٱ]لْقَوْلِ وَيَعْلَمُ مَا تَكْتُم[p[ُو]نَ","Албатта, У сўзнинг ошкорасини биладир ва нимани беркитаётган бўлсангиз ҳам биладир.",331,17],["وَإِنْ أَ[q:8888[دْ]رِى لَعَلَّهُ[n[ۥ] فِتْنَ[u:8892[ةٌ ل]َّكُمْ وَمَتَ[n[ـٰ]عٌ إِلَىٰ ح[p[ِي]نٍ","Билмайман, эҳтимол, бу сизлар учун синовдир ёки вақтинчалик ҳаловатдир», деб айт.",331,17],["قَ[n[ـٰ]لَ رَبِّ [h:8893[ٱ]حْك[c:8894[ُم ب]ِ[h:370[ٱ]لْحَقِّ‌ۗ وَرَبُّنَا [h:8895[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ [h:8896[ٱ]لْمُسْتَعَانُ عَلَىٰ مَا تَصِف[p[ُو]نَ","У: «Эй Роббим, Ўзинг ҳақ ила ҳукм қил. Роббимиз Роҳмандир ва сизлар қилган васфлардан мадад сўраладиган зотдир», деди.",331,17]]},{"n":22,"ar":"الحَجِّ","en":"Al-Hajj","uz":"Ҳаж","type":"Мадина","ayahs":[["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ [h:2529[ٱ]تَّقُو[s[اْ] رَبَّكُمْ‌ۚ إِ[g[نّ]َ زَلْزَلَةَ [h:8897[ٱ][l[ل]سَّاعَةِ شَىْءٌ عَظ[p[ِي]مٌ","Эй одамлар! Роббингиздан қўрқинг! Албатта, соати зилзиласи улкан нарсадир.",332,17],["يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَ[g[مّ][o[َآ] أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى [h:8898[ٱ][l[ل][g[نّ]َاسَ سُكَ[n[ـٰ]رَىٰ وَمَا ه[c:8899[ُم ب]ِسُكَ[n[ـٰ]رَىٰ وَلَ[n[ـٰ]كِ[g[نّ]َ عَذَابَ [h:8900[ٱ]للَّهِ شَد[p[ِي][q[د]ٌ","Уни кўрадиган кунингизда, ҳар бир эмизувчи ўзи эмизаётган нарсасини унутар. Ҳар бир ҳомиладор ҳомиласини ташлар. Одамларни маст ҳолда кўрарсан. Ҳолбуки, улар маст эмас. Лекин Аллоҳнинг азоби шиддатлидир.",332,17],["وَمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ م[a:8901[َن ي]ُجَ[n[ـٰ]دِلُ فِى [h:714[ٱ]للَّهِ بِغَيْرِ عِلْ[a:8902[مٍ و]َيَتَّبِعُ كُلَّ شَيْطَ[n[ـٰ][a:8903[نٍ م]َّر[p[ِي][q[د]ٍ","Одамлардан Аллоҳ ҳақида билмасдан тортишганлари ва бебош шайтонга эргашганлари ҳам бор.",332,17],["كُتِبَ عَلَيْهِ أَ[g[نّ]َهُ[n[ۥ] مَ[f:8904[ن ت]َوَلَّاهُ فَأَ[g[نّ]َهُ[n[ۥ] يُضِلُّهُ[n[ۥ] وَيَهْدِيهِ إِلَىٰ عَذَابِ [h:8905[ٱ][l[ل]سَّع[p[ِي]رِ","Унга битилганки, албатта, унга ким дўст бўлса, шубҳасиз, уни адаштиради ва дўзах азобига «ҳидоят» қилади.",332,17],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ فِى رَيْ[a:8906[بٍ م]ِّنَ [h:8907[ٱ]لْبَعْثِ فَإِ[g[نّ]َا خَلَ[q:4250[قْ]نَ[n[ـٰ]ك[w:8908[ُم م]ِّ[f:1972[ن ت]ُرَا[f:1973[بٍ ث]ُ[g[مّ]َ م[a:7325[ِن ن]ُّ[q:7326[طْ]فَ[f:8077[ةٍ ث]ُ[g[مّ]َ مِنْ عَلَقَ[f:8909[ةٍ ث]ُ[g[مّ]َ م[a:8910[ِن م]ُّضْغَ[a:8911[ةٍ م]ُّخَلَّقَ[a:8912[ةٍ و]َغَيْرِ مُخَلَّقَ[u:8913[ةٍ ل]ِّنُبَيِّنَ لَكُمْ‌ۚ وَنُقِرُّ فِى [h:1733[ٱ]لْأَرْحَامِ مَا نَش[o[َا]ٓءُ إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَم[f:4121[ًّى ث]ُ[g[مّ]َ نُخْرِجُكُمْ طِفْل[f:8914[اً ث]ُ[g[مّ]َ لِتَ[q:8915[بْ]لُغ[o[ُوٓ][s[اْ] أَشُدَّكُمْ‌ۖ وَمِ[f:2325[نك][w:2326[ُم م]ّ[a:8916[َن ي]ُتَوَفَّىٰ وَمِ[f:2325[نك][w:2326[ُم م]ّ[a:7485[َن ي]ُرَدُّ إِلَ[o[ىٰٓ] أَرْذَلِ [h:7486[ٱ]لْعُمُرِ لِكَيْلَا يَعْلَمَ م[i:146[ِنۢ ب]َعْدِ عِلْ[f:7487[مٍ ش]َيْـ[a:8917[ـًٔا‌ۚ و]َتَرَى [h:8108[ٱ]لْأَرْضَ هَامِدَ[f:8918[ةً ف]َإِذ[o[َآ] أَ[f:515[نز]َلْنَا عَلَيْهَا [h:8919[ٱ]لْم[o[َا]ٓءَ [h:8920[ٱ]هْتَزَّتْ وَرَبَتْ وَأَ[i:8921[نۢب]َتَتْ مِ[f:843[ن ك]ُلِّ زَوْ[i:8922[جِۭ ب]َه[p[ِي][q[ج]ٍ","Эй одамлар! Агар қайта тирилиш ҳақида шубҳа қиладиган бўлсангиз, бас, Биз сизга баён қилишимиз учун сизларни тупроқдан, сўнгра нутфадан, сўнгра алақадан, сўнгра битган-битмаган бир чайнам гўштдан яратдик. Ва бачадонларда хоҳлаган нарсамизни маълум муддатгача қарор топдирамиз. Кейин сизларни бувак ҳолингизда чиқарамиз. Сўнгра вояга етишингиз учун. Сиздан вафот қилиб кетадиганлар ҳам, билганидан кейин ҳеч нарсани билмай қоладиган даражада тубан умрга етадиганлар ҳам бор. Ва ерни қақраган ҳолда кўрасан. Қачонки, Биз унга сув туширсак, у сесканар ва кўпчир. Ҳамда ҳар хил гўзал жуфтларни ўстирадир.",332,17],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َ [h:897[ٱ]للَّهَ هُوَ [h:8923[ٱ]لْحَقُّ وَأَ[g[نّ]َهُ[n[ۥ] يُحْىِ [h:8924[ٱ]لْمَوْتَىٰ وَأَ[g[نّ]َهُ[n[ۥ] عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Булар кўрсатурки, албатта, Аллоҳ ҳақ зотдир ва, албатта, У ўликларни тирилтирур ҳамда У ҳар бир нарсага қодирдир.",333,17],["وَأَ[g[نّ]َ [h:8014[ٱ][l[ل]سَّاعَةَ ءَاتِيَ[u:8925[ةٌ ل]َّا رَيْبَ فِيهَا وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ يَ[q:7405[بْ]عَثُ مَ[f:2074[ن ف]ِى [h:8926[ٱ]لْقُب[p[ُو]رِ","Ва, албатта, соати келгувчидир, бунга шубҳа йўқ. Ва, албатта, Аллоҳ қабрлардаги кимсаларни тирилтирур.",333,17],["وَمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ م[a:8901[َن ي]ُجَ[n[ـٰ]دِلُ فِى [h:714[ٱ]للَّهِ بِغَيْرِ عِلْ[a:7953[مٍ و]َلَا هُ[a:8927[دًى و]َلَا كِتَ[n[ـٰ][a:8928[بٍ م]ُّن[p[ِي]رٍ","Одамлардан Аллоҳ ҳақида билмасдан, ҳидоятга ёки нурли китобга эга бўлмасдан туриб тортишадиганлари бор.",333,17],["ثَانِىَ عِ[q:8929[طْ]فِه[n[ِۦ] لِيُضِلَّ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ‌ۖ لَهُ[n[ۥ] فِى [h:599[ٱ][l[ل]دُّنْيَا خِزْ[a:8930[ىٌ‌ۖ و]َنُذِيقُهُ[n[ۥ] يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ عَذَابَ [h:2465[ٱ]لْحَر[p[ِي][q[ق]ِ","Аллоҳнинг йўлидан адаштириш учун, бўйнини булқаб. Унга дунёда расволик бор. Қиёмат куни унга куйдириш азобини тотдирамиз.",333,17],["ذ[n[َٲ]لِكَ بِمَا قَدَّمَتْ يَدَاكَ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ لَيْسَ بِظَلَّ[n[ـٰ][u:2466[مٍ ل]ِّلْعَب[p[ِي][q[د]ِ","Бундай бўлиши ўз қўлларинг тақдим қилган нарсалардандир. Албатта, Аллоҳ бандаларга зулм қилгувчи эмасдир.",333,17],["وَمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ م[a:8931[َن ي]َعْبُدُ [h:8932[ٱ]للَّهَ عَلَىٰ حَرْ[f:8933[فٍ‌ۖ ف]َإِنْ أَصَابَهُ[n[ۥ] خَيْرٌ [h:8934[ٱ][q:8935[طْ]مَأَ[g[نّ]َ بِه[n[ِۦ]‌ۖ وَإِنْ أَصَابَتْهُ فِتْنَةٌ [h:8936[ٱ][f:8937[نق]َلَبَ عَلَىٰ وَ[q:6818[جْ]هِه[n[ِۦ] خَسِرَ [h:8938[ٱ][l[ل]دُّنْيَا وَ[h:8939[ٱ]لْأَخِرَةَ‌ۚ ذ[n[َٲ]لِكَ هُوَ [h:8940[ٱ]لْخُسْرَانُ [h:8941[ٱ]لْمُب[p[ِي]نُ","Одамлардан Аллоҳга бир томонлама ибодат қиладиганлари ҳам бор. Агар унга яхшилик етса, кўнгли тўлур. Агар унга бало етса, юз ўгириб кетур. У дунёда ҳам, охиратда ҳам зиён кўрур. Ана ўша очиқ-ойдин зиёндир.",333,17],["يَ[q:1242[دْ]عُو[s[اْ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مَا لَا يَضُرُّهُ[n[ۥ] وَمَا لَا يَ[f:8942[نف]َعُهُ[n[ۥ]‌ۚ ذ[n[َٲ]لِكَ هُوَ [h:7084[ٱ][l[ل]ضَّلَ[n[ـٰ]لُ [h:7085[ٱ]لْبَع[p[ِي][q[د]ُ","У Аллоҳни қўйиб, ўзига зарар ҳам бермайдиган, манфаат ҳам бермайдиган нарсага илтижо қилур. Шунинг ўзи қаттиқ адашишдир.",333,17],["يَ[q:1242[دْ]عُو[s[اْ] لَمَ[f:8943[ن ض]َرُّهُ[o[ۥٓ] أَ[q:1355[قْ]رَبُ م[a:8944[ِن ن]َّفْعِه[n[ِۦ]‌ۚ لَبِئْسَ [h:8945[ٱ]لْمَوْلَىٰ وَلَبِئْسَ [h:8946[ٱ]لْعَش[p[ِي]رُ","У манфаатидан кўра зарари яқинроқ бўлганга илтижо қиладир. У қандай ҳам ёмон хожа ва қандай ҳам ёмон дўстдир!",333,17],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُ[q:8947[دْ]خِلُ [h:8948[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَفْعَلُ مَا يُر[p[ِي][q[د]ُ","Албатта, иймон келтириб, яхши амалларни қилганларни Аллоҳ остиларидан анҳорлар оқиб турган жаннатларга киритадир. Албатта, Аллоҳ ирода этган нарсани қиладир.",333,17],["مَ[f:506[ن ك]َانَ يَظُ[g[نّ]ُ أ[u:8842[َن ل]ّ[a:8949[َن ي]َ[f:8950[نص]ُرَهُ [h:8951[ٱ]للَّهُ فِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ فَلْيَمْدُ[q:8398[دْ] بِسَبَبٍ إِلَى [h:157[ٱ][l[ل]سَّم[o[َا]ٓءِ ثُ[g[مّ]َ لْيَ[q:8952[قْ]طَعْ فَلْيَ[f:8007[نظ]ُرْ هَلْ يُذْهِبَ[g[نّ]َ كَيْدُهُ[n[ۥ] مَا يَغ[p[ِي]ظُ","Кимки унга бу дунёю охиратда Аллоҳ нусрат беришига шубҳа қилса, бир восита топиб, осмонга осилсин, сўнгра уни кессин. Бас, назар солсин-чи, унинг бу ҳийласи ғам-ғуссани кеткизармикан?!",333,17],["وَكَذ[n[َٲ]لِكَ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ ءَايَ[n[ـٰ][i:516[تِۭ ب]َيِّنَ[n[ـٰ][a:8953[تٍ و]َأَ[g[نّ]َ [h:859[ٱ]للَّهَ يَهْدِى م[a:2323[َن ي]ُر[p[ِي][q[د]ُ","Мана шундай қилиб, Биз уни очиқ-ойдин оятлар ҳолида нозил қилдик. Албатта, Аллоҳ хоҳлаган кишиларни ҳидоят қиладир.",334,17],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَ[h:37[ٱ]لَّذِينَ هَادُو[s[اْ] وَ[h:327[ٱ][l[ل]صَّ[n[ـٰ]بِــِٔينَ وَ[h:326[ٱ][l[ل][g[نّ]َصَ[n[ـٰ]رَىٰ وَ[h:8954[ٱ]لْمَجُوسَ وَ[h:37[ٱ]لَّذِينَ أَشْرَك[o[ُوٓ][s[اْ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:3903[َىْءٍ ش]َه[p[ِي][q[د]ٌ","Албатта, Аллоҳ қиёмат куни иймон келтирганлар, яҳудий бўлганлар, собиийлар, насоролар, мажусийлар ва ширк келтирганлар орасида Ўзи ажрим қилур. Албатта, Аллоҳ ҳар бир нарсага шоҳиддир.",334,17],["أَلَمْ تَرَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَسْجُدُ لَهُ[n[ۥ] مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَ[f:3453[ن ف]ِى [h:44[ٱ]لْأَرْضِ وَ[h:8955[ٱ][l[ل]شَّمْسُ وَ[h:8956[ٱ]لْقَمَرُ وَ[h:7346[ٱ][l[ل][g[نّ]ُجُومُ وَ[h:8957[ٱ]لْجِبَالُ وَ[h:8958[ٱ][l[ل]شَّجَرُ وَ[h:8959[ٱ][l[ل]دَّو[m[َا]ٓبُّ وَكَثِي[a:8960[رٌ م]ِّنَ [h:721[ٱ][l[ل][g[نّ]َاسِ‌ۖ وَكَثِيرٌ حَقَّ عَلَيْهِ [h:8961[ٱ]لْعَذَابُ‌ۗ وَم[a:8962[َن ي]ُهِنِ [h:8963[ٱ]للَّهُ فَمَا لَهُ[n[ۥ] م[a:8964[ِن م]ُّكْرِمٍ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَفْعَلُ مَا يَش[o[َا]ٓءُ ۩","Осмонлардаги кимсалар, ердаги кимсалар, қуёш, ой, юлдузлар, тоғлар, дарахтлар, жониворлар ва одамлардан кўплари, албатта, Аллоҳга сажда қилишини кўрмайсанми? Кўпларига эса, азоб ҳақ бўлди. Кимни Аллоҳ хор қилса, уни икром қилгувчи бўлмас. Албатта, Аллоҳ хоҳлаган нарсасини қилади.",334,17],["۞ هَ[n[ـٰ]ذَانِ خَصْمَانِ [h:8965[ٱ]خْتَصَمُو[s[اْ] فِى رَبِّهِمْ‌ۖ فَ[h:2514[ٱ]لَّذِينَ كَفَرُو[s[اْ] قُطِّعَتْ لَهُمْ ثِيَا[a:8966[بٌ م]ّ[a:4598[ِن ن]َّا[a:8967[رٍ ي]ُصَبُّ مِ[f:7114[ن ف]َوْقِ رُءُوسِهِمُ [h:8968[ٱ]لْحَم[p[ِي]مُ","Мана бу икки ғаним Роббилари ҳақида талашган эдилар. Бас, куфр келтирганларга оловдан кийим бичилди. Бошлари устидан ўта қайноқ сув қуйиладир.",334,17],["يُصْهَرُ بِه[n[ِۦ] مَا فِى بُطُونِهِمْ وَ[h:8969[ٱ]لْجُل[p[ُو][q[د]ُ","У билан қоринларидаги нарсалар ва терилари эритилади.",334,17],["وَلَه[w:8970[ُم م]َّقَ[n[ـٰ]مِعُ مِنْ حَد[p[ِي][q[د]ٍ","Улар учун темир гурзилар бор.",334,17],["كُلَّم[o[َآ] أَرَاد[o[ُوٓ][s[اْ] أ[a:3533[َن ي]َخْرُجُو[s[اْ] مِنْهَا مِنْ غَ[g[مّ]ٍ أُعِيدُو[s[اْ] فِيهَا وَذُوقُو[s[اْ] عَذَابَ [h:2465[ٱ]لْحَر[p[ِي][q[ق]ِ","Улар ҳар қачон ундаги ғамдан чиқмоқчи бўлсалар, унга қайтариладилар ва «Ёниш азобини тотинг!» дейиладир.",334,17],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُ[q:8947[دْ]خِلُ [h:8948[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِ[f:8050[ن ذ]َهَ[a:8971[بٍ و]َلُؤْلُ[a:8972[ؤًا‌ۖ و]َلِبَاسُهُمْ فِيهَا حَر[p[ِي]رٌ","Албатта, Аллоҳ иймон келтириб, яхши амалларни қилганларни остидан анҳорлар оқиб турган жаннатларга киритур. Улар у ерда олтин билакузуклар ва инжулар ила безанурлар. У ердаги либослари эса, ипакдандир.",334,17],["وَهُد[o[ُوٓ][s[اْ] إِلَى [h:8973[ٱ][l[ل]طَّيِّبِ مِنَ [h:3107[ٱ]لْقَوْلِ وَهُد[o[ُوٓ][s[اْ] إِلَىٰ صِر[n[َٲ]طِ [h:8974[ٱ]لْحَم[p[ِي][q[د]ِ","Улар ширин сўзга ҳидоят қилинурлар ва мақталган Зотнинг йўлига ҳидоят қилинурлар.",335,17],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَيَصُدُّونَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ وَ[h:1205[ٱ]لْمَسْجِدِ [h:1206[ٱ]لْحَرَامِ [h:8975[ٱ]لَّذِى جَعَلْنَ[n[ـٰ]هُ لِل[g[نّ]َاسِ سَو[o[َا]ٓءً [h:8976[ٱ]لْعَ[n[ـٰ]كِفُ فِيهِ وَ[h:8977[ٱ]لْبَادِ‌ۚ وَم[a:2292[َن ي]ُرِ[q:2293[دْ] فِيهِ بِإِلْحَا[i:8978[دِۭ ب]ِظُلْ[a:8979[مٍ ن]ُّذِ[q:8980[قْ]هُ مِنْ عَذَابٍ أَل[p[ِي]مٍ","Куфр келтирганлар ва Аллоҳнинг йўлидан ҳамда ерли ва четдан келган одамлар учун баробар қилиб қўйганимиз Масжидул Ҳаромдан тўсганларга ва у ерда ким зулм ила янглиш йўлга бурилишни ирода қилса, унга аламли азобни тоттирамиз.",335,17],["وَإِذْ بَوَّأْنَا لِإِ[q:8981[بْ]ر[n[َٲ]هِيمَ مَكَانَ [h:8982[ٱ]لْبَيْتِ أ[u:4908[َن ل]َّا تُشْرِكْ بِى شَيْـ[a:8983[ـًٔا و]َطَهِّرْ بَيْتِىَ لِلطّ[o[َا]ٓئِفِينَ وَ[h:8984[ٱ]لْق[o[َا]ٓئِمِينَ وَ[h:654[ٱ][l[ل]رُّكَّعِ [h:655[ٱ][l[ل]سُّج[p[ُو][q[د]ِ","Биз Иброҳимга Байтнинг жойини белгилаб бериб: «Менга ҳеч нарсани шерик қилма, Байтимни тавоф қилгувчилар, қоим тургувчилар ҳамда рукуъ, сужуд қилгувчилар учун поклагин.",335,17],["وَأَذِّ[f:8985[ن ف]ِى [h:4380[ٱ][l[ل][g[نّ]َاسِ بِ[h:8986[ٱ]لْحَجِّ يَأْتُوكَ رِجَال[a:8987[اً و]َعَلَىٰ كُلِّ ضَامِ[a:8988[رٍ ي]َأْتِينَ مِ[f:843[ن ك]ُلِّ فَجٍّ عَم[p[ِي][q[ق]ٍ","Одамларни ҳажга чақир, улар сен томон пиёда, узоқ-узоқ йўллардан юриб, озиган уловлар устида келсинлар.",335,17],["لِّيَشْهَدُو[s[اْ] مَنَ[n[ـٰ]فِعَ لَهُمْ وَيَذْكُرُو[s[اْ] [h:8989[ٱ]سْمَ [h:3393[ٱ]للَّهِ ف[o[ِىٓ] أَيَّا[a:8990[مٍ م]َّعْلُومَ[n[ـٰ]تٍ عَلَىٰ مَا رَزَقَه[w:8991[ُم م]ّ[i:8992[ِنۢ ب]َهِيمَةِ [h:8993[ٱ]لْأَنْعَ[n[ـٰ]مِ‌ۖ فَكُلُو[s[اْ] مِنْهَا وَأَ[q:8994[طْ]عِمُو[s[اْ] [h:8995[ٱ]لْب[o[َا]ٓئِسَ [h:8996[ٱ]لْفَق[p[ِي]رَ","Ва ўзларига бўладиган манфаатларга шоҳид бўлсинлар. Маълум кунларда уларга ризқ қилиб берган чорва ҳайвонларини Аллоҳнинг исмини зикр қилсинлар. Бас, улардан енглар ва бечора ва фақирларга ҳам егизинглар.",335,17],["ثُ[g[مّ]َ لْيَ[q:8997[قْ]ضُو[s[اْ] تَفَثَهُمْ وَلْيُوفُو[s[اْ] نُذُورَهُمْ وَلْيَطَّوَّفُو[s[اْ] بِ[h:8998[ٱ]لْبَيْتِ [h:8999[ٱ]لْعَت[p[ِي][q[ق]ِ","Сўнгра ўзларидаги кирларни кетказсинлар, назрларига вафо қилсинлар ва «қадимги уй»ни тавоф қилсинлар», деганимизни эсла.",335,17],["ذ[n[َٲ]لِكَ وَم[a:9000[َن ي]ُعَظِّمْ حُرُمَ[n[ـٰ]تِ [h:9001[ٱ]للَّهِ فَهُوَ خَيْ[u:964[رٌ ل]َّهُ[n[ۥ] عِ[f:264[ند]َ رَبِّه[n[ِۦ]‌ۗ وَأُحِلَّتْ لَكُمُ [h:9002[ٱ]لْأَنْعَ[n[ـٰ]مُ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ‌ۖ فَ[h:9003[ٱ][q:9003[جْ]تَنِبُو[s[اْ] [h:9004[ٱ][l[ل]رِّ[q:4401[جْ]سَ مِنَ [h:9005[ٱ]لْأَوْثَ[n[ـٰ]نِ وَ[h:7400[ٱ][q:7400[جْ]تَنِبُو[s[اْ] قَوْلَ [h:9006[ٱ][l[ل]زّ[p[ُو]رِ","Ана шундай. Ким Аллоҳ ҳаром қилган нарсаларга риоя қилса, бас, бу Робби ҳузурида унинг ўзи учун яхшидир. Ва сизларга тиловат қилинадиганлардан бошқа чорва ҳайвонлари ҳалол қилинди. Бас, бутлардан иборат нажосатдан йироқ бўлинг ва ёлғон сўздан йироқ бўлинг.",335,17],["حُنَف[o[َا]ٓءَ لِلَّهِ غَيْرَ مُشْرِكِينَ بِه[n[ِۦ]‌ۚ وَم[a:2834[َن ي]ُشْرِكْ بِ[h:32[ٱ]للَّهِ فَكَأَ[g[نّ]َمَا خَرَّ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ فَتَخْطَفُهُ [h:9007[ٱ][l[ل]طَّيْرُ أَوْ تَهْوِى بِهِ [h:7082[ٱ][l[ل]رِّيحُ فِى مَكَا[f:9008[نٍ س]َح[p[ِي][q[ق]ٍ","Аллоҳга бўлган иймондан оғманг, Унга ширк келтиргувчи бўлманг. Ким Аллоҳга ширк келтирса, бас, у гўёки осмондан қулаб тушгану уни йиртқич қуш олиб қочган ёки уни шамол узоқ ерга учириб кетган кабидир.",336,17],["ذ[n[َٲ]لِكَ وَم[a:9000[َن ي]ُعَظِّمْ شَعَ[o[ـٰٓ]ئِرَ [h:3349[ٱ]للَّهِ فَإِ[g[نّ]َهَا مِ[f:9009[ن ت]َ[q:5843[قْ]وَى [h:9010[ٱ]لْقُل[p[ُو][q[ب]ِ","Иш бундоқ. Ким Аллоҳнинг нишонларини улуғласа, бас, албатта, бу қалбларнинг тақвосидандир.",336,17],["لَكُمْ فِيهَا مَنَ[n[ـٰ]فِعُ إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَم[f:4121[ًّى ث]ُ[g[مّ]َ مَحِلُّه[o[َآ] إِلَى [h:9011[ٱ]لْبَيْتِ [h:9012[ٱ]لْعَت[p[ِي][q[ق]ِ","Сизга уларда маълум вақтгача манфаатлар бордир. Сўнгра уларни ҳалол макони «қадимги уй» дадир.",336,17],["وَلِكُلِّ أُ[g[مّ]َ[f:9013[ةٍ ج]َعَلْنَا مَ[f:9014[نس]َ[u:9015[كًا ل]ِّيَذْكُرُو[s[اْ] [h:9016[ٱ]سْمَ [h:3393[ٱ]للَّهِ عَلَىٰ مَا رَزَقَه[w:8991[ُم م]ّ[i:8992[ِنۢ ب]َهِيمَةِ [h:8993[ٱ]لْأَنْعَ[n[ـٰ]مِ‌ۗ فَإِلَ[n[ـٰ]هُكُمْ إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[f:9017[دٌ ف]َلَهُ[o[ۥٓ] أَسْلِمُو[s[اْ‌ۗ] وَبَشِّرِ [h:9018[ٱ]لْمُخْبِت[p[ِي]نَ","Ҳар бир умматга уларга чорва ҳайвонларини ризқ қилиб берганига Аллоҳнинг исмини эслашлари учун қурбонлик қилишни жорий этганмиз. Бас, илоҳларингиз бир илоҳдир. Бас, Унгагина мусулмон бўлинг. Итоатли, мутавозеъларга башорат бер.",336,17],["ٱلَّذِينَ إِذَا ذُكِرَ [h:5234[ٱ]للَّهُ وَجِلَتْ قُلُوبُهُمْ وَ[h:918[ٱ][l[ل]صَّ[n[ـٰ]بِرِينَ عَلَىٰ م[o[َآ] أَصَابَهُمْ وَ[h:9019[ٱ]لْمُقِيمِى [h:9020[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ وَمِ[g[مّ]َا رَزَ[q:15[قْ]نَ[n[ـٰ]هُمْ يُ[f:16[نف]ِق[p[ُو]نَ","Улар Аллоҳ зикр қилинган вақтда қалблари титрайдиган ва ўзларига етган мусибатга сабр қилгувчилар ҳамда намозни тўкис адо этгувчилардир, уларга ризқ қилиб берган нарсамиздан инфоқ қиларлар.",336,17],["وَ[h:9999[ٱ]لْبُ[q:9021[دْ]نَ جَعَلْنَ[n[ـٰ]هَا لَك[w:556[ُم م]ِّ[f:809[ن ش]َعَ[o[ـٰٓ]ئِرِ [h:810[ٱ]للَّهِ لَكُمْ فِيهَا خَيْ[f:9022[رٌ‌ۖ ف]َ[h:1091[ٱ]ذْكُرُو[s[اْ] [h:9023[ٱ]سْمَ [h:3393[ٱ]للَّهِ عَلَيْهَا صَو[m[َا]ٓفَّ‌ۖ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُو[s[اْ] مِنْهَا وَأَ[q:8994[طْ]عِمُو[s[اْ] [h:9024[ٱ]لْقَانِعَ وَ[h:9025[ٱ]لْمُعْتَرَّ‌ۚ كَذ[n[َٲ]لِكَ سَخَّرْنَ[n[ـٰ]هَا لَكُمْ لَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Ва туяларни сиз учун Аллоҳнинг нишонларидан қилдик. Уларда сизга яхшилик бор. Уларга олд оёқларидан бири боғлиқ турган ҳолида Аллоҳнинг номини зикр қилинг. Ёнлари ерга текканида эса, бас, улардан енг ва қаноатли ва тиланган камбағалларни ҳам таомлантиринг. Шундай қилиб, Биз уларни сизга бўйинсундириб қўйдик. Шоядки шукр қилсангиз.",336,17],["ل[a:9026[َن ي]َنَالَ [h:9027[ٱ]للَّهَ لُحُومُهَا وَلَا دِم[o[َا]ٓؤُهَا وَلَ[n[ـٰ]ك[a:9028[ِن ي]َنَالُهُ [h:9029[ٱ][l[ل]تَّ[q:1084[قْ]وَىٰ مِ[f:344[نك]ُمْ‌ۚ كَذ[n[َٲ]لِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُو[s[اْ] [h:9030[ٱ]للَّهَ عَلَىٰ مَا هَدَ[n[ٮٰ]كُمْ‌ۗ وَبَشِّرِ [h:9031[ٱ]لْمُحْسِن[p[ِي]نَ","Уларнинг гўштлари ҳам, қонлари ҳам зинҳор Аллоҳга етмайдир. Лекин Унга сиздан тақво етадир. Шундай қилиб, сизни ҳидоят қилгани эвазига Аллоҳга такбир айтишингиз учун уларни сизга бўйинсундириб қўйди. Яхшилик қилгувчиларга башорат бер.",336,17],["۞ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُد[n[َٲ]فِعُ عَنِ [h:3106[ٱ]لَّذِينَ ءَامَن[o[ُوٓ[s[اْ]‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُحِبُّ كُلَّ خَوَّا[f:9032[نٍ ك]َف[p[ُو]رٍ","Албатта, Аллоҳ иймон келтирганларни мудофаа қиладир. Албатта, Аллоҳ барча хоин ва кофирларни хуш кўрмас.",336,17],["أُذِنَ لِلَّذِينَ يُقَ[n[ـٰ]تَلُونَ بِأَ[g[نّ]َهُمْ ظُلِمُو[s[اْ‌ۚ] وَإِ[g[نّ]َ [h:1986[ٱ]للَّهَ عَلَىٰ نَصْرِهِمْ لَقَد[p[ِي]رٌ","Ўзларига қарши уруш очганларга уларга зулм қилингани учун изн берилди. Албатта, Аллоҳ уларга нусрат беришга қодирдир.",337,17],["ٱلَّذِينَ أُخْرِجُو[s[اْ] مِ[f:432[ن د]ِيَ[n[ـٰ]رِه[c:9033[ِم ب]ِغَيْرِ حَقٍّ إِلّ[o[َآ] أ[a:6263[َن ي]َقُولُو[s[اْ] رَبُّنَا [h:9034[ٱ]للَّهُ‌ۗ وَلَوْلَا دَفْعُ [h:1436[ٱ]للَّهِ [h:1437[ٱ][l[ل][g[نّ]َاسَ بَعْضَه[c:1438[ُم ب]ِبَعْ[u:9035[ضٍ ل]َّهُدِّمَتْ صَو[n[َٲ]مِعُ وَبِيَ[a:9036[عٌ و]َصَلَو[n[َٲ][a:9037[تٌ و]َمَسَ[n[ـٰ]جِدُ يُذْكَرُ فِيهَا [h:9038[ٱ]سْمُ [h:4364[ٱ]للَّهِ كَثِي[a:9039[رًا‌ۗ و]َلَيَ[f:9040[نص]ُرَ[g[نّ]َ [h:9041[ٱ]للَّهُ م[a:9042[َن ي]َ[f:9043[نص]ُرُهُ[o[ۥٓ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَقَوِىٌّ عَز[p[ِي]زٌ","Улар ноҳақдан, фақатгина «Роббимиз Аллоҳ» деганлари учун ўз диёрларидан чиқарилгандирлар. Агар Аллоҳ одамларнинг баъзиларини баъзилари билан даф қилиб турмаса, узлатгоҳлар, канисалар, ҳавралар ва Аллоҳнинг номи кўплаб зикр қилинадиган масжидлар вайрон қилинган бўлур эди. Албатта, Аллоҳ Ўзига ёрдам берганларга ёрдам берур. Албатта, Аллоҳ кучли ва ғолибдир.",337,17],["ٱلَّذِينَ إ[a:9044[ِن م]َّكَّ[g[نّ]َ[n[ـٰ]هُمْ فِى [h:44[ٱ]لْأَرْضِ أَقَامُو[s[اْ] [h:9045[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتَوُ[s[اْ] [h:1642[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَأَمَرُو[s[اْ] بِ[h:934[ٱ]لْمَعْرُوفِ وَنَهَوْ[s[اْ] عَنِ [h:2144[ٱ]لْمُ[f:2145[نك]َرِ‌ۗ وَلِلَّهِ عَ[n[ـٰ]قِبَةُ [h:9046[ٱ]لْأُم[p[ُو]رِ","Уларга ер юзида имкон берсак, намозни тўкис адо этарлар, закотни берарлар, яхшиликка буюриб, ёмонликдан қайтарарлар. Ишларнинг оқибати Аллоҳга оиддир.",337,17],["وَإ[a:9047[ِن ي]ُكَذِّبُوكَ فَقَ[q:563[دْ] كَذَّبَتْ قَ[q:8394[بْ]لَهُمْ قَوْمُ نُو[a:9048[حٍ و]َعَا[a:9049[دٌ و]َثَم[p[ُو][q[د]ُ","Агар сени ёлғончи қилаётган бўлсалар, бас, булардан олдин Нуҳ қавми, Од ва Самуд ҳам ёлғончи қилган эдилар.",337,17],["وَقَوْمُ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَقَوْمُ ل[p[ُو][q[ط]ٍ","Иброҳим қавми, Лут қавми.",337,17],["وَأَصْحَ[n[ـٰ]بُ مَ[q:4842[دْ]يَنَ‌ۖ وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَ[n[ـٰ]فِرِينَ ثُ[g[مّ]َ أَخَذْتُهُمْ‌ۖ فَكَيْفَ كَانَ نَك[p[ِي]رِ","Мадян эгалари ҳам. Ва Мусо ҳам ёлғончи қилинди. Мен кофирларга бир оз муҳлат бердим, сўнгра уларни тутдим. Бас, Менинг инкорим қандоқ бўлди?!",337,17],["فَكَأَيّ[a:9050[ِن م]ِّ[f:4585[ن ق]َرْيَةٍ أَهْلَكْنَ[n[ـٰ]هَا وَهِىَ ظَالِمَ[f:9051[ةٌ ف]َهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْ[a:9052[رٍ م]ُّعَطَّلَ[a:9053[ةٍ و]َقَصْ[a:9054[رٍ م]َّش[p[ِي][q[د]ٍ","Қанчадан-қанча шаҳар-қишлоқларни зулм қилгувчи бўлган ҳолида ҳалок этдик. Бас, улар шифтлари қулаган, ташландиқ қудуқ, юксак қаср.",337,17],["أَفَلَمْ يَسِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَتَكُونَ لَهُمْ قُلُو[a:9055[بٌ ي]َعْقِلُونَ بِه[o[َآ] أَوْ ءَاذَا[a:5198[نٌ ي]َسْمَعُونَ بِهَا‌ۖ فَإِ[g[نّ]َهَا لَا تَعْمَى [h:9056[ٱ]لْأَ[q:4305[بْ]صَ[n[ـٰ]رُ وَلَ[n[ـٰ]كِ[f:9057[ن ت]َعْمَى [h:9058[ٱ]لْقُلُوبُ [h:9059[ٱ]لَّتِى فِى [h:6095[ٱ][l[ل]صُّد[p[ُو]رِ","Ахир, ер юзида айланиб юрмайдимиларки, уларга ақл этадиган қалблар, эшитадиган қулоқлар бўлсин. Зеро, кўзлар кўр бўлмас, кўксилардаги қалблар кўр бўлур.",337,17],["وَيَسْتَعْجِلُونَكَ بِ[h:9060[ٱ]لْعَذَابِ وَل[a:9061[َن ي]ُخْلِفَ [h:411[ٱ]للَّهُ وَعْدَهُ[n[ۥ]‌ۚ وَإِ[g[نّ]َ يَوْمًا عِ[f:264[ند]َ رَبِّكَ كَأَلْفِ سَنَ[a:9062[ةٍ م]ِّ[g[مّ]َا تَعُدّ[p[ُو]نَ","Улар сендан азобнинг тезроқ келишини сўрарлар. Ҳолбуки, Аллоҳ ваъдасига хилоф қилмас. Дарҳақиқат, Роббинг ҳузуридаги бир кун, сиз санайдиган минг йилдекдир.",338,17],["وَكَأَيّ[a:2298[ِن م]ِّ[f:4585[ن ق]َرْيَةٍ أَمْلَيْتُ لَهَا وَهِىَ ظَالِمَ[f:9063[ةٌ ث]ُ[g[مّ]َ أَخَذْتُهَا وَإِلَىَّ [h:9064[ٱ]لْمَص[p[ِي]رُ","Қанчадан-қанча шаҳар-қишлоқларга зулм қилгувчи бўлган ҳолида ҳам муҳлат бердим. Сўнгра уларни тутдим. Қайтиш фақат менгагинадир.",338,17],["قُلْ يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ إِ[g[نّ]َم[o[َآ] أَنَا۟ لَكُمْ نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","Сен: «Эй одамлар! Мен сизлар учун фақат бир очиқ огоҳлантиргувчиман, холос», деб айт.",338,17],["فَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَه[w:3412[ُم م]َّغْفِرَ[a:5445[ةٌ و]َرِزْ[f:5239[قٌ ك]َر[p[ِي]مٌ","Иймон келтириб, яхши амалларни қилганларга мағфират ва икромли ризқ бордир.",338,17],["وَ[h:9999[ٱ]لَّذِينَ سَعَوْ[s[اْ] ف[o[ِىٓ] ءَايَ[n[ـٰ]تِنَا مُعَ[n[ـٰ]جِزِينَ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:3415[ٱ]لْجَح[p[ِي]مِ","Бизнинг оятларимизни ожиз қолдирмоқчи бўлиб, саъйи-ҳаракат қилганлар, ана ўшалар жаҳийм эгаларидир.",338,17],["وَم[o[َآ] أَرْسَلْنَا مِ[f:18[ن ق]َ[q:19[بْ]لِكَ م[u:2882[ِن ر]َّسُو[a:9065[لٍ و]َلَا نَبِىٍّ إِلّ[o[َآ] إِذَا تَمَ[g[نّ]َ[o[ىٰٓ] أَلْقَى [h:9066[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ ف[o[ِىٓ] أُمْنِيَّتِه[n[ِۦ] فَيَ[f:9067[نس]َخُ [h:9068[ٱ]للَّهُ مَا يُلْقِى [h:9069[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ ثُ[g[مّ]َ يُحْكِمُ [h:9070[ٱ]للَّهُ ءَايَ[n[ـٰ]تِه[n[ِۦ]‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Биз сендан илгари ҳеч бир Расул ва Набий юбормадикки, у бир нарсани таманний қилганида, шайтон унинг таманнийсига ташламаган бўлса. Бас, Аллоҳ шайтон ташлайдиган нарсани кетказур. Сўнгра Аллоҳ Ўз оятларини мустаҳкам қилур. Аллоҳ ўта билгувчи ва ҳикматли зотдир.",338,17],["لِّيَ[q:2360[جْ]عَلَ مَا يُلْقِى [h:9069[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ فِتْنَ[u:9071[ةً ل]ِّلَّذِينَ فِى قُلُوبِه[w:39[ِم م]َّرَ[a:9072[ضٌ و]َ[h:9073[ٱ]لْقَاسِيَةِ قُلُوبُهُمْ‌ۗ وَإِ[g[نّ]َ [h:9074[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ لَفِى شِقَا[i:900[قِۭ ب]َع[p[ِي][q[د]ٍ","Шайтон ташлайдиган нарсанинг қалбларида касали борларга ва қалблари тошларга фитна бўлиши учундир. Албатта, золимлар узоқ тортишувдадирлар.",338,17],["وَلِيَعْلَمَ [h:2400[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:7379[ٱ]لْعِلْمَ أَ[g[نّ]َهُ [h:137[ٱ]لْحَقُّ م[u:770[ِن ر]َّبِّكَ فَيُؤْمِنُو[s[اْ] بِه[n[ِۦ] فَتُخْبِتَ لَهُ[n[ۥ] قُلُوبُهُمْ‌ۗ وَإِ[g[نّ]َ [h:1986[ٱ]للَّهَ لَهَادِ [h:9075[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Илм берилганлар у Роббингдан келган ҳақ эканини билишлари, унга иймон келтиришлари ва қалблари унга боғланиб, таскин топиши учундир. Албатта, Аллоҳ иймон келтирганларни тўғри йўлга ҳидоят қилгувчидир.",338,17],["وَلَا يَزَالُ [h:6990[ٱ]لَّذِينَ كَفَرُو[s[اْ] فِى مِرْيَ[a:6279[ةٍ م]ِّنْهُ حَتَّىٰ تَأْتِيَهُمُ [h:6846[ٱ][l[ل]سَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَق[p[ِي]مٍ","Куфр келтирганлар, уларга соати тўсатдан келгунича ёки қисир Кун азоби келгунича удан шубҳада бўлишда давом этурлар.",338,17],["ٱلْمُلْكُ يَوْمَئِ[u:9076[ذٍ ل]ِّلَّهِ يَحْكُمُ بَيْنَهُمْ‌ۚ فَ[h:2514[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ فِى جَ[g[نّ]َ[n[ـٰ]تِ [h:3680[ٱ][l[ل][g[نّ]َع[p[ِي]مِ","Ўша кунда ҳукмронлик Аллоҳгагина хосдир. У улар орасида ҳукм қилур. Бас, иймон келтирганлар ва яхши амал қилганлар нозу неъмат жаннатларидадирлар.",339,17],["وَ[h:9999[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَكَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ عَذَا[a:478[بٌ م]ُّه[p[ِي]نٌ","Куфр келтирган ва оятларимизни ёлғонга чиқарганлар эса, бас, ана ўшаларга хорловчи азоб бордир.",339,17],["وَ[h:9999[ٱ]لَّذِينَ هَاجَرُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ ثُ[g[مّ]َ قُتِل[o[ُوٓ][s[اْ] أَوْ مَاتُو[s[اْ] لَيَرْزُقَ[g[نّ]َهُمُ [h:9077[ٱ]للَّهُ رِزْقًا حَسَ[a:9078[نًا‌ۚ و]َإِ[g[نّ]َ [h:1986[ٱ]للَّهَ لَهُوَ خَيْرُ [h:3894[ٱ][l[ل]رّ[n[َٲ]زِق[p[ِي]نَ","Аллоҳ йўлида ҳижрат қилганлар, сўнгра ўлдирилиб ёки вафот этганларни, албатта, Аллоҳ гўзал ризқ ила ризқлантирур. Албатта, Аллоҳ ризқ бергувчиларнинг энг яхшисидир.",339,17],["لَيُ[q:9079[دْ]خِلَ[g[نّ]َه[w:9080[ُم م]ُّ[q:2743[دْ]خَل[a:9081[اً ي]َرْضَوْنَهُ[n[ۥ]‌ۗ وَإِ[g[نّ]َ [h:1986[ٱ]للَّهَ لَعَلِيمٌ حَل[p[ِي]مٌ","Албатта, У зот уларни ўзлари рози бўладиган жойга киритур. Албатта, Аллоҳ ўта билгувчи ва ҳалим зотдир.",339,17],["۞ ذ[n[َٲ]لِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِه[n[ِۦ] ثُ[g[مّ]َ بُغِىَ عَلَيْهِ لَيَ[f:9082[نص]ُرَ[g[نّ]َهُ [h:9083[ٱ]للَّهُ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَعَفُوٌّ غَف[p[ُو]رٌ","Иш бундоқ. Ким ўзига иқоб қилинганига ўхшаш иқоб қилсаю, сўнгра унга яна зўравонлик қилинса, Аллоҳ, албатта, унга нусрат берур. Албатта, Аллоҳ авфли ва мағфиратли зотдир.",339,17],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َ [h:897[ٱ]للَّهَ يُولِجُ [h:9084[ٱ]لَّيْلَ فِى [h:1829[ٱ][l[ل][g[نّ]َهَارِ وَيُولِجُ [h:9085[ٱ][l[ل][g[نّ]َهَارَ فِى [h:1831[ٱ]لَّيْلِ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ سَمِي[i:9086[عُۢ ب]َص[p[ِي]رٌ","Чунки Аллоҳ, албатта, кечани кундузга киритур ва кундузни кечага киритур. Албатта, Аллоҳ ўта эшитгувчи ва ўта кўргувчи зотдир.",339,17],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َ [h:897[ٱ]للَّهَ هُوَ [h:8923[ٱ]لْحَقُّ وَأَ[g[نّ]َ مَا يَ[q:1240[دْ]عُونَ مِ[f:3136[ن د]ُونِه[n[ِۦ] هُوَ [h:9087[ٱ]لْبَ[n[ـٰ]طِلُ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ هُوَ [h:9088[ٱ]لْعَلِىُّ [h:9089[ٱ]لْكَب[p[ِي]رُ","Чунки Аллоҳнинг Ўзигина ҳақдир, Ундан бошқа топинаётганлари эса, ботилдир. Албатта, Аллоҳ юксак ва буюкдир.",339,17],["أَلَمْ تَرَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ أَ[f:471[نز]َلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:9090[ءً ف]َتُصْبِحُ [h:9091[ٱ]لْأَرْضُ مُخْضَرَّةً‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَطِيفٌ خَب[p[ِي]رٌ","Аллоҳ осмондан сув туширганида, ернинг ям-яшил бўлишини кўрмадингми?! Албатта, Аллоҳ ўта лутфли ва хабардор зотдир.",339,17],["لَّهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۗ وَإِ[g[نّ]َ [h:1986[ٱ]للَّهَ لَهُوَ [h:9092[ٱ]لْغَنِىُّ [h:9093[ٱ]لْحَم[p[ِي][q[د]ُ","Осмонлару ердаги нарсалар Уникидир. Албатта, Аллоҳ, Унинг Ўзигина беҳожат ва мақталган зотдир.",339,17],["أَلَمْ تَرَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ سَخَّرَ لَك[w:154[ُم م]َّا فِى [h:44[ٱ]لْأَرْضِ وَ[h:9094[ٱ]لْفُلْكَ تَ[q:120[جْ]رِى فِى [h:837[ٱ]لْبَحْرِ بِأَمْرِه[n[ِۦ] وَيُمْسِكُ [h:9095[ٱ][l[ل]سَّم[o[َا]ٓءَ أَ[f:9096[ن ت]َقَعَ عَلَى [h:7958[ٱ]لْأَرْضِ إِلَّا بِإِذْنِه[o[ِۦٓ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ بِ[h:743[ٱ][l[ل][g[نّ]َاسِ لَرَءُو[u:744[فٌ ر]َّح[p[ِي]مٌ","Аллоҳ ердаги нарсаларни, денгизда Ўз изни ила юрадиган кемани сизларга бўйсундириб қўйганини ҳамда осмонни изнисиз ерга тушишдан тутиб туришини кўрмадингизми?! Албатта, Аллоҳ одамларга шафқатли ва меҳрибондир.",340,17],["وَهُوَ [h:4114[ٱ]لَّذ[o[ِىٓ] أَحْيَاكُمْ ثُ[g[مّ]َ يُمِيتُكُمْ ثُ[g[مّ]َ يُحْيِيكُمْ‌ۗ إِ[g[نّ]َ [h:7137[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ لَكَف[p[ُو]رٌ","Сизларни тирилтирган, кейин ўлдирадиган, сўнгра тирилтирадиган ҳам Унинг Ўзидир. Албатта, инсон ўта ношукрдир.",340,17],["لِّكُلِّ أُ[g[مّ]َ[f:9013[ةٍ ج]َعَلْنَا مَ[f:9014[نس]َكًا هُمْ نَاسِكُوهُ‌ۖ فَلَا يُنَ[n[ـٰ]زِعُ[g[نّ]َكَ فِى [h:2319[ٱ]لْأَمْرِ‌ۚ وَ[h:9097[ٱ][q:9097[دْ]عُ إِلَىٰ رَبِّكَ‌ۖ إِ[g[نّ]َكَ لَعَلَىٰ هُ[a:9098[دًى م]ُّسْتَق[p[ِي]مٍ","Биз ҳар бир умматга шариат берганмиз. Улар ўшанга амал қилгувчилардир. Бас, бу ишда ҳаргиз сен ила низо қилмасинлар. Роббингга даъват қил. Албатта, сен мустақийм ҳидоятдасан.",340,17],["وَإِ[f:9099[ن ج]َ[n[ـٰ]دَلُوكَ فَقُلِ [h:9100[ٱ]للَّهُ أَعْلَمُ بِمَا تَعْمَل[p[ُو]نَ","Агар улар сен билан тортишсалар: «Аллоҳ нима қилаётганингизни билгувчидир.",340,17],["ٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ فِيمَا كُ[f:100[نت]ُمْ فِيهِ تَخْتَلِف[p[ُو]نَ","Аллоҳ қиёмат куни сиз ихтилоф қилган нарса бўйича орангизда ҳукм қиладир», деб айт.",340,17],["أَلَمْ تَعْلَمْ أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَعْلَمُ مَا فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِ‌ۗ إِ[g[نّ]َ ذ[n[َٲ]لِكَ فِى كِتَ[n[ـٰ]بٍ‌ۚ إِ[g[نّ]َ ذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ يَس[p[ِي]رٌ","Аллоҳ, албатта, осмону ердаги нарсани билишини, ана ўша, албатта, китобда эканини ва, албатта, у нарса Аллоҳга осон эканини билмайсанми?!",340,17],["وَيَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مَا لَمْ يُنَزِّلْ بِه[n[ِۦ] سُلْطَ[n[ـٰ][a:9101[نًا و]َمَا لَيْسَ لَه[c:3276[ُم ب]ِه[n[ِۦ] عِلْ[a:9102[مٌ‌ۗ و]َمَا لِلظَّ[n[ـٰ]لِمِينَ م[a:9103[ِن ن]َّص[p[ِي]رٍ","Улар Аллоҳни қўйиб, У зот ҳақларида бирон ҳужжат туширмаган, ўзларида у ҳақда илм бўлмаган нарсага ибодат қиладилар. Золимларга ҳеч бир нусрат бергувчи йўқдир.",340,17],["وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَ[n[ـٰ]تُنَا بَيِّنَ[n[ـٰ][f:9104[تٍ ت]َعْرِفُ فِى وُجُوهِ [h:9105[ٱ]لَّذِينَ كَفَرُو[s[اْ] [h:9106[ٱ]لْمُ[f:9107[نك]َرَ‌ۖ يَكَادُونَ يَسْطُونَ بِ[h:2413[ٱ]لَّذِينَ يَتْلُونَ عَلَيْهِمْ ءَايَ[n[ـٰ]تِنَا‌ۗ قُلْ أَفَأُنَبِّئُك[c:9108[ُم ب]ِشَ[a:3654[رٍّ م]ِّ[f:9109[ن ذ][n[َٲ]لِكُمُ‌ۗ [h:9110[ٱ][l[ل][g[نّ]َارُ وَعَدَهَا [h:9111[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ كَفَرُو[s[اْ‌ۖ] وَبِئْسَ [h:665[ٱ]لْمَص[p[ِي]رُ","Уларга очиқ-ойдин оятларимиз тиловат қилинаётганида, куфр келтирганларнинг юзларида инкорни кўрурсан. Улар ўзларига оятларимизни тиловат қилиб бераётганларга чанг солишга оз қолурлар. Сен уларга: «Бунингиздан ҳам ёмонроқ нарсанинг хабарини берайми? У дўзахдир. Аллоҳ уни куфр келтирганларга ваъда қилгандир. Ва у нақадар ёмон қайтиш жойидир», деб айт.",340,17],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ ضُرِبَ مَثَ[f:9112[لٌ ف]َ[h:5220[ٱ]سْتَمِعُو[s[اْ] لَهُ[o[ۥٓ‌ۚ] إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ تَ[q:4040[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ ل[a:9113[َن ي]َخْلُقُو[s[اْ] ذُبَا[a:9114[بًا و]َلَوِ [h:9115[ٱ][q:9116[جْ]تَمَعُو[s[اْ] لَهُ[n[ۥ]‌ۖ وَإ[a:9117[ِن ي]َسْلُ[q:9118[بْ]هُمُ [h:9119[ٱ][l[ل]ذُّبَابُ شَيْـ[u:9120[ـًٔا ل]َّا يَسْتَ[f:9121[نق]ِذُوهُ مِنْهُ‌ۚ ضَعُفَ [h:9122[ٱ][l[ل]طَّالِبُ وَ[h:9123[ٱ]لْمَ[q:9123[طْ]ل[p[ُو][q[ب]ُ","Эй одамлар! Бир масал айтилмиш, бас, унга қулоқ солинг! Албатта, сизлар Аллоҳни қўйиб, топинаётган нарсаларингиз, агар барчалари бирлашсалар ҳам, битта пашша ярата олмаслар. Ва агар пашша улардан бирон нарсани тортиб олса, ундан ўшани қутқариб ололмаслар. Талаб қилувчи ҳам, талаб қилинган ҳам ожиз бўлди.",341,17],["مَا قَدَرُو[s[اْ] [h:4225[ٱ]للَّهَ حَقَّ قَ[q:4226[دْ]رِه[o[ِۦٓ‌ۗ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَقَوِىٌّ عَز[p[ِي]زٌ","Улар Аллоҳнинг қадрини жойига қўймадилар. Албатта, Аллоҳ кучли ва азиздир.",341,17],["ٱللَّهُ يَصْطَفِى مِنَ [h:2217[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ رُسُل[a:9124[اً و]َمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَمِي[i:9086[عُۢ ب]َص[p[ِي]رٌ","Аллоҳ фаришталардан ва одамлардан Пайғамбарлар танлар. Албатта, Аллоҳ ўта эшитгувчи ва кўргувчидир.",341,17],["يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ‌ۗ وَإِلَى [h:1148[ٱ]للَّهِ تُرْجَعُ [h:1149[ٱ]لْأُم[p[ُو]رُ","У зот уларнинг олдиларидаги ва ортларидаги нарсани билур. Барча ишлар ёлғиз Аллоҳгагина қайтарилур.",341,17],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:9125[ٱ]رْكَعُو[s[اْ] وَ[h:9126[ٱ]سْجُدُو[s[اْ] وَ[h:9127[ٱ]عْبُدُو[s[اْ] رَبَّكُمْ وَ[h:9128[ٱ]فْعَلُو[s[اْ] [h:9129[ٱ]لْخَيْرَ لَعَلَّكُمْ تُفْلِحُ[p[و]نَ ۩","Эй иймон келтирганлар! Рукуъ, сажда қилинглар ва Роббингизга ибодат қилинглар ҳамда яхшилик қилинглар, шоядки нажот топсангиз.",341,17],["وَجَ[n[ـٰ]هِدُو[s[اْ] فِى [h:714[ٱ]للَّهِ حَقَّ جِهَادِه[n[ِۦ]‌ۚ هُوَ [h:9130[ٱ][q:9131[جْ]تَبَ[n[ـٰ]كُمْ وَمَا جَعَلَ عَلَيْكُمْ فِى [h:1477[ٱ][l[ل]دِّينِ مِنْ حَرَ[a:9132[جٍ‌ۚ م]ِّلَّةَ أَبِيكُمْ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ‌ۚ هُوَ سَ[g[مّ]َ[n[ـٰ]كُمُ [h:9133[ٱ]لْمُسْلِمِينَ مِ[f:128[ن ق]َ[q:129[بْ]لُ وَفِى هَ[n[ـٰ]ذَا لِيَكُونَ [h:9134[ٱ][l[ل]رَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُو[s[اْ] شُهَد[o[َا]ٓءَ عَلَى [h:729[ٱ][l[ل][g[نّ]َاسِ‌ۚ فَأَقِيمُو[s[اْ] [h:3095[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتُو[s[اْ] [h:215[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَ[h:9135[ٱ]عْتَصِمُو[s[اْ] بِ[h:32[ٱ]للَّهِ هُوَ مَوْلَ[n[ـٰ]كُمْ‌ۖ فَنِعْمَ [h:9136[ٱ]لْمَوْلَىٰ وَنِعْمَ [h:5337[ٱ][l[ل][g[نّ]َص[p[ِي]رُ","Ва Аллоҳ ҳақ жиҳод қилингиз. У сизларни танлаб олди. Ва сизга бу динда ҳеч танглик қилмади. Бу отангиз Иброҳимнинг миллати. У сизларни бундан олдин ва буда Пайғамбар сизларга гувоҳ бўлиши учун, сизлар эса, одамларга гувоҳлар бўлишингиз учун мусулмонлар деб номлади. Бас, намозни тўкис адо этинглар, закот беринглар ва Аллоҳга боғланинглар. У сизнинг хожангиздир. Бас, У зот қандай ҳам яхши хожа ва қандай ҳам яхши нусрат бергувчи.",341,17]]},{"n":23,"ar":"المُؤۡمِنُونَ","en":"Al-Muminoon","uz":"Муъминун","type":"Макка","ayahs":[["قَ[q:298[دْ] أَفْلَحَ [h:9137[ٱ]لْمُؤْمِن[p[ُو]نَ","Батаҳқиқ, мўминлар нажот топдилар.",342,18],["ٱلَّذِينَ هُمْ فِى صَلَاتِهِمْ خَ[n[ـٰ]شِع[p[ُو]نَ","Улар намозларида хушуъ қилувчилардир.",342,18],["وَ[h:9999[ٱ]لَّذِينَ هُمْ عَنِ [h:9138[ٱ][l[ل]لَّغْوِ مُعْرِض[p[ُو]نَ","Улар беҳуда нарсалардан юз ўгиргувчилардир.",342,18],["وَ[h:9999[ٱ]لَّذِينَ هُمْ لِلزَّكَ[s[و][n[ٲ]ةِ فَ[n[ـٰ]عِل[p[ُو]نَ","Улар закотни адо қилгувчилардир.",342,18],["وَ[h:9999[ٱ]لَّذِينَ هُمْ لِفُرُوجِهِمْ حَ[n[ـٰ]فِظ[p[ُو]نَ","Улар фаржларини сақловчилардир.",342,18],["إِلَّا عَلَ[o[ىٰٓ] أَزْو[n[َٲ]جِهِمْ أَوْ مَا مَلَكَتْ أَيْمَ[n[ـٰ]نُهُمْ فَإِ[g[نّ]َهُمْ غَيْرُ مَلُوم[p[ِي]نَ","Магар ўз жуфти ҳалоллари ва қўлларида мулк бўлганлардан, албатта, улар маломат қилинувчи эмаслардир.",342,18],["فَمَنِ [h:9139[ٱ][q:9140[بْ]تَغَىٰ وَر[o[َا]ٓءَ ذ[n[َٲ]لِكَ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:9141[ٱ]لْعَاد[p[ُو]نَ","Ким ана шундан бошқани талаб қилса, бас, ана ўшалар тажовузкорлардир.",342,18],["وَ[h:9999[ٱ]لَّذِينَ هُمْ لِأَمَ[n[ـٰ]نَ[n[ـٰ]تِهِمْ وَعَهْدِهِمْ ر[n[َٲ]ع[p[ُو]نَ","Улар омонатларига ва аҳдларига риоя қилгувчилардир.",342,18],["وَ[h:9999[ٱ]لَّذِينَ هُمْ عَلَىٰ صَلَو[n[َٲ]تِهِمْ يُحَافِظ[p[ُو]نَ","Улар намозларини муҳофаза қилувчилардир.",342,18],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:9142[ٱ]لْو[n[َٲ]رِث[p[ُو]نَ","Ана ўшалар ворис бўлгувчилардир.",342,18],["ٱلَّذِينَ يَرِثُونَ [h:9143[ٱ]لْفِرْدَوْسَ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Улар Фирдавсни мерос олурлар, улар унда абадий қолгувчилардир.",342,18],["وَلَقَ[q:341[دْ] خَلَ[q:5159[قْ]نَا [h:7228[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ مِ[f:9144[ن س]ُلَ[n[ـٰ]لَ[a:9145[ةٍ م]ِّ[f:3917[ن ط][p[ِي]نٍ","Қасамки, батаҳқиқ, инсонни лой сулоласидан яратдик.",342,18],["ثُ[g[مّ]َ جَعَلْنَ[n[ـٰ]هُ نُ[q:9146[طْ]فَ[f:9147[ةً ف]ِى قَرَا[a:9148[رٍ م]َّك[p[ِي]نٍ","Сўнгра уни мустаҳкам қароргоҳда нутфа қилдик.",342,18],["ثُ[g[مّ]َ خَلَ[q:5159[قْ]نَا [h:9149[ٱ][l[ل][g[نّ]ُ[q:9150[طْ]فَةَ عَلَقَ[f:9151[ةً ف]َخَلَ[q:9152[قْ]نَا [h:9153[ٱ]لْعَلَقَةَ مُضْغَ[f:9154[ةً ف]َخَلَ[q:9152[قْ]نَا [h:9155[ٱ]لْمُضْغَةَ عِظَ[n[ـٰ][f:9156[مًا ف]َكَسَوْنَا [h:9157[ٱ]لْعِظَ[n[ـٰ]مَ لَحْ[f:9158[مًا ث]ُ[g[مّ]َ أَ[f:9159[نش]َأْنَ[n[ـٰ]هُ خَلْقًا ءَاخَرَ‌ۚ فَتَبَارَكَ [h:9160[ٱ]للَّهُ أَحْسَنُ [h:9161[ٱ]لْخَ[n[ـٰ]لِق[p[ِي]نَ","Сўнгра нутфадан алақа яратдик, алақадан чайналган гўшт яратдик, чайналган парча гўштдан суяк яратдик, бас, суякка гўшт қопладик, сўнгра уни бошқа бир жонзот этиб пайдо қилдик. Бас, яратгувчиларнинг энг яхшиси Аллоҳ баракотли ва буюкдир.",342,18],["ثُ[g[مّ]َ إِ[g[نّ]َك[c:9162[ُم ب]َعْدَ ذ[n[َٲ]لِكَ لَمَيِّت[p[ُو]نَ","Сўнгра, албатта, сизлар бундан кейин ўлгувчисизлар.",342,18],["ثُ[g[مّ]َ إِ[g[نّ]َكُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ تُ[q:9163[بْ]عَث[p[ُو]نَ","Сўнгра, албатта, сизлар қиёмат куни қайта тирилтирилурсизлар.",342,18],["وَلَقَ[q:341[دْ] خَلَ[q:5159[قْ]نَا فَوْقَكُمْ سَ[q:158[بْ]عَ طَر[o[َا]ٓئِقَ وَمَا كُ[g[نّ]َا عَنِ [h:9164[ٱ]لْخَلْقِ غَ[n[ـٰ]فِل[p[ِي]نَ","Батаҳқиқ, Биз устингизда етти йўлни яратдик. Биз махлуқотдан ғофил бўлган эмасмиз.",342,18],["وَأَ[f:271[نز]َلْنَا مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[i:9165[ءَۢ ب]ِقَدَ[f:9166[رٍ ف]َأَسْكَ[g[نّ]َ[n[ـٰ]هُ فِى [h:44[ٱ]لْأَرْضِ‌ۖ وَإِ[g[نّ]َا عَلَىٰ ذَهَا[i:9167[بِۭ ب]ِه[n[ِۦ] لَقَ[n[ـٰ]دِر[p[ُو]نَ","Биз осмондан ўлчов ила сув тушириб, уни ерга жойлаштирдик. Албатта, Биз уни кетказишга ҳам қодирдирмиз.",343,18],["فَأَ[f:9168[نش]َأْنَا لَك[c:2000[ُم ب]ِه[n[ِۦ] جَ[g[نّ]َ[n[ـٰ][a:9169[تٍ م]ّ[a:1568[ِن ن]َّخِي[a:1569[لٍ و]َأَعْنَ[n[ـٰ][u:9170[بٍ ل]َّكُمْ فِيهَا فَو[n[َٲ]كِهُ كَثِيرَ[a:9171[ةٌ و]َمِنْهَا تَأْكُل[p[ُو]نَ","Ва у ила сиз учун хурмо ва узум боғлари пайдо қилдик, сизга уларда кўп мевалар бўлиб, улардан ерсизлар.",343,18],["وَشَجَرَ[f:9172[ةً ت]َخْرُجُ مِ[f:9173[ن ط]ُورِ سَيْن[o[َا]ٓءَ تَ[i:9174[نۢب]ُتُ بِ[h:9175[ٱ][l[ل]دُّهْنِ وَصِ[q:9176[بْ][u:9177[غٍ ل]ِّلْأَكِل[p[ِي]نَ","Ва Тури Сийнодан чиқадиган бир дарахтни, у ёғ ва егувчиларга нонхуриш ила ўсур.",343,18],["وَإِ[g[نّ]َ لَكُمْ فِى [h:7465[ٱ]لْأَنْعَ[n[ـٰ]مِ لَعِ[q:1764[بْ]رَ[a:7466[ةً‌ۖ ن]ُّسْقِيك[w:7467[ُم م]ِّ[g[مّ]َا فِى بُطُونِهَا وَلَكُمْ فِيهَا مَنَ[n[ـٰ]فِعُ كَثِيرَ[a:9171[ةٌ و]َمِنْهَا تَأْكُل[p[ُو]نَ","Албатта, сиз учун чорва ҳайвонларида ибрат бордир. Биз сизни уларнинг қоринларидаги нарса ила суғорурмиз ва сиз учун уларда кўпгина манфаатлар бор ва улардан ерсизлар.",343,18],["وَعَلَيْهَا وَعَلَى [h:9178[ٱ]لْفُلْكِ تُحْمَل[p[ُو]نَ","Ва уларга ва кемаларга юкланурсизлар.",343,18],["وَلَقَ[q:341[دْ] أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِه[n[ِۦ] فَقَالَ يَ[n[ـٰ]قَوْمِ [h:4768[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ مَا لَك[w:556[ُم م]ِّنْ إِلَ[n[ـٰ]هٍ غَيْرُهُ[o[ۥٓ‌ۖ] أَفَلَا تَتَّق[p[ُو]نَ","Батаҳқиқ, Биз Нуҳни қавмига юбордик. Бас, у: «Эй қавмим, Аллоҳга ибодат қилинг. Сиз учун Ундан ўзга ҳеч бир илоҳ йўқдир. Наҳотки қўрқмасангиз?!» деди.",343,18],["فَقَالَ [h:9179[ٱ]لْمَلَؤُ[s[اْ] [h:9180[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِ[f:4770[ن ق]َوْمِه[n[ِۦ] مَا هَ[n[ـٰ]ذ[o[َآ] إِلَّا بَشَ[a:7069[رٌ م]ِّثْلُكُمْ يُرِيدُ أ[a:9181[َن ي]َتَفَضَّلَ عَلَيْكُمْ وَلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ لَأَ[f:9182[نز]َلَ مَلَ[o[ـٰٓ]ئِكَ[a:9183[ةً م]َّا سَمِعْنَا بِهَ[n[ـٰ]ذَا ف[o[ِىٓ] ءَاب[o[َا]ٓئِنَا [h:9184[ٱ]لْأَوَّل[p[ِي]نَ","Бас, унинг қавмидан куфр келтирган зодагонлари: «Бу сизга ўхшаш башар, холос, сиздан афзал бўлиб олмоқчи. Агар Аллоҳ хоҳласа, фаришталарни туширар эди. Аввалги ота-боболаримизда буни эшитган эмасмиз.",343,18],["إِنْ هُوَ إِلَّا رَجُ[i:9185[لُۢ ب]ِه[n[ِۦ] جِ[g[نّ]َ[f:9186[ةٌ ف]َتَرَبَّصُو[s[اْ] بِه[n[ِۦ] حَتَّىٰ ح[p[ِي]نٍ","У фақат бир жинни одам, холос. Бас, уни бир оз муддат пойлаб туринг», дедилар.",343,18],["قَالَ رَبِّ [h:9187[ٱ][f:9188[نص]ُرْنِى بِمَا كَذَّب[p[ُو]نِ","У: «Эй Роббим, мени ёлғончи қилганларга қарши менга нусрат бер», деди.",343,18],["فَأَوْحَيْن[o[َآ] إِلَيْهِ أَنِ [h:9189[ٱ]صْنَعِ [h:9190[ٱ]لْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا ج[o[َا]ٓءَ أَمْرُنَا وَفَارَ [h:6327[ٱ][l[ل]تَّ[g[نّ]ُورُ‌ۙ فَ[h:9191[ٱ]سْلُكْ فِيهَا مِ[f:6329[ن ك]ُ[f:6330[لٍّ ز]َوْجَيْنِ [h:6331[ٱ]ثْنَيْنِ وَأَهْلَكَ إِلَّا مَ[f:6332[ن س]َبَقَ عَلَيْهِ [h:6333[ٱ]لْقَوْلُ مِنْهُمْ‌ۖ وَلَا تُخَ[n[ـٰ]طِ[q:6319[بْ]نِى فِى [h:6320[ٱ]لَّذِينَ ظَلَم[o[ُوٓ[s[اْ]‌ۖ] إِ[g[نّ]َه[w:6321[ُم م]ُّغْرَق[p[ُو]نَ","Бас, Биз унга: «Бизнинг кўз ўнгимизда ва ваҳийимиз ила кема яса. Бас, Бизнинг амримиз келиб, таннур фаввора бўлганда, уга ҳар бир турдан бир жуфтдан ва аҳлингни чиқар, магар кимнинг зиддига олдин сўзимиз ўтган бўлса. Зулм қилганлар ҳақида Менга хитоб қилма. Албатта, улар ғарқ қилингувчилардир.",343,18],["فَإِذَا [h:9192[ٱ]سْتَوَيْتَ أَ[f:169[نت]َ وَم[a:9193[َن م]َّعَكَ عَلَى [h:9194[ٱ]لْفُلْكِ فَقُلِ [h:9195[ٱ]لْحَمْدُ لِلَّهِ [h:3912[ٱ]لَّذِى نَجَّ[n[ـٰ]نَا مِنَ [h:4196[ٱ]لْقَوْمِ [h:4155[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Бас, сен ўзинг билан бирга бўлганлар ила кемага жойлашиб олгач: «Бизни золим қавмлардан қутқарган Аллоҳга ҳамдлар бўлсин», дегин.",344,18],["وَقُ[b:7725[ل] رَّبِّ أَ[f:9196[نز]ِلْنِى مُ[f:9197[نز]َل[a:9198[اً م]ُّبَارَ[a:9199[كًا و]َأَ[f:3893[نت]َ خَيْرُ [h:6726[ٱ]لْمُ[f:6727[نز]ِل[p[ِي]نَ","Ва: «Эй Роббим, мени муборак манзилга туширгин, Сен, Ўзинг манзилга туширгувчиларнинг энг яхшисисан», дегин», дедик.",344,18],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][a:9200[تٍ و]َإِ[f:4542[ن ك]ُ[g[نّ]َا لَمُ[q:9201[بْ]تَل[p[ِي]نَ","Албатта, бунда оят-ибратлар бордир. Албатта, Биз синовчи бўлган эдик.",344,18],["ثُ[g[مّ]َ أَ[f:9202[نش]َأْنَا م[i:1453[ِنۢ ب]َعْدِهِمْ قَرْنًا ءَاخَر[p[ِي]نَ","Сўнгра улардан кейин бошқа авлодларни пайдо қилдик.",344,18],["فَأَرْسَلْنَا فِيهِمْ رَسُول[a:677[اً م]ِّنْهُمْ أَنِ [h:3899[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ مَا لَك[w:556[ُم م]ِّنْ إِلَ[n[ـٰ]هٍ غَيْرُهُ[o[ۥٓ‌ۖ] أَفَلَا تَتَّق[p[ُو]نَ","Бас, уларнинг ичига ўзларидан бўлган Пайғамбарни: «Аллоҳга ибодат қилинг. Сиз учун Ундан ўзга илоҳ йўқдир, наҳотки, қўрқмасангиз», деб юбордик.",344,18],["وَقَالَ [h:4866[ٱ]لْمَلَأُ مِ[f:4770[ن ق]َوْمِهِ [h:9203[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَكَذَّبُو[s[اْ] بِلِق[o[َا]ٓءِ [h:9204[ٱ]لْأَخِرَةِ وَأَتْرَفْنَ[n[ـٰ]هُمْ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا مَا هَ[n[ـٰ]ذ[o[َآ] إِلَّا بَشَ[a:7069[رٌ م]ِّثْلُكُمْ يَأْكُلُ مِ[g[مّ]َا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِ[g[مّ]َا تَشْرَب[p[ُو]نَ","Унинг қавмидан куфр келтирган, охиратга рўбарў бўлишини ёлғонга чиқарган ва Биз уларни ҳаёти дунёда маишатпараст қилиб қўйган зодагонлари: «Бу сизга ўхшаган башар, холос. Сиз еган нарсадан ейди, сиз ичган нарсадан ичади.",344,18],["وَلَئِنْ أَطَعْت[c:9205[ُم ب]َشَ[a:9206[رًا م]ِّثْلَكُمْ إِ[g[نّ]َكُمْ إِ[u:4868[ذًا ل]َّخَ[n[ـٰ]سِر[p[ُو]نَ","Агар ўзингизга ўхшаган башарга итоат қилсангиз, унда, албатта, сиз зиёнкорлардандирсиз.",344,18],["أَيَعِدُكُمْ أَ[g[نّ]َكُمْ إِذَا مِتُّمْ وَكُ[f:151[نت]ُمْ تُرَا[a:9207[بًا و]َعِظَ[n[ـٰ]مًا أَ[g[نّ]َك[w:9208[ُم م]ُّخْرَج[p[ُو]نَ","У сизга, ўлсангиз, тупроқ ва суяк бўлсангиз ҳам, албатта, чиқарилгувчи бўлишингизни ваъда қилмоқдами?!",344,18],["۞ هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَد[p[ُو]نَ","Ҳайҳот! Ҳайҳот! Сизга ваъда қилинган нарса нақадар узоқ!",344,18],["إِنْ هِىَ إِلَّا حَيَاتُنَا [h:3995[ٱ][l[ل]دُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَ[q:3996[بْ]عُوث[p[ِي]نَ","Шу дунёдаги ҳаётимиздан бошқа ҳаёт йўқдир. Ўламиз, тириламиз ва биз қайта тирилгувчи эмасмиз.",344,18],["إِنْ هُوَ إِلَّا رَجُلٌ [h:9209[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِ[a:9210[بًا و]َمَا نَحْنُ لَهُ[n[ۥ] بِمُؤْمِن[p[ِي]نَ","У фақат Аллоҳга нисбатан ёлғон уйдирган одам, холос. Биз унга иймон келтиргувчи эмасмиз», дедилар.",344,18],["قَالَ رَبِّ [h:9187[ٱ][f:9188[نص]ُرْنِى بِمَا كَذَّب[p[ُو]نِ","У: «Эй Роббим, мени ёлғончи қилганларга қарши менга нусрат бер», деди.",344,18],["قَالَ عَ[g[مّ]َا قَلِي[u:9211[لٍ ل]َّيُصْبِحُ[g[نّ]َ نَ[n[ـٰ]دِم[p[ِي]نَ","У зот: «Озгинадан сўнг улар надомат чекувчи бўлурлар», деди.",344,18],["فَأَخَذَتْهُمُ [h:7288[ٱ][l[ل]صَّيْحَةُ بِ[h:370[ٱ]لْحَقِّ فَجَعَلْنَ[n[ـٰ]هُمْ غُث[o[َا]ٓ[f:9212[ءً‌ۚ ف]َبُعْ[u:9213[دًا ل]ِّلْقَوْمِ [h:6165[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Бас, уларни ҳақ ила қичқириқ олди. Бас, Биз уларни хасу чўпга айлантирдик. Даф бўлсин золим қавмлар!",344,18],["ثُ[g[مّ]َ أَ[f:9202[نش]َأْنَا م[i:1453[ِنۢ ب]َعْدِهِمْ قُرُونًا ءَاخَر[p[ِي]نَ","Сўнгра улардан кейин бошқа аср авлодларини пайдо қилдик.",344,18],["مَا تَسْبِقُ مِنْ أُ[g[مّ]َةٍ أَجَلَهَا وَمَا يَسْتَــْٔخِر[p[ُو]نَ","Ҳеч бир уммат ўз ажалидан олдин ҳам кетмас, ортда ҳам қолмас.",345,18],["ثُ[g[مّ]َ أَرْسَلْنَا رُسُلَنَا تَتْرَا‌ۖ كُلَّ مَا ج[o[َا]ٓءَ أُ[g[مّ]َ[u:9214[ةً ر]َّسُولُهَا كَذَّبُوهُ‌ۚ فَأَتْبَعْنَا بَعْضَه[c:9215[ُم ب]َعْ[a:9216[ضًا و]َجَعَلْنَ[n[ـٰ]هُمْ أَحَادِيثَ‌ۚ فَبُعْ[u:9217[دًا ل]ِّقَوْ[u:9218[مٍ ل]َّا يُؤْمِن[p[ُو]نَ","Сўнгра Пайғамбарларимизни кетма-кет юбордик. Ҳар қачон бир умматга ўз Пайғамбари келса, уни ёлғончи қилдилар. Бас, Биз ҳам уларни баъзилари ортидан баъзиларини эргаштиравердик ва уларни гапу сўзга айлантирдик. Бас, даф бўлсин иймон келтирмайдиган қавмлар!",345,18],["ثُ[g[مّ]َ أَرْسَلْنَا مُوسَىٰ وَأَخَاهُ هَ[n[ـٰ]رُونَ بِـَٔـايَ[n[ـٰ]تِنَا وَسُلْطَ[n[ـٰ][a:6479[نٍ م]ُّب[p[ِي]نٍ","Сўнгра биз Мусо ва биродари Ҳорунни оятларимиз ва очиқ ҳужжат ила юбордик.",345,18],["إِلَىٰ فِرْعَوْنَ وَمَلَإِ[s[يْ]ه[n[ِۦ] فَ[h:4956[ٱ]سْتَكْبَرُو[s[اْ] وَكَانُو[s[اْ] قَوْمًا عَال[p[ِي]نَ","Фиръавн ва унинг аъёнларига. Бас, улар мутакаббирлик қилдилар ва ўзини юқори қўйган қавм бўлдилар.",345,18],["فَقَال[o[ُوٓ][s[اْ] أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَ[n[ـٰ]بِد[p[ُو]نَ","Бас, улар: «Ўзимизга ўхшаган икки башарга иймон келтирамизми?! Ҳолбуки, уларнинг қавми бизга қуллик қилгувчи бўлиб турибди-ку?! « дедилар.",345,18],["فَكَذَّبُوهُمَا فَكَانُو[s[اْ] مِنَ [h:9219[ٱ]لْمُهْلَك[p[ِي]نَ","Бас, икковларини ёлғончи қилдилар ва ҳалок қилинганлардан бўлдилар.",345,18],["وَلَقَ[q:341[دْ] ءَاتَيْنَا مُوسَى [h:257[ٱ]لْكِتَ[n[ـٰ]بَ لَعَلَّهُمْ يَهْتَد[p[ُو]نَ","Батаҳқиқ, Биз, шоядки, ҳидоят топсалар, деб Мусога Китобни берган эдик.",345,18],["وَجَعَلْنَا [h:9220[ٱ][q:451[بْ]نَ مَرْيَمَ وَأُ[g[مّ]َهُ[o[ۥٓ] ءَايَ[a:9221[ةً و]َءَاوَيْنَ[n[ـٰ]هُم[o[َآ] إِلَىٰ رَ[q:9222[بْ]وَ[f:9223[ةٍ ذ]َاتِ قَرَا[a:9224[رٍ و]َمَع[p[ِي]نٍ","Ибн Марямни ва унинг онасини оят-аломат қилдик ва икковларини оқар сувли қароргоҳ тепаликка жойладик.",345,18],["يَ[o[ـٰٓ]أَيُّهَا [h:9225[ٱ][l[ل]رُّسُلُ كُلُو[s[اْ] مِنَ [h:5307[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تِ وَ[h:9226[ٱ]عْمَلُو[s[اْ] صَ[n[ـٰ]لِحًا‌ۖ إِ[g[نّ]ِى بِمَا تَعْمَلُونَ عَل[p[ِي]مٌ","Эй Пайғамбарлар! Пок нарсалардан енглар ва солиҳ амаллар қилинглар. Албатта, Мен нима амал қилаётганингизни ўта билгувчиман.",345,18],["وَإِ[g[نّ]َ هَ[n[ـٰ]ذِه[o[ِۦٓ] أُ[g[مّ]َتُكُمْ أُ[g[مّ]َ[a:1159[ةً و][n[َٲ]حِدَ[a:8854[ةً و]َأَنَا۟ رَبُّكُمْ فَ[h:210[ٱ]تَّق[p[ُو]نِ","Албатта, сизнинг бу умматингиз ягона умматдир. Мен эса, Роббингизман. Бас, Менгагина тақво қилинг.",345,18],["فَتَقَطَّع[o[ُوٓ][s[اْ] أَمْرَه[c:8517[ُم ب]َيْنَهُمْ زُبُ[f:9227[رًا‌ۖ ك]ُلُّ حِزْ[i:9228[بِۭ ب]ِمَا لَدَيْهِمْ فَرِح[p[ُو]نَ","Бас, улар ишларини ўз ораларида пора-пора қилиб бўлиб юбордилар. Ҳар фирқа ўз ҳузурларидаги нарса ила хурсанддирлар.",345,18],["فَذَرْهُمْ فِى غَمْرَتِهِمْ حَتَّىٰ ح[p[ِي]نٍ","Бас, сен уларни ғафлатларида бир муддат қўйиб қўй.",345,18],["أَيَحْسَبُونَ أَ[g[نّ]َمَا نُمِدُّه[c:9229[ُم ب]ِه[n[ِۦ] م[a:9230[ِن م]َّا[a:9231[لٍ و]َبَن[p[ِي]نَ","Улар Бизнинг ўзларига молу дунё ва фарзандлар ила мадад бераётганимизни.",345,18],["نُسَارِعُ لَهُمْ فِى [h:2181[ٱ]لْخَيْر[n[َٲ]تِ‌ۚ بَل لَّا يَشْعُر[p[ُو]نَ","Уларга яхшиликларни тезлатишимиз, деб ҳисоблайдиларми? Йўқ! Улар сезмаслар.",345,18],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ه[w:9232[ُم م]ِّنْ خَشْيَةِ رَبِّه[w:9233[ِم م]ُّشْفِق[p[ُو]نَ","Албатта, Роббиларидан қўрқиб хавфда турувчилар.",345,18],["وَ[h:9999[ٱ]لَّذِينَ ه[c:9234[ُم ب]ِـَٔـايَ[n[ـٰ]تِ رَبِّهِمْ يُؤْمِن[p[ُو]نَ","Ва Роббилари оятларига иймон келтирадиганлар.",345,18],["وَ[h:9999[ٱ]لَّذِينَ ه[c:9235[ُم ب]ِرَبِّهِمْ لَا يُشْرِك[p[ُو]نَ","Ва Роббиларига ширк келтирмайдиганлар.",345,18],["وَ[h:9999[ٱ]لَّذِينَ يُؤْتُونَ م[o[َآ] ءَاتَو[s[اْ] وَّقُلُوبُهُمْ وَجِلَةٌ أَ[g[نّ]َهُمْ إِلَىٰ رَبِّهِمْ ر[n[َٲ]جِع[p[ُو]نَ","Ва берадиган нарсаларини, албатта, Роббиларига қайтгувчи эканликларидан қалблари титраган ҳолда берурлар.",346,18],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يُسَ[n[ـٰ]رِعُونَ فِى [h:2181[ٱ]لْخَيْر[n[َٲ]تِ وَهُمْ لَهَا سَ[n[ـٰ]بِق[p[ُو]نَ","Ана ўшалар яхшиликларга шошилурлар ва улар ўшалар учун мусобақа қилурлар.",346,18],["وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا‌ۖ وَلَدَيْنَا كِتَ[n[ـٰ][a:9236[بٌ ي]َ[f:9237[نط]ِقُ بِ[h:370[ٱ]لْحَقِّ‌ۚ وَهُمْ لَا يُظْلَم[p[ُو]نَ","Биз ҳеч бир жонга тоқатидан ташқари таклиф қилмасмиз. Ҳузуримизда китоб бор. У ҳақни сўзлайдир. Уларга зулм қилинмас.",346,18],["بَلْ قُلُوبُهُمْ فِى غَمْرَ[a:9238[ةٍ م]ِّنْ هَ[n[ـٰ]ذَا وَلَهُمْ أَعْمَ[n[ـٰ][a:9239[لٌ م]ِّ[f:107[ن د]ُونِ ذ[n[َٲ]لِكَ هُمْ لَهَا عَ[n[ـٰ]مِل[p[ُو]نَ","Йўқ! Уларнинг қалблари бундан ғафлатдадир. Уларнинг бундан бошқа амаллари бордир. Улар ўша ларни қилгувчидирлар.",346,18],["حَتَّ[o[ىٰٓ] إِذ[o[َآ] أَخَذْنَا مُتْرَفِيه[c:9240[ِم ب]ِ[h:9060[ٱ]لْعَذَابِ إِذَا هُمْ يَ[q:9241[جْ]ــَٔر[p[ُو]نَ","Токи уларнинг маишатпарастларини азоб ила тутганимизда, бирдан фарёд солурлар.",346,18],["لَا تَ[q:9242[جْ]ــَٔرُو[s[اْ] [h:9243[ٱ]لْيَوْمَ‌ۖ إِ[g[نّ]َك[w:9244[ُم م]ِّ[g[نّ]َا لَا تُ[f:6517[نص]َر[p[ُو]نَ","Энди, бугун фарёд солманг! Албатта, Биз томонимиздан сизга нусрат қилинмас.",346,18],["قَ[q:298[دْ] كَانَتْ ءَايَ[n[ـٰ]تِى تُتْلَىٰ عَلَيْكُمْ فَكُ[f:9245[نت]ُمْ عَلَ[o[ىٰٓ] أَعْقَ[n[ـٰ]بِكُمْ تَ[f:9246[نك]ِص[p[ُو]نَ","Батаҳқиқ, Менинг оятларим сизга тиловат қилинар эди. Сиз эса, ортингизга қочар эдингиз.",346,18],["مُسْتَكْبِرِينَ بِه[n[ِۦ] سَ[n[ـٰ]مِ[f:9247[رًا ت]َهْجُر[p[ُو]نَ","У билан кибрланар, тунги суҳбатингизда беҳуда сўзлар айтар эдингиз.",346,18],["أَفَلَمْ يَدَّبَّرُو[s[اْ] [h:9248[ٱ]لْقَوْلَ أَمْ ج[o[َا]ٓءَه[w:466[ُم م]َّا لَمْ يَأْتِ ءَاب[o[َا]ٓءَهُمُ [h:9249[ٱ]لْأَوَّل[p[ِي]نَ","Наҳотки улар бу сўзни тадаббур қилиб кўрмадилар? Ёки уларга аввалги ота-боболарига келмаган нарса келибдими?",346,18],["أَمْ لَمْ يَعْرِفُو[s[اْ] رَسُولَهُمْ فَهُمْ لَهُ[n[ۥ] مُ[f:6721[نك]ِر[p[ُو]نَ","Ёки ўз Пайғамбарларини танимасдан улар унга инкор қилгувчи бўлмоқдаларми?",346,18],["أَمْ يَقُولُونَ بِه[n[ِۦ] جِ[g[نّ]َ[i:9250[ةُۢ‌ۚ ب]َلْ ج[o[َا]ٓءَه[c:9251[ُم ب]ِ[h:370[ٱ]لْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَ[n[ـٰ]رِه[p[ُو]نَ","Ёки, унда жиннилик бор, дейдиларми? Йўқ! У уларга ҳақ ила келди. Уларнинг кўплари эса, ҳақни ёмон кўргувчидирлар.",346,18],["وَلَوِ [h:9252[ٱ]تَّبَعَ [h:9253[ٱ]لْحَقُّ أَهْو[o[َا]ٓءَهُمْ لَفَسَدَتِ [h:9254[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تُ وَ[h:2241[ٱ]لْأَرْضُ وَمَ[f:7773[ن ف]ِيهِ[g[نّ]َ‌ۚ بَلْ أَتَيْنَ[n[ـٰ]ه[c:9255[ُم ب]ِذِكْرِهِمْ فَهُمْ عَ[f:9256[ن ذ]ِكْرِه[w:9257[ِم م]ُّعْرِض[p[ُو]نَ","Агар ҳақ уларнинг ҳавойи нафсларига эргашса, албатта, осмонлару ер ва улардаги кимсалар фасодга учрар эди. Йўқ! Биз уларга ўз шарафларини келтирдик. Улар эса, шарафларидан юз ўгирмоқдалар.",346,18],["أَمْ تَسْــَٔلُهُمْ خَرْ[f:9258[جًا ف]َخَرَاجُ رَبِّكَ خَيْ[a:9259[رٌ‌ۖ و]َهُوَ خَيْرُ [h:3894[ٱ][l[ل]رّ[n[َٲ]زِق[p[ِي]نَ","Ёки сен улардан харож сўраяпсанми?! Бас, Роббингнинг харожи яхшироқдир. У зот энг яхши ризқ бергувчидир.",346,18],["وَإِ[g[نّ]َكَ لَتَ[q:9260[دْ]عُوهُمْ إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Албатта, сен уларни тўғри йўлга чақирасан.",346,18],["وَإِ[g[نّ]َ [h:754[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ عَنِ [h:9261[ٱ][l[ل]صِّر[n[َٲ]طِ لَنَ[n[ـٰ]كِب[p[ُو]نَ","Албатта, охиратга иймон келтирмайдиганлар бу йўлдан озгувчидирлар.",346,18],["۞ وَلَوْ رَحِمْنَ[n[ـٰ]هُمْ وَكَشَفْنَا مَا بِه[w:2414[ِم م]ِّ[f:8832[ن ض]ُ[u:9262[رٍّ ل]َّلَجُّو[s[اْ] فِى طُغْيَ[n[ـٰ]نِهِمْ يَعْمَه[p[ُو]نَ","Агар уларга раҳм қилиб, уларга етган зарарни кушойиш қилсак ҳам, туғёнларида бардавом бўлиб, адашиб-улоқиб юраверадилар.",347,18],["وَلَقَ[q:341[دْ] أَخَذْنَ[n[ـٰ]ه[c:9263[ُم ب]ِ[h:9060[ٱ]لْعَذَابِ فَمَا [h:9264[ٱ]سْتَكَانُو[s[اْ] لِرَبِّهِمْ وَمَا يَتَضَرَّع[p[ُو]نَ","Батаҳқиқ, Биз уларни азоб ила тутдик, бас, улар Роббиларига бўйин ҳам эгмадилар, тазарруъ ҳам қилмадилар.",347,18],["حَتَّ[o[ىٰٓ] إِذَا فَتَحْنَا عَلَيْه[c:7208[ِم ب]َا[f:9265[بًا ذ]َا عَذَا[f:7040[بٍ ش]َدِيدٍ إِذَا هُمْ فِيهِ مُ[q:4051[بْ]لِس[p[ُو]نَ","Токи қачон уларга шиддатли азоб эшигини очганимизда, тўсатдан ноумид бўлгувчилардир.",347,18],["وَهُوَ [h:4114[ٱ]لَّذ[o[ِىٓ] أَ[f:4460[نش]َأَ لَكُمُ [h:7518[ٱ][l[ل]سَّمْعَ وَ[h:6037[ٱ]لْأَ[q:6037[بْ]صَ[n[ـٰ]رَ وَ[h:7519[ٱ]لْأَفْــِٔدَةَ‌ۚ قَلِيل[a:4583[اً م]َّا تَشْكُر[p[ُو]نَ","У зот сизга қулоқни, кўзлару қалбларни пайдо қилган зот. Нақадар оз шукр қилурсиз!",347,18],["وَهُوَ [h:4114[ٱ]لَّذِى ذَرَأَكُمْ فِى [h:44[ٱ]لْأَرْضِ وَإِلَيْهِ تُحْشَر[p[ُو]نَ","У зот сизларни ер юзида яратиб, таратгандир. Ва Унгагина тўпланурсизлар.",347,18],["وَهُوَ [h:4114[ٱ]لَّذِى يُحْى[n[ِۦ] وَيُمِيتُ وَلَهُ [h:9266[ٱ]خْتِلَ[n[ـٰ]فُ [h:9267[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ‌ۚ أَفَلَا تَعْقِل[p[ُو]نَ","У зот тирилтирур ва ўлдирур. Кечаю кундузнинг алмашиниши ҳам Унга оид. Наҳотки ақл юритмасангиз?",347,18],["بَلْ قَالُو[s[اْ] مِثْلَ مَا قَالَ [h:9268[ٱ]لْأَوَّل[p[ُو]نَ","Йўқ! Улар аввалгилар айтган нарсага ўхшаш нарсани айтдилар.",347,18],["قَال[o[ُوٓ][s[اْ] أَءِذَا مِتْنَا وَكُ[g[نّ]َا تُرَا[a:9207[بًا و]َعِظَ[n[ـٰ]مًا أَءِ[g[نّ]َا لَمَ[q:7784[بْ]عُوث[p[ُو]نَ","Улар: «Биз ўлиб тупроқ ва суяк бўлганимиздан кейин ҳам-а? Биз, албатта, қайта тирилтирилувчимизми-а?",347,18],["لَقَ[q:2389[دْ] وُعِ[q:9269[دْ]نَا نَحْنُ وَءَاب[o[َا]ٓؤُنَا هَ[n[ـٰ]ذَا مِ[f:128[ن ق]َ[q:129[بْ]لُ إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلّ[o[َآ] أَسَ[n[ـٰ]طِيرُ [h:3993[ٱ]لْأَوَّل[p[ِي]نَ","Батаҳқиқ, бизга ҳам, бундан олдин ота-боболаримизга ҳам бу ваъда қилинган эди. Бу аввалгиларнинг афсонасидан бошқа нарса эмас», дедилар.",347,18],["قُل لِّمَنِ [h:9270[ٱ]لْأَرْضُ وَمَ[f:9271[ن ف]ِيه[o[َآ] إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","Сен: «Агар билсангиз, Ер ва ундаги кимсалар кимникидир?» деб айт.",347,18],["سَيَقُولُونَ لِلَّهِ‌ۚ قُلْ أَفَلَا تَذَكَّر[p[ُو]نَ","«Аллоҳникидир», дерлар. Сен: «Наҳотки эслатма олмасангиз?!» дегин.",347,18],["قُلْ م[u:6925[َن ر]َّبُّ [h:6926[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ [h:9272[ٱ][l[ل]سَّ[q:9273[بْ]عِ وَرَبُّ [h:9274[ٱ]لْعَرْشِ [h:5931[ٱ]لْعَظ[p[ِي]مِ","Сен: «Етти осмоннинг Робби ким? Улуғ аршнинг Робби ким?» деб айт.",347,18],["سَيَقُولُونَ لِلَّهِ‌ۚ قُلْ أَفَلَا تَتَّق[p[ُو]نَ","Улар: «Аллоҳникидир», дерлар. Сен: «Наҳотки қўрқмасангиз?!» деб айт.",347,18],["قُلْ م[i:9275[َنۢ ب]ِيَدِه[n[ِۦ] مَلَكُوتُ كُلِّ ش[a:4300[َىْءٍ و]َهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","Сен: «Агар билсангиз, ҳар бир нарсанинг мулки қўлида бўлмиш, Ўзи ҳимоя қиладиган ва Ундан ҳимоя қилинмайдиган зот ким?!» деб айт.",347,18],["سَيَقُولُونَ لِلَّهِ‌ۚ قُلْ فَأَ[g[نّ]َىٰ تُسْحَر[p[ُو]نَ","«Аллоҳникидир», дерлар. Сен: «Қандоқ ҳам сеҳрланмоқдасиз-а?!» деб айт.",347,18],["بَلْ أَتَيْنَ[n[ـٰ]ه[c:9276[ُم ب]ِ[h:370[ٱ]لْحَقِّ وَإِ[g[نّ]َهُمْ لَكَ[n[ـٰ]ذِب[p[ُو]نَ","Йўқ! Биз уларга ҳақни келтирдик. Улар эса ёлғончилардир.",348,18],["مَا [h:9277[ٱ]تَّخَذَ [h:606[ٱ]للَّهُ م[a:8332[ِن و]َلَ[a:9278[دٍ و]َمَا كَانَ مَعَهُ[n[ۥ] مِنْ إِلَ[n[ـٰ]هٍ‌ۚ إِ[u:9279[ذًا ل]َّذَهَبَ كُلُّ إِلَ[n[ـٰ][i:9280[هِۭ ب]ِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْ[f:9281[ضٍ‌ۚ س]ُ[q:7648[بْ]حَ[n[ـٰ]نَ [h:9282[ٱ]للَّهِ عَ[g[مّ]َا يَصِف[p[ُو]نَ","Аллоҳ ҳеч бир фарзанд тутмаган, У билан бирга ҳеч бир илоҳ бўлмаган. Шундоқ бўлганида, ҳар бир илоҳ ўзи яратган нарсаси билан кетиб, баъзилари баъзиларидан устун келар эди. Аллоҳ улар қилаётган васфдан пок бўлди.",348,18],["عَ[n[ـٰ]لِمِ [h:5788[ٱ]لْغَيْبِ وَ[h:4187[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ فَتَعَ[n[ـٰ]لَىٰ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","У ғайбни ва ҳозирни билгувчидир. У улар ширк келтираётган нарсадан олийдир.",348,18],["قُ[b:9283[ل] رَّبِّ إِ[g[مّ]َا تُرِيَ[g[نّ]ِى مَا يُوعَد[p[ُو]نَ","Сен: «Эй Роббим, агар менга, албатта, уларга ваъда қилинган нарсани кўрсатадиган бўлсанг.",348,18],["رَبِّ فَلَا تَ[q:5031[جْ]عَلْنِى فِى [h:9284[ٱ]لْقَوْمِ [h:4155[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Эй Роббим, мени золим қавмлар ичида қилмагин», деб айт.",348,18],["وَإِ[g[نّ]َا عَلَ[o[ىٰٓ] أ[a:9285[َن ن]ُّرِيَكَ مَا نَعِدُهُمْ لَقَ[n[ـٰ]دِر[p[ُو]نَ","Албатта, Биз уларга ваъда қилаётган нарсамизни сенга кўрсатишга қодирмиз.",348,18],["ٱ[q:9286[دْ]فَعْ بِ[h:4526[ٱ]لَّتِى هِىَ أَحْسَنُ [h:9287[ٱ][l[ل]سَّيِّئَةَ‌ۚ نَحْنُ أَعْلَمُ بِمَا يَصِف[p[ُو]نَ","Сен эса, ёмонликни гўзал нарса ила даф қил. Биз нима васф қилаётганларини яхши билгувчимиз.",348,18],["وَقُ[b:7725[ل] رَّبِّ أَعُوذُ بِكَ مِنْ هَمَز[n[َٲ]تِ [h:9288[ٱ][l[ل]شَّيَ[n[ـٰ]ط[p[ِي]نِ","Сен: «Эй Роббим, сендан шайтонларнинг васвасасидан паноҳ сўрайман!",348,18],["وَأَعُوذُ بِكَ رَبِّ أ[a:9289[َن ي]َحْضُر[p[ُو]نِ","Сендан, эй Роббим, уларнинг менга ҳозир бўлишларидан паноҳ сўрайман», деб айт.",348,18],["حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءَ أَحَدَهُمُ [h:2656[ٱ]لْمَوْتُ قَالَ رَبِّ [h:9290[ٱ]رْجِع[p[ُو]نِ","Токи улардан бирига ўлим келган чоғда: «Эй Роббим, мени қайтаргин.",348,18],["لَعَلّ[o[ِىٓ] أَعْمَلُ صَ[n[ـٰ]لِ[f:9291[حًا ف]ِيمَا تَرَكْتُ‌ۚ كَلّ[o[َآ‌ۚ] إِ[g[نّ]َهَا كَلِمَةٌ هُوَ ق[o[َا]ٓئِلُهَا‌ۖ وَم[a:9292[ِن و]َر[o[َا]ٓئِه[c:9293[ِم ب]َرْزَخٌ إِلَىٰ يَوْمِ يُ[q:4606[بْ]عَث[p[ُو]نَ","Шоядки тарк қилган нарсамда солиҳ амал қилсам», дер. Йўқ! Албатта, бу сўз бўлиб, у айтгувчи, холос. Уларнинг ортида қайта тириладиган кунларигача тўсиқ бордир.",348,18],["فَإِذَا نُفِخَ فِى [h:4185[ٱ][l[ل]صُّورِ فَل[o[َآ] أَ[f:9294[نس]َابَ بَيْنَهُمْ يَوْمَئِ[a:9295[ذٍ و]َلَا يَتَس[o[َا]ٓءَل[p[ُو]نَ","Бас, қачонки сурга пуфланганда, у кунда ораларида на насаб қолур ва на бир-бирларини суриштирурлар.",348,18],["فَمَ[f:4591[ن ث]َقُلَتْ مَو[n[َٲ]زِينُهُ[n[ۥ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Кимнинг мезонлари оғир келса, бас, ана ўшалар, ўзлари нажот топгувчилардир.",348,18],["وَمَنْ خَفَّتْ مَو[n[َٲ]زِينُهُ[n[ۥ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:4592[ٱ]لَّذِينَ خَسِر[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ فِى جَهَ[g[نّ]َمَ خَ[n[ـٰ]لِد[p[ُو]نَ","Кимнинг мезони енгил келса, бас, ана ўшалар, ўзларига зиён қилибдилар. Жаҳаннамда абадий қолгувчи бўлибдилар.",348,18],["تَلْفَحُ وُجُوهَهُمُ [h:7188[ٱ][l[ل][g[نّ]َارُ وَهُمْ فِيهَا كَ[n[ـٰ]لِح[p[ُو]نَ","Юзларини олов куйдирур. Улар унда бадбашара ҳолда бўлурлар.",348,18],["أَلَمْ تَكُنْ ءَايَ[n[ـٰ]تِى تُتْلَىٰ عَلَيْكُمْ فَكُ[f:9245[نت][c:9296[ُم ب]ِهَا تُكَذِّب[p[ُو]نَ","Сизларга оятларим тиловат қилинган эмасмиди?! Бас, сиз уларни ёлғонга чиқарган эмасмидингиз?!",349,18],["قَالُو[s[اْ] رَبَّنَا غَلَبَتْ عَلَيْنَا شِ[q:9297[قْ]وَتُنَا وَكُ[g[نّ]َا قَوْ[f:9298[مًا ض][m[َا]ٓلّ[p[ِي]نَ","Улар: «Эй Роббимиз, бадбахтлигимиз ўзимиздан устун келиб, залолатга кетган қавм бўлган эканмиз.",349,18],["رَبَّن[o[َآ] أَخْرِ[q:2927[جْ]نَا مِنْهَا فَإِنْ عُ[q:4860[دْ]نَا فَإِ[g[نّ]َا ظَ[n[ـٰ]لِم[p[ُو]نَ","Эй Роббимиз, бизни бу дан чиқаргин, агар яна қайтсак, бас, албатта, золимлардан бўлурмиз«, дерлар.",349,18],["قَالَ [h:9299[ٱ]خْسَــُٔو[s[اْ] فِيهَا وَلَا تُكَلِّم[p[ُو]نِ","У зот: «Уда хор бўлиб қолаверинг ва Менга гапирманг!",349,18],["إِ[g[نّ]َهُ[n[ۥ] كَانَ فَرِي[a:9300[قٌ م]ِّنْ عِبَادِى يَقُولُونَ رَبَّن[o[َآ] ءَامَ[g[نّ]َا فَ[h:1791[ٱ]غْفِرْ لَنَا وَ[h:1721[ٱ]رْحَمْنَا وَأَ[f:3893[نت]َ خَيْرُ [h:9301[ٱ][l[ل]رّ[n[َٲ]حِم[p[ِي]نَ","Аниқки, Менинг бандаларимдан бир гуруҳи: «Эй Роббимиз, Биз иймон келтирдик. Бизни мағфират қилгин. Бизга раҳм қилгин. Сенинг Ўзинг раҳм қилгувчиларнинг яхшисисан», деган эдилар.",349,18],["فَ[h:9999[ٱ]تَّخَذْتُمُوهُمْ سِخْرِيًّا حَتَّ[o[ىٰٓ] أَ[f:9302[نس]َوْكُمْ ذِكْرِى وَكُ[f:151[نت][w:9303[ُم م]ِّنْهُمْ تَضْحَك[p[ُو]نَ","Бас, сиз уларни масхара қилдингиз. Ҳаттоки улар сизга Менинг зикримни унуттирди. Сиз улардан кулар эдингиз.",349,18],["إِ[g[نّ]ِى جَزَيْتُهُمُ [h:9304[ٱ]لْيَوْمَ بِمَا صَبَر[o[ُوٓ][s[اْ] أَ[g[نّ]َهُمْ هُمُ [h:5510[ٱ]لْف[o[َا]ٓئِز[p[ُو]نَ","Албатта, Мен бугун уларни сабр қилганлари учун мукофотладим. Албатта, улар ўзлари ютуққа эришгувчилардир.",349,18],["قَ[n[ـٰ]لَ كَمْ لَبِثْتُمْ فِى [h:44[ٱ]لْأَرْضِ عَدَدَ سِن[p[ِي]نَ","У зот: «Ер юзида неча йил қолдингиз?» деди.",349,18],["قَالُو[s[اْ] لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْ[f:9305[مٍ ف]َسْــَٔلِ [h:9306[ٱ]لْع[m[َا]ٓدّ[p[ِي]نَ","Улар: «Бир кун ёки куннинг баъзисича қолдик. Ҳисобловчилардан сўра», дедилар.",349,18],["قَ[n[ـٰ]لَ إ[u:7790[ِن ل]َّبِثْتُمْ إِلَّا قَلِيل[u:9307[اً‌ۖ ل]َّوْ أَ[g[نّ]َكُمْ كُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","У зот: «Агар билсангиз, жуда оз қолдингиз, холос», деди.",349,18],["أَفَحَسِ[q:9308[بْ]تُمْ أَ[g[نّ]َمَا خَلَ[q:4250[قْ]نَ[n[ـٰ]كُمْ عَبَ[a:9309[ثًا و]َأَ[g[نّ]َكُمْ إِلَيْنَا لَا تُرْجَع[p[ُو]نَ","Наҳотки Бизнинг сизни яратишимиз беҳуда бўлган ва сиз Бизга қайтарилмассиз, деб ҳисобласангиз?!",349,18],["فَتَعَ[n[ـٰ]لَى [h:5187[ٱ]للَّهُ [h:8621[ٱ]لْمَلِكُ [h:8622[ٱ]لْحَقُّ‌ۖ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ رَبُّ [h:5930[ٱ]لْعَرْشِ [h:9310[ٱ]لْكَر[p[ِي]مِ","Бас, ҳақ подшоҳ Аллоҳ юксакдир. Ҳеч бир илоҳ йўқ. Магар у–карамли Аршнинг Робби бор.",349,18],["وَم[a:9311[َن ي]َ[q:9312[دْ]عُ مَعَ [h:3975[ٱ]للَّهِ إِلَ[n[ـٰ]هًا ءَاخَرَ لَا بُرْهَ[n[ـٰ]نَ لَهُ[n[ۥ] بِه[n[ِۦ] فَإِ[g[نّ]َمَا حِسَابُهُ[n[ۥ] عِ[f:264[ند]َ رَبِّه[o[ِۦٓ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] لَا يُفْلِحُ [h:9313[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Ким Аллоҳ билан бирга бошқа илоҳга илтижо қилса, бу хусусда ҳеч бир далили йўқдир. Бас, унинг ҳисоби фақат Роббининг ҳузуридадир. Албатта, кофирлар нажот топмаслар.",349,18],["وَقُ[b:7725[ل] رَّبِّ [h:5032[ٱ]غْفِرْ وَ[h:9314[ٱ]رْحَمْ وَأَ[f:3893[نت]َ خَيْرُ [h:9301[ٱ][l[ل]رّ[n[َٲ]حِم[p[ِي]نَ","Сен: «Эй Роббим, мағфират қил, раҳм қил. Ўзинг раҳм қилгувчиларнинг яхшисисан», деб айт.",349,18]]},{"n":24,"ar":"النُّورِ","en":"An-Noor","uz":"Нур","type":"Мадина","ayahs":[["سُورَةٌ أَ[f:9315[نز]َلْنَ[n[ـٰ]هَا وَفَرَضْنَ[n[ـٰ]هَا وَأَ[f:271[نز]َلْنَا فِيه[o[َآ] ءَايَ[n[ـٰ][i:516[تِۭ ب]َيِّنَ[n[ـٰ][u:9316[تٍ ل]َّعَلَّكُمْ تَذَكَّر[p[ُو]نَ","сурадир. Биз уни нозил қилдик. Биз уни фарз қилдик. Биз унда очиқ-ойдин оятларни нозил қилдик. Шоядки эсласангиз.",350,18],["ٱ[l[ل]زَّانِيَةُ وَ[h:9317[ٱ][l[ل]زَّانِى فَ[h:9318[ٱ][q:9318[جْ]لِدُو[s[اْ] كُلَّ و[n[َٲ]حِ[a:2592[دٍ م]ِّنْهُمَا مِ[s[اْ]ئَةَ جَلْدَ[a:9319[ةٍ‌ۖ و]َلَا تَأْخُذْك[c:9320[ُم ب]ِهِمَا رَأْفَ[f:9321[ةٌ ف]ِى دِينِ [h:2072[ٱ]للَّهِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ‌ۖ وَلْيَشْهَ[q:9322[دْ] عَذَابَهُمَا ط[o[َا]ٓئِفَ[a:9323[ةٌ م]ِّنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Зинокор аёл ва зинокор эркак, икковларидан ҳар бирини юз даррадан уринг. Агар сиз Аллоҳга ва охират кунига иймон келтирадиган бўлсангиз, сизларни уларга нисбатан Аллоҳнинг динида шафқат тутмасин. Ва уларнинг азобига бир тоифа мўминлар гувоҳ бўлсинлар.",350,18],["ٱ[l[ل]زَّانِى لَا يَ[f:9324[نك]ِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَ[a:9325[ةً و]َ[h:9326[ٱ][l[ل]زَّانِيَةُ لَا يَ[f:9327[نك]ِحُه[o[َآ] إِلَّا زَانٍ أَوْ مُشْرِ[a:9328[كٌ‌ۚ و]َحُرِّمَ ذ[n[َٲ]لِكَ عَلَى [h:2329[ٱ]لْمُؤْمِن[p[ِي]نَ","Зинокор эркак фақат зинокор ёки мушрика аёлга никоҳланур. Зинокор аёлга фақат зинокор ёки мушрик эркак никоҳланур. Бу мўминларга ҳаром қилинмишдир.",350,18],["وَ[h:9999[ٱ]لَّذِينَ يَرْمُونَ [h:9329[ٱ]لْمُحْصَنَ[n[ـٰ]تِ ثُ[g[مّ]َ لَمْ يَأْتُو[s[اْ] بِأَرْبَعَةِ شُهَد[o[َا]ٓءَ فَ[h:9330[ٱ][q:9330[جْ]لِدُوهُمْ ثَمَ[n[ـٰ]نِينَ جَلْدَ[a:9331[ةً و]َلَا تَ[q:9332[قْ]بَلُو[s[اْ] لَهُمْ شَهَ[n[ـٰ]دَةً أَبَ[a:9333[دًا‌ۚ و]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:2071[ٱ]لْفَ[n[ـٰ]سِق[p[ُو]نَ","Покиза аёлларга тоши отиб, сўнгра тўртта гувоҳ келтира олмаганларни саксон дарра уринглар ва уларнинг гувоҳлигини абадий қабул қилманглар. Ана ўшалар фосиқлардир.",350,18],["إِلَّا [h:778[ٱ]لَّذِينَ تَابُو[s[اْ] م[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ وَأَصْلَحُو[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Магар бундан кейин тавба қилиб, ўзини ислоҳ қилганлар. Зеро, Аллоҳ ўта мағфиратли ва ўта раҳмлидир.",350,18],["وَ[h:9999[ٱ]لَّذِينَ يَرْمُونَ أَزْو[n[َٲ]جَهُمْ وَلَمْ يَك[u:9334[ُن ل]َّهُمْ شُهَد[o[َا]ٓءُ إِلّ[o[َآ] أَ[f:2341[نف]ُسُهُمْ فَشَهَ[n[ـٰ]دَةُ أَحَدِهِمْ أَرْبَعُ شَهَ[n[ـٰ]د[n[َٲ][i:9335[تِۭ ب]ِ[h:32[ٱ]للَّهِ‌ۙ إِ[g[نّ]َهُ[n[ۥ] لَمِنَ [h:6711[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","Ўз жуфтларига тоши отиб, фақат ўзларидан бошқа гувоҳлари бўлмаганлар эса, бас, улардан ҳар бирининг гувоҳлиги Аллоҳнинг номи ила тўрт марта, албатта, у ростгўйлардан эканлиги ҳақида шоҳидлик беришдир.",350,18],["وَ[h:9999[ٱ]لْخَ[n[ـٰ]مِسَةُ أَ[g[نّ]َ لَعْنَتَ [h:1982[ٱ]للَّهِ عَلَيْهِ إِ[f:2594[ن ك]َانَ مِنَ [h:4785[ٱ]لْكَ[n[ـٰ]ذِب[p[ِي]نَ","Бешинчисида эса, агар ёлғончилардан бўлса, унга Аллоҳнинг лаънати бўлишини.",350,18],["وَيَ[q:9336[دْ]رَؤُ[s[اْ] عَنْهَا [h:9337[ٱ]لْعَذَابَ أَ[f:9338[ن ت]َشْهَدَ أَرْبَعَ شَهَ[n[ـٰ]د[n[َٲ][i:9335[تِۭ ب]ِ[h:32[ٱ]للَّهِ‌ۙ إِ[g[نّ]َهُ[n[ۥ] لَمِنَ [h:9339[ٱ]لْكَ[n[ـٰ]ذِب[p[ِي]نَ","Ва удан азобни қайтарадиган нарса, Аллоҳнинг номи ила тўрт марта, албатта, у ёлғончилардандир, деб шоҳидлик беришидир.",350,18],["وَ[h:9999[ٱ]لْخَ[n[ـٰ]مِسَةَ أَ[g[نّ]َ غَضَبَ [h:9340[ٱ]للَّهِ عَلَيْه[o[َآ] إِ[f:2594[ن ك]َانَ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","Бешинчисида эса, агар у ростгўйлардан бўлса, ўзига Аллоҳнинг ғазаби бўлишини.",350,18],["وَلَوْلَا فَضْلُ [h:337[ٱ]للَّهِ عَلَيْكُمْ وَرَحْمَتُهُ[n[ۥ] وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ تَوَّابٌ حَك[p[ِي]مٌ","Агар сизларга Аллоҳнинг фазли ва марҳамати бўлмаганида!.. Албатта, Аллоҳ тавбаларни кўплаб қабул қилгувчи ва ўта ҳикматли зот бўлмаганида эди!..",350,18],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ج[o[َا]ٓءُو بِ[h:9341[ٱ]لْإِفْكِ عُصْبَ[a:9342[ةٌ م]ِّ[f:344[نك]ُمْ‌ۚ لَا تَحْسَبُوهُ شَر[u:9343[ًّا ل]َّك[c:9344[ُم‌ۖ ب]َلْ هُوَ خَيْ[u:263[رٌ ل]َّكُمْ‌ۚ لِكُلِّ [h:9345[ٱ]مْرِى[a:9346[ٍٕ م]ِّنْه[w:3670[ُم م]َّا [h:9347[ٱ]كْتَسَبَ مِنَ [h:9348[ٱ]لْإِثْمِ‌ۚ وَ[h:4765[ٱ]لَّذِى تَوَلَّىٰ كِ[q:9349[بْ]رَهُ[n[ۥ] مِنْهُمْ لَهُ[n[ۥ] عَذَابٌ عَظ[p[ِي]مٌ","Албатта, ифкни келтирганлар ўзингиздан бўлган бир тўдадир. Уни ўзингизга ёмонлик деб ҳисобламанг. Аксинча, у сиз учун яхшиликдир. Улардан ҳар бир киши учун ўзи қилган касбнинг гуноҳи бордир. Улардан каттасини кўтарган кимсага буюк азоб бордир.",351,18],["لَّوْل[o[َآ] إِذْ سَمِعْتُمُوهُ ظَ[g[نّ]َ [h:9350[ٱ]لْمُؤْمِنُونَ وَ[h:5714[ٱ]لْمُؤْمِنَ[n[ـٰ]تُ بِأَ[f:4384[نف]ُسِهِمْ خَيْ[a:9351[رًا و]َقَالُو[s[اْ] هَ[n[ـٰ]ذ[o[َآ] إِفْ[a:9352[كٌ م]ُّب[p[ِي]نٌ","Уни эшитган вақтингизда мўминлар ва мўминалар ўзлари ҳақида яхши гумонга бориб: «Бу очиқ-ойдин ифк-ку!» десалар бўлмасмиди?!",351,18],["لَّوْلَا ج[o[َا]ٓءُو عَلَيْهِ بِأَرْبَعَةِ شُهَد[o[َا]ٓءَ‌ۚ فَإِذْ لَمْ يَأْتُو[s[اْ] بِ[h:9353[ٱ][l[ل]شُّهَد[o[َا]ٓءِ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ هُمُ [h:7594[ٱ]لْكَ[n[ـٰ]ذِب[p[ُو]نَ","Улар ўшага тўртта гувоҳ келтирсалар бўлмасмиди?! Бас, гувоҳларни келтира олмаган чоғда ана ўшалар ўзлари Аллоҳнинг ҳузурида ёлғончидирлар.",351,18],["وَلَوْلَا فَضْلُ [h:337[ٱ]للَّهِ عَلَيْكُمْ وَرَحْمَتُهُ[n[ۥ] فِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ لَمَسَّكُمْ فِى م[o[َآ] أَفَضْتُمْ فِيهِ عَذَابٌ عَظ[p[ِي]مٌ","Агар дунёю охиратда сизларга Аллоҳнинг фазли, марҳамати бўлмаганида, ўзингиз ичига шўнғиган нарса учун сизни, албатта, буюк азоб тутар эди.",351,18],["إِذْ تَلَقَّوْنَهُ[n[ۥ] بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِك[w:9354[ُم م]َّا لَيْسَ لَك[c:2000[ُم ب]ِه[n[ِۦ] عِلْ[a:9355[مٌ و]َتَحْسَبُونَهُ[n[ۥ] هَيِّ[a:9356[نًا و]َهُوَ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ عَظ[p[ِي]مٌ","Ўшанда сиз уни тилларингиз ила илиб олар, оғзингиз ила ўзингиз билмаган нарсани гапирар эдингиз ва уни ўзингизга енгил санардингиз. Ҳолбуки, у Аллоҳнинг наздида буюкдир.",351,18],["وَلَوْل[o[َآ] إِذْ سَمِعْتُمُوهُ قُلْت[w:9357[ُم م]َّا يَكُونُ لَن[o[َآ] أ[a:9358[َن ن]َّتَكَلَّمَ بِهَ[n[ـٰ]ذَا سُ[q:168[بْ]حَ[n[ـٰ]نَكَ هَ[n[ـٰ]ذَا بُهْتَ[n[ـٰ]نٌ عَظ[p[ِي]مٌ","Уни эшитган чоғингизда: «Бизга буни гапирмоғимиз тўғри келмайди. Сен, Ўзинг поксан! Бу катта бўҳтондир! « десангиз бўлмасмиди?!",351,18],["يَعِظُكُمُ [h:9359[ٱ]للَّهُ أَ[f:9360[ن ت]َعُودُو[s[اْ] لِمِثْلِه[o[ِۦٓ] أَبَدًا إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Агар мўмин бўлсангиз, ҳаргиз уга ўхшаш нарсага қайтмаслигингизни Аллоҳ сизга ваъз-насиҳат қилур.",351,18],["وَيُبَيِّنُ [h:9361[ٱ]للَّهُ لَكُمُ [h:1221[ٱ]لْأَيَ[n[ـٰ]تِ‌ۚ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Аллоҳ сизга оятларни баён қилур. Ва Аллоҳ ўта билгувчи, ўта ҳикматли зотдир.",351,18],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يُحِبُّونَ أَ[f:9362[ن ت]َشِيعَ [h:9363[ٱ]لْفَ[n[ـٰ]حِشَةُ فِى [h:6320[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَهُمْ عَذَابٌ أَلِي[f:9364[مٌ ف]ِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ‌ۚ وَ[h:72[ٱ]للَّهُ يَعْلَمُ وَأَ[f:98[نت]ُمْ لَا تَعْلَم[p[ُو]نَ","Албатта, иймон келтирганлар ичида фоҳиша тарқалишини яхши кўрадиганларга бу дунёю охиратда аламли азоб бордир. Аллоҳ биладир, сизлар билмассизлар.",351,18],["وَلَوْلَا فَضْلُ [h:337[ٱ]للَّهِ عَلَيْكُمْ وَرَحْمَتُهُ[n[ۥ] وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ رَءُو[u:5881[فٌ ر]َّح[p[ِي]مٌ","Агар сизларга Аллоҳнинг фазли, марҳамати бўлмаганида... Ва, албатта, Аллоҳ ўта шафқатли ва раҳмли бўлмаганида...",351,18],["۞ يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَتَّبِعُو[s[اْ] خُطُو[n[َٲ]تِ [h:872[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ‌ۚ وَم[a:9365[َن ي]َتَّبِعْ خُطُو[n[َٲ]تِ [h:872[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ فَإِ[g[نّ]َهُ[n[ۥ] يَأْمُرُ بِ[h:1587[ٱ]لْفَحْش[o[َا]ٓءِ وَ[h:7554[ٱ]لْمُ[f:7554[نك]َرِ‌ۚ وَلَوْلَا فَضْلُ [h:337[ٱ]للَّهِ عَلَيْكُمْ وَرَحْمَتُهُ[n[ۥ] مَا زَكَىٰ مِ[f:344[نك][w:431[ُم م]ِّنْ أَحَدٍ أَبَ[a:9366[دًا و]َلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ يُزَكِّى م[a:476[َن ي]َش[o[َا]ٓءُ‌ۗ وَ[h:72[ٱ]للَّهُ سَمِيعٌ عَل[p[ِي]مٌ","Эй иймон келтирганлар! Шайтоннинг изидан эргашманг. Ким шайтоннинг изидан эргашса, бас, албатта, у фоҳиша ва мункарга буюради. Агар сизларга Аллоҳнинг фазли ва марҳамати бўлмаганида абадул-абад ичингиздан бирор киши поклана олмас эди. Лекин Аллоҳ Ўзи хохлаган кишини поклайдир. Аллоҳ ўта эшитгувчи, ўта билгувчи зотдир.",352,18],["وَلَا يَأْتَلِ أُ[s[وْ]لُو[s[اْ] [h:9367[ٱ]لْفَضْلِ مِ[f:344[نك]ُمْ وَ[h:9368[ٱ][l[ل]سَّعَةِ أ[a:9369[َن ي]ُؤْت[o[ُوٓ][s[اْ] أُ[s[وْ]لِى [h:9370[ٱ]لْقُرْبَىٰ وَ[h:910[ٱ]لْمَسَ[n[ـٰ]كِينَ وَ[h:5876[ٱ]لْمُهَ[n[ـٰ]جِرِينَ فِى سَبِيلِ [h:788[ٱ]للَّهِ‌ۖ وَلْيَعْفُو[s[اْ] وَلْيَصْفَح[o[ُوٓ[s[اْ]‌ۗ] أَلَا تُحِبُّونَ أ[a:9371[َن ي]َغْفِرَ [h:5741[ٱ]للَّهُ لَكُمْ‌ۗ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Сизлардан фазл ва бойлик эгаси бўлганлар қариндошларга, мискинларга ва Аллоҳнинг йўлида муҳожир бўлганларга бермасликка қасам ичмасинлар, бас, авф этсинлар, ўтиб юборсинлар. Аллоҳ сизларни мағфират қилишини хуш кўрмайсизларми?! Аллоҳ ўта мағфиратли, ўта раҳмли зотдир».",352,18],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَرْمُونَ [h:9329[ٱ]لْمُحْصَنَ[n[ـٰ]تِ [h:9372[ٱ]لْغَ[n[ـٰ]فِلَ[n[ـٰ]تِ [h:9373[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ لُعِنُو[s[اْ] فِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ وَلَهُمْ عَذَابٌ عَظ[p[ِي]مٌ","Албатта, покиза, ғофила ва мўмина аёлларга тоши отганлар, бу дунёю охиратда лаънатланурлар. Уларга катта азоб бордур.",352,18],["يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُه[c:9374[ُم ب]ِمَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","У кунда тиллари, қўллари ва оёқлари қилиб юрган амаллари ҳақида уларга қарши гувоҳлик берур.",352,18],["يَوْمَئِ[a:9375[ذٍ ي]ُوَفِّيهِمُ [h:9376[ٱ]للَّهُ دِينَهُمُ [h:9377[ٱ]لْحَقَّ وَيَعْلَمُونَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ هُوَ [h:8923[ٱ]لْحَقُّ [h:9378[ٱ]لْمُب[p[ِي]نُ","Ўша кунда Аллоҳ уларнинг ҳақ жазоларини тўлиқ берур ва улар Аллоҳнинг Ўзи очиқ ҳақ эканини билурлар.",352,18],["ٱلْخَبِيثَ[n[ـٰ]تُ لِلْخَبِيثِينَ وَ[h:9379[ٱ]لْخَبِيثُونَ لِلْخَبِيثَ[n[ـٰ]تِ‌ۖ وَ[h:9380[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تُ لِلطَّيِّبِينَ وَ[h:9381[ٱ][l[ل]طَّيِّبُونَ لِلطَّيِّبَ[n[ـٰ]تِ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مُبَرَّءُونَ مِ[g[مّ]َا يَقُولُونَ‌ۖ لَه[w:3412[ُم م]َّغْفِرَ[a:5445[ةٌ و]َرِزْ[f:5239[قٌ ك]َر[p[ِي]مٌ","Нопок хотинлар нопок эркаклар учундир. Нопок эркаклар нопок хотинлар учундир. Покиза аёллар покиза эркаклар учундир. Покиза эркаклар покиза аёллар учундир. Ана ўшалар у лар айтаётган нарсалардан поклангандирлар. Уларга мағфират ва гўзал ризқ бордир.",352,18],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَ[q:1176[دْ]خُلُو[s[اْ] بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُو[s[اْ] وَتُسَلِّمُو[s[اْ] عَلَ[o[ىٰٓ] أَهْلِهَا‌ۚ ذ[n[َٲ]لِكُمْ خَيْ[u:263[رٌ ل]َّكُمْ لَعَلَّكُمْ تَذَكَّر[p[ُو]نَ","Эй иймон келтирганлар! Ўз уйларингиздан бошқа уйларга то изн сўрамагунингизча ва уларнинг аҳлига салом бермагунингизча, кирманг. Ана шундай қилмоғингиз сиз учун яхшидир, шоядки эсласангиз.",352,18],["فَإ[u:110[ِن ل]َّمْ تَجِدُو[s[اْ] فِيه[o[َآ] أَحَ[f:9382[دًا ف]َلَا تَ[q:9383[دْ]خُلُوهَا حَتَّىٰ يُؤْذَنَ لَكُمْ‌ۖ وَإِ[f:9384[ن ق]ِيلَ لَكُمُ [h:9385[ٱ]رْجِعُو[s[اْ] فَ[h:9386[ٱ]رْجِعُو[s[اْ‌ۖ] هُوَ أَزْكَىٰ لَكُمْ‌ۚ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ عَل[p[ِي]مٌ","Бас, агар уларда бирортани топмасангиз, то сизга изн берилмагунча уларга кирманг. Агар сизга, қайтинг, дейилса, бас, қайтинг, ўша сиз учун покдир. Аллоҳ нима амал қилаётганингизни ўта билгувчидир.",353,18],["لَّيْسَ عَلَيْكُمْ جُنَاحٌ أَ[f:1175[ن ت]َ[q:1176[دْ]خُلُو[s[اْ] بُيُوتًا غَيْرَ مَسْكُونَ[f:9387[ةٍ ف]ِيهَا مَتَ[n[ـٰ][u:9388[عٌ ل]َّكُمْ‌ۚ وَ[h:72[ٱ]للَّهُ يَعْلَمُ مَا تُ[q:178[بْ]دُونَ وَمَا تَكْتُم[p[ُو]نَ","Маскан бўлмаган, сиз учун фойда бор уйларга киришингизда гуноҳ йўқдир. Аллоҳ нимани ошкор қилаётганингизни ва нимани яширин қилаётганингизни билади.",353,18],["قُل لِّلْمُؤْمِنِينَ يَغُضُّو[s[اْ] مِنْ أَ[q:28[بْ]صَ[n[ـٰ]رِهِمْ وَيَحْفَظُو[s[اْ] فُرُوجَهُمْ‌ۚ ذ[n[َٲ]لِكَ أَزْكَىٰ لَهُمْ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ خَبِي[i:2335[رُۢ ب]ِمَا يَصْنَع[p[ُو]نَ","Сен мўминларга айт, кўзларини тийсинлар ва фаржларини сақласинлар. Ана шу улар учун покдир. Албатта, Аллоҳ нима ҳунар қилаётганларидан хабардордир.",353,18],["وَقُل لِّلْمُؤْمِنَ[n[ـٰ]تِ يَغْضُضْنَ مِنْ أَ[q:9389[بْ]صَ[n[ـٰ]رِهِ[g[نّ]َ وَيَحْفَظْنَ فُرُوجَهُ[g[نّ]َ وَلَا يُ[q:9390[بْ]دِينَ زِينَتَهُ[g[نّ]َ إِلَّا مَا ظَهَرَ مِنْهَا‌ۖ وَلْيَضْرِ[q:9391[بْ]نَ بِخُمُرِهِ[g[نّ]َ عَلَىٰ جُيُوبِهِ[g[نّ]َ‌ۖ وَلَا يُ[q:9390[بْ]دِينَ زِينَتَهُ[g[نّ]َ إِلَّا لِبُعُولَتِهِ[g[نّ]َ أَوْ ءَاب[o[َا]ٓئِهِ[g[نّ]َ أَوْ ءَاب[o[َا]ٓءِ بُعُولَتِهِ[g[نّ]َ أَوْ أَ[q:9392[بْ]ن[o[َا]ٓئِهِ[g[نّ]َ أَوْ أَ[q:9393[بْ]ن[o[َا]ٓءِ بُعُولَتِهِ[g[نّ]َ أَوْ إِخْو[n[َٲ]نِهِ[g[نّ]َ أَوْ بَن[o[ِىٓ] إِخْو[n[َٲ]نِهِ[g[نّ]َ أَوْ بَن[o[ِىٓ] أَخَو[n[َٲ]تِهِ[g[نّ]َ أَوْ نِس[o[َا]ٓئِهِ[g[نّ]َ أَوْ مَا مَلَكَتْ أَيْمَ[n[ـٰ]نُهُ[g[نّ]َ أَوِ [h:9394[ٱ][l[ل]تَّ[n[ـٰ]بِعِينَ غَيْرِ أُ[s[وْ]لِى [h:9395[ٱ]لْإِرْبَةِ مِنَ [h:2923[ٱ][l[ل]رِّجَالِ أَوِ [h:9396[ٱ][l[ل]طِّفْلِ [h:9397[ٱ]لَّذِينَ لَمْ يَظْهَرُو[s[اْ] عَلَىٰ عَوْر[n[َٲ]تِ [h:9398[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ‌ۖ وَلَا يَضْرِ[q:9399[بْ]نَ بِأَرْجُلِهِ[g[نّ]َ لِيُعْلَمَ مَا يُخْفِينَ مِ[f:9400[ن ز]ِينَتِهِ[g[نّ]َ‌ۚ وَتُوب[o[ُوٓ][s[اْ] إِلَى [h:1637[ٱ]للَّهِ جَمِيعًا أَيُّهَ [h:9401[ٱ]لْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِح[p[ُو]نَ","Сен мўминаларга айт: Кўзларини тийсинлар, фаржларини сақласинлар ва зийнатларини кўрсатмасинлар, магар зоҳир бўлган зийнатлар бўлса. Рўмолларини кўксиларига тўсиб юрсинлар. Зийнатларини кўрсатмасинлар, магар эрларига ё оталарига ё эрларининг оталарига ё ўғилларига ё эрларининг ўғилларига ё ака-укаларига ё ака-укаларининг ўғилларига ё опа-сингилларининг ўғилларига ё аёлларига ё ўз қўлларида мулк бўлганларга ё беҳожат эркак хизматчиларга ё аёллар авратининг фарқига бормаган ёш болаларга. Махфий зийнатларини билдириш учун оёқларини урмасинлар. Аллоҳга барчангиз тавба қилинг, эй мўминлар! Шоядки, нажот топсангизлар».",353,18],["وَأَ[f:9402[نك]ِحُو[s[اْ] [h:9403[ٱ]لْأَيَ[n[ـٰ]مَىٰ مِ[f:344[نك]ُمْ وَ[h:2905[ٱ][l[ل]صَّ[n[ـٰ]لِحِينَ مِنْ عِبَادِكُمْ وَإِم[o[َا]ٓئِكُمْ‌ۚ إ[a:9404[ِن ي]َكُونُو[s[اْ] فُقَر[o[َا]ٓءَ يُغْنِهِمُ [h:9405[ٱ]للَّهُ مِ[f:475[ن ف]َضْلِه[n[ِۦ]‌ۗ وَ[h:72[ٱ]للَّهُ و[n[َٲ]سِعٌ عَل[p[ِي]مٌ","Ораларингиздаги никоҳсизларни ва қулу чўриларингиздан солиҳларини никоҳлаб қўйинг. Агар фақир бўлсалар, Аллоҳ уларни Ўз фазлидан бой қилур. Аллоҳ кенг, ўта билгувчи зотдир.",354,18],["وَلْيَسْتَعْفِفِ [h:9406[ٱ]لَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغْنِيَهُمُ [h:9407[ٱ]للَّهُ مِ[f:475[ن ف]َضْلِه[n[ِۦ]‌ۗ وَ[h:37[ٱ]لَّذِينَ يَ[q:3357[بْ]تَغُونَ [h:9408[ٱ]لْكِتَ[n[ـٰ]بَ مِ[g[مّ]َا مَلَكَتْ أَيْمَ[n[ـٰ]نُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْ[a:9409[رًا‌ۖ و]َءَاتُوه[w:9410[ُم م]ّ[a:9411[ِن م]َّالِ [h:9412[ٱ]للَّهِ [h:9413[ٱ]لَّذ[o[ِىٓ] ءَاتَ[n[ـٰ]كُمْ‌ۚ وَلَا تُكْرِهُو[s[اْ] فَتَيَ[n[ـٰ]تِكُمْ عَلَى [h:9414[ٱ]لْبِغ[o[َا]ٓءِ إِنْ أَرَ[q:9415[دْ]نَ تَحَصُّ[u:9416[نًا ل]ِّتَ[q:7694[بْ]تَغُو[s[اْ] عَرَضَ [h:3041[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۚ وَم[a:9417[َن ي]ُكْرِههُّ[g[نّ]َ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ م[i:146[ِنۢ ب]َعْدِ إِكْر[n[َٲ]هِهِ[g[نّ]َ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Никоҳ ни топа олмаганлар, то Аллоҳ уларни Ўз фазлидан бой қилгунича иффатларини сақласинлар. Қўлларингизда мулк бўлганлардан васиқасини истайдиганлари бўлса, бас, уларда яхшилик борлигини билсангиз, улар ила васиқа ёзинг ва Аллоҳнинг сизга берган молидан уларга беринг. Ҳаёти дунёнинг ўткинчи матоҳини истаб, покликни ирода қилган чўриларингизни фоҳишаликка мажбур қилманг. Ким уларни мажбур қилган бўлса, бас, албатта, Аллоҳ улар мажбур қилганларидан кейин ўта мағфиратли ва раҳмли зотдир.",354,18],["وَلَقَ[q:341[دْ] أَ[f:515[نز]َلْن[o[َآ] إِلَيْكُمْ ءَايَ[n[ـٰ][a:9418[تٍ م]ُّبَيِّنَ[n[ـٰ][a:9419[تٍ و]َمَثَل[a:9420[اً م]ِّنَ [h:523[ٱ]لَّذِينَ خَلَوْ[s[اْ] مِ[f:85[ن ق]َ[q:86[بْ]لِكُمْ وَمَوْعِظَ[u:348[ةً ل]ِّلْمُتَّق[p[ِي]نَ","Батаҳқиқ, Биз сизларга очиқ-ойдин оятларни, сиздан олдин ўтганлардан мисолни ва тақводорлар учун ваъзни нозил қилдик.",354,18],["۞ ٱللَّهُ نُورُ [h:9421[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ مَثَلُ نُورِه[n[ِۦ] كَمِشْكَ[s[و][n[ٲ][f:9422[ةٍ ف]ِيهَا مِصْبَاحٌ‌ۖ [h:9423[ٱ]لْمِصْبَاحُ فِى زُجَاجَةٍ‌ۖ [h:9424[ٱ][l[ل]زُّجَاجَةُ كَأَ[g[نّ]َهَا كَوْكَ[f:9425[بٌ د]ُرِّ[a:9426[ىٌّ ي]ُوقَدُ مِ[f:9427[ن ش]َجَرَ[a:9428[ةٍ م]ُّبَ[n[ـٰ]رَكَ[f:9429[ةٍ ز]َيْتُونَ[u:9430[ةٍ ل]َّا شَرْقِيَّ[a:9431[ةٍ و]َلَا غَرْبِيَّ[a:9432[ةٍ ي]َكَادُ زَيْتُهَا يُض[o[ِى]ٓءُ وَلَوْ لَمْ تَمْسَسْهُ نَا[a:9433[رٌ‌ۚ ن]ُّورٌ عَلَىٰ نُو[a:9434[رٍ‌ۗ ي]َهْدِى [h:2084[ٱ]للَّهُ لِنُورِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَيَضْرِبُ [h:7110[ٱ]للَّهُ [h:6948[ٱ]لْأَمْثَ[n[ـٰ]لَ لِل[g[نّ]َاسِ‌ۗ وَ[h:72[ٱ]للَّهُ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","Аллоҳ осмонлар ва ернинг нуридир. Унинг нурининг мисоли худди бир токча, унинг ичига чироқ қўйилган, чироқ эса, шиша ичида, шиша эса, гўё дурдан бўлган бир юлдуз бўлиб, шарқий ҳам, ғарбий ҳам бўлмаган муборак зайтун дарахтидан ёқилур. Унинг мойи ўзига олов тегмаса ҳам, ёритиб юборай дейдир. нур устига нурдир. Аллоҳ хоҳлаган одамни Ўз нурига ҳидоят қилур. Аллоҳ одамларга мисолларни келтирур. Аллоҳ ҳар бир нарсани ўта билгувчидир.",354,18],["فِى بُيُوتٍ أَذِنَ [h:9435[ٱ]للَّهُ أَ[f:9436[ن ت]ُرْفَعَ وَيُذْكَرَ فِيهَا [h:596[ٱ]سْمُهُ[n[ۥ] يُسَبِّحُ لَهُ[n[ۥ] فِيهَا بِ[h:5225[ٱ]لْغُدُوِّ وَ[h:5226[ٱ]لْأَص[p[َا]لِ","бир уйлардаки, Аллоҳ уларнинг кўтарилишига ва уларда Ўз исми зикр қилинишига изн бергандир. Уларда Унга эртаю кеч тасбиҳ айтурлар;",354,18],["رِجَا[u:9437[لٌ ل]َّا تُلْهِيهِمْ تِجَ[n[ـٰ]رَ[a:9438[ةٌ و]َلَا بَيْعٌ عَ[f:3773[ن ذ]ِكْرِ [h:3774[ٱ]للَّهِ وَإِقَامِ [h:9439[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةِ وَإِيت[o[َا]ٓءِ [h:9440[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةِ‌ۙ يَخَافُونَ يَوْ[f:9441[مًا ت]َتَقَلَّبُ فِيهِ [h:9442[ٱ]لْقُلُوبُ وَ[h:9443[ٱ]لْأَ[q:9443[بْ]صَ[p[ـٰ]رُ","Бир кишиларки, уларни тижорат ҳам, олди-сотди ҳам Аллоҳнинг зикридан, намозни тўкис адо этишдан ва закот беришдан машғул қила олмас. Улар қалблар ва кўзлар изтиробга тушадиган кундан қўрқарлар.",355,18],["لِيَ[q:5903[جْ]زِيَهُمُ [h:5904[ٱ]للَّهُ أَحْسَنَ مَا عَمِلُو[s[اْ] وَيَزِيدَه[w:9444[ُم م]ِّ[f:475[ن ف]َضْلِه[n[ِۦ]‌ۗ وَ[h:72[ٱ]للَّهُ يَرْزُقُ م[a:476[َن ي]َش[o[َا]ٓءُ بِغَيْرِ حِس[p[َا][q[ب]ٍ","Аллоҳ уларни қилган амалларининг энг гўзали ила мукофотлаши ва фазли карамидан зиёда қилиб бериши учундир. Аллоҳ хоҳлаган кишига беҳисоб ризқ берур.",355,18],["وَ[h:9999[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أَعْمَ[n[ـٰ]لُهُمْ كَسَرَا[i:9445[بِۭ ب]ِقِيعَ[a:9446[ةٍ ي]َحْسَبُهُ [h:9447[ٱ][l[ل]ظَّمْـَٔـانُ م[o[َا]ٓءً حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءَهُ[n[ۥ] لَمْ يَجِ[q:9448[دْ]هُ شَيْـ[a:9449[ـًٔا و]َوَجَدَ [h:9450[ٱ]للَّهَ عِ[f:719[ند]َهُ[n[ۥ] فَوَفَّ[n[ـٰ]هُ حِسَابَهُ[n[ۥ]‌ۗ وَ[h:72[ٱ]للَّهُ سَرِيعُ [h:1112[ٱ]لْحِس[p[َا][q[ب]ِ","Куфр келтирганларнинг амаллари саҳродаги саробга ўхшайдир. Чанқоқ одам уни сув деб ҳисоблайдир. Қачонки, унинг олдига келса, ҳеч нарсани топмас. Ва у олдида Аллоҳни топур. Бас, У зот унинг ҳисобини тўлиқ қилур. Аллоҳ ўта тез ҳисоб қилгувчидир.",355,18],["أَوْ كَظُلُمَ[n[ـٰ][f:9451[تٍ ف]ِى بَحْ[u:9452[رٍ ل]ُّجِّ[a:9453[ىٍّ ي]َغْشَ[n[ـٰ]هُ مَوْ[a:9454[جٌ م]ِّ[f:9455[ن ف]َوْقِه[n[ِۦ] مَوْ[a:9454[جٌ م]ِّ[f:9455[ن ف]َوْقِه[n[ِۦ] سَحَا[f:9456[بٌ‌ۚ ظ]ُلُمَ[n[ـٰ][i:9457[تُۢ ب]َعْضُهَا فَوْقَ بَعْضٍ إِذ[o[َآ] أَخْرَجَ يَدَهُ[n[ۥ] لَمْ يَكَ[q:9458[دْ] يَرَ[n[ٮٰ]هَا‌ۗ وَم[u:1416[َن ل]َّمْ يَ[q:9459[جْ]عَلِ [h:9460[ٱ]للَّهُ لَهُ[n[ۥ] نُو[f:9461[رًا ف]َمَا لَهُ[n[ۥ] م[a:9462[ِن ن]ّ[p[ُو]رٍ","Ёки худди қаърсиз денгиздаги зулматларга ўхшайдир. Унинг устидан мавж қоплагандир, унинг ҳам устидан мавж ва уни эса, булут. Бир-бирининг устидаги зулматлардир. У қўлини чиқарса, кўра олмас. Кимгаки Аллоҳ нур бермаса, унинг учун нур бўлмас.",355,18],["أَلَمْ تَرَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ يُسَبِّحُ لَهُ[n[ۥ] مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَ[h:9463[ٱ][l[ل]طَّيْرُ صَ[m[ـٰٓ]فَّ[n[ـٰ][f:9464[تٍ‌ۖ ك]ُ[f:9465[لٌّ ق]َ[q:298[دْ] عَلِمَ صَلَاتَهُ[n[ۥ] وَتَسْبِيحَهُ[n[ۥ]‌ۗ وَ[h:72[ٱ]للَّهُ عَلِي[i:6056[مُۢ ب]ِمَا يَفْعَل[p[ُو]نَ","Аллоҳга осмонлар ва ердаги бор жонзот ва саф тортган ҳолидаги қушлар тасбиҳ айтишини ҳам кўрмайсанми?! Ҳар бири ўз дуоси ва тасбиҳини, батаҳқиқ, билмишдир. Аллоҳ нима амал қилишларини ўта билгувчидир.",355,18],["وَلِلَّهِ مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ وَإِلَى [h:1148[ٱ]للَّهِ [h:1842[ٱ]لْمَص[p[ِي]رُ","Осмонлар ва ернинг мулки Аллоҳникидир ва қайтиш ҳам фақат Аллоҳгадир.",355,18],["أَلَمْ تَرَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ يُزْجِى سَحَا[f:9466[بًا ث]ُ[g[مّ]َ يُؤَلِّفُ بَيْنَهُ[n[ۥ] ثُ[g[مّ]َ يَ[q:9467[جْ]عَلُهُ[n[ۥ] رُكَا[f:9468[مًا ف]َتَرَى [h:9469[ٱ]لْوَ[q:9470[دْ]قَ يَخْرُجُ مِنْ خِلَ[n[ـٰ]لِه[n[ِۦ] وَيُنَزِّلُ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ مِ[f:9471[ن ج]ِبَا[f:9472[لٍ ف]ِيهَا م[i:9473[ِنۢ ب]َرَ[f:9474[دٍ ف]َيُصِيبُ بِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ وَيَصْرِفُهُ[n[ۥ] ع[a:9475[َن م]ّ[a:476[َن ي]َش[o[َا]ٓءُ‌ۖ يَكَادُ سَنَا بَرْقِه[n[ِۦ] يَذْهَبُ بِ[h:9476[ٱ]لْأَ[q:9476[بْ]صَ[p[ـٰ]رِ","Аллоҳ булутларни ҳайдашини, сўнгра бирга тўплашини, сўнгра уйиб қўйишини кўрмаяпсанми?! Бас, унинг орасидан ёмғир чиқаётганини кўрурсан. У зот осмондан, ундаги тоғлардан дўл тушириб, у билан Ўзи хоҳлаган кишиларга мусибат етказур ва уни Ўзи хоҳлаган кишилардан буриб юборур. Унинг чақмоғининг ярқираши кўзларни кетказгудек бўлур.",355,18],["يُقَلِّبُ [h:9477[ٱ]للَّهُ [h:9478[ٱ]لَّيْلَ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَعِ[q:1764[بْ]رَ[u:1765[ةً ل]ِّأُ[s[وْ]لِى [h:1766[ٱ]لْأَ[q:1767[بْ]صَ[p[ـٰ]رِ","Аллоҳ кеча ва кундузни айлантириб турур. Албатта, бунда кўзи борлар учун ибрат бордир.",356,18],["وَ[h:9999[ٱ]للَّهُ خَلَقَ كُلَّ د[m[َا]ٓبَّ[a:9479[ةٍ م]ّ[a:840[ِن م]ّ[o[َا]ٓ[f:9480[ءٍ‌ۖ ف]َمِنْه[w:1456[ُم م]ّ[a:9481[َن ي]َمْشِى عَلَىٰ بَ[q:9482[طْ]نِه[n[ِۦ] وَمِنْه[w:1106[ُم م]ّ[a:9481[َن ي]َمْشِى عَلَىٰ رِ[q:9483[جْ]لَيْنِ وَمِنْه[w:1106[ُم م]ّ[a:9481[َن ي]َمْشِى عَلَ[o[ىٰٓ] أَرْبَ[a:9484[عٍ‌ۚ ي]َخْلُقُ [h:9485[ٱ]للَّهُ مَا يَش[o[َا]ٓءُ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Аллоҳ ҳамма жониворни сувдан яратди. Бас, улардан баъзилари қорни билан юрадир, баъзилари икки оёқ билан юрадир ва баъзилари тўрт билан. Аллоҳ Ўзи хоҳлаган нарсани яратур. Албатта, Аллоҳ ҳар бир нарсага қодирдир.",356,18],["لَّقَ[q:2389[دْ] أَ[f:515[نز]َلْن[o[َآ] ءَايَ[n[ـٰ][a:9418[تٍ م]ُّبَيِّنَ[n[ـٰ][a:9486[تٍ‌ۚ و]َ[h:72[ٱ]للَّهُ يَهْدِى م[a:476[َن ي]َش[o[َا]ٓءُ إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Батаҳқиқ, Биз очиқ-ойдин баён қилгувчи оятларни туширдик. Аллоҳ Ўзи хоҳлаган кимсани тўғри йўлга ҳидоят қиладир.",356,18],["وَيَقُولُونَ ءَامَ[g[نّ]َا بِ[h:32[ٱ]للَّهِ وَبِ[h:9487[ٱ][l[ل]رَّسُولِ وَأَطَعْنَا ثُ[g[مّ]َ يَتَوَلَّىٰ فَرِي[a:388[قٌ م]ِّنْه[w:8433[ُم م]ّ[i:146[ِنۢ ب]َعْدِ ذ[n[َٲ]لِكَ‌ۚ وَم[o[َآ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ بِ[h:3560[ٱ]لْمُؤْمِن[p[ِي]نَ","Улар: «Аллоҳга ва Пайғамбарга иймон келтирдик ва итоат қилдик», дерлар. Сўнгра улардан бир гуруҳи юз ўгириб кетурлар. Ана ўшалар мўмин эмаслар.",356,18],["وَإِذَا دُع[o[ُوٓ][s[اْ] إِلَى [h:1637[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِي[a:388[قٌ م]ِّنْه[w:9488[ُم م]ُّعْرِض[p[ُو]نَ","Уларни қачонки Аллоҳга ва Унинг Пайғамбарига ораларида ҳукм чиқариш учун чорланса, баногоҳ улардан бир гуруҳи юз ўгиргувчилардир.",356,18],["وَإ[a:4454[ِن ي]َك[u:9489[ُن ل]َّهُمُ [h:570[ٱ]لْحَقُّ يَأْت[o[ُوٓ][s[اْ] إِلَيْهِ مُذْعِن[p[ِي]نَ","Агар ҳақ улар бўлса, у га бўйин эгиб келурлар.",356,18],["أَفِى قُلُوبِه[w:39[ِم م]َّرَضٌ أَمِ [h:9490[ٱ]رْتَاب[o[ُوٓ][s[اْ] أَمْ يَخَافُونَ أ[a:9491[َن ي]َحِيفَ [h:9492[ٱ]للَّهُ عَلَيْهِمْ وَرَسُولُهُ[n[ۥ]‌ۚ بَلْ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:1285[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Уларнинг қалбларида мараз борми?! Ёки шубҳа қилдиларми?! Ёхуд Аллоҳ ва Унинг Пайғамбари уларга зулм қилишидан қўрқадиларми?! Йўқ! Уларнинг ўзлари золимлардир.",356,18],["إِ[g[نّ]َمَا كَانَ قَوْلَ [h:9493[ٱ]لْمُؤْمِنِينَ إِذَا دُع[o[ُوٓ][s[اْ] إِلَى [h:1637[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] لِيَحْكُمَ بَيْنَهُمْ أ[a:6263[َن ي]َقُولُو[s[اْ] سَمِعْنَا وَأَطَعْنَا‌ۚ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Албатта, мўминларнинг Аллоҳга ва Унинг Пайғамбарига ораларида ҳукм чиқариш учун чорланганларидаги гаплари: «Эшитдик ва итоат қилдик», демоқларидир. Ана ўшаларнинг ўзларигина нажот топгувчилардир.",356,18],["وَم[a:2629[َن ي]ُطِعِ [h:2630[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] وَيَخْشَ [h:9494[ٱ]للَّهَ وَيَتَّ[q:9495[قْ]هِ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:5510[ٱ]لْف[o[َا]ٓئِز[p[ُو]نَ","Ким Аллоҳга ва Унинг Пайғамбарига итоат этса ҳамда Аллоҳдан қўрқиб, Унга тақво қилса, бас, ана ўшаларгина ютуққа эришгувчилардир.",356,18],["۞ وَأَ[q:4324[قْ]سَمُو[s[اْ] بِ[h:32[ٱ]للَّهِ جَهْدَ أَيْمَ[n[ـٰ]نِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُ[g[نّ]َ‌ۖ قُل لَّا تُ[q:9496[قْ]سِمُو[s[اْ‌ۖ] طَاعَ[a:9497[ةٌ م]َّعْرُوفَةٌ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ خَبِي[i:2335[رُۢ ب]ِمَا تَعْمَل[p[ُو]نَ","Улар агар амр қилсанг, албатта, чиқишлари ҳақида Аллоҳ номи билан жон-жаҳдлари ила қасам ичадилар. Сен: «Қасам ичманглар! маълум тоатдир! Албатта, Аллоҳ нима амал қилаётганларингиздан хабардордир», деб айт.",356,18],["قُلْ أَطِيعُو[s[اْ] [h:1855[ٱ]للَّهَ وَأَطِيعُو[s[اْ] [h:2865[ٱ][l[ل]رَّسُولَ‌ۖ فَإِ[f:1857[ن ت]َوَلَّوْ[s[اْ] فَإِ[g[نّ]َمَا عَلَيْهِ مَا حُ[g[مّ]ِلَ وَعَلَيْك[w:9498[ُم م]َّا حُ[g[مّ]ِلْتُمْ‌ۖ وَإِ[f:9499[ن ت]ُطِيعُوهُ تَهْتَدُو[s[اْ‌ۚ] وَمَا عَلَى [h:3818[ٱ][l[ل]رَّسُولِ إِلَّا [h:3819[ٱ]لْبَلَ[n[ـٰ]غُ [h:3781[ٱ]لْمُب[p[ِي]نُ","Сен: «Аллоҳга итоат қилинглар, Пайғамбарга итоат қилинглар. Бас, агар юз ўгириб кетсангиз, уга ўзига юклатилган нарса, сизга ўзингизга юклатилган нарса. Агар унга итоат қилсангиз, ҳидоят топурсиз. Пайғамбарнинг зиммасида очиқ-ойдин етказишдан бошқа нарса йўқ», деб айт.",357,18],["وَعَدَ [h:3055[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مِ[f:344[نك]ُمْ وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَيَسْتَخْلِفَ[g[نّ]َهُمْ فِى [h:44[ٱ]لْأَرْضِ كَمَا [h:9500[ٱ]سْتَخْلَفَ [h:9501[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ وَلَيُمَكِّنَ[g[نّ]َ لَهُمْ دِينَهُمُ [h:9502[ٱ]لَّذِى [h:9503[ٱ]رْتَضَىٰ لَهُمْ وَلَيُبَدِّلَ[g[نّ]َه[w:9504[ُم م]ّ[i:146[ِنۢ ب]َعْدِ خَوْفِهِمْ أَمْ[a:9505[نًا‌ۚ ي]َعْبُدُونَنِى لَا يُشْرِكُونَ بِى شَيْـ[a:9506[ـًٔا‌ۚ و]َمَ[f:662[ن ك]َفَرَ بَعْدَ ذ[n[َٲ]لِكَ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:2071[ٱ]لْفَ[n[ـٰ]سِق[p[ُو]نَ","Аллоҳ сизлардан иймон келтириб, солиҳ амалларни қилганларга уларни ер юзида худди улардан олдин ўтганларни халифа қилганидек халифа қилишни, улар учун Ўзи рози бўлган динни мустаҳкамлашни ва уларнинг хавф-хатарларидан сўнг омонликни бадал қилиб беришни ваъда қилди. Менгагина ибодат қилурлар ва Менга ҳеч нарсани ширк келтирмаслар. Шундан кейин ҳам ким куфр келтирса, бас, ана ўшалар, ўзлари фосиқлардир.",357,18],["وَأَقِيمُو[s[اْ] [h:214[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتُو[s[اْ] [h:215[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَأَطِيعُو[s[اْ] [h:2865[ٱ][l[ل]رَّسُولَ لَعَلَّكُمْ تُرْحَم[p[ُو]نَ","Намозни тўкис адо этинглар, закот беринглар ва Пайғамбарга итоат қилинглар. Шоядки раҳм қилсангиз.",357,18],["لَا تَحْسَبَ[g[نّ]َ [h:2409[ٱ]لَّذِينَ كَفَرُو[s[اْ] مُعْجِزِينَ فِى [h:44[ٱ]لْأَرْضِ‌ۚ وَمَأْوَ[n[ٮٰ]هُمُ [h:2315[ٱ][l[ل][g[نّ]َارُ‌ۖ وَلَبِئْسَ [h:9507[ٱ]لْمَص[p[ِي]رُ","Сен куфр келтирганларни ер юзида қочиб қутула олгувчилардир, деб ҳисоблама! Уларнинг жойи дўзахдир. У нақадар ёмон борар жойдир!",357,18],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لِيَسْتَــْٔذِ[f:9508[نك]ُمُ [h:9509[ٱ]لَّذِينَ مَلَكَتْ أَيْمَ[n[ـٰ]نُكُمْ وَ[h:37[ٱ]لَّذِينَ لَمْ يَ[q:9510[بْ]لُغُو[s[اْ] [h:9511[ٱ]لْحُلُمَ مِ[f:344[نك]ُمْ ثَلَ[n[ـٰ]ثَ مَرّ[n[َٲ][a:9512[تٍ‌ۚ م]ِّ[f:1346[ن ق]َ[q:1347[بْ]لِ صَلَ[s[و][n[ٲ]ةِ [h:9513[ٱ]لْفَ[q:996[جْ]رِ وَحِينَ تَضَعُونَ ثِيَابَك[w:9514[ُم م]ِّنَ [h:9515[ٱ][l[ل]ظَّهِيرَةِ وَم[i:4943[ِنۢ ب]َعْدِ صَلَ[s[و][n[ٲ]ةِ [h:9516[ٱ]لْعِش[o[َا]ٓءِ‌ۚ ثَلَ[n[ـٰ]ثُ عَوْر[n[َٲ][u:9517[تٍ ل]َّكُمْ‌ۚ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَا[i:9518[حُۢ ب]َعْدَهُ[g[نّ]َ‌ۚ طَوّ[n[َٲ]فُونَ عَلَيْك[c:9519[ُم ب]َعْضُكُمْ عَلَىٰ بَعْ[f:9520[ضٍ‌ۚ ك]َذ[n[َٲ]لِكَ يُبَيِّنُ [h:1002[ٱ]للَّهُ لَكُمُ [h:1221[ٱ]لْأَيَ[n[ـٰ]تِ‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Эй иймон келтирганлар! Қўлингизда мулк бўлганлар ва ўзингиздан балоғатга етмаганлар сиздан уч вақтда изн сўрасинлар: бомдод намозидан олдин, пешинда кийимларингизни ечадиган пайтингизда ва хуфтон намозидан сўнг. уч вақт, сиз учун авратдир. Улардан кейин сизга ҳам, уларга ҳам гуноҳ йўқ. Улар сизнинг атрофингизда, бир-бирингизга айланиб турувчидирсиз. Аллоҳ сизларга оятларни ана шундай баён қилур. Аллоҳ ўта билгувчи, ўта ҳикматли зотдир.",357,18],["وَإِذَا بَلَغَ [h:9521[ٱ]لْأَ[q:9522[طْ]فَ[n[ـٰ]لُ مِ[f:973[نك]ُمُ [h:9523[ٱ]لْحُلُمَ فَلْيَسْتَــْٔذِنُو[s[اْ] كَمَا [h:9524[ٱ]سْتَــْٔذَنَ [h:9525[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ كَذ[n[َٲ]لِكَ يُبَيِّنُ [h:1002[ٱ]للَّهُ لَكُمْ ءَايَ[n[ـٰ]تِه[n[ِۦ]‌ۗ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Қачон сизнинг ёш болаларингиз балоғатга етсалар, улардан олдингилар изн сўраганидек, изн сўрасинлар. Аллоҳ Ўз оятларини сизга ана шундай баён қилур. Аллоҳ ўта билгувчи, ўта ҳикматли зотдир.",358,18],["وَ[h:9999[ٱ]لْقَو[n[َٲ]عِدُ مِنَ [h:1769[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ [h:3168[ٱ]لَّ[n[ـٰ]تِى لَا يَرْجُونَ نِكَا[f:9526[حًا ف]َلَيْسَ عَلَيْهِ[g[نّ]َ جُنَاحٌ أ[a:9527[َن ي]َضَعْنَ ثِيَابَهُ[g[نّ]َ غَيْرَ مُتَبَرِّجَ[n[ـٰ][i:9528[تِۭ ب]ِزِينَ[a:9529[ةٍ‌ۖ و]َأ[a:9530[َن ي]َسْتَعْفِفْنَ خَيْ[u:9531[رٌ ل]َّهُ[g[نّ]َ‌ۗ وَ[h:72[ٱ]للَّهُ سَمِيعٌ عَل[p[ِي]مٌ","Аёллардан ўтириб қолганлари, никоҳни умид қилмайдиганларига зийнатларини кўз-кўз қилмаган ҳолда кийимларини қўйишларида гуноҳ йўқдир. Иффат талабида бўлсалар, ўзлари учун яхшидир. Аллоҳ ўта эшитгувчи, ўта билгувчи зотдир.",358,18],["لَّيْسَ عَلَى [h:9532[ٱ]لْأَعْمَىٰ حَرَ[a:9533[جٌ و]َلَا عَلَى [h:9534[ٱ]لْأَعْرَجِ حَرَ[a:9533[جٌ و]َلَا عَلَى [h:9535[ٱ]لْمَرِيضِ حَرَ[a:9533[جٌ و]َلَا عَلَ[o[ىٰٓ] أَ[f:1329[نف]ُسِكُمْ أَ[f:9536[ن ت]َأْكُلُو[s[اْ] م[i:7523[ِنۢ ب]ُيُوتِكُمْ أَوْ بُيُوتِ ءَاب[o[َا]ٓئِكُمْ أَوْ بُيُوتِ أُ[g[مّ]َهَ[n[ـٰ]تِكُمْ أَوْ بُيُوتِ إِخْو[n[َٲ]نِكُمْ أَوْ بُيُوتِ أَخَو[n[َٲ]تِكُمْ أَوْ بُيُوتِ أَعْمَ[n[ـٰ]مِكُمْ أَوْ بُيُوتِ عَ[g[مّ]َ[n[ـٰ]تِكُمْ أَوْ بُيُوتِ أَخْو[n[َٲ]لِكُمْ أَوْ بُيُوتِ خَ[n[ـٰ]لَ[n[ـٰ]تِكُمْ أَوْ مَا مَلَكْت[w:9537[ُم م]َّفَاتِحَهُ[o[ۥٓ] أَوْ صَدِيقِكُمْ‌ۚ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَ[f:9536[ن ت]َأْكُلُو[s[اْ] جَمِيعًا أَوْ أَشْتَا[f:9538[تًا‌ۚ ف]َإِذَا دَخَلْت[c:9539[ُم ب]ُيُو[f:9540[تًا ف]َسَلِّمُو[s[اْ] عَلَ[o[ىٰٓ] أَ[f:1329[نف]ُسِكُمْ تَحِيَّ[a:9541[ةً م]ِّنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ مُبَ[n[ـٰ]رَكَ[f:9542[ةً ط]َيِّبَ[f:9543[ةً‌ۚ ك]َذ[n[َٲ]لِكَ يُبَيِّنُ [h:1002[ٱ]للَّهُ لَكُمُ [h:1221[ٱ]لْأَيَ[n[ـٰ]تِ لَعَلَّكُمْ تَعْقِل[p[ُو]نَ","Кўзи ожизга гуноҳ-танглик йўқдир. Чўлоққа гуноҳ-танглик йўқдир. Беморга гуноҳ-танглик йўқдир. Сизнинг ўзингизга ҳам ўз уйингиздан ё оталарингизнинг уйларидан ё оналарингизнинг уйларидан ё ака-укаларингизнинг уйларидан ё опа-сингилларингизнинг уйларидан ё амакиларингизнинг уйларидан ё аммаларингизнинг уйларидан ё тоғаларингизнинг уйларидан ё холаларингизнинг уйларидан ё сиз калитига молик бўлган ёки дўстингиз емоқлигингизда йўқдир. Сизларга жамланган ёки тарқоқ ҳолда емоқликда ҳам гуноҳ-танглик йўқдир. Уйларга кирган чоғингизда ўзларингизга Аллоҳдан бўлган покиза ва муборак табрик ила салом беринглар. Аллоҳ сизларга оятларни ана шундай баён қилур. Шоядки ақл юритсангиз.",358,18],["إِ[g[نّ]َمَا [h:5232[ٱ]لْمُؤْمِنُونَ [h:5233[ٱ]لَّذِينَ ءَامَنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] وَإِذَا كَانُو[s[اْ] مَعَهُ[n[ۥ] عَلَ[o[ىٰٓ] أَمْ[f:9544[رٍ ج]َامِ[u:9545[عٍ ل]َّمْ يَذْهَبُو[s[اْ] حَتَّىٰ يَسْتَــْٔذِنُوهُ‌ۚ إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَسْتَــْٔذِنُونَكَ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ يُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ]‌ۚ فَإِذَا [h:9546[ٱ]سْتَــْٔذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذ[u:9547[َن ل]ِّمَ[f:9548[ن ش]ِئْتَ مِنْهُمْ وَ[h:2374[ٱ]سْتَغْفِرْ لَهُمُ [h:9549[ٱ]للَّهَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Албатта, мўминлар Аллоҳга ва Унинг Расулига иймон келтирган кишилардир. Улар у билан бирга жамловчи ишда бўлсалар, ундан изн сўрамасдан туриб кетиб қолмаслар. Албатта, сендан изн сўрайдиганлар, ана ўшалар Аллоҳга ва Унинг Расулига иймон келтирадиганлардир. Улар баъзи ишлари учун сендан изн сўрасалар, улардан кимга хоҳласанг, изн бер ва улар учун Аллоҳга истиғфор айт. Албатта, Аллоҳ ўта мағфиратли, ўта раҳмли зотдир.",359,18],["لَّا تَ[q:95[جْ]عَلُو[s[اْ] دُع[o[َا]ٓءَ [h:9550[ٱ][l[ل]رَّسُولِ بَيْنَكُمْ كَدُع[o[َا]ٓءِ بَعْضِك[c:9551[ُم ب]َعْ[f:9552[ضًا‌ۚ ق]َ[q:298[دْ] يَعْلَمُ [h:2880[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ يَتَسَلَّلُونَ مِ[f:344[نك]ُمْ لِوَا[f:9553[ذًا‌ۚ ف]َلْيَحْذَرِ [h:9554[ٱ]لَّذِينَ يُخَالِفُونَ عَنْ أَمْرِه[o[ِۦٓ] أَ[f:9555[ن ت]ُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Пайғамбарнинг орангиздаги даъватини бир-бирингизнинг даъватингизга ўхшатманг. Батаҳқиқ, Аллоҳ сизлардан паналаб, аста-аста суғирилиб чиқиб кетадиганларни яхши биладир. Унинг ишига хилоф қиладиганлар ўзларига фитна етиши ёки аламли азоб етишидан ҳазир бўлсинлар.",359,18],["أَل[o[َآ] إِ[g[نّ]َ لِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ قَ[q:298[دْ] يَعْلَمُ م[o[َآ] أَ[f:428[نت]ُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُه[c:4323[ُم ب]ِمَا عَمِلُو[s[اْ‌ۗ] وَ[h:72[ٱ]للَّهُ بِكُلِّ شَىْءٍ عَل[p[ِي]مُۢ","Огоҳ бўлинглар! Албатта, осмонлару ердаги нарсалар Аллоҳникидир. У зот сизнинг қай ҳолатда эканингизни яхши биладир. Унинг Ўзига қайтариладиган кунда эса, қилган амаллари ҳақида уларга хабар берур. Аллоҳ ҳар бир нарсани ўта билгувчи зотдир.",359,18]]},{"n":25,"ar":"الفُرۡقَانِ","en":"Al-Furqaan","uz":"Фурқон","type":"Макка","ayahs":[["تَبَارَكَ [h:9556[ٱ]لَّذِى نَزَّلَ [h:9557[ٱ]لْفُرْقَانَ عَلَىٰ عَ[q:7944[بْ]دِه[n[ِۦ] لِيَكُونَ لِلْعَ[n[ـٰ]لَمِينَ نَذِيرًا","Оламларга огоҳлантирувчи бўлсин учун бандасига Фурқонни нозил қилган Зот баракотли, улуғдир.",359,18],["ٱلَّذِى لَهُ[n[ۥ] مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَلَمْ يَتَّخِذْ وَلَ[a:7939[دًا و]َلَمْ يَك[u:2596[ُن ل]َّهُ[n[ۥ] شَرِي[f:7940[كٌ ف]ِى [h:7941[ٱ]لْمُلْكِ وَخَلَقَ كُلَّ ش[f:9558[َىْءٍ ف]َقَدَّرَهُ[n[ۥ] تَ[q:9559[قْ]دِيرًا","У осмонлару ернинг мулки Унга хос бўлган, Ўзига фарзанд тутмаган, мулкида шериги бўлмаган, ҳар бир нарсани ўлчов ила ўлчаб яратган Зотдир.",359,18],["وَ[h:9999[ٱ]تَّخَذُو[s[اْ] مِ[f:3136[ن د]ُونِه[o[ِۦٓ] ءَالِهَ[u:9560[ةً ل]َّا يَخْلُقُونَ شَيْـ[a:5188[ـًٔا و]َهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَ[f:6929[نف]ُسِهِمْ ضَر[a:3719[ًّا و]َلَا نَفْ[a:5175[عًا و]َلَا يَمْلِكُونَ مَوْ[a:9561[تًا و]َلَا حَيَ[s[و][n[ٲ][a:9562[ةً و]َلَا نُشُورًا","У Зотдан бошқа, ҳеч нарса ярата олмайдиган, ўзлари яратиладиган, ўзлари учун зарарга ҳам, нафга ҳам эга бўлмайдиган, ўлимга ҳам, ҳаётга ҳам, қайта тирилишга ҳам молик бўлмайдиган «худо»лар тутдилар.",360,18],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلّ[o[َآ] إِفْكٌ [h:9563[ٱ]فْتَرَ[n[ٮٰ]هُ وَأَعَانَهُ[n[ۥ] عَلَيْهِ قَوْمٌ ءَاخَرُونَ‌ۖ فَقَ[q:563[دْ] ج[o[َا]ٓءُو ظُلْ[a:9564[مًا و]َزُورًا","Куфр келтирганлар: «Бу уйдирмадан бошқа нарса эмас. Уни ўзи уйдириб олди ва бунда унга бошқа қавмлар кўмак бердилар», дедилар. Бас, шубҳасиз, зулм ва ёлғон гувоҳлик келтирдилар.",360,18],["وَقَال[o[ُوٓ][s[اْ] أَسَ[n[ـٰ]طِيرُ [h:3993[ٱ]لْأَوَّلِينَ [h:9565[ٱ]كْتَتَبَهَا فَهِىَ تُمْلَىٰ عَلَيْهِ بُكْرَ[a:9566[ةً و]َأَصِيلاً","Улар: «Бу аввалгиларнинг афсонасидир. Уларни ёздириб олган. Ҳолбуки, улар унга эртаю кеч имло қилинур», дедилар.",360,18],["قُلْ أَ[f:3300[نز]َلَهُ [h:9567[ٱ]لَّذِى يَعْلَمُ [h:8444[ٱ][l[ل]سِّرَّ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ غَفُو[u:2701[رًا ر]َّحِيمًا","Сен: «Уни осмонлару ердаги сирни биладиган Зот нозил қилди. Албатта, У мағфиратли ва раҳмли Зотдир», дегин.",360,18],["وَقَالُو[s[اْ] مَالِ هَ[n[ـٰ]ذَا [h:9568[ٱ][l[ل]رَّسُولِ يَأْكُلُ [h:9569[ٱ][l[ل]طَّعَامَ وَيَمْشِى فِى [h:9570[ٱ]لْأَسْوَاقِ‌ۙ لَوْل[o[َآ] أُ[f:17[نز]ِلَ إِلَيْهِ مَلَ[f:9571[كٌ ف]َيَكُونَ مَعَهُ[n[ۥ] نَذِيرًا","Улар: «Бу не Пайғамбарки, таом еб, бозорда юрадир?! Унга бир фаришта туширилса эди, у билан огоҳлантиргувчи бўлар эди.",360,18],["أَوْ يُلْقَ[o[ىٰٓ] إِلَيْهِ كَ[f:6264[نز]ٌ أَوْ تَكُونُ لَهُ[n[ۥ] جَ[g[نّ]َ[a:9572[ةٌ ي]َأْكُلُ مِنْهَا‌ۚ وَقَالَ [h:9573[ٱ][l[ل]ظَّ[n[ـٰ]لِمُونَ إِ[f:4511[ن ت]َتَّبِعُونَ إِلَّا رَجُل[a:7781[اً م]َّسْحُورًا","Ёки унга хазина ташланса ёхуд унинг боғи бўлсаю ундан еса», дедилар. Золимлар: «Сизлар фақат сеҳрланган кишига эргашяпсизлар, холос», дедилар.",360,18],["ٱ[f:2837[نظ]ُرْ كَيْفَ ضَرَبُو[s[اْ] لَكَ [h:7782[ٱ]لْأَمْثَ[n[ـٰ]لَ فَضَلُّو[s[اْ] فَلَا يَسْتَطِيعُونَ سَبِيلاً","Сенга қандай мисоллар келтирганига назар сол! Бас, улар йўлдан оздилар. Энди йўл топишга қодир эмаслар.",360,18],["تَبَارَكَ [h:9556[ٱ]لَّذ[o[ِىٓ] إِ[f:364[ن ش][o[َا]ٓءَ جَعَلَ لَكَ خَيْ[a:8082[رًا م]ِّ[f:2624[ن ذ][n[َٲ]لِكَ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ وَيَ[q:9574[جْ]عَل لَّكَ قُصُورَۢا","Агар хоҳласа, сенга ўшандан яхшироғини–остидан анҳорлар оқиб турадиган боғларни ва қасрларни қилиб берадиган Зот баракотли ва улуғ бўлди.",360,18],["بَلْ كَذَّبُو[s[اْ] بِ[h:9575[ٱ][l[ل]سَّاعَةِ‌ۖ وَأَعْتَ[q:2782[دْ]نَا لِمَ[f:9576[ن ك]َذَّبَ بِ[h:9575[ٱ][l[ل]سَّاعَةِ سَعِيرًا","Йўқ! Улар соатни ҳам ёлғонга чиқардилар. Ва Биз соатни ёлғонга чиқарганларга дўзахни тайёрлаб қўйдик.",360,18],["إِذَا رَأَتْه[w:9577[ُم م]ّ[a:9578[ِن م]َّكَا[i:9579[نِۭ ب]َعِي[f:9580[دٍ س]َمِعُو[s[اْ] لَهَا تَغَيُّ[a:9581[ظًا و]َزَفِيرًا","Вақтики у уларни узоқ жойдан кўрганида, унинг ғазабнок қайнашини ва бўкиришини эшитурлар.",361,18],["وَإِذ[o[َآ] أُلْقُو[s[اْ] مِنْهَا مَكَا[f:9582[نًا ض]َيِّ[a:9583[قًا م]ُّقَرَّنِينَ دَعَوْ[s[اْ] هُنَالِكَ ثُبُورًا","Унинг тор жойига кишанланган ҳолларида ташлаганларида эса, ўша жойда ҳалокат тиларлар.",361,18],["لَّا تَ[q:7934[دْ]عُو[s[اْ] [h:9584[ٱ]لْيَوْمَ ثُبُو[a:9585[رًا و][n[َٲ]حِ[a:9586[دًا و]َ[h:105[ٱ][q:105[دْ]عُو[s[اْ] ثُبُو[f:9587[رًا ك]َثِيرًا","Бугунги кунда бир ҳалокатни эмас, кўп ҳалокатни тиланглар!",361,18],["قُلْ أَذ[n[َٲ]لِكَ خَيْرٌ أَمْ جَ[g[نّ]َةُ [h:9588[ٱ]لْخُلْدِ [h:9589[ٱ]لَّتِى وُعِدَ [h:7004[ٱ]لْمُتَّقُونَ‌ۚ كَانَتْ لَهُمْ جَز[o[َا]ٓ[a:9590[ءً و]َمَصِيرًا","Бу яхшими ёки тақводорларга тайёрлаб қўйилган мангулик жаннати яхшими? У улар учун мукофот ва қайтиш жойидир.",361,18],["لَّهُمْ فِيهَا مَا يَش[o[َا]ٓءُونَ خَ[n[ـٰ]لِدِينَ‌ۚ كَانَ عَلَىٰ رَبِّكَ وَعْ[a:9591[دًا م]َّسْــُٔولاً","Уларга у ерда хоҳлаган нарсалари бор, абадий ҳолда қолурлар. Бу Роббинг зиммасидаги масъулиятли ваъдадир.",361,18],["وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ فَيَقُولُ ءَأَ[f:716[نت]ُمْ أَضْلَلْتُمْ عِبَادِى هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ أَمْ هُمْ ضَلُّو[s[اْ] [h:9592[ٱ][l[ل]سَّب[p[ِي]لَ","Уларни ва Аллоҳдан ўзга ибодат қилган нарсаларини тўплаган кунда У зот: «Анави бандаларимни сизлар адаштирдингизми ёки улар ўзлари йўлдан оздиларми?!» дейдир.",361,18],["قَالُو[s[اْ] سُ[q:168[بْ]حَ[n[ـٰ]نَكَ مَا كَانَ يَ[i:8425[نۢب]َغِى لَن[o[َآ] أ[a:8693[َن ن]َّتَّخِذَ مِ[f:7543[ن د]ُونِكَ مِنْ أَوْلِي[o[َا]ٓءَ وَلَ[n[ـٰ]ك[a:9593[ِن م]َّتَّعْتَهُمْ وَءَاب[o[َا]ٓءَهُمْ حَتَّىٰ نَسُو[s[اْ] [h:9594[ٱ][l[ل]ذِّكْرَ وَكَانُو[s[اْ] قَوْم[i:9595[َۢا ب]ُورًا","Улар: «Эй пок Парвардигор, Сендан ўзгани дўст тутмоқ биз учун ярашмас. Лекин сен уларни ва ота-боболарини ҳузурлантирдингки, ҳатто улар зикрингни унутдилар ва ҳалокат қавми бўлиб қолдилар», дерлар.",361,18],["فَقَ[q:563[دْ] كَذَّبُوك[c:9596[ُم ب]ِمَا تَقُولُونَ فَمَا تَسْتَطِيعُونَ صَرْ[a:9597[فًا و]َلَا نَصْ[a:9598[رًا‌ۚ و]َم[a:9599[َن ي]َظْل[w:9600[ِم م]ِّ[f:344[نك]ُمْ نُذِ[q:8980[قْ]هُ عَذَا[f:9601[بًا ك]َبِيرًا","Батаҳқиқ, улар сизларни айтаётган нарсангизда ёлғончига чиқардилар. Энди буришга ҳам, ёрдам олишга ҳам қодир бўлмассиз. Сиздан ким зулм қилган бўлса, унга азобни тортдирамиз.",361,18],["وَم[o[َآ] أَرْسَلْنَا قَ[q:7849[بْ]لَكَ مِنَ [h:4822[ٱ]لْمُرْسَلِينَ إِلّ[o[َآ] إِ[g[نّ]َهُمْ لَيَأْكُلُونَ [h:9602[ٱ][l[ل]طَّعَامَ وَيَمْشُونَ فِى [h:9570[ٱ]لْأَسْوَاقِ‌ۗ وَجَعَلْنَا بَعْضَكُمْ لِبَعْ[f:9603[ضٍ ف]ِتْنَةً أَتَصْبِرُونَ‌ۗ وَكَانَ رَبُّكَ بَصِيرًا","Биз сендан олдин юборган Пайғамбарларимиз ҳам, албатта, таом ер ва бозорларда юрар эдилар. Баъзиларингизни баъзиларингизга синов қилдик. Сабр қиласизлармикин?! Роббинг кўргувчи бўлган зотдир.",361,18],["۞ وَقَالَ [h:614[ٱ]لَّذِينَ لَا يَرْجُونَ لِق[o[َا]ٓءَنَا لَوْل[o[َآ] أُ[f:17[نز]ِلَ عَلَيْنَا [h:9604[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ أَوْ نَرَىٰ رَبَّنَا‌ۗ لَقَدِ [h:9605[ٱ]سْتَكْبَرُو[s[اْ] ف[o[ِىٓ] أَ[f:568[نف]ُسِهِمْ وَعَتَوْ عُتُو[f:9606[ًّا ك]َبِيرًا","Бизга учрашдан умидсиз бўлганлар, бизга фаришталар туширилса ёки, Роббимизни кўрсак эди, дерлар. Батаҳқиқ, улар ўзларидан кетдилар ва катта туғён-ла туғён қилдилар.",362,19],["يَوْمَ يَرَوْنَ [h:9607[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةَ لَا بُشْرَىٰ يَوْمَئِ[u:9608[ذٍ ل]ِّلْمُ[q:9609[جْ]رِمِينَ وَيَقُولُونَ حِ[q:9610[جْ][a:9611[رًا م]َّحْجُورًا","Улар фаришталарни кўрадиган кунда, ҳа, ўша кунда жиноятчиларга хушхабар бўлмас. Ва улар: «Ҳаром, ҳаром», дерлар.",362,19],["وَقَدِمْن[o[َآ] إِلَىٰ مَا عَمِلُو[s[اْ] مِنْ عَمَ[f:9612[لٍ ف]َجَعَلْنَ[n[ـٰ]هُ هَب[o[َا]ٓ[a:9613[ءً م]َّ[f:9614[نث]ُورًا","Ва қилган амалига келиб, уларни тўзон каби сочиб юборурмиз.",362,19],["أَصْحَ[n[ـٰ]بُ [h:415[ٱ]لْجَ[g[نّ]َةِ يَوْمَئِذٍ خَيْ[a:9615[رٌ م]ُّسْتَقَر[a:9616[ًّا و]َأَحْسَنُ مَقِيلاً","Ўша кунда жаннат эгаларининг қароргоҳлари ва оромгоҳлар ғоят яхшидир.",362,19],["وَيَوْمَ تَشَقَّقُ [h:9617[ٱ][l[ل]سَّم[o[َا]ٓءُ بِ[h:9618[ٱ]لْغَمَ[n[ـٰ]مِ وَنُزِّلَ [h:9619[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ تَ[f:7929[نز]ِيلاً","У кунда булутли осмон ёрилиб, фаришталар бўлак-бўлак тушурилурлар.",362,19],["ٱلْمُلْكُ يَوْمَئِذٍ [h:4590[ٱ]لْحَقُّ لِلرَّحْمَ[n[ـٰ]نِ‌ۚ وَكَانَ يَوْمًا عَلَى [h:468[ٱ]لْكَ[n[ـٰ]فِرِينَ عَسِيرًا","У кунда ҳукмронлик Роҳманга ҳақ бўлур. У кун кофирлар учун кўп қийин кун бўлур.",362,19],["وَيَوْمَ يَعَضُّ [h:9620[ٱ][l[ل]ظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَ[n[ـٰ]لَيْتَنِى [h:9621[ٱ]تَّخَذْتُ مَعَ [h:9622[ٱ][l[ل]رَّسُولِ سَبِيلاً","У кунда золим икки қўлини тишлаб: «Эй воҳ!!! Пайғамбар ила бир йўлни тутганимда эди!» дер.",362,19],["يَ[n[ـٰ]وَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلاً","«Эй воҳ!!! Кошки фалончини дўст тутмасам эди.",362,19],["لَّقَ[q:2389[دْ] أَضَلَّنِى عَنِ [h:9623[ٱ][l[ل]ذِّكْرِ بَعْدَ إِذْ ج[o[َا]ٓءَنِى‌ۗ وَكَانَ [h:7732[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ لِلْإِ[f:6549[نس]َ[n[ـٰ]نِ خَذُولاً","Батаҳқиқ, менга зикр келгандан сўнг у мени адаштирди. Шайтон инсонни ёрдамсиз ташлаб кетгувчидир», дер.",362,19],["وَقَالَ [h:9624[ٱ][l[ل]رَّسُولُ يَ[n[ـٰ]رَبِّ إِ[g[نّ]َ قَوْمِى [h:9625[ٱ]تَّخَذُو[s[اْ] هَ[n[ـٰ]ذَا [h:6544[ٱ]لْقُرْءَانَ مَهْجُورًا","Ва Пайғамбар: «Эй Роббим, албатта, менинг қавмим ушбу Қуръонни тарк этдилар», деди.",362,19],["وَكَذ[n[َٲ]لِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُو[a:9626[ًّا م]ِّنَ [h:9627[ٱ]لْمُ[q:4093[جْ]رِمِينَ‌ۗ وَكَفَىٰ بِرَبِّكَ هَادِ[a:9628[يًا و]َنَصِيرًا","Ана шундай. Ҳар Пайғамбар учун жиноятчилардан душман қилганмиз. Ҳидоят ва ёрдамчиликда Роббинг Ўзи кифоя қилур.",362,19],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَوْلَا نُزِّلَ عَلَيْهِ [h:9629[ٱ]لْقُرْءَانُ جُمْلَ[a:9630[ةً و][n[َٲ]حِدَ[f:9631[ةً‌ۚ ك]َذ[n[َٲ]لِكَ لِنُثَبِّتَ بِه[n[ِۦ] فُؤَادَكَ‌ۖ وَرَتَّلْنَ[n[ـٰ]هُ تَرْتِيلاً","Куфр келтирганлар: «Унга Қуръон бир йўла нозил қилинса эди», дедилар. Биз сенинг қалбингни у билан собит қилиш учун шундай қилдик ва уни дона-дона қилиб ўқидик.",362,19],["وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَ[n[ـٰ]كَ بِ[h:370[ٱ]لْحَقِّ وَأَحْسَنَ تَفْسِيرًا","Улар сенга бирор масал келтирсалар, Биз, албатта, сенга ҳақни ва гўзал шарҳини келтирамиз.",363,19],["ٱلَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَ[g[نّ]َمَ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ شَ[a:3659[رٌّ م]َّكَا[a:3660[نًا و]َأَضَلُّ سَبِيلاً","Жаҳаннам томон юз тубан ҳолларида судраладиганлар, ана ўшалар, маконлари энг ёмон, йўллари энг адашган кимсалардир.",363,19],["وَلَقَ[q:341[دْ] ءَاتَيْنَا مُوسَى [h:257[ٱ]لْكِتَ[n[ـٰ]بَ وَجَعَلْنَا مَعَهُ[o[ۥٓ] أَخَاهُ هَ[n[ـٰ]رُونَ وَزِيرًا","Батаҳқиқ, Биз Мусога китобни бердик ва унга акаси Ҳорунни вазир қилдик.",363,19],["فَقُلْنَا [h:9632[ٱ]ذْهَب[o[َآ] إِلَى [h:9633[ٱ]لْقَوْمِ [h:4053[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا فَدَ[g[مّ]َرْنَ[n[ـٰ]هُمْ تَ[q:7705[دْ]مِيرًا","Бас: «Иккингиз бизнинг оятларимизни ёлғонга чиқарган қавмга боринг», дедик. Сўнг уларни ер билан яксон қилдик.",363,19],["وَقَوْمَ نُو[u:9634[حٍ ل]َّ[g[مّ]َا كَذَّبُو[s[اْ] [h:9635[ٱ][l[ل]رُّسُلَ أَغْرَ[q:9636[قْ]نَ[n[ـٰ]هُمْ وَجَعَلْنَ[n[ـٰ]هُمْ لِل[g[نّ]َاسِ ءَايَ[a:9637[ةً‌ۖ و]َأَعْتَ[q:2782[دْ]نَا لِلظَّ[n[ـٰ]لِمِينَ عَذَابًا أَلِيمًا","Ва Нуҳ қавми Пайғамбарларни ёлғонга чиқарганларида ғарқ этдик ва уларни одамларга ибрат қилдик. Ҳамда Биз золимларга аламли азоблар тайёрлаб қўйдик.",363,19],["وَعَا[a:9638[دًا و]َثَمُودَ[s[اْ] وَأَصْحَ[n[ـٰ]بَ [h:9639[ٱ][l[ل]رَّسِّ وَقُرُون[i:9640[َۢا ب]َيْنَ ذ[n[َٲ]لِكَ كَثِيرًا","Од, Самуд ва қудуқ эгаларини ҳамда бу орадаги асрларни эсла.",363,19],["وَكُل[f:9641[اًّ ض]َرَ[q:9642[بْ]نَا لَهُ [h:9643[ٱ]لْأَمْثَ[n[ـٰ]لَ‌ۖ وَكُل[f:9644[اًّ ت]َبَّرْنَا تَتْبِيرًا","Улардан ҳар бирига мисоллар келтирдик. Ва уларни қириб битирдик.",363,19],["وَلَقَ[q:341[دْ] أَتَوْ[s[اْ] عَلَى [h:9645[ٱ]لْقَرْيَةِ [h:5089[ٱ]لَّت[o[ِىٓ] أُمْطِرَتْ مَطَرَ [h:9646[ٱ][l[ل]سَّوْءِ‌ۚ أَفَلَمْ يَكُونُو[s[اْ] يَرَوْنَهَا‌ۚ بَلْ كَانُو[s[اْ] لَا يَرْجُونَ نُشُورًا","Батаҳқиқ, улар ёмонлик ёмғири ёғдирилган шаҳарга келган эдилар. Уни кўрмаган эдиларми?! Йўқ! Улар қайта тирилишдан умидсиз эдилар.",363,19],["وَإِذَا رَأَوْكَ إ[a:8741[ِن ي]َتَّخِذُونَكَ إِلَّا هُزُوًا أَهَ[n[ـٰ]ذَا [h:8742[ٱ]لَّذِى بَعَثَ [h:9647[ٱ]للَّهُ رَسُولاً","Улар сени кўрган вақтларида: «Аллоҳ Пайғамбар қилиб юборган шуми?!",363,19],["إِ[f:9648[ن ك]َادَ لَيُضِلُّنَا عَنْ ءَالِهَتِنَا لَوْل[o[َآ] أَ[f:9649[ن ص]َبَرْنَا عَلَيْهَا‌ۚ وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ [h:856[ٱ]لْعَذَابَ مَنْ أَضَلُّ سَبِيلاً","Агар сабр қилмаганимизда, албатта, у бизни сал бўлмаса худоларимиздан оздирарди-я!» деб масхарага олурлар. Яқинда–азобни кўрган чоғларида–ким йўлдан озганроқ эканини билурлар.",363,19],["أَرَءَيْتَ مَنِ [h:8418[ٱ]تَّخَذَ إِلَ[n[ـٰ]هَهُ[n[ۥ] هَوَ[n[ٮٰ]هُ أَفَأَ[f:6069[نت]َ تَكُونُ عَلَيْهِ وَكِيلاً","Ҳавои нафсини ўзига худо қилиб олганни кўрдингми?! Энди сен унга вакил бўласанми?!",363,19],["أَمْ تَحْسَبُ أَ[g[نّ]َ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ‌ۚ إِنْ هُمْ إِلَّا كَ[h:5153[ٱ]لْأَنْعَ[n[ـٰ]مِ‌ۖ بَلْ هُمْ أَضَلُّ سَبِيلاً","Ёки сен уларнинг кўплари тинглай оладилар ё англай оладилар, деб ҳисоблайсанми? Аслида, уларнинг ҳайвонлардан фарқи йўқ. Балки яна ҳам йўлдан озганроқдирлар.",364,19],["أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ [h:9650[ٱ][l[ل]ظِّلَّ وَلَوْ ش[o[َا]ٓءَ لَجَعَلَهُ[n[ۥ] سَاكِ[f:9651[نًا ث]ُ[g[مّ]َ جَعَلْنَا [h:9652[ٱ][l[ل]شَّمْسَ عَلَيْهِ دَلِيلاً","Роббингнинг сояни қандай ёйиб қўйганини кўрмадингми? Агар хоҳласа, уни жилмас қиларди. Сўнгра қуёшни Биз унга далил қилдик.",364,19],["ثُ[g[مّ]َ قَبَضْنَ[n[ـٰ]هُ إِلَيْنَا قَ[q:9653[بْ][a:9654[ضًا ي]َسِيرًا","Сўнгра Биз уни Ўзимизга аста-секин тортиб олдик.",364,19],["وَهُوَ [h:4114[ٱ]لَّذِى جَعَلَ لَكُمُ [h:6116[ٱ]لَّيْلَ لِبَا[a:9655[سًا و]َ[h:9656[ٱ][l[ل][g[نّ]َوْمَ سُبَا[a:9657[تًا و]َجَعَلَ [h:9658[ٱ][l[ل][g[نّ]َهَارَ نُشُورًا","У сиз учун кечани либос, уйқуни истироҳот қилган ва кундузни тирилиш қилган Зотдир.",364,19],["وَهُوَ [h:4114[ٱ]لَّذ[o[ِىٓ] أَرْسَلَ [h:9659[ٱ][l[ل]رِّيَ[n[ـٰ]حَ بُشْر[i:4756[َۢا ب]َيْنَ يَدَىْ رَحْمَتِه[n[ِۦ]‌ۚ وَأَ[f:271[نز]َلْنَا مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:9660[ءً ط]َهُورًا","У Ўз раҳмати олдидан шамолларни хушхабар қилиб юборган Зотдир. Ва осмондан пок сув туширдик.",364,19],["لِّنُحْــِۧىَ بِه[n[ِۦ] بَلْدَ[a:9661[ةً م]َّيْ[a:9662[تًا و]َنُسْقِيَهُ[n[ۥ] مِ[g[مّ]َا خَلَ[q:5159[قْ]ن[o[َآ] أَنْعَ[n[ـٰ][a:9663[مًا و]َأَنَاسِىَّ كَثِيرًا","У ила ўлик юртни тирилтиришимиз ва ўзимиз яратган кўплаб чорва ҳайвонлари ҳамда инсонларни суғоришимиз учун.",364,19],["وَلَقَ[q:341[دْ] صَرَّفْنَ[n[ـٰ]هُ بَيْنَهُمْ لِيَذَّكَّرُو[s[اْ] فَأَبَ[o[ىٰٓ] أَكْثَرُ [h:6838[ٱ][l[ل][g[نّ]َاسِ إِلَّا كُفُورًا","Батаҳқиқ, Биз уни эслатма олишлари учун ораларида турлича тасарруф қилиб кўрдик. Одамларнинг кўплари куфрдан бошқа нарсадан бош тортдилар.",364,19],["وَلَوْ شِئْنَا لَبَعَثْنَا فِى كُلِّ قَرْيَ[a:9664[ةٍ ن]َّذِيرًا","Агар хоҳласак, ҳар шаҳарга битта огоҳлантиргувчи юборар эдик.",364,19],["فَلَا تُطِعِ [h:9665[ٱ]لْكَ[n[ـٰ]فِرِينَ وَجَ[n[ـٰ]هِ[q:9666[دْ]ه[c:9667[ُم ب]ِه[n[ِۦ] جِهَا[f:9668[دًا ك]َبِيرًا","Кофирларга итоат этма! Уларга қарши у билан катта жиҳод қил!",364,19],["۞ وَهُوَ [h:4114[ٱ]لَّذِى مَرَجَ [h:9669[ٱ]لْبَحْرَيْنِ هَ[n[ـٰ]ذَا عَذْ[f:9670[بٌ ف]ُرَا[a:9671[تٌ و]َهَ[n[ـٰ]ذَا مِلْحٌ أُجَا[a:9672[جٌ و]َجَعَلَ بَيْنَهُمَا بَرْزَ[a:9673[خًا و]َحِ[q:9674[جْ][a:9675[رًا م]َّحْجُورًا","У икки денгизни-буниси чучук-ширин, униси шўр-аччиқ қилиб оқизиб қўйган ва ораларига кўринмас тўсиқ ҳамда очилмас сарҳад қилган Зотдир.",364,19],["وَهُوَ [h:4114[ٱ]لَّذِى خَلَقَ مِنَ [h:4727[ٱ]لْم[o[َا]ٓءِ بَشَ[f:9676[رًا ف]َجَعَلَهُ[n[ۥ] نَسَ[a:9677[بًا و]َصِهْ[a:9678[رًا‌ۗ و]َكَانَ رَبُّكَ قَدِيرًا","У сувдан башар яратган ва уни насл-насаб, қуда-анда қилиб қўйган Зотдир. Роббинг қодир бўлган Зотдир.",364,19],["وَيَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ مَا لَا يَ[f:534[نف]َعُهُمْ وَلَا يَضُرُّهُمْ‌ۗ وَكَانَ [h:9679[ٱ]لْكَافِرُ عَلَىٰ رَبِّه[n[ِۦ] ظَهِيرًا","Улар Аллоҳдан ўзга уларга наф ҳам, зарар ҳам етказмайдиган нарсаларга ибодат қиларлар. Ва кофир Роббига қарши ёрдамчи бўлгандир.",364,19],["وَم[o[َآ] أَرْسَلْنَ[n[ـٰ]كَ إِلَّا مُبَشِّ[a:7924[رًا و]َنَذِيرًا","Биз сени фақат хушхабарчи ва огоҳлантиргувчи этиб юборганмиз, холос.",365,19],["قُلْ م[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ مِنْ أَ[q:6133[جْ]رٍ إِلَّا مَ[f:9680[ن ش][o[َا]ٓءَ أ[a:8331[َن ي]َتَّخِذَ إِلَىٰ رَبِّه[n[ِۦ] سَبِيلاً","Сен: «Мен сизлардан бунинг учун ажр сўрамайман, фақат, ким хоҳласа, Робби томон йўл олишини», деб айт.",365,19],["وَتَوَكَّلْ عَلَى [h:9681[ٱ]لْحَىِّ [h:9682[ٱ]لَّذِى لَا يَمُوتُ وَسَبِّحْ بِحَمْدِه[n[ِۦ]‌ۚ وَكَفَىٰ بِه[n[ِۦ] بِذُنُوبِ عِبَادِه[n[ِۦ] خَبِيرًا","Ва барҳаёт, ўлмайдиган Зотга таваккал қил ҳамда Уни ҳамду сано ила поклаб ёд эт. Бандаларининг гуноҳларидан ўта хабардор бўлишда Унинг Ўзи кифоядир.",365,19],["ٱلَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّا[f:4739[مٍ ث]ُ[g[مّ]َ [h:156[ٱ]سْتَوَىٰ عَلَى [h:4740[ٱ]لْعَرْشِ‌ۚ [h:9683[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ فَسْــَٔلْ بِه[n[ِۦ] خَبِيرًا","У осмонлару ерни ва уларнинг орасидаги нарсаларни олти кунда яратган, сўнгра аршни эгаллаган зотдир. У Роҳмандир. Бас, ўша ўта Хабардордан сўра.",365,19],["وَإِذَا قِيلَ لَهُمُ [h:9684[ٱ]سْجُدُو[s[اْ] لِلرَّحْمَ[n[ـٰ]نِ قَالُو[s[اْ] وَمَا [h:9685[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا ۩","Қачонки уларга: «Роҳманга сажда қилинглар!» дейилса, улар: «Роҳман нима? Сен буюрган нарсага сажда қилаверамизми?» дерлар. Бу уларнинг узоқлашишини зиёда қилур.",365,19],["تَبَارَكَ [h:9556[ٱ]لَّذِى جَعَلَ فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ بُرُو[a:9686[جًا و]َجَعَلَ فِيهَا سِر[n[َٲ][a:9687[جًا و]َقَمَ[a:9688[رًا م]ُّنِيرًا","Осмонда буржлар қилган ва унда чироқ ва нур сочгувчи ой қилган Зот баракотли-буюк бўлди.",365,19],["وَهُوَ [h:4114[ٱ]لَّذِى جَعَلَ [h:9689[ٱ]لَّيْلَ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ خِلْفَ[u:9690[ةً ل]ِّمَنْ أَرَادَ أ[a:9691[َن ي]َذَّكَّرَ أَوْ أَرَادَ شُكُورًا","У ибрат олмоқни ирода қилган ва шукр қилмоқни ирода қилган киши учун кеча-кундузни бирин-кетин қилган Зотдир.",365,19],["وَعِبَادُ [h:9692[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ [h:9693[ٱ]لَّذِينَ يَمْشُونَ عَلَى [h:7958[ٱ]لْأَرْضِ هَوْ[a:9694[نًا و]َإِذَا خَاطَبَهُمُ [h:9695[ٱ]لْجَ[n[ـٰ]هِلُونَ قَالُو[s[اْ] سَلَ[n[ـٰ]مًا","Роҳманнинг бандалари ер юзида тавозуъ ила юрадиган ва жоҳиллар хитоб қилганида, «салом», дейдиганлардир.",365,19],["وَ[h:9999[ٱ]لَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّ[a:9696[دًا و]َقِيَ[n[ـٰ]مًا","Улар тунларни Роббиларига сажда қилиб, бедор ўтказурлар.",365,19],["وَ[h:9999[ٱ]لَّذِينَ يَقُولُونَ رَبَّنَا [h:9697[ٱ]صْرِفْ عَ[g[نّ]َا عَذَابَ جَهَ[g[نّ]َمَ‌ۖ إِ[g[نّ]َ عَذَابَهَا كَانَ غَرَامًا","Улар: «Эй Роббимиз, Ўзинг биздан жаҳаннам азобини бургин, албатта, жаҳаннам азоби доимийдир.",365,19],["إِ[g[نّ]َهَا س[o[َا]ٓءَتْ مُسْتَقَر[a:9698[ًّا و]َمُقَامًا","Албатта, у энг ёмон қароргоҳ ва турар жойдир», дейдиганлардир.",365,19],["وَ[h:9999[ٱ]لَّذِينَ إِذ[o[َآ] أَ[f:1538[نف]َقُو[s[اْ] لَمْ يُسْرِفُو[s[اْ] وَلَمْ يَ[q:9699[قْ]تُرُو[s[اْ] وَكَانَ بَيْنَ ذ[n[َٲ]لِكَ قَوَامًا","Улар инфоқ қилганларида исроф ҳам ва хасислик ҳам қилмаслар. У иккиси ўртасида мўътадил бўлурлар.",365,19],["وَ[h:9999[ٱ]لَّذِينَ لَا يَ[q:1240[دْ]عُونَ مَعَ [h:3975[ٱ]للَّهِ إِلَ[n[ـٰ]هًا ءَاخَرَ وَلَا يَ[q:3698[قْ]تُلُونَ [h:9700[ٱ][l[ل][g[نّ]َفْسَ [h:4523[ٱ]لَّتِى حَرَّمَ [h:3706[ٱ]للَّهُ إِلَّا بِ[h:370[ٱ]لْحَقِّ وَلَا يَزْنُونَ‌ۚ وَم[a:1297[َن ي]َفْعَلْ ذ[n[َٲ]لِكَ يَلْقَ أَثَامًا","Улар Аллоҳ билан бирга бирор илоҳга илтижо қилмаслар. Аллоҳ ҳаром қилган жонни ноҳақдан ўлдирмаслар. Зино қилмаслар. Ким ана шуни қилса, уқубатга дучор бўлур.",366,19],["يُضَ[n[ـٰ]عَفْ لَهُ [h:9701[ٱ]لْعَذَابُ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ وَيَخْلُ[q:9702[دْ] فِيه[n[ِۦ] مُهَانًا","Қиёмат куни унинг азоби бир неча баробар кўпайтирилур ва у да хор бўлиб абадий қолур.",366,19],["إِلَّا مَ[f:8374[ن ت]َابَ وَءَامَنَ وَعَمِلَ عَمَل[f:5817[اً ص]َ[n[ـٰ]لِ[f:8375[حًا ف]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يُبَدِّلُ [h:9703[ٱ]للَّهُ سَيِّـَٔـاتِهِمْ حَسَنَ[n[ـٰ][a:9704[تٍ‌ۗ و]َكَانَ [h:2653[ٱ]للَّهُ غَفُو[u:2701[رًا ر]َّحِيمًا","Магар ким тавба қилса, иймон келтириб, солиҳ амал қилса, бас, Аллоҳ ана ўшаларнинг ёмонликларини яхшиликларга алмаштирур. Аллоҳ мағфиратли ва раҳмли бўлган зотдир.",366,19],["وَمَ[f:6514[ن ت]َابَ وَعَمِلَ صَ[n[ـٰ]لِ[f:9705[حًا ف]َإِ[g[نّ]َهُ[n[ۥ] يَتُوبُ إِلَى [h:1637[ٱ]للَّهِ مَتَابًا","Ким тавба қилиб, солиҳ амал қилса, у, албатта, Аллоҳга қайтиш ила қайтар.",366,19],["وَ[h:9999[ٱ]لَّذِينَ لَا يَشْهَدُونَ [h:9706[ٱ][l[ل]زُّورَ وَإِذَا مَرُّو[s[اْ] بِ[h:1262[ٱ][l[ل]لَّغْوِ مَرُّو[s[اْ] كِرَامًا","Улар ёлғон гувоҳлик бермайдиганлардир ва беҳуда нарсалар олдидан ўтсалар, ҳурматларини сақлаган ҳолда ўтарлар.",366,19],["وَ[h:9999[ٱ]لَّذِينَ إِذَا ذُكِّرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ رَبِّهِمْ لَمْ يَخِرُّو[s[اْ] عَلَيْهَا صُم[a:9707[ًّا و]َعُمْيَانًا","Уларга Роббиларининг оятлари эслатилганда, уларга гунг ва кўрлардек ташланмаслар.",366,19],["وَ[h:9999[ٱ]لَّذِينَ يَقُولُونَ رَبَّنَا هَ[q:1878[بْ] لَنَا مِنْ أَزْو[n[َٲ]جِنَا وَذُرِّيَّ[n[ـٰ]تِنَا قُرَّةَ أَعْيُ[a:9708[نٍ و]َ[h:670[ٱ][q:670[جْ]عَلْنَا لِلْمُتَّقِينَ إِمَامًا","Улар: «Эй Роббимиз, Ўзинг бизга жуфти ҳалолларимиздан ва зурриётларимиздан кўзимиз қувонадиган нарса ҳадя эт ҳамда бизларни тақводорларга йўлбошчи эт», дейдиганлардир.",366,19],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يُ[q:5019[جْ]زَوْنَ [h:9709[ٱ]لْغُرْفَةَ بِمَا صَبَرُو[s[اْ] وَيُلَقَّوْنَ فِيهَا تَحِيَّ[a:9710[ةً و]َسَلَ[n[ـٰ]مًا","Ана ўшалар сабр қилганлари учун «ғурфа» ила мукофотланурлар ва унда табрик ва салом билан қаршиланурлар.",366,19],["خَ[n[ـٰ]لِدِينَ فِيهَا‌ۚ حَسُنَتْ مُسْتَقَر[a:9698[ًّا و]َمُقَامًا","Улар ўшанда абадий қолурлар. У қандай ҳам гўзал қароргоҳ ва манзилдир.",366,19],["قُلْ مَا يَعْبَؤُ[s[اْ] بِكُمْ رَبِّى لَوْلَا دُع[o[َا]ٓؤُكُمْ‌ۖ فَقَ[q:563[دْ] كَذَّ[q:459[بْ]تُمْ فَسَوْفَ يَكُونُ لِزَامَۢا","Сен: «Агар дуо-илтижоларингиз бўлмаса, Роббим сизларга ҳеч қиймат бермас. Бас, батаҳқиқ, сиз ёлғонга чиқардингиз. Энди сизларга лозим бўлур», деб айт.",366,19]]},{"n":26,"ar":"الشُّعَرَاءِ","en":"Ash-Shu'araa","uz":"Шуаро","type":"Макка","ayahs":[["ط[m[سٓ][m[مٓ]","То. Син. Мим.",367,19],["تِلْكَ ءَايَ[n[ـٰ]تُ [h:5932[ٱ]لْكِتَ[n[ـٰ]بِ [h:6541[ٱ]لْمُب[p[ِي]نِ","Булар очиқ китобнинг оятларидир.",367,19],["لَعَلَّكَ بَ[n[ـٰ]خِ[a:7956[عٌ ن]َّفْسَكَ أَلَّا يَكُونُو[s[اْ] مُؤْمِن[p[ِي]نَ","Эҳтимол, мўмин бўлмаганлари учун сен ўзингни ҳалок қилмоқчидирсан?!",367,19],["إ[a:9711[ِن ن]َّشَأْ نُنَزِّلْ عَلَيْه[w:2901[ِم م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ ءَايَ[f:9712[ةً ف]َظَلَّتْ أَعْنَ[n[ـٰ]قُهُمْ لَهَا خَ[n[ـٰ]ضِع[p[ِي]نَ","Агар хоҳласак, уларга осмондан оят-мўъжиза нозил қилурмиз. Бас, уларнинг бўйинлари унга эгилиб қоладир.",367,19],["وَمَا يَأْتِيه[w:7205[ِم م]ِّ[f:8667[ن ذ]ِكْ[a:9713[رٍ م]ِّنَ [h:8351[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ مُحْدَثٍ إِلَّا كَانُو[s[اْ] عَنْهُ مُعْرِض[p[ِي]نَ","Уларга Роҳмандан янги эслатма келибдики, албатта, ундан юз ўгиргувчи бўлганлар.",367,19],["فَقَ[q:563[دْ] كَذَّبُو[s[اْ] فَسَيَأْتِيهِمْ أَ[i:3925[نۢب]َ[o[ـٰٓ]ؤُ[s[اْ] مَا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Бас, батаҳқиқ, ёлғонга чиқардилар. Яқинда уларга ўзлари истеҳзо қилган нарсанинг хабари келажакдир.",367,19],["أَوَلَمْ يَرَوْ[s[اْ] إِلَى [h:5136[ٱ]لْأَرْضِ كَمْ أَ[i:9714[نۢب]َتْنَا فِيهَا مِ[f:843[ن ك]ُلِّ زَوْ[f:9715[جٍ ك]َر[p[ِي]مٍ","Улар ерга қарамайдиларми?! Биз унда гўзал навлардан қанчаларини ундириб қўйибмиз.",367,19],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[a:9716[ةً‌ۖ و]َمَا كَانَ أَكْثَرُه[w:9717[ُم م]ُّؤْمِن[p[ِي]نَ","Албатта, бунда оят-белги бор. Лекин кўплари мўмин бўлмаслар.",367,19],["وَإِ[g[نّ]َ رَبَّكَ لَهُوَ [h:1987[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Албатта, Роббинг Ўзи азизу меҳрибондир.",367,19],["وَإِذْ نَادَىٰ رَبُّكَ مُوسَ[o[ىٰٓ] أَنِ [h:9719[ٱ]ئْتِ [h:9720[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Роббинг Мусога: «У золим қавмга боргин.",367,19],["قَوْمَ فِرْعَوْنَ‌ۚ أَلَا يَتَّق[p[ُو]نَ","Фиръавн қавмига. қўрқмайдиларми?! « деб нидо қилганини эсла.",367,19],["قَالَ رَبِّ إِ[g[نّ][o[ِىٓ] أَخَافُ أ[a:9721[َن ي]ُكَذِّب[p[ُو]نِ","У: «Эй Роббим, улар мени ёлғончи қилишларидан қўрқаман.",367,19],["وَيَضِيقُ صَ[q:8465[دْ]رِى وَلَا يَ[f:9722[نط]َلِقُ لِسَانِى فَأَرْسِلْ إِلَىٰ هَ[n[ـٰ]ر[p[ُو]نَ","Ва дилим сиқилишидан ҳамда тилим бурро бўлмай қолишидан. Бас, Ҳорунни элчи қил.",367,19],["وَلَهُمْ عَلَىَّ ذَ[i:9723[نۢب][f:9724[ٌ ف]َأَخَافُ أ[a:9725[َن ي]َ[q:9726[قْ]تُل[p[ُو]نِ","Менинг зиммамда улар наздида гуноҳ бор. Бас, мени ўлдиришларидан хавфдаман», деди.",367,19],["قَالَ كَلَّا‌ۖ فَ[h:9727[ٱ]ذْهَبَا بِـَٔـايَ[n[ـٰ]تِن[o[َآ‌ۖ] إِ[g[نّ]َا مَعَك[w:9728[ُم م]ُّسْتَمِع[p[ُو]نَ","У зот: «Йўқ! Бас, иккингиз Бизнинг оят-мўъжизаларимиз ила боринглар. Албатта, Биз иккингиз билан эшитгувчилармиз.",367,19],["فَأْتِيَا فِرْعَوْنَ فَقُول[o[َآ] إِ[g[نّ]َا رَسُولُ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Бас, Фиръавнга боринглар ва унга: «Биз Роббул Оламийннинг Пайғамбарларимиз.",367,19],["أَنْ أَرْسِلْ مَعَنَا بَن[o[ِىٓ] إِسْر[o[َٲ]ٓء[p[ِي]لَ","Бани Исроилни биз билан қўйиб юбор», деб айтинглар, деди.",367,19],["قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِي[a:9729[دًا و]َلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِن[p[ِي]نَ","У: «Биз сени гўдаклигингдан ўз ичимизда тарбия қилмадикми?! Умрингнинг бир неча йилини бизнинг ичимизда ўтказмадингми?!",367,19],["وَفَعَلْتَ فَعْلَتَكَ [h:9730[ٱ]لَّتِى فَعَلْتَ وَأَ[f:3893[نت]َ مِنَ [h:182[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Ва нонкўрлардан бўлиб, қиладиган ишингни қилиб қўймадингми?!» деди.",367,19],["قَالَ فَعَلْتُه[o[َآ] إِ[a:9731[ذًا و]َأَنَا۟ مِنَ [h:9732[ٱ][l[ل]ضّ[m[َا]ٓلّ[p[ِي]نَ",": «Ўша ишни қилган бўлсам, билмасдан қилганман.",368,19],["فَفَرَرْتُ مِ[f:344[نك]ُمْ لَ[g[مّ]َا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْ[a:9733[مًا و]َجَعَلَنِى مِنَ [h:4822[ٱ]لْمُرْسَل[p[ِي]نَ","Бас, сизлардан хавфсираб қочиб кетдим. Кейин Аллоҳ менга ҳикмат берди ва мени Пайғамбарлардан қилди.",368,19],["وَتِلْكَ نِعْمَ[f:9734[ةٌ ت]َمُ[g[نّ]ُهَا عَلَىَّ أَنْ عَبَّ[d:9735[د]تَّ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓء[p[ِي]لَ","Ўша менга қилаётган миннатинг Бани Исроилни қул қилиб олганингдандир», деди.",368,19],["قَالَ فِرْعَوْنُ وَمَا رَبُّ [h:4750[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Фиръавн: «Роббул Оламийн нима?» деди.",368,19],["قَالَ رَبُّ [h:6926[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَيْنَهُم[o[َآ‌ۖ] إِ[f:109[ن ك]ُ[f:100[نت][w:9736[ُم م]ُّوقِن[p[ِي]نَ","У: «Агар англамоқчи бўлсангиз, У осмонлару ер ва уларнинг орасидаги нарсаларнинг Роббидир», деди.",368,19],["قَالَ لِمَنْ حَوْلَهُ[o[ۥٓ] أَلَا تَسْتَمِع[p[ُو]نَ","У атрофидаги кишиларга: «Эшитмаяпсизларми?!» деди.",368,19],["قَالَ رَبُّكُمْ وَرَبُّ ءَاب[o[َا]ٓئِكُمُ [h:9737[ٱ]لْأَوَّل[p[ِي]نَ","У: « У зот сизнинг Роббингиз ва аввалги ота-боболарингизнинг Роббидир», деди.",368,19],["قَالَ إِ[g[نّ]َ رَسُولَكُمُ [h:9738[ٱ]لَّذ[o[ِىٓ] أُرْسِلَ إِلَيْكُمْ لَمَ[q:7198[جْ]ن[p[ُو]نٌ","У: «Албатта, сизга юборилган Пайғамбарингиз жиннидир», деди.",368,19],["قَالَ رَبُّ [h:9739[ٱ]لْمَشْرِقِ وَ[h:904[ٱ]لْمَغْرِبِ وَمَا بَيْنَهُم[o[َآ‌ۖ] إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْقِل[p[ُو]نَ","У: «У, агар ақл юритсангиз, машриқу мағрибнинг ва улар ўртасидаги нарсаларнинг Роббидир», деди.",368,19],["قَالَ لَئِنِ [h:9740[ٱ]تَّخَذْتَ إِلَ[n[ـٰ]هًا غَيْرِى لَأَ[q:9741[جْ]عَلَ[g[نّ]َكَ مِنَ [h:9742[ٱ]لْمَسْجُون[p[ِي]نَ","У: «Агар мендан бошқани илоҳ қилиб олсанг, албатта, мен сени зиндонбандлардан қилурман», деди.",368,19],["قَالَ أَوَلَوْ جِئْتُكَ بِش[a:9743[َىْءٍ م]ُّب[p[ِي]نٍ","У: «Агар мен сенга очиқ-ойдин нарса келтирсам ҳам-а?!» деди.",368,19],["قَالَ فَأْتِ بِه[o[ِۦٓ] إِ[f:4792[ن ك]ُ[f:735[نت]َ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","У: «Агар ростгўйлардан бўлсанг, келтир уни!» деди.",368,19],["فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَا[a:4912[نٌ م]ُّب[p[ِي]نٌ","Бас, у асосини ташлади. Баногоҳ у аниқ аждарга айланди.",368,19],["وَنَزَعَ يَدَهُ[n[ۥ] فَإِذَا هِىَ بَيْض[o[َا]ٓءُ لِل[g[نّ]َ[n[ـٰ]ظِر[p[ِي]نَ","Ва қўлини чиқарди. Банагоҳ у назар қилгувчиларга оппоқ кўринди.",368,19],["قَالَ لِلْمَلَإِ حَوْلَهُ[o[ۥٓ] إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَسَ[n[ـٰ]حِرٌ عَل[p[ِي]مٌ","У атрофидаги аъёнларига: «Албатта, бу ўта билимдон сеҳргардир.",368,19],["يُرِيدُ أ[a:4914[َن ي]ُخْرِجَك[w:4915[ُم م]ِّنْ أَرْضِك[c:9744[ُم ب]ِسِحْرِه[n[ِۦ] فَمَاذَا تَأْمُر[p[ُو]نَ","У ўз сеҳри билан сизларни ерингиздан чиқармоқчи, нима дейсизлар?», деди.",368,19],["قَال[o[ُوٓ][s[اْ] أَرْجِهْ وَأَخَاهُ وَ[h:676[ٱ][q:676[بْ]عَثْ فِى [h:4916[ٱ]لْمَد[o[َا]ٓئِنِ حَ[n[ـٰ]شِر[p[ِي]نَ","Улар: «Уни ва акасини қўйиб тургин-да, шаҳарларга тўпловчиларни юбор.",368,19],["يَأْتُوكَ بِكُلِّ سَحَّارٍ عَل[p[ِي]مٍ","Сенга барча ўта билимдон сеҳргарларни олиб келсинлар», дедилар.",368,19],["فَجُمِعَ [h:9745[ٱ][l[ل]سَّحَرَةُ لِمِيقَ[n[ـٰ]تِ يَوْ[a:9746[مٍ م]َّعْل[p[ُو]مٍ","Бас, сеҳргарлар маълум куни келишилган вақтда жамландилар.",368,19],["وَقِيلَ لِل[g[نّ]َاسِ هَلْ أَ[f:428[نت][w:9747[ُم م]ُّ[q:9748[جْ]تَمِع[p[ُو]نَ","Ва одамларга: «Сизлар тўпланиб бўлдингизми?",368,19],["لَعَلَّنَا نَتَّبِعُ [h:9749[ٱ][l[ل]سَّحَرَةَ إِ[f:5674[ن ك]َانُو[s[اْ] هُمُ [h:9750[ٱ]لْغَ[n[ـٰ]لِب[p[ِي]نَ","Ажаб эрмас, устин келсалар, сеҳргарларга эргашсак», дейилди.",369,19],["فَلَ[g[مّ]َا ج[o[َا]ٓءَ [h:6148[ٱ][l[ل]سَّحَرَةُ قَالُو[s[اْ] لِفِرْعَوْنَ أَئِ[g[نّ]َ لَنَا لَأَ[q:4918[جْ]رًا إِ[f:4919[ن ك]ُ[g[نّ]َا نَحْنُ [h:4920[ٱ]لْغَ[n[ـٰ]لِب[p[ِي]نَ","Сеҳргарлар келган чоғларида Фиръавнга: «Агар биз ғолиб келгувчи бўлсак, бизга, албатта, ҳақ бериладими?» дедилар.",369,19],["قَالَ نَعَمْ وَإِ[g[نّ]َكُمْ إِ[u:765[ذًا ل]َّمِنَ [h:4921[ٱ]لْمُقَرَّب[p[ِي]نَ","У: «Ҳа! У ҳолда сиз, албатта, энг яқинларимдан бўласиз», деди.",369,19],["قَالَ لَه[w:6149[ُم م]ُّوسَ[o[ىٰٓ] أَلْقُو[s[اْ] م[o[َآ] أَ[f:428[نت][w:6150[ُم م]ُّلْق[p[ُو]نَ","Мусо уларга: «Сиз ташлайдиган нарсангизни ташланг», деди.",369,19],["فَأَلْقَوْ[s[اْ] حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُو[s[اْ] بِعِزَّةِ فِرْعَوْنَ إِ[g[نّ]َا لَنَحْنُ [h:9751[ٱ]لْغَ[n[ـٰ]لِب[p[ُو]نَ","Бас, улар арқонлари ва асоларини ташладилар ва «Фиръавннинг иззати билан қасамки, албатта, биз ғолиблармиз», дедилар.",369,19],["فَأَلْقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِك[p[ُو]نَ","Сўнгра Мусо асосини ташлаган эди, бирдан у уларнинг уйдирмаларини юта бошлади.",369,19],["فَأُلْقِىَ [h:8533[ٱ][l[ل]سَّحَرَةُ سَ[n[ـٰ]جِد[p[ِي]نَ","Бас, сеҳргарлар сажда қилган ҳолларида йиқилдилар.",369,19],["قَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا بِرَبِّ [h:4930[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Улар: «Роббул Оламийнга иймон келтирдик.",369,19],["رَبِّ مُوسَىٰ وَهَ[n[ـٰ]ر[p[ُو]نَ","Мусо ва Ҳоруннинг Роббига», дедилар.",369,19],["قَالَ ءَامَ[f:703[نت]ُمْ لَهُ[n[ۥ] قَ[q:3282[بْ]لَ أَنْ ءَاذَنَ لَكُمْ‌ۖ إِ[g[نّ]َهُ[n[ۥ] لَكَبِيرُكُمُ [h:8535[ٱ]لَّذِى عَلَّمَكُمُ [h:8536[ٱ][l[ل]سِّحْرَ فَلَسَوْفَ تَعْلَمُونَ‌ۚ لَأُقَطِّعَ[g[نّ]َ أَيْدِيَكُمْ وَأَرْجُلَك[w:4933[ُم م]ِّنْ خِلَ[n[ـٰ][a:8537[فٍ و]َلَأُصَلِّبَ[g[نّ]َكُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","У: «Мен сизга изн бермасимдан олдин унга иймон келтирдингиз! Албатта, у сизга сеҳр ўргатган каттангиздир! Энди тезда биласиз, мен, албатта, қўл-оёғингизни қарама-қарши томонидан кесажакман ва барчангизни осажакман», деди.",369,19],["قَالُو[s[اْ] لَا ضَيْرَ‌ۖ إِ[g[نّ][o[َآ] إِلَىٰ رَبِّنَا مُ[f:4935[نق]َلِب[p[ُو]نَ","Улар: «Зарари йўқ. Албатта, биз Роббимизга қайтгувчимиз.",369,19],["إِ[g[نّ]َا نَ[q:9752[طْ]مَعُ أ[a:9371[َن ي]َغْفِرَ لَنَا رَبُّنَا خَطَ[n[ـٰ]يَ[n[ـٰ]ن[o[َآ] أَ[f:9753[ن ك]ُ[g[نّ][o[َآ] أَوَّلَ [h:9754[ٱ]لْمُؤْمِن[p[ِي]نَ","Мўминларнинг аввалгиси бўлганимиз учун Роббимиз хатоларимизни кечиришидан умид қиламиз», дедилар.",369,19],["۞ وَأَوْحَيْن[o[َآ] إِلَىٰ مُوسَ[o[ىٰٓ] أَنْ أَسْرِ بِعِبَاد[o[ِىٓ] إِ[g[نّ]َك[w:9755[ُم م]ُّتَّبَع[p[ُو]نَ","Ва Мусога: «Бандаларим билан кечаси йўлга чиқ. Албатта, таъқиб этилурсиз», деб ваҳий юбордик.",369,19],["فَأَرْسَلَ فِرْعَوْنُ فِى [h:4916[ٱ]لْمَد[o[َا]ٓئِنِ حَ[n[ـٰ]شِر[p[ِي]نَ","Бас, Фиръавн шаҳарларга тўпловчилар юборди:",369,19],["إِ[g[نّ]َ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ لَشِرْذِمَ[f:9756[ةٌ ق]َلِيل[p[ُو]نَ","«Шубҳасиз, анавилар озгина тоифадирлар.",369,19],["وَإِ[g[نّ]َهُمْ لَنَا لَغ[o[َا]ٓئِظ[p[ُو]نَ","Албатта, улар бизни ғазаблантиргувчилардир.",369,19],["وَإِ[g[نّ]َا لَجَمِيعٌ حَ[n[ـٰ]ذِر[p[ُو]نَ","Албатта, биз ҳаммамиз ҳушёрмиз», деб.",369,19],["فَأَخْرَ[q:9757[جْ]نَ[n[ـٰ]ه[w:9758[ُم م]ِّ[f:9759[ن ج]َ[g[نّ]َ[n[ـٰ][a:7257[تٍ و]َعُي[p[ُو]نٍ","Бас, Биз уларни боғ-роғлар ва булоқлардан.",369,19],["وَكُنُو[a:9760[زٍ و]َمَقَا[f:9761[مٍ ك]َر[p[ِي]مٍ","Хазиналар ва муҳтарам маскандан чиқардик.",369,19],["كَذ[n[َٲ]لِكَ وَأَوْرَثْنَ[n[ـٰ]هَا بَن[o[ِىٓ] إِسْر[o[َٲ]ٓء[p[ِي]لَ","Ана шундай. Ўшаларни Бани Исроилга мерос қилиб бердик.",369,19],["فَأَتْبَعُوه[w:9762[ُم م]ُّشْرِق[p[ِي]نَ","Бас, уларни қуёш чиқиш пайтида қувиб етдилар.",369,19],["فَلَ[g[مّ]َا تَر[o[َٲ]ٓءَا [h:9763[ٱ]لْجَمْعَانِ قَالَ أَصْحَ[n[ـٰ]بُ مُوسَ[o[ىٰٓ] إِ[g[نّ]َا لَمُ[q:9764[دْ]رَك[p[ُو]نَ","Икки жамоат бир-бирларини кўрган чоғида, Мусонинг одамлари: «Энди қўлга тушдик», дедилар.",370,19],["قَالَ كَلّ[o[َآ‌ۖ] إِ[g[نّ]َ مَعِىَ رَبِّى سَيَهْد[p[ِي]نِ","У:»Йўқ! Албатта, Роббим мен билан, У менга тўғри йўлни кўрсатур«, деди.",370,19],["فَأَوْحَيْن[o[َآ] إِلَىٰ مُوسَ[o[ىٰٓ] أَنِ [h:5080[ٱ]ضْرِب بِّعَصَاكَ [h:9765[ٱ]لْبَحْرَ‌ۖ فَ[h:9766[ٱ][f:9766[نف]َلَقَ فَكَانَ كُلُّ فِرْ[f:9767[قٍ ك]َ[h:9768[ٱ][l[ل]طَّوْدِ [h:9769[ٱ]لْعَظ[p[ِي]مِ","Бас, Биз Мусога: «Асонг билан денгизни ур», деб ваҳий қилдик. Бас, у бўлиниб, ҳар бўлаги улкан тоғдек бўлди.",370,19],["وَأَزْلَفْنَا ثَ[g[مّ]َ [h:9770[ٱ]لْأَخَر[p[ِي]نَ","Ва кейин бошқаларни ҳам яқинлаштирдик.",370,19],["وَأَ[f:9771[نج]َيْنَا مُوسَىٰ وَم[a:4948[َن م]َّعَهُ[o[ۥٓ] أَ[q:825[جْ]مَع[p[ِي]نَ","Мусо ва унга эргашганларга, ҳаммаларига нажот бердик.",370,19],["ثُ[g[مّ]َ أَغْرَ[q:9772[قْ]نَا [h:9773[ٱ]لْأَخَر[p[ِي]نَ","Сўнгра бошқаларни ғарқ қилдик.",370,19],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[a:9716[ةً‌ۖ و]َمَا كَانَ أَكْثَرُه[w:9717[ُم م]ُّؤْمِن[p[ِي]نَ","Албатта, бунда оят-белги бор. Лекин кўплари мўмин бўлмадилар.",370,19],["وَإِ[g[نّ]َ رَبَّكَ لَهُوَ [h:1987[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Албатта, Роббинг Ўзи азизу меҳрибондир.",370,19],["وَ[h:9999[ٱ]تْلُ عَلَيْهِمْ نَبَأَ إِ[q:1860[بْ]ر[n[َٲ]ه[p[ِي]مَ","Ва уларга Иброҳимнинг хабарини тиловат қилиб бер.",370,19],["إِذْ قَالَ لِأَبِيهِ وَقَوْمِه[n[ِۦ] مَا تَعْبُد[p[ُو]نَ","Ўшанда у отаси ва қавмига: «Нимага ибодат қилмоқдасизлар?» деган эди.",370,19],["قَالُو[s[اْ] نَعْبُدُ أَصْنَا[f:9774[مًا ف]َنَظَلُّ لَهَا عَ[n[ـٰ]كِف[p[ِي]نَ","Улар: «Санамларга ибодат қилмоқдамиз. Ва уларга ихлос ила ибодат қилишда бардавом бўлурмиз», дедилар.",370,19],["قَالَ هَلْ يَسْمَعُونَكُمْ إِذْ تَ[q:4040[دْ]ع[p[ُو]نَ","У: «Илтижо қилганингизда улар сизни эшитадиларми?",370,19],["أَوْ يَ[f:9775[نف]َعُونَكُمْ أَوْ يَضُرّ[p[ُو]نَ","Ёхуд наф ёки зарар етказа оладиларми?» деди.",370,19],["قَالُو[s[اْ] بَلْ وَجَ[q:3834[دْ]ن[o[َآ] ءَاب[o[َا]ٓءَنَا كَذ[n[َٲ]لِكَ يَفْعَل[p[ُو]نَ","Улар: «Йўқ, биз ота-боболаримизни шундай қилаётганларини кўрдик», дедилар.",370,19],["قَالَ أَفَرَءَيْت[w:9776[ُم م]َّا كُ[f:100[نت]ُمْ تَعْبُد[p[ُو]نَ","У: «Нимага ибодат қилаётганингизни билдингизми?!",370,19],["أَ[f:428[نت]ُمْ وَءَاب[o[َا]ٓؤُكُمُ [h:9777[ٱ]لْأَ[q:9778[قْ]دَم[p[ُو]نَ","Сиз ва қадимги оталарингиз?!",370,19],["فَإِ[g[نّ]َهُمْ عَدُ[u:8477[وٌّ ل]ّ[o[ِىٓ] إِلَّا رَبَّ [h:3505[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Албатта, Роббул Оламийндан бошқа уларнинг барчаси менга душмандир», деди.",370,19],["ٱلَّذِى خَلَقَنِى فَهُوَ يَهْد[p[ِي]نِ","У мени яратган зотдир. Бас, мени ҳидоят қилади ҳам Унинг Ўзи.",370,19],["وَ[h:9999[ٱ]لَّذِى هُوَ يُ[q:9779[طْ]عِمُنِى وَيَسْق[p[ِي]نِ","Ва мени таомлантирадиган ва суғорадиган ҳам Унинг Ўзи.",370,19],["وَإِذَا مَرِضْتُ فَهُوَ يَشْف[p[ِي]نِ","Бемор бўлганимда менга шифо берадиган ҳам Унинг Ўзи.",370,19],["وَ[h:9999[ٱ]لَّذِى يُمِيتُنِى ثُ[g[مّ]َ يُحْي[p[ِي]نِ","Мени ўлдирадиган, сўнгра тирилтирадиган ҳам Унинг Ўзи.",370,19],["وَ[h:9999[ٱ]لَّذ[o[ِىٓ] أَ[q:9780[طْ]مَعُ أ[a:9371[َن ي]َغْفِرَ لِى خَطِ[o[يٓ]ــَٔتِى يَوْمَ [h:9781[ٱ][l[ل]دّ[p[ِي]نِ","Ва менинг хатоимни қиёмат куни мағфират қилишидан умидвор бўлганим ҳам Унинг Ўзи.",370,19],["رَبِّ هَ[q:1878[بْ] لِى حُكْ[a:9782[مًا و]َأَلْحِ[q:6835[قْ]نِى بِ[h:6836[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Эй Роббим, менга ҳикмат ҳадя эт ва мени солиҳларга қўшгин.",370,19],["وَ[h:9999[ٱ][q:2930[جْ]عَل لِّى لِسَانَ صِ[q:5937[دْ][f:9783[قٍ ف]ِى [h:9784[ٱ]لْأَخِر[p[ِي]نَ","Ва менга кейин келгувчилар ичида содиқ мақтовлар бўладиган қилгин.",371,19],["وَ[h:9999[ٱ][q:9785[جْ]عَلْنِى م[a:9786[ِن و]َرَثَةِ جَ[g[نّ]َةِ [h:9787[ٱ][l[ل][g[نّ]َع[p[ِي]مِ","Ва мени наъийм жаннати ворисларидан қилгин.",371,19],["وَ[h:9999[ٱ]غْفِرْ لِأَب[o[ِىٓ] إِ[g[نّ]َهُ[n[ۥ] كَانَ مِنَ [h:9732[ٱ][l[ل]ضّ[m[َا]ٓلّ[p[ِي]نَ","Ва отамни мағфират қил. Албатта, у адашганлардан бўлди.",371,19],["وَلَا تُخْزِنِى يَوْمَ يُ[q:4606[بْ]عَث[p[ُو]نَ","Ва қайта тирилтириладиган кунда мени шарманда қилмагин.",371,19],["يَوْمَ لَا يَ[f:838[نف]َعُ مَا[a:9788[لٌ و]َلَا بَن[p[ُو]نَ","У кунда на мол манфаат берар ва на болалар.",371,19],["إِلَّا مَنْ أَتَى [h:9789[ٱ]للَّهَ بِقَلْ[f:9790[بٍ س]َل[p[ِي]مٍ","Магар ким Аллоҳ ҳузурига тоза қалб ила келар,.",371,19],["وَأُزْلِفَتِ [h:9791[ٱ]لْجَ[g[نّ]َةُ لِلْمُتَّق[p[ِي]نَ","Ва жаннат тақводорларга яқинлаштирилди.",371,19],["وَبُرِّزَتِ [h:9792[ٱ]لْجَحِيمُ لِلْغَاو[p[ِي]نَ","Жаҳийм иғвога учганларга зоҳир қилинди.",371,19],["وَقِيلَ لَهُمْ أَيْنَ مَا كُ[f:100[نت]ُمْ تَعْبُد[p[ُو]نَ","Ва уларга:»Аллоҳдан ўзга ибодат қилиб юрган нарсаларингиз қани?!",371,19],["مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ هَلْ يَ[f:9793[نص]ُرُونَكُمْ أَوْ يَ[f:9794[نت]َصِر[p[ُو]نَ","Улар сизга ёрдам бера олурларми ёки ўзларини қутқара олурларми?! « дейилди.",371,19],["فَكُ[q:9795[بْ]كِبُو[s[اْ] فِيهَا هُمْ وَ[h:9796[ٱ]لْغَاوُ[p[ۥ]نَ","Бас, унга улар, иғвога учганлар.",371,19],["وَجُنُودُ إِ[q:180[بْ]لِيسَ أَ[q:7239[جْ]مَع[p[ُو]نَ","Ва Иблиснинг аскарлари биргаликда юзтубан тахлаб ташландилар.",371,19],["قَالُو[s[اْ] وَهُمْ فِيهَا يَخْتَصِم[p[ُو]نَ","Улар унинг ичида бир-бирлари ила хусумат қилар эканлар, дедилар:",371,19],["تَ[h:9999[ٱ]للَّهِ إِ[f:4919[ن ك]ُ[g[نّ]َا لَفِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","«Аллоҳга қасамки, албатта, биз очиқ-ойдин адашувда эканмиз.",371,19],["إِذْ نُسَوِّيك[c:9797[ُم ب]ِرَبِّ [h:4930[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Чунки сизларни Роббул Оламийнга тенглаштирардик.",371,19],["وَم[o[َآ] أَضَلَّن[o[َآ] إِلَّا [h:9798[ٱ]لْمُ[q:5255[جْ]رِم[p[ُو]نَ","Бизни фақат жиноятчилар йўлдан оздирдилар.",371,19],["فَمَا لَنَا مِ[f:9799[ن ش]َ[n[ـٰ]فِع[p[ِي]نَ","Мана энди биз учун шафоатчилар ҳам йўқ.",371,19],["وَلَا صَدِيقٍ حَم[p[ِي]مٍ","Бирон қадрдон дўст ҳам йўқ.",371,19],["فَلَوْ أَ[g[نّ]َ لَنَا كَرَّ[f:9800[ةً ف]َنَكُونَ مِنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Қани энди ортга қайтсагу мўминлардан бўлсак».",371,19],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[a:9716[ةً‌ۖ و]َمَا كَانَ أَكْثَرُه[w:9717[ُم م]ُّؤْمِن[p[ِي]نَ","Албатта, бунда оят-белги бор. Лекин кўплари мўмин бўлмадилар.",371,19],["وَإِ[g[نّ]َ رَبَّكَ لَهُوَ [h:1987[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Албатта, Роббинг Ўзи азизу меҳрибондир.",371,19],["كَذَّبَتْ قَوْمُ نُوحٍ [h:9801[ٱ]لْمُرْسَل[p[ِي]نَ","Нуҳ қавми Пайғамбарларни ёлғончи қилди.",371,19],["إِذْ قَالَ لَهُمْ أَخُوهُمْ نُوحٌ أَلَا تَتَّق[p[ُو]نَ","Ўшанда уларга биродарлари Нуҳ деди: «У зотдан қўрқмайсизми?!",371,19],["إِ[g[نّ]ِى لَكُمْ رَسُولٌ أَم[p[ِي]نٌ","Албатта, мен сизларга ишончли Пайғамбарман.",371,19],["فَ[h:9999[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَطِيع[p[ُو]نِ","Бас, Аллоҳдан қўрқинглар ва менга итоат қилинглар.",371,19],["وَم[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ مِنْ أَ[q:6133[جْ]رٍ‌ۖ إِنْ أَ[q:6134[جْ]رِىَ إِلَّا عَلَىٰ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Мен сизлардан бунинг учун ҳақ-ажр сўрамасман. Менинг ажрим фақатгина Роббул Оламийннинг зиммасидадир.",371,19],["فَ[h:9999[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَطِيع[p[ُو]نِ","Бас, Аллоҳдан қўрқинглар ва менга итоат қилинглар».",371,19],["۞ قَال[o[ُوٓ][s[اْ] أَنُؤْمِنُ لَكَ وَ[h:9802[ٱ]تَّبَعَكَ [h:9803[ٱ]لْأَرْذَل[p[ُو]نَ","Улар: «Сенга пасткашлар эргашиб турган ҳолда, биз сенга иймон келтирармидик?!» дедилар.",371,19],["قَالَ وَمَا عِلْمِى بِمَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","У деди: «Менинг улар нима қилаётганлари ҳақида илмим йўқ.",372,19],["إِنْ حِسَابُهُمْ إِلَّا عَلَىٰ رَبِّى‌ۖ لَوْ تَشْعُر[p[ُو]نَ","Агар сезсангиз, уларнинг ҳисоби фақат Аллоҳнинг зиммасидадир.",372,19],["وَم[o[َآ] أَنَا۟ بِطَارِدِ [h:9804[ٱ]لْمُؤْمِن[p[ِي]نَ","Ва мен мўминларни ҳайдаб юборгувчи эмасман.",372,19],["إِنْ أَنَا۟ إِلَّا نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","Мен фақат очиқ-ойдин огоҳлантиргувчиман, холос».",372,19],["قَالُو[s[اْ] لَئ[u:4195[ِن ل]َّمْ تَ[f:8352[نت]َهِ يَ[n[ـٰ]نُوحُ لَتَكُونَ[g[نّ]َ مِنَ [h:9805[ٱ]لْمَرْجُوم[p[ِي]نَ","Улар: «Эй Нуҳ, агар тўхтамасанг, албатта, тошбўрон қилинганлардан бўлурсан», дедилар.",372,19],["قَالَ رَبِّ إِ[g[نّ]َ قَوْمِى كَذَّب[p[ُو]نِ","У: «Эй Роббим, шубҳасиз, қавмим мени ёлғончи қилдилар.",372,19],["فَ[h:9999[ٱ]فْتَحْ بَيْنِى وَبَيْنَهُمْ فَتْ[a:9806[حًا و]َنَجِّنِى وَم[a:9807[َن م]َّعِىَ مِنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Бас, Ўзинг мен билан уларнинг орамизни яхшилаб очгин ва менга ҳамда мен билан бирга бўлган мўминларга нажот бергин», деди.",372,19],["فَأَ[f:4779[نج]َيْنَ[n[ـٰ]هُ وَم[a:4948[َن م]َّعَهُ[n[ۥ] فِى [h:4780[ٱ]لْفُلْكِ [h:9808[ٱ]لْمَشْح[p[ُو]نِ","Бас, Биз унга ва у билан бирга бўлганларга тўлган кемада нажот бердик.",372,19],["ثُ[g[مّ]َ أَغْرَ[q:9772[قْ]نَا بَعْدُ [h:9809[ٱ]لْبَاق[p[ِي]نَ","Сўнгра қолганларни ғарқ қилдик.",372,19],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[a:9716[ةً‌ۖ و]َمَا كَانَ أَكْثَرُه[w:9717[ُم م]ُّؤْمِن[p[ِي]نَ","Албатта, бунда оят-белги бор. Лекин кўплари мўмин бўлмадилар.",372,19],["وَإِ[g[نّ]َ رَبَّكَ لَهُوَ [h:1987[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Албатта, Роббинг Ўзи азизу меҳрибондир.",372,19],["كَذَّبَتْ عَادٌ [h:9810[ٱ]لْمُرْسَل[p[ِي]نَ","Од қавми Пайғамбарларни ёлғончи қилди.",372,19],["إِذْ قَالَ لَهُمْ أَخُوهُمْ هُودٌ أَلَا تَتَّق[p[ُو]نَ","Ўшанда уларга биродарлари Ҳуд деди: «Қўрқмайсизларми?!",372,19],["إِ[g[نّ]ِى لَكُمْ رَسُولٌ أَم[p[ِي]نٌ","Албатта, мен сизларга ишончли Пайғамбарман.",372,19],["فَ[h:9999[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَطِيع[p[ُو]نِ","Бас, Аллоҳдан қўрқинглар ва менга итоат қилинглар.",372,19],["وَم[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ مِنْ أَ[q:6133[جْ]رٍ‌ۖ إِنْ أَ[q:6134[جْ]رِىَ إِلَّا عَلَىٰ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Мен сизлардан бунинг учун ҳақ-ажр сўрамасман. Менинг ажрим фақатгина Роббул Оламийн зиммасидадир.",372,19],["أَتَ[q:9811[بْ]نُونَ بِكُلِّ رِيعٍ ءَايَ[f:9812[ةً ت]َعْبَث[p[ُو]نَ","Ҳар тепаликка бир белги бўладиган бино қуриб, беҳуда ўйин қилаверасизми?",372,19],["وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُد[p[ُو]نَ","Ва худди мангу туражакдек «маснаълар» тутаверасизми?.",372,19],["وَإِذَا بَطَشْت[c:9813[ُم ب]َطَشْتُمْ جَبَّار[p[ِي]نَ","Тутганингизда ўта жабрчи бўлиб тутдингиз.",372,19],["فَ[h:9999[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَطِيع[p[ُو]نِ","Бас, Аллоҳдан қўрқинг ва менга итоат қилинг.",372,19],["وَ[h:9999[ٱ]تَّقُو[s[اْ] [h:9814[ٱ]لَّذ[o[ِىٓ] أَمَدَّك[c:9815[ُم ب]ِمَا تَعْلَم[p[ُو]نَ","Сизга ўзингиз билган нарса ила мадад берган зотдан қўрқинг.",372,19],["أَمَدَّك[c:9816[ُم ب]ِأَنْعَ[n[ـٰ][a:9817[مٍ و]َبَن[p[ِي]نَ","У сизларга чорва ҳайвонлари ва фарзандлар ила мадад берди.",372,19],["وَجَ[g[نّ]َ[n[ـٰ][a:9818[تٍ و]َعُي[p[ُو]نٍ","Боғ-роғлар ва булоқлар ила.",372,19],["إِ[g[نّ][o[ِىٓ] أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظ[p[ِي]مٍ","Мен, албатта, сизга улуғ куннинг азоби келишидан қўрураман».",372,19],["قَالُو[s[اْ] سَو[o[َا]ٓءٌ عَلَيْن[o[َآ] أَوَعَظْتَ أَمْ لَمْ تَك[a:1974[ُن م]ِّنَ [h:9819[ٱ]لْو[n[َٲ]عِظ[p[ِي]نَ","Улар: «Биз учун ваъз қилсанг ҳам ёки ваъз қилгувчилардан бўлмасанг ҳам, барибир.",372,19],["إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا خُلُقُ [h:9820[ٱ]لْأَوَّل[p[ِي]نَ","Бу эскиларнинг одати, холос.",373,19],["وَمَا نَحْنُ بِمُعَذَّب[p[ِي]نَ","Биз азоблангувчи эмасмиз», дедилар.",373,19],["فَكَذَّبُوهُ فَأَهْلَكْنَ[n[ـٰ]هُمْ‌ۗ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[a:9716[ةً‌ۖ و]َمَا كَانَ أَكْثَرُه[w:9717[ُم م]ُّؤْمِن[p[ِي]نَ","Улар уни ёлғончи қилдилар. Бас, Биз уларни ҳалок қилдик. Албатта, бунда оят-белги бор. Лекин кўплари мўмин бўлмадилар.",373,19],["وَإِ[g[نّ]َ رَبَّكَ لَهُوَ [h:1987[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Албатта, Роббинг Ўзи азизу меҳрибондир.",373,19],["كَذَّبَتْ ثَمُودُ [h:9821[ٱ]لْمُرْسَل[p[ِي]نَ","Самуд қавми Пайғамбарларни ёлғончи қилди.",373,19],["إِذْ قَالَ لَهُمْ أَخُوهُمْ صَ[n[ـٰ]لِحٌ أَلَا تَتَّق[p[ُو]نَ","Ўшанда уларга биродарлари Солиҳ деди: «Қўрқмайсизларми?!",373,19],["إِ[g[نّ]ِى لَكُمْ رَسُولٌ أَم[p[ِي]نٌ","Албатта, мен сизларга ишончли Пайғамбарман.",373,19],["فَ[h:9999[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَطِيع[p[ُو]نِ","Бас, Аллоҳдан қўрқинглар ва менга итоат қилинглар.",373,19],["وَم[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ مِنْ أَ[q:6133[جْ]رٍ‌ۖ إِنْ أَ[q:6134[جْ]رِىَ إِلَّا عَلَىٰ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Мен сизлардан бунинг учун ҳақ-ажр сўрамасман. Менинг ажрим фақатгина Роббул оламийн зиммасидадир.",373,19],["أَتُتْرَكُونَ فِى مَا هَ[n[ـٰ]هُن[o[َآ] ءَامِن[p[ِي]نَ","Сиз бу жойдаги нарсаларда омон ҳолда тарк қилинасизми?!",373,19],["فِى جَ[g[نّ]َ[n[ـٰ][a:7257[تٍ و]َعُي[p[ُو]نٍ","Боғ-роғларда, булоқларда?!",373,19],["وَزُرُو[a:9822[عٍ و]َنَخْ[f:9823[لٍ ط]َلْعُهَا هَض[p[ِي]مٌ","Экинзорлару майин хурмозор ичларида-я?!",373,19],["وَتَنْحِتُونَ مِنَ [h:7297[ٱ]لْجِبَالِ بُيُو[f:9824[تًا ف]َ[n[ـٰ]رِه[p[ِي]نَ","Ва тоғлардан манманлик-ла уйлар йўнаверасизми?!",373,19],["فَ[h:9999[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَطِيع[p[ُو]نِ","Бас, Аллоҳдан қўрқинглар ва менга итоат қилинглар.",373,19],["وَلَا تُطِيع[o[ُوٓ][s[اْ] أَمْرَ [h:9825[ٱ]لْمُسْرِف[p[ِي]نَ","Ва ер юзида исрофчилик қиладиганларнинг ишига итоат қилманглар.",373,19],["ٱلَّذِينَ يُفْسِدُونَ فِى [h:44[ٱ]لْأَرْضِ وَلَا يُصْلِح[p[ُو]نَ","Бузғунчилик қиладиган, ислоҳчилик этмайдиганларнинг».",373,19],["قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َم[o[َآ] أَ[f:169[نت]َ مِنَ [h:9826[ٱ]لْمُسَحَّر[p[ِي]نَ","Улар: «Сен, албатта, сеҳрланганлардандирсан.",373,19],["م[o[َآ] أَ[f:169[نت]َ إِلَّا بَشَ[a:7065[رٌ م]ِّثْلُنَا فَأْتِ بِـَٔـايَةٍ إِ[f:4792[ن ك]ُ[f:735[نت]َ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","Сен бизга ўхшаган башардан бошқа ҳеч нарса эмассан. Агар ростгўйлардан бўлсанг, оят-мўъжиза келтир», дедилар.",373,19],["قَالَ هَ[n[ـٰ]ذِه[n[ِۦ] نَاقَ[u:9827[ةٌ ل]َّهَا شِرْ[a:9828[بٌ و]َلَكُمْ شِرْبُ يَوْ[a:9746[مٍ م]َّعْل[p[ُو]مٍ","У: «Мана бу туя. Унга сув ичиш ва сизга маълум бир кун сув ичиш.",373,19],["وَلَا تَمَسُّوهَا بِس[o[ُو]ٓ[f:4810[ءٍ ف]َيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظ[p[ِي]مٍ","Ва унга ёмонлик етказманглар, унда сизни улуғ куннинг азоби тутадир», деди.",373,19],["فَعَقَرُوهَا فَأَصْبَحُو[s[اْ] نَ[n[ـٰ]دِم[p[ِي]نَ","Бас, уни сўйдилару надомат чекувчига айландилар.",373,19],["فَأَخَذَهُمُ [h:7618[ٱ]لْعَذَابُ‌ۗ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[a:9716[ةً‌ۖ و]َمَا كَانَ أَكْثَرُه[w:9717[ُم م]ُّؤْمِن[p[ِي]نَ","Бас, уларни азоб тутди. Албатта, бунда оят-белги бор. Лекин кўплари мўмин бўлмадилар.",373,19],["وَإِ[g[نّ]َ رَبَّكَ لَهُوَ [h:1987[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Албатта, Роббинг Ўзи азизу меҳрибондир.",373,19],["كَذَّبَتْ قَوْمُ لُوطٍ [h:9829[ٱ]لْمُرْسَل[p[ِي]نَ","Лут қавми Пайғамбарларни ёлғончи қилди.",374,19],["إِذْ قَالَ لَهُمْ أَخُوهُمْ لُوطٌ أَلَا تَتَّق[p[ُو]نَ","Ўшанда уларга биродарлари Лут деди: «Қўрқмайсизларми?!",374,19],["إِ[g[نّ]ِى لَكُمْ رَسُولٌ أَم[p[ِي]نٌ","Албатта, мен сизларга ишончли Пайғамбарман.",374,19],["فَ[h:9999[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَطِيع[p[ُو]نِ","Бас, Аллоҳдан қўрқинглар ва менга итоат қилинглар.",374,19],["وَم[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ مِنْ أَ[q:6133[جْ]رٍ‌ۖ إِنْ أَ[q:6134[جْ]رِىَ إِلَّا عَلَىٰ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Мен сизлардан бунинг учун ҳақ-ажр сўрамасман. Менинг ажрим фақатгина Роббул Оламийн зиммасидадир.",374,19],["أَتَأْتُونَ [h:9830[ٱ][l[ل]ذُّكْرَانَ مِنَ [h:3475[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Оламлар ичидан эркакларга борасизми?!",374,19],["وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّك[w:7985[ُم م]ِّنْ أَزْو[n[َٲ]جِك[c:9831[ُم‌ۚ ب]َلْ أَ[f:428[نت]ُمْ قَوْمٌ عَاد[p[ُو]نَ","Ва Роббингиз сиз учун яратган жуфти ҳалолларингизни тарк қиласизми?! Йўқ!!! Сиз ҳаддан ошган қавмсиз».",374,19],["قَالُو[s[اْ] لَئ[u:4195[ِن ل]َّمْ تَ[f:8352[نت]َهِ يَ[n[ـٰ]لُوطُ لَتَكُونَ[g[نّ]َ مِنَ [h:9832[ٱ]لْمُخْرَج[p[ِي]نَ","Улар: «Эй Лут, агар тўхтамасанг, албатта, ҳайдаб чиқарилганлардан бўлурсан!» дедилар.",374,19],["قَالَ إِ[g[نّ]ِى لِعَمَلِك[w:9833[ُم م]ِّنَ [h:9834[ٱ]لْقَال[p[ِي]نَ","У: «Албатта, мен бу ишингизни ўта ёмон кўргувчиларданман.",374,19],["رَبِّ نَجِّنِى وَأَهْلِى مِ[g[مّ]َا يَعْمَل[p[ُو]نَ","Эй Роббим, менга ва аҳлимга қилаётган нарсаларидан нажот бергин!» деди.",374,19],["فَنَجَّيْنَ[n[ـٰ]هُ وَأَهْلَهُ[o[ۥٓ] أَ[q:825[جْ]مَع[p[ِي]نَ","Бас, унга ва аҳлига, ҳаммаларига нажот бердик.",374,19],["إِلَّا عَجُو[f:9835[زًا ف]ِى [h:9836[ٱ]لْغَ[n[ـٰ]بِر[p[ِي]نَ","Магар қолгувчилардан бўлган бир кампирга.",374,19],["ثُ[g[مّ]َ دَ[g[مّ]َرْنَا [h:9837[ٱ]لْأَخَر[p[ِي]نَ","Сўнгра қолганларини ер билан яксон қилдик.",374,19],["وَأَمْطَرْنَا عَلَيْه[w:4839[ِم م]َّطَ[f:9838[رًا‌ۖ ف]َس[o[َا]ٓءَ مَطَرُ [h:9839[ٱ]لْمُ[f:6137[نذ]َر[p[ِي]نَ","Ва уларнинг устига бир ёмғир ёғдирдикки, бас, огоҳлантирилганларнинг ёмғири қандоқ ҳам ёмон бўлди.",374,19],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[a:9716[ةً‌ۖ و]َمَا كَانَ أَكْثَرُه[w:9717[ُم م]ُّؤْمِن[p[ِي]نَ","Албатта, бунда оят-белги бор. Лекин кўплари мўмин бўлмадилар.",374,19],["وَإِ[g[نّ]َ رَبَّكَ لَهُوَ [h:1987[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Албатта, Роббинг Ўзи азизу меҳрибондир.",374,19],["كَذَّبَ أَصْحَ[n[ـٰ]بُ لْــَٔيْكَةِ [h:9840[ٱ]لْمُرْسَل[p[ِي]نَ","Қалин дарахтзор эгалари Пайғамбарларни ёлғончи қилдилар.",374,19],["إِذْ قَالَ لَهُمْ شُعَيْبٌ أَلَا تَتَّق[p[ُو]نَ","Ўшанда уларга биродарлари Шуайб деди: «Қўрқмайсизларми?!",374,19],["إِ[g[نّ]ِى لَكُمْ رَسُولٌ أَم[p[ِي]نٌ","Албатта, мен сизларга ишончли Пайғамбарман.",374,19],["فَ[h:9999[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَطِيع[p[ُو]نِ","Бас, Аллоҳдан қўрқинглар ва менга итоат қилинглар.",374,19],["وَم[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ مِنْ أَ[q:6133[جْ]رٍ‌ۖ إِنْ أَ[q:6134[جْ]رِىَ إِلَّا عَلَىٰ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Мен сизлардан бунинг учун ҳақ-ажр сўрамасман. Менинг ажрим фақатгина Роббул Оламийн зиммасидадир.",374,19],["۞ أَوْفُو[s[اْ] [h:9841[ٱ]لْكَيْلَ وَلَا تَكُونُو[s[اْ] مِنَ [h:9842[ٱ]لْمُخْسِر[p[ِي]نَ","Бас, ўлчовни тўлиқ ўлчанглар ва камайтиргувчилардан бўлманглар.",374,19],["وَزِنُو[s[اْ] بِ[h:7750[ٱ]لْقِسْطَاسِ [h:7751[ٱ]لْمُسْتَق[p[ِي]مِ","Ва тўғри тарози ила тортинглар.",374,19],["وَلَا تَ[q:4845[بْ]خَسُو[s[اْ] [h:4846[ٱ][l[ل][g[نّ]َاسَ أَشْي[o[َا]ٓءَهُمْ وَلَا تَعْثَوْ[s[اْ] فِى [h:44[ٱ]لْأَرْضِ مُفْسِد[p[ِي]نَ","Одамларнинг нарсаларини камайтириб берманг. Ер юзида турли бузғунчиликлар қилманглар.",374,19],["وَ[h:9999[ٱ]تَّقُو[s[اْ] [h:9814[ٱ]لَّذِى خَلَقَكُمْ وَ[h:9843[ٱ]لْجِبِلَّةَ [h:9844[ٱ]لْأَوَّل[p[ِي]نَ","Сизни ва аввалги наслларни яратган зотдан қўрқинг».",375,19],["قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َم[o[َآ] أَ[f:169[نت]َ مِنَ [h:9826[ٱ]لْمُسَحَّر[p[ِي]نَ","Улар: «Албатта, сен сеҳрланганлардансан.",375,19],["وَم[o[َآ] أَ[f:169[نت]َ إِلَّا بَشَ[a:7065[رٌ م]ِّثْلُنَا وَإ[a:9845[ِن ن]َّظُ[g[نّ]ُكَ لَمِنَ [h:9339[ٱ]لْكَ[n[ـٰ]ذِب[p[ِي]نَ","Ва сен бизга ўхшаган башардан бошқа нарса эмассан. Биз сени, албатта, ёлғончилардан, деб биурамиз.",375,19],["فَأَسْقِ[q:9846[طْ] عَلَيْنَا كِسَ[a:9847[فًا م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ إِ[f:4792[ن ك]ُ[f:735[نت]َ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","Агар ростгўйлардан бўлсанг устимиздан осмоннинг бир бўлагини ташлавор», дедилар.",375,19],["قَالَ رَبّ[o[ِىٓ] أَعْلَمُ بِمَا تَعْمَل[p[ُو]نَ","У: «Роббим қилаётган ишингизни ўта яхши билгувчидир», деди.",375,19],["فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ [h:9848[ٱ][l[ل]ظُّلَّةِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ عَذَابَ يَوْمٍ عَظ[p[ِي]مٍ","Бас, улар уни ёлғончи қилдилар. Бас, уларни «соябон» куни азоби тутди. Албатта, у улуғ куннинг азоби эди.",375,19],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[a:9716[ةً‌ۖ و]َمَا كَانَ أَكْثَرُه[w:9717[ُم م]ُّؤْمِن[p[ِي]نَ","Албатта, бунда оят-белги бор. Лекин кўплари мўмин бўлмадилар.",375,19],["وَإِ[g[نّ]َ رَبَّكَ لَهُوَ [h:1987[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Албатта, Роббинг Ўзи азизу меҳрибондир.",375,19],["وَإِ[g[نّ]َهُ[n[ۥ] لَتَ[f:9849[نز]ِيلُ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Албатта, у Роббул Оламийннинг туширганидир.",375,19],["نَزَلَ بِهِ [h:9850[ٱ][l[ل]رُّوحُ [h:9851[ٱ]لْأَم[p[ِي]نُ","Уни Руҳул амийн олиб тушди.",375,19],["عَلَىٰ قَلْبِكَ لِتَكُونَ مِنَ [h:9852[ٱ]لْمُ[f:9853[نذ]ِر[p[ِي]نَ","Сенинг қалбингга, огоҳлантиргувчилардан бўлишинг учун.",375,19],["بِلِسَانٍ عَرَبِ[a:9854[ىٍّ م]ُّب[p[ِي]نٍ","Очиқ-ойдин араб тилида.",375,19],["وَإِ[g[نّ]َهُ[n[ۥ] لَفِى زُبُرِ [h:9855[ٱ]لْأَوَّل[p[ِي]نَ","Албатта, у аввалгиларининг китобларида ҳам бордир.",375,19],["أَوَلَمْ يَك[u:9334[ُن ل]َّهُمْ ءَايَةً أ[a:9856[َن ي]َعْلَمَهُ[n[ۥ] عُلَمَ[o[ـٰٓ]ؤُ[s[اْ] بَن[o[ِىٓ] إِسْر[o[َٲ]ٓء[p[ِي]لَ","Уни Бани Исроил уламоларининг билишлари, улар учун оят-далил эмасми?!",375,19],["وَلَوْ نَزَّلْنَ[n[ـٰ]هُ عَلَىٰ بَعْضِ [h:9857[ٱ]لْأَعْجَم[p[ِي]نَ","Агар Биз уни баъзи ажамийларга нозил қилсак.",375,19],["فَقَرَأَهُ[n[ۥ] عَلَيْه[w:3946[ِم م]َّا كَانُو[s[اْ] بِه[n[ِۦ] مُؤْمِن[p[ِي]نَ","Бас, у уларга уни ўқиб берса ҳам, мўмин бўлмас эдилар.",375,19],["كَذ[n[َٲ]لِكَ سَلَكْنَ[n[ـٰ]هُ فِى قُلُوبِ [h:7206[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","Биз уни жиноятчилар қалбларига ана шундай йўлладик.",375,19],["لَا يُؤْمِنُونَ بِه[n[ِۦ] حَتَّىٰ يَرَوُ[s[اْ] [h:6176[ٱ]لْعَذَابَ [h:6177[ٱ]لْأَل[p[ِي]مَ","Улар унга то аламли азобни кўрмагунларича иймон келтирмаслар.",375,19],["فَيَأْتِيَه[c:9858[ُم ب]َغْتَ[a:4880[ةً و]َهُمْ لَا يَشْعُر[p[ُو]نَ","Бас, уларга у тўсатдан келур. Улар сезмай қолурлар.",375,19],["فَيَقُولُو[s[اْ] هَلْ نَحْنُ مُ[f:9859[نظ]َر[p[ُو]نَ","Шунда улар: «Бизга муҳлат берилармикан?!» дерлар.",375,19],["أَفَبِعَذَابِنَا يَسْتَعْجِل[p[ُو]نَ","Бизнинг азобимизнинг тезроқ келишини истайдиларми-я?!",375,19],["أَفَرَءَيْتَ إ[a:9860[ِن م]َّتَّعْنَ[n[ـٰ]هُمْ سِن[p[ِي]نَ","Айтгин-чи, агар Биз уларни йилларча ҳузурлантирсак-да.",375,19],["ثُ[g[مّ]َ ج[o[َا]ٓءَه[w:466[ُم م]َّا كَانُو[s[اْ] يُوعَد[p[ُو]نَ","сўнгра уларга ваъда қилинган нарса келса.",375,19],["م[o[َآ] أَغْنَىٰ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يُمَتَّع[p[ُو]نَ","Ўша ҳузурланиб юрган нарсалари нимага асқотур?!",376,19],["وَم[o[َآ] أَهْلَكْنَا مِ[f:4585[ن ق]َرْيَةٍ إِلَّا لَهَا مُ[f:9861[نذ]ِر[p[ُو]نَ","Биз бирон шаҳар-қишлоқни ҳалок қилган бўлсак, албатта, унинг огоҳлантиргувчилари бўлган.",376,19],["ذِكْرَىٰ وَمَا كُ[g[نّ]َا ظَ[n[ـٰ]لِم[p[ِي]نَ","Эслатма бўлиши учундир. Биз зулм қилгувчи бўлмасдик.",376,19],["وَمَا تَنَزَّلَتْ بِهِ [h:9862[ٱ][l[ل]شَّيَ[n[ـٰ]ط[p[ِي]نُ","Уни шайтонлар олиб тушганлари йўқ.",376,19],["وَمَا يَ[i:8425[نۢب]َغِى لَهُمْ وَمَا يَسْتَطِيع[p[ُو]نَ","Бунга уларнинг имконлари йўқ ва унга қодир ҳам эмаслар.",376,19],["إِ[g[نّ]َهُمْ عَنِ [h:9863[ٱ][l[ل]سَّمْعِ لَمَعْزُول[p[ُو]نَ","Албатта, улар эшитишдан четлатилгандирлар.",376,19],["فَلَا تَ[q:6220[دْ]عُ مَعَ [h:3975[ٱ]للَّهِ إِلَ[n[ـٰ]هًا ءَاخَرَ فَتَكُونَ مِنَ [h:9864[ٱ]لْمُعَذَّب[p[ِي]نَ","Аллоҳ билан бирга бошқа илоҳга илтижо қилма. Йўқса, азобланганлардан бўлурсан.",376,19],["وَأَ[f:4070[نذ]ِرْ عَشِيرَتَكَ [h:9865[ٱ]لْأَ[q:9866[قْ]رَب[p[ِي]نَ","Ва яқин қариндошларингни огоҳлантир.",376,19],["وَ[h:9999[ٱ]خْفِضْ جَنَاحَكَ لِمَنِ [h:9867[ٱ]تَّبَعَكَ مِنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Ва сенга эргашган мўминларга қанотингни пастлат.",376,19],["فَإِنْ عَصَوْكَ فَقُلْ إِ[g[نّ]ِى بَر[o[ِى]ٓ[a:3977[ءٌ م]ِّ[g[مّ]َا تَعْمَل[p[ُو]نَ","Бас, агар улар сенга исён қилсалар: «Мен сиз қилаётган амаллардан безорман», дегин.",376,19],["وَتَوَكَّلْ عَلَى [h:9868[ٱ]لْعَزِيزِ [h:9869[ٱ][l[ل]رَّح[p[ِي]مِ","Ва азиз ва меҳрибон зотга таваккал қил;",376,19],["ٱلَّذِى يَرَ[n[ٮٰ]كَ حِينَ تَق[p[ُو]مُ","Сени қоим бўлганингда кўрадиган.",376,19],["وَتَقَلُّبَكَ فِى [h:9870[ٱ][l[ل]سَّ[n[ـٰ]جِد[p[ِي]نَ","Ва сажда қилгувчилар ичида ҳаракатланишингни зотга.",376,19],["إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:3721[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Албатта, Унинг Ўзи ўта эшитгувчи ва ўта билгувчи зотдир.",376,19],["هَلْ أُنَبِّئُكُمْ عَلَىٰ مَ[f:9871[ن ت]َنَزَّلُ [h:9872[ٱ][l[ل]شَّيَ[n[ـٰ]ط[p[ِي]نُ","Сизларга шайтонлар кимга тушишини айтиб берайми?",376,19],["تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَث[p[ِي]مٍ","Улар ўта уйдирмачи ва ўта гуноҳкорларга тушурлар.",376,19],["يُلْقُونَ [h:9873[ٱ][l[ل]سَّمْعَ وَأَكْثَرُهُمْ كَ[n[ـٰ]ذِب[p[ُو]نَ","Улар қулоқ осарлар. Ва уларнинг кўплари ёлғончилардир.",376,19],["وَ[h:9999[ٱ][l[ل]شُّعَر[o[َا]ٓءُ يَتَّبِعُهُمُ [h:9874[ٱ]لْغَاوُ[p[ۥ]نَ","Ва шоирларга гумроҳлар эргашур.",376,19],["أَلَمْ تَرَ أَ[g[نّ]َهُمْ فِى كُلِّ وَا[a:9875[دٍ ي]َهِيم[p[ُو]نَ","Уларнинг ҳар водийда дайдишини.",376,19],["وَأَ[g[نّ]َهُمْ يَقُولُونَ مَا لَا يَفْعَل[p[ُو]نَ","Ва ўзлари қилмайдиган ишларни айтишини кўрмадингми?",376,19],["إِلَّا [h:778[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ وَذَكَرُو[s[اْ] [h:9876[ٱ]للَّهَ كَثِي[a:9877[رًا و]َ[h:9878[ٱ][f:9878[نت]َصَرُو[s[اْ] م[i:146[ِنۢ ب]َعْدِ مَا ظُلِمُو[s[اْ‌ۗ] وَسَيَعْلَمُ [h:9879[ٱ]لَّذِينَ ظَلَم[o[ُوٓ][s[اْ] أَىَّ مُ[f:9880[نق]َلَ[a:9881[بٍ ي]َ[f:9882[نق]َلِب[p[ُو]نَ","Магар иймон келтириб, солиҳ амаллар қилганлар, Аллоҳни кўп зикр этганлар ва мазлум бўлганларидан кейин нусрат қозонганлар. Зулм қилганлар эса, тезда қайси ағдарилиш жойига ағдарилишларини билурлар.",376,19]]},{"n":27,"ar":"النَّمۡلِ","en":"An-Naml","uz":"Намл","type":"Макка","ayahs":[["ط[m[سٓ]‌ۚ تِلْكَ ءَايَ[n[ـٰ]تُ [h:9883[ٱ]لْقُرْءَانِ وَكِتَا[a:9884[بٍ م]ُّب[p[ِي]نٍ","То. Сийн. Ушбулар Қуръон-очиқ китоб оятларидир.",377,19],["هُ[a:9885[دًى و]َبُشْرَىٰ لِلْمُؤْمِن[p[ِي]نَ","Мўминлар учун ҳидоят ва хушхабардир.",377,19],["ٱلَّذِينَ يُقِيمُونَ [h:3638[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَيُؤْتُونَ [h:3639[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَه[c:4710[ُم ب]ِ[h:447[ٱ]لْأَخِرَةِ هُمْ يُوقِن[p[ُو]نَ","Улар намозни тўкис адо этадиган, закотни берадиган ва охиратга қаттиқ ишонадиганлардир.",377,19],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ زَيَّ[g[نّ]َا لَهُمْ أَعْمَ[n[ـٰ]لَهُمْ فَهُمْ يَعْمَه[p[ُو]نَ","Албатта, охиратга иймон келтирмайдиганларга Биз амалларини зийнатлаб кўрсатдик. Бас, улар адашиб-улоқиб юраверарлар.",377,19],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ لَهُمْ س[o[ُو]ٓءُ [h:9886[ٱ]لْعَذَابِ وَهُمْ فِى [h:536[ٱ]لْأَخِرَةِ هُمُ [h:6285[ٱ]لْأَخْسَر[p[ُو]نَ","Ана ўшаларга ёмон азоб бордир ва улар охиратда энг кўп зиён кўргувчилардир.",377,19],["وَإِ[g[نّ]َكَ لَتُلَقَّى [h:9887[ٱ]لْقُرْءَانَ م[u:6233[ِن ل]َّدُنْ حَكِيمٍ عَل[p[ِي]مٍ","Албатта, сенга бу Қуръон ўта ҳикматли ва ўта илмли зот томонидан берилур.",377,19],["إِذْ قَالَ مُوسَىٰ لِأَهْلِه[o[ِۦٓ] إِ[g[نّ][o[ِىٓ] ءَانَسْتُ نَا[f:9888[رًا س]َـَٔـاتِيك[w:9889[ُم م]ِّنْهَا بِخَبَرٍ أَوْ ءَاتِيك[c:9890[ُم ب]ِشِهَا[f:9891[بٍ ق]َبَ[u:9892[سٍ ل]َّعَلَّكُمْ تَصْطَل[p[ُو]نَ","Мусо ўз аҳлига: «Аниқки, мен бир олов кўрдим. Тезда мен сизларга ундан бирор хабар ёки исинишингиз учун бир тутам чўғ келтираман», деганини эсла.",377,19],["فَلَ[g[مّ]َا ج[o[َا]ٓءَهَا نُودِىَ أ[i:9893[َنۢ ب]ُورِكَ مَ[f:2074[ن ف]ِى [h:4674[ٱ][l[ل][g[نّ]َارِ وَمَنْ حَوْلَهَا وَسُ[q:6849[بْ]حَ[n[ـٰ]نَ [h:6850[ٱ]للَّهِ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","У га келганида: «Олов олдидаги ва атрофидаги шахсларга барака берилди ва Оламларнинг Робби–Аллоҳ покдир», деб нидо қилинди.",377,19],["يَ[n[ـٰ]مُوسَ[o[ىٰٓ] إِ[g[نّ]َهُ[o[ۥٓ] أَنَا [h:8455[ٱ]للَّهُ [h:9894[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","«Эй Мусо! Албатта, бу Менман! Азизу ҳаким Аллоҳман!",377,19],["وَأَلْقِ عَصَاكَ‌ۚ فَلَ[g[مّ]َا رَءَاهَا تَهْتَزُّ كَأَ[g[نّ]َهَا ج[m[َا]ٓ[a:9895[[g[نّ]ٌ و]َلَّىٰ مُ[q:9896[دْ]بِ[a:9897[رًا و]َلَمْ يُعَقِّ[q:9898[بْ]‌ۚ يَ[n[ـٰ]مُوسَىٰ لَا تَخَفْ إِ[g[نّ]ِى لَا يَخَافُ لَدَىَّ [h:9899[ٱ]لْمُرْسَل[p[ُو]نَ","Ва асоингни ташла!» Бас, қачонки Мусо унинг илондек қимирлаётганини кўрганида, ортига қарамай қочди. «Эй Мусо! Қўрқма! Зеро, Менинг ҳузуримда Пайғамбарлар қўрқмаслар!",377,19],["إِلَّا مَ[f:8211[ن ظ]َلَمَ ثُ[g[مّ]َ بَدَّلَ حُسْن[i:9900[َۢا ب]َعْدَ س[o[ُو]ٓ[f:9901[ءٍ ف]َإِ[g[نّ]ِى غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Лекин ким зулм қилсаю сўнгра ёмонлик кетидан унга яхшиликни бадал қилса, бас, Мен, албатта, мағфиратли ва меҳрибондирман.",377,19],["وَأَ[q:9902[دْ]خِلْ يَدَكَ فِى جَيْبِكَ تَخْرُ[q:8461[جْ] بَيْض[o[َا]ٓءَ مِنْ غَيْرِ س[o[ُو]ٓ[f:9903[ءٍ‌ۖ ف]ِى تِسْعِ ءَايَ[n[ـٰ]تٍ إِلَىٰ فِرْعَوْنَ وَقَوْمِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َهُمْ كَانُو[s[اْ] قَوْ[f:5652[مًا ف]َ[n[ـٰ]سِق[p[ِي]نَ","Қўлингни ёқангнинг ичига суқ, ҳеч қандай ёмонликсиз оппоқ бўлиб чиқур. Фиръавн ва унинг қавмига қаратилган тўққиз мўъжиза орасида. Албатта, улар бузғунчи қавм бўлдилар».",377,19],["فَلَ[g[مّ]َا ج[o[َا]ٓءَتْهُمْ ءَايَ[n[ـٰ]تُنَا مُ[q:7692[بْ]صِرَ[f:9904[ةً ق]َالُو[s[اْ] هَ[n[ـٰ]ذَا سِحْ[a:3879[رٌ م]ُّب[p[ِي]نٌ","Бас, қачонки уларга оят-мўъжизаларимиз кўз очгувчи бўлиб келганида, «Бу очиқ-ойдин сеҳрдир», дедилар.",377,19],["وَجَحَدُو[s[اْ] بِهَا وَ[h:9905[ٱ]سْتَيْقَنَتْه[o[َآ] أَ[f:2341[نف]ُسُهُمْ ظُلْ[a:9906[مًا و]َعُلُو[f:9907[ًّا‌ۚ ف]َ[h:1513[ٱ][f:1513[نظ]ُرْ كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:4852[ٱ]لْمُفْسِد[p[ِي]نَ","Ва ўзлари аниқ билиб туриб, зулм ва кибр туфайли уларни инкор этдилар. Бузғунчиларнинг оқибати қандай бўлишига назар сол.",378,19],["وَلَقَ[q:341[دْ] ءَاتَيْنَا دَاوُ[n[ۥ]دَ وَسُلَيْمَ[n[ـٰ]نَ عِلْ[a:9908[مًا‌ۖ و]َقَالَا [h:9909[ٱ]لْحَمْدُ لِلَّهِ [h:3912[ٱ]لَّذِى فَضَّلَنَا عَلَىٰ كَثِي[a:3126[رٍ م]ِّنْ عِبَادِهِ [h:9910[ٱ]لْمُؤْمِن[p[ِي]نَ","Батаҳқиқ, Биз Довуд ва Сулаймонга илм бердик. Икковлари: «Бизни кўпгина мўмин бандаларидан афзал қилган Аллоҳга ҳамдлар бўлсин», дедилар.",378,19],["وَوَرِثَ سُلَيْمَ[n[ـٰ]نُ دَاوُ[n[ۥ]دَ‌ۖ وَقَالَ يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ عُلِّمْنَا مَ[f:9911[نط]ِقَ [h:9912[ٱ][l[ل]طَّيْرِ وَأُوتِينَا مِ[f:843[ن ك]ُلِّ شَىْءٍ‌ۖ إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَهُوَ [h:9913[ٱ]لْفَضْلُ [h:9914[ٱ]لْمُب[p[ِي]نُ","Ва Сулаймон Довудга ворис бўлди. У: «Эй одамлар, бизга қуш тили ўргатилди ва ҳар бир нарсадан берилди. Бу, албатта, очиқ-ойдин фазлдир», деди.",378,19],["وَحُشِرَ لِسُلَيْمَ[n[ـٰ]نَ جُنُودُهُ[n[ۥ] مِنَ [h:4673[ٱ]لْجِ[g[نّ]ِ وَ[h:4418[ٱ]لْإِ[f:4418[نس]ِ وَ[h:9915[ٱ][l[ل]طَّيْرِ فَهُمْ يُوزَع[p[ُو]نَ","Сулаймонга жин, инс ва қушлардан бўлган аскарлари тўпланиб, тизилган ҳолда турдилар.",378,19],["حَتَّ[o[ىٰٓ] إِذ[o[َآ] أَتَوْ[s[اْ] عَلَىٰ وَادِ [h:9916[ٱ][l[ل][g[نّ]َمْلِ قَالَتْ نَمْلَ[a:9917[ةٌ ي]َ[o[ـٰٓ]أَيُّهَا [h:9918[ٱ][l[ل][g[نّ]َمْلُ [h:9919[ٱ][q:278[دْ]خُلُو[s[اْ] مَسَ[n[ـٰ]كِنَكُمْ لَا يَحْطِمَ[g[نّ]َكُمْ سُلَيْمَ[n[ـٰ]نُ وَجُنُودُهُ[n[ۥ] وَهُمْ لَا يَشْعُر[p[ُو]نَ","Токи улар чумолилар водийсига келганларида, бир чумоли: «Эй чумолилар, масканларингга киринглар, Сулаймон ва унинг аскарлари сизларни билмасдан эзиб юбормасинлар», деди.",378,19],["فَتَبَسَّمَ ضَاحِ[a:9920[كًا م]ِّ[f:9921[ن ق]َوْلِهَا وَقَالَ رَبِّ أَوْزِعْن[o[ِىٓ] أَنْ أَشْكُرَ نِعْمَتَكَ [h:9922[ٱ]لَّت[o[ِىٓ] أَنْعَمْتَ عَلَىَّ وَعَلَىٰ و[n[َٲ]لِدَىَّ وَأَنْ أَعْمَلَ صَ[n[ـٰ]لِ[f:9923[حًا ت]َرْضَ[n[ـٰ]هُ وَأَ[q:9924[دْ]خِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ [h:9925[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Бас, у унинг сўзидан табассум қилди ва: «Роббим, мени Ўзинг менга ва ота-онамга берган неъматларингга шукр этишимга ва сен рози бўладиган солиҳ амаллар қилишимга муяссар этгин. Ўз раҳматинг ила мени солиҳ бандаларингга қўшгин», деди.",378,19],["وَتَفَقَّدَ [h:9926[ٱ][l[ل]طَّيْرَ فَقَالَ مَا لِىَ ل[o[َآ] أَرَى [h:9927[ٱ]لْهُ[q:9928[دْ]هُدَ أَمْ كَانَ مِنَ [h:9929[ٱ]لْغ[o[َا]ٓئِب[p[ِي]نَ","Ва қушларни текширди-да: «Нега Ҳудҳудни кўрмаётирман ёки ғойиблардан бўлдими?",378,19],["لَأُعَذِّبَ[g[نّ]َهُ[n[ۥ] عَذَا[f:1966[بًا ش]َدِيدًا أَوْ لَأَ[s[اْ]ذْبَحَ[g[نّ]َهُ[o[ۥٓ] أَوْ لَيَأْتِيَ[g[نّ]ِى بِسُلْطَ[n[ـٰ][a:7067[نٍ م]ُّب[p[ِي]نٍ","Албатта, уни шиддатли азобла азобларман ёки сўйиб юборурман ёхуд менга, албатта, очиқ-ойдин ҳужжат келтиражак», деди.",378,19],["فَمَكَثَ غَيْرَ بَعِي[f:9930[دٍ ف]َقَالَ أَحَطتُ بِمَا لَمْ تُحِ[q:8160[طْ] بِه[n[ِۦ] وَجِئْتُكَ مِ[f:9931[ن س]َبَ[i:9932[إِۭ ب]ِنَبَ[a:9933[إٍ ي]َق[p[ِي]نٍ","Кўп ўтмасдан у келиб: «Сен билмаган нарсани билдим ва сенга Сабаъдан ишончли бир хабар олиб келдим.",378,19],["إِ[g[نّ]ِى وَجَ[d:9934[د]تُّ [h:9935[ٱ]مْرَأَ[f:9936[ةً ت]َمْلِكُهُمْ وَأُوتِيَتْ مِ[f:843[ن ك]ُلِّ ش[a:9937[َىْءٍ و]َلَهَا عَرْشٌ عَظ[p[ِي]مٌ","Дарҳақиқат, мен бир аёлни кўрдим. У уларнинг маликаси экан. Унга ҳар нарса берилган экан. Ҳамда унинг улуғ тахти бор экан.",379,19],["وَجَ[d:9938[د]تُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَزَيَّنَ لَهُمُ [h:4046[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ أَعْمَ[n[ـٰ]لَهُمْ فَصَدَّهُمْ عَنِ [h:6998[ٱ][l[ل]سَّبِيلِ فَهُمْ لَا يَهْتَد[p[ُو]نَ","Мен унинг ва қавмининг Аллоҳни қўйиб, қуёшга сажда қилаётганларини ва шайтон уларга амалларини зийнатлаб, йўлдан тўсаётганини кўрдим. Бас, улар ҳидоят топмаслар.",379,19],["أَلَّا يَسْجُدُو[s[اْ] لِلَّهِ [h:3912[ٱ]لَّذِى يُخْرِجُ [h:9939[ٱ]لْخَ[q:9940[بْ]ءَ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِن[p[ُو]نَ","Осмонлару ердаги сирларни ошкор қиладиган, махфий ва ошкор қилган нарсаларингизни биладиган Аллоҳга сажда қилмайдиларми?!",379,19],["ٱللَّهُ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ رَبُّ [h:5930[ٱ]لْعَرْشِ [h:5931[ٱ]لْعَظِ[p[ي]مِ ۩","Аллоҳ–Ундан ўзга ҳеч қандай илоҳ йўқ зотдир. У улуғ аршнинг Роббидир», деди.",379,19],["۞ قَالَ سَنَ[f:9941[نظ]ُرُ أَصَدَ[q:9942[قْ]تَ أَمْ كُ[f:735[نت]َ مِنَ [h:4785[ٱ]لْكَ[n[ـٰ]ذِب[p[ِي]نَ","У: «Кўрамиз, рост сўзладингми ёки ёлғончилардан бўлдингми?",379,19],["ٱذْهَب بِّكِتَ[n[ـٰ]بِى هَ[n[ـٰ]ذَا فَأَلْقِهْ إِلَيْهِمْ ثُ[g[مّ]َ تَوَلَّ عَنْهُمْ فَ[h:1513[ٱ][f:1513[نظ]ُرْ مَاذَا يَرْجِع[p[ُو]نَ","Бу мактубимни олиб бориб, уларга ташла, сўнгра четга чиқиб назар сол-чи, нима қайтарарлар», деди.",379,19],["قَالَتْ يَ[o[ـٰٓ]أَيُّهَا [h:9943[ٱ]لْمَلَؤُ[s[اْ] إِ[g[نّ][o[ِىٓ] أُلْقِىَ إِلَىَّ كِتَ[n[ـٰ][f:9944[بٌ ك]َر[p[ِي]مٌ","У: «Эй аъёнлар! Менга кароматли бир мактуб ташланди.",379,19],["إِ[g[نّ]َهُ[n[ۥ] مِ[f:9945[ن س]ُلَيْمَ[n[ـٰ]نَ وَإِ[g[نّ]َهُ[n[ۥ] بِسْمِ [h:6335[ٱ]للَّهِ [h:9946[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ [h:3[ٱ][l[ل]رَّح[p[ِي]مِ","Албатта, у Сулаймондандир, албатта, унда: «Бисмиллаҳир роҳманир роҳийм.",379,19],["أَلَّا تَعْلُو[s[اْ] عَلَىَّ وَأْتُونِى مُسْلِم[p[ِي]نَ","Менга қарши бош кўтармай, таслим бўлган ҳолингизда келинг», дейилмишдир», деди.",379,19],["قَالَتْ يَ[o[ـٰٓ]أَيُّهَا [h:9943[ٱ]لْمَلَؤُ[s[اْ] أَفْتُونِى ف[o[ِىٓ] أَمْرِى مَا كُ[f:2917[نت]ُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَد[p[ُو]نِ","У: «Эй аъёнлар! Менга бу ишимда фатво беринглар. Сизлар шоҳид бўлмагунингизча, мен бир ишга қатъий қарор қилмасман», деди.",379,19],["قَالُو[s[اْ] نَحْنُ أُ[s[وْ]لُو[s[اْ] قُوَّ[a:9947[ةٍ و]َأُ[s[وْ]لُو[s[اْ] بَأْ[f:7663[سٍ ش]َدِي[a:9948[دٍ و]َ[h:4748[ٱ]لْأَمْرُ إِلَيْكِ فَ[h:9949[ٱ][f:9949[نظ]ُرِى مَاذَا تَأْمُر[p[ِي]نَ","Улар: «Биз куч-қувват эгаларимиз ва шиддатли азму шижоат эгаларимиз. Иш ўзингга ҳавола. Нима амр қилишингни ўйлаб кўр», дедилар.",379,19],["قَالَتْ إِ[g[نّ]َ [h:9950[ٱ]لْمُلُوكَ إِذَا دَخَلُو[s[اْ] قَرْيَةً أَفْسَدُوهَا وَجَعَل[o[ُوٓ][s[اْ] أَعِزَّةَ أَهْلِه[o[َآ] أَذِلَّ[a:9951[ةً‌ۖ و]َكَذ[n[َٲ]لِكَ يَفْعَل[p[ُو]نَ","У: «Албатта, подшоҳлар бирор шаҳар-қишлоққа кирсалар, уни вайрон қилурлар ва унинг азиз аҳлларини хор қилурлар. Ана шундай қилурлар.",379,19],["وَإِ[g[نّ]ِى مُرْسِلَةٌ إِلَيْه[c:9952[ِم ب]ِهَدِيَّ[f:9953[ةٍ ف]َنَاظِرَ[i:9954[ةُۢ ب]ِمَ يَرْجِعُ [h:9955[ٱ]لْمُرْسَل[p[ُو]نَ","Мен уларга бир ҳадя юборурман, кўрай-чи, элчилар нима билан қайтар эканлар», деди.",379,19],["فَلَ[g[مّ]َا ج[o[َا]ٓءَ سُلَيْمَ[n[ـٰ]نَ قَالَ أَتُمِدُّونَنِ بِمَا[f:9956[لٍ ف]َم[o[َآ] ءَاتَ[n[ـٰ]ن[n[ِۦ]َ [h:9957[ٱ]للَّهُ خَيْ[a:2365[رٌ م]ِّ[g[مّ][o[َآ] ءَاتَ[n[ـٰ]ك[c:9958[ُم ب]َلْ أَ[f:428[نت][c:9959[ُم ب]ِهَدِيَّتِكُمْ تَفْرَح[p[ُو]نَ","Қачонки, Сулаймонга келганида, у: «Сизлар менга мол-дунё ила мадад бермоқчимисиз?! Бас, Аллоҳ менга берган нарса сизга берган нарсадан яхшидир. Аммо сизлар ҳадяларингиз билан қувонурсиз.",380,19],["ٱرْجِعْ إِلَيْهِمْ فَلَنَأْتِيَ[g[نّ]َه[c:9960[ُم ب]ِجُنُو[u:9961[دٍ ل]َّا قِبَلَ لَه[c:9962[ُم ب]ِهَا وَلَنُخْرِجَ[g[نّ]َه[w:9963[ُم م]ِّنْه[o[َآ] أَذِلَّ[a:9964[ةً و]َهُمْ صَ[n[ـٰ]غِر[p[ُو]نَ","Сен уларга қайтиб бор. Бас, албатта, Биз улар бас кела олмайдиган қўшин ила борурмиз ва у ердан уларни хору зор ҳолларида чиқарурмиз», деди.",380,19],["قَالَ يَ[o[ـٰٓ]أَيُّهَا [h:9943[ٱ]لْمَلَؤُ[s[اْ] أَيُّكُمْ يَأْتِينِى بِعَرْشِهَا قَ[q:3282[بْ]لَ أ[a:9965[َن ي]َأْتُونِى مُسْلِم[p[ِي]نَ","У: «Эй аъёнлар! Улар менга таслим бўлиб келишларидан олдин қайсингиз ҳузуримга унинг тахтини келтира оладир?» деди.",380,19],["قَالَ عِفْرِي[a:9966[تٌ م]ِّنَ [h:4673[ٱ]لْجِ[g[نّ]ِ أَنَا۟ ءَاتِيكَ بِه[n[ِۦ] قَ[q:3282[بْ]لَ أَ[f:5839[ن ت]َقُومَ م[a:9967[ِن م]َّقَامِكَ‌ۖ وَإِ[g[نّ]ِى عَلَيْهِ لَقَوِىٌّ أَم[p[ِي]نٌ","Жинлардан бўлган Ифрит: «Мен уни сенга мақомингдан тургунингча келтирурман. Албатта, бунга қувватим ва ишончим бор», деди.",380,19],["قَالَ [h:9968[ٱ]لَّذِى عِ[f:719[ند]َهُ[n[ۥ] عِلْ[a:9969[مٌ م]ِّنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ أَنَا۟ ءَاتِيكَ بِه[n[ِۦ] قَ[q:3282[بْ]لَ أ[a:9970[َن ي]َرْتَدَّ إِلَيْكَ طَرْفُكَ‌ۚ فَلَ[g[مّ]َا رَءَاهُ مُسْتَقِرًّا عِ[f:719[ند]َهُ[n[ۥ] قَالَ هَ[n[ـٰ]ذَا مِ[f:6655[ن ف]َضْلِ رَبِّى لِيَ[q:9971[بْ]لُوَن[o[ِىٓ] ءَأَشْكُرُ أَمْ أَكْفُرُ‌ۖ وَمَ[f:9972[ن ش]َكَرَ فَإِ[g[نّ]َمَا يَشْكُرُ لِنَفْسِه[n[ِۦ]‌ۖ وَمَ[f:662[ن ك]َفَرَ فَإِ[g[نّ]َ رَبِّى غَنِ[f:9973[ىٌّ ك]َر[p[ِي]مٌ","Китобдан илми бор шахс: «Мен уни сенга кўзингни очиб юмгунингча келтирурман», деди. Қачонки, у уни ўз ҳузурида қарор топганини кўргач: «Бу Роббимнинг фазлидандир. Мен шукр қиламанми ёки куфрони неъмат қиламанми, синаш учундир. Ким шукр келтирса, ўзи учунгина шукр қилур. Ким куфрони неъмат қилса, бас, Роббим беҳожат ва карамли зотдир», деди.",380,19],["قَالَ نَكِّرُو[s[اْ] لَهَا عَرْشَهَا نَ[f:9974[نظ]ُرْ أَتَهْتَد[o[ِىٓ] أَمْ تَكُونُ مِنَ [h:523[ٱ]لَّذِينَ لَا يَهْتَد[p[ُو]نَ","У: «Унинг тахтини танимайдиган қилиб қўйинг. Кўрайлик-чи, у уни танийдими ёки танимайдиганлардан бўладими?» деди.",380,19],["فَلَ[g[مّ]َا ج[o[َا]ٓءَتْ قِيلَ أَهَ[n[ـٰ]كَذَا عَرْشُكِ‌ۖ قَالَتْ كَأَ[g[نّ]َهُ[n[ۥ] هُوَ‌ۚ وَأُوتِينَا [h:9975[ٱ]لْعِلْمَ مِ[f:6977[ن ق]َ[q:6978[بْ]لِهَا وَكُ[g[نّ]َا مُسْلِم[p[ِي]نَ","Қачонки у келганида: «Сенинг тахтинг шундайми?» дейилди. У: «Худди ўшанинг ўзи», деди. «Бизга бундан илгари илм берилган эди ва мусулмон бўлган эдик».",380,19],["وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ‌ۖ إِ[g[نّ]َهَا كَانَتْ مِ[f:3024[ن ق]َوْ[f:4873[مٍ ك]َ[n[ـٰ]فِر[p[ِي]نَ","Ва уни Аллоҳдан ўзга ибодат қилган нарса тўсди. Албатта, у кофир қавмлардан бўлган эди.",380,19],["قِيلَ لَهَا [h:9976[ٱ][q:9977[دْ]خُلِى [h:9978[ٱ][l[ل]صَّرْحَ‌ۖ فَلَ[g[مّ]َا رَأَتْهُ حَسِبَتْهُ لُجَّ[a:9979[ةً و]َكَشَفَتْ عَ[f:9980[ن س]َاقَيْهَا‌ۚ قَالَ إِ[g[نّ]َهُ[n[ۥ] صَرْ[a:9981[حٌ م]ُّمَرَّ[a:9982[دٌ م]ِّ[f:9983[ن ق]َوَارِيرَ‌ۗ قَالَتْ رَبِّ إِ[g[نّ]ِى ظَلَمْتُ نَفْسِى وَأَسْلَمْتُ مَعَ سُلَيْمَ[n[ـٰ]نَ لِلَّهِ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Уга: «Саройга кир», дейилди. Қачонки уни кўрганида, сув деб ўйлаб, пойчаларини очди. У: «Албатта, бу биллурдан силлиқ қилиб ясалган саройдир», деди. У: «Эй Роббим, албатта, мен ўзимга зулм қилиб юрган эканман, Сулаймон ила оламларнинг Робби– Аллоҳга мусулмон бўлдим!» деди.",380,19],["وَلَقَ[q:341[دْ] أَرْسَلْن[o[َآ] إِلَىٰ ثَمُودَ أَخَاهُمْ صَ[n[ـٰ]لِحًا أَنِ [h:3899[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِم[p[ُو]نَ","Батаҳқиқ, Самуд қавмига, Аллоҳга ибодат қилинг, деб биродарлари Солиҳни юбордик. Бас, баногоҳ улар икки гуруҳ бўлиб тортиша бошладилар.",381,19],["قَالَ يَ[n[ـٰ]قَوْمِ لِمَ تَسْتَعْجِلُونَ بِ[h:4563[ٱ][l[ل]سَّيِّئَةِ قَ[q:3282[بْ]لَ [h:6889[ٱ]لْحَسَنَةِ‌ۖ لَوْلَا تَسْتَغْفِرُونَ [h:9984[ٱ]للَّهَ لَعَلَّكُمْ تُرْحَم[p[ُو]نَ","У: «Эй қавмим, нима учун яхшиликдан олдин ёмонликка ошиқасиз?! Аллоҳдан мағфират сўрасангиз-чи?! Шояд раҳм қилинсангиз», деди.",381,19],["قَالُو[s[اْ] [h:9985[ٱ]طَّيَّرْنَا بِكَ وَبِم[a:9986[َن م]َّعَكَ‌ۚ قَالَ طَ[o[ـٰٓ]ئِرُكُمْ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۖ بَلْ أَ[f:428[نت]ُمْ قَوْ[f:9987[مٌ ت]ُفْتَن[p[ُو]نَ","Улар: «Сендан ва сен билан бўлганлардан шумландик», дедилар. У: «Шумланишингиз Аллоҳнинг ҳузуридадир. Балки сизлар синалаётган қавмсиз», деди.",381,19],["وَكَانَ فِى [h:4932[ٱ]لْمَدِينَةِ تِسْعَةُ رَهْ[a:9988[طٍ ي]ُفْسِدُونَ فِى [h:44[ٱ]لْأَرْضِ وَلَا يُصْلِح[p[ُو]نَ","У шаҳарда тўққиз нафарли гуруҳ бор бўлиб, ер юзида бузғунчилик қилишар, ислоҳ қилмас эдилар.",381,19],["قَالُو[s[اْ] تَقَاسَمُو[s[اْ] بِ[h:32[ٱ]للَّهِ لَنُبَيِّتَ[g[نّ]َهُ[n[ۥ] وَأَهْلَهُ[n[ۥ] ثُ[g[مّ]َ لَنَقُولَ[g[نّ]َ لِوَلِيِّه[n[ِۦ] مَا شَهِ[q:4421[دْ]نَا مَهْلِكَ أَهْلِه[n[ِۦ] وَإِ[g[نّ]َا لَصَ[n[ـٰ]دِق[p[ُو]نَ","Улар: «Аллоҳнинг номига қасам ичинглар! Албатта, уни ва унинг аҳлини тунда ўлдирармиз, сўнгра валийсига, биз унинг аҳлининг ҳалокатига гувоҳ эмасмиз, албатта, биз ростгўйлармиз, дермиз», дедилар.",381,19],["وَمَكَرُو[s[اْ] مَكْ[a:9989[رًا و]َمَكَرْنَا مَكْ[a:9990[رًا و]َهُمْ لَا يَشْعُر[p[ُو]نَ","Улар макр қилдилар. Биз ҳам улар сезмаган ҳолда бир «макр» қилдик.",381,19],["فَ[h:9999[ٱ][f:1513[نظ]ُرْ كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ مَكْرِهِمْ أَ[g[نّ]َا دَ[g[مّ]َرْنَ[n[ـٰ]هُمْ وَقَوْمَهُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Назар сол! Уларнинг макри оқибати нима бўлди?! Биз, албатта, уларни ва қавмларининг ҳаммаларини ер билан яксон қилдик.",381,19],["فَتِلْكَ بُيُوتُهُمْ خَاوِيَ[i:9991[ةَۢ ب]ِمَا ظَلَم[o[ُوٓ[s[اْ]‌ۗ] إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:7345[ةً ل]ِّقَوْ[a:1292[مٍ ي]َعْلَم[p[ُو]نَ","Ана, зулмлари сабабли уйлари ҳувуллаб ётибди! Албатта, бунда биладиган қавмлар учун ибрат бордир.",381,19],["وَأَ[f:9771[نج]َيْنَا [h:9992[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَكَانُو[s[اْ] يَتَّق[p[ُو]نَ","Ва иймон келтириб, тақво қилиб юрганларга нажот бердик.",381,19],["وَلُوطًا إِذْ قَالَ لِقَوْمِه[o[ِۦٓ] أَتَأْتُونَ [h:4827[ٱ]لْفَ[n[ـٰ]حِشَةَ وَأَ[f:98[نت]ُمْ تُ[q:8674[بْ]صِر[p[ُو]نَ","Ва Лутни ҳам. Ўшанда у ўз қавмига: «Сиз кўриб-билиб туриб, фоҳиша иш қиласизми?!",381,19],["أَئِ[g[نّ]َكُمْ لَتَأْتُونَ [h:4830[ٱ][l[ل]رِّجَالَ شَهْوَ[a:4831[ةً م]ِّ[f:107[ن د]ُونِ [h:4832[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِ‌ۚ بَلْ أَ[f:428[نت]ُمْ قَوْ[f:4983[مٌ ت]َ[q:4984[جْ]هَل[p[ُو]نَ","Сиз, албатта, аёлларни қўйиб, эркакларга шаҳват ила яқинлик қиласизми?! Йўқ! Сиз жоҳиллик қилаётган қавмдирсиз!» деди.",381,19],["۞ فَمَا كَانَ جَوَابَ قَوْمِه[o[ِۦٓ] إِلّ[o[َآ] أَ[f:2304[ن ق]َال[o[ُوٓ][s[اْ] أَخْرِج[o[ُوٓ][s[اْ] ءَالَ لُو[a:9993[طٍ م]ِّ[f:4835[ن ق]َرْيَتِكُمْ‌ۖ إِ[g[نّ]َهُمْ أُنَا[a:4836[سٌ ي]َتَطَهَّر[p[ُو]نَ","Унинг қавмининг жавоби: «Лут аҳлини юртингиздан қувиб чиқаринг, чунки улар покиза бўлишни хоҳлаган кишилардир», дейишдан бошқа нарса бўлмади.",382,20],["فَأَ[f:4779[نج]َيْنَ[n[ـٰ]هُ وَأَهْلَهُ[o[ۥٓ] إِلَّا [h:4837[ٱ]مْرَأَتَهُ[n[ۥ] قَدَّرْنَ[n[ـٰ]هَا مِنَ [h:4838[ٱ]لْغَ[n[ـٰ]بِر[p[ِي]نَ","Бас, Биз унга ва хотинидан бошқа аҳлига нажот бердик. Унинг азобда қолгувчилар ичида бўлишини тақдир қилдик.",382,20],["وَأَمْطَرْنَا عَلَيْه[w:4839[ِم م]َّطَ[f:9838[رًا‌ۖ ف]َس[o[َا]ٓءَ مَطَرُ [h:9839[ٱ]لْمُ[f:6137[نذ]َر[p[ِي]نَ","Ва уларнинг устларига бир ёмғир ёғдирдикки, бас, огоҳлантирилганларнинг азоби қандай ҳам ёмон бўлди.",382,20],["قُلِ [h:9994[ٱ]لْحَمْدُ لِلَّهِ وَسَلَ[n[ـٰ]مٌ عَلَىٰ عِبَادِهِ [h:9995[ٱ]لَّذِينَ [h:9996[ٱ]صْطَفَ[o[ىٰٓ‌ۗ] ءَآللَّهُ خَيْرٌ أَ[g[مّ]َا يُشْرِك[p[ُو]نَ","Сен: «Аллоҳга ҳамд бўлсин ва у танлаб олган бандаларига салом бўлсин. Аллоҳ яхшими ёки улар ширк келтираётган нарсаларми?» дегин.",382,20],["أَ[g[مّ]َنْ خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَأَ[f:91[نز]َلَ لَك[w:1578[ُم م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:9997[ءً ف]َأَ[i:9998[نۢب]َتْنَا بِه[n[ِۦ] حَد[o[َا]ٓئِقَ ذَاتَ بَهْجَ[a:9999[ةٍ م]َّا كَانَ لَكُمْ أَ[f:10000[ن ت]ُ[i:10001[نۢب]ِتُو[s[اْ] شَجَرَه[o[َآ‌ۗ] أَءِلَ[n[ـٰ][a:10002[هٌ م]َّعَ [h:3975[ٱ]للَّهِ‌ۚ بَلْ هُمْ قَوْ[a:10003[مٌ ي]َعْدِل[p[ُو]نَ","Ёки осмонлару ерни яратган, сизларга осмондан сув туширган зотми? Бас, Биз у билан гўзал боғлар ўстирдик. Сиз ўзингиз унинг дарахтини ўстира олмас эдингиз. Аллоҳ билан бирга бошқа илоҳ борми?! Йўқ, улар ўзлари тенглаштирадиган қавмдирлар.",382,20],["أَ[g[مّ]َ[f:10004[ن ج]َعَلَ [h:10005[ٱ]لْأَرْضَ قَرَا[a:10006[رًا و]َجَعَلَ خِلَ[n[ـٰ]لَه[o[َآ] أَنْهَ[n[ـٰ][a:10007[رًا و]َجَعَلَ لَهَا رَو[n[َٲ]سِىَ وَجَعَلَ بَيْنَ [h:10008[ٱ]لْبَحْرَيْنِ حَاجِزًا‌ۗ أَءِلَ[n[ـٰ][a:10002[هٌ م]َّعَ [h:3975[ٱ]للَّهِ‌ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَم[p[ُو]نَ","Ёки ерни қароргоҳ этган, унинг узра анҳорлар қилган, унга тоғлар қилган ва икки денгиз ўртасида тўсиқ қилган зотми?! Аллоҳ билан бирга бошқа илоҳ борми?! Йўқ, уларнинг кўплари билмаслар.",382,20],["أَ[g[مّ][a:10009[َن ي]ُجِيبُ [h:10010[ٱ]لْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ [h:10011[ٱ][l[ل]سّ[o[ُو]ٓءَ وَيَ[q:10012[جْ]عَلُكُمْ خُلَف[o[َا]ٓءَ [h:10013[ٱ]لْأَرْضِ‌ۗ أَءِلَ[n[ـٰ][a:10002[هٌ م]َّعَ [h:3975[ٱ]للَّهِ‌ۚ قَلِيل[a:4583[اً م]َّا تَذَكَّر[p[ُو]نَ","Ёки музтар-ночор одам дуо қилганда ижобат этиб, унинг мушкулини осон қилган ҳамда сизни ер юзида халифа қилган зот яхшими?! Аллоҳ билан бирга бошқа илоҳ борми? Қанчалик оз эслайсизлар-а?!",382,20],["أَ[g[مّ][a:10014[َن ي]َهْدِيكُمْ فِى ظُلُمَ[n[ـٰ]تِ [h:4129[ٱ]لْبَرِّ وَ[h:4107[ٱ]لْبَحْرِ وَم[a:10015[َن ي]ُرْسِلُ [h:4755[ٱ][l[ل]رِّيَ[n[ـٰ]حَ بُشْر[i:4756[َۢا ب]َيْنَ يَدَىْ رَحْمَتِه[o[ِۦٓ‌ۗ] أَءِلَ[n[ـٰ][a:10002[هٌ م]َّعَ [h:3975[ٱ]للَّهِ‌ۚ تَعَ[n[ـٰ]لَى [h:10016[ٱ]للَّهُ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","Ёки сизларни қуруқлик ва денгиз зулматларида тўғри йўлга соладиган ҳамда Ўз раҳмати олдидан шамолларни хушхабар қилиб юборадиган зотми?! Аллоҳ билан бирга бошқа илоҳ борми?! Аллоҳ улар ширк келтираётган нарсалардан олийдир.",382,20],["أَ[g[مّ][a:10017[َن ي]َ[q:5943[بْ]دَؤُ[s[اْ] [h:5944[ٱ]لْخَلْقَ ثُ[g[مّ]َ يُعِيدُهُ[n[ۥ] وَم[a:10018[َن ي]َرْزُقُك[w:6034[ُم م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِ‌ۗ أَءِلَ[n[ـٰ][a:10002[هٌ م]َّعَ [h:3975[ٱ]للَّهِ‌ۚ قُلْ هَاتُو[s[اْ] بُرْهَ[n[ـٰ]نَكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Ёки аввал-бошдан яратадиган, сўнгра яна қайтадан яратадиган ва сизларни осмонлару ердан ризқлантирадиган зот яхшими? Аллоҳ билан бирга бошқа илоҳ борми?! «Агар ростгўй бўлсангиз ҳужжатингизни келтиринг», дегин.",383,20],["قُل لَّا يَعْلَمُ مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ [h:10019[ٱ]لْغَيْبَ إِلَّا [h:1742[ٱ]للَّهُ‌ۚ وَمَا يَشْعُرُونَ أَيَّانَ يُ[q:4606[بْ]عَث[p[ُو]نَ","Сен: «Осмонлару ерда Аллоҳдан бошқа ҳеч ким ғайбни билмас», деб айт. Улар қачон қайта тирилтирилишларини ҳам сезмаслар.",383,20],["بَلِ [h:10020[ٱ]دّ[n[َٲ]رَكَ عِلْمُهُمْ فِى [h:536[ٱ]لْأَخِرَةِ‌ۚ بَلْ هُمْ فِى شَ[a:10021[كٍّ م]ِّنْهَا‌ۖ بَلْ ه[w:7261[ُم م]ِّنْهَا عَم[p[ُو]نَ","Балки илмлари охиратни идрок қилгандир? Йўқ, улар ундан шак-шубҳададирлар. Йўқ, улар ундан кўрдирлар. Кофирлар охират илмидан хабардормикин? Йўқ, била олмайдилар. Улар охират нима эканини билиш у ёқда турсин, охиратнинг бўлиш-бўлмаслигига аниқ ишонмайдилар. Балки у хусусдаги масалада кўрдирлар, ҳеч нарсани кўрмаслар.",383,20],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أَءِذَا كُ[g[نّ]َا تُر[n[َٲ][a:10022[بًا و]َءَاب[o[َا]ٓؤُن[o[َآ] أَئِ[g[نّ]َا لَمُخْرَج[p[ُو]نَ","Куфр келтирганлар: «Биз ва ота-боболаримиз тупроқ бўлганимиздан кейин, яна чиқариламизми?!",383,20],["لَقَ[q:2389[دْ] وُعِ[q:9269[دْ]نَا هَ[n[ـٰ]ذَا نَحْنُ وَءَاب[o[َا]ٓؤُنَا مِ[f:128[ن ق]َ[q:129[بْ]لُ إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلّ[o[َآ] أَسَ[n[ـٰ]طِيرُ [h:3993[ٱ]لْأَوَّل[p[ِي]نَ","Батаҳқиқ, бу бизга-да, ота-боболармизга-да олдин ҳам ваъда қилинган эди. Бу аввалгиларнинг афсонасидан бошқа ҳеч нарса эмас», дедилар.",383,20],["قُلْ سِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَ[h:2257[ٱ][f:2257[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:4841[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","Сен: «Ер юзида сайр қилинглар ва жиноятчиларнинг оқибати қандай бўлганига назар солинглар», деб айт.",383,20],["وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ[f:10023[ن ف]ِى ضَيْ[a:7646[قٍ م]ِّ[g[مّ]َا يَمْكُر[p[ُو]نَ","Сен улар ҳақида ғам чекма ва қилаётган макрларидан сиқилма ҳам.",383,20],["وَيَقُولُونَ مَتَىٰ هَ[n[ـٰ]ذَا [h:6081[ٱ]لْوَعْدُ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Улар: «Агар ростгўй бўлсангиз, бу ваъда қачон бўладир?» дерлар.",383,20],["قُلْ عَسَ[o[ىٰٓ] أ[a:3312[َن ي]َكُونَ رَدِفَ لَك[c:10024[ُم ب]َعْضُ [h:10025[ٱ]لَّذِى تَسْتَعْجِل[p[ُو]نَ","Сен: «Сиз келишига ошиқаётган нарсанинг баъзиси ортингизга мингашиб олган, бўлса ажаб эмас», деб айт.",383,20],["وَإِ[g[نّ]َ رَبَّكَ لَذُو فَضْلٍ عَلَى [h:729[ٱ][l[ل][g[نّ]َاسِ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَشْكُر[p[ُو]نَ","Албатта, Роббинг одамларга нисбатан фазлу марҳамат соҳибидир. Лекин уларнинг кўплари шукр қилмаслар.",383,20],["وَإِ[g[نّ]َ رَبَّكَ لَيَعْلَمُ مَا تُكِ[g[نّ]ُ صُدُورُهُمْ وَمَا يُعْلِن[p[ُو]نَ","Ва, албатта, Роббинг уларнинг диллари беркитган нарсани ҳам, ошкор қилган нарсани ҳам билур.",383,20],["وَمَا مِنْ غ[o[َا]ٓئِبَ[f:10026[ةٍ ف]ِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِ إِلَّا فِى كِتَ[n[ـٰ][a:4113[بٍ م]ُّب[p[ِي]نٍ","Осмону ерда ҳеч бир ғайб нарса йўқ, илло у очиқ-ойдин китобда бордир.",383,20],["إِ[g[نّ]َ هَ[n[ـٰ]ذَا [h:6544[ٱ]لْقُرْءَانَ يَقُصُّ عَلَىٰ بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ أَكْثَرَ [h:10027[ٱ]لَّذِى هُمْ فِيهِ يَخْتَلِف[p[ُو]نَ","Албатта, ушбу Қуръон Бани Исроилга улар ихтилофлар қилаётган нарсаларнинг кўпини айтиб берадир.",383,20],["وَإِ[g[نّ]َهُ[n[ۥ] لَهُ[a:10028[دًى و]َرَحْمَ[u:6096[ةٌ ل]ِّلْمُؤْمِن[p[ِي]نَ","Албатта, у мўминлар учун ҳидоят ва раҳматдир.",384,20],["إِ[g[نّ]َ رَبَّكَ يَ[q:6194[قْ]ضِى بَيْنَه[c:10029[ُم ب]ِحُكْمِه[n[ِۦ]‌ۚ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:10030[ٱ]لْعَل[p[ِي]مُ","Албатта, Роббинг улар ўртасида Ўз ҳукми ила ажрим чиқарур. У азиз ва билгувчидир.",384,20],["فَتَوَكَّلْ عَلَى [h:412[ٱ]للَّهِ‌ۖ إِ[g[نّ]َكَ عَلَى [h:10031[ٱ]لْحَقِّ [h:10032[ٱ]لْمُب[p[ِي]نِ","Бас, сен Аллоҳга таваккал қил. Албатта, сен очиқ-ойдин ҳақдадирсан.",384,20],["إِ[g[نّ]َكَ لَا تُسْمِعُ [h:10033[ٱ]لْمَوْتَىٰ وَلَا تُسْمِعُ [h:6070[ٱ][l[ل]صُّ[g[مّ]َ [h:10034[ٱ][l[ل]دُّع[o[َا]ٓءَ إِذَا وَلَّوْ[s[اْ] مُ[q:5528[دْ]بِر[p[ِي]نَ","Албатта, сен ўликларга эшиттира олмассан, ортга қараб қочаётган карларга ҳам чақириқни эшиттира олмайссан.",384,20],["وَم[o[َآ] أَ[f:169[نت]َ بِهَ[n[ـٰ]دِى [h:10035[ٱ]لْعُمْىِ عَ[f:10036[ن ض]َلَ[n[ـٰ]لَتِهِمْ‌ۖ إِ[f:10037[ن ت]ُسْمِعُ إِلَّا م[a:5799[َن ي]ُؤْمِنُ بِـَٔـايَ[n[ـٰ]تِنَا فَه[w:10038[ُم م]ُّسْلِم[p[ُو]نَ","Сен кўрларни залолатдан ҳидоятга солгувчи эмассан. Сен фақат мусулмон бўлган ҳолларида оятларимизга иймон келтирадиганларгагина эшиттира олурсан.",384,20],["۞ وَإِذَا وَقَعَ [h:10039[ٱ]لْقَوْلُ عَلَيْهِمْ أَخْرَ[q:1577[جْ]نَا لَهُمْ د[m[َا]ٓبَّ[a:10040[ةً م]ِّنَ [h:1579[ٱ]لْأَرْضِ تُكَلِّمُهُمْ أَ[g[نّ]َ [h:10041[ٱ][l[ل][g[نّ]َاسَ كَانُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا لَا يُوقِن[p[ُو]نَ","Қачонки уларнинг бошига сўз тушганида, Биз улар учун ердан бир жонивор чиқарамиз. У уларга, албатта, одамлар Бизнинг оятларимизга ишонмайдиган бўлганларини айтиб берадир.",384,20],["وَيَوْمَ نَحْشُرُ مِ[f:843[ن ك]ُلِّ أُ[g[مّ]َ[f:10042[ةٍ ف]َوْ[a:10043[جًا م]ِّ[g[مّ][a:10044[َن ي]ُكَذِّبُ بِـَٔـايَ[n[ـٰ]تِنَا فَهُمْ يُوزَع[p[ُو]نَ","Биз ҳар умматнинг оятларимизни ёлғонга чиқарганларидан бир гуруҳини тўплаган кунда улар жамланиб-тизилиб туришар.",384,20],["حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءُو قَالَ أَكَذَّ[q:10045[بْ]ت[c:10046[ُم ب]ِـَٔـايَ[n[ـٰ]تِى وَلَمْ تُحِيطُو[s[اْ] بِهَا عِلْمًا أَ[g[مّ]َاذَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Токи улар келиб бўлгач, У зот: «Бизнинг оятларимизни ёлғонга чиқардингизми?! Уларни пухта англамай туриб-а? Йўқса, нима қилган эдингиз?» дейдир.",384,20],["وَوَقَعَ [h:10047[ٱ]لْقَوْلُ عَلَيْه[c:10048[ِم ب]ِمَا ظَلَمُو[s[اْ] فَهُمْ لَا يَ[f:8795[نط]ِق[p[ُو]نَ","Ва уларга зулм қилганлари сабабли сўз тушар. Бас, улар сўзлай олмаслар.",384,20],["أَلَمْ يَرَوْ[s[اْ] أَ[g[نّ]َا جَعَلْنَا [h:10049[ٱ]لَّيْلَ لِيَسْكُنُو[s[اْ] فِيهِ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ مُ[q:6118[بْ]صِرًا‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Биз сокинлик топишлари учун кечани, кўришлари учун кундузни қилганимизни кўрмадиларми?! Албатта, бунда иймон келтирадиган қавмлар учун ибратлар бордир.",384,20],["وَيَوْمَ يُ[f:4184[نف]َخُ فِى [h:4185[ٱ][l[ل]صُّورِ فَفَزِعَ مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَ[f:3453[ن ف]ِى [h:44[ٱ]لْأَرْضِ إِلَّا مَ[f:9680[ن ش][o[َا]ٓءَ [h:78[ٱ]للَّهُ‌ۚ وَكُلٌّ أَتَوْهُ د[n[َٲ]خِر[p[ِي]نَ","Сур чалиниб, Аллоҳ хоҳлаганидан бошқа осмонлардаги кимсалар ва ердаги кимсалар даҳшатга тушган кунда ҳамма У зотга бўйин эгиб келурлар.",384,20],["وَتَرَى [h:10050[ٱ]لْجِبَالَ تَحْسَبُهَا جَامِدَ[a:10051[ةً و]َهِىَ تَمُرُّ مَرَّ [h:10052[ٱ][l[ل]سَّحَابِ‌ۚ صُنْعَ [h:10053[ٱ]للَّهِ [h:7038[ٱ]لَّذ[o[ِىٓ] أَتْقَنَ كُلَّ شَىْءٍ‌ۚ إِ[g[نّ]َهُ[n[ۥ] خَبِي[i:2335[رُۢ ب]ِمَا تَفْعَل[p[ُو]نَ","Тоғларни кўриб, қимирламай турибди деб ҳисоблайсан. Ҳолбуки, улар булутнинг ўтишидек ўтурлар. Бу ҳар бир нарсани пухта қиладиган Аллоҳнинг санъатидир. Албатта, у нима қилаётганингиздан хабардордир.",384,20],["مَ[f:4560[ن ج][o[َا]ٓءَ بِ[h:4561[ٱ]لْحَسَنَةِ فَلَهُ[n[ۥ] خَيْ[a:10054[رٌ م]ِّنْهَا وَه[w:8717[ُم م]ِّ[f:10055[ن ف]َزَ[a:10056[عٍ ي]َوْمَئِذٍ ءَامِن[p[ُو]نَ","Ким яхшилик қилса, унга ундан кўра яхшироқ бўлур. Ҳамда улар ўша куннинг даҳшатидан омондадирлар.",385,20],["وَمَ[f:4562[ن ج][o[َا]ٓءَ بِ[h:4563[ٱ][l[ل]سَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِى [h:4674[ٱ][l[ل][g[نّ]َارِ هَلْ تُ[q:4248[جْ]زَوْنَ إِلَّا مَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Ким ёмонлик қилса, бас, юзтубан дўзахга ташланурлар ва: «Сизларга фақат қилган амалларингиз жазоси берилмоқда, холос»,.",385,20],["إِ[g[نّ]َم[o[َآ] أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَ[n[ـٰ]ذِهِ [h:10057[ٱ]لْبَلْدَةِ [h:10058[ٱ]لَّذِى حَرَّمَهَا وَلَهُ[n[ۥ] كُلُّ ش[a:10059[َىْءٍ‌ۖ و]َأُمِرْتُ أَنْ أَكُونَ مِنَ [h:6135[ٱ]لْمُسْلِم[p[ِي]نَ","Мен ушбу шаҳарнинг Робби, уни ҳаром қилган зотга ибодат қилишга амр этилдим, холос. Ҳамма нарса Уникидир. Ва мусулмонлардан бўлишга амр этилдим.",385,20],["وَأَنْ أَتْلُوَ[s[اْ] [h:10060[ٱ]لْقُرْءَانَ‌ۖ فَمَنِ [h:6230[ٱ]هْتَدَىٰ فَإِ[g[نّ]َمَا يَهْتَدِى لِنَفْسِه[n[ِۦ]‌ۖ وَمَ[f:6231[ن ض]َلَّ فَقُلْ إِ[g[نّ]َم[o[َآ] أَنَا۟ مِنَ [h:9852[ٱ]لْمُ[f:9853[نذ]ِر[p[ِي]نَ","Ва Қуръонни тиловат қилишга. Ким ҳидоят топса, фақат ўзи учун ҳидоят топадир. Ким залолатга кетса, унга: «Мен огоҳлантиргувчиларданман, холос», дегин.",385,20],["وَقُلِ [h:7938[ٱ]لْحَمْدُ لِلَّهِ سَيُرِيكُمْ ءَايَ[n[ـٰ]تِه[n[ِۦ] فَتَعْرِفُونَهَا‌ۚ وَمَا رَبُّكَ بِغَ[n[ـٰ]فِلٍ عَ[g[مّ]َا تَعْمَل[p[ُو]نَ","Сен: «Аллоҳга ҳамд бўлсин! У сизларга ўз оят-мўъжизаларини кўрсатур. Сиз уларни кўриб, танийсиз», деб айт. Роббинг қилаётган амалларингиздан ғофил эмасдир.",385,20]]},{"n":28,"ar":"القَصَصِ","en":"Al-Qasas","uz":"Қасас","type":"Макка","ayahs":[["ط[m[سٓ][m[مٓ]","То. Сийн. Мийм.",385,20],["تِلْكَ ءَايَ[n[ـٰ]تُ [h:5932[ٱ]لْكِتَ[n[ـٰ]بِ [h:6541[ٱ]لْمُب[p[ِي]نِ","Ушбулар очиқ-ойдин китоб оятларидир.",385,20],["نَتْلُو[s[اْ] عَلَيْكَ م[a:10061[ِن ن]َّبَإِ مُوسَىٰ وَفِرْعَوْنَ بِ[h:370[ٱ]لْحَقِّ لِقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Иймон келтирадиган қавм учун сенга Мусо ва Фиръавннинг хабаридан ҳақ ила тиловат қилиб берамиз.",385,20],["إِ[g[نّ]َ فِرْعَوْنَ عَلَا فِى [h:44[ٱ]لْأَرْضِ وَجَعَلَ أَهْلَهَا شِيَ[a:10062[عًا ي]َسْتَضْعِفُ ط[o[َا]ٓئِفَ[a:10063[ةً م]ِّنْهُمْ يُذَبِّحُ أَ[q:767[بْ]ن[o[َا]ٓءَهُمْ وَيَسْتَحْى[n[ِۦ] نِس[o[َا]ٓءَهُمْ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ مِنَ [h:6188[ٱ]لْمُفْسِد[p[ِي]نَ","Албатта, Фиръавн ер юзида баланд кетди. У нинг аҳолисини бўлиб ташлади. Улардан бир тоифасини эзар, ўғилларини сўйиб, қизларини тирик қолдирарди. Албатта, у бузғунчилардан бўлган эди.",385,20],["وَنُرِيدُ أ[a:10064[َن ن]َّمُ[g[نّ]َ عَلَى [h:289[ٱ]لَّذِينَ [h:10065[ٱ]سْتُضْعِفُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ وَنَ[q:10066[جْ]عَلَهُمْ أَئِ[g[مّ]َ[a:10067[ةً و]َنَ[q:10068[جْ]عَلَهُمُ [h:10069[ٱ]لْو[n[َٲ]رِث[p[ِي]نَ","Биз эса, ер юзида эзилганларга беминнат неъмат беришни, уларни пешво қилишни ва уларни ворислар қилишни.",385,20],["وَنُمَكِّنَ لَهُمْ فِى [h:44[ٱ]لْأَرْضِ وَنُرِىَ فِرْعَوْنَ وَهَ[n[ـٰ]مَ[n[ـٰ]نَ وَجُنُودَهُمَا مِنْه[w:3670[ُم م]َّا كَانُو[s[اْ] يَحْذَر[p[ُو]نَ","Ва ер юзида уларга имконлар беришни, Фиръавн, Ҳомон ва икковининг аскарларига улардан қўрққан нарсаларини кўрсатишни истаймиз.",386,20],["وَأَوْحَيْن[o[َآ] إِلَ[o[ىٰٓ] أُ[g[مّ]ِ مُوسَ[o[ىٰٓ] أَنْ أَرْضِعِيهِ‌ۖ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِى [h:4971[ٱ]لْيَ[g[مّ]ِ وَلَا تَخَافِى وَلَا تَحْزَن[o[ِىٓ‌ۖ] إِ[g[نّ]َا ر[m[َا]ٓدُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ [h:4822[ٱ]لْمُرْسَل[p[ِي]نَ","Ва Мусонинг онасига: «Уни эмизавер. Бас, қўрққан чоғингда уни дарёга ташла, қўрқма, хафа бўлма, Биз, албатта, уни сенга қайтаргувчимиз ва Пайғамбарлардан қилгувчимиз», деб ваҳий қилдик.",386,20],["فَ[h:9999[ٱ]لْتَقَطَهُ[o[ۥٓ] ءَالُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُو[a:10070[ًّا و]َحَزَنًا‌ۗ إِ[g[نّ]َ فِرْعَوْنَ وَهَ[n[ـٰ]مَ[n[ـٰ]نَ وَجُنُودَهُمَا كَانُو[s[اْ] خَ[n[ـٰ]طِــٔ[p[ِي]نَ","Бас, Фиръавн оиласи уни ўзларига душман ва ғам-ғусса бўлиши учун тутиб олдилар. Албатта, Фиръавн, Ҳомон ва икковларининг аскарлари хатокорлардан бўлган эдилар.",386,20],["وَقَالَتِ [h:10071[ٱ]مْرَأَتُ فِرْعَوْنَ قُرَّتُ عَيْ[u:10072[نٍ ل]ِّى وَلَكَ‌ۖ لَا تَ[q:10073[قْ]تُلُوهُ عَسَ[o[ىٰٓ] أ[a:6597[َن ي]َ[f:6598[نف]َعَن[o[َآ] أَوْ نَتَّخِذَهُ[n[ۥ] وَلَ[a:10074[دًا و]َهُمْ لَا يَشْعُر[p[ُو]نَ","Фиръавннинг хотини: « мен учун ҳам, сен учун ҳам кўз қувончидир. Уни ўлдирманглар. Шоядки, у бизга фойда берса ёки уни бола қилиб олсак», деди. Ҳолбуки, улар сезмасдилар.",386,20],["وَأَصْبَحَ فُؤَادُ أُ[g[مّ]ِ مُوسَىٰ فَ[n[ـٰ]رِغًا‌ۖ إِ[f:10075[ن ك]َادَتْ لَتُ[q:10076[بْ]دِى بِه[n[ِۦ] لَوْل[o[َآ] أ[u:10077[َن ر]َّبَ[q:10078[طْ]نَا عَلَىٰ قَلْبِهَا لِتَكُونَ مِنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Мусонинг онасининг қалби бўшаб қолди. Мўминлардан бўлиши учун қалбини мустаҳкам боғламаганимизда, уни билдириб қўйишига сал қолди.",386,20],["وَقَالَتْ لِأُخْتِه[n[ِۦ] قُصِّيهِ‌ۖ فَبَصُرَتْ بِه[n[ِۦ] عَ[f:10079[ن ج]ُنُ[a:10080[بٍ و]َهُمْ لَا يَشْعُر[p[ُو]نَ","У унинг опасига: «Изидан бор», деди. Бас, уни бир четдан кўрди. Ҳолбуки, улар сезмасдилар.",386,20],["۞ وَحَرَّمْنَا عَلَيْهِ [h:10081[ٱ]لْمَرَاضِعَ مِ[f:128[ن ق]َ[q:129[بْ]لُ فَقَالَتْ هَلْ أَدُلُّكُمْ عَلَ[o[ىٰٓ] أَهْلِ بَيْ[a:10082[تٍ ي]َكْفُلُونَهُ[n[ۥ] لَكُمْ وَهُمْ لَهُ[n[ۥ] نَ[n[ـٰ]صِح[p[ُو]نَ","Ва бундан олдин унга эмизгувчиларни ҳаром қилган эдик. Бас,: «Мен сизларга уни сиз учун кафилликка оладиган ва унга насиҳатгўй бўлгувчи аҳли байтни айтиб берайми?» деди.",386,20],["فَرَدَ[q:10083[دْ]نَ[n[ـٰ]هُ إِلَ[o[ىٰٓ] أُ[g[مّ]ِه[n[ِۦ] كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ أَ[g[نّ]َ وَعْدَ [h:3149[ٱ]للَّهِ حَ[a:6092[قٌّ و]َلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَعْلَم[p[ُو]نَ","Бас, Биз уни онасига кўзи қувончга тўлиши, хафа бўлмаслиги ва, албатта, Аллоҳнинг ваъдаси ҳақ эканини билиши учун қайтардик. Лекин кўплари буни билмаслар.",386,20],["وَلَ[g[مّ]َا بَلَغَ أَشُدَّهُ[n[ۥ] وَ[h:10084[ٱ]سْتَوَ[o[ىٰٓ] ءَاتَيْنَ[n[ـٰ]هُ حُكْ[a:6600[مًا و]َعِلْ[a:6601[مًا‌ۚ و]َكَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4215[ٱ]لْمُحْسِن[p[ِي]نَ","Қачонки у вояга етиб, мукаммал бўлганида, унга ҳикмат ва илмни бердик. Биз яхши амал қилгувчиларни шундай мукофотлармиз.",387,20],["وَدَخَلَ [h:10085[ٱ]لْمَدِينَةَ عَلَىٰ حِينِ غَفْلَ[a:8863[ةٍ م]ِّنْ أَهْلِهَا فَوَجَدَ فِيهَا رَجُلَيْنِ يَ[q:10086[قْ]تَتِلَانِ هَ[n[ـٰ]ذَا مِ[f:10087[ن ش]ِيعَتِه[n[ِۦ] وَهَ[n[ـٰ]ذَا مِنْ عَدُوِّه[n[ِۦ]‌ۖ فَ[h:10088[ٱ]سْتَغَ[n[ـٰ]ثَهُ [h:10089[ٱ]لَّذِى مِ[f:10087[ن ش]ِيعَتِه[n[ِۦ] عَلَى [h:4534[ٱ]لَّذِى مِنْ عَدُوِّه[n[ِۦ] فَوَكَزَهُ[n[ۥ] مُوسَىٰ فَقَضَىٰ عَلَيْهِ‌ۖ قَالَ هَ[n[ـٰ]ذَا مِنْ عَمَلِ [h:3767[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ‌ۖ إِ[g[نّ]َهُ[n[ۥ] عَدُ[a:10090[وٌّ م]ُّضِ[a:10091[لٌّ م]ُّب[p[ِي]نٌ","Ва у шаҳарга унинг аҳолиси ғафлатдалик пайтда кирди. Унда уришаётган икки кишини кўрди. Буниси ўз гуруҳидан, униси эса, душманларидан эди. Бас, ўз гуруҳидан бўлган душман бўлганга қарши ундан ёрдам сўради. Шунда Мусо уни бир мушт уриб ўлдириб қўйди. У: «Бу шайтоннинг ишидир. Албатта, у очиқ-ойдин душман ва йўлдан оздиргувчидир», деди.",387,20],["قَالَ رَبِّ إِ[g[نّ]ِى ظَلَمْتُ نَفْسِى فَ[h:1791[ٱ]غْفِرْ لِى فَغَفَرَ لَهُ[o[ۥٓ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:6822[ٱ]لْغَفُورُ [h:6228[ٱ][l[ل]رَّح[p[ِي]مُ","У: «Эй Роббим, албатта, мен ўзимга зулм қилдим. Бас, мени мағфират қил», деди. Шунда У зот уни мағфират қилди. Албатта, Унинг Ўзи мағфират қилгувчи, меҳрибондир.",387,20],["قَالَ رَبِّ بِم[o[َآ] أَنْعَمْتَ عَلَىَّ فَلَنْ أَكُونَ ظَهِي[u:10092[رًا ل]ِّلْمُ[q:9609[جْ]رِم[p[ِي]نَ","У: «Эй Роббим, менга берган неъматнинг ҳаққи-ҳурмати ҳаргиз жиноятчиларга ёрдамчи бўлмасман», деди.",387,20],["فَأَصْبَحَ فِى [h:4932[ٱ]لْمَدِينَةِ خ[o[َا]ٓئِ[a:10093[فًا ي]َتَرَقَّبُ فَإِذَا [h:10094[ٱ]لَّذِى [h:10095[ٱ]سْتَ[f:10096[نص]َرَهُ[n[ۥ] بِ[h:6017[ٱ]لْأَمْسِ يَسْتَصْرِخُهُ[n[ۥ]‌ۚ قَالَ لَهُ[n[ۥ] مُوسَ[o[ىٰٓ] إِ[g[نّ]َكَ لَغَوِ[a:10097[ىٌّ م]ُّب[p[ِي]نٌ","Бас, у эрталаб шаҳарда қўрққан ҳолида, аланглаб кетаётган эди, бирдан кеча ундан ёрдам сўраган яна ёрдам сўраб қичқириб қолди. Мусо унга: «Албатта, сен очиқ-ойдин гумроҳсан», деди.",387,20],["فَلَ[g[مّ][o[َآ] أَنْ أَرَادَ أ[a:10098[َن ي]َ[q:10099[بْ]طِشَ بِ[h:315[ٱ]لَّذِى هُوَ عَدُ[u:10100[وٌّ ل]َّهُمَا قَالَ يَ[n[ـٰ]مُوسَ[o[ىٰٓ] أَتُرِيدُ أَ[f:10101[ن ت]َ[q:10102[قْ]تُلَنِى كَمَا قَتَلْتَ نَفْس[i:10103[َۢا ب]ِ[h:6017[ٱ]لْأَمْسِ‌ۖ إِ[f:10104[ن ت]ُرِيدُ إِلّ[o[َآ] أَ[f:1566[ن ت]َكُونَ جَبَّا[f:10105[رًا ف]ِى [h:44[ٱ]لْأَرْضِ وَمَا تُرِيدُ أَ[f:1566[ن ت]َكُونَ مِنَ [h:10106[ٱ]لْمُصْلِح[p[ِي]نَ","Қачонки икковларига душман бўлганни тутмоқчи бўлган эди, у: «Эй Мусо, кеча бир жонни ўлдирганинг каби, мени ўлдирмоқчимисан?! Сен ер юзида фақат жаббор бўлишни истайсан ва ислоҳ қилгувчилардан бўлишни истамайсан», деди.",387,20],["وَج[o[َا]ٓءَ رَجُ[a:10107[لٌ م]ِّنْ أَ[q:10108[قْ]صَا [h:10109[ٱ]لْمَدِينَةِ يَسْعَىٰ قَالَ يَ[n[ـٰ]مُوسَ[o[ىٰٓ] إِ[g[نّ]َ [h:10110[ٱ]لْمَلَأَ يَأْتَمِرُونَ بِكَ لِيَ[q:10111[قْ]تُلُوكَ فَ[h:4603[ٱ]خْرُ[q:4603[جْ] إِ[g[نّ]ِى لَكَ مِنَ [h:10112[ٱ][l[ل][g[نّ]َ[n[ـٰ]صِح[p[ِي]نَ","Ва шаҳарнинг нариги четидан бир киши шошиб келиб: «Эй Мусо, аниқки, аъёнлар сени ўлдириш учун тил бириктирмоқдалар. Бас, чиқиб кет! Албатта, мен сенга насиҳат қилгувчиларданман», деди.",387,20],["فَخَرَجَ مِنْهَا خ[o[َا]ٓئِ[a:10093[فًا ي]َتَرَقَّبُ‌ۖ قَالَ رَبِّ نَجِّنِى مِنَ [h:4196[ٱ]لْقَوْمِ [h:4155[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Бас, хавфсираб, аланглаган ҳолда у ердан: «Эй Роббим, менга золим қавмлардан нажот бергин», деб чиқди.",387,20],["وَلَ[g[مّ]َا تَوَجَّهَ تِلْق[o[َا]ٓءَ مَ[q:4842[دْ]يَنَ قَالَ عَسَىٰ رَبّ[o[ِىٓ] أ[a:10113[َن ي]َهْدِيَنِى سَو[o[َا]ٓءَ [h:564[ٱ][l[ل]سَّب[p[ِي]لِ","Қачонки Мадян томон юзланганида: «Шоядки Роббим мени тўғри йўлга ҳидоят қилса», деди.",388,20],["وَلَ[g[مّ]َا وَرَدَ م[o[َا]ٓءَ مَ[q:4842[دْ]يَنَ وَجَدَ عَلَيْهِ أُ[g[مّ]َ[a:10114[ةً م]ِّنَ [h:721[ٱ][l[ل][g[نّ]َاسِ يَسْقُونَ وَوَجَدَ مِ[f:10115[ن د]ُونِهِمُ [h:10116[ٱ]مْرَأَتَيْنِ تَذُودَانِ‌ۖ قَالَ مَا خَ[q:10117[طْ]بُكُمَا‌ۖ قَالَتَا لَا نَسْقِى حَتَّىٰ يُصْدِرَ [h:10118[ٱ][l[ل]رِّع[o[َا]ٓءُ‌ۖ وَأَبُونَا شَيْ[f:10119[خٌ ك]َب[p[ِي]رٌ","Қачонки Мадян сувига етиб келгач, бир тўп одамларнинг ҳайвонларини суғораётганини кўрди ва улардан бошқа қайтараётган икки аёлни кўрди. У: «Сизларга не бўлди?» деди. Улар: «Чўпонлар қайтмагунларича суғора олмаймиз, отамиз қари чол», дедилар.",388,20],["فَسَقَىٰ لَهُمَا ثُ[g[مّ]َ تَوَلَّ[o[ىٰٓ] إِلَى [h:10120[ٱ][l[ل]ظِّلِّ فَقَالَ رَبِّ إِ[g[نّ]ِى لِم[o[َآ] أَ[f:1954[نز]َلْتَ إِلَىَّ مِنْ خَيْ[f:10121[رٍ ف]َق[p[ِي]رٌ","Бас, икковларига суғориб берди. Сўнгра сояга қайтди ва «Эй Роббим, албатта, менга туширажагинг ҳар бир яхшиликка муҳтожман», деди.",388,20],["فَج[o[َا]ٓءَتْهُ إِحْدَ[n[ٮٰ]هُمَا تَمْشِى عَلَى [h:10122[ٱ]سْتِحْي[o[َا]ٓ[f:10123[ءٍ ق]َالَتْ إِ[g[نّ]َ أَبِى يَ[q:10124[دْ]عُوكَ لِيَ[q:10125[جْ]زِيَكَ أَ[q:2418[جْ]رَ مَا سَقَيْتَ لَنَا‌ۚ فَلَ[g[مّ]َا ج[o[َا]ٓءَهُ[n[ۥ] وَقَصَّ عَلَيْهِ [h:10126[ٱ]لْقَصَصَ قَالَ لَا تَخَفْ‌ۖ نَجَوْتَ مِنَ [h:4196[ٱ]لْقَوْمِ [h:4155[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Бас, икковларидан бири ҳаё билан юриб келиб: «Отам сенга бизларга суғориб берганинг ҳаққини бериш учун чақирмоқда», деди. Қачонки унга келганида ва қиссани айтиб берганида, у: «Қўрқма, золим қавмлардан нажот топдинг», деди.",388,20],["قَالَتْ إِحْدَ[n[ٮٰ]هُمَا يَ[o[ـٰٓ]أَبَتِ [h:10127[ٱ]سْتَــْٔجِرْهُ‌ۖ إِ[g[نّ]َ خَيْرَ مَنِ [h:10128[ٱ]سْتَــْٔجَرْتَ [h:10129[ٱ]لْقَوِىُّ [h:10130[ٱ]لْأَم[p[ِي]نُ","Икки дан бири: «Эй отагинам, уни ишга ёллаб ол. Чунки ишга ёлланадиган энг яхши кимса кучли ва ишончли кимсадир», деди.",388,20],["قَالَ إِ[g[نّ][o[ِىٓ] أُرِيدُ أَنْ أُ[f:10131[نك]ِحَكَ إِحْدَى [h:10132[ٱ][q:10133[بْ]نَتَىَّ هَ[n[ـٰ]تَيْنِ عَلَ[o[ىٰٓ] أَ[f:10134[ن ت]َأْجُرَنِى ثَمَ[n[ـٰ]نِىَ حِجَ[f:10135[جٍ‌ۖ ف]َإِنْ أَتْمَمْتَ عَشْ[f:10136[رًا ف]َمِنْ عِ[f:2954[ند]ِكَ‌ۖ وَم[o[َآ] أُرِيدُ أَنْ أَشُقَّ عَلَيْكَ‌ۚ سَتَجِدُن[o[ِىٓ] إِ[f:364[ن ش][o[َا]ٓءَ [h:78[ٱ]للَّهُ مِنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","У: «Менга саккиз йил ишлаб беришинг шарти билан, шу икки қизимдан бирини сенга никоҳлаб бермоқчиман, агар ўн йилни тамомласанг, бу сенинг ишинг. Мен эса сенга машаққат қилишни истамайман. Иншааллоҳ, менинг солиҳ кишилардан эканимни кўрасан», деди.",388,20],["قَالَ ذ[n[َٲ]لِكَ بَيْنِى وَبَيْنَكَ‌ۖ أَيَّمَا [h:10137[ٱ]لْأَجَلَيْنِ قَضَيْتُ فَلَا عُ[q:1034[دْ]و[n[َٲ]نَ عَلَىَّ‌ۖ وَ[h:72[ٱ]للَّهُ عَلَىٰ مَا نَقُولُ وَك[p[ِي]لٌ","У: «Бу мен билан сенинг орамиздадир. Икки муддатдан қай бирини адо қилсам ҳам, менга тажовуз қилинмас. Айтаётган нарсамизга Аллоҳ вакилдир», деди.",388,20],["۞ فَلَ[g[مّ]َا قَضَىٰ مُوسَى [h:10138[ٱ]لْأَجَلَ وَسَارَ بِأَهْلِه[o[ِۦٓ] ءَانَسَ مِ[f:8361[ن ج]َانِبِ [h:8362[ٱ][l[ل]طُّورِ نَا[f:8235[رًا ق]َالَ لِأَهْلِهِ [h:8447[ٱ]مْكُث[o[ُوٓ][s[اْ] إِ[g[نّ][o[ِىٓ] ءَانَسْتُ نَا[u:8448[رًا ل]َّعَلّ[o[ِىٓ] ءَاتِيك[w:8449[ُم م]ِّنْهَا بِخَبَرٍ أَوْ جَذْوَ[a:10139[ةٍ م]ِّنَ [h:869[ٱ][l[ل][g[نّ]َارِ لَعَلَّكُمْ تَصْطَل[p[ُو]نَ","Қачонки, Мусо муддатни тугатиб, аҳли билан йўлга тушиб кетаётиб, Тур томонда узоқдан оловни кўриб қолди. У аҳлига: «Туриб туринглар, аниқки, мен узоқдан оловни кўрдим. Балки у ердан сизга бирор хабар ёки исинишингиз учун бир тутам чўғ олиб келарман», деди.",389,20],["فَلَ[g[مّ][o[َآ] أَتَ[n[ـٰ]هَا نُودِىَ مِ[f:10140[ن ش]َ[n[ـٰ]طِىِٕ [h:10141[ٱ]لْوَادِ [h:10142[ٱ]لْأَيْمَنِ فِى [h:10143[ٱ]لْبُ[q:10144[قْ]عَةِ [h:10145[ٱ]لْمُبَ[n[ـٰ]رَكَةِ مِنَ [h:10146[ٱ][l[ل]شَّجَرَةِ أ[a:10147[َن ي]َ[n[ـٰ]مُوسَ[o[ىٰٓ] إِ[g[نّ][o[ِىٓ] أَنَا [h:8455[ٱ]للَّهُ رَبُّ [h:4750[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Бас, қачонки унинг олдига етиб келганида, водийнинг ўнг томонидан, муборак жойдан, дарахтдан унга: «Эй Мусо, албатта, Мен, Ўзим, оламларнинг Робби Аллоҳдирман.",389,20],["وَأَنْ أَلْقِ عَصَاكَ‌ۖ فَلَ[g[مّ]َا رَءَاهَا تَهْتَزُّ كَأَ[g[نّ]َهَا ج[m[َا]ٓ[a:9895[[g[نّ]ٌ و]َلَّىٰ مُ[q:9896[دْ]بِ[a:9897[رًا و]َلَمْ يُعَقِّ[q:9898[بْ]‌ۚ يَ[n[ـٰ]مُوسَ[o[ىٰٓ] أَ[q:10148[قْ]بِلْ وَلَا تَخَفْ‌ۖ إِ[g[نّ]َكَ مِنَ [h:10149[ٱ]لْأَمِن[p[ِي]نَ","Ва асонгни ташла», деб нидо қилинди. Қачонки унинг катта илон каби қимирлаётганини кўргач, қарамасдан ортга қочди. «Эй Мусо, бери кел, қўрқма, албатта, сен омонликдагилардансан».",389,20],["ٱسْلُكْ يَدَكَ فِى جَيْبِكَ تَخْرُ[q:8461[جْ] بَيْض[o[َا]ٓءَ مِنْ غَيْرِ س[o[ُو]ٓ[a:10150[ءٍ و]َ[h:10151[ٱ]ضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ [h:10152[ٱ][l[ل]رَّهْبِ‌ۖ فَذ[n[َٲ]نِكَ بُرْهَ[n[ـٰ]نَانِ م[u:770[ِن ر]َّبِّكَ إِلَىٰ فِرْعَوْنَ وَمَلَإِ[s[يْ]ه[o[ِۦٓ‌ۚ] إِ[g[نّ]َهُمْ كَانُو[s[اْ] قَوْ[f:5652[مًا ف]َ[n[ـٰ]سِق[p[ِي]نَ","«Қўлингни ёқангдан суқ, бирон нуқсонсиз оппоқ бўлиб чиқур ва қўрқувда қанотингни ўзингга тортиб ол. Бас, шу иккиси Роббингдан Фиръавн ва унинг одамларига икки ҳужжатдир. Албатта, улар фосиқ қавм бўлдилар».",389,20],["قَالَ رَبِّ إِ[g[نّ]ِى قَتَلْتُ مِنْهُمْ نَفْ[f:10153[سًا ف]َأَخَافُ أ[a:9725[َن ي]َ[q:9726[قْ]تُل[p[ُو]نِ","У: «Эй Роббим, мен улардан бир жонни ўлдирганман, улар мени ўлдиришларидан қўрқурман.",389,20],["وَأَخِى هَ[n[ـٰ]رُونُ هُوَ أَفْصَحُ مِ[g[نّ]ِى لِسَا[f:10154[نًا ف]َأَرْسِلْهُ مَعِىَ رِ[q:10155[دْ][a:10156[ءًا ي]ُصَدِّقُن[o[ِىٓ‌ۖ] إِ[g[نّ][o[ِىٓ] أَخَافُ أ[a:9721[َن ي]ُكَذِّب[p[ُو]نِ","Биродарим Ҳорун мендан кўра тили бурророқ, уни ҳам мен билан юбор, мени тасдиқлайдир. Зеро, улар мени ёлғончи қилишларидан қўрқурман», деди.",389,20],["قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَ[q:10157[جْ]عَلُ لَكُمَا سُلْطَ[n[ـٰ][f:7745[نًا ف]َلَا يَصِلُونَ إِلَيْكُمَا‌ۚ بِـَٔـايَ[n[ـٰ]تِن[o[َآ] أَ[f:10158[نت]ُمَا وَمَنِ [h:10159[ٱ]تَّبَعَكُمَا [h:10160[ٱ]لْغَ[n[ـٰ]لِب[p[ُو]نَ","У зот: «Биз сени оғанг билан қувватлаймиз ва икковингизга бир салтанат берурмизки, улар сизга етиша олмаслар. Бизнинг оятларимиз ила иккингиз ва сизга эргашганлар ғолибдирсиз», деди.",389,20],["فَلَ[g[مّ]َا ج[o[َا]ٓءَه[w:10161[ُم م]ُّوسَىٰ بِـَٔـايَ[n[ـٰ]تِنَا بَيِّنَ[n[ـٰ][f:10162[تٍ ق]َالُو[s[اْ] مَا هَ[n[ـٰ]ذ[o[َآ] إِلَّا سِحْ[a:10163[رٌ م]ُّفْتَ[a:10164[رًى و]َمَا سَمِعْنَا بِهَ[n[ـٰ]ذَا ف[o[ِىٓ] ءَاب[o[َا]ٓئِنَا [h:9184[ٱ]لْأَوَّل[p[ِي]نَ","Бас, қачонки Мусо уларга очиқ-ойдин оятларимиз ила келганида, улар: «Бу уйдирма, сеҳрдан бошқа нарса эмас. Аввалги ота-боболаримиздан ҳам бу ҳақда эшитмаган эдик», дедилар.",390,20],["وَقَالَ مُوسَىٰ رَبّ[o[ِىٓ] أَعْلَمُ بِمَ[f:10165[ن ج][o[َا]ٓءَ بِ[h:54[ٱ]لْهُدَىٰ مِنْ عِ[f:3628[ند]ِه[n[ِۦ] وَمَ[f:10166[ن ت]َكُونُ لَهُ[n[ۥ] عَ[n[ـٰ]قِبَةُ [h:4439[ٱ][l[ل]دَّارِ‌ۖ إِ[g[نّ]َهُ[n[ۥ] لَا يُفْلِحُ [h:3981[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Ва Мусо: «Роббим Ўз ҳузуридан ким ҳидоят келтирганини ҳам, охират диёри оқибати кимга бўлишини ҳам яхши билгувчи зотдир. Албатта, золимлар нажот топмаслар», деди.",390,20],["وَقَالَ فِرْعَوْنُ يَ[o[ـٰٓ]أَيُّهَا [h:6683[ٱ]لْمَلَأُ مَا عَلِمْتُ لَك[w:556[ُم م]ِّنْ إِلَ[n[ـٰ]هٍ غَيْرِى فَأَوْقِ[q:10167[دْ] لِى يَ[n[ـٰ]هَ[n[ـٰ]مَ[n[ـٰ]نُ عَلَى [h:10168[ٱ][l[ل]طِّينِ فَ[h:7148[ٱ][q:7148[جْ]عَل لِّى صَرْ[u:10169[حًا ل]َّعَلّ[o[ِىٓ] أَطَّلِعُ إِلَ[o[ىٰٓ] إِلَ[n[ـٰ]هِ مُوسَىٰ وَإِ[g[نّ]ِى لَأَظُ[g[نّ]ُهُ[n[ۥ] مِنَ [h:4785[ٱ]لْكَ[n[ـٰ]ذِب[p[ِي]نَ","Ва Фиръавн: «Эй аъёнлар, мен сизларга ўзимдан бошқа илоҳ борлигини билмасман. Бас, эй Ҳомон, лойга ўт ёқиб, мен учун бир баланд қаср қур, шоядки Мусонинг илоҳини кўрсай. Албатта, мен уни ёлғончилардан деб ўйламоқдаман», деди.",390,20],["وَ[h:9999[ٱ]سْتَكْبَرَ هُوَ وَجُنُودُهُ[n[ۥ] فِى [h:44[ٱ]لْأَرْضِ بِغَيْرِ [h:325[ٱ]لْحَقِّ وَظَ[g[نّ][o[ُوٓ][s[اْ] أَ[g[نّ]َهُمْ إِلَيْنَا لَا يُرْجَع[p[ُو]نَ","У ва унинг аскарлари ер юзида ноҳақдан такаббурлик қилдилар ҳамда ўзларини Бизга қайтарилмайдилар деб гумон қилдилар.",390,20],["فَأَخَذْنَ[n[ـٰ]هُ وَجُنُودَهُ[n[ۥ] فَنَبَذْنَ[n[ـٰ]هُمْ فِى [h:4971[ٱ]لْيَ[g[مّ]ِ‌ۖ فَ[h:1513[ٱ][f:1513[نظ]ُرْ كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6064[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Бас, Биз уни ва унинг аскарларини тутдик ва денгизга отдик. Энди золимларнинг оқибати қандоқ бўлганига назар сол.",390,20],["وَجَعَلْنَ[n[ـٰ]هُمْ أَئِ[g[مّ]َ[a:10170[ةً ي]َ[q:1240[دْ]عُونَ إِلَى [h:1241[ٱ][l[ل][g[نّ]َارِ‌ۖ وَيَوْمَ [h:443[ٱ]لْقِيَ[n[ـٰ]مَةِ لَا يُ[f:237[نص]َر[p[ُو]نَ","Ва уларни дўзахга чақирадиган пешволар қилдик. Қиёмат куни эса, уларга ёрдам берилмас.",390,20],["وَأَتْبَعْنَ[n[ـٰ]هُمْ فِى هَ[n[ـٰ]ذِهِ [h:5052[ٱ][l[ل]دُّنْيَا لَعْنَ[a:6394[ةً‌ۖ و]َيَوْمَ [h:443[ٱ]لْقِيَ[n[ـٰ]مَةِ ه[w:10171[ُم م]ِّنَ [h:10172[ٱ]لْمَ[q:10173[قْ]بُوح[p[ِي]نَ","Ва бу дунёда уларга лаънатни эргаштириб қўйдик. Қиёмат куни эса, улар йироқ қилинганлардандирлар.",390,20],["وَلَقَ[q:341[دْ] ءَاتَيْنَا مُوسَى [h:257[ٱ]لْكِتَ[n[ـٰ]بَ م[i:146[ِنۢ ب]َعْدِ م[o[َآ] أَهْلَكْنَا [h:5975[ٱ]لْقُرُونَ [h:10174[ٱ]لْأُولَىٰ بَص[o[َا]ٓئِرَ لِل[g[نّ]َاسِ وَهُ[a:4537[دًى و]َرَحْمَ[u:4538[ةً ل]َّعَلَّهُمْ يَتَذَكَّر[p[ُو]نَ","Батаҳқиқ, Биз аввалги асрларни ҳалок қилганимиздан сўнг Мусога одамлар учун нур, ҳидоят ва раҳмат қилиб китобни бердик. Шоядки улар эсласалар.",390,20],["وَمَا كُ[f:735[نت]َ بِجَانِبِ [h:10175[ٱ]لْغَرْبِىِّ إِذْ قَضَيْن[o[َآ] إِلَىٰ مُوسَى [h:10176[ٱ]لْأَمْرَ وَمَا كُ[f:735[نت]َ مِنَ [h:2069[ٱ][l[ل]شَّ[n[ـٰ]هِد[p[ِي]نَ","Биз Мусога ишни ҳукм қилган пайтимизда сен ғарбий томонда эмас эдинг ва гувоҳлардан ҳам бўлмагансан.",391,20],["وَلَ[n[ـٰ]كِ[g[نّ][o[َآ] أَ[f:9202[نش]َأْنَا قُرُو[f:10177[نًا ف]َتَطَاوَلَ عَلَيْهِمُ [h:8761[ٱ]لْعُمُرُ‌ۚ وَمَا كُ[f:735[نت]َ ثَاوِ[f:10178[يًا ف][o[ِىٓ] أَهْلِ مَ[q:4842[دْ]يَنَ تَتْلُو[s[اْ] عَلَيْهِمْ ءَايَ[n[ـٰ]تِنَا وَلَ[n[ـٰ]كِ[g[نّ]َا كُ[g[نّ]َا مُرْسِل[p[ِي]نَ","Лекин Биз бир неча асрларни пайдо қилдик, бас, уларнинг умри чўзилди. Сен Мадянда туриб, уларга оятларимизни тиловат қилиб берганинг йўқ. Аммо Биз Пайғамбар юборгувчи бўлдик.",391,20],["وَمَا كُ[f:735[نت]َ بِجَانِبِ [h:10179[ٱ][l[ل]طُّورِ إِذْ نَادَيْنَا وَلَ[n[ـٰ]ك[u:10180[ِن ر]َّحْمَ[a:5993[ةً م]ّ[u:770[ِن ر]َّبِّكَ لِتُ[f:4582[نذ]ِرَ قَوْ[a:10181[مًا م]ّ[o[َآ] أَتَ[n[ـٰ]ه[w:10182[ُم م]ّ[a:10183[ِن ن]َّذِي[a:10184[رٍ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ لَعَلَّهُمْ يَتَذَكَّر[p[ُو]نَ","Биз нидо қилган чоғимизда Турнинг ёнида йўқ эдинг. Лекин Роббингдан раҳмат сифатида сендан олдин огоҳлантиргувчи келмаган қавмни огоҳлантириш учун. Шоядки эсласалар.",391,20],["وَلَوْل[o[َآ] أَ[f:9555[ن ت]ُصِيبَه[w:10185[ُم م]ُّصِيبَ[i:2877[ةُۢ ب]ِمَا قَدَّمَتْ أَيْدِيهِمْ فَيَقُولُو[s[اْ] رَبَّنَا لَوْل[o[َآ] أَرْسَلْتَ إِلَيْنَا رَسُول[f:8659[اً ف]َنَتَّبِعَ ءَايَ[n[ـٰ]تِكَ وَنَكُونَ مِنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Агар уларга қилмишлари туфайли мусибат етганида: «Эй Роббимиз, бизга Пайғамбар юборганингда эди, оятларингга эргашар эдик ва мўминлардан бўлар эдик», демасалар эди.",391,20],["فَلَ[g[مّ]َا ج[o[َا]ٓءَهُمُ [h:6141[ٱ]لْحَقُّ مِنْ عِ[f:6142[ند]ِنَا قَالُو[s[اْ] لَوْل[o[َآ] أُوتِىَ مِثْلَ م[o[َآ] أُوتِىَ مُوسَ[o[ىٰٓ‌ۚ] أَوَلَمْ يَكْفُرُو[s[اْ] بِم[o[َآ] أُوتِىَ مُوسَىٰ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ قَالُو[s[اْ] سِحْرَانِ تَظَ[n[ـٰ]هَرَا وَقَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا بِكُ[f:10186[لٍّ ك]َ[n[ـٰ]فِر[p[ُو]نَ","Қачонки уларга Бизнинг ҳузуримиздан ҳақ келганида, улар: «Унга ҳам Мусога берилган нарса берилса эди», дедилар. Улар илгари Мусога берилган нарсага куфр келтирмаган эдиларми?! Улар: «Икки сеҳр ўртага чиқди, бир-бирига ёрдам бермоқда, биз ҳар бирига куфр келтиргувчимиз», дедилар.",391,20],["قُلْ فَأْتُو[s[اْ] بِكِتَ[n[ـٰ][a:10187[بٍ م]ِّنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ هُوَ أَهْدَىٰ مِنْهُم[o[َآ] أَتَّبِعْهُ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Сен: «Агар ростгўйлардан бўлсангиз, Аллоҳнинг ҳузуридаги у иккисидан кўра тўғрироқ бир китоб келтиринг, мен унга эргашаман», дегин.",391,20],["فَإ[u:110[ِن ل]َّمْ يَسْتَجِيبُو[s[اْ] لَكَ فَ[h:3611[ٱ]عْلَمْ أَ[g[نّ]َمَا يَتَّبِعُونَ أَهْو[o[َا]ٓءَهُمْ‌ۚ وَمَنْ أَضَلُّ مِ[g[مّ]َنِ [h:10188[ٱ]تَّبَعَ هَوَ[n[ٮٰ]هُ بِغَيْرِ هُ[a:10189[دًى م]ِّنَ [h:321[ٱ]للَّهِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Агар сенга жавоб бера олмасалар, бас, билгинки, улар фақат ҳавои нафсларига эргашмоқдалар, холос. Аллоҳдан бўлган ҳидоятсиз, ўз ҳавои нафсига эргашгандан кўра ҳам гумроҳроқ кимса борми?! Албатта, Аллоҳ золим қавмларни ҳидоят қилмас.",391,20],["۞ وَلَقَ[q:341[دْ] وَصَّلْنَا لَهُمُ [h:10190[ٱ]لْقَوْلَ لَعَلَّهُمْ يَتَذَكَّر[p[ُو]نَ","Батаҳқиқ, Биз уларга гапни етказиб қўйдик. Шоядки эсласалар.",392,20],["ٱلَّذِينَ ءَاتَيْنَ[n[ـٰ]هُمُ [h:635[ٱ]لْكِتَ[n[ـٰ]بَ مِ[f:1097[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] ه[c:7581[ُم ب]ِه[n[ِۦ] يُؤْمِن[p[ُو]نَ","Удан олдин китоб берилганлар унга иймон келтирурлар.",392,20],["وَإِذَا يُتْلَىٰ عَلَيْهِمْ قَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا بِه[o[ِۦٓ] إِ[g[نّ]َهُ [h:6280[ٱ]لْحَقُّ م[u:10191[ِن ر]َّبِّن[o[َآ] إِ[g[نّ]َا كُ[g[نّ]َا مِ[f:1097[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] مُسْلِم[p[ِي]نَ","Уларга тиловат қилинган чоқда: «Биз унга иймон келтирдик. Албатта, у Роббимиздан келган ҳақдир. Албатта, биз бундан олдин ҳам мусулмон эдик», дедилар.",392,20],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يُؤْتَوْنَ أَ[q:7573[جْ]رَه[w:10192[ُم م]َّرَّتَيْنِ بِمَا صَبَرُو[s[اْ] وَيَ[q:6958[دْ]رَءُونَ بِ[h:4561[ٱ]لْحَسَنَةِ [h:6959[ٱ][l[ل]سَّيِّئَةَ وَمِ[g[مّ]َا رَزَ[q:15[قْ]نَ[n[ـٰ]هُمْ يُ[f:16[نف]ِق[p[ُو]نَ","Ана ўшаларга сабр қилганлари учун ажрлари икки марта берилган. Улар яхшилик ила ёмонликни даф қилурлар ва уларга ризқ қилиб берган нарсаларимиздан нафақа қилурлар.",392,20],["وَإِذَا سَمِعُو[s[اْ] [h:10193[ٱ][l[ل]لَّغْوَ أَعْرَضُو[s[اْ] عَنْهُ وَقَالُو[s[اْ] لَن[o[َآ] أَعْمَ[n[ـٰ]لُنَا وَلَكُمْ أَعْمَ[n[ـٰ]لُكُمْ سَلَ[n[ـٰ]مٌ عَلَيْكُمْ لَا نَ[q:10194[بْ]تَغِى [h:10195[ٱ]لْجَ[n[ـٰ]هِل[p[ِي]نَ","Қачонки беҳуда нарса эшитсалар, ундан юз ўгириб: «Бизга ўз амалларимиз, сизга ўз амалларингиз, омон бўлинглар, биз жоҳилларни истамасмиз», дедилар.",392,20],["إِ[g[نّ]َكَ لَا تَهْدِى مَنْ أَحْبَ[q:10196[بْ]تَ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ يَهْدِى م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَهُوَ أَعْلَمُ بِ[h:4362[ٱ]لْمُهْتَد[p[ِي]نَ","Албатта, сен ўзинг севган кишингни ҳидоят қила олмассан. Лекин Аллоҳ кимни хоҳласа, ўшани ҳидоят қилур. У ҳидоятга юрувчиларни яхши билгувчи зотдир.",392,20],["وَقَال[o[ُوٓ][s[اْ] إ[a:10197[ِن ن]َّتَّبِعِ [h:10198[ٱ]لْهُدَىٰ مَعَكَ نُتَخَطَّفْ مِنْ أَرْضِن[o[َآ‌ۚ] أَوَلَمْ نُمَكّ[u:10199[ِن ل]َّهُمْ حَرَمًا ءَامِ[a:10200[نًا ي]ُ[q:10201[جْ]بَ[o[ىٰٓ] إِلَيْهِ ثَمَر[n[َٲ]تُ كُلِّ ش[u:10202[َىْءٍ ر]ِّزْ[a:10203[قًا م]ّ[u:2897[ِن ل]َّدُ[g[نّ]َا وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَعْلَم[p[ُو]نَ","Улар: «Агар сен билан ҳидоятга эргашсак, ўз еримиздан юлиб олинамиз», дедилар. Биз уларга омонлик ҳарамини макон қилиб бермадикми?! У ерга ҳар нарсанинг мевалари Бизнинг даргоҳимиздан ризқ ўлароқ йиғилади-ку! Аммо кўплари билмаслар.",392,20],["وَكَمْ أَهْلَكْنَا مِ[f:4585[ن ق]َرْيَ[i:10204[ةِۭ ب]َطِرَتْ مَعِيشَتَهَا‌ۖ فَتِلْكَ مَسَ[n[ـٰ]كِنُهُمْ لَمْ تُسْك[a:10205[َن م]ّ[i:1453[ِنۢ ب]َعْدِهِمْ إِلَّا قَلِيل[a:10206[اً‌ۖ و]َكُ[g[نّ]َا نَحْنُ [h:10207[ٱ]لْو[n[َٲ]رِث[p[ِي]نَ","Биз маишатлари ҳаддан ошган қанчадан-қанча юртларни ҳалок қилдик. Бас, анавилар, уларнинг масканлари, улардан кейин маскан қилинмади, илло, озгинаси, холос. Ва Биз ўзимиз ворис бўлиб қолдик.",392,20],["وَمَا كَانَ رَبُّكَ مُهْلِكَ [h:4425[ٱ]لْقُرَىٰ حَتَّىٰ يَ[q:4140[بْ]عَثَ ف[o[ِىٓ] أُ[g[مّ]ِهَا رَسُول[a:10208[اً ي]َتْلُو[s[اْ] عَلَيْهِمْ ءَايَ[n[ـٰ]تِنَا‌ۚ وَمَا كُ[g[نّ]َا مُهْلِكِى [h:10209[ٱ]لْقُرَ[o[ىٰٓ] إِلَّا وَأَهْلُهَا ظَ[n[ـٰ]لِم[p[ُو]نَ","Роббинг шаҳар-қишлоқларни то улар орасига уларга оятларимизни тиловат қиладиган Пайғамбар юбормасдан туриб ҳалок қилувчи бўлмаган. Биз шаҳар-қишлоқларни фақат аҳли золим бўлган ҳолдагина ҳалок қилгувчи бўлганмиз.",392,20],["وَم[o[َآ] أُوتِيت[w:10210[ُم م]ِّ[f:2103[ن ش][f:10211[َىْءٍ ف]َمَتَ[n[ـٰ]عُ [h:10212[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا وَزِينَتُهَا‌ۚ وَمَا عِ[f:264[ند]َ [h:408[ٱ]للَّهِ خَيْ[a:8546[رٌ و]َأَ[q:8540[بْ]قَ[o[ىٰٓ‌ۚ] أَفَلَا تَعْقِل[p[ُو]نَ","Ва сизга берилган нарсалар бу дунёнинг матоҳи ва зийнати, холос. Аллоҳнинг ҳузуридаги нарса яхшироқ ва боқийдир. Ақл ишлатмайсизларми?",393,20],["أَفَم[a:10213[َن و]َعَ[q:10214[دْ]نَ[n[ـٰ]هُ وَعْدًا حَسَ[f:7506[نًا ف]َهُوَ لَ[n[ـٰ]قِيهِ كَم[a:10215[َن م]َّتَّعْنَ[n[ـٰ]هُ مَتَ[n[ـٰ]عَ [h:6006[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا ثُ[g[مّ]َ هُوَ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ مِنَ [h:10216[ٱ]لْمُحْضَر[p[ِي]نَ","Биз унга гўзал ваъда қилган, кейин ўшанга эришувчи киши бу ҳаёти дунё матоҳини берганимиздан сўнгра қиёмат куни ҳозир қилинганлардан бўлган киши каби бўлармиди?!",393,20],["وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَك[o[َا]ٓءِىَ [h:7378[ٱ]لَّذِينَ كُ[f:100[نت]ُمْ تَزْعُم[p[ُو]نَ","У зот уларни чақирган кунида: «Сиз даъво қилган Менинг «шерик»ларим қани?!» дейдир.",393,20],["قَالَ [h:590[ٱ]لَّذِينَ حَقَّ عَلَيْهِمُ [h:10217[ٱ]لْقَوْلُ رَبَّنَا هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ [h:6282[ٱ]لَّذِينَ أَغْوَيْن[o[َآ] أَغْوَيْنَ[n[ـٰ]هُمْ كَمَا غَوَيْنَا‌ۖ تَبَرَّأْن[o[َآ] إِلَيْكَ‌ۖ مَا كَان[o[ُوٓ][s[اْ] إِيَّانَا يَعْبُد[p[ُو]نَ","Устиларига сўз тушиши ҳақ бўлганлар: «Эй Роббимиз, анави йўлдан оздирганларимизни ўзимиз йўлдан озганимиздек оздирганмиз. Сенга ўзимизни оқладик. Улар бизга ибодат қилган эмаслар», дерлар.",393,20],["وَقِيلَ [h:10218[ٱ][q:4751[دْ]عُو[s[اْ] شُرَك[o[َا]ٓءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُو[s[اْ] لَهُمْ وَرَأَوُ[s[اْ] [h:864[ٱ]لْعَذَابَ‌ۚ لَوْ أَ[g[نّ]َهُمْ كَانُو[s[اْ] يَهْتَد[p[ُو]نَ","Ва: «Менинг «шерик»ларимни чақиринглар», дейилур. Улар чақирадрлар. Бас, уларга жавоб бермаслар. Ва, азобни кўрурлар. Кошки, ҳидоят топган бўлганларида эди!",393,20],["وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ مَاذ[o[َآ] أَجَ[q:10219[بْ]تُمُ [h:10220[ٱ]لْمُرْسَل[p[ِي]نَ","У кунда, У зот уларга нидо қилиб: «Пайғамбарларга нима деб жавоб бердингиз», дер.",393,20],["فَعَمِيَتْ عَلَيْهِمُ [h:10221[ٱ]لْأَ[i:10222[نۢب][o[َا]ٓءُ يَوْمَئِ[f:10223[ذٍ ف]َهُمْ لَا يَتَس[o[َا]ٓءَل[p[ُو]نَ","Ана ўша кунда хабарлар улардан махфий бўлур ва улар бир-бирларидан сўрай олмаслар ҳам.",393,20],["فَأَ[g[مّ]َا مَ[f:8374[ن ت]َابَ وَءَامَنَ وَعَمِلَ صَ[n[ـٰ]لِ[f:10224[حًا ف]َعَسَ[o[ىٰٓ] أ[a:3312[َن ي]َكُونَ مِنَ [h:10225[ٱ]لْمُفْلِح[p[ِي]نَ","Аммо тавба қилганлар, иймон келтириб, солиҳ амалларни қилган кишилар шоядки нажот топгувчилардан бўлсалар.",393,20],["وَرَبُّكَ يَخْلُقُ مَا يَش[o[َا]ٓءُ وَيَخْتَارُ‌ۗ مَا كَانَ لَهُمُ [h:10226[ٱ]لْخِيَرَةُ‌ۚ سُ[q:7648[بْ]حَ[n[ـٰ]نَ [h:9282[ٱ]للَّهِ وَتَعَ[n[ـٰ]لَىٰ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","Ва Роббинг хоҳлаганини яратиб, хоҳлаганини ихтиёр қилур. Уларда ихтиёр ҳаққи йўқдир. Улар ширк келтираётган нарсалардан Аллоҳ пок ва юксакдир.",393,20],["وَرَبُّكَ يَعْلَمُ مَا تُكِ[g[نّ]ُ صُدُورُهُمْ وَمَا يُعْلِن[p[ُو]نَ","Ва Роббинг уларнинг қалблари яшираётган нарсаларни ҳам, ошкор қилаётган нарсаларни ҳам билур.",393,20],["وَهُوَ [h:3921[ٱ]للَّهُ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۖ لَهُ [h:10227[ٱ]لْحَمْدُ فِى [h:10228[ٱ]لْأُولَىٰ وَ[h:1213[ٱ]لْأَخِرَةِ‌ۖ وَلَهُ [h:10229[ٱ]لْحُكْمُ وَإِلَيْهِ تُرْجَع[p[ُو]نَ","У Аллоҳ, Ундан бошқа ибодатга сазовор илоҳ йўқ зотдир. Бу дунёда ва охиратда барча ҳамд Унгадир. Ҳукм ҳам Унинг Ўзигадир ва Унгагина қайтарилурсизлар.",393,20],["قُلْ أَرَءَيْتُمْ إِ[f:10230[ن ج]َعَلَ [h:2556[ٱ]للَّهُ عَلَيْكُمُ [h:10231[ٱ]لَّيْلَ سَرْمَدًا إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ مَنْ إِلَ[n[ـٰ]هٌ غَيْرُ [h:4057[ٱ]للَّهِ يَأْتِيك[c:10232[ُم ب]ِضِي[o[َا]ٓءٍ‌ۖ أَفَلَا تَسْمَع[p[ُو]نَ","Сен уларга: «Айтинг-чи, агар Аллоҳ кечани қиёмат кунигача доимий қилиб қўйса, Аллоҳдан ўзга қайси илоҳ сизга ёруғлик келтира олур? Эшитмайсизларми?!» деб айт.",394,20],["قُلْ أَرَءَيْتُمْ إِ[f:10230[ن ج]َعَلَ [h:2556[ٱ]للَّهُ عَلَيْكُمُ [h:10233[ٱ][l[ل][g[نّ]َهَارَ سَرْمَدًا إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ مَنْ إِلَ[n[ـٰ]هٌ غَيْرُ [h:4057[ٱ]للَّهِ يَأْتِيك[c:10234[ُم ب]ِلَيْ[f:10235[لٍ ت]َسْكُنُونَ فِيهِ‌ۖ أَفَلَا تُ[q:8674[بْ]صِر[p[ُو]نَ","Сен уларга: «Айтинг-чи, агар Аллоҳ кундузни қиёмат кунигача доимий қилиб қўйса, Аллоҳдан ўзга қайси илоҳ сизларга ором оладиганингиз кечани келтира олади?! Кўрмайсизларми?!» деб айт.",394,20],["وَم[u:10236[ِن ر]َّحْمَتِه[n[ِۦ] جَعَلَ لَكُمُ [h:6116[ٱ]لَّيْلَ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ لِتَسْكُنُو[s[اْ] فِيهِ وَلِتَ[q:7353[بْ]تَغُو[s[اْ] مِ[f:475[ن ف]َضْلِه[n[ِۦ] وَلَعَلَّكُمْ تَشْكُر[p[ُو]نَ","У зот Ўз раҳмати ила сизларга кеча ва кундузни ором олишингиз ва ўз фазлидан талаб қилишингиз учун пайдо қилди. Шоядки шукр келтирсангиз.",394,20],["وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَك[o[َا]ٓءِىَ [h:7378[ٱ]لَّذِينَ كُ[f:100[نت]ُمْ تَزْعُم[p[ُو]نَ","У кунда, У зот уларга нидо қилиб: «Сизлар даъво қилган «шерик»ларим қани?» дейдир.",394,20],["وَنَزَعْنَا مِ[f:843[ن ك]ُلِّ أُ[g[مّ]َ[f:7537[ةٍ ش]َهِي[f:10237[دًا ف]َقُلْنَا هَاتُو[s[اْ] بُرْهَ[n[ـٰ]نَكُمْ فَعَلِم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:10238[ٱ]لْحَقَّ لِلَّهِ وَضَلَّ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَفْتَر[p[ُو]نَ","Ва ҳар бир умматдан бир шоҳид чиқариб: «Ҳужжатларингизни келтиринг!» дегаймиз. Бас, улар ҳақ Аллоҳга эканини билурлар ва ўзлари уйдириб юрган нарсалари ғойиб бўлур.",394,20],["۞ إِ[g[نّ]َ قَ[n[ـٰ]رُونَ كَانَ مِ[f:4913[ن ق]َوْمِ مُوسَىٰ فَبَغَىٰ عَلَيْهِمْ‌ۖ وَءَاتَيْنَ[n[ـٰ]هُ مِنَ [h:10239[ٱ]لْكُنُوزِ م[o[َآ] إِ[g[نّ]َ مَفَاتِحَهُ[n[ۥ] لَتَن[o[ُو]ٓأُ بِ[h:10240[ٱ]لْعُصْبَةِ أُ[s[وْ]لِى [h:10241[ٱ]لْقُوَّةِ إِذْ قَالَ لَهُ[n[ۥ] قَوْمُهُ[n[ۥ] لَا تَفْرَحْ‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُحِبُّ [h:10242[ٱ]لْفَرِح[p[ِي]نَ","Албатта, Қорун Мусо қавмидан бўлиб, уларга такаббурлик қилди. Биз унга калитлари бир гуруҳ қувватлиларга ҳам оғирлик қиладиган хазиналарни берган эдик. Ўшанда қавми унга: «Ҳовлиқма, албатта, Аллоҳ ҳовлиққанларни суймас.",394,20],["وَ[h:9999[ٱ][q:7937[بْ]تَغِ فِيم[o[َآ] ءَاتَ[n[ـٰ]كَ [h:10243[ٱ]للَّهُ [h:10244[ٱ][l[ل]دَّارَ [h:10245[ٱ]لْأَخِرَةَ‌ۖ وَلَا تَ[f:10246[نس]َ نَصِيبَكَ مِنَ [h:10247[ٱ][l[ل]دُّنْيَا‌ۖ وَأَحْسِ[f:10248[ن ك]َم[o[َآ] أَحْسَنَ [h:10249[ٱ]للَّهُ إِلَيْكَ‌ۖ وَلَا تَ[q:10250[بْ]غِ [h:10251[ٱ]لْفَسَادَ فِى [h:44[ٱ]لْأَرْضِ‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُحِبُّ [h:3677[ٱ]لْمُفْسِد[p[ِي]نَ","Ва Аллоҳ сенга берган нарса билан охиратни излагин, бу дунёдаги насибангни ҳам унутма. Аллоҳ сенга яхшилик қилганидек, сен ҳам яхшилик қил. Ер юзида бузғунчиликни излама. Албатта, Аллоҳ бузғунчиларни суймас», дедилар.",394,20],["قَالَ إِ[g[نّ]َم[o[َآ] أُوتِيتُهُ[n[ۥ] عَلَىٰ عِلْمٍ عِ[f:4065[ند][o[ِىٓ‌ۚ] أَوَلَمْ يَعْلَمْ أَ[g[نّ]َ [h:394[ٱ]للَّهَ قَ[q:298[دْ] أَهْلَكَ مِ[f:1097[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] مِنَ [h:6524[ٱ]لْقُرُونِ مَنْ هُوَ أَشَدُّ مِنْهُ قُوَّ[a:10252[ةً و]َأَكْثَرُ جَمْ[a:10253[عًا‌ۚ و]َلَا يُسْــَٔلُ عَ[f:10254[ن ذ]ُنُوبِهِمُ [h:10255[ٱ]لْمُ[q:5255[جْ]رِم[p[ُو]نَ","У: «Менга у фақат ўзимдаги илм туфайлигина берилгандир», деди. У, албатта, Аллоҳ ундан олдинги асрларда ундан кўра қувватлироқ, ундан кўра кўпроқ тўплаганларни ҳалок этганини билмасмиди?! Гуноҳкорлардан гуноҳлари ҳақида сўраб ўтирилмас.",395,20],["فَخَرَجَ عَلَىٰ قَوْمِه[n[ِۦ] فِى زِينَتِه[n[ِۦ]‌ۖ قَالَ [h:590[ٱ]لَّذِينَ يُرِيدُونَ [h:10256[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَا يَ[n[ـٰ]لَيْتَ لَنَا مِثْلَ م[o[َآ] أُوتِىَ قَ[n[ـٰ]رُونُ إِ[g[نّ]َهُ[n[ۥ] لَذُو حَظٍّ عَظ[p[ِي]مٍ","Бас, у қавми ҳузурига зебу зийнати ила чиқди. Ҳаёти дунёни хоҳлайдиганлар: «Қани энди бизга ҳам Қорунга берилган нарсадан бўлса эди. Ҳақиқатда у улуғ насиба эгасидир», дедилар.",395,20],["وَقَالَ [h:614[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:7379[ٱ]لْعِلْمَ وَيْلَكُمْ ثَوَابُ [h:10257[ٱ]للَّهِ خَيْ[u:10258[رٌ ل]ِّمَنْ ءَامَنَ وَعَمِلَ صَ[n[ـٰ]لِ[a:8256[حًا و]َلَا يُلَقَّ[n[ـٰ]ه[o[َآ] إِلَّا [h:10259[ٱ][l[ل]صَّ[n[ـٰ]بِر[p[ُو]نَ","Илм берилганлар эса: «Вой бўлсин сизларга! Иймон келтириб, солиҳ амалларни қилганлар учун Аллоҳнинг савоби яхшидир. Унга фақат сабр қилганларгина эришурлар», дедилар.",395,20],["فَخَسَفْنَا بِه[n[ِۦ] وَبِدَارِهِ [h:10260[ٱ]لْأَرْضَ فَمَا كَانَ لَهُ[n[ۥ] مِ[f:1423[ن ف]ِئَ[a:10261[ةٍ ي]َ[f:8090[نص]ُرُونَهُ[n[ۥ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَمَا كَانَ مِنَ [h:10262[ٱ]لْمُ[f:10263[نت]َصِر[p[ِي]نَ","Бас, Биз уни ва унинг ҳовли-жойини ерга ютдирдик. Унга Аллоҳ дан ёрдам берадиган гуруҳ ҳам бўлмади, унинг ўзи нусратга эришгувчилардан ҳам бўлмади.",395,20],["وَأَصْبَحَ [h:10264[ٱ]لَّذِينَ تَمَ[g[نّ]َوْ[s[اْ] مَكَانَهُ[n[ۥ] بِ[h:6017[ٱ]لْأَمْسِ يَقُولُونَ وَيْكَأَ[g[نّ]َ [h:10265[ٱ]للَّهَ يَ[q:6968[بْ]سُطُ [h:6969[ٱ][l[ل]رِّزْقَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[n[ِۦ] وَيَ[q:6970[قْ]دِرُ‌ۖ لَوْل[o[َآ] أ[a:10266[َن م]َّ[g[نّ]َ [h:2390[ٱ]للَّهُ عَلَيْنَا لَخَسَفَ بِنَا‌ۖ وَيْكَأَ[g[نّ]َهُ[n[ۥ] لَا يُفْلِحُ [h:9313[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Ва кечагина унинг маконини орзу қилаётганлар: «Воажаб, Аллоҳ бандаларидан Ўзи хоҳлаганларига ризқини кенг ёки тор қиладиганга ўхшайдир. Агар Аллоҳ бизга лутф қилмаганида, бизни ҳам ерга ютгизар эди. Воажаб, кофирлар нажот топмайдиганга ўхшайди-ку!» дейишга ўтдилар.",395,20],["تِلْكَ [h:10267[ٱ][l[ل]دَّارُ [h:491[ٱ]لْأَخِرَةُ نَ[q:10268[جْ]عَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُو[f:10269[ًّا ف]ِى [h:44[ٱ]لْأَرْضِ وَلَا فَسَا[a:10270[دًا‌ۚ و]َ[h:4941[ٱ]لْعَ[n[ـٰ]قِبَةُ لِلْمُتَّق[p[ِي]نَ","Ўша охират диёрини Биз ер юзида такаббурлик ва бузғунчиликни истамайдиганлар учун қилурмиз. Оқибат тақводорларникидир.",395,20],["مَ[f:4560[ن ج][o[َا]ٓءَ بِ[h:4561[ٱ]لْحَسَنَةِ فَلَهُ[n[ۥ] خَيْ[a:10054[رٌ م]ِّنْهَا‌ۖ وَمَ[f:4562[ن ج][o[َا]ٓءَ بِ[h:4563[ٱ][l[ل]سَّيِّئَةِ فَلَا يُ[q:4564[جْ]زَى [h:10271[ٱ]لَّذِينَ عَمِلُو[s[اْ] [h:5038[ٱ][l[ل]سَّيِّـَٔـاتِ إِلَّا مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Ким бир яхшилик келтирса, унга удан кўра хайрлироқ бор. Ким бир ёмонлик келтирса, ёмонлик қилганлар фақат қилганларига яраша жазоланурлар.",395,20],["إِ[g[نّ]َ [h:10272[ٱ]لَّذِى فَرَضَ عَلَيْكَ [h:8434[ٱ]لْقُرْءَانَ لَر[m[َا]ٓدُّكَ إِلَىٰ مَعَا[f:10273[دٍ‌ۚ ق]ُ[b:8026[ل] رَّبّ[o[ِىٓ] أَعْلَمُ مَ[f:4560[ن ج][o[َا]ٓءَ بِ[h:54[ٱ]لْهُدَىٰ وَمَنْ هُوَ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Сенга Қуръонни фарз қилган зот, албатта, сени қайтар жойга қайтаргувчидир. Сен: «Роббим ҳидоят келтирган шахсни ҳам ва очиқ-ойдин гумроҳликдаги шахсни ҳам яхши билгувчидир», деб айт.",396,20],["وَمَا كُ[f:735[نت]َ تَرْج[o[ُوٓ][s[اْ] أ[a:10274[َن ي]ُلْقَ[o[ىٰٓ] إِلَيْكَ [h:10275[ٱ]لْكِتَ[n[ـٰ]بُ إِلَّا رَحْمَ[a:5993[ةً م]ّ[u:770[ِن ر]َّبِّكَ‌ۖ فَلَا تَكُونَ[g[نّ]َ ظَهِي[u:10276[رًا ل]ِّلْكَ[n[ـٰ]فِر[p[ِي]نَ","Сен ўзингга китоб туширилишидан умидвор ҳам эмас эдинг. Илло, Роббинг раҳмати бўлиб. Бас, ҳаргиз кофирларга ёрдамчи бўлма.",396,20],["وَلَا يَصُدُّ[g[نّ]َكَ عَنْ ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ بَعْدَ إِذْ أُ[f:5767[نز]ِلَتْ إِلَيْكَ‌ۖ وَ[h:9097[ٱ][q:9097[دْ]عُ إِلَىٰ رَبِّكَ‌ۖ وَلَا تَكُونَ[g[نّ]َ مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Ва сени улар ҳаргиз сенга туширилган Аллоҳнинг оятларидан тўсмасинлар. Роббингга даъват қил. Асло мушриклардан бўлма.",396,20],["وَلَا تَ[q:6220[دْ]عُ مَعَ [h:3975[ٱ]للَّهِ إِلَ[n[ـٰ]هًا ءَاخَرَ‌ۘ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۚ كُلُّ شَىْءٍ هَالِكٌ إِلَّا وَ[q:580[جْ]هَهُ[n[ۥ]‌ۚ لَهُ [h:4124[ٱ]لْحُكْمُ وَإِلَيْهِ تُرْجَع[p[ُو]نَ","Аллоҳдан ўзга ҳеч бир илоҳга илтижо қилма. Ундан ўзга ибодатга сазовор зот йўқ. Ундан ўзга ҳар бир нарса ҳалок бўлгувчидир. Ҳукм Унинг Ўзигагинадир ва фақат Унгагина қайтарилурсиз.",396,20]]},{"n":29,"ar":"العَنكَبُوتِ","en":"Al-Ankaboot","uz":"Анкабут","type":"Макка","ayahs":[["ا[m[لٓ][m[مٓ]","Алиф. Лом. Мийм.",396,20],["أَحَسِبَ [h:10277[ٱ][l[ل][g[نّ]َاسُ أ[a:10278[َن ي]ُتْرَك[o[ُوٓ][s[اْ] أ[a:6263[َن ي]َقُول[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا وَهُمْ لَا يُفْتَن[p[ُو]نَ","Одамлар»иймон келтирдик« дейишлари ила имтиҳон қилинмай, тарк этилишларини ўйладиларми?",396,20],["وَلَقَ[q:341[دْ] فَتَ[g[نّ]َا [h:10279[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۖ فَلَيَعْلَمَ[g[نّ]َ [h:10280[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ صَدَقُو[s[اْ] وَلَيَعْلَمَ[g[نّ]َ [h:10281[ٱ]لْكَ[n[ـٰ]ذِب[p[ِي]نَ","Ва, батаҳқиқ, Биз улардан олдингиларни ҳам имтиҳондан ўтказганмиз. Бас, Аллоҳ, албатта, содиқ бўлганларни ҳам билажак, ёлғончиларни ҳам билажак.",396,20],["أَمْ حَسِبَ [h:10282[ٱ]لَّذِينَ يَعْمَلُونَ [h:2655[ٱ][l[ل]سَّيِّـَٔـاتِ أ[a:10283[َن ي]َسْبِقُونَا‌ۚ س[o[َا]ٓءَ مَا يَحْكُم[p[ُو]نَ","Ёки ёмонликларни қиладиганлар Биздан қочиб қутулишни ўйлайдиларми? Қилган ҳукмлари қандай ҳам ёмон-а?!",396,20],["مَ[f:506[ن ك]َانَ يَرْجُو[s[اْ] لِق[o[َا]ٓءَ [h:10284[ٱ]للَّهِ فَإِ[g[نّ]َ أَجَلَ [h:10285[ٱ]للَّهِ لَأَ[a:10286[تٍ‌ۚ و]َهُوَ [h:709[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Ким Аллоҳга рўбарў бўлишдан умидвор бўлса, албатта, Аллоҳ белгилаган вақт келгувчидир. У ўта эшитгувчи ва ўта билгувчидир.",396,20],["وَمَ[f:10287[ن ج]َ[n[ـٰ]هَدَ فَإِ[g[نّ]َمَا يُجَ[n[ـٰ]هِدُ لِنَفْسِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَغَنِىٌّ عَنِ [h:2124[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Ким жиҳод қилса, бас, албатта, ўз фойдаси учун жиҳод қилур. Албатта, Аллоҳ барча оламлардан беҳожатдир.",396,20],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَنُكَفِّرَ[g[نّ]َ عَنْهُمْ سَيِّـَٔـاتِهِمْ وَلَنَ[q:7579[جْ]زِيَ[g[نّ]َهُمْ أَحْسَنَ [h:10288[ٱ]لَّذِى كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Иймон келтириб, яхши амаллар қилганларнинг ёмонликларини, албатта, ўчирурмиз ва уларни қилган амалларининг энг яхшиси ила мукофотлармиз.",397,20],["وَوَصَّيْنَا [h:10289[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ بِو[n[َٲ]لِدَيْهِ حُسْ[a:10290[نًا‌ۖ و]َإِ[f:10291[ن ج]َ[n[ـٰ]هَدَاكَ لِتُشْرِكَ بِى مَا لَيْسَ لَكَ بِه[n[ِۦ] عِلْ[f:10292[مٌ ف]َلَا تُطِعْهُم[o[َآ‌ۚ] إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُك[c:10293[ُم ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Ва инсонга ота-онасига яхшилик қилишни тасвия қилдик. Агар улар сени ўзинг билмаган нарсани Менга ширк келтиришинг учун жиҳод қилсалар, бас, уларга итоат қилма. Қайтишларингиз Менгагинадир. Бас, сизларга қилган нарсаларингиз хабарини берурман.",397,20],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَنُ[q:10294[دْ]خِلَ[g[نّ]َهُمْ فِى [h:10295[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Иймон келтириб, яхши амаллар қилганларни солиҳлар қаторига қўшурмиз.",397,20],["وَمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ م[a:31[َن ي]َقُولُ ءَامَ[g[نّ]َا بِ[h:32[ٱ]للَّهِ فَإِذ[o[َآ] أُوذِىَ فِى [h:714[ٱ]للَّهِ جَعَلَ فِتْنَةَ [h:10296[ٱ][l[ل][g[نّ]َاسِ كَعَذَابِ [h:10297[ٱ]للَّهِ وَلَئِ[f:10298[ن ج][o[َا]ٓءَ نَصْ[a:10299[رٌ م]ّ[u:770[ِن ر]َّبِّكَ لَيَقُولُ[g[نّ]َ إِ[g[نّ]َا كُ[g[نّ]َا مَعَكُمْ‌ۚ أَوَلَيْسَ [h:10300[ٱ]للَّهُ بِأَعْلَمَ بِمَا فِى صُدُورِ [h:10301[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Ва одамлардан, Аллоҳга иймон келтирдик, дейдиган, сўнгра Аллоҳнинг йўлида озорланса, одамларнинг фитнасини Аллоҳнинг азобидек қабул қиладиганлари ҳам бор. Агар Роббинг томонидан нусрат келса, улар, албатта, биз сиз билан бирга эдик, дерлар. Аллоҳ оламларнинг кўксиларидаги нарсаларни ўта билгувчи зот эмасми?!",397,20],["وَلَيَعْلَمَ[g[نّ]َ [h:10302[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَلَيَعْلَمَ[g[نّ]َ [h:10303[ٱ]لْمُنَ[n[ـٰ]فِق[p[ِي]نَ","Албатта, Аллоҳ иймон келтирганларни ҳам яхши билур, мунофиқларни ҳам яхши билур.",397,20],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَرُو[s[اْ] لِلَّذِينَ ءَامَنُو[s[اْ] [h:10304[ٱ]تَّبِعُو[s[اْ] سَبِيلَنَا وَلْنَحْمِلْ خَطَ[n[ـٰ]يَ[n[ـٰ]كُمْ وَمَا ه[c:10305[ُم ب]ِحَ[n[ـٰ]مِلِينَ مِنْ خَطَ[n[ـٰ]يَ[n[ـٰ]ه[w:10306[ُم م]ِّ[f:2103[ن ش]َىْءٍ‌ۖ إِ[g[نّ]َهُمْ لَكَ[n[ـٰ]ذِب[p[ُو]نَ","Ва куфр келтирганлар иймон келтирганларга:»Бизнинг йўлимизга эргашинглар, хатоларингизни биз кўтарайлик«, дерлар. Ҳолбуки, улар аларнинг хатоларидан ҳеч бир нарсани кўтаргувчи эмаслар. Албатта, улар ёлғончилардир.",397,20],["وَلَيَحْمِلُ[g[نّ]َ أَثْقَالَهُمْ وَأَثْقَال[a:10307[اً م]َّعَ أَثْقَالِهِمْ‌ۖ وَلَيُسْــَٔلُ[g[نّ]َ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ عَ[g[مّ]َا كَانُو[s[اْ] يَفْتَر[p[ُو]نَ","Албатта, улар ўз юкларини ҳам, у юклар билан бирга бошқа юкларни ҳам кўтарурлар. Албатта, қиёмат кунида уйдириб юрган нарсалари ҳақида сўралурлар.",397,20],["وَلَقَ[q:341[دْ] أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِه[n[ِۦ] فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَا[f:10308[مًا ف]َأَخَذَهُمُ [h:10309[ٱ][l[ل]طُّوفَانُ وَهُمْ ظَ[n[ـٰ]لِم[p[ُو]نَ","Ва, батаҳқиқ, биз Нуҳни қавмига Пайғамбар этиб юбордик. Бас, у улар ичида эллик йили кам минг йил турди. Сўнгра уларни золим бўлган ҳолларида тўфон олди.",397,20],["فَأَ[f:4779[نج]َيْنَ[n[ـٰ]هُ وَأَصْحَ[n[ـٰ]بَ [h:10310[ٱ][l[ل]سَّفِينَةِ وَجَعَلْنَ[n[ـٰ]ه[o[َآ] ءَايَ[u:8853[ةً ل]ِّلْعَ[n[ـٰ]لَم[p[ِي]نَ","Бас, Биз унга ва кема соҳибларига нажот бердик ва уни оламларга оят-белги қилдик.",398,20],["وَإِ[q:10311[بْ]ر[n[َٲ]هِيمَ إِذْ قَالَ لِقَوْمِهِ [h:10312[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ وَ[h:4181[ٱ]تَّقُوهُ‌ۖ ذ[n[َٲ]لِكُمْ خَيْ[u:263[رٌ ل]َّكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","Ва Иброҳимни. Ўшанда у ўз қавмига: «Аллоҳга ибодат қилинглар ва Унга тақво қилинглар. Бундай қилишингиз, агар билсангиз, сиз учун яхшидир.",398,20],["إِ[g[نّ]َمَا تَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ أَوْثَ[n[ـٰ][a:10313[نًا و]َتَخْلُقُونَ إِفْكًا‌ۚ إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ تَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ لَا يَمْلِكُونَ لَكُمْ رِزْ[f:10314[قًا ف]َ[h:10315[ٱ][q:10315[بْ]تَغُو[s[اْ] عِ[f:264[ند]َ [h:408[ٱ]للَّهِ [h:10316[ٱ][l[ل]رِّزْقَ وَ[h:10317[ٱ]عْبُدُوهُ وَ[h:783[ٱ]شْكُرُو[s[اْ] لَهُ[o[ۥٓ‌ۖ] إِلَيْهِ تُرْجَع[p[ُو]نَ","Албатта, сизлар Аллоҳни қўйиб, бутларга ибодат қилмоқдасиз ва уйдирмалар тўқимоқдасиз, холос. Албатта, Аллоҳдан ўзга ибодат қилаётган нарсаларингиз сизга ризқ беришга молик эмаслар. Ризқни Аллоҳнинг ҳузуридан истанглар. Унга ибодат ва шукр қилинглар. Унгагина қайтарилурсиз», деди.",398,20],["وَإِ[f:10318[ن ت]ُكَذِّبُو[s[اْ] فَقَ[q:563[دْ] كَذَّبَ أُمَ[a:10319[مٌ م]ِّ[f:85[ن ق]َ[q:86[بْ]لِكُمْ‌ۖ وَمَا عَلَى [h:3818[ٱ][l[ل]رَّسُولِ إِلَّا [h:3819[ٱ]لْبَلَ[n[ـٰ]غُ [h:3781[ٱ]لْمُب[p[ِي]نُ","Агар сизлар ёлғончи қилсангиз, бас, сиздан олдинги умматлар ҳам ёлғончи қилганлар. Пайғамбар зиммасида очиқ-ойдин етказишдан бошқа нарса йўқ.",398,20],["أَوَلَمْ يَرَوْ[s[اْ] كَيْفَ يُ[q:10320[بْ]دِئُ [h:10321[ٱ]للَّهُ [h:10322[ٱ]لْخَلْقَ ثُ[g[مّ]َ يُعِيدُهُ[o[ۥٓ‌ۚ] إِ[g[نّ]َ ذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ يَس[p[ِي]رٌ","Аллоҳ махлуқни аввал-бошдан қандай яратишини, сўнгра уни яна қайтаришини кўрмайдиларми?! Албатта, бу Аллоҳ учун осондир.",398,20],["قُلْ سِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَ[h:2257[ٱ][f:2257[نظ]ُرُو[s[اْ] كَيْفَ بَدَأَ [h:10323[ٱ]لْخَلْقَ‌ۚ ثُ[g[مّ]َ [h:6078[ٱ]للَّهُ يُ[f:10324[نش]ِئُ [h:10325[ٱ][l[ل][g[نّ]َشْأَةَ [h:10326[ٱ]لْأَخِرَةَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Сен: «Ер юзида сайр этиб юринглар ва махлуқотларни У зот аввал-бошдан қандай яратганига назар солинглар. Сўнгра Аллоҳ охират ҳаётини пайдо қилур. Албатта, Аллоҳ ҳар бир нарсага қодирдир.",398,20],["يُعَذِّبُ م[a:476[َن ي]َش[o[َا]ٓءُ وَيَرْحَمُ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۖ وَإِلَيْهِ تُ[q:10327[قْ]لَب[p[ُو]نَ","Кимни хоҳласа, азоблайдир, кимни хоҳласа, раҳм қиладир. Унгагина қайтарилурсизлар.",398,20],["وَم[o[َآ] أَ[f:428[نت][c:4435[ُم ب]ِمُعْجِزِينَ فِى [h:44[ٱ]لْأَرْضِ وَلَا فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ‌ۖ وَمَا لَك[w:556[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ م[a:557[ِن و]َلِ[a:558[ىٍّ و]َلَا نَص[p[ِي]رٍ","Сиз на ер юзида ва на кўкда У зотни ожиз қолдиргувчи эмассиз. Сизга Аллоҳдан ўзга дўст ҳам, ёрдамчи ҳам бўлмас», деб айт.",398,20],["وَ[h:9999[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ وَلِق[o[َا]ٓئِه[o[ِۦٓ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يَئِسُو[s[اْ] م[u:10328[ِن ر]َّحْمَتِى وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Аллоҳнинг оятларига ва Унга рўбарў бўлишга куфр келтирганлар, ана ўшалар Менинг раҳматимдан ноумид бўлдилар. Ана ўшаларнинг ўзларига аламли азоб бор.",398,20],["فَمَا كَانَ جَوَابَ قَوْمِه[o[ِۦٓ] إِلّ[o[َآ] أَ[f:2304[ن ق]َالُو[s[اْ] [h:10329[ٱ][q:10330[قْ]تُلُوهُ أَوْ حَرِّقُوهُ فَأَ[f:10331[نج]َ[n[ـٰ]هُ [h:10332[ٱ]للَّهُ مِنَ [h:869[ٱ][l[ل][g[نّ]َارِ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Унинг қавмининг жавоби: «Уни ўлдиринглар ёки ўтда ёқинглар!» дейишларидан бошқа нарса бўлмади. Бас, Аллоҳ уни ўтдан қутқарди. Албатта, бунда иймон келтирадиган қавмлар учун оят-белгилар бордир.",399,20],["وَقَالَ إِ[g[نّ]َمَا [h:10333[ٱ]تَّخَذْت[w:10334[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ أَوْثَ[n[ـٰ][a:10335[نًا م]َّوَدَّةَ بَيْنِكُمْ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۖ ثُ[g[مّ]َ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ يَكْفُرُ بَعْضُك[c:10336[ُم ب]ِبَعْ[a:10337[ضٍ و]َيَلْعَنُ بَعْضُك[c:1697[ُم ب]َعْ[a:10338[ضًا و]َمَأْوَ[n[ٮٰ]كُمُ [h:10339[ٱ][l[ل][g[نّ]َارُ وَمَا لَك[w:556[ُم م]ّ[a:1813[ِن ن]َّ[n[ـٰ]صِر[p[ِي]نَ","У: «Сизлар, албатта, ҳаёти дунёдаги ўзаро маваддатингиз учун Аллоҳни қўйиб, бутларни тутдингиз. Сўнгра қиёмат кунида баъзингиз баъзингизга куфр келтирурсиз ва баъзингиз баъзингизни лаънатларсиз. Ва жойингиз дўзахдир. Ҳамда сизга нусрат бергувчилар бўлмас.",399,20],["۞ فَـَٔـامَنَ لَهُ[n[ۥ] لُو[a:10340[طٌ‌ۘ و]َقَالَ إِ[g[نّ]ِى مُهَاجِرٌ إِلَىٰ رَبّ[o[ِىٓ‌ۖ] إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:1734[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Бас, унга Лут иймон келтирди ва: «Албатта, мен Роббимга ҳижрат қилгувчиман. Албатта, У азиз ва ҳакимдир», деди.",399,20],["وَوَهَ[q:4212[بْ]نَا لَهُ[o[ۥٓ] إِسْحَ[n[ـٰ]قَ وَيَعْقُوبَ وَجَعَلْنَا فِى ذُرِّيَّتِهِ [h:10341[ٱ][l[ل][g[نّ]ُبُوَّةَ وَ[h:10342[ٱ]لْكِتَ[n[ـٰ]بَ وَءَاتَيْنَ[n[ـٰ]هُ أَ[q:10343[جْ]رَهُ[n[ۥ] فِى [h:599[ٱ][l[ل]دُّنْيَا‌ۖ وَإِ[g[نّ]َهُ[n[ۥ] فِى [h:536[ٱ]لْأَخِرَةِ لَمِنَ [h:686[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Биз унга Исҳоқни ва Яқубни бахш этдик ва Пайғамбарлик ҳамда китобни унинг зурриётида бўладиган қилдик. Унга бу дунёда ажрини бердик. Албатта, у охиратда солиҳлардан бўлгай.",399,20],["وَلُوطًا إِذْ قَالَ لِقَوْمِه[o[ِۦٓ] إِ[g[نّ]َكُمْ لَتَأْتُونَ [h:10344[ٱ]لْفَ[n[ـٰ]حِشَةَ مَا سَبَقَك[c:4828[ُم ب]ِهَا مِنْ أَحَ[a:4829[دٍ م]ِّنَ [h:3475[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Ва Лутни. Ўшанда у ўз қавмига: «Албатта, сиз ўзингиздан олдин ўтган оламлардан ҳеч ким қилмаган фоҳиша ишни қилмоқдасиз.",399,20],["أَئِ[g[نّ]َكُمْ لَتَأْتُونَ [h:4830[ٱ][l[ل]رِّجَالَ وَتَ[q:10345[قْ]طَعُونَ [h:10346[ٱ][l[ل]سَّبِيلَ وَتَأْتُونَ فِى نَادِيكُمُ [h:10347[ٱ]لْمُ[f:9107[نك]َرَ‌ۖ فَمَا كَانَ جَوَابَ قَوْمِه[o[ِۦٓ] إِلّ[o[َآ] أَ[f:2304[ن ق]َالُو[s[اْ] [h:10348[ٱ]ئْتِنَا بِعَذَابِ [h:10349[ٱ]للَّهِ إِ[f:4792[ن ك]ُ[f:735[نت]َ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","Сизлар эркакларга яқинлик қилиб, йўлни кесасизми ва тўплантиларингизда мункир иш қилурмисиз?!»деди. Унинг қавмининг жавоби: «Агар ростгўйлардан бўлсанг, бизга Аллоҳнинг азобини келтир», дейишдан бошқа бўлмади.",399,20],["قَالَ رَبِّ [h:9187[ٱ][f:9188[نص]ُرْنِى عَلَى [h:1431[ٱ]لْقَوْمِ [h:10350[ٱ]لْمُفْسِد[p[ِي]نَ","У: «Эй Роббим, менга бузғунчи қавмларга қарши Ўзинг нусрат бер», деди.",399,20],["وَلَ[g[مّ]َا ج[o[َا]ٓءَتْ رُسُلُن[o[َآ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ بِ[h:6414[ٱ]لْبُشْرَىٰ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا مُهْلِك[o[ُوٓ][s[اْ] أَهْلِ هَ[n[ـٰ]ذِهِ [h:2928[ٱ]لْقَرْيَةِ‌ۖ إِ[g[نّ]َ أَهْلَهَا كَانُو[s[اْ] ظَ[n[ـٰ]لِم[p[ِي]نَ","Бизнинг элчиларимиз Иброҳимга хушхабарни келтиришганида: «Албатта, биз ушбу шаҳар аҳлини ҳалок қилгувчидирмиз. Албатта, унинг аҳли зулм қилгувчилардан бўлдилар», дедилар.",400,20],["قَالَ إِ[g[نّ]َ فِيهَا لُو[f:10351[طًا‌ۚ ق]َالُو[s[اْ] نَحْنُ أَعْلَمُ بِمَ[f:10352[ن ف]ِيهَا‌ۖ لَنُنَجِّيَ[g[نّ]َهُ[n[ۥ] وَأَهْلَهُ[o[ۥٓ] إِلَّا [h:4837[ٱ]مْرَأَتَهُ[n[ۥ] كَانَتْ مِنَ [h:4838[ٱ]لْغَ[n[ـٰ]بِر[p[ِي]نَ","У: «Унда Лут бор-ку?!» деди. Улар: «Биз унда ким борлигини яхши биламиз. Биз, албатта, унга ва унинг аҳлига нажот берамиз. Магар унинг хотини ҳалок бўлгувчилардан бўлгандир», дедилар.",400,20],["وَلَ[g[مّ][o[َآ] أَ[f:10353[ن ج][o[َا]ٓءَتْ رُسُلُنَا لُو[f:6430[طًا س][o[ِى]ٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْ[a:10354[عًا و]َقَالُو[s[اْ] لَا تَخَفْ وَلَا تَحْزَنْ‌ۖ إِ[g[نّ]َا مُنَجُّوكَ وَأَهْلَكَ إِلَّا [h:6440[ٱ]مْرَأَتَكَ كَانَتْ مِنَ [h:4838[ٱ]لْغَ[n[ـٰ]بِر[p[ِي]نَ","Элчиларимиз Лутга келишганида, у улар сабабли маҳзун бўлди ва келишларидан юраги сиқилди. Улар: «Сен хавфсирама ва маҳзун ҳам бўлма, албатта, биз сени ва аҳлингни қутқаргувчилармиз. Магар хотининг ҳалок бўлгувчилардан бўлгандир.",400,20],["إِ[g[نّ]َا مُ[f:10355[نز]ِلُونَ عَلَ[o[ىٰٓ] أَهْلِ هَ[n[ـٰ]ذِهِ [h:2928[ٱ]لْقَرْيَةِ رِ[q:290[جْ][a:291[زًا م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ بِمَا كَانُو[s[اْ] يَفْسُق[p[ُو]نَ","Албатта, Биз ушбу шаҳар аҳолиси бошига фосиқлик қилганлари туфайли осмондан азоб туширгувчимиз», дедилар.",400,20],["وَلَقَ[d:10356[د] تَّرَكْنَا مِنْه[o[َآ] ءَايَ[i:10357[ةَۢ ب]َيِّنَ[u:10358[ةً ل]ِّقَوْ[a:850[مٍ ي]َعْقِل[p[ُو]نَ","Батаҳқиқ, Биз ундан ақл юритгувчи қавмлар учун очиқ-ойдин оят-белгилар қолдирганмиз.",400,20],["وَإِلَىٰ مَ[q:4842[دْ]يَنَ أَخَاهُمْ شُعَيْ[f:10359[بًا ف]َقَالَ يَ[n[ـٰ]قَوْمِ [h:4768[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ وَ[h:10360[ٱ]رْجُو[s[اْ] [h:10361[ٱ]لْيَوْمَ [h:10362[ٱ]لْأَخِرَ وَلَا تَعْثَوْ[s[اْ] فِى [h:44[ٱ]لْأَرْضِ مُفْسِد[p[ِي]نَ","Ва Мадянга биродарлари Шуайбни. Бас, у: «Эй қавмим, Аллоҳга ибодат қилинг, охират кунидан умидвор бўлинг ва ер юзида бузғунчилик ила харакат қилиб юрманг», деди.",400,20],["فَكَذَّبُوهُ فَأَخَذَتْهُمُ [h:4823[ٱ][l[ل]رَّ[q:4824[جْ]فَةُ فَأَصْبَحُو[s[اْ] فِى دَارِهِمْ جَ[n[ـٰ]ثِم[p[ِي]نَ","Бас, уни ёлғончига чиқардилар. Шунда уларни бир силкиниш тутди ва диёрларида чўккалаб қолдилар.",400,20],["وَعَا[a:9638[دًا و]َثَمُودَ[s[اْ] وَقَ[d:10363[د] تَّبَيَّنَ لَك[w:556[ُم م]ّ[a:10364[ِن م]َّسَ[n[ـٰ]كِنِهِمْ‌ۖ وَزَيَّنَ لَهُمُ [h:4046[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ أَعْمَ[n[ـٰ]لَهُمْ فَصَدَّهُمْ عَنِ [h:6998[ٱ][l[ل]سَّبِيلِ وَكَانُو[s[اْ] مُسْتَ[q:10365[بْ]صِر[p[ِي]نَ","Ва Од ва Самудни. Батаҳқиқ, бу сизга уларнинг масканларидан аён бўлиб турибди. Шайтон уларга амалларини зийнатлаб кўрсатиб, уларни йўлдан тўсди. Ҳолбуки, улар кўриб-билиб тургувчи эдилар.",400,20],["وَقَ[n[ـٰ]رُونَ وَفِرْعَوْنَ وَهَ[n[ـٰ]مَ[n[ـٰ]نَ‌ۖ وَلَقَ[q:341[دْ] ج[o[َا]ٓءَه[w:10161[ُم م]ُّوسَىٰ بِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ فَ[h:4956[ٱ]سْتَكْبَرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ وَمَا كَانُو[s[اْ] سَ[n[ـٰ]بِق[p[ِي]نَ","Қорун, Фиръавн ва Ҳомонларни. Батаҳқиқ, Мусо уларга очиқ-ойдин ҳужжатлар келтирди. Бас, улар ер юзида мутакаббирлик қилдилар ва қочиб қутулгувчи бўлмадилар.",401,20],["فَكُلاًّ أَخَذْنَا بِذَ[i:10366[نۢب]ِه[n[ِۦ]‌ۖ فَمِنْه[w:1456[ُم م]َّنْ أَرْسَلْنَا عَلَيْهِ حَاصِ[a:10367[بًا و]َمِنْه[w:1106[ُم م]َّنْ أَخَذَتْهُ [h:10368[ٱ][l[ل]صَّيْحَةُ وَمِنْه[w:1106[ُم م]َّنْ خَسَفْنَا بِهِ [h:842[ٱ]لْأَرْضَ وَمِنْه[w:1106[ُم م]َّنْ أَغْرَ[q:9772[قْ]نَا‌ۚ وَمَا كَانَ [h:742[ٱ]للَّهُ لِيَظْلِمَهُمْ وَلَ[n[ـٰ]كِ[f:276[ن ك]َان[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ يَظْلِم[p[ُو]نَ","Улардан ҳар бирини гуноҳи туфайли тутдик. Бас, улардан баъзилари устига тош ёғдирдик, баъзиларини қичқириқ ушлади, баъзиларини ерга ютдирдик ва баъзиларини ғарқ қилдик. Аллоҳ уларга зулм этгувчи бўлмади, лекин улар ўзларига зулм этдилар.",401,20],["مَثَلُ [h:1179[ٱ]لَّذِينَ [h:3645[ٱ]تَّخَذُو[s[اْ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ أَوْلِي[o[َا]ٓءَ كَمَثَلِ [h:10369[ٱ]لْعَ[f:10370[نك]َبُوتِ [h:10371[ٱ]تَّخَذَتْ بَيْ[a:10372[تًا‌ۖ و]َإِ[g[نّ]َ أَوْهَنَ [h:10373[ٱ]لْبُيُوتِ لَبَيْتُ [h:10374[ٱ]لْعَ[f:10370[نك]َبُوتِ‌ۖ لَوْ كَانُو[s[اْ] يَعْلَم[p[ُو]نَ","Аллоҳни қўйиб, ўзга дўстлар тутганларнинг мисоли ўзига уй тутган ўргимчакка ўхшайди. Ҳолбуки, энг заиф уй ўргимчакнинг уясидир. Кошки билсалар эди.",401,20],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَعْلَمُ مَا يَ[q:1240[دْ]عُونَ مِ[f:3136[ن د]ُونِه[n[ِۦ] مِ[f:2103[ن ش][a:4300[َىْءٍ‌ۚ و]َهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Албатта, Аллоҳ улар ўзидан бошқа нима нарсага дуо қилаётганларини яхши биладир. Ва У азиз ва ҳаким зотдир.",401,20],["وَتِلْكَ [h:10375[ٱ]لْأَمْثَ[n[ـٰ]لُ نَضْرِبُهَا لِل[g[نّ]َاسِ‌ۖ وَمَا يَعْقِلُه[o[َآ] إِلَّا [h:10376[ٱ]لْعَ[n[ـٰ]لِم[p[ُو]نَ","Ушбу мисолларни Биз одамлар учун келтирурмиз. Лекин уларга олимлардан ўзгаларнинг ақллари етмас.",401,20],["خَلَقَ [h:1272[ٱ]للَّهُ [h:10377[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ بِ[h:370[ٱ]لْحَقِّ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:7291[ةً ل]ِّلْمُؤْمِن[p[ِي]نَ","Аллоҳ осмонлар ва ерни ҳақ ила яратгандир. Албатта, бунда мўминлар учун оят-белги бордир.",401,20],["ٱتْلُ م[o[َآ] أُوحِىَ إِلَيْكَ مِنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ وَأَقِمِ [h:6518[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ‌ۖ إِ[g[نّ]َ [h:3096[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ تَنْهَىٰ عَنِ [h:7553[ٱ]لْفَحْش[o[َا]ٓءِ وَ[h:7554[ٱ]لْمُ[f:7554[نك]َرِ‌ۗ وَلَذِكْرُ [h:10378[ٱ]للَّهِ أَكْبَرُ‌ۗ وَ[h:72[ٱ]للَّهُ يَعْلَمُ مَا تَصْنَع[p[ُو]نَ","Сенга китобдан ваҳий қилинган нарсани тиловат қил ва намозни тўкис адо эт, албатта, намоз фоҳиша ва мункар ишлардан қайтарур. Албатта, Аллоҳнинг зикри буюк ишдир. Аллоҳ нима қилсангиз, билур.",401,20],["۞ وَلَا تُجَ[n[ـٰ]دِل[o[ُوٓ][s[اْ] أَهْلَ [h:3678[ٱ]لْكِتَ[n[ـٰ]بِ إِلَّا بِ[h:4526[ٱ]لَّتِى هِىَ أَحْسَنُ إِلَّا [h:778[ٱ]لَّذِينَ ظَلَمُو[s[اْ] مِنْهُمْ‌ۖ وَقُول[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا بِ[h:315[ٱ]لَّذ[o[ِىٓ] أُ[f:17[نز]ِلَ إِلَيْنَا وَأُ[f:10379[نز]ِلَ إِلَيْكُمْ وَإِلَ[n[ـٰ]هُنَا وَإِلَ[n[ـٰ]هُكُمْ و[n[َٲ]حِ[a:10380[دٌ و]َنَحْنُ لَهُ[n[ۥ] مُسْلِم[p[ُو]نَ","Сизлар аҳли китобларнинг зулм қилганларидан бошқалари билан фақат яхши услубда мужодала этинглар ва уларга: «Биз ўзимизга нозил қилинган ва сизга нозил қилинган нарсага иймон келтирдик, бизнинг илоҳимиз ва сизнинг илоҳингиз бирдир ва биз унга бўйсунгувчимиз», денглар.",402,21],["وَكَذ[n[َٲ]لِكَ أَ[f:515[نز]َلْن[o[َآ] إِلَيْكَ [h:3102[ٱ]لْكِتَ[n[ـٰ]بَ‌ۚ فَ[h:2514[ٱ]لَّذِينَ ءَاتَيْنَ[n[ـٰ]هُمُ [h:635[ٱ]لْكِتَ[n[ـٰ]بَ يُؤْمِنُونَ بِه[n[ِۦ]‌ۖ وَمِنْ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ م[a:5799[َن ي]ُؤْمِنُ بِه[n[ِۦ]‌ۚ وَمَا يَ[q:10381[جْ]حَدُ بِـَٔـايَ[n[ـٰ]تِن[o[َآ] إِلَّا [h:10382[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Ана шундай қилиб, сенга ҳам китоб нозил қилдик. Бас, Биз уларга китоб берган кимсалар унга иймон келтирурлар. Анавилардан ҳам унга иймон келтирадиганлари бор. Бизнинг оятларимизни фақат кофирларгина инкор этурлар.",402,21],["وَمَا كُ[f:735[نت]َ تَتْلُو[s[اْ] مِ[f:1097[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] مِ[f:2060[ن ك]ِتَ[n[ـٰ][a:10383[بٍ و]َلَا تَخُطُّهُ[n[ۥ] بِيَمِينِكَ‌ۖ إِ[u:10384[ذًا ل]َّ[h:10385[ٱ]رْتَابَ [h:10386[ٱ]لْمُ[q:5131[بْ]طِل[p[ُو]نَ","Ундан олдин ҳеч бир китобни тиловат қилмас эдинг ва қўлинг билан хат ёзмас эдинг. Агар шундай бўлганида, ботил аҳллари шубҳага тушган бўлур эдилар.",402,21],["بَلْ هُوَ ءَايَ[n[ـٰ][i:2117[تُۢ ب]َيِّنَ[n[ـٰ][f:10387[تٌ ف]ِى صُدُورِ [h:10388[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:7379[ٱ]لْعِلْمَ‌ۚ وَمَا يَ[q:10381[جْ]حَدُ بِـَٔـايَ[n[ـٰ]تِن[o[َآ] إِلَّا [h:10389[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Йўқ! У илм берилганлар кўксидаги очиқ-ойдин оятлардир. Бизнинг оятларимизни фақат золимларгина инкор қилур.",402,21],["وَقَالُو[s[اْ] لَوْل[o[َآ] أُ[f:17[نز]ِلَ عَلَيْهِ ءَايَ[n[ـٰ][a:10390[تٌ م]ّ[u:192[ِن ر]َّبِّه[n[ِۦ]‌ۖ قُلْ إِ[g[نّ]َمَا [h:4327[ٱ]لْأَيَ[n[ـٰ]تُ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَإِ[g[نّ]َم[o[َآ] أَنَا۟ نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","Ва улар: «Унга Роббидан мўжизалар нозил қилинса эди», дедилар. Сен:»Мўъжизалар ёлғиз Аллоҳнинг ҳузуридадир. Мен эса, фақат очиқ-ойдин огоҳлантиргувчиман, холос», дегин.",402,21],["أَوَلَمْ يَكْفِهِمْ أَ[g[نّ][o[َآ] أَ[f:515[نز]َلْنَا عَلَيْكَ [h:1723[ٱ]لْكِتَ[n[ـٰ]بَ يُتْلَىٰ عَلَيْهِمْ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَرَحْمَ[a:10391[ةً و]َذِكْرَىٰ لِقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Уларга Бизнинг сенга ўзлари учун тиловат қилинаётган ушбу китобни нозил этганимиз кифоя қилмайдими?! Албатта, бунда иймон келтирадиган қавмлар учун раҳмат ва эслатма бордир.",402,21],["قُلْ كَفَىٰ بِ[h:32[ٱ]للَّهِ بَيْنِى وَبَيْنَكُمْ شَهِي[a:10392[دًا‌ۖ ي]َعْلَمُ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۗ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] بِ[h:212[ٱ]لْبَ[n[ـٰ]طِلِ وَكَفَرُو[s[اْ] بِ[h:32[ٱ]للَّهِ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:150[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","«Мен билан сизнинг орамизда гувоҳликка Аллоҳнинг Ўзи кифоядир. У осмонлару ердаги нарсани билур. Ботилга иймон келтириб, Аллоҳга куфр келтирганлар, ана ўшалар ўзлари зиён кўргувчилардир», деб айт.",402,21],["وَيَسْتَعْجِلُونَكَ بِ[h:9060[ٱ]لْعَذَابِ‌ۚ وَلَوْل[o[َآ] أَجَ[a:4120[لٌ م]ُّسَم[u:10393[ًّى ل]َّج[o[َا]ٓءَهُمُ [h:10394[ٱ]لْعَذَابُ وَلَيَأْتِيَ[g[نّ]َه[c:10395[ُم ب]َغْتَ[a:4880[ةً و]َهُمْ لَا يَشْعُر[p[ُو]نَ","Улар сендан азобни тезлаштиришни талаб қилурлар. Агар белгиланган ажал бўлмаганида, уларга, албатта, азоб келган бўлур эди. Албатта, уларга у тўсатдан, улар сезмаган ҳолда келур.",403,21],["يَسْتَعْجِلُونَكَ بِ[h:9060[ٱ]لْعَذَابِ وَإِ[g[نّ]َ جَهَ[g[نّ]َمَ لَمُحِيطَ[i:5639[ةُۢ ب]ِ[h:74[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Улар сендан азобни тезлаштиришни талаб қилурлар. Ҳолбуки, жаҳаннам ҳеч шубҳасиз кофирларни ўраб тургувчидир.",403,21],["يَوْمَ يَغْشَ[n[ـٰ]هُمُ [h:10396[ٱ]لْعَذَابُ مِ[f:3683[ن ف]َوْقِهِمْ وَمِ[f:3684[ن ت]َحْتِ أَرْجُلِهِمْ وَيَقُولُ ذُوقُو[s[اْ] مَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","У кунда азоб уларни устларидан ва оёқлари остидан ўраб олур ва У зот: «Қилиб юрган амалларингиз тотинг!» деб айтур.",403,21],["يَ[n[ـٰ]عِبَادِىَ [h:10397[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[g[نّ]َ أَرْضِى و[n[َٲ]سِعَ[f:10398[ةٌ ف]َإِيَّ[n[ـٰ]ىَ فَ[h:8713[ٱ]عْبُد[p[ُو]نِ","Эй иймон келтирган бандаларим, албатта, Менинг ерим кенгдир. Бас, Менгагина ибодат қилинглар.",403,21],["كُلُّ نَفْ[f:2476[سٍ ذ][o[َا]ٓئِقَةُ [h:2477[ٱ]لْمَوْتِ‌ۖ ثُ[g[مّ]َ إِلَيْنَا تُرْجَع[p[ُو]نَ","Ҳар бир жон ўлимни топажакдир. Сўнгра Бизгагина қайтарилурсиз.",403,21],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَنُبَوِّئَ[g[نّ]َه[w:10399[ُم م]ِّنَ [h:4643[ٱ]لْجَ[g[نّ]َةِ غُرَ[f:10400[فًا ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۚ نِعْمَ أَ[q:2254[جْ]رُ [h:2255[ٱ]لْعَ[n[ـٰ]مِل[p[ِي]نَ","Иймон келтириб, яхши амалларни қилганларни жаннатдан остидан анҳорлар оқиб турган олимақом жойларга жойлаштирурмиз. У ерда абадий қолурлар. Амал қилгувчиларнинг ажри қандай ҳам яхши!",403,21],["ٱلَّذِينَ صَبَرُو[s[اْ] وَعَلَىٰ رَبِّهِمْ يَتَوَكَّل[p[ُو]نَ","Улар сабр қилган ва Роббиларигагина таваккул қиладиган зотлардир.",403,21],["وَكَأَيّ[a:2298[ِن م]ِّ[f:4026[ن د][m[َا]ٓبَّ[u:10401[ةٍ ل]َّا تَحْمِلُ رِزْقَهَا [h:10402[ٱ]للَّهُ يَرْزُقُهَا وَإِيَّاكُمْ‌ۚ وَهُوَ [h:709[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Ўз ризқини кўтара олмайдиган қанчадан-қанча жонзотлар бор. Уларга ҳам, сизларга ҳам Аллоҳ ризқ берадир. Ва У ўта эшитгувчи ва ўта билгувчи зотдир. Дарҳақиқат, ўйлаб кўрадиган бўлсак, кўпгина жонзотлар ризқга муҳтож бўлганида, уни тановвул қилишдан бошқа нарсани билмайди. Ризқ топиш учун ҳаракат ҳам қилмайди. Ризқни ўзи билан кўтариб ҳам юрмайди. Ўзига ризқ жамғармайди ҳам. Фақат ризқ керак бўлганида, уни тановвул қилади, холос. Аммо ризқ топилмасдан, бирортаси очқаб ўлиб ҳам қолмайди. Ризқини териб еб юраверади. Фақат инсонгина ризқ тўплашни одат қилган. Илоҳий таълимотлардан узоқ бўлган баъзи бир одамлар ҳаётни ризқ-рўз учун курашишдан иборат, деб ўйлайдилар. Улар ўзларича, ризқни ўзимиз топмоқдамиз, деб гумон қиладилар.",403,21],["وَلَئِ[f:5683[ن س]َأَلْتَه[w:10403[ُم م]َّنْ خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَسَخَّرَ [h:6864[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ لَيَقُولُ[g[نّ]َ [h:10404[ٱ]للَّهُ‌ۖ فَأَ[g[نّ]َىٰ يُؤْفَك[p[ُو]نَ","Агар улардан: «Осмонлару ерни ким яратган ва қуёшнию ойни ўз измига қаратган ким?» деб сўрасанг: «Аллоҳ», дерлар. Бас, унда қаёққа бурилмоқдалар?!",403,21],["ٱللَّهُ يَ[q:6968[بْ]سُطُ [h:6969[ٱ][l[ل]رِّزْقَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[n[ِۦ] وَيَ[q:6970[قْ]دِرُ لَهُ[o[ۥٓ‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","Аллоҳ Ўз бандаларидан кимни хоҳласа, ризқини кенг қилиб қўядир ва хоҳлаганиникини тор қиладир. Албатта, Аллоҳ ҳар бир нарсани ўта билгувчи зотдир.",403,21],["وَلَئِ[f:5683[ن س]َأَلْتَه[w:10403[ُم م]ّ[a:10405[َن ن]َّزَّلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:7464[ءً ف]َأَحْيَا بِهِ [h:842[ٱ]لْأَرْضَ م[i:146[ِنۢ ب]َعْدِ مَوْتِهَا لَيَقُولُ[g[نّ]َ [h:10404[ٱ]للَّهُ‌ۚ قُلِ [h:9994[ٱ]لْحَمْدُ لِلَّهِ‌ۚ بَلْ أَكْثَرُهُمْ لَا يَعْقِل[p[ُو]نَ","Агар улардан: «Осмондан сув тушириб, у билан ўлган ерни тирилтирган ким?!» деб сўрасанг, албатта, улар: «Аллоҳ», дерлар. Сен: «Аллоҳга ҳамд бўлсин!» деб айт. Йўқ! Уларнинг кўплари ақл юритмаслар.",403,21],["وَمَا هَ[n[ـٰ]ذِهِ [h:10406[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْي[o[َآ] إِلَّا لَهْ[a:10407[وٌ و]َلَعِ[a:10408[بٌ‌ۚ و]َإِ[g[نّ]َ [h:10409[ٱ][l[ل]دَّارَ [h:10245[ٱ]لْأَخِرَةَ لَهِىَ [h:10410[ٱ]لْحَيَوَانُ‌ۚ لَوْ كَانُو[s[اْ] يَعْلَم[p[ُو]نَ","Бу дунё ҳаёти фақат ўйин-кулгидан иборатдир. Агар билсалар, охират диёри, ана ўша ҳақиқий ҳаётдир.",404,21],["فَإِذَا رَكِبُو[s[اْ] فِى [h:4780[ٱ]لْفُلْكِ دَعَوُ[s[اْ] [h:6002[ٱ]للَّهَ مُخْلِصِينَ لَهُ [h:4649[ٱ][l[ل]دِّينَ فَلَ[g[مّ]َا نَجَّ[n[ـٰ]هُمْ إِلَى [h:7827[ٱ]لْبَرِّ إِذَا هُمْ يُشْرِك[p[ُو]نَ","Улар қачон кемага минсалар, Аллоҳга, Унинг динига ихлос қилган ҳолларида дуо қилурлар. Нажот бериб, уларни қуруқликка чиқарса, баногоҳ ширк келтирурлар.",404,21],["لِيَكْفُرُو[s[اْ] بِم[o[َآ] ءَاتَيْنَ[n[ـٰ]هُمْ وَلِيَتَمَتَّعُو[s[اْ‌ۖ] فَسَوْفَ يَعْلَم[p[ُو]نَ","Улар Биз берган нарсага куфр келтираверсинлар ва ҳузур қилаверсинлар! Бас, тезда билурлар.",404,21],["أَوَلَمْ يَرَوْ[s[اْ] أَ[g[نّ]َا جَعَلْنَا حَرَمًا ءَامِ[a:10411[نًا و]َيُتَخَطَّفُ [h:10412[ٱ][l[ل][g[نّ]َاسُ مِنْ حَوْلِهِمْ‌ۚ أَفَبِ[h:7495[ٱ]لْبَ[n[ـٰ]طِلِ يُؤْمِنُونَ وَبِنِعْمَةِ [h:10413[ٱ]للَّهِ يَكْفُر[p[ُو]نَ","Биз уларга Ҳарамни омонлик жойи қилиб қўйганимизни билмабмидилар?! Ҳолбуки, уларнинг атрофида одамлар талон-тарожга учрамоқдалар. Улар ботилга иймон келтириб, Аллоҳнинг неъматига куфр келтирадиларми?!",404,21],["وَمَنْ أَظْلَمُ مِ[g[مّ]َنِ [h:3980[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِبًا أَوْ كَذَّبَ بِ[h:370[ٱ]لْحَقِّ لَ[g[مّ]َا ج[o[َا]ٓءَهُ[o[ۥٓ‌ۚ] أَلَيْسَ فِى جَهَ[g[نّ]َمَ مَثْ[u:10414[وًى ل]ِّلْكَ[n[ـٰ]فِر[p[ِي]نَ","Аллоҳга нисбатан ёлғон тўқиган ёки ўзига келган ҳақни ёлғонга чиқарган кимсадан ҳам золимроқ одам борми?! Кофирларга жаҳаннамда турар жой йўқмиди?!",404,21],["وَ[h:9999[ٱ]لَّذِينَ جَ[n[ـٰ]هَدُو[s[اْ] فِينَا لَنَهْدِيَ[g[نّ]َهُمْ سُبُلَنَا‌ۚ وَإِ[g[نّ]َ [h:1986[ٱ]للَّهَ لَمَعَ [h:10415[ٱ]لْمُحْسِن[p[ِي]نَ","Бизнинг жиҳод қилганларни Ўз йўлларимизга ҳидоят этурмиз. Албатта, Аллоҳ чиройли амал қилгувчилар биландир.",404,21]]},{"n":30,"ar":"الرُّومِ","en":"Ar-Room","uz":"Рум","type":"Макка","ayahs":[["ا[m[لٓ][m[مٓ]","Алиф. Лам. Мийм.",404,21],["غُلِبَتِ [h:10416[ٱ][l[ل]رّ[p[ُو]مُ","Рум мағлуб бўлди.",404,21],["ف[o[ِىٓ] أَ[q:314[دْ]نَى [h:10417[ٱ]لْأَرْضِ وَه[w:8717[ُم م]ّ[i:146[ِنۢ ب]َعْدِ غَلَبِهِمْ سَيَغْلِب[p[ُو]نَ","Яқин ерда. Ва улар мағлубиятларидан кейин тезда ғолиб бўлажаклар.",404,21],["فِى بِضْعِ سِنِينَ‌ۗ لِلَّهِ [h:10418[ٱ]لْأَمْرُ مِ[f:128[ن ق]َ[q:129[بْ]لُ وَم[i:10419[ِنۢ ب]َعْدُ‌ۚ وَيَوْمَئِ[a:10420[ذٍ ي]َفْرَحُ [h:10421[ٱ]لْمُؤْمِن[p[ُو]نَ","Саноқли йилларда. Ундан олдин ҳам, кейин ҳам барча иш Аллоҳдандир. Ўша кунда мўминлар шодланурлар.",404,21],["بِنَصْرِ [h:10422[ٱ]للَّهِ‌ۚ يَ[f:10423[نص]ُرُ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۖ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Аллоҳнинг нусратидан. У хоҳлаганига нусрат берур. Ва У азизу роҳиймдир.",404,21],["وَعْدَ [h:3149[ٱ]للَّهِ‌ۖ لَا يُخْلِفُ [h:10424[ٱ]للَّهُ وَعْدَهُ[n[ۥ] وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Аллоҳнинг ваъдасидир. Аллоҳ Ўз ваъдасига хилоф қилмас. Лекин одамларнинг кўпи буни билмаслар.",405,21],["يَعْلَمُونَ ظَ[n[ـٰ]هِ[a:10425[رًا م]ِّنَ [h:10426[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا وَهُمْ عَنِ [h:10427[ٱ]لْأَخِرَةِ هُمْ غَ[n[ـٰ]فِل[p[ُو]نَ","Улар бу дунё ҳаётининг зоҳирини билурлар. Ҳолбуки, улар охиратдан ғофилдирлар.",405,21],["أَوَلَمْ يَتَفَكَّرُو[s[اْ] ف[o[ِىٓ] أَ[f:568[نف]ُسِه[w:2346[ِم‌ۗ م]َّا خَلَقَ [h:1272[ٱ]للَّهُ [h:10377[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَمَا بَيْنَهُم[o[َآ] إِلَّا بِ[h:370[ٱ]لْحَقِّ وَأَجَ[a:10428[لٍ م]ُّسَم[a:10429[ًّى‌ۗ و]َإِ[g[نّ]َ كَثِي[a:3614[رًا م]ِّنَ [h:721[ٱ][l[ل][g[نّ]َاسِ بِلِقَآىِٕ رَبِّهِمْ لَكَ[n[ـٰ]فِر[p[ُو]نَ","Ахир, улар Аллоҳ осмонлару ерни ва улар орасидаги нарсаларни фақат ҳақ билан ва маълум муддатга яратганини тафаккур қилиб кўрмайдиларми?! Ҳақиқатда, одамлардан кўплари Роббиларига рўбарў бўлишни инкор қилгувчилардир.",405,21],["أَوَلَمْ يَسِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَيَ[f:6853[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6854[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ كَان[o[ُوٓ][s[اْ] أَشَدَّ مِنْهُمْ قُوَّ[a:10430[ةً و]َأَثَارُو[s[اْ] [h:10431[ٱ]لْأَرْضَ وَعَمَرُوه[o[َآ] أَكْثَرَ مِ[g[مّ]َا عَمَرُوهَا وَج[o[َا]ٓءَتْهُمْ رُسُلُه[c:4900[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ‌ۖ فَمَا كَانَ [h:742[ٱ]للَّهُ لِيَظْلِمَهُمْ وَلَ[n[ـٰ]كِ[f:276[ن ك]َان[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ يَظْلِم[p[ُو]نَ","Ер юзида юриб, ўзларидан олдингиларнинг оқибати қандай бўлганига назар солмайдиларми?! Уларнинг булардан қувватлари кўпроқ эди ва ерга ишлов бериб, уни булар обод қилгандан кўра кўпроқ обод қилган эдилар. Ва уларга Пайғамбарлари очиқ-ойдин лар билан келдилар. Аллоҳ уларга зулм қилмас эди, лекин улар ўзларига зулм қилардилар.",405,21],["ثُ[g[مّ]َ كَانَ عَ[n[ـٰ]قِبَةَ [h:10432[ٱ]لَّذِينَ أَسَ[o[ـٰٓـ]ــُٔو[s[اْ] [h:10433[ٱ][l[ل]سّ[o[ُو]ٓأَ[o[ىٰٓ] أَ[f:10434[ن ك]َذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ وَكَانُو[s[اْ] بِهَا يَسْتَهْزِء[p[ُو]نَ","Сўнгра ёмонлик қилганларнинг оқибати Аллоҳнинг оятларини ёлғонга чиқарганлари ва уларни истеҳзо қилганлари учун ёмон бўлди.",405,21],["ٱللَّهُ يَ[q:5943[بْ]دَؤُ[s[اْ] [h:5944[ٱ]لْخَلْقَ ثُ[g[مّ]َ يُعِيدُهُ[n[ۥ] ثُ[g[مّ]َ إِلَيْهِ تُرْجَع[p[ُو]نَ","Аллоҳ махлуқотни йўқдан бор қилади, сўнгра уни яна қайтадан вужудга келтиради, сўнгра Унга қайтарилурсиз.",405,21],["وَيَوْمَ تَقُومُ [h:10435[ٱ][l[ل]سَّاعَةُ يُ[q:10436[بْ]لِسُ [h:10437[ٱ]لْمُ[q:5255[جْ]رِم[p[ُو]نَ","Қиёмат қоим бўлган кунда жиноятчилар ноумид бўлурлар.",405,21],["وَلَمْ يَك[u:9334[ُن ل]َّه[w:1812[ُم م]ِّ[f:10438[ن ش]ُرَك[o[َا]ٓئِهِمْ شُفَعَ[o[ـٰٓ]ؤُ[s[اْ] وَكَانُو[s[اْ] بِشُرَك[o[َا]ٓئِهِمْ كَ[n[ـٰ]فِر[p[ِي]نَ","Уларга шерикларидан шафоатчилар бўлмади ва улар шерикларига куфр келтиргувчи бўлдилар.",405,21],["وَيَوْمَ تَقُومُ [h:10435[ٱ][l[ل]سَّاعَةُ يَوْمَئِ[a:10439[ذٍ ي]َتَفَرَّق[p[ُو]نَ","Қиёмат қоим бўлган куни, ўша куни бўлинурлар.",405,21],["فَأَ[g[مّ]َا [h:136[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ فَهُمْ فِى رَوْضَ[a:10440[ةٍ ي]ُحْبَر[p[ُو]نَ","Бас, иймон келтириб, яхши амалларни қилганлар, улар жаннатда шодланурлар.",405,21],["وَأَ[g[مّ]َا [h:138[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَكَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا وَلِقَآىِٕ [h:10441[ٱ]لْأَخِرَةِ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ فِى [h:10442[ٱ]لْعَذَابِ مُحْضَر[p[ُو]نَ","Куфр келтириб, Бизнинг оятларимизни ва охират мулоқотини ёлғонга чиқарганлар, ана ўшалар, азобга ҳозир қилинурлар.",406,21],["فَسُ[q:8705[بْ]حَ[n[ـٰ]نَ [h:8706[ٱ]للَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِح[p[ُو]نَ","Бас, тунга киришингизда ҳам, тонгга киришингизда ҳам Аллоҳни поклаб ёд этинг.",406,21],["وَلَهُ [h:10443[ٱ]لْحَمْدُ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَعَشِي[a:10444[ًّا و]َحِينَ تُظْهِر[p[ُو]نَ","Осмонлару ердаги ҳамду сано Уникидир. Оқшомда ва пешинда ҳам.",406,21],["يُخْرِجُ [h:4258[ٱ]لْحَىَّ مِنَ [h:1833[ٱ]لْمَيِّتِ وَيُخْرِجُ [h:6039[ٱ]لْمَيِّتَ مِنَ [h:1835[ٱ]لْحَىِّ وَيُحْىِ [h:10445[ٱ]لْأَرْضَ بَعْدَ مَوْتِهَا‌ۚ وَكَذ[n[َٲ]لِكَ تُخْرَج[p[ُو]نَ","У ўликдан тирикни чиқарур ва тирикдан ўликни чиқарур ва ерни ўлимидан кейин тирилтирур. Шунга ўхшаш сиз ҳам чиқарилурсиз.",406,21],["وَمِنْ ءَايَ[n[ـٰ]تِه[o[ِۦٓ] أَنْ خَلَقَك[w:2530[ُم م]ِّ[f:1972[ن ت]ُرَا[f:1973[بٍ ث]ُ[g[مّ]َ إِذ[o[َآ] أَ[f:428[نت][c:3459[ُم ب]َشَ[f:10446[رٌ ت]َ[f:10447[نت]َشِر[p[ُو]نَ","Сизни тупроқдан яратгани ва сўнгра сизлар башарга айланиб тарқалишингиз Унинг оят-белгиларидандир.",406,21],["وَمِنْ ءَايَ[n[ـٰ]تِه[o[ِۦٓ] أَنْ خَلَقَ لَك[w:556[ُم م]ِّنْ أَ[f:1329[نف]ُسِكُمْ أَزْو[n[َٲ][u:10448[جًا ل]ِّتَسْكُن[o[ُوٓ][s[اْ] إِلَيْهَا وَجَعَلَ بَيْنَك[w:10449[ُم م]َّوَدَّ[a:10450[ةً و]َرَحْمَةً‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:6018[مٍ ي]َتَفَكَّر[p[ُو]نَ","Ва сизларга сокинлик топишингиз учун ўзингиздан жуфтлар яратганлиги ва ораларингизда севги ва марҳаматни солиб қўйгани Унинг оят-белгиларидандир. Албатта, бунда тафаккур қиладиган қавмлар учун оят-белгилар бордир.",406,21],["وَمِنْ ءَايَ[n[ـٰ]تِه[n[ِۦ] خَلْقُ [h:10451[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَ[h:10452[ٱ]خْتِلَ[n[ـٰ]فُ أَلْسِنَتِكُمْ وَأَلْو[n[َٲ]نِكُمْ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:10453[تٍ ل]ِّلْعَ[n[ـٰ]لِم[p[ِي]نَ","Ва Унинг оят-белгиларидан осмонлару ернинг яратилиши ва тилларингиз ва рангларингизнинг турлича бўлишидир. Албатта, бунда олимлар учун оят-белгилар бордир.",406,21],["وَمِنْ ءَايَ[n[ـٰ]تِه[n[ِۦ] مَنَامُك[c:10454[ُم ب]ِ[h:1622[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ وَ[h:10455[ٱ][q:10455[بْ]تِغ[o[َا]ٓؤُك[w:10456[ُم م]ِّ[f:475[ن ف]َضْلِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:6119[مٍ ي]َسْمَع[p[ُو]نَ","Ва Унинг оят-белгиларидан кечаси ва кундузи ухлашингиз ҳамда Унинг фазлидан талаб қилишингиздир. Албатта, бунда эшитадиган қавм учун оят-белгилар бордир.",406,21],["وَمِنْ ءَايَ[n[ـٰ]تِه[n[ِۦ] يُرِيكُمُ [h:6910[ٱ]لْبَرْقَ خَوْ[a:4752[فًا و]َطَمَ[a:10457[عًا و]َيُنَزِّلُ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:10458[ءً ف]َيُحْى[n[ِۦ] بِهِ [h:842[ٱ]لْأَرْضَ بَعْدَ مَوْتِه[o[َآ‌ۚ] إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:850[مٍ ي]َعْقِل[p[ُو]نَ","Ва Унинг оятларидан сизга қўрқув ва умид учун чақмоқни кўрсатади ва осмондан сувни нозил қилади-да, у билан ерни ўлгандан кейин тирилтиради. Албатта, бунда ақл юратадиган қавм учун оят-белгилар бордир.",406,21],["وَمِنْ ءَايَ[n[ـٰ]تِه[o[ِۦٓ] أَ[f:5839[ن ت]َقُومَ [h:10459[ٱ][l[ل]سَّم[o[َا]ٓءُ وَ[h:2241[ٱ]لْأَرْضُ بِأَمْرِه[n[ِۦ]‌ۚ ثُ[g[مّ]َ إِذَا دَعَاكُمْ دَعْوَ[a:10460[ةً م]ِّنَ [h:1579[ٱ]لْأَرْضِ إِذ[o[َآ] أَ[f:428[نت]ُمْ تَخْرُج[p[ُو]نَ","Унинг оят-белгиларидан, осмонлару ер Унинг амри ила туришидир. Сўнгра сизларни бир бор чақирса, ердан ҳаммангиз бирдан чиқарсизлар.",407,21],["وَلَهُ[n[ۥ] مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ كُ[u:610[لٌّ ل]َّهُ[n[ۥ] قَ[n[ـٰ]نِت[p[ُو]نَ","Осмонлару ердаги кимсалар Унга хосдир. Барчалари Унга итоат қилгувчидирлар.",407,21],["وَهُوَ [h:4114[ٱ]لَّذِى يَ[q:5943[بْ]دَؤُ[s[اْ] [h:5944[ٱ]لْخَلْقَ ثُ[g[مّ]َ يُعِيدُهُ[n[ۥ] وَهُوَ أَهْوَنُ عَلَيْهِ‌ۚ وَلَهُ [h:10461[ٱ]لْمَثَلُ [h:7451[ٱ]لْأَعْلَىٰ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","У махлуқотни йўқдан бор қиладир, сўнгра уни яна қайтадан вужудга келтирадир, бу унга жуда осондир. Осмонлару ердаги энг олий васф Уникидир. У азиз ва ҳаким зотдир.",407,21],["ضَرَبَ لَك[w:10462[ُم م]َّثَل[a:10463[اً م]ِّنْ أَ[f:1329[نف]ُسِكُمْ‌ۖ هَل لَّك[w:556[ُم م]ّ[a:10464[ِن م]َّا مَلَكَتْ أَيْمَ[n[ـٰ]نُك[w:2713[ُم م]ِّ[f:10465[ن ش]ُرَك[o[َا]ٓءَ فِى مَا رَزَ[q:275[قْ]نَ[n[ـٰ]كُمْ فَأَ[f:10466[نت]ُمْ فِيهِ سَو[o[َا]ٓ[f:10467[ءٌ ت]َخَافُونَهُمْ كَخِيفَتِكُمْ أَ[f:221[نف]ُسَكُمْ‌ۚ كَذ[n[َٲ]لِكَ نُفَصِّلُ [h:4091[ٱ]لْأَيَ[n[ـٰ]تِ لِقَوْ[a:850[مٍ ي]َعْقِل[p[ُو]نَ","У сизга ўзингиздан мисол келтирди. Сизларнинг қўлингиздаги дан Биз сизга ризқ қилиб берган нарсада шерикларингиз бор-у, сизлар уда тенг бўлиб, улар ҳақида ҳам ўзингиздан ҳаққингизда қўрққанингиздек қўрқасизми?! Ақл юритадиган қавмлар учун оятларни ана шундай муфассал қилиб борурмиз.",407,21],["بَلِ [h:10468[ٱ]تَّبَعَ [h:10469[ٱ]لَّذِينَ ظَلَم[o[ُوٓ][s[اْ] أَهْو[o[َا]ٓءَه[c:10470[ُم ب]ِغَيْرِ عِلْ[f:10471[مٍ‌ۖ ف]َم[a:10472[َن ي]َهْدِى مَنْ أَضَلَّ [h:3001[ٱ]للَّهُ‌ۖ وَمَا لَه[w:1812[ُم م]ّ[a:1813[ِن ن]َّ[n[ـٰ]صِر[p[ِي]نَ","Йўқ!!! Зулм қилганлар илмсиз равишда ҳавойи нафсларига эргашдилар, холос. Аллоҳ залолатга солган кимсани ким ҳидоятга сола оларди?! Ва охиратда уларга нусрат бергувчилар бўлмас.",407,21],["فَأَقِمْ وَ[q:749[جْ]هَكَ لِلدِّينِ حَنِي[f:10473[فًا‌ۚ ف]ِ[q:10474[طْ]رَتَ [h:10475[ٱ]للَّهِ [h:4656[ٱ]لَّتِى فَطَرَ [h:10476[ٱ][l[ل][g[نّ]َاسَ عَلَيْهَا‌ۚ لَا تَ[q:6113[بْ]دِيلَ لِخَلْقِ [h:10477[ٱ]للَّهِ‌ۚ ذ[n[َٲ]لِكَ [h:5569[ٱ][l[ل]دِّينُ [h:5570[ٱ]لْقَيِّمُ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Бас, сен ҳаққа мойил бўлиб, динга юз тут. Бу Аллоҳ одамларни яратган асил табиатдир. Аллоҳнинг яратганини ўзгартириб бўлмас. Ушбу тўғри диндир. Лекин одамларнинг кўпи билмаслар.",407,21],["۞ مُنِيبِينَ إِلَيْهِ وَ[h:4181[ٱ]تَّقُوهُ وَأَقِيمُو[s[اْ] [h:214[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَلَا تَكُونُو[s[اْ] مِنَ [h:699[ٱ]لْمُشْرِك[p[ِي]نَ","Унга қайтгувчи бўлароқ, У зотга тақво қилинг, намозни тўкис адо этинг ва мушриклардан бўлманг.",407,21],["مِنَ [h:523[ٱ]لَّذِينَ فَرَّقُو[s[اْ] دِينَهُمْ وَكَانُو[s[اْ] شِيَ[f:10478[عًا‌ۖ ك]ُلُّ حِزْ[i:9228[بِۭ ب]ِمَا لَدَيْهِمْ فَرِح[p[ُو]نَ","Динларида тафриқага тушган, гуруҳ-гуруҳ бўлиб олиб, ҳар бир фирқа ўз олдидаги нарсадан шод бўлганлардан.",407,21],["وَإِذَا مَسَّ [h:10479[ٱ][l[ل][g[نّ]َاسَ ضُ[f:10480[رٌّ د]َعَوْ[s[اْ] رَبَّه[w:10481[ُم م]ُّنِيبِينَ إِلَيْهِ ثُ[g[مّ]َ إِذ[o[َآ] أَذَاقَه[w:10482[ُم م]ِّنْهُ رَحْمَةً إِذَا فَرِي[a:388[قٌ م]ِّنْه[c:10483[ُم ب]ِرَبِّهِمْ يُشْرِك[p[ُو]نَ","Қачон одамларга зарар етса, Роббиларининг Ўзигагина қайтиб, дуо қилурлар. Сўнгра У зот уларга Ўзидан раҳмат тоттирганда, кўрибсанки, улардан баъзи гуруҳлари Роббиларига ширк келтирурлар.",408,21],["لِيَكْفُرُو[s[اْ] بِم[o[َآ] ءَاتَيْنَ[n[ـٰ]هُمْ‌ۚ فَتَمَتَّعُو[s[اْ] فَسَوْفَ تَعْلَم[p[ُو]نَ","Биз уларга берган нарсага куфр келтираверсинлар! Бас, ҳузурланаверинг! Яқинда биласизлар!",408,21],["أَمْ أَ[f:515[نز]َلْنَا عَلَيْهِمْ سُلْطَ[n[ـٰ][f:10484[نًا ف]َهُوَ يَتَكَلَّمُ بِمَا كَانُو[s[اْ] بِه[n[ِۦ] يُشْرِك[p[ُو]نَ","Ёки Биз уларга осмондан ҳужжат туширганмизу у У зотга ширк келтирган нарса ҳақида сўзлайдими?!",408,21],["وَإِذ[o[َآ] أَذَ[q:5991[قْ]نَا [h:5992[ٱ][l[ل][g[نّ]َاسَ رَحْمَ[f:10485[ةً ف]َرِحُو[s[اْ] بِهَا‌ۖ وَإِ[f:2950[ن ت]ُصِ[q:2951[بْ]هُمْ سَيِّئَ[i:10486[ةُۢ ب]ِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَ[q:10487[قْ]نَط[p[ُو]نَ","Ва қачон одамларга раҳматни тоттирсак, ундан шод бўлурлар. Агар уларга ўз қўллари тақдим қилган нарса туфайли ёмонлик етса, дарҳол умидсизликка тушурлар.",408,21],["أَوَلَمْ يَرَوْ[s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَ[q:6968[بْ]سُطُ [h:6969[ٱ][l[ل]رِّزْقَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيَ[q:6970[قْ]دِرُ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Улар Аллоҳ Ўзи хоҳлаган кишисига ризқни кенг ёки тор қилишини билмайдиларми? Албатта, бунда иймон келтирадиган қавм учун оят-белгилар бордир.",408,21],["فَـَٔـاتِ ذَا [h:7727[ٱ]لْقُرْبَىٰ حَقَّهُ[n[ۥ] وَ[h:7728[ٱ]لْمِسْكِينَ وَ[h:911[ٱ][q:911[بْ]نَ [h:912[ٱ][l[ل]سَّبِيلِ‌ۚ ذ[n[َٲ]لِكَ خَيْ[u:4005[رٌ ل]ِّلَّذِينَ يُرِيدُونَ وَ[q:2019[جْ]هَ [h:10488[ٱ]للَّهِ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Бас, қариндошга, мискинга ва йўл ўғлига ҳаққини бер. Ана шу Аллоҳнинг юзини ирода қилганлар учун хайрлидир. Ва ана ўшалар нажот топгувчилардир.",408,21],["وَم[o[َآ] ءَاتَيْت[w:10489[ُم م]ّ[u:10490[ِن ر]ِّ[u:10491[بًا ل]ِّيَرْبُوَ[s[اْ] ف[o[ِىٓ] أَمْو[n[َٲ]لِ [h:1008[ٱ][l[ل][g[نّ]َاسِ فَلَا يَرْبُو[s[اْ] عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۖ وَم[o[َآ] ءَاتَيْت[w:10489[ُم م]ِّ[f:10492[ن ز]َكَ[s[و][n[ٲ][f:10493[ةٍ ت]ُرِيدُونَ وَ[q:2019[جْ]هَ [h:10488[ٱ]للَّهِ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:10494[ٱ]لْمُضْعِف[p[ُو]نَ","Одамлар моллари ичида зиёда бўлсин, деб рибо учун берган молингиз Аллоҳ ҳузурида зиёда бўлмас. Аллоҳнинг юзини кўзлаб берган закотингиз эса, бас, ана ўшалар, бир неча баробар қилиб олгувчилардир.",408,21],["ٱللَّهُ [h:4738[ٱ]لَّذِى خَلَقَكُمْ ثُ[g[مّ]َ رَزَقَكُمْ ثُ[g[مّ]َ يُمِيتُكُمْ ثُ[g[مّ]َ يُحْيِيكُمْ‌ۖ هَلْ مِ[f:6046[ن ش]ُرَك[o[َا]ٓئِك[w:6047[ُم م]ّ[a:439[َن ي]َفْعَلُ مِ[f:1784[ن ذ][n[َٲ]لِك[w:10495[ُم م]ِّ[f:2103[ن ش][f:10496[َىْءٍ‌ۚ س]ُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ] وَتَعَ[n[ـٰ]لَىٰ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","Сизларни халқ қилган, сўнгра ризқлантирган, кейин ўлдирадиган ва яна тирилтирадиган зот Аллоҳдир. Сизнинг шерикларингиздан, ким ана шуларингиздан бирортасини қила олади?! У зот улар ширк келтираётган нарсалардан пок ва олий бўлди.",408,21],["ظَهَرَ [h:10497[ٱ]لْفَسَادُ فِى [h:4106[ٱ]لْبَرِّ وَ[h:4107[ٱ]لْبَحْرِ بِمَا كَسَبَتْ أَيْدِى [h:10498[ٱ][l[ل][g[نّ]َاسِ لِيُذِيقَه[c:10499[ُم ب]َعْضَ [h:1943[ٱ]لَّذِى عَمِلُو[s[اْ] لَعَلَّهُمْ يَرْجِع[p[ُو]نَ","Қилган амалларининг баъзисини тоттириш учун, одамлар қўллари касб қилган нарсалар туфайли қуруқликдаю денгизда фасод зоҳир бўлди. Шоядки улар қайтсалар.",408,21],["قُلْ سِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَ[h:2257[ٱ][f:2257[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6854[ٱ]لَّذِينَ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۚ كَانَ أَكْثَرُه[w:10500[ُم م]ُّشْرِك[p[ِي]نَ","Сен: «Ер юзида сайр қилинглар. Олдин ўтганларнинг оқибати қандай бўлганига назар солинглар. Уларнинг кўплари мушрик бўлган эдилар», деб айт.",409,21],["فَأَقِمْ وَ[q:749[جْ]هَكَ لِلدِّينِ [h:10501[ٱ]لْقَيِّمِ مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:1462[َن ي]َأْتِىَ يَوْ[u:1463[مٌ ل]َّا مَرَدَّ لَهُ[n[ۥ] مِنَ [h:321[ٱ]للَّهِ‌ۖ يَوْمَئِ[a:10502[ذٍ ي]َصَّدَّع[p[ُو]نَ","Бас, Аллоҳ томонидан рад қилинмайдиган кун келмасдан аввал тўғри динга юз тут. Ўша кунда бўлак-бзлак бўлурлар.",409,21],["مَ[f:1457[ن ك]َفَرَ فَعَلَيْهِ كُفْرُهُ[n[ۥ]‌ۖ وَمَنْ عَمِلَ صَ[n[ـٰ]لِ[f:10503[حًا ف]َلِأَ[f:10504[نف]ُسِهِمْ يَمْهَد[p[ُو]نَ","Ким куфр келтирса, унинг куфри ўз зарарига. Кимлар яхши амаллар қилган бўлса, ўзлари учун замин тайёрларлар.",409,21],["لِيَ[q:5945[جْ]زِىَ [h:5946[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ مِ[f:475[ن ف]َضْلِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] لَا يُحِبُّ [h:1858[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","У зот иймон келтирган ва яхши амалларни қилганларни Ўз фазли ила мукофотлаши учундир. Албатта, У кофирларни севмас.",409,21],["وَمِنْ ءَايَ[n[ـٰ]تِه[o[ِۦٓ] أ[a:10505[َن ي]ُرْسِلَ [h:10506[ٱ][l[ل]رِّيَاحَ مُبَشِّر[n[َٲ][a:10507[تٍ و]َلِيُذِيقَك[w:10508[ُم م]ّ[u:7986[ِن ر]َّحْمَتِه[n[ِۦ] وَلِتَ[q:10509[جْ]رِىَ [h:10510[ٱ]لْفُلْكُ بِأَمْرِه[n[ِۦ] وَلِتَ[q:7353[بْ]تَغُو[s[اْ] مِ[f:475[ن ف]َضْلِه[n[ِۦ] وَلَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Ва Унинг оят-белгиларидан сизга Ўз раҳматидан тоттириш учун, Ўз амри ила кемаларни юрдириш учун ва Унинг фазлидан талаб қилишингиз учун шамолларни хушхабарчи қилиб юборишидир. Шоядки шукр қилсангиз.",409,21],["وَلَقَ[q:341[دْ] أَرْسَلْنَا مِ[f:18[ن ق]َ[q:19[بْ]لِكَ رُسُلاً إِلَىٰ قَوْمِهِمْ فَج[o[َا]ٓءُوه[c:6138[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ فَ[h:4969[ٱ][f:4969[نت]َقَمْنَا مِنَ [h:523[ٱ]لَّذِينَ أَ[q:4390[جْ]رَمُو[s[اْ‌ۖ] وَكَانَ حَقًّا عَلَيْنَا نَصْرُ [h:10511[ٱ]لْمُؤْمِن[p[ِي]نَ","Батаҳқиқ, Биз сендан олдин ҳам Пайғамбарларни қавмларига юбордик. Бас, улар очиқ-ойдин ҳужжатлар келтирганлар. Сўнг Биз жиноят қилганлардан интиқом олганмиз. Мўминларга нусрат бериш Бизнинг зиммамиздаги ҳақ бўлган.",409,21],["ٱللَّهُ [h:4738[ٱ]لَّذِى يُرْسِلُ [h:4755[ٱ][l[ل]رِّيَ[n[ـٰ]حَ فَتُثِيرُ سَحَا[f:10512[بًا ف]َيَ[q:10513[بْ]سُطُهُ[n[ۥ] فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ كَيْفَ يَش[o[َا]ٓءُ وَيَ[q:10514[جْ]عَلُهُ[n[ۥ] كِسَ[f:10515[فًا ف]َتَرَى [h:9469[ٱ]لْوَ[q:9470[دْ]قَ يَخْرُجُ مِنْ خِلَ[n[ـٰ]لِه[n[ِۦ]‌ۖ فَإِذ[o[َآ] أَصَابَ بِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[o[ِۦٓ] إِذَا هُمْ يَسْتَ[q:2415[بْ]شِر[p[ُو]نَ","Аллоҳ шундай зотки, шамолларни юбориб, улар ила булутни қўзғатар ва у ни осмонда Ўзи хоҳлаганича ёяр ва бўлак-бўлак қилар, бас, унинг орасидан ёмғир чиқаётганини кўрасан. Қачон уни Ўз бандаларидан хоҳлаган кимсаларга етказса, улар дарҳол шод бўлурлар.",409,21],["وَإِ[f:2392[ن ك]َانُو[s[اْ] مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:547[َن ي]ُنَزَّلَ عَلَيْه[w:4082[ِم م]ِّ[f:1097[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] لَمُ[q:10516[بْ]لِس[p[ِي]نَ","Ҳолбуки, устларига туширилишидан олдин, ҳа, ундан олдин, мутлақо умидсиз эдилар.",409,21],["فَ[h:9999[ٱ][f:1513[نظ]ُرْ إِلَ[o[ىٰٓ] ءَاثَ[n[ـٰ]رِ رَحْمَتِ [h:10517[ٱ]للَّهِ كَيْفَ يُحْىِ [h:10518[ٱ]لْأَرْضَ بَعْدَ مَوْتِه[o[َآ‌ۚ] إِ[g[نّ]َ ذ[n[َٲ]لِكَ لَمُحْىِ [h:10519[ٱ]لْمَوْتَىٰ‌ۖ وَهُوَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Бас, Роббинг раҳмати асарларига назар сол. У ерни ўлиб ётганидан кейин қандай тирилтиради?! Албатта, У зот ўликларни ҳам тирилтиргувчидир ва У ҳар бир нарсага қодирдир.",409,21],["وَلَئِنْ أَرْسَلْنَا رِي[f:10520[حًا ف]َرَأَوْهُ مُصْفَر[u:10521[ًّا ل]َّظَلُّو[s[اْ] م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] يَكْفُر[p[ُو]نَ","Агар Биз бир шамол юбориб, улар сарғайган ҳолда кўрсалар, ундан кейин, албатта, куфрони неъмат қилишга ўтарлар.",410,21],["فَإِ[g[نّ]َكَ لَا تُسْمِعُ [h:10033[ٱ]لْمَوْتَىٰ وَلَا تُسْمِعُ [h:6070[ٱ][l[ل]صُّ[g[مّ]َ [h:10034[ٱ][l[ل]دُّع[o[َا]ٓءَ إِذَا وَلَّوْ[s[اْ] مُ[q:5528[دْ]بِر[p[ِي]نَ","Албатта, сен ўликка эшиттира олмассан ва даъватни ортларига бурилиб кетаётган карларга эшиттира олмайссан.",410,21],["وَم[o[َآ] أَ[f:169[نت]َ بِهَ[n[ـٰ]دِ [h:10522[ٱ]لْعُمْىِ عَ[f:10036[ن ض]َلَ[n[ـٰ]لَتِهِمْ‌ۖ إِ[f:10037[ن ت]ُسْمِعُ إِلَّا م[a:5799[َن ي]ُؤْمِنُ بِـَٔـايَ[n[ـٰ]تِنَا فَه[w:10038[ُم م]ُّسْلِم[p[ُو]نَ","Сен кўрларни гумроҳликларидан ҳидоят қилгувчи эмассан. Сен фақат Бизнинг оятларимизга иймон келтирганларгагина эшиттира олурсан. Ана ўшалар мусулмонлардир.",410,21],["۞ ٱللَّهُ [h:4738[ٱ]لَّذِى خَلَقَك[w:2530[ُم م]ِّ[f:10523[ن ض]َعْ[f:10524[فٍ ث]ُ[g[مّ]َ جَعَلَ م[i:146[ِنۢ ب]َعْدِ ضَعْ[f:10525[فٍ ق]ُوَّ[f:10526[ةً ث]ُ[g[مّ]َ جَعَلَ م[i:146[ِنۢ ب]َعْدِ قُوَّ[f:10527[ةٍ ض]َعْ[a:10528[فًا و]َشَيْبَ[a:10529[ةً‌ۚ ي]َخْلُقُ مَا يَش[o[َا]ٓءُ‌ۖ وَهُوَ [h:10530[ٱ]لْعَلِيمُ [h:10531[ٱ]لْقَد[p[ِي]رُ","Аллоҳ сизни заифликда яратган, сўнгра заифликдан кейин қувватли қилган, сўнгра қувватдан кейин яна заифлик ва қарилик ориз қилган зотдир. У хоҳлаганини яратур. У ўта илмли ва ўта қудратлидир.",410,21],["وَيَوْمَ تَقُومُ [h:10435[ٱ][l[ل]سَّاعَةُ يُ[q:10532[قْ]سِمُ [h:10533[ٱ]لْمُ[q:5255[جْ]رِمُونَ مَا لَبِثُو[s[اْ] غَيْرَ سَاعَ[f:10534[ةٍ‌ۚ ك]َذ[n[َٲ]لِكَ كَانُو[s[اْ] يُؤْفَك[p[ُو]نَ","Қиёмат қоим бўладиган куни жиноятчилар бир соатдан бошқа турмаганлари ҳақида қасам ичурлар. Улар ана шундай ўгрилар эдилар.",410,21],["وَقَالَ [h:614[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:7379[ٱ]لْعِلْمَ وَ[h:10535[ٱ]لْإِيمَ[n[ـٰ]نَ لَقَ[q:2389[دْ] لَبِثْتُمْ فِى كِتَ[n[ـٰ]بِ [h:1816[ٱ]للَّهِ إِلَىٰ يَوْمِ [h:10536[ٱ]لْبَعْثِ‌ۖ فَهَ[n[ـٰ]ذَا يَوْمُ [h:10537[ٱ]لْبَعْثِ وَلَ[n[ـٰ]كِ[g[نّ]َكُمْ كُ[f:100[نت]ُمْ لَا تَعْلَم[p[ُو]نَ","Илм ва иймон берилганлар: «Батаҳқиқ, Аллоҳнинг китоби бўйича қайта тирилиш кунигача турдингиз. Бас, бугун қайта тирилиш кунидир. Лекин сизлар билмас эдингиз», дерлар.",410,21],["فَيَوْمَئِ[u:10538[ذٍ ل]َّا يَ[f:838[نف]َعُ [h:10539[ٱ]لَّذِينَ ظَلَمُو[s[اْ] مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَب[p[ُو]نَ","Бас, бугунги кунда зулм қилганларга маъзиратлари манфаат бермас ҳамда улар итобга ҳам қайтарилмаслар.",410,21],["وَلَقَ[q:341[دْ] ضَرَ[q:9642[بْ]نَا لِل[g[نّ]َاسِ فِى هَ[n[ـٰ]ذَا [h:7765[ٱ]لْقُرْءَانِ مِ[f:843[ن ك]ُلِّ مَثَ[a:10540[لٍ‌ۚ و]َلَئِ[f:10541[ن ج]ِئْتَه[c:10542[ُم ب]ِـَٔـايَ[u:10543[ةٍ ل]َّيَقُولَ[g[نّ]َ [h:6248[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] إِنْ أَ[f:428[نت]ُمْ إِلَّا مُ[q:10544[بْ]طِل[p[ُو]نَ","Батаҳқиқ, Биз ушбу Қуръонда одамлар учун турли мисоллар келтирдик. Аниқки, агар сен уларга оят-мўъжиза келтирсанг ҳам, куфр келтирганлар: «Сиз ботилчилардан ўзга эмассиз», дерлар.",410,21],["كَذ[n[َٲ]لِكَ يَ[q:4901[طْ]بَعُ [h:4902[ٱ]للَّهُ عَلَىٰ قُلُوبِ [h:2312[ٱ]لَّذِينَ لَا يَعْلَم[p[ُو]نَ","Аллоҳ билмайдиганларнинг қалбларини ана шундай қилиб муҳрлар.",410,21],["فَ[h:9999[ٱ]صْبِرْ إِ[g[نّ]َ وَعْدَ [h:3149[ٱ]للَّهِ حَ[a:10545[قٌّ‌ۖ و]َلَا يَسْتَخِفَّ[g[نّ]َكَ [h:10546[ٱ]لَّذِينَ لَا يُوقِن[p[ُو]نَ","Бас, сабр қил. Албатта, Аллоҳнинг ваъдаси ҳақдир. Собит иймон келтирмаганлар сени енгилтакликка бошламасинлар.",410,21]]},{"n":31,"ar":"لُقۡمَانَ","en":"Luqman","uz":"Луқмон","type":"Макка","ayahs":[["ا[m[لٓ][m[مٓ]","Алиф. Лам. Мийм.",411,21],["تِلْكَ ءَايَ[n[ـٰ]تُ [h:5932[ٱ]لْكِتَ[n[ـٰ]بِ [h:5933[ٱ]لْحَك[p[ِي]مِ","Ушбулар ҳикматли Китоб оятларидир.",411,21],["هُ[a:4734[دًى و]َرَحْمَ[u:10547[ةً ل]ِّلْمُحْسِن[p[ِي]نَ","У муҳсинларга ҳидоят ва раҳматдир.",411,21],["ٱلَّذِينَ يُقِيمُونَ [h:3638[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَيُؤْتُونَ [h:3639[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَه[c:4710[ُم ب]ِ[h:447[ٱ]لْأَخِرَةِ هُمْ يُوقِن[p[ُو]نَ","Намозни тўкис адо этадиган, закотни берадиган ва охиратга ишонч-ла иймон келтирадиганларга.",411,21],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ عَلَىٰ هُ[a:21[دًى م]ّ[u:22[ِن ر]َّبِّهِمْ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Ана ўшалар, Роббиларидан бўлган ҳидоятдадирлар. Ана ўшалар, ўзлари нажот топгувчилардир.",411,21],["وَمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ م[a:10548[َن ي]َشْتَرِى لَهْوَ [h:10549[ٱ]لْحَدِيثِ لِيُضِلَّ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ بِغَيْرِ عِلْ[a:10550[مٍ و]َيَتَّخِذَهَا هُزُوًا‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ عَذَا[a:478[بٌ م]ُّه[p[ِي]نٌ","Одамлар орасида илмсиз равишда Аллоҳнинг йўлидан адаштириш учун ва уни истеҳзо қилиш учун беҳуда сўзни сотиб оладиган кимсалар ҳам бор. Ана ўшаларга ўзларига хорловчи азоб бордир.",411,21],["وَإِذَا تُتْلَىٰ عَلَيْهِ ءَايَ[n[ـٰ]تُنَا وَلَّىٰ مُسْتَكْبِ[f:10551[رًا ك]َأ[u:2914[َن ل]َّمْ يَسْمَعْهَا كَأَ[g[نّ]َ ف[o[ِىٓ] أُذُنَيْهِ وَ[q:3988[قْ][f:10552[رًا‌ۖ ف]َبَشِّرْهُ بِعَذَابٍ أَل[p[ِي]مٍ","Қачон унга Бизнинг оятларимиз тиловат қилинса, худди уларни эшитмагандек, худди қулоғида оғирлик бордек мутакаббирлик билан ортга қараб кетадир. Бас, унга аламли азобнинг башоратини бер.",411,21],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَهُمْ جَ[g[نّ]َ[n[ـٰ]تُ [h:10553[ٱ][l[ل][g[نّ]َع[p[ِي]مِ","Албатта, иймон келтириб, яхши амаллар қилганларга, ўшаларга неъмат жаннатлари бордир.",411,21],["خَ[n[ـٰ]لِدِينَ فِيهَا‌ۖ وَعْدَ [h:3149[ٱ]للَّهِ حَق[a:10554[ًّا‌ۚ و]َهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Улар унда абадий қолурлар. Аллоҳнинг ваъдаси ҳақдир. Ва У азиз ва ҳакимдир.",411,21],["خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ بِغَيْرِ عَمَ[f:6863[دٍ ت]َرَوْنَهَا‌ۖ وَأَلْقَىٰ فِى [h:44[ٱ]لْأَرْضِ رَو[n[َٲ]سِىَ أَ[f:7354[ن ت]َمِيدَ بِكُمْ وَبَثَّ فِيهَا مِ[f:843[ن ك]ُلِّ د[m[َا]ٓبَّ[a:10555[ةٍ‌ۚ و]َأَ[f:271[نز]َلْنَا مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:9997[ءً ف]َأَ[i:9998[نۢب]َتْنَا فِيهَا مِ[f:843[ن ك]ُلِّ زَوْ[f:9715[جٍ ك]َر[p[ِي]مٍ","У, сиз кўриб турганингиздек, осмонларни устунсиз яратган, сизларни тебратмаслиги учун ер юзига оғир тоғларни ташлаган ва да ҳар турли жониворларни таратиб қўйган зотдир. Ва осмондан сув тушириб, у билан унда турли гўзал ва фойдали жуфтларни ўстириб қўйдик.",411,21],["هَ[n[ـٰ]ذَا خَلْقُ [h:10556[ٱ]للَّهِ فَأَرُونِى مَاذَا خَلَقَ [h:10557[ٱ]لَّذِينَ مِ[f:3136[ن د]ُونِه[n[ِۦ]‌ۚ بَلِ [h:10558[ٱ][l[ل]ظَّ[n[ـٰ]لِمُونَ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Бу Аллоҳнинг яратганидир. Қани менга кўрсатинг-чи, Ундан бошқалар нимани яратдилар. Йўқ! Золимлар очиқ-ойдин адашувдадирлар.",411,21],["وَلَقَ[q:341[دْ] ءَاتَيْنَا لُ[q:10559[قْ]مَ[n[ـٰ]نَ [h:10560[ٱ]لْحِكْمَةَ أَنِ [h:10561[ٱ]شْكُرْ لِلَّهِ‌ۚ وَم[a:10562[َن ي]َشْكُرْ فَإِ[g[نّ]َمَا يَشْكُرُ لِنَفْسِه[n[ِۦ]‌ۖ وَمَ[f:662[ن ك]َفَرَ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَنِىٌّ حَم[p[ِي][q[د]ٌ","Батаҳқиқ, Биз Луқмонга: «Аллоҳга шукр қил. Ким шукр қилса, ўзи учун қиладир. Ким ношукрлик қилса, бас, албатта, Аллоҳ беҳожат ва мақталган зотдир», деб ҳикматни бердик.",412,21],["وَإِذْ قَالَ لُ[q:10563[قْ]مَ[n[ـٰ]نُ لِ[h:10564[ٱ][q:10564[بْ]نِه[n[ِۦ] وَهُوَ يَعِظُهُ[n[ۥ] يَ[n[ـٰ]بُنَىَّ لَا تُشْرِكْ بِ[h:32[ٱ]للَّهِ‌ۖ إِ[g[نّ]َ [h:10565[ٱ][l[ل]شِّرْكَ لَظُلْمٌ عَظ[p[ِي]مٌ","Луқмон ўғлига ваъз-насиҳат қилиб айтганларини эсла: «Эй ўғилчам, Аллоҳга ширк келтирма. Албатта, ширк катта зулмдир».",412,21],["وَوَصَّيْنَا [h:10289[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ بِو[n[َٲ]لِدَيْهِ حَمَلَتْهُ أُ[g[مّ]ُهُ[n[ۥ] وَهْنًا عَلَىٰ وَهْ[a:10566[نٍ و]َفِصَ[n[ـٰ]لُهُ[n[ۥ] فِى عَامَيْنِ أَنِ [h:10561[ٱ]شْكُرْ لِى وَلِو[n[َٲ]لِدَيْكَ إِلَىَّ [h:10567[ٱ]لْمَص[p[ِي]رُ","Биз инсонга ота-онаси ҳақида тавсия қилдик: онаси уни заифлик устига заифлик билан кўтарди; уни сутдан ажратиш икки йил ичидадир: «Менга ва ота-онага шукр қилгин. Ва қайтиш фақат Менгадир».",412,21],["وَإِ[f:10291[ن ج]َ[n[ـٰ]هَدَاكَ عَلَ[o[ىٰٓ] أَ[f:10568[ن ت]ُشْرِكَ بِى مَا لَيْسَ لَكَ بِه[n[ِۦ] عِلْ[f:10292[مٌ ف]َلَا تُطِعْهُمَا‌ۖ وَصَاحِ[q:10569[بْ]هُمَا فِى [h:599[ٱ][l[ل]دُّنْيَا مَعْرُو[a:10570[فًا‌ۖ و]َ[h:7280[ٱ]تَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَىَّ‌ۚ ثُ[g[مّ]َ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُك[c:10293[ُم ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Агар икковлари сени ўзинг билмаган нарсани Менга ширк келтиришга зўрласалар, бас, уларга итоат этма! Ва дунёда икковларига яхшилик қил ҳамда Менга йўналганларнинг йўлига эргаш. Сўнгра қайтишингиз фақат Менгадир. Бас, Мен сизга нима амал қилганингиз хабарини берурман.",412,21],["يَ[n[ـٰ]بُنَىَّ إِ[g[نّ]َه[o[َآ] إِ[f:10571[ن ت]َكُ مِثْقَالَ حَبَّ[a:8775[ةٍ م]ِّنْ خَرْدَ[f:10572[لٍ ف]َتَكُ[f:10573[ن ف]ِى صَخْرَةٍ أَوْ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ أَوْ فِى [h:44[ٱ]لْأَرْضِ يَأْتِ بِهَا [h:10574[ٱ]للَّهُ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَطِيفٌ خَب[p[ِي]رٌ","«Эй ўғилчам, албатта, у агар ачитқининг бир дона уруғича бўлсаю у бир қоя тош ичида ёки осмонларда ёхуд ерда бўлса ҳам, Аллоҳ уни келтирур. Албатта, Аллоҳ ўта лутфли ва ўта хабардор зотдир.",412,21],["يَ[n[ـٰ]بُنَىَّ أَقِمِ [h:7851[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَأْمُرْ بِ[h:934[ٱ]لْمَعْرُوفِ وَ[h:10575[ٱ]نْهَ عَنِ [h:2144[ٱ]لْمُ[f:2145[نك]َرِ وَ[h:6232[ٱ]صْبِرْ عَلَىٰ م[o[َآ] أَصَابَكَ‌ۖ إِ[g[نّ]َ ذ[n[َٲ]لِكَ مِنْ عَزْمِ [h:2488[ٱ]لْأُم[p[ُو]رِ","Эй ўғилчам, намозни тўкис адо қил, яхшиликка буюриб, ёмонликдан қайтар ва ўзингга етган мусибатга сабр қил. Албатта, булар азм этилажак ишлардандир.",412,21],["وَلَا تُصَعِّرْ خَدَّكَ لِل[g[نّ]َاسِ وَلَا تَمْشِ فِى [h:44[ٱ]لْأَرْضِ مَرَحًا‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يُحِبُّ كُلَّ مُخْتَا[f:10576[لٍ ف]َخ[p[ُو]رٍ","Одамлардан такаббурла юз ўгирма ва ер юзида кибр-ҳаво ила юрма. Албатта, Аллоҳ ҳеч бир мутакаббир ва мақтанчоқни севмас.",412,21],["وَ[h:9999[ٱ][q:10577[قْ]صِ[q:10577[دْ] فِى مَشْيِكَ وَ[h:10578[ٱ]غْضُضْ مِ[f:10579[ن ص]َوْتِكَ‌ۚ إِ[g[نّ]َ أَ[f:10580[نك]َرَ [h:10581[ٱ]لْأَصْو[n[َٲ]تِ لَصَوْتُ [h:10582[ٱ]لْحَم[p[ِي]رِ","Юришингда мўътадил бўл ва овозингни пасайтир. Чунки овозларнинг энг ёмони эшакнинг овозидир».",412,21],["أَلَمْ تَرَوْ[s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ سَخَّرَ لَك[w:154[ُم م]َّا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُ[n[ۥ] ظَ[n[ـٰ]هِرَ[a:10583[ةً و]َبَاطِنَ[a:10584[ةً‌ۗ و]َمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ م[a:8901[َن ي]ُجَ[n[ـٰ]دِلُ فِى [h:714[ٱ]للَّهِ بِغَيْرِ عِلْ[a:7953[مٍ و]َلَا هُ[a:8927[دًى و]َلَا كِتَ[n[ـٰ][a:8928[بٍ م]ُّن[p[ِي]رٍ","Аллоҳ сизларга осмонлардаги нарсаларни ва ердаги нарсаларни беминнат хизматкор қилиб қўйганини ва сизга зоҳирий ва ботиний неъматларни мукаммал қилиб берганини билмадингизми?! Одамлардан илмсиз, ҳидоятсиз ва ёритувчи китобсиз Аллоҳ ҳақида тортишадиганлари ҳам бор.",413,21],["وَإِذَا قِيلَ لَهُمُ [h:878[ٱ]تَّبِعُو[s[اْ] م[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ قَالُو[s[اْ] بَلْ نَتَّبِعُ مَا وَجَ[q:3834[دْ]نَا عَلَيْهِ ءَاب[o[َا]ٓءَن[o[َآ‌ۚ] أَوَلَوْ كَانَ [h:10585[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ يَ[q:10586[دْ]عُوهُمْ إِلَىٰ عَذَابِ [h:8905[ٱ][l[ل]سَّع[p[ِي]رِ","Қачон уларга: «Аллоҳ нозил қилган нарсага эргашинглар», дейилса: «Йўқ! Биз оталаримизни ниманинг устида топсак, ўшанга эргашамиз», дерлар. Агар шайтон уларни дўзах азобига чақираётган бўлса ҳам-а?!",413,21],["۞ وَم[a:10587[َن ي]ُسْلِمْ وَ[q:580[جْ]هَهُ[o[ۥٓ] إِلَى [h:1637[ٱ]للَّهِ وَهُوَ مُحْسِ[f:10588[نٌ ف]َقَدِ [h:1484[ٱ]سْتَمْسَكَ بِ[h:1485[ٱ]لْعُرْوَةِ [h:1486[ٱ]لْوُثْقَىٰ‌ۗ وَإِلَى [h:1148[ٱ]للَّهِ عَ[n[ـٰ]قِبَةُ [h:9046[ٱ]لْأُم[p[ُو]رِ","Ким гўзал амалларни қилгувчи бўлган ҳолида Аллоҳга юз тутса, батаҳқиқ, у ишончли арқонни маҳкам тутибди. Ишларнинг оқибати фақат Аллоҳга қайтур.",413,21],["وَمَ[f:662[ن ك]َفَرَ فَلَا يَحْزُ[f:2435[نك]َ كُفْرُهُ[o[ۥٓ‌ۚ] إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُه[c:10589[ُم ب]ِمَا عَمِل[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","Ким куфр келтирса, унинг куфри сени хафа қилмасин. Қайтишлари фақат Бизгадир. Бас, Биз уларга нима амал қилганлари хабарини берурмиз. Албатта, Аллоҳ қалблардаги нарсаларни ўта билгувчидир.",413,21],["نُمَتِّعُهُمْ قَلِيل[f:663[اً ث]ُ[g[مّ]َ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَل[p[ِي]ظٍ","Уларни бир оз ҳузурлантирурмиз, сўнгра қаттиқ азобга мажбур қилурмиз.",413,21],["وَلَئِ[f:5683[ن س]َأَلْتَه[w:10403[ُم م]َّنْ خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ لَيَقُولُ[g[نّ]َ [h:10404[ٱ]للَّهُ‌ۚ قُلِ [h:9994[ٱ]لْحَمْدُ لِلَّهِ‌ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَم[p[ُو]نَ","Агар улардан: «Осмонлару ерни ким яратган?» деб сўрасанг, албатта, — «Аллоҳ», дерлар. Сен: «Аллоҳга ҳамд бўлсин», деб айт. Йўқ! Кўплари билмаслар.",413,21],["لِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ هُوَ [h:6121[ٱ]لْغَنِىُّ [h:9093[ٱ]لْحَم[p[ِي][q[د]ُ","Осмонлару ердаги нарсалар Аллоҳникидир. Албатта, Аллоҳ Ўзи беҳожат ва мақталган зотдир.",413,21],["وَلَوْ أَ[g[نّ]َمَا فِى [h:44[ٱ]لْأَرْضِ مِ[f:9427[ن ش]َجَرَةٍ أَ[q:10590[قْ]لَ[n[ـٰ][a:10591[مٌ و]َ[h:10592[ٱ]لْبَحْرُ يَمُدُّهُ[n[ۥ] م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] سَ[q:7251[بْ]عَةُ أَ[q:10593[بْ]حُ[a:10594[رٍ م]َّا نَفِدَتْ كَلِمَ[n[ـٰ]تُ [h:10595[ٱ]للَّهِ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَزِيزٌ حَك[p[ِي]مٌ","Агар ер юзидаги дарахтнинг барчаси қаламлар бўлиб, денгиз–уни ортида етти денгиз мадад бериб туриб бўлса ҳам, Аллоҳнинг калималари битмас. Албатта, Аллоҳ азиз ва ҳакимдир.",413,21],["مَّا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْ[a:10596[سٍ و][n[َٲ]حِدَةٍ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَمِي[i:9086[عُۢ ب]َص[p[ِي]رٌ","Сизларни яратиш ҳам, қайта тирилтириш ҳам фақат бир жон кабидир. Албатта, Аллоҳ ўта эшитгувчи ва ўта кўргувчидир.",413,21],["أَلَمْ تَرَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ يُولِجُ [h:9084[ٱ]لَّيْلَ فِى [h:1829[ٱ][l[ل][g[نّ]َهَارِ وَيُولِجُ [h:9085[ٱ][l[ل][g[نّ]َهَارَ فِى [h:1831[ٱ]لَّيْلِ وَسَخَّرَ [h:6864[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ كُ[a:6865[لٌّ ي]َ[q:6866[جْ]ر[o[ِىٓ] إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَم[a:10597[ًّى و]َأَ[g[نّ]َ [h:859[ٱ]للَّهَ بِمَا تَعْمَلُونَ خَب[p[ِي]رٌ","Аллоҳ кечани кундузга киритишини ва кундузни кечага киритишини, қуёш ва ойни беминнат хизматкор қилиб қўйганини, уларнинг ҳар бири белгиланган муддат томон юришини ва, албатта, Аллоҳ нима амал қилаётганингиздан хабардор эканини кўрмадингми?!",414,21],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َ [h:897[ٱ]للَّهَ هُوَ [h:8923[ٱ]لْحَقُّ وَأَ[g[نّ]َ مَا يَ[q:1240[دْ]عُونَ مِ[f:3136[ن د]ُونِهِ [h:10598[ٱ]لْبَ[n[ـٰ]طِلُ وَأَ[g[نّ]َ [h:859[ٱ]للَّهَ هُوَ [h:9088[ٱ]لْعَلِىُّ [h:9089[ٱ]لْكَب[p[ِي]رُ","Бу, албатта, Аллоҳнинг Ўзи ҳақ, албатта, Ундан ўзга илтижо қилаётганлари ботил ва, албатта, Аллоҳнинг Ўзи энг юксак ва энг буюк зот эканидандир.",414,21],["أَلَمْ تَرَ أَ[g[نّ]َ [h:10599[ٱ]لْفُلْكَ تَ[q:120[جْ]رِى فِى [h:837[ٱ]لْبَحْرِ بِنِعْمَتِ [h:10600[ٱ]للَّهِ لِيُرِيَك[w:10601[ُم م]ِّنْ ءَايَ[n[ـٰ]تِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:7049[تٍ ل]ِّكُلِّ صَبَّا[f:7050[رٍ ش]َك[p[ُو]رٍ","Кемалар Аллоҳнинг неъмати ила сизга Унинг оят-белгиларини кўрсатиш учун денгизда юрганини кўрмадингми?! Албатта, бунда ҳар бир ўта сабрли ва ўта шукрлилар учун оят-белгилар бордир.",414,21],["وَإِذَا غَشِيَه[w:10602[ُم م]َّوْ[f:10603[جٌ ك]َ[h:10604[ٱ][l[ل]ظُّلَلِ دَعَوُ[s[اْ] [h:6002[ٱ]للَّهَ مُخْلِصِينَ لَهُ [h:4649[ٱ][l[ل]دِّينَ فَلَ[g[مّ]َا نَجَّ[n[ـٰ]هُمْ إِلَى [h:7827[ٱ]لْبَرِّ فَمِنْه[w:10605[ُم م]ُّ[q:10606[قْ]تَصِ[a:10607[دٌ‌ۚ و]َمَا يَ[q:10381[جْ]حَدُ بِـَٔـايَ[n[ـٰ]تِن[o[َآ] إِلَّا كُلُّ خَتَّا[f:10608[رٍ ك]َف[p[ُو]رٍ","Қачон уларни тоғ каби тўлқин ўраб қолса, Аллоҳнинг динига ихлос этароқ, дуо қилурлар. Нажот бериб, уларни қуруқликка чиқарса, баъзилари тежамкор бўлур. Бизнинг оятларимизни фақат ўта хоин ва ўта кофирларгина инкор этурлар.",414,21],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ [h:2529[ٱ]تَّقُو[s[اْ] رَبَّكُمْ وَ[h:10609[ٱ]خْشَوْ[s[اْ] يَوْ[u:228[مًا ل]َّا يَ[q:6806[جْ]زِى وَالِدٌ ع[a:10610[َن و]َلَدِه[n[ِۦ] وَلَا مَوْلُودٌ هُوَ جَازٍ ع[a:10611[َن و]َالِدِه[n[ِۦ] شَيْــًٔا‌ۚ إِ[g[نّ]َ وَعْدَ [h:3149[ٱ]للَّهِ حَ[f:10612[قٌّ‌ۖ ف]َلَا تَغُرَّ[g[نّ]َكُمُ [h:10613[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَا وَلَا يَغُرَّ[g[نّ]َك[c:10614[ُم ب]ِ[h:32[ٱ]للَّهِ [h:10615[ٱ]لْغَر[p[ُو]رُ","Эй одамлар! Роббингизга тақво қилинг ва ота боласига фойда бера олмайдиган, бола отасига бирор нарсада фойда бергувчи бўлмайдиган кундан қўрқинг. Албатта, Аллоҳнинг ваъдаси ҳақдир. Бас, ҳаёти дунё сизни ғурурга кетказмасин. Ўта ғурурга кетказгувчи сизни Аллоҳ ила ғурурга кетказмасин.",414,21],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ عِ[f:719[ند]َهُ[n[ۥ] عِلْمُ [h:10616[ٱ][l[ل]سَّاعَةِ وَيُنَزِّلُ [h:10617[ٱ]لْغَيْثَ وَيَعْلَمُ مَا فِى [h:1733[ٱ]لْأَرْحَامِ‌ۖ وَمَا تَ[q:10618[دْ]رِى نَفْ[a:10619[سٌ م]َّاذَا تَكْسِبُ غَ[a:10620[دًا‌ۖ و]َمَا تَ[q:10618[دْ]رِى نَفْ[i:10621[سُۢ ب]ِأَىِّ أَرْ[f:10622[ضٍ ت]َمُوتُ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلِيمٌ خَب[p[ِي]رُۢ","Албатта, соат илми ёлғиз Аллоҳнинг ҳузуридадир. Ёмғирни У ёғдирур. Бачадонлардаги нарсани ҳам У билур. Ҳеч бир жон эртага нима касб қилишини билмас. Ҳеч бир жон қайси ерда ўлишини ҳам билмас. Албатта, Аллоҳ ўта билгувчи ва ўта хабардордир.",414,21]]},{"n":32,"ar":"السَّجۡدَةِ","en":"As-Sajda","uz":"Сажда","type":"Макка","ayahs":[["ا[m[لٓ][m[مٓ]","Алиф. Лам. Мийм.",415,21],["تَ[f:10623[نز]ِيلُ [h:10624[ٱ]لْكِتَ[n[ـٰ]بِ لَا رَيْبَ فِيهِ م[u:4772[ِن ر]َّبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Бу китобнинг нозил қилиниши, ҳеч шак-шубҳасиз, оламларнинг Робби томонидандир.",415,21],["أَمْ يَقُولُونَ [h:6061[ٱ]فْتَرَ[ٮٰ]هُ‌ۚ بَلْ هُوَ [h:8923[ٱ]لْحَقُّ م[u:770[ِن ر]َّبِّكَ لِتُ[f:4582[نذ]ِرَ قَوْ[a:10181[مًا م]ّ[o[َآ] أَتَ[n[ـٰ]ه[w:10182[ُم م]ّ[a:10183[ِن ن]َّذِي[a:10184[رٍ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ لَعَلَّهُمْ يَهْتَد[p[ُو]نَ","Ёки, унинг ўзи тўқиб олган, дейдиларми?! Йўқ! У сендан олдин ўзларига ҳеч огоҳлантиргувчи келмаган қавмни огоҳлантиришинг учун Роббингдан ҳақдир. Шояд улар ҳидоят топсалар.",415,21],["ٱللَّهُ [h:4738[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّا[f:4739[مٍ ث]ُ[g[مّ]َ [h:156[ٱ]سْتَوَىٰ عَلَى [h:4740[ٱ]لْعَرْشِ‌ۖ مَا لَك[w:556[ُم م]ِّ[f:3136[ن د]ُونِه[n[ِۦ] م[a:557[ِن و]َلِ[a:558[ىٍّ و]َلَا شَفِيعٍ‌ۚ أَفَلَا تَتَذَكَّر[p[ُو]نَ","Аллоҳ осмонлару ерни ва улар орасидаги нарсаларни олти кунда яратиб, сўнгра аршни эгаллган зотдир. Сиз учун ундан ўзга дўст ҳам, шафоатчи ҳам йўқдир. Ахир, эсламайсизларми?!",415,21],["يُدَبِّرُ [h:5940[ٱ]لْأَمْرَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ إِلَى [h:5136[ٱ]لْأَرْضِ ثُ[g[مّ]َ يَعْرُجُ إِلَيْهِ فِى يَوْ[f:10625[مٍ ك]َانَ مِ[q:10626[قْ]دَارُهُ[o[ۥٓ] أَلْفَ سَنَ[a:9062[ةٍ م]ِّ[g[مّ]َا تَعُدّ[p[ُو]نَ","У зот осмондан ергача барча ишнинг тадбирини қилур. Сўнгра ўша миқдорини сиз санаётган ҳисобда минг йилга тенг бўлган кунда Унга чиқар.",415,21],["ذ[n[َٲ]لِكَ عَ[n[ـٰ]لِمُ [h:4186[ٱ]لْغَيْبِ وَ[h:4187[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ [h:10627[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Ана шу Зот ғойибнию ҳозирни билгувчи, азизу раҳиймдир.",415,21],["ٱلَّذ[o[ِىٓ] أَحْسَنَ كُلَّ شَىْءٍ خَلَقَهُ[n[ۥ]‌ۖ وَبَدَأَ خَلْقَ [h:10628[ٱ]لْإِ[f:7874[نس]َ[n[ـٰ]نِ مِ[f:3917[ن ط][p[ِي]نٍ","У Ўзи яратган ҳар бир нарсани гўзал этган ва инсонни яратишни лойдан бошлаган зотдир.",415,21],["ثُ[g[مّ]َ جَعَلَ نَسْلَهُ[n[ۥ] مِ[f:9144[ن س]ُلَ[n[ـٰ]لَ[a:9145[ةٍ م]ّ[a:840[ِن م]ّ[o[َا]ٓ[a:10629[ءٍ م]َّه[p[ِي]نٍ","Сўнгра унинг наслини ҳақир бир сувдан ажраб чиқадиган қилди.",415,21],["ثُ[g[مّ]َ سَوَّ[n[ٮٰ]هُ وَنَفَخَ فِيهِ م[u:10630[ِن ر]ُّوحِه[n[ِۦ]‌ۖ وَجَعَلَ لَكُمُ [h:7518[ٱ][l[ل]سَّمْعَ وَ[h:6037[ٱ]لْأَ[q:6037[بْ]صَ[n[ـٰ]رَ وَ[h:7519[ٱ]لْأَفْــِٔدَةَ‌ۚ قَلِيل[a:4583[اً م]َّا تَشْكُر[p[ُو]نَ","Сўнгра уни ростлади ва унинг ичига Ўз руҳидан пуфлади. У сизларга қулоқ, кўзлар ва диллар пайдо қилди. Камдан-кам шукр қилурсизлар.",415,21],["وَقَال[o[ُوٓ][s[اْ] أَءِذَا ضَلَلْنَا فِى [h:44[ٱ]لْأَرْضِ أَءِ[g[نّ]َا لَفِى خَلْ[f:6887[قٍ ج]َدِي[i:10631[دِۭ‌ۚ ب]َلْ ه[c:10632[ُم ب]ِلِق[o[َا]ٓءِ رَبِّهِمْ كَ[n[ـٰ]فِر[p[ُو]نَ","Улар: «Биз ер остида йўқ бўлиб кетгач ҳам, яна янгитдан яратиламизми?!» дерлар. Йўқ! Улар Роббиларига рўбарў бўлишни инкор қилгувчилардир.",415,21],["۞ قُلْ يَتَوَفَّ[n[ـٰ]ك[w:10633[ُم م]َّلَكُ [h:10634[ٱ]لْمَوْتِ [h:10635[ٱ]لَّذِى وُكِّلَ بِكُمْ ثُ[g[مّ]َ إِلَىٰ رَبِّكُمْ تُرْجَع[p[ُو]نَ","Сен: «Сизларга вакил қилинган ўлим фариштаси жонингизни оладир. Сўнгра Роббингизга қайтарилурсиз», деб айт.",415,21],["وَلَوْ تَرَ[o[ىٰٓ] إِذِ [h:10636[ٱ]لْمُ[q:5255[جْ]رِمُونَ نَاكِسُو[s[اْ] رُءُوسِهِمْ عِ[f:264[ند]َ رَبِّهِمْ رَبَّن[o[َآ] أَ[q:10637[بْ]صَرْنَا وَسَمِعْنَا فَ[h:10638[ٱ]رْجِعْنَا نَعْمَلْ صَ[n[ـٰ]لِحًا إِ[g[نّ]َا مُوقِن[p[ُو]نَ","Гуноҳкорларнинг Роббилари ҳузурида бошларини эгиб туриб:»Эй Роббимиз, кўрдик, эшитдик. Бас, бизни ортга қайтар, яхши амал қиламиз. Албатта, биз ишониб етдик«, дейишларини кўрсанг эди.",416,21],["وَلَوْ شِئْنَا لَأَتَيْنَا كُلَّ نَفْسٍ هُدَ[n[ٮٰ]هَا وَلَ[n[ـٰ]كِنْ حَقَّ [h:10639[ٱ]لْقَوْلُ مِ[g[نّ]ِى لَأَمْلَأَ[g[نّ]َ جَهَ[g[نّ]َمَ مِنَ [h:6531[ٱ]لْجِ[g[نّ]َةِ وَ[h:824[ٱ][l[ل][g[نّ]َاسِ أَ[q:825[جْ]مَع[p[ِي]نَ","Агар хоҳлаганимизда, ҳар бир жонга ўз ҳидоятини берар эдик. Лекин мендан: «Албатта, жаҳаннамни жинлар ва одамларни жамлаб тўлдираман», деган сўз ҳақ бўлди.",416,21],["فَذُوقُو[s[اْ] بِمَا نَسِيتُمْ لِق[o[َا]ٓءَ يَوْمِكُمْ هَ[n[ـٰ]ذ[o[َآ] إِ[g[نّ]َا نَسِينَ[n[ـٰ]كُمْ‌ۖ وَذُوقُو[s[اْ] عَذَابَ [h:6085[ٱ]لْخُلْدِ بِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","«Бас, тотиб кўринглар, ушбу кунингизда учрашувни унутганингиз туфайли Биз ҳам сизни унутдик. Қилиб ўтган амалларингиз туфайли мангу азобни тотинг!» дейилур.",416,21],["إِ[g[نّ]َمَا يُؤْمِنُ بِـَٔـايَ[n[ـٰ]تِنَا [h:10640[ٱ]لَّذِينَ إِذَا ذُكِّرُو[s[اْ] بِهَا خَرُّو[s[اْ] سُجَّ[a:10641[دًا و]َسَبَّحُو[s[اْ] بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُ[p[و]نَ ۩","Албатта, Бизнинг оятларимизга уларла эслатма берилганда саждага йиқиладиган, Роббиларига ҳамд ила тасбиҳ айтадиган ва мутакаббирлик қилмайдиганларгина иймон келтирарлар.",416,21],["تَتَجَافَىٰ جُنُوبُهُمْ عَنِ [h:10642[ٱ]لْمَضَاجِعِ يَ[q:1240[دْ]عُونَ رَبَّهُمْ خَوْ[a:4752[فًا و]َطَمَ[a:10643[عًا و]َمِ[g[مّ]َا رَزَ[q:15[قْ]نَ[n[ـٰ]هُمْ يُ[f:16[نف]ِق[p[ُو]نَ","Уларнинг ёнбошлари ётар жойдан йироқ бўлур. Улар Роббиларига қўрқув ва умидворлик ила дуо қилурлар ва ўзларига ризқ қилиб берган нарсаларимиздан инфоқ қилурлар.",416,21],["فَلَا تَعْلَمُ نَفْ[a:10644[سٌ م]ّ[o[َآ] أُخْفِىَ لَه[w:1812[ُم م]ِّ[f:10645[ن ق]ُرَّةِ أَعْيُ[f:10646[نٍ ج]َز[o[َا]ٓ[i:3537[ءَۢ ب]ِمَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Бас, ҳеч бир жон ўзлари учун қилиб ўтган амаллари мукофотига беркитиб қўйилган кўз қувончларини билмас.",416,21],["أَفَمَ[f:6273[ن ك]َانَ مُؤْمِ[f:10647[نًا ك]َمَ[f:10648[ن ك]َانَ فَاسِ[u:10649[قًا‌ۚ ل]َّا يَسْتَوُ[p[ۥ]نَ","Ахир, мўмин бўлган одам фосиқ бўлган одамдек бўладими?! Тенг бўлмаслар.",416,21],["أَ[g[مّ]َا [h:10650[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ فَلَهُمْ جَ[g[نّ]َ[n[ـٰ]تُ [h:10651[ٱ]لْمَأْوَىٰ نُزُل[i:10652[اَۢ ب]ِمَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Ҳа, иймон келтириб, яхши амалларни қилганларга, бас, уларга қилиб ўтган амаллари учун жаннатул маъво манзилдир.",416,21],["وَأَ[g[مّ]َا [h:138[ٱ]لَّذِينَ فَسَقُو[s[اْ] فَمَأْوَ[n[ٮٰ]هُمُ [h:10653[ٱ][l[ل][g[نّ]َارُ‌ۖ كُلَّم[o[َآ] أَرَاد[o[ُوٓ][s[اْ] أ[a:3533[َن ي]َخْرُجُو[s[اْ] مِنْه[o[َآ] أُعِيدُو[s[اْ] فِيهَا وَقِيلَ لَهُمْ ذُوقُو[s[اْ] عَذَابَ [h:1110[ٱ][l[ل][g[نّ]َارِ [h:10654[ٱ]لَّذِى كُ[f:100[نت][c:6084[ُم ب]ِه[n[ِۦ] تُكَذِّب[p[ُو]نَ","Аммо фосиқлик қилганлар эса, бас, уларнинг жойлари дўзахдир. Ҳар қачон ундан чиқмоқни ирода қилсалар, унга қайтарилурлар ва уларга: «Ўзингиз ёлғонга чиқарган дўзахнинг азобини тотинг», дейилур.",416,21],["وَلَنُذِيقَ[g[نّ]َه[w:10655[ُم م]ِّنَ [h:503[ٱ]لْعَذَابِ [h:10656[ٱ]لْأَ[q:5116[دْ]نَىٰ دُونَ [h:10657[ٱ]لْعَذَابِ [h:10658[ٱ]لْأَكْبَرِ لَعَلَّهُمْ يَرْجِع[p[ُو]نَ","Албатта, Биз уларга буюк азобдан олдин яқин азобни тоттирамиз. Шоядки қайтсалар.",417,21],["وَمَنْ أَظْلَمُ مِ[g[مّ]َ[f:8134[ن ذ]ُكِّرَ بِـَٔـايَ[n[ـٰ]تِ رَبِّه[n[ِۦ] ثُ[g[مّ]َ أَعْرَضَ عَنْه[o[َآ‌ۚ] إِ[g[نّ]َا مِنَ [h:9627[ٱ]لْمُ[q:4093[جْ]رِمِينَ مُ[f:10659[نت]َقِم[p[ُو]نَ","Роббининг оятлари ила эслатилган, сўнгра улардан юз ўгирган одамдан ҳам золимроқ одам борми?! Албатта, Биз жиноятчилардан интиқом олгувчилармиз.",417,21],["وَلَقَ[q:341[دْ] ءَاتَيْنَا مُوسَى [h:257[ٱ]لْكِتَ[n[ـٰ]بَ فَلَا تَكُ[f:10023[ن ف]ِى مِرْيَ[a:10660[ةٍ م]ّ[u:10661[ِن ل]ِّق[o[َا]ٓئِه[n[ِۦ‌ۖ] وَجَعَلْنَ[n[ـٰ]هُ هُ[u:7658[دًى ل]ِّبَن[o[ِىٓ] إِسْر[o[َٲ]ٓء[p[ِي]لَ","Батаҳқиқ, Биз Мусога китобни бердик. Бас, сен унинг рўбарў бўлишидан шубҳада бўлма. Ва Биз уни Бани Исроилга ҳидоят қилиб бердик.",417,21],["وَجَعَلْنَا مِنْهُمْ أَئِ[g[مّ]َ[a:8805[ةً ي]َهْدُونَ بِأَمْرِنَا لَ[g[مّ]َا صَبَرُو[s[اْ‌ۖ] وَكَانُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا يُوقِن[p[ُو]نَ","Ва сабр қилган пайтларида улардан Бизнинг амримиз ила ҳидоятга бошлайдиган пешволар чиқардик. Улар Бизнинг оятларимизга аниқ ишонардилар.",417,21],["إِ[g[نّ]َ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ فِيمَا كَانُو[s[اْ] فِيهِ يَخْتَلِف[p[ُو]نَ","Албатта, Роббинг Ўзи қиёмат куни улар орасида ихтилоф қилган нарсалари тўғрисида ажрим қилур.",417,21],["أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِ[f:617[ن ق]َ[q:618[بْ]لِه[w:10662[ِم م]ِّنَ [h:6524[ٱ]لْقُرُونِ يَمْشُونَ فِى مَسَ[n[ـٰ]كِنِهِمْ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ]تٍ‌ۖ أَفَلَا يَسْمَع[p[ُو]نَ","Ўзларидан олдин ўтган, масканларида юриб турганлари қанчадан-қанча асрларини ҳалок қилганимиз уларни ҳидоятга бошламадими?! Албатта, бунда оят-белгилар бордир. Эшитмайдиларми?!",417,21],["أَوَلَمْ يَرَوْ[s[اْ] أَ[g[نّ]َا نَسُوقُ [h:10663[ٱ]لْم[o[َا]ٓءَ إِلَى [h:5136[ٱ]لْأَرْضِ [h:10664[ٱ]لْجُرُزِ فَنُخْرِجُ بِه[n[ِۦ] زَرْ[f:10665[عًا ت]َأْكُلُ مِنْهُ أَنْعَ[n[ـٰ]مُهُمْ وَأَ[f:10666[نف]ُسُهُمْ‌ۖ أَفَلَا يُ[q:60[بْ]صِر[p[ُو]نَ","Бизнинг сувни қуруқ ерга ҳайдаб у билан чорвалари ва ўзлари ейдиган зироатни чиқаришимизни билмайдиларми?! Ахир, кўрмайдиларми?!",417,21],["وَيَقُولُونَ مَتَىٰ هَ[n[ـٰ]ذَا [h:10667[ٱ]لْفَتْحُ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Улар: «Агар ростгўй бўлсаларингиз, бу фатҳ қачон бўлур?!» дерлар.",417,21],["قُلْ يَوْمَ [h:10668[ٱ]لْفَتْحِ لَا يَ[f:838[نف]َعُ [h:10539[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] إِيمَ[n[ـٰ]نُهُمْ وَلَا هُمْ يُ[f:826[نظ]َر[p[ُو]نَ","Сен: «Фатҳ куни куфр келтирганларга иймонлари манфаат бермас ва уларга муҳлат ҳам берилмас», деб айт.",417,21],["فَأَعْرِضْ عَنْهُمْ وَ[h:10669[ٱ][f:10669[نت]َظِرْ إِ[g[نّ]َه[w:10670[ُم م]ُّ[f:4557[نت]َظِر[p[ُو]نَ","Бас, улардан юз ўгир ва мунтазир бўл. Албатта, улар ҳам мунтазирдирлар.",417,21]]},{"n":33,"ar":"الأَحۡزَابِ","en":"Al-Ahzaab","uz":"Аҳзоб","type":"Мадина","ayahs":[["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ [h:10671[ٱ]تَّقِ [h:1125[ٱ]للَّهَ وَلَا تُطِعِ [h:9665[ٱ]لْكَ[n[ـٰ]فِرِينَ وَ[h:5724[ٱ]لْمُنَ[n[ـٰ]فِقِينَ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَلِيمًا حَكِيمًا","Эй Набий! Аллоҳга тақво қил ва кофиру мунофиқларга итоат этма! Албатта, Аллоҳ ўта олим ва ўта ҳикматли зотдир.",418,21],["وَ[h:9999[ٱ]تَّبِعْ مَا يُوحَ[o[ىٰٓ] إِلَيْكَ م[u:770[ِن ر]َّبِّكَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا","Ва ўзингга Роббингдан ваҳий қилинаётган нарсага эргаш. Албатта, Аллоҳ нима амал қилаётганингиздан хабардордир.",418,21],["وَتَوَكَّلْ عَلَى [h:412[ٱ]للَّهِ‌ۚ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ وَكِيلاً","Ва фақат Аллоҳга таваккал қил. Вакилликка Аллоҳ кофийдир.",418,21],["مَّا جَعَلَ [h:2556[ٱ]للَّهُ لِرَجُ[a:10672[لٍ م]ِّ[f:10673[ن ق]َلْبَيْنِ فِى جَوْفِه[n[ِۦ]‌ۚ وَمَا جَعَلَ أَزْو[n[َٲ]جَكُمُ [h:10674[ٱ]لَّ[o[ــٰٓ]ــِٔى تُظَ[n[ـٰ]هِرُونَ مِنْهُ[g[نّ]َ أُ[g[مّ]َهَ[n[ـٰ]تِكُمْ‌ۚ وَمَا جَعَلَ أَ[q:10675[دْ]عِي[o[َا]ٓءَكُمْ أَ[q:240[بْ]ن[o[َا]ٓءَكُمْ‌ۚ ذ[n[َٲ]لِكُمْ قَوْلُك[c:10676[ُم ب]ِأَفْو[n[َٲ]هِكُمْ‌ۖ وَ[h:72[ٱ]للَّهُ يَقُولُ [h:10677[ٱ]لْحَقَّ وَهُوَ يَهْدِى [h:10678[ٱ][l[ل]سَّب[p[ِي]لَ","Аллоҳ бирон кишининг ичида иккита қалб қилган эмасдир. Ўзларингиз зиҳор қилаётган хотинларингизни сиз учун она ҳам қилган эмас ва асранди болаларингизни сизга фарзанд ҳам қилган эмас. Буларингиз оғзингиз билан айтган гапларингиздир. Аллоҳ эса ҳақни айтур ва У тўғри йўлга ҳидоят қилур.",418,21],["ٱ[q:10679[دْ]عُوهُمْ لِأَب[o[َا]ٓئِهِمْ هُوَ أَ[q:1683[قْ]سَطُ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ‌ۚ فَإ[u:110[ِن ل]َّمْ تَعْلَم[o[ُوٓ][s[اْ] ءَاب[o[َا]ٓءَهُمْ فَإِخْو[n[َٲ]نُكُمْ فِى [h:1477[ٱ][l[ل]دِّينِ وَمَو[n[َٲ]لِيكُمْ‌ۚ وَلَيْسَ عَلَيْكُمْ جُنَا[f:3782[حٌ ف]ِيم[o[َآ] أَخْطَأْت[c:10680[ُم ب]ِه[n[ِۦ] وَلَ[n[ـٰ]ك[a:10681[ِن م]َّا تَعَ[g[مّ]َدَتْ قُلُوبُكُمْ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ غَفُو[u:2701[رًا ر]َّحِيمًا","Уларни ўз оталари номи билан чақиринглар. Ана шу Аллоҳнинг наздида тўғридир. Агар оталарини билмасангиз, улар сизнинг дин қардошларингиз ва дўстларингиздир. Билмасдан қилган хато нарсангиз учун сизга гуноҳ йўқ. Аммо дилдан қасд қилган бўлсангиз, Аллоҳ ўта мағфиратли ва ўта раҳмли зотдир.",418,21],["ٱ[l[ل][g[نّ]َبِىُّ أَوْلَىٰ بِ[h:3560[ٱ]لْمُؤْمِنِينَ مِنْ أَ[f:568[نف]ُسِهِمْ‌ۖ وَأَزْو[n[َٲ]جُهُ[o[ۥٓ] أُ[g[مّ]َهَ[n[ـٰ]تُهُمْ‌ۗ وَأُ[s[وْ]لُو[s[اْ] [h:5446[ٱ]لْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْ[f:5447[ضٍ ف]ِى كِتَ[n[ـٰ]بِ [h:1816[ٱ]للَّهِ مِنَ [h:3047[ٱ]لْمُؤْمِنِينَ وَ[h:5876[ٱ]لْمُهَ[n[ـٰ]جِرِينَ إِلّ[o[َآ] أَ[f:10682[ن ت]َفْعَل[o[ُوٓ][s[اْ] إِلَ[o[ىٰٓ] أَوْلِي[o[َا]ٓئِك[w:10683[ُم م]َّعْرُو[f:10684[فًا‌ۚ ك]َانَ ذ[n[َٲ]لِكَ فِى [h:818[ٱ]لْكِتَ[n[ـٰ]بِ مَسْطُورًا","Набий мўминлар учун ўзларидан кўра ҳақлидир. Унинг аёллари эса, уларнинг оналаридир. Аллоҳнинг Китобида қариндошлар бир-бирларига бошқа мўминлардан ва муҳожирлардан ҳақлидирлар. Фақат дўстларингизга яхшилик қилмоғингиз мустаснодир. Бу Китобда сатрлар ила битилмиш.",418,21],["وَإِذْ أَخَذْنَا مِنَ [h:2902[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ مِيثَ[n[ـٰ]قَهُمْ وَمِ[f:10685[نك]َ وَم[a:10686[ِن ن]ُّو[a:10687[حٍ و]َإِ[q:10311[بْ]ر[n[َٲ]هِيمَ وَمُوسَىٰ وَعِيسَى [h:3725[ٱ][q:3590[بْ]نِ مَرْيَمَ‌ۖ وَأَخَذْنَا مِنْه[w:3265[ُم م]ِّيثَ[n[ـٰ]قًا غَلِيظًا","Набийлардан аҳду паймонларини олганимизни эсла! Сендан, Нуҳдан, Иброҳимдан, Мусодан ва Ийсо ибн Марямдан ҳам. Биз улардан салмоқли аҳду паймон олдик.",419,21],["لِّيَسْــَٔلَ [h:10688[ٱ][l[ل]صَّ[n[ـٰ]دِقِينَ عَ[f:10689[ن ص]ِ[q:10690[دْ]قِهِمْ‌ۚ وَأَعَدَّ لِلْكَ[n[ـٰ]فِرِينَ عَذَابًا أَلِيمًا","содиқлардан садоқатлари ҳақида сўраш учун қилди. Ва кофирларга аламли азобни тайёрлаб қўйди.",419,21],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:3416[ٱ]ذْكُرُو[s[اْ] نِعْمَةَ [h:1154[ٱ]للَّهِ عَلَيْكُمْ إِذْ ج[o[َا]ٓءَتْكُمْ جُنُو[f:10691[دٌ ف]َأَرْسَلْنَا عَلَيْهِمْ رِي[a:10692[حًا و]َجُنُو[u:10693[دًا ل]َّمْ تَرَوْهَا‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ بِمَا تَعْمَلُونَ بَصِيرًا","Эй иймон келтирганлар! Аллоҳнинг сизга берган неъматини эсланг. Ўшанда устингизга лашкарлар келган эди. Бас, Биз уларнинг устига шамолни ва сиз кўрмаган лашкарларни юбордик. Аллоҳ нима қилаётганингизни яхши кўриб тургувчи эди.",419,21],["إِذْ ج[o[َا]ٓءُوك[w:10694[ُم م]ِّ[f:4142[ن ف]َوْقِكُمْ وَمِنْ أَسْفَلَ مِ[f:344[نك]ُمْ وَإِذْ زَاغَتِ [h:10695[ٱ]لْأَ[q:4305[بْ]صَ[n[ـٰ]رُ وَبَلَغَتِ [h:10696[ٱ]لْقُلُوبُ [h:10697[ٱ]لْحَنَاجِرَ وَتَظُ[g[نّ]ُونَ بِ[h:32[ٱ]للَّهِ [h:10698[ٱ][l[ل]ظُّنُونَا۟","Ўшанда улар сизнинг уст ва қуйи томонингиздан келган эдилар. Ўшанда кўзлар тиниб, жонлар ҳалқумга келган эди ва Аллоҳ ҳақида турли гумонлар қилардингиз.",419,21],["هُنَالِكَ [h:10699[ٱ][q:10700[بْ]تُلِىَ [h:10701[ٱ]لْمُؤْمِنُونَ وَزُلْزِلُو[s[اْ] زِلْزَال[f:10702[اً ش]َدِيدًا","Ана шунда мўминлар синовга дучор бўлдилар ва шиддатли ларзага тушдилар.",419,21],["وَإِذْ يَقُولُ [h:5376[ٱ]لْمُنَ[n[ـٰ]فِقُونَ وَ[h:37[ٱ]لَّذِينَ فِى قُلُوبِه[w:39[ِم م]َّرَ[a:10703[ضٌ م]َّا وَعَدَنَا [h:10704[ٱ]للَّهُ وَرَسُولُهُ[o[ۥٓ] إِلَّا غُرُورًا","Ўшанда мунофиқлар ва қалбларида касаллик борлар: «Аллоҳ ва Унинг Расули бизга ёлғондан бошқани ваъда қилмаган экан», дердилар.",419,21],["وَإِذْ قَالَ[d:10705[ت] طّ[o[َا]ٓئِفَ[a:2967[ةٌ م]ِّنْهُمْ يَ[o[ـٰٓ]أَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَ[h:9386[ٱ]رْجِعُو[s[اْ‌ۚ] وَيَسْتَــْٔذِنُ فَرِي[a:10706[قٌ م]ِّنْهُمُ [h:10707[ٱ][l[ل][g[نّ]َبِىَّ يَقُولُونَ إِ[g[نّ]َ بُيُوتَنَا عَوْرَ[a:10708[ةٌ و]َمَا هِىَ بِعَوْرَةٍ‌ۖ إ[a:10709[ِن ي]ُرِيدُونَ إِلَّا فِرَارًا","Ўшанда улардан бир тоифаси: «Эй Ясриб аҳли, бу ерда сизга туриш имкони йўқ. Бас, қайтинглар», деди. Улардан бир гуруҳлари Набийдан изн сўраб: «Уйларимиз очиқ-сочиқ қолган», дейдилар. Ҳолбуки, улар очиқ-сочиқ эмас. Улар қочишдан бошқани ирода қилмаслар.",419,21],["وَلَوْ دُخِلَتْ عَلَيْه[w:4082[ِم م]ِّنْ أَ[q:10710[قْ]طَارِهَا ثُ[g[مّ]َ سُئِلُو[s[اْ] [h:10711[ٱ]لْفِتْنَةَ لَأَتَوْهَا وَمَا تَلَبَّثُو[s[اْ] بِه[o[َآ] إِلَّا يَسِيرًا","Агар уларнинг устига у нинг ҳар тарафидан бостириб кирилса, сўнгра улардан фитна талаб қилинса, албатта, уни қилурлар. Ҳеч кечикмаслар. Магар озгинагина.",419,21],["وَلَقَ[q:341[دْ] كَانُو[s[اْ] عَ[n[ـٰ]هَدُو[s[اْ] [h:10712[ٱ]للَّهَ مِ[f:128[ن ق]َ[q:129[بْ]لُ لَا يُوَلُّونَ [h:10713[ٱ]لْأَ[q:2168[دْ]بَ[n[ـٰ]رَ‌ۚ وَكَانَ عَهْدُ [h:10714[ٱ]للَّهِ مَسْــُٔولاً","Ҳолбуки, улар бундан олдин ортга қараб қочмасликка Аллоҳга аҳд берган эдилар. Аллоҳга аҳд эса, масъулият бўлгандир.",419,21],["قُل لّ[a:10715[َن ي]َ[f:10716[نف]َعَكُمُ [h:10717[ٱ]لْفِرَارُ إِ[f:10718[ن ف]َرَرْت[w:10719[ُم م]ِّنَ [h:10720[ٱ]لْمَوْتِ أَوِ [h:10721[ٱ]لْقَتْلِ وَإِ[u:7848[ذًا ل]َّا تُمَتَّعُونَ إِلَّا قَلِيلاً","Сен: «Қочиш сизга ҳеч қандай фойда бермас. Демак, агар ўлимдан ёки қатл бўлишдан қочсангиз ҳам, жуда оз ҳузурланасиз, холос», деб айт.",420,21],["قُلْ مَ[f:1375[ن ذ]َا [h:1376[ٱ]لَّذِى يَعْصِمُك[w:10722[ُم م]ِّنَ [h:321[ٱ]للَّهِ إِنْ أَرَادَ بِكُمْ س[o[ُو]ٓءًا أَوْ أَرَادَ بِكُمْ رَحْمَ[a:10723[ةً‌ۚ و]َلَا يَجِدُونَ لَه[w:1812[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ وَلِي[a:3006[ًّا و]َلَا نَصِيرًا","Сен: «Агар сизга Аллоҳ ёмонликни ирода қилса ёки сизга раҳматни ирода қилса, сизларни ундан тўсадиган ким бор?!» деб айт. Улар ўзларига Аллоҳдан ўзга дўст ва ёрдам бергувчи топа олмаслар.",420,21],["۞ قَ[q:298[دْ] يَعْلَمُ [h:2880[ٱ]للَّهُ [h:10724[ٱ]لْمُعَوِّقِينَ مِ[f:344[نك]ُمْ وَ[h:10725[ٱ]لْق[o[َا]ٓئِلِينَ لِإِخْو[n[َٲ]نِهِمْ هَلُ[g[مّ]َ إِلَيْنَا‌ۖ وَلَا يَأْتُونَ [h:10726[ٱ]لْبَأْسَ إِلَّا قَلِيلاً","Батаҳқиқ, Аллоҳ ичингиздаги тўсиқлик қилгувчиларни ҳам ва ўз биродарларига: «Биз томон келинг», деювчиларни ҳам билур. Улар жангга келмаслар, илло, озгина келурлар.",420,21],["أَشِحَّةً عَلَيْكُمْ‌ۖ فَإِذَا ج[o[َا]ٓءَ [h:10727[ٱ]لْخَوْفُ رَأَيْتَهُمْ يَ[f:1141[نظ]ُرُونَ إِلَيْكَ تَدُورُ أَعْيُنُهُمْ كَ[h:1506[ٱ]لَّذِى يُغْشَىٰ عَلَيْهِ مِنَ [h:10720[ٱ]لْمَوْتِ‌ۖ فَإِذَا ذَهَبَ [h:10728[ٱ]لْخَوْفُ سَلَقُوك[c:10729[ُم ب]ِأَلْسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى [h:10730[ٱ]لْخَيْرِ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَمْ يُؤْمِنُو[s[اْ] فَأَحْبَطَ [h:10731[ٱ]للَّهُ أَعْمَ[n[ـٰ]لَهُمْ‌ۚ وَكَانَ ذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ يَسِيرًا","Сизларга нисбатан бахиллик қилган ҳолларида. Бас, хавф келган чоғда уларнинг сенга ўлим талвасасидаги кишига ўхшаб, кўзлари айланиб назар солишларини кўрасан. Бас, хавф кетганда эса, яхшиликка очкўзлик қилиб, сизларга ўткир тиллар ила озор берурлар. Ана ўшалар иймон келтирмаганлардир. Бас, Аллоҳ амалларини беҳуда кетказди. Бу эса, Аллоҳ учун осон эди.",420,21],["يَحْسَبُونَ [h:10732[ٱ]لْأَحْزَابَ لَمْ يَذْهَبُو[s[اْ‌ۖ] وَإ[a:10733[ِن ي]َأْتِ [h:10734[ٱ]لْأَحْزَابُ يَوَدُّو[s[اْ] لَوْ أَ[g[نّ]َه[c:10735[ُم ب]َادُونَ فِى [h:10736[ٱ]لْأَعْرَابِ يَسْــَٔلُونَ عَنْ أَ[i:10737[نۢب][o[َا]ٓئِكُمْ‌ۖ وَلَوْ كَانُو[s[اْ] فِيك[w:5627[ُم م]َّا قَ[n[ـٰ]تَل[o[ُوٓ][s[اْ] إِلَّا قَلِيلاً","Улар аҳзобларни кетмаган деб ҳисобларлар. Агар аҳзоблар яна келсалар, улар аъробийлар ичида, чўлда бўлиб, сизнинг хабарингизни сўраб туришни орзу қилурлар. Агар сизнинг ичингизда бўлганларида ҳам, камдан-кам жанг қилган бўлур эдилар.",420,21],["لَّقَ[q:2389[دْ] كَانَ لَكُمْ فِى رَسُولِ [h:5744[ٱ]للَّهِ أُسْوَةٌ حَسَنَ[u:10738[ةٌ ل]ِّمَ[f:10739[ن ك]َانَ يَرْجُو[s[اْ] [h:10740[ٱ]للَّهَ وَ[h:10741[ٱ]لْيَوْمَ [h:10742[ٱ]لْأَخِرَ وَذَكَرَ [h:10743[ٱ]للَّهَ كَثِيرًا","Батаҳқиқ, сизлар учун–Аллоҳдан ва охират кунидан умидвор бўлганлар учун ва Аллоҳни кўп зикр қилганлар учун Расулуллоҳда гўзал ўрнак бор эди.",420,21],["وَلَ[g[مّ]َا رَءَا [h:10744[ٱ]لْمُؤْمِنُونَ [h:10745[ٱ]لْأَحْزَابَ قَالُو[s[اْ] هَ[n[ـٰ]ذَا مَا وَعَدَنَا [h:10704[ٱ]للَّهُ وَرَسُولُهُ[n[ۥ] وَصَدَقَ [h:10746[ٱ]للَّهُ وَرَسُولُهُ[n[ۥ]‌ۚ وَمَا زَادَهُمْ إِلّ[o[َآ] إِيمَ[n[ـٰ][a:10747[نًا و]َتَسْلِيمًا","Мўминлар аҳзобларни кўрганларида: «Бу бизга Аллоҳ ва Унинг Расули ваъда қилган нарсадир. Аллоҳ ва Унинг Расули рост сўзларлар», дедилар. Бу уларга иймон ва таслимдан бошқа нарсани зиёда этмади.",420,21],["مِّنَ [h:3047[ٱ]لْمُؤْمِنِينَ رِجَا[f:10748[لٌ ص]َدَقُو[s[اْ] مَا عَ[n[ـٰ]هَدُو[s[اْ] [h:10712[ٱ]للَّهَ عَلَيْهِ‌ۖ فَمِنْه[w:1456[ُم م]َّ[f:10749[ن ق]َضَىٰ نَحْبَهُ[n[ۥ] وَمِنْه[w:1106[ُم م]ّ[a:10750[َن ي]َ[f:10751[نت]َظِرُ‌ۖ وَمَا بَدَّلُو[s[اْ] تَ[q:10752[بْ]دِيلاً","Мўминлардан Аллоҳга берган ваъдаларига содиқ қолган кишилар бордир. Бас, улардан баъзилари ажалини топди. Баъзилари эса, интизор бўлиб турибди. Улар бирор нарсани алмаштирмадилар.",421,21],["لِّيَ[q:5945[جْ]زِىَ [h:7189[ٱ]للَّهُ [h:10753[ٱ][l[ل]صَّ[n[ـٰ]دِقِينَ بِصِ[q:10754[دْ]قِهِمْ وَيُعَذِّبَ [h:10755[ٱ]لْمُنَ[n[ـٰ]فِقِينَ إِ[f:364[ن ش][o[َا]ٓءَ أَوْ يَتُوبَ عَلَيْهِمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ غَفُو[u:2701[رًا ر]َّحِيمًا","Аллоҳ содиқларни садоқатлари сабабидан мукофотлаш учун ва мунофиқларни Аллоҳ хоҳласа, азоблаши ёки тавбасини қабул қилиши учундир. Албатта, Аллоҳ ўта мағфиратли ва ўта раҳмлидир.",421,21],["وَرَدَّ [h:10756[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِغَيْظِهِمْ لَمْ يَنَالُو[s[اْ] خَيْ[a:10757[رًا‌ۚ و]َكَفَى [h:10758[ٱ]للَّهُ [h:5717[ٱ]لْمُؤْمِنِينَ [h:10759[ٱ]لْقِتَالَ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ قَوِيًّا عَزِيزًا","Ва Аллоҳ куфр келтирганларни ғазаблари ила ортларига қайтарди. Улар ҳеч бир яхшиликка эриша олмадилар. Мўминлар учун урушда Аллоҳнинг Ўзи кифоя қилди. Ва Аллоҳ кучли ва азиз зотдир.",421,21],["وَأَ[f:91[نز]َلَ [h:10760[ٱ]لَّذِينَ ظَ[n[ـٰ]هَرُوه[w:10761[ُم م]ِّنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ مِ[f:10762[ن ص]َيَاصِيهِمْ وَقَذَفَ فِى قُلُوبِهِمُ [h:10763[ٱ][l[ل]رُّعْبَ فَرِي[f:10764[قًا ت]َ[q:429[قْ]تُلُونَ وَتَأْسِرُونَ فَرِيقًا","Ва У зот уларга ёрдам берган аҳли китоблардан бўлганларни қўрғонларидан туширди ва қалбларига қўрқинч солди. Бир гуруҳини ўлдирурсизлар ва бир гуруҳини асир олурсизлар.",421,21],["وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَ[n[ـٰ]رَهُمْ وَأَمْو[n[َٲ]لَهُمْ وَأَرْ[u:10765[ضًا ل]َّمْ تَطَــُٔوهَا‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:10766[َىْءٍ ق]َدِيرًا","Ва сизларга уларнинг ерини, ҳовли-жойларини, молу мулкларини ва қадамингиз етмаган ерни мерос қилиб берди. Аллоҳ ҳар бир нарсага қодир зотдир.",421,21],["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ قُل لِّأَزْو[n[َٲ]جِكَ إِ[f:10767[ن ك]ُ[f:10768[نت]ُ[g[نّ]َ تُرِ[q:10769[دْ]نَ [h:10770[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُ[g[نّ]َ وَأُسَرِّحْكُ[g[نّ]َ سَرَا[f:10771[حًا ج]َمِيلاً","Эй Набий, жуфти ҳалолларингга: «Агар бу дунё ҳаётини ва унинг зийнатини ирода қилсангиз, келинглар, сизларни баҳраманд қилай ва чиройли бўшатиш ила бўшатиб қўяй.",421,21],["وَإِ[f:10772[ن ك]ُ[f:10768[نت]ُ[g[نّ]َ تُرِ[q:10769[دْ]نَ [h:10773[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] وَ[h:10774[ٱ][l[ل]دَّارَ [h:10775[ٱ]لْأَخِرَةَ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ أَعَدَّ لِلْمُحْسِنَ[n[ـٰ]تِ مِ[f:10776[نك]ُ[g[نّ]َ أَ[q:2795[جْ]رًا عَظِيمًا","Агар Аллоҳни ва Унинг Расулини ва охират диёрини ирода қиладиган бўлсангиз, бас, албатта, Аллоҳ сизлардан гўзал амал қилгувчиларга улуғ ажрни тайёрлаб қўйган», деб айт.",421,21],["يَ[n[ـٰ]نِس[o[َا]ٓءَ [h:10777[ٱ][l[ل][g[نّ]َبِىِّ م[a:8547[َن ي]َأْتِ مِ[f:10776[نك]ُ[g[نّ]َ بِفَ[n[ـٰ]حِشَ[a:2665[ةٍ م]ُّبَيِّنَ[a:10778[ةٍ ي]ُضَ[n[ـٰ]عَفْ لَهَا [h:10779[ٱ]لْعَذَابُ ضِعْفَيْنِ‌ۚ وَكَانَ ذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ يَسِيرًا","Эй Набийнинг аёллари! Сиздан ким очиқ гуноҳ қилса, унга бериладиган азоб икки марта кўпайтирилур. Бу эса, Аллоҳ учун осон бўлган ишдир.",421,21],["۞ وَم[a:10780[َن ي]َ[q:10781[قْ]نُتْ مِ[f:10776[نك]ُ[g[نّ]َ لِلَّهِ وَرَسُولِه[n[ِۦ] وَتَعْمَلْ صَ[n[ـٰ]لِ[a:10782[حًا ن]ُّؤْتِه[o[َآ] أَ[q:10783[جْ]رَهَا مَرَّتَيْنِ وَأَعْتَ[q:2782[دْ]نَا لَهَا رِزْ[f:10784[قًا ك]َرِيمًا","Сизлардан ким Аллоҳга ва Унинг Расулига мудом итоатда бўлса ва яхши амал қилса, унинг ажрини икки марта берамиз ва унинг учун гўзал ризқни тайёрлаганмиз.",422,22],["يَ[n[ـٰ]نِس[o[َا]ٓءَ [h:10777[ٱ][l[ل][g[نّ]َبِىِّ لَسْتُ[g[نّ]َ كَأَحَ[a:10785[دٍ م]ِّنَ [h:1769[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءِۚ إِنِ [h:10786[ٱ]تَّقَيْتُ[g[نّ]َ فَلَا تَخْضَعْنَ بِ[h:7118[ٱ]لْقَوْلِ فَيَ[q:10787[طْ]مَعَ [h:10788[ٱ]لَّذِى فِى قَلْبِه[n[ِۦ] مَرَ[a:10789[ضٌ و]َقُلْنَ قَوْل[a:1331[اً م]َّعْرُوفًا","Эй Набийнинг аёллари! Сизлар аёллардан бирортаси каби эмассиз. Агар тақво қилсангиз, майин сўз қилманг, яна қалбида касали бор бўлган тамаъ қилиб юрмасин. Гапирганда яхши гапни гапиринглар.",422,22],["وَقَرْنَ فِى بُيُوتِكُ[g[نّ]َ وَلَا تَبَرَّ[q:10790[جْ]نَ تَبَرُّجَ [h:10791[ٱ]لْجَ[n[ـٰ]هِلِيَّةِ [h:10792[ٱ]لْأُولَىٰۖ وَأَقِمْنَ [h:10793[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتِينَ [h:10794[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَأَطِعْنَ [h:10795[ٱ]للَّهَ وَرَسُولَهُۚ[o[ۥٓ] إِ[g[نّ]َمَا يُرِيدُ [h:976[ٱ]للَّهُ لِيُذْهِبَ عَ[f:10796[نك]ُمُ [h:10797[ٱ][l[ل]رِّ[q:4401[جْ]سَ أَهْلَ [h:6424[ٱ]لْبَيْتِ وَيُطَهِّرَكُمْ تَ[q:10798[طْ]هِيرًا","Виқор билан уйингизда ўтиринг. Илгариги жоҳилиятнинг очиқ-сочиқлиги каби очиқ-сочиқ юрманг. Намозни тўкис адо этинг, закот беринг, Аллоҳга ва унинг Расулига итоат қилинг. Албатта, Аллоҳ сиздан кирни кетказиб, бутунлай поклашни хоҳлайди, эй аҳли байт!",422,22],["وَ[h:9999[ٱ]ذْكُرْنَ مَا يُتْلَىٰ فِى بُيُوتِكُ[g[نّ]َ مِنْ ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ وَ[h:1302[ٱ]لْحِكْمَةِۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ لَطِيفًا خَبِيرًا","Ва уйларингизда тиловат қилинаётган Аллоҳнинг оятларини ва ҳикматни эсланг. Албатта, Аллоҳ ўта латиф ва ўта хабардор бўлган зотдир.",422,22],["إِ[g[نّ]َ [h:10799[ٱ]لْمُسْلِمِينَ وَ[h:10800[ٱ]لْمُسْلِمَ[n[ـٰ]تِ وَ[h:10801[ٱ]لْمُؤْمِنِينَ وَ[h:5718[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ وَ[h:1793[ٱ]لْقَ[n[ـٰ]نِتِينَ وَ[h:10802[ٱ]لْقَ[n[ـٰ]نِتَ[n[ـٰ]تِ وَ[h:1792[ٱ][l[ل]صَّ[n[ـٰ]دِقِينَ وَ[h:10803[ٱ][l[ل]صَّ[n[ـٰ]دِقَ[n[ـٰ]تِ وَ[h:918[ٱ][l[ل]صَّ[n[ـٰ]بِرِينَ وَ[h:10804[ٱ][l[ل]صَّ[n[ـٰ]بِر[n[َٲ]تِ وَ[h:10805[ٱ]لْخَ[n[ـٰ]شِعِينَ وَ[h:10806[ٱ]لْخَ[n[ـٰ]شِعَ[n[ـٰ]تِ وَ[h:10807[ٱ]لْمُتَصَدِّقِينَ وَ[h:10808[ٱ]لْمُتَصَدِّقَ[n[ـٰ]تِ وَ[h:10809[ٱ][l[ل]صَّ[o[ـٰٓ]ئِمِينَ وَ[h:10810[ٱ][l[ل]صَّ[o[ـٰٓ]ئِمَ[n[ـٰ]تِ وَ[h:10811[ٱ]لْحَ[n[ـٰ]فِظِينَ فُرُوجَهُمْ وَ[h:10812[ٱ]لْحَ[n[ـٰ]فِظَ[n[ـٰ]تِ وَ[h:10813[ٱ][l[ل]ذّ[n[َٲ]كِرِينَ [h:10814[ٱ]للَّهَ كَثِي[a:10815[رًا و]َ[h:10816[ٱ][l[ل]ذّ[n[َٲ]كِر[n[َٲ]تِ أَعَدَّ [h:5775[ٱ]للَّهُ لَه[w:10817[ُم م]َّغْفِرَ[a:10818[ةً و]َأَ[q:10819[جْ]رًا عَظِيمًا","Албатта, муслимлар ва муслималар, мўминлар ва мўминалар, давомли итоаткор эркаклар ва давомли итоаткор аёллар, садоқатли эркаклар ва садоқатли аёллар, сабрли эркаклар ва сабрли аёллар, тавозуъли эркаклар ва тавозуъли аёллар, садақа қилгувчи эркаклар ва садақа қилгувчи аёллар, рўза тутгувчи эркаклар ва рўза тутгувчи аёллар, фаржларини сақловчи эркаклар ва сақловчи аёллар, Аллоҳни кўп зикр қилгувчи эркаклар ва зикр қилгувчи аёллар–ўшаларга Аллоҳ мағфиратни ва улуғ ажрни тайёрлаб қўйгандир.",422,22],["وَمَا كَانَ لِمُؤْمِ[a:10820[نٍ و]َلَا مُؤْمِنَةٍ إِذَا قَضَى [h:10821[ٱ]للَّهُ وَرَسُولُهُ[o[ۥٓ] أَمْرًا أ[a:3312[َن ي]َكُونَ لَهُمُ [h:10226[ٱ]لْخِيَرَةُ مِنْ أَمْرِهِمْۗ وَم[a:2634[َن ي]َعْصِ [h:2635[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] فَقَ[q:563[دْ] ضَلَّ ضَلَ[n[ـٰ]ل[a:10822[اً م]ُّبِينًا","Ҳеч бир мўмин эркак ва ҳеч бир мўмина аёл учун Аллоҳ ва Унинг Расули бир ишга ҳукм қилганида, ўз ишларини ўзларича ихтиёр қилмоқ йўқ. Ким Аллоҳга ва Унинг Расулига осий бўлса, бас, батаҳқиқ, очиқ адашиш-ла адашибди.",423,22],["وَإِذْ تَقُولُ لِلَّذ[o[ِىٓ] أَنْعَمَ [h:2900[ٱ]للَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَ[h:10823[ٱ]تَّقِ [h:10824[ٱ]للَّهَ وَتُخْفِى فِى نَفْسِكَ مَا [h:10825[ٱ]للَّهُ مُ[q:10826[بْ]دِيهِ وَتَخْشَى [h:10827[ٱ][l[ل][g[نّ]َاسَ وَ[h:72[ٱ]للَّهُ أَحَقُّ أَ[f:10828[ن ت]َخْشَ[n[ـٰ]هُۖ فَلَ[g[مّ]َا قَضَىٰ زَيْ[a:10829[دٌ م]ِّنْهَا وَطَ[f:10830[رًا ز]َوَّ[q:10831[جْ]نَ[n[ـٰ]كَهَا لِكَىْ لَا يَكُونَ عَلَى [h:2329[ٱ]لْمُؤْمِنِينَ حَرَ[f:10832[جٌ ف][o[ِىٓ] أَزْو[n[َٲ]جِ أَ[q:10833[دْ]عِي[o[َا]ٓئِهِمْ إِذَا قَضَوْ[s[اْ] مِنْهُ[g[نّ]َ وَطَ[a:10834[رًاۚ و]َكَانَ أَمْرُ [h:2832[ٱ]للَّهِ مَفْعُولاً","Эсла, сен Аллоҳ неъмат берган ва сен ҳам неъмат берган шахсга: «Жуфтингни ўзинг ила тутиб тур ва Аллоҳга тақво қил», дер эдинг. Ва ичингда Аллоҳ ошкор қилгувчи бўлган нарсани махфий тутардинг ва одамлардан қўрқардинг, ҳолбуки, Аллоҳдан қўрқмоғинг ҳақлироқ эди. Қачонки Зайд ундан ўз ҳожатини адо этгач, Биз сени унга уйлантирдик. Токи мўминларга ўз асранди болалари хотинларида улардан ҳожатларини адо қилишгач, танглик бўлмасин, деб. Ва Аллоҳнинг амри амал қилиниши лозим бўлгандир.",423,22],["مَّا كَانَ عَلَى [h:5875[ٱ][l[ل][g[نّ]َبِىِّ مِنْ حَرَ[f:10835[جٍ ف]ِيمَا فَرَضَ [h:10836[ٱ]للَّهُ لَهُۖ[n[ۥ] سُ[g[نّ]َةَ [h:10837[ٱ]للَّهِ فِى [h:6320[ٱ]لَّذِينَ خَلَوْ[s[اْ] مِ[f:128[ن ق]َ[q:129[بْ]لُۚ وَكَانَ أَمْرُ [h:2832[ٱ]للَّهِ قَدَ[a:10838[رًا م]َّ[q:10839[قْ]دُورًا","Набийга Аллоҳ унга фарз қилган нарсада бирон танглик бўлмас. Бу олдин ўтганлар ҳақида ҳам Аллоҳ тутган йўлдир. Аллоҳнинг амри белгиланган қадар бўлди.",423,22],["ٱلَّذِينَ يُبَلِّغُونَ رِسَ[n[ـٰ]لَ[n[ـٰ]تِ [h:10840[ٱ]للَّهِ وَيَخْشَوْنَهُ[n[ۥ] وَلَا يَخْشَوْنَ أَحَدًا إِلَّا [h:416[ٱ]للَّهَۗ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ حَسِيبًا","Улар Аллоҳнинг элчилигини етказадиган, Ундангина қўрқадиган, Аллоҳдан бошқа ҳеч кимдан қўрқмайдиган зотлардир. Аллоҳнинг Ўзи ҳисоб қилгувчиликка кифоядир.",423,22],["مَّا كَانَ مُحَ[g[مّ]َدٌ أَب[o[َآ] أَحَ[a:1710[دٍ م]ّ[u:1674[ِن ر]ِّجَالِكُمْ وَلَ[n[ـٰ]ك[u:10841[ِن ر]َّسُولَ [h:3273[ٱ]للَّهِ وَخَاتَمَ [h:10842[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَۗ وَكَانَ [h:2653[ٱ]للَّهُ بِكُلِّ شَىْءٍ عَلِيمًا","Муҳаммад сизлардан бирон эркакнинг отаси бўлган эмас. Лекин Аллоҳнинг Расули ва Набийларнинг сўнггисидир. Аллоҳ ҳар бир нарсани ўта билгувчидир.",423,22],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:3416[ٱ]ذْكُرُو[s[اْ] [h:10843[ٱ]للَّهَ ذِكْ[f:10844[رًا ك]َثِيرًا","Эй иймон келтирганлар! Аллоҳни кўп зикр қилинглар.",423,22],["وَسَبِّحُوهُ بُكْرَ[a:9566[ةً و]َأَصِيلاً","Ва эртаю кеч уни поклаб ёд этинглар.",423,22],["هُوَ [h:153[ٱ]لَّذِى يُصَلِّى عَلَيْكُمْ وَمَلَ[o[ـٰٓ]ئِكَتُهُ[n[ۥ] لِيُخْرِجَك[w:10845[ُم م]ِّنَ [h:1491[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ إِلَى [h:1492[ٱ][l[ل][g[نّ]ُورِۚ وَكَانَ بِ[h:3560[ٱ]لْمُؤْمِنِينَ رَحِيمًا","У сизларни зулматлардан нурга чиқариш учун Ўзи ҳам, фаришталари ҳам саловот айтадир. У мўминларга ўта меҳрибон бўлган зотдир.",423,22],["تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُ[n[ۥ] سَلَ[n[ـٰ][a:10846[مٌۚ و]َأَعَدَّ لَهُمْ أَ[q:2795[جْ][f:10847[رًا ك]َرِيمًا","У зотга йўлиқадиган кундаги сўрашишлари саломдир. Ва У зот уларга гўзал ажрни тайёрлаб қўйгандир.",424,22],["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ إِ[g[نّ][o[َآ] أَرْسَلْنَ[n[ـٰ]كَ شَ[n[ـٰ]هِ[a:10848[دًا و]َمُبَشِّ[a:10849[رًا و]َنَذِيرًا","Эй Набий, албатта, Биз сени гувоҳлик бергувчи, хушхабар элтгувчи ва огоҳлантиргувчи.",424,22],["وَدَاعِيًا إِلَى [h:1637[ٱ]للَّهِ بِإِذْنِه[n[ِۦ] وَسِرَا[a:10850[جًا م]ُّنِيرًا","Ўз изни ила Аллоҳга даъват қилгувчи ҳамда нурли чироқ қилиб юбордик.",424,22],["وَبَشِّرِ [h:1257[ٱ]لْمُؤْمِنِينَ بِأَ[g[نّ]َ لَه[w:6026[ُم م]ِّنَ [h:321[ٱ]للَّهِ فَضْل[f:10851[اً ك]َبِيرًا","Мўминларга, албатта, уларга Аллоҳдан улуғ фазлу марҳамат бўлиши ҳақида хушхабар бер.",424,22],["وَلَا تُطِعِ [h:9665[ٱ]لْكَ[n[ـٰ]فِرِينَ وَ[h:5724[ٱ]لْمُنَ[n[ـٰ]فِقِينَ وَدَعْ أَذَ[n[ٮٰ]هُمْ وَتَوَكَّلْ عَلَى [h:412[ٱ]للَّهِۚ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ وَكِيلاً","Кофир ва мунофиқларга итоат этма. Уларнинг озорларига парво қилма. Аллоҳга таваккал қил. Вакил бўлишга Аллоҳнинг Ўзи кифоядир.",424,22],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا نَكَحْتُمُ [h:10852[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ ثُ[g[مّ]َ طَلَّ[q:1345[قْ]تُمُوهُ[g[نّ]َ مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أَ[f:1348[ن ت]َمَسُّوهُ[g[نّ]َ فَمَا لَكُمْ عَلَيْهِ[g[نّ]َ مِنْ عِدَّ[f:10853[ةٍ ت]َعْتَدُّونَهَاۖ فَمَتِّعُوهُ[g[نّ]َ وَسَرِّحُوهُ[g[نّ]َ سَرَا[f:10771[حًا ج]َمِيلاً","Эй иймон келтирганлар! Қачонки мўминаларни никоҳлаб олсангиз, сўнгра уларни қўл теккизмай туриб, талоқ қилсангиз, улар зиммасида сиз учун идда ўтириш бўлмас. Бас, сиз уларни баҳраманд қилинг ва гўзал бўшатиш ила бўшатиб юборинг.",424,22],["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ إِ[g[نّ][o[َآ] أَحْلَلْنَا لَكَ أَزْو[n[َٲ]جَكَ [h:10854[ٱ]لَّ[n[ـٰ]ت[o[ِىٓ] ءَاتَيْتَ أُجُورَهُ[g[نّ]َ وَمَا مَلَكَتْ يَمِينُكَ مِ[g[مّ][o[َآ] أَف[o[َا]ٓءَ [h:10855[ٱ]للَّهُ عَلَيْكَ وَبَنَاتِ عَ[g[مّ]ِكَ وَبَنَاتِ عَ[g[مّ]َ[n[ـٰ]تِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَ[n[ـٰ]لَ[n[ـٰ]تِكَ [h:10856[ٱ]لَّ[n[ـٰ]تِى هَاجَرْنَ مَعَكَ وَ[h:10857[ٱ]مْرَأَ[a:10858[ةً م]ُّؤْمِنَةً إ[a:10859[ِن و]َهَبَتْ نَفْسَهَا لِل[g[نّ]َبِىِّ إِنْ أَرَادَ [h:10860[ٱ][l[ل][g[نّ]َبِىُّ أ[a:10861[َن ي]َسْتَ[f:10862[نك]ِحَهَا خَالِصَ[u:10863[ةً ل]َّكَ مِ[f:107[ن د]ُونِ [h:1838[ٱ]لْمُؤْمِنِينَۗ قَ[q:298[دْ] عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ ف[o[ِىٓ] أَزْو[n[َٲ]جِهِمْ وَمَا مَلَكَتْ أَيْمَ[n[ـٰ]نُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَ[a:10864[جٌۗ و]َكَانَ [h:2653[ٱ]للَّهُ غَفُو[u:2701[رًا ر]َّحِيمًا","Эй Набий, Биз сенга маҳрларини берган жуфтларингни, Аллоҳ сенга ўлжа қилиб берган қўл остингдаги ларни, амакингнинг қизлари, аммаларингнинг қизлари, тоғангнинг қизлари, холаларингнинг қизларидан сен билан ҳижрат қилганларини ҳалол қилдик. Ва агар бир мўмина аёл ўз нафсини Набийга ҳадя этса, Набий уни никоҳлаб олишни ирода қилса, сен учун махсус ҳалол қилдик. Мўминларга эмас. Уларга жуфтлари ва қўллари остидаги мулклари ҳақида нимани фарз қилганимизни билурмиз. Буни сенга танглик бўлмаслиги учун қилдик. Аллоҳ ўта мағфиратли ва ўта раҳмли зотдир.",424,22],["۞ تُرْجِى مَ[f:1823[ن ت]َش[o[َا]ٓءُ مِنْهُ[g[نّ]َ وَتُــْٔو[o[ِىٓ] إِلَيْكَ مَ[f:1823[ن ت]َش[o[َا]ٓءُۖ وَمَنِ [h:10865[ٱ][q:10866[بْ]تَغَيْتَ مِ[g[مّ]َنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَۚ ذ[n[َٲ]لِكَ أَ[q:314[دْ]نَ[o[ىٰٓ] أَ[f:10867[ن ت]َقَرَّ أَعْيُنُهُ[g[نّ]َ وَلَا يَحْزَ[g[نّ]َ وَيَرْضَيْنَ بِم[o[َآ] ءَاتَيْتَهُ[g[نّ]َ كُلُّهُ[g[نّ]َۚ وَ[h:72[ٱ]للَّهُ يَعْلَمُ مَا فِى قُلُوبِكُمْۚ وَكَانَ [h:2653[ٱ]للَّهُ عَلِيمًا حَلِيمًا","Улардан хоҳлаганингни нари қўйиб, хоҳлаганингни Ўзингга олурсан. Ўзинг четлатганлардан бирортасини истасанг, сенга гуноҳ бўлмас. Шундай бўлиши уларнинг кўзлари қувончга тўлиши, хафа бўлмасликлари ва ҳаммаларининг сен уларга берган нарсадан рози бўлишларига яқинроқдир. Аллоҳ қалбларингиздаги нарсани биладир ва Аллоҳ ўта билгувчи ва ўта ҳалим зотдир.",425,22],["لَّا يَحِلُّ لَكَ [h:10868[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءُ م[i:1287[ِنۢ ب]َعْدُ وَل[o[َآ] أَ[f:10869[ن ت]َبَدَّلَ بِهِ[g[نّ]َ مِنْ أَزْو[n[َٲ][a:10870[جٍ و]َلَوْ أَعْجَبَكَ حُسْنُهُ[g[نّ]َ إِلَّا مَا مَلَكَتْ يَمِينُكَۗ وَكَانَ [h:2653[ٱ]للَّهُ عَلَىٰ كُلِّ ش[u:10871[َىْءٍ ر]َّقِيبًا","Сенга бундан бошқа аёллар ҳалол бўлмас ва уларга бошқа завжаларни алмаштиришинг ҳам бўлмас. Агар ўшаларнинг ҳусни сени ажаблантирса ҳам. Магар қўлингда мулк бўлган бўлса мумкин. Аллоҳ ҳар бир нарсани кузатиб тургувчи зотдир.",425,22],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَ[q:1176[دْ]خُلُو[s[اْ] بُيُوتَ [h:10872[ٱ][l[ل][g[نّ]َبِىِّ إِلّ[o[َآ] أ[a:10873[َن ي]ُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَ[n[ـٰ]ظِرِينَ إِنَ[n[ـٰ]هُ وَلَ[n[ـٰ]كِنْ إِذَا دُعِيتُمْ فَ[h:7386[ٱ][q:7386[دْ]خُلُو[s[اْ] فَإِذَا طَعِمْتُمْ فَ[h:10874[ٱ][f:10874[نت]َشِرُو[s[اْ] وَلَا مُسْتَــْٔنِسِينَ لِحَدِيثٍۚ إِ[g[نّ]َ ذ[n[َٲ]لِكُمْ كَانَ يُؤْذِى [h:10875[ٱ][l[ل][g[نّ]َبِىَّ فَيَسْتَحْى[n[ِۦ] مِ[f:344[نك]ُمْۖ وَ[h:72[ٱ]للَّهُ لَا يَسْتَحْى[n[ِۦ] مِنَ [h:1173[ٱ]لْحَقِّۚ وَإِذَا سَأَلْتُمُوهُ[g[نّ]َ مَتَ[n[ـٰ][f:10876[عًا ف]َسْــَٔلُوهُ[g[نّ]َ م[a:10877[ِن و]َر[o[َا]ٓءِ حِجَا[f:10878[بٍۚ ذ][n[َٲ]لِكُمْ أَ[q:6433[طْ]هَرُ لِقُلُوبِكُمْ وَقُلُوبِهِ[g[نّ]َۚ وَمَا كَانَ لَكُمْ أَ[f:10879[ن ت]ُؤْذُو[s[اْ] رَسُولَ [h:3273[ٱ]للَّهِ وَل[o[َآ] أَ[f:10880[ن ت]َ[f:1228[نك]ِح[o[ُوٓ][s[اْ] أَزْو[n[َٲ]جَهُ[n[ۥ] م[i:254[ِنۢ ب]َعْدِه[o[ِۦٓ] أَبَدًاۚ إِ[g[نّ]َ ذ[n[َٲ]لِكُمْ كَانَ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ عَظِيمًا","Эй иймон келтирганлар! Набийнинг уйларига кирманг. Магар таомга изн берилганида, унинг пишишига мунтазир бўлмайдиган бўлиб. Лекин чақирилсангиз, киринг-да, таомни еб бўлишингиз билан тарқалиб кетинг, гапга берилиб, кетманг. Албатта, бундай қилишингиз Набийга озор берадир. У эса, сизлардан ҳаё қилардир. Аллоҳ ҳақни ҳаё қилмас. Қачонки улардан бирор нарса сўрасангиз, парда ортидан сўранг. Шундай қилмоғингиз ўз қалбларингиз учун ҳам, уларнинг қалблари учун ҳам покроқдир. Сиз учун Расулуллоҳга озор бериш ва ундан кейин унинг жуфтларини никоҳингизга олишингиз ҳеч қачон мумкин эмас. Албатта, бундай қилмоғингиз Аллоҳнинг наздида катта дир.",425,22],["إِ[f:1601[ن ت]ُ[q:1602[بْ]دُو[s[اْ] شَيْــًٔا أَوْ تُخْفُوهُ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا","Гар бир нарсани ошкор қилсангиз ҳам, махфий қилсангиз ҳам, албатта, Аллоҳ барча нарсани ўта билгувчи зотдир.",425,22],["لَّا جُنَاحَ عَلَيْهِ[g[نّ]َ ف[o[ِىٓ] ءَاب[o[َا]ٓئِهِ[g[نّ]َ وَل[o[َآ] أَ[q:9392[بْ]ن[o[َا]ٓئِهِ[g[نّ]َ وَل[o[َآ] إِخْو[n[َٲ]نِهِ[g[نّ]َ وَل[o[َآ] أَ[q:9393[بْ]ن[o[َا]ٓءِ إِخْو[n[َٲ]نِهِ[g[نّ]َ وَل[o[َآ] أَ[q:9393[بْ]ن[o[َا]ٓءِ أَخَو[n[َٲ]تِهِ[g[نّ]َ وَلَا نِس[o[َا]ٓئِهِ[g[نّ]َ وَلَا مَا مَلَكَتْ أَيْمَ[n[ـٰ]نُهُ[g[نّ]َۗ وَ[h:10881[ٱ]تَّقِينَ [h:10882[ٱ]للَّهَۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَلَىٰ كُلِّ ش[f:2752[َىْءٍ ش]َهِيدًا","Уларга ўз оталари, ўғиллари, ака-укалари, ака-укаларининг ўғиллари, опа-сингилларнинг ўғиллари, ўз аёллари ва қўллари остида мулк бўлган лари ҳақида гуноҳ йўқдир. Аллоҳга тақво қилинглар. Албатта, Аллоҳ ҳар бир нарсага шоҳид зотдир.",426,22],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ وَمَلَ[o[ـٰٓ]ئِكَتَهُ[n[ۥ] يُصَلُّونَ عَلَى [h:5875[ٱ][l[ل][g[نّ]َبِىِّۚ يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] صَلُّو[s[اْ] عَلَيْهِ وَسَلِّمُو[s[اْ] تَسْلِيمًا","Албатта, Аллоҳ ва Унинг фаришталари Пайғамбарга саловот айтурлар. Эй иймон келтирганлар! Сиз ҳам унга саловот айтинг ва салом юборинг.",426,22],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يُؤْذُونَ [h:10883[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] لَعَنَهُمُ [h:462[ٱ]للَّهُ فِى [h:599[ٱ][l[ل]دُّنْيَا وَ[h:1213[ٱ]لْأَخِرَةِ وَأَعَدَّ لَهُمْ عَذَا[a:2783[بًا م]ُّهِينًا","Албатта, Аллоҳга ва Унинг Расулига озор берадиганларни Аллоҳ бу дунё ва охиратда лаънатлади ҳамда уларга хорловчи азобни тайёрлаб қўйди.",426,22],["وَ[h:9999[ٱ]لَّذِينَ يُؤْذُونَ [h:10884[ٱ]لْمُؤْمِنِينَ وَ[h:5718[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ بِغَيْرِ مَا [h:10885[ٱ]كْتَسَبُو[s[اْ] فَقَدِ [h:10886[ٱ]حْتَمَلُو[s[اْ] بُهْتَ[n[ـٰ][a:2678[نًا و]َإِثْ[a:2679[مًا م]ُّبِينًا","Мўмин ва мўминаларга, улар бирор нарса қилмасалар ҳам, озор берадиганлар, батаҳқиқ, ўз устларига очиқ бўҳтон ва гуноҳни олибдилар.",426,22],["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ قُل لِّأَزْو[n[َٲ]جِكَ وَبَنَاتِكَ وَنِس[o[َا]ٓءِ [h:10887[ٱ]لْمُؤْمِنِينَ يُ[q:10888[دْ]نِينَ عَلَيْهِ[g[نّ]َ مِ[f:10889[ن ج]َلَ[n[ـٰ]بِيبِهِ[g[نّ]َۚ ذ[n[َٲ]لِكَ أَ[q:314[دْ]نَ[o[ىٰٓ] أ[a:10890[َن ي]ُعْرَفْنَ فَلَا يُؤْذَيْنَۗ وَكَانَ [h:2653[ٱ]للَّهُ غَفُو[u:2701[رًا ر]َّحِيمًا","Эй Набий, жуфтларингга, қизларингга ва мўминларнинг аёлларига айт: жилбобларини ўзларига яқин қилсинлар. Ана ўша уларнинг танилмоқлари ва озорга учрамасликлари учун яқинроқдир. Аллоҳ ўта мағфиратли ва раҳмли зотдир.",426,22],["۞ لَّئ[u:4195[ِن ل]َّمْ يَ[f:10891[نت]َهِ [h:10892[ٱ]لْمُنَ[n[ـٰ]فِقُونَ وَ[h:37[ٱ]لَّذِينَ فِى قُلُوبِه[w:39[ِم م]َّرَ[a:10893[ضٌ و]َ[h:10894[ٱ]لْمُرْجِفُونَ فِى [h:4932[ٱ]لْمَدِينَةِ لَنُغْرِيَ[g[نّ]َكَ بِهِمْ ثُ[g[مّ]َ لَا يُجَاوِرُونَكَ فِيه[o[َآ] إِلَّا قَلِيلاً","Қасамки, агар мунофиқлар, қалбларида марази борлар ва Мадинада миш-миш тарқатувчилар тўхтамасалар, сени уларга қарши қўзғотурмиз. Сўнгра улар уда сенга озгинадан бошқа қўшни бўла олмаслар.",426,22],["مَّلْعُونِينَۖ أَيْنَمَا ثُقِف[o[ُوٓ][s[اْ] أُخِذُو[s[اْ] وَقُتِّلُو[s[اْ] تَ[q:10895[قْ]تِيلاً","Лаънатланган ҳолларида, қаерда топилсалар, тутилурлар ва ўлдириб ташланурлар.",426,22],["سُ[g[نّ]َةَ [h:10837[ٱ]للَّهِ فِى [h:6320[ٱ]لَّذِينَ خَلَوْ[s[اْ] مِ[f:128[ن ق]َ[q:129[بْ]لُۖ وَلَ[f:3232[ن ت]َجِدَ لِسُ[g[نّ]َةِ [h:10896[ٱ]للَّهِ تَ[q:10752[بْ]دِيلاً","Илгари ўтганлар ҳақида Аллоҳ тутган йўл ҳам шудир. Аллоҳнинг йўлига ҳеч бадал топа олмассан.",426,22],["يَسْــَٔلُكَ [h:10897[ٱ][l[ل][g[نّ]َاسُ عَنِ [h:5172[ٱ][l[ل]سَّاعَةِۖ قُلْ إِ[g[نّ]َمَا عِلْمُهَا عِ[f:264[ند]َ [h:408[ٱ]للَّهِۚ وَمَا يُ[q:10898[دْ]رِيكَ لَعَلَّ [h:10899[ٱ][l[ل]سَّاعَةَ تَكُونُ قَرِيبًا","Одамлар сендан соати ҳақида сўрарлар. Сен: «Унинг илми фақат Аллоҳнинг ҳузуридадир», деб айт. Недан билурсан, эҳтимол ўша соат яқиндир.",427,22],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَعَنَ [h:10900[ٱ]لْكَ[n[ـٰ]فِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا","Албатта, Аллоҳ кофирларни лаънатлади ва уларга дўзахни тайёрлаб қўйди.",427,22],["خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَ[u:10901[دًاۖ ل]َّا يَجِدُونَ وَلِي[a:3006[ًّا و]َلَا نَصِيرًا","Улар унда абадий бардавом қолурлар. На бир дўст ва на бир ёрдамчи топа олмаслар.",427,22],["يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى [h:4674[ٱ][l[ل][g[نّ]َارِ يَقُولُونَ يَ[n[ـٰ]لَيْتَن[o[َآ] أَطَعْنَا [h:10902[ٱ]للَّهَ وَأَطَعْنَا [h:10903[ٱ][l[ل]رَّسُولَا۟","Юзлари олов ичида айлантирилаётган кунда улар: «Вой шўримиз қурсин, кошки Аллоҳга итоат қилсак эди, Расулига итоат қилсак эди», дерлар.",427,22],["وَقَالُو[s[اْ] رَبَّن[o[َآ] إِ[g[نّ][o[َآ] أَطَعْنَا سَادَتَنَا وَكُبَر[o[َا]ٓءَنَا فَأَضَلُّونَا [h:10904[ٱ][l[ل]سَّبِيلَا۟","Ва: «Эй Роббимиз, албатта, биз бошлиқларимизга ва катталаримизга итоат қилдик. Бас, улар бизни йўлдан оздирдилар.",427,22],["رَبَّن[o[َآ] ءَاتِهِمْ ضِعْفَيْنِ مِنَ [h:503[ٱ]لْعَذَابِ وَ[h:10905[ٱ]لْعَنْهُمْ لَعْ[f:10906[نًا ك]َبِيرًا","Эй Роббимиз, сен уларга азобдан икки ҳисса бергин ва уларни катта лаънатлаш ила лаънатла!» дедилар.",427,22],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَكُونُو[s[اْ] كَ[h:2146[ٱ]لَّذِينَ ءَاذَوْ[s[اْ] مُوسَىٰ فَبَرَّأَهُ [h:10907[ٱ]للَّهُ مِ[g[مّ]َا قَالُو[s[اْۚ] وَكَانَ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَجِيهًا","Эй иймон келтирганлар! Мусога озор берганлар каби бўлманглар. Бас, Аллоҳ уни улар айтган нарсадан поклади. Ва у Аллоҳнинг наздида обрўли эди.",427,22],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:1643[ٱ]تَّقُو[s[اْ] [h:1644[ٱ]للَّهَ وَقُولُو[s[اْ] قَوْل[f:2581[اً س]َدِيدًا","Эй иймон келтирганлар! Аллоҳга тақво қилинглар ва тўғри сўз сўзланглар.",427,22],["يُصْلِحْ لَكُمْ أَعْمَ[n[ـٰ]لَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْۗ وَم[a:2629[َن ي]ُطِعِ [h:2630[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] فَقَ[q:563[دْ] فَازَ فَوْزًا عَظِيمًا","Сизнинг амаларингизни солиҳ қилур ва гуноҳларингизни мағфират қилур. Ким Аллоҳга ва Унинг Расулига итоат қилса, батаҳқиқ, буюк зафарга эришибдир.",427,22],["إِ[g[نّ]َا عَرَضْنَا [h:10908[ٱ]لْأَمَانَةَ عَلَى [h:10909[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَ[h:10910[ٱ]لْجِبَالِ فَأَبَيْنَ أ[a:10911[َن ي]َحْمِلْنَهَا وَأَشْفَ[q:10912[قْ]نَ مِنْهَا وَحَمَلَهَا [h:10913[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُۖ إِ[g[نّ]َهُ[n[ۥ] كَانَ ظَلُو[f:10914[مًا ج]َهُولاً","Албатта, Биз бу омонатни осмонларга, ерга ва тоғларга таклиф қилдик. Бас, улар уни кўтаришдан бош тортдилар ва ундан қўрқдилар. Уни инсон кўтарди. Дарҳақиқат, у ўта золим ва ўта жоҳилдир.",427,22],["لِّيُعَذِّبَ [h:10915[ٱ]للَّهُ [h:5698[ٱ]لْمُنَ[n[ـٰ]فِقِينَ وَ[h:5699[ٱ]لْمُنَ[n[ـٰ]فِقَ[n[ـٰ]تِ وَ[h:10916[ٱ]لْمُشْرِكِينَ وَ[h:10917[ٱ]لْمُشْرِكَ[n[ـٰ]تِ وَيَتُوبَ [h:10918[ٱ]للَّهُ عَلَى [h:2329[ٱ]لْمُؤْمِنِينَ وَ[h:5718[ٱ]لْمُؤْمِنَ[n[ـٰ]تِۗ وَكَانَ [h:2653[ٱ]للَّهُ غَفُو[u:2701[رًا ر]َّحِيمَۢا","Аллоҳ мунофиқлар ва мунофиқаларни, мушриклар ва мушрикаларни азоблаши учун ҳамда мўмин ва мўминаларнинг тавбаларини қабул этиш учундир. Аллоҳ ўта мағфиратли ва ўта раҳмли зотдир.",427,22]]},{"n":34,"ar":"سَبَإٍ","en":"Saba","uz":"Сабаъ","type":"Макка","ayahs":[["ٱلْحَمْدُ لِلَّهِ [h:3912[ٱ]لَّذِى لَهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ وَلَهُ [h:10443[ٱ]لْحَمْدُ فِى [h:536[ٱ]لْأَخِرَةِۚ وَهُوَ [h:3967[ٱ]لْحَكِيمُ [h:3968[ٱ]لْخَب[p[ِي]رُ","Осмонлардаги нарсалар ва ердаги нарсалар Уники бўлган Аллоҳга ҳамд бўлсин. Охиратдаги ҳамд ҳам Уникидир. Ва У ўта ҳикматли, ўта хабардор зотдир.",428,22],["يَعْلَمُ مَا يَلِجُ فِى [h:44[ٱ]لْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَ[f:10919[نز]ِلُ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ وَمَا يَعْرُجُ فِيهَاۚ وَهُوَ [h:10920[ٱ][l[ل]رَّحِيمُ [h:10921[ٱ]لْغَف[p[ُو]رُ","У ерга нима кирса ва ундан нима чиқса, биладир, осмондан нима тушса ва унга нима чиқса, биладир. Ва У ўта раҳмли ва ўта мағфиратли зотдир.",428,22],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَا تَأْتِينَا [h:10922[ٱ][l[ل]سَّاعَةُۖ قُلْ بَلَىٰ وَرَبِّى لَتَأْتِيَ[g[نّ]َكُمْ عَ[n[ـٰ]لِمِ [h:5788[ٱ]لْغَيْبِۖ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّ[f:6110[ةٍ ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَلَا فِى [h:44[ٱ]لْأَرْضِ وَل[o[َآ] أَصْغَرُ مِ[f:2624[ن ذ][n[َٲ]لِكَ وَل[o[َآ] أَكْبَرُ إِلَّا فِى كِتَ[n[ـٰ][a:4113[بٍ م]ُّب[p[ِي]نٍ","Куфр келтирганлар: «Бизга соати келмас», дедилар. Сен: «Йўқ! Ғойибни билгувчи Роббим ила қасамки, у сизларга албатта келур. У зотдан осмонлару ердаги зарра вазнича, ундан кичик нарса ҳам, катта нарса ҳам ғойиб бўлмас. Илло, ҳаммаси очиқ китобдадир», деб айт.",428,22],["لِّيَ[q:5945[جْ]زِىَ [h:5946[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَه[w:3412[ُم م]َّغْفِرَ[a:5445[ةٌ و]َرِزْ[f:5239[قٌ ك]َر[p[ِي]مٌ","Иймон келтирган ва яхши амалларни қилганларни мукофотлаш учун. Ана ўшаларга, мағфират ва гўзал ризқ бордир.",428,22],["وَ[h:9999[ٱ]لَّذِينَ سَعَوْ ف[o[ِىٓ] ءَايَ[n[ـٰ]تِنَا مُعَ[n[ـٰ]جِزِينَ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ عَذَا[a:10923[بٌ م]ّ[u:10924[ِن ر]ِّ[q:10925[جْ]زٍ أَل[p[ِي]مٌ","Бизнинг оятларимизни ожиз қолдиргувчи бўлиш учун ҳаракат қилганларга эса, ана ўшаларга, аламли жазодан иборат азоб бордир.",428,22],["وَيَرَى [h:10926[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:7379[ٱ]لْعِلْمَ [h:10927[ٱ]لَّذ[o[ِىٓ] أُ[f:17[نز]ِلَ إِلَيْكَ م[u:770[ِن ر]َّبِّكَ هُوَ [h:5317[ٱ]لْحَقَّ وَيَهْد[o[ِىٓ] إِلَىٰ صِر[n[َٲ]طِ [h:7036[ٱ]لْعَزِيزِ [h:7037[ٱ]لْحَم[p[ِي][q[د]ِ","Илм берилганлар сенга Роббингдан нозил қилинган нарсани айни ҳақ деб ва азиз ва мақталган зотнинг йўлига ҳидоят қилур деб билурлар.",428,22],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَرُو[s[اْ] هَلْ نَدُلُّكُمْ عَلَىٰ رَجُ[a:10928[لٍ ي]ُنَبِّئُكُمْ إِذَا مُزِّ[q:10929[قْ]تُمْ كُلَّ مُمَزَّقٍ إِ[g[نّ]َكُمْ لَفِى خَلْ[f:6887[قٍ ج]َد[p[ِي][q[د]ٍ","Куфр келтирганлар эса: «Сизларга бутунлай титилиб битган чоғингизда албатта янгитдан яратилишингиз хабарини бераётган кишини кўрсатайликми?!",428,22],["أَفْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِبًا أ[c:10930[َم ب]ِه[n[ِۦ] جِ[g[نّ]َۗ[i:10931[ةُۢ ب]َلِ [h:10932[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ فِى [h:10442[ٱ]لْعَذَابِ وَ[h:10933[ٱ][l[ل]ضَّلَ[n[ـٰ]لِ [h:10934[ٱ]لْبَع[p[ِي][q[د]ِ","У Аллоҳга нисбатан ёлғон тўқидими ёки жинни бўлиб қолдими? « дедилар. Йўқ! Охиратга иймон келтирмайдиганлар азобда ва йироқ залолатдадирлар.",429,22],["أَفَلَمْ يَرَوْ[s[اْ] إِلَىٰ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَه[w:10935[ُم م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِۚ إ[a:9711[ِن ن]َّشَأْ نَخْسِفْ بِهِمُ [h:7419[ٱ]لْأَرْضَ أَوْ نُسْقِ[q:10936[طْ] عَلَيْهِمْ كِسَ[a:9847[فًا م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[u:10937[ةً ل]ِّكُلِّ عَ[q:10938[بْ][a:10939[دٍ م]ُّن[p[ِي][q[ب]ٍ","Ахир, улар осмону ердаги, олдиларидаги нарсаларни, ортларидаги нарсаларни кўрмайдиларми?! Агар хоҳласак, уларни ерга ютдириб юборурмиз ёки устларига осмондан парчалар туширурмиз. Албатта, бунда қайтгувчи ҳар бир банда учун оят-белги бордир.",429,22],["۞ وَلَقَ[q:341[دْ] ءَاتَيْنَا دَاوُ[n[ۥ]دَ مِ[g[نّ]َا فَضْل[a:10940[اًۖ ي]َ[n[ـٰ]جِبَالُ أَوِّبِى مَعَهُ[n[ۥ] وَ[h:8822[ٱ][l[ل]طَّيْرَۖ وَأَلَ[g[نّ]َا لَهُ [h:10941[ٱ]لْحَد[p[ِي][q[د]َ","Батаҳқиқ, Биз Довудга Ўзимиздан фазл бердик. «Эй тоғлар, у билан бирга қайтар ва қушлар ҳам»,. Ва унга темирни юмшоқ қилдик.",429,22],["أَنِ [h:10942[ٱ]عْمَلْ سَ[n[ـٰ]بِغَ[n[ـٰ][a:10943[تٍ و]َقَدِّرْ فِى [h:10944[ٱ][l[ل]سَّرْدِۖ وَ[h:9226[ٱ]عْمَلُو[s[اْ] صَ[n[ـٰ]لِحًاۖ إِ[g[نّ]ِى بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","Ва унга: «Совутлар қилгин ва бичимини ўлчовли қил. Солиҳ амаллар қилинглар. Албатта, Мен нима амал қилаётганингизни яхши кўриб тургувчиман», дедик.",429,22],["وَلِسُلَيْمَ[n[ـٰ]نَ [h:8826[ٱ][l[ل]رِّيحَ غُدُوُّهَا شَهْ[a:10945[رٌ و]َرَوَاحُهَا شَهْ[a:10946[رٌۖ و]َأَسَلْنَا لَهُ[n[ۥ] عَيْنَ [h:10947[ٱ]لْقِ[q:10948[طْ]رِۖ وَمِنَ [h:10949[ٱ]لْجِ[g[نّ]ِ م[a:10950[َن ي]َعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِ[n[ۖۦ] وَم[a:10951[َن ي]َزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِ[q:8980[قْ]هُ مِنْ عَذَابِ [h:8905[ٱ][l[ل]سَّع[p[ِي]رِ","Ва Сулаймонга шамолни. Унинг эрталаб кетиши бир ойлик, кечқурун қайтиши бир ойлик йўл эди. Унга мис булоғини оқизиб қўйдик ва жинлардан Роббининг изни ила унинг ҳузурида ишлайдиганлари бор эди. Улардан ким амримиздан чиқса, унга қаттиқ олов азобини тотдирамиз.",429,22],["يَعْمَلُونَ لَهُ[n[ۥ] مَا يَش[o[َا]ٓءُ م[a:10952[ِن م]َّحَ[n[ـٰ]رِيبَ وَتَمَ[n[ـٰ]ثِيلَ وَجِفَا[f:10953[نٍ ك]َ[h:10954[ٱ]لْجَوَابِ وَقُدُو[u:10955[رٍ ر]َّاسِيَ[n[ـٰ]تٍۚ [h:10956[ٱ]عْمَل[o[ُوٓ][s[اْ] ءَالَ دَاوُ[n[ۥ]دَ شُكْ[a:10957[رًاۚ و]َقَلِي[a:10958[لٌ م]ِّنْ عِبَادِىَ [h:10959[ٱ][l[ل]شَّك[p[ُو]رُ","Улар унга меҳроблар, ҳайкаллар, ҳовузлар каби лаганлар ва собит қозонлардан хоҳлаганини қилиб беришар эди. Эй Оли Довуд, шукр қилинглар! Бандаларимдан шукр қилгувчилари оздир.",429,22],["فَلَ[g[مّ]َا قَضَيْنَا عَلَيْهِ [h:10960[ٱ]لْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِه[o[ِۦٓ] إِلَّا د[m[َا]ٓبَّةُ [h:10961[ٱ]لْأَرْضِ تَأْكُلُ مِ[f:10962[نس]َأَتَهُۖ[n[ۥ] فَلَ[g[مّ]َا خَرَّ تَبَيَّنَتِ [h:10963[ٱ]لْجِ[g[نّ]ُ أ[u:4894[َن ل]َّوْ كَانُو[s[اْ] يَعْلَمُونَ [h:10964[ٱ]لْغَيْبَ مَا لَبِثُو[s[اْ] فِى [h:10442[ٱ]لْعَذَابِ [h:10965[ٱ]لْمُه[p[ِي]نِ","Қачонки, Биз уга ўлимни ҳукм этганимизда, уларга унинг ўлими ҳақида асосини еяётган ёғоч қуртидан бошқа ҳеч бир нарса далолат қилмади. Қачонки, у йиқилганда, жинларга, агар улар ғайбни билганларида, хорловчи азобда қолмаган бўлишлари аён бўлди.",429,22],["لَقَ[q:2389[دْ] كَانَ لِسَبَ[f:10966[إٍ ف]ِى مَسْكَنِهِمْ ءَايَ[f:10967[ةٌۖ ج]َ[g[نّ]َتَانِ ع[a:10968[َن ي]َمِي[a:10969[نٍ و]َشِمَا[f:10970[لٍۖ ك]ُلُو[s[اْ] م[u:301[ِن ر]ِّزْقِ رَبِّكُمْ وَ[h:783[ٱ]شْكُرُو[s[اْ] لَهُۚ[n[ۥ] بَلْدَ[f:10971[ةٌ ط]َيِّبَ[a:10972[ةٌ و]َرَبٌّ غَف[p[ُو]رٌ","Батаҳқиқ, сабаъликлар учун ўз масканларида оят-белги бор эди–ўнг ва чапдан икки боғ бор эди. «Роббингиз ризқидан енг ва Унга шукр қилинг! Не гўзал юртингиз ва ўта мағфиратли Роббингиз»,.",430,22],["فَأَعْرَضُو[s[اْ] فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ [h:10973[ٱ]لْعَرِمِ وَبَدَّلْنَ[n[ـٰ]ه[c:10974[ُم ب]ِجَ[g[نّ]َتَيْهِمْ جَ[g[نّ]َتَيْنِ ذَوَات[o[َىْ] أُكُلٍ خَمْ[a:10975[طٍ و]َأَثْ[a:10976[لٍ و]َش[a:10977[َىْءٍ م]ِّ[f:10978[ن س]ِ[q:10979[دْ][f:10980[رٍ ق]َل[p[ِي]لٍ","Улар юз ўгирдилар. Бас, Биз устларига арим селини юбордик ва уларнинг икки боғларини аччиқ мевали, юлғунзор ва бир озгина сидрли икки «боғ»га айлантирдик.",430,22],["ذ[n[َٲ]لِكَ جَزَيْنَ[n[ـٰ]ه[c:10981[ُم ب]ِمَا كَفَرُو[s[اْۖ] وَهَلْ نُجَ[n[ـٰ]ز[o[ِىٓ] إِلَّا [h:10982[ٱ]لْكَف[p[ُو]رَ","Уларни ношукрлик қилганлари учун ана шундоқ жазоладик. Биз фақат ўта ношукрларгагина жазо берурмиз.",430,22],["وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ [h:10983[ٱ]لْقُرَى [h:10984[ٱ]لَّتِى بَ[n[ـٰ]رَكْنَا فِيهَا قُ[f:10985[رًى ظ]َ[n[ـٰ]هِرَ[a:10986[ةً و]َقَدَّرْنَا فِيهَا [h:10987[ٱ][l[ل]سَّيْرَۖ سِيرُو[s[اْ] فِيهَا لَيَالِىَ وَأَيَّامًا ءَامِن[p[ِي]نَ","Биз улар билан Ўзимиз баракали қилган шаҳарлар орасида кетма-кет қишлоқлар қилиб, улар орасидаги юришни ўлчовли этиб қўйган ва «Уларда кечалар ҳам, кундузлар ҳам омонлик-ла юраверинг».",430,22],["فَقَالُو[s[اْ] رَبَّنَا بَ[n[ـٰ]عِ[q:10988[دْ] بَيْنَ أَسْفَارِنَا وَظَلَم[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ فَجَعَلْنَ[n[ـٰ]هُمْ أَحَادِيثَ وَمَزَّ[q:10989[قْ]نَ[n[ـٰ]هُمْ كُلَّ مُمَزَّقٍۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:7049[تٍ ل]ِّكُلِّ صَبَّا[f:7050[رٍ ش]َك[p[ُو]رٍ","Улар: «Эй Роббимиз, сафарларимиз орасини узоқ қил!» дедилар ва ўзларига зулм қилдилар. Бас, Биз уларни ҳикояларга айлантирдик ва бутунлай парча-парча қилиб ташладик. Албатта, бунда ҳар бир ўта сабрли ва ўта шукрли учун оят-белгилар бордир.",430,22],["وَلَقَ[q:341[دْ] صَدَّقَ عَلَيْهِمْ إِ[q:10990[بْ]لِيسُ ظَ[g[نّ]َهُ[n[ۥ] فَ[h:10991[ٱ]تَّبَعُوهُ إِلَّا فَرِي[a:2128[قًا م]ِّنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Батаҳқиқ, иблис улар ҳақидаги гумонини рўёбга чиқарди. Бас, фақат бир гуруҳ мўминлардан бошқалари унга эргашдилар.",430,22],["وَمَا كَانَ لَهُ[n[ۥ] عَلَيْه[w:4082[ِم م]ِّ[f:4798[ن س]ُلْطَ[n[ـٰ]نٍ إِلَّا لِنَعْلَمَ م[a:5799[َن ي]ُؤْمِنُ بِ[h:447[ٱ]لْأَخِرَةِ مِ[g[مّ]َنْ هُوَ مِنْهَا فِى شَ[a:10992[كٍّۗ و]َرَبُّكَ عَلَىٰ كُلِّ شَىْءٍ حَف[p[ِي]ظٌ","Ҳолбуки, унинг улар устидан ҳеч бир ҳукумронлиги бўлмас эди. Магар, Биз охиратга иймон келтирадиганни, унда шаки бордан айришимиз учун бўлди. Роббинг ҳар бир нарсани муҳофаза қилгувчидир.",430,22],["قُلِ [h:5199[ٱ][q:4751[دْ]عُو[s[اْ] [h:7796[ٱ]لَّذِينَ زَعَمْت[w:7797[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِۖ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّ[f:6110[ةٍ ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَلَا فِى [h:44[ٱ]لْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِ[f:10993[ن ش]ِرْ[a:10994[كٍ و]َمَا لَهُ[n[ۥ] مِنْه[w:8433[ُم م]ِّ[f:10995[ن ظ]َه[p[ِي]رٍ","Сен: «Аллоҳдан ўзга гумон қилган дуо қилаверинглар-чи?! Улар осмонлару ерда зарра вазнича нарсага молик эмаслар. Уларга буларида шериклик ҳам йўқ. Ва У зотга улардан бирорта ёрдамчи ҳам йўқ«, деб айт.",430,22],["وَلَا تَ[f:8613[نف]َعُ [h:8614[ٱ][l[ل]شَّفَ[n[ـٰ]عَةُ عِ[f:719[ند]َهُ[o[ۥٓ] إِلَّا لِمَنْ أَذِنَ لَهُۚ[n[ۥ] حَتَّ[o[ىٰٓ] إِذَا فُزِّعَ عَ[f:10996[ن ق]ُلُوبِهِمْ قَالُو[s[اْ] مَاذَا قَالَ رَبُّكُمْۖ قَالُو[s[اْ] [h:10997[ٱ]لْحَقَّۖ وَهُوَ [h:1475[ٱ]لْعَلِىُّ [h:9089[ٱ]لْكَب[p[ِي]رُ","У зотнинг ҳузурида фақат Ўзи изн берганлардан бошқанинг шафоати манфаат бермас. Токи қалбларидан қўрқинч кетгач: «Роббингиз нима деди?» дерлар. «Ҳақни», дерлар. У олий ва буюк зотдир.",431,22],["۞ قُلْ م[a:6033[َن ي]َرْزُقُك[w:6034[ُم م]ِّنَ [h:7498[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِۖ قُلِ [h:3166[ٱ]للَّهُۖ وَإِ[g[نّ][o[َآ] أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Сен: «Сизга осмонлару ердан ким ризқ берур?» деб айт. «Аллоҳ. Албатта, биз ёки сиз ҳидоятда ёхуд очиқ-ойдин залолатдадирмиз».",431,22],["قُل لَّا تُسْــَٔلُونَ عَ[g[مّ][o[َآ] أَ[q:10998[جْ]رَمْنَا وَلَا نُسْــَٔلُ عَ[g[مّ]َا تَعْمَل[p[ُو]نَ","Сен: «Сизлар биз қилган жиноятдан сўралмассиз, биз эса сиз қилган амалдан сўралмасмиз», деб айт.",431,22],["قُلْ يَ[q:3861[جْ]مَعُ بَيْنَنَا رَبُّنَا ثُ[g[مّ]َ يَفْتَحُ بَيْنَنَا بِ[h:370[ٱ]لْحَقِّ وَهُوَ [h:10999[ٱ]لْفَتَّاحُ [h:11000[ٱ]لْعَل[p[ِي]مُ","Сен: «Роббимиз бизларни жамлар, сўнгра ҳақ ила орамизни очиқ қилур. У ўта очгувчи ва ўта билгувчидир», деб айт.",431,22],["قُلْ أَرُونِىَ [h:11001[ٱ]لَّذِينَ أَلْحَ[q:11002[قْ]ت[c:11003[ُم ب]ِه[n[ِۦ] شُرَك[o[َا]ٓءَۖ كَلَّاۚ بَلْ هُوَ [h:8078[ٱ]للَّهُ [h:9894[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Сен: «У зотга шериклар қилиб тиқиштирганларингизни менга кўрсатинг. Йўқ! Фақат азиз ва ҳаким бўлган Аллоҳгина бордир», деб айт.",431,22],["وَم[o[َآ] أَرْسَلْنَ[n[ـٰ]كَ إِلَّا ك[m[َا]ٓفَّ[u:11004[ةً ل]ِّل[g[نّ]َاسِ بَشِي[a:622[رًا و]َنَذِي[a:11005[رًا و]َلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Биз сени барча одамларга фақат хушхабарчи ва огоҳлантиргувчи қилиб юбордик. Лекин одамларнинг кўплари билмаслар.",431,22],["وَيَقُولُونَ مَتَىٰ هَ[n[ـٰ]ذَا [h:6081[ٱ]لْوَعْدُ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Улар: «Агар ростгўй бўлсангиз, бу ваъда қачон бўлур?» дерлар.",431,22],["قُل لَّك[w:11006[ُم م]ِّيعَادُ يَوْ[u:11007[مٍ ل]َّا تَسْتَــْٔخِرُونَ عَنْهُ سَاعَ[a:4666[ةً و]َلَا تَسْتَ[q:11008[قْ]دِم[p[ُو]نَ","Сен: «Сизга бир куннинг ваъдаси бор. Ундан бир он ортга ҳам қола олмассиз, олдин ҳам кета олмассиз», деб айт.",431,22],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَرُو[s[اْ] ل[a:265[َن ن]ُّؤْمِنَ بِهَ[n[ـٰ]ذَا [h:11009[ٱ]لْقُرْءَانِ وَلَا بِ[h:315[ٱ]لَّذِى بَيْنَ يَدَيْهِۗ وَلَوْ تَرَ[o[ىٰٓ] إِذِ [h:4244[ٱ][l[ل]ظَّ[n[ـٰ]لِمُونَ مَوْقُوفُونَ عِ[f:264[ند]َ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ [h:11010[ٱ]لْقَوْلَ يَقُولُ [h:3992[ٱ]لَّذِينَ [h:10065[ٱ]سْتُضْعِفُو[s[اْ] لِلَّذِينَ [h:7089[ٱ]سْتَكْبَرُو[s[اْ] لَوْل[o[َآ] أَ[f:428[نت]ُمْ لَكُ[g[نّ]َا مُؤْمِن[p[ِي]نَ","Куфр келтирганлар: «Ушбу Қуръонга ҳам, ундан олдинги нарсага ҳам ҳеч иймон келтирмаймиз», дедилар. Агар сен ўша золимларни Роббилари ҳузурида турғазиб қўйилганларида бир-бирларига гап қайтараётганларини кўрсанг эди. Ўшанда заиф саналганлар мутакаббирлик қилганларга: «Сиз бўлмаганингизда, албатта, биз мўмин бўлар эдик», дерлар.",431,22],["قَالَ [h:590[ٱ]لَّذِينَ [h:4816[ٱ]سْتَكْبَرُو[s[اْ] لِلَّذِينَ [h:4817[ٱ]سْتُضْعِف[o[ُوٓ][s[اْ] أَنَحْنُ صَدَ[q:11011[دْ]نَ[n[ـٰ]كُمْ عَنِ [h:11012[ٱ]لْهُدَىٰ بَعْدَ إِذْ ج[o[َا]ٓءَك[c:11013[ُمۖ ب]َلْ كُ[f:100[نت][w:11014[ُم م]ُّ[q:4958[جْ]رِم[p[ِي]نَ","Мутакаббирлик қилганлар заиф саналганларга: «Сизга ҳидоят келганидан кейин биз сизни ундан тўсдикми?! Йўқ! Ўзингиз жиноятчи бўлдингиз», дерлар.",432,22],["وَقَالَ [h:614[ٱ]لَّذِينَ [h:10065[ٱ]سْتُضْعِفُو[s[اْ] لِلَّذِينَ [h:7089[ٱ]سْتَكْبَرُو[s[اْ] بَلْ مَكْرُ [h:11015[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ إِذْ تَأْمُرُونَن[o[َآ] أ[a:11016[َن ن]َّكْفُرَ بِ[h:32[ٱ]للَّهِ وَنَ[q:11017[جْ]عَلَ لَهُ[o[ۥٓ] أَ[f:96[ند]َا[a:11018[دًاۚ و]َأَسَرُّو[s[اْ] [h:6090[ٱ][l[ل][g[نّ]َدَامَةَ لَ[g[مّ]َا رَأَوُ[s[اْ] [h:6091[ٱ]لْعَذَابَ وَجَعَلْنَا [h:11019[ٱ]لْأَغْلَ[n[ـٰ]لَ ف[o[ِىٓ] أَعْنَاقِ [h:11020[ٱ]لَّذِينَ كَفَرُو[s[اْۚ] هَلْ يُ[q:5019[جْ]زَوْنَ إِلَّا مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Заиф саналганлар мутакаббирлик қилганларга: «Йўқ! Кечаю кундузнинг макр-ҳийласи. Ўшанда сизлар бизни Аллоҳга куфр келтиришимизга, Унга тенгдошлар қўшишимизга амр қилар эдингиз», дедилар. Улар азобни кўрган чоғларида надоматни ичларида тутдилар. Биз куфр келтирганларнинг бўйинларига кишанлар солдик. Улар фақат қилиб юрган амалларига яраша жазоланурлар.",432,22],["وَم[o[َآ] أَرْسَلْنَا فِى قَرْيَ[a:4874[ةٍ م]ّ[a:10183[ِن ن]َّذِيرٍ إِلَّا قَالَ مُتْرَفُوه[o[َآ] إِ[g[نّ]َا بِم[o[َآ] أُرْسِلْت[c:7059[ُم ب]ِه[n[ِۦ] كَ[n[ـٰ]فِر[p[ُو]نَ","Қайсики бир шаҳар-қишлоққа огоҳлантиргувчи юборсак, албатта, унинг маишатбозлари: «Биз, албатта, сиз ила юборилган нарсага куфр келтиргувчилармиз», дедилар.",432,22],["وَقَالُو[s[اْ] نَحْنُ أَكْثَرُ أَمْو[n[َٲ]ل[a:5702[اً و]َأَوْلَ[n[ـٰ][a:11021[دًا و]َمَا نَحْنُ بِمُعَذَّب[p[ِي]نَ","Улар: «Бизнинг молу дунёмиз, бола-чақамиз кўпроқ. Биз азоблангувчи эмасмиз», дерлар.",432,22],["قُلْ إِ[g[نّ]َ رَبِّى يَ[q:6968[بْ]سُطُ [h:6969[ٱ][l[ل]رِّزْقَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيَ[q:6970[قْ]دِرُ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Сен: «Албатта, Роббим хоҳлаган кишисига ризқни кенг қилур ва тор қилур. Лекин одамларнинг кўплари билмаслар», деб айт.",432,22],["وَم[o[َآ] أَمْو[n[َٲ]لُكُمْ وَل[o[َآ] أَوْلَ[n[ـٰ]دُك[c:11022[ُم ب]ِ[h:4526[ٱ]لَّتِى تُقَرِّبُكُمْ عِ[f:2359[ند]َنَا زُلْفَ[o[ىٰٓ] إِلَّا مَنْ ءَامَنَ وَعَمِلَ صَ[n[ـٰ]لِ[f:8375[حًا ف]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ جَز[o[َا]ٓءُ [h:11023[ٱ][l[ل]ضِّعْفِ بِمَا عَمِلُو[s[اْ] وَهُمْ فِى [h:11024[ٱ]لْغُرُفَ[n[ـٰ]تِ ءَامِن[p[ُو]نَ","На молу дунёларингиз ва на бола-чақаларингиз сизни Бизнинг ҳузуримизга яқин қила олмас. Магар ким иймон келтирган ва солиҳ амал қилган бўлса, ана ўшаларгагина қилган амаллари туфайли кўпайтирилган мукофот бордир. Улар болохоналарида омонликдадирлар.",432,22],["وَ[h:9999[ٱ]لَّذِينَ يَسْعَوْنَ ف[o[ِىٓ] ءَايَ[n[ـٰ]تِنَا مُعَ[n[ـٰ]جِزِينَ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ فِى [h:10442[ٱ]لْعَذَابِ مُحْضَر[p[ُو]نَ","Бизнинг оятларимизни ожиз қолдириш учун ҳаракат қиладиганлар эса, ана ўшалар азоб ичига ҳозир қилинганлардир.",432,22],["قُلْ إِ[g[نّ]َ رَبِّى يَ[q:6968[بْ]سُطُ [h:6969[ٱ][l[ل]رِّزْقَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[n[ِۦ] وَيَ[q:6970[قْ]دِرُ لَهُ[n[ۥ]ۚ وَم[o[َآ] أَ[f:1186[نف]َ[q:1186[قْ]ت[w:1187[ُم م]ِّ[f:2103[ن ش][f:11025[َىْءٍ ف]َهُوَ يُخْلِفُهُۖ[n[ۥ] وَهُوَ خَيْرُ [h:3894[ٱ][l[ل]رّ[n[َٲ]زِق[p[ِي]نَ","Айт: «Албатта, Роббим ризқни Ўз бандаларидан кимни хоҳласа ўшанга кенг қилур ва тор қилур. Ҳар бир инфоқ қилган нарсангизнинг ўрнини У тўлдирур. У зот ризқ бергувчиларнинг яхшисидир».",432,22],["وَيَوْمَ يَحْشُرُهُمْ جَمِي[f:155[عًا ث]ُ[g[مّ]َ يَقُولُ لِلْمَلَ[o[ـٰٓ]ئِكَةِ أَهَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ إِيَّاكُمْ كَانُو[s[اْ] يَعْبُد[p[ُو]نَ","Уларнинг барчаларини жамлайдиган, сўнгра У зот фаришталарга: «Анавилар сизларга ибодат қилган эдиларми?» дейдиган кунда.",433,22],["قَالُو[s[اْ] سُ[q:168[بْ]حَ[n[ـٰ]نَكَ أَ[f:169[نت]َ وَلِيُّنَا مِ[f:5400[ن د]ُونِه[c:11026[ِمۖ ب]َلْ كَانُو[s[اْ] يَعْبُدُونَ [h:11027[ٱ]لْجِ[g[نّ]َۖ أَكْثَرُه[c:11028[ُم ب]ِه[w:11029[ِم م]ُّؤْمِن[p[ُو]نَ","Улар: «Сен поксан! Сен бизнинг валиймизсан! Улар эмас! Йўқ! Улар жинларга ибодат қилар эдилар. Кўплари ўшаларга иймон келтиргувчидирлар», дерлар.",433,22],["فَ[h:9999[ٱ]لْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْ[a:11030[ضٍ ن]َّفْ[a:5175[عًا و]َلَا ضَر[a:11031[ًّا و]َنَقُولُ لِلَّذِينَ ظَلَمُو[s[اْ] ذُوقُو[s[اْ] عَذَابَ [h:1110[ٱ][l[ل][g[نّ]َارِ [h:11032[ٱ]لَّتِى كُ[f:100[نت][c:11033[ُم ب]ِهَا تُكَذِّب[p[ُو]نَ","Бугунги кунда бир-бирингиз учун манфаатга ҳам, зарарга ҳам молик эмассизлар. Ва зулм қилганларга: «Ўзингиз ёлғонга чиқариб юрган оловнинг азобини татиб кўринг», дермиз.",433,22],["وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَ[n[ـٰ]تُنَا بَيِّنَ[n[ـٰ][f:10162[تٍ ق]َالُو[s[اْ] مَا هَ[n[ـٰ]ذ[o[َآ] إِلَّا رَجُ[a:11034[لٌ ي]ُرِيدُ أ[a:11035[َن ي]َصُدَّكُمْ عَ[g[مّ]َا كَانَ يَعْبُدُ ءَاب[o[َا]ٓؤُكُمْ وَقَالُو[s[اْ] مَا هَ[n[ـٰ]ذ[o[َآ] إِلّ[o[َآ] إِفْ[a:11036[كٌ م]ُّفْتَ[a:11037[رًىۚ و]َقَالَ [h:614[ٱ]لَّذِينَ كَفَرُو[s[اْ] لِلْحَقِّ لَ[g[مّ]َا ج[o[َا]ٓءَهُمْ إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا سِحْ[a:3879[رٌ م]ُّب[p[ِي]نٌ","Қачонки уларга Бизнинг очиқ-ойдин оятларимиз тиловат қилинса: «Бу сизни ота-боболарингиз ибодат қилиб юрган нарсадан тўсмоқни ирода қиладиган одам, холос», дедилар ва «Бу тўқилган уйдирмадан бошқа нарса эмас», дедилар. Ва куфр келтирганлар ўзларига ҳақ келган чоғда: «Бу очиқ-ойдин сеҳрдан бошқа нарса эмас», дедилар.",433,22],["وَم[o[َآ] ءَاتَيْنَ[n[ـٰ]ه[w:1150[ُم م]ِّ[f:11038[ن ك]ُتُ[a:11039[بٍ ي]َ[q:11040[دْ]رُسُونَهَاۖ وَم[o[َآ] أَرْسَلْن[o[َآ] إِلَيْهِمْ قَ[q:7849[بْ]لَكَ م[a:10183[ِن ن]َّذ[p[ِي]رٍ","Ҳолбуки Биз уларга дарс оладиган китобларни бермаган эдик. Шунингдек, сендан олдин уларга бирор огоҳлантиргувчи ҳам юбормаган эдик.",433,22],["وَكَذَّبَ [h:11041[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ وَمَا بَلَغُو[s[اْ] مِعْشَارَ م[o[َآ] ءَاتَيْنَ[n[ـٰ]هُمْ فَكَذَّبُو[s[اْ] رُسُلِىۖ فَكَيْفَ كَانَ نَك[p[ِي]رِ","Улардан илгари ўтганлар ҳам ёлғончи қилган эдилар. уларга берган нарсаларимизнинг ўндан бирига ҳам етганлари йўқ. Бас, Пайғамбарларимни ёлғончи қилдилар, аммо Менинг инкорим қандоқ бўлди?!",433,22],["۞ قُلْ إِ[g[نّ]َم[o[َآ] أَعِظُك[c:11042[ُم ب]ِو[n[َٲ]حِدَةٍۖ أَ[f:11043[ن ت]َقُومُو[s[اْ] لِلَّهِ مَثْنَىٰ وَفُر[n[َٲ]دَىٰ ثُ[g[مّ]َ تَتَفَكَّرُو[s[اْۚ] مَا بِصَاحِبِك[w:11044[ُم م]ِّ[f:5163[ن ج]ِ[g[نّ]َةٍۚ إِنْ هُوَ إِلَّا نَذِي[u:11045[رٌ ل]َّك[c:11046[ُم ب]َيْنَ يَدَىْ عَذَا[f:7040[بٍ ش]َد[p[ِي][q[د]ٍ","Сен: «Мен сизга биргина насиҳат қиламан: Аллоҳ учун холис, якка-якка ва тўп-тўп туриб бир фикр юритиб кўринглар. Соҳибингизда жинга оид ҳеч нарса йўқ. У сизларга шиддатли азобдан олдинги огоҳлантиргувчи, холос», деб айт.",433,22],["قُلْ مَا سَأَلْتُك[w:6132[ُم م]ِّنْ أَ[q:6133[جْ][f:11047[رٍ ف]َهُوَ لَكُمْۖ إِنْ أَ[q:6134[جْ]رِىَ إِلَّا عَلَى [h:412[ٱ]للَّهِۖ وَهُوَ عَلَىٰ كُلِّ ش[f:3903[َىْءٍ ش]َه[p[ِي][q[د]ٌ","Сен: «Мен сизлардан ҳеч бир ажр-ҳақ сўрамадим. Бас, у сизга бўлсин. Менинг ажрим фақат Аллоҳнинг зиммасида. У зот ҳар бир нарсага Ўзи шоҳиддир», деб айт.",433,22],["قُلْ إِ[g[نّ]َ رَبِّى يَ[q:11048[قْ]ذِفُ بِ[h:370[ٱ]لْحَقِّ عَلَّ[n[ـٰ]مُ [h:3865[ٱ]لْغُي[p[ُو][q[ب]ِ","Сен: «Албатта, Роббим ҳақни отур. У зот ғайбларни ўта билгувчидир», деб айт.",433,22],["قُلْ ج[o[َا]ٓءَ [h:5635[ٱ]لْحَقُّ وَمَا يُ[q:10320[بْ]دِئُ [h:11049[ٱ]لْبَ[n[ـٰ]طِلُ وَمَا يُع[p[ِي][q[د]ُ","Сен: «Ҳақ келди! Ботил бошлай олмас ва қайтара ҳам олмас», деб айт.",434,22],["قُلْ إِ[f:11050[ن ض]َلَلْتُ فَإِ[g[نّ]َم[o[َآ] أَضِلُّ عَلَىٰ نَفْسِىۖ وَإِنِ [h:11051[ٱ]هْتَدَيْتُ فَبِمَا يُوح[o[ِىٓ] إِلَىَّ رَبّ[o[ِىٓۚ] إِ[g[نّ]َهُ[n[ۥ] سَمِي[f:11052[عٌ ق]َر[p[ِي][q[ب]ٌ","Сен: «Агар мен залолатга кетган бўлсам, ўз зараримга кетурман. Агар ҳидоят топсам, Роббим менга ваҳий қилган нарса туфайли топурман. Албатта, У зот ўта эшитгувчи, яқиндир», деб айт.",434,22],["وَلَوْ تَرَ[o[ىٰٓ] إِذْ فَزِعُو[s[اْ] فَلَا فَوْتَ وَأُخِذُو[s[اْ] م[a:9578[ِن م]َّكَا[f:11053[نٍ ق]َر[p[ِي][q[ب]ٍ","Агар уларнинг талвасага тушишларини, энди қочиб қутулиш йўқ ва яқин макондан тутилишларини бир кўрсанг эди?",434,22],["وَقَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا بِه[n[ِۦ] وَأَ[g[نّ]َىٰ لَهُمُ [h:11054[ٱ][l[ل]تَّنَاوُشُ م[a:9578[ِن م]َّكَا[i:9579[نِۭ ب]َع[p[ِي][q[د]ٍ","Улар: «Унга иймон келтирдик», дерлар. Энди, узоқ бир макондан қўллари қандоқ етсин?!",434,22],["وَقَ[q:387[دْ] كَفَرُو[s[اْ] بِه[n[ِۦ] مِ[f:128[ن ق]َ[q:129[بْ]لُۖ وَيَ[q:11055[قْ]ذِفُونَ بِ[h:13[ٱ]لْغَيْبِ م[a:9578[ِن م]َّكَا[i:9579[نِۭ ب]َع[p[ِي][q[د]ٍ","Ҳолбуки, унга олдин куфр келтирган эдилар. Ғойибга узоқ жойдан тош отар эдилар.",434,22],["وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِه[w:11056[ِم م]ِّ[f:128[ن ق]َ[q:129[بْ]لُۚ إِ[g[نّ]َهُمْ كَانُو[s[اْ] فِى شَ[a:11057[كٍّ م]ُّر[p[ِي][q[ب]ِۭ","Ва улар билан ўзлари иштаҳа қилган нарсанинг ораси тўсилди. Худди олдин ўтган маслакдошлари каби. Албатта, улар шак-шубҳа ичида эдилар.",434,22]]},{"n":35,"ar":"فَاطِرٍ","en":"Faatir","uz":"Фотир","type":"Макка","ayahs":[["ٱلْحَمْدُ لِلَّهِ فَاطِرِ [h:3956[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ جَاعِلِ [h:11058[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةِ رُسُلاً أُ[s[وْ]ل[o[ِىٓ] أَ[q:11059[جْ]نِحَ[a:11060[ةٍ م]َّثْنَىٰ وَثُلَ[n[ـٰ]ثَ وَرُبَ[n[ـٰ]عَۚ يَزِيدُ فِى [h:4788[ٱ]لْخَلْقِ مَا يَش[o[َا]ٓءُۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Ҳамду сано осмонлару ерни йўқдан бор қилган, фаришталарни икки, уч, тўрт қанотли элчилар қилган Аллоҳга бўлсин. У зот махлуқотларда нимани хоҳласа, зиёда қиладир. Албатта, Аллоҳ ҳар бир нарсага қодирдир.",434,22],["مَّا يَفْتَحِ [h:11061[ٱ]للَّهُ لِل[g[نّ]َاسِ م[u:11062[ِن ر]َّحْمَ[f:11063[ةٍ ف]َلَا مُمْسِكَ لَهَاۖ وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُ[n[ۥ] م[i:254[ِنۢ ب]َعْدِهِ[n[ۚۦ] وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Аллоҳ одамларга не раҳматни очса, бас, уни тутиб қолгувчи бўлмас. У зот тутиб қолган нарсани Ундан кейин қўйиб юборгувчи бўлмас. У зот азизу ҳакиймдир.",434,22],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ [h:11064[ٱ]ذْكُرُو[s[اْ] نِعْمَتَ [h:1300[ٱ]للَّهِ عَلَيْكُمْۚ هَلْ مِنْ خَ[n[ـٰ]لِقٍ غَيْرُ [h:4057[ٱ]للَّهِ يَرْزُقُك[w:6034[ُم م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِۚ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَۖ فَأَ[g[نّ]َىٰ تُؤْفَك[p[ُو]نَ","Эй одамлар! Аллоҳнинг сизга берган неъматларини эсланг! Аллоҳдан бошқа сизларга осмон ва ердан ризқ берадиган холиқ борми? Ундан ўзга ибодатга сазовор зот йўқ. Бас, қаён кетмоқдасиз?!",434,22],["وَإ[a:9047[ِن ي]ُكَذِّبُوكَ فَقَ[q:563[دْ] كُذِّبَتْ رُسُ[a:2469[لٌ م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَۚ وَإِلَى [h:1148[ٱ]للَّهِ تُرْجَعُ [h:1149[ٱ]لْأُم[p[ُو]رُ","Агар сени ёлғончига чиқарсалар, бас, сендан олдин ҳам Пайғамбарлар ёлғончи қилинганлар. Барча ишлар Аллоҳга қайтарилур.",435,22],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ إِ[g[نّ]َ وَعْدَ [h:3149[ٱ]للَّهِ حَ[f:10612[قٌّۖ ف]َلَا تَغُرَّ[g[نّ]َكُمُ [h:10613[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَاۖ وَلَا يَغُرَّ[g[نّ]َك[c:10614[ُم ب]ِ[h:32[ٱ]للَّهِ [h:10615[ٱ]لْغَر[p[ُو]رُ","Эй одамлар! Албатта, Аллоҳнинг ваъдаси ҳақдир. Бу дунё ҳаёти сизларни ғурурга кетказмасин. Сизларни ўта ғурурга кетказгувчи Аллоҳ ҳақида алдаб қўймасин.",435,22],["إِ[g[نّ]َ [h:4634[ٱ][l[ل]شَّيْطَ[n[ـٰ]نَ لَكُمْ عَدُ[f:11065[وٌّ ف]َ[h:11066[ٱ]تَّخِذُوهُ عَدُوًّاۚ إِ[g[نّ]َمَا يَ[q:1242[دْ]عُو[s[اْ] حِزْبَهُ[n[ۥ] لِيَكُونُو[s[اْ] مِنْ أَصْحَ[n[ـٰ]بِ [h:11067[ٱ][l[ل]سَّع[p[ِي]رِ","Албатта, шайтон сизга душмандир. Бас, уни душман тутинг. У ўз гуруҳини фақат ўта қизиган дўзахга эга бўлишларига чақиради.",435,22],["ٱلَّذِينَ كَفَرُو[s[اْ] لَهُمْ عَذَا[f:1727[بٌ ش]َدِي[a:11068[دٌۖ و]َ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَه[w:3412[ُم م]َّغْفِرَ[a:3413[ةٌ و]َأَ[q:3414[جْ][f:6259[رٌ ك]َب[p[ِي]رٌ","Куфр келтирганларга шиддатли азоб бордир. Иймон келтириб, солиҳ амалларни қилганларга мағфират ва улкан ажр бордир.",435,22],["أَفَمَ[f:11069[ن ز]ُيِّنَ لَهُ[n[ۥ] س[o[ُو]ٓءُ عَمَلِه[n[ِۦ] فَرَءَاهُ حَسَ[f:11070[نًاۖ ف]َإِ[g[نّ]َ [h:513[ٱ]للَّهَ يُضِلُّ م[a:476[َن ي]َش[o[َا]ٓءُ وَيَهْدِى م[a:476[َن ي]َش[o[َا]ٓءُۖ فَلَا تَذْهَ[q:11071[بْ] نَفْسُكَ عَلَيْهِمْ حَسَر[n[َٲ]تٍۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلِي[i:6056[مُۢ ب]ِمَا يَصْنَع[p[ُو]نَ","Ахир, қилган ёмон амали ўзига зийнатлаб кўрсатилиб, уни гўзал деб билган одам?! Албатта, Аллоҳ хоҳлаган кимсани залолатга кетказур, хоҳлаган кимсани ҳидоятга солур. Бас, уларга жонинг ҳасрат-ла ачинмасин. Албатта, Аллоҳ нима қилаётганларини яхши билгувчидир.",435,22],["وَ[h:9999[ٱ]للَّهُ [h:11072[ٱ]لَّذ[o[ِىٓ] أَرْسَلَ [h:9659[ٱ][l[ل]رِّيَ[n[ـٰ]حَ فَتُثِيرُ سَحَا[f:11073[بًا ف]َسُ[q:11074[قْ]نَ[n[ـٰ]هُ إِلَىٰ بَلَ[a:11075[دٍ م]َّيِّ[f:11076[تٍ ف]َأَحْيَيْنَا بِهِ [h:842[ٱ]لْأَرْضَ بَعْدَ مَوْتِهَاۚ كَذ[n[َٲ]لِكَ [h:11077[ٱ][l[ل][g[نّ]ُش[p[ُو]رُ","Аллоҳ шамолларни юборган зотдир. Бас, улар булутни қўзғатур. Биз уни ўлик юрт томон ҳайдаб, у билан ерни ўлиб ётганидан кейин тирилтирамиз. Тирилиш ҳам шунга ўхшашдир.",435,22],["مَ[f:506[ن ك]َانَ يُرِيدُ [h:11078[ٱ]لْعِزَّةَ فَلِلَّهِ [h:11079[ٱ]لْعِزَّةُ جَمِيعًاۚ إِلَيْهِ يَصْعَدُ [h:11080[ٱ]لْكَلِمُ [h:11081[ٱ][l[ل]طَّيِّبُ وَ[h:11082[ٱ]لْعَمَلُ [h:11083[ٱ][l[ل]صَّ[n[ـٰ]لِحُ يَرْفَعُهُۚ[n[ۥ] وَ[h:37[ٱ]لَّذِينَ يَمْكُرُونَ [h:11084[ٱ][l[ل]سَّيِّـَٔـاتِ لَهُمْ عَذَا[f:1727[بٌ ش]َدِي[a:11085[دٌۖ و]َمَكْرُ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُوَ يَب[p[ُو]رُ","Кимки иззат истаса, бас, барча иззат Аллоҳникидир. Унга хуш каломлар юксалур ва солиҳ амал кўтарур уни. Макр ила ёмонликлар қилганларга шиддатли азоб бордир. Ана ўшаларнинг макри ботил бўлур.",435,22],["وَ[h:9999[ٱ]للَّهُ خَلَقَك[w:2530[ُم م]ِّ[f:1972[ن ت]ُرَا[f:1973[بٍ ث]ُ[g[مّ]َ م[a:7325[ِن ن]ُّ[q:7326[طْ]فَ[f:8077[ةٍ ث]ُ[g[مّ]َ جَعَلَكُمْ أَزْو[n[َٲ][a:11086[جًاۚ و]َمَا تَحْمِلُ مِنْ أُ[f:1867[نث]َىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِ[n[ۚۦ] وَمَا يُعَ[g[مّ]َرُ م[a:11087[ِن م]ُّعَ[g[مّ]َ[a:11088[رٍ و]َلَا يُ[f:11089[نق]َصُ مِنْ عُمُرِه[o[ِۦٓ] إِلَّا فِى كِتَ[n[ـٰ]بٍۚ إِ[g[نّ]َ ذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ يَس[p[ِي]رٌ","Аллоҳ сизларни тупроқдан, сўнгра нутфадан яратиб, кейин жуфт-жуфт қилиб қўйди. Қайси бир урғочи нимага ҳомиладор бўлса, нимани туғса, фақат Унинг илми билан бўлур. Ҳар бир умр кўргувчига умр берилиши ёки унинг умрининг қисқартилиши албатта китобда бордир. Албатта, бу Аллоҳга осондир.",435,22],["وَمَا يَسْتَوِى [h:11090[ٱ]لْبَحْرَانِ هَ[n[ـٰ]ذَا عَذْ[f:9670[بٌ ف]ُرَا[f:11091[تٌ س][o[َا]ٓئِ[f:11092[غٌ ش]َرَابُهُ[n[ۥ] وَهَ[n[ـٰ]ذَا مِلْحٌ أُجَا[a:11093[جٌۖ و]َمِ[f:11094[ن ك]ُ[f:11095[لٍّ ت]َأْكُلُونَ لَحْ[f:7349[مًا ط]َرِي[a:11096[ًّا و]َتَسْتَخْرِجُونَ حِلْيَ[f:7351[ةً ت]َلْبَسُونَهَاۖ وَتَرَى [h:7352[ٱ]لْفُلْكَ فِيهِ مَوَاخِرَ لِتَ[q:7694[بْ]تَغُو[s[اْ] مِ[f:475[ن ف]َضْلِه[n[ِۦ] وَلَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Дарё-денгиз иккиси тенг бўла олмас. Буниси тотли, чанқоқ босар, ичиш осондир. Буниси эса шўр, тахирдир. Сиз ҳар биридан тоза гўшт ейсиз ва тақинчоқ чиқариб тақурсиз. Ва Унинг фазлидан талаб қилишингиз учун уни ёриб кетаётган кемаларни кўрурсиз. Шоядки, шукр қилсангиз.",436,22],["يُولِجُ [h:9084[ٱ]لَّيْلَ فِى [h:1829[ٱ][l[ل][g[نّ]َهَارِ وَيُولِجُ [h:9085[ٱ][l[ل][g[نّ]َهَارَ فِى [h:1831[ٱ]لَّيْلِ وَسَخَّرَ [h:6864[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ كُ[a:6865[لٌّ ي]َ[q:6866[جْ]رِى لِأَجَ[a:6867[لٍ م]ُّسَم[f:11097[ًّىۚ ذ][n[َٲ]لِكُمُ [h:4260[ٱ]للَّهُ رَبُّكُمْ لَهُ [h:1397[ٱ]لْمُلْكُۚ وَ[h:37[ٱ]لَّذِينَ تَ[q:4040[دْ]عُونَ مِ[f:3136[ن د]ُونِه[n[ِۦ] مَا يَمْلِكُونَ مِ[f:11098[ن ق]ِ[q:11099[طْ]م[p[ِي]رٍ","У зот кечани кундузга, кундузни кечага киритур, қуёш ва ойни беминнат хизматкор қилиб қўйгандир. Ҳар бири белгиланган муддатгача юрадир. Ана шу Аллоҳ–Роббингиздир. Мулк Уникидир. Ундан ўзга илтижо қилаётганларингиз эса, данак пўстлоғига ҳам молик эмаслар.",436,22],["إِ[f:11100[ن ت]َ[q:5192[دْ]عُوهُمْ لَا يَسْمَعُو[s[اْ] دُع[o[َا]ٓءَكُمْ وَلَوْ سَمِعُو[s[اْ] مَا [h:11101[ٱ]سْتَجَابُو[s[اْ] لَكُمْۖ وَيَوْمَ [h:443[ٱ]لْقِيَ[n[ـٰ]مَةِ يَكْفُرُونَ بِشِرْكِكُمْۚ وَلَا يُنَبِّئُكَ مِثْلُ خَب[p[ِي]رٍ","Агар уларга дуо қилсангиз, дуоингизни эшитмаслар. Гап эшитсалар ҳам, сизга жавоб бера олмаслар. Қиёмат куни эса, сизнинг уларни ширк келтирганингизни инкор этурлар. Ўта хабардор зотдек ҳеч ким сенга хабар бера олмас.",436,22],["۞ يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ أَ[f:8796[نت]ُمُ [h:11102[ٱ]لْفُقَر[o[َا]ٓءُ إِلَى [h:1637[ٱ]للَّهِۖ وَ[h:72[ٱ]للَّهُ هُوَ [h:6121[ٱ]لْغَنِىُّ [h:9093[ٱ]لْحَم[p[ِي][q[د]ُ","Эй одамлар! Сизлар Аллоҳга муҳтождирсиз. Аллоҳ эса, Ўзи беҳожат ва мақталган зотдир.",436,22],["إ[a:3197[ِن ي]َشَأْ يُذْهِ[q:3198[بْ]كُمْ وَيَأْتِ بِخَلْ[f:7086[قٍ ج]َد[p[ِي][q[د]ٍ","Агар У зот хоҳласа, сизни кетказиб, янги бир халқни келтирур.",436,22],["وَمَا ذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ بِعَز[p[ِي]زٍ","Ва бу Аллоҳ учун қийин эмас.",436,22],["وَلَا تَزِرُ وَازِرَ[a:4572[ةٌ و]ِزْرَ أُخْرَىٰۚ وَإِ[f:11103[ن ت]َ[q:6220[دْ]عُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ ش[a:11104[َىْءٌ و]َلَوْ كَانَ ذَا قُرْبَ[o[ىٰٓۗ] إِ[g[نّ]َمَا تُ[f:11105[نذ]ِرُ [h:11106[ٱ]لَّذِينَ يَخْشَوْنَ رَبَّه[c:8779[ُم ب]ِ[h:13[ٱ]لْغَيْبِ وَأَقَامُو[s[اْ] [h:1641[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَۚ وَمَ[f:11107[ن ت]َزَكَّىٰ فَإِ[g[نّ]َمَا يَتَزَكَّىٰ لِنَفْسِهِ[n[ۚۦ] وَإِلَى [h:1148[ٱ]للَّهِ [h:1842[ٱ]لْمَص[p[ِي]رُ","Ўзи юкли жон ўзга жоннинг юкини кўтара олмас. Юки оғир жон ўз юкига чақирса-да, ундан ҳеч бир нарса кўтарилмас. Гарчи қариндош бўлса ҳам. Сен фақат ғайбдаги Роббиларидан қўрқадиган ва намозни тўкис адо этганларни огоҳлантирурсан. Ким покланса, Ўзи учун покланур. Қайтиш Аллоҳгадир.",436,22],["وَمَا يَسْتَوِى [h:4068[ٱ]لْأَعْمَىٰ وَ[h:4069[ٱ]لْبَص[p[ِي]رُ","Кўр билан кўзи очиқ тенг бўлмас.",437,22],["وَلَا [h:11108[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تُ وَلَا [h:11109[ٱ][l[ل][g[نّ][p[ُو]رُ","Зулумотлар билан нур ҳам.",437,22],["وَلَا [h:11110[ٱ][l[ل]ظِّلُّ وَلَا [h:11111[ٱ]لْحَر[p[ُو]رُ","Соя билан жазирама ҳам.",437,22],["وَمَا يَسْتَوِى [h:11112[ٱ]لْأَحْي[o[َا]ٓءُ وَلَا [h:11113[ٱ]لْأَمْو[n[َٲ]تُۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُسْمِعُ م[a:476[َن ي]َش[o[َا]ٓءُۖ وَم[o[َآ] أَ[f:169[نت]َ بِمُسْمِ[a:11114[عٍ م]َّ[f:2074[ن ف]ِى [h:8926[ٱ]لْقُب[p[ُو]رِ","Тириклар билан ўликлар тенг бўлмас. Албатта, Аллоҳ хоҳлаган кимсага эшиттирур. Сен қабрлардаги кимсаларга эшиттиргувчи эмассан.",437,22],["إِنْ أَ[f:169[نت]َ إِلَّا نَذ[p[ِي]رٌ","Сен фақат огоҳлантиргувчисан, холос.",437,22],["إِ[g[نّ][o[َآ] أَرْسَلْنَ[n[ـٰ]كَ بِ[h:370[ٱ]لْحَقِّ بَشِي[a:622[رًا و]َنَذِي[a:11115[رًاۚ و]َإ[a:3281[ِن م]ِّنْ أُ[g[مّ]َةٍ إِلَّا خَلَا فِيهَا نَذ[p[ِي]رٌ","Албатта, Биз сени ҳақ ила хушхабарчи ва огоҳлантиргувчи этиб юбордик. Қайси бир умматки бўлса, унда огоҳлантиргувчи бўлган.",437,22],["وَإ[a:9047[ِن ي]ُكَذِّبُوكَ فَقَ[q:563[دْ] كَذَّبَ [h:4507[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ ج[o[َا]ٓءَتْهُمْ رُسُلُه[c:4900[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ وَبِ[h:11116[ٱ][l[ل]زُّبُرِ وَبِ[h:11117[ٱ]لْكِتَ[n[ـٰ]بِ [h:11118[ٱ]لْمُن[p[ِي]رِ","Агар сени ёлғончи қилсалар, бас, батаҳқиқ, улардан олдин ўтганлар ҳам ёлғончи қилганлар. Ҳолбуки, Пайғамбарлари уларга равшан мўъжизалар, саҳифалар ва нурли китоб келтирган эдилар.",437,22],["ثُ[g[مّ]َ أَخَذْتُ [h:11119[ٱ]لَّذِينَ كَفَرُو[s[اْۖ] فَكَيْفَ كَانَ نَك[p[ِي]رِ","Сўнгра куфр келтирганларни тутдим. Бас, Менинг инкорим қандоқ бўлди?!",437,22],["أَلَمْ تَرَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ أَ[f:471[نز]َلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:4278[ءً ف]َأَخْرَ[q:4279[جْ]نَا بِه[n[ِۦ] ثَمَر[n[َٲ][a:11120[تٍ م]ُّخْتَلِفًا أَلْو[n[َٲ]نُهَاۚ وَمِنَ [h:11121[ٱ]لْجِبَالِ جُدَ[i:11122[دُۢ ب]ِي[a:11123[ضٌ و]َحُمْ[a:11124[رٌ م]ُّخْتَلِفٌ أَلْو[n[َٲ]نُهَا وَغَرَابِيبُ س[p[ُو][q[د]ٌ","Аллоҳнинг осмондан сув туширганини кўрмадингми? Бас, у ила турли ранглардаги меваларни ва тоғлардан ҳам йўл-йўл, оқ ҳамда қизилнинг турли рангларини ва қоп-қораларини чиқардик.",437,22],["وَمِنَ [h:30[ٱ][l[ل][g[نّ]َاسِ وَ[h:11125[ٱ][l[ل]دَّو[m[َا]ٓبِّ وَ[h:1778[ٱ]لْأَنْعَ[n[ـٰ]مِ مُخْتَلِفٌ أَلْو[n[َٲ]نُهُ[n[ۥ] كَذ[n[َٲ]لِكَۗ إِ[g[نّ]َمَا يَخْشَى [h:11126[ٱ]للَّهَ مِنْ عِبَادِهِ [h:11127[ٱ]لْعُلَمَ[o[ـٰٓ]ؤُ[s[اْ]ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَزِيزٌ غَف[p[ُو]رٌ","Шунингдек, одамлардан, ҳайвонлардан ва чорвалардан ҳам турли ранглардагиларини чиқардик. Аллоҳдан бандалари ичидан фақат олимларигина қўрқарлар. Албатта, Аллоҳ азиз ва ўта мағфиратли зотдир.",437,22],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَتْلُونَ كِتَ[n[ـٰ]بَ [h:525[ٱ]للَّهِ وَأَقَامُو[s[اْ] [h:1641[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَأَ[f:2789[نف]َقُو[s[اْ] مِ[g[مّ]َا رَزَ[q:15[قْ]نَ[n[ـٰ]هُمْ سِر[a:1623[ًّا و]َعَلَانِيَ[a:11128[ةً ي]َرْجُونَ تِجَ[n[ـٰ]رَ[u:11129[ةً ل]َّ[f:11130[ن ت]َب[p[ُو]رَ","Албатта, Аллоҳнинг китобини тиловат қиладиганлар, намозни тўкис адо этиб, Биз уларга ризқ қилиб берган нарсалардан махфий ва ошкора инфоқ қилганлар, ҳаргиз касодга учрамайдиган тижоратдан умидвор бўлурлар.",437,22],["لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَه[w:9444[ُم م]ِّ[f:475[ن ف]َضْلِهِ[o[ۚۦٓ] إِ[g[نّ]َهُ[n[ۥ] غَفُو[f:11131[رٌ ش]َك[p[ُو]رٌ","Чунки У зот уларга ажрларини тўлиқ қилиб берур ва Ўз фазлидан зиёда ҳам қилур. Албатта, У ўта мағфиратли ва ўта шукр қилгувчидир.",437,22],["وَ[h:9999[ٱ]لَّذ[o[ِىٓ] أَوْحَيْن[o[َآ] إِلَيْكَ مِنَ [h:891[ٱ]لْكِتَ[n[ـٰ]بِ هُوَ [h:8923[ٱ]لْحَقُّ مُصَدِّ[u:206[قًا ل]ِّمَا بَيْنَ يَدَيْهِۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ بِعِبَادِه[n[ِۦ] لَخَبِي[i:11132[رُۢ ب]َص[p[ِي]رٌ","Биз сенга ваҳий қилган китоб айни ҳақдир, ўзидан олдинги нарсани тасдиқловчи бўлгандир. Албатта, Аллоҳ Ўз бандаларидан ўта хабардор ва уларни ўта кўргувчидир.",438,22],["ثُ[g[مّ]َ أَوْرَثْنَا [h:11133[ٱ]لْكِتَ[n[ـٰ]بَ [h:11134[ٱ]لَّذِينَ [h:11135[ٱ]صْطَفَيْنَا مِنْ عِبَادِنَاۖ فَمِنْهُمْ ظَالِ[u:8069[مٌ ل]ِّنَفْسِه[n[ِۦ] وَمِنْه[w:11136[ُم م]ُّ[q:10606[قْ]تَصِ[a:11137[دٌ و]َمِنْهُمْ سَابِ[i:11138[قُۢ ب]ِ[h:11139[ٱ]لْخَيْر[n[َٲ]تِ بِإِذْنِ [h:509[ٱ]للَّهِۚ ذ[n[َٲ]لِكَ هُوَ [h:11140[ٱ]لْفَضْلُ [h:11141[ٱ]لْكَب[p[ِي]رُ","Сўнгра бу китобни Ўз бандаларимиздан танлаб олганларимизга мерос қилдик. Бас, улардан ўзига ўзи зулм қилувчилари бор, улардан ўртачалари бор ва улардан Аллоҳнинг изни ила яхшиликларга ўзувчилар ҳам бор. Ана шу айни улуғ фазлдир.",438,22],["جَ[g[نّ]َ[n[ـٰ]تُ عَ[q:5720[دْ][a:6962[نٍ ي]َ[q:6963[دْ]خُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِ[f:8050[ن ذ]َهَ[a:8971[بٍ و]َلُؤْلُ[a:8972[ؤًاۖ و]َلِبَاسُهُمْ فِيهَا حَر[p[ِي]رٌ","Улар адн жаннатларига кирурлар. Унда тилло билакузуклар ва инжулар ила безатилажаклар. Унда либослари ипакдир.",438,22],["وَقَالُو[s[اْ] [h:4698[ٱ]لْحَمْدُ لِلَّهِ [h:3912[ٱ]لَّذ[o[ِىٓ] أَذْهَبَ عَ[g[نّ]َا [h:11142[ٱ]لْحَزَنَۖ إِ[g[نّ]َ رَبَّنَا لَغَفُو[f:11143[رٌ ش]َك[p[ُو]رٌ","Улар: «Биздан ғам-қайғуни кетказган Аллоҳга ҳамду сано бўлсин. Албатта, Роббимиз ўта мағфиратли ва ўта шукр қилгувчидир.",438,22],["ٱلَّذ[o[ِىٓ] أَحَلَّنَا دَارَ [h:11144[ٱ]لْمُقَامَةِ مِ[f:475[ن ف]َضْلِه[n[ِۦ] لَا يَمَسُّنَا فِيهَا نَصَ[a:5892[بٌ و]َلَا يَمَسُّنَا فِيهَا لُغ[p[ُو][q[ب]ٌ","У зот бизларни Ўз фазли ила бир турар жойга жойлаштирдики, у ерда бизга чарчоқ ҳам етмас, ҳорғинлик ҳам етмас», дерлар.",438,22],["وَ[h:9999[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَهُمْ نَارُ جَهَ[g[نّ]َمَ لَا يُ[q:8625[قْ]ضَىٰ عَلَيْهِمْ فَيَمُوتُو[s[اْ] وَلَا يُخَفَّفُ عَنْه[w:11145[ُم م]ِّنْ عَذَابِهَاۚ كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى كُلَّ كَف[p[ُو]رٍ","Куфр келтирганларга жаҳаннам оташи бордир. Уларга на ўлишлари учун ҳукм қилинмас ва на улардан у нинг азобидан енгиллатилмас. Ҳар бир кофирни шундоқ жазолармиз.",438,22],["وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّن[o[َآ] أَخْرِ[q:2927[جْ]نَا نَعْمَلْ صَ[n[ـٰ]لِحًا غَيْرَ [h:287[ٱ]لَّذِى كُ[g[نّ]َا نَعْمَلُۚ أَوَلَمْ نُعَ[g[مّ]ِرْك[w:11146[ُم م]َّا يَتَذَكَّرُ فِيهِ مَ[f:11147[ن ت]َذَكَّرَ وَج[o[َا]ٓءَكُمُ [h:11148[ٱ][l[ل][g[نّ]َذِيرُۖ فَذُوقُو[s[اْ] فَمَا لِلظَّ[n[ـٰ]لِمِينَ م[a:9103[ِن ن]َّص[p[ِي]رٍ","Улар у ерда: «Эй Роббимиз! Бизларни чиқар! Қилиб юрган амалларимиздан бошқа, солиҳ амаллар қилурмиз!» деб доду фарёд солурлар. «Сизларга эслайдиган одам эслагудек умр бермаган эдикми?! Сизларга огоҳлантиргувчи келмаган эдими?! Бас, энди, тотийверинглар! Золимларга ҳеч бир ёрдамчи йўқдир».",438,22],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَ[n[ـٰ]لِمُ غَيْبِ [h:11149[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِۚ إِ[g[نّ]َهُ[n[ۥ] عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","Албатта, Аллоҳ осмонлару ернинг ғайбини билгувчидир. Албатта, У диллардаги сирларни ҳам ўта билгувчидир.",438,22],["هُوَ [h:153[ٱ]لَّذِى جَعَلَكُمْ خَلَ[o[ـٰٓ]ئِفَ فِى [h:44[ٱ]لْأَرْضِۚ فَمَ[f:3429[ن ك]َفَرَ فَعَلَيْهِ كُفْرُهُۖ[n[ۥ] وَلَا يَزِيدُ [h:11150[ٱ]لْكَ[n[ـٰ]فِرِينَ كُفْرُهُمْ عِ[f:264[ند]َ رَبِّهِمْ إِلَّا مَ[q:11151[قْ][a:11152[تًاۖ و]َلَا يَزِيدُ [h:11150[ٱ]لْكَ[n[ـٰ]فِرِينَ كُفْرُهُمْ إِلَّا خَسَارًا","У зот сизларни ер юзида халифалар қилиб қўйгандир. Ким куфр келтирса, унинг кофирлиги ўзига зарар. Кофирлар учун куфрлари Роббилари ҳузурида ғазабдан бошқани зиёда қилмас. Кофирлар учун куфрлари зиёндан бошқани зиёда қилмас.",439,22],["قُلْ أَرَءَيْتُمْ شُرَك[o[َا]ٓءَكُمُ [h:11153[ٱ]لَّذِينَ تَ[q:4040[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ أَرُونِى مَاذَا خَلَقُو[s[اْ] مِنَ [h:1579[ٱ]لْأَرْضِ أَمْ لَهُمْ شِرْ[f:11154[كٌ ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ أَمْ ءَاتَيْنَ[n[ـٰ]هُمْ كِتَ[n[ـٰ][f:11155[بًا ف]َهُمْ عَلَىٰ بَيِّنَ[a:11156[تٍ م]ِّنْهُۚ بَلْ إ[a:11157[ِن ي]َعِدُ [h:11158[ٱ][l[ل]ظَّ[n[ـٰ]لِمُونَ بَعْضُه[c:11159[ُم ب]َعْضًا إِلَّا غُرُورًا","Сен: «Менга Аллоҳдан бошқа илтижо қилаётган шерикларингизнинг хабарини беринг-чи?! Менга кўрсатинглар-чи улар ерда нимани яратдилар?! Ёки уларнинг осмонлар шерикликлари борми?! Ёки Биз уларга китоб берганмизу, улар ундан бирон ҳужжатга эга бўлганларми?! Йўқ!!! Золимлар бир-бирларига алдовдан бошқани ваъда қилмаслар», деб айт.",439,22],["۞ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُمْسِكُ [h:11160[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ أَ[f:11161[ن ت]َزُولَاۚ وَلَئِ[f:11162[ن ز]َالَت[o[َآ] إِنْ أَمْسَكَهُمَا مِنْ أَحَ[a:1710[دٍ م]ّ[i:254[ِنۢ ب]َعْدِهِ[o[ۚۦٓ] إِ[g[نّ]َهُ[n[ۥ] كَانَ حَلِيمًا غَفُورًا","Албатта, Аллоҳ осмонлару ерни қулаб тушишларидан ушлаб турур. Агар улар қулайдиган бўлсалар, Ундан ўзга ҳеч ким уларни ушлаб тура олмас. Албатта, У ўта ҳалим ва ўта мағфиратли бўлган зотдир.",439,22],["وَأَ[q:4324[قْ]سَمُو[s[اْ] بِ[h:32[ٱ]للَّهِ جَهْدَ أَيْمَ[n[ـٰ]نِهِمْ لَئِ[f:11163[ن ج][o[َا]ٓءَهُمْ نَذِي[u:11164[رٌ ل]َّيَكُونُ[g[نّ]َ أَهْدَىٰ مِنْ إِحْدَى [h:11165[ٱ]لْأُمَمِۖ فَلَ[g[مّ]َا ج[o[َا]ٓءَهُمْ نَذِي[a:11166[رٌ م]َّا زَادَهُمْ إِلَّا نُفُورًا","Улар жон-жаҳдлари билан, агар ўзларига огоҳлантирувчи келса, ҳар қандай умматдан кўра ҳидоятли бўлишлари ҳақида Аллоҳ номи ила қасам ичар эдилар. Қачонки огоҳлантирувчи келганида, уларда нафратдан бошқани зиёда қилмади.",439,22],["ٱسْتِكْبَا[f:11167[رًا ف]ِى [h:44[ٱ]لْأَرْضِ وَمَكْرَ [h:11168[ٱ][l[ل]سَّيِّىِٕۚ وَلَا يَحِيقُ [h:11169[ٱ]لْمَكْرُ [h:11170[ٱ][l[ل]سَّيِّئُ إِلَّا بِأَهْلِهِ[n[ۚۦ] فَهَلْ يَ[f:1141[نظ]ُرُونَ إِلَّا سُ[g[نّ]َتَ [h:11171[ٱ]لْأَوَّلِينَۚ فَلَ[f:2843[ن ت]َجِدَ لِسُ[g[نّ]َتِ [h:11172[ٱ]للَّهِ تَ[q:10752[بْ]دِيل[a:11173[اًۖ و]َلَ[f:3232[ن ت]َجِدَ لِسُ[g[نّ]َتِ [h:11172[ٱ]للَّهِ تَحْوِيلاً","Ер юзида мутакаббирлик ва ёмон макр учун. Ёмон макр эса, фақат ўз эгасига қайтадир. Улар фақат илгаригиларнинг суннатига интизор бўлмоқдалар, холос. Аллоҳнинг суннатига ҳаргиз бадал топа олмассан. Аллоҳнинг суннатига ҳаргиз ўзгартириш топа олмассан.",439,22],["أَوَلَمْ يَسِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَيَ[f:6853[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6854[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ وَكَان[o[ُوٓ][s[اْ] أَشَدَّ مِنْهُمْ قُوَّۚ[a:11174[ةً و]َمَا كَانَ [h:742[ٱ]للَّهُ لِيُعْجِزَهُ[n[ۥ] مِ[f:2103[ن ش][f:5402[َىْءٍ ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَلَا فِى [h:44[ٱ]لْأَرْضِۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ عَلِي[f:11175[مًا ق]َدِيرًا","Улар ер юзида сайр қилиб юриб ўзларидан олдин ўтганларнинг оқибати қандоқ бўлганига назар солмайдиларми?! Ҳолбуки ўшалар булардан кўра қувватлари кўп бўлган эдилар. На осмонларда ва на ерда бирор нарса Аллоҳни ожиз қолдира олмас. Албатта, У зот ўта илмли ва ўта қодирдир.",439,22],["وَلَوْ يُؤَاخِذُ [h:7452[ٱ]للَّهُ [h:7453[ٱ][l[ل][g[نّ]َاسَ بِمَا كَسَبُو[s[اْ] مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِ[f:4026[ن د][m[َا]ٓبَّ[a:7455[ةٍ و]َلَ[n[ـٰ]ك[a:7456[ِن ي]ُؤَخِّرُهُمْ إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَم[f:7457[ًّىۖ ف]َإِذَا ج[o[َا]ٓءَ أَجَلُهُمْ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ كَانَ بِعِبَادِه[n[ِۦ] بَصِيرَۢا","Агар Аллоҳ одамларни қилганларига яраша оладиган бўлса, ер устида қимир этган жониворни қўймас эди. Лекин уларни белгиланган муддатгача қўйиб қўюр. Ўша ажаллари келганда эса... Бас, албатта, Аллоҳ бандаларини кўриб тургувчи зотдир.",440,22]]},{"n":36,"ar":"يسٓ","en":"Yaseen","uz":"Ёсин","type":"Макка","ayahs":[["ي[m[سٓ]","Йасин.",440,22],["وَ[h:9999[ٱ]لْقُرْءَانِ [h:11176[ٱ]لْحَك[p[ِي]مِ","Қуръони Ҳаким ила қасам.",440,22],["إِ[g[نّ]َكَ لَمِنَ [h:1443[ٱ]لْمُرْسَل[p[ِي]نَ","Албатта, сен Пайғамбарлардандирсан.",440,22],["عَلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Сироти мустақиймдасан.",440,22],["تَ[f:11177[نز]ِيلَ [h:11178[ٱ]لْعَزِيزِ [h:9869[ٱ][l[ل]رَّح[p[ِي]مِ","Бу Азизу Раҳимнинг нозил қилганидир.",440,22],["لِتُ[f:4582[نذ]ِرَ قَوْ[a:10181[مًا م]ّ[o[َآ] أُ[f:11179[نذ]ِرَ ءَاب[o[َا]ٓؤُهُمْ فَهُمْ غَ[n[ـٰ]فِل[p[ُو]نَ","Ота-боболари огоҳлантирилмаган, ўзлари эса, ғофил бўлган қавмларни огоҳлантиришинг учун.",440,22],["لَقَ[q:2389[دْ] حَقَّ [h:10639[ٱ]لْقَوْلُ عَلَ[o[ىٰٓ] أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِن[p[ُو]نَ","Батаҳқиқ, уларнинг кўпларига сўз ҳақ бўлди. Бас, улар иймон келтирмаслар.",440,22],["إِ[g[نّ]َا جَعَلْنَا ف[o[ِىٓ] أَعْنَ[n[ـٰ]قِهِمْ أَغْلَ[n[ـٰ]ل[f:11180[اً ف]َهِىَ إِلَى [h:11181[ٱ]لْأَذْقَانِ فَه[w:11182[ُم م]ُّ[q:11183[قْ]مَح[p[ُو]نَ","Биз уларнинг бўйинларига кишанлар солдик. Улар иякларигача етади. Бас, улар кўзлари юмуқ, осмонга қараб ғўдайиб қолдилар.",440,22],["وَجَعَلْنَا م[i:4612[ِنۢ ب]َيْنِ أَيْدِيهِمْ سَد[a:11184[ًّا و]َمِنْ خَلْفِهِمْ سَد[f:11185[ًّا ف]َأَغْشَيْنَ[n[ـٰ]هُمْ فَهُمْ لَا يُ[q:60[بْ]صِر[p[ُو]نَ","Ва Биз уларнинг олдиларидан ҳам тўсиқ қилдик, орқаларидан ҳам тўсиқ қилдик, кўзларига парда тортдик. Бас, улар кўрмаслар.",440,22],["وَسَو[o[َا]ٓءٌ عَلَيْهِمْ ءَأَ[f:25[نذ]َرْتَهُمْ أَمْ لَمْ تُ[f:26[نذ]ِرْهُمْ لَا يُؤْمِن[p[ُو]نَ","Уларни огоҳлантирсанг ҳам, огоҳлантирмасанг ҳам, улар учун барибир, иймонга келмаслар.",440,22],["إِ[g[نّ]َمَا تُ[f:11105[نذ]ِرُ مَنِ [h:3443[ٱ]تَّبَعَ [h:11186[ٱ][l[ل]ذِّكْرَ وَخَشِىَ [h:11187[ٱ][l[ل]رَّحْمَ[n[ـٰ]نَ بِ[h:13[ٱ]لْغَيْبِۖ فَبَشِّرْهُ بِمَغْفِرَ[a:11188[ةٍ و]َأَ[q:11189[جْ][f:11190[رٍ ك]َر[p[ِي]مٍ","Сен эса, фақат зикр-эслатмага эргашган ва Роҳмандан ғойибона қўрққан кимсани огоҳлантирасан. Бас, унга мағфират ва гўзал ажрнинг хушхабарини бер.",440,22],["إِ[g[نّ]َا نَحْنُ نُحْىِ [h:11191[ٱ]لْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُو[s[اْ] وَءَاثَ[n[ـٰ]رَهُمْۚ وَكُلَّ شَىْءٍ أَحْصَيْنَ[n[ـٰ]هُ ف[o[ِىٓ] إِمَا[a:11192[مٍ م]ُّب[p[ِي]نٍ","Албатта, Биз, Ўзимиз ўликларни тирилтирурмиз ва улар тақдим қилган нарсаларни ва қолдирган асарларни ёзурмиз. Ҳар бир нарсанинг ҳисобини очиқ-ойдин имомда олиб қўйганмиз.",440,22],["وَ[h:9999[ٱ]ضْرِ[q:8060[بْ] لَه[w:8061[ُم م]َّثَلاً أَصْحَ[n[ـٰ]بَ [h:11193[ٱ]لْقَرْيَةِ إِذْ ج[o[َا]ٓءَهَا [h:11194[ٱ]لْمُرْسَل[p[ُو]نَ","Сен уларга Пайғамбарлар шаҳар аҳолисига келган пайтни мисол қилиб келтир.",441,22],["إِذْ أَرْسَلْن[o[َآ] إِلَيْهِمُ [h:11195[ٱ]ثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِ[f:11196[ثٍ ف]َقَال[o[ُوٓ][s[اْ] إِ[g[نّ][o[َآ] إِلَيْك[w:11197[ُم م]ُّرْسَل[p[ُو]نَ","Ўшанда Биз уларга иккитани юборган эдик, улар икковларини ёлғончига чиқардилар. Бас, Биз учинчи билан қувватладик. Шунда: «Албатта, биз сизларга юборилган Пайғамбарлармиз», дедилар.",441,22],["قَالُو[s[اْ] م[o[َآ] أَ[f:428[نت]ُمْ إِلَّا بَشَ[a:7065[رٌ م]ِّثْلُنَا وَم[o[َآ] أَ[f:471[نز]َلَ [h:11198[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ مِ[f:2103[ن ش]َىْءٍ إِنْ أَ[f:428[نت]ُمْ إِلَّا تَكْذِب[p[ُو]نَ","Улар: «Сиз бизга ўхшаган башардан бошқа нарса эмассиз. Роҳман ҳеч нарса нозил қилгани йўқ. Сизлар фақат ёлғон сўзламоқдасиз, холос», дедилар.",441,22],["قَالُو[s[اْ] رَبُّنَا يَعْلَمُ إِ[g[نّ][o[َآ] إِلَيْكُمْ لَمُرْسَل[p[ُو]نَ","Улар: «Роббимиз билади. Албатта, биз сизларга юборилган Пайғамбарлармиз.",441,22],["وَمَا عَلَيْن[o[َآ] إِلَّا [h:3819[ٱ]لْبَلَ[n[ـٰ]غُ [h:3781[ٱ]لْمُب[p[ِي]نُ","Бизнинг зиммамизда очиқ-ойдан етказишдан бошқа нарса йўқ», дедилар.",441,22],["قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا تَطَيَّرْنَا بِكُمْۖ لَئ[u:4195[ِن ل]َّمْ تَ[f:5288[نت]َهُو[s[اْ] لَنَرْجُمَ[g[نّ]َكُمْ وَلَيَمَسَّ[g[نّ]َك[w:11199[ُم م]ِّ[g[نّ]َا عَذَابٌ أَل[p[ِي]مٌ","Улар: «Биз сизлардан бадгумон бўлдик. Агар тўхтамасангиз, албатта, сизни тошбўрон қиламиз ва сизга биздан аламли азоб етади», дедилар.",441,22],["قَالُو[s[اْ] طَ[o[ـٰٓ]ئِرُك[w:11200[ُم م]َّعَكُمْۚ أَئِ[f:11201[ن ذ]ُكِّرْت[c:11202[ُمۚ ب]َلْ أَ[f:428[نت]ُمْ قَوْ[a:4833[مٌ م]ُّسْرِف[p[ُو]نَ","Улар: «Бадгумонлигингиз ўзингиз билан. Сизга эслатма берилганигами?! Йўқ! Сиз ўзингиз исрофчи қавмсиз», дедилар.",441,22],["وَج[o[َا]ٓءَ مِنْ أَ[q:10108[قْ]صَا [h:10109[ٱ]لْمَدِينَةِ رَجُ[a:11203[لٌ ي]َسْعَىٰ قَالَ يَ[n[ـٰ]قَوْمِ [h:11204[ٱ]تَّبِعُو[s[اْ] [h:11205[ٱ]لْمُرْسَل[p[ِي]نَ","Шаҳар четидан бир киши шошилиб келиб: «Эй қавмим, юборилган Пайғамбарларга эргашинг!",441,22],["ٱتَّبِعُو[s[اْ] م[u:6065[َن ل]َّا يَسْــَٔلُكُمْ أَ[q:2795[جْ][a:11206[رًا و]َه[w:4209[ُم م]ُّهْتَد[p[ُو]نَ","Сиздан ажр-ҳақ сўрамайдиган, ўзлари ҳидоятда бўлган шахсларга эргашинг!",441,22],["وَمَا لِىَ ل[o[َآ] أَعْبُدُ [h:11207[ٱ]لَّذِى فَطَرَنِى وَإِلَيْهِ تُرْجَع[p[ُو]نَ","Менга нима бўлибдики, ўзимни яратган зотга ибодат қилмайин?! Унгагина қайтарилурсизлар.",441,22],["ءَأَتَّخِذُ مِ[f:3136[ن د]ُونِه[o[ِۦٓ] ءَالِهَةً إ[a:11208[ِن ي]ُرِ[q:11209[دْ]نِ [h:11210[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ بِضُ[u:11211[رٍّ ل]َّا تُغْنِ عَ[g[نّ]ِى شَفَ[n[ـٰ]عَتُهُمْ شَيْـ[a:232[ـًٔا و]َلَا يُ[f:11212[نق]ِذ[p[ُو]نِ","Мен уни қўйиб, бошқа илоҳлар тутайми?! Агар Роҳман менга бирор зарарни ирода қилса, уларнинг шафоати менга ҳеч фойда бермас ва улар мени қутқара олмаслар.",441,22],["إِ[g[نّ][o[ِىٓ] إِ[u:11213[ذًا ل]َّفِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Албатта, у тақдирда мен очиқ-ойдин адашувда бўламан.",441,22],["إِ[g[نّ][o[ِىٓ] ءَامَ[f:6185[نت]ُ بِرَبِّكُمْ فَ[h:11214[ٱ]سْمَع[p[ُو]نِ","Албатта, мен Роббингизга иймон келтирдим. Бас, мени тинглангиз», деди.",441,22],["قِيلَ [h:11215[ٱ][q:11216[دْ]خُلِ [h:11217[ٱ]لْجَ[g[نّ]َةَۖ قَالَ يَ[n[ـٰ]لَيْتَ قَوْمِى يَعْلَم[p[ُو]نَ","«Жаннатга кир», дейилди. У: «Кошки қавмим билсалар эди.",441,22],["بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ [h:11218[ٱ]لْمُكْرَم[p[ِي]نَ","Роббим мени мағфират этганини ва икром қилинганлардан қилганини», деди.",441,22],["۞ وَم[o[َآ] أَ[f:515[نز]َلْنَا عَلَىٰ قَوْمِه[n[ِۦ] م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] مِ[f:11219[ن ج]ُن[a:11220[دٍ م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ وَمَا كُ[g[نّ]َا مُ[f:11221[نز]ِل[p[ِي]نَ","Биз унинг қавмига ундан кейин осмондан бирор лашкар туширмадик ва туширувчи эмас ҳам эдик.",442,23],["إِ[f:489[ن ك]َانَتْ إِلَّا صَيْحَ[a:11222[ةً و][n[َٲ]حِدَ[f:11223[ةً ف]َإِذَا هُمْ خَ[n[ـٰ]مِد[p[ُو]نَ","Фақат биргина қичқириқдан бошқа нарса бўлмади. Бирдан улар сўниб қолдилар.",442,23],["يَ[n[ـٰ]حَسْرَةً عَلَى [h:11224[ٱ]لْعِبَادِ‌ۚ مَا يَأْتِيه[w:7205[ِم م]ّ[u:2882[ِن ر]َّسُولٍ إِلَّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Бандаларга ҳасратлар бўлсин! Ҳар қачон уларга Пайғамбар келса, уни фақат истеҳзо қилар эдилар.",442,23],["أَلَمْ يَرَوْ[s[اْ] كَمْ أَهْلَكْنَا قَ[q:8394[بْ]لَه[w:8646[ُم م]ِّنَ [h:6524[ٱ]لْقُرُونِ أَ[g[نّ]َهُمْ إِلَيْهِمْ لَا يَرْجِع[p[ُو]نَ","Ахир улар ўзларидан олдинги қанча асрларни ҳалок этганимизни ва, албатта, ўшалар уларга қайтмасликларини кўрмайдиларми?!",442,23],["وَإِ[f:11225[ن ك]ُ[u:11226[لٌّ ل]َّ[g[مّ]َا جَمِي[u:11227[عٌ ل]َّدَيْنَا مُحْضَر[p[ُو]نَ","Албатта, барчалари тўпланган ҳолларида ҳузуримизга ҳозир қилингайлар.",442,23],["وَءَايَ[u:11228[ةٌ ل]َّهُمُ [h:11229[ٱ]لْأَرْضُ [h:11230[ٱ]لْمَيْتَةُ أَحْيَيْنَ[n[ـٰ]هَا وَأَخْرَ[q:11231[جْ]نَا مِنْهَا حَب[f:11232[ًّا ف]َمِنْهُ يَأْكُل[p[ُو]نَ","Улар учун ўлик ер оят-белгидир. Биз уни тирилтирдик ва ундан дон чиқардик. Бас, ундан ерлар.",442,23],["وَجَعَلْنَا فِيهَا جَ[g[نّ]َ[n[ـٰ][a:9169[تٍ م]ّ[a:1568[ِن ن]َّخِي[a:1569[لٍ و]َأَعْنَ[n[ـٰ][a:11233[بٍ و]َفَجَّرْنَا فِيهَا مِنَ [h:11234[ٱ]لْعُي[p[ُو]نِ","Ва унда хурмо ва узум боғлари яратдик ҳамда ичидан булоқларни чиқардик.",442,23],["لِيَأْكُلُو[s[اْ] مِ[f:4468[ن ث]َمَرِه[n[ِۦ] وَمَا عَمِلَتْهُ أَيْدِيهِمْ‌ۖ أَفَلَا يَشْكُر[p[ُو]نَ","Унинг меваларидан ва ўз қўллари қилган нарсалардан ейишлари учун. Шукр қилмайдиларми?!",442,23],["سُ[q:7648[بْ]حَ[n[ـٰ]نَ [h:7649[ٱ]لَّذِى خَلَقَ [h:11235[ٱ]لْأَزْو[n[َٲ]جَ كُلَّهَا مِ[g[مّ]َا تُ[i:308[نۢب]ِتُ [h:309[ٱ]لْأَرْضُ وَمِنْ أَ[f:568[نف]ُسِهِمْ وَمِ[g[مّ]َا لَا يَعْلَم[p[ُو]نَ","Ер ўстирадиган нарсалардан, уларнинг ўзларидан ва улар билмайдиган нарсалардан, барчасидан жуфтларни яратган зот пок бўлди.",442,23],["وَءَايَ[u:11228[ةٌ ل]َّهُمُ [h:11236[ٱ]لَّيْلُ نَسْلَخُ مِنْهُ [h:11237[ٱ][l[ل][g[نّ]َهَارَ فَإِذَا ه[w:11238[ُم م]ُّظْلِم[p[ُو]نَ","Улар учун кечаси ҳам оят-белгидир. Биз уни кундуздан шилиб оламиз. Бас, улар бирдан зулматда қолгувчилардир.",442,23],["وَ[h:9999[ٱ][l[ل]شَّمْسُ تَ[q:120[جْ]رِى لِمُسْتَقَ[u:11239[رٍّ ل]َّهَا‌ۚ ذ[n[َٲ]لِكَ تَ[q:4267[قْ]دِيرُ [h:4268[ٱ]لْعَزِيزِ [h:4269[ٱ]لْعَل[p[ِي]مِ","Қуёш ўз истиқрори учун жараён этар. Бу азизу ўта билгувчи зотнинг тақдир қилганидир.",442,23],["وَ[h:9999[ٱ]لْقَمَرَ قَدَّرْنَ[n[ـٰ]هُ مَنَازِلَ حَتَّىٰ عَادَ كَ[h:11240[ٱ]لْعُرْجُونِ [h:11241[ٱ]لْقَد[p[ِي]مِ","Ойни эса, токи эски шингили қайтгунга қадар манзилларини бичиб қўйганмиз.",442,23],["لَا [h:11242[ٱ][l[ل]شَّمْسُ يَ[i:8425[نۢب]َغِى لَه[o[َآ] أَ[f:11243[ن ت]ُ[q:11244[دْ]رِكَ [h:11245[ٱ]لْقَمَرَ وَلَا [h:11246[ٱ]لَّيْلُ سَابِقُ [h:11247[ٱ][l[ل][g[نّ]َهَارِ‌ۚ وَكُ[f:11248[لٌّ ف]ِى فَلَ[a:8732[كٍ ي]َسْبَح[p[ُو]نَ","На қуёшнинг ойга етиб олмоғи дуруст бўлар ва на кеча кундуздан ўзиб кетар. Ҳар бири фалакда сузиб юрар.",442,23],["وَءَايَ[u:11249[ةٌ ل]َّهُمْ أَ[g[نّ]َا حَمَلْنَا ذُرِّيَّتَهُمْ فِى [h:4780[ٱ]لْفُلْكِ [h:9808[ٱ]لْمَشْح[p[ُو]نِ","Улар учун Биз уларнинг наслларини тўла кемада кўтарганимиз ҳам бир оят-белгидир.",443,23],["وَخَلَ[q:11250[قْ]نَا لَه[w:1812[ُم م]ّ[a:104[ِن م]ِّثْلِه[n[ِۦ] مَا يَرْكَب[p[ُو]نَ","Ва Биз улар учун унга ўхшаш минадиган нарсаларни халқ қилдик.",443,23],["وَإ[a:11251[ِن ن]َّشَأْ نُغْرِ[q:11252[قْ]هُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُ[f:11253[نق]َذ[p[ُو]نَ","Агар хоҳласак, уларни ғарқ этурмиз. Бас, уларнинг ёрдамчиси бўлмас ва ҳам улар қутқазилмас.",443,23],["إِلَّا رَحْمَ[a:11254[ةً م]ِّ[g[نّ]َا وَمَتَ[n[ـٰ]عًا إِلَىٰ ح[p[ِي]نٍ","Магар Биздан бир раҳмат ва маълум муддатгача баҳраманд бўлиш бўлсагина.",443,23],["وَإِذَا قِيلَ لَهُمُ [h:11255[ٱ]تَّقُو[s[اْ] مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَم[p[ُو]نَ","Уларга: «Олдингиздаги нарсадан ва ортингиздаги нарсадан қўрқинг. Шояд раҳм қилинсангиз», дейилса.",443,23],["وَمَا تَأْتِيه[w:3923[ِم م]ِّنْ ءَايَ[a:3924[ةٍ م]ِّنْ ءَايَ[n[ـٰ]تِ رَبِّهِمْ إِلَّا كَانُو[s[اْ] عَنْهَا مُعْرِض[p[ِي]نَ","Ва уларга Роббилари оятларидан бир оят келганида, фақат ундан юз ўгиргувчи бўлурлар.",443,23],["وَإِذَا قِيلَ لَهُمْ أَ[f:1460[نف]ِقُو[s[اْ] مِ[g[مّ]َا رَزَقَكُمُ [h:3751[ٱ]للَّهُ قَالَ [h:590[ٱ]لَّذِينَ كَفَرُو[s[اْ] لِلَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَنُ[q:11256[طْ]عِمُ م[u:11257[َن ل]َّوْ يَش[o[َا]ٓءُ [h:6988[ٱ]للَّهُ أَ[q:11258[طْ]عَمَهُ[o[ۥٓ] إِنْ أَ[f:428[نت]ُمْ إِلَّا فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Уларга: «Аллоҳ сизга ризқ қилиб берган нарсадан инфоқ қилинглар», дейилганда, куфр келтирганлар иймон келтирганларга: «Аллоҳ хоҳласа, ўзи таом берадиган кимсани биз таомлантирамизми?! Сиз очиқ-ойдин залолатдан бошқа нарсада эмассиз», дерлар.",443,23],["وَيَقُولُونَ مَتَىٰ هَ[n[ـٰ]ذَا [h:6081[ٱ]لْوَعْدُ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Улар: «Агар ростгўй бўлсангиз, бу ваъда қачон бўлур?» дерлар.",443,23],["مَا يَ[f:1141[نظ]ُرُونَ إِلَّا صَيْحَ[a:11222[ةً و][n[َٲ]حِدَ[f:11259[ةً ت]َأْخُذُهُمْ وَهُمْ يَخِصِّم[p[ُو]نَ","Улар фақат талашиб-тортишиб турганларида ўзларини бирдан оладиган биргина қичқириқдан бошқа нарсани кутаётганлари йўқ.",443,23],["فَلَا يَسْتَطِيعُونَ تَوْصِيَ[a:11260[ةً و]َل[o[َآ] إِلَ[o[ىٰٓ] أَهْلِهِمْ يَرْجِع[p[ُو]نَ","Улар на васият қилишга қодир бўларлар ва на ўз аҳлларига қайтарлар.",443,23],["وَنُفِخَ فِى [h:4185[ٱ][l[ل]صُّورِ فَإِذَا ه[w:10171[ُم م]ِّنَ [h:11261[ٱ]لْأَ[q:11262[جْ]دَاثِ إِلَىٰ رَبِّهِمْ يَ[f:8857[نس]ِل[p[ُو]نَ","Ва сурга пуфланди. Бас, улар бирдан Роббилари томон қабрлардан шошилиб чиқурлар.",443,23],["قَالُو[s[اْ] يَ[n[ـٰ]وَيْلَنَا م[i:11263[َنۢ ب]َعَثَنَا م[a:11264[ِن م]َّرْقَدِنَاۜ‌ۗ هَ[n[ـٰ]ذَا مَا وَعَدَ [h:8377[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ وَصَدَقَ [h:11265[ٱ]لْمُرْسَل[p[ُو]نَ","Улар: «Воҳ, шўримиз қурисин! Бизни ётган жойимиздан ким қўзғотди?! Бу Роҳман ваъда қилган ва юборилган Пайғамбарлар тасдиқлаган нарса-ку?!» дерлар.",443,23],["إِ[f:489[ن ك]َانَتْ إِلَّا صَيْحَ[a:11222[ةً و][n[َٲ]حِدَ[f:11223[ةً ف]َإِذَا هُمْ جَمِي[u:11227[عٌ ل]َّدَيْنَا مُحْضَر[p[ُو]نَ","Фақат биргина қичқириқдан бошқа нарса бўлгани йўқ. Бас, улар бирдан тўпланиб, ҳузуримизда ҳозир қилингандирлар.",443,23],["فَ[h:9999[ٱ]لْيَوْمَ لَا تُظْلَمُ نَفْ[f:8774[سٌ ش]َيْـ[a:232[ـًٔا و]َلَا تُ[q:4248[جْ]زَوْنَ إِلَّا مَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Бугунги кунда бирор жонга ҳеч бир зулм қилинмас. Қилиб ўтган амалларингиздан бошқасига жазо ҳам олмассиз.",443,23],["إِ[g[نّ]َ أَصْحَ[n[ـٰ]بَ [h:4715[ٱ]لْجَ[g[نّ]َةِ [h:11266[ٱ]لْيَوْمَ فِى شُغُ[f:11267[لٍ ف]َ[n[ـٰ]كِه[p[ُو]نَ","Албатта, жаннат эгалари у кунда завқланувчилик ила машғуллар.",444,23],["هُمْ وَأَزْو[n[َٲ]جُهُمْ فِى ظِلَ[n[ـٰ]لٍ عَلَى [h:8058[ٱ]لْأَر[o[َا]ٓئِكِ مُتَّكِــٔ[p[ُو]نَ","Улар ва уларнинг жуфтлари сояларда сўриларда ёнбошлаб ётурлар.",444,23],["لَهُمْ فِيهَا فَ[n[ـٰ]كِهَ[a:11268[ةٌ و]َلَه[w:7443[ُم م]َّا يَدَّع[p[ُو]نَ","Улар учун у ерда мевалар бордир. Улар учун у ерда истаган нарсалар бордир.",444,23],["سَلَ[n[ـٰ][f:11269[مٌ ق]َوْل[a:11270[اً م]ّ[u:11271[ِن ر]َّ[u:11272[بٍّ ر]َّح[p[ِي]مٍ","Раҳим бўлган Роббдан «Салом» сўзи бордир.",444,23],["وَ[h:9999[ٱ]مْتَ[n[ـٰ]زُو[s[اْ] [h:11273[ٱ]لْيَوْمَ أَيُّهَا [h:11274[ٱ]لْمُ[q:5255[جْ]رِم[p[ُو]نَ","Эй жиноятчилар! Бугунги кунда сиз ажралингиз!",444,23],["۞ أَلَمْ أَعْهَ[q:11275[دْ] إِلَيْكُمْ يَ[n[ـٰ]بَن[o[ِىٓ] ءَادَمَ أ[u:4908[َن ل]َّا تَعْبُدُو[s[اْ] [h:11276[ٱ][l[ل]شَّيْطَ[n[ـٰ]نَ‌ۖ إِ[g[نّ]َهُ[n[ۥ] لَكُمْ عَدُ[a:873[وٌّ م]ُّب[p[ِي]نٌ","Мен сизларга: «Эй одам болалари, шайтонга ибодат қилманг, албатта, у сизга очиқ-ойдин душмандир.",444,23],["وَأَنِ [h:11277[ٱ]عْبُدُونِى‌ۚ هَ[n[ـٰ]ذَا صِر[n[َٲ][a:1947[طٌ م]ُّسْتَق[p[ِي]مٌ","Ва Менга ибодат қилинг, мана шу тўғри йўлдир», деб амр қилмаган эдимми?!",444,23],["وَلَقَ[q:341[دْ] أَضَلَّ مِ[f:344[نك]ُمْ جِبِل[f:11278[اًّ ك]َثِيرًا‌ۖ أَفَلَمْ تَكُونُو[s[اْ] تَعْقِل[p[ُو]نَ","Батаҳқиқ, у сизлардан кўпчилик авлодни адаштирди. Ақл юритувчи бўлмаган эдингизми?!",444,23],["هَ[n[ـٰ]ذِه[n[ِۦ] جَهَ[g[نّ]َمُ [h:11279[ٱ]لَّتِى كُ[f:100[نت]ُمْ تُوعَد[p[ُو]نَ","Мана бу сизга ваъда қилинган жаҳаннамдир!",444,23],["ٱصْلَوْهَا [h:11280[ٱ]لْيَوْمَ بِمَا كُ[f:100[نت]ُمْ تَكْفُر[p[ُو]نَ","Куфр келтириб ўтганингиз туфайли бугунги кунда унга киринг!",444,23],["ٱلْيَوْمَ نَخْتِمُ عَلَ[o[ىٰٓ] أَفْو[n[َٲ]هِهِمْ وَتُكَلِّمُن[o[َآ] أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُه[c:11281[ُم ب]ِمَا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Бугунги кунда уларнинг оғизларига муҳр урамиз. Нима касб қилганларини Бизга қўллари сўзлар ва оёқлари гувоҳлик берур.",444,23],["وَلَوْ نَش[o[َا]ٓءُ لَطَمَسْنَا عَلَ[o[ىٰٓ] أَعْيُنِهِمْ فَ[h:11282[ٱ]سْتَبَقُو[s[اْ] [h:11283[ٱ][l[ل]صِّر[n[َٲ]طَ فَأَ[g[نّ]َىٰ يُ[q:60[بْ]صِر[p[ُو]نَ","Агар хоҳласак, кўзларини теп-текис қилиб қўюрмиз. Бас, улар йўлга шошилурлар. Аммо қандай ҳам кўрсинлар.",444,23],["وَلَوْ نَش[o[َا]ٓءُ لَمَسَخْنَ[n[ـٰ]هُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا [h:11284[ٱ]سْتَطَ[n[ـٰ]عُو[s[اْ] مُضِي[a:11285[ًّا و]َلَا يَرْجِع[p[ُو]نَ","Агар хоҳласак, уларни жойларида қотириб қўюрмиз. Бас, олдинги юришга ҳам қодир бўлмаслар, ортга ҳам қайта олмаслар.",444,23],["وَم[a:11286[َن ن]ُّعَ[g[مّ]ِرْهُ نُنَكِّسْهُ فِى [h:4788[ٱ]لْخَلْقِ‌ۖ أَفَلَا يَعْقِل[p[ُو]نَ","Кимнинг умрини узоқ қилсак, уни хилқатида ночор қилиб қўюрмиз. Ахир ақл ишлатиб кўрмайдиларми?!",444,23],["وَمَا عَلَّمْنَ[n[ـٰ]هُ [h:11287[ٱ][l[ل]شِّعْرَ وَمَا يَ[i:8425[نۢب]َغِى لَهُ[o[ۥٓ‌ۚ] إِنْ هُوَ إِلَّا ذِكْ[a:11288[رٌ و]َقُرْءَا[a:11289[نٌ م]ُّب[p[ِي]نٌ","Биз унга шеърни таълим берганимиз йўқ. Ва бу унинг учун тўғри ҳам келмайди. У зикр ва очиқ-ойдин Қуръондан ўзга нарса эмас.",444,23],["لِّيُ[f:7947[نذ]ِرَ مَ[f:506[ن ك]َانَ حَي[a:11290[ًّا و]َيَحِقَّ [h:11291[ٱ]لْقَوْلُ عَلَى [h:468[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Тирик бўлган шахсларни огоҳлантириш ва кофирларга сўзини ҳақ қилиши учундир.",444,23],["أَوَلَمْ يَرَوْ[s[اْ] أَ[g[نّ]َا خَلَ[q:5159[قْ]نَا لَه[w:402[ُم م]ِّ[g[مّ]َا عَمِلَتْ أَيْدِين[o[َآ] أَنْعَ[n[ـٰ][f:11292[مًا ف]َهُمْ لَهَا مَ[n[ـٰ]لِك[p[ُو]نَ","Ахир Биз улар учун Ўз қўлларимиз—ла қилган нарсалардан чорваларни яратиб қўйганимизни кўрмайдиларми?! Бас, улар ўшаларга молик–эгадирлар-ку!",445,23],["وَذَلَّلْنَ[n[ـٰ]هَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُل[p[ُو]نَ","Биз уларга ўшаларни бўйинсундириб қўйдик. Бас, улардан маркаблари бор ва улардан ерлар.",445,23],["وَلَهُمْ فِيهَا مَنَ[n[ـٰ]فِعُ وَمَشَارِبُ‌ۖ أَفَلَا يَشْكُر[p[ُو]نَ","Улар учун ўшаларда манфаатлар ва ичкиликлар бор. Ахир шукр қилмайдиларми?!",445,23],["وَ[h:9999[ٱ]تَّخَذُو[s[اْ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ ءَالِهَ[u:11293[ةً ل]َّعَلَّهُمْ يُ[f:237[نص]َر[p[ُو]نَ","Улар Аллоҳдан ўзга илоҳлар тутдилар. Гўёки улардан ёрдам берилар эмиш.",445,23],["لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُن[a:11294[دٌ م]ُّحْضَر[p[ُو]نَ","Уларнинг ёрдамига улари қодир бўлмаслар. Улар эса, ўшалари учун ҳозир қилинган аскардирлар.",445,23],["فَلَا يَحْزُ[f:2435[نك]َ قَوْلُهُمْ‌ۘ إِ[g[نّ]َا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِن[p[ُو]نَ","Уларнинг гапи сени хафа қилмасин. Албатта, Биз нимани сир тутсалар ва нимани ошкор қилсалар, билурмиз.",445,23],["أَوَلَمْ يَرَ [h:11295[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ أَ[g[نّ]َا خَلَ[q:7232[قْ]نَ[n[ـٰ]هُ م[a:7325[ِن ن]ُّ[q:7326[طْ]فَ[f:7327[ةٍ ف]َإِذَا هُوَ خَصِي[a:7328[مٌ م]ُّب[p[ِي]نٌ","Инсон Биз уни нутфадан яратганимизни билмасми?! Энди эса, у очиқ-ойдин хусуматчи бўлиб турибди?!",445,23],["وَضَرَبَ لَنَا مَثَل[a:11296[اً و]َنَسِىَ خَلْقَهُ[n[ۥ]‌ۖ قَالَ م[a:11297[َن ي]ُحْىِ [h:11298[ٱ]لْعِظَ[n[ـٰ]مَ وَهِىَ رَم[p[ِي]مٌ","У Бизга мисол келтирди ва ўз яратилишини унутди. «Суякларни ким тирилтиради? Ҳолбуки, улар титилиб кетган-ку?!» деди.",445,23],["قُلْ يُحْيِيهَا [h:11299[ٱ]لَّذ[o[ِىٓ] أَ[f:11300[نش]َأَه[o[َآ] أَوَّلَ مَرَّ[a:11301[ةٍ‌ۖ و]َهُوَ بِكُلِّ خَلْقٍ عَل[p[ِي]مٌ","Сен: «Уларни илк марта йўқдан бор қилган зот тирилтирур ва у ҳар бир яратилган нарсани яхши билгувчидир», деб айт.",445,23],["ٱلَّذِى جَعَلَ لَك[w:1578[ُم م]ِّنَ [h:11302[ٱ][l[ل]شَّجَرِ [h:11303[ٱ]لْأَخْضَرِ نَا[f:11304[رًا ف]َإِذ[o[َآ] أَ[f:428[نت][w:11305[ُم م]ِّنْهُ تُوقِد[p[ُو]نَ","У зот сизларга яшил дарахтдан олов қилиб бергандир. Энди эса, сиз ундан олов ёқмоқдасиз.",445,23],["أَوَلَيْسَ [h:11306[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ بِقَ[n[ـٰ]دِرٍ عَلَ[o[ىٰٓ] أ[a:7911[َن ي]َخْلُقَ مِثْلَه[c:11307[ُم‌ۚ ب]َلَىٰ وَهُوَ [h:11308[ٱ]لْخَلَّ[n[ـٰ]قُ [h:7305[ٱ]لْعَل[p[ِي]مُ","Осмонлару ерни яратган зот уларга ўхшашни яратишга қодир эмасми?! Йўқ! У ўта яратгувчи, ўта билгувчи зотдир.",445,23],["إِ[g[نّ]َم[o[َآ] أَمْرُهُ[o[ۥٓ] إِذ[o[َآ] أَرَادَ شَيْــًٔا أ[a:11309[َن ي]َقُولَ لَهُ[n[ۥ] كُ[f:613[ن ف]َيَك[p[ُو]نُ","Қачон бирон нарсани ирода қилса, Унинг иши «Бўл» демоқликдир, холос. Бас, у нарса бўлур.",445,23],["فَسُ[q:8705[بْ]حَ[n[ـٰ]نَ [h:11310[ٱ]لَّذِى بِيَدِه[n[ِۦ] مَلَكُوتُ كُلِّ ش[a:11311[َىْءٍ و]َإِلَيْهِ تُرْجَع[p[ُو]نَ","Бас, барча нарсанинг том эгалиги қўлида бўлган зот покдир. Унгагина қайтарилурсизлар.",445,23]]},{"n":37,"ar":"الصَّافَّاتِ","en":"As-Saaffaat","uz":"Соффат","type":"Макка","ayahs":[["وَ[h:9999[ٱ][l[ل]صَّ[m[ـٰٓ]فَّ[n[ـٰ]تِ صَفًّا","Сафда тизилиб турувчилар ила қасам.",446,23],["فَ[h:9999[ٱ][l[ل]زّ[n[َٲ]جِر[n[َٲ]تِ زَ[q:11312[جْ]رًا","Зажр зажр қилгувчилар ила қасам.",446,23],["فَ[h:9999[ٱ][l[ل]تَّ[n[ـٰ]لِيَ[n[ـٰ]تِ ذِكْرًا","Зикрни тиловат қилгувчилар ила қасам.",446,23],["إِ[g[نّ]َ إِلَ[n[ـٰ]هَكُمْ لَو[n[َٲ]حِ[q[د]ٌ","Албатта, илоҳингиз ягонадир.",446,23],["رَّبُّ [h:6926[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ [h:11313[ٱ]لْمَشَ[n[ـٰ]رِ[q[ق]ِ","У зот осмонлару ернинг ва иккиси орасидаги нарсаларнинг Роббидир. Ва машриқларнинг Роббидир.",446,23],["إِ[g[نّ]َا زَيَّ[g[نّ]َا [h:11314[ٱ][l[ل]سَّم[o[َا]ٓءَ [h:11315[ٱ][l[ل]دُّنْيَا بِزِينَةٍ [h:11316[ٱ]لْكَوَاكِ[q[ب]ِ","Албатта, Биз бу дунё осмонини юлдузлар зийнати-ла зийнатладик.",446,23],["وَحِفْ[a:11317[ظًا م]ِّ[f:843[ن ك]ُلِّ شَيْطَ[n[ـٰ][a:11318[نٍ م]َّارِ[q[د]ٍ","Ва ҳар бир итоатсиз шайтондан сақлаш учун.",446,23],["لَّا يَسَّ[g[مّ]َعُونَ إِلَى [h:1384[ٱ]لْمَلَإِ [h:11319[ٱ]لْأَعْلَىٰ وَيُ[q:11320[قْ]ذَفُونَ مِ[f:843[ن ك]ُلِّ جَانِ[q[ب]ٍ","Улар юксак тўплиққа қулоқ сола олмаслар ва ҳар томондан отилурлар.",446,23],["دُحُو[a:11321[رًا‌ۖ و]َلَهُمْ عَذَا[a:11322[بٌ و]َاصِ[q[ب]ٌ","Ҳайдалурлар! Улар учун узлуксиз азоб бордир.",446,23],["إِلَّا مَنْ خَطِفَ [h:11323[ٱ]لْخَ[q:11324[طْ]فَةَ فَأَتْبَعَهُ[n[ۥ] شِهَا[f:11325[بٌ ث]َاقِ[q[ب]ٌ","Магар бирорта сўзни ўғриликча тинглаган шахс бўлса, уни ёқгувчи олов таъқиб этар.",446,23],["فَ[h:9999[ٱ]سْتَفْتِهِمْ أَهُمْ أَشَدُّ خَلْقًا أ[w:3110[َم م]َّنْ خَلَ[q:5159[قْ]ن[o[َآ‌ۚ] إِ[g[نّ]َا خَلَ[q:11326[قْ]نَ[n[ـٰ]ه[w:11327[ُم م]ِّ[f:3917[ن ط]ِي[u:11328[نٍ ل]َّازِ[q[ب]ِۭ","Бас, сен улардан сўра: уларни яратиш қийинроқмикан ёки Биз яратган зотларни?! Албатта, Биз уларни ёпишқоқ лойдан яратдик.",446,23],["بَلْ عَجِ[q:11329[بْ]تَ وَيَسْخَر[p[ُو]نَ","Балки сен ажабландинг, улар эса масхара қилурлар.",446,23],["وَإِذَا ذُكِّرُو[s[اْ] لَا يَذْكُر[p[ُو]نَ","Қачонки эслатилсалар, эсламаслар.",446,23],["وَإِذَا رَأَوْ[s[اْ] ءَايَ[a:11330[ةً ي]َسْتَسْخِر[p[ُو]نَ","Қачонки бирор оят-белгини кўрсалар, қаттиқроқ масхара қилурлар.",446,23],["وَقَال[o[ُوٓ][s[اْ] إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا سِحْ[a:3879[رٌ م]ُّب[p[ِي]نٌ","Улар: «Бу очиқ-ойдин сеҳрдан бошқа нарса эмас.",446,23],["أَءِذَا مِتْنَا وَكُ[g[نّ]َا تُرَا[a:9207[بًا و]َعِظَ[n[ـٰ]مًا أَءِ[g[نّ]َا لَمَ[q:7784[بْ]عُوث[p[ُو]نَ","Ўлсак-да, тупроқ ва суяк бўлсак-да, албатта, Биз қайта тирилтирилурмизми?!",446,23],["أَوَءَاب[o[َا]ٓؤُنَا [h:11331[ٱ]لْأَوَّل[p[ُو]نَ","Аввалги ота-боболаримиз ҳам-а?!» дедилар.",446,23],["قُلْ نَعَمْ وَأَ[f:98[نت]ُمْ د[n[َٲ]خِر[p[ُو]نَ","Сен: «Ҳа! Хор бўлган ҳолларингизда!» дегин.",446,23],["فَإِ[g[نّ]َمَا هِىَ زَ[q:11332[جْ]رَ[a:11333[ةٌ و][n[َٲ]حِدَ[f:11334[ةٌ ف]َإِذَا هُمْ يَ[f:1141[نظ]ُر[p[ُو]نَ","Бас, у фақатгина бир қичқириқдан иборат, холос. Бас, бирдан улар назар солиб турибдилар-да!",446,23],["وَقَالُو[s[اْ] يَ[n[ـٰ]وَيْلَنَا هَ[n[ـٰ]ذَا يَوْمُ [h:11335[ٱ][l[ل]دّ[p[ِي]نِ","Ва улар: «Воҳ, шўримиз қурисин! Бу жазо куни-ку!» дерлар.",446,23],["هَ[n[ـٰ]ذَا يَوْمُ [h:11336[ٱ]لْفَصْلِ [h:11337[ٱ]لَّذِى كُ[f:100[نت][c:6084[ُم ب]ِه[n[ِۦ] تُكَذِّب[p[ُو]نَ","Бу сизлар ёлғонга чиқариб юрган ажрим кунидир.",446,23],["۞ ٱحْشُرُو[s[اْ] [h:11338[ٱ]لَّذِينَ ظَلَمُو[s[اْ] وَأَزْو[n[َٲ]جَهُمْ وَمَا كَانُو[s[اْ] يَعْبُد[p[ُو]نَ","Зулм қилганларни, уларнинг жуфтларини ва улар ибодат қилиб юрган нарсаларини тўпланг.",446,23],["مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ فَ[h:11339[ٱ]هْدُوهُمْ إِلَىٰ صِر[n[َٲ]طِ [h:11340[ٱ]لْجَح[p[ِي]مِ","Аллоҳдан ўзга. Бас, уларни жаҳийм йўлига ҳидоят қилинг».",446,23],["وَقِفُوهُمْ‌ۖ إِ[g[نّ]َه[w:11341[ُم م]َّسْــُٔول[p[ُو]نَ","Ва уларни тўхтатинглар! Албатта, улар сўралгувчидирлар.",446,23],["مَا لَكُمْ لَا تَنَاصَر[p[ُو]نَ","Сизларга нима бўлди? Ўзаро ёрдамлашмаяпсиз?!",447,23],["بَلْ هُمُ [h:11342[ٱ]لْيَوْمَ مُسْتَسْلِم[p[ُو]نَ","Йўқ! Улар бугунги кунда таслим бўлгувчилардир.",447,23],["وَأَ[q:11343[قْ]بَلَ بَعْضُهُمْ عَلَىٰ بَعْ[a:11344[ضٍ ي]َتَس[o[َا]ٓءَل[p[ُو]نَ","Улар бир-бирларига савол берурлар.",447,23],["قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َكُمْ كُ[f:100[نت]ُمْ تَأْتُونَنَا عَنِ [h:7424[ٱ]لْيَم[p[ِي]نِ","Улар: «Албатта, сизлар бизга ўнг томондан келар эдингиз», дерлар.",447,23],["قَالُو[s[اْ] بَل لَّمْ تَكُونُو[s[اْ] مُؤْمِن[p[ِي]نَ","Улар: «Йўқ! Сиз ўзингиз мўмин бўлмаган эдингиз.",447,23],["وَمَا كَانَ لَنَا عَلَيْك[w:548[ُم م]ِّ[f:4798[ن س]ُلْطَ[n[ـٰ][i:11345[نِۭ‌ۖ ب]َلْ كُ[f:100[نت]ُمْ قَوْ[f:11346[مًا ط]َ[n[ـٰ]غ[p[ِي]نَ","Бизнинг устингиздан ҳукмронлигимиз бўлмаган эди. Йўқ! Сиз ўзингиз туғёнга кетган қавм эдингиз.",447,23],["فَحَقَّ عَلَيْنَا قَوْلُ رَبِّن[o[َآ‌ۖ] إِ[g[نّ]َا لَذ[o[َا]ٓئِق[p[ُو]نَ","Бас, ҳаммамизга Роббимизнинг сўзи ҳақ бўлди. Албатта, биз тотгувчилармиз.",447,23],["فَأَغْوَيْنَ[n[ـٰ]كُمْ إِ[g[نّ]َا كُ[g[نّ]َا غَ[n[ـٰ]و[p[ِي]نَ","Ҳа, биз сизларни иғво қилдик. Албатта, биз иғво қилгувчи эдик», дерлар.",447,23],["فَإِ[g[نّ]َهُمْ يَوْمَئِ[f:11347[ذٍ ف]ِى [h:10442[ٱ]لْعَذَابِ مُشْتَرِك[p[ُو]نَ","Бас, улар у кунда азобда шерик бўлгувчилардир.",447,23],["إِ[g[نّ]َا كَذ[n[َٲ]لِكَ نَفْعَلُ بِ[h:11348[ٱ]لْمُ[q:11348[جْ]رِم[p[ِي]نَ","Албатта, Биз жиноятчиларга шундоқ қилурмиз.",447,23],["إِ[g[نّ]َهُمْ كَان[o[ُوٓ][s[اْ] إِذَا قِيلَ لَهُمْ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا [h:1742[ٱ]للَّهُ يَسْتَكْبِر[p[ُو]نَ","Чунки, уларга қачонки «Ла илаҳа иллоллоҳу», дейилса, мутакаббирлик қилар эдилар.",447,23],["وَيَقُولُونَ أَئِ[g[نّ]َا لَتَارِك[o[ُوٓ][s[اْ] ءَالِهَتِنَا لِشَاعِ[a:11349[رٍ م]َّ[q:11350[جْ]ن[p[ُو]نِۭ","«Ахир биз бир жинни шоирни деб ўз худоларимизни тарк қилгувчи бўлайликми?!» дер эдилар.",447,23],["بَلْ ج[o[َا]ٓءَ بِ[h:370[ٱ]لْحَقِّ وَصَدَّقَ [h:11351[ٱ]لْمُرْسَل[p[ِي]نَ","Йўқ! У ҳақни келтирди ва Пайғамбарларни тасдиқ қилди.",447,23],["إِ[g[نّ]َكُمْ لَذ[o[َا]ٓئِقُو[s[اْ] [h:11352[ٱ]لْعَذَابِ [h:11353[ٱ]لْأَل[p[ِي]مِ","Албатта, сиз аламли азобни тотгувчидирсиз.",447,23],["وَمَا تُ[q:4248[جْ]زَوْنَ إِلَّا مَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Қилиб ўтган нарсангиздан бошқа нарсанинг жазосини олмассиз.",447,23],["إِلَّا عِبَادَ [h:11354[ٱ]للَّهِ [h:11355[ٱ]لْمُخْلَص[p[ِي]نَ","Магар Аллоҳнинг ихлосли бандалари.",447,23],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ رِزْ[a:11356[قٌ م]َّعْل[p[ُو]مٌ","Ана ўшаларга, ўзларига маълум ризқ бордир.",447,23],["فَو[n[َٲ]كِهُ‌ۖ وَه[w:11357[ُم م]ُّكْرَم[p[ُو]نَ","Мева-чевалар бордир. Улар икром қилинган ҳолларида...",447,23],["فِى جَ[g[نّ]َ[n[ـٰ]تِ [h:3680[ٱ][l[ل][g[نّ]َع[p[ِي]مِ","Наъийм жаннатларида...",447,23],["عَلَىٰ سُرُ[a:7259[رٍ م]ُّتَقَ[n[ـٰ]بِل[p[ِي]نَ","Сўрилар устида бир-бирларига қараган ҳолларида бўлурлар.",447,23],["يُطَافُ عَلَيْه[c:11358[ِم ب]ِكَأْ[a:11359[سٍ م]ّ[a:11360[ِن م]َّع[p[ِي]نِۭ","Уларга оқар чашмадан қадаҳлар айлантириб турилур.",447,23],["بَيْض[o[َا]ٓءَ لَذَّ[u:11361[ةٍ ل]ِّلشَّ[n[ـٰ]رِب[p[ِي]نَ","Оппоқ, ичгувчига лаззатбахшдир.",447,23],["لَا فِيهَا غَوْ[a:11362[لٌ و]َلَا هُمْ عَنْهَا يُ[f:11363[نز]َف[p[ُو]نَ","Унда ҳеч бир зарар йўқдир ва ундан сархуш ҳам бўлмаслар.",447,23],["وَعِ[f:11364[ند]َهُمْ قَ[n[ـٰ]صِر[n[َٲ]تُ [h:11365[ٱ][l[ل]طَّرْفِ ع[p[ِي]نٌ","Олдиларида кўзларини тийгувчи шаҳло кўзлилар бордир.",447,23],["كَأَ[g[نّ]َهُ[g[نّ]َ بَيْ[a:11366[ضٌ م]َّكْن[p[ُو]نٌ","Улар худди асраб қўйилган тухумга ўхшарлар.",447,23],["فَأَ[q:11367[قْ]بَلَ بَعْضُهُمْ عَلَىٰ بَعْ[a:11344[ضٍ ي]َتَس[o[َا]ٓءَل[p[ُو]نَ","Бас, улар бир-бирларидан сўрай бошлайдилар.",447,23],["قَالَ ق[o[َا]ٓئِ[a:6558[لٌ م]ِّنْهُمْ إِ[g[نّ]ِى كَانَ لِى قَر[p[ِي]نٌ","Ичларидан бир сўзловчи: «Аниқки, менинг бир дўстим бор эди.",447,23],["يَقُولُ أَءِ[g[نّ]َكَ لَمِنَ [h:11368[ٱ]لْمُصَدِّق[p[ِي]نَ","У: «Сен ҳам тасдиқловчиларданмисан?!",448,23],["أَءِذَا مِتْنَا وَكُ[g[نّ]َا تُرَا[a:9207[بًا و]َعِظَ[n[ـٰ]مًا أَءِ[g[نّ]َا لَمَدِين[p[ُو]نَ","Ўлиб, тупроқ ва суяклар бўлиб кетсак ҳам, албатта, жазоланадиганлардан бўлурмизми?!» дер эди.",448,23],["قَالَ هَلْ أَ[f:428[نت][w:11369[ُم م]ُّطَّلِع[p[ُو]نَ","Сизлар ҳам қараяпсизларми?» деди.",448,23],["فَ[h:9999[ٱ]طَّلَعَ فَرَءَاهُ فِى سَو[o[َا]ٓءِ [h:11370[ٱ]لْجَح[p[ِي]مِ","Бас, ўзи қараб, уни дўзахнинг ўртасида кўрди.",448,23],["قَالَ تَ[h:6760[ٱ]للَّهِ إِ[f:11371[ن ك]ِ[d:7842[د]تَّ لَتُرْد[p[ِي]نِ","У: «Аллоҳга қасамки, мени ҳам ҳалок қилишингга оз қолган экан.",448,23],["وَلَوْلَا نِعْمَةُ رَبِّى لَكُ[f:11372[نت]ُ مِنَ [h:10216[ٱ]لْمُحْضَر[p[ِي]نَ","Агар Роббимнинг неъмати бўлмаганида, мен ҳам ҳозир қилинганлардан бўлур эдим.",448,23],["أَفَمَا نَحْنُ بِمَيِّت[p[ِي]نَ","Биз ўлгувчи эмас эканмизми?!",448,23],["إِلَّا مَوْتَتَنَا [h:11373[ٱ]لْأُولَىٰ وَمَا نَحْنُ بِمُعَذَّب[p[ِي]نَ","Фақат биринчи ўлимимиздан бошқа?! Биз азоблангувчи эмас эканмизми?!» деди.",448,23],["إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَهُوَ [h:11374[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Албатта, бу айни улуғ ютуқдир.",448,23],["لِمِثْلِ هَ[n[ـٰ]ذَا فَلْيَعْمَلِ [h:11375[ٱ]لْعَ[n[ـٰ]مِل[p[ُو]نَ","Бас, амал қилгувчилар мана шунга ўхшаш нарса учун амал этсинлар.",448,23],["أَذ[n[َٲ]لِكَ خَيْ[a:11376[رٌ ن]ُّزُلاً أَمْ شَجَرَةُ [h:11377[ٱ][l[ل]زَّقّ[p[ُو]مِ","Манзил ўлароқ ана ўша яхшими ёки заққум дарахтими?",448,23],["إِ[g[نّ]َا جَعَلْنَ[n[ـٰ]هَا فِتْنَ[u:11378[ةً ل]ِّلظَّ[n[ـٰ]لِم[p[ِي]نَ","Албатта, Биз уни золимлар учун фитна қилдик.",448,23],["إِ[g[نّ]َهَا شَجَرَ[f:11379[ةٌ ت]َخْرُجُ ف[o[ِىٓ] أَصْلِ [h:11380[ٱ]لْجَح[p[ِي]مِ","Дарҳақиқат, у бир дарахт бўлиб, дўзах қаъридан чиқур.",448,23],["طَلْعُهَا كَأَ[g[نّ]َهُ[n[ۥ] رُءُوسُ [h:11381[ٱ][l[ل]شَّيَ[n[ـٰ]ط[p[ِي]نِ","Унинг тугар жойи, худди шайтонларнинг бошларига ўхшайдир.",448,23],["فَإِ[g[نّ]َهُمْ لَأَكِلُونَ مِنْهَا فَمَالِــُٔونَ مِنْهَا [h:11382[ٱ]لْبُط[p[ُو]نَ","Бас, албатта, улар ундан егувчилардир. Ундан қоринларни тўлдиргувчилардир.",448,23],["ثُ[g[مّ]َ إِ[g[نّ]َ لَهُمْ عَلَيْهَا لَشَوْ[a:11383[بًا م]ِّنْ حَم[p[ِي]مٍ","Сўнгра, бунинг устига, улар учун ўта қайноқ сувдан аралаштирма ҳам бор.",448,23],["ثُ[g[مّ]َ إِ[g[نّ]َ مَرْجِعَهُمْ لَإِلَى [h:11384[ٱ]لْجَح[p[ِي]مِ","Сўнгра, албатта, уларнинг қайтар жойи жаҳаннамга бўлур.",448,23],["إِ[g[نّ]َهُمْ أَلْفَوْ[s[اْ] ءَاب[o[َا]ٓءَهُمْ ض[m[َا]ٓلّ[p[ِي]نَ","Чунки улар ўз оталарини адашган ҳолда топдилар.",448,23],["فَهُمْ عَلَ[o[ىٰٓ] ءَاثَ[n[ـٰ]رِهِمْ يُهْرَع[p[ُو]نَ","Энди эса, улар ўшаларнинг изидан чопмоқдалар.",448,23],["وَلَقَ[q:341[دْ] ضَلَّ قَ[q:8394[بْ]لَهُمْ أَكْثَرُ [h:11385[ٱ]لْأَوَّل[p[ِي]نَ","Батаҳқиқ, улардан олдин аввалгиларнинг кўплари адашганлар.",448,23],["وَلَقَ[q:341[دْ] أَرْسَلْنَا فِيه[w:11386[ِم م]ُّ[f:11387[نذ]ِر[p[ِي]نَ","Батаҳқиқ, Биз ичларига огоҳлантиргувчилар юбордик.",448,23],["فَ[h:9999[ٱ][f:1513[نظ]ُرْ كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6136[ٱ]لْمُ[f:6137[نذ]َر[p[ِي]نَ","Бас, огоҳлантирилганларнинг оқибати қандоқ бўлганига назар сол.",448,23],["إِلَّا عِبَادَ [h:11354[ٱ]للَّهِ [h:11355[ٱ]لْمُخْلَص[p[ِي]نَ","Магар ихлосли бандаларимизгина ҳалокатга учрамадилар.",448,23],["وَلَقَ[q:341[دْ] نَادَ[n[ٮٰ]نَا نُو[f:11388[حٌ ف]َلَنِعْمَ [h:11389[ٱ]لْمُجِيب[p[ُو]نَ","Батаҳқиқ, Бизга Нуҳ нидо қилди. Бас, нақадар яхши ижобат қилгувчимиз.",448,23],["وَنَجَّيْنَ[n[ـٰ]هُ وَأَهْلَهُ[n[ۥ] مِنَ [h:8815[ٱ]لْكَرْبِ [h:8816[ٱ]لْعَظ[p[ِي]مِ","Ва Биз унга ва унинг аҳлига улуғ ғамдан нажот бердик.",448,23],["وَجَعَلْنَا ذُرِّيَّتَهُ[n[ۥ] هُمُ [h:11390[ٱ]لْبَاق[p[ِي]نَ","Ва унинг зурриётларини, ўзларини боқий қолгувчилар қилдик.",449,23],["وَتَرَكْنَا عَلَيْهِ فِى [h:9784[ٱ]لْأَخِر[p[ِي]نَ","Ва кейингилар ичида унинг учун қолдирдик.",449,23],["سَلَ[n[ـٰ]مٌ عَلَىٰ نُو[f:11391[حٍ ف]ِى [h:11392[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Барча оламларда Нуҳга салом бўлсин!",449,23],["إِ[g[نّ]َا كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4215[ٱ]لْمُحْسِن[p[ِي]نَ","Албатта, Биз гўзал амал қилгувчиларни мана шундай мукофотлармиз.",449,23],["إِ[g[نّ]َهُ[n[ۥ] مِنْ عِبَادِنَا [h:11393[ٱ]لْمُؤْمِن[p[ِي]نَ","Албатта, у мўмин бандаларимиздандир.",449,23],["ثُ[g[مّ]َ أَغْرَ[q:9772[قْ]نَا [h:9773[ٱ]لْأَخَر[p[ِي]نَ","Сўнгра қолганларни ғарқ қилдик.",449,23],["۞ وَإِ[g[نّ]َ مِ[f:10087[ن ش]ِيعَتِه[n[ِۦ] لَإِ[q:11394[بْ]ر[n[َٲ]ه[p[ِي]مَ","Албатта, Иброҳим ҳам унинг гуруҳидандир.",449,23],["إِذْ ج[o[َا]ٓءَ رَبَّهُ[n[ۥ] بِقَلْ[f:9790[بٍ س]َل[p[ِي]مٍ","Ўшанда у ўз Роббига соғлом қалб ила келмишди.",449,23],["إِذْ قَالَ لِأَبِيهِ وَقَوْمِه[n[ِۦ] مَاذَا تَعْبُد[p[ُو]نَ","Ўшанда отасига ва қавмига: «Нимага ибодат қилмоқдасиз?!",449,23],["أَئِفْكًا ءَالِهَ[f:11395[ةً د]ُونَ [h:11396[ٱ]للَّهِ تُرِيد[p[ُو]نَ","Аллоҳдан ўзга уйдирма илоҳларни хоҳлайсизларми?!",449,23],["فَمَا ظَ[g[نّ]ُك[c:11397[ُم ب]ِرَبِّ [h:4930[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Оламларнинг Робби ҳақида нима гумонингиз бор?!» демишди.",449,23],["فَنَظَرَ نَظْرَ[f:11398[ةً ف]ِى [h:11399[ٱ][l[ل][g[نّ]ُج[p[ُو]مِ","У юлдузларга бир назар солди",449,23],["فَقَالَ إِ[g[نّ]ِى سَق[p[ِي]مٌ","Ва: «Албатта, мен беморман» деди.",449,23],["فَتَوَلَّوْ[s[اْ] عَنْهُ مُ[q:5528[دْ]بِر[p[ِي]نَ","Дарҳол, ундан юз ўгириб юриб кетдилар.",449,23],["فَرَاغَ إِلَ[o[ىٰٓ] ءَالِهَتِهِمْ فَقَالَ أَلَا تَأْكُل[p[ُو]نَ","Бас, тезда уларнинг худоларига бурилди ва: «Қани, емайсизларми?!",449,23],["مَا لَكُمْ لَا تَ[f:11400[نط]ِق[p[ُو]نَ","Сизга нима бўлди?! Гапирмайсизларми?!» деди.",449,23],["فَرَاغَ عَلَيْهِمْ ضَرْب[i:11401[َۢا ب]ِ[h:11402[ٱ]لْيَم[p[ِي]نِ","Сўнг уларга яқинлашиб, ўнг қўл билан ура бошлади.",449,23],["فَأَ[q:11403[قْ]بَل[o[ُوٓ][s[اْ] إِلَيْهِ يَزِفّ[p[ُو]نَ","Улар у томон шошиб, бир-бирларини туртиб кела бошлади.",449,23],["قَالَ أَتَعْبُدُونَ مَا تَنْحِت[p[ُو]نَ","У: «Ўзингиз йўниб ясаган нарсага ибодат қиласизларми?!",449,23],["وَ[h:9999[ٱ]للَّهُ خَلَقَكُمْ وَمَا تَعْمَل[p[ُو]نَ","Ҳолбуки, сизни ҳам, қолган нарсаларингизни ҳам Аллоҳ яратган-ку?!» деди.",449,23],["قَالُو[s[اْ] [h:11404[ٱ][q:8016[بْ]نُو[s[اْ] لَهُ[n[ۥ] بُنْيَ[n[ـٰ][f:11405[نًا ف]َأَلْقُوهُ فِى [h:11406[ٱ]لْجَح[p[ِي]مِ","Улар: «Унинг учун бино қилинглар, бас, уни гулханга отинглар!» дедилар.",449,23],["فَأَرَادُو[s[اْ] بِه[n[ِۦ] كَيْ[f:8801[دًا ف]َجَعَلْنَ[n[ـٰ]هُمُ [h:11407[ٱ]لْأَسْفَل[p[ِي]نَ","Бас, улар унга макр-ҳийлани ирода қилишди. Биз уларни тубан қилдик.",449,23],["وَقَالَ إِ[g[نّ]ِى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْد[p[ِي]نِ","У: «Албатта, мен Роббимга боргувчиман. У мени ҳидоят қилур.",449,23],["رَبِّ هَ[q:1878[بْ] لِى مِنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Роббим, менга солиҳлардан ато эт», деди.",449,23],["فَبَشَّرْنَ[n[ـٰ]هُ بِغُلَ[n[ـٰ]مٍ حَل[p[ِي]مٍ","Бас, Биз унга бир ҳалим ўғилнинг хушхабарини бердик.",449,23],["فَلَ[g[مّ]َا بَلَغَ مَعَهُ [h:11408[ٱ][l[ل]سَّعْىَ قَالَ يَ[n[ـٰ]بُنَىَّ إِ[g[نّ][o[ِىٓ] أَرَىٰ فِى [h:11409[ٱ]لْمَنَامِ أَ[g[نّ][o[ِىٓ] أَذْبَحُكَ فَ[h:1513[ٱ][f:1513[نظ]ُرْ مَاذَا تَرَىٰ‌ۚ قَالَ يَ[o[ـٰٓ]أَبَتِ [h:11410[ٱ]فْعَلْ مَا تُؤْمَرُ‌ۖ سَتَجِدُن[o[ِىٓ] إِ[f:364[ن ش][o[َا]ٓءَ [h:78[ٱ]للَّهُ مِنَ [h:8837[ٱ][l[ل]صَّ[n[ـٰ]بِر[p[ِي]نَ","Бас, қачонки унинг ўзи билан бирга юрадиган бўлганида: «Эй ўғилчам, мен тушимда сени сўяётганимни кўрмоқдаман, боқиб кўр, нима дейсан?» деди. У: «Эй отажон, сенга амр этилганни бажар, инша Аллоҳ, мени сабр қилгувчилардан топурсан», деди.",449,23],["فَلَ[g[مّ][o[َآ] أَسْلَمَا وَتَلَّهُ[n[ۥ] لِلْجَب[p[ِي]نِ","Икковлари таслим бўлиб, уни пешонасича ётқизганида.",450,23],["وَنَ[n[ـٰ]دَيْنَ[n[ـٰ]هُ أ[a:11411[َن ي]َ[o[ـٰٓ]إِ[q:6429[بْ]ر[n[َٲ]ه[p[ِي]مُ","Биз унга нидо қилдик: «Эй Иброҳим!",450,23],["قَ[q:298[دْ] صَدَّ[q:11412[قْ]تَ [h:11413[ٱ][l[ل]رُّءْي[o[َآ‌ۚ] إِ[g[نّ]َا كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4215[ٱ]لْمُحْسِن[p[ِي]نَ","Батаҳқиқ, сен тушни тасдиқ қилдинг! Албатта, биз гўзал иш қилгувчиларни мана шундай мукофотлаймиз», деб.",450,23],["إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَهُوَ [h:11414[ٱ]لْبَلَ[o[ـٰٓ]ؤُ[s[اْ] [h:11415[ٱ]لْمُب[p[ِي]نُ","Албатта, бу очиқ-ойдин синовнинг айни ўзидир.",450,23],["وَفَدَيْنَ[n[ـٰ]هُ بِذِ[q:11416[بْ]حٍ عَظ[p[ِي]مٍ","Биз унинг ўрнига катта қурбонлик фидо қилдик.",450,23],["وَتَرَكْنَا عَلَيْهِ فِى [h:9784[ٱ]لْأَخِر[p[ِي]نَ","Ва кейингилар ичида унинг учун қолдирдик.",450,23],["سَلَ[n[ـٰ]مٌ عَلَ[o[ىٰٓ] إِ[q:1860[بْ]ر[n[َٲ]ه[p[ِي]مَ","Иброҳимга салом бўлсин!",450,23],["كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4215[ٱ]لْمُحْسِن[p[ِي]نَ","Биз гўзал амал қилгувчиларни шундай мукофотлармиз.",450,23],["إِ[g[نّ]َهُ[n[ۥ] مِنْ عِبَادِنَا [h:11393[ٱ]لْمُؤْمِن[p[ِي]نَ","Чунки у мўмин бандаларимиздандир.",450,23],["وَبَشَّرْنَ[n[ـٰ]هُ بِإِسْحَ[n[ـٰ]قَ نَبِي[a:11417[ًّا م]ِّنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Яна Биз унга солиҳлардан бир Пайғамбар бўлажак Исҳоқнинг хушхабарини бердик.",450,23],["وَبَ[n[ـٰ]رَكْنَا عَلَيْهِ وَعَلَ[o[ىٰٓ] إِسْحَ[n[ـٰ]قَ‌ۚ وَمِ[f:11418[ن ذ]ُرِّيَّتِهِمَا مُحْسِ[a:11419[نٌ و]َظَالِ[u:11420[مٌ ل]ِّنَفْسِه[n[ِۦ] مُب[p[ِي]نٌ","Ва унга ҳам, Исҳоққа ҳам барака бердик. Икковларининг зурриётидан гўзал амал қилгувчи ҳам, ўзига очиқ-ойдин зулм қилгувчи ҳам бўлур.",450,23],["وَلَقَ[q:341[دْ] مَنَ[g[نّ]َا عَلَىٰ مُوسَىٰ وَهَ[n[ـٰ]ر[p[ُو]نَ","Батаҳқиқ, Биз Мусо ва Ҳорунга неъмат бердик.",450,23],["وَنَجَّيْنَ[n[ـٰ]هُمَا وَقَوْمَهُمَا مِنَ [h:8815[ٱ]لْكَرْبِ [h:8816[ٱ]لْعَظ[p[ِي]مِ","Икковларига ва қавмларига катта ғамдан нажот бердик.",450,23],["وَنَصَرْنَ[n[ـٰ]هُمْ فَكَانُو[s[اْ] هُمُ [h:9750[ٱ]لْغَ[n[ـٰ]لِب[p[ِي]نَ","Ва уларга нусрат бердик, бас, улар ғолиб бўлдилар.",450,23],["وَءَاتَيْنَ[n[ـٰ]هُمَا [h:11421[ٱ]لْكِتَ[n[ـٰ]بَ [h:11422[ٱ]لْمُسْتَب[p[ِي]نَ","Ва Биз икковларига равшану комил баёнли китобни бердик.",450,23],["وَهَدَيْنَ[n[ـٰ]هُمَا [h:11423[ٱ][l[ل]صِّر[n[َٲ]طَ [h:7[ٱ]لْمُسْتَق[p[ِي]مَ","Ва икковларини сиротул мустақиймга ҳидоят қилдик.",450,23],["وَتَرَكْنَا عَلَيْهِمَا فِى [h:9784[ٱ]لْأَخِر[p[ِي]نَ","Ва кейингилар ичида икковлари учун қолдирдик.",450,23],["سَلَ[n[ـٰ]مٌ عَلَىٰ مُوسَىٰ وَهَ[n[ـٰ]ر[p[ُو]نَ","Мусо ва Ҳорунга салом бўлсин!",450,23],["إِ[g[نّ]َا كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4215[ٱ]لْمُحْسِن[p[ِي]نَ","Биз гўзал амал қилгувчиларни мана шундай мукофотлармиз.",450,23],["إِ[g[نّ]َهُمَا مِنْ عِبَادِنَا [h:11393[ٱ]لْمُؤْمِن[p[ِي]نَ","Чунки икковлари мўмин бандаларимиздандирлар.",450,23],["وَإِ[g[نّ]َ إِلْيَاسَ لَمِنَ [h:1443[ٱ]لْمُرْسَل[p[ِي]نَ","Албатта, Илёс ҳам Пайғамбарлардандир.",450,23],["إِذْ قَالَ لِقَوْمِه[o[ِۦٓ] أَلَا تَتَّق[p[ُو]نَ","Ўшанда у қавмига: «Тақво қилмайсизми?!",450,23],["أَتَ[q:11424[دْ]عُونَ بَعْل[a:11425[اً و]َتَذَرُونَ أَحْسَنَ [h:11426[ٱ]لْخَ[n[ـٰ]لِق[p[ِي]نَ","Баълга ибодат қилиб, яратувчиларнинг энг яхшисини.",450,23],["ٱللَّهَ رَبَّكُمْ وَرَبَّ ءَاب[o[َا]ٓئِكُمُ [h:9737[ٱ]لْأَوَّل[p[ِي]نَ","Ўз Роббингизни ва аввалги ота-боболарингизнинг Робби Аллоҳни тарк этасизми?!» деди.",450,23],["فَكَذَّبُوهُ فَإِ[g[نّ]َهُمْ لَمُحْضَر[p[ُو]نَ","Бас, уни ёлғончи қилдилар. Энди, албатта, улар ҳозир қилингувчилардир.",451,23],["إِلَّا عِبَادَ [h:11354[ٱ]للَّهِ [h:11355[ٱ]لْمُخْلَص[p[ِي]نَ","Магар Аллоҳнинг мухлис бандаларигина.",451,23],["وَتَرَكْنَا عَلَيْهِ فِى [h:9784[ٱ]لْأَخِر[p[ِي]نَ","Ва кейингилар ичида унинг учун қолдирдик.",451,23],["سَلَ[n[ـٰ]مٌ عَلَ[o[ىٰٓ] إِلْ يَاس[p[ِي]نَ","Илиёсийнга салом бўлсин.",451,23],["إِ[g[نّ]َا كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4215[ٱ]لْمُحْسِن[p[ِي]نَ","Биз гўзал амал қилгувчиларни мана шундай мукофотлармиз.",451,23],["إِ[g[نّ]َهُ[n[ۥ] مِنْ عِبَادِنَا [h:11393[ٱ]لْمُؤْمِن[p[ِي]نَ","Чунки у мўмин бандаларимиздандир.",451,23],["وَإِ[g[نّ]َ لُو[u:11427[طًا ل]َّمِنَ [h:1443[ٱ]لْمُرْسَل[p[ِي]نَ","Албатта, Лут ҳам Пайғамбарлардандир.",451,23],["إِذْ نَجَّيْنَ[n[ـٰ]هُ وَأَهْلَهُ[o[ۥٓ] أَ[q:825[جْ]مَع[p[ِي]نَ","Ўшанда Биз унга ва унинг аҳлига, ҳаммаларига нажот бердик.",451,23],["إِلَّا عَجُو[f:9835[زًا ف]ِى [h:9836[ٱ]لْغَ[n[ـٰ]بِر[p[ِي]نَ","Магар бир кампиргина қолгувчилардан бўлди.",451,23],["ثُ[g[مّ]َ دَ[g[مّ]َرْنَا [h:9837[ٱ]لْأَخَر[p[ِي]نَ","Сўнгра қолганларини ҳалок этдик.",451,23],["وَإِ[g[نّ]َكُمْ لَتَمُرُّونَ عَلَيْه[w:11428[ِم م]ُّصْبِح[p[ِي]نَ","Албатта, сиз уларнинг устидан ўтиб турурсизлар. Эрталаб.",451,23],["وَبِ[h:9999[ٱ]لَّيْلِ‌ۗ أَفَلَا تَعْقِل[p[ُو]نَ","Ва кечда ҳам. Ақл юритмайсизларми?!",451,23],["وَإِ[g[نّ]َ يُونُسَ لَمِنَ [h:1443[ٱ]لْمُرْسَل[p[ِي]نَ","Албатта, Юнус ҳам Пайғамбарлардандир.",451,23],["إِذْ أَبَقَ إِلَى [h:11429[ٱ]لْفُلْكِ [h:9808[ٱ]لْمَشْح[p[ُو]نِ","Ўшанда у тўлган кемага қочди.",451,23],["فَسَاهَمَ فَكَانَ مِنَ [h:11430[ٱ]لْمُ[q:11431[دْ]حَض[p[ِي]نَ","Бас, қуръа ташлашди ва у мағлублардан бўлди.",451,23],["فَ[h:9999[ٱ]لْتَقَمَهُ [h:11432[ٱ]لْحُوتُ وَهُوَ مُل[p[ِي]مٌ","Бас, уни маломатга лойиқ бўлган ҳолида наҳанг балиқ ютди.",451,23],["فَلَوْل[o[َآ] أَ[g[نّ]َهُ[n[ۥ] كَانَ مِنَ [h:11433[ٱ]لْمُسَبِّح[p[ِي]نَ","Агар у кўп тасбиҳ айтгувчилардан бўлмаганида эди.",451,23],["لَلَبِثَ فِى بَ[q:9482[طْ]نِه[o[ِۦٓ] إِلَىٰ يَوْمِ يُ[q:4606[بْ]عَث[p[ُو]نَ","Унинг қорнида қайта тирилтирадиган кунгача қолиб кетар эди.",451,23],["۞ فَنَبَذْنَ[n[ـٰ]هُ بِ[h:11434[ٱ]لْعَر[o[َا]ٓءِ وَهُوَ سَق[p[ِي]مٌ","Бас, Биз уни бемор ҳолида майдонга отдик.",451,23],["وَأَ[i:7218[نۢب]َتْنَا عَلَيْهِ شَجَرَ[a:11435[ةً م]ّ[a:11436[ِن ي]َ[q:11437[قْ]ط[p[ِي]نٍ","Ва унинг устига қовоқ дарахтини ўстириб қўйдик.",451,23],["وَأَرْسَلْنَ[n[ـٰ]هُ إِلَىٰ مِ[s[اْ]ئَةِ أَلْفٍ أَوْ يَزِيد[p[ُو]نَ","Ва уни юз минг ёки ундан кўпроққа Пайғамбар қилиб юбордик.",451,23],["فَـَٔـامَنُو[s[اْ] فَمَتَّعْنَ[n[ـٰ]هُمْ إِلَىٰ ح[p[ِي]نٍ","Бас, иймон келтирдилар. Кейин Биз уларни маълум муддат баҳраманд қилдик.",451,23],["فَ[h:9999[ٱ]سْتَفْتِهِمْ أَلِرَبِّكَ [h:11438[ٱ]لْبَنَاتُ وَلَهُمُ [h:11439[ٱ]لْبَن[p[ُو]نَ","Бас, улардан сўра-чи, Роббингга қизлар-у, уларга ўғиллар эканми?!",451,23],["أَمْ خَلَ[q:5159[قْ]نَا [h:11440[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةَ إِنَ[n[ـٰ][a:11441[ثًا و]َهُمْ شَ[n[ـٰ]هِد[p[ُو]نَ","Ёки Биз фаришталарни қиз қилиб яратганмизу улар гувоҳ бўлиб турганларми?",451,23],["أَل[o[َآ] إِ[g[نّ]َه[w:11442[ُم م]ِّنْ إِفْكِهِمْ لَيَقُول[p[ُو]نَ","Огоҳ бўлингким! Улар ўз уйдирмаларида дерлар:",451,23],["وَلَدَ [h:11443[ٱ]للَّهُ وَإِ[g[نّ]َهُمْ لَكَ[n[ـٰ]ذِب[p[ُو]نَ","«Аллоҳ туғди». Албатта, улар ёлғончилардир.",451,23],["أَصْطَفَى [h:11444[ٱ]لْبَنَاتِ عَلَى [h:11445[ٱ]لْبَن[p[ِي]نَ","У зот ўғилларини қўйиб қизларни танлаб олибдими?",451,23],["مَا لَكُمْ كَيْفَ تَحْكُم[p[ُو]نَ","Сизга нима бўлди?! Қандай ҳукм чиқармоқдасиз?",452,23],["أَفَلَا تَذَكَّر[p[ُو]نَ","Ахир эсламайсизларми?!",452,23],["أَمْ لَكُمْ سُلْطَ[n[ـٰ][a:11446[نٌ م]ُّب[p[ِي]نٌ","Ёки сизда очиқ-ойдин ҳужжат борми?!",452,23],["فَأْتُو[s[اْ] بِكِتَ[n[ـٰ]بِكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Агар ростгўйлардан бўлсангиз, китобингизни келтиринг!",452,23],["وَجَعَلُو[s[اْ] بَيْنَهُ[n[ۥ] وَبَيْنَ [h:11447[ٱ]لْجِ[g[نّ]َةِ نَسَ[a:11448[بًا‌ۚ و]َلَقَ[q:341[دْ] عَلِمَتِ [h:11449[ٱ]لْجِ[g[نّ]َةُ إِ[g[نّ]َهُمْ لَمُحْضَر[p[ُو]نَ","Ва улар У билан жинлар орасида насаб қилдилар. Ҳолбуки, жинлар ўзларининг, албатта, ҳозир қилингувчиликларини билганлар.",452,23],["سُ[q:7648[بْ]حَ[n[ـٰ]نَ [h:9282[ٱ]للَّهِ عَ[g[مّ]َا يَصِف[p[ُو]نَ","Аллоҳ улар васф қилган нарсадан покдир.",452,23],["إِلَّا عِبَادَ [h:11354[ٱ]للَّهِ [h:11355[ٱ]لْمُخْلَص[p[ِي]نَ","Фақат Аллоҳнинг ихлосли бандаларигина.",452,23],["فَإِ[g[نّ]َكُمْ وَمَا تَعْبُد[p[ُو]نَ","Албатта, сиз ҳам, сиз ибодат қилаётган нарсалар ҳам.",452,23],["م[o[َآ] أَ[f:428[نت]ُمْ عَلَيْهِ بِفَ[n[ـٰ]تِن[p[ِي]نَ","У зотга қарши фитнага солгувчи бўла олмассиз.",452,23],["إِلَّا مَنْ هُوَ صَالِ [h:11450[ٱ]لْجَح[p[ِي]مِ","Ўзи жаҳаннамга киргувчи кимсадан бошқани.",452,23],["وَمَا مِ[g[نّ][o[َآ] إِلَّا لَهُ[n[ۥ] مَقَا[a:11451[مٌ م]َّعْل[p[ُو]مٌ","Биздан ҳар биримизнинг маълум мақоми бордир.",452,23],["وَإِ[g[نّ]َا لَنَحْنُ [h:11452[ٱ][l[ل]صّ[m[َا]ٓفّ[p[ُو]نَ","Албатта, бизлар саф тортиб тургувчилармиз.",452,23],["وَإِ[g[نّ]َا لَنَحْنُ [h:11453[ٱ]لْمُسَبِّح[p[ُو]نَ","Ва, албатта, бизлар тасбиҳ айтгувчилармиз.",452,23],["وَإِ[f:2392[ن ك]َانُو[s[اْ] لَيَقُول[p[ُو]نَ","Ҳолбуки, улар дер эдилар:",452,23],["لَوْ أَ[g[نّ]َ عِ[f:2359[ند]َنَا ذِكْ[a:11454[رًا م]ِّنَ [h:11455[ٱ]لْأَوَّل[p[ِي]نَ","«Агар бизнинг ҳузуримизда ҳам аввалгилардан бир эслатма бўлганида.",452,23],["لَكُ[g[نّ]َا عِبَادَ [h:11354[ٱ]للَّهِ [h:11355[ٱ]لْمُخْلَص[p[ِي]نَ","Албатта, Аллоҳнинг ихлосли бандаларидан бўлар эдик».",452,23],["فَكَفَرُو[s[اْ] بِه[n[ِۦ]‌ۖ فَسَوْفَ يَعْلَم[p[ُو]نَ","Бас, унга куфр келтирдилар. Энди яқинда билурлар.",452,23],["وَلَقَ[q:341[دْ] سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا [h:11456[ٱ]لْمُرْسَل[p[ِي]نَ","Батаҳқиқ, Пайғамбар этиб юборилган бандаларимизга сўзимиз ўтгандир.",452,23],["إِ[g[نّ]َهُمْ لَهُمُ [h:11457[ٱ]لْمَ[f:11458[نص]ُور[p[ُو]نَ","Албатта, улар, ҳа, уларгина нусрат топишлари.",452,23],["وَإِ[g[نّ]َ جُ[f:11459[ند]َنَا لَهُمُ [h:11460[ٱ]لْغَ[n[ـٰ]لِب[p[ُو]نَ","Ва, албатта, Бизнинг лашкаримизгина ғолиб бўлиши ҳақида.",452,23],["فَتَوَلَّ عَنْهُمْ حَتَّىٰ ح[p[ِي]نٍ","Бас, сен улардан бир вақтгача юз ўгир.",452,23],["وَأَ[q:11461[بْ]صِرْهُمْ فَسَوْفَ يُ[q:60[بْ]صِر[p[ُو]نَ","Ва уларнинг кўр! Бас, тезда ўзлари ҳам кўрурлар.",452,23],["أَفَبِعَذَابِنَا يَسْتَعْجِل[p[ُو]نَ","Ҳали улар Бизнинг азобимизни шошилтирмоқдамилар?!",452,23],["فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَس[o[َا]ٓءَ صَبَاحُ [h:11462[ٱ]لْمُ[f:6137[نذ]َر[p[ِي]نَ","Қачонки, у уларнинг ҳовлисига тушганида, огоҳлантирилганларнинг тонги жуда ёмон бўлур.",452,23],["وَتَوَلَّ عَنْهُمْ حَتَّىٰ ح[p[ِي]نٍ","Бас, сен улардан бир вақтгача юз ўгир.",452,23],["وَأَ[q:8337[بْ]صِرْ فَسَوْفَ يُ[q:60[بْ]صِر[p[ُو]نَ","Ва уларнинг кўр! Бас, тезда ўзлари ҳам кўрурлар.",452,23],["سُ[q:7648[بْ]حَ[n[ـٰ]نَ رَبِّكَ رَبِّ [h:11463[ٱ]لْعِزَّةِ عَ[g[مّ]َا يَصِف[p[ُو]نَ","Сенинг Роббинг, иззат Робби улар қилган васфдан покдир.",452,23],["وَسَلَ[n[ـٰ]مٌ عَلَى [h:11464[ٱ]لْمُرْسَل[p[ِي]نَ","Ва Пайғамбарларга салом бўлсин!",452,23],["وَ[h:9999[ٱ]لْحَمْدُ لِلَّهِ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Оламларнинг Робби Аллоҳга ҳамдлар бўлсин!",452,23]]},{"n":38,"ar":"صٓ","en":"Saad","uz":"Сод","type":"Макка","ayahs":[["[m[صٓ]‌ۚ وَ[h:5855[ٱ]لْقُرْءَانِ ذِى [h:11465[ٱ][l[ل]ذِّكْرِ","Сод. Зикр соҳиби бўлмиш Қуръон ила қасам.",453,23],["بَلِ [h:10932[ٱ]لَّذِينَ كَفَرُو[s[اْ] فِى عِزَّ[a:11466[ةٍ و]َشِق[p[َا][q[ق]ٍ","Аммо куфр келтирганлар кибру ҳаво ва мухолифликдадирлар.",453,23],["كَمْ أَهْلَكْنَا مِ[f:617[ن ق]َ[q:618[بْ]لِه[w:3926[ِم م]ِّ[f:3927[ن ق]َرْ[f:11467[نٍ ف]َنَادَو[s[اْ] وَّلَاتَ حِينَ مَن[p[َا]صٍ","Биз улардан илгари ҳам қанча асрларни ҳалок этганмиз. Улар нидо қилдилар. Аммо қочиб қутулиш вақти эмас эди.",453,23],["وَعَجِب[o[ُوٓ][s[اْ] أَ[f:11468[ن ج][o[َا]ٓءَه[w:11469[ُم م]ُّ[f:6895[نذ]ِ[a:11470[رٌ م]ِّنْهُمْ‌ۖ وَقَالَ [h:11471[ٱ]لْكَ[n[ـٰ]فِرُونَ هَ[n[ـٰ]ذَا سَ[n[ـٰ]حِ[f:11472[رٌ ك]َذّ[p[َا][q[ب]ٌ","Уларнинг ичларига ўзларидан огоҳлантиргувчи келганидан ажабландилар ва кофирлар: «Бу сеҳргар ва каззобдир.",453,23],["أَجَعَلَ [h:11473[ٱ]لْأَلِهَةَ إِلَ[n[ـٰ][a:693[هًا و][n[َٲ]حِدًا‌ۖ إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَشَىْءٌ عُج[p[َا][q[ب]ٌ","У худоларни битта худо қилдими?! Албатта, бу ажабланарли нарса!» дедилар.",453,23],["وَ[h:9999[ٱ][f:11474[نط]َلَقَ [h:11475[ٱ]لْمَلَأُ مِنْهُمْ أَنِ [h:11476[ٱ]مْشُو[s[اْ] وَ[h:11477[ٱ]صْبِرُو[s[اْ] عَلَ[o[ىٰٓ] ءَالِهَتِكُمْ‌ۖ إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَش[a:11478[َىْءٌ ي]ُر[p[َا][q[د]ُ","Уларнинг аъёнлари: «Юринглар, худоларингиз тўғрисида сабр қилинглар. Албатта, бу қасддан қилинаётган нарсадир.",453,23],["مَا سَمِعْنَا بِهَ[n[ـٰ]ذَا فِى [h:11479[ٱ]لْمِلَّةِ [h:11480[ٱ]لْأَخِرَةِ إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا [h:11481[ٱ]خْتِلَ[p[ـٰ][q[ق]ٌ","Биз бу ҳақда охирги миллатдан эшитганимиз йўқ. Бу тўқилгандан бошқа нарса эмас.",453,23],["أَءُ[f:11482[نز]ِلَ عَلَيْهِ [h:7197[ٱ][l[ل]ذِّكْرُ م[i:4086[ِنۢ ب]َيْنِنَا‌ۚ بَلْ هُمْ فِى شَ[a:6215[كٍّ م]ِّ[f:11483[ن ذ]ِكْرِى‌ۖ بَل لَّ[g[مّ]َا يَذُوقُو[s[اْ] عَذ[p[َا][q[ب]ِ","Бизнинг ичимиздан ўшанга зикр нозил қилинибдими?!» деб туриб кетдилар. Йўқ! Улар Менинг зикрим ҳақида шак-шубҳададирлар. Йўқ! Улар азобимни татиб кўрмадилар.",453,23],["أَمْ عِ[f:5060[ند]َهُمْ خَز[o[َا]ٓئِنُ رَحْمَةِ رَبِّكَ [h:11484[ٱ]لْعَزِيزِ [h:11485[ٱ]لْوَهّ[p[َا][q[ب]ِ","Ёки уларнинг ҳузурида азизу ўта саҳоватли Роббингнинг раҳмат хазинаси борми?",453,23],["أَمْ لَه[w:11486[ُم م]ُّلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَيْنَهُمَا‌ۖ فَلْيَرْتَقُو[s[اْ] فِى [h:11487[ٱ]لْأَسْبَ[p[ـٰ][q[ب]ِ","Ёки осмонлару ернинг ва улар орасидаги нарсаларнинг мулки уларникими? Бас, унда сабаблари ила кўтарилсинлар!",453,23],["جُن[a:11488[دٌ م]َّا هُنَالِكَ مَهْزُو[a:11489[مٌ م]ِّنَ [h:6277[ٱ]لْأَحْز[p[َا][q[ب]ِ","Анави ердаги енгилган фирқалардан бўлган қандайдир лашкар.",453,23],["كَذَّبَتْ قَ[q:8394[بْ]لَهُمْ قَوْمُ نُو[a:9048[حٍ و]َعَا[a:11490[دٌ و]َفِرْعَوْنُ ذُو [h:11491[ٱ]لْأَوْت[p[َا][q[د]ِ","Улардан олдин ҳам Нуҳ қавми, Од, қозиқлар эгаси Фиръавн ҳам ёлғончи қилган.",453,23],["وَثَمُودُ وَقَوْمُ لُو[a:11492[طٍ و]َأَصْحَ[n[ـٰ]بُ لْــَٔيْكَةِ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:11493[ٱ]لْأَحْز[p[َا][q[ب]ُ","Ва Самуд, Лут қавми ва дарахтзор эгалари ҳам. Фирқалар ўшалардир.",453,23],["إِ[f:11494[ن ك]ُلٌّ إِلَّا كَذَّبَ [h:11495[ٱ][l[ل]رُّسُلَ فَحَقَّ عِق[p[َا][q[ب]ِ","Барчалари, албатта, Пайғамбарларни ёлғончи қилдилар. Бас, Менинг иқобим ҳақ бўлди.",453,23],["وَمَا يَ[f:2039[نظ]ُرُ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ إِلَّا صَيْحَ[a:11222[ةً و][n[َٲ]حِدَ[a:11496[ةً م]َّا لَهَا مِ[f:11497[ن ف]َو[p[َا][q[ق]ٍ","Ана ўшалар бир лаҳзага кечикмай келадиган биргина қичқириқдан бошқа нарсага интизор бўлаётганлари йўқ",453,23],["وَقَالُو[s[اْ] رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَ[q:3282[بْ]لَ يَوْمِ [h:11498[ٱ]لْحِس[p[َا][q[ب]ِ","Улар: «Эй Роббимиз, бизга ҳисоб кунидан илгари насибамизни тезроқ бер!» дедилар.",453,23],["ٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَ[h:1898[ٱ]ذْكُرْ عَ[q:11499[بْ]دَنَا دَاوُ[n[ۥ]دَ ذَا [h:11500[ٱ]لْأَيْدِ‌ۖ إِ[g[نّ]َهُ[o[ۥٓ] أَوّ[p[َا][q[ب]ٌ","Улар айтаётган нарсаларга сабр қил. Қувват соҳиби бўлган бандамиз Довудни эсла. Албатта, у ўта қайтгувчидир.",454,23],["إِ[g[نّ]َا سَخَّرْنَا [h:11501[ٱ]لْجِبَالَ مَعَهُ[n[ۥ] يُسَبِّحْنَ بِ[h:1900[ٱ]لْعَشِىِّ وَ[h:11502[ٱ]لْإِشْر[p[َا][q[ق]ِ","Албатта, Биз унга тоғларни бўйсундирдик. Улар у билан кечки пайту эрталаб тасбиҳ айтардилар.",454,23],["وَ[h:9999[ٱ][l[ل]طَّيْرَ مَحْشُورَ[f:11503[ةً‌ۖ ك]ُ[u:610[لٌّ ل]َّهُ[o[ۥٓ] أَوّ[p[َا][q[ب]ٌ","Тўпланган ҳолдаги қушларни ҳам. Барчалари У зотга ўта қайтгувчилардир.",454,23],["وَشَدَ[q:11504[دْ]نَا مُلْكَهُ[n[ۥ] وَءَاتَيْنَ[n[ـٰ]هُ [h:11505[ٱ]لْحِكْمَةَ وَفَصْلَ [h:11506[ٱ]لْخِط[p[َا][q[ب]ِ","Ва Биз унга мулкини қувватли қилиб бердик ҳамда ҳикматни ва ҳал қилгувчи китобни бердик.",454,23],["۞ وَهَلْ أَتَ[n[ـٰ]كَ نَبَؤُ[s[اْ] [h:11507[ٱ]لْخَصْمِ إِذْ تَسَوَّرُو[s[اْ] [h:11508[ٱ]لْمِحْر[p[َا][q[ب]َ","Сенга даъволашганларнинг хабари келдими? Ўшанда улар меҳробга чиқишган эди.",454,23],["إِذْ دَخَلُو[s[اْ] عَلَىٰ دَاوُ[n[ۥ]دَ فَفَزِعَ مِنْهُمْ‌ۖ قَالُو[s[اْ] لَا تَخَفْ‌ۖ خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْ[f:11509[ضٍ ف]َ[h:3549[ٱ]حْك[c:11510[ُم ب]َيْنَنَا بِ[h:370[ٱ]لْحَقِّ وَلَا تُشْطِ[q:11511[طْ] وَ[h:11512[ٱ]هْدِن[o[َآ] إِلَىٰ سَو[o[َا]ٓءِ [h:11513[ٱ][l[ل]صِّر[p[َٲ][q[ط]ِ","Ўшанда улар Довуднинг олдига киришган эди. Бас, у улардан қўрқиб кетди. Улар: «Қўрқма, булар–икки даъволашгувчи томон. Биз бир-биримизга зулм қилдик. Бас, орамизда ҳақ ила ҳукм чиқар. Жабр қилма. Бизларни тўғри йўлга ҳидоят қил», дедилар.",454,23],["إِ[g[نّ]َ هَ[n[ـٰ]ذ[o[َآ] أَخِى لَهُ[n[ۥ] تِسْ[a:11514[عٌ و]َتِسْعُونَ نَعْجَ[a:11515[ةً و]َلِىَ نَعْجَ[a:11516[ةٌ و][n[َٲ]حِدَ[f:11517[ةٌ ف]َقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى [h:11518[ٱ]لْخِط[p[َا][q[ب]ِ","«Мана бу менинг биродарим. Унинг тўқсон тўққизта совлиғи бор. Менинг эса, биргина совлиғим бор. Бас, у: «Уни ҳам менинг кафолатимга бер», деди ва сўзлашувда мендан устун чиқди».",454,23],["قَالَ لَقَ[q:2389[دْ] ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِه[n[ِۦ]‌ۖ وَإِ[g[نّ]َ كَثِي[a:3614[رًا م]ِّنَ [h:11519[ٱ]لْخُلَط[o[َا]ٓءِ لَيَ[q:11520[بْ]غِى بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا [h:778[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ وَقَلِي[a:11521[لٌ م]َّا هُمْ‌ۗ وَظَ[g[نّ]َ دَاوُ[n[ۥ]دُ أَ[g[نّ]َمَا فَتَ[g[نّ]َ[n[ـٰ]هُ فَ[h:11522[ٱ]سْتَغْفَرَ رَبَّهُ[n[ۥ] وَخَرَّ رَاكِ[a:11523[عًا و]َأَنَ[p[ا][q[ب]َ ۩","У: «Дарҳақиқат, сенинг совлиғингни сўраб, ўз совлиқларига билан сенга зулм қилибдир. Албатта, кўп шериклар бир-бирларига зулм қилурлар. Магар иймон келтириб, солиҳ амал қилганларгина. Улар жуда ҳам оз», деди. Ва Довуд Биз уни синаганимизни билди-да, тезда Роббига истиғфор айтиб, саждага йиқилди ва тавба қилди.",454,23],["فَغَفَرْنَا لَهُ[n[ۥ] ذ[n[َٲ]لِكَ‌ۖ وَإِ[g[نّ]َ لَهُ[n[ۥ] عِ[f:2359[ند]َنَا لَزُلْفَىٰ وَحُسْنَ مَــٔ[p[َا][q[ب]ٍ","Бас, Биз унинг ўшани мағфират қилдик. Албатта, унинг учун ҳузуримизда яқинлик ва гўзал оқибат бордир.",454,23],["يَ[n[ـٰ]دَاوُ[n[ۥ]دُ إِ[g[نّ]َا جَعَلْنَ[n[ـٰ]كَ خَلِيفَ[f:11524[ةً ف]ِى [h:44[ٱ]لْأَرْضِ فَ[h:3549[ٱ]حْك[c:11525[ُم ب]َيْنَ [h:1165[ٱ][l[ل][g[نّ]َاسِ بِ[h:370[ٱ]لْحَقِّ وَلَا تَتَّبِعِ [h:11526[ٱ]لْهَوَىٰ فَيُضِلَّكَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ‌ۚ إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَضِلُّونَ عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ لَهُمْ عَذَا[f:1727[بٌ ش]َدِي[i:4392[دُۢ ب]ِمَا نَسُو[s[اْ] يَوْمَ [h:11527[ٱ]لْحِس[p[َا][q[ب]ِ","Эй Довуд, албатта, Биз сени ер юзида халифа қилдик. Бас, одамлар орасида ҳақ ила ҳукм юрит. Ҳавои нафсга эргашма! Яна у сени Аллоҳнинг йўлидан адаштирмасин. Албатта, Аллоҳнинг йўлидан адашадиганларга унутганлари учун ҳисоб кунида шиддатли азоб бордир.",454,23],["وَمَا خَلَ[q:5159[قْ]نَا [h:8692[ٱ][l[ل]سَّم[o[َا]ٓءَ وَ[h:1474[ٱ]لْأَرْضَ وَمَا بَيْنَهُمَا بَ[n[ـٰ]طِل[f:11528[اً‌ۚ ذ][n[َٲ]لِكَ ظَ[g[نّ]ُ [h:6104[ٱ]لَّذِينَ كَفَرُو[s[اْ‌ۚ] فَوَيْ[u:396[لٌ ل]ِّلَّذِينَ كَفَرُو[s[اْ] مِنَ [h:869[ٱ][l[ل][g[نّ][p[َا]رِ","Биз осмону ерни ва уларнинг орасидаги нарсаларни беҳуда яратганимиз йўқ. Бу куфр келтирганларнинг гумонидир. Бас, куфр келтирганлар учун дўзахдан вой бўлсин!",455,23],["أَمْ نَ[q:8225[جْ]عَلُ [h:11529[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ كَ[h:11530[ٱ]لْمُفْسِدِينَ فِى [h:44[ٱ]لْأَرْضِ أَمْ نَ[q:8225[جْ]عَلُ [h:11531[ٱ]لْمُتَّقِينَ كَ[h:11532[ٱ]لْفُجّ[p[َا]رِ","Йўқ! Биз иймон келтириб, солиҳ амаллар қилганларни ер юзида бузғунчилик қилувчилар каби қилармидик?! Йўқ! Биз тақводорларни фожирлар каби қилармидик?!",455,23],["كِتَ[n[ـٰ]بٌ أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ إِلَيْكَ مُبَ[n[ـٰ]رَ[u:11533[كٌ ل]ِّيَدَّبَّر[o[ُوٓ][s[اْ] ءَايَ[n[ـٰ]تِه[n[ِۦ] وَلِيَتَذَكَّرَ أُ[s[وْ]لُو[s[اْ] [h:1595[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","Биз сенга нозил қилган Китоб муборакдир. Ақл эгалари унинг оятларини тадаббур қилишлари ва эслашлари учундир.",455,23],["وَوَهَ[q:4212[بْ]نَا لِدَاوُ[n[ۥ]دَ سُلَيْمَ[n[ـٰ]نَ‌ۚ نِعْمَ [h:11534[ٱ]لْعَ[q:11535[بْ]دُ‌ۖ إِ[g[نّ]َهُ[o[ۥٓ] أَوّ[p[َا][q[ب]ٌ","Ва Биз Довудга Сулаймонни ҳадя қилдик. У қандай ҳам яхши бандадир. Албатта, у ўта қайтгувчидир.",455,23],["إِذْ عُرِضَ عَلَيْهِ بِ[h:1900[ٱ]لْعَشِىِّ [h:11536[ٱ][l[ل]صَّ[n[ـٰ]فِنَ[n[ـٰ]تُ [h:11537[ٱ]لْجِي[p[َا][q[د]ُ","Эсла, бир оқшом унга гижинглаб турган учқур отлар кўрсатилди.",455,23],["فَقَالَ إِ[g[نّ][o[ِىٓ] أَحْبَ[q:11538[بْ]تُ حُبَّ [h:11539[ٱ]لْخَيْرِ عَ[f:3773[ن ذ]ِكْرِ رَبِّى حَتَّىٰ تَوَارَتْ بِ[h:11540[ٱ]لْحِج[p[َا][q[ب]ِ","У: «Албатта, мен Роббимнинг зикридан кўра дунё ишқига берилиб кетиб, ҳатто парда ила беркинибди-ку!",455,23],["رُدُّوهَا عَلَىَّ‌ۖ فَطَفِقَ مَسْح[i:11541[َۢا ب]ِ[h:11542[ٱ][l[ل]سُّوقِ وَ[h:11543[ٱ]لْأَعْن[p[َا][q[ق]ِ","Уларни менга қайтаринг!» деди. Сўнгра уларнинг оёқ ва бўйинларини «силай» бошлади!",455,23],["وَلَقَ[q:341[دْ] فَتَ[g[نّ]َا سُلَيْمَ[n[ـٰ]نَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّه[n[ِۦ] جَسَ[f:11544[دًا ث]ُ[g[مّ]َ أَن[p[َا][q[ب]َ","Батаҳқиқ, Биз Сулаймонни синадик. Унинг курсисига жасадни ташладик. Сўнгра у тавба қилди.",455,23],["قَالَ رَبِّ [h:5032[ٱ]غْفِرْ لِى وَهَ[q:1745[بْ] لِى مُلْ[u:11545[كًا ل]َّا يَ[i:8425[نۢب]َغِى لِأَحَ[a:11546[دٍ م]ّ[i:692[ِنۢ ب]َعْد[o[ِىٓ‌ۖ] إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:1748[ٱ]لْوَهّ[p[َا][q[ب]ُ","У: «Эй Роббим, мени мағфират қилгин ва менга ўзимдан кейин бирор кишига муяссар бўлмайдиган мулкни ҳадя этгин. Албатта, сен кўплаб атоларни бергувчисан», деди.",455,23],["فَسَخَّرْنَا لَهُ [h:11547[ٱ][l[ل]رِّيحَ تَ[q:120[جْ]رِى بِأَمْرِه[n[ِۦ] رُخ[o[َا]ٓءً حَيْثُ أَص[p[َا][q[ب]َ","Бас, Биз унга шамолни бўйинсундирдик, у ирода қилган томонга майин эсаверади.",455,23],["وَ[h:9999[ٱ][l[ل]شَّيَ[n[ـٰ]طِينَ كُلَّ بَ[g[نّ][o[َا]ٓ[a:11548[ءٍ و]َغَوّ[p[َا]صٍ","Яна барча бинокор ва ғаввос шайтонларни ҳам.",455,23],["وَءَاخَرِينَ مُقَرَّنِينَ فِى [h:7184[ٱ]لْأَصْف[p[َا][q[د]ِ","Ва бошқаларини ҳам кишанланган ҳолда тўплаб.",455,23],["هَ[n[ـٰ]ذَا عَط[o[َا]ٓؤُنَا فَ[h:11549[ٱ]مْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِس[p[َا][q[ب]ٍ","Бу Бизнинг ато этган нарсамиздир. Инъом эт ёки тутиб қол, ҳисоб йўқ.",455,23],["وَإِ[g[نّ]َ لَهُ[n[ۥ] عِ[f:2359[ند]َنَا لَزُلْفَىٰ وَحُسْنَ مَــٔ[p[َا][q[ب]ٍ","Ва, албатта, унинг учун ҳузуримизда яқинлик ва гўзал оқибат бордир.",455,23],["وَ[h:9999[ٱ]ذْكُرْ عَ[q:11499[بْ]دَن[o[َآ] أَيُّوبَ إِذْ نَادَىٰ رَبَّهُ[o[ۥٓ] أَ[g[نّ]ِى مَسَّنِىَ [h:11550[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ بِنُصْ[a:11551[بٍ و]َعَذ[p[َا][q[ب]ٍ","Бизнинг бандамиз Аййубни эсла. Ўшанда у Роббига нидо қилиб: «Албатта, мени шайтон машаққат ва азоб ила тутди», деди.",455,23],["ٱرْكُضْ بِرِ[q:11552[جْ]لِكَ‌ۖ هَ[n[ـٰ]ذَا مُغْتَسَ[i:11553[لُۢ ب]َارِ[a:11554[دٌ و]َشَر[p[َا][q[ب]ٌ","«Оёғинг ила тепгин! Бу чўмиладиган ва ичиладиган совуқ»,.",455,23],["وَوَهَ[q:4212[بْ]نَا لَهُ[o[ۥٓ] أَهْلَهُ[n[ۥ] وَمِثْلَه[w:8834[ُم م]َّعَهُمْ رَحْمَ[a:11254[ةً م]ِّ[g[نّ]َا وَذِكْرَىٰ لِأُ[s[وْ]لِى [h:11555[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","Ва биз унга аҳлини ва яна улар билан бирга мислларичани ҳам ҳадя этдик. Бу Биздан раҳмат ўлароқ ва ақл эгаларига эслатма учун бўлди.",456,23],["وَخُذْ بِيَدِكَ ضِغْ[f:11556[ثًا ف]َ[h:8556[ٱ]ضْرِب بِّه[n[ِۦ] وَلَا تَحْنَثْ‌ۗ إِ[g[نّ]َا وَجَ[q:11557[دْ]نَ[n[ـٰ]هُ صَابِ[a:11558[رًا‌ۚ ن]ِّعْمَ [h:11534[ٱ]لْعَ[q:11535[بْ]دُ‌ۖ إِ[g[نّ]َهُ[o[ۥٓ] أَوّ[p[َا][q[ب]ٌ","«Қўлингга бир дастани ол-да, у билан ур. Қасамингни бузма»,. Биз уни сабрли топдик. У қандай ҳам яхши банда. Албатта, у ўта қайтгувчидир.",456,23],["وَ[h:9999[ٱ]ذْكُرْ عِبَ[n[ـٰ]دَن[o[َآ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَإِسْحَ[n[ـٰ]قَ وَيَعْقُوبَ أُ[s[وْ]لِى [h:11559[ٱ]لْأَيْدِى وَ[h:11560[ٱ]لْأَ[q:11560[بْ]صَ[p[ـٰ]رِ","Қўллар ва кўзлар соҳиблари бўлган бандаларимиз Иброҳим, Исҳоқ ва Яъқубларни эсла.",456,23],["إِ[g[نّ][o[َآ] أَخْلَصْنَ[n[ـٰ]ه[c:11561[ُم ب]ِخَالِصَ[f:11562[ةٍ ذ]ِكْرَى [h:11563[ٱ][l[ل]دّ[p[َا]رِ","Албатта, Биз уларни холис бир хислат-ла ажратдик. У диёрини эслаш эди.",456,23],["وَإِ[g[نّ]َهُمْ عِ[f:2359[ند]َنَا لَمِنَ [h:11564[ٱ]لْمُصْطَفَيْنَ [h:11565[ٱ]لْأَخْي[p[َا]رِ","Албатта, улар Бизнинг ҳузуримизда танланган ахёрлардандир.",456,23],["وَ[h:9999[ٱ]ذْكُرْ إِسْمَ[n[ـٰ]عِيلَ وَ[h:4217[ٱ]لْيَسَعَ وَذَا [h:8836[ٱ]لْكِفْلِ‌ۖ وَكُ[a:11566[لٌّ م]ِّنَ [h:11567[ٱ]لْأَخْي[p[َا]رِ","Исмоил, ал-Ясаъ ва Зул-Кифлни ҳам эсла. Барчалари ахёрлардандир.",456,23],["هَ[n[ـٰ]ذَا ذِكْ[a:11568[رٌ‌ۚ و]َإِ[g[نّ]َ لِلْمُتَّقِينَ لَحُسْنَ مَــٔ[p[َا][q[ب]ٍ","Бу эслатмадир. Албатта, тақводорлар учун гўзал оқибат.",456,23],["جَ[g[نّ]َ[n[ـٰ]تِ عَ[q:5720[دْ][a:11569[نٍ م]ُّفَتَّحَ[u:11570[ةً ل]َّهُمُ [h:11571[ٱ]لْأَ[q:11572[بْ]و[p[َٲ][q[ب]ُ","Улар учун эшиклари очиқ адн жаннатлари бордир.",456,23],["مُتَّكِــِٔينَ فِيهَا يَ[q:1240[دْ]عُونَ فِيهَا بِفَ[n[ـٰ]كِهَ[f:11573[ةٍ ك]َثِيرَ[a:11574[ةٍ و]َشَر[p[َا][q[ب]ٍ","У ерда ёнбошлаган ҳолларида ундаги кўплаб мевалар ва шароблардан чақирарлар.",456,23],["۞ وَعِ[f:11364[ند]َهُمْ قَ[n[ـٰ]صِر[n[َٲ]تُ [h:11365[ٱ][l[ل]طَّرْفِ أَتْر[p[َا][q[ب]ٌ","Уларнинг ҳузурида кўзларини тийган тенгдош лар бордир.",456,23],["هَ[n[ـٰ]ذَا مَا تُوعَدُونَ لِيَوْمِ [h:11575[ٱ]لْحِس[p[َا][q[ب]ِ","Бу сизга ҳисоб куни учун ваъда этилган нарсалардир.",456,23],["إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَرِزْقُنَا مَا لَهُ[n[ۥ] م[a:11576[ِن ن]َّف[p[َا][q[د]ٍ","Албатта, бу Бизнинг ризқимиздир. Унинг ъеч тугаши йщқдир.",456,23],["هَ[n[ـٰ]ذَا‌ۚ وَإِ[g[نّ]َ لِلطَّ[n[ـٰ]غِينَ لَشَرَّ مَــٔ[p[َا][q[ب]ٍ","бундайдир. Албатта, туғёнга кетгувчилар учун ёмон оқибат.",456,23],["جَهَ[g[نّ]َمَ يَصْلَوْنَهَا فَبِئْسَ [h:11577[ٱ]لْمِه[p[َا][q[د]ُ","Жаҳаннам бордир. Унга кирурлар. Бас, у қандай ҳам ёмон ётоқ!",456,23],["هَ[n[ـٰ]ذَا فَلْيَذُوقُوهُ حَمِي[a:11578[مٌ و]َغَسّ[p[َا][q[ق]ٌ","Мана буни татиб турсинлар, қайноқ сув ва йирингни!",456,23],["وَءَاخَرُ مِ[f:11579[ن ش]َكْلِه[o[ِۦٓ] أَزْو[p[َٲ][q[ج]ٌ","Ва бошқа унинг шаклидаги қўша-қўшаларни ҳам.",456,23],["هَ[n[ـٰ]ذَا فَوْ[a:11580[جٌ م]ُّ[q:11581[قْ]تَحِ[a:11582[مٌ م]َّعَكُمْ‌ۖ لَا مَرْحَب[i:11583[َۢا ب]ِهِمْ‌ۚ إِ[g[نّ]َهُمْ صَالُو[s[اْ] [h:11584[ٱ][l[ل][g[نّ][p[َا]رِ","«Мана бу гуруҳ ҳам сиз билан бирга бостириб киргувчидир. Уларга марҳабо йўқ. Улар, албатта, жаҳаннамга киргувчилардир»,.",456,23],["قَالُو[s[اْ] بَلْ أَ[f:428[نت]ُمْ لَا مَرْحَب[i:11585[َۢا ب]ِكُمْ‌ۖ أَ[f:428[نت]ُمْ قَدَّمْتُمُوهُ لَنَا‌ۖ فَبِئْسَ [h:11586[ٱ]لْقَر[p[َا]رُ","Улар: «Йўқ! Ўзингизга марҳабо йўқ! Сизлар ўша ни бизга тақдим қилдингиз! Бас, у нақадар ёмон қароргоҳ!» дерлар.",456,23],["قَالُو[s[اْ] رَبَّنَا مَ[f:11587[ن ق]َدَّمَ لَنَا هَ[n[ـٰ]ذَا فَزِ[q:11588[دْ]هُ عَذَا[f:4678[بًا ض]ِعْ[f:11589[فًا ف]ِى [h:4674[ٱ][l[ل][g[نّ][p[َا]رِ","Улар: «Эй Роббимиз, бизга буни ким тақдим этган бўлса, унга дўзахда икки баробар азобни зиёда қил!» дерлар.",456,23],["وَقَالُو[s[اْ] مَا لَنَا لَا نَرَىٰ رِجَال[f:11590[اً ك]ُ[g[نّ]َا نَعُدُّه[w:11591[ُم م]ِّنَ [h:11592[ٱ]لْأَشْر[p[َا]رِ","Улар: «Бизга нима бўлди? Ёмонлардан ҳисоблаб юрган кишиларимизни кўрмаяпмиз?",457,23],["أَتَّخَذْنَ[n[ـٰ]هُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ [h:11593[ٱ]لْأَ[q:4305[بْ]صَ[p[ـٰ]رُ","Биз уларни масхара қилиб олган эдикми?! Ёки кўзлар улардан тойдими?!» дерлар.",457,23],["إِ[g[نّ]َ ذ[n[َٲ]لِكَ لَحَ[f:11594[قٌّ ت]َخَاصُمُ أَهْلِ [h:11595[ٱ][l[ل][g[نّ][p[َا]رِ","Албатта, мана шу ҳақдир–дўзах аҳлининг ўзаро тортишувидир.",457,23],["قُلْ إِ[g[نّ]َم[o[َآ] أَنَا۟ مُ[f:6895[نذ]ِ[a:11596[رٌ‌ۖ و]َمَا مِنْ إِلَ[n[ـٰ]هٍ إِلَّا [h:1742[ٱ]للَّهُ [h:11597[ٱ]لْو[n[َٲ]حِدُ [h:6662[ٱ]لْقَهّ[p[َا]رُ","Сен: «Мен фақат огоҳлантиргувчиман, холос. Ҳеч бир ибодатга сазовор зот йўқдир, магар ягона ва ўта қаҳрли Аллоҳгина бор.",457,23],["رَبُّ [h:6926[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَيْنَهُمَا [h:11598[ٱ]لْعَزِيزُ [h:11599[ٱ]لْغَفَّ[p[ـٰ]رُ","У осмонлару ернинг ва уларнинг орасидаги нарсаларнинг Робби, Азизу Ғаффордир», деб айт.",457,23],["قُلْ هُوَ نَبَؤٌاْ عَظ[p[ِي]مٌ","«Бу улуғ бир хабардир.",457,23],["أَ[f:428[نت]ُمْ عَنْهُ مُعْرِض[p[ُو]نَ","Сиз бўлсангиз, ундан юз ўгирмоқдасиз.",457,23],["مَا كَانَ لِىَ مِنْ عِلْ[i:11600[مِۭ ب]ِ[h:11601[ٱ]لْمَلَإِ [h:11602[ٱ]لْأَعْلَ[o[ىٰٓ] إِذْ يَخْتَصِم[p[ُو]نَ","Менинг олий тўплам ҳақида улар тортишаётганларида ҳеч билимим бўлмаган эди.",457,23],["إ[a:11603[ِن ي]ُوحَ[o[ىٰٓ] إِلَىَّ إِلّ[o[َآ] أَ[g[نّ]َم[o[َآ] أَنَا۟ نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","Менга фақат ўзимнинг очиқ-ойдин огоҳлантиргувчи эканлигимгина ваҳий этилур», деб айт.",457,23],["إِذْ قَالَ رَبُّكَ لِلْمَلَ[o[ـٰٓ]ئِكَةِ إِ[g[نّ]ِى خَ[n[ـٰ]لِ[i:7235[قُۢ ب]َشَ[a:7236[رًا م]ِّ[f:3917[ن ط][p[ِي]نٍ","Эсла! Ўшанда Роббинг фаришталарга: «Албатта, мен лойдан башар яратгувчидирман.",457,23],["فَإِذَا سَوَّيْتُهُ[n[ۥ] وَنَفَخْتُ فِيهِ م[u:7237[ِن ر]ُّوحِى فَقَعُو[s[اْ] لَهُ[n[ۥ] سَ[n[ـٰ]جِد[p[ِي]نَ","Бас, қачонки уни ростлаб, ичига руҳимдан пуфлаганимда, унга сажда қилиб йиқилинглар!» деган эди.",457,23],["فَسَجَدَ [h:7238[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ كُلُّهُمْ أَ[q:7239[جْ]مَع[p[ُو]نَ","Бас, фаришталар барчалари жамланиб, сажда қилдилар.",457,23],["إِلّ[o[َآ] إِ[q:180[بْ]لِيسَ [h:11604[ٱ]سْتَكْبَرَ وَكَانَ مِنَ [h:182[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Магар Иблисгина мутакаббирлик қилди ва кофирлардан бўлди.",457,23],["قَالَ يَ[o[ـٰٓ]إِ[q:7241[بْ]لِيسُ مَا مَنَعَكَ أَ[f:11605[ن ت]َسْجُدَ لِمَا خَلَ[q:11606[قْ]تُ بِيَدَىَّ‌ۖ أَسْتَكْبَرْتَ أَمْ كُ[f:735[نت]َ مِنَ [h:11607[ٱ]لْعَال[p[ِي]نَ","У зот: «Эй Иблис, Ўз қўлим билан яратган нарсага сажда қилишингдан сени нима ман қилди?! Мутакаббирлик қилдингми?! Ёки олий даражалилардан бўлдингми?!» деди.",457,23],["قَالَ أَنَا۟ خَيْ[a:4596[رٌ م]ِّنْهُ‌ۖ خَلَ[q:4597[قْ]تَنِى م[a:4598[ِن ن]َّا[a:4599[رٍ و]َخَلَ[q:4600[قْ]تَهُ[n[ۥ] مِ[f:3917[ن ط][p[ِي]نٍ","У: «Мен ундан яхшиман. Мени оловдан яратгансан. Уни лойдан яратгансан», деди.",457,23],["قَالَ فَ[h:4603[ٱ]خْرُ[q:4603[جْ] مِنْهَا فَإِ[g[نّ]َكَ رَج[p[ِي]مٌ","У зот: «Сен ундан чиқ! Бас, албатта, сен қувилгансан.",457,23],["وَإِ[g[نّ]َ عَلَيْكَ لَعْنَت[o[ِىٓ] إِلَىٰ يَوْمِ [h:5[ٱ][l[ل]دّ[p[ِي]نِ","Ва, албатта, сенга жазо кунигача Менинг лаънатим бўлгай», деди.",457,23],["قَالَ رَبِّ فَأَ[f:7245[نظ]ِرْن[o[ِىٓ] إِلَىٰ يَوْمِ يُ[q:4606[بْ]عَث[p[ُو]نَ","У: «Эй Роббим, менга улар қайта тирилтирилажак кунгача муҳлат бергин!» деди.",457,23],["قَالَ فَإِ[g[نّ]َكَ مِنَ [h:4607[ٱ]لْمُ[f:4608[نظ]َر[p[ِي]نَ","У зот: «Сен муҳлат берилганлардансан.",457,23],["إِلَىٰ يَوْمِ [h:7246[ٱ]لْوَ[q:7247[قْ]تِ [h:7248[ٱ]لْمَعْل[p[ُو]مِ","Маълум вақтли кунгача», деди.",457,23],["قَالَ فَبِعِزَّتِكَ لَأُغْوِيَ[g[نّ]َهُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","У: «Сенинг иззатинг ила қасамки, мен уларнинг барчасини иғво қиламан.",457,23],["إِلَّا عِبَادَكَ مِنْهُمُ [h:7249[ٱ]لْمُخْلَص[p[ِي]نَ","Магар улардан танланган бандаларинггина», деди.",457,23],["قَالَ فَ[h:11608[ٱ]لْحَقُّ وَ[h:11609[ٱ]لْحَقَّ أَق[p[ُو]لُ","У зот: «Ҳақ шулки, Мен фақат ҳақни айтурман.",458,23],["لَأَمْلَأَ[g[نّ]َ جَهَ[g[نّ]َمَ مِ[f:3891[نك]َ وَمِ[g[مّ]َ[f:11610[ن ت]َبِعَكَ مِنْهُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Албатта, Мен жаҳаннамни сен ва улардан сенга эргашганлар билан жамлаб тўлдирурман», деди.",458,23],["قُلْ م[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ مِنْ أَ[q:6133[جْ][a:11611[رٍ و]َم[o[َآ] أَنَا۟ مِنَ [h:11612[ٱ]لْمُتَكَلِّف[p[ِي]نَ","Сен: «Мен унинг учун сиздан ҳеч ажр-ҳақ сўрамасман. Мен сохтакорлардан ҳам эмасман.",458,23],["إِنْ هُوَ إِلَّا ذِكْ[u:6839[رٌ ل]ِّلْعَ[n[ـٰ]لَم[p[ِي]نَ","У фақат оламлар учун эслатма, холос.",458,23],["وَلَتَعْلَمُ[g[نّ]َ نَبَأَهُ[n[ۥ] بَعْدَ ح[p[ِي]نِۭ","Албатта, унинг хабарини бир муддатдан сўнг билурсиз», деб айт.",458,23]]},{"n":39,"ar":"الزُّمَرِ","en":"Az-Zumar","uz":"Зумар","type":"Макка","ayahs":[["تَ[f:10623[نز]ِيلُ [h:10624[ٱ]لْكِتَ[n[ـٰ]بِ مِنَ [h:321[ٱ]للَّهِ [h:11613[ٱ]لْعَزِيزِ [h:2229[ٱ]لْحَك[p[ِي]مِ","Бу китобнинг нозил қилиниши азизу ҳаким бўлган Аллоҳ томонидандир.",458,23],["إِ[g[نّ][o[َآ] أَ[f:515[نز]َلْن[o[َآ] إِلَيْكَ [h:3102[ٱ]لْكِتَ[n[ـٰ]بَ بِ[h:370[ٱ]لْحَقِّ فَ[h:11614[ٱ]عْبُدِ [h:11615[ٱ]للَّهَ مُخْلِ[u:11616[صًا ل]َّهُ [h:4649[ٱ][l[ل]دّ[p[ِي]نَ","Албатта, Биз сенга китобни ҳақ ила нозил қилдик. Бас, сен Аллоҳга Унга динни холис қилган ҳолингда ибодат эт.",458,23],["أَلَا لِلَّهِ [h:11617[ٱ][l[ل]دِّينُ [h:11618[ٱ]لْخَالِصُ‌ۚ وَ[h:37[ٱ]لَّذِينَ [h:5828[ٱ]تَّخَذُو[s[اْ] مِ[f:3136[ن د]ُونِه[o[ِۦٓ] أَوْلِي[o[َا]ٓءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُون[o[َآ] إِلَى [h:1637[ٱ]للَّهِ زُلْفَ[o[ىٰٓ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ‌ۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَهْدِى مَنْ هُوَ كَ[n[ـٰ]ذِ[f:11619[بٌ ك]َفّ[p[َا]رٌ","Огоҳ бўлингким, холис дин Аллоҳникидир. Ундан ўзга авлиё-дўстлар тутганлар: «Биз уларга фақат бизларни Аллоҳга жуда ҳам яқин қилишлари учунгина ибодат қилурмиз»,. Албатта, У зот улар орасида ихтилоф этаётган нарсалар бўйича ҳукм қилур. Албатта, Аллоҳ ёлғончи ва кофир кимсаларни ҳидоят қилмас.",458,23],["لَّوْ أَرَادَ [h:139[ٱ]للَّهُ أ[a:8331[َن ي]َتَّخِذَ وَلَ[u:11620[دًا ل]َّ[h:11621[ٱ]صْطَفَىٰ مِ[g[مّ]َا يَخْلُقُ مَا يَش[o[َا]ٓءُ‌ۚ سُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ]‌ۖ هُوَ [h:8078[ٱ]للَّهُ [h:11597[ٱ]لْو[n[َٲ]حِدُ [h:6662[ٱ]لْقَهّ[p[َا]رُ","Агар Аллоҳ бола тутишни истаса, албатта, Ўзи яратган нарсалардан хоҳлаганини танлаб олар эди. У зот покдир. У якка ва ўта қаҳрли Аллоҳдир.",458,23],["خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ بِ[h:370[ٱ]لْحَقِّ‌ۖ يُكَوِّرُ [h:11622[ٱ]لَّيْلَ عَلَى [h:11623[ٱ][l[ل][g[نّ]َهَارِ وَيُكَوِّرُ [h:11624[ٱ][l[ل][g[نّ]َهَارَ عَلَى [h:11625[ٱ]لَّيْلِ‌ۖ وَسَخَّرَ [h:6864[ٱ][l[ل]شَّمْسَ وَ[h:4265[ٱ]لْقَمَرَ‌ۖ كُ[a:6865[لٌّ ي]َ[q:6866[جْ]رِى لِأَجَ[a:6867[لٍ م]ُّسَ[g[مّ]ًى‌ۗ أَلَا هُوَ [h:1734[ٱ]لْعَزِيزُ [h:11599[ٱ]لْغَفَّ[p[ـٰ]رُ","У осмонлару ерни ҳақ ила яратган, кечани кундуз устига ўрайдиган, кундузни кеча устига ўрайдиган, қуёш ва ойни бўйсундирадиган зотдир. Ҳар бири белгиланган муддатча юрмоқда. Огоҳ бўлингким, У азизу ўта мағфиратли зотдир.",458,23],["خَلَقَك[w:2530[ُم م]ّ[a:2531[ِن ن]َّفْ[a:2532[سٍ و][n[َٲ]حِدَ[f:11626[ةٍ ث]ُ[g[مّ]َ جَعَلَ مِنْهَا زَوْجَهَا وَأَ[f:91[نز]َلَ لَك[w:1578[ُم م]ِّنَ [h:11627[ٱ]لْأَنْعَ[n[ـٰ]مِ ثَمَ[n[ـٰ]نِيَةَ أَزْو[n[َٲ][a:11628[جٍ‌ۚ ي]َخْلُقُكُمْ فِى بُطُونِ أُ[g[مّ]َهَ[n[ـٰ]تِكُمْ خَلْ[a:11629[قًا م]ّ[i:146[ِنۢ ب]َعْدِ خَلْ[f:11630[قٍ ف]ِى ظُلُمَ[n[ـٰ][f:11631[تٍ ث]َلَ[n[ـٰ][f:11632[ثٍ‌ۚ ذ][n[َٲ]لِكُمُ [h:4260[ٱ]للَّهُ رَبُّكُمْ لَهُ [h:1397[ٱ]لْمُلْكُ‌ۖ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۖ فَأَ[g[نّ]َىٰ تُصْرَف[p[ُو]نَ","У сизларни бир жондан яратди. Сўнгра ундан жуфтини қилди ва сизларга чорва ҳайвонларидан саккиз жуфтни туширди. У сизни оналарингиз қорнида уч зулмат ичида, бир яратишдан кейин яна бошқа яратишга ўтказиб, аста яратадир. Ана ўша Аллоҳ Роббингиздир. Барча мулк Уникидир. Ундан ўзга ҳеч бир ибодатга сазовор зот йўқ. Бас, қаён бурилиб кетмоқдасиз?!",459,23],["إِ[f:7056[ن ت]َكْفُرُو[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَنِىٌّ عَ[f:255[نك]ُمْ‌ۖ وَلَا يَرْضَىٰ لِعِبَادِهِ [h:11633[ٱ]لْكُفْرَ‌ۖ وَإِ[f:11634[ن ت]َشْكُرُو[s[اْ] يَرْضَهُ لَكُمْ‌ۗ وَلَا تَزِرُ وَازِرَ[a:4572[ةٌ و]ِزْرَ أُخْرَىٰ‌ۗ ثُ[g[مّ]َ إِلَىٰ رَبِّك[w:4573[ُم م]َّرْجِعُكُمْ فَيُنَبِّئُك[c:3605[ُم ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَلُونَ‌ۚ إِ[g[نّ]َهُ[n[ۥ] عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","Агар куфр келтирсангиз, албатта, Аллоҳ сиздан беҳожатдир. У ўз бандаларининг кофир бўлишига рози бўлмас. Агар Унга шукр келтирсангиз, сиздан рози бўлур. Ҳеч бир оғирлик кўтаргувчи жон ўзга жоннинг оғирлигини кўтармас. Сўнгра фақатгина Роббингизга қайтишингиз бор. Бас, У нима амал қилиб юрганингизнинг хабарини берур. Албатта, У диллардаги нарсаларни ҳам ўта билгувчи зотдир.",459,23],["۞ وَإِذَا مَسَّ [h:5968[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ ضُ[f:11635[رٌّ د]َعَا رَبَّهُ[n[ۥ] مُنِيبًا إِلَيْهِ ثُ[g[مّ]َ إِذَا خَوَّلَهُ[n[ۥ] نِعْمَ[a:11636[ةً م]ِّنْهُ نَسِىَ مَا كَانَ يَ[q:1242[دْ]ع[o[ُوٓ][s[اْ] إِلَيْهِ مِ[f:128[ن ق]َ[q:129[بْ]لُ وَجَعَلَ لِلَّهِ أَ[f:96[ند]َا[u:11637[دًا ل]ِّيُضِلَّ عَ[f:4361[ن س]َبِيلِه[n[ِۦ]‌ۚ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلاً‌ۖ إِ[g[نّ]َكَ مِنْ أَصْحَ[n[ـٰ]بِ [h:3507[ٱ][l[ل][g[نّ][p[َا]رِ","Қачонки инсонни зарар тутса, Роббига тавба қилган ҳолида дуо қиладир. Сўнгра унга Ўз фазлидан неъмат берса, олдин дуо қилиб турган нарсасини унутадир ва Аллоҳга Унинг йўлидан адаштирмоқ учун тенгдошлар қилади. Сен: «Куфринг билан бир оз ҳузурланиб тур. Албатта, сен жаҳаннам эгаларидансан», деб айт.",459,23],["أَ[g[مّ]َنْ هُوَ قَ[n[ـٰ]نِتٌ ءَان[o[َا]ٓءَ [h:2180[ٱ]لَّيْلِ سَاجِ[a:11638[دًا و]َق[o[َا]ٓئِ[a:11639[مًا ي]َحْذَرُ [h:11640[ٱ]لْأَخِرَةَ وَيَرْجُو[s[اْ] رَحْمَةَ رَبِّه[n[ِۦ]‌ۗ قُلْ هَلْ يَسْتَوِى [h:11641[ٱ]لَّذِينَ يَعْلَمُونَ وَ[h:37[ٱ]لَّذِينَ لَا يَعْلَمُونَ‌ۗ إِ[g[نّ]َمَا يَتَذَكَّرُ أُ[s[وْ]لُو[s[اْ] [h:1595[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","Йўқса, у кечалари ибодат қилиб, сажда этган, бедор ҳолида охиратдан қўрқиб, Робби раҳматидан умидвор бўлган одамга тенгми?! Сен: «Биладиганлар билан билмайдиганлар тенг бўлармиди?!» деб айт. Албатта, ақл эгаларигина эсларлар.",459,23],["قُلْ يَ[n[ـٰ]عِبَادِ [h:11642[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:1643[ٱ]تَّقُو[s[اْ] رَبَّكُمْ‌ۚ لِلَّذِينَ أَحْسَنُو[s[اْ] فِى هَ[n[ـٰ]ذِهِ [h:5052[ٱ][l[ل]دُّنْيَا حَسَنَ[a:11643[ةٌ‌ۗ و]َأَرْضُ [h:11644[ٱ]للَّهِ و[n[َٲ]سِعَةٌ‌ۗ إِ[g[نّ]َمَا يُوَفَّى [h:11645[ٱ][l[ل]صَّ[n[ـٰ]بِرُونَ أَ[q:7573[جْ]رَه[c:11646[ُم ب]ِغَيْرِ حِس[p[َا][q[ب]ٍ","Сен менинг тарафимдан: «Эй иймон келтирган бандаларим, Роббингизга тақво қилинг. Бу дунёда гўзал амал қилганларга гўзаллик бордир. Аллоҳнинг ери кенгдир. Албатта, сабр қилгувчиларга ажрлари ҳисобсиз, тўлиқ берилур», деб айт.",459,23],["قُلْ إِ[g[نّ][o[ِىٓ] أُمِرْتُ أَنْ أَعْبُدَ [h:7014[ٱ]للَّهَ مُخْلِ[u:11616[صًا ل]َّهُ [h:4649[ٱ][l[ل]دّ[p[ِي]نَ","Сен: «Албатта, мен динни Ўзи учун холис қилган ҳолимда Аллоҳга ибодат этишимга буюрилганман.",460,23],["وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ [h:11647[ٱ]لْمُسْلِم[p[ِي]نَ","Ва мен мусулмонларнинг аввалгиси бўлишимга амр этилганман», деб айт.",460,23],["قُلْ إِ[g[نّ][o[ِىٓ] أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظ[p[ِي]مٍ","Сен: «Албатта, мен агар Роббимга исён этсам, улуғ куннинг азобидан қўрқаман», деб айт.",460,23],["قُلِ [h:11648[ٱ]للَّهَ أَعْبُدُ مُخْلِ[u:11616[صًا ل]َّهُ[n[ۥ] دِينِى","Сен: «Динимни Ўзига холис қилган ҳолимда Аллоҳгагина ибодат қилурман.",460,23],["فَ[h:9999[ٱ]عْبُدُو[s[اْ] مَا شِئْت[w:11649[ُم م]ِّ[f:3136[ن د]ُونِه[n[ِۦ]‌ۗ قُلْ إِ[g[نّ]َ [h:11650[ٱ]لْخَ[n[ـٰ]سِرِينَ [h:11651[ٱ]لَّذِينَ خَسِر[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ وَأَهْلِيهِمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۗ أَلَا ذ[n[َٲ]لِكَ هُوَ [h:8940[ٱ]لْخُسْرَانُ [h:8941[ٱ]لْمُب[p[ِي]نُ","Бас, сизлар ундан ўзга нимани хоҳласангиз, ўшанга ибодат қилаверинглар», деб айт. Сен: «Албатта, зиёнкорлар қиёмат куни ўзларига ва аҳлларига зиён қилгувчилардир. Огоҳ бўлингким, ана ўша очиқ-ойдин зиёнкорликдир», деб айт.",460,23],["لَه[w:1812[ُم م]ِّ[f:3683[ن ف]َوْقِهِمْ ظُلَ[a:11652[لٌ م]ِّنَ [h:869[ٱ][l[ل][g[نّ]َارِ وَمِ[f:11653[ن ت]َحْتِهِمْ ظُلَ[f:11654[لٌ‌ۚ ذ][n[َٲ]لِكَ يُخَوِّفُ [h:11655[ٱ]للَّهُ بِه[n[ِۦ] عِبَادَهُ[n[ۥ]‌ۚ يَ[n[ـٰ]عِبَادِ فَ[h:210[ٱ]تَّق[p[ُو]نِ","Улар учун тепаларидан ҳам оловдан «соябонлар» бор, остларидан ҳам оловдан «соябонлар» бор. Бу билан Аллоҳ Ўз бандаларини қўрқитур: «Эй бандаларим, менга тақво қилинглар!».",460,23],["وَ[h:9999[ٱ]لَّذِينَ [h:11656[ٱ][q:11657[جْ]تَنَبُو[s[اْ] [h:11658[ٱ][l[ل]طَّ[n[ـٰ]غُوتَ أ[a:11659[َن ي]َعْبُدُوهَا وَأَنَاب[o[ُوٓ][s[اْ] إِلَى [h:1637[ٱ]للَّهِ لَهُمُ [h:6112[ٱ]لْبُشْرَىٰ‌ۚ فَبَشِّرْ عِب[p[َا][q[د]ِ","Тоғутдан, унга ибодат қилишдан четда бўлганларга ва Аллоҳга қайтганларга хушхабар бор. Бас, бир бандаларимга хушхабар бер.",460,23],["ٱلَّذِينَ يَسْتَمِعُونَ [h:11660[ٱ]لْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُ[o[ۥٓ‌ۚ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ هَدَ[n[ٮٰ]هُمُ [h:11661[ٱ]للَّهُ‌ۖ وَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمْ أُ[s[وْ]لُو[s[اْ] [h:1595[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","Улар гапни эшитиб, энг гўзалига эргашадиганлардир. Ана ўшалар Аллоҳ ҳидоят қилганлардир. Ана ўшалар, ҳа, ўшалар ақл эгаларидир.",460,23],["أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ [h:11662[ٱ]لْعَذَابِ أَفَأَ[f:6069[نت]َ تُ[f:11663[نق]ِذُ مَ[f:2074[ن ف]ِى [h:4674[ٱ][l[ل][g[نّ][p[َا]رِ","Ёки ҳақида азоб сўзи ҳақ бўлган кимсани— дўзахдаги кимсани сен қутқара олурмисан?!",460,23],["لَ[n[ـٰ]كِنِ [h:2522[ٱ]لَّذِينَ [h:2523[ٱ]تَّقَوْ[s[اْ] رَبَّهُمْ لَهُمْ غُرَ[a:11664[فٌ م]ِّ[f:11665[ن ف]َوْقِهَا غُرَ[a:11666[فٌ م]َّ[q:11667[بْ]نِيَّ[f:11668[ةٌ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۖ وَعْدَ [h:3149[ٱ]للَّهِ‌ۖ لَا يُخْلِفُ [h:10424[ٱ]للَّهُ [h:11669[ٱ]لْمِيع[p[َا][q[د]َ","Лекин Роббиларига тақво қилганлар учун болохоналар устидан болохоналар бино қилингандир. Остларидан анҳорлар оқиб турур. Аллоҳнинг ваъдаси шу! Аллоҳ ваъдага хилоф қилмас.",460,23],["أَلَمْ تَرَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ أَ[f:471[نز]َلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[f:11670[ءً ف]َسَلَكَهُ[n[ۥ] يَنَ[n[ـٰ]بِيعَ فِى [h:44[ٱ]لْأَرْضِ ثُ[g[مّ]َ يُخْرِجُ بِه[n[ِۦ] زَرْ[a:11671[عًا م]ُّخْتَلِفًا أَلْو[n[َٲ]نُهُ[n[ۥ] ثُ[g[مّ]َ يَهِيجُ فَتَرَ[n[ٮٰ]هُ مُصْفَر[f:11672[ًّا ث]ُ[g[مّ]َ يَ[q:9467[جْ]عَلُهُ[n[ۥ] حُطَ[n[ـٰ]مًا‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَذِكْرَىٰ لِأُ[s[وْ]لِى [h:11555[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","Аллоҳ осмондан сув тушириб, уни ердаги манбаълардан юритиб қўйганини кўрмадингми?! Сўнгра у ила турли рангдаги экинларни чиқарур. Кейин у қурийдир. Бас, уни сарғайган ҳолида кўрарсан. Сўнгра уни қуруқ чўпга айлантирур. Албаттта, бунда ақл эгалари учун эслатма бордир.",460,23],["أَفَمَ[f:11673[ن ش]َرَحَ [h:11674[ٱ]للَّهُ صَ[q:4395[دْ]رَهُ[n[ۥ] لِلْإِسْلَ[n[ـٰ]مِ فَهُوَ عَلَىٰ نُو[a:11675[رٍ م]ّ[u:192[ِن ر]َّبِّه[n[ِۦ]‌ۚ فَوَيْ[u:11676[لٌ ل]ِّلْقَ[n[ـٰ]سِيَةِ قُلُوبُه[w:11677[ُم م]ِّ[f:11678[ن ذ]ِكْرِ [h:3774[ٱ]للَّهِ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Аллоҳ кўксини Исломга кенг қилиб очиб қўйган шахс ўз Роббидан бўлган нурда эмасми?! Аллоҳни зикр қилишдан қалблари қотиб қолганларга вой бўлсин! Ана ўшалар очиқ-ойдин залолатдадирлар.",461,23],["ٱللَّهُ نَزَّلَ أَحْسَنَ [h:11679[ٱ]لْحَدِيثِ كِتَ[n[ـٰ][a:11680[بًا م]ُّتَشَ[n[ـٰ]بِ[a:11681[هًا م]َّثَانِىَ تَ[q:11682[قْ]شَعِرُّ مِنْهُ جُلُودُ [h:11683[ٱ]لَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُ[g[مّ]َ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ [h:3774[ٱ]للَّهِ‌ۚ ذ[n[َٲ]لِكَ هُدَى [h:629[ٱ]للَّهِ يَهْدِى بِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَم[a:3002[َن ي]ُضْلِلِ [h:3003[ٱ]للَّهُ فَمَا لَهُ[n[ۥ] مِنْ ه[p[َا][q[د]ٍ","Аллоҳ энг гўзал сўзни ўхшаш ва такрорланган китоб этиб туширар. Ундан Роббиларидан қўрқадиганларнинг терилари титрар. Сўнгра уларнинг терилари ва қалблари Аллоҳнинг зикрига юмшар. Ана шу Аллоҳнинг ҳидоятидир. У ила Аллоҳ хоҳлаган кимсани ҳидоят қилур. Кимни Аллоҳ залолатига кетказса, бас, унинг учун ҳидоят қилгувчи йўқ.",461,23],["أَفَم[a:11684[َن ي]َتَّقِى بِوَ[q:11685[جْ]هِه[n[ِۦ] س[o[ُو]ٓءَ [h:239[ٱ]لْعَذَابِ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۚ وَقِيلَ لِلظَّ[n[ـٰ]لِمِينَ ذُوقُو[s[اْ] مَا كُ[f:100[نت]ُمْ تَكْسِب[p[ُو]نَ","Ахир қиёмат куни золимларга, касб қилиб юрган нарсангизни тотиб кўринг, дейилганида ёмон азобдан юзи ила сақланадиган одам?!",461,23],["كَذَّبَ [h:4507[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ فَأَتَ[n[ـٰ]هُمُ [h:11686[ٱ]لْعَذَابُ مِنْ حَيْثُ لَا يَشْعُر[p[ُو]نَ","Улардан олдингилар ҳам ёлғончи қилганлар, бас, уларга ўзлари сезмаган томондан азоб келган.",461,23],["فَأَذَاقَهُمُ [h:11687[ٱ]للَّهُ [h:11688[ٱ]لْخِزْىَ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۖ وَلَعَذَابُ [h:7000[ٱ]لْأَخِرَةِ أَكْبَرُ‌ۚ لَوْ كَانُو[s[اْ] يَعْلَم[p[ُو]نَ","Аллоҳ уларга бу дунёда хорликни тотдирди, албатта, охират азоби, агар билсалар, янада улкан бўлур.",461,23],["وَلَقَ[q:341[دْ] ضَرَ[q:9642[بْ]نَا لِل[g[نّ]َاسِ فِى هَ[n[ـٰ]ذَا [h:7765[ٱ]لْقُرْءَانِ مِ[f:843[ن ك]ُلِّ مَثَ[u:11689[لٍ ل]َّعَلَّهُمْ يَتَذَكَّر[p[ُو]نَ","Батаҳқиқ, Биз ушбу Қуръонда одамларга турли мисоллар келтирдик. Шоядки эсласалар.",461,23],["قُرْءَانًا عَرَبِيًّا غَيْرَ ذِى عِوَ[u:11690[جٍ ل]َّعَلَّهُمْ يَتَّق[p[ُو]نَ","Арабча Қуръонни эгриликсиз қилиб, шоядки тақво қилсалар.",461,23],["ضَرَبَ [h:7103[ٱ]للَّهُ مَثَل[u:11691[اً ر]َّجُل[f:11692[اً ف]ِيهِ شُرَك[o[َا]ٓءُ مُتَشَ[n[ـٰ]كِسُونَ وَرَجُل[f:11693[اً س]َلَ[u:11694[مًا ل]ِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلاً‌ۚ [h:11695[ٱ]لْحَمْدُ لِلَّهِ‌ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَم[p[ُو]نَ","Аллоҳ бир мисол келтирур. Бир одамга талашувчи шериклар эгадир. Саломат ҳолидаги бошқа бирига бир киши эгадир. Икковларининг мисоли баробарми?! Аллоҳга ҳамд бўлсин. Йўқ, кўплари билмаслар.",461,23],["إِ[g[نّ]َكَ مَيِّ[a:11696[تٌ و]َإِ[g[نّ]َه[w:11697[ُم م]َّيِّت[p[ُو]نَ","Албатта, сен ҳам ўлгувчисан, улар ҳам ўлгувчидирлар.",461,23],["ثُ[g[مّ]َ إِ[g[نّ]َكُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ عِ[f:264[ند]َ رَبِّكُمْ تَخْتَصِم[p[ُو]نَ","Сўнгра, албатта, сизлар қиёмат куни Роббингиз ҳузурида тортишурсизлар.",461,23],["۞ فَمَنْ أَظْلَمُ مِ[g[مّ]َ[f:11698[ن ك]َذَبَ عَلَى [h:412[ٱ]للَّهِ وَكَذَّبَ بِ[h:11699[ٱ][l[ل]صِّ[q:11699[دْ]قِ إِذْ ج[o[َا]ٓءَهُ[o[ۥٓ‌ۚ] أَلَيْسَ فِى جَهَ[g[نّ]َمَ مَثْ[u:10414[وًى ل]ِّلْكَ[n[ـٰ]فِر[p[ِي]نَ","Аллоҳга нисбатан ёлғон гапирган ва ўзига содиқ келганида уни ёлғонга чиқаргандан ҳам золимроқ кимса борми?! Кофирларнинг жойи жаҳаннамда эмасми?!",462,24],["وَ[h:9999[ٱ]لَّذِى ج[o[َا]ٓءَ بِ[h:11699[ٱ][l[ل]صِّ[q:11699[دْ]قِ وَصَدَّقَ بِه[o[ِۦٓ‌ۙ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:922[ٱ]لْمُتَّق[p[ُو]نَ","Содиқ ни келтирган ва уни тасдиқ қилган эса, ана ўшалар тақводорлардир.",462,24],["لَه[w:3531[ُم م]َّا يَش[o[َا]ٓءُونَ عِ[f:264[ند]َ رَبِّهِمْ‌ۚ ذ[n[َٲ]لِكَ جَز[o[َا]ٓءُ [h:3749[ٱ]لْمُحْسِن[p[ِي]نَ","Улар учун Роббилари ҳузурида хоҳлаган нарсалари бордир. Ана ўша гўзал амал қилгувчиларнинг мукофотидир.",462,24],["لِيُكَفِّرَ [h:11700[ٱ]للَّهُ عَنْهُمْ أَسْوَأَ [h:11701[ٱ]لَّذِى عَمِلُو[s[اْ] وَيَ[q:11702[جْ]زِيَهُمْ أَ[q:7573[جْ]رَه[c:7574[ُم ب]ِأَحْسَنِ [h:11703[ٱ]لَّذِى كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Зеро, Аллоҳ уларнинг қилган энг ёмон амалини ўчириб, қилиб юрган энг гўзал амаллари ажри ила мукофотлар.",462,24],["أَلَيْسَ [h:4087[ٱ]للَّهُ بِكَافٍ عَ[q:8257[بْ]دَهُ[n[ۥ]‌ۖ وَيُخَوِّفُونَكَ بِ[h:2413[ٱ]لَّذِينَ مِ[f:3136[ن د]ُونِه[n[ِۦ]‌ۚ وَم[a:3002[َن ي]ُضْلِلِ [h:3003[ٱ]للَّهُ فَمَا لَهُ[n[ۥ] مِنْ ه[p[َا][q[د]ٍ","Аллоҳ Ўз бандасига етарли эмасми?! Улар сени ундан бошқалар билан қўрқитадилар. Кимни Аллоҳ залолатга кеткизса, бас, унинг учун ҳеч бир ҳидоят қилгувчи йўқ.",462,24],["وَم[a:7905[َن ي]َهْدِ [h:5147[ٱ]للَّهُ فَمَا لَهُ[n[ۥ] م[a:11704[ِن م]ُّضِلٍّ‌ۗ أَلَيْسَ [h:4087[ٱ]للَّهُ بِعَزِي[f:11705[زٍ ذ]ِى [h:11706[ٱ][f:1731[نت]ِق[p[َا]مٍ","Кимни Аллоҳ ҳидоятга солса, бас, унинг учун ҳеч бир залолатга кетказгувчи йўқ. Аллоҳ азизу интиқом эгаси эмасми?!",462,24],["وَلَئِ[f:5683[ن س]َأَلْتَه[w:10403[ُم م]َّنْ خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ لَيَقُولُ[g[نّ]َ [h:10404[ٱ]للَّهُ‌ۚ قُلْ أَفَرَءَيْت[w:9776[ُم م]َّا تَ[q:4040[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ إِنْ أَرَادَنِىَ [h:11707[ٱ]للَّهُ بِضُرٍّ هَلْ هُ[g[نّ]َ كَ[n[ـٰ]شِفَ[n[ـٰ]تُ ضُرِّه[o[ِۦٓ] أَوْ أَرَادَنِى بِرَحْمَةٍ هَلْ هُ[g[نّ]َ مُمْسِكَ[n[ـٰ]تُ رَحْمَتِه[n[ِۦ]‌ۚ قُلْ حَسْبِىَ [h:5929[ٱ]للَّهُ‌ۖ عَلَيْهِ يَتَوَكَّلُ [h:11708[ٱ]لْمُتَوَكِّل[p[ُو]نَ","Агар улардан: «Осмонлару ерни ким яратди?» деб сўрасанг, албатта: «Аллоҳ!» дерлар. Сен: «Менга хабар беринглар-чи! Сиз илтижо қилаётган Аллоҳдан бошқа нарсалар, агар Аллоҳ менга зарарни ирода қилса, ўшалар унинг зарарини аритгувчи бўла олурларми?! Ёки менга марҳаматни ирода қилса, ўшалар Унинг марҳаматини тутиб қолгувчи бўла олурми?!» деб айт. Сен: «Менга Аллоҳ етарли, таваккал қилгувчилар унгагина таваккал қилурлар», деб айт.",462,24],["قُلْ يَ[n[ـٰ]قَوْمِ [h:4436[ٱ]عْمَلُو[s[اْ] عَلَىٰ مَكَانَتِكُمْ إِ[g[نّ]ِى عَ[n[ـٰ]مِ[f:4437[لٌ‌ۖ ف]َسَوْفَ تَعْلَم[p[ُو]نَ","Сен: «Эй қавмим, ўз ҳолингизча амал қилаверинг. Албатта, мен ҳам амал қилгувчиман. Бас, тезда билурсиз.",462,24],["م[a:6325[َن ي]َأْتِيهِ عَذَا[a:6326[بٌ ي]ُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَا[a:3534[بٌ م]ُّق[p[ِي]مٌ","Кимга уни расво қиладиган азоб келажагини ва кимга давомли азоб тушажагини», деб айт.",462,24],["إِ[g[نّ][o[َآ] أَ[f:515[نز]َلْنَا عَلَيْكَ [h:1723[ٱ]لْكِتَ[n[ـٰ]بَ لِل[g[نّ]َاسِ بِ[h:370[ٱ]لْحَقِّ‌ۖ فَمَنِ [h:6230[ٱ]هْتَدَىٰ فَلِنَفْسِه[n[ِۦ]‌ۖ وَمَ[f:6231[ن ض]َلَّ فَإِ[g[نّ]َمَا يَضِلُّ عَلَيْهَا‌ۖ وَم[o[َآ] أَ[f:169[نت]َ عَلَيْه[c:4316[ِم ب]ِوَك[p[ِي]لٍ","Албатта, Биз одамлар учун сенга китобни ҳақ ила туширдик. Бас, ким ҳидоятга юрса, ўзига фойда. Ким залолатга кетса, ўзига зарар. Сен уларга вакил-қўриқчи эмассан.",463,24],["ٱللَّهُ يَتَوَفَّى [h:11709[ٱ]لْأَ[f:11710[نف]ُسَ حِينَ مَوْتِهَا وَ[h:11711[ٱ]لَّتِى لَمْ تَمُتْ فِى مَنَامِهَا‌ۖ فَيُمْسِكُ [h:11712[ٱ]لَّتِى قَضَىٰ عَلَيْهَا [h:11713[ٱ]لْمَوْتَ وَيُرْسِلُ [h:11714[ٱ]لْأُخْرَ[o[ىٰٓ] إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَ[g[مّ]ًى‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:6018[مٍ ي]َتَفَكَّر[p[ُو]نَ","Аллоҳ жонларни ўлими вақтида, ўлмаганларини эса, уйқуси вақтида олур. Бас, ўлишига ҳукм қилганларини ушлаб қолур, қолганларини маълум муддатгача қўйиб юборур. Албатта, бунда тафаккур қиладиган қавмлар учун оят-ибратлар бордир.",463,24],["أَمِ [h:8702[ٱ]تَّخَذُو[s[اْ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ شُفَع[o[َا]ٓءَ‌ۚ قُلْ أَوَلَوْ كَانُو[s[اْ] لَا يَمْلِكُونَ شَيْـ[a:232[ـًٔا و]َلَا يَعْقِل[p[ُو]نَ","Ёки Аллоҳдан ўзга шафоатчилар тутганларми?! Сен: «Ахир улар бирор нарсага эга бўлмасалар ва бирор нарсани англамасалар ҳам-а?!» деб айт.",463,24],["قُل لِّلَّهِ [h:11715[ٱ][l[ل]شَّفَ[n[ـٰ]عَةُ جَمِي[u:11716[عًا‌ۖ ل]َّهُ[n[ۥ] مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ ثُ[g[مّ]َ إِلَيْهِ تُرْجَع[p[ُو]نَ","Сен: «Барча шафоат ёлғиз Аллоҳникидир. Осмонлару ернинг мулки-эгалиги ҳам ёлғиз Уникидир. Сўнгра Унгагина қайтарилурсизлар», деб айт.",463,24],["وَإِذَا ذُكِرَ [h:5234[ٱ]للَّهُ وَحْدَهُ [h:11717[ٱ]شْمَأَزَّتْ قُلُوبُ [h:11718[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ‌ۖ وَإِذَا ذُكِرَ [h:11719[ٱ]لَّذِينَ مِ[f:3136[ن د]ُونِه[o[ِۦٓ] إِذَا هُمْ يَسْتَ[q:2415[بْ]شِر[p[ُو]نَ","Қачонки Аллоҳнинг ёлғиз Ўзи зикр қилинса, охиратга иймон келтирмайдиганларнинг қалблари сиқилиб кетар. Қачонки ундан ўзгалар зикр қилинсалар, бирдан шодланиб кетарлар.",463,24],["قُلِ [h:1820[ٱ][l[ل]لَّهُ[g[مّ]َ فَاطِرَ [h:6833[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ عَ[n[ـٰ]لِمَ [h:11720[ٱ]لْغَيْبِ وَ[h:4187[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ أَ[f:169[نت]َ تَحْكُمُ بَيْنَ عِبَادِكَ فِى مَا كَانُو[s[اْ] فِيهِ يَخْتَلِف[p[ُو]نَ","Сен: «Эй Аллоҳим! Осмонлару ерни яратган зот! Ғойиб ва ошкорни билгувчи зот! Сенинг Ўзинг бандаларнинг орасида улар ихтилоф қилиб юрган нарсаларда ҳукм қилурсан», деб айт.",463,24],["وَلَوْ أَ[g[نّ]َ لِلَّذِينَ ظَلَمُو[s[اْ] مَا فِى [h:44[ٱ]لْأَرْضِ جَمِي[a:3532[عًا و]َمِثْلَهُ[n[ۥ] مَعَهُ[n[ۥ] لَ[h:6951[ٱ]فْتَدَوْ[s[اْ] بِه[n[ِۦ] مِ[f:7447[ن س][o[ُو]ٓءِ [h:11721[ٱ]لْعَذَابِ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۚ وَبَدَا لَه[w:6026[ُم م]ِّنَ [h:321[ٱ]للَّهِ مَا لَمْ يَكُونُو[s[اْ] يَحْتَسِب[p[ُو]نَ","Агар зулм этганларга ер юзидаги барча нарса ва у билан яна шу қадар нарса берилса ҳам, қиёмат куни ёмон азобга тўлов қилиб юборишлари аниқ. Ва уларга Аллоҳ томонидан ўзлари хаёлларига ҳам келтирмаган нарсалар зоҳир бўлур.",463,24],["وَبَدَا لَهُمْ سَيِّـَٔـاتُ مَا كَسَبُو[s[اْ] وَحَاقَ بِه[w:6252[ِم م]َّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Ва уларга ўзлари касб қилган нарсаларнинг ёмонлиги зоҳир бўлур ва уларни ўзлари масхара қилиб юрган нарса ўраб олур.",464,24],["فَإِذَا مَسَّ [h:5968[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ ضُ[f:11722[رٌّ د]َعَانَا ثُ[g[مّ]َ إِذَا خَوَّلْنَ[n[ـٰ]هُ نِعْمَ[a:11723[ةً م]ِّ[g[نّ]َا قَالَ إِ[g[نّ]َم[o[َآ] أُوتِيتُهُ[n[ۥ] عَلَىٰ عِلْ[i:11724[مِۭ‌ۚ ب]َلْ هِىَ فِتْنَ[a:11725[ةٌ و]َلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَعْلَم[p[ُو]نَ","Бас, қачонки инсонни зарар тутса, у бизга дуо қилур. Сўнгра унга Биз ўзимиздан неъмат берсак: «Албатта, бу менга илмим туфайли берилди», дер. Йўқ! У синовдир. Лекин кўплари билмаслар.",464,24],["قَ[q:298[دْ] قَالَهَا [h:11726[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ فَم[o[َآ] أَغْنَىٰ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Батаҳқиқ, буни улардан аввалгилар ҳам айтган эдилар. Бас, уларнинг қилган касблари ўзларига асқотмади.",464,24],["فَأَصَابَهُمْ سَيِّـَٔـاتُ مَا كَسَبُو[s[اْ‌ۚ] وَ[h:37[ٱ]لَّذِينَ ظَلَمُو[s[اْ] مِنْ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ سَيُصِيبُهُمْ سَيِّـَٔـاتُ مَا كَسَبُو[s[اْ] وَمَا ه[c:7421[ُم ب]ِمُعْجِز[p[ِي]نَ","Бас, уларга қилган касбларининг ёмонликлари мусибат бўлди. Анавилардан зулм қилганларига ҳам тезда қилган касбларининг ёмонликлари мусибат бўлур. Улар қочиб қутулгувчи ҳам эмаслар.",464,24],["أَوَلَمْ يَعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَ[q:6968[بْ]سُطُ [h:6969[ٱ][l[ل]رِّزْقَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيَ[q:6970[قْ]دِرُ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:4294[مٍ ي]ُؤْمِن[p[ُو]نَ","Улар Аллоҳ хоҳлаган кишисига ризқни кенг ва тор қилишини билмасмидилар?! Албатта, бунда иймон келтиргувчи қавмлар учун оят-белгилар бордир.",464,24],["۞ قُلْ يَ[n[ـٰ]عِبَادِىَ [h:10397[ٱ]لَّذِينَ أَسْرَفُو[s[اْ] عَلَ[o[ىٰٓ] أَ[f:568[نف]ُسِهِمْ لَا تَ[q:11727[قْ]نَطُو[s[اْ] م[u:7271[ِن ر]َّحْمَةِ [h:2157[ٱ]للَّهِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَغْفِرُ [h:2250[ٱ][l[ل]ذُّنُوبَ جَمِيعًا‌ۚ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:6822[ٱ]لْغَفُورُ [h:6228[ٱ][l[ل]رَّح[p[ِي]مُ","Сен менинг тарафимдан: «Эй ўз жонларига исроф қилган бандаларим, Аллоҳнинг раҳматидан ноумид бўлманг! Албатта, Аллоҳ барча гуноҳларни мағфират этар. Албатта, унинг ўзи ўта мағфиратли ва ўта раҳмли зотдир», деб айт.",464,24],["وَأَنِيب[o[ُوٓ][s[اْ] إِلَىٰ رَبِّكُمْ وَأَسْلِمُو[s[اْ] لَهُ[n[ۥ] مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:1405[َن ي]َأْتِيَكُمُ [h:11728[ٱ]لْعَذَابُ ثُ[g[مّ]َ لَا تُ[f:6517[نص]َر[p[ُو]نَ","Сизга азоб келишидан олдин Роббингизга қайтинг ва Унга таслим бўлинг. Сўнгра сизга ёрдам берилмас.",464,24],["وَ[h:9999[ٱ]تَّبِع[o[ُوٓ][s[اْ] أَحْسَنَ م[o[َآ] أُ[f:17[نز]ِلَ إِلَيْك[w:3691[ُم م]ّ[u:243[ِن ر]َّبِّك[w:11729[ُم م]ِّ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:1405[َن ي]َأْتِيَكُمُ [h:11728[ٱ]لْعَذَابُ بَغْتَ[a:11730[ةً و]َأَ[f:98[نت]ُمْ لَا تَشْعُر[p[ُو]نَ","Сизга ўзингиз сезмаган ҳолда тўсатдан азоб келиб қолишидан олдин Роббингиздан сизга туширилган энг гўзал нарсага эргашинг.",464,24],["أَ[f:8589[ن ت]َقُولَ نَفْ[a:11731[سٌ ي]َ[n[ـٰ]حَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَ[i:11732[نۢب]ِ [h:11733[ٱ]للَّهِ وَإِ[f:11734[ن ك]ُ[f:2917[نت]ُ لَمِنَ [h:11735[ٱ][l[ل]سَّ[n[ـٰ]خِر[p[ِي]نَ","Жон: «Аллоҳ ҳақида йўл қўйган камчиликларим учун надомат бўлсин. Тўғриси, мен масхара қилгувчилардан бўлган эдим», демасидан олдин...",464,24],["أَوْ تَقُولَ لَوْ أَ[g[نّ]َ [h:394[ٱ]للَّهَ هَدَ[n[ٮٰ]نِى لَكُ[f:11372[نت]ُ مِنَ [h:3499[ٱ]لْمُتَّق[p[ِي]نَ","Ёки: «Агар Аллоҳ мени ҳидоят қилганида, албатта, тақводорлардан бўлар эдим», демасидан олдин...",465,24],["أَوْ تَقُولَ حِينَ تَرَى [h:11736[ٱ]لْعَذَابَ لَوْ أَ[g[نّ]َ لِى كَرَّ[f:11737[ةً ف]َأَكُونَ مِنَ [h:4754[ٱ]لْمُحْسِن[p[ِي]نَ","Ёки азобни кўрган чоғида: «Агар менга яна бир марта ортга қайтиш бўлганида, гўзал амал қилгувчилардан бўлар эдим», демасидан олдин...",465,24],["بَلَىٰ قَ[q:298[دْ] ج[o[َا]ٓءَتْكَ ءَايَ[n[ـٰ]تِى فَكَذَّ[q:11738[بْ]تَ بِهَا وَ[h:11739[ٱ]سْتَكْبَرْتَ وَكُ[f:6187[نت]َ مِنَ [h:182[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","«Йўқ! Батаҳқиқ, сенга Менинг оятларим келди. Бас, сен уларни ёлғонга чиқардинг, мутакаббирлик қилдинг ва кофирлардан бўлдинг!» дейди.",465,24],["وَيَوْمَ [h:443[ٱ]لْقِيَ[n[ـٰ]مَةِ تَرَى [h:11740[ٱ]لَّذِينَ كَذَبُو[s[اْ] عَلَى [h:412[ٱ]للَّهِ وُجُوهُه[w:11741[ُم م]ُّسْوَدَّةٌ‌ۚ أَلَيْسَ فِى جَهَ[g[نّ]َمَ مَثْ[u:11742[وًى ل]ِّلْمُتَكَبِّر[p[ِي]نَ","Қиёмат куни Аллоҳга нисбатан ёлғон сўзлаганларни кўрсанг, юзлари қоп-қорадир. Ёки мутакаббирларнинг жойи жаҳаннамда эмасми?!",465,24],["وَيُنَجِّى [h:11743[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ [h:2523[ٱ]تَّقَوْ[s[اْ] بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ [h:11744[ٱ][l[ل]سّ[o[ُو]ٓءُ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Аллоҳ тақво қилганларга ютуқлари туфайли нажот берур. Уларга ёмонлик етмас ва улар хафа ҳам бўлмас.",465,24],["ٱللَّهُ خَ[n[ـٰ]لِقُ كُلِّ ش[a:4300[َىْءٍ‌ۖ و]َهُوَ عَلَىٰ كُلِّ ش[a:4302[َىْءٍ و]َك[p[ِي]لٌ","Аллоҳ ҳар бир нарсанинг яратгувчисидир. Ва У ҳар бир нарсага вакилдир.",465,24],["لَّهُ[n[ۥ] مَقَالِيدُ [h:11745[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۗ وَ[h:37[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:150[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","Осмонлару ернинг калитлари Унгагина хосдир. Аллоҳнинг оятларига куфр келтирганлар, ана ўшалар зиёнкорлардир.",465,24],["قُلْ أَفَغَيْرَ [h:4347[ٱ]للَّهِ تَأْمُر[m[ُو]ٓ[g[نّ][o[ِىٓ] أَعْبُدُ أَيُّهَا [h:11746[ٱ]لْجَ[n[ـٰ]هِل[p[ُو]نَ","Сен: «Эй жоҳиллар! Мени Аллоҳдан ўзгага ибодат қилишимга буюрурмисиз?!» деб айт.",465,24],["وَلَقَ[q:341[دْ] أُوحِىَ إِلَيْكَ وَإِلَى [h:11747[ٱ]لَّذِينَ مِ[f:18[ن ق]َ[q:19[بْ]لِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَ[g[نّ]َ عَمَلُكَ وَلَتَكُونَ[g[نّ]َ مِنَ [h:340[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","Батаҳқиқ, сенга ва сендан олдин ўтганларга ҳам: «Агар ширк келтирсанг, албатта, амалинг беҳуда кетур ва, албатта, зиёнкорлардан бўлурсан.",465,24],["بَلِ [h:11748[ٱ]للَّهَ فَ[h:11749[ٱ]عْبُ[q:11749[دْ] وَك[a:5006[ُن م]ِّنَ [h:4134[ٱ][l[ل]شَّ[n[ـٰ]كِر[p[ِي]نَ","Йўқ! Аллоҳгагина ибодат қил ва шукр этгувчилардан бўл!» деб ваҳий қилинган.",465,24],["وَمَا قَدَرُو[s[اْ] [h:4225[ٱ]للَّهَ حَقَّ قَ[q:4226[دْ]رِه[n[ِۦ] وَ[h:2241[ٱ]لْأَرْضُ جَمِي[f:11750[عًا ق]َ[q:11751[بْ]ضَتُهُ[n[ۥ] يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ وَ[h:7179[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تُ مَ[q:11752[طْ]وِيَّ[n[ـٰ][i:11753[تُۢ ب]ِيَمِينِه[n[ِۦ]‌ۚ سُ[q:608[بْ]حَ[n[ـٰ]نَهُ[n[ۥ] وَتَعَ[n[ـٰ]لَىٰ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","Улар Аллоҳнинг қадрини тўғри тақдирламадилар. Ҳолбуки, ер борлигича Унинг сиқимидадир. Осмонлар эса, Унинг қудрат қўлига йиғилгандир. У зот улар ширк келтираётган нарсалардан пок ва юксакдир.",465,24],["وَنُفِخَ فِى [h:4185[ٱ][l[ل]صُّورِ فَصَعِقَ مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَ[f:3453[ن ف]ِى [h:44[ٱ]لْأَرْضِ إِلَّا مَ[f:9680[ن ش][o[َا]ٓءَ [h:78[ٱ]للَّهُ‌ۖ ثُ[g[مّ]َ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَا[a:11754[مٌ ي]َ[f:1141[نظ]ُر[p[ُو]نَ","Ва сурга пуфланди. Осмонлару ерда ким бўлса, қулаб ўлди. Магар Аллоҳ хоҳлаганларгина қолди. Сўнгра унга яна бир бор пуфланди. Бас, тўсатдан улар туриб интизор бўлурлар.",466,24],["وَأَشْرَقَتِ [h:11755[ٱ]لْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ [h:8115[ٱ]لْكِتَ[n[ـٰ]بُ وَجِ[s[اْ][o[ىٓ]ءَ بِ[h:11756[ٱ][l[ل][g[نّ]َبِيِّـ[n[ـۧ]نَ وَ[h:2904[ٱ][l[ل]شُّهَد[o[َا]ٓءِ وَقُضِىَ بَيْنَه[c:11757[ُم ب]ِ[h:370[ٱ]لْحَقِّ وَهُمْ لَا يُظْلَم[p[ُو]نَ","Ва ер Робби нури ила ёришди. Китоб қўйилди. Пайғамбарлар ва гувоҳлар келтирилди. Улар орасида ҳақ ила ҳукм чиқарилди. Уларга зулм қилинмади.",466,24],["وَوُفِّيَتْ كُلُّ نَفْ[a:1654[سٍ م]َّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَل[p[ُو]نَ","Ва ҳар бир жонга қилган амали тўлиқ берилди. У зот улар қилаётган ишларни ўта яхши билгувчидир.",466,24],["وَسِيقَ [h:11758[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] إِلَىٰ جَهَ[g[نّ]َمَ زُمَرًا‌ۖ حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءُوهَا فُتِحَتْ أَ[q:11759[بْ]و[n[َٲ]بُهَا وَقَالَ لَهُمْ خَزَنَتُه[o[َآ] أَلَمْ يَأْتِكُمْ رُسُ[a:4419[لٌ م]ِّ[f:344[نك]ُمْ يَتْلُونَ عَلَيْكُمْ ءَايَ[n[ـٰ]تِ رَبِّكُمْ وَيُ[f:4420[نذ]ِرُونَكُمْ لِق[o[َا]ٓءَ يَوْمِكُمْ هَ[n[ـٰ]ذَا‌ۚ قَالُو[s[اْ] بَلَىٰ وَلَ[n[ـٰ]كِنْ حَقَّتْ كَلِمَةُ [h:11662[ٱ]لْعَذَابِ عَلَى [h:468[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Ва куфр келтирганлар жаҳаннамга гуруҳ-гуруҳ қилиб ҳайдалди. Токи унга етиб келган чоғларида унинг эшиклари очилди ва унинг қўриқчилари уларга: «Сизларга ўзингиздан бўлган Пайғамбарлар келиб, Роббингиз оятларини тиловат қилиб бермадиларми? Сизларни ушбу кунингизга дучор бўлишингиздан огоҳлантирмадиларми?!» дедилар. Улар: «Ҳа! Лекин азоб сўзи кофирлар устига ҳақ бўлгандир», дедилар.",466,24],["قِيلَ [h:11760[ٱ][q:278[دْ]خُل[o[ُوٓ][s[اْ] أَ[q:4047[بْ]و[n[َٲ]بَ جَهَ[g[نّ]َمَ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۖ فَبِئْسَ مَثْوَى [h:7387[ٱ]لْمُتَكَبِّر[p[ِي]نَ","«Жаҳаннам эшикларидан унда абадий қолгувчи бўлган ҳолингизда киринг», дейилди. Бас, мутакаббирларнинг жойи қандай ҳам ёмон бўлди.",466,24],["وَسِيقَ [h:11758[ٱ]لَّذِينَ [h:2523[ٱ]تَّقَوْ[s[اْ] رَبَّهُمْ إِلَى [h:1243[ٱ]لْجَ[g[نّ]َةِ زُمَرًا‌ۖ حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءُوهَا وَفُتِحَتْ أَ[q:11759[بْ]و[n[َٲ]بُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَ[n[ـٰ]مٌ عَلَيْكُمْ طِ[q:11761[بْ]تُمْ فَ[h:11762[ٱ][q:11762[دْ]خُلُوهَا خَ[n[ـٰ]لِد[p[ِي]نَ","Ва Роббиларига тақво қилганлар жаннатга гуруҳ-гуруҳ қилиб олиб борилдилар. Токи унга етиб келган чоғларида унинг эшиклари очилди ва унинг қўриқчилари уларга: «Сизга саломлар бўлсин! Хуш келдингиз! Бас, унга абадий қолгувчи бўлган ҳолингизда киринг», дедилар.",466,24],["وَقَالُو[s[اْ] [h:4698[ٱ]لْحَمْدُ لِلَّهِ [h:3912[ٱ]لَّذِى صَدَقَنَا وَعْدَهُ[n[ۥ] وَأَوْرَثَنَا [h:11763[ٱ]لْأَرْضَ نَتَبَوَّأُ مِنَ [h:4643[ٱ]لْجَ[g[نّ]َةِ حَيْثُ نَش[o[َا]ٓءُ‌ۖ فَنِعْمَ أَ[q:2254[جْ]رُ [h:2255[ٱ]لْعَ[n[ـٰ]مِل[p[ِي]نَ","Улар: «Бизларга берган ваъдасини рост қилган ва бизга бу ерни мерос қилиб берган Аллоҳга ҳамдлар бўлсин. Энди ундан хоҳлаган жойимизни оламиз», дедилар. Бас, амал қилувчиларнинг ажри қандай ҳам яхши бўлди!",466,24],["وَتَرَى [h:11764[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةَ ح[m[َا]ٓفِّينَ مِنْ حَوْلِ [h:11765[ٱ]لْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ‌ۖ وَقُضِىَ بَيْنَه[c:11757[ُم ب]ِ[h:370[ٱ]لْحَقِّ وَقِيلَ [h:11766[ٱ]لْحَمْدُ لِلَّهِ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Ва фаришталарни Аршни ўраб олиб Роббиларига ҳамд ила тасбиҳ айтаётган ҳолда кўрурсан. Улар орасида ҳақ ила ҳукм қилинур ва: «Оламларнинг Робби Аллоҳга ҳамду сано бўлсин!» дейилди.",467,24]]},{"n":40,"ar":"غَافِرٍ","en":"Ghafir","uz":"Ғофир","type":"Макка","ayahs":[["ح[m[مٓ]","Ҳа-а. Мийм.",467,24],["تَ[f:10623[نز]ِيلُ [h:10624[ٱ]لْكِتَ[n[ـٰ]بِ مِنَ [h:321[ٱ]للَّهِ [h:11613[ٱ]لْعَزِيزِ [h:4269[ٱ]لْعَل[p[ِي]مِ","Бу китобнинг нозил қилиниши азизу ўта илмли Аллоҳ томонидандир.",467,24],["غَافِرِ [h:11767[ٱ][l[ل]ذَّ[i:11768[نۢب]ِ وَقَابِلِ [h:11769[ٱ][l[ل]تَّوْبِ شَدِيدِ [h:11770[ٱ]لْعِقَابِ ذِى [h:11771[ٱ][l[ل]طَّوْلِۖ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَۖ إِلَيْهِ [h:11772[ٱ]لْمَص[p[ِي]رُ","У гуноҳни мағфират қилгувчи, тавбани қабул этгувчи, иқоби шиддатли ва фазлу карам соҳиби бўлган зотдир. Ундан ўзга ибодатга сазовор зот йўқ. Қайтиш Унинг Ўзигагинадир.",467,24],["مَا يُجَ[n[ـٰ]دِلُ ف[o[ِىٓ] ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ إِلَّا [h:778[ٱ]لَّذِينَ كَفَرُو[s[اْ] فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِى [h:2519[ٱ]لْبِلَ[p[ـٰ][q[د]ِ","Аллоҳнинг оятлари ҳақида фақатгина куфр келтирганлар талашиб-тортишурлар. Бас, уларнинг юртларда айланиб юришлари сени алдаб қўймасин.",467,24],["كَذَّبَتْ قَ[q:8394[بْ]لَهُمْ قَوْمُ نُو[a:11773[حٍ و]َ[h:11774[ٱ]لْأَحْزَابُ م[i:1453[ِنۢ ب]َعْدِهِمْۖ وَهَ[g[مّ]َتْ كُلُّ أُ[g[مّ]َ[i:11775[ةِۭ ب]ِرَسُولِهِمْ لِيَأْخُذُوهُۖ وَجَ[n[ـٰ]دَلُو[s[اْ] بِ[h:212[ٱ]لْبَ[n[ـٰ]طِلِ لِيُ[q:8130[دْ]حِضُو[s[اْ] بِهِ [h:8131[ٱ]لْحَقَّ فَأَخَذْتُهُمْۖ فَكَيْفَ كَانَ عِق[p[َا][q[ب]ِ","Улардан олдин Нуҳ қавми ва улар кетидан келган фирқалар ҳам ёлғончи қилган эдилар. Ҳар уммат ўз Пайғамбарини тутишга қасд қилди ва ҳақни йўқотиш учун ботил ила мужодала этди. Бас, Мен уларни тутдим. Бас, Менинг иқобим қандай бўлди!",467,24],["وَكَذ[n[َٲ]لِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى [h:289[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أَ[g[نّ]َهُمْ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ][p[َا]رِ","Куфр келтирганларга ҳам Роббингнинг сўзи худди ана шундай ҳақ бўлди. Албатта, улар дўзах эгаларидир.",467,24],["ٱلَّذِينَ يَحْمِلُونَ [h:11776[ٱ]لْعَرْشَ وَمَنْ حَوْلَهُ[n[ۥ] يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِه[n[ِۦ] وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُو[s[اْ] رَبَّنَا وَسِعْتَ كُلَّ ش[u:11777[َىْءٍ ر]َّحْمَ[a:11778[ةً و]َعِلْ[f:11779[مًا ف]َ[h:1791[ٱ]غْفِرْ لِلَّذِينَ تَابُو[s[اْ] وَ[h:2433[ٱ]تَّبَعُو[s[اْ] سَبِيلَكَ وَقِهِمْ عَذَابَ [h:11780[ٱ]لْجَح[p[ِي]مِ","Аршни кўтариб турадиганлар ва унинг атрофидагилар Роббларига ҳамд ила тасбиҳ айтурлар, Унга иймон келтирурлар ва иймон келтирганларга мағфират сўраб: «Эй Роббимиз, раҳматинг ва илминг ила ҳар бир нарсани қуршагансан, бас, тавба қилиб, йўлингга эргашганларни мағфират қилгин ва уларни дўзах азобидан сақлагин.",467,24],["رَبَّنَا وَأَ[q:11781[دْ]خِلْهُمْ جَ[g[نّ]َ[n[ـٰ]تِ عَ[q:5720[دْ]نٍ [h:8376[ٱ]لَّتِى وَعَ[d:11782[د]تَّهُمْ وَمَ[f:6964[ن ص]َلَحَ مِنْ ءَاب[o[َا]ٓئِهِمْ وَأَزْو[n[َٲ]جِهِمْ وَذُرِّيَّ[n[ـٰ]تِهِمْۚ إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:680[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Эй Роббимиз, уларни ҳам, оталаридан, жуфтларидан ва зурриётларидан аҳли солиҳ бўлганларини ҳам Ўзинг уларга ваъда қилган адн жаннатларига киритгин. Албатта, Сенинг Ўзинг азизу ўта ҳикматли зотсан.",468,24],["وَقِهِمُ [h:11783[ٱ][l[ل]سَّيِّـَٔـاتِۚ وَمَ[f:11784[ن ت]َقِ [h:11785[ٱ][l[ل]سَّيِّـَٔـاتِ يَوْمَئِ[f:3960[ذٍ ف]َقَ[q:563[دْ] رَحِمْتَهُ[n[ۥ]ۚ وَذ[n[َٲ]لِكَ هُوَ [h:5722[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Ва уларни ёмонликлардан сақла, ўша куни кимни ёмонликлардан сақласанг, батаҳқиқ, унга раҳм қилибсан. Ана ўша буюк ютуқдир»,.",468,24],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] يُنَادَوْنَ لَمَ[q:11786[قْ]تُ [h:11787[ٱ]للَّهِ أَكْبَرُ م[a:11788[ِن م]َّ[q:11789[قْ]تِكُمْ أَ[f:221[نف]ُسَكُمْ إِذْ تُ[q:11790[دْ]عَوْنَ إِلَى [h:11791[ٱ]لْإِيمَ[n[ـٰ]نِ فَتَكْفُر[p[ُو]نَ","Албатта, куфр келтирганларга: «Иймонга чақирилганингизда куфр келтирган чоғингиздаги Аллоҳнинг ғазаби сизнинг ўзингизга ғазабингиздан каттароқдир», деб нидо қилинур.",468,24],["قَالُو[s[اْ] رَبَّن[o[َآ] أَمَتَّنَا [h:11792[ٱ]ثْنَتَيْنِ وَأَحْيَيْتَنَا [h:11793[ٱ]ثْنَتَيْنِ فَ[h:11794[ٱ]عْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَىٰ خُرُو[a:11795[جٍ م]ِّ[f:5782[ن س]َب[p[ِي]لٍ","Улар: «Эй Роббимиз, Сен бизни икки марта ўлдирдинг, икки марта тирилтирдинг. Бас, биз гуноҳларимизни эътироф этдик. Энди чиқишнинг бирон йўли борми?» дедилар.",468,24],["ذ[n[َٲ]لِك[c:11796[ُم ب]ِأَ[g[نّ]َهُ[o[ۥٓ] إِذَا دُعِىَ [h:11797[ٱ]للَّهُ وَحْدَهُ[n[ۥ] كَفَرْتُمْۖ وَإ[a:11798[ِن ي]ُشْرَكْ بِه[n[ِۦ] تُؤْمِنُو[s[اْۚ] فَ[h:11799[ٱ]لْحُكْمُ لِلَّهِ [h:11800[ٱ]لْعَلِىِّ [h:11801[ٱ]لْكَب[p[ِي]رِ","Бундай бўлишингиз Аллоҳнинг ёлғиз Ўзига даъват қилинганида, куфр келтирганингиз, Унга ширк келтирилса, иймон келтирганингиз учундир. Бас, ҳукм олий ва улуғ Аллоҳникидир.",468,24],["هُوَ [h:153[ٱ]لَّذِى يُرِيكُمْ ءَايَ[n[ـٰ]تِه[n[ِۦ] وَيُنَزِّلُ لَك[w:1578[ُم م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ رِزْ[a:11802[قًاۚ و]َمَا يَتَذَكَّرُ إِلَّا م[a:11803[َن ي]ُن[p[ِي][q[ب]ُ","Унинг Ўзи сизга оят-белгиларини кўрсатадиган, осмондан сизга ризқ туширадиган зотдир. Фақат қайтадиган кишигина англар.",468,24],["فَ[h:9999[ٱ][q:11804[دْ]عُو[s[اْ] [h:11805[ٱ]للَّهَ مُخْلِصِينَ لَهُ [h:4649[ٱ][l[ل]دِّينَ وَلَوْ كَرِهَ [h:5556[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Бас, агар кофирлар ёқтирмасалар ҳам, Аллоҳга динни холис қилган ҳолингизда ёлборинг.",468,24],["رَفِيعُ [h:11806[ٱ][l[ل]دَّرَجَ[n[ـٰ]تِ ذُو [h:11807[ٱ]لْعَرْشِ يُلْقِى [h:11808[ٱ][l[ل]رُّوحَ مِنْ أَمْرِه[n[ِۦ] عَلَىٰ م[a:476[َن ي]َش[o[َا]ٓءُ مِنْ عِبَادِه[n[ِۦ] لِيُ[f:7947[نذ]ِرَ يَوْمَ [h:11809[ٱ][l[ل]تَّل[p[َا][q[ق]ِ","У даражаси юксак, Арш эгаси бўлган зотдир. У Ўз амри ила бандаларидан кимни хоҳласа, ўшанга мулоқот кунидан огоҳлантириши учун руҳни туширур.",468,24],["يَوْمَ ه[c:11810[ُم ب]َ[n[ـٰ]رِزُونَۖ لَا يَخْفَىٰ عَلَى [h:412[ٱ]للَّهِ مِنْهُمْ ش[u:11811[َىْءٌۚ ل]ِّمَنِ [h:11812[ٱ]لْمُلْكُ [h:11813[ٱ]لْيَوْمَۖ لِلَّهِ [h:7180[ٱ]لْو[n[َٲ]حِدِ [h:7181[ٱ]لْقَهّ[p[َا]رِ","Ўша кунда улар зоҳир бўлурлар. Аллоҳга улардан бирон нарса махфий қолмас. Бугун мулк кимникидир?! Яккаю ёлғиз, ўта қаҳрли Аллоҳникидир!",468,24],["ٱلْيَوْمَ تُ[q:11814[جْ]زَىٰ كُلُّ نَفْ[i:6995[سِۭ ب]ِمَا كَسَبَتْۚ لَا ظُلْمَ [h:11815[ٱ]لْيَوْمَۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَرِيعُ [h:1112[ٱ]لْحِس[p[َا][q[ب]ِ","Бугунги кунда ҳар бир жон ўзи қилган касбга яраша жазо олур. Бугунги кунда зулм йўқдир. Албатта, Аллоҳ ҳисобни тез қилгувчи зотдир.",469,24],["وَأَ[f:8340[نذ]ِرْهُمْ يَوْمَ [h:11816[ٱ]لْأَزِفَةِ إِذِ [h:11817[ٱ]لْقُلُوبُ لَدَى [h:11818[ٱ]لْحَنَاجِرِ كَ[n[ـٰ]ظِمِينَۚ مَا لِلظَّ[n[ـٰ]لِمِينَ مِنْ حَمِي[a:11819[مٍ و]َلَا شَفِي[a:11820[عٍ ي]ُط[p[َا]عُ","Сен уларни яқинлашгувчи кундан огоҳлантир. Ўшанда жонлар халқумга келиб, ғам-ғуссага тўлиб турарлар. Золимлар учун ҳеч бир дўст ҳам, итоат қилинадиган шафоатчи ҳам йўқ.",469,24],["يَعْلَمُ خ[o[َا]ٓئِنَةَ [h:11821[ٱ]لْأَعْيُنِ وَمَا تُخْفِى [h:11822[ٱ][l[ل]صُّد[p[ُو]رُ","У зот кўзларнинг хиёнатини ҳам, диллар махфий тутган нарсаларни ҳам билур.",469,24],["وَ[h:9999[ٱ]للَّهُ يَ[q:6194[قْ]ضِى بِ[h:370[ٱ]لْحَقِّۖ وَ[h:37[ٱ]لَّذِينَ يَ[q:1240[دْ]عُونَ مِ[f:3136[ن د]ُونِه[n[ِۦ] لَا يَ[q:11823[قْ]ضُونَ بِشَىْءٍۗ إِ[g[نّ]َ [h:80[ٱ]للَّهَ هُوَ [h:3721[ٱ][l[ل]سَّمِيعُ [h:7657[ٱ]لْبَص[p[ِي]رُ","Аллоҳ ҳақ ила ҳукм қилур. Ундан ўзга илтижо қилаётганлари эса, ҳеч нарса билан ҳукм қилмаслар. Албатта, Аллоҳнинг Ўзи ўта эшитгувчи ва ўта кўргувчи зотдир.",469,24],["۞ أَوَلَمْ يَسِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَيَ[f:6853[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6854[ٱ]لَّذِينَ كَانُو[s[اْ] مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْۚ كَانُو[s[اْ] هُمْ أَشَدَّ مِنْهُمْ قُوَّ[a:11824[ةً و]َءَاثَا[f:11825[رًا ف]ِى [h:44[ٱ]لْأَرْضِ فَأَخَذَهُمُ [h:1756[ٱ]للَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَه[w:6026[ُم م]ِّنَ [h:321[ٱ]للَّهِ م[a:7001[ِن و][p[َا][q[ق]ٍ","Ахир улар ер юзида юриб, ўзларидан олдин ўтганларнинг оқибати қандай бўлганига назар солмайдиларми?! Ўшалар улардан кўра қувватлироқ ва ер юзида асарлари кўпроқ бўлган эдилар. Бас, Аллоҳ ўшаларни гуноҳлари сабабли тутди. Уларга Аллоҳдан ўзга бир сақловчи бўлмади.",469,24],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ كَانَت تَّأْتِيهِمْ رُسُلُه[c:4900[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ فَكَفَرُو[s[اْ] فَأَخَذَهُمُ [h:1756[ٱ]للَّهُۚ إِ[g[نّ]َهُ[n[ۥ] قَوِ[f:5381[ىٌّ ش]َدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Бундай бўлишининг сабаби шуки, уларга Пайғамбарлари келар эдилар, улар эса, куфр келтирдилар. Бас, Аллоҳ уларни тутди. Албатта, у кучли ва иқоби шиддатли зотдир.",469,24],["وَلَقَ[q:341[دْ] أَرْسَلْنَا مُوسَىٰ بِـَٔـايَ[n[ـٰ]تِنَا وَسُلْطَ[n[ـٰ][a:6479[نٍ م]ُّب[p[ِي]نٍ","Батаҳқиқ, Биз Мусони Ўз оятларимиз ва очиқ ҳужжат ила юбордик.",469,24],["إِلَىٰ فِرْعَوْنَ وَهَ[n[ـٰ]مَ[n[ـٰ]نَ وَقَ[n[ـٰ]رُونَ فَقَالُو[s[اْ] سَ[n[ـٰ]حِ[f:11472[رٌ ك]َذّ[p[َا][q[ب]ٌ","Фиръавнга, Ҳомонга ва Қорунга. Бас, улар: « сеҳргар ва каззоб», дедилар.",469,24],["فَلَ[g[مّ]َا ج[o[َا]ٓءَه[c:9251[ُم ب]ِ[h:370[ٱ]لْحَقِّ مِنْ عِ[f:6142[ند]ِنَا قَالُو[s[اْ] [h:11826[ٱ][q:2891[قْ]تُل[o[ُوٓ][s[اْ] أَ[q:11827[بْ]ن[o[َا]ٓءَ [h:11828[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مَعَهُ[n[ۥ] وَ[h:11829[ٱ]سْتَحْيُو[s[اْ] نِس[o[َا]ٓءَهُمْۚ وَمَا كَيْدُ [h:11830[ٱ]لْكَ[n[ـٰ]فِرِينَ إِلَّا فِى ضَلَ[p[ـٰ]لٍ","Мусо уларга Бизнинг ҳузуримиздан ҳақ ила келган чоқда, улар: «У билан бирга иймон келтирганларнинг ўғилларини қатл қилинглар, қизларини тирик қолдиринглар», дедилар. Кофирларнинг макр-ҳийласи залолатдан бошқа нарса эмас.",469,24],["وَقَالَ فِرْعَوْنُ ذَرُون[o[ِىٓ] أَ[q:11831[قْ]تُلْ مُوسَىٰ وَلْيَ[q:11832[دْ]عُ رَبَّهُ[o[ۥٓ‌ۖ] إِ[g[نّ][o[ِىٓ] أَخَافُ أ[a:11833[َن ي]ُبَدِّلَ دِينَكُمْ أَوْ أ[a:11834[َن ي]ُظْهِرَ فِى [h:44[ٱ]لْأَرْضِ [h:11835[ٱ]لْفَس[p[َا][q[د]َ","Фиръавн: «Мени қўйинглар, Мусони ўлдирай. Майли, Роббига дуо қилсин. Албатта, мен унинг динингизни алмаштиришидан ва ер юзида фасод чиқаришидан қўрқмоқдаман», деди.",470,24],["وَقَالَ مُوسَ[o[ىٰٓ] إِ[g[نّ]ِى عُذْتُ بِرَبِّى وَرَبِّك[w:11836[ُم م]ِّ[f:843[ن ك]ُلِّ مُتَكَبِّ[u:11837[رٍ ل]َّا يُؤْمِنُ بِيَوْمِ [h:11838[ٱ]لْحِس[p[َا][q[ب]ِ","Мусо: «Албатта, мен Роббим ва Роббингиз бўлган зотдан ҳисоб кунига иймон келтирмайдиган ҳар бир мутакаббирдан паноҳ сўрайман», деди.",470,24],["وَقَالَ رَجُ[a:11839[لٌ م]ُّؤْمِ[a:11840[نٌ م]ِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَ[n[ـٰ]نَهُ[o[ۥٓ] أَتَ[q:11841[قْ]تُلُونَ رَجُلاً أ[a:11309[َن ي]َقُولَ رَبِّىَ [h:11842[ٱ]للَّهُ وَقَ[q:387[دْ] ج[o[َا]ٓءَك[c:11843[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ م[u:243[ِن ر]َّبِّكُمْۖ وَإ[a:11844[ِن ي]َكُ كَ[n[ـٰ]ذِ[f:11845[بًا ف]َعَلَيْهِ كَذِبُهُ[n[ۥ]ۖ وَإ[a:11844[ِن ي]َكُ صَادِ[a:11846[قًا ي]ُصِ[q:11847[بْ]ك[c:11848[ُم ب]َعْضُ [h:10025[ٱ]لَّذِى يَعِدُكُمْۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِ[f:11849[فٌ ك]َذّ[p[َا][q[ب]ٌ","Фиръавн аҳлидан бўлган, иймонини беркитиб юрадиган бир мўмин киши: «Бир одамни, Аллоҳ Роббимдир, дегани учун ўлдирасизларми?! Ҳолбуки, у сизга Роббингиздан очиқ-ойдин ҳужжатлар ила келмишдир. Агар у ёлғончи бўлса, ёлғони ўзига зарар. Агар ростгўй бўлса, унда у ваъда қилаётган баъзи мусибатлар сизга етади. Албатта, Аллоҳ исрофчи ва каззоб бўлган шахсни ҳидоят қилмас.",470,24],["يَ[n[ـٰ]قَوْمِ لَكُمُ [h:11850[ٱ]لْمُلْكُ [h:11813[ٱ]لْيَوْمَ ظَ[n[ـٰ]هِرِينَ فِى [h:44[ٱ]لْأَرْضِ فَم[a:11851[َن ي]َ[f:11852[نص]ُرُنَا م[i:11853[ِنۢ ب]َأْسِ [h:11854[ٱ]للَّهِ إِ[f:11855[ن ج][o[َا]ٓءَنَاۚ قَالَ فِرْعَوْنُ م[o[َآ] أُرِيكُمْ إِلَّا م[o[َآ] أَرَىٰ وَم[o[َآ] أَهْدِيكُمْ إِلَّا سَبِيلَ [h:11856[ٱ][l[ل]رَّش[p[َا][q[د]ِ","Эй қавмим, бугунги кунда мулк сизникидир. Ер юзида юзага чиқиб турибсизлар. Агар бизга Аллоҳнинг азоби келса, унда бизга ким ёрдам беради?!» деди. Фиръавн: «Мен сизга ўзим кўраётган нарсадан бошқани кўрсатмасман ва сизларни тўғри йўлдан бошқага йўлламасман», деди.",470,24],["وَقَالَ [h:6593[ٱ]لَّذ[o[ِىٓ] ءَامَنَ يَ[n[ـٰ]قَوْمِ إِ[g[نّ][o[ِىٓ] أَخَافُ عَلَيْك[w:11857[ُم م]ِّثْلَ يَوْمِ [h:11858[ٱ]لْأَحْز[p[َا][q[ب]ِ","Иймон келирган киши: «Эй қавмим, албатта, мен сизга ҳам бошқа фирқалар кунига ўхшаш кун...",470,24],["مِثْلَ دَأْبِ قَوْمِ نُو[a:5711[حٍ و]َعَا[a:5712[دٍ و]َثَمُودَ وَ[h:37[ٱ]لَّذِينَ م[i:1453[ِنۢ ب]َعْدِهِمْۚ وَمَا [h:384[ٱ]للَّهُ يُرِيدُ ظُلْ[u:11859[مًا ل]ِّلْعِب[p[َا][q[د]ِ","Нуҳ қавми, Од, Самуд ва улардан кейингилар ҳолига ўхшаш ҳол бўлишидан қўрқаман. Аллоҳ бандаларга зулмни ирода қилмас.",470,24],["وَيَ[n[ـٰ]قَوْمِ إِ[g[نّ][o[ِىٓ] أَخَافُ عَلَيْكُمْ يَوْمَ [h:11860[ٱ][l[ل]تَّن[p[َا][q[د]ِ","Эй қавмим, албатта, мен сизларга нидолашув кунидан қўрқаман.",470,24],["يَوْمَ تُوَلُّونَ مُ[q:5528[دْ]بِرِينَ مَا لَك[w:1578[ُم م]ِّنَ [h:321[ٱ]للَّهِ مِنْ عَاصِ[a:11861[مٍۗ و]َم[a:3002[َن ي]ُضْلِلِ [h:3003[ٱ]للَّهُ فَمَا لَهُ[n[ۥ] مِنْ ه[p[َا][q[د]ٍ","У кунда ортга қараб қочасиз. Сиз учун Аллоҳдан ҳеч бир қутқаргувчи бўлмас. Кимни Аллоҳ залолатга кетказса, бас, унга ҳеч бир ҳидоятчи бўлмас.",470,24],["وَلَقَ[q:341[دْ] ج[o[َا]ٓءَكُمْ يُوسُفُ مِ[f:128[ن ق]َ[q:129[بْ]لُ بِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ فَمَا زِلْتُمْ فِى شَ[a:6196[كٍّ م]ِّ[g[مّ]َا ج[o[َا]ٓءَك[c:11862[ُم ب]ِه[n[ِۦ]ۖ حَتَّ[o[ىٰٓ] إِذَا هَلَكَ قُلْتُمْ ل[a:11863[َن ي]َ[q:4140[بْ]عَثَ [h:11864[ٱ]للَّهُ م[i:254[ِنۢ ب]َعْدِه[n[ِۦ] رَسُوۚل[f:11865[اً ك]َذ[n[َٲ]لِكَ يُضِلُّ [h:11866[ٱ]للَّهُ مَنْ هُوَ مُسْرِ[a:11867[فٌ م]ُّرْت[p[َا][q[ب]ٌ","Батаҳқиқ, бундан олдин Юсуф очиқ-ойдин ҳужжатлар ила келди. Бас, сиз у ўзингизга келтирган нарсага шак келтириб, туриб олдингиз. Ниҳоят, у вафот этган пайтда: «Аллоҳ ундан кейин Пайғамбар юбормас», дедингиз. Аллоҳ шундай қилиб, исрофчи ва шубҳачи бўлган кимсани залолатга кетказди.",471,24],["ٱلَّذِينَ يُجَ[n[ـٰ]دِلُونَ ف[o[ِىٓ] ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ بِغَيْرِ سُلْطَ[n[ـٰ]نٍ أَتَ[n[ـٰ]هُمْۖ كَبُرَ مَ[q:11151[قْ]تًا عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَعِ[f:5476[ند]َ [h:11868[ٱ]لَّذِينَ ءَامَنُو[s[اْۚ] كَذ[n[َٲ]لِكَ يَ[q:4901[طْ]بَعُ [h:4902[ٱ]للَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّ[f:11869[رٍ ج]َبّ[p[َا]رٍ","Аллоҳнинг оятлари ҳақида ўзларига келган ҳужжат-далилсиз талашиб-тортишадиганлар Аллоҳ томонидан ҳам, иймон келтирганлар томонидан ҳам қаттиқ ғазабга қолурлар. Аллоҳ шундай қилиб, ҳар бир мутакаббир ва зўровон қалбни муҳрлар», деди.",471,24],["وَقَالَ فِرْعَوْنُ يَ[n[ـٰ]هَ[n[ـٰ]مَ[n[ـٰ]نُ [h:11870[ٱ][q:3590[بْ]نِ لِى صَرْ[u:10169[حًا ل]َّعَلّ[o[ِىٓ] أَ[q:11871[بْ]لُغُ [h:11872[ٱ]لْأَسْبَ[p[ـٰ][q[ب]َ","Фиръавн деди: «Эй Ҳомон, менга бир баланд қаср бино қил, шояд сабабларга етсам.",471,24],["أَسْبَ[n[ـٰ]بَ [h:11873[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ فَأَطَّلِعَ إِلَ[o[ىٰٓ] إِلَ[n[ـٰ]هِ مُوسَىٰ وَإِ[g[نّ]ِى لَأَظُ[g[نّ]ُهُ[n[ۥ] كَ[n[ـٰ]ذِ[a:11874[بًاۚ و]َكَذ[n[َٲ]لِكَ زُيِّنَ لِفِرْعَوْنَ س[o[ُو]ٓءُ عَمَلِه[n[ِۦ] وَصُدَّ عَنِ [h:6998[ٱ][l[ل]سَّبِيلِۚ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِى تَب[p[َا][q[ب]ٍ","Осмонларнинг сабабларига етсам, сўнгра Мусонинг Илоҳига боқсам. Албатта, мен уни ёлғончи деб гумон қилмоқдаман». Шундай қилиб, Фиръавнга унинг ёмон амали зийнатланди ва у йўлдан тўсилди. Фиръавннинг макр-ҳийласи зиёнкорликдан бошқа нарса эмас.",471,24],["وَقَالَ [h:6593[ٱ]لَّذ[o[ِىٓ] ءَامَنَ يَ[n[ـٰ]قَوْمِ [h:11875[ٱ]تَّبِعُونِ أَهْدِكُمْ سَبِيلَ [h:11856[ٱ][l[ل]رَّش[p[َا][q[د]ِ","Иймон келтирган киши: «Эй қавмим, менга эргашинглар, сизни тўғри йўлга ҳидоят қиламан.",471,24],["يَ[n[ـٰ]قَوْمِ إِ[g[نّ]َمَا هَ[n[ـٰ]ذِهِ [h:10406[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَا مَتَ[n[ـٰ][a:11876[عٌ و]َإِ[g[نّ]َ [h:11877[ٱ]لْأَخِرَةَ هِىَ دَارُ [h:11878[ٱ]لْقَر[p[َا]رِ","Эй қавмим, бу дунё ҳаёти вақтинчалик бир, матоҳ, холос. Албатта, охират- ўшанинг ўзи барқарорлик диёридир.",471,24],["مَنْ عَمِلَ سَيِّئَ[f:11879[ةً ف]َلَا يُ[q:4564[جْ]زَ[o[ىٰٓ] إِلَّا مِثْلَهَاۖ وَمَنْ عَمِلَ صَ[n[ـٰ]لِ[a:7575[حًا م]ِّ[f:2511[ن ذ]َكَرٍ أَوْ أُ[f:1867[نث]َىٰ وَهُوَ مُؤْمِ[f:3155[نٌ ف]َأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يَ[q:3156[دْ]خُلُونَ [h:3157[ٱ]لْجَ[g[نّ]َةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِس[p[َا][q[ب]ٍ","Ким бирор ёмонлик қилса, фақат ўшанга яраша жазо оладир, холос. Эркакдир, аёлдир, ҳар ким мўмин бўлган ҳолида солиҳ амал қилса, бас, ана ўшалар жаннатга кирурлар, у ерда ҳисобсиз ризқланурлар.",471,24],["۞ وَيَ[n[ـٰ]قَوْمِ مَا ل[o[ِىٓ] أَ[q:11880[دْ]عُوكُمْ إِلَى [h:11881[ٱ][l[ل][g[نّ]َجَ[s[و][n[ٲ]ةِ وَتَ[q:11882[دْ]عُونَن[o[ِىٓ] إِلَى [h:1241[ٱ][l[ل][g[نّ][p[َا]رِ","Эй қавмим, нечун мен сизни нажотга чақирсам, сиз мени дўзахга чақирурсиз?!",472,24],["تَ[q:11883[دْ]عُونَنِى لِأَكْفُرَ بِ[h:32[ٱ]للَّهِ وَأُشْرِكَ بِه[n[ِۦ] مَا لَيْسَ لِى بِه[n[ِۦ] عِلْ[a:11884[مٌ و]َأَنَا۟ أَ[q:11880[دْ]عُوكُمْ إِلَى [h:11885[ٱ]لْعَزِيزِ [h:11886[ٱ]لْغَفَّ[p[ـٰ]رِ","Сиз мени Аллоҳга куфр келтиришимга ва ўзим билмаган нарсани Унга ширк келтиришимга чақирмоқдасиз. Ҳолбуки, мен сизни азизу ўта мағфиратли зотга чақирмоқдаман.",472,24],["لَا جَرَمَ أَ[g[نّ]َمَا تَ[q:11883[دْ]عُونَن[o[ِىٓ] إِلَيْهِ لَيْسَ لَهُ[n[ۥ] دَعْوَ[f:11887[ةٌ ف]ِى [h:599[ٱ][l[ل]دُّنْيَا وَلَا فِى [h:536[ٱ]لْأَخِرَةِ وَأَ[g[نّ]َ مَرَدَّن[o[َآ] إِلَى [h:1637[ٱ]للَّهِ وَأَ[g[نّ]َ [h:11888[ٱ]لْمُسْرِفِينَ هُمْ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ][p[َا]رِ","Ҳеч шубҳа йўқки, албатта, сиз мени унга чақираётган нарсанинг дунёда ҳам, охиратда ҳам даъватга ҳаққи йўқдир. Албатта, қайтиб бораримиз Аллоҳгадир. Албатта, исрофчилар, айни ўшалар дўзах эгаларидир.",472,24],["فَسَتَذْكُرُونَ م[o[َآ] أَقُولُ لَكُمْۚ وَأُفَوِّضُ أَمْر[o[ِىٓ] إِلَى [h:1637[ٱ]للَّهِۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ بَصِي[i:1790[رُۢ ب]ِ[h:1133[ٱ]لْعِب[p[َا][q[د]ِ","Ҳали мен сизга айтаётган гапларни эслайсизлар. Мен ишимни Аллоҳнинг Ўзига топширдим. Албатта, Аллоҳ бандаларини аниқ кўриб тургувчидир», деди.",472,24],["فَوَقَ[n[ـٰ]هُ [h:11889[ٱ]للَّهُ سَيِّـَٔـاتِ مَا مَكَرُو[s[اْۖ] وَحَاقَ بِـَٔـالِ فِرْعَوْنَ س[o[ُو]ٓءُ [h:9886[ٱ]لْعَذ[p[َا][q[ب]ِ","Бас, Аллоҳ уни макрлари ёмонликларидан сақлади ва Фиръавн аҳлини ёмон азоб ўраб олди.",472,24],["ٱ[l[ل][g[نّ]َارُ يُعْرَضُونَ عَلَيْهَا غُدُو[a:11890[ًّا و]َعَشِي[a:11891[ًّاۖ و]َيَوْمَ تَقُومُ [h:10435[ٱ][l[ل]سَّاعَةُ أَ[q:11892[دْ]خِل[o[ُوٓ][s[اْ] ءَالَ فِرْعَوْنَ أَشَدَّ [h:11893[ٱ]لْعَذ[p[َا][q[ب]ِ","У оловдир. Унга эртаю кеч кўндаланг қилинурлар. соати қоим бўлганида эса: «Фиръавн аҳлини энг ашаддий азобга киритинглар», дейилур.",472,24],["وَإِذْ يَتَح[m[َا]ٓجُّونَ فِى [h:4674[ٱ][l[ل][g[نّ]َارِ فَيَقُولُ [h:11894[ٱ][l[ل]ضُّعَفَ[o[ـٰٓ]ؤُ[s[اْ] لِلَّذِينَ [h:7089[ٱ]سْتَكْبَر[o[ُوٓ][s[اْ] إِ[g[نّ]َا كُ[g[نّ]َا لَكُمْ تَبَ[f:7090[عًا ف]َهَلْ أَ[f:428[نت][w:7091[ُم م]ُّغْنُونَ عَ[g[نّ]َا نَصِي[a:1814[بًا م]ِّنَ [h:869[ٱ][l[ل][g[نّ][p[َا]رِ","Ўшанда улар дўзахда бир-бирлари ила хусумат қилурлар. Бас, заифлар мутакаббирлик қилганларга: «Албатта, биз сизга эргашувчи бўлган эдик. Энди сиз бизнинг дўзах насибамиздан бирор бўлагини даф қиласизларми?!» дерлар.",472,24],["قَالَ [h:590[ٱ]لَّذِينَ [h:4816[ٱ]سْتَكْبَر[o[ُوٓ][s[اْ] إِ[g[نّ]َا كُ[f:11895[لٌّ ف]ِيه[o[َآ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ قَ[q:298[دْ] حَكَمَ بَيْنَ [h:11896[ٱ]لْعِب[p[َا][q[د]ِ","Мутакаббирлик қилганлар: «Албатта, ҳаммамиз унинг ичидамиз. Шубҳасиз, Аллоҳ бандалар орасида ҳукм чиқариб бўлди», дерлар.",472,24],["وَقَالَ [h:614[ٱ]لَّذِينَ فِى [h:4674[ٱ][l[ل][g[نّ]َارِ لِخَزَنَةِ جَهَ[g[نّ]َمَ [h:11897[ٱ][q:4751[دْ]عُو[s[اْ] رَبَّكُمْ يُخَفِّفْ عَ[g[نّ]َا يَوْ[a:11898[مًا م]ِّنَ [h:503[ٱ]لْعَذ[p[َا][q[ب]ِ","Дўзахда турганлар жаҳаннам қўриқчиларига: «Роббингизга дуо қилинглар, биздан бирор кун азобни енгиллатсин», дедилар.",472,24],["قَال[o[ُوٓ][s[اْ] أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُك[c:11899[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِۖ قَالُو[s[اْ] بَلَىٰۚ قَالُو[s[اْ] فَ[h:11804[ٱ][q:11804[دْ]عُو[s[اْۗ] وَمَا دُعَ[o[ـٰٓ]ؤُ[s[اْ] [h:11900[ٱ]لْكَ[n[ـٰ]فِرِينَ إِلَّا فِى ضَلَ[p[ـٰ]لٍ","Улар: «Сизга Пайғамбарларингиз очиқ-ойдин ҳужжатлар билан келмаган эдиларми?!» дедилар. Булар: «Ҳа», дейишди. Улар: «Бас, дуо қилаверинглар. Кофирларнинг дуоси залолатдан бошқа нарса эмас», дедилар.",473,24],["إِ[g[نّ]َا لَنَ[f:11901[نص]ُرُ رُسُلَنَا وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا وَيَوْمَ يَقُومُ [h:11902[ٱ]لْأَشْهَ[p[ـٰ][q[د]ُ","Албатта, Биз Пайғамбарларимизга ва иймон келтирганларга бу дунё ҳаётида ва гувоҳлар турган кунда ҳам нусрат берурмиз.",473,24],["يَوْمَ لَا يَ[f:838[نف]َعُ [h:11903[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ مَعْذِرَتُهُمْۖ وَلَهُمُ [h:11904[ٱ][l[ل]لَّعْنَةُ وَلَهُمْ س[o[ُو]ٓءُ [h:6967[ٱ][l[ل]دّ[p[َا]رِ","У кунда золимларга маъзиратлари наф бермас. Уларга лаънат бўлғай ва уларга ёмон ҳовли жой бўлғай.",473,24],["وَلَقَ[q:341[دْ] ءَاتَيْنَا مُوسَى [h:11905[ٱ]لْهُدَىٰ وَأَوْرَثْنَا بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ [h:11906[ٱ]لْكِتَ[p[ـٰ][q[ب]َ","Батаҳқиқ, Биз Мусога ҳидоятни бердик ва Бани Исроилни Китобга ворис қилдик.",473,24],["هُ[a:11907[دًى و]َذِكْرَىٰ لِأُ[s[وْ]لِى [h:11555[ٱ]لْأَلْبَ[p[ـٰ][q[ب]ِ","Ақл эгаларига ҳидоятчи ва эслатма бўлсин учун.",473,24],["فَ[h:9999[ٱ]صْبِرْ إِ[g[نّ]َ وَعْدَ [h:3149[ٱ]للَّهِ حَ[a:11908[قٌّ و]َ[h:2374[ٱ]سْتَغْفِرْ لِذَ[i:11909[نۢب]ِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِ[h:1900[ٱ]لْعَشِىِّ وَ[h:1901[ٱ]لْإِ[q:1901[بْ]كَ[p[ـٰ]رِ","Бас, сабр қил. Албатта, Аллоҳнинг ваъдаси ҳақдир. Гуноҳинг учун истиғфор айт. Эртаю кеч Роббингга ҳамд ила тасбиҳ айт.",473,24],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يُجَ[n[ـٰ]دِلُونَ ف[o[ِىٓ] ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ بِغَيْرِ سُلْطَ[n[ـٰ]نٍ أَتَ[n[ـٰ]هُمْۙ إِ[f:11910[ن ف]ِى صُدُورِهِمْ إِلَّا كِ[q:11911[بْ][a:11912[رٌ م]َّا ه[c:11913[ُم ب]ِبَ[n[ـٰ]لِغِيهِۚ فَ[h:5208[ٱ]سْتَعِذْ بِ[h:32[ٱ]للَّهِۖ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:3721[ٱ][l[ل]سَّمِيعُ [h:7657[ٱ]لْبَص[p[ِي]رُ","Албатта, Аллоҳнинг оятлари ҳақида ўзларига келган ҳужжатсиз талашиб-тортишадиганларнинг дилларида кибрдан ўзга нарса йўқ. Улар унга етишгувчи эмаслар. Бас, Аллоҳдан паноҳ сўра. Албатта, Унинг Ўзи ўта эшитгувчи, ўта кўргувчи зотдир.",473,24],["لَخَلْقُ [h:11914[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ أَكْبَرُ مِنْ خَلْقِ [h:11915[ٱ][l[ل][g[نّ]َاسِ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Албатта, осмонлару ерни яратиш одамларни яратишдан каттароқдир. Лекин одамларнинг кўплари билмаслар.",473,24],["وَمَا يَسْتَوِى [h:4068[ٱ]لْأَعْمَىٰ وَ[h:4069[ٱ]لْبَصِيرُ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ وَلَا [h:11916[ٱ]لْمُس[o[ِى]ٓءُۚ قَلِيل[a:4583[اً م]َّا تَتَذَكَّر[p[ُو]نَ","Кўр билан кўрувчи баробар бўлмас. Иймон келтириб, солиҳ амаллар қилганлар билан ёмонлик қилгувчи ҳам. Жуда ҳам кам эслайсизлар.",473,24],["إِ[g[نّ]َ [h:8457[ٱ][l[ل]سَّاعَةَ لَأَتِيَ[u:11917[ةٌ ل]َّا رَيْبَ فِيهَا وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يُؤْمِن[p[ُو]نَ","Албатта, соати келгувчидир. Унда шубҳа йўқ. Лекин одамларнинг кўплари иймон келтирмаслар.",474,24],["وَقَالَ رَبُّكُمُ [h:11918[ٱ][q:11919[دْ]عُون[o[ِىٓ] أَسْتَجِ[q:11920[بْ] لَكُمْۚ إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَ[q:11921[دْ]خُلُونَ جَهَ[g[نّ]َمَ دَاخِر[p[ِي]نَ","Роббингиз: «Менга дуо қилинг, сизга ижобат қилурман. Албатта, Менинг ибодатимдан кибр қилганлар жаҳаннамга хору зор ҳолларида кирурлар», деди.",474,24],["ٱللَّهُ [h:4738[ٱ]لَّذِى جَعَلَ لَكُمُ [h:6116[ٱ]لَّيْلَ لِتَسْكُنُو[s[اْ] فِيهِ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ مُ[q:6118[بْ]صِرًاۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَذُو فَضْلٍ عَلَى [h:729[ٱ][l[ل][g[نّ]َاسِ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَشْكُر[p[ُو]نَ","Аллоҳ сизга сукунат топишингиз учун кечани, кўрсатувчи этиб кундузни қилиб берган зотдир. Албатта, Аллоҳ одамларга нисбатан фазлу карам соҳибидир. Лекин одамларнинг кўплари билмаслар.",474,24],["ذ[n[َٲ]لِكُمُ [h:4260[ٱ]للَّهُ رَبُّكُمْ خَ[n[ـٰ]لِقُ كُلِّ ش[u:11922[َىْءٍ ل]ّ[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَۖ فَأَ[g[نّ]َىٰ تُؤْفَك[p[ُو]نَ","Ана ўша Аллоҳ–Роббингиздир. У ҳар бир нарсанинг яратгувчисидир. Ундан ўзга ибодатга сазовор зот йўқ. Бас, қаёққа бурилиб кетмоқдасиз?!",474,24],["كَذ[n[َٲ]لِكَ يُؤْفَكُ [h:11923[ٱ]لَّذِينَ كَانُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ يَ[q:4008[جْ]حَد[p[ُو]نَ","Аллоҳнинг оятларини инкор қиладиганлар ана шундай бурилиб кетурлар.",474,24],["ٱللَّهُ [h:4738[ٱ]لَّذِى جَعَلَ لَكُمُ [h:87[ٱ]لْأَرْضَ قَرَا[a:11924[رًا و]َ[h:89[ٱ][l[ل]سَّم[o[َا]ٓءَ بِن[o[َا]ٓ[a:11925[ءً و]َصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَك[w:5306[ُم م]ِّنَ [h:5307[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تِۚ ذ[n[َٲ]لِكُمُ [h:4260[ٱ]للَّهُ رَبُّكُمْۖ فَتَبَارَكَ [h:9160[ٱ]للَّهُ رَبُّ [h:4750[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Аллоҳ сизга ерни қароргоҳ, осмонни том қилган ва сизларнинг сувратларингизни гўзал сувратда қилган, сизларга пок нарсалардан ризқ берган зотдир. Ана ўша Аллоҳ Роббингиздир. Бас, оламларнинг Робби Аллоҳ юксак-баракотли бўлди.",474,24],["هُوَ [h:1468[ٱ]لْحَىُّ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ فَ[h:5157[ٱ][q:5157[دْ]عُوهُ مُخْلِصِينَ لَهُ [h:4649[ٱ][l[ل]دِّينَۗ [h:11926[ٱ]لْحَمْدُ لِلَّهِ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","У зот тирикдир. Ундан ўзга ибодатга сазовор зот йўқ. Бас, Унга динни холис қилган ҳолда дуо қилинг. Оламларнинг Робби Аллоҳга ҳамдлар бўлсин.",474,24],["۞ قُلْ إِ[g[نّ]ِى نُهِيتُ أَنْ أَعْبُدَ [h:4094[ٱ]لَّذِينَ تَ[q:4040[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ لَ[g[مّ]َا ج[o[َا]ٓءَنِىَ [h:11927[ٱ]لْبَيِّنَ[n[ـٰ]تُ م[u:4098[ِن ر]َّبِّى وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ [h:687[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Сен: «Албатта, мен ўзимга Роббимдан очиқ-ойдин ҳужжатлар келган пайтда сиз илтижо этаётган нарсаларга ибодат қилишдан қайтарилганман ва оламларнинг Роббига таслим бўлишга амр этилдим», деб айт.",474,24],["هُوَ [h:153[ٱ]لَّذِى خَلَقَك[w:2530[ُم م]ِّ[f:1972[ن ت]ُرَا[f:1973[بٍ ث]ُ[g[مّ]َ م[a:7325[ِن ن]ُّ[q:7326[طْ]فَ[f:8077[ةٍ ث]ُ[g[مّ]َ مِنْ عَلَقَ[f:8909[ةٍ ث]ُ[g[مّ]َ يُخْرِجُكُمْ طِفْل[f:8914[اً ث]ُ[g[مّ]َ لِتَ[q:8915[بْ]لُغ[o[ُوٓ][s[اْ] أَشُدَّكُمْ ثُ[g[مّ]َ لِتَكُونُو[s[اْ] شُيُو[a:11928[خًاۚ و]َمِ[f:2325[نك][w:2326[ُم م]ّ[a:8916[َن ي]ُتَوَفَّىٰ مِ[f:128[ن ق]َ[q:129[بْ]لُۖ وَلِتَ[q:11929[بْ]لُغ[o[ُوٓ][s[اْ] أَجَل[a:11930[اً م]ُّسَم[a:11931[ًّى و]َلَعَلَّكُمْ تَعْقِل[p[ُو]نَ","У сизни тупроқдан, сўнгра нутфадан, сўнгра лахта қондан яратган зотдир. Сўнгра У сизни бувак ҳолингизда чиқарур. Сўнгра камолга етишингиз учун, қари бўлишингиз учун. Сизнинг ичингизда ундан олдин вафот этадиганлар ҳам бўлур. белгиланган ажалга етишингиз учундир. Шоядки ақл юритсангиз.",475,24],["هُوَ [h:153[ٱ]لَّذِى يُحْى[n[ِۦ] وَيُمِيتُۖ فَإِذَا قَضَ[o[ىٰٓ] أَمْ[f:612[رًا ف]َإِ[g[نّ]َمَا يَقُولُ لَهُ[n[ۥ] كُ[f:613[ن ف]َيَك[p[ُو]نُ","У зот тирилтирур ва ўлдирур. Қачонки бирор ишни хоҳласа, «Бўл!» дер ва у бўлур.",475,24],["أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ يُجَ[n[ـٰ]دِلُونَ ف[o[ِىٓ] ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ أَ[g[نّ]َىٰ يُصْرَف[p[ُو]نَ","Аллоҳнинг оятлари ҳақида талашиб-тортишадиганларни кўрмайсанми?! Қаёққа бурилиб кетмоқдалар?!",475,24],["ٱلَّذِينَ كَذَّبُو[s[اْ] بِ[h:2042[ٱ]لْكِتَ[n[ـٰ]بِ وَبِم[o[َآ] أَرْسَلْنَا بِه[n[ِۦ] رُسُلَنَاۖ فَسَوْفَ يَعْلَم[p[ُو]نَ","Китобни ва Биз Пайғамбарларимиз ила юборган нарсани ёлғонга чиқарганлар тезда билурлар.",475,24],["إِذِ [h:11932[ٱ]لْأَغْلَ[n[ـٰ]لُ ف[o[ِىٓ] أَعْنَ[n[ـٰ]قِهِمْ وَ[h:11933[ٱ][l[ل]سَّلَ[n[ـٰ]سِلُ يُسْحَب[p[ُو]نَ","Ўшанда улар бўйинларида кишанлар ва занжирлар ила тортилурлар.",475,24],["فِى [h:11934[ٱ]لْحَمِيمِ ثُ[g[مّ]َ فِى [h:4674[ٱ][l[ل][g[نّ]َارِ يُسْجَر[p[ُو]نَ","Ўта қайноқ сувга. Сўнгра оловда куйдирилурлар.",475,24],["ثُ[g[مّ]َ قِيلَ لَهُمْ أَيْنَ مَا كُ[f:100[نت]ُمْ تُشْرِك[p[ُو]نَ","Сўнгра уларга: «Ширк келтириб юрган нарсаларингиз қани?!",475,24],["مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِۖ قَالُو[s[اْ] ضَلُّو[s[اْ] عَ[g[نّ]َا بَل لَّمْ نَك[a:11935[ُن ن]َّ[q:7542[دْ]عُو[s[اْ] مِ[f:128[ن ق]َ[q:129[بْ]لُ شَيْـ[f:11936[ـًٔاۚ ك]َذ[n[َٲ]لِكَ يُضِلُّ [h:11866[ٱ]للَّهُ [h:11937[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Аллоҳдан ўзга» дейилди. Улар: «Биздан йўқолиб қолдилар. Йўқ. Олдин ҳеч нарсага илтижо қилмаган эдик», дедилар. Аллоҳ кофирларни шундай қилиб, залолатга кетказур.",475,24],["ذ[n[َٲ]لِك[c:11938[ُم ب]ِمَا كُ[f:100[نت]ُمْ تَفْرَحُونَ فِى [h:44[ٱ]لْأَرْضِ بِغَيْرِ [h:325[ٱ]لْحَقِّ وَبِمَا كُ[f:100[نت]ُمْ تَمْرَح[p[ُو]نَ","Мана шуларингиз ер юзида ноҳақдан шодланиб юрганингиз ва кибру ҳавога берилиб юрганингиз учундир.",475,24],["ٱ[q:278[دْ]خُل[o[ُوٓ][s[اْ] أَ[q:4047[بْ]و[n[َٲ]بَ جَهَ[g[نّ]َمَ خَ[n[ـٰ]لِدِينَ فِيهَاۖ فَبِئْسَ مَثْوَى [h:7387[ٱ]لْمُتَكَبِّر[p[ِي]نَ","Жаҳаннам эшикларидан унда абадий қолгувчи бўлган ҳолингизда киринглар. Мутакаббирларнинг жойи нақадар ёмон!",475,24],["فَ[h:9999[ٱ]صْبِرْ إِ[g[نّ]َ وَعْدَ [h:3149[ٱ]للَّهِ حَۚ[f:11939[قٌّ ف]َإِ[g[مّ]َا نُرِيَ[g[نّ]َكَ بَعْضَ [h:1943[ٱ]لَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَ[g[نّ]َكَ فَإِلَيْنَا يُرْجَع[p[ُو]نَ","Бас, сабр қил. Албатта, Аллоҳнинг ваъдаси ҳақдир. Энди Биз ёки сенга уларга ваъда қилган нарсаларимизнинг баъзиларини кўрсатамиз, ёки сени вафот эттирамиз. Бас, Бизгагина қайтарилурлар.",475,24],["وَلَقَ[q:341[دْ] أَرْسَلْنَا رُسُل[a:7017[اً م]ِّ[f:18[ن ق]َ[q:19[بْ]لِكَ مِنْه[w:1446[ُم م]َّ[f:11940[ن ق]َصَصْنَا عَلَيْكَ وَمِنْه[w:1106[ُم م]ّ[u:11941[َن ل]َّمْ نَ[q:11942[قْ]صُصْ عَلَيْكَۗ وَمَا كَانَ لِرَسُولٍ أ[a:1462[َن ي]َأْتِىَ بِـَٔـايَةٍ إِلَّا بِإِذْنِ [h:509[ٱ]للَّهِۚ فَإِذَا ج[o[َا]ٓءَ أَمْرُ [h:2832[ٱ]للَّهِ قُضِىَ بِ[h:370[ٱ]لْحَقِّ وَخَسِرَ هُنَالِكَ [h:11943[ٱ]لْمُ[q:5131[بْ]طِل[p[ُو]نَ","Батаҳқиқ, Биз сендан олдин ҳам Пайғамбарлар юборганмиз. Улардан кимнингдир қиссасини сенга айтдик ва улардан кимнингдир қиссасини сенга айтмадик. Ҳеч Пайғамбар Аллоҳнинг изнисиз оят-мўъжиза келтирган эмас. Бас, қачонки Аллоҳнинг амри келганида, ҳақ ила ҳукм чиқарилур ва ўшанда ботил иш қилиб юргувчилар зиён тортурлар.",476,24],["ٱللَّهُ [h:4738[ٱ]لَّذِى جَعَلَ لَكُمُ [h:11944[ٱ]لْأَنْعَ[n[ـٰ]مَ لِتَرْكَبُو[s[اْ] مِنْهَا وَمِنْهَا تَأْكُل[p[ُو]نَ","Аллоҳ сизларга чорва ҳайвонларини, улардан баъзиларини минишингиз учун яратди. Улардан баъзиларини ерсизлар.",476,24],["وَلَكُمْ فِيهَا مَنَ[n[ـٰ]فِعُ وَلِتَ[q:11929[بْ]لُغُو[s[اْ] عَلَيْهَا حَاجَ[f:6751[ةً ف]ِى صُدُورِكُمْ وَعَلَيْهَا وَعَلَى [h:9178[ٱ]لْفُلْكِ تُحْمَل[p[ُو]نَ","Сиз учун уларда манфаатлар бор. Ва улар устида дилларингиздаги ҳожатларга етишишингиз учундир. Уларда ва кемаларда ташилурсиз.",476,24],["وَيُرِيكُمْ ءَايَ[n[ـٰ]تِه[n[ِۦ] فَأَىَّ ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ تُ[f:11945[نك]ِر[p[ُو]نَ","Ва У зот сизларга Ўз оят-белгиларини кўрсатур. Бас, Аллоҳнинг қайси оятларини инкор қилурсизлар?!",476,24],["أَفَلَمْ يَسِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَيَ[f:6853[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6854[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْۚ كَان[o[ُوٓ][s[اْ] أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّ[a:11824[ةً و]َءَاثَا[f:11825[رًا ف]ِى [h:44[ٱ]لْأَرْضِ فَم[o[َآ] أَغْنَىٰ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Ер юзида юриб, ўзларидан олдингиларнинг оқибати қандай бўлганига назар солмайдиларми?! Улар булардан кўра қувватлироқ ва ер юзида асарлари кўпроқ бўлган эдилар. Бас, уларга касб қилган нарсалари асқотмади.",476,24],["فَلَ[g[مّ]َا ج[o[َا]ٓءَتْهُمْ رُسُلُه[c:4900[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ فَرِحُو[s[اْ] بِمَا عِ[f:5060[ند]َه[w:11946[ُم م]ِّنَ [h:634[ٱ]لْعِلْمِ وَحَاقَ بِه[w:6252[ِم م]َّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Қачонки уларга Пайғамбарлари очиқ-ойдин ҳужжатлар билан келганларида, улар ўзларидаги илм билан мақтандилар. Ва уларни ўзлари истеҳзо қилган нарса ўраб олди.",476,24],["فَلَ[g[مّ]َا رَأَوْ[s[اْ] بَأْسَنَا قَال[o[ُوٓ][s[اْ] ءَامَ[g[نّ]َا بِ[h:32[ٱ]للَّهِ وَحْدَهُ[n[ۥ] وَكَفَرْنَا بِمَا كُ[g[نّ]َا بِه[n[ِۦ] مُشْرِك[p[ِي]نَ","Қачонки азобимизни кўрганларида: «Биз Аллоҳнинг ёлғиз Ўзига иймон келтирдик ва Унга шерик қилган нарсаларимизга куфр келтирдик», дедилар.",476,24],["فَلَمْ يَكُ يَ[f:534[نف]َعُهُمْ إِيمَ[n[ـٰ]نُهُمْ لَ[g[مّ]َا رَأَوْ[s[اْ] بَأْسَنَاۖ سُ[g[نّ]َتَ [h:11947[ٱ]للَّهِ [h:4656[ٱ]لَّتِى قَ[q:298[دْ] خَلَتْ فِى عِبَادِهِ[n[ۖۦ] وَخَسِرَ هُنَالِكَ [h:11948[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Бизнинг азобимизни кўрганларидаги иймонлари уларга мафаат бера олмас эди. Аллоҳнинг бандаларига жорий бўлиб келган суннати шу. Ана ўшанда кофирлар зиён кўрдилар.",476,24]]},{"n":41,"ar":"فُصِّلَتۡ","en":"Fussilat","uz":"Фуссилат","type":"Макка","ayahs":[["ح[m[مٓ]","Ҳа-а. Мийм.",477,24],["تَ[f:11949[نز]ِي[a:11950[لٌ م]ِّنَ [h:8351[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ [h:3[ٱ][l[ل]رَّح[p[ِي]مِ","Роҳман ва Раҳийм томонидан нозил қилинган.",477,24],["كِتَ[n[ـٰ][f:11951[بٌ ف]ُصِّلَتْ ءَايَ[n[ـٰ]تُهُ[n[ۥ] قُرْءَانًا عَرَبِي[u:11952[ًّا ل]ِّقَوْ[a:1292[مٍ ي]َعْلَم[p[ُو]نَ","Биладиган қавмлар учун оятлари муфассал баён қилинган китобдир.",477,24],["بَشِي[a:622[رًا و]َنَذِي[f:11953[رًا ف]َأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَع[p[ُو]نَ","Хушхабар бергувчи ва огоҳлантиргувчи бўлган ҳолидадир. Бас, кўплари ундан юз ўгирдилар. Энди улар эшитмаслар.",477,24],["وَقَالُو[s[اْ] قُلُوبُنَا ف[o[ِىٓ] أَكِ[g[نّ]َ[a:11954[ةٍ م]ِّ[g[مّ]َا تَ[q:6404[دْ]عُون[o[َآ] إِلَيْهِ وَف[o[ِىٓ] ءَاذَانِنَا وَ[q:11955[قْ][a:11956[رٌ و]َم[i:11957[ِنۢ ب]َيْنِنَا وَبَيْنِكَ حِجَا[f:11958[بٌ ف]َ[h:11959[ٱ]عْمَلْ إِ[g[نّ]َنَا عَ[n[ـٰ]مِل[p[ُو]نَ","Улар: «Қалбларимиз сен даъват қилаётган нарсадан ғилофлардадир, қулоқларимизда оғирлик бор, сен билан бизнинг орамизда эса, парда бор. Бас, сен амалингни қилавер, биз ҳам, албатта, ўз амалимизни қилгувчилармиз», дедилар.",477,24],["قُلْ إِ[g[نّ]َم[o[َآ] أَنَا۟ بَشَ[a:7069[رٌ م]ِّثْلُكُمْ يُوحَ[o[ىٰٓ] إِلَىَّ أَ[g[نّ]َم[o[َآ] إِلَ[n[ـٰ]هُكُمْ إِلَ[n[ـٰ][a:827[هٌ و][n[َٲ]حِ[f:11960[دٌ ف]َ[h:5478[ٱ]سْتَقِيم[o[ُوٓ][s[اْ] إِلَيْهِ وَ[h:11961[ٱ]سْتَغْفِرُوهُ‌ۗ وَوَيْ[u:11962[لٌ ل]ِّلْمُشْرِك[p[ِي]نَ","Сен: «Мен ҳам сизга ўхшар башарман, холос. Менга, албатта, илоҳингиз ягона илоҳдир, дея ваҳий қилинур. Бас, Унинг Ўзигагина тўғри юзланинг ва Унга истиғфор айтинг. Мушриклар ҳолига вой бўлсин.",477,24],["ٱلَّذِينَ لَا يُؤْتُونَ [h:11963[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَه[c:4710[ُم ب]ِ[h:447[ٱ]لْأَخِرَةِ هُمْ كَ[n[ـٰ]فِر[p[ُو]نَ","Улар закотни адо этмаслар ва улар ўзлари охиратда куфр келтиргувчилардир.",477,24],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَهُمْ أَ[q:2423[جْ]رٌ غَيْرُ مَمْن[p[ُو]نٍ","Албатта, иймон келтириб, солиҳ амалларни қилганларга битмас-туганмас ажрлар бор», деб айт.",477,24],["۞ قُلْ أَئِ[g[نّ]َكُمْ لَتَكْفُرُونَ بِ[h:315[ٱ]لَّذِى خَلَقَ [h:8438[ٱ]لْأَرْضَ فِى يَوْمَيْنِ وَتَ[q:11964[جْ]عَلُونَ لَهُ[o[ۥٓ] أَ[f:96[ند]َا[f:11965[دًا‌ۚ ذ][n[َٲ]لِكَ رَبُّ [h:4750[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Сен: «Сизлар ҳақиқатан ҳам ерни икки кунда яратган зотга куфр келтиряпсизми ва Унга тенгдошлар қўшяпсизми?! Ахир У зот оламларнинг Робби-ку!",477,24],["وَجَعَلَ فِيهَا رَو[n[َٲ]سِىَ مِ[f:11665[ن ف]َوْقِهَا وَبَ[n[ـٰ]رَكَ فِيهَا وَقَدَّرَ فِيه[o[َآ] أَ[q:11966[قْ]و[n[َٲ]تَهَا ف[o[ِىٓ] أَرْبَعَةِ أَيَّا[f:11967[مٍ س]َو[o[َا]ٓ[u:11968[ءً ل]ِّلسّ[o[َا]ٓئِل[p[ِي]نَ","У зот ўшанинг устида тоғларни қилди, уни баракотли қилди ва унинг ризқини тўрт кунда ўлчовли этиб тақдир қилди. Бу сўровчилар учундир», деб айт.",477,24],["ثُ[g[مّ]َ [h:156[ٱ]سْتَوَ[o[ىٰٓ] إِلَى [h:157[ٱ][l[ل]سَّم[o[َا]ٓءِ وَهِىَ دُخَا[f:11969[نٌ ف]َقَالَ لَهَا وَلِلْأَرْضِ [h:11970[ٱ]ئْتِيَا طَوْعًا أَوْ كَرْ[f:11971[هًا ق]َالَت[o[َآ] أَتَيْنَا ط[o[َا]ٓئِع[p[ِي]نَ","Сўнгра тутун ҳолидаги осмонга юзланиб, унга ва ерга: «Икковингиз ихтиёр қилган ҳолингизда ёки мажбур бўлган ҳолингизда келинг!» деди. Икковлари: «Ихтиёр қилган ҳолимизда келдик», дедилар.",477,24],["فَقَضَ[n[ـٰ]هُ[g[نّ]َ سَ[q:158[بْ]عَ سَمَ[n[ـٰ]وَا[f:11972[تٍ ف]ِى يَوْمَيْنِ وَأَوْحَىٰ فِى كُلِّ سَم[o[َا]ٓءٍ أَمْرَهَا‌ۚ وَزَيَّ[g[نّ]َا [h:11973[ٱ][l[ل]سَّم[o[َا]ٓءَ [h:11315[ٱ][l[ل]دُّنْيَا بِمَصَ[n[ـٰ]بِيحَ وَحِفْ[f:11974[ظًا‌ۚ ذ][n[َٲ]لِكَ تَ[q:4267[قْ]دِيرُ [h:4268[ٱ]لْعَزِيزِ [h:4269[ٱ]لْعَل[p[ِي]مِ","Бас, икки кунда етти осмонни барпо этди ва ҳар бир осмонга ишини ваҳий қилди. Биз, у яқин осмонни чироқлар-ла зийнатладик ва қўридик. Бу азизу ўта илмли зотнинг ўлчовидир.",478,24],["فَإِنْ أَعْرَضُو[s[اْ] فَقُلْ أَ[f:11975[نذ]َرْتُكُمْ صَ[n[ـٰ]عِقَ[a:11976[ةً م]ِّثْلَ صَ[n[ـٰ]عِقَةِ عَا[a:11977[دٍ و]َثَم[p[ُو][q[د]َ","Бас, агар юз ўгирсалар, сен: «Мен сизларни Од ва Самудга келган чақмоққа ўхшаш чақмоқ-ла огоҳлантирдим», деб айт.",478,24],["إِذْ ج[o[َا]ٓءَتْهُمُ [h:11978[ٱ][l[ل]رُّسُلُ م[i:4612[ِنۢ ب]َيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُد[o[ُوٓ][s[اْ] إِلَّا [h:416[ٱ]للَّهَ‌ۖ قَالُو[s[اْ] لَوْ ش[o[َا]ٓءَ رَبُّنَا لَأَ[f:9182[نز]َلَ مَلَ[o[ـٰٓ]ئِكَ[f:11979[ةً ف]َإِ[g[نّ]َا بِم[o[َآ] أُرْسِلْت[c:7059[ُم ب]ِه[n[ِۦ] كَ[n[ـٰ]فِر[p[ُو]نَ","Ўшанда Пайғамбарлар уларнинг олдиларидан ҳам, орқаларидан ҳам: «Фақат Аллоҳдан ўзгага ибодат қилманглар», деб келганларида, улар: «Агар Роббимиз хоҳласа, фаришталарни тушурур эди. Албатта, биз сиз билан юборилган нарсага кофирдирмиз», дедилар.",478,24],["فَأَ[g[مّ]َا عَا[f:11980[دٌ ف]َ[h:4956[ٱ]سْتَكْبَرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ بِغَيْرِ [h:325[ٱ]لْحَقِّ وَقَالُو[s[اْ] مَنْ أَشَدُّ مِ[g[نّ]َا قُوَّةً‌ۖ أَوَلَمْ يَرَوْ[s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ [h:2537[ٱ]لَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّ[a:11981[ةً‌ۖ و]َكَانُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا يَ[q:4008[جْ]حَد[p[ُو]نَ","Од бўлса, ер юзида ноҳақдан муткаббирлик қилдилар. Улар: «Биздан қувватлироқ ким бор?!» дедилар. Уларни яратган Аллоҳ ўзларидан қувватли эканини билмасмидилар?! Улар Бизнинг оятларимизни инкор этар эдилар.",478,24],["فَأَرْسَلْنَا عَلَيْهِمْ رِي[f:11982[حًا ص]َرْصَ[f:11983[رًا ف][o[ِىٓ] أَيَّا[a:11984[مٍ ن]َّحِسَا[u:11985[تٍ ل]ِّنُذِيقَهُمْ عَذَابَ [h:6201[ٱ]لْخِزْىِ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۖ وَلَعَذَابُ [h:7000[ٱ]لْأَخِرَةِ أَخْزَىٰ‌ۖ وَهُمْ لَا يُ[f:237[نص]َر[p[ُو]نَ","Бас, Биз устларига шумлик кунларида сарсор шамолини юбордик. Буни уларга ҳаёти дунёнинг хорлик азобини тотдириш учун қилдик. Албатта, охират азоби хор қилгувчироқдир ва уларга нусрат берилмас.",478,24],["وَأَ[g[مّ]َا ثَمُودُ فَهَدَيْنَ[n[ـٰ]هُمْ فَ[h:11986[ٱ]سْتَحَبُّو[s[اْ] [h:11987[ٱ]لْعَمَىٰ عَلَى [h:4019[ٱ]لْهُدَىٰ فَأَخَذَتْهُمْ صَ[n[ـٰ]عِقَةُ [h:11988[ٱ]لْعَذَابِ [h:11989[ٱ]لْهُونِ بِمَا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Аммо Самуд бўлса, бас, Биз уларни ҳидоят қилдик. Улар эса, ҳидоятдан кўра кўрликни афзал кўрдилар. Бас, касб қилган нарсалари туфайли уларни хорлик азоби чақмоғи урди.",478,24],["وَنَجَّيْنَا [h:11990[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَكَانُو[s[اْ] يَتَّق[p[ُو]نَ","Иймон келтирганларга ва тақво қилиб юрганларга нажот бердик.",478,24],["وَيَوْمَ يُحْشَرُ أَعْد[o[َا]ٓءُ [h:11991[ٱ]للَّهِ إِلَى [h:1241[ٱ][l[ل][g[نّ]َارِ فَهُمْ يُوزَع[p[ُو]نَ","Аллоҳнинг душманлари дўзахга жамланадиган, улар тизиб қўйиладиган кунни.",478,24],["حَتَّ[o[ىٰٓ] إِذَا مَا ج[o[َا]ٓءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَ[q:11992[بْ]صَ[n[ـٰ]رُهُمْ وَجُلُودُه[c:11993[ُم ب]ِمَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Ниҳоят унга етиб келишгач, қулоқлари, кўзлари ва терилари қилиб ўтган нарсалари ҳақида уларга қарши гувоҳлик берадилар.",478,24],["وَقَالُو[s[اْ] لِجُلُودِهِمْ لِمَ شَهِ[d:11994[د]تُّمْ عَلَيْنَا‌ۖ قَال[o[ُوٓ][s[اْ] أَ[f:11995[نط]َقَنَا [h:11996[ٱ]للَّهُ [h:4738[ٱ]لَّذ[o[ِىٓ] أَ[f:11997[نط]َقَ كُلَّ ش[a:4300[َىْءٍ و]َهُوَ خَلَقَكُمْ أَوَّلَ مَرَّ[a:11998[ةٍ و]َإِلَيْهِ تُرْجَع[p[ُو]نَ","Улар териларига: «Нима учун бизга қарши гувоҳлик бердингиз?» дедилар. Улар: «Ҳар бир нарсани нутқ қилдирган Аллоҳ бизни ҳам нутқ қилдирди. У зот сизларни аввал- бошда яратган ва Унгагина қайтарилурсизлар», дедилар.",479,24],["وَمَا كُ[f:100[نت]ُمْ تَسْتَتِرُونَ أ[a:11999[َن ي]َشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَل[o[َآ] أَ[q:12000[بْ]صَ[n[ـٰ]رُكُمْ وَلَا جُلُودُكُمْ وَلَ[n[ـٰ]كِ[f:12001[ن ظ]َنَ[f:12002[نت]ُمْ أَ[g[نّ]َ [h:394[ٱ]للَّهَ لَا يَعْلَمُ كَثِي[a:3437[رًا م]ِّ[g[مّ]َا تَعْمَل[p[ُو]نَ","Сиз ўзингизга қарши қулоғингиз, кўзларингиз ва териларингиз гувоҳлик беришларидан яширинмас эдингиз. Лекин Аллоҳ қилаётган амалларингизнинг кўпини билмайди, деб гумон қилар эдингиз.",479,24],["وَذ[n[َٲ]لِكُمْ ظَ[g[نّ]ُكُمُ [h:12003[ٱ]لَّذِى ظَنَ[f:12002[نت][c:12004[ُم ب]ِرَبِّكُمْ أَرْدَ[n[ٮٰ]كُمْ فَأَصْبَحْت[w:12005[ُم م]ِّنَ [h:340[ٱ]لْخَ[n[ـٰ]سِر[p[ِي]نَ","Ана ўша Роббингиз ҳақида қилган гумонингиз сизни ҳалокатга учратди. Бас, зиёнкорлардан бўлдингиз.",479,24],["فَإ[a:12006[ِن ي]َصْبِرُو[s[اْ] فَ[h:6278[ٱ][l[ل][g[نّ]َارُ مَثْ[u:12007[وًى ل]َّهُمْ‌ۖ وَإ[a:12008[ِن ي]َسْتَعْتِبُو[s[اْ] فَمَا ه[w:10171[ُم م]ِّنَ [h:12009[ٱ]لْمُعْتَب[p[ِي]نَ","Агар сабр қилсалар, жаҳаннам уларга макондир. Агар итобни талаб қилсалар, улар итобга қайтарилувчи ҳам бўлмаслар.",479,24],["۞ وَقَيَّضْنَا لَهُمْ قُرَن[o[َا]ٓءَ فَزَيَّنُو[s[اْ] لَه[w:3531[ُم م]َّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ [h:10217[ٱ]لْقَوْلُ ف[o[ِىٓ] أُمَ[f:4671[مٍ ق]َ[q:298[دْ] خَلَتْ مِ[f:617[ن ق]َ[q:618[بْ]لِه[w:10662[ِم م]ِّنَ [h:4673[ٱ]لْجِ[g[نّ]ِ وَ[h:4418[ٱ]لْإِ[f:4418[نس]ِ‌ۖ إِ[g[نّ]َهُمْ كَانُو[s[اْ] خَ[n[ـٰ]سِر[p[ِي]نَ","Биз уларга «дўстлар» тайёрладик. Бас, ўшалар уларга олдиларидаги ва ортларидаги нарсаларни зийнатлаб кўрсатдилар ва уларга ҳам ўзларидан олдин ўтган жин ва инсдан бўлган умматлар қатори сўзи ҳақ бўлди. Албатта, улар зиёнкор бўлдилар.",479,24],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَا تَسْمَعُو[s[اْ] لِهَ[n[ـٰ]ذَا [h:12010[ٱ]لْقُرْءَانِ وَ[h:12011[ٱ]لْغَوْ[s[اْ] فِيهِ لَعَلَّكُمْ تَغْلِب[p[ُو]نَ","Куфр келтирганлар: «Бу Қуръонга қулоқ солманглар, унга халақит беринг, шоядки ғолиб бўлсангиз», дедилар.",479,24],["فَلَنُذِيقَ[g[نّ]َ [h:12012[ٱ]لَّذِينَ كَفَرُو[s[اْ] عَذَا[f:1966[بًا ش]َدِي[a:12013[دًا و]َلَنَ[q:7579[جْ]زِيَ[g[نّ]َهُمْ أَسْوَأَ [h:11701[ٱ]لَّذِى كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Бас, албатта, Биз куфр келтирганларга шиддатли азобни тоттирамиз ва, албатта, уларга қилиб юрган амалларининг энг ёмон жазосини берамиз.",479,24],["ذ[n[َٲ]لِكَ جَز[o[َا]ٓءُ أَعْد[o[َا]ٓءِ [h:12014[ٱ]للَّهِ [h:12015[ٱ][l[ل][g[نّ]َارُ‌ۖ لَهُمْ فِيهَا دَارُ [h:12016[ٱ]لْخُلْدِ‌ۖ جَز[o[َا]ٓ[i:3537[ءَۢ ب]ِمَا كَانُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا يَ[q:4008[جْ]حَد[p[ُو]نَ","Мана, Аллоҳ душманларининг жазоси дўзахдир. Уларга унда абадийлик диёри бор. Оятларимизни инкор қилганларининг жазоси шудир.",479,24],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَرُو[s[اْ] رَبَّن[o[َآ] أَرِنَا [h:12017[ٱ]لَّذَيْنِ أَضَلَّانَا مِنَ [h:4673[ٱ]لْجِ[g[نّ]ِ وَ[h:4418[ٱ]لْإِ[f:4418[نس]ِ نَ[q:12018[جْ]عَلْهُمَا تَحْتَ أَ[q:12019[قْ]دَامِنَا لِيَكُونَا مِنَ [h:12020[ٱ]لْأَسْفَل[p[ِي]نَ","Куфр келтирганлар: «Эй Роббимиз, бизни адаштирган жин ва инсдан бўлган шахсларни бизга кўрсатгин, уларни оёқларимиз остига олайлик, токи улар энг пастлардан бўлсинлар», дедилар.",479,24],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ قَالُو[s[اْ] رَبُّنَا [h:9034[ٱ]للَّهُ ثُ[g[مّ]َ [h:12021[ٱ]سْتَقَ[n[ـٰ]مُو[s[اْ] تَتَنَزَّلُ عَلَيْهِمُ [h:12022[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ أَلَّا تَخَافُو[s[اْ] وَلَا تَحْزَنُو[s[اْ] وَأَ[q:12023[بْ]شِرُو[s[اْ] بِ[h:12024[ٱ]لْجَ[g[نّ]َةِ [h:12025[ٱ]لَّتِى كُ[f:100[نت]ُمْ تُوعَد[p[ُو]نَ","Албатта, «Роббимиз Аллоҳ» деган, сўнгра мустақийм бўлганларнинг устиларидан фаришталар: «Қўрқманглар, маҳзун ҳам бўлманглар, ўзингизга ваъда қилинган жаннат хушхабарини қабул қилинглар.",480,24],["نَحْنُ أَوْلِي[o[َا]ٓؤُكُمْ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا وَفِى [h:1108[ٱ]لْأَخِرَةِ‌ۖ وَلَكُمْ فِيهَا مَا تَشْتَه[o[ِىٓ] أَ[f:6579[نف]ُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّع[p[ُو]نَ","Биз ҳаёти дунёда ҳам, охиратда ҳам сизларнинг дўстларингиздирмиз. Сизга уда кўнглингиз иштаҳа қилган нарса бордир ва сизга унда орзу қилинган нарсангиз бордир.",480,24],["نُزُل[a:2524[اً م]ِّنْ غَفُو[u:12026[رٍ ر]َّح[p[ِي]مٍ","Бу ўта мағфиратли ва ўта раҳмли зотдан зиёфатдир», деб тушарлар.",480,24],["وَمَنْ أَحْسَنُ قَوْل[a:12027[اً م]ِّ[g[مّ]َ[f:12028[ن د]َع[o[َآ] إِلَى [h:1637[ٱ]للَّهِ وَعَمِلَ صَ[n[ـٰ]لِ[a:12029[حًا و]َقَالَ إِ[g[نّ]َنِى مِنَ [h:6135[ٱ]لْمُسْلِم[p[ِي]نَ","Аллоҳга даъват қилган, солиҳ амалларни қилган ва «Албатта, мен мусулмонларданман!» деган, кишидан ҳам гўзал сўзли ким бор?!",480,24],["وَلَا تَسْتَوِى [h:12030[ٱ]لْحَسَنَةُ وَلَا [h:12031[ٱ][l[ل]سَّيِّئَةُ‌ۚ [h:12032[ٱ][q:9286[دْ]فَعْ بِ[h:4526[ٱ]لَّتِى هِىَ أَحْسَنُ فَإِذَا [h:10094[ٱ]لَّذِى بَيْنَكَ وَبَيْنَهُ[n[ۥ] عَد[n[َٲ]وَ[f:12033[ةٌ ك]َأَ[g[نّ]َهُ[n[ۥ] وَلِىٌّ حَم[p[ِي]مٌ","Яхшилик билан ёмонлик баробар бўлмас. Сен яхшилик бўлган нарса ила даф қил. Кўрибсанки, сен билан орасида адовати бор кимса, худди содиқ дўстдек бўлур.",480,24],["وَمَا يُلَقَّ[n[ـٰ]ه[o[َآ] إِلَّا [h:778[ٱ]لَّذِينَ صَبَرُو[s[اْ] وَمَا يُلَقَّ[n[ـٰ]ه[o[َآ] إِلَّا ذُو حَظٍّ عَظ[p[ِي]مٍ","Унга фақат сабр қилганларгина эришур. Унга фақат улуғ насиба эгаси бўлганларгина эришур.",480,24],["وَإِ[g[مّ]َا يَ[f:5206[نز]َغَ[g[نّ]َكَ مِنَ [h:1870[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ نَزْ[f:5207[غٌ ف]َ[h:5208[ٱ]سْتَعِذْ بِ[h:32[ٱ]للَّهِ‌ۖ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:3721[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Агар сени шайтон васвасасидан бир васваса тутса, Аллоҳдан паноҳ сўра. Албатта, У зот ўта эшитгувчи ва ўта билгувчи зотдир.",480,24],["وَمِنْ ءَايَ[n[ـٰ]تِهِ [h:12034[ٱ]لَّيْلُ وَ[h:12035[ٱ][l[ل][g[نّ]َهَارُ وَ[h:8955[ٱ][l[ل]شَّمْسُ وَ[h:8956[ٱ]لْقَمَرُ‌ۚ لَا تَسْجُدُو[s[اْ] لِلشَّمْسِ وَلَا لِلْقَمَرِ وَ[h:9126[ٱ]سْجُدُو[s[اْ] لِلَّهِ [h:3912[ٱ]لَّذِى خَلَقَهُ[g[نّ]َ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ إِيَّاهُ تَعْبُد[p[ُو]نَ","Кечаю кундуз, қуёшу ой Унинг оят-белгиларидан. Бас, қуёшга ҳам, ойга ҳам сажда қилманглар. Уларни яратган Аллоҳга сажда қилинг. Гар сиз Унгагина ибодат қилмоқчи бўлсангиз.",480,24],["فَإِنِ [h:12036[ٱ]سْتَكْبَرُو[s[اْ] فَ[h:2514[ٱ]لَّذِينَ عِ[f:264[ند]َ رَبِّكَ يُسَبِّحُونَ لَهُ[n[ۥ] بِ[h:1622[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ وَهُمْ لَا يَسْــَٔمُ[p[و]نَ ۩","Агар улар мутакаббирлик қилсалар. Роббингнинг ҳузуридагилар Унга кечасию кундузи тасбиҳ айтурлар. Улар малол олмаслар.",480,24],["وَمِنْ ءَايَ[n[ـٰ]تِه[o[ِۦٓ] أَ[g[نّ]َكَ تَرَى [h:12037[ٱ]لْأَرْضَ خَ[n[ـٰ]شِعَ[f:12038[ةً ف]َإِذ[o[َآ] أَ[f:515[نز]َلْنَا عَلَيْهَا [h:8919[ٱ]لْم[o[َا]ٓءَ [h:8920[ٱ]هْتَزَّتْ وَرَبَتْ‌ۚ إِ[g[نّ]َ [h:10272[ٱ]لَّذ[o[ِىٓ] أَحْيَاهَا لَمُحْىِ [h:10519[ٱ]لْمَوْتَ[o[ىٰٓ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Яна Унинг оят-белгиларидан, ерни қақраган ҳолда кўришингдир. Бас, Биз унинг устидан сув тушурсак, у қимирлар ва ўсадир. Уни тирилтирган зот, албатта, ўликларни ҳам тирилтиргувчидир. Албатта, У зот ҳар бир нарсага қодирдир.",481,24],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يُلْحِدُونَ ف[o[ِىٓ] ءَايَ[n[ـٰ]تِنَا لَا يَخْفَوْنَ عَلَيْن[o[َآ‌ۗ] أَفَم[a:12039[َن ي]ُلْقَىٰ فِى [h:4674[ٱ][l[ل][g[نّ]َارِ خَيْرٌ أ[w:3110[َم م]ّ[a:12040[َن ي]َأْت[o[ِىٓ] ءَامِ[a:12041[نًا ي]َوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۚ [h:12042[ٱ]عْمَلُو[s[اْ] مَا شِئْتُمْ‌ۖ إِ[g[نّ]َهُ[n[ۥ] بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","Албатта, оятларимиз ҳақида эгрилик қиладиганлар Бизга махфий бўлиб қолмаслар. Дўзахга ташланадиган одам яхшими ёки қиёмат куни омон ҳолида келадиган одамми?! Нимани хоҳласангиз, қилаверинг. Албатта, У зот нима қилаётганингизни кўриб тургувчидир.",481,24],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِ[h:12043[ٱ][l[ل]ذِّكْرِ لَ[g[مّ]َا ج[o[َا]ٓءَهُمْ‌ۖ وَإِ[g[نّ]َهُ[n[ۥ] لَكِتَ[n[ـٰ]بٌ عَز[p[ِي]زٌ","Албатта, ўзларига Зикр келганда унга куфр келтирганлар... Албатта, У азиз китобдир.",481,24],["لَّا يَأْتِيهِ [h:12044[ٱ]لْبَ[n[ـٰ]طِلُ م[i:4612[ِنۢ ب]َيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِه[n[ِۦ]‌ۖ تَ[f:11949[نز]ِي[a:12045[لٌ م]ِّنْ حَكِيمٍ حَم[p[ِي][q[د]ٍ","Унинг олдидан ҳам, ортидан ҳам ботил келмас. У ўта ҳикматли ва ўта мақталган зотнинг туширганидир.",481,24],["مَّا يُقَالُ لَكَ إِلَّا مَا قَ[q:298[دْ] قِيلَ لِلرُّسُلِ مِ[f:18[ن ق]َ[q:19[بْ]لِكَ‌ۚ إِ[g[نّ]َ رَبَّكَ لَذُو مَغْفِرَ[a:12046[ةٍ و]َذُو عِقَابٍ أَل[p[ِي]مٍ","Сенга айтилаётган нарсаки бор, батаҳқиқ, сендан олдинги Пайғамбарларга ҳам айтилгандир. Албатта, Роббинг мағфират эгасидир ва аламли азоб эгасидир.",481,24],["وَلَوْ جَعَلْنَ[n[ـٰ]هُ قُرْءَانًا أَعْجَمِي[u:12047[ًّا ل]َّقَالُو[s[اْ] لَوْلَا فُصِّلَتْ ءَايَ[n[ـٰ]تُهُ[o[ۥٓ‌ۖ] ءَا۠عْجَمِ[a:12048[ىٌّ۬ و]َعَرَبِ[f:12049[ىٌّ‌ۗ ق]ُلْ هُوَ لِلَّذِينَ ءَامَنُو[s[اْ] هُ[a:12050[دًى و]َشِف[o[َا]ٓ[a:12051[ءٌ‌ۖ و]َ[h:37[ٱ]لَّذِينَ لَا يُؤْمِنُونَ ف[o[ِىٓ] ءَاذَانِهِمْ وَ[q:11955[قْ][a:12052[رٌ و]َهُوَ عَلَيْهِمْ عَمًى‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ يُنَادَوْنَ م[a:9578[ِن م]َّكَا[i:9579[نِۭ ب]َع[p[ِي][q[د]ٍ","Агар Биз уни ажамийча Қуръон қилганимизда, албатта: «Унинг оятлари муфассал баён қилинганида эди. Арабийга ажамчами?!» дер эдилар. Сен: «У иймон келтирганлар учун ҳидоят ва шифодир. Иймон келтирмайдиганларнинг қулоқларида оғирлик бордир. У улар учун кўрликдир. Улар узоқ макондан чақирилаётганлардир», деб айт.",481,24],["وَلَقَ[q:341[دْ] ءَاتَيْنَا مُوسَى [h:257[ٱ]لْكِتَ[n[ـٰ]بَ فَ[h:6512[ٱ]خْتُلِفَ فِيهِ‌ۗ وَلَوْلَا كَلِمَ[f:5989[ةٌ س]َبَقَتْ م[u:770[ِن ر]َّبِّكَ لَقُضِىَ بَيْنَهُمْ‌ۚ وَإِ[g[نّ]َهُمْ لَفِى شَ[a:3275[كٍّ م]ِّنْهُ مُر[p[ِي][q[ب]ٍ","Батаҳқиқ, Биз Мусога китобни бердик. Бас, у ҳақида ихтилоф қилинди. Агар Роббинг томонидан олдин сўз ўтмаганида, ораларида, албатта, ҳукм чиқариларди. Албатта, улар у ҳақда гумонли шакдадирлар.",481,24],["مَّنْ عَمِلَ صَ[n[ـٰ]لِ[f:12053[حًا ف]َلِنَفْسِه[n[ِۦ]‌ۖ وَمَنْ أَس[o[َا]ٓءَ فَعَلَيْهَا‌ۗ وَمَا رَبُّكَ بِظَلَّ[n[ـٰ][u:2466[مٍ ل]ِّلْعَب[p[ِي][q[د]ِ","Ким солиҳ амал қилса, ўзига фойда. Ким ёмонлик қилса, ўзига зарар. Роббинг бандаларга зулм қилгувчи эмас.",481,24],["۞ إِلَيْهِ يُرَدُّ عِلْمُ [h:10616[ٱ][l[ل]سَّاعَةِ‌ۚ وَمَا تَخْرُجُ مِ[f:12054[ن ث]َمَر[n[َٲ][a:12055[تٍ م]ِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُ[f:1867[نث]َىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِه[n[ِۦ]‌ۚ وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَك[o[َا]ٓءِى قَال[o[ُوٓ][s[اْ] ءَاذَ[g[نّ]َ[n[ـٰ]كَ مَا مِ[g[نّ]َا مِ[f:12056[ن ش]َه[p[ِي][q[د]ٍ","Соат илми Унинг Ўзигагина қайтарилур. Барча меваларнинг гулкосаларидан чиқиши ҳам, ҳар бир урғочининг нимага ҳомиладор бўлиши ҳам, нимани туғиши ҳам фақат Унинг илми ила бўлур. У зот уларга: «Менинг шерикларим қани?!» деб нидо қиладиган кунда, улар: «Биз Сенга билдирамизки, бунга биздан бирорта гувоҳ йўқ», дерлар.",482,25],["وَضَلَّ عَنْه[w:3985[ُم م]َّا كَانُو[s[اْ] يَ[q:1240[دْ]عُونَ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ وَظَ[g[نّ]ُو[s[اْ] مَا لَه[w:1812[ُم م]ّ[a:7093[ِن م]َّح[p[ِي]صٍ","Ва улардан илгари илтижо қилиб юрган нарсалари ғойиб бўлди. Улар ўзларига қочар жой йўқлигига тўла ишондилар.",482,25],["لَّا يَسْــَٔمُ [h:12057[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ مِ[f:12058[ن د]ُع[o[َا]ٓءِ [h:12059[ٱ]لْخَيْرِ وَإ[a:12060[ِن م]َّسَّهُ [h:7875[ٱ][l[ل]شَّرُّ فَيَــُٔو[f:12061[سٌ ق]َن[p[ُو][q[ط]ٌ","Инсон яхшилик тилашни ҳеч малол олмас. Агар уни ёмонлик тутса, у умидсиз тушкундир.",482,25],["وَلَئِنْ أَذَ[q:6256[قْ]نَ[n[ـٰ]هُ رَحْمَ[a:11254[ةً م]ِّ[g[نّ]َا م[i:146[ِنۢ ب]َعْدِ ضَرّ[o[َا]ٓءَ مَسَّتْهُ لَيَقُولَ[g[نّ]َ هَ[n[ـٰ]ذَا لِى وَم[o[َآ] أَظُ[g[نّ]ُ [h:8071[ٱ][l[ل]سَّاعَةَ ق[o[َا]ٓئِمَ[a:8072[ةً و]َلَئ[u:12062[ِن ر]ُّجِعْتُ إِلَىٰ رَبّ[o[ِىٓ] إِ[g[نّ]َ لِى عِ[f:719[ند]َهُ[n[ۥ] لَلْحُسْنَىٰ‌ۚ فَلَنُنَبِّئَ[g[نّ]َ [h:12063[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِمَا عَمِلُو[s[اْ] وَلَنُذِيقَ[g[نّ]َه[w:12064[ُم م]ِّنْ عَذَابٍ غَل[p[ِي]ظٍ","Агар Биз унга уни тутган зарардан сўнг Ўзимиздан раҳмат тоттирсак, албатта, у: «Бу меникидир. Мен соати қоим бўладир, деб ўйламасман. Агар Роббимга қайтарилсам, албатта, мен учун Унинг ҳузурида гўзал бордир», дер. Бас, албатта, куфр келтирганларга қилган амаллари хабарини берурмиз. Албатта, уларга оғир азобдан тоттирурмиз.",482,25],["وَإِذ[o[َآ] أَنْعَمْنَا عَلَى [h:7873[ٱ]لْإِ[f:7874[نس]َ[n[ـٰ]نِ أَعْرَضَ وَنَـَٔـا بِجَانِبِه[n[ِۦ] وَإِذَا مَسَّهُ [h:7875[ٱ][l[ل]شَّرُّ فَذُو دُع[o[َا]ٓءٍ عَر[p[ِي]ضٍ","Қачон инсонга неъмат берсак, у юз ўгирар ва ёнбоши ила узоқлашар. Қачон уни ёмонлик тутса, бас, у узундан-узоқ дуо эгасидир.",482,25],["قُلْ أَرَءَيْتُمْ إِ[f:2594[ن ك]َانَ مِنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ ثُ[g[مّ]َ كَفَرْت[c:12065[ُم ب]ِه[n[ِۦ] مَنْ أَضَلُّ مِ[g[مّ]َنْ هُوَ فِى شِقَا[i:900[قِۭ ب]َع[p[ِي][q[د]ٍ","Сен: «Менга айтинглар-чи, агар у Аллоҳнинг ҳузуридан бўлса-ю, сиз унга куфр келтириб юрган бўлсангиз. Хўш, узоқ тортишувда бўлганлардан ҳам адашганроқ ким бор?!» деб айт.",482,25],["سَنُرِيهِمْ ءَايَ[n[ـٰ]تِنَا فِى [h:12066[ٱ]لْأَفَاقِ وَف[o[ِىٓ] أَ[f:568[نف]ُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَ[g[نّ]َهُ [h:137[ٱ]لْحَقُّ‌ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَ[g[نّ]َهُ[n[ۥ] عَلَىٰ كُلِّ ش[f:3903[َىْءٍ ش]َه[p[ِي][q[د]ٌ","Биз уларга ҳам уфқлардаги, ҳам ўз нафсларидаги оят-белгиларимизни кўрсатамиз. Токи уларга Унинг ҳақлиги равшан бўлсин. Сенинг Роббинг ҳар бир нарсага шоҳид эканлиги кифоя қилмасмиди?!",482,25],["أَل[o[َآ] إِ[g[نّ]َهُمْ فِى مِرْيَ[a:10660[ةٍ م]ّ[u:12067[ِن ل]ِّق[o[َا]ٓءِ رَبِّهِمْ‌ۗ أَل[o[َآ] إِ[g[نّ]َهُ[n[ۥ] بِكُلِّ ش[a:12068[َىْءٍ م]ُّح[p[ِي][q[ط]ُۢ","Огоҳ бўлинглар. Албатта, улар Роббиларига рўбарў бўлишдан шакдадирлар. Огоҳ бўлинглар. Албатта, У зот ҳар бир нарсани ихота қилгувчидир.",482,25]]},{"n":42,"ar":"الشُّورَىٰ","en":"Ash-Shura","uz":"Шуро","type":"Макка","ayahs":[["ح[m[مٓ]","Ҳа-а. Мийм.",483,25],["[m[عٓ][m[سٓ][m[قٓ]","Айн. Сийн. Қо-оф.",483,25],["كَذ[n[َٲ]لِكَ يُوح[o[ِىٓ] إِلَيْكَ وَإِلَى [h:11747[ٱ]لَّذِينَ مِ[f:18[ن ق]َ[q:19[بْ]لِكَ [h:12069[ٱ]للَّهُ [h:9894[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Азизу ўта ҳикматли бўлмиш Аллоҳ сенга ва сендан аввалгиларга мана шундай ваҳий қилур.",483,25],["لَهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۖ وَهُوَ [h:1475[ٱ]لْعَلِىُّ [h:1476[ٱ]لْعَظ[p[ِي]مُ","Осмондаги нарсалар ва ердаги нарслар уникидир. У зот юксак ва улуғдир.",483,25],["تَكَادُ [h:8420[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تُ يَتَفَطَّرْنَ مِ[f:12070[ن ف]َوْقِهِ[g[نّ]َ‌ۚ وَ[h:1146[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَ[f:5428[ن ف]ِى [h:44[ٱ]لْأَرْضِ‌ۗ أَل[o[َآ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ هُوَ [h:6822[ٱ]لْغَفُورُ [h:6228[ٱ][l[ل]رَّح[p[ِي]مُ","Осмонлар уст томонларидан ёрилиб кетай дейдир. Фаришталар эса, Роббилари ҳамди ила тасбиҳ айтурлар ва ер юзидаги кимсаларга истиғфор сўрарлар. Огоҳ бўлингким, албатта, Аллоҳ ўта мағфиратли ва ўта раҳмли зотдир.",483,25],["وَ[h:9999[ٱ]لَّذِينَ [h:5828[ٱ]تَّخَذُو[s[اْ] مِ[f:3136[ن د]ُونِه[o[ِۦٓ] أَوْلِي[o[َا]ٓءَ [h:12071[ٱ]للَّهُ حَفِيظٌ عَلَيْهِمْ وَم[o[َآ] أَ[f:169[نت]َ عَلَيْه[c:4316[ِم ب]ِوَك[p[ِي]لٍ","Ундан ўзга «дўстлар» тутганларга Аллоҳ кузатгувчидир. Сен уларга вакил эмассан",483,25],["وَكَذ[n[َٲ]لِكَ أَوْحَيْن[o[َآ] إِلَيْكَ قُرْءَانًا عَرَبِي[u:12072[ًّا ل]ِّتُ[f:4582[نذ]ِرَ أُ[g[مّ]َ [h:4240[ٱ]لْقُرَىٰ وَمَنْ حَوْلَهَا وَتُ[f:8431[نذ]ِرَ يَوْمَ [h:12073[ٱ]لْجَمْعِ لَا رَيْبَ فِيهِ‌ۚ فَرِي[f:12074[قٌ ف]ِى [h:12075[ٱ]لْجَ[g[نّ]َةِ وَفَرِي[f:12076[قٌ ف]ِى [h:12077[ٱ][l[ل]سَّع[p[ِي]رِ","Ана шундай қилиб, Биз сенга шаҳарларнинг онасини ва унинг атрофини огоҳлантиришинг учун, бўлишида ҳеч шубҳа йўқ жамлаш кунидан огоҳлантиришинг учун арабий Қуръонни юбордик. Бир гуруҳ жаннатда, бир гуруҳ дўзахда.",483,25],["وَلَوْ ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ لَجَعَلَهُمْ أُ[g[مّ]َ[a:1159[ةً و][n[َٲ]حِدَ[a:3601[ةً و]َلَ[n[ـٰ]ك[a:12078[ِن ي]ُ[q:8947[دْ]خِلُ م[a:476[َن ي]َش[o[َا]ٓءُ فِى رَحْمَتِه[n[ِۦ]‌ۚ وَ[h:12079[ٱ][l[ل]ظَّ[n[ـٰ]لِمُونَ مَا لَه[w:1812[ُم م]ّ[a:557[ِن و]َلِ[a:558[ىٍّ و]َلَا نَص[p[ِي]رٍ","Агар Аллоҳ хоҳлаганида, албатта, уларни бир уммат қилар эди. Лекин У зот хоҳлаган кишини Ўз раҳматига киритур. Золимларга эса, ҳеч бир дўст ҳам, ёрдам берувчи ҳам йўқдир.",483,25],["أَمِ [h:8702[ٱ]تَّخَذُو[s[اْ] مِ[f:3136[ن د]ُونِه[o[ِۦٓ] أَوْلِي[o[َا]ٓءَ‌ۖ فَ[h:591[ٱ]للَّهُ هُوَ [h:12080[ٱ]لْوَلِىُّ وَهُوَ يُحْىِ [h:8924[ٱ]لْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Ёки улар ундан бошқа «дўстлар» тутдиларми?! Бас, Аллоҳнинг Ўзигина дўстдир. У зот ўликларни тирилтирур. Узот ҳар бир нарсага қодирдир.",483,25],["وَمَا [h:12081[ٱ]خْتَلَفْتُمْ فِيهِ مِ[f:2103[ن ش][f:12082[َىْءٍ ف]َحُكْمُهُ[o[ۥٓ] إِلَى [h:1637[ٱ]للَّهِ‌ۚ ذ[n[َٲ]لِكُمُ [h:4260[ٱ]للَّهُ رَبِّى عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُن[p[ِي][q[ب]ُ","«Бирор нарсада ихтилоф қилсангиз, унинг ҳукми Аллоҳдадир. Ана ўша Аллоҳ Роббимдир. Унгагина таваккал қилдим ва Унгагина қайтурман».",483,25],["فَاطِرُ [h:12083[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ جَعَلَ لَك[w:556[ُم م]ِّنْ أَ[f:1329[نف]ُسِكُمْ أَزْو[n[َٲ][a:12084[جًا و]َمِنَ [h:4470[ٱ]لْأَنْعَ[n[ـٰ]مِ أَزْو[n[َٲ][a:12085[جًا‌ۖ ي]َذْرَؤُكُمْ فِيهِ‌ۚ لَيْسَ كَمِثْلِه[n[ِۦ] ش[a:12086[َىْءٌ‌ۖ و]َهُوَ [h:709[ٱ][l[ل]سَّمِيعُ [h:7657[ٱ]لْبَص[p[ِي]رُ","У осмонлару ерни йўқдан бор қилгувчи зотдир. У сизларга ўз жинсингиздан жуфтлар яратди. Чорва ҳайвонларини ҳам жуфт қилиб яратди. У зот сизни ўша асосида кўпайтирур. У зотга ўхшаш ҳеч нарса йўқдир. У зот ўта эшитгувчи, ўта кўргувчи зотдир.",484,25],["لَهُ[n[ۥ] مَقَالِيدُ [h:11745[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ يَ[q:6968[بْ]سُطُ [h:6969[ٱ][l[ل]رِّزْقَ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيَ[q:6970[قْ]دِرُ‌ۚ إِ[g[نّ]َهُ[n[ۥ] بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","Осмонлару ер калитлари Уникидир. У хоҳлаган одамига ризқни кенг ёки тор қилур. Зотан у барча нарсани ўта билгувчи зотдир.",484,25],["۞ شَرَعَ لَك[w:1578[ُم م]ِّنَ [h:12087[ٱ][l[ل]دِّينِ مَا وَصَّىٰ بِه[n[ِۦ] نُو[a:12088[حًا و]َ[h:4765[ٱ]لَّذ[o[ِىٓ] أَوْحَيْن[o[َآ] إِلَيْكَ وَمَا وَصَّيْنَا بِه[o[ِۦٓ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَمُوسَىٰ وَعِيسَ[o[ىٰٓ‌ۖ] أَنْ أَقِيمُو[s[اْ] [h:12089[ٱ][l[ل]دِّينَ وَلَا تَتَفَرَّقُو[s[اْ] فِيهِ‌ۚ كَبُرَ عَلَى [h:12090[ٱ]لْمُشْرِكِينَ مَا تَ[q:5192[دْ]عُوهُمْ إِلَيْهِ‌ۚ [h:12091[ٱ]للَّهُ يَ[q:2454[جْ]تَب[o[ِىٓ] إِلَيْهِ م[a:476[َن ي]َش[o[َا]ٓءُ وَيَهْد[o[ِىٓ] إِلَيْهِ م[a:11803[َن ي]ُن[p[ِي][q[ب]ُ","У зот сизларга дин этиб Ўзи Нуҳга васият қилган ва сенга ваҳий қилган нарсамизни ҳамда Иброҳим, Мусо ва Ийсоларга васият қилган нарсамизни шариат қилди. «Динни барпо қилингиз ва унда тафриқага тушмангиз», деди. Мушрикларга сен уларни даъват қилган нарса оғир келди. Аллоҳ Ўзи хоҳлаган кишисини танлаб олур ва У Ўзигагина илтижо этгувчи кишини ҳидоят қилур.",484,25],["وَمَا تَفَرَّق[o[ُوٓ][s[اْ] إِلَّا م[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَهُمُ [h:1804[ٱ]لْعِلْمُ بَغْي[i:1169[َۢا ب]َيْنَهُمْ‌ۚ وَلَوْلَا كَلِمَ[f:5989[ةٌ س]َبَقَتْ م[u:770[ِن ر]َّبِّكَ إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَم[u:12092[ًّى ل]َّقُضِىَ بَيْنَهُمْ‌ۚ وَإِ[g[نّ]َ [h:754[ٱ]لَّذِينَ أُورِثُو[s[اْ] [h:12093[ٱ]لْكِتَ[n[ـٰ]بَ م[i:1453[ِنۢ ب]َعْدِهِمْ لَفِى شَ[a:3275[كٍّ م]ِّنْهُ مُر[p[ِي][q[ب]ٍ","Улар фақат ўзларига илм келгандан кейингина, ўзаро ҳасад-адоват қилишиб тафриқага тушдилар. Агар Роббингдан маълум муддатгача ҳақида сўз ўтган бўлмаганида, улар орасида албатта ҳукм чиқарилган бўлур эди. Албатта, улардан кейин китобга ворис қилинганлар у ҳақида шак-шубҳададирлар.",484,25],["فَلِذ[n[َٲ]لِكَ فَ[h:306[ٱ][q:306[دْ]عُ‌ۖ وَ[h:12094[ٱ]سْتَقِمْ كَم[o[َآ] أُمِرْتَ‌ۖ وَلَا تَتَّبِعْ أَهْو[o[َا]ٓءَهُمْ‌ۖ وَقُلْ ءَامَ[f:6185[نت]ُ بِم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ مِ[f:2060[ن ك]ِتَ[n[ـٰ][a:12095[بٍ‌ۖ و]َأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ‌ۖ [h:12096[ٱ]للَّهُ رَبُّنَا وَرَبُّكُمْ‌ۖ لَن[o[َآ] أَعْمَ[n[ـٰ]لُنَا وَلَكُمْ أَعْمَ[n[ـٰ]لُكُمْ‌ۖ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ‌ۖ [h:12097[ٱ]للَّهُ يَ[q:3861[جْ]مَعُ بَيْنَنَا‌ۖ وَإِلَيْهِ [h:3461[ٱ]لْمَص[p[ِي]رُ","Бас, шунинг учун ҳам даъват қил, ўзингга амр қилинганидек, мустақим тур ва уларнинг ҳавои нафсларига эргашма ҳамда: «Мен Аллоҳ нозил қилган ҳар бир китобга иймон келтирдим ва орангизда адолат ўрнатишга амр қилиндим. Аллоҳ бизнинг Роббимиз, сизнинг ҳам Роббингиз. Бизнинг амалларимиз ўзимиз учун, сизнинг амалларингиз ўзингиз учун. Биз билан сизнинг орамизда жанжал йўқ. Аллоҳ бизларни жамлайди ва қайтиш ёлғиз Унинг Ўзигадир», деб айт.",484,25],["وَ[h:9999[ٱ]لَّذِينَ يُح[m[َا]ٓجُّونَ فِى [h:714[ٱ]للَّهِ م[i:146[ِنۢ ب]َعْدِ مَا [h:12098[ٱ]سْتُجِيبَ لَهُ[n[ۥ] حُجَّتُهُمْ دَاحِضَةٌ عِ[f:264[ند]َ رَبِّهِمْ وَعَلَيْهِمْ غَضَ[a:12099[بٌ و]َلَهُمْ عَذَا[f:1727[بٌ ش]َد[p[ِي][q[د]ٌ","Аллоҳ ҳақида Унга ижобат қилинганидан кейин ҳам талашиб-тортишадиганларнинг ҳужжатлари Роббилари ҳузурида ботилдир, уларга ғазаб бордир ва уларга шиддатли азоб бордир.",485,25],["ٱللَّهُ [h:4738[ٱ]لَّذ[o[ِىٓ] أَ[f:471[نز]َلَ [h:4228[ٱ]لْكِتَ[n[ـٰ]بَ بِ[h:370[ٱ]لْحَقِّ وَ[h:4528[ٱ]لْمِيزَانَ‌ۗ وَمَا يُ[q:10898[دْ]رِيكَ لَعَلَّ [h:10899[ٱ][l[ل]سَّاعَةَ قَر[p[ِي][q[ب]ٌ","Аллоҳ ҳақ ила китобни ва тарозуни нозил қилган зотдир. Қаердан билурсан, эҳтимол соати яқиндир!",485,25],["يَسْتَعْجِلُ بِهَا [h:12100[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِهَا‌ۖ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَ[g[نّ]َهَا [h:12101[ٱ]لْحَقُّ‌ۗ أَل[o[َآ] إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يُمَارُونَ فِى [h:12102[ٱ][l[ل]سَّاعَةِ لَفِى ضَلَ[n[ـٰ][i:7043[لِۭ ب]َع[p[ِي][q[د]ٍ","Уга иймон келтирмайдиганлар унинг тезлашини истарлар, иймон келтирганлар эса, ундан қўрқувчидирлар, зотан унинг шубҳасиз ҳақ эканини билурлар. Огоҳ бўлинг! Албатта, соати ҳақида шубҳа қилгувчилар йироқ залолатдадирлар.",485,25],["ٱللَّهُ لَطِي[i:12103[فُۢ ب]ِعِبَادِه[n[ِۦ] يَرْزُقُ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۖ وَهُوَ [h:12104[ٱ]لْقَوِىُّ [h:6410[ٱ]لْعَز[p[ِي]زُ","Аллоҳ бандаларига лутфлидир. У хоҳлаган кишига ризқ берур. У зот кучлигу азиздир.",485,25],["مَ[f:506[ن ك]َانَ يُرِيدُ حَرْثَ [h:12105[ٱ]لْأَخِرَةِ نَزِ[q:12106[دْ] لَهُ[n[ۥ] فِى حَرْثِه[n[ِۦ]‌ۖ وَمَ[f:975[ن ك]َانَ يُرِيدُ حَرْثَ [h:12107[ٱ][l[ل]دُّنْيَا نُؤْتِه[n[ِۦ] مِنْهَا وَمَا لَهُ[n[ۥ] فِى [h:536[ٱ]لْأَخِرَةِ م[a:12108[ِن ن]َّص[p[ِي][q[ب]ٍ","Ким охират ҳосилини истаса, Биз унга ҳосилини зиёда қилиб берурмиз. Ким дунё ҳосилини истаса, Биз унга ўшандан берурмиз ва унга охиратда бирон насиба бўлмас.",485,25],["أَمْ لَهُمْ شُرَكَ[o[ـٰٓ]ؤُ[s[اْ] شَرَعُو[s[اْ] لَه[w:6026[ُم م]ِّنَ [h:12087[ٱ][l[ل]دِّينِ مَا لَمْ يَأْذ[i:12109[َنۢ ب]ِهِ [h:1707[ٱ]للَّهُ‌ۚ وَلَوْلَا كَلِمَةُ [h:12110[ٱ]لْفَصْلِ لَقُضِىَ بَيْنَهُمْ‌ۗ وَإِ[g[نّ]َ [h:9074[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ لَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Ёки уларнинг диндан Аллоҳ изн бермаган нарсаларни шариат қилиб берган шерик лари борми?! Агар ажрим калимаси бўлмаганида, албатта, улар ўртасида ҳукм қилинган бўлар эди. Албатта, золим кимсалар учун аламли азоб бордир.",485,25],["تَرَى [h:12111[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ مُشْفِقِينَ مِ[g[مّ]َا كَسَبُو[s[اْ] وَهُوَ وَاقِ[i:5127[عُۢ ب]ِهِمْ‌ۗ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ فِى رَوْضَاتِ [h:12112[ٱ]لْجَ[g[نّ]َاتِ‌ۖ لَه[w:3531[ُم م]َّا يَش[o[َا]ٓءُونَ عِ[f:264[ند]َ رَبِّهِمْ‌ۚ ذ[n[َٲ]لِكَ هُوَ [h:11140[ٱ]لْفَضْلُ [h:11141[ٱ]لْكَب[p[ِي]رُ","Золимларни ўзлари касб қилган нарсаларидан қўрқувчи ўлароқ кўрасан. Ҳолбуки, у уларга тушгувчидир. Иймон келтириб, солиҳ амалларни қилувчилар эса, жаннат боғларидадир. Улар учун Роббилари ҳузурида хоҳлаган нарсалари бордир. Мана шунинг ўзи катта фазлдир.",485,25],["ذ[n[َٲ]لِكَ [h:12113[ٱ]لَّذِى يُبَشِّرُ [h:12114[ٱ]للَّهُ عِبَادَهُ [h:12115[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ‌ۗ قُل لّ[o[َآ] أَسْــَٔلُكُمْ عَلَيْهِ أَ[q:2795[جْ]رًا إِلَّا [h:12116[ٱ]لْمَوَدَّةَ فِى [h:12117[ٱ]لْقُرْبَىٰ‌ۗ وَم[a:12118[َن ي]َ[q:12119[قْ]تَرِفْ حَسَنَ[a:12120[ةً ن]َّزِ[q:12106[دْ] لَهُ[n[ۥ] فِيهَا حُسْنًا‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[f:11131[رٌ ش]َك[p[ُو]رٌ","Ана ўша, Аллоҳ иймон келтириб, солиҳ амалларни қилган бандаларига бераётган хушхабардир. Сен: «Мен сиздан бу учун ажр эмас, фақат қариндошлик меҳринигина сўрайман», деб айт. Ким яхшилик қилса, Биз унга ўша ишида яхшиликни зиёда қилурмиз. Албатта, Аллоҳ ўта мағфиратли, ўта шукр қилгувчи зотдир.",486,25],["أَمْ يَقُولُونَ [h:12121[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ كَذِ[f:12122[بًا‌ۖ ف]َإ[a:12123[ِن ي]َشَإِ [h:4035[ٱ]للَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ‌ۗ وَيَمْحُ [h:12124[ٱ]للَّهُ [h:12125[ٱ]لْبَ[n[ـٰ]طِلَ وَيُحِقُّ [h:12126[ٱ]لْحَقَّ بِكَلِمَ[n[ـٰ]تِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َهُ[n[ۥ] عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","Ёки улар: «У Аллоҳга нисбатан ёлғон тўқиди», дейдиларми?! Бас, агар Аллоҳ хоҳласа, қалбингга муҳр босур ва Аллоҳ Ўз сўзлари ила ботилни йўқ қилиб, ҳақни ҳақ қилур. Албатта, у диллардаги нарсани ўта билгувчидир.",486,25],["وَهُوَ [h:4114[ٱ]لَّذِى يَ[q:5822[قْ]بَلُ [h:5823[ٱ][l[ل]تَّوْبَةَ عَنْ عِبَادِه[n[ِۦ] وَيَعْفُو[s[اْ] عَنِ [h:12127[ٱ][l[ل]سَّيِّـَٔـاتِ وَيَعْلَمُ مَا تَفْعَل[p[ُو]نَ","Унинг Ўзи бандаларидан тавбани қабул қилур, гуноҳларини афв этур ва нима қилаётганингизни билур.",486,25],["وَيَسْتَجِيبُ [h:12128[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ وَيَزِيدُه[w:3323[ُم م]ِّ[f:475[ن ف]َضْلِه[n[ِۦ]‌ۚ وَ[h:1467[ٱ]لْكَ[n[ـٰ]فِرُونَ لَهُمْ عَذَا[f:1727[بٌ ش]َد[p[ِي][q[د]ٌ","У зот иймон келтириб, солиҳ амаллар қилганларнинг ижобат қилур ва уларга Ўз фазлидан зиёда қилур. Кофирларга эса, уларга, шиддатли азоб бордир.",486,25],["۞ وَلَوْ بَسَطَ [h:12129[ٱ]للَّهُ [h:12130[ٱ][l[ل]رِّزْقَ لِعِبَادِه[n[ِۦ] لَبَغَوْ[s[اْ] فِى [h:44[ٱ]لْأَرْضِ وَلَ[n[ـٰ]ك[a:12131[ِن ي]ُنَزِّلُ بِقَدَ[a:12132[رٍ م]َّا يَش[o[َا]ٓءُ‌ۚ إِ[g[نّ]َهُ[n[ۥ] بِعِبَادِه[n[ِۦ] خَبِي[i:12133[رُۢ ب]َص[p[ِي]رٌ","Агар Аллоҳ бандаарига ризқни кенг қилиб қўйса, албатта, улар ер юзида ҳаддан ошиб кетурлар, лекин У Ўзи хоҳлаганига ўлчов билан туширур. Албатта, у ўз бандаларидан ўта хабардор ва уларни ўта кўргувчидир.",486,25],["وَهُوَ [h:4114[ٱ]لَّذِى يُنَزِّلُ [h:12134[ٱ]لْغَيْثَ م[i:146[ِنۢ ب]َعْدِ مَا قَنَطُو[s[اْ] وَيَ[f:12135[نش]ُرُ رَحْمَتَهُ[n[ۥ]‌ۚ وَهُوَ [h:12136[ٱ]لْوَلِىُّ [h:12137[ٱ]لْحَم[p[ِي][q[د]ُ","У зот ноумид бўлганларидан кейин ёмғирни нозил қилур ва Ўз раҳматини таратур. У валий ва мақталган зотдир.",486,25],["وَمِنْ ءَايَ[n[ـٰ]تِه[n[ِۦ] خَلْقُ [h:10451[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَثَّ فِيهِمَا مِ[f:4026[ن د][m[َا]ٓبَّ[a:12138[ةٍ‌ۚ و]َهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَش[o[َا]ٓءُ قَد[p[ِي]رٌ","У зотнинг оят-белгиларидан осмонлару ернинг яратилиши ва уларда турли жониворларнинг таратиб қўйилишидир. Ва У зот агар хоҳласа, уларни жамлашга қодирдир.",486,25],["وَم[o[َآ] أَصَ[n[ـٰ]بَك[w:12139[ُم م]ّ[a:12140[ِن م]ُّصِيبَ[f:12141[ةٍ ف]َبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو[s[اْ] عَ[f:3438[ن ك]َث[p[ِي]رٍ","Сизга қайси бир мусибат етса, бас, ўз қўлингиз қилган касбдандир ва У зот кўпини афв қилур.",486,25],["وَم[o[َآ] أَ[f:428[نت][c:4435[ُم ب]ِمُعْجِزِينَ فِى [h:44[ٱ]لْأَرْضِ‌ۖ وَمَا لَك[w:556[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ م[a:557[ِن و]َلِ[a:558[ىٍّ و]َلَا نَص[p[ِي]رٍ","Ва сиз ер юзида қочиб қутула олмассиз. Ҳамда сиз учун Аллоҳдан ўзга валий ҳам, нусрат бергувчи ҳам йўқ.",486,25],["وَمِنْ ءَايَ[n[ـٰ]تِهِ [h:12142[ٱ]لْجَوَارِ فِى [h:837[ٱ]لْبَحْرِ كَ[h:12143[ٱ]لْأَعْلَ[p[ـٰ]مِ","Денгизда тоғдек бўлиб сузиб юргувчи кемалар У зотнинг оят-белгиларидандир.",487,25],["إ[a:3197[ِن ي]َشَأْ يُسْكِنِ [h:12144[ٱ][l[ل]رِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِه[o[ِۦٓ‌ۚ] إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:7049[تٍ ل]ِّكُلِّ صَبَّا[f:7050[رٍ ش]َك[p[ُو]رٍ","Агар У зот хоҳласа, шамолни тўхтатиб қўюр. Бас, улар унинг устида туриб қолурлар. Албатта, ана шунда ҳар бир сабр қилувчи ва шукр қилгувчи учун оят-белгилар бордир.",487,25],["أَوْ يُوبِ[q:12145[قْ]هُ[g[نّ]َ بِمَا كَسَبُو[s[اْ] وَيَعْفُ عَ[f:3438[ن ك]َث[p[ِي]رٍ","Ёки уларни аларнинг касби туфайли ҳалок қилур ва У зот кўпни афв қилур.",487,25],["وَيَعْلَمَ [h:12146[ٱ]لَّذِينَ يُجَ[n[ـٰ]دِلُونَ ف[o[ِىٓ] ءَايَ[n[ـٰ]تِنَا مَا لَه[w:1812[ُم م]ّ[a:7093[ِن م]َّح[p[ِي]صٍ","Токи Бизнинг оятларимиз ҳақида тортишадиганлар билсинларки, улар учун ҳеч бир қочар жой йўқдир.",487,25],["فَم[o[َآ] أُوتِيت[w:10210[ُم م]ِّ[f:2103[ن ش][f:10211[َىْءٍ ف]َمَتَ[n[ـٰ]عُ [h:10212[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۖ وَمَا عِ[f:264[ند]َ [h:408[ٱ]للَّهِ خَيْ[a:8546[رٌ و]َأَ[q:8540[بْ]قَىٰ لِلَّذِينَ ءَامَنُو[s[اْ] وَعَلَىٰ رَبِّهِمْ يَتَوَكَّل[p[ُو]نَ","Сизга берилган нарсалар ҳаёти дунёнинг матоҳи, холос. Аллоҳнинг ҳузуридаги яхши ва боқий нарсалар эса, иймон келтирган ва Роббиларига таваккал қилганлар учундир.",487,25],["وَ[h:9999[ٱ]لَّذِينَ يَ[q:12147[جْ]تَنِبُونَ كَبَ[o[ـٰٓ]ئِرَ [h:12148[ٱ]لْإِثْمِ وَ[h:12149[ٱ]لْفَو[n[َٲ]حِشَ وَإِذَا مَا غَضِبُو[s[اْ] هُمْ يَغْفِر[p[ُو]نَ","Катта гуноҳлар ва фоҳиша ишлардан четда бўладиган ва ғазабланган вақтда кечириб юборадиганлар учундир.",487,25],["وَ[h:9999[ٱ]لَّذِينَ [h:12150[ٱ]سْتَجَابُو[s[اْ] لِرَبِّهِمْ وَأَقَامُو[s[اْ] [h:1641[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ وَمِ[g[مّ]َا رَزَ[q:15[قْ]نَ[n[ـٰ]هُمْ يُ[f:16[نف]ِق[p[ُو]نَ","Роббиларига ижобат қилган, намозни тўкис адо этган, ишлари ўзаро шуро ила бўлган ва уларга ризқ қилиб берган нарсаларимиздан инфоқ қиладиганлар учундир.",487,25],["وَ[h:9999[ٱ]لَّذِينَ إِذ[o[َآ] أَصَابَهُمُ [h:12151[ٱ]لْبَغْىُ هُمْ يَ[f:9794[نت]َصِر[p[ُو]نَ","Ўзларига тажовузкорлик етганда нусрат қозонадиганлар учундир.",487,25],["وَجَز[o[َٲ]ٓؤُ[s[اْ] سَيِّئَ[f:12152[ةٍ س]َيِّئَ[a:12153[ةٌ م]ِّثْلُهَا‌ۖ فَمَنْ عَفَا وَأَصْلَحَ فَأَ[q:12154[جْ]رُهُ[n[ۥ] عَلَى [h:412[ٱ]للَّهِ‌ۚ إِ[g[نّ]َهُ[n[ۥ] لَا يُحِبُّ [h:1968[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Ёмонликнинг жазоси ўз мислидек ёмонликдир. Ким афв этиб ислоҳ қилса, унинг ажри Аллоҳнинг зиммасидадир. Албатта, У зот золимларни севмас.",487,25],["وَلَمَنِ [h:12155[ٱ][f:12156[نت]َصَرَ بَعْدَ ظُلْمِه[n[ِۦ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ مَا عَلَيْه[w:4082[ِم م]ِّ[f:5782[ن س]َب[p[ِي]لٍ","Албатта, ким ўзига бўлган зулмдан кейин нусрат қозонса, бас, ундайларни ҳеч йўл йўқ.",487,25],["إِ[g[نّ]َمَا [h:5784[ٱ][l[ل]سَّبِيلُ عَلَى [h:289[ٱ]لَّذِينَ يَظْلِمُونَ [h:12157[ٱ][l[ل][g[نّ]َاسَ وَيَ[q:12158[بْ]غُونَ فِى [h:44[ٱ]لْأَرْضِ بِغَيْرِ [h:325[ٱ]لْحَقِّ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Фақатгина одамларга зулм қиладиган ва ер юзида ноҳақ тажовузкорлик қиладиганларни йўл бордир. Ана ўшаларга аламли азоб бордир.",487,25],["وَلَمَ[f:12159[ن ص]َبَرَ وَغَفَرَ إِ[g[نّ]َ ذ[n[َٲ]لِكَ لَمِنْ عَزْمِ [h:2488[ٱ]لْأُم[p[ُو]رِ","Шубҳасиз, ким сабр қилиб, кечирса, албатта, бу мардлик ишларидандир.",487,25],["وَم[a:3002[َن ي]ُضْلِلِ [h:3003[ٱ]للَّهُ فَمَا لَهُ[n[ۥ] م[a:557[ِن و]َلِ[a:12160[ىٍّ م]ّ[i:254[ِنۢ ب]َعْدِه[n[ِۦ]‌ۗ وَتَرَى [h:12161[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ لَ[g[مّ]َا رَأَوُ[s[اْ] [h:6091[ٱ]لْعَذَابَ يَقُولُونَ هَلْ إِلَىٰ مَرَ[a:12162[دٍّ م]ِّ[f:5782[ن س]َب[p[ِي]لٍ","Аллоҳ кимни залолатга кетказса, бас, унга У зотдан ўзга ҳеч бир валий бўлмас. Золимларни кўрурсанки, азобни кўрган чоқларида: « қайтишга ҳеч бир йўл бормикан?» дерлар.",487,25],["وَتَرَ[n[ٮٰ]هُمْ يُعْرَضُونَ عَلَيْهَا خَ[n[ـٰ]شِعِينَ مِنَ [h:7943[ٱ][l[ل]ذُّلِّ يَ[f:1141[نظ]ُرُونَ مِ[f:12163[ن ط]َرْفٍ خَفِ[a:12164[ىٍّ‌ۗ و]َقَالَ [h:614[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[g[نّ]َ [h:11650[ٱ]لْخَ[n[ـٰ]سِرِينَ [h:11651[ٱ]لَّذِينَ خَسِر[o[ُوٓ][s[اْ] أَ[f:38[نف]ُسَهُمْ وَأَهْلِيهِمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۗ أَل[o[َآ] إِ[g[نّ]َ [h:7101[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ فِى عَذَا[a:12165[بٍ م]ُّق[p[ِي]مٍ","Сен уларни уга кўндаланг қилинаётганларида хору зор ва қўрққан ҳолларида кўз қири билан назар солаётганларини кўрурсан. Иймон келтирганлар: «Албатта, зиёнкорлар қиёмат куни ўзларига ва аҳли аёлларига зиён қилганлардир» дерлар. Огоҳ бўлингким, албатта, золимлар доимий азобдадирлар.",488,25],["وَمَا كَانَ لَه[w:1812[ُم م]ِّنْ أَوْلِي[o[َا]ٓءَ يَ[f:12166[نص]ُرُونَه[w:12167[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ‌ۗ وَم[a:3002[َن ي]ُضْلِلِ [h:3003[ٱ]للَّهُ فَمَا لَهُ[n[ۥ] مِ[f:5782[ن س]َب[p[ِي]لٍ","Ва уларга Аллоҳдан ўзга ёрдам берадиган ҳеч қандай валийлар бўлмади. Аллоҳ кимни залолатга кетказса, бас, унга ҳеч бир йўл йўқдир.",488,25],["ٱسْتَجِيبُو[s[اْ] لِرَبِّك[w:12168[ُم م]ِّ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:1462[َن ي]َأْتِىَ يَوْ[u:1463[مٌ ل]َّا مَرَدَّ لَهُ[n[ۥ] مِنَ [h:321[ٱ]للَّهِ‌ۚ مَا لَك[w:556[ُم م]ّ[a:12169[ِن م]َّلْجَ[a:12170[إٍ ي]َوْمَئِ[a:12171[ذٍ و]َمَا لَك[w:556[ُم م]ّ[a:12172[ِن ن]َّك[p[ِي]رٍ","Аллоҳ томонидан, қайтариб бўлмайдиган кун келмай туриб, Роббингизга ижобат қилинг! Ўша куни сизга паноҳгоҳ топилмас ва сизга инкор қилгувчи топилмас.",488,25],["فَإِنْ أَعْرَضُو[s[اْ] فَم[o[َآ] أَرْسَلْنَ[n[ـٰ]كَ عَلَيْهِمْ حَفِيظًا‌ۖ إِنْ عَلَيْكَ إِلَّا [h:3819[ٱ]لْبَلَ[n[ـٰ]غُ‌ۗ وَإِ[g[نّ][o[َآ] إِذ[o[َآ] أَذَ[q:5991[قْ]نَا [h:6253[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ مِ[g[نّ]َا رَحْمَ[f:12173[ةً ف]َرِحَ بِهَا‌ۖ وَإِ[f:2950[ن ت]ُصِ[q:2951[بْ]هُمْ سَيِّئَ[i:10486[ةُۢ ب]ِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِ[g[نّ]َ [h:12174[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ كَف[p[ُو]رٌ","Агар улар юз ўгирсалар, бас, Биз сени уларга қўриқчи қилиб юборганимиз йўқ. Сенинг зиммангда фақат етказиш бор, холос. Албатта, Биз инсонга Ўзимиздан раҳмат тоттирган чоғимизда у ундан қувонур ва агар уларга ўз қўллари тақдим этган нарса туфайли ёмонлик етса, бас, албатта, инсон куфрони неъмат қилур.",488,25],["لِّلَّهِ مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ يَخْلُقُ مَا يَش[o[َا]ٓءُ‌ۚ يَهَبُ لِم[a:1537[َن ي]َش[o[َا]ٓءُ إِنَ[n[ـٰ][a:12175[ثًا و]َيَهَبُ لِم[a:1537[َن ي]َش[o[َا]ٓءُ [h:12176[ٱ][l[ل]ذُّك[p[ُو]رَ","Осмонлару ернинг мулки Аллоҳникидир. У зот хоҳлаган нарсасини яратур. У зот хоҳлаган кишисига қизлар ҳадя этур ва хоҳлаган кишисига ўғиллар ҳадя этур.",488,25],["أَوْ يُزَوِّجُهُمْ ذُكْرَا[a:12177[نًا و]َإِنَ[n[ـٰ][a:12178[ثًا‌ۖ و]َيَ[q:6204[جْ]عَلُ م[a:476[َن ي]َش[o[َا]ٓءُ عَقِيمًا‌ۚ إِ[g[نّ]َهُ[n[ۥ] عَلِي[f:7488[مٌ ق]َد[p[ِي]رٌ","Ёки уларни жуфтлаб ўғил-қиз қилиб берур ва хоҳлаган кишисини туғмас қилур. Албатта, У зот ўта билгувчи ва ўта қодирдир.",488,25],["۞ وَمَا كَانَ لِبَشَرٍ أ[a:12179[َن ي]ُكَلِّمَهُ [h:12180[ٱ]للَّهُ إِلَّا وَحْيًا أَوْ م[a:12181[ِن و]َرَآىِٕ حِجَابٍ أَوْ يُرْسِلَ رَسُول[f:12182[اً ف]َيُوحِىَ بِإِذْنِه[n[ِۦ] مَا يَش[o[َا]ٓءُ‌ۚ إِ[g[نّ]َهُ[n[ۥ] عَلِىٌّ حَك[p[ِي]مٌ","Аллоҳ башар билан гаплашмоғи бўлмаган, магар ваҳий орқали, ёки парда ортидан ёхуд элчи юборадию, У зотнинг изни ила хоҳлаган нарсасини ваҳий қилур. Албатта, У зот ўта олий ва ўта ҳикматлидир.",488,25],["وَكَذ[n[َٲ]لِكَ أَوْحَيْن[o[َآ] إِلَيْكَ رُو[a:12183[حًا م]ِّنْ أَمْرِنَا‌ۚ مَا كُ[f:735[نت]َ تَ[q:10618[دْ]رِى مَا [h:12184[ٱ]لْكِتَ[n[ـٰ]بُ وَلَا [h:12185[ٱ]لْإِيمَ[n[ـٰ]نُ وَلَ[n[ـٰ]كِ[f:12186[ن ج]َعَلْنَ[n[ـٰ]هُ نُو[a:12187[رًا ن]َّهْدِى بِه[n[ِۦ] م[a:4211[َن ن]َّش[o[َا]ٓءُ مِنْ عِبَادِنَا‌ۚ وَإِ[g[نّ]َكَ لَتَهْد[o[ِىٓ] إِلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Ана шунга ўхшаш, Биз сенга Ўз амримиздан бир руҳни ваҳий қилдик. Сен китоб нималигини ҳам, иймон нималигини ҳам идрок қилмас эдинг. Лекин, Биз уни бир нур қилдикки, у билан бандаларимиздан кимни хоҳласак ҳидоят қилурмиз. Албатта, сен тўғри йўлга ҳидоят қилурсан.",489,25],["صِر[n[َٲ]طِ [h:12188[ٱ]للَّهِ [h:9413[ٱ]لَّذِى لَهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۗ أَل[o[َآ] إِلَى [h:1637[ٱ]للَّهِ تَصِيرُ [h:12189[ٱ]لْأُم[p[ُو]رُ","Осмонлардаги нарсалар ва ердаги нарсалар Уники бўлган Аллоҳнинг йўлига. Огоҳ бўлингким, барча ишлар Аллоҳгагина қайтур.",489,25]]},{"n":43,"ar":"الزُّخۡرُفِ","en":"Az-Zukhruf","uz":"Зухруф","type":"Макка","ayahs":[["ح[m[مٓ]","Ҳа-а. Мийм.",489,25],["وَ[h:9999[ٱ]لْكِتَ[n[ـٰ]بِ [h:12190[ٱ]لْمُب[p[ِي]نِ","қ-ойдин китоб ила қасам.",489,25],["إِ[g[نّ]َا جَعَلْنَ[n[ـٰ]هُ قُرْء[n[َٲ]نًا عَرَبِي[u:6542[ًّا ل]َّعَلَّكُمْ تَعْقِل[p[ُو]نَ","Албатта, Биз уни арабча Қуръон қилдик. Шоядки ақл юритсангиз.",489,25],["وَإِ[g[نّ]َهُ[n[ۥ] ف[o[ِىٓ] أُ[g[مّ]ِ [h:12191[ٱ]لْكِتَ[n[ـٰ]بِ لَدَيْنَا لَعَلِىٌّ حَك[p[ِي]مٌ","Албатта, у ҳузуримиздаги она китобдадир, у олийдир, ҳикматлидир.",489,25],["أَفَنَضْرِبُ عَ[f:10796[نك]ُمُ [h:12192[ٱ][l[ل]ذِّكْرَ صَفْحًا أَ[f:12193[ن ك]ُ[f:100[نت]ُمْ قَوْ[a:12194[مًا م]ُّسْرِف[p[ِي]نَ","Наҳотки сиз исрофчи қавм бўлганингиз учун сиздан юз ўгириб, зикр-эслатмани буриб юборсак?!",489,25],["وَكَمْ أَرْسَلْنَا م[a:2299[ِن ن]َّبِ[f:12195[ىٍّ ف]ِى [h:12196[ٱ]لْأَوَّل[p[ِي]نَ","Аввалгиларга қанчадан-қанча Пайғамбарлар юбордик.",489,25],["وَمَا يَأْتِيه[w:7205[ِم م]ّ[a:2299[ِن ن]َّبِىٍّ إِلَّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Улар ўзларига келган ҳар бир Пайғамбарни, албатта, истеҳзо қилганлар.",489,25],["فَأَهْلَكْن[o[َآ] أَشَدَّ مِنْه[c:12197[ُم ب]َ[q:12198[طْ][a:12199[شًا و]َمَضَىٰ مَثَلُ [h:12200[ٱ]لْأَوَّل[p[ِي]نَ","Бас, Биз улардан кўра кучлироқларни ҳалок қилганмиз. Аввалгиларнинг мисоли ўтди.",489,25],["وَلَئِ[f:5683[ن س]َأَلْتَه[w:10403[ُم م]َّنْ خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ لَيَقُولُ[g[نّ]َ خَلَقَهُ[g[نّ]َ [h:12201[ٱ]لْعَزِيزُ [h:10030[ٱ]لْعَل[p[ِي]مُ","Улардан: «Осмонлару ерни ким яратган!» деб сўрасанг, албатта: «Уларни азиз ва ўта илмли зот яратган», дерлар.",489,25],["ٱلَّذِى جَعَلَ لَكُمُ [h:87[ٱ]لْأَرْضَ مَهْ[a:12202[دًا و]َجَعَلَ لَكُمْ فِيهَا سُبُل[u:12203[اً ل]َّعَلَّكُمْ تَهْتَد[p[ُو]نَ","У зот сизга ерни бешик қилиб берди ва сизга унда йўллар қилиб қўйди. Шоядки, ҳидоят топсангиз.",489,25],["وَ[h:9999[ٱ]لَّذِى نَزَّلَ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[i:9165[ءَۢ ب]ِقَدَ[f:12204[رٍ ف]َأَ[f:12205[نش]َرْنَا بِه[n[ِۦ] بَلْدَ[a:9661[ةً م]َّيْ[f:12206[تًا‌ۚ ك]َذ[n[َٲ]لِكَ تُخْرَج[p[ُو]نَ","У зот осмондан ўлчов ила сув туширди. Бас, Биз у ила ўлик юртни тирилтирдик. Сиз ҳам шунга ўхшаш чиқарилурсиз.",490,25],["وَ[h:9999[ٱ]لَّذِى خَلَقَ [h:11235[ٱ]لْأَزْو[n[َٲ]جَ كُلَّهَا وَجَعَلَ لَك[w:1578[ُم م]ِّنَ [h:12207[ٱ]لْفُلْكِ وَ[h:1778[ٱ]لْأَنْعَ[n[ـٰ]مِ مَا تَرْكَب[p[ُو]نَ","У зот барча жуфтларни яратган ва сизга кемалар ҳамда чорва ҳайвонларидан минадиган нарсаларингизни қилди.",490,25],["لِتَسْتَوُ[n[ۥ]اْ عَلَىٰ ظُهُورِه[n[ِۦ] ثُ[g[مّ]َ تَذْكُرُو[s[اْ] نِعْمَةَ رَبِّكُمْ إِذَا [h:12208[ٱ]سْتَوَيْتُمْ عَلَيْهِ وَتَقُولُو[s[اْ] سُ[q:7648[بْ]حَ[n[ـٰ]نَ [h:7649[ٱ]لَّذِى سَخَّرَ لَنَا هَ[n[ـٰ]ذَا وَمَا كُ[g[نّ]َا لَهُ[n[ۥ] مُ[q:12209[قْ]رِن[p[ِي]نَ","Токи сиз уларнинг устига ўрнашгайсизлар, сўнгра уларнинг устига ўрнашиб олгач, Роббингиз неъматини эслаб: «Бизга буни бўйсундирган зот покдир. Биз бунга қодир эмас эдик.",490,25],["وَإِ[g[نّ][o[َآ] إِلَىٰ رَبِّنَا لَمُ[f:12210[نق]َلِب[p[ُو]نَ","Ва, албатта, Биз Роббимизга қайтгувчилардирмиз», дегайсиз.",490,25],["وَجَعَلُو[s[اْ] لَهُ[n[ۥ] مِنْ عِبَادِه[n[ِۦ] جُزْءًا‌ۚ إِ[g[نّ]َ [h:7137[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ لَكَفُو[a:12211[رٌ م]ُّب[p[ِي]نٌ","Улар бандаларидан Унга бўлак қилдилар. Албатта, инсон очиқ-ойдин ношукрдир.",490,25],["أَمِ [h:8410[ٱ]تَّخَذَ مِ[g[مّ]َا يَخْلُقُ بَنَا[a:12212[تٍ و]َأَصْفَ[n[ـٰ]ك[c:12213[ُم ب]ِ[h:7764[ٱ]لْبَن[p[ِي]نَ","Ёки У зот Ўзи яратадиган нарсадан қизлар тутиб, сизларни ўғиллар ила сийладими?",490,25],["وَإِذَا بُشِّرَ أَحَدُه[c:12214[ُم ب]ِمَا ضَرَبَ لِلرَّحْمَ[n[ـٰ]نِ مَثَل[f:12215[اً ظ]َلَّ وَ[q:7445[جْ]هُهُ[n[ۥ] مُسْوَد[a:7446[ًّا و]َهُوَ كَظ[p[ِي]مٌ","Қачонки улардан бирортасига, Роҳманга мисол келтирган нарсанинг хушхабари берилса, ғазабга тўлиб, юзи қорайиб кетур.",490,25],["أَوَم[a:12216[َن ي]ُنَشَّؤُ[s[اْ] فِى [h:12217[ٱ]لْحِلْيَةِ وَهُوَ فِى [h:12218[ٱ]لْخِصَامِ غَيْرُ مُب[p[ِي]نٍ","Зебу зийнат ичида ўстириладиган ва хусумат пайтида очиқ-ойдин бўла олмайдиган кимсаними?!",490,25],["وَجَعَلُو[s[اْ] [h:12219[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةَ [h:12220[ٱ]لَّذِينَ هُمْ عِبَ[n[ـٰ]دُ [h:12221[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ إِنَ[n[ـٰ]ثًا‌ۚ أَشَهِدُو[s[اْ] خَلْقَهُمْ‌ۚ سَتُكْتَبُ شَهَ[n[ـٰ]دَتُهُمْ وَيُسْــَٔل[p[ُو]نَ","Улар Роҳманнинг бандалари бўлмиш фаришталарни аёллар ҳисобладилар. Ёки уларнинг яратилишига гувоҳ бўлдиларми?! Албатта, бу гувоҳликлари ёзилур ва сўроққа тутилурлар!",490,25],["وَقَالُو[s[اْ] لَوْ ش[o[َا]ٓءَ [h:12222[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ مَا عَبَ[q:12223[دْ]نَ[n[ـٰ]ه[w:12224[ُم‌ۗ م]َّا لَه[c:12225[ُم ب]ِذ[n[َٲ]لِكَ مِنْ عِلْمٍ‌ۖ إِنْ هُمْ إِلَّا يَخْرُص[p[ُو]نَ","Улар: «Агар Роҳман хоҳлаганида, Биз уларга ибодат қилмас эдик», дедилар. Уларда бу ҳақда ҳеч бир илм йўқ. Улар фақат алжирамоқдалар, холос.",490,25],["أَمْ ءَاتَيْنَ[n[ـٰ]هُمْ كِتَ[n[ـٰ][a:12226[بًا م]ِّ[f:1097[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] فَه[c:12227[ُم ب]ِه[n[ِۦ] مُسْتَمْسِك[p[ُو]نَ","Ёки Биз уларга удан олдин бир китоб берганмизу улар уни маҳкам тутувчиларми?!",490,25],["بَلْ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا وَجَ[q:3834[دْ]ن[o[َآ] ءَاب[o[َا]ٓءَنَا عَلَ[o[ىٰٓ] أُ[g[مّ]َ[a:12228[ةٍ و]َإِ[g[نّ]َا عَلَ[o[ىٰٓ] ءَاثَ[n[ـٰ]رِه[w:12229[ِم م]ُّهْتَد[p[ُو]نَ","Йўқ! Улар: «Биз ота-боболаримизни бир динда топдикки, албатта, биз уларнинг изларидан ҳидоят топгувчидирмиз», дедилар.",490,25],["وَكَذ[n[َٲ]لِكَ م[o[َآ] أَرْسَلْنَا مِ[f:18[ن ق]َ[q:19[بْ]لِكَ فِى قَرْيَ[a:4874[ةٍ م]ّ[a:10183[ِن ن]َّذِيرٍ إِلَّا قَالَ مُتْرَفُوه[o[َآ] إِ[g[نّ]َا وَجَ[q:3834[دْ]ن[o[َآ] ءَاب[o[َا]ٓءَنَا عَلَ[o[ىٰٓ] أُ[g[مّ]َ[a:12228[ةٍ و]َإِ[g[نّ]َا عَلَ[o[ىٰٓ] ءَاثَ[n[ـٰ]رِه[w:12230[ِم م]ُّ[q:12231[قْ]تَد[p[ُو]نَ","Худди шунингдек, Биз сендан илгари ҳам қайси бир қишлоқ-шаҳарга огоҳлантиргувчи юборсак, албатта, унинг зодагонлари: «Таъкидки, биз ота-боболаримизни бир динда топдик ва, албатта, биз уларнинг изларидан эргашгувчилардирмиз», дедилар.",491,25],["۞ قَ[n[ـٰ]لَ أَوَلَوْ جِئْتُك[c:12232[ُم ب]ِأَهْدَىٰ مِ[g[مّ]َا وَجَ[d:4703[د]تُّمْ عَلَيْهِ ءَاب[o[َا]ٓءَكُمْ‌ۖ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا بِم[o[َآ] أُرْسِلْت[c:7059[ُم ب]ِه[n[ِۦ] كَ[n[ـٰ]فِر[p[ُو]نَ","У: «Агар мен сизга сиз ота-бобонгизни устида топган нарсангиздан ҳам ҳидоятлироқни келтирган бўлсам ҳам-а?!» деди. Улар: «Биз сиз ила юборилган нарсага кофирдирмиз», дедилар.",491,25],["فَ[h:9999[ٱ][f:4969[نت]َقَمْنَا مِنْهُمْ‌ۖ فَ[h:1513[ٱ][f:1513[نظ]ُرْ كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:2258[ٱ]لْمُكَذِّب[p[ِي]نَ","Бас, Биз улардан интиқом олдик. Энди назар сол. ёлғончи қилгувчиларнинг оқибати қандай бўлди?!",491,25],["وَإِذْ قَالَ إِ[q:2003[بْ]ر[n[َٲ]هِيمُ لِأَبِيهِ وَقَوْمِه[o[ِۦٓ] إِ[g[نّ]َنِى بَر[o[َا]ٓ[a:12233[ءٌ م]ِّ[g[مّ]َا تَعْبُد[p[ُو]نَ","Эсла, Иброҳим отасига ва қавмига: «Мен, албатта, сиз ибодат қилаётган нарсадан воз кечгувчиман.",491,25],["إِلَّا [h:6186[ٱ]لَّذِى فَطَرَنِى فَإِ[g[نّ]َهُ[n[ۥ] سَيَهْد[p[ِي]نِ","Магар мени яратган зотдангина. Албатта, У зот мени ҳидоят қилур», деган эди.",491,25],["وَجَعَلَهَا كَلِمَ[i:12234[ةَۢ ب]َاقِيَ[f:12235[ةً ف]ِى عَقِبِه[n[ِۦ] لَعَلَّهُمْ يَرْجِع[p[ُو]نَ","Ва буни у ўз ортидан зурриётига боқий қолгувчи қилди. Шоядки қайтсалар.",491,25],["بَلْ مَتَّعْتُ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ وَءَاب[o[َا]ٓءَهُمْ حَتَّىٰ ج[o[َا]ٓءَهُمُ [h:6141[ٱ]لْحَقُّ وَرَسُو[a:12236[لٌ م]ُّب[p[ِي]نٌ","Мен эса, анавиларни ва уларнинг ота-боболарини, то уларга ҳақ ҳамда очиқ-ойдин Пайғамбар келгунча фойдалантирдим.",491,25],["وَلَ[g[مّ]َا ج[o[َا]ٓءَهُمُ [h:6141[ٱ]لْحَقُّ قَالُو[s[اْ] هَ[n[ـٰ]ذَا سِحْ[a:12237[رٌ و]َإِ[g[نّ]َا بِه[n[ِۦ] كَ[n[ـٰ]فِر[p[ُو]نَ","Қачонки уларга ҳақ келганида, улар: «Бу сеҳрдир ва, албатта, биз бунга кофирдирмиз», дедилар.",491,25],["وَقَالُو[s[اْ] لَوْلَا نُزِّلَ هَ[n[ـٰ]ذَا [h:3971[ٱ]لْقُرْءَانُ عَلَىٰ رَجُ[a:12238[لٍ م]ِّنَ [h:12239[ٱ]لْقَرْيَتَيْنِ عَظ[p[ِي]مٍ","Улар: «Ушбу Қуръон икки шаҳардан бўлган улуғ кишига нозил қилинганида эди», дедилар.",491,25],["أَهُمْ يَ[q:12240[قْ]سِمُونَ رَحْمَتَ رَبِّكَ‌ۚ نَحْنُ قَسَمْنَا بَيْنَه[w:12241[ُم م]َّعِيشَتَهُمْ فِى [h:441[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۚ وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْ[f:4575[ضٍ د]َرَجَ[n[ـٰ][u:12242[تٍ ل]ِّيَتَّخِذَ بَعْضُه[c:11159[ُم ب]َعْ[f:12243[ضًا س]ُخْرِي[a:12244[ًّا‌ۗ و]َرَحْمَتُ رَبِّكَ خَيْ[a:2365[رٌ م]ِّ[g[مّ]َا يَ[q:2366[جْ]مَع[p[ُو]نَ","Ёки улар Роббингнинг раҳматини тақсимлайдиларми? Биз ҳаёти дунёда уларнинг ораларида маишатларини тақсимладик ва баъзилари баъзиларини хизматкор қилиб олишлари учун айримларининг даражаларини айримларидан устун қилиб қўйганмиз. Роббингнинг раҳмати улар жамлайдиган нарсадан яхшидир.",491,25],["وَلَوْل[o[َآ] أ[a:3312[َن ي]َكُونَ [h:12245[ٱ][l[ل][g[نّ]َاسُ أُ[g[مّ]َ[a:1159[ةً و][n[َٲ]حِدَ[u:12246[ةً ل]َّجَعَلْنَا لِم[a:12247[َن ي]َكْفُرُ بِ[h:6981[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ لِبُيُوتِهِمْ سُقُ[a:12248[فًا م]ِّ[f:12249[ن ف]ِضَّ[a:12250[ةٍ و]َمَعَارِجَ عَلَيْهَا يَظْهَر[p[ُو]نَ","Агар одамлар бир миллат бўлиб қолишлари бўлмаганда, албатта, Биз Роҳманга куфр келтирадиганларнинг уйлари шифтини ва унга чиқадиган нарвонларини кумушдан қилиб қўяр эдик.",491,25],["وَلِبُيُوتِهِمْ أَ[q:12251[بْ]و[n[َٲ][a:12252[بًا و]َسُرُرًا عَلَيْهَا يَتَّكِــٔ[p[ُو]نَ","Ва уйларининг эшикларини ҳам, устида ёнбошлаб ётадиган сўриларини ҳам.",492,25],["وَزُخْرُ[a:12253[فًا‌ۚ و]َإِ[f:12254[ن ك]ُلُّ ذ[n[َٲ]لِكَ لَ[g[مّ]َا مَتَ[n[ـٰ]عُ [h:1780[ٱ]لْحَيَ[s[و][n[ٲ]ةِ [h:442[ٱ][l[ل]دُّنْيَا‌ۚ وَ[h:2944[ٱ]لْأَخِرَةُ عِ[f:264[ند]َ رَبِّكَ لِلْمُتَّق[p[ِي]نَ","Ва зебу зийнату безакларни ҳам. Буларнинг ҳаммаси ҳаёти дунёнинг матоҳидан бошқа нарса эмас. Охират эса, Роббинг наздида тақводорлар учундир.",492,25],["وَم[a:12255[َن ي]َعْشُ عَ[f:3773[ن ذ]ِكْرِ [h:12256[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ نُقَيِّضْ لَهُ[n[ۥ] شَيْطَ[n[ـٰ][f:12257[نًا ف]َهُوَ لَهُ[n[ۥ] قَر[p[ِي]نٌ","Ким Роҳманнинг эслатмасидан шабкўр бўлиб олса, Биз унга шайтонни яқин қилиб қўюрмиз, бас, у унга доимий ҳамроҳ бўлур.",492,25],["وَإِ[g[نّ]َهُمْ لَيَصُدُّونَهُمْ عَنِ [h:6998[ٱ][l[ل]سَّبِيلِ وَيَحْسَبُونَ أَ[g[نّ]َه[w:4653[ُم م]ُّهْتَد[p[ُو]نَ","Албатта, улар йўлдан тўсурлар ва улар ўзларини шак-шубҳасиз ҳидоят топгувчилардек ҳисобларлар.",492,25],["حَتَّ[o[ىٰٓ] إِذَا ج[o[َا]ٓءَنَا قَالَ يَ[n[ـٰ]لَيْتَ بَيْنِى وَبَيْنَكَ بُعْدَ [h:12258[ٱ]لْمَشْرِقَيْنِ فَبِئْسَ [h:12259[ٱ]لْقَر[p[ِي]نُ","Токи ҳузуримизга келганда: «Қани энди мен билан сенинг оранг мағриб ила машриқчалик узоқ бўлса эди. Бас, сен нақадар ёмон ҳамроҳсан», дер.",492,25],["وَل[a:12260[َن ي]َ[f:10716[نف]َعَكُمُ [h:12261[ٱ]لْيَوْمَ إِ[d:12262[ذ] ظَّلَمْتُمْ أَ[g[نّ]َكُمْ فِى [h:10442[ٱ]لْعَذَابِ مُشْتَرِك[p[ُو]نَ","Зулм қилганингиз учун бугунги кунда азобга шерик бўлишингиз ҳам ҳеч фойда бермас.",492,25],["أَفَأَ[f:6069[نت]َ تُسْمِعُ [h:6070[ٱ][l[ل]صُّ[g[مّ]َ أَوْ تَهْدِى [h:6072[ٱ]لْعُمْىَ وَمَ[f:975[ن ك]َانَ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Сен карларга эшиттира олармидинг ёки кўрларни ва очиқ-ойдин залолатда бўлган кимсаларни ҳидоятга сола олармидинг?!",492,25],["فَإِ[g[مّ]َا نَذْهَبَ[g[نّ]َ بِكَ فَإِ[g[نّ]َا مِنْه[w:12263[ُم م]ُّ[f:10659[نت]َقِم[p[ُو]نَ","Агар сени кетказсак ҳам, албатта, Биз улардан интиқом олурмиз.",492,25],["أَوْ نُرِيَ[g[نّ]َكَ [h:12264[ٱ]لَّذِى وَعَ[q:12265[دْ]نَ[n[ـٰ]هُمْ فَإِ[g[نّ]َا عَلَيْه[w:12266[ِم م]ُّ[q:12267[قْ]تَدِر[p[ُو]نَ","Ёки Биз уларга ваъда қилинган нарсани сенга кўрсатурмиз. Бас, албатта, Биз уларга қодирмиз.",492,25],["فَ[h:9999[ٱ]سْتَمْسِكْ بِ[h:315[ٱ]لَّذ[o[ِىٓ] أُوحِىَ إِلَيْكَ‌ۖ إِ[g[نّ]َكَ عَلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Бас, ўзингга ваҳий қилинган нарсани маҳкам тут! Албатта, сен тўғри йўлдасан.",492,25],["وَإِ[g[نّ]َهُ[n[ۥ] لَذِكْ[u:12268[رٌ ل]َّكَ وَلِقَوْمِكَ‌ۖ وَسَوْفَ تُسْــَٔل[p[ُو]نَ","Албатта, у сенга ҳам шарафдир, қавмингга ҳам. Ва, албатта, сўралурсизлар.",492,25],["وَسْــَٔلْ مَنْ أَرْسَلْنَا مِ[f:18[ن ق]َ[q:19[بْ]لِكَ م[u:7850[ِن ر]ُّسُلِن[o[َآ] أَجَعَلْنَا مِ[f:107[ن د]ُونِ [h:12269[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ ءَالِهَ[a:12270[ةً ي]ُعْبَد[p[ُو]نَ","Сендан олдин Биз юборган Пайғамбарларимиздан сўра: Роҳмандан бошқа ибодат қилинадиган илоҳлар қилган эканмизми?!",492,25],["وَلَقَ[q:341[دْ] أَرْسَلْنَا مُوسَىٰ بِـَٔـايَ[n[ـٰ]تِن[o[َآ] إِلَىٰ فِرْعَوْنَ وَمَلَإِ[s[يْ]ه[n[ِۦ] فَقَالَ إِ[g[نّ]ِى رَسُولُ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Батаҳқиқ, Биз Мусони Ўз оят-мўъжизаларимиз ила Фиръавнга ва унинг аъёнларига юбордик. Бас, у: «Албатта, мен оламлар Роббининг Пайғамбаридирман», деди.",492,25],["فَلَ[g[مّ]َا ج[o[َا]ٓءَه[c:12271[ُم ب]ِـَٔـايَ[n[ـٰ]تِن[o[َآ] إِذَا ه[w:7261[ُم م]ِّنْهَا يَضْحَك[p[ُو]نَ","Бас, қачонки у уларга мўъжизаларимизни келтирганда, улар баногоҳ улардан кула бошладилар.",492,25],["وَمَا نُرِيه[w:12272[ِم م]ِّنْ ءَايَةٍ إِلَّا هِىَ أَكْبَرُ مِنْ أُخْتِهَا‌ۖ وَأَخَذْنَ[n[ـٰ]ه[c:12273[ُم ب]ِ[h:9060[ٱ]لْعَذَابِ لَعَلَّهُمْ يَرْجِع[p[ُو]نَ","Биз уларга қайси бир оят-мўъжизани кўрсатсак ҳам, албатта, у ўз шеригидан каттароқ бўлар эди. Шояд қайтсалар, деб уларни азоб-ла тутдик.",493,25],["وَقَالُو[s[اْ] يَ[o[ـٰٓ]أَيُّهَ [h:12274[ٱ][l[ل]سَّاحِرُ [h:12275[ٱ][q:354[دْ]عُ لَنَا رَبَّكَ بِمَا عَهِدَ عِ[f:4962[ند]َكَ إِ[g[نّ]َنَا لَمُهْتَد[p[ُو]نَ","Улар: «Эй сеҳргар! Сенга берган аҳдига биноан, биз учун Роббингга дуо қил! Албатта, биз ҳидоят топгувчилардан бўламиз», дедилар.",493,25],["فَلَ[g[مّ]َا كَشَفْنَا عَنْهُمُ [h:6249[ٱ]لْعَذَابَ إِذَا هُمْ يَ[f:4968[نك]ُث[p[ُو]نَ","Бас, қачонки улардан азобни аритсанг, тўсатдан улар бузарлар.",493,25],["وَنَادَىٰ فِرْعَوْنُ فِى قَوْمِه[n[ِۦ] قَالَ يَ[n[ـٰ]قَوْمِ أَلَيْسَ لِى مُلْكُ مِصْرَ وَهَ[n[ـٰ]ذِهِ [h:12276[ٱ]لْأَنْهَ[n[ـٰ]رُ تَ[q:120[جْ]رِى مِ[f:12277[ن ت]َحْت[o[ِىٓ‌ۖ] أَفَلَا تُ[q:8674[بْ]صِر[p[ُو]نَ","Фиръавн ўз қавмига: «Эй қавмим! Миср мулки ва мана бу остимдан оқиб турган анҳорлар меники эмасми?! Кўрмаяпсизларми?!",493,25],["أَمْ أَنَا۟ خَيْ[a:1231[رٌ م]ِّنْ هَ[n[ـٰ]ذَا [h:126[ٱ]لَّذِى هُوَ مَهِي[a:12278[نٌ و]َلَا يَكَادُ يُب[p[ِي]نُ","Мен мана бу хор, гапини очиқ баён қила олмайдиган кимсадан яхши эмасманми?",493,25],["فَلَوْل[o[َآ] أُلْقِىَ عَلَيْهِ أَسْوِرَ[a:12279[ةٌ م]ِّ[f:8050[ن ذ]َهَبٍ أَوْ ج[o[َا]ٓءَ مَعَهُ [h:12280[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ مُ[q:12281[قْ]تَرِن[p[ِي]نَ","Унга тиллодан бўлган билакузуклар ташланса ёки у билан бирга фаришталар ҳамроҳ бўлиб келса бўлмас эдими?!» деб нидо қилди.",493,25],["فَ[h:9999[ٱ]سْتَخَفَّ قَوْمَهُ[n[ۥ] فَأَطَاعُوهُ‌ۚ إِ[g[نّ]َهُمْ كَانُو[s[اْ] قَوْ[f:5652[مًا ف]َ[n[ـٰ]سِق[p[ِي]نَ","Бас, у қавмини лақиллатди ва улар унга итоат қилдилар. Чунки улар фосиқ қавм эдилар.",493,25],["فَلَ[g[مّ][o[َآ] ءَاسَفُونَا [h:12282[ٱ][f:12283[نت]َقَمْنَا مِنْهُمْ فَأَغْرَ[q:4970[قْ]نَ[n[ـٰ]هُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Бас, қачонки улар Бизни дарғазаб қилишгач, улардан интиқом олдик–уларнинг барчаларини жамлаб, ғарқ қилдик.",493,25],["فَجَعَلْنَ[n[ـٰ]هُمْ سَلَ[a:12284[فًا و]َمَثَل[u:12285[اً ل]ِّلْأَخِر[p[ِي]نَ","Бас, уларни ўтмишга айлантирдик ва кейингиларга мисол қилиб қўйдик.",493,25],["۞ وَلَ[g[مّ]َا ضُرِبَ [h:12286[ٱ][q:1917[بْ]نُ مَرْيَمَ مَثَلاً إِذَا قَوْمُكَ مِنْهُ يَصِدّ[p[ُو]نَ","Ибн Марям мисол келтирилган чоқда сенинг қавминг бирдан шодланиб қичқирурлар.",493,25],["وَقَال[o[ُوٓ][s[اْ] ءَأ[n[َٲ]لِهَتُنَا خَيْرٌ أَمْ هُوَ‌ۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَل[i:12287[اَۢ‌ۚ ب]َلْ هُمْ قَوْمٌ خَصِم[p[ُو]نَ","Улар: «Бизнинг олиҳаларимиз яхшими ёки уми?» дедилар. Улар уни сенга фақат талашиб-тортишиш учунгина мисол келтирдилар. Зеро, улар хусуматчи қавмдирлар.",493,25],["إِنْ هُوَ إِلَّا عَ[q:12288[بْ]دٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَ[n[ـٰ]هُ مَثَل[u:12289[اً ل]ِّبَن[o[ِىٓ] إِسْر[o[َٲ]ٓء[p[ِي]لَ","У фақат бир бандадир. Биз унга неъмат бердик ва уни Бани Исроилга мисол қилдик.",493,25],["وَلَوْ نَش[o[َا]ٓءُ لَجَعَلْنَا مِ[f:344[نك][w:12290[ُم م]َّلَ[o[ـٰٓ]ئِكَ[f:12291[ةً ف]ِى [h:44[ٱ]لْأَرْضِ يَخْلُف[p[ُو]نَ","Агар хоҳласак, ўрнингизга ер юзида халифа бўладиган фаришталар қилиб қўяр эдик.",493,25],["وَإِ[g[نّ]َهُ[n[ۥ] لَعِلْ[u:12292[مٌ ل]ِّلسَّاعَةِ فَلَا تَمْتَرُ[g[نّ]َ بِهَا وَ[h:12293[ٱ]تَّبِعُونِ‌ۚ هَ[n[ـٰ]ذَا صِر[n[َٲ][a:1947[طٌ م]ُّسْتَق[p[ِي]مٌ","Албатта, у қиёмат соати илми-белгисидир. Бас, сиз у ҳақида ҳеч шубҳа қилманг ва Менга эргашинг. Мана шу тўғри йўлдир.",494,25],["وَلَا يَصُدَّ[g[نّ]َكُمُ [h:12294[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ‌ۖ إِ[g[نّ]َهُ[n[ۥ] لَكُمْ عَدُ[a:873[وٌّ م]ُّب[p[ِي]نٌ","Шайтон сизни ҳаргиз тўсмасин. Албатта, у сизга очиқ-ойдин душмандир.",494,25],["وَلَ[g[مّ]َا ج[o[َا]ٓءَ عِيسَىٰ بِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ قَالَ قَ[q:298[دْ] جِئْتُك[c:12295[ُم ب]ِ[h:7635[ٱ]لْحِكْمَةِ وَلِأُبَيِّنَ لَك[c:1942[ُم ب]َعْضَ [h:1943[ٱ]لَّذِى تَخْتَلِفُونَ فِيهِ‌ۖ فَ[h:112[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ وَأَطِيع[p[ُو]نِ","Ийсо очиқ-ойдин мўъжизалар билан келган чоғида: «Батаҳқиқ, мен сизга ҳикматни келтирдим ва баъзи сиз ихтилоф қилаётган нарсаларни баён қилиш учун келдим. Бас, Аллоҳга тақво ва менга итоат қилинглар.",494,25],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ هُوَ رَبِّى وَرَبُّكُمْ فَ[h:1946[ٱ]عْبُدُوهُ‌ۚ هَ[n[ـٰ]ذَا صِر[n[َٲ][a:1947[طٌ م]ُّسْتَق[p[ِي]مٌ","Албатта, Аллоҳ менинг ҳам Роббим, сизнинг ҳам Роббингиздир. Бас, Унга ибодат қилинг. Мана шу тўғри йўлдир», деди.",494,25],["فَ[h:9999[ٱ]خْتَلَفَ [h:8334[ٱ]لْأَحْزَابُ م[i:8335[ِنۢ ب]َيْنِهِمْ‌ۖ فَوَيْ[u:396[لٌ ل]ِّلَّذِينَ ظَلَمُو[s[اْ] مِنْ عَذَابِ يَوْمٍ أَل[p[ِي]مٍ","Бас, уларнинг орасидан фирқалар ихтилоф қилдилар. Зулм қилганлар ҳолига аламли кун азобидан вой бўлсин!",494,25],["هَلْ يَ[f:1141[نظ]ُرُونَ إِلَّا [h:12296[ٱ][l[ل]سَّاعَةَ أَ[f:6843[ن ت]َأْتِيَه[c:12297[ُم ب]َغْتَ[a:4880[ةً و]َهُمْ لَا يَشْعُر[p[ُو]نَ","Улар фақат ўзлари ҳам сезмай қолган ҳолда соати келиб қолишини кутмоқдалар, холос.",494,25],["ٱلْأَخِلّ[o[َا]ٓءُ يَوْمَئِ[i:12298[ذِۭ ب]َعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا [h:12299[ٱ]لْمُتَّق[p[ِي]نَ","Ўша кунда тақводорлардан бошқа дўстлар бир-бирларига душмандир.",494,25],["يَ[n[ـٰ]عِبَادِ لَا خَوْفٌ عَلَيْكُمُ [h:6811[ٱ]لْيَوْمَ وَل[o[َآ] أَ[f:428[نت]ُمْ تَحْزَن[p[ُو]نَ","Эй бандаларим! Бугунги кунда сизга хавф йўқ ва маҳзун ҳам бўлмассиз.",494,25],["ٱلَّذِينَ ءَامَنُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا وَكَانُو[s[اْ] مُسْلِم[p[ِي]نَ","Оятларимизга иймон келтирганлар ва мусулмон бўлганлар.",494,25],["ٱ[q:278[دْ]خُلُو[s[اْ] [h:4726[ٱ]لْجَ[g[نّ]َةَ أَ[f:428[نت]ُمْ وَأَزْو[n[َٲ]جُكُمْ تُحْبَر[p[ُو]نَ","Жаннатга киринглар, сизлар ва жуфтларингиз шод бўлурсизлар.",494,25],["يُطَافُ عَلَيْه[c:12300[ِم ب]ِصِحَا[a:12301[فٍ م]ِّ[f:8050[ن ذ]َهَ[a:12302[بٍ و]َأَكْوَا[a:12303[بٍ‌ۖ و]َفِيهَا مَا تَشْتَهِيهِ [h:12304[ٱ]لْأَ[f:3181[نف]ُسُ وَتَلَذُّ [h:12305[ٱ]لْأَعْيُنُ‌ۖ وَأَ[f:98[نت]ُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Уларга тиллодан бўлган товоқлар ва қадаҳлар айлантирилур. У ерда кўнгил иштаҳа қиладиган ва кўзлар лаззатланадиган нарсалар бордир. Сизлар у ерда абадий қолурсизлар.",494,25],["وَتِلْكَ [h:12306[ٱ]لْجَ[g[نّ]َةُ [h:8380[ٱ]لَّت[o[ِىٓ] أُورِثْتُمُوهَا بِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Мана шу қилиб юрган амалларингиз сабабли сизга мерос қилиб берилган жаннатдир.",494,25],["لَكُمْ فِيهَا فَ[n[ـٰ]كِهَ[f:12307[ةٌ ك]َثِيرَ[a:12308[ةٌ م]ِّنْهَا تَأْكُل[p[ُو]نَ","Сизга у ерда кўплаб мевалар бор, улардан ерсизлар.",494,25],["إِ[g[نّ]َ [h:12309[ٱ]لْمُ[q:4093[جْ]رِمِينَ فِى عَذَابِ جَهَ[g[نّ]َمَ خَ[n[ـٰ]لِد[p[ُو]نَ","Албатта, жиноятчилар жаҳаннам азобида абадий қолурлар.",495,25],["لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُ[q:4051[بْ]لِس[p[ُو]نَ","У улардан енгиллатилмас ва улар у да ноумид ҳолда қолурлар.",495,25],["وَمَا ظَلَمْنَ[n[ـٰ]هُمْ وَلَ[n[ـٰ]كِ[f:276[ن ك]َانُو[s[اْ] هُمُ [h:12310[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Биз уларга зулм қилганимиз йўқ. Лекин улар ўзлари золим бўлдилар.",495,25],["وَنَادَوْ[s[اْ] يَ[n[ـٰ]مَ[n[ـٰ]لِكُ لِيَ[q:12311[قْ]ضِ عَلَيْنَا رَبُّكَ‌ۖ قَالَ إِ[g[نّ]َك[w:12312[ُم م]َّ[n[ـٰ]كِث[p[ُو]نَ","Улар: «Эй Молик! Роббинг бизни битирсин!» деб нидо қилдилар. У: «Албатта, сиз туриб қолгувчисиз», деди.",495,25],["لَقَ[q:2389[دْ] جِئْنَ[n[ـٰ]ك[c:12313[ُم ب]ِ[h:370[ٱ]لْحَقِّ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَكُمْ لِلْحَقِّ كَ[n[ـٰ]رِه[p[ُو]نَ","Батаҳқиқ, Биз сизга ҳақни келтирдик. Лекин кўпларингиз ҳақни ёмон кўргувчисиз.",495,25],["أَمْ أَ[q:12314[بْ]رَم[o[ُوٓ][s[اْ] أَمْ[f:12315[رًا ف]َإِ[g[نّ]َا مُ[q:12316[بْ]رِم[p[ُو]نَ","Ёки улар бирон ишга қарор қилдиларми? Бас, Биз, албатта, қарор қилгувчимиз.",495,25],["أَمْ يَحْسَبُونَ أَ[g[نّ]َا لَا نَسْمَعُ سِرَّهُمْ وَنَ[q:5735[جْ]وَ[n[ٮٰ]ه[c:12317[ُم‌ۚ ب]َلَىٰ وَرُسُلُنَا لَدَيْهِمْ يَكْتُب[p[ُو]نَ","Ёки улар Бизни уларнинг сирларини ва пичирлашиб қилган маслаҳатларини эшитмайди деб ҳисоблайдиларми? Йўқ! Ҳолбуки, элчиларимиз уларнинг олдиларида ёзмоқдалар.",495,25],["قُلْ إِ[f:2594[ن ك]َانَ لِلرَّحْمَ[n[ـٰ]نِ وَلَ[f:12318[دٌ ف]َأَنَا۟ أَوَّلُ [h:12319[ٱ]لْعَ[n[ـٰ]بِد[p[ِي]نَ","Сен: «Агар Роҳманнинг боласи бўлганида, мен унга ибодат қилгувчиларнинг биринчиси бўлар эдим», деб айт.",495,25],["سُ[q:7648[بْ]حَ[n[ـٰ]نَ رَبِّ [h:12320[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ رَبِّ [h:8707[ٱ]لْعَرْشِ عَ[g[مّ]َا يَصِف[p[ُو]نَ","Осмонлару ернинг Робби, Аршнинг Робби улар қилаётган васфдан покдир.",495,25],["فَذَرْهُمْ يَخُوضُو[s[اْ] وَيَلْعَبُو[s[اْ] حَتَّىٰ يُلَ[n[ـٰ]قُو[s[اْ] يَوْمَهُمُ [h:12321[ٱ]لَّذِى يُوعَد[p[ُو]نَ","Бас, уларни қўйиб бер, ўзларига ваъда қилинаётган кунга рўбарў бўлгунларича шўнғийверсинлар, ўйнайверсинлар.",495,25],["وَهُوَ [h:4114[ٱ]لَّذِى فِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ إِلَ[n[ـٰ][a:12322[هٌ و]َفِى [h:3922[ٱ]لْأَرْضِ إِلَ[n[ـٰ][a:12323[هٌ‌ۚ و]َهُوَ [h:3967[ٱ]لْحَكِيمُ [h:12324[ٱ]لْعَل[p[ِي]مُ","У зот осмонда ҳам илоҳдир, ерда ҳам илоҳдир. У зот ўта ҳикматли, ўта илмлидир.",495,25],["وَتَبَارَكَ [h:12325[ٱ]لَّذِى لَهُ[n[ۥ] مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَيْنَهُمَا وَعِ[f:4104[ند]َهُ[n[ۥ] عِلْمُ [h:10616[ٱ][l[ل]سَّاعَةِ وَإِلَيْهِ تُرْجَع[p[ُو]نَ","Осмонлару ернинг ва уларнинг орасидаги нарсаларнинг мулкига эга бўлган зот баракотли-буюкдир. соати илми Унинг ҳузуридадир. Унгагина қайтарилурсизлар.",495,25],["وَلَا يَمْلِكُ [h:12326[ٱ]لَّذِينَ يَ[q:1240[دْ]عُونَ مِ[f:3136[ن د]ُونِهِ [h:12327[ٱ][l[ل]شَّفَ[n[ـٰ]عَةَ إِلَّا مَ[f:12328[ن ش]َهِدَ بِ[h:370[ٱ]لْحَقِّ وَهُمْ يَعْلَم[p[ُو]نَ","Аллоҳдан ўзга илтижо қилаётган нарсалари шафоатга эга бўлмаслар. Магар билган ҳолларида ҳақ шаҳодат берганларгина.",495,25],["وَلَئِ[f:5683[ن س]َأَلْتَه[w:10403[ُم م]َّنْ خَلَقَهُمْ لَيَقُولُ[g[نّ]َ [h:10404[ٱ]للَّهُ‌ۖ فَأَ[g[نّ]َىٰ يُؤْفَك[p[ُو]نَ","Агар сен улардан ўзларини ким яратганини сўрасанг, албатта, «Аллоҳ», дерлар. Бас, қаёққа бурилиб кетмоқдалар?!",495,25],["وَقِيلِه[n[ِۦ] يَ[n[ـٰ]رَبِّ إِ[g[نّ]َ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ قَوْ[u:3651[مٌ ل]َّا يُؤْمِن[p[ُو]نَ","Унинг: «Эй Роббим, албатта, анавилар иймон келтирмайдиган қавмлардир», деган гапини ҳам.",495,25],["فَ[h:9999[ٱ]صْفَحْ عَنْهُمْ وَقُلْ سَلَ[n[ـٰ][f:12329[مٌ‌ۚ ف]َسَوْفَ يَعْلَم[p[ُو]نَ","Бас, сен улардан юз ўгир ва: «Сизларга салом бўлсин», дегин. Бас, улар тезда билурлар.",495,25]]},{"n":44,"ar":"الدُّخَانِ","en":"Ad-Dukhaan","uz":"Духон","type":"Макка","ayahs":[["ح[m[مٓ]","Ҳа-а. Мийм.",496,25],["وَ[h:9999[ٱ]لْكِتَ[n[ـٰ]بِ [h:12190[ٱ]لْمُب[p[ِي]نِ","Очиқ-ойдин Китобга қасам.",496,25],["إِ[g[نّ][o[َآ] أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ فِى لَيْلَ[a:12330[ةٍ م]ُّبَ[n[ـٰ]رَكَةٍ‌ۚ إِ[g[نّ]َا كُ[g[نّ]َا مُ[f:11387[نذ]ِر[p[ِي]نَ","Албатта, Биз уни муборак кечада нозил қилдик. Албатта, Биз огоҳлантиргувчи бўлдик.",496,25],["فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَك[p[ِي]مٍ","Ўшада ҳар бир ҳикматли иш ажратилиб, ҳал қилинур.",496,25],["أَمْ[a:12331[رًا م]ِّنْ عِ[f:6142[ند]ِن[o[َآ‌ۚ] إِ[g[نّ]َا كُ[g[نّ]َا مُرْسِل[p[ِي]نَ","Биз томонимиздан бўлган амрга биноан. Албатта, Биз Пайғамбар юборгувчи бўлдик.",496,25],["رَحْمَ[a:5993[ةً م]ّ[u:770[ِن ر]َّبِّكَ‌ۚ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:3721[ٱ][l[ل]سَّمِيعُ [h:669[ٱ]لْعَل[p[ِي]مُ","Роббинг томонидан раҳматдир. Албатта, Унинг Ўзи ўта эшитгувчи, ўта билгувчи зотдир.",496,25],["رَبِّ [h:12320[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَيْنَهُم[o[َآ‌ۖ] إِ[f:109[ن ك]ُ[f:100[نت][w:9736[ُم م]ُّوقِن[p[ِي]نَ","Осмонлару ернинг ва уларнинг орасидаги нарсаларнинг Роббидир. Гар ишонгувчи бўлсангиз.",496,25],["ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ يُحْى[n[ِۦ] وَيُمِيتُ‌ۖ رَبُّكُمْ وَرَبُّ ءَاب[o[َا]ٓئِكُمُ [h:9737[ٱ]لْأَوَّل[p[ِي]نَ","Ундан ўзга ибодатга сазовор зот йўқ. У тирилтирур ва ўлдирур. У сизнинг Роббингиз ва ота- боболарингизнинг Роббидир.",496,25],["بَلْ هُمْ فِى شَ[a:12332[كٍّ ي]َلْعَب[p[ُو]نَ","Йўқ! Улар шак-шубҳада, ўйнамоқдалар.",496,25],["فَ[h:9999[ٱ]رْتَقِ[q:12333[بْ] يَوْمَ تَأْتِى [h:12334[ٱ][l[ل]سَّم[o[َا]ٓءُ بِدُخَا[a:12335[نٍ م]ُّب[p[ِي]نٍ","Бас, осмон аниқ тутунни келтирадиган кунни кут.",496,25],["يَغْشَى [h:12336[ٱ][l[ل][g[نّ]َاسَ‌ۖ هَ[n[ـٰ]ذَا عَذَابٌ أَل[p[ِي]مٌ","У одамларни ўраб олур. Бу аламли азобдир.",496,25],["رَّبَّنَا [h:12337[ٱ]كْشِفْ عَ[g[نّ]َا [h:12338[ٱ]لْعَذَابَ إِ[g[نّ]َا مُؤْمِن[p[ُو]نَ","Эй Роббимиз! Биздан азобни кушойиш қил! Албатта, Биз иймон келтиргувчидирмиз.",496,25],["أَ[g[نّ]َىٰ لَهُمُ [h:12339[ٱ][l[ل]ذِّكْرَىٰ وَقَ[q:387[دْ] ج[o[َا]ٓءَهُمْ رَسُو[a:12340[لٌ م]ُّب[p[ِي]نٌ","Уларга қаёқдан ҳам эслатма бўлсин. Ҳолбуки, уларга очиқ-ойдин Пайғамбар келган эди.",496,25],["ثُ[g[مّ]َ تَوَلَّوْ[s[اْ] عَنْهُ وَقَالُو[s[اْ] مُعَلَّ[a:12341[مٌ م]َّ[q:12342[جْ]ن[p[ُو]نٌ","Сўнгра ундан юз ўгирдилар ва: «Бу ўргатилган мажнун», дедилар.",496,25],["إِ[g[نّ]َا كَاشِفُو[s[اْ] [h:12343[ٱ]لْعَذَابِ قَلِيلاً‌ۚ إِ[g[نّ]َكُمْ ع[o[َا]ٓئِد[p[ُو]نَ","Албатта, Биз азобни озгина кушойиш қилгувчимиз. Албатта, сизлар қайтгувчисизлар.",496,25],["يَوْمَ نَ[q:12344[بْ]طِشُ [h:12345[ٱ]لْبَ[q:12346[طْ]شَةَ [h:12347[ٱ]لْكُ[q:8463[بْ]رَ[o[ىٰٓ] إِ[g[نّ]َا مُ[f:10659[نت]َقِم[p[ُو]نَ","Катта ушлаш ила ушлаганимиз куни, албатта, Биз интиқом олгувчимиз.",496,25],["۞ وَلَقَ[q:341[دْ] فَتَ[g[نّ]َا قَ[q:8394[بْ]لَهُمْ قَوْمَ فِرْعَوْنَ وَج[o[َا]ٓءَهُمْ رَسُو[f:12348[لٌ ك]َر[p[ِي]مٌ","Батаҳқиқ, улардан олдин Фиръавн қавмини синадик. Уларга карамли Пайғамбар келди.",496,25],["أَنْ أَدّ[o[ُوٓ][s[اْ] إِلَىَّ عِبَادَ [h:11354[ٱ]للَّهِ‌ۖ إِ[g[نّ]ِى لَكُمْ رَسُولٌ أَم[p[ِي]نٌ","«Сизлар менга Аллоҳнинг бандаларини беринглар. Албатта, мен сизларга ишончли Пайғамбарман.",496,25],["وَأ[u:6269[َن ل]َّا تَعْلُو[s[اْ] عَلَى [h:412[ٱ]للَّهِ‌ۖ إِ[g[نّ][o[ِىٓ] ءَاتِيك[c:12349[ُم ب]ِسُلْطَ[n[ـٰ][a:7067[نٍ م]ُّب[p[ِي]نٍ","Ва Аллоҳга мутакаббирлик қилманг. Албатта, мен сизга очиқ-ойдин ҳужжат келтирурман.",497,25],["وَإِ[g[نّ]ِى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَ[f:12350[ن ت]َرْجُم[p[ُو]نِ","Ва, албатта, мен ўзимнинг Роббим ва сизнинг Роббингиздан мени тошбўрон қилишингиздан паноҳ сўрадим.",497,25],["وَإ[u:3542[ِن ل]َّمْ تُؤْمِنُو[s[اْ] لِى فَ[h:12351[ٱ]عْتَزِل[p[ُو]نِ","Ва агар менга иймон келтирмасангиз, мендан четланинг», деб.",497,25],["فَدَعَا رَبَّهُ[o[ۥٓ] أَ[g[نّ]َ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ قَوْ[a:12352[مٌ م]ُّ[q:12353[جْ]رِم[p[ُو]نَ","Бас, у Роббига: «Албатта, анавилар жиноятчи қавмдир», деб дуо қилди.",497,25],["فَأَسْرِ بِعِبَادِى لَيْلاً إِ[g[نّ]َك[w:9755[ُم م]ُّتَّبَع[p[ُو]نَ","Бас, бандаларим ила кечаси юриб кет. Албатта, сиз изингиздан қувилурсиз.",497,25],["وَ[h:9999[ٱ]تْرُكِ [h:12354[ٱ]لْبَحْرَ رَهْوًا‌ۖ إِ[g[نّ]َهُمْ جُن[a:12355[دٌ م]ُّغْرَق[p[ُو]نَ","Ва денгизни сокин ҳолида қўй, албатта, улар ғарқ қилинадиган қўшиндир.",497,25],["كَمْ تَرَكُو[s[اْ] مِ[f:9759[ن ج]َ[g[نّ]َ[n[ـٰ][a:7257[تٍ و]َعُي[p[ُو]نٍ","Улар ортларидан қанчадан-қанча боғу роғларни ва булоқларни.",497,25],["وَزُرُو[a:12356[عٍ و]َمَقَا[f:9761[مٍ ك]َر[p[ِي]مٍ","Экинзорларни ва яхши жойларни.",497,25],["وَنَعْمَ[f:12357[ةٍ ك]َانُو[s[اْ] فِيهَا فَ[n[ـٰ]كِه[p[ِي]نَ","Ва ўзлари ичида маза қилаётган нозу неъматларни қолдирдилар.",497,25],["كَذ[n[َٲ]لِكَ‌ۖ وَأَوْرَثْنَ[n[ـٰ]هَا قَوْمًا ءَاخَر[p[ِي]نَ","Мана шундай! Биз уларни бошқа қавмларга мерос қилиб бердик.",497,25],["فَمَا بَكَتْ عَلَيْهِمُ [h:12358[ٱ][l[ل]سَّم[o[َا]ٓءُ وَ[h:2241[ٱ]لْأَرْضُ وَمَا كَانُو[s[اْ] مُ[f:7202[نظ]َر[p[ِي]نَ","Бас, уларга осмон ҳам, ер ҳам йиғламади ва улар муҳлат берилганлардан ҳам бўлмадилар.",497,25],["وَلَقَ[q:341[دْ] نَجَّيْنَا بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ مِنَ [h:503[ٱ]لْعَذَابِ [h:10965[ٱ]لْمُه[p[ِي]نِ","Батаҳқиқ, Бани Исроилга хорловчи азобдан.",497,25],["مِ[f:6159[ن ف]ِرْعَوْنَ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ عَالِ[a:12359[يًا م]ِّنَ [h:12360[ٱ]لْمُسْرِف[p[ِي]نَ","Фиръавндан нажот бердик. Албатта, у мутакаббир ва ҳаддидан ошганлардан эди.",497,25],["وَلَقَدِ [h:12361[ٱ]خْتَرْنَ[n[ـٰ]هُمْ عَلَىٰ عِلْمٍ عَلَى [h:227[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Батаҳқиқ, Биз уларни билиб туриб, оламлар ичидан танлаб олдик.",497,25],["وَءَاتَيْنَ[n[ـٰ]ه[w:12362[ُم م]ِّنَ [h:1969[ٱ]لْأَيَ[n[ـٰ]تِ مَا فِيهِ بَلَ[o[ـٰٓ][a:12363[ؤٌاْ م]ُّب[p[ِي]نٌ","Ва уларга оят-мўъзижалардан ичида очиқ-ойдин синов бор нарсаларни бердик.",497,25],["إِ[g[نّ]َ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ لَيَقُول[p[ُو]نَ","Албатта, анавилар дерлар:",497,25],["إِنْ هِىَ إِلَّا مَوْتَتُنَا [h:12364[ٱ]لْأُولَىٰ وَمَا نَحْنُ بِمُ[f:12365[نش]َر[p[ِي]نَ","«Биринчи ўлимимиздан бошқа ҳеч қандай ўлим йўқ ва биз қайта тирилтирилувчи эмасмиз.",497,25],["فَأْتُو[s[اْ] بِـَٔـاب[o[َا]ٓئِن[o[َآ] إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Агар ростгўй бўлсангиз, ота-боболаримизни келтиринглар».",497,25],["أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّ[a:12366[عٍ و]َ[h:37[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ أَهْلَكْنَ[n[ـٰ]هُمْ‌ۖ إِ[g[نّ]َهُمْ كَانُو[s[اْ] مُ[q:4958[جْ]رِم[p[ِي]نَ","Улар яхшироқми ёки Туббаъ қавмию улардан олдин ўтганларми?! Биз уларни ҳалок қилдик. Албатта, улар жиноятчи бўлган эдилар.",497,25],["وَمَا خَلَ[q:5159[قْ]نَا [h:7298[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَمَا بَيْنَهُمَا لَ[n[ـٰ]عِب[p[ِي]نَ","Осмонлару ерни ва уларнинг орасидаги нарсаларни ўйнаб яратганимиз йўқ!",497,25],["مَا خَلَ[q:12367[قْ]نَ[n[ـٰ]هُم[o[َآ] إِلَّا بِ[h:370[ٱ]لْحَقِّ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَعْلَم[p[ُو]نَ","Биз уларни фақат ҳақ ила яратдик, лекин кўплари билмаслар.",497,25],["إِ[g[نّ]َ يَوْمَ [h:12368[ٱ]لْفَصْلِ مِيقَ[n[ـٰ]تُهُمْ أَ[q:825[جْ]مَع[p[ِي]نَ","Албатта, ажратиш куни барчалари учун белгиланган вақтдир.",498,25],["يَوْمَ لَا يُغْنِى مَوْلًى ع[a:12369[َن م]َّوْ[f:12370[لًى ش]َيْـ[a:232[ـًٔا و]َلَا هُمْ يُ[f:237[نص]َر[p[ُو]نَ","У кунда дўст дўстга бирон нарсада асқотмас ва уларга ёрдам ҳам берилмас.",498,25],["إِلَّا م[u:6349[َن ر]َّحِمَ [h:12371[ٱ]للَّهُ‌ۚ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:1734[ٱ]لْعَزِيزُ [h:9718[ٱ][l[ل]رَّح[p[ِي]مُ","Магар кимга Аллоҳ раҳм қилсагина. Албатта, У азиз ва ўта раҳмли зотдир.",498,25],["إِ[g[نّ]َ شَجَرَتَ [h:12372[ٱ][l[ل]زَّقّ[p[ُو]مِ","Албатта, Заққум дарахти.",498,25],["طَعَامُ [h:12373[ٱ]لْأَث[p[ِي]مِ","Гуноҳкорлар таомидир.",498,25],["كَ[h:9999[ٱ]لْمُهْلِ يَغْلِى فِى [h:12374[ٱ]لْبُط[p[ُو]نِ","У худди эритилган маъдандек қоринларда қайнайдир.",498,25],["كَغَلْىِ [h:12375[ٱ]لْحَم[p[ِي]مِ","Қайноқ сувнинг қайнашига ўхшайдир.",498,25],["خُذُوهُ فَ[h:12376[ٱ]عْتِلُوهُ إِلَىٰ سَو[o[َا]ٓءِ [h:11370[ٱ]لْجَح[p[ِي]مِ","Уни тутиб, жаҳиймнинг ўртасига судраб олиб боринглар!",498,25],["ثُ[g[مّ]َ صُبُّو[s[اْ] فَوْقَ رَأْسِه[n[ِۦ] مِنْ عَذَابِ [h:12377[ٱ]لْحَم[p[ِي]مِ","Сўнгра боши устидан қайноқ сув азобини қуйинглар!",498,25],["ذُ[q:12378[قْ] إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:680[ٱ]لْعَزِيزُ [h:12379[ٱ]لْكَر[p[ِي]مُ","Тотиб кўр! Албатта, сен ўзинг «азизу мукаррамсан»!",498,25],["إِ[g[نّ]َ هَ[n[ـٰ]ذَا مَا كُ[f:100[نت][c:6084[ُم ب]ِه[n[ِۦ] تَمْتَر[p[ُو]نَ","Албатта, бу сиз шубҳа қилиб юрган нарсадир!",498,25],["إِ[g[نّ]َ [h:7256[ٱ]لْمُتَّقِينَ فِى مَقَامٍ أَم[p[ِي]نٍ","Албатта, тақводорлар омонлик жойида.",498,25],["فِى جَ[g[نّ]َ[n[ـٰ][a:7257[تٍ و]َعُي[p[ُو]نٍ","Боғу роғлар ва булоқларда бўлурлар.",498,25],["يَلْبَسُونَ مِ[f:8053[ن س]ُ[f:8054[ند]ُ[a:8055[سٍ و]َإِسْتَ[q:8056[بْ]رَ[a:12380[قٍ م]ُّتَقَ[n[ـٰ]بِل[p[ِي]نَ","Улар шойи ипак киюрлар, бир-бирларига юзма-юз ҳолда.",498,25],["كَذ[n[َٲ]لِكَ وَزَوَّ[q:12381[جْ]نَ[n[ـٰ]ه[c:12382[ُم ب]ِحُورٍ ع[p[ِي]نٍ","Ана шундай! Ва Биз уларни ҳури ийнларга уйлантирдик.",498,25],["يَ[q:1240[دْ]عُونَ فِيهَا بِكُلِّ فَ[n[ـٰ]كِهَةٍ ءَامِن[p[ِي]نَ","Улар у ерда омонлик ҳолларида турли меваларни чақирурлар.",498,25],["لَا يَذُوقُونَ فِيهَا [h:12383[ٱ]لْمَوْتَ إِلَّا [h:12384[ٱ]لْمَوْتَةَ [h:12385[ٱ]لْأُولَىٰ‌ۖ وَوَقَ[n[ـٰ]هُمْ عَذَابَ [h:11780[ٱ]لْجَح[p[ِي]مِ","Улар у ерда биринчи ўлимдан бошқа ўлимни тотмаслар. У зот уларни жаҳийм азобидан сақлар.",498,25],["فَضْل[a:1088[اً م]ّ[u:770[ِن ر]َّبِّكَ‌ۚ ذ[n[َٲ]لِكَ هُوَ [h:5722[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Бу Роббингдан бўлган фазлдир. Ана шу улкан ютуқдир.",498,25],["فَإِ[g[نّ]َمَا يَسَّرْنَ[n[ـٰ]هُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّر[p[ُو]نَ","Бас, албатта, Биз уни сенинг тилинг ила осонлаштирдик. Шоядки эсласалар.",498,25],["فَ[h:9999[ٱ]رْتَقِ[q:12333[بْ] إِ[g[نّ]َه[w:12386[ُم م]ُّرْتَقِب[p[ُو]نَ","Бас, кутиб тур. Улар ҳам кутгувчидирлар.",498,25]]},{"n":45,"ar":"الجَاثِيَةِ","en":"Al-Jaathiya","uz":"Жосия","type":"Макка","ayahs":[["ح[m[مٓ]","Ҳа-а. Мийм.",499,25],["تَ[f:10623[نز]ِيلُ [h:10624[ٱ]لْكِتَ[n[ـٰ]بِ مِنَ [h:321[ٱ]للَّهِ [h:11613[ٱ]لْعَزِيزِ [h:2229[ٱ]لْحَك[p[ِي]مِ","Бу китобнинг нозил қилиниши азиз ва ўта ҳикматли Аллоҳдандир.",499,25],["إِ[g[نّ]َ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ لَأَيَ[n[ـٰ][u:12387[تٍ ل]ِّلْمُؤْمِن[p[ِي]نَ","Албатта, осмонлару ерда мўминлар учун оят-белгилар бордир.",499,25],["وَفِى خَلْقِكُمْ وَمَا يَبُثُّ مِ[f:4026[ن د][m[َا]ٓبَّةٍ ءَايَ[n[ـٰ][u:12388[تٌ ل]ِّقَوْ[a:621[مٍ ي]ُوقِن[p[ُو]نَ","Ва сизларнинг яратилишингизда ва таратиб қўйган жониворларда аниқ ишонадиган қавм учун оят-белгилар бор.",499,25],["وَ[h:9999[ٱ]خْتِلَ[n[ـٰ]فِ [h:833[ٱ]لَّيْلِ وَ[h:834[ٱ][l[ل][g[نّ]َهَارِ وَم[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[u:6099[ِن ر]ِّزْ[f:12389[قٍ ف]َأَحْيَا بِهِ [h:842[ٱ]لْأَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ [h:845[ٱ][l[ل]رِّيَ[n[ـٰ]حِ ءَايَ[n[ـٰ][u:12388[تٌ ل]ِّقَوْ[a:850[مٍ ي]َعْقِل[p[ُو]نَ","Кечаю кундузнинг алмашиб туришида, Аллоҳ осмондан ризқ нозил қилиб, унинг ила ерни ўлимидан кейин тирилтиришида ва шамолларни не йўналишида ақл юритадиган қавм учун оят-белгилар бор.",499,25],["تِلْكَ ءَايَ[n[ـٰ]تُ [h:1442[ٱ]للَّهِ نَتْلُوهَا عَلَيْكَ بِ[h:370[ٱ]لْحَقِّ‌ۖ فَبِأَىِّ حَدِي[i:12390[ثِۭ ب]َعْدَ [h:12391[ٱ]للَّهِ وَءَايَ[n[ـٰ]تِه[n[ِۦ] يُؤْمِن[p[ُو]نَ","Булар Аллоҳнинг оятларидир. Биз уларни сенга ҳақ ила тиловат қилурмиз. Улар Аллоҳни ва Унинг оятларини қўйиб, қайси гапга иймон келтирурлар?!",499,25],["وَيْ[u:12392[لٌ ل]ِّكُلِّ أَفَّاكٍ أَث[p[ِي]مٍ","Ҳар бир ёлғончи гуноҳкорга ҳалокат бўлсин!",499,25],["يَسْمَعُ ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ تُتْلَىٰ عَلَيْهِ ثُ[g[مّ]َ يُصِرُّ مُسْتَكْبِ[f:10551[رًا ك]َأ[u:2914[َن ل]َّمْ يَسْمَعْهَا‌ۖ فَبَشِّرْهُ بِعَذَابٍ أَل[p[ِي]مٍ","У ўзига тиловат қилинган Аллоҳнинг оятларини эшитади-ю, сўнгра худди эшитмагандек мутакаббирлик қилиб туриб олади. Бас, унга аламли азоб хушхабарини бер.",499,25],["وَإِذَا عَلِمَ مِنْ ءَايَ[n[ـٰ]تِنَا شَيْــًٔا [h:12393[ٱ]تَّخَذَهَا هُزُوًا‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ لَهُمْ عَذَا[a:478[بٌ م]ُّه[p[ِي]نٌ","Қачонки Бизнинг оятларимиздан бирор нарса билса, уни истеҳзо қилади. Ана ўшаларга хорловчи азоб бордир.",499,25],["مّ[a:12394[ِن و]َر[o[َا]ٓئِهِمْ جَهَ[g[نّ]َمُ‌ۖ وَلَا يُغْنِى عَنْه[w:3985[ُم م]َّا كَسَبُو[s[اْ] شَيْـ[a:232[ـًٔا و]َلَا مَا [h:12395[ٱ]تَّخَذُو[s[اْ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ أَوْلِي[o[َا]ٓءَ‌ۖ وَلَهُمْ عَذَابٌ عَظ[p[ِي]مٌ","Ва ортларида жаҳаннам бор. Уларга касб қилган нарсалари ҳам, Аллоҳни қўйиб тутган «дўстлари» ҳам ҳеч бир нарсада асқотмас. Уларга улкан азоб бордир.",499,25],["هَ[n[ـٰ]ذَا هُ[a:12396[دًى‌ۖ و]َ[h:37[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ رَبِّهِمْ لَهُمْ عَذَا[a:10923[بٌ م]ّ[u:10924[ِن ر]ِّ[q:10925[جْ]زٍ أَل[p[ِي]مٌ","Бу ҳидоятдир. Роббилари оятларига куфр келтирганларга аламли азобнинг ашаддийси бордир.",499,25],["۞ ٱللَّهُ [h:4738[ٱ]لَّذِى سَخَّرَ لَكُمُ [h:12397[ٱ]لْبَحْرَ لِتَ[q:7132[جْ]رِىَ [h:12398[ٱ]لْفُلْكُ فِيهِ بِأَمْرِه[n[ِۦ] وَلِتَ[q:7353[بْ]تَغُو[s[اْ] مِ[f:475[ن ف]َضْلِه[n[ِۦ] وَلَعَلَّكُمْ تَشْكُر[p[ُو]نَ","Аллоҳ сизга денгизни унда Ўз амри билан кемалар юриши учун ва сиз Унинг фазлидан исташингиз учун бўйсундириб қўйди. Шоядки, шукр келтирсангиз.",499,25],["وَسَخَّرَ لَك[w:154[ُم م]َّا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ جَمِي[a:12399[عًا م]ِّنْهُ‌ۚ إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَأَيَ[n[ـٰ][u:849[تٍ ل]ِّقَوْ[a:6018[مٍ ي]َتَفَكَّر[p[ُو]نَ","Ва сизга осмонлардаги нарсаларни ва ердаги нарсаларни—ҳаммасини Ўз томонидан бўйсундириб қўйди. Албатта, ана шунда тафаккур қиладиган қавм учун оят-белгилар бордир.",499,25],["قُل لِّلَّذِينَ ءَامَنُو[s[اْ] يَغْفِرُو[s[اْ] لِلَّذِينَ لَا يَرْجُونَ أَيَّامَ [h:12400[ٱ]للَّهِ لِيَ[q:5945[جْ]زِىَ قَوْم[i:12401[َۢا ب]ِمَا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Сен иймон келтирганларга айт. Аллоҳнинг кунларидан умидвор бўлмайдиганларни кечирсинлар. Токи У зот бу қавмни касб қилиб юрган нарсалари учун мукофотласин.",500,25],["مَنْ عَمِلَ صَ[n[ـٰ]لِ[f:12053[حًا ف]َلِنَفْسِه[n[ِۦ]‌ۖ وَمَنْ أَس[o[َا]ٓءَ فَعَلَيْهَا‌ۖ ثُ[g[مّ]َ إِلَىٰ رَبِّكُمْ تُرْجَع[p[ُو]نَ","Ким солиҳ амал қилса, ўзига фойда. Ким ёмонлик қилса, ўзига зарар. Сўнгра Роббингизга қайтарилурсиз.",500,25],["وَلَقَ[q:341[دْ] ءَاتَيْنَا بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ [h:11906[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:2046[ٱ]لْحُكْمَ وَ[h:2047[ٱ][l[ل][g[نّ]ُبُوَّةَ وَرَزَ[q:6191[قْ]نَ[n[ـٰ]ه[w:6192[ُم م]ِّنَ [h:5307[ٱ][l[ل]طَّيِّبَ[n[ـٰ]تِ وَفَضَّلْنَ[n[ـٰ]هُمْ عَلَى [h:227[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Батаҳқиқ, биз Бани Исроилга китобни, ҳукмни ва Пайғамбарликни бердик, уларга пок нарсаларни ризқ қилиб бердик ва уларни оламлар ичида афзал қилдик.",500,25],["وَءَاتَيْنَ[n[ـٰ]ه[c:12402[ُم ب]َيِّنَ[n[ـٰ][a:12403[تٍ م]ِّنَ [h:2233[ٱ]لْأَمْرِ‌ۖ فَمَا [h:6193[ٱ]خْتَلَف[o[ُوٓ][s[اْ] إِلَّا م[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَهُمُ [h:1804[ٱ]لْعِلْمُ بَغْي[i:1169[َۢا ب]َيْنَهُمْ‌ۚ إِ[g[نّ]َ رَبَّكَ يَ[q:6194[قْ]ضِى بَيْنَهُمْ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ فِيمَا كَانُو[s[اْ] فِيهِ يَخْتَلِف[p[ُو]نَ","Ва Биз уларга иши ҳақида очиқ-ойдин баёнотлар бердик. Бас, улар ўзларига илм келганидан сўнг ўзаро ҳасад-адоват қилибгина ихтилофга тушдилар. Албатта, Роббинг улар орасида қиёмат куни ихтилоф қилган нарсалари ҳақида ҳукм чиқарур.",500,25],["ثُ[g[مّ]َ جَعَلْنَ[n[ـٰ]كَ عَلَىٰ شَرِيعَ[a:12404[ةٍ م]ِّنَ [h:2233[ٱ]لْأَمْرِ فَ[h:12405[ٱ]تَّبِعْهَا وَلَا تَتَّبِعْ أَهْو[o[َا]ٓءَ [h:4516[ٱ]لَّذِينَ لَا يَعْلَم[p[ُو]نَ","Сўнгра Биз сени ишида бир шариатга йўлладик. Бас, унга эргаш, билмайдиганларнинг ҳавои нафсларига эргашма.",500,25],["إِ[g[نّ]َهُمْ ل[a:12406[َن ي]ُغْنُو[s[اْ] عَ[f:626[نك]َ مِنَ [h:321[ٱ]للَّهِ شَيْـ[a:12407[ـًٔا‌ۚ و]َإِ[g[نّ]َ [h:9074[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ بَعْضُهُمْ أَوْلِي[o[َا]ٓءُ بَعْ[a:1863[ضٍ‌ۖ و]َ[h:72[ٱ]للَّهُ وَلِىُّ [h:12408[ٱ]لْمُتَّق[p[ِي]نَ","Албатта, улар сендан Аллоҳ томонидан бўладиган ҳеч бир нарсани арита олмаслар. Ва, албатта, золимлар бир-бирларига дўстдирлар. Аллоҳ тақводорларнинг дўстидир.",500,25],["هَ[n[ـٰ]ذَا بَصَ[o[ـٰٓ]ئِرُ لِل[g[نّ]َاسِ وَهُ[a:4547[دًى و]َرَحْمَ[u:5218[ةٌ ل]ِّقَوْ[a:621[مٍ ي]ُوقِن[p[ُو]نَ","Бу одамлар учун қалб кўзлари, аниқ ишонадиган қавм учун ҳидоят ва раҳматдир.",500,25],["أَمْ حَسِبَ [h:10282[ٱ]لَّذِينَ [h:12409[ٱ][q:12410[جْ]تَرَحُو[s[اْ] [h:12411[ٱ][l[ل]سَّيِّـَٔـاتِ أ[a:12412[َن ن]َّ[q:12413[جْ]عَلَهُمْ كَ[h:2146[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ سَو[o[َا]ٓ[a:12414[ءً م]َّحْيَاهُمْ وَمَمَاتُهُمْ‌ۚ س[o[َا]ٓءَ مَا يَحْكُم[p[ُو]نَ","Наҳотки ёмонликларни қилганлар уларни иймон келтириб, солиҳ амаллар қилганларга ўхшаш қилмоғимизни, ҳаётлари ҳам, мамотлари ҳам баробар бўлишини гумон қилсалар?! Уларнинг қилган ҳукми нақадар ҳам ёмон!",500,25],["وَخَلَقَ [h:12415[ٱ]للَّهُ [h:10377[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ بِ[h:370[ٱ]لْحَقِّ وَلِتُ[q:12416[جْ]زَىٰ كُلُّ نَفْ[i:6995[سِۭ ب]ِمَا كَسَبَتْ وَهُمْ لَا يُظْلَم[p[ُو]نَ","Аллоҳ осмонлару ерни ҳақ ила, ҳар бир жон қилган касбига яраша, зулм қилинмаган ҳолида жазосини олиши учун яратган.",500,25],["أَفَرَءَيْتَ مَنِ [h:8418[ٱ]تَّخَذَ إِلَ[n[ـٰ]هَهُ[n[ۥ] هَوَ[n[ٮٰ]هُ وَأَضَلَّهُ [h:12417[ٱ]للَّهُ عَلَىٰ عِلْ[a:12418[مٍ و]َخَتَمَ عَلَىٰ سَمْعِه[n[ِۦ] وَقَلْبِه[n[ِۦ] وَجَعَلَ عَلَىٰ بَصَرِه[n[ِۦ] غِشَ[n[ـٰ]وَ[f:12419[ةً ف]َم[a:12420[َن ي]َهْدِيهِ م[i:146[ِنۢ ب]َعْدِ [h:12421[ٱ]للَّهِ‌ۚ أَفَلَا تَذَكَّر[p[ُو]نَ","Айтинг-чи, ҳавои нафсини илоҳ қилиб олган, Аллоҳ уни билиб туриб залолатга солган ва қулоғига ҳамда қалбига муҳр босиб, кўзига парда тортиб қўйган кимсани Аллоҳдан бошқа ким ҳидоят қила олади?! Эсламайсизларми?!",501,25],["وَقَالُو[s[اْ] مَا هِىَ إِلَّا حَيَاتُنَا [h:3995[ٱ][l[ل]دُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُن[o[َآ] إِلَّا [h:12422[ٱ][l[ل]دَّهْرُ‌ۚ وَمَا لَه[c:12225[ُم ب]ِذ[n[َٲ]لِكَ مِنْ عِلْمٍ‌ۖ إِنْ هُمْ إِلَّا يَظُ[g[نّ][p[ُو]نَ","Улар: «У фақат бу дунёдаги ҳаётимиздир. Ўламиз, тириламиз, бизни фақат замон ҳалок қилади», дерлар. Уларнинг бу ҳақда илмлари йўқ. Улар фақат гумон қиладилар, холос.",501,25],["وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَ[n[ـٰ]تُنَا بَيِّنَ[n[ـٰ][a:12423[تٍ م]َّا كَانَ حُجَّتَهُمْ إِلّ[o[َآ] أَ[f:2304[ن ق]َالُو[s[اْ] [h:12424[ٱ]ئْتُو[s[اْ] بِـَٔـاب[o[َا]ٓئِن[o[َآ] إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Уларга очиқ-ойдин оятларимиз тиловат қилинган чоғда: «Агар ростгўй бўлсангиз, ота-боболаримизни келтиринг-чи?!» дейишдан бошқа ҳужжатлари бўлмас.",501,25],["قُلِ [h:3166[ٱ]للَّهُ يُحْيِيكُمْ ثُ[g[مّ]َ يُمِيتُكُمْ ثُ[g[مّ]َ يَ[q:12425[جْ]مَعُكُمْ إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ لَا رَيْبَ فِيهِ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَ [h:1374[ٱ][l[ل][g[نّ]َاسِ لَا يَعْلَم[p[ُو]نَ","Сен: «Аллоҳ сизларни тирилтирур, сўнгра ўлдирур, сўнгра сизларни шубҳа йўқ қиёмат кунида жамлар. Лекин одамларнинг кўплари билмаслар», деб айт.",501,25],["وَلِلَّهِ مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَيَوْمَ تَقُومُ [h:10435[ٱ][l[ل]سَّاعَةُ يَوْمَئِ[a:12426[ذٍ ي]َخْسَرُ [h:12427[ٱ]لْمُ[q:5131[بْ]طِل[p[ُو]نَ","Ва осмонлару ернинг мулки Аллоҳникидир. Қиёмат соати қоим бўладиган кунда, ўша кунда ботилчилар зиён тортурлар.",501,25],["وَتَرَىٰ كُلَّ أُ[g[مّ]َ[f:12428[ةٍ ج]َاثِيَ[f:12429[ةً‌ۚ ك]ُلُّ أُ[g[مّ]َ[f:12430[ةٍ ت]ُ[q:12431[دْ]عَ[o[ىٰٓ] إِلَىٰ كِتَ[n[ـٰ]بِهَا [h:12432[ٱ]لْيَوْمَ تُ[q:4248[جْ]زَوْنَ مَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Ҳар бир умматни тиз чўккан ҳолида кўрурсан. Ҳар бир уммат ўз номаи амалига чақирилур: «Бугунги кунда қилиб юрган амалларингиз бўйича жазо олурсиз»,.",501,25],["هَ[n[ـٰ]ذَا كِتَ[n[ـٰ]بُنَا يَ[f:9237[نط]ِقُ عَلَيْك[c:12433[ُم ب]ِ[h:370[ٱ]لْحَقِّ‌ۚ إِ[g[نّ]َا كُ[g[نّ]َا نَسْتَ[f:12434[نس]ِخُ مَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","«Мана бу китобимиз сизга ҳақни нутқ қилур. Албатта, Биз қилган амалингизни ёзиб турган эдик».",501,25],["فَأَ[g[مّ]َا [h:136[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ فَيُ[q:12435[دْ]خِلُهُمْ رَبُّهُمْ فِى رَحْمَتِه[n[ِۦ]‌ۚ ذ[n[َٲ]لِكَ هُوَ [h:5722[ٱ]لْفَوْزُ [h:3961[ٱ]لْمُب[p[ِي]نُ","Бас, иймон келтириб солиҳ амалларни қилганларни Роббилари Ўз раҳматига киритур. Ана ўшанинг ўзи очиқ-ойдин ютуқдир.",501,25],["وَأَ[g[مّ]َا [h:138[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أَفَلَمْ تَكُنْ ءَايَ[n[ـٰ]تِى تُتْلَىٰ عَلَيْكُمْ فَ[h:12436[ٱ]سْتَكْبَرْتُمْ وَكُ[f:151[نت]ُمْ قَوْ[a:4957[مًا م]ُّ[q:4958[جْ]رِم[p[ِي]نَ","Аммо куфр келтирганларга эса: «Ахир сизга Менинг оятларим тиловат қилинмаганмиди?! Бас, сиз мутакаббирлик қилдингиз ва жиноятчи қавм бўлдингиз.",501,25],["وَإِذَا قِيلَ إِ[g[نّ]َ وَعْدَ [h:3149[ٱ]للَّهِ حَ[a:12437[قٌّ و]َ[h:12438[ٱ][l[ل]سَّاعَةُ لَا رَيْبَ فِيهَا قُلْت[w:9357[ُم م]َّا نَ[q:12439[دْ]رِى مَا [h:12440[ٱ][l[ل]سَّاعَةُ إ[a:12441[ِن ن]َّظُ[g[نّ]ُ إِلَّا ظَن[a:12442[ًّا و]َمَا نَحْنُ بِمُسْتَيْقِن[p[ِي]نَ","Вақтики: «Албатта, Аллоҳнинг ваъдаси ҳақдир ва соатида шубҳа йўқдир», дейилса, «Қиёмат соати нима эканини билмасмиз. Биз фақат гумон қиламиз, холос. Биз аниқ ишонгувчи эмасмиз, дедингиз»,.",501,25],["وَبَدَا لَهُمْ سَيِّـَٔـاتُ مَا عَمِلُو[s[اْ] وَحَاقَ بِه[w:6252[ِم م]َّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Ва уларга қилган амалларининг ёмонликлари ўзларига аён бўлди ва уларни ўзлари истеҳзо қилиб юрган нарса ўраб олди. Уларга куфр ва исёнлари учун бериладиган жазо аниқ кўринди ва ўзларича, охират азоби ҳам бўлармиди, деб истеҳзо қилиб юрган азоб уларни ўраб олди.",502,25],["وَقِيلَ [h:12443[ٱ]لْيَوْمَ نَ[f:12444[نس]َ[n[ـٰ]كُمْ كَمَا نَسِيتُمْ لِق[o[َا]ٓءَ يَوْمِكُمْ هَ[n[ـٰ]ذَا وَمَأْوَ[n[ٮٰ]كُمُ [h:10339[ٱ][l[ل][g[نّ]َارُ وَمَا لَك[w:556[ُم م]ّ[a:1813[ِن ن]َّ[n[ـٰ]صِر[p[ِي]نَ","«Бугунги кунда худди сиз ушбу кунингизга рўбарў бўлишни унутганингиздек, Биз ҳам сизни унутурмиз. Жойингиз жаҳаннамдир ва сизларга ҳеч ёрдамчилар йўқ.",502,25],["ذ[n[َٲ]لِك[c:12445[ُم ب]ِأَ[g[نّ]َكُمُ [h:12446[ٱ]تَّخَذْتُمْ ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ هُزُ[a:12447[وًا و]َغَرَّتْكُمُ [h:12448[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَا‌ۚ فَ[h:4730[ٱ]لْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَب[p[ُو]نَ","Бундай бўлишингиз, албатта, сизнинг Аллоҳнинг оятларини масхара қилиб олганингиз ва сизни дунё ҳаёти ғурурга кетказгани учундир», дейилди. Бас, бугунги кунда улар удан чиқарилмаслар ва улар итобга ҳам қайтарилмаслар. Жаҳанам азобида қийналиб турган кофиру осийларга айтиладиган бу гаплар, улар учун жуда ҳам оғир маънавий азоб бўлади. Яъни, сиз ёруғ дунёда қиёмат кунига рўбарў бўлишни қандай унутган бўлсангиз, биз ҳам сизни шундай унутамиз. Яъни, сизга раҳм қилишни унутамиз.",502,25],["فَلِلَّهِ [h:12449[ٱ]لْحَمْدُ رَبِّ [h:12320[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَرَبِّ [h:12450[ٱ]لْأَرْضِ رَبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Бас, барча ҳамд осмонларнинг Роббига, ернинг Роббига ва оламларнинг Роббигадир.",502,25],["وَلَهُ [h:12451[ٱ]لْكِ[q:6146[بْ]رِي[o[َا]ٓءُ فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Осмонлару ердаги улуғлик Уникидир. У зот азизу ҳакимдир.",502,25]]},{"n":46,"ar":"الأَحۡقَافِ","en":"Al-Ahqaf","uz":"Аҳқоф","type":"Макка","ayahs":[["ح[m[مٓ]","Ҳа мийм.",502,26],["تَ[f:10623[نز]ِيلُ [h:10624[ٱ]لْكِتَ[n[ـٰ]بِ مِنَ [h:321[ٱ]للَّهِ [h:11613[ٱ]لْعَزِيزِ [h:2229[ٱ]لْحَك[p[ِي]مِ","Китобнинг туширилиши Ғолиб ва ҳикматли Аллоҳ тарафидандир.",502,26],["مَا خَلَ[q:5159[قْ]نَا [h:7298[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَمَا بَيْنَهُم[o[َآ] إِلَّا بِ[h:370[ٱ]لْحَقِّ وَأَجَ[a:10428[لٍ م]ُّسَم[a:12452[ًّى‌ۚ و]َ[h:37[ٱ]لَّذِينَ كَفَرُو[s[اْ] عَ[g[مّ][o[َآ] أُ[f:8133[نذ]ِرُو[s[اْ] مُعْرِض[p[ُو]نَ","Осмонлару ерни ҳамда улар ўртасидаги нарсаларни фақат ҳақ ва белгиланган муддат ила яратдик. Кофирлар бўлса, ўзлари огоҳлантирилган нарсадан юз ўгурувчилардир.",502,26],["قُلْ أَرَءَيْت[w:6098[ُم م]َّا تَ[q:4040[دْ]عُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ أَرُونِى مَاذَا خَلَقُو[s[اْ] مِنَ [h:1579[ٱ]لْأَرْضِ أَمْ لَهُمْ شِرْ[f:11154[كٌ ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ‌ۖ [h:12453[ٱ]ئْتُونِى بِكِتَ[n[ـٰ][a:10187[بٍ م]ِّ[f:1346[ن ق]َ[q:1347[بْ]لِ هَ[n[ـٰ]ذ[o[َآ] أَوْ أَثَ[n[ـٰ]رَ[a:12454[ةٍ م]ِّنْ عِلْمٍ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Сен: « Аллоҳдан ўзга сиғинаётган нарсаларингизнинг хабарини беринг-чи, менга кўрсатинг-чи, улар ердан нимани яратдилар? Ёки осмонларни иштироклари борми? Агар ростгўй бўлсаларингиз, менга бундан олдинги китобни ёки илмий асарни келтиринг.»- деб айт.",502,26],["وَمَنْ أَضَلُّ مِ[g[مّ][a:12455[َن ي]َ[q:1242[دْ]عُو[s[اْ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ م[u:6065[َن ل]َّا يَسْتَجِيبُ لَهُ[o[ۥٓ] إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ وَهُمْ عَ[f:12456[ن د]ُع[o[َا]ٓئِهِمْ غَ[n[ـٰ]فِل[p[ُو]نَ","Аллоҳни қўйиб, қиёмат кунигича дуосини мустажоб қилолмайдиганларга илтижо этадиганлардан ҳам адашганроқлар борми?! Ҳолбуки, Улар уларнинг дуосидан ғофилдирлар.",502,26],["وَإِذَا حُشِرَ [h:12457[ٱ][l[ل][g[نّ]َاسُ كَانُو[s[اْ] لَهُمْ أَعْد[o[َا]ٓ[a:12458[ءً و]َكَانُو[s[اْ] بِعِبَادَتِهِمْ كَ[n[ـٰ]فِر[p[ِي]نَ","Одамлар маҳшарга тўпланганда, уларга душман бўлурлар ва ибодатларига ҳам мункир бўлурлар.",503,26],["وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَ[n[ـٰ]تُنَا بَيِّنَ[n[ـٰ][f:5979[تٍ ق]َالَ [h:590[ٱ]لَّذِينَ كَفَرُو[s[اْ] لِلْحَقِّ لَ[g[مّ]َا ج[o[َا]ٓءَهُمْ هَ[n[ـٰ]ذَا سِحْ[a:3879[رٌ م]ُّب[p[ِي]نٌ","Қачонки уларга равшан оятларимиз тиловот қилинса, куфр келтирганлар Ҳақ уларга келгандаёқ, бу очиқ-ойдин сеҳрдир, дерлар.",503,26],["أَمْ يَقُولُونَ [h:6061[ٱ]فْتَرَ[n[ٮٰ]هُ‌ۖ قُلْ إِنِ [h:6311[ٱ]فْتَرَيْتُهُ[n[ۥ] فَلَا تَمْلِكُونَ لِى مِنَ [h:321[ٱ]للَّهِ شَيْــًٔا‌ۖ هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ‌ۖ كَفَىٰ بِه[n[ِۦ] شَهِيد[i:7033[َۢا ب]َيْنِى وَبَيْنَكُمْ‌ۖ وَهُوَ [h:6227[ٱ]لْغَفُورُ [h:6228[ٱ][l[ل]رَّح[p[ِي]مُ","Балки уни ўзи тўқиб олган ҳам дерлар. Сен: «Агар уни тўқиб олган бўлсам, Аллоҳдан бирор нарсани мендан қайтаришга қодир эмассиз. У зотнинг Ўзи ҳақида сиз шўнғиётган нарсаларни яхши билувчидир. Мен билан сизнинг ўртангизда гувоҳликка Унинг Ўзи кифоядир. Ва У кечирувчи ҳам раҳмли зотдир», деб айт.",503,26],["قُلْ مَا كُ[f:2917[نت]ُ بِ[q:12459[دْ][a:12460[عًا م]ِّنَ [h:3463[ٱ][l[ل]رُّسُلِ وَم[o[َآ] أَ[q:8888[دْ]رِى مَا يُفْعَلُ بِى وَلَا بِكُمْ‌ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَ[o[ىٰٓ] إِلَىَّ وَم[o[َآ] أَنَا۟ إِلَّا نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","Сен:»Мен биринчи Пайғамбар эмасман, менга ва сизларга нима қилинишини билмайсман. Фақат, ўзимга ваҳий қилинаётган нарсагагина эргашурман. Мен очиқ-ойдин огоҳлантирувчиман, холос», деб айт.",503,26],["قُلْ أَرَءَيْتُمْ إِ[f:2594[ن ك]َانَ مِنْ عِ[f:398[ند]ِ [h:399[ٱ]للَّهِ وَكَفَرْت[c:12461[ُم ب]ِه[n[ِۦ] وَشَهِدَ شَاهِ[a:6616[دٌ م]ّ[i:1385[ِنۢ ب]َن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ عَلَىٰ مِثْلِه[n[ِۦ] فَـَٔـامَنَ وَ[h:12462[ٱ]سْتَكْبَرْتُمْ‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Сен: «Айтинг-чи, агар у Аллоҳдан бўлса-ю, сиз унга куфр келтирсангиз ва ҳолбуки, Бани Исроилдан бир гувоҳ уга ўхшаш нарсага гувоҳлик бериб, иймон келтириб турибди, сиз эса, кибру ҳаво қиляпсиз. Албатта, Аллоҳ золим қавмларни ҳидоят қилмайди», деб айт.",503,26],["وَقَالَ [h:614[ٱ]لَّذِينَ كَفَرُو[s[اْ] لِلَّذِينَ ءَامَنُو[s[اْ] لَوْ كَانَ خَيْ[a:12463[رًا م]َّا سَبَقُون[o[َآ] إِلَيْهِ‌ۚ وَإِذْ لَمْ يَهْتَدُو[s[اْ] بِه[n[ِۦ] فَسَيَقُولُونَ هَ[n[ـٰ]ذ[o[َآ] إِفْ[f:12464[كٌ ق]َد[p[ِي]مٌ","Куфр келтирганлар иймон келтирганларга: «Агар у яхшилик бўлганида, унга биздан аввал бормасдилар», дерлар. Удан ҳидоят топишмагач, бу-қадимги уйдирмадир», дерлар.",503,26],["وَمِ[f:6275[ن ق]َ[q:1098[بْ]لِه[n[ِۦ] كِتَ[n[ـٰ]بُ مُوسَ[o[ىٰٓ] إِمَا[a:6276[مًا و]َرَحْمَ[a:12465[ةً‌ۚ و]َهَ[n[ـٰ]ذَا كِتَ[n[ـٰ][a:12466[بٌ م]ُّصَدِّ[u:12467[قٌ ل]ِّسَانًا عَرَبِي[u:12468[ًّا ل]ِّيُ[f:7947[نذ]ِرَ [h:12469[ٱ]لَّذِينَ ظَلَمُو[s[اْ] وَبُشْرَىٰ لِلْمُحْسِن[p[ِي]نَ","Удан олдин Мусонинг китоби йўл бошловчи ва раҳмат эди. Бу эса, араб тилидаги, тасдиқловчи, зулм қилувчиларни огоҳлантириш учун ва яхшиларга башорат китобидир.",503,26],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ قَالُو[s[اْ] رَبُّنَا [h:9034[ٱ]للَّهُ ثُ[g[مّ]َ [h:12021[ٱ]سْتَقَ[n[ـٰ]مُو[s[اْ] فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَن[p[ُو]نَ","Албатта «Роббимиз Аллоҳдир» деган, сўнгра бунда мустақим турганларга хавф йўқдир ва улар хафа ҳам бўлмаслар.",503,26],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:415[ٱ]لْجَ[g[نّ]َةِ خَ[n[ـٰ]لِدِينَ فِيهَا جَز[o[َا]ٓ[i:3537[ءَۢ ب]ِمَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Ана ўшалар жаннат эгаларидир, унда қилган амаллари мукофотига абадий қолурлар.",503,26],["وَوَصَّيْنَا [h:10289[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ بِو[n[َٲ]لِدَيْهِ إِحْسَ[n[ـٰ]نًا‌ۖ حَمَلَتْهُ أُ[g[مّ]ُهُ[n[ۥ] كُرْ[a:12470[هًا و]َوَضَعَتْهُ كُرْ[a:12471[هًا‌ۖ و]َحَمْلُهُ[n[ۥ] وَفِصَ[n[ـٰ]لُهُ[n[ۥ] ثَلَ[n[ـٰ]ثُونَ شَهْرًا‌ۚ حَتَّ[o[ىٰٓ] إِذَا بَلَغَ أَشُدَّهُ[n[ۥ] وَبَلَغَ أَرْبَعِينَ سَنَ[f:12472[ةً ق]َالَ رَبِّ أَوْزِعْن[o[ِىٓ] أَنْ أَشْكُرَ نِعْمَتَكَ [h:9922[ٱ]لَّت[o[ِىٓ] أَنْعَمْتَ عَلَىَّ وَعَلَىٰ و[n[َٲ]لِدَىَّ وَأَنْ أَعْمَلَ صَ[n[ـٰ]لِ[f:9923[حًا ت]َرْضَ[n[ـٰ]هُ وَأَصْلِحْ لِى فِى ذُرِّيَّت[o[ِىٓ‌ۖ] إِ[g[نّ]ِى تُ[q:2657[بْ]تُ إِلَيْكَ وَإِ[g[نّ]ِى مِنَ [h:6135[ٱ]لْمُسْلِم[p[ِي]نَ","Биз инсонни ота-онасига яхшилик қилишга буюрдик. Онаси унга қийланиб ҳомиладор бўлди ва уни қийланиб туғди. Ва унинг ҳомиласи ва кўкракдан ажратиши ўттиз ойдир. Токи у камолга етиб, қирқ ёшга кирганида: «Роббим Ўзинг менга ва ота-онамга берган неъматларингга шукр қилишимга ва сен рози бўлган солиҳ ишларни қилишимга илҳом бергин. Ва менинг зурриётларимни ҳам солиҳлардан қилгин. Албатта, мен тавба қилдим ва албатта, мен мусулмонларданман, деди.",504,26],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُو[s[اْ] وَنَتَجَاوَزُ عَ[f:12473[ن س]َيِّـَٔـاتِهِمْ ف[o[ِىٓ] أَصْحَ[n[ـٰ]بِ [h:12474[ٱ]لْجَ[g[نّ]َةِ‌ۖ وَعْدَ [h:12475[ٱ][l[ل]صِّ[q:12476[دْ]قِ [h:12477[ٱ]لَّذِى كَانُو[s[اْ] يُوعَد[p[ُو]نَ","Ана ўшаларнинг энг яхши амалларни қабул қилиб, ёмонликларини ўтиб юборурмиз. Улар жаннат эгаларидандир. Уларга берилган ҳақ ваъда шулдир.",504,26],["وَ[h:9999[ٱ]لَّذِى قَالَ لِو[n[َٲ]لِدَيْهِ أُ[u:12478[فٍّ ل]َّكُم[o[َآ] أَتَعِدَانِن[o[ِىٓ] أَنْ أُخْرَجَ وَقَ[q:387[دْ] خَلَتِ [h:12479[ٱ]لْقُرُونُ مِ[f:2470[ن ق]َ[q:2471[بْ]لِى وَهُمَا يَسْتَغِيثَانِ [h:12480[ٱ]للَّهَ وَيْلَكَ ءَامِنْ إِ[g[نّ]َ وَعْدَ [h:3149[ٱ]للَّهِ حَ[f:12481[قٌّ ف]َيَقُولُ مَا هَ[n[ـٰ]ذ[o[َآ] إِلّ[o[َآ] أَسَ[n[ـٰ]طِيرُ [h:3993[ٱ]لْأَوَّل[p[ِي]نَ","Ота-онасига: «Уфф сизларга, чиқарилишимнинг ваъдасини бераяпсизларми?! Мендан аввал ҳам асрлар ўтган-ку!» деган кишига, Аллоҳдан мадад сўраган ҳолда улар: «Ҳолингга вой бўлгур, иймон келтир, албатта, Аллоҳнинг ваъдаси ҳақдир», дедилар. У бўлса «Бу ўтганларнинг афсоналари, холос», дер.",504,26],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ حَقَّ عَلَيْهِمُ [h:10217[ٱ]لْقَوْلُ ف[o[ِىٓ] أُمَ[f:4671[مٍ ق]َ[q:298[دْ] خَلَتْ مِ[f:617[ن ق]َ[q:618[بْ]لِه[w:10662[ِم م]ِّنَ [h:4673[ٱ]لْجِ[g[نّ]ِ وَ[h:4418[ٱ]لْإِ[f:4418[نس]ِ‌ۖ إِ[g[نّ]َهُمْ كَانُو[s[اْ] خَ[n[ـٰ]سِر[p[ِي]نَ","Ана ўшаларга ўзларидан аввал ўтган жин ва инс умматлари қаторида сўзи ҳақ бўлгандир. Албатта, улар зиён кўрувчилардан бўлдилар.",504,26],["وَلِكُ[f:4427[لٍّ د]َرَجَ[n[ـٰ][a:4428[تٌ م]ِّ[g[مّ]َا عَمِلُو[s[اْ‌ۖ] وَلِيُوَفِّيَهُمْ أَعْمَ[n[ـٰ]لَهُمْ وَهُمْ لَا يُظْلَم[p[ُو]نَ","Ҳар бирларига қилган амалларига яраша даражалар бордир. Ва уларга амалларининг тўлиқ берилур ва уларга зулм қилинмас.",504,26],["وَيَوْمَ يُعْرَضُ [h:12482[ٱ]لَّذِينَ كَفَرُو[s[اْ] عَلَى [h:896[ٱ][l[ل][g[نّ]َارِ أَذْهَ[q:12483[بْ]تُمْ طَيِّبَ[n[ـٰ]تِكُمْ فِى حَيَاتِكُمُ [h:12484[ٱ][l[ل]دُّنْيَا وَ[h:12485[ٱ]سْتَمْتَعْت[c:12486[ُم ب]ِهَا فَ[h:4730[ٱ]لْيَوْمَ تُ[q:4248[جْ]زَوْنَ عَذَابَ [h:4249[ٱ]لْهُونِ بِمَا كُ[f:100[نت]ُمْ تَسْتَكْبِرُونَ فِى [h:44[ٱ]لْأَرْضِ بِغَيْرِ [h:325[ٱ]لْحَقِّ وَبِمَا كُ[f:100[نت]ُمْ تَفْسُق[p[ُو]نَ","Куфр келтирганлар дўзахга кўндаланг қилинган кунда: «Ҳаёти дунёдаёқ ҳузур ҳаловатингизни кетказиб, мазасини татиб бўлгансиз. Бугунги кунда ер юзида ноҳақ кибру ҳаво ва фисқу фасод қилганингиз учун хорлик азоби ила жазоланасиз», дейилур.",504,26],["۞ وَ[h:9999[ٱ]ذْكُرْ أَخَا عَادٍ إِذْ أَ[f:12487[نذ]َرَ قَوْمَهُ[n[ۥ] بِ[h:12488[ٱ]لْأَحْقَافِ وَقَ[q:387[دْ] خَلَتِ [h:12489[ٱ][l[ل][g[نّ]ُذُرُ م[i:4612[ِنۢ ب]َيْنِ يَدَيْهِ وَمِنْ خَلْفِه[o[ِۦٓ] أَلَّا تَعْبُد[o[ُوٓ][s[اْ] إِلَّا [h:416[ٱ]للَّهَ إِ[g[نّ][o[ِىٓ] أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظ[p[ِي]مٍ","Ўз қавмини қум тепаликларда огоҳлантирган Однинг биродарини эсла! Ва ҳолбуки, ундан аввал ҳам, кейин ҳам огоҳлантирувчилар ўтган. «У зотдан ўзгага ибодат қилманглар, албатта, мен улуғ кунда бошингизга тушадиган азобдан қўрқурман»,.",505,26],["قَال[o[ُوٓ][s[اْ] أَجِئْتَنَا لِتَأْفِكَنَا عَنْ ءَالِهَتِنَا فَأْتِنَا بِمَا تَعِدُن[o[َآ] إِ[f:4792[ن ك]ُ[f:735[نت]َ مِنَ [h:4793[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ِي]نَ","Улар: «Бизни худоларимиздан оздиришга келдингми? Агар ростгўйлардан бўлсанг, бизга ваъда қилаётган нарсангни келтир», дедилар.",505,26],["قَالَ إِ[g[نّ]َمَا [h:12490[ٱ]لْعِلْمُ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَأُبَلِّغُك[w:12491[ُم م]ّ[o[َآ] أُرْسِلْتُ بِه[n[ِۦ] وَلَ[n[ـٰ]كِ[g[نّ][o[ِىٓ] أَرَ[n[ٮٰ]كُمْ قَوْ[f:6298[مًا ت]َ[q:4984[جْ]هَل[p[ُو]نَ","У: «Албатта, илм Аллоҳнинг ҳузуридадир. Мен нима билан юборилган бўлсам, шуни етказмоқдаман. Лекин сизларнинг жоҳил қавмлигингизни кўриб турибман», деди.",505,26],["فَلَ[g[مّ]َا رَأَوْهُ عَارِ[a:12492[ضًا م]ُّسْتَ[q:12493[قْ]بِلَ أَوْدِيَتِهِمْ قَالُو[s[اْ] هَ[n[ـٰ]ذَا عَارِ[a:12494[ضٌ م]ُّمْطِرُنَا‌ۚ بَلْ هُوَ مَا [h:12495[ٱ]سْتَعْجَلْت[c:12496[ُم ب]ِه[n[ِۦ]‌ۖ رِي[f:12497[حٌ ف]ِيهَا عَذَابٌ أَل[p[ِي]مٌ","Унинг водийлари томон кўндаланг бўлиб юрганини кўришганда, бу кўндаланг бўлувчи, бизга ёмғир ёғдирур, дедилар. Йўқ! Бу ўзингиз орзиқиб сўраган нарса, аламли азоби бор бўрондир.",505,26],["تُدَ[g[مّ]ِرُ كُلَّ شَىْ[i:12498[ءِۭ ب]ِأَمْرِ رَبِّهَا فَأَصْبَحُو[s[اْ] لَا يُرَ[o[ىٰٓ] إِلَّا مَسَ[n[ـٰ]كِنُهُمْ‌ۚ كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:5976[ٱ]لْقَوْمَ [h:5977[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","У Роббисининг амри ила ҳар бир нарсани вайрон қилур. Бас, масканларидан бошқа нарса кўринмай қолди. Жиноятчи қавмларни шундоқ жазолайрмиз.",505,26],["وَلَقَ[q:341[دْ] مَكَّ[g[نّ]َ[n[ـٰ]هُمْ فِيم[o[َآ] إ[a:12499[ِن م]َّكَّ[g[نّ]َ[n[ـٰ]كُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْ[a:12500[عًا و]َأَ[q:12501[بْ]صَ[n[ـٰ][a:12502[رًا و]َأَفْــِٔدَ[f:12503[ةً ف]َم[o[َآ] أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَل[o[َآ] أَ[q:4718[بْ]صَ[n[ـٰ]رُهُمْ وَل[o[َآ] أَفْــِٔدَتُه[w:12504[ُم م]ِّ[f:2103[ن ش]َىْءٍ إِذْ كَانُو[s[اْ] يَ[q:4008[جْ]حَدُونَ بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ وَحَاقَ بِه[w:6252[ِم م]َّا كَانُو[s[اْ] بِه[n[ِۦ] يَسْتَهْزِء[p[ُو]نَ","Ва, дарҳақиқат, Биз уларга сизга бермаган имконларни берган эдик. Ҳамда қулоқ, кўз ва қалблар ато этдик. Бас, на қулоқлари, на кўзлари ва на қалблари уларга ҳеч бир фойда бермади. Чунки улар Аллоҳнинг оятларини инкор қилган эдилар. Бас, уларни ўзлари масхара қилган нарса ўраб олди.",505,26],["وَلَقَ[q:341[دْ] أَهْلَكْنَا مَا حَوْلَك[w:5812[ُم م]ِّنَ [h:12505[ٱ]لْقُرَىٰ وَصَرَّفْنَا [h:12506[ٱ]لْأَيَ[n[ـٰ]تِ لَعَلَّهُمْ يَرْجِع[p[ُو]نَ","Ҳақиқатда, атрофингиздаги шаҳар-қишлоқларни ҳалокатга учратдик ва шоядки, ўзларига қайтсалар, деб ҳужжат-далилларни баён қилдик.",505,26],["فَلَوْلَا نَصَرَهُمُ [h:12507[ٱ]لَّذِينَ [h:3645[ٱ]تَّخَذُو[s[اْ] مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ قُرْبَانًا ءَالِهَ[i:12508[ةَۢ‌ۖ ب]َلْ ضَلُّو[s[اْ] عَنْهُمْ‌ۚ وَذ[n[َٲ]لِكَ إِفْكُهُمْ وَمَا كَانُو[s[اْ] يَفْتَر[p[ُو]نَ","Қани энди, Аллоҳни қўйиб, яқинлаштирувчи деб тутинган худолари уларга ёрдам берсалар эди. Йўқ! Улар ғойиб бўлдилар ва бу уларнинг уйдирма ҳамда тўқиган бўҳтонларидир.",505,26],["وَإِذْ صَرَفْن[o[َآ] إِلَيْكَ نَفَ[a:12509[رًا م]ِّنَ [h:4673[ٱ]لْجِ[g[نّ]ِ يَسْتَمِعُونَ [h:12510[ٱ]لْقُرْءَانَ فَلَ[g[مّ]َا حَضَرُوهُ قَال[o[ُوٓ][s[اْ] أَ[f:12511[نص]ِتُو[s[اْ‌ۖ] فَلَ[g[مّ]َا قُضِىَ وَلَّوْ[s[اْ] إِلَىٰ قَوْمِه[w:12512[ِم م]ُّ[f:11387[نذ]ِر[p[ِي]نَ","Ва сен томон бир гуруҳ жинларни Қуръон эшитишга бурганимизни эсла. Унга ҳозир бўлганларида: «Жим, қулоқ осинглар!», дедилар. Қачонки, қироат охирлаганда, ўз қавмларига огоҳлантирувчи бўлиб қайтдилар:",506,26],["قَالُو[s[اْ] يَ[n[ـٰ]قَوْمَن[o[َآ] إِ[g[نّ]َا سَمِعْنَا كِتَ[n[ـٰ]بًا أُ[f:17[نز]ِلَ م[i:146[ِنۢ ب]َعْدِ مُوسَىٰ مُصَدِّ[u:206[قًا ل]ِّمَا بَيْنَ يَدَيْهِ يَهْد[o[ِىٓ] إِلَى [h:6050[ٱ]لْحَقِّ وَإِلَىٰ طَرِي[a:12513[قٍ م]ُّسْتَق[p[ِي]مٍ","«Эй, қавмимиз! Биз Мусодан кейин туширилган, ўзидан аввалги нарсаларни тасдиқловчи, ҳақга ва тўғри йўлга ҳидоят қилувчи китобни эшитдик.",506,26],["يَ[n[ـٰ]قَوْمَن[o[َآ] أَجِيبُو[s[اْ] دَاعِىَ [h:12514[ٱ]للَّهِ وَءَامِنُو[s[اْ] بِه[n[ِۦ] يَغْفِرْ لَك[w:556[ُم م]ِّ[f:7063[ن ذ]ُنُوبِكُمْ وَيُجِرْك[w:12515[ُم م]ِّنْ عَذَابٍ أَل[p[ِي]مٍ","Эй, қавмимиз, Аллоҳнинг даъватчисига жавоб беринг ва Унга иймон келтиринг: У зот сизларнинг гуноҳларингизни мағфират қиладир ва аламли азобдан сақлайдир.",506,26],["وَم[u:12516[َن ل]َّا يُجِ[q:12517[بْ] دَاعِىَ [h:12514[ٱ]للَّهِ فَلَيْسَ بِمُعْجِ[f:12518[زٍ ف]ِى [h:44[ٱ]لْأَرْضِ وَلَيْسَ لَهُ[n[ۥ] مِ[f:3136[ن د]ُونِه[o[ِۦٓ] أَوْلِي[o[َا]ٓءُ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Кимки, Аллоҳнинг даъватчисини қабул қилмаса, бас у ер юзида қочиб қутила олувчи эмасдир ва унга У зотдан ўзга валийлар ҳам йўқдир. Ана ўшалар очиқ-ойдин залолатдадир», дедилар.",506,26],["أَوَلَمْ يَرَوْ[s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ [h:2537[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَلَمْ يَعْىَ بِخَلْقِهِ[g[نّ]َ بِقَ[n[ـٰ]دِرٍ عَلَ[o[ىٰٓ] أ[a:12519[َن ي]ُحْــِۧىَ [h:12520[ٱ]لْمَوْتَىٰ‌ۚ بَلَ[o[ىٰٓ] إِ[g[نّ]َهُ[n[ۥ] عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Улар осмонлару ерни яратган ва уларни яратишда беҳол бўлмаган зот–Аллоҳ, ўликларни ҳам тирилтиришга қодир эканини англаб етмадиларми? Зеро, У зот ҳар бир нарсага қодирдир.",506,26],["وَيَوْمَ يُعْرَضُ [h:12482[ٱ]لَّذِينَ كَفَرُو[s[اْ] عَلَى [h:896[ٱ][l[ل][g[نّ]َارِ أَلَيْسَ هَ[n[ـٰ]ذَا بِ[h:370[ٱ]لْحَقِّ‌ۖ قَالُو[s[اْ] بَلَىٰ وَرَبِّنَا‌ۚ قَالَ فَذُوقُو[s[اْ] [h:2154[ٱ]لْعَذَابَ بِمَا كُ[f:100[نت]ُمْ تَكْفُر[p[ُو]نَ","Куфр келтирганлар дўзахга кўндаланг қилинган кунда: «Бу ҳақиқат эмасми?!». Улар, Роббимизга қасамки, худди шундоқ, дерлар. У зот: «Бас, куфр келтирганингиз учун азобни тотинглар», дер.",506,26],["فَ[h:9999[ٱ]صْبِرْ كَمَا صَبَرَ أُ[s[وْ]لُو[s[اْ] [h:12521[ٱ]لْعَزْمِ مِنَ [h:3463[ٱ][l[ل]رُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ‌ۚ كَأَ[g[نّ]َهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَث[o[ُوٓ][s[اْ] إِلَّا سَاعَ[a:12522[ةً م]ّ[a:12523[ِن ن]َّهَا[i:12524[رِۭ‌ۚ ب]َلَ[n[ـٰ][f:12525[غٌ‌ۚ ف]َهَلْ يُهْلَكُ إِلَّا [h:4061[ٱ]لْقَوْمُ [h:12526[ٱ]لْفَ[n[ـٰ]سِق[p[ُو]نَ","Бас, азму-матонат соҳиби бўлган Пайғамбарлар сабр қилгандек, сабр қил, уларга шошилма! Улар ваъда қилинган нарсани кўрганларида худди кундуздан бир лаҳзагина турганга ўхшарлар. Бу етказишдир! Бас, фақат фосиқ қавмларгина ҳалок қилинур!",506,26]]},{"n":47,"ar":"مُحَمَّدٍ","en":"Muhammad","uz":"Муҳаммад","type":"Мадина","ayahs":[["ٱلَّذِينَ كَفَرُو[s[اْ] وَصَدُّو[s[اْ] عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ أَضَلَّ أَعْمَ[n[ـٰ]لَهُمْ","Куфр келтирган ва Аллоҳнинг йўлидан тўсганларнинг амалларини У зот ботил қилди.",507,26],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ وَءَامَنُو[s[اْ] بِمَا نُزِّلَ عَلَىٰ مُحَ[g[مّ]َ[a:12527[دٍ و]َهُوَ [h:479[ٱ]لْحَقُّ م[u:22[ِن ر]َّبِّهِمْ‌ۙ كَفَّرَ عَنْهُمْ سَيِّـَٔـاتِهِمْ وَأَصْلَحَ بَالَهُمْ","У зот иймон келтирган, солиҳ амалларни қилган ва Муҳаммадга нозил қилинган нарсага–ҳолбуки у Роббиларидан келган ҳақдир–иймон келтирганларнинг айбларини беркитур ва аҳволларини яхшилар.",507,26],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َ [h:12528[ٱ]لَّذِينَ كَفَرُو[s[اْ] [h:12529[ٱ]تَّبَعُو[s[اْ] [h:12530[ٱ]لْبَ[n[ـٰ]طِلَ وَأَ[g[نّ]َ [h:7684[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:12531[ٱ]تَّبَعُو[s[اْ] [h:12532[ٱ]لْحَقَّ م[u:22[ِن ر]َّبِّهِمْ‌ۚ كَذ[n[َٲ]لِكَ يَضْرِبُ [h:6944[ٱ]للَّهُ لِل[g[نّ]َاسِ أَمْثَ[n[ـٰ]لَهُمْ","Ундоқ бўлишига, албатта, куфр келтирганларнинг ботилга эргашганлари ва иймон келтирганларнинг Роббиларидан бўлган ҳаққа эргашганликлари сабабдир. Аллоҳ кишиларга ўзларининг мисолларини шундай келтиради.",507,26],["فَإِذَا لَقِيتُمُ [h:5274[ٱ]لَّذِينَ كَفَرُو[s[اْ] فَضَرْبَ [h:12533[ٱ][l[ل]رِّقَابِ حَتَّ[o[ىٰٓ] إِذ[o[َآ] أَثْخَ[f:12534[نت]ُمُوهُمْ فَشُدُّو[s[اْ] [h:12535[ٱ]لْوَثَاقَ فَإِ[g[مّ]َا مَ[g[نّ][i:12536[َۢا ب]َعْدُ وَإِ[g[مّ]َا فِد[o[َا]ٓءً حَتَّىٰ تَضَعَ [h:12537[ٱ]لْحَرْبُ أَوْزَارَهَا‌ۚ ذ[n[َٲ]لِكَ وَلَوْ يَش[o[َا]ٓءُ [h:6988[ٱ]للَّهُ لَ[h:12538[ٱ][f:12538[نت]َصَرَ مِنْهُمْ وَلَ[n[ـٰ]ك[u:12539[ِن ل]ِّيَ[q:12540[بْ]لُوَ[s[اْ] بَعْضَك[c:12541[ُم ب]ِبَعْ[a:12542[ضٍ‌ۗ و]َ[h:37[ٱ]لَّذِينَ قُتِلُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ فَل[a:12543[َن ي]ُضِلَّ أَعْمَ[n[ـٰ]لَهُمْ","Қачонки куфр келтирганлар билан тўқнашсангиз, бас, бўйинига урмоқ керак. Вақтики, уларни тор-мор қилсангиз, бас, маҳкам боғланг. Сўнгра ёки миннат, ёки товон олишдир. Ҳаттоки уруш ўз анжомларни қўйгунча. Ана шундай. Аллоҳ хоҳласа, улардан Ўзи ғолиб келарди, лекин баъзиларингизни баъзиларингиз ила синаш учун. Аллоҳ йўлида қатл қилинганларнинг амалларни У зот ҳеч зое қилмас.",507,26],["سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ","Албатта, уларни ҳидоят қилар ва аҳволларни яхшилар.",507,26],["وَيُ[q:12544[دْ]خِلُهُمُ [h:12545[ٱ]لْجَ[g[نّ]َةَ عَرَّفَهَا لَهُمْ","Ҳамда Ўзи уларга таърифлаб берган жаннатга киритар.",507,26],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[f:12546[ن ت]َ[f:12547[نص]ُرُو[s[اْ] [h:12548[ٱ]للَّهَ يَ[f:12549[نص]ُرْكُمْ وَيُثَبِّتْ أَ[q:12550[قْ]دَامَكُمْ","Эй иймон келтирганлар! Агар Аллоҳга ёрдам берсангиз, сизга ҳам ёрдам берадир ва қадамларингизни собит қиладир.",507,26],["وَ[h:9999[ٱ]لَّذِينَ كَفَرُو[s[اْ] فَتَعْ[u:12551[سًا ل]َّهُمْ وَأَضَلَّ أَعْمَ[n[ـٰ]لَهُمْ","Ва куфр келтирганларга бахтсизлик ва амалларини зое қилиш бўлур.",507,26],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ كَرِهُو[s[اْ] م[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ فَأَحْبَطَ أَعْمَ[n[ـٰ]لَهُمْ","Бу уларнинг Аллоҳ нозил қилган нарсани хуш кўрмаганлари сабабидандир. Бас, У зот амалларини ботил қилди.",507,26],["۞ أَفَلَمْ يَسِيرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ فَيَ[f:6853[نظ]ُرُو[s[اْ] كَيْفَ كَانَ عَ[n[ـٰ]قِبَةُ [h:6854[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ دَ[g[مّ]َرَ [h:12552[ٱ]للَّهُ عَلَيْهِمْ‌ۖ وَلِلْكَ[n[ـٰ]فِرِينَ أَمْثَ[n[ـٰ]لُهَا","Ер юзида юриб, ўзларидан аввалгиларнинг оқибати қандоқ бўлганлигига назар солмасларми? Аллоҳ уларни вайрон қилди-ку! Кофирларга ҳам шунга ўхшаш бўлур.",507,26],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َ [h:897[ٱ]للَّهَ مَوْلَى [h:12553[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَأَ[g[نّ]َ [h:12554[ٱ]لْكَ[n[ـٰ]فِرِينَ لَا مَوْلَىٰ لَهُمْ","Шундоқ бўлиши, албатта, Аллоҳ иймон келтирганларга дўст эканлигидан ва албатта, кофирларга дўст йўқлигидандир.",507,26],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُ[q:8947[دْ]خِلُ [h:8948[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۖ وَ[h:37[ٱ]لَّذِينَ كَفَرُو[s[اْ] يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ [h:12555[ٱ]لْأَنْعَ[n[ـٰ]مُ وَ[h:12556[ٱ][l[ل][g[نّ]َارُ مَثْ[u:12007[وًى ل]َّهُمْ","Албатта, Аллоҳ иймон келтирганлар ва яхши амал қилганларни тагидан анҳорлар оқиб турган жаннатларга киритур. Куфр келтирганлар ҳузур қилурлар ва худди чорва ҳайвонлари егандек ерлар ва дўзах уларнинг жойидир.",508,26],["وَكَأَيّ[a:2298[ِن م]ِّ[f:4585[ن ق]َرْيَةٍ هِىَ أَشَدُّ قُوَّ[a:12557[ةً م]ِّ[f:12558[ن ق]َرْيَتِكَ [h:12559[ٱ]لَّت[o[ِىٓ] أَخْرَجَتْكَ أَهْلَكْنَ[n[ـٰ]هُمْ فَلَا نَاصِرَ لَهُمْ","Кўпгина шаҳарлар сени чиқарган шаҳарингдан кўра қувватлироқ эди, уларни ҳалок қилдик. Бас, уларга нусрат берувчи йўқдир.",508,26],["أَفَمَ[f:6273[ن ك]َانَ عَلَىٰ بَيِّنَ[a:4097[ةٍ م]ّ[u:192[ِن ر]َّبِّه[n[ِۦ] كَمَ[f:12560[ن ز]ُيِّنَ لَهُ[n[ۥ] س[o[ُو]ٓءُ عَمَلِه[n[ِۦ] وَ[h:2433[ٱ]تَّبَع[o[ُوٓ][s[اْ] أَهْو[o[َا]ٓءَهُم","Ўз Роббисидан ҳужжатга эга бўлган шахс ёмон амали ўзига зийнатли кўринган ва ҳавои нафсига эргашганларга ўхшаши мумкинми?!",508,26],["مَّثَلُ [h:7002[ٱ]لْجَ[g[نّ]َةِ [h:7003[ٱ]لَّتِى وُعِدَ [h:7004[ٱ]لْمُتَّقُونَ‌ۖ فِيه[o[َآ] أَنْهَ[n[ـٰ][a:12561[رٌ م]ّ[a:840[ِن م]ّ[o[َا]ٓءٍ غَيْرِ ءَاسِ[a:12562[نٍ و]َأَنْهَ[n[ـٰ][a:12563[رٌ م]ّ[u:12564[ِن ل]َّبَ[u:12565[نٍ ل]َّمْ يَتَغَيَّرْ طَعْمُهُ[n[ۥ] وَأَنْهَ[n[ـٰ][a:12563[رٌ م]ِّنْ خَمْ[u:12566[رٍ ل]َّذَّ[u:11361[ةٍ ل]ِّلشَّ[n[ـٰ]رِبِينَ وَأَنْهَ[n[ـٰ][a:12563[رٌ م]ِّنْ عَسَ[a:12567[لٍ م]ُّصَف[a:12568[ًّى‌ۖ و]َلَهُمْ فِيهَا مِ[f:843[ن ك]ُلِّ [h:1571[ٱ][l[ل]ثَّمَر[n[َٲ]تِ وَمَغْفِرَ[a:12569[ةٌ م]ّ[u:22[ِن ر]َّبِّهِمْ‌ۖ كَمَنْ هُوَ خَ[n[ـٰ]لِ[f:12570[دٌ ف]ِى [h:4674[ٱ][l[ل][g[نّ]َارِ وَسُقُو[s[اْ] م[o[َا]ٓءً حَمِي[f:12571[مًا ف]َقَطَّعَ أَمْع[o[َا]ٓءَهُمْ","Тақводорларга ваъда қилинган жаннатнинг мисоли: ичида айнимаган сувли анҳорлари, таъми ўзгармаган сутли анҳорлари, ичувчиларга лаззатбахш хамр-шаробли анҳорлари, мусаффо асалли анҳорлари бор. Улар учун у ерда барча мевалар ва ўз Роббиларидан мағфират бор. Ўшалар оташда мангу қолувчи ва ўта қайноқ сув ила суғорилиб, ичаклари титилиб кетган кимсага ўхшайдиларми?",508,26],["وَمِنْه[w:1106[ُم م]ّ[a:3986[َن ي]َسْتَمِعُ إِلَيْكَ حَتَّ[o[ىٰٓ] إِذَا خَرَجُو[s[اْ] مِنْ عِ[f:2954[ند]ِكَ قَالُو[s[اْ] لِلَّذِينَ أُوتُو[s[اْ] [h:7379[ٱ]لْعِلْمَ مَاذَا قَالَ ءَانِفًا‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ طَبَعَ [h:3271[ٱ]للَّهُ عَلَىٰ قُلُوبِهِمْ وَ[h:2433[ٱ]تَّبَع[o[ُوٓ][s[اْ] أَهْو[o[َا]ٓءَهُمْ","Ва улардан сенга қулоқ осадиганлари бор. Ҳузурингдан чиққанларида эса, илм берилганларга: «Ҳали у нима деди?» дерлар. Ана ўшалар қалбларига Аллоҳ тамға босганлар ва ҳавои нафсларига эргашганлардир.",508,26],["وَ[h:9999[ٱ]لَّذِينَ [h:12572[ٱ]هْتَدَوْ[s[اْ] زَادَهُمْ هُ[a:12573[دًى و]َءَاتَ[n[ـٰ]هُمْ تَ[q:12574[قْ]وَ[n[ٮٰ]هُمْ","У зот ҳидоят топганларнинг ҳидоятини зиёда қилгай ва уларнинг тақволарини бергай.",508,26],["فَهَلْ يَ[f:1141[نظ]ُرُونَ إِلَّا [h:12296[ٱ][l[ل]سَّاعَةَ أَ[f:6843[ن ت]َأْتِيَه[c:12297[ُم ب]َغْتَ[f:12575[ةً‌ۖ ف]َقَ[q:563[دْ] ج[o[َا]ٓءَ أَشْرَاطُهَا‌ۚ فَأَ[g[نّ]َىٰ لَهُمْ إِذَا ج[o[َا]ٓءَتْهُمْ ذِكْرَ[n[ٮٰ]هُمْ","Улар соатининг бирдан келишидан бошқа нарсага интизор бўлишаётгани йўқ. Дарвоқеъ, аломатлари келиб ҳам қолди. Агар у келиб қолса, улар қаердан эслатма олурлар?!",508,26],["فَ[h:9999[ٱ]عْلَمْ أَ[g[نّ]َهُ[n[ۥ] ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا [h:1742[ٱ]للَّهُ وَ[h:2374[ٱ]سْتَغْفِرْ لِذَ[i:11909[نۢب]ِكَ وَلِلْمُؤْمِنِينَ وَ[h:5718[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ‌ۗ وَ[h:72[ٱ]للَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَ[n[ٮٰ]كُمْ","Бас, билгин: Аллоҳдан ўзга ибодатга сазовор зот йўқ, ўзингнинг, мўминларнинг ва мўминаларнинг гуноҳларини мағфират қилинишини сўра. Аллоҳ сизларнинг кезар жойларингизни ҳам, борар жойларингизни ҳам билур.",508,26],["وَيَقُولُ [h:3629[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَوْلَا نُزِّلَتْ سُورَ[f:12576[ةٌ‌ۖ ف]َإِذ[o[َآ] أُ[f:5767[نز]ِلَتْ سُورَ[a:12577[ةٌ م]ُّحْكَمَ[a:12578[ةٌ و]َذُكِرَ فِيهَا [h:12579[ٱ]لْقِتَالُ‌ۙ رَأَيْتَ [h:4150[ٱ]لَّذِينَ فِى قُلُوبِه[w:39[ِم م]َّرَ[a:12580[ضٌ ي]َ[f:1141[نظ]ُرُونَ إِلَيْكَ نَظَرَ [h:12581[ٱ]لْمَغْشِىِّ عَلَيْهِ مِنَ [h:10720[ٱ]لْمَوْتِ‌ۖ فَأَوْلَىٰ لَهُمْ","Ва иймон келтирганлар, бирон сура нозил қилинса эди, дерлар. Вақтики, аниқ сура нозил қилиниб, унда уруш зикр қилинса, қалбларида касали борларни сенга жон бераётганнинг қарашидек қараётганини кўрасан.",509,26],["طَاعَ[a:12582[ةٌ و]َقَوْ[a:12583[لٌ م]َّعْرُو[f:12584[فٌ‌ۚ ف]َإِذَا عَزَمَ [h:12585[ٱ]لْأَمْرُ فَلَوْ صَدَقُو[s[اْ] [h:12586[ٱ]للَّهَ لَكَانَ خَيْ[u:2160[رًا ل]َّهُمْ","Уларга тоат ва яхши сўз яхшироқдир, бас, иш жиддийлашганда, Аллоҳга содиқ қолсалар, ўзларига яхши бўлур эди.",509,26],["فَهَلْ عَسَيْتُمْ إِ[f:12587[ن ت]َوَلَّيْتُمْ أَ[f:12588[ن ت]ُفْسِدُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ وَتُقَطِّع[o[ُوٓ][s[اْ] أَرْحَامَكُمْ","Эҳтимол, юз ўгирсангиз, ер юзида фасод қилиб, қардошлик ришталарини узарсиз?!",509,26],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ لَعَنَهُمُ [h:462[ٱ]للَّهُ فَأَصَ[g[مّ]َهُمْ وَأَعْمَ[o[ىٰٓ] أَ[q:76[بْ]صَ[n[ـٰ]رَهُمْ","Ана ўшаларни Аллоҳ лаънатлади, уларни кар қилди ва кўзларини кўр қилди.",509,26],["أَفَلَا يَتَدَبَّرُونَ [h:2968[ٱ]لْقُرْءَانَ أَمْ عَلَىٰ قُلُوبٍ أَ[q:12589[قْ]فَالُهَآ","Қуръонни тадаббур ила ўйлаб кўрмасларми? Ёки қалбларида қулф борми?",509,26],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ [h:12590[ٱ]رْتَدُّو[s[اْ] عَلَ[o[ىٰٓ] أَ[q:7778[دْ]بَ[n[ـٰ]رِه[w:12591[ِم م]ّ[i:146[ِنۢ ب]َعْدِ مَا تَبَيَّنَ لَهُمُ [h:12592[ٱ]لْهُدَى‌ۙ [h:12593[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ سَوَّلَ لَهُمْ وَأَمْلَىٰ لَهُمْ","Албатта, ҳидоят равшан бўлгандан сўнг ортларига қайтганларга шайтон зийнатлаб кўрсатди ва уларни ўша йўллади.",509,26],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ قَالُو[s[اْ] لِلَّذِينَ كَرِهُو[s[اْ] مَا نَزَّلَ [h:4797[ٱ]للَّهُ سَنُطِيعُكُمْ فِى بَعْضِ [h:12594[ٱ]لْأَمْرِ‌ۖ وَ[h:72[ٱ]للَّهُ يَعْلَمُ إِسْرَارَهُمْ","Ундоқ бўлишлиги, албатта, уларнинг Аллоҳ нозил қилган нарсани хуш кўрмаганларга:»Сизларга баъзи ишларда итоат қиламиз», дейишлари сабабидандир. Ва ҳолбуки Аллоҳ сир-асрорларини билиб турибди.",509,26],["فَكَيْفَ إِذَا تَوَفَّتْهُمُ [h:12595[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَ[q:5380[دْ]بَ[n[ـٰ]رَهُمْ","Фаришталар юзларига ва ортларига уриб жонларини олаётганларида қандоқ бўларкин?!",509,26],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمُ [h:12596[ٱ]تَّبَعُو[s[اْ] م[o[َآ] أَسْخَطَ [h:12597[ٱ]للَّهَ وَكَرِهُو[s[اْ] رِضْو[n[َٲ]نَهُ[n[ۥ] فَأَحْبَطَ أَعْمَ[n[ـٰ]لَهُمْ","Бундай бўлиши, албатта уларнинг Аллоҳни ғазаблантирган нарсага эргашганлари ва Унинг розилигини хуш кўрмаганликлари сабабидандир. Бас, У зот амалларини ҳабата қилди.",509,26],["أَمْ حَسِبَ [h:10282[ٱ]لَّذِينَ فِى قُلُوبِه[w:39[ِم م]َّرَضٌ أ[u:8842[َن ل]ّ[a:12598[َن ي]ُخْرِجَ [h:12599[ٱ]للَّهُ أَضْغَ[n[ـٰ]نَهُمْ","Қалбларида касал борлар, Аллоҳ уларнинг қаттиқ ҳасадларини ошкор қилмайди, деб ҳисоблайдиларми?!",509,26],["وَلَوْ نَش[o[َا]ٓءُ لَأَرَيْنَ[n[ـٰ]كَهُمْ فَلَعَرَفْتَه[c:12600[ُم ب]ِسِيمَ[n[ـٰ]هُمْ‌ۚ وَلَتَعْرِفَ[g[نّ]َهُمْ فِى لَحْنِ [h:12601[ٱ]لْقَوْلِ‌ۚ وَ[h:72[ٱ]للَّهُ يَعْلَمُ أَعْمَ[n[ـٰ]لَكُمْ","Агар хоҳласак, Биз уларни сенга кўрсатамиз, таъкидки, сен уларни сиймоларидан танийсан, албатта, сен уларни гап оҳангларидан танийсан. Аллоҳ амалларингизни билиб турур.",510,26],["وَلَنَ[q:791[بْ]لُوَ[g[نّ]َكُمْ حَتَّىٰ نَعْلَمَ [h:12602[ٱ]لْمُجَ[n[ـٰ]هِدِينَ مِ[f:344[نك]ُمْ وَ[h:918[ٱ][l[ل]صَّ[n[ـٰ]بِرِينَ وَنَ[q:12603[بْ]لُو[o[َ[s[اْ]] أَخْبَارَكُمْ","Ва таъкидки, Биз сизларни синаймиз, токи сизлардан мужоҳидларни, сабрлиларни билсак ва хабарларингизни имтиҳон этсак.",510,26],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَصَدُّو[s[اْ] عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ وَش[m[َا]ٓقُّو[s[اْ] [h:12604[ٱ][l[ل]رَّسُولَ م[i:146[ِنۢ ب]َعْدِ مَا تَبَيَّنَ لَهُمُ [h:12592[ٱ]لْهُدَىٰ ل[a:2438[َن ي]َضُرُّو[s[اْ] [h:2439[ٱ]للَّهَ شَيْـ[a:12605[ـًٔا و]َسَيُحْبِطُ أَعْمَ[n[ـٰ]لَهُمْ","Албатта, куфр келтирганлар ва Аллоҳнинг йўлидан тўсганлар ҳамда ҳидоят аниқ бўлгандан сўнг Пайғамбарга қарши чиққанлар Аллоҳга ҳеч зарар келтира олмаслар. Ва уларнинг амалларини У зот ҳабата қилур.",510,26],["۞ يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَطِيعُو[s[اْ] [h:1855[ٱ]للَّهَ وَأَطِيعُو[s[اْ] [h:2865[ٱ][l[ل]رَّسُولَ وَلَا تُ[q:1546[بْ]طِل[o[ُوٓ][s[اْ] أَعْمَ[n[ـٰ]لَكُمْ","Эй иймон келтирганлар! Аллоҳга итоат этинг ва Расулга итоат этинг. Ва амалларингизни ботил қилмангиз.",510,26],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَصَدُّو[s[اْ] عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ ثُ[g[مّ]َ مَاتُو[s[اْ] وَهُمْ كُفَّا[f:2095[رٌ ف]َل[a:5740[َن ي]َغْفِرَ [h:5741[ٱ]للَّهُ لَهُمْ","Албатта куфр келтирганлар ва Аллоҳнинг йўлидан тўсган, сўнгра кофир ҳолларида ўлганларни Аллоҳ ҳеч-ҳеч мағфират қилмас.",510,26],["فَلَا تَهِنُو[s[اْ] وَتَ[q:12606[دْ]ع[o[ُوٓ][s[اْ] إِلَى [h:12607[ٱ][l[ل]سَّلْمِ وَأَ[f:2262[نت]ُمُ [h:2263[ٱ]لْأَعْلَوْنَ وَ[h:72[ٱ]للَّهُ مَعَكُمْ وَل[a:12608[َن ي]َتِرَكُمْ أَعْمَ[n[ـٰ]لَكُمْ","Бас, бўш келманглар ва ўзингиз устун бўлиб туриб, ярашга чақирманглар. Аллоҳ сиз билан ва амалларингизни ҳеч-ҳеч камайтирмас.",510,26],["إِ[g[نّ]َمَا [h:12609[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَا لَعِ[a:4002[بٌ و]َلَهْ[a:12610[وٌ‌ۚ و]َإِ[f:2455[ن ت]ُؤْمِنُو[s[اْ] وَتَتَّقُو[s[اْ] يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْــَٔلْكُمْ أَمْو[n[َٲ]لَكُمْ","Албатта, бу дунё ҳаёти ўйин ва кўнгил хушидир ва гар иймон келтирсангиз ва тақво қилсангиз, У зот ажрларингизни берур ва молу дунёларингизни сўрамас.",510,26],["إ[a:12611[ِن ي]َسْــَٔلْكُمُوهَا فَيُحْفِكُمْ تَ[q:12612[بْ]خَلُو[s[اْ] وَيُخْرِ[q:12613[جْ] أَضْغَ[n[ـٰ]نَكُمْ","Агар сиздан уларни сўраса, қийнаса, бахиллик қилурсизлар ва кек-ҳиқдларингизни чиқарадир.",510,26],["هَ[o[ـٰٓ]أَ[f:1998[نت]ُمْ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ تُ[q:11790[دْ]عَوْنَ لِتُ[f:12614[نف]ِقُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ فَمِ[f:12615[نك][w:12616[ُم م]ّ[a:12617[َن ي]َ[q:12618[بْ]خَلُ‌ۖ وَم[a:12619[َن ي]َ[q:12620[بْ]خَلْ فَإِ[g[نّ]َمَا يَ[q:12618[بْ]خَلُ ع[a:5890[َن ن]َّفْسِه[n[ِۦ]‌ۚ وَ[h:72[ٱ]للَّهُ [h:12621[ٱ]لْغَنِىُّ وَأَ[f:2262[نت]ُمُ [h:12622[ٱ]لْفُقَر[o[َا]ٓءُ‌ۚ وَإِ[f:12623[ن ت]َتَوَلَّوْ[s[اْ] يَسْتَ[q:12624[بْ]دِلْ قَوْمًا غَيْرَكُمْ ثُ[g[مّ]َ لَا يَكُون[o[ُوٓ][s[اْ] أَمْثَ[n[ـٰ]لَكُم","Ҳой сизлар! Анавилар! Аллоҳнинг йўлида нафақа қилишга чақирилсангиз, бас, баъзиларингиз бахиллик қилурсизлар. Ва ким бахиллик қилса, албатта, ўзига бахиллик қиладир. Ва, ҳолбуки, Аллоҳ бой, сизлар камбағалсизлар. Ва агар сиз юз ўгириб кетсангиз, У зот сиздан бошқа қавмни ўрнингизга келтирур, улар эса сизларга ўхшаган бўлмаслар.",510,26]]},{"n":48,"ar":"الفَتۡحِ","en":"Al-Fath","uz":"Фатҳ","type":"Мадина","ayahs":[["إِ[g[نّ]َا فَتَحْنَا لَكَ فَتْ[a:12625[حًا م]ُّبِينًا","Албатта Биз сенга равшан фатҳни бердик.",511,26],["لِّيَغْفِرَ لَكَ [h:12626[ٱ]للَّهُ مَا تَقَدَّمَ مِ[f:12627[ن ذ]َ[i:12628[نۢب]ِكَ وَمَا تَأَخَّرَ وَيُتِ[g[مّ]َ نِعْمَتَهُ[n[ۥ] عَلَيْكَ وَيَهْدِيَكَ صِر[n[َٲ][a:2898[طًا م]ُّسْتَقِيمًا","Аллоҳ сенинг аввал ўтган гуноҳларингни ва кейингиларини мағфират этиши, неъматини батамом қилиши ва сени тўғри йўлга бошлаши учун.",511,26],["وَيَ[f:12629[نص]ُرَكَ [h:12630[ٱ]للَّهُ نَصْرًا عَزِيزًا","Ва Аллоҳ сенга иззатли нусрат бериши учун.",511,26],["هُوَ [h:153[ٱ]لَّذ[o[ِىٓ] أَ[f:471[نز]َلَ [h:12631[ٱ][l[ل]سَّكِينَةَ فِى قُلُوبِ [h:12632[ٱ]لْمُؤْمِنِينَ لِيَزْدَاد[o[ُوٓ][s[اْ] إِيمَ[n[ـٰ][a:12633[نًا م]َّعَ إِيمَ[n[ـٰ]نِهِمْ‌ۗ وَلِلَّهِ جُنُودُ [h:12634[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ عَلِيمًا حَكِيمًا","У иймонларига иймон зиёда бўлиши учун мўминлар қалбига сокинликни нозил этган зотдир. Ва осмонлару ернинг лашкари Аллоҳникидир. Ва Аллоҳ билувчи ва ҳикматли зотдир.",511,26],["لِّيُ[q:12635[دْ]خِلَ [h:12636[ٱ]لْمُؤْمِنِينَ وَ[h:5718[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔـاتِهِمْ‌ۚ وَكَانَ ذ[n[َٲ]لِكَ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ فَوْزًا عَظِيمًا","Мўминлар ва мўминаларни тагларидан анҳорлар оқиб турган жаннатларга мангу киритиш учун ва уларнинг гуноҳлари ювиш учун. Ва бу Аллоҳнинг ҳузурида катта ютуқдир.",511,26],["وَيُعَذِّبَ [h:10755[ٱ]لْمُنَ[n[ـٰ]فِقِينَ وَ[h:5699[ٱ]لْمُنَ[n[ـٰ]فِقَ[n[ـٰ]تِ وَ[h:10916[ٱ]لْمُشْرِكِينَ وَ[h:10917[ٱ]لْمُشْرِكَ[n[ـٰ]تِ [h:12637[ٱ][l[ل]ظّ[m[َا]ٓ[g[نّ]ِينَ بِ[h:32[ٱ]للَّهِ ظَ[g[نّ]َ [h:12638[ٱ][l[ل]سَّوْءِ‌ۚ عَلَيْهِمْ د[o[َا]ٓئِرَةُ [h:5798[ٱ][l[ل]سَّوْءِ‌ۖ وَغَضِبَ [h:3036[ٱ]للَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَ[g[نّ]َمَ‌ۖ وَس[o[َا]ٓءَتْ مَصِيرًا","Аллоҳ тўғрисида ёмон гумон қилувчи мунофиқ ва мунофиқалар, мушрик ва мушрикаларни азоблаш учун. Уларни ёмонлик ўраб олсин. Уларга Аллоҳ ғазаб қилди, уларни лаънатлади ва уларга жаҳаннамни тайёрлаб қўйди. Ва нақадар ёмон жой у!",511,26],["وَلِلَّهِ جُنُودُ [h:12634[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ عَزِيزًا حَكِيمًا","Осмонлару ернинг лашкарлари Аллоҳникидир. Ва Аллоҳ иззатли ва ҳикматли зотдир.",511,26],["إِ[g[نّ][o[َآ] أَرْسَلْنَ[n[ـٰ]كَ شَ[n[ـٰ]هِ[a:10848[دًا و]َمُبَشِّ[a:10849[رًا و]َنَذِيرًا","Албатта, Биз сени гувоҳлик берувчи, хушхабар элтувчи ва огоҳлантирувчи қилиб юбордик.",511,26],["لِّتُؤْمِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكْرَ[a:9566[ةً و]َأَصِيلاً","Аллоҳга ва Унинг Расулига иймон келтиришингиз, уни қўллаб қувватлашингиз, улуғлашингиз ҳамда У зотга эрта-ю кеч тасбиҳ айтишингиз учундир.",511,26],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يُبَايِعُونَكَ إِ[g[نّ]َمَا يُبَايِعُونَ [h:12639[ٱ]للَّهَ يَدُ [h:3668[ٱ]للَّهِ فَوْقَ أَيْدِيهِمْ‌ۚ فَم[a:12640[َن ن]َّكَثَ فَإِ[g[نّ]َمَا يَ[f:12641[نك]ُثُ عَلَىٰ نَفْسِه[n[ِۦ]‌ۖ وَمَنْ أَوْفَىٰ بِمَا عَ[n[ـٰ]هَدَ عَلَيْهُ [h:12642[ٱ]للَّهَ فَسَيُؤْتِيهِ أَ[q:2795[جْ]رًا عَظِيمًا","Албатта, сенга байъат қилаётганлар фақат Аллоҳнинг Ўзига байъат қилмоқдалар. Аллоҳнинг қўли уларнинг қўллари устидадир. Ким бузса, ўзига қарши бузади, холос. Ва ким Аллоҳга қилган аҳдига вафо қилса, унга тезда улкан ажр берилур.",512,26],["سَيَقُولُ لَكَ [h:12643[ٱ]لْمُخَلَّفُونَ مِنَ [h:5777[ٱ]لْأَعْرَابِ شَغَلَتْن[o[َآ] أَمْو[n[َٲ]لُنَا وَأَهْلُونَا فَ[h:12644[ٱ]سْتَغْفِرْ لَنَا‌ۚ يَقُولُونَ بِأَلْسِنَتِه[w:12645[ِم م]َّا لَيْسَ فِى قُلُوبِهِمْ‌ۚ قُلْ فَم[a:3449[َن ي]َمْلِكُ لَك[w:1578[ُم م]ِّنَ [h:321[ٱ]للَّهِ شَيْــًٔا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْع[i:12646[َۢا‌ۚ ب]َلْ كَانَ [h:742[ٱ]للَّهُ بِمَا تَعْمَلُونَ خَبِيرَۢا","Ортда қолган аъробийлар сенга, молимиз ва аҳлимиз бизни машғул қилди, бизга истиғфор айт, дерлар. Улар қалбларида йўқ нарсани тиллари ила айтарлар. Сен: «Агар Аллоҳ сизга зарарни ирода қилса ёки сизга манфаатни ирода қилса, ким сизларни Аллоҳдан бирор нарсадан молик бўладир? Балки Аллоҳ қилган амалларингиздан хабардордир», деб айт.",512,26],["بَلْ ظَنَ[f:12002[نت]ُمْ أ[u:8842[َن ل]ّ[a:12647[َن ي]َ[f:12648[نق]َلِبَ [h:12649[ٱ][l[ل]رَّسُولُ وَ[h:1709[ٱ]لْمُؤْمِنُونَ إِلَ[o[ىٰٓ] أَهْلِيهِمْ أَبَ[a:12650[دًا و]َزُيِّنَ ذ[n[َٲ]لِكَ فِى قُلُوبِكُمْ وَظَنَ[f:12651[نت]ُمْ ظَ[g[نّ]َ [h:12638[ٱ][l[ل]سَّوْءِ وَكُ[f:151[نت]ُمْ قَوْم[i:9595[َۢا ب]ُورًا","Балки сизлар Расул ва мўминлар абадий ўз аҳлларига қайтиб келмаслар, деб гумон қилдингиз ва бу нарса қалбингизда зийнатланди, ёмон гумон қилдингиз ва ёмон қавм бўлдингиз.",512,26],["وَم[u:1416[َن ل]َّمْ يُؤْم[i:12652[ِنۢ ب]ِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] فَإِ[g[نّ][o[َآ] أَعْتَ[q:2660[دْ]نَا لِلْكَ[n[ـٰ]فِرِينَ سَعِيرًا","Ва ким Аллоҳга ва Унинг Расулига иймон келтирмаса, албатта, Биз кофирларга дўзахни тайёрлаганмиз.",512,26],["وَلِلَّهِ مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ يَغْفِرُ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيُعَذِّبُ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ غَفُو[u:2701[رًا ر]َّحِيمًا","Осмонлару ернинг мулки Аллоҳникидир. Кимни хоҳласа, мағфират қилур ва кимни хоҳласа азоблар. Ва Аллоҳ кечирувчи, раҳмли зотдир.",512,26],["سَيَقُولُ [h:12653[ٱ]لْمُخَلَّفُونَ إِذَا [h:12654[ٱ][f:12655[نط]َلَ[q:12655[قْ]تُمْ إِلَىٰ مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ‌ۖ يُرِيدُونَ أ[a:12656[َن ي]ُبَدِّلُو[s[اْ] كَلَ[n[ـٰ]مَ [h:389[ٱ]للَّهِ‌ۚ قُل لَّ[f:12657[ن ت]َتَّبِعُونَا كَذ[n[َٲ]لِكُمْ قَالَ [h:1961[ٱ]للَّهُ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا‌ۚ بَلْ كَانُو[s[اْ] لَا يَفْقَهُونَ إِلَّا قَلِيلاً","Ўлжалар томон, уларни олиш учун юрганингизда ортда қолганлар: «Қўйиб беринг, биз ҳам сизга эргашамиз», дерлар. Аллоҳнинг каломини ўзгартирмоқчи бўлурлар. Айт: «Ҳеч-ҳеч бизга эргашмассиз, ушбуни Аллоҳ аввал айтган». Улар: «Балки ҳасад қилаётгандирсизлар», дерлар. Йўқ, улар озгина нарсадан бошқа нарсани англамаслар.",512,26],["قُل لِّلْمُخَلَّفِينَ مِنَ [h:5777[ٱ]لْأَعْرَابِ سَتُ[q:12658[دْ]عَوْنَ إِلَىٰ قَوْمٍ أُ[s[وْ]لِى بَأْ[f:7663[سٍ ش]َدِي[f:12659[دٍ ت]ُقَ[n[ـٰ]تِلُونَهُمْ أَوْ يُسْلِمُونَ‌ۖ فَإِ[f:12660[ن ت]ُطِيعُو[s[اْ] يُؤْتِكُمُ [h:12661[ٱ]للَّهُ أَ[q:2795[جْ]رًا حَسَ[a:12662[نًا‌ۖ و]َإِ[f:12623[ن ت]َتَوَلَّوْ[s[اْ] كَمَا تَوَلَّيْت[w:336[ُم م]ِّ[f:128[ن ق]َ[q:129[بْ]لُ يُعَذِّ[q:5585[بْ]كُمْ عَذَابًا أَلِيمًا","Ортда қолган аъробийларга: « Катта кучга эга қавмга чақирилурсизлар, улар мусулмон бўлгунларича урушурсизлар. Агар итоат қилсангиз, Аллоҳ сизга яхши ажр берур. Ва агар яна аввал қочганингиздек, ортга қочсангиз, аламли азоб ила азоблайдир», деб айт.",513,26],["لَّيْسَ عَلَى [h:9532[ٱ]لْأَعْمَىٰ حَرَ[a:9533[جٌ و]َلَا عَلَى [h:9534[ٱ]لْأَعْرَجِ حَرَ[a:9533[جٌ و]َلَا عَلَى [h:9535[ٱ]لْمَرِيضِ حَرَ[a:12663[جٌ‌ۗ و]َم[a:2629[َن ي]ُطِعِ [h:2630[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] يُ[q:2631[دْ]خِلْهُ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۖ وَم[a:3640[َن ي]َتَوَلَّ يُعَذِّ[q:12664[بْ]هُ عَذَابًا أَلِيمًا","Кўрга танглик йўқ, чўлоққа ҳам тангликлик йўқ. Ҳаста кишига ҳам танглик йўқ. Ким Аллоҳга ва Унинг Расулига итоат қилса, уни остидан сувлар оқиб турган жаннатларга киритилур. Ким юз ўгирса, аламли азоб ила азоблар.",513,26],["۞ لَّقَ[q:2389[دْ] رَضِىَ [h:3910[ٱ]للَّهُ عَنِ [h:12665[ٱ]لْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ [h:12666[ٱ][l[ل]شَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمْ فَأَ[f:5594[نز]َلَ [h:12667[ٱ][l[ل]سَّكِينَةَ عَلَيْهِمْ وَأَثَ[n[ـٰ]بَهُمْ فَتْ[f:12668[حًا ق]َرِيبًا","Батаҳқиқ, Аллоҳ мўминлардан дарахт остида сенга байъат қилаётганларида рози бўлди. Бас, уларнинг қалбларидагини билди, уларга сокинликни туширди ва яқин фатҳ ила мукофатлади.",513,26],["وَمَغَانِمَ كَثِيرَ[a:12669[ةً ي]َأْخُذُونَهَا‌ۗ وَكَانَ [h:2653[ٱ]للَّهُ عَزِيزًا حَكِيمًا","Ва кўпгина ўлжаларни ҳам олурлар. Ва Аллоҳ азиз ва ҳаким зотдир.",513,26],["وَعَدَكُمُ [h:12670[ٱ]للَّهُ مَغَانِمَ كَثِيرَ[f:12671[ةً ت]َأْخُذُونَهَا فَعَجَّلَ لَكُمْ هَ[n[ـٰ]ذِه[n[ِۦ] وَكَفَّ أَيْدِىَ [h:12672[ٱ][l[ل][g[نّ]َاسِ عَ[f:255[نك]ُمْ وَلِتَكُونَ ءَايَ[u:12673[ةً ل]ِّلْمُؤْمِنِينَ وَيَهْدِيَكُمْ صِر[n[َٲ][a:2898[طًا م]ُّسْتَقِيمًا","Аллоҳ сизларга кўпгина ўлжаларни ваъда қилди. Уларни олсангизлар, бунисини сизга тезлатиб берди, мўминларга ибрат бўлиши учун ва сизларни сироти мустақиймга бошлаш учун одамларнинг қўлини сиздан тўсди.",513,26],["وَأُخْرَىٰ لَمْ تَ[q:3529[قْ]دِرُو[s[اْ] عَلَيْهَا قَ[q:298[دْ] أَحَاطَ [h:12674[ٱ]للَّهُ بِهَا‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:10766[َىْءٍ ق]َدِيرًا","Ва сизлар қодир бўлмаган бошқасини ҳам. Уни Аллоҳ иҳота қилган ва Аллоҳ ҳар бир нарсага қодир зотдир.",513,26],["وَلَوْ قَ[n[ـٰ]تَلَكُمُ [h:12675[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَوَلَّوُ[s[اْ] [h:12676[ٱ]لْأَ[q:2168[دْ]بَ[n[ـٰ]رَ ثُ[g[مّ]َ لَا يَجِدُونَ وَلِي[a:3006[ًّا و]َلَا نَصِيرًا","Агар кофирлар сизлар билан урушганларида орқага қараб қочар эдилар, сўнгра ўзларига валий ҳам, нусрат бергувчи ҳам топмасдилар.",513,26],["سُ[g[نّ]َةَ [h:10837[ٱ]للَّهِ [h:4656[ٱ]لَّتِى قَ[q:298[دْ] خَلَتْ مِ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ وَلَ[f:3232[ن ت]َجِدَ لِسُ[g[نّ]َةِ [h:10896[ٱ]للَّهِ تَ[q:10752[بْ]دِيلاً","Бу Аллоҳнинг аввалдан келаётган суннатидир. Ва Аллоҳнинг суннатини ҳеч ўзгартира олмассан.",513,26],["وَهُوَ [h:4114[ٱ]لَّذِى كَفَّ أَيْدِيَهُمْ عَ[f:255[نك]ُمْ وَأَيْدِيَكُمْ عَنْه[c:12677[ُم ب]ِبَ[q:12678[طْ]نِ مَكَّةَ م[i:146[ِنۢ ب]َعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ بِمَا تَعْمَلُونَ بَصِيرًا","У зот Макка водийсида сизларни уларнинг устидан зафар қозонтирганидан сўнг уларнинг қўлларини сиздан, сизнинг қўлингизни улардан тўсган зотдир. Ва Аллоҳ қилаётган амалларингизни кўриб турувчидир.",514,26],["هُمُ [h:12679[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَصَدُّوكُمْ عَنِ [h:3362[ٱ]لْمَسْجِدِ [h:752[ٱ]لْحَرَامِ وَ[h:3816[ٱ]لْهَ[q:3816[دْ]ىَ مَعْكُوفًا أ[a:12680[َن ي]َ[q:1053[بْ]لُغَ مَحِلَّهُ[n[ۥ]‌ۚ وَلَوْلَا رِجَا[a:12681[لٌ م]ُّؤْمِنُونَ وَنِس[o[َا]ٓ[a:12682[ءٌ م]ُّؤْمِنَ[n[ـٰ][u:12683[تٌ ل]َّمْ تَعْلَمُوهُمْ أَ[f:12684[ن ت]َطَــُٔوهُمْ فَتُصِيبَك[w:12685[ُم م]ِّنْه[w:12686[ُم م]َّعَرَّ[i:12687[ةُۢ ب]ِغَيْرِ عِلْ[u:12688[مٍ‌ۖ ل]ِّيُ[q:12635[دْ]خِلَ [h:12689[ٱ]للَّهُ فِى رَحْمَتِه[n[ِۦ] م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ لَوْ تَزَيَّلُو[s[اْ] لَعَذَّ[q:12690[بْ]نَا [h:12691[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِنْهُمْ عَذَابًا أَلِيمًا","Улар куфр келтирган, сизларни Масжидул Ҳаромга, қурбонликларни эса, ушланиб ўз жойига етишидан ман қилган кишилардир, агар сиз билмайдиган мўмин эркаклар ва мўмина аёллар бўлмаганида, сизга билмасдан уларни ҳалок қилганингиз туфайли гуноҳ етиши бўлмаганида эди, -Аллоҳ кимни хоҳласа, Ўз раҳматига киритиши учун- агар ажраб турганларида эди, улардан кофирларини аламли азоб ила азоблар эдик.",514,26],["إِذْ جَعَلَ [h:12692[ٱ]لَّذِينَ كَفَرُو[s[اْ] فِى قُلُوبِهِمُ [h:12693[ٱ]لْحَمِيَّةَ حَمِيَّةَ [h:12694[ٱ]لْجَ[n[ـٰ]هِلِيَّةِ فَأَ[f:5594[نز]َلَ [h:5595[ٱ]للَّهُ سَكِينَتَهُ[n[ۥ] عَلَىٰ رَسُولِه[n[ِۦ] وَعَلَى [h:5529[ٱ]لْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ [h:12695[ٱ][l[ل]تَّ[q:1084[قْ]وَىٰ وَكَان[o[ُوٓ][s[اْ] أَحَقَّ بِهَا وَأَهْلَهَا‌ۚ وَكَانَ [h:2653[ٱ]للَّهُ بِكُلِّ شَىْءٍ عَلِيمًا","Эсла! Куфр келтирганлар қалбларида қизиққонликни жоҳилият қизиққонлигини жойлаганларида, Аллоҳ Ўз сокинлигини Пайғамбарига ва мўминларга туширди ва уларга тақво калимасини лозим кўрди, улар ушбуга ҳақли ва аҳл эдилар. Ва Аллоҳ ҳар бир нарсани билувчидир.",514,26],["لَّقَ[q:2389[دْ] صَدَقَ [h:2112[ٱ]للَّهُ رَسُولَهُ [h:12696[ٱ][l[ل]رُّءْيَا بِ[h:370[ٱ]لْحَقِّ‌ۖ لَتَ[q:12697[دْ]خُلُ[g[نّ]َ [h:12698[ٱ]لْمَسْجِدَ [h:5536[ٱ]لْحَرَامَ إِ[f:364[ن ش][o[َا]ٓءَ [h:78[ٱ]للَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ‌ۖ فَعَلِمَ مَا لَمْ تَعْلَمُو[s[اْ] فَجَعَلَ مِ[f:107[ن د]ُونِ ذ[n[َٲ]لِكَ فَتْ[f:12668[حًا ق]َرِيبًا","Батаҳқиқ, Аллоҳ Расулининг тушини ҳақ ила тасдиқлади, албатта, Масжидул Ҳаромга, иншоаллоҳ, омонликда, сочларингиз олинган, қисқартирилган ҳолда қўрқмасдан кирасизлар. Бас, У сиз билмаган нарсани биладир ва сизларга бундан бошқа яқин фатҳни қилди.",514,26],["هُوَ [h:153[ٱ]لَّذ[o[ِىٓ] أَرْسَلَ رَسُولَهُ[n[ۥ] بِ[h:54[ٱ]لْهُدَىٰ وَدِينِ [h:5557[ٱ]لْحَقِّ لِيُظْهِرَهُ[n[ۥ] عَلَى [h:5558[ٱ][l[ل]دِّينِ كُلِّه[n[ِۦ]‌ۚ وَكَفَىٰ بِ[h:32[ٱ]للَّهِ شَهِيدًا","У Ўз Расулини ҳидоят ва ҳақ дин билан, уни барча динлардан устун қилиш учун юборган зотдир.",514,26],["مُّحَ[g[مّ]َ[u:12699[دٌ ر]َّسُولُ [h:3306[ٱ]للَّهِ‌ۚ وَ[h:37[ٱ]لَّذِينَ مَعَهُ[o[ۥٓ] أَشِدّ[o[َا]ٓءُ عَلَى [h:12700[ٱ]لْكُفَّارِ رُحَم[o[َا]ٓءُ بَيْنَهُمْ‌ۖ تَرَ[n[ٮٰ]هُمْ رُكَّ[f:12701[عًا س]ُجَّ[a:12702[دًا ي]َ[q:3357[بْ]تَغُونَ فَضْل[a:12703[اً م]ِّنَ [h:321[ٱ]للَّهِ وَرِضْو[n[َٲ][f:12704[نًا‌ۖ س]ِيمَاهُمْ فِى وُجُوهِه[w:12705[ِم م]ِّنْ أَثَرِ [h:12706[ٱ][l[ل]سُّجُودِ‌ۚ ذ[n[َٲ]لِكَ مَثَلُهُمْ فِى [h:5061[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةِ‌ۚ وَمَثَلُهُمْ فِى [h:12707[ٱ]لْإِ[f:3596[نج]ِيلِ كَزَرْعٍ أَخْرَجَ شَ[q:12708[طْ]ــَٔهُ[n[ۥ] فَـَٔـازَرَهُ[n[ۥ] فَ[h:12709[ٱ]سْتَغْلَظَ فَ[h:12710[ٱ]سْتَوَىٰ عَلَىٰ سُوقِه[n[ِۦ] يُعْجِبُ [h:12711[ٱ][l[ل]زُّرَّاعَ لِيَغِيظَ بِهِمُ [h:12712[ٱ]لْكُفَّارَ‌ۗ وَعَدَ [h:3055[ٱ]للَّهُ [h:1171[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ مِنْه[w:12713[ُم م]َّغْفِرَ[a:10818[ةً و]َأَ[q:10819[جْ]رًا عَظِيمَۢا","Муҳаммад Аллоҳнинг Расулидир. У билан бирга бўлганлар кофирларга шиддатли, ўзаро раҳимдилдирлар. Уларни Аллоҳдан фазл ва розилик тилаб, рукуъ ва сажда қилган ҳолларини кўрурсан. Уларнинг сиймоси сажда асаридан юзларида. Ана ўша, уларнинг Таврот ва Инжилдаги мисолларидир. Бу худди уруғини ёриб чиқариб, қувватланиб, йўғонлашиб, поясида тик туриб, деҳқонларни ажаблантирган бир экинга ўхшайдир. Кофирларнинг ғазабини қўзиш учун. Аллоҳ улардан иймон келтириб ва солиҳ амалларни қилганларга мағфират ва улуғ ажрни ваъда қилди.",515,26]]},{"n":49,"ar":"الحُجُرَاتِ","en":"Al-Hujuraat","uz":"Ҳужурот","type":"Мадина","ayahs":[["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تُقَدِّمُو[s[اْ] بَيْنَ يَدَىِ [h:12714[ٱ]للَّهِ وَرَسُولِه[n[ِۦ]‌ۖ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَمِيعٌ عَل[p[ِي]مٌ","Эй иймон келтирганлар! Аллоҳдан ва Унинг Расулдан олдин шошилманглар. Ва Аллоҳга тақво қилинглар. Албатта Аллоҳ эшитувчи ва билувчи зотдир.",515,26],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَرْفَع[o[ُوٓ][s[اْ] أَصْو[n[َٲ]تَكُمْ فَوْقَ صَوْتِ [h:12715[ٱ][l[ل][g[نّ]َبِىِّ وَلَا تَ[q:12716[جْ]هَرُو[s[اْ] لَهُ[n[ۥ] بِ[h:7118[ٱ]لْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَ[f:12717[ن ت]َحْبَطَ أَعْمَ[n[ـٰ]لُكُمْ وَأَ[f:98[نت]ُمْ لَا تَشْعُر[p[ُو]نَ","Эй иймон келтирганлар! Овозингизни Пайғамбар овозидан юқори кўтарманг ва унга бир-бирингиз ила сўзлашгандек дағал сўз айтманг, ўзингиз сезмаган ҳолда амалларингиз ҳабата бўлиб қолмасин.",515,26],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَغُضُّونَ أَصْو[n[َٲ]تَهُمْ عِ[f:264[ند]َ رَسُولِ [h:5744[ٱ]للَّهِ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:51[ٱ]لَّذِينَ [h:12718[ٱ]مْتَحَنَ [h:12719[ٱ]للَّهُ قُلُوبَهُمْ لِلتَّ[q:1356[قْ]وَىٰ‌ۚ لَه[w:3412[ُم م]َّغْفِرَ[a:3413[ةٌ و]َأَ[q:3414[جْ]رٌ عَظ[p[ِي]مٌ","Албатта, Расулуллоҳнинг ҳузурида овозларини пастлатганлар, ана ўшалар Аллоҳ қалбларини тақвога имтиҳон қилган зотлардир. Уларга мағфират ва улкан ажр бор.",515,26],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يُنَادُونَكَ م[a:10877[ِن و]َر[o[َا]ٓءِ [h:12720[ٱ]لْحُجُر[n[َٲ]تِ أَكْثَرُهُمْ لَا يَعْقِل[p[ُو]نَ","Албатта, сени ҳужралар ортидан чақираётганларнинг кўплари ақл ишлатмаслар.",515,26],["وَلَوْ أَ[g[نّ]َهُمْ صَبَرُو[s[اْ] حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْ[u:2160[رًا ل]َّهُمْ‌ۚ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Агар уларнинг ҳузурига чиққунингча сабр қилсалар, ўзлари учун яхши бўларди. Аллоҳ мағфират қилувчи ва раҳимлидир.",516,26],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[f:12721[ن ج][o[َا]ٓءَكُمْ فَاسِ[i:12722[قُۢ ب]ِنَبَ[f:12723[إٍ ف]َتَبَيَّن[o[ُوٓ][s[اْ] أَ[f:12724[ن ت]ُصِيبُو[s[اْ] قَوْم[i:12725[َۢا ب]ِجَهَ[n[ـٰ]لَ[f:12726[ةٍ ف]َتُصْبِحُو[s[اْ] عَلَىٰ مَا فَعَلْتُمْ نَ[n[ـٰ]دِم[p[ِي]نَ","Эй иймон келтирганлар! Агар фосиқ хабар келтирса, аниқлаб кўринглар, бир қавмга билмасдан мусибат етказиб қўйиб, қилганингизга надомат чекувчи бўлманглар.",516,26],["وَ[h:9999[ٱ]عْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ فِيكُمْ رَسُولَ [h:3273[ٱ]للَّهِ‌ۚ لَوْ يُطِيعُكُمْ فِى كَثِي[a:12727[رٍ م]ِّنَ [h:2233[ٱ]لْأَمْرِ لَعَنِتُّمْ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ حَبَّبَ إِلَيْكُمُ [h:12728[ٱ]لْإِيمَ[n[ـٰ]نَ وَزَيَّنَهُ[n[ۥ] فِى قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ [h:12729[ٱ]لْكُفْرَ وَ[h:12730[ٱ]لْفُسُوقَ وَ[h:12731[ٱ]لْعِصْيَانَ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:12732[ٱ][l[ل]رّ[n[َٲ]شِد[p[ُو]نَ","Ва билингларки, албатта, ичларингизда Расулуллоҳ бордир. Агар У ишлардан кўпида сизга итоат қилса, албатта, қийинчиликка дучор бўлардингиз. Лекин, Аллоҳ сизларга иймонни маҳбуб қилди ва уни қалбларингизда зийнатлади ва сизларга куфрни, фисқни ва исённи ёмон кўрсатди. Ана ўшалар тўғриликда юрувчиларидир.",516,26],["فَضْل[a:12703[اً م]ِّنَ [h:321[ٱ]للَّهِ وَنِعْمَ[a:12733[ةً‌ۚ و]َ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Бу Аллоҳ томонидан фазл ва неъматдир. Аллоҳ билувчи ва ҳикматли зотдир.",516,26],["وَإِ[f:12734[ن ط][o[َا]ٓئِفَتَانِ مِنَ [h:3047[ٱ]لْمُؤْمِنِينَ [h:12735[ٱ][q:1459[قْ]تَتَلُو[s[اْ] فَأَصْلِحُو[s[اْ] بَيْنَهُمَا‌ۖ فَإ[i:12736[ِنۢ ب]َغَتْ إِحْدَ[n[ٮٰ]هُمَا عَلَى [h:12737[ٱ]لْأُخْرَىٰ فَقَ[n[ـٰ]تِلُو[s[اْ] [h:12738[ٱ]لَّتِى تَ[q:12739[بْ]غِى حَتَّىٰ تَف[o[ِى]ٓءَ إِلَ[o[ىٰٓ] أَمْرِ [h:6348[ٱ]للَّهِ‌ۚ فَإِ[f:12740[ن ف][o[َا]ٓءَتْ فَأَصْلِحُو[s[اْ] بَيْنَهُمَا بِ[h:1661[ٱ]لْعَ[q:1661[دْ]لِ وَأَ[q:12741[قْ]سِط[o[ُوٓ[s[اْ]‌ۖ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُحِبُّ [h:3555[ٱ]لْمُ[q:3556[قْ]سِط[p[ِي]نَ","Агар мўминлардан икки тоифа урушиб кетсалар, бас, ўрталарини ислоҳ қилинг. Агар улардан бири иккинчисига тажовуз қилса, сиз тажовуз қилганига қарши, то у Аллоҳнинг амрига қайтгунича урушинг, агар қайтса, бас, ўрталарини адолат билан ислоҳ қилинг. Одил бўлинг, албатта, Аллоҳ адолат қилгувчиларни суядир.",516,26],["إِ[g[نّ]َمَا [h:5232[ٱ]لْمُؤْمِنُونَ إِخْوَ[f:12742[ةٌ ف]َأَصْلِحُو[s[اْ] بَيْنَ أَخَوَيْكُمْ‌ۚ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ لَعَلَّكُمْ تُرْحَم[p[ُو]نَ","Албатта, мўминлар биродардирлар, бас, икки биродарингиз ўртасини ислоҳ қилинг, Аллоҳга тақво қилинг, шоядки, раҳм қилинсангиз.",516,26],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا يَسْخَرْ قَوْ[a:3827[مٌ م]ِّ[f:3024[ن ق]َوْمٍ عَسَ[o[ىٰٓ] أ[a:5507[َن ي]َكُونُو[s[اْ] خَيْ[a:12743[رًا م]ِّنْهُمْ وَلَا نِس[o[َا]ٓ[a:12744[ءٌ م]ّ[a:12745[ِن ن]ِّس[o[َا]ٓءٍ عَسَ[o[ىٰٓ] أ[a:12746[َن ي]َكُ[g[نّ]َ خَيْ[a:12747[رًا م]ِّنْهُ[g[نّ]َ‌ۖ وَلَا تَلْمِز[o[ُوٓ][s[اْ] أَ[f:221[نف]ُسَكُمْ وَلَا تَنَابَزُو[s[اْ] بِ[h:12748[ٱ]لْأَلْقَ[n[ـٰ]بِ‌ۖ بِئْسَ [h:12749[ٱ]لِ[h:12750[ٱ]سْمُ [h:12751[ٱ]لْفُسُوقُ بَعْدَ [h:12752[ٱ]لْإِيمَ[n[ـٰ]نِ‌ۚ وَم[u:1416[َن ل]َّمْ يَتُ[q:12753[بْ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:1285[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Эй иймон келтирганлар! Бир қавм бошқасини масхара қилмасин, эҳтимол улар булардан яхшироқдир. Ва аёллар ҳам бошқа аёлларни, эҳтимол улар булардан яхшироқдир. Ва ўзингизни ўзингиз мазах қилманг, бир-бирингизга лақаб қўйманг. Иймондан кейин фосиқлик исми нақадар ёмон! Ва ким тавба қилмаса, бас, ана ўшалар ўзлари золимлардир.",516,26],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:12754[ٱ][q:12755[جْ]تَنِبُو[s[اْ] كَثِي[a:3614[رًا م]ِّنَ [h:12756[ٱ][l[ل]ظَّ[g[نّ]ِ إِ[g[نّ]َ بَعْضَ [h:12757[ٱ][l[ل]ظَّ[g[نّ]ِ إِثْ[a:12758[مٌ‌ۖ و]َلَا تَجَسَّسُو[s[اْ] وَلَا يَغْتَب بَّعْضُك[c:1697[ُم ب]َعْضًا‌ۚ أَيُحِبُّ أَحَدُكُمْ أ[a:12759[َن ي]َأْكُلَ لَحْمَ أَخِيهِ مَيْ[f:12760[تًا ف]َكَرِهْتُمُوهُ‌ۚ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ تَوَّا[u:12761[بٌ ر]َّح[p[ِي]مٌ","Эй иймон келтирганлар! Кўп гумонлардан четда бўлинглар, чунки баъзи гумонлар гуноҳдир. Жосуслик қилманглар. Баъзиларингиз баъзиларингизни ғийбат қилманглар. Сизлардан бирорталарингиз ўзининг ўлган биродарининг гўштини ейишни яхши кўрадими? Ҳа, ёмон кўрасизлар. Аллоҳдан қўрқинглар! Албатта, Аллоҳ тавбани кўп қабул қилувчи ва раҳмлидир.",517,26],["يَ[o[ـٰٓ]أَيُّهَا [h:82[ٱ][l[ل][g[نّ]َاسُ إِ[g[نّ]َا خَلَ[q:4250[قْ]نَ[n[ـٰ]ك[w:8908[ُم م]ِّ[f:2511[ن ذ]َكَ[a:12762[رٍ و]َأُ[f:12763[نث]َىٰ وَجَعَلْنَ[n[ـٰ]كُمْ شُعُو[a:12764[بًا و]َقَب[o[َا]ٓئِلَ لِتَعَارَف[o[ُوٓ[s[اْ]‌ۚ] إِ[g[نّ]َ أَكْرَمَكُمْ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ أَتْقَ[n[ـٰ]كُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ عَلِيمٌ خَب[p[ِي]رٌ","Эй одамлар! Биз сизларни бир эркак ва аёлдан яратдик ва сизларни ўзаро танишишингиз учун халқлар ва қабилалар қилиб қўйдик. Албатта, Аллоҳнинг ҳузурида энг ҳурматлигингиз энг тақводорингиздир. Албатта, Аллоҳ билувчи ва хабардор зотдир.",517,26],["۞ قَالَتِ [h:12765[ٱ]لْأَعْرَابُ ءَامَ[g[نّ]َا‌ۖ قُل لَّمْ تُؤْمِنُو[s[اْ] وَلَ[n[ـٰ]كِ[f:12766[ن ق]ُول[o[ُوٓ][s[اْ] أَسْلَمْنَا وَلَ[g[مّ]َا يَ[q:12767[دْ]خُلِ [h:12768[ٱ]لْإِيمَ[n[ـٰ]نُ فِى قُلُوبِكُمْ‌ۖ وَإِ[f:12769[ن ت]ُطِيعُو[s[اْ] [h:12770[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] لَا يَلِتْك[w:12771[ُم م]ِّنْ أَعْمَ[n[ـٰ]لِكُمْ شَيْــًٔا‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Аъробийлар, иймон келтирдик, дедилар. Сен: «Иймон келтирганингиз йўқ, лекин бўйинсундик денглар, ҳали иймон қалбларингизга киргани йўқ ва агар Аллоҳга ва Унинг Расулига итоат қилсангиз, амалларингиздан ҳеч нарса камимас. Албатта, Аллоҳ кечирувчи ва раҳмли зотдир», деб айт.",517,26],["إِ[g[نّ]َمَا [h:5232[ٱ]لْمُؤْمِنُونَ [h:5233[ٱ]لَّذِينَ ءَامَنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] ثُ[g[مّ]َ لَمْ يَرْتَابُو[s[اْ] وَجَ[n[ـٰ]هَدُو[s[اْ] بِأَمْو[n[َٲ]لِهِمْ وَأَ[f:3050[نف]ُسِهِمْ فِى سَبِيلِ [h:788[ٱ]للَّهِ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:12772[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ُو]نَ","Албатта, ҳақиқий мўминлар Аллоҳга ва Унинг Расулига иймон келтирган, сўнгра шубҳа қилмаган ва Аллоҳнинг йўлидан моллари ва жонлари ила жиҳод қилганлардир. Ана ўшалар, ўшаларгина содиқлардир.",517,26],["قُلْ أَتُعَلِّمُونَ [h:12773[ٱ]للَّهَ بِدِينِكُمْ وَ[h:72[ٱ]للَّهُ يَعْلَمُ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۚ وَ[h:72[ٱ]للَّهُ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","Сен: «Аллоҳга динингизни билдирмоқчимисиз? Ва ҳолбуки, Аллоҳ осмонлару ердаги нарсани билувчи зотдир. Аллоҳ ҳар бир нарсани билувчидир», деб айт.",517,26],["يَمُ[g[نّ]ُونَ عَلَيْكَ أَنْ أَسْلَمُو[s[اْ‌ۖ] قُل لَّا تَمُ[g[نّ]ُو[s[اْ] عَلَىَّ إِسْلَ[n[ـٰ]مَك[c:12774[ُم‌ۖ ب]َلِ [h:2310[ٱ]للَّهُ يَمُ[g[نّ]ُ عَلَيْكُمْ أَنْ هَدَ[n[ٮٰ]كُمْ لِلْإِيمَ[n[ـٰ]نِ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Сенга мусулмон бўлганларини миннат қилурлар. Сен: «Менга Исломингизни миннат қилманг. Балки агар содиқ бўлсангиз, Аллоҳ сизни иймонга ҳидоят қилганини миннат қилур», деб айт.",517,26],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ يَعْلَمُ غَيْبَ [h:176[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَ[h:72[ٱ]للَّهُ بَصِي[i:505[رُۢ ب]ِمَا تَعْمَل[p[ُو]نَ","Албатта, Аллоҳ осмонлару ернинг ғайбини билувчи зотдир. Ва Аллоҳ қилаётган ишларингизни кўрувчи зотдир.",517,26]]},{"n":50,"ar":"قٓ","en":"Qaaf","uz":"Қоф","type":"Макка","ayahs":[["[m[قٓ]‌ۚ وَ[h:5855[ٱ]لْقُرْءَانِ [h:12775[ٱ]لْمَج[p[ِي][q[د]ِ","Қоф. Улуғ Қуръон ила қасам.",518,26],["بَلْ عَجِب[o[ُوٓ][s[اْ] أَ[f:11468[ن ج][o[َا]ٓءَه[w:11469[ُم م]ُّ[f:6895[نذ]ِ[a:11470[رٌ م]ِّنْهُمْ فَقَالَ [h:12776[ٱ]لْكَ[n[ـٰ]فِرُونَ هَ[n[ـٰ]ذَا شَىْءٌ عَج[p[ِي][q[ب]ٌ","Балки уларга ўзларидан огоҳлантирувчи келганидан ажабландилар ва кофирлар: «Бу ажиб нарса-ку?!",518,26],["أَءِذَا مِتْنَا وَكُ[g[نّ]َا تُرَا[f:12777[بًا‌ۖ ذ][n[َٲ]لِكَ رَ[q:12778[جْ][i:12779[عُۢ ب]َع[p[ِي][q[د]ٌ","Ўлиб, тупроқ бўлганимиздан кейин ҳам-а? Бу қайтиш узоқ-ку?!» дедилар.",518,26],["قَ[q:298[دْ] عَلِمْنَا مَا تَ[f:12780[نق]ُصُ [h:12781[ٱ]لْأَرْضُ مِنْهُمْ‌ۖ وَعِ[f:12782[ند]َنَا كِتَ[n[ـٰ]بٌ حَف[p[ِي]ظُۢ","Ҳақиқатда Биз уларни ер камайтираётганини билдик ва Бизнинг ҳузуримизда сақловчи китоб бор.",518,26],["بَلْ كَذَّبُو[s[اْ] بِ[h:370[ٱ]لْحَقِّ لَ[g[مّ]َا ج[o[َا]ٓءَهُمْ فَهُمْ ف[o[ِىٓ] أَمْ[a:12783[رٍ م]َّر[p[ِي][q[ج]ٍ","Балки уларга ҳақ келганда, уни ёлғонга чиқардилар. Улар изтиробли ишдадирлар.",518,26],["أَفَلَمْ يَ[f:5165[نظ]ُر[o[ُوٓ][s[اْ] إِلَى [h:157[ٱ][l[ل]سَّم[o[َا]ٓءِ فَوْقَهُمْ كَيْفَ بَنَيْنَ[n[ـٰ]هَا وَزَيَّ[g[نّ]َ[n[ـٰ]هَا وَمَا لَهَا مِ[f:12784[ن ف]ُر[p[ُو][q[ج]ٍ","Устиларидаги осмонга назар солмайдиларми? Уни қандай бино қилибмиз, зийнатлабмиз ва унинг тешиклари ҳам йўқ?!",518,26],["وَ[h:9999[ٱ]لْأَرْضَ مَدَ[q:7217[دْ]نَ[n[ـٰ]هَا وَأَلْقَيْنَا فِيهَا رَو[n[َٲ]سِىَ وَأَ[i:7218[نۢب]َتْنَا فِيهَا مِ[f:843[ن ك]ُلِّ زَوْ[i:8922[جِۭ ب]َه[p[ِي][q[ج]ٍ","Ва ерни чўзиб қўйдик, унга тоғларни ташладик ва унда турли гўзал жуфтларни ўстирдик.",518,26],["تَ[q:12785[بْ]صِرَ[a:12786[ةً و]َذِكْرَىٰ لِكُلِّ عَ[q:10938[بْ][a:10939[دٍ م]ُّن[p[ِي][q[ب]ٍ","қайтувчи ҳар бир бандага кўргазма ва эслатма қилиб.",518,26],["وَنَزَّلْنَا مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ م[o[َا]ٓ[a:12787[ءً م]ُّبَ[n[ـٰ]رَ[f:12788[كًا ف]َأَ[i:9998[نۢب]َتْنَا بِه[n[ِۦ] جَ[g[نّ]َ[n[ـٰ][a:12789[تٍ و]َحَبَّ [h:12790[ٱ]لْحَص[p[ِي][q[د]ِ","Ва осмондан барака сувини туширдик, ҳамда у билан боғ-роғларни ва дон ҳосилини ўстирдик.",518,26],["وَ[h:9999[ٱ][l[ل][g[نّ]َخْلَ بَاسِقَ[n[ـٰ][u:12791[تٍ ل]َّهَا طَلْ[a:12792[عٌ ن]َّض[p[ِي][q[د]ٌ","Ва зич мевали шингиллари бор хурмоларни ҳам.",518,26],["رِّزْ[u:12793[قًا ل]ِّلْعِبَادِ‌ۖ وَأَحْيَيْنَا بِه[n[ِۦ] بَلْدَ[a:9661[ةً م]َّيْ[f:12206[تًا‌ۚ ك]َذ[n[َٲ]لِكَ [h:12794[ٱ]لْخُر[p[ُو][q[ج]ُ","Бандаларга ризқ қилиб. Ва у билан ўлган шаҳарни тирилтирдик. чиқиш ҳам шундай бўладир.",518,26],["كَذَّبَتْ قَ[q:8394[بْ]لَهُمْ قَوْمُ نُو[a:12795[حٍ و]َأَصْحَ[n[ـٰ]بُ [h:12796[ٱ][l[ل]رَّسِّ وَثَم[p[ُو][q[د]ُ","Улардан аввал Нуҳ қавми, қудуқ соҳиблари ва Самуд ёлғонга чиқарганлар.",518,26],["وَعَا[a:11490[دٌ و]َفِرْعَوْنُ وَإِخْو[n[َٲ]نُ ل[p[ُو][q[ط]ٍ","Од, Фиръавн, Лут биродарлари.",518,26],["وَأَصْحَ[n[ـٰ]بُ [h:12797[ٱ]لْأَيْكَةِ وَقَوْمُ تُبَّ[f:12798[عٍ‌ۚ ك]ُ[f:12799[لٌّ ك]َذَّبَ [h:11495[ٱ][l[ل]رُّسُلَ فَحَقَّ وَع[p[ِي][q[د]ِ","Ва дарахтзор эгалари ва Туббаъ қавми — барчалари Пайғамбарларни ёлғонга чиқарганлар. Бас, ваъдам ҳақ бўлди.",518,26],["أَفَعَيِينَا بِ[h:12800[ٱ]لْخَلْقِ [h:12801[ٱ]لْأَوَّلِ‌ۚ بَلْ هُمْ فِى لَ[q:12802[بْ][a:12803[سٍ م]ِّنْ خَلْ[f:6887[قٍ ج]َد[p[ِي][q[د]ٍ","Аввалги яратишга ожиз бўлдикми? Йўқ! Улар янгидан яратилишига шубҳададирлар.",518,26],["وَلَقَ[q:341[دْ] خَلَ[q:5159[قْ]نَا [h:7228[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ وَنَعْلَمُ مَا تُوَسْوِسُ بِه[n[ِۦ] نَفْسُهُ[n[ۥ]‌ۖ وَنَحْنُ أَ[q:1355[قْ]رَبُ إِلَيْهِ مِنْ حَ[q:12804[بْ]لِ [h:12805[ٱ]لْوَر[p[ِي][q[د]ِ","Албатта, инсонни Биз яратганмиз ва унинг нафси нимани васваса қилишини ҳам биламиз. Ва Биз унга жон томиридан ҳам яқинмиз.",519,26],["إِذْ يَتَلَقَّى [h:12806[ٱ]لْمُتَلَقِّيَانِ عَنِ [h:7424[ٱ]لْيَمِينِ وَعَنِ [h:12807[ٱ][l[ل]شِّمَالِ قَع[p[ِي][q[د]ٌ","Зотан икки кутиб олувчи ўнгда ва чапда ўтирган ҳолларида кутиб олурлар.",519,26],["مَّا يَلْفِظُ مِ[f:12808[ن ق]َوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَت[p[ِي][q[د]ٌ","У бирор сўз айтмас, магар ҳузурида ҳозиру нозир.",519,26],["وَج[o[َا]ٓءَتْ سَكْرَةُ [h:12809[ٱ]لْمَوْتِ بِ[h:370[ٱ]لْحَقِّ‌ۖ ذ[n[َٲ]لِكَ مَا كُ[f:735[نت]َ مِنْهُ تَح[p[ِي][q[د]ُ","Ўлимнинг мастлиги ҳақиқат бўлиб келди. Сен қочиб юрган нарса шулдир.",519,26],["وَنُفِخَ فِى [h:4185[ٱ][l[ل]صُّورِ‌ۚ ذ[n[َٲ]لِكَ يَوْمُ [h:12810[ٱ]لْوَع[p[ِي][q[د]ِ","Ва сур ҳам чалинди. Бу қўрқитилган кундир.",519,26],["وَج[o[َا]ٓءَتْ كُلُّ نَفْ[a:12811[سٍ م]َّعَهَا س[o[َا]ٓئِ[a:12812[قٌ و]َشَه[p[ِي][q[د]ٌ","Ва ҳар бир жон ҳайдагувчи ва гувоҳлик берувчи билан келди.",519,26],["لَّقَ[q:2389[دْ] كُ[f:735[نت]َ فِى غَفْلَ[a:8863[ةٍ م]ِّنْ هَ[n[ـٰ]ذَا فَكَشَفْنَا عَ[f:626[نك]َ غِط[o[َا]ٓءَكَ فَبَصَرُكَ [h:12813[ٱ]لْيَوْمَ حَد[p[ِي][q[د]ٌ","Албатта, сен бундан ғафлатда эдинг. Бас, Биз сенинг пардангни очдик ва бугун кўзинг ўткирдир.",519,26],["وَقَالَ قَرِينُهُ[n[ۥ] هَ[n[ـٰ]ذَا مَا لَدَىَّ عَت[p[ِي][q[د]ٌ","Ва унинг «яқини»: «Мана, бу мендаги тайёр нарса», деди.",519,26],["أَلْقِيَا فِى جَهَ[g[نّ]َمَ كُلَّ كَفَّارٍ عَن[p[ِي][q[د]ٍ","Ҳар бир қайсарни, кофирни жаҳаннамга ташланг!",519,26],["مَّ[g[نّ]َا[u:12814[عٍ ل]ِّلْخَيْرِ مُعْتَ[a:12815[دٍ م]ُّر[p[ِي][q[ب]ٍ","Яхшиликни ман қилувчини, тажовузкорни, шак келтирувчини!",519,26],["ٱلَّذِى جَعَلَ مَعَ [h:3975[ٱ]للَّهِ إِلَ[n[ـٰ]هًا ءَاخَرَ فَأَلْقِيَاهُ فِى [h:10442[ٱ]لْعَذَابِ [h:12816[ٱ][l[ل]شَّد[p[ِي][q[د]ِ","Аллоҳ билан бирга бошқани илоҳ қилиб олганни шиддатли азобга ташланг!",519,26],["۞ قَالَ قَرِينُهُ[n[ۥ] رَبَّنَا م[o[َآ] أَ[q:12817[طْ]غَيْتُهُ[n[ۥ] وَلَ[n[ـٰ]كِ[f:2006[ن ك]َانَ فِى ضَلَ[n[ـٰ][i:7043[لِۭ ب]َع[p[ِي][q[د]ٍ","Унинг «яқини»: «Роббимиз, уни мен туғёнга кетгазганим йўқ, лекин унинг ўзи узоқ залолатда бўлди», дер.",519,26],["قَالَ لَا تَخْتَصِمُو[s[اْ] لَدَىَّ وَقَ[q:387[دْ] قَدَّمْتُ إِلَيْك[c:12818[ُم ب]ِ[h:12819[ٱ]لْوَع[p[ِي][q[د]ِ","У зот: «Менинг ҳузуримда тортишманглар, сизларга азоб ваъдасини тақдим қилувдим.",519,26],["مَا يُبَدَّلُ [h:12820[ٱ]لْقَوْلُ لَدَىَّ وَم[o[َآ] أَنَا۟ بِظَلَّ[n[ـٰ][u:2466[مٍ ل]ِّلْعَب[p[ِي][q[د]ِ","Менинг ҳузуримда гап ўзгармас ва Мен бандаларга зулм қилгувчи эмасман», деди.",519,26],["يَوْمَ نَقُولُ لِجَهَ[g[نّ]َمَ هَلِ [h:12821[ٱ]مْتَلَأْتِ وَتَقُولُ هَلْ م[a:12822[ِن م]َّز[p[ِي][q[د]ٍ","«Бугун жаҳаннамга тўлдингми?» десак, у: « яна қўшимча борми?» дер.",519,26],["وَأُزْلِفَتِ [h:9791[ٱ]لْجَ[g[نّ]َةُ لِلْمُتَّقِينَ غَيْرَ بَع[p[ِي][q[د]ٍ","Ва жаннат тақводорларга узоқ бўлмаган жойга яқинлаштирилди.",519,26],["هَ[n[ـٰ]ذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَف[p[ِي]ظٍ","Бу сизга ваъда қилинган нарсадир. Ҳар бир сертавбага ва сақловчига.",519,26],["مَّنْ خَشِىَ [h:12823[ٱ][l[ل]رَّحْمَ[n[ـٰ]نَ بِ[h:13[ٱ]لْغَيْبِ وَج[o[َا]ٓءَ بِقَلْ[a:12824[بٍ م]ُّن[p[ِي][q[ب]ٍ","Роҳмандан ғоибдан қўрққан ва саломат қалб ила келган кимсасага.",519,26],["ٱ[q:7258[دْ]خُلُوهَا بِسَلَ[n[ـٰ][f:12825[مٍ‌ۖ ذ][n[َٲ]لِكَ يَوْمُ [h:12826[ٱ]لْخُل[p[ُو][q[د]ِ","Унга саломат бўлган ҳолда кирингиз. Бу мангулик кунидир».",519,26],["لَه[w:3531[ُم م]َّا يَش[o[َا]ٓءُونَ فِيهَا وَلَدَيْنَا مَز[p[ِي][q[د]ٌ","У ерда нима хоҳласалар, уларникидир. Ва ҳузуримизда зиёдаси бор.",519,26],["وَكَمْ أَهْلَكْنَا قَ[q:8394[بْ]لَه[w:8395[ُم م]ِّ[f:3927[ن ق]َرْنٍ هُمْ أَشَدُّ مِنْه[c:12197[ُم ب]َ[q:12198[طْ][f:12827[شًا ف]َنَقَّبُو[s[اْ] فِى [h:2519[ٱ]لْبِلَ[n[ـٰ]دِ هَلْ م[a:7093[ِن م]َّح[p[ِي]صٍ","Улардан аввал, улардан кўра кучлироқ асрларнинг қанчасини ҳалок қилдик. «Қочадиган жой борми?» деб юртма-юрт кезиб чиқдилар.",520,26],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَذِكْرَىٰ لِمَ[f:10739[ن ك]َانَ لَهُ[n[ۥ] قَلْبٌ أَوْ أَلْقَى [h:12828[ٱ][l[ل]سَّمْعَ وَهُوَ شَه[p[ِي][q[د]ٌ","Албатта, бунда қалби борларга ва зеҳн билан қулоқ осганларга эслатма бордир.",520,26],["وَلَقَ[q:341[دْ] خَلَ[q:5159[قْ]نَا [h:7298[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّا[a:12829[مٍ و]َمَا مَسَّنَا م[u:12830[ِن ل]ُّغ[p[ُو][q[ب]ٍ","Албатта, осмонлару ерни ва уларнинг орасидаги нарсаларни олти кунда яратдик. Ва Бизни чарчоқ тутмади.",520,26],["فَ[h:9999[ٱ]صْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَ[q:3282[بْ]لَ طُلُوعِ [h:8648[ٱ][l[ل]شَّمْسِ وَقَ[q:8649[بْ]لَ [h:12831[ٱ]لْغُر[p[ُو][q[ب]ِ","Уларнинг айтаётганларига сабр қил ва Роббингга қуёш чиқиши ва ботишидан аввал ҳамду тасбиҳ айт.",520,26],["وَمِنَ [h:7856[ٱ]لَّيْلِ فَسَبِّحْهُ وَأَ[q:12832[دْ]بَ[n[ـٰ]رَ [h:12833[ٱ][l[ل]سُّج[p[ُو][q[د]ِ","Кечасида ҳам Унга тасбиҳ айт. Ва саждадан кейин ҳам.",520,26],["وَ[h:9999[ٱ]سْتَمِعْ يَوْمَ يُنَادِ [h:12834[ٱ]لْمُنَادِ م[a:9578[ِن م]َّكَا[f:11053[نٍ ق]َر[p[ِي][q[ب]ٍ","Нидо қилувчи яқин жойдан нидо қилган кунда, қулоқ ос.",520,26],["يَوْمَ يَسْمَعُونَ [h:12835[ٱ][l[ل]صَّيْحَةَ بِ[h:370[ٱ]لْحَقِّ‌ۚ ذ[n[َٲ]لِكَ يَوْمُ [h:12836[ٱ]لْخُر[p[ُو][q[ج]ِ","У кунда қичқириқни ҳақ ила эшитурлар. Ана ўша чиқиш кунидир.",520,26],["إِ[g[نّ]َا نَحْنُ نُحْى[n[ِۦ] وَنُمِيتُ وَإِلَيْنَا [h:12837[ٱ]لْمَص[p[ِي]رُ","Албатта, Биз тирилтирамиз, ўлдирурмиз. Ва қайтиш ҳам Бизгадир.",520,26],["يَوْمَ تَشَقَّقُ [h:12838[ٱ]لْأَرْضُ عَنْهُمْ سِرَا[f:12839[عًا‌ۚ ذ][n[َٲ]لِكَ حَشْرٌ عَلَيْنَا يَس[p[ِي]رٌ","У кунда устларидаги ер ёрилиб, шошиб чиқурлар. Ана ўша Биз учун осон тўплашдир.",520,26],["نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ‌ۖ وَم[o[َآ] أَ[f:169[نت]َ عَلَيْه[c:12840[ِم ب]ِجَبَّا[f:12841[رٍ‌ۖ ف]َذَكِّرْ بِ[h:8623[ٱ]لْقُرْءَانِ م[a:12842[َن ي]َخَافُ وَع[p[ِي][q[د]ِ","Уларнинг айтганларини Биз билувчимиз. Сен уларнинг устидаги жаббор эмассан. Бас, Қуръон ила азоб ваъдамдан қўрққанларни огоҳлантир.",520,26]]},{"n":51,"ar":"الذَّارِيَاتِ","en":"Adh-Dhaariyat","uz":"Зориёт","type":"Макка","ayahs":[["وَ[h:9999[ٱ][l[ل]ذّ[n[َٲ]رِيَ[n[ـٰ]تِ ذَرْوًا","Чанг тўзитувчи лар билан қасам.",520,26],["فَ[h:9999[ٱ]لْحَ[n[ـٰ]مِلَ[n[ـٰ]تِ وِ[q:12843[قْ]رًا","Юк кўтарувчилар билан қасам.",520,26],["فَ[h:9999[ٱ]لْجَ[n[ـٰ]رِيَ[n[ـٰ]تِ يُسْرًا","Осон юрувчилар билан қасам;",520,26],["فَ[h:9999[ٱ]لْمُقَسِّمَ[n[ـٰ]تِ أَمْرًا","Иш тақсимловчилар билан қасам.",520,26],["إِ[g[نّ]َمَا تُوعَدُونَ لَصَادِ[q[ق]ٌ","Албатта, сизга ваъда қилинган нарса ростдир.",520,26],["وَإِ[g[نّ]َ [h:12844[ٱ][l[ل]دِّينَ لَو[n[َٲ]قِعٌ","Ва, албатта, қиёмат воқеъ бўлгувчидир.",520,26],["وَ[h:9999[ٱ][l[ل]سَّم[o[َا]ٓءِ ذَاتِ [h:12845[ٱ]لْحُبُكِ","Гўзал, мустаҳкам осмон билан қасам.",521,26],["إِ[g[نّ]َكُمْ لَفِى قَوْ[a:12846[لٍ م]ُّخْتَلِفٍ","Албатта, сиз ихтилофли гапдасиз.",521,26],["يُؤْفَكُ عَنْهُ مَنْ أُفِكَ","Удан ким бурилса, буриб қўйилур.",521,26],["قُتِلَ [h:12847[ٱ]لْخَرّ[n[َٲ]ص[p[ُو]نَ","Ёлғончиларга лаънат бўлсин!",521,26],["ٱلَّذِينَ هُمْ فِى غَمْرَ[f:12848[ةٍ س]َاه[p[ُو]نَ","Улар жаҳолатдаги ғофиллардир.",521,26],["يَسْــَٔلُونَ أَيَّانَ يَوْمُ [h:11335[ٱ][l[ل]دّ[p[ِي]نِ","Улар ҳисоб-китоб куни қачон, деб сўрарлар.",521,26],["يَوْمَ هُمْ عَلَى [h:896[ٱ][l[ل][g[نّ]َارِ يُفْتَن[p[ُو]نَ","Бу кунда улар оловда азобланурлар.",521,26],["ذُوقُو[s[اْ] فِتْنَتَكُمْ هَ[n[ـٰ]ذَا [h:126[ٱ]لَّذِى كُ[f:100[نت][c:6084[ُم ب]ِه[n[ِۦ] تَسْتَعْجِل[p[ُو]نَ","«Азобингизни татиб кўринг», сиз қачон бўлур? деб шошилган нарса-шу».",521,26],["إِ[g[نّ]َ [h:7256[ٱ]لْمُتَّقِينَ فِى جَ[g[نّ]َ[n[ـٰ][a:7257[تٍ و]َعُي[p[ُو]نٍ","Албатта, тақводорлар жаннатлар ва булоқлардадир.",521,26],["ءَاخِذِينَ م[o[َآ] ءَاتَ[n[ـٰ]هُمْ رَبُّهُمْ‌ۚ إِ[g[نّ]َهُمْ كَانُو[s[اْ] قَ[q:3282[بْ]لَ ذ[n[َٲ]لِكَ مُحْسِن[p[ِي]نَ","Роббилари берган нарсаларни олувчилардир. Чунки улар бундан олдин эҳсон қилувчилардан бўлганлардир.",521,26],["كَانُو[s[اْ] قَلِيل[a:12849[اً م]ِّنَ [h:6029[ٱ]لَّيْلِ مَا يَهْجَع[p[ُو]نَ","Улар кечалари оз ухлар эдилар.",521,26],["وَبِ[h:9999[ٱ]لْأَسْحَارِ هُمْ يَسْتَغْفِر[p[ُو]نَ","Ва улар саҳарларда истиғфор айтар эдилар.",521,26],["وَف[o[ِىٓ] أَمْو[n[َٲ]لِهِمْ حَ[u:12850[قٌّ ل]ِّلسّ[o[َا]ٓئِلِ وَ[h:12851[ٱ]لْمَحْر[p[ُو]مِ","Ва молу мулкларида, сўровчи ва бечораларнинг ҳақи бордир.",521,26],["وَفِى [h:3922[ٱ]لْأَرْضِ ءَايَ[n[ـٰ][u:12852[تٌ ل]ِّلْمُوقِن[p[ِي]نَ","Ва ер юзида чуқур ишонувчилар учун белгилар бордир.",521,26],["وَف[o[ِىٓ] أَ[f:1329[نف]ُسِكُمْ‌ۚ أَفَلَا تُ[q:8674[بْ]صِر[p[ُو]نَ","Ва ўзларингизда ҳам. Ёки кўрмаяпсизларми?!",521,26],["وَفِى [h:12853[ٱ][l[ل]سَّم[o[َا]ٓءِ رِزْقُكُمْ وَمَا تُوعَد[p[ُو]نَ","Ва осмонда ризқингиз ҳамда сизга ваъда қилинаётган нарсалар.",521,26],["فَوَرَبِّ [h:12854[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِ إِ[g[نّ]َهُ[n[ۥ] لَحَ[a:12855[قٌّ م]ِّثْلَ م[o[َآ] أَ[g[نّ]َكُمْ تَ[f:11400[نط]ِق[p[ُو]نَ","Осмону ернинг Роббиси ила қасамки, албатта, у мисоли сиз нутқ қилаётганингиздек ҳақиқатдир.",521,26],["هَلْ أَتَ[n[ـٰ]كَ حَدِيثُ ضَيْفِ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ [h:12856[ٱ]لْمُكْرَم[p[ِي]نَ","Сенга Иброҳимнинг карамли меҳмонларининг хабари келмадими?",521,26],["إِذْ دَخَلُو[s[اْ] عَلَيْهِ فَقَالُو[s[اْ] سَلَ[n[ـٰ][f:6415[مًا‌ۖ ق]َالَ سَلَ[n[ـٰ][f:12857[مٌ ق]َوْ[a:7278[مٌ م]ُّ[f:7279[نك]َر[p[ُو]نَ","Улар унинг ҳузурига кириб, «Салом» деганларида, у: «Салом, нотаниш қавмлар», деди.",521,26],["فَرَاغَ إِلَ[o[ىٰٓ] أَهْلِه[n[ِۦ] فَج[o[َا]ٓءَ بِعِ[q:6418[جْ][f:12858[لٍ س]َم[p[ِي]نٍ","Ва аҳлига бориб, семиз бузоқни келтирди.",521,26],["فَقَرَّبَهُ[o[ۥٓ] إِلَيْهِمْ قَالَ أَلَا تَأْكُل[p[ُو]نَ","Уни уларга яқинига сурди ва: «Емайсизларми?» деди.",521,26],["فَأَوْجَسَ مِنْهُمْ خِيفَ[f:6419[ةً‌ۖ ق]َالُو[s[اْ] لَا تَخَفْ‌ۖ وَبَشَّرُوهُ بِغُلَ[n[ـٰ]مٍ عَل[p[ِي]مٍ","Улардан хавфсиради. Улар: «қўрқма», дедилар ва унга илмли ўғил башоратини бердилар.",521,26],["فَأَ[q:12859[قْ]بَلَتِ [h:12860[ٱ]مْرَأَتُهُ[n[ۥ] فِى صَرَّ[f:12861[ةٍ ف]َصَكَّتْ وَ[q:12862[جْ]هَهَا وَقَالَتْ عَجُوزٌ عَق[p[ِي]مٌ","Хотини қичқириб келди ва ўз юзига шапалоқ тушириб: «Туғмас кампир-а?!» деди.",521,26],["قَالُو[s[اْ] كَذ[n[َٲ]لِكِ قَالَ رَبُّكِ‌ۖ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:12863[ٱ]لْحَكِيمُ [h:12324[ٱ]لْعَل[p[ِي]مُ","Улар: «Сенинг Роббинг шундай деди. Албатта, Унинг Ўзи ўта ҳаким ва ўта билувчидир», дедилар.",521,26],["۞ قَالَ فَمَا خَ[q:7273[طْ]بُكُمْ أَيُّهَا [h:7274[ٱ]لْمُرْسَل[p[ُو]نَ","У: «Эй элчилар! Сизнинг ишингиз надир», деди.",522,27],["قَال[o[ُوٓ][s[اْ] إِ[g[نّ][o[َآ] أُرْسِلْن[o[َآ] إِلَىٰ قَوْ[a:7275[مٍ م]ُّ[q:4958[جْ]رِم[p[ِي]نَ","Улар: «Албатта, биз жиноятчи қавмга юборилганмиз.",522,27],["لِنُرْسِلَ عَلَيْهِمْ حِجَارَ[a:6444[ةً م]ِّ[f:3917[ن ط][p[ِي]نٍ","Уларнинг устидан лойдан тошларни ташлаш учун.",522,27],["مُّسَوَّمَةً عِ[f:264[ند]َ رَبِّكَ لِلْمُسْرِف[p[ِي]نَ","Роббинг ҳузурида исрофчилар учун белгилаб қўйилганларни», дедилар.",522,27],["فَأَخْرَ[q:4279[جْ]نَا مَ[f:506[ن ك]َانَ فِيهَا مِنَ [h:3047[ٱ]لْمُؤْمِن[p[ِي]نَ","Ва Биз у жойдан мўминларни чиқардик.",522,27],["فَمَا وَجَ[q:3834[دْ]نَا فِيهَا غَيْرَ بَيْ[a:12864[تٍ م]ِّنَ [h:6135[ٱ]لْمُسْلِم[p[ِي]نَ","У ерда бир хонадондан бошқа мусулмонларни топмадик.",522,27],["وَتَرَكْنَا فِيه[o[َآ] ءَايَ[u:12865[ةً ل]ِّلَّذِينَ يَخَافُونَ [h:12866[ٱ]لْعَذَابَ [h:6177[ٱ]لْأَل[p[ِي]مَ","Ва у ерда аламли азобдан қўрқадиганлар учун белги қолдирдик.",522,27],["وَفِى مُوسَ[o[ىٰٓ] إِذْ أَرْسَلْنَ[n[ـٰ]هُ إِلَىٰ فِرْعَوْنَ بِسُلْطَ[n[ـٰ][a:7067[نٍ م]ُّب[p[ِي]نٍ","Ва Мусода ҳам. Биз уни Фиръавнга равшан ҳужжат ила юбоганимизда...",522,27],["فَتَوَلَّىٰ بِرُكْنِه[n[ِۦ] وَقَالَ سَ[n[ـٰ]حِرٌ أَوْ مَ[q:12342[جْ]ن[p[ُو]نٌ","У юз ўгириб, ишонгани томон юрди ва: «Бу сеҳргар ёки мажнундир», деди.",522,27],["فَأَخَذْنَ[n[ـٰ]هُ وَجُنُودَهُ[n[ۥ] فَنَبَذْنَ[n[ـٰ]هُمْ فِى [h:4971[ٱ]لْيَ[g[مّ]ِ وَهُوَ مُل[p[ِي]مٌ","Бас, Биз уни ва аскарларини тутиб денгизга ташладик ва у маломатга лойиқ иш қилувчи эди.",522,27],["وَفِى عَادٍ إِذْ أَرْسَلْنَا عَلَيْهِمُ [h:12867[ٱ][l[ل]رِّيحَ [h:12868[ٱ]لْعَق[p[ِي]مَ","Ва Одда ҳам бор. Вақтики, Биз уларга туғмас шамолни юбордик.",522,27],["مَا تَذَرُ مِ[f:2103[ن ش]َىْءٍ أَتَتْ عَلَيْهِ إِلَّا جَعَلَتْهُ كَ[h:12869[ٱ][l[ل]رَّم[p[ِي]مِ","У қайси нарсага етиб борса, титиб ташламасдан қўймас.",522,27],["وَفِى ثَمُودَ إِذْ قِيلَ لَهُمْ تَمَتَّعُو[s[اْ] حَتَّىٰ ح[p[ِي]نٍ","Ва Самудда ҳам бор. Уларга вақтинчалик маза қилиб туринглар, дейилган вақтда...",522,27],["فَعَتَوْ[s[اْ] عَنْ أَمْرِ رَبِّهِمْ فَأَخَذَتْهُمُ [h:3257[ٱ][l[ل]صَّ[n[ـٰ]عِقَةُ وَهُمْ يَ[f:1141[نظ]ُر[p[ُو]نَ","Аллоҳнинг амридан бош тортдилар, бас, қараб турган ҳолларида уларни қаттиқ овоз тутди.",522,27],["فَمَا [h:11284[ٱ]سْتَطَ[n[ـٰ]عُو[s[اْ] مِ[f:12870[ن ق]ِيَا[a:12871[مٍ و]َمَا كَانُو[s[اْ] مُ[f:12872[نت]َصِر[p[ِي]نَ","Бас, улар ўринларидан туролмадилар ва ёрдам ҳам ололмадилар.",522,27],["وَقَوْمَ نُو[a:12873[حٍ م]ِّ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ إِ[g[نّ]َهُمْ كَانُو[s[اْ] قَوْ[f:5652[مًا ف]َ[n[ـٰ]سِق[p[ِي]نَ","Ва бундан аввал Нуҳ қавмини ҳам. Албатта, улар фосиқ қавм эдилар.",522,27],["وَ[h:9999[ٱ][l[ل]سَّم[o[َا]ٓءَ بَنَيْنَ[n[ـٰ]هَا بِأَيْ[s[يْ][a:12874[دٍ و]َإِ[g[نّ]َا لَمُوسِع[p[ُو]نَ","Осмонни Ўз қудратимиз ила бино қилдик. Албатта, Биз кенг қилувчимиз.",522,27],["وَ[h:9999[ٱ]لْأَرْضَ فَرَشْنَ[n[ـٰ]هَا فَنِعْمَ [h:12875[ٱ]لْمَ[n[ـٰ]هِد[p[ُو]نَ","Ва ерни тўшаб қўйдик. Биз қандоқ ҳам яхши тайёрловчимиз!",522,27],["وَمِ[f:4136[ن ك]ُلِّ شَىْءٍ خَلَ[q:5159[قْ]نَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّر[p[ُو]نَ","Ва Биз ҳар бир нарсани жуфт яратдик. Шоядки эсласангиз.",522,27],["فَفِرّ[o[ُوٓ][s[اْ] إِلَى [h:1637[ٱ]للَّهِ‌ۖ إِ[g[نّ]ِى لَك[w:6234[ُم م]ِّنْهُ نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","Бас, фақат Аллоҳгагина қочинг. Албатта, мен сизларга Ундан очиқ-ойдин огоҳлантирувчиман.",522,27],["وَلَا تَ[q:95[جْ]عَلُو[s[اْ] مَعَ [h:3975[ٱ]للَّهِ إِلَ[n[ـٰ]هًا ءَاخَرَ‌ۖ إِ[g[نّ]ِى لَك[w:6234[ُم م]ِّنْهُ نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","Ва Аллоҳга бошқа маъбудни шерик қилманглар. Албатта, мен сизларга Ундан очиқ-ойдин огоҳлантирувчиман.",522,27],["كَذ[n[َٲ]لِكَ م[o[َآ] أَتَى [h:12876[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِه[w:3926[ِم م]ّ[u:2882[ِن ر]َّسُولٍ إِلَّا قَالُو[s[اْ] سَاحِرٌ أَوْ مَ[q:12342[جْ]ن[p[ُو]نٌ","Худди шундай, булардан аввалгиларга ҳам ҳар бир Пайғамбар келган вақт, уни, сеҳргар ёки мажнун, деганлар.",523,27],["أَتَوَاصَوْ[s[اْ] بِه[n[ِۦ]‌ۚ بَلْ هُمْ قَوْ[f:12877[مٌ ط]َاغ[p[ُو]نَ","Келишиб олганмилар?! Йўқ, улар туғёнга кетган қавмлардир!",523,27],["فَتَوَلَّ عَنْهُمْ فَم[o[َآ] أَ[f:169[نت]َ بِمَل[p[ُو]مٍ","Улардан юз ўгир. Бас, сен маломатга қолувчи эмассан.",523,27],["وَذَكِّرْ فَإِ[g[نّ]َ [h:12878[ٱ][l[ل]ذِّكْرَىٰ تَ[f:8613[نف]َعُ [h:12879[ٱ]لْمُؤْمِن[p[ِي]نَ","Ва эслатгин. Албатта, эслатиш мўминларга манфаат берур.",523,27],["وَمَا خَلَ[q:11606[قْ]تُ [h:12880[ٱ]لْجِ[g[نّ]َ وَ[h:12881[ٱ]لْإِ[f:12881[نس]َ إِلَّا لِيَعْبُد[p[ُو]نِ","Жин ва инсонни фақат Менга ибодат қилиш учунгина яратдим.",523,27],["م[o[َآ] أُرِيدُ مِنْه[w:8433[ُم م]ّ[u:6099[ِن ر]ِّزْ[a:12882[قٍ و]َم[o[َآ] أُرِيدُ أ[a:12883[َن ي]ُ[q:12884[طْ]عِم[p[ُو]نِ","Мен улардан ризқ хоҳламасман ва Мени тоамлантиришларини ҳам хоҳламасман.",523,27],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ هُوَ [h:12885[ٱ][l[ل]رَّزَّاقُ ذُو [h:12886[ٱ]لْقُوَّةِ [h:12887[ٱ]لْمَت[p[ِي]نُ","Албатта, Аллоҳ Ўзи ризқ берувчи, қувват эгаси, шиддатлидир.",523,27],["فَإِ[g[نّ]َ لِلَّذِينَ ظَلَمُو[s[اْ] ذَنُو[a:12888[بًا م]ِّثْلَ ذَنُوبِ أَصْحَ[n[ـٰ]بِهِمْ فَلَا يَسْتَعْجِل[p[ُو]نِ","Албатта, зулм қилганларга ўз биродарлари азобичалик азоб бор, шошилмасинлар.",523,27],["فَوَيْ[u:396[لٌ ل]ِّلَّذِينَ كَفَرُو[s[اْ] م[a:12889[ِن ي]َوْمِهِمُ [h:12890[ٱ]لَّذِى يُوعَد[p[ُو]نَ","Кофирларга ваъда қилинаётган кунларида ҳалокат бўлсин.",523,27]]},{"n":52,"ar":"الطُّورِ","en":"At-Tur","uz":"Тур","type":"Макка","ayahs":[["وَ[h:9999[ٱ][l[ل]طّ[p[ُو]رِ","Тур билан қасам.",523,27],["وَكِتَ[n[ـٰ][a:12891[بٍ م]َّسْط[p[ُو]رٍ","Сатрланган китоб билан қасам.",523,27],["فِى رَ[a:12892[قٍّ م]َّ[f:12893[نش][p[ُو]رٍ","Ёйилган терига.",523,27],["وَ[h:9999[ٱ]لْبَيْتِ [h:12894[ٱ]لْمَعْم[p[ُو]رِ","Ва обод уй билан қасам.",523,27],["وَ[h:9999[ٱ][l[ل]سَّ[q:12895[قْ]فِ [h:12896[ٱ]لْمَرْف[p[ُو]عِ","Ва кўтарилган билан шифт қасам.",523,27],["وَ[h:9999[ٱ]لْبَحْرِ [h:12897[ٱ]لْمَسْج[p[ُو]رِ","Ва тўлган денгиз билан қасам.",523,27],["إِ[g[نّ]َ عَذَابَ رَبِّكَ لَو[n[َٲ]قِعٌ","Албатта, Роббинг азоби рўй беражак.",523,27],["مَّا لَهُ[n[ۥ] مِ[f:12898[ن د]َافِعٍ","Уни ҳеч бир қайтарувчи йўқдир.",523,27],["يَوْمَ تَمُورُ [h:12899[ٱ][l[ل]سَّم[o[َا]ٓءُ مَوْرًا","У кунда осмон ларзага келиб чайқалур.",523,27],["وَتَسِيرُ [h:12900[ٱ]لْجِبَالُ سَيْرًا","Ва тоғлар сайр этиб юрур.",523,27],["فَوَيْ[a:12901[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Бас, ўша кунда ёлғонга чиқарувчиларга вайл бўлсин!",523,27],["ٱلَّذِينَ هُمْ فِى خَوْ[a:12903[ضٍ ي]َلْعَب[p[ُو]نَ","шўнғиб ўйнайдиганларга!",523,27],["يَوْمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَ[g[نّ]َمَ دَعًّا","У кунда жаҳаннам ўтига итарилурлар.",523,27],["هَ[n[ـٰ]ذِهِ [h:12904[ٱ][l[ل][g[نّ]َارُ [h:12905[ٱ]لَّتِى كُ[f:100[نت][c:11033[ُم ب]ِهَا تُكَذِّب[p[ُو]نَ","Мана бу, сизлар ёлғонга чиқарган ўт бўладир!",523,27],["أَفَسِحْرٌ هَ[n[ـٰ]ذ[o[َآ] أَمْ أَ[f:428[نت]ُمْ لَا تُ[q:8674[بْ]صِر[p[ُو]نَ","Бу сеҳрми?! Ёки сизлар кўрмаяпсизларми?!",524,27],["ٱصْلَوْهَا فَ[h:4855[ٱ]صْبِر[o[ُوٓ][s[اْ] أَوْ لَا تَصْبِرُو[s[اْ] سَو[o[َا]ٓءٌ عَلَيْكُمْ‌ۖ إِ[g[نّ]َمَا تُ[q:4248[جْ]زَوْنَ مَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Киринглар унга! Чидайсизларми, чидамайсизларми - барибир. Қилиб юрган амалларингизнинг жазосини олурсизлар, холос.",524,27],["إِ[g[نّ]َ [h:7256[ٱ]لْمُتَّقِينَ فِى جَ[g[نّ]َ[n[ـٰ][a:12906[تٍ و]َنَع[p[ِي]مٍ","Албатта, тақводорлар жаннатлар ва нозу неъматлар ичидадирлар.",524,27],["فَ[n[ـٰ]كِهِينَ بِم[o[َآ] ءَاتَ[n[ـٰ]هُمْ رَبُّهُمْ وَوَقَ[n[ـٰ]هُمْ رَبُّهُمْ عَذَابَ [h:11780[ٱ]لْجَح[p[ِي]مِ","Роббилари уларга берган нарсалардан лаззатдадирлар. Роббилари уларни жаҳаннам азобидан сақлар.",524,27],["كُلُو[s[اْ] وَ[h:300[ٱ]شْرَبُو[s[اْ] هَنِ[o[يٓـ]ـ[i:12907[ـَٔۢا ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Енглар, ичинглар, ош бўлсин. қилган амалларингиз учундир.",524,27],["مُتَّكِــِٔينَ عَلَىٰ سُرُ[a:12908[رٍ م]َّصْفُوفَ[a:12909[ةٍ‌ۖ و]َزَوَّ[q:12381[جْ]نَ[n[ـٰ]ه[c:12382[ُم ب]ِحُورٍ ع[p[ِي]نٍ","Улар қатор тизилган сўриларга ёнбошлаган ҳолдалар. Ва уларни гўзал кўзли ҳурларга уйлаб қўйганмиз.",524,27],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَ[h:12910[ٱ]تَّبَعَتْهُمْ ذُرِّيَّتُه[c:12911[ُم ب]ِإِيمَ[n[ـٰ]نٍ أَلْحَ[q:12912[قْ]نَا بِهِمْ ذُرِّيَّتَهُمْ وَم[o[َآ] أَلَتْنَ[n[ـٰ]ه[w:12913[ُم م]ِّنْ عَمَلِه[w:12914[ِم م]ِّ[f:2103[ن ش][f:12915[َىْءٍ‌ۚ ك]ُلُّ [h:12916[ٱ]مْرِى[i:12917[ِٕۭ ب]ِمَا كَسَبَ رَه[p[ِي]نٌ","Ўзлари иймон келтириб, зурриётлари уларга иймон билан эргашганларнинг зурриётини уларга қўшдик ва уларнинг амалларидан ҳеч нарсани камайтирмадик. Ҳар бир киши ўз касби гаровидир.",524,27],["وَأَمْدَ[q:12918[دْ]نَ[n[ـٰ]ه[c:12919[ُم ب]ِفَ[n[ـٰ]كِهَ[a:12920[ةٍ و]َلَحْ[a:12921[مٍ م]ِّ[g[مّ]َا يَشْتَه[p[ُو]نَ","Ва Биз уларга хоҳлаган мевалари ва гўштларини муҳайё қилиб қўйдик.",524,27],["يَتَنَ[n[ـٰ]زَعُونَ فِيهَا كَأْ[u:12922[سًا ل]َّا لَغْ[f:12923[وٌ ف]ِيهَا وَلَا تَأْث[p[ِي]مٌ","Улар унда қадаҳларни бир-бирларига узатурлар. У ерда беҳуда сергаплик ва гуноҳ йўқ.",524,27],["۞ وَيَطُوفُ عَلَيْهِمْ غِلْمَا[u:12924[نٌ ل]َّهُمْ كَأَ[g[نّ]َهُمْ لُؤْلُ[a:12925[ؤٌ م]َّكْن[p[ُو]نٌ","Ва атрофларида худди садафдаги дурдек ғуломлари айланиб, хизматда юришадир.",524,27],["وَأَ[q:11343[قْ]بَلَ بَعْضُهُمْ عَلَىٰ بَعْ[a:11344[ضٍ ي]َتَس[o[َا]ٓءَل[p[ُو]نَ","Баъзилари бошқаларидан ўгрилиб сўраша бошладилар.",524,27],["قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا كُ[g[نّ]َا قَ[q:129[بْ]لُ ف[o[ِىٓ] أَهْلِنَا مُشْفِق[p[ِي]نَ","Албатта, биз илгари ўз аҳлимиз даврасида У зотдан қўрқувчилардан эдик.",524,27],["فَمَ[g[نّ]َ [h:3045[ٱ]للَّهُ عَلَيْنَا وَوَقَ[n[ـٰ]نَا عَذَابَ [h:12926[ٱ][l[ل]سَّم[p[ُو]مِ","Бас, Аллоҳ бизга марҳамат қилди ва бизни дўзах азобидан сақлади.",524,27],["إِ[g[نّ]َا كُ[g[نّ]َا مِ[f:128[ن ق]َ[q:129[بْ]لُ نَ[q:12927[دْ]عُوهُ‌ۖ إِ[g[نّ]َهُ[n[ۥ] هُوَ [h:12928[ٱ]لْبَرُّ [h:12929[ٱ][l[ل]رَّح[p[ِي]مُ","Албатта, биз илгари Унга дуо қилардик. Албатта, Унинг Ўзи яхшилик қилувчи ва раҳмлидур.",524,27],["فَذَكِّرْ فَم[o[َآ] أَ[f:169[نت]َ بِنِعْمَتِ رَبِّكَ بِكَاهِ[a:12930[نٍ و]َلَا مَ[q:11350[جْ]ن[p[ُو]نٍ","Бас, эслатгин: сен Роббинг неъмати ила фолбин ҳам эмассан, мажнун ҳам эмассан.",524,27],["أَمْ يَقُولُونَ شَاعِ[a:12931[رٌ ن]َّتَرَبَّصُ بِه[n[ِۦ] رَيْبَ [h:12932[ٱ]لْمَن[p[ُو]نِ","Балки улар: «У шоир, биз унга ўлим етишини кутамиз», дерлар?",524,27],["قُلْ تَرَبَّصُو[s[اْ] فَإِ[g[نّ]ِى مَعَك[w:2068[ُم م]ِّنَ [h:12933[ٱ]لْمُتَرَبِّص[p[ِي]نَ","Сен: «Кутинглар, албатта, мен ҳам сизлар билан бирга кутувчидирман», деб айт.",524,27],["أَمْ تَأْمُرُهُمْ أَحْلَ[n[ـٰ]مُه[c:12934[ُم ب]ِهَ[n[ـٰ]ذ[o[َآ‌ۚ] أَمْ هُمْ قَوْ[f:12877[مٌ ط]َاغ[p[ُو]نَ","Ё ақллари шунга буюрарми ёки улар туғёнга кетган қавмларми?",525,27],["أَمْ يَقُولُونَ تَقَوَّلَهُ[n[ۥ]‌ۚ بَل لَّا يُؤْمِن[p[ُو]نَ","Балки, уни ўзи тўқиди, дерлар? Йўқ, улар иймон келтирмаслар.",525,27],["فَلْيَأْتُو[s[اْ] بِحَدِي[a:12935[ثٍ م]ِّثْلِه[o[ِۦٓ] إِ[f:5674[ن ك]َانُو[s[اْ] صَ[n[ـٰ]دِق[p[ِي]نَ","Агар уларнинг гапи рост бўлса, уга ўхшаш сўзни келтирсинлар.",525,27],["أَمْ خُلِقُو[s[اْ] مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ [h:12936[ٱ]لْخَ[n[ـٰ]لِق[p[ُو]نَ","Балки, улар ҳеч нарсадан ҳеч нарса йўқ ўзлари яралгандирлар?! Ёки улар яратувчиларми?",525,27],["أَمْ خَلَقُو[s[اْ] [h:12937[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ‌ۚ بَل لَّا يُوقِن[p[ُو]نَ","Балки, улар осмонлару ерни яратгандирлар?! Йўқ, улар ишонмаслар.",525,27],["أَمْ عِ[f:5060[ند]َهُمْ خَز[o[َا]ٓئِنُ رَبِّكَ أَمْ هُمُ [h:12938[ٱ]لْمُصَۣيْطِر[p[ُو]نَ","Балки уларнинг ҳузурида Роббингнинг хазиналари бордир?! Ёки улар бошқарувчиларми?",525,27],["أَمْ لَهُمْ سُلَّ[a:12939[مٌ ي]َسْتَمِعُونَ فِيهِ‌ۖ فَلْيَأْتِ مُسْتَمِعُه[c:12940[ُم ب]ِسُلْطَ[n[ـٰ][a:7067[نٍ م]ُّب[p[ِي]نٍ","Балки уларнинг эшитадиган нарвонлари бордир?! Ундоқ бўлса, эшитувчилари равшан ҳужжат келтирсинлар.",525,27],["أَمْ لَهُ [h:12941[ٱ]لْبَنَ[n[ـٰ]تُ وَلَكُمُ [h:12942[ٱ]لْبَن[p[ُو]نَ","Ёки У зотга қизлару сизларга ўғилларми?!",525,27],["أَمْ تَسْــَٔلُهُمْ أَ[q:2795[جْ][f:12943[رًا ف]َه[w:12944[ُم م]ّ[a:12945[ِن م]َّغْرَ[a:12946[مٍ م]ُّثْقَل[p[ُو]نَ","Ёки сен улардан ҳақ сўраяпсан-у, улар тўловдан қийналаяптиларми?!",525,27],["أَمْ عِ[f:3212[ند]َهُمُ [h:12947[ٱ]لْغَيْبُ فَهُمْ يَكْتُب[p[ُو]نَ","Балки уларнинг ихтиёрида ғайб бўлиб, улар ёзиб олаётгандирлар?!",525,27],["أَمْ يُرِيدُونَ كَيْ[f:12948[دًا‌ۖ ف]َ[h:2514[ٱ]لَّذِينَ كَفَرُو[s[اْ] هُمُ [h:12949[ٱ]لْمَكِيد[p[ُو]نَ","Балки ҳийла кўрсатишни хоҳларлар?! Бас, кофирлар ҳийлаларининг жазосини тортурлар.",525,27],["أَمْ لَهُمْ إِلَ[n[ـٰ]هٌ غَيْرُ [h:4057[ٱ]للَّهِ‌ۚ سُ[q:7648[بْ]حَ[n[ـٰ]نَ [h:9282[ٱ]للَّهِ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","Балки, уларнинг Аллоҳдан бошқа худолари бордир?! Аллоҳ улар келтираётган ширкдан пок бўлди.",525,27],["وَإ[a:3990[ِن ي]َرَوْ[s[اْ] كِسْ[a:12950[فًا م]ِّنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ سَاقِ[a:12951[طًا ي]َقُولُو[s[اْ] سَحَا[a:12952[بٌ م]َّرْك[p[ُو]مٌ","Агар улар бошларига тушаётган парчани кўрсалар ҳам, тўпланган булут, дерлар.",525,27],["فَذَرْهُمْ حَتَّىٰ يُلَ[n[ـٰ]قُو[s[اْ] يَوْمَهُمُ [h:12321[ٱ]لَّذِى فِيهِ يُصْعَق[p[ُو]نَ","Уларни ҳалокатга учрайдиган кунларига йўлиққунларигача тек қўй.",525,27],["يَوْمَ لَا يُغْنِى عَنْهُمْ كَيْدُهُمْ شَيْـ[a:232[ـًٔا و]َلَا هُمْ يُ[f:237[نص]َر[p[ُو]نَ","У кунда ҳийлалари уларга ҳеч қандай фойда бермас ва уларга ёрдам ҳам берилмас.",525,27],["وَإِ[g[نّ]َ لِلَّذِينَ ظَلَمُو[s[اْ] عَذَا[f:12953[بًا د]ُونَ ذ[n[َٲ]لِكَ وَلَ[n[ـٰ]كِ[g[نّ]َ أَكْثَرَهُمْ لَا يَعْلَم[p[ُو]نَ","Ва, албатта, зулм қилганларга ундан ўзга азоб ҳам бор, лекин кўплари билмаслар.",525,27],["وَ[h:9999[ٱ]صْبِرْ لِحُكْمِ رَبِّكَ فَإِ[g[نّ]َكَ بِأَعْيُنِنَا‌ۖ وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَق[p[ُو]مُ","Бас, Роббинг ҳукмига сабр қил. Албатта, сен кўз ўнгимиздасан, ўрингдан турганингда Роббингга тасбиҳ айт!",525,27],["وَمِنَ [h:7856[ٱ]لَّيْلِ فَسَبِّحْهُ وَإِ[q:12954[دْ]بَ[n[ـٰ]رَ [h:12955[ٱ][l[ل][g[نّ]ُج[p[ُو]مِ","Ва кечаси ҳам. Бас, юлдузлар ботгандан кейин ҳам тасбиҳ айт.",525,27]]},{"n":53,"ar":"النَّجۡمِ","en":"An-Najm","uz":"Нажм","type":"Макка","ayahs":[["وَ[h:9999[ٱ][l[ل][g[نّ]َ[q:12956[جْ]مِ إِذَا هَوَىٰ","Ботаётган юлдуз билан қасам.",526,27],["مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ","Сизнинг биродарингиз адашгани ҳам, йўлдан озгани ҳам йўқ.",526,27],["وَمَا يَ[f:9237[نط]ِقُ عَنِ [h:12957[ٱ]لْهَوَىٰٓ","У ҳаводан нутқ қилмас.",526,27],["إِنْ هُوَ إِلَّا وَحْ[a:12958[ىٌ ي]ُوحَىٰ","У ваҳийдан ўзга нарса эмас.",526,27],["عَلَّمَهُ[n[ۥ] شَدِيدُ [h:12959[ٱ]لْقُوَىٰ","Унга шиддатли қувват эгаси ўргатди.",526,27],["ذُو مِرَّ[f:12960[ةٍ ف]َ[h:12710[ٱ]سْتَوَىٰ","Миррат эгаси. Бас кўтарилди.",526,27],["وَهُوَ بِ[h:12961[ٱ]لْأُفُقِ [h:12962[ٱ]لْأَعْلَىٰ","Ва у олий уфқда эди.",526,27],["ثُ[g[مّ]َ دَنَا فَتَدَلَّىٰ","Сўнгра яқинлашди ва жуда ҳам яқин бўлди.",526,27],["فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَ[q:314[دْ]نَىٰ","Бас, икки камон миқдоридай жойгда бўлди. Балки ундан ҳам яқинроқ келди.",526,27],["فَأَوْحَ[o[ىٰٓ] إِلَىٰ عَ[q:7944[بْ]دِه[n[ِۦ] م[o[َآ] أَوْحَىٰ","Ва У зот бандасига нимани ваҳий қилган бўлса, етказди.",526,27],["مَا كَذَبَ [h:12963[ٱ]لْفُؤَادُ مَا رَأَىٰٓ","Қалб кўрганини ёлғонга чиқармади.",526,27],["أَفَتُمَ[n[ـٰ]رُونَهُ[n[ۥ] عَلَىٰ مَا يَرَىٰ","У билан ўзи кўрган нарса устида тортишасизларми?!",526,27],["وَلَقَ[q:341[دْ] رَءَاهُ نَزْلَةً أُخْرَىٰ","Ва дарҳақиқат, уни бошқа сафар кўрди.",526,27],["عِ[f:264[ند]َ سِ[q:12964[دْ]رَةِ [h:12965[ٱ]لْمُ[f:12966[نت]َهَىٰ","Тугаш дарахти олдида.",526,27],["عِ[f:1876[ند]َهَا جَ[g[نّ]َةُ [h:12967[ٱ]لْمَأْوَىٰٓ","Унинг ҳузурида маъво жаннати бор.",526,27],["إِذْ يَغْشَى [h:12968[ٱ][l[ل]سِّ[q:12969[دْ]رَةَ مَا يَغْشَىٰ","Ўшанда, дарахтни ўрайдиган нарса ўраб турибди.",526,27],["مَا زَاغَ [h:12970[ٱ]لْبَصَرُ وَمَا طَغَىٰ","Нигоҳ бурилмади ҳам, ҳаддидан ошмади ҳам.",526,27],["لَقَ[q:2389[دْ] رَأَىٰ مِنْ ءَايَ[n[ـٰ]تِ رَبِّهِ [h:12971[ٱ]لْكُ[q:8463[بْ]رَىٰٓ","Дарҳақиқат, Ўз Роббисининг улкан белгиларидан кўрди.",526,27],["أَفَرَءَيْتُمُ [h:12972[ٱ][l[ل]لَّ[n[ـٰ]تَ وَ[h:12973[ٱ]لْعُزَّىٰ","Лот ва Уззони ўйлаб кўрдингизми?",526,27],["وَمَنَ[s[و][n[ٲ]ةَ [h:12974[ٱ][l[ل]ثَّالِثَةَ [h:12975[ٱ]لْأُخْرَىٰٓ","Ва бошқаси-учинчиси Манотни ҳам?",526,27],["أَلَكُمُ [h:12976[ٱ][l[ل]ذَّكَرُ وَلَهُ [h:12977[ٱ]لْأُ[f:12978[نث]َىٰ","Сизларга эркаг-у, У зотга аёлми?",526,27],["تِلْكَ إِ[f:12979[ذًا ق]ِسْمَ[f:12980[ةٌ ض]ِيزَىٰٓ","Ундоқ бўлса, бу нотўғри тақсим-ку!",526,27],["إِنْ هِىَ إِلّ[o[َآ] أَسْم[o[َا]ٓ[f:12981[ءٌ س]َ[g[مّ]َيْتُمُوه[o[َآ] أَ[f:428[نت]ُمْ وَءَاب[o[َا]ٓؤُك[w:4796[ُم م]ّ[o[َآ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ بِهَا مِ[f:4798[ن س]ُلْطَ[n[ـٰ]نٍ‌ۚ إ[a:4358[ِن ي]َتَّبِعُونَ إِلَّا [h:4359[ٱ][l[ل]ظَّ[g[نّ]َ وَمَا تَهْوَى [h:12982[ٱ]لْأَ[f:3181[نف]ُسُ‌ۖ وَلَقَ[q:341[دْ] ج[o[َا]ٓءَه[w:12983[ُم م]ّ[u:12984[ِن ر]َّبِّهِمُ [h:12985[ٱ]لْهُدَىٰٓ","Улар сиз ва ота-боболарингиз қўйган номлардан ўзга ҳеч нарса эмас. Аллоҳ бунга ҳеч ҳужжат туширган эмас. У лар Роббиларидан ҳидоят келганига қарамай гумон ва ҳавойи нафс хоҳишига эргашарлар, холос.",526,27],["أَمْ لِلْإِ[f:6549[نس]َ[n[ـٰ]نِ مَا تَمَ[g[نّ]َىٰ","Ёки ҳар инсон нимани хоҳласа, шу бўлурми?",526,27],["فَلِلَّهِ [h:12986[ٱ]لْأَخِرَةُ وَ[h:12987[ٱ]لْأُولَىٰ","Зеро, охират ҳам, дунё ҳам Аллоҳникидир.",526,27],["۞ وَك[w:4584[َم م]ّ[a:12988[ِن م]َّلَ[f:12989[كٍ ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ لَا تُغْنِى شَفَ[n[ـٰ]عَتُهُمْ شَيْــًٔا إِلَّا م[i:146[ِنۢ ب]َعْدِ أ[a:12990[َن ي]َأْذَنَ [h:12991[ٱ]للَّهُ لِم[a:1537[َن ي]َش[o[َا]ٓءُ وَيَرْضَىٰٓ","Осмонларда қанчадан-қанча фаришталар мавжуд, уларнинг шафоати ҳеч фойда бермас. Магар Аллоҳ Ўзи хоҳлаган ва рози бўлганларга изн берсагина.",526,27],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ لَا يُؤْمِنُونَ بِ[h:447[ٱ]لْأَخِرَةِ لَيُسَ[g[مّ]ُونَ [h:12992[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةَ تَسْمِيَةَ [h:12993[ٱ]لْأُ[f:12978[نث]َىٰ","Албатта, охиратга иймон келтирмаганлар фаришталарни аёл номи билан номларлар.",527,27],["وَمَا لَه[c:3276[ُم ب]ِه[n[ِۦ] مِنْ عِلْمٍ‌ۖ إ[a:4358[ِن ي]َتَّبِعُونَ إِلَّا [h:4359[ٱ][l[ل]ظَّ[g[نّ]َ‌ۖ وَإِ[g[نّ]َ [h:12994[ٱ][l[ل]ظَّ[g[نّ]َ لَا يُغْنِى مِنَ [h:1173[ٱ]لْحَقِّ شَيْــًٔا","Уларда бу ҳақда ҳеч қандай илм йўқ. Гумондан бошқа нарсага эргашмаслар. Албатта, гумон ҳақиқат ўрнига ўтмас.",527,27],["فَأَعْرِضْ ع[a:9475[َن م]َّ[f:12995[ن ت]َوَلَّىٰ عَ[f:8039[ن ذ]ِكْرِنَا وَلَمْ يُرِ[q:2293[دْ] إِلَّا [h:12996[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَا","Бизнинг зикримизга орқа ўгирган, ҳаёти дунёдан бошқани хоҳламайдиганлардан юз ўгир.",527,27],["ذ[n[َٲ]لِكَ مَ[q:12997[بْ]لَغُه[w:12998[ُم م]ِّنَ [h:634[ٱ]لْعِلْمِ‌ۚ إِ[g[نّ]َ رَبَّكَ هُوَ أَعْلَمُ بِمَ[f:7639[ن ض]َلَّ عَ[f:4361[ن س]َبِيلِه[n[ِۦ] وَهُوَ أَعْلَمُ بِمَنِ [h:12999[ٱ]هْتَدَىٰ","Уларнинг эришган илмлари мана шу. Албатта, Роббинг Унинг йўлидан адашганларни билгувчидир ва ҳидоятдагиларни ҳам билгувчидир.",527,27],["وَلِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ لِيَ[q:5945[جْ]زِىَ [h:5946[ٱ]لَّذِينَ أَسَ[o[ـٰٓـ]ــُٔو[s[اْ] بِمَا عَمِلُو[s[اْ] وَيَ[q:13000[جْ]زِىَ [h:13001[ٱ]لَّذِينَ أَحْسَنُو[s[اْ] بِ[h:13002[ٱ]لْحُسْنَى","Осмонлару ердаги барча нарсалар Аллоҳникидир. У ёмонлик қилганларни амалига яраша жазолар ва яхшилик қилганларни гўзалила мукофотлар.",527,27],["ٱلَّذِينَ يَ[q:12147[جْ]تَنِبُونَ كَبَ[o[ـٰٓ]ئِرَ [h:12148[ٱ]لْإِثْمِ وَ[h:12149[ٱ]لْفَو[n[َٲ]حِشَ إِلَّا [h:13003[ٱ][l[ل]لَّمَمَ‌ۚ إِ[g[نّ]َ رَبَّكَ و[n[َٲ]سِعُ [h:13004[ٱ]لْمَغْفِرَةِ‌ۚ هُوَ أَعْلَمُ بِكُمْ إِذْ أَ[f:4272[نش]َأَك[w:6398[ُم م]ِّنَ [h:1579[ٱ]لْأَرْضِ وَإِذْ أَ[f:428[نت]ُمْ أَجِ[g[نّ]َ[f:13005[ةٌ ف]ِى بُطُونِ أُ[g[مّ]َهَ[n[ـٰ]تِكُمْ‌ۖ فَلَا تُزَكّ[o[ُوٓ][s[اْ] أَ[f:221[نف]ُسَكُمْ‌ۖ هُوَ أَعْلَمُ بِمَنِ [h:13006[ٱ]تَّقَىٰٓ","Улар кичик гуноҳлардан бошқа катта гуноҳлар ва фаҳш ишлардан четда бўладиганлардир. Албатта, Роббинг мағфирати кенг зотдир. У сизларни тупроқдан пайдо қилганда ҳам, оналарингиз қоринларида ҳомилалик чоғингизни ҳам яхши билувчидир. Шундоқ экан, ўзингизни оқламанг, У ким тақводорлигини яхши биладир.",527,27],["أَفَرَءَيْتَ [h:8408[ٱ]لَّذِى تَوَلَّىٰ","Юз ўгириб кетганни кўрмадингми?!",527,27],["وَأَعْطَىٰ قَلِيل[a:13007[اً و]َأَكْدَىٰٓ","У озгина берди ва тўхтатди.",527,27],["أَعِ[f:13008[ند]َهُ[n[ۥ] عِلْمُ [h:13009[ٱ]لْغَيْبِ فَهُوَ يَرَىٰٓ","Унинг ҳузурида ғайб илми бору, у кўриб турибдими?!",527,27],["أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ","Ёки Мусонинг саҳифаларидаги сўзлар хабари унга берилмадими?",527,27],["وَإِ[q:10311[بْ]ر[n[َٲ]هِيمَ [h:13010[ٱ]لَّذِى وَفَّىٰٓ","Ва вафо қилган Иброҳимнинг?",527,27],["أَلَّا تَزِرُ وَازِرَ[a:4572[ةٌ و]ِزْرَ أُخْرَىٰ","«Ҳеч бир гуноҳкор жон бошқанинг гуноҳини кўтармас.",527,27],["وَأ[u:13011[َن ل]َّيْسَ لِلْإِ[f:6549[نس]َ[n[ـٰ]نِ إِلَّا مَا سَعَىٰ","Ҳар бир инсонга ўз қилганидан бошқа нарса йўқ.",527,27],["وَأَ[g[نّ]َ سَعْيَهُ[n[ۥ] سَوْفَ يُرَىٰ","Ва, албатта, унинг қилмиши тезда кўринар.",527,27],["ثُ[g[مّ]َ يُ[q:13012[جْ]زَ[n[ٮٰ]هُ [h:13013[ٱ]لْجَز[o[َا]ٓءَ [h:13014[ٱ]لْأَوْفَىٰ","Сўнгра жазо ёки мукофоти тўлиқ берилар», деб.",527,27],["وَأَ[g[نّ]َ إِلَىٰ رَبِّكَ [h:13015[ٱ]لْمُ[f:12966[نت]َهَىٰ","Ва, албатта, интиҳо Роббинг ҳузуридадир.",527,27],["وَأَ[g[نّ]َهُ[n[ۥ] هُوَ أَضْحَكَ وَأَ[q:13016[بْ]كَىٰ","Ва, албатта, кулдирган ҳам Ўзи, йиғлатган ҳам Ўзи.",527,27],["وَأَ[g[نّ]َهُ[n[ۥ] هُوَ أَمَاتَ وَأَحْيَا","Албатта, ўлдирган ҳам Ўзи, тирилтирган ҳам Ўзи.",527,27],["وَأَ[g[نّ]َهُ[n[ۥ] خَلَقَ [h:13017[ٱ][l[ل]زَّوْجَيْنِ [h:13018[ٱ][l[ل]ذَّكَرَ وَ[h:929[ٱ]لْأُ[f:929[نث]َىٰ","Албатта, икки жуфтни; эркак ва аёлни яратган ҳам Ўзи.",528,27],["م[a:7325[ِن ن]ُّ[q:7326[طْ]فَةٍ إِذَا تُمْنَىٰ","Нутфадан, оқиб тушганда.",528,27],["وَأَ[g[نّ]َ عَلَيْهِ [h:13019[ٱ][l[ل][g[نّ]َشْأَةَ [h:13020[ٱ]لْأُخْرَىٰ","Ва, албатта, кейинги пайдо қилиш зиммасидаги зот ҳам Ўзи.",528,27],["وَأَ[g[نّ]َهُ[n[ۥ] هُوَ أَغْنَىٰ وَأَ[q:13021[قْ]نَىٰ","Ва, албатта, беҳожат қилган ҳам Ўзи, бадавлат қилган ҳам Ўзи.",528,27],["وَأَ[g[نّ]َهُ[n[ۥ] هُوَ رَبُّ [h:13022[ٱ][l[ل]شِّعْرَىٰ","Ва, албатта Шеъронинг Роббиси ҳам Унинг Ўзи.",528,27],["وَأَ[g[نّ]َهُ[o[ۥٓ] أَهْلَكَ عَادًا [h:13023[ٱ]لْأُولَىٰ","Ва, албатта, биринчи Одни ҳалок қилган ҳам Ўзи.",528,27],["وَثَمُودَ[s[اْ] فَم[o[َآ] أَ[q:13024[بْ]قَىٰ","Ва Самудни боқий қолдирмаган ҳам Ўзи.",528,27],["وَقَوْمَ نُو[a:12873[حٍ م]ِّ[f:128[ن ق]َ[q:129[بْ]لُ‌ۖ إِ[g[نّ]َهُمْ كَانُو[s[اْ] هُمْ أَظْلَمَ وَأَ[q:13025[طْ]غَىٰ","Ва бундан олдин Нуҳ қавмини. Чунки улар ўта золим ва ўта туғёнга кетган эдилар.",528,27],["وَ[h:9999[ٱ]لْمُؤْتَفِكَةَ أَهْوَىٰ","Ва тўнтарилганни қулатган.",528,27],["فَغَشَّ[n[ـٰ]هَا مَا غَشَّىٰ","Бас, уларни ўраган нарса ўраб олди.",528,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكَ تَتَمَارَىٰ","Шундай экан, Роббингнинг қайси неъматларига шак келтирасан?",528,27],["هَ[n[ـٰ]ذَا نَذِي[a:13026[رٌ م]ِّنَ [h:13027[ٱ][l[ل][g[نّ]ُذُرِ [h:13028[ٱ]لْأُولَىٰٓ","Бу аввалги огоҳлантирувчилар каби бир огоҳлантирувчидир.",528,27],["أَزِفَتِ [h:13029[ٱ]لْأَزِفَةُ","Яқинлашувчи яқинлашди.",528,27],["لَيْسَ لَهَا مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ كَاشِفَةٌ","Уни Аллоҳдан бошқа кашф қилувчи йўқ.",528,27],["أَفَمِنْ هَ[n[ـٰ]ذَا [h:13030[ٱ]لْحَدِيثِ تَعْجَب[p[ُو]نَ","Бу сўздан сизлар ажабланасизларми?",528,27],["وَتَضْحَكُونَ وَلَا تَ[q:13031[بْ]ك[p[ُو]نَ","Ва куласизлар-у, йиғламайсизларми?",528,27],["وَأَ[f:98[نت]ُمْ سَ[n[ـٰ]مِد[p[ُو]نَ","Ва ҳолбуки, сизлар бепарвосизлар.",528,27],["فَ[h:9999[ٱ]سْجُدُو[s[اْ] لِلَّهِ وَ[h:9127[ٱ]عْبُدُو[s[اْ] ۩","Бас, ллоҳга сажда ва ибодат қилинглар.",528,27]]},{"n":54,"ar":"القَمَرِ","en":"Al-Qamar","uz":"Қамар","type":"Макка","ayahs":[["ٱ[q:13032[قْ]تَرَبَتِ [h:13033[ٱ][l[ل]سَّاعَةُ وَ[h:13034[ٱ][f:13034[نش]َقَّ [h:13035[ٱ]لْقَمَرُ","Соат яқинлашди ва ой бўлинди.",528,27],["وَإ[a:3990[ِن ي]َرَوْ[s[اْ] ءَايَ[a:13036[ةً ي]ُعْرِضُو[s[اْ] وَيَقُولُو[s[اْ] سِحْ[a:13037[رٌ م]ُّسْتَمِرٌّ","Агар бир оят-мўъжизани кўрсалар, юз ўгирарлар, бу ўткинчи сеҳр, дерлар.",528,27],["وَكَذَّبُو[s[اْ] وَ[h:2433[ٱ]تَّبَع[o[ُوٓ][s[اْ] أَهْو[o[َا]ٓءَهُمْ‌ۚ وَكُلُّ أَمْ[a:13038[رٍ م]ُّسْتَقِرٌّ","Ва ёлғонга чиқардилар ҳамда ҳавойи нафсларига эргашдилар. Ҳолбуки, ҳар бир иш ўз ўрнини топувчидир.",528,27],["وَلَقَ[q:341[دْ] ج[o[َا]ٓءَه[w:13039[ُم م]ِّنَ [h:13040[ٱ]لْأَ[i:13041[نۢب][o[َا]ٓءِ مَا فِيهِ مُزْدَجَرٌ","Ва, дарҳақиқат, уларга зажри бор хабарлардан келган эди.",528,27],["حِكْمَ[i:13042[ةُۢ ب]َ[n[ـٰ]لِغَ[f:13043[ةٌ‌ۖ ف]َمَا تُغْنِ [h:13044[ٱ][l[ل][g[نّ]ُذُرُ","етук ҳикматдир. Бас, огоҳлантирувчилар фойда бермас.",528,27],["فَتَوَلَّ عَنْهُمْ‌ۘ يَوْمَ يَ[q:9312[دْ]عُ [h:13045[ٱ][l[ل]دَّاعِ إِلَىٰ ش[a:13046[َىْءٍ ن]ُّكُرٍ","Бас, улардан юз ўгир! Чақирувчи мункар нарсага чақирган кунда. қабрлардан, кўзлари қўрқинчга тўлган ҳолда, худди ёйилган чигирткага ўхшаб чиқиб келадилар.",528,27],["خُشَّعًا أَ[q:4718[بْ]صَ[n[ـٰ]رُهُمْ يَخْرُجُونَ مِنَ [h:11261[ٱ]لْأَ[q:11262[جْ]دَاثِ كَأَ[g[نّ]َهُمْ جَرَا[a:13047[دٌ م]ُّ[f:13048[نت]َشِرٌ","Улар қабрлардан, кўзлари қўрқинчга тўлган ҳолда, худди ёйилган чигирткага ўхшаб чиқиб келурлар.",529,27],["مُّهْطِعِينَ إِلَى [h:13049[ٱ][l[ل]دَّاعِ‌ۖ يَقُولُ [h:13050[ٱ]لْكَ[n[ـٰ]فِرُونَ هَ[n[ـٰ]ذَا يَوْمٌ عَسِرٌ","Чақирувчига қараб бўйинларини чўзиб, шошилиб борурлар. Кофирлар, бу қийин кун-ку, дерлар.",529,27],["۞ كَذَّبَتْ قَ[q:8394[بْ]لَهُمْ قَوْمُ نُو[f:13051[حٍ ف]َكَذَّبُو[s[اْ] عَ[q:11499[بْ]دَنَا وَقَالُو[s[اْ] مَ[q:12342[جْ]نُو[a:13052[نٌ و]َ[h:13053[ٱ]زْدُجِرَ","Булардан олдин Нуҳ қавми ҳам ёлғончи қилган эди. Бас бандамизни ёлғончига чиқаришди ва, мажнун, дейишди. Ҳамда унга тўсиқлар қўйишди.",529,27],["فَدَعَا رَبَّهُ[o[ۥٓ] أَ[g[نّ]ِى مَغْلُو[f:13054[بٌ ف]َ[h:13055[ٱ][f:13055[نت]َصِرْ","Бас, у Роббисига дуо қилиб: «Албатта, мен мағлуб бўлдим, ёрдам бер», деди.",529,27],["فَفَتَحْن[o[َآ] أَ[q:4047[بْ]و[n[َٲ]بَ [h:13056[ٱ][l[ل]سَّم[o[َا]ٓءِ بِم[o[َا]ٓ[a:13057[ءٍ م]ُّنْهَمِرٍ","Осмон эшикларини шаррос сув билан очиб юбордик.",529,27],["وَفَجَّرْنَا [h:13058[ٱ]لْأَرْضَ عُيُو[f:13059[نًا ف]َ[h:13060[ٱ]لْتَقَى [h:13061[ٱ]لْم[o[َا]ٓءُ عَلَ[o[ىٰٓ] أَمْ[f:13062[رٍ ق]َ[q:298[دْ] قُدِرَ","Ва ердан отилтириб, булоқлар чиқардик. Бас, сувлар тақдир қилинган иш учун бирлашдилар.",529,27],["وَحَمَلْنَ[n[ـٰ]هُ عَلَىٰ ذَاتِ أَلْو[n[َٲ][a:13063[حٍ و]َدُسُرٍ","Ва уни тахталари ва михлари бор нарса устига кўтардик.",529,27],["تَ[q:120[جْ]رِى بِأَعْيُنِنَا جَز[o[َا]ٓ[u:13064[ءً ل]ِّمَ[f:10739[ن ك]َانَ كُفِرَ","У инкор қилинган шахс га мукофот бўлиб, Бизнинг иноятимиз ила юрадир.",529,27],["وَلَقَ[d:13065[د] تَّرَكْنَ[n[ـٰ]ه[o[َآ] ءَايَ[f:13066[ةً ف]َهَلْ م[a:13067[ِن م]ُّدَّكِرٍ","Ва уни белги қилиб қолдирдик. Қани, ибрат олувчи борми?",529,27],["فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ","Бас, Менинг азобим ва огоҳлантиришим қандоқ бўлди?!",529,27],["وَلَقَ[q:341[دْ] يَسَّرْنَا [h:13068[ٱ]لْقُرْءَانَ لِلذِّكْرِ فَهَلْ م[a:13067[ِن م]ُّدَّكِرٍ","Дарҳақиқат, Биз Қуръонни зикр учун осон қилдик. Бас, зикр қилувчи борми?!",529,27],["كَذَّبَتْ عَا[f:13069[دٌ ف]َكَيْفَ كَانَ عَذَابِى وَنُذُرِ","Од ёлғончига чиқарди. Бас, Менинг азобим ва огоҳлантиришим қандоқ бўлди?",529,27],["إِ[g[نّ][o[َآ] أَرْسَلْنَا عَلَيْهِمْ رِي[f:11982[حًا ص]َرْصَ[f:11983[رًا ف]ِى يَوْمِ نَحْ[a:13070[سٍ م]ُّسْتَمِرٍّ","Биз давомли машъум кунда улар устига сорсор шамолини юбордик.",529,27],["تَ[f:13071[نز]ِعُ [h:13072[ٱ][l[ل][g[نّ]َاسَ كَأَ[g[نّ]َهُمْ أَعْجَازُ نَخْ[a:13073[لٍ م]ُّ[f:13074[نق]َعِرٍ","У одамларни, худди хурмо дарахтини томири билан қўпоргандек, узиб-учириб ташларди.",529,27],["فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ","Бас, Менинг азобим ва огоҳлантиришим қандоқ бўлди?!",529,27],["وَلَقَ[q:341[دْ] يَسَّرْنَا [h:13068[ٱ]لْقُرْءَانَ لِلذِّكْرِ فَهَلْ م[a:13067[ِن م]ُّدَّكِرٍ","Дарҳақиқат, Биз Қуръонни зикр учун осон қилдик. Бас, зикр қилувчи борми?!",529,27],["كَذَّبَتْ ثَمُودُ بِ[h:13075[ٱ][l[ل][g[نّ]ُذُرِ","Самуд огоҳлантирувчиларни ёлғонга чиқарди.",529,27],["فَقَال[o[ُوٓ][s[اْ] أَبَشَ[a:13076[رًا م]ِّ[g[نّ]َا و[n[َٲ]حِ[a:13077[دًا ن]َّتَّبِعُهُ[o[ۥٓ] إِ[g[نّ][o[َآ] إِ[u:11213[ذًا ل]َّفِى ضَلَ[n[ـٰ][a:13078[لٍ و]َسُعُرٍ","Улар: «Биз ўзимиздан бўлган бир одамга эргашамизми? Агар шундай бўлса, албатта, адашувда ва жинниликда бўламиз.",529,27],["أَءُلْقِىَ [h:13079[ٱ][l[ل]ذِّكْرُ عَلَيْهِ م[i:4086[ِنۢ ب]َيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌ","Бизларнинг орамиздан унга зикр туширилибдими; Йўқ, у ёлғончи ва кеккайгандир», дедилар.",529,27],["سَيَعْلَمُونَ غَ[a:13080[دًا م]َّنِ [h:13081[ٱ]لْكَذَّابُ [h:13082[ٱ]لْأَشِرُ","Эртага ким ёлғончи ва кеккайган эканини билурлар.",529,27],["إِ[g[نّ]َا مُرْسِلُو[s[اْ] [h:13083[ٱ][l[ل][g[نّ]َاقَةِ فِتْنَ[u:13084[ةً ل]َّهُمْ فَ[h:13085[ٱ]رْتَقِ[q:13085[بْ]هُمْ وَ[h:8381[ٱ]صْطَبِرْ","Биз уларни синаш учун туяни юборувчимиз. Уларни кузатиб тур ва сабр қил.",529,27],["وَنَبِّئْهُمْ أَ[g[نّ]َ [h:13086[ٱ]لْم[o[َا]ٓءَ قِسْمَ[i:13087[ةُۢ ب]َيْنَهُمْ‌ۖ كُلُّ شِرْ[a:13088[بٍ م]ُّحْتَضَرٌ","Ва уларга, албатта, сув ораларида тақсимланганининг хабарини бер. Ҳар бир ичишга ҳозир бўлинар.",530,27],["فَنَادَوْ[s[اْ] صَاحِبَهُمْ فَتَعَاطَىٰ فَعَقَرَ","Бас, улар ўз шерикларини чақирдилар. У тутди ва сўйиб юборди.",530,27],["فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ","Бас, Менинг азобим ва огоҳлантиришим қандоқ бўлди?!",530,27],["إِ[g[نّ][o[َآ] أَرْسَلْنَا عَلَيْهِمْ صَيْحَ[a:11222[ةً و][n[َٲ]حِدَ[f:13089[ةً ف]َكَانُو[s[اْ] كَهَشِيمِ [h:13090[ٱ]لْمُحْتَظِرِ","Албатта, Биз уларга бир овоз юбордик. Ва улар қўра қурувчи қуруқ шох-шаббаларга ўхшаб қолдилар.",530,27],["وَلَقَ[q:341[دْ] يَسَّرْنَا [h:13068[ٱ]لْقُرْءَانَ لِلذِّكْرِ فَهَلْ م[a:13067[ِن م]ُّدَّكِرٍ","Дарҳақиқат, Биз Қуръонни зикр учун осон қилдик. Бас, зикр қилувчи борми?!",530,27],["كَذَّبَتْ قَوْمُ لُو[i:13091[طِۭ ب]ِ[h:13075[ٱ][l[ل][g[نّ]ُذُرِ","Лут қавми огоҳлантирувчиларни ёлғончига чиқарди.",530,27],["إِ[g[نّ][o[َآ] أَرْسَلْنَا عَلَيْهِمْ حَاصِبًا إِلّ[o[َآ] ءَالَ لُو[a:13092[طٍ‌ۖ ن]َّجَّيْنَ[n[ـٰ]ه[c:13093[ُم ب]ِسَحَرٍ","Албатта, Биз уларнинг устига бўрон юбордик. Фақат Лут хонадонига саҳар чоғи нажот бердик.",530,27],["نِّعْمَ[a:13094[ةً م]ِّنْ عِ[f:6142[ند]ِنَا‌ۚ كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى مَ[f:13095[ن ش]َكَرَ","Бу Биз тарафимиздан неъмат бўлди. Кимки шукр қилса, худди шундай мукофотлармиз.",530,27],["وَلَقَ[q:341[دْ] أَ[f:13096[نذ]َرَه[c:13097[ُم ب]َ[q:13098[طْ]شَتَنَا فَتَمَارَوْ[s[اْ] بِ[h:13075[ٱ][l[ل][g[نّ]ُذُرِ","Дарҳақиқат, у уларни Бизнинг тутишимиздан огоҳлантирган эди. Бас, улар огоҳлантиришларга ишонмадилар.",530,27],["وَلَقَ[q:341[دْ] ر[n[َٲ]وَدُوهُ عَ[f:13099[ن ض]َيْفِه[n[ِۦ] فَطَمَسْن[o[َآ] أَعْيُنَهُمْ فَذُوقُو[s[اْ] عَذَابِى وَنُذُرِ","Улар ундан меҳмонларини топширишни сўрадилар. Бас, кўзларини кўр қилдик. Менинг азобим ва огоҳлантиришларимни тотиб кўрсинлар.",530,27],["وَلَقَ[q:341[دْ] صَبَّحَه[c:13100[ُم ب]ُكْرَةً عَذَا[a:13101[بٌ م]ُّسْتَقِرٌّ","Батаҳқиқ, эрта тонгда уларни собит, давомли азоб тутди.",530,27],["فَذُوقُو[s[اْ] عَذَابِى وَنُذُرِ","Бас, Менинг азобларимни ва огоҳлантиришларимни татиб кўринглар!",530,27],["وَلَقَ[q:341[دْ] يَسَّرْنَا [h:13068[ٱ]لْقُرْءَانَ لِلذِّكْرِ فَهَلْ م[a:13067[ِن م]ُّدَّكِرٍ","Дарҳақиқат, Биз Қуръонни зикр учун осон қилдик. Бас, зикр қилувчи борми?!",530,27],["وَلَقَ[q:341[دْ] ج[o[َا]ٓءَ ءَالَ فِرْعَوْنَ [h:13102[ٱ][l[ل][g[نّ]ُذُرُ","Дарҳақиқат, Фиръавн аҳлига огоҳлантиришлар келди.",530,27],["كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا كُلِّهَا فَأَخَذْنَ[n[ـٰ]هُمْ أَخْذَ عَزِي[a:13103[زٍ م]ُّ[q:13104[قْ]تَدِرٍ","Улар Бизнинг оятларимизнинг барчасини ёлғонга чиқаришди. Бас, Биз уларни ғолиб, қудратли олувчининг олиши билан олдик.",530,27],["أَكُفَّارُكُمْ خَيْ[a:1231[رٌ م]ِّنْ أُ[s[وْ]لَ[o[ـٰٓ]ئِكُمْ أَمْ لَك[c:13105[ُم ب]َر[o[َا]ٓءَ[f:13106[ةٌ ف]ِى [h:13107[ٱ][l[ل]زُّبُرِ","Сизнинг кофирларингиз аввалгиларингиздан яхшироқми?! Ёки самовий китобларда сизларга оқлов борми?!",530,27],["أَمْ يَقُولُونَ نَحْنُ جَمِي[a:13108[عٌ م]ُّ[f:13109[نت]َصِرٌ","Ёки, Биз нусратга эришувчи жамоатмиз, дейишадими?!",530,27],["سَيُهْزَمُ [h:13110[ٱ]لْجَمْعُ وَيُوَلُّونَ [h:13111[ٱ][l[ل]دُّبُرَ","У жамоа тезда енгилар ва орқаларига қараб қочарлар.",530,27],["بَلِ [h:13112[ٱ][l[ل]سَّاعَةُ مَوْعِدُهُمْ وَ[h:12438[ٱ][l[ل]سَّاعَةُ أَ[q:13113[دْ]هَىٰ وَأَمَرُّ","Йўқ! Уларга ваъда қилинган вақт, соатдир. Ва соат улканроқ ва аччиқроқдир.",530,27],["إِ[g[نّ]َ [h:12309[ٱ]لْمُ[q:4093[جْ]رِمِينَ فِى ضَلَ[n[ـٰ][a:13078[لٍ و]َسُعُرٍ","Албатта, жинояткорлар адашувда ва олов-оташдадирлар.",530,27],["يَوْمَ يُسْحَبُونَ فِى [h:4674[ٱ][l[ل][g[نّ]َارِ عَلَىٰ وُجُوهِهِمْ ذُوقُو[s[اْ] مَسَّ سَقَرَ","Юзтубан дўзахга судраладиган кунларида: «Жаҳаннам азобини татиб кўринг!».",530,27],["إِ[g[نّ]َا كُلَّ شَىْءٍ خَلَ[q:7232[قْ]نَ[n[ـٰ]هُ بِقَدَرٍ","Албатта, Биз ҳар нарсани ўлчов билан яратдик.",530,27],["وَم[o[َآ] أَمْرُن[o[َآ] إِلَّا و[n[َٲ]حِدَ[f:13114[ةٌ ك]َلَمْ[i:13115[حِۭ ب]ِ[h:13116[ٱ]لْبَصَرِ","Бизнинг фармонимиз бир сўздан ўзга эмас. Кўз юмгунча бўлур.",531,27],["وَلَقَ[q:341[دْ] أَهْلَكْن[o[َآ] أَشْيَاعَكُمْ فَهَلْ م[a:13067[ِن م]ُّدَّكِرٍ","Дарҳақиқат, Биз сизга ўхшаганларни ҳалок қилдик. Бас, буни эсловчи борми ўзи?!",531,27],["وَكُلُّ ش[f:13117[َىْءٍ ف]َعَلُوهُ فِى [h:13107[ٱ][l[ل]زُّبُرِ","Ва уларнинг ҳар бир иши китоблардадир.",531,27],["وَكُلُّ صَغِي[a:13118[رٍ و]َكَبِي[a:13119[رٍ م]ُّسْتَطَرٌ","Ҳар бир кичигу катта сатрлангандир.",531,27],["إِ[g[نّ]َ [h:7256[ٱ]لْمُتَّقِينَ فِى جَ[g[نّ]َ[n[ـٰ][a:13120[تٍ و]َنَهَرٍ","Албатта, тақводорлар жаннату анҳорларда.",531,27],["فِى مَ[q:13121[قْ]عَدِ صِ[q:5937[دْ]قٍ عِ[f:264[ند]َ مَلِي[a:13122[كٍ م]ُّ[q:13104[قْ]تَدِرِۭ","Сидқ ўриндиқда, қудратли Подшоҳ ҳузуридадирлар.",531,27]]},{"n":55,"ar":"الرَّحۡمَٰن","en":"Ar-Rahmaan","uz":"Раҳмон","type":"Мадина","ayahs":[["ٱ[l[ل]رَّحْمَ[p[ـٰ]نُ","Роҳман.",531,27],["عَلَّمَ [h:13123[ٱ]لْقُرْء[p[َا]نَ","Қуръони ўргатди.",531,27],["خَلَقَ [h:7324[ٱ]لْإِ[f:5969[نس]َ[p[ـٰ]نَ","Инсонни яратди.",531,27],["عَلَّمَهُ [h:13124[ٱ]لْبَي[p[َا]نَ","Унга баённи ўргатди.",531,27],["ٱ[l[ل]شَّمْسُ وَ[h:8956[ٱ]لْقَمَرُ بِحُسْب[p[َا]نٍ","Қуёш ва ой ҳисобдадир.",531,27],["وَ[h:9999[ٱ][l[ل][g[نّ]َ[q:13125[جْ]مُ وَ[h:8958[ٱ][l[ل]شَّجَرُ يَسْجُد[p[َا]نِ","Ўт-ўлан ҳам, дарахтлар ҳам сажда қилурлар.",531,27],["وَ[h:9999[ٱ][l[ل]سَّم[o[َا]ٓءَ رَفَعَهَا وَوَضَعَ [h:13126[ٱ]لْمِيز[p[َا]نَ","Осмонни баланд кўтарди ва тарозуни ўрнатди.",531,27],["أَلَّا تَ[q:6515[طْ]غَوْ[s[اْ] فِى [h:13127[ٱ]لْمِيز[p[َا]نِ","Тортишда ҳаддан ошмаслигингиз учун.",531,27],["وَأَقِيمُو[s[اْ] [h:13128[ٱ]لْوَزْنَ بِ[h:1800[ٱ]لْقِسْطِ وَلَا تُخْسِرُو[s[اْ] [h:13129[ٱ]لْمِيز[p[َا]نَ","Адолат ила ўлчанг ва тарозудан уриб қолманг.",531,27],["وَ[h:9999[ٱ]لْأَرْضَ وَضَعَهَا لِلْأَن[p[َا]مِ","Ва ерни ҳалойиқ учун қўйди.",531,27],["فِيهَا فَ[n[ـٰ]كِهَ[a:13130[ةٌ و]َ[h:13131[ٱ][l[ل][g[نّ]َخْلُ ذَاتُ [h:13132[ٱ]لْأَكْم[p[َا]مِ","Уда мевалар ва гулкосали хурмолар бор.",531,27],["وَ[h:9999[ٱ]لْحَبُّ ذُو [h:13133[ٱ]لْعَصْفِ وَ[h:13134[ٱ][l[ل]رَّيْح[p[َا]نُ","Ва сомонли донлар ҳамда райҳон бор.",531,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",531,27],["خَلَقَ [h:7324[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ مِ[f:7229[ن ص]َلْصَ[n[ـٰ][f:13135[لٍ ك]َ[h:13136[ٱ]لْفَخّ[p[َا]رِ","Инсонни сополга ўхшаш қуриган лойдан яратди.",531,27],["وَخَلَقَ [h:13137[ٱ]لْج[m[َا]ٓ[g[نّ]َ م[a:13138[ِن م]َّارِ[a:13139[جٍ م]ّ[a:4598[ِن ن]ّ[p[َا]رٍ","Ва жинларни алангадан яратди.",531,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз.",531,27],["رَبُّ [h:13140[ٱ]لْمَشْرِقَيْنِ وَرَبُّ [h:13141[ٱ]لْمَغْرِبَ[p[يْ]نِ","У икки машриқ ва икки мағрибнинг Роббисидир.",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?",532,27],["مَرَجَ [h:9669[ٱ]لْبَحْرَيْنِ يَلْتَقِي[p[َا]نِ","Дарё-денгизларни бир-бири билан учрашадиган қилиб қўйди.",532,27],["بَيْنَهُمَا بَرْزَ[u:13142[خٌ ل]َّا يَ[q:13143[بْ]غِي[p[َا]نِ","Ўрталаридаги тўсиқдан ошиб ўтолмаслар.",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?",532,27],["يَخْرُجُ مِنْهُمَا [h:13144[ٱ][l[ل]لُّؤْلُؤُ وَ[h:13145[ٱ]لْمَرْج[p[َا]نُ","У иккисидан луълуъ ва маржон чиқар.",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматлрини ёлғон дея олурсиз?!",532,27],["وَلَهُ [h:13146[ٱ]لْجَوَارِ [h:13147[ٱ]لْمُ[f:13148[نش]َـَٔـاتُ فِى [h:837[ٱ]لْبَحْرِ كَ[h:12143[ٱ]لْأَعْلَ[p[ـٰ]مِ","Денгизларда тоғдек бўлиб сузиб юрувчилар ҳам Уникидир.",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",532,27],["كُلُّ مَنْ عَلَيْهَا ف[p[َا]نٍ","юзидаги барча жонзот фонийдир.",532,27],["وَيَ[q:13149[بْ]قَىٰ وَ[q:603[جْ]هُ رَبِّكَ ذُو [h:13150[ٱ]لْجَلَ[n[ـٰ]لِ وَ[h:13151[ٱ]لْإِكْر[p[َا]مِ","Улуғлик ва икром эгаси Роббингнинг Ўзигина боқийдир.",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?",532,27],["يَسْــَٔلُهُ[n[ۥ] مَ[f:2074[ن ف]ِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ كُلَّ يَوْمٍ هُوَ فِى شَأْنٍ","Ундан еру осмондаги жонзотлар сўрарлар. У ҳар куни ишдадир.",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",532,27],["سَنَفْرُغُ لَكُمْ أَيُّهَ [h:13152[ٱ][l[ل]ثَّقَل[p[َا]نِ","Албатта, сизлар учун вақт топармиз, эй инсу жинлар!",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",532,27],["يَ[n[ـٰ]مَعْشَرَ [h:4407[ٱ]لْجِ[g[نّ]ِ وَ[h:4418[ٱ]لْإِ[f:4418[نس]ِ إِنِ [h:13153[ٱ]سْتَطَعْتُمْ أَ[f:13154[ن ت]َ[f:13155[نف]ُذُو[s[اْ] مِنْ أَ[q:13156[قْ]طَارِ [h:13157[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ فَ[h:13158[ٱ][f:13158[نف]ُذُو[s[اْ‌ۚ] لَا تَ[f:13159[نف]ُذُونَ إِلَّا بِسُلْطَ[p[ـٰ]نٍ","Эй жин ва инс жамоалари, агар сиз осмонлару ер чегараларидан чиқиб кетишга қодир бўлсаларингиз, чиқаверинглар. Фақат Султон ила чиқа олурсиз, холос.",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",532,27],["يُرْسَلُ عَلَيْكُمَا شُوَا[a:13160[ظٌ م]ّ[a:4598[ِن ن]َّا[a:13161[رٍ و]َنُحَا[f:13162[سٌ ف]َلَا تَ[f:13163[نت]َصِر[p[َا]نِ","Устингиздан ўт-чўғ ва тутун юборилур. Бас, қутула олмассиз.",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",532,27],["فَإِذَا [h:13164[ٱ][f:13165[نش]َقَّتِ [h:13166[ٱ][l[ل]سَّم[o[َا]ٓءُ فَكَانَتْ وَرْدَ[f:13167[ةً ك]َ[h:13168[ٱ][l[ل]دِّه[p[َا]نِ","Осмон ёрилиб, қирмизи мойга айланган вақтда...",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",532,27],["فَيَوْمَئِ[u:10538[ذٍ ل]َّا يُسْــَٔلُ عَ[f:13169[ن ذ]َ[i:13170[نۢب]ِه[o[ِۦٓ] إِن[a:13171[سٌ و]َلَا ج[m[َا]ٓ[g[نّ]ٌ","Бас, у кунда инс ҳам, жин ҳам гуноҳидан сўралмас.",532,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",532,27],["يُعْرَفُ [h:13172[ٱ]لْمُ[q:5255[جْ]رِمُونَ بِسِيمَ[n[ـٰ]هُمْ فَيُؤْخَذُ بِ[h:13173[ٱ][l[ل][g[نّ]َو[n[َٲ]صِى وَ[h:13174[ٱ]لْأَ[q:13174[قْ]د[p[َا]مِ","Жиноятчмлар сиймоларидан билиниб турур. Ва уларнинг пешона сочлари ва оёқларидан тутилур.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["هَ[n[ـٰ]ذِه[n[ِۦ] جَهَ[g[نّ]َمُ [h:11279[ٱ]لَّتِى يُكَذِّبُ بِهَا [h:13175[ٱ]لْمُ[q:5255[جْ]رِم[p[ُو]نَ","Жиноятчилар ёлғонга чиқараётган жаҳаннам шу бўлур.",533,27],["يَطُوفُونَ بَيْنَهَا وَبَيْنَ حَمِيمٍ ء[p[َا]نٍ","Улар жаҳаннам билан ўта қайноқ сув ўртасида айланур.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["وَلِمَنْ خَافَ مَقَامَ رَبِّه[n[ِۦ] جَ[g[نّ]َت[p[َا]نِ","Роббиси ҳузурида туришдан қўрққанлар учун икки жаннат бор.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["ذَوَات[o[َآ] أَفْن[p[َا]نٍ","Улар шох-новдалидирлар.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["فِيهِمَا عَيْنَانِ تَ[q:13176[جْ]رِي[p[َا]نِ","Икковларида оқувчи икки булоқ бор.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["فِيهِمَا مِ[f:843[ن ك]ُلِّ فَ[n[ـٰ]كِهَ[f:13177[ةٍ ز]َوْج[p[َا]نِ","Икковларида ҳам мевадан жуфт навлар бор.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["مُتَّكِــِٔينَ عَلَىٰ فُرُ[i:13178[شِۭ ب]َط[o[َا]ٓئِنُهَا مِنْ إِسْتَ[q:13179[بْ]رَ[a:13180[قٍ‌ۚ و]َجَنَى [h:13181[ٱ]لْجَ[g[نّ]َتَيْنِ د[p[َا]نٍ","Ипак астарли тўшакларга ёнбошлаган ва икки жаннат мевалари яқин бўлган ҳоллари бор.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["فِيهِ[g[نّ]َ قَ[n[ـٰ]صِر[n[َٲ]تُ [h:11365[ٱ][l[ل]طَّرْفِ لَمْ يَ[q:13182[طْ]مِثْهُ[g[نّ]َ إِ[f:13183[نس][f:13184[ٌ ق]َ[q:8394[بْ]لَهُمْ وَلَا ج[m[َا]ٓ[g[نّ]ٌ","Уларда кўзлари тийилган, аввал инс ҳам, жин ҳам тегмаганлар бор.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["كَأَ[g[نّ]َهُ[g[نّ]َ [h:13185[ٱ]لْيَاقُوتُ وَ[h:13145[ٱ]لْمَرْج[p[َا]نُ","Улар худди ёқут ва маржонга ўхшарлар.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["هَلْ جَز[o[َا]ٓءُ [h:13186[ٱ]لْإِحْسَ[n[ـٰ]نِ إِلَّا [h:13187[ٱ]لْإِحْسَ[p[ـٰ]نُ","Эҳсоннинг мукофоти, фақат эҳсондир.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["وَمِ[f:13188[ن د]ُونِهِمَا جَ[g[نّ]َت[p[َا]نِ","У икковидан пастроқда яна икки жаннат бор.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["مُ[q:13189[دْ]ه[m[َا]ٓ[g[مّ]َت[p[َا]نِ","Икковлари ям-яшилдир.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["فِيهِمَا عَيْنَانِ نَضَّاخَت[p[َا]نِ","Икковларида отилиб турувчи икки булоқ бор.",533,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",533,27],["فِيهِمَا فَ[n[ـٰ]كِهَ[a:13190[ةٌ و]َنَخْ[a:13191[لٌ و]َرُ[g[مّ][p[َا]نٌ","Икковларида мевалар, хурмо ва анорлар бор.",534,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",534,27],["فِيهِ[g[نّ]َ خَيْر[n[َٲ]تٌ حِس[p[َا]نٌ","Уларда яхши, гўзаллар бор.",534,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",534,27],["حُو[a:13192[رٌ م]َّ[q:13193[قْ]صُور[n[َٲ][f:13194[تٌ ف]ِى [h:13195[ٱ]لْخِي[p[َا]مِ","Чодирларни лозим тутган ҳурлар бор.",534,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",534,27],["لَمْ يَ[q:13182[طْ]مِثْهُ[g[نّ]َ إِ[f:13183[نس][f:13184[ٌ ق]َ[q:8394[بْ]لَهُمْ وَلَا ج[m[َا]ٓ[g[نّ]ٌ","Аввал уларга инс ҳам, жин ҳам тегмаган.",534,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",534,27],["مُتَّكِــِٔينَ عَلَىٰ رَفْرَفٍ خُضْ[a:13196[رٍ و]َعَ[q:13197[بْ]قَرِىٍّ حِس[p[َا]نٍ","Яшил болишларга ва гўзал гиламларда ёнбошлаган ҳоллари бор.",534,27],["فَبِأَىِّ ءَال[o[َا]ٓءِ رَبِّكُمَا تُكَذِّب[p[َا]نِ","Бас, Роббингизнинг қайси неъматларини ёлғон дея олурсиз?!",534,27],["تَبَ[n[ـٰ]رَكَ [h:13198[ٱ]سْمُ رَبِّكَ ذِى [h:13199[ٱ]لْجَلَ[n[ـٰ]لِ وَ[h:13151[ٱ]لْإِكْر[p[َا]مِ","Улуғлик ва икром эгаси бўлмиш Роббинг исми муборак бўлди.",534,27]]},{"n":56,"ar":"الوَاقِعَةِ","en":"Al-Waaqia","uz":"Воқеа","type":"Макка","ayahs":[["إِذَا وَقَعَتِ [h:13200[ٱ]لْوَاقِعَةُ","Воқеа воқеъ бўлганда.",534,27],["لَيْسَ لِوَ[q:13201[قْ]عَتِهَا كَاذِبَةٌ","Унинг воқеъ бўлишини ёлғон қилувчи йўқдир.",534,27],["خَافِضَ[u:13202[ةٌ ر]َّافِعَةٌ","У ҳам пастлатувчи, ҳам кўтарувчидир.",534,27],["إِذَا رُجَّتِ [h:13203[ٱ]لْأَرْضُ رَجًّا","Қачонки ер қаттиқ ларзага келганда.",534,27],["وَبُسَّتِ [h:13204[ٱ]لْجِبَالُ بَسًّا","Тоғлар майдаланиб, титилганда.",534,27],["فَكَانَتْ هَب[o[َا]ٓ[a:13205[ءً م]ُّ[i:13206[نۢب]َثًّا","Бас, улар тарқалган чанг-тўзонга айланганда.",534,27],["وَكُ[f:151[نت]ُمْ أَزْو[n[َٲ][f:13207[جًا ث]َلَ[n[ـٰ]ثَةً","Ва сизлар уч тоифа бўлгангда.",534,27],["فَأَصْحَ[n[ـٰ]بُ [h:13208[ٱ]لْمَيْمَنَةِ م[o[َآ] أَصْحَ[n[ـٰ]بُ [h:13209[ٱ]لْمَيْمَنَةِ","Ўнг тараф эгалари. Ўнг тараф эгалари недир?!",534,27],["وَأَصْحَ[n[ـٰ]بُ [h:13210[ٱ]لْمَشْــَٔمَةِ م[o[َآ] أَصْحَ[n[ـٰ]بُ [h:13211[ٱ]لْمَشْــَٔمَةِ","Ва чап тараф эгалари. Чап тараф эгалари недир?!",534,27],["وَ[h:9999[ٱ][l[ل]سَّ[n[ـٰ]بِقُونَ [h:13212[ٱ][l[ل]سَّ[n[ـٰ]بِق[p[ُو]نَ","Ва пешқадамлар, пешқадамлар.",534,27],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ [h:13213[ٱ]لْمُقَرَّب[p[ُو]نَ","Ана ўшалар, яқин бўлганлар.",534,27],["فِى جَ[g[نّ]َ[n[ـٰ]تِ [h:3680[ٱ][l[ل][g[نّ]َع[p[ِي]مِ","Сернеъмат жаннатлардалар.",534,27],["ثُلَّ[a:13214[ةٌ م]ِّنَ [h:11455[ٱ]لْأَوَّل[p[ِي]نَ","Аввалгилардан кўпгина жамоатлар.",534,27],["وَقَلِي[a:13215[لٌ م]ِّنَ [h:13216[ٱ]لْأَخِر[p[ِي]نَ","Ва охиргилардан оздирлар.",534,27],["عَلَىٰ سُرُ[a:13217[رٍ م]َّوْضُونَةٍ","Тўқима сўриларидалар.",534,27],["مُّتَّكِــِٔينَ عَلَيْهَا مُتَقَ[n[ـٰ]بِل[p[ِي]نَ","Бир-бирларига рўбарў бўлиб, ёнбошлаган ҳолларидалар.",534,27],["يَطُوفُ عَلَيْهِمْ وِلْد[n[َٲ][a:13218[نٌ م]ُّخَلَّد[p[ُو]نَ","Атрофларида мангу ёш йигитлар айланиб юрурлар.",535,27],["بِأَكْوَا[a:13219[بٍ و]َأَبَارِيقَ وَكَأْ[a:13220[سٍ م]ّ[a:11360[ِن م]َّع[p[ِي]نٍ","Оқар чашма қадаҳлар, кўзалар ва косалар билан.",535,27],["لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُ[f:13221[نز]ِف[p[ُو]نَ","Ундан бош оғриғи ҳам, маст ҳам бўлмаслар.",535,27],["وَفَ[n[ـٰ]كِهَ[a:13222[ةٍ م]ِّ[g[مّ]َا يَتَخَيَّر[p[ُو]نَ","Ва улар хоҳлаган мевалар билан.",535,27],["وَلَحْمِ طَيْ[a:13223[رٍ م]ِّ[g[مّ]َا يَشْتَه[p[ُو]نَ","Иштаҳалари тусаган қуш гўшти билан.",535,27],["وَحُورٌ ع[p[ِي]نٌ","Яна кўзи гўзал ҳурлар бор.",535,27],["كَأَمْثَ[n[ـٰ]لِ [h:13224[ٱ][l[ل]لُّؤْلُوِٕ [h:13225[ٱ]لْمَكْن[p[ُو]نِ","Мисоли яширилган дур.",535,27],["جَز[o[َا]ٓ[i:3537[ءَۢ ب]ِمَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Булар, қилган амалларнинг мукофотидур.",535,27],["لَا يَسْمَعُونَ فِيهَا لَغْ[a:13226[وًا و]َلَا تَأْثِيمًا","Улар у ерда беҳуда, гуноҳ сўзларни эшитмаслар.",535,27],["إِلَّا قِيل[f:13227[اً س]َلَ[n[ـٰ][f:13228[مًا س]َلَ[n[ـٰ]مًا","Фақат «Салом, Салом» дейилганини.",535,27],["وَأَصْحَ[n[ـٰ]بُ [h:13229[ٱ]لْيَمِينِ م[o[َآ] أَصْحَ[n[ـٰ]بُ [h:13230[ٱ]لْيَم[p[ِي]نِ","Ўнг тараф эгалари. Ўнг тараф эгалари недир!",535,27],["فِى سِ[q:10979[دْ][a:13231[رٍ م]َّخْض[p[ُو][q[د]ٍ","Улар тиконсиз сидрзорлардадир.",535,27],["وَطَلْ[a:13232[حٍ م]َّ[f:6447[نض][p[ُو][q[د]ٍ","Сермева бананзорлардадир.",535,27],["وَظِ[a:13233[لٍّ م]َّمْد[p[ُو][q[د]ٍ","Ва ёйилган соялардадир.",535,27],["وَم[o[َا]ٓ[a:13234[ءٍ م]َّسْك[p[ُو][q[ب]ٍ","Оқар сувлардадир.",535,27],["وَفَ[n[ـٰ]كِهَ[f:13235[ةٍ ك]َثِيرَةٍ","Сероб мевалардадир.",535,27],["لَّا مَ[q:13236[قْ]طُوعَ[a:13237[ةٍ و]َلَا مَمْنُوعَةٍ","Тугамайдиган ва ман қилинмайдиганлардадир.",535,27],["وَفُرُ[a:13238[شٍ م]َّرْفُوعَةٍ","Баланд-баланд кўрпачалардадир.",535,27],["إِ[g[نّ][o[َآ] أَ[f:13239[نش]َأْنَ[n[ـٰ]هُ[g[نّ]َ إِ[f:13240[نش][o[َا]ٓءً","Албатта, Биз уни дафъатан, хос қилиб, яратдик.",535,27],["فَجَعَلْنَ[n[ـٰ]هُ[g[نّ]َ أَ[q:13241[بْ]كَارًا","Бас, уларни бокиралар қилдик.",535,27],["عُرُبًا أَتْرَابًا","Тенгдош маҳбубалар қилдик.",535,27],["لِّأَصْحَ[n[ـٰ]بِ [h:13242[ٱ]لْيَم[p[ِي]نِ","Ўнг тараф эгалари учун.",535,27],["ثُلَّ[a:13214[ةٌ م]ِّنَ [h:11455[ٱ]لْأَوَّل[p[ِي]نَ","Улар аввалгилардан кўпгина жамоатлардир.",535,27],["وَثُلَّ[a:13243[ةٌ م]ِّنَ [h:13216[ٱ]لْأَخِر[p[ِي]نَ","Кейингилардан ҳам кўпгина жамоатлардир.",535,27],["وَأَصْحَ[n[ـٰ]بُ [h:13244[ٱ][l[ل]شِّمَالِ م[o[َآ] أَصْحَ[n[ـٰ]بُ [h:13245[ٱ][l[ل]شِّم[p[َا]لِ","Ва чап тараф эгалари. Чап тараф эгалари недир?!",535,27],["فِى سَمُو[a:13246[مٍ و]َحَم[p[ِي]مٍ","Улар ўт шамол ва қайноқ сувдадирлар.",535,27],["وَظِ[a:13247[لٍّ م]ّ[a:13248[ِن ي]َحْم[p[ُو]مٍ","Қоп-қора тутундан бўлган соядадирлар.",535,27],["لَّا بَارِ[a:13249[دٍ و]َلَا كَر[p[ِي]مٍ","Салқин ҳамэмас, фойдаии ҳам.",535,27],["إِ[g[نّ]َهُمْ كَانُو[s[اْ] قَ[q:3282[بْ]لَ ذ[n[َٲ]لِكَ مُتْرَف[p[ِي]نَ","Албатта улар бундан олдин ҳой-ҳавасга берилганлардан эдилар.",535,27],["وَكَانُو[s[اْ] يُصِرُّونَ عَلَى [h:13250[ٱ]لْحِ[f:13251[نث]ِ [h:13252[ٱ]لْعَظ[p[ِي]مِ","Ва мудом катта гуноҳ ишлар қилар эдилар.",535,27],["وَكَانُو[s[اْ] يَقُولُونَ أَئِذَا مِتْنَا وَكُ[g[نّ]َا تُرَا[a:9207[بًا و]َعِظَ[n[ـٰ]مًا أَءِ[g[نّ]َا لَمَ[q:7784[بْ]عُوث[p[ُو]نَ","Ва «Биз ўлиб, тупроққа ва суякка айланганимиздан кейин қайта тирилтриламизми?",535,27],["أَوَءَاب[o[َا]ٓؤُنَا [h:11331[ٱ]لْأَوَّل[p[ُو]نَ","Аввалги оталаримиз ҳам-а?!» дер эдилар.",535,27],["قُلْ إِ[g[نّ]َ [h:13253[ٱ]لْأَوَّلِينَ وَ[h:13254[ٱ]لْأَخِر[p[ِي]نَ","Айтгил: «Албатта, аввалгилар ва охиргилар.",535,27],["لَمَ[q:13255[جْ]مُوعُونَ إِلَىٰ مِيقَ[n[ـٰ]تِ يَوْ[a:9746[مٍ م]َّعْل[p[ُو]مٍ","Маълум кунга белгиланган вақтда албатта тўпланувчилар».",535,27],["ثُ[g[مّ]َ إِ[g[نّ]َكُمْ أَيُّهَا [h:13256[ٱ][l[ل]ضّ[m[َا]ٓلُّونَ [h:13257[ٱ]لْمُكَذِّب[p[ُو]نَ","Сўнгра, сиз эй адашганлар, ёлғонга чиқарувчилар!",536,27],["لَأَكِلُونَ مِ[f:13258[ن ش]َجَ[a:13259[رٍ م]ِّ[f:13260[ن ز]َقّ[p[ُو]مٍ","Албатта, заққум дарахтидан еювчисизлар.",536,27],["فَمَالِــُٔونَ مِنْهَا [h:11382[ٱ]لْبُط[p[ُو]نَ","Бас, ундан қоринларни тўлдирувчисизлар.",536,27],["فَشَ[n[ـٰ]رِبُونَ عَلَيْهِ مِنَ [h:13261[ٱ]لْحَم[p[ِي]مِ","Бас, устидан ўта қайноқ сувдан ичувчисизлар.",536,27],["فَشَ[n[ـٰ]رِبُونَ شُرْبَ [h:13262[ٱ]لْه[p[ِي]مِ","Бас, чанқоқ туядек ичувчисизлар.",536,27],["هَ[n[ـٰ]ذَا نُزُلُهُمْ يَوْمَ [h:9781[ٱ][l[ل]دّ[p[ِي]نِ","Уларнинг қиёмат кунидаги зиёфатлари мана шу!",536,27],["نَحْنُ خَلَ[q:4250[قْ]نَ[n[ـٰ]كُمْ فَلَوْلَا تُصَدِّق[p[ُو]نَ","Биз сизларни яратганимиз, ишонсаларинг-чи!",536,27],["أَفَرَءَيْت[w:9776[ُم م]َّا تُمْن[p[ُو]نَ","Ўзингиз чиқарадиган манийни ўйлаб кўринг-а!",536,27],["ءَأَ[f:716[نت]ُمْ تَخْلُقُونَهُ[o[ۥٓ] أَمْ نَحْنُ [h:13263[ٱ]لْخَ[n[ـٰ]لِق[p[ُو]نَ","Уни сизлар яратасизми ёки Биз яратувчимизми?!",536,27],["نَحْنُ قَدَّرْنَا بَيْنَكُمُ [h:13264[ٱ]لْمَوْتَ وَمَا نَحْنُ بِمَسْبُوق[p[ِي]نَ","Орангиздаги ўлимни Биз белгилаганмиз ва Биз ожиз эмасмиз.",536,27],["عَلَ[o[ىٰٓ] أ[a:13265[َن ن]ُّبَدِّلَ أَمْثَ[n[ـٰ]لَكُمْ وَنُ[f:13266[نش]ِئَكُمْ فِى مَا لَا تَعْلَم[p[ُو]نَ","Сизнинг ўрнингизга сизга ўхшашларни алмаштиришдан ва сизларни ўзингиз билмайдиган ҳолда яратишдан.",536,27],["وَلَقَ[q:341[دْ] عَلِمْتُمُ [h:13267[ٱ][l[ل][g[نّ]َشْأَةَ [h:13268[ٱ]لْأُولَىٰ فَلَوْلَا تَذَكَّر[p[ُو]نَ","Ва дарҳақиқат, аввалги яратилишини билдингиз-ку, эсласаларингиз-чи!",536,27],["أَفَرَءَيْت[w:9776[ُم م]َّا تَحْرُث[p[ُو]نَ","Ўзингиз экаётган нарсани ўйлаб кўринг-а!",536,27],["ءَأَ[f:716[نت]ُمْ تَزْرَعُونَهُ[o[ۥٓ] أَمْ نَحْنُ [h:13269[ٱ][l[ل]زّ[n[َٲ]رِع[p[ُو]نَ","Уни сиз ундирасизми ёки Биз ундирувчимизми?",536,27],["لَوْ نَش[o[َا]ٓءُ لَجَعَلْنَ[n[ـٰ]هُ حُطَ[n[ـٰ][f:13270[مًا ف]َظَلْتُمْ تَفَكَّه[p[ُو]نَ","Агар хоҳласак, Биз уни қуруқ чўпга айлантириб қўямиз. Сизлар эса надоматда ажабланиб:",536,27],["إِ[g[نّ]َا لَمُغْرَم[p[ُو]نَ","«Албатта, биз зиён кўрганлармиз.",536,27],["بَلْ نَحْنُ مَحْرُوم[p[ُو]نَ","Балки маҳрум бўлганлармиз»,.",536,27],["أَفَرَءَيْتُمُ [h:13271[ٱ]لْم[o[َا]ٓءَ [h:13272[ٱ]لَّذِى تَشْرَب[p[ُو]نَ","Ўзингиз ичадиган сувни ўйлаб кўринг-а!",536,27],["ءَأَ[f:716[نت]ُمْ أَ[f:13273[نز]َلْتُمُوهُ مِنَ [h:13274[ٱ]لْمُزْنِ أَمْ نَحْنُ [h:13275[ٱ]لْمُ[f:13276[نز]ِل[p[ُو]نَ","Уни булутлардан сиз туширасизми ёки Биз тушурувчимизми?",536,27],["لَوْ نَش[o[َا]ٓءُ جَعَلْنَ[n[ـٰ]هُ أُجَا[f:13277[جًا ف]َلَوْلَا تَشْكُر[p[ُو]نَ","Агар хоҳласак, Биз уни шўр қилиб қўямиз. Шукр қилсангиз-чи!",536,27],["أَفَرَءَيْتُمُ [h:13278[ٱ][l[ل][g[نّ]َارَ [h:114[ٱ]لَّتِى تُور[p[ُو]نَ","Ўзингиз ёқадиган оловни ўйлаб кўринг-а!",536,27],["ءَأَ[f:716[نت]ُمْ أَ[f:13279[نش]َأْتُمْ شَجَرَتَه[o[َآ] أَمْ نَحْنُ [h:13280[ٱ]لْمُ[f:13281[نش]ِــٔ[p[ُو]نَ","Унинг дарахтини сиз яратгансизми ёки Биз яратувчимизми?",536,27],["نَحْنُ جَعَلْنَ[n[ـٰ]هَا تَذْكِرَ[a:13282[ةً و]َمَتَ[n[ـٰ][u:13283[عًا ل]ِّلْمُ[q:13284[قْ]و[p[ِي]نَ","Биз уни эслатма ва йўловчилар учун манфаъат қилиб қўйдик.",536,27],["فَسَبِّحْ بِ[h:13285[ٱ]سْمِ رَبِّكَ [h:13286[ٱ]لْعَظ[p[ِي]مِ","Бас, улуғ Роббинг исмини поклаб ёд эт!",536,27],["۞ فَل[o[َآ] أُ[q:13287[قْ]سِمُ بِمَو[n[َٲ]قِعِ [h:13288[ٱ][l[ل][g[نّ]ُج[p[ُو]مِ","Юлдузларнинг манзиллари билан қасам ичаман.",536,27],["وَإِ[g[نّ]َهُ[n[ۥ] لَقَسَ[u:13289[مٌ ل]َّوْ تَعْلَمُونَ عَظ[p[ِي]مٌ","Албатта, агар билсангиз бу улуғ қасамдир.",536,27],["إِ[g[نّ]َهُ[n[ۥ] لَقُرْءَا[f:13290[نٌ ك]َر[p[ِي]مٌ","Албатта, у Қуръони каримдир.",537,27],["فِى كِتَ[n[ـٰ][a:13291[بٍ م]َّكْن[p[ُو]نٍ","У сақланган китобдадир.",537,27],["لَّا يَمَسُّهُ[o[ۥٓ] إِلَّا [h:13292[ٱ]لْمُطَهَّر[p[ُو]نَ","Уни фақат покланганларгина ушлайдир.",537,27],["تَ[f:11949[نز]ِي[a:12045[لٌ م]ّ[u:4772[ِن ر]َّبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","У оламларнинг Роббисидан туширилгандир.",537,27],["أَفَبِهَ[n[ـٰ]ذَا [h:13293[ٱ]لْحَدِيثِ أَ[f:428[نت][w:13294[ُم م]ُّ[q:13295[دْ]هِن[p[ُو]نَ","Бас, сизлар мана шу сўзга бепарволик қиласизларми?!",537,27],["وَتَ[q:11964[جْ]عَلُونَ رِزْقَكُمْ أَ[g[نّ]َكُمْ تُكَذِّب[p[ُو]نَ","Ва ёлғонга чиқаришни ризқ қилиб оласизларми?!",537,27],["فَلَوْل[o[َآ] إِذَا بَلَغَتِ [h:13296[ٱ]لْحُلْق[p[ُو]مَ","Жонингиз ҳалқумга келиб қолса-чи?!",537,27],["وَأَ[f:98[نت]ُمْ حِينَئِ[f:13297[ذٍ ت]َ[f:248[نظ]ُر[p[ُو]نَ","Ҳолбуки, ўша вақтда ўзларингиз қараб турган бўласизлар.",537,27],["وَنَحْنُ أَ[q:1355[قْ]رَبُ إِلَيْهِ مِ[f:344[نك]ُمْ وَلَ[n[ـٰ]ك[u:46[ِن ل]َّا تُ[q:8674[بْ]صِر[p[ُو]نَ","Биз эса, сиздан кўра унга яқинмиз, аммо сизлар кўрмайсизлар.",537,27],["فَلَوْل[o[َآ] إِ[f:109[ن ك]ُ[f:100[نت]ُمْ غَيْرَ مَدِين[p[ِي]نَ","Агар сиз ҳисоб бермас бўлсангиз.",537,27],["تَرْجِعُونَه[o[َآ] إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Уни ўрнига қайтаринг-чи! Агар ростгўй бўлсангиз!",537,27],["فَأَ[g[مّ][o[َآ] إِ[f:2594[ن ك]َانَ مِنَ [h:13298[ٱ]لْمُقَرَّب[p[ِي]نَ","Агар, у муқарраблардан бўлса.",537,27],["فَرَوْ[a:13299[حٌ و]َرَيْحَا[a:13300[نٌ و]َجَ[g[نّ]َتُ نَع[p[ِي]مٍ","Роҳатда, фароғатда ва сернеъмат жаннатдадир.",537,27],["وَأَ[g[مّ][o[َآ] إِ[f:2594[ن ك]َانَ مِنْ أَصْحَ[n[ـٰ]بِ [h:13301[ٱ]لْيَم[p[ِي]نِ","Агар ўнг тараф эгаларидан бўлса.",537,27],["فَسَلَ[n[ـٰ][u:13302[مٌ ل]َّكَ مِنْ أَصْحَ[n[ـٰ]بِ [h:13301[ٱ]لْيَم[p[ِي]نِ","Бас, «Сенга ўнг тараф эгаларидан Салом»дир.",537,27],["وَأَ[g[مّ][o[َآ] إِ[f:2594[ن ك]َانَ مِنَ [h:13303[ٱ]لْمُكَذِّبِينَ [h:13304[ٱ][l[ل]ضّ[m[َا]ٓلّ[p[ِي]نَ","Ва агар ёлғонга чиқарувчилардан, гумроҳлардан бўлса.",537,27],["فَنُزُ[a:13305[لٌ م]ِّنْ حَم[p[ِي]مٍ","Бас, ўта қайноқ сувдан зиёфатдир.",537,27],["وَتَصْلِيَةُ جَح[p[ِي]مٍ","Ва дўзахга киришдир.",537,27],["إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَهُوَ حَقُّ [h:13306[ٱ]لْيَق[p[ِي]نِ","Албатта, ушбуочиқ-ойдин ҳақиқатдир.",537,27],["فَسَبِّحْ بِ[h:13285[ٱ]سْمِ رَبِّكَ [h:13286[ٱ]لْعَظ[p[ِي]مِ","Бас, улуғ Роббинг исмини поклаб ёд эт!",537,27]]},{"n":57,"ar":"الحَدِيدِ","en":"Al-Hadid","uz":"Ҳадид","type":"Мадина","ayahs":[["سَبَّحَ لِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Осмонлардаги ва ердаги нарсалар Аллоҳга тасбиҳ айтди. Ва У азиз ва ҳакимдир.",537,27],["لَهُ[n[ۥ] مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ يُحْى[n[ِۦ] وَيُمِيتُ‌ۖ وَهُوَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Осмонлару ернинг мулки Уникидир. У тирилтирур ва ўлдирур ва У ҳар бир нарсага қодирдир.",537,27],["هُوَ [h:13307[ٱ]لْأَوَّلُ وَ[h:13308[ٱ]لْأَخِرُ وَ[h:13309[ٱ][l[ل]ظَّ[n[ـٰ]هِرُ وَ[h:13310[ٱ]لْبَاطِنُ‌ۖ وَهُوَ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","У аввал ва охир, ошкор ва пинҳондир. Ва У ҳар бир нарсани билувчидир.",537,27],["هُوَ [h:153[ٱ]لَّذِى خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ فِى سِتَّةِ أَيَّا[f:4739[مٍ ث]ُ[g[مّ]َ [h:156[ٱ]سْتَوَىٰ عَلَى [h:4740[ٱ]لْعَرْشِ‌ۚ يَعْلَمُ مَا يَلِجُ فِى [h:44[ٱ]لْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَ[f:10919[نز]ِلُ مِنَ [h:64[ٱ][l[ل]سَّم[o[َا]ٓءِ وَمَا يَعْرُجُ فِيهَا‌ۖ وَهُوَ مَعَكُمْ أَيْنَ مَا كُ[f:100[نت]ُمْ‌ۚ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","У осмонлару ерни олти кунда яратиб, сўнгра аршни эгаллаган зотдир. Ерга нима кирганини ҳам, ундан нима чиққанини ҳам, осмондан нима тушганини ҳам унга нима чиққанини ҳам биладир. У қаерда бўлсангиз ҳам сиз билан биргадир. Аллоҳ қилаётган амалларингизни кўриб турувчидир.",538,27],["لَّهُ[n[ۥ] مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَإِلَى [h:1148[ٱ]للَّهِ تُرْجَعُ [h:1149[ٱ]لْأُم[p[ُو]رُ","Осмонлару ернинг мулки Уникидир ва барча ишлар Аллоҳнинг Ўзигагина қайтадир.",538,27],["يُولِجُ [h:9084[ٱ]لَّيْلَ فِى [h:1829[ٱ][l[ل][g[نّ]َهَارِ وَيُولِجُ [h:9085[ٱ][l[ل][g[نّ]َهَارَ فِى [h:1831[ٱ]لَّيْلِ‌ۚ وَهُوَ عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","У кечасини кундузга киритадир, кундузни кечасига киритадир ва У кўксингиздаги нарсани ҳам яхши билувчидир.",538,27],["ءَامِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] وَأَ[f:1045[نف]ِقُو[s[اْ] مِ[g[مّ]َا جَعَلَك[w:13311[ُم م]ُّسْتَخْلَفِينَ فِيهِ‌ۖ فَ[h:2514[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مِ[f:344[نك]ُمْ وَأَ[f:2789[نف]َقُو[s[اْ] لَهُمْ أَ[q:2423[جْ][f:13312[رٌ ك]َب[p[ِي]رٌ","Аллоҳга ва Унинг Расулига иймон келтиринглар ҳамда сизларни халифа қилиб қўйган нарсалардан эҳсон қилинглар. Бас, сизлардан иймон келтирган ва эҳсон қилганларга улкан ажр бордир.",538,27],["وَمَا لَكُمْ لَا تُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ‌ۙ وَ[h:2331[ٱ][l[ل]رَّسُولُ يَ[q:2332[دْ]عُوكُمْ لِتُؤْمِنُو[s[اْ] بِرَبِّكُمْ وَقَ[q:387[دْ] أَخَذَ مِيثَ[n[ـٰ]قَكُمْ إِ[f:109[ن ك]ُ[f:100[نت][w:482[ُم م]ُّؤْمِن[p[ِي]نَ","Сизларга нима бўлдики, Аллоҳга иймон келтирмайсизлар?! Ҳолбуки, Пайғамбар сизларни Роббиингизга иймон келтиришга чақириб турибдир. У сизлардан аҳд олган эди. Агар иймон келтирувчи бўлсаларингиз.",538,27],["هُوَ [h:153[ٱ]لَّذِى يُنَزِّلُ عَلَىٰ عَ[q:7944[بْ]دِه[o[ِۦٓ] ءَايَ[n[ـٰ][i:516[تِۭ ب]َيِّنَ[n[ـٰ][u:13313[تٍ ل]ِّيُخْرِجَك[w:10845[ُم م]ِّنَ [h:1491[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ إِلَى [h:1492[ٱ][l[ل][g[نّ]ُورِ‌ۚ وَإِ[g[نّ]َ [h:1986[ٱ]للَّهَ بِكُمْ لَرَءُو[u:744[فٌ ر]َّح[p[ِي]مٌ","У зот Ўз бандасига сизларни зулматлардан нурга чиқариш учун равшан оятларни туширадир. Ва, албатта, Аллоҳ сизларга шафқатли ва раҳмлидир.",538,27],["وَمَا لَكُمْ أَلَّا تُ[f:1607[نف]ِقُو[s[اْ] فِى سَبِيلِ [h:788[ٱ]للَّهِ وَلِلَّهِ مِير[n[َٲ]ثُ [h:2459[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ لَا يَسْتَوِى مِ[f:344[نك][w:2322[ُم م]َّنْ أَ[f:8088[نف]َقَ مِ[f:1346[ن ق]َ[q:1347[بْ]لِ [h:13314[ٱ]لْفَتْحِ وَقَ[n[ـٰ]تَلَ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَعْظَمُ دَرَجَ[a:13315[ةً م]ِّنَ [h:523[ٱ]لَّذِينَ أَ[f:1538[نف]َقُو[s[اْ] م[i:1287[ِنۢ ب]َعْدُ وَقَ[n[ـٰ]تَلُو[s[اْ‌ۚ] وَكُل[a:3054[اًّ و]َعَدَ [h:3055[ٱ]للَّهُ [h:3056[ٱ]لْحُسْنَىٰ‌ۚ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ خَب[p[ِي]رٌ","Сизларга нима бўлдики, Аллоҳнинг йўлида эҳсон қилмайсизлар?! Ҳолбуки, осмонлару ернинг мероси Аллоҳникидир. Сизлардан ҳеч ким фатҳдан илгари эҳсон қилганларга ва урушда қатнашганларга баробар бўла олмайдир. Уларнинг даражалари фатҳдан сўнг эҳсон қилганлардан ва урушда қатнашганлардан кўра улуғдир. Аллоҳ барчага яхшиликни ваъда қилгандир. Ва Аллоҳ нима қилаётганларингиздан хабардордир.",538,27],["مَّ[f:1375[ن ذ]َا [h:1376[ٱ]لَّذِى يُ[q:1377[قْ]رِضُ [h:1378[ٱ]للَّهَ قَرْضًا حَسَ[f:1379[نًا ف]َيُضَ[n[ـٰ]عِفَهُ[n[ۥ] لَهُ[n[ۥ] وَلَهُ[o[ۥٓ] أَ[q:2423[جْ][f:13316[رٌ ك]َر[p[ِي]مٌ","Аллоҳга яхши қарз берадиган киши борми?! Бас, У зот унга бир неча марта кўпайтириб қайтарадир ва унга карамли ажр бордир.",538,27],["يَوْمَ تَرَى [h:13317[ٱ]لْمُؤْمِنِينَ وَ[h:5718[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ يَسْعَىٰ نُورُه[c:13318[ُم ب]َيْنَ أَيْدِيهِمْ وَبِأَيْمَ[n[ـٰ]نِه[c:13319[ِم ب]ُشْرَ[n[ٮٰ]كُمُ [h:13320[ٱ]لْيَوْمَ جَ[g[نّ]َ[n[ـٰ][f:1786[تٌ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۚ ذ[n[َٲ]لِكَ هُوَ [h:5722[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Мўмин ва мўминаларни уларнинг олдиларида ва ўнг тарафларида нурлари ҳаракат қилаётган ҳолда кўрган кунингда, Сизларга бугунги куннинг хушхабари дарахтлари остидан сувлари оқиб турган жаннатлардир. У жойда абадий қолажаксиз. Бу эса, айнан улкан ютуқдир,.",539,27],["يَوْمَ يَقُولُ [h:5376[ٱ]لْمُنَ[n[ـٰ]فِقُونَ وَ[h:5691[ٱ]لْمُنَ[n[ـٰ]فِقَ[n[ـٰ]تُ لِلَّذِينَ ءَامَنُو[s[اْ] [h:13321[ٱ][f:13322[نظ]ُرُونَا نَ[q:13323[قْ]تَبِسْ م[a:13324[ِن ن]ُّورِكُمْ قِيلَ [h:13325[ٱ]رْجِعُو[s[اْ] وَر[o[َا]ٓءَكُمْ فَ[h:13326[ٱ]لْتَمِسُو[s[اْ] نُو[f:13327[رًا ف]َضُرِبَ بَيْنَه[c:13328[ُم ب]ِسُو[u:13329[رٍ ل]َّهُ[n[ۥ] بَا[i:13330[بُۢ ب]َاطِنُهُ[n[ۥ] فِيهِ [h:13331[ٱ][l[ل]رَّحْمَةُ وَظَ[n[ـٰ]هِرُهُ[n[ۥ] مِ[f:13332[ن ق]ِبَلِهِ [h:13333[ٱ]لْعَذ[p[َا][q[ب]ُ","Мунофиқ ва мунофиқалар иймонлиларга: «Тўхтаб туринглар, биз ҳам нурингиздан бир оз олайлик», деган ва уларга: «Ортингизга қайтинг ҳамда нур қидиринг», дейилган кунда. Бас, уларнинг орасига эшиги бор қўрғон уриладир. Унинг ичида раҳмат, ташқарисида - олдида азобдир.",539,27],["يُنَادُونَهُمْ أَلَمْ نَك[a:3220[ُن م]َّعَكُمْ‌ۖ قَالُو[s[اْ] بَلَىٰ وَلَ[n[ـٰ]كِ[g[نّ]َكُمْ فَتَ[f:13334[نت]ُمْ أَ[f:221[نف]ُسَكُمْ وَتَرَبَّصْتُمْ وَ[h:13335[ٱ]رْتَ[q:13335[بْ]تُمْ وَغَرَّتْكُمُ [h:13336[ٱ]لْأَمَانِىُّ حَتَّىٰ ج[o[َا]ٓءَ أَمْرُ [h:2832[ٱ]للَّهِ وَغَرَّك[c:13337[ُم ب]ِ[h:32[ٱ]للَّهِ [h:10615[ٱ]لْغَر[p[ُو]رُ","Уларга: «Биз сиз билан бирга эмасмидик?!» деб нидо қилурлар. Улар: «Худди шундай. Лекин сизлар Аллоҳнинг амри келгунча ўзингизни ўзингиз фитнага дучор қилдингиз, кўз тикиб кутдингиз, шубҳа қилдингиз ва сизларни хом-хаёллар ғурурга кетказди. Сизларни Аллоҳ ҳақида алдамчи алдаб қўйди.",539,27],["فَ[h:9999[ٱ]لْيَوْمَ لَا يُؤْخَذُ مِ[f:344[نك]ُمْ فِ[q:959[دْ]يَ[a:13338[ةٌ و]َلَا مِنَ [h:523[ٱ]لَّذِينَ كَفَرُو[s[اْ‌ۚ] مَأْوَ[n[ٮٰ]كُمُ [h:13339[ٱ][l[ل][g[نّ]َارُ‌ۖ هِىَ مَوْلَ[n[ـٰ]كُمْ‌ۖ وَبِئْسَ [h:665[ٱ]لْمَص[p[ِي]رُ","Бугун сизлардан ҳам, куфр келтирганлардан ҳам тўлов олинмас. Жойларингиз жаҳаннамда, у сизнинг эгангиздир. Қандай ҳам ёмон борар жой!» - дерлар.",539,27],["۞ أَلَمْ يَأْنِ لِلَّذِينَ ءَامَن[o[ُوٓ][s[اْ] أَ[f:13340[ن ت]َخْشَعَ قُلُوبُهُمْ لِذِكْرِ [h:13341[ٱ]للَّهِ وَمَا نَزَلَ مِنَ [h:1173[ٱ]لْحَقِّ وَلَا يَكُونُو[s[اْ] كَ[h:2146[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ مِ[f:128[ن ق]َ[q:129[بْ]لُ فَطَالَ عَلَيْهِمُ [h:13342[ٱ]لْأَمَدُ فَقَسَتْ قُلُوبُهُمْ‌ۖ وَكَثِي[a:3689[رٌ م]ِّنْهُمْ فَ[n[ـٰ]سِق[p[ُو]نَ","Иймон келтирганлар учун Аллоҳнинг зикрига ва нозил бўлган ҳаққа қалблари юмшаш, айни чоқда, олдин китоб берилган, сўнг муддат ўтиши билан қалблари қотиб қолган, кўплари фосиқ бўлганларга ўхшамаслик вақти келмадими?!",539,27],["ٱعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ يُحْىِ [h:10518[ٱ]لْأَرْضَ بَعْدَ مَوْتِهَا‌ۚ قَ[q:298[دْ] بَيَّ[g[نّ]َا لَكُمُ [h:1221[ٱ]لْأَيَ[n[ـٰ]تِ لَعَلَّكُمْ تَعْقِل[p[ُو]نَ","Билингларки, албатта Аллоҳ ўлик ерни тирилтирур. Дарҳақиқат, сизларга оятларни баён қилдик, шоядки ақл юритсангизлар.",539,27],["إِ[g[نّ]َ [h:13343[ٱ]لْمُصَّدِّقِينَ وَ[h:13344[ٱ]لْمُصَّدِّقَ[n[ـٰ]تِ وَأَ[q:13345[قْ]رَضُو[s[اْ] [h:13346[ٱ]للَّهَ قَرْضًا حَسَ[a:13347[نًا ي]ُضَ[n[ـٰ]عَفُ لَهُمْ وَلَهُمْ أَ[q:2423[جْ][f:13316[رٌ ك]َر[p[ِي]مٌ","Албатта, садақа қилувчи эркагу аёл ҳамда Аллоҳга қарзи ҳасана берувчиларга кўпайтириб берилур. Уларга карамли ажр ҳам бор.",539,27],["وَ[h:9999[ٱ]لَّذِينَ ءَامَنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرُسُلِه[o[ِۦٓ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:13348[ٱ][l[ل]صِّدِّيقُونَ‌ۖ وَ[h:13349[ٱ][l[ل]شُّهَد[o[َا]ٓءُ عِ[f:264[ند]َ رَبِّهِمْ لَهُمْ أَ[q:331[جْ]رُهُمْ وَنُورُهُمْ‌ۖ وَ[h:37[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَكَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِن[o[َآ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:3415[ٱ]لْجَح[p[ِي]مِ","Аллоҳга ва Унинг Пайғамбарларига иймон келтирганлар, ана ўшалар, сиддиқлардир. Ва Роббилари ҳузуридаги шоҳидлардир. Уларнинг ажрлари ва нурлари бор. Куфр келтирганлар ва оятларимизни ёлғонга чиқарганлар, ана ўшалар, дўзах эгаларидир.",540,27],["ٱعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َمَا [h:13350[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْيَا لَعِ[a:4002[بٌ و]َلَهْ[a:13351[وٌ و]َزِينَ[a:13352[ةٌ و]َتَفَاخُ[i:13353[رُۢ ب]َيْنَكُمْ وَتَكَاثُ[f:13354[رٌ ف]ِى [h:7821[ٱ]لْأَمْو[n[َٲ]لِ وَ[h:7822[ٱ]لْأَوْلَ[n[ـٰ]دِ‌ۖ كَمَثَلِ غَيْثٍ أَعْجَبَ [h:13355[ٱ]لْكُفَّارَ نَبَاتُهُ[n[ۥ] ثُ[g[مّ]َ يَهِيجُ فَتَرَ[n[ٮٰ]هُ مُصْفَر[f:11672[ًّا ث]ُ[g[مّ]َ يَكُونُ حُطَ[n[ـٰ][a:13356[مًا‌ۖ و]َفِى [h:1108[ٱ]لْأَخِرَةِ عَذَا[f:1727[بٌ ش]َدِي[a:13357[دٌ و]َمَغْفِرَ[a:13358[ةٌ م]ِّنَ [h:321[ٱ]للَّهِ وَرِضْو[n[َٲ][a:13359[نٌ‌ۚ و]َمَا [h:2482[ٱ]لْحَيَ[s[و][n[ٲ]ةُ [h:1156[ٱ][l[ل]دُّنْي[o[َآ] إِلَّا مَتَ[n[ـٰ]عُ [h:2483[ٱ]لْغُر[p[ُو]رِ","Билингки, албатта, бу дунё ҳаёти ўйин, кўнгил эрмаги ва зеб-зийнатдан, ўзаро фахрланишдан, мол-мулкни ва бола-чақани кўпайтиришдан иборатдир. Худди ўсимлиги деҳқонларни ажаблантирган ёмғирга ўхшайдир. Кейинроқ бу ўсимликлар қурийдир ва сарғайганини кўрасан. У сўнгра хас-чўпга айланиб кетадир. Охиратда эса қаттиқ азоб бор, Аллоҳдан мағфират ва розилик бор. Бу дунё ҳаёти ғурурга кетгазувчи матодан ўзга ҳеч нарса эмас.",540,27],["سَابِق[o[ُوٓ][s[اْ] إِلَىٰ مَغْفِرَ[a:2239[ةٍ م]ّ[u:243[ِن ر]َّبِّكُمْ وَجَ[g[نّ]َةٍ عَرْضُهَا كَعَرْضِ [h:13360[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:177[ٱ]لْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرُسُلِه[n[ِۦ]‌ۚ ذ[n[َٲ]لِكَ فَضْلُ [h:337[ٱ]للَّهِ يُؤْتِيهِ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَ[h:72[ٱ]للَّهُ ذُو [h:550[ٱ]لْفَضْلِ [h:551[ٱ]لْعَظ[p[ِي]مِ","Роббингизнинг мағфиратига ва Аллоҳга ҳамда Унинг Пайғамбарларига иймон келтирганлар учун тайёрланган, кенглиги осмону ернинг кенглигича бўлган жаннатга мусобақалашинг. Ана ўша Аллоҳнинг фазли. Кимга хоҳласа беради, Аллоҳ улуғ фазл эгасидир.",540,27],["م[o[َآ] أَصَابَ م[a:12140[ِن م]ُّصِيبَ[f:13361[ةٍ ف]ِى [h:44[ٱ]لْأَرْضِ وَلَا ف[o[ِىٓ] أَ[f:1329[نف]ُسِكُمْ إِلَّا فِى كِتَ[n[ـٰ][a:13362[بٍ م]ِّ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:13363[َن ن]َّ[q:13364[بْ]رَأَه[o[َآ‌ۚ] إِ[g[نّ]َ ذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ يَس[p[ِي]رٌ","Бирор мусибатни пайдо қилмасамиздан олдин у Китобда битилган бўлур, акс ҳолда ер юзида ва ўз шахсларингизда сизга бирор мусибат етмас. Албатта, бу иш Аллоҳ учун осондир.",540,27],["لِّكَيْلَا تَأْسَوْ[s[اْ] عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُو[s[اْ] بِم[o[َآ] ءَاتَ[n[ـٰ]كُمْ‌ۗ وَ[h:72[ٱ]للَّهُ لَا يُحِبُّ كُلَّ مُخْتَا[f:10576[لٍ ف]َخ[p[ُو]رٍ","Токи, кетган нарсага қайғуриб, келган нарсадан хурсанд бўлмаслигингиз учун, Аллоҳ барча димоғдор ва мақтанчоқларни суймайдир.",540,27],["ٱلَّذِينَ يَ[q:2456[بْ]خَلُونَ وَيَأْمُرُونَ [h:2780[ٱ][l[ل][g[نّ]َاسَ بِ[h:2781[ٱ]لْبُخْلِ‌ۗ وَم[a:3640[َن ي]َتَوَلَّ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ هُوَ [h:6121[ٱ]لْغَنِىُّ [h:9093[ٱ]لْحَم[p[ِي][q[د]ُ","Улар бахилдирлар ва кишиларни ҳам бахилликка буюрадилар. Ким юз ўгирса, бас, Аллоҳ беҳожат ва мақталган зотдир.",540,27],["لَقَ[q:2389[دْ] أَرْسَلْنَا رُسُلَنَا بِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ وَأَ[f:271[نز]َلْنَا مَعَهُمُ [h:1164[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:4528[ٱ]لْمِيزَانَ لِيَقُومَ [h:13365[ٱ][l[ل][g[نّ]َاسُ بِ[h:1800[ٱ]لْقِسْطِ‌ۖ وَأَ[f:271[نز]َلْنَا [h:13366[ٱ]لْحَدِيدَ فِيهِ بَأْ[f:13367[سٌ ش]َدِي[a:13368[دٌ و]َمَنَ[n[ـٰ]فِعُ لِل[g[نّ]َاسِ وَلِيَعْلَمَ [h:2269[ٱ]للَّهُ م[a:9042[َن ي]َ[f:9043[نص]ُرُهُ[n[ۥ] وَرُسُلَهُ[n[ۥ] بِ[h:13[ٱ]لْغَيْبِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ قَوِىٌّ عَز[p[ِي]زٌ","Дарҳақиқат, Биз Пайғамбарларимизни равшанлар ила юбордик ва улар ила китоб, ҳамда одамлар адолатда туришлари учун мезон туширдик. Ва темирни туширдик - унда катта куч-қувват ва одамлар учун манфаатлар бор. Аллоҳ ким Ўзига ва Пайғамбарларига ғойибона ёрдам бераётганини билиши учун. Албатта, Аллоҳ кучли ва азиздир.",541,27],["وَلَقَ[q:341[دْ] أَرْسَلْنَا نُو[a:13369[حًا و]َإِ[q:10311[بْ]ر[n[َٲ]هِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا [h:13370[ٱ][l[ل][g[نّ]ُبُوَّةَ وَ[h:10342[ٱ]لْكِتَ[n[ـٰ]بَ‌ۖ فَمِنْه[w:13371[ُم م]ُّهْتَ[a:13372[دٍ‌ۖ و]َكَثِي[a:3689[رٌ م]ِّنْهُمْ فَ[n[ـٰ]سِق[p[ُو]نَ","Дарҳақиқат, Нуҳ ва Иброҳимни Пайғамбар қилиб юбордик ҳамда Пайғамбарликни ва китобни икковларининг зурриётига хос қилдик. Улар орасида ҳидоят топганлар бор, лекин уларнинг кўплари фосиқлардир.",541,27],["ثُ[g[مّ]َ قَفَّيْنَا عَلَ[o[ىٰٓ] ءَاثَ[n[ـٰ]رِه[c:13373[ِم ب]ِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى [h:3589[ٱ][q:3590[بْ]نِ مَرْيَمَ وَءَاتَيْنَ[n[ـٰ]هُ [h:3591[ٱ]لْإِ[f:3592[نج]ِيلَ وَجَعَلْنَا فِى قُلُوبِ [h:2312[ٱ]لَّذِينَ [h:5878[ٱ]تَّبَعُوهُ رَأْفَ[a:13374[ةً و]َرَحْمَ[a:13375[ةً و]َرَهْبَانِيَّةً [h:13376[ٱ][q:13377[بْ]تَدَعُوهَا مَا كَتَ[q:13378[بْ]نَ[n[ـٰ]هَا عَلَيْهِمْ إِلَّا [h:1610[ٱ][q:1130[بْ]تِغ[o[َا]ٓءَ رِضْو[n[َٲ]نِ [h:13379[ٱ]للَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا‌ۖ فَـَٔـاتَيْنَا [h:13380[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مِنْهُمْ أَ[q:7573[جْ]رَهُمْ‌ۖ وَكَثِي[a:3689[رٌ م]ِّنْهُمْ فَ[n[ـٰ]سِق[p[ُو]نَ","Сўнгра уларнинг ортидан Пайғамбарларимизни кетма-кет юбордик ва Исйо ибн Марямни ҳам ортларидан юбордик ҳамда унга Инжилни бердик. Унга эргашганларнинг қалбларига меҳрибонлик ва раҳмдилликни солдик. Роҳибликни ўзлари чиқариб олдилар, Биз буни уларга фарз қилмаган эдик, фақат ўзлари Аллоҳнинг розилигини тилаб қилдилар, лекин ҳақиқий риоясини қила олмадилар. Бас, улардан иймон келтирганларига ажрларини бердик, лекин уларнинг кўпи фосиқлардир.",541,27],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:1643[ٱ]تَّقُو[s[اْ] [h:1644[ٱ]للَّهَ وَءَامِنُو[s[اْ] بِرَسُولِه[n[ِۦ] يُؤْتِكُمْ كِفْلَيْنِ م[u:7986[ِن ر]َّحْمَتِه[n[ِۦ] وَيَ[q:9574[جْ]عَل لَّكُمْ نُو[f:13381[رًا ت]َمْشُونَ بِه[n[ِۦ] وَيَغْفِرْ لَكُمْ‌ۚ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Эй иймон келтирганлар! Аллоҳга тақво қилинглар ва Унинг Пайғамбарига иймон келтиринглар. У зот Ўз раҳматидан сизларга икки ҳисса берадир ва сизларнинг юришингизга нур берадир ҳамда сизларни мағфират қиладир. Аллоҳ кечирувчи, раҳмли зотдир.",541,27],["لِّئَلَّا يَعْلَمَ أَهْلُ [h:2159[ٱ]لْكِتَ[n[ـٰ]بِ أَلَّا يَ[q:1555[قْ]دِرُونَ عَلَىٰ ش[a:13382[َىْءٍ م]ِّ[f:6655[ن ف]َضْلِ [h:6656[ٱ]للَّهِ‌ۙ وَأَ[g[نّ]َ [h:13383[ٱ]لْفَضْلَ بِيَدِ [h:2027[ٱ]للَّهِ يُؤْتِيهِ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَ[h:72[ٱ]للَّهُ ذُو [h:550[ٱ]لْفَضْلِ [h:551[ٱ]لْعَظ[p[ِي]مِ","Токи китоб аҳллари Аллоҳнинг фазлидан ҳеч нарсага қодир эмасликларини, фазл Аллоҳнинг қўлида бўлиб, хоҳлаган кишисига беришини билсинлар. Аллоҳ улуғ фазл эгасидир.",541,27]]},{"n":58,"ar":"المُجَادلَةِ","en":"Al-Mujaadila","uz":"Мужодала","type":"Мадина","ayahs":[["قَ[q:298[دْ] سَمِعَ [h:2460[ٱ]للَّهُ قَوْلَ [h:13384[ٱ]لَّتِى تُجَ[n[ـٰ]دِلُكَ فِى زَوْجِهَا وَتَشْتَك[o[ِىٓ] إِلَى [h:1637[ٱ]للَّهِ وَ[h:72[ٱ]للَّهُ يَسْمَعُ تَحَاوُرَكُم[o[َآ‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ سَمِي[i:9086[عُۢ ب]َص[p[ِي]رٌ","Албатта, Аллоҳ Сен билан ўз эри ҳақида тортишаётган ва Аллоҳга шикоят қилаётган нинг сўзини эшитди. Ҳа, Аллоҳ икковингизнинг гаплашувингизни эшитмоқда. Албатта, Аллоҳ эшитувчи ва кўрувчидир.",542,28],["ٱلَّذِينَ يُظَ[n[ـٰ]هِرُونَ مِ[f:344[نك][w:431[ُم م]ّ[a:1265[ِن ن]ِّس[o[َا]ٓئِه[w:13385[ِم م]َّا هُ[g[نّ]َ أُ[g[مّ]َهَ[n[ـٰ]تِهِمْ‌ۖ إِنْ أُ[g[مّ]َهَ[n[ـٰ]تُهُمْ إِلَّا [h:13386[ٱ]لَّ[o[ــٰٓ]ــِٔى وَلَ[q:13387[دْ]نَهُمْ‌ۚ وَإِ[g[نّ]َهُمْ لَيَقُولُونَ مُ[f:13388[نك]َ[a:13389[رًا م]ِّنَ [h:3107[ٱ]لْقَوْلِ وَزُو[a:13390[رًا‌ۚ و]َإِ[g[نّ]َ [h:1986[ٱ]للَّهَ لَعَفُوٌّ غَف[p[ُو]رٌ","Сизлардан ўз хотинларидан зиҳор қиладиганлар, улар оналари эмас. Туққан оналаридан ўзга ҳеч ким уларга она эмаслар. Ва, албатта, улар инкор қилинган ва ғирт ёлғон сўзларни айтарлар. Ва, албатта, Аллоҳ кечирувчи ва мағфират қилувчидир.",542,28],["وَ[h:9999[ٱ]لَّذِينَ يُظَ[n[ـٰ]هِرُونَ م[a:1265[ِن ن]ِّس[o[َا]ٓئِهِمْ ثُ[g[مّ]َ يَعُودُونَ لِمَا قَالُو[s[اْ] فَتَحْرِيرُ رَقَبَ[a:13391[ةٍ م]ِّ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:13392[َن ي]َتَم[m[َا]ٓسَّا‌ۚ ذ[n[َٲ]لِكُمْ تُوعَظُونَ بِه[n[ِۦ]‌ۚ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ خَب[p[ِي]رٌ","Хотинларидан зиҳор қилганлар ўз айтганларидан қайтсалар, қўшилмасларидан аввал бир қул озод қилсинлар. Бу ваъзланишингиз учундир. Аллоҳ қилаётган ишларингиздан хабардордир.",542,28],["فَم[u:1066[َن ل]َّمْ يَجِ[q:1067[دْ] فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:13392[َن ي]َتَم[m[َا]ٓسَّا‌ۖ فَم[u:1066[َن ل]َّمْ يَسْتَطِعْ فَإِ[q:13393[طْ]عَامُ سِتِّينَ مِسْكِي[f:13394[نًا‌ۚ ذ][n[َٲ]لِكَ لِتُؤْمِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ]‌ۚ وَتِلْكَ حُدُودُ [h:1000[ٱ]للَّهِ‌ۗ وَلِلْكَ[n[ـٰ]فِرِينَ عَذَابٌ أَل[p[ِي]مٌ","Ким топмаса, бас қўшилмасдан аввал икки ой кетма-кет рўза тутсин. Ким қодир бўлмаса, олтмиш мискинни тўйғазсин. Бу Аллоҳга ва Унинг Расулига иймон келтиришингиз учун. Ва булар Аллоҳнинг чегараларидир. Ва кофирларга аламли азоб бор.",542,28],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يُح[m[َا]ٓدُّونَ [h:13395[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] كُبِتُو[s[اْ] كَمَا كُبِتَ [h:13396[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ‌ۚ وَقَ[q:387[دْ] أَ[f:515[نز]َلْن[o[َآ] ءَايَ[n[ـٰ][i:516[تِۭ ب]َيِّنَ[n[ـٰ][a:13397[تٍ‌ۚ و]َلِلْكَ[n[ـٰ]فِرِينَ عَذَا[a:478[بٌ م]ُّه[p[ِي]نٌ","Албатта, Аллоҳга ва Унинг Пайғамбарига душманлик қиладиганлар, улардан аввалгилар хор бўлганидек, хор бўлурлар. Ҳолбуки батаҳқиқ Биз очиқ-ойдин оятларни тушириб қўйганмиз. Ва кофирларга хорловчи азоб бор.",542,28],["يَوْمَ يَ[q:4022[بْ]عَثُهُمُ [h:4023[ٱ]للَّهُ جَمِي[f:13398[عًا ف]َيُنَبِّئُه[c:4323[ُم ب]ِمَا عَمِل[o[ُوٓ[s[اْ]‌ۚ] أَحْصَ[n[ـٰ]هُ [h:13399[ٱ]للَّهُ وَنَسُوهُ‌ۚ وَ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:3903[َىْءٍ ش]َه[p[ِي][q[د]ٌ","Аллоҳ барчаларини қайта тирилтирадиган кунда, уларга қилган ишларининг хабарини берур. Аллоҳ ҳисоблаб турган, улар эса унутганлар. Ҳолбуки Аллоҳ ҳар бир нарсага шоҳиддир.",542,28],["أَلَمْ تَرَ أَ[g[نّ]َ [h:394[ٱ]للَّهَ يَعْلَمُ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۖ مَا يَكُونُ م[a:13400[ِن ن]َّ[q:7779[جْ]وَىٰ ثَلَ[n[ـٰ]ثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَل[o[َآ] أَ[q:314[دْ]نَىٰ مِ[f:2624[ن ذ][n[َٲ]لِكَ وَل[o[َآ] أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُو[s[اْ‌ۖ] ثُ[g[مّ]َ يُنَبِّئُه[c:4559[ُم ب]ِمَا عَمِلُو[s[اْ] يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","Албатта, Аллоҳ осмонлару ердаги барча нарсаларни билишини англамадингми? Агар учтанинг сирли сўзлашуви бўлса, албатта, У зот тўртинчидир. Бешта бўлсалар, У зот олтинчидир, бундан оз бўлса ҳам, кўп бўлса ҳам ва қаерда бўлсалар ҳам, албатта, Аллоҳ улар биландир. Сўнг қиёмат кунида уларга қилган ишларидан хабар берадир. Албатта, Аллоҳ ҳар бир нарсани билувчидир.",543,28],["أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ نُهُو[s[اْ] عَنِ [h:13401[ٱ][l[ل][g[نّ]َ[q:8519[جْ]وَىٰ ثُ[g[مّ]َ يَعُودُونَ لِمَا نُهُو[s[اْ] عَنْهُ وَيَتَنَ[n[ـٰ]جَوْنَ بِ[h:434[ٱ]لْإِثْمِ وَ[h:435[ٱ]لْعُ[q:435[دْ]و[n[َٲ]نِ وَمَعْصِيَتِ [h:13402[ٱ][l[ل]رَّسُولِ وَإِذَا ج[o[َا]ٓءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ [h:1707[ٱ]للَّهُ وَيَقُولُونَ ف[o[ِىٓ] أَ[f:568[نف]ُسِهِمْ لَوْلَا يُعَذِّبُنَا [h:13403[ٱ]للَّهُ بِمَا نَقُولُ‌ۚ حَسْبُهُمْ جَهَ[g[نّ]َمُ يَصْلَوْنَهَا‌ۖ فَبِئْسَ [h:13404[ٱ]لْمَص[p[ِي]رُ","Сирли сўзлашувдан қайтарилганларни кўрмадингми?! Ман этилган ишга яна қайтурлар, гуноҳ ва душманлик-ла ва Пайғамбарга осий бўлиб, сирли сўзлашурлар. Ва ҳузурингга келсалар, сен билан Аллоҳ ўргатмаган тарзда сўрашурлар. Ва ичларида, шу гапимиз учун Аллоҳ бизни азобламаса эди, дерлар. Уларга жаҳаннам кифоядир, унга кирурлар. У қандоқ ҳам ёмон жой!",543,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا تَنَ[n[ـٰ]جَيْتُمْ فَلَا تَتَنَ[n[ـٰ]جَوْ[s[اْ] بِ[h:434[ٱ]لْإِثْمِ وَ[h:435[ٱ]لْعُ[q:435[دْ]و[n[َٲ]نِ وَمَعْصِيَتِ [h:13402[ٱ][l[ل]رَّسُولِ وَتَنَ[n[ـٰ]جَوْ[s[اْ] بِ[h:219[ٱ]لْبِرِّ وَ[h:3365[ٱ][l[ل]تَّ[q:3365[قْ]وَىٰ‌ۖ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ [h:2537[ٱ]لَّذ[o[ِىٓ] إِلَيْهِ تُحْشَر[p[ُو]نَ","Эй иймон келтирганлар! Қачон сирли суҳбат қилсангиз, гуноҳ, душманлик ва Пайғамбарга маъсиятга сирли суҳбат қилмангиз. Яхшилик ва тақвога сирли суҳбат қилингиз. Ҳузурига тўпланиб борадиганингиз Аллоҳга тақво қилингиз.",543,28],["إِ[g[نّ]َمَا [h:13405[ٱ][l[ل][g[نّ]َ[q:8519[جْ]وَىٰ مِنَ [h:1870[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ لِيَحْزُنَ [h:13406[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَلَيْسَ بِض[m[َا]ٓرِّهِمْ شَيْــًٔا إِلَّا بِإِذْنِ [h:509[ٱ]للَّهِ‌ۚ وَعَلَى [h:2207[ٱ]للَّهِ فَلْيَتَوَكَّلِ [h:2208[ٱ]لْمُؤْمِن[p[ُو]نَ","Албатта, иймонлиларни ранжитиш учун қилинган сирли суҳбат шайтондандур, Аллоҳнинг изни билан қилинган сирли суҳбатгина уларга ҳеч зарар етказмас. Мўминлар Аллоҳнинг Ўзига таваккал қилсинлар.",543,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا قِيلَ لَكُمْ تَفَسَّحُو[s[اْ] فِى [h:13407[ٱ]لْمَجَ[n[ـٰ]لِسِ فَ[h:13408[ٱ]فْسَحُو[s[اْ] يَفْسَحِ [h:13409[ٱ]للَّهُ لَكُمْ‌ۖ وَإِذَا قِيلَ [h:13410[ٱ][f:13411[نش]ُزُو[s[اْ] فَ[h:13412[ٱ][f:13412[نش]ُزُو[s[اْ] يَرْفَعِ [h:13413[ٱ]للَّهُ [h:2273[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مِ[f:344[نك]ُمْ وَ[h:37[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:7379[ٱ]لْعِلْمَ دَرَجَ[n[ـٰ][a:13414[تٍ‌ۚ و]َ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ خَب[p[ِي]رٌ","Эй иймон келтирганлар! Агар сизларга мажлисларда силжиброқ ўтиринг, дейилса, бас, силжинг, агар туринг дейилса, туринг. Аллоҳ сизлардан иймон келтирганларни ва илмга берилганларнинг даражаларини кўтарур. Аллоҳ нима қилаётганингиздан хабардордир.",543,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا نَ[n[ـٰ]جَيْتُمُ [h:13415[ٱ][l[ل]رَّسُولَ فَقَدِّمُو[s[اْ] بَيْنَ يَدَىْ نَ[q:13416[جْ]وَ[n[ٮٰ]كُمْ صَدَقَ[f:13417[ةً‌ۚ ذ][n[َٲ]لِكَ خَيْ[u:263[رٌ ل]َّكُمْ وَأَ[q:1307[طْ]هَرُ‌ۚ فَإ[u:110[ِن ل]َّمْ تَجِدُو[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Эй иймон келтирганлар! Агар Пайғамбар билан сирли суҳбат қилмоқчи бўлсангиз, сирли суҳбатингиздан аввал садақа беринг. Шундоқ қилмоғингиз ўзингиз учун яхшироқдир ва покроқдир. Агар топмасангиз, албатта Аллоҳ кечирувчи ва раҳмдилдир.",544,28],["ءَأَشْفَ[q:13418[قْ]تُمْ أَ[f:13419[ن ت]ُقَدِّمُو[s[اْ] بَيْنَ يَدَىْ نَ[q:13416[جْ]وَ[n[ٮٰ]كُمْ صَدَقَ[n[ـٰ][f:13420[تٍ‌ۚ ف]َإِذْ لَمْ تَفْعَلُو[s[اْ] وَتَابَ [h:13421[ٱ]للَّهُ عَلَيْكُمْ فَأَقِيمُو[s[اْ] [h:3095[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتُو[s[اْ] [h:215[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَأَطِيعُو[s[اْ] [h:2238[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ]‌ۚ وَ[h:72[ٱ]للَّهُ خَبِي[i:2335[رُۢ ب]ِمَا تَعْمَل[p[ُو]نَ","Сизларга сирли суҳбатингиздан аввал садақа бериш оғир келдими. Агар бажармасангиз, Аллоҳ авф қилди. Бас, намоз ўқинглар ва закот беринглар. Ва Аллоҳга ва Унинг Пайғамбарига итоат қилинглар. Аллоҳ қилаётган ишларингиздан хабардордир.",544,28],["۞ أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ تَوَلَّوْ[s[اْ] قَوْمًا غَضِبَ [h:13422[ٱ]للَّهُ عَلَيْه[w:3946[ِم م]َّا ه[w:5658[ُم م]ِّ[f:344[نك]ُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى [h:13423[ٱ]لْكَذِبِ وَهُمْ يَعْلَم[p[ُو]نَ","Аллоҳнинг ғазабига дучор бўлган қавмни дўст тутганларни кўрмайсанми? Улар сизлардан ҳам эмас, улардан ҳам эмас. Билиб туриб, ёлғонга қасам ичурлар.",544,28],["أَعَدَّ [h:5775[ٱ]للَّهُ لَهُمْ عَذَا[f:1966[بًا ش]َدِيدًا‌ۖ إِ[g[نّ]َهُمْ س[o[َا]ٓءَ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Аллоҳ улар учун шиддатли азобни тайёрлаган. Уларнинг қилаётган ишлари нақадар ёмон!",544,28],["ٱتَّخَذ[o[ُوٓ][s[اْ] أَيْمَ[n[ـٰ]نَهُمْ جُ[g[نّ]َ[f:13424[ةً ف]َصَدُّو[s[اْ] عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ فَلَهُمْ عَذَا[a:478[بٌ م]ُّه[p[ِي]نٌ","Қасамларини ўзлари учун тўсиқ қилиб олдилар. Бас, Аллоҳнинг йўлидан тўсдилар. Улар хорловчи азоб бор!",544,28],["لَّ[f:1752[ن ت]ُغْنِىَ عَنْهُمْ أَمْو[n[َٲ]لُهُمْ وَل[o[َآ] أَوْلَ[n[ـٰ]دُه[w:1753[ُم م]ِّنَ [h:321[ٱ]للَّهِ شَيْــًٔا‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ‌ۖ هُمْ فِيهَا خَ[n[ـٰ]لِد[p[ُو]نَ","Моллари ҳам, болалари ҳам улардан Аллоҳдан ҳеч нарсани қайтара олмас. Ундай кишилар дўзах аҳлидурлар. Улар унда абадий қолурлар.",544,28],["يَوْمَ يَ[q:4022[بْ]عَثُهُمُ [h:4023[ٱ]للَّهُ جَمِي[f:13425[عًا ف]َيَحْلِفُونَ لَهُ[n[ۥ] كَمَا يَحْلِفُونَ لَكُمْ‌ۖ وَيَحْسَبُونَ أَ[g[نّ]َهُمْ عَلَىٰ شَىْءٍ‌ۚ أَل[o[َآ] إِ[g[نّ]َهُمْ هُمُ [h:7594[ٱ]لْكَ[n[ـٰ]ذِب[p[ُو]نَ","Аллоҳ уларнинг барчасини қайта тирилтирадиган кунда худди сизларга қасам ичганларидек, Унга ҳам қасам ичарлар, ва бирор нарсага эришамиз, деб ўйларлар. Аё, огоҳ бўлинг, улар, ҳа, улар ёлғончидирлар.",544,28],["ٱسْتَحْوَذَ عَلَيْهِمُ [h:13426[ٱ][l[ل]شَّيْطَ[n[ـٰ]نُ فَأَ[f:13427[نس]َ[n[ـٰ]هُمْ ذِكْرَ [h:13428[ٱ]للَّهِ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ حِزْبُ [h:13429[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ‌ۚ أَل[o[َآ] إِ[g[نّ]َ حِزْبَ [h:13430[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ هُمُ [h:150[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","Шайтон уларни эгаллаб олган ва Аллоҳнинг зикрини унутдирган. Ана ўшалар, шайтон фирқасидирлар. Аё, огоҳ бўлинглар, шайтон фирқаси, ҳа, ўшалар, ютқазувчидирлар.",544,28],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يُح[m[َا]ٓدُّونَ [h:13395[ٱ]للَّهَ وَرَسُولَهُ[o[ۥٓ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ فِى [h:13431[ٱ]لْأَذَلّ[p[ِي]نَ","Албатта, Аллоҳга ва Унинг Расулига душманлик қилувчилар, ана ўшалар, энг хорлар ичидадир.",544,28],["كَتَبَ [h:989[ٱ]للَّهُ لَأَغْلِبَ[g[نّ]َ أَنَا۟ وَرُسُل[o[ِىٓ‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ قَوِىٌّ عَز[p[ِي]زٌ","Аллоҳ, Мен ва Менинг Расулларим ғалаба қиламиз, деб ҳукм қилган. Албатта, Аллоҳ қувватли ва ғолибдир.",544,28],["لَّا تَجِدُ قَوْ[a:13432[مًا ي]ُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ يُو[m[َا]ٓدُّونَ مَنْ ح[m[َا]ٓدَّ [h:13433[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] وَلَوْ كَان[o[ُوٓ][s[اْ] ءَاب[o[َا]ٓءَهُمْ أَوْ أَ[q:767[بْ]ن[o[َا]ٓءَهُمْ أَوْ إِخْو[n[َٲ]نَهُمْ أَوْ عَشِيرَتَهُمْ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ كَتَبَ فِى قُلُوبِهِمُ [h:13434[ٱ]لْإِيمَ[n[ـٰ]نَ وَأَيَّدَه[c:13435[ُم ب]ِرُو[a:13436[حٍ م]ِّنْهُ‌ۖ وَيُ[q:13437[دْ]خِلُهُمْ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۚ رَضِىَ [h:3910[ٱ]للَّهُ عَنْهُمْ وَرَضُو[s[اْ] عَنْهُ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ حِزْبُ [h:13438[ٱ]للَّهِ‌ۚ أَل[o[َآ] إِ[g[نّ]َ حِزْبَ [h:3642[ٱ]للَّهِ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Аллоҳга ва охират кунига иймон келтирган қавмнинг Аллоҳга ва Унинг Расулига душманлик қилувчиларга дўстлик қилганларини топмайсан. Ҳатто улар ўз оталари, болалари, ака-укалари ёки қариндошлари бўлса ҳам. Аллоҳ ундоқ кишиларнинг қалбларида иймонни собит қилган, уларни Ўз ҳузуридан бир руҳ билан қўллагандир. Ва уларни остидан сувлар оқиб турган жаннатларга киритадир. Унда абадий қолурлар. Аллоҳ улардан рози бўладир. Улар Аллоҳдан рози бўладир. Ана ўшалар, Аллоҳнинг фирқасидирлар. Аё, огоҳ бўлинглар, албатта, Аллоҳнинг фирқаси, ҳа, ўшалар ютувчилардир.",545,28]]},{"n":59,"ar":"الحَشۡرِ","en":"Al-Hashr","uz":"Ҳашр","type":"Мадина","ayahs":[["سَبَّحَ لِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۖ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Осмонлардагию ердаги барча нарсалар Аллоҳни поклаб ёд этди. У зот азиз ва ҳикматли Зотдир.",545,28],["هُوَ [h:153[ٱ]لَّذ[o[ِىٓ] أَخْرَجَ [h:13439[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ مِ[f:432[ن د]ِيَ[n[ـٰ]رِهِمْ لِأَوَّلِ [h:13440[ٱ]لْحَشْرِ‌ۚ مَا ظَنَ[f:12002[نت]ُمْ أ[a:3533[َن ي]َخْرُجُو[s[اْ‌ۖ] وَظَ[g[نّ][o[ُوٓ][s[اْ] أَ[g[نّ]َه[w:13441[ُم م]َّانِعَتُهُمْ حُصُونُه[w:13442[ُم م]ِّنَ [h:321[ٱ]للَّهِ فَأَتَ[n[ـٰ]هُمُ [h:13443[ٱ]للَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُو[s[اْ‌ۖ] وَقَذَفَ فِى قُلُوبِهِمُ [h:10763[ٱ][l[ل]رُّعْبَ‌ۚ يُخْرِبُونَ بُيُوتَه[c:13444[ُم ب]ِأَيْدِيهِمْ وَأَيْدِى [h:13445[ٱ]لْمُؤْمِنِينَ فَ[h:13446[ٱ]عْتَبِرُو[s[اْ] يَ[o[ـٰٓ]أُ[s[وْ]لِى [h:13447[ٱ]لْأَ[q:1767[بْ]صَ[p[ـٰ]رِ","У зот аҳли китобдан бўлган кофирларни ўз диёрларидан биринчи ҳашр учун чиқарди. Уларни чиқади деб ўйламаган эдингиз. Ўзлари ҳам қўрғонимиз бизни Аллоҳдан сақлаб қоладир, деб ўйлашарди. Аллоҳ улар ўйламаган тарафдан олди ва уларни қалбига қўрқинч солди. Уйларини ўз қўллари билан ва мўминларнинг қўллари билан буза бошладилар. Ибрат олинг, эй ақл эгалари!",545,28],["وَلَوْل[o[َآ] أَ[f:13448[ن ك]َتَبَ [h:989[ٱ]للَّهُ عَلَيْهِمُ [h:13449[ٱ]لْجَل[o[َا]ٓءَ لَعَذَّبَهُمْ فِى [h:599[ٱ][l[ل]دُّنْيَا‌ۖ وَلَهُمْ فِى [h:536[ٱ]لْأَخِرَةِ عَذَابُ [h:13450[ٱ][l[ل][g[نّ][p[َا]رِ","Мабодо Аллоҳ уларга кўчишни ёзмаганда ҳам бу дунёда уларни азоблар эди. Уларга охиратда дўзах азоби бордур.",545,28],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ ش[m[َا]ٓقُّو[s[اْ] [h:5272[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ]‌ۖ وَم[a:13451[َن ي]ُش[m[َا]ٓقِّ [h:13452[ٱ]للَّهَ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ شَدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Ундай бўлиши, улар Аллоҳга ва Унинг Расулига хилоф қилганлари учундир. Кимки Аллоҳга хилоф қилса, албатта, Аллоҳ - азоби зўр зотдир.",546,28],["مَا قَطَعْت[w:13453[ُم م]ّ[u:13454[ِن ل]ِّينَةٍ أَوْ تَرَكْتُمُوهَا ق[o[َا]ٓئِمَةً عَلَ[o[ىٰٓ] أُصُولِهَا فَبِإِذْنِ [h:2398[ٱ]للَّهِ وَلِيُخْزِىَ [h:13455[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","Сизнинг хурмони кесишингиз ёки аслида тик қолдирганингиз фақат, Аллоҳнинг изни билан ва бузғунчиларни хорлаши учун бўлди.",546,28],["وَم[o[َآ] أَف[o[َا]ٓءَ [h:10855[ٱ]للَّهُ عَلَىٰ رَسُولِه[n[ِۦ] مِنْهُمْ فَم[o[َآ] أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْ[a:13456[لٍ و]َلَا رِكَا[a:13457[بٍ و]َلَ[n[ـٰ]كِ[g[نّ]َ [h:1441[ٱ]للَّهَ يُسَلِّطُ رُسُلَهُ[n[ۥ] عَلَىٰ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Аллоҳ Ўз Расулига улардан қайтариб берган нарсага сизлар от ёки туя чоптириб бормадингиз. Лекин Аллоҳ Ўз Пайғамбарини хоҳлаган кимсанинг устидан, ғолиб қиладир. Аллоҳ ҳар бир нарсага қодирдир.",546,28],["مّ[o[َآ] أَف[o[َا]ٓءَ [h:10855[ٱ]للَّهُ عَلَىٰ رَسُولِه[n[ِۦ] مِنْ أَهْلِ [h:6852[ٱ]لْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى [h:5340[ٱ]لْقُرْبَىٰ وَ[h:420[ٱ]لْيَتَ[n[ـٰ]مَىٰ وَ[h:421[ٱ]لْمَسَ[n[ـٰ]كِينِ وَ[h:1189[ٱ][q:1189[بْ]نِ [h:1190[ٱ][l[ل]سَّبِيلِ كَىْ لَا يَكُونَ دُولَ[i:13458[ةَۢ ب]َيْنَ [h:13459[ٱ]لْأَغْنِي[o[َا]ٓءِ مِ[f:344[نك]ُمْ‌ۚ وَم[o[َآ] ءَاتَ[n[ـٰ]كُمُ [h:13460[ٱ][l[ل]رَّسُولُ فَخُذُوهُ وَمَا نَهَ[n[ـٰ]كُمْ عَنْهُ فَ[h:13461[ٱ][f:13461[نت]َهُو[s[اْ‌ۚ] وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ شَدِيدُ [h:1075[ٱ]لْعِق[p[َا][q[ب]ِ","Аллоҳ Ўз Расулига шаҳар аҳлидан қайтариб берган нарса. Аллоҳгадир ва Унинг Расулига ва яқин қариндошларига, етимларга ва мискинларга ва кўча ўғилларигадир. Сизлардан бойларингиз орасида айланадиган нарса бўлиб қолмаслиги учун. Пайғамбар сизга нимани берса, ўшани олинглар ва нимадан қайтарса, ўшандан қайтинглар. Аллоҳдан қўрқинглар. Албатта, Аллоҳ азоби шиддатли зотдир.",546,28],["لِلْفُقَر[o[َا]ٓءِ [h:13462[ٱ]لْمُهَ[n[ـٰ]جِرِينَ [h:13463[ٱ]لَّذِينَ أُخْرِجُو[s[اْ] مِ[f:432[ن د]ِيَ[n[ـٰ]رِهِمْ وَأَمْو[n[َٲ]لِهِمْ يَ[q:3357[بْ]تَغُونَ فَضْل[a:12703[اً م]ِّنَ [h:321[ٱ]للَّهِ وَرِضْو[n[َٲ][a:13464[نًا و]َيَ[f:13465[نص]ُرُونَ [h:13466[ٱ]للَّهَ وَرَسُولَهُ[o[ۥٓ‌ۚ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:12772[ٱ][l[ل]صَّ[n[ـٰ]دِق[p[ُو]نَ","Фақир муҳожирларгаки, улар ўз диёрларидан ва мол-мулкларидан жудо қилинган эдилар, Аллоҳдан фазл ва Унинг розилигини умид қилулар. Аллоҳга ва Унинг Расулига ёрдам берурлар. Ана ўшалар содиқлардир.",546,28],["وَ[h:9999[ٱ]لَّذِينَ تَبَوَّءُو [h:13467[ٱ][l[ل]دَّارَ وَ[h:10535[ٱ]لْإِيمَ[n[ـٰ]نَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَ[a:13468[ةً م]ِّ[g[مّ][o[َآ] أُوتُو[s[اْ] وَيُؤْثِرُونَ عَلَ[o[ىٰٓ] أَ[f:568[نف]ُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَ[a:13469[ةٌ‌ۚ و]َم[a:13470[َن ي]ُوقَ شُحَّ نَفْسِه[n[ِۦ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Улардан аввал бу жойда яшаган ва иймонга. Ўзларига ҳижрат қилиб келганларни севадирлар ва уларга берилган нарсаларга қалбларида ҳасад қилмаслар. Ва гар ўзларининг ҳожатлари бўлса ҳам, ўзларидан устун қўярлар. Ким ўз нафсининг бахиллигидан сақланса, ундоқ кишилар, ҳа, ўшалар ютувчилардир.",546,28],["وَ[h:9999[ٱ]لَّذِينَ ج[o[َا]ٓءُو م[i:1453[ِنۢ ب]َعْدِهِمْ يَقُولُونَ رَبَّنَا [h:2305[ٱ]غْفِرْ لَنَا وَلِإِخْو[n[َٲ]نِنَا [h:13471[ٱ]لَّذِينَ سَبَقُونَا بِ[h:562[ٱ]لْإِيمَ[n[ـٰ]نِ وَلَا تَ[q:7716[جْ]عَلْ فِى قُلُوبِنَا غِل[u:13472[اًّ ل]ِّلَّذِينَ ءَامَنُو[s[اْ] رَبَّن[o[َآ] إِ[g[نّ]َكَ رَءُو[u:5881[فٌ ر]َّح[p[ِي]مٌ","Улардан кейин келганлар: «Эй Роббимиз, бизни ва биздан аввал иймон билан ўтган биродарларимизни мағфират қилгин, қалбимизда иймон келтирганларга нафрат солмагин, эй Роббимиз, албатта, сен шафқатли ва меҳрибонсан», дерлар.",547,28],["۞ أَلَمْ تَرَ إِلَى [h:1372[ٱ]لَّذِينَ نَافَقُو[s[اْ] يَقُولُونَ لِإِخْو[n[َٲ]نِهِمُ [h:13473[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ لَئِنْ أُخْرِ[q:13474[جْ]تُمْ لَنَخْرُجَ[g[نّ]َ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَ[a:13475[دًا و]َإِ[f:13476[ن ق]ُوتِلْتُمْ لَنَ[f:13477[نص]ُرَ[g[نّ]َكُمْ وَ[h:72[ٱ]للَّهُ يَشْهَدُ إِ[g[نّ]َهُمْ لَكَ[n[ـٰ]ذِب[p[ُو]نَ","Нифоқ қилганларнинг аҳли китобдан бўлмиш куфр келтирган ўз биродарларига: «Агар сизлар чиқарилсангиз, биз ҳам сизлар билан чиқамиз, сизни қуйиб ҳеч қачон ҳеч кимга итоат қилмасмиз ва мабодо сизларга уруш қилинса, албатта ёрдам берурмиз», дейишларини кўрмайсанми?",547,28],["لَئِنْ أُخْرِجُو[s[اْ] لَا يَخْرُجُونَ مَعَهُمْ وَلَئِ[f:13478[ن ق]ُوتِلُو[s[اْ] لَا يَ[f:12166[نص]ُرُونَهُمْ وَلَئ[a:13479[ِن ن]َّصَرُوهُمْ لَيُوَلُّ[g[نّ]َ [h:13480[ٱ]لْأَ[q:2168[دْ]بَ[n[ـٰ]رَ ثُ[g[مّ]َ لَا يُ[f:237[نص]َر[p[ُو]نَ","Албатта агар улар чиқарилсалар, улар бирга чиқмаслар. Ва, албатта, агар уларга уруш қилинса, уларга ёрдам бермаслар. Бордию ёрдам берганларида ҳам, ортларига қараб қочарлар ва алар ёрдамсиз қоларлар.",547,28],["لَأَ[f:13481[نت]ُمْ أَشَدُّ رَهْبَ[f:13482[ةً ف]ِى صُدُورِه[w:13483[ِم م]ِّنَ [h:321[ٱ]للَّهِ‌ۚ ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ قَوْ[u:3651[مٌ ل]َّا يَفْقَه[p[ُو]نَ","Албатта, уларнинг қалбларига Аллоҳдан кўра сизлар кўпроқ қўрқинчли туюласизлар. Чунки улар яхши англамайдиган қавмдирлар.",547,28],["لَا يُقَ[n[ـٰ]تِلُونَكُمْ جَمِيعًا إِلَّا فِى قُ[a:13484[رًى م]ُّحَصَّنَةٍ أَوْ م[a:10877[ِن و]َر[o[َا]ٓءِ جُدُ[i:13485[رِۭ‌ۚ ب]َأْسُه[c:13486[ُم ب]َيْنَهُمْ شَدِي[f:13487[دٌ‌ۚ ت]َحْسَبُهُمْ جَمِي[a:13488[عًا و]َقُلُوبُهُمْ شَتَّىٰ‌ۚ ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ قَوْ[u:3651[مٌ ل]َّا يَعْقِل[p[ُو]نَ","Сизларга қарши уюшиб очиқ уруш қила олмаслар, балки қўрғон билан ўралган қишлоқларда ёки деворлар ортига бекиниб олиб уруш қилурлар. Ўз ораларида адоватлари шиддатли. Уларни бир деб ўйлайсан. Ҳолбуки, қалблари тарқоқдир. Бу, уларнинг ақл юритмайдиган қавм эканликларидандир.",547,28],["كَمَثَلِ [h:13489[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ قَرِي[f:13490[بًا‌ۖ ذ]َاقُو[s[اْ] وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Бу худди яқинда ўз қилмишларининг оқибатини татиб кўрганларга ўхшашдир. Ва уларга аламли азоблар бор.",547,28],["كَمَثَلِ [h:13491[ٱ][l[ل]شَّيْطَ[n[ـٰ]نِ إِذْ قَالَ لِلْإِ[f:6549[نس]َ[n[ـٰ]نِ [h:13492[ٱ]كْفُرْ فَلَ[g[مّ]َا كَفَرَ قَالَ إِ[g[نّ]ِى بَر[o[ِى]ٓ[a:13493[ءٌ م]ِّ[f:3891[نك]َ إِ[g[نّ][o[ِىٓ] أَخَافُ [h:3504[ٱ]للَّهَ رَبَّ [h:3505[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Бу худди Шайтон инсонга, кофир бўл, деган пайтга ўхшайдир. У куфр келтирганда эса, сен билан менинг ишим йўқ, мен оламлар Оббиси-Аллоҳдан қўрқаман, деди.",547,28],["فَكَانَ عَ[n[ـٰ]قِبَتَهُم[o[َآ] أَ[g[نّ]َهُمَا فِى [h:4674[ٱ][l[ل][g[نّ]َارِ خَ[n[ـٰ]لِدَيْنِ فِيهَا‌ۚ وَذ[n[َٲ]لِكَ جَز[o[َٲ]ٓؤُ[s[اْ] [h:3508[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Бас, уларнинг оқибатлари бир. Албатта, икковлари ҳам дўзахда бўлурлар, у ерда абадий қолурлар. Ва бу золимларнинг жазосидир.",548,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] [h:1643[ٱ]تَّقُو[s[اْ] [h:1644[ٱ]للَّهَ وَلْتَ[f:13494[نظ]ُرْ نَفْ[a:10644[سٌ م]َّا قَدَّمَتْ لِغَ[a:13495[دٍ‌ۖ و]َ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ خَبِي[i:2335[رُۢ ب]ِمَا تَعْمَل[p[ُو]نَ","Эй иймон келтирганлар! Аллоҳга тақво қилинглар! Ҳар ким эрталик учун нима тақдим қилганига назар солсин. Аллоҳга тақво қилинглар! Албатта, Аллоҳ нима қилаётганингиздан хабардордир.",548,28],["وَلَا تَكُونُو[s[اْ] كَ[h:2146[ٱ]لَّذِينَ نَسُو[s[اْ] [h:5697[ٱ]للَّهَ فَأَ[f:13427[نس]َ[n[ـٰ]هُمْ أَ[f:38[نف]ُسَهُمْ‌ۚ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:2071[ٱ]لْفَ[n[ـٰ]سِق[p[ُو]نَ","Аллоҳни унутганларга ўхшаган бўлманглар. У зот уларга ўз шахсларини унутдирди. Ана ўшалар, фосиқдирлар.",548,28],["لَا يَسْتَو[o[ِىٓ] أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ وَأَصْحَ[n[ـٰ]بُ [h:13496[ٱ]لْجَ[g[نّ]َةِ‌ۚ أَصْحَ[n[ـٰ]بُ [h:415[ٱ]لْجَ[g[نّ]َةِ هُمُ [h:5510[ٱ]لْف[o[َا]ٓئِز[p[ُو]نَ","Дўзах эгалари ва жаннат эгалари тенг бўлмаслар. Жаннат эгалари, ўшалар ютуққа эришувчилардир.",548,28],["لَوْ أَ[f:515[نز]َلْنَا هَ[n[ـٰ]ذَا [h:6544[ٱ]لْقُرْءَانَ عَلَىٰ جَبَ[u:13497[لٍ ل]َّرَأَيْتَهُ[n[ۥ] خَ[n[ـٰ]شِ[a:13498[عًا م]ُّتَصَدِّ[a:13499[عًا م]ِّنْ خَشْيَةِ [h:383[ٱ]للَّهِ‌ۚ وَتِلْكَ [h:10375[ٱ]لْأَمْثَ[n[ـٰ]لُ نَضْرِبُهَا لِل[g[نّ]َاسِ لَعَلَّهُمْ يَتَفَكَّر[p[ُو]نَ","Агар ушбу Қуъонни тоғга туширганимизда эди, унинг Аллоҳдан қўрққанидан титраб-қақшаб ва парчаланиб кетганини кўрар эдинг. Ушбу мисолларни одамларга келтирурмиз, шоядки улар фикр юритсалар.",548,28],["هُوَ [h:8078[ٱ]للَّهُ [h:4738[ٱ]لَّذِى ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۖ عَ[n[ـٰ]لِمُ [h:4186[ٱ]لْغَيْبِ وَ[h:4187[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ‌ۖ هُوَ [h:829[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ [h:830[ٱ][l[ل]رَّح[p[ِي]مُ","У Аллоҳ Ундан ўзга илоҳ йўқ зотдир. У ғойибни ҳам, ошкорни ҳам билувчидир. У меҳрибон ва раҳмлидир.",548,28],["هُوَ [h:8078[ٱ]للَّهُ [h:4738[ٱ]لَّذِى ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ [h:13500[ٱ]لْمَلِكُ [h:13501[ٱ]لْقُدُّوسُ [h:13502[ٱ][l[ل]سَّلَ[n[ـٰ]مُ [h:13503[ٱ]لْمُؤْمِنُ [h:13504[ٱ]لْمُهَيْمِنُ [h:13505[ٱ]لْعَزِيزُ [h:13506[ٱ]لْجَبَّارُ [h:13507[ٱ]لْمُتَكَبِّرُ‌ۚ سُ[q:7648[بْ]حَ[n[ـٰ]نَ [h:9282[ٱ]للَّهِ عَ[g[مّ]َا يُشْرِك[p[ُو]نَ","У Аллоҳ, Ундан ўзга илоҳ йўқ. У - Малик, У-Қуддус, У-Салом, У- Мўмин, У- Муҳаймин, У-Азиз, У-Жаббор, У-мутакаббирдир. Аллоҳ Унга ширк келтираётган нарсалардан покдир.",548,28],["هُوَ [h:8078[ٱ]للَّهُ [h:13508[ٱ]لْخَ[n[ـٰ]لِقُ [h:13509[ٱ]لْبَارِئُ [h:13510[ٱ]لْمُصَوِّرُ‌ۖ لَهُ [h:8445[ٱ]لْأَسْم[o[َا]ٓءُ [h:5156[ٱ]لْحُسْنَىٰ‌ۚ يُسَبِّحُ لَهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۖ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","У Аллоҳ Холиқ, Бариъу, Мусаввирдур. Барча гўзал исмлар Уникидир. Осмонлару ердаги барча нарсалар Уни поклаб ёд этарлар. Яна У Азиз ва Ҳакимдир.",548,28]]},{"n":60,"ar":"المُمۡتَحنَةِ","en":"Al-Mumtahana","uz":"Мумтаҳана","type":"Мадина","ayahs":[["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَتَّخِذُو[s[اْ] عَدُوِّى وَعَدُوَّكُمْ أَوْلِي[o[َا]ٓءَ تُلْقُونَ إِلَيْه[c:13511[ِم ب]ِ[h:13512[ٱ]لْمَوَدَّةِ وَقَ[q:387[دْ] كَفَرُو[s[اْ] بِمَا ج[o[َا]ٓءَك[w:3440[ُم م]ِّنَ [h:1173[ٱ]لْحَقِّ يُخْرِجُونَ [h:13513[ٱ][l[ل]رَّسُولَ وَإِيَّاكُمْ‌ۙ أَ[f:13514[ن ت]ُؤْمِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ رَبِّكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ خَرَ[q:13515[جْ]تُمْ جِهَ[n[ـٰ][f:13516[دًا ف]ِى سَبِيلِى وَ[h:1741[ٱ][q:1741[بْ]تِغ[o[َا]ٓءَ مَرْضَاتِى‌ۚ تُسِرُّونَ إِلَيْه[c:13511[ِم ب]ِ[h:13512[ٱ]لْمَوَدَّةِ وَأَنَا۟ أَعْلَمُ بِم[o[َآ] أَخْفَيْتُمْ وَم[o[َآ] أَعْلَ[f:13517[نت]ُمْ‌ۚ وَم[a:13518[َن ي]َفْعَلْهُ مِ[f:344[نك]ُمْ فَقَ[q:563[دْ] ضَلَّ سَو[o[َا]ٓءَ [h:564[ٱ][l[ل]سَّب[p[ِي]لِ","Эй иймон келтирганлар! Агар Менинг йўлимда жиҳод қилиб ва розилигимни сўраб чиққан бўлсангиз, Менинг душманларимни ва ўзингизнинг душманларингизни дўст тутманглар. Сизлар уларга дўстлик қиласизлар, улар бўлса сизларга келган ҳаққа куфр келтирарлар. Роббингиз бўлмиш Аллоҳга иймон келтирганингиз учун Пайғамбарни ва сизни ҳайдаб чиқарарлар. Сиз уларга дўстлик қилиб сир айтасиз. Ҳолбуки, Мен нимани махфий тутганингизнию нимани ошкор қилганингизни жуда яхши билурман. Ораларингизда ким ўша ишни қилса, тўғри йўлдан адашган бўладир.",549,28],["إ[a:13519[ِن ي]َثْقَفُوكُمْ يَكُونُو[s[اْ] لَكُمْ أَعْد[o[َا]ٓ[a:13520[ءً و]َيَ[q:13521[بْ]سُط[o[ُوٓ][s[اْ] إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَه[c:13522[ُم ب]ِ[h:875[ٱ][l[ل]سّ[o[ُو]ٓءِ وَوَدُّو[s[اْ] لَوْ تَكْفُر[p[ُو]نَ","Агар улар сиздан устун келсалар, сизга душман бўларлар ва сизларга қўлларию тилларини ёмонликла чўзар лар. Ва сизларнинг кофир бўлишларингизни хоҳларлар.",549,28],["لَ[f:13523[ن ت]َ[f:13524[نف]َعَكُمْ أَرْحَامُكُمْ وَل[o[َآ] أَوْلَ[n[ـٰ]دُكُمْ‌ۚ يَوْمَ [h:592[ٱ]لْقِيَ[n[ـٰ]مَةِ يَفْصِلُ بَيْنَكُمْ‌ۚ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","Қариндошларингиз ва фарзандларингиз сизга ҳеч манфаат бера олмаслар. Қиёмат куни У зот ораларингизни бўлур. Аллоҳ нима қилаётганингизни кўриб тургувчидир.",549,28],["قَ[q:298[دْ] كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَ[f:13525[ةٌ ف][o[ِىٓ] إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَ[h:37[ٱ]لَّذِينَ مَعَهُ[o[ۥٓ] إِذْ قَالُو[s[اْ] لِقَوْمِهِمْ إِ[g[نّ]َا بُرَء[o[َٲ]ٓؤُ[s[اْ] مِ[f:344[نك]ُمْ وَمِ[g[مّ]َا تَعْبُدُونَ مِ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ [h:13526[ٱ]لْعَد[n[َٲ]وَةُ وَ[h:13527[ٱ]لْبَغْض[o[َا]ٓءُ أَبَدًا حَتَّىٰ تُؤْمِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَحْدَهُ[o[ۥٓ] إِلَّا قَوْلَ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ لِأَبِيهِ لَأَسْتَغْفِرَ[g[نّ]َ لَكَ وَم[o[َآ] أَمْلِكُ لَكَ مِنَ [h:321[ٱ]للَّهِ مِ[f:2103[ن ش][u:13528[َىْءٍ‌ۖ ر]َّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَ[q:13529[بْ]نَا وَإِلَيْكَ [h:1712[ٱ]لْمَص[p[ِي]رُ","Ҳақиқатда, сизларга Иброҳим ва у билан бирга бўлганларда яхши ўрнак бор. Улар, биз сиздан ва сиз ибодат қилаётган нарсадан безормиз, сизга куфр келтирдик, энди токи ягона Аллоҳга иймон келтирмагунларингизча орамизда доимий адоват ва кучли нафрат пайдо бўлди, дедилар. Магар Иброҳимнинг отасига қарата, албатта сен учун истиғфор айтаман, сендан Аллоҳдан бирор нарса қайтаришга молик эмасман, деган сўзи мустасно. Эй Роббимиз, фақат Сенга таваккал қилдик, фақат Сенгагина қайтдик ва қайтиб борадиган жой ҳам фақат Сенгинадир.",549,28],["رَبَّنَا لَا تَ[q:4719[جْ]عَلْنَا فِتْنَ[u:9071[ةً ل]ِّلَّذِينَ كَفَرُو[s[اْ] وَ[h:1720[ٱ]غْفِرْ لَنَا رَبَّن[o[َآ‌ۖ] إِ[g[نّ]َكَ أَ[f:169[نت]َ [h:680[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Эй Роббимиз, бизни кофирларга фитна қилиб қўймагин ва бизни кечиргин. Эй Роббимиз, албатта, Сен, Ўзинг азизу ҳакимсан.",549,28],["لَقَ[q:2389[دْ] كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَ[u:10738[ةٌ ل]ِّمَ[f:10739[ن ك]َانَ يَرْجُو[s[اْ] [h:10740[ٱ]للَّهَ وَ[h:10741[ٱ]لْيَوْمَ [h:10742[ٱ]لْأَخِرَ‌ۚ وَم[a:3640[َن ي]َتَوَلَّ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ هُوَ [h:6121[ٱ]لْغَنِىُّ [h:9093[ٱ]لْحَم[p[ِي][q[د]ُ","Албатта, кимнинг Аллоҳдан ва қиёмат кунидан умиди бўлса, шулар учун уларда яхши ўрнак бор эди. Лекин ким юз ўгирса, Аллоҳ беҳожат, мақталган зотдир.",550,28],["۞ عَسَى [h:2982[ٱ]للَّهُ أ[a:13530[َن ي]َ[q:2441[جْ]عَلَ بَيْنَكُمْ وَبَيْنَ [h:7774[ٱ]لَّذِينَ عَادَيْت[w:13531[ُم م]ِّنْه[w:13532[ُم م]َّوَدَّ[a:13533[ةً‌ۚ و]َ[h:72[ٱ]للَّهُ قَدِي[a:13534[رٌ‌ۚ و]َ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Шоядки, Аллоҳ сизлар билан улар ичидаги душманларингиз ўртасида дўстлик пайдо қилса, Аллоҳ қодирдир. Аллоҳ кечирувчи ва раҳмдилдир.",550,28],["لَّا يَنْهَ[n[ـٰ]كُمُ [h:13535[ٱ]للَّهُ عَنِ [h:3106[ٱ]لَّذِينَ لَمْ يُقَ[n[ـٰ]تِلُوكُمْ فِى [h:1477[ٱ][l[ل]دِّينِ وَلَمْ يُخْرِجُوك[w:13536[ُم م]ِّ[f:426[ن د]ِيَ[n[ـٰ]رِكُمْ أَ[f:13537[ن ت]َبَرُّوهُمْ وَتُ[q:13538[قْ]سِط[o[ُوٓ][s[اْ] إِلَيْهِمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُحِبُّ [h:3555[ٱ]لْمُ[q:3556[قْ]سِط[p[ِي]نَ","Аллоҳ сизларни диний уруш қилмаган ва диёрларингиздан чиқармаганларга яхшилик ва адолатли муомала қилишдан сизларни қайтармас. Албатта, Аллоҳ адолат қилувчиларни яхши кўрадир.",550,28],["إِ[g[نّ]َمَا يَنْهَ[n[ـٰ]كُمُ [h:13535[ٱ]للَّهُ عَنِ [h:3106[ٱ]لَّذِينَ قَ[n[ـٰ]تَلُوكُمْ فِى [h:1477[ٱ][l[ل]دِّينِ وَأَخْرَجُوك[w:13539[ُم م]ِّ[f:426[ن د]ِيَ[n[ـٰ]رِكُمْ وَظَ[n[ـٰ]هَرُو[s[اْ] عَلَ[o[ىٰٓ] إِخْرَاجِكُمْ أَ[f:13540[ن ت]َوَلَّوْهُمْ‌ۚ وَم[a:3619[َن ي]َتَوَلَّهُمْ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:1285[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ُو]نَ","Албатта Аллоҳ сизларни диний уруш қилганлар, диёрингиздан чиқарганлар ва чиқарилишингизга ёрдам берганларга дўстлик қилишдан қайтарур. Уларни дўст тутганлар, ана ўшалар, золимлардир.",550,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا ج[o[َا]ٓءَكُمُ [h:13541[ٱ]لْمُؤْمِنَ[n[ـٰ]تُ مُهَ[n[ـٰ]جِر[n[َٲ][f:13542[تٍ ف]َ[h:13543[ٱ]مْتَحِنُوهُ[g[نّ]َ‌ۖ [h:13544[ٱ]للَّهُ أَعْلَمُ بِإِيمَ[n[ـٰ]نِهِ[g[نّ]َ‌ۖ فَإِنْ عَلِمْتُمُوهُ[g[نّ]َ مُؤْمِنَ[n[ـٰ][f:13545[تٍ ف]َلَا تَرْجِعُوهُ[g[نّ]َ إِلَى [h:13546[ٱ]لْكُفَّارِ‌ۖ لَا هُ[g[نّ]َ حِ[u:3396[لٌّ ل]َّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُ[g[نّ]َ‌ۖ وَءَاتُوه[w:13547[ُم م]ّ[o[َآ] أَ[f:1538[نف]َقُو[s[اْ‌ۚ] وَلَا جُنَاحَ عَلَيْكُمْ أَ[f:3169[ن ت]َ[f:3170[نك]ِحُوهُ[g[نّ]َ إِذ[o[َآ] ءَاتَيْتُمُوهُ[g[نّ]َ أُجُورَهُ[g[نّ]َ‌ۚ وَلَا تُمْسِكُو[s[اْ] بِعِصَمِ [h:13548[ٱ]لْكَوَافِرِ وَسْــَٔلُو[s[اْ] م[o[َآ] أَ[f:1186[نف]َ[q:1186[قْ]تُمْ وَلْيَسْــَٔلُو[s[اْ] م[o[َآ] أَ[f:1538[نف]َقُو[s[اْ‌ۚ] ذ[n[َٲ]لِكُمْ حُكْمُ [h:3559[ٱ]للَّهِ‌ۖ يَحْكُمُ بَيْنَكُمْ‌ۚ وَ[h:72[ٱ]للَّهُ عَلِيمٌ حَك[p[ِي]مٌ","Эй, иймон келтирганлар! Агар сизларга мўминалар ҳижрат қилиб келсалар, уларни имтиҳон қилиб кўринглар. Аллоҳ уларнинг иймонини билгувчидир. Бас, мўминаликларини билсангиз, уларни кофирларга қайтариб юборманг. Бу лар уларга ҳалол эмас ва улар ҳам буларга ҳалол бўлмаслар. Ва уларга нафақа қилган нарсаларини беринглар. Ва уларни никоҳлаб олсангиз, агар маҳрларини берсангиз, сизларга гуноҳ бўлмас. Кофир хотинларингизни никоҳларингизда ушлаб турманглар. Нафақа қилган нарсаларингизни сўранглар, улар ҳам нафақа қилган нарсаларини сўрасинлар. Бу сизларга Аллоҳнинг ҳукмидир. Орангизда ҳукм қиладир. Аллоҳ билгувчи ва ҳикматлидир.",550,28],["وَإِ[f:13549[ن ف]َاتَكُمْ ش[a:13550[َىْءٌ م]ِّنْ أَزْو[n[َٲ]جِكُمْ إِلَى [h:13546[ٱ]لْكُفَّارِ فَعَاقَ[q:13551[بْ]تُمْ فَـَٔـاتُو[s[اْ] [h:13552[ٱ]لَّذِينَ ذَهَبَتْ أَزْو[n[َٲ]جُه[w:13553[ُم م]ِّثْلَ م[o[َآ] أَ[f:1538[نف]َقُو[s[اْ‌ۚ] وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ [h:2537[ٱ]لَّذ[o[ِىٓ] أَ[f:428[نت][c:3753[ُم ب]ِه[n[ِۦ] مُؤْمِن[p[ُو]نَ","Агар аёлларингиздан бирортаси кофирларга ўтиб кетса, урушда туширилган ўлжадан хотини кетиб қолганга, у нафақа қилган миқдорни берингиз. Ўзингиз иймон келтирган Аллоҳдан қўрқинг.",550,28],["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ إِذَا ج[o[َا]ٓءَكَ [h:13554[ٱ]لْمُؤْمِنَ[n[ـٰ]تُ يُبَايِعْنَكَ عَلَ[o[ىٰٓ] أ[u:4908[َن ل]َّا يُشْرِكْنَ بِ[h:32[ٱ]للَّهِ شَيْـ[a:232[ـًٔا و]َلَا يَسْرِ[q:13555[قْ]نَ وَلَا يَزْنِينَ وَلَا يَ[q:13556[قْ]تُلْنَ أَوْلَ[n[ـٰ]دَهُ[g[نّ]َ وَلَا يَأْتِينَ بِبُهْتَ[n[ـٰ][a:13557[نٍ ي]َفْتَرِينَهُ[n[ۥ] بَيْنَ أَيْدِيهِ[g[نّ]َ وَأَرْجُلِهِ[g[نّ]َ وَلَا يَعْصِينَكَ فِى مَعْرُو[f:13558[فٍ‌ۙ ف]َبَايِعْهُ[g[نّ]َ وَ[h:2374[ٱ]سْتَغْفِرْ لَهُ[g[نّ]َ [h:13559[ٱ]للَّهَ‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Эй Набий! Агар мўминалар сенга Аллоҳга ҳеч нарсани ширк келтирмаслик, ўғрилик қилмаслик, зино қилмаслик, болаларини ўлдирмаслик, қўллари ва оёқлари орасидан бўҳтон тўқиб келтирмаслик ва сенга яхшилик ишда исён қилмасликка байъат қилиб келсалар, уларнинг байъатини қабул қил. Ва Аллоҳдан уларнинг гуноҳини кечишни сўра. Албатта, Аллоҳ гуноҳларни кечирувчи ва меҳрибондир.",551,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تَتَوَلَّوْ[s[اْ] قَوْمًا غَضِبَ [h:13422[ٱ]للَّهُ عَلَيْهِمْ قَ[q:298[دْ] يَئِسُو[s[اْ] مِنَ [h:5583[ٱ]لْأَخِرَةِ كَمَا يَئِسَ [h:13560[ٱ]لْكُفَّارُ مِنْ أَصْحَ[n[ـٰ]بِ [h:13561[ٱ]لْقُب[p[ُو]رِ","Эй иймон келтирганлар! Аллоҳнинг ғазабига учраган қавмни дўст тутманглар. Кофирлар қабр эгаларидан умид узганларидек, улар ҳам охиратдан умид узганлар.",551,28]]},{"n":61,"ar":"الصَّفِّ","en":"As-Saff","uz":"Саф","type":"Мадина","ayahs":[["سَبَّحَ لِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۖ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Осмонлару ердаги барча нарсалар Аллоҳга тасбиҳ айтадир. У зот ғолиб ва ҳикмат эгасидир.",551,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لِمَ تَقُولُونَ مَا لَا تَفْعَل[p[ُو]نَ","Эй иймон келтирганлар! Нима учун қилмаган нарсангизни гапирасиз.",551,28],["كَبُرَ مَ[q:11151[قْ]تًا عِ[f:264[ند]َ [h:408[ٱ]للَّهِ أَ[f:1330[ن ت]َقُولُو[s[اْ] مَا لَا تَفْعَل[p[ُو]نَ","Қилмаган нарсангизни гапиришингиз Аллоҳнинг наздида қаттиқ ёмон кўрилгандир.",551,28],["إِ[g[نّ]َ [h:80[ٱ]للَّهَ يُحِبُّ [h:13562[ٱ]لَّذِينَ يُقَ[n[ـٰ]تِلُونَ فِى سَبِيلِه[n[ِۦ] صَف[f:13563[ًّا ك]َأَ[g[نّ]َه[c:13564[ُم ب]ُنْيَ[n[ـٰ][a:13565[نٌ م]َّرْص[p[ُو]صٌ","Албатта, Аллоҳ Ўз йўлида худди жипс бинодек бўлиб, сафда туриб уруш қиладиганларни яхши кўрадир.",551,28],["وَإِذْ قَالَ مُوسَىٰ لِقَوْمِه[n[ِۦ] يَ[n[ـٰ]قَوْمِ لِمَ تُؤْذُونَنِى وَقَ[d:13566[د] تَّعْلَمُونَ أَ[g[نّ]ِى رَسُولُ [h:3306[ٱ]للَّهِ إِلَيْكُمْ‌ۖ فَلَ[g[مّ]َا زَاغ[o[ُوٓ][s[اْ] أَزَاغَ [h:13567[ٱ]للَّهُ قُلُوبَهُمْ‌ۚ وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:3860[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","Мусо ўз қавмига: «Эй қавмим, Аллоҳнинг Расули эканимни билиб туриб, яна нима учун менга озор берасиз», деганини эсла. Улар бурилган эдилар Аллоҳ уларнинг қалбини буриб қўйди. Аллоҳ фосиқ қавмларни ҳидоят қилмас.",551,28],["وَإِذْ قَالَ عِيسَى [h:1916[ٱ][q:1917[بْ]نُ مَرْيَمَ يَ[n[ـٰ]بَن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ إِ[g[نّ]ِى رَسُولُ [h:3306[ٱ]للَّهِ إِلَيْك[w:13568[ُم م]ُّصَدِّ[u:206[قًا ل]ِّمَا بَيْنَ يَدَىَّ مِنَ [h:1941[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةِ وَمُبَشِّر[i:13569[َۢا ب]ِرَسُو[a:13570[لٍ ي]َأْتِى م[i:692[ِنۢ ب]َعْدِى [h:13571[ٱ]سْمُهُ[o[ۥٓ] أَحْمَدُ‌ۖ فَلَ[g[مّ]َا ج[o[َا]ٓءَه[c:13572[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ قَالُو[s[اْ] هَ[n[ـٰ]ذَا سِحْ[a:3879[رٌ م]ُّب[p[ِي]نٌ","Ийсо ибн Мариям: «Эй Бани Исроил, албатта, мен ўзимдан олдин келган Тавротни тасдиқловчи ва мендан кейин келувчи Аҳмад исмли Расулнинг башоратини берувчи, Аллоҳ сизларга юборган Пайғамбарман», деганини эсла. уларга ҳақ билан келган вақтда эса, бу очиқ-ойдин сеҳрдир, дедилар.",552,28],["وَمَنْ أَظْلَمُ مِ[g[مّ]َنِ [h:3980[ٱ]فْتَرَىٰ عَلَى [h:412[ٱ]للَّهِ [h:2035[ٱ]لْكَذِبَ وَهُوَ يُ[q:13573[دْ]عَ[o[ىٰٓ] إِلَى [h:13574[ٱ]لْإِسْلَ[n[ـٰ]مِ‌ۚ وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Исломга даъват қилиниб турганда Аллоҳга нисбатан ёлғон тўқиган кимсадан ҳам золимроқ киши борми? Ҳолбуки. Аллоҳ золимларни ҳидоятга солмас.",552,28],["يُرِيدُونَ لِيُ[q:13575[طْ]فِــُٔو[s[اْ] نُورَ [h:5554[ٱ]للَّهِ بِأَفْو[n[َٲ]هِهِمْ وَ[h:72[ٱ]للَّهُ مُتِ[g[مّ]ُ نُورِه[n[ِۦ] وَلَوْ كَرِهَ [h:5556[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Оғизлари билан Аллоҳнинг нурини ўчирмоқчи бўлурлар. Ҳолбуки, Аллоҳ, кофирлар ёқтирмаса ҳам, Ўз нурини тугал этгувчидир.",552,28],["هُوَ [h:153[ٱ]لَّذ[o[ِىٓ] أَرْسَلَ رَسُولَهُ[n[ۥ] بِ[h:54[ٱ]لْهُدَىٰ وَدِينِ [h:5557[ٱ]لْحَقِّ لِيُظْهِرَهُ[n[ۥ] عَلَى [h:5558[ٱ][l[ل]دِّينِ كُلِّه[n[ِۦ] وَلَوْ كَرِهَ [h:5559[ٱ]لْمُشْرِك[p[ُو]نَ","У зот, Ўз Расулини ҳидоят ва ҳақ дин билан барча динлардан устун қилиш учун юборган зотдир. Гарчи мушриклар ёқтирмасалар ҳам.",552,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] هَلْ أَدُلُّكُمْ عَلَىٰ تِجَ[n[ـٰ]رَ[f:13576[ةٍ ت]ُ[f:13577[نج]ِيك[w:13578[ُم م]ِّنْ عَذَابٍ أَل[p[ِي]مٍ","Эй иймон келтирганлар! Сизларни аламли азобдан нажот топтирувчи тижоратга далолат қилайми?",552,28],["تُؤْمِنُونَ بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] وَتُجَ[n[ـٰ]هِدُونَ فِى سَبِيلِ [h:788[ٱ]للَّهِ بِأَمْو[n[َٲ]لِكُمْ وَأَ[f:2485[نف]ُسِكُمْ‌ۚ ذ[n[َٲ]لِكُمْ خَيْ[u:263[رٌ ل]َّكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","Аллоҳга ва Унинг Расулига иймон келтирасизлар ҳамда Унинг йўлида молингиз ва жонингиз билан жиҳод қиласизлар. Шундоқ қилмоқларингиз, агар билсангизлар, ўзларингиз учун яхшидир.",552,28],["يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُ[q:13579[دْ]خِلْكُمْ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ وَمَسَ[n[ـٰ]كِنَ طَيِّبَ[f:5719[ةً ف]ِى جَ[g[نّ]َ[n[ـٰ]تِ عَ[q:5720[دْ][f:13580[نٍ‌ۚ ذ][n[َٲ]لِكَ [h:3911[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","Ана шунда, У зот гуноҳларингизни кечирур ва сизларни адн жаннатидаги остидан анҳорлар оқиб турган боғларга ва яхши масканларга киритур. Бу улуғ ютуқдир.",552,28],["وَأُخْرَىٰ تُحِبُّونَهَا‌ۖ نَصْ[a:13581[رٌ م]ِّنَ [h:321[ٱ]للَّهِ وَفَتْ[f:13582[حٌ ق]َرِي[a:13583[بٌ‌ۗ و]َبَشِّرِ [h:1257[ٱ]لْمُؤْمِن[p[ِي]نَ","Ва сизлар яхши кўрадиган бошқаси ҳам бор. Аллоҳдан ёрдам ва яқин зафар. Ва мўминларга башорат бер.",552,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] كُون[o[ُوٓ][s[اْ] أَ[f:13584[نص]َارَ [h:13585[ٱ]للَّهِ كَمَا قَالَ عِيسَى [h:1916[ٱ][q:1917[بْ]نُ مَرْيَمَ لِلْحَوَارِيِّـ[n[ـۧ]نَ مَنْ أَ[f:1949[نص]َار[o[ِىٓ] إِلَى [h:1637[ٱ]للَّهِ‌ۖ قَالَ [h:1950[ٱ]لْحَوَارِيُّونَ نَحْنُ أَ[f:1951[نص]َارُ [h:1952[ٱ]للَّهِ‌ۖ فَـَٔـامَنَ[d:13586[ت] طّ[o[َا]ٓئِفَ[a:2015[ةٌ م]ّ[i:1385[ِنۢ ب]َن[o[ِىٓ] إِسْر[o[َٲ]ٓءِيلَ وَكَفَرَ[d:13587[ت] طّ[o[َا]ٓئِفَ[f:13588[ةٌ‌ۖ ف]َأَيَّ[q:13589[دْ]نَا [h:13590[ٱ]لَّذِينَ ءَامَنُو[s[اْ] عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُو[s[اْ] ظَ[n[ـٰ]هِر[p[ِي]نَ","Эй иймон келтирганлар! Аллоҳнинг ёрдамчилари бўлинг! Худди Ийсо ибн Марям ҳаворийларга: «Ким Аллоҳ учун менинг ёрдамчим» деганида, ҳаворийлар: «Биз Аллоҳнинг ёрдамчиларимиз», деганларидек. Бас, Бани Исроилдан бир тоифа иймон келтирди ва бир тоифа кофир бўлди. Бас, Биз иймон келтирганларни душманлари устидан қўллаб-қувватладик. Ва улар ғолиб бўлдилар.",552,28]]},{"n":62,"ar":"الجُمُعَةِ","en":"Al-Jumu'a","uz":"Жумъа","type":"Мадина","ayahs":[["يُسَبِّحُ لِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ [h:13591[ٱ]لْمَلِكِ [h:13592[ٱ]لْقُدُّوسِ [h:13593[ٱ]لْعَزِيزِ [h:2229[ٱ]لْحَك[p[ِي]مِ","Осмонлару ердаги барча нарсалар Хожа, Бенуқсон, Азиз, Ҳаким Аллоҳга тасбиҳ айтадир.",553,28],["هُوَ [h:153[ٱ]لَّذِى بَعَثَ فِى [h:2033[ٱ]لْأُ[g[مّ]ِيِّـ[n[ـۧ]نَ رَسُول[a:677[اً م]ِّنْهُمْ يَتْلُو[s[اْ] عَلَيْهِمْ ءَايَ[n[ـٰ]تِه[n[ِۦ] وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ [h:678[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:679[ٱ]لْحِكْمَةَ وَإِ[f:2392[ن ك]َانُو[s[اْ] مِ[f:128[ن ق]َ[q:129[بْ]لُ لَفِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","У зот саводсизлар ичидан, гарчи улар бундан аввал очиқ залолатда бўлсалар ҳам, уларга оятларини ўқиб берадиган ва уларни поклайдиган ҳамда китобни ва ҳикматни ўргатадиган Пайғамбарни юборди.",553,28],["وَءَاخَرِينَ مِنْهُمْ لَ[g[مّ]َا يَلْحَقُو[s[اْ] بِهِمْ‌ۚ وَهُوَ [h:7045[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","Ва ҳозирча уларга қўшилмаган бошқаларга ҳам. Ва У зот ғолиб ва ҳикмат эгасидир.",553,28],["ذ[n[َٲ]لِكَ فَضْلُ [h:337[ٱ]للَّهِ يُؤْتِيهِ م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَ[h:72[ٱ]للَّهُ ذُو [h:550[ٱ]لْفَضْلِ [h:551[ٱ]لْعَظ[p[ِي]مِ","Бу Аллоҳнинг фазлидир хоҳлаган кишисига берадир. Аллоҳ улуғ фазл эгасидир.",553,28],["مَثَلُ [h:1179[ٱ]لَّذِينَ حُ[g[مّ]ِلُو[s[اْ] [h:13594[ٱ][l[ل]تَّوْرَ[n[ٮٰ]ةَ ثُ[g[مّ]َ لَمْ يَحْمِلُوهَا كَمَثَلِ [h:13595[ٱ]لْحِمَارِ يَحْمِلُ أَسْفَار[i:13596[َۢا‌ۚ ب]ِئْسَ مَثَلُ [h:5140[ٱ]لْقَوْمِ [h:4053[ٱ]لَّذِينَ كَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِ [h:322[ٱ]للَّهِ‌ۚ وَ[h:72[ٱ]للَّهُ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:1505[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Устларига Таврот юклатилган, сўнгра уни кўтармаганлар мисоли устига китоб юкланган эшакка ўхшарлар. Аллоҳнинг оятларини ёлғонга чиқарган қавмнинг мисоли қандоқ ҳам ёмон. Аллоҳ золим қавмларни ҳидоят қилмас.",553,28],["قُلْ يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ هَاد[o[ُوٓ][s[اْ] إِ[f:13597[ن ز]َعَمْتُمْ أَ[g[نّ]َكُمْ أَوْلِي[o[َا]ٓءُ لِلَّهِ مِ[f:107[ن د]ُونِ [h:493[ٱ][l[ل][g[نّ]َاسِ فَتَمَ[g[نّ]َوُ[s[اْ] [h:494[ٱ]لْمَوْتَ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Сен: «Эй яҳудийлар, албатта сиз, бошқалардан фарқли ўлароқ, Аллоҳнинг авлиёларимиз, деб даъво қиладиган бўлсангиз, бас, ўлимни орзу қилинг, агар ростгўй бўлсангиз», деб айт.",553,28],["وَلَا يَتَمَ[g[نّ]َوْنَهُ[o[ۥٓ] أَبَد[i:496[َۢا ب]ِمَا قَدَّمَتْ أَيْدِيهِمْ‌ۚ وَ[h:72[ٱ]للَّهُ عَلِي[i:497[مُۢ ب]ِ[h:498[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Улар қўллари қилганлари туфайли ҳеч қачон, уни орзу қилмаслар. Аллоҳ золимларни билувчидир.",553,28],["قُلْ إِ[g[نّ]َ [h:13598[ٱ]لْمَوْتَ [h:13599[ٱ]لَّذِى تَفِرُّونَ مِنْهُ فَإِ[g[نّ]َهُ[n[ۥ] مُلَ[n[ـٰ]قِيكُمْ‌ۖ ثُ[g[مّ]َ تُرَدُّونَ إِلَىٰ عَ[n[ـٰ]لِمِ [h:5788[ٱ]لْغَيْبِ وَ[h:4187[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ فَيُنَبِّئُك[c:3605[ُم ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Сен: «Албатта, сиз ундан қочаётган ўлим, таъкид шулки, сизга барибир йўлиқувчидир. Сўнгра махфий ва ошкор нарсаларни Билувчининг ҳузурига қайтарилурсизлар. Бас, У сизга нима қилиб юрганингизнинг хабарини берадир.",553,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِذَا نُودِىَ لِلصَّلَ[s[و][n[ٲ]ةِ م[a:13600[ِن ي]َوْمِ [h:13601[ٱ]لْجُمُعَةِ فَ[h:13602[ٱ]سْعَوْ[s[اْ] إِلَىٰ ذِكْرِ [h:3774[ٱ]للَّهِ وَذَرُو[s[اْ] [h:13603[ٱ]لْبَيْعَ‌ۚ ذ[n[َٲ]لِكُمْ خَيْ[u:263[رٌ ل]َّكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","Эй иймон келтирганлар! Жума куни намозга нидо қилинганда, Аллоҳнинг зикрига шошилинг ва савдони қўйинг. Агар билсангиз, бу ўзингиз учун яхшидир.",554,28],["فَإِذَا قُضِيَتِ [h:13604[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةُ فَ[h:10874[ٱ][f:10874[نت]َشِرُو[s[اْ] فِى [h:44[ٱ]لْأَرْضِ وَ[h:988[ٱ][q:988[بْ]تَغُو[s[اْ] مِ[f:6655[ن ف]َضْلِ [h:6656[ٱ]للَّهِ وَ[h:335[ٱ]ذْكُرُو[s[اْ] [h:1113[ٱ]للَّهَ كَثِي[u:5368[رًا ل]َّعَلَّكُمْ تُفْلِح[p[ُو]نَ","Бас, намоз тугагандан сўнг ер юзи бўйлаб тарқалинг ва Аллоҳнинг фазлидан талаб қилинг ва Аллоҳни кўп эсланг, шоядки ютуққа эришсангиз.",554,28],["وَإِذَا رَأَوْ[s[اْ] تِجَ[n[ـٰ]رَةً أَوْ لَهْوًا [h:13605[ٱ][f:13606[نف]َضّ[o[ُوٓ][s[اْ] إِلَيْهَا وَتَرَكُوكَ ق[o[َا]ٓئِ[f:13607[مًا‌ۚ ق]ُلْ مَا عِ[f:264[ند]َ [h:408[ٱ]للَّهِ خَيْ[a:13608[رٌ م]ِّنَ [h:13609[ٱ][l[ل]لَّهْوِ وَمِنَ [h:13610[ٱ][l[ل]تِّجَ[n[ـٰ]رَةِ‌ۚ وَ[h:72[ٱ]للَّهُ خَيْرُ [h:3894[ٱ][l[ل]رّ[n[َٲ]زِق[p[ِي]نَ","Ва улар тижорат ёки ўйин-кулгу кўрганларида, унга томон ёпирилдилар ва сени тик ҳолда тарк этдилар. Сен: «Аллоҳнинг ҳузуридаги нарса ўйин-кулгудан ва тижоратдан яхшидир. Ва Аллоҳ энг яхши ризқ берувчидир», деб айт.",554,28]]},{"n":63,"ar":"المُنَافِقُونَ","en":"Al-Munaafiqoon","uz":"Мунофиқун","type":"Мадина","ayahs":[["إِذَا ج[o[َا]ٓءَكَ [h:13611[ٱ]لْمُنَ[n[ـٰ]فِقُونَ قَالُو[s[اْ] نَشْهَدُ إِ[g[نّ]َكَ لَرَسُولُ [h:13612[ٱ]للَّهِ‌ۗ وَ[h:72[ٱ]للَّهُ يَعْلَمُ إِ[g[نّ]َكَ لَرَسُولُهُ[n[ۥ] وَ[h:72[ٱ]للَّهُ يَشْهَدُ إِ[g[نّ]َ [h:3224[ٱ]لْمُنَ[n[ـٰ]فِقِينَ لَكَ[n[ـٰ]ذِب[p[ُو]نَ","Мунофиқлар ҳузурингга келганларида, гувоҳлик берамизки, сен, албатта, Аллоҳнинг Расулисан, дерлар. Ҳолбуки, Аллоҳ албатта сен Унинг Расули эканингни биладир. Ва Аллоҳ гувоҳли берурки, албатта, мунофиқлар ёлғончидирлар.",554,28],["ٱتَّخَذ[o[ُوٓ][s[اْ] أَيْمَ[n[ـٰ]نَهُمْ جُ[g[نّ]َ[f:13424[ةً ف]َصَدُّو[s[اْ] عَ[f:1203[ن س]َبِيلِ [h:788[ٱ]للَّهِ‌ۚ إِ[g[نّ]َهُمْ س[o[َا]ٓءَ مَا كَانُو[s[اْ] يَعْمَل[p[ُو]نَ","Улар қасамларини қалқон қилиб олдилар ва Аллоҳнинг йўлидан бурдилар. Бас, албатта, уларнинг қилган ишлари ёмон бўлди!",554,28],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُمْ ءَامَنُو[s[اْ] ثُ[g[مّ]َ كَفَرُو[s[اْ] فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَه[p[ُو]نَ","Бунга сабаб шуки, улар иймон келтирдилар, сўнг кофир бўлдилар, бас, қалбларига муҳр босилди. Энди улар фаҳмламаслар.",554,28],["۞ وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَ[q:13613[جْ]سَامُهُمْ‌ۖ وَإ[a:13614[ِن ي]َقُولُو[s[اْ] تَسْمَعْ لِقَوْلِهِمْ‌ۖ كَأَ[g[نّ]َهُمْ خُشُ[a:13615[بٌ م]ُّسَ[g[نّ]َدَ[a:13616[ةٌ‌ۖ ي]َحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ‌ۚ هُمُ [h:13617[ٱ]لْعَدُوُّ فَ[h:13618[ٱ]حْذَرْهُمْ‌ۚ قَ[n[ـٰ]تَلَهُمُ [h:5548[ٱ]للَّهُ‌ۖ أَ[g[نّ]َىٰ يُؤْفَك[p[ُو]نَ","Ва агар уларни кўрсанг, жисмлари сени ажаблантирур ва агар гапирсалар, гапларига қулоқ осурсан. Улар худди суяб қуйилган ходага ўхшарлар. Ҳар қичқириқни зиддиларига ҳисоблайдилар. Улар душмандирлар. Улардан ҳазир бўл. Аллоҳ уларга уруш очсин, ҳақдан қандоқ ўгирилурлар.",554,28],["وَإِذَا قِيلَ لَهُمْ تَعَالَوْ[s[اْ] يَسْتَغْفِرْ لَكُمْ رَسُولُ [h:3306[ٱ]للَّهِ لَوَّوْ[s[اْ] رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَه[w:7366[ُم م]ُّسْتَكْبِر[p[ُو]نَ","Ва агар уларга: «Келинглар, Аллоҳнинг Расули сизларга истиғфор айтадир», дейилса, улар бошларини чайқарлар. Ва уларни мутакаббирлик ҳолида юз ўгираётганларини кўрарсан.",555,28],["سَو[o[َا]ٓءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ ل[a:13619[َن ي]َغْفِرَ [h:5741[ٱ]للَّهُ لَهُمْ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ لَا يَهْدِى [h:1504[ٱ]لْقَوْمَ [h:3860[ٱ]لْفَ[n[ـٰ]سِق[p[ِي]نَ","Уларга истиғфор айтасанми ёки айтмайсанми-улар учун бари бир. Аллоҳ уларни ҳеч мағфират қилмас. Зеро, Аллоҳ фосиқ қавмларни ҳидоятга бошламас.",555,28],["هُمُ [h:12679[ٱ]لَّذِينَ يَقُولُونَ لَا تُ[f:1607[نف]ِقُو[s[اْ] عَلَىٰ مَنْ عِ[f:264[ند]َ رَسُولِ [h:5744[ٱ]للَّهِ حَتَّىٰ يَ[f:13620[نف]َضُّو[s[اْ‌ۗ] وَلِلَّهِ خَز[o[َا]ٓئِنُ [h:13621[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:13622[ٱ]لْمُنَ[n[ـٰ]فِقِينَ لَا يَفْقَه[p[ُو]نَ","Улар, Расулуллоҳнинг ҳузуридагиларга нафақа берманглар, токи тарқаб кетсинлар, дерлар. Ҳолбуки, осмонлару ернинг хазиналари Аллоҳникидир. Ва лекин мунофиқлар тушунмаслар.",555,28],["يَقُولُونَ لَئ[u:13623[ِن ر]َّجَعْن[o[َآ] إِلَى [h:8006[ٱ]لْمَدِينَةِ لَيُخْرِجَ[g[نّ]َ [h:13624[ٱ]لْأَعَزُّ مِنْهَا [h:13625[ٱ]لْأَذَلَّ‌ۚ وَلِلَّهِ [h:13626[ٱ]لْعِزَّةُ وَلِرَسُولِه[n[ِۦ] وَلِلْمُؤْمِنِينَ وَلَ[n[ـٰ]كِ[g[نّ]َ [h:13622[ٱ]لْمُنَ[n[ـٰ]فِقِينَ لَا يَعْلَم[p[ُو]نَ","Улар, агар Мадинага қайтиб борсак, албатта азиз хорни ундан чиқарур, дерлар. Ҳолбуки, азизлик Аллоҳга, Унинг Расулига ва мўминларига хосдир. Лекин мунофиқлар билмаслар.",555,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] لَا تُلْهِكُمْ أَمْو[n[َٲ]لُكُمْ وَل[o[َآ] أَوْلَ[n[ـٰ]دُكُمْ عَ[f:3773[ن ذ]ِكْرِ [h:3774[ٱ]للَّهِ‌ۚ وَم[a:1297[َن ي]َفْعَلْ ذ[n[َٲ]لِكَ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:150[ٱ]لْخَ[n[ـٰ]سِر[p[ُو]نَ","Эй иймон келтирганлар. Молларингиз ва болаларингиз сизни Аллоҳнинг зикридан чалғитмасин. Ким шундай қилса, бас, ана ўшалар ютқазувчилардир.",555,28],["وَأَ[f:1045[نف]ِقُو[s[اْ] م[a:10464[ِن م]َّا رَزَ[q:275[قْ]نَ[n[ـٰ]ك[w:1461[ُم م]ِّ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:1462[َن ي]َأْتِىَ أَحَدَكُمُ [h:942[ٱ]لْمَوْتُ فَيَقُولَ رَبِّ لَوْل[o[َآ] أَخَّرْتَن[o[ِىٓ] إِلَ[o[ىٰٓ] أَجَ[f:2940[لٍ ق]َرِي[f:13627[بٍ ف]َأَصَّدَّقَ وَأَك[a:6642[ُن م]ِّنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Ва бирингизга ўлим келиб: «Эй Роббим, агар менинг ўлимимни яқин муддатга орқага сурсанг, бас, садақа қилиб солиҳлардан бўлсам», демасдан аввал Биз сизларга ризқ қилиб берган нарсалардан нафақа қилинг.",555,28],["وَل[a:13628[َن ي]ُؤَخِّرَ [h:13629[ٱ]للَّهُ نَفْسًا إِذَا ج[o[َا]ٓءَ أَجَلُهَا‌ۚ وَ[h:72[ٱ]للَّهُ خَبِي[i:2335[رُۢ ب]ِمَا تَعْمَل[p[ُو]نَ","Аллоҳ ажали келган жонни ҳеч-ҳеч орқага сурмас. Зеро, Аллоҳ нима қилаётганингиздан хабардордир.",555,28]]},{"n":64,"ar":"التَّغَابُنِ","en":"At-Taghaabun","uz":"Тағобун","type":"Мадина","ayahs":[["يُسَبِّحُ لِلَّهِ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَمَا فِى [h:44[ٱ]لْأَرْضِ‌ۖ لَهُ [h:1397[ٱ]لْمُلْكُ وَلَهُ [h:10443[ٱ]لْحَمْدُ‌ۖ وَهُوَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Осмонлардаги нарсалар ва ердаги нарсалар Аллоҳга тасбиҳ айтурлар. Мулк Унга хосдир, мақтов ҳам Унга хосдир ва У барча нарсага қодирдир.",556,28],["هُوَ [h:153[ٱ]لَّذِى خَلَقَكُمْ فَمِ[f:12615[نك]ُمْ كَافِ[a:13630[رٌ و]َمِ[f:2325[نك][w:13631[ُم م]ُّؤْمِ[a:13632[نٌ‌ۚ و]َ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ بَص[p[ِي]رٌ","У сизларни яратган зотдир. Бас, баъзиларингиз кофир ва баъзиларингиз мўминдир. Аллоҳ нима қилаётганингизни кўриб турувчидир.",556,28],["خَلَقَ [h:3913[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:1474[ٱ]لْأَرْضَ بِ[h:370[ٱ]لْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ‌ۖ وَإِلَيْهِ [h:3461[ٱ]لْمَص[p[ِي]رُ","У осмонлару ерни ҳақ билан яратди. Ва қиёфангизни чиройли сувратда қилди. Ва қайтиб бориш Унинг Ўзигадир.",556,28],["يَعْلَمُ مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ‌ۚ وَ[h:72[ٱ]للَّهُ عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","У осмонлару ердаги нарсаларни биладир. Сизлар сир тутаётган нарсани ҳам ва эълон қилаётган нарсани ҳам биладир. Аллоҳ кўкракдаги нарсаларни ҳам билувчидир.",556,28],["أَلَمْ يَأْتِكُمْ نَبَؤُ[s[اْ] [h:7058[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِ[f:128[ن ق]َ[q:129[بْ]لُ فَذَاقُو[s[اْ] وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Сизларга олдин кофир бўлганларнинг хабари келмадими? Бас, улар ўз ишларининг азобини татидилар ва уларга аламли азоблар бор.",556,28],["ذ[n[َٲ]لِكَ بِأَ[g[نّ]َهُ[n[ۥ] كَانَت تَّأْتِيهِمْ رُسُلُه[c:4900[ُم ب]ِ[h:484[ٱ]لْبَيِّنَ[n[ـٰ]تِ فَقَال[o[ُوٓ][s[اْ] أَبَشَ[a:13633[رٌ ي]َهْدُونَنَا فَكَفَرُو[s[اْ] وَتَوَلَّو[s[اْ‌ۚ] وَّ[h:13634[ٱ]سْتَغْنَى [h:13635[ٱ]للَّهُ‌ۚ وَ[h:72[ٱ]للَّهُ غَنِىٌّ حَم[p[ِي][q[د]ٌ","Бунинг боиси шундаки, уларга Пайғамбарлари ойдин далиллар билан келардилар, улар бўлса, бизни башар ҳидоятга бошлайдими, деб куфрга кетардилар ва юз ўгирардилар. Ва Аллоҳ беҳожат бўлди. Аллоҳ беҳожат ва мақталгандир.",556,28],["زَعَمَ [h:13636[ٱ]لَّذِينَ كَفَر[o[ُوٓ][s[اْ] أ[u:8842[َن ل]ّ[a:13637[َن ي]ُ[q:13638[بْ]عَثُو[s[اْ‌ۚ] قُلْ بَلَىٰ وَرَبِّى لَتُ[q:13639[بْ]عَثُ[g[نّ]َ ثُ[g[مّ]َ لَتُنَبَّؤُ[g[نّ]َ بِمَا عَمِلْتُمْ‌ۚ وَذ[n[َٲ]لِكَ عَلَى [h:412[ٱ]للَّهِ يَس[p[ِي]رٌ","Кофирлар ҳеч қайта тирилмасликларини даъво қилдилар. Сен: «Ундоқ эмас, Роббим билан қасамки, албатта қайта тирилтирилурсизлар, сўнгра қилган ишларингиздан хабардор қилинурсизлар. Бу иш Аллоҳ учун осондир», деб айт.",556,28],["فَـَٔـامِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ وَرَسُولِه[n[ِۦ] وَ[h:13640[ٱ][l[ل][g[نّ]ُورِ [h:13641[ٱ]لَّذ[o[ِىٓ] أَ[f:515[نز]َلْنَا‌ۚ وَ[h:72[ٱ]للَّهُ بِمَا تَعْمَلُونَ خَب[p[ِي]رٌ","Бас, Аллоҳга, Унинг Расулига ва Биз туширган нурга иймон келтиринглар. Аллоҳ нима қилаётганингиздан хабардордир.",556,28],["يَوْمَ يَ[q:12425[جْ]مَعُكُمْ لِيَوْمِ [h:13642[ٱ]لْجَمْعِ‌ۖ ذ[n[َٲ]لِكَ يَوْمُ [h:13643[ٱ][l[ل]تَّغَابُنِ‌ۗ وَم[a:13644[َن ي]ُؤْم[i:12652[ِنۢ ب]ِ[h:32[ٱ]للَّهِ وَيَعْمَلْ صَ[n[ـٰ]لِ[a:13645[حًا ي]ُكَفِّرْ عَنْهُ سَيِّـَٔـاتِه[n[ِۦ] وَيُ[q:13646[دْ]خِلْهُ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَ[f:5811[دًا‌ۚ ذ][n[َٲ]لِكَ [h:3911[ٱ]لْفَوْزُ [h:2633[ٱ]لْعَظ[p[ِي]مُ","У сизларни «Жамлаш куни»га тўплайдиган кунни эсланг. У кун «тағобун» кунидир. Ким Аллоҳга иймон келтирса ва солиҳ амаллар қилса, унинг гуноҳларини кечирур ва остидан анҳорлар оқиб турган жаннатларга киритур. Унда абадул-абад қолурлар. Бу улкан ютуқдир.",556,28],["وَ[h:9999[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَكَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِن[o[َآ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:201[ٱ][l[ل][g[نّ]َارِ خَ[n[ـٰ]لِدِينَ فِيهَا‌ۖ وَبِئْسَ [h:665[ٱ]لْمَص[p[ِي]رُ","Куфр келтириб, Бизнинг оятларимизни ёлғонга чиқарганлар, ана ўшалар, оташ эгаларидир. Унда абадий қолурлар. Қандоқ ҳам ёмон жой у!",557,28],["م[o[َآ] أَصَابَ م[a:12140[ِن م]ُّصِيبَةٍ إِلَّا بِإِذْنِ [h:509[ٱ]للَّهِ‌ۗ وَم[a:13644[َن ي]ُؤْم[i:12652[ِنۢ ب]ِ[h:32[ٱ]للَّهِ يَهْدِ قَلْبَهُ[n[ۥ]‌ۚ وَ[h:72[ٱ]للَّهُ بِكُلِّ شَىْءٍ عَل[p[ِي]مٌ","Сизга Аллоҳнинг изнисиз ҳеч бир мусибат етмас. Ким Аллоҳга иймон келтирса, У зот унинг қалбини ҳидоятга солур. Аллоҳ ҳар бир нарсани билувчидир.",557,28],["وَأَطِيعُو[s[اْ] [h:2238[ٱ]للَّهَ وَأَطِيعُو[s[اْ] [h:2865[ٱ][l[ل]رَّسُولَ‌ۚ فَإِ[f:3779[ن ت]َوَلَّيْتُمْ فَإِ[g[نّ]َمَا عَلَىٰ رَسُولِنَا [h:3780[ٱ]لْبَلَ[n[ـٰ]غُ [h:3781[ٱ]لْمُب[p[ِي]نُ","Аллоҳга итоат қилинг ва ҳамда Расулга итоат қилинг. Агар юз ўгириб кетсангиз, бас, Бизнинг Расулимизга очиқ-ойдин етказиш, холос.",557,28],["ٱللَّهُ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ‌ۚ وَعَلَى [h:2207[ٱ]للَّهِ فَلْيَتَوَكَّلِ [h:2208[ٱ]لْمُؤْمِن[p[ُو]نَ","Аллоҳ, Ундан ўзга ибодатга сазовор зот йўқ. Бас, мўминлар Аллоҳнинг Ўзигагина таваккал қилсинлар.",557,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِ[g[نّ]َ مِنْ أَزْو[n[َٲ]جِكُمْ وَأَوْلَ[n[ـٰ]دِكُمْ عَدُو[u:13647[ًّا ل]َّكُمْ فَ[h:13648[ٱ]حْذَرُوهُمْ‌ۚ وَإِ[f:13649[ن ت]َعْفُو[s[اْ] وَتَصْفَحُو[s[اْ] وَتَغْفِرُو[s[اْ] فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Эй иймон келтирганлар! Албатта, жуфтларингиздан ва болаларингиздан сизга душман бор, бас, улардан ҳазир бўлинг. Ва агар афв этсангиз, кўнгилга олмасангиз ва айбларини кечирсангиз, бас, албатта, Аллоҳ кечирувчи ва раҳмдил зотдир.",557,28],["إِ[g[نّ]َم[o[َآ] أَمْو[n[َٲ]لُكُمْ وَأَوْلَ[n[ـٰ]دُكُمْ فِتْنَ[a:13650[ةٌ‌ۚ و]َ[h:72[ٱ]للَّهُ عِ[f:719[ند]َهُ[o[ۥٓ] أَ[q:2423[جْ]رٌ عَظ[p[ِي]مٌ","Албатта, мол-мулкларингиз ва фарзандларингиз синовдан бошқа нарса эмас. Ва Аллоҳнинг ҳузурида улуғ ажр бор.",557,28],["فَ[h:9999[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ مَا [h:5393[ٱ]سْتَطَعْتُمْ وَ[h:486[ٱ]سْمَعُو[s[اْ] وَأَطِيعُو[s[اْ] وَأَ[f:1045[نف]ِقُو[s[اْ] خَيْ[u:13651[رًا ل]ِّأَ[f:13652[نف]ُسِكُمْ‌ۗ وَم[a:13470[َن ي]ُوقَ شُحَّ نَفْسِه[n[ِۦ] فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:23[ٱ]لْمُفْلِح[p[ُو]نَ","Аллоҳга қўлингиздан келганича тақво қилинг ва тингланг ва итоат қилинг ва инфоқ қилинг - ўзингизга яхши бўлади. Ва кимки нафсининг қизғанчиқлигидан сақланса, ана ўшалар нажот топувчилардир.",557,28],["إِ[f:13653[ن ت]ُ[q:13654[قْ]رِضُو[s[اْ] [h:13655[ٱ]للَّهَ قَرْضًا حَسَ[a:13656[نًا ي]ُضَ[n[ـٰ]عِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ‌ۚ وَ[h:72[ٱ]للَّهُ شَكُورٌ حَل[p[ِي]مٌ","Агар Аллоҳга яхши қарз берсангиз, У сизга кўпайтириб берур ва сизни кечирур. Аллоҳ шакур ва ҳалимдир.",557,28],["عَ[n[ـٰ]لِمُ [h:4186[ٱ]لْغَيْبِ وَ[h:4187[ٱ][l[ل]شَّهَ[n[ـٰ]دَةِ [h:10627[ٱ]لْعَزِيزُ [h:681[ٱ]لْحَك[p[ِي]مُ","У ғойиб ва ошкорни билувчи, азиз ва ҳаким зотдир.",557,28]]},{"n":65,"ar":"الطَّلَاقِ","en":"At-Talaaq","uz":"Талоқ","type":"Мадина","ayahs":[["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ إِذَا طَلَّ[q:1293[قْ]تُمُ [h:1294[ٱ][l[ل][g[نّ]ِس[o[َا]ٓءَ فَطَلِّقُوهُ[g[نّ]َ لِعِدَّتِهِ[g[نّ]َ وَأَحْصُو[s[اْ] [h:13657[ٱ]لْعِدَّةَ‌ۖ وَ[h:1018[ٱ]تَّقُو[s[اْ] [h:1019[ٱ]للَّهَ رَبَّكُمْ‌ۖ لَا تُخْرِجُوهُ[g[نّ]َ م[i:13658[ِنۢ ب]ُيُوتِهِ[g[نّ]َ وَلَا يَخْرُ[q:13659[جْ]نَ إِلّ[o[َآ] أ[a:2664[َن ي]َأْتِينَ بِفَ[n[ـٰ]حِشَ[a:2665[ةٍ م]ُّبَيِّنَ[a:13660[ةٍ‌ۚ و]َتِلْكَ حُدُودُ [h:1000[ٱ]للَّهِ‌ۚ وَم[a:1284[َن ي]َتَعَدَّ حُدُودَ [h:1282[ٱ]للَّهِ فَقَ[q:563[دْ] ظَلَمَ نَفْسَهُ[n[ۥ]‌ۚ لَا تَ[q:10618[دْ]رِى لَعَلَّ [h:13661[ٱ]للَّهَ يُحْدِثُ بَعْدَ ذ[n[َٲ]لِكَ أَمْرًا","Эй Набий! Агар аёлларни талоқ қиладиган бўлсангиз, иддалари учун қилинг ва иддани ҳисобланг ва Алоҳга тақво қилинг. Уларни уйларидан чиқарманглар ва ўзлари ҳам чиқмасинлар, илло, очиқ-ойдин фоҳиша иш қилган бўлсалар. Ва ана шу нарсалар Аллоҳнинг чегараларидир. Ким Аллоҳнинг чегарасидан чиқса, ҳақиқатда ўзи ўзига зулм қилибди. Сен билмайссан, шоядки Аллоҳ ундан кейин бирор ишни пайдо қилса.",558,28],["فَإِذَا بَلَغْنَ أَجَلَهُ[g[نّ]َ فَأَمْسِكُوهُ[g[نّ]َ بِمَعْرُوفٍ أَوْ فَارِقُوهُ[g[نّ]َ بِمَعْرُو[a:13662[فٍ و]َأَشْهِدُو[s[اْ] ذَوَىْ عَ[q:3797[دْ][a:3798[لٍ م]ِّ[f:344[نك]ُمْ وَأَقِيمُو[s[اْ] [h:13663[ٱ][l[ل]شَّهَ[n[ـٰ]دَةَ لِلَّهِ‌ۚ ذ[n[َٲ]لِكُمْ يُوعَظُ بِه[n[ِۦ] مَ[f:506[ن ك]َانَ يُؤْمِنُ بِ[h:32[ٱ]للَّهِ وَ[h:328[ٱ]لْيَوْمِ [h:329[ٱ]لْأَخِرِ‌ۚ وَم[a:13664[َن ي]َتَّقِ [h:13665[ٱ]للَّهَ يَ[q:4397[جْ]عَل لَّهُ[n[ۥ] مَخْرَجًا","Бас, улар муддатларига етсалар, яхшилик билан ушланглар, ёки яхшилик билан ажралинглар ва сиздан икки адолатли кишини гувоҳ қилинглар. Ва гувоҳликни Аллоҳ учун қилинглар. Бу ишингиздан кимнинг Аллоҳга ва қиёмат кунига иймони бўлса, ваъзланади. Ким Аллоҳга тақво қилса, У зот унинг йўлини очиб қўюр.",558,28],["وَيَرْزُ[q:13666[قْ]هُ مِنْ حَيْثُ لَا يَحْتَسِبُ‌ۚ وَم[a:5377[َن ي]َتَوَكَّلْ عَلَى [h:412[ٱ]للَّهِ فَهُوَ حَسْبُهُ[o[ۥٓ‌ۚ] إِ[g[نّ]َ [h:80[ٱ]للَّهَ بَ[n[ـٰ]لِغُ أَمْرِه[n[ِۦ]‌ۚ قَ[q:298[دْ] جَعَلَ [h:2556[ٱ]للَّهُ لِكُلِّ ش[f:13667[َىْءٍ ق]َ[q:13668[دْ]رًا","Ва унга ўзи ўйламаган тарафдан ризқ берур. Ким Аллоҳга таваккал қилса, бас, унга У зотнинг Ўзи кифоядир. Албатта, Аллоҳ Ўз ишини етказувчидир. Ҳақиқатда, Аллоҳ ҳар бир нарсага ўлчов қилиб қўйган.",558,28],["وَ[h:9999[ٱ]لَّ[o[ــٰٓ]ــِٔى يَئِسْنَ مِنَ [h:13669[ٱ]لْمَحِيضِ م[a:2638[ِن ن]ِّس[o[َا]ٓئِكُمْ إِنِ [h:3844[ٱ]رْتَ[q:3845[بْ]تُمْ فَعِدَّتُهُ[g[نّ]َ ثَلَ[n[ـٰ]ثَةُ أَشْهُ[a:13670[رٍ و]َ[h:13671[ٱ]لَّ[o[ــٰٓ]ــِٔى لَمْ يَحِضْنَ‌ۚ وَأُ[s[وْ]لَ[n[ـٰ]تُ [h:13672[ٱ]لْأَحْمَالِ أَجَلُهُ[g[نّ]َ أ[a:9527[َن ي]َضَعْنَ حَمْلَهُ[g[نّ]َ‌ۚ وَم[a:13664[َن ي]َتَّقِ [h:13665[ٱ]للَّهَ يَ[q:4397[جْ]عَل لَّهُ[n[ۥ] مِنْ أَمْرِه[n[ِۦ] يُسْرًا","Аёлларингиздан ҳайздан ноумид бўлганларининг иддаси, агар шубҳангиз бўлса, уч ойдир. Ҳайз кўрмаганлариники ҳам. Ҳомиладорларнинг иддаси ҳомилаларини қўймоқликдир. Ким Аллоҳга тақво қилса, У зот унинг ишида осонлик қилиб берадир.",558,28],["ذ[n[َٲ]لِكَ أَمْرُ [h:2832[ٱ]للَّهِ أَ[f:3300[نز]َلَهُ[o[ۥٓ] إِلَيْكُمْ‌ۚ وَم[a:13664[َن ي]َتَّقِ [h:13665[ٱ]للَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔـاتِه[n[ِۦ] وَيُعْظِمْ لَهُ[o[ۥٓ] أَ[q:2795[جْ]رًا","Булар Аллоҳнинг сизга туширган амридир. Ким Аллоҳга тақво қилса, унинг гуноҳларини кечирур ва ажрини кўпайтириб берур.",558,28],["أَسْكِنُوهُ[g[نّ]َ مِنْ حَيْثُ سَكَ[f:13673[نت][w:13674[ُم م]ّ[a:13675[ِن و]ُ[q:13676[جْ]دِكُمْ وَلَا تُض[m[َا]ٓرُّوهُ[g[نّ]َ لِتُضَيِّقُو[s[اْ] عَلَيْهِ[g[نّ]َ‌ۚ وَإِ[f:13677[ن ك]ُ[g[نّ]َ أُ[s[وْ]لَ[n[ـٰ]تِ حَمْ[f:13678[لٍ ف]َأَ[f:13679[نف]ِقُو[s[اْ] عَلَيْهِ[g[نّ]َ حَتَّىٰ يَضَعْنَ حَمْلَهُ[g[نّ]َ‌ۚ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔـاتُوهُ[g[نّ]َ أُجُورَهُ[g[نّ]َ‌ۖ وَأْتَمِرُو[s[اْ] بَيْنَك[c:13680[ُم ب]ِمَعْرُو[a:13681[فٍ‌ۖ و]َإِ[f:13682[ن ت]َعَاسَرْتُمْ فَسَتُرْضِعُ لَهُ[o[ۥٓ] أُخْرَىٰ","Уларга имконингиз борича ўзингиз яшаб турган жойдан жой беринг. Уларга сиқиштириш мақсадида зарар етказманг. Агар ҳомиладор бўлсалар, то ҳомилаларини қўйгунларича уларга нафақа беринглар. Агар сизга эмизиб берсалар, ҳақларини беринглар, ўзаро яхшилик билан маслаҳат қилинглар. Агар қийинчиликка учрасангиз, уга бошқа аёл эмизиб берур.",559,28],["لِيُ[f:13683[نف]ِ[q:13683[قْ] ذُو سَعَ[a:13684[ةٍ م]ِّ[f:3193[ن س]َعَتِه[n[ِۦ]‌ۖ وَمَ[f:13685[ن ق]ُدِرَ عَلَيْهِ رِزْقُهُ[n[ۥ] فَلْيُ[f:13686[نف]ِ[q:13686[قْ] مِ[g[مّ][o[َآ] ءَاتَ[n[ـٰ]هُ [h:1498[ٱ]للَّهُ‌ۚ لَا يُكَلِّفُ [h:1713[ٱ]للَّهُ نَفْسًا إِلَّا م[o[َآ] ءَاتَ[n[ـٰ]هَا‌ۚ سَيَ[q:8428[جْ]عَلُ [h:13687[ٱ]للَّهُ بَعْدَ عُسْ[a:13688[رٍ ي]ُسْرًا","Ризқи кенг кенглигидан нафақа қилсин. Кимнинг ризқи тор бўлса, унга Аллоҳ берганидан нафақа қилсин. Аллоҳ ҳар бир нафсни Ўзи берганидан ортиқчага таклиф қилмас. Аллоҳ қийинчиликдан сўнг тезда осонликни берадир.",559,28],["وَكَأَيّ[a:2298[ِن م]ِّ[f:4585[ن ق]َرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِه[n[ِۦ] فَحَاسَ[q:13689[بْ]نَ[n[ـٰ]هَا حِسَا[f:13690[بًا ش]َدِي[a:13691[دًا و]َعَذَّ[q:13692[بْ]نَ[n[ـٰ]هَا عَذَا[a:8212[بًا ن]ُّكْرًا","Кўпгина қишлоқлар ўз Роббисин амрига саркашлик қилди. Бас, Биз уларни шиддатли ҳисобга олдик ва қаттиқ азоб ила азобладик.",559,28],["فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَ[n[ـٰ]قِبَةُ أَمْرِهَا خُسْرًا","Бас, улар ўз ишларининг ёмонлигини тотиб кўрдилар ва ишларининг оқибати ютқизиқ бўлди.",559,28],["أَعَدَّ [h:5775[ٱ]للَّهُ لَهُمْ عَذَا[f:1966[بًا ش]َدِي[f:13693[دًا‌ۖ ف]َ[h:112[ٱ]تَّقُو[s[اْ] [h:1945[ٱ]للَّهَ يَ[o[ـٰٓ]أُ[s[وْ]لِى [h:941[ٱ]لْأَلْبَ[n[ـٰ]بِ [h:13694[ٱ]لَّذِينَ ءَامَنُو[s[اْ‌ۚ] قَ[q:298[دْ] أَ[f:471[نز]َلَ [h:472[ٱ]للَّهُ إِلَيْكُمْ ذِكْرًا","Аллоҳ уларга қаттиқ азобни тайёрлаб қўйди. Бас, Аллоҳга тақво қилинг, эй иймон келтирган ақл эгалари. Ҳақиқатда, Аллоҳ сизларга зикрни туширди.",559,28],["رَّسُول[a:10208[اً ي]َتْلُو[s[اْ] عَلَيْكُمْ ءَايَ[n[ـٰ]تِ [h:1298[ٱ]للَّهِ مُبَيِّنَ[n[ـٰ][u:13695[تٍ ل]ِّيُخْرِجَ [h:13696[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ مِنَ [h:1491[ٱ][l[ل]ظُّلُمَ[n[ـٰ]تِ إِلَى [h:1492[ٱ][l[ل][g[نّ]ُورِ‌ۚ وَم[a:13644[َن ي]ُؤْم[i:12652[ِنۢ ب]ِ[h:32[ٱ]للَّهِ وَيَعْمَلْ صَ[n[ـٰ]لِ[a:13697[حًا ي]ُ[q:2631[دْ]خِلْهُ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَ[f:13698[دًا‌ۖ ق]َ[q:298[دْ] أَحْسَنَ [h:10249[ٱ]للَّهُ لَهُ[n[ۥ] رِزْقًا","Пайғабарники, у иймон келтириб ва яхши амалларни қилганларни зулматлардан нурга чиқариш учун, сизларга Аллоҳнинг равшан оятларини тиловат қилиб берур. Ва ким Аллоҳга иймон келтирса ва яхши амалларни қилса, У зот уни дарахтлари остидан анҳорлар оқиб турган жаннатларга киритур. У ерда абадул-абад қолурлар. Ҳақиқатда, Аллоҳ унинг ризқини яхши қилгандир.",559,28],["ٱللَّهُ [h:4738[ٱ]لَّذِى خَلَقَ سَ[q:158[بْ]عَ سَمَ[n[ـٰ]و[n[َٲ][a:13699[تٍ و]َمِنَ [h:13700[ٱ]لْأَرْضِ مِثْلَهُ[g[نّ]َ يَتَنَزَّلُ [h:13701[ٱ]لْأَمْرُ بَيْنَهُ[g[نّ]َ لِتَعْلَم[o[ُوٓ][s[اْ] أَ[g[نّ]َ [h:394[ٱ]للَّهَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َدِي[a:13702[رٌ و]َأَ[g[نّ]َ [h:859[ٱ]للَّهَ قَ[q:298[دْ] أَحَاطَ بِكُلِّ شَىْءٍ عِلْمَۢا","Аллоҳ етти осмонни ва улар мислидек ерни яратган зотдир. Уларнинг орасидан У зотнинг амри тушадир. Аллоҳ ҳар бир нарсага қодир эканини ва, албатта, Аллоҳ ҳар бир нарсани Ўз илми ила ўраб олганини билишингиз учун.",559,28]]},{"n":66,"ar":"التَّحۡرِيمِ","en":"At-Tahrim","uz":"Таҳрим","type":"Мадина","ayahs":[["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ لِمَ تُحَرِّمُ م[o[َآ] أَحَلَّ [h:3750[ٱ]للَّهُ لَكَ‌ۖ تَ[q:13703[بْ]تَغِى مَرْضَاتَ أَزْو[n[َٲ]جِكَ‌ۚ وَ[h:72[ٱ]للَّهُ غَفُو[u:890[رٌ ر]َّح[p[ِي]مٌ","Эй Набий! Нима учун хотинларинг розилигини тилаб, Аллоҳ сенга ҳалол қилган нарсани ҳаром қиласан! Аллоҳ кечирувчи ва раҳмдилдир.",560,28],["قَ[q:298[دْ] فَرَضَ [h:10836[ٱ]للَّهُ لَكُمْ تَحِلَّةَ أَيْمَ[n[ـٰ]نِكُمْ‌ۚ وَ[h:72[ٱ]للَّهُ مَوْلَ[n[ـٰ]كُمْ‌ۖ وَهُوَ [h:10530[ٱ]لْعَلِيمُ [h:171[ٱ]لْحَك[p[ِي]مُ","Батаҳҳиқ, Аллоҳ сизларга қасамларингизни бўшатишни шариатга киритди ва Аллоҳ сизнинг хожангиздир ва У ўта билувчи ва ўта ҳикматлидир.",560,28],["وَإِذْ أَسَرَّ [h:13704[ٱ][l[ل][g[نّ]َبِىُّ إِلَىٰ بَعْضِ أَزْو[n[َٲ]جِه[n[ِۦ] حَدِي[f:13705[ثًا ف]َلَ[g[مّ]َا نَبَّأَتْ بِه[n[ِۦ] وَأَظْهَرَهُ [h:13706[ٱ]للَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُ[n[ۥ] وَأَعْرَضَ ع[i:13707[َنۢ ب]َعْ[f:13708[ضٍ‌ۖ ف]َلَ[g[مّ]َا نَبَّأَهَا بِه[n[ِۦ] قَالَتْ مَنْ أَ[i:13709[نۢب]َأَكَ هَ[n[ـٰ]ذَا‌ۖ قَالَ نَبَّأَنِىَ [h:13710[ٱ]لْعَلِيمُ [h:13711[ٱ]لْخَب[p[ِي]رُ","Набий хотинларидан баъзисига сир гап айтган эди. Бас, удан хабар берди ва Аллоҳ ишни уга билдирди. У баъзисини билдирди ва баъзисини эсламади. Қачон улга ҳақида хабар берганида, у, буни сенга ким хабар қилди? деди. У, менга ҳамма нарсани билувчи ва ҳамма нарсадан хабардор Аллоҳ хабар берди, деди. Эй икки аёл!",560,28],["إِ[f:13712[ن ت]َتُوب[o[َآ] إِلَى [h:1637[ٱ]للَّهِ فَقَ[q:563[دْ] صَغَتْ قُلُوبُكُمَا‌ۖ وَإِ[f:13713[ن ت]َظَ[n[ـٰ]هَرَا عَلَيْهِ فَإِ[g[نّ]َ [h:513[ٱ]للَّهَ هُوَ مَوْلَ[n[ـٰ]هُ وَجِ[q:13714[بْ]رِيلُ وَصَ[n[ـٰ]لِحُ [h:13715[ٱ]لْمُؤْمِنِينَ‌ۖ وَ[h:1146[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ بَعْدَ ذ[n[َٲ]لِكَ ظَه[p[ِي]رٌ","Агар икковингиз Аллоҳга тавба қилсангиз, батаҳқиқ, қалбларингиз моил бўлур. Агар унга қарши чиқсангиз, бас, албатта, Аллоҳ унинг ёрдамчисидир ва Жаброил ҳам, солиҳ мўминлар ҳам. Ундан сўнг фаришталар ҳам унга суянчиқдир.",560,28],["عَسَىٰ رَبُّهُ[o[ۥٓ] إِ[f:13716[ن ط]َلَّقَكُ[g[نّ]َ أ[a:13717[َن ي]ُ[q:13718[بْ]دِلَهُ[o[ۥٓ] أَزْو[n[َٲ]جًا خَيْ[a:13719[رًا م]ِّ[f:10776[نك]ُ[g[نّ]َ مُسْلِمَ[n[ـٰ][a:13720[تٍ م]ُّؤْمِنَ[n[ـٰ][f:13721[تٍ ق]َ[n[ـٰ]نِتَ[n[ـٰ][f:13722[تٍ ت]َ[o[ـٰٓ]ئِبَ[n[ـٰ]تٍ عَ[n[ـٰ]بِد[n[َٲ][f:13723[تٍ س]َ[o[ـٰٓ]ئِحَ[n[ـٰ][f:13724[تٍ ث]َيِّبَ[n[ـٰ][a:13725[تٍ و]َأَ[q:13726[بْ]كَارًا","У сизларни талоқ қилса, шоядки, Роббиси сиздан яхшироқ, муслима, мўмина, итоатли, тавбачи, ибодатли, рўзадор жувон ва қизларни ўрнингизга хотин қилиб берса.",560,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] ق[o[ُوٓ][s[اْ] أَ[f:221[نف]ُسَكُمْ وَأَهْلِيكُمْ نَا[a:13727[رًا و]َقُودُهَا [h:115[ٱ][l[ل][g[نّ]َاسُ وَ[h:116[ٱ]لْحِجَارَةُ عَلَيْهَا مَلَ[o[ـٰٓ]ئِكَةٌ غِلَا[f:13728[ظٌ ش]ِدَا[u:13729[دٌ ل]َّا يَعْصُونَ [h:13730[ٱ]للَّهَ م[o[َآ] أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَر[p[ُو]نَ","Эй иймон келтирганлар! Ўзингизни ва аҳли аёлингизни ёқилғиси одамлару тошдан бўлган ўтдан сақланг. Унинг тепасида қўпол, дарғазаб фаришталар бўлиб, улар Аллоҳнинг амрига исён қилмаслар ва нимага буюрилсалар, шуни қилурлар.",560,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَا تَعْتَذِرُو[s[اْ] [h:13731[ٱ]لْيَوْمَ‌ۖ إِ[g[نّ]َمَا تُ[q:4248[جْ]زَوْنَ مَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Эй кофир бўлганлар, бугунги кунда узр айтманглар, сиз ўзингиз қилган ишларнинг жазосини олмоқдасиз, холос.",560,28],["يَ[o[ـٰٓ]أَيُّهَا [h:541[ٱ]لَّذِينَ ءَامَنُو[s[اْ] تُوب[o[ُوٓ][s[اْ] إِلَى [h:1637[ٱ]للَّهِ تَوْبَ[a:13732[ةً ن]َّصُوحًا عَسَىٰ رَبُّكُمْ أ[a:13733[َن ي]ُكَفِّرَ عَ[f:255[نك]ُمْ سَيِّـَٔـاتِكُمْ وَيُ[q:13734[دْ]خِلَكُمْ جَ[g[نّ]َ[n[ـٰ][f:119[تٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ يَوْمَ لَا يُخْزِى [h:13735[ٱ]للَّهُ [h:13736[ٱ][l[ل][g[نّ]َبِىَّ وَ[h:37[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مَعَهُ[n[ۥ]‌ۖ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَ[n[ـٰ]نِهِمْ يَقُولُونَ رَبَّن[o[َآ] أَتْمِمْ لَنَا نُورَنَا وَ[h:1720[ٱ]غْفِرْ لَن[o[َآ‌ۖ] إِ[g[نّ]َكَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Эй иймон келтирганлар! Аллоҳга холис тавба қилинглар! Шоядки Роббингиз гуноҳларингизни ювса ва сизни дарахтлари остидан анҳорлар оқиб турган жаннатларга киритса. Бир кундаки, унда Аллоҳ Набийни ва у билан бирга бўлган иймон келтирганларни шарманда қилмас. Уларнинг нурлари олдиларида ва ўнг тарафларида юриб борадир. Улар эса, Роббимиз, бизга нуримизни батамом қилиб бер, гуноҳларимизни кечир, албатта, Сен барча нарсага қодирсан, дерлар.",561,28],["يَ[o[ـٰٓ]أَيُّهَا [h:5411[ٱ][l[ل][g[نّ]َبِىُّ جَ[n[ـٰ]هِدِ [h:5723[ٱ]لْكُفَّارَ وَ[h:5724[ٱ]لْمُنَ[n[ـٰ]فِقِينَ وَ[h:5725[ٱ]غْلُظْ عَلَيْهِمْ‌ۚ وَمَأْوَ[n[ٮٰ]هُمْ جَهَ[g[نّ]َمُ‌ۖ وَبِئْسَ [h:665[ٱ]لْمَص[p[ِي]رُ","Эй Набий! Кофир ва мунофиқларга қарши жиҳод қил ва уларга маҳкам тур. Уларнинг жойи жаҳаннамдир ва у жой қандоқ ҳам ёмон манзил!",561,28],["ضَرَبَ [h:7103[ٱ]للَّهُ مَثَل[u:13737[اً ل]ِّلَّذِينَ كَفَرُو[s[اْ] [h:13738[ٱ]مْرَأَتَ نُو[a:13739[حٍ و]َ[h:13740[ٱ]مْرَأَتَ لُو[f:13741[طٍ‌ۖ ك]َانَتَا تَحْتَ عَ[q:13742[بْ]دَيْنِ مِنْ عِبَادِنَا صَ[n[ـٰ]لِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ [h:321[ٱ]للَّهِ شَيْـ[a:13743[ـًٔا و]َقِيلَ [h:13744[ٱ][q:13745[دْ]خُلَا [h:13746[ٱ][l[ل][g[نّ]َارَ مَعَ [h:13747[ٱ][l[ل]دّ[n[َٲ]خِل[p[ِي]نَ","Аллоҳ куфр келтирганларга Нуҳнинг хотини ва Лутнинг хотинини мисол қилиб келтирди. Улар бандаларимиздан икки солиҳ банданинг тагида эдилар. Бас, уларга хиёнат қилдилар ва улардан Аллоҳнинг азобини қайтара олмадилар ва уларга, дўзахга кирувчилар билан киринглар, дейилди.",561,28],["وَضَرَبَ [h:7509[ٱ]للَّهُ مَثَل[u:13737[اً ل]ِّلَّذِينَ ءَامَنُو[s[اْ] [h:13748[ٱ]مْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ [h:13749[ٱ][q:3590[بْ]نِ لِى عِ[f:4962[ند]َكَ بَيْ[f:13750[تًا ف]ِى [h:12075[ٱ]لْجَ[g[نّ]َةِ وَنَجِّنِى مِ[f:6159[ن ف]ِرْعَوْنَ وَعَمَلِه[n[ِۦ] وَنَجِّنِى مِنَ [h:4196[ٱ]لْقَوْمِ [h:4155[ٱ][l[ل]ظَّ[n[ـٰ]لِم[p[ِي]نَ","Аллоҳ иймон келтирганларга Фиръавннинг хотинини мисол қилиб кўрсатди. У: «Роббим, менга Ўз ҳузурингда, жаннатда бир уй бино қилгин. Менга Фиръавндан ва унинг ишидан нажот бергин ва золим қавмлардан нажот бергин, деб айтди.",561,28],["وَمَرْيَمَ [h:13751[ٱ][q:13752[بْ]نَتَ عِمْر[n[َٲ]نَ [h:13753[ٱ]لَّت[o[ِىٓ] أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ م[u:8851[ِن ر]ُّوحِنَا وَصَدَّقَتْ بِكَلِمَ[n[ـٰ]تِ رَبِّهَا وَكُتُبِه[n[ِۦ] وَكَانَتْ مِنَ [h:13754[ٱ]لْقَ[n[ـٰ]نِت[p[ِي]نَ","Ва Марям Имрон қизини, у фаржини пок сақлаган эди, Биз унга Ўз руҳимиздан пуфладик ва у Роббисининг сўзларини ҳамда китобларини тасдиқ қилди ва итоаткорлардан бўлди.",561,28]]},{"n":67,"ar":"المُلۡكِ","en":"Al-Mulk","uz":"Мулк","type":"Макка","ayahs":[["تَبَ[n[ـٰ]رَكَ [h:9556[ٱ]لَّذِى بِيَدِهِ [h:13755[ٱ]لْمُلْكُ وَهُوَ عَلَىٰ كُلِّ ش[f:81[َىْءٍ ق]َد[p[ِي]رٌ","Қўлида мулк бўлган У зот улуғ, муқаддас бўлди. У барча нарсага қодирдир.",562,29],["ٱلَّذِى خَلَقَ [h:13756[ٱ]لْمَوْتَ وَ[h:13757[ٱ]لْحَيَ[s[و][n[ٲ]ةَ لِيَ[q:3603[بْ]لُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَل[a:13758[اً‌ۚ و]َهُوَ [h:7045[ٱ]لْعَزِيزُ [h:13759[ٱ]لْغَف[p[ُو]رُ","У ўлим ва ҳаётини сизларнинг қайсиларингиз амалда яхшироқ эканлигингизни синаш учун яратгандир. У азиз ва ўта мағфиратлидир.",562,29],["ٱلَّذِى خَلَقَ سَ[q:158[بْ]عَ سَمَ[n[ـٰ]و[n[َٲ][f:13760[تٍ ط]ِبَا[a:13761[قًا‌ۖ م]َّا تَرَىٰ فِى خَلْقِ [h:13762[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ مِ[f:13763[ن ت]َفَ[n[ـٰ]وُ[f:13764[تٍ‌ۖ ف]َ[h:13765[ٱ]رْجِعِ [h:13766[ٱ]لْبَصَرَ هَلْ تَرَىٰ مِ[f:13767[ن ف]ُط[p[ُو]رٍ","У етти осмонни табақама-табақа яратгандир. Роҳманнинг яратганида ҳеч тафовут кўрмассан. Қайта назар сол! Бирор камчилик кўряпсанми?",562,29],["ثُ[g[مّ]َ [h:13768[ٱ]رْجِعِ [h:13769[ٱ]لْبَصَرَ كَرَّتَيْنِ يَ[f:2282[نق]َلِ[q:2282[بْ] إِلَيْكَ [h:13770[ٱ]لْبَصَرُ خَاسِ[a:13771[ئًا و]َهُوَ حَس[p[ِي]رٌ","Сўнг такрор-такрор назар сол, назар сенга истаганини топа олмай, ҳорғин- чарчаган ҳолда қайтади.",562,29],["وَلَقَ[q:341[دْ] زَيَّ[g[نّ]َا [h:11314[ٱ][l[ل]سَّم[o[َا]ٓءَ [h:11315[ٱ][l[ل]دُّنْيَا بِمَصَ[n[ـٰ]بِيحَ وَجَعَلْنَ[n[ـٰ]هَا رُجُو[u:13772[مًا ل]ِّلشَّيَ[n[ـٰ]طِينِ‌ۖ وَأَعْتَ[q:2782[دْ]نَا لَهُمْ عَذَابَ [h:13773[ٱ][l[ل]سَّع[p[ِي]رِ","Ва дарҳақиқат Биз яқин осмонни чироқлар билан зийнатлаб қўйдик ва у ларни шайтонларга отиладиган нарса ҳам қилиб қўйдик. Ва уларга олови қизиб турган жаҳаннамни тайёрлаб қўйдик.",562,29],["وَلِلَّذِينَ كَفَرُو[s[اْ] بِرَبِّهِمْ عَذَابُ جَهَ[g[نّ]َمَ‌ۖ وَبِئْسَ [h:665[ٱ]لْمَص[p[ِي]رُ","Ўз Роббиларига куфр келтирганлар учун жаҳаннам азоби бордур ва у қандай ҳам ёмон қайтадиган жой!",562,29],["إِذ[o[َآ] أُلْقُو[s[اْ] فِيهَا سَمِعُو[s[اْ] لَهَا شَهِي[a:13774[قًا و]َهِىَ تَف[p[ُو]رُ","Улар жаҳаннамга ташланган чоғларида унинг ҳанграган овозини эшитурлар, у эса қайнаб турган бўладир.",562,29],["تَكَادُ تَمَيَّزُ مِنَ [h:2195[ٱ]لْغَيْظِ‌ۖ كُلَّم[o[َآ] أُلْقِىَ فِيهَا فَوْ[f:13775[جٌ س]َأَلَهُمْ خَزَنَتُه[o[َآ] أَلَمْ يَأْتِكُمْ نَذ[p[ِي]رٌ","У ғазабдан ёрилиб кетай дейдир. Ҳар қачон унга янги гуруҳ ташланганда унинг хизматкорлари: «Сизларга огоҳлантирувчи келмаганмиди?», деб сўрайдир.",562,29],["قَالُو[s[اْ] بَلَىٰ قَ[q:298[دْ] ج[o[َا]ٓءَنَا نَذِي[f:13776[رٌ ف]َكَذَّ[q:13777[بْ]نَا وَقُلْنَا مَا نَزَّلَ [h:4797[ٱ]للَّهُ مِ[f:2103[ن ش]َىْءٍ إِنْ أَ[f:428[نت]ُمْ إِلَّا فِى ضَلَ[n[ـٰ][f:13778[لٍ ك]َب[p[ِي]رٍ","Улар: «Ҳа, дарҳақиқат бизга огоҳлантирувчи келган эди. Лекин биз ёлғончига чиқардик ва: «Аллоҳ ҳеч нарса туширгани йўқ, сизлар катта адашувдан бошқа ҳеч нарса эмассизлар», деган эдик», дерлар.",562,29],["وَقَالُو[s[اْ] لَوْ كُ[g[نّ]َا نَسْمَعُ أَوْ نَعْقِلُ مَا كُ[g[نّ]َا ف[o[ِىٓ] أَصْحَ[n[ـٰ]بِ [h:11067[ٱ][l[ل]سَّع[p[ِي]رِ","Ва улар: «Агар эътибор қулоғи билан эшитганимизда ёки ақлни ишлатганимизда эди, дўзахийлар орасида бўлмаган бўлар эдик», дерлар.",562,29],["فَ[h:9999[ٱ]عْتَرَفُو[s[اْ] بِذَ[i:13779[نۢب]ِهِمْ فَسُحْ[u:13780[قًا ل]ِّأَصْحَ[n[ـٰ]بِ [h:13781[ٱ][l[ل]سَّع[p[ِي]رِ","Бас, улар ўз гуноҳларини эътироф этдилар. Йўқолсин дўзахийлар!",562,29],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ يَخْشَوْنَ رَبَّه[c:8779[ُم ب]ِ[h:13[ٱ]لْغَيْبِ لَه[w:3412[ُم م]َّغْفِرَ[a:3413[ةٌ و]َأَ[q:3414[جْ][f:6259[رٌ ك]َب[p[ِي]رٌ","Албатта ўз Роббиларидан ғойибдан қўрқадиганлар учун гуноҳларини кечиш ва улкан ажр-савоблар бордир.",562,29],["وَأَسِرُّو[s[اْ] قَوْلَكُمْ أَوِ [h:13782[ٱ][q:13783[جْ]هَرُو[s[اْ] بِه[o[ِۦٓ‌ۖ] إِ[g[نّ]َهُ[n[ۥ] عَلِي[i:2196[مُۢ ب]ِذَاتِ [h:2197[ٱ][l[ل]صُّد[p[ُو]رِ","Ва сиз сўзингизни сир тутасизми ёки ошкора айтасизми, албатта, У кўнгиллардагини ҳам билгувчи зотдир.",563,29],["أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ [h:4309[ٱ][l[ل]لَّطِيفُ [h:4310[ٱ]لْخَب[p[ِي]رُ","Яратган зот Ўзи билмасмиди? Ва У дақиқларгача билувчи ва хабардор зотдир.",563,29],["هُوَ [h:153[ٱ]لَّذِى جَعَلَ لَكُمُ [h:87[ٱ]لْأَرْضَ ذَلُول[f:13784[اً ف]َ[h:13785[ٱ]مْشُو[s[اْ] فِى مَنَاكِبِهَا وَكُلُو[s[اْ] م[u:13786[ِن ر]ِّزْقِه[n[ِۦ]‌ۖ وَإِلَيْهِ [h:13787[ٱ][l[ل][g[نّ]ُش[p[ُو]رُ","У сизларга ерни бўйсундириб қўйган зотдир. Бас, унинг турли жойларида юринг ва Унинг ризқидан енг ва қабрдан чиқиб бориш ҳам Унинг ҳузурига бўладир.",563,29],["ءَأَمِ[f:13788[نت][w:13789[ُم م]َّ[f:2074[ن ف]ِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ أ[a:7417[َن ي]َخْسِفَ بِكُمُ [h:13790[ٱ]لْأَرْضَ فَإِذَا هِىَ تَم[p[ُو]رُ","Осмондаги зот сизларни ерга юттириб юборишидан омонда бўлдингизми? У эса изтиробда ҳаракатланиб туради.",563,29],["أَمْ أَمِ[f:1062[نت][w:13791[ُم م]َّ[f:2074[ن ف]ِى [h:746[ٱ][l[ل]سَّم[o[َا]ٓءِ أ[a:10505[َن ي]ُرْسِلَ عَلَيْكُمْ حَاصِ[f:13792[بًا‌ۖ ف]َسَتَعْلَمُونَ كَيْفَ نَذ[p[ِي]رِ","Ёки осмондаги зот сизларга азоб шамолни юборишидан омонда бўлдингизми? Бас, албатта огоҳлантириш қандоқ бўлишини билурсизлар.",563,29],["وَلَقَ[q:341[دْ] كَذَّبَ [h:4507[ٱ]لَّذِينَ مِ[f:617[ن ق]َ[q:618[بْ]لِهِمْ فَكَيْفَ كَانَ نَك[p[ِي]رِ","Ва дарҳақиқат улардан аввалгилари ҳам ёлғонга чиқарган эдилар. Бас инкорим қандай бўлди?!",563,29],["أَوَلَمْ يَرَوْ[s[اْ] إِلَى [h:7520[ٱ][l[ل]طَّيْرِ فَوْقَهُمْ صَ[m[ـٰٓ]فَّ[n[ـٰ][a:13793[تٍ و]َيَ[q:13794[قْ]بِضْنَ‌ۚ مَا يُمْسِكُهُ[g[نّ]َ إِلَّا [h:13795[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ‌ۚ إِ[g[نّ]َهُ[n[ۥ] بِكُلِّ شَىْ[i:13796[ءِۭ ب]َص[p[ِي]رٌ","Тепаларида ёйиб ва йиғаётган қушни кўрмайдиларми? Уларни Роҳмандан бошқа ушлаб турувчи йўқ. Албатта, У барча нарсани кўрувчидир.",563,29],["أَ[g[مّ]َنْ هَ[n[ـٰ]ذَا [h:126[ٱ]لَّذِى هُوَ جُن[u:13797[دٌ ل]َّكُمْ يَ[f:2381[نص]ُرُك[w:2382[ُم م]ِّ[f:107[ن د]ُونِ [h:12269[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ‌ۚ إِنِ [h:13798[ٱ]لْكَ[n[ـٰ]فِرُونَ إِلَّا فِى غُر[p[ُو]رٍ","Роҳмандан бошқа сизларга ёрдам берадиган аскар ким ўзи? Кофирлар ғурурдан бошқа ҳеч нарсада эмаслар!",563,29],["أَ[g[مّ]َنْ هَ[n[ـٰ]ذَا [h:126[ٱ]لَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُ[n[ۥ]‌ۚ بَل لَّجُّو[s[اْ] فِى عُتُ[a:13799[وٍّ و]َنُف[p[ُو]رٍ","У Ризқни тортиб қўйса, сизга ризқ берадиган ким ўзи?! Балки улар абадий туғёнда ва ҳақдан нафратда бўлурлар.",563,29],["أَفَم[a:13800[َن ي]َمْشِى مُكِبًّا عَلَىٰ وَ[q:6818[جْ]هِه[o[ِۦٓ] أَهْدَ[o[ىٰٓ] أَ[g[مّ][a:13801[َن ي]َمْشِى سَوِيًّا عَلَىٰ صِر[n[َٲ][a:726[طٍ م]ُّسْتَق[p[ِي]مٍ","Юз тубан қоқилиб юраётган киши ҳидоятдами ёки тўғри йўлдан қоматини тик тутиб бораётган кишими?",563,29],["قُلْ هُوَ [h:153[ٱ]لَّذ[o[ِىٓ] أَ[f:4272[نش]َأَكُمْ وَجَعَلَ لَكُمُ [h:7518[ٱ][l[ل]سَّمْعَ وَ[h:6037[ٱ]لْأَ[q:6037[بْ]صَ[n[ـٰ]رَ وَ[h:7519[ٱ]لْأَفْــِٔدَةَ‌ۖ قَلِيل[a:4583[اً م]َّا تَشْكُر[p[ُو]نَ","Сен: «У сизларни йўқдан бор қилган ва сизларга эшитиш, кўриш ва ақлни берган зотдир. Жуда ҳам оз шукр қиласизлар-а?!» деб айт.",563,29],["قُلْ هُوَ [h:153[ٱ]لَّذِى ذَرَأَكُمْ فِى [h:44[ٱ]لْأَرْضِ وَإِلَيْهِ تُحْشَر[p[ُو]نَ","Сен: «У сизларни ер юзида яратган, кўпайтирган зотдир. Ва Унинг ҳузурига тўпланурсизлар», деб айт.",563,29],["وَيَقُولُونَ مَتَىٰ هَ[n[ـٰ]ذَا [h:6081[ٱ]لْوَعْدُ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]دِق[p[ِي]نَ","Ва улар: «Агар ростгўй бўлсангиз, бу ваъда қачон бўлади?» дерлар.",563,29],["قُلْ إِ[g[نّ]َمَا [h:12490[ٱ]لْعِلْمُ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ وَإِ[g[نّ]َم[o[َآ] أَنَا۟ نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","Мен: «Албатта, илм, фақат Аллоҳнинг ҳузуридадир. Ва албатта, мен яққол огоҳлантирувчиман, холос», деб айт.",563,29],["فَلَ[g[مّ]َا رَأَوْهُ زُلْفَ[f:13802[ةً س]ِ[o[يٓ]ــَٔتْ وُجُوهُ [h:13803[ٱ]لَّذِينَ كَفَرُو[s[اْ] وَقِيلَ هَ[n[ـٰ]ذَا [h:126[ٱ]لَّذِى كُ[f:100[نت][c:6084[ُم ب]ِه[n[ِۦ] تَدَّع[p[ُو]نَ","Бас азобни яқиндан кўрганда куфр келтирганларнинг юзлари қораяр. Ва уларга: «Сўраган нарсангиз шу бўлади», дейилур.",564,29],["قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ [h:13804[ٱ]للَّهُ وَم[a:9807[َن م]َّعِىَ أَوْ رَحِمَنَا فَم[a:13805[َن ي]ُجِيرُ [h:13806[ٱ]لْكَ[n[ـٰ]فِرِينَ مِنْ عَذَابٍ أَل[p[ِي]مٍ","Сен: «Айтинглар-чи, агар Аллоҳ мени ва мен билан бўлганларни ҳалок қилса ёки раҳм қилса, кофирларни аламли азобдан ким қутқариб қолади?!» деб айт.",564,29],["قُلْ هُوَ [h:829[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ ءَامَ[g[نّ]َا بِه[n[ِۦ] وَعَلَيْهِ تَوَكَّلْنَا‌ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَ[n[ـٰ][a:2393[لٍ م]ُّب[p[ِي]نٍ","Сен: «У Роҳмандур, биз Унга иймон келтирдик ва Унга таваккал қилдик. Бас, сизлар тезда ким очиқ-ойдин хатода эканини билурсизлар», деб айт.",564,29],["قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ م[o[َا]ٓؤُكُمْ غَوْ[f:13807[رًا ف]َم[a:13808[َن ي]َأْتِيك[c:13809[ُم ب]ِم[o[َا]ٓ[a:13810[ءٍ م]َّع[p[ِي]نِۭ","Сен: «Айтинглар-чи, агар сувларингиз ерга сингиб кетса, сизларга ким осонгина топиладиган сувни келтиради?» деб айт.",564,29]]},{"n":68,"ar":"القَلَمِ","en":"Al-Qalam","uz":"Қалам","type":"Макка","ayahs":[["[m[نٓ]‌ۚ وَ[h:13811[ٱ]لْقَلَمِ وَمَا يَسْطُر[p[ُو]نَ","Нуун. Қалам билан ва сатрларга ёзадиган нарсалар билан қасам.",564,29],["م[o[َآ] أَ[f:169[نت]َ بِنِعْمَةِ رَبِّكَ بِمَ[q:13812[جْ]ن[p[ُو]نٍ","Сен Роббинг неъмати ила мажнун эмассан.",564,29],["وَإِ[g[نّ]َ لَكَ لَأَ[q:4918[جْ]رًا غَيْرَ مَمْن[p[ُو]نٍ","Ва албатта, сенга миннат қилинмайдиган ажр бордур.",564,29],["وَإِ[g[نّ]َكَ لَعَلَىٰ خُلُقٍ عَظ[p[ِي]مٍ","Ва албатта, сен улкан хулқдасан.",564,29],["فَسَتُ[q:13813[بْ]صِرُ وَيُ[q:13814[بْ]صِر[p[ُو]نَ","Бас, тезда кўрурсан ва улар ҳам кўрурлар.",564,29],["بِأَييِّكُمُ [h:13815[ٱ]لْمَفْت[p[ُو]نُ","Сизлардан кимда жунунлик борлигини.",564,29],["إِ[g[نّ]َ رَبَّكَ هُوَ أَعْلَمُ بِمَ[f:7639[ن ض]َلَّ عَ[f:4361[ن س]َبِيلِه[n[ِۦ] وَهُوَ أَعْلَمُ بِ[h:4362[ٱ]لْمُهْتَد[p[ِي]نَ","Албатта, Роббинг Ўзи, ким Унинг йўлидан адашганини билувчидур ва У ҳидоятда юрувчиларни ҳам билувчидур.",564,29],["فَلَا تُطِعِ [h:13816[ٱ]لْمُكَذِّب[p[ِي]نَ","Бас, ёлғонга чиқарувчиларга итоат қилма.",564,29],["وَدُّو[s[اْ] لَوْ تُ[q:13817[دْ]هِنُ فَيُ[q:13818[دْ]هِن[p[ُو]نَ","Агар сен муроса қилсанг, улар ҳам муроса қилишни орзу қиларлар.",564,29],["وَلَا تُطِعْ كُلَّ حَلَّا[a:13819[فٍ م]َّه[p[ِي]نٍ","Итоат қилма! Ҳар бир қасамхўр, пасткашга.",564,29],["هَ[g[مّ]َا[a:13820[زٍ م]َّشّ[o[َا]ٓ[i:13821[ءِۭ ب]ِنَم[p[ِي]مٍ","Кишиларни айбловчи, чақимчилик қилиб юрувчига.",564,29],["مَّ[g[نّ]َا[u:12814[عٍ ل]ِّلْخَيْرِ مُعْتَدٍ أَث[p[ِي]مٍ","яхшиликни ман қилувчи, тажавузкор, сергуноҳга.",564,29],["عُتُل[i:13822[ِّۭ ب]َعْدَ ذ[n[َٲ]لِكَ زَن[p[ِي]مٍ","Қўпол, ундан сўнг отасининг таъйини йўққа.",564,29],["أَ[f:13823[ن ك]َانَ ذَا مَا[a:9231[لٍ و]َبَن[p[ِي]نَ","Моли ва ўғиллари кўп бўлганидан.",564,29],["إِذَا تُتْلَىٰ عَلَيْهِ ءَايَ[n[ـٰ]تُنَا قَالَ أَسَ[n[ـٰ]طِيرُ [h:3993[ٱ]لْأَوَّل[p[ِي]نَ","Бизнинг оятларимиз Унгаўқилган пайтда, аввалгиларнинг афсоналари, деганга.",564,29],["سَنَسِمُهُ[n[ۥ] عَلَى [h:13824[ٱ]لْخُرْط[p[ُو]مِ","Тезда унинг тумшуғига белги қўямиз.",565,29],["إِ[g[نّ]َا بَلَوْنَ[n[ـٰ]هُمْ كَمَا بَلَوْن[o[َآ] أَصْحَ[n[ـٰ]بَ [h:4715[ٱ]لْجَ[g[نّ]َةِ إِذْ أَ[q:3631[قْ]سَمُو[s[اْ] لَيَصْرِمُ[g[نّ]َهَا مُصْبِح[p[ِي]نَ","Албатта, Биз уларини боғ эгаларини синаганимиздек синаб кўрдик. Вақтики, эрта тонгада териб оламиз, деб қасам ичдилар.",565,29],["وَلَا يَسْتَثْن[p[ُو]نَ","Ва истисно қилмадилар.",565,29],["فَطَافَ عَلَيْهَا ط[o[َا]ٓئِ[a:13825[فٌ م]ّ[u:770[ِن ر]َّبِّكَ وَهُمْ ن[o[َا]ٓئِم[p[ُو]نَ","Улар ухлаб ётганда, боғ устидан Роббингдан бўлган айланувчи айланиб чиқди.",565,29],["فَأَصْبَحَتْ كَ[h:13826[ٱ][l[ل]صَّر[p[ِي]مِ","Бас, у худди меваси териб олинганга ўхшаб қолди.",565,29],["فَتَنَادَوْ[s[اْ] مُصْبِح[p[ِي]نَ","Улар, тонг-саҳарда бир-бирларини чақирдилар:",565,29],["أَنِ [h:13827[ٱ]غْدُو[s[اْ] عَلَىٰ حَرْثِكُمْ إِ[f:109[ن ك]ُ[f:100[نت]ُمْ صَ[n[ـٰ]رِم[p[ِي]نَ","«Агар терадиган бўлсангиз, экинзорингизга эртароқ боринг», деб.",565,29],["فَ[h:9999[ٱ][f:13828[نط]َلَقُو[s[اْ] وَهُمْ يَتَخَ[n[ـٰ]فَت[p[ُو]نَ","Бас, паст овозла гаплашиб, юриб кетдилар.",565,29],["أ[u:4908[َن ل]َّا يَ[q:13829[دْ]خُلَ[g[نّ]َهَا [h:13830[ٱ]لْيَوْمَ عَلَيْك[w:13831[ُم م]ِّسْك[p[ِي]نٌ","«Бугун сиз борингизда у боғга мискин кира кўрмасин», деб.",565,29],["وَغَدَوْ[s[اْ] عَلَىٰ حَرْ[f:13832[دٍ ق]َ[n[ـٰ]دِر[p[ِي]نَ","Ва эрталабда қасдла, ўзларини қодир сезиб, бордилар.",565,29],["فَلَ[g[مّ]َا رَأَوْهَا قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا لَض[m[َا]ٓلّ[p[ُو]نَ","Уни кўрганларида, биз адашибмиз, дедилар.",565,29],["بَلْ نَحْنُ مَحْرُوم[p[ُو]نَ","Балки биз маҳрум бўлгандиримиз, дедилар.",565,29],["قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّح[p[ُو]نَ","Уларнинг энг яхши ва адолатлиси, «Сизларга тасбиҳ айтсаларингиз-чи, демабмидим?!», деди.",565,29],["قَالُو[s[اْ] سُ[q:7648[بْ]حَ[n[ـٰ]نَ رَبِّن[o[َآ] إِ[g[نّ]َا كُ[g[نّ]َا ظَ[n[ـٰ]لِم[p[ِي]نَ","Роббимиз айблардан пок бўлди, албатта биз золимлардан эдик, дедилар.",565,29],["فَأَ[q:11367[قْ]بَلَ بَعْضُهُمْ عَلَىٰ بَعْ[a:13833[ضٍ ي]َتَلَ[n[ـٰ]وَم[p[ُو]نَ","Бас, баъзилари баъзиларни маломат қила бошладилар.",565,29],["قَالُو[s[اْ] يَ[n[ـٰ]وَيْلَن[o[َآ] إِ[g[نّ]َا كُ[g[نّ]َا طَ[n[ـٰ]غ[p[ِي]نَ","Вой, шўримиз қурсин, туғёнга кетган эканмиз.",565,29],["عَسَىٰ رَبُّن[o[َآ] أ[a:13834[َن ي]ُ[q:13835[بْ]دِلَنَا خَيْ[a:8075[رًا م]ِّنْه[o[َآ] إِ[g[نّ][o[َآ] إِلَىٰ رَبِّنَا ر[n[َٲ]غِب[p[ُو]نَ","Шояд Роббимиз унинг ўрнига ундан кўра яхшироғини берса. Биз ўз Роббимизга рағбатлимиз, дедилар.",565,29],["كَذ[n[َٲ]لِكَ [h:13836[ٱ]لْعَذَابُ‌ۖ وَلَعَذَابُ [h:7000[ٱ]لْأَخِرَةِ أَكْبَرُ‌ۚ لَوْ كَانُو[s[اْ] يَعْلَم[p[ُو]نَ","Азоб шундоқ бўлур ва агар билсалар, албатта охират азоби бундан катта бўладир.",565,29],["إِ[g[نّ]َ لِلْمُتَّقِينَ عِ[f:264[ند]َ رَبِّهِمْ جَ[g[نّ]َ[n[ـٰ]تِ [h:3680[ٱ][l[ل][g[نّ]َع[p[ِي]مِ","Албатта, тақводорлар учун Роббилари ҳузурида наъийм жаннатлари бордур.",565,29],["أَفَنَ[q:13837[جْ]عَلُ [h:13838[ٱ]لْمُسْلِمِينَ كَ[h:13839[ٱ]لْمُ[q:13839[جْ]رِم[p[ِي]نَ","Мусулмонларни жинояткорларга ўхшатиб қўярмидик?!",565,29],["مَا لَكُمْ كَيْفَ تَحْكُم[p[ُو]نَ","Сизларга нима бўлди, қандай ҳукм чиқаряпсизлар?!",565,29],["أَمْ لَكُمْ كِتَ[n[ـٰ][f:13840[بٌ ف]ِيهِ تَ[q:2051[دْ]رُس[p[ُو]نَ","Ёки сизларнинг китобингиз бор-у, ундан ўқидингизми?",565,29],["إِ[g[نّ]َ لَكُمْ فِيهِ لَمَا تَخَيَّر[p[ُو]نَ","Унда сизларга нимани ихтиёр қилсангиз, албатта, дейилганми?!",565,29],["أَمْ لَكُمْ أَيْمَ[n[ـٰ]نٌ عَلَيْنَا بَ[n[ـٰ]لِغَةٌ إِلَىٰ يَوْمِ [h:1965[ٱ]لْقِيَ[n[ـٰ]مَةِ‌ۙ إِ[g[نّ]َ لَكُمْ لَمَا تَحْكُم[p[ُو]نَ","Ёки сизларга Бизнинг қиёмат кунигача етадиган ваъдаларимиз бўлиб, унда, албатта, сиз нима ҳукм қилсангиз шу бўлади, дейилганми?!",565,29],["سَلْهُمْ أَيُّه[c:13841[ُم ب]ِذ[n[َٲ]لِكَ زَع[p[ِي]مٌ","Сўра улардан, қай бирлари бу нарсага кафил экан?",565,29],["أَمْ لَهُمْ شُرَك[o[َا]ٓءُ فَلْيَأْتُو[s[اْ] بِشُرَك[o[َا]ٓئِهِمْ إِ[f:5674[ن ك]َانُو[s[اْ] صَ[n[ـٰ]دِق[p[ِي]نَ","Ёки уларнинг шериклари бормикин, агар ростгўй бўлсалар, ўша шерикларини ҳам олиб келсинлар.",565,29],["يَوْمَ يُكْشَفُ عَ[f:13842[ن س]َا[a:13843[قٍ و]َيُ[q:13844[دْ]عَوْنَ إِلَى [h:13845[ٱ][l[ل]سُّجُودِ فَلَا يَسْتَطِيع[p[ُو]نَ","Болдирлар шимарилган кунида ва улар саждага чақирилганда, қодир бўлмаслар.",565,29],["خَ[n[ـٰ]شِعَةً أَ[q:4718[بْ]صَ[n[ـٰ]رُهُمْ تَرْهَقُهُمْ ذِلَّ[a:13846[ةٌ‌ۖ و]َقَ[q:387[دْ] كَانُو[s[اْ] يُ[q:1815[دْ]عَوْنَ إِلَى [h:13845[ٱ][l[ل]سُّجُودِ وَهُمْ سَ[n[ـٰ]لِم[p[ُو]نَ","Уларнинг кўзлари қўрқинчга тўла, хорлик ўраб олган. Ва дарҳақиқат, улар саломатлик ҳолларида сажда қилишга чақирилган эдилар.",566,29],["فَذَرْنِى وَم[a:13847[َن ي]ُكَذِّبُ بِهَ[n[ـٰ]ذَا [h:7957[ٱ]لْحَدِيثِ‌ۖ سَنَسْتَ[q:5160[دْ]رِجُه[w:5161[ُم م]ِّنْ حَيْثُ لَا يَعْلَم[p[ُو]نَ","Бу гапни ёлғонга чиқарувчиларни Менинг Ўзимга қўйиб қўй. Биз уларни ўзлари билмаган тарафдан аста-секин оламиз.",566,29],["وَأُمْلِى لَهُمْ‌ۚ إِ[g[نّ]َ كَيْدِى مَت[p[ِي]نٌ","Ва уларга муҳлат бераман, албатта, Менинг ҳийлам метиндир.",566,29],["أَمْ تَسْــَٔلُهُمْ أَ[q:2795[جْ][f:12943[رًا ف]َه[w:12944[ُم م]ّ[a:12945[ِن م]َّغْرَ[a:12946[مٍ م]ُّثْقَل[p[ُو]نَ","Ёки сен улардан ҳақ сўраяпсану, улар қарзга ботиб қолдиларми?",566,29],["أَمْ عِ[f:3212[ند]َهُمُ [h:12947[ٱ]لْغَيْبُ فَهُمْ يَكْتُب[p[ُو]نَ","Ёки ҳузурларида ғойиб илми бору, улар ёзиб оладиларми?",566,29],["فَ[h:9999[ٱ]صْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُ[f:13848[ن ك]َصَاحِبِ [h:13849[ٱ]لْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظ[p[ُو]مٌ","Роббинг ҳукмига сабр қил ва бир вақтлар ғамга тўлган ҳолда нидо қилган балиқ соҳибига ўхшама.",566,29],["لَّوْل[o[َآ] أَ[f:13850[ن ت]َد[n[َٲ]رَكَهُ[n[ۥ] نِعْمَ[a:13851[ةٌ م]ّ[u:192[ِن ر]َّبِّه[n[ِۦ] لَنُبِذَ بِ[h:11434[ٱ]لْعَر[o[َا]ٓءِ وَهُوَ مَذْم[p[ُو]مٌ","Агар уни Роббисининг неъмати топмаганда, очиқ саҳро жойга, мазамматга қолган ҳолда ташланган бўларди.",566,29],["فَ[h:9999[ٱ][q:13852[جْ]تَبَ[n[ـٰ]هُ رَبُّهُ[n[ۥ] فَجَعَلَهُ[n[ۥ] مِنَ [h:1889[ٱ][l[ل]صَّ[n[ـٰ]لِح[p[ِي]نَ","Бас, уни Роббиси танлаб олди ва солиҳ бандаларидан қилди.",566,29],["وَإ[a:13853[ِن ي]َكَادُ [h:13854[ٱ]لَّذِينَ كَفَرُو[s[اْ] لَيُزْلِقُونَكَ بِأَ[q:13855[بْ]صَ[n[ـٰ]رِهِمْ لَ[g[مّ]َا سَمِعُو[s[اْ] [h:13856[ٱ][l[ل]ذِّكْرَ وَيَقُولُونَ إِ[g[نّ]َهُ[n[ۥ] لَمَ[q:7198[جْ]ن[p[ُو]نٌ","Ва кофирлар зикрни эшитаётганларида сени кўзлари билан тойдирмоқчи бўлдилар ва, албатта, у жиннидур, дерлар.",566,29],["وَمَا هُوَ إِلَّا ذِكْ[u:6839[رٌ ل]ِّلْعَ[n[ـٰ]لَم[p[ِي]نَ","Ҳолбуки, у бутун одамларга эслатмадан ўзга нарса эмас.",566,29]]},{"n":69,"ar":"الحَاقَّةِ","en":"Al-Haaqqa","uz":"Ҳаққа","type":"Макка","ayahs":[["ٱلْح[m[َا]ٓقَّةُ","Ал-Ҳааққаҳ.",566,29],["مَا [h:13857[ٱ]لْح[m[َا]ٓقَّةُ","Ал-Ҳааққаҳ нима ўзи?!",566,29],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا [h:13857[ٱ]لْح[m[َا]ٓقَّةُ","Ал-Ҳааққаҳ нималигини сенга нима билдирди?!",566,29],["كَذَّبَتْ ثَمُودُ وَعَا[i:13859[دُۢ ب]ِ[h:13860[ٱ]لْقَارِعَةِ","Самуд ва Од қориъани ёлғонга чиқаришди.",566,29],["فَأَ[g[مّ]َا ثَمُودُ فَأُهْلِكُو[s[اْ] بِ[h:13861[ٱ][l[ل]طَّاغِيَةِ","Бас, аммо Самуд ҳаддан ошувчи билан ҳалок қилинди.",566,29],["وَأَ[g[مّ]َا عَا[f:13862[دٌ ف]َأُهْلِكُو[s[اْ] بِرِي[f:13863[حٍ ص]َرْصَرٍ عَاتِيَةٍ","Ва аммо Од қаттиқ шамол билан ҳалок қилиндилар.",566,29],["سَخَّرَهَا عَلَيْهِمْ سَ[q:158[بْ]عَ لَيَا[a:13864[لٍ و]َثَمَ[n[ـٰ]نِيَةَ أَيَّامٍ حُسُو[f:13865[مًا ف]َتَرَى [h:13866[ٱ]لْقَوْمَ فِيهَا صَرْعَىٰ كَأَ[g[نّ]َهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ","У зот уларнинг устидан бу шамолни етти кечаю саккиз кундуз бетўхтов эстириб қўйди. Бас, қавмни у ерда ҳалок бўлиб, ағдарилиб ётганини кўрасан. Улар худди хурмонинг чириган томирларига ўхшарлар.",566,29],["فَهَلْ تَرَىٰ لَه[w:1812[ُم م]ّ[i:13867[ِنۢ ب]َاقِيَةٍ","Бас, сен улардан бирортасини боқий қолганини кўрасанми?",566,29],["وَج[o[َا]ٓءَ فِرْعَوْنُ وَمَ[f:13868[ن ق]َ[q:13869[بْ]لَهُ[n[ۥ] وَ[h:13870[ٱ]لْمُؤْتَفِكَ[n[ـٰ]تُ بِ[h:13871[ٱ]لْخَاطِئَةِ","Фиръавн, ундан аввалгилар ва тўнтарилганлар хато қилдилар.",567,29],["فَعَصَوْ[s[اْ] رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَ[u:13872[ةً ر]َّابِيَةً","Бас, улар Роббиларининг Расулига осий бўлдилар. Дарҳақиқат, У зот уларни қаттиқ тутишлик билан тутди.",567,29],["إِ[g[نّ]َا لَ[g[مّ]َا طَغَا [h:13873[ٱ]لْم[o[َا]ٓءُ حَمَلْنَ[n[ـٰ]كُمْ فِى [h:13874[ٱ]لْجَارِيَةِ","Албатта, Биз сув туғёнга келган пайтда сизларни кемада кўтарганмиз.",567,29],["لِنَ[q:13875[جْ]عَلَهَا لَكُمْ تَذْكِرَ[a:13876[ةً و]َتَعِيَه[o[َآ] أُذُ[a:13877[نٌ و][n[َٲ]عِيَةٌ","Уни сизларга эслатма қилиш учун ва англовчи қулоқлар англаб олиши учун.",567,29],["فَإِذَا نُفِخَ فِى [h:4185[ٱ][l[ل]صُّورِ نَفْخَ[a:13878[ةٌ و][n[َٲ]حِدَةٌ","Қачонки дудга биргина пуфлашла пуфланса...",567,29],["وَحُمِلَتِ [h:13879[ٱ]لْأَرْضُ وَ[h:8957[ٱ]لْجِبَالُ فَدُكَّتَا دَكَّ[a:13880[ةً و][n[َٲ]حِدَةً","Ва еру тоғлар кўтарилиб, бир мартагина силкитилса...",567,29],["فَيَوْمَئِ[a:13881[ذٍ و]َقَعَتِ [h:13200[ٱ]لْوَاقِعَةُ","Бас, ўша кунда, воқеа воқеъ бўлибдир.",567,29],["وَ[h:9999[ٱ][f:13882[نش]َقَّتِ [h:13883[ٱ][l[ل]سَّم[o[َا]ٓءُ فَهِىَ يَوْمَئِ[a:13884[ذٍ و]َاهِيَةٌ","Ва осмон парчаланса, бас, ўша кунда, у беҳолдир.",567,29],["وَ[h:9999[ٱ]لْمَلَكُ عَلَ[o[ىٰٓ] أَرْج[o[َا]ٓئِهَا‌ۚ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِ[f:13885[ذٍ ث]َمَ[n[ـٰ]نِيَةٌ","Ва фаришталар унинг атрофида ва ўша кунда Роббингнинг Аршини саккизтаси кўтариб турадир.",567,29],["يَوْمَئِ[f:13886[ذٍ ت]ُعْرَضُونَ لَا تَخْفَىٰ مِ[f:344[نك]ُمْ خَافِيَةٌ","Бас, ўша кунда кўрикдан ўтасизлар, бирорта нарсангиз махфий қолмайдир.",567,29],["فَأَ[g[مّ]َا مَنْ أُوتِىَ كِتَ[n[ـٰ]بَهُ[n[ۥ] بِيَمِينِه[n[ِۦ] فَيَقُولُ ه[o[َا]ٓؤُمُ [h:13887[ٱ][q:13888[قْ]رَءُو[s[اْ] كِتَ[n[ـٰ]بِيَهْ","Бас, кимнинг китоби ўнг тарафдан берилса, у, мана, менинг китобимни ўқиб кўринглар...",567,29],["إِ[g[نّ]ِى ظَنَ[f:13889[نت]ُ أَ[g[نّ]ِى مُلَ[n[ـٰ]قٍ حِسَابِيَهْ","Албатта, мен ҳисоб-китобимга йўлиқишимга ишонардим, дейдир.",567,29],["فَهُوَ فِى عِيشَ[u:13890[ةٍ ر]َّاضِيَةٍ","Бас, у розилик ҳаётидадир.",567,29],["فِى جَ[g[نّ]َةٍ عَالِيَةٍ","Олий жаннатдадир.",567,29],["قُطُوفُهَا دَانِيَةٌ","Унинг мевалари яқиндир.",567,29],["كُلُو[s[اْ] وَ[h:300[ٱ]شْرَبُو[s[اْ] هَنِ[o[يٓـ]ـ[i:12907[ـَٔۢا ب]ِم[o[َآ] أَسْلَفْتُمْ فِى [h:13891[ٱ]لْأَيَّامِ [h:13892[ٱ]لْخَالِيَةِ","Ўтган кунларда қилган нарсаларингиз туфайли енглар ва ичинглар, ош бўлсин.",567,29],["وَأَ[g[مّ]َا مَنْ أُوتِىَ كِتَ[n[ـٰ]بَهُ[n[ۥ] بِشِمَالِه[n[ِۦ] فَيَقُولُ يَ[n[ـٰ]لَيْتَنِى لَمْ أُوتَ كِتَ[n[ـٰ]بِيَهْ","Ва аммо кимнинг китоби чап тарафдан берилса, у, вой шўрим, кошки менга китобим берилмаса эди.",567,29],["وَلَمْ أَ[q:13893[دْ]رِ مَا حِسَابِيَهْ","Ва ҳисоб-китоб қандоқлигини билмасам эди.",567,29],["يَ[n[ـٰ]لَيْتَهَا كَانَتِ [h:13894[ٱ]لْقَاضِيَةَ","Қани охиргиси бўлса эди.",567,29],["م[o[َآ] أَغْنَىٰ عَ[g[نّ]ِى مَالِيَهْۜ","Молу мулким мени сақлаб қола олмади.",567,29],["هَلَكَ عَ[g[نّ]ِى سُلْطَ[n[ـٰ]نِيَهْ","Менинг султоним ҳам ҳалок бўлди, дейдир.",567,29],["خُذُوهُ فَغُلّ[p[ُو]هُ","Тутинглар уни ва кишанланглар уни!!!",567,29],["ثُ[g[مّ]َ [h:13895[ٱ]لْجَحِيمَ صَلّ[p[ُو]هُ","Сўнгра жаҳаннамга солинглар уни!!!",567,29],["ثُ[g[مّ]َ فِى سِلْسِلَ[f:13896[ةٍ ذ]َرْعُهَا سَ[q:13897[بْ]عُونَ ذِرَا[f:13898[عًا ف]َ[h:13899[ٱ]سْلُك[p[ُو]هُ","Сўнгра етмиш қулочли занжирга киритинг уни!!!",567,29],["إِ[g[نّ]َهُ[n[ۥ] كَانَ لَا يُؤْمِنُ بِ[h:32[ٱ]للَّهِ [h:13900[ٱ]لْعَظ[p[ِي]مِ","Чунки у улуғ Аллоҳга иймон келтирмаган эди.",567,29],["وَلَا يَحُضُّ عَلَىٰ طَعَامِ [h:13901[ٱ]لْمِسْك[p[ِي]نِ","Ва мискинларга таом беришга қизиқтирмаган эди.",567,29],["فَلَيْسَ لَهُ [h:13902[ٱ]لْيَوْمَ هَ[n[ـٰ]هُنَا حَم[p[ِي]مٌ","Бас, бугунги кунда унга бу ерда бирон чин дўст йўқ.",568,29],["وَلَا طَعَامٌ إِلَّا مِنْ غِسْل[p[ِي]نٍ","Ва ғислийндан ўзга таом ҳам йўқ.",568,29],["لَّا يَأْكُلُهُ[o[ۥٓ] إِلَّا [h:13903[ٱ]لْخَ[n[ـٰ]طِــٔ[p[ُو]نَ","Уни хатокорлардан бошқа ҳеч ким емас.",568,29],["فَل[o[َآ] أُ[q:13287[قْ]سِمُ بِمَا تُ[q:8674[بْ]صِر[p[ُو]نَ","Сизлар кўриб турган нарсалар билан қасам ичурман.",568,29],["وَمَا لَا تُ[q:8674[بْ]صِر[p[ُو]نَ","Ва сизлар кўрмайдиган нарсалар билан ҳам.",568,29],["إِ[g[نّ]َهُ[n[ۥ] لَقَوْلُ رَسُو[f:13904[لٍ ك]َر[p[ِي]مٍ","Албатта у карамли Расулнинг сўзидир.",568,29],["وَمَا هُوَ بِقَوْلِ شَاعِ[f:13905[رٍ‌ۚ ق]َلِيل[a:4583[اً م]َّا تُؤْمِن[p[ُو]نَ","Ва у шоирнинг сўзи эмас. Сизлар жуда оз ишонасизлар.",568,29],["وَلَا بِقَوْلِ كَاهِ[f:13906[نٍ‌ۚ ق]َلِيل[a:4583[اً م]َّا تَذَكَّر[p[ُو]نَ","Ва фолбиннинг ҳам сўзи эмас. Сизлар жуда оз эсларсизлар.",568,29],["تَ[f:11949[نز]ِي[a:12045[لٌ م]ّ[u:4772[ِن ر]َّبِّ [h:4[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Оламлар Роббисидан туширилгандир.",568,29],["وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ [h:13907[ٱ]لْأَقَاو[p[ِي]لِ","Ва агар у Бизнинг баъзи ёлғон сўзларни тўқиса.",568,29],["لَأَخَذْنَا مِنْهُ بِ[h:11402[ٱ]لْيَم[p[ِي]نِ","Албатта, Биз уни қудрат билан тутармиз.",568,29],["ثُ[g[مّ]َ لَقَطَعْنَا مِنْهُ [h:13908[ٱ]لْوَت[p[ِي]نَ","Сўнгра, албатта, унинг шоҳ томирини кесармиз.",568,29],["فَمَا مِ[f:344[نك][w:431[ُم م]ِّنْ أَحَدٍ عَنْهُ حَ[n[ـٰ]جِز[p[ِي]نَ","Бас, сизлардан ҳеч ким уни тўсиб қола олмас.",568,29],["وَإِ[g[نّ]َهُ[n[ۥ] لَتَذْكِرَ[u:13909[ةٌ ل]ِّلْمُتَّق[p[ِي]نَ","Ва, албатта, у тақводорлар учун эслатмадир.",568,29],["وَإِ[g[نّ]َا لَنَعْلَمُ أَ[g[نّ]َ مِ[f:344[نك][w:13910[ُم م]ُّكَذِّب[p[ِي]نَ","Ва, албата, Биз сизларнинг ичингизда ёлғонга чиқарувчилар борлигини билиб турамиз.",568,29],["وَإِ[g[نّ]َهُ[n[ۥ] لَحَسْرَةٌ عَلَى [h:468[ٱ]لْكَ[n[ـٰ]فِر[p[ِي]نَ","Ва албатта у кофирлар учун ҳасратдир.",568,29],["وَإِ[g[نّ]َهُ[n[ۥ] لَحَقُّ [h:13911[ٱ]لْيَق[p[ِي]نِ","Ва албатта у шубҳасиз ҳақиқатдир.",568,29],["فَسَبِّحْ بِ[h:13285[ٱ]سْمِ رَبِّكَ [h:13286[ٱ]لْعَظ[p[ِي]مِ","Бас, улуғ Роббингнинг исмини поклаб ёд эт.",568,29]]},{"n":70,"ar":"المَعَارِجِ","en":"Al-Ma'aarij","uz":"Маориж","type":"Макка","ayahs":[["سَأَلَ س[o[َا]ٓئِ[i:13912[لُۢ ب]ِعَذَا[a:13913[بٍ و]َاقِعٍ","Сўровчи воқеъ бўлувчи азоб ҳақида сўради.",568,29],["لِّلْكَ[n[ـٰ]فِرِينَ لَيْسَ لَهُ[n[ۥ] دَافِعٌ","Кофирлар устига. Уни даф қилувчи йўқдир.",568,29],["مِّنَ [h:321[ٱ]للَّهِ ذِى [h:13914[ٱ]لْمَعَارِ[q[ج]ِ","У маъорижлар эгаси Аллоҳдандир.",568,29],["تَعْرُجُ [h:13915[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ وَ[h:13916[ٱ][l[ل]رُّوحُ إِلَيْهِ فِى يَوْ[f:10625[مٍ ك]َانَ مِ[q:10626[قْ]دَارُهُ[n[ۥ] خَمْسِينَ أَلْفَ سَنَةٍ","Фаришталар ва Руҳ Унинг ҳузурига миқдори эллик минг йил бўлган кунда кўтариладир.",568,29],["فَ[h:9999[ٱ]صْبِرْ صَ[q:1427[بْ][f:13917[رًا ج]َمِيلاً","Бас, чиройли сабр қил.",568,29],["إِ[g[نّ]َهُمْ يَرَوْنَهُ[n[ۥ] بَعِيدًا","Албатта, улар уни узоқ деб билурлар.",568,29],["وَنَرَ[n[ٮٰ]هُ قَرِيبًا","Ва Биз уни жуда яқин деб билурмиз.",568,29],["يَوْمَ تَكُونُ [h:13918[ٱ][l[ل]سَّم[o[َا]ٓءُ كَ[h:8046[ٱ]لْمُهْلِ","У кунда осмон худди қора мой қолдиқларига ўхшаб қоладир.",568,29],["وَتَكُونُ [h:13919[ٱ]لْجِبَالُ كَ[h:13920[ٱ]لْعِهْنِ","Ва тоғлар худди титилган жунга ўхшаб қоладир.",568,29],["وَلَا يَسْــَٔلُ حَمِيمٌ حَمِيمًا","Ва яқин дўст ўз дўстидан сўрамайдир.",568,29],["يُبَصَّرُونَهُمْ‌ۚ يَوَدُّ [h:13921[ٱ]لْمُ[q:13922[جْ]رِمُ لَوْ يَفْتَدِى مِنْ عَذَابِ يَوْمِئِ[i:13923[ذِۭ ب]ِبَن[p[ِي]هِ","Уларни кўриб турурлар. Гуноҳкор ўша кун азобидан қутулиш учун ўз болаларини ҳам.",569,29],["وَصَ[n[ـٰ]حِبَتِه[n[ِۦ] وَأَخ[p[ِي]هِ","Хотинини ва ака-укасини ҳам,",569,29],["وَفَصِيلَتِهِ [h:13924[ٱ]لَّتِى تُــْٔو[p[ِي]هِ","Ва уни ўзига олган қабиласини ҳам.",569,29],["وَمَ[f:3453[ن ف]ِى [h:44[ٱ]لْأَرْضِ جَمِي[f:155[عًا ث]ُ[g[مّ]َ يُ[f:13925[نج][p[ِي]هِ","Ва ер юзидаги жамийки кимсаларни ҳам фидо қилишни, сўнгра ўзи нажот топишни истайдир.",569,29],["كَلّ[o[َآ‌ۖ] إِ[g[نّ]َهَا لَظَىٰ","Йўқ! Албатта у кучли алангадир.",569,29],["نَزَّاعَ[u:13926[ةً ل]ِّلشَّوَىٰ","Бошнинг терисини сидириб олувчидир.",569,29],["تَ[q:7934[دْ]عُو[s[اْ] مَنْ أَ[q:13927[دْ]بَرَ وَتَوَلَّىٰ","У чақирадир; орқага кетган ва юз ўгирганни.",569,29],["وَجَمَعَ فَأَوْعَىٰٓ","Ва йиғиб беркитганни.",569,29],["۞ إِ[g[نّ]َ [h:7137[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ خُلِقَ هَلُوعًا","Албатта, инсон «ҳалуъ» қилиб яратилгандир.",569,29],["إِذَا مَسَّهُ [h:7875[ٱ][l[ل]شَّرُّ جَزُوعًا","Агар унга ёмонлик етса, чидамсиздир.",569,29],["وَإِذَا مَسَّهُ [h:13928[ٱ]لْخَيْرُ مَنُوعًا","Ва агар яхшилик етса, кўп ман қилувчидир.",569,29],["إِلَّا [h:13929[ٱ]لْمُصَلّ[p[ِي]نَ","Магара намоз ўқувчиларгина мустаснодир.",569,29],["ٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ د[o[َا]ٓئِم[p[ُو]نَ","Улар намозларида доим бўладиганлардир.",569,29],["وَ[h:9999[ٱ]لَّذِينَ ف[o[ِىٓ] أَمْو[n[َٲ]لِهِمْ حَ[a:13930[قٌّ م]َّعْل[p[ُو]مٌ","Уларнинг молу мулкларида мвълум ҳақ бордир.",569,29],["لِّلسّ[o[َا]ٓئِلِ وَ[h:12851[ٱ]لْمَحْر[p[ُو]مِ","Сўровчи ва бечоралар учундир.",569,29],["وَ[h:9999[ٱ]لَّذِينَ يُصَدِّقُونَ بِيَوْمِ [h:13931[ٱ][l[ل]دّ[p[ِي]نِ","Ва улар қиёмат кунини тасдиқлайдиганлардир.",569,29],["وَ[h:9999[ٱ]لَّذِينَ ه[w:9232[ُم م]ِّنْ عَذَابِ رَبِّه[w:9233[ِم م]ُّشْفِق[p[ُو]نَ","Ва улар ўз Роббилари азобидан қўрқадиганлардир.",569,29],["إِ[g[نّ]َ عَذَابَ رَبِّهِمْ غَيْرُ مَأْم[p[ُو]نٍ","Албатта Роббиларининг азобидан омонлик йўқдир.",569,29],["وَ[h:9999[ٱ]لَّذِينَ هُمْ لِفُرُوجِهِمْ حَ[n[ـٰ]فِظ[p[ُو]نَ","Ва улар ўз фаржларини сақлайдиганлардир.",569,29],["إِلَّا عَلَ[o[ىٰٓ] أَزْو[n[َٲ]جِهِمْ أَوْ مَا مَلَكَتْ أَيْمَ[n[ـٰ]نُهُمْ فَإِ[g[نّ]َهُمْ غَيْرُ مَلُوم[p[ِي]نَ","Магарам ўз хотинлари ёки ўз мулки бўлганлар мустаснодир. Албатта улар бунга маломат қилинмайдир.",569,29],["فَمَنِ [h:9139[ٱ][q:9140[بْ]تَغَىٰ وَر[o[َا]ٓءَ ذ[n[َٲ]لِكَ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:9141[ٱ]لْعَاد[p[ُو]نَ","Кимки ўшандан ўзгани истаса, бас, улар чегарадан чиққанлардир.",569,29],["وَ[h:9999[ٱ]لَّذِينَ هُمْ لِأَمَ[n[ـٰ]نَ[n[ـٰ]تِهِمْ وَعَهْدِهِمْ ر[n[َٲ]ع[p[ُو]نَ","Улар омонатларига ва аҳдларига риоя қиладиганлардир.",569,29],["وَ[h:9999[ٱ]لَّذِينَ ه[c:13932[ُم ب]ِشَهَ[n[ـٰ]د[n[َٲ]تِهِمْ ق[o[َا]ٓئِم[p[ُو]نَ","Ва улар гувоҳликларини тўғри берадиганлардир.",569,29],["وَ[h:9999[ٱ]لَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظ[p[ُو]نَ","Улар намозларини муҳофаза қиладиганлардир.",569,29],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ فِى جَ[g[نّ]َ[n[ـٰ][a:13933[تٍ م]ُّكْرَم[p[ُو]نَ","Ўшалар жаннатларда ҳурматланадиганлардир.",569,29],["فَمَالِ [h:13934[ٱ]لَّذِينَ كَفَرُو[s[اْ] قِبَلَكَ مُهْطِع[p[ِي]نَ","Куфр келтирганларга нима бўлдики, бўйинларини чўзиб сен томон шошмоқдалар?!",569,29],["عَنِ [h:7424[ٱ]لْيَمِينِ وَعَنِ [h:12807[ٱ][l[ل]شِّمَالِ عِز[p[ِي]نَ","Ўнг тарафдан ва чап тарафдан тўп-тўп бўлмоқдалар?!",569,29],["أَيَ[q:13935[طْ]مَعُ كُلُّ [h:12916[ٱ]مْرِى[a:9346[ٍٕ م]ِّنْهُمْ أ[a:13936[َن ي]ُ[q:13937[دْ]خَلَ جَ[g[نّ]َةَ نَع[p[ِي]مٍ","Улардан ҳар бир киши наъим жаннатга киритилишни тамаъ қиладими?",569,29],["كَلّ[o[َآ‌ۖ] إِ[g[نّ]َا خَلَ[q:11326[قْ]نَ[n[ـٰ]ه[w:13938[ُم م]ِّ[g[مّ]َا يَعْلَم[p[ُو]نَ","Йўқ! Албатта, Биз уларни ўзлари билган нарсадан яратганмиз.",569,29],["فَل[o[َآ] أُ[q:13287[قْ]سِمُ بِرَبِّ [h:13939[ٱ]لْمَشَ[n[ـٰ]رِقِ وَ[h:13940[ٱ]لْمَغَ[n[ـٰ]رِبِ إِ[g[نّ]َا لَقَ[n[ـٰ]دِر[p[ُو]نَ","Машриқлар ва мағриблар Роббиси билан қасам ичаманки, албатта Биз қодирмиз.",570,29],["عَلَ[o[ىٰٓ] أ[a:13265[َن ن]ُّبَدِّلَ خَيْ[a:12743[رًا م]ِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوق[p[ِي]نَ","Ўринларига улардан яхшироқларини алмаштиришга қодирмиз ва Биз бу ишни қилишдан ожиз эмасмиз.",570,29],["فَذَرْهُمْ يَخُوضُو[s[اْ] وَيَلْعَبُو[s[اْ] حَتَّىٰ يُلَ[n[ـٰ]قُو[s[اْ] يَوْمَهُمُ [h:12321[ٱ]لَّذِى يُوعَد[p[ُو]نَ","Уларни тек қўй. То ваъда қилинган кунга йўлиққунларича хоҳлаганларига шўнғийверсинлар ва ўйнайверсинлар.",570,29],["يَوْمَ يَخْرُجُونَ مِنَ [h:11261[ٱ]لْأَ[q:11262[جْ]دَاثِ سِرَا[f:13941[عًا ك]َأَ[g[نّ]َهُمْ إِلَىٰ نُصُ[a:13942[بٍ ي]ُوفِض[p[ُو]نَ","У кунда худди санамлар шошганларидек, қабрларидан шошиб чиқурлар.",570,29],["خَ[n[ـٰ]شِعَةً أَ[q:4718[بْ]صَ[n[ـٰ]رُهُمْ تَرْهَقُهُمْ ذِلَّ[f:13943[ةٌ‌ۚ ذ][n[َٲ]لِكَ [h:13944[ٱ]لْيَوْمُ [h:13945[ٱ]لَّذِى كَانُو[s[اْ] يُوعَد[p[ُو]نَ","Кўзлари қўрқинчга тўлган, ўзларини хорлик қоплаган ҳолда турурлар. Бу ўша-уларга ваъда қилинган кундир.",570,29]]},{"n":71,"ar":"نُوحٍ","en":"Nooh","uz":"Нуҳ","type":"Макка","ayahs":[["إِ[g[نّ][o[َآ] أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِه[o[ِۦٓ] أَنْ أَ[f:13946[نذ]ِرْ قَوْمَكَ مِ[f:1346[ن ق]َ[q:1347[بْ]لِ أ[a:4887[َن ي]َأْتِيَهُمْ عَذَابٌ أَل[p[ِي]مٌ","Биз Нуҳни ўз қавмига, қавмингни уларга аламли азоб келишидан аввал огоҳлантиргин деб, Пайғамбар қилиб юбордик.",570,29],["قَالَ يَ[n[ـٰ]قَوْمِ إِ[g[نّ]ِى لَكُمْ نَذِي[a:5164[رٌ م]ُّب[p[ِي]نٌ","У: «Эй қавмим, албатта мен сиз учун очиқ-ойдин огоҳлантирувчиман.",570,29],["أَنِ [h:3899[ٱ]عْبُدُو[s[اْ] [h:3704[ٱ]للَّهَ وَ[h:4181[ٱ]تَّقُوهُ وَأَطِيع[p[ُو]نِ","Аллоҳга ибодат қилинглар, Унга тақво қилинглар ва менга итоат қилинглар.",570,29],["يَغْفِرْ لَك[w:556[ُم م]ِّ[f:7063[ن ذ]ُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَ[o[ىٰٓ] أَجَ[a:1657[لٍ م]ُّسَ[g[مّ]ًى‌ۚ إِ[g[نّ]َ أَجَلَ [h:10285[ٱ]للَّهِ إِذَا ج[o[َا]ٓءَ لَا يُؤَخَّرُ‌ۖ لَوْ كُ[f:100[نت]ُمْ تَعْلَم[p[ُو]نَ","У сизларнинг гуноҳларингиздан мағфират қиладир ва сизни белгиланган ажалгача қўйиб қўядир. Агар билсангиз, албатта, Аллоҳнинг ажали орқага сурилмайдир», деди.",570,29],["قَالَ رَبِّ إِ[g[نّ]ِى دَعَوْتُ قَوْمِى لَيْل[a:13947[اً و]َنَهَارًا","У: «Роббим, мен ўз қавмимни кечаю кундуз даъват қилдим.",570,29],["فَلَمْ يَزِ[q:13948[دْ]هُمْ دُع[o[َا]ٓء[o[ِىٓ] إِلَّا فِرَارًا","Менинг чақириғим уларда қочишдан бошқа нарсани зиёда қилмади.",570,29],["وَإِ[g[نّ]ِى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَل[o[ُوٓ][s[اْ] أَصَ[n[ـٰ]بِعَهُمْ ف[o[ِىٓ] ءَاذَانِهِمْ وَ[h:13949[ٱ]سْتَغْشَوْ[s[اْ] ثِيَابَهُمْ وَأَصَرُّو[s[اْ] وَ[h:3326[ٱ]سْتَكْبَرُو[s[اْ] [h:13950[ٱ]سْتِكْبَارًا","Ва алабатта қачонки мен уларни сенинг мағфират қилишинг учун чақирсам, улар бармоқларини қулоқларига тиқдилар ва кийимларига бурканиб олдилар ва собит бўлдилар ва ниҳоятда улкан такаббурлик қилдилар.",570,29],["ثُ[g[مّ]َ إِ[g[نّ]ِى دَعَوْتُهُمْ جِهَارًا","Сўнгра, албатта мен уларни очиқ даъват қилдим.",570,29],["ثُ[g[مّ]َ إِ[g[نّ][o[ِىٓ] أَعْلَ[f:13951[نت]ُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًا","Сўнгра, албатта мен уларга эълон ва сиррий қилдим.",570,29],["فَقُلْتُ [h:13952[ٱ]سْتَغْفِرُو[s[اْ] رَبَّكُمْ إِ[g[نّ]َهُ[n[ۥ] كَانَ غَفَّارًا","Бас, ўз Роббингизга истиғфор айтинг, албатта у гуноҳларни кўплаб мағфират қилувчидир, дедим.",570,29],["يُرْسِلِ [h:6377[ٱ][l[ل]سَّم[o[َا]ٓءَ عَلَيْك[w:6378[ُم م]ِّ[q:3932[دْ]رَارًا","У зот осмондан устингизга кетма-кет юборадир.",571,29],["وَيُمْدِ[q:13953[دْ]ك[c:13954[ُم ب]ِأَمْو[n[َٲ][a:7671[لٍ و]َبَنِينَ وَيَ[q:9574[جْ]عَل لَّكُمْ جَ[g[نّ]َ[n[ـٰ][a:13955[تٍ و]َيَ[q:9574[جْ]عَل لَّكُمْ أَنْهَ[n[ـٰ]رًا","Ва сизга молу мулк ва бола-чақа ила мадад берадир ва сизларга боғу роғлар ҳамда анқорларни берадир.",571,29],["مَّا لَكُمْ لَا تَرْجُونَ لِلَّهِ وَقَارًا","Сизларга нима бўлдики, Аллоҳнинг азаматини ўйлаб кўрмайсизлар?",571,29],["وَقَ[q:387[دْ] خَلَقَكُمْ أَ[q:13956[طْ]وَارًا","Ҳолбуки, у сизларни ҳолатма-ҳолат яратди.",571,29],["أَلَمْ تَرَوْ[s[اْ] كَيْفَ خَلَقَ [h:1272[ٱ]للَّهُ سَ[q:158[بْ]عَ سَمَ[n[ـٰ]و[n[َٲ][f:13760[تٍ ط]ِبَاقًا","Аллоҳ еттти осмонни қандоқ қилиб табақама-табақа яратиб қўйганини кўрмадингизми?",571,29],["وَجَعَلَ [h:13957[ٱ]لْقَمَرَ فِيهِ[g[نّ]َ نُو[a:13958[رًا و]َجَعَلَ [h:13959[ٱ][l[ل]شَّمْسَ سِرَاجًا","Ва улар ичида ойни нур ва қуёшни чироқ қилиб қўйганини кўрмадингизми?",571,29],["وَ[h:9999[ٱ]للَّهُ أَ[i:13960[نۢب]َتَك[w:13961[ُم م]ِّنَ [h:1579[ٱ]لْأَرْضِ نَبَاتًا","Ва Аллоҳ сизларни ердан ўстириб чиқарадир.",571,29],["ثُ[g[مّ]َ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًا","Сўнгра сизларни унга қайтариб, яна чиқарадир.",571,29],["وَ[h:9999[ٱ]للَّهُ جَعَلَ لَكُمُ [h:87[ٱ]لْأَرْضَ بِسَاطًا","Ва Аллоҳ сизларга ерни гиламдек тўшаб қўйди.",571,29],["لِّتَسْلُكُو[s[اْ] مِنْهَا سُبُل[f:13962[اً ف]ِجَاجًا","Унда сиз кенг йўллардан юришингиз учун», деб айтдим.",571,29],["قَالَ نُو[u:13963[حٌ ر]َّبِّ إِ[g[نّ]َهُمْ عَصَوْنِى وَ[h:2433[ٱ]تَّبَعُو[s[اْ] م[u:11941[َن ل]َّمْ يَزِ[q:13964[دْ]هُ مَالُهُ[n[ۥ] وَوَلَدُهُ[o[ۥٓ] إِلَّا خَسَارًا","Нуҳ: «Эй Роббим, албатта улар менга исён қилдилар ва моли, бола-чақаси хусрондан бошқани зиёда қилмаганга эргашдилар.",571,29],["وَمَكَرُو[s[اْ] مَكْ[f:13965[رًا ك]ُبَّارًا","Ва ниҳоятда улкан макр қилдилар.",571,29],["وَقَالُو[s[اْ] لَا تَذَرُ[g[نّ]َ ءَالِهَتَكُمْ وَلَا تَذَرُ[g[نّ]َ وَد[a:13966[ًّا و]َلَا سُوَا[a:13967[عًا و]َلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا","Ва улар: «Олиҳаларингизни ҳеч тарк қилманглар ва албатта Ваддни ҳам, Суваъни ҳам, Яғусни ҳам, Яъуқни ҳам ва Насрни ҳам тарк қилманг», дедилар.",571,29],["وَقَ[q:387[دْ] أَضَلُّو[s[اْ] كَثِي[a:13968[رًا‌ۖ و]َلَا تَزِدِ [h:13969[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ إِلَّا ضَلَ[n[ـٰ]لاً","Дарҳақиқат улар кўпларини адаштирдилар ва сен золимларга залолатдан бошқани зиёда қилма», деди.",571,29],["مِّ[g[مّ]َا خَط[o[ِيٓ]ـَٔ[n[ـٰ]تِهِمْ أُغْرِقُو[s[اْ] فَأُ[q:13970[دْ]خِلُو[s[اْ] نَا[f:13971[رًا ف]َلَمْ يَجِدُو[s[اْ] لَه[w:1812[ُم م]ِّ[f:107[ن د]ُونِ [h:108[ٱ]للَّهِ أَ[f:13972[نص]َارًا","Улар хатолари туфайли ғарқ қилиндилар, бас, дўзахга киритилдилар. Бас, ўзларига Аллоҳдан ўзга ёрдамчи топа олмадилар.",571,29],["وَقَالَ نُو[u:13963[حٌ ر]َّبِّ لَا تَذَرْ عَلَى [h:7958[ٱ]لْأَرْضِ مِنَ [h:182[ٱ]لْكَ[n[ـٰ]فِرِينَ دَيَّارًا","Ва Нуҳ: «Эй Роббим, ер юзида кофирлардан бирорта ҳам ҳаракатланувчини қўймагин.",571,29],["إِ[g[نّ]َكَ إِ[f:13973[ن ت]َذَرْهُمْ يُضِلُّو[s[اْ] عِبَادَكَ وَلَا يَلِد[o[ُوٓ][s[اْ] إِلَّا فَاجِ[f:13974[رًا ك]َفَّارًا","Албатта сен уларни тек қўйсанг, бандаларингни адаштирурлар ва фожиру кофирдан бошқа туғмаслар.",571,29],["رَّبِّ [h:5032[ٱ]غْفِرْ لِى وَلِو[n[َٲ]لِدَىَّ وَلِمَ[f:13975[ن د]َخَلَ بَيْتِىَ مُؤْمِ[a:13976[نًا و]َلِلْمُؤْمِنِينَ وَ[h:5718[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ وَلَا تَزِدِ [h:13969[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ إِلَّا تَبَارَۢا","Роббим, мени мағфират қилгин, менинг ота-онамни ҳам ва уйимга мўмин бўлиб кирганларни ва мўминлару мўминаларни ҳам. Ва золимларга ҳалокатдан ўзга нарсани зиёда қилмагин», деди.",571,29]]},{"n":72,"ar":"الجِنِّ","en":"Al-Jinn","uz":"Жин","type":"Макка","ayahs":[["قُلْ أُوحِىَ إِلَىَّ أَ[g[نّ]َهُ [h:13977[ٱ]سْتَمَعَ نَفَ[a:13978[رٌ م]ِّنَ [h:4673[ٱ]لْجِ[g[نّ]ِ فَقَال[o[ُوٓ][s[اْ] إِ[g[نّ]َا سَمِعْنَا قُرْءَانًا عَجَبًا","Сен айт: «Менга ваҳий қилиндики, Албатта жинлардан нафари қулоқ осдилар ва дедилар: «Биз ажойиб Қуръонни эшитдик.",572,29],["يَهْد[o[ِىٓ] إِلَى [h:13979[ٱ][l[ل]رُّشْدِ فَـَٔـامَ[g[نّ]َا بِه[n[ِۦ]‌ۖ وَل[a:13980[َن ن]ُّشْرِكَ بِرَبِّن[o[َآ] أَحَدًا","У тўғри йўлга ҳидоят қилур. Бас, биз унга иймон келтирдик ва ўз Роббимизга бировни ширк келтирмасмиз.",572,29],["وَأَ[g[نّ]َهُ[n[ۥ] تَعَ[n[ـٰ]لَىٰ جَدُّ رَبِّنَا مَا [h:9277[ٱ]تَّخَذَ صَ[n[ـٰ]حِبَ[a:13981[ةً و]َلَا وَلَدًا","Ва, албатта, Роббимизнинг азамати юксак бўлди. У ўзига хотин ва фарзанд тутгани йўқ!",572,29],["وَأَ[g[نّ]َهُ[n[ۥ] كَانَ يَقُولُ سَفِيهُنَا عَلَى [h:412[ٱ]للَّهِ شَطَطًا","Ва албатта эси пастимиз Аллоҳга ноҳақ гапларни айтарди.",572,29],["وَأَ[g[نّ]َا ظَنَ[g[نّ][o[َآ] أ[u:8842[َن ل]َّ[f:13982[ن ت]َقُولَ [h:13983[ٱ]لْإِ[f:7884[نس]ُ وَ[h:7885[ٱ]لْجِ[g[نّ]ُ عَلَى [h:412[ٱ]للَّهِ كَذِبًا","Ва, албатта, биз, инс ҳам, жин ҳам Аллоҳга ёлғон гапирмас, деб ўйлардик.",572,29],["وَأَ[g[نّ]َهُ[n[ۥ] كَانَ رِجَا[a:13984[لٌ م]ِّنَ [h:4410[ٱ]لْإِ[f:4338[نس]ِ يَعُوذُونَ بِرِجَا[a:13985[لٍ م]ِّنَ [h:4673[ٱ]لْجِ[g[نّ]ِ فَزَادُوهُمْ رَهَقًا","Албатта, инсдан баъзи кишилар, жинларнинг баъзи кишиларидан паноҳ сўрардилар. Бас, булар уларнинг гуноҳ ва хорлигини зиёда қилдилар.",572,29],["وَأَ[g[نّ]َهُمْ ظَ[g[نّ]ُو[s[اْ] كَمَا ظَنَ[f:12002[نت]ُمْ أ[u:8842[َن ل]ّ[a:11863[َن ي]َ[q:4140[بْ]عَثَ [h:11864[ٱ]للَّهُ أَحَدًا","Ва албатта улар худди сизлар гумон қилганингиздек, Аллоҳ бирор кишини ўлгандан сўнг тирилтирмас, деб гумон қилардилар.",572,29],["وَأَ[g[نّ]َا لَمَسْنَا [h:13986[ٱ][l[ل]سَّم[o[َا]ٓءَ فَوَجَ[q:13987[دْ]نَ[n[ـٰ]هَا مُلِئَتْ حَرَ[f:13988[سًا ش]َدِي[a:13989[دًا و]َشُهُبًا","Ва албатта биз осмонга талаб қилдик. Бас, уни кучли қўриқчиларга ва учқунларга тўлган ҳолда кўрдик.",572,29],["وَأَ[g[نّ]َا كُ[g[نّ]َا نَ[q:13990[قْ]عُدُ مِنْهَا مَقَ[n[ـٰ]عِدَ لِلسَّمْعِ‌ۖ فَم[a:13991[َن ي]َسْتَمِعِ [h:13992[ٱ]لْأَنَ يَجِ[q:1067[دْ] لَهُ[n[ۥ] شِهَا[u:13993[بًا ر]َّصَدًا","Ва, алабатта, биз уда тинглашга қулай жойларга жойлашиб олар эдик. Энди эса, ким қулоқ солса, ўзини пойлаб турган учқунга дучор бўладир.",572,29],["وَأَ[g[نّ]َا لَا نَ[q:12439[دْ]ر[o[ِىٓ] أَشَرٌّ أُرِيدَ بِمَ[f:7793[ن ف]ِى [h:44[ٱ]لْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا","Ва, албатта, биз ер юзидагиларга ёмонлик ирода қилиндими ёки Роббилари уларга рушдни ирода қилдими-билмасмиз.",572,29],["وَأَ[g[نّ]َا مِ[g[نّ]َا [h:13994[ٱ][l[ل]صَّ[n[ـٰ]لِحُونَ وَمِ[g[نّ]َا دُونَ ذ[n[َٲ]لِكَ‌ۖ كُ[g[نّ]َا طَر[o[َا]ٓئِقَ قِدَدًا","Ва, албатта, биздан солиҳлар ҳам ва бошқалар ҳам бор. Турли гуруҳлар бўлган эдик.",572,29],["وَأَ[g[نّ]َا ظَنَ[g[نّ][o[َآ] أ[u:8842[َن ل]ّ[a:13995[َن ن]ُّعْجِزَ [h:13996[ٱ]للَّهَ فِى [h:44[ٱ]لْأَرْضِ وَل[a:13997[َن ن]ُّعْجِزَهُ[n[ۥ] هَرَبًا","Ва, албатта, биз Аллоҳни ер юзида ожиз қолдира олмаслигимизга ва ундан қочиб қутила олмаслигимизга ишондик.",572,29],["وَأَ[g[نّ]َا لَ[g[مّ]َا سَمِعْنَا [h:13998[ٱ]لْهُدَ[o[ىٰٓ] ءَامَ[g[نّ]َا بِه[n[ِۦ]‌ۖ فَم[a:13999[َن ي]ُؤْم[i:14000[ِنۢ ب]ِرَبِّه[n[ِۦ] فَلَا يَخَافُ بَخْ[a:14001[سًا و]َلَا رَهَقًا","Ва, албатта, биз ҳидоятни эшитган пайтимизда унга иймон келтирдик. Кимки ўз Роббисига иймон келтирса, савоби озайиб қолишдан ҳам, унга оғир юк юкланишидан ҳам қўрқмас.",572,29],["وَأَ[g[نّ]َا مِ[g[نّ]َا [h:14002[ٱ]لْمُسْلِمُونَ وَمِ[g[نّ]َا [h:14003[ٱ]لْقَ[n[ـٰ]سِطُونَ‌ۖ فَمَنْ أَسْلَمَ فَأُ[s[وْ]لَ[o[ـٰٓ]ئِكَ تَحَرَّوْ[s[اْ] رَشَدًا","Ва, албатта, биздан мусулмонлар ва биздан адашганлар бор. Кимлар Исломга кирса, бас, улар ҳақ йўлни танлабдилар.",573,29],["وَأَ[g[مّ]َا [h:14004[ٱ]لْقَ[n[ـٰ]سِطُونَ فَكَانُو[s[اْ] لِجَهَ[g[نّ]َمَ حَطَبًا","Ва, аммо, адашганлар, бас, жаҳаннамга ўтин бўлибдилар.",573,29],["وَأَلَّوِ [h:14005[ٱ]سْتَقَ[n[ـٰ]مُو[s[اْ] عَلَى [h:14006[ٱ][l[ل]طَّرِيقَةِ لَأَسْقَيْنَ[n[ـٰ]ه[w:14007[ُم م]ّ[o[َا]ٓءً غَدَقًا","Ва агар улар тўғри йўлда мустақим бўлсалар, албатта, Биз кўп сув ила суғорамиз.",573,29],["لِّنَفْتِنَهُمْ فِيهِ‌ۚ وَم[a:14008[َن ي]ُعْرِضْ عَ[f:3773[ن ذ]ِكْرِ رَبِّه[n[ِۦ] يَسْلُكْهُ عَذَا[f:14009[بًا ص]َعَدًا","У ила уларни синаш учун. Ва кимки ўз Роббиси зикридан юз ўригса, уни У зот қийин азобга соладир.",573,29],["وَأَ[g[نّ]َ [h:14010[ٱ]لْمَسَ[n[ـٰ]جِدَ لِلَّهِ فَلَا تَ[q:7934[دْ]عُو[s[اْ] مَعَ [h:3975[ٱ]للَّهِ أَحَدًا","Ва, алабатта, масжидлар Аллоҳникидир. Бас, Аллоҳдан бошқага дуо қилманг.",573,29],["وَأَ[g[نّ]َهُ[n[ۥ] لَ[g[مّ]َا قَامَ عَ[q:8319[بْ]دُ [h:8320[ٱ]للَّهِ يَ[q:14011[دْ]عُوهُ كَادُو[s[اْ] يَكُونُونَ عَلَيْهِ لِبَدًا","Ва, албатта, Аллоҳнинг бандаси Унга ибодат қилиб турганда улар унинг атрофида от ёлидек тўпланиб, босиб юборай дейишди.",573,29],["قُلْ إِ[g[نّ]َم[o[َآ] أَ[q:6847[دْ]عُو[s[اْ] رَبِّى وَل[o[َآ] أُشْرِكُ بِه[o[ِۦٓ] أَحَدًا","Сен: «Албатта, мен фақат ўз Роббимга ибодат қиламан ва Унга ҳеч кимни ширк келтирмасман», деб айт.",573,29],["قُلْ إِ[g[نّ]ِى ل[o[َآ] أَمْلِكُ لَكُمْ ضَر[a:3719[ًّا و]َلَا رَشَدًا","Сен: «Албатта, мен сизлар учун зарарга ҳам, манфаатга ҳам молик эмасман»-деб айт.",573,29],["قُلْ إِ[g[نّ]ِى ل[a:14012[َن ي]ُجِيرَنِى مِنَ [h:321[ٱ]للَّهِ أَحَ[a:14013[دٌ و]َلَنْ أَجِدَ مِ[f:3136[ن د]ُونِه[n[ِۦ] مُلْتَحَدًا","Сен: «Албатта, мени ҳеч ким Аллоҳдан сақлаб қола олмас ва ҳаргиз Аллоҳдан ўзга пушти паноҳ топа олмасман.",573,29],["إِلَّا بَلَ[n[ـٰ][a:14014[غًا م]ِّنَ [h:321[ٱ]للَّهِ وَرِسَ[n[ـٰ]لَ[n[ـٰ]تِه[n[ِۦ]‌ۚ وَم[a:2634[َن ي]َعْصِ [h:2635[ٱ]للَّهَ وَرَسُولَهُ[n[ۥ] فَإِ[g[نّ]َ لَهُ[n[ۥ] نَارَ جَهَ[g[نّ]َمَ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَدًا","Менинг вазифам, фақат, Аллоҳнинг топшириқларини етказишдир. Кимки Аллоҳга ва Унинг Пайғамбарига бўйсунмаса, унга жаҳаннам оташи бор, унда абадий қолажаклар.",573,29],["حَتَّ[o[ىٰٓ] إِذَا رَأَوْ[s[اْ] مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِ[a:14015[رًا و]َأَقَلُّ عَدَدًا","Токи уларга ваъда қилинган нарсани кўрганларида, кимнинг ёрдамчиси заифу, кимнинг сони озлигини ҳам биларлар», деб айт.",573,29],["قُلْ إِنْ أَ[q:8888[دْ]ر[o[ِىٓ] أَقَرِي[a:14016[بٌ م]َّا تُوعَدُونَ أَمْ يَ[q:4388[جْ]عَلُ لَهُ[n[ۥ] رَبّ[o[ِىٓ] أَمَدًا","Сен: «Сизларга ваъда қилинган нарса яқинми ёки Роббим унга узоқ муддат қилганми–билмайман.",573,29],["عَ[n[ـٰ]لِمُ [h:4186[ٱ]لْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِه[o[ِۦٓ] أَحَدًا","У ғайбни билувчидир ва ҳеч кимни Ўз ғойбидан хабардор қилмайди.",573,29],["إِلَّا مَنِ [h:14017[ٱ]رْتَضَىٰ م[u:2882[ِن ر]َّسُو[f:14018[لٍ ف]َإِ[g[نّ]َهُ[n[ۥ] يَسْلُكُ م[i:4612[ِنۢ ب]َيْنِ يَدَيْهِ وَمِنْ خَلْفِه[n[ِۦ] رَصَدًا","Магар Ўзи рози бўлган Пайғамбарлар. Албатта Аллоҳ унинг олдидан ҳам, ортидан ҳам кузатиб юрувчи қўйиб қўядир.",573,29],["لِّيَعْلَمَ أَ[f:3885[ن ق]َ[q:298[دْ] أَ[q:14019[بْ]لَغُو[s[اْ] رِسَ[n[ـٰ]لَ[n[ـٰ]تِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدَۢا","Пайғамбарлар ўз Роббилари рисолаларини дарҳақиқат етказганликларини билиш учун ва Аллоҳ бандалар ҳузуридаги барча нарсани ихота қилиб олганлигини ва ҳамма нарсани адади, ҳисобини қилганлигини билиш учун», деб айт.",573,29]]},{"n":73,"ar":"المُزَّمِّلِ","en":"Al-Muzzammil","uz":"Муззаммил","type":"Макка","ayahs":[["يَ[o[ـٰٓ]أَيُّهَا [h:14020[ٱ]لْمُزَّ[g[مّ]ِلُ","Эй ўраниб ётувчи!",574,29],["قُمِ [h:14021[ٱ]لَّيْلَ إِلَّا قَلِيلاً","Кечани озгинасидан бошқасини тик туриб ўтказ!",574,29],["نِّصْفَهُ[o[ۥٓ] أَوِ [h:14022[ٱ][f:14023[نق]ُصْ مِنْهُ قَلِيلاً","Ярмини ёки ундан бир оз қисқароғини.",574,29],["أَوْ زِ[q:14024[دْ] عَلَيْهِ وَرَتِّلِ [h:14025[ٱ]لْقُرْءَانَ تَرْتِيلاً","Ёки уга яна қўш ва Қуръонни тартил билан тиловат қил.",574,29],["إِ[g[نّ]َا سَنُلْقِى عَلَيْكَ قَوْل[f:14026[اً ث]َقِيلاً","Албатта, Биз устингга оғир сўзни ташлармиз.",574,29],["إِ[g[نّ]َ نَاشِئَةَ [h:14027[ٱ]لَّيْلِ هِىَ أَشَدُّ وَ[q:14028[طْ]ـ[a:14029[ـًٔا و]َأَ[q:1684[قْ]وَمُ قِيلاً","Албатта, кечасиги ибодат кўпроқ мувофиқ келадир ва қироати тўғрироқ бўладир.",574,29],["إِ[g[نّ]َ لَكَ فِى [h:1829[ٱ][l[ل][g[نّ]َهَارِ سَ[q:14030[بْ][f:14031[حًا ط]َوِيلاً","Албатта, кундузи сенинг узоқ ишлашинг бор.",574,29],["وَ[h:9999[ٱ]ذْكُرِ [h:14032[ٱ]سْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَ[q:14033[بْ]تِيلاً","Ва Роббингнинг исмини зикр эт ва Унинг ибодатига бутунлай ажралиб чиқ.",574,29],["رَّبُّ [h:9739[ٱ]لْمَشْرِقِ وَ[h:904[ٱ]لْمَغْرِبِ ل[o[َآ] إِلَ[n[ـٰ]هَ إِلَّا هُوَ فَ[h:14034[ٱ]تَّخِذْهُ وَكِيلاً","У машриқу мағрибнинг Роббисидир. Ундан ўзга ибодатга сазовор илоҳ йўқ. Бас, Уни ўзингга вакил тут.",574,29],["وَ[h:9999[ٱ]صْبِرْ عَلَىٰ مَا يَقُولُونَ وَ[h:14035[ٱ]هْجُرْهُمْ هَ[q:14036[جْ][f:14037[رًا ج]َمِيلاً","Ва уларнинг гапларига сабр қил ва улардан чиройли четлашла, четлаб тур.",574,29],["وَذَرْنِى وَ[h:14038[ٱ]لْمُكَذِّبِينَ أُ[s[وْ]لِى [h:14039[ٱ][l[ل][g[نّ]َعْمَةِ وَمَهِّلْهُمْ قَلِيلاً","Аҳли неъмат бўлган, ёлғонга чиқарувчиларни Ўзимга қўйиб қўй ва уларга озгина муҳлат бер.",574,29],["إِ[g[نّ]َ لَدَيْن[o[َآ] أَ[f:14040[نك]َال[a:14041[اً و]َجَحِيمًا","Албатта, Бизда оғир кишанлар ва жаҳаннам бор.",574,29],["وَطَعَا[f:14042[مًا ذ]َا غُصَّ[a:14043[ةٍ و]َعَذَابًا أَلِيمًا","Ва тиқиладиган таом ва аламли азоб бор.",574,29],["يَوْمَ تَرْجُفُ [h:14044[ٱ]لْأَرْضُ وَ[h:8957[ٱ]لْجِبَالُ وَكَانَتِ [h:14045[ٱ]لْجِبَالُ كَثِي[a:14046[بًا م]َّهِيلاً","Бир кундаки, унда еру тоғлар ларзага келадир ва тоғлар оқувчи қумтепаларга айланадир.",574,29],["إِ[g[نّ][o[َآ] أَرْسَلْن[o[َآ] إِلَيْكُمْ رَسُول[f:14047[اً ش]َ[n[ـٰ]هِدًا عَلَيْكُمْ كَم[o[َآ] أَرْسَلْن[o[َآ] إِلَىٰ فِرْعَوْنَ رَسُولاً","Албатта, Биз сизларга, худди Фиръавнга Расул юборганимиздек, сиз ҳақингизда гувоҳлик берувчи Расулни юбордик.",574,29],["فَعَصَىٰ فِرْعَوْنُ [h:14048[ٱ][l[ل]رَّسُولَ فَأَخَذْنَ[n[ـٰ]هُ أَخْ[a:14049[ذًا و]َبِيلاً","Бас, Фиръавн Расулга осий бўлди ва Биз уни шиддатли азоб билан тутдик.",574,29],["فَكَيْفَ تَتَّقُونَ إِ[f:14050[ن ك]َفَرْتُمْ يَوْ[a:14051[مًا ي]َ[q:4388[جْ]عَلُ [h:14052[ٱ]لْوِلْد[n[َٲ]نَ شِيبًا","Агар кофир бўлсангиз, болаларнинг сочини оқартиб юборадиган кундан қандай сақланасиз?!",574,29],["ٱ[l[ل]سَّم[o[َا]ٓءُ مُ[f:14053[نف]َطِ[i:14054[رُۢ ب]ِه[n[ِۦ]‌ۚ كَانَ وَعْدُهُ[n[ۥ] مَفْعُولاً","Унда осмон парчаланувчидир, У зотнинг ваъдаси амалга ошадир.",574,29],["إِ[g[نّ]َ هَ[n[ـٰ]ذِه[n[ِۦ] تَذْكِرَ[f:14055[ةٌ‌ۖ ف]َمَ[f:8041[ن ش][o[َا]ٓءَ [h:14056[ٱ]تَّخَذَ إِلَىٰ رَبِّه[n[ِۦ] سَبِيلاً","Албатта, булар эслатмадир, Ким хоҳласа, ўз Робиси томон йўл оладир.",574,29],["۞ إِ[g[نّ]َ رَبَّكَ يَعْلَمُ أَ[g[نّ]َكَ تَقُومُ أَ[q:314[دْ]نَىٰ مِ[f:14057[ن ث]ُلُثَىِ [h:14058[ٱ]لَّيْلِ وَنِصْفَهُ[n[ۥ] وَثُلُثَهُ[n[ۥ] وَط[o[َا]ٓئِفَ[a:14059[ةٌ م]ِّنَ [h:523[ٱ]لَّذِينَ مَعَكَ‌ۚ وَ[h:72[ٱ]للَّهُ يُقَدِّرُ [h:14060[ٱ]لَّيْلَ وَ[h:6117[ٱ][l[ل][g[نّ]َهَارَ‌ۚ عَلِمَ أ[u:8842[َن ل]َّ[f:14061[ن ت]ُحْصُوهُ فَتَابَ عَلَيْكُمْ‌ۖ فَ[h:14062[ٱ][q:14062[قْ]رَءُو[s[اْ] مَا تَيَسَّرَ مِنَ [h:7870[ٱ]لْقُرْءَانِ‌ۚ عَلِمَ أَ[f:14063[ن س]َيَكُونُ مِ[f:344[نك][w:14064[ُم م]َّرْضَىٰ‌ۙ وَءَاخَرُونَ يَضْرِبُونَ فِى [h:44[ٱ]لْأَرْضِ يَ[q:3357[بْ]تَغُونَ مِ[f:6655[ن ف]َضْلِ [h:6656[ٱ]للَّهِ‌ۙ وَءَاخَرُونَ يُقَ[n[ـٰ]تِلُونَ فِى سَبِيلِ [h:788[ٱ]للَّهِ‌ۖ فَ[h:14062[ٱ][q:14062[قْ]رَءُو[s[اْ] مَا تَيَسَّرَ مِنْهُ‌ۚ وَأَقِيمُو[s[اْ] [h:214[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَءَاتُو[s[اْ] [h:215[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ وَأَ[q:14065[قْ]رِضُو[s[اْ] [h:14066[ٱ]للَّهَ قَرْضًا حَسَ[a:6460[نًا‌ۚ و]َمَا تُقَدِّمُو[s[اْ] لِأَ[f:574[نف]ُسِك[w:575[ُم م]ِّنْ خَيْ[f:576[رٍ ت]َجِدُوهُ عِ[f:264[ند]َ [h:408[ٱ]للَّهِ هُوَ خَيْ[a:14067[رًا و]َأَعْظَمَ أَ[q:2795[جْ][a:14068[رًا‌ۚ و]َ[h:1101[ٱ]سْتَغْفِرُو[s[اْ] [h:1102[ٱ]للَّهَ‌ۖ إِ[g[نّ]َ [h:80[ٱ]للَّهَ غَفُو[u:890[رٌ ر]َّح[p[ِي]مُۢ","Албатта, Роббинг сени кечанинг учдан биридан озроғини, ё ярмини, ё учдан бирини қоим бўлиб ўтказаётганингни ва сен билан бирга бўлганлардан ҳам бир тоифа биладир. Ва Аллоҳ кечаю кундузни Ўзи ўлчайдир. У сизлар ҳеч чидай олмаслигингизни билиб, сизларга қайтарди. Бас, Қуръондан муяссар бўлганича ўқинглар. Сизлардан келажакда касаллар бўлишини ҳам билди. Бошқалар ер юзида юриб, Аллоҳнинг фазлини ахтаришини, яна бошқалар эса, Аллоҳнинг йўлида жиҳод қилишларини. Бас, ундан муяссар бўлганича қироат қилинглар. Ва намозни қоим қилинглар, закот беринглар ва Аллоҳга яхши қарз беринглар. Ўзингиз учун нима яхшилик қилган бўлсангиз, Аллоҳнинг ҳузурида ундан яхшироғини ва улканроқ ажрни топарсизлар. Аллоҳга истиғфор айтинглар. Албатта, Аллоҳ мағфират қилувчи ва раҳмдилдир.",575,29]]},{"n":74,"ar":"المُدَّثِّرِ","en":"Al-Muddaththir","uz":"Муддассир","type":"Макка","ayahs":[["يَ[o[ـٰٓ]أَيُّهَا [h:14069[ٱ]لْمُدَّثِّرُ","Эй бурканиб ётган!",575,29],["قُمْ فَأَ[f:14070[نذ]ِرْ","Тур ва огоҳлантир!",575,29],["وَرَبَّكَ فَكَبِّرْ","Ва Роббингни улуғла!",575,29],["وَثِيَابَكَ فَطَهِّرْ","Ва кийимингни покла!",575,29],["وَ[h:9999[ٱ][l[ل]رُّ[q:14071[جْ]زَ فَ[h:14072[ٱ]هْجُرْ","Ва азобдан четлан!",575,29],["وَلَا تَمْنُ[f:14073[ن ت]َسْتَكْثِرُ","Ва кўп қилган бўлсанг ҳам, миннат қилма!",575,29],["وَلِرَبِّكَ فَ[h:6374[ٱ]صْبِرْ","Ва Роббинг учун сабр қил!",575,29],["فَإِذَا نُقِرَ فِى [h:14074[ٱ][l[ل][g[نّ]َاق[p[ُو]رِ","Ва қачонки дудга пуфланса.",575,29],["فَذ[n[َٲ]لِكَ يَوْمَئِ[a:14075[ذٍ ي]َوْمٌ عَس[p[ِي]رٌ","Ўшал кун, қийин кундир.",575,29],["عَلَى [h:468[ٱ]لْكَ[n[ـٰ]فِرِينَ غَيْرُ يَس[p[ِي]رٍ","У кофирларга осон эмасдир.",575,29],["ذَرْنِى وَمَنْ خَلَ[q:11606[قْ]تُ وَحِيدًا","Мени, Ўзим якка яратган кимса бидан қўйиб қўй.",575,29],["وَجَعَلْتُ لَهُ[n[ۥ] مَال[a:14076[اً م]َّمْدُودًا","Ва унга кўплаб молу дунё.",575,29],["وَبَنِينَ شُهُودًا","Ва ҳозиру нозир фарзандлар бериб қўйдим.",575,29],["وَمَهَّ[d:14077[د]تُّ لَهُ[n[ۥ] تَمْهِيدًا","Ва унга осонлаштириб қўйдим.",575,29],["ثُ[g[مّ]َ يَ[q:14078[طْ]مَعُ أَنْ أَز[p[ِي][q[د]َ","Сўнгра, яна зиёда қилишимни тамаъ қиладир.",575,29],["كَلّ[o[َآ‌ۖ] إِ[g[نّ]َهُ[n[ۥ] كَانَ لِأَيَ[n[ـٰ]تِنَا عَنِيدًا","Йўқ! Чунки, у Бизнинг оятларимизга саркаш эди.",575,29],["سَأُرْهِقُهُ[n[ۥ] صَعُودًا","Тезда уни машаққатли чиқишла ҳоритарман.",575,29],["إِ[g[نّ]َهُ[n[ۥ] فَكَّرَ وَقَدَّرَ","Албатта, у тафаккур қилди ва чамалаб кўрди.",576,29],["فَقُتِلَ كَيْفَ قَدَّرَ","Лаънат бўлсин унга, қандоқ ҳам чамалаб кўрди!",576,29],["ثُ[g[مّ]َ قُتِلَ كَيْفَ قَدَّرَ","Сўнгра яна лаънат бўлсин унга, қандоқ ҳам чамалаб кўрди.",576,29],["ثُ[g[مّ]َ نَظَرَ","Сўнгра назар солди.",576,29],["ثُ[g[مّ]َ عَبَسَ وَبَسَرَ","Сўнгра юзини буриштирди ва қавоғини солди.",576,29],["ثُ[g[مّ]َ أَ[q:13927[دْ]بَرَ وَ[h:181[ٱ]سْتَكْبَرَ","Сўнгра юз ўгирди ва такаббурлик қилди.",576,29],["فَقَالَ إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا سِحْ[a:14079[رٌ ي]ُؤْثَرُ","Бас, бу асар қолган сеҳрдан ўзга ҳеч нарса эмас.",576,29],["إِنْ هَ[n[ـٰ]ذ[o[َآ] إِلَّا قَوْلُ [h:14080[ٱ]لْبَشَرِ","Бу башар сўзидан ўзга ҳеч нарса эмас, деди.",576,29],["سَأُصْلِيهِ سَقَرَ","Тезда уни сақар га киритаман.",576,29],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا سَقَرُ","Ва сақар нималигини сенга нима билдирди?",576,29],["لَا تُ[q:14081[بْ]قِى وَلَا تَذَرُ","У боқий қолдирмас ва тарк ҳам қилмас.",576,29],["لَوَّاحَ[u:14082[ةٌ ل]ِّلْبَشَرِ","У терини кўп куйдирувчидир.",576,29],["عَلَيْهَا تِسْعَةَ عَشَرَ","Унинг устида ўн тўққизта бордир.",576,29],["وَمَا جَعَلْن[o[َآ] أَصْحَ[n[ـٰ]بَ [h:4701[ٱ][l[ل][g[نّ]َارِ إِلَّا مَلَ[o[ـٰٓ]ئِكَ[a:14083[ةً‌ۙ و]َمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَ[u:9071[ةً ل]ِّلَّذِينَ كَفَرُو[s[اْ] لِيَسْتَيْقِنَ [h:14084[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ وَيَزْدَادَ [h:14085[ٱ]لَّذِينَ ءَامَن[o[ُوٓ][s[اْ] إِيمَ[n[ـٰ][a:14086[نًا‌ۙ و]َلَا يَرْتَابَ [h:14087[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ وَ[h:1709[ٱ]لْمُؤْمِنُونَ‌ۙ وَلِيَقُولَ [h:14088[ٱ]لَّذِينَ فِى قُلُوبِه[w:39[ِم م]َّرَ[a:14089[ضٌ و]َ[h:1467[ٱ]لْكَ[n[ـٰ]فِرُونَ مَاذ[o[َآ] أَرَادَ [h:139[ٱ]للَّهُ بِهَ[n[ـٰ]ذَا مَثَل[f:14090[اً‌ۚ ك]َذ[n[َٲ]لِكَ يُضِلُّ [h:11866[ٱ]للَّهُ م[a:476[َن ي]َش[o[َا]ٓءُ وَيَهْدِى م[a:476[َن ي]َش[o[َا]ٓءُ‌ۚ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ‌ۚ وَمَا هِىَ إِلَّا ذِكْرَىٰ لِلْبَشَرِ","Дўзах соҳибларини фаришталардан қилганимиз ва уларнинг адади ҳам фақат кофирларни санаш учундир. Китоб берилганлар ишонч ҳосил қилишлари учундир. Ва иймонлиларнинг иймони зиёда бўлиши учундир. Китоб берилганлар ва мўминлар шак-шубҳа қилмасликлари учундир ва қалбларида касали борлар ва кофирлар, Аллоҳ бу билан нима мисолни ирода қилмоқчи, дейишлари учундир. Шундоқ қилиб Аллоҳ хоҳлаган кимсани адаштирадир ва хоҳлаган кимсани ҳидоятга соладир. Роббингнинг аскарларини Ўзидан бошқа ҳеч ким билмайдир. Ва у башарият учун эслатмадан ўзга ҳеч нарса эмасдир.",576,29],["كَلَّا وَ[h:14091[ٱ]لْقَمَرِ","Йўқ! Ой билан қасам.",576,29],["وَ[h:9999[ٱ]لَّيْلِ إِذْ أَ[q:13927[دْ]بَرَ","Ва чекинаётган тун билан қасам.",576,29],["وَ[h:9999[ٱ][l[ل]صُّ[q:14092[بْ]حِ إِذ[o[َآ] أَسْفَرَ","Ва ёришаётган тонг билан қасам.",576,29],["إِ[g[نّ]َهَا لَإِحْدَى [h:14093[ٱ]لْكُبَرِ","Албатта у улкан ларнинг биридир.",576,29],["نَذِي[u:14094[رًا ل]ِّلْبَشَرِ","Башарият учун огоҳлантирувчидир.",576,29],["لِمَ[f:14095[ن ش][o[َا]ٓءَ مِ[f:344[نك]ُمْ أ[a:14096[َن ي]َتَقَدَّمَ أَوْ يَتَأَخَّرَ","Сизлардан пешқадам бўлишни ёки ортда қолишни хоҳлаётган кимсалар учун ҳамдир.",576,29],["كُلُّ نَفْ[i:6995[سِۭ ب]ِمَا كَسَبَتْ رَهِينَةٌ","Ҳар бир шахс ўз касбининг гаровидир.",576,29],["إِلّ[o[َآ] أَصْحَ[n[ـٰ]بَ [h:14097[ٱ]لْيَم[p[ِي]نِ","Магар ўнг тараф соҳиблари мустаснодир.",576,29],["فِى جَ[g[نّ]َ[n[ـٰ][a:14098[تٍ ي]َتَس[o[َا]ٓءَل[p[ُو]نَ","Улар жаннатларда сўрарлар.",576,29],["عَنِ [h:14099[ٱ]لْمُ[q:4093[جْ]رِم[p[ِي]نَ","Гуноҳкорлардан.",576,29],["مَا سَلَكَكُمْ فِى سَقَرَ","Сизларни дўзахга нима киритди?",576,29],["قَالُو[s[اْ] لَمْ نَكُ مِنَ [h:14100[ٱ]لْمُصَلّ[p[ِي]نَ","Улар: «Намоз ўқийдиганлардан бўлмаган эдик.",576,29],["وَلَمْ نَكُ نُ[q:14101[طْ]عِمُ [h:14102[ٱ]لْمِسْك[p[ِي]نَ","Ва мискинларга таом бермаган эдик.",576,29],["وَكُ[g[نّ]َا نَخُوضُ مَعَ [h:14103[ٱ]لْخ[o[َا]ٓئِض[p[ِي]نَ","Ва ботилга шунғувчилар билан бирга шўнғир эдик.",576,29],["وَكُ[g[نّ]َا نُكَذِّبُ بِيَوْمِ [h:13931[ٱ][l[ل]دّ[p[ِي]نِ","Ва қиёмат куни ёлғонга чиқарган эдик.",576,29],["حَتَّ[o[ىٰٓ] أَتَ[n[ـٰ]نَا [h:14104[ٱ]لْيَق[p[ِي]نُ","Токи бизга ўлим келгунича», дерлар.",576,29],["فَمَا تَ[f:14105[نف]َعُهُمْ شَفَ[n[ـٰ]عَةُ [h:14106[ٱ][l[ل]شَّ[n[ـٰ]فِع[p[ِي]نَ","Бас, уларга шафоатчиларнинг шафоати манфаат бермас.",577,29],["فَمَا لَهُمْ عَنِ [h:14107[ٱ][l[ل]تَّذْكِرَةِ مُعْرِض[p[ِي]نَ","Уларга не бўлдики, эслатмадан юз ўрирурлар?!",577,29],["كَأَ[g[نّ]َهُمْ حُمُ[a:14108[رٌ م]ُّسْتَ[f:14109[نف]ِرَةٌ","Худди қаттиқ қўрққан эшаклар.",577,29],["فَرَّتْ مِ[f:14110[ن ق]َسْوَرَةِۭ","Арслондан қочгани каби.",577,29],["بَلْ يُرِيدُ كُلُّ [h:12916[ٱ]مْرِى[a:9346[ٍٕ م]ِّنْهُمْ أ[a:2024[َن ي]ُؤْتَىٰ صُحُ[a:14111[فًا م]ُّنَشَّرَةً","Балки улардан ҳар бири ўзига нашр қилинган саҳифалар берилишини ирода қиладир.",577,29],["كَلَّا‌ۖ بَل لَّا يَخَافُونَ [h:14112[ٱ]لْأَخِرَةَ","Йўқ! Балки улар охиратдан қўрқмаслар.",577,29],["كَلّ[o[َآ] إِ[g[نّ]َهُ[n[ۥ] تَذْكِرَةٌ","Йўқ! Албатта у эслатмадир.",577,29],["فَمَ[f:8041[ن ش][o[َا]ٓءَ ذَكَرَهُۥ","Бас, ким хоҳласа уни эслайдир.",577,29],["وَمَا يَذْكُرُونَ إِلّ[o[َآ] أ[a:4201[َن ي]َش[o[َا]ٓءَ [h:4334[ٱ]للَّهُ‌ۚ هُوَ أَهْلُ [h:14113[ٱ][l[ل]تَّ[q:1084[قْ]وَىٰ وَأَهْلُ [h:14114[ٱ]لْمَغْفِرَةِ","Ва фақат Аллоҳ хоҳласагина эслайдилар. У зот тақво аҳлидир ва мағфират аҳлидир.",577,29]]},{"n":75,"ar":"القِيَامَةِ","en":"Al-Qiyaama","uz":"Қиёмат","type":"Макка","ayahs":[["ل[o[َآ] أُ[q:13287[قْ]سِمُ بِيَوْمِ [h:14115[ٱ]لْقِيَ[n[ـٰ]مَةِ","Қиёмат куни билан қасам.",577,29],["وَل[o[َآ] أُ[q:13287[قْ]سِمُ بِ[h:3575[ٱ][l[ل][g[نّ]َفْسِ [h:14116[ٱ][l[ل]لَّوَّامَةِ","Ва маломатчи нафс билан қасам.",577,29],["أَيَحْسَبُ [h:14117[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ أَلّ[a:14118[َن ن]َّ[q:14119[جْ]مَعَ عِظَامَهُۥ","Инсон Бизни, унинг суякларини жамлай олмас, деб ўйларми?",577,29],["بَلَىٰ قَ[n[ـٰ]دِرِينَ عَلَ[o[ىٰٓ] أ[a:14120[َن ن]ُّسَوِّىَ بَنَانَهُۥ","Ҳа, Биз унинг бармоқ учларини ҳам асл ҳолига келтиришга қодирмиз.",577,29],["بَلْ يُرِيدُ [h:14121[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ لِيَفْجُرَ أَمَامَهُۥ","Балки инсон келажакда фисқу фужур қилишни хоҳлайдир.",577,29],["يَسْــَٔلُ أَيَّانَ يَوْمُ [h:14122[ٱ]لْقِيَ[n[ـٰ]مَةِ","У: «Қиёмат куни қачон?» деб сўрайдир.",577,29],["فَإِذَا بَرِقَ [h:14123[ٱ]لْبَصَرُ","Қачонки кўз даҳшатда лол қолса.",577,29],["وَخَسَفَ [h:14124[ٱ]لْقَمَرُ","Ва ой тутилса.",577,29],["وَجُمِعَ [h:14125[ٱ][l[ل]شَّمْسُ وَ[h:8956[ٱ]لْقَمَرُ","Ва қуёш билан ой жамланса.",577,29],["يَقُولُ [h:14126[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ يَوْمَئِذٍ أَيْنَ [h:14127[ٱ]لْمَفَرُّ","Ўшал кунда инсон, қочар жой қайда? деб қолар.",577,29],["كَلَّا لَا وَزَرَ","Йўқ! Қочадиган жой йўқ!",577,29],["إِلَىٰ رَبِّكَ يَوْمَئِذٍ [h:14128[ٱ]لْمُسْتَقَرُّ","У кунда истиқрор фақат Роббинг ҳузурида бўлар.",577,29],["يُنَبَّؤُ[s[اْ] [h:14129[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ يَوْمَئِ[i:14130[ذِۭ ب]ِمَا قَدَّمَ وَأَخَّرَ","У кунда инсонга аввалу охир қилганининг хабари берилар.",577,29],["بَلِ [h:14131[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ عَلَىٰ نَفْسِه[n[ِۦ] بَصِيرَةٌ","Ҳа, инсон ўз нафсига қарши ўзи шоҳиддир.",577,29],["وَلَوْ أَلْقَىٰ مَعَاذِيرَهُۥ","Гарчи узр-маъзурларини тўкиб соладир.",577,29],["لَا تُحَرِّكْ بِه[n[ِۦ] لِسَانَكَ لِتَعْجَلَ بِهِۦٓ","Сен шошилиб, у билан, тилингни қимирлатма.",577,29],["إِ[g[نّ]َ عَلَيْنَا جَمْعَهُ[n[ۥ] وَقُرْءَانَهُۥ","Албатта, уни жамлаш ва ўқиб бериш Бизнинг зиммамиздадир.",577,29],["فَإِذَا قَرَأْنَ[n[ـٰ]هُ فَ[h:14132[ٱ]تَّبِعْ قُرْءَانَهُۥ","Бас, Биз уни ўқисак, қироатига зеҳн солиб тур.",577,29],["ثُ[g[مّ]َ إِ[g[نّ]َ عَلَيْنَا بَيَانَهُۥ","Сўнгра уни баён қилиб бериш ҳам Бизнинг зиммамиздадир.",577,29],["كَلَّا بَلْ تُحِبُّونَ [h:14133[ٱ]لْعَاجِلَةَ","Йўқ! Балки сизлар шошар дунёни яхши кўрасизлар.",578,29],["وَتَذَرُونَ [h:14134[ٱ]لْأَخِرَةَ","Ва охиратни тарк этасизлар.",578,29],["وُجُو[a:14135[هٌ ي]َوْمَئِ[a:14136[ذٍ ن]َّاضِرَةٌ","У кунда бор чиройли юзлар.",578,29],["إِلَىٰ رَبِّهَا نَاظِرَةٌ","Роббисига назар солувчилар.",578,29],["وَوُجُو[a:14137[هٌ ي]َوْمَئِ[i:14138[ذِۭ ب]َاسِرَةٌ","Ва у кунда бор тиришиб-буришган юзлар.",578,29],["تَظُ[g[نّ]ُ أ[a:14139[َن ي]ُفْعَلَ بِهَا فَاقِرَةٌ","Ўзига умуртқасин синдирар иш бўлишига ишонар.",578,29],["كَلّ[o[َآ] إِذَا بَلَغَتِ [h:14140[ٱ][l[ل]تَّرَاقِىَ","Йўқ! жон ҳалқумга келганда.",578,29],["وَقِيلَ م[u:14141[َنْۜ ر][p[َا][q[ق]ٍ","Ва, қутқарувчи ким? деганда.",578,29],["وَظَ[g[نّ]َ أَ[g[نّ]َهُ [h:14142[ٱ]لْفِر[p[َا][q[ق]ُ","Ва, албатта, у фироқлигин билганда.",578,29],["وَ[h:9999[ٱ]لْتَفَّتِ [h:14143[ٱ][l[ل]سَّاقُ بِ[h:14144[ٱ][l[ل]سّ[p[َا][q[ق]ِ","Ва болдирлар бир-бирига алмашганда.",578,29],["إِلَىٰ رَبِّكَ يَوْمَئِذٍ [h:14145[ٱ]لْمَس[p[َا][q[ق]ُ","У кунда ҳайдаб борар жой фақат Роббинггадир.",578,29],["فَلَا صَدَّقَ وَلَا صَلَّىٰ","Бас, у тасдиқламади ва намоз ўқимади.",578,29],["وَلَ[n[ـٰ]كِ[f:14146[ن ك]َذَّبَ وَتَوَلَّىٰ","Ва лекин ёлғонга чиқарди ва юз ўгирди.",578,29],["ثُ[g[مّ]َ ذَهَبَ إِلَ[o[ىٰٓ] أَهْلِه[n[ِۦ] يَتَمَطَّىٰٓ","Сўнг ўз аҳлига керилиб борди.",578,29],["أَوْلَىٰ لَكَ فَأَوْلَىٰ","Ҳолингга вой бўлсин сенинг, вой бўлсин!",578,29],["ثُ[g[مّ]َ أَوْلَىٰ لَكَ فَأَوْلَىٰٓ","Яна ҳолингга вой бўлсин сенинг, вой бўлсин!",578,29],["أَيَحْسَبُ [h:14117[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ أ[a:14147[َن ي]ُتْرَكَ سُدًى","Инсон беҳуда тарк қилинишнинг ҳисобини қилурми?",578,29],["أَلَمْ يَكُ نُ[q:9146[طْ]فَ[a:14148[ةً م]ّ[a:14149[ِن م]َّنِ[a:14150[ىٍّ ي]ُمْنَىٰ","У манийдан оққан нутфа бўлмаганмиди?",578,29],["ثُ[g[مّ]َ كَانَ عَلَقَ[f:14151[ةً ف]َخَلَقَ فَسَوَّىٰ","Сўнг алақа бўлди. Бас бекаму-кўст этиб яратди.",578,29],["فَجَعَلَ مِنْهُ [h:14152[ٱ][l[ل]زَّوْجَيْنِ [h:13018[ٱ][l[ل]ذَّكَرَ وَ[h:929[ٱ]لْأُ[f:929[نث]َىٰٓ","Бас ундан жуфтни–эркак ва аёлни яратди.",578,29],["أَلَيْسَ ذ[n[َٲ]لِكَ بِقَ[n[ـٰ]دِرٍ عَلَ[o[ىٰٓ] أ[a:12519[َن ي]ُحْــِۧىَ [h:12520[ٱ]لْمَوْتَىٰ","Шундай зот ўликларни тирилтиришга қодир эмасми?!",578,29]]},{"n":76,"ar":"الإِنسَانِ","en":"Al-Insaan","uz":"Инсон","type":"Мадина","ayahs":[["هَلْ أَتَىٰ عَلَى [h:7873[ٱ]لْإِ[f:7874[نس]َ[n[ـٰ]نِ حِي[a:14153[نٌ م]ِّنَ [h:14154[ٱ][l[ل]دَّهْرِ لَمْ يَكُ[f:14155[ن ش]َيْـ[a:14156[ـًٔا م]َّذْكُورًا","Ҳақиқатда инсонга, у эсга олинадиган нарса бўлмаган бир замон келмадими?",578,29],["إِ[g[نّ]َا خَلَ[q:5159[قْ]نَا [h:7228[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ م[a:7325[ِن ن]ُّ[q:7326[طْ]فَةٍ أَمْشَا[a:14157[جٍ ن]َّ[q:14158[بْ]تَلِيهِ فَجَعَلْنَ[n[ـٰ]هُ سَمِيع[i:2864[َۢا ب]َصِيرًا","Албатта, Биз инсонни аралаш нутфадан яратдик. Синаш учун, бас, уни эшитадиган, кўрадиган қилдик.",578,29],["إِ[g[نّ]َا هَدَيْنَ[n[ـٰ]هُ [h:14159[ٱ][l[ل]سَّبِيلَ إِ[g[مّ]َا شَاكِ[a:14160[رًا و]َإِ[g[مّ]َا كَفُورًا","Албатта, Биз унга йўл кўрсатдик. ёки шукр қилувчи, ёки куфр қилувчи бўлди.",578,29],["إِ[g[نّ][o[َآ] أَعْتَ[q:2660[دْ]نَا لِلْكَ[n[ـٰ]فِرِينَ سَلَ[n[ـٰ]سِلَ[s[اْ] وَأَغْلَ[n[ـٰ]ل[a:14161[اً و]َسَعِيرًا","Албатта, Биз кофирлар учун занжирлар, кишанлар ва ёниб турган оловни тайёрлаб қўйдик.",578,29],["إِ[g[نّ]َ [h:14162[ٱ]لْأَ[q:14163[بْ]رَارَ يَشْرَبُونَ مِ[f:14164[ن ك]َأْ[f:14165[سٍ ك]َانَ مِزَاجُهَا كَافُورًا","Албатта, яхшилар каафур аралаштирилган қадаҳдан ичарлар.",578,29],["عَيْ[a:14166[نًا ي]َشْرَبُ بِهَا عِبَادُ [h:14167[ٱ]للَّهِ يُفَجِّرُونَهَا تَفْجِيرًا","Бир булоқданики, ундан Аллоҳнинг бандалари отилтириб ичарлар.",579,29],["يُوفُونَ بِ[h:14168[ٱ][l[ل][g[نّ]َذْرِ وَيَخَافُونَ يَوْ[f:14169[مًا ك]َانَ شَرُّهُ[n[ۥ] مُسْتَطِيرًا","Улар назрга вафо қиларлар ва ёмонлиги кенг тарқаладиган кундан қўрқарлар.",579,29],["وَيُ[q:14170[طْ]عِمُونَ [h:14171[ٱ][l[ل]طَّعَامَ عَلَىٰ حُبِّه[n[ِۦ] مِسْكِي[a:14172[نًا و]َيَتِي[a:14173[مًا و]َأَسِيرًا","Ўзлари таомни яхши кўриб турсалар ҳам, уни мискин, етим ва асирга берарлар.",579,29],["إِ[g[نّ]َمَا نُ[q:14174[طْ]عِمُكُمْ لِوَ[q:14175[جْ]هِ [h:14176[ٱ]للَّهِ لَا نُرِيدُ مِ[f:344[نك]ُمْ جَز[o[َا]ٓ[a:14177[ءً و]َلَا شُكُورًا","«Албатта, Биз сизларни фақат Аллоҳнинг розилиги учун овқатлантирамиз. Бунинг эвазига сизлардан мукофот ёки ташуккур хоҳласмиз.",579,29],["إِ[g[نّ]َا نَخَافُ م[u:10191[ِن ر]َّبِّنَا يَوْمًا عَبُو[f:14178[سًا ق]َمْطَرِيرًا","Албатта, биз қўрқинчли, шиддатли, узун кунда ўз Роббимиздан қўрқамиз»,.",579,29],["فَوَقَ[n[ـٰ]هُمُ [h:14179[ٱ]للَّهُ شَرَّ ذ[n[َٲ]لِكَ [h:14180[ٱ]لْيَوْمِ وَلَقَّ[n[ـٰ]هُمْ نَضْرَ[a:14181[ةً و]َسُرُورًا","Бас, уларни Роббилари ўшал кун шарридан сақлади ва уларга хушрўйлик ҳамда хурсандчилик ато қилди.",579,29],["وَجَزَ[n[ٮٰ]ه[c:14182[ُم ب]ِمَا صَبَرُو[s[اْ] جَ[g[نّ]َ[a:14183[ةً و]َحَرِيرًا","Ва сабр қилганликлари учун уларни боғу роғ ва ипаклар билан мукофотлади.",579,29],["مُّتَّكِــِٔينَ فِيهَا عَلَى [h:8058[ٱ]لْأَر[o[َا]ٓئِكِ‌ۖ لَا يَرَوْنَ فِيهَا شَمْ[a:14184[سًا و]َلَا زَمْهَرِيرًا","У ерда сўриларда суянган ҳолдалар. У ерда қуёшни ҳам, совуқни ҳам кўрмаслар.",579,29],["وَدَانِيَةً عَلَيْهِمْ ظِلَ[n[ـٰ]لُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلاً","Ва устиларига унинг соялари яқиндир ҳамда унинг мевалари жуда ҳам осон қилингандир.",579,29],["وَيُطَافُ عَلَيْه[c:14185[ِم ب]ِـَٔـانِيَ[a:14186[ةٍ م]ِّ[f:12249[ن ف]ِضَّ[a:14187[ةٍ و]َأَكْوَا[f:14188[بٍ ك]َانَتْ قَوَارِيرَا۟","Ва уларга кумуш идишлар ва биллурлардан бўлган қадаҳлар айлантириб турилар.",579,29],["قَوَارِيرَ[s[اْ] مِ[f:12249[ن ف]ِضَّ[f:14189[ةٍ ق]َدَّرُوهَا تَ[q:9559[قْ]دِيرًا","Биллурлар, кумушсиймон, ўлчовини келтирар.",579,29],["وَيُسْقَوْنَ فِيهَا كَأْ[f:14190[سًا ك]َانَ مِزَاجُهَا زَ[f:14191[نج]َبِيلاً","Ва улар у ерда аралашмаси занжабил бўлган қадаҳдан суғорилар",579,29],["عَيْ[f:14192[نًا ف]ِيهَا تُسَ[g[مّ]َىٰ سَلْسَبِيلاً","Уердаги салсабийл, деб номланган булоқдан.",579,29],["۞ وَيَطُوفُ عَلَيْهِمْ وِلْد[n[َٲ][a:13218[نٌ م]ُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِ[q:14193[بْ]تَهُمْ لُؤْلُ[a:14194[ؤًا م]َّ[f:9614[نث]ُورًا","Ва уларнинг атрофида абадий ёш болалар айланурлар, агар уларни кўрсанг, сочилган маржон, деб ўйларсан.",579,29],["وَإِذَا رَأَيْتَ ثَ[g[مّ]َ رَأَيْتَ نَعِي[a:14195[مًا و]َمُلْ[f:14196[كًا ك]َبِيرًا","Ва агар кўрсанг, у ерда неъматни ва улкан мулкни кўрарсан.",579,29],["عَ[n[ـٰ]لِيَهُمْ ثِيَابُ سُ[f:8054[ند]ُسٍ خُضْ[a:14197[رٌ و]َإِسْتَ[q:14198[بْ]رَ[a:14199[قٌ‌ۖ و]َحُلّ[o[ُوٓ][s[اْ] أَسَاوِرَ مِ[f:12249[ن ف]ِضَّ[a:14200[ةٍ و]َسَقَ[n[ـٰ]هُمْ رَبُّهُمْ شَرَا[f:14201[بًا ط]َهُورًا","Уларнинг устиларида яшил сундусдан ва истобрақдан кийимлар бор ва кумуш билакузуклар-ла ясанганлар ва Роббилари уларни пок шароб билан суғорар.",579,29],["إِ[g[نّ]َ هَ[n[ـٰ]ذَا كَانَ لَكُمْ جَز[o[َا]ٓ[a:14202[ءً و]َكَانَ سَعْيُك[w:14203[ُم م]َّشْكُورًا","Албатта, бу сизга мукофот бўлди, ва амалингиз қабул бўлмшдир.",579,29],["إِ[g[نّ]َا نَحْنُ نَزَّلْنَا عَلَيْكَ [h:8434[ٱ]لْقُرْءَانَ تَ[f:7929[نز]ِيلاً","Албатта, Биз сенга Қуръонни бўлак-бўлак қилиб туширдик.",579,29],["فَ[h:9999[ٱ]صْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ ءَاثِمًا أَوْ كَفُورًا","Бас, Роббинг ҳукмига сабр қил ва улардан гуноҳкор ёки кофирларига итоат қилма.",579,29],["وَ[h:9999[ٱ]ذْكُرِ [h:14032[ٱ]سْمَ رَبِّكَ بُكْرَ[a:9566[ةً و]َأَصِيلاً","Эртаю кеч Роббинг исмини зикр қил.",579,29],["وَمِنَ [h:7856[ٱ]لَّيْلِ فَ[h:14204[ٱ]سْجُ[q:14204[دْ] لَهُ[n[ۥ] وَسَبِّحْهُ لَيْل[f:14205[اً ط]َوِيلاً","Ва кечасида ҳам Унга сажда қил ва узоқ кечаларда Унга тасбиҳ айт.",580,29],["إِ[g[نّ]َ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ يُحِبُّونَ [h:14206[ٱ]لْعَاجِلَةَ وَيَذَرُونَ وَر[o[َا]ٓءَهُمْ يَوْ[f:14207[مًا ث]َقِيلاً","Албатта, анавилар шошган дунёни яхши кўрарлар ва оғир кунни ортларида қолдирарлар.",580,29],["نَّحْنُ خَلَ[q:11326[قْ]نَ[n[ـٰ]هُمْ وَشَدَ[q:11504[دْ]ن[o[َآ] أَسْرَهُمْ‌ۖ وَإِذَا شِئْنَا بَدَّلْن[o[َآ] أَمْثَ[n[ـٰ]لَهُمْ تَ[q:10752[بْ]دِيلاً","Биз уларни яратдик ва яратилишларини мстаҳкам қилдик. Ва агар хоҳласак уларнинг ўринларига ўхшашларини келтирурмиз.",580,29],["إِ[g[نّ]َ هَ[n[ـٰ]ذِه[n[ِۦ] تَذْكِرَ[f:14055[ةٌ‌ۖ ف]َمَ[f:8041[ن ش][o[َا]ٓءَ [h:14056[ٱ]تَّخَذَ إِلَىٰ رَبِّه[n[ِۦ] سَبِيلاً","Албатта, буэслатмадир. Бас, ким хоҳласа ўз Роббисига йўл оладир.",580,29],["وَمَا تَش[o[َا]ٓءُونَ إِلّ[o[َآ] أ[a:4201[َن ي]َش[o[َا]ٓءَ [h:4334[ٱ]للَّهُ‌ۚ إِ[g[نّ]َ [h:80[ٱ]للَّهَ كَانَ عَلِيمًا حَكِيمًا","Ва Аллоҳ хоҳласагина, сизлар ҳам хоҳларсиз. Албатта, Аллоҳ билувчи ва ҳикматли зотдир.",580,29],["يُ[q:8947[دْ]خِلُ م[a:476[َن ي]َش[o[َا]ٓءُ فِى رَحْمَتِه[n[ِۦ]‌ۚ وَ[h:14208[ٱ][l[ل]ظَّ[n[ـٰ]لِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمَۢا","У кимни хоҳласа Ўз раҳматига киритадир ва золимлар учун аламли азоблар тайёрлаб қўйгандир.",580,29]]},{"n":77,"ar":"المُرۡسَلَاتِ","en":"Al-Mursalaat","uz":"Мурсалот","type":"Макка","ayahs":[["وَ[h:9999[ٱ]لْمُرْسَلَ[n[ـٰ]تِ عُرْفًا","Кет-кет юборилганлар билан қасам.",580,29],["فَ[h:9999[ٱ]لْعَ[n[ـٰ]صِفَ[n[ـٰ]تِ عَصْفًا","Қаттиқ эсувчи шамоллар билан қасам.",580,29],["وَ[h:9999[ٱ][l[ل][g[نّ]َ[n[ـٰ]شِر[n[َٲ]تِ نَشْرًا","Ва таратувчилар билан қасам.",580,29],["فَ[h:9999[ٱ]لْفَ[n[ـٰ]رِقَ[n[ـٰ]تِ فَرْقًا","Фарқловчилар билан қасам.",580,29],["فَ[h:9999[ٱ]لْمُلْقِيَ[n[ـٰ]تِ ذِكْرًا","Ваҳийни ташувчилар билан қасам.",580,29],["عُذْرًا أَوْ نُذْرًا","Узрни ёки огоҳлантиришни.",580,29],["إِ[g[نّ]َمَا تُوعَدُونَ لَو[n[َٲ]قِعٌ","Албатта, сизга ваъда қилинаётган нарса воқеъ бўлувчидир.",580,29],["فَإِذَا [h:14209[ٱ][l[ل][g[نّ]ُجُومُ طُمِسَتْ","Бас, вақтики юлдузлар ўчирилса.",580,29],["وَإِذَا [h:14210[ٱ][l[ل]سَّم[o[َا]ٓءُ فُرِجَتْ","Ва вақтики, осмон ёрилса.",580,29],["وَإِذَا [h:14211[ٱ]لْجِبَالُ نُسِفَتْ","Ва вақтики, тоғлар кўчирилса.",580,29],["وَإِذَا [h:14212[ٱ][l[ل]رُّسُلُ أُقِّتَتْ","Ва вақтики, Пайғамбарларга вақт белгиланса.",580,29],["لِأَىِّ يَوْمٍ أُجِّلَتْ","Қандоқ кунга сурилган-а?",580,29],["لِيَوْمِ [h:14213[ٱ]لْفَصْلِ","Ажратиш кунига.",580,29],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا يَوْمُ [h:11336[ٱ]لْفَصْلِ","Ажратиш кунини сенга нима билдирди?",580,29],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўшал кунда ёлғонга чиқарувчиларга вайл бўлсин!",580,29],["أَلَمْ نُهْلِكِ [h:14215[ٱ]لْأَوَّل[p[ِي]نَ","Аввалгиларни ҳалок қилмадикми?",580,29],["ثُ[g[مّ]َ نُتْبِعُهُمُ [h:14216[ٱ]لْأَخِر[p[ِي]نَ","Сўнгра кейингиларини уларга эргаштирмадикми?",580,29],["كَذ[n[َٲ]لِكَ نَفْعَلُ بِ[h:11348[ٱ]لْمُ[q:11348[جْ]رِم[p[ِي]نَ","Гуноҳкорларни шундоқ қиламиз.",580,29],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўшал кунда ёлғонга чиқарувчиларга вайл бўлсин!",580,29],["أَلَمْ نَخْلُ[b:14217[ق]كّ[w:14218[ُم م]ّ[a:840[ِن م]ّ[o[َا]ٓ[a:10629[ءٍ م]َّه[p[ِي]نٍ","Сизларни ҳақир сувдан яратмдикми?",581,29],["فَجَعَلْنَ[n[ـٰ]هُ فِى قَرَا[a:9148[رٍ م]َّك[p[ِي]نٍ","Бас, уни мустаҳкам қароргоҳга жойламадикми?",581,29],["إِلَىٰ قَدَ[a:14219[رٍ م]َّعْل[p[ُو]مٍ","Маълум вақтга қадар.",581,29],["فَقَدَرْنَا فَنِعْمَ [h:14220[ٱ]لْقَ[n[ـٰ]دِر[p[ُو]نَ","Бас, Биз қодир бўлдик ва қандоқ ҳам яхши қодир бўлувчимиз.",581,29],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўшал кунда ёлғонга чиқавчиларга вайл бўлсин!",581,29],["أَلَمْ نَ[q:14221[جْ]عَلِ [h:14222[ٱ]لْأَرْضَ كِفَاتًا","Ерни ўзига тортувчи қилмадикми?",581,29],["أَحْي[o[َا]ٓ[a:14223[ءً و]َأَمْو[n[َٲ]تًا","Тирикларни ва ўликларни?",581,29],["وَجَعَلْنَا فِيهَا رَو[n[َٲ]سِىَ شَ[n[ـٰ]مِخَ[n[ـٰ][a:14224[تٍ و]َأَسْقَيْنَ[n[ـٰ]ك[w:14225[ُم م]ّ[o[َا]ٓ[f:14226[ءً ف]ُرَاتًا","Ва Биз унда юкасак тоғлар қилдик ва сизларни зилол сув билан суғордик.",581,29],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўшал кунда ёлғонга чиқарувчиларга вайл бўлсин!",581,29],["ٱ[f:14227[نط]َلِق[o[ُوٓ][s[اْ] إِلَىٰ مَا كُ[f:100[نت][c:6084[ُم ب]ِه[n[ِۦ] تُكَذِّب[p[ُو]نَ","Юрингиз! Ўзингиз ёлғонга чиқарган нарсага қараб.",581,29],["ٱ[f:14227[نط]َلِق[o[ُوٓ][s[اْ] إِلَىٰ ظِ[f:14228[لٍّ ذ]ِى ثَلَ[n[ـٰ]ثِ شُعَ[q[ب]ٍ","Юрингиз! Учта шўъбаси бор «соя»га қараб.",581,29],["لَّا ظَلِي[a:14229[لٍ و]َلَا يُغْنِى مِنَ [h:14230[ٱ][l[ل]لَّهَ[q[ب]ِ","У салқин қилувчимас ва оловни ҳам қайтармас.",581,29],["إِ[g[نّ]َهَا تَرْمِى بِشَرَ[f:14231[رٍ ك]َ[h:14232[ٱ]لْقَصْرِ","Албатта у қасрдек учқунларни отадир.",581,29],["كَأَ[g[نّ]َهُ[n[ۥ] جِمَ[n[ـٰ]لَ[f:14233[تٌ ص]ُفْرٌ","У худди қорамтир-сарғиш туяларга ўхшайдир.",581,29],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўшал кунда ёлғонга чиқарувчиларга вайл бўлсин!",581,29],["هَ[n[ـٰ]ذَا يَوْمُ لَا يَ[f:8795[نط]ِق[p[ُو]نَ","Бу улар гапира олмайдиган кундир.",581,29],["وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِر[p[ُو]نَ","Ва уларга узр айтишга изн берилмайдир.",581,29],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўшал кунда ёлғонга чиқарувчиларга вайл бўлсин!",581,29],["هَ[n[ـٰ]ذَا يَوْمُ [h:11336[ٱ]لْفَصْلِ‌ۖ جَمَعْنَ[n[ـٰ]كُمْ وَ[h:14234[ٱ]لْأَوَّل[p[ِي]نَ","Бу ажратиш куни, сизларни ва аввалгиларни жамладик.",581,29],["فَإِ[f:1670[ن ك]َانَ لَكُمْ كَيْ[f:14235[دٌ ف]َكِيد[p[ُو]نِ","Бас, сизларнинг ҳийлангиз бўлса, менга ишлатиб кўринг-чи?",581,29],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўшал кунда ёлғонга чиқарувчиларга вайл бўлсин!",581,29],["إِ[g[نّ]َ [h:7256[ٱ]لْمُتَّقِينَ فِى ظِلَ[n[ـٰ][a:14236[لٍ و]َعُي[p[ُو]نٍ","Албатта тақводорлар соялар ва булоқлардадир.",581,29],["وَفَو[n[َٲ]كِهَ مِ[g[مّ]َا يَشْتَه[p[ُو]نَ","Ва ўзлари хоҳлаган мевалардадир.",581,29],["كُلُو[s[اْ] وَ[h:300[ٱ]شْرَبُو[s[اْ] هَنِ[o[يٓـ]ـ[i:12907[ـَٔۢا ب]ِمَا كُ[f:100[نت]ُمْ تَعْمَل[p[ُو]نَ","Енглар ва ичинглар, ош бўлсин. Қилган амалларингиз сабабидандир.",581,29],["إِ[g[نّ]َا كَذ[n[َٲ]لِكَ نَ[q:4214[جْ]زِى [h:4215[ٱ]لْمُحْسِن[p[ِي]نَ","Албатта, Биз муҳсинларни шундай мукофотлармиз.",581,29],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўшал кунда ёлғонга чиқарувчиларга вайл бўлсин!",581,29],["كُلُو[s[اْ] وَتَمَتَّعُو[s[اْ] قَلِيلاً إِ[g[نّ]َك[w:14237[ُم م]ُّ[q:12353[جْ]رِم[p[ُو]نَ","Енглар ва мазза қилинглар, озгинагина. Албатта, сизлар гуноҳкорсизлар.",581,29],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўшал кунда ёлғонга чиқавурчиларга вайл бўлсин!",581,29],["وَإِذَا قِيلَ لَهُمُ [h:14238[ٱ]رْكَعُو[s[اْ] لَا يَرْكَع[p[ُو]نَ","Ва агар уларга рукуъ қилинглар дейилса, рукуъ қилмаслар.",581,29],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўшал кунда ёлғонга чиқарувчилварга вайл бўлсин!",581,29],["فَبِأَىِّ حَدِي[i:5170[ثِۭ ب]َعْدَهُ[n[ۥ] يُؤْمِن[p[ُو]نَ","Бас, ундан кейин, қайси сўзга ишонарлар?!",581,29]]},{"n":78,"ar":"النَّبَإِ","en":"An-Naba","uz":"Набаъ","type":"Макка","ayahs":[["عَ[g[مّ]َ يَتَس[o[َا]ٓءَل[p[ُو]نَ","Нима ҳақида сўрашади?",582,30],["عَنِ [h:14239[ٱ][l[ل][g[نّ]َبَإِ [h:14240[ٱ]لْعَظ[p[ِي]مِ","Улкан, муҳим хабар ҳақида.",582,30],["ٱلَّذِى هُمْ فِيهِ مُخْتَلِف[p[ُو]نَ","Шундай хабарки, улар унинг ҳақида ихтилоф қиларлар.",582,30],["كَلَّا سَيَعْلَم[p[ُو]نَ","Йўқ! Улар тезда биларлар!",582,30],["ثُ[g[مّ]َ كَلَّا سَيَعْلَم[p[ُو]نَ","Яна йўқ! Улар тезда биларлар!",582,30],["أَلَمْ نَ[q:14221[جْ]عَلِ [h:14222[ٱ]لْأَرْضَ مِهَ[n[ـٰ]دًا","Ерни тўшаб қўймадикми?",582,30],["وَ[h:9999[ٱ]لْجِبَالَ أَوْتَادًا","Ва тоғларни қозиқ.",582,30],["وَخَلَ[q:14241[قْ]نَ[n[ـٰ]كُمْ أَزْو[n[َٲ]جًا","Ва сизларни жуфт қилиб яратдик.",582,30],["وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا","Ва уйқуларингизни роҳат қилиб қўйдик.",582,30],["وَجَعَلْنَا [h:7689[ٱ]لَّيْلَ لِبَاسًا","Ва кечасини либос қилиб қўйдик.",582,30],["وَجَعَلْنَا [h:14242[ٱ][l[ل][g[نّ]َهَارَ مَعَاشًا","Ва кундузни тириклик қилдик.",582,30],["وَبَنَيْنَا فَوْقَكُمْ سَ[q:7306[بْ][f:14243[عًا ش]ِدَادًا","Тепаларнгизга етти мустаҳкам ни бино қилдик.",582,30],["وَجَعَلْنَا سِرَا[a:14244[جًا و]َهَّاجًا","Ва шуъла таратувчи чироқ ҳам қилдик.",582,30],["وَأَ[f:271[نز]َلْنَا مِنَ [h:14245[ٱ]لْمُعْصِر[n[َٲ]تِ م[o[َا]ٓ[f:14246[ءً ث]َجَّاجًا","Ва сиқилганлардан оқувчи сувлар туширдик.",582,30],["لِّنُخْرِجَ بِه[n[ِۦ] حَب[a:14247[ًّا و]َنَبَاتًا","У билан дон ва наботот чиқаришимиз учун.",582,30],["وَجَ[g[نّ]َ[n[ـٰ]تٍ أَلْفَافًا","Ва дарахтлари бир-бирига киришган бўстонлар.",582,30],["إِ[g[نّ]َ يَوْمَ [h:12368[ٱ]لْفَصْلِ كَانَ مِيقَ[n[ـٰ]تًا","Албатта, ажрим куни вақти белгиланган эди.",582,30],["يَوْمَ يُ[f:4184[نف]َخُ فِى [h:4185[ٱ][l[ل]صُّورِ فَتَأْتُونَ أَفْوَاجًا","У кунда сурга пуфланур ва сизлар тўп-тўп бўлиб келурсизлар.",582,30],["وَفُتِحَتِ [h:14248[ٱ][l[ل]سَّم[o[َا]ٓءُ فَكَانَتْ أَ[q:12251[بْ]و[n[َٲ]بًا","Осмон ёрилиб, эшик-эшиклар очилур.",582,30],["وَسُيِّرَتِ [h:14249[ٱ]لْجِبَالُ فَكَانَتْ سَرَابًا","Тоғлар ўрнидан кўчирилиб, саробга айланур.",582,30],["إِ[g[نّ]َ جَهَ[g[نّ]َمَ كَانَتْ مِرْصَادًا","Албатта, жаҳаннам пойлаб турувчи эди.",582,30],["لِّلطَّ[n[ـٰ]غِينَ مَـَٔـابًا","Туғёнга кетганларга қайтар жойдир.",582,30],["لَّ[n[ـٰ]بِثِينَ فِيه[o[َآ] أَحْقَابًا","Улар унда замонлар бўйи қолувчилардир.",582,30],["لَّا يَذُوقُونَ فِيهَا بَرْ[a:14250[دًا و]َلَا شَرَابًا","Улар унда совуқни ҳам, шаробни ҳам татий олмаслар.",582,30],["إِلَّا حَمِي[a:14251[مًا و]َغَسَّاقًا","Магар қайноқ сув ва йирингни.",582,30],["جَز[o[َا]ٓ[a:14252[ءً و]ِفَاقًا","Мувофиқ жазо ўлароқ.",582,30],["إِ[g[نّ]َهُمْ كَانُو[s[اْ] لَا يَرْجُونَ حِسَابًا","Чунки улар ҳисоб-китоб бўлишига ишонмасдилар.",582,30],["وَكَذَّبُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا كِذَّابًا","Ва Бизнинг оятлариимизни ёлғон дейишган эди, ёлғон!.",582,30],["وَكُلَّ شَىْءٍ أَحْصَيْنَ[n[ـٰ]هُ كِتَ[n[ـٰ]بًا","Биз барча нарсани китобга жамлаб қўйганмиз.",582,30],["فَذُوقُو[s[اْ] فَل[a:14253[َن ن]َّزِيدَكُمْ إِلَّا عَذَابًا","Бас, татиб кўринглар, сизларга азобдан бошқа ҳеч нарсани зиёда қилмасмиз.",582,30],["إِ[g[نّ]َ لِلْمُتَّقِينَ مَفَازًا","Албатта, тақводорларга ютуқ бордир:",583,30],["حَد[o[َا]ٓئِقَ وَأَعْنَ[n[ـٰ]بًا","Боғ-роғлар, узумзорлар бордир.",583,30],["وَكَوَاعِبَ أَتْرَابًا","Ва янги бўйи етган бир хил ёшдаги қизлар бордир.",583,30],["وَكَأْ[f:14254[سًا د]ِهَاقًا","Ва тўлдирилган қадаҳлар бордир.",583,30],["لَّا يَسْمَعُونَ فِيهَا لَغْ[a:13226[وًا و]َلَا كِذّ[n[َٲ]بًا","У ерда бекорчи гапларни ҳам, ёлғон гапларни ҳам эшитмаслар.",583,30],["جَز[o[َا]ٓ[a:14255[ءً م]ّ[u:770[ِن ر]َّبِّكَ عَط[o[َا]ٓءً حِسَابًا","Роббингдан мукофот, совға ҳисобидандир.",583,30],["رَّبِّ [h:12320[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَمَا بَيْنَهُمَا [h:14256[ٱ][l[ل]رَّحْمَ[n[ـٰ]نِ‌ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًا","У осмонлар, ер ва уларнинг орасидаги барча нарсаларнинг Роббиси, Роҳмандир, Унинг ҳузурида ҳеч ким хитоб қилишга қодир бўлмас.",583,30],["يَوْمَ يَقُومُ [h:14257[ٱ][l[ل]رُّوحُ وَ[h:1146[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ صَف[u:14258[ًّا‌ۖ ل]َّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ [h:8399[ٱ][l[ل]رَّحْمَ[n[ـٰ]نُ وَقَالَ صَوَابًا","Ўша кунда Руҳ ва фаришталар саф бўлиб турадир. Роҳман изн берганлар ва тўғри сўзлаганлардан ўзгалар гапира олмаслар.",583,30],["ذ[n[َٲ]لِكَ [h:13944[ٱ]لْيَوْمُ [h:14259[ٱ]لْحَقُّ‌ۖ فَمَ[f:8041[ن ش][o[َا]ٓءَ [h:14056[ٱ]تَّخَذَ إِلَىٰ رَبِّه[n[ِۦ] مَـَٔـابًا","У ҳақ кундир. Ким хоҳласа, ўз Роббисига қайтар йўл оладир.",583,30],["إِ[g[نّ][o[َآ] أَ[f:14260[نذ]َرْنَ[n[ـٰ]كُمْ عَذَا[f:14261[بًا ق]َرِي[a:14262[بًا ي]َوْمَ يَ[f:2039[نظ]ُرُ [h:14263[ٱ]لْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ [h:14264[ٱ]لْكَافِرُ يَ[n[ـٰ]لَيْتَنِى كُ[f:2917[نت]ُ تُر[n[َٲ]بَۢا","Албатта, Биз сизларни яқин келажакдаги азобдан қўрқитдик. У кунда, ҳар киши тақдим қилган нарсага назар соладир. Ва кофир «кошки тупроқ бўлиб кетсам», –дейдир.",583,30]]},{"n":79,"ar":"النَّازِعَاتِ","en":"An-Naazi'aat","uz":"Назиъат","type":"Макка","ayahs":[["وَ[h:9999[ٱ][l[ل][g[نّ]َ[n[ـٰ]زِعَ[n[ـٰ]تِ غَرْقًا","Шиддат билан жонни суғуриб олувчилар билан қасам.",583,30],["وَ[h:9999[ٱ][l[ل][g[نّ]َ[n[ـٰ]شِطَ[n[ـٰ]تِ نَشْطًا","Юмшоқлик билан жонни олувчи лар билан қасам.",583,30],["وَ[h:9999[ٱ][l[ل]سَّ[n[ـٰ]بِحَ[n[ـٰ]تِ سَ[q:14030[بْ]حًا","Сузиб юрувчи лар билан қасам.",583,30],["فَ[h:9999[ٱ][l[ل]سَّ[n[ـٰ]بِقَ[n[ـٰ]تِ سَ[q:14265[بْ]قًا","Ўзишда мусобақа қилувчи лар билан қасам.",583,30],["فَ[h:9999[ٱ]لْمُدَبِّر[n[َٲ]تِ أَمْرًا","Амрнинг тадбирини қилувчи лар билан қасам.",583,30],["يَوْمَ تَرْجُفُ [h:14266[ٱ][l[ل]رَّاجِفَةُ","Изтиробга тушувчи изтиробга тушган кунда.",583,30],["تَتْبَعُهَا [h:14267[ٱ][l[ل]رَّادِفَةُ","Унга эргашувчи эргашар.",583,30],["قُلُو[a:14268[بٌ ي]َوْمَئِ[a:14269[ذٍ و]َاجِفَةٌ","Ўша кунда қалблар хавфга тўлар.",583,30],["أَ[q:14270[بْ]صَ[n[ـٰ]رُهَا خَ[n[ـٰ]شِعَةٌ","Уларнинг кўзлари қўрқинчга тўлар.",583,30],["يَقُولُونَ أَءِ[g[نّ]َا لَمَرْدُودُونَ فِى [h:14271[ٱ]لْحَافِرَةِ","Улар: «Биз ортга қайтариламизми?",583,30],["أَءِذَا كُ[g[نّ]َا عِظَ[n[ـٰ][a:14272[مًا ن]َّخِرَةً","Чириган суяк бўлганимиздан кейин ҳам-а?",583,30],["قَالُو[s[اْ] تِلْكَ إِ[f:14273[ذًا ك]َرَّةٌ خَاسِرَةٌ","Агар шундоқ бўлса, бу ҳасратий қайтиш-ку?» дерлар.",583,30],["فَإِ[g[نّ]َمَا هِىَ زَ[q:11332[جْ]رَ[a:11333[ةٌ و][n[َٲ]حِدَةٌ","Албатта, у бир қичқириқдан бошқа нарса эмас.",583,30],["فَإِذَا ه[c:14274[ُم ب]ِ[h:14275[ٱ][l[ل]سَّاهِرَةِ","Кўрибсизки, улар қиёмат майдонида турибди-да.",583,30],["هَلْ أَتَ[n[ـٰ]كَ حَدِيثُ مُوسَىٰٓ","Сенга Мусонинг хабари келдими?",583,30],["إِذْ نَادَ[n[ٮٰ]هُ رَبُّهُ[n[ۥ] بِ[h:8451[ٱ]لْوَادِ [h:8452[ٱ]لْمُقَدَّسِ طُوًى","Қачонки Роббиси унга муқаддас Тува водийсида нидо қилди:",584,30],["ٱذْهَ[q:7814[بْ] إِلَىٰ فِرْعَوْنَ إِ[g[نّ]َهُ[n[ۥ] طَغَىٰ","«Фиръавн ҳузурига бор, албатта у туғёнга кетди.",584,30],["فَقُلْ هَل لَّكَ إِلَ[o[ىٰٓ] أَ[f:14276[ن ت]َزَكَّىٰ","Бас унга айт: «Сенда покланишга борми?",584,30],["وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ","Ва сени Роббингга ҳидоят қилсам, шоядки қўрқсанг», деб»",584,30],["فَأَرَ[n[ٮٰ]هُ [h:14277[ٱ]لْأَيَةَ [h:14278[ٱ]لْكُ[q:8463[بْ]رَىٰ","Ва унга улкан аломатни кўрсатди.",584,30],["فَكَذَّبَ وَعَصَىٰ","Ул уни ёлғонга чиқарди ва осий бўлди.",584,30],["ثُ[g[مّ]َ أَ[q:13927[دْ]بَرَ يَسْعَىٰ","Сўнг ортига ўгирилиб тезлаб кетди¬.",584,30],["فَحَشَرَ فَنَادَىٰ","Кейин тўплаб нидо қилди.",584,30],["فَقَالَ أَنَا۟ رَبُّكُمُ [h:14279[ٱ]لْأَعْلَىٰ","Ва, мен сизларнинг энг олий Роббингизман, деди.",584,30],["فَأَخَذَهُ [h:14280[ٱ]للَّهُ نَكَالَ [h:14281[ٱ]لْأَخِرَةِ وَ[h:12987[ٱ]لْأُولَىٰٓ","Бас Аллоҳ уни аввалги ва охирги гуноҳлари учун азобга олди.",584,30],["إِ[g[نّ]َ فِى ذ[n[َٲ]لِكَ لَعِ[q:1764[بْ]رَ[u:14282[ةً ل]ِّم[a:8436[َن ي]َخْشَىٰٓ","Албатта, бунда қўрқадиганлар учун ибрат бордир.",584,30],["ءَأَ[f:716[نت]ُمْ أَشَدُّ خَلْقًا أَمِ [h:14283[ٱ][l[ل]سَّم[o[َا]ٓءُ‌ۚ بَنَ[n[ـٰ]هَا","Сизларни яратиш қийинми ёки У зот бино қилган осмонними?",584,30],["رَفَعَ سَمْكَهَا فَسَوَّ[n[ٮٰ]هَا","Унинг шифтини юқори кўтарди ва бекаму кўст, мустаҳкам қилиб қўйди.",584,30],["وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَ[n[ـٰ]هَا","Кечасини қоронғу ва кундузини ёруғ қилди.",584,30],["وَ[h:9999[ٱ]لْأَرْضَ بَعْدَ ذ[n[َٲ]لِكَ دَحَ[n[ـٰ]هَآ","Ва ундан сўнг ерни тухум шаклида қилди.",584,30],["أَخْرَجَ مِنْهَا م[o[َا]ٓءَهَا وَمَرْعَ[n[ـٰ]هَا","Ундан сувни, ўт-ўланларни чиқарди.",584,30],["وَ[h:9999[ٱ]لْجِبَالَ أَرْسَ[n[ـٰ]هَا","Ва тоғларни собит қилди.",584,30],["مَتَ[n[ـٰ][u:3808[عًا ل]َّكُمْ وَلِأَنْعَ[n[ـٰ]مِكُمْ","Сизларга ва чорваларингизга манфаат бўлсин учун.",584,30],["فَإِذَا ج[o[َا]ٓءَتِ [h:14284[ٱ][l[ل]طّ[m[َا]ٓ[g[مّ]َةُ [h:14285[ٱ]لْكُ[q:8463[بْ]رَىٰ","Вақтики катта ғолиб келса.",584,30],["يَوْمَ يَتَذَكَّرُ [h:14286[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ مَا سَعَىٰ","У куни инсон қилган ишларини эслайдир.",584,30],["وَبُرِّزَتِ [h:9792[ٱ]لْجَحِيمُ لِم[a:14287[َن ي]َرَىٰ","Ва жаҳаннам кўрадиганларга зоҳир қилинадир.",584,30],["فَأَ[g[مّ]َا مَ[f:14288[ن ط]َغَىٰ","Аммо кимики туғёнга кетиб, ҳаддидан ошган бўлса",584,30],["وَءَاثَرَ [h:14289[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَا","Ва бу дунё ҳаётини устун қўйган бўлса,",584,30],["فَإِ[g[نّ]َ [h:14290[ٱ]لْجَحِيمَ هِىَ [h:14291[ٱ]لْمَأْوَىٰ","Бас, албатта, Жаҳийм ўрин бўладир.",584,30],["وَأَ[g[مّ]َا مَنْ خَافَ مَقَامَ رَبِّه[n[ِۦ] وَنَهَى [h:14292[ٱ][l[ل][g[نّ]َفْسَ عَنِ [h:12957[ٱ]لْهَوَىٰ","Ва, аммо ким Роббисининг мақомидан қўрққан ва ўз нафсини ҳаволаниб кетишидан қайтарган бўлса.",584,30],["فَإِ[g[نّ]َ [h:14293[ٱ]لْجَ[g[نّ]َةَ هِىَ [h:14291[ٱ]لْمَأْوَىٰ","Бас, албатта, жаннат ўрин бўладир.",584,30],["يَسْــَٔلُونَكَ عَنِ [h:5172[ٱ][l[ل]سَّاعَةِ أَيَّانَ مُرْسَ[n[ـٰ]هَا","Сендан, қиёмат қачон бўлур? деб сўрарлар.",584,30],["فِيمَ أَ[f:169[نت]َ مِ[f:14294[ن ذ]ِكْرَ[n[ٮٰ]هَآ","Унинг зикрини сен қандоқ билардинг.",584,30],["إِلَىٰ رَبِّكَ مُ[f:14295[نت]َهَ[n[ـٰ]هَآ","Унинг интиҳоси Роббингга хосдир.",584,30],["إِ[g[نّ]َم[o[َآ] أَ[f:169[نت]َ مُ[f:14296[نذ]ِرُ م[a:14297[َن ي]َخْشَ[n[ـٰ]هَا","Албатта сен ундан қўрққанларга огоҳлантирувчисан, холос.",584,30],["كَأَ[g[نّ]َهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَث[o[ُوٓ][s[اْ] إِلَّا عَشِيَّةً أَوْ ضُحَ[n[ـٰ]هَا","Уни кўрган кунлари худди бу дунёда бир кеча ёки кундуздан бошқа турмаганга ўхшарлар.",584,30]]},{"n":80,"ar":"عَبَسَ","en":"Abasa","uz":"Абаса","type":"Макка","ayahs":[["عَبَسَ وَتَوَلَّىٰٓ","Афтини буриштирди ва юз ўгирди.",585,30],["أَ[f:14298[ن ج][o[َا]ٓءَهُ [h:14299[ٱ]لْأَعْمَىٰ","Кўзи кўр киши ҳузурига келганда.",585,30],["وَمَا يُ[q:10898[دْ]رِيكَ لَعَلَّهُ[n[ۥ] يَزَّكَّىٰٓ","Қаердан биласан, эҳтимол, у покланар.",585,30],["أَوْ يَذَّكَّرُ فَتَ[f:14300[نف]َعَهُ [h:14301[ٱ][l[ل]ذِّكْرَىٰٓ","Ёки насиҳат олар ва мавъиза унга манфаат берар.",585,30],["أَ[g[مّ]َا مَنِ [h:14302[ٱ]سْتَغْنَىٰ","Аммо истиғно қилганга бўлса...",585,30],["فَأَ[f:14303[نت]َ لَهُ[n[ۥ] تَصَدَّىٰ","Сен у томонга интиласан.",585,30],["وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ","У покланмаса, сени ҳеч ким маломат қилмас.",585,30],["وَأَ[g[مّ]َا مَ[f:14304[ن ج][o[َا]ٓءَكَ يَسْعَىٰ","Аммо ҳузурингга шошилиб келган.",585,30],["وَهُوَ يَخْشَىٰ","Ва қўрққан ҳолда бўлгандан эса...",585,30],["فَأَ[f:14303[نت]َ عَنْهُ تَلَهَّىٰ","Бас, Сен ундан машғул бўласан.",585,30],["كَلّ[o[َآ] إِ[g[نّ]َهَا تَذْكِرَةٌ","Йўқ! Албатта улар эслатмадир.",585,30],["فَمَ[f:8041[ن ش][o[َا]ٓءَ ذَكَرَهُۥ","Ким хоҳласа уни эслайдир.",585,30],["فِى صُحُ[a:14305[فٍ م]ُّكَرَّمَةٍ","Ҳурматланган саҳифалардадир.",585,30],["مَّرْفُوعَ[a:14306[ةٍ م]ُّطَهَّرَةِۭ","Олий қадардирлар, поклангандирлар.",585,30],["بِأَيْدِى سَفَرَةٍ","Элчилар қўлларидадир.",585,30],["كِرَا[i:14307[مِۭ ب]َرَرَةٍ","Улар ҳурматланган ва ўта яхшидирлар.",585,30],["قُتِلَ [h:14308[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ م[o[َآ] أَكْفَرَهُۥ","инсонга лаънат бўлсин, унинг кофирлиги қандоқ шиддатли бўлди.",585,30],["مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ","Уни қайси нарсадан яратди?",585,30],["م[a:7325[ِن ن]ُّ[q:7326[طْ]فَةٍ خَلَقَهُ[n[ۥ] فَقَدَّرَهُۥ","Нутфадан яратди. Уни яратди ва унни ўлчовли қилди.",585,30],["ثُ[g[مّ]َ [h:14309[ٱ][l[ل]سَّبِيلَ يَسَّرَهُۥ","Сўнгра чиқиш йўлини осон қилди.",585,30],["ثُ[g[مّ]َ أَمَاتَهُ[n[ۥ] فَأَ[q:14310[قْ]بَرَهُۥ","Сўнгра ўлдирди ва қабрга киритди.",585,30],["ثُ[g[مّ]َ إِذَا ش[o[َا]ٓءَ أَ[f:14311[نش]َرَهُۥ","Сўнгра қачон хоҳласа, уни қайта тирилтиради.",585,30],["كَلَّا لَ[g[مّ]َا يَ[q:14312[قْ]ضِ م[o[َآ] أَمَرَهُۥ","Йўқ ундоқ эмас! У ўзига У зот қилган амрни бажармади.",585,30],["فَلْيَ[f:14313[نظ]ُرِ [h:14314[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ إِلَىٰ طَعَامِهِۦٓ","Инсон ўз таомига назар солсин.",585,30],["أَ[g[نّ]َا صَبَ[q:14315[بْ]نَا [h:14316[ٱ]لْم[o[َا]ٓءَ صَبًّا","Албатта, Биз сувни роса қуйиб қўйдик.",585,30],["ثُ[g[مّ]َ شَقَ[q:14317[قْ]نَا [h:14318[ٱ]لْأَرْضَ شَقًّا","Сўнгра ерни ўзига хос ёрдик.",585,30],["فَأَ[i:9998[نۢب]َتْنَا فِيهَا حَبًّا","Биз унда дон ўстириб қўйдик.",585,30],["وَعِنَ[a:14319[بًا و]َقَضْبًا","Ва узум ва кўкларни ҳам.",585,30],["وَزَيْتُو[a:14320[نًا و]َنَخْلاً","Ва зайтун ва хурмоларни ҳам.",585,30],["وَحَد[o[َا]ٓئِقَ غُلْبًا","Ва тиғиз боғларни ҳам.",585,30],["وَفَ[n[ـٰ]كِهَ[a:14321[ةً و]َأَبًّا","Ва меваларни ва ўт-ўланларни ҳам.",585,30],["مَّتَ[n[ـٰ][u:3808[عًا ل]َّكُمْ وَلِأَنْعَ[n[ـٰ]مِكُمْ","Сизларга ва чорваларингизга манфаат бўлсин, деб.",585,30],["فَإِذَا ج[o[َا]ٓءَتِ [h:14322[ٱ][l[ل]صّ[m[َا]ٓخَّةُ","Вақтики қулоқларни кар қилувчи овоз келса.",585,30],["يَوْمَ يَفِرُّ [h:14323[ٱ]لْمَرْءُ مِنْ أَخ[p[ِي]هِ","У кунда киши қочадир; ўз ака-укасидан.",585,30],["وَأُ[g[مّ]ِه[n[ِۦ] وَأَب[p[ِي]هِ","Ва онаси ва отасидан.",585,30],["وَصَ[n[ـٰ]حِبَتِه[n[ِۦ] وَبَن[p[ِي]هِ","Ва хотини ва бола-чақасидан.",585,30],["لِكُلِّ [h:9345[ٱ]مْرِى[a:9346[ٍٕ م]ِّنْهُمْ يَوْمَئِ[f:14324[ذٍ ش]َأْ[a:14325[نٌ ي]ُغْن[p[ِي]هِ","У кунда улардан ҳар бир шахсни овора қилувчи ўз иши бор.",585,30],["وُجُو[a:14135[هٌ ي]َوْمَئِ[a:14326[ذٍ م]ُّسْفِرَةٌ","У кунда порлоқ чеҳралар бор.",585,30],["ضَاحِكَ[a:14327[ةٌ م]ُّسْتَ[q:14328[بْ]شِرَةٌ","Улар кулгу билан тўла, етган хушхабардан хурсанд.",585,30],["وَوُجُو[a:14137[هٌ ي]َوْمَئِذٍ عَلَيْهَا غَبَرَةٌ","У кунда ғубор босган чеҳралар бор.",585,30],["تَرْهَقُهَا قَتَرَةٌ","Устини зулмат қоплаган.",585,30],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمُ [h:14329[ٱ]لْكَفَرَةُ [h:14330[ٱ]لْفَجَرَةُ","Улар, ана ўшалар, кофирлар ва фожирлардир.",585,30]]},{"n":81,"ar":"التَّكۡوِيرِ","en":"At-Takwir","uz":"Таквир","type":"Макка","ayahs":[["إِذَا [h:14331[ٱ][l[ل]شَّمْسُ كُوِّرَتْ","Вақтики, қуёшни буклаб, ўралса.",586,30],["وَإِذَا [h:14332[ٱ][l[ل][g[نّ]ُجُومُ [h:14333[ٱ][f:14334[نك]َدَرَتْ","Ва, вақтики, юлдузлар сочилиб кетса.",586,30],["وَإِذَا [h:14211[ٱ]لْجِبَالُ سُيِّرَتْ","Ва, вақтики, тоғлар сайр қилдирилса.",586,30],["وَإِذَا [h:14335[ٱ]لْعِشَارُ عُطِّلَتْ","Ва, вақтики, ҳомиласига ўн ой тўлган туялар қаровсиз қолса.",586,30],["وَإِذَا [h:14336[ٱ]لْوُحُوشُ حُشِرَتْ","Ва, вақтики, ваҳший ҳайвонлар бир жойга тўпланса.",586,30],["وَإِذَا [h:14337[ٱ]لْبِحَارُ سُجِّرَتْ","Ва, вақтики, денгизлар аланга олиб ёнса.",586,30],["وَإِذَا [h:14338[ٱ][l[ل][g[نّ]ُفُوسُ زُوِّجَتْ","Ва вақтики, нафслар жуфтлаштирилса.",586,30],["وَإِذَا [h:14339[ٱ]لْمَوْءُ[n[ۥ]دَةُ سُئِلَتْ","Ва вақтики, тириклай кўмилган қиздан сўралса.",586,30],["بِأَىِّ ذَ[i:14340[نۢب][f:14341[ٍ ق]ُتِلَتْ","У нима гуноҳ учун ўлдирилган?",586,30],["وَإِذَا [h:14342[ٱ][l[ل]صُّحُفُ نُشِرَتْ","Ва, вақтики, саҳифалар нашр қилинса.",586,30],["وَإِذَا [h:14210[ٱ][l[ل]سَّم[o[َا]ٓءُ كُشِطَتْ","Ва, вақтики, осмон қўпорилса.",586,30],["وَإِذَا [h:14343[ٱ]لْجَحِيمُ سُعِّرَتْ","Ва, вақтики, жаҳаннам қиздирилса.",586,30],["وَإِذَا [h:14344[ٱ]لْجَ[g[نّ]َةُ أُزْلِفَتْ","Ва, вақтики, жаннат яқинлаштирилса.",586,30],["عَلِمَتْ نَفْ[a:10644[سٌ م]ّ[o[َآ] أَحْضَرَتْ","Ҳар бир жон нима ҳозирланганини билади.",586,30],["فَل[o[َآ] أُ[q:13287[قْ]سِمُ بِ[h:14345[ٱ]لْخُ[g[نّ]َسِ","махфий бўлувчилар билан қасам.",586,30],["ٱلْجَوَارِ [h:14346[ٱ]لْكُ[g[نّ]َسِ","юрувчи, беркинувчилар билан қасам.",586,30],["وَ[h:9999[ٱ]لَّيْلِ إِذَا عَسْعَسَ","Қоронғулиги билан кириб келган кеча билан қасам.",586,30],["وَ[h:9999[ٱ][l[ل]صُّ[q:14092[بْ]حِ إِذَا تَنَفَّسَ","Нафас олиб, кириб келган тонг билан қасам.",586,30],["إِ[g[نّ]َهُ[n[ۥ] لَقَوْلُ رَسُو[f:13904[لٍ ك]َر[p[ِي]مٍ","Албатта у карамли Расулнинг сўзидир.",586,30],["ذِى قُوَّةٍ عِ[f:264[ند]َ ذِى [h:7769[ٱ]لْعَرْشِ مَك[p[ِي]نٍ","У қувватлидир. Арш эгаси ҳузурида мартабаси олийдир.",586,30],["مُّطَا[f:14347[عٍ ث]َ[g[مّ]َ أَم[p[ِي]نٍ","Итоат қилинган, омонатли.",586,30],["وَمَا صَاحِبُك[c:14348[ُم ب]ِمَ[q:13812[جْ]ن[p[ُو]نٍ","Сизнинг соҳибингиз мажнун эмас.",586,30],["وَلَقَ[q:341[دْ] رَءَاهُ بِ[h:12961[ٱ]لْأُفُقِ [h:14349[ٱ]لْمُب[p[ِي]نِ","Батаҳқиқ ул ани очиқ-ойдин уфқда кўрди.",586,30],["وَمَا هُوَ عَلَى [h:2453[ٱ]لْغَيْبِ بِضَن[p[ِي]نٍ","Ва у ғайбга бахил эмас.",586,30],["وَمَا هُوَ بِقَوْلِ شَيْطَ[n[ـٰ][u:7213[نٍ ر]َّج[p[ِي]مٍ","Ва у тошбўрон қилинган шайтоннинг сўзи эмас.",586,30],["فَأَيْنَ تَذْهَب[p[ُو]نَ","Бас, қаёққа кетмоқдасиз?!",586,30],["إِنْ هُوَ إِلَّا ذِكْ[u:6839[رٌ ل]ِّلْعَ[n[ـٰ]لَم[p[ِي]نَ","У оламларга эслатмадан бошқа нарса эмас.",586,30],["لِمَ[f:14095[ن ش][o[َا]ٓءَ مِ[f:344[نك]ُمْ أ[a:14350[َن ي]َسْتَق[p[ِي]مَ","Сизлардан мустақим бўлишни хоҳловчилар учун.",586,30],["وَمَا تَش[o[َا]ٓءُونَ إِلّ[o[َآ] أ[a:4201[َن ي]َش[o[َا]ٓءَ [h:4334[ٱ]للَّهُ رَبُّ [h:4750[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","Оламларнинг Роббиси Аллоҳ хоҳламаса, сизлар хоҳлай олмассизлар.",586,30]]},{"n":82,"ar":"الانفِطَارِ","en":"Al-Infitaar","uz":"Инфитор","type":"Макка","ayahs":[["إِذَا [h:14351[ٱ][l[ل]سَّم[o[َا]ٓءُ [h:14352[ٱ][f:14353[نف]َطَرَتْ","Вақтики, осмон ёрилса.",587,30],["وَإِذَا [h:14354[ٱ]لْكَوَاكِبُ [h:14355[ٱ][f:14356[نت]َثَرَتْ","Ва, вақтики, юлдузлар сочилиб кетса.",587,30],["وَإِذَا [h:14337[ٱ]لْبِحَارُ فُجِّرَتْ","Ва, вақтики, денгизлар портлатилса.",587,30],["وَإِذَا [h:14357[ٱ]لْقُبُورُ بُعْثِرَتْ","Ва, вақтики, қабрлар остин-устин бўлса.",587,30],["عَلِمَتْ نَفْ[a:10644[سٌ م]َّا قَدَّمَتْ وَأَخَّرَتْ","Ҳар бир жон нимани тақдим қилдию, нимани таъхир қилди- билади.",587,30],["يَ[o[ـٰٓ]أَيُّهَا [h:14358[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ مَا غَرَّكَ بِرَبِّكَ [h:14359[ٱ]لْكَر[p[ِي]مِ","Эй Инсон! Сени карамли Роббинг ҳақида нима ғурурга кетказди?!",587,30],["ٱلَّذِى خَلَقَكَ فَسَوَّ[n[ٮٰ]كَ فَعَدَلَكَ","У сени тўла-тўкис ва мўътадил қилиб яратган зотдир.",587,30],["ف[o[ِىٓ] أَىِّ صُورَ[a:14360[ةٍ م]َّا ش[o[َا]ٓءَ رَكَّبَكَ","Ўзи хоҳлаган суратда сени таркиб қилди.",587,30],["كَلَّا بَلْ تُكَذِّبُونَ بِ[h:14361[ٱ][l[ل]دّ[p[ِي]نِ","Йўқ! Балки, сиз жазони ёлғонга чиқармоқдасиз!",587,30],["وَإِ[g[نّ]َ عَلَيْكُمْ لَحَ[n[ـٰ]فِظ[p[ِي]نَ","Ҳолбуки, устингиздан кузатиб турувчилар бордир.",587,30],["كِرَا[f:14362[مًا ك]َ[n[ـٰ]تِب[p[ِي]نَ","Улар ҳурматли, ёзиб тургувчилардир.",587,30],["يَعْلَمُونَ مَا تَفْعَل[p[ُو]نَ","Улар нима қилаётганингизни биладир.",587,30],["إِ[g[نّ]َ [h:14162[ٱ]لْأَ[q:14163[بْ]رَارَ لَفِى نَع[p[ِي]مٍ","Албатта, яхшилар жаннатдадир.",587,30],["وَإِ[g[نّ]َ [h:14363[ٱ]لْفُجَّارَ لَفِى جَح[p[ِي]مٍ","Ва албатта, фожирлар жаҳаннамдадир.",587,30],["يَصْلَوْنَهَا يَوْمَ [h:9781[ٱ][l[ل]دّ[p[ِي]نِ","Улар у ерга қиёмат куни кирадир.",587,30],["وَمَا هُمْ عَنْهَا بِغ[o[َا]ٓئِب[p[ِي]نَ","Ва улар ундан ғойиб бўла олмайдир.",587,30],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا يَوْمُ [h:11335[ٱ][l[ل]دّ[p[ِي]نِ","Ва жазо куни нима эканини сенга нима билдирди?",587,30],["ثُ[g[مّ]َ م[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا يَوْمُ [h:11335[ٱ][l[ل]دّ[p[ِي]نِ","Сўнг жазо куни нима эканини сенга нима билдирди?",587,30],["يَوْمَ لَا تَمْلِكُ نَفْ[u:14364[سٌ ل]ِّنَفْ[f:14365[سٍ ش]َيْـ[a:14366[ـًٔا‌ۖ و]َ[h:4748[ٱ]لْأَمْرُ يَوْمَئِ[u:9076[ذٍ ل]ِّلَّهِ","Ўша кунда ҳеч бир жон бошқа бир жон учун бирор нарса қилиш имконига молик эмасдир. У кунда барча иш Аллоҳнинг Ўзига хосдир.",587,30]]},{"n":83,"ar":"المُطَفِّفِينَ","en":"Al-Mutaffifin","uz":"Мутаффифун","type":"Макка","ayahs":[["وَيْ[u:14367[لٌ ل]ِّلْمُطَفِّف[p[ِي]نَ","Вайл бўлсин, ўлчовдан уриб қолувчиларга.",587,30],["ٱلَّذِينَ إِذَا [h:14368[ٱ]كْتَالُو[s[اْ] عَلَى [h:729[ٱ][l[ل][g[نّ]َاسِ يَسْتَوْف[p[ُو]نَ","Улар одамлардан нарса ўлчаб олсалар, тўлиқ оларлар.",587,30],["وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِر[p[ُو]نَ","Ва агар одамларга ўлчаб ёки тортиб берсалар, камайтирарлар.",587,30],["أَلَا يَظُ[g[نّ]ُ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَ[g[نّ]َه[w:14369[ُم م]َّ[q:6246[بْ]عُوث[p[ُو]نَ","Ана шулар, албатта, қайта тирилтирилишларини ўйламайдиларми?",587,30],["لِيَوْمٍ عَظ[p[ِي]مٍ","Улуғ бир кунда.",587,30],["يَوْمَ يَقُومُ [h:14370[ٱ][l[ل][g[نّ]َاسُ لِرَبِّ [h:687[ٱ]لْعَ[n[ـٰ]لَم[p[ِي]نَ","У кунда, одамлар оламлар Роббиси ҳузурида тик турарлар.",587,30],["كَلّ[o[َآ] إِ[g[نّ]َ كِتَ[n[ـٰ]بَ [h:14371[ٱ]لْفُجَّارِ لَفِى سِجّ[p[ِي]نٍ","Йўқ! Албатта фожирларларнинг китоби «сижжин»дадир.",588,30],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا سِجّ[p[ِي]نٌ","«Сижжин» қандай нарса эканини сенга нима билдирди?!",588,30],["كِتَ[n[ـٰ][a:14372[بٌ م]َّرْق[p[ُو]مٌ","У ёзилган китобдур.",588,30],["وَيْ[a:14214[لٌ ي]َوْمَئِ[u:12902[ذٍ ل]ِّلْمُكَذِّب[p[ِي]نَ","Ўша кунда ёлғонга чиқарувчиларга вайл бўлсин!",588,30],["ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ [h:13931[ٱ][l[ل]دّ[p[ِي]نِ","Улар жазо кунини ёлғонга чиқарарлар.",588,30],["وَمَا يُكَذِّبُ بِه[o[ِۦٓ] إِلَّا كُلُّ مُعْتَدٍ أَث[p[ِي]مٍ","У кунни ҳаддан ошувчи ва ўта гуноҳкорлардан бошқалар ёлғонга чиқармаслар.",588,30],["إِذَا تُتْلَىٰ عَلَيْهِ ءَايَ[n[ـٰ]تُنَا قَالَ أَسَ[n[ـٰ]طِيرُ [h:3993[ٱ]لْأَوَّل[p[ِي]نَ","Қачон унга оятларимиз тиловат қилинса, «авалгиларнинг афсоналари», дер.",588,30],["كَلَّا‌ۖ بَلْۜ رَانَ عَلَىٰ قُلُوبِه[w:14373[ِم م]َّا كَانُو[s[اْ] يَكْسِب[p[ُو]نَ","Йўқ! Уларнинг қилган касблари қалбларига моғор бўлиб ўрнашиб қолган, холос.",588,30],["كَلّ[o[َآ] إِ[g[نّ]َهُمْ ع[u:14374[َن ر]َّبِّهِمْ يَوْمَئِ[u:14375[ذٍ ل]َّمَحْجُوب[p[ُو]نَ","Йўқ! Албатта, улар ўша кунда ўз Роббиларини кўришдан тўсиларлар.",588,30],["ثُ[g[مّ]َ إِ[g[نّ]َهُمْ لَصَالُو[s[اْ] [h:14376[ٱ]لْجَح[p[ِي]مِ","Сўнгра улар албатта жаҳиймга кирувчидирлар.",588,30],["ثُ[g[مّ]َ يُقَالُ هَ[n[ـٰ]ذَا [h:126[ٱ]لَّذِى كُ[f:100[نت][c:6084[ُم ب]ِه[n[ِۦ] تُكَذِّب[p[ُو]نَ","Сўнгра, мана бу, сизлар ёлғонга чиқариб юрган нарса, дейилар.",588,30],["كَلّ[o[َآ] إِ[g[نّ]َ كِتَ[n[ـٰ]بَ [h:14377[ٱ]لْأَ[q:2507[بْ]رَارِ لَفِى عِلِّيّ[p[ِي]نَ","Йўқ! Албатта аброрларнинг китоби «Иллиййун»дадир.",588,30],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا عِلِّيّ[p[ُو]نَ","«Иллиййун» қандоқ нарса эканини сенга нима билдирди?!",588,30],["كِتَ[n[ـٰ][a:14372[بٌ م]َّرْق[p[ُو]مٌ","У ёзилган китобдур.",588,30],["يَشْهَدُهُ [h:14378[ٱ]لْمُقَرَّب[p[ُو]نَ","Унга муқарраблар шоҳид бўларлар.",588,30],["إِ[g[نّ]َ [h:14162[ٱ]لْأَ[q:14163[بْ]رَارَ لَفِى نَع[p[ِي]مٍ","Албатта, аброрлар жаннати найимдадирлар.",588,30],["عَلَى [h:8058[ٱ]لْأَر[o[َا]ٓئِكِ يَ[f:1141[نظ]ُر[p[ُو]نَ","Пардали баланд сўрилар устида назар солиб турарлар.",588,30],["تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ [h:14379[ٱ][l[ل][g[نّ]َع[p[ِي]مِ","Уларнинг чеҳраларидан жаннат равнақини билиб оларсан.",588,30],["يُسْقَوْنَ م[u:14380[ِن ر]َّحِي[a:14381[قٍ م]َّخْت[p[ُو]مٍ","Улар муҳрланган, ниҳоятда пок, шаробдан ичарлар.",588,30],["خِتَ[n[ـٰ]مُهُ[n[ۥ] مِسْ[a:14382[كٌ‌ۚ و]َفِى ذ[n[َٲ]لِكَ فَلْيَتَنَافَسِ [h:14383[ٱ]لْمُتَنَ[n[ـٰ]فِس[p[ُو]نَ","Унинг хотимаси мискдир. Ва шу нарса учун мусобақа қилувчилар мусобақа қилсинлар.",588,30],["وَمِزَاجُهُ[n[ۥ] مِ[f:14384[ن ت]َسْن[p[ِي]مٍ","Унинг аралашмаси «тасним»дандир.",588,30],["عَيْ[a:14166[نًا ي]َشْرَبُ بِهَا [h:14385[ٱ]لْمُقَرَّب[p[ُو]نَ","У бир булоқдирки, ундан муқарраблар ичарлар.",588,30],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ أَ[q:4390[جْ]رَمُو[s[اْ] كَانُو[s[اْ] مِنَ [h:523[ٱ]لَّذِينَ ءَامَنُو[s[اْ] يَضْحَك[p[ُو]نَ","Албатта жиноят қилганлар иймон келтирганлар устидан кулар эдилар.",588,30],["وَإِذَا مَرُّو[s[اْ] بِهِمْ يَتَغَامَز[p[ُو]نَ","Агар уллар аларнинг ёнидан ўтсалар, масхаралаб, ишоралар қила эдилар.",588,30],["وَإِذَا [h:14386[ٱ][f:6732[نق]َلَب[o[ُوٓ][s[اْ] إِلَ[o[ىٰٓ] أَهْلِهِمُ [h:14387[ٱ][f:6732[نق]َلَبُو[s[اْ] فَكِه[p[ِي]نَ","Агар улар ўз аҳллари ҳузурига қайтиб борсалар, ҳузурланиб қайтиб борар эдилар.",588,30],["وَإِذَا رَأَوْهُمْ قَال[o[ُوٓ][s[اْ] إِ[g[نّ]َ هَ[o[ـٰٓ]ؤُل[o[َا]ٓءِ لَض[m[َا]ٓلّ[p[ُو]نَ","Ва агар уларни кўрсалар, «албатта ановилар адашганлар», дер эдилар.",588,30],["وَم[o[َآ] أُرْسِلُو[s[اْ] عَلَيْهِمْ حَ[n[ـٰ]فِظ[p[ِي]نَ","Ҳолбуки, улар алар устидан кузатувчи қилиб юборилган эмаслар!",588,30],["فَ[h:9999[ٱ]لْيَوْمَ [h:14388[ٱ]لَّذِينَ ءَامَنُو[s[اْ] مِنَ [h:5912[ٱ]لْكُفَّارِ يَضْحَك[p[ُو]نَ","Энди, бу Кунда иймон келтирганлар кофирлар устидан куларлар.",588,30],["عَلَى [h:8058[ٱ]لْأَر[o[َا]ٓئِكِ يَ[f:1141[نظ]ُر[p[ُو]نَ","Пардали, баланд сўрилар устида назар солиб турарлар.",589,30],["هَلْ ثُوِّبَ [h:14389[ٱ]لْكُفَّارُ مَا كَانُو[s[اْ] يَفْعَل[p[ُو]نَ","Кофирлар қилган ишларининг «савобини» олар миканлар?!",589,30]]},{"n":84,"ar":"الانشِقَاقِ","en":"Al-Inshiqaaq","uz":"Иншиқоқ","type":"Макка","ayahs":[["إِذَا [h:14351[ٱ][l[ل]سَّم[o[َا]ٓءُ [h:14390[ٱ][f:14391[نش]َقَّتْ","Вақтики, осмон ёрилса.",589,30],["وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","Ва у ўз Роббисига қулоқ осди ва шундоқ бўлиши керак эди.",589,30],["وَإِذَا [h:14392[ٱ]لْأَرْضُ مُدَّتْ","Ва, вақтики, ер чўзилса.",589,30],["وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ","Ва ўз ичидаги нарсаларни отиб чиқариб, холи қолса.",589,30],["وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","Ва у ўз Роббисига қулоқ осди ва шундоқ бўлиши керак эди.",589,30],["يَ[o[ـٰٓ]أَيُّهَا [h:14358[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ إِ[g[نّ]َكَ كَادِحٌ إِلَىٰ رَبِّكَ كَ[q:14393[دْ][f:14394[حًا ف]َمُلَ[n[ـٰ]ق[p[ِي]هِ","Эй инсон! Албатта сен Роббингга йўлиққунингча, ҳаракату уринишда бўларсан ва охири унга йўлиқарсан.",589,30],["فَأَ[g[مّ]َا مَنْ أُوتِىَ كِتَ[n[ـٰ]بَهُ[n[ۥ] بِيَمِينِهِۦ","Аммо кимнинг китоби ўнг тарафдан берилса.",589,30],["فَسَوْفَ يُحَاسَبُ حِسَا[a:14395[بًا ي]َسِيرًا","Тезда, осонгина ҳисоб қилинар.",589,30],["وَيَ[f:14396[نق]َلِبُ إِلَ[o[ىٰٓ] أَهْلِه[n[ِۦ] مَسْرُورًا","Ва аҳли ҳузурига хурсанд ҳолда қайтиб борар.",589,30],["وَأَ[g[مّ]َا مَنْ أُوتِىَ كِتَ[n[ـٰ]بَهُ[n[ۥ] وَر[o[َا]ٓءَ ظَهْرِهِۦ","Ва, аммо, кимнинг китоби орқа тарафдан берилса.",589,30],["فَسَوْفَ يَ[q:1242[دْ]عُو[s[اْ] ثُبُورًا","У тезда ўзига ҳалокатни чақирар.",589,30],["وَيَصْلَىٰ سَعِيرًا","Ва қизиб турган дўзахга кирар.",589,30],["إِ[g[نّ]َهُ[n[ۥ] كَانَ ف[o[ِىٓ] أَهْلِه[n[ِۦ] مَسْرُورًا","Чунки, у ўз аҳли билан хурсанд бўлиб ўтган эди.",589,30],["إِ[g[نّ]َهُ[n[ۥ] ظَ[g[نّ]َ أ[u:8842[َن ل]ّ[a:14397[َن ي]َح[p[ُو]رَ","Чунки, у ҳеч қачон орқага қайтмасликни ўйлаган эди.",589,30],["بَلَ[o[ىٰٓ] إِ[g[نّ]َ رَبَّهُ[n[ۥ] كَانَ بِه[n[ِۦ] بَصِيرًا","Ҳа! Албатта, Роббиси уни доим кўриб турувчи эди.",589,30],["فَل[o[َآ] أُ[q:13287[قْ]سِمُ بِ[h:14398[ٱ][l[ل]شَّفَ[q[ق]ِ","Шафақ билан қасамки.",589,30],["وَ[h:9999[ٱ]لَّيْلِ وَمَا وَسَ[q[ق]َ","Кечаси ва у ўраб олган нарсалар билан қасамки.",589,30],["وَ[h:9999[ٱ]لْقَمَرِ إِذَا [h:14399[ٱ]تَّسَ[q[ق]َ","Ва тўлин ой билан қасамки.",589,30],["لَتَرْكَبُ[g[نّ]َ طَبَقًا عَ[f:14400[ن ط]َبَ[q[ق]ٍ","Албатта, сизлар табақама-табақа минасизлар.",589,30],["فَمَا لَهُمْ لَا يُؤْمِن[p[ُو]نَ","Нима бўлган уларга, иймон келтирмаслар?!",589,30],["وَإِذَا قُرِئَ عَلَيْهِمُ [h:14401[ٱ]لْقُرْءَانُ لَا يَسْجُدُ[p[و]نَ ۩","Ва агар уларга Қуръон ўқилса, сажда қилмаслар?!",589,30],["بَلِ [h:10932[ٱ]لَّذِينَ كَفَرُو[s[اْ] يُكَذِّب[p[ُو]نَ","Балки кофирлар ёлғонга чиқарарлар.",589,30],["وَ[h:9999[ٱ]للَّهُ أَعْلَمُ بِمَا يُوع[p[ُو]نَ","Улар қалбларида нимани сақлаётганларини Аллоҳнинг Ўзи билар.",589,30],["فَبَشِّرْه[c:1811[ُم ب]ِعَذَابٍ أَل[p[ِي]مٍ","Уларга аламли азобнинг «башоратини» бер.",589,30],["إِلَّا [h:778[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَهُمْ أَ[q:2423[جْ]رٌ غَيْرُ مَمْن[p[ُو]نِۭ","Магар иймон келтирганларга ва яхши амаллар қилганларга, уларга миннатсиз, узлуксиз ажрлар бордир.",589,30]]},{"n":85,"ar":"البُرُوجِ","en":"Al-Burooj","uz":"Буруж","type":"Макка","ayahs":[["وَ[h:9999[ٱ][l[ل]سَّم[o[َا]ٓءِ ذَاتِ [h:14402[ٱ]لْبُر[p[ُو][q[ج]ِ","Буржлар эгаси бўлган осмон билан қасам.",590,30],["وَ[h:9999[ٱ]لْيَوْمِ [h:14403[ٱ]لْمَوْع[p[ُو][q[د]ِ","Ва ваъда қилинган кун билан қасам.",590,30],["وَشَاهِ[a:14404[دٍ و]َمَشْه[p[ُو][q[د]ٍ","Гувоҳлик берувчи ва гувоҳлик берилган билан қасам.",590,30],["قُتِلَ أَصْحَ[n[ـٰ]بُ [h:14405[ٱ]لْأُخْد[p[ُو][q[د]ِ","«Ухдуд» эгаларига лаънат бўлсин.",590,30],["ٱ[l[ل][g[نّ]َارِ ذَاتِ [h:14406[ٱ]لْوَق[p[ُو][q[د]ِ","У ёқилғиси кўп, қаттиқ исиган оловдир.",590,30],["إِذْ هُمْ عَلَيْهَا قُع[p[ُو][q[د]ٌ","Улар алар атрофида ўтирибдилар.",590,30],["وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِ[h:3560[ٱ]لْمُؤْمِنِينَ شُه[p[ُو][q[د]ٌ","Ва улар мўминларга қилаётган нарсаларига ўзлари ҳозирдирлар.",590,30],["وَمَا نَقَمُو[s[اْ] مِنْهُمْ إِلّ[o[َآ] أ[a:386[َن ي]ُؤْمِنُو[s[اْ] بِ[h:32[ٱ]للَّهِ [h:14407[ٱ]لْعَزِيزِ [h:7037[ٱ]لْحَم[p[ِي][q[د]ِ","Ва мўминлардан Азиз, Ҳамид Аллоҳга бўлган иймондан бошқа «айб» топа олмадилар.",590,30],["ٱلَّذِى لَهُ[n[ۥ] مُلْكُ [h:555[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ‌ۚ وَ[h:72[ٱ]للَّهُ عَلَىٰ كُلِّ ش[f:3903[َىْءٍ ش]َه[p[ِي][q[د]ٌ","У шундай зотки, осмонлару ернинг мулки Унга хосдир ва Аллоҳ ҳар бир нарсага Ўзи гувоҳдир.",590,30],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ فَتَنُو[s[اْ] [h:14408[ٱ]لْمُؤْمِنِينَ وَ[h:5718[ٱ]لْمُؤْمِنَ[n[ـٰ]تِ ثُ[g[مّ]َ لَمْ يَتُوبُو[s[اْ] فَلَهُمْ عَذَابُ جَهَ[g[نّ]َمَ وَلَهُمْ عَذَابُ [h:14409[ٱ]لْحَر[p[ِي][q[ق]ِ","Албатта, мўмин ва мўминаларни фитна қилиб, сўнгра тавба қилмаганларга, ана ўшаларга, жаҳаннам азоби ва куйдирувчи азоб бор.",590,30],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ لَهُمْ جَ[g[نّ]َ[n[ـٰ][f:1786[تٌ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ‌ۚ ذ[n[َٲ]لِكَ [h:3911[ٱ]لْفَوْزُ [h:14410[ٱ]لْكَب[p[ِي]رُ","Албатта, иймон келтирган ва солиҳ амал қилганларга, уларга, остидан анҳорлар оқиб турган жаннат бор. Бу эса ниҳоятда улкан ютуқдир.",590,30],["إِ[g[نّ]َ بَ[q:14411[طْ]شَ رَبِّكَ لَشَد[p[ِي][q[د]ٌ","Албатта, Роббингнинг чангали жуда ҳам шиддатлидир.",590,30],["إِ[g[نّ]َهُ[n[ۥ] هُوَ يُ[q:10320[بْ]دِئُ وَيُع[p[ِي][q[د]ُ","Албатта, У Ўзи бошлар ва қайтарар.",590,30],["وَهُوَ [h:6227[ٱ]لْغَفُورُ [h:14412[ٱ]لْوَد[p[ُو][q[د]ُ","Ва У мағфират қилувчи, муҳаббати зўр зотдир.",590,30],["ذُو [h:11807[ٱ]لْعَرْشِ [h:14413[ٱ]لْمَج[p[ِي][q[د]ُ","У Арш эгаси ҳамда қадри улуғ зотдир.",590,30],["فَعَّا[u:6506[لٌ ل]ِّمَا يُر[p[ِي][q[د]ُ","У нимани хоҳласа, қила олувчи зотдир.",590,30],["هَلْ أَتَ[n[ـٰ]كَ حَدِيثُ [h:14414[ٱ]لْجُن[p[ُو][q[د]ِ","Сенга аскарларнинг хабари келдими?",590,30],["فِرْعَوْنَ وَثَم[p[ُو][q[د]َ","Фиръавн ва Самуднинг.",590,30],["بَلِ [h:10932[ٱ]لَّذِينَ كَفَرُو[s[اْ] فِى تَكْذ[p[ِي][q[ب]ٍ","Балки кофирлар ёлғонга чиқаришдадир?",590,30],["وَ[h:9999[ٱ]للَّهُ م[a:12394[ِن و]َر[o[َا]ٓئِه[w:14415[ِم م]ُّح[p[ِي][q[ط]ُۢ","Ҳолбуки, Аллоҳ уларнинг ортидан иҳота қилиб турувчидир.",590,30],["بَلْ هُوَ قُرْءَا[a:14416[نٌ م]َّج[p[ِي][q[د]ٌ","Йўқ! У Қуръони мажиддур.",590,30],["فِى لَوْ[a:14417[حٍ م]َّحْف[p[ُو]ظِۭ","У Лавҳул- Маҳфуздадир.",590,30]]},{"n":86,"ar":"الطَّارِقِ","en":"At-Taariq","uz":"Ториқ","type":"Макка","ayahs":[["وَ[h:9999[ٱ][l[ل]سَّم[o[َا]ٓءِ وَ[h:14418[ٱ][l[ل]طَّارِ[q[ق]ِ","Осмон билан қасам ва ториқ билан қасам.",591,30],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا [h:14419[ٱ][l[ل]طَّارِ[q[ق]ُ","Ториқ нималигини сенга не билдирди?",591,30],["ٱ[l[ل][g[نّ]َ[q:14420[جْ]مُ [h:14421[ٱ][l[ل]ثَّاقِ[q[ب]ُ","У нур сочиб турувчи юлдуздир.",591,30],["إِ[f:8426[ن ك]ُلُّ نَفْ[u:14422[سٍ ل]َّ[g[مّ]َا عَلَيْهَا حَافِظٌ","Ҳеч бир жон йўқки, унинг ҳифз қилиб турувчиси бўлмаса.",591,30],["فَلْيَ[f:14313[نظ]ُرِ [h:14314[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ مِ[g[مّ]َ خُلِ[q[ق]َ","Инсон нимадан яралганига назар солсин.",591,30],["خُلِقَ م[a:840[ِن م]ّ[o[َا]ٓ[f:14423[ءٍ د]َافِ[q[ق]ٍ","У отилиб чиқувчи сувдан яратилгандир.",591,30],["يَخْرُجُ م[i:4612[ِنۢ ب]َيْنِ [h:14424[ٱ][l[ل]صُّلْبِ وَ[h:14425[ٱ][l[ل]تَّر[o[َا]ٓئِ[q[ب]ِ","У сулб ва тароиб орасидан чиқадир.",591,30],["إِ[g[نّ]َهُ[n[ۥ] عَلَىٰ رَ[q:14426[جْ]عِه[n[ِۦ] لَقَادِرٌ","Албатта У зот уни қайта тирилтиришга қодирдир.",591,30],["يَوْمَ تُ[q:14427[بْ]لَى [h:14428[ٱ][l[ل]سَّر[o[َا]ٓئِرُ","Сирлар фош бўладиган кундадир.",591,30],["فَمَا لَهُ[n[ۥ] مِ[f:5395[ن ق]ُوَّ[a:14429[ةٍ و]َلَا نَاصِرٍ","Бас, уда қувват ҳам, нусрат берувчи ҳам бўлмайдир.",591,30],["وَ[h:9999[ٱ][l[ل]سَّم[o[َا]ٓءِ ذَاتِ [h:14430[ٱ][l[ل]رَّ[q:14431[جْ]عِ","Қайтувчи соҳиби бўлган осмон билан қасам.",591,30],["وَ[h:9999[ٱ]لْأَرْضِ ذَاتِ [h:14432[ٱ][l[ل]صَّ[q:14433[دْ]عِ","Ёриб чиқувчи эгаси бўлган ер билан қасам.",591,30],["إِ[g[نّ]َهُ[n[ۥ] لَقَوْ[f:14434[لٌ ف]َصْلٌ","Албатта у ажратувчи сўздир.",591,30],["وَمَا هُوَ بِ[h:14435[ٱ]لْهَزْلِ","Ва у ҳазил эмасдир.",591,30],["إِ[g[نّ]َهُمْ يَكِيدُونَ كَيْدًا","Албатта улар ҳийла-найранг қиларлар.",591,30],["وَأَكِيدُ كَيْدًا","Ва Мен ҳам ҳийла қилурман.",591,30],["فَمَهِّلِ [h:14436[ٱ]لْكَ[n[ـٰ]فِرِينَ أَمْهِلْهُمْ رُوَيْدَۢا","Муҳлат бер кофирларга, уларга озгина муҳлат бер.",591,30]]},{"n":87,"ar":"الأَعۡلَىٰ","en":"Al-A'laa","uz":"Аъло","type":"Макка","ayahs":[["سَبِّحِ [h:14437[ٱ]سْمَ رَبِّكَ [h:14438[ٱ]لْأَعْلَى","Олий қадар бўлган Роббинг исмини поклаб ёд эт.",591,30],["ٱلَّذِى خَلَقَ فَسَوَّىٰ","У яратган ва мутаносиб қилган зотдир.",591,30],["وَ[h:9999[ٱ]لَّذِى قَدَّرَ فَهَدَىٰ","У ўлчовли қилган ва ҳидоятга бошлаган зотдир.",591,30],["وَ[h:9999[ٱ]لَّذ[o[ِىٓ] أَخْرَجَ [h:14439[ٱ]لْمَرْعَىٰ","У ўт-ўланни чиқарган зотдир.",591,30],["فَجَعَلَهُ[n[ۥ] غُث[o[َا]ٓءً أَحْوَىٰ","Бас, У уни қорайган хашак қилган зотдир.",591,30],["سَنُ[q:14440[قْ]رِئُكَ فَلَا تَ[f:14441[نس]َىٰٓ","Биз сенга қироат қилдирамиз, бас, эсдан чиқармайссан.",591,30],["إِلَّا مَا ش[o[َا]ٓءَ [h:78[ٱ]للَّهُ‌ۚ إِ[g[نّ]َهُ[n[ۥ] يَعْلَمُ [h:8891[ٱ]لْجَهْرَ وَمَا يَخْفَىٰ","Магар Аллоҳ хоҳлаганини. Албатта, У ошкорни ҳам, махфий нарсани ҳам биладир.",591,30],["وَنُيَسِّرُكَ لِلْيُسْرَىٰ","Ва сени осон йўлга муяссар қилармиз.",591,30],["فَذَكِّرْ إ[a:14442[ِن ن]َّفَعَتِ [h:14443[ٱ][l[ل]ذِّكْرَىٰ","Бас, агар эслатиш манфаат берса, эслатгин.",591,30],["سَيَذَّكَّرُ م[a:14444[َن ي]َخْشَىٰ","Албатта, қўрққан эсга оладир.",591,30],["وَيَتَجَ[g[نّ]َبُهَا [h:14445[ٱ]لْأَشْقَى","Ва бадбахт ундан четда бўладир.",591,30],["ٱلَّذِى يَصْلَى [h:14446[ٱ][l[ل][g[نّ]َارَ [h:14447[ٱ]لْكُ[q:8463[بْ]رَىٰ","У катта оловга кирадир.",591,30],["ثُ[g[مّ]َ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","Сўнгра унинг ичида ўлмай ҳам, тирилмай ҳам қоладир.",591,30],["قَ[q:298[دْ] أَفْلَحَ مَ[f:8555[ن ت]َزَكَّىٰ","Батаҳқиқ, ким пок бўлса, ютуқ топадир.",591,30],["وَذَكَرَ [h:14448[ٱ]سْمَ رَبِّه[n[ِۦ] فَصَلَّىٰ","Ва Роббиси исмини зикр қилса ва намоз ўқиса ҳамдир.",591,30],["بَلْ تُؤْثِرُونَ [h:14449[ٱ]لْحَيَ[s[و][n[ٲ]ةَ [h:446[ٱ][l[ل]دُّنْيَا","Лекин, сизлар дунё ҳаётини устун қўясизлар.",592,30],["وَ[h:9999[ٱ]لْأَخِرَةُ خَيْ[a:8546[رٌ و]َأَ[q:8540[بْ]قَىٰٓ","Ҳолбуки, охират яхшироқ ва боқийроқдир.",592,30],["إِ[g[نّ]َ هَ[n[ـٰ]ذَا لَفِى [h:14450[ٱ][l[ل]صُّحُفِ [h:8657[ٱ]لْأُولَىٰ","Албатта, бу аввалги саҳифаларда бордир.",592,30],["صُحُفِ إِ[q:1860[بْ]ر[n[َٲ]هِيمَ وَمُوسَىٰ","Иброҳим ва Мусо саҳифаларидадир.",592,30]]},{"n":88,"ar":"الغَاشِيَةِ","en":"Al-Ghaashiya","uz":"Ғошия","type":"Макка","ayahs":[["هَلْ أَتَ[n[ـٰ]كَ حَدِيثُ [h:14451[ٱ]لْغَ[n[ـٰ]شِيَةِ","Батаҳқиқ сенга ғошия хабари келди.",592,30],["وُجُو[a:14135[هٌ ي]َوْمَئِذٍ خَ[n[ـٰ]شِعَةٌ","Ўшал кунда бир чеҳралар қўрқувчидир.",592,30],["عَامِلَ[a:14452[ةٌ ن]َّاصِبَةٌ","Улар амал қилуви ва чарчавчидир.",592,30],["تَصْلَىٰ نَارًا حَامِيَةً","Улар ўта қизиган оловга кирарлар.",592,30],["تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍ","Улар қайнаб турган булоқдан суғориларлар.",592,30],["لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِ[f:14453[ن ض]َر[p[ِي]عٍ","Уларга тикандан бошқа таом йўқ.",592,30],["لَّا يُسْمِنُ وَلَا يُغْنِى مِ[f:14454[ن ج][p[ُو]عٍ","У на семиртирмас ва на очликни кетказмас.",592,30],["وُجُو[a:14135[هٌ ي]َوْمَئِ[a:14455[ذٍ ن]َّاعِمَةٌ","Ўшал кунда бир чеҳралар неъматланувчидир.",592,30],["لِّسَعْيِهَا رَاضِيَةٌ","Улар ўз ишларидан розидир.",592,30],["فِى جَ[g[نّ]َةٍ عَالِيَةٍ","Улар олий жаннатдадир.",592,30],["لَّا تَسْمَعُ فِيهَا لَ[n[ـٰ]غِيَةً","Унда улар бекорчи гапни эшитмасдир.",592,30],["فِيهَا عَيْ[f:14456[نٌ ج]َارِيَةٌ","Унда оқиб турган булоқлар бор.",592,30],["فِيهَا سُرُ[a:14457[رٌ م]َّرْفُوعَةٌ","Унда баланд-баланд сўрилар бор.",592,30],["وَأَكْوَا[a:14458[بٌ م]َّوْضُوعَةٌ","Ва тайёрлаб қўйилган қадаҳлар бор.",592,30],["وَنَمَارِقُ مَصْفُوفَةٌ","Ва саф-саф тизилган ёстиқлар бор.",592,30],["وَزَرَابِىُّ مَ[q:14459[بْ]ثُوثَةٌ","Ҳамма ёққа тўшалган гиламлар бор.",592,30],["أَفَلَا يَ[f:1141[نظ]ُرُونَ إِلَى [h:14460[ٱ]لْإِبِلِ كَيْفَ خُلِقَتْ","Улар назар солмасларми; Туянинг қандай яратилганига?",592,30],["وَإِلَى [h:14461[ٱ][l[ل]سَّم[o[َا]ٓءِ كَيْفَ رُفِعَتْ","Ва осмонни қандоқ кўтарилганига?",592,30],["وَإِلَى [h:14462[ٱ]لْجِبَالِ كَيْفَ نُصِبَتْ","Ва тоғларнинг қандоқ ўрнаштирилганига?",592,30],["وَإِلَى [h:14463[ٱ]لْأَرْضِ كَيْفَ سُطِحَتْ","Ва ерни қандоқ текислаб қўйилганига?",592,30],["فَذَكِّرْ إِ[g[نّ]َم[o[َآ] أَ[f:169[نت]َ مُذَكِّرٌ","Бас, эслатгин, сен, албатта, эслатувчидирсан.",592,30],["لَّسْتَ عَلَيْه[c:14464[ِم ب]ِمُصَيْطِرٍ","Сен улар устидан ҳукмингни ўтказувчи эмассан.",592,30],["إِلَّا مَ[f:12995[ن ت]َوَلَّىٰ وَكَفَرَ","Лекин, ким юз ўгирса ва кофир бўлса.",592,30],["فَيُعَذِّبُهُ [h:14465[ٱ]للَّهُ [h:14466[ٱ]لْعَذَابَ [h:14467[ٱ]لْأَكْبَرَ","Бас, уни Аллоҳ катта азоб билан азоблайдир.",592,30],["إِ[g[نّ]َ إِلَيْن[o[َآ] إِيَابَهُمْ","Албатта уларнинг қайтиши Бизгадир.",592,30],["ثُ[g[مّ]َ إِ[g[نّ]َ عَلَيْنَا حِسَابَهُم","Сўнгра, албатта, уларнинг ҳисоб-китоби ҳам Биздадир.",592,30]]},{"n":89,"ar":"الفَجۡرِ","en":"Al-Fajr","uz":"Фажр","type":"Макка","ayahs":[["وَ[h:9999[ٱ]لْفَ[q:14468[جْ]رِ","Фажр билан қасам.",593,30],["وَلَيَالٍ عَشْرٍ","Ва ўн кеча билан қасам.",593,30],["وَ[h:9999[ٱ][l[ل]شَّفْعِ وَ[h:14469[ٱ]لْوَتْرِ","Жуфту тоқ билан қасам.",593,30],["وَ[h:9999[ٱ]لَّيْلِ إِذَا يَسْرِ","Ва юрилган тун билан қасам.",593,30],["هَلْ فِى ذ[n[َٲ]لِكَ قَسَ[u:14470[مٌ ل]ِّذِى حِ[q:14471[جْ]رٍ","Мана шуларда ақл эгаси учун қасам бордир?!",593,30],["أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِع[p[َا][q[د]ٍ","Сен Роббинг Одга қандай қилганинни билмадингми?",593,30],["إِرَمَ ذَاتِ [h:14472[ٱ]لْعِم[p[َا][q[د]ِ","Баланд устунли «Ирам»га.",593,30],["ٱلَّتِى لَمْ يُخْلَ[q:14473[قْ] مِثْلُهَا فِى [h:2519[ٱ]لْبِلَ[p[ـٰ][q[د]ِ","Унинг мисли бошқа диёрларда халқ қилинмаганга.",593,30],["وَثَمُودَ [h:14474[ٱ]لَّذِينَ جَابُو[s[اْ] [h:14475[ٱ][l[ل]صَّخْرَ بِ[h:8451[ٱ]لْو[p[َا][q[د]ِ","Ва водийда харсанг тошларни кесган Самудга.",593,30],["وَفِرْعَوْنَ ذِى [h:14476[ٱ]لْأَوْت[p[َا][q[د]ِ","Ва кўп аскарлари бор Фиръавнга.",593,30],["ٱلَّذِينَ طَغَوْ[s[اْ] فِى [h:2519[ٱ]لْبِلَ[p[ـٰ][q[د]ِ","Улар турли ўлкаларда туғёнга кетган эдилар.",593,30],["فَأَكْثَرُو[s[اْ] فِيهَا [h:14477[ٱ]لْفَس[p[َا][q[د]َ","Улар уларда бузғунчиликни кўпайтирдилар.",593,30],["فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذ[p[َا][q[ب]ٍ","Бас, Роббинг уларнинг бошига турли азобларни қуйди.",593,30],["إِ[g[نّ]َ رَبَّكَ لَبِ[h:14478[ٱ]لْمِرْص[p[َا][q[د]ِ","Албатта, Роббинг кузатиб турувчидир.",593,30],["فَأَ[g[مّ]َا [h:14479[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ إِذَا مَا [h:14480[ٱ][q:14481[بْ]تَلَ[n[ـٰ]هُ رَبُّهُ[n[ۥ] فَأَكْرَمَهُ[n[ۥ] وَنَعَّمَهُ[n[ۥ] فَيَقُولُ رَبّ[o[ِىٓ] أَكْرَمَنِ","Бас, қачон инсонни Роббиси синаш учун икром қилса ва неъмат берса: «Мени Роббим икром қилди», дейдир.",593,30],["وَأَ[g[مّ][o[َآ] إِذَا مَا [h:14480[ٱ][q:14481[بْ]تَلَ[n[ـٰ]هُ فَقَدَرَ عَلَيْهِ رِزْقَهُ[n[ۥ] فَيَقُولُ رَبّ[o[ِىٓ] أَهَ[n[ـٰ]نَنِ","Бас, қачон Роббиси синаш учун ризқини тор қилиб қўйса: «Роббим мени хорлади», дейдир.",593,30],["كَلَّا‌ۖ بَل لَّا تُكْرِمُونَ [h:14482[ٱ]لْيَت[p[ِي]مَ","Йўқ! Балки Сизлар етимларни икром қилмассизлар.",593,30],["وَلَا تَحَ[m[ـٰٓ]ضُّونَ عَلَىٰ طَعَامِ [h:13901[ٱ]لْمِسْك[p[ِي]نِ","Бир-бирингизни мискинларга таом беришга ундамассизлар.",593,30],["وَتَأْكُلُونَ [h:14483[ٱ][l[ل]تُّرَاثَ أَكْل[u:14484[اً ل]َّ[g[مّ]ًا","Ва меросни шиддатла ейсизлар.",593,30],["وَتُحِبُّونَ [h:14485[ٱ]لْمَالَ حُب[f:14486[ًّا ج]َ[g[مّ]ًا","Ва молни кўп яхши кўрасизлар.",593,30],["كَلّ[o[َآ] إِذَا دُكَّتِ [h:14487[ٱ]لْأَرْضُ دَك[f:14488[ًّا د]َكًّا","Йўқ! Вақтики, ер зилзилага тушиб парча-парча бўлиб кетса.",593,30],["وَج[o[َا]ٓءَ رَبُّكَ وَ[h:14489[ٱ]لْمَلَكُ صَف[f:14490[ًّا ص]َفًّا","Ва Роббинг ва фаришталар саф-саф бўлиб келса.",593,30],["وَجِ[s[اْ][o[ىٓ]ءَ يَوْمَئِ[i:14491[ذِۭ ب]ِجَهَ[g[نّ]َمَ‌ۚ يَوْمَئِ[a:14492[ذٍ ي]َتَذَكَّرُ [h:14286[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ وَأَ[g[نّ]َىٰ لَهُ [h:14493[ٱ][l[ل]ذِّكْرَىٰ","Ва ўша кунда жаҳаннамни келтирилса, ўша кунда инсон эслайдир. Лекин бу эслашдан энди не фойда?!",593,30],["يَقُولُ يَ[n[ـٰ]لَيْتَنِى قَدَّمْتُ لِحَيَاتِى","У, афсуски, ҳаётимга ҳам бирор нарса тақдим қилсам бўлар экан, дейдир.",594,30],["فَيَوْمَئِ[u:10538[ذٍ ل]َّا يُعَذِّبُ عَذَابَهُ[o[ۥٓ] أَحَ[q[د]ٌ","Бас, ўша кунда Аллоҳнинг азобига ўхшаш азобла ҳеч ким азобламас.",594,30],["وَلَا يُوثِقُ وَثَاقَهُ[o[ۥٓ] أَحَ[q[د]ٌ","Ва Унинг боғлашига ўхшаш ҳеч ким боғламас.",594,30],["يَ[o[ـٰٓ]أَيَّتُهَا [h:14494[ٱ][l[ل][g[نّ]َفْسُ [h:14495[ٱ]لْمُ[q:14496[طْ]مَئِ[g[نّ]َةُ","Эй хотиржам нафс!",594,30],["ٱرْجِع[o[ِىٓ] إِلَىٰ رَبِّكِ رَاضِيَ[a:14497[ةً م]َّرْضِيَّةً","Роббингга сен Ундан, У сендан рози бўлган ҳолингда қайт!",594,30],["فَ[h:9999[ٱ][q:14498[دْ]خُلِى فِى عِبَ[n[ـٰ]دِى","Бас, бандаларим ичига киргин!",594,30],["وَ[h:9999[ٱ][q:14499[دْ]خُلِى جَ[g[نّ]َتِى","Ва жаннатимга киргин!",594,30]]},{"n":90,"ar":"البَلَدِ","en":"Al-Balad","uz":"Балад","type":"Макка","ayahs":[["ل[o[َآ] أُ[q:13287[قْ]سِمُ بِهَ[n[ـٰ]ذَا [h:14500[ٱ]لْبَلَ[q[د]ِ","Мана шу шаҳар билан қасам.",594,30],["وَأَ[f:3893[نت]َ حِل[i:14501[ُّۢ ب]ِهَ[n[ـٰ]ذَا [h:14500[ٱ]لْبَلَ[q[د]ِ","Сен муқим турган бу шаҳарла.",594,30],["وَوَالِ[a:14502[دٍ و]َمَا وَلَ[q[د]َ","Ва волид ва ундан тарқаган валадлар билан қасам.",594,30],["لَقَ[q:2389[دْ] خَلَ[q:5159[قْ]نَا [h:7228[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ فِى كَبَ[q[د]ٍ","Батаҳқиқ, Биз инсонни машаққатда яратдик.",594,30],["أَيَحْسَبُ أ[u:8842[َن ل]ّ[a:14503[َن ي]َ[q:14504[قْ]دِرَ عَلَيْهِ أَحَ[q[د]ٌ","У инсон унга ҳеч кимнинг кучи етмайди, деб ҳисоблайдими?",594,30],["يَقُولُ أَهْلَكْتُ مَال[u:14505[اً ل]ُّبَدًا","У, кўплаб мол-дунё нафақа қилдим, дейдир.",594,30],["أَيَحْسَبُ أ[u:4423[َن ل]َّمْ يَرَهُ[o[ۥٓ] أَحَ[q[د]ٌ","У инсон уни биров кўрмади, деб ўйлайдими?",594,30],["أَلَمْ نَ[q:8219[جْ]عَل لَّهُ[n[ۥ] عَيْنَ[p[يْ]نِ","Биз унга икки кўзни бермадикми?",594,30],["وَلِسَا[a:14506[نًا و]َشَفَتَ[p[يْ]نِ","Ва тилни ва икки лабни",594,30],["وَهَدَيْنَ[n[ـٰ]هُ [h:14507[ٱ][l[ل][g[نّ]َ[q:14508[جْ]دَ[p[يْ]نِ","Ва Биз уни икки: йўлга йўллаб қўйдик.",594,30],["فَلَا [h:14509[ٱ][q:14510[قْ]تَحَمَ [h:14511[ٱ]لْعَقَبَةَ","Бас, у довон ошиб ўтмади.",594,30],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا [h:14512[ٱ]لْعَقَبَةُ","Довон қандоқ нарса эканини сенга нима билдирди?",594,30],["فَكُّ رَقَبَةٍ","У қул озод қилишдир.",594,30],["أَوْ إِ[q:14513[طْ]عَ[n[ـٰ][f:14514[مٌ ف]ِى يَوْ[f:14515[مٍ ذ]ِى مَسْغَبَةٍ","Ёки очарчилик кунида таом беришдир.",594,30],["يَتِي[f:14516[مًا ذ]َا مَ[q:14517[قْ]رَبَةٍ","Қариндош етимларга.",594,30],["أَوْ مِسْكِي[f:14518[نًا ذ]َا مَتْرَبَةٍ","Ёки тупроққа қориган мискинларга.",594,30],["ثُ[g[مّ]َ كَانَ مِنَ [h:523[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَتَوَاصَوْ[s[اْ] بِ[h:223[ٱ][l[ل]صَّ[q:223[بْ]رِ وَتَوَاصَوْ[s[اْ] بِ[h:14519[ٱ]لْمَرْحَمَةِ","Сўнгра иймон келтирганлар ва бир-бирини сабрга, меҳр-шафқатга чақирганлар бўлса.",594,30],["أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ أَصْحَ[n[ـٰ]بُ [h:13209[ٱ]لْمَيْمَنَةِ","Ана ўшалар ўнг томон эгаларидир.",594,30],["وَ[h:9999[ٱ]لَّذِينَ كَفَرُو[s[اْ] بِـَٔـايَ[n[ـٰ]تِنَا هُمْ أَصْحَ[n[ـٰ]بُ [h:13211[ٱ]لْمَشْــَٔمَةِ","Оятларимизга куфр келтирганлар, улар, чап томон эгаларидир.",594,30],["عَلَيْهِمْ نَا[a:14520[رٌ م]ُّؤْصَدَةُۢ","Уларни чиқиб бўлмайдиган ўт-олов ўраб олгандир.",594,30]]},{"n":91,"ar":"الشَّمۡسِ","en":"Ash-Shams","uz":"Шамс","type":"Макка","ayahs":[["وَ[h:9999[ٱ][l[ل]شَّمْسِ وَضُحَ[n[ـٰ]هَا","Қуёш билан ва унинг зиёси билан қасам.",595,30],["وَ[h:9999[ٱ]لْقَمَرِ إِذَا تَلَ[n[ـٰ]هَا","Унинг ортидан келадиган Ой билан қасам.",595,30],["وَ[h:9999[ٱ][l[ل][g[نّ]َهَارِ إِذَا جَلَّ[n[ـٰ]هَا","Ва уни равшан кўрсатган наҳор билан қасам.",595,30],["وَ[h:9999[ٱ]لَّيْلِ إِذَا يَغْشَ[n[ـٰ]هَا","Ва уни қоплаган тун билан қасам.",595,30],["وَ[h:9999[ٱ][l[ل]سَّم[o[َا]ٓءِ وَمَا بَنَ[n[ـٰ]هَا","Ва осмон билан ва унинг бино қилиниши билан қасам.",595,30],["وَ[h:9999[ٱ]لْأَرْضِ وَمَا طَحَ[n[ـٰ]هَا","Ва ер билан ва унинг тўшалиши билан қасам.",595,30],["وَنَفْ[a:14521[سٍ و]َمَا سَوَّ[n[ٮٰ]هَا","Ва нафс билан ва унинг бекам-кўст қилиб яратилиши билан қасам.",595,30],["فَأَلْهَمَهَا فُجُورَهَا وَتَ[q:14522[قْ]وَ[n[ٮٰ]هَا","Бас, уга фужурини ва тақвосини билдирди.",595,30],["قَ[q:298[دْ] أَفْلَحَ مَ[f:14523[ن ز]َكَّ[n[ـٰ]هَا","Батаҳқиқ, ким уни покласа, ютуққа эришади.",595,30],["وَقَ[q:387[دْ] خَابَ مَ[f:14524[ن د]َسَّ[n[ـٰ]هَا","Ва батаҳқиқ, ким уни кирласа, ноумид бўлади.",595,30],["كَذَّبَتْ ثَمُودُ بِطَغْوَ[n[ٮٰ]هَآ","Самуд қавми ўз туғёни ила ёлғонга чиқарди.",595,30],["إِذِ [h:14525[ٱ][i:14526[نۢب]َعَثَ أَشْقَ[n[ـٰ]هَا","Вақтики, энг бадбахт шахс шошилиб турди.",595,30],["فَقَالَ لَهُمْ رَسُولُ [h:3306[ٱ]للَّهِ نَاقَةَ [h:14527[ٱ]للَّهِ وَسُ[q:14528[قْ]يَ[n[ـٰ]هَا","Бас, уларга Аллоҳнинг Расули «Аллоҳнинг туясига ва унинг сувига тегманглар», деди.",595,30],["فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّه[c:14529[ُم ب]ِذَ[i:13779[نۢب]ِهِمْ فَسَوَّ[n[ٮٰ]هَا","Бас, уни ёлғончига чиқаришди ва ул сўйишди.",595,30],["وَلَا يَخَافُ عُ[q:14530[قْ]بَ[n[ـٰ]هَا","Ва У зот бу ишнинг оқибатидан қўрқмайди.",595,30]]},{"n":92,"ar":"اللَّيۡلِ","en":"Al-Lail","uz":"Лайл","type":"Макка","ayahs":[["وَ[h:9999[ٱ]لَّيْلِ إِذَا يَغْشَىٰ","Туннинг қоплаб келаётган пайти билан қасам.",595,30],["وَ[h:9999[ٱ][l[ل][g[نّ]َهَارِ إِذَا تَجَلَّىٰ","Наҳорнинг тажалли пайти билан қасам.",595,30],["وَمَا خَلَقَ [h:14531[ٱ][l[ل]ذَّكَرَ وَ[h:929[ٱ]لْأُ[f:929[نث]َىٰٓ","Эркак ва урғочининг яратилиши билан қасам.",595,30],["إِ[g[نّ]َ سَعْيَكُمْ لَشَتَّىٰ","Албатта, сизларнинг ишларингиз турличадур.",595,30],["فَأَ[g[مّ]َا مَنْ أَعْطَىٰ وَ[h:2036[ٱ]تَّقَىٰ","Аммо кимки берса ва тақво қилса.",595,30],["وَصَدَّقَ بِ[h:13002[ٱ]لْحُسْنَىٰ","Ва гўзални тасдиқ қилса.",595,30],["فَسَنُيَسِّرُهُ[n[ۥ] لِلْيُسْرَىٰ","Бас, Биз уни осонга муяссар қиламиз.",595,30],["وَأَ[g[مّ]َا م[i:14532[َنۢ ب]َخِلَ وَ[h:13634[ٱ]سْتَغْنَىٰ","Аммо кимки бахиллик ва истиғно қилса.",595,30],["وَكَذَّبَ بِ[h:13002[ٱ]لْحُسْنَىٰ","Ва гўзални ёлғонга чиқарса.",595,30],["فَسَنُيَسِّرُهُ[n[ۥ] لِلْعُسْرَىٰ","Бас, Биз уни қийинга муяссар қиламиз.",595,30],["وَمَا يُغْنِى عَنْهُ مَالُهُ[o[ۥٓ] إِذَا تَرَدَّىٰٓ","У қулаган вақтда унга мол-мулки фойда бермас.",595,30],["إِ[g[نّ]َ عَلَيْنَا لَلْهُدَىٰ","Албатта, ҳидоятга бошлаш Бизнинг зиммамиздадир.",595,30],["وَإِ[g[نّ]َ لَنَا لَلْأَخِرَةَ وَ[h:12987[ٱ]لْأُولَىٰ","Албатта, ҳам охират ва ҳам бу дунё Бизникидир.",595,30],["فَأَ[f:14533[نذ]َرْتُكُمْ نَا[f:14534[رًا ت]َلَظَّىٰ","Бас, Мен сизларни ўтдан огоҳлантирдим.",595,30],["لَا يَصْلَ[n[ـٰ]ه[o[َآ] إِلَّا [h:14535[ٱ]لْأَشْقَى","Уга бадбахтдан бошқа ҳеч ким кирмас.",596,30],["ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ","Ўша ёлғонга чиқарган ва юз ўгирган эди.",596,30],["وَسَيُجَ[g[نّ]َبُهَا [h:14536[ٱ]لْأَتْقَى","Ва албатта, ундан тақводор банда четда қолади.",596,30],["ٱلَّذِى يُؤْتِى مَالَهُ[n[ۥ] يَتَزَكَّىٰ","У бойлигини сарфлайди ва ўзини поклайди.",596,30],["وَمَا لِأَحَدٍ عِ[f:719[ند]َهُ[n[ۥ] م[a:7433[ِن ن]ِّعْمَ[f:14537[ةٍ ت]ُ[q:11814[جْ]زَىٰٓ","Унда бирор кишининг қайтарилиши лозим яхшилиги йўқ эди.",596,30],["إِلَّا [h:1610[ٱ][q:1130[بْ]تِغ[o[َا]ٓءَ وَ[q:1611[جْ]هِ رَبِّهِ [h:14538[ٱ]لْأَعْلَىٰ","Фақатгина олий мақом Роббисининг розилигини сўраб қилади.",596,30],["وَلَسَوْفَ يَرْضَىٰ","Ва у албатта тезда рози бўлади.",596,30]]},{"n":93,"ar":"الضُّحَىٰ","en":"Ad-Dhuhaa","uz":"Зуҳо","type":"Макка","ayahs":[["وَ[h:9999[ٱ][l[ل]ضُّحَىٰ","Чошгоҳ билан қасам.",596,30],["وَ[h:9999[ٱ]لَّيْلِ إِذَا سَجَىٰ","Сукунатга чўмган тун билан қасам.",596,30],["مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","Роббинг сени тарк қилмади ва ғазаб ҳам қилмади.",596,30],["وَلَلْأَخِرَةُ خَيْ[u:14539[رٌ ل]َّكَ مِنَ [h:14540[ٱ]لْأُولَىٰ","Ва, албатта, охират сен учун бу дунёдан яхшидир.",596,30],["وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ","Ва тезда Роббинг сенга ато қиладир ва сен рози бўлурсан.",596,30],["أَلَمْ يَجِ[q:14541[دْ]كَ يَتِي[f:14542[مًا ف]َـَٔـاوَىٰ","У сени етим топиб, жойлаб қўймадими?",596,30],["وَوَجَدَكَ ضَآل[f:14543[اًّ ف]َهَدَىٰ","Ва У сени ҳайрон топиб, ҳидоятга бошламадими?",596,30],["وَوَجَدَكَ ع[o[َا]ٓئِل[f:14544[اً ف]َأَغْنَىٰ","Ва У сени камбағал топиб, бой қилмадими?",596,30],["فَأَ[g[مّ]َا [h:14545[ٱ]لْيَتِيمَ فَلَا تَ[q:14546[قْ]هَرْ","Аммо етимга қаҳр қилма.",596,30],["وَأَ[g[مّ]َا [h:14547[ٱ][l[ل]سّ[o[َا]ٓئِلَ فَلَا تَنْهَرْ","Ва, аммо, «соил»га зажр қилма.",596,30],["وَأَ[g[مّ]َا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ","Ва, аммо, Роббингнинг берган неъмати ҳақида сўзла.",596,30]]},{"n":94,"ar":"الشَّرۡحِ","en":"Ash-Sharh","uz":"Шарҳ","type":"Макка","ayahs":[["أَلَمْ نَشْرَحْ لَكَ صَ[q:14548[دْ]رَكَ","Сенинг кўксингни кенг қилиб қўймадикми?",596,30],["وَوَضَعْنَا عَ[f:626[نك]َ وِزْرَكَ","Ва сенинг юкингни енгиллатмадикми?",596,30],["ٱلَّذ[o[ِىٓ] أَ[f:14549[نق]َضَ ظَهْرَكَ","У сенинг елкангни босиб турган эди.",596,30],["وَرَفَعْنَا لَكَ ذِكْرَكَ","Ва сенинг зикрингни юқори кўтардик.",596,30],["فَإِ[g[نّ]َ مَعَ [h:14550[ٱ]لْعُسْرِ يُسْرًا","Бас, албатта, бир қийинчилик билан осончилик бордир.",596,30],["إِ[g[نّ]َ مَعَ [h:14550[ٱ]لْعُسْرِ يُسْرًا","Албатта, бир қийинчилик билан осончилик бордир.",596,30],["فَإِذَا فَرَغْتَ فَ[h:14551[ٱ][f:14551[نص]َ[q:14551[بْ]","Фориғ бўлсанг, ибодатига урингин.",596,30],["وَإِلَىٰ رَبِّكَ فَ[h:14552[ٱ]رْغَ[q[ب]","Ва фақат Роббингга рағбат қил.",596,30]]},{"n":95,"ar":"التِّينِ","en":"At-Tin","uz":"Тийн","type":"Макка","ayahs":[["وَ[h:9999[ٱ][l[ل]تِّينِ وَ[h:14553[ٱ][l[ل]زَّيْت[p[ُو]نِ","Анжир билан қасам ва зайтун билан қасам.",597,30],["وَطُورِ سِين[p[ِي]نَ","Ва Тури Сийно билан қасам.",597,30],["وَهَ[n[ـٰ]ذَا [h:14554[ٱ]لْبَلَدِ [h:14555[ٱ]لْأَم[p[ِي]نِ","Ва мана бу, эминлик юрти билан қасам.",597,30],["لَقَ[q:2389[دْ] خَلَ[q:5159[قْ]نَا [h:7228[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ ف[o[ِىٓ] أَحْسَنِ تَ[q:14556[قْ]و[p[ِي]مٍ","Батаҳқиқ, Биз инсонни энг яхши суратда яратдик.",597,30],["ثُ[g[مّ]َ رَدَ[q:14557[دْ]نَ[n[ـٰ]هُ أَسْفَلَ سَ[n[ـٰ]فِل[p[ِي]نَ","Сўнгра уни асфала сафилинга қайтардик.",597,30],["إِلَّا [h:778[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ فَلَهُمْ أَ[q:2423[جْ]رٌ غَيْرُ مَمْن[p[ُو]نٍ","Магар иймон келтирганлар ва яхши амаллар қилганларга миннатсиз ва узлуксиз ажрлар бордир.",597,30],["فَمَا يُكَذِّبُكَ بَعْدُ بِ[h:14361[ٱ][l[ل]دّ[p[ِي]نِ","Бас, сени нима охиратни ёлғонга чиқаришга олиб келади?",597,30],["أَلَيْسَ [h:4087[ٱ]للَّهُ بِأَحْكَمِ [h:14558[ٱ]لْحَ[n[ـٰ]كِم[p[ِي]نَ","Аллоҳ ҳукм қилгувчиларнинг энг ҳикматлиси эмасми?!",597,30]]},{"n":96,"ar":"العَلَقِ","en":"Al-Alaq","uz":"Алақ","type":"Макка","ayahs":[["ٱ[q:7699[قْ]رَأْ بِ[h:13285[ٱ]سْمِ رَبِّكَ [h:14559[ٱ]لَّذِى خَلَ[q[ق]َ","Яратган Роббинг номи билан ўқи.",597,30],["خَلَقَ [h:7324[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ مِنْ عَلَ[q[ق]ٍ","У инсонни алақдан яратди.",597,30],["ٱ[q:7699[قْ]رَأْ وَرَبُّكَ [h:14560[ٱ]لْأَكْرَمُ","Ўқи! Ва Роббинг энг карамлидир!",597,30],["ٱلَّذِى عَلَّمَ بِ[h:14561[ٱ]لْقَلَمِ","У қалам билан илм ўргатгандир.",597,30],["عَلَّمَ [h:14562[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ مَا لَمْ يَعْلَمْ","У инсонга у билмаган нарсани ўргатди.",597,30],["كَلّ[o[َآ] إِ[g[نّ]َ [h:7137[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ لَيَ[q:14563[طْ]غَىٰٓ","Йўқ! Албатта инсон туғёнга кетадир.",597,30],["أ[u:14564[َن ر]َّءَاهُ [h:14565[ٱ]سْتَغْنَىٰٓ","Ўзини бой кўргани учун.",597,30],["إِ[g[نّ]َ إِلَىٰ رَبِّكَ [h:14566[ٱ][l[ل]رُّ[q:14567[جْ]عَىٰٓ","Албатта, қайтиб бориш Роббингадир.",597,30],["أَرَءَيْتَ [h:14568[ٱ]لَّذِى يَنْهَىٰ","Қайтарганни кўрдингми?!",597,30],["عَ[q:3317[بْ]دًا إِذَا صَلَّىٰٓ","Бандани намоз ўқиётганида?!",597,30],["أَرَءَيْتَ إِ[f:2594[ن ك]َانَ عَلَى [h:4019[ٱ]لْهُدَىٰٓ","Айт-чи, агар ўша ҳидоятда бўлса.",597,30],["أَوْ أَمَرَ بِ[h:14569[ٱ][l[ل]تَّ[q:14569[قْ]وَىٰٓ","Ёки тақвога амр қилса.",597,30],["أَرَءَيْتَ إِ[f:14570[ن ك]َذَّبَ وَتَوَلَّىٰٓ","Айт-чи, ўша ёлғонга чиқарса ва юз ўгирса.",597,30],["أَلَمْ يَعْل[c:14571[َم ب]ِأَ[g[نّ]َ [h:897[ٱ]للَّهَ يَرَىٰ","Албатта Аллоҳ уни кўришини билмасми?!",597,30],["كَلَّا لَئ[u:4195[ِن ل]َّمْ يَ[f:10891[نت]َهِ لَنَسْفَع[i:14572[َۢا ب]ِ[h:14573[ٱ][l[ل][g[نّ]َاصِيَةِ","Йўқ! Агар қайтмаса, пешонасидан шиддатла тутамиз.",597,30],["نَاصِيَ[f:14574[ةٍ ك]َ[n[ـٰ]ذِبَةٍ خَاطِئَةٍ","Ёлғончи, хатокор пешонасидан.",597,30],["فَلْيَ[q:14575[دْ]عُ نَادِيَهُۥ","Бас, ўз тўпини чақирсин.",597,30],["سَنَ[q:14576[دْ]عُ [h:14577[ٱ][l[ل]زَّبَانِيَةَ","Биз ҳам забонияларни чақирамиз.",597,30],["كَلَّا لَا تُطِعْهُ وَ[h:14578[ٱ]سْجُ[q:14578[دْ] وَ[h:14579[ٱ][q:14579[قْ]تَرِ[q[ب] ۩","Йўқ! Сен унга итоат қилма! Сажда қил ва қурбат ҳосил қил.",597,30]]},{"n":97,"ar":"القَدۡرِ","en":"Al-Qadr","uz":"Қадр","type":"Макка","ayahs":[["إِ[g[نّ][o[َآ] أَ[f:4236[نز]َلْنَ[n[ـٰ]هُ فِى لَيْلَةِ [h:14580[ٱ]لْقَ[q:14581[دْ]رِ","Албатта, Биз уни Лайлатул Қадр да туширдик.",598,30],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا لَيْلَةُ [h:14582[ٱ]لْقَ[q:14581[دْ]رِ","Лайлатул Қадр қандоқ нарса эканини сенга нима билдирди?",598,30],["لَيْلَةُ [h:14582[ٱ]لْقَ[q:14581[دْ]رِ خَيْ[a:1231[رٌ م]ِّنْ أَلْفِ شَهْرٍ","Лайлатул Қадр минг ойдин яхшироқдир.",598,30],["تَنَزَّلُ [h:14583[ٱ]لْمَلَ[o[ـٰٓ]ئِكَةُ وَ[h:13916[ٱ][l[ل]رُّوحُ فِيهَا بِإِذْنِ رَبِّه[w:14584[ِم م]ِّ[f:843[ن ك]ُلِّ أَمْرٍ","Унда фаришталар ва Руҳ Роббилари изни билан барча ишлар учун тушадир.",598,30],["سَلَ[n[ـٰ]مٌ هِىَ حَتَّىٰ مَ[q:14585[طْ]لَعِ [h:14586[ٱ]لْفَ[q:996[جْ]رِ","У то тонг отгунча салом бўлиб турадир.",598,30]]},{"n":98,"ar":"البَيِّنَةِ","en":"Al-Bayyina","uz":"Баййина","type":"Мадина","ayahs":[["لَمْ يَكُنِ [h:14587[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ وَ[h:10916[ٱ]لْمُشْرِكِينَ مُ[f:14588[نف]َكِّينَ حَتَّىٰ تَأْتِيَهُمُ [h:14589[ٱ]لْبَيِّنَةُ","Аҳли китоб ва мушриклардан бўлган куфр келтирганларга «баййина» келмагунча ажралмасдилар.",598,30],["رَسُو[a:14590[لٌ م]ِّنَ [h:321[ٱ]للَّهِ يَتْلُو[s[اْ] صُحُ[a:14591[فًا م]ُّطَهَّرَةً","У Аллоҳ тарафидан юборилган Расул бўлиб, покланган саҳифаларни тиловат қиладир.",598,30],["فِيهَا كُتُ[f:14592[بٌ ق]َيِّمَةٌ","Уларда ажойиб битиклар бордир.",598,30],["وَمَا تَفَرَّقَ [h:14593[ٱ]لَّذِينَ أُوتُو[s[اْ] [h:524[ٱ]لْكِتَ[n[ـٰ]بَ إِلَّا م[i:146[ِنۢ ب]َعْدِ مَا ج[o[َا]ٓءَتْهُمُ [h:14594[ٱ]لْبَيِّنَةُ","Китоб берилганлар уларга «баййина» келганидан сўнггина бўлиниб кетишди.",598,30],["وَم[o[َآ] أُمِر[o[ُوٓ][s[اْ] إِلَّا لِيَعْبُدُو[s[اْ] [h:14595[ٱ]للَّهَ مُخْلِصِينَ لَهُ [h:4649[ٱ][l[ل]دِّينَ حُنَف[o[َا]ٓءَ وَيُقِيمُو[s[اْ] [h:14596[ٱ][l[ل]صَّلَ[s[و][n[ٲ]ةَ وَيُؤْتُو[s[اْ] [h:14597[ٱ][l[ل]زَّكَ[s[و][n[ٲ]ةَ‌ۚ وَذ[n[َٲ]لِكَ دِينُ [h:14598[ٱ]لْقَيِّمَةِ","Ҳолбуки, улар фақат Аллоҳгагина ибодат қилишга, Унинг динигагина ихлос қилишга, бошқа динларга мойил бўлмасликка, намозни тўлиқ ўқишга, закот беришга буюрилган эдилар. Ана шу тўғри миллатнинг динидир.",598,30],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ كَفَرُو[s[اْ] مِنْ أَهْلِ [h:545[ٱ]لْكِتَ[n[ـٰ]بِ وَ[h:10916[ٱ]لْمُشْرِكِينَ فِى نَارِ جَهَ[g[نّ]َمَ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ‌ۚ] أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمْ شَرُّ [h:14599[ٱ]لْبَرِيَّةِ","Албатта, аҳли китоб ва мушриклардан бўлган куфр келтирганлар жаҳаннам ўтидадурлар, у ерда абадий қолурлар. Ана ўшалар халойиқнинг энг ёмонларидир.",598,30],["إِ[g[نّ]َ [h:24[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ أُ[s[وْ]لَ[o[ـٰٓ]ئِكَ هُمْ خَيْرُ [h:14600[ٱ]لْبَرِيَّةِ","Албатта, иймон келтирганлар ва солиҳ амалларни қилганлар, ана ўшалар, халойиқнинг энг яхшиларидир.",598,30],["جَز[o[َا]ٓؤُهُمْ عِ[f:264[ند]َ رَبِّهِمْ جَ[g[نّ]َ[n[ـٰ]تُ عَ[q:5720[دْ][f:8049[نٍ ت]َ[q:120[جْ]رِى مِ[f:121[ن ت]َحْتِهَا [h:122[ٱ]لْأَنْهَ[n[ـٰ]رُ خَ[n[ـٰ]لِدِينَ فِيه[o[َآ] أَبَ[u:3909[دًا‌ۖ ر]َّضِىَ [h:3910[ٱ]للَّهُ عَنْهُمْ وَرَضُو[s[اْ] عَنْهُ‌ۚ ذ[n[َٲ]لِكَ لِمَنْ خَشِىَ رَبَّهُۥ","Уларнинг мукофотлари Роббилари ҳузуридаги остидан анҳорлар оқиб турган жаннат «адн»дир. У ерда абадул абад қолажаклар. Аллоҳ улардан рози бўлди, улар ҳам У зотдан рози бўлдилар. Бу Роббисидан қўрққанлар учундир.",599,30]]},{"n":99,"ar":"الزَّلۡزَلَةِ","en":"Az-Zalzala","uz":"Залзала","type":"Мадина","ayahs":[["إِذَا زُلْزِلَتِ [h:14601[ٱ]لْأَرْضُ زِلْزَالَهَا","Вақтики, ер ўзига хос зилзилага тушса.",599,30],["وَأَخْرَجَتِ [h:14602[ٱ]لْأَرْضُ أَثْقَالَهَا","Ва ер ўз юкларини отиб чиқарса.",599,30],["وَقَالَ [h:14603[ٱ]لْإِ[f:2732[نس]َ[n[ـٰ]نُ مَا لَهَا","Ва инсон, унга нима бўлди?!, деса.",599,30],["يَوْمَئِ[f:14604[ذٍ ت]ُحَدِّثُ أَخْبَارَهَا","Ўша кунда у ўз хабарини айтадир.",599,30],["بِأَ[g[نّ]َ رَبَّكَ أَوْحَىٰ لَهَا","Сенинг Роббинг унга ваҳий юборганини.",599,30],["يَوْمَئِ[a:14605[ذٍ ي]َصْدُرُ [h:14606[ٱ][l[ل][g[نّ]َاسُ أَشْتَا[u:14607[تًا ل]ِّيُرَوْ[s[اْ] أَعْمَ[n[ـٰ]لَهُمْ","Ўша кунда одамлар гуруҳ-гуруҳ бўлиб, амалларини кўриш учун жойларидан қўзғаладир.",599,30],["فَم[a:8855[َن ي]َعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْ[a:14608[رًا ي]َرَهُۥ","Бас, ким зарра оғирлигида яхшилик қилса ҳам кўрадир.",599,30],["وَم[a:3112[َن ي]َعْمَلْ مِثْقَالَ ذَرَّ[f:14609[ةٍ ش]َر[a:14610[ًّا ي]َرَهُۥ","Ва ким зарра оғирлигида ёмонлик қилса ҳам кўрадир.",599,30]]},{"n":100,"ar":"العَادِيَاتِ","en":"Al-Aadiyaat","uz":"Одиёт","type":"Макка","ayahs":[["وَ[h:9999[ٱ]لْعَ[n[ـٰ]دِيَ[n[ـٰ]تِ ضَ[q:14611[بْ]حًا","Ҳарсиллаб чопувчиотлар билан қасам.",599,30],["فَ[h:9999[ٱ]لْمُورِيَ[n[ـٰ]تِ قَ[q:14612[دْ]حًا","Ўт чақнатиб чопувчи отлар билан қасам.",599,30],["فَ[h:9999[ٱ]لْمُغِير[n[َٲ]تِ صُ[q:14613[بْ]حًا","Тонг чоғида ғорат қилувчи отлар билан қасам.",599,30],["فَأَثَرْنَ بِه[n[ِۦ] نَ[q:14614[قْ]عًا","Ўша пайтда чанг қўзғотдилар.",599,30],["فَوَسَ[q:14615[طْ]نَ بِه[n[ِۦ] جَمْعًا","Ва у ила жамоа ўртасига кирдилар.",599,30],["إِ[g[نّ]َ [h:7137[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ لِرَبِّه[n[ِۦ] لَكَن[p[ُو][q[د]ٌ","Албатта, инсон ўз Роббисига ношукрдир.",599,30],["وَإِ[g[نّ]َهُ[n[ۥ] عَلَىٰ ذ[n[َٲ]لِكَ لَشَه[p[ِي][q[د]ٌ","Ва албатта, у ана шунга ўзи гувоҳдир.",599,30],["وَإِ[g[نّ]َهُ[n[ۥ] لِحُبِّ [h:14616[ٱ]لْخَيْرِ لَشَد[p[ِي][q[د]ٌ","Албатта, у мол-дунёга ҳаддан ташқари ўчдир.",599,30],["۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى [h:8926[ٱ]لْقُب[p[ُو]رِ","У билмасми?! Қабрдагилар қўзғатилганда.",599,30],["وَحُصِّلَ مَا فِى [h:6095[ٱ][l[ل]صُّد[p[ُو]رِ","Ва кўкракларидаги ошкор бўлганда.",600,30],["إِ[g[نّ]َ رَبَّه[c:14617[ُم ب]ِهِمْ يَوْمَئِ[u:14618[ذٍ ل]َّخَب[p[ِي]رُۢ","Ўша кунда Роббилари улардан, хабардор эканини?!",600,30]]},{"n":101,"ar":"القَارِعَةِ","en":"Al-Qaari'a","uz":"Қориа","type":"Макка","ayahs":[["ٱلْقَارِعَةُ","Ал-Қориъату.",600,30],["مَا [h:14619[ٱ]لْقَارِعَةُ","Қориъату нима?",600,30],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا [h:14619[ٱ]لْقَارِعَةُ","Қориъат қандоқ нарса эканлигини сенга нима билдирди?",600,30],["يَوْمَ يَكُونُ [h:14620[ٱ][l[ل][g[نّ]َاسُ كَ[h:14621[ٱ]لْفَرَاشِ [h:14622[ٱ]لْمَ[q:14623[بْ]ث[p[ُو]ثِ","У кунда одамлар тўзиб кетган капалакка ўхшаб қоларлар.",600,30],["وَتَكُونُ [h:13919[ٱ]لْجِبَالُ كَ[h:13920[ٱ]لْعِهْنِ [h:14624[ٱ]لْمَ[f:14625[نف][p[ُو]شِ","Ва тоғлар титилган жунга ўхшаб қолар.",600,30],["فَأَ[g[مّ]َا مَ[f:14626[ن ث]َقُلَتْ مَو[n[َٲ]زِينُهُۥ","Кимнинг торозуси оғир келса...",600,30],["فَهُوَ فِى عِيشَ[u:13890[ةٍ ر]َّاضِيَةٍ","Бас, у розилик ҳаётидадир.",600,30],["وَأَ[g[مّ]َا مَنْ خَفَّتْ مَو[n[َٲ]زِينُهُۥ","Ва аммо кимнинг тарозуси енгил келса...",600,30],["فَأُ[g[مّ]ُهُ[n[ۥ] هَاوِيَةٌ","Бас, унинг онаси дўзахдир.",600,30],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا هِيَهْ","У қандоқ нарса эканлигини сенга нима билдирди?",600,30],["نَارٌ حَامِيَةُۢ","У қаттиқ қизиган ўтдир.",600,30]]},{"n":102,"ar":"التَّكَاثُرِ","en":"At-Takaathur","uz":"Такосур","type":"Макка","ayahs":[["أَلْهَ[n[ـٰ]كُمُ [h:14627[ٱ][l[ل]تَّكَاثُرُ","Кимники кўп сизни машғул қилди.",600,30],["حَتَّىٰ زُرْتُمُ [h:14628[ٱ]لْمَقَابِرَ","То қабрларни зиёрат қилгунингизча",600,30],["كَلَّا سَوْفَ تَعْلَم[p[ُو]نَ","Йўқ! Сизлар тезда биласизлар.",600,30],["ثُ[g[مّ]َ كَلَّا سَوْفَ تَعْلَم[p[ُو]نَ","Яна йўқ! Сизлар тезда биласизлар.",600,30],["كَلَّا لَوْ تَعْلَمُونَ عِلْمَ [h:14629[ٱ]لْيَق[p[ِي]نِ","Йўқ! Агар сизлар аниқ илм ила билганингизда эди.",600,30],["لَتَرَوُ[g[نّ]َ [h:14630[ٱ]لْجَح[p[ِي]مَ","Албатта, жаҳаннамни кўрасизлар.",600,30],["ثُ[g[مّ]َ لَتَرَوُ[g[نّ]َهَا عَيْنَ [h:14631[ٱ]لْيَق[p[ِي]نِ","Ва яна, албатта, уни ишонч кўзи билан кўрасизлар.",600,30],["ثُ[g[مّ]َ لَتُسْــَٔلُ[g[نّ]َ يَوْمَئِذٍ عَنِ [h:14632[ٱ][l[ل][g[نّ]َع[p[ِي]مِ","Сўнгра ўша кунда, албатта, берилган неъматлардан сўраласизлар.",600,30]]},{"n":103,"ar":"العَصۡرِ","en":"Al-Asr","uz":"Аср","type":"Макка","ayahs":[["وَ[h:9999[ٱ]لْعَصْرِ","Аср билан қасам.",601,30],["إِ[g[نّ]َ [h:7137[ٱ]لْإِ[f:5969[نس]َ[n[ـٰ]نَ لَفِى خُسْرٍ","Албатта, инсон хусрондадир.",601,30],["إِلَّا [h:778[ٱ]لَّذِينَ ءَامَنُو[s[اْ] وَعَمِلُو[s[اْ] [h:118[ٱ][l[ل]صَّ[n[ـٰ]لِحَ[n[ـٰ]تِ وَتَوَاصَوْ[s[اْ] بِ[h:370[ٱ]لْحَقِّ وَتَوَاصَوْ[s[اْ] بِ[h:223[ٱ][l[ل]صَّ[q:223[بْ]رِ","Магар иймон келтирганлар ва солиҳ амаллар қилганлар, бир-бирларини ҳақга чақирганлар ва бир-бирларини сабрга чақирганлар мустаснодир.",601,30]]},{"n":104,"ar":"الهُمَزَةِ","en":"Al-Humaza","uz":"Ҳумаза","type":"Макка","ayahs":[["وَيْ[u:12392[لٌ ل]ِّكُلِّ هُمَزَ[u:14633[ةٍ ل]ُّمَزَةٍ","Ҳар бир обрў тўкувчи ва айбловчига «вайл» бўлсин.",601,30],["ٱلَّذِى جَمَعَ مَال[a:14634[اً و]َعَدَّدَهُۥ","У мол жамлади ва уни санаб турди.",601,30],["يَحْسَبُ أَ[g[نّ]َ مَالَهُ[o[ۥٓ] أَخْلَدَهُۥ","У, албатта, уни абадий қолдирур, деб ҳисоблар.",601,30],["كَلَّا‌ۖ لَيُ[i:14635[نۢب]َذَ[g[نّ]َ فِى [h:14636[ٱ]لْحُطَمَةِ","Йўқ! Албатта у «ҳутома»га хор-зор этиб ташланар.",601,30],["وَم[o[َآ] أَ[q:13858[دْ]رَ[n[ٮٰ]كَ مَا [h:14637[ٱ]لْحُطَمَةُ","«Ҳутома» қандоқ нарса эканини сенга нима билдирар?",601,30],["نَارُ [h:14638[ٱ]للَّهِ [h:14639[ٱ]لْمُوقَدَةُ","У Аллоҳнинг шиддатли, ўчмас оловидир.",601,30],["ٱلَّتِى تَطَّلِعُ عَلَى [h:14640[ٱ]لْأَفْــِٔدَةِ","Қалбгача етиб борадир.",601,30],["إِ[g[نّ]َهَا عَلَيْه[w:14641[ِم م]ُّؤْصَدَةٌ","Албатта, у уларни устидан қоплангандир.",601,30],["فِى عَمَ[a:14642[دٍ م]ُّمَدَّدَةِۭ","Узун-узун устунларга боғлангандирлар.",601,30]]},{"n":105,"ar":"الفِيلِ","en":"Al-Fil","uz":"Фил","type":"Макка","ayahs":[["أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَ[n[ـٰ]بِ [h:14643[ٱ]لْف[p[ِي]لِ","Роббинг фил соҳибларини қандоқ қилганини билмадингми?",601,30],["أَلَمْ يَ[q:4397[جْ]عَلْ كَيْدَهُمْ فِى تَضْل[p[ِي]لٍ","Уларнинг макру ҳийласини зое кетказмадими?",601,30],["وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَاب[p[ِي]لَ","Ва уларнинг устига тўп-тўп қушларни юбормадими?",601,30],["تَرْمِيه[c:14644[ِم ب]ِحِجَارَ[a:14645[ةٍ م]ِّ[f:6445[ن س]ِجّ[p[ِي]لٍ","Лойдан пиширилган тошларни отадиганларни?",601,30],["فَجَعَلَهُمْ كَعَصْ[a:14646[فٍ م]َّأْك[p[ُو]لِۭ","Бас, уларни қурт еб ташлаган ўсимликка ўхшатиб юбормадими?. Муҳаммад алайҳиссалом «Фил йили»да туғилганлар дейилишининг сабаби ҳам шу.",601,30]]},{"n":106,"ar":"قُرَيۡشٍ","en":"Quraish","uz":"Қурайш","type":"Макка","ayahs":[["لِإِيلَ[n[ـٰ]فِ قُر[p[َي]ْشٍ","Қурайшнинг лозим тутиши қандай яхши!",602,30],["إ[n[ِۦ]لَ[n[ـٰ]فِهِمْ رِحْلَةَ [h:14647[ٱ][l[ل]شِّت[o[َا]ٓءِ وَ[h:14648[ٱ][l[ل]صّ[p[َي]ْفِ","Уларнинг қиш ва ёз сафарларини ўзларига лозим тутишлари қандай яхши!",602,30],["فَلْيَعْبُدُو[s[اْ] رَبَّ هَ[n[ـٰ]ذَا [h:14649[ٱ]لْب[p[َي]ْتِ","Бас, улар мана шу Байтнинг Роббисига ибодат қилсинлар!",602,30],["ٱلَّذ[o[ِىٓ] أَ[q:14650[طْ]عَمَه[w:14651[ُم م]ِّ[f:14454[ن ج]ُو[a:14652[عٍ و]َءَامَنَه[w:14653[ُم م]ِّنْ خ[p[َو]ْفِۭ","У зот уларини очликдан тўқ қилган, хавфдан омон қилгандир.",602,30]]},{"n":107,"ar":"المَاعُونِ","en":"Al-Maa'un","uz":"Моъун","type":"Макка","ayahs":[["أَرَءَيْتَ [h:14568[ٱ]لَّذِى يُكَذِّبُ بِ[h:14361[ٱ][l[ل]دّ[p[ِي]نِ","Жазо кунини ёлғонга чиқарувчини кўрдингми?",602,30],["فَذ[n[َٲ]لِكَ [h:14654[ٱ]لَّذِى يَدُعُّ [h:14655[ٱ]لْيَت[p[ِي]مَ","Ана ўша, етимни қўполлик билан ҳайдайдир.",602,30],["وَلَا يَحُضُّ عَلَىٰ طَعَامِ [h:13901[ٱ]لْمِسْك[p[ِي]نِ","Ва мискинларга таом беришга қизиқтирмайдир.",602,30],["فَوَيْ[u:14656[لٌ ل]ِّلْمُصَلّ[p[ِي]نَ","«Намозхонлар»га вайл бўлсин.",602,30],["ٱلَّذِينَ هُمْ عَ[f:14657[ن ص]َلَاتِهِمْ سَاه[p[ُو]نَ","Улар ўз намозларини унитувчилардир.",602,30],["ٱلَّذِينَ هُمْ يُر[o[َا]ٓء[p[ُو]نَ","Ана ўшалар риё қиладиганлардир.",602,30],["وَيَمْنَعُونَ [h:14658[ٱ]لْمَاع[p[ُو]نَ","Ва маоъунни ман қиладиганлардир.",602,30]]},{"n":108,"ar":"الكَوۡثَرِ","en":"Al-Kawthar","uz":"Кавсар","type":"Макка","ayahs":[["إِ[g[نّ][o[َآ] أَعْطَيْنَ[n[ـٰ]كَ [h:14659[ٱ]لْكَوْثَرَ","Албатта, Биз сенга Кавсарни бердик.",602,30],["فَصَلِّ لِرَبِّكَ وَ[h:14660[ٱ]نْحَرْ","Бас, Роббингга намоз ўқи ва жонлик сўй.",602,30],["إِ[g[نّ]َ شَانِئَكَ هُوَ [h:14661[ٱ]لْأَ[q:14662[بْ]تَرُ","Албатта, сени ёмон кўриб, айбловчининг орқаси кесикдир.",602,30]]},{"n":109,"ar":"الكَافِرُونَ","en":"Al-Kaafiroon","uz":"Кофирун","type":"Макка","ayahs":[["قُلْ يَ[o[ـٰٓ]أَيُّهَا [h:14663[ٱ]لْكَ[n[ـٰ]فِر[p[ُو]نَ","Айт: «Эй кофирлар!",603,30],["ل[o[َآ] أَعْبُدُ مَا تَعْبُد[p[ُو]نَ","Мен сиз ибодат қилган нарсаларга ибодат қилмасман.",603,30],["وَل[o[َآ] أَ[f:428[نت]ُمْ عَ[n[ـٰ]بِدُونَ م[o[َآ] أَعْبُ[q[د]ُ","Ва сизлар ҳам мен ибодат қиладиганга ибодат қилувчимассиз.",603,30],["وَل[o[َآ] أَنَا۟ عَابِ[a:14664[دٌ م]َّا عَبَ[d:14665[د]تُّمْ","Ва мен сиз ибодат қилган нарсага ибодат қилувчимасман.",603,30],["وَل[o[َآ] أَ[f:428[نت]ُمْ عَ[n[ـٰ]بِدُونَ م[o[َآ] أَعْبُ[q[د]ُ","Ва сиз ҳам мен ибодат қилганга ибодат қилувчимассиз.",603,30],["لَكُمْ دِينُكُمْ وَلِىَ د[p[ِي]نِ","Сизга ўз динингиз, менга ўз диним.",603,30]]},{"n":110,"ar":"النَّصۡرِ","en":"An-Nasr","uz":"Наср","type":"Мадина","ayahs":[["إِذَا ج[o[َا]ٓءَ نَصْرُ [h:1184[ٱ]للَّهِ وَ[h:14666[ٱ]لْفَتْحُ","Вақтики, Аллоҳнинг нусрати ва фатҳ келса...",603,30],["وَرَأَيْتَ [h:14667[ٱ][l[ل][g[نّ]َاسَ يَ[q:3156[دْ]خُلُونَ فِى دِينِ [h:2072[ٱ]للَّهِ أَفْوَاجًا","Ва одамларнинг Аллоҳнинг динига тўп-тўп бўлиб кираётганини кўрсанг...",603,30],["فَسَبِّحْ بِحَمْدِ رَبِّكَ وَ[h:14668[ٱ]سْتَغْفِرْهُ‌ۚ إِ[g[نّ]َهُ[n[ۥ] كَانَ تَوَّابَۢا","Бас, Роббингни поклаб ёд эт ва Унга истиғфор айт. Албатта, У тавбаларни кўплаб қабул этувчидир.",603,30]]},{"n":111,"ar":"المَسَدِ","en":"Al-Masad","uz":"Масад","type":"Макка","ayahs":[["تَبَّتْ يَد[o[َآ] أَبِى لَهَ[a:14669[بٍ و]َتَ[q[ب]َّ","Абу Лаҳабнинг икки қўли ҳалок бўлсин, ҳалок!",603,30],["م[o[َآ] أَغْنَىٰ عَنْهُ مَالُهُ[n[ۥ] وَمَا كَسَ[q[ب]َ","Унга моли ва касб қилган нарсалари фойда бермади.",603,30],["سَيَصْلَىٰ نَا[f:14670[رًا ذ]َاتَ لَهَ[q[ب]ٍ","У тезда чўғи қизиб турган ўтга киради.",603,30],["وَ[h:9999[ٱ]مْرَأَتُهُ[n[ۥ] حَ[g[مّ]َالَةَ [h:14671[ٱ]لْحَطَ[q[ب]ِ","Ва унинг хотини, ўтин кўтарган аёл ҳам.",603,30],["فِى جِيدِهَا حَ[q:14672[بْ][a:14673[لٌ م]ّ[a:14674[ِن م]َّسَ[q[د]ِۭ","Унинг бўйнида эшилган арқон бор ҳолда.",603,30]]},{"n":112,"ar":"الإِخۡلَاصِ","en":"Al-Ikhlaas","uz":"Ихлос","type":"Макка","ayahs":[["قُلْ هُوَ [h:8078[ٱ]للَّهُ أَحَ[q[د]ٌ","Айт: «У Аллоҳ ягонадир».",604,30],["ٱللَّهُ [h:14675[ٱ][l[ل]صَّمَ[q[د]ُ","Аллоҳ сомаддир.",604,30],["لَمْ يَلِ[q:14676[دْ] وَلَمْ يُولَ[q:14677[دْ]","У туғмаган ва туғилмаган.",604,30],["وَلَمْ يَك[u:2596[ُن ل]َّهُ[n[ۥ] كُفُوًا أَحَ[q[د]ُۢ","Ва Унга ҳеч ким тенг бўлмаган.",604,30]]},{"n":113,"ar":"الفَلَقِ","en":"Al-Falaq","uz":"Фалақ","type":"Макка","ayahs":[["قُلْ أَعُوذُ بِرَبِّ [h:14678[ٱ]لْفَلَ[q[ق]ِ","Тонг Роббисидан паноҳ сўрайман.",604,30],["مِ[f:14679[ن ش]َرِّ مَا خَلَ[q[ق]َ","У яратган нарсалар ёмонлигидан.",604,30],["وَمِ[f:14680[ن ش]َرِّ غَاسِقٍ إِذَا وَقَ[q[ب]َ","Ва кириб келган қоронғулик ёмонлигидан.",604,30],["وَمِ[f:14680[ن ش]َرِّ [h:14681[ٱ][l[ل][g[نّ]َفَّ[n[ـٰ]ثَ[n[ـٰ]تِ فِى [h:14682[ٱ]لْعُقَ[q[د]ِ","Ва тугунларга дам солувчилар ёмонлигидан.",604,30],["وَمِ[f:14680[ن ش]َرِّ حَاسِدٍ إِذَا حَسَ[q[د]َ","Ва ҳасад қилган ҳасадчининг ёмонлигидан, деб айт.",604,30]]},{"n":114,"ar":"النَّاسِ","en":"An-Naas","uz":"Нос","type":"Макка","ayahs":[["قُلْ أَعُوذُ بِرَبِّ [h:14683[ٱ][l[ل][g[نّ][p[َا]سِ","Одамлар Роббисидан.",604,30],["مَلِكِ [h:14684[ٱ][l[ل][g[نّ][p[َا]سِ","Одамлар Подшоҳидан.",604,30],["إِلَ[n[ـٰ]هِ [h:14685[ٱ][l[ل][g[نّ][p[َا]سِ","Одамлар Илоҳидан паноҳ сўрайман.",604,30],["مِ[f:14679[ن ش]َرِّ [h:14686[ٱ]لْوَسْوَاسِ [h:14687[ٱ]لْخَ[g[نّ][p[َا]سِ","Беркиниб, кўриниб турувчи васвоснинг.",604,30],["ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ [h:14688[ٱ][l[ل][g[نّ][p[َا]سِ","Одамлар қалбига васваса соладиганнинг.",604,30],["مِنَ [h:6531[ٱ]لْجِ[g[نّ]َةِ وَ[h:824[ٱ][l[ل][g[نّ][p[َا]سِ","Жинлардан ва одамлардан бўлганнинг ёмонлигидан, деб айт.",604,30]]}]};
